window.JOURNAL_DATA = {"updated_at": "2026-10-08T22:00:02+00:00", "journals": [{"code": "AER", "title": "American Economic Review", "issn": "0002-8282", "field": "\u7ecf\u6d4e\u5b66", "last_success": "2026-10-08T22:00:02+00:00", "error": null, "fetched": 100, "source_url": "https://api.crossref.org/journals/0002-8282/works"}, {"code": "ECTA", "title": "Econometrica", "issn": "0012-9682", "field": "\u7ecf\u6d4e\u5b66", "last_success": "2026-10-08T22:00:02+00:00", "error": null, "fetched": 100, "source_url": "https://api.crossref.org/journals/0012-9682/works"}, {"code": "JPE", "title": "Journal of Political Economy", "issn": "0022-3808", "field": "\u7ecf\u6d4e\u5b66", "last_success": "2026-10-08T22:00:02+00:00", "error": null, "fetched": 100, "source_url": "https://api.crossref.org/journals/0022-3808/works"}, {"code": "QJE", "title": "The Quarterly Journal of Economics", "issn": "0033-5533", "field": "\u7ecf\u6d4e\u5b66", "last_success": "2026-10-08T22:00:02+00:00", "error": null, "fetched": 100, "source_url": "https://api.crossref.org/journals/0033-5533/works"}, {"code": "REStud", "title": "The Review of Economic Studies", "issn": "0034-6527", "field": "\u7ecf\u6d4e\u5b66", "last_success": "2026-10-08T22:00:02+00:00", "error": null, "fetched": 100, "source_url": "https://api.crossref.org/journals/0034-6527/works"}, {"code": "JF", "title": "The Journal of Finance", "issn": "0022-1082", "field": "\u91d1\u878d\u5b66", "last_success": "2026-10-08T22:00:02+00:00", "error": null, "fetched": 100, "source_url": "https://api.crossref.org/journals/0022-1082/works"}, {"code": "RFS", "title": "The Review of Financial Studies", "issn": "0893-9454", "field": "\u91d1\u878d\u5b66", "last_success": "2026-10-08T22:00:02+00:00", "error": null, "fetched": 100, "source_url": "https://api.crossref.org/journals/0893-9454/works"}, {"code": "JFE", "title": "Journal of Financial Economics", "issn": "0304-405X", "field": "\u91d1\u878d\u5b66", "last_success": "2026-10-08T22:00:02+00:00", "error": null, "fetched": 100, "source_url": "https://api.crossref.org/journals/0304-405X/works"}, {"code": "JFQA", "title": "Journal of Financial and Quantitative Analysis", "issn": "0022-1090", "field": "\u91d1\u878d\u5b66", "last_success": "2026-10-08T22:00:02+00:00", "error": null, "fetched": 100, "source_url": "https://api.crossref.org/journals/0022-1090/works"}, {"code": "JPubE", "title": "Journal of Public Economics", "issn": "0047-2727", "field": "\u7ecf\u6d4e\u5b66", "last_success": "2026-10-08T22:00:02+00:00", "error": null, "fetched": 100, "source_url": "https://api.crossref.org/journals/0047-2727/works"}, {"code": "MS", "title": "Management Science", "issn": "0025-1909", "field": "\u7ba1\u7406\u5b66", "last_success": "2026-10-08T22:00:02+00:00", "error": null, "fetched": 100, "source_url": "https://api.crossref.org/journals/0025-1909/works"}, {"code": "NBER", "title": "NBER Working Papers", "issn": "", "field": "\u5de5\u4f5c\u8bba\u6587", "last_success": "2026-10-08T22:00:02+00:00", "error": null, "fetched": 45, "source_url": "https://www.nber.org/rss/new.xml"}], "articles": [{"doi": "10.1111/jofi.70084", "journal": "JF", "title": "The Financial Premium", "authors": ["JENS DICK\u2010NIELSEN", "PETER FELDH\u00dcTTER", "DAVID LANDO"], "author_details": [{"name": "JENS DICK\u2010NIELSEN", "affiliations": []}, {"name": "PETER FELDH\u00dcTTER", "affiliations": []}, {"name": "DAVID LANDO", "affiliations": []}], "abstract": "ABSTRACT We show that bonds issued by financial firms have higher spreads than bonds issued by industrial firms with the same rating and maturity, a difference that we refer to as the financial premium. Over the period 1987 to 2020, in the United States, this premium is 43 basis points on average, with the premium higher for lower ratings, higher during financial crises, and increasing in bond beta. We derive a model that explains the financial premium: banks hold diversified portfolios of nonfinancial debt, and bank debt therefore reflects more systematic risk than nonfinancial debt.", "date": "2026-10-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-08T22:00:02+00:00", "url": "https://doi.org/10.1111/jofi.70084", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u6781\u7aef\u98ce\u9669"], "title_zh": "\u91d1\u878d\u6ea2\u4ef7", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u91d1\u878d\u4f01\u4e1a\u53d1\u884c\u7684\u503a\u5238\u4e0e\u8bc4\u7ea7\u548c\u5230\u671f\u65e5\u76f8\u540c\u7684\u975e\u91d1\u878d\u4f01\u4e1a\u53d1\u884c\u7684\u503a\u5238\u76f8\u6bd4\uff0c\u5176\u5229\u5dee\u66f4\u9ad8\uff0c\u8fd9\u4e00\u5dee\u5f02\u6211\u4eec\u79f0\u4e4b\u4e3a\u91d1\u878d\u6ea2\u4ef7\u3002\u57281987\u5e74\u81f32020\u5e74\u671f\u95f4\uff0c\u7f8e\u56fd\u7684\u8fd9\u4e00\u6ea2\u4ef7\u5e73\u5747\u4e3a43\u4e2a\u57fa\u70b9\uff0c\u5bf9\u4e8e\u8f83\u4f4e\u8bc4\u7ea7\u7684\u503a\u5238\uff0c\u6ea2\u4ef7\u66f4\u9ad8\uff1b\u5728\u91d1\u878d\u5371\u673a\u671f\u95f4\u6ea2\u4ef7\u4e5f\u66f4\u9ad8\uff1b\u4e14\u968f\u7740\u503a\u5238\u7684\u7cfb\u7edf\u6027\u98ce\u9669\uff08beta\uff09\u589e\u52a0\u800c\u4e0a\u5347\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6a21\u578b\u6765\u89e3\u91ca\u8fd9\u4e00\u91d1\u878d\u6ea2\u4ef7\uff1a\u94f6\u884c\u6301\u6709\u975e\u91d1\u878d\u503a\u52a1\u7684\u591a\u6837\u5316\u6295\u8d44\u7ec4\u5408\uff0c\u56e0\u6b64\u94f6\u884c\u503a\u52a1\u6240\u53cd\u6620\u7684\u7cfb\u7edf\u6027\u98ce\u9669\u9ad8\u4e8e\u975e\u91d1\u878d\u503a\u52a1\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1111/jofi.70080", "journal": "JF", "title": "Feedback and Contagion through Distressed Competition", "authors": ["HUI CHEN", "WINSTON WEI DOU", "HONGYE GUO", "YAN JI"], "author_details": [{"name": "HUI CHEN", "affiliations": []}, {"name": "WINSTON WEI DOU", "affiliations": []}, {"name": "HONGYE GUO", "affiliations": []}, {"name": "YAN JI", "affiliations": []}], "abstract": "ABSTRACT Firms tend to compete more aggressively when facing financial distress. This intensified competition reduces profit margins, pushing them further into distress and adversely affecting their industry peers. To study such feedback and contagion effects, we incorporate strategic competition in a dynamic model with long\u2010term defaultable debt, exploring various peer interactions such as predation and price wars. The feedback effect represents a novel source of financial distress costs associated with leverage, which helps explain the negative profitability\u2010leverage relation across industries. Owing to the contagion effect, firms' optimal leverage is often excessively high from an industry perspective, undermining the industry's financial stability.", "date": "2026-10-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-08T22:00:02+00:00", "url": "https://doi.org/10.1111/jofi.70080", "topics": ["\u5e02\u573a\u53cd\u9988"], "title_zh": "\u53cd\u9988\u4e0e\u901a\u8fc7\u56f0\u5883\u7ade\u4e89\u7684\u4f20\u67d3", "abstract_zh": "\u6458\u8981 \u4f01\u4e1a\u9762\u4e34\u8d22\u52a1\u56f0\u5883\u65f6\u5f80\u5f80\u66f4\u52a0\u6fc0\u70c8\u5730\u7ade\u4e89\u3002\u8fd9\u79cd\u52a0\u5267\u7684\u7ade\u4e89\u4f1a\u964d\u4f4e\u5229\u6da6\u7a7a\u95f4\uff0c\u4f7f\u4f01\u4e1a\u8fdb\u4e00\u6b65\u9677\u5165\u56f0\u5883\uff0c\u5e76\u5bf9\u5176\u884c\u4e1a\u5185\u7684\u540c\u884c\u4ea7\u751f\u4e0d\u5229\u5f71\u54cd\u3002\u4e3a\u4e86\u7814\u7a76\u8fd9\u79cd\u53cd\u9988\u548c\u4f20\u67d3\u6548\u5e94\uff0c\u6211\u4eec\u5728\u4e00\u4e2a\u5305\u542b\u957f\u671f\u53ef\u8fdd\u7ea6\u503a\u52a1\u7684\u52a8\u6001\u6a21\u578b\u4e2d\u5f15\u5165\u4e86\u6218\u7565\u7ade\u4e89\uff0c\u8003\u5bdf\u4e86\u8bf8\u5982\u63a0\u593a\u548c\u4ef7\u683c\u6218\u7b49\u5404\u79cd\u540c\u884c\u4e92\u52a8\u3002\u53cd\u9988\u6548\u5e94\u4e3a\u6760\u6746\u5e26\u6765\u7684\u8d22\u52a1\u56f0\u5883\u6210\u672c\u63d0\u4f9b\u4e86\u4e00\u4e2a\u65b0\u7684\u6765\u6e90\uff0c\u6709\u52a9\u4e8e\u89e3\u91ca\u5404\u884c\u4e1a\u4e2d\u76c8\u5229\u80fd\u529b\u4e0e\u6760\u6746\u4e4b\u95f4\u7684\u8d1f\u76f8\u5173\u5173\u7cfb\u3002\u7531\u4e8e\u4f20\u67d3\u6548\u5e94\u7684\u5b58\u5728\uff0c\u4ece\u884c\u4e1a\u89d2\u5ea6\u770b\uff0c\u4f01\u4e1a\u7684\u6700\u4f18\u6760\u6746\u6c34\u5e73\u5f80\u5f80\u8fc7\u9ad8\uff0c\u635f\u5bb3\u4e86\u6574\u4e2a\u884c\u4e1a\u7684\u8d22\u52a1\u7a33\u5b9a\u6027\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2023.01108", "journal": "MS", "title": "Predicted Incrementality by Experimentation for Ad Measurement", "authors": ["Brett R. Gordon", "Robert Moakler", "Florian Zettelmeyer"], "author_details": [{"name": "Brett R. Gordon", "affiliations": ["Kellogg School of Management, Northwestern University, Evanston, Illinois 60208"]}, {"name": "Robert Moakler", "affiliations": ["Ads Research, Meta, Menlo Park, California 94025"]}, {"name": "Florian Zettelmeyer", "affiliations": ["Kellogg School of Management, Northwestern University, Evanston, Illinois 60208; and National Bureau of Economic Research, Cambridge, Massachusetts 02138"]}], "abstract": "Randomized controlled trials (RCTs) provide the most credible estimates of advertising incrementality but are difficult to scale. We propose Predicted Incrementality by Experimentation (PIE), which reframes ad measurement as a campaign-level prediction problem. PIE uses a sample of RCTs to learn a mapping from campaign features to causal effects, then applies it to campaigns not run as RCTs. Because the RCTs identify the causal effects, PIE can incorporate post-determined features\u2014campaign-level aggregates such as test-group outcomes, exposure rates, and last-click conversions, computed after campaign completion. These metrics reflect the consumer behaviors that generate treatment effects, so they carry predictive information about incrementality, even though they would be invalid controls in a causal model. Using 2,226 Meta ad experiments, PIE achieves an out-of-sample [Formula: see text] for incremental conversions per dollar, compared with [Formula: see text] for industry-standard seven-day last-click attribution. In a decision-making framework, PIE disagrees with RCT-based decisions in only 8%\u201312% of campaigns, compared with 12%\u201320% for last-click attribution. We conclude that PIE can help scale causal measurement from a limited number of RCTs to a large set of nonexperimental campaigns.", "date": "2026-10-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-08T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.01108", "topics": ["\u5176\u4ed6"], "title_zh": "\u901a\u8fc7\u5b9e\u9a8c\u9884\u6d4b\u5e7f\u544a\u589e\u91cf", "abstract_zh": "\u968f\u673a\u5bf9\u7167\u8bd5\u9a8c\uff08RCT\uff09\u63d0\u4f9b\u4e86\u6700\u53ef\u4fe1\u7684\u5e7f\u544a\u589e\u91cf\u6027\u4f30\u8ba1\uff0c\u4f46\u96be\u4ee5\u5927\u89c4\u6a21\u63a8\u5e7f\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u901a\u8fc7\u5b9e\u9a8c\u9884\u6d4b\u5e7f\u544a\u589e\u91cf\uff08PIE\uff09\uff0c\u5c06\u5e7f\u544a\u6d4b\u91cf\u91cd\u65b0\u5b9a\u4e49\u4e3a\u4e00\u4e2a\u9762\u5411\u6d3b\u52a8\u7ea7\u522b\u7684\u9884\u6d4b\u95ee\u9898\u3002PIE\u5229\u7528\u4e00\u7ec4RCT\u6570\u636e\uff0c\u5b66\u4e60\u4ece\u6d3b\u52a8\u7279\u5f81\u5230\u56e0\u679c\u6548\u5e94\u7684\u6620\u5c04\u5173\u7cfb\uff0c\u7136\u540e\u5c06\u5176\u5e94\u7528\u4e8e\u672a\u8fdb\u884cRCT\u7684\u6d3b\u52a8\u3002\u7531\u4e8eRCT\u80fd\u591f\u8bc6\u522b\u56e0\u679c\u6548\u5e94\uff0cPIE\u53ef\u4ee5\u7eb3\u5165\u4e8b\u540e\u786e\u5b9a\u7684\u7279\u5f81\u2014\u2014\u5982\u6d4b\u8bd5\u7ec4\u7ed3\u679c\u3001\u66dd\u5149\u7387\u548c\u6700\u540e\u70b9\u51fb\u8f6c\u5316\u7387\u7b49\u6d3b\u52a8\u5c42\u9762\u7684\u6c47\u603b\u6307\u6807\uff0c\u8fd9\u4e9b\u6307\u6807\u5728\u6d3b\u52a8\u7ed3\u675f\u540e\u8ba1\u7b97\u5f97\u51fa\u3002\u8fd9\u4e9b\u6307\u6807\u53cd\u6620\u4e86\u4ea7\u751f\u5904\u7406\u6548\u5e94\u7684\u6d88\u8d39\u8005\u884c\u4e3a\uff0c\u56e0\u6b64\u8574\u542b\u4e86\u5173\u4e8e\u589e\u91cf\u6027\u7684\u9884\u6d4b\u4fe1\u606f\uff0c\u5373\u4f7f\u5b83\u4eec\u5728\u56e0\u679c\u6a21\u578b\u4e2d\u4f5c\u4e3a\u63a7\u5236\u53d8\u91cf\u662f\u65e0\u6548\u7684\u3002\u57282,226\u4e2aMeta\u5e7f\u544a\u5b9e\u9a8c\u6570\u636e\u4e0a\uff0cPIE\u5b9e\u73b0\u4e86\u6bcf\u7f8e\u5143\u589e\u91cf\u8f6c\u5316\u7684\u6837\u672c\u5916[Formula: see text]\uff0c\u76f8\u6bd4\u884c\u4e1a\u6807\u51c6\u7684\u4e03\u5929\u6700\u540e\u70b9\u51fb\u5f52\u56e0\u65b9\u6cd5\u7684[Formula: see text]\u8868\u73b0\u66f4\u4f18\u3002\u5728\u51b3\u7b56\u6846\u67b6\u4e0b\uff0cPIE\u4ec5\u57288%\u81f312%\u7684\u6d3b\u52a8\u4e2d\u4e0e\u57fa\u4e8eRCT\u7684\u51b3\u7b56\u4ea7\u751f\u5206\u6b67\uff0c\u800c\u6700\u540e\u70b9\u51fb\u5f52\u56e0\u65b9\u6cd5\u7684\u5206\u6b67\u7387\u5219\u4e3a12%\u81f320%\u3002\u6211\u4eec\u5f97\u51fa\u7ed3\u8bba\uff1aPIE\u80fd\u591f\u5c06\u56e0\u679c\u6d4b\u91cf\u4ece\u5c11\u6570RCT\u6269\u5c55\u5230\u5927\u91cf\u975e\u5b9e\u9a8c\u6027\u6d3b\u52a8\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1093/restud/rdag110", "journal": "REStud", "title": "Are Markups Too High? Competition, Strategic Innovation, and Industry Dynamics", "authors": ["Laurent Cavenaile", "Murat Alp Celik", "Xu Tian"], "author_details": [{"name": "Laurent Cavenaile", "affiliations": ["University of Toronto"]}, {"name": "Murat Alp Celik", "affiliations": ["University of Toronto"]}, {"name": "Xu Tian", "affiliations": ["University of Georgia"]}], "abstract": "Abstract To study competition, innovation, and industry dynamics that arise as a result of their interaction, we develop a new oligopolistic general-equilibrium Schumpeterian growth model. This model ties together the endogenous growth, oligopolistic competition, and dynamic industrial organization literatures in a single unified framework. Within each industry, there are an endogenously determined number of large firms (\u201csuperstars\u201d) that compete \u00e1 la Cournot and a continuum of small firms which collectively constitute a competitive fringe. Firms dynamically choose their innovation strategies, cognizant of other firms' choices, and their entry and exit are endogenous. The model is consistent with the macroeconomic trends observed in the United States since the 1970s, such as the domination of industries by a small number of superstar firms, the rise of markups, market concentration, profits, and R&D spending, and the decline in business dynamism, productivity growth, and the labor share. It replicates the empirical relationship between innovation and competition within and across industries. As an application, we estimate the model to disentangle the effects of separate mechanisms on the structural transition observed in the United States, which yields striking results: (1) While the increase in the average markup causes a significant static welfare loss, this loss is overshadowed by the dynamic welfare gains from increased innovation in response to higher profit opportunities. (2) The increasing costs of innovation are found to be the primary determinant of lackluster productivity growth, i.e., ideas are getting harder to find.", "date": "2026-10-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-07T22:00:02+00:00", "url": "https://doi.org/10.1093/restud/rdag110", "topics": ["\u5176\u4ed6"], "title_zh": "\u6807\u4ef7\u662f\u5426\u8fc7\u9ad8\uff1f\u7ade\u4e89\u3001\u6218\u7565\u521b\u65b0\u4e0e\u4ea7\u4e1a\u52a8\u6001", "abstract_zh": "\u6458\u8981 \u4e3a\u7814\u7a76\u7ade\u4e89\u3001\u521b\u65b0\u53ca\u4ea7\u4e1a\u52a8\u6001\u5982\u4f55\u56e0\u76f8\u4e92\u4f5c\u7528\u800c\u4ea7\u751f\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u65b0\u7684\u5be1\u5934\u4e00\u822c\u5747\u8861\u65bd\u7a46\u5c14\u7279\u589e\u957f\u6a21\u578b\u3002\u8be5\u6a21\u578b\u5c06\u5185\u751f\u589e\u957f\u3001\u5be1\u5934\u7ade\u4e89\u548c\u52a8\u6001\u4ea7\u4e1a\u7ec4\u7ec7\u6587\u732e\u6574\u5408\u5728\u4e00\u4e2a\u7edf\u4e00\u7684\u6846\u67b6\u4e2d\u3002\u5728\u6bcf\u4e2a\u884c\u4e1a\u4e2d\uff0c\u5b58\u5728\u4e00\u4e2a\u5185\u751f\u786e\u5b9a\u6570\u91cf\u7684\u5927\u578b\u4f01\u4e1a\uff08\"\u8d85\u7ea7\u660e\u661f\"\u4f01\u4e1a\uff09\uff0c\u5b83\u4eec\u6309\u7167\u53e4\u8bfa\u7ade\u4e89\u6a21\u5f0f\u8fdb\u884c\u7ade\u4e89\uff0c\u800c\u5927\u91cf\u5c0f\u578b\u4f01\u4e1a\u5219\u5171\u540c\u6784\u6210\u4e00\u4e2a\u7ade\u4e89\u8fb9\u7f18\u3002\u4f01\u4e1a\u52a8\u6001\u9009\u62e9\u5176\u521b\u65b0\u7b56\u7565\uff0c\u5145\u5206\u8003\u8651\u5176\u4ed6\u4f01\u4e1a\u7684\u9009\u62e9\u53ca\u5176\u5229\u6da6\u673a\u4f1a\uff0c\u5e76\u4e14\u4f01\u4e1a\u7684\u8fdb\u5165\u4e0e\u9000\u51fa\u662f\u5185\u751f\u7684\u3002\u8be5\u6a21\u578b\u4e0e\u7f8e\u56fd\u81ea20\u4e16\u7eaa70\u5e74\u4ee3\u4ee5\u6765\u89c2\u5bdf\u5230\u7684\u5b8f\u89c2\u7ecf\u6d4e\u8d8b\u52bf\u4e00\u81f4\uff0c\u4f8b\u5982\u5c11\u6570\u8d85\u7ea7\u660e\u661f\u4f01\u4e1a\u4e3b\u5bfc\u884c\u4e1a\u3001\u6807\u4ef7\u4e0a\u5347\u3001\u5e02\u573a\u96c6\u4e2d\u5ea6\u3001\u5229\u6da6\u548c\u7814\u53d1\u652f\u51fa\u589e\u52a0\uff0c\u4ee5\u53ca\u4f01\u4e1a\u6d3b\u529b\u3001\u751f\u4ea7\u7387\u589e\u957f\u548c\u52b3\u52a8\u4efd\u989d\u7684\u4e0b\u964d\u3002\u6a21\u578b\u518d\u73b0\u4e86\u884c\u4e1a\u5185\u548c\u8de8\u884c\u4e1a\u521b\u65b0\u4e0e\u7ade\u4e89\u4e4b\u95f4\u7684\u5b9e\u8bc1\u5173\u7cfb\u3002\u4f5c\u4e3a\u5e94\u7528\uff0c\u6211\u4eec\u5bf9\u6a21\u578b\u8fdb\u884c\u4f30\u8ba1\uff0c\u4ee5\u5206\u79bb\u51fa\u5bfc\u81f4\u7f8e\u56fd\u7ed3\u6784\u6027\u8f6c\u53d8\u7684\u4e0d\u540c\u673a\u5236\uff0c\u5f97\u51fa\u663e\u8457\u7ed3\u679c\uff1a\uff081\uff09\u5c3d\u7ba1\u5e73\u5747\u6807\u4ef7\u4e0a\u5347\u5bfc\u81f4\u663e\u8457\u7684\u9759\u6001\u798f\u5229\u635f\u5931\uff0c\u4f46\u8fd9\u4e00\u635f\u5931\u88ab\u66f4\u9ad8\u5229\u6da6\u673a\u4f1a\u4e0b\u521b\u65b0\u5e26\u6765\u7684\u52a8\u6001\u798f\u5229\u6536\u76ca\u6240\u63a9\u76d6\u3002\uff082\uff09\u521b\u65b0\u6210\u672c\u7684\u4e0a\u5347\u662f\u751f\u4ea7\u7387\u589e\u957f\u4e4f\u529b\u7684\u4e3b\u8981\u539f\u56e0\uff0c\u5373\u53d1\u73b0\u65b0\u60f3\u6cd5\u53d8\u5f97\u8d8a\u6765\u8d8a\u56f0\u96be\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1111/jofi.70085", "journal": "JF", "title": "When Do Treasuries Earn the Convenience Yield?\u2014A Hedging Perspective", "authors": ["VIRAL V. ACHARYA", "TOOMAS LAARITS"], "author_details": [{"name": "VIRAL V. ACHARYA", "affiliations": []}, {"name": "TOOMAS LAARITS", "affiliations": []}], "abstract": "ABSTRACT We document that the convenience yield of U.S. Treasuries exhibits properties consistent with a hedging perspective of safe assets, that is, Treasuries are valued highly if they appreciate with poor aggregate shocks. In particular, the convenience yield tends to be low when the covariance of Treasury returns with the aggregate stock market returns is high. A decomposition of the aggregate stock\u2010bond covariance into terms corresponding to the convenience yield, the frictionless risk\u2010free rate, and default risk reveals that the covariance between stock returns and the convenience yield itself drives the effect in a substantive capacity.", "date": "2026-10-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-07T22:00:02+00:00", "url": "https://doi.org/10.1111/jofi.70085", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"], "title_zh": "\u56fd\u503a\u4f55\u65f6\u83b7\u5f97\u4fbf\u5229\u6536\u76ca\uff1f\u2014\u2014\u4e00\u79cd\u5bf9\u5b89\u5168\u8d44\u4ea7\u7684\u5bf9\u51b2\u89c6\u89d2", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u7f8e\u56fd\u56fd\u503a\u7684\u4fbf\u5229\u6536\u76ca\u8868\u73b0\u51fa\u4e0e\u5b89\u5168\u8d44\u4ea7\u5bf9\u51b2\u89c6\u89d2\u4e00\u81f4\u7684\u7279\u5f81\uff0c\u5373\u5f53\u56fd\u503a\u5728\u7ecf\u6d4e\u6574\u4f53\u51b2\u51fb\u4e2d\u8868\u73b0\u826f\u597d\u65f6\uff0c\u5176\u4ef7\u503c\u88ab\u9ad8\u5ea6\u8bc4\u4ef7\u3002\u5177\u4f53\u800c\u8a00\uff0c\u5f53\u56fd\u503a\u6536\u76ca\u7387\u4e0e\u6574\u4f53\u80a1\u7968\u5e02\u573a\u6536\u76ca\u7387\u7684\u534f\u65b9\u5dee\u8f83\u9ad8\u65f6\uff0c\u4fbf\u5229\u6536\u76ca\u5f80\u5f80\u8f83\u4f4e\u3002\u5c06\u6574\u4f53\u80a1\u7968\u4e0e\u503a\u5238\u6536\u76ca\u7387\u7684\u534f\u65b9\u5dee\u5206\u89e3\u4e3a\u4e0e\u4fbf\u5229\u6536\u76ca\u3001\u65e0\u6469\u64e6\u65e0\u98ce\u9669\u5229\u7387\u4ee5\u53ca\u8fdd\u7ea6\u98ce\u9669\u76f8\u5173\u7684\u90e8\u5206\u540e\u53d1\u73b0\uff0c\u80a1\u7968\u6536\u76ca\u7387\u4e0e\u4fbf\u5229\u6536\u76ca\u672c\u8eab\u7684\u534f\u65b9\u5dee\u5728\u8fd9\u4e00\u6548\u5e94\u4e2d\u8d77\u5230\u4e86\u5b9e\u8d28\u6027\u7684\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1111/jofi.70090", "journal": "JF", "title": "Targeted Philanthropy: Evidence from M&As", "authors": ["CARA VANSTEENKISTE"], "author_details": [{"name": "CARA VANSTEENKISTE", "affiliations": []}], "abstract": "ABSTRACT I show how firms optimize the allocation of charitable funds around investments that require external stakeholder support, such as mergers and acquisitions. Acquirers increase donations to target\u2010related charities before making a takeover offer, but scale funds back after withdrawing from a deal. Firms redistribute funds from nontakeover\u2010related areas to target insider\u2013affiliated charities, employee communities, and counties with a regulatory presence. Targeted donations that encourage blockholder reciprocity and employee commitment are associated with better deal performance through decreased merger premiums and lower integration costs. Overall, the results highlight firms\u2019 use of philanthropy to manage stakeholder relations in takeover decisions.", "date": "2026-10-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-07T22:00:02+00:00", "url": "https://doi.org/10.1111/jofi.70090", "topics": ["\u5e76\u8d2d"], "title_zh": "\u5b9a\u5411\u6148\u5584\uff1a\u6765\u81ea\u5e76\u8d2d\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u5c55\u793a\u4e86\u4f01\u4e1a\u5982\u4f55\u5728\u9700\u8981\u5916\u90e8\u5229\u76ca\u76f8\u5173\u8005\u652f\u6301\u7684\u6295\u8d44\u51b3\u7b56\uff08\u5982\u5e76\u8d2d\uff09\u4e2d\u4f18\u5316\u6148\u5584\u8d44\u91d1\u7684\u5206\u914d\u3002\u6536\u8d2d\u65b9\u5728\u63d0\u51fa\u5e76\u8d2d\u8981\u7ea6\u524d\u589e\u52a0\u5bf9\u4e0e\u76ee\u6807\u516c\u53f8\u76f8\u5173\u7684\u6148\u5584\u673a\u6784\u7684\u6350\u8d60\uff0c\u4f46\u5728\u64a4\u56de\u5e76\u8d2d\u4ea4\u6613\u540e\u5219\u51cf\u5c11\u6350\u8d60\u3002\u4f01\u4e1a\u4f1a\u5c06\u539f\u672c\u7528\u4e8e\u975e\u5e76\u8d2d\u76f8\u5173\u9886\u57df\u7684\u8d44\u91d1\u91cd\u65b0\u5206\u914d\u5230\u4e0e\u76ee\u6807\u516c\u53f8\u5185\u90e8\u5173\u8054\u4eba\u5458\u76f8\u5173\u7684\u6148\u5584\u673a\u6784\u3001\u5458\u5de5\u7fa4\u4f53\u4ee5\u53ca\u5177\u6709\u76d1\u7ba1\u5b58\u5728\u7684\u53bf\u533a\u3002\u65e8\u5728\u4fc3\u8fdb\u5927\u80a1\u4e1c\u4e92\u60e0\u5173\u7cfb\u548c\u5458\u5de5\u627f\u8bfa\u7684\u5b9a\u5411\u6350\u8d60\uff0c\u4e0e\u5e76\u8d2d\u4ea4\u6613\u8868\u73b0\u6539\u5584\u76f8\u5173\uff0c\u8868\u73b0\u4e3a\u5e76\u8d2d\u6ea2\u4ef7\u4e0b\u964d\u548c\u6574\u5408\u6210\u672c\u964d\u4f4e\u3002\u603b\u4f53\u800c\u8a00\uff0c\u7814\u7a76\u7ed3\u679c\u51f8\u663e\u4e86\u4f01\u4e1a\u5728\u5e76\u8d2d\u51b3\u7b56\u4e2d\u5229\u7528\u6148\u5584\u6d3b\u52a8\u6765\u7ba1\u7406\u5229\u76ca\u76f8\u5173\u8005\u5173\u7cfb\u7684\u505a\u6cd5\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2024.06516", "journal": "MS", "title": "Using Representation Learning and Website Text to Identify Competitor Networks", "authors": ["Gerard Hoberg", "Craig Knoblock", "Gordon Phillips", "Jay Pujara", "Zhiqiang Qiu", "Louiqa Raschid"], "author_details": [{"name": "Gerard Hoberg", "affiliations": ["University of Southern California, Los Angeles, California 90089"]}, {"name": "Craig Knoblock", "affiliations": ["University of Southern California, Los Angeles, California 90089"]}, {"name": "Gordon Phillips", "affiliations": ["Tuck School of Business, Dartmouth College, Hanover, New Hampshire 03755"]}, {"name": "Jay Pujara", "affiliations": ["University of Southern California, Los Angeles, California 90089"]}, {"name": "Zhiqiang Qiu", "affiliations": ["University of Southern California, Los Angeles, California 90089"]}, {"name": "Louiqa Raschid", "affiliations": ["University of Maryland at College Park, College Park, Maryland 20742"]}], "abstract": "This paper introduces a new approach to identify competitors using company websites to map competitive relationships among public and private firms. We apply representation learning techniques to create embeddings of companies based on website content, emphasizing information about industry-specific products and services. By placing all firms, public and private, within the same embedding space, we construct a peer competitor network that supports analysis of company interactions and market evolution. We label this new approach and set of network competitors as the website text-based network industry classification (WTNIC). We evaluate the quality of the network using multiple ground truth datasets and benchmarks and show that it offers a robust alternative for understanding competition at scale. Despite using noisy website data, WTNIC matches or outperforms prior approaches that rely on curated data. We demonstrate the value of WTNIC through a case study examining how competition from China affects the public and private peers of a focal firm, highlighting the importance of placing both public and private companies within the same embedding space.", "date": "2026-10-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-07T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06516", "topics": ["\u7f51\u7edc"], "title_zh": "\u5229\u7528\u8868\u793a\u5b66\u4e60\u548c\u7f51\u7ad9\u6587\u672c\u8bc6\u522b\u7ade\u4e89\u5bf9\u624b\u7f51\u7edc", "abstract_zh": "\u672c\u6587\u63d0\u51fa\u4e86\u4e00\u79cd\u5229\u7528\u516c\u53f8\u7f51\u7ad9\u5185\u5bb9\u8bc6\u522b\u7ade\u4e89\u5bf9\u624b\u7684\u65b0\u65b9\u6cd5\uff0c\u901a\u8fc7\u6620\u5c04\u516c\u5171\u548c\u79c1\u8425\u4f01\u4e1a\u4e4b\u95f4\u7684\u7ade\u4e89\u5173\u7cfb\u3002\u6211\u4eec\u5e94\u7528\u8868\u793a\u5b66\u4e60\u6280\u672f\uff0c\u57fa\u4e8e\u7f51\u7ad9\u5185\u5bb9\u751f\u6210\u4f01\u4e1a\u7684\u5d4c\u5165\u8868\u793a\uff0c\u91cd\u70b9\u5173\u6ce8\u884c\u4e1a\u7279\u5b9a\u7684\u4ea7\u54c1\u548c\u670d\u52a1\u4fe1\u606f\u3002\u901a\u8fc7\u5c06\u6240\u6709\u4f01\u4e1a\u2014\u2014\u65e0\u8bba\u662f\u516c\u5171\u8fd8\u662f\u79c1\u8425\u2014\u2014\u7f6e\u4e8e\u540c\u4e00\u5d4c\u5165\u7a7a\u95f4\u4e2d\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u540c\u884c\u7ade\u4e89\u5bf9\u624b\u7f51\u7edc\uff0c\u4ee5\u652f\u6301\u5bf9\u516c\u53f8\u4e92\u52a8\u548c\u5e02\u573a\u6f14\u53d8\u7684\u5206\u6790\u3002\u6211\u4eec\u5c06\u8fd9\u4e00\u65b0\u65b9\u6cd5\u53ca\u5176\u5f62\u6210\u7684\u7ade\u4e89\u5bf9\u624b\u7f51\u7edc\u79f0\u4e3a\u7f51\u7ad9\u6587\u672c\u57fa\u7840\u7684\u7f51\u7edc\u884c\u4e1a\u5206\u7c7b\uff08WTNIC\uff09\u3002\u6211\u4eec\u4f7f\u7528\u591a\u4e2a\u771f\u5b9e\u6570\u636e\u96c6\u548c\u57fa\u51c6\u6d4b\u8bd5\u8bc4\u4f30\u4e86\u8be5\u7f51\u7edc\u7684\u8d28\u91cf\uff0c\u7ed3\u679c\u8868\u660e\uff0cWTNIC\u5728\u5927\u89c4\u6a21\u7406\u89e3\u7ade\u4e89\u65b9\u9762\u63d0\u4f9b\u4e86\u4e00\u4e2a\u7a33\u5065\u7684\u66ff\u4ee3\u65b9\u6848\u3002\u5c3d\u7ba1\u4f7f\u7528\u7684\u662f\u566a\u58f0\u8f83\u5927\u7684\u7f51\u7ad9\u6570\u636e\uff0cWTNIC\u5728\u5339\u914d\u6216\u8d85\u8d8a\u4f9d\u8d56\u4e8e\u4eba\u5de5\u6574\u7406\u6570\u636e\u7684\u5148\u524d\u65b9\u6cd5\u65b9\u9762\u8868\u73b0\u4f18\u5f02\u3002\u6211\u4eec\u901a\u8fc7\u4e00\u4e2a\u6848\u4f8b\u7814\u7a76\u5c55\u793a\u4e86WTNIC\u7684\u4ef7\u503c\uff0c\u5373\u5206\u6790\u4e2d\u56fd\u7ade\u4e89\u5bf9\u624b\u5982\u4f55\u5f71\u54cd\u67d0\u7126\u70b9\u4f01\u4e1a\u7684\u516c\u5171\u548c\u79c1\u8425\u540c\u884c\uff0c\u7a81\u663e\u4e86\u5c06\u516c\u5171\u548c\u79c1\u8425\u4f01\u4e1a\u7f6e\u4e8e\u540c\u4e00\u5d4c\u5165\u7a7a\u95f4\u4e2d\u7684\u91cd\u8981\u6027\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2024.06298", "journal": "MS", "title": "Personalization, Engagement, and Content Quality on Social Media: An Evaluation of Reddit\u2019s News Feed", "authors": ["Alex Moehring"], "author_details": [{"name": "Alex Moehring", "affiliations": ["Operations, Information and Decisions, The Wharton School, University of Pennsylvania, Philadelphia Pennsylvania 19104"]}], "abstract": "Digital platforms increasingly curate their content through personalized algorithmic feeds. Platforms have an incentive to promote content that increases the predicted engagement of each user to lift advertising revenues. This paper studies how ranking content to maximize engagement affects the credibility of news content with which users engage. In addition, I evaluate how the ranking algorithm itself can be designed to promote engagement with high-credibility content. Using data from the Reddit politics community, I exploit a novel discontinuity in the ranking algorithm to identify the causal effect of a post\u2019s rank on the number of comments it receives. I use this discontinuity to identify a model of user comment decisions and estimate the credibility of news content that users engage with under a personalized engagement-maximizing algorithm. The personalized engagement-maximizing algorithm exacerbates differences in the credibility of news content with which users engage. I then evaluate a credibility-aware algorithm that explicitly promotes credible news publishers and find the platform can substantially increase the share of engagement with high-credibility publishers for a small reduction in total engagement. These findings suggest algorithmic interventions can be a useful tool for managers to balance engagement quantity and content quality.", "date": "2026-10-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-07T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06298", "topics": ["\u5176\u4ed6"], "title_zh": "\u793e\u4ea4\u5a92\u4f53\u4e0a\u7684\u4e2a\u6027\u5316\u3001\u53c2\u4e0e\u5ea6\u4e0e\u5185\u5bb9\u8d28\u91cf\uff1a\u5bf9Reddit\u65b0\u95fb\u63a8\u9001\u7684\u8bc4\u4f30", "abstract_zh": "\u6570\u5b57\u5e73\u53f0\u8d8a\u6765\u8d8a\u591a\u5730\u901a\u8fc7\u4e2a\u6027\u5316\u7b97\u6cd5\u63a8\u9001\u5185\u5bb9\u3002\u5e73\u53f0\u6709\u52a8\u673a\u63a8\u5e7f\u80fd\u591f\u63d0\u5347\u6bcf\u4f4d\u7528\u6237\u9884\u6d4b\u53c2\u4e0e\u5ea6\u7684\u5185\u5bb9\uff0c\u4ee5\u63d0\u9ad8\u5e7f\u544a\u6536\u5165\u3002\u672c\u6587\u7814\u7a76\u4e86\u4e3a\u6700\u5927\u5316\u53c2\u4e0e\u5ea6\u800c\u5bf9\u5185\u5bb9\u8fdb\u884c\u6392\u5e8f\uff0c\u5982\u4f55\u5f71\u54cd\u7528\u6237\u53c2\u4e0e\u7684\u5185\u5bb9\u7684\u53ef\u4fe1\u5ea6\u3002\u6b64\u5916\uff0c\u672c\u6587\u8bc4\u4f30\u4e86\u5982\u4f55\u8bbe\u8ba1\u6392\u5e8f\u7b97\u6cd5\uff0c\u4ee5\u4fc3\u8fdb\u5bf9\u9ad8\u53ef\u4fe1\u5ea6\u5185\u5bb9\u7684\u53c2\u4e0e\u3002\u5229\u7528\u6765\u81eaReddit\u653f\u6cbb\u793e\u533a\u7684\u6570\u636e\uff0c\u6211\u5229\u7528\u6392\u5e8f\u7b97\u6cd5\u4e2d\u4e00\u4e2a\u65b0\u9896\u7684\u4e0d\u8fde\u7eed\u6027\uff0c\u8bc6\u522b\u51fa\u5e16\u5b50\u6392\u540d\u5bf9\u6536\u5230\u8bc4\u8bba\u6570\u91cf\u7684\u56e0\u679c\u6548\u5e94\u3002\u6211\u5229\u7528\u8fd9\u4e00\u4e0d\u8fde\u7eed\u6027\uff0c\u6784\u5efa\u4e86\u7528\u6237\u8bc4\u8bba\u51b3\u7b56\u6a21\u578b\uff0c\u5e76\u4f30\u8ba1\u4e86\u5728\u4e2a\u6027\u5316\u53c2\u4e0e\u6700\u5927\u5316\u7b97\u6cd5\u4e0b\uff0c\u7528\u6237\u53c2\u4e0e\u7684\u5185\u5bb9\u7684\u53ef\u4fe1\u5ea6\u3002\u4e2a\u6027\u5316\u53c2\u4e0e\u6700\u5927\u5316\u7b97\u6cd5\u52a0\u5267\u4e86\u7528\u6237\u6240\u63a5\u89e6\u65b0\u95fb\u5185\u5bb9\u53ef\u4fe1\u5ea6\u7684\u5dee\u5f02\u3002\u968f\u540e\uff0c\u6211\u8bc4\u4f30\u4e86\u4e00\u79cd\u5173\u6ce8\u53ef\u4fe1\u5ea6\u7684\u7b97\u6cd5\uff0c\u8be5\u7b97\u6cd5\u660e\u786e\u4fc3\u8fdb\u53ef\u4fe1\u65b0\u95fb\u51fa\u7248\u5546\uff0c\u53d1\u73b0\u5e73\u53f0\u53ef\u4ee5\u901a\u8fc7\u5c0f\u5e45\u964d\u4f4e\u603b\u53c2\u4e0e\u5ea6\uff0c\u663e\u8457\u63d0\u5347\u5bf9\u9ad8\u53ef\u4fe1\u5ea6\u51fa\u7248\u5546\u7684\u53c2\u4e0e\u6bd4\u4f8b\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u7b97\u6cd5\u5e72\u9884\u53ef\u4ee5\u6210\u4e3a\u7ba1\u7406\u8005\u5728\u53c2\u4e0e\u91cf\u4e0e\u5185\u5bb9\u8d28\u91cf\u4e4b\u95f4\u53d6\u5f97\u5e73\u8861\u7684\u6709\u529b\u5de5\u5177\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1111/jofi.70083", "journal": "JF", "title": "Flow\u2010Driven ESG Returns", "authors": ["PHILIPPE VAN DER BECK"], "author_details": [{"name": "PHILIPPE VAN DER BECK", "affiliations": []}], "abstract": "ABSTRACT I show that the recent returns to environmental, social, and governance (ESG) investing are strongly driven by price impact from flows toward ESG portfolios. Using data on trades, I estimate the market's ability to accommodate ESG flows, which is given by the elasticity of substitution between ESG and other stocks. I show that every dollar flowing toward a representative ESG portfolio increases the market value of ESG stocks by $0.8. The growing institutional flows into the ESG portfolio are the main driver of ESG returns and have caused an annual flow\u2010driven return of 1.9%. In the absence of flows, ESG stocks would not have outperformed the market from 2012 to 2023.", "date": "2026-10-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-08T22:00:02+00:00", "url": "https://doi.org/10.1111/jofi.70083", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"], "title_zh": "\u6d41\u91cf\u9a71\u52a8\u7684ESG\u6536\u76ca", "abstract_zh": "\u6211\u8bc1\u660e\u4e86\u8fd1\u5e74\u6765\u73af\u5883\u3001\u793e\u4f1a\u548c\u6cbb\u7406\uff08ESG\uff09\u6295\u8d44\u7684\u56de\u62a5\u4e3b\u8981\u7531\u6d41\u5411ESG\u7ec4\u5408\u7684\u4ea4\u6613\u51b2\u51fb\u5f15\u8d77\u3002\u5229\u7528\u4ea4\u6613\u6570\u636e\uff0c\u6211\u4f30\u8ba1\u4e86\u5e02\u573a\u5bb9\u7eb3ESG\u6d41\u91cf\u7684\u80fd\u529b\uff0c\u5373ESG\u80a1\u7968\u4e0e\u5176\u4ed6\u80a1\u7968\u4e4b\u95f4\u7684\u66ff\u4ee3\u5f39\u6027\u3002\u6211\u8868\u660e\uff0c\u6bcf\u5411\u4e00\u4e2a\u4ee3\u8868\u6027ESG\u7ec4\u5408\u6ce8\u5165\u4e00\u7f8e\u5143\uff0cESG\u80a1\u7968\u7684\u5e02\u573a\u4ef7\u503c\u5c31\u4f1a\u589e\u52a00.8\u7f8e\u5143\u3002\u65e5\u76ca\u589e\u957f\u7684\u673a\u6784\u8d44\u91d1\u6d41\u5165ESG\u7ec4\u5408\u662fESG\u6536\u76ca\u7684\u4e3b\u8981\u9a71\u52a8\u56e0\u7d20\uff0c\u5df2\u5bfc\u81f4\u6bcf\u5e74\u7531\u6d41\u91cf\u9a71\u52a8\u7684\u56de\u62a5\u7387\u4e3a1.9%\u3002\u5728\u6ca1\u6709\u8d44\u91d1\u6d41\u52a8\u7684\u60c5\u51b5\u4e0b\uff0c\u4ece2012\u5e74\u52302023\u5e74ESG\u80a1\u7968\u5e76\u672a\u8dd1\u8d62\u5e02\u573a\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1093/restud/rdag111", "journal": "REStud", "title": "The Marginal Propensity to Hire", "authors": ["Davide Melcangi"], "author_details": [{"name": "Davide Melcangi", "affiliations": ["Federal Reserve Bank of New York"]}], "abstract": "Abstract When financial constraints bind, firms adjust employment in response to cash flow shocks. A 2010 revaluation of business rates, a UK tax levied on business-occupied properties, implied that similar firms, occupying similar properties in narrow geographical locations, experienced different tax changes. I find that, on average, for every \uffe11 of additional cash flow triggered by the tax change, 39 pence were spent on employment, with small and leveraged firms responding the most. I use these findings to discipline a general equilibrium model with firm heterogeneity and financial frictions and quantitatively determine the aggregate effects of a fiscal transfer to firms.", "date": "2026-10-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-06T22:00:02+00:00", "url": "https://doi.org/10.1093/restud/rdag111", "title_zh": "\u96c7\u4f63\u8fb9\u9645\u503e\u5411", "abstract_zh": "\u5f53\u8d22\u52a1\u7ea6\u675f\u751f\u6548\u65f6\uff0c\u4f01\u4e1a\u4f1a\u6839\u636e\u73b0\u91d1\u6d41\u51b2\u51fb\u8c03\u6574\u96c7\u4f63\u6c34\u5e73\u3002\u4e00\u98792010\u5e74\u5bf9\u82f1\u56fd\u4f01\u4e1a\u7a0e\u7684\u91cd\u65b0\u8bc4\u4f30\u663e\u793a\uff0c\u4f4d\u4e8e\u76f8\u8fd1\u5730\u7406\u533a\u57df\u3001\u5360\u7528\u76f8\u4f3c\u7269\u4e1a\u7684\u76f8\u4f3c\u4f01\u4e1a\u7ecf\u5386\u4e86\u4e0d\u540c\u7684\u7a0e\u8d1f\u53d8\u5316\u3002\u6211\u53d1\u73b0\uff0c\u5e73\u5747\u800c\u8a00\uff0c\u6bcf\u589e\u52a01\u82f1\u9551\u7684\u73b0\u91d1\u6d41\uff0c\u4f01\u4e1a\u4f1a\u5c0639\u4fbf\u58eb\u7528\u4e8e\u96c7\u4f63\u652f\u51fa\uff0c\u5176\u4e2d\u5c0f\u578b\u4f01\u4e1a\u548c\u6760\u6746\u7387\u8f83\u9ad8\u7684\u4f01\u4e1a\u53cd\u5e94\u6700\u4e3a\u663e\u8457\u3002\u6211\u5229\u7528\u8fd9\u4e9b\u53d1\u73b0\u6765\u7ea6\u675f\u4e00\u4e2a\u5305\u542b\u4f01\u4e1a\u5f02\u8d28\u6027\u548c\u91d1\u878d\u6469\u64e6\u7684\u4e00\u822c\u5747\u8861\u6a21\u578b\uff0c\u5e76\u5b9a\u91cf\u786e\u5b9a\u8d22\u653f\u8f6c\u79fb\u5bf9\u4f01\u4e1a\u6574\u4f53\u7684\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag090", "journal": "RFS", "title": "Directing the Labor Market: Shared Directors and Employee Flows", "authors": ["Taylor A Begley", "Peter Haslag", "Daniel Weagley"], "author_details": [{"name": "Taylor A Begley", "affiliations": ["University of Kentucky ,"]}, {"name": "Peter Haslag", "affiliations": ["University of Tennessee, Vanderbilt University ,"]}, {"name": "Daniel Weagley", "affiliations": ["University of Tennessee ,"]}], "abstract": "Abstract Using r\u00e9sum\u00e9 data on over 20 million U.S. workers, we find that the flow of employees between a pair of firms sharply drops by about 20% during periods in which the firms share a board director. This relationship is stronger in settings where firms have greater potential gains from limiting worker mobility and is most pronounced for higher-skilled employees. Moreover, we find more connected firms have lower rates of internal promotion and no improvements in employee satisfaction. The evidence is consistent with shared directors serving as a mechanism for labor market coordination. (JEL G34, G38, J42, J62, J08, K21, K31, M50)", "date": "2026-10-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-06T22:00:02+00:00", "url": "https://doi.org/10.1093/rfs/hhag090", "title_zh": "\u5f15\u5bfc\u52b3\u52a8\u529b\u5e02\u573a\uff1a\u5171\u4eab\u8463\u4e8b\u4e0e\u5458\u5de5\u6d41\u52a8", "abstract_zh": "\u5229\u7528\u5bf9\u8d85\u8fc72000\u4e07\u540d\u7f8e\u56fd\u5458\u5de5\u7b80\u5386\u6570\u636e\u7684\u5206\u6790\uff0c\u6211\u4eec\u53d1\u73b0\u5f53\u4e24\u5bb6\u516c\u53f8\u5171\u4eab\u8463\u4e8b\u4f1a\u8463\u4e8b\u65f6\uff0c\u5458\u5de5\u5728\u4e24\u5bb6\u4f01\u4e1a\u4e4b\u95f4\u7684\u6d41\u52a8\u7387\u4f1a\u663e\u8457\u4e0b\u964d\u7ea620%\u3002\u8fd9\u4e00\u5173\u7cfb\u5728\u4f01\u4e1a\u901a\u8fc7\u9650\u5236\u5458\u5de5\u6d41\u52a8\u53ef\u80fd\u83b7\u5f97\u66f4\u5927\u6536\u76ca\u7684\u73af\u5883\u4e2d\u66f4\u4e3a\u660e\u663e\uff0c\u4e14\u5bf9\u9ad8\u6280\u80fd\u5458\u5de5\u5c24\u4e3a\u663e\u8457\u3002\u6b64\u5916\uff0c\u6211\u4eec\u53d1\u73b0\u8fde\u63a5\u66f4\u7d27\u5bc6\u7684\u516c\u53f8\u5185\u90e8\u664b\u5347\u7387\u66f4\u4f4e\uff0c\u5458\u5de5\u6ee1\u610f\u5ea6\u4e5f\u672a\u5f97\u5230\u6539\u5584\u3002\u8bc1\u636e\u8868\u660e\uff0c\u5171\u4eab\u8463\u4e8b\u53ef\u80fd\u4f5c\u4e3a\u4e00\u79cd\u52b3\u52a8\u529b\u5e02\u573a\u534f\u8c03\u7684\u673a\u5236\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag089", "journal": "RFS", "title": "Central Bank Economic Transparency and Managerial Learning", "authors": ["Oliver Binz", "Elia Ferracuti", "Gary Lind"], "author_details": [{"name": "Oliver Binz", "affiliations": ["ESMT Berlin,"]}, {"name": "Elia Ferracuti", "affiliations": ["Duke University Fuqua School of Business, ,"]}, {"name": "Gary Lind", "affiliations": ["University of Pittsburgh Katz Graduate School of Business, ,"]}], "abstract": "Abstract Central banks increasingly disclose their private information regarding the economy\u2019s current and future state (CBET). Consistent with CBET shifting investors\u2019 collection and pricing of aggregate-level (where managers do not have an information advantage) toward firm-level (where managers do have an information advantage) information, we find that CBET reduces managers\u2019 learning from stock price. The results are (1) pronounced when firms do not provide guidance and when noise trading in firms\u2019 stock is low, and (2) robust to using the 2013\u20132014 amendments to the Bank of England\u2019s Inflation Report as an exogenous shock. Additional evidence suggests that CBET lowers investment efficiency. (JEL E22, E52, M41)", "date": "2026-10-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-06T22:00:02+00:00", "url": "https://doi.org/10.1093/rfs/hhag089", "title_zh": "\u4e2d\u592e\u94f6\u884c\u7ecf\u6d4e\u900f\u660e\u5ea6\u4e0e\u7ba1\u7406\u5c42\u5b66\u4e60", "abstract_zh": "\u6458\u8981 \u4e2d\u592e\u94f6\u884c\u8d8a\u6765\u8d8a\u9891\u7e41\u5730\u62ab\u9732\u5176\u5173\u4e8e\u7ecf\u6d4e\u5f53\u524d\u53ca\u672a\u6765\u72b6\u6001\u7684\u79c1\u4eba\u4fe1\u606f\uff08CBET\uff09\u3002\u4e0eCBET\u4fc3\u4f7f\u6295\u8d44\u8005\u4ece\u6574\u4f53\u5c42\u9762\uff08\u5176\u4e2d\u7ba1\u7406\u5c42\u6ca1\u6709\u4fe1\u606f\u4f18\u52bf\uff09\u7684\u4fe1\u606f\u6536\u96c6\u548c\u5b9a\u4ef7\u8f6c\u5411\u4f01\u4e1a\u5c42\u9762\uff08\u5176\u4e2d\u7ba1\u7406\u5c42\u62e5\u6709\u4fe1\u606f\u4f18\u52bf\uff09\u7684\u4fe1\u606f\u6536\u96c6\u548c\u5b9a\u4ef7\u76f8\u4e00\u81f4\uff0c\u6211\u4eec\u53d1\u73b0CBET\u4f1a\u964d\u4f4e\u7ba1\u7406\u5c42\u4ece\u80a1\u4ef7\u4e2d\u83b7\u5f97\u7684\u5b66\u4e60\u6548\u679c\u3002\u8fd9\u4e00\u7ed3\u679c\u5728\u4ee5\u4e0b\u4e24\u79cd\u60c5\u51b5\u4e0b\u5c24\u4e3a\u663e\u8457\uff1a\u4e00\u662f\u4f01\u4e1a\u4e0d\u63d0\u4f9b\u4e1a\u7ee9\u6307\u5f15\uff0c\u4e8c\u662f\u4f01\u4e1a\u80a1\u7968\u4e2d\u7684\u566a\u97f3\u4ea4\u6613\u8f83\u4f4e\uff1b\u540c\u65f6\uff0c\u8be5\u7ed3\u679c\u5728\u4f7f\u7528\u82f1\u683c\u5170\u94f6\u884c2013-2014\u5e74\u300a\u901a\u80c0\u62a5\u544a\u300b\u4fee\u8ba2\u7248\u4f5c\u4e3a\u5916\u751f\u51b2\u51fb\u65f6\u4f9d\u7136\u7a33\u5065\u3002\u989d\u5916\u7684\u8bc1\u636e\u8868\u660e\uff0cCBET\u4f1a\u964d\u4f4e\u6295\u8d44\u6548\u7387\u3002\uff08JEL E22, E52, M41\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.04789", "journal": "MS", "title": "Trading Off Business and Family Investments: Evidence from U.S. Entrepreneurial Households", "authors": ["Olivia S. Kim"], "author_details": [{"name": "Olivia S. Kim", "affiliations": ["Harvard Business School, Harvard University, Boston, Massachusetts 02163"]}], "abstract": "Investing in children\u2019s human capital reduces business investments for U.S. entrepreneurial households. Using financial account data of 90,000 small businesses linked to their owners and a regression discontinuity design that compares the business performance of households with college-aged dependents (18\u201322) to those with near-college-aged dependents (14\u201317), I show that business revenues and expenses decline sharply when owners\u2019 children reach age 18. Despite the declines, profitability and productivity remain largely unaffected, suggesting a general downsizing rather than a loss in efficiency. Heterogeneity analysis shows that downsizing is concentrated among highly indebted owner households and businesses with volatile cash flows. For each dollar increase in household spending associated with a child turning 18, business expenses decline by $2.26. These findings are consistent with entrepreneurial parents reallocating capital from business investments toward their children\u2019s human capital, as both compete for the same pool of internal family financial resources.", "date": "2026-10-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-06T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.04789", "title_zh": "\u5728\u5546\u4e1a\u6295\u8d44\u4e0e\u5bb6\u5ead\u6295\u8d44\u4e4b\u95f4\u6743\u8861\uff1a\u6765\u81ea\u7f8e\u56fd\u521b\u4e1a\u5bb6\u5ead\u7684\u8bc1\u636e", "abstract_zh": "\u7f8e\u56fd\u521b\u4e1a\u5bb6\u5ead\u5728\u6295\u8d44\u5b50\u5973\u4eba\u529b\u8d44\u672c\u65f6\uff0c\u4f1a\u51cf\u5c11\u5176\u5546\u4e1a\u6295\u8d44\u3002\u5229\u752890,000\u5bb6\u5c0f\u578b\u4f01\u4e1a\u7684\u8d22\u52a1\u8d26\u6237\u6570\u636e\uff0c\u5e76\u5c06\u5176\u4e0e\u4f01\u4e1a\u6240\u6709\u8005\u5173\u8054\uff0c\u901a\u8fc7\u56de\u5f52\u65ad\u70b9\u8bbe\u8ba1\uff0c\u5c06\u62e5\u670918\u81f322\u5c81\u5927\u5b66\u751f\u5b50\u5973\u7684\u5bb6\u5ead\u4e0e\u62e5\u670914\u81f317\u5c81\u63a5\u8fd1\u5927\u5b66\u5e74\u9f84\u5b50\u5973\u7684\u5bb6\u5ead\u8fdb\u884c\u6bd4\u8f83\uff0c\u6211\u53d1\u73b0\u5f53\u4f01\u4e1a\u6240\u6709\u8005\u7684\u5b50\u5973\u8fbe\u523018\u5c81\u65f6\uff0c\u4f01\u4e1a\u7684\u6536\u5165\u548c\u652f\u51fa\u663e\u8457\u4e0b\u964d\u3002\u5c3d\u7ba1\u6536\u5165\u548c\u652f\u51fa\u4e0b\u964d\uff0c\u4f46\u76c8\u5229\u80fd\u529b\u548c\u751f\u4ea7\u7387\u57fa\u672c\u672a\u53d7\u5f71\u54cd\uff0c\u8fd9\u8868\u660e\u662f\u4e00\u79cd\u6574\u4f53\u89c4\u6a21\u7f29\u51cf\u800c\u975e\u6548\u7387\u635f\u5931\u3002\u5f02\u8d28\u6027\u5206\u6790\u663e\u793a\uff0c\u8fd9\u79cd\u89c4\u6a21\u7f29\u51cf\u4e3b\u8981\u96c6\u4e2d\u5728\u503a\u52a1\u6c34\u5e73\u8f83\u9ad8\u7684\u6240\u6709\u8005\u5bb6\u5ead\u4ee5\u53ca\u73b0\u91d1\u6d41\u6ce2\u52a8\u8f83\u5927\u7684\u4f01\u4e1a\u4e2d\u3002\u6bcf\u5f53\u5bb6\u5ead\u56e0\u5b50\u5973\u5e74\u6ee118\u5c81\u800c\u589e\u52a01\u7f8e\u5143\u7684\u652f\u51fa\uff0c\u5176\u5546\u4e1a\u652f\u51fa\u5c31\u51cf\u5c112.26\u7f8e\u5143\u3002\u8fd9\u4e9b\u53d1\u73b0\u4e0e\u521b\u4e1a\u7236\u6bcd\u5c06\u5bb6\u5ead\u5185\u90e8\u8d22\u52a1\u8d44\u6e90\u4ece\u5546\u4e1a\u6295\u8d44\u91cd\u65b0\u5206\u914d\u5230\u5b50\u5973\u4eba\u529b\u8d44\u672c\u6295\u8d44\u7684\u73b0\u8c61\u4e00\u81f4\uff0c\u56e0\u4e3a\u5546\u4e1a\u6295\u8d44\u548c\u5b50\u5973\u6559\u80b2\u6295\u8d44\u5728\u8d44\u6e90\u5206\u914d\u4e0a\u5b58\u5728\u7ade\u4e89\u5173\u7cfb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.08420", "journal": "MS", "title": "Money Creation for Crypto Space: Stablecoins or Central Bank Digital Currencies?", "authors": ["Jonathan Chiu", "Cyril Monnet"], "author_details": [{"name": "Jonathan Chiu", "affiliations": ["Payments and Regulatory Oversight, Bank of Canada, Ottawa, Ontario K1A 0G9, Canada"]}, {"name": "Cyril Monnet", "affiliations": ["Department of Economics, University of Bern, 3012 Bern, Switzerland; and Study Center Gerzensee, 3115 Gerzensee, Switzerland"]}], "abstract": "Stablecoins are the current go-to digital money to settle transactions on the blockchain. We explore the implications of introducing competing tokenized public digital monies (i.e., tokenized central bank digital currencies (CBDCs)). When they pay a moderate interest rate and guarantee users\u2019 anonymity, tokenized CBDCs crowd out stablecoins. However, when they pay a high interest rate and have low anonymity features, stablecoin issuers could use tokenized CBDCs as collateral, promoting the creation of stablecoins. We identify conditions under which introducing a CBDC to compete with stablecoins in the crypto sector would be socially optimal.", "date": "2026-10-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-06T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08420", "title_zh": "\u4e3a\u52a0\u5bc6\u7a7a\u95f4\u521b\u9020\u8d27\u5e01\uff1a\u7a33\u5b9a\u5e01\u8fd8\u662f\u4e2d\u592e\u94f6\u884c\u6570\u5b57\u8d27\u5e01\uff1f", "abstract_zh": "\u7a33\u5b9a\u5e01\u662f\u76ee\u524d\u5728\u533a\u5757\u94fe\u4e0a\u7ed3\u7b97\u4ea4\u6613\u7684\u9996\u9009\u6570\u5b57\u8d27\u5e01\u3002\u6211\u4eec\u63a2\u8ba8\u5f15\u5165\u7ade\u4e89\u6027\u6570\u5b57\u5316\u516c\u5171\u8d27\u5e01\uff08\u5373\u6570\u5b57\u5316\u4e2d\u592e\u94f6\u884c\u6570\u5b57\u8d27\u5e01\uff08CBDC\uff09\uff09\u7684\u540e\u679c\u3002\u5f53\u8fd9\u4e9b\u6570\u5b57\u8d27\u5e01\u652f\u4ed8\u9002\u5ea6\u7684\u5229\u7387\u5e76\u4fdd\u8bc1\u7528\u6237\u7684\u533f\u540d\u6027\u65f6\uff0c\u6570\u5b57\u5316CBDC\u4f1a\u6324\u51fa\u7a33\u5b9a\u5e01\uff1b\u7136\u800c\uff0c\u5f53\u5b83\u4eec\u652f\u4ed8\u9ad8\u5229\u7387\u4e14\u5177\u6709\u8f83\u4f4e\u7684\u533f\u540d\u6027\u7279\u5f81\u65f6\uff0c\u7a33\u5b9a\u5e01\u53d1\u884c\u65b9\u53ef\u4ee5\u5c06\u6570\u5b57\u5316CBDC\u4f5c\u4e3a\u62b5\u62bc\u54c1\uff0c\u4ece\u800c\u4fc3\u8fdb\u7a33\u5b9a\u5e01\u7684\u53d1\u884c\u3002\u6211\u4eec\u8bc6\u522b\u51fa\u5728\u4f55\u79cd\u6761\u4ef6\u4e0b\uff0c\u5c06CBDC\u5f15\u5165\u4e0e\u7a33\u5b9a\u5e01\u7ade\u4e89\u7684\u52a0\u5bc6\u9886\u57df\u5c06\u5bf9\u793e\u4f1a\u6574\u4f53\u6700\u4f18\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.07399", "journal": "MS", "title": "The Welfare Effects of Selling Leads in a Two-Sided Marketplace", "authors": ["Peng Shi"], "author_details": [{"name": "Peng Shi", "affiliations": ["USC Marshall School of Business, University of Southern California, Los Angeles, California 90089"]}], "abstract": "Digital platforms that connect customers with service providers often monetize by selling customer leads to interested providers. Examples include Bark, Google Local Services, HomeAdvisor, Modernize, Porch, and Thumbtack. This paper develops a game-theoretic model to analyze how lead pricing affects customer and provider welfare. When the platform raises the fee-per-lead for a customer-type, those customers\u2014conditional on receiving the same number of provider quotes\u2014are quoted lower prices. However, if the fee is sufficiently high, providers purchase fewer of these leads, which can reduce the number of quotes and diminish customer surplus. To maximize social welfare, a simple policy that sets a market-clearing fee-per-lead for each customer-type guarantees at least [Formula: see text] of the first-best welfare and at least [Formula: see text] of the welfare under the welfare-optimal fees. The first-best outcome can be achieved by subsidizing providers for each job well done, so that experienced providers with cheaper sources of leads do not exit the platform. Understanding these welfare trade-offs can help platforms design policies that support balanced marketplace growth and preserve a sustainable revenue stream.", "date": "2026-10-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07399", "title_zh": "\u5728\u53cc\u8fb9\u5e02\u573a\u4e2d\u51fa\u552e\u7ebf\u7d22\u5bf9\u798f\u5229\u7684\u5f71\u54cd", "abstract_zh": "\u8fde\u63a5\u5ba2\u6237\u4e0e\u670d\u52a1\u63d0\u4f9b\u8005\u7684\u6570\u5b57\u5e73\u53f0\u901a\u5e38\u901a\u8fc7\u5411\u611f\u5174\u8da3\u7684\u63d0\u4f9b\u5546\u51fa\u552e\u5ba2\u6237\u7ebf\u7d22\u6765\u76c8\u5229\u3002\u4f8b\u5982\uff0cBark\u3001Google Local Services\u3001HomeAdvisor\u3001Modernize\u3001Porch \u548c Thumbtack \u7b49\u5e73\u53f0\u5747\u91c7\u7528\u6b64\u7c7b\u6a21\u5f0f\u3002\u672c\u6587\u6784\u5efa\u4e86\u4e00\u4e2a\u535a\u5f08\u8bba\u6a21\u578b\uff0c\u5206\u6790\u7ebf\u7d22\u5b9a\u4ef7\u5982\u4f55\u5f71\u54cd\u5ba2\u6237\u548c\u63d0\u4f9b\u5546\u7684\u798f\u5229\u3002\u5f53\u5e73\u53f0\u63d0\u9ad8\u67d0\u4e00\u5ba2\u6237\u7c7b\u578b\u6bcf\u6761\u7ebf\u7d22\u7684\u8d39\u7528\u65f6\uff0c\u8fd9\u4e9b\u5ba2\u6237\u5728\u83b7\u5f97\u76f8\u540c\u6570\u91cf\u63d0\u4f9b\u5546\u62a5\u4ef7\u7684\u6761\u4ef6\u4e0b\uff0c\u4f1a\u6536\u5230\u66f4\u4f4e\u7684\u62a5\u4ef7\u3002\u7136\u800c\uff0c\u5982\u679c\u8d39\u7528\u9ad8\u5230\u4e00\u5b9a\u7a0b\u5ea6\uff0c\u63d0\u4f9b\u5546\u5c06\u8d2d\u4e70\u66f4\u5c11\u7684\u6b64\u7c7b\u7ebf\u7d22\uff0c\u4ece\u800c\u51cf\u5c11\u62a5\u4ef7\u6570\u91cf\uff0c\u964d\u4f4e\u5ba2\u6237\u7684\u5269\u4f59\u6536\u76ca\u3002\u4e3a\u4e86\u6700\u5927\u5316\u793e\u4f1a\u798f\u5229\uff0c\u4e00\u4e2a\u7b80\u5355\u7684\u653f\u7b56\u2014\u2014\u4e3a\u6bcf\u79cd\u5ba2\u6237\u7c7b\u578b\u8bbe\u5b9a\u5e02\u573a\u5747\u8861\u7684\u6bcf\u6761\u7ebf\u7d22\u8d39\u7528\u2014\u2014\u53ef\u4ee5\u4fdd\u8bc1\u81f3\u5c11\u8fbe\u5230\u7b2c\u4e00\u6700\u4f18\u798f\u5229\u7684 [Formula: see text]\uff0c\u4ee5\u53ca\u81f3\u5c11\u8fbe\u5230\u6700\u4f18\u8d39\u7528\u4e0b\u798f\u5229\u7684 [Formula: see text]\u3002\u901a\u8fc7\u4e3a\u6bcf\u4e2a\u5b8c\u6210\u4efb\u52a1\u7684\u63d0\u4f9b\u5546\u63d0\u4f9b\u8865\u8d34\uff0c\u53ef\u4ee5\u5b9e\u73b0\u7b2c\u4e00\u6700\u4f18\u7ed3\u679c\uff0c\u4ece\u800c\u9632\u6b62\u90a3\u4e9b\u62e5\u6709\u66f4\u4f4e\u6210\u672c\u7ebf\u7d22\u6765\u6e90\u7684\u8d44\u6df1\u63d0\u4f9b\u5546\u9000\u51fa\u5e73\u53f0\u3002\u7406\u89e3\u8fd9\u4e9b\u798f\u5229\u6743\u8861\u6709\u52a9\u4e8e\u5e73\u53f0\u8bbe\u8ba1\u51fa\u652f\u6301\u5e02\u573a\u5747\u8861\u53d1\u5c55\u7684\u653f\u7b56\uff0c\u5e76\u7ef4\u6301\u53ef\u6301\u7eed\u7684\u6536\u5165\u6765\u6e90\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35800", "journal": "NBER", "title": "Inference for Regression with Clustered or Spatially Correlated Data I: Framework and Clustering", "authors": ["A. Colin Cameron", "Douglas L. Miller"], "author_details": [{"name": "A. Colin Cameron", "affiliations": []}, {"name": "Douglas L. Miller", "affiliations": []}], "abstract": "Many regression analyses use observations that are correlated within uncorrelated clusters and/or are correlated in distance or other spatial measure. Such data are often positively correlated. This reduces the information content of an additional observation compared to the default of independent observations. Consequently, failure to adjust standard errors for such correlation leads to confidence intervals that are too narrow, and to hypothesis tests that over reject. In this paper we first provide a general framework. We then focus on inference when observations are correlated within cluster and uncorrelated across clusters. We detail cluster-robust inference methods, particularly methods that provide improved finite-sample performance when there is not a large number of clusters. Such adjustments are often necessary. A companion paper, Cameron and Miller (2026), presents inference when correlation is spatially dampening in the distance between observations. The two papers are intended to provide a guide to empirical researchers.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35800", "title_zh": "\u5177\u6709\u805a\u7c7b\u6216\u7a7a\u95f4\u76f8\u5173\u6570\u636e\u7684\u56de\u5f52\u63a8\u65ad I\uff1a\u6846\u67b6\u4e0e\u805a\u7c7b", "abstract_zh": "\u8bb8\u591a\u56de\u5f52\u5206\u6790\u4f7f\u7528\u5728\u96c6\u7fa4\u5185\u90e8\u76f8\u5173\u800c\u96c6\u7fa4\u4e4b\u95f4\u4e0d\u76f8\u5173\u7684\u89c2\u6d4b\u503c\uff0c\u6216\u8005\u5728\u8ddd\u79bb\u6216\u5176\u4ed6\u7a7a\u95f4\u5ea6\u91cf\u4e0a\u76f8\u5173\u3002\u8fd9\u7c7b\u6570\u636e\u901a\u5e38\u5448\u6b63\u76f8\u5173\u3002\u8fd9\u4f7f\u5f97\u989d\u5916\u89c2\u6d4b\u503c\u7684\u4fe1\u606f\u542b\u91cf\u4f4e\u4e8e\u72ec\u7acb\u89c2\u6d4b\u503c\u7684\u9ed8\u8ba4\u60c5\u51b5\u3002\u56e0\u6b64\uff0c\u82e5\u4e0d\u8c03\u6574\u6807\u51c6\u8bef\u5dee\u4ee5\u53cd\u6620\u8fd9\u79cd\u76f8\u5173\u6027\uff0c\u4f1a\u5bfc\u81f4\u7f6e\u4fe1\u533a\u95f4\u8fc7\u7a84\uff0c\u4ee5\u53ca\u5047\u8bbe\u68c0\u9a8c\u8fc7\u5ea6\u62d2\u7edd\u3002\u672c\u6587\u9996\u5148\u63d0\u51fa\u4e00\u4e2a\u901a\u7528\u6846\u67b6\u3002\u968f\u540e\uff0c\u6211\u4eec\u96c6\u4e2d\u4e8e\u5f53\u89c2\u6d4b\u503c\u5728\u96c6\u7fa4\u5185\u90e8\u76f8\u5173\u800c\u96c6\u7fa4\u4e4b\u95f4\u4e0d\u76f8\u5173\u65f6\u7684\u63a8\u65ad\u95ee\u9898\u3002\u6211\u4eec\u8be6\u7ec6\u4ecb\u7ecd\u4e86\u805a\u7c7b\u7a33\u5065\u7684\u63a8\u65ad\u65b9\u6cd5\uff0c\u7279\u522b\u662f\u90a3\u4e9b\u5728\u96c6\u7fa4\u6570\u91cf\u4e0d\u591a\u65f6\u5177\u6709\u66f4\u597d\u5c0f\u6837\u672c\u6027\u80fd\u7684\u65b9\u6cd5\u3002\u8fd9\u7c7b\u8c03\u6574\u901a\u5e38\u90fd\u662f\u5fc5\u8981\u7684\u3002 companion paper, Cameron and Miller (2026)\uff0c\u5219\u8ba8\u8bba\u4e86\u5f53\u89c2\u6d4b\u503c\u4e4b\u95f4\u7684\u76f8\u5173\u6027\u968f\u8ddd\u79bb\u8870\u51cf\u65f6\u7684\u63a8\u65ad\u95ee\u9898\u3002\u8fd9\u4e24\u7bc7\u8bba\u6587\u65e8\u5728\u4e3a\u5b9e\u8bc1\u7814\u7a76\u4eba\u5458\u63d0\u4f9b\u6307\u5bfc\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35801", "journal": "NBER", "title": "Inference for Regression with Clustered or Spatially Correlated Data II: Spatial Correlation", "authors": ["A. Colin Cameron", "Douglas L. Miller"], "author_details": [{"name": "A. Colin Cameron", "affiliations": []}, {"name": "Douglas L. Miller", "affiliations": []}], "abstract": "This article presents inference for regression with data that are correlated across some measure of distance; most often geographic distance. Failure to appropriately adjust standard errors can lead to confidence intervals that are too narrow, and hypothesis tests that over-reject. If spatial correlation exists within region but not across regions then one can use cluster-robust inference methods presented in the companion paper, Cameron and Miller (2026). In this paper we focus on methods when spatial correlation is dampening in distance. Then the standard inference method is the spatial HAC of Conley (1999). This method does not work well when spatial persistence is high, and alternative inference methods are needed. Additionally it is important that regression models control for any spatial trends to avoid finding spurious correlation.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35801", "title_zh": "\u5177\u6709\u7a7a\u95f4\u76f8\u5173\u6027\u7684\u56de\u5f52\u63a8\u65ad II\uff1a\u7a7a\u95f4\u76f8\u5173\u6027", "abstract_zh": "\u672c\u6587\u63d0\u51fa\u4e86\u9488\u5bf9\u5b58\u5728\u8ddd\u79bb\u5ea6\u91cf\u4e0b\u76f8\u5173\u6027\u7684\u6570\u636e\uff08\u901a\u5e38\u4e3a\u5730\u7406\u8ddd\u79bb\uff09\u7684\u56de\u5f52\u63a8\u65ad\u65b9\u6cd5\u3002\u82e5\u672a\u9002\u5f53\u8c03\u6574\u6807\u51c6\u8bef\uff0c\u53ef\u80fd\u5bfc\u81f4\u7f6e\u4fe1\u533a\u95f4\u8fc7\u7a84\uff0c\u4ee5\u53ca\u5047\u8bbe\u68c0\u9a8c\u8fc7\u5ea6\u62d2\u7edd\u3002\u5f53\u533a\u57df\u5185\u5b58\u5728\u7a7a\u95f4\u76f8\u5173\u6027\u4f46\u533a\u57df\u95f4\u4e0d\u5b58\u5728\u65f6\uff0c\u53ef\u4ee5\u4f7f\u7528 companion paper\uff08Cameron \u548c Miller\uff0c2026\uff09\u4e2d\u63d0\u51fa\u7684\u805a\u7c7b\u7a33\u5065\u63a8\u65ad\u65b9\u6cd5\u3002\u672c\u6587\u5219\u805a\u7126\u4e8e\u7a7a\u95f4\u76f8\u5173\u6027\u968f\u8ddd\u79bb\u8870\u51cf\u7684\u60c5\u51b5\uff0c\u6b64\u65f6\u6807\u51c6\u63a8\u65ad\u65b9\u6cd5\u662f Conley\uff081999\uff09\u63d0\u51fa\u7684\u7a7a\u95f4\u5f02\u8d28\u6027\u6807\u51c6\u8bef\uff08HAC\uff09\u65b9\u6cd5\u3002\u7136\u800c\uff0c\u5f53\u7a7a\u95f4\u6301\u7eed\u6027\u8f83\u9ad8\u65f6\uff0c\u8be5\u65b9\u6cd5\u8868\u73b0\u4e0d\u4f73\uff0c\u9700\u8981\u91c7\u7528\u66ff\u4ee3\u7684\u63a8\u65ad\u65b9\u6cd5\u3002\u6b64\u5916\uff0c\u5fc5\u987b\u786e\u4fdd\u56de\u5f52\u6a21\u578b\u63a7\u5236\u4e86\u4efb\u4f55\u7a7a\u95f4\u8d8b\u52bf\uff0c\u4ee5\u907f\u514d\u53d1\u73b0\u865a\u5047\u76f8\u5173\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35833", "journal": "NBER", "title": "Crowding Out Temptation: Experimental Evidence on Savings and Health Behaviors in Kenya", "authors": ["Harsha Thirumurthy", "Elizabeth F. Bair", "Dean Yang", "Teniola I. Egbe", "Benard Ayieko", "Julius Wesonga", "Sue Napierala", "Connie Celum", "Mary E. Putt", "Carol S. Camlin", "Mark Ayallo"], "author_details": [{"name": "Harsha Thirumurthy", "affiliations": []}, {"name": "Elizabeth F. Bair", "affiliations": []}, {"name": "Dean Yang", "affiliations": []}, {"name": "Teniola I. Egbe", "affiliations": []}, {"name": "Benard Ayieko", "affiliations": []}, {"name": "Julius Wesonga", "affiliations": []}, {"name": "Sue Napierala", "affiliations": []}, {"name": "Connie Celum", "affiliations": []}, {"name": "Mary E. Putt", "affiliations": []}, {"name": "Carol S. Camlin", "affiliations": []}, {"name": "Mark Ayallo", "affiliations": []}], "abstract": "Alcohol use, transactional sex, and gambling carry significant health and economic consequences. We conducted a randomized controlled trial in Kenya to assess whether these behaviors could be altered with a savings intervention that provided lottery-based interest, goal-setting support, and savings reminders. Over 24 months, the intervention increased formal savings and assets, financed primarily by lower spending on alcohol, transactional sex, and gambling. It also reduced hazardous drinking by 26 percent and intimate partner violence by 15 percent. HIV/STI incidence declined by 8 percent, though this was not statistically significant. Savings interventions can simultaneously boost financial security and change health behavior.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35833", "title_zh": "\u8bf1\u60d1\u7684\u6324\u51fa\uff1a\u80af\u5c3c\u4e9a\u5173\u4e8e\u50a8\u84c4\u4e0e\u5065\u5eb7\u884c\u4e3a\u5b9e\u9a8c\u8bc1\u636e", "abstract_zh": "\u9152\u7cbe\u6d88\u8d39\u3001\u4ea4\u6613\u6027\u6027\u884c\u4e3a\u548c\u8d4c\u535a\u5177\u6709\u663e\u8457\u7684\u5065\u5eb7\u548c\u7ecf\u6d4e\u540e\u679c\u3002\u6211\u4eec\u5728\u80af\u5c3c\u4e9a\u5f00\u5c55\u4e86\u4e00\u9879\u968f\u673a\u5bf9\u7167\u8bd5\u9a8c\uff0c\u8bc4\u4f30\u4e00\u79cd\u50a8\u84c4\u5e72\u9884\u63aa\u65bd\uff08\u63d0\u4f9b\u5f69\u7968\u5f0f\u5229\u606f\u3001\u76ee\u6807\u8bbe\u5b9a\u652f\u6301\u548c\u50a8\u84c4\u63d0\u9192\uff09\u662f\u5426\u80fd\u591f\u6539\u53d8\u8fd9\u4e9b\u884c\u4e3a\u3002\u572824\u4e2a\u6708\u5185\uff0c\u5e72\u9884\u7ec4\u7684\u6b63\u5f0f\u50a8\u84c4\u548c\u8d44\u4ea7\u663e\u8457\u589e\u52a0\uff0c\u4e3b\u8981\u6765\u6e90\u4e8e\u5bf9\u9152\u7cbe\u3001\u4ea4\u6613\u6027\u6027\u884c\u4e3a\u548c\u8d4c\u535a\u652f\u51fa\u7684\u51cf\u5c11\u3002\u540c\u65f6\uff0c\u5371\u9669\u996e\u9152\u884c\u4e3a\u51cf\u5c11\u4e8626%\uff0c\u4eb2\u5bc6\u4f34\u4fa3\u66b4\u529b\u51cf\u5c11\u4e8615%\u3002HIV/STI\u7684\u53d1\u75c5\u7387\u4e0b\u964d\u4e868%\uff0c\u4f46\u8fd9\u4e00\u53d8\u5316\u672a\u8fbe\u5230\u7edf\u8ba1\u5b66\u663e\u8457\u6027\u3002\u50a8\u84c4\u5e72\u9884\u63aa\u65bd\u4e0d\u4ec5\u80fd\u63d0\u5347\u8d22\u52a1\u5b89\u5168\uff0c\u8fd8\u80fd\u6539\u5584\u5065\u5eb7\u884c\u4e3a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35834", "journal": "NBER", "title": "A Framework for Integrating Climate Goals into Trade Agreements", "authors": ["Farid Farrokhi", "Ahmad Lashkaripour", "Homa Taheri"], "author_details": [{"name": "Farid Farrokhi", "affiliations": []}, {"name": "Ahmad Lashkaripour", "affiliations": []}, {"name": "Homa Taheri", "affiliations": []}], "abstract": "A critical tension in global governance is that trade agreements have evolved largely in isolation from climate policy. This paper shows that the two domains generate systematic cross-externalities: larger gains from trade are associated with greater climate externalities imposed on partners, while linking carbon taxes to trade agreements produces distributive externalities that undermine the balance of trade concessions. To address this tension, we present a framework to integrate harmonized carbon pricing into the WTO subject to institutional and political-feasibility constraints. We explore two linkage designs. The first is a centralized Climate Fund, where all members apply a common demand-side carbon tax and contribute a portion of the revenues to the fund, capped by fiscal constraints. The Fund then reallocates these contributions to balance the tax burden across countries, subject to informational constraints. Quantitative analysis shows that even a simple fund allocation rule can sustain a carbon price of $138 per ton of CO2, reducing global emissions by 54%. The main binding constraint is informational: knowing the precise incidence of the carbon tax across countries ex ante would raise the feasible price to $265. The second is a decentralized design without transfers. Each member meets a carbon tax revenue floor but retains full discretion over its mix of demand-side and supply-side taxes. Energy exporters choose supply-side taxes while energy importers opt for demand-side taxes. These choices organically balance the tax burden and yield a 47% reduction in global emissions, almost rivaling the centralized Climate Fund.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35834", "title_zh": "\u5c06\u6c14\u5019\u76ee\u6807\u878d\u5165\u8d38\u6613\u534f\u5b9a\u7684\u6846\u67b6", "abstract_zh": "\u5168\u7403\u6cbb\u7406\u4e2d\u7684\u4e00\u4e2a\u5173\u952e\u77db\u76fe\u662f\uff0c\u8d38\u6613\u534f\u5b9a\u7684\u53d1\u5c55\u957f\u671f\u8131\u79bb\u4e86\u6c14\u5019\u653f\u7b56\u3002\u672c\u6587\u8868\u660e\uff0c\u8fd9\u4e24\u4e2a\u9886\u57df\u4f1a\u4ea7\u751f\u7cfb\u7edf\u6027\u7684\u4ea4\u53c9\u5916\u90e8\u6027\uff1a\u8d38\u6613\u6536\u76ca\u8d8a\u5927\uff0c\u5bf9\u5408\u4f5c\u4f19\u4f34\u9020\u6210\u7684\u6c14\u5019\u5916\u90e8\u6027\u4e5f\u8d8a\u9ad8\uff1b\u800c\u5c06\u78b3\u7a0e\u4e0e\u8d38\u6613\u534f\u5b9a\u6302\u94a9\uff0c\u5219\u4f1a\u4ea7\u751f\u5206\u914d\u6027\u5916\u90e8\u6027\uff0c\u7834\u574f\u8d38\u6613\u8ba9\u6b65\u7684\u5e73\u8861\u3002\u4e3a\u89e3\u51b3\u8fd9\u4e00\u77db\u76fe\uff0c\u672c\u6587\u63d0\u51fa\u4e00\u4e2a\u5c06\u7edf\u4e00\u7684\u78b3\u5b9a\u4ef7\u7eb3\u5165\u4e16\u754c\u8d38\u6613\u7ec4\u7ec7\uff08WTO\uff09\u7684\u6846\u67b6\uff0c\u8be5\u6846\u67b6\u53d7\u5230\u5236\u5ea6\u548c\u653f\u6cbb\u53ef\u884c\u6027\u7ea6\u675f\u3002\u6211\u4eec\u63a2\u8ba8\u4e86\u4e24\u79cd\u8054\u52a8\u8bbe\u8ba1\u3002\u7b2c\u4e00\u79cd\u662f\u96c6\u4e2d\u5f0f\u6c14\u5019\u57fa\u91d1\uff0c\u6240\u6709\u6210\u5458\u5b9e\u65bd\u7edf\u4e00\u7684\u9700\u6c42\u4fa7\u78b3\u7a0e\uff0c\u5e76\u5c06\u90e8\u5206\u7a0e\u6536\u6536\u5165\u8d21\u732e\u7ed9\u57fa\u91d1\uff0c\u6536\u5165\u4e0a\u9650\u53d7\u8d22\u653f\u7ea6\u675f\u9650\u5236\u3002\u57fa\u91d1\u968f\u540e\u5728\u4fe1\u606f\u7ea6\u675f\u4e0b\u91cd\u65b0\u5206\u914d\u8fd9\u4e9b\u8d44\u91d1\uff0c\u4ee5\u5e73\u8861\u5404\u56fd\u7684\u7a0e\u6536\u8d1f\u62c5\u3002\u5b9a\u91cf\u5206\u6790\u663e\u793a\uff0c\u5373\u4f7f\u91c7\u7528\u4e00\u4e2a\u7b80\u5355\u7684\u57fa\u91d1\u5206\u914d\u89c4\u5219\uff0c\u4e5f\u80fd\u7ef4\u6301\u6bcf\u5428\u4e8c\u6c27\u5316\u78b3138\u7f8e\u5143\u7684\u78b3\u4ef7\uff0c\u4f7f\u5168\u7403\u51cf\u639254%\u3002\u4e3b\u8981\u7684\u7ea6\u675f\u662f\u4fe1\u606f\u6027\u95ee\u9898\uff1a\u4e8b\u524d\u77e5\u6653\u78b3\u7a0e\u5728\u5404\u56fd\u7684\u5177\u4f53\u5f71\u54cd\uff0c\u4f1a\u4f7f\u53ef\u884c\u78b3\u4ef7\u63d0\u5347\u81f3\u6bcf\u5428\u4e8c\u6c27\u5316\u78b3265\u7f8e\u5143\u3002\u7b2c\u4e8c\u79cd\u662f\u53bb\u4e2d\u5fc3\u5316\u8bbe\u8ba1\uff0c\u4e0d\u6d89\u53ca\u8d44\u91d1\u8f6c\u79fb\u3002\u6bcf\u4e2a\u6210\u5458\u9700\u6ee1\u8db3\u6700\u4f4e\u78b3\u7a0e\u6536\u5165\u95e8\u69db\uff0c\u4f46\u53ef\u81ea\u4e3b\u51b3\u5b9a\u9700\u6c42\u4fa7\u548c\u4f9b\u7ed9\u4fa7\u7a0e\u6536\u7684\u7ec4\u5408\u3002\u80fd\u6e90\u51fa\u53e3\u56fd\u9009\u62e9\u4f9b\u7ed9\u4fa7\u7a0e\u6536\uff0c\u800c\u80fd\u6e90\u8fdb\u53e3\u56fd\u5219\u9009\u62e9\u9700\u6c42\u4fa7\u7a0e\u6536\u3002\u8fd9\u4e9b\u9009\u62e9\u81ea\u7136\u5730\u5e73\u8861\u4e86\u7a0e\u6536\u8d1f\u62c5\uff0c\u5b9e\u73b0\u4e86\u8fd147%\u7684\u5168\u7403\u51cf\u6392\uff0c\u51e0\u4e4e\u4e0e\u96c6\u4e2d\u5f0f\u6c14\u5019\u57fa\u91d1\u76f8\u5f53\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35835", "journal": "NBER", "title": "Does Food Assistance Drive Spending on Sugary Foods? Evidence from the Pandemic Electronic Benefit Transfer Program", "authors": ["Georgina Cisneros", "Brandyn F. Churchill"], "author_details": [{"name": "Georgina Cisneros", "affiliations": []}, {"name": "Brandyn F. Churchill", "affiliations": []}], "abstract": "We provide evidence on the extent to which food assistance affects spending on sugary items by studying the Pandemic Electronic Benefit Transfer (P-EBT) program, which provided funds to families of children who lost access to free and reduced-price school meals due to COVID-19 pandemic school closures. Leveraging state-level variation in the timing of P-EBT disbursements using a stacked difference-in-differences identification strategy with NielsenIQ Consumer Panel data, we find that P-EBT disbursement was associated with a 16-percent increase in weekly spending on sugary items among SNAP-eligible households with school-aged children. Notably, this increase exceeded the percentage increase in overall food spending for this group, suggesting that SNAP-eligible households with school-aged children allocated a disproportionately large share of their P-EBT-driven purchases toward sugary items relative to their pre-period baseline. We do not detect changes among households unlikely to have received P-EBT benefits or in placebo disbursement years.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35835", "title_zh": "\u98df\u54c1\u63f4\u52a9\u662f\u5426\u63a8\u52a8\u5bf9\u542b\u7cd6\u98df\u54c1\u7684\u6d88\u8d39\uff1f\u6765\u81ea\u75ab\u60c5\u7535\u5b50\u798f\u5229\u8f6c\u79fb\u8ba1\u5212\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u901a\u8fc7\u7814\u7a76\u75ab\u60c5\u7535\u5b50\u798f\u5229\u8f6c\u79fb\uff08P-EBT\uff09\u8ba1\u5212\uff0c\u63a2\u8ba8\u4e86\u98df\u54c1\u63f4\u52a9\u5bf9\u542b\u7cd6\u98df\u54c1\u6d88\u8d39\u7684\u5f71\u54cd\u3002\u8be5\u8ba1\u5212\u4e3a\u56e0\u65b0\u51a0\u75ab\u60c5\u5b66\u6821\u5173\u95ed\u800c\u5931\u53bb\u514d\u8d39\u548c\u4f4e\u4ef7\u6821\u9910\u8d44\u683c\u7684\u5bb6\u5ead\u513f\u7ae5\u63d0\u4f9b\u8d44\u91d1\u652f\u6301\u3002\u5229\u7528\u5404\u5ddeP-EBT\u53d1\u653e\u65f6\u95f4\u7684\u5dee\u5f02\uff0c\u5e76\u7ed3\u5408\u5c3c\u5c14\u68eeIQ\u6d88\u8d39\u8005\u9762\u677f\u6570\u636e\uff0c\u91c7\u7528\u5806\u53e0\u53cc\u91cd\u5dee\u5206\u8bc6\u522b\u7b56\u7565\uff0c\u6211\u4eec\u53d1\u73b0P-EBT\u53d1\u653e\u4e0e\u6709\u5b66\u9f84\u513f\u7ae5\u4e14\u7b26\u5408SNAP\u8d44\u683c\u7684\u5bb6\u5ead\u6bcf\u5468\u5bf9\u542b\u7cd6\u98df\u54c1\u7684\u652f\u51fa\u589e\u52a0\u4e8616%\u3002\u503c\u5f97\u6ce8\u610f\u7684\u662f\uff0c\u8fd9\u4e00\u589e\u5e45\u8d85\u8fc7\u4e86\u8be5\u7fa4\u4f53\u6574\u4f53\u98df\u54c1\u652f\u51fa\u7684\u589e\u5e45\uff0c\u8868\u660e\u8fd9\u4e9b\u5bb6\u5ead\u5728P-EBT\u5e26\u6765\u7684\u652f\u51fa\u4e2d\uff0c\u5c06\u8f83\u5927\u6bd4\u4f8b\u5206\u914d\u7ed9\u4e86\u542b\u7cd6\u98df\u54c1\uff0c\u76f8\u5bf9\u4e8e\u5176\u524d\u671f\u57fa\u51c6\u6c34\u5e73\u3002\u6211\u4eec\u672a\u5728\u4e0d\u592a\u53ef\u80fd\u83b7\u5f97P-EBT\u798f\u5229\u7684\u5bb6\u5ead\u6216\u5728\u5b89\u6170\u5242\u53d1\u653e\u5e74\u4efd\u4e2d\u68c0\u6d4b\u5230\u6b64\u7c7b\u53d8\u5316\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35836", "journal": "NBER", "title": "Consumption, Savings, and Earnings Responses to Financial Windfalls", "authors": ["Rajashri Chakrabarti", "Philippe d'Astous", "Kory Kroft", "Sheisha Kulkarni", "Vyacheslav Mikhed", "Matthew J. Notowidigdo", "Sahil Raina", "Barry Scholnick"], "author_details": [{"name": "Rajashri Chakrabarti", "affiliations": []}, {"name": "Philippe d'Astous", "affiliations": []}, {"name": "Kory Kroft", "affiliations": []}, {"name": "Sheisha Kulkarni", "affiliations": []}, {"name": "Vyacheslav Mikhed", "affiliations": []}, {"name": "Matthew J. Notowidigdo", "affiliations": []}, {"name": "Sahil Raina", "affiliations": []}, {"name": "Barry Scholnick", "affiliations": []}], "abstract": "We estimate the causal effects of a financial windfall on consumption, savings, and wage earnings using linked administrative data on a large sample of Canadian lottery winners. Using separate linkages of lottery winners to income tax records and credit bureau data, we estimate how lottery winnings affect consumption measured through credit card spending, savings through financial asset accumulation and debt repayment, and wage earnings from tax records. We then examine how these responses vary across the income distribution. We find that high-income individuals allocated a larger share of lottery winnings to savings and leisure, while low-income individuals spent a larger share on consumption. We illustrate the policy relevance of these heterogeneous responses through three applications: designing fiscal stimulus programs, evaluating a Universal Basic Income (UBI), and determining optimal top tax rates on wage earnings and savings.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35836", "title_zh": "\u6d88\u8d39\u3001\u50a8\u84c4\u548c\u6536\u5165\u5bf9\u91d1\u878d\u610f\u5916\u4e4b\u8d22\u7684\u53cd\u5e94", "abstract_zh": "\u6211\u4eec\u5229\u7528\u52a0\u62ff\u5927\u5927\u91cf\u5f69\u7968\u4e2d\u5956\u8005\u94fe\u63a5\u7684\u884c\u653f\u6570\u636e\uff0c\u4f30\u8ba1\u4e86\u91d1\u878d\u610f\u5916\u4e4b\u8d22\u5bf9\u6d88\u8d39\u3001\u50a8\u84c4\u548c\u5de5\u8d44\u6536\u5165\u7684\u56e0\u679c\u6548\u5e94\u3002\u901a\u8fc7\u5c06\u5f69\u7968\u4e2d\u5956\u8005\u4e0e\u6536\u5165\u7a0e\u8bb0\u5f55\u548c\u4fe1\u7528\u5c40\u6570\u636e\u5206\u522b\u8fdb\u884c\u5173\u8054\uff0c\u6211\u4eec\u5206\u6790\u4e86\u5f69\u7968\u4e2d\u5956\u5982\u4f55\u5f71\u54cd\u901a\u8fc7\u4fe1\u7528\u5361\u652f\u51fa\u8861\u91cf\u7684\u6d88\u8d39\u3001\u901a\u8fc7\u91d1\u878d\u8d44\u4ea7\u79ef\u7d2f\u548c\u503a\u52a1\u507f\u8fd8\u8861\u91cf\u7684\u50a8\u84c4\uff0c\u4ee5\u53ca\u901a\u8fc7\u7a0e\u6536\u8bb0\u5f55\u8861\u91cf\u7684\u5de5\u8d44\u6536\u5165\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u8003\u5bdf\u4e86\u8fd9\u4e9b\u53cd\u5e94\u5728\u4e0d\u540c\u6536\u5165\u7fa4\u4f53\u4e2d\u7684\u5dee\u5f02\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u9ad8\u6536\u5165\u4eba\u7fa4\u5c06\u66f4\u591a\u5f69\u7968\u5956\u91d1\u7528\u4e8e\u50a8\u84c4\u548c\u4f11\u95f2\uff0c\u800c\u4f4e\u6536\u5165\u4eba\u7fa4\u5219\u5c06\u66f4\u591a\u7528\u4e8e\u6d88\u8d39\u3002\u6211\u4eec\u901a\u8fc7\u4e09\u4e2a\u5e94\u7528\u573a\u666f\u5c55\u793a\u4e86\u8fd9\u4e9b\u5f02\u8d28\u6027\u53cd\u5e94\u7684\u653f\u7b56\u610f\u4e49\uff1a\u8bbe\u8ba1\u8d22\u653f\u523a\u6fc0\u8ba1\u5212\u3001\u8bc4\u4f30\u5168\u6c11\u57fa\u672c\u6536\u5165\uff08UBI\uff09\u653f\u7b56\uff0c\u4ee5\u53ca\u786e\u5b9a\u5bf9\u5de5\u8d44\u6536\u5165\u548c\u50a8\u84c4\u5f81\u6536\u6700\u9ad8\u7a0e\u7387\u7684\u6700\u4f18\u6c34\u5e73\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35837", "journal": "NBER", "title": "Approximating the Equilibrium Effects of Informed School Choice", "authors": ["Claudia Allende", "Francisco Gallego", "Christopher Neilson"], "author_details": [{"name": "Claudia Allende", "affiliations": []}, {"name": "Francisco Gallego", "affiliations": []}, {"name": "Christopher Neilson", "affiliations": []}], "abstract": "We study how information about school quality affects families\u2019 choices and how scaling up the intervention changes its impact. In a randomized trial in Chile, we offer families a short video and a personalized school report card before they enroll their children. Treated families choose schools with higher test scores and value added. Among families reached before enrollment, treated children score about 0.2 standard deviations higher in fourth grade, with positive but less precise estimates on later assessments. We embed the experimentally identified demand shift in a structural model of school choice and competition to study equilibrium effects at scale. Capacity constraints and centralized assignment attenuate the demand-side gains, but the same shift in demand strengthens schools\u2019 incentives to improve quality, and the supply response roughly offsets the congestion effect. More generally, equilibrium scaling can alter experimental effects in either direction because congestion and endogenous quality responses work against each other. We use the model to guide the design of a follow-up cluster-randomized experiment, focusing on the tradeoff between precision and contamination from equilibrium spillovers.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35837", "title_zh": "\u4fe1\u606f\u5bf9\u5b66\u6821\u9009\u62e9\u5747\u8861\u6548\u5e94\u7684\u8fd1\u4f3c\u5206\u6790", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5173\u4e8e\u5b66\u6821\u8d28\u91cf\u7684\u4fe1\u606f\u5982\u4f55\u5f71\u54cd\u5bb6\u5ead\u7684\u9009\u62e9\uff0c\u4ee5\u53ca\u6269\u5927\u5e72\u9884\u63aa\u65bd\u5982\u4f55\u6539\u53d8\u5176\u5f71\u54cd\u3002\u5728\u667a\u5229\u7684\u4e00\u9879\u968f\u673a\u8bd5\u9a8c\u4e2d\uff0c\u6211\u4eec\u5411\u5bb6\u5ead\u63d0\u4f9b\u4e86\u7b80\u77ed\u7684\u89c6\u9891\u548c\u4e2a\u6027\u5316\u7684\u5b66\u6821\u62a5\u544a\u5361\uff0c\u4ee5\u4fbf\u4ed6\u4eec\u5728\u5b69\u5b50\u5165\u5b66\u524d\u4e86\u89e3\u60c5\u51b5\u3002\u63a5\u53d7\u5e72\u9884\u7684\u5bb6\u5ead\u9009\u62e9\u7684\u5b66\u6821\u6d4b\u8bd5\u6210\u7ee9\u548c\u589e\u503c\u503c\u66f4\u9ad8\u3002\u5728\u5165\u5b66\u524d\u88ab\u8986\u76d6\u7684\u5bb6\u5ead\u4e2d\uff0c\u63a5\u53d7\u5e72\u9884\u7684\u5b69\u5b50\u56db\u5e74\u7ea7\u6210\u7ee9\u5e73\u5747\u9ad8\u51fa0.2\u4e2a\u6807\u51c6\u5dee\uff0c\u540e\u7eed\u8bc4\u4f30\u4e2d\u867d\u6709\u6b63\u5411\u4f46\u7cbe\u5ea6\u8f83\u4f4e\u7684\u4f30\u8ba1\u3002\u6211\u4eec\u5c06\u5b9e\u9a8c\u8bc6\u522b\u51fa\u7684\u9700\u6c42\u53d8\u5316\u5d4c\u5165\u5230\u5b66\u6821\u9009\u62e9\u548c\u7ade\u4e89\u7684\u7ed3\u6784\u6a21\u578b\u4e2d\uff0c\u4ee5\u7814\u7a76\u5728\u66f4\u5927\u89c4\u6a21\u4e0b\u7684\u5747\u8861\u6548\u5e94\u3002\u5bb9\u91cf\u9650\u5236\u548c\u96c6\u4e2d\u5206\u914d\u524a\u5f31\u4e86\u9700\u6c42\u4fa7\u7684\u6536\u76ca\uff0c\u4f46\u9700\u6c42\u4fa7\u7684\u8fd9\u79cd\u53d8\u5316\u589e\u5f3a\u4e86\u5b66\u6821\u63d0\u5347\u8d28\u91cf\u7684\u6fc0\u52b1\uff0c\u800c\u4f9b\u5e94\u7aef\u7684\u54cd\u5e94\u5927\u81f4\u62b5\u6d88\u4e86\u62e5\u5835\u6548\u5e94\u3002\u66f4\u4e00\u822c\u5730\uff0c\u5747\u8861\u89c4\u6a21\u6269\u5927\u53ef\u80fd\u4ee5\u76f8\u53cd\u65b9\u5411\u6539\u53d8\u5b9e\u9a8c\u6548\u5e94\uff0c\u56e0\u4e3a\u62e5\u5835\u6548\u5e94\u548c\u5185\u751f\u8d28\u91cf\u54cd\u5e94\u76f8\u4e92\u62b5\u6d88\u3002\u6211\u4eec\u5229\u7528\u8be5\u6a21\u578b\u6307\u5bfc\u540e\u7eed\u96c6\u7fa4\u968f\u673a\u8bd5\u9a8c\u7684\u8bbe\u8ba1\uff0c\u91cd\u70b9\u5173\u6ce8\u7cbe\u5ea6\u4e0e\u5747\u8861\u6ea2\u51fa\u6548\u5e94\u6c61\u67d3\u4e4b\u95f4\u7684\u6743\u8861\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35838", "journal": "NBER", "title": "When Does Bad News Stick? Topic-Level Asymmetry in Narrative Dynamics", "authors": ["Isha Agarwal", "Wentong Chen", "Eswar S. Prasad"], "author_details": [{"name": "Isha Agarwal", "affiliations": []}, {"name": "Wentong Chen", "affiliations": []}, {"name": "Eswar S. Prasad", "affiliations": []}], "abstract": "When does bad news stick? This paper shows that the persistence of media sentiment depends not only on whether news is good or bad, but also on what the news is about. Using the complete Wall Street Journal archive from 1990 to 2025, we construct monthly positive and negative sentiment indices for twelve economic topics and estimate topic-specific sentiment dynamics. Bad-news innovations generate larger cumulative responses than positive-sentiment innovations in every topic, indicating that negativity asymmetry is a broad feature of media sentiment. But the size of this asymmetry varies sharply across topics. The bad-minus-positive persistence gap is largest in security and human rights, firms and corporate strategy, health and public safety, and real estate and financial stability. Bad-news persistence is also sizable in data-rich topics such as financial markets, real estate, and corporate news, suggesting that frequent information arrival does not necessarily lead narratives to revert quickly. These findings show that aggregate sentiment indices mask substantial topic-level heterogeneity in the asymmetric dynamics of narratives, with potential implications for how persistent negative sentiment shapes expectations, asset prices, and real economic outcomes.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35838", "title_zh": "\u574f\u6d88\u606f\u4f55\u65f6\u4f1a\u6301\u7eed\uff1f\u53d9\u4e8b\u52a8\u6001\u4e2d\u7684\u4e3b\u9898\u5c42\u9762\u4e0d\u5bf9\u79f0\u6027", "abstract_zh": "\u574f\u6d88\u606f\u4f55\u65f6\u4f1a\u6301\u7eed\uff1f\u672c\u6587\u8868\u660e\uff0c\u5a92\u4f53\u60c5\u7eea\u7684\u6301\u7eed\u6027\u4e0d\u4ec5\u53d6\u51b3\u4e8e\u65b0\u95fb\u662f\u597d\u662f\u574f\uff0c\u8fd8\u53d6\u51b3\u4e8e\u65b0\u95fb\u6d89\u53ca\u7684\u4e3b\u9898\u3002\u5229\u75281990\u5e74\u81f32025\u5e74\u5b8c\u6574\u7684\u300a\u534e\u5c14\u8857\u65e5\u62a5\u300b\u6863\u6848\uff0c\u6211\u4eec\u4e3a\u5341\u4e8c\u4e2a\u7ecf\u6d4e\u4e3b\u9898\u6784\u5efa\u4e86\u6bcf\u6708\u7684\u6b63\u9762\u548c\u8d1f\u9762\u60c5\u7eea\u6307\u6570\uff0c\u5e76\u4f30\u8ba1\u4e86\u5404\u4e3b\u9898\u7684\u60c5\u7eea\u52a8\u6001\u3002\u5728\u6240\u6709\u4e3b\u9898\u4e2d\uff0c\u8d1f\u9762\u65b0\u95fb\u7684\u521b\u65b0\u5f15\u53d1\u7684\u7d2f\u8ba1\u53cd\u5e94\u5747\u5927\u4e8e\u6b63\u9762\u65b0\u95fb\u521b\u65b0\uff0c\u8868\u660e\u8d1f\u9762\u60c5\u7eea\u4e0d\u5bf9\u79f0\u662f\u5a92\u4f53\u60c5\u7eea\u7684\u4e00\u4e2a\u666e\u904d\u7279\u5f81\u3002\u4f46\u8fd9\u79cd\u4e0d\u5bf9\u79f0\u7684\u7a0b\u5ea6\u5728\u4e0d\u540c\u4e3b\u9898\u95f4\u5dee\u5f02\u663e\u8457\u3002\u8d1f\u9762\u51cf\u6b63\u9762\u7684\u6301\u7eed\u6027\u5dee\u8ddd\u5728\u5b89\u5168\u4e0e\u4eba\u6743\u3001\u4f01\u4e1a\u4e0e\u516c\u53f8\u6218\u7565\u3001\u5065\u5eb7\u4e0e\u516c\u5171\u5b89\u5168\u3001\u623f\u5730\u4ea7\u4e0e\u91d1\u878d\u7a33\u5b9a\u7b49\u4e3b\u9898\u4e2d\u6700\u5927\u3002\u5728\u4fe1\u606f\u4e30\u5bcc\u7684\u4e3b\u9898\u5982\u91d1\u878d\u5e02\u573a\u3001\u623f\u5730\u4ea7\u548c\u4f01\u4e1a\u65b0\u95fb\u4e2d\uff0c\u8d1f\u9762\u60c5\u7eea\u7684\u6301\u7eed\u6027\u4e5f\u8f83\u4e3a\u663e\u8457\uff0c\u8fd9\u8868\u660e\u9891\u7e41\u7684\u4fe1\u606f\u5230\u8fbe\u5e76\u4e0d\u5fc5\u7136\u5bfc\u81f4\u53d9\u4e8b\u8fc5\u901f\u9006\u8f6c\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u603b\u4f53\u60c5\u7eea\u6307\u6570\u63a9\u76d6\u4e86\u53d9\u4e8b\u52a8\u6001\u4e2d\u5404\u4e3b\u9898\u5c42\u9762\u663e\u8457\u7684\u4e0d\u5bf9\u79f0\u6027\uff0c\u53ef\u80fd\u5bf9\u6301\u7eed\u7684\u8d1f\u9762\u60c5\u7eea\u5982\u4f55\u5f71\u54cd\u9884\u671f\u3001\u8d44\u4ea7\u4ef7\u683c\u548c\u5b9e\u9645\u7ecf\u6d4e\u7ed3\u679c\u4ea7\u751f\u91cd\u8981\u542f\u793a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.3386/w35839", "journal": "NBER", "title": "Large Language Models as Voting Mechanisms", "authors": ["Ra\u0161a Karapand\u017ea", "Yaw Nyarko"], "author_details": [{"name": "Ra\u0161a Karapand\u017ea", "affiliations": []}, {"name": "Yaw Nyarko", "affiliations": []}], "abstract": "Large language models (LLMs) increasingly provide economic and financial advice. We develop a microeconomic framework for understanding this role. We prove that an LLM acts like a voting rule: each input text is an election, possible continuations are candidates, and output probabilities are vote shares derived from the training corpus. Such rules can generate Condorcet cycles, implying intransitive pairwise recommendations and potential money-pump exploitation. Using ChatGPT-4o, we identify millions of cycles in pairwise investment choices among S&P 100 firms. Our theorems establish the voting interpretation on the training data and support its use off-sample. We also show that correcting cycles ex post is generally infeasible. Finally, temperature changes the voting rule: at T = 1, outputs are sampled in proportion to vote shares; lower temperatures favor the plurality winner, whereas higher temperatures flatten probabilities toward uniformity.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35839", "title_zh": "\u5927\u578b\u8bed\u8a00\u6a21\u578b\u4f5c\u4e3a\u6295\u7968\u673a\u5236", "abstract_zh": "\u5927\u578b\u8bed\u8a00\u6a21\u578b\uff08LLMs\uff09\u6b63\u5728\u8d8a\u6765\u8d8a\u591a\u5730\u63d0\u4f9b\u7ecf\u6d4e\u548c\u91d1\u878d\u5efa\u8bae\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5fae\u89c2\u7ecf\u6d4e\u6846\u67b6\u6765\u7406\u89e3\u8fd9\u4e00\u89d2\u8272\u3002\u6211\u4eec\u8bc1\u660e\uff0cLLM\u7684\u4f5c\u7528\u7c7b\u4f3c\u4e8e\u4e00\u79cd\u6295\u7968\u89c4\u5219\uff1a\u6bcf\u4e2a\u8f93\u5165\u6587\u672c\u662f\u4e00\u6b21\u9009\u4e3e\uff0c\u53ef\u80fd\u7684\u5ef6\u7eed\u662f\u5019\u9009\u4eba\uff0c\u8f93\u51fa\u6982\u7387\u5219\u662f\u4ece\u8bad\u7ec3\u8bed\u6599\u5e93\u4e2d\u63a8\u5bfc\u51fa\u7684\u9009\u7968\u4efd\u989d\u3002\u6b64\u7c7b\u89c4\u5219\u53ef\u80fd\u4ea7\u751f\u5eb7\u591a\u5c14\u5faa\u73af\uff0c\u610f\u5473\u7740\u4e0d\u4e00\u81f4\u7684\u6210\u5bf9\u63a8\u8350\uff0c\u5e76\u53ef\u80fd\u5bfc\u81f4\u5957\u5229\u884c\u4e3a\u3002\u5229\u7528ChatGPT-4o\uff0c\u6211\u4eec\u53d1\u73b0\u4e86\u5728\u6807\u51c6\u666e\u5c14100\u5bb6\u516c\u53f8\u4e4b\u95f4\u6210\u5bf9\u6295\u8d44\u9009\u62e9\u4e2d\u7684\u6570\u767e\u4e07\u4e2a\u5faa\u73af\u3002\u6211\u4eec\u7684\u5b9a\u7406\u5728\u8bad\u7ec3\u6570\u636e\u4e0a\u786e\u7acb\u4e86\u6295\u7968\u89e3\u91ca\uff0c\u5e76\u652f\u6301\u5176\u5728\u6837\u672c\u5916\u5e94\u7528\u3002\u6211\u4eec\u8fd8\u8868\u660e\uff0c\u4e8b\u540e\u7ea0\u6b63\u8fd9\u4e9b\u5faa\u73af\u901a\u5e38\u662f\u4e0d\u53ef\u884c\u7684\u3002\u6700\u540e\uff0c\u6e29\u5ea6\u53c2\u6570\u6539\u53d8\u4e86\u6295\u7968\u89c4\u5219\uff1a\u5f53\u6e29\u5ea6T=1\u65f6\uff0c\u8f93\u51fa\u6309\u9009\u7968\u4efd\u989d\u6bd4\u4f8b\u91c7\u6837\uff1b\u8f83\u4f4e\u7684\u6e29\u5ea6\u503e\u5411\u4e8e\u9009\u62e9\u591a\u6570\u7968\u83b7\u80dc\u8005\uff0c\u800c\u8f83\u9ad8\u7684\u6e29\u5ea6\u5219\u4f7f\u6982\u7387\u8d8b\u4e8e\u5747\u5300\u5206\u5e03\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790", "AI"]}, {"doi": "10.3386/w35840", "journal": "NBER", "title": "Asymmetric Reversals", "authors": ["Federico Baldi-Lanfranchi", "Pierre Collin-Dufresne", "Kent D. Daniel"], "author_details": [{"name": "Federico Baldi-Lanfranchi", "affiliations": []}, {"name": "Pierre Collin-Dufresne", "affiliations": []}, {"name": "Kent D. Daniel", "affiliations": []}], "abstract": "Short-term return reversal is one of the most robust asset-pricing anomalies, and is commonly linked to liquidity provision. We decompose individual firm stock returns into two distinct components: SYS, the component of returns that can be linked to systematic risk and public information releases; and an orthogonal residual RES. The RES component reverses, while the SYS component exhibits continuation. Moreover, the residual reversals are highly asymmetric: positive residual shocks reverse much more slowly than negative shocks. A return factor based on asymmetric idiosyncratic reversal subsumes the idiosyncratic volatility factor and a broad set of other short-horizon anomalies. Our findings suggest that asymmetric idiosyncratic reversal (AIR) is the primary driver of short-term return predictability.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35840", "title_zh": "\u4e0d\u5bf9\u79f0\u53cd\u8f6c", "abstract_zh": "\u77ed\u671f\u6536\u76ca\u53cd\u8f6c\u662f\u8d44\u4ea7\u5b9a\u4ef7\u4e2d\u6700\u7a33\u5065\u7684\u5f02\u5e38\u73b0\u8c61\u4e4b\u4e00\uff0c\u901a\u5e38\u4e0e\u6d41\u52a8\u6027\u63d0\u4f9b\u76f8\u5173\u3002\u6211\u4eec\u5c06\u5355\u4e2a\u4f01\u4e1a\u7684\u80a1\u7968\u6536\u76ca\u5206\u89e3\u4e3a\u4e24\u4e2a\u72ec\u7acb\u7684\u7ec4\u6210\u90e8\u5206\uff1aSYS\uff0c\u5373\u53ef\u4ee5\u4e0e\u7cfb\u7edf\u6027\u98ce\u9669\u548c\u516c\u5f00\u4fe1\u606f\u53d1\u5e03\u76f8\u5173\u8054\u7684\u6536\u76ca\u90e8\u5206\uff1b\u4ee5\u53ca\u4e00\u4e2a\u6b63\u4ea4\u7684\u6b8b\u5dee\u90e8\u5206RES\u3002RES\u90e8\u5206\u8868\u73b0\u51fa\u53cd\u8f6c\u7279\u5f81\uff0c\u800cSYS\u90e8\u5206\u5219\u5448\u73b0\u6301\u7eed\u6027\u3002\u6b64\u5916\uff0c\u6b8b\u5dee\u53cd\u8f6c\u5177\u6709\u9ad8\u5ea6\u7684\u4e0d\u5bf9\u79f0\u6027\uff1a\u6b63\u5411\u6b8b\u5dee\u51b2\u51fb\u7684\u53cd\u8f6c\u901f\u5ea6\u8fdc\u6162\u4e8e\u8d1f\u5411\u51b2\u51fb\u3002\u4e00\u4e2a\u57fa\u4e8e\u4e0d\u5bf9\u79f0\u7279\u8d28\u98ce\u9669\u53cd\u8f6c\u7684\u6536\u76ca\u56e0\u5b50\u4e0d\u4ec5\u5305\u542b\u4e86\u7279\u8d28\u6ce2\u52a8\u7387\u56e0\u5b50\uff0c\u8fd8\u6db5\u76d6\u4e86\u5927\u91cf\u5176\u4ed6\u77ed\u671f\u5f02\u5e38\u73b0\u8c61\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u4e0d\u5bf9\u79f0\u7279\u8d28\u98ce\u9669\u53cd\u8f6c\uff08AIR\uff09\u662f\u77ed\u671f\u6536\u76ca\u53ef\u9884\u6d4b\u6027\u7684\u4e3b\u8981\u9a71\u52a8\u56e0\u7d20\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.3386/w35841", "journal": "NBER", "title": "Soft Reserves, Learning and Bid Adjustment in Advertising Auctions", "authors": ["Joshua S. Gans"], "author_details": [{"name": "Joshua S. Gans", "affiliations": []}], "abstract": "An advertiser in a second-price auction sees what it paid, not the rival bids that supposedly set the price. Akbarpour and Li (2020) show that an auctioneer can therefore charge a winner up to its bid undetected. The Federal Trade Commission alleges that Amazon\u2019s advertising auctions, described as second-price, used soft reserves that did this. We ask whether repeated bidding exposes such charges and what adjustment does to welfare. If each charge equal to the bid is flagged, the soft reserve is exposed quickly, however much the advertiser trusted the description. If reports show only win rates and expected charges, it is indistinguishable from a second-price auction at any fixed bid: an advertiser that trusts the description and bids its value never learns, and one that doubts it but bids for current profit needs a number of auctions at least inversely proportional to its doubt before it considers a soft reserve more likely than not. The second-price description and aggregate reporting are complements. Among informed, symmetric advertisers, the soft reserve raises no more revenue than a second-price auction, and when only some advertisers adjust, placements are misallocated. Disclosure returns surplus to advertisers; removing the surcharge also restores efficiency.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35841", "title_zh": "\u8f6f\u50a8\u5907\u3001\u5b66\u4e60\u4e0e\u5e7f\u544a\u62cd\u5356\u4e2d\u7684\u51fa\u4ef7\u8c03\u6574", "abstract_zh": "\u5728\u7b2c\u4e8c\u4ef7\u683c\u62cd\u5356\u4e2d\uff0c\u5e7f\u544a\u5546\u53ea\u80fd\u770b\u5230\u81ea\u5df1\u652f\u4ed8\u7684\u91d1\u989d\uff0c\u800c\u65e0\u6cd5\u770b\u5230\u8bbe\u5b9a\u4ef7\u683c\u7684\u7ade\u4e89\u5bf9\u624b\u51fa\u4ef7\u3002Akbarpour\u548cLi\uff082020\uff09\u6307\u51fa\uff0c\u62cd\u5356\u65b9\u56e0\u6b64\u53ef\u4ee5\u5bf9\u4e2d\u6807\u8005\u6536\u53d6\u9ad8\u8fbe\u5176\u51fa\u4ef7\u7684\u8d39\u7528\uff0c\u4e14\u8fd9\u79cd\u884c\u4e3a\u65e0\u6cd5\u88ab\u68c0\u6d4b\u5230\u3002\u7f8e\u56fd\u8054\u90a6\u8d38\u6613\u59d4\u5458\u4f1a\u58f0\u79f0\uff0c\u4e9a\u9a6c\u900a\u7684\u5e7f\u544a\u62cd\u5356\u867d\u88ab\u63cf\u8ff0\u4e3a\u7b2c\u4e8c\u4ef7\u683c\u62cd\u5356\uff0c\u4f46\u5b9e\u9645\u4e0a\u4f7f\u7528\u4e86\u8f6f\u50a8\u5907\uff0c\u4ece\u800c\u5b9e\u65bd\u4e86\u8fd9\u79cd\u884c\u4e3a\u3002\u6211\u4eec\u63a2\u8ba8\u91cd\u590d\u51fa\u4ef7\u662f\u5426\u80fd\u66b4\u9732\u8fd9\u79cd\u884c\u4e3a\uff0c\u4ee5\u53ca\u51fa\u4ef7\u8c03\u6574\u5bf9\u798f\u5229\u7684\u5f71\u54cd\u3002\u5982\u679c\u6bcf\u4e2a\u7b49\u4e8e\u51fa\u4ef7\u7684\u6536\u8d39\u90fd\u88ab\u6807\u8bb0\u51fa\u6765\uff0c\u90a3\u4e48\u8f6f\u50a8\u5907\u4f1a\u8fc5\u901f\u88ab\u66b4\u9732\uff0c\u65e0\u8bba\u5e7f\u544a\u5546\u5bf9\u63cf\u8ff0\u7684\u53ef\u4fe1\u5ea6\u6709\u591a\u9ad8\u3002\u5982\u679c\u62a5\u544a\u4ec5\u663e\u793a\u80dc\u7387\u548c\u9884\u671f\u6536\u8d39\uff0c\u5219\u5728\u4efb\u4f55\u56fa\u5b9a\u51fa\u4ef7\u4e0b\uff0c\u5176\u8868\u73b0\u90fd\u4e0e\u6807\u51c6\u7b2c\u4e8c\u4ef7\u683c\u62cd\u5356\u65e0\u6cd5\u533a\u5206\uff1a\u90a3\u4e9b\u4fe1\u4efb\u63cf\u8ff0\u5e76\u4ee5\u81ea\u8eab\u4ef7\u503c\u51fa\u4ef7\u7684\u5e7f\u544a\u5546\u59cb\u7ec8\u65e0\u6cd5\u83b7\u5f97\u4fe1\u606f\uff0c\u800c\u90a3\u4e9b\u6000\u7591\u63cf\u8ff0\u4f46\u4e3a\u5f53\u524d\u5229\u6da6\u51fa\u4ef7\u7684\u5e7f\u544a\u5546\uff0c\u5219\u9700\u8981\u8fdb\u884c\u6570\u91cf\u4e0a\u81f3\u5c11\u4e0e\u6000\u7591\u7a0b\u5ea6\u6210\u53cd\u6bd4\u7684\u62cd\u5356\uff0c\u624d\u80fd\u8ba4\u4e3a\u8f6f\u50a8\u5907\u7684\u53ef\u80fd\u6027\u8d85\u8fc7\u4e00\u534a\u3002\u7b2c\u4e8c\u4ef7\u683c\u63cf\u8ff0\u4e0e\u6574\u4f53\u62a5\u544a\u662f\u4e92\u8865\u7684\u3002\u5728\u4fe1\u606f\u5145\u5206\u4e14\u5bf9\u79f0\u7684\u5e7f\u544a\u5546\u7fa4\u4f53\u4e2d\uff0c\u8f6f\u50a8\u5907\u6240\u83b7\u5f97\u7684\u6536\u5165\u5e76\u4e0d\u8d85\u8fc7\u6807\u51c6\u7b2c\u4e8c\u4ef7\u683c\u62cd\u5356\uff1b\u5f53\u4ec5\u90e8\u5206\u5e7f\u544a\u5546\u8fdb\u884c\u8c03\u6574\u65f6\uff0c\u5e7f\u544a\u4f4d\u7684\u5206\u914d\u4f1a\u51fa\u73b0\u504f\u5dee\u3002\u62ab\u9732\u884c\u4e3a\u5c06\u76c8\u4f59\u8fd4\u8fd8\u7ed9\u5e7f\u544a\u5546\uff1b\u79fb\u9664\u9644\u52a0\u8d39\u7528\u4e5f\u80fd\u6062\u590d\u6548\u7387\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35842", "journal": "NBER", "title": "Schooling and Political Activism in the Early Civil Rights Era", "authors": ["Daniel Aaronson", "Mark Borgschulte", "Sunny Liu", "Bhashkar Mazumder"], "author_details": [{"name": "Daniel Aaronson", "affiliations": []}, {"name": "Mark Borgschulte", "affiliations": []}, {"name": "Sunny Liu", "affiliations": []}, {"name": "Bhashkar Mazumder", "affiliations": []}], "abstract": "Does education lead to political activity? We find that a large, early 20th century school construction program, the Rosenwald schools, led to more NAACP branches in the rural South starting in the early 1940s, i.e. prior to the classic U.S. Civil Rights Movement. Branch growth was stronger where Jim Crow occupational segregation prevented Black men from realizing some of the economic gains of their education. Our findings lend support to theories emphasizing that economic context can act as a critical mediator in determining whether human capital causes political engagement.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35842", "title_zh": "20\u4e16\u7eaa\u65e9\u671f\u7684\u6559\u80b2\u4e0e\u6c11\u6743\u8fd0\u52a8\u521d\u671f\u7684\u653f\u6cbb\u53c2\u4e0e", "abstract_zh": "\u6559\u80b2\u662f\u5426\u4f1a\u5bfc\u81f4\u653f\u6cbb\u53c2\u4e0e\uff1f\u6211\u4eec\u53d1\u73b0\uff0c20\u4e16\u7eaa\u65e9\u671f\u7684\u4e00\u9879\u5927\u89c4\u6a21\u5b66\u6821\u5efa\u8bbe\u8ba1\u5212\u2014\u2014\u7f57\u68ee\u74e6\u5c14\u5fb7\u5b66\u6821\u2014\u2014\u572820\u4e16\u7eaa40\u5e74\u4ee3\u521d\uff0c\u5373\u7f8e\u56fd\u7ecf\u5178\u6c11\u6743\u8fd0\u52a8\u4e4b\u524d\uff0c\u4fc3\u4f7f\u7f8e\u56fd\u5357\u65b9\u519c\u6751\u5730\u533a\u6210\u7acb\u4e86\u66f4\u591a\u7684\u5168\u56fd\u6709\u8272\u4eba\u79cd\u534f\u8fdb\u4f1a\uff08NAACP\uff09\u5206\u652f\u673a\u6784\u3002\u5728\u5409\u59c6\u00b7\u514b\u52b3\u5236\u5ea6\u5bfc\u81f4\u9ed1\u4eba\u7537\u6027\u65e0\u6cd5\u5b9e\u73b0\u5176\u6559\u80b2\u5e26\u6765\u7684\u90e8\u5206\u7ecf\u6d4e\u6536\u76ca\u7684\u5730\u533a\uff0cNAACP\u5206\u652f\u673a\u6784\u7684\u589e\u957f\u66f4\u4e3a\u663e\u8457\u3002\u6211\u4eec\u7684\u53d1\u73b0\u652f\u6301\u4e86\u5f3a\u8c03\u7ecf\u6d4e\u73af\u5883\u5728\u51b3\u5b9a\u4eba\u529b\u8d44\u672c\u662f\u5426\u5f15\u53d1\u653f\u6cbb\u53c2\u4e0e\u65b9\u9762\u8d77\u5173\u952e\u4e2d\u4ecb\u4f5c\u7528\u7684\u7406\u8bba\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35843", "journal": "NBER", "title": "Welfare Analysis with Complementarities: When Direct and Total Responses Are Sufficient", "authors": ["David Argente"], "author_details": [{"name": "David Argente", "affiliations": []}], "abstract": "Complementarities can have important welfare consequences, but quantifying these effects would seem to require identifying and valuing the underlying mechanisms separately. This paper shows that this need not be the case. I provide necessary and sufficient conditions under which baseline subsidized activity and the direct and total responses to a subsidy determine aggregate willingness to pay. A sufficient condition for valuing the equilibrium adjustment is that it has the same effect on utility as an additional subsidy common to all agents and relevant actions. The formula is easy to apply to existing estimates and guides the design of new experiments.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35843", "title_zh": "\u4e92\u8865\u6027\u4e0b\u7684\u798f\u5229\u5206\u6790\uff1a\u5f53\u76f4\u63a5\u53cd\u5e94\u548c\u603b\u53cd\u5e94\u8db3\u4ee5\u8bf4\u660e\u95ee\u9898", "abstract_zh": "\u4e92\u8865\u6027\u53ef\u80fd\u5bf9\u798f\u5229\u4ea7\u751f\u91cd\u8981\u5f71\u54cd\uff0c\u4f46\u8981\u91cf\u5316\u8fd9\u4e9b\u6548\u5e94\uff0c\u4f3c\u4e4e\u9700\u8981\u5206\u522b\u8bc6\u522b\u5e76\u8bc4\u4f30\u5176 underlying \u673a\u5236\u3002\u672c\u6587\u8868\u660e\uff0c\u8fd9\u672a\u5fc5\u5fc5\u8981\u3002\u6211\u63d0\u4f9b\u4e86\u5fc5\u8981\u4e14\u5145\u5206\u7684\u6761\u4ef6\uff0c\u5373\u5728\u57fa\u7ebf\u8865\u8d34\u6d3b\u52a8\u4ee5\u53ca\u5bf9\u8865\u8d34\u7684\u76f4\u63a5\u53cd\u5e94\u548c\u603b\u53cd\u5e94\u786e\u5b9a\u4e86\u6574\u4f53\u652f\u4ed8\u610f\u613f\u3002\u5bf9\u5747\u8861\u8c03\u6574\u8fdb\u884c\u4f30\u503c\u7684\u5145\u5206\u6761\u4ef6\u662f\uff1a\u5176\u5bf9\u6548\u7528\u7684\u5f71\u54cd\u7b49\u540c\u4e8e\u6240\u6709\u53c2\u4e0e\u8005\u548c\u76f8\u5173\u884c\u4e3a\u5747\u63a5\u53d7\u989d\u5916\u8865\u8d34\u7684\u60c5\u51b5\u3002\u8be5\u516c\u5f0f\u6613\u4e8e\u5e94\u7528\u4e8e\u73b0\u6709\u4f30\u8ba1\uff0c\u5e76\u6307\u5bfc\u65b0\u5b9e\u9a8c\u7684\u8bbe\u8ba1\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35844", "journal": "NBER", "title": "Aging Out of Coverage: Lessons from the West Virginia $1,000 Adult Dental Benefit", "authors": ["Daniel S. Grossman", "Kole T. Reddig", "Jane Ruseski", "Fotinos Panagakos"], "author_details": [{"name": "Daniel S. Grossman", "affiliations": []}, {"name": "Kole T. Reddig", "affiliations": []}, {"name": "Jane Ruseski", "affiliations": []}, {"name": "Fotinos Panagakos", "affiliations": []}], "abstract": "This paper studies the utilization of dental services during the recent implementation of an adult (age 21 and over) Medicaid dental benefit in West Virginia. We analyze claims data and find: 1) before implementation, quarterly utilization of preventative and restorative services falls from 8% at age 20 to virtually 0% at age 21; 2) post-implementation, utilization falls from 8% at age 20 to 5% at age 21, implying a net increase of 50% of baseline utilization; 3) the net effect of the dental benefit is significantly larger in counties with a larger number of oral health care provider practices. Our results provide evidence that public health insurance expansions are dampened in markets with a limited supply of provider practices.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35844", "title_zh": "\u9000\u51fa\u4fdd\u969c\uff1a\u6765\u81ea\u897f\u5f17\u5409\u5c3c\u4e9a\u5dde1000\u7f8e\u5143\u6210\u4eba\u7259\u79d1\u798f\u5229\u7684\u542f\u793a", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u897f\u5f17\u5409\u5c3c\u4e9a\u5dde\u8fd1\u671f\u5b9e\u65bd\u6210\u4eba\uff0821\u5c81\u53ca\u4ee5\u4e0a\uff09Medicaid\u7259\u79d1\u798f\u5229\u671f\u95f4\u7259\u79d1\u670d\u52a1\u7684\u4f7f\u7528\u60c5\u51b5\u3002\u6211\u4eec\u5206\u6790\u4e86\u7406\u8d54\u6570\u636e\uff0c\u53d1\u73b0\uff1a1\uff09\u5b9e\u65bd\u524d\uff0c\u9884\u9632\u6027\u548c\u4fee\u590d\u6027\u7259\u79d1\u670d\u52a1\u7684\u5b63\u5ea6\u4f7f\u7528\u7387\u4ece20\u5c81\u65f6\u76848%\u4e0b\u964d\u523021\u5c81\u65f6\u51e0\u4e4e\u4e3a0%\uff1b2\uff09\u5b9e\u65bd\u540e\uff0c\u4f7f\u7528\u7387\u4ece20\u5c81\u65f6\u76848%\u4e0b\u964d\u523021\u5c81\u65f6\u76845%\uff0c\u610f\u5473\u7740\u57fa\u7ebf\u4f7f\u7528\u7387\u51c0\u589e\u957f50%\uff1b3\uff09\u5728\u53e3\u8154\u5065\u5eb7\u62a4\u7406\u63d0\u4f9b\u673a\u6784\u6570\u91cf\u8f83\u591a\u7684\u53bf\uff0c\u8be5\u7259\u79d1\u798f\u5229\u7684\u51c0\u6548\u679c\u663e\u8457\u66f4\u5927\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u516c\u5171\u5065\u5eb7\u4fdd\u9669\u6269\u5c55\u5728\u63d0\u4f9b\u673a\u6784\u6570\u91cf\u6709\u9650\u7684\u5e02\u573a\u4e2d\u4f1a\u53d7\u5230\u6291\u5236\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35845", "journal": "NBER", "title": "Limits to Arbitrage and Prediction Market Efficiency: the Case of PredictIt", "authors": ["Eric Zitzewitz"], "author_details": [{"name": "Eric Zitzewitz", "affiliations": []}], "abstract": "PredictIt is a CFTC-regulated US prediction market focused on political outcomes. It was very successful in attracting participants in the 2016-22 period, running liquid markets on topics predecessors had tried unsuccesfully. During this period, investors were limited to $850 positions in each contract, which limited arbitrage trading. PredictIt exhibited much larger pricing biases than previously studied prediction markets. Bid prices often persistently added to more than 110, implying an immediate arbitrage profit even after fees. Prices exhibited an overpricing of longshots that was larger than in other prediction markets. The experience of PredictIt suggests that limiting stakes may undermine the ability of prediction markets to accurately price event probabilities.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35845", "title_zh": "\u5957\u5229\u9650\u5236\u4e0e\u9884\u6d4b\u5e02\u573a\u6548\u7387\uff1a\u4ee5PredictIt\u4e3a\u4f8b", "abstract_zh": "PredictIt\u662f\u4e00\u4e2a\u53d7\u7f8e\u56fd\u5546\u54c1\u671f\u8d27\u4ea4\u6613\u59d4\u5458\u4f1a\uff08CFTC\uff09\u76d1\u7ba1\u7684\u9884\u6d4b\u5e02\u573a\uff0c\u4e13\u6ce8\u4e8e\u653f\u6cbb\u7ed3\u679c\u7684\u9884\u6d4b\u3002\u57282016\u81f32022\u5e74\u95f4\uff0c\u8be5\u5e73\u53f0\u6210\u529f\u5438\u5f15\u4e86\u5927\u91cf\u53c2\u4e0e\u8005\uff0c\u8fd0\u884c\u4e86\u6b64\u524d\u5176\u4ed6\u5e73\u53f0\u5c1d\u8bd5\u4f46\u672a\u6210\u529f\u7684\u6d41\u52a8\u6027\u5e02\u573a\u3002\u5728\u6b64\u671f\u95f4\uff0c\u6295\u8d44\u8005\u5728\u6bcf\u4e2a\u5408\u7ea6\u4e2d\u7684\u6301\u4ed3\u88ab\u9650\u5236\u5728850\u7f8e\u5143\uff0c\u8fd9\u9650\u5236\u4e86\u5957\u5229\u4ea4\u6613\u7684\u89c4\u6a21\u3002PredictIt\u8868\u73b0\u51fa\u6bd4\u4ee5\u5f80\u7814\u7a76\u7684\u9884\u6d4b\u5e02\u573a\u66f4\u5927\u7684\u5b9a\u4ef7\u504f\u5dee\u3002\u6295\u6807\u4ef7\u683c\u5e38\u5e38\u6301\u7eed\u9ad8\u4e8e110\uff0c\u8fd9\u610f\u5473\u7740\u5373\u4f7f\u6263\u9664\u8d39\u7528\u4ecd\u5b58\u5728\u5373\u65f6\u5957\u5229\u5229\u6da6\u3002\u5e02\u573a\u5bf9\u51b7\u95e8\u4e8b\u4ef6\u7684\u9ad8\u4f30\u7a0b\u5ea6\u4e5f\u8d85\u8fc7\u4e86\u5176\u4ed6\u9884\u6d4b\u5e02\u573a\u3002PredictIt\u7684\u8fd0\u884c\u7ecf\u9a8c\u8868\u660e\uff0c\u9650\u5236\u6301\u4ed3\u53ef\u80fd\u524a\u5f31\u9884\u6d4b\u5e02\u573a\u51c6\u786e\u5b9a\u4ef7\u4e8b\u4ef6\u6982\u7387\u7684\u80fd\u529b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35846", "journal": "NBER", "title": "Are Prediction Markets Politically Biased?", "authors": ["Eric Zitzewitz"], "author_details": [{"name": "Eric Zitzewitz", "affiliations": []}], "abstract": "As prediction markets become more prominent, there are concerns that they will be a conduit for political bias. I analyze prediction markets returns from 1880 to 2025 and find no evidence of an overpricing of either left or right-leaning candidates, across a variety of subsamples. In recent elections, there is also no overpricing of either male or female, white or non-white, or young or old candidates. Most political prediction markets exhibit a favorite-longshot bias, and markets on near-term polling averages exhibit a very small overpricing of left-leaning outcomes (e.g., President Trump\u2019s approval falling), which is detectable only because the sample size is large. For elections, however, despite attracting participants who may not be representative of the voting population, prediction markets yield predictions without systematic bias.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35846", "title_zh": "\u9884\u6d4b\u5e02\u573a\u5b58\u5728\u653f\u6cbb\u504f\u89c1\u5417\uff1f", "abstract_zh": "\u968f\u7740\u9884\u6d4b\u5e02\u573a\u53d8\u5f97\u8d8a\u6765\u8d8a\u91cd\u8981\uff0c\u4eba\u4eec\u62c5\u5fc3\u5b83\u4eec\u4f1a\u6210\u4e3a\u653f\u6cbb\u504f\u89c1\u7684\u4f20\u64ad\u6e20\u9053\u3002\u6211\u5206\u6790\u4e861880\u5e74\u81f32025\u5e74\u95f4\u9884\u6d4b\u5e02\u573a\u7684\u56de\u62a5\u6570\u636e\uff0c\u53d1\u73b0\u65e0\u8bba\u662f\u5de6\u503e\u8fd8\u662f\u53f3\u503e\u5019\u9009\u4eba\uff0c\u5747\u6ca1\u6709\u51fa\u73b0\u7cfb\u7edf\u6027\u9ad8\u4f30\u7684\u73b0\u8c61\uff0c\u8fd9\u4e00\u7ed3\u8bba\u5728\u591a\u4e2a\u5b50\u6837\u672c\u4e2d\u5747\u6210\u7acb\u3002\u5728\u6700\u8fd1\u7684\u9009\u4e3e\u4e2d\uff0c\u4e5f\u6ca1\u6709\u53d1\u73b0\u5bf9\u7537\u6027\u6216\u5973\u6027\u3001\u767d\u4eba\u6216\u975e\u767d\u4eba\u3001\u5e74\u8f7b\u4eba\u6216\u8001\u5e74\u4eba\u5019\u9009\u4eba\u7684\u7cfb\u7edf\u6027\u9ad8\u4f30\u3002\u5927\u591a\u6570\u653f\u6cbb\u9884\u6d4b\u5e02\u573a\u8868\u73b0\u51fa\u5bf9\u70ed\u95e8\u5019\u9009\u4eba\u7684\u504f\u597d\uff08\u5373\u70ed\u95e8\u957f\u8d54\u7387\u504f\u5dee\uff09\uff0c\u800c\u9488\u5bf9\u8fd1\u671f\u6c11\u8c03\u5e73\u5747\u503c\u7684\u5e02\u573a\u5219\u5bf9\u5de6\u503e\u7ed3\u679c\uff08\u4f8b\u5982\u7279\u6717\u666e\u652f\u6301\u7387\u4e0b\u964d\uff09\u6709\u6781\u5fae\u5c0f\u7684\u9ad8\u4f30\uff0c\u8fd9\u79cd\u73b0\u8c61\u53ea\u6709\u5728\u6837\u672c\u91cf\u8db3\u591f\u5927\u65f6\u624d\u80fd\u88ab\u68c0\u6d4b\u5230\u3002\u7136\u800c\uff0c\u5728\u9009\u4e3e\u9884\u6d4b\u4e2d\uff0c\u5c3d\u7ba1\u53c2\u4e0e\u8005\u53ef\u80fd\u65e0\u6cd5\u4ee3\u8868\u5b9e\u9645\u9009\u6c11\u7fa4\u4f53\uff0c\u9884\u6d4b\u5e02\u573a\u6240\u751f\u6210\u7684\u9884\u6d4b\u7ed3\u679c\u5374\u4e0d\u5b58\u5728\u7cfb\u7edf\u6027\u504f\u89c1\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35847", "journal": "NBER", "title": "Targeted Acceleration in Middle School Math: Impacts on College Entry, Degree Completion, and STEM", "authors": ["David Card", "Laura Giuliano"], "author_details": [{"name": "David Card", "affiliations": []}, {"name": "Laura Giuliano", "affiliations": []}], "abstract": "We study an accelerated 3-year math curriculum offered in the middle schools of a large urban district that enables students to finish Algebra I and Geometry before high school. Entry to the program is based on 5th-grade math test scores, with a cutoff at the 80th percentile. Continuing eligibility requires at least a B grade in the previous year; successful completion of all three years is highly correlated with an index of non-cognitive skills. Following students for 6 years after high school graduation, we find that the impacts of admission vary widely by non-cognitive skill and gender. Marginally eligible boys with high non-cognitive skills have a 33 percentage point (ppt.) increase in the probability of completing calculus by 11th grade and a 12 ppt. increase in the probability of completing a major in STEM or business within 6 years; boys with lower noncognitive skills take more advanced math classes in high school but have no significant effects on their college outcomes. Like their male peers, marginally eligible girls with high non-cognitive skills are more likely to complete calculus by 11th grade (+17 ppt.). Their rate of graduating with a STEM or business major is unaffected, but they switch from social sciences to the core STEM majors (science, engineering and math). Girls in the two lower terciles of non-cognitive skill are also strongly affected by entry to the program, with higher participation in advanced math classes in high school, higher rates of entry to selective 4-year colleges, and higher rates of completing a STEM or business major (+12 ppt).", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35847", "title_zh": "\u521d\u4e2d\u6570\u5b66\u52a0\u901f\u8ba1\u5212\u7684\u5f71\u54cd\uff1a\u5bf9\u5927\u5b66\u5165\u5b66\u3001\u5b66\u4f4d\u5b8c\u6210\u53caSTEM\u9886\u57df\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u67d0\u5927\u578b\u57ce\u5e02\u5b66\u533a\u521d\u4e2d\u5b66\u6821\u63d0\u4f9b\u7684\u4e00\u4e2a\u4e3a\u671f\u4e09\u5e74\u7684\u52a0\u901f\u6570\u5b66\u8bfe\u7a0b\uff0c\u8be5\u8bfe\u7a0b\u4f7f\u5b66\u751f\u80fd\u591f\u5728\u9ad8\u4e2d\u4e4b\u524d\u5b8c\u6210\u4ee3\u6570\u548c\u51e0\u4f55\u8bfe\u7a0b\u3002\u5b66\u751f\u5165\u5b66\u8d44\u683c\u57fa\u4e8e\u4e94\u5e74\u7ea7\u6570\u5b66\u8003\u8bd5\u6210\u7ee9\uff0c\u8bbe\u5b9a\u5728\u7b2c80\u767e\u5206\u4f4d\u3002\u6301\u7eed\u8d44\u683c\u8981\u6c42\u524d\u4e00\u5e74\u6210\u7ee9\u81f3\u5c11\u4e3aB\u7ea7\uff1b\u6210\u529f\u5b8c\u6210\u4e09\u5e74\u8bfe\u7a0b\u4e0e\u975e\u8ba4\u77e5\u6280\u80fd\u6307\u6570\u9ad8\u5ea6\u76f8\u5173\u3002\u5728\u5b66\u751f\u9ad8\u4e2d\u6bd5\u4e1a\u540e\u8ffd\u8e2a\u516d\u5e74\uff0c\u6211\u4eec\u53d1\u73b0\u5165\u5b66\u5f71\u54cd\u56e0\u975e\u8ba4\u77e5\u6280\u80fd\u548c\u6027\u522b\u800c\u5f02\u3002\u975e\u8ba4\u77e5\u6280\u80fd\u8f83\u9ad8\u7684\u8fb9\u7f18\u5408\u683c\u7537\u751f\uff0c\u5176\u572811\u5e74\u7ea7\u5b8c\u6210\u5fae\u79ef\u5206\u7684\u6982\u7387\u63d0\u9ad8\u4e8633\u4e2a\u767e\u5206\u70b9\uff08ppt.\uff09\uff0c\u5728\u516d\u5e74\u5185\u5b8c\u6210STEM\u6216\u5546\u4e1a\u4e13\u4e1a\u5b66\u4f4d\u7684\u6982\u7387\u63d0\u9ad8\u4e8612 ppt.\uff1b\u975e\u8ba4\u77e5\u6280\u80fd\u8f83\u4f4e\u7684\u7537\u751f\u867d\u7136\u5728\u9ad8\u4e2d\u9636\u6bb5\u9009\u4fee\u4e86\u66f4\u591a\u9ad8\u7ea7\u6570\u5b66\u8bfe\u7a0b\uff0c\u4f46\u5bf9\u5927\u5b66\u7ed3\u679c\u65e0\u663e\u8457\u5f71\u54cd\u3002\u4e0e\u7537\u751f\u7c7b\u4f3c\uff0c\u975e\u8ba4\u77e5\u6280\u80fd\u8f83\u9ad8\u7684\u8fb9\u7f18\u5408\u683c\u5973\u751f\u572811\u5e74\u7ea7\u5b8c\u6210\u5fae\u79ef\u5206\u7684\u6982\u7387\u4e5f\u63d0\u9ad8\u4e8617 ppt.\uff1b\u5176\u83b7\u5f97STEM\u6216\u5546\u4e1a\u4e13\u4e1a\u5b66\u4f4d\u7684\u6bd4\u7387\u672a\u53d7\u5f71\u54cd\uff0c\u4f46\u5979\u4eec\u4ece\u793e\u4f1a\u79d1\u5b66\u8f6c\u5411\u4e86\u6838\u5fc3STEM\u4e13\u4e1a\uff08\u79d1\u5b66\u3001\u5de5\u7a0b\u548c\u6570\u5b66\uff09\u3002\u5728\u975e\u8ba4\u77e5\u6280\u80fd\u8f83\u4f4e\u7684\u4e24\u4e2a\u4e09\u5206\u4f4d\u4e2d\u7684\u5973\u751f\u4e5f\u53d7\u5230\u5165\u5b66\u8ba1\u5212\u7684\u663e\u8457\u5f71\u54cd\uff0c\u8868\u73b0\u4e3a\u9ad8\u4e2d\u9636\u6bb5\u53c2\u4e0e\u9ad8\u7ea7\u6570\u5b66\u8bfe\u7a0b\u7684\u6bd4\u4f8b\u66f4\u9ad8\uff0c\u8fdb\u5165\u9876\u5c16\u56db\u5e74\u5236\u5927\u5b66\u7684\u6bd4\u4f8b\u66f4\u9ad8\uff0c\u4ee5\u53ca\u5b8c\u6210STEM\u6216\u5546\u4e1a\u4e13\u4e1a\u5b66\u4f4d\u7684\u6bd4\u4f8b\u63d0\u9ad8\u4e8612 ppt.", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35848", "journal": "NBER", "title": "The Regulatory Burden of Licensure Sales Laws: New Evidence on Race and the U.S. Tobacco Market", "authors": ["Dhaval M. Dave", "Jooyoung Kim", "Joseph J. Sabia"], "author_details": [{"name": "Dhaval M. Dave", "affiliations": []}, {"name": "Jooyoung Kim", "affiliations": []}, {"name": "Joseph J. Sabia", "affiliations": []}], "abstract": "Licensure sales requirements are commonly justified as consumer protection regulations intended to improve seller compliance and reduce harm associated with risky products. However, licensure effects may differ across communities with heterogeneous enforcement intensity and seller responses. We study this question in the context of e-cigarette retail licensure laws (ERLLs), a policy intended to regulate access to e-cigarettes among youth. We find that state ERLLs with strong penalties for non-compliance reduce nicotine vaping among Black youths by 2.5-4.0 percentage points but have no effect on White youths. This racially disparate finding is driven by heterogeneous supply-side responses to increased regulatory burden. Vendors in Black neighborhoods are more likely to be targeted for inspections than those in White neighborhoods despite having lower pre-treatment rates of infractions. Moreover, vendors in Black neighborhoods are also less likely to sell e-cigarettes following ERLL adoption, consistent with a racially disparate regulatory burden. Together, our results suggest important distributional consequences of licensure requirements.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35848", "title_zh": "\u8bb8\u53ef\u8bc1\u9500\u552e\u6cd5\u89c4\u7684\u76d1\u7ba1\u8d1f\u62c5\uff1a\u5173\u4e8e\u79cd\u65cf\u4e0e\u7f8e\u56fd\u70df\u8349\u5e02\u573a\u7684\u65b0\u8bc1\u636e", "abstract_zh": "\u8bb8\u53ef\u8bc1\u9500\u552e\u8981\u6c42\u901a\u5e38\u88ab\u89e3\u91ca\u4e3a\u6d88\u8d39\u8005\u4fdd\u62a4\u6cd5\u89c4\uff0c\u65e8\u5728\u63d0\u9ad8\u9500\u552e\u5546\u7684\u5408\u89c4\u6027\u5e76\u51cf\u5c11\u4e0e\u9ad8\u98ce\u9669\u4ea7\u54c1\u76f8\u5173\u7684\u4f24\u5bb3\u3002\u7136\u800c\uff0c\u8bb8\u53ef\u8bc1\u653f\u7b56\u7684\u6548\u679c\u53ef\u80fd\u5728\u4e0d\u540c\u793e\u533a\u95f4\u5b58\u5728\u5dee\u5f02\uff0c\u8fd9\u53d6\u51b3\u4e8e\u6267\u6cd5\u5f3a\u5ea6\u548c\u9500\u552e\u5546\u7684\u53cd\u5e94\u3002\u6211\u4eec\u4ee5\u7535\u5b50\u70df\u96f6\u552e\u8bb8\u53ef\u8bc1\u6cd5\u89c4\uff08ERLLs\uff09\u4e3a\u4f8b\uff0c\u8be5\u653f\u7b56\u65e8\u5728\u9650\u5236\u9752\u5c11\u5e74\u63a5\u89e6\u7535\u5b50\u70df\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5177\u6709\u4e25\u683c\u8fdd\u89c4\u5904\u7f5a\u7684\u5dde\u7ea7ERLLs\u4f7f\u9ed1\u4eba\u9752\u5c11\u5e74\u7684\u5c3c\u53e4\u4e01\u5438\u5165\u7387\u4e0b\u964d2.5\u81f34.0\u4e2a\u767e\u5206\u70b9\uff0c\u4f46\u5bf9\u767d\u4eba\u9752\u5c11\u5e74\u5219\u65e0\u663e\u8457\u5f71\u54cd\u3002\u8fd9\u4e00\u79cd\u65cf\u5dee\u5f02\u7684\u53d1\u73b0\u6e90\u4e8e\u4f9b\u7ed9\u4fa7\u5bf9\u76d1\u7ba1\u8d1f\u62c5\u589e\u52a0\u7684\u4e0d\u540c\u53cd\u5e94\u3002\u5c3d\u7ba1\u5728\u4e8b\u524d\u8fdd\u89c4\u7387\u8f83\u4f4e\uff0c\u9ed1\u4eba\u793e\u533a\u7684\u5546\u5bb6\u66f4\u53ef\u80fd\u88ab\u6267\u6cd5\u68c0\u67e5\uff0c\u800c\u767d\u4eba\u793e\u533a\u7684\u5546\u5bb6\u5219\u8f83\u5c11\u88ab\u68c0\u67e5\u3002\u6b64\u5916\uff0cERLL\u5b9e\u65bd\u540e\uff0c\u9ed1\u4eba\u793e\u533a\u7684\u5546\u5bb6\u66f4\u4e0d\u53ef\u80fd\u7ee7\u7eed\u9500\u552e\u7535\u5b50\u70df\uff0c\u8fd9\u8868\u660e\u5b58\u5728\u79cd\u65cf\u5dee\u5f02\u5316\u7684\u76d1\u7ba1\u8d1f\u62c5\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u8bb8\u53ef\u8bc1\u8981\u6c42\u53ef\u80fd\u5e26\u6765\u91cd\u8981\u7684\u5206\u914d\u6027\u540e\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35849", "journal": "NBER", "title": "Avoiding Regulation: Evidence from Nursing Homes", "authors": ["Alden Cheng", "Riley League"], "author_details": [{"name": "Alden Cheng", "affiliations": []}, {"name": "Riley League", "affiliations": []}], "abstract": "We study strategic responses by firms to threshold-based regulations. We document extensive bunching in response to additional staffing requirements for California nursing homes with at least 100 beds. To estimate the regulation\u2019s effect on staffing, we develop a novel treatment effects estimator for threshold-based regulations under precise manipulation, by decomposing firms into response types based on counterfactual and realized staffing and size, separating causal effects from selection. We estimate that higher staffing above the threshold is nearly entirely due to selection, with low-staffing facilities manipulating their size to avoid the regulation. These size distortions limit access, particularly for disadvantaged patients.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35849", "title_zh": "\u89c4\u907f\u76d1\u7ba1\uff1a\u6765\u81ea\u62a4\u7406\u673a\u6784\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4f01\u4e1a\u5728\u9762\u5bf9\u57fa\u4e8e\u9608\u503c\u7684\u76d1\u7ba1\u65f6\u7684\u7b56\u7565\u6027\u53cd\u5e94\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5bf9\u4e8e\u52a0\u5dde\u62e5\u6709\u81f3\u5c11100\u5f20\u5e8a\u4f4d\u7684\u62a4\u7406\u673a\u6784\uff0c\u5176\u5728\u989d\u5916 staffing \u8981\u6c42\u65b9\u9762\u5b58\u5728\u5e7f\u6cdb\u96c6\u4e2d\u73b0\u8c61\u3002\u4e3a\u4e86\u4f30\u8ba1\u76d1\u7ba1\u5bf9 staffing \u7684\u5f71\u54cd\uff0c\u6211\u4eec\u5f00\u53d1\u4e86\u4e00\u79cd\u9488\u5bf9\u57fa\u4e8e\u9608\u503c\u76d1\u7ba1\u7684\u65b0\u578b\u5904\u7406\u6548\u5e94\u4f30\u8ba1\u65b9\u6cd5\uff0c\u5728\u7cbe\u786e\u64cd\u7eb5\u6761\u4ef6\u4e0b\uff0c\u901a\u8fc7\u6839\u636e\u53cd\u4e8b\u5b9e\u548c\u5b9e\u9645\u7684 staffing \u4ee5\u53ca\u89c4\u6a21\u5c06\u4f01\u4e1a\u5212\u5206\u4e3a\u4e0d\u540c\u54cd\u5e94\u7c7b\u578b\uff0c\u5c06\u56e0\u679c\u6548\u5e94\u4e0e\u9009\u62e9\u56e0\u7d20\u5206\u79bb\u3002\u6211\u4eec\u4f30\u8ba1\uff0c\u8d85\u8fc7\u9608\u503c\u7684 staffing \u589e\u52a0\u51e0\u4e4e\u5b8c\u5168\u6e90\u4e8e\u9009\u62e9\u884c\u4e3a\uff0c\u5373\u89c4\u6a21\u8f83\u5c0f\u7684\u673a\u6784\u901a\u8fc7\u64cd\u7eb5\u5176\u89c4\u6a21\u6765\u89c4\u907f\u76d1\u7ba1\u3002\u8fd9\u79cd\u89c4\u6a21\u626d\u66f2\u9650\u5236\u4e86\u5bf9\u5f31\u52bf\u60a3\u8005\u7fa4\u4f53\u7684\u8bbf\u95ee\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35850", "journal": "NBER", "title": "Debt Sustainability and the Range of Multiple Equilibria", "authors": ["Olivier J. Blanchard", "Pedro Mart\u00ednez-Bruera", "Gonzalo Huertas"], "author_details": [{"name": "Olivier J. Blanchard", "affiliations": []}, {"name": "Pedro Mart\u00ednez-Bruera", "affiliations": []}, {"name": "Gonzalo Huertas", "affiliations": []}], "abstract": "We characterize the size of the range of multiple equilibria in sovereign debt markets. We show that the nature of the equilibrium depends crucially on the degree of uncertainty, which we formalize first as uncertainty about primary balances and later as uncertainty about the fiscal feedback rule. For low uncertainty, the range can be large, but it becomes smaller as uncertainty becomes larger. If uncertainty is large enough, the multiplicity disappears: the interest rate is unique and becomes a continuous function of the debt level. The source of these results is that larger uncertainty decreases the effect of the perceived probability of default on the actual probability of default, thus reducing and eventually eliminating the scope for multiplicity. Interpreting the source of an increase in the interest rate in actual situations is difficult, and complicates the use of intervention by central banks.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35850", "title_zh": "\u503a\u52a1\u53ef\u6301\u7eed\u6027\u4e0e\u591a\u91cd\u5747\u8861\u8303\u56f4", "abstract_zh": "\u6211\u4eec\u523b\u753b\u4e86\u4e3b\u6743\u503a\u52a1\u5e02\u573a\u4e2d\u591a\u91cd\u5747\u8861\u8303\u56f4\u7684\u5927\u5c0f\u3002\u6211\u4eec\u8868\u660e\uff0c\u5747\u8861\u7684\u6027\u8d28\u5173\u952e\u53d6\u51b3\u4e8e\u4e0d\u786e\u5b9a\u6027\u7a0b\u5ea6\uff0c\u6211\u4eec\u9996\u5148\u5c06\u4e0d\u786e\u5b9a\u6027\u5f62\u5f0f\u5316\u4e3a\u5bf9\u8d22\u653f\u76c8\u4f59\u7684\u4e0d\u786e\u5b9a\u6027\uff0c\u968f\u540e\u8fdb\u4e00\u6b65\u5f62\u5f0f\u5316\u4e3a\u5bf9\u8d22\u653f\u53cd\u9988\u89c4\u5219\u7684\u4e0d\u786e\u5b9a\u6027\u3002\u5728\u4e0d\u786e\u5b9a\u6027\u8f83\u4f4e\u65f6\uff0c\u591a\u91cd\u5747\u8861\u7684\u8303\u56f4\u53ef\u80fd\u8f83\u5927\uff0c\u4f46\u968f\u7740\u4e0d\u786e\u5b9a\u6027\u589e\u52a0\uff0c\u8be5\u8303\u56f4\u4f1a\u7f29\u5c0f\u3002\u5f53\u4e0d\u786e\u5b9a\u6027\u8db3\u591f\u5927\u65f6\uff0c\u591a\u91cd\u5747\u8861\u6d88\u5931\uff1a\u5229\u7387\u53d8\u5f97\u552f\u4e00\uff0c\u5e76\u6210\u4e3a\u503a\u52a1\u6c34\u5e73\u7684\u8fde\u7eed\u51fd\u6570\u3002\u8fd9\u4e00\u7ed3\u679c\u7684\u6765\u6e90\u662f\uff0c\u66f4\u5927\u7684\u4e0d\u786e\u5b9a\u6027\u4f1a\u964d\u4f4e\u4eba\u4eec\u5bf9\u8fdd\u7ea6\u6982\u7387\u7684\u611f\u77e5\u5bf9\u5176\u5b9e\u9645\u8fdd\u7ea6\u6982\u7387\u7684\u5f71\u54cd\uff0c\u4ece\u800c\u51cf\u5c11\u751a\u81f3\u6d88\u9664\u591a\u91cd\u5747\u8861\u7684\u7a7a\u95f4\u3002\u5728\u5b9e\u9645\u60c5\u5883\u4e2d\uff0c\u89e3\u91ca\u5229\u7387\u4e0a\u5347\u7684\u539f\u56e0\u5177\u6709\u96be\u5ea6\uff0c\u8fd9\u4f7f\u5f97\u4e2d\u592e\u94f6\u884c\u7684\u5e72\u9884\u53d8\u5f97\u66f4\u52a0\u590d\u6742\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35851", "journal": "NBER", "title": "Latent Human Capital: How Early Investments in Parents Buffer Against Future Schooling Shocks", "authors": ["Shruti Jha", "John A. List", "Rebecca C. Royer", "Anya Samek"], "author_details": [{"name": "Shruti Jha", "affiliations": []}, {"name": "John A. List", "affiliations": []}, {"name": "Rebecca C. Royer", "affiliations": []}, {"name": "Anya Samek", "affiliations": []}], "abstract": "Do early investments in parents pay off even when treatment effects for children appear to fade out quickly? We answer this question by leveraging a field experiment in which households with 3-5 year-old children were randomized into a parenting program, a preschool, or a control group, combined with a natural experiment (Covid-19 school closures) that occurred ten years later. Prior to the closures, treatment effects on academic achievement had faded to zero across all groups. Yet, with Covid-19 school closures, effects of the parenting program re-emerge: test scores in control and preschool groups drop by roughly 0.25-0.30 SD, whereas scores in the parenting group drop by only 0.11 SD (difference: p = 0.01). Our findings suggest that parenting programs can generate latent human capital that only becomes visible when complementary school inputs are removed. This result is consonant with parental and school investments acting as substitutes in skill production. Because this latent parental capacity pays off precisely when school inputs fail, standard measurement tools for early childhood programs can miss crucial state-contingent value.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35851", "title_zh": "\u6f5c\u5728\u7684\u4eba\u529b\u8d44\u672c\uff1a\u65e9\u671f\u5bf9\u7236\u6bcd\u7684\u6295\u8d44\u5982\u4f55\u7f13\u51b2\u672a\u6765\u6559\u80b2\u51b2\u51fb", "abstract_zh": "\u65e9\u671f\u5bf9\u7236\u6bcd\u7684\u6295\u8d44\u5373\u4f7f\u5728\u513f\u7ae5\u7684\u5e72\u9884\u6548\u679c\u4f3c\u4e4e\u8fc5\u901f\u6d88\u5931\u7684\u60c5\u51b5\u4e0b\uff0c\u662f\u5426\u4ecd\u80fd\u5e26\u6765\u56de\u62a5\uff1f\u6211\u4eec\u901a\u8fc7\u4e00\u9879\u5b9e\u5730\u5b9e\u9a8c\u6765\u56de\u7b54\u8fd9\u4e2a\u95ee\u9898\uff1a\u8be5\u5b9e\u9a8c\u5c06\u62e5\u67093\u81f35\u5c81\u513f\u7ae5\u7684\u5bb6\u5ead\u968f\u673a\u5206\u914d\u5230\u5bb6\u957f\u57f9\u8bad\u9879\u76ee\u3001\u5e7c\u513f\u56ed\u6216\u5bf9\u7167\u7ec4\uff0c\u540c\u65f6\u7ed3\u5408\u4e86\u5341\u5e74\u540e\u53d1\u751f\u7684\u81ea\u7136\u5b9e\u9a8c\uff08\u65b0\u51a0\u75ab\u60c5\u5bfc\u81f4\u7684\u5b66\u6821\u505c\u8bfe\uff09\u3002\u5728\u505c\u8bfe\u4e4b\u524d\uff0c\u6240\u6709\u7ec4\u522b\u4e2d\u5bf9\u5b66\u4e1a\u6210\u5c31\u7684\u5e72\u9884\u6548\u679c\u5747\u5df2\u964d\u81f3\u96f6\u3002\u7136\u800c\uff0c\u5728\u65b0\u51a0\u75ab\u60c5\u5bfc\u81f4\u5b66\u6821\u505c\u8bfe\u540e\uff0c\u5bb6\u957f\u57f9\u8bad\u9879\u76ee\u7684\u5e72\u9884\u6548\u679c\u91cd\u65b0\u663e\u73b0\uff1a\u5bf9\u7167\u7ec4\u548c\u5e7c\u513f\u56ed\u7ec4\u7684\u5b66\u751f\u6210\u7ee9\u4e0b\u964d\u7ea60.25\u81f30.30\u4e2a\u6807\u51c6\u5dee\uff0c\u800c\u5bb6\u957f\u57f9\u8bad\u7ec4\u7684\u6210\u7ee9\u4ec5\u4e0b\u964d0.11\u4e2a\u6807\u51c6\u5dee\uff08\u5dee\u5f02\uff1ap = 0.01\uff09\u3002\u6211\u4eec\u7684\u53d1\u73b0\u8868\u660e\uff0c\u5bb6\u957f\u57f9\u8bad\u9879\u76ee\u53ef\u4ee5\u4ea7\u751f\u6f5c\u5728\u7684\u4eba\u529b\u8d44\u672c\uff0c\u8fd9\u79cd\u4eba\u529b\u8d44\u672c\u53ea\u6709\u5728\u4e0e\u5b66\u6821\u8f93\u5165\u76f8\u914d\u5408\u7684\u6761\u4ef6\u88ab\u79fb\u9664\u65f6\u624d\u4f1a\u663e\u73b0\u3002\u8fd9\u4e00\u7ed3\u679c\u4e0e\u7236\u6bcd\u548c\u5b66\u6821\u6295\u8d44\u5728\u6280\u80fd\u5f62\u6210\u4e2d\u76f8\u4e92\u66ff\u4ee3\u7684\u7406\u8bba\u4e00\u81f4\u3002\u7531\u4e8e\u8fd9\u79cd\u6f5c\u5728\u7684\u7236\u6bcd\u80fd\u529b\u5728\u5b66\u6821\u7684\u8f93\u5165\u5931\u6548\u65f6\u624d\u53d1\u6325\u4f5c\u7528\uff0c\u5e38\u89c4\u7684\u65e9\u671f\u513f\u7ae5\u9879\u76ee\u8bc4\u4f30\u5de5\u5177\u53ef\u80fd\u4f1a\u9057\u6f0f\u5173\u952e\u7684\u6761\u4ef6\u6027\u4ef7\u503c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35852", "journal": "NBER", "title": "Living in a Ghost Town: The Geography of Depopulation and Aging", "authors": ["Elisa Giannone", "Yuhei Miyauchi", "Nuno Paixao", "Xinle Pang", "Yuta Suzuki"], "author_details": [{"name": "Elisa Giannone", "affiliations": []}, {"name": "Yuhei Miyauchi", "affiliations": []}, {"name": "Nuno Paixao", "affiliations": []}, {"name": "Xinle Pang", "affiliations": []}, {"name": "Yuta Suzuki", "affiliations": []}], "abstract": "How do depopulation and population aging evolve differently across regions within a country, and what are their implications for aggregate economic activity and regional inequality? Using spatially disaggregated data from Japan over the past several decades, we show that rural areas have experienced significantly faster depopulation and aging than urban areas, driven by low fertility and sustained out-migration of young cohorts. Regions undergoing these trends face declining local amenities and rising per-capita public service costs. To study the future evolution and economic consequences of these dynamics, we develop and calibrate a dynamic life-cycle spatial general equilibrium model. The model predicts widening geographic disparities in depopulation, aging, and economic activity in the coming centuries. While subsidies to declining regions can lower regional inequality, they come at the cost of lower aggregate efficiency and higher public service expenditures.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35852", "title_zh": "\u751f\u6d3b\u5728\u9b3c\u9547\uff1a\u4eba\u53e3\u51cf\u5c11\u4e0e\u8001\u9f84\u5316\u5730\u7406\u683c\u5c40", "abstract_zh": "\u4eba\u53e3\u51cf\u5c11\u548c\u4eba\u53e3\u8001\u9f84\u5316\u5728\u56fd\u5bb6\u5185\u90e8\u4e0d\u540c\u5730\u533a\u7684\u53d1\u5c55\u901f\u5ea6\u5982\u4f55\u4e0d\u540c\uff0c\u4ee5\u53ca\u8fd9\u5bf9\u6574\u4f53\u7ecf\u6d4e\u6d3b\u52a8\u548c\u533a\u57df\u4e0d\u5e73\u7b49\u6709\u4f55\u5f71\u54cd\uff1f\u5229\u7528\u8fc7\u53bb\u51e0\u5341\u5e74\u65e5\u672c\u7684\u5730\u7406\u7ec6\u5206\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u519c\u6751\u5730\u533a\u7684\u4eba\u53e3\u51cf\u5c11\u548c\u8001\u9f84\u5316\u901f\u5ea6\u663e\u8457\u5feb\u4e8e\u57ce\u5e02\u5730\u533a\uff0c\u8fd9\u4e3b\u8981\u7531\u4f4e\u751f\u80b2\u7387\u548c\u5e74\u8f7b\u7fa4\u4f53\u6301\u7eed\u5916\u6d41\u6240\u9a71\u52a8\u3002\u7ecf\u5386\u8fd9\u4e9b\u8d8b\u52bf\u7684\u5730\u533a\u9762\u4e34\u672c\u5730\u8bbe\u65bd\u548c\u670d\u52a1\u7684\u8870\u9000\u4ee5\u53ca\u4eba\u5747\u516c\u5171\u670d\u52a1\u6210\u672c\u7684\u4e0a\u5347\u3002\u4e3a\u4e86\u7814\u7a76\u8fd9\u4e9b\u52a8\u6001\u7684\u672a\u6765\u6f14\u53d8\u53ca\u5176\u7ecf\u6d4e\u540e\u679c\uff0c\u6211\u4eec\u6784\u5efa\u5e76\u6821\u51c6\u4e86\u4e00\u4e2a\u52a8\u6001\u751f\u547d\u5468\u671f\u7a7a\u95f4\u4e00\u822c\u5747\u8861\u6a21\u578b\u3002\u8be5\u6a21\u578b\u9884\u6d4b\uff0c\u672a\u6765\u51e0\u4e2a\u4e16\u7eaa\u5185\uff0c\u4eba\u53e3\u51cf\u5c11\u3001\u8001\u9f84\u5316\u4ee5\u53ca\u7ecf\u6d4e\u6d3b\u52a8\u7684\u5730\u7406\u5dee\u5f02\u5c06\u8fdb\u4e00\u6b65\u6269\u5927\u3002\u5c3d\u7ba1\u5bf9\u8870\u9000\u5730\u533a\u7684\u8865\u8d34\u53ef\u4ee5\u964d\u4f4e\u533a\u57df\u4e0d\u5e73\u7b49\uff0c\u4f46\u4f1a\u4ee5\u6574\u4f53\u7ecf\u6d4e\u6548\u7387\u4e0b\u964d\u548c\u516c\u5171\u670d\u52a1\u652f\u51fa\u589e\u52a0\u4e3a\u4ee3\u4ef7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35853", "journal": "NBER", "title": "Randomized to Opportunity: Measuring Place Effects for Refugee Children", "authors": ["N. Meltem Daysal", "Joseph J. Doyle Jr.", "Naeim S. Samandari", "Emil A. L. Simonsen", "Mircea Trandafir"], "author_details": [{"name": "N. Meltem Daysal", "affiliations": []}, {"name": "Joseph J. Doyle Jr.", "affiliations": []}, {"name": "Naeim S. Samandari", "affiliations": []}, {"name": "Emil A. L. Simonsen", "affiliations": []}, {"name": "Mircea Trandafir", "affiliations": []}], "abstract": "Area-level measures of economic opportunity are increasingly used to guide place-based policies. We study whether these measures predict long-run outcomes for a vulnerable population: over 12,000 refugee children quasi-randomly assigned to municipalities under Denmark's 1986\u20131998 dispersal policy. We focus on predetermined measures of opportunity available when children arrive and validate them using a mover-exposure design among permanent residents. Moving from a low- to a high-opportunity area (a two-standard-deviation increase) raises adult income rank by 3 percentile points (7.5 percent) and employment by 4 percentage points. It also reduces criminal convictions by 14 percent and teen parenthood by 19 percent, with more modest effects on educational attainment. Economic opportunity predicts crime and teen parenthood more strongly than other area characteristics, including local crime rates. For adult income, area-level inequality is a particularly strong predictor. These findings suggest that social mobility in the areas where refugee children grow up meaningfully shapes their long-term wellbeing.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35853", "title_zh": "\u968f\u673a\u5206\u914d\u5230\u673a\u4f1a\uff1a\u8861\u91cf\u96be\u6c11\u513f\u7ae5\u7684\u5730\u57df\u6548\u5e94", "abstract_zh": "\u533a\u57df\u5c42\u9762\u7684\u7ecf\u6d4e\u673a\u4f1a\u6307\u6807\u6b63\u8d8a\u6765\u8d8a\u591a\u5730\u88ab\u7528\u4e8e\u6307\u5bfc\u57fa\u4e8e\u5730\u57df\u7684\u653f\u7b56\u3002\u6211\u4eec\u7814\u7a76\u8fd9\u4e9b\u6307\u6807\u662f\u5426\u80fd\u591f\u9884\u6d4b\u4e00\u4e2a\u8106\u5f31\u7fa4\u4f53\u7684\u957f\u671f\u7ed3\u679c\uff1a\u8d85\u8fc712,000\u540d\u96be\u6c11\u513f\u7ae5\u6839\u636e\u4e39\u9ea61986\u5e74\u81f31998\u5e74\u5206\u6563\u653f\u7b56\u88ab\u968f\u673a\u5206\u914d\u5230\u4e0d\u540c\u7684\u5e02\u9547\u3002\u6211\u4eec\u91cd\u70b9\u5173\u6ce8\u513f\u7ae5\u62b5\u8fbe\u65f6\u5df2\u786e\u5b9a\u7684\u7ecf\u6d4e\u673a\u4f1a\u6307\u6807\uff0c\u5e76\u901a\u8fc7\u6c38\u4e45\u5c45\u6c11\u7684\u8fc1\u79fb\u66b4\u9732\u8bbe\u8ba1\u5bf9\u5176\u8fdb\u884c\u4e86\u9a8c\u8bc1\u3002\u4ece\u4f4e\u673a\u4f1a\u5730\u533a\u8fc1\u79fb\u5230\u9ad8\u673a\u4f1a\u5730\u533a\uff08\u589e\u52a0\u4e24\u4e2a\u6807\u51c6\u5dee\uff09\u4f7f\u6210\u5e74\u6536\u5165\u6392\u540d\u63d0\u9ad83\u4e2a\u767e\u5206\u70b9\uff087.5%\uff09\uff0c\u5c31\u4e1a\u7387\u63d0\u9ad84\u4e2a\u767e\u5206\u70b9\uff0c\u72af\u7f6a\u5b9a\u7f6a\u7387\u4e0b\u964d14%\uff0c\u9752\u5c11\u5e74\u751f\u80b2\u7387\u4e0b\u964d19%\uff0c\u5728\u6559\u80b2\u6210\u5c31\u65b9\u9762\u7684\u5f71\u54cd\u5219\u8f83\u4e3a\u6e29\u548c\u3002\u7ecf\u6d4e\u673a\u4f1a\u5bf9\u72af\u7f6a\u548c\u9752\u5c11\u5e74\u751f\u80b2\u7684\u9884\u6d4b\u80fd\u529b\u5f3a\u4e8e\u5176\u4ed6\u533a\u57df\u7279\u5f81\uff0c\u5305\u62ec\u5f53\u5730\u72af\u7f6a\u7387\u3002\u5bf9\u4e8e\u6210\u5e74\u6536\u5165\u800c\u8a00\uff0c\u533a\u57df\u5c42\u9762\u7684\u4e0d\u5e73\u7b49\u662f\u7279\u522b\u5f3a\u7684\u9884\u6d4b\u56e0\u7d20\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u96be\u6c11\u513f\u7ae5\u6210\u957f\u7684\u5730\u533a\u4e2d\u7684\u793e\u4f1a\u6d41\u52a8\u6027\u5bf9\u5176\u957f\u671f\u798f\u7949\u5177\u6709\u91cd\u8981\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35854", "journal": "NBER", "title": "Taxing Entrepreneurial Wealth: Evidence from Norway, 2021\u20132025", "authors": ["Marius A. K. Ring"], "author_details": [{"name": "Marius A. K. Ring", "affiliations": []}], "abstract": "Whether imposing higher taxes on business owners adversely affects business activity by constraining investment and inducing capitalist flight is a central question in the ongoing debate on how to tax the ultra wealthy. To shed new light, I exploit a series of related Norwegian reforms during 2021\u20132024 that increased dividend tax rates, removed migration-related capital gains tax loopholes, and nearly doubled the effective marginal tax rate on business wealth. These reforms spurred international debate and, allegedly, an \u201cexodus\u201d of Norwegian billionaires (Financial Times, 2023). While I document clear effects on migration, these responses are concentrated among the top 0.1% of the wealth distribution and mostly confined to 2022 and 2023. My results indicate that at most 100 individuals left due to the reforms. I find no evidence of significant outmigration or reduced inflows of startup founders or inventors. I estimate that absent any outmigration, wealth tax revenues would have increased by 75% from 2021 to 2024. Reform-driven outmigration lowers the revenue gain to 71.5%. My findings further show that outmigrating owners\u2019 firms remain economically active and do not reduce investment. In a broader set of analyses, I examine whether business outcomes are affected, regardless of whether owners outmigrate, since firms may reduce investment both due to liquidity constraints or distortions to owners\u2019 savings decisions. I compare firms owned by Norwegian individuals subject to the wealth tax with firms owned by foreigners and other tax-exempt entities. By merging historical ownership data from Orbis with the Norwegian shareholder register, I perform these analyses on both Norwegian and foreign-domiciled firms. Across settings, I find no evidence that Norwegian-owned firms pay out more dividends or invest less after the reforms, nor is there any evidence that the reform induced more bankruptcies. These findings indicate that the short-run economic costs of wealth taxation, in terms of migration and firm investment, are more limited than the public debate implies.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35854", "title_zh": "\u5bf9\u521b\u4e1a\u8d22\u5bcc\u5f81\u7a0e\uff1a\u6765\u81ea\u632a\u5a012021\u20132025\u5e74\u7684\u8bc1\u636e", "abstract_zh": "\u662f\u5426\u5bf9\u4f01\u4e1a\u5bb6\u5f81\u6536\u66f4\u9ad8\u7a0e\u7387\u4f1a\u901a\u8fc7\u9650\u5236\u6295\u8d44\u6216\u5f15\u53d1\u8d44\u672c\u5916\u9003\u800c\u5bf9\u5546\u4e1a\u6d3b\u52a8\u4ea7\u751f\u8d1f\u9762\u5f71\u54cd\uff0c\u662f\u5173\u4e8e\u5982\u4f55\u5f81\u7a0e\u8d85\u5bcc\u4eba\u7fa4\u7684\u6301\u7eed\u4e89\u8bba\u4e2d\u7684\u6838\u5fc3\u95ee\u9898\u3002\u4e3a\u4e86\u63d0\u4f9b\u65b0\u7684\u89c1\u89e3\uff0c\u6211\u5229\u75282021\u20132024\u5e74\u95f4\u632a\u5a01\u4e00\u7cfb\u5217\u76f8\u5173\u6539\u9769\u6240\u5f15\u53d1\u7684\u8bc1\u636e\uff0c\u8fd9\u4e9b\u6539\u9769\u63d0\u9ad8\u4e86\u80a1\u606f\u7a0e\u7387\uff0c\u6d88\u9664\u4e86\u4e0e\u79fb\u6c11\u76f8\u5173\u7684\u8d44\u672c\u5229\u5f97\u7a0e\u6f0f\u6d1e\uff0c\u5e76\u5c06\u4f01\u4e1a\u8d22\u5bcc\u7684\u6709\u6548\u8fb9\u9645\u7a0e\u7387\u51e0\u4e4e\u7ffb\u500d\u3002\u8fd9\u4e9b\u6539\u9769\u5f15\u53d1\u4e86\u56fd\u9645\u8fa9\u8bba\uff0c\u751a\u81f3\u88ab\u6307\u5f15\u53d1\u4e86\u201c\u632a\u5a01\u4ebf\u4e07\u5bcc\u7fc1\u7684\u5916\u9003\u201d\uff08Financial Times, 2023\uff09\u3002\u5c3d\u7ba1\u6211\u8bc1\u5b9e\u4e86\u6539\u9769\u5bf9\u79fb\u6c11\u884c\u4e3a\u6709\u660e\u786e\u5f71\u54cd\uff0c\u4f46\u8fd9\u4e9b\u53cd\u5e94\u4e3b\u8981\u96c6\u4e2d\u5728\u8d22\u5bcc\u5206\u5e03\u7684\u524d0.1%\u7fa4\u4f53\u4e2d\uff0c\u4e14\u5927\u591a\u5c40\u9650\u4e8e2022\u548c2023\u5e74\u3002\u6211\u7684\u7814\u7a76\u7ed3\u679c\u663e\u793a\uff0c\u6700\u591a\u4ec5\u6709100\u540d\u4e2a\u4eba\u56e0\u6539\u9769\u800c\u79bb\u5f00\u3002\u6211\u672a\u53d1\u73b0\u663e\u8457\u7684\u79fb\u6c11\u5916\u6d41\u6216\u521d\u521b\u4f01\u4e1a\u521b\u59cb\u4eba\u53ca\u53d1\u660e\u5bb6\u6d41\u5165\u51cf\u5c11\u7684\u8bc1\u636e\u3002\u6211\u4f30\u8ba1\uff0c\u5728\u6ca1\u6709\u79fb\u6c11\u5916\u6d41\u7684\u60c5\u51b5\u4e0b\uff0c2021\u81f32024\u5e74\u95f4\u8d22\u5bcc\u7a0e\u6536\u5165\u5c06\u589e\u52a075%\u3002\u7531\u6539\u9769\u5f15\u53d1\u7684\u79fb\u6c11\u5916\u6d41\u4f7f\u6536\u5165\u589e\u957f\u964d\u81f371.5%\u3002\u6211\u7684\u7814\u7a76\u8fdb\u4e00\u6b65\u8868\u660e\uff0c\u79fb\u6c11\u7684\u516c\u53f8\u4ecd\u4fdd\u6301\u7ecf\u6d4e\u6d3b\u8dc3\uff0c\u672a\u51cf\u5c11\u6295\u8d44\u3002\u5728\u66f4\u5e7f\u6cdb\u7684\u5206\u6790\u4e2d\uff0c\u6211\u8003\u5bdf\u4e86\u65e0\u8bba\u4f01\u4e1a\u6240\u6709\u8005\u662f\u5426\u79fb\u6c11\uff0c\u4f01\u4e1a\u8868\u73b0\u662f\u5426\u53d7\u5230\u5f71\u54cd\uff0c\u56e0\u4e3a\u4f01\u4e1a\u53ef\u80fd\u56e0\u6d41\u52a8\u6027\u7ea6\u675f\u6216\u6240\u6709\u8005\u50a8\u84c4\u51b3\u7b56\u7684\u626d\u66f2\u800c\u51cf\u5c11\u6295\u8d44\u3002\u6211\u6bd4\u8f83\u4e86\u53d7\u8d22\u5bcc\u7a0e\u5f71\u54cd\u7684\u632a\u5a01\u4e2a\u4eba\u6240\u6709\u4f01\u4e1a\u4e0e\u5916\u56fd\u6240\u6709\u8005\u53ca\u5176\u4ed6\u514d\u7a0e\u5b9e\u4f53\u6240\u6709\u4f01\u4e1a\u3002\u901a\u8fc7\u5c06Orbis\u7684\u5386\u53f2\u6240\u6709\u6743\u6570\u636e\u4e0e\u632a\u5a01\u80a1\u4e1c\u767b\u8bb0\u518c\u5408\u5e76\uff0c\u6211\u5bf9\u632a\u5a01\u548c\u5916\u56fd\u6ce8\u518c\u4f01\u4e1a\u8fdb\u884c\u4e86\u8fd9\u4e9b\u5206\u6790\u3002\u5728\u5404\u79cd\u60c5\u5883\u4e0b\uff0c\u6211\u5747\u672a\u53d1\u73b0\u632a\u5a01\u6240\u6709\u4f01\u4e1a\u6539\u9769\u540e\u5206\u7ea2\u589e\u52a0\u6216\u6295\u8d44\u51cf\u5c11\u7684\u8bc1\u636e\uff0c\u4e5f\u672a\u53d1\u73b0\u6539\u9769\u5bfc\u81f4\u4f01\u4e1a\u7834\u4ea7\u589e\u52a0\u7684\u8ff9\u8c61\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u8d22\u5bcc\u5f81\u7a0e\u5728\u77ed\u671f\u5185\u5bf9\u7ecf\u6d4e\u9020\u6210\u7684\u6210\u672c\uff0c\u5982\u79fb\u6c11\u548c\u4f01\u4e1a\u6295\u8d44\u51cf\u5c11\uff0c\u8fdc\u4e0d\u5982\u516c\u4f17\u8ba8\u8bba\u6240\u6697\u793a\u7684\u4e25\u91cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35855", "journal": "NBER", "title": "Physicians' Occupational Licensing and the Quantity-Quality Trade-off", "authors": ["Juan Pablo Atal", "Tom\u00e1s Larroucau", "Pablo Mu\u00f1oz", "Crist\u00f3bal Otero"], "author_details": [{"name": "Juan Pablo Atal", "affiliations": []}, {"name": "Tom\u00e1s Larroucau", "affiliations": []}, {"name": "Pablo Mu\u00f1oz", "affiliations": []}, {"name": "Crist\u00f3bal Otero", "affiliations": []}], "abstract": "Occupational licensing is a widespread quality regulation that potentially increases the quality of labor but reduces its quantity. We provide a theoretical framework to empirically quantify this trade-off in public hospitals, where both clinical quality and physician shortages are critical concerns. Using quasi-exogenous variation driven by a recent and unprecedented migration of physicians to Chile, together with growth in domestic medical schools, we show that more physicians improve patient outcomes, while lower-quality physicians\u2014as measured by licensing exam performance\u2014worsen them. Incorporating these findings into our theoretical framework, we evaluate the implications of locally changing the stringency of the licensing policy.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35855", "title_zh": "\u533b\u751f\u804c\u4e1a\u8bb8\u53ef\u4e0e\u6570\u91cf\u8d28\u91cf\u6743\u8861", "abstract_zh": "\u804c\u4e1a\u8bb8\u53ef\u662f\u4e00\u79cd\u5e7f\u6cdb\u5b58\u5728\u7684\u8d28\u91cf\u76d1\u7ba1\u63aa\u65bd\uff0c\u53ef\u80fd\u63d0\u5347\u52b3\u52a8\u529b\u8d28\u91cf\u4f46\u51cf\u5c11\u5176\u6570\u91cf\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u7406\u8bba\u6846\u67b6\uff0c\u7528\u4e8e\u5728\u516c\u7acb\u533b\u9662\u4e2d\u5b9e\u8bc1\u91cf\u5316\u8fd9\u4e00\u6743\u8861\uff0c\u5176\u4e2d\u4e34\u5e8a\u8d28\u91cf\u548c\u533b\u751f\u77ed\u7f3a\u90fd\u662f\u5173\u952e\u95ee\u9898\u3002\u5229\u7528\u7531\u8fd1\u671f\u4e00\u6b21\u524d\u6240\u672a\u6709\u7684\u533b\u751f\u8fc1\u79fb\u5230\u667a\u5229\u5f15\u53d1\u7684\u51c6\u5916\u751f\u53d8\u5316\uff0c\u4ee5\u53ca\u56fd\u5185\u533b\u5b66\u9662\u6821\u89c4\u6a21\u7684\u6269\u5927\uff0c\u6211\u4eec\u53d1\u73b0\u66f4\u591a\u533b\u751f\u80fd\u591f\u6539\u5584\u60a3\u8005\u7ed3\u679c\uff0c\u800c\u8d28\u91cf\u8f83\u4f4e\u7684\u533b\u751f\u2014\u2014\u4ee5\u6267\u4e1a\u8d44\u683c\u8003\u8bd5\u6210\u7ee9\u8861\u91cf\u2014\u2014\u5219\u4f1a\u6076\u5316\u60a3\u8005\u7ed3\u679c\u3002\u5c06\u8fd9\u4e9b\u53d1\u73b0\u7eb3\u5165\u6211\u4eec\u7684\u7406\u8bba\u6846\u67b6\uff0c\u6211\u4eec\u8bc4\u4f30\u4e86\u5728\u5730\u65b9\u5c42\u9762\u8c03\u6574\u8bb8\u53ef\u653f\u7b56\u4e25\u683c\u7a0b\u5ea6\u7684\u6f5c\u5728\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35856", "journal": "NBER", "title": "Which Workers Left the Labor Force Post-COVID Recession and Why?: Filing, Tax Credit Take-Up, and Labor Force Engagement by Occupation", "authors": ["Andrew C. Barr", "Laura Kawano", "Bruce Sacerdote", "Michael Stevens"], "author_details": [{"name": "Andrew C. Barr", "affiliations": []}, {"name": "Laura Kawano", "affiliations": []}, {"name": "Bruce Sacerdote", "affiliations": []}, {"name": "Michael Stevens", "affiliations": []}], "abstract": "The COVID-19 pandemic caused a sharp initial rise in unemployment, followed by an unexpectedly tight labor market. Using a panel of tax data containing newly assembled information on worker occupation, we document persistent labor force exit, especially among low-income and low-skill workers. Low-skilled unmarried men are by far the most likely to exit, reinforcing recent concerns regarding the economic and social engagement of this group. Contrary to prevailing theories, we find little evidence that school closures, virus exposure, stimulus payments, or unemployment benefits explain these exits. Nor is the exit explained by additional upgrading of occupations or firm quality. Individuals who leave the labor force do not (on average) make up the missing income; however, self-employment income replaces roughly a quarter of the lost W-2 income. The facts suggest that the willingness to work for low pay decreased and preferences for leisure and job flexibility increased among a large set of workers who have found ways to get by with less income. These results have implications for tax policy, fiscal projections, and labor market dynamics in the post-pandemic economy.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35856", "title_zh": "\u65b0\u51a0\u75ab\u60c5\u540e\u54ea\u4e9b\u5de5\u4eba\u79bb\u5f00\u4e86\u52b3\u52a8\u529b\u5e02\u573a\u4ee5\u53ca\u539f\u56e0\u662f\u4ec0\u4e48\uff1f\uff1a\u7533\u62a5\u3001\u7a0e\u6536\u62b5\u514d\u4f7f\u7528\u60c5\u51b5\u53ca\u6309\u804c\u4e1a\u5212\u5206\u7684\u52b3\u52a8\u529b\u53c2\u4e0e\u5ea6", "abstract_zh": "\u65b0\u51a0\u75ab\u60c5\u5bfc\u81f4\u5931\u4e1a\u7387\u6025\u5267\u4e0a\u5347\uff0c\u968f\u540e\u52b3\u52a8\u529b\u5e02\u573a\u610f\u5916\u53d8\u5f97\u7d27\u5f20\u3002\u5229\u7528\u5305\u542b\u65b0\u6536\u96c6\u7684\u5de5\u4eba\u804c\u4e1a\u4fe1\u606f\u7684\u7a0e\u6536\u6570\u636e\u9762\u677f\uff0c\u6211\u4eec\u53d1\u73b0\u52b3\u52a8\u529b\u9000\u51fa\u73b0\u8c61\u6301\u7eed\u5b58\u5728\uff0c\u5c24\u5176\u5728\u4f4e\u6536\u5165\u548c\u4f4e\u6280\u80fd\u5de5\u4eba\u4e2d\u66f4\u4e3a\u660e\u663e\u3002\u4f4e\u6280\u80fd\u672a\u5a5a\u7537\u6027\u662f\u9000\u51fa\u52b3\u52a8\u529b\u5e02\u573a\u7684\u6700\u4e3b\u8981\u7fa4\u4f53\uff0c\u8fd9\u8fdb\u4e00\u6b65\u51f8\u663e\u4e86\u5bf9\u8be5\u7fa4\u4f53\u7ecf\u6d4e\u548c\u793e\u4f1a\u53c2\u4e0e\u5ea6\u7684\u62c5\u5fe7\u3002\u4e0e\u4e3b\u6d41\u7406\u8bba\u76f8\u53cd\uff0c\u6211\u4eec\u53d1\u73b0\u5b66\u6821\u5173\u95ed\u3001\u75c5\u6bd2\u66b4\u9732\u3001\u523a\u6fc0\u91d1\u6216\u5931\u4e1a\u6551\u6d4e\u91d1\u5e76\u4e0d\u80fd\u89e3\u91ca\u8fd9\u4e9b\u9000\u51fa\u884c\u4e3a\u3002\u6b64\u5916\uff0c\u804c\u4e1a\u5347\u7ea7\u6216\u4f01\u4e1a\u8d28\u91cf\u7684\u63d0\u5347\u4e5f\u672a\u80fd\u89e3\u91ca\u8fd9\u4e00\u73b0\u8c61\u3002\u79bb\u5f00\u52b3\u52a8\u529b\u5e02\u573a\u7684\u4e2a\u4f53\u5e73\u5747\u5e76\u672a\u586b\u8865\u6536\u5165\u7f3a\u53e3\uff1b\u7136\u800c\uff0c\u81ea\u96c7\u6536\u5165\u5927\u7ea6\u66ff\u4ee3\u4e86\u5931\u53bb\u7684W-2\u6536\u5165\u7684\u56db\u5206\u4e4b\u4e00\u3002\u8fd9\u4e9b\u4e8b\u5b9e\u8868\u660e\uff0c\u5927\u91cf\u5de5\u4eba\u5bf9\u4f4e\u5de5\u8d44\u5de5\u4f5c\u7684\u610f\u613f\u4e0b\u964d\uff0c\u800c\u5bf9\u4f11\u95f2\u548c\u5de5\u4f5c\u7075\u6d3b\u6027\u7684\u504f\u597d\u4e0a\u5347\u3002\u8fd9\u4e9b\u7ed3\u679c\u5bf9\u75ab\u60c5\u540e\u7a0e\u6536\u653f\u7b56\u3001\u8d22\u653f\u9884\u6d4b\u4ee5\u53ca\u52b3\u52a8\u529b\u5e02\u573a\u52a8\u6001\u5177\u6709\u91cd\u8981\u542f\u793a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35857", "journal": "NBER", "title": "Capital-Skill Complementarity Beyond Firm Boundaries", "authors": ["Gert Bijnens", "Anders Humlum", "Stijn Vanormelingen"], "author_details": [{"name": "Gert Bijnens", "affiliations": []}, {"name": "Anders Humlum", "affiliations": []}, {"name": "Stijn Vanormelingen", "affiliations": []}], "abstract": "New machinery has long been argued to raise the relative demand for skilled labor, yet firm-level evidence finds no such shift at investing firms. We resolve this puzzle by looking beyond firm boundaries. Linking Belgian data on capital investments, buyer\u2013supplier transactions, and worker skills, we show that the skill bias of new machinery arises entirely at external suppliers. Following machinery investment spikes, purchases from suppliers raise firms\u2019 total demand for high-STEM workers by 45%, three times the rise for other skill groups, while in-house hiring raises it by less than 5%, evenly across skill groups. This external demand comes first from machine integrators and later from complementary services such as software, and is stronger for smaller firms, lumpier investments, and rapidly advancing capital, consistent with fixed and adjustment costs of hiring high-STEM workers in-house. In a general-equilibrium model estimated on our event studies, the rise in machinery per worker from 2003 to 2021 raises relative demand for high-STEM workers by 8.8 log points and their wage premium by 3.1. Measured on payrolls alone, both would fall.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35857", "title_zh": "\u8d44\u672c\u4e0e\u6280\u80fd\u4e92\u8865\u6027\u8d85\u8d8a\u4f01\u4e1a\u8fb9\u754c", "abstract_zh": "\u957f\u671f\u4ee5\u6765\uff0c\u65b0\u673a\u5668\u8bbe\u5907\u88ab\u8ba4\u4e3a\u4f1a\u63d0\u9ad8\u5bf9\u9ad8\u6280\u80fd\u52b3\u52a8\u529b\u7684\u9700\u6c42\uff0c\u4f46\u4f01\u4e1a\u5c42\u9762\u7684\u8bc1\u636e\u5374\u672a\u53d1\u73b0\u6295\u8d44\u4f01\u4e1a\u5185\u90e8\u5b58\u5728\u8fd9\u79cd\u9700\u6c42\u53d8\u5316\u3002\u6211\u4eec\u901a\u8fc7\u8d85\u8d8a\u4f01\u4e1a\u8fb9\u754c\u6765\u89e3\u51b3\u8fd9\u4e00\u6096\u8bba\u3002\u5229\u7528\u6bd4\u5229\u65f6\u5173\u4e8e\u8d44\u672c\u6295\u8d44\u3001\u4e70\u65b9-\u4f9b\u5e94\u5546\u4ea4\u6613\u4ee5\u53ca\u5458\u5de5\u6280\u80fd\u7684\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u65b0\u673a\u5668\u8bbe\u5907\u5bf9\u6280\u80fd\u7684\u9700\u6c42\u5b8c\u5168\u4f53\u73b0\u5728\u5916\u90e8\u4f9b\u5e94\u5546\u8eab\u4e0a\u3002\u5728\u673a\u5668\u8bbe\u5907\u6295\u8d44\u6fc0\u589e\u4e4b\u540e\uff0c\u6765\u81ea\u4f9b\u5e94\u5546\u7684\u91c7\u8d2d\u4f7f\u4f01\u4e1a\u5bf9\u9ad8STEM\u6280\u80fd\u5458\u5de5\u7684\u603b\u9700\u6c42\u4e0a\u5347\u4e8645%\uff0c\u662f\u5176\u4ed6\u6280\u80fd\u7fa4\u4f53\u9700\u6c42\u589e\u957f\u7684\u4e09\u500d\uff0c\u800c\u4f01\u4e1a\u5185\u90e8\u62db\u8058\u4ec5\u4f7f\u9700\u6c42\u4e0a\u5347\u4e0d\u52305%\uff0c\u4e14\u5728\u5404\u6280\u80fd\u7fa4\u4f53\u95f4\u5206\u5e03\u5747\u5300\u3002\u8fd9\u79cd\u5916\u90e8\u9700\u6c42\u6700\u521d\u6765\u81ea\u8bbe\u5907\u96c6\u6210\u5546\uff0c\u968f\u540e\u6765\u81ea\u8f6f\u4ef6\u7b49\u914d\u5957\u670d\u52a1\uff0c\u4e14\u5bf9\u89c4\u6a21\u8f83\u5c0f\u7684\u4f01\u4e1a\u3001\u6295\u8d44\u66f4\u4e3a\u5206\u6563\u7684\u4f01\u4e1a\u4ee5\u53ca\u8d44\u672c\u6280\u672f\u5feb\u901f\u8fdb\u6b65\u7684\u4f01\u4e1a\u66f4\u4e3a\u663e\u8457\uff0c\u8fd9\u4e0e\u96c7\u4f63\u9ad8STEM\u6280\u80fd\u5458\u5de5\u6240\u9762\u4e34\u7684\u56fa\u5b9a\u6210\u672c\u548c\u8c03\u6574\u6210\u672c\u76f8\u4e00\u81f4\u3002\u5728\u57fa\u4e8e\u6211\u4eec\u4e8b\u4ef6\u7814\u7a76\u6570\u636e\u4f30\u8ba1\u7684\u4e00\u822c\u5747\u8861\u6a21\u578b\u4e2d\uff0c2003\u5e74\u81f32021\u5e74\u95f4\u4eba\u5747\u673a\u5668\u8bbe\u5907\u6570\u91cf\u7684\u589e\u52a0\u4f7f\u5bf9\u9ad8STEM\u6280\u80fd\u5458\u5de5\u7684\u76f8\u5bf9\u9700\u6c42\u4e0a\u5347\u4e868.8\u4e2a\u5bf9\u6570\u70b9\uff0c\u5176\u5de5\u8d44\u6ea2\u4ef7\u63d0\u9ad8\u4e863.1\u3002\u4f46\u4ec5\u4ece\u5de5\u8d44\u652f\u51fa\u6765\u770b\uff0c\u8fd9\u4e24\u4e2a\u6307\u6807\u5747\u4f1a\u4e0b\u964d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.3386/w35858", "journal": "NBER", "title": "Stressful Exposure from the 2004 Indian Ocean Tsunami Drives Long-term Changes in Thyroid Hormone Physiology", "authors": ["Ralph I. Lawton", "Duncan Thomas", "Elizabeth Frankenberg", "Cecep Sumantri", "Teresa Seeman", "Eileen Crimmins", "Daniel Hochbaum"], "author_details": [{"name": "Ralph I. Lawton", "affiliations": []}, {"name": "Duncan Thomas", "affiliations": []}, {"name": "Elizabeth Frankenberg", "affiliations": []}, {"name": "Cecep Sumantri", "affiliations": []}, {"name": "Teresa Seeman", "affiliations": []}, {"name": "Eileen Crimmins", "affiliations": []}, {"name": "Daniel Hochbaum", "affiliations": []}], "abstract": "Stressful events are associated with long-term adverse health impacts, but the causal mechanisms linking exposures to disease remain poorly understood. One mechanism is persistent changes to hormonal signaling that regulate metabolic homeostasis. We examine the long-term impacts of stress associated with exposure to the 2004 Indian Ocean tsunami on levels of free triiodothyronine (FT3), a circulating measure of biologically active thyroid hormone, using data from the Study of Tsunami Aftermath and Recovery. Biomarkers are measured 20 years post-tsunami in a population-representative sample age 35y+ in 2024 who, at the time of the tsunami, were living along the coast of Aceh, Indonesia, the area hardest-hit by the tsunami. Because respondents were first interviewed before the tsunami and subsequently tracked regardless of migration, the sample avoids selection bias common in long-term disaster studies. We identify the causal effect of tsunami exposure using variation in community-level tsunami mortality, comparing communities within the same sub-district. We find that greater tsunami exposure reduced levels of FT3 20 years later. Exposure also altered relationships between FT3, body composition, and cortisol and increased cardiometabolic risk. These findings identify persistent alteration of thyroid hormone physiology as a potential pathway linking severe stressful exposures to long-term cardiometabolic disease risk.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35858", "title_zh": "2004\u5370\u5ea6\u6d0b\u6d77\u5578\u5e26\u6765\u7684\u538b\u529b\u66b4\u9732\u5f15\u53d1\u7532\u72b6\u817a\u6fc0\u7d20\u751f\u7406\u7684\u957f\u671f\u53d8\u5316", "abstract_zh": "\u538b\u529b\u4e8b\u4ef6\u4e0e\u957f\u671f\u4e0d\u826f\u5065\u5eb7\u5f71\u54cd\u76f8\u5173\uff0c\u4f46\u66b4\u9732\u4e0e\u75be\u75c5\u4e4b\u95f4\u7684\u56e0\u679c\u673a\u5236\u4ecd\u4e0d\u660e\u786e\u3002\u4e00\u79cd\u53ef\u80fd\u7684\u673a\u5236\u662f\u6fc0\u7d20\u4fe1\u53f7\u7684\u6301\u4e45\u6027\u6539\u53d8\uff0c\u8fd9\u4e9b\u6fc0\u7d20\u8c03\u8282\u4ee3\u8c22\u7a33\u6001\u3002\u6211\u4eec\u5229\u7528\u201c\u6d77\u5578\u540e\u5f71\u54cd\u4e0e\u6062\u590d\u7814\u7a76\u201d\u6570\u636e\uff0c\u8003\u5bdf\u4e862004\u5e74\u5370\u5ea6\u6d0b\u6d77\u5578\u66b4\u9732\u4e0e\u81ea\u7531\u4e09\u7898\u7532\u72b6\u817a\u7d20\uff08FT3\uff09\u6c34\u5e73\u4e4b\u95f4\u7684\u957f\u671f\u5f71\u54cd\uff0cFT3\u662f\u751f\u7269\u6d3b\u6027\u7532\u72b6\u817a\u6fc0\u7d20\u7684\u5faa\u73af\u6307\u6807\u3002\u7814\u7a76\u6837\u672c\u4e3a2024\u5e74\u5e74\u9f84\u572835\u5c81\u53ca\u4ee5\u4e0a\u3001\u5728\u6d77\u5578\u53d1\u751f\u65f6\u5c45\u4f4f\u4e8e\u5370\u5ea6\u5c3c\u897f\u4e9a\u4e9a\u9f50\u6d77\u5cb8\uff08\u6d77\u5578\u6700\u4e25\u91cd\u533a\u57df\uff09\u7684\u4ee3\u8868\u6027\u4eba\u7fa4\uff0c\u5176\u751f\u7269\u6807\u5fd7\u7269\u5728\u6d77\u5578\u540e20\u5e74\u8fdb\u884c\u6d4b\u91cf\u3002\u7531\u4e8e\u53d7\u8bbf\u8005\u5728\u6d77\u5578\u524d\u5df2\u63a5\u53d7\u9996\u6b21\u8bbf\u8c08\uff0c\u5e76\u5728\u4e4b\u540e\u65e0\u8bba\u662f\u5426\u8fc1\u79fb\u5747\u88ab\u6301\u7eed\u8ffd\u8e2a\uff0c\u8be5\u6837\u672c\u907f\u514d\u4e86\u957f\u671f\u707e\u96be\u7814\u7a76\u4e2d\u5e38\u89c1\u7684\u9009\u62e9\u504f\u5dee\u3002\u6211\u4eec\u901a\u8fc7\u6bd4\u8f83\u540c\u4e00\u884c\u653f\u533a\u5185\u7684\u793e\u533a\u5c42\u9762\u6d77\u5578\u6b7b\u4ea1\u7387\u5dee\u5f02\uff0c\u8bc6\u522b\u4e86\u6d77\u5578\u66b4\u9732\u7684\u56e0\u679c\u6548\u5e94\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u6d77\u5578\u66b4\u9732\u7a0b\u5ea6\u8d8a\u9ad8\uff0c20\u5e74\u540eFT3\u6c34\u5e73\u8d8a\u4f4e\u3002\u66b4\u9732\u8fd8\u6539\u53d8\u4e86FT3\u4e0e\u4f53\u6210\u5206\u3001\u76ae\u8d28\u9187\u4e4b\u95f4\u7684\u5173\u7cfb\uff0c\u5e76\u589e\u52a0\u4e86\u5fc3\u8840\u7ba1\u4ee3\u8c22\u98ce\u9669\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u4e25\u91cd\u538b\u529b\u66b4\u9732\u5bfc\u81f4\u7532\u72b6\u817a\u6fc0\u7d20\u751f\u7406\u7684\u6301\u4e45\u6027\u6539\u53d8\uff0c\u53ef\u80fd\u662f\u8fde\u63a5\u5267\u70c8\u538b\u529b\u66b4\u9732\u4e0e\u957f\u671f\u5fc3\u8840\u7ba1\u4ee3\u8c22\u75be\u75c5\u98ce\u9669\u7684\u6f5c\u5728\u9014\u5f84\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35859", "journal": "NBER", "title": "How Heavily Are PhD Students Offloading Their Scientific Writing to AI? Evidence from US STEM PhD Dissertations", "authors": ["Daniel P. Gross", "Dror Shvadron", "Hansen Zhang"], "author_details": [{"name": "Daniel P. Gross", "affiliations": []}, {"name": "Dror Shvadron", "affiliations": []}, {"name": "Hansen Zhang", "affiliations": []}], "abstract": "Large language models are diffusing rapidly into science, raising concerns that delegating research writing to AI may undermine the development of expertise that scientific training is supposed to build. We measure AI-generated writing in the dissertations of a near-census of US STEM PhD graduates from 2019 to 2026 and link graduates to their subsequent employment. AI writing is absent before 2023, present in 29% of dissertations filed in 2026, and rapidly growing. Use is more common among students from non-English-speaking countries and at lower-ranked programs. Among graduates in the same program and cohort, those whose dissertations contain AI writing are less likely to enter academic research careers and more likely to enter non-tenure-track roles or industry, with this pattern strongest among US-origin students. At the same time as AI may increase research productivity, it thus appears to also be displacing a potentially important portion of the work through which scientific expertise is developed.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35859", "title_zh": "\u7f8e\u56fdSTEM\u535a\u58eb\u751f\u5c06\u591a\u5c11\u79d1\u5b66\u5199\u4f5c\u5916\u5305\u7ed9AI\uff1f\u6765\u81ea2019\u81f32026\u5e74\u7f8e\u56fdSTEM\u535a\u58eb\u8bba\u6587\u7684\u8bc1\u636e", "abstract_zh": "\u5927\u578b\u8bed\u8a00\u6a21\u578b\u6b63\u8fc5\u901f\u6e17\u900f\u5230\u79d1\u5b66\u9886\u57df\uff0c\u5f15\u53d1\u4eba\u4eec\u62c5\u5fe7\u5c06\u7814\u7a76\u5199\u4f5c\u59d4\u6258\u7ed9AI\u53ef\u80fd\u524a\u5f31\u79d1\u5b66\u8bad\u7ec3\u672c\u5e94\u57f9\u517b\u7684\u4e13\u4e1a\u80fd\u529b\u3002\u6211\u4eec\u5bf92019\u5e74\u81f32026\u5e74\u7f8e\u56fdSTEM\u535a\u58eb\u6bd5\u4e1a\u751f\u7684\u5b66\u4f4d\u8bba\u6587\u8fdb\u884c\u4e86\u6d4b\u91cf\uff0c\u6db5\u76d6\u4e86\u51e0\u4e4e\u5168\u90e8\u7684\u6837\u672c\uff0c\u5e76\u5c06\u5176\u4e0e\u6bd5\u4e1a\u751f\u540e\u7eed\u5c31\u4e1a\u60c5\u51b5\u5173\u8054\u3002\u57282023\u5e74\u4e4b\u524d\uff0c\u8bba\u6587\u4e2d\u672a\u53d1\u73b0AI\u751f\u6210\u7684\u5185\u5bb9\uff1b\u52302026\u5e74\uff0c29%\u7684\u5b66\u4f4d\u8bba\u6587\u4e2d\u51fa\u73b0\u4e86AI\u5199\u4f5c\uff0c\u4e14\u8fd9\u4e00\u4f7f\u7528\u7387\u6b63\u5728\u8fc5\u901f\u4e0a\u5347\u3002\u6765\u81ea\u975e\u82f1\u8bed\u56fd\u5bb6\u7684\u5b66\u751f\u4ee5\u53ca\u6392\u540d\u8f83\u4f4e\u9879\u76ee\u4e2d\u7684\u5b66\u751f\u66f4\u503e\u5411\u4e8e\u4f7f\u7528AI\u5199\u4f5c\u3002\u5728\u540c\u4e00\u6279\u6b21\u548c\u540c\u4e2a\u9879\u76ee\u7684\u6bd5\u4e1a\u751f\u4e2d\uff0c\u90a3\u4e9b\u5b66\u4f4d\u8bba\u6587\u4e2d\u5305\u542bAI\u5199\u4f5c\u7684\u6bd5\u4e1a\u751f\uff0c\u66f4\u5c11\u8fdb\u5165\u5b66\u672f\u7814\u7a76\u804c\u4e1a\uff0c\u800c\u66f4\u53ef\u80fd\u8fdb\u5165\u975e\u7ec8\u8eab\u5236\u804c\u4f4d\u6216\u4ea7\u4e1a\u5c97\u4f4d\uff0c\u8fd9\u4e00\u8d8b\u52bf\u5728\u6765\u81ea\u7f8e\u56fd\u672c\u571f\u7684\u5b66\u751f\u4e2d\u5c24\u4e3a\u660e\u663e\u3002\u56e0\u6b64\uff0c\u5c3d\u7ba1AI\u53ef\u80fd\u63d0\u5347\u7814\u7a76\u4ea7\u51fa\uff0c\u4f46\u5b83\u4f3c\u4e4e\u4e5f\u5728\u53d6\u4ee3\u901a\u8fc7\u79d1\u5b66\u5199\u4f5c\u53d1\u5c55\u4e13\u4e1a\u80fd\u529b\u7684\u91cd\u8981\u73af\u8282\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790", "AI"]}, {"doi": "10.3386/w35860", "journal": "NBER", "title": "Communicating Performance: Textual and Financial Disclosures in Private Equity", "authors": ["Josh Lerner", "Fiona Paine", "Antoinette Schoar"], "author_details": [{"name": "Josh Lerner", "affiliations": []}, {"name": "Fiona Paine", "affiliations": []}, {"name": "Antoinette Schoar", "affiliations": []}], "abstract": "Private capital fund managers appear to possess significant information about the relative quality of their portfolio firms even within the first three years after the investment. But the way this information is disclosed to investors changes dynamically: Textual discussions of portfolio companies have substantial information about the firms\u2019 ultimate performance in the early stages of investment, while interim valuations are less important. Over time, this pattern reverses, with interim valuations becoming more important in explaining future returns, especially after portfolio companies have a financing event. The results vary not only with the tone but also with the content of fund manager disclosures. In an opaque market with substantial information asymmetries, textual discussions seem to serve as a signal about general partner quality.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35860", "title_zh": "\u7ee9\u6548\u6c9f\u901a\uff1a\u79c1\u52df\u80a1\u6743\u4e2d\u7684\u6587\u672c\u4e0e\u8d22\u52a1\u62ab\u9732", "abstract_zh": "\u79c1\u52df\u8d44\u672c\u57fa\u91d1\u7ba1\u7406\u8005\u4f3c\u4e4e\u5728\u6295\u8d44\u540e\u7684\u5934\u4e09\u5e74\u5185\u5c31\u638c\u63e1\u4e86\u5176\u6295\u8d44\u7ec4\u5408\u4f01\u4e1a\u76f8\u5bf9\u8d28\u91cf\u7684\u5927\u91cf\u4fe1\u606f\u3002\u7136\u800c\uff0c\u8fd9\u79cd\u4fe1\u606f\u5411\u6295\u8d44\u8005\u7684\u62ab\u9732\u65b9\u5f0f\u662f\u52a8\u6001\u53d8\u5316\u7684\uff1a\u5728\u6295\u8d44\u521d\u671f\uff0c\u5bf9\u6295\u8d44\u7ec4\u5408\u4f01\u4e1a\u7684\u6587\u672c\u6027\u8ba8\u8bba\u5305\u542b\u4e86\u5927\u91cf\u5173\u4e8e\u4f01\u4e1a\u6700\u7ec8\u8868\u73b0\u7684\u4fe1\u606f\uff0c\u800c\u4e2d\u671f\u4f30\u503c\u7684\u4f5c\u7528\u5219\u76f8\u5bf9\u8f83\u5c0f\u3002\u968f\u7740\u65f6\u95f4\u63a8\u79fb\uff0c\u8fd9\u4e00\u6a21\u5f0f\u53d1\u751f\u9006\u8f6c\uff0c\u4e2d\u671f\u4f30\u503c\u5728\u89e3\u91ca\u672a\u6765\u56de\u62a5\u65b9\u9762\u53d8\u5f97\u66f4\u4e3a\u91cd\u8981\uff0c\u5c24\u5176\u662f\u5728\u6295\u8d44\u7ec4\u5408\u4f01\u4e1a\u53d1\u751f\u878d\u8d44\u4e8b\u4ef6\u4e4b\u540e\u3002\u7814\u7a76\u7ed3\u679c\u4e0d\u4ec5\u53d6\u51b3\u4e8e\u62ab\u9732\u7684\u8bed\u6c14\uff0c\u4e5f\u53d6\u51b3\u4e8e\u62ab\u9732\u7684\u5185\u5bb9\u3002\u5728\u4fe1\u606f\u4e0d\u900f\u660e\u4e14\u5b58\u5728\u663e\u8457\u4fe1\u606f\u4e0d\u5bf9\u79f0\u7684\u5e02\u573a\u4e2d\uff0c\u6587\u672c\u6027\u8ba8\u8bba\u4f3c\u4e4e\u6210\u4e3a\u5173\u4e8e\u4e00\u822c\u5408\u4f19\u4eba\u8d28\u91cf\u7684\u4fe1\u53f7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u6587\u672c\u5206\u6790"]}, {"doi": "10.3386/w35861", "journal": "NBER", "title": "Labor Supply and Wages over the Life Cycle: Human Capital and Disability Benefits", "authors": ["Richard Blundell", "Monica Costa-Dias", "Graham Mazeine", "Costas Meghir", "Tom Waters"], "author_details": [{"name": "Richard Blundell", "affiliations": []}, {"name": "Monica Costa-Dias", "affiliations": []}, {"name": "Graham Mazeine", "affiliations": []}, {"name": "Costas Meghir", "affiliations": []}, {"name": "Tom Waters", "affiliations": []}], "abstract": "Work experience has been found to be a key determinant of work and wages for educated women, but it seems to play a smaller role for the less educated. For them, welfare, tax credits and family composition matter more, and increasingly so does participation in disability programmes. Here we document how labor supply, wages, health, and disability claims have evolved in the UK over the last three decades, and examine how reforms to tax credits, disability benefits and other welfare programs have changed work incentives over this period. We then introduce these features into an empirical dynamic structural model of life-cycle labor supply, human capital and disability benefit application, in which human capital combines health capital, experience accumulated in work, and education. Estimating the model on a panel of working-age women in the UK, we examine the interactions between experience capital and health capital in driving life-cycle earnings across different education groups. Our results highlight the importance of interactions in the disability benefit, welfare and tax-credit systems for understanding the life cycle pattern of hours, employment, earnings, and disability claims, and for evaluating policy counterfactuals.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35861", "title_zh": "\u751f\u547d\u5468\u671f\u5185\u52b3\u52a8\u4f9b\u7ed9\u4e0e\u5de5\u8d44\uff1a\u4eba\u529b\u8d44\u672c\u4e0e\u6b8b\u75be\u798f\u5229", "abstract_zh": "\u5de5\u4f5c\u7ecf\u9a8c\u88ab\u53d1\u73b0\u662f\u53d7\u6559\u80b2\u5973\u6027\u5de5\u4f5c\u548c\u5de5\u8d44\u7684\u5173\u952e\u51b3\u5b9a\u56e0\u7d20\uff0c\u4f46\u5bf9\u4e8e\u6559\u80b2\u7a0b\u5ea6\u8f83\u4f4e\u7684\u7fa4\u4f53\uff0c\u5176\u4f5c\u7528\u5219\u8f83\u5c0f\u3002\u5bf9\u4e8e\u8fd9\u4e9b\u7fa4\u4f53\u800c\u8a00\uff0c\u798f\u5229\u3001\u7a0e\u6536\u62b5\u514d\u548c\u5bb6\u5ead\u7ed3\u6784\u66f4\u4e3a\u91cd\u8981\uff0c\u800c\u53c2\u4e0e\u6b8b\u75be\u8ba1\u5212\u7684\u4f5c\u7528\u4e5f\u65e5\u76ca\u663e\u8457\u3002\u672c\u6587\u8bb0\u5f55\u4e86\u8fc7\u53bb\u4e09\u5341\u5e74\u82f1\u56fd\u52b3\u52a8\u4f9b\u7ed9\u3001\u5de5\u8d44\u3001\u5065\u5eb7\u72b6\u51b5\u4ee5\u53ca\u6b8b\u75be\u7533\u9886\u7684\u53d8\u5316\uff0c\u5e76\u8003\u5bdf\u4e86\u7a0e\u6536\u62b5\u514d\u3001\u6b8b\u75be\u798f\u5229\u53ca\u5176\u4ed6\u798f\u5229\u9879\u76ee\u6539\u9769\u5982\u4f55\u6539\u53d8\u4e86\u5de5\u4f5c\u6fc0\u52b1\u3002\u968f\u540e\uff0c\u6211\u4eec\u5c06\u8fd9\u4e9b\u7279\u5f81\u5f15\u5165\u4e00\u4e2a\u7ecf\u9a8c\u6027\u7684\u52a8\u6001\u7ed3\u6784\u6a21\u578b\u4e2d\uff0c\u8be5\u6a21\u578b\u6db5\u76d6\u4e86\u751f\u547d\u5468\u671f\u5185\u7684\u52b3\u52a8\u4f9b\u7ed9\u3001\u4eba\u529b\u8d44\u672c\uff08\u5305\u62ec\u5065\u5eb7\u8d44\u672c\u3001\u5de5\u4f5c\u79ef\u7d2f\u7684\u7ecf\u9a8c\u548c\u6559\u80b2\uff09\u4ee5\u53ca\u6b8b\u75be\u798f\u5229\u7533\u8bf7\u3002\u57fa\u4e8e\u82f1\u56fd\u6210\u5e74\u5973\u6027\u7684\u9762\u677f\u6570\u636e\u5bf9\u6a21\u578b\u8fdb\u884c\u4f30\u8ba1\uff0c\u6211\u4eec\u5206\u6790\u4e86\u7ecf\u9a8c\u8d44\u672c\u4e0e\u5065\u5eb7\u8d44\u672c\u5728\u4e0d\u540c\u6559\u80b2\u7fa4\u4f53\u4e2d\u5982\u4f55\u5171\u540c\u9a71\u52a8\u751f\u547d\u5468\u671f\u6536\u5165\u6a21\u5f0f\u3002\u7814\u7a76\u7ed3\u679c\u5f3a\u8c03\u4e86\u6b8b\u75be\u798f\u5229\u3001\u798f\u5229\u548c\u7a0e\u6536\u62b5\u514d\u4f53\u7cfb\u4e2d\u76f8\u4e92\u4f5c\u7528\u7684\u91cd\u8981\u6027\uff0c\u5bf9\u4e8e\u7406\u89e3\u52b3\u52a8\u65f6\u95f4\u3001\u5c31\u4e1a\u3001\u6536\u5165\u548c\u6b8b\u75be\u7533\u9886\u7684\u751f\u547d\u5468\u671f\u6a21\u5f0f\uff0c\u4ee5\u53ca\u8bc4\u4f30\u653f\u7b56\u53cd\u4e8b\u5b9e\u60c5\u666f\u5177\u6709\u91cd\u8981\u610f\u4e49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35862", "journal": "NBER", "title": "The Geopolitical Trap: How Great Power Rivalry Protects Rising Powers", "authors": ["Johann Caro-Burnett", "Sebastian Galiani", "Gustavo Torrens"], "author_details": [{"name": "Johann Caro-Burnett", "affiliations": []}, {"name": "Sebastian Galiani", "affiliations": []}, {"name": "Gustavo Torrens", "affiliations": []}], "abstract": "Why do rising powers survive periods in which established states can still suppress them? Existing theories of preventive war emphasize commitment problems between declining and rising states, which can make adverse power shifts especially dangerous. We show that commitment problems among established rivals can have the opposite effect. Preventive action against a rising power can alter the incumbent\u2019s relationship with another state. Under opportunistic rivalry, prevention temporarily exposes the incumbent to exploitation by an existing rival. Under defensive rivalry, successful prevention strengthens the incumbent by eliminating a potential counterweight, giving its rival an incentive to protect the rising state. In both cases, third-party responses can deter preventive action that would occur in an otherwise identical dyadic setting. Cooperation among established powers can reverse this result when credible arrangements allow them to manage the strategic consequences of suppression. Historical evidence from the American Revolution, China\u2019s nuclear emergence, and U.S.\u2013Soviet bargaining over West German nuclear capabilities illustrates the mechanisms and their limits. The analysis shows how rivalry among established powers can protect vulnerable rising states and thereby facilitate changes in the international distribution of power.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35862", "title_zh": "\u5730\u7f18\u653f\u6cbb\u9677\u9631\uff1a\u5927\u56fd\u7ade\u4e89\u5982\u4f55\u4fdd\u62a4\u65b0\u5174\u529b\u91cf", "abstract_zh": "\u4e3a\u4ec0\u4e48\u65b0\u5174\u529b\u91cf\u80fd\u591f\u5728\u73b0\u6709\u56fd\u5bb6\u4ecd\u53ef\u80fd\u538b\u5236\u5b83\u4eec\u7684\u65f6\u671f\u4e2d\u751f\u5b58\u4e0b\u6765\uff1f\u73b0\u6709\u5173\u4e8e\u9884\u9632\u6218\u4e89\u7684\u7406\u8bba\u5f3a\u8c03\u8870\u9000\u56fd\u4e0e\u5d1b\u8d77\u56fd\u4e4b\u95f4\u7684\u627f\u8bfa\u95ee\u9898\uff0c\u8fd9\u53ef\u80fd\u4f7f\u6743\u529b\u8f6c\u79fb\u53d8\u5f97\u5c24\u5176\u5371\u9669\u3002\u6211\u4eec\u8868\u660e\uff0c\u73b0\u6709\u5927\u56fd\u4e4b\u95f4\u7684\u627f\u8bfa\u95ee\u9898\u53cd\u800c\u53ef\u80fd\u4ea7\u751f\u76f8\u53cd\u6548\u679c\u3002\u9488\u5bf9\u65b0\u5174\u529b\u91cf\u7684\u9884\u9632\u884c\u52a8\u53ef\u80fd\u6539\u53d8\u73b0\u6709\u56fd\u5bb6\u4e0e\u5176\u4ed6\u56fd\u5bb6\u4e4b\u95f4\u7684\u5173\u7cfb\u3002\u5728\u673a\u4f1a\u4e3b\u4e49\u7ade\u4e89\u4e2d\uff0c\u9884\u9632\u884c\u52a8\u4f1a\u6682\u65f6\u4f7f\u73b0\u6709\u56fd\u5bb6\u66b4\u9732\u4e8e\u73b0\u6709\u5bf9\u624b\u7684\u5265\u524a\u4e4b\u4e0b\uff1b\u5728\u9632\u5fa1\u6027\u7ade\u4e89\u4e2d\uff0c\u6210\u529f\u9884\u9632\u4f1a\u589e\u5f3a\u73b0\u6709\u56fd\u5bb6\u7684\u5b9e\u529b\uff0c\u6d88\u9664\u6f5c\u5728\u7684\u5236\u8861\u529b\u91cf\uff0c\u4ece\u800c\u6fc0\u52b1\u5176\u5bf9\u624b\u4fdd\u62a4\u65b0\u5174\u529b\u91cf\u3002\u5728\u4e24\u79cd\u60c5\u51b5\u4e0b\uff0c\u7b2c\u4e09\u65b9\u7684\u53cd\u5e94\u90fd\u53ef\u80fd\u963b\u6b62\u5728\u5176\u4ed6\u53cc\u8fb9\u5173\u7cfb\u4e2d\u672c\u4f1a\u53d1\u751f\u7684\u9884\u9632\u884c\u52a8\u3002\u5f53\u73b0\u6709\u5927\u56fd\u4e4b\u95f4\u80fd\u591f\u901a\u8fc7\u53ef\u4fe1\u7684\u5b89\u6392\u7ba1\u7406\u538b\u5236\u884c\u52a8\u7684\u6218\u7565\u540e\u679c\u65f6\uff0c\u8fd9\u79cd\u5408\u4f5c\u53ef\u4ee5\u9006\u8f6c\u4e0a\u8ff0\u7ed3\u679c\u3002\u7f8e\u56fd\u72ec\u7acb\u6218\u4e89\u3001\u4e2d\u56fd\u6838\u80fd\u529b\u7684\u5d1b\u8d77\u4ee5\u53ca\u7f8e\u82cf\u5c31\u897f\u5fb7\u6838\u80fd\u529b\u7684\u8c08\u5224\u7b49\u5386\u53f2\u8bc1\u636e\u8bf4\u660e\u4e86\u8fd9\u4e9b\u673a\u5236\u53ca\u5176\u5c40\u9650\u6027\u3002\u5206\u6790\u8868\u660e\uff0c\u73b0\u6709\u5927\u56fd\u4e4b\u95f4\u7684\u7ade\u4e89\u53ef\u4ee5\u4fdd\u62a4\u8106\u5f31\u7684\u65b0\u5174\u529b\u91cf\uff0c\u4ece\u800c\u4fc3\u8fdb\u56fd\u9645\u6743\u529b\u5206\u5e03\u7684\u8f6c\u53d8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.3386/w35863", "journal": "NBER", "title": "Reassessing the 2000s Housing Cycle After Two Decades of Research", "authors": ["Adam Guren"], "author_details": [{"name": "Adam Guren", "affiliations": []}], "abstract": "What caused the 2000s housing cycle? This article synthesizes two decades of research, including reduced-form empirics and structural models. Although often contentious, the literature coheres once one accounts for each study\u2019s timing, place, methodology, and measurement. The cycle was a perfect storm that occurred in distinct stages. Starting in the late 1990s, fundamentals improved, and credit supply increased across the income distribution due to automated underwriting and financial deregulation. In the early 2000s, a decline in interest rates was followed by a further expansion in securitized and subprime credit, the origin of which remains controversial. This sequence of shocks produced a persistent boom that triggered two shifts in beliefs: average expectations became overly optimistic, pushing prices higher, and expectations diverged, fueling speculation. In the bust, prices overshot primarily due to mortgage defaults, which removed buyers and contracted credit supply. How these forces interact and how expectations form require further research.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35863", "title_zh": "\u5728\u4e8c\u5341\u5e74\u7814\u7a76\u4e4b\u540e\u91cd\u65b0\u5ba1\u89c62000\u5e74\u4ee3\u7684\u4f4f\u623f\u5468\u671f", "abstract_zh": "2000\u5e74\u4ee3\u7684\u4f4f\u623f\u5468\u671f\u662f\u7531\u4ec0\u4e48\u5f15\u8d77\u7684\uff1f\u672c\u6587\u7efc\u5408\u4e86\u4e8c\u5341\u5e74\u6765\u7684\u7814\u7a76\uff0c\u5305\u62ec\u7b80\u5316\u5f62\u5f0f\u7684\u5b9e\u8bc1\u5206\u6790\u548c\u7ed3\u6784\u6a21\u578b\u3002\u5c3d\u7ba1\u8fd9\u4e9b\u7814\u7a76\u5e38\u5e38\u5b58\u5728\u4e89\u8bae\uff0c\u4f46\u4e00\u65e6\u8003\u8651\u5230\u6bcf\u9879\u7814\u7a76\u7684\u65f6\u95f4\u3001\u5730\u70b9\u3001\u65b9\u6cd5\u548c\u6d4b\u91cf\u65b9\u5f0f\uff0c\u6587\u732e\u5c31\u5448\u73b0\u51fa\u4e00\u81f4\u6027\u3002\u8fd9\u4e00\u5468\u671f\u662f\u4e00\u4e2a\u5b8c\u7f8e\u98ce\u66b4\uff0c\u5206\u9636\u6bb5\u53d1\u751f\u3002\u57281990\u5e74\u4ee3\u672b\uff0c\u57fa\u672c\u9762\u6539\u5584\uff0c\u7531\u4e8e\u81ea\u52a8\u5316\u5ba1\u6279\u548c\u91d1\u878d\u53bb\u76d1\u7ba1\uff0c\u4fe1\u8d37\u4f9b\u7ed9\u5728\u4e0d\u540c\u6536\u5165\u7fa4\u4f53\u4e2d\u90fd\u589e\u52a0\u4e86\u30022000\u5e74\u4ee3\u521d\uff0c\u5229\u7387\u4e0b\u964d\uff0c\u968f\u540e\u662f\u8bc1\u5238\u5316\u548c\u6b21\u7ea7\u4fe1\u8d37\u7684\u8fdb\u4e00\u6b65\u6269\u5f20\uff0c\u5176\u8d77\u6e90\u4ecd\u5b58\u5728\u4e89\u8bae\u3002\u8fd9\u4e00\u7cfb\u5217\u51b2\u51fb\u5f15\u53d1\u4e86\u6301\u7eed\u7684\u7e41\u8363\uff0c\u5bfc\u81f4\u4e86\u4e24\u79cd\u4fe1\u5ff5\u7684\u8f6c\u53d8\uff1a\u5e73\u5747\u9884\u671f\u53d8\u5f97\u8fc7\u5ea6\u4e50\u89c2\uff0c\u63a8\u9ad8\u4e86\u4ef7\u683c\uff1b\u9884\u671f\u51fa\u73b0\u5206\u5316\uff0c\u52a9\u957f\u4e86\u6295\u673a\u884c\u4e3a\u3002\u5728\u5d29\u76d8\u9636\u6bb5\uff0c\u4ef7\u683c\u8fc7\u5ea6\u4e0a\u6da8\u4e3b\u8981\u662f\u7531\u4e8e\u62b5\u62bc\u8d37\u6b3e\u8fdd\u7ea6\uff0c\u5bfc\u81f4\u8d2d\u623f\u8005\u51cf\u5c11\uff0c\u4fe1\u8d37\u4f9b\u7ed9\u6536\u7f29\u3002\u8fd9\u4e9b\u529b\u91cf\u5982\u4f55\u76f8\u4e92\u4f5c\u7528\uff0c\u4ee5\u53ca\u9884\u671f\u5982\u4f55\u5f62\u6210\uff0c\u4ecd\u9700\u8fdb\u4e00\u6b65\u7814\u7a76\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35864", "journal": "NBER", "title": "From Importer to Exporter: Oil Shocks and the U.S. Economy", "authors": ["Diego R. K\u00e4nzig", "James H. Stock", "Luca Zanotti"], "author_details": [{"name": "Diego R. K\u00e4nzig", "affiliations": []}, {"name": "James H. Stock", "affiliations": []}, {"name": "Luca Zanotti", "affiliations": []}], "abstract": "We study how the shale revolution and the U.S. transition from petroleum importer to net exporter have changed the macroeconomic effects of oil shocks. Using oil supply news shocks identified from OPEC announcements, a time-varying model of the U.S. macroeconomy shows that the contractionary effects weakened over time and eventually became expansionary. State-dependent local projections link this change to the U.S. petroleum trade balance. The improvement goes beyond mechanical net export effects: as the terms-of-trade response turns more favorable, consumption, equity valuations, and activity strengthen broadly across sectors and regions, pointing to general-equilibrium income and wealth effects. A counterfactual analysis of the 2022 oil price surge implies sharply different paths for U.S. activity, prices, and monetary policy under the propagation mechanisms prevailing before the shale boom vs. the early 2020s.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35864", "title_zh": "\u4ece\u8fdb\u53e3\u56fd\u5230\u51fa\u53e3\u56fd\uff1a\u77f3\u6cb9\u51b2\u51fb\u4e0e\u7f8e\u56fd\u7ecf\u6d4e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u9875\u5ca9\u9769\u547d\u4ee5\u53ca\u7f8e\u56fd\u4ece\u77f3\u6cb9\u8fdb\u53e3\u56fd\u8f6c\u53d8\u4e3a\u51c0\u51fa\u53e3\u56fd\u8fd9\u4e00\u8f6c\u53d8\u5982\u4f55\u6539\u53d8\u4e86\u77f3\u6cb9\u51b2\u51fb\u7684\u5b8f\u89c2\u7ecf\u6d4e\u6548\u5e94\u3002\u5229\u7528\u4eceOPEC\u516c\u544a\u4e2d\u8bc6\u522b\u51fa\u7684\u77f3\u6cb9\u4f9b\u7ed9\u65b0\u95fb\u51b2\u51fb\uff0c\u4e00\u4e2a\u65f6\u53d8\u7684\u7f8e\u56fd\u5b8f\u89c2\u7ecf\u6d4e\u6a21\u578b\u8868\u660e\uff0c\u6536\u7f29\u6548\u5e94\u968f\u65f6\u95f4\u51cf\u5f31\uff0c\u5e76\u6700\u7ec8\u8f6c\u53d8\u4e3a\u6269\u5f20\u6548\u5e94\u3002\u72b6\u6001\u4f9d\u8d56\u7684\u5c40\u90e8\u6295\u5f71\u5c06\u8fd9\u4e00\u53d8\u5316\u4e0e\u7f8e\u56fd\u77f3\u6cb9\u8d38\u6613\u5e73\u8861\u8054\u7cfb\u8d77\u6765\u3002\u8fd9\u79cd\u6539\u5584\u4e0d\u4ec5\u4f53\u73b0\u5728\u673a\u68b0\u6027\u7684\u51c0\u51fa\u53e3\u6548\u5e94\u4e0a\uff1a\u968f\u7740\u8d38\u6613\u6761\u4ef6\u53cd\u5e94\u53d8\u5f97\u66f4\u52a0\u6709\u5229\uff0c\u6d88\u8d39\u3001\u80a1\u6743\u4f30\u503c\u4ee5\u53ca\u5404\u884c\u4e1a\u548c\u5730\u533a\u7684\u6d3b\u52a8\u5747\u5f97\u5230\u52a0\u5f3a\uff0c\u53cd\u6620\u51fa\u4e00\u822c\u5747\u8861\u6536\u5165\u548c\u8d22\u5bcc\u6548\u5e94\u3002\u5bf92022\u5e74\u6cb9\u4ef7\u4e0a\u6da8\u7684\u53cd\u4e8b\u5b9e\u5206\u6790\u8868\u660e\uff0c\u5728\u9875\u5ca9\u9769\u547d\u4e4b\u524d\u548c2020\u5e74\u4ee3\u521d\u671f\u76db\u884c\u7684\u4f20\u64ad\u673a\u5236\u4e0b\uff0c\u7f8e\u56fd\u7ecf\u6d4e\u6d3b\u52a8\u3001\u4ef7\u683c\u548c\u8d27\u5e01\u653f\u7b56\u7684\u8def\u5f84\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35865", "journal": "NBER", "title": "Financing the AI Buildout", "authors": ["Stijn Van Nieuwerburgh"], "author_details": [{"name": "Stijn Van Nieuwerburgh", "affiliations": []}], "abstract": "Artificial intelligence is driving a large expansion in data center capacity, power infrastructure, and specialized computing equipment. We estimate that a 1 GW AI campus costs about $41 billion. A 188 GW U.S. buildout completed by 2032 would require total investment of nearly$9 trillion and amount to annual investment of 3.2 percent of GDP over 2025\u20132032. As hyperscaler capital expenditures outgrow internal cash flow, financing is shifting toward leases, joint ventures, project debt, private credit, securitization, and special-purpose vehicles. These structures expand funding capacity but also raise asset-level leverage, obscure contingent obligations, and expose investors to tenant concentration, technological obsolescence, execution delays, and uncertain residual values.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35865", "title_zh": "\u878d\u8d44\u4eba\u5de5\u667a\u80fd\u5efa\u8bbe", "abstract_zh": "\u4eba\u5de5\u667a\u80fd\u6b63\u5728\u63a8\u52a8\u6570\u636e\u4e2d\u5fc3\u5bb9\u91cf\u3001\u7535\u529b\u57fa\u7840\u8bbe\u65bd\u4ee5\u53ca\u4e13\u7528\u8ba1\u7b97\u8bbe\u5907\u7684\u5927\u5e45\u6269\u5f20\u3002\u6211\u4eec\u4f30\u8ba1\uff0c\u4e00\u4e2a1 GW\u7684\u4eba\u5de5\u667a\u80fd\u56ed\u533a\u6210\u672c\u7ea6\u4e3a410\u4ebf\u7f8e\u5143\u3002\u52302032\u5e74\uff0c\u7f8e\u56fd\u5b8c\u6210188 GW\u7684\u5efa\u8bbe\u5c06\u9700\u8981\u8fd19\u4e07\u4ebf\u7f8e\u5143\u7684\u603b\u6295\u8d44\uff0c\u671f\u95f42025\u81f32032\u5e74\u6bcf\u5e74\u7684\u6295\u8d44\u989d\u5c06\u8fbe\u5230GDP\u76843.2%\u3002\u968f\u7740\u8d85\u5927\u578b\u79d1\u6280\u516c\u53f8\u8d44\u672c\u652f\u51fa\u8d85\u8fc7\u5185\u90e8\u73b0\u91d1\u6d41\uff0c\u878d\u8d44\u6b63\u8f6c\u5411\u79df\u8d41\u3001\u5408\u8d44\u4f01\u4e1a\u3001\u9879\u76ee\u503a\u52a1\u3001\u79c1\u4eba\u4fe1\u8d37\u3001\u8bc1\u5238\u5316\u4ee5\u53ca\u7279\u6b8a\u76ee\u7684\u5b9e\u4f53\u3002\u8fd9\u4e9b\u878d\u8d44\u7ed3\u6784\u867d\u7136\u6269\u5927\u4e86\u8d44\u91d1\u6765\u6e90\uff0c\u4f46\u4e5f\u63d0\u9ad8\u4e86\u8d44\u4ea7\u5c42\u9762\u7684\u6760\u6746\u7387\uff0c\u6a21\u7cca\u4e86\u6216\u6709\u8d1f\u503a\uff0c\u4f7f\u6295\u8d44\u8005\u9762\u4e34\u79df\u6237\u96c6\u4e2d\u3001\u6280\u672f\u8fc7\u65f6\u3001\u6267\u884c\u5ef6\u8fdf\u4ee5\u53ca\u6b8b\u503c\u4e0d\u786e\u5b9a\u7b49\u98ce\u9669\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.3386/w35866", "journal": "NBER", "title": "Gang Crackdowns", "authors": ["Nikita Melnikov", "Carlos Schmidt-Padilla", "Mar\u00eda Micaela Sviatschi"], "author_details": [{"name": "Nikita Melnikov", "affiliations": []}, {"name": "Carlos Schmidt-Padilla", "affiliations": []}, {"name": "Mar\u00eda Micaela Sviatschi", "affiliations": []}], "abstract": "What are the consequences of restoring state authority in territories governed by criminal organizations? Combining household surveys and administrative records with detailed maps of former gang-controlled areas, we study how El Salvador\u2019s 2022 State of Exception, which ended two decades of gang territorial control, reshaped Salvadoran society. We find that the removal of gang control integrated previously segmented labor markets, improving mobility, employment outcomes, household income, and financial inclusion. Areas with greater pre-2022 gang exposure also experienced larger increases in business formation and property investment. However, the legacy of criminal governance persists through residence-based discrimination: employers remain less willing to hire otherwise identical applicants from former gang-controlled neighborhoods. Finally, although overall support for the crackdowns remains high, individuals who witnessed police abuse report substantially greater distrust of the police and the national government, suggesting that abuses of state authority may undermine the political sustainability of tough-on-crime policies.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35866", "title_zh": "\u6253\u51fb\u5e2e\u6d3e\u884c\u52a8", "abstract_zh": "\u6062\u590d\u56fd\u5bb6\u6743\u529b\u5728\u72af\u7f6a\u7ec4\u7ec7\u63a7\u5236\u7684\u5730\u533a\u4f1a\u4ea7\u751f\u600e\u6837\u7684\u540e\u679c\uff1f\u7ed3\u5408\u5bb6\u5ead\u8c03\u67e5\u548c\u884c\u653f\u8bb0\u5f55\uff0c\u4ee5\u53ca\u5bf9\u524d\u5e2e\u6d3e\u63a7\u5236\u533a\u57df\u7684\u8be6\u7ec6\u5730\u56fe\uff0c\u6211\u4eec\u7814\u7a76\u4e86\u8428\u5c14\u74e6\u591a2022\u5e74\u201c\u7d27\u6025\u72b6\u6001\u201d\u653f\u7b56\u5bf9\u8428\u5c14\u74e6\u591a\u793e\u4f1a\u7684\u5f71\u54cd\uff0c\u8be5\u653f\u7b56\u7ed3\u675f\u4e86\u957f\u8fbe\u4e8c\u5341\u5e74\u7684\u5e2e\u6d3e\u5730\u533a\u63a7\u5236\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5e2e\u6d3e\u63a7\u5236\u7684\u89e3\u9664\u4f7f\u6b64\u524d\u5206\u5272\u7684\u52b3\u52a8\u529b\u5e02\u573a\u5b9e\u73b0\u4e86\u6574\u5408\uff0c\u63d0\u5347\u4e86\u52b3\u52a8\u529b\u6d41\u52a8\u6027\u3001\u5c31\u4e1a\u72b6\u51b5\u3001\u5bb6\u5ead\u6536\u5165\u548c\u91d1\u878d\u5305\u5bb9\u6027\u3002\u57282022\u5e74\u524d\u5e2e\u6d3e\u6d3b\u52a8\u66f4\u4e25\u91cd\u7684\u5730\u533a\uff0c\u4f01\u4e1a\u6210\u7acb\u548c\u623f\u5730\u4ea7\u6295\u8d44\u7684\u589e\u957f\u4e5f\u66f4\u4e3a\u663e\u8457\u3002\u7136\u800c\uff0c\u72af\u7f6a\u6cbb\u7406\u7684\u9057\u7559\u95ee\u9898\u4ecd\u901a\u8fc7\u57fa\u4e8e\u5c45\u4f4f\u5730\u7684\u6b67\u89c6\u6301\u7eed\u5b58\u5728\uff1a\u96c7\u4e3b\u5bf9\u6765\u81ea\u524d\u5e2e\u6d3e\u63a7\u5236\u533a\u57df\u7684\u3001\u5176\u4ed6\u6761\u4ef6\u5b8c\u5168\u76f8\u540c\u7684\u6c42\u804c\u8005\u4ecd\u8868\u73b0\u51fa\u66f4\u4f4e\u7684\u96c7\u4f63\u610f\u613f\u3002\u5c3d\u7ba1\u603b\u4f53\u4e0a\u516c\u4f17\u5bf9\u6253\u51fb\u884c\u52a8\u7684\u652f\u6301\u7387\u8f83\u9ad8\uff0c\u4f46\u66fe\u76ee\u7779\u8b66\u5bdf\u6ee5\u7528\u6743\u529b\u7684\u4e2a\u4f53\u5bf9\u8b66\u5bdf\u548c\u56fd\u5bb6\u653f\u5e9c\u7684\u4e0d\u4fe1\u4efb\u7a0b\u5ea6\u663e\u8457\u66f4\u9ad8\uff0c\u8fd9\u8868\u660e\u56fd\u5bb6\u6743\u529b\u7684\u6ee5\u7528\u53ef\u80fd\u524a\u5f31\u5f3a\u786c\u53cd\u72af\u7f6a\u653f\u7b56\u7684\u653f\u6cbb\u53ef\u6301\u7eed\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35867", "journal": "NBER", "title": "The Investment Channel of Monetary Policy: Disentangling Firm Heterogeneity", "authors": ["Thomas Drechsel", "Daniel Lewis", "Davide Melcangi", "Laura Pilossoph"], "author_details": [{"name": "Thomas Drechsel", "affiliations": []}, {"name": "Daniel Lewis", "affiliations": []}, {"name": "Davide Melcangi", "affiliations": []}, {"name": "Laura Pilossoph", "affiliations": []}], "abstract": "To study monetary policy transmission at the firm level, researchers typically consider heterogeneity along a small number of firm characteristics, such as size or leverage. We instead estimate the full distribution of firms\u2019 investment responses to monetary policy, using a clustering regression framework. Our novel approach captures multidimensional and unobservable heterogeneity across firms and time. We find that investment by most firms in most time periods responds little to monetary policy. Only about 5% of firm-time observations are associated with a strong response. We then investigate the sources of heterogeneity ex post. We find that most of the variation in investment sensitivity arises within firms over time. Although several firm characteristics predict responsiveness to monetary policy, the majority of heterogeneity remains unexplained by firm observables. We demonstrate that our empirical estimates provide new targets for disciplining structural models of firm heterogeneity.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35867", "title_zh": "\u8d27\u5e01\u653f\u7b56\u7684\u6295\u8d44\u6e20\u9053\uff1a\u5206\u79bb\u4f01\u4e1a\u5f02\u8d28\u6027", "abstract_zh": "\u4e3a\u4e86\u7814\u7a76\u8d27\u5e01\u653f\u7b56\u5728\u4f01\u4e1a\u5c42\u9762\u7684\u4f20\u5bfc\u673a\u5236\uff0c\u7814\u7a76\u4eba\u5458\u901a\u5e38\u53ea\u8003\u8651\u5c11\u6570\u51e0\u4e2a\u4f01\u4e1a\u7279\u5f81\u4e0a\u7684\u5f02\u8d28\u6027\uff0c\u4f8b\u5982\u4f01\u4e1a\u89c4\u6a21\u6216\u8d1f\u503a\u7387\u3002\u6211\u4eec\u5219\u91c7\u7528\u805a\u7c7b\u56de\u5f52\u6846\u67b6\uff0c\u4f30\u8ba1\u4f01\u4e1a\u6295\u8d44\u5bf9\u8d27\u5e01\u653f\u7b56\u53cd\u5e94\u7684\u5b8c\u6574\u5206\u5e03\u3002\u6211\u4eec\u7684\u65b0\u65b9\u6cd5\u6355\u6349\u4e86\u4f01\u4e1a\u5728\u4e0d\u540c\u7ef4\u5ea6\u548c\u65f6\u95f4\u4e0a\u7684\u4e0d\u53ef\u89c2\u6d4b\u5f02\u8d28\u6027\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u5927\u591a\u6570\u65f6\u671f\u548c\u5927\u591a\u6570\u4f01\u4e1a\u4e2d\uff0c\u6295\u8d44\u5bf9\u8d27\u5e01\u653f\u7b56\u7684\u53cd\u5e94\u975e\u5e38\u5fae\u5f31\uff0c\u4ec5\u6709\u7ea65%\u7684\u4f01\u4e1a\u65f6\u95f4\u89c2\u6d4b\u503c\u4e0e\u5f3a\u70c8\u7684\u53cd\u5e94\u76f8\u5173\u3002\u968f\u540e\uff0c\u6211\u4eec\u5bf9\u5f02\u8d28\u6027\u7684\u6765\u6e90\u8fdb\u884c\u4e86\u4e8b\u540e\u5206\u6790\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u4f01\u4e1a\u6295\u8d44\u654f\u611f\u5ea6\u7684\u5927\u90e8\u5206\u53d8\u5316\u6e90\u4e8e\u4f01\u4e1a\u81ea\u8eab\u968f\u65f6\u95f4\u7684\u53d8\u5316\u3002\u5c3d\u7ba1\u591a\u4e2a\u4f01\u4e1a\u7279\u5f81\u80fd\u591f\u9884\u6d4b\u5176\u5bf9\u8d27\u5e01\u653f\u7b56\u7684\u654f\u611f\u6027\uff0c\u4f46\u5927\u90e8\u5206\u5f02\u8d28\u6027\u4ecd\u65e0\u6cd5\u7531\u53ef\u89c2\u6d4b\u7684\u4f01\u4e1a\u7279\u5f81\u89e3\u91ca\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u6211\u4eec\u7684\u5b9e\u8bc1\u4f30\u8ba1\u4e3a\u7ed3\u6784\u5316\u4f01\u4e1a\u5f02\u8d28\u6027\u6a21\u578b\u63d0\u4f9b\u4e86\u65b0\u7684\u6821\u51c6\u76ee\u6807\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35868", "journal": "NBER", "title": "Optimal Line-Drawing for Legal Rules", "authors": ["Jacob Goldin", "David Weisbach"], "author_details": [{"name": "Jacob Goldin", "affiliations": []}, {"name": "David Weisbach", "affiliations": []}], "abstract": "Line drawing is a pervasive feature of legal systems. Across many domains, the applicable legal treatment turns on whether an activity falls above or below some threshold. We characterize the economic forces that determine the optimal placement of such thresholds, both generally and in specific legal settings involving monetary and non-monetary sanctions, prohibitions, and mandates. We apply our results to two important line-drawing questions in private law: the optimal due-care threshold for negligence liability and the optimal threshold for whether a shortfall in contract performance constitutes breach. In both applications, the optimal line takes the form of a population-level marginal cost-benefit rule, with the relevant costs and benefits weighted over the actors whose behavior the line induces to change.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35868", "title_zh": "\u6cd5\u5f8b\u89c4\u5219\u4e2d\u9608\u503c\u8bbe\u5b9a\u7684\u6700\u4f18\u9009\u62e9", "abstract_zh": "\u9608\u503c\u8bbe\u5b9a\u662f\u6cd5\u5f8b\u4f53\u7cfb\u4e2d\u7684\u666e\u904d\u7279\u5f81\u3002\u5728\u8bb8\u591a\u9886\u57df\u4e2d\uff0c\u9002\u7528\u7684\u6cd5\u5f8b\u5904\u7406\u65b9\u5f0f\u53d6\u51b3\u4e8e\u67d0\u9879\u6d3b\u52a8\u662f\u5426\u9ad8\u4e8e\u6216\u4f4e\u4e8e\u67d0\u4e2a\u9608\u503c\u3002\u6211\u4eec\u523b\u753b\u4e86\u51b3\u5b9a\u6b64\u7c7b\u9608\u503c\u6700\u4f18\u4f4d\u7f6e\u7684\u7ecf\u6d4e\u529b\u91cf\uff0c\u65e2\u4ece\u4e00\u822c\u5c42\u9762\uff0c\u4e5f\u4ece\u6d89\u53ca\u8d27\u5e01\u6027\u4e0e\u975e\u8d27\u5e01\u6027\u5236\u88c1\u3001\u7981\u6b62\u548c\u5f3a\u5236\u63aa\u65bd\u7684\u5177\u4f53\u6cd5\u5f8b\u60c5\u5883\u4e2d\u8fdb\u884c\u5206\u6790\u3002\u6211\u4eec\u5c06\u7814\u7a76\u6210\u679c\u5e94\u7528\u4e8e\u79c1\u6cd5\u4e2d\u7684\u4e24\u4e2a\u91cd\u8981\u9608\u503c\u95ee\u9898\uff1a\u8fc7\u5931\u8d23\u4efb\u4e2d\u6700\u4f18\u7684\u8c28\u614e\u4e49\u52a1\u9608\u503c\uff0c\u4ee5\u53ca\u5408\u540c\u5c65\u884c\u4e0d\u8db3\u662f\u5426\u6784\u6210\u8fdd\u7ea6\u7684\u6700\u4f18\u9608\u503c\u3002\u5728\u4e24\u4e2a\u5e94\u7528\u4e2d\uff0c\u6700\u4f18\u9608\u503c\u5747\u8868\u73b0\u4e3a\u4e00\u4e2a\u7fa4\u4f53\u5c42\u9762\u7684\u8fb9\u9645\u6210\u672c-\u6536\u76ca\u89c4\u5219\uff0c\u5176\u4e2d\u76f8\u5173\u6210\u672c\u548c\u6536\u76ca\u6839\u636e\u9608\u503c\u5f15\u53d1\u884c\u4e3a\u6539\u53d8\u7684\u4e3b\u4f53\u8fdb\u884c\u52a0\u6743\u8ba1\u7b97\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.3386/w35869", "journal": "NBER", "title": "Voluntary Corporate Climate Targets in a Patchwork Policy Landscape", "authors": ["Joseph E. Aldy", "Michael W. Toffel", "Alison J. Ong", "Lavender Yang"], "author_details": [{"name": "Joseph E. Aldy", "affiliations": []}, {"name": "Michael W. Toffel", "affiliations": []}, {"name": "Alison J. Ong", "affiliations": []}, {"name": "Lavender Yang", "affiliations": []}], "abstract": "Many large, publicly-traded companies adopt voluntary greenhouse gas emission reduction commitments in the presence of a fragmented public policy landscape. To explore the potential emission implications of such commitments, we develop a framework for understanding how firms\u2019 voluntary emission targets interact with carbon pricing, regulatory mandates, subsidies, and heterogeneous policies across political jurisdictions. This analysis highlights the difficulty of distinguishing incremental voluntary emission abatement from policy-induced emission reductions. We introduce the Salata Institute Corporate Climate Targets Database, which we produced from public domain reports published by Russell 3000 firms over 2000-2024. The database documents the growth, form, scope, and sectoral distribution of voluntary greenhouse gas emission targets, including net-zero, carbon-neutral, carbon-reduction, energy-related, and qualitative commitments. Comparing this database with CDP, a non-profit organization formerly known as the Carbon Disclosure Project and the most common source of corporate emission targets used in the research literature, reveals substantial omissions in their survey-based data, especially in recent years. We show that voluntary corporate targets often mirror government-established goals and public policies, and some firms benchmark their internal carbon prices to existing carbon taxes and emission trading systems. The paper concludes by outlining empirical challenges and future research needs for evaluating the emission impacts of voluntary commitments.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35869", "title_zh": "\u5728\u653f\u7b56\u788e\u7247\u5316\u80cc\u666f\u4e0b\u7684\u4f01\u4e1a\u81ea\u613f\u6c14\u5019\u76ee\u6807", "abstract_zh": "\u8bb8\u591a\u5927\u578b\u4e0a\u5e02\u516c\u53f8\u5728\u516c\u5171\u653f\u7b56\u788e\u7247\u5316\u7684\u80cc\u666f\u4e0b\u91c7\u7eb3\u4e86\u81ea\u613f\u7684\u6e29\u5ba4\u6c14\u4f53\u51cf\u6392\u627f\u8bfa\u3002\u4e3a\u4e86\u63a2\u8ba8\u6b64\u7c7b\u627f\u8bfa\u53ef\u80fd\u5e26\u6765\u7684\u51cf\u6392\u5f71\u54cd\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6846\u67b6\uff0c\u7528\u4ee5\u7406\u89e3\u4f01\u4e1a\u81ea\u613f\u51cf\u6392\u76ee\u6807\u5982\u4f55\u4e0e\u78b3\u5b9a\u4ef7\u3001\u76d1\u7ba1\u8981\u6c42\u3001\u8865\u8d34\u4ee5\u53ca\u4e0d\u540c\u653f\u6cbb\u8f96\u533a\u7684\u5f02\u8d28\u6027\u653f\u7b56\u76f8\u4e92\u4f5c\u7528\u3002\u8be5\u5206\u6790\u51f8\u663e\u4e86\u533a\u5206\u81ea\u613f\u51cf\u6392\u4e0e\u653f\u7b56\u5bfc\u81f4\u7684\u51cf\u6392\u4e4b\u95f4\u7684\u96be\u5ea6\u3002\u6211\u4eec\u5f15\u5165\u4e86\u8428\u62c9\u5854\u7814\u7a76\u6240\u4f01\u4e1a\u6c14\u5019\u76ee\u6807\u6570\u636e\u5e93\uff0c\u8be5\u6570\u636e\u5e93\u57fa\u4e8e2000\u5e74\u81f32024\u5e74\u95f4Russell 3000\u6307\u6570\u516c\u53f8\u516c\u5f00\u53d1\u5e03\u7684\u62a5\u544a\u6784\u5efa\u800c\u6210\u3002\u6570\u636e\u5e93\u8bb0\u5f55\u4e86\u81ea\u613f\u6e29\u5ba4\u6c14\u4f53\u51cf\u6392\u76ee\u6807\u7684\u589e\u957f\u3001\u5f62\u5f0f\u3001\u8303\u56f4\u53ca\u884c\u4e1a\u5206\u5e03\uff0c\u5305\u62ec\u51c0\u96f6\u6392\u653e\u3001\u78b3\u4e2d\u548c\u3001\u78b3\u51cf\u6392\u3001\u80fd\u6e90\u76f8\u5173\u4ee5\u53ca\u5b9a\u6027\u627f\u8bfa\u3002\u5c06\u8be5\u6570\u636e\u5e93\u4e0eCDP\uff08\u539f\u79f0\u78b3\u62ab\u9732\u9879\u76ee\uff0c\u662f\u7814\u7a76\u6587\u732e\u4e2d\u6700\u5e38\u7528\u7684\u516c\u53f8\u51cf\u6392\u76ee\u6807\u6765\u6e90\uff09\u8fdb\u884c\u5bf9\u6bd4\uff0c\u53d1\u73b0\u5176\u57fa\u4e8e\u8c03\u67e5\u7684\u6570\u636e\u5b58\u5728\u663e\u8457\u9057\u6f0f\uff0c\u5c24\u5176\u662f\u5728\u8fd1\u5e74\u6765\u3002\u6211\u4eec\u8868\u660e\uff0c\u4f01\u4e1a\u7684\u81ea\u613f\u76ee\u6807\u5f80\u5f80\u4e0e\u653f\u5e9c\u8bbe\u5b9a\u7684\u76ee\u6807\u548c\u516c\u5171\u653f\u7b56\u76f8\u547c\u5e94\uff0c\u90e8\u5206\u4f01\u4e1a\u8fd8\u5c06\u5185\u90e8\u78b3\u4ef7\u683c\u57fa\u51c6\u4e8e\u73b0\u6709\u7684\u78b3\u7a0e\u548c\u6392\u653e\u4ea4\u6613\u4f53\u7cfb\u3002\u672c\u6587\u6700\u540e\u6982\u8ff0\u4e86\u8bc4\u4f30\u81ea\u613f\u627f\u8bfa\u51cf\u6392\u5f71\u54cd\u6240\u9762\u4e34\u7684\u5b9e\u8bc1\u6311\u6218\u53ca\u672a\u6765\u7814\u7a76\u9700\u6c42\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35870", "journal": "NBER", "title": "Aligning Platform and User Incentives in Social Media Age Restrictions", "authors": ["Leonardo Bursztyn", "Rafael Jim\u00e9nez-Dur\u00e1n", "Aaron Leonard", "Filip Milojevi\u0107", "Christopher Roth"], "author_details": [{"name": "Leonardo Bursztyn", "affiliations": []}, {"name": "Rafael Jim\u00e9nez-Dur\u00e1n", "affiliations": []}, {"name": "Aaron Leonard", "affiliations": []}, {"name": "Filip Milojevi\u0107", "affiliations": []}, {"name": "Christopher Roth", "affiliations": []}], "abstract": "Several countries are adopting social media bans for teenagers, yet early evidence suggests limited adherence to the age-based restrictions. Such bans ask platforms to remove profitable customers and teens to give up access to their online social networks. We study an alternative regulatory regime in which platforms remain liable for teens on the adult tier but may offer a safe tier that removes restricted features, such as algorithmic feeds, while preserving interactions with their relevant network. Provision of the safe tier and enforcement are complementary: teens can adhere without giving up access to their network, and platforms can retain displaced adult-tier users as lower-margin customers. This policy design makes the teen decision to avoid the adult tier less dependent on peer dynamics and increases teen welfare for a relevant range of regulatory penalties.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35870", "title_zh": "\u5728\u793e\u4ea4\u5a92\u4f53\u5e74\u9f84\u9650\u5236\u4e2d\u5bf9\u5e73\u53f0\u4e0e\u7528\u6237\u6fc0\u52b1\u7684\u5bf9\u9f50", "abstract_zh": "\u591a\u4e2a\u56fd\u5bb6\u6b63\u5728\u5b9e\u65bd\u9488\u5bf9\u9752\u5c11\u5e74\u7684\u793e\u4ea4\u5a92\u4f53\u7981\u4ee4\uff0c\u4f46\u65e9\u671f\u8bc1\u636e\u8868\u660e\uff0c\u8fd9\u4e9b\u57fa\u4e8e\u5e74\u9f84\u7684\u9650\u5236\u6267\u884c\u60c5\u51b5\u6709\u9650\u3002\u6b64\u7c7b\u7981\u4ee4\u8981\u6c42\u5e73\u53f0\u5254\u9664\u76c8\u5229\u5ba2\u6237\uff0c\u800c\u9752\u5c11\u5e74\u5219\u9700\u653e\u5f03\u5bf9\u5728\u7ebf\u793e\u4ea4\u7f51\u7edc\u7684\u8bbf\u95ee\u3002\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u79cd\u66ff\u4ee3\u6027\u76d1\u7ba1\u5236\u5ea6\uff0c\u5373\u5e73\u53f0\u4ecd\u9700\u5bf9\u9752\u5c11\u5e74\u5728\u6210\u4eba\u5c42\u7ea7\u4e0a\u7684\u4f7f\u7528\u8d1f\u8d23\uff0c\u4f46\u53ef\u4ee5\u63d0\u4f9b\u4e00\u4e2a\u5b89\u5168\u5c42\u7ea7\uff0c\u8be5\u5c42\u7ea7\u79fb\u9664\u53d7\u9650\u529f\u80fd\uff08\u5982\u7b97\u6cd5\u63a8\u8350\u6d41\uff09\uff0c\u540c\u65f6\u4fdd\u7559\u4e0e\u76f8\u5173\u7f51\u7edc\u7684\u4e92\u52a8\u3002\u5b89\u5168\u5c42\u7ea7\u7684\u63d0\u4f9b\u4e0e\u76d1\u7ba1\u6267\u884c\u5177\u6709\u4e92\u8865\u6027\uff1a\u9752\u5c11\u5e74\u53ef\u4ee5\u5728\u4e0d\u653e\u5f03\u7f51\u7edc\u8bbf\u95ee\u7684\u60c5\u51b5\u4e0b\u9009\u62e9\u907f\u5f00\u6210\u4eba\u5c42\u7ea7\uff0c\u5e73\u53f0\u4e5f\u80fd\u5c06\u88ab\u8f6c\u79fb\u7684\u6210\u4eba\u5c42\u7ea7\u7528\u6237\u4fdd\u7559\u4e3a\u4f4e\u5229\u6da6\u5ba2\u6237\u3002\u8fd9\u79cd\u653f\u7b56\u8bbe\u8ba1\u4f7f\u9752\u5c11\u5e74\u907f\u514d\u6210\u4eba\u5c42\u7ea7\u7684\u51b3\u5b9a\u4e0d\u518d\u8fc7\u5ea6\u4f9d\u8d56\u540c\u4f34\u5f71\u54cd\uff0c\u5e76\u5728\u4e00\u5b9a\u8303\u56f4\u5185\u7684\u76d1\u7ba1\u5904\u7f5a\u4e0b\u63d0\u5347\u9752\u5c11\u5e74\u7684\u798f\u5229\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.3386/w35871", "journal": "NBER", "title": "The Effects of Long-Term Exposure to Pollution on Health", "authors": ["Joshua S. Graff Zivin", "Johnny Huynh", "Timothy Frank Justicz", "Adriana Lleras-Muney", "Matthew J. Neidell"], "author_details": [{"name": "Joshua S. Graff Zivin", "affiliations": []}, {"name": "Johnny Huynh", "affiliations": []}, {"name": "Timothy Frank Justicz", "affiliations": []}, {"name": "Adriana Lleras-Muney", "affiliations": []}, {"name": "Matthew J. Neidell", "affiliations": []}], "abstract": "We provide the first causal evidence on how long-term exposure to fine particulate matter (PM2.5) at contemporary ambient levels contributes to the development of chronic disease in a young, initially healthy population. Our analysis links detailed personnel records for roughly 150,000 U.S. Army soldiers to high-resolution annual measures of PM2.5. Because soldiers enter service exceptionally healthy and receive uniform access to care, new diagnoses reflect pollution\u2019s physiological impact rather than preexisting conditions or differential health care access. They are also required to relocate based on the needs of the Army, which provides us with quasi-random variation in initial duty-station assignments that we use as an instrument for average annual pollution exposure over a soldier\u2019s career. We find that sustained PM2.5 exposure substantially increases circulatory disease, particularly hypertension, with mixed evidence on respiratory conditions that are sensitive to specification. Exposure over shorter durations, by contrast, has little detectable effect, a pattern consistent with the cumulative nature of pollution\u2019s health burden. These findings demonstrate that even moderate long-term exposure to air pollution can erode health capital in ways that are invisible to studies focused on short-run variations or mortality alone, and they highlight the importance of regulatory standards that account for chronic exposure risks.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35871", "title_zh": "\u957f\u671f\u66b4\u9732\u4e8e\u6c61\u67d3\u5bf9\u5065\u5eb7\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u9996\u6b21\u63d0\u4f9b\u4e86\u5173\u4e8e\u957f\u671f\u66b4\u9732\u4e8e\u5f53\u4ee3\u73af\u5883\u6c34\u5e73\u4e0b\u7684\u7ec6\u9897\u7c92\u7269\uff08PM2.5\uff09\u5982\u4f55\u5bfc\u81f4\u5e74\u8f7b\u4e14\u521d\u59cb\u5065\u5eb7\u4eba\u7fa4\u4e2d\u6162\u6027\u75be\u75c5\u53d1\u5c55\u7684\u56e0\u679c\u8bc1\u636e\u3002\u6211\u4eec\u7684\u5206\u6790\u5c06\u5927\u7ea615\u4e07\u540d\u7f8e\u56fd\u9646\u519b\u58eb\u5175\u7684\u8be6\u7ec6\u4eba\u4e8b\u8bb0\u5f55\u4e0e\u9ad8\u5206\u8fa8\u7387\u7684\u5e74\u5ea6PM2.5\u6570\u636e\u76f8\u8054\u7cfb\u3002\u7531\u4e8e\u58eb\u5175\u5165\u4f0d\u65f6\u8eab\u4f53\u72b6\u51b5\u6781\u4e3a\u5065\u5eb7\uff0c\u5e76\u4e14\u4eab\u6709\u7edf\u4e00\u7684\u533b\u7597\u4fdd\u969c\uff0c\u65b0\u8bca\u65ad\u7684\u75be\u75c5\u53cd\u6620\u4e86\u6c61\u67d3\u5bf9\u8eab\u4f53\u7684\u751f\u7406\u5f71\u54cd\uff0c\u800c\u975e\u65e2\u5b58\u5065\u5eb7\u95ee\u9898\u6216\u533b\u7597\u8d44\u6e90\u83b7\u53d6\u7684\u5dee\u5f02\u3002\u6b64\u5916\uff0c\u58eb\u5175\u9700\u6839\u636e\u519b\u961f\u9700\u8981\u8fdb\u884c\u8c03\u52a8\uff0c\u8fd9\u4e3a\u6211\u4eec\u63d0\u4f9b\u4e86\u521d\u59cb\u9a7b\u5730\u5206\u914d\u7684\u51c6\u968f\u673a\u53d8\u5f02\uff0c\u6211\u4eec\u5c06\u5176\u4f5c\u4e3a\u58eb\u5175\u804c\u4e1a\u751f\u6daf\u4e2d\u5e73\u5747\u5e74\u6c61\u67d3\u66b4\u9732\u6c34\u5e73\u7684\u5de5\u5177\u53d8\u91cf\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u6301\u7eed\u7684PM2.5\u66b4\u9732\u663e\u8457\u589e\u52a0\u4e86\u5faa\u73af\u7cfb\u7edf\u75be\u75c5\uff0c\u5c24\u5176\u662f\u9ad8\u8840\u538b\uff0c\u800c\u5728\u547c\u5438\u7cfb\u7edf\u75be\u75c5\u7684\u8bc1\u636e\u4e0a\u5219\u5b58\u5728\u4e0d\u4e00\u81f4\u7684\u60c5\u51b5\uff0c\u4e14\u8fd9\u4e9b\u7ed3\u679c\u5bf9\u6a21\u578b\u8bbe\u5b9a\u654f\u611f\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u77ed\u671f\u66b4\u9732\u5219\u51e0\u4e4e\u6ca1\u6709\u53ef\u68c0\u6d4b\u5230\u7684\u5f71\u54cd\uff0c\u8fd9\u4e00\u6a21\u5f0f\u4e0e\u6c61\u67d3\u5065\u5eb7\u8d1f\u62c5\u7684\u7d2f\u79ef\u6027\u4e00\u81f4\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u5373\u4f7f\u662f\u5728\u4e2d\u7b49\u6c34\u5e73\u7684\u957f\u671f\u7a7a\u6c14\u6c61\u67d3\u66b4\u9732\u4e0b\uff0c\u4e5f\u53ef\u80fd\u4ee5\u4e0d\u53ef\u89c1\u7684\u65b9\u5f0f\u4fb5\u8680\u5065\u5eb7\u8d44\u672c\uff0c\u800c\u90a3\u4e9b\u4ec5\u5173\u6ce8\u77ed\u671f\u53d8\u5316\u6216\u6b7b\u4ea1\u7387\u7684\u7814\u7a76\u5f80\u5f80\u65e0\u6cd5\u6355\u6349\u5230\u8fd9\u79cd\u5f71\u54cd\uff0c\u540c\u65f6\u4e5f\u51f8\u663e\u4e86\u9700\u8981\u8003\u8651\u957f\u671f\u66b4\u9732\u98ce\u9669\u7684\u76d1\u7ba1\u6807\u51c6\u7684\u91cd\u8981\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35872", "journal": "NBER", "title": "Estimating Heterogeneous Impacts with Endogenous Participation and Non-Compliance", "authors": ["Orazio Attanasio", "Lina Cardona-Sosa", "Ziqian Liu"], "author_details": [{"name": "Orazio Attanasio", "affiliations": []}, {"name": "Lina Cardona-Sosa", "affiliations": []}, {"name": "Ziqian Liu", "affiliations": []}], "abstract": "This paper considers the estimation of heterogeneous impacts within a Randomized Controlled Trial (RCT) in a situation where heterogeneous status is endogenous and is not fully observed in the control sample. We show how to use information in the treatment sample and a noisy signal on the heterogeneous status to estimate meaningful impacts under a minimal set of assumptions. We provide an application of this approach to a data set from Ghana, collected around a clustered RCT to evaluate the impacts of an early-years intervention, differentiating the impact between households that participate actively in the program from those who participate only passively, as recipients. We show that, for some outcomes, the properly estimated heterogeneous impacts differ substantially from those computed with a naive estimator.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35872", "title_zh": "\u5728\u5185\u751f\u53c2\u4e0e\u548c\u975e\u5408\u89c4\u60c5\u51b5\u4e0b\u7684\u5f02\u8d28\u6027\u5f71\u54cd\u4f30\u8ba1", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5728\u968f\u673a\u5bf9\u7167\u8bd5\u9a8c\uff08RCT\uff09\u4e2d\uff0c\u5f53\u5f02\u8d28\u72b6\u6001\u662f\u5185\u751f\u4e14\u5728\u5bf9\u7167\u7ec4\u6837\u672c\u4e2d\u672a\u5b8c\u5168\u89c2\u6d4b\u5230\u65f6\uff0c\u5982\u4f55\u4f30\u8ba1\u5f02\u8d28\u6027\u5f71\u54cd\u3002\u6211\u4eec\u5c55\u793a\u4e86\u5982\u4f55\u5229\u7528\u5904\u7406\u7ec4\u6837\u672c\u4e2d\u7684\u4fe1\u606f\u4ee5\u53ca\u4e00\u4e2a\u5173\u4e8e\u5f02\u8d28\u72b6\u6001\u7684\u566a\u58f0\u4fe1\u53f7\uff0c\u5728\u6700\u5c11\u91cf\u7684\u5047\u8bbe\u6761\u4ef6\u4e0b\uff0c\u4f30\u8ba1\u6709\u610f\u4e49\u7684\u5f71\u54cd\u3002\u6211\u4eec\u4ee5\u6765\u81ea\u52a0\u7eb3\u7684\u4e00\u4e2a\u6570\u636e\u96c6\u4e3a\u4f8b\uff0c\u8be5\u6570\u636e\u96c6\u662f\u56f4\u7ed5\u4e00\u4e2a\u5206\u7ec4\u968f\u673a\u5bf9\u7167\u8bd5\u9a8c\u6536\u96c6\u7684\uff0c\u7528\u4e8e\u8bc4\u4f30\u65e9\u671f\u5e72\u9884\u63aa\u65bd\u7684\u5f71\u54cd\uff0c\u5e76\u533a\u5206\u4e86\u79ef\u6781\u53c2\u4e0e\u8ba1\u5212\u7684\u5bb6\u5ead\u4e0e\u4ec5\u4f5c\u4e3a\u53d7\u76ca\u8005\u88ab\u52a8\u53c2\u4e0e\u7684\u5bb6\u5ead\u4e4b\u95f4\u7684\u5dee\u5f02\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5bf9\u4e8e\u67d0\u4e9b\u7ed3\u679c\uff0c\u901a\u8fc7\u6b63\u786e\u4f30\u8ba1\u7684\u5f02\u8d28\u6027\u5f71\u54cd\u4e0e\u4f7f\u7528\u7b80\u5355\u4f30\u8ba1\u5668\u8ba1\u7b97\u7684\u7ed3\u679c\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35873", "journal": "NBER", "title": "In Utero Exposure to the 1982 Tylenol Recall and Neurodevelopmental Outcomes", "authors": ["Christopher M. Worsham", "Charles Bray", "Joshua Rothman", "Brian Kwan", "Anupam Jena"], "author_details": [{"name": "Christopher M. Worsham", "affiliations": []}, {"name": "Charles Bray", "affiliations": []}, {"name": "Joshua Rothman", "affiliations": []}, {"name": "Brian Kwan", "affiliations": []}, {"name": "Anupam Jena", "affiliations": []}], "abstract": "Observational research into the relationship between maternal acetaminophen use during pregnancy and a child\u2019s subsequent risk of attention deficit hyperactivity disorder (ADHD) or autism has been limited by confounding factors. Using two large national U.S. insurance claims databases and a novel natural experiment, we assessed differences in prevalence of ADHD and autism among children whose gestational periods were impacted by a nationwide Tylenol recall issued in 1982, following deaths from Tylenol capsules containing potassium cyanide. Prevalence of ADHD and autism was not significantly different in birth cohorts exposed to the recall during gestation, when maternal acetaminophen use would have been reduced; interrupted time series models showed no significant differences compared to underlying temporal diagnostic trends. These findings are inconsistent with a clinically meaningful effect of maternal acetaminophen use on subsequent development of neurodevelopmental disorders.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35873", "title_zh": "\u5b55\u671f\u66b4\u9732\u4e8e1982\u5e74\u6cf0\u8bfa\u53ec\u56de\u4e8b\u4ef6\u4e0e\u795e\u7ecf\u53d1\u80b2\u7ed3\u679c", "abstract_zh": "\u5173\u4e8e\u5b55\u671f\u6bcd\u4eb2\u4f7f\u7528\u5bf9\u4e59\u9170\u6c28\u57fa\u915a\u4e0e\u513f\u7ae5\u65e5\u540e\u60a3\u6ce8\u610f\u529b\u7f3a\u9677\u591a\u52a8\u969c\u788d\uff08ADHD\uff09\u6216\u81ea\u95ed\u75c7\u4e4b\u95f4\u5173\u7cfb\u7684\u89c2\u5bdf\u6027\u7814\u7a76\uff0c\u957f\u671f\u53d7\u5230\u6df7\u6742\u56e0\u7d20\u7684\u9650\u5236\u3002\u5229\u7528\u4e24\u4e2a\u5927\u578b\u7f8e\u56fd\u56fd\u5bb6\u4fdd\u9669\u7d22\u8d54\u6570\u636e\u5e93\u548c\u4e00\u4e2a\u65b0\u9896\u7684\u81ea\u7136\u5b9e\u9a8c\uff0c\u6211\u4eec\u8bc4\u4f30\u4e86\u57281982\u5e74\u56e0\u6cf0\u8bfa\u80f6\u56ca\u4e2d\u542b\u6709\u6c30\u5316\u94be\u800c\u5f15\u53d1\u5168\u56fd\u6027\u53ec\u56de\u4e8b\u4ef6\u671f\u95f4\uff0c\u5b55\u671f\u53d7\u5230\u5f71\u54cd\u7684\u513f\u7ae5\u7fa4\u4f53\u4e2dADHD\u548c\u81ea\u95ed\u75c7\u7684\u60a3\u75c5\u7387\u5dee\u5f02\u3002\u5728\u6bcd\u4eb2\u5bf9\u4e59\u9170\u6c28\u57fa\u915a\u4f7f\u7528\u53ef\u80fd\u56e0\u6b64\u51cf\u5c11\u7684\u5b55\u671f\u5185\uff0cADHD\u548c\u81ea\u95ed\u75c7\u7684\u60a3\u75c5\u7387\u5e76\u672a\u663e\u8457\u5347\u9ad8\uff1b\u4e2d\u65ad\u65f6\u95f4\u5e8f\u5217\u6a21\u578b\u663e\u793a\uff0c\u4e0e\u57fa\u7840\u65f6\u95f4\u8bca\u65ad\u8d8b\u52bf\u76f8\u6bd4\uff0c\u672a\u89c2\u5bdf\u5230\u663e\u8457\u5dee\u5f02\u3002\u8fd9\u4e9b\u53d1\u73b0\u4e0e\u6bcd\u4f53\u5bf9\u4e59\u9170\u6c28\u57fa\u915a\u4f7f\u7528\u5bf9\u540e\u4ee3\u795e\u7ecf\u53d1\u80b2\u969c\u788d\u4ea7\u751f\u4e34\u5e8a\u610f\u4e49\u5f71\u54cd\u7684\u8bf4\u6cd5\u76f8\u77db\u76fe\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35874", "journal": "NBER", "title": "Tax Planning and Multinational Behavior", "authors": ["Rosanne Altshuler", "Lysle Boller", "Kevin A. Roberts", "Juan Carlos Su\u00e1rez Serrato"], "author_details": [{"name": "Rosanne Altshuler", "affiliations": []}, {"name": "Lysle Boller", "affiliations": []}, {"name": "Kevin A. Roberts", "affiliations": []}, {"name": "Juan Carlos Su\u00e1rez Serrato", "affiliations": []}], "abstract": "We use newly linked IRS data to study how US multinationals use tax-planning structures that exploit mismatches between US and foreign tax laws. In 2016, these structures accounted for 36% of foreign profits despite being adopted by only 18% of firms. We develop and estimate a structural model using adoption patterns and changes in foreign effective tax rates, domestic and foreign investment, and global R&D following adoption. The model implies substantial heterogeneity in adoption costs and benefits and shows that restricting tax planning creates tradeoffs between tax revenue and economic activity that are amplified by global R&D linkages.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35874", "title_zh": "\u7a0e\u52a1\u7b79\u5212\u4e0e\u8de8\u56fd\u884c\u4e3a", "abstract_zh": "\u6211\u4eec\u5229\u7528\u65b0\u8fde\u63a5\u7684\u7f8e\u56fd\u56fd\u7a0e\u5c40\uff08IRS\uff09\u6570\u636e\uff0c\u7814\u7a76\u7f8e\u56fd\u8de8\u56fd\u4f01\u4e1a\u5982\u4f55\u5229\u7528\u7f8e\u56fd\u4e0e\u5916\u56fd\u7a0e\u6cd5\u4e4b\u95f4\u7684\u4e0d\u5339\u914d\u6765\u8bbe\u8ba1\u7a0e\u52a1\u7b79\u5212\u7ed3\u6784\u30022016\u5e74\uff0c\u8fd9\u4e9b\u7ed3\u6784\u5360\u5916\u56fd\u5229\u6da6\u768436%\uff0c\u5c3d\u7ba1\u4ec5\u670918%\u7684\u4f01\u4e1a\u91c7\u7528\u4e86\u6b64\u7c7b\u7ed3\u6784\u3002\u6211\u4eec\u6784\u5efa\u5e76\u4f30\u8ba1\u4e86\u4e00\u4e2a\u7ed3\u6784\u6a21\u578b\uff0c\u57fa\u4e8e\u4f01\u4e1a\u91c7\u7528\u8fd9\u4e9b\u7ed3\u6784\u7684\u6a21\u5f0f\u4ee5\u53ca\u5916\u56fd\u6709\u6548\u7a0e\u7387\u7684\u53d8\u5316\u3001\u56fd\u5185\u548c\u56fd\u5916\u6295\u8d44\u3001\u4ee5\u53ca\u5168\u7403\u7814\u53d1\u6d3b\u52a8\u7684\u53d8\u5316\u3002\u6a21\u578b\u8868\u660e\uff0c\u4f01\u4e1a\u5728\u91c7\u7528\u7a0e\u52a1\u7b79\u5212\u7ed3\u6784\u65f6\u5b58\u5728\u663e\u8457\u7684\u91c7\u7528\u6210\u672c\u4e0e\u6536\u76ca\u5dee\u5f02\uff0c\u5e76\u663e\u793a\u9650\u5236\u7a0e\u52a1\u7b79\u5212\u4f1a\u5f15\u53d1\u7a0e\u6536\u6536\u5165\u4e0e\u7ecf\u6d4e\u6d3b\u52a8\u4e4b\u95f4\u7684\u6743\u8861\uff0c\u800c\u8fd9\u79cd\u6743\u8861\u5728\u4f01\u4e1a\u5168\u7403\u7814\u53d1\u8054\u52a8\u80cc\u666f\u4e0b\u88ab\u8fdb\u4e00\u6b65\u653e\u5927\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35875", "journal": "NBER", "title": "High and Rising Institutional Concentration of Award-Winning Economists", "authors": ["Richard B. Freeman", "Danxia Xie", "Hanzhe Zhang", "Hanzhang Zhou"], "author_details": [{"name": "Richard B. Freeman", "affiliations": []}, {"name": "Danxia Xie", "affiliations": []}, {"name": "Hanzhe Zhang", "affiliations": []}, {"name": "Hanzhang Zhou", "affiliations": []}], "abstract": "We analyze the academic affiliations of nearly 6,000 award-winning researchers in 18 major fields in the natural sciences, engineering, and social sciences from the 1820s to the 2020s, focusing on the 1960s onward. The analysis reveals a trend of declining concentration in the institutional affiliations of award-winning researchers, shifting from a few science-strong universities in high-income countries to a more diverse set of institutions across the world. The decline in concentration is observed in all fields except one: economics. The institutional affiliations of prizewinning economists have become more concentrated over time, making economics the most concentrated field. We associate the higher concentration of prizewinning work in economics with the field\u2019s stronger sorting by institutional prestige, its lower reliance on specialized equipment and instruments, and its assessment of findings based on a synthesis of evidence rather than on decisive experiments or proofs. We discuss the benefits and costs of this high and rising institutional concentration of prizewinning economists.", "date": "2026-10-05", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://www.nber.org/papers/w35875", "title_zh": "\u83b7\u5956\u7ecf\u6d4e\u5b66\u5bb6\u673a\u6784\u96c6\u4e2d\u5ea6\u9ad8\u4e14\u6301\u7eed\u4e0a\u5347", "abstract_zh": "\u6211\u4eec\u5206\u6790\u4e861820\u5e74\u81f32020\u5e74\u95f418\u4e2a\u4e3b\u8981\u81ea\u7136\u79d1\u5b66\u3001\u5de5\u7a0b\u5b66\u548c\u793e\u4f1a\u79d1\u5b66\u9886\u57df\u8fd16000\u540d\u83b7\u5956\u7814\u7a76\u4eba\u5458\u7684\u5b66\u672f affiliations\uff0c\u91cd\u70b9\u5173\u6ce81960\u5e74\u4ee3\u4ee5\u6765\u7684\u60c5\u51b5\u3002\u5206\u6790\u53d1\u73b0\uff0c\u9664\u7ecf\u6d4e\u5b66\u5916\uff0c\u6240\u6709\u9886\u57df\u7684\u83b7\u5956\u7814\u7a76\u4eba\u5458\u673a\u6784\u96c6\u4e2d\u5ea6\u5747\u5448\u4e0b\u964d\u8d8b\u52bf\uff0c\u4ece\u9ad8\u6536\u5165\u56fd\u5bb6\u5c11\u6570\u4ee5\u79d1\u5b66\u89c1\u957f\u7684\u5927\u5b66\uff0c\u8f6c\u5411\u5168\u7403\u66f4\u5e7f\u6cdb\u7684\u673a\u6784\u5206\u5e03\u3002\u7136\u800c\uff0c\u7ecf\u6d4e\u5b66\u9886\u57df\u7684\u83b7\u5956\u7814\u7a76\u4eba\u5458\u673a\u6784\u96c6\u4e2d\u5ea6\u5374\u968f\u65f6\u95f4\u63a8\u79fb\u800c\u4e0a\u5347\uff0c\u6210\u4e3a\u96c6\u4e2d\u5ea6\u6700\u9ad8\u7684\u9886\u57df\u3002\u6211\u4eec\u6307\u51fa\uff0c\u7ecf\u6d4e\u5b66\u9886\u57df\u83b7\u5956\u6210\u679c\u7684\u9ad8\u96c6\u4e2d\u5ea6\u6e90\u4e8e\u8be5\u9886\u57df\u5bf9\u673a\u6784\u58f0\u671b\u7684\u66f4\u5f3a\u7b5b\u9009\u3001\u5bf9\u4e13\u7528\u8bbe\u5907\u548c\u4eea\u5668\u7684\u8f83\u4f4e\u4f9d\u8d56\uff0c\u4ee5\u53ca\u5bf9\u7814\u7a76\u7ed3\u679c\u7684\u8bc4\u4f30\u66f4\u4f9d\u8d56\u4e8e\u8bc1\u636e\u7684\u7efc\u5408\u5206\u6790\uff0c\u800c\u975e\u51b3\u5b9a\u6027\u5b9e\u9a8c\u6216\u8bc1\u660e\u3002\u6211\u4eec\u8ba8\u8bba\u4e86\u8fd9\u79cd\u9ad8\u4e14\u6301\u7eed\u4e0a\u5347\u7684\u83b7\u5956\u7ecf\u6d4e\u5b66\u5bb6\u673a\u6784\u96c6\u4e2d\u5ea6\u6240\u5e26\u6765\u7684\u76ca\u5904\u4e0e\u6210\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240651", "journal": "AER", "title": "A Model of the Attention Economy: Data, Platforms, and Discovery", "authors": ["Daniel Chen"], "author_details": [{"name": "Daniel Chen", "affiliations": ["Assistant Professor of Economics, Princeton University (email: )"]}], "abstract": "This paper develops a dynamic model of the attention economy featuring two interlinked markets: a product market, where consumers have limited awareness of firms, and an attention market, where platforms attract attention by investing in free services (e.g., social media, streaming, podcasts) and sell targeted ads using data on consumer preferences. The model provides a tractable framework in which platform investment, ad-driven discovery, product demand, and ad revenue are jointly determined. The effects of data and interoperability policies can reverse over time, platform quality may be inefficiently high or low, and the rise of data-rich digital advertising can coincide with a declining ad revenue-to-GDP ratio. (JEL D43, D44, D58, D83, L86, M37)", "date": "2026-10-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1257/aer.20240651", "title_zh": "\u6ce8\u610f\u529b\u7ecf\u6d4e\u6a21\u578b\uff1a\u6570\u636e\u3001\u5e73\u53f0\u4e0e\u53d1\u73b0", "abstract_zh": "\u672c\u6587\u6784\u5efa\u4e86\u4e00\u4e2a\u52a8\u6001\u7684\u6ce8\u610f\u529b\u7ecf\u6d4e\u6a21\u578b\uff0c\u5305\u542b\u4e24\u4e2a\u76f8\u4e92\u5173\u8054\u7684\u5e02\u573a\uff1a\u4ea7\u54c1\u5e02\u573a\uff0c\u5176\u4e2d\u6d88\u8d39\u8005\u5bf9\u4f01\u4e1a\u7f3a\u4e4f\u5145\u5206\u4e86\u89e3\uff1b\u4ee5\u53ca\u6ce8\u610f\u529b\u5e02\u573a\uff0c\u5e73\u53f0\u901a\u8fc7\u6295\u8d44\u514d\u8d39\u670d\u52a1\uff08\u5982\u793e\u4ea4\u5a92\u4f53\u3001\u6d41\u5a92\u4f53\u3001\u64ad\u5ba2\uff09\u5438\u5f15\u6ce8\u610f\u529b\uff0c\u5e76\u5229\u7528\u6d88\u8d39\u8005\u504f\u597d\u6570\u636e\u8fdb\u884c\u5b9a\u5411\u5e7f\u544a\u6295\u653e\u3002\u8be5\u6a21\u578b\u63d0\u4f9b\u4e86\u4e00\u4e2a\u53ef\u64cd\u4f5c\u7684\u6846\u67b6\uff0c\u7528\u4e8e\u5171\u540c\u786e\u5b9a\u5e73\u53f0\u6295\u8d44\u3001\u5e7f\u544a\u9a71\u52a8\u7684\u53d1\u73b0\u3001\u4ea7\u54c1\u9700\u6c42\u4ee5\u53ca\u5e7f\u544a\u6536\u5165\u3002\u6570\u636e\u548c\u4e92\u64cd\u4f5c\u6027\u653f\u7b56\u7684\u6548\u679c\u53ef\u80fd\u968f\u65f6\u95f4\u9006\u8f6c\uff0c\u5e73\u53f0\u8d28\u91cf\u53ef\u80fd\u88ab\u4f4e\u6548\u5730\u9ad8\u4f30\u6216\u4f4e\u4f30\uff0c\u6570\u636e\u4e30\u5bcc\u7684\u6570\u5b57\u5e7f\u544a\u5174\u8d77\u53ef\u80fd\u4e0e\u5e7f\u544a\u6536\u5165\u5360GDP\u6bd4\u7387\u7684\u4e0b\u964d\u540c\u65f6\u53d1\u751f\u3002\uff08JEL D43, D44, D58, D83, L86, M37\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20241596", "journal": "AER", "title": "Taxing Top Wealth: Migration Responses and Their Aggregate Economic Implications", "authors": ["Katrine Jakobsen", "Henrik Kleven", "Jonas Kolsrud", "Camille Landais", "Mathilde Munoz"], "author_details": [{"name": "Katrine Jakobsen", "affiliations": ["University of Copenhagen (email: )"]}, {"name": "Henrik Kleven", "affiliations": ["Princeton University, NBER, and CEPR (email: )"]}, {"name": "Jonas Kolsrud", "affiliations": ["Linnaeus University and RFBerlin ()"]}, {"name": "Camille Landais", "affiliations": ["London School of Economics and CEPR (email: )"]}, {"name": "Mathilde Munoz", "affiliations": ["UC Berkeley, NBER, and CEPR (email: )"]}], "abstract": "Using administrative data from Scandinavian countries, we provide evidence on international migration responses to wealth taxes and evaluate their aggregate economic implications. We find significant migration responses among the wealthy: A 1 percentage point increase in the top wealth tax rate decreases the stock of wealthy taxpayers by about 2 percent. A large fraction of the wealthy are business owners, and their businesses are negatively affected by owner out-migration. The aggregate effects are nevertheless modest: The migration responses to a 1 percentage point increase in the top wealth tax rate reduce employment by 0.02 percent, investments by 0.07 percent, and value added by 0.10 percent. (JEL D31, E22, E24, F22, H24, L26, K34)", "date": "2026-10-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1257/aer.20241596", "title_zh": "\u5bf9\u9876\u5c42\u8d22\u5bcc\u5f81\u7a0e\u7684\u8fc1\u79fb\u53cd\u5e94\u53ca\u5176\u603b\u4f53\u7ecf\u6d4e\u5f71\u54cd", "abstract_zh": "\u5229\u7528\u5317\u6b27\u56fd\u5bb6\u7684\u884c\u653f\u6570\u636e\uff0c\u6211\u4eec\u63d0\u4f9b\u4e86\u5173\u4e8e\u8d22\u5bcc\u7a0e\u5bf9\u56fd\u9645\u8fc1\u79fb\u53cd\u5e94\u7684\u8bc1\u636e\uff0c\u5e76\u8bc4\u4f30\u4e86\u5176\u603b\u4f53\u7ecf\u6d4e\u5f71\u54cd\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8d22\u5bcc\u9636\u5c42\u5b58\u5728\u663e\u8457\u7684\u8fc1\u79fb\u53cd\u5e94\uff1a\u9876\u5c42\u8d22\u5bcc\u7a0e\u7a0e\u7387\u6bcf\u63d0\u9ad81\u4e2a\u767e\u5206\u70b9\uff0c\u5bcc\u88d5\u7eb3\u7a0e\u4eba\u6570\u91cf\u5c06\u51cf\u5c11\u7ea62%\u3002\u5927\u91cf\u5bcc\u88d5\u4eba\u7fa4\u662f\u4f01\u4e1a\u4e3b\uff0c\u5176\u4f01\u4e1a\u4e3b\u7684\u8fc1\u51fa\u5bf9\u4f01\u4e1a\u7684\u7ecf\u8425\u4ea7\u751f\u8d1f\u9762\u5f71\u54cd\u3002\u7136\u800c\uff0c\u603b\u4f53\u7ecf\u6d4e\u5f71\u54cd\u8f83\u4e3a\u6709\u9650\uff1a\u8d22\u5bcc\u7a0e\u7a0e\u7387\u6bcf\u63d0\u9ad81\u4e2a\u767e\u5206\u70b9\u6240\u5f15\u53d1\u7684\u8fc1\u79fb\u53cd\u5e94\uff0c\u4f7f\u5c31\u4e1a\u51cf\u5c110.02%\uff0c\u6295\u8d44\u51cf\u5c110.07%\uff0c\u589e\u52a0\u503c\u51cf\u5c110.10%\u3002\uff08JEL D31, E22, E24, F22, H24, L26, K34\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20250115", "journal": "AER", "title": "Who Marries Whom? The Role of Segregation by Race and Class", "authors": ["Benjamin Goldman", "Jamie Gracie", "Sonya R. Porter"], "author_details": [{"name": "Benjamin Goldman", "affiliations": ["Cornell University (email: )"]}, {"name": "Jamie Gracie", "affiliations": ["Harvard University (email: )"]}, {"name": "Sonya R. Porter", "affiliations": ["US Census Bureau (email: )"]}], "abstract": "Americans rarely marry outside their race or class group, a pattern with well-documented implications for inequality and intergenerational mobility. Limited exposure may partly explain these low intergroup marriage rates. We instrument for exposure using variation in childhood neighborhoods based on whether other race and class groups had more opposite-sex children of similar age. Exposure increases interclass (high- and low-parent income) marriage but has no detectable effect on interracial (White and Black) marriage. A spatial marriage model predicts that residential segregation\u2014one of many forms of exposure\u2014accounts for more than one-third of marital sorting by class but less than 5 percent by race. (JEL J12, J15, J62, R23)", "date": "2026-10-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1257/aer.20250115", "title_zh": "\u8c01\u5a36\u8c01\uff1f\u79cd\u65cf\u4e0e\u9636\u7ea7\u5206\u79bb\u7684\u4f5c\u7528", "abstract_zh": "\u7f8e\u56fd\u4eba\u5f88\u5c11\u4e0e\u4e0d\u540c\u79cd\u65cf\u6216\u9636\u7ea7\u7684\u4eba\u7ed3\u5a5a\uff0c\u8fd9\u4e00\u73b0\u8c61\u5bf9\u4e0d\u5e73\u7b49\u548c\u4ee3\u9645\u6d41\u52a8\u6027\u6709\u7740\u660e\u786e\u7684\u5f71\u54cd\u3002\u6709\u9650\u7684\u63a5\u89e6\u53ef\u80fd\u90e8\u5206\u89e3\u91ca\u4e86\u8fd9\u79cd\u8de8\u7fa4\u4f53\u7ed3\u5a5a\u7387\u8f83\u4f4e\u7684\u60c5\u51b5\u3002\u6211\u4eec\u5229\u7528\u7ae5\u5e74\u5c45\u4f4f\u533a\u57df\u4e2d\u5176\u4ed6\u79cd\u65cf\u548c\u9636\u7ea7\u7fa4\u4f53\u662f\u5426\u6709\u540c\u9f84\u5f02\u6027\u5b50\u5973\u7684\u5dee\u5f02\u4f5c\u4e3a\u63a5\u89e6\u7684\u5de5\u5177\u53d8\u91cf\u3002\u63a5\u89e6\u589e\u52a0\u4e86\u4e0d\u540c\u6536\u5165\u9636\u5c42\uff08\u9ad8\u6536\u5165\u548c\u4f4e\u6536\u5165\u5bb6\u5ead\uff09\u4e4b\u95f4\u7684\u5a5a\u59fb\uff0c\u4f46\u5bf9\u79cd\u65cf\u95f4\u5a5a\u59fb\uff08\u767d\u4eba\u4e0e\u9ed1\u4eba\uff09\u6ca1\u6709\u53ef\u68c0\u6d4b\u7684\u5f71\u54cd\u3002\u4e00\u4e2a\u57fa\u4e8e\u7a7a\u95f4\u5a5a\u59fb\u7684\u6a21\u578b\u9884\u6d4b\uff0c\u5c45\u4f4f\u9694\u79bb\u2014\u2014\u63a5\u89e6\u7684\u591a\u79cd\u5f62\u5f0f\u4e4b\u4e00\u2014\u2014\u89e3\u91ca\u4e86\u8d85\u8fc7\u4e09\u5206\u4e4b\u4e00\u7684\u9636\u7ea7\u5a5a\u59fb\u5206\u5c42\uff0c\u4f46\u5bf9\u79cd\u65cf\u5a5a\u59fb\u5206\u5c42\u7684\u89e3\u91ca\u4e0d\u8db35%\u3002\uff08JEL J12, J15, J62, R23\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20231368", "journal": "AER", "title": "Racial Promotion Gaps", "authors": ["Deepak Hegde", "Alexander Ljungqvist", "Manav Raj"], "author_details": [{"name": "Deepak Hegde", "affiliations": ["New York University and NBER (email: )"]}, {"name": "Alexander Ljungqvist", "affiliations": ["Stockholm School of Economics, Swedish House of Finance, and CEPR (email: )"]}, {"name": "Manav Raj", "affiliations": ["University of Pennsylvania Wharton School (email: )"]}], "abstract": "We study racial disparities in promotions in a setting in which promotions are formulaic: the US patent office. Using detailed administrative data that allow us to observe who is eligible for promotion when, we document that Black patent examiners experience delays in promotions they are entitled to, slowing their climb to the top of the career ladder by a year and reducing career earnings by 2.5 percent. Institutional features rule out statistical discrimination with accurate priors. Slow promotions even under Black supervisors argue against taste-based animus. Instead, the patterns fit models of belief-based discrimination. (JEL J15, J41, J71, M12, M51, O34)", "date": "2026-10-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1257/aer.20231368", "title_zh": "\u79cd\u65cf\u664b\u5347\u5dee\u8ddd", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5728\u7f8e\u56fd\u4e13\u5229\u5c40\u8fd9\u4e00\u664b\u5347\u89c4\u5219\u660e\u786e\u7684\u73af\u5883\u4e2d\u5b58\u5728\u7684\u79cd\u65cf\u664b\u5347\u5dee\u5f02\u3002\u5229\u7528\u80fd\u591f\u89c2\u5bdf\u5230\u8c01\u5728\u4f55\u65f6\u6709\u8d44\u683c\u664b\u5347\u7684\u8be6\u7ec6\u884c\u653f\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u9ed1\u4eba\u4e13\u5229\u5ba1\u67e5\u5458\u5728\u672c\u5e94\u83b7\u5f97\u664b\u5347\u7684\u60c5\u51b5\u4e0b\u5b58\u5728\u664b\u5347\u5ef6\u8fdf\uff0c\u5bfc\u81f4\u5176\u804c\u4e1a\u664b\u5347\u8def\u5f84\u5ef6\u957f\u4e00\u5e74\uff0c\u5e76\u4f7f\u5176\u804c\u4e1a\u751f\u6daf\u6536\u5165\u51cf\u5c112.5\u4e2a\u767e\u5206\u70b9\u3002\u5236\u5ea6\u7279\u5f81\u6392\u9664\u4e86\u57fa\u4e8e\u51c6\u786e\u5148\u9a8c\u7684\u7edf\u8ba1\u6027\u6b67\u89c6\u3002\u5373\u4f7f\u5728\u9ed1\u4eba\u4e3b\u7ba1\u9886\u5bfc\u4e0b\uff0c\u664b\u5347\u901f\u5ea6\u4f9d\u7136\u7f13\u6162\uff0c\u8fd9\u53cd\u9a73\u4e86\u57fa\u4e8e\u504f\u597d\u7684\u654c\u610f\u3002\u76f8\u53cd\uff0c\u8fd9\u4e9b\u73b0\u8c61\u7b26\u5408\u57fa\u4e8e\u4fe1\u5ff5\u7684\u6b67\u89c6\u6a21\u578b\u3002\uff08JEL J15, J41, J71, M12, M51, O34\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240393", "journal": "AER", "title": "Fighting for Growth: Labor Scarcity and Technological Progress during the British Industrial Revolution", "authors": ["Hans-Joachim Voth", "Bruno Caprettini", "Alex Trew"], "author_details": [{"name": "Hans-Joachim Voth", "affiliations": ["University of Zurich and CEPR ()"]}, {"name": "Bruno Caprettini", "affiliations": ["University of St. Gallen and CEPR ()"]}, {"name": "Alex Trew", "affiliations": ["University of Glasgow ()"]}], "abstract": "We establish a link between labor scarcity and the adoption of laborsaving technology in industrializing England. During the Napoleonic Wars, more than 10 percent of the male population served in the armed forces. Where recruitment was heavy, more machines economizing on labor were adopted. Naval recruitment, instrumented by warships' coastal access, provides exogenous variation in labor scarcity and suggests that the link between labor shortages and adoption is causal. Where mechanical skills were abundant, the impact of labor scarcity on adoption appears to be larger. (JEL J24, N13, N43, N63, N73, O14, O31)", "date": "2026-10-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1257/aer.20240393", "title_zh": "\u4e89\u53d6\u589e\u957f\uff1a\u82f1\u56fd\u5de5\u4e1a\u9769\u547d\u671f\u95f4\u52b3\u52a8\u529b\u77ed\u7f3a\u4e0e\u6280\u672f\u8fdb\u6b65", "abstract_zh": "\u6211\u4eec\u5efa\u7acb\u4e86\u52b3\u52a8\u529b\u77ed\u7f3a\u4e0e\u5de5\u4e1a\u9769\u547d\u65f6\u671f\u82f1\u683c\u5170\u91c7\u7528\u8282\u7701\u52b3\u52a8\u529b\u6280\u672f\u4e4b\u95f4\u7684\u8054\u7cfb\u3002\u5728\u62ff\u7834\u4ed1\u6218\u4e89\u671f\u95f4\uff0c\u8d85\u8fc710%\u7684\u7537\u6027\u4eba\u53e3\u670d\u5f79\u4e8e\u519b\u961f\u3002\u5728\u5f81\u5175\u538b\u529b\u8f83\u5927\u7684\u5730\u533a\uff0c\u66f4\u591a\u8282\u7701\u52b3\u52a8\u529b\u7684\u673a\u5668\u88ab\u91c7\u7528\u3002\u6d77\u519b\u5f81\u5175\u901a\u8fc7\u519b\u8230\u7684\u6cbf\u6d77\u53ef\u8fbe\u6027\u63d0\u4f9b\u4e86\u52b3\u52a8\u529b\u77ed\u7f3a\u7684\u5916\u751f\u53d8\u5316\uff0c\u8868\u660e\u52b3\u52a8\u529b\u77ed\u7f3a\u4e0e\u6280\u672f\u91c7\u7528\u4e4b\u95f4\u7684\u8054\u7cfb\u5177\u6709\u56e0\u679c\u6027\u3002\u5728\u673a\u68b0\u6280\u80fd\u4e30\u5bcc\u7684\u5730\u533a\uff0c\u52b3\u52a8\u529b\u77ed\u7f3a\u5bf9\u6280\u672f\u91c7\u7528\u7684\u5f71\u54cd\u4f3c\u4e4e\u66f4\u4e3a\u663e\u8457\u3002\uff08JEL J24, N13, N43, N63, N73, O14, O31\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20230714", "journal": "AER", "title": "Knowledge Spillovers, Competition, and Individual Careers", "authors": ["Thomas Cornelissen", "Christian Dustmann", "Uta Sch\u00f6nberg"], "author_details": [{"name": "Thomas Cornelissen", "affiliations": ["Department of Economics, University of Essex, RF Berlin, and Institute for Employment Research (IAB) (email: )"]}, {"name": "Christian Dustmann", "affiliations": ["Department of Economics, University College London, and RF Berlin (email: )"]}, {"name": "Uta Sch\u00f6nberg", "affiliations": ["Faculty of Business and Economics, University of Hong Kong, RF Berlin, and IAB (email: )"]}], "abstract": "Exposure to better peers in the workplace can influence career trajectories through two opposing channels: positively, via knowledge spillovers, and negatively, through competition for advancement. We disentangle these effects by studying untrained labor market entrants and distinguishing between coworkers in the same occupation with whom they are likely to compete versus those with whom they are unlikely to compete. We find robust evidence of persistent knowledge spillovers but also identify countervailing competition effects of comparable magnitude. Both effects are more pronounced for men than for women. (JEL D83, J16, J24, M53, M54, O33)", "date": "2026-10-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1257/aer.20230714", "title_zh": "\u77e5\u8bc6\u6ea2\u51fa\u3001\u7ade\u4e89\u4e0e\u4e2a\u4eba\u804c\u4e1a\u751f\u6daf", "abstract_zh": "\u5728\u804c\u573a\u4e2d\u63a5\u89e6\u5230\u66f4\u4f18\u79c0\u540c\u4e8b\u53ef\u80fd\u901a\u8fc7\u4e24\u4e2a\u76f8\u53cd\u7684\u6e20\u9053\u5f71\u54cd\u804c\u4e1a\u53d1\u5c55\uff1a\u4e00\u65b9\u9762\uff0c\u901a\u8fc7\u77e5\u8bc6\u6ea2\u51fa\u4ea7\u751f\u79ef\u6781\u5f71\u54cd\uff1b\u53e6\u4e00\u65b9\u9762\uff0c\u901a\u8fc7\u664b\u5347\u7ade\u4e89\u4ea7\u751f\u8d1f\u9762\u5f71\u54cd\u3002\u6211\u4eec\u901a\u8fc7\u7814\u7a76\u672a\u7ecf\u57f9\u8bad\u7684\u52b3\u52a8\u529b\u5e02\u573a\u65b0\u8fdb\u5165\u8005\uff0c\u5e76\u533a\u5206\u90a3\u4e9b\u4e0e\u4ed6\u4eec\u53ef\u80fd\u7ade\u4e89\u7684\u540c\u804c\u4e1a\u540c\u4e8b\uff0c\u4ee5\u53ca\u90a3\u4e9b\u4e0d\u592a\u53ef\u80fd\u4e0e\u4ed6\u4eec\u7ade\u4e89\u7684\u540c\u4e8b\uff0c\u6765\u5206\u79bb\u8fd9\u4e24\u79cd\u6548\u5e94\u3002\u7814\u7a76\u53d1\u73b0\u5b58\u5728\u7a33\u5065\u7684\u77e5\u8bc6\u6ea2\u51fa\u6548\u5e94\uff0c\u540c\u65f6\u4e5f\u8bc6\u522b\u51fa\u89c4\u6a21\u76f8\u5f53\u7684\u7ade\u4e89\u6548\u5e94\u3002\u8fd9\u4e24\u79cd\u6548\u5e94\u5728\u7537\u6027\u4e2d\u6bd4\u5728\u5973\u6027\u4e2d\u66f4\u4e3a\u663e\u8457\u3002\uff08JEL D83, J16, J24, M53, M54, O33\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20251879", "journal": "AER", "title": "Truth Elicitation in a Nonstrategic Environment", "authors": ["Jacob Glazer", "Ariel Rubinstein"], "author_details": [{"name": "Jacob Glazer", "affiliations": ["University of Warwick and Tel Aviv University (email: )"]}, {"name": "Ariel Rubinstein", "affiliations": ["Tel Aviv University and New York University (email: )"]}], "abstract": "A principal decides which party deserves a prize. Only the parties observe the state that determines who is deserving. The principal gives each party a text describing the conditions under which that party deserves the prize and asks each to report the state. The parties are nonstrategic. Each activates a known cheating procedure whose outcome depends on the state and on the text. Implementation is achieved if, whenever the parties disagree, the liar is identified by the \u201cone-way cheating principle\u201d: The truthful party is the unique party who could not have produced his story had the rival's story been true. (JEL D82, D91)", "date": "2026-10-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1257/aer.20251879", "title_zh": "\u975e\u6218\u7565\u73af\u5883\u4e2d\u7684\u771f\u76f8\u83b7\u53d6", "abstract_zh": "\u4e00\u4e2a\u4e3b\u5bfc\u8005\u51b3\u5b9a\u54ea\u4e00\u65b9\u503c\u5f97\u83b7\u5f97\u5956\u52b1\u3002\u53ea\u6709\u5404\u65b9\u89c2\u5bdf\u5230\u51b3\u5b9a\u8c01\u503c\u5f97\u83b7\u5f97\u5956\u52b1\u7684\u72b6\u6001\u3002\u4e3b\u5bfc\u8005\u4e3a\u6bcf\u65b9\u63d0\u4f9b\u4e00\u4efd\u63cf\u8ff0\u5176\u83b7\u5f97\u5956\u52b1\u6761\u4ef6\u7684\u6587\u672c\uff0c\u5e76\u8981\u6c42\u6bcf\u65b9\u62a5\u544a\u8be5\u72b6\u6001\u3002\u5404\u65b9\u662f\u975e\u6218\u7565\u6027\u7684\uff0c\u6bcf\u4e2a\u65b9\u90fd\u4f1a\u6fc0\u6d3b\u4e00\u4e2a\u5df2\u77e5\u7684\u4f5c\u5f0a\u7a0b\u5e8f\uff0c\u5176\u7ed3\u679c\u53d6\u51b3\u4e8e\u72b6\u6001\u548c\u6587\u672c\u3002\u5f53\u5404\u65b9\u610f\u89c1\u4e0d\u4e00\u81f4\u65f6\uff0c\u901a\u8fc7\u2018\u5355\u5411\u4f5c\u5f0a\u539f\u5219\u2019\u53ef\u4ee5\u8bc6\u522b\u51fa\u8bf4\u8c0e\u8005\uff1a\u5373\u552f\u4e00\u4e00\u4e2a\u5728\u5bf9\u65b9\u9648\u8ff0\u4e3a\u771f\u65f6\u65e0\u6cd5\u4ea7\u751f\u5176\u9648\u8ff0\u7684\u5f53\u4e8b\u4eba\uff0c\u5c31\u662f\u8bda\u5b9e\u7684\u4e00\u65b9\u3002\uff08JEL D82, D91\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20231417", "journal": "AER", "title": "Social Push and the Direction of Innovation", "authors": ["Elias Eini\u00f6", "Josh Feng", "Xavier Jaravel"], "author_details": [{"name": "Elias Eini\u00f6", "affiliations": ["VATT Institute for Economic Research (email: )"]}, {"name": "Josh Feng", "affiliations": ["University of Utah (email: )"]}, {"name": "Xavier Jaravel", "affiliations": ["London School of Economics and CEPR (email: )"]}], "abstract": "What are the implications of unequal access to innovation careers for the direction of innovation and inequality? Leveraging novel linked datasets in the United States and Finland, we document that innovators create products more likely to be purchased by consumers like them in terms of gender, socioeconomic status, and age. Homophily exists both within narrow product categories and across industries and has been stable in recent decades. Incorporating this \u201csocial push\u201d channel into a growth model, we estimate that unequal access to innovation careers has a large effect on cost of living inequality and long-run growth. (JEL D63, J16, L26, M13, O31, O33, O47)", "date": "2026-10-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1257/aer.20231417", "title_zh": "\u793e\u4f1a\u63a8\u52a8\u4e0e\u521b\u65b0\u65b9\u5411", "abstract_zh": "\u4e0d\u5e73\u7b49\u7684\u521b\u65b0\u804c\u4e1a\u83b7\u53d6\u673a\u4f1a\u5bf9\u521b\u65b0\u65b9\u5411\u548c\u4e0d\u5e73\u7b49\u6709\u4f55\u5f71\u54cd\uff1f\u5229\u7528\u7f8e\u56fd\u548c\u82ac\u5170\u7684\u65b0\u578b\u5173\u8054\u6570\u636e\u96c6\uff0c\u6211\u4eec\u53d1\u73b0\u521b\u65b0\u8005\u521b\u9020\u7684\u4ea7\u54c1\u66f4\u53ef\u80fd\u88ab\u4e0e\u4e4b\u5728\u6027\u522b\u3001\u793e\u4f1a\u7ecf\u6d4e\u5730\u4f4d\u548c\u5e74\u9f84\u4e0a\u76f8\u4f3c\u7684\u6d88\u8d39\u8005\u8d2d\u4e70\u3002\u8fd9\u79cd\u540c\u8d28\u6027\u73b0\u8c61\u65e2\u5b58\u5728\u4e8e\u72ed\u7a84\u7684\u4ea7\u54c1\u7c7b\u522b\u4e2d\uff0c\u4e5f\u5b58\u5728\u4e8e\u4e0d\u540c\u884c\u4e1a\u4e4b\u95f4\uff0c\u5e76\u5728\u8fc7\u53bb\u51e0\u5341\u5e74\u4e2d\u4fdd\u6301\u7a33\u5b9a\u3002\u5c06\u8fd9\u4e00\u201c\u793e\u4f1a\u63a8\u52a8\u201d\u6e20\u9053\u7eb3\u5165\u589e\u957f\u6a21\u578b\u540e\uff0c\u6211\u4eec\u4f30\u8ba1\uff0c\u521b\u65b0\u804c\u4e1a\u83b7\u53d6\u673a\u4f1a\u7684\u4e0d\u5e73\u7b49\u5bf9\u751f\u6d3b\u6210\u672c\u4e0d\u5e73\u7b49\u548c\u957f\u671f\u7ecf\u6d4e\u589e\u957f\u5177\u6709\u663e\u8457\u5f71\u54cd\u3002\uff08JEL D63, J16, L26, M13, O31, O33, O47\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20250206", "journal": "AER", "title": "Screening and Segmenting: A Consumer Surplus Perspective", "authors": ["Dirk Bergemann", "Tibor Heumann", "Michael C. Wang"], "author_details": [{"name": "Dirk Bergemann", "affiliations": ["Department of Economics, Yale University (email: )"]}, {"name": "Tibor Heumann", "affiliations": ["Instituto de Econom\u00eda, Pontificia Universidad Cat\u00f3lica de Chile (email: )"]}, {"name": "Michael C. Wang", "affiliations": ["Department of Economics, Yale University (email: )"]}], "abstract": "We analyze consumer surplus when a monopolist can adjust both prices and product qualities across segments, engaging in secondand third-degree price discrimination simultaneously. We characterize the consumer-optimal segmentation and show that it has a striking structure: Consumers with the same value receive the same quality in every segment, though prices differ. Under mild conditions, any segmentation harms consumers if and only if demand is sufficiently more elastic than supply. Hence, potential benefits for consumers depend critically on demand and supply elasticities. These findings have implications for regulatory policy regarding price discrimination and market segmentation. (JEL D42, D83, K21, L12, L15)", "date": "2026-10-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1257/aer.20250206", "title_zh": "\u7b5b\u9009\u4e0e\u7ec6\u5206\uff1a\u6d88\u8d39\u8005\u5269\u4f59\u89c6\u89d2", "abstract_zh": "\u6211\u4eec\u5206\u6790\u4e86\u5784\u65ad\u4f01\u4e1a\u80fd\u591f\u540c\u65f6\u5b9e\u65bd\u4e8c\u7ea7\u548c\u4e09\u7ea7\u4ef7\u683c\u6b67\u89c6\u65f6\uff0c\u6d88\u8d39\u8005\u5269\u4f59\u7684\u60c5\u51b5\uff0c\u5373\u5728\u4e0d\u540c\u7ec6\u5206\u5e02\u573a\u4e2d\u8c03\u6574\u4ef7\u683c\u548c\u4ea7\u54c1\u54c1\u8d28\u3002\u6211\u4eec\u523b\u753b\u4e86\u6d88\u8d39\u8005\u6700\u4f18\u7684\u7ec6\u5206\u7ed3\u6784\uff1a\u5728\u6bcf\u4e2a\u7ec6\u5206\u5e02\u573a\u4e2d\uff0c\u5177\u6709\u76f8\u540c\u4ef7\u503c\u7684\u6d88\u8d39\u8005\u4f1a\u83b7\u5f97\u76f8\u540c\u7684\u4ea7\u54c1\u8d28\u91cf\uff0c\u5c3d\u7ba1\u4ef7\u683c\u4e0d\u540c\u3002\u5728\u6e29\u548c\u6761\u4ef6\u4e0b\uff0c\u53ea\u8981\u9700\u6c42\u5f39\u6027\u663e\u8457\u5927\u4e8e\u4f9b\u7ed9\u5f39\u6027\uff0c\u4efb\u4f55\u7ec6\u5206\u90fd\u4f1a\u635f\u5bb3\u6d88\u8d39\u8005\u5229\u76ca\u3002\u56e0\u6b64\uff0c\u6d88\u8d39\u8005\u53ef\u80fd\u83b7\u5f97\u7684\u76ca\u5904\u9ad8\u5ea6\u4f9d\u8d56\u4e8e\u9700\u6c42\u548c\u4f9b\u7ed9\u7684\u5f39\u6027\u3002\u8fd9\u4e9b\u53d1\u73b0\u5bf9\u5173\u4e8e\u4ef7\u683c\u6b67\u89c6\u548c\u5e02\u573a\u7ec6\u5206\u7684\u76d1\u7ba1\u653f\u7b56\u5177\u6709\u91cd\u8981\u542f\u793a\u3002(JEL D42, D83, K21, L12, L15)", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag035", "journal": "QJE", "title": "Retrieval Failures and Consumption Smoothing: A Field Experiment on Seasonal Poverty", "authors": ["Ned Augenblick", "B Kelsey Jack", "Supreet Kaur", "Felix Masiye", "Nicholas Swanson"], "author_details": [{"name": "Ned Augenblick", "affiliations": ["University of California, Berkeley ,"]}, {"name": "B Kelsey Jack", "affiliations": ["University of California, Berkeley, and National Bureau of Economic Research ,"]}, {"name": "Supreet Kaur", "affiliations": ["University of California, Berkeley, and National Bureau of Economic Research ,"]}, {"name": "Felix Masiye", "affiliations": ["University of Zambia ,"]}, {"name": "Nicholas Swanson", "affiliations": ["Cornell University ,"]}], "abstract": "Abstract People may fail to recall and use information they already know when making decisions. We empirically investigate whether such \u201cretrieval failures\u201d distort consumption-smoothing behavior among Zambian farmers, who derive their income from one annual harvest and spend it over the course of the year. We document that individuals underestimate upcoming spending by 50%, creating scope for undersaving. To improve recall, we randomize an intervention that prompts people to think through their future expenses associatively in categories\u2014without providing any external information or guidance. Treated individuals increase \u201cremembered\u201d expenses by 36%\u201360%; as predicted by the memory literature, effects are concentrated among small, irregular, and stochastic items. Immediate spending drops and, six weeks after the intervention, treated households hold 15% higher savings. They subsequently enter the hungry season\u2014the final months of the year when consumption typically declines sharply\u2014with one additional month of savings, leading to a flatter spending profile over the year. Households use the increased savings to self-finance additional farm investment, resulting in a 9% increase in the next year\u2019s crop revenue. We replicate the intervention\u2019s effect on beliefs among low-income Americans, suggesting that retrieval failures generalize across settings and populations.", "date": "2026-10-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1093/qje/qjag035", "title_zh": "\u56de\u5fc6\u5931\u8d25\u4e0e\u6d88\u8d39\u5e73\u6ed1\uff1a\u4e00\u9879\u5173\u4e8e\u5b63\u8282\u6027\u8d2b\u56f0\u7684\u5b9e\u5730\u5b9e\u9a8c", "abstract_zh": "\u4eba\u4eec\u5728\u505a\u51b3\u7b56\u65f6\u53ef\u80fd\u65e0\u6cd5\u56de\u5fc6\u548c\u4f7f\u7528\u4ed6\u4eec\u5df2\u7ecf\u77e5\u9053\u7684\u4fe1\u606f\u3002\u6211\u4eec\u5b9e\u8bc1\u7814\u7a76\u4e86\u8fd9\u79cd\u2018\u56de\u5fc6\u5931\u8d25\u2019\u662f\u5426\u4f1a\u5f71\u54cd\u8d5e\u6bd4\u4e9a\u519c\u6c11\u7684\u6d88\u8d39\u5e73\u6ed1\u884c\u4e3a\uff0c\u8fd9\u4e9b\u519c\u6c11\u4f9d\u9760\u6bcf\u5e74\u4e00\u6b21\u7684\u6536\u83b7\u6536\u5165\uff0c\u5e76\u5728\u5168\u5e74\u4e2d\u652f\u51fa\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u4e2a\u4f53\u5bf9\u672a\u6765\u7684\u652f\u51fa\u4e25\u91cd\u4f4e\u4f30\u4e8650%\uff0c\u5b58\u5728\u50a8\u84c4\u4e0d\u8db3\u7684\u7a7a\u95f4\u3002\u4e3a\u4e86\u6539\u5584\u8bb0\u5fc6\uff0c\u6211\u4eec\u968f\u673a\u5b9e\u65bd\u4e86\u4e00\u9879\u5e72\u9884\u63aa\u65bd\uff0c\u4fc3\u4f7f\u4eba\u4eec\u4ee5\u7c7b\u522b\u5f62\u5f0f\u8054\u60f3\u5230\u672a\u6765\u7684\u652f\u51fa\uff0c\u4f46\u4e0d\u63d0\u4f9b\u4efb\u4f55\u5916\u90e8\u4fe1\u606f\u6216\u6307\u5bfc\u3002\u63a5\u53d7\u5e72\u9884\u7684\u4e2a\u4f53\u5c06\u2018\u56de\u5fc6\u2019\u5230\u7684\u652f\u51fa\u589e\u52a0\u4e8636%\u81f360%\uff1b\u6b63\u5982\u8bb0\u5fc6\u6587\u732e\u6240\u9884\u6d4b\uff0c\u8fd9\u79cd\u6548\u5e94\u4e3b\u8981\u96c6\u4e2d\u5728\u5c0f\u989d\u3001\u4e0d\u89c4\u5219\u548c\u968f\u673a\u7684\u652f\u51fa\u9879\u76ee\u4e0a\u3002\u7acb\u5373\u652f\u51fa\u51cf\u5c11\uff0c\u5e72\u9884\u540e\u516d\u5468\uff0c\u63a5\u53d7\u5e72\u9884\u7684\u5bb6\u5ead\u50a8\u84c4\u63d0\u9ad8\u4e8615%\u3002\u4ed6\u4eec\u968f\u540e\u8fdb\u5165\u9965\u8352\u5b63\u8282\u2014\u2014\u5373\u6bcf\u5e74\u6d88\u8d39\u901a\u5e38\u6025\u5267\u4e0b\u964d\u7684\u6700\u540e\u51e0\u4e2a\u6708\u2014\u2014\u65f6\uff0c\u591a\u51fa\u4e00\u4e2a\u6708\u7684\u50a8\u84c4\uff0c\u4ece\u800c\u5b9e\u73b0\u4e86\u5168\u5e74\u6d88\u8d39\u652f\u51fa\u7684\u66f4\u5e73\u7a33\u3002\u5bb6\u5ead\u5229\u7528\u589e\u52a0\u7684\u50a8\u84c4\u81ea\u884c\u878d\u8d44\u8fdb\u884c\u989d\u5916\u7684\u519c\u4e1a\u6295\u8d44\uff0c\u5bfc\u81f4\u6b21\u5e74\u519c\u4f5c\u7269\u6536\u5165\u63d0\u9ad8\u4e869%\u3002\u6211\u4eec\u8fd8\u5728\u4f4e\u6536\u5165\u7f8e\u56fd\u4eba\u7fa4\u4e2d\u590d\u5236\u4e86\u8be5\u5e72\u9884\u5bf9\u4fe1\u5ff5\u7684\u5f71\u54cd\uff0c\u8868\u660e\u56de\u5fc6\u5931\u8d25\u73b0\u8c61\u5728\u4e0d\u540c\u73af\u5883\u548c\u4eba\u7fa4\u4e2d\u5177\u6709\u666e\u904d\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2025.00107", "journal": "MS", "title": "Does Privacy Matter? Evidence from a Legal Reform", "authors": ["Liran Einav", "Ehud Guttel", "Ilan Kremer", "Guy Lakan", "Sarit Weisburd"], "author_details": [{"name": "Liran Einav", "affiliations": ["Department of Economics, Stanford University, Stanford, California 94305; and Industrial Organization Program, National Bureau of Economic Research, Cambridge, Massachusetts 02138"]}, {"name": "Ehud Guttel", "affiliations": ["Faculty of Law, Hebrew University of Jerusalem, Jerusalem 9190501, Israel"]}, {"name": "Ilan Kremer", "affiliations": ["Hebrew University Business School, Hebrew University of Jerusalem, Jerusalem 9190501, Israel; and Department of Economics, The University of Warwick, Coventry CV4 7AL, United Kingdom; and Department of Economics, Hebrew University of Jerusalem, Jerusalem 9190501, Israel"]}, {"name": "Guy Lakan", "affiliations": ["Hebrew University Business School, Hebrew University of Jerusalem, Jerusalem 9190501, Israel"]}, {"name": "Sarit Weisburd", "affiliations": ["Hebrew University Business School, Hebrew University of Jerusalem, Jerusalem 9190501, Israel; and Industrial Organization Program, Centre for Economic Policy Research, London EC1V 0DX, United Kingdom"]}], "abstract": "We investigate the impact of a unique legislative reform that granted anonymity to plaintiffs in court rulings for personal injury claims. Prior to the reform\u2019s implementation in August 2015, claimants who rejected settlement offers faced the risk that court proceedings would publicly disclose sensitive information regarding their health and earnings. By eliminating this source of privacy loss, the reform provides an opportunity to examine how privacy considerations affect outcomes in a real-world setting. Our analysis measures changes in payments for personal injury versus property damage claims (which were not affected by the reform) for car accident cases handled by the major insurance firms in Israel between 2011 and 2020. Using a difference-in-differences framework, we find that the reform led to a 12%\u201317% increase in payments for personal injury claims. We interpret this estimate as the implicit cost claimants were previously willing to bear, in the form of lower settlements, to avoid the disclosure of private information through court rulings. This result underscores the economic value individuals place on privacy, revealing that concerns about public exposure can significantly influence decision making and negotiation outcomes. Our findings demonstrate the importance of privacy considerations in customer interactions where sensitive information is often involved.", "date": "2026-10-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2025.00107", "title_zh": "\u9690\u79c1\u91cd\u8981\u5417\uff1f\u6765\u81ea\u4e00\u9879\u6cd5\u5f8b\u6539\u9769\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u9879\u72ec\u7279\u7684\u7acb\u6cd5\u6539\u9769\uff0c\u8be5\u6539\u9769\u5728\u4e2a\u4eba\u4f24\u5bb3\u7d22\u8d54\u6848\u4ef6\u7684\u6cd5\u9662\u5224\u51b3\u4e2d\u8d4b\u4e88\u539f\u544a\u533f\u540d\u6743\u3002\u57282015\u5e748\u6708\u6539\u9769\u5b9e\u65bd\u4e4b\u524d\uff0c\u62d2\u7edd\u548c\u89e3\u63d0\u8bae\u7684\u7d22\u8d54\u4eba\u9762\u4e34\u6cd5\u9662\u7a0b\u5e8f\u53ef\u80fd\u516c\u5f00\u62ab\u9732\u5176\u5065\u5eb7\u72b6\u51b5\u548c\u6536\u5165\u7b49\u654f\u611f\u4fe1\u606f\u7684\u98ce\u9669\u3002\u901a\u8fc7\u6d88\u9664\u8fd9\u4e00\u9690\u79c1\u635f\u5931\u6765\u6e90\uff0c\u8be5\u6539\u9769\u4e3a\u8003\u5bdf\u9690\u79c1\u8003\u8651\u5982\u4f55\u5f71\u54cd\u73b0\u5b9e\u73af\u5883\u4e2d\u7684\u7ed3\u679c\u63d0\u4f9b\u4e86\u673a\u4f1a\u3002\u6211\u4eec\u7684\u5206\u6790\u6d4b\u91cf\u4e862011\u5e74\u81f32020\u5e74\u95f4\u4ee5\u8272\u5217\u4e3b\u8981\u4fdd\u9669\u516c\u53f8\u5904\u7406\u7684\u4ea4\u901a\u4e8b\u6545\u6848\u4ef6\u4e2d\uff0c\u4e2a\u4eba\u4f24\u5bb3\u7d22\u8d54\u4e0e\u8d22\u4ea7\u635f\u5bb3\u7d22\u8d54\uff08\u540e\u8005\u672a\u53d7\u6539\u9769\u5f71\u54cd\uff09\u7684\u652f\u4ed8\u53d8\u5316\u3002\u91c7\u7528\u5dee\u5206-\u5dee\u5206\u6846\u67b6\uff0c\u6211\u4eec\u53d1\u73b0\u6539\u9769\u5bfc\u81f4\u4e2a\u4eba\u4f24\u5bb3\u7d22\u8d54\u7684\u652f\u4ed8\u63d0\u9ad8\u4e8612%\u81f317%\u3002\u6211\u4eec\u5c06\u8fd9\u4e00\u4f30\u8ba1\u89e3\u91ca\u4e3a\u7d22\u8d54\u4eba\u6b64\u524d\u4e3a\u907f\u514d\u901a\u8fc7\u6cd5\u9662\u5224\u51b3\u516c\u5f00\u79c1\u4eba\u4fe1\u606f\u800c\u613f\u610f\u627f\u62c5\u7684\u9690\u6027\u6210\u672c\uff0c\u8868\u73b0\u4e3a\u66f4\u4f4e\u7684\u548c\u89e3\u91d1\u989d\u3002\u8fd9\u4e00\u7ed3\u679c\u51f8\u663e\u4e86\u4e2a\u4eba\u5bf9\u9690\u79c1\u4ef7\u503c\u7684\u91cd\u89c6\uff0c\u8868\u660e\u5bf9\u516c\u4f17\u66dd\u5149\u7684\u62c5\u5fe7\u53ef\u4ee5\u663e\u8457\u5f71\u54cd\u51b3\u7b56\u548c\u8c08\u5224\u7ed3\u679c\u3002\u6211\u4eec\u7684\u53d1\u73b0\u8868\u660e\uff0c\u5728\u6d89\u53ca\u654f\u611f\u4fe1\u606f\u7684\u5ba2\u6237\u4e92\u52a8\u4e2d\uff0c\u9690\u79c1\u8003\u8651\u5177\u6709\u91cd\u8981\u610f\u4e49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.08553", "journal": "MS", "title": "More Monitoring, Less Pay: Active Ownership and Employee Compensation", "authors": ["Claudine Gartenberg", "Elaine Pak"], "author_details": [{"name": "Claudine Gartenberg", "affiliations": ["The Wharton School, University of Pennsylvania, Philadelphia, Pennsylvania 19104"]}, {"name": "Elaine Pak", "affiliations": ["The Wharton School, University of Pennsylvania, Philadelphia, Pennsylvania 19104"]}], "abstract": "The rise of active owners\u2014hedge funds and private equity firms\u2014has raised questions about the influence of corporate owners on employee compensation. Prior research documents that active owners reduce overall compensation through workforce restructuring and slower wage growth. What remains unexplored is whether active owners also pay less for comparable work: whether they compensate the same jobs differently than other owners. Using detailed compensation from more than 20 million employee records across 896 U.S. firms, we compare pay within narrowly defined labor markets that hold constant year, region, occupation, and skill level. We find that firms with active owners pay 2%\u20134% less for comparable work than other firms. These differentials manifest as both lower base salary and flatter incentive pay and appear to reflect, at least in part, an owner treatment effect. Notably, the effects are concentrated in more monitorable contexts, including routine jobs, jobs with quantifiable outputs, and those in less knowledge-intensive industries. These patterns are consistent with active owners substituting compensation-based incentives with managerial oversight, particularly in quantifiable and routine settings. This suggests that, as work becomes more measurable, firm ownership may play a greater role in shaping employee outcomes.", "date": "2026-10-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08553", "title_zh": "\u66f4\u591a\u76d1\u63a7\uff0c\u66f4\u5c11\u85aa\u916c\uff1a\u4e3b\u52a8\u6240\u6709\u6743\u4e0e\u5458\u5de5\u85aa\u916c", "abstract_zh": "\u4e3b\u52a8\u6240\u6709\u8005\u2014\u2014\u5982\u5bf9\u51b2\u57fa\u91d1\u548c\u79c1\u52df\u80a1\u6743\u516c\u53f8\u2014\u2014\u7684\u5174\u8d77\u5f15\u53d1\u4e86\u5173\u4e8e\u4f01\u4e1a\u6240\u6709\u8005\u5982\u4f55\u5f71\u54cd\u5458\u5de5\u85aa\u916c\u7684\u8ba8\u8bba\u3002\u4ee5\u5f80\u7814\u7a76\u53d1\u73b0\uff0c\u4e3b\u52a8\u6240\u6709\u8005\u901a\u8fc7\u8c03\u6574\u52b3\u52a8\u529b\u7ed3\u6784\u548c\u51cf\u7f13\u5de5\u8d44\u589e\u957f\u6765\u964d\u4f4e\u6574\u4f53\u85aa\u916c\u6c34\u5e73\u3002\u7136\u800c\uff0c\u5c1a\u672a\u63a2\u8ba8\u7684\u662f\uff0c\u4e3b\u52a8\u6240\u6709\u8005\u662f\u5426\u4e5f\u4f1a\u5bf9\u76f8\u540c\u5de5\u4f5c\u63d0\u4f9b\u66f4\u4f4e\u7684\u85aa\u916c\uff1a\u5373\u4ed6\u4eec\u662f\u5426\u5bf9\u76f8\u540c\u5c97\u4f4d\u7684\u85aa\u916c\u5f85\u9047\u4e0e\u5176\u5b83\u6240\u6709\u8005\u5b58\u5728\u5dee\u5f02\u3002\u6211\u4eec\u5229\u7528\u6765\u81ea896\u5bb6\u7f8e\u56fd\u4f01\u4e1a\u8d85\u8fc72000\u4e07\u6761\u5458\u5de5\u85aa\u916c\u6570\u636e\uff0c\u6bd4\u8f83\u5728\u5e74\u4efd\u3001\u5730\u533a\u3001\u804c\u4e1a\u548c\u6280\u80fd\u6c34\u5e73\u4fdd\u6301\u4e0d\u53d8\u7684\u72ed\u4e49\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u7684\u85aa\u916c\u5dee\u5f02\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u62e5\u6709\u4e3b\u52a8\u6240\u6709\u8005\u7684\u516c\u53f8\u5bf9\u76f8\u540c\u5de5\u4f5c\u7684\u85aa\u916c\u6bd4\u5176\u4ed6\u516c\u53f8\u4f4e2%\u81f34%\u3002\u8fd9\u79cd\u5dee\u5f02\u4f53\u73b0\u5728\u57fa\u672c\u5de5\u8d44\u7684\u964d\u4f4e\u4ee5\u53ca\u6fc0\u52b1\u6027\u85aa\u916c\u7684\u5e73\u7f13\uff0c\u4f3c\u4e4e\u90e8\u5206\u53cd\u6620\u4e86\u6240\u6709\u8005\u5bf9\u5f85\u5458\u5de5\u7684\u6548\u5e94\u3002\u503c\u5f97\u6ce8\u610f\u7684\u662f\uff0c\u8fd9\u79cd\u6548\u5e94\u4e3b\u8981\u96c6\u4e2d\u5728\u66f4\u6613\u88ab\u76d1\u63a7\u7684\u73af\u5883\u4e2d\uff0c\u5305\u62ec\u4f8b\u884c\u6027\u5de5\u4f5c\u3001\u53ef\u91cf\u5316\u4ea7\u51fa\u7684\u5de5\u4f5c\u4ee5\u53ca\u77e5\u8bc6\u5bc6\u96c6\u5ea6\u8f83\u4f4e\u7684\u884c\u4e1a\u3002\u8fd9\u4e9b\u6a21\u5f0f\u8868\u660e\uff0c\u4e3b\u52a8\u6240\u6709\u8005\u53ef\u80fd\u5728\u53ef\u91cf\u5316\u548c\u4f8b\u884c\u6027\u60c5\u5883\u4e0b\uff0c\u7528\u7ba1\u7406\u5c42\u76d1\u7763\u66ff\u4ee3\u4e86\u85aa\u916c\u6fc0\u52b1\u3002\u8fd9\u8868\u660e\uff0c\u968f\u7740\u5de5\u4f5c\u53d8\u5f97\u66f4\u52a0\u53ef\u8861\u91cf\uff0c\u4f01\u4e1a\u6240\u6709\u6743\u53ef\u80fd\u5728\u5851\u9020\u5458\u5de5\u7ed3\u679c\u65b9\u9762\u53d1\u6325\u8d8a\u6765\u8d8a\u91cd\u8981\u7684\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1287/mnsc.2024.06184", "journal": "MS", "title": "Do Mutual Funds Respond to Mechanical Changes in ESG Ratings?", "authors": ["Seungju Choi", "Fabrizio Ferri", "Daniele Macciocchi"], "author_details": [{"name": "Seungju Choi", "affiliations": ["Faculty of Business and Economics, The University of Hong Kong, Hong Kong, Hong Kong"]}, {"name": "Fabrizio Ferri", "affiliations": ["Miami Herbert Business School, University of Miami, Coral Gables, Florida 33146"]}, {"name": "Daniele Macciocchi", "affiliations": ["Miami Herbert Business School, University of Miami, Coral Gables, Florida 33146"]}], "abstract": "Using a quasi-experimental setting, we study whether mutual fund investors respond to a purely mechanical change in environmental, social, and governance (ESG) ratings\u2014that is, a change independent of concurrent changes in firms\u2019 actual ESG activities. We find that when a firm experiences a mechanical increase in ESG ratings, the probability of being selected by an ESG fund increases (extensive margin). In contrast, if the firm is already in the fund\u2019s portfolio, its holdings do not change (intensive margin), consistent with portfolio weighting being based on market capitalization. The selection effect is observable not only among funds that follow an ESG index but also among active ESG funds, which presumably should have the resources and ability to identify and filter out the mechanical increase in ESG ratings. Among active ESG funds, the selection effect is stronger for funds with less assets under management, larger portfolios of firms, and lower expense ratios, consistent with the notion that resource constraints may impede a fund\u2019s screening ability. Our findings imply that passive investing based on commercial ESG ratings\u2014whether due to resource constraints or portfolio indexing\u2014might result in portfolio allocations that do not reflect the actual ESG activities of firms.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06184", "title_zh": "\u5171\u540c\u57fa\u91d1\u662f\u5426\u5bf9ESG\u8bc4\u7ea7\u7684\u673a\u68b0\u6027\u53d8\u5316\u4f5c\u51fa\u53cd\u5e94\uff1f", "abstract_zh": "\u6211\u4eec\u91c7\u7528\u51c6\u5b9e\u9a8c\u8bbe\u7f6e\uff0c\u7814\u7a76\u6295\u8d44\u8005\u662f\u5426\u4f1a\u5bf9\u73af\u5883\u3001\u793e\u4f1a\u548c\u6cbb\u7406\uff08ESG\uff09\u8bc4\u7ea7\u7684\u7eaf\u7cb9\u673a\u68b0\u6027\u53d8\u5316\u4f5c\u51fa\u53cd\u5e94\u2014\u2014\u5373\u8fd9\u79cd\u53d8\u5316\u4e0e\u4f01\u4e1a\u5b9e\u9645ESG\u6d3b\u52a8\u7684\u53d8\u52a8\u65e0\u5173\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5f53\u4e00\u5bb6\u516c\u53f8\u7ecf\u5386ESG\u8bc4\u7ea7\u7684\u673a\u68b0\u6027\u63d0\u5347\u65f6\uff0c\u5176\u88abESG\u57fa\u91d1\u9009\u4e2d\u7684\u6982\u7387\u4f1a\u589e\u52a0\uff08\u5e7f\u4e49\u8fb9\u9645\uff09\u3002\u76f8\u53cd\uff0c\u5982\u679c\u8be5\u516c\u53f8\u5df2\u7ecf\u5b58\u5728\u4e8e\u57fa\u91d1\u7684\u6295\u8d44\u7ec4\u5408\u4e2d\uff0c\u5176\u6301\u80a1\u6bd4\u4f8b\u4e0d\u4f1a\u53d1\u751f\u53d8\u5316\uff08\u72ed\u4e49\u8fb9\u9645\uff09\uff0c\u8fd9\u4e0e\u6295\u8d44\u7ec4\u5408\u6743\u91cd\u57fa\u4e8e\u5e02\u503c\u7684\u8bbe\u5b9a\u4e00\u81f4\u3002\u8fd9\u79cd\u9009\u62e9\u6548\u5e94\u4e0d\u4ec5\u5728\u9075\u5faaESG\u6307\u6570\u7684\u57fa\u91d1\u4e2d\u53ef\u89c2\u5bdf\u5230\uff0c\u4e5f\u5728\u4e3b\u52a8\u578bESG\u57fa\u91d1\u4e2d\u663e\u73b0\uff0c\u8fd9\u4e9b\u57fa\u91d1\u672c\u5e94\u5177\u5907\u8bc6\u522b\u5e76\u8fc7\u6ee4\u673a\u68b0\u6027ESG\u8bc4\u7ea7\u63d0\u5347\u7684\u80fd\u529b\u3002\u5728\u4e3b\u52a8\u578bESG\u57fa\u91d1\u4e2d\uff0c\u9009\u62e9\u6548\u5e94\u5728\u8d44\u4ea7\u7ba1\u7406\u89c4\u6a21\u8f83\u5c0f\u3001\u4f01\u4e1a\u6301\u4ed3\u6570\u91cf\u8f83\u591a\u4e14\u8d39\u7528\u6bd4\u7387\u8f83\u4f4e\u7684\u57fa\u91d1\u4e2d\u66f4\u4e3a\u663e\u8457\uff0c\u8fd9\u4e0e\u8d44\u6e90\u9650\u5236\u53ef\u80fd\u5f71\u54cd\u57fa\u91d1\u7b5b\u9009\u80fd\u529b\u7684\u89c2\u70b9\u76f8\u4e00\u81f4\u3002\u6211\u4eec\u7684\u53d1\u73b0\u8868\u660e\uff0c\u57fa\u4e8e\u5546\u4e1aESG\u8bc4\u7ea7\u7684\u88ab\u52a8\u6295\u8d44\u2014\u2014\u65e0\u8bba\u662f\u7531\u4e8e\u8d44\u6e90\u9650\u5236\u8fd8\u662f\u6295\u8d44\u7ec4\u5408\u7d22\u5f15\u5316\u2014\u2014\u53ef\u80fd\u5bfc\u81f4\u6295\u8d44\u7ec4\u5408\u5206\u914d\u65e0\u6cd5\u53cd\u6620\u4f01\u4e1a\u5b9e\u9645\u7684ESG\u6d3b\u52a8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1287/mnsc.2023.01322", "journal": "MS", "title": "Joint Assortment and Inventory Planning Under the Markov Chain Choice Model", "authors": ["Omar Mouchtaki", "Omar El Housni", "Guillermo Gallego", "Vineet Goyal", "Salal Humair", "Sangjo Kim", "Ali Sadighian", "Jingchen Wu"], "author_details": [{"name": "Omar Mouchtaki", "affiliations": ["NYU Stern School of Business, New York, New York 10012"]}, {"name": "Omar El Housni", "affiliations": ["School of Operations Research and Information Engineering, Cornell Tech, Cornell University, New York, New York 10044"]}, {"name": "Guillermo Gallego", "affiliations": ["School of Data Science, Chinese University of Hong Kong in Shenzhen, Shenzhen, Guangdong 518172, China"]}, {"name": "Vineet Goyal", "affiliations": ["Industrial Engineering and Operations Research, Columbia University, New York, New York 10027"]}, {"name": "Salal Humair", "affiliations": ["Amazon.com, Seattle, Washington 98109"]}, {"name": "Sangjo Kim", "affiliations": ["College of Business, Shanghai University of Finance and Economics, Shanghai 200433, China"]}, {"name": "Ali Sadighian", "affiliations": ["The Hershey Company, New York, New York 10024"]}, {"name": "Jingchen Wu", "affiliations": ["Amazon.com, Seattle, Washington 98109"]}], "abstract": "We address the joint assortment and inventory optimization problem for an online retailer facing a set of N substitutable products. The retailer must determine both the assortment and inventories of these products before the start of the selling season to maximize the expected profit. We consider a setting with dynamic SOBS, where consumers\u2019 choices follow the Markov chain choice model. This is a challenging problem, and even computing the expected profit for a given assortment and inventory solution requires solving an intractable dynamic program. We present a sample average approximation-based algorithm for the problem that achieves a regret of [Formula: see text] with respect to an linear program (LP) upper bound. Our algorithm first selects an assortment by balancing the expected revenue (from a single consumer) and the inventory cost. We do this by identifying a subset of products that can pool demand from the universe of substitutable products without significantly cannibalizing the revenue in the presence of dynamic substitution behavior of consumers. We then use a sample average approximation-based LP to decide on the inventory level for each item in the selected assortment. We numerically show that our algorithm considerably improves the performance over standard approaches from the literature on a wide range of instances of the Markov chain choice model and demonstrate that it carefully handles the inventory of products in the long tail (i.e., products with small mean total demand).", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.01322", "topics": ["\u5176\u4ed6"], "title_zh": "\u57fa\u4e8e\u9a6c\u5c14\u53ef\u592b\u94fe\u9009\u62e9\u6a21\u578b\u7684\u8054\u5408\u4ea7\u54c1\u7ec4\u5408\u4e0e\u5e93\u5b58\u89c4\u5212", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5728\u7ebf\u96f6\u552e\u5546\u5728\u9762\u5bf9\u4e00\u7ec4N\u4e2a\u53ef\u66ff\u4ee3\u4ea7\u54c1\u65f6\u7684\u8054\u5408\u4ea7\u54c1\u7ec4\u5408\u4e0e\u5e93\u5b58\u4f18\u5316\u95ee\u9898\u3002\u96f6\u552e\u5546\u5fc5\u987b\u5728\u9500\u552e\u5b63\u8282\u5f00\u59cb\u524d\u786e\u5b9a\u8fd9\u4e9b\u4ea7\u54c1\u7684\u7ec4\u5408\u548c\u5e93\u5b58\uff0c\u4ee5\u6700\u5927\u5316\u9884\u671f\u5229\u6da6\u3002\u6211\u4eec\u8003\u8651\u4e00\u4e2a\u5177\u6709\u52a8\u6001SOBS\uff08\u6d88\u8d39\u8005\u9009\u62e9\u884c\u4e3a\uff09\u7684\u573a\u666f\uff0c\u5176\u4e2d\u6d88\u8d39\u8005\u7684\u8d2d\u4e70\u51b3\u7b56\u9075\u5faa\u9a6c\u5c14\u53ef\u592b\u94fe\u9009\u62e9\u6a21\u578b\u3002\u8fd9\u662f\u4e00\u4e2a\u5177\u6709\u6311\u6218\u6027\u7684\u95ee\u9898\uff0c\u751a\u81f3\u5bf9\u4e8e\u7ed9\u5b9a\u7684\u4ea7\u54c1\u7ec4\u5408\u548c\u5e93\u5b58\u65b9\u6848\uff0c\u8ba1\u7b97\u9884\u671f\u5229\u6da6\u4e5f\u9700\u8981\u6c42\u89e3\u4e00\u4e2a\u4e0d\u53ef\u884c\u7684\u52a8\u6001\u89c4\u5212\u95ee\u9898\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u57fa\u4e8e\u6837\u672c\u5e73\u5747\u8fd1\u4f3c\u7684\u7b97\u6cd5\uff0c\u8be5\u7b97\u6cd5\u76f8\u5bf9\u4e8e\u7ebf\u6027\u89c4\u5212\uff08LP\uff09\u4e0a\u754c\u5177\u6709[Formula: see text]\u7684\u9057\u61be\u503c\u3002\u8be5\u7b97\u6cd5\u9996\u5148\u901a\u8fc7\u5e73\u8861\u5355\u4e2a\u6d88\u8d39\u8005\u5e26\u6765\u7684\u9884\u671f\u6536\u5165\u4e0e\u5e93\u5b58\u6210\u672c\uff0c\u6765\u9009\u62e9\u4ea7\u54c1\u7ec4\u5408\u3002\u5177\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u8bc6\u522b\u51fa\u4e00\u4e2a\u4ea7\u54c1\u5b50\u96c6\uff0c\u8be5\u5b50\u96c6\u80fd\u591f\u5728\u4e0d\u663e\u8457\u635f\u5bb3\u52a8\u6001\u66ff\u4ee3\u884c\u4e3a\u4e0b\u6d88\u8d39\u8005\u6536\u5165\u7684\u524d\u63d0\u4e0b\uff0c\u805a\u5408\u6765\u81ea\u53ef\u66ff\u4ee3\u4ea7\u54c1\u5168\u96c6\u7684\u5e02\u573a\u9700\u6c42\u3002\u968f\u540e\uff0c\u6211\u4eec\u4f7f\u7528\u57fa\u4e8e\u6837\u672c\u5e73\u5747\u8fd1\u4f3c\u7684\u7ebf\u6027\u89c4\u5212\u6765\u786e\u5b9a\u6240\u9009\u4ea7\u54c1\u7ec4\u5408\u4e2d\u6bcf\u4e2a\u4ea7\u54c1\u7684\u5e93\u5b58\u6c34\u5e73\u3002\u6570\u503c\u5b9e\u9a8c\u8868\u660e\uff0c\u6211\u4eec\u7684\u7b97\u6cd5\u5728\u9a6c\u5c14\u53ef\u592b\u94fe\u9009\u62e9\u6a21\u578b\u7684\u591a\u79cd\u5b9e\u4f8b\u4e0a\u663e\u8457\u4f18\u4e8e\u6587\u732e\u4e2d\u7684\u6807\u51c6\u65b9\u6cd5\uff0c\u5e76\u4e14\u80fd\u591f\u59a5\u5584\u5904\u7406\u957f\u5c3e\u4ea7\u54c1\uff08\u5373\u5e73\u5747\u603b\u9700\u6c42\u8f83\u5c0f\u7684\u4ea7\u54c1\uff09\u7684\u5e93\u5b58\u95ee\u9898\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2023.00239", "journal": "MS", "title": "Nudging Green-but-Slow Shipping Choices in Online Retail", "authors": ["Yeonjoo Lee", "Karen Donohue"], "author_details": [{"name": "Yeonjoo Lee", "affiliations": ["Smeal College of Business, The Pennsylvania State University, University Park, Pennsylvania 16802"]}, {"name": "Karen Donohue", "affiliations": ["W. P. Carey School of Business, Arizona State University, Tempe, Arizona 85281"]}], "abstract": "Faster e-commerce fulfillment often comes at a cost to the environment because of energy-intensive transportation modes and more frequent, less consolidated last-mile deliveries. Despite these environmental implications, most retailers feel pressure to provide fast fulfillment to remain competitive. But what if consumers could be nudged to voluntarily choose green-but-slow shipping? In practice, a variety of information strategies are used to nudge such decisions, but it is unclear which strategy is best and why. This study examines these questions in two logistical contexts, each involving a different type of process change to support green-but-slow shipping: shipping mode and order consolidation. We first introduce a conceptual framework for selecting information strategies based on their influence on customer perceptions related to key stakeholders in each context: delivery convenience (self), environmental impact (society), and sustainability intention (retailer). Then, drawing on behavioral research and industry practices, we identify and test the effect of a comprehensive set of information strategies (i.e., Process, Green Label, Green Process, and Green Outcome) through controlled experiments involving 3,800 participants. Experimental results suggest that different logistical contexts require distinct nudging strategies, aligning with our conceptual framework. We find that including a green label is particularly effective for the shipping mode context, especially when combined with outcome information. In contrast, process information is more promising in the order consolidation context. Also, adding financial incentives can enhance the effectiveness of information strategies without a clear environmental signal, whereas pairing them with a simple green label may be effective for low eco-conscious individuals.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.00239", "topics": ["\u5176\u4ed6"], "title_zh": "\u5728\u5728\u7ebf\u96f6\u552e\u4e2d\u5f15\u5bfc\u6d88\u8d39\u8005\u9009\u62e9\u7eff\u8272\u4f46\u7f13\u6162\u7684\u7269\u6d41\u65b9\u5f0f", "abstract_zh": "\u66f4\u5feb\u7684\u7535\u5546\u5c65\u7ea6\u5f80\u5f80\u4ee5\u73af\u5883\u6210\u672c\u4e3a\u4ee3\u4ef7\uff0c\u56e0\u4e3a\u9700\u8981\u91c7\u7528\u80fd\u8017\u8f83\u9ad8\u7684\u8fd0\u8f93\u65b9\u5f0f\u4ee5\u53ca\u66f4\u9891\u7e41\u3001\u4e0d\u96c6\u4e2d\u7684\u6700\u540e\u4e00\u516c\u91cc\u914d\u9001\u3002\u5c3d\u7ba1\u5b58\u5728\u8fd9\u4e9b\u73af\u5883\u5f71\u54cd\uff0c\u5927\u591a\u6570\u96f6\u552e\u5546\u4ecd\u9762\u4e34\u538b\u529b\uff0c\u5fc5\u987b\u63d0\u4f9b\u5feb\u901f\u5c65\u7ea6\u4ee5\u4fdd\u6301\u7ade\u4e89\u529b\u3002\u4f46\u82e5\u6d88\u8d39\u8005\u80fd\u591f\u88ab\u5f15\u5bfc\u81ea\u613f\u9009\u62e9\u7eff\u8272\u4f46\u7f13\u6162\u7684\u7269\u6d41\u65b9\u5f0f\uff0c\u4f1a\u600e\u6837\u5462\uff1f\u5728\u5b9e\u8df5\u4e2d\uff0c\u5404\u79cd\u4fe1\u606f\u7b56\u7565\u88ab\u7528\u4e8e\u5f15\u5bfc\u6b64\u7c7b\u51b3\u7b56\uff0c\u4f46\u5c1a\u4e0d\u6e05\u695a\u54ea\u79cd\u7b56\u7565\u6700\u6709\u6548\u4ee5\u53ca\u539f\u56e0\u4f55\u5728\u3002\u672c\u7814\u7a76\u5728\u4e24\u79cd\u7269\u6d41\u60c5\u5883\u4e2d\u63a2\u8ba8\u4e86\u8fd9\u4e9b\u95ee\u9898\uff0c\u6bcf\u79cd\u60c5\u5883\u6d89\u53ca\u4e0d\u540c\u7c7b\u578b\u7684\u8fc7\u7a0b\u53d8\u9769\u4ee5\u652f\u6301\u7eff\u8272\u4f46\u7f13\u6162\u7684\u7269\u6d41\uff1a\u8fd0\u8f93\u6a21\u5f0f\u548c\u8ba2\u5355\u5408\u5e76\u3002\u6211\u4eec\u9996\u5148\u63d0\u51fa\u4e00\u4e2a\u6982\u5ff5\u6846\u67b6\uff0c\u7528\u4e8e\u6839\u636e\u4fe1\u606f\u7b56\u7565\u5bf9\u987e\u5ba2\u4e0e\u5404\u5173\u952e\u5229\u76ca\u76f8\u5173\u65b9\uff08\u5373\u914d\u9001\u4fbf\u5229\u6027\uff08\u81ea\u6211\uff09\u3001\u73af\u5883\u5f71\u54cd\uff08\u793e\u4f1a\uff09\u548c\u53ef\u6301\u7eed\u6027\u610f\u56fe\uff08\u96f6\u552e\u5546\uff09\uff09\u7684\u611f\u77e5\u5f71\u54cd\u6765\u9009\u62e9\u4fe1\u606f\u7b56\u7565\u3002\u968f\u540e\uff0c\u7ed3\u5408\u884c\u4e3a\u7814\u7a76\u548c\u884c\u4e1a\u5b9e\u8df5\uff0c\u901a\u8fc7\u6d89\u53ca3800\u540d\u53c2\u4e0e\u8005\u7684\u53d7\u63a7\u5b9e\u9a8c\uff0c\u68c0\u9a8c\u4e86\u4e00\u5957\u5168\u9762\u7684\u4fe1\u606f\u7b56\u7565\uff08\u5373\u8fc7\u7a0b\u4fe1\u606f\u3001\u7eff\u8272\u6807\u7b7e\u3001\u7eff\u8272\u8fc7\u7a0b\u548c\u7eff\u8272\u7ed3\u679c\uff09\u7684\u6548\u679c\u3002\u5b9e\u9a8c\u7ed3\u679c\u8868\u660e\uff0c\u4e0d\u540c\u7684\u7269\u6d41\u60c5\u5883\u9700\u8981\u4e0d\u540c\u7684\u5f15\u5bfc\u7b56\u7565\uff0c\u8fd9\u4e0e\u6211\u4eec\u7684\u6982\u5ff5\u6846\u67b6\u76f8\u4e00\u81f4\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u8fd0\u8f93\u6a21\u5f0f\u60c5\u5883\u4e2d\uff0c\u52a0\u5165\u7eff\u8272\u6807\u7b7e\u5c24\u5176\u6709\u6548\uff0c\u7279\u522b\u662f\u5f53\u4e0e\u7ed3\u679c\u4fe1\u606f\u7ed3\u5408\u65f6\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u5728\u8ba2\u5355\u5408\u5e76\u60c5\u5883\u4e2d\uff0c\u8fc7\u7a0b\u4fe1\u606f\u66f4\u5177\u6f5c\u529b\u3002\u6b64\u5916\uff0c\u6dfb\u52a0\u8d22\u52a1\u6fc0\u52b1\u53ef\u4ee5\u5728\u6ca1\u6709\u660e\u786e\u73af\u5883\u4fe1\u53f7\u7684\u60c5\u51b5\u4e0b\u589e\u5f3a\u4fe1\u606f\u7b56\u7565\u7684\u6548\u679c\uff0c\u800c\u5c06\u6fc0\u52b1\u4e0e\u4e00\u4e2a\u7b80\u5355\u7684\u7eff\u8272\u6807\u7b7e\u7ed3\u5408\uff0c\u5219\u5bf9\u73af\u4fdd\u610f\u8bc6\u8f83\u4f4e\u7684\u6d88\u8d39\u8005\u53ef\u80fd\u66f4\u6709\u6548\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2023.00254", "journal": "MS", "title": "Start-Up Firms and Corporate Culture: Evidence from Advertised Corporate Culture", "authors": ["Jungho Lee"], "author_details": [{"name": "Jungho Lee", "affiliations": ["School of Economics, Yonsei University, Seoul 03722, South Korea"]}], "abstract": "I document the advertised corporate culture among start-up firms from an online job board. Two corporate culture types emerge: one that concerns the well-being of employees (worker-centered culture) and another that emphasizes other values, such as customers, firms, and markets (firm-centered culture). The worker-centered culture attracts 20% more applications than the other culture type. Firms advertising the worker-centered culture pay 5% lower salaries than measurably similar jobs. Outcomes do not significantly differ among firms that promote different types of corporate culture. To assess whether a worker-centered culture is adopted to reduce labor costs or enhance productivity, I develop an equilibrium model. The model implies that many firms adopt a worker-centered culture primarily for cost savings.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.00254", "topics": ["\u5176\u4ed6"], "title_zh": "\u521d\u521b\u4f01\u4e1a\u4e0e\u4f01\u4e1a\u6587\u5316\uff1a\u6765\u81ea\u5e7f\u544a\u4e2d\u4f01\u4e1a\u6587\u5316\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u57fa\u4e8e\u4e00\u4e2a\u5728\u7ebf\u62db\u8058\u5e73\u53f0\u6536\u96c6\u4e86\u521d\u521b\u4f01\u4e1a\u6240\u5ba3\u4f20\u7684\u4f01\u4e1a\u6587\u5316\u3002\u4e24\u79cd\u4f01\u4e1a\u6587\u5316\u7c7b\u578b\u663e\u73b0\u51fa\u6765\uff1a\u4e00\u79cd\u5173\u6ce8\u5458\u5de5\u798f\u7949\uff08\u5458\u5de5\u5bfc\u5411\u578b\u6587\u5316\uff09\uff0c\u53e6\u4e00\u79cd\u5f3a\u8c03\u5176\u4ed6\u4ef7\u503c\u89c2\uff0c\u5982\u5ba2\u6237\u3001\u4f01\u4e1a\u53ca\u5e02\u573a\uff08\u4f01\u4e1a\u5bfc\u5411\u578b\u6587\u5316\uff09\u3002\u5458\u5de5\u5bfc\u5411\u578b\u6587\u5316\u5438\u5f15\u6bd4\u5176\u4ed6\u7c7b\u578b\u591a20%\u7684\u7533\u8bf7\u3002\u5ba3\u4f20\u5458\u5de5\u5bfc\u5411\u578b\u6587\u5316\u7684\u4f01\u4e1a\u6240\u63d0\u4f9b\u7684\u85aa\u8d44\u6bd4\u53ef\u8861\u91cf\u76f8\u4f3c\u5c97\u4f4d\u4f4e5%\u3002\u5728\u4e0d\u540c\u4f01\u4e1a\u6587\u5316\u5ba3\u4f20\u7684\u4f01\u4e1a\u4e4b\u95f4\uff0c\u5176\u4ed6\u7ed3\u679c\u6ca1\u6709\u663e\u8457\u5dee\u5f02\u3002\u4e3a\u4e86\u5224\u65ad\u4f01\u4e1a\u91c7\u7528\u5458\u5de5\u5bfc\u5411\u578b\u6587\u5316\u662f\u51fa\u4e8e\u964d\u4f4e\u52b3\u52a8\u529b\u6210\u672c\u8fd8\u662f\u63d0\u5347\u751f\u4ea7\u7387\uff0c\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u5747\u8861\u6a21\u578b\u3002\u8be5\u6a21\u578b\u8868\u660e\uff0c\u8bb8\u591a\u4f01\u4e1a\u91c7\u7528\u5458\u5de5\u5bfc\u5411\u578b\u6587\u5316\u4e3b\u8981\u662f\u4e3a\u4e86\u964d\u4f4e\u6210\u672c\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2022.02785", "journal": "MS", "title": "Simple and (Approximately) Optimal Mechanism in Efficiency and Equality Tradeoff", "authors": ["Zhou Chen", "Qi Qi", "Changjun Wang", "Zhen Wang"], "author_details": [{"name": "Zhou Chen", "affiliations": ["School of Economics and Management, Southeast University, Nanjing 210096, China"]}, {"name": "Qi Qi", "affiliations": ["Gaoling School of Artificial Intelligence, Renmin University of China, Beijing 100872, China; and Beijing Key Laboratory of Research on Large Models and Intelligent Governance, Beijing 100872, China; and Engineering Research Center of Next-Generation Intelligent Search and Recommendation, Ministry of Education, Beijing 100872, China"]}, {"name": "Changjun Wang", "affiliations": ["State Key Laboratory of Mathematical Sciences, Academy of Mathematics and Systems Science, Chinese Academy of Sciences, Beijing 100190, China"]}, {"name": "Zhen Wang", "affiliations": ["Research Institute for Interdisciplinary Sciences, School of Information Management and Engineering, Shanghai University of Finance and Economics, Shanghai 200433, China; and Key Laboratory of Interdisciplinary Research of Computation and Economics (Shanghai University of Finance and Economics), Ministry of Education, Shanghai 200433, China"]}], "abstract": "Many large cities have adopted a policy of restricting the number of new vehicle licenses in order to address the challenges of traffic and air pollution problems. An important question that then arises is how to allocate these limited new license quotas among a large set of demanders while taking both social efficiency and equality into consideration. Inspired by this practical problem, we study the problem of designing simple and optimal mechanisms to tradeoff between efficiency and equality in a similar public goods allocation problem. We first propose a truthful two-group mechanism framework that is both general and simple and then use it to compute the optimal solution that maximizes social efficiency while guaranteeing a certain level of equality. Interestingly and surprisingly, under some natural conditions regarding the players\u2019 private values, we show that the optimal mechanisms within the proposed framework are always the mechanisms that first run an auction and then run a lottery (ATL for short). In addition, beyond the framework and those conditions, we prove that the ATL mechanism can always guarantee at least [Formula: see text] ([Formula: see text] is the minimum equality level) of the optimal solution efficiency. This approximation ratio can in practice be further improved to near-optimal when resources are scarce and the natural conditions hold. We further establish a theoretical connection between these natural conditions and common value distributions, demonstrating that these conditions are widely satisfied in practice. Finally, we implement several experiments to verify the ATL mechanism\u2019s optimality and robustness.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2022.02785", "topics": ["\u5176\u4ed6"], "title_zh": "\u6548\u7387\u4e0e\u5e73\u7b49\u6743\u8861\u4e2d\u7684\u7b80\u5355\u4e14\uff08\u8fd1\u4f3c\uff09\u6700\u4f18\u673a\u5236", "abstract_zh": "\u8bb8\u591a\u5927\u57ce\u5e02\u5df2\u91c7\u53d6\u9650\u5236\u65b0\u8f66\u724c\u7167\u6570\u91cf\u7684\u653f\u7b56\uff0c\u4ee5\u5e94\u5bf9\u4ea4\u901a\u62e5\u5835\u548c\u7a7a\u6c14\u6c61\u67d3\u95ee\u9898\u3002\u968f\u4e4b\u800c\u6765\u7684\u4e00\u4e2a\u91cd\u8981\u95ee\u9898\u662f\uff0c\u5982\u4f55\u5728\u5927\u91cf\u9700\u6c42\u8005\u4e4b\u95f4\u5206\u914d\u8fd9\u4e9b\u6709\u9650\u7684\u65b0\u724c\u7167\u914d\u989d\uff0c\u540c\u65f6\u517c\u987e\u793e\u4f1a\u6548\u7387\u4e0e\u5e73\u7b49\u3002\u53d7\u8fd9\u4e00\u5b9e\u9645\u95ee\u9898\u7684\u542f\u53d1\uff0c\u6211\u4eec\u7814\u7a76\u4e86\u5728\u7c7b\u4f3c\u516c\u5171\u7269\u54c1\u5206\u914d\u95ee\u9898\u4e2d\u8bbe\u8ba1\u7b80\u5355\u4e14\u6700\u4f18\u673a\u5236\u4ee5\u6743\u8861\u6548\u7387\u4e0e\u5e73\u7b49\u7684\u95ee\u9898\u3002\u6211\u4eec\u9996\u5148\u63d0\u51fa\u4e86\u4e00\u79cd\u65e2\u901a\u7528\u53c8\u7b80\u5355\u7684\u8bda\u5b9e\u4e24\u7ec4\u673a\u5236\u6846\u67b6\uff0c\u5e76\u5229\u7528\u8be5\u6846\u67b6\u8ba1\u7b97\u51fa\u5728\u6700\u5927\u5316\u793e\u4f1a\u6548\u7387\u7684\u540c\u65f6\u4fdd\u8bc1\u4e00\u5b9a\u5e73\u7b49\u6c34\u5e73\u7684\u6700\u4f18\u89e3\u3002\u6709\u8da3\u4e14\u51fa\u4eba\u610f\u6599\u7684\u662f\uff0c\u5728\u73a9\u5bb6\u79c1\u4eba\u4ef7\u503c\u6ee1\u8db3\u67d0\u4e9b\u81ea\u7136\u6761\u4ef6\u7684\u524d\u63d0\u4e0b\uff0c\u6211\u4eec\u8bc1\u660e\u4e86\u5728\u6240\u63d0\u51fa\u7684\u6846\u67b6\u5185\uff0c\u6700\u4f18\u673a\u5236\u59cb\u7ec8\u662f\u5148\u8fdb\u884c\u62cd\u5356\u518d\u8fdb\u884c\u62bd\u7b7e\uff08\u7b80\u79f0ATL\u673a\u5236\uff09\u3002\u6b64\u5916\uff0c\u5728\u6846\u67b6\u53ca\u8fd9\u4e9b\u6761\u4ef6\u4e4b\u5916\uff0c\u6211\u4eec\u8bc1\u660e\u4e86ATL\u673a\u5236\u59cb\u7ec8\u80fd\u4fdd\u8bc1\u81f3\u5c11[Formula: see text]\uff08[Formula: see text]\u4e3a\u6700\u4f4e\u5e73\u7b49\u6c34\u5e73\uff09\u7684\u6700\u4f18\u89e3\u6548\u7387\u3002\u5728\u8d44\u6e90\u7a00\u7f3a\u4e14\u81ea\u7136\u6761\u4ef6\u6210\u7acb\u7684\u60c5\u51b5\u4e0b\uff0c\u8be5\u8fd1\u4f3c\u6bd4\u7387\u5728\u5b9e\u8df5\u4e2d\u53ef\u8fdb\u4e00\u6b65\u63d0\u5347\u81f3\u8fd1\u6700\u4f18\u6c34\u5e73\u3002\u6211\u4eec\u8fd8\u5efa\u7acb\u4e86\u8fd9\u4e9b\u81ea\u7136\u6761\u4ef6\u4e0e\u5171\u540c\u4ef7\u503c\u5206\u5e03\u4e4b\u95f4\u7684\u7406\u8bba\u8054\u7cfb\uff0c\u8868\u660e\u8fd9\u4e9b\u6761\u4ef6\u5728\u5b9e\u8df5\u4e2d\u88ab\u5e7f\u6cdb\u6ee1\u8db3\u3002\u6700\u540e\uff0c\u6211\u4eec\u901a\u8fc7\u82e5\u5e72\u5b9e\u9a8c\u9a8c\u8bc1\u4e86ATL\u673a\u5236\u7684\u6700\u4f18\u6027\u4e0e\u9c81\u68d2\u6027\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2023.02773", "journal": "MS", "title": "Does Agglomeration Enhance Property Value?", "authors": ["Crocker H. Liu", "Chen Zheng", "Bing Zhu"], "author_details": [{"name": "Crocker H. Liu", "affiliations": ["Cornell University, Ithaca, New York 14853"]}, {"name": "Chen Zheng", "affiliations": ["University of Bath, Bath BA2 7AY, United Kingdom"]}, {"name": "Bing Zhu", "affiliations": ["Technical University of Munich, 80333 Munich, Germany"]}], "abstract": "Does agglomeration within a building and/or neighborhood enhance or weaken property value? The valuation impact is unclear ex ante, given that agglomeration tradesoff enhanced productivity at the expense of a more concentrated tenant base. We find that a value premium exists only when agglomeration at both the building and neighborhood levels consists of firms in the same industry. This premium represents capitalized knowledge spillover externalities. Additionally, we show the stock market rewards real estate investment trusts that transact specialized buildings. The valuation consequences arising from agglomeration in the underlying real estate market are thus consistent with the public real estate market.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.02773", "topics": ["\u5176\u4ed6"], "title_zh": "\u96c6\u805a\u662f\u5426\u63d0\u5347\u623f\u4ea7\u4ef7\u503c\uff1f", "abstract_zh": "\u5efa\u7b51\u7269\u5185\u90e8\u548c/\u6216\u90bb\u91cc\u533a\u57df\u7684\u96c6\u805a\u662f\u5426\u589e\u5f3a\u6216\u524a\u5f31\u623f\u4ea7\u4ef7\u503c\uff1f\u7531\u4e8e\u96c6\u805a\u5728\u63d0\u9ad8\u751f\u4ea7\u7387\u7684\u540c\u65f6\u4e5f\u5e26\u6765\u4e86\u66f4\u96c6\u4e2d\u7684\u79df\u6237\u57fa\u7840\uff0c\u5176\u5bf9\u4ef7\u503c\u7684\u5f71\u54cd\u5728\u4e8b\u524d\u5c1a\u4e0d\u660e\u786e\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u53ea\u6709\u5f53\u5efa\u7b51\u548c\u90bb\u91cc\u533a\u57df\u7684\u96c6\u805a\u5747\u5305\u542b\u540c\u884c\u4e1a\u7684\u4f01\u4e1a\u65f6\uff0c\u624d\u4f1a\u51fa\u73b0\u4ef7\u503c\u6ea2\u4ef7\u3002\u8fd9\u4e00\u6ea2\u4ef7\u53cd\u6620\u4e86\u77e5\u8bc6\u6ea2\u51fa\u5916\u90e8\u6027\u88ab\u8d44\u672c\u5316\u7684\u7ed3\u679c\u3002\u6b64\u5916\uff0c\u6211\u4eec\u8fd8\u53d1\u73b0\u80a1\u7968\u5e02\u573a\u5bf9\u4ea4\u6613\u4e13\u95e8\u5316\u5efa\u7b51\u7684\u623f\u5730\u4ea7\u6295\u8d44\u4fe1\u6258\u7ed9\u4e88\u56de\u62a5\u3002\u56e0\u6b64\uff0c\u5e95\u5c42\u623f\u5730\u4ea7\u5e02\u573a\u7684\u96c6\u805a\u6240\u4ea7\u751f\u7684\u4f30\u503c\u5f71\u54cd\u4e0e\u516c\u5f00\u623f\u5730\u4ea7\u5e02\u573a\u662f\u4e00\u81f4\u7684\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2025.02523", "journal": "MS", "title": "The Rapid Adoption of Generative AI", "authors": ["Alexander Bick", "Adam Blandin", "David J. Deming"], "author_details": [{"name": "Alexander Bick", "affiliations": ["Federal Reserve Bank of St. Louis, St. Louis, Missouri 63102; and CEPR, London EC1R 5HL, United Kingdom"]}, {"name": "Adam Blandin", "affiliations": ["Vanderbilt University, Nashville, Tennessee 37235"]}, {"name": "David J. Deming", "affiliations": ["Harvard Kennedy School, Cambridge, Massachusetts 02138; and NBER, Cambridge, Massachusetts 02138"]}], "abstract": "Generative artificial intelligence (genAI) is a potentially important new technology, but its impact on the economy depends on the speed and intensity of adoption. This paper reports results from a series of nationally representative U.S. surveys of genAI use at work and at home. As of late 2024, 45% of the U.S. population age 18\u201364 uses genAI. Among employed respondents, 27% used genAI for work at least once in the previous week: 10% used it every workday and 17% on some but not all workdays. Relative to each technology\u2019s first mass-market product launch, work adoption of genAI has been faster than the personal computer (PC), and overall adoption has outpaced both PCs and the internet by an even wider margin. Between 1% and 7% of all work hours are currently assisted by genAI, and respondents report time savings equivalent to 1.4% of total work hours. Potential productivity gains vary widely by industry, and firm climate and policies play an important role in adoption patterns.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2025.02523", "title_zh": "\u751f\u6210\u5f0f\u4eba\u5de5\u667a\u80fd\u7684\u5feb\u901f\u91c7\u7eb3", "abstract_zh": "\u751f\u6210\u5f0f\u4eba\u5de5\u667a\u80fd\uff08genAI\uff09\u662f\u4e00\u79cd\u53ef\u80fd\u5bf9\u7ecf\u6d4e\u4ea7\u751f\u91cd\u8981\u5f71\u54cd\u7684\u65b0\u6280\u672f\uff0c\u4f46\u5176\u5bf9\u7ecf\u6d4e\u7684\u5f71\u54cd\u53d6\u51b3\u4e8e\u91c7\u7eb3\u7684\u901f\u5ea6\u548c\u5f3a\u5ea6\u3002\u672c\u6587\u57fa\u4e8e\u4e00\u7cfb\u5217\u5177\u6709\u5168\u56fd\u4ee3\u8868\u6027\u7684\u7f8e\u56fd\u5173\u4e8egenAI\u5728\u5de5\u4f5c\u548c\u5bb6\u5ead\u4e2d\u4f7f\u7528\u60c5\u51b5\u7684\u8c03\u67e5\u62a5\u544a\u4e86\u7ed3\u679c\u3002\u622a\u81f32024\u5e74\u5e95\uff0c\u7f8e\u56fd18\u81f364\u5c81\u4eba\u53e3\u4e2d\u670945%\u4f7f\u7528genAI\u3002\u5728\u5c31\u4e1a\u4eba\u7fa4\u4e2d\uff0c27%\u7684\u53d7\u8bbf\u8005\u5728\u8fc7\u53bb\u4e00\u5468\u5185\u81f3\u5c11\u4f7f\u7528\u8fc7\u4e00\u6b21genAI\u7528\u4e8e\u5de5\u4f5c\uff1a\u5176\u4e2d10%\u6bcf\u5929\u90fd\u5728\u5de5\u4f5c\u65f6\u4f7f\u7528\uff0c17%\u5219\u5728\u90e8\u5206\u5de5\u4f5c\u65e5\u4f7f\u7528\u3002\u4e0e\u6bcf\u9879\u6280\u672f\u9996\u6b21\u5927\u89c4\u6a21\u4e0a\u5e02\u4ea7\u54c1\u76f8\u6bd4\uff0cgenAI\u5728\u5de5\u4f5c\u9886\u57df\u7684\u91c7\u7eb3\u901f\u5ea6\u5df2\u5feb\u4e8e\u4e2a\u4eba\u8ba1\u7b97\u673a\uff08PC\uff09\uff0c\u4e14\u6574\u4f53\u91c7\u7eb3\u901f\u5ea6\u4e5f\u663e\u8457\u8d85\u8fc7PC\u548c\u4e92\u8054\u7f51\u3002\u76ee\u524d\uff0cgenAI\u534f\u52a9\u4e86\u5de5\u4f5c\u65f6\u95f4\u76841%\u81f37%\uff0c\u53d7\u8bbf\u8005\u62a5\u544a\u7684\u65f6\u95f4\u8282\u7701\u76f8\u5f53\u4e8e\u603b\u5de5\u4f5c\u65f6\u95f4\u76841.4%\u3002\u4e0d\u540c\u884c\u4e1a\u7684\u6f5c\u5728\u751f\u4ea7\u7387\u63d0\u5347\u5dee\u5f02\u8f83\u5927\uff0c\u4f01\u4e1a\u6587\u5316\u548c\u653f\u7b56\u5728\u91c7\u7eb3\u6a21\u5f0f\u4e2d\u53d1\u6325\u7740\u91cd\u8981\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2023.02065", "journal": "MS", "title": "Earnings Conference Calls and the SEC Comment Letter Process", "authors": ["Alina Lerman", "Thomas D. Steffen", "Kangkang Zhang"], "author_details": [{"name": "Alina Lerman", "affiliations": ["School of Business, University of Connecticut, Storrs, Connecticut 06269"]}, {"name": "Thomas D. Steffen", "affiliations": ["School of Management, Yale University, New Haven, Connecticut 06520"]}, {"name": "Kangkang Zhang", "affiliations": ["Gies College of Business, University of Illinois Urbana-Champaign, Champaign, Illinois 61820"]}], "abstract": "The Securities and Exchange Commission (SEC) reviews firms\u2019 financial reports and issues comment letters to ensure compliance with applicable disclosure and accounting requirements. We explore the nature, determinants, and consequences of SEC comment letters that refer to information disclosed in voluntary earnings conference calls. Using hand-collected data, we document that the SEC primarily references these voluntary disclosures to illustrate insufficiencies and, less commonly, inconsistencies in mandatory filings across a wide range of topics. These letters are more likely to be issued when filing reviews are more complex, SEC staff are less resource constrained, and for firms with more institutional investors and analysts. Conference call\u2013related comments tend to occur during higher-quality review processes and require greater remediation costs than other comments. The SEC\u2019s use of call disclosures also leads to more pronounced changes in firms\u2019 subsequent mandatory filings, particularly when the firm indicates agreement with SEC comments. However, we observe a mixed effect on the overall information environment, consistent with possible unintended consequences for the quality of firms\u2019 voluntary disclosures.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.02065", "title_zh": "\u76c8\u5229\u7535\u8bdd\u4f1a\u8bae\u4e0e\u7f8e\u56fd\u8bc1\u5238\u4ea4\u6613\u59d4\u5458\u4f1a\u8bc4\u8bba\u4fe1\u6d41\u7a0b", "abstract_zh": "\u7f8e\u56fd\u8bc1\u5238\u4ea4\u6613\u59d4\u5458\u4f1a\uff08SEC\uff09\u4f1a\u5ba1\u67e5\u4f01\u4e1a\u7684\u8d22\u52a1\u62a5\u544a\uff0c\u5e76\u53d1\u51fa\u8bc4\u8bba\u4fe1\u4ee5\u786e\u4fdd\u5176\u7b26\u5408\u76f8\u5173\u62ab\u9732\u548c\u4f1a\u8ba1\u8981\u6c42\u3002\u6211\u4eec\u63a2\u8ba8\u4e86SEC\u5728\u8bc4\u8bba\u4fe1\u4e2d\u63d0\u53ca\u81ea\u613f\u6027\u76c8\u5229\u7535\u8bdd\u4f1a\u8bae\u62ab\u9732\u4fe1\u606f\u7684\u6027\u8d28\u3001\u51b3\u5b9a\u56e0\u7d20\u53ca\u5176\u540e\u679c\u3002\u901a\u8fc7\u624b\u5de5\u6536\u96c6\u7684\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0SEC\u4e3b\u8981\u5229\u7528\u8fd9\u4e9b\u81ea\u613f\u62ab\u9732\u4fe1\u606f\u6765\u8bf4\u660e\u5f3a\u5236\u6027\u6587\u4ef6\u4e2d\u5b58\u5728\u4e0d\u8db3\uff0c\u8f83\u5c11\u60c5\u51b5\u4e0b\u5219\u6307\u51fa\u4e0d\u4e00\u81f4\u4e4b\u5904\uff0c\u6d89\u53ca\u8303\u56f4\u5e7f\u6cdb\u3002\u8fd9\u4e9b\u8bc4\u8bba\u4fe1\u66f4\u53ef\u80fd\u5728\u6587\u4ef6\u5ba1\u67e5\u66f4\u4e3a\u590d\u6742\u3001SEC\u5de5\u4f5c\u4eba\u5458\u8d44\u6e90\u76f8\u5bf9\u5bbd\u677e\uff0c\u4ee5\u53ca\u4f01\u4e1a\u62e5\u6709\u66f4\u591a\u673a\u6784\u6295\u8d44\u8005\u548c\u5206\u6790\u5e08\u7684\u60c5\u51b5\u4e0b\u88ab\u53d1\u51fa\u3002\u4e0e\u7535\u8bdd\u4f1a\u8bae\u76f8\u5173\u7684\u8bc4\u8bba\u901a\u5e38\u51fa\u73b0\u5728\u9ad8\u8d28\u91cf\u7684\u5ba1\u67e5\u6d41\u7a0b\u4e2d\uff0c\u5e76\u9700\u8981\u66f4\u9ad8\u7684\u6574\u6539\u6210\u672c\u3002SEC\u5bf9\u7535\u8bdd\u4f1a\u8bae\u62ab\u9732\u7684\u4f7f\u7528\u8fd8\u4f1a\u5bfc\u81f4\u4f01\u4e1a\u540e\u7eed\u5f3a\u5236\u6027\u6587\u4ef6\u53d1\u751f\u66f4\u4e3a\u663e\u8457\u7684\u53d8\u66f4\uff0c\u5c24\u5176\u662f\u5728\u4f01\u4e1a\u660e\u786e\u8868\u793a\u540c\u610fSEC\u610f\u89c1\u7684\u60c5\u51b5\u4e0b\u3002\u7136\u800c\uff0c\u6211\u4eec\u89c2\u5bdf\u5230\u5bf9\u6574\u4f53\u4fe1\u606f\u73af\u5883\u7684\u5f71\u54cd\u662f\u6df7\u5408\u7684\uff0c\u8fd9\u53ef\u80fd\u53cd\u6620\u51fa\u5bf9\u4f01\u4e1a\u81ea\u613f\u62ab\u9732\u8d28\u91cf\u7684\u6f5c\u5728\u8d1f\u9762\u540e\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1287/mnsc.2024.07650", "journal": "MS", "title": "Macroeconomic Announcements and the News That Matters Most to Investors", "authors": ["Samia Badidi", "Martijn Boons", "Rik Frehen"], "author_details": [{"name": "Samia Badidi", "affiliations": ["Tilburg University, 5000 LE Tilburg, Netherlands"]}, {"name": "Martijn Boons", "affiliations": ["Nova School of Business and Economics, Universidade NOVA de Lisboa, 2775-405 Carcavelos, Portugal"]}, {"name": "Rik Frehen", "affiliations": ["Tilburg University, 5000 LE Tilburg, Netherlands"]}], "abstract": "Studying a large set of macroeconomic announcements (MAs) and disentangling their news content, we show that a portfolio of stocks that pays off around MAs that negatively impact the aggregate stock market commands a positive risk premium. Adding this portfolio to a position in the aggregate market substantially increases Sharpe ratio while reducing MA risk exposure, which implies a rejection of the CAPM. Using state-of-the-art measures of cash flow and discount rate news and consistent with prominent intertemporal CAPM specifications, we argue that the portfolio\u2019s risk premium compensates investors for large reinvestment risk. Thus, we conclude that the MA news that matters most to investors is discount rate news and not cash flows news.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07650", "title_zh": "\u5b8f\u89c2\u7ecf\u6d4e\u516c\u544a\u4e0e\u6295\u8d44\u8005\u6700\u5173\u6ce8\u7684\u65b0\u95fb", "abstract_zh": "\u901a\u8fc7\u5bf9\u5927\u91cf\u5b8f\u89c2\u7ecf\u6d4e\u516c\u544a\uff08MA\uff09\u8fdb\u884c\u7814\u7a76\uff0c\u5e76\u5206\u79bb\u5176\u65b0\u95fb\u5185\u5bb9\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u4e00\u4e2a\u5728\u5bf9\u6574\u4f53\u80a1\u5e02\u4ea7\u751f\u8d1f\u9762\u5f71\u54cd\u7684\u5b8f\u89c2\u7ecf\u6d4e\u516c\u544a\u671f\u95f4\u8868\u73b0\u826f\u597d\u7684\u80a1\u7968\u7ec4\u5408\uff0c\u80fd\u591f\u83b7\u5f97\u6b63\u7684\u98ce\u9669\u6ea2\u4ef7\u3002\u5c06\u8be5\u7ec4\u5408\u4e0e\u6574\u4f53\u5e02\u573a\u6295\u8d44\u76f8\u7ed3\u5408\uff0c\u663e\u8457\u63d0\u9ad8\u4e86\u590f\u666e\u6bd4\u7387\uff0c\u540c\u65f6\u964d\u4f4e\u4e86\u5bf9\u5b8f\u89c2\u7ecf\u6d4e\u516c\u544a\u7684\u98ce\u9669\u66b4\u9732\uff0c\u8fd9\u8868\u660e\u5bf9\u8d44\u672c\u8d44\u4ea7\u5b9a\u4ef7\u6a21\u578b\uff08CAPM\uff09\u7684\u62d2\u7edd\u3002\u5229\u7528\u6700\u5148\u8fdb\u7684\u73b0\u91d1\u6d41\u548c\u6298\u73b0\u7387\u65b0\u95fb\u8861\u91cf\u65b9\u6cd5\uff0c\u5e76\u4e0e\u4e3b\u6d41\u7684\u8de8\u671fCAPM\u6a21\u578b\u8bbe\u5b9a\u76f8\u4e00\u81f4\uff0c\u6211\u4eec\u8ba4\u4e3a\u8be5\u7ec4\u5408\u7684\u98ce\u9669\u6ea2\u4ef7\u8865\u507f\u4e86\u6295\u8d44\u8005\u9762\u4e34\u7684\u91cd\u5927\u518d\u6295\u8d44\u98ce\u9669\u3002\u56e0\u6b64\uff0c\u6211\u4eec\u5f97\u51fa\u7ed3\u8bba\uff1a\u5bf9\u6295\u8d44\u8005\u800c\u8a00\u6700\u91cd\u8981\u7684\u5b8f\u89c2\u7ecf\u6d4e\u516c\u544a\u65b0\u95fb\u662f\u6298\u73b0\u7387\u65b0\u95fb\uff0c\u800c\u975e\u73b0\u91d1\u6d41\u65b0\u95fb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1287/mnsc.2024.06429", "journal": "MS", "title": "Female Equity Analysts and Corporate Environmental and Social Performance", "authors": ["Kai Li", "Feng Mai", "Gabriel Wong", "Chelsea Yang", "Tengfei Zhang"], "author_details": [{"name": "Kai Li", "affiliations": ["Sauder School of Business, University of British Columbia, Vancouver, British Columbia V6T 1Z2, Canada"]}, {"name": "Feng Mai", "affiliations": ["Tippie College of Business, University of Iowa, Iowa City, Iowa 52242"]}, {"name": "Gabriel Wong", "affiliations": ["Department of Economics, Cardiff University, Cardiff CF10 3EU, United Kingdom"]}, {"name": "Chelsea Yang", "affiliations": ["Sauder School of Business, University of British Columbia, Vancouver, British Columbia V6T 1Z2, Canada"]}, {"name": "Tengfei Zhang", "affiliations": ["Rutgers School of Business-Camden, Rutgers University, Camden, New Jersey 08102"]}], "abstract": "This paper examines the impact of female analyst coverage on firms\u2019 environmental and social (E&S) performance. Exploiting broker closures as a quasi-exogenous shock to analyst coverage, we find that firms experiencing an exogenous decline in female analyst coverage subsequently show a significantly larger drop in E&S scores than those experiencing an equivalent decline in male analyst coverage. To explore the underlying mechanisms, we develop novel machine-learning models to analyze more than 2.4 million analyst reports and 120,000 earnings call transcripts. Our analysis shows that, compared with their male counterparts, female analysts are more likely to address E&S issues, particularly those involving regulatory compliance, stakeholders, and the environment, in both research reports and earnings conference calls. They also display distinct cognitive and linguistic patterns when discussing E&S issues. Furthermore, female analysts are more likely to issue lower stock recommendations and target prices (lower stock recommendations) following negative E&S discussions in their reports (E&S incidents) than male analysts. Finally, investors respond more strongly to female analysts\u2019 negative tones when discussing E&S issues. Overall, our findings suggest that gender diversity among analysts plays a significant role in shaping corporate E&S practices and provide new insights into the origins of gender differences in skills within the equity analyst profession.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06429", "topics": ["\u5176\u4ed6"], "title_zh": "\u5973\u6027\u80a1\u7968\u5206\u6790\u5e08\u4e0e\u4f01\u4e1a\u73af\u5883\u548c\u793e\u4f1a\u8868\u73b0", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5973\u6027\u5206\u6790\u5e08\u8986\u76d6\u5bf9\u4f01\u4e1a\u73af\u5883\u548c\u793e\u4f1a\uff08E&S\uff09\u8868\u73b0\u7684\u5f71\u54cd\u3002\u5229\u7528\u5238\u5546\u5173\u95ed\u8fd9\u4e00\u5206\u6790\u5e08\u8986\u76d6\u7684\u5916\u751f\u51b2\u51fb\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u7ecf\u5386\u5916\u751f\u6027\u5973\u6027\u5206\u6790\u5e08\u8986\u76d6\u51cf\u5c11\u7684\u4f01\u4e1a\uff0c\u5176E&S\u8bc4\u5206\u7684\u4e0b\u964d\u5e45\u5ea6\u663e\u8457\u5927\u4e8e\u7ecf\u5386\u540c\u7b49\u7a0b\u5ea6\u7537\u6027\u5206\u6790\u5e08\u8986\u76d6\u51cf\u5c11\u7684\u4f01\u4e1a\u3002\u4e3a\u63a2\u7a76\u5176\u5185\u5728\u673a\u5236\uff0c\u6211\u4eec\u5f00\u53d1\u4e86\u65b0\u578b\u673a\u5668\u5b66\u4e60\u6a21\u578b\uff0c\u5206\u6790\u4e86\u8d85\u8fc7240\u4e07\u4efd\u5206\u6790\u5e08\u62a5\u544a\u548c12\u4e07\u4efd\u8d22\u62a5\u7535\u8bdd\u4f1a\u8bae\u8bb0\u5f55\u3002\u5206\u6790\u663e\u793a\uff0c\u4e0e\u7537\u6027\u5206\u6790\u5e08\u76f8\u6bd4\uff0c\u5973\u6027\u5206\u6790\u5e08\u5728\u7814\u7a76\u62a5\u544a\u548c\u8d22\u62a5\u7535\u8bdd\u4f1a\u8bae\u4e2d\u66f4\u53ef\u80fd\u63d0\u53caE&S\u95ee\u9898\uff0c\u5c24\u5176\u662f\u6d89\u53ca\u76d1\u7ba1\u5408\u89c4\u3001\u5229\u76ca\u76f8\u5173\u65b9\u548c\u73af\u5883\u95ee\u9898\u7684\u5185\u5bb9\u3002\u5979\u4eec\u5728\u8ba8\u8bbaE&S\u95ee\u9898\u65f6\u4e5f\u8868\u73b0\u51fa\u72ec\u7279\u7684\u8ba4\u77e5\u548c\u8bed\u8a00\u6a21\u5f0f\u3002\u6b64\u5916\uff0c\u5973\u6027\u5206\u6790\u5e08\u5728\u62a5\u544a\u4e2d\u51fa\u73b0\u8d1f\u9762E&S\u8ba8\u8bba\uff08E&S\u4e8b\u4ef6\uff09\u540e\uff0c\u66f4\u503e\u5411\u4e8e\u7ed9\u51fa\u66f4\u4f4e\u7684\u80a1\u7968\u8bc4\u7ea7\u548c\u76ee\u6807\u80a1\u4ef7\uff0c\u800c\u7537\u6027\u5206\u6790\u5e08\u5219\u8f83\u5c11\u5982\u6b64\u3002\u6700\u540e\uff0c\u6295\u8d44\u8005\u5bf9\u5973\u6027\u5206\u6790\u5e08\u5728\u8ba8\u8bbaE&S\u95ee\u9898\u65f6\u8868\u73b0\u51fa\u7684\u8d1f\u9762\u8bed\u6c14\u53cd\u5e94\u66f4\u4e3a\u5f3a\u70c8\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u5206\u6790\u5e08\u961f\u4f0d\u4e2d\u7684\u6027\u522b\u591a\u6837\u6027\u5728\u5851\u9020\u4f01\u4e1aE&S\u5b9e\u8df5\u65b9\u9762\u53d1\u6325\u7740\u91cd\u8981\u4f5c\u7528\uff0c\u5e76\u4e3a\u7406\u89e3\u80a1\u7968\u5206\u6790\u5e08\u804c\u4e1a\u4e2d\u6027\u522b\u5dee\u5f02\u7684\u6280\u80fd\u6765\u6e90\u63d0\u4f9b\u4e86\u65b0\u7684\u6d1e\u89c1\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2025.00232", "journal": "MS", "title": "Do Financial Advisors Charge Sustainable Investors a Premium?", "authors": ["Marten Laudi", "Paul Smeets", "Utz Weitzel"], "author_details": [{"name": "Marten Laudi", "affiliations": ["Faculty of Business Studies and Economics, University of Bremen, 28359 Bremen, Germany"]}, {"name": "Paul Smeets", "affiliations": ["Faculty of Economics and Business, University of Amsterdam, 1001 NL Amsterdam, Netherlands"]}, {"name": "Utz Weitzel", "affiliations": ["School of Business and Economics, Vrije Universiteit Amsterdam and Tinbergen Institute, 1081 HV Amsterdam, Netherlands; and Department of Economics and Business Economics, Radboud University, 6525 AJ, Nijmegen, Netherlands"]}], "abstract": "Despite growing regulatory concerns about potential overcharging of sustainable investors, empirical evidence is lacking. In two controlled laboratory-in-the-field experiments with 415 professional financial advisors from Europe and the United States and an incentivized survey, we identify two distinct but interacting effects. First, advisors charge sustainable investors a premium. This premium persists even when accounting for differences in skill, effort, and costs. Second, advisors impose higher fees on clients with low financial literacy. These factors interact. Sustainable investors with low financial literacy are charged the highest fee, whereas those with high financial literacy do not pay a sustainability premium. Our findings suggest that advisors extract additional fees for sustainable investment mandates but avoid overcharging sustainable investors with high financial literacy.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2025.00232", "topics": ["\u5176\u4ed6"], "title_zh": "\u8d22\u52a1\u987e\u95ee\u662f\u5426\u5411\u53ef\u6301\u7eed\u6295\u8d44\u8005\u6536\u53d6\u6ea2\u4ef7\uff1f", "abstract_zh": "\u5c3d\u7ba1\u5173\u4e8e\u8d22\u52a1\u987e\u95ee\u53ef\u80fd\u5bf9\u53ef\u6301\u7eed\u6295\u8d44\u8005\u8fc7\u5ea6\u6536\u8d39\u5b58\u5728\u65e5\u76ca\u589e\u957f\u7684\u76d1\u7ba1\u62c5\u5fe7\uff0c\u4f46\u5b9e\u8bc1\u8bc1\u636e\u4ecd\u7136\u7f3a\u4e4f\u3002\u5728\u4e24\u9879\u9488\u5bf9\u6765\u81ea\u6b27\u6d32\u548c\u7f8e\u56fd\u7684415\u540d\u4e13\u4e1a\u8d22\u52a1\u987e\u95ee\u7684\u5b9e\u5730\u5b9e\u9a8c\u5ba4\u5b9e\u9a8c\u4ee5\u53ca\u4e00\u9879\u6fc0\u52b1\u6027\u8c03\u67e5\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\u4e86\u4e24\u4e2a\u76f8\u4e92\u4f5c\u7528\u4f46\u622a\u7136\u4e0d\u540c\u7684\u6548\u5e94\u3002\u9996\u5148\uff0c\u987e\u95ee\u786e\u5b9e\u5411\u53ef\u6301\u7eed\u6295\u8d44\u8005\u6536\u53d6\u6ea2\u4ef7\u3002\u8fd9\u4e00\u6ea2\u4ef7\u5728\u8003\u8651\u4e86\u987e\u95ee\u6280\u80fd\u3001\u52aa\u529b\u7a0b\u5ea6\u548c\u6210\u672c\u5dee\u5f02\u540e\u4f9d\u7136\u5b58\u5728\u3002\u5176\u6b21\uff0c\u987e\u95ee\u5bf9\u91d1\u878d\u7d20\u517b\u8f83\u4f4e\u7684\u5ba2\u6237\u6536\u53d6\u66f4\u9ad8\u7684\u8d39\u7528\u3002\u8fd9\u4e24\u4e2a\u56e0\u7d20\u76f8\u4e92\u4f5c\u7528\uff1a\u91d1\u878d\u7d20\u517b\u8f83\u4f4e\u7684\u53ef\u6301\u7eed\u6295\u8d44\u8005\u88ab\u6536\u53d6\u6700\u9ad8\u8d39\u7528\uff0c\u800c\u91d1\u878d\u7d20\u517b\u8f83\u9ad8\u7684\u53ef\u6301\u7eed\u6295\u8d44\u8005\u5219\u4e0d\u652f\u4ed8\u53ef\u6301\u7eed\u6295\u8d44\u6ea2\u4ef7\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u987e\u95ee\u4f1a\u4e3a\u53ef\u6301\u7eed\u6295\u8d44\u59d4\u6258\u6536\u53d6\u989d\u5916\u8d39\u7528\uff0c\u4f46\u4f1a\u907f\u514d\u5bf9\u91d1\u878d\u7d20\u517b\u8f83\u9ad8\u7684\u53ef\u6301\u7eed\u6295\u8d44\u8005\u8fc7\u5ea6\u6536\u8d39\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2022.02412", "journal": "MS", "title": "Dynamic Unraveling", "authors": ["Joel P. Flynn"], "author_details": [{"name": "Joel P. Flynn", "affiliations": ["Department of Economics, Yale University, New Haven, Connecticut 06511"]}], "abstract": "This paper studies price and liquidity dynamics in the presence of costly short-selling when uninformed traders have limited willingness-to-pay to trade securities. In this setting, unraveling and Bayesian social learning interact to produce a novel mechanism, dynamic unraveling: Unraveling that generates signals that lead to future unraveling. Applying the theory, I show how dynamic unraveling explains low-volume crashes: falls in the prices of securities on low or declining trading volume. In this context, short-selling restrictions can make low-volume crashes more likely by intensifying dynamic unraveling, but liquidity injections have the opposite effect.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2022.02412", "topics": ["\u5176\u4ed6"], "title_zh": "\u52a8\u6001\u89e3\u6784", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5728\u5b58\u5728\u6210\u672c\u6027\u5356\u7a7a\u4e14\u65e0\u4fe1\u606f\u4ea4\u6613\u8005\u5bf9\u4ea4\u6613\u8bc1\u5238\u7684\u652f\u4ed8\u610f\u613f\u6709\u9650\u7684\u60c5\u51b5\u4e0b\uff0c\u4ef7\u683c\u548c\u6d41\u52a8\u6027\u52a8\u6001\u3002\u5728\u6b64\u8bbe\u5b9a\u4e2d\uff0c\u89e3\u6784\u4e0e\u8d1d\u53f6\u65af\u793e\u4f1a\u5b66\u4e60\u76f8\u4e92\u4f5c\u7528\uff0c\u4ea7\u751f\u4e00\u79cd\u65b0\u7684\u673a\u5236\u2014\u2014\u52a8\u6001\u89e3\u6784\uff1a\u89e3\u6784\u6240\u4ea7\u751f\u7684\u4fe1\u53f7\u4f1a\u5f15\u53d1\u672a\u6765\u7684\u89e3\u6784\u3002\u5e94\u7528\u8be5\u7406\u8bba\uff0c\u6211\u5c55\u793a\u4e86\u52a8\u6001\u89e3\u6784\u5982\u4f55\u89e3\u91ca\u4f4e\u6210\u4ea4\u91cf\u5d29\u76d8\uff1a\u8bc1\u5238\u5728\u4ea4\u6613\u91cf\u4f4e\u6216\u6301\u7eed\u4e0b\u964d\u65f6\u4ef7\u683c\u7684\u4e0b\u8dcc\u3002\u5728\u8fd9\u4e00\u80cc\u666f\u4e0b\uff0c\u5356\u7a7a\u9650\u5236\u4f1a\u901a\u8fc7\u52a0\u5267\u52a8\u6001\u89e3\u6784\u800c\u4f7f\u4f4e\u6210\u4ea4\u91cf\u5d29\u76d8\u66f4\u53ef\u80fd\u53d1\u751f\uff0c\u4f46\u6d41\u52a8\u6027\u6ce8\u5165\u5219\u4f1a\u4ea7\u751f\u76f8\u53cd\u6548\u679c\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2024.05203", "journal": "MS", "title": "Searching for Rewards", "authors": ["T. Tony Ke", "Jiwoong Shin", "Xu Zhu"], "author_details": [{"name": "T. Tony Ke", "affiliations": ["Chinese University of Hong Kong, Hong Kong"]}, {"name": "Jiwoong Shin", "affiliations": ["Yale University, New Haven, Connecticut 06520"]}, {"name": "Xu Zhu", "affiliations": ["School of Economics and Management, Beihang University, Beijing 100191, China"]}], "abstract": "Loyalty programs are widespread across various markets, offering members rewards based on their past purchases for future benefits. This study offers new insights into the strategic use of loyalty programs and their impact on market competition by exploring the dynamics of loyalty programs within a repeated ordered search framework, in which consumers sequentially search for the optimal product across multiple firms over two periods. Our findings highlight distinct roles for price discounts and rewards in influencing consumer decisions. Price discounts discourage further search in the current shopping period, whereas rewards encourage consumer loyalty by inducing prominence in subsequent visits. As search costs increase, firms tend to offer lower price discounts but higher rewards, and this results in a higher industry profit but lower consumer surplus. Compared with their absence, loyalty programs decrease both industry profit and consumer welfare, leading to a lose\u2013lose outcome. Moreover, we demonstrate that, when the firms are heterogeneous in terms of their network sizes, those with larger networks tend to offer lower rewards yet achieve greater consumer loyalty in contrast to the firms with smaller networks, which compensate with higher rewards.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.05203", "title_zh": "\u5bfb\u627e\u5956\u52b1", "abstract_zh": "\u5fe0\u8bda\u5ea6\u8ba1\u5212\u5728\u5404\u79cd\u5e02\u573a\u4e2d\u5e7f\u6cdb\u5b58\u5728\uff0c\u901a\u8fc7\u6839\u636e\u6d88\u8d39\u8005\u7684\u8fc7\u5f80\u8d2d\u4e70\u8bb0\u5f55\u63d0\u4f9b\u672a\u6765\u6536\u76ca\u6765\u5438\u5f15\u4f1a\u5458\u3002\u672c\u7814\u7a76\u5728\u91cd\u590d\u7684\u6709\u5e8f\u641c\u7d22\u6846\u67b6\u4e0b\uff0c\u63a2\u8ba8\u4e86\u5fe0\u8bda\u5ea6\u8ba1\u5212\u5728\u591a\u671f\u4e2d\u6d88\u8d39\u8005\u4f9d\u6b21\u5728\u591a\u5bb6\u4f01\u4e1a\u95f4\u5bfb\u627e\u6700\u4f18\u4ea7\u54c1\u8fc7\u7a0b\u4e2d\u7684\u52a8\u6001\u673a\u5236\uff0c\u4ece\u800c\u4e3a\u5fe0\u8bda\u5ea6\u8ba1\u5212\u7684\u6218\u7565\u8fd0\u7528\u53ca\u5176\u5bf9\u5e02\u573a\u7ade\u4e89\u7684\u5f71\u54cd\u63d0\u4f9b\u4e86\u65b0\u7684\u6d1e\u89c1\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u4ef7\u683c\u6298\u6263\u4f1a\u6291\u5236\u6d88\u8d39\u8005\u5728\u5f53\u524d\u8d2d\u7269\u5468\u671f\u5185\u7684\u8fdb\u4e00\u6b65\u641c\u7d22\uff0c\u800c\u5956\u52b1\u5219\u901a\u8fc7\u5728\u540e\u7eed\u8bbf\u95ee\u4e2d\u589e\u5f3a\u6d88\u8d39\u8005\u5fe0\u8bda\u5ea6\u6765\u6fc0\u52b1\u5176\u6301\u7eed\u6d88\u8d39\u3002\u968f\u7740\u641c\u7d22\u6210\u672c\u7684\u4e0a\u5347\uff0c\u4f01\u4e1a\u503e\u5411\u4e8e\u63d0\u4f9b\u66f4\u4f4e\u7684\u4ef7\u683c\u6298\u6263\u4f46\u66f4\u9ad8\u7684\u5956\u52b1\uff0c\u8fd9\u5bfc\u81f4\u884c\u4e1a\u5229\u6da6\u4e0a\u5347\u800c\u6d88\u8d39\u8005\u5269\u4f59\u4e0b\u964d\u3002\u4e0e\u4e0d\u5b58\u5728\u5fe0\u8bda\u5ea6\u8ba1\u5212\u7684\u60c5\u51b5\u76f8\u6bd4\uff0c\u5fe0\u8bda\u5ea6\u8ba1\u5212\u53cd\u800c\u964d\u4f4e\u4e86\u884c\u4e1a\u5229\u6da6\u548c\u6d88\u8d39\u8005\u798f\u5229\uff0c\u5f62\u6210\u4e00\u79cd\u4e24\u8d25\u4ff1\u4f24\u7684\u5c40\u9762\u3002\u6b64\u5916\uff0c\u6211\u4eec\u8bc1\u660e\uff0c\u5f53\u4f01\u4e1a\u5728\u7f51\u7edc\u89c4\u6a21\u4e0a\u5b58\u5728\u5dee\u5f02\u65f6\uff0c\u7f51\u7edc\u89c4\u6a21\u8f83\u5927\u7684\u4f01\u4e1a\u503e\u5411\u4e8e\u63d0\u4f9b\u8f83\u4f4e\u7684\u5956\u52b1\uff0c\u5374\u80fd\u83b7\u5f97\u66f4\u9ad8\u7684\u6d88\u8d39\u8005\u5fe0\u8bda\u5ea6\uff1b\u800c\u7f51\u7edc\u89c4\u6a21\u8f83\u5c0f\u7684\u4f01\u4e1a\u5219\u901a\u8fc7\u63d0\u4f9b\u66f4\u9ad8\u7684\u5956\u52b1\u6765\u5f25\u8865\u8fd9\u4e00\u5dee\u8ddd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1287/mnsc.2023.02957", "journal": "MS", "title": "Matchmaking Strategies for Maximizing Player Engagement in Video Games", "authors": ["Mingliu Chen", "Adam N. Elmachtoub", "Xiao Lei"], "author_details": [{"name": "Mingliu Chen", "affiliations": ["Naveen Jindal School of Management, University of Texas at Dallas, Dallas, Texas 75074"]}, {"name": "Adam N. Elmachtoub", "affiliations": ["Department of Industrial Engineering and Operations Research & Data Science Institute, Columbia University, New York, New York 10027"]}, {"name": "Xiao Lei", "affiliations": ["Faculty of Business and Economics, The University of Hong Kong, Hong Kong SAR"]}], "abstract": "Managing player engagement is vital to the online gaming industry, given that many games generate revenue through subscription models and microtransactions. We scrutinize engagement management in the prevalent category of competitive video games, where players are frequently matched against one another, and matchmaking systems substantially impact engagement. We propose a dynamic model to analyze player dynamics and optimize matchmaking policies for maximum engagement. Our model takes into account two essential factors in competitive games: heterogeneous skill levels and players\u2019 aversion to losing. Additionally, the model enables us to consider pay-to-win strategies and AI-powered bots, which are contentious methods of influencing player engagement and endogenously affect the optimal matchmaking policy. To provide sharp insights, we analyze a specific case where there are two skill levels, and players churn only after experiencing a losing streak. The optimal matchmaking policy considers both short-term rewards by matching players myopically and long-term rewards by adjusting skill distribution. The pay-to-win system can positively impact player engagement when the majority of players are low-skilled, because adopting pay-to-win also affects skill distribution. This result challenges the conventional wisdom that typically regards pay-to-win as trading player experience for revenue. When incorporating AI-powered bots, we demonstrate that optimizing the matchmaking policy can significantly reduce the number of required bots. We then extend our model and conduct a case study with real data from an online chess platform. The optimal policy can improve engagement by 4%\u20136% or reduce the percentage of bots by 3% in comparison with skill-based matchmaking.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.02957", "title_zh": "\u6700\u5927\u5316\u89c6\u9891\u6e38\u620f\u73a9\u5bb6\u53c2\u4e0e\u5ea6\u7684\u5339\u914d\u7b56\u7565", "abstract_zh": "\u73a9\u5bb6\u53c2\u4e0e\u5ea6\u7684\u7ba1\u7406\u5bf9\u4e8e\u5728\u7ebf\u6e38\u620f\u4ea7\u4e1a\u81f3\u5173\u91cd\u8981\uff0c\u56e0\u4e3a\u8bb8\u591a\u6e38\u620f\u901a\u8fc7\u8ba2\u9605\u5236\u548c\u5fae\u4ea4\u6613\u6a21\u5f0f\u83b7\u5f97\u6536\u5165\u3002\u6211\u4eec\u6df1\u5165\u7814\u7a76\u4e86\u7ade\u4e89\u6027\u89c6\u9891\u6e38\u620f\u7c7b\u522b\u4e2d\u7684\u53c2\u4e0e\u5ea6\u7ba1\u7406\u95ee\u9898\uff0c\u8fd9\u7c7b\u6e38\u620f\u4e2d\u73a9\u5bb6\u901a\u5e38\u4f1a\u88ab\u914d\u5bf9\u5bf9\u6218\uff0c\u800c\u5339\u914d\u7cfb\u7edf\u5bf9\u53c2\u4e0e\u5ea6\u6709\u663e\u8457\u5f71\u54cd\u3002\u6211\u4eec\u63d0\u51fa\u4e00\u4e2a\u52a8\u6001\u6a21\u578b\uff0c\u7528\u4e8e\u5206\u6790\u73a9\u5bb6\u884c\u4e3a\u5e76\u4f18\u5316\u5339\u914d\u7b56\u7565\u4ee5\u5b9e\u73b0\u6700\u5927\u53c2\u4e0e\u5ea6\u3002\u8be5\u6a21\u578b\u8003\u8651\u4e86\u7ade\u4e89\u6027\u6e38\u620f\u4e2d\u7684\u4e24\u4e2a\u5173\u952e\u56e0\u7d20\uff1a\u73a9\u5bb6\u6280\u80fd\u6c34\u5e73\u7684\u5f02\u8d28\u6027\u4ee5\u53ca\u73a9\u5bb6\u5bf9\u8f93\u6389\u6bd4\u8d5b\u7684\u538c\u6076\u60c5\u7eea\u3002\u6b64\u5916\uff0c\u6a21\u578b\u8fd8\u80fd\u591f\u8003\u8651\u4ed8\u8d39\u83b7\u80dc\uff08pay-to-win\uff09\u7b56\u7565\u548c\u4eba\u5de5\u667a\u80fd\u9a71\u52a8\u7684\u673a\u5668\u4eba\uff0c\u8fd9\u4e9b\u662f\u5f71\u54cd\u73a9\u5bb6\u53c2\u4e0e\u5ea6\u4e14\u4f1a\u5185\u751f\u6539\u53d8\u6700\u4f18\u5339\u914d\u7b56\u7565\u7684\u4e89\u8bae\u6027\u624b\u6bb5\u3002\u4e3a\u4e86\u63d0\u4f9b\u6e05\u6670\u7684\u89c1\u89e3\uff0c\u6211\u4eec\u5206\u6790\u4e86\u4e00\u4e2a\u5177\u4f53\u6848\u4f8b\uff1a\u5b58\u5728\u4e24\u79cd\u6280\u80fd\u6c34\u5e73\uff0c\u4e14\u73a9\u5bb6\u4ec5\u5728\u7ecf\u5386\u8fde\u7eed\u8f93\u6389\u6bd4\u8d5b\u540e\u624d\u4f1a\u6d41\u5931\u3002\u6700\u4f18\u5339\u914d\u7b56\u7565\u540c\u65f6\u8003\u8651\u77ed\u671f\u5956\u52b1\uff08\u901a\u8fc7\u77ed\u671f\u5339\u914d\u5b9e\u73b0\uff09\u548c\u957f\u671f\u5956\u52b1\uff08\u901a\u8fc7\u8c03\u6574\u6280\u80fd\u5206\u5e03\u5b9e\u73b0\uff09\u3002\u5f53\u5927\u591a\u6570\u73a9\u5bb6\u6280\u80fd\u8f83\u4f4e\u65f6\uff0c\u4ed8\u8d39\u83b7\u80dc\u7b56\u7565\u53ef\u4ee5\u79ef\u6781\u63d0\u5347\u73a9\u5bb6\u53c2\u4e0e\u5ea6\uff0c\u56e0\u4e3a\u91c7\u7528\u8be5\u7b56\u7565\u4e5f\u4f1a\u6539\u53d8\u6280\u80fd\u5206\u5e03\u3002\u8fd9\u4e00\u7ed3\u679c\u6311\u6218\u4e86\u4f20\u7edf\u89c2\u70b9\uff0c\u5373\u901a\u5e38\u8ba4\u4e3a\u4ed8\u8d39\u83b7\u80dc\u662f\u7528\u73a9\u5bb6\u4f53\u9a8c\u6362\u53d6\u6536\u5165\u3002\u5f53\u5f15\u5165\u4eba\u5de5\u667a\u80fd\u9a71\u52a8\u7684\u673a\u5668\u4eba\u65f6\uff0c\u6211\u4eec\u8bc1\u660e\u901a\u8fc7\u4f18\u5316\u5339\u914d\u7b56\u7565\u53ef\u4ee5\u663e\u8457\u51cf\u5c11\u6240\u9700\u673a\u5668\u4eba\u7684\u6570\u91cf\u3002\u968f\u540e\uff0c\u6211\u4eec\u6269\u5c55\u4e86\u8be5\u6a21\u578b\uff0c\u5e76\u57fa\u4e8e\u4e00\u4e2a\u5728\u7ebf\u56fd\u9645\u8c61\u68cb\u5e73\u53f0\u7684\u5b9e\u6d4b\u6570\u636e\u8fdb\u884c\u6848\u4f8b\u7814\u7a76\u3002\u4e0e\u57fa\u4e8e\u6280\u80fd\u7684\u5339\u914d\u7b56\u7565\u76f8\u6bd4\uff0c\u6700\u4f18\u7b56\u7565\u53ef\u63d0\u5347\u53c2\u4e0e\u5ea64%\u81f36%\uff0c\u6216\u51cf\u5c11\u673a\u5668\u4eba\u5360\u6bd43%\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2023.02973", "journal": "MS", "title": "Evaluating the Efficacy of Providers\u2019 Compensation Contracts in Improving Participant Retention for Clinical Studies", "authors": ["Xueze Song", "Mili Mehrotra", "Tharanga Rajapakshe"], "author_details": [{"name": "Xueze Song", "affiliations": ["Department of Information Systems, Statistics and Management Science, Culverhouse College of Business, The University of Alabama, Tuscaloosa, Alabama 35487"]}, {"name": "Mili Mehrotra", "affiliations": ["Department of Business Administration, Gies College of Business, University of Illinois Urbana-Champaign, Champaign, Illinois 61820"]}, {"name": "Tharanga Rajapakshe", "affiliations": ["Information System and Operations Management Department, Warrington College of Business, University of Florida, Gainesville, Florida 32611"]}], "abstract": "In this work, we aim to analyze a clinical study sponsor\u2019s decisions regarding monetary payments to participants and compensation for providers (investigators and coordinators) for their efforts to improve participant retention in the study. To this end, we first consider a centralized model where the sponsor decides the monetary payments to participants and the providers\u2019 efforts. We then identify the optimal contracts for the providers under the two decentralized team structures: the sponsor-investigator (SI) model and the outsourcing (OM) model. We further analyze three widely adopted compensation contracts for the providers: fixed (FC), linear (LC), and conditional linear (CLC) given a decentralized structure. Our theoretical analysis shows that the expected retention cost with optimal contracts under decentralized structures is at most 40% higher than that under the centralized model. However, in practical instances, this cost increase is, at the most, 8% on average. A comparison of the FC, LC, and CLC contracts reveals that it is sufficient for the sponsor to choose between the FC and the LC contracts under the SI model, whereas under the OM model, there exist cases where the sponsor is better off adopting the CLC contract. Furthermore, the sponsor\u2019s expected retention cost when choosing the best of the three contracts is at most 6% (10%) higher on average relative to that for the optimal compensation contract under the SI (OM) model. Given a decentralized structure, we also identify cases where the optimal contract offers significant benefit over the three contracts observed in practice.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.02973", "topics": ["\u5176\u4ed6"], "title_zh": "\u8bc4\u4f30\u4e34\u5e8a\u7814\u7a76\u4e2d\u63d0\u4f9b\u8005\u8865\u507f\u5408\u540c\u5728\u63d0\u9ad8\u53c2\u4e0e\u8005\u7559\u5b58\u7387\u65b9\u9762\u7684\u6709\u6548\u6027", "abstract_zh": "\u5728\u672c\u7814\u7a76\u4e2d\uff0c\u6211\u4eec\u65e8\u5728\u5206\u6790\u4e34\u5e8a\u7814\u7a76\u8d5e\u52a9\u5546\u5728\u5411\u53c2\u4e0e\u8005\u652f\u4ed8\u8d27\u5e01\u62a5\u916c\u4ee5\u53ca\u5411\u63d0\u4f9b\u8005\uff08\u7814\u7a76\u8005\u548c\u534f\u8c03\u5458\uff09\u652f\u4ed8\u62a5\u916c\u4ee5\u63d0\u9ad8\u7814\u7a76\u53c2\u4e0e\u8005\u7559\u5b58\u7387\u65b9\u9762\u7684\u51b3\u7b56\u3002\u4e3a\u6b64\uff0c\u6211\u4eec\u9996\u5148\u8003\u8651\u4e00\u4e2a\u96c6\u4e2d\u5f0f\u6a21\u578b\uff0c\u5176\u4e2d\u8d5e\u52a9\u5546\u51b3\u5b9a\u5bf9\u53c2\u4e0e\u8005\u7684\u8d27\u5e01\u652f\u4ed8\u4ee5\u53ca\u5bf9\u63d0\u4f9b\u8005\u52aa\u529b\u7684\u5b89\u6392\u3002\u7136\u540e\uff0c\u6211\u4eec\u9488\u5bf9\u4e24\u79cd\u53bb\u4e2d\u5fc3\u5316\u7684\u56e2\u961f\u7ed3\u6784\u2014\u2014\u8d5e\u52a9\u5546-\u7814\u7a76\u8005\uff08SI\uff09\u6a21\u5f0f\u548c\u5916\u5305\uff08OM\uff09\u6a21\u5f0f\u2014\u2014\u8bc6\u522b\u63d0\u4f9b\u8005\u7684\u6700\u4f18\u5408\u540c\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u5206\u6790\u4e86\u5728\u53bb\u4e2d\u5fc3\u5316\u7ed3\u6784\u4e0b\u4e09\u79cd\u5e7f\u6cdb\u91c7\u7528\u7684\u63d0\u4f9b\u8005\u8865\u507f\u5408\u540c\uff1a\u56fa\u5b9a\u5408\u540c\uff08FC\uff09\u3001\u7ebf\u6027\u5408\u540c\uff08LC\uff09\u548c\u6761\u4ef6\u7ebf\u6027\u5408\u540c\uff08CLC\uff09\u3002\u6211\u4eec\u7684\u7406\u8bba\u5206\u6790\u8868\u660e\uff0c\u5728\u53bb\u4e2d\u5fc3\u5316\u7ed3\u6784\u4e0b\uff0c\u91c7\u7528\u6700\u4f18\u5408\u540c\u7684\u9884\u671f\u7559\u5b58\u6210\u672c\u6700\u591a\u6bd4\u96c6\u4e2d\u5f0f\u6a21\u578b\u9ad840%\u3002\u7136\u800c\uff0c\u5728\u5b9e\u9645\u6848\u4f8b\u4e2d\uff0c\u8fd9\u4e00\u6210\u672c\u589e\u52a0\u6700\u591a\u4ec5\u4e3a\u5e73\u57478%\u3002\u5bf9FC\u3001LC\u548cCLC\u5408\u540c\u7684\u6bd4\u8f83\u8868\u660e\uff0c\u5728SI\u6a21\u5f0f\u4e0b\uff0c\u8d5e\u52a9\u5546\u53ea\u9700\u5728FC\u548cLC\u5408\u540c\u4e4b\u95f4\u8fdb\u884c\u9009\u62e9\u5373\u53ef\uff1b\u800c\u5728OM\u6a21\u5f0f\u4e0b\uff0c\u5b58\u5728\u67d0\u4e9b\u60c5\u51b5\u4e0b\u8d5e\u52a9\u5546\u91c7\u7528CLC\u5408\u540c\u4f1a\u66f4\u4f18\u3002\u6b64\u5916\uff0c\u5f53\u8d5e\u52a9\u5546\u9009\u62e9\u4e09\u79cd\u5408\u540c\u4e2d\u7684\u6700\u4f73\u65b9\u6848\u65f6\uff0c\u5176\u9884\u671f\u7559\u5b58\u6210\u672c\u6700\u591a\u6bd4SI\uff08OM\uff09\u6a21\u5f0f\u4e0b\u6700\u4f18\u8865\u507f\u5408\u540c\u7684\u5e73\u5747\u6210\u672c\u9ad8\u51fa6%\uff0810%\uff09\u3002\u5728\u53bb\u4e2d\u5fc3\u5316\u7ed3\u6784\u4e0b\uff0c\u6211\u4eec\u8fd8\u8bc6\u522b\u51fa\u67d0\u4e9b\u60c5\u51b5\u4e0b\uff0c\u6700\u4f18\u5408\u540c\u76f8\u8f83\u4e8e\u5b9e\u8df5\u4e2d\u89c2\u5bdf\u5230\u7684\u4e09\u79cd\u5408\u540c\u63d0\u4f9b\u4e86\u663e\u8457\u4f18\u52bf\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2024.05808", "journal": "MS", "title": "Expectations Matter: When (Not) to Use Machine Learning Earnings Forecasts", "authors": ["John L. Campbell", "Harrison Ham", "Zhongjin (Gene) Lu", "Katherine Wood"], "author_details": [{"name": "John L. Campbell", "affiliations": ["Department of Accounting and Finance, Terry College of Business, University of Georgia, Athens, Georgia 30602"]}, {"name": "Harrison Ham", "affiliations": ["Department of Finance, Clemson University, Clemson, South Carolina 29634"]}, {"name": "Zhongjin (Gene) Lu", "affiliations": ["Department of Finance, Terry College of Business, University of Georgia, Athens, Georgia 30602"]}, {"name": "Katherine Wood", "affiliations": ["Department of Finance, Oklahoma State University, Stillwater, Oklahoma 74078"]}], "abstract": "We comprehensively examine the usefulness of machine learning technology to predict a firm\u2019s earnings and offer three main findings. First, although prior literature suggests machine learning can offer better earnings forecasts than analysts, we show that this result is highly sensitive to machine learning model specification choices (i.e., 80% of evaluated machine forecasts fail to beat analysts). Second, we examine why the most accurate machine learning forecast consistently beats analysts, finding that they correct for predictable analyst biases that are both linear and nonlinear and largely relate to analysts\u2019 prior forecast errors, forecasted earnings levels, and the firm\u2019s stock price. Finally, we find that investors\u2019 earnings expectations, as revealed through stock prices, largely\u2014but do not fully\u2014correct for these predictable analyst biases, with delayed price realization up to nine months. In additional analysis, we find that optimal machine learning specification choices remain stable over time and that, although the machine\u2019s outperformance narrows in recent periods, it remains substantial among small-cap stocks. Overall, our study moves beyond the question of whether machine forecasts are superior to human forecasts and instead focuses on which machine forecast specifications matter, as well as when and why machine forecasts are most superior. In so doing, we provide code and estimates for the most accurate machine forecast specification and demonstrate that investors\u2019 expectations appear to largely (but not fully) align with them.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.05808", "title_zh": "\u9884\u671f\u5f88\u91cd\u8981\uff1a\u5728\u4f55\u65f6\uff08\u4e0d\uff09\u4f7f\u7528\u673a\u5668\u5b66\u4e60\u9884\u6d4b\u76c8\u5229", "abstract_zh": "\u6211\u4eec\u5168\u9762\u8003\u5bdf\u4e86\u673a\u5668\u5b66\u4e60\u6280\u672f\u5728\u9884\u6d4b\u4f01\u4e1a\u76c8\u5229\u65b9\u9762\u7684\u6709\u6548\u6027\uff0c\u5e76\u5f97\u51fa\u4e09\u4e2a\u4e3b\u8981\u53d1\u73b0\u3002\u9996\u5148\uff0c\u5c3d\u7ba1\u5148\u524d\u6587\u732e\u8868\u660e\u673a\u5668\u5b66\u4e60\u53ef\u80fd\u6bd4\u5206\u6790\u5e08\u63d0\u4f9b\u66f4\u51c6\u786e\u7684\u76c8\u5229\u9884\u6d4b\uff0c\u4f46\u6211\u4eec\u53d1\u73b0\u8fd9\u4e00\u7ed3\u679c\u5bf9\u673a\u5668\u5b66\u4e60\u6a21\u578b\u7684\u8bbe\u5b9a\u9009\u62e9\u6781\u4e3a\u654f\u611f\uff08\u5373\u8bc4\u4f30\u768480%\u673a\u5668\u5b66\u4e60\u9884\u6d4b\u672a\u80fd\u8d85\u8d8a\u5206\u6790\u5e08\uff09\u3002\u5176\u6b21\uff0c\u6211\u4eec\u63a2\u7a76\u4e86\u4e3a\u4f55\u6700\u51c6\u786e\u7684\u673a\u5668\u5b66\u4e60\u9884\u6d4b\u59cb\u7ec8\u4f18\u4e8e\u5206\u6790\u5e08\uff0c\u53d1\u73b0\u5176\u80fd\u591f\u7ea0\u6b63\u5206\u6790\u5e08\u7684\u53ef\u9884\u6d4b\u6027\u504f\u89c1\uff0c\u8fd9\u4e9b\u504f\u89c1\u65e2\u5305\u62ec\u7ebf\u6027\u4e5f\u5305\u62ec\u975e\u7ebf\u6027\u6210\u5206\uff0c\u4e3b\u8981\u4e0e\u5206\u6790\u5e08\u4e4b\u524d\u7684\u9884\u6d4b\u8bef\u5dee\u3001\u9884\u6d4b\u7684\u76c8\u5229\u6c34\u5e73\u4ee5\u53ca\u4f01\u4e1a\u7684\u80a1\u4ef7\u76f8\u5173\u3002\u6700\u540e\uff0c\u6211\u4eec\u53d1\u73b0\u6295\u8d44\u8005\u7684\u76c8\u5229\u9884\u671f\uff0c\u901a\u8fc7\u80a1\u4ef7\u4f53\u73b0\u51fa\u6765\uff0c\u5f88\u5927\u7a0b\u5ea6\u4e0a\u4f46\u5e76\u975e\u5b8c\u5168\u5730\u7ea0\u6b63\u4e86\u8fd9\u4e9b\u53ef\u9884\u6d4b\u7684\u5206\u6790\u5e08\u504f\u89c1\uff0c\u4ef7\u683c\u5b9e\u73b0\u5b58\u5728\u957f\u8fbe\u4e5d\u4e2a\u6708\u7684\u5ef6\u8fdf\u3002\u5728\u989d\u5916\u5206\u6790\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\u6700\u4f18\u673a\u5668\u5b66\u4e60\u6a21\u578b\u8bbe\u5b9a\u9009\u62e9\u5728\u65f6\u95f4\u4e0a\u4fdd\u6301\u7a33\u5b9a\uff0c\u5c3d\u7ba1\u8fd1\u5e74\u6765\u673a\u5668\u5b66\u4e60\u7684\u8d85\u8d8a\u4f18\u52bf\u6709\u6240\u7f29\u5c0f\uff0c\u4f46\u5728\u5c0f\u76d8\u80a1\u4e2d\u4ecd\u4fdd\u6301\u663e\u8457\u3002\u603b\u4f53\u800c\u8a00\uff0c\u672c\u7814\u7a76\u8d85\u8d8a\u4e86\u673a\u5668\u9884\u6d4b\u662f\u5426\u4f18\u4e8e\u4eba\u5de5\u9884\u6d4b\u8fd9\u4e00\u95ee\u9898\uff0c\u8f6c\u800c\u5173\u6ce8\u54ea\u4e9b\u673a\u5668\u5b66\u4e60\u9884\u6d4b\u8bbe\u5b9a\u5177\u6709\u91cd\u8981\u6027\uff0c\u4ee5\u53ca\u5728\u4f55\u79cd\u60c5\u51b5\u4e0b\u548c\u4e3a\u4f55\u673a\u5668\u9884\u6d4b\u6700\u4e3a\u4f18\u8d8a\u3002\u901a\u8fc7\u8fd9\u4e00\u5206\u6790\uff0c\u6211\u4eec\u63d0\u4f9b\u4e86\u6700\u51c6\u786e\u673a\u5668\u5b66\u4e60\u9884\u6d4b\u8bbe\u5b9a\u7684\u4ee3\u7801\u548c\u4f30\u8ba1\u7ed3\u679c\uff0c\u5e76\u8868\u660e\u6295\u8d44\u8005\u7684\u9884\u671f\u5728\u5f88\u5927\u7a0b\u5ea6\u4e0a\u4f46\u5e76\u975e\u5b8c\u5168\u4e0e\u673a\u5668\u9884\u6d4b\u7ed3\u679c\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2024.07017", "journal": "MS", "title": "How Do Different Remote Work Arrangements Impact Employee Job Satisfaction and Retention?", "authors": ["Christos A. Makridis", "Jason Schloetzer"], "author_details": [{"name": "Christos A. Makridis", "affiliations": ["Arizona State University, Tempe, Arizona 85281; and Gallup Inc., Washington, District of Columbia 20001; and University of Nicosia, Nicosia 2417, Cyprus"]}, {"name": "Jason Schloetzer", "affiliations": ["Georgetown University, McDonough School of Business, Washington, District of Columbia 20057"]}], "abstract": "We study how working remotely impacts employee job satisfaction and retention using unique data on the remote work arrangements of nearly 165,000 employees. Our findings show that the positive association between working remotely more frequently and job satisfaction diminishes substantially after controlling for employee compensation, occupation, demographics, and workplace characteristics (e.g., feeling appreciated at work). Moreover, remote work is associated with a higher intention to leave the firm after considering these other factors. This suggests that workplace characteristics beyond remote work have a more consequential association with job satisfaction and retention than remote work itself. Using variation in job tasks and worker\u2013manager relationships, we find that working remotely more frequently confers higher job satisfaction for employees in low-coordination roles or those who perceive their direct supervisors unfavorably. The findings suggest that remote work plays a more limited role in shaping job satisfaction and retention relative to broader workplace characteristics, and that its value depends on how well work arrangements are matched to employees\u2019 strengths, coordination requirements, and managerial context.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07017", "topics": ["\u5176\u4ed6"], "title_zh": "\u4e0d\u540c\u7684\u8fdc\u7a0b\u5de5\u4f5c\u5b89\u6392\u5982\u4f55\u5f71\u54cd\u5458\u5de5\u7684\u5de5\u4f5c\u6ee1\u610f\u5ea6\u548c\u7559\u4efb\u7387\uff1f", "abstract_zh": "\u6211\u4eec\u5229\u7528\u8fd116.5\u4e07\u540d\u5458\u5de5\u7684\u8fdc\u7a0b\u5de5\u4f5c\u5b89\u6392\u72ec\u7279\u6570\u636e\uff0c\u7814\u7a76\u8fdc\u7a0b\u5de5\u4f5c\u5bf9\u5458\u5de5\u5de5\u4f5c\u6ee1\u610f\u5ea6\u548c\u7559\u4efb\u7387\u7684\u5f71\u54cd\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u8fdc\u7a0b\u5de5\u4f5c\u9891\u7387\u4e0e\u5de5\u4f5c\u6ee1\u610f\u5ea6\u4e4b\u95f4\u7684\u6b63\u5411\u5173\u8054\uff0c\u5728\u63a7\u5236\u4e86\u5458\u5de5\u85aa\u916c\u3001\u804c\u4e1a\u3001\u4eba\u53e3\u7edf\u8ba1\u7279\u5f81\u4ee5\u53ca\u5de5\u4f5c\u573a\u6240\u7279\u5f81\uff08\u4f8b\u5982\u611f\u53d7\u5230\u88ab\u91cd\u89c6\uff09\u540e\u663e\u8457\u51cf\u5f31\u3002\u6b64\u5916\uff0c\u8003\u8651\u8fd9\u4e9b\u56e0\u7d20\u540e\uff0c\u8fdc\u7a0b\u5de5\u4f5c\u4e0e\u5458\u5de5\u79bb\u804c\u610f\u613f\u4e0a\u5347\u76f8\u5173\u3002\u8fd9\u8868\u660e\uff0c\u9664\u8fdc\u7a0b\u5de5\u4f5c\u4e4b\u5916\u7684\u5de5\u4f5c\u573a\u6240\u7279\u5f81\u5bf9\u5de5\u4f5c\u6ee1\u610f\u5ea6\u548c\u7559\u4efb\u7387\u7684\u5f71\u54cd\u66f4\u4e3a\u91cd\u8981\u3002\u901a\u8fc7\u5206\u6790\u5de5\u4f5c\u4efb\u52a1\u548c\u5458\u5de5\u4e0e\u7ba1\u7406\u8005\u5173\u7cfb\u7684\u5dee\u5f02\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5bf9\u4e8e\u534f\u8c03\u9700\u6c42\u8f83\u4f4e\u7684\u5c97\u4f4d\u6216\u5bf9\u76f4\u63a5\u4e3b\u7ba1\u8bc4\u4ef7\u4e0d\u4f73\u7684\u5458\u5de5\u800c\u8a00\uff0c\u66f4\u9891\u7e41\u5730\u8fdc\u7a0b\u5de5\u4f5c\u4f1a\u5e26\u6765\u66f4\u9ad8\u7684\u5de5\u4f5c\u6ee1\u610f\u5ea6\u3002\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u8fdc\u7a0b\u5de5\u4f5c\u5728\u5851\u9020\u5de5\u4f5c\u6ee1\u610f\u5ea6\u548c\u7559\u4efb\u7387\u65b9\u9762\u4f5c\u7528\u6709\u9650\uff0c\u5176\u4ef7\u503c\u53d6\u51b3\u4e8e\u5de5\u4f5c\u5b89\u6392\u662f\u5426\u4e0e\u5458\u5de5\u7684\u4e2a\u4eba\u4f18\u52bf\u3001\u534f\u8c03\u9700\u6c42\u4ee5\u53ca\u7ba1\u7406\u73af\u5883\u76f8\u5339\u914d\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2024.04637", "journal": "MS", "title": "Forecasting Earnings from Home", "authors": ["Michael Durney", "Hoyoun Kyung", "Stanimir Markov", "Jihwon Park"], "author_details": [{"name": "Michael Durney", "affiliations": ["Tippie College of Business, University of Iowa, Iowa City, Iowa 52242"]}, {"name": "Hoyoun Kyung", "affiliations": ["Trulaske College of Business, University of Missouri, Columbia, Missouri 65211"]}, {"name": "Stanimir Markov", "affiliations": ["Naveen Jindal School of Management, University of Texas at Dallas, Richardson, Texas 75080"]}, {"name": "Jihwon Park", "affiliations": ["Zicklin School of Business, Baruch College, City University of New York, New York, New York 10010"]}], "abstract": "We examine the impact of working from home (WFH) practices on the financial services industry, focusing on sell-side equity analysts. We find that analysts who previously benefited from access to in-person interactions with other informed parties experience a greater decline in earnings forecast accuracy following the COVID lockdown and the shift to WFH. Notably, the informational advantage associated with the in-person access disappears during the lockdown and returns once restrictions are lifted. Our results are stronger for all-star analysts and analysts with shorter coverage periods, suggesting that all-star analysts rely relatively more on access to in-person interactions prelockdown and that accumulated firm-specific knowledge mitigates the loss of in-person interactions. Our results remain robust across alternative analyst performance measures. We conclude that, despite recent advances in communications technology, AI, and machine learning, in-person interactions remain a unique and difficult to substitute information channel for sell-side research providers and that WFH impedes information flows between market participants in capital markets.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.04637", "title_zh": "\u4ece\u5bb6\u4e2d\u5de5\u4f5c\u5bf9\u91d1\u878d\u670d\u52a1\u4e1a\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5728\u5bb6\u529e\u516c\uff08WFH\uff09\u5b9e\u8df5\u5bf9\u91d1\u878d\u670d\u52a1\u4e1a\u7684\u5f71\u54cd\uff0c\u91cd\u70b9\u5173\u6ce8\u5356\u65b9\u80a1\u6743\u5206\u6790\u5e08\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u90a3\u4e9b\u5728\u75ab\u60c5\u5c01\u9501\u671f\u95f4\u53ca\u8f6c\u5411\u5c45\u5bb6\u529e\u516c\u524d\u66fe\u53d7\u76ca\u4e8e\u4e0e\u77e5\u60c5\u65b9\u9762\u5bf9\u9762\u4e92\u52a8\u7684\u5206\u6790\u5e08\uff0c\u5728\u6b64\u4e4b\u540e\u5176\u76c8\u5229\u9884\u6d4b\u51c6\u786e\u6027\u51fa\u73b0\u66f4\u5927\u7a0b\u5ea6\u7684\u4e0b\u964d\u3002\u503c\u5f97\u6ce8\u610f\u7684\u662f\uff0c\u4e0e\u9762\u5bf9\u9762\u63a5\u89e6\u76f8\u5173\u7684\u4fe1\u606f\u4f18\u52bf\u5728\u5c01\u9501\u671f\u95f4\u6d88\u5931\uff0c\u5e76\u5728\u9650\u5236\u89e3\u9664\u540e\u6062\u590d\u3002\u6211\u4eec\u7684\u7ed3\u679c\u5bf9\u4e8e\u660e\u661f\u5206\u6790\u5e08\u548c\u8986\u76d6\u5468\u671f\u8f83\u77ed\u7684\u5206\u6790\u5e08\u66f4\u4e3a\u663e\u8457\uff0c\u8868\u660e\u660e\u661f\u5206\u6790\u5e08\u5728\u5c01\u9501\u524d\u66f4\u4f9d\u8d56\u4e8e\u9762\u5bf9\u9762\u4e92\u52a8\uff0c\u800c\u79ef\u7d2f\u7684\u516c\u53f8\u7279\u5b9a\u77e5\u8bc6\u5219\u51cf\u8f7b\u4e86\u5931\u53bb\u9762\u5bf9\u9762\u4e92\u52a8\u5e26\u6765\u7684\u5f71\u54cd\u3002\u6211\u4eec\u7684\u7ed3\u679c\u5728\u4f7f\u7528\u5176\u4ed6\u5206\u6790\u5e08\u7ee9\u6548\u8861\u91cf\u6807\u51c6\u65f6\u4f9d\u7136\u7a33\u5065\u3002\u6211\u4eec\u5f97\u51fa\u7ed3\u8bba\uff1a\u5c3d\u7ba1\u8fd1\u5e74\u6765\u901a\u4fe1\u6280\u672f\u3001\u4eba\u5de5\u667a\u80fd\u548c\u673a\u5668\u5b66\u4e60\u53d6\u5f97\u4e86\u8fdb\u5c55\uff0c\u4f46\u9762\u5bf9\u9762\u4e92\u52a8\u4ecd\u7136\u662f\u5356\u65b9\u7814\u7a76\u63d0\u4f9b\u5546\u72ec\u6709\u7684\u3001\u96be\u4ee5\u66ff\u4ee3\u7684\u4fe1\u606f\u6e20\u9053\uff0c\u800c\u5c45\u5bb6\u529e\u516c\u963b\u788d\u4e86\u8d44\u672c\u5e02\u573a\u53c2\u4e0e\u8005\u4e4b\u95f4\u7684\u4fe1\u606f\u6d41\u52a8\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2023.00212", "journal": "MS", "title": "Bond Risk Characteristics and Factor Risk Premia", "authors": ["Pierluigi Balduzzi", "Michael F. Connolly", "Alan Marcus"], "author_details": [{"name": "Pierluigi Balduzzi", "affiliations": ["Carroll School of Management, Boston College, Chestnut Hill, Massachusetts 02467"]}, {"name": "Michael F. Connolly", "affiliations": ["Independent researcher"]}, {"name": "Alan Marcus", "affiliations": ["Carroll School of Management, Boston College, Chestnut Hill, Massachusetts 02467"]}], "abstract": "Assuming no arbitrage and that a polynomial in the time to maturity approximates spot-rate increments, we develop a consistent approach to estimate factor risk premia in the bond market. This approach is attractive, as the underlying risk factors are the time-varying coefficients of the polynomial specification, and the factor loadings correspond to familiar bond risk characteristics, such as duration and convexity. Our two-factor model\u2014with a positive (negative) duration-factor (convexity-factor) risk premium\u2014is easy to estimate and provides straightforward economic intuition for the concave term structure of bond risk premia and the downward-sloping term structure of bond Sharpe ratios. Our model decomposes the conditional factor risk premia into a \u201cstatus quo\u201d component\u2014the expected factors\u2019 realizations when expected spot-rate increments are zero\u2014and the factors\u2019 forecasts. The status quo factor risk premia provide measures of the state of fixed income markets that both outperform alternative measures and are easily estimated in real time; moreover, the underlying risk factors and their loadings are familiar to and readily interpreted by investors and traders.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.00212", "title_zh": "\u503a\u5238\u98ce\u9669\u7279\u5f81\u4e0e\u56e0\u5b50\u98ce\u9669\u6ea2\u4ef7", "abstract_zh": "\u5728\u65e0\u5957\u5229\u5047\u8bbe\u4e0b\uff0c\u4e14\u5047\u8bbe\u5230\u671f\u65f6\u95f4\u7684\u591a\u9879\u5f0f\u8fd1\u4f3c\u4e8e\u5373\u671f\u5229\u7387\u589e\u91cf\u7684\u60c5\u51b5\u4e0b\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u79cd\u4e00\u81f4\u7684\u65b9\u6cd5\u6765\u4f30\u8ba1\u503a\u5238\u5e02\u573a\u7684\u56e0\u5b50\u98ce\u9669\u6ea2\u4ef7\u3002\u8be5\u65b9\u6cd5\u5177\u6709\u5438\u5f15\u529b\uff0c\u56e0\u4e3a\u5176\u57fa\u7840\u98ce\u9669\u56e0\u5b50\u662f\u591a\u9879\u5f0f\u89c4\u8303\u4e2d\u7684\u65f6\u53d8\u7cfb\u6570\uff0c\u800c\u56e0\u5b50\u8f7d\u8377\u5bf9\u5e94\u4e8e\u719f\u6089\u7684\u503a\u5238\u98ce\u9669\u7279\u5f81\uff0c\u5982\u4e45\u671f\u548c\u51f8\u6027\u3002\u6211\u4eec\u7684\u4e24\u56e0\u5b50\u6a21\u578b\u2014\u2014\u5305\u542b\u6b63\uff08\u8d1f\uff09\u4e45\u671f\u56e0\u5b50\uff08\u51f8\u6027\u56e0\u5b50\uff09\u98ce\u9669\u6ea2\u4ef7\u2014\u2014\u6613\u4e8e\u4f30\u8ba1\uff0c\u5e76\u4e3a\u503a\u5238\u98ce\u9669\u6ea2\u4ef7\u7684\u51f9\u5f62\u671f\u9650\u7ed3\u6784\u4ee5\u53ca\u503a\u5238\u590f\u666e\u6bd4\u7387\u7684\u4e0b\u884c\u671f\u9650\u7ed3\u6784\u63d0\u4f9b\u4e86\u6e05\u6670\u7684\u7ecf\u6d4e\u76f4\u89c9\u3002\u8be5\u6a21\u578b\u5c06\u6761\u4ef6\u56e0\u5b50\u98ce\u9669\u6ea2\u4ef7\u5206\u89e3\u4e3a\u4e24\u4e2a\u90e8\u5206\uff1a\"\u73b0\u72b6\"\u90e8\u5206\u2014\u2014\u5f53\u9884\u671f\u5373\u671f\u5229\u7387\u589e\u91cf\u4e3a\u96f6\u65f6\uff0c\u98ce\u9669\u56e0\u5b50\u7684\u9884\u671f\u5b9e\u73b0\u503c\u2014\u2014\u4ee5\u53ca\u98ce\u9669\u56e0\u5b50\u7684\u9884\u6d4b\u503c\u3002\u73b0\u72b6\u56e0\u5b50\u98ce\u9669\u6ea2\u4ef7\u63d0\u4f9b\u4e86\u4f18\u4e8e\u5176\u4ed6\u6307\u6807\u7684\u56fa\u5b9a\u6536\u76ca\u5e02\u573a\u72b6\u6001\u5ea6\u91cf\uff0c\u4e14\u53ef\u5b9e\u65f6\u4f30\u7b97\uff1b\u6b64\u5916\uff0c\u5176\u57fa\u7840\u98ce\u9669\u56e0\u5b50\u53ca\u5176\u8f7d\u8377\u5bf9\u6295\u8d44\u8005\u548c\u4ea4\u6613\u5458\u800c\u8a00\u65e2\u719f\u6089\u53c8\u6613\u4e8e\u7406\u89e3\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1287/mnsc.2023.02996", "journal": "MS", "title": "An Integer Programming Approach for Quick-Commerce Assortment Planning", "authors": ["Yajing Chen", "Taotao He", "Ying Rong", "Yunlong Wang"], "author_details": [{"name": "Yajing Chen", "affiliations": ["Antai College of Economics and Management, Shanghai Jiao Tong University, Shanghai 200030, China"]}, {"name": "Taotao He", "affiliations": ["Antai College of Economics and Management, Shanghai Jiao Tong University, Shanghai 200030, China"]}, {"name": "Ying Rong", "affiliations": ["Data-Driven Management Decision Making Lab, Antai College of Economics and Management, Shanghai Jiao Tong University, Shanghai 200030, China"]}, {"name": "Yunlong Wang", "affiliations": ["Data-Driven Management Decision Making Lab, Antai College of Economics and Management, Shanghai Jiao Tong University, Shanghai 200030, China"]}], "abstract": "In this paper, we explore the challenge of assortment planning in the context of quick commerce, a rapidly growing business model that aims to deliver time-sensitive products. In order to achieve quick delivery to satisfy the immediate demands of online customers in close proximity, personalized online assortments need to be included in brick-and-mortar store offerings. With the presence of this physical linkage requirement and distinct multinomial logit choice models for online consumer segments, the firm seeks to maximize overall revenue by selecting an optimal assortment of products for local stores and by tailoring a personalized assortment for each online consumer segment. We employ an integer programming approach to solve this NP-hard problem to global optimality. In particular, we derive convex hull results to represent the consumer choice of each online segment under a general class of operational constraints, and to characterize the relation between assortment decisions and choice probabilities of products. Our convex hull results, coupled with a modified choice probability\u2013ordered separation algorithm, yield formulations that provide a significant computational advantage over existing methods. Finally, we illustrate how our convex hull results can be used to address other assortment optimization problems.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.02996", "topics": ["\u5176\u4ed6"], "title_zh": "\u4e00\u79cd\u7528\u4e8e\u5373\u65f6\u96f6\u552e\u5546\u54c1\u7ec4\u5408\u89c4\u5212\u7684\u6574\u6570\u89c4\u5212\u65b9\u6cd5", "abstract_zh": "\u672c\u6587\u63a2\u8ba8\u4e86\u5728\u5373\u65f6\u96f6\u552e\u4e1a\u52a1\u80cc\u666f\u4e0b\u5546\u54c1\u7ec4\u5408\u89c4\u5212\u7684\u6311\u6218\u3002\u5373\u65f6\u96f6\u552e\u662f\u4e00\u79cd\u5feb\u901f\u589e\u957f\u7684\u5546\u4e1a\u6a21\u5f0f\uff0c\u65e8\u5728\u5b9e\u73b0\u65f6\u95f4\u654f\u611f\u578b\u4ea7\u54c1\u7684\u5feb\u901f\u4ea4\u4ed8\u3002\u4e3a\u4e86\u6ee1\u8db3\u5728\u7ebf\u987e\u5ba2\u5728\u8fd1\u8ddd\u79bb\u5185\u7684\u5373\u65f6\u9700\u6c42\uff0c\u9700\u8981\u5c06\u4e2a\u6027\u5316\u5728\u7ebf\u5546\u54c1\u7ec4\u5408\u7eb3\u5165\u5b9e\u4f53\u5e97\u94fa\u7684\u4f9b\u5e94\u4e2d\u3002\u5728\u5b58\u5728\u8fd9\u79cd\u7269\u7406\u8fde\u63a5\u8981\u6c42\u4ee5\u53ca\u9488\u5bf9\u4e0d\u540c\u5728\u7ebf\u6d88\u8d39\u8005\u7fa4\u4f53\u7684\u7279\u5b9a\u591a\u5143\u903b\u8f91\u9009\u62e9\u6a21\u578b\u7684\u60c5\u51b5\u4e0b\uff0c\u4f01\u4e1a\u901a\u8fc7\u9009\u62e9\u6700\u4f18\u7684\u5546\u54c1\u7ec4\u5408\u7528\u4e8e\u672c\u5730\u95e8\u5e97\uff0c\u5e76\u4e3a\u6bcf\u4e2a\u5728\u7ebf\u6d88\u8d39\u8005\u7fa4\u4f53\u5b9a\u5236\u4e2a\u6027\u5316\u5546\u54c1\u7ec4\u5408\uff0c\u4ee5\u6700\u5927\u5316\u6574\u4f53\u6536\u5165\u3002\u6211\u4eec\u91c7\u7528\u6574\u6570\u89c4\u5212\u65b9\u6cd5\u6765\u6c42\u89e3\u8fd9\u4e00NP\u96be\u95ee\u9898\u7684\u5168\u5c40\u6700\u4f18\u89e3\u3002\u5177\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u63a8\u5bfc\u51fa\u5728\u4e00\u822c\u8fd0\u8425\u7ea6\u675f\u4e0b\uff0c\u6bcf\u4e2a\u5728\u7ebf\u6d88\u8d39\u8005\u7fa4\u4f53\u5546\u54c1\u9009\u62e9\u7684\u51f8\u5305\u7ed3\u679c\uff0c\u4ee5\u8868\u5f81\u5546\u54c1\u7ec4\u5408\u51b3\u7b56\u4e0e\u4ea7\u54c1\u9009\u62e9\u6982\u7387\u4e4b\u95f4\u7684\u5173\u7cfb\u3002\u8fd9\u4e9b\u51f8\u5305\u7ed3\u679c\u7ed3\u5408\u4e00\u79cd\u6539\u8fdb\u7684\u57fa\u4e8e\u9009\u62e9\u6982\u7387\u6392\u5e8f\u7684\u5206\u79bb\u7b97\u6cd5\uff0c\u5f62\u6210\u4e86\u663e\u8457\u4f18\u4e8e\u73b0\u6709\u65b9\u6cd5\u7684\u8ba1\u7b97\u4f18\u52bf\u3002\u6700\u540e\uff0c\u6211\u4eec\u8bf4\u660e\u4e86\u5982\u4f55\u5229\u7528\u8fd9\u4e9b\u51f8\u5305\u7ed3\u679c\u6765\u89e3\u51b3\u5176\u4ed6\u5546\u54c1\u7ec4\u5408\u4f18\u5316\u95ee\u9898\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2019.02983", "journal": "MS", "title": "The Value of Flexibility from Opaque Selling", "authors": ["Adam N. Elmachtoub", "David D. Yao", "Yeqing Zhou"], "author_details": [{"name": "Adam N. Elmachtoub", "affiliations": ["Department of Industrial Engineering and Operations Research and Data Science Institute, Columbia University, New York, New York 10027"]}, {"name": "David D. Yao", "affiliations": ["Department of Industrial Engineering and Operations Research, Columbia University, New York, New York 10027"]}, {"name": "Yeqing Zhou", "affiliations": ["Rotterdam School of Management, Erasmus University, 3062 PA Rotterdam, Netherlands"]}], "abstract": "An opaque product refers to a subset of products that only differ in some secondary attribute (such as color or style). After a customer purchases an opaque product, one of the products in the subset is then allocated to the customer. Selling opaque products has become popular on e-commerce platforms, because it is a source of flexibility that reduces demand variability and hence inventory cost. In this paper, we seek to understand how the design of opaque product configurations and the fraction of customers choosing opaque products impact the value of flexibility arising from opaque selling. The key finding from our study is the following insight: A modest opaque selling strategy where (i) the opaque options contain small subsets and (ii) only a small fraction of customers buy opaque products achieves substantial cost savings (compared with nonopaque traditional selling). Moreover, the cost savings of this modest opaque strategy is on the same order as a fully flexible scenario where all customers buy an opaque product. Our analysis relies on exploring a novel connection of multiproduct inventory management to the balls-into-bins framework along with a simple balancing policy for opaque selling. As a byproduct of our analysis, we show that the simple balancing policy is asymptotically optimal. For extensions outside of our theoretical analysis, we conduct extensive numerical experiments to show that our core insights continue to hold.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2019.02983", "topics": ["\u5176\u4ed6"], "title_zh": "\u4ece\u4e0d\u900f\u660e\u9500\u552e\u4e2d\u83b7\u5f97\u7684\u7075\u6d3b\u6027\u4ef7\u503c", "abstract_zh": "\u4e0d\u900f\u660e\u4ea7\u54c1\u662f\u6307\u4ec5\u5728\u67d0\u4e9b\u6b21\u8981\u5c5e\u6027\uff08\u5982\u989c\u8272\u6216\u6b3e\u5f0f\uff09\u4e0a\u5b58\u5728\u5dee\u5f02\u7684\u4e00\u7c7b\u4ea7\u54c1\u96c6\u5408\u3002\u5f53\u987e\u5ba2\u8d2d\u4e70\u4e0d\u900f\u660e\u4ea7\u54c1\u540e\uff0c\u4f1a\u4ece\u8be5\u96c6\u5408\u4e2d\u5206\u914d\u4e00\u4e2a\u5177\u4f53\u4ea7\u54c1\u7ed9\u987e\u5ba2\u3002\u5728\u7535\u5b50\u5546\u52a1\u5e73\u53f0\u4e0a\uff0c\u4e0d\u900f\u660e\u4ea7\u54c1\u7684\u9500\u552e\u65e5\u76ca\u6d41\u884c\uff0c\u56e0\u4e3a\u5b83\u80fd\u63d0\u4f9b\u7075\u6d3b\u6027\uff0c\u964d\u4f4e\u9700\u6c42\u6ce2\u52a8\uff0c\u4ece\u800c\u51cf\u5c11\u5e93\u5b58\u6210\u672c\u3002\u672c\u6587\u65e8\u5728\u63a2\u8ba8\u4e0d\u900f\u660e\u4ea7\u54c1\u914d\u7f6e\u7684\u8bbe\u8ba1\u4ee5\u53ca\u9009\u62e9\u4e0d\u900f\u660e\u4ea7\u54c1\u7684\u987e\u5ba2\u6bd4\u4f8b\u5982\u4f55\u5f71\u54cd\u4e0d\u900f\u660e\u9500\u552e\u5e26\u6765\u7684\u7075\u6d3b\u6027\u4ef7\u503c\u3002\u6211\u4eec\u7684\u7814\u7a76\u5f97\u51fa\u4e00\u4e2a\u5173\u952e\u53d1\u73b0\uff1a\u4e00\u79cd\u9002\u5ea6\u7684\u4e0d\u900f\u660e\u9500\u552e\u7b56\u7565\u2014\u2014\u5373\uff08i\uff09\u4e0d\u900f\u660e\u9009\u9879\u5305\u542b\u8f83\u5c0f\u7684\u5b50\u96c6\uff0c\u4e14\uff08ii\uff09\u53ea\u6709\u5c11\u6570\u987e\u5ba2\u9009\u62e9\u8d2d\u4e70\u4e0d\u900f\u660e\u4ea7\u54c1\u2014\u2014\u80fd\u591f\u5e26\u6765\u663e\u8457\u7684\u6210\u672c\u8282\u7ea6\uff08\u4e0e\u4f20\u7edf\u7684\u975e\u4e0d\u900f\u660e\u9500\u552e\u76f8\u6bd4\uff09\u3002\u6b64\u5916\uff0c\u8fd9\u79cd\u9002\u5ea6\u7684\u4e0d\u900f\u660e\u7b56\u7565\u7684\u6210\u672c\u8282\u7ea6\u6c34\u5e73\u4e0e\u5b8c\u5168\u7075\u6d3b\u7684\u573a\u666f\uff08\u5373\u6240\u6709\u987e\u5ba2\u5747\u8d2d\u4e70\u4e0d\u900f\u660e\u4ea7\u54c1\uff09\u76f8\u5f53\u3002\u6211\u4eec\u7684\u5206\u6790\u57fa\u4e8e\u5c06\u591a\u4ea7\u54c1\u5e93\u5b58\u7ba1\u7406\u4e0e\u2018\u7403\u5165\u6876\u2019\u6846\u67b6\u5efa\u7acb\u4e00\u79cd\u65b0\u9896\u7684\u8054\u7cfb\uff0c\u5e76\u7ed3\u5408\u4e00\u79cd\u7b80\u5355\u7684\u5e73\u8861\u7b56\u7565\u6765\u5b9e\u73b0\u4e0d\u900f\u660e\u9500\u552e\u3002\u4f5c\u4e3a\u5206\u6790\u7684\u526f\u4ea7\u54c1\uff0c\u6211\u4eec\u8bc1\u660e\u4e86\u8be5\u7b80\u5355\u5e73\u8861\u7b56\u7565\u5728\u6e10\u8fd1\u610f\u4e49\u4e0a\u662f\u6700\u4f18\u7684\u3002\u5bf9\u4e8e\u8d85\u51fa\u6211\u4eec\u7406\u8bba\u5206\u6790\u8303\u56f4\u7684\u6269\u5c55\u60c5\u51b5\uff0c\u6211\u4eec\u8fdb\u884c\u4e86\u5e7f\u6cdb\u7684\u6570\u503c\u5b9e\u9a8c\uff0c\u7ed3\u679c\u8868\u660e\u6211\u4eec\u7684\u6838\u5fc3\u89c1\u89e3\u4f9d\u7136\u6210\u7acb\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2023.03580", "journal": "MS", "title": "Optimal Contests with Negative Prizes: Theory and Experiment", "authors": ["Lingbo Huang", "Jingjing Zhang", "Jun Zhang"], "author_details": [{"name": "Lingbo Huang", "affiliations": ["Center for Economic Research, Shandong University, Jinan, Shandong 250100, China"]}, {"name": "Jingjing Zhang", "affiliations": ["Department of Economics, Royal Melbourne Institute of Technology, Melbourne, Victoria 3000, Australia"]}, {"name": "Jun Zhang", "affiliations": ["Economics Discipline Group, School of Business, University of Technology Sydney, Sydney, New South Wales 2007, Australia; and The China Research Institute of Regulation and Public Policy, Zhejiang University of Finance and Economics, Hangzhou, Zhejiang Province 310018, China"]}], "abstract": "This paper examines the optimal design of contests in the presence of negative prizes and establishes the optimality of a modified all-pay auction with entry fee and reserve. The entry fee always equals the contestants\u2019 liability, and the reserve is weakly higher than in contests without negative prizes. The modification involves awarding all contestants a strictly positive prize if none meet the reserve. This optimal contest better incentivizes high-ability contestants by offering them a higher prize augmented by entry fees, while still ensuring full participation from low-ability contestants. Theoretical analysis demonstrates that when contestants\u2019 liability is sufficiently high, the same contest maximizes both the expected total effort and winner\u2019s effort, with both measures increasing with liability. Numerical simulations show that even with low liability, predictions from the two optimal contests are closely aligned. To test these predictions, we conduct an experiment comparing optimal contests across different liability levels, confirming the \u201ckilling-two-birds-with-one-stone\u201d prediction.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.03580", "topics": ["\u5176\u4ed6"], "title_zh": "\u8d1f\u5956\u60c5\u51b5\u4e0b\u6700\u4f18\u7ade\u8d5b\u7684\u8bbe\u8ba1\uff1a\u7406\u8bba\u4e0e\u5b9e\u9a8c", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5728\u5b58\u5728\u8d1f\u5956\u60c5\u51b5\u4e0b\u7ade\u8d5b\u7684\u6700\u4f18\u8bbe\u8ba1\uff0c\u5e76\u5efa\u7acb\u4e86\u5e26\u6709\u5165\u573a\u8d39\u548c\u4fdd\u7559\u4ef7\u7684\u4fee\u6539\u578b\u5168\u652f\u4ed8\u62cd\u5356\u7684\u6700\u4f18\u6027\u3002\u5165\u573a\u8d39\u59cb\u7ec8\u7b49\u4e8e\u53c2\u8d5b\u8005\u7684\u8d23\u4efb\u91d1\u989d\uff0c\u4fdd\u7559\u4ef7\u5f31\u4e8e\u65e0\u8d1f\u5956\u7ade\u8d5b\u4e2d\u7684\u4fdd\u7559\u4ef7\u3002\u8be5\u4fee\u6539\u65b9\u6848\u662f\uff1a\u5982\u679c\u6ca1\u6709\u4efb\u4f55\u53c2\u8d5b\u8005\u8fbe\u5230\u4fdd\u7559\u4ef7\uff0c\u5219\u5411\u6240\u6709\u53c2\u8d5b\u8005\u6388\u4e88\u4e00\u4e2a\u4e25\u683c\u6b63\u7684\u5956\u54c1\u3002\u8fd9\u79cd\u6700\u4f18\u7ade\u8d5b\u901a\u8fc7\u4e3a\u9ad8\u80fd\u529b\u53c2\u8d5b\u8005\u63d0\u4f9b\u4e00\u4e2a\u7531\u5165\u573a\u8d39\u589e\u5f3a\u7684\u66f4\u9ad8\u5956\u54c1\uff0c\u4ece\u800c\u66f4\u597d\u5730\u6fc0\u52b1\u4ed6\u4eec\uff0c\u540c\u65f6\u4ecd\u786e\u4fdd\u4f4e\u80fd\u529b\u53c2\u8d5b\u8005\u7684\u5b8c\u5168\u53c2\u4e0e\u3002\u7406\u8bba\u5206\u6790\u8868\u660e\uff0c\u5f53\u53c2\u8d5b\u8005\u7684\u8d23\u4efb\u91d1\u989d\u8db3\u591f\u9ad8\u65f6\uff0c\u76f8\u540c\u7684\u7ade\u8d5b\u540c\u65f6\u6700\u5927\u5316\u9884\u671f\u603b\u52aa\u529b\u548c\u83b7\u80dc\u8005\u52aa\u529b\uff0c\u4e14\u8fd9\u4e24\u9879\u6307\u6807\u5747\u968f\u8d23\u4efb\u91d1\u989d\u7684\u589e\u52a0\u800c\u4e0a\u5347\u3002\u6570\u503c\u6a21\u62df\u663e\u793a\uff0c\u5373\u4f7f\u5728\u8d23\u4efb\u91d1\u989d\u8f83\u4f4e\u7684\u60c5\u51b5\u4e0b\uff0c\u4e24\u79cd\u6700\u4f18\u7ade\u8d5b\u7684\u9884\u6d4b\u4e5f\u9ad8\u5ea6\u4e00\u81f4\u3002\u4e3a\u9a8c\u8bc1\u8fd9\u4e9b\u9884\u6d4b\uff0c\u6211\u4eec\u8fdb\u884c\u4e86\u5b9e\u9a8c\uff0c\u6bd4\u8f83\u4e86\u4e0d\u540c\u8d23\u4efb\u6c34\u5e73\u4e0b\u7684\u6700\u4f18\u7ade\u8d5b\uff0c\u8bc1\u5b9e\u4e86\u2018\u4e00\u77f3\u4e8c\u9e1f\u2019\u7684\u9884\u6d4b\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2024.06802", "journal": "MS", "title": "Delegation and Chief Financial Officer Retention: Evidence from Chief Accounting Officers on the Executive Team", "authors": ["Leah Muriel", "Adrienne Rhodes", "Dan Russomanno"], "author_details": [{"name": "Leah Muriel", "affiliations": ["Coggin College of Business, University of North Florida, Jacksonville, Florida 32224"]}, {"name": "Adrienne Rhodes", "affiliations": ["Accounting, Tippie College of Business, University of Iowa, Iowa City, Iowa 52242"]}, {"name": "Dan Russomanno", "affiliations": ["Russomanno Research, Tucson, Arizona 85718"]}], "abstract": "In recent years, chief financial officer (CFO) responsibilities and resignations have increased. Given these trends, we examine whether delegating accounting is associated with CFO retention. We develop a methodology to identify voluntary CFO departures using the firm\u2019s public messaging around the CFO\u2019s exit. Our results suggest that CFOs are less likely to voluntarily depart when accounting is delegated. Further, we find evidence that the negative association between delegating accounting and voluntary CFO departures is stronger when accounting demands are higher. Moreover, we find evidence that delegating accounting increases the CFO\u2019s human capital. When CFOs do leave, they are more likely to become a chief executive officer and less likely to make a lateral move to another CFO position. Taken together, this study finds evidence consistent with the delegation of accounting increasing CFO retention and human capital.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06802", "topics": ["\u5176\u4ed6"], "title_zh": "\u4ee3\u7406\u4f1a\u8ba1\u4e0e\u9996\u5e2d\u8d22\u52a1\u5b98\u7559\u4efb\uff1a\u6765\u81ea\u9ad8\u7ba1\u56e2\u961f\u4e2d\u9996\u5e2d\u4f1a\u8ba1\u5b98\u7684\u8bc1\u636e", "abstract_zh": "\u8fd1\u5e74\u6765\uff0c\u9996\u5e2d\u8d22\u52a1\u5b98\uff08CFO\uff09\u7684\u804c\u8d23\u548c\u79bb\u804c\u73b0\u8c61\u6709\u6240\u589e\u52a0\u3002\u9274\u4e8e\u8fd9\u4e00\u8d8b\u52bf\uff0c\u6211\u4eec\u7814\u7a76\u4e86\u5c06\u4f1a\u8ba1\u5de5\u4f5c\u59d4\u6258\u51fa\u53bb\u662f\u5426\u4e0eCFO\u7684\u7559\u4efb\u76f8\u5173\u3002\u6211\u4eec\u5f00\u53d1\u4e86\u4e00\u79cd\u65b9\u6cd5\uff0c\u901a\u8fc7\u4f01\u4e1a\u5173\u4e8eCFO\u79bb\u804c\u7684\u516c\u5f00\u4fe1\u606f\u6765\u8bc6\u522b\u81ea\u613f\u79bb\u804c\u884c\u4e3a\u3002\u7ed3\u679c\u8868\u660e\uff0c\u5f53\u4f1a\u8ba1\u5de5\u4f5c\u88ab\u59d4\u6258\u65f6\uff0cCFO\u81ea\u613f\u79bb\u804c\u7684\u53ef\u80fd\u6027\u66f4\u4f4e\u3002\u6b64\u5916\uff0c\u6211\u4eec\u53d1\u73b0\u4f1a\u8ba1\u5de5\u4f5c\u59d4\u6258\u4e0e\u81ea\u613f\u79bb\u804c\u4e4b\u95f4\u7684\u8d1f\u76f8\u5173\u5173\u7cfb\u5728\u4f1a\u8ba1\u9700\u6c42\u8f83\u9ad8\u7684\u60c5\u51b5\u4e0b\u66f4\u4e3a\u663e\u8457\u3002\u540c\u65f6\uff0c\u6211\u4eec\u53d1\u73b0\u4ee3\u7406\u4f1a\u8ba1\u4f1a\u63d0\u5347CFO\u7684\u4eba\u529b\u8d44\u672c\u3002\u5f53CFO\u79bb\u804c\u65f6\uff0c\u4ed6\u4eec\u66f4\u53ef\u80fd\u8f6c\u4efb\u9996\u5e2d\u6267\u884c\u5b98\uff0c\u800c\u8f83\u5c11\u8f6c\u4efb\u5176\u4ed6\u9996\u5e2d\u8d22\u52a1\u5b98\u804c\u4f4d\u3002\u7efc\u5408\u6765\u770b\uff0c\u672c\u7814\u7a76\u53d1\u73b0\u4ee3\u7406\u4f1a\u8ba1\u6709\u52a9\u4e8e\u63d0\u9ad8CFO\u7684\u7559\u4efb\u7387\u548c\u4eba\u529b\u8d44\u672c\u6c34\u5e73\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2022.02201", "journal": "MS", "title": "An Economic Analysis of Online Ad Fraud Deterrence", "authors": ["Min Chen", "Subodha Kumar", "Abhishek Ray"], "author_details": [{"name": "Min Chen", "affiliations": ["Costello College of Business, George Mason University, Fairfax, Virginia 22030"]}, {"name": "Subodha Kumar", "affiliations": ["Fox School of Business, Temple University, Philadelphia, Pennsylvania 19122"]}, {"name": "Abhishek Ray", "affiliations": ["Costello College of Business, George Mason University, Fairfax, Virginia 22030"]}], "abstract": "Ad fraud is increasingly becoming a major concern in online advertising, with publishers being one of the key sources of fraudulent ad traffic. Although ad fraud deterrence is a critical problem from both technical and economic perspectives, past research has not considered their interplay. Our paper fills this critical gap by building a game-theoretic model wherein an ad network (an intermediary between publishers and advertisers) strategically leverages its technological tool (the configuration of a given fraud detection technology) and economic tool (the payment to publishers) to deter ad fraud and maximize profits effectively. Our analysis generates several interesting findings. For example, as the fraud detection technology and fraud generation techniques improve, we show that although the ad network needs to respond by making the technology configuration stricter to dampen fraud motives and admit less ad traffic, it may sometimes need to increase the payment. Furthermore, although many stakeholders advocate instituting strict legislation and policies to reduce malicious publishers, we show that this may sometimes fail to reduce fraud traffic and even hurt an ad network\u2019s profit. In addition, our results provide other useful implications that present a new theoretical perspective on the incentive problems in ad fraud generation and detection. Our study also draws valuable insights for ad networks into implementing effective ad fraud deterrence policies and for advertisers to audit and monitor their ad campaign performance.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2022.02201", "title_zh": "\u5728\u7ebf\u5e7f\u544a\u6b3a\u8bc8\u904f\u5236\u7684\u7ecf\u6d4e\u5206\u6790", "abstract_zh": "\u5e7f\u544a\u6b3a\u8bc8\u6b63\u65e5\u76ca\u6210\u4e3a\u5728\u7ebf\u5e7f\u544a\u9886\u57df\u7684\u91cd\u8981\u95ee\u9898\uff0c\u5176\u4e2d\u53d1\u5e03\u8005\u662f\u6b3a\u8bc8\u6027\u5e7f\u544a\u6d41\u91cf\u7684\u4e3b\u8981\u6765\u6e90\u4e4b\u4e00\u3002\u5c3d\u7ba1\u4ece\u6280\u672f\u548c\u7ecf\u6d4e\u89d2\u5ea6\u6765\u770b\uff0c\u5e7f\u544a\u6b3a\u8bc8\u904f\u5236\u90fd\u662f\u4e00\u4e2a\u5173\u952e\u95ee\u9898\uff0c\u4f46\u4ee5\u5f80\u7814\u7a76\u5e76\u672a\u8003\u8651\u4e8c\u8005\u4e4b\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\u3002\u672c\u6587\u586b\u8865\u4e86\u8fd9\u4e00\u5173\u952e\u7a7a\u767d\uff0c\u6784\u5efa\u4e86\u4e00\u4e2a\u535a\u5f08\u8bba\u6a21\u578b\uff0c\u5176\u4e2d\u5e7f\u544a\u7f51\u7edc\uff08\u8fde\u63a5\u53d1\u5e03\u8005\u548c\u5e7f\u544a\u4e3b\u7684\u4e2d\u4ecb\uff09\u6218\u7565\u6027\u5730\u5229\u7528\u5176\u6280\u672f\u624b\u6bb5\uff08\u7279\u5b9a\u6b3a\u8bc8\u68c0\u6d4b\u6280\u672f\u7684\u914d\u7f6e\uff09\u548c\u7ecf\u6d4e\u624b\u6bb5\uff08\u5411\u53d1\u5e03\u8005\u652f\u4ed8\u8d39\u7528\uff09\uff0c\u4ee5\u6709\u6548\u904f\u5236\u5e7f\u544a\u6b3a\u8bc8\u5e76\u6700\u5927\u5316\u5229\u6da6\u3002\u6211\u4eec\u7684\u5206\u6790\u5f97\u51fa\u82e5\u5e72\u6709\u8da3\u7ed3\u8bba\uff1a\u4f8b\u5982\uff0c\u968f\u7740\u6b3a\u8bc8\u68c0\u6d4b\u6280\u672f\u548c\u6b3a\u8bc8\u751f\u6210\u6280\u672f\u7684\u63d0\u5347\uff0c\u6211\u4eec\u8868\u660e\u5e7f\u544a\u7f51\u7edc\u9700\u8981\u901a\u8fc7\u4f7f\u6280\u672f\u914d\u7f6e\u66f4\u52a0\u4e25\u683c\u6765\u6291\u5236\u6b3a\u8bc8\u52a8\u673a\u5e76\u51cf\u5c11\u5e7f\u544a\u6d41\u91cf\uff0c\u4f46\u6709\u65f6\u53ef\u80fd\u9700\u8981\u63d0\u9ad8\u652f\u4ed8\u91d1\u989d\u3002\u6b64\u5916\uff0c\u5c3d\u7ba1\u8bb8\u591a\u5229\u76ca\u76f8\u5173\u65b9\u4e3b\u5f20\u901a\u8fc7\u5236\u5b9a\u4e25\u683c\u7acb\u6cd5\u548c\u653f\u7b56\u6765\u51cf\u5c11\u6076\u610f\u53d1\u5e03\u8005\uff0c\u4f46\u6211\u4eec\u8868\u660e\uff0c\u8fd9\u6709\u65f6\u53ef\u80fd\u65e0\u6cd5\u51cf\u5c11\u6b3a\u8bc8\u6d41\u91cf\uff0c\u751a\u81f3\u635f\u5bb3\u5e7f\u544a\u7f51\u7edc\u7684\u5229\u6da6\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8fd8\u63d0\u4f9b\u4e86\u5176\u4ed6\u6709\u7528\u7684\u542f\u793a\uff0c\u4e3a\u5e7f\u544a\u6b3a\u8bc8\u751f\u6210\u4e0e\u68c0\u6d4b\u4e2d\u7684\u6fc0\u52b1\u95ee\u9898\u63d0\u4f9b\u4e86\u65b0\u7684\u7406\u8bba\u89c6\u89d2\u3002\u540c\u65f6\uff0c\u672c\u7814\u7a76\u4e5f\u4e3a\u5e7f\u544a\u7f51\u7edc\u5b9e\u65bd\u6709\u6548\u7684\u5e7f\u544a\u6b3a\u8bc8\u904f\u5236\u653f\u7b56\uff0c\u4ee5\u53ca\u5e7f\u544a\u4e3b\u5bf9\u5e7f\u544a\u6d3b\u52a8\u7ee9\u6548\u8fdb\u884c\u5ba1\u8ba1\u548c\u76d1\u63a7\u63d0\u4f9b\u4e86\u5b9d\u8d35\u7684\u53c2\u8003\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1287/mnsc.2025.03558", "journal": "MS", "title": "A Note on \u201cCorporate Provision of Public Goods\u201d", "authors": ["Thomas Eichner", "Mark Schopf"], "author_details": [{"name": "Thomas Eichner", "affiliations": ["Faculty of Business Administration and Economics, FernUniversit\u00e4t in Hagen, 58097 Hagen, Germany"]}, {"name": "Mark Schopf", "affiliations": ["Faculty of Business Administration and Economics, FernUniversit\u00e4t in Hagen, 58097 Hagen, Germany"]}], "abstract": "Morgan and Tumlinson (2019, Management Science 65(10), 4489\u20134504) study a game in which citizens first fund a company venture or purchase bonds, and then bondholders and the firm\u2019s manager, acting on behalf of the shareholders, contribute to a public good. One of their major results is that the venture is funded with positive probability in all trembling-hand perfect Nash equilibria. The purpose of this note is to prove the existence of economies in which the venture is not funded in all trembling-hand perfect Nash equilibria.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2025.03558", "topics": ["\u5176\u4ed6"], "title_zh": "\u5173\u4e8e\u300a\u4f01\u4e1a\u63d0\u4f9b\u516c\u5171\u7269\u54c1\u300b\u7684\u4e00\u5219\u8bf4\u660e", "abstract_zh": "Morgan\u548cTumlinson\uff082019\u5e74\uff0c\u300a\u7ba1\u7406\u79d1\u5b66\u300b65(10)\uff0c4489\u20134504\uff09\u7814\u7a76\u4e86\u4e00\u4e2a\u535a\u5f08\uff0c\u5176\u4e2d\u516c\u6c11\u9996\u5148\u9009\u62e9\u8d44\u52a9\u4e00\u5bb6\u516c\u53f8\u9879\u76ee\u6216\u8d2d\u4e70\u503a\u5238\uff0c\u7136\u540e\u503a\u5238\u6301\u6709\u4eba\u548c\u516c\u53f8\u7ecf\u7406\u4ee3\u8868\u80a1\u4e1c\u5171\u540c\u51fa\u8d44\u7528\u4e8e\u516c\u5171\u7269\u54c1\u3002\u4ed6\u4eec\u7684\u4e00\u9879\u4e3b\u8981\u7ed3\u8bba\u662f\uff0c\u5728\u6240\u6709\u98a4\u6296\u624b\u5b8c\u7f8e\u7eb3\u4ec0\u5747\u8861\u4e2d\uff0c\u8be5\u9879\u76ee\u5747\u4ee5\u6b63\u6982\u7387\u88ab\u8d44\u52a9\u3002\u672c\u6587\u7684\u76ee\u7684\u5728\u4e8e\u8bc1\u660e\u5b58\u5728\u67d0\u4e9b\u7ecf\u6d4e\u73af\u5883\uff0c\u5728\u8fd9\u4e9b\u73af\u5883\u4e2d\uff0c\u9879\u76ee\u5728\u6240\u6709\u98a4\u6296\u624b\u5b8c\u7f8e\u7eb3\u4ec0\u5747\u8861\u4e2d\u5747\u4e0d\u88ab\u8d44\u52a9\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2023.00726", "journal": "MS", "title": "The Need for Fees at a DEX: How Increases in Fees Can Increase DEX Trading Volume", "authors": ["Joel Hasbrouck", "Thomas J. Rivera", "Fahad Saleh"], "author_details": [{"name": "Joel Hasbrouck", "affiliations": ["Stern School of Business, New York University, New York, New York 10012"]}, {"name": "Thomas J. Rivera", "affiliations": ["McGill University, Montreal, Quebec H3A 0G4, Canada"]}, {"name": "Fahad Saleh", "affiliations": ["University of Florida, Gainesville, Florida 32611"]}], "abstract": "We model endogenous trading and liquidity provision at a decentralized exchange (DEX) and demonstrate that increasing DEX trading fees can increase DEX trading volume. DEXs employ a mechanical pricing rule whereby price impacts decrease with inventory that DEXs acquire by offering fee revenues to investors. Consequently, higher DEX fees can incentivize higher inventory, thereby reducing price impacts. Moreover, the reduction of price impact can offset the increase in fees so that the marginal cost of DEX trading declines despite charging a higher trading fee. In turn, lower DEX marginal trading costs lead to an increase in DEX trading volume.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.00726", "topics": ["\u5176\u4ed6"], "title_zh": "\u53bb\u4e2d\u5fc3\u5316\u4ea4\u6613\u6240\u4e2d\u8d39\u7528\u7684\u5fc5\u8981\u6027\uff1a\u8d39\u7528\u589e\u52a0\u5982\u4f55\u63d0\u5347\u53bb\u4e2d\u5fc3\u5316\u4ea4\u6613\u6240\u4ea4\u6613\u91cf", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u53bb\u4e2d\u5fc3\u5316\u4ea4\u6613\u6240\uff08DEX\uff09\u4e2d\u5185\u751f\u4ea4\u6613\u548c\u6d41\u52a8\u6027\u63d0\u4f9b\u884c\u4e3a\u7684\u6a21\u578b\uff0c\u8bc1\u660e\u63d0\u9ad8DEX\u4ea4\u6613\u8d39\u7528\u53ef\u4ee5\u589e\u52a0DEX\u7684\u4ea4\u6613\u91cf\u3002\u53bb\u4e2d\u5fc3\u5316\u4ea4\u6613\u6240\u91c7\u7528\u673a\u68b0\u5b9a\u4ef7\u89c4\u5219\uff0c\u5373\u968f\u7740\u4ea4\u6613\u6240\u901a\u8fc7\u5411\u6295\u8d44\u8005\u63d0\u4f9b\u8d39\u7528\u6536\u5165\u800c\u79ef\u7d2f\u7684\u5e93\u5b58\u589e\u52a0\uff0c\u4ef7\u683c\u51b2\u51fb\u4f1a\u51cf\u5c0f\u3002\u56e0\u6b64\uff0c\u66f4\u9ad8\u7684DEX\u8d39\u7528\u53ef\u4ee5\u6fc0\u52b1\u66f4\u9ad8\u7684\u5e93\u5b58\u79ef\u7d2f\uff0c\u4ece\u800c\u964d\u4f4e\u4ef7\u683c\u51b2\u51fb\u3002\u6b64\u5916\uff0c\u4ef7\u683c\u51b2\u51fb\u7684\u51cf\u5c11\u53ef\u4ee5\u62b5\u6d88\u4ea4\u6613\u8d39\u7528\u7684\u4e0a\u5347\uff0c\u4f7f\u5f97DEX\u4ea4\u6613\u7684\u8fb9\u9645\u6210\u672c\u4e0b\u964d\uff0c\u5373\u4f7f\u6536\u8d39\u66f4\u9ad8\u3002\u968f\u4e4b\u800c\u6765\u7684\u662fDEX\u4ea4\u6613\u7684\u8fb9\u9645\u6210\u672c\u964d\u4f4e\uff0c\u4ece\u800c\u5bfc\u81f4DEX\u4ea4\u6613\u91cf\u7684\u589e\u52a0\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2024.08149", "journal": "MS", "title": "Transaction Sequencing and House Price Pressures", "authors": ["Morten Grindaker", "Artashes Karapetyan", "Espen R. Moen", "Plamen Nenov"], "author_details": [{"name": "Morten Grindaker", "affiliations": ["BI Norwegian Business School, 0484 Oslo, Norway"]}, {"name": "Artashes Karapetyan", "affiliations": ["ESSEC Busienss School, 95000 Cergy, France"]}, {"name": "Espen R. Moen", "affiliations": ["BI Norwegian Business School, 0484 Oslo, Norway"]}, {"name": "Plamen Nenov", "affiliations": ["Norges Bank and BI Norwegian Business School, 0151 Oslo, Norway"]}], "abstract": "We use a unique data set of individual housing transaction histories from Norway and a novel shift-share design to show that temporary changes in the transaction sequencing decisions of moving homeowners\u2014whether to buy first and then sell or vice versa\u2014cause temporary local increases in house prices and seller liquidity. Our findings are consistent with a simple theory of how transaction sequencing decisions impact house prices in a frictional housing market. We also provide the first causal estimate of the elasticity of house prices to market tightness, which is around 0.1. Overall, our findings highlight the importance of trading frictions and supply-demand imbalances for housing market dynamics.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08149", "topics": ["\u5176\u4ed6"], "title_zh": "\u4ea4\u6613\u987a\u5e8f\u4e0e\u623f\u4ef7\u538b\u529b", "abstract_zh": "\u6211\u4eec\u5229\u7528\u632a\u5a01\u7684\u4e2a\u4f53\u4f4f\u623f\u4ea4\u6613\u5386\u53f2\u6570\u636e\uff0c\u5e76\u91c7\u7528\u4e00\u79cd\u65b0\u7684\u79fb\u4f4d\u4efd\u989d\u8bbe\u8ba1\uff0c\u53d1\u73b0\u79fb\u52a8\u4e1a\u4e3b\u5728\u4ea4\u6613\u987a\u5e8f\u51b3\u7b56\u4e0a\u7684\u4e34\u65f6\u53d8\u5316\u2014\u2014\u65e0\u8bba\u662f\u5148\u4e70\u540e\u5356\u8fd8\u662f\u5148\u5356\u540e\u4e70\u2014\u2014\u4f1a\u5bfc\u81f4\u5f53\u5730\u623f\u4ef7\u548c\u5356\u5bb6\u6d41\u52a8\u6027\u51fa\u73b0\u6682\u65f6\u6027\u4e0a\u5347\u3002\u6211\u4eec\u7684\u53d1\u73b0\u4e0e\u6469\u64e6\u6027\u4f4f\u623f\u5e02\u573a\u4e2d\u4ea4\u6613\u987a\u5e8f\u51b3\u7b56\u5f71\u54cd\u623f\u4ef7\u7684\u7b80\u5355\u7406\u8bba\u4e00\u81f4\u3002\u6211\u4eec\u8fd8\u9996\u6b21\u5bf9\u623f\u4ef7\u5bf9\u5e02\u573a\u7d27\u7f29\u7a0b\u5ea6\u7684\u5f39\u6027\u8fdb\u884c\u4e86\u56e0\u679c\u4f30\u8ba1\uff0c\u8be5\u5f39\u6027\u503c\u7ea6\u4e3a0.1\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u53d1\u73b0\u5f3a\u8c03\u4e86\u4ea4\u6613\u6469\u64e6\u548c\u4f9b\u9700\u5931\u8861\u5728\u4f4f\u623f\u5e02\u573a\u52a8\u6001\u4e2d\u7684\u91cd\u8981\u6027\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2022.03264", "journal": "MS", "title": "Forced Ranking Systems and Gender Gaps in Job Tenure", "authors": ["Shuo Yan", "Shaobo (Kevin) Li", "Daniel Houser", "Chunmian Ge", "Jiayi Zhuo"], "author_details": [{"name": "Shuo Yan", "affiliations": ["International Business School, Zhejiang University, Haining, Zhejiang 314400, China"]}, {"name": "Shaobo (Kevin) Li", "affiliations": ["School of Business, Southern University of Science and Technology, Shenzhen, Guangdong Province 518055, China"]}, {"name": "Daniel Houser", "affiliations": ["Interdisciplinary Center for Economic Science, George Mason University, Arlington, Virginia 22201"]}, {"name": "Chunmian Ge", "affiliations": ["School of Business Administration, South China University of Technology, Guangzhou, Guangdong Province 510641, China"]}, {"name": "Jiayi Zhuo", "affiliations": ["School of Business, Macau University of Science and Technology, Taipa, Macao, China"]}], "abstract": "Using career history data from employees\u2019 online profiles, we provide empirical evidence regarding how human resources systems can affect the gender gap in job tenure. Our results indicate that female workers experience shorter average job tenure than male workers. Our results further show that abandoning forced ranking systems helps to narrow this gender gap. We present experimental evidence indicating that in forced ranking environments, women experience shorter tenure than men and are more likely to exit their roles. This is true even when women are on equal footing with men. Finally, we present survey evidence that under forced ranking systems, more women resign as compared with men. In sum, our empirical, experimental, and survey results indicate that forced ranking systems may contribute to a gender gap in job tenure. Accordingly, abandoning such systems may help promote workplace gender equality.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2022.03264", "topics": ["\u5176\u4ed6"], "title_zh": "\u5f3a\u5236\u6392\u540d\u5236\u5ea6\u4e0e\u6027\u522b\u5728\u5de5\u4f5c\u5e74\u9650\u4e0a\u7684\u5dee\u8ddd", "abstract_zh": "\u5229\u7528\u5458\u5de5\u5728\u7ebf\u6863\u6848\u4e2d\u7684\u804c\u4e1a\u5386\u53f2\u6570\u636e\uff0c\u6211\u4eec\u63d0\u4f9b\u4e86\u5173\u4e8e\u4eba\u529b\u8d44\u6e90\u7cfb\u7edf\u5982\u4f55\u5f71\u54cd\u6027\u522b\u5728\u5de5\u4f5c\u5e74\u9650\u5dee\u8ddd\u7684\u5b9e\u8bc1\u8bc1\u636e\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u5973\u6027\u5458\u5de5\u7684\u5e73\u5747\u5de5\u4f5c\u5e74\u9650\u77ed\u4e8e\u7537\u6027\u5458\u5de5\u3002\u8fdb\u4e00\u6b65\u7ed3\u679c\u663e\u793a\uff0c\u653e\u5f03\u5f3a\u5236\u6392\u540d\u5236\u5ea6\u6709\u52a9\u4e8e\u7f29\u5c0f\u8fd9\u4e00\u6027\u522b\u5dee\u8ddd\u3002\u6211\u4eec\u63d0\u4f9b\u4e86\u5b9e\u9a8c\u8bc1\u636e\u8868\u660e\uff0c\u5728\u5f3a\u5236\u6392\u540d\u73af\u5883\u4e2d\uff0c\u5973\u6027\u5458\u5de5\u7684\u5de5\u4f5c\u5e74\u9650\u77ed\u4e8e\u7537\u6027\u5458\u5de5\uff0c\u4e14\u66f4\u53ef\u80fd\u9000\u51fa\u5c97\u4f4d\uff0c\u5373\u4f7f\u5973\u6027\u4e0e\u7537\u6027\u5904\u4e8e\u540c\u7b49\u5730\u4f4d\u3002\u6700\u540e\uff0c\u6211\u4eec\u63d0\u4f9b\u4e86\u8c03\u67e5\u8bc1\u636e\u8868\u660e\uff0c\u5728\u5f3a\u5236\u6392\u540d\u5236\u5ea6\u4e0b\uff0c\u5973\u6027\u79bb\u804c\u7684\u6bd4\u4f8b\u9ad8\u4e8e\u7537\u6027\u3002\u7efc\u4e0a\uff0c\u6211\u4eec\u7684\u5b9e\u8bc1\u3001\u5b9e\u9a8c\u548c\u8c03\u67e5\u7ed3\u679c\u8868\u660e\uff0c\u5f3a\u5236\u6392\u540d\u5236\u5ea6\u53ef\u80fd\u52a0\u5267\u6027\u522b\u5728\u5de5\u4f5c\u5e74\u9650\u4e0a\u7684\u5dee\u8ddd\u3002\u56e0\u6b64\uff0c\u653e\u5f03\u6b64\u7c7b\u5236\u5ea6\u53ef\u80fd\u6709\u52a9\u4e8e\u4fc3\u8fdb\u804c\u573a\u6027\u522b\u5e73\u7b49\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2023.03756", "journal": "MS", "title": "The Role of Success and Failure in Fluid Teams: Evidence from the Motion Picture Industry", "authors": ["Suresh Muthulingam", "Kumar Rajaram"], "author_details": [{"name": "Suresh Muthulingam", "affiliations": ["Smeal College of Business, The Pennsylvania State University, University Park, Pennsylvania 16802"]}, {"name": "Kumar Rajaram", "affiliations": ["Anderson School of Management, University of California, Los Angeles, Los Angeles, California 90095"]}], "abstract": "Many business settings involve fluid teams, where team members come together to work on a project, after which the team is disbanded. It is well-known that coordination can be challenging and affect the performance outcomes of fluid teams. The literature has studied how several facets of experience can facilitate learning and improve outcomes for fluid teams. However, the role of experience with success and failure and its effect on improving outcomes for fluid teams has remained unexplored. In this study, we use data from the motion picture industry to examine how the experience with success and failure resident within key members of a movie production team affects profitability. Our analysis of the data for 2,091 movies released in the United States between 1999 and 2018 reveals that a movie\u2019s profitability depends on the production team\u2019s history with success and failure. Additionally, we find that teams with a history of success result in movies with higher profits, whereas teams with a history of failure result in movies with lower profits. We also find that increased relative dispersion in the team\u2019s experience does not affect the movie\u2019s profitability. Further analysis of the composition of movie teams indicates that financial performance can be significantly impacted when movie teams are predominantly composed of members with a history of success or failure. We contribute by illustrating a new measure of team experience relevant for fluid teams and by providing insights on how to compose teams based on members\u2019 experience with success and failure.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.03756", "topics": ["\u5176\u4ed6"], "title_zh": "\u6210\u529f\u4e0e\u5931\u8d25\u7ecf\u9a8c\u5728\u6d41\u52a8\u56e2\u961f\u4e2d\u7684\u4f5c\u7528\uff1a\u6765\u81ea\u7535\u5f71\u4ea7\u4e1a\u7684\u8bc1\u636e", "abstract_zh": "\u8bb8\u591a\u5546\u4e1a\u73af\u5883\u90fd\u6d89\u53ca\u6d41\u52a8\u56e2\u961f\uff0c\u5373\u56e2\u961f\u6210\u5458\u4e34\u65f6\u805a\u96c6\u5171\u540c\u5b8c\u6210\u4e00\u4e2a\u9879\u76ee\uff0c\u9879\u76ee\u5b8c\u6210\u540e\u56e2\u961f\u4fbf\u89e3\u6563\u3002\u4f17\u6240\u5468\u77e5\uff0c\u534f\u8c03\u5de5\u4f5c\u5177\u6709\u6311\u6218\u6027\uff0c\u4f1a\u5f71\u54cd\u6d41\u52a8\u56e2\u961f\u7684\u7ee9\u6548\u3002\u73b0\u6709\u6587\u732e\u63a2\u8ba8\u4e86\u591a\u79cd\u7ecf\u9a8c\u56e0\u7d20\u5982\u4f55\u4fc3\u8fdb\u5b66\u4e60\u5e76\u6539\u5584\u6d41\u52a8\u56e2\u961f\u7684\u6210\u679c\uff0c\u4f46\u5173\u4e8e\u6210\u529f\u4e0e\u5931\u8d25\u7ecf\u9a8c\u7684\u4f5c\u7528\u53ca\u5176\u5bf9\u6d41\u52a8\u56e2\u961f\u6210\u679c\u7684\u5f71\u54cd\u4ecd\u9c9c\u6709\u7814\u7a76\u3002\u5728\u672c\u7814\u7a76\u4e2d\uff0c\u6211\u4eec\u5229\u7528\u7535\u5f71\u4ea7\u4e1a\u7684\u6570\u636e\uff0c\u8003\u5bdf\u7535\u5f71\u5236\u4f5c\u56e2\u961f\u4e2d\u5173\u952e\u6210\u5458\u8fc7\u5f80\u6210\u529f\u4e0e\u5931\u8d25\u7ecf\u9a8c\u5982\u4f55\u5f71\u54cd\u7535\u5f71\u7684\u76c8\u5229\u80fd\u529b\u3002\u6211\u4eec\u5bf91999\u5e74\u81f32018\u5e74\u671f\u95f4\u5728\u7f8e\u56fd\u4e0a\u6620\u76842091\u90e8\u7535\u5f71\u7684\u6570\u636e\u8fdb\u884c\u5206\u6790\uff0c\u53d1\u73b0\u7535\u5f71\u7684\u76c8\u5229\u80fd\u529b\u53d6\u51b3\u4e8e\u5236\u4f5c\u56e2\u961f\u6210\u5458\u8fc7\u53bb\u6210\u529f\u4e0e\u5931\u8d25\u7684\u7ecf\u9a8c\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u62e5\u6709\u6210\u529f\u5386\u53f2\u7684\u56e2\u961f\u5236\u4f5c\u51fa\u7684\u7535\u5f71\u5229\u6da6\u66f4\u9ad8\uff0c\u800c\u62e5\u6709\u5931\u8d25\u5386\u53f2\u7684\u56e2\u961f\u5236\u4f5c\u51fa\u7684\u7535\u5f71\u5229\u6da6\u66f4\u4f4e\u3002\u6b64\u5916\uff0c\u6211\u4eec\u53d1\u73b0\u56e2\u961f\u6210\u5458\u7ecf\u9a8c\u7684\u76f8\u5bf9\u5206\u6563\u7a0b\u5ea6\u5e76\u4e0d\u5f71\u54cd\u7535\u5f71\u7684\u76c8\u5229\u80fd\u529b\u3002\u8fdb\u4e00\u6b65\u5bf9\u7535\u5f71\u56e2\u961f\u6784\u6210\u7684\u5206\u6790\u8868\u660e\uff0c\u5f53\u56e2\u961f\u4e3b\u8981\u7531\u5177\u6709\u6210\u529f\u6216\u5931\u8d25\u5386\u53f2\u7684\u6210\u5458\u7ec4\u6210\u65f6\uff0c\u8d22\u52a1\u8868\u73b0\u4f1a\u53d7\u5230\u663e\u8457\u5f71\u54cd\u3002\u672c\u7814\u7a76\u8d21\u732e\u5728\u4e8e\u63d0\u51fa\u4e86\u9002\u7528\u4e8e\u6d41\u52a8\u56e2\u961f\u7684\u65b0\u7ecf\u9a8c\u8861\u91cf\u6307\u6807\uff0c\u5e76\u4e3a\u5982\u4f55\u57fa\u4e8e\u6210\u5458\u7684\u6210\u529f\u4e0e\u5931\u8d25\u7ecf\u9a8c\u6765\u7ec4\u5efa\u56e2\u961f\u63d0\u4f9b\u4e86\u89c1\u89e3\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2023.01839", "journal": "MS", "title": "Information Provision and the Curse of Knowledge", "authors": ["Snehal Banerjee", "Jesse Davis", "Naveen Gondhi"], "author_details": [{"name": "Snehal Banerjee", "affiliations": ["University of Michigan\u2014Ann Arbor, Ann Arbor, Michigan 48109"]}, {"name": "Jesse Davis", "affiliations": ["University of North Carolina\u2014Chapel Hill, Chapel Hill, North Carolina 27599"]}, {"name": "Naveen Gondhi", "affiliations": ["INSEAD, 77305 Fontainebleau, France"]}], "abstract": "Common wisdom suggests that the \u201ccurse of knowledge\u201d (COK), whereby better-informed individuals are unable to ignore their private information when forecasting others\u2019 beliefs, reduces the quality of communication. We study how this bias affects costly information provision by a founder who wants to raise financing from an outside investor. When the founder exhibits COK about the content of her communication, there is less information provision and payoffs tend to be lower for both players. However, we show that when the founder exhibits COK about the context of her message, the bias can lead to more information production and better investment decisions. Moreover, this can exacerbate the conflict of interest between the founder and the outsider.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.01839", "topics": ["\u5176\u4ed6"], "title_zh": "\u4fe1\u606f\u63d0\u4f9b\u4e0e\u77e5\u8bc6\u8bc5\u5492", "abstract_zh": "\u666e\u904d\u8ba4\u4e3a\uff0c\u2018\u77e5\u8bc6\u8bc5\u5492\u2019\uff08COK\uff09\u2014\u2014\u5373\u4fe1\u606f\u66f4\u5145\u5206\u7684\u4e2a\u4f53\u5728\u9884\u6d4b\u4ed6\u4eba\u4fe1\u5ff5\u65f6\u65e0\u6cd5\u5ffd\u89c6\u5176\u79c1\u6709\u4fe1\u606f\u2014\u2014\u4f1a\u964d\u4f4e\u6c9f\u901a\u8d28\u91cf\u3002\u6211\u4eec\u7814\u7a76\u8fd9\u79cd\u504f\u89c1\u5982\u4f55\u5f71\u54cd\u521b\u59cb\u4eba\u5411\u5916\u90e8\u6295\u8d44\u8005\u878d\u8d44\u65f6\u7684\u6210\u672c\u6027\u4fe1\u606f\u63d0\u4f9b\u884c\u4e3a\u3002\u5f53\u521b\u59cb\u4eba\u5bf9\u5176\u4fe1\u606f\u4f20\u9012\u7684\u5185\u5bb9\u8868\u73b0\u51fa\u77e5\u8bc6\u8bc5\u5492\u65f6\uff0c\u4fe1\u606f\u63d0\u4f9b\u4f1a\u51cf\u5c11\uff0c\u53cc\u65b9\u7684\u6536\u76ca\u4e5f\u5f80\u5f80\u8f83\u4f4e\u3002\u7136\u800c\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5f53\u521b\u59cb\u4eba\u5bf9\u5176\u4fe1\u606f\u4f20\u9012\u7684\u8bed\u5883\u8868\u73b0\u51fa\u77e5\u8bc6\u8bc5\u5492\u65f6\uff0c\u8fd9\u79cd\u504f\u89c1\u53cd\u800c\u53ef\u80fd\u4fc3\u8fdb\u66f4\u591a\u4fe1\u606f\u7684\u4ea7\u751f\uff0c\u5e76\u6539\u5584\u6295\u8d44\u51b3\u7b56\u3002\u6b64\u5916\uff0c\u8fd9\u8fd8\u53ef\u80fd\u52a0\u5267\u521b\u59cb\u4eba\u4e0e\u5916\u90e8\u6295\u8d44\u8005\u4e4b\u95f4\u7684\u5229\u76ca\u51b2\u7a81\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2021.03426", "journal": "MS", "title": "Spatial Information Sharing on On-Demand Service Platforms", "authors": ["Swanand Kulkarni", "Basak Kalkanci"], "author_details": [{"name": "Swanand Kulkarni", "affiliations": ["Scheller College of Business, Georgia Institute of Technology, Atlanta, Georgia 30308"]}, {"name": "Basak Kalkanci", "affiliations": ["Scheller College of Business, Georgia Institute of Technology, Atlanta, Georgia 30308"]}], "abstract": "We investigate how an on-demand service platform\u2019s mechanism to share demand-supply mismatch information spatially affects drivers\u2019 relocation decisions and the platform\u2019s matching efficiency. We consider three mechanisms motivated by practice; the platform shares demand-supply mismatch information about either zones(s) with excess demand with all drivers (surge information sharing, common practice today), all zones with all drivers (full information sharing), or zone(s) with excess demand only with drivers sufficiently close by (local information sharing). We develop a game-theoretic model with three zones wherein drivers in two non-surge zones decide whether to relocate to the surge zone with excess demand. We incorporate two spatial aspects: drivers\u2019 relocation costs and initial supply across different non-surge zones. Theoretically, full information sharing can hurt the platform\u2019s matching efficiency compared with surge information sharing under low relocation costs because drivers in non-surge zones facing high demand locally do not chase the surge as much. Local information sharing is strictly dominated by other mechanisms in terms of matching efficiency when the supply of drivers near the surge zone is limited and weakly dominated otherwise by surge information sharing. We test these theory predictions in the laboratory with human participants as drivers in an environment where theoretical matching efficiency is highest with surge and lowest with local information sharing. Experimentally, the platform serves fewer customers than predicted with surge information sharing because drivers relocate too often, compromising efficiency in non-surge zones. In contrast, the platform serves more customers than predicted with full and local information sharing, and these mechanisms perform at least as well in matching efficiency as surge. Therefore, sharing demand-supply mismatch information either fully or in a targeted manner (as in local) can help to alleviate coordination problems on a platform. A behavioral equilibrium incorporating loss aversion through mental accounting and decision errors describes drivers\u2019 behavior in our experiments better than the rational equilibrium.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2021.03426", "topics": ["\u5176\u4ed6"], "title_zh": "\u6309\u9700\u670d\u52a1\u5e73\u53f0\u4e0a\u7684\u7a7a\u95f4\u4fe1\u606f\u5171\u4eab", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u6309\u9700\u670d\u52a1\u5e73\u53f0\u5728\u7a7a\u95f4\u4e0a\u5171\u4eab\u4f9b\u9700\u4e0d\u5339\u914d\u4fe1\u606f\u7684\u673a\u5236\u5982\u4f55\u5f71\u54cd\u53f8\u673a\u7684\u642c\u8fc1\u51b3\u7b56\u4ee5\u53ca\u5e73\u53f0\u7684\u5339\u914d\u6548\u7387\u3002\u6211\u4eec\u8003\u8651\u4e86\u4e09\u79cd\u57fa\u4e8e\u5b9e\u8df5\u7684\u673a\u5236\uff1a\u5e73\u53f0\u5411\u6240\u6709\u53f8\u673a\u5171\u4eab\u6709\u5173\u9700\u6c42\u8fc7\u5269\u533a\u57df\u7684\u4f9b\u9700\u4e0d\u5339\u914d\u4fe1\u606f\uff08\u5373\u9ad8\u5cf0\u4fe1\u606f\u5171\u4eab\uff0c\u76ee\u524d\u7684\u666e\u904d\u505a\u6cd5\uff09\uff0c\u5411\u6240\u6709\u533a\u57df\u7684\u6240\u6709\u53f8\u673a\u5171\u4eab\u4f9b\u9700\u4e0d\u5339\u914d\u4fe1\u606f\uff08\u5373\u5b8c\u5168\u4fe1\u606f\u5171\u4eab\uff09\uff0c\u6216\u4ec5\u5411\u8ddd\u79bb\u9700\u6c42\u8fc7\u5269\u533a\u57df\u8f83\u8fd1\u7684\u53f8\u673a\u5171\u4eab\u9700\u6c42\u8fc7\u5269\u533a\u57df\u7684\u4fe1\u606f\uff08\u5373\u5c40\u90e8\u4fe1\u606f\u5171\u4eab\uff09\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u4e09\u4e2a\u533a\u57df\u7684\u535a\u5f08\u6a21\u578b\uff0c\u5176\u4e2d\u4e24\u4e2a\u975e\u9ad8\u5cf0\u533a\u57df\u7684\u53f8\u673a\u51b3\u5b9a\u662f\u5426\u642c\u8fc1\u81f3\u9700\u6c42\u8fc7\u5269\u7684\u9ad8\u5cf0\u533a\u57df\u3002\u6a21\u578b\u4e2d\u7eb3\u5165\u4e86\u4e24\u4e2a\u7a7a\u95f4\u56e0\u7d20\uff1a\u53f8\u673a\u642c\u8fc1\u6210\u672c\u4ee5\u53ca\u4e0d\u540c\u975e\u9ad8\u5cf0\u533a\u57df\u7684\u521d\u59cb\u4f9b\u7ed9\u3002\u7406\u8bba\u4e0a\uff0c\u5728\u642c\u8fc1\u6210\u672c\u8f83\u4f4e\u7684\u60c5\u51b5\u4e0b\uff0c\u5b8c\u5168\u4fe1\u606f\u5171\u4eab\u53ef\u80fd\u6bd4\u9ad8\u5cf0\u4fe1\u606f\u5171\u4eab\u66f4\u635f\u5bb3\u5e73\u53f0\u7684\u5339\u914d\u6548\u7387\uff0c\u56e0\u4e3a\u975e\u9ad8\u5cf0\u533a\u57df\u4e2d\u9762\u4e34\u5c40\u90e8\u9ad8\u9700\u6c42\u7684\u53f8\u673a\u5e76\u4e0d\u79ef\u6781\u8ffd\u9010\u9ad8\u5cf0\u3002\u5f53\u9760\u8fd1\u9ad8\u5cf0\u533a\u57df\u7684\u53f8\u673a\u4f9b\u7ed9\u6709\u9650\u65f6\uff0c\u5c40\u90e8\u4fe1\u606f\u5171\u4eab\u5728\u5339\u914d\u6548\u7387\u4e0a\u4e25\u683c\u52a3\u4e8e\u5176\u4ed6\u673a\u5236\uff1b\u5426\u5219\uff0c\u5176\u8868\u73b0\u5f31\u4e8e\u9ad8\u5cf0\u4fe1\u606f\u5171\u4eab\u3002\u6211\u4eec\u5728\u5b9e\u9a8c\u5ba4\u4e2d\u901a\u8fc7\u4eba\u7c7b\u53c2\u4e0e\u8005\u4f5c\u4e3a\u53f8\u673a\uff0c\u5728\u7406\u8bba\u5339\u914d\u6548\u7387\u6700\u9ad8\uff08\u9ad8\u5cf0\u4fe1\u606f\u5171\u4eab\uff09\u548c\u6700\u4f4e\uff08\u5c40\u90e8\u4fe1\u606f\u5171\u4eab\uff09\u7684\u73af\u5883\u4e2d\u9a8c\u8bc1\u4e86\u8fd9\u4e9b\u7406\u8bba\u9884\u6d4b\u3002\u5b9e\u9a8c\u7ed3\u679c\u663e\u793a\uff0c\u9ad8\u5cf0\u4fe1\u606f\u5171\u4eab\u4e0b\u5e73\u53f0\u670d\u52a1\u7684\u5ba2\u6237\u6570\u91cf\u5c11\u4e8e\u7406\u8bba\u9884\u6d4b\uff0c\u56e0\u4e3a\u53f8\u673a\u642c\u8fc1\u8fc7\u4e8e\u9891\u7e41\uff0c\u635f\u5bb3\u4e86\u975e\u9ad8\u5cf0\u533a\u57df\u7684\u6548\u7387\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u5b8c\u5168\u4fe1\u606f\u5171\u4eab\u548c\u5c40\u90e8\u4fe1\u606f\u5171\u4eab\u4e0b\u5e73\u53f0\u670d\u52a1\u7684\u5ba2\u6237\u6570\u91cf\u591a\u4e8e\u7406\u8bba\u9884\u6d4b\uff0c\u4e14\u8fd9\u4e24\u79cd\u673a\u5236\u5728\u5339\u914d\u6548\u7387\u4e0a\u81f3\u5c11\u4e0e\u9ad8\u5cf0\u4fe1\u606f\u5171\u4eab\u76f8\u5f53\u3002\u56e0\u6b64\uff0c\u5171\u4eab\u4f9b\u9700\u4e0d\u5339\u914d\u4fe1\u606f\uff0c\u65e0\u8bba\u662f\u5b8c\u5168\u5171\u4eab\u8fd8\u662f\u6709\u9488\u5bf9\u6027\u5730\u5171\u4eab\uff08\u5982\u5c40\u90e8\u5171\u4eab\uff09\uff0c\u90fd\u6709\u52a9\u4e8e\u7f13\u89e3\u5e73\u53f0\u4e0a\u7684\u534f\u8c03\u95ee\u9898\u3002\u4e00\u4e2a\u7ed3\u5408\u635f\u5931\u538c\u6076\u3001\u5fc3\u7406\u8d26\u6237\u548c\u51b3\u7b56\u9519\u8bef\u7684\u884c\u4e3a\u4e3b\u89c2\u5747\u8861\uff0c\u6bd4\u7406\u6027\u5747\u8861\u66f4\u80fd\u89e3\u91ca\u5b9e\u9a8c\u4e2d\u53f8\u673a\u7684\u884c\u4e3a\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2026.01340", "journal": "MS", "title": "Commentary on \u201cMy Advisor, Her AI, and Me: Evidence from a Field Experiment on Human-AI Collaboration and Investment Decisions\u201d", "authors": ["Hans-Paul B\u00fcrkner"], "author_details": [{"name": "Hans-Paul B\u00fcrkner", "affiliations": ["The Boston Consulting Group, 80539 Munich, Germany"]}], "abstract": "This is a commentary by Dr. Hans-Paul B\u00fcrkner (Global Chair Emeritus and former CEO of The Boston Consulting Group) on Yang, Bauer, Li, and Hinz (2025) \u201cMy Advisor, Her AI, and Me: Evidence from a Field Experiment on Human\u2013AI Collaboration and Investment Decisions.\u201d", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2026.01340", "title_zh": "\u5173\u4e8e\u300a\u6211\u7684\u987e\u95ee\u3001\u5979\u7684AI\u4ee5\u53ca\u6211\uff1a\u6765\u81ea\u4e00\u9879\u5173\u4e8e\u4eba\u7c7b-\u4eba\u5de5\u667a\u80fd\u534f\u4f5c\u4e0e\u6295\u8d44\u51b3\u7b56\u7684\u5b9e\u5730\u5b9e\u9a8c\u7684\u8bc1\u636e\u300b\u7684\u8bc4\u8bba", "abstract_zh": "\u8fd9\u662f\u7531\u535a\u601d\u54a8\u8be2\u96c6\u56e2\u5168\u7403\u8363\u8a89\u4e3b\u5e2d\u3001\u524d\u9996\u5e2d\u6267\u884c\u5b98\u6c49\u65af-\u4fdd\u7f57\u00b7\u5e03\u5c14\u514b\u7eb3\u535a\u58eb\u5bf9\u6768\u3001\u9c8d\u5c14\u3001\u674e\u548c\u6b23\uff082025\uff09\u53d1\u8868\u7684\u300a\u6211\u7684\u987e\u95ee\u3001\u5979\u7684AI\u4ee5\u53ca\u6211\uff1a\u6765\u81ea\u4e00\u9879\u5173\u4e8e\u4eba\u7c7b-\u4eba\u5de5\u667a\u80fd\u534f\u4f5c\u4e0e\u6295\u8d44\u51b3\u7b56\u7684\u5b9e\u5730\u5b9e\u9a8c\u7684\u8bc1\u636e\u300b\u4e00\u6587\u6240\u64b0\u5199\u7684\u8bc4\u8bba\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2023.04263", "journal": "MS", "title": "Identifying Demand Curves in Index Option Markets", "authors": ["Kris Jacobs", "Anh Thu Mai", "Paola Pederzoli"], "author_details": [{"name": "Kris Jacobs", "affiliations": ["University of Houston, Houston, Texas 77204"]}, {"name": "Anh Thu Mai", "affiliations": ["Purdue University Northwest, Hammond, Indiana 46323"]}, {"name": "Paola Pederzoli", "affiliations": ["University of Houston, Houston, Texas 77204"]}], "abstract": "We identify latent demands in index option markets using a sign-restricted vector autoregression (VAR) and highlight the bias from treating (equilibrium) net demand as exogenous. Market-maker and end-user demand curves are far from infinitely elastic as assumed by some models, but elasticities exceed existing estimates for equities. Characterizing demand curves provides insights into the structure of index option markets. Deteriorating market conditions are associated with right shifts of the latent demand curves. The at-the-money (ATM) (out-of-the-money (OTM)) markets for calls and puts are mainly driven by end-user (market-maker) demand, and end-user (market-maker) ATM (OTM) call option demand predicts S&P500 returns.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.04263", "topics": ["\u5176\u4ed6"], "title_zh": "\u8bc6\u522b\u6307\u6570\u671f\u6743\u5e02\u573a\u7684\u9700\u6c42\u66f2\u7ebf", "abstract_zh": "\u6211\u4eec\u4f7f\u7528\u7b26\u53f7\u9650\u5236\u5411\u91cf\u81ea\u56de\u5f52\uff08VAR\uff09\u6a21\u578b\u8bc6\u522b\u6307\u6570\u671f\u6743\u5e02\u573a\u4e2d\u7684\u6f5c\u5728\u9700\u6c42\uff0c\u5e76\u5f3a\u8c03\u5c06\uff08\u5747\u8861\uff09\u51c0\u9700\u6c42\u89c6\u4e3a\u5916\u751f\u53d8\u91cf\u6240\u5e26\u6765\u7684\u504f\u5dee\u3002\u5e02\u573a\u505a\u5e02\u5546\u548c\u7ec8\u7aef\u7528\u6237\u7684\u9700\u6c42\u66f2\u7ebf\u8fdc\u975e\u67d0\u4e9b\u6a21\u578b\u6240\u5047\u8bbe\u7684\u65e0\u9650\u5f39\u6027\uff0c\u4f46\u5176\u5f39\u6027\u8d85\u8fc7\u4e86\u73b0\u6709\u80a1\u7968\u5e02\u573a\u7684\u4f30\u8ba1\u503c\u3002\u523b\u753b\u9700\u6c42\u66f2\u7ebf\u6709\u52a9\u4e8e\u7406\u89e3\u6307\u6570\u671f\u6743\u5e02\u573a\u7684\u7ed3\u6784\u3002\u5e02\u573a\u72b6\u51b5\u6076\u5316\u4e0e\u6f5c\u5728\u9700\u6c42\u66f2\u7ebf\u7684\u53f3\u79fb\u76f8\u5173\u3002\u5bf9\u4e8e\u770b\u6da8\u548c\u770b\u8dcc\u671f\u6743\uff0c\u5e73\u503c\uff08ATM\uff09\u548c\u865a\u503c\uff08OTM\uff09\u5e02\u573a\u4e3b\u8981\u7531\u7ec8\u7aef\u7528\u6237\uff08\u5e02\u573a\u505a\u5e02\u5546\uff09\u9700\u6c42\u9a71\u52a8\uff0c\u7ec8\u7aef\u7528\u6237\uff08\u5e02\u573a\u505a\u5e02\u5546\uff09\u5728\u5e73\u503c\uff08OTM\uff09\u770b\u6da8\u671f\u6743\u9700\u6c42\u80fd\u591f\u9884\u6d4b\u6807\u666e500\u6307\u6570\u7684\u56de\u62a5\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2023.03236", "journal": "MS", "title": "Tail-Driven Nonparametric Estimation for State Price Densities", "authors": ["Chenxu Li", "Xiaojun Song", "Yating Wan"], "author_details": [{"name": "Chenxu Li", "affiliations": ["Guanghua School of Management, Peking University, Beijing 100871, China"]}, {"name": "Xiaojun Song", "affiliations": ["Guanghua School of Management, Peking University, Beijing 100871, China"]}, {"name": "Yating Wan", "affiliations": ["School of Management Science and Engineering, Tianjin University of Finance and Economics, Tianjin 300222, China"]}], "abstract": "This paper proposes and implements a novel nonparametric method for estimating the state price density (SPD) over the entire state space, including the tails. This SPD estimator achieves shape consistency properties in theory, particularly at the tails. Monte Carlo simulations demonstrate the accuracy and robustness of our method. In particular, our estimator accurately captures the risk-neutral tail distribution, which is often underestimated by existing alternative methods. In an empirical analysis based on Standard and Poor\u2019s 500 options data, we evaluate the out-of-sample performance of our SPD estimation method and demonstrate that the estimates can serve as effective indicators for market conditions and exhibit predictive power for asset returns. Combining these perspectives, we suggest that our SPD estimator renders a valuable tool for risk management and asset pricing.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.03236", "title_zh": "\u5c3e\u90e8\u9a71\u52a8\u7684\u975e\u53c2\u6570\u72b6\u6001\u4ef7\u683c\u5bc6\u5ea6\u4f30\u8ba1", "abstract_zh": "\u672c\u6587\u63d0\u51fa\u5e76\u5b9e\u73b0\u4e86\u7528\u4e8e\u5728\u6574\u4e2a\u72b6\u6001\u7a7a\u95f4\uff08\u5305\u62ec\u5c3e\u90e8\uff09\u4f30\u8ba1\u72b6\u6001\u4ef7\u683c\u5bc6\u5ea6\uff08SPD\uff09\u7684\u4e00\u79cd\u65b0\u578b\u975e\u53c2\u6570\u65b9\u6cd5\u3002\u8be5SPD\u4f30\u8ba1\u5668\u5728\u7406\u8bba\u4e0a\u5177\u6709\u5f62\u72b6\u4e00\u81f4\u6027\u7279\u6027\uff0c\u5c24\u5176\u662f\u5728\u5c3e\u90e8\u533a\u57df\u3002\u8499\u7279\u5361\u6d1b\u6a21\u62df\u8868\u660e\uff0c\u8be5\u65b9\u6cd5\u5177\u6709\u51c6\u786e\u6027\u548c\u9c81\u68d2\u6027\u3002\u7279\u522b\u662f\uff0c\u6211\u4eec\u7684\u4f30\u8ba1\u65b9\u6cd5\u80fd\u591f\u51c6\u786e\u6355\u6349\u98ce\u9669\u4e2d\u6027\u5c3e\u90e8\u5206\u5e03\uff0c\u800c\u8fd9\u4e00\u5206\u5e03\u5f80\u5f80\u88ab\u73b0\u6709\u66ff\u4ee3\u65b9\u6cd5\u4f4e\u4f30\u3002\u57fa\u4e8e\u6807\u51c6\u666e\u5c14500\u6307\u6570\u671f\u6743\u6570\u636e\u7684\u5b9e\u8bc1\u5206\u6790\u4e2d\uff0c\u6211\u4eec\u8bc4\u4f30\u4e86\u8be5SPD\u4f30\u8ba1\u65b9\u6cd5\u7684\u6837\u672c\u5916\u8868\u73b0\uff0c\u5e76\u8bc1\u660e\u8fd9\u4e9b\u4f30\u8ba1\u7ed3\u679c\u53ef\u4f5c\u4e3a\u5e02\u573a\u72b6\u51b5\u7684\u6709\u6548\u6307\u793a\u5668\uff0c\u5e76\u5bf9\u8d44\u4ea7\u6536\u76ca\u5177\u6709\u9884\u6d4b\u80fd\u529b\u3002\u7efc\u5408\u8fd9\u4e9b\u89c6\u89d2\uff0c\u6211\u4eec\u8ba4\u4e3a\uff0c\u6211\u4eec\u7684SPD\u4f30\u8ba1\u5668\u4e3a\u98ce\u9669\u7ba1\u7406\u4e0e\u8d44\u4ea7\u5b9a\u4ef7\u63d0\u4f9b\u4e86\u6709\u4ef7\u503c\u7684\u5de5\u5177\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1287/mnsc.2024.04716", "journal": "MS", "title": "Getting on the Map: The Impact of Online Listings on Business Performance", "authors": ["Michael Luca", "Abhishek Nagaraj", "Gauri Subramani"], "author_details": [{"name": "Michael Luca", "affiliations": ["Johns Hopkins University, Baltimore, Maryland 20001"]}, {"name": "Abhishek Nagaraj", "affiliations": ["Haas School of Business, University of California, Berkeley, California 94720"]}, {"name": "Gauri Subramani", "affiliations": ["Management Department, Lehigh University, Bethlehem, Pennsylvania 18015"]}], "abstract": "We evaluate the extent to which small businesses maintain an online presence and estimate the impact of digital representation on business performance. Looking at a review platform, we find that roughly 18% of bars and restaurants in our sample do not have a listing as of the end of 2017, even though creating one is free. We then estimate the effect of adding a new listing using tax records on revenues combined with temporal variation in listing activity as well as a natural experiment that added over a thousand businesses to the platform via a data acquisition. The results suggest that new listings increase revenues in the range of 5%\u201310%; however, these effects vary substantially across establishments. Establishments that struggle to develop a reputation (e.g., nonchains or those in tourist areas) and those with a higher quality of product (e.g., larger restaurants or those with good reviews) experience larger increases after being listed.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.04716", "topics": ["\u5176\u4ed6"], "title_zh": "\u767b\u4e0a\u5730\u56fe\uff1a\u5728\u7ebf\u5217\u8868\u5bf9\u4f01\u4e1a\u53d1\u5c55\u7ee9\u6548\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u8bc4\u4f30\u4e86\u5c0f\u578b\u4f01\u4e1a\u7ef4\u6301\u5728\u7ebf\u5b58\u5728\u7a0b\u5ea6\uff0c\u5e76\u4f30\u8ba1\u4e86\u6570\u5b57\u8868\u793a\u5bf9\u4e1a\u52a1\u7ee9\u6548\u7684\u5f71\u54cd\u3002\u5728\u4e00\u5bb6\u8bc4\u8bba\u5e73\u53f0\u7684\u7814\u7a76\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\u622a\u81f32017\u5e74\u5e95\uff0c\u6837\u672c\u4e2d\u7684\u9152\u5427\u548c\u9910\u5385\u4e2d\u7ea6\u670918%\u6ca1\u6709\u5728\u7ebf\u5217\u8868\uff0c\u5c3d\u7ba1\u521b\u5efa\u5217\u8868\u662f\u514d\u8d39\u7684\u3002\u6211\u4eec\u5229\u7528\u7a0e\u6536\u8bb0\u5f55\u4e2d\u7684\u6536\u5165\u6570\u636e\uff0c\u7ed3\u5408\u5217\u8868\u6d3b\u52a8\u7684\u65f6\u95f4\u53d8\u5316\u4ee5\u53ca\u4e00\u4e2a\u81ea\u7136\u5b9e\u9a8c\uff08\u901a\u8fc7\u6570\u636e\u91c7\u96c6\u5c06\u8d85\u8fc7\u4e00\u5343\u5bb6\u5546\u5bb6\u6dfb\u52a0\u5230\u5e73\u53f0\uff09\uff0c\u6765\u4f30\u8ba1\u65b0\u589e\u5217\u8868\u7684\u5f71\u54cd\u3002\u7ed3\u679c\u8868\u660e\uff0c\u65b0\u589e\u5217\u8868\u4f7f\u6536\u5165\u589e\u52a05%\u81f310%\uff1b\u7136\u800c\uff0c\u8fd9\u79cd\u5f71\u54cd\u5728\u4e0d\u540c\u4f01\u4e1a\u4e4b\u95f4\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002\u90a3\u4e9b\u96be\u4ee5\u5efa\u7acb\u58f0\u8a89\u7684\u4f01\u4e1a\uff08\u4f8b\u5982\u975e\u8fde\u9501\u5e97\u6216\u4f4d\u4e8e\u65c5\u6e38\u533a\u7684\u4f01\u4e1a\uff09\u4ee5\u53ca\u4ea7\u54c1\u54c1\u8d28\u8f83\u9ad8\u7684\u4f01\u4e1a\uff08\u4f8b\u5982\u89c4\u6a21\u8f83\u5927\u7684\u9910\u5385\u6216\u62e5\u6709\u826f\u597d\u8bc4\u4ef7\u7684\u4f01\u4e1a\uff09\u5728\u88ab\u5217\u4e3a\u5728\u7ebf\u5546\u5bb6\u540e\uff0c\u6536\u5165\u589e\u957f\u66f4\u4e3a\u660e\u663e\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2024.05802", "journal": "MS", "title": "Gender Gap in Debt Renegotiation", "authors": ["Paulo Manoel", "Vinicius Brunassi Silva"], "author_details": [{"name": "Paulo Manoel", "affiliations": ["Gatton College of Business and Economics, University of Kentucky, Lexington, Kentucky 40506"]}, {"name": "Vinicius Brunassi Silva", "affiliations": ["S\u00e3o Paulo School of Economics, Funda\u00e7\u00e3o Getulio Vargas, S\u00e3o Paulo 01313-020, Brazil"]}], "abstract": "We study the role of gender in corporate debt renegotiation. Using in-court reorganizations from Brazil, we find that male-led creditors are more likely to reject plans put forward by female-led debtors. Although we cannot definitively identify the underlying mechanism driving this pattern, our findings align more consistently with gender-based discrimination compared with alternative explanations. This behavior may be costly: Female-led debtors deliver higher recoveries under reorganization than under liquidation, implying that rejections potentially create deadweight losses. Supporting a miscalibrated-beliefs explanation, we observe that the gender-based rejection gap narrows when male creditors have prior exposure to successful female-led businesses, pointing to a potential path for mitigation.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.05802", "topics": ["\u5176\u4ed6"], "title_zh": "\u503a\u52a1\u91cd\u7ec4\u4e2d\u7684\u6027\u522b\u5dee\u8ddd", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u6027\u522b\u5728\u4f01\u4e1a\u503a\u52a1\u91cd\u7ec4\u4e2d\u7684\u4f5c\u7528\u3002\u57fa\u4e8e\u5df4\u897f\u7684\u6cd5\u9662\u5185\u91cd\u7ec4\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u7531\u7537\u6027\u4e3b\u5bfc\u7684\u503a\u6743\u4eba\u66f4\u53ef\u80fd\u62d2\u7edd\u7531\u5973\u6027\u4e3b\u5bfc\u7684\u503a\u52a1\u4eba\u63d0\u51fa\u7684\u91cd\u7ec4\u8ba1\u5212\u3002\u5c3d\u7ba1\u6211\u4eec\u65e0\u6cd5 definitively \u786e\u5b9a\u9a71\u52a8\u8fd9\u4e00\u6a21\u5f0f\u7684\u5e95\u5c42\u673a\u5236\uff0c\u4f46\u6211\u4eec\u7684\u53d1\u73b0\u66f4\u7b26\u5408\u6027\u522b\u6b67\u89c6\u7684\u89e3\u91ca\uff0c\u800c\u975e\u5176\u4ed6\u66ff\u4ee3\u6027\u89e3\u91ca\u3002\u8fd9\u79cd\u884c\u4e3a\u53ef\u80fd\u5e26\u6765\u6210\u672c\uff1a\u7531\u5973\u6027\u4e3b\u5bfc\u7684\u503a\u52a1\u4eba\u5728\u91cd\u7ec4\u4e2d\u83b7\u5f97\u7684\u56de\u6536\u91d1\u989d\u9ad8\u4e8e\u6e05\u7b97\u60c5\u51b5\uff0c\u610f\u5473\u7740\u62d2\u7edd\u53ef\u80fd\u9020\u6210\u65e0\u8c13\u635f\u5931\u3002\u652f\u6301\u4e00\u79cd\u8ba4\u77e5\u504f\u5dee\u89e3\u91ca\uff0c\u6211\u4eec\u89c2\u5bdf\u5230\u5f53\u7537\u6027\u503a\u6743\u4eba\u66fe\u6709\u8fc7\u6210\u529f\u5973\u6027\u4e3b\u5bfc\u4f01\u4e1a\u63a5\u89e6\u7ecf\u5386\u65f6\uff0c\u57fa\u4e8e\u6027\u522b\u7684\u62d2\u7edd\u5dee\u8ddd\u4f1a\u7f29\u5c0f\uff0c\u8fd9\u8868\u660e\u5b58\u5728\u4e00\u79cd\u6f5c\u5728\u7684\u7f13\u89e3\u8def\u5f84\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2024.05744", "journal": "MS", "title": "Eliciting Supplier Cooperation for Value Chain Decarbonization: A Field Experiment with Smallholder Farmers in India", "authors": ["Sukti Ghosh", "Jasjit Singh"], "author_details": [{"name": "Sukti Ghosh", "affiliations": ["Lee Kong Chian School of Business, Singapore Management University, Singapore 178899"]}, {"name": "Jasjit Singh", "affiliations": ["INSEAD, Singapore 138676"]}], "abstract": "Many firms are pledging to reduce greenhouse gas emissions across their value chains. However, this requires their suppliers to also adopt more climate-friendly practices for decarbonization. This can involve addressing gaps in not only the suppliers\u2019 ability but also, their willingness to adopt such practices, which can be challenging if the suppliers perceive the practices as risky or potentially detrimental to their economic well-being. We examine the effectiveness of relational investments to help mitigate this challenge, arguing that such investments can serve as a signal of the firm\u2019s commitment toward joint value creation. In a field experiment conducted with supplier farmers in a multinational firm\u2019s agricultural supply chain in India, we examine the impact of two kinds of relational investments in providing the farmers with customized agricultural services that they valued. In the first intervention, the firm\u2019s field officers offered the farmers support specific to the crop that the firm sourced from them. The second intervention additionally involved bringing in expert agronomists to also provide the farmers with support on broader agricultural matters of interest to them. Relative to a control condition in which the farmers only received training on the relevant climate-friendly practices, both interventions improved the farmers\u2019 adoption of the recommended practices. The second intervention was more impactful than the first in improving the farmers\u2019 practice adoption as well as their retention with the firm. Exploratory mediation analysis and post-experiment field interviews suggest that these findings are partly driven by the farmers\u2019 positive perception of the firm\u2019s relational investments.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.05744", "title_zh": "\u901a\u8fc7\u5b9e\u5730\u5b9e\u9a8c\u4fc3\u8fdb\u4ef7\u503c\u94fe\u8131\u78b3\uff1a\u5370\u5ea6\u5c0f\u519c\u6237\u519c\u6c11\u7684\u4f9b\u5e94\u5546\u5408\u4f5c\u7814\u7a76", "abstract_zh": "\u8bb8\u591a\u4f01\u4e1a\u627f\u8bfa\u5728\u5176\u4ef7\u503c\u94fe\u4e2d\u51cf\u5c11\u6e29\u5ba4\u6c14\u4f53\u6392\u653e\u3002\u7136\u800c\uff0c\u8fd9\u9700\u8981\u5176\u4f9b\u5e94\u5546\u4e5f\u91c7\u53d6\u66f4\u73af\u4fdd\u7684\u5b9e\u8df5\u4ee5\u5b9e\u73b0\u8131\u78b3\u3002\u8fd9\u4e0d\u4ec5\u6d89\u53ca\u4f9b\u5e94\u5546\u80fd\u529b\u7684\u5dee\u8ddd\uff0c\u8fd8\u6d89\u53ca\u4ed6\u4eec\u91c7\u7eb3\u8fd9\u4e9b\u5b9e\u8df5\u7684\u610f\u613f\u95ee\u9898\uff0c\u5982\u679c\u4f9b\u5e94\u5546\u8ba4\u4e3a\u8fd9\u4e9b\u5b9e\u8df5\u5177\u6709\u98ce\u9669\u6216\u53ef\u80fd\u635f\u5bb3\u5176\u7ecf\u6d4e\u5229\u76ca\uff0c\u8fd9\u4e00\u6311\u6218\u5c06\u66f4\u52a0\u7a81\u51fa\u3002\u6211\u4eec\u7814\u7a76\u4e86\u5173\u7cfb\u6027\u6295\u8d44\u5728\u7f13\u89e3\u8fd9\u4e00\u6311\u6218\u4e2d\u7684\u6709\u6548\u6027\uff0c\u8ba4\u4e3a\u8fd9\u7c7b\u6295\u8d44\u53ef\u4ee5\u4f5c\u4e3a\u4f01\u4e1a\u81f4\u529b\u4e8e\u5171\u540c\u4ef7\u503c\u521b\u9020\u627f\u8bfa\u7684\u4fe1\u53f7\u3002\u5728\u5370\u5ea6\u4e00\u5bb6\u8de8\u56fd\u4f01\u4e1a\u519c\u4e1a\u4f9b\u5e94\u94fe\u7684\u5c0f\u519c\u6237\u519c\u6c11\u4e2d\u8fdb\u884c\u7684\u5b9e\u5730\u5b9e\u9a8c\u4e2d\uff0c\u6211\u4eec\u8003\u5bdf\u4e86\u4e24\u79cd\u5173\u7cfb\u6027\u6295\u8d44\u5bf9\u519c\u6c11\u91c7\u7eb3\u63a8\u8350\u5b9e\u8df5\u7684\u5f71\u54cd\uff0c\u5373\u4e3a\u4f01\u4e1a\u63d0\u4f9b\u4ed6\u4eec\u6240\u91cd\u89c6\u7684\u5b9a\u5236\u5316\u519c\u4e1a\u670d\u52a1\u3002\u7b2c\u4e00\u9879\u5e72\u9884\u4e2d\uff0c\u4f01\u4e1a\u7684\u73b0\u573a\u5de5\u4f5c\u4eba\u5458\u4e3a\u519c\u6c11\u63d0\u4f9b\u4e86\u9488\u5bf9\u4f01\u4e1a\u6240\u91c7\u8d2d\u4f5c\u7269\u7684\u5177\u4f53\u652f\u6301\u3002\u7b2c\u4e8c\u9879\u5e72\u9884\u5219\u8fdb\u4e00\u6b65\u5f15\u5165\u4e86\u4e13\u5bb6\u519c\u5b66\u5bb6\uff0c\u4e3a\u519c\u6c11\u63d0\u4f9b\u66f4\u5e7f\u6cdb\u7684\u519c\u4e1a\u4e8b\u52a1\u652f\u6301\u3002\u4e0e\u4ec5\u63d0\u4f9b\u6709\u5173\u6c14\u5019\u53cb\u597d\u5b9e\u8df5\u57f9\u8bad\u7684\u5bf9\u7167\u7ec4\u76f8\u6bd4\uff0c\u4e24\u9879\u5e72\u9884\u5747\u63d0\u9ad8\u4e86\u519c\u6c11\u91c7\u7eb3\u63a8\u8350\u5b9e\u8df5\u7684\u610f\u613f\u3002\u5176\u4e2d\uff0c\u7b2c\u4e8c\u9879\u5e72\u9884\u5728\u63d0\u5347\u519c\u6c11\u5b9e\u8df5\u91c7\u7eb3\u7387\u4ee5\u53ca\u5176\u4e0e\u4f01\u4e1a\u7684\u7559\u5b58\u7387\u65b9\u9762\u6548\u679c\u66f4\u4e3a\u663e\u8457\u3002\u63a2\u7d22\u6027\u4e2d\u4ecb\u5206\u6790\u548c\u5b9e\u9a8c\u540e\u7684\u5b9e\u5730\u8bbf\u8c08\u8868\u660e\uff0c\u8fd9\u4e9b\u53d1\u73b0\u90e8\u5206\u6e90\u4e8e\u519c\u6c11\u5bf9\u4f01\u4e1a\u5173\u7cfb\u6027\u6295\u8d44\u7684\u79ef\u6781\u611f\u77e5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1287/mnsc.2024.07052", "journal": "MS", "title": "Multidimensional Signaling with Supplier Credit Guarantees", "authors": ["Huihui Liu", "Haotian Song", "Wenqiang Xiao"], "author_details": [{"name": "Huihui Liu", "affiliations": ["School of Economics and Management, Beihang University, Beijing 100191, China"]}, {"name": "Haotian Song", "affiliations": ["School of Management, Zhejiang University, Hangzhou 310058, China"]}, {"name": "Wenqiang Xiao", "affiliations": ["Stern School of Business, New York University, New York, New York 10012"]}], "abstract": "This paper investigates credit guarantees in a supply chain setting involving a supplier, a capital-constrained buyer, and a bank. We find that under complete information, credit guarantees increase order quantities but paradoxically raise wholesale prices, overall rendering the credit guarantee not useful for improving the operational efficiency. However, under information asymmetry, either a partial or full guarantee emerges in equilibrium, with the wholesale price maintained at its optimal full-information level. This underscores the pivotal role of credit guarantees in effective signaling and delineates the distinct functions of the wholesale price and the guarantee\u2014the former on operational efficiency and the latter on signaling efficacy. Further comparative analysis of the supplier and buyer performances under the two contract types reveals that credit guarantees do not always benefit both parties.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07052", "title_zh": "\u4f9b\u5e94\u5546\u4fe1\u7528\u62c5\u4fdd\u7684\u591a\u7ef4\u4fe1\u53f7\u4f20\u9012", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u4f9b\u5e94\u94fe\u73af\u5883\u4e2d\u4f9b\u5e94\u5546\u3001\u8d44\u672c\u53d7\u9650\u7684\u4e70\u5bb6\u548c\u94f6\u884c\u4e4b\u95f4\u4fe1\u7528\u62c5\u4fdd\u7684\u4f5c\u7528\u3002\u5728\u5b8c\u5168\u4fe1\u606f\u60c5\u51b5\u4e0b\uff0c\u4fe1\u7528\u62c5\u4fdd\u4f1a\u589e\u52a0\u8ba2\u5355\u91cf\uff0c\u4f46\u51fa\u4eba\u610f\u6599\u5730\u63d0\u9ad8\u6279\u53d1\u4ef7\u683c\uff0c\u603b\u4f53\u4e0a\u4f7f\u5f97\u4fe1\u7528\u62c5\u4fdd\u65e0\u6cd5\u63d0\u5347\u8fd0\u8425\u6548\u7387\u3002\u7136\u800c\uff0c\u5728\u4fe1\u606f\u4e0d\u5bf9\u79f0\u60c5\u51b5\u4e0b\uff0c\u65e0\u8bba\u662f\u90e8\u5206\u62c5\u4fdd\u8fd8\u662f\u5168\u989d\u62c5\u4fdd\u90fd\u4f1a\u5728\u5747\u8861\u4e2d\u51fa\u73b0\uff0c\u4e14\u6279\u53d1\u4ef7\u683c\u7ef4\u6301\u5728\u5b8c\u5168\u4fe1\u606f\u4e0b\u7684\u6700\u4f18\u6c34\u5e73\u3002\u8fd9\u51f8\u663e\u4e86\u4fe1\u7528\u62c5\u4fdd\u5728\u6709\u6548\u4fe1\u53f7\u4f20\u9012\u4e2d\u7684\u5173\u952e\u4f5c\u7528\uff0c\u5e76\u9610\u660e\u4e86\u6279\u53d1\u4ef7\u683c\u548c\u62c5\u4fdd\u5728\u529f\u80fd\u4e0a\u7684\u533a\u522b\u2014\u2014\u524d\u8005\u5f71\u54cd\u8fd0\u8425\u6548\u7387\uff0c\u540e\u8005\u5219\u5f71\u54cd\u4fe1\u53f7\u4f20\u9012\u7684\u6709\u6548\u6027\u3002\u8fdb\u4e00\u6b65\u5bf9\u4e24\u79cd\u5408\u540c\u7c7b\u578b\u4e0b\u4f9b\u5e94\u5546\u548c\u4e70\u5bb6\u8868\u73b0\u7684\u6bd4\u8f83\u5206\u6790\u8868\u660e\uff0c\u4fe1\u7528\u62c5\u4fdd\u5e76\u4e0d\u603b\u662f\u5bf9\u53cc\u65b9\u90fd\u6709\u5229\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1287/mnsc.2022.03573", "journal": "MS", "title": "Chasing Market Growth and Matching Performance in Two-Sided Platforms: Evidence from the Lazy-Minting Policy in an NFT Marketplace", "authors": ["Hong Zhang", "Hongchang Wang", "Amit Mehra", "Zhiqiang (Eric) Zheng"], "author_details": [{"name": "Hong Zhang", "affiliations": ["Department of Management Information Systems, Eller College of Management, University of Arizona, Tucson, Arizona 85721; and Center for the Management of Information, Eller College of Management, University of Arizona, Tucson, Arizona 85721"]}, {"name": "Hongchang Wang", "affiliations": ["Department of Information Systems, Naveen Jindal School of Management, University of Texas at Dallas, Richardson, Texas 75080"]}, {"name": "Amit Mehra", "affiliations": ["Department of Information Systems, Naveen Jindal School of Management, University of Texas at Dallas, Richardson, Texas 75080"]}, {"name": "Zhiqiang (Eric) Zheng", "affiliations": ["Department of Information Systems, Naveen Jindal School of Management, University of Texas at Dallas, Richardson, Texas 75080"]}], "abstract": "A common challenge faced by two-sided marketplaces is to expand the market while ensuring satisfactory matching of the two sides. We study a new platform growth strategy that increases market thickness with free entry while allowing suppliers to discretionarily signal product quality to buyers, thus forming a tiered market structure that maintains matching performance. We consider such an example with nonfungible token (NFT) markets where suppliers could choose to delay the entry cost of the NFT creation fee until an NFT is sold (lazy minting) or pay the fee up front at the time of NFT creation (gas minting). We use the difference-in-differences strategy to identify the impact of this lazy-minting policy on market matching performance. We find that the impacts of this policy are multifaceted: Although the introduction of lazy minting reduces the average matching likelihood of an NFT by 98.2%, it increases the gas-minting segment\u2019s matching likelihood by 112.3% and first-sale price by 126.5%. Overall, this new growth strategy benefits the platform because of increased total sales and higher revenues. We unravel two mechanisms: the market thickness effect and the quality signaling effect. For the latter, we introduce a systematic framework to empirically establish the quality signaling mechanism with a separating equilibrium, where suppliers prefer gas minting for their high-quality creations. This effectively sends a quality signal that buyers could rely on to recognize high-quality NFTs. This new platform growth strategy provides generic implications for platforms endeavoring to balance market thickness and matching performance.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2022.03573", "topics": ["\u7f51\u7edc"], "title_zh": "\u8ffd\u9010\u5e02\u573a\u589e\u957f\u4e0e\u5339\u914d\u6027\u80fd\u7684\u53cc\u4fa7\u5e73\u53f0\uff1a\u6765\u81eaNFT\u5e02\u573a\u201c\u61d2\u94f8\u9020\u201d\u653f\u7b56\u7684\u8bc1\u636e", "abstract_zh": "\u53cc\u4fa7\u5e02\u573a\u5e73\u53f0\u9762\u4e34\u7684\u4e00\u4e2a\u5e38\u89c1\u6311\u6218\u662f\u5728\u6269\u5927\u5e02\u573a\u7684\u540c\u65f6\u786e\u4fdd\u53cc\u65b9\u7684\u6709\u6548\u5339\u914d\u3002\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u79cd\u65b0\u7684\u5e73\u53f0\u589e\u957f\u7b56\u7565\uff0c\u901a\u8fc7\u514d\u8d39\u51c6\u5165\u6765\u589e\u52a0\u5e02\u573a\u6df1\u5ea6\uff0c\u540c\u65f6\u5141\u8bb8\u4f9b\u5e94\u5546\u81ea\u4e3b\u9009\u62e9\u5411\u4e70\u5bb6\u4f20\u8fbe\u4ea7\u54c1\u54c1\u8d28\u7684\u65b9\u5f0f\uff0c\u4ece\u800c\u5f62\u6210\u5206\u5c42\u5e02\u573a\u7ed3\u6784\uff0c\u7ef4\u6301\u5339\u914d\u6027\u80fd\u3002\u6211\u4eec\u4ee5\u975e\u540c\u8d28\u5316\u4ee3\u5e01\uff08NFT\uff09\u5e02\u573a\u4e3a\u4f8b\uff0c\u5176\u4e2d\u4f9b\u5e94\u5546\u53ef\u4ee5\u9009\u62e9\u5ef6\u8fdf\u652f\u4ed8NFT\u521b\u5efa\u8d39\u7528\uff0c\u76f4\u5230NFT\u552e\u51fa\uff08\u61d2\u94f8\u9020\uff09\uff0c\u6216\u5728\u521b\u5efaNFT\u65f6\u7acb\u5373\u652f\u4ed8\u8d39\u7528\uff08\u6c14\u94f8\u9020\uff09\u3002\u6211\u4eec\u91c7\u7528\u5dee\u5206\u5dee\u5206\u6cd5\u6765\u8bc6\u522b\u8be5\u61d2\u94f8\u9020\u653f\u7b56\u5bf9\u5e02\u573a\u5339\u914d\u6027\u80fd\u7684\u5f71\u54cd\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u8be5\u653f\u7b56\u7684\u5f71\u54cd\u662f\u591a\u65b9\u9762\u7684\uff1a\u5c3d\u7ba1\u61d2\u94f8\u9020\u7684\u5f15\u5165\u4f7fNFT\u7684\u5e73\u5747\u5339\u914d\u6982\u7387\u4e0b\u964d\u4e8698.2%\uff0c\u4f46\u5176\u63d0\u5347\u4e86\u6c14\u94f8\u9020\u7ec4\u7684\u5339\u914d\u6982\u7387112.3%\u4ee5\u53ca\u9996\u6b21\u9500\u552e\u4ef7\u683c126.5%\u3002\u603b\u4f53\u800c\u8a00\uff0c\u8fd9\u79cd\u65b0\u589e\u957f\u7b56\u7565\u7531\u4e8e\u603b\u9500\u552e\u989d\u589e\u52a0\u548c\u6536\u5165\u63d0\u5347\uff0c\u5bf9\u5e73\u53f0\u6709\u5229\u3002\u6211\u4eec\u63ed\u793a\u4e86\u4e24\u79cd\u673a\u5236\uff1a\u5e02\u573a\u6df1\u5ea6\u6548\u5e94\u548c\u54c1\u8d28\u4fe1\u53f7\u6548\u5e94\u3002\u5bf9\u4e8e\u540e\u8005\uff0c\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u5957\u7cfb\u7edf\u6027\u7684\u6846\u67b6\uff0c\u901a\u8fc7\u5206\u79bb\u5747\u8861\u6765\u5b9e\u8bc1\u9a8c\u8bc1\u54c1\u8d28\u4fe1\u53f7\u673a\u5236\uff0c\u5373\u4f9b\u5e94\u5546\u503e\u5411\u4e8e\u4e3a\u9ad8\u8d28\u91cf\u521b\u4f5c\u9009\u62e9\u6c14\u94f8\u9020\uff0c\u4ece\u800c\u5411\u4e70\u5bb6\u4f20\u9012\u53ef\u4fe1\u8d56\u7684\u9ad8\u8d28\u91cfNFT\u4fe1\u53f7\u3002\u8fd9\u79cd\u65b0\u7684\u5e73\u53f0\u589e\u957f\u7b56\u7565\u4e3a\u81f4\u529b\u4e8e\u5e73\u8861\u5e02\u573a\u6df1\u5ea6\u4e0e\u5339\u914d\u6027\u80fd\u7684\u5e73\u53f0\u63d0\u4f9b\u4e86\u666e\u904d\u6027\u542f\u793a\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1287/mnsc.2023.03118", "journal": "MS", "title": "Optimal Tax Timing with Transaction Costs", "authors": ["Min Dai", "Yaoting Lei", "Hong Liu", "Chen Yang"], "author_details": [{"name": "Min Dai", "affiliations": ["Department of Applied Mathematics at the Faculty of Computer and Mathematical Sciences, The Hong Kong Polytechnic University, Hong Kong SAR, China; and School of Accounting and Finance at the Faculty of Business, The Hong Kong Polytechnic University, Hong Kong SAR, China"]}, {"name": "Yaoting Lei", "affiliations": ["School of Economics and Management, Nanchang University, Nanchang 330031, China"]}, {"name": "Hong Liu", "affiliations": ["Olin Business School, Washington University in St. Louis, St. Louis, Missouri 63130; and Fudan International School of Finance, Fudan University, Shanghai 200433, China"]}, {"name": "Chen Yang", "affiliations": ["Department of Systems Engineering and Engineering Management, The Chinese University of Hong Kong, Hong Kong SAR, China"]}], "abstract": "We develop a dynamic portfolio model incorporating capital gains tax (CGT), transaction costs, and year-end taxation. We find that even tiny transaction costs can lead to significant deferral of large losses and that transaction costs affect loss deferrals much more than gain deferrals. Our model can thus help explain the puzzle that even when investors face equal long-term/short-term CGT rates, they may still defer realizing large capital losses for an extended period of time, displaying the disposition effect. In addition, we find that misestimating transaction costs is costly. We also provide several unique, empirically testable predictions and shed light on recently proposed tax policy changes.", "date": "2026-10", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-10-05T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.03118", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"], "title_zh": "\u8003\u8651\u4ea4\u6613\u6210\u672c\u7684\u6700\u4f18\u7a0e\u6536\u65f6\u673a", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u52a8\u6001\u6295\u8d44\u7ec4\u5408\u6a21\u578b\uff0c\u7eb3\u5165\u4e86\u8d44\u672c\u5229\u5f97\u7a0e\uff08CGT\uff09\u3001\u4ea4\u6613\u6210\u672c\u4ee5\u53ca\u5e74\u672b\u5f81\u7a0e\u56e0\u7d20\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5373\u4f7f\u4ea4\u6613\u6210\u672c\u6781\u5c0f\uff0c\u4e5f\u53ef\u80fd\u5bfc\u81f4\u5927\u989d\u4e8f\u635f\u7684\u663e\u8457\u5ef6\u8fdf\uff0c\u4e14\u4ea4\u6613\u6210\u672c\u5bf9\u4e8f\u635f\u5ef6\u8fdf\u7684\u5f71\u54cd\u8fdc\u5927\u4e8e\u5bf9\u6536\u76ca\u5ef6\u8fdf\u7684\u5f71\u54cd\u3002\u56e0\u6b64\uff0c\u8be5\u6a21\u578b\u6709\u52a9\u4e8e\u89e3\u91ca\u4e00\u4e2a\u73b0\u8c61\uff1a\u5373\u4f7f\u6295\u8d44\u8005\u9762\u4e34\u76f8\u540c\u7684\u957f\u671f/\u77ed\u671f\u8d44\u672c\u5229\u5f97\u7a0e\u7387\uff0c\u4ed6\u4eec\u4ecd\u53ef\u80fd\u5c06\u5927\u989d\u8d44\u672c\u4e8f\u635f\u7684\u5b9e\u73b0\u63a8\u8fdf\u5f88\u957f\u65f6\u95f4\uff0c\u8868\u73b0\u51fa\u5904\u7f6e\u6548\u5e94\u3002\u6b64\u5916\uff0c\u6211\u4eec\u53d1\u73b0\u5bf9\u4ea4\u6613\u6210\u672c\u7684\u8bef\u4f30\u4f1a\u9020\u6210\u91cd\u5927\u635f\u5931\u3002\u6211\u4eec\u8fd8\u63d0\u51fa\u4e86\u82e5\u5e72\u72ec\u7279\u4e14\u53ef\u88ab\u5b9e\u8bc1\u68c0\u9a8c\u7684\u9884\u6d4b\uff0c\u5e76\u4e3a\u6700\u8fd1\u63d0\u51fa\u7684\u7a0e\u6536\u653f\u7b56\u8c03\u6574\u63d0\u4f9b\u4e86\u89c1\u89e3\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.1093/restud/rdag104", "journal": "REStud", "title": "Monetary Policy Invariance, Hysteresis, and Optimal Inflation", "authors": ["Mirko Abbritti", "Agostino Consolo", "Sebastian Weber"], "author_details": [{"name": "Mirko Abbritti", "affiliations": ["University of Navarra, Spain and University of Perugia ,"]}, {"name": "Agostino Consolo", "affiliations": ["European Central Bank ,"]}, {"name": "Sebastian Weber", "affiliations": ["International Monetary Fund , USA"]}], "abstract": "Abstract Standard New Keynesian (NK) models feature an optimal inflation target well below 2%, limited welfare losses from business cycle fluctuations and long-term monetary neutrality. We develop an NK framework with endogenous productivity and downward nominal wage rigidity (DNWR) which challenges these results. The interaction between endogenous growth and DNWR generates asymmetric hysteresis effects on unemployment and R&D. As a consequence, the model features a nonvertical long-run Phillips curve and a trade-off between price distortions and output hysteresis that changes the welfare-maximizing inflation rate to above 2%. Deviations from the optimal target carry welfare costs multiple times those in traditional NK models. Taylor rules that respond to the unemployment rate address more effectively the asymmetric hysteresis in our model. Results are robust to the inclusion of the effective lower bound on interest rates.", "date": "2026-09-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-30T22:00:02+00:00", "url": "https://doi.org/10.1093/restud/rdag104", "title_zh": "\u8d27\u5e01\u653f\u7b56\u4e0d\u53d8\u6027\u3001\u6ede\u540e\u6548\u5e94\u4e0e\u6700\u4f18\u901a\u80c0", "abstract_zh": "\u6807\u51c6\u7684\u65b0\u51ef\u6069\u65af\uff08NK\uff09\u6a21\u578b\u5177\u6709\u4e00\u4e2a\u8fdc\u4f4e\u4e8e2%\u7684\u6700\u4f18\u901a\u80c0\u7387\uff0c\u5bf9\u4f01\u4e1a\u5468\u671f\u6ce2\u52a8\u7684\u798f\u5229\u635f\u5931\u6709\u9650\uff0c\u4e14\u957f\u671f\u8d27\u5e01\u4e2d\u6027\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5177\u6709\u5185\u751f\u751f\u4ea7\u7387\u548c\u5411\u4e0b\u540d\u4e49\u5de5\u8d44\u521a\u6027\uff08DNWR\uff09\u7684\u65b0\u51ef\u6069\u65af\u6846\u67b6\uff0c\u8be5\u6846\u67b6\u6311\u6218\u4e86\u8fd9\u4e9b\u7ed3\u8bba\u3002\u5185\u751f\u589e\u957f\u4e0e\u5411\u4e0b\u540d\u4e49\u5de5\u8d44\u521a\u6027\u4e4b\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\u5bfc\u81f4\u5931\u4e1a\u7387\u548c\u7814\u53d1\u6d3b\u52a8\u7684\u975e\u5bf9\u79f0\u6ede\u540e\u6548\u5e94\u3002\u56e0\u6b64\uff0c\u8be5\u6a21\u578b\u5448\u73b0\u51fa\u975e\u5782\u76f4\u7684\u957f\u671f\u83f2\u5229\u666e\u65af\u66f2\u7ebf\uff0c\u5e76\u5728\u4ef7\u683c\u626d\u66f2\u4e0e\u4ea7\u51fa\u6ede\u540e\u4e4b\u95f4\u5b58\u5728\u6743\u8861\uff0c\u4ece\u800c\u5c06\u798f\u5229\u6700\u5927\u5316\u65f6\u7684\u901a\u80c0\u7387\u63d0\u5347\u81f32%\u4ee5\u4e0a\u3002\u504f\u79bb\u6700\u4f18\u76ee\u6807\u7684\u901a\u80c0\u4f1a\u5e26\u6765\u4f20\u7edf\u65b0\u51ef\u6069\u65af\u6a21\u578b\u4e2d\u591a\u500d\u7684\u798f\u5229\u635f\u5931\u3002\u9488\u5bf9\u5931\u4e1a\u7387\u7684\u6cf0\u52d2\u89c4\u5219\u5728\u672c\u6a21\u578b\u4e2d\u66f4\u6709\u6548\u5730\u5e94\u5bf9\u4e86\u975e\u5bf9\u79f0\u6ede\u540e\u6548\u5e94\u3002\u7ed3\u679c\u5728\u5305\u542b\u5229\u7387\u4e0b\u9650\u6709\u6548\u8fb9\u754c\u7684\u60c5\u51b5\u4e0b\u4f9d\u7136\u7a33\u5065\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70091", "journal": "JF", "title": "Supranational Banking Supervision, Credit Supply, and Risk\u2010Taking: European Evidence from Multi\u2010Country Credit Registers", "authors": ["CARLO ALTAVILLA", "MIGUEL BOUCINHA", "MARTINA JASOVA", "JOS\u00c9\u2010LUIS PEYDR\u00d3", "FRANK SMETS"], "author_details": [{"name": "CARLO ALTAVILLA", "affiliations": []}, {"name": "MIGUEL BOUCINHA", "affiliations": []}, {"name": "MARTINA JASOVA", "affiliations": []}, {"name": "JOS\u00c9\u2010LUIS PEYDR\u00d3", "affiliations": []}, {"name": "FRANK SMETS", "affiliations": []}], "abstract": "ABSTRACT Using a novel data set of multi\u2010country credit registers and an institutional change from national to supranational supervision, we show that supranational banking supervision can increase credit supply while mitigating excessive risk\u2010taking. Supranational supervision increases credit supply only in financially stressed countries while reducing the credit supply to the riskiest (zombie) firms. These improved lending effects stem from weaker national institutions, differential national supervisory incentives, lower national supervisory abilities, and weaker national insolvency laws. Moreover, improved access to external finance from wholesale and bond markets as well as lower risk\u2010weighted assets allow supranationally supervised banks to expand the supply of credit. Overall, despite some supranational supervisory arbitrage, supranational supervision decreases firm\u2010level credit to the riskiest firms while increasing firm\u2010level credit availability in stressed countries without reducing it in nonstressed countries.", "date": "2026-09-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-30T22:00:02+00:00", "url": "https://doi.org/10.1111/jofi.70091", "title_zh": "\u8de8\u56fd\u94f6\u884c\u76d1\u7ba1\u3001\u4fe1\u8d37\u4f9b\u7ed9\u4e0e\u98ce\u9669\u627f\u62c5\uff1a\u6765\u81ea\u591a\u56fd\u4fe1\u8d37\u767b\u8bb0\u7684\u6b27\u6d32\u8bc1\u636e", "abstract_zh": "\u4f7f\u7528\u4e00\u4e2a\u5305\u542b\u591a\u56fd\u4fe1\u8d37\u767b\u8bb0\u7684\u65b0\u578b\u6570\u636e\u96c6\uff0c\u4ee5\u53ca\u4ece\u56fd\u5bb6\u76d1\u7ba1\u5411\u8de8\u56fd\u76d1\u7ba1\u8f6c\u53d8\u7684\u5236\u5ea6\u53d8\u5316\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u8de8\u56fd\u94f6\u884c\u76d1\u7ba1\u53ef\u4ee5\u5728\u589e\u52a0\u4fe1\u8d37\u4f9b\u7ed9\u7684\u540c\u65f6\u6291\u5236\u8fc7\u5ea6\u98ce\u9669\u627f\u62c5\u3002\u8de8\u56fd\u76d1\u7ba1\u4ec5\u5728\u91d1\u878d\u538b\u529b\u8f83\u5927\u7684\u56fd\u5bb6\u589e\u52a0\u4fe1\u8d37\u4f9b\u7ed9\uff0c\u540c\u65f6\u51cf\u5c11\u5bf9\u6700\u5371\u9669\uff08\u50f5\u5c38\uff09\u4f01\u4e1a\u7684\u4fe1\u8d37\u4f9b\u7ed9\u3002\u8fd9\u4e9b\u4fe1\u8d37\u4f9b\u7ed9\u6539\u5584\u7684\u6548\u679c\u6e90\u4e8e\u56fd\u5bb6\u673a\u6784\u8584\u5f31\u3001\u5404\u56fd\u76d1\u7ba1\u6fc0\u52b1\u7684\u5dee\u5f02\u3001\u56fd\u5bb6\u76d1\u7ba1\u80fd\u529b\u8f83\u4f4e\u4ee5\u53ca\u56fd\u5bb6\u7834\u4ea7\u6cd5\u6548\u529b\u8f83\u5f31\u3002\u6b64\u5916\uff0c\u8de8\u56fd\u76d1\u7ba1\u94f6\u884c\u901a\u8fc7\u83b7\u5f97\u6279\u53d1\u548c\u503a\u5238\u5e02\u573a\u7684\u5916\u90e8\u878d\u8d44\u4ee5\u53ca\u964d\u4f4e\u98ce\u9669\u52a0\u6743\u8d44\u4ea7\uff0c\u80fd\u591f\u6269\u5927\u4fe1\u8d37\u4f9b\u7ed9\u3002\u603b\u4f53\u800c\u8a00\uff0c\u5c3d\u7ba1\u5b58\u5728\u4e00\u5b9a\u7a0b\u5ea6\u7684\u8de8\u56fd\u76d1\u7ba1\u5957\u5229\uff0c\u8de8\u56fd\u76d1\u7ba1\u5728\u51cf\u5c11\u5bf9\u6700\u5371\u9669\u4f01\u4e1a\u7684\u4f01\u4e1a\u7ea7\u4fe1\u8d37\u4f9b\u7ed9\u7684\u540c\u65f6\uff0c\u63d0\u9ad8\u4e86\u91d1\u878d\u538b\u529b\u56fd\u5bb6\u7684\u4fe1\u8d37\u53ef\u83b7\u5f97\u6027\uff0c\u800c\u5e76\u672a\u51cf\u5c11\u975e\u538b\u529b\u56fd\u5bb6\u7684\u4fe1\u8d37\u4f9b\u7ed9\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1111/jofi.70087", "journal": "JF", "title": "Mind the App: Mobile Access to Financial Information and Consumer Behavior", "authors": ["YARON LEVI", "SHLOMO BENARTZI"], "author_details": [{"name": "YARON LEVI", "affiliations": []}, {"name": "SHLOMO BENARTZI", "affiliations": []}], "abstract": "ABSTRACT We study whether easier monitoring of personal finances affects consumer spending. We use transaction data from an account aggregation company to study consumers who installed the mobile app after using the same service on a personal computer for several months. We utilize the staggered release of the apps on different devices (iPhone, iPad, and Android) to identify a causal effect conditional on adoption of the mobile app. Consumers decrease their discretionary spending following the installation of the mobile app. The decrease is larger during evening hours and among individuals with lower proxies of self\u2010control, patterns consistent with a monitoring/self\u2010regulation channel and with benchmark models of costly self\u2010control.", "date": "2026-09-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-30T22:00:02+00:00", "url": "https://doi.org/10.1111/jofi.70087", "title_zh": "\u6ce8\u610f\u5e94\u7528\uff1a\u79fb\u52a8\u91d1\u878d\u4fe1\u606f\u8bbf\u95ee\u4e0e\u6d88\u8d39\u8005\u884c\u4e3a", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u4e2a\u4eba\u8d22\u52a1\u66f4\u6613\u76d1\u63a7\u662f\u5426\u4f1a\u5f71\u54cd\u6d88\u8d39\u8005\u7684\u652f\u51fa\u884c\u4e3a\u3002\u6211\u4eec\u5229\u7528\u4e00\u5bb6\u8d26\u6237\u805a\u5408\u516c\u53f8\u7684\u4ea4\u6613\u6570\u636e\uff0c\u7814\u7a76\u90a3\u4e9b\u5728\u4f7f\u7528\u4e2a\u4eba\u7535\u8111\u670d\u52a1\u6570\u6708\u540e\u5b89\u88c5\u4e86\u79fb\u52a8\u5e94\u7528\u7684\u6d88\u8d39\u8005\u3002\u6211\u4eec\u5229\u7528\u79fb\u52a8\u5e94\u7528\u5728\u4e0d\u540c\u8bbe\u5907\uff08iPhone\u3001iPad \u548c Android\uff09\u4e0a\u5206\u9636\u6bb5\u53d1\u5e03\u7684\u7279\u6027\uff0c\u6765\u8bc6\u522b\u5728\u91c7\u7528\u79fb\u52a8\u5e94\u7528\u6761\u4ef6\u4e0b\u7684\u4e00\u79cd\u56e0\u679c\u6548\u5e94\u3002\u6d88\u8d39\u8005\u5728\u5b89\u88c5\u79fb\u52a8\u5e94\u7528\u540e\u51cf\u5c11\u4e86\u975e\u5fc5\u8981\u652f\u51fa\u3002\u8fd9\u79cd\u51cf\u5c11\u5728\u665a\u95f4\u65f6\u6bb5\u66f4\u4e3a\u663e\u8457\uff0c\u4e14\u5728\u81ea\u6211\u63a7\u5236\u80fd\u529b\u8f83\u4f4e\u7684\u4e2a\u4f53\u4e2d\u66f4\u4e3a\u660e\u663e\uff0c\u8fd9\u4e0e\u76d1\u63a7/\u81ea\u6211\u8c03\u8282\u673a\u5236\u4ee5\u53ca\u6210\u672c\u81ea\u63a7\u7684\u57fa\u51c6\u6a21\u578b\u9884\u6d4b\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70092", "journal": "JF", "title": "The Real Channel for Nominal Bond\u2010Stock Puzzles", "authors": ["MIKHAIL CHERNOV", "LARS A. LOCHSTOER", "DONGHO SONG"], "author_details": [{"name": "MIKHAIL CHERNOV", "affiliations": []}, {"name": "LARS A. LOCHSTOER", "affiliations": []}, {"name": "DONGHO SONG", "affiliations": []}], "abstract": "ABSTRACT We document that the nature of aggregate consumption dynamics changes when the bond\u2010stock correlation switches sign. We identify three regimes in a real\u2010time, sequential learning framework: two highly persistent regimes where permanent or transitory consumption shocks are more dominant, and a largely transitory disaster regime. We study the implications for asset prices. The transition from the second to the first regime in the late 1990s makes the correlation between equities and real bonds switch from positive to negative as in the data, providing an explanation from the perspective of real consumption dynamics. The findings extend to the international setting.", "date": "2026-09-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-30T22:00:02+00:00", "url": "https://doi.org/10.1111/jofi.70092", "title_zh": "\u540d\u4e49\u503a\u5238-\u80a1\u7968\u4e4b\u8c1c\u7684\u73b0\u5b9e\u6e20\u9053", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u53d1\u73b0\uff0c\u5f53\u503a\u5238\u4e0e\u80a1\u7968\u7684\u76f8\u5173\u6027\u6539\u53d8\u7b26\u53f7\u65f6\uff0c\u6574\u4f53\u6d88\u8d39\u52a8\u6001\u7684\u6027\u8d28\u4e5f\u968f\u4e4b\u53d1\u751f\u53d8\u5316\u3002\u6211\u4eec\u5728\u4e00\u4e2a\u5b9e\u65f6\u3001\u987a\u5e8f\u5b66\u4e60\u6846\u67b6\u4e2d\u8bc6\u522b\u51fa\u4e09\u4e2a\u9636\u6bb5\uff1a\u4e24\u4e2a\u9ad8\u5ea6\u6301\u4e45\u7684\u9636\u6bb5\uff0c\u5176\u4e2d\u6c38\u4e45\u6027\u6216\u6682\u65f6\u6027\u7684\u6d88\u8d39\u51b2\u51fb\u5360\u4e3b\u5bfc\u5730\u4f4d\uff0c\u4ee5\u53ca\u4e00\u4e2a\u4e3b\u8981\u7531\u6682\u65f6\u6027\u707e\u96be\u6784\u6210\u7684\u9636\u6bb5\u3002\u6211\u4eec\u7814\u7a76\u4e86\u8fd9\u4e9b\u53d1\u73b0\u5bf9\u8d44\u4ea7\u4ef7\u683c\u7684\u5f71\u54cd\u300220\u4e16\u7eaa90\u5e74\u4ee3\u672b\u4ece\u7b2c\u4e8c\u9636\u6bb5\u5411\u7b2c\u4e00\u9636\u6bb5\u7684\u8f6c\u53d8\uff0c\u4f7f\u5f97\u80a1\u7968\u4e0e\u5b9e\u9645\u503a\u5238\u4e4b\u95f4\u7684\u76f8\u5173\u6027\u4ece\u6b63\u53d8\u8d1f\uff0c\u4e0e\u6570\u636e\u4e00\u81f4\uff0c\u8fd9\u4ece\u73b0\u5b9e\u6d88\u8d39\u52a8\u6001\u7684\u89d2\u5ea6\u63d0\u4f9b\u4e86\u89e3\u91ca\u3002\u8fd9\u4e9b\u53d1\u73b0\u4e5f\u9002\u7528\u4e8e\u56fd\u9645\u73af\u5883\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1017/s0022109026103354", "journal": "JFQA", "title": "How Does Domestic Competition Affect Firms\u2019 Foreign Market Expansion?", "authors": ["Tiago Loncan", "Philip Valta"], "author_details": [{"name": "Tiago Loncan", "affiliations": ["King\u2019s College London King\u2019s Business School"]}, {"name": "Philip Valta", "affiliations": ["University of Bern Institute for Financial Management"]}], "abstract": "Abstract We examine how domestic product market competition shapes firms\u2019 foreign market expansion. Using a panel of U.S. public firms from 1997 to 2017 and text-based measures of output offshoring, we show that stronger domestic competition increases foreign sales activity. To address endogeneity concerns, we exploit the competitive effects of policy-induced variation from staggered rejections of the Inevitable Disclosure Doctrine. Further tests indicate that these labor mobility shocks that intensify competitive pressure spur foreign expansion primarily among firms with stronger intangible and organizational capabilities and higher profitability. The findings suggest that domestic competition is an important driver of foreign market expansion.", "date": "2026-09-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-30T22:00:02+00:00", "url": "https://doi.org/10.1017/s0022109026103354", "title_zh": "\u56fd\u5185\u7ade\u4e89\u5982\u4f55\u5f71\u54cd\u4f01\u4e1a\u7684\u6d77\u5916\u5e02\u573a\u6269\u5f20\uff1f", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u56fd\u5185\u4ea7\u54c1\u5e02\u573a\u7ade\u4e89\u5982\u4f55\u5f71\u54cd\u4f01\u4e1a\u7684\u6d77\u5916\u5e02\u573a\u6269\u5f20\u3002\u5229\u75281997\u5e74\u81f32017\u5e74\u7f8e\u56fd\u4e0a\u5e02\u516c\u53f8\u9762\u677f\u6570\u636e\u4ee5\u53ca\u57fa\u4e8e\u6587\u672c\u7684\u4ea7\u51fa\u5916\u5305\u6d4b\u91cf\u6307\u6807\uff0c\u6211\u4eec\u53d1\u73b0\u56fd\u5185\u7ade\u4e89\u8d8a\u6fc0\u70c8\uff0c\u4f01\u4e1a\u7684\u6d77\u5916\u9500\u552e\u6d3b\u52a8\u4e5f\u8d8a\u591a\u3002\u4e3a\u89e3\u51b3\u5185\u751f\u6027\u95ee\u9898\uff0c\u6211\u4eec\u5229\u7528\u653f\u7b56\u5f15\u53d1\u7684\u3001\u5206\u9636\u6bb5\u62d2\u7edd\u2018\u4e0d\u53ef\u907f\u514d\u62ab\u9732\u539f\u5219\u2019\u6240\u4ea7\u751f\u7684\u7ade\u4e89\u6548\u5e94\u8fdb\u884c\u5206\u6790\u3002\u8fdb\u4e00\u6b65\u7684\u68c0\u9a8c\u8868\u660e\uff0c\u8fd9\u4e9b\u52b3\u52a8\u529b\u6d41\u52a8\u6027\u51b2\u51fb\u52a0\u5267\u4e86\u5e02\u573a\u7ade\u4e89\uff0c\u4e3b\u8981\u63a8\u52a8\u5177\u5907\u66f4\u5f3a\u65e0\u5f62\u8d44\u4ea7\u548c\u7ec4\u7ec7\u80fd\u529b\u4ee5\u53ca\u66f4\u9ad8\u76c8\u5229\u80fd\u529b\u7684\u4f01\u4e1a\u8fdb\u884c\u6d77\u5916\u6269\u5f20\u3002\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u56fd\u5185\u7ade\u4e89\u662f\u63a8\u52a8\u4f01\u4e1a\u6d77\u5916\u5e02\u573a\u6269\u5f20\u7684\u91cd\u8981\u56e0\u7d20\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.01668", "journal": "MS", "title": "Constant Regret Primal-Dual Policy for Multiway Dynamic Matching", "authors": ["Yehua Wei", "Jiaming Xu", "Sophie H. Yu"], "author_details": [{"name": "Yehua Wei", "affiliations": ["The Fuqua School of Business, Duke University, Durham, North Carolina 27708"]}, {"name": "Jiaming Xu", "affiliations": ["The Fuqua School of Business, Duke University, Durham, North Carolina 27708"]}, {"name": "Sophie H. Yu", "affiliations": ["The Wharton School of the University of Pennsylvania, Philadelphia, Pennsylvania 19104"]}], "abstract": "We study a discrete-time dynamic multiway matching model. There are finitely many agent types that arrive stochastically and wait to be matched. State-of-the-art dynamic matching policies in the literature require the knowledge of all system parameters to determine an optimal basis of the fluid relaxation, and focus on controlling the number of waiting agents using only matches within the optimal basis. In this paper, we propose a primal-dual policy that schedules matches for future arrivals based on an estimator for the dual solution. Our policy does not require the knowledge of the arrival rates and operates with greater flexibility as it does not restrict matches to only the match types within an optimal basis. We show that our policy is the first to achieve constant regret at all times under unknown arrival rates, and when the arrival rates are known, it achieves the optimal scaling. Furthermore, when the arrival rates are known, the primal-dual policy significantly outperforms alternative dynamic matching policies in several numerical simulations.", "date": "2026-09-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-30T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2023.01668", "title_zh": "\u57fa\u4e8e\u5bf9\u5076\u89e3\u4f30\u8ba1\u7684\u591a\u8def\u5f84\u52a8\u6001\u5339\u914d\u5e38\u540e\u6094\u7b56\u7565", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u79cd\u79bb\u6563\u65f6\u95f4\u52a8\u6001\u591a\u8def\u5f84\u5339\u914d\u6a21\u578b\u3002\u73b0\u6709\u6587\u732e\u4e2d\u7684\u5148\u8fdb\u52a8\u6001\u5339\u914d\u7b56\u7565\u9700\u8981\u4e86\u89e3\u6240\u6709\u7cfb\u7edf\u53c2\u6570\uff0c\u4ee5\u786e\u5b9a\u6d41\u677e\u5f1b\u7684\u6700\u4f18\u57fa\u7840\uff0c\u5e76\u4ec5\u901a\u8fc7\u63a7\u5236\u6700\u4f18\u57fa\u7840\u5185\u7684\u5339\u914d\u6765\u7ba1\u7406\u7b49\u5f85\u4e2d\u7684\u4ee3\u7406\u6570\u91cf\u3002\u672c\u6587\u63d0\u51fa\u4e86\u4e00\u79cd\u57fa\u4e8e\u5bf9\u5076\u89e3\u4f30\u8ba1\u5668\u7684\u539f\u5bf9\u5076\u7b56\u7565\uff0c\u8be5\u7b56\u7565\u6839\u636e\u4f30\u8ba1\u7684\u5bf9\u5076\u89e3\u4e3a\u672a\u6765\u5230\u8fbe\u7684\u4ee3\u7406\u5b89\u6392\u5339\u914d\u3002\u6211\u4eec\u7684\u7b56\u7565\u65e0\u9700\u77e5\u6653\u5230\u8fbe\u7387\uff0c\u4e14\u5177\u6709\u66f4\u5927\u7684\u7075\u6d3b\u6027\uff0c\u56e0\u4e3a\u5b83\u4e0d\u9650\u5236\u5339\u914d\u4ec5\u5728\u6700\u4f18\u57fa\u7840\u5185\u7684\u7c7b\u578b\u4e4b\u95f4\u8fdb\u884c\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u8be5\u7b56\u7565\u662f\u9996\u4e2a\u5728\u672a\u77e5\u5230\u8fbe\u7387\u4e0b\u59cb\u7ec8\u5b9e\u73b0\u5e38\u540e\u6094\u7684\u7b56\u7565\uff0c\u4e14\u5f53\u5230\u8fbe\u7387\u5df2\u77e5\u65f6\uff0c\u5176\u6027\u80fd\u8fbe\u5230\u6700\u4f18\u91cf\u7ea7\u3002\u6b64\u5916\uff0c\u5728\u5230\u8fbe\u7387\u5df2\u77e5\u7684\u60c5\u51b5\u4e0b\uff0c\u539f\u5bf9\u5076\u7b56\u7565\u5728\u591a\u4e2a\u6570\u503c\u6a21\u62df\u4e2d\u663e\u8457\u4f18\u4e8e\u5176\u4ed6\u52a8\u6001\u5339\u914d\u7b56\u7565\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.06402", "journal": "MS", "title": "Managing Inventory and Pricing with Contextual Robust Optimization", "authors": ["Xun Zhang", "Qinshen Tang", "Zhi Chen", "Li Chen"], "author_details": [{"name": "Xun Zhang", "affiliations": ["International Institute of Finance, School of Management, University of Science and Technology of China, Hefei 230026, China"]}, {"name": "Qinshen Tang", "affiliations": ["Division of Information Technology & Operations Management, Nanyang Business School, Nanyang Technological University, Singapore 639798"]}, {"name": "Zhi Chen", "affiliations": ["Department of Decisions, Operations and Technology, CUHK Business School, The Chinese University of Hong Kong, Hong Kong"]}, {"name": "Li Chen", "affiliations": ["The University of Sydney Business School, The University of Sydney, Sydney, New South Wales 2006, Australia"]}], "abstract": "Multiproduct inventory and pricing problems are traditionally approached by estimating a presumed sufficiently accurate demand model and then optimizing with this specified model to determine optimal inventory and pricing decisions. However, obtaining an accurate demand model is nearly impossible because of unobservable parameters, resulting in parameter uncertainty; meanwhile, the unknown distribution of the error term in the stochastic demand model raises residual ambiguity. Additionally, the predicted demand is endogenously affected by pricing, leading to decision-dependent prediction that often brings about intractable optimization problems. We introduce a contextual robust optimization model that simultaneously addresses these challenges. Our proposed model possesses attractive finite-sample performance guarantees and can be effectively approached using an enhanced affine recourse adaptation to resolve the issue of intractability, and it can be extended to broader contextual decision-making problems under mild conditions. Extensive numerical studies demonstrate the effectiveness of our approach, showing that it outperforms the conventional estimate-then-optimize approach and the residual-based robust optimization approach that does not account for parameter uncertainty, particularly when the available data are limited. Notably, our proposed model exhibits greater resilience when contextual information is disregarded, reflecting practical situations in which collecting such information might be impossible or costly.", "date": "2026-09-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-30T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06402", "title_zh": "\u57fa\u4e8e\u4e0a\u4e0b\u6587\u9c81\u68d2\u4f18\u5316\u7684\u5e93\u5b58\u4e0e\u5b9a\u4ef7\u7ba1\u7406", "abstract_zh": "\u591a\u4ea7\u54c1\u5e93\u5b58\u4e0e\u5b9a\u4ef7\u95ee\u9898\u4f20\u7edf\u4e0a\u662f\u901a\u8fc7\u4f30\u8ba1\u4e00\u4e2a\u5047\u8bbe\u8db3\u591f\u51c6\u786e\u7684\u9700\u6c42\u6a21\u578b\uff0c\u7136\u540e\u57fa\u4e8e\u8be5\u6a21\u578b\u8fdb\u884c\u4f18\u5316\u6765\u786e\u5b9a\u6700\u4f18\u7684\u5e93\u5b58\u548c\u5b9a\u4ef7\u51b3\u7b56\u3002\u7136\u800c\uff0c\u7531\u4e8e\u53c2\u6570\u4e0d\u53ef\u89c2\u6d4b\uff0c\u83b7\u5f97\u51c6\u786e\u7684\u9700\u6c42\u6a21\u578b\u51e0\u4e4e\u662f\u4e0d\u53ef\u80fd\u7684\uff0c\u4ece\u800c\u5bfc\u81f4\u53c2\u6570\u4e0d\u786e\u5b9a\u6027\uff1b\u540c\u65f6\uff0c\u968f\u673a\u9700\u6c42\u6a21\u578b\u4e2d\u8bef\u5dee\u9879\u7684\u672a\u77e5\u5206\u5e03\u4e5f\u5e26\u6765\u4e86\u6b8b\u4f59\u6a21\u7cca\u6027\u3002\u6b64\u5916\uff0c\u9884\u6d4b\u9700\u6c42\u4f1a\u53d7\u5230\u5b9a\u4ef7\u7684\u5185\u751f\u5f71\u54cd\uff0c\u5bfc\u81f4\u51b3\u7b56\u4f9d\u8d56\u578b\u9884\u6d4b\uff0c\u5e38\u5e38\u5f15\u53d1\u96be\u4ee5\u5904\u7406\u7684\u4f18\u5316\u95ee\u9898\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u4e0a\u4e0b\u6587\u9c81\u68d2\u4f18\u5316\u6a21\u578b\uff0c\u540c\u65f6\u89e3\u51b3\u4e86\u8fd9\u4e9b\u6311\u6218\u3002\u8be5\u6a21\u578b\u5177\u6709\u826f\u597d\u7684\u5c0f\u6837\u672c\u6027\u80fd\u4fdd\u8bc1\uff0c\u5e76\u53ef\u901a\u8fc7\u589e\u5f3a\u7684\u4eff\u5c04\u60c5\u666f\u9002\u5e94\u65b9\u6cd5\u6709\u6548\u89e3\u51b3\u4e0d\u53ef\u884c\u6027\u95ee\u9898\uff0c\u4e14\u5728\u6ee1\u8db3\u4e00\u5b9a\u6761\u4ef6\u4e0b\u53ef\u6269\u5c55\u81f3\u66f4\u5e7f\u6cdb\u7684\u4e0a\u4e0b\u6587\u51b3\u7b56\u95ee\u9898\u3002\u5927\u91cf\u6570\u503c\u7814\u7a76\u8868\u660e\uff0c\u6211\u4eec\u7684\u65b9\u6cd5\u4f18\u4e8e\u4f20\u7edf\u7684\u201c\u4f30\u8ba1\u540e\u4f18\u5316\u201d\u65b9\u6cd5\u4ee5\u53ca\u4e0d\u8003\u8651\u53c2\u6570\u4e0d\u786e\u5b9a\u6027\u7684\u57fa\u4e8e\u6b8b\u5dee\u7684\u9c81\u68d2\u4f18\u5316\u65b9\u6cd5\uff0c\u5c24\u5176\u662f\u5728\u53ef\u7528\u6570\u636e\u6709\u9650\u7684\u60c5\u51b5\u4e0b\u3002\u503c\u5f97\u6ce8\u610f\u7684\u662f\uff0c\u5f53\u5ffd\u7565\u4e0a\u4e0b\u6587\u4fe1\u606f\u65f6\uff0c\u6211\u4eec\u7684\u6a21\u578b\u8868\u73b0\u51fa\u66f4\u5f3a\u7684\u9c81\u68d2\u6027\uff0c\u8fd9\u53cd\u6620\u4e86\u5b9e\u9645\u4e2d\u6536\u96c6\u6b64\u7c7b\u4fe1\u606f\u53ef\u80fd\u4e0d\u53ef\u884c\u6216\u6210\u672c\u9ad8\u6602\u7684\u73b0\u5b9e\u60c5\u51b5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.05567", "journal": "MS", "title": "The Effects of Stock Ownership on Individual Spending, Investments, and Loyalty", "authors": ["Paolina C. Medina", "Vrinda Mittal", "Michaela Pagel"], "author_details": [{"name": "Paolina C. Medina", "affiliations": ["C. T. Bauer College of Business, University of Houston, Houston, Texas 77204"]}, {"name": "Vrinda Mittal", "affiliations": ["Kenan-Flagler Business School, University of North Carolina at Chapel Hill, Chapel Hill, North Carolina 27599"]}, {"name": "Michaela Pagel", "affiliations": ["Olin Business School, National Bureau of Economic Research, and CEPR, Washington University in St. Louis, St. Louis, Missouri 63130"]}], "abstract": "In this paper, we analyze how one of the most fundamental behavioral biases in investing\u2014people\u2019s preference for buying specific stocks rather than holding the market portfolio\u2014affects their life-cycle consumption, savings, and stock market participation. We first show that when investors receive stocks from specific companies, they increase their spending in those companies\u2019 stores. Although specific stock ownership increases total spending in the short run, individuals\u2019 overall stock market investments increase in the long run. For identification, we use the staggered allocation of brokerage accounts to individuals over time as well as quasirandomly distributed stock grants.", "date": "2026-09-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-30T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.05567", "title_zh": "\u80a1\u7968\u6240\u6709\u6743\u5bf9\u4e2a\u4eba\u6d88\u8d39\u3001\u6295\u8d44\u548c\u5fe0\u8bda\u5ea6\u7684\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u5206\u6790\u4e86\u6295\u8d44\u4e2d\u6700\u57fa\u672c\u7684\u884c\u4e3a\u504f\u5dee\u4e4b\u4e00\u2014\u2014\u4eba\u4eec\u66f4\u503e\u5411\u4e8e\u8d2d\u4e70\u7279\u5b9a\u80a1\u7968\u800c\u975e\u6301\u6709\u5e02\u573a\u7ec4\u5408\u2014\u2014\u5982\u4f55\u5f71\u54cd\u5176\u751f\u547d\u5468\u671f\u5185\u7684\u6d88\u8d39\u3001\u50a8\u84c4\u4ee5\u53ca\u80a1\u7968\u5e02\u573a\u53c2\u4e0e\u3002\u6211\u4eec\u9996\u5148\u53d1\u73b0\uff0c\u5f53\u6295\u8d44\u8005\u83b7\u5f97\u7279\u5b9a\u516c\u53f8\u7684\u80a1\u7968\u65f6\uff0c\u4ed6\u4eec\u4f1a\u589e\u52a0\u5728\u8be5\u516c\u53f8\u5546\u5e97\u7684\u6d88\u8d39\u3002\u5c3d\u7ba1\u7279\u5b9a\u80a1\u7968\u6240\u6709\u6743\u5728\u77ed\u671f\u5185\u589e\u52a0\u4e86\u603b\u6d88\u8d39\uff0c\u4f46\u4e2a\u4f53\u5728\u957f\u671f\u4e2d\u7684\u6574\u4f53\u80a1\u7968\u5e02\u573a\u6295\u8d44\u4f1a\u589e\u52a0\u3002\u4e3a\u4e86\u8bc6\u522b\u8fd9\u4e00\u6548\u5e94\uff0c\u6211\u4eec\u5229\u7528\u4e86\u7ecf\u7eaa\u8d26\u6237\u5728\u4e2a\u4f53\u4e4b\u95f4\u968f\u65f6\u95f4\u5206\u6279\u5206\u914d\u7684\u60c5\u51b5\uff0c\u4ee5\u53ca\u80a1\u7968\u8d60\u4e0e\u5728\u4e2a\u4f53\u95f4\u8fd1\u4f3c\u968f\u673a\u5206\u5e03\u7684\u7279\u5f81\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/qje/qjag048", "journal": "QJE", "title": "The Origin of Risk", "authors": ["Alexandr Kopytov", "Mathieu Taschereau-Dumouchel", "Zebang Xu"], "author_details": [{"name": "Alexandr Kopytov", "affiliations": ["University of Rochester ,"]}, {"name": "Mathieu Taschereau-Dumouchel", "affiliations": ["Cornell University ,"]}, {"name": "Zebang Xu", "affiliations": ["Cornell University ,"]}], "abstract": "Abstract We propose a tractable model in which risk, at both the micro and macro levels, is endogenous and driven by incentives. In the model, each firm chooses the mean and the variance of its productivity process, as well as how it covaries with the productivity of other firms. Aggregate risk arises when firms select productivity processes that are correlated with one another. The theory predicts that larger firms and those with lower markups are less volatile and less correlated with aggregate productivity. We find support for these predictions in the data. Through their impact on risk-taking decisions, distortions such as taxes and markups can make GDP more volatile in equilibrium. In a calibrated version of the model, removing distortions significantly reduces GDP volatility.", "date": "2026-09-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1093/qje/qjag048", "title_zh": "\u98ce\u9669\u7684\u8d77\u6e90", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e00\u4e2a\u53ef\u5904\u7406\u7684\u6a21\u578b\uff0c\u5176\u4e2d\u5fae\u89c2\u548c\u5b8f\u89c2\u5c42\u9762\u7684\u98ce\u9669\u662f\u5185\u751f\u7684\uff0c\u5e76\u7531\u6fc0\u52b1\u673a\u5236\u9a71\u52a8\u3002\u5728\u8be5\u6a21\u578b\u4e2d\uff0c\u6bcf\u5bb6\u4f01\u4e1a\u9009\u62e9\u5176\u751f\u4ea7\u7387\u8fc7\u7a0b\u7684\u5747\u503c\u548c\u65b9\u5dee\uff0c\u4ee5\u53ca\u5176\u4e0e\u5176\u4ed6\u4f01\u4e1a\u751f\u4ea7\u7387\u8fc7\u7a0b\u7684\u534f\u65b9\u5dee\u3002\u5f53\u4f01\u4e1a\u9009\u62e9\u76f8\u4e92\u5173\u8054\u7684\u751f\u4ea7\u7387\u8fc7\u7a0b\u65f6\uff0c\u5c31\u4f1a\u4ea7\u751f\u6574\u4f53\u98ce\u9669\u3002\u8be5\u7406\u8bba\u9884\u6d4b\uff0c\u89c4\u6a21\u8f83\u5927\u7684\u4f01\u4e1a\u4ee5\u53ca\u90a3\u4e9b\u5229\u6da6\u7387\u8f83\u4f4e\u7684\u4f01\u4e1a\u5177\u6709\u66f4\u4f4e\u7684\u6ce2\u52a8\u6027\u548c\u4e0e\u6574\u4f53\u751f\u4ea7\u7387\u7684\u76f8\u5173\u6027\u3002\u6570\u636e\u652f\u6301\u4e86\u8fd9\u4e9b\u9884\u6d4b\u3002\u7531\u4e8e\u7a0e\u6536\u548c\u5229\u6da6\u7387\u7b49\u626d\u66f2\u56e0\u7d20\u5bf9\u98ce\u9669\u627f\u62c5\u51b3\u7b56\u7684\u5f71\u54cd\uff0c\u5747\u8861\u72b6\u6001\u4e0bGDP\u7684\u6ce2\u52a8\u6027\u4f1a\u589e\u52a0\u3002\u5728\u6a21\u578b\u7684\u6821\u51c6\u7248\u672c\u4e2d\uff0c\u6d88\u9664\u8fd9\u4e9b\u626d\u66f2\u56e0\u7d20\u80fd\u663e\u8457\u964d\u4f4eGDP\u7684\u6ce2\u52a8\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70093", "journal": "JF", "title": "The Politicization of Social Responsibility", "authors": ["TODD A. GORMLEY", "MANISH JHA", "MENG WANG"], "author_details": [{"name": "TODD A. GORMLEY", "affiliations": []}, {"name": "MANISH JHA", "affiliations": []}, {"name": "MENG WANG", "affiliations": []}], "abstract": "ABSTRACT Institutional investors are less likely to support shareholder proposals on environmental and social issues for firms headquartered in Republican\u2010led states. The decline in support has become more pronounced in recent years, aligning with politicians emphasizing companies\u2019 social responsibility efforts, and among firms receiving state\u2010level subsidies and tax breaks. Investor support also varies with shifts in state leadership, dropping by 12 percentage points in the same state when Republicans are in control instead of Democrats. The findings indicate that institutional investors prioritize maximizing shareholder value and that politicians can influence investor votes by altering the value implications of shareholder proposals.", "date": "2026-09-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-10-01T22:00:02+00:00", "url": "https://doi.org/10.1111/jofi.70093", "title_zh": "\u793e\u4f1a\u8d23\u4efb\u7684\u653f\u6cbb\u5316", "abstract_zh": "\u6458\u8981\uff1a\u673a\u6784\u6295\u8d44\u8005\u5bf9\u603b\u90e8\u4f4d\u4e8e\u5171\u548c\u515a\u6267\u653f\u5dde\u4f01\u4e1a\u63d0\u51fa\u7684\u73af\u5883\u548c\u793e\u4f1a\u8bae\u9898\u80a1\u4e1c\u63d0\u6848\u7684\u652f\u6301\u7a0b\u5ea6\u8f83\u4f4e\u3002\u8fd1\u5e74\u6765\uff0c\u8fd9\u79cd\u652f\u6301\u7a0b\u5ea6\u7684\u4e0b\u964d\u53d8\u5f97\u66f4\u52a0\u663e\u8457\uff0c\u8fd9\u4e0e\u653f\u6cbb\u4eba\u7269\u5f3a\u8c03\u4f01\u4e1a\u793e\u4f1a\u8d23\u4efb\u52aa\u529b\u7684\u73b0\u8c61\u76f8\u543b\u5408\uff0c\u5c24\u5176\u5728\u83b7\u5f97\u5dde\u7ea7\u8865\u8d34\u548c\u7a0e\u6536\u4f18\u60e0\u7684\u4f01\u4e1a\u4e2d\u66f4\u4e3a\u660e\u663e\u3002\u6295\u8d44\u8005\u7684\u652f\u6301\u7a0b\u5ea6\u4e5f\u968f\u7740\u5dde\u9886\u5bfc\u5c42\u7684\u66f4\u66ff\u800c\u53d8\u5316\uff0c\u5f53\u540c\u4e00\u5dde\u7531\u5171\u548c\u515a\u6267\u653f\u800c\u975e\u6c11\u4e3b\u515a\u6267\u653f\u65f6\uff0c\u652f\u6301\u7387\u4e0b\u964d\u4e8612\u4e2a\u767e\u5206\u70b9\u3002\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u673a\u6784\u6295\u8d44\u8005\u4f18\u5148\u8003\u8651\u6700\u5927\u5316\u80a1\u4e1c\u4ef7\u503c\uff0c\u800c\u653f\u6cbb\u4eba\u7269\u53ef\u4ee5\u901a\u8fc7\u6539\u53d8\u80a1\u4e1c\u63d0\u6848\u7684\u4ef7\u503c\u542b\u4e49\u6765\u5f71\u54cd\u6295\u8d44\u8005\u7684\u6295\u7968\u884c\u4e3a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1017/s0022109026103172", "journal": "JFQA", "title": "Flow Diversification", "authors": ["Sunil Wahal", "Albert Y. Wang"], "author_details": [{"name": "Sunil Wahal", "affiliations": ["Arizona State University W.P. Carey School of Business"]}, {"name": "Albert Y. Wang", "affiliations": ["Auburn University"]}], "abstract": "Abstract We measure flow diversification in mutual funds using the cross-sectional correlation of daily flows across investor clienteles. Greater flow diversification is associated with lower future flow volatility, smaller subsequent outflows, and lower cash holdings. We decompose flow correlation into predictable and unexpected components. Unexpectedly low flow correlation is associated with higher post-outflow fund returns, mitigating outflow-induced externalities on incumbent shareholders. Flow diversification also dampens the higher flow-performance sensitivity of illiquid funds, partially offsetting strategic complementarities that can generate fragility.", "date": "2026-09-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-29T22:00:02+00:00", "url": "https://doi.org/10.1017/s0022109026103172", "title_zh": "\u6d41\u91cf\u591a\u5143\u5316", "abstract_zh": "\u6211\u4eec\u5229\u7528\u6295\u8d44\u8005\u7fa4\u4f53\u4e4b\u95f4\u6bcf\u65e5\u6d41\u91cf\u7684\u6a2a\u622a\u9762\u76f8\u5173\u6027\u6765\u8861\u91cf\u5171\u540c\u57fa\u91d1\u7684\u6d41\u91cf\u591a\u5143\u5316\u3002\u6d41\u91cf\u591a\u5143\u5316\u7a0b\u5ea6\u8d8a\u9ad8\uff0c\u672a\u6765\u6d41\u91cf\u6ce2\u52a8\u8d8a\u5c0f\uff0c\u540e\u7eed\u6d41\u51fa\u91cf\u8d8a\u5c11\uff0c\u73b0\u91d1\u6301\u6709\u91cf\u4e5f\u8d8a\u4f4e\u3002\u6211\u4eec\u5c06\u6d41\u91cf\u76f8\u5173\u6027\u5206\u89e3\u4e3a\u53ef\u9884\u6d4b\u548c\u4e0d\u53ef\u9884\u6d4b\u7684\u7ec4\u6210\u90e8\u5206\u3002\u4e0d\u53ef\u9884\u6d4b\u7684\u4f4e\u6d41\u91cf\u76f8\u5173\u6027\u4e0e\u6d41\u51fa\u540e\u57fa\u91d1\u7684\u66f4\u9ad8\u56de\u62a5\u76f8\u5173\uff0c\u4ece\u800c\u7f13\u89e3\u4e86\u6d41\u51fa\u5bf9\u73b0\u6709\u80a1\u4e1c\u9020\u6210\u7684\u5916\u90e8\u6027\u5f71\u54cd\u3002\u6d41\u91cf\u591a\u5143\u5316\u8fd8\u964d\u4f4e\u4e86\u975e\u6d41\u52a8\u6027\u57fa\u91d1\u5bf9\u6d41\u91cf\u8868\u73b0\u7684\u654f\u611f\u6027\uff0c\u90e8\u5206\u62b5\u6d88\u4e86\u53ef\u80fd\u5f15\u53d1\u8106\u5f31\u6027\u7684\u6218\u7565\u4e92\u8865\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1287/mnsc.2024.05152", "journal": "MS", "title": "Data-Driven Population Tracking in Service Systems", "authors": ["Fernando Bernstein", "N. Bora Keskin", "Adam Mersereau", "Morgan Wood", "Serhan Ziya"], "author_details": [{"name": "Fernando Bernstein", "affiliations": ["Fuqua School of Business, Duke University, Durham, North Carolina 27708"]}, {"name": "N. Bora Keskin", "affiliations": ["Fuqua School of Business, Duke University, Durham, North Carolina 27708"]}, {"name": "Adam Mersereau", "affiliations": ["Kenan-Flagler School of Business, The University of North Carolina at Chapel Hill, Chapel Hill, North Carolina 27599"]}, {"name": "Morgan Wood", "affiliations": ["School of Business and Professional Studies, North Carolina Wesleyan University, Rocky Mount, North Carolina 27804"]}, {"name": "Serhan Ziya", "affiliations": ["Department of Statistics and Operations Research, The University of North Carolina at Chapel Hill, Chapel Hill, North Carolina 27599"]}], "abstract": "Motivated by an application at the Raleigh-Durham International Airport, we consider a service system in which a manager aims to track the number of people in the system based only on noisy observations of arrivals and departures over a time horizon. We study two tracking problems in this context. In the busyness tracking problem, the manager seeks to determine whether the system is busy or not, whereas in the population tracking problem, the manager tracks the number of people in the system and accumulates losses as squared errors. We characterize the cumulative losses of various policies in an asymptotic regime in which the time horizon grows large. We prove general lower bounds on the cumulative loss of any policy and propose relatively simple policies that achieve these lower bounds, up to logarithmic terms. These policies outperform naive tracking policies in many instances. Finally, we characterize the impact of having the ability to periodically inspect the system at a cost. We find that effective population tracking policies take opportunities to reset the population count to accurate estimates to stop the accumulation of error. Without inspections, this is achieved by resetting the population count to zero when a near-empty system is detected based on observing the departure stream. Inspections, although coming at a cost, allow for greater flexibility in the timing of corrections and, hence, improved performance. We demonstrate the performance of our policies using real-world data we collected by installing people-counting sensors at the airport.", "date": "2026-09-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-29T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.05152", "title_zh": "\u57fa\u4e8e\u6570\u636e\u7684\u670d\u52a1\u7cfb\u7edf\u4eba\u7fa4\u8ffd\u8e2a", "abstract_zh": "\u53d7\u7f57\u5229-\u8fbe\u52d2\u59c6\u56fd\u9645\u673a\u573a\u5e94\u7528\u7684\u542f\u53d1\uff0c\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u4e2a\u670d\u52a1\u7cfb\u7edf\uff0c\u5176\u4e2d\u7ba1\u7406\u8005\u4ec5\u57fa\u4e8e\u5bf9\u5230\u8fbe\u548c\u79bb\u5f00\u4e8b\u4ef6\u7684\u566a\u58f0\u89c2\u6d4b\u6765\u8ffd\u8e2a\u7cfb\u7edf\u4e2d\u7684\u4eba\u6570\u3002\u6211\u4eec\u5728\u6b64\u80cc\u666f\u4e0b\u7814\u7a76\u4e86\u4e24\u4e2a\u8ffd\u8e2a\u95ee\u9898\uff1a\u5728\u7e41\u5fd9\u72b6\u6001\u8ffd\u8e2a\u95ee\u9898\u4e2d\uff0c\u7ba1\u7406\u8005\u65e8\u5728\u5224\u65ad\u7cfb\u7edf\u662f\u5426\u5904\u4e8e\u7e41\u5fd9\u72b6\u6001\uff1b\u800c\u5728\u4eba\u7fa4\u6570\u91cf\u8ffd\u8e2a\u95ee\u9898\u4e2d\uff0c\u7ba1\u7406\u8005\u8ffd\u8e2a\u7cfb\u7edf\u4e2d\u7684\u4eba\u6570\uff0c\u5e76\u56e0\u5e73\u65b9\u8bef\u5dee\u7d2f\u79ef\u635f\u5931\u3002\u6211\u4eec\u5728\u65f6\u95f4\u8de8\u5ea6\u8d8b\u4e8e\u65e0\u7a77\u5927\u7684\u6e10\u8fd1\u60c5\u5f62\u4e0b\uff0c\u523b\u753b\u4e86\u5404\u79cd\u7b56\u7565\u7684\u7d2f\u8ba1\u635f\u5931\u3002\u6211\u4eec\u8bc1\u660e\u4e86\u4efb\u4f55\u7b56\u7565\u7684\u7d2f\u8ba1\u635f\u5931\u7684\u901a\u7528\u4e0b\u754c\uff0c\u5e76\u63d0\u51fa\u4e86\u82e5\u5e72\u76f8\u5bf9\u7b80\u5355\u7684\u7b56\u7565\uff0c\u8fd9\u4e9b\u7b56\u7565\u5728\u5bf9\u6570\u9879\u8303\u56f4\u5185\u8fbe\u5230\u4e86\u8be5\u4e0b\u754c\uff0c\u4e14\u5728\u8bb8\u591a\u60c5\u51b5\u4e0b\u4f18\u4e8e\u6734\u7d20\u7684\u8ffd\u8e2a\u7b56\u7565\u3002\u6700\u540e\uff0c\u6211\u4eec\u5206\u6790\u4e86\u80fd\u591f\u4ee5\u4e00\u5b9a\u6210\u672c\u5468\u671f\u6027\u68c0\u67e5\u7cfb\u7edf\u7684\u5f71\u54cd\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u6709\u6548\u7684\u7fa4\u4f53\u8ffd\u8e2a\u7b56\u7565\u4f1a\u5229\u7528\u673a\u4f1a\u5c06\u4eba\u7fa4\u6570\u91cf\u4f30\u8ba1\u91cd\u7f6e\u4e3a\u51c6\u786e\u503c\uff0c\u4ee5\u505c\u6b62\u8bef\u5dee\u7684\u7d2f\u79ef\u3002\u5728\u6ca1\u6709\u68c0\u67e5\u7684\u60c5\u51b5\u4e0b\uff0c\u8fd9\u79cd\u91cd\u7f6e\u662f\u57fa\u4e8e\u89c2\u5bdf\u5230\u7684\u79bb\u5f00\u6d41\u68c0\u6d4b\u5230\u63a5\u8fd1\u7a7a\u7cfb\u7edf\u7684\u72b6\u6001\u65f6\uff0c\u5c06\u4eba\u7fa4\u6570\u91cf\u4f30\u8ba1\u91cd\u7f6e\u4e3a\u96f6\u6765\u5b9e\u73b0\u7684\u3002\u5c3d\u7ba1\u68c0\u67e5\u4f1a\u5e26\u6765\u6210\u672c\uff0c\u4f46\u5176\u5141\u8bb8\u5728\u66f4\u7075\u6d3b\u7684\u65f6\u95f4\u70b9\u8fdb\u884c\u4fee\u6b63\uff0c\u4ece\u800c\u63d0\u5347\u6574\u4f53\u6027\u80fd\u3002\u6211\u4eec\u5229\u7528\u5728\u673a\u573a\u5b89\u88c5\u7684\u4eba\u7fa4\u8ba1\u6570\u4f20\u611f\u5668\u6536\u96c6\u7684\u73b0\u5b9e\u6570\u636e\uff0c\u5c55\u793a\u4e86\u6240\u63d0\u7b56\u7565\u7684\u6027\u80fd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.08260", "journal": "MS", "title": "Impact of Short-Form Videos on Screentime and Sleep: Evidence from TikTok", "authors": ["Saharsh Agarwal", "Uttara M. Ananthakrishnan"], "author_details": [{"name": "Saharsh Agarwal", "affiliations": ["Information Systems Department, Indian School of Business, Hyderabad, Telangana 500032, India"]}, {"name": "Uttara M. Ananthakrishnan", "affiliations": ["Information Systems Department, Foster School of Business, University of Washington, Seattle, Washington 98195"]}], "abstract": "Short-form video platforms have become central to debates about digital overuse and sleep disruption, yet causal evidence on their behavioral impacts remains limited. We study the effects of adopting short-form video in the context of TikTok, which pioneered the format and accounts for a large share of global short-form video consumption. Using granular smartphone touchstream data from a large opt-in panel of U.S. Android users, we track app usage, screen time, and inferred sleep behavior before and after TikTok adoption. We employ a difference-in-differences framework leveraging a high-frequency app usage data set from nearly 7,000 TikTok adopters. Our findings reveal a significant increase in overall screen time\u2014averaging 221 minutes per week for heavy TikTok users\u2014following TikTok adoption, alongside notable declines in usage of other social media and gaming apps, suggesting a strong substitution effect. The screen time effects are highest during late night hours. We also observe shifts in sleep patterns, including delayed bedtimes and a moderate reduction in sleep duration, among high-intensity users. We observe no effects for low-intensity users, who engage minimally with TikTok postadoption. Our findings show that short-form video adoption expands total digital attention rather than merely reallocating it, with important implications for platform design, regulation, and digital well-being. As a side result, our analysis provides clear evidence of substitutability between TikTok and traditional social media platforms, which has important implications for competition policy.", "date": "2026-09-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-29T22:00:02+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08260", "title_zh": "\u77ed\u89c6\u9891\u5bf9\u5c4f\u5e55\u4f7f\u7528\u65f6\u95f4\u4e0e\u7761\u7720\u7684\u5f71\u54cd\uff1a\u6765\u81eaTikTok\u7684\u8bc1\u636e", "abstract_zh": "\u77ed\u89c6\u9891\u5e73\u53f0\u5df2\u6210\u4e3a\u5173\u4e8e\u6570\u5b57\u8fc7\u5ea6\u4f7f\u7528\u548c\u7761\u7720\u5e72\u6270\u4e89\u8bae\u7684\u6838\u5fc3\uff0c\u4f46\u5bf9\u5176\u884c\u4e3a\u5f71\u54cd\u7684\u56e0\u679c\u8bc1\u636e\u4ecd\u5341\u5206\u6709\u9650\u3002\u6211\u4eec\u7814\u7a76\u4e86\u5728TikTok\u5e73\u53f0\u91c7\u7528\u77ed\u89c6\u9891\u683c\u5f0f\u540e\u7684\u884c\u4e3a\u5f71\u54cd\uff0cTikTok\u662f\u8fd9\u4e00\u683c\u5f0f\u7684\u5f00\u521b\u8005\uff0c\u5e76\u5360\u636e\u4e86\u5168\u7403\u77ed\u89c6\u9891\u6d88\u8d39\u7684\u5927\u90e8\u5206\u4efd\u989d\u3002\u5229\u7528\u6765\u81ea\u7f8e\u56fd\u5927\u91cf\u5b89\u5353\u7528\u6237\u81ea\u613f\u53c2\u4e0e\u9762\u677f\u7684\u7ec6\u7c92\u5ea6\u667a\u80fd\u624b\u673a\u89e6\u6478\u6d41\u6570\u636e\uff0c\u6211\u4eec\u8ffd\u8e2a\u4e86\u7528\u6237\u5728\u91c7\u7528TikTok\u524d\u540e\u5e94\u7528\u7a0b\u5e8f\u7684\u4f7f\u7528\u60c5\u51b5\u3001\u5c4f\u5e55\u4f7f\u7528\u65f6\u95f4\u4ee5\u53ca\u63a8\u65ad\u51fa\u7684\u7761\u7720\u884c\u4e3a\u3002\u6211\u4eec\u91c7\u7528\u5dee\u5206\u5dee\u5206\u6846\u67b6\uff0c\u5229\u7528\u8fd17000\u540dTikTok\u4f7f\u7528\u8005\u7684\u9ad8\u9891\u5e94\u7528\u7a0b\u5e8f\u4f7f\u7528\u6570\u636e\u3002\u7814\u7a76\u53d1\u73b0\uff0cTikTok\u91c7\u7528\u540e\uff0c\u603b\u4f53\u5c4f\u5e55\u4f7f\u7528\u65f6\u95f4\u663e\u8457\u589e\u52a0\u2014\u2014\u91cd\u5ea6\u7528\u6237\u6bcf\u5468\u5e73\u5747\u589e\u52a0221\u5206\u949f\uff0c\u540c\u65f6\u5176\u4ed6\u793e\u4ea4\u5a92\u4f53\u548c\u6e38\u620f\u7c7b\u5e94\u7528\u7684\u4f7f\u7528\u91cf\u660e\u663e\u4e0b\u964d\uff0c\u8868\u660e\u5b58\u5728\u5f3a\u70c8\u7684\u66ff\u4ee3\u6548\u5e94\u3002\u5c4f\u5e55\u4f7f\u7528\u65f6\u95f4\u7684\u589e\u52a0\u5728\u591c\u95f4\u8f83\u665a\u65f6\u6bb5\u6700\u4e3a\u663e\u8457\u3002\u6211\u4eec\u8fd8\u89c2\u5bdf\u5230\u7761\u7720\u6a21\u5f0f\u7684\u6539\u53d8\uff0c\u5305\u62ec\u5c31\u5bdd\u65f6\u95f4\u63a8\u8fdf\u4ee5\u53ca\u9ad8\u5f3a\u5ea6\u7528\u6237\u7684\u7761\u7720\u65f6\u957f\u4e2d\u7b49\u7a0b\u5ea6\u51cf\u5c11\u3002\u5bf9\u4e8e\u8f7b\u5ea6\u4f7f\u7528\u8005\u800c\u8a00\uff0c\u91c7\u7528TikTok\u540e\u5176\u4f7f\u7528\u9891\u7387\u51e0\u4e4e\u672a\u53d1\u751f\u53d8\u5316\u3002\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u77ed\u89c6\u9891\u5e73\u53f0\u7684\u91c7\u7528\u6269\u5c55\u4e86\u603b\u4f53\u7684\u6570\u5b57\u6ce8\u610f\u529b\uff0c\u800c\u4e0d\u4ec5\u4ec5\u662f\u91cd\u65b0\u5206\u914d\u6ce8\u610f\u529b\uff0c\u8fd9\u5bf9\u5e73\u53f0\u8bbe\u8ba1\u3001\u76d1\u7ba1\u548c\u6570\u5b57\u798f\u7949\u5177\u6709\u91cd\u8981\u610f\u4e49\u3002\u4f5c\u4e3a\u526f\u4ea7\u54c1\uff0c\u6211\u4eec\u7684\u5206\u6790\u63d0\u4f9b\u4e86\u660e\u786e\u8bc1\u636e\uff0c\u8868\u660eTikTok\u4e0e\u4f20\u7edf\u793e\u4ea4\u5a92\u4f53\u5e73\u53f0\u4e4b\u95f4\u5b58\u5728\u53ef\u66ff\u4ee3\u6027\uff0c\u8fd9\u5bf9\u7ade\u4e89\u653f\u7b56\u5177\u6709\u91cd\u8981\u542f\u793a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70094", "journal": "JF", "title": "Money to Burn: Crowdfunding Wildfire Recovery", "authors": ["J. ANTHONY COOKSON", "EMILY A. GALLAGHER", "PHILIP MULDER"], "author_details": [{"name": "J. ANTHONY COOKSON", "affiliations": []}, {"name": "EMILY A. GALLAGHER", "affiliations": []}, {"name": "PHILIP MULDER", "affiliations": []}], "abstract": "ABSTRACT Person\u2010to\u2010person crowdfunding is an increasingly important form of disaster relief, yet its distribution is poorly understood. Linking GoFundMe campaigns from a major wildfire to property and household credit records, we find that higher\u2010income households are 12 pp more likely to have campaigns and raise over 25% more, holding property losses constant. These disparities reflect unequal access to social capital: broader donor bases, more nonlocal ties, greater advocacy by friends, and more generous donors. Donors appear influenced by social pressure in online crowdfunding. These mechanisms mirror national patterns and underscore crowdfunding's limitations as a tool for equitable disaster relief.", "date": "2026-09-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-30T22:00:02+00:00", "url": "https://doi.org/10.1111/jofi.70094", "title_zh": "\u70e7\u94b1\u6551\u63f4\uff1a\u4f17\u7b79\u5728\u91ce\u706b\u6062\u590d\u4e2d\u7684\u5e94\u7528", "abstract_zh": "\u6458\u8981 \u4e2a\u4eba\u5bf9\u4e2a\u4eba\u7684\u4f17\u7b79\u5df2\u6210\u4e3a\u707e\u96be\u6551\u63f4\u4e2d\u8d8a\u6765\u8d8a\u91cd\u8981\u7684\u5f62\u5f0f\uff0c\u4f46\u5176\u5206\u914d\u673a\u5236\u4ecd\u4e0d\u660e\u786e\u3002\u901a\u8fc7\u5c06\u67d0\u6b21\u91cd\u5927\u91ce\u706b\u4e8b\u4ef6\u4e2d\u7684GoFundMe\u4f17\u7b79\u6d3b\u52a8\u4e0e\u623f\u4ea7\u548c\u5bb6\u5ead\u4fe1\u7528\u8bb0\u5f55\u76f8\u94fe\u63a5\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u9ad8\u6536\u5165\u5bb6\u5ead\u53d1\u8d77\u4f17\u7b79\u6d3b\u52a8\u7684\u6982\u7387\u9ad8\u51fa12\u4e2a\u767e\u5206\u70b9\uff0c\u5e76\u5728\u8d22\u4ea7\u635f\u5931\u4fdd\u6301\u4e0d\u53d8\u7684\u60c5\u51b5\u4e0b\uff0c\u7b79\u96c6\u91d1\u989d\u8d85\u8fc725%\u3002\u8fd9\u79cd\u5dee\u5f02\u53cd\u6620\u4e86\u793e\u4f1a\u8d44\u672c\u5206\u914d\u4e0d\u5747\uff1a\u66f4\u5e7f\u6cdb\u7684\u6350\u8d60\u8005\u7f51\u7edc\u3001\u66f4\u591a\u975e\u672c\u5730\u4eba\u9645\u5173\u7cfb\u3001\u670b\u53cb\u66f4\u79ef\u6781\u7684\u5021\u5bfc\u884c\u4e3a\u4ee5\u53ca\u66f4\u6177\u6168\u7684\u6350\u8d60\u8005\u3002\u6350\u8d60\u8005\u4f3c\u4e4e\u53d7\u5230\u5728\u7ebf\u4f17\u7b79\u4e2d\u7684\u793e\u4f1a\u538b\u529b\u5f71\u54cd\u3002\u8fd9\u4e9b\u673a\u5236\u4e0e\u5168\u56fd\u8303\u56f4\u5185\u7684\u6a21\u5f0f\u76f8\u543b\u5408\uff0c\u51f8\u663e\u4e86\u4f17\u7b79\u4f5c\u4e3a\u5b9e\u73b0\u516c\u5e73\u707e\u96be\u6551\u63f4\u5de5\u5177\u7684\u5c40\u9650\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70088", "journal": "JF", "title": "An IV Hazard Model of Loan Default with an Application to Subprime Mortgage Cohorts", "authors": ["CHRISTOPHER J. PALMER"], "author_details": [{"name": "CHRISTOPHER J. PALMER", "affiliations": []}], "abstract": "ABSTRACT I develop a control function methodology robust to endogenous or mismeasured regressors in hazard models. Applying the estimator to the subprime mortgage crisis, I quantify what caused the foreclosure rate to triple across the 2003 to 2007 subprime cohorts. To identify the elasticity of default to housing prices, I use various home price instruments including historical variation in home price cyclicality. Loose credit played a significant role in the crisis, but much of the increase in defaults across cohorts was caused by price declines unrelated to lending standards, with a 10% price decline increasing subprime mortgage default rates by 50%.", "date": "2026-09-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://doi.org/10.1111/jofi.70088", "title_zh": "\u8d37\u6b3e\u8fdd\u7ea6\u7684IV\u5371\u9669\u6a21\u578b\u53ca\u5176\u5728\u6b21\u7ea7\u62b5\u62bc\u8d37\u6b3e\u7fa4\u4f53\u4e2d\u7684\u5e94\u7528", "abstract_zh": "\u6458\u8981 \u6211\u5f00\u53d1\u4e86\u4e00\u79cd\u5bf9\u5371\u9669\u6a21\u578b\u4e2d\u5185\u751f\u6216\u6d4b\u91cf\u9519\u8bef\u7684\u56de\u5f52\u53d8\u91cf\u5177\u6709\u9c81\u68d2\u6027\u7684\u63a7\u5236\u51fd\u6570\u65b9\u6cd5\u3002\u5c06\u8be5\u4f30\u8ba1\u91cf\u5e94\u7528\u4e8e\u6b21\u7ea7\u62b5\u62bc\u8d37\u6b3e\u5371\u673a\uff0c\u6211\u91cf\u5316\u4e862003\u5e74\u81f32007\u5e74\u6b21\u7ea7\u62b5\u62bc\u8d37\u6b3e\u7fa4\u4f53\u4e2d\u8fdd\u7ea6\u7387\u4e09\u500d\u589e\u957f\u7684\u539f\u56e0\u3002\u4e3a\u4e86\u8bc6\u522b\u8fdd\u7ea6\u5bf9\u623f\u4ef7\u7684\u5f39\u6027\uff0c\u6211\u4f7f\u7528\u4e86\u591a\u79cd\u623f\u4ef7\u5de5\u5177\u53d8\u91cf\uff0c\u5305\u62ec\u623f\u4ef7\u5468\u671f\u6027\u53d8\u5316\u7684\u5386\u53f2\u6ce2\u52a8\u3002\u5bbd\u677e\u7684\u4fe1\u8d37\u5728\u5371\u673a\u4e2d\u53d1\u6325\u4e86\u91cd\u8981\u4f5c\u7528\uff0c\u4f46\u5404\u7fa4\u4f53\u8fdd\u7ea6\u7387\u7684\u5927\u90e8\u5206\u589e\u52a0\u662f\u7531\u4e0e\u4fe1\u8d37\u6807\u51c6\u65e0\u5173\u7684\u4ef7\u683c\u4e0b\u8dcc\u5f15\u8d77\u7684\uff0c\u623f\u4ef7\u4e0b\u964d10%\u4f1a\u4f7f\u6b21\u7ea7\u62b5\u62bc\u8d37\u6b3e\u8fdd\u7ea6\u7387\u4e0a\u534750%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.07339", "journal": "MS", "title": "How Awareness of Media Slant Affects Reaction to News: Field and Experimental Evidence from Microblog Users", "authors": ["Yihong Huang", "Juanjuan Meng", "Xi Weng"], "author_details": [{"name": "Yihong Huang", "affiliations": ["Guanghua School of Management, Peking University"]}, {"name": "Juanjuan Meng", "affiliations": ["Guanghua School of Management, Peking University"]}, {"name": "Xi Weng", "affiliations": ["Guanghua School of Management, Peking University"]}], "abstract": "This paper investigates whether news consumers react strategically to media slant. Using data from Microblog users and an online experiment that varies whether sources and stances are disclosed, we find that users are more likely to repost news consistent with their own attitudes, yet they also exhibit a higher propensity to repost news inconsistent with the reporting outlet\u2019s general stance. Evidence suggests that this latter behavior reflects strategic inference: users recognize the outlet\u2019s tradeoff between popularity and stance, and thus infer greater popularity for inconsistent news. Heterogeneity analysis indicates that users with stronger Bayesian updating and level-k reasoning abilities display larger strategic reactions. Finally, we show that simply reminding users of media slant can serve as an effective nudge to foster more strategic responses.", "date": "2026-09-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07339", "title_zh": "\u5bf9\u5a92\u4f53\u503e\u5411\u610f\u8bc6\u5982\u4f55\u5f71\u54cd\u65b0\u95fb\u53cd\u5e94\uff1a\u6765\u81ea\u5fae\u535a\u7528\u6237\u7684\u5b9e\u5730\u4e0e\u5b9e\u9a8c\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u65b0\u95fb\u6d88\u8d39\u8005\u662f\u5426\u4f1a\u5bf9\u5a92\u4f53\u503e\u5411\u8fdb\u884c\u6218\u7565\u6027\u53cd\u5e94\u3002\u5229\u7528\u5fae\u535a\u7528\u6237\u7684\u6570\u636e\u4ee5\u53ca\u4e00\u4e2a\u5728\u7ebf\u5b9e\u9a8c\uff0c\u8be5\u5b9e\u9a8c\u6539\u53d8\u4e86\u4fe1\u606f\u6765\u6e90\u548c\u7acb\u573a\u662f\u5426\u62ab\u9732\u7684\u6761\u4ef6\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u7528\u6237\u66f4\u503e\u5411\u4e8e\u8f6c\u53d1\u4e0e\u81ea\u8eab\u89c2\u70b9\u4e00\u81f4\u7684\u65b0\u95fb\uff0c\u4f46\u4ed6\u4eec\u4e5f\u8868\u73b0\u51fa\u66f4\u9ad8\u7684\u503e\u5411\u53bb\u8f6c\u53d1\u4e0e\u65b0\u95fb\u6765\u6e90\u6574\u4f53\u7acb\u573a\u4e0d\u4e00\u81f4\u7684\u65b0\u95fb\u3002\u8bc1\u636e\u8868\u660e\uff0c\u8fd9\u79cd\u540e\u4e00\u79cd\u884c\u4e3a\u53cd\u6620\u4e86\u6218\u7565\u63a8\u65ad\uff1a\u7528\u6237\u8ba4\u8bc6\u5230\u5a92\u4f53\u5728\u6d41\u884c\u5ea6\u548c\u7acb\u573a\u4e4b\u95f4\u7684\u6743\u8861\uff0c\u56e0\u6b64\u63a8\u65ad\u51fa\u4e0e\u7acb\u573a\u4e0d\u4e00\u81f4\u7684\u65b0\u95fb\u53ef\u80fd\u66f4\u53d7\u6b22\u8fce\u3002\u5f02\u8d28\u6027\u5206\u6790\u8868\u660e\uff0c\u5177\u6709\u66f4\u5f3a\u8d1d\u53f6\u65af\u66f4\u65b0\u548c\u5c42\u7ea7\u63a8\u7406\u80fd\u529b\u7684\u7528\u6237\u8868\u73b0\u51fa\u66f4\u5927\u7684\u6218\u7565\u6027\u53cd\u5e94\u3002\u6700\u540e\uff0c\u6211\u4eec\u8bc1\u660e\uff0c\u4ec5\u4ec5\u63d0\u9192\u7528\u6237\u6ce8\u610f\u5a92\u4f53\u503e\u5411\uff0c\u5c31\u53ef\u4ee5\u4f5c\u4e3a\u4e00\u79cd\u6709\u6548\u7684\u5f15\u5bfc\uff0c\u4fc3\u8fdb\u66f4\u5177\u6709\u6218\u7565\u6027\u7684\u53cd\u5e94\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2025.02137", "journal": "MS", "title": "Who Directs the Control Tower? Customer vs. Supplier-Managed Inventory in Supply Chains", "authors": ["Shi Chen", "Morris A. Cohen", "Hau L. Lee"], "author_details": [{"name": "Shi Chen", "affiliations": ["Foster School of Business, University of Washington, Seattle, Washington 98195"]}, {"name": "Morris A. Cohen", "affiliations": ["Wharton School of Business, University of Pennsylvania, Philadelphia, Pennsylvania 19104"]}, {"name": "Hau L. Lee", "affiliations": ["Graduate School of Business, Stanford University, Stanford, California 94305"]}], "abstract": "Information distortion and incentive misalignment often undermine supply chain performance. In response, many firms adopt a \u201ccontrol tower\u201d approach, whereby one party assumes responsibility for replenishment decisions across the supply chain. Industry examples showed that this role may be assigned to the customer, Customer-Managed Inventory (CMI), or to the supplier, Supplier-Managed Inventory (SMI). This paper investigates when one governance structure is preferable. We study a two-echelon, one-to-many supply chain consisting of a single supplier and a customer operating multiple warehouses. We characterize optimal base-stock policies and equilibrium holding-cost-sharing parameters under CMI and SMI and benchmark them against decentralized operations and a fully centralized system. Two primary forces shape the choice between CMI and SMI: the relative shortage penalty costs of the two parties and the structure of the customer\u2019s distribution network. Specifically, CMI is preferred when the customer faces relatively higher shortage penalties and operates in a more asymmetric environment\u2014for example, when demand is concentrated in a subset of its warehouses or when replenishment lead times vary substantially across these locations. In contrast, SMI is favored under opposite conditions. We further examine how intertemporal and interspatial demand correlations affect this comparison. A key finding is that, although neither CMI nor SMI achieves the first-best outcome, their efficiency loss relative to full centralization is typically small. Calibrated numerical studies based on four industry cases disentangle the incremental value of information sharing, decision-right transfer, and cost sharing, showing that most performance gains stem from decision-right transfer supported by appropriate holding-cost sharing.", "date": "2026-09-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://doi.org/10.1287/mnsc.2025.02137", "title_zh": "\u8c01\u6765\u638c\u63a7\u63a7\u5236\u5854\uff1f\u4f9b\u5e94\u94fe\u4e2d\u5ba2\u6237\u4e0e\u4f9b\u5e94\u5546\u7ba1\u7406\u5e93\u5b58", "abstract_zh": "\u4fe1\u606f\u626d\u66f2\u548c\u6fc0\u52b1\u9519\u914d\u5e38\u5e38\u635f\u5bb3\u4f9b\u5e94\u94fe\u7ee9\u6548\u3002\u4e3a\u6b64\uff0c\u8bb8\u591a\u4f01\u4e1a\u91c7\u7528\u2018\u63a7\u5236\u5854\u2019\u6a21\u5f0f\uff0c\u5373\u7531\u4e00\u65b9\u8d1f\u8d23\u6574\u4e2a\u4f9b\u5e94\u94fe\u7684\u8865\u8d27\u51b3\u7b56\u3002\u884c\u4e1a\u6848\u4f8b\u8868\u660e\uff0c\u8fd9\u4e00\u89d2\u8272\u53ef\u80fd\u7531\u5ba2\u6237\u627f\u62c5\uff08\u5ba2\u6237\u7ba1\u7406\u5e93\u5b58\uff0cCMI\uff09\uff0c\u4e5f\u53ef\u80fd\u7531\u4f9b\u5e94\u5546\u627f\u62c5\uff08\u4f9b\u5e94\u5546\u7ba1\u7406\u5e93\u5b58\uff0cSMI\uff09\u3002\u672c\u6587\u7814\u7a76\u5728\u4f55\u79cd\u60c5\u51b5\u4e0b\u4e00\u79cd\u6cbb\u7406\u7ed3\u6784\u4f18\u4e8e\u53e6\u4e00\u79cd\u3002\u6211\u4eec\u7814\u7a76\u4e00\u4e2a\u4e24\u7ea7\u3001\u4e00\u5230\u591a\u7684\u4f9b\u5e94\u94fe\uff0c\u7531\u5355\u4e00\u4f9b\u5e94\u5546\u548c\u4e00\u4e2a\u8fd0\u8425\u591a\u4e2a\u4ed3\u5e93\u7684\u5ba2\u6237\u7ec4\u6210\u3002\u6211\u4eec\u523b\u753b\u4e86\u5728CMI\u548cSMI\u4e0b\u6700\u4f18\u7684\u57fa\u5e93\u5b58\u7b56\u7565\u4ee5\u53ca\u5747\u8861\u7684\u5e93\u5b58\u6210\u672c\u5206\u62c5\u53c2\u6570\uff0c\u5e76\u5c06\u5176\u4e0e\u5206\u6563\u5316\u8fd0\u8425\u548c\u5b8c\u5168\u96c6\u4e2d\u5316\u7cfb\u7edf\u8fdb\u884c\u5bf9\u6bd4\u3002\u5f71\u54cdCMI\u4e0eSMI\u9009\u62e9\u7684\u4e24\u4e2a\u4e3b\u8981\u56e0\u7d20\u662f\u53cc\u65b9\u7684\u76f8\u5bf9\u7f3a\u8d27\u60e9\u7f5a\u6210\u672c\u4ee5\u53ca\u5ba2\u6237\u7684\u5206\u9500\u7f51\u7edc\u7ed3\u6784\u3002\u5177\u4f53\u800c\u8a00\uff0c\u5f53\u5ba2\u6237\u9762\u4e34\u76f8\u5bf9\u8f83\u9ad8\u7684\u7f3a\u8d27\u60e9\u7f5a\u6210\u672c\uff0c\u4e14\u8fd0\u8425\u73af\u5883\u66f4\u4e0d\u5747\u8861\u65f6\uff08\u4f8b\u5982\uff0c\u9700\u6c42\u96c6\u4e2d\u5728\u90e8\u5206\u4ed3\u5e93\uff0c\u6216\u5404\u4ed3\u5e93\u7684\u8865\u8d27\u5468\u671f\u5dee\u5f02\u663e\u8457\uff09\uff0c\u503e\u5411\u4e8e\u9009\u62e9CMI\u3002\u76f8\u53cd\uff0c\u5728\u76f8\u53cd\u6761\u4ef6\u4e0b\u5219\u66f4\u503e\u5411\u4e8e\u9009\u62e9SMI\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u8003\u5bdf\u4e86\u8de8\u65f6\u95f4\u4e0e\u8de8\u7a7a\u95f4\u9700\u6c42\u76f8\u5173\u6027\u5bf9\u8fd9\u4e00\u6bd4\u8f83\u7684\u5f71\u54cd\u3002\u4e00\u4e2a\u5173\u952e\u53d1\u73b0\u662f\uff0c\u5c3d\u7ba1CMI\u548cSMI\u5747\u65e0\u6cd5\u8fbe\u5230\u6700\u4f18\u96c6\u4e2d\u5316\u6c34\u5e73\uff0c\u4f46\u5b83\u4eec\u76f8\u5bf9\u4e8e\u5b8c\u5168\u96c6\u4e2d\u5316\u7cfb\u7edf\u7684\u6548\u7387\u635f\u5931\u901a\u5e38\u5f88\u5c0f\u3002\u57fa\u4e8e\u56db\u4e2a\u884c\u4e1a\u6848\u4f8b\u7684\u6821\u51c6\u6570\u503c\u7814\u7a76\u5206\u79bb\u4e86\u4fe1\u606f\u5171\u4eab\u3001\u51b3\u7b56\u6743\u8f6c\u79fb\u548c\u6210\u672c\u5206\u62c5\u7684\u589e\u91cf\u4ef7\u503c\uff0c\u8868\u660e\u5927\u591a\u6570\u7ee9\u6548\u63d0\u5347\u6e90\u4e8e\u7531\u9002\u5f53\u7684\u5e93\u5b58\u6210\u672c\u5206\u62c5\u652f\u6301\u7684\u51b3\u7b56\u6743\u8f6c\u79fb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.3386/w35782", "journal": "NBER", "title": "An LLM Workflow That Reproduces, Improves, and Extends Published Economics Research", "authors": ["Matthew Schwartz", "Isaiah Andrews", "Jesse M. Shapiro"], "author_details": [{"name": "Matthew Schwartz", "affiliations": []}, {"name": "Isaiah Andrews", "affiliations": []}, {"name": "Jesse M. Shapiro", "affiliations": []}], "abstract": "We introduce an open-source workflow that enables an LLM to reproduce, improve, and extend an economics article using the article\u2019s published replication package. First, the workflow attempts to reproduce the original calculations, checks for discrepancies with published findings, and performs automated sensitivity analysis. Across 4,452 published replication packages for five economics journals, the workflow flags discrepancies in 3,460 articles or their appendices. Second, the workflow improves the original calculations by using a different implementation or algorithm. In 496 articles, the workflow is able to reduce a calculation\u2019s computation time, at similar or greater accuracy, by more than a factor of 10. Third, the workflow extends the original analysis. In 923 articles, the workflow develops an extension that does not appear in the original article and that is aligned with the original article\u2019s goals and assumptions.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35782", "title_zh": "\u4e00\u79cd\u80fd\u591f\u590d\u73b0\u3001\u6539\u8fdb\u5e76\u6269\u5c55\u5df2\u53d1\u8868\u7ecf\u6d4e\u5b66\u7814\u7a76\u7684LLM\u5de5\u4f5c\u6d41", "abstract_zh": "\u6211\u4eec\u4ecb\u7ecd\u4e86\u4e00\u79cd\u5f00\u6e90\u5de5\u4f5c\u6d41\uff0c\u4f7f\u5927\u8bed\u8a00\u6a21\u578b\u80fd\u591f\u5229\u7528\u5df2\u53d1\u8868\u7684\u7814\u7a76\u590d\u73b0\u5305\u6765\u590d\u73b0\u3001\u6539\u8fdb\u548c\u6269\u5c55\u4e00\u7bc7\u7ecf\u6d4e\u5b66\u8bba\u6587\u3002\u9996\u5148\uff0c\u8be5\u5de5\u4f5c\u6d41\u5c1d\u8bd5\u590d\u73b0\u539f\u59cb\u8ba1\u7b97\uff0c\u68c0\u67e5\u4e0e\u5df2\u53d1\u8868\u7ed3\u679c\u4e4b\u95f4\u7684\u5dee\u5f02\uff0c\u5e76\u6267\u884c\u81ea\u52a8\u654f\u611f\u6027\u5206\u6790\u3002\u5728\u9488\u5bf9\u4e94\u4e2a\u7ecf\u6d4e\u5b66\u671f\u520a\u76844,452\u4e2a\u5df2\u53d1\u8868\u590d\u73b0\u5305\u4e2d\uff0c\u8be5\u5de5\u4f5c\u6d41\u57283,460\u7bc7\u6587\u7ae0\u6216\u9644\u5f55\u4e2d\u68c0\u6d4b\u5230\u5dee\u5f02\u3002\u5176\u6b21\uff0c\u8be5\u5de5\u4f5c\u6d41\u901a\u8fc7\u91c7\u7528\u4e0d\u540c\u7684\u5b9e\u73b0\u65b9\u5f0f\u6216\u7b97\u6cd5\u6765\u6539\u8fdb\u539f\u59cb\u8ba1\u7b97\u3002\u5728496\u7bc7\u6587\u7ae0\u4e2d\uff0c\u5de5\u4f5c\u6d41\u80fd\u591f\u5c06\u8ba1\u7b97\u7684\u6267\u884c\u65f6\u95f4\u964d\u4f4e\u8d85\u8fc710\u500d\uff0c\u540c\u65f6\u4fdd\u6301\u76f8\u4f3c\u6216\u66f4\u9ad8\u7684\u51c6\u786e\u6027\u3002\u7b2c\u4e09\uff0c\u8be5\u5de5\u4f5c\u6d41\u6269\u5c55\u4e86\u539f\u59cb\u5206\u6790\u3002\u5728923\u7bc7\u6587\u7ae0\u4e2d\uff0c\u5de5\u4f5c\u6d41\u5f00\u53d1\u51fa\u4e00\u79cd\u5728\u539f\u59cb\u6587\u7ae0\u4e2d\u672a\u51fa\u73b0\u4f46\u4e0e\u539f\u59cb\u6587\u7ae0\u76ee\u6807\u548c\u5047\u8bbe\u76f8\u4e00\u81f4\u7684\u6269\u5c55\u5206\u6790\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.3386/w35789", "journal": "NBER", "title": "(How) Do We Teach Emotions?", "authors": ["Anjali Adukia", "Matthew Bonci", "Paula Dastres Gallardo", "Emileigh Harrison", "Jake Nicoll", "Teodora Szasz"], "author_details": [{"name": "Anjali Adukia", "affiliations": []}, {"name": "Matthew Bonci", "affiliations": []}, {"name": "Paula Dastres Gallardo", "affiliations": []}, {"name": "Emileigh Harrison", "affiliations": []}, {"name": "Jake Nicoll", "affiliations": []}, {"name": "Teodora Szasz", "affiliations": []}], "abstract": "Emotional intelligence constitutes a key component of human capital, shaped partially by educational materials. Using machine learning and generative AI tools, we examine emotional content in public-school textbooks and children\u2019s literature. A stark mismatch emerges: text exposes children to a broad emotional range, but images overwhelmingly depict happiness and calm, regardless of emotions described in text on the same page. Nearly half of pages show zero overlap between the emotions described in text and those shown in images. This pattern persists across time, contexts, and identities. Household purchases and library inventories suggest content may be endogenously shaped by consumer demand favoring \u201cpositive\u201d cover imagery, implying market forces narrow the emotional landscape children encounter.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35789", "title_zh": "(\u5982\u4f55) \u6211\u4eec\u6559\u60c5\u611f\uff1f", "abstract_zh": "\u60c5\u611f\u667a\u529b\u662f\u4eba\u529b\u8d44\u672c\u7684\u5173\u952e\u7ec4\u6210\u90e8\u5206\uff0c\u90e8\u5206\u7531\u6559\u80b2\u6750\u6599\u5851\u9020\u3002\u6211\u4eec\u5229\u7528\u673a\u5668\u5b66\u4e60\u548c\u751f\u6210\u5f0f\u4eba\u5de5\u667a\u80fd\u5de5\u5177\uff0c\u7814\u7a76\u516c\u7acb\u5b66\u6821\u6559\u6750\u548c\u513f\u7ae5\u6587\u5b66\u4e2d\u7684\u60c5\u611f\u5185\u5bb9\u3002\u7ed3\u679c\u663e\u793a\u5b58\u5728\u663e\u8457\u77db\u76fe\uff1a\u6587\u672c\u4e2d\u5448\u73b0\u4e86\u5e7f\u6cdb\u7684\u60c5\u611f\u8303\u56f4\uff0c\u4f46\u56fe\u50cf\u5374\u51e0\u4e4e\u59cb\u7ec8\u53ea\u63cf\u7ed8\u5feb\u4e50\u548c\u5e73\u9759\uff0c\u65e0\u8bba\u6587\u672c\u63cf\u8ff0\u7684\u662f\u4f55\u79cd\u60c5\u611f\u3002\u63a5\u8fd1\u4e00\u534a\u7684\u9875\u9762\u4e2d\uff0c\u6587\u672c\u63cf\u8ff0\u7684\u60c5\u611f\u4e0e\u56fe\u50cf\u5c55\u73b0\u7684\u60c5\u611f\u5b8c\u5168\u4e0d\u5339\u914d\u3002\u8fd9\u4e00\u6a21\u5f0f\u5728\u65f6\u95f4\u3001\u60c5\u5883\u548c\u8eab\u4efd\u4e0a\u5747\u6301\u7eed\u5b58\u5728\u3002\u5bb6\u5ead\u8d2d\u4e70\u884c\u4e3a\u548c\u56fe\u4e66\u9986\u85cf\u4e66\u663e\u793a\uff0c\u5185\u5bb9\u53ef\u80fd\u53d7\u5230\u6d88\u8d39\u8005\u9700\u6c42\u7684\u5185\u751f\u5f71\u54cd\uff0c\u5373\u5e02\u573a\u529b\u91cf\u504f\u597d\u201c\u79ef\u6781\u201d\u7684\u5c01\u9762\u56fe\u50cf\uff0c\u4ece\u800c\u7f29\u5c0f\u4e86\u513f\u7ae5\u63a5\u89e6\u7684\u60c5\u611f\u8303\u56f4\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.3386/w35790", "journal": "NBER", "title": "Price Setting During a Currency Changeover", "authors": ["Fernando E. Alvarez", "David Argente", "Alberto Cavallo", "Francesco Lippi"], "author_details": [{"name": "Fernando E. Alvarez", "affiliations": []}, {"name": "David Argente", "affiliations": []}, {"name": "Alberto Cavallo", "affiliations": []}, {"name": "Francesco Lippi", "affiliations": []}], "abstract": "We use the euro cash changeover, a large-scale and purely nominal reform that requires all firms to redenominate posted prices, to distinguish among theories of price rigidity. We develop a nonstationary menu-cost model in which firms anticipate the changeover date and may combine currency adoption with real price adjustment. The announcement makes the firm\u2019s inaction region time-varying, a singular control problem with a moving boundary for which closed-form characterizations are rarely available. We solve this problem analytically by perturbation, recovering the whole path of the boundary, the date at which firms begin adopting the new currency, and the implied pricing moments. The model predicts that, as the changeover approaches, firms adjust more frequently but by smaller amounts, compressing the distribution of price changes. We test these predictions using historical CPI micro data from Austria, Finland, Greece, and Slovakia, a UK benchmark, and daily price data from the recent changeovers in Croatia and Bulgaria. Across changeovers, adjustment frequency rises while the size and dispersion of price changes fall. The model adds a single parameter to the standard menu-cost setup, the cost of pricing in the wrong currency. Calibrating it to the observed rise in adjustment frequency, the model reproduces the decline in the size of price changes and its subsequent recovery, neither of which is targeted. The evidence supports state-dependent price-setting models over models in which nominal redenomination leaves real pricing behavior unchanged.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35790", "title_zh": "\u8d27\u5e01\u8f6c\u6362\u671f\u95f4\u7684\u4ef7\u683c\u8bbe\u5b9a", "abstract_zh": "\u6211\u4eec\u5229\u7528\u6b27\u5143\u73b0\u91d1\u8f6c\u6362\u8fd9\u4e00\u5927\u89c4\u6a21\u4e14\u7eaf\u7cb9\u540d\u4e49\u6027\u8d28\u7684\u6539\u9769\uff0c\u8981\u6c42\u6240\u6709\u4f01\u4e1a\u91cd\u65b0\u6807\u5b9a\u4ef7\u683c\uff0c\u6765\u533a\u5206\u5173\u4e8e\u4ef7\u683c\u521a\u6027\u7684\u4e0d\u540c\u7406\u8bba\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u975e\u5e73\u7a33\u83dc\u5355\u6210\u672c\u6a21\u578b\uff0c\u5176\u4e2d\u4f01\u4e1a\u4f1a\u9884\u671f\u8f6c\u6362\u65e5\u671f\uff0c\u5e76\u53ef\u80fd\u5c06\u8d27\u5e01\u91c7\u7528\u4e0e\u5b9e\u9645\u4ef7\u683c\u8c03\u6574\u76f8\u7ed3\u5408\u3002\u516c\u544a\u4f7f\u5f97\u4f01\u4e1a\u4e0d\u884c\u52a8\u533a\u57df\u968f\u65f6\u95f4\u53d8\u5316\uff0c\u5f62\u6210\u4e00\u4e2a\u5177\u6709\u79fb\u52a8\u8fb9\u754c\u7684\u5947\u5f02\u63a7\u5236\u95ee\u9898\uff0c\u8fd9\u7c7b\u95ee\u9898\u901a\u5e38\u96be\u4ee5\u83b7\u5f97\u95ed\u5f0f\u89e3\u3002\u6211\u4eec\u901a\u8fc7\u6270\u52a8\u6cd5\u89e3\u6790\u5730\u89e3\u51b3\u4e86\u8be5\u95ee\u9898\uff0c\u6062\u590d\u4e86\u8fb9\u754c\u8def\u5f84\u7684\u5b8c\u6574\u5f62\u6001\u3001\u4f01\u4e1a\u5f00\u59cb\u91c7\u7528\u65b0\u8d27\u5e01\u7684\u65e5\u671f\u4ee5\u53ca\u9690\u542b\u7684\u4ef7\u683c\u8bbe\u5b9a\u7279\u5f81\u3002\u6a21\u578b\u9884\u6d4b\uff0c\u968f\u7740\u8f6c\u6362\u65e5\u671f\u4e34\u8fd1\uff0c\u4f01\u4e1a\u8c03\u6574\u9891\u7387\u4e0a\u5347\u4f46\u6bcf\u6b21\u8c03\u6574\u5e45\u5ea6\u51cf\u5c0f\uff0c\u538b\u7f29\u4e86\u4ef7\u683c\u53d8\u52a8\u7684\u5206\u5e03\u3002\u6211\u4eec\u5229\u7528\u5965\u5730\u5229\u3001\u82ac\u5170\u3001\u5e0c\u814a\u548c\u65af\u6d1b\u4f10\u514b\u7684\u5386\u53f2CPI\u5fae\u89c2\u6570\u636e\uff0c\u4ee5\u53ca\u82f1\u56fd\u7684\u57fa\u51c6\u6570\u636e\uff0c\u548c\u6700\u8fd1\u514b\u7f57\u5730\u4e9a\u4e0e\u4fdd\u52a0\u5229\u4e9a\u8d27\u5e01\u8f6c\u6362\u671f\u95f4\u7684\u6bcf\u65e5\u4ef7\u683c\u6570\u636e\uff0c\u68c0\u9a8c\u4e86\u8fd9\u4e9b\u9884\u6d4b\u3002\u5728\u6240\u6709\u8d27\u5e01\u8f6c\u6362\u8fc7\u7a0b\u4e2d\uff0c\u8c03\u6574\u9891\u7387\u4e0a\u5347\uff0c\u800c\u4ef7\u683c\u53d8\u52a8\u7684\u5e45\u5ea6\u548c\u5206\u6563\u7a0b\u5ea6\u4e0b\u964d\u3002\u8be5\u6a21\u578b\u5728\u6807\u51c6\u83dc\u5355\u6210\u672c\u6846\u67b6\u4e2d\u589e\u52a0\u4e86\u4e00\u4e2a\u53c2\u6570\u2014\u2014\u4ee5\u9519\u8bef\u8d27\u5e01\u5b9a\u4ef7\u7684\u6210\u672c\u3002\u5c06\u8be5\u53c2\u6570\u6821\u51c6\u81f3\u89c2\u5bdf\u5230\u7684\u8c03\u6574\u9891\u7387\u4e0a\u5347\uff0c\u6a21\u578b\u6210\u529f\u518d\u73b0\u4e86\u4ef7\u683c\u53d8\u52a8\u5e45\u5ea6\u7684\u4e0b\u964d\u53ca\u5176\u540e\u7eed\u6062\u590d\uff0c\u8fd9\u4e9b\u7ed3\u679c\u5747\u672a\u4f5c\u4e3a\u6821\u51c6\u76ee\u6807\u3002\u8bc1\u636e\u652f\u6301\u57fa\u4e8e\u72b6\u6001\u4f9d\u8d56\u7684\u4ef7\u683c\u8bbe\u5b9a\u6a21\u578b\uff0c\u800c\u975e\u8ba4\u4e3a\u540d\u4e49\u91cd\u6807\u4ef7\u4e0d\u5f71\u54cd\u5b9e\u9645\u5b9a\u4ef7\u884c\u4e3a\u7684\u6a21\u578b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35791", "journal": "NBER", "title": "Here, There, and Everywhere: Remote Work\u2019s Impact on Employment in the UK", "authors": ["Ian Burn", "Melissa D. Gentry", "Joanna Lahey"], "author_details": [{"name": "Ian Burn", "affiliations": []}, {"name": "Melissa D. Gentry", "affiliations": []}, {"name": "Joanna Lahey", "affiliations": []}], "abstract": "Remote work is often touted as a way for disabled and older workers to remain in the labour market. Post-Covid, the incidence of remote work has increased in the UK. Following Bloom et al. (2026), we test the effects of remote work on employment for these two groups using the pandemic\u2019s increase in work from home rates as a quasi-experiment. We compare occupations with high growth in work from home (WFH) to those with lower growth in work from home, with growth rates measured among the non-disabled or younger. We then instrument using pre-pandemic remote work scores from Dingle and Neiman (2020). We find significant evidence that rising WFH increases employment of disabled and older workers in the UK. We additionally find decreases in commute time and wages for both groups, but no effect on hours worked.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35791", "title_zh": "\u8fd9\u91cc\u3001\u90a3\u91cc\u3001\u4ee5\u53ca\u5904\u5904\uff1a\u8fdc\u7a0b\u5de5\u4f5c\u5bf9\u82f1\u56fd\u5c31\u4e1a\u7684\u5f71\u54cd", "abstract_zh": "\u8fdc\u7a0b\u5de5\u4f5c\u5e38\u88ab\u89c6\u4f5c\u5e2e\u52a9\u6b8b\u75be\u4eba\u58eb\u548c\u5e74\u957f\u52b3\u52a8\u8005\u7559\u5728\u52b3\u52a8\u529b\u5e02\u573a\u7684\u4e00\u79cd\u65b9\u5f0f\u3002\u75ab\u60c5\u540e\uff0c\u82f1\u56fd\u8fdc\u7a0b\u5de5\u4f5c\u7684\u6bd4\u4f8b\u6709\u6240\u4e0a\u5347\u3002\u9075\u5faaBloom\u7b49\u4eba\uff082026\uff09\u7684\u7814\u7a76\u65b9\u6cd5\uff0c\u6211\u4eec\u5229\u7528\u75ab\u60c5\u65f6\u671f\u8fdc\u7a0b\u5de5\u4f5c\u7387\u7684\u4e0a\u5347\u4f5c\u4e3a\u51c6\u81ea\u7136\u5b9e\u9a8c\uff0c\u68c0\u9a8c\u8fdc\u7a0b\u5de5\u4f5c\u5bf9\u8fd9\u4e24\u7c7b\u7fa4\u4f53\u5c31\u4e1a\u7684\u5f71\u54cd\u3002\u6211\u4eec\u6bd4\u8f83\u4e86\u8fdc\u7a0b\u5de5\u4f5c\u589e\u957f\u663e\u8457\u7684\u804c\u4e1a\u4e0e\u8fdc\u7a0b\u5de5\u4f5c\u589e\u957f\u8f83\u4f4e\u7684\u804c\u4e1a\uff0c\u5176\u4e2d\u589e\u957f\u901f\u7387\u662f\u57fa\u4e8e\u975e\u6b8b\u75be\u4eba\u7fa4\u6216\u5e74\u8f7b\u7fa4\u4f53\u7684\u6570\u636e\u6765\u8861\u91cf\u7684\u3002\u968f\u540e\uff0c\u6211\u4eec\u4f7f\u7528Dingle\u548cNeiman\uff082020\uff09\u7814\u7a76\u4e2d\u7684\u75ab\u60c5\u524d\u8fdc\u7a0b\u5de5\u4f5c\u8bc4\u5206\u4f5c\u4e3a\u5de5\u5177\u53d8\u91cf\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u8fdc\u7a0b\u5de5\u4f5c\u6bd4\u4f8b\u7684\u4e0a\u5347\u663e\u8457\u63d0\u9ad8\u4e86\u82f1\u56fd\u6b8b\u75be\u4eba\u58eb\u548c\u5e74\u957f\u52b3\u52a8\u8005\u7684\u5c31\u4e1a\u6c34\u5e73\u3002\u6b64\u5916\uff0c\u6211\u4eec\u8fd8\u53d1\u73b0\u8fd9\u4e24\u7c7b\u7fa4\u4f53\u7684\u901a\u52e4\u65f6\u95f4\u548c\u5de5\u8d44\u5747\u6709\u6240\u4e0b\u964d\uff0c\u4f46\u5de5\u4f5c\u65f6\u957f\u672a\u53d1\u751f\u53d8\u5316\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35792", "journal": "NBER", "title": "Impact of Adults\u2019 College Completion on their Parents\u2019 Mortality: Evidence from the 1993 Korean Higher Education Reform", "authors": ["Ah-Reum Lee", "William H. Dow", "Jacqueline M. Torres"], "author_details": [{"name": "Ah-Reum Lee", "affiliations": []}, {"name": "William H. Dow", "affiliations": []}, {"name": "Jacqueline M. Torres", "affiliations": []}], "abstract": "A large literature examines the economic and health returns to college education. We extend this literature by studying the upward intergenerational effects of children\u2019s education on parental mortality. We exploit Korea\u2019s 1993 Higher Education Reform, which we estimate raised college completion by 13 percentage points among eldest children in the 1974\u20131983 birth cohorts relative to the prior 10-year cohort. Using data from the Korean Longitudinal Study of Aging, reduced-form estimates indicate a 27% (s.e.=10%) reduction in mortality among parents whose oldest child was in the reform-affected cohort. Because the reform affected college completion but not other education levels or quality, we use it as an instrumental variable (IV) for child college completion. IV estimates indicate a 20% (s.e.=7%) reduction in parental mortality for children induced to complete college by the reform. These parents received greater financial support and contact from their children and had lower smoking and higher physical activity, although these mechanisms explain only a small share of the mortality benefit. Effects were larger for parents of daughters in reduced-form analyses, although IV estimates did not differ significantly by child gender. Future research should further investigate the mechanisms through which children\u2019s college education affects parental mortality.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35792", "title_zh": "\u6210\u5e74\u4eba\u5b8c\u6210\u5927\u5b66\u6559\u80b2\u5bf9\u5176\u7236\u6bcd\u6b7b\u4ea1\u7387\u7684\u5f71\u54cd\uff1a\u6765\u81ea1993\u5e74\u97e9\u56fd\u9ad8\u7b49\u6559\u80b2\u6539\u9769\u7684\u8bc1\u636e", "abstract_zh": "\u5927\u91cf\u6587\u732e\u7814\u7a76\u4e86\u5927\u5b66\u6559\u80b2\u7684\u7ecf\u6d4e\u548c\u5065\u5eb7\u56de\u62a5\u3002\u6211\u4eec\u5728\u6b64\u57fa\u7840\u4e0a\uff0c\u7814\u7a76\u4e86\u5b50\u5973\u6559\u80b2\u5bf9\u7236\u6bcd\u6b7b\u4ea1\u7387\u7684\u5411\u4e0a\u4ee3\u9645\u5f71\u54cd\u3002\u6211\u4eec\u5229\u7528\u97e9\u56fd1993\u5e74\u9ad8\u7b49\u6559\u80b2\u6539\u9769\u8fd9\u4e00\u4e8b\u4ef6\uff0c\u4f30\u8ba1\u8be5\u6539\u9769\u4f7f1974\u20131983\u5e74\u51fa\u751f\u961f\u5217\u4e2d\u6700\u5e74\u957f\u5b50\u5973\u7684\u5927\u5b66\u5b8c\u6210\u7387\u76f8\u6bd4\u524d\u5341\u5e74\u961f\u5217\u63d0\u9ad8\u4e8613\u4e2a\u767e\u5206\u70b9\u3002\u57fa\u4e8e\u97e9\u56fd\u8001\u9f84\u5316\u7eb5\u5411\u7814\u7a76\u7684\u6570\u636e\uff0c\u7b80\u5316\u6a21\u578b\u4f30\u8ba1\u663e\u793a\uff0c\u7236\u6bcd\u4e2d\u5e74\u957f\u5b50\u5973\u5c5e\u4e8e\u6539\u9769\u5f71\u54cd\u961f\u5217\u7684\uff0c\u5176\u6b7b\u4ea1\u7387\u4e0b\u964d\u4e8627%\uff08\u6807\u51c6\u8bef=10%\uff09\u3002\u7531\u4e8e\u6539\u9769\u63d0\u9ad8\u4e86\u5927\u5b66\u5b8c\u6210\u7387\uff0c\u4f46\u5e76\u672a\u5f71\u54cd\u5176\u4ed6\u6559\u80b2\u5c42\u6b21\u6216\u8d28\u91cf\uff0c\u6211\u4eec\u5c06\u5176\u4f5c\u4e3a\u5b50\u5973\u5927\u5b66\u5b8c\u6210\u7387\u7684\u5de5\u5177\u53d8\u91cf\uff08IV\uff09\u3002\u4f7f\u7528\u5de5\u5177\u53d8\u91cf\u4f30\u8ba1\u53d1\u73b0\uff0c\u7531\u6539\u9769\u4fc3\u4f7f\u5b50\u5973\u5b8c\u6210\u5927\u5b66\u6559\u80b2\u7684\u7236\u6bcd\uff0c\u5176\u6b7b\u4ea1\u7387\u4e0b\u964d\u4e8620%\uff08\u6807\u51c6\u8bef=7%\uff09\u3002\u8fd9\u4e9b\u7236\u6bcd\u83b7\u5f97\u4e86\u66f4\u591a\u7684\u5bb6\u5ead\u8d22\u52a1\u652f\u6301\u548c\u4e0e\u5b50\u5973\u7684\u8054\u7cfb\uff0c\u4e14\u5438\u70df\u7387\u66f4\u4f4e\u3001\u8eab\u4f53\u6d3b\u52a8\u6c34\u5e73\u66f4\u9ad8\uff0c\u5c3d\u7ba1\u8fd9\u4e9b\u673a\u5236\u4ec5\u89e3\u91ca\u4e86\u6b7b\u4ea1\u7387\u964d\u4f4e\u7684\u8f83\u5c0f\u90e8\u5206\u3002\u5728\u7b80\u5316\u6a21\u578b\u5206\u6790\u4e2d\uff0c\u5973\u513f\u7684\u7236\u6bcd\u6548\u5e94\u66f4\u5927\uff0c\u4f46\u5de5\u5177\u53d8\u91cf\u4f30\u8ba1\u4e2d\u6027\u522b\u5dee\u5f02\u4e0d\u663e\u8457\u3002\u672a\u6765\u7814\u7a76\u5e94\u8fdb\u4e00\u6b65\u63a2\u7a76\u5b50\u5973\u5927\u5b66\u6559\u80b2\u5982\u4f55\u5f71\u54cd\u7236\u6bcd\u6b7b\u4ea1\u7387\u7684\u673a\u5236\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35793", "journal": "NBER", "title": "The Macroeconomic Effect of AI: Sizing the Software Engineering Channel", "authors": ["Alex Blumenfeld", "Jonathon Hazell", "Chen Lian", "Andreas Schaab"], "author_details": [{"name": "Alex Blumenfeld", "affiliations": []}, {"name": "Jonathon Hazell", "affiliations": []}, {"name": "Chen Lian", "affiliations": []}, {"name": "Andreas Schaab", "affiliations": []}], "abstract": "We measure how artificial intelligence (AI) affects the economy through its impact on software engineering productivity. We use information from financial markets to develop a forward-looking measure that is available in real time. We estimate the sensitivity of each firm\u2019s stock return to an AI stock market index, and how this sensitivity depends on the share of firm payroll in software engineering. We use a model to map this cross-sectional relationship into software engineering productivity gains. From November 2022 to December 2025, AI increased the market\u2019s expected present value of software engineering productivity by the equivalent of a permanent 32.6% productivity increase. The corresponding effect on the level of GDP is 3.6% in the baseline and 6.5% when higher software engineering productivity also raises R&D productivity. By mid-2026, amid rapid progress in coding agents, the effect of AI on productivity and GDP had more than doubled relative to the end of 2025.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35793", "title_zh": "\u4eba\u5de5\u667a\u80fd\u5bf9\u5b8f\u89c2\u7ecf\u6d4e\u7684\u5f71\u54cd\uff1a\u8f6f\u4ef6\u5de5\u7a0b\u6e20\u9053\u7684\u91cf\u5316\u5206\u6790", "abstract_zh": "\u6211\u4eec\u901a\u8fc7\u4eba\u5de5\u667a\u80fd\u5bf9\u8f6f\u4ef6\u5de5\u7a0b\u751f\u4ea7\u7387\u7684\u5f71\u54cd\u6765\u8861\u91cf\u5176\u5bf9\u7ecf\u6d4e\u7684\u4f5c\u7528\u3002\u6211\u4eec\u5229\u7528\u91d1\u878d\u5e02\u573a\u4fe1\u606f\u6784\u5efa\u4e86\u4e00\u4e2a\u53ef\u5b9e\u65f6\u83b7\u53d6\u7684\u524d\u77bb\u6027\u6307\u6807\u3002\u6211\u4eec\u4f30\u8ba1\u4e86\u6bcf\u5bb6\u4f01\u4e1a\u7684\u80a1\u7968\u56de\u62a5\u5bf9\u5176AI\u80a1\u7968\u5e02\u573a\u6307\u6570\u7684\u654f\u611f\u6027\uff0c\u4ee5\u53ca\u8fd9\u79cd\u654f\u611f\u6027\u5982\u4f55\u4f9d\u8d56\u4e8e\u4f01\u4e1a\u5de5\u8d44\u4e2d\u8f6f\u4ef6\u5de5\u7a0b\u90e8\u5206\u7684\u5360\u6bd4\u3002\u6211\u4eec\u4f7f\u7528\u6a21\u578b\u5c06\u8fd9\u4e00\u6a2a\u622a\u9762\u5173\u7cfb\u6620\u5c04\u5230\u8f6f\u4ef6\u5de5\u7a0b\u751f\u4ea7\u7387\u7684\u63d0\u5347\u4e0a\u3002\u4ece2022\u5e7411\u6708\u52302025\u5e7412\u6708\uff0c\u4eba\u5de5\u667a\u80fd\u4f7f\u5e02\u573a\u5bf9\u8f6f\u4ef6\u5de5\u7a0b\u751f\u4ea7\u7387\u7684\u9884\u671f\u73b0\u503c\u63d0\u9ad8\u4e86\u76f8\u5f53\u4e8e\u6c38\u4e45\u602732.6%\u7684\u751f\u4ea7\u7387\u63d0\u5347\u3002\u76f8\u5e94\u5730\uff0c\u5bf9GDP\u6c34\u5e73\u7684\u5f71\u54cd\u5728\u57fa\u51c6\u60c5\u666f\u4e0b\u4e3a3.6%\uff0c\u5f53\u8f6f\u4ef6\u5de5\u7a0b\u751f\u4ea7\u7387\u7684\u63d0\u5347\u4e5f\u5e26\u52a8\u7814\u53d1\u751f\u4ea7\u7387\u63d0\u5347\u65f6\uff0c\u8fd9\u4e00\u5f71\u54cd\u4e0a\u5347\u81f36.5%\u3002\u52302026\u5e74\u4e2d\u671f\uff0c\u968f\u7740\u7f16\u7801\u4ee3\u7406\u6280\u672f\u7684\u5feb\u901f\u8fdb\u5c55\uff0c\u4eba\u5de5\u667a\u80fd\u5bf9\u751f\u4ea7\u7387\u548cGDP\u7684\u5f71\u54cd\u76f8\u6bd42025\u5e74\u5e95\u5df2\u8d85\u8fc7\u4e00\u500d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "AI"]}, {"doi": "10.3386/w35794", "journal": "NBER", "title": "Permits as Real Options: Anticipation and Regulatory Leakage", "authors": ["Anna French", "Nicholas Vreugdenhil"], "author_details": [{"name": "Anna French", "affiliations": []}, {"name": "Nicholas Vreugdenhil", "affiliations": []}], "abstract": "We identify a new channel for regulatory leakage: the \u201cpermitting channel\u201d. In many settings, permits lock in the regulatory regime at approval, allowing firms to acquire the option to invest under current rules. Unlike the conventional Green Paradox response, this channel operates without accelerating physical investment and pollution. We develop a framework in which firms can use real options to avoid anticipated regulation. We estimate the framework using Colorado\u2019s oil and gas reforms, where permits surged before regulation but drilling did not. Policy-relevant designs that remove the permitting channel substantially reduce the health risks from pollution despite amplifying anticipatory investment.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35794", "title_zh": "\u8bb8\u53ef\u4f5c\u4e3a\u5b9e\u7269\u671f\u6743\uff1a\u9884\u671f\u4e0e\u76d1\u7ba1\u6f0f\u51fa", "abstract_zh": "\u6211\u4eec\u8bc6\u522b\u51fa\u76d1\u7ba1\u6f0f\u51fa\u7684\u4e00\u79cd\u65b0\u6e20\u9053\uff1a\u2018\u8bb8\u53ef\u6e20\u9053\u2019\u3002\u5728\u8bb8\u591a\u60c5\u51b5\u4e0b\uff0c\u8bb8\u53ef\u5728\u5ba1\u6279\u65f6\u5c31\u56fa\u5b9a\u4e86\u76d1\u7ba1\u5236\u5ea6\uff0c\u4f7f\u4f01\u4e1a\u83b7\u5f97\u5728\u73b0\u884c\u89c4\u5219\u4e0b\u6295\u8d44\u7684\u671f\u6743\u3002\u4e0e\u4f20\u7edf\u7684\u7eff\u8272\u6096\u8bba\u53cd\u5e94\u4e0d\u540c\uff0c\u8be5\u6e20\u9053\u5728\u4e0d\u52a0\u901f\u5b9e\u7269\u6295\u8d44\u548c\u6c61\u67d3\u7684\u60c5\u51b5\u4e0b\u53d1\u6325\u4f5c\u7528\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6846\u67b6\uff0c\u5176\u4e2d\u4f01\u4e1a\u53ef\u4ee5\u5229\u7528\u5b9e\u7269\u671f\u6743\u6765\u89c4\u907f\u9884\u671f\u4e2d\u7684\u76d1\u7ba1\u3002\u6211\u4eec\u4f7f\u7528\u79d1\u7f57\u62c9\u591a\u5dde\u7684\u6cb9\u6c14\u6539\u9769\u6570\u636e\u5bf9\u8fd9\u4e00\u6846\u67b6\u8fdb\u884c\u4f30\u8ba1\uff0c\u7ed3\u679c\u663e\u793a\u8bb8\u53ef\u5728\u76d1\u7ba1\u4e4b\u524d\u6fc0\u589e\uff0c\u4f46\u94bb\u63a2\u6d3b\u52a8\u5e76\u672a\u589e\u52a0\u3002\u76f8\u5173\u653f\u7b56\u8bbe\u8ba1\u82e5\u6d88\u9664\u8bb8\u53ef\u6e20\u9053\uff0c\u5c06\u663e\u8457\u964d\u4f4e\u6c61\u67d3\u5e26\u6765\u7684\u5065\u5eb7\u98ce\u9669\uff0c\u5c3d\u7ba1\u4f1a\u52a0\u5267\u9884\u671f\u4e2d\u7684\u6295\u8d44\u884c\u4e3a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35795", "journal": "NBER", "title": "Innovation, Business Cycles, and the Climate Transition", "authors": ["Diego R. K\u00e4nzig", "Maximilian Konradt", "Lixing Wang", "Donghai Zhang"], "author_details": [{"name": "Diego R. K\u00e4nzig", "affiliations": []}, {"name": "Maximilian Konradt", "affiliations": []}, {"name": "Lixing Wang", "affiliations": []}, {"name": "Donghai Zhang", "affiliations": []}], "abstract": "We study how business cycle fluctuations shape the pace and direction of innovation. Non-green innovation is procyclical, while green innovation is countercyclical, both over the cycle and in response to economic shocks. We explain this divergence in a dynamic general equilibrium model with endogenous green and non-green innovation. Green patents derive more value from distant profits, making green innovation less sensitive to short-run fluctuations. Endogenous innovation costs reinforce this mechanism, making green and non-green innovation effective substitutes. Evidence from market-implied patent valuations and scientist earnings supports the mechanism. The model implies larger and greener effects of innovation subsidies during downturns.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35795", "title_zh": "\u521b\u65b0\u3001\u5546\u4e1a\u5468\u671f\u4e0e\u6c14\u5019\u8f6c\u578b", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5546\u4e1a\u5468\u671f\u6ce2\u52a8\u5982\u4f55\u5f71\u54cd\u521b\u65b0\u7684\u901f\u5ea6\u548c\u65b9\u5411\u3002\u975e\u7eff\u8272\u521b\u65b0\u662f\u987a\u5468\u671f\u7684\uff0c\u800c\u7eff\u8272\u521b\u65b0\u662f\u9006\u5468\u671f\u7684\uff0c\u8fd9\u65e2\u4f53\u73b0\u5728\u5468\u671f\u5185\uff0c\u4e5f\u4f53\u73b0\u5728\u5bf9\u7ecf\u6d4e\u51b2\u51fb\u7684\u53cd\u5e94\u4e2d\u3002\u6211\u4eec\u5728\u4e00\u4e2a\u5177\u6709\u5185\u751f\u7eff\u8272\u548c\u975e\u7eff\u8272\u521b\u65b0\u7684\u52a8\u6001\u4e00\u822c\u5747\u8861\u6a21\u578b\u4e2d\u89e3\u91ca\u4e86\u8fd9\u79cd\u5dee\u5f02\u3002\u7eff\u8272\u4e13\u5229\u4ece\u8fdc\u671f\u5229\u6da6\u4e2d\u83b7\u5f97\u66f4\u9ad8\u7684\u4ef7\u503c\uff0c\u4f7f\u5f97\u7eff\u8272\u521b\u65b0\u5bf9\u77ed\u671f\u6ce2\u52a8\u7684\u654f\u611f\u6027\u8f83\u4f4e\u3002\u5185\u751f\u521b\u65b0\u6210\u672c\u5f3a\u5316\u4e86\u8fd9\u4e00\u673a\u5236\uff0c\u4f7f\u7eff\u8272\u548c\u975e\u7eff\u8272\u521b\u65b0\u6210\u4e3a\u6709\u6548\u7684\u66ff\u4ee3\u54c1\u3002\u6765\u81ea\u5e02\u573a\u9690\u542b\u4e13\u5229\u4f30\u503c\u548c\u79d1\u5b66\u5bb6\u6536\u5165\u7684\u8bc1\u636e\u652f\u6301\u4e86\u8fd9\u4e00\u673a\u5236\u3002\u6a21\u578b\u8868\u660e\uff0c\u5728\u7ecf\u6d4e\u4e0b\u884c\u671f\u95f4\uff0c\u521b\u65b0\u8865\u8d34\u7684\u6548\u5e94\u66f4\u5927\u4e14\u66f4\u7eff\u8272\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35796", "journal": "NBER", "title": "The Early Impacts of AI on Employment among Recent College Graduates", "authors": ["Robert W. Fairlie", "Jane Wu"], "author_details": [{"name": "Robert W. Fairlie", "affiliations": []}, {"name": "Jane Wu", "affiliations": []}], "abstract": "The impact of AI on the employment prospects of recent college graduates is hotly debated with no consensus on the magnitude of impacts nor even the timing of those potential impacts. Using CPS microdata, we provide the first estimates of the effects of AI on the unemployment of recent college graduates in June, July and August 2026. We provide evidence suggesting that unemployment rates are especially high for summer months and that 2026 might be the first year of widespread enough AI use in the workplace to detect impacts of AI on recent college graduates, the group argued to be most vulnerable to AI replacement. Taking an agnostic approach to defining treatment timing, we find that unemployment rates did not spike in summer 2026 relative to summer months in previous years and did not rise in a significant way relative to older college graduates or young workers without a college degree. We also provide the first analysis of an expanded definition of unemployment that includes those who report \u201cwanting a job\u201d which adds nearly two percentage points to the unemployment rate of recent college graduates but we find no evidence of a statistically significant increase in summer 2026 even after adding these \u201csidelined unemployed.\u201d We estimate difference-in-differences and event-study interaction models using both older college graduates and young non-college graduates as comparison groups and do not find evidence of an increase in relative unemployment rates. Finally, we estimate models in which we interact 2026 unemployment with AI exposure and remote work availability by occupation and find some evidence of a positive relationship with remote work availability.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35796", "title_zh": "\u4eba\u5de5\u667a\u80fd\u5bf9\u8fd1\u671f\u5927\u5b66\u6bd5\u4e1a\u751f\u5c31\u4e1a\u7684\u65e9\u671f\u5f71\u54cd", "abstract_zh": "\u4eba\u5de5\u667a\u80fd\u5bf9\u8fd1\u671f\u5927\u5b66\u6bd5\u4e1a\u751f\u5c31\u4e1a\u524d\u666f\u7684\u5f71\u54cd\u76ee\u524d\u5b58\u5728\u6fc0\u70c8\u4e89\u8bba\uff0c\u5173\u4e8e\u5176\u5f71\u54cd\u7684\u89c4\u6a21\u4ee5\u53ca\u53d1\u751f\u65f6\u95f4\u5c1a\u65e0\u5171\u8bc6\u3002\u5229\u7528\u7f8e\u56fd\u4eba\u53e3\u666e\u67e5\u5c40\uff08CPS\uff09\u5fae\u89c2\u6570\u636e\uff0c\u6211\u4eec\u9996\u6b21\u4f30\u8ba1\u4e86\u4eba\u5de5\u667a\u80fd\u5bf92026\u5e746\u6708\u30017\u6708\u548c8\u6708\u8fd1\u671f\u5927\u5b66\u6bd5\u4e1a\u751f\u5931\u4e1a\u7387\u7684\u5f71\u54cd\u3002\u6211\u4eec\u7684\u7814\u7a76\u8868\u660e\uff0c\u590f\u5b63\u7684\u5931\u4e1a\u7387\u5c24\u5176\u9ad8\uff0c\u4e142026\u5e74\u53ef\u80fd\u662f\u4eba\u5de5\u667a\u80fd\u5728\u804c\u573a\u4e2d\u5e7f\u6cdb\u5e94\u7528\u5230\u8db3\u4ee5\u663e\u73b0\u5176\u5bf9\u8fd1\u671f\u5927\u5b66\u6bd5\u4e1a\u751f\uff08\u88ab\u8ba4\u4e3a\u6700\u6613\u53d7\u4eba\u5de5\u667a\u80fd\u66ff\u4ee3\u5f71\u54cd\u7684\u7fa4\u4f53\uff09\u5f71\u54cd\u7684\u9996\u4e2a\u5e74\u4efd\u3002\u5728\u4e0d\u9884\u8bbe\u4eba\u5de5\u667a\u80fd\u5f71\u54cd\u53d1\u751f\u65f6\u95f4\u7684\u524d\u63d0\u4e0b\uff0c\u6211\u4eec\u53d1\u73b02026\u5e74\u590f\u5b63\u7684\u5931\u4e1a\u7387\u5e76\u672a\u663e\u8457\u9ad8\u4e8e\u6b64\u524d\u5e74\u4efd\u7684\u590f\u5b63\uff0c\u4e5f\u672a\u76f8\u5bf9\u4e8e\u5e74\u957f\u7684\u5927\u5b66\u6bd5\u4e1a\u751f\u6216\u6ca1\u6709\u5927\u5b66\u5b66\u5386\u7684\u5e74\u8f7b\u5de5\u4eba\u51fa\u73b0\u663e\u8457\u4e0a\u5347\u3002\u6b64\u5916\uff0c\u6211\u4eec\u9996\u6b21\u5bf9\u5931\u4e1a\u7684\u6269\u5c55\u5b9a\u4e49\u8fdb\u884c\u4e86\u5206\u6790\uff0c\u8be5\u5b9a\u4e49\u5305\u62ec\u90a3\u4e9b\u8868\u793a\u201c\u60f3\u8981\u5de5\u4f5c\u201d\u7684\u4eba\u7fa4\uff0c\u8fd9\u4e00\u8c03\u6574\u4f7f\u8fd1\u671f\u5927\u5b66\u6bd5\u4e1a\u751f\u7684\u5931\u4e1a\u7387\u589e\u52a0\u4e86\u8fd1\u4e24\u4e2a\u767e\u5206\u70b9\uff0c\u4f46\u5373\u4f7f\u5728\u52a0\u5165\u8fd9\u4e9b\u2018\u88ab\u8fb9\u7f18\u5316\u5931\u4e1a\u8005\u2019\u540e\uff0c\u6211\u4eec\u4e5f\u672a\u53d1\u73b02026\u5e74\u590f\u5b63\u5b58\u5728\u7edf\u8ba1\u5b66\u4e0a\u663e\u8457\u7684\u4e0a\u5347\u3002\u6211\u4eec\u901a\u8fc7\u4f7f\u7528\u5e74\u957f\u5927\u5b66\u6bd5\u4e1a\u751f\u548c\u65e0\u5927\u5b66\u5b66\u5386\u7684\u5e74\u8f7b\u5de5\u4eba\u4f5c\u4e3a\u5bf9\u7167\u7ec4\uff0c\u4f30\u8ba1\u4e86\u5dee\u5206-\u5dee\u5f02\u6a21\u578b\u548c\u4e8b\u4ef6\u7814\u7a76\u4ea4\u4e92\u6a21\u578b\uff0c\u672a\u53d1\u73b0\u76f8\u5bf9\u5931\u4e1a\u7387\u7684\u663e\u8457\u4e0a\u5347\u3002\u6700\u540e\uff0c\u6211\u4eec\u8fd8\u6784\u5efa\u4e86\u5c062026\u5e74\u5931\u4e1a\u7387\u4e0e\u804c\u4e1a\u4e2d\u7684AI\u66b4\u9732\u7a0b\u5ea6\u53ca\u8fdc\u7a0b\u5de5\u4f5c\u53ef\u53ca\u6027\u8fdb\u884c\u4ea4\u4e92\u7684\u6a21\u578b\uff0c\u53d1\u73b0\u8fdc\u7a0b\u5de5\u4f5c\u53ef\u53ca\u6027\u4e0e\u5931\u4e1a\u7387\u4e4b\u95f4\u5b58\u5728\u4e00\u5b9a\u7684\u6b63\u5411\u5173\u7cfb\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.3386/w35797", "journal": "NBER", "title": "Property Rights Uncertainty, Prices, and Speculation: Evidence from China's Housing Market", "authors": ["Hanming Fang", "Jing Wu", "Vincent Yao"], "author_details": [{"name": "Hanming Fang", "affiliations": []}, {"name": "Jing Wu", "affiliations": []}, {"name": "Vincent Yao", "affiliations": []}], "abstract": "We examine the causal effect of uncertainty in property rights on housing prices and speculative behavior. We take advantage of a distinctive setting in Shenzhen, China, where neighboring residential units that are otherwise similar differ in the strength of their property rights protections. Some units have full property rights (FPR) with a 70-year leasehold, whereas others have only limited property rights (LPR) protections. Using detailed listing data, we find that the sales market prices these protections, while the rental market does not. Our estimates imply that the perceived probability that FPR rights could be questioned at the end of the 70-year term is between 7% and 21%, and that the probability the LPR receives no legal protection in any future year exceeds 50%. We further show that LPR units are more susceptible to speculation, as reflected in higher turnover and greater price volatility. Lastly, we show that the public release of new urban planning codes raises listing prices and lowers turnover and price volatility for LPR properties relative to matched FPR units.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35797", "title_zh": "\u4ea7\u6743\u4e0d\u786e\u5b9a\u6027\u3001\u4ef7\u683c\u4e0e\u6295\u673a\uff1a\u6765\u81ea\u4e2d\u56fd\u623f\u5730\u4ea7\u5e02\u573a\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u8003\u5bdf\u4e86\u4ea7\u6743\u4e0d\u786e\u5b9a\u6027\u5bf9\u623f\u4ef7\u548c\u6295\u673a\u884c\u4e3a\u7684\u56e0\u679c\u5f71\u54cd\u3002\u6211\u4eec\u5229\u7528\u4e2d\u56fd\u6df1\u5733\u4e00\u4e2a\u72ec\u7279\u7684\u60c5\u51b5\uff1a\u76f8\u90bb\u7684\u4f4f\u5b85\u5355\u5143\u5728\u5176\u4ed6\u65b9\u9762\u76f8\u4f3c\uff0c\u4f46\u5728\u4ea7\u6743\u4fdd\u62a4\u5f3a\u5ea6\u4e0a\u5b58\u5728\u5dee\u5f02\u3002\u4e00\u4e9b\u5355\u5143\u62e5\u6709\u5b8c\u6574\u7684\u4ea7\u6743\uff08FPR\uff09\uff0c\u4eab\u670970\u5e74\u79df\u8d41\u6743\uff0c\u800c\u53e6\u4e00\u4e9b\u5355\u5143\u4ec5\u62e5\u6709\u6709\u9650\u4ea7\u6743\uff08LPR\uff09\u4fdd\u62a4\u3002\u5229\u7528\u8be6\u7ec6\u7684\u6302\u724c\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u9500\u552e\u5e02\u573a\u5bf9\u8fd9\u4e9b\u4ea7\u6743\u4fdd\u62a4\u8fdb\u884c\u4e86\u5b9a\u4ef7\uff0c\u800c\u79df\u8d41\u5e02\u573a\u5219\u6ca1\u6709\u3002\u6211\u4eec\u7684\u4f30\u8ba1\u8868\u660e\uff0c\u4eba\u4eec\u8ba4\u4e3aFPR\u572870\u5e74\u671f\u6ee1\u65f6\u53ef\u80fd\u88ab\u8d28\u7591\u7684\u6982\u7387\u57287%\u523021%\u4e4b\u95f4\uff0c\u800cLPR\u5728\u4efb\u4f55\u672a\u6765\u5e74\u4efd\u5f97\u4e0d\u5230\u6cd5\u5f8b\u4fdd\u62a4\u7684\u6982\u7387\u8d85\u8fc750%\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u53d1\u73b0\uff0cLPR\u5355\u5143\u66f4\u5bb9\u6613\u53d7\u5230\u6295\u673a\u5f71\u54cd\uff0c\u8868\u73b0\u4e3a\u66f4\u9ad8\u7684\u4ea4\u6613\u9891\u7387\u548c\u66f4\u5927\u7684\u4ef7\u683c\u6ce2\u52a8\u3002\u6700\u540e\uff0c\u6211\u4eec\u53d1\u73b0\u65b0\u57ce\u5e02\u89c4\u5212\u6cd5\u89c4\u7684\u516c\u5f00\u53d1\u5e03\uff0c\u4f1a\u63d0\u9ad8LPR\u623f\u4ea7\u7684\u6302\u724c\u4ef7\u683c\uff0c\u964d\u4f4e\u5176\u4ea4\u6613\u9891\u7387\u548c\u4ef7\u683c\u6ce2\u52a8\uff0c\u76f8\u5bf9\u4e8e\u5339\u914d\u7684FPR\u5355\u5143\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35798", "journal": "NBER", "title": "Are Guidelines Worth Following? Decision-Making Under Incomplete Evidence", "authors": ["Jason Abaluck", "Leila Agha", "David C. Chan Jr"], "author_details": [{"name": "Jason Abaluck", "affiliations": []}, {"name": "Leila Agha", "affiliations": []}, {"name": "David C. Chan Jr", "affiliations": []}], "abstract": "Medical guidelines translate clinical evidence into treatment rules, but the evidence may identify treatment benefits more clearly than harms. We study anticoagulation for atrial fibrillation, combining randomized trials with Veterans Health Administration data. Trial evidence reveals substantial heterogeneity in stroke-prevention benefits but does not reliably identify how treatment-induced bleeding harms vary across patients. In the target population, patients with larger predicted stroke benefits also have higher untreated bleeding risk, making this ambiguity consequential. We evaluate existing guidelines and develop maximin and minimax-regret treatment rules robust to alternative harm structures. At a benchmark preventing 50% of preventable strokes, robust rules induce 33-41% fewer bleeds than random treatment and outperform existing guidelines. Finite-sample uncertainty generates noticeable instability in fine patient rankings but little instability in treatment assignments or welfare. Physician performance and the relationship between guideline adherence and skill also depend substantially on assumptions about how treatment-induced bleeding harms vary across patients.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35798", "title_zh": "\u6307\u5357\u503c\u5f97\u9075\u5faa\u5417\uff1f\u4e0d\u5b8c\u5168\u8bc1\u636e\u4e0b\u7684\u51b3\u7b56\u5236\u5b9a", "abstract_zh": "\u533b\u5b66\u6307\u5357\u5c06\u4e34\u5e8a\u8bc1\u636e\u8f6c\u5316\u4e3a\u6cbb\u7597\u89c4\u5219\uff0c\u4f46\u8bc1\u636e\u53ef\u80fd\u66f4\u6e05\u6670\u5730\u8bc6\u522b\u6cbb\u7597\u7684\u76ca\u5904\u800c\u975e\u5371\u5bb3\u3002\u6211\u4eec\u7814\u7a76\u5fc3\u623f\u98a4\u52a8\u7684\u6297\u51dd\u6cbb\u7597\uff0c\u7ed3\u5408\u968f\u673a\u5bf9\u7167\u8bd5\u9a8c\u4e0e\u9000\u4f0d\u519b\u4eba\u533b\u7597\u7ba1\u7406\u5c40\u7684\u6570\u636e\u3002\u8bd5\u9a8c\u8bc1\u636e\u663e\u793a\uff0c\u9884\u9632\u4e2d\u98ce\u7684\u76ca\u5904\u5b58\u5728\u663e\u8457\u5f02\u8d28\u6027\uff0c\u4f46\u5e76\u672a\u53ef\u9760\u5730\u63ed\u793a\u6cbb\u7597\u5f15\u8d77\u7684\u51fa\u8840\u5371\u5bb3\u5728\u4e0d\u540c\u60a3\u8005\u4e4b\u95f4\u7684\u53d8\u5316\u3002\u5728\u76ee\u6807\u4eba\u7fa4\u4e2d\uff0c\u9884\u6d4b\u4e2d\u98ce\u9884\u9632\u76ca\u5904\u8f83\u5927\u7684\u60a3\u8005\uff0c\u5176\u672a\u63a5\u53d7\u6cbb\u7597\u65f6\u7684\u51fa\u8840\u98ce\u9669\u4e5f\u66f4\u9ad8\uff0c\u56e0\u6b64\u8fd9\u79cd\u4e0d\u786e\u5b9a\u6027\u5177\u6709\u5b9e\u9645\u5f71\u54cd\u3002\u6211\u4eec\u8bc4\u4f30\u4e86\u73b0\u6709\u6307\u5357\uff0c\u5e76\u5236\u5b9a\u4e86\u5728\u4e0d\u540c\u5371\u5bb3\u7ed3\u6784\u4e0b\u5177\u6709\u9c81\u68d2\u6027\u7684\u6700\u5927\u5316\u6700\u5c0f\u6536\u76ca\u548c\u6700\u5c0f\u5316\u540e\u6094\u7684\u6cbb\u7597\u89c4\u5219\u3002\u5728\u9884\u963250%\u53ef\u9884\u9632\u4e2d\u98ce\u7684\u57fa\u51c6\u4e0b\uff0c\u8fd9\u4e9b\u9c81\u68d2\u89c4\u5219\u6bd4\u968f\u673a\u6cbb\u7597\u51cf\u5c1133-41%\u7684\u51fa\u8840\u4e8b\u4ef6\uff0c\u5e76\u4f18\u4e8e\u73b0\u6709\u6307\u5357\u3002\u6709\u9650\u6837\u672c\u7684\u4e0d\u786e\u5b9a\u6027\u5bfc\u81f4\u60a3\u8005\u6392\u5e8f\u5b58\u5728\u660e\u663e\u6ce2\u52a8\uff0c\u4f46\u6cbb\u7597\u5206\u914d\u548c\u798f\u5229\u65b9\u9762\u53d8\u5316\u5f88\u5c0f\u3002\u533b\u751f\u7684\u8868\u73b0\u4ee5\u53ca\u6307\u5357\u9075\u5faa\u7a0b\u5ea6\u4e0e\u4e13\u4e1a\u6280\u80fd\u4e4b\u95f4\u7684\u5173\u7cfb\uff0c\u5f88\u5927\u7a0b\u5ea6\u4e0a\u4f9d\u8d56\u4e8e\u6cbb\u7597\u5f15\u8d77\u51fa\u8840\u5371\u5bb3\u5728\u60a3\u8005\u95f4\u5982\u4f55\u53d8\u5316\u7684\u5047\u8bbe\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35799", "journal": "NBER", "title": "The Wealth of Nations: Origins of Prosperity and Seeds of Inequality", "authors": ["Oded Galor"], "author_details": [{"name": "Oded Galor", "affiliations": []}], "abstract": "What ignited humanity\u2019s momentous ascent from millennia of stagnation to an era of sustained economic growth? And what are the roots of the vast disparities in the wealth of nations? These enduring mysteries, which have preoccupied scholars across generations, lie at the core of Unified Growth Theory. This encompassing framework captures the evolution of societies over the entire course of human history and identifies the universal wheels of change that governed humanity\u2019s long journey, propelled the growth process, and shaped inequality across the globe. The theory uncovers the forces underlying the dramatic transformation in living standards over the past two centuries, emerging from an economic ice age of near stagnation, while highlighting the enduring historical roots of the immense divergence in the prosperity of nations. It suggests that forces set in motion in the distant past played a pivotal role in shaping development across the globe and remain essential for the design of effective policies that foster economic progress and mitigate inequality in the wealth of nations.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35799", "title_zh": "\u56fd\u5bcc\u8bba\uff1a\u7e41\u8363\u7684\u8d77\u6e90\u4e0e\u4e0d\u5e73\u7b49\u7684\u79cd\u5b50", "abstract_zh": "\u662f\u4ec0\u4e48\u70b9\u71c3\u4e86\u4eba\u7c7b\u4ece\u6570\u5343\u5e74\u505c\u6ede\u72b6\u6001\u8fc8\u5411\u6301\u7eed\u7ecf\u6d4e\u589e\u957f\u65f6\u4ee3\u7684\u4f1f\u5927\u53d8\u9769\uff1f\u53c8\u662f\u4ec0\u4e48\u5bfc\u81f4\u4e86\u5404\u56fd\u8d22\u5bcc\u7684\u5de8\u5927\u5dee\u5f02\uff1f\u8fd9\u4e9b\u56f0\u6270\u5b66\u8005\u4eec\u4e16\u4ee3\u7684\u6c38\u6052\u4e4b\u8c1c\uff0c\u6b63\u662f\u7edf\u4e00\u589e\u957f\u7406\u8bba\u7684\u6838\u5fc3\u6240\u5728\u3002\u8fd9\u4e00\u5168\u9762\u7684\u6846\u67b6\u6db5\u76d6\u4e86\u4eba\u7c7b\u793e\u4f1a\u4ece\u53f2\u524d\u81f3\u4eca\u7684\u6574\u4e2a\u6f14\u8fdb\u8fc7\u7a0b\uff0c\u63ed\u793a\u4e86\u63a8\u52a8\u4eba\u7c7b\u957f\u671f\u53d1\u5c55\u3001\u9a71\u52a8\u7ecf\u6d4e\u589e\u957f\u5e76\u5851\u9020\u5168\u7403\u4e0d\u5e73\u7b49\u7684\u666e\u904d\u53d8\u9769\u673a\u5236\u3002\u8be5\u7406\u8bba\u9610\u660e\u4e86\u8fc7\u53bb\u4e24\u767e\u5e74\u751f\u6d3b\u6c34\u5e73\u53d1\u751f\u5267\u70c8\u8f6c\u53d8\u80cc\u540e\u7684\u9a71\u52a8\u529b\uff0c\u8fd9\u4e00\u8f6c\u53d8\u6e90\u4e8e\u6b64\u524d\u957f\u671f\u8fd1\u4e4e\u505c\u6ede\u7684\u7ecf\u6d4e\u51b0\u671f\uff0c\u540c\u65f6\u5f3a\u8c03\u4e86\u5404\u56fd\u7e41\u8363\u7a0b\u5ea6\u5de8\u5927\u5dee\u5f02\u7684\u6301\u4e45\u5386\u53f2\u6839\u6e90\u3002\u5b83\u6307\u51fa\uff0c\u8fdc\u53e4\u65f6\u671f\u542f\u52a8\u7684\u8bf8\u591a\u529b\u91cf\u5728\u5851\u9020\u5168\u7403\u53d1\u5c55\u8fdb\u7a0b\u4e2d\u53d1\u6325\u4e86\u5173\u952e\u4f5c\u7528\uff0c\u8fd9\u4e9b\u529b\u91cf\u5bf9\u4e8e\u8bbe\u8ba1\u80fd\u591f\u4fc3\u8fdb\u7ecf\u6d4e\u589e\u957f\u5e76\u7f13\u89e3\u56fd\u5bb6\u95f4\u8d22\u5bcc\u4e0d\u5e73\u7b49\u7684\u6709\u6548\u653f\u7b56\u4f9d\u7136\u81f3\u5173\u91cd\u8981\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35802", "journal": "NBER", "title": "The Political Foundations of Industrial Policy: Emergence, Endurance, and Exhaustion", "authors": ["Lottie Field", "R\u00e9ka Juh\u00e1sz", "Michele Zampa"], "author_details": [{"name": "Lottie Field", "affiliations": []}, {"name": "R\u00e9ka Juh\u00e1sz", "affiliations": []}, {"name": "Michele Zampa", "affiliations": []}], "abstract": "We study how politics shapes industrial policy through two paradigmatic twentieth-century cases: the Cassa per il Mezzogiorno in Italy (1950\u20131984) and Kennedy's Moonshot in the United States (1961\u20131972). Drawing on historical and primary political sources, we show that each policy originated in a broader political project rather than in an economic diagnosis: the Christian Democrats' pursuit of national integration and democratic consolidation, and Kennedy's New Frontier. We introduce the concept of industrial policy vision - a publicly articulated, transformational objective that political leaders attach to a set of ideals and pursue through state-led intervention in the economy - and develop a five-component definition that makes it empirically tractable. We then trace each vision through decades of newspaper coverage, combining topic modeling and sentiment analysis with systematic close reading. In both cases, public debate proceeded largely within the frame the vision set, granting the policies tolerance for setbacks and expense. The cases diverge in their fates: the Moonshot's bounded vision was redeemed on schedule, while the Cassa's open-ended vision was exhausted by accumulated failure and the policy outlived it only briefly. This divergence points to our central conclusion: while a vision holds, it sets the terms on which an industrial policy's performance is judged, including what counts as failure and how much time the policy is given to deliver.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35802", "title_zh": "\u4ea7\u4e1a\u653f\u7b56\u7684\u653f\u6cbb\u57fa\u7840\uff1a\u5174\u8d77\u3001\u6301\u7eed\u4e0e\u8017\u5c3d", "abstract_zh": "\u6211\u4eec\u901a\u8fc7\u4e24\u4e2a\u4e8c\u5341\u4e16\u7eaa\u7684\u5178\u578b\u6848\u4f8b\u7814\u7a76\u653f\u6cbb\u5982\u4f55\u5851\u9020\u4ea7\u4e1a\u653f\u7b56\uff1a\u610f\u5927\u5229\u7684\u5357\u90e8\u53d1\u5c55\u57fa\u91d1\uff081950\u20131984\u5e74\uff09\u548c\u7f8e\u56fd\u80af\u5c3c\u8fea\u7684\u767b\u6708\u8ba1\u5212\uff081961\u20131972\u5e74\uff09\u3002\u57fa\u4e8e\u5386\u53f2\u548c\u653f\u6cbb\u539f\u59cb\u8d44\u6599\uff0c\u6211\u4eec\u8868\u660e\uff0c\u6bcf\u4e2a\u653f\u7b56\u7684\u8d77\u6e90\u90fd\u6e90\u4e8e\u66f4\u5e7f\u6cdb\u7684\u653f\u6cbb\u76ee\u6807\uff0c\u800c\u975e\u7ecf\u6d4e\u8bca\u65ad\uff1a\u5929\u4e3b\u6559\u6c11\u4e3b\u515a\u4eba\u8ffd\u6c42\u56fd\u5bb6\u6574\u5408\u4e0e\u6c11\u4e3b\u5de9\u56fa\uff0c\u4ee5\u53ca\u80af\u5c3c\u8fea\u7684\u2018\u65b0\u524d\u6cbf\u2019\u8ba1\u5212\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u2018\u4ea7\u4e1a\u653f\u7b56\u613f\u666f\u2019\u7684\u6982\u5ff5\u2014\u2014\u653f\u6cbb\u9886\u5bfc\u4eba\u5c06\u4e00\u7ec4\u7406\u60f3\u4e0e\u516c\u5f00\u8868\u8ff0\u7684\u53d8\u9769\u6027\u76ee\u6807\u76f8\u7ed3\u5408\uff0c\u5e76\u901a\u8fc7\u56fd\u5bb6\u4e3b\u5bfc\u7684\u7ecf\u6d4e\u5e72\u9884\u6765\u5b9e\u73b0\u8fd9\u4e00\u76ee\u6807\u2014\u2014\u5e76\u6784\u5efa\u4e86\u4e00\u4e2a\u4e94\u8981\u7d20\u5b9a\u4e49\uff0c\u4f7f\u5176\u5177\u6709\u53ef\u64cd\u4f5c\u7684\u5b9e\u8bc1\u57fa\u7840\u3002\u968f\u540e\uff0c\u6211\u4eec\u901a\u8fc7\u51e0\u5341\u5e74\u7684\u62a5\u7eb8\u62a5\u9053\u5bf9\u6bcf\u4e2a\u613f\u666f\u8fdb\u884c\u8ffd\u8e2a\uff0c\u7ed3\u5408\u4e3b\u9898\u5efa\u6a21\u548c\u60c5\u611f\u5206\u6790\uff0c\u5e76\u8f85\u4ee5\u7cfb\u7edf\u6027\u7684\u7ec6\u8bfb\u3002\u5728\u4e24\u79cd\u60c5\u51b5\u4e0b\uff0c\u516c\u5171\u8fa9\u8bba\u5927\u591a\u5728\u613f\u666f\u8bbe\u5b9a\u7684\u6846\u67b6\u5185\u5c55\u5f00\uff0c\u4f7f\u653f\u7b56\u80fd\u591f\u5bb9\u5fcd\u632b\u6298\u548c\u652f\u51fa\u3002\u7136\u800c\uff0c\u4e24\u4e2a\u6848\u4f8b\u7684\u7ed3\u5c40\u6709\u6240\u4e0d\u540c\uff1a\u767b\u6708\u8ba1\u5212\u7684\u6709\u9650\u613f\u666f\u6309\u671f\u5b9e\u73b0\uff0c\u800c\u5357\u90e8\u53d1\u5c55\u57fa\u91d1\u7684\u5f00\u653e\u6027\u613f\u666f\u5219\u56e0\u7d2f\u79ef\u5931\u8d25\u800c\u8017\u5c3d\uff0c\u8be5\u653f\u7b56\u4ec5\u77ed\u6682\u5730\u5ef6\u7eed\u4e86\u5176\u539f\u6709\u76ee\u6807\u3002\u8fd9\u4e00\u5dee\u5f02\u6307\u5411\u6211\u4eec\u7684\u6838\u5fc3\u7ed3\u8bba\uff1a\u5f53\u613f\u666f\u6301\u7eed\u5b58\u5728\u65f6\uff0c\u5b83\u51b3\u5b9a\u4e86\u4ea7\u4e1a\u653f\u7b56\u8868\u73b0\u7684\u8bc4\u5224\u6807\u51c6\uff0c\u5305\u62ec\u5982\u4f55\u5b9a\u4e49\u5931\u8d25\u4ee5\u53ca\u653f\u7b56\u88ab\u8d4b\u4e88\u7684\u6267\u884c\u65f6\u95f4\u957f\u5ea6\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790"]}, {"doi": "10.3386/w35803", "journal": "NBER", "title": "Injury, Workload, and the Strategic Response of Coaches in the NBA", "authors": ["Kala Krishna", "Sergey Lychagin", "Lewis S. McLean"], "author_details": [{"name": "Kala Krishna", "affiliations": []}, {"name": "Sergey Lychagin", "affiliations": []}, {"name": "Lewis S. McLean", "affiliations": []}], "abstract": "Worker effort increases contemporaneous output but may result in injury or burnout. Directing effort away from the workers most exposed to injury would reduce this risk, but information on the exposure is often hidden. We ask whether managers act on such private information, studying the NBA as a data-rich workplace. Instrumenting workload with teammate absence, we find that work causally raises injury risk, which contrasts with the spurious negative correlation commonly found in sports medicine studies. We also show that coaches rest players in response to injury risk shocks. By acting on this private information, coaches can raise player productivity.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35803", "title_zh": "\u4f24\u75c5\u3001\u5de5\u4f5c\u91cf\u4e0eNBA\u6559\u7ec3\u7684\u6218\u7565\u5e94\u5bf9", "abstract_zh": "\u5de5\u4eba\u52aa\u529b\u4f1a\u63d0\u9ad8\u5f53\u671f\u4ea7\u51fa\uff0c\u4f46\u53ef\u80fd\u5bfc\u81f4\u4f24\u75c5\u6216\u5026\u6020\u3002\u5c06\u52aa\u529b\u8f6c\u5411\u6700\u6613\u53d7\u4f24\u7684\u7403\u5458\u4e4b\u5916\uff0c\u53ef\u4ee5\u964d\u4f4e\u8fd9\u79cd\u98ce\u9669\uff0c\u4f46\u5173\u4e8e\u66b4\u9732\u7a0b\u5ea6\u7684\u4fe1\u606f\u5f80\u5f80\u88ab\u9690\u85cf\u3002\u6211\u4eec\u63a2\u8ba8\u7ba1\u7406\u8005\u662f\u5426\u4f1a\u5229\u7528\u6b64\u7c7b\u79c1\u4eba\u4fe1\u606f\uff0c\u4ee5NBA\u4f5c\u4e3a\u6570\u636e\u4e30\u5bcc\u7684\u804c\u573a\u8fdb\u884c\u7814\u7a76\u3002\u901a\u8fc7\u7528\u961f\u53cb\u7f3a\u5e2d\u6765\u5de5\u5177\u5316\u5de5\u4f5c\u91cf\uff0c\u6211\u4eec\u53d1\u73b0\u5de5\u4f5c\u786e\u5b9e\u4f1a\u63d0\u9ad8\u4f24\u75c5\u98ce\u9669\uff0c\u8fd9\u4e0e\u4f53\u80b2\u533b\u5b66\u7814\u7a76\u4e2d\u5e38\u89c1\u7684\u865a\u5047\u8d1f\u76f8\u5173\u7ed3\u679c\u5f62\u6210\u5bf9\u6bd4\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0c\u6559\u7ec3\u4f1a\u6839\u636e\u4f24\u75c5\u98ce\u9669\u51b2\u51fb\u8c03\u6574\u7403\u5458\u7684\u4f11\u606f\u5b89\u6392\u3002\u901a\u8fc7\u5229\u7528\u8fd9\u4e00\u79c1\u4eba\u4fe1\u606f\uff0c\u6559\u7ec3\u80fd\u591f\u63d0\u5347\u7403\u5458\u7684\u751f\u4ea7\u6548\u7387\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35804", "journal": "NBER", "title": "Beveridgean Phillips Curve", "authors": ["Pascal Michaillat", "Emmanuel Saez"], "author_details": [{"name": "Pascal Michaillat", "affiliations": []}, {"name": "Emmanuel Saez", "affiliations": []}], "abstract": "This paper develops a Beveridgean model of the Phillips curve. While the New Keynesian Phillips curve is based on monopolistic pricing under price-adjustment costs, the Beveridgean Phillips curve is based on directed-search pricing under price-adjustment costs. Under directed search, prices respond to slack instead of marginal costs. The resulting Phillips curve has three properties that match recent US evidence. First, it delivers the divine coincidence: inflation is on target whenever unemployment is at its efficient level\u2014the full-employment rate of unemployment (FERU), the geometric mean of the unemployment and vacancy rates. Second, it is decreasing and convex in the unemployment-inflation plane: inflation responds more strongly to unemployment when the labor market is inefficiently tight than when it is inefficiently slack. The convexity is inherited from the Beveridge curve, which makes unemployment a decreasing and convex function of tightness. Third, shifts of the Beveridge curve move the FERU and therefore shift the unemployment-inflation Phillips curve. The model also implies that the Fed's dual mandate is internally consistent, that a soft landing from an inefficiently tight labor market is possible, and that the zero lower bound is not topsy-turvy.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35804", "title_zh": "\u8d1d\u5f17\u91cc\u5947\u83f2\u5229\u666e\u65af\u66f2\u7ebf", "abstract_zh": "\u672c\u6587\u6784\u5efa\u4e86\u4e00\u4e2a\u57fa\u4e8e\u5b9a\u5411\u641c\u7d22\u5b9a\u4ef7\u7684\u83f2\u5229\u666e\u65af\u66f2\u7ebf\u6a21\u578b\u3002\u4e0e\u65b0\u51ef\u6069\u65af\u4e3b\u4e49\u83f2\u5229\u666e\u65af\u66f2\u7ebf\u57fa\u4e8e\u5784\u65ad\u5b9a\u4ef7\u548c\u4ef7\u683c\u8c03\u6574\u6210\u672c\u4e0d\u540c\uff0c\u8d1d\u5f17\u91cc\u5947\u83f2\u5229\u666e\u65af\u66f2\u7ebf\u57fa\u4e8e\u5b9a\u5411\u641c\u7d22\u5b9a\u4ef7\u548c\u4ef7\u683c\u8c03\u6574\u6210\u672c\u3002\u5728\u5b9a\u5411\u641c\u7d22\u4e0b\uff0c\u4ef7\u683c\u54cd\u5e94\u7684\u662f\u5e02\u573a\u7a7a\u7f3a\u7a0b\u5ea6\u800c\u975e\u8fb9\u9645\u6210\u672c\u3002\u7531\u6b64\u4ea7\u751f\u7684\u83f2\u5229\u666e\u65af\u66f2\u7ebf\u5177\u6709\u4e09\u4e2a\u4e0e\u8fd1\u671f\u7f8e\u56fd\u6570\u636e\u76f8\u7b26\u7684\u7279\u6027\u3002\u9996\u5148\uff0c\u8be5\u6a21\u578b\u5b9e\u73b0\u4e86\u2018\u795e\u5723\u5de7\u5408\u2019\uff1a\u5f53\u5931\u4e1a\u7387\u5904\u4e8e\u5176\u6709\u6548\u6c34\u5e73\u2014\u2014\u5373\u5931\u4e1a\u7387\u4e0e\u7a7a\u7f3a\u7387\u7684\u51e0\u4f55\u5e73\u5747\u503c\uff08\u5373\u5145\u5206\u5c31\u4e1a\u5931\u4e1a\u7387\uff0cFERU\uff09\u65f6\uff0c\u901a\u8d27\u81a8\u80c0\u59cb\u7ec8\u5904\u4e8e\u76ee\u6807\u6c34\u5e73\u3002\u5176\u6b21\uff0c\u8be5\u66f2\u7ebf\u5728\u5931\u4e1a\u7387-\u901a\u8d27\u81a8\u80c0\u5e73\u9762\u4e0a\u662f\u9012\u51cf\u4e14\u51f8\u7684\uff1a\u5f53\u52b3\u52a8\u529b\u5e02\u573a\u5904\u4e8e\u975e\u6709\u6548\u7d27\u7f29\u72b6\u6001\u65f6\uff0c\u901a\u8d27\u81a8\u80c0\u5bf9\u5931\u4e1a\u7387\u7684\u53cd\u5e94\u6bd4\u5728\u975e\u6709\u6548\u5bbd\u677e\u72b6\u6001\u65f6\u66f4\u5f3a\u70c8\u3002\u8fd9\u79cd\u51f8\u6027\u6e90\u81ea\u8d1d\u5f17\u91cc\u5947\u66f2\u7ebf\u672c\u8eab\uff0c\u5373\u5931\u4e1a\u7387\u662f\u7d27\u7f29\u7a0b\u5ea6\u7684\u9012\u51cf\u4e14\u51f8\u51fd\u6570\u3002\u7b2c\u4e09\uff0c\u8d1d\u5f17\u91cc\u5947\u66f2\u7ebf\u7684\u79fb\u52a8\u4f1a\u6539\u53d8\u5145\u5206\u5c31\u4e1a\u5931\u4e1a\u7387\uff08FERU\uff09\uff0c\u4ece\u800c\u5bfc\u81f4\u5931\u4e1a\u7387-\u901a\u8d27\u81a8\u80c0\u83f2\u5229\u666e\u65af\u66f2\u7ebf\u7684\u79fb\u52a8\u3002\u8be5\u6a21\u578b\u8fd8\u8868\u660e\uff0c\u7f8e\u8054\u50a8\u7684\u53cc\u91cd\u76ee\u6807\u662f\u5185\u5728\u4e00\u81f4\u7684\uff0c\u4ece\u975e\u6709\u6548\u7d27\u7f29\u7684\u52b3\u52a8\u529b\u5e02\u573a\u5b9e\u73b0\u8f6f\u7740\u9646\u662f\u53ef\u80fd\u7684\uff0c\u4e14\u96f6\u4e0b\u9650\u5e76\u975e\u98a0\u5012\u5f02\u5e38\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35805", "journal": "NBER", "title": "Foreign Tax Advantages after the U.S. Tax Reform of 2017", "authors": ["Anmol Bhandari", "Ellen McGrattan"], "author_details": [{"name": "Anmol Bhandari", "affiliations": []}, {"name": "Ellen McGrattan", "affiliations": []}], "abstract": "We construct a firm-year panel of income-tax rate reconciliations from annual 10-K filings of public companies to study the effects of the Tax Cuts and Jobs Act (TCJA) on U.S. multinational profit shifting. These reconciliations decompose the gap between company-level effective tax rates and the federal statutory corporate tax rate, allowing us to isolate the contribution of foreign tax advantages before and after the reform. We find that TCJA significantly reduced the tax rate gap and increased effective tax rates for companies most exposed to pre-TCJA international tax benefits. This resulted in an onshoring of profits with foreign profit shares falling 1.3 percentage points per percentage point of tax increase. Among more exposed companies, we find no differential change in investment, employment, or the geographic distribution of sales and installed capital. A neoclassical model of a multinational that chooses where to book its income rationalizes this pattern: the reform raised the average tax on income booked abroad relative to income booked at home, which governs where profits are reported, while the marginal tax on capital, which governs investment, changed by an amount common to all firms. Controlling for deferred-tax windfall gains leaves our main results unchanged.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35805", "title_zh": "2017\u5e74\u7f8e\u56fd\u7a0e\u6539\u4e4b\u540e\u7684\u5916\u56fd\u7a0e\u6536\u4f18\u60e0", "abstract_zh": "\u6211\u4eec\u57fa\u4e8e\u516c\u5f00\u516c\u53f8\u5e74\u5ea610-K\u6587\u4ef6\u4e2d\u7684\u6240\u5f97\u7a0e\u7a0e\u7387\u8c03\u6574\u6570\u636e\uff0c\u6784\u5efa\u4e86\u4e00\u4e2a\u4f01\u4e1a\u5e74\u5ea6\u9762\u677f\u6570\u636e\uff0c\u4ee5\u7814\u7a76\u300a\u51cf\u7a0e\u4e0e\u5c31\u4e1a\u6cd5\u6848\u300b\uff08TCJA\uff09\u5bf9\u7f8e\u56fd\u8de8\u56fd\u4f01\u4e1a\u5229\u6da6\u8f6c\u79fb\u7684\u5f71\u54cd\u3002\u8fd9\u4e9b\u8c03\u6574\u6570\u636e\u5206\u89e3\u4e86\u516c\u53f8\u5c42\u9762\u5b9e\u9645\u7a0e\u7387\u4e0e\u8054\u90a6\u516c\u53f8\u6240\u5f97\u7a0e\u6cd5\u5b9a\u7a0e\u7387\u4e4b\u95f4\u7684\u5dee\u8ddd\uff0c\u4f7f\u6211\u4eec\u80fd\u591f\u5206\u79bb\u51fa\u6539\u9769\u524d\u540e\u7684\u5916\u56fd\u7a0e\u6536\u4f18\u60e0\u8d21\u732e\u3002\u7814\u7a76\u53d1\u73b0\uff0cTCJA\u663e\u8457\u7f29\u5c0f\u4e86\u7a0e\u7387\u5dee\u8ddd\uff0c\u5e76\u63d0\u9ad8\u4e86\u90a3\u4e9b\u5728\u6539\u9769\u524d\u9ad8\u5ea6\u4f9d\u8d56\u56fd\u9645\u7a0e\u6536\u4f18\u60e0\u7684\u4f01\u4e1a\u5b9e\u9645\u7a0e\u7387\u3002\u8fd9\u5bfc\u81f4\u5229\u6da6\u5411\u56fd\u5185\u8f6c\u79fb\uff0c\u6bcf\u589e\u52a01\u4e2a\u767e\u5206\u70b9\u7684\u7a0e\u7387\uff0c\u6d77\u5916\u5229\u6da6\u4efd\u989d\u4e0b\u964d1.3\u4e2a\u767e\u5206\u70b9\u3002\u5bf9\u4e8e\u66f4\u4f9d\u8d56\u56fd\u9645\u7a0e\u6536\u4f18\u60e0\u7684\u4f01\u4e1a\uff0c\u6211\u4eec\u5e76\u672a\u53d1\u73b0\u6295\u8d44\u3001\u5c31\u4e1a\u6216\u9500\u552e\u53ca\u56fa\u5b9a\u8d44\u4ea7\u5730\u7406\u5206\u5e03\u53d1\u751f\u663e\u8457\u53d8\u5316\u3002\u4e00\u4e2a\u8de8\u56fd\u4f01\u4e1a\u7684\u65b0\u53e4\u5178\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u5047\u8bbe\u4f01\u4e1a\u81ea\u4e3b\u9009\u62e9\u6536\u5165\u5f52\u5c5e\u5730\uff0c\u53ef\u4ee5\u89e3\u91ca\u8fd9\u4e00\u73b0\u8c61\uff1a\u6539\u9769\u63d0\u9ad8\u4e86\u6d77\u5916\u6536\u5165\u7533\u62a5\u76f8\u5bf9\u4e8e\u56fd\u5185\u6536\u5165\u7533\u62a5\u7684\u5e73\u5747\u7a0e\u7387\uff0c\u4ece\u800c\u5f71\u54cd\u4e86\u5229\u6da6\u7684\u62a5\u544a\u5730\u70b9\uff0c\u800c\u8d44\u672c\u7684\u8fb9\u9645\u7a0e\u7387\u53d8\u5316\u5bf9\u6240\u6709\u4f01\u4e1a\u800c\u8a00\u662f\u76f8\u540c\u7684\u3002\u5728\u63a7\u5236\u4e86\u9012\u5ef6\u6240\u5f97\u7a0e\u610f\u5916\u6536\u76ca\u540e\uff0c\u6211\u4eec\u7684\u4e3b\u8981\u7ed3\u8bba\u4fdd\u6301\u4e0d\u53d8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35806", "journal": "NBER", "title": "Deep Learning as a Projection Method for Solving Economic Models", "authors": ["Kenneth L. Judd", "Karl Schmedders"], "author_details": [{"name": "Kenneth L. Judd", "affiliations": []}, {"name": "Karl Schmedders", "affiliations": []}], "abstract": "Deep learning is increasingly presented in economics as a new paradigm for solving dynamic models, superseding the classical projection methods of numerical economics. We argue that this dichotomy rests on a misclassification. The neural-network solvers emphasized in this literature are least-squares projection methods with an adaptive nonlinear parameterization. Placing deep learning inside the projection family reorients the agenda. The issue is not a contest between paradigms, but suggests a single toolkit using a variety of approximation methods, residual criteria, and evaluation designs to be chosen on the merits for the model at hand. In low and moderate dimensions, linear-basis and sparsegrid methods are often more accurate, faster, and easier to verify than a trained neural network. In high dimensions, an appropriate choice for the space of permissible functions will often avoid the curse of dimensionality.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35806", "title_zh": "\u6df1\u5ea6\u5b66\u4e60\u4f5c\u4e3a\u6c42\u89e3\u7ecf\u6d4e\u6a21\u578b\u7684\u6295\u5f71\u65b9\u6cd5", "abstract_zh": "\u6df1\u5ea6\u5b66\u4e60\u6b63\u8d8a\u6765\u8d8a\u591a\u5730\u88ab\u5f15\u5165\u7ecf\u6d4e\u5b66\u9886\u57df\uff0c\u4f5c\u4e3a\u6c42\u89e3\u52a8\u6001\u6a21\u578b\u7684\u4e00\u79cd\u65b0\u8303\u5f0f\uff0c\u53d6\u4ee3\u4e86\u6570\u503c\u7ecf\u6d4e\u5b66\u4e2d\u7684\u7ecf\u5178\u6295\u5f71\u65b9\u6cd5\u3002\u6211\u4eec\u8ba4\u4e3a\uff0c\u8fd9\u79cd\u4e8c\u5143\u5bf9\u7acb\u6e90\u4e8e\u5bf9\u65b9\u6cd5\u7684\u8bef\u5206\u7c7b\u3002\u5f53\u524d\u6587\u732e\u4e2d\u5f3a\u8c03\u7684\u795e\u7ecf\u7f51\u7edc\u6c42\u89e3\u5668\u672c\u8d28\u4e0a\u662f\u5e26\u6709\u81ea\u9002\u5e94\u975e\u7ebf\u6027\u53c2\u6570\u5316\u7684\u6700\u5c0f\u4e8c\u4e58\u6295\u5f71\u65b9\u6cd5\u3002\u5c06\u6df1\u5ea6\u5b66\u4e60\u7eb3\u5165\u6295\u5f71\u65b9\u6cd5\u5bb6\u65cf\uff0c\u91cd\u65b0\u5b9a\u4e49\u4e86\u7814\u7a76\u8bae\u7a0b\u3002\u95ee\u9898\u5e76\u975e\u8303\u5f0f\u4e4b\u95f4\u7684\u7ade\u4e89\uff0c\u800c\u662f\u5efa\u8bae\u91c7\u7528\u4e00\u4e2a\u7edf\u4e00\u7684\u5de5\u5177\u7bb1\uff0c\u6839\u636e\u5177\u4f53\u6a21\u578b\u7684\u7279\u6027\uff0c\u7075\u6d3b\u9009\u62e9\u4e0d\u540c\u7684\u8fd1\u4f3c\u65b9\u6cd5\u3001\u6b8b\u5dee\u6807\u51c6\u548c\u8bc4\u4f30\u8bbe\u8ba1\u3002\u5728\u4f4e\u7ef4\u548c\u4e2d\u7b49\u7ef4\u5ea6\u4e0b\uff0c\u7ebf\u6027\u57fa\u51fd\u6570\u548c\u7a00\u758f\u7f51\u683c\u65b9\u6cd5\u901a\u5e38\u6bd4\u8bad\u7ec3\u597d\u7684\u795e\u7ecf\u7f51\u7edc\u66f4\u51c6\u786e\u3001\u66f4\u5feb\uff0c\u4e14\u66f4\u5bb9\u6613\u9a8c\u8bc1\u3002\u5728\u9ad8\u7ef4\u60c5\u51b5\u4e0b\uff0c\u5408\u7406\u9009\u62e9\u5141\u8bb8\u51fd\u6570\u7684\u7a7a\u95f4\u5f80\u5f80\u80fd\u591f\u907f\u514d\u7ef4\u5ea6\u707e\u96be\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc", "AI"]}, {"doi": "10.3386/w35807", "journal": "NBER", "title": "Network General Equilibrium as a Threat to Identification: The Failure of Time Fixed Effects", "authors": ["Bernard Herskovic", "Gill Segal"], "author_details": [{"name": "Bernard Herskovic", "affiliations": []}, {"name": "Gill Segal", "affiliations": []}], "abstract": "Time fixed effects are not a general-equilibrium control. In network economies, aggregate shocks do not enter firm outcomes uniformly: they propagate through equilibrium prices, costs, and demand, leaving a residual network gradient after time demeaning. When an instrument, treatment, or exposure design even partially aligns with this gradient, standard panel estimators recover the direct effect plus an endogenous network-leakage component. We develop a tractable framework that signs and quantifies this Network-SUTVA bias in closed form, showing how network topology governs its magnitude. Weak instruments magnify the leakage. Difference-in-differences designs are similarly contaminated because controls can be untreated by assignment but treated in equilibrium. Calibrated to the U.S. production network, the distortion can exceed 130% of the true direct effect. We propose observed- and hidden-network diagnostics and remedies, and test them on canonical difference-in-differences designs, showing that standard estimators can confound direct policy responses with systemic network leakage.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35807", "title_zh": "\u7f51\u7edc\u4e00\u822c\u5747\u8861\u5bf9\u8bc6\u522b\u7684\u5a01\u80c1\uff1a\u65f6\u95f4\u56fa\u5b9a\u6548\u5e94\u7684\u5931\u6548", "abstract_zh": "\u65f6\u95f4\u56fa\u5b9a\u6548\u5e94\u5e76\u975e\u4e00\u822c\u5747\u8861\u7684\u63a7\u5236\u53d8\u91cf\u3002\u5728\u7f51\u7edc\u7ecf\u6d4e\u4e2d\uff0c\u603b\u51b2\u51fb\u4e0d\u4f1a\u5747\u5300\u5730\u5f71\u54cd\u4f01\u4e1a\u7ed3\u679c\uff1a\u5b83\u4eec\u901a\u8fc7\u5747\u8861\u4ef7\u683c\u3001\u6210\u672c\u548c\u9700\u6c42\u4f20\u64ad\uff0c\u7ecf\u65f6\u95f4\u53bb\u5747\u503c\u540e\u4ecd\u7559\u4e0b\u4e00\u4e2a\u7f51\u7edc\u68af\u5ea6\u3002\u5f53\u4e00\u4e2a\u5de5\u5177\u3001\u5904\u7406\u6216\u66b4\u9732\u8bbe\u8ba1\u90e8\u5206\u4e0e\u8fd9\u4e00\u68af\u5ea6\u76f8\u4e00\u81f4\u65f6\uff0c\u6807\u51c6\u9762\u677f\u4f30\u8ba1\u65b9\u6cd5\u4f1a\u6062\u590d\u76f4\u63a5\u6548\u5e94\u52a0\u4e0a\u4e00\u4e2a\u5185\u751f\u7684\u7f51\u7edc\u6cc4\u6f0f\u6210\u5206\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u53ef\u5904\u7406\u7684\u6846\u67b6\uff0c\u4ee5\u5c01\u95ed\u5f62\u5f0f\u8bc6\u522b\u5e76\u91cf\u5316\u8fd9\u79cd\u7f51\u7edcSUTVA\u504f\u5dee\uff0c\u8868\u660e\u7f51\u7edc\u7ed3\u6784\u51b3\u5b9a\u4e86\u5176\u5927\u5c0f\u3002\u5f31\u5de5\u5177\u4f1a\u653e\u5927\u8fd9\u79cd\u6cc4\u6f0f\u3002\u5dee\u5f02-in-\u5dee\u5f02\u8bbe\u8ba1\u540c\u6837\u53d7\u5230\u6c61\u67d3\uff0c\u56e0\u4e3a\u63a7\u5236\u53d8\u91cf\u53ef\u80fd\u5728\u5206\u914d\u4e2d\u672a\u88ab\u5904\u7406\uff0c\u4f46\u5728\u5747\u8861\u4e2d\u88ab\u5904\u7406\u3002\u57fa\u4e8e\u7f8e\u56fd\u751f\u4ea7\u7f51\u7edc\u8fdb\u884c\u6821\u51c6\uff0c\u8fd9\u79cd\u504f\u5dee\u53ef\u80fd\u8d85\u8fc7\u771f\u5b9e\u76f4\u63a5\u6548\u5e94\u7684130%\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u57fa\u4e8e\u89c2\u6d4b\u7f51\u7edc\u548c\u9690\u85cf\u7f51\u7edc\u7684\u8bca\u65ad\u65b9\u6cd5\u53ca\u4fee\u6b63\u65b9\u6848\uff0c\u5e76\u5728\u5178\u578b\u5dee\u5f02-in-\u5dee\u5f02\u8bbe\u8ba1\u4e2d\u8fdb\u884c\u6d4b\u8bd5\uff0c\u7ed3\u679c\u8868\u660e\u6807\u51c6\u4f30\u8ba1\u65b9\u6cd5\u53ef\u80fd\u5c06\u76f4\u63a5\u653f\u7b56\u54cd\u5e94\u4e0e\u7cfb\u7edf\u6027\u7f51\u7edc\u6cc4\u6f0f\u6df7\u6dc6\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.3386/w35808", "journal": "NBER", "title": "Shipping to America", "authors": ["Xiwen Bai", "Jes\u00fas Fern\u00e1ndez-Villaverde", "Yiliang Li", "Ricardo Marto", "Francesco Zanetti"], "author_details": [{"name": "Xiwen Bai", "affiliations": []}, {"name": "Jes\u00fas Fern\u00e1ndez-Villaverde", "affiliations": []}, {"name": "Yiliang Li", "affiliations": []}, {"name": "Ricardo Marto", "affiliations": []}, {"name": "Francesco Zanetti", "affiliations": []}], "abstract": "We study the macroeconomic and trade-policy implications of disruptions to U.S.-bound shipping routes. Standard models treat them as iceberg-cost shocks, conflating the shock with the response to it. Using satellite vessel-tracking data, we construct route-level measures of potential and effective capacity for all U.S.-bound container ships from 2016 to 2025. Utilization losses in recent disruptions ran 20 to 40 percentage points, and began months before port congestion became visible. We embed these measures in a general equilibrium model in which firms reallocate a common fleet without internalizing the congestion they create and price above marginal cost, while importers' sourcing responds to route profitability. The reallocation triggered by a disruption then has first-order welfare effects, and the route's Domar weight is not a sufficient statistic for its welfare cost. The 2021 West Coast crisis and the 2023-2024 Red Sea attacks cost 0.69% and 0.35% of output. Naval protection of Red Sea shipping generated benefits of 0.04-0.08% of output at a fiscal cost of 0.02%. Tariffs decongest the routes they tax, offsetting or even reversing their conventional welfare cost.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35808", "title_zh": "\u8fd0\u5f80\u7f8e\u56fd", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5bf9\u7f8e\u56fd\u822a\u7ebf\u822a\u8fd0\u8def\u7ebf\u7684\u4e2d\u65ad\u6240\u4ea7\u751f\u7684\u5b8f\u89c2\u7ecf\u6d4e\u548c\u8d38\u6613\u653f\u7b56\u5f71\u54cd\u3002\u6807\u51c6\u6a21\u578b\u5c06\u8fd9\u4e9b\u4e2d\u65ad\u89c6\u4e3a\u51b0\u5c71\u6210\u672c\u51b2\u51fb\uff0c\u5c06\u51b2\u51fb\u4e0e\u5bf9\u51b2\u51fb\u7684\u53cd\u5e94\u6df7\u4e3a\u4e00\u8c08\u3002\u5229\u7528\u536b\u661f\u8239\u8236\u8ddf\u8e2a\u6570\u636e\uff0c\u6211\u4eec\u6784\u5efa\u4e862016\u5e74\u81f32025\u5e74\u95f4\u6240\u6709\u5f00\u5f80\u7f8e\u56fd\u7684\u96c6\u88c5\u7bb1\u8239\u7684\u6f5c\u5728\u5bb9\u91cf\u548c\u6709\u6548\u5bb9\u91cf\u7684\u822a\u7ebf\u7ea7\u6307\u6807\u3002\u8fd1\u671f\u4e2d\u65ad\u5bfc\u81f4\u7684\u5229\u7528\u7387\u635f\u5931\u572820\u523040\u4e2a\u767e\u5206\u70b9\u4e4b\u95f4\uff0c\u5e76\u5728\u6e2f\u53e3\u62e5\u5835\u53d8\u5f97\u660e\u663e\u4e4b\u524d\u6570\u6708\u5c31\u5f00\u59cb\u51fa\u73b0\u3002\u6211\u4eec\u5c06\u8fd9\u4e9b\u6307\u6807\u5d4c\u5165\u4e00\u4e2a\u4e00\u822c\u5747\u8861\u6a21\u578b\u4e2d\uff0c\u5176\u4e2d\u4f01\u4e1a\u91cd\u65b0\u5206\u914d\u5171\u540c\u7684\u8239\u961f\uff0c\u4f46\u672a\u5185\u90e8\u5316\u5176\u5f15\u53d1\u7684\u62e5\u5835\uff0c\u5e76\u4e14\u4ef7\u683c\u9ad8\u4e8e\u8fb9\u9645\u6210\u672c\uff0c\u800c\u8fdb\u53e3\u5546\u7684\u91c7\u8d2d\u884c\u4e3a\u5219\u6839\u636e\u822a\u7ebf\u7684\u76c8\u5229\u80fd\u529b\u8fdb\u884c\u8c03\u6574\u3002\u7531\u4e2d\u65ad\u5f15\u53d1\u7684\u91cd\u65b0\u5206\u914d\u4ea7\u751f\u4e86\u76f4\u63a5\u7684\u798f\u5229\u6548\u5e94\uff0c\u4e14\u822a\u7ebf\u7684\u591a\u59c6\u6743\u91cd\u4e0d\u8db3\u4ee5\u53cd\u6620\u5176\u798f\u5229\u6210\u672c\u30022021\u5e74\u897f\u6d77\u5cb8\u5371\u673a\u548c2023-2024\u5e74\u7ea2\u6d77\u88ad\u51fb\u5206\u522b\u5bfc\u81f4\u4e860.69%\u548c0.35%\u7684\u4ea7\u51fa\u635f\u5931\u3002\u5bf9\u7ea2\u6d77\u822a\u8fd0\u7684\u6d77\u519b\u4fdd\u62a4\u5e26\u6765\u4e860.04%\u81f30.08%\u7684\u4ea7\u51fa\u6536\u76ca\uff0c\u4f46\u8d22\u653f\u6210\u672c\u4e3a0.02%\u3002\u5173\u7a0e\u5728\u7f13\u89e3\u88ab\u5f81\u7a0e\u8def\u7ebf\u7684\u62e5\u5835\u65b9\u9762\u53d1\u6325\u4e86\u4f5c\u7528\uff0c\u62b5\u6d88\u751a\u81f3\u9006\u8f6c\u4e86\u5176\u4f20\u7edf\u610f\u4e49\u4e0a\u7684\u798f\u5229\u6210\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.3386/w35809", "journal": "NBER", "title": "Terra Incognita: The Economics of a Shrinking World", "authors": ["Jes\u00fas Fern\u00e1ndez-Villaverde", "Patrick Norrick"], "author_details": [{"name": "Jes\u00fas Fern\u00e1ndez-Villaverde", "affiliations": []}, {"name": "Patrick Norrick", "affiliations": []}], "abstract": "As of 2026, humanity is likely below replacement fertility. That has never happened before, not in wars or pandemics. But the real surprise is that the fall has been concentrated in low- and middle-income countries and among poorer and less educated women. We fit a single-factor model to 236 countries since 1950: the common component peaked in 1978, and what drives fertility down today are country-specific trends, 219 of them negative and not one leveling off. None of the commonly cited mechanisms can account for this pattern, so we offer a conjecture: modernity itself, which makes a third child expensive and childlessness cheap. Children come in integers, so it takes very little to move a cohort\u2019s fertility rate from 1.8 to 1.3. And nothing in an economy pushes fertility back to 2.1. We close with the main economic consequences, in particular slow growth.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35809", "title_zh": "\u672a\u77e5\u4e4b\u5730\uff1a\u4e00\u4e2a\u7f29\u5c0f\u4e16\u754c\u4e2d\u7684\u7ecf\u6d4e\u5b66", "abstract_zh": "\u52302026\u5e74\uff0c\u4eba\u7c7b\u7684\u751f\u80b2\u7387\u5f88\u53ef\u80fd\u4f4e\u4e8e\u66f4\u66ff\u6c34\u5e73\u3002\u8fd9\u79cd\u60c5\u51b5\u4ee5\u524d\u4ece\u672a\u53d1\u751f\u8fc7\uff0c\u65e0\u8bba\u662f\u6218\u4e89\u8fd8\u662f\u75ab\u60c5\u3002\u771f\u6b63\u7684\u610f\u5916\u662f\uff0c\u8fd9\u4e00\u4e0b\u964d\u8d8b\u52bf\u96c6\u4e2d\u5728\u4f4e\u6536\u5165\u548c\u4e2d\u7b49\u6536\u5165\u56fd\u5bb6\uff0c\u4ee5\u53ca\u6536\u5165\u8f83\u4f4e\u548c\u6559\u80b2\u7a0b\u5ea6\u8f83\u5f31\u7684\u5973\u6027\u7fa4\u4f53\u4e2d\u3002\u6211\u4eec\u5bf91950\u5e74\u4ee5\u6765\u7684236\u4e2a\u56fd\u5bb6\u6784\u5efa\u4e86\u4e00\u4e2a\u5355\u56e0\u5b50\u6a21\u578b\uff1a\u5171\u540c\u6210\u5206\u57281978\u5e74\u8fbe\u5230\u5cf0\u503c\uff0c\u800c\u5f53\u524d\u63a8\u52a8\u751f\u80b2\u7387\u4e0b\u964d\u7684\u5219\u662f\u5404\u56fd\u7279\u6709\u7684\u8d8b\u52bf\uff0c\u5176\u4e2d219\u4e2a\u4e3a\u8d1f\u5411\u8d8b\u52bf\uff0c\u4e14\u6ca1\u6709\u4e00\u4e2a\u8d8b\u4e8e\u5e73\u7f13\u3002\u76ee\u524d\u88ab\u5e7f\u6cdb\u63d0\u53ca\u7684\u673a\u5236\u90fd\u65e0\u6cd5\u89e3\u91ca\u8fd9\u4e00\u73b0\u8c61\uff0c\u56e0\u6b64\u6211\u4eec\u63d0\u51fa\u4e00\u4e2a\u5047\u8bbe\uff1a\u73b0\u4ee3\u6027\u672c\u8eab\u4f7f\u5f97\u751f\u80b2\u7b2c\u4e09\u4e2a\u5b69\u5b50\u53d8\u5f97\u6602\u8d35\uff0c\u800c\u65e0\u5b50\u5973\u53d8\u5f97\u5ec9\u4ef7\u3002\u5b69\u5b50\u6570\u91cf\u662f\u6574\u6570\uff0c\u56e0\u6b64\u53ea\u9700\u6781\u5c0f\u7684\u53d8\u52a8\uff0c\u5c31\u80fd\u4f7f\u4e00\u4e2a\u7fa4\u4f53\u7684\u751f\u80b2\u7387\u4ece1.8\u4e0b\u964d\u52301.3\u3002\u800c\u7ecf\u6d4e\u4f53\u7cfb\u4e2d\u6ca1\u6709\u4efb\u4f55\u56e0\u7d20\u80fd\u591f\u5c06\u751f\u80b2\u7387\u62c9\u56de\u52302.1\u3002\u6211\u4eec\u6700\u540e\u603b\u7ed3\u4e86\u4e3b\u8981\u7684\u7ecf\u6d4e\u540e\u679c\uff0c\u5c24\u5176\u662f\u7ecf\u6d4e\u589e\u957f\u7684\u653e\u7f13\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.3386/w35810", "journal": "NBER", "title": "Like a Good Neighbor: Childhood Neighbors Influence Occupation Choice", "authors": ["Michael J. Andrews", "Ryan R. Hill", "Joseph Price", "Riley Wilson"], "author_details": [{"name": "Michael J. Andrews", "affiliations": []}, {"name": "Ryan R. Hill", "affiliations": []}, {"name": "Joseph Price", "affiliations": []}, {"name": "Riley Wilson", "affiliations": []}], "abstract": "Occupation choice is a key determinant of economic mobility. This paper studies how childhood neighbors influence occupational choices and later-life earnings. Using linked historical U.S. census records for over six million boys and four million girls, we reconstruct neighborhood microgeography to identify childhood neighbors and their occupations. We find that living next door to someone in a given occupation increases the probability of working in that same occupation 30 years later by about 10 percent relative to other children on the same street. The transmission effect is higher with more intense exposure, in more connected neighborhoods, and when neighboring families are more similar. Exposure to high-income or highly educated neighbors has lasting economic effects, leading to significant gains in adult income and education even compared to other children from the same street. These findings suggest that neighborhood networks play an important role in shaping intergenerational economic mobility.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35810", "title_zh": "\u50cf\u597d\u90bb\u5c45\u4e00\u6837\uff1a\u7ae5\u5e74\u90bb\u5c45\u5f71\u54cd\u804c\u4e1a\u9009\u62e9", "abstract_zh": "\u804c\u4e1a\u9009\u62e9\u662f\u7ecf\u6d4e\u6d41\u52a8\u6027\u7684\u91cd\u8981\u51b3\u5b9a\u56e0\u7d20\u3002\u672c\u6587\u7814\u7a76\u4e86\u7ae5\u5e74\u90bb\u5c45\u5982\u4f55\u5f71\u54cd\u804c\u4e1a\u9009\u62e9\u4ee5\u53ca\u6210\u5e74\u540e\u7684\u6536\u5165\u3002\u5229\u7528\u8d85\u8fc7\u516d\u767e\u4e07\u540d\u7537\u5b69\u548c\u56db\u767e\u4e07\u540d\u5973\u5b69\u7684\u94fe\u63a5\u5386\u53f2\u7f8e\u56fd\u4eba\u53e3\u666e\u67e5\u6570\u636e\uff0c\u6211\u4eec\u91cd\u5efa\u4e86\u90bb\u91cc\u5fae\u89c2\u5730\u7406\u4fe1\u606f\uff0c\u4ee5\u8bc6\u522b\u7ae5\u5e74\u90bb\u5c45\u53ca\u5176\u804c\u4e1a\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u4e0e\u67d0\u4e2a\u804c\u4e1a\u7684\u90bb\u5c45\u5171\u540c\u751f\u6d3b\uff0c\u4f1a\u4f7f30\u5e74\u540e\u4ece\u4e8b\u8be5\u804c\u4e1a\u7684\u6982\u7387\u6bd4\u540c\u8857\u5176\u4ed6\u5b69\u5b50\u9ad8\u51fa\u7ea610%\u3002\u8fd9\u79cd\u5f71\u54cd\u5728\u66b4\u9732\u66f4\u5f3a\u70c8\u3001\u90bb\u91cc\u8054\u7cfb\u66f4\u7d27\u5bc6\u4ee5\u53ca\u90bb\u5c45\u5bb6\u5ead\u66f4\u76f8\u4f3c\u7684\u60c5\u51b5\u4e0b\u66f4\u4e3a\u663e\u8457\u3002\u63a5\u89e6\u9ad8\u6536\u5165\u6216\u9ad8\u5b66\u5386\u90bb\u5c45\u4f1a\u5e26\u6765\u6301\u4e45\u7684\u7ecf\u6d4e\u6548\u5e94\uff0c\u5373\u4f7f\u4e0e\u5176\u4ed6\u540c\u8857\u513f\u7ae5\u76f8\u6bd4\uff0c\u4e5f\u4f1a\u663e\u8457\u63d0\u5347\u6210\u5e74\u540e\u7684\u6536\u5165\u548c\u6559\u80b2\u6c34\u5e73\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u90bb\u91cc\u7f51\u7edc\u5728\u5851\u9020\u4ee3\u9645\u7ecf\u6d4e\u6d41\u52a8\u6027\u65b9\u9762\u53d1\u6325\u7740\u91cd\u8981\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.3386/w35811", "journal": "NBER", "title": "Evaluating the Spatial Consequences of a Climate Tipping Point", "authors": ["Jos\u00e9-Luis Cruz", "Klaus Desmet", "Esteban Rossi-Hansberg"], "author_details": [{"name": "Jos\u00e9-Luis Cruz", "affiliations": []}, {"name": "Klaus Desmet", "affiliations": []}, {"name": "Esteban Rossi-Hansberg", "affiliations": []}], "abstract": "The Atlantic Meridional Overturning Circulation (AMOC) is a system of ocean currents that plays a key role in regulating global climate, including moderating temperatures in Europe and the North Atlantic. Its potential collapse due to global warming is widely considered one of the more likely climate tipping points. This paper examines the economic implications of such a collapse using a dynamic spatially integrated assessment model (S-IAM) of the world economy. Scandinavia and parts of Russia are predicted to experience significant losses in GDP and welfare, while southern Europe, northern Africa, and Brazil benefit from slightly colder temperatures. S-IAMs generally predict that global warming is especially harmful to low-income regions, but an AMOC collapse could mitigate some of these negative impacts in parts of the developing world while instead harming some of the more advanced economies. This lowers spatial inequality, but global welfare drops by 1.9% by 2200 under an intermediate-emissions scenario.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35811", "title_zh": "\u8bc4\u4f30\u6c14\u5019\u4e34\u754c\u70b9\u7684\u7a7a\u95f4\u540e\u679c", "abstract_zh": "\u5927\u897f\u6d0b\u7ecf\u5411\u7ffb\u8f6c\u73af\u6d41\uff08AMOC\uff09\u662f\u8c03\u8282\u5168\u7403\u6c14\u5019\u7684\u5173\u952e\u6d77\u6d0b\u73af\u6d41\u7cfb\u7edf\uff0c\u5305\u62ec\u5bf9\u6b27\u6d32\u548c\u5317\u5927\u897f\u6d0b\u6e29\u5ea6\u7684\u8c03\u8282\u4f5c\u7528\u3002\u5176\u56e0\u5168\u7403\u53d8\u6696\u800c\u53ef\u80fd\u5d29\u6e83\uff0c\u88ab\u5e7f\u6cdb\u8ba4\u4e3a\u662f\u6700\u91cd\u8981\u7684\u6c14\u5019\u4e34\u754c\u70b9\u4e4b\u4e00\u3002\u672c\u6587\u5229\u7528\u4e00\u4e2a\u52a8\u6001\u7a7a\u95f4\u6574\u5408\u8bc4\u4f30\u6a21\u578b\uff08S-IAM\uff09\u5206\u6790\u8be5\u7cfb\u7edf\u5d29\u6e83\u5bf9\u4e16\u754c\u7ecf\u6d4e\u7684\u7ecf\u6d4e\u5f71\u54cd\u3002\u9884\u6d4b\u65af\u582a\u7684\u7eb3\u7ef4\u4e9a\u5730\u533a\u548c\u4fc4\u7f57\u65af\u90e8\u5206\u5730\u533a\u5c06\u9762\u4e34GDP\u548c\u798f\u5229\u7684\u663e\u8457\u635f\u5931\uff0c\u800c\u5357\u6b27\u3001\u5317\u975e\u548c\u5df4\u897f\u5219\u56e0\u6c14\u6e29\u7565\u5fae\u4e0b\u964d\u800c\u53d7\u76ca\u3002\u901a\u5e38S-IAM\u6a21\u578b\u9884\u6d4b\u5168\u7403\u53d8\u6696\u5bf9\u4f4e\u6536\u5165\u5730\u533a\u5371\u5bb3\u6700\u5927\uff0c\u4f46AMOC\u5d29\u6e83\u53ef\u80fd\u5728\u90e8\u5206\u53d1\u5c55\u4e2d\u56fd\u5bb6\u7f13\u89e3\u8fd9\u4e9b\u8d1f\u9762\u6548\u5e94\uff0c\u540c\u65f6\u635f\u5bb3\u4e00\u4e9b\u53d1\u8fbe\u7ecf\u6d4e\u4f53\u3002\u8fd9\u5728\u4e00\u5b9a\u7a0b\u5ea6\u4e0a\u964d\u4f4e\u4e86\u7a7a\u95f4\u4e0d\u5e73\u7b49\uff0c\u4f46\u5728\u4e2d\u7b49\u6392\u653e\u60c5\u666f\u4e0b\uff0c\u52302200\u5e74\u5168\u7403\u798f\u5229\u5c06\u4e0b\u964d1.9%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35812", "journal": "NBER", "title": "Transportation Bottlenecks and Aggregate Shocks", "authors": ["Giulia Brancaccio", "Myrto Kalouptsidi", "Theodore Papageorgiou", "Yixin Zhou"], "author_details": [{"name": "Giulia Brancaccio", "affiliations": []}, {"name": "Myrto Kalouptsidi", "affiliations": []}, {"name": "Theodore Papageorgiou", "affiliations": []}, {"name": "Yixin Zhou", "affiliations": []}], "abstract": "Do transportation disruptions affect aggregate outcomes? We develop a tractable model of the transportation sector to study its impact on prices and international trade. By casting maritime transportation as a queueing network, the model identifies where the transportation bottlenecks lie and delivers a simple and easy-to compute measure of transportation capacity over time. We calibrate the model using shipping and trade data and use it to evaluate the resilience of the shipping sector during the last 20 years. During the Great Supply Chain Disruption, port bottlenecks raised commodity prices and caused shortages, but a contemporaneous contraction in commodity supply reduced shipping demand and thereby dampened these effects. By contrast, insufficient shipping capacity was a key driver of price increases during the 2000s Commodity Supercycle.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35812", "title_zh": "\u8fd0\u8f93\u74f6\u9888\u4e0e\u603b\u4f53\u51b2\u51fb", "abstract_zh": "\u8fd0\u8f93\u4e2d\u65ad\u4f1a\u5f71\u54cd\u603b\u4f53\u7ecf\u6d4e\u7ed3\u679c\u5417\uff1f\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u53ef\u5904\u7406\u7684\u8fd0\u8f93\u90e8\u95e8\u6a21\u578b\uff0c\u4ee5\u7814\u7a76\u5176\u5bf9\u4ef7\u683c\u548c\u56fd\u9645\u8d38\u6613\u7684\u5f71\u54cd\u3002\u901a\u8fc7\u5c06\u6d77\u8fd0\u8fd0\u8f93\u89c6\u4e3a\u4e00\u4e2a\u6392\u961f\u7f51\u7edc\uff0c\u6a21\u578b\u8bc6\u522b\u51fa\u8fd0\u8f93\u74f6\u9888\u6240\u5728\u4f4d\u7f6e\uff0c\u5e76\u63d0\u4f9b\u4e86\u4e00\u4e2a\u7b80\u5355\u4e14\u6613\u4e8e\u8ba1\u7b97\u7684\u8fd0\u8f93\u5bb9\u91cf\u65f6\u95f4\u5ea6\u91cf\u3002\u6211\u4eec\u5229\u7528\u822a\u8fd0\u548c\u8d38\u6613\u6570\u636e\u5bf9\u6a21\u578b\u8fdb\u884c\u6821\u51c6\uff0c\u5e76\u7528\u5176\u8bc4\u4f30\u8fc7\u53bb\u4e8c\u5341\u5e74\u4e2d\u822a\u8fd0\u90e8\u95e8\u7684\u97e7\u6027\u3002\u5728\u91cd\u5927\u4f9b\u5e94\u94fe\u4e2d\u65ad\u671f\u95f4\uff0c\u6e2f\u53e3\u74f6\u9888\u5bfc\u81f4\u5546\u54c1\u4ef7\u683c\u4e0a\u6da8\u548c\u77ed\u7f3a\uff0c\u4f46\u540c\u671f\u5546\u54c1\u4f9b\u5e94\u6536\u7f29\u51cf\u5c11\u4e86\u822a\u8fd0\u9700\u6c42\uff0c\u4ece\u800c\u51cf\u5f31\u4e86\u8fd9\u4e9b\u5f71\u54cd\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u57282000\u5e74\u4ee3\u7684\u5546\u54c1\u8d85\u7ea7\u5468\u671f\u4e2d\uff0c\u822a\u8fd0\u80fd\u529b\u4e0d\u8db3\u662f\u4ef7\u683c\u4e0a\u6da8\u7684\u5173\u952e\u9a71\u52a8\u56e0\u7d20\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.3386/w35813", "journal": "NBER", "title": "The Dynamics of Development in a Zero-Sum World", "authors": ["Augustin Bergeron", "Jean-Paul Carvalho", "Joseph Henrich", "Nathan Nunn", "Jonathan L. Weigel"], "author_details": [{"name": "Augustin Bergeron", "affiliations": []}, {"name": "Jean-Paul Carvalho", "affiliations": []}, {"name": "Joseph Henrich", "affiliations": []}, {"name": "Nathan Nunn", "affiliations": []}, {"name": "Jonathan L. Weigel", "affiliations": []}], "abstract": "This chapter examines the consequences of zero-sum environments for cultural change, innovation, and long-term economic growth. We introduce innovation into the framework developed by Bergeron et al. (forthcoming), in which zero-sum environments give rise to demotivating beliefs. Although demotivating beliefs improve static efficiency by limiting excessive competition in zero-sum environments, we show that they can also impede long-term growth. Because demotivating beliefs suppress effort, they can also reduce learning-by-doing and other production spillovers. Hence, they can inhibit innovation and act as a cultural evolutionary kludge. We apply the model to explain the cultural changes associated with Western Europe's economic rise after 1500.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35813", "title_zh": "\u96f6\u548c\u4e16\u754c\u4e2d\u7684\u53d1\u5c55\u52a8\u6001", "abstract_zh": "\u672c\u7ae0\u8003\u5bdf\u4e86\u96f6\u548c\u73af\u5883\u5bf9\u6587\u5316\u53d8\u8fc1\u3001\u521b\u65b0\u4ee5\u53ca\u957f\u671f\u7ecf\u6d4e\u589e\u957f\u7684\u540e\u679c\u3002\u6211\u4eec\u5728Bergeron\u7b49\uff08\u5373\u5c06\u51fa\u7248\uff09\u6240\u5efa\u7acb\u7684\u6846\u67b6\u4e2d\u5f15\u5165\u4e86\u521b\u65b0\u6982\u5ff5\uff0c\u8be5\u6846\u67b6\u6307\u51fa\u96f6\u548c\u73af\u5883\u4f1a\u5bfc\u81f4\u52a8\u673a\u51cf\u5f31\u7684\u4fe1\u5ff5\u3002\u5c3d\u7ba1\u8fd9\u4e9b\u52a8\u673a\u51cf\u5f31\u7684\u4fe1\u5ff5\u901a\u8fc7\u9650\u5236\u96f6\u548c\u73af\u5883\u4e2d\u7684\u8fc7\u5ea6\u7ade\u4e89\u800c\u63d0\u9ad8\u4e86\u9759\u6001\u6548\u7387\uff0c\u4f46\u6211\u4eec\u8bc1\u660e\u5b83\u4eec\u4e5f\u53ef\u80fd\u963b\u788d\u957f\u671f\u589e\u957f\u3002\u7531\u4e8e\u8fd9\u4e9b\u4fe1\u5ff5\u4f1a\u6291\u5236\u52aa\u529b\uff0c\u4ece\u800c\u51cf\u5c11\u901a\u8fc7\u5b9e\u8df5\u5b66\u4e60\u53ca\u5176\u4ed6\u751f\u4ea7\u5916\u6ea2\u6548\u5e94\uff0c\u56e0\u6b64\u53ef\u80fd\u6291\u5236\u521b\u65b0\uff0c\u5e76\u6210\u4e3a\u6587\u5316\u6f14\u5316\u4e2d\u7684\u4e00\u4e2a\u4e34\u65f6\u6027\u4fee\u8865\u63aa\u65bd\u3002\u6211\u4eec\u5c06\u8be5\u6a21\u578b\u5e94\u7528\u4e8e\u89e3\u91ca1500\u5e74\u4ee5\u540e\u897f\u6b27\u7ecf\u6d4e\u5d1b\u8d77\u8fc7\u7a0b\u4e2d\u4f34\u968f\u7684\u6587\u5316\u53d8\u5316\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35814", "journal": "NBER", "title": "Foreign Opportunity and Regional Revival: Evidence from the French Rust Belt", "authors": ["Antoine B. Levy", "Mathilde Mu\u00f1oz"], "author_details": [{"name": "Antoine B. Levy", "affiliations": []}, {"name": "Mathilde Mu\u00f1oz", "affiliations": []}], "abstract": "This paper studies whether and how distressed regions can recover from industrial decline. We exploit differences in access to an increasingly thriving Luxembourg labor market for neighboring residents of the French \u201cRust Belt.\u201d We document a three-phase expansion of treated local labor markets, driven by an initial workplace substitution of incumbent residents towards cross-border job opportunities, a medium-term rise in local labor force utilization, and a long-run sustained increase in population via net domestic in-migration. A broader process of local revitalization follows, with higher incomes, reduced reliance on transfers, and resilience to social dislocation, although it is partially offset by rising housing costs and unequal congestion. This leads to a net decrease in far-right and anti- EU vote shares, muting the rise of populism visible elsewhere in former industrial regions of France. Our findings suggest that former industrial regions are not inherently rigid nor doomed to fall to anti-globalization backlash, but can and do adjust \u2013 given sufficiently large-scale reversals in local labor demand.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35814", "title_zh": "\u5916\u56fd\u673a\u4f1a\u4e0e\u533a\u57df\u590d\u5174\uff1a\u6765\u81ea\u6cd5\u56fd\u9508\u5e26\u7684\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u9677\u5165\u56f0\u5883\u7684\u5730\u533a\u662f\u5426\u4ee5\u53ca\u5982\u4f55\u4ece\u5de5\u4e1a\u8870\u9000\u4e2d\u6062\u590d\u3002\u6211\u4eec\u5229\u7528\u90bb\u8fd1\u6cd5\u56fd\u2018\u9508\u5e26\u2019\u5c45\u6c11\u5bf9\u65e5\u76ca\u7e41\u8363\u7684\u5362\u68ee\u5821\u52b3\u52a8\u529b\u5e02\u573a\u7684\u4e0d\u540c\u63a5\u89e6\u7a0b\u5ea6\u8fdb\u884c\u5206\u6790\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u53d7\u5904\u7406\u5730\u533a\u7684\u672c\u5730\u52b3\u52a8\u529b\u5e02\u573a\u7ecf\u5386\u4e86\u4e09\u4e2a\u9636\u6bb5\u7684\u6269\u5f20\uff1a\u9996\u5148\u662f\u73b0\u6709\u5c45\u6c11\u5411\u8de8\u5883\u5c31\u4e1a\u673a\u4f1a\u8f6c\u79fb\uff0c\u5176\u6b21\u662f\u5728\u4e2d\u671f\u5185\u672c\u5730\u52b3\u52a8\u529b\u5229\u7528\u7387\u4e0a\u5347\uff0c\u6700\u540e\u662f\u957f\u671f\u6301\u7eed\u7684\u4eba\u53e3\u589e\u957f\uff0c\u8868\u73b0\u4e3a\u51c0\u56fd\u5185\u79fb\u6c11\u589e\u52a0\u3002\u968f\u4e4b\u800c\u6765\u7684\u662f\u66f4\u5e7f\u6cdb\u7684\u5730\u65b9\u590d\u5174\u8fc7\u7a0b\uff0c\u8868\u73b0\u4e3a\u6536\u5165\u63d0\u9ad8\u3001\u5bf9\u8f6c\u79fb\u652f\u4ed8\u7684\u4f9d\u8d56\u51cf\u5c11\u4ee5\u53ca\u5bf9\u793e\u4f1a\u52a8\u8361\u7684\u6297\u538b\u80fd\u529b\u589e\u5f3a\uff0c\u5c3d\u7ba1\u4e5f\u53d7\u5230\u4f4f\u623f\u6210\u672c\u4e0a\u6da8\u548c\u4e0d\u5747\u62e5\u6324\u7684\u62b5\u6d88\u3002\u8fd9\u5bfc\u81f4\u5bf9\u6781\u53f3\u7ffc\u548c\u53cd\u6b27\u76df\u9009\u7968\u4efd\u989d\u7684\u51c0\u4e0b\u964d\uff0c\u6291\u5236\u4e86\u6cd5\u56fd\u5176\u4ed6\u524d\u5de5\u4e1a\u5730\u533a\u4e2d\u6240\u663e\u73b0\u7684\u6c11\u7cb9\u4e3b\u4e49\u4e0a\u5347\u8d8b\u52bf\u3002\u6211\u4eec\u7684\u53d1\u73b0\u8868\u660e\uff0c\u524d\u5de5\u4e1a\u5730\u533a\u5e76\u975e\u672c\u8d28\u4e0a\u50f5\u5316\uff0c\u4e5f\u5e76\u975e\u6ce8\u5b9a\u4f1a\u9677\u5165\u53cd\u5168\u7403\u5316\u53cd\u5f39\uff0c\u53ea\u8981\u5f53\u5730\u52b3\u52a8\u529b\u9700\u6c42\u51fa\u73b0\u8db3\u591f\u89c4\u6a21\u7684\u9006\u8f6c\uff0c\u5b83\u4eec\u5c31\u80fd\u591f\u5e76\u786e\u5b9e\u5b9e\u73b0\u8c03\u6574\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35815", "journal": "NBER", "title": "The Commoditization of Labor", "authors": ["Masao Fukui", "Emi Nakamura", "J\u00f3n Steinsson"], "author_details": [{"name": "Masao Fukui", "affiliations": []}, {"name": "Emi Nakamura", "affiliations": []}, {"name": "J\u00f3n Steinsson", "affiliations": []}], "abstract": "Technical change often simplifies jobs. This increases productivity, but it also makes workers more substitutable\u2013or more \"commoditized.\" Commoditization of labor drives down worker bargaining power: anyone can do the job, implying workers are disposable, which improves the outside option of firms and can lower worker wages. We develop a model that captures both the productivity enhancing and wage depressing effects of commoditizing technical change. Commoditizing technical change involves firms standardizing tasks. This reduces the sensitivity of output to worker quality. Firms benefit because they can more easily fill vacancies for their durable jobs. We show that our model can help explain the divergence between productivity and wages in the service sector, increasing wage markdowns despite falling local concentration, and the decline of the large-firm wage premium.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35815", "title_zh": "\u52b3\u52a8\u7684\u5546\u54c1\u5316", "abstract_zh": "\u6280\u672f\u53d8\u9769\u5f80\u5f80\u7b80\u5316\u4e86\u5de5\u4f5c\u5185\u5bb9\u3002\u8fd9\u63d0\u9ad8\u4e86\u751f\u4ea7\u7387\uff0c\u4f46\u4e5f\u4f7f\u5de5\u4eba\u66f4\u5177\u53ef\u66ff\u4ee3\u6027\u2014\u2014\u6216\u8005\u8bf4\u66f4\"\u5546\u54c1\u5316\"\u3002\u52b3\u52a8\u7684\u5546\u54c1\u5316\u524a\u5f31\u4e86\u5de5\u4eba\u7684\u8bae\u4ef7\u80fd\u529b\uff1a\u4efb\u4f55\u4eba\u53ea\u8981\u80fd\u5b8c\u6210\u8fd9\u9879\u5de5\u4f5c\uff0c\u5c31\u610f\u5473\u7740\u5de5\u4eba\u662f\u53ef\u66ff\u4ee3\u7684\uff0c\u4ece\u800c\u589e\u5f3a\u4e86\u4f01\u4e1a\u7684\u5916\u90e8\u9009\u62e9\u6743\uff0c\u53ef\u80fd\u5bfc\u81f4\u5de5\u8d44\u4e0b\u964d\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6a21\u578b\uff0c\u4ee5\u6355\u6349\u5546\u54c1\u5316\u6280\u672f\u53d8\u9769\u5e26\u6765\u7684\u751f\u4ea7\u7387\u63d0\u5347\u548c\u5de5\u8d44\u6291\u5236\u7684\u53cc\u91cd\u6548\u5e94\u3002\u52b3\u52a8\u7684\u5546\u54c1\u5316\u610f\u5473\u7740\u4f01\u4e1a\u5bf9\u4efb\u52a1\u8fdb\u884c\u6807\u51c6\u5316\uff0c\u8fd9\u964d\u4f4e\u4e86\u4ea7\u51fa\u5bf9\u5de5\u4eba\u8d28\u91cf\u7684\u654f\u611f\u6027\u3002\u4f01\u4e1a\u56e0\u6b64\u80fd\u591f\u66f4\u8f7b\u677e\u5730\u586b\u8865\u5176\u957f\u671f\u5c97\u4f4d\u7684\u7a7a\u7f3a\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u8be5\u6a21\u578b\u53ef\u4ee5\u89e3\u91ca\u670d\u52a1\u4e1a\u4e2d\u751f\u4ea7\u7387\u4e0e\u5de5\u8d44\u4e4b\u95f4\u7684\u5206\u5316\u73b0\u8c61\uff0c\u5373\u5c3d\u7ba1\u672c\u5730\u96c6\u4e2d\u5ea6\u4e0b\u964d\uff0c\u5de5\u8d44\u6298\u6263\u5374\u5728\u589e\u52a0\uff0c\u4ee5\u53ca\u5927\u578b\u4f01\u4e1a\u5de5\u8d44\u6ea2\u4ef7\u7684\u4e0b\u964d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35816", "journal": "NBER", "title": "The Great Accretion and the Great Depression", "authors": ["Harold L. Cole", "Stefano Cravero", "Jeremy Greenwood"], "author_details": [{"name": "Harold L. Cole", "affiliations": []}, {"name": "Stefano Cravero", "affiliations": []}, {"name": "Jeremy Greenwood", "affiliations": []}], "abstract": "The Second Industrial Revolution sparked a wave of new products and industrial processes, fueling an optimistic Roaring Twenties. But did excitement about technological progress contribute to an over accumulation of investment, despite a slowdown in new product development and satiated demand during the 1920s? And, was this over investment worsened by continuous process innovation? Could these factors have played a role in triggering the Great Depression? To explore these questions, a macroeconomic model that incorporates both process and product innovation is proposed. Proof-of-concept simulations are performed to assess whether these factors can help explain the Great Depression. The answer is yes.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35816", "title_zh": "\u5de8\u5927\u7684\u79ef\u7d2f\u4e0e\u5927\u8427\u6761", "abstract_zh": "\u7b2c\u4e8c\u6b21\u5de5\u4e1a\u9769\u547d\u5f15\u53d1\u4e86\u4e00\u7cfb\u5217\u65b0\u4ea7\u54c1\u548c\u5de5\u4e1a\u6d41\u7a0b\u7684\u6d8c\u73b0\uff0c\u63a8\u52a8\u4e8620\u5e74\u4ee3\u7684\u4e50\u89c2\u6c1b\u56f4\u3002\u4f46\u5bf9\u6280\u672f\u8fdb\u6b65\u7684\u5174\u594b\u662f\u5426\u5bfc\u81f4\u4e86\u6295\u8d44\u8fc7\u5ea6\u79ef\u7d2f\uff0c\u5c3d\u7ba120\u5e74\u4ee3\u65b0\u4ea7\u54c1\u5f00\u53d1\u653e\u7f13\u4e14\u5e02\u573a\u9700\u6c42\u8d8b\u4e8e\u9971\u548c\uff1f\u6301\u7eed\u7684\u8fc7\u7a0b\u521b\u65b0\u662f\u5426\u52a0\u5267\u4e86\u8fd9\u4e00\u8fc7\u5ea6\u6295\u8d44\uff1f\u8fd9\u4e9b\u56e0\u7d20\u662f\u5426\u53ef\u80fd\u5728\u5f15\u53d1\u5927\u8427\u6761\u4e2d\u8d77\u5230\u4e86\u4f5c\u7528\uff1f\u4e3a\u63a2\u8ba8\u8fd9\u4e9b\u95ee\u9898\uff0c\u672c\u6587\u63d0\u51fa\u4e00\u4e2a\u878d\u5408\u8fc7\u7a0b\u521b\u65b0\u4e0e\u4ea7\u54c1\u521b\u65b0\u7684\u5b8f\u89c2\u7ecf\u6d4e\u6a21\u578b\uff0c\u5e76\u901a\u8fc7\u6982\u5ff5\u9a8c\u8bc1\u6a21\u62df\u8bc4\u4f30\u8fd9\u4e9b\u56e0\u7d20\u662f\u5426\u6709\u52a9\u4e8e\u89e3\u91ca\u5927\u8427\u6761\u3002\u7b54\u6848\u662f\u80af\u5b9a\u7684\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35817", "journal": "NBER", "title": "Early Results from the RESET Demonstration Project: Inflation in Food at Home", "authors": ["Steve Coffey", "Gabriel Ehrlich", "John C. Haltiwanger", "Ron S. Jarmin", "David Johnson", "Tod Johnson", "Matthew D. Shapiro"], "author_details": [{"name": "Steve Coffey", "affiliations": []}, {"name": "Gabriel Ehrlich", "affiliations": []}, {"name": "John C. Haltiwanger", "affiliations": []}, {"name": "Ron S. Jarmin", "affiliations": []}, {"name": "David Johnson", "affiliations": []}, {"name": "Tod Johnson", "affiliations": []}, {"name": "Matthew D. Shapiro", "affiliations": []}], "abstract": "This paper presents early results from the RESET Demonstration Project, an initiative that constructs price and sales indices using item-level transactions data. The project\u2019s overarching goal is to demonstrate the feasibility and advantages of leveraging modern transactions data for economic measurement by pointing toward a future in which official economic statistics are rebuilt on 21st-century data and technology. The paper introduces new inflation measures for Food at Home and evaluates them on two fronts: how they compare to current official statistics and what they offer as novel measures that capture more accurately the dynamics of consumer choice. The paper also addresses the challenges of producing reliable and credible official statistics from item-level transactions data and reports findings on recent Food at Home inflation trends.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35817", "title_zh": "RESET\u793a\u8303\u9879\u76ee\u65e9\u671f\u6210\u679c\uff1a\u5bb6\u5ead\u98df\u54c1\u4ef7\u683c\u901a\u80c0", "abstract_zh": "\u672c\u6587\u4ecb\u7ecd\u4e86RESET\u793a\u8303\u9879\u76ee\u7684\u65e9\u671f\u6210\u679c\uff0c\u8be5\u9879\u76ee\u5229\u7528\u5546\u54c1\u7ea7\u4ea4\u6613\u6570\u636e\u6784\u5efa\u4ef7\u683c\u548c\u9500\u552e\u6307\u6570\u3002\u9879\u76ee\u7684\u6838\u5fc3\u76ee\u6807\u662f\u8bc1\u660e\u5229\u7528\u73b0\u4ee3\u4ea4\u6613\u6570\u636e\u8fdb\u884c\u7ecf\u6d4e\u6d4b\u91cf\u7684\u53ef\u884c\u6027\u548c\u4f18\u52bf\uff0c\u6307\u5411\u4e00\u4e2a\u672a\u6765\uff0c\u5373\u5b98\u65b9\u7ecf\u6d4e\u7edf\u8ba1\u6570\u636e\u5c06\u57fa\u4e8e21\u4e16\u7eaa\u7684\u6570\u636e\u548c\u6280\u672f\u91cd\u5efa\u3002\u672c\u6587\u63d0\u51fa\u4e86\u5bb6\u5ead\u98df\u54c1\u9886\u57df\u7684\u65b0\u578b\u901a\u80c0\u6307\u6807\uff0c\u5e76\u4ece\u4e24\u4e2a\u65b9\u9762\u8fdb\u884c\u8bc4\u4f30\uff1a\u4e0e\u5f53\u524d\u5b98\u65b9\u7edf\u8ba1\u6570\u636e\u7684\u5bf9\u6bd4\uff0c\u4ee5\u53ca\u4f5c\u4e3a\u66f4\u51c6\u786e\u6355\u6349\u6d88\u8d39\u8005\u9009\u62e9\u52a8\u6001\u7684\u65b0\u578b\u6307\u6807\u6240\u5177\u5907\u7684\u7279\u6027\u3002\u672c\u6587\u8fd8\u63a2\u8ba8\u4e86\u4ece\u5546\u54c1\u7ea7\u4ea4\u6613\u6570\u636e\u4e2d\u4ea7\u751f\u53ef\u9760\u4e14\u53ef\u4fe1\u7684\u5b98\u65b9\u7edf\u8ba1\u6570\u636e\u6240\u9762\u4e34\u7684\u6311\u6218\uff0c\u5e76\u62a5\u544a\u4e86\u8fd1\u671f\u5bb6\u5ead\u98df\u54c1\u901a\u80c0\u8d8b\u52bf\u7684\u53d1\u73b0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35818", "journal": "NBER", "title": "Windows of Opportunity in Early Childhood: A Dynamic Model of Multidimensional Development", "authors": ["Orazio Attanasio", "Raquel Bernal", "Michele Giannola", "Milagros Nores"], "author_details": [{"name": "Orazio Attanasio", "affiliations": []}, {"name": "Raquel Bernal", "affiliations": []}, {"name": "Michele Giannola", "affiliations": []}, {"name": "Milagros Nores", "affiliations": []}], "abstract": "Using child development data collected during the evaluation of an early childhood education program, this paper estimates a dynamic model of human development from ages 1 to 6. We model three latent factors\u2014health, cognitive skills, and socio-emotional skills\u2014and allow them to interact with each other and with multiple inputs to shape subsequent development. The richness and high-frequency nature of the data permit a flexible specification that (i) allows for complex dynamics, (ii) lets each factor con- tribute to the production of the others, (iii) permits age-varying production technologies, and (iv) treats parental investment as endogenous. We use the estimated model to identify \u201cwindows of opportunity\u201d in which parental interventions, or programs that increase investment, are especially effective. Results indicate that developmental dynamics are richer than typically assumed, with important implications for persistence: the impact of inputs can decay or endure in ways that vary across domains and over age. Accounting for endogenous investment is consequential for inference.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35818", "title_zh": "\u65e9\u671f\u513f\u7ae5\u6210\u957f\u4e2d\u7684\u673a\u9047\u7a97\u53e3\uff1a\u4e00\u4e2a\u591a\u7ef4\u5ea6\u53d1\u5c55\u7684\u52a8\u6001\u6a21\u578b", "abstract_zh": "\u5229\u7528\u4e00\u9879\u65e9\u671f\u513f\u7ae5\u6559\u80b2\u9879\u76ee\u8bc4\u4f30\u8fc7\u7a0b\u4e2d\u6536\u96c6\u7684\u513f\u7ae5\u53d1\u5c55\u6570\u636e\uff0c\u672c\u6587\u4f30\u8ba1\u4e86\u4ece1\u5c81\u52306\u5c81\u7684\u4eba\u7c7b\u53d1\u5c55\u52a8\u6001\u6a21\u578b\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e09\u4e2a\u6f5c\u5728\u56e0\u7d20\u2014\u2014\u5065\u5eb7\u3001\u8ba4\u77e5\u80fd\u529b\u548c\u793e\u4f1a\u60c5\u611f\u80fd\u529b\u2014\u2014\u5e76\u5141\u8bb8\u5b83\u4eec\u76f8\u4e92\u4f5c\u7528\uff0c\u4ee5\u53ca\u4e0e\u591a\u79cd\u8f93\u5165\u56e0\u7d20\u76f8\u4e92\u4f5c\u7528\uff0c\u4ece\u800c\u5f71\u54cd\u540e\u7eed\u7684\u53d1\u5c55\u3002\u6570\u636e\u7684\u4e30\u5bcc\u6027\u548c\u9ad8\u9891\u7279\u6027\u4f7f\u5f97\u6a21\u578b\u80fd\u591f\u7075\u6d3b\u8bbe\u5b9a\uff1a\uff08i\uff09\u5141\u8bb8\u590d\u6742\u7684\u52a8\u6001\u8fc7\u7a0b\uff1b\uff08ii\uff09\u8ba9\u6bcf\u4e2a\u56e0\u7d20\u5bf9\u5176\u4ed6\u56e0\u7d20\u7684\u4ea7\u751f\u505a\u51fa\u8d21\u732e\uff1b\uff08iii\uff09\u5141\u8bb8\u751f\u4ea7\u6280\u672f\u968f\u5e74\u9f84\u53d8\u5316\uff1b\uff08iv\uff09\u5c06\u7236\u6bcd\u6295\u8d44\u89c6\u4e3a\u5185\u751f\u53d8\u91cf\u3002\u6211\u4eec\u5229\u7528\u4f30\u8ba1\u7684\u6a21\u578b\u8bc6\u522b\u51fa\u201c\u673a\u9047\u7a97\u53e3\u201d\uff0c\u5373\u7236\u6bcd\u5e72\u9884\u6216\u589e\u52a0\u6295\u8d44\u7684\u9879\u76ee\u5728\u5176\u4e2d\u7279\u522b\u6709\u6548\u7684\u65f6\u671f\u3002\u7ed3\u679c\u8868\u660e\uff0c\u53d1\u5c55\u52a8\u6001\u6bd4\u901a\u5e38\u5047\u8bbe\u7684\u66f4\u4e3a\u590d\u6742\uff0c\u5bf9\u6301\u4e45\u6027\u5177\u6709\u91cd\u8981\u5f71\u54cd\uff1a\u8f93\u5165\u7684\u5f71\u54cd\u53ef\u80fd\u8870\u51cf\u6216\u6301\u7eed\uff0c\u4e14\u8fd9\u79cd\u53d8\u5316\u5728\u4e0d\u540c\u9886\u57df\u548c\u4e0d\u540c\u5e74\u9f84\u95f4\u5b58\u5728\u5dee\u5f02\u3002\u8003\u8651\u7236\u6bcd\u6295\u8d44\u7684\u5185\u751f\u6027\u5bf9\u63a8\u65ad\u7ed3\u679c\u5177\u6709\u91cd\u5927\u610f\u4e49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35819", "journal": "NBER", "title": "Timing, Trading Frictions, and the Limits of Subsidy Capture in Livestock Risk Protection", "authors": ["Yifei Zhang", "Andrew Keller", "Shawn Arita", "Sandro Steinbach"], "author_details": [{"name": "Yifei Zhang", "affiliations": []}, {"name": "Andrew Keller", "affiliations": []}, {"name": "Shawn Arita", "affiliations": []}, {"name": "Sandro Steinbach", "affiliations": []}], "abstract": "Publicly subsidized insurance programs can create incentives for subsidy capture when insured products closely resemble privately traded financial instruments. Livestock Risk Protection (LRP) is one such case because it provides price insurance through a contract that closely resembles an exchange-traded put option. Using LRP endorsement records and matched CME options data for 2020\u20132025, we document that endorsement activity clusters around CME option expiration dates, especially for feeder cattle and lean hogs. Because producer-level derivatives positions are unobserved, however, timing patterns alone cannot identify subsidy capture. We therefore simulate returns to combined LRP-CME strategies using observed contract terms, option prices, and trading frictions, including bid-ask spreads, margin requirements, and financing costs. We find that the subsidy-created premium wedge is observable at purchase, but realized gains are small, commodity-specific, and concentrated in low-volatility environments where realized volatility falls below implied volatility. Even in those favorable cases, combined strategies substantially worsen downside outcomes relative to holding LRP alone. Additional evidence shows that clustering persists across volatility regimes and after the 2025 revisions to the LRP Handbook, suggesting that observed timing patterns may reflect contract alignment and routine hedging practices, instead of widespread economically meaningful subsidy capture.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35819", "title_zh": "\u65f6\u673a\u3001\u4ea4\u6613\u6469\u64e6\u4e0e\u7272\u755c\u98ce\u9669\u4fdd\u62a4\u8865\u8d34\u6355\u83b7\u7684\u9650\u5236", "abstract_zh": "\u516c\u5171\u8865\u8d34\u7684\u4fdd\u9669\u8ba1\u5212\u5728\u88ab\u4fdd\u9669\u4ea7\u54c1\u4e0e\u79c1\u4eba\u4ea4\u6613\u91d1\u878d\u5de5\u5177\u9ad8\u5ea6\u76f8\u4f3c\u65f6\uff0c\u53ef\u80fd\u4ea7\u751f\u8865\u8d34\u6355\u83b7\u7684\u6fc0\u52b1\u3002\u7272\u755c\u98ce\u9669\u4fdd\u62a4\uff08LRP\uff09\u5c31\u662f\u4e00\u4e2a\u5178\u578b\u6848\u4f8b\uff0c\u56e0\u4e3a\u5b83\u901a\u8fc7\u4e00\u79cd\u4e0e\u4ea4\u6613\u6240\u4ea4\u6613\u770b\u8dcc\u671f\u6743\u6781\u4e3a\u76f8\u4f3c\u7684\u5408\u540c\u63d0\u4f9b\u4ef7\u683c\u4fdd\u9669\u3002\u5229\u75282020\u5e74\u81f32025\u5e74\u671f\u95f4\u7684LRP\u6295\u4fdd\u8bb0\u5f55\u4ee5\u53ca\u5339\u914d\u7684CME\u671f\u6743\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u6295\u4fdd\u6d3b\u52a8\u96c6\u4e2d\u5728CME\u671f\u6743\u5230\u671f\u65e5\u9644\u8fd1\uff0c\u5c24\u5176\u662f\u5728\u80b2\u80a5\u725b\u548c\u7626\u8089\u732a\u9886\u57df\u3002\u7136\u800c\uff0c\u7531\u4e8e\u4f01\u4e1a\u5c42\u9762\u7684\u884d\u751f\u54c1\u5934\u5bf8\u65e0\u6cd5\u89c2\u6d4b\uff0c\u4ec5\u51ed\u65f6\u95f4\u6a21\u5f0f\u65e0\u6cd5\u8bc6\u522b\u8865\u8d34\u6355\u83b7\u73b0\u8c61\u3002\u56e0\u6b64\uff0c\u6211\u4eec\u57fa\u4e8e\u89c2\u5bdf\u5230\u7684\u5408\u540c\u6761\u6b3e\u3001\u671f\u6743\u4ef7\u683c\u4ee5\u53ca\u4ea4\u6613\u6469\u64e6\uff08\u5305\u62ec\u4e70\u5356\u4ef7\u5dee\u3001\u4fdd\u8bc1\u91d1\u8981\u6c42\u548c\u878d\u8d44\u6210\u672c\uff09\u6a21\u62df\u4e86LRP\u4e0eCME\u7ec4\u5408\u7b56\u7565\u7684\u56de\u62a5\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u8865\u8d34\u4ea7\u751f\u7684\u6ea2\u4ef7\u5dee\u5728\u8d2d\u4e70\u65f6\u662f\u53ef\u89c2\u5bdf\u7684\uff0c\u4f46\u5b9e\u9645\u6536\u76ca\u8f83\u5c0f\uff0c\u5177\u6709\u5546\u54c1\u7279\u5f02\u6027\uff0c\u5e76\u4e14\u96c6\u4e2d\u5728\u6ce2\u52a8\u7387\u8f83\u4f4e\u7684\u73af\u5883\u4e2d\uff0c\u6b64\u65f6\u5b9e\u9645\u6ce2\u52a8\u7387\u4f4e\u4e8e\u9690\u542b\u6ce2\u52a8\u7387\u3002\u5373\u4f7f\u5728\u8fd9\u4e9b\u6709\u5229\u6761\u4ef6\u4e0b\uff0c\u7ec4\u5408\u7b56\u7565\u76f8\u5bf9\u4e8e\u4ec5\u6301\u6709LRP\u800c\u8a00\uff0c\u663e\u8457\u6076\u5316\u4e86\u4e0b\u884c\u98ce\u9669\u3002\u8fdb\u4e00\u6b65\u7684\u8bc1\u636e\u8868\u660e\uff0c\u8fd9\u79cd\u96c6\u4e2d\u73b0\u8c61\u5728\u4e0d\u540c\u6ce2\u52a8\u7387\u73af\u5883\u4e0b\u4ee5\u53ca2025\u5e74LRP\u624b\u518c\u4fee\u8ba2\u540e\u4f9d\u7136\u6301\u7eed\u5b58\u5728\uff0c\u8868\u660e\u6240\u89c2\u5bdf\u5230\u7684\u65f6\u95f4\u6a21\u5f0f\u53ef\u80fd\u53cd\u6620\u4e86\u5408\u540c\u8bbe\u8ba1\u7684\u5339\u914d\u4ee5\u53ca\u5e38\u89c4\u5bf9\u51b2\u884c\u4e3a\uff0c\u800c\u975e\u5e7f\u6cdb\u5b58\u5728\u7684\u5177\u6709\u7ecf\u6d4e\u610f\u4e49\u7684\u8865\u8d34\u6355\u83b7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.3386/w35820", "journal": "NBER", "title": "Social Sorting and Political Cleavages: Evidence from 2.5 Million Electoral Candidates", "authors": ["Jes\u00fas Fern\u00e1ndez-Villaverde", "Carlos Sanz"], "author_details": [{"name": "Jes\u00fas Fern\u00e1ndez-Villaverde", "affiliations": []}, {"name": "Carlos Sanz", "affiliations": []}], "abstract": "How socially distinct are competing political parties' candidate pools? Since names encode cultural milieu, lineage, linguistic origin, and ancestry that standard socioeconomic variables miss, we measure social sorting across parties with names, predicting affiliation out of sample within municipality-years. Across more than 2.5 million local-election candidates, names pick the right-wing candidate in a random within-municipality pair 55.8\\% of the time in Spain and 56.5\\% in France. Given names alone do most of the work: around 55.0%. Under a stylized model of intergenerational transmission of political orientation, this translates to an implied gap of about 25 p.p. in parental naming propensities. The signal is stable in Spain but doubles in France by 2026. Within ideological families, names separate parties as sharply as across the right--left divide, even more so in France. The Spanish cleavage is linguistic and growing. The French one runs through names of immigrant origin and is strongest in large cities.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35820", "title_zh": "\u793e\u4f1a\u5206\u5c42\u4e0e\u653f\u6cbb\u5206\u88c2\uff1a\u6765\u81ea250\u4e07\u9009\u4e3e\u5019\u9009\u4eba\u7684\u8bc1\u636e", "abstract_zh": "\u7ade\u4e89\u6027\u653f\u6cbb\u515a\u6d3e\u7684\u5019\u9009\u4eba\u6c60\u5728\u793e\u4f1a\u4e0a\u6709\u591a\u663e\u8457\u7684\u533a\u522b\uff1f\u7531\u4e8e\u59d3\u540d\u7f16\u7801\u4e86\u6587\u5316\u80cc\u666f\u3001\u5bb6\u65cf\u6e0a\u6e90\u3001\u8bed\u8a00\u8d77\u6e90\u548c\u8840\u7edf\uff0c\u800c\u8fd9\u4e9b\u4fe1\u606f\u6807\u51c6\u7684\u7ecf\u6d4e\u793e\u4f1a\u53d8\u91cf\u65e0\u6cd5\u6355\u6349\uff0c\u6211\u4eec\u5229\u7528\u59d3\u540d\u6765\u8861\u91cf\u515a\u6d3e\u95f4\u7684\u793e\u4f1a\u5206\u5c42\uff0c\u5e76\u5728\u5e02\u9547\u5c42\u9762\u9884\u6d4b\u5019\u9009\u4eba\u7684\u5f52\u5c5e\u3002\u5728\u8d85\u8fc7250\u4e07\u5730\u65b9\u9009\u4e3e\u5019\u9009\u4eba\u4e2d\uff0c\u59d3\u540d\u5728\u897f\u73ed\u7259\u968f\u673a\u914d\u5bf9\u7684\u5e02\u9547\u5185\uff0c\u670955.8%\u7684\u51c6\u786e\u7387\u8bc6\u522b\u51fa\u53f3\u7ffc\u5019\u9009\u4eba\uff0c\u5728\u6cd5\u56fd\u5219\u4e3a56.5%\u3002\u4ec5\u51ed\u59d3\u540d\u5c31\u5b8c\u6210\u4e86\u5927\u90e8\u5206\u9884\u6d4b\u5de5\u4f5c\uff1a\u7ea6\u4e3a55.0%\u3002\u5728\u4e00\u79cd\u7b80\u5316\u7684\u4ee3\u9645\u653f\u6cbb\u503e\u5411\u4f20\u9012\u6a21\u578b\u4e0b\uff0c\u8fd9\u8868\u660e\u7236\u6bcd\u5728\u547d\u540d\u4e0a\u7684\u503e\u5411\u5b58\u5728\u7ea625\u4e2a\u767e\u5206\u70b9\u7684\u5dee\u8ddd\u3002\u8fd9\u4e00\u4fe1\u53f7\u5728\u897f\u73ed\u7259\u7a33\u5b9a\uff0c\u4f46\u5728\u6cd5\u56fd\u52302026\u5e74\u4f1a\u7ffb\u500d\u3002\u5728\u610f\u8bc6\u5f62\u6001\u5bb6\u65cf\u5185\u90e8\uff0c\u59d3\u540d\u80fd\u591f\u50cf\u5de6\u53f3\u5206\u88c2\u90a3\u6837\u6e05\u6670\u5730\u533a\u5206\u4e0d\u540c\u515a\u6d3e\uff0c\u5c24\u5176\u5728\u6cd5\u56fd\u66f4\u4e3a\u660e\u663e\u3002\u897f\u73ed\u7259\u7684\u5206\u88c2\u5177\u6709\u8bed\u8a00\u7279\u5f81\u4e14\u6b63\u5728\u52a0\u5267\uff0c\u800c\u6cd5\u56fd\u7684\u5206\u88c2\u5219\u8d2f\u7a7f\u4e8e\u79fb\u6c11\u80cc\u666f\u7684\u59d3\u540d\uff0c\u4e14\u5728\u5927\u57ce\u5e02\u4e2d\u6700\u4e3a\u663e\u8457\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35821", "journal": "NBER", "title": "Endogenous Rigidities and Capital Misallocation: Evidence from Containerships", "authors": ["Maria Garcia-Osipenko", "Nicholas Vreugdenhil", "Nahim B. Zahur"], "author_details": [{"name": "Maria Garcia-Osipenko", "affiliations": []}, {"name": "Nicholas Vreugdenhil", "affiliations": []}, {"name": "Nahim B. Zahur", "affiliations": []}], "abstract": "We investigate how endogenous rigidities inhibit physical capital reallocation. We focus on the role of contract duration - a classic example of an adjustment rigidity. We argue that when agents sign longer contracts in booms when markets are thin, they generate a contracting externality which further amplifies thinness and impedes the adjustment of markets to shocks. We develop a dynamic spatial framework with booms and busts where agents search and choose match duration. Applying the framework to the containership leasing market, we find substantial misallocation from endogenous rigidities, particularly in the transition after a crash.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35821", "title_zh": "\u5185\u751f\u521a\u6027\u4e0e\u8d44\u672c\u9519\u914d\uff1a\u6765\u81ea\u96c6\u88c5\u7bb1\u8239\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5185\u751f\u521a\u6027\u5982\u4f55\u6291\u5236\u5b9e\u7269\u8d44\u672c\u7684\u91cd\u65b0\u914d\u7f6e\u3002\u6211\u4eec\u91cd\u70b9\u5173\u6ce8\u5408\u540c\u671f\u9650\u2014\u2014\u4e00\u4e2a\u5178\u578b\u7684\u8c03\u6574\u521a\u6027\u4f8b\u5b50\u3002\u6211\u4eec\u8ba4\u4e3a\uff0c\u5f53\u5e02\u573a\u6d41\u52a8\u6027\u8f83\u5f31\u65f6\uff0c\u53c2\u4e0e\u8005\u5728\u7e41\u8363\u65f6\u671f\u7b7e\u8ba2\u66f4\u957f\u671f\u7684\u5408\u540c\uff0c\u4f1a\u4ea7\u751f\u4e00\u79cd\u5408\u540c\u5916\u90e8\u6027\uff0c\u8fdb\u4e00\u6b65\u52a0\u5267\u5e02\u573a\u6d41\u52a8\u6027\u4e0d\u8db3\uff0c\u5e76\u963b\u788d\u5e02\u573a\u5bf9\u51b2\u51fb\u7684\u8c03\u6574\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u7e41\u8363\u4e0e\u8870\u9000\u7684\u52a8\u6001\u7a7a\u95f4\u6846\u67b6\uff0c\u5176\u4e2d\u53c2\u4e0e\u8005\u8fdb\u884c\u641c\u5bfb\u5e76\u9009\u62e9\u5339\u914d\u671f\u9650\u3002\u5c06\u8be5\u6846\u67b6\u5e94\u7528\u4e8e\u96c6\u88c5\u7bb1\u8239\u79df\u8d41\u5e02\u573a\uff0c\u6211\u4eec\u53d1\u73b0\u5185\u751f\u521a\u6027\u5bfc\u81f4\u4e86\u663e\u8457\u7684\u8d44\u672c\u9519\u914d\uff0c\u5c24\u5176\u662f\u5728\u5371\u673a\u540e\u7684\u8fc7\u6e21\u9636\u6bb5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35822", "journal": "NBER", "title": "Financial Innovation and the International Monetary System", "authors": ["Gordon Y. Liao", "Eswar S. Prasad", "Tony Zhang"], "author_details": [{"name": "Gordon Y. Liao", "affiliations": []}, {"name": "Eswar S. Prasad", "affiliations": []}, {"name": "Tony Zhang", "affiliations": []}], "abstract": "We show that the dollar remains dominant in most aspects of global finance. The euro and renminbi are competing in an increasingly fragmented second tier of currencies, leaving no clear rivals to the dollar. We study how financial innovation could reshape the international monetary system. In principle, innovation levels the playing field between countries, for instance by reducing the need for vehicle currencies to intermediate transactions between other currency pairs and by making it easier to acquire and trade foreign assets. We show that an alternative outcome is more likely. Innovations that reduce frictions in cross-border transactions, especially dollar-backed payment stablecoins and other forms of tokenization of money, could interact with relative market thickness to reinforce the dollar\u2019s dominance. This outcome is not preordained but depends on other countries\u2019 willingness to embrace innovations and strengthen their financial markets and regulatory frameworks. While unipolarity has many disadvantages, we show that in some circumstances multipolarity might result in greater global fragility at times of financial market stress.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35822", "title_zh": "\u91d1\u878d\u521b\u65b0\u4e0e\u56fd\u9645\u8d27\u5e01\u4f53\u7cfb", "abstract_zh": "\u6211\u4eec\u8868\u660e\uff0c\u7f8e\u5143\u5728\u5927\u591a\u6570\u5168\u7403\u91d1\u878d\u9886\u57df\u4ecd\u5360\u636e\u4e3b\u5bfc\u5730\u4f4d\u3002\u6b27\u5143\u548c\u4eba\u6c11\u5e01\u6b63\u5728\u4e00\u4e2a\u65e5\u76ca\u788e\u7247\u5316\u7684\u7b2c\u4e8c\u5c42\u7ea7\u8d27\u5e01\u4f53\u7cfb\u4e2d\u5c55\u5f00\u7ade\u4e89\uff0c\u5c1a\u672a\u51fa\u73b0\u80fd\u591f\u6311\u6218\u7f8e\u5143\u7684\u660e\u786e\u5bf9\u624b\u3002\u6211\u4eec\u7814\u7a76\u4e86\u91d1\u878d\u521b\u65b0\u5982\u4f55\u91cd\u5851\u56fd\u9645\u8d27\u5e01\u4f53\u7cfb\u3002\u539f\u5219\u4e0a\uff0c\u521b\u65b0\u80fd\u591f\u7f29\u5c0f\u5404\u56fd\u4e4b\u95f4\u7684\u5dee\u8ddd\uff0c\u4f8b\u5982\u901a\u8fc7\u51cf\u5c11\u5bf9\u4e2d\u95f4\u8d27\u5e01\u8fdb\u884c\u8de8\u5883\u4ea4\u6613\u7684\u4f9d\u8d56\uff0c\u4ee5\u53ca\u4f7f\u83b7\u53d6\u548c\u4ea4\u6613\u5916\u56fd\u8d44\u4ea7\u53d8\u5f97\u66f4\u52a0\u5bb9\u6613\u3002\u4f46\u6211\u4eec\u53d1\u73b0\uff0c\u53e6\u4e00\u79cd\u7ed3\u679c\u66f4\u6709\u53ef\u80fd\u51fa\u73b0\uff1a\u90a3\u4e9b\u964d\u4f4e\u8de8\u5883\u4ea4\u6613\u6469\u64e6\u7684\u521b\u65b0\uff0c\u7279\u522b\u662f\u4ee5\u7f8e\u5143\u4e3a\u540e\u76fe\u7684\u652f\u4ed8\u7a33\u5b9a\u5e01\u53ca\u5176\u4ed6\u8d27\u5e01\u6570\u5b57\u5316\u5f62\u5f0f\uff0c\u53ef\u80fd\u4e0e\u5404\u5e02\u573a\u7684\u76f8\u5bf9\u6d41\u52a8\u6027\u76f8\u4e92\u4f5c\u7528\uff0c\u4ece\u800c\u8fdb\u4e00\u6b65\u5de9\u56fa\u7f8e\u5143\u7684\u4e3b\u5bfc\u5730\u4f4d\u3002\u8fd9\u4e00\u7ed3\u679c\u5e76\u975e\u6ce8\u5b9a\u53d1\u751f\uff0c\u800c\u662f\u53d6\u51b3\u4e8e\u5176\u4ed6\u56fd\u5bb6\u662f\u5426\u613f\u610f\u91c7\u7eb3\u521b\u65b0\u5e76\u52a0\u5f3a\u81ea\u8eab\u7684\u91d1\u878d\u5e02\u573a\u53ca\u76d1\u7ba1\u6846\u67b6\u3002\u5c3d\u7ba1\u5355\u6781\u683c\u5c40\u5b58\u5728\u8bf8\u591a\u5f0a\u7aef\uff0c\u6211\u4eec\u8868\u660e\uff0c\u5728\u67d0\u4e9b\u60c5\u51b5\u4e0b\uff0c\u591a\u6781\u5316\u53ef\u80fd\u5bfc\u81f4\u5168\u7403\u91d1\u878d\u5e02\u573a\u7684\u8106\u5f31\u6027\u5728\u5e02\u573a\u538b\u529b\u65f6\u671f\u8fdb\u4e00\u6b65\u52a0\u5267\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35823", "journal": "NBER", "title": "Optimal Population Growth in the Diamond OLG Model", "authors": ["Laurence M. Ball"], "author_details": [{"name": "Laurence M. Ball", "affiliations": []}], "abstract": "This paper studies the effects of population growth on welfare in an OLG model, in which lower population growth raises output per worker but also reduces the ratio of workers to retirees. Under fairly mild restrictions on the model\u2019s parameters, there exists an optimal population-growth rate\u2014one that maximizes steady-state welfare. This growth rate may well be negative: it may be optimal for the population to shrink over time. The introduction of a pay-as-you-go social security system reduces the optimal population-growth rate.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35823", "title_zh": "\u94bb\u77f3OLG\u6a21\u578b\u4e2d\u7684\u6700\u4f18\u4eba\u53e3\u589e\u957f", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u4eba\u53e3\u589e\u957f\u5bf9OLG\u6a21\u578b\u4e2d\u798f\u5229\u7684\u5f71\u54cd\uff0c\u5728\u8be5\u6a21\u578b\u4e2d\uff0c\u8f83\u4f4e\u7684\u4eba\u53e3\u589e\u957f\u7387\u4f1a\u63d0\u9ad8\u6bcf\u4f4d\u5de5\u4eba\u7684\u4ea7\u51fa\uff0c\u4f46\u540c\u65f6\u4e5f\u4f1a\u964d\u4f4e\u5de5\u4eba\u4e0e\u9000\u4f11\u4eba\u5458\u7684\u6bd4\u4f8b\u3002\u5728\u5bf9\u6a21\u578b\u53c2\u6570\u65bd\u52a0\u76f8\u5f53\u6e29\u548c\u7684\u9650\u5236\u6761\u4ef6\u4e0b\uff0c\u5b58\u5728\u4e00\u4e2a\u80fd\u591f\u6700\u5927\u5316\u7a33\u6001\u798f\u5229\u7684\u6700\u4f18\u4eba\u53e3\u589e\u957f\u7387\u3002\u8fd9\u4e00\u589e\u957f\u7387\u5f88\u53ef\u80fd\u662f\u8d1f\u7684\uff1a\u4eba\u53e3\u968f\u65f6\u95f4\u51cf\u5c11\u53ef\u80fd\u662f\u6700\u4f18\u7684\u3002\u5f15\u5165\u4e00\u79cd\u73b0\u6536\u73b0\u4ed8\u7684\u793e\u4f1a\u4fdd\u969c\u4f53\u7cfb\u4f1a\u964d\u4f4e\u6700\u4f18\u7684\u4eba\u53e3\u589e\u957f\u7387\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35824", "journal": "NBER", "title": "Does Fertility Stabilize At Low Levels? Evidence from Period, Cohort, and Subnational Data", "authors": ["Diane Coffey", "Michael Geruso", "Dean Spears", "Sangita Vyas"], "author_details": [{"name": "Diane Coffey", "affiliations": []}, {"name": "Michael Geruso", "affiliations": []}, {"name": "Dean Spears", "affiliations": []}, {"name": "Sangita Vyas", "affiliations": []}], "abstract": "Many population projections used by international and government agencies assume that, in today's low-fertility societies, future fertility rates will stop declining and roughly stabilize. This paper assesses the evidence for an equilibrium point or rebound from low levels. We show that there is no robust evidence for a systematic fertility rebound, or for a stable equilibrium point at any fertility level conventionally assumed. Instead, where and when fertility has fallen low, it has tended to keep falling. This is true across a range of data sources, time periods, and fertility measures: United Nations data on period total fertility rates for all country-years from 1950 to 2023; Human Fertility Database data on completed fertility for cohorts born between 1935 and 1975 in 31 countries; and fertility rates in subnational geographies in Japan, India, and the United States. We reconcile these results with a prior literature that documented fertility reversals among some low-fertility countries in the early 2000s. Our findings provide an empirical basis for re-examining the equilibrium and rebound assumptions embedded in widely used population projections.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35824", "title_zh": "\u751f\u80b2\u7387\u5728\u4f4e\u6c34\u5e73\u4e0b\u4f1a\u7a33\u5b9a\u5417\uff1f\u57fa\u4e8e\u5468\u671f\u3001\u4e16\u4ee3\u548c\u6b21\u56fd\u5bb6\u6570\u636e\u7684\u8bc1\u636e", "abstract_zh": "\u8bb8\u591a\u56fd\u9645\u548c\u653f\u5e9c\u673a\u6784\u7528\u4e8e\u4eba\u53e3\u9884\u6d4b\u7684\u6a21\u578b\u5047\u8bbe\uff0c\u5728\u5f53\u4eca\u751f\u80b2\u7387\u8f83\u4f4e\u7684\u793e\u4f1a\u4e2d\uff0c\u672a\u6765\u751f\u80b2\u7387\u5c06\u505c\u6b62\u4e0b\u964d\u5e76\u5927\u81f4\u7a33\u5b9a\u3002\u672c\u6587\u8bc4\u4f30\u4e86\u662f\u5426\u5b58\u5728\u7cfb\u7edf\u6027\u7684\u751f\u80b2\u7387\u53cd\u5f39\uff0c\u6216\u5728\u4efb\u4f55\u901a\u5e38\u5047\u8bbe\u7684\u751f\u80b2\u6c34\u5e73\u4e0a\u8fbe\u5230\u7a33\u5b9a\u5747\u8861\u7684\u8bc1\u636e\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u65e0\u8bba\u5728\u54ea\u4e9b\u5730\u533a\u3001\u54ea\u4e9b\u65f6\u95f4\u70b9\uff0c\u6216\u91c7\u7528\u4f55\u79cd\u751f\u80b2\u7387\u8861\u91cf\u65b9\u5f0f\uff0c\u5f53\u751f\u80b2\u7387\u964d\u81f3\u8f83\u4f4e\u6c34\u5e73\u65f6\uff0c\u5b83\u5f80\u5f80\u6301\u7eed\u4e0b\u964d\u3002\u8fd9\u4e00\u7ed3\u8bba\u5728\u591a\u79cd\u6570\u636e\u6765\u6e90\u3001\u65f6\u95f4\u8303\u56f4\u548c\u751f\u80b2\u7387\u6307\u6807\u4e2d\u5747\u6210\u7acb\uff1a\u8054\u5408\u56fd1950\u5e74\u81f32023\u5e74\u6240\u6709\u56fd\u5bb6\u5e74\u4efd\u7684\u5468\u671f\u603b\u751f\u80b2\u7387\u6570\u636e\uff1b1935\u5e74\u81f31975\u5e74\u95f4\u51fa\u751f\u768431\u4e2a\u56fd\u5bb6\u4e16\u4ee3\u7684\u5b8c\u6210\u751f\u80b2\u6570\u636e\uff1b\u4ee5\u53ca\u65e5\u672c\u3001\u5370\u5ea6\u548c\u7f8e\u56fd\u6b21\u56fd\u5bb6\u5730\u7406\u533a\u57df\u7684\u751f\u80b2\u7387\u6570\u636e\u3002\u6211\u4eec\u7ed3\u5408\u6b64\u524d\u6587\u732e\u4e2d\u5173\u4e8e\u90e8\u5206\u4f4e\u751f\u80b2\u7387\u56fd\u5bb6\u57282000\u5e74\u4ee3\u521d\u51fa\u73b0\u751f\u80b2\u7387\u9006\u8f6c\u7684\u53d1\u73b0\uff0c\u89e3\u91ca\u4e86\u8fd9\u4e9b\u7ed3\u679c\u3002\u672c\u7814\u7a76\u4e3a\u91cd\u65b0\u5ba1\u89c6\u5e7f\u6cdb\u4f7f\u7528\u7684\u4eba\u53e3\u9884\u6d4b\u4e2d\u6240\u9690\u542b\u7684\u5747\u8861\u548c\u53cd\u5f39\u5047\u8bbe\u63d0\u4f9b\u4e86\u5b9e\u8bc1\u57fa\u7840\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35825", "journal": "NBER", "title": "The Positive Spillovers to Risky Investments in Vacant, Abandoned, and Disinvested Properties", "authors": ["Edward W. Chen", "Reagan L. Lengefeld", "Omar Isaac Asensio"], "author_details": [{"name": "Edward W. Chen", "affiliations": []}, {"name": "Reagan L. Lengefeld", "affiliations": []}, {"name": "Omar Isaac Asensio", "affiliations": []}], "abstract": "This study examines a housing program that created affordable infill developments on formerly vacant, abandoned, or disinvested properties in Savannah, Georgia. Savannah is a major economic hub anchored by the Port of Savannah, where many urban neighborhoods remain impacted by disinvestment and climate risk. Using two decades of record-linked property and tax data, this study quantifies local economic spillovers from this public intervention, revealing previously hidden social and economic benefits of infill housing policies. These benefits include an 11% increase in the market value of properties immediately neighboring an infill development site and an increase of up to 35% in areas with a high density of infill activity, pointing to block-level revitalization in climate-disadvantaged and distressed areas.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35825", "title_zh": "\u7a7a\u7f6e\u3001\u5e9f\u5f03\u548c\u64a4\u8d44\u623f\u4ea7\u4e2d\u98ce\u9669\u6295\u8d44\u7684\u6b63\u5411\u6ea2\u51fa\u6548\u5e94", "abstract_zh": "\u672c\u7814\u7a76\u8003\u5bdf\u4e86\u5728\u4f50\u6cbb\u4e9a\u5dde\u8428\u51e1\u7eb3\u5e02\u5b9e\u65bd\u7684\u4e00\u9879\u4f4f\u623f\u8ba1\u5212\uff0c\u8be5\u8ba1\u5212\u5728\u66fe\u7ecf\u7a7a\u7f6e\u3001\u5e9f\u5f03\u6216\u64a4\u8d44\u7684\u623f\u4ea7\u4e0a\u5efa\u8bbe\u4e86\u53ef\u8d1f\u62c5\u7684\u586b\u5145\u5f0f\u5f00\u53d1\u9879\u76ee\u3002\u8428\u51e1\u7eb3\u662f\u4f9d\u6258\u8428\u51e1\u7eb3\u6e2f\u7684\u91cd\u8981\u7ecf\u6d4e\u4e2d\u5fc3\uff0c\u8bb8\u591a\u57ce\u5e02\u8857\u533a\u4ecd\u53d7\u5230\u64a4\u8d44\u548c\u6c14\u5019\u98ce\u9669\u7684\u5f71\u54cd\u3002\u5229\u7528\u957f\u8fbe\u4e8c\u5341\u5e74\u7684\u8bb0\u5f55\u5173\u8054\u623f\u4ea7\u548c\u7a0e\u6536\u6570\u636e\uff0c\u672c\u7814\u7a76\u91cf\u5316\u4e86\u8fd9\u4e00\u516c\u5171\u5e72\u9884\u63aa\u65bd\u5e26\u6765\u7684\u672c\u5730\u7ecf\u6d4e\u6ea2\u51fa\u6548\u5e94\uff0c\u63ed\u793a\u4e86\u586b\u5145\u5f0f\u4f4f\u623f\u653f\u7b56\u6b64\u524d\u672a\u88ab\u5bdf\u89c9\u7684\u793e\u4f1a\u548c\u7ecf\u6d4e\u76ca\u5904\u3002\u8fd9\u4e9b\u76ca\u5904\u5305\u62ec\u7d27\u90bb\u586b\u5145\u5f0f\u5f00\u53d1\u9879\u76ee\u7684\u623f\u4ea7\u5e02\u573a\u4ef7\u503c\u63d0\u9ad8\u4e8611%\uff0c\u800c\u5728\u586b\u5145\u5f0f\u6d3b\u52a8\u5bc6\u96c6\u533a\u57df\uff0c\u5e02\u573a\u4ef7\u503c\u6700\u9ad8\u53ef\u63d0\u534735%\uff0c\u8868\u660e\u5728\u6c14\u5019\u4e0d\u5229\u548c\u53d7\u56f0\u5730\u533a\u5b9e\u73b0\u4e86\u8857\u533a\u5c42\u9762\u7684\u590d\u5174\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35826", "journal": "NBER", "title": "Accounting for Cross-Country Income Differences Revisited", "authors": ["David Lagakos", "Todd Schoellman"], "author_details": [{"name": "David Lagakos", "affiliations": []}, {"name": "Todd Schoellman", "affiliations": []}], "abstract": "Development accounting is the search for proximate sources of cross-country income differences. This article describes how knowledge in this field has evolved over the two decades since the influential work of Caselli (2005). There have been large advances in the measurement of production inputs (labor, physical capital, and human capital). These advances have raised the estimated contribution of inputs, mostly human capital, in development accounting. Our preferred estimate is that inputs account for 50--65 percent of gross domestic product (GDP) per worker differences, versus 30 percent using the classic specification. The literature has also made progress in moving away from Cobb-Douglas production functions and measuring factors such as management quality that were previously bundled into total factor productivity (TFP). Our review highlights the new implications of these advances, areas where future research would be beneficial, and the limitations of development accounting.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35826", "title_zh": "\u91cd\u65b0\u5ba1\u89c6\u8de8\u56fd\u6536\u5165\u5dee\u5f02\u7684\u89e3\u91ca", "abstract_zh": "\u53d1\u5c55\u4f1a\u8ba1\u65e8\u5728\u5bfb\u627e\u89e3\u91ca\u5404\u56fd\u6536\u5165\u5dee\u5f02\u7684\u8fd1\u56e0\u3002\u672c\u6587\u63cf\u8ff0\u4e86\u81eaCaselli\uff082005\uff09\u5177\u6709\u5f71\u54cd\u529b\u7684\u5de5\u4f5c\u4ee5\u6765\uff0c\u8fd9\u4e00\u9886\u57df\u77e5\u8bc6\u7684\u6f14\u53d8\u3002\u5728\u8fc7\u53bb\u4e8c\u5341\u5e74\u4e2d\uff0c\u751f\u4ea7\u6295\u5165\uff08\u52b3\u52a8\u3001\u5b9e\u7269\u8d44\u672c\u548c\u4eba\u529b\u8d44\u672c\uff09\u7684\u6d4b\u91cf\u65b9\u6cd5\u53d6\u5f97\u4e86\u91cd\u5927\u8fdb\u5c55\uff0c\u8fd9\u4e9b\u8fdb\u5c55\u663e\u8457\u63d0\u9ad8\u4e86\u5bf9\u6295\u5165\u56e0\u7d20\uff0c\u5c24\u5176\u662f\u4eba\u529b\u8d44\u672c\uff0c\u8d21\u732e\u5ea6\u7684\u4f30\u8ba1\u3002\u6211\u4eec\u7684\u9996\u9009\u4f30\u8ba1\u8868\u660e\uff0c\u6295\u5165\u56e0\u7d20\u89e3\u91ca\u4e86\u4eba\u5747\u56fd\u5185\u751f\u4ea7\u603b\u503c\uff08GDP\uff09\u5dee\u5f02\u768450\u81f365\u4e2a\u767e\u5206\u70b9\uff0c\u800c\u7ecf\u5178\u6a21\u578b\u7684\u4f30\u8ba1\u4ec5\u4e3a30\u4e2a\u767e\u5206\u70b9\u3002\u6587\u732e\u5728\u6446\u8131\u67ef\u5e03-\u9053\u683c\u62c9\u65af\u751f\u4ea7\u51fd\u6570\u3001\u5e76\u5c06\u7ba1\u7406\u8d28\u91cf\u7b49\u5148\u524d\u7eb3\u5165\u603b\u8981\u7d20\u751f\u4ea7\u7387\uff08TFP\uff09\u7684\u56e0\u7d20\u5355\u72ec\u6d4b\u91cf\u65b9\u9762\u4e5f\u53d6\u5f97\u4e86\u8fdb\u5c55\u3002\u672c\u6587\u56de\u987e\u4e86\u8fd9\u4e9b\u8fdb\u5c55\u7684\u65b0\u542b\u4e49\uff0c\u6307\u51fa\u4e86\u672a\u6765\u7814\u7a76\u7684\u6f5c\u5728\u65b9\u5411\uff0c\u5e76\u6307\u51fa\u4e86\u53d1\u5c55\u4f1a\u8ba1\u7684\u5c40\u9650\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35827", "journal": "NBER", "title": "Crime in Covid Times", "authors": ["Jens Ludwig"], "author_details": [{"name": "Jens Ludwig", "affiliations": []}], "abstract": "What caused the historically unique volatility in American homicides since 2019, driven by gun homicides? While there is no shortage of candidate explanations, a coherent understanding has been elusive because of the widely held view that gun violence, like other crimes, stems from a rational weighing of benefits and costs as in Becker (1968). This model does a generally poor job of explaining recent trends in homicide. Behavioral economics helps explain what the Becker model cannot. This view starts with the fact that most shootings don\u2019t further some larger goal like robbery or gang wars over drug turf (\u201cinstrumental violence\u201d); they\u2019re arguments settled with guns (\u201cexpressive violence\u201d). Why do arguments start or escalate? The behavioral model points to automatic cognition that is fast, effortless but sometimes prone to error. The pandemic increased automaticity by increasing distress \u2013 a cognitive \u201cbandwidth tax.\u201d Recent homicide trends, driven by changes in expressive violence, are mirrored by similar trends for deaths from drug overdose, car crashes, and suicide (especially for Black Americans, the group most affected by violence) \u2013 \u201cdeaths of decision-making.\u201d Also relevant is a large rise and fall in gun carrying, which might partially stem from Becker-like mechanisms: Large changes in handgun sales and police stops, both of which may also have been affected by the killing of George Floyd. Since American gun violence is mostly arguments with guns, no wonder homicide trends are due mostly to changes in the number of arguments and the odds a given argument had a gun present.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35827", "title_zh": "\u75ab\u60c5\u65f6\u671f\u7684\u72af\u7f6a", "abstract_zh": "\u662f\u4ec0\u4e48\u5bfc\u81f4\u4e86\u81ea2019\u5e74\u4ee5\u6765\u7f8e\u56fd\u51f6\u6740\u6848\u5386\u53f2\u4e0a\u524d\u6240\u672a\u6709\u7684\u6ce2\u52a8\uff0c\u5c24\u5176\u662f\u67aa\u51fb\u51f6\u6740\u6848\uff1f\u5c3d\u7ba1\u6709\u8bb8\u591a\u53ef\u80fd\u7684\u89e3\u91ca\uff0c\u4f46\u4eba\u4eec\u4e00\u76f4\u7f3a\u4e4f\u4e00\u4e2a\u8fde\u8d2f\u7684\u7406\u89e3\uff0c\u539f\u56e0\u5728\u4e8e\u666e\u904d\u8ba4\u4e3a\u67aa\u652f\u66b4\u529b\u548c\u5176\u4ed6\u72af\u7f6a\u4e00\u6837\uff0c\u6e90\u4e8e\u8d1d\u514b\u5c14\uff081968\uff09\u6240\u63d0\u51fa\u7684\u7406\u6027\u6743\u8861\u6536\u76ca\u4e0e\u6210\u672c\u7684\u6a21\u578b\u3002\u7136\u800c\uff0c\u8fd9\u4e00\u6a21\u578b\u5728\u89e3\u91ca\u8fd1\u671f\u51f6\u6740\u8d8b\u52bf\u65b9\u9762\u8868\u73b0\u4e0d\u4f73\u3002\u884c\u4e3a\u7ecf\u6d4e\u5b66\u4e3a\u8d1d\u514b\u5c14\u6a21\u578b\u65e0\u6cd5\u89e3\u91ca\u7684\u73b0\u8c61\u63d0\u4f9b\u4e86\u65b0\u7684\u89c6\u89d2\u3002\u8be5\u89c2\u70b9\u8ba4\u4e3a\uff0c\u5927\u591a\u6570\u67aa\u51fb\u4e8b\u4ef6\u5e76\u975e\u4e3a\u4e86\u5b9e\u73b0\u67d0\u79cd\u66f4\u5927\u7684\u76ee\u6807\uff0c\u6bd4\u5982\u62a2\u52ab\u6216\u6bd2\u54c1\u5730\u76d8\u7684\u5e2e\u6d3e\u6218\u4e89\uff08\u5373\u2018\u5de5\u5177\u6027\u66b4\u529b\u2019\uff09\uff0c\u800c\u662f\u6e90\u4e8e\u4e89\u6267\u4e2d\u7528\u67aa\u89e3\u51b3\uff08\u5373\u2018\u8868\u8fbe\u6027\u66b4\u529b\u2019\uff09\u3002\u4e3a\u4ec0\u4e48\u4e89\u6267\u4f1a\u5f00\u59cb\u6216\u5347\u7ea7\uff1f\u884c\u4e3a\u7ecf\u6d4e\u5b66\u6307\u51fa\uff0c\u8fd9\u4e0e\u5feb\u901f\u3001\u8f7b\u677e\u4f46\u6709\u65f6\u4f1a\u51fa\u9519\u7684\u81ea\u52a8\u8ba4\u77e5\u6709\u5173\u3002\u75ab\u60c5\u589e\u52a0\u4e86\u4eba\u4eec\u7684\u75db\u82e6\u7a0b\u5ea6\uff0c\u4ece\u800c\u63d0\u9ad8\u4e86\u8ba4\u77e5\u7684\u2018\u5e26\u5bbd\u7a0e\u2019\uff0c\u5bfc\u81f4\u81ea\u52a8\u8ba4\u77e5\u66f4\u52a0\u663e\u8457\u3002\u8fd1\u671f\u51f6\u6740\u8d8b\u52bf\uff0c\u7531\u8868\u8fbe\u6027\u66b4\u529b\u7684\u53d8\u5316\u9a71\u52a8\uff0c\u4e5f\u4e0e\u836f\u7269\u8fc7\u91cf\u6b7b\u4ea1\u3001\u4ea4\u901a\u4e8b\u6545\u6b7b\u4ea1\u4ee5\u53ca\u81ea\u6740\uff08\u5c24\u5176\u662f\u5bf9\u66b4\u529b\u5f71\u54cd\u6700\u4e25\u91cd\u7684\u9ed1\u4eba\u7fa4\u4f53\uff09\u7684\u7c7b\u4f3c\u8d8b\u52bf\u76f8\u547c\u5e94\u2014\u2014\u8fd9\u4e9b\u90fd\u88ab\u79f0\u4e3a\u2018\u51b3\u7b56\u80fd\u529b\u4e27\u5931\u7684\u6b7b\u4ea1\u2019\u3002\u6b64\u5916\uff0c\u643a\u5e26\u67aa\u652f\u7684\u884c\u4e3a\u4e5f\u51fa\u73b0\u4e86\u5927\u5e45\u6ce2\u52a8\uff0c\u8fd9\u53ef\u80fd\u90e8\u5206\u6e90\u4e8e\u8d1d\u514b\u5c14\u6a21\u578b\u4e2d\u7684\u673a\u5236\uff1a\u624b\u67aa\u9500\u91cf\u548c\u8b66\u5bdf\u67e5\u6263\u6570\u91cf\u7684\u663e\u8457\u53d8\u5316\uff0c\u4e5f\u53ef\u80fd\u53d7\u5230\u4e54\u6cbb\u00b7\u5f17\u6d1b\u4f0a\u5fb7\u88ab\u6740\u5bb3\u4e8b\u4ef6\u7684\u5f71\u54cd\u3002\u7531\u4e8e\u7f8e\u56fd\u5927\u591a\u6570\u67aa\u652f\u66b4\u529b\u4e8b\u4ef6\u672c\u8d28\u4e0a\u662f\u4e89\u6267\u4e2d\u7528\u67aa\u89e3\u51b3\uff0c\u56e0\u6b64\u51f6\u6740\u6848\u8d8b\u52bf\u4e3b\u8981\u6e90\u4e8e\u4e89\u6267\u6570\u91cf\u7684\u589e\u52a0\u4ee5\u53ca\u6bcf\u6b21\u4e89\u6267\u4e2d\u4f7f\u7528\u67aa\u652f\u7684\u6982\u7387\u53d8\u5316\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35828", "journal": "NBER", "title": "Liability and Pricing of Dual-Use AI", "authors": ["Joshua S. Gans"], "author_details": [{"name": "Joshua S. Gans", "affiliations": []}], "abstract": "How much liability should AI providers bear when their services enable both attack and defence? Liability can improve welfare while increasing harm. Providers sell a common input to productive users, attackers and defenders. Within a defended contest, a higher common price reduces effort without changing attack success or attacker profits, saving resources and improving the target's security payoff. Compensation weakens defence and raises attacker profits. Optimal liability balances these effects against productive exclusion. Greater competition can lower optimal liability; every such decline must end at an outcome retaining defence. With cybersecurity access fixed, monopoly can warrant partial liability but never full liability when provision is worthwhile. When guardrails preserving productive uses are available, strong competition favours universal guarding socially but encourages unilateral removal at insufficient liability. At a fixed provider count, sufficiently many productive users ensure a pure equilibrium with universal guarding under high liability. A universal-guarding requirement makes liability redundant. Under monopoly, adoption follows a unique liability threshold, while zero liability remains uniquely optimal for a range of parameters with sufficiently many productive users.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35828", "title_zh": "\u53cc\u91cd\u7528\u9014\u4eba\u5de5\u667a\u80fd\u7684\u8d23\u4efb\u4e0e\u5b9a\u4ef7", "abstract_zh": "\u5f53\u4eba\u5de5\u667a\u80fd\u670d\u52a1\u65e2\u53ef\u7528\u4e8e\u653b\u51fb\u4e5f\u53ef\u7528\u4e8e\u9632\u5fa1\u65f6\uff0cAI\u63d0\u4f9b\u5546\u5e94\u627f\u62c5\u591a\u5c11\u8d23\u4efb\uff1f\u8d23\u4efb\u53ef\u80fd\u63d0\u5347\u798f\u5229\uff0c\u4f46\u4e5f\u4f1a\u589e\u52a0\u635f\u5bb3\u3002\u63d0\u4f9b\u5546\u5411\u751f\u4ea7\u6027\u7528\u6237\u3001\u653b\u51fb\u8005\u548c\u9632\u5fa1\u8005\u51fa\u552e\u4e00\u79cd\u5171\u540c\u6295\u5165\u54c1\u3002\u5728\u53d7\u4fdd\u62a4\u7684\u7ade\u4e89\u4e2d\uff0c\u66f4\u9ad8\u7684\u5171\u540c\u4ef7\u683c\u4f1a\u51cf\u5c11\u52aa\u529b\u7a0b\u5ea6\uff0c\u800c\u4e0d\u4f1a\u6539\u53d8\u653b\u51fb\u6210\u529f\u7387\u6216\u653b\u51fb\u8005\u7684\u5229\u6da6\uff0c\u4ece\u800c\u8282\u7701\u8d44\u6e90\u5e76\u63d0\u5347\u76ee\u6807\u7684\u5b89\u5168\u6536\u76ca\u3002\u8d54\u507f\u4f1a\u524a\u5f31\u9632\u5fa1\u80fd\u529b\u5e76\u63d0\u9ad8\u653b\u51fb\u8005\u7684\u5229\u6da6\u3002\u6700\u4f18\u8d23\u4efb\u9700\u5728\u63d0\u5347\u751f\u4ea7\u6027\u7528\u6237\u6392\u9664\u98ce\u9669\u4e0e\u51cf\u5c11\u9632\u5fa1\u4e4b\u95f4\u53d6\u5f97\u5e73\u8861\u3002\u66f4\u5f3a\u7684\u7ade\u4e89\u53ef\u4ee5\u964d\u4f4e\u6700\u4f18\u8d23\u4efb\u6c34\u5e73\uff1b\u4f46\u4efb\u4f55\u6b64\u7c7b\u4e0b\u964d\u90fd\u5fc5\u987b\u4ee5\u4fdd\u7559\u9632\u5fa1\u6548\u679c\u4e3a\u7ec8\u70b9\u3002\u5728\u7f51\u7edc\u5b89\u5168\u8bbf\u95ee\u56fa\u5b9a\u7684\u60c5\u51b5\u4e0b\uff0c\u5784\u65ad\u60c5\u51b5\u4e0b\u5728\u670d\u52a1\u5177\u6709\u4ef7\u503c\u65f6\u53ea\u80fd\u5141\u8bb8\u90e8\u5206\u8d23\u4efb\uff0c\u800c\u7edd\u4e0d\u80fd\u627f\u62c5\u5b8c\u5168\u8d23\u4efb\u3002\u5f53\u5b58\u5728\u4fdd\u62a4\u751f\u4ea7\u6027\u7528\u9014\u7684\u62a4\u680f\u65f6\uff0c\u5f3a\u7ade\u4e89\u5728\u793e\u4f1a\u5c42\u9762\u6709\u5229\u4e8e\u666e\u904d\u5b9e\u65bd\u9632\u62a4\uff0c\u4f46\u53ef\u80fd\u4fc3\u4f7f\u5355\u65b9\u9762\u53d6\u6d88\u9632\u62a4\uff0c\u4e14\u8d23\u4efb\u6c34\u5e73\u4e0d\u8db3\u3002\u5728\u63d0\u4f9b\u5546\u6570\u91cf\u56fa\u5b9a\u7684\u60c5\u51b5\u4e0b\uff0c\u8db3\u591f\u591a\u7684\u751f\u4ea7\u6027\u7528\u6237\u53ef\u786e\u4fdd\u5728\u9ad8\u8d23\u4efb\u6c34\u5e73\u4e0b\u5f62\u6210\u7eaf\u7cb9\u7684\u666e\u904d\u9632\u62a4\u5747\u8861\u3002\u666e\u904d\u9632\u62a4\u8981\u6c42\u4f7f\u5f97\u8d23\u4efb\u673a\u5236\u53d8\u5f97\u591a\u4f59\u3002\u5728\u5784\u65ad\u60c5\u51b5\u4e0b\uff0c\u91c7\u7528\u884c\u4e3a\u9075\u5faa\u4e00\u4e2a\u72ec\u7279\u7684\u8d23\u4efb\u9608\u503c\uff0c\u800c\u5728\u751f\u4ea7\u6027\u7528\u6237\u6570\u91cf\u8db3\u591f\u591a\u7684\u60c5\u51b5\u4e0b\uff0c\u5bf9\u4e8e\u4e00\u7cfb\u5217\u53c2\u6570\uff0c\u96f6\u8d23\u4efb\u59cb\u7ec8\u662f\u552f\u4e00\u6700\u4f18\u9009\u62e9\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.3386/w35829", "journal": "NBER", "title": "Importers, Market Power and Optimal Tariffs", "authors": ["Jonathan Becker", "Corina Boar", "Virgiliu Midrigan"], "author_details": [{"name": "Jonathan Becker", "affiliations": []}, {"name": "Corina Boar", "affiliations": []}, {"name": "Virgiliu Midrigan", "affiliations": []}], "abstract": "Importers are few and large, have higher labor productivity and pass through cost changes to prices incompletely. We study optimal tariffs in a model consistent with these facts. Firms pay a fixed cost to import and charge markups that increase with size. Market power implies that importers are too few and too small relative to the efficient allocations. Tariffs amplify this distortion. We derive a formula that relates the optimal tariff not only to the foreign export supply elasticity but also to how much distortions amplify the effect of trade costs on welfare. In our calibrated economy the optimal tariff is negative and decreases with country size.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35829", "title_zh": "\u8fdb\u53e3\u5546\u3001\u5e02\u573a\u529b\u91cf\u4e0e\u6700\u4f18\u5173\u7a0e", "abstract_zh": "\u8fdb\u53e3\u5546\u6570\u91cf\u5c11\u4e14\u89c4\u6a21\u5927\uff0c\u52b3\u52a8\u751f\u4ea7\u7387\u8f83\u9ad8\uff0c\u4e14\u5bf9\u4ef7\u683c\u6210\u672c\u53d8\u5316\u7684\u4f20\u9012\u4e0d\u5b8c\u5168\u3002\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u4e2a\u4e0e\u8fd9\u4e9b\u4e8b\u5b9e\u4e00\u81f4\u7684\u6a21\u578b\u4e2d\u7684\u6700\u4f18\u5173\u7a0e\u3002\u4f01\u4e1a\u8fdb\u53e3\u9700\u652f\u4ed8\u56fa\u5b9a\u6210\u672c\uff0c\u5e76\u4e14\u5b9a\u4ef7\u5b58\u5728\u968f\u89c4\u6a21\u589e\u52a0\u7684\u6ea2\u4ef7\u3002\u5e02\u573a\u529b\u91cf\u610f\u5473\u7740\u8fdb\u53e3\u5546\u6570\u91cf\u548c\u89c4\u6a21\u76f8\u5bf9\u4e8e\u6709\u6548\u914d\u7f6e\u800c\u8a00\u8fc7\u5c11\u3002\u5173\u7a0e\u4f1a\u52a0\u5267\u8fd9\u4e00\u626d\u66f2\u3002\u6211\u4eec\u63a8\u5bfc\u51fa\u4e00\u4e2a\u516c\u5f0f\uff0c\u8be5\u516c\u5f0f\u4e0d\u4ec5\u5c06\u6700\u4f18\u5173\u7a0e\u4e0e\u5916\u56fd\u51fa\u53e3\u4f9b\u7ed9\u5f39\u6027\u8054\u7cfb\u8d77\u6765\uff0c\u8fd8\u5c06\u5176\u4e0e\u626d\u66f2\u7a0b\u5ea6\u653e\u5927\u8d38\u6613\u6210\u672c\u5bf9\u798f\u5229\u5f71\u54cd\u7684\u7a0b\u5ea6\u76f8\u5173\u8054\u3002\u5728\u6211\u4eec\u7684\u6821\u51c6\u7ecf\u6d4e\u4e2d\uff0c\u6700\u4f18\u5173\u7a0e\u4e3a\u8d1f\u503c\uff0c\u5e76\u968f\u7740\u56fd\u5bb6\u89c4\u6a21\u7684\u589e\u5927\u800c\u51cf\u5c0f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.3386/w35830", "journal": "NBER", "title": "Economics of Demand-Side and Supply-Side Climate Policies", "authors": ["Ryan Kellogg"], "author_details": [{"name": "Ryan Kellogg", "affiliations": []}], "abstract": "Should a jurisdiction seeking to cut greenhouse gas emissions use demand-side climate policies that target fossil fuel consumption? Or should it introduce supply-side policies that target extraction? My analysis points to a policy portfolio rather than an either/or choice. ``Leakage'' of emissions to unregulated jurisdictions can be mitigated by combining standard demand-side carbon emissions pricing with supply-side pricing of carbon extraction. Emissions pricing drives leakage by lowering fossil fuel prices abroad; extraction pricing counteracts this effect. Supply-side climate policies in practice, however, do not broadly price extraction but instead narrowly foreclose investments in fossil fuel infrastructure and are thus inefficient. To reduce carbon demand, an alternative to emissions pricing is support for clean energy. I emphasize reforms to transmission planning and utility governance as crucial for unlocking clean energy resources' potential, and I highlight the case for publicly supporting clean energy R&D, including green industrial policy, to reduce carbon emissions not just at home but also abroad. I close by discussing distributional consequences. Domestically, carbon pricing and clean energy subsidies have sharply different distributional profiles. Globally, carbon extraction pricing would harm low-income countries that are also fossil fuel importers, though there also exist low-income fossil fuel exporters that would benefit.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35830", "title_zh": "\u9700\u6c42\u4fa7\u4e0e\u4f9b\u7ed9\u4fa7\u6c14\u5019\u653f\u7b56\u7684\u7ecf\u6d4e\u5b66", "abstract_zh": "\u4e00\u4e2a\u5e0c\u671b\u51cf\u5c11\u6e29\u5ba4\u6c14\u4f53\u6392\u653e\u7684\u5730\u533a\uff0c\u662f\u5e94\u8be5\u91c7\u7528\u9488\u5bf9\u5316\u77f3\u71c3\u6599\u6d88\u8d39\u7684\u9700\u6c42\u4fa7\u6c14\u5019\u653f\u7b56\uff0c\u8fd8\u662f\u5e94\u8be5\u5f15\u5165\u9488\u5bf9\u5f00\u91c7\u7684\u4f9b\u7ed9\u4fa7\u653f\u7b56\uff1f\u6211\u7684\u5206\u6790\u8868\u660e\uff0c\u5e94\u91c7\u53d6\u4e00\u79cd\u653f\u7b56\u7ec4\u5408\uff0c\u800c\u975e\u975e\u6b64\u5373\u5f7c\u7684\u9009\u62e9\u3002\u901a\u8fc7\u5c06\u4f20\u7edf\u7684\u57fa\u4e8e\u78b3\u6392\u653e\u5b9a\u4ef7\u7684\u9700\u6c42\u4fa7\u653f\u7b56\u4e0e\u9488\u5bf9\u78b3\u5f00\u91c7\u7684\u4f9b\u7ed9\u4fa7\u5b9a\u4ef7\u76f8\u7ed3\u5408\uff0c\u53ef\u4ee5\u7f13\u89e3\u6392\u653e\u5411\u672a\u76d1\u7ba1\u5730\u533a\u8f6c\u79fb\uff08\u5373\u2018\u6cc4\u6f0f\u2019\uff09\u7684\u95ee\u9898\u3002\u6392\u653e\u5b9a\u4ef7\u4f1a\u901a\u8fc7\u964d\u4f4e\u6d77\u5916\u5316\u77f3\u71c3\u6599\u4ef7\u683c\u6765\u5f15\u53d1\u6cc4\u6f0f\uff1b\u800c\u5f00\u91c7\u5b9a\u4ef7\u5219\u53ef\u4ee5\u62b5\u6d88\u8fd9\u4e00\u6548\u5e94\u3002\u7136\u800c\uff0c\u5728\u5b9e\u8df5\u4e2d\uff0c\u4f9b\u7ed9\u4fa7\u6c14\u5019\u653f\u7b56\u5e76\u672a\u5bf9\u5f00\u91c7\u8fdb\u884c\u5e7f\u6cdb\u5b9a\u4ef7\uff0c\u800c\u662f\u4ec5\u9650\u4e8e\u9650\u5236\u5316\u77f3\u71c3\u6599\u57fa\u7840\u8bbe\u65bd\u7684\u6295\u8d44\uff0c\u56e0\u6b64\u6548\u7387\u8f83\u4f4e\u3002\u4e3a\u4e86\u51cf\u5c11\u78b3\u9700\u6c42\uff0c\u66ff\u4ee3\u78b3\u5b9a\u4ef7\u7684\u53e6\u4e00\u79cd\u65b9\u5f0f\u662f\u652f\u6301\u6e05\u6d01\u80fd\u6e90\u3002\u6211\u5f3a\u8c03\uff0c\u5bf9\u8f93\u7535\u89c4\u5212\u548c\u516c\u7528\u4e8b\u4e1a\u6cbb\u7406\u7684\u6539\u9769\u5bf9\u4e8e\u91ca\u653e\u6e05\u6d01\u80fd\u6e90\u8d44\u6e90\u7684\u6f5c\u529b\u81f3\u5173\u91cd\u8981\uff0c\u5e76\u6307\u51fa\u5e94\u7531\u516c\u5171\u90e8\u95e8\u652f\u6301\u6e05\u6d01\u80fd\u6e90\u7814\u53d1\uff0c\u5305\u62ec\u7eff\u8272\u4ea7\u4e1a\u653f\u7b56\uff0c\u4ee5\u4e0d\u4ec5\u5728\u56fd\u5185\uff0c\u4e5f\u5728\u56fd\u5916\u51cf\u5c11\u78b3\u6392\u653e\u3002\u6700\u540e\uff0c\u6211\u8ba8\u8bba\u4e86\u5206\u914d\u6548\u5e94\u3002\u5728\u56fd\u5185\uff0c\u78b3\u5b9a\u4ef7\u4e0e\u6e05\u6d01\u80fd\u6e90\u8865\u8d34\u5177\u6709\u622a\u7136\u4e0d\u540c\u7684\u5206\u914d\u7279\u5f81\u3002\u5728\u5168\u7403\u8303\u56f4\u5185\uff0c\u78b3\u5f00\u91c7\u5b9a\u4ef7\u5c06\u635f\u5bb3\u90a3\u4e9b\u540c\u65f6\u4e5f\u662f\u5316\u77f3\u71c3\u6599\u8fdb\u53e3\u56fd\u7684\u4f4e\u6536\u5165\u56fd\u5bb6\uff0c\u5c3d\u7ba1\u4e5f\u5b58\u5728\u4f1a\u4ece\u4e2d\u53d7\u76ca\u7684\u4f4e\u6536\u5165\u5316\u77f3\u71c3\u6599\u51fa\u53e3\u56fd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.3386/w35831", "journal": "NBER", "title": "Subjective Models of the Macroeconomy and the Transmission of Monetary Policy", "authors": ["Francesco D\u2019Acunto", "Dimitris Georgarakos", "Geoff Kenny", "Michael Weber"], "author_details": [{"name": "Francesco D\u2019Acunto", "affiliations": []}, {"name": "Dimitris Georgarakos", "affiliations": []}, {"name": "Geoff Kenny", "affiliations": []}, {"name": "Michael Weber", "affiliations": []}], "abstract": "Standard macroeconomic theories assume that representative or heterogeneous agents share a common model of how the economy operates. Yet evidence shows that households hold heterogeneous subjective models---distinct beliefs about how macroeconomic variables interact. As a result, identical shocks or policies may elicit different responses from otherwise similar households. We test this hypothesis by measuring subjective models and investigating their role in the transmission of monetary policy to consumption embedding randomized controlled experiment in a large-scale, multi-country survey. Consumers who believe that monetary tightening primarily operates through its effects on borrowing or savings rates plan to reduce consumption more in response to randomly assigned rate increase scenarios. By contrast, those who think about inflation or general equilibrium effects adjust consumption less. These differences are not explained by demographics, financial characteristics, including mortgage holdings and mortgage type, or country-level factors. Households' actual consumption responses to endogenous policy-rate changes exhibit broadly similar patterns. Our findings stress that heterogeneity in subjective models is an overlooked determinant of monetary policy transmission.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35831", "title_zh": "\u5b8f\u89c2\u7ecf\u6d4e\u7684\u4e3b\u89c2\u6a21\u578b\u53ca\u5176\u5bf9\u8d27\u5e01\u653f\u7b56\u4f20\u5bfc\u7684\u5f71\u54cd", "abstract_zh": "\u6807\u51c6\u7684\u5b8f\u89c2\u7ecf\u6d4e\u7406\u8bba\u5047\u8bbe\u4ee3\u8868\u6027\u6216\u5f02\u8d28\u6027\u4e3b\u4f53\u5171\u4eab\u4e00\u4e2a\u5173\u4e8e\u7ecf\u6d4e\u8fd0\u884c\u65b9\u5f0f\u7684\u5171\u540c\u6a21\u578b\u3002\u7136\u800c\uff0c\u8bc1\u636e\u8868\u660e\u5bb6\u5ead\u6301\u6709\u4e0d\u540c\u7684\u4e3b\u89c2\u6a21\u578b\u2014\u2014\u5bf9\u5b8f\u89c2\u7ecf\u6d4e\u53d8\u91cf\u4e4b\u95f4\u5173\u7cfb\u6301\u6709\u4e0d\u540c\u7684\u4fe1\u5ff5\u3002\u56e0\u6b64\uff0c\u5373\u4f7f\u9762\u5bf9\u76f8\u540c\u7684\u51b2\u51fb\u6216\u653f\u7b56\uff0c\u76f8\u4f3c\u7684\u5bb6\u5ead\u4e5f\u53ef\u80fd\u4ea7\u751f\u4e0d\u540c\u7684\u53cd\u5e94\u3002\u6211\u4eec\u901a\u8fc7\u6d4b\u91cf\u4e3b\u89c2\u6a21\u578b\u5e76\u7814\u7a76\u5176\u5728\u8d27\u5e01\u653f\u7b56\u5411\u6d88\u8d39\u4f20\u5bfc\u8fc7\u7a0b\u4e2d\u7684\u4f5c\u7528\uff0c\u9a8c\u8bc1\u4e86\u8fd9\u4e00\u5047\u8bbe\u3002\u5728\u4e00\u9879\u5927\u89c4\u6a21\u3001\u591a\u56fd\u8c03\u67e5\u4e2d\u8fdb\u884c\u7684\u968f\u673a\u5bf9\u7167\u5b9e\u9a8c\u663e\u793a\uff0c\u8ba4\u4e3a\u8d27\u5e01\u653f\u7b56\u7d27\u7f29\u4e3b\u8981\u901a\u8fc7\u5f71\u54cd\u501f\u8d37\u6216\u50a8\u84c4\u7387\u53d1\u6325\u4f5c\u7528\u7684\u6d88\u8d39\u8005\uff0c\u5728\u9762\u5bf9\u968f\u673a\u5206\u914d\u7684\u5229\u7387\u4e0a\u5347\u60c5\u666f\u65f6\uff0c\u8ba1\u5212\u51cf\u5c11\u6d88\u8d39\u66f4\u591a\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u8ba4\u4e3a\u901a\u80c0\u6216\u4e00\u822c\u5747\u8861\u6548\u5e94\u662f\u4e3b\u8981\u4f5c\u7528\u673a\u5236\u7684\u6d88\u8d39\u8005\u5219\u8c03\u6574\u6d88\u8d39\u8f83\u5c11\u3002\u8fd9\u4e9b\u5dee\u5f02\u65e0\u6cd5\u7531\u4eba\u53e3\u7edf\u8ba1\u7279\u5f81\u3001\u91d1\u878d\u7279\u5f81\uff08\u5305\u62ec\u623f\u8d37\u6301\u6709\u60c5\u51b5\u548c\u623f\u8d37\u7c7b\u578b\uff09\u6216\u56fd\u5bb6\u5c42\u9762\u56e0\u7d20\u89e3\u91ca\u3002\u5bb6\u5ead\u5bf9\u5185\u751f\u653f\u7b56\u5229\u7387\u53d8\u5316\u7684\u5b9e\u9645\u6d88\u8d39\u53cd\u5e94\u4e5f\u8868\u73b0\u51fa\u7c7b\u4f3c\u6a21\u5f0f\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u5f3a\u8c03\uff0c\u4e3b\u89c2\u6a21\u578b\u7684\u5f02\u8d28\u6027\u662f\u8d27\u5e01\u653f\u7b56\u4f20\u5bfc\u8fc7\u7a0b\u4e2d\u88ab\u5ffd\u89c6\u7684\u91cd\u8981\u51b3\u5b9a\u56e0\u7d20\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35832", "journal": "NBER", "title": "Global Temperature and Global Mortality", "authors": ["Adrien Bilal", "Diego R. K\u00e4nzig", "Krzysztof Lisiecki"], "author_details": [{"name": "Adrien Bilal", "affiliations": []}, {"name": "Diego R. K\u00e4nzig", "affiliations": []}, {"name": "Krzysztof Lisiecki", "affiliations": []}], "abstract": "This paper documents large indirect mortality impacts of climate change. Exploiting natural global temperature variability, we find that 1\u00b0C of warming increases annual mortality by 2.5 deaths per 1,000 individuals, compared to 0.1 deaths per 1,000 due to the associated local heat exposure. Using external estimates of the impact of global income on mortality, we show that the macroeconomic effects of global temperature changes explain two thirds of the gap between these estimates. We use this evidence to estimate damage functions in a neoclassical growth model that links mortality and economic activity and accounts for adaptation to mortality impacts. Mortality contributes $400 per ton of CO\u2082 to the Social Cost of Carbon, or one quarter of total climate damages. These results suggest that economic adaptation has a double dividend by also reducing climate-related mortality.", "date": "2026-09-28", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-28T22:00:03+00:00", "url": "https://www.nber.org/papers/w35832", "title_zh": "\u5168\u7403\u6e29\u5ea6\u4e0e\u5168\u7403\u6b7b\u4ea1\u7387", "abstract_zh": "\u672c\u6587\u8bb0\u5f55\u4e86\u6c14\u5019\u53d8\u5316\u5e26\u6765\u7684\u91cd\u5927\u95f4\u63a5\u6b7b\u4ea1\u5f71\u54cd\u3002\u5229\u7528\u81ea\u7136\u5168\u7403\u6e29\u5ea6\u7684\u6ce2\u52a8\u6027\uff0c\u6211\u4eec\u53d1\u73b0\u5168\u7403\u6e29\u5ea6\u4e0a\u53471\u00b0C\u4f1a\u4f7f\u6bcf\u5e74\u6bcf\u5343\u4eba\u589e\u52a02.5\u4f8b\u6b7b\u4ea1\uff0c\u800c\u4e0e\u5c40\u90e8\u9ad8\u6e29\u66b4\u9732\u76f8\u5173\u7684\u6b7b\u4ea1\u4ec5\u4e3a\u6bcf\u5343\u4eba0.1\u4f8b\u3002\u5229\u7528\u5916\u90e8\u4f30\u8ba1\u7684\u5168\u7403\u6536\u5165\u5bf9\u6b7b\u4ea1\u7387\u7684\u5f71\u54cd\uff0c\u6211\u4eec\u8868\u660e\u5168\u7403\u6e29\u5ea6\u53d8\u5316\u7684\u5b8f\u89c2\u7ecf\u6d4e\u6548\u5e94\u89e3\u91ca\u4e86\u8fd9\u4e24\u9879\u4f30\u8ba1\u4e4b\u95f4\u5dee\u8ddd\u7684\u4e09\u5206\u4e4b\u4e8c\u3002\u6211\u4eec\u57fa\u4e8e\u8fd9\u4e9b\u8bc1\u636e\uff0c\u5728\u4e00\u4e2a\u5c06\u6b7b\u4ea1\u7387\u4e0e\u7ecf\u6d4e\u6d3b\u52a8\u8054\u7cfb\u8d77\u6765\u3001\u5e76\u8003\u8651\u5bf9\u6b7b\u4ea1\u7387\u5f71\u54cd\u8fdb\u884c\u9002\u5e94\u7684\u65b0\u53e4\u5178\u589e\u957f\u6a21\u578b\u4e2d\uff0c\u4f30\u8ba1\u4e86\u635f\u5bb3\u51fd\u6570\u3002\u6b7b\u4ea1\u7387\u5bf9\u6bcf\u5428\u4e8c\u6c27\u5316\u78b3\u7684\u793e\u4ea4\u6210\u672c\u8d21\u732e\u4e3a400\u7f8e\u5143\uff0c\u5360\u603b\u6c14\u5019\u635f\u5bb3\u7684\u56db\u5206\u4e4b\u4e00\u3002\u8fd9\u4e9b\u7ed3\u679c\u8868\u660e\uff0c\u7ecf\u6d4e\u9002\u5e94\u4e0d\u4ec5\u51cf\u5c11\u4e86\u6c14\u5019\u76f8\u5173\u6b7b\u4ea1\uff0c\u8fd8\u4ea7\u751f\u4e86\u53cc\u91cd\u6536\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag043", "journal": "QJE", "title": "BUSING TO OPPORTUNITY? THE IMPACTS OF THE METCO VOLUNTARY SCHOOL DESEGREGATION PROGRAM ON URBAN STUDENTS OF COLOR", "authors": ["Elizabeth Setren"], "author_details": [{"name": "Elizabeth Setren", "affiliations": ["Tufts University and NBER ,"]}], "abstract": "Abstract School assignment policies are a key lever for expanding access to high-performing schools and promoting racial and socioeconomic integration. For over 50 years, the Metropolitan Council for Educational Opportunity (METCO) has bussed students of color from Boston, Massachusetts, to relatively wealthier and predominantly white suburbs. I estimate the effects of attending a high-performing suburban school by comparing applicants who receive enrollment offers with applicants who do not. A two-stage least squares approach exploits waitlist assignment priorities and controls for a rich set of characteristics from birth records and application data. Attending a suburban school boosts math and English test scores, reduces dropout, and increases on-time high school graduation. Four-year college aspirations, enrollment, and graduation increase along with earnings in adulthood. Students whose parents did not attend college and boys experience the largest effects. The evidence points to several mechanisms, including access to higher value-added schools, higher-achieving peers, and schools with stronger college-going norms. Participants are more likely to be tracked into lower-performing classes, implying that effects could be larger with access to more advanced coursework. District value-added estimates suggest that students\u2019 educational trajectories shift at least as much as they would from growing up in the suburban districts.", "date": "2026-09-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-27T00:00:01+00:00", "url": "https://doi.org/10.1093/qje/qjag043", "title_zh": "\u901a\u5411\u673a\u4f1a\uff1fMETCO\u81ea\u613f\u6027\u5b66\u6821\u53bb\u79cd\u65cf\u9694\u79bb\u8ba1\u5212\u5bf9\u57ce\u5e02\u6709\u8272\u4eba\u79cd\u5b66\u751f\u7684\u5f71\u54cd", "abstract_zh": "\u6458\u8981 \u5b66\u6821\u5206\u914d\u653f\u7b56\u662f\u6269\u5927\u4f18\u8d28\u5b66\u6821\u53ef\u53ca\u6027\u5e76\u4fc3\u8fdb\u79cd\u65cf\u548c\u7ecf\u6d4e\u72b6\u51b5\u878d\u5408\u7684\u5173\u952e\u624b\u6bb5\u3002\u5728\u8fc7\u53bb50\u591a\u5e74\u4e2d\uff0c\u5927\u90fd\u4f1a\u6559\u80b2\u673a\u4f1a\u59d4\u5458\u4f1a\uff08METCO\uff09\u4e00\u76f4\u5c06\u9a6c\u8428\u8bf8\u585e\u5dde\u6ce2\u58eb\u987f\u7684\u6709\u8272\u4eba\u79cd\u5b66\u751f\u9001\u5f80\u76f8\u5bf9\u5bcc\u88d5\u4e14\u4ee5\u767d\u4eba\u4e3a\u4e3b\u7684\u90ca\u533a\u3002\u6211\u901a\u8fc7\u6bd4\u8f83\u83b7\u5f97\u5165\u5b66\u9080\u8bf7\u7684\u5b66\u751f\u4e0e\u672a\u83b7\u5f97\u9080\u8bf7\u7684\u5b66\u751f\uff0c\u6765\u4f30\u8ba1\u8fdb\u5165\u4f18\u8d28\u90ca\u533a\u5b66\u6821\u7684\u5f71\u54cd\u3002\u91c7\u7528\u4e24\u9636\u6bb5\u6700\u5c0f\u4e8c\u4e58\u6cd5\uff0c\u5229\u7528\u7b49\u5f85\u540d\u5355\u5206\u914d\u4f18\u5148\u7ea7\uff0c\u5e76\u63a7\u5236\u6765\u81ea\u51fa\u751f\u8bb0\u5f55\u548c\u7533\u8bf7\u6570\u636e\u7684\u4e30\u5bcc\u7279\u5f81\u3002\u8fdb\u5165\u90ca\u533a\u5b66\u6821\u53ef\u63d0\u5347\u6570\u5b66\u548c\u82f1\u8bed\u8003\u8bd5\u6210\u7ee9\uff0c\u964d\u4f4e\u8f8d\u5b66\u7387\uff0c\u5e76\u63d0\u9ad8\u6309\u65f6\u5b8c\u6210\u9ad8\u4e2d\u5b66\u4e1a\u7684\u6982\u7387\u3002\u56db\u5e74\u540e\u5927\u5b66\u5fd7\u5411\u3001\u5165\u5b66\u548c\u6bd5\u4e1a\u7387\u5747\u6709\u6240\u4e0a\u5347\uff0c\u6210\u5e74\u540e\u7684\u6536\u5165\u4e5f\u76f8\u5e94\u63d0\u9ad8\u3002\u7236\u6bcd\u672a\u4e0a\u8fc7\u5927\u5b66\u7684\u5b66\u751f\u4ee5\u53ca\u7537\u751f\u53d7\u76ca\u6700\u4e3a\u663e\u8457\u3002\u8bc1\u636e\u8868\u660e\uff0c\u5b58\u5728\u591a\u79cd\u673a\u5236\uff0c\u5305\u62ec\u8fdb\u5165\u66f4\u9ad8\u4ef7\u503c\u52a0\u6743\u7684\u5b66\u6821\u3001\u4e0e\u66f4\u9ad8\u6210\u5c31\u6c34\u5e73\u7684\u540c\u9f84\u4eba\u5171\u5904\uff0c\u4ee5\u53ca\u5b66\u6821\u4e2d\u66f4\u5f3a\u7684\u5927\u5b66\u5347\u5b66\u6587\u5316\u3002\u53c2\u4e0e\u8005\u66f4\u53ef\u80fd\u88ab\u5212\u5165\u8868\u73b0\u8f83\u5dee\u7684\u73ed\u7ea7\uff0c\u8fd9\u610f\u5473\u7740\u82e5\u80fd\u83b7\u5f97\u66f4\u9ad8\u7ea7\u8bfe\u7a0b\uff0c\u5176\u6548\u679c\u53ef\u80fd\u66f4\u5927\u3002\u5b66\u533a\u4ef7\u503c\u52a0\u6743\u4f30\u8ba1\u663e\u793a\uff0c\u5b66\u751f\u4eec\u7684\u6559\u80b2\u8f68\u8ff9\u53d8\u5316\u81f3\u5c11\u76f8\u5f53\u4e8e\u5728\u90ca\u533a\u5b66\u533a\u6210\u957f\u6240\u4ea7\u751f\u7684\u53d8\u5316\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag046", "journal": "QJE", "title": "How Does Wage Inequality Affect the Labor Movement?", "authors": ["Barbara Biasi", "Zo\u00eb Cullen", "Julia Gilman", "Nina Roussille"], "author_details": [{"name": "Barbara Biasi", "affiliations": ["Yale University School of Management and National Bureau of Economic Research ,"]}, {"name": "Zo\u00eb Cullen", "affiliations": ["Harvard Business School and National Bureau of Economic Research ,"]}, {"name": "Julia Gilman", "affiliations": ["Massachusetts Institute of Technology ,"]}, {"name": "Nina Roussille", "affiliations": ["Massachusetts Institute of Technology and National Bureau of Economic Research ,"]}], "abstract": "Abstract This paper provides evidence on how wage inequality among workers affects the labor movement using three complementary research designs: a vignette experiment with union organizers, a natural policy experiment that increased wage inequality among Wisconsin school teachers, and an information intervention during the 2023 Writers Guild of America strike. Across all studies, we find that inequality undermines union strength through multiple channels. First, workers with high individual bargaining power are more likely to withdraw support in unequal environments, preferring individual over collective bargaining. Second, union organizers facing hypothetical choices strategically respond to inequality in ways that may preserve membership but limit redistribution, such as shifting their campaign away from wages and choosing smaller, more homogeneous bargaining units.", "date": "2026-09-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag046", "title_zh": "\u5de5\u8d44\u4e0d\u5e73\u7b49\u5982\u4f55\u5f71\u54cd\u52b3\u5de5\u8fd0\u52a8\uff1f", "abstract_zh": "\u672c\u6587\u901a\u8fc7\u4e09\u79cd\u76f8\u4e92\u8865\u5145\u7684\u7814\u7a76\u8bbe\u8ba1\uff0c\u63d0\u4f9b\u5de5\u4eba\u4e4b\u95f4\u5de5\u8d44\u4e0d\u5e73\u7b49\u5982\u4f55\u5f71\u54cd\u52b3\u5de5\u8fd0\u52a8\u7684\u8bc1\u636e\uff1a\u9762\u5411\u5de5\u4f1a\u7ec4\u7ec7\u8005\u7684\u60c5\u5883\u5b9e\u9a8c\u3001\u4e00\u9879\u63d0\u9ad8\u4e86\u5a01\u65af\u5eb7\u661f\u5dde\u5b66\u6821\u6559\u5e08\u5de5\u8d44\u4e0d\u5e73\u7b49\u7a0b\u5ea6\u7684\u81ea\u7136\u653f\u7b56\u5b9e\u9a8c\uff0c\u4ee5\u53ca 2023 \u5e74\u7f8e\u56fd\u7f16\u5267\u5de5\u4f1a\u7f62\u5de5\u671f\u95f4\u7684\u4e00\u9879\u4fe1\u606f\u5e72\u9884\u3002\u5728\u6240\u6709\u7814\u7a76\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\u4e0d\u5e73\u7b49\u901a\u8fc7\u591a\u79cd\u6e20\u9053\u524a\u5f31\u5de5\u4f1a\u529b\u91cf\u3002\u9996\u5148\uff0c\u4e2a\u4eba\u8bae\u4ef7\u80fd\u529b\u8f83\u5f3a\u7684\u5de5\u4eba\u5728\u4e0d\u5e73\u7b49\u73af\u5883\u4e2d\u66f4\u53ef\u80fd\u64a4\u56de\u652f\u6301\uff0c\u66f4\u503e\u5411\u4e8e\u4e2a\u4eba\u8c08\u5224\u800c\u975e\u96c6\u4f53\u8c08\u5224\u3002\u5176\u6b21\uff0c\u9762\u5bf9\u5047\u8bbe\u6027\u9009\u62e9\u65f6\uff0c\u5de5\u4f1a\u7ec4\u7ec7\u8005\u4f1a\u7b56\u7565\u6027\u5730\u5e94\u5bf9\u4e0d\u5e73\u7b49\uff0c\u91c7\u53d6\u53ef\u80fd\u4fdd\u4f4f\u4f1a\u5458\u89c4\u6a21\u5374\u9650\u5236\u518d\u5206\u914d\u7684\u505a\u6cd5\uff0c\u4f8b\u5982\u628a\u8fd0\u52a8\u91cd\u70b9\u4ece\u5de5\u8d44\u8f6c\u5411\u5176\u4ed6\u8bae\u9898\uff0c\u4ee5\u53ca\u9009\u62e9\u89c4\u6a21\u66f4\u5c0f\u3001\u540c\u8d28\u6027\u66f4\u9ad8\u7684\u8c08\u5224\u5355\u4f4d\u3002", "translation_source": "\u9996\u7248\u6837\u4f8b\uff1a\u7531 Codex \u6839\u636e\u516c\u5f00\u6458\u8981\u7ffb\u8bd1\uff0c\u975e Qwen \u8f93\u51fa", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.03234", "journal": "MS", "title": "The Power of Data: Assessing Primary Care Performance Using Routinely Collected Emergency Department Data", "authors": ["Nicos Savva", "Sandra S\u00fclz", "Mark Kinirons", "Emer Sutherland", "Richard Leach"], "author_details": [{"name": "Nicos Savva", "affiliations": ["Management Science & Operations, London Business School, London NW1 4SA, United Kingdom"]}, {"name": "Sandra S\u00fclz", "affiliations": ["Erasmus School of Health Policy & Management, Erasmus University, 3062 PA Rotterdam, Netherlands"]}, {"name": "Mark Kinirons", "affiliations": ["Guy\u2019s and St. Thomas\u2019 National Health Service Foundation Trust and Kings College London, London SE1 7EH, United Kingdom"]}, {"name": "Emer Sutherland", "affiliations": ["King\u2019s College Hospital, London WC2R 2LS, United Kingdom"]}, {"name": "Richard Leach", "affiliations": ["Guy\u2019s and St. Thomas\u2019 National Health Service Foundation Trust and Kings College London, London SE1 7EH, United Kingdom"]}], "abstract": "This paper develops and validates an approach to assess the impact of individual primary care practices (PCPs) on demand for emergency department (ED) services. Using operational data from two geographically adjacent EDs in England, we focus on attendances for ambulatory care-sensitive (ACS) conditions, which are more appropriately and cost-effectively treated outside the ED. We employ a variance-decomposition approach that controls for observed and unobserved heterogeneity and explicitly accounts for socioeconomic differences. The analysis shows that approximately 52% of the variation in ACS attendance proportions is attributable to systematic differences across PCPs and that these differences are operationally meaningful. Using this methodology, we construct a PCP-level measure of systematic variation in ACS attendances and show that it correlates with patient feedback from National Health Service surveys, Quality and Outcomes Framework scores, and PCP staffing decisions. This measure outperforms existing metrics based on ACS admissions in identifying PCP-level variation and is robust to alternative modeling choices. The modular nature of the approach allows it to be applied to data from one or multiple hospitals, providing policymakers with a practical tool to evaluate PCP-level interventions and their downstream effects on ED demand.", "date": "2026-09-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.03234", "title_zh": "\u6570\u636e\u7684\u529b\u91cf\uff1a\u5229\u7528\u5e38\u89c4\u6536\u96c6\u7684\u6025\u8bca\u79d1\u6570\u636e\u8bc4\u4f30\u521d\u7ea7\u62a4\u7406\u670d\u52a1\u8d28\u91cf", "abstract_zh": "\u672c\u6587\u5f00\u53d1\u5e76\u9a8c\u8bc1\u4e86\u4e00\u79cd\u8bc4\u4f30\u5355\u4e2a\u521d\u7ea7\u62a4\u7406\u5b9e\u8df5\uff08PCP\uff09\u5bf9\u6025\u8bca\u79d1\uff08ED\uff09\u670d\u52a1\u9700\u6c42\u5f71\u54cd\u7684\u65b9\u6cd5\u3002\u57fa\u4e8e\u82f1\u683c\u5170\u4e24\u4e2a\u5730\u7406\u4e0a\u76f8\u90bb\u7684\u6025\u8bca\u79d1\u7684\u8fd0\u8425\u6570\u636e\uff0c\u6211\u4eec\u91cd\u70b9\u5173\u6ce8\u95e8\u8bca\u62a4\u7406\u654f\u611f\uff08ACS\uff09\u72b6\u51b5\u7684\u5c31\u8bca\u60c5\u51b5\uff0c\u8fd9\u4e9b\u72b6\u51b5\u66f4\u9002\u5b9c\u4e14\u6210\u672c\u66f4\u6709\u6548\u5728\u95e8\u8bca\u6cbb\u7597\u3002\u6211\u4eec\u91c7\u7528\u4e00\u79cd\u65b9\u5dee\u5206\u89e3\u65b9\u6cd5\uff0c\u63a7\u5236\u4e86\u5df2\u89c2\u5bdf\u5230\u548c\u672a\u89c2\u5bdf\u5230\u7684\u5f02\u8d28\u6027\uff0c\u5e76\u660e\u786e\u8003\u8651\u4e86\u793e\u4f1a\u7ecf\u6d4e\u5dee\u5f02\u3002\u5206\u6790\u8868\u660e\uff0c\u7ea652%\u7684ACS\u5c31\u8bca\u6bd4\u4f8b\u53d8\u5f02\u53ef\u5f52\u56e0\u4e8e\u4e0d\u540cPCP\u4e4b\u95f4\u7684\u7cfb\u7edf\u6027\u5dee\u5f02\uff0c\u4e14\u8fd9\u4e9b\u5dee\u5f02\u5177\u6709\u5b9e\u9645\u64cd\u4f5c\u610f\u4e49\u3002\u5229\u7528\u8be5\u65b9\u6cd5\uff0c\u6211\u4eec\u6784\u5efa\u4e86PCP\u5c42\u9762\u7684\u7cfb\u7edf\u6027ACS\u5c31\u8bca\u53d8\u5f02\u5ea6\u91cf\uff0c\u5e76\u8bc1\u660e\u5176\u4e0e\u56fd\u5bb6\u536b\u751f\u670d\u52a1\u8c03\u67e5\u4e2d\u7684\u60a3\u8005\u53cd\u9988\u3001\u8d28\u91cf\u4e0e\u6210\u679c\u6846\u67b6\u8bc4\u5206\u4ee5\u53caPCP\u4eba\u5458\u914d\u7f6e\u51b3\u7b56\u76f8\u5173\u3002\u8be5\u5ea6\u91cf\u5728\u8bc6\u522bPCP\u5c42\u9762\u53d8\u5f02\u65b9\u9762\u4f18\u4e8e\u73b0\u6709\u57fa\u4e8eACS\u4f4f\u9662\u6570\u636e\u7684\u6307\u6807\uff0c\u5e76\u5bf9\u66ff\u4ee3\u5efa\u6a21\u9009\u62e9\u5177\u6709\u7a33\u5065\u6027\u3002\u8be5\u65b9\u6cd5\u7684\u6a21\u5757\u5316\u7279\u6027\u4f7f\u5176\u53ef\u5e94\u7528\u4e8e\u5355\u4e2a\u6216\u591a\u4e2a\u533b\u9662\u7684\u6570\u636e\uff0c\u4e3a\u653f\u7b56\u5236\u5b9a\u8005\u63d0\u4f9b\u4e86\u4e00\u79cd\u5b9e\u7528\u5de5\u5177\uff0c\u4ee5\u8bc4\u4f30PCP\u5c42\u9762\u5e72\u9884\u63aa\u65bd\u53ca\u5176\u5bf9\u6025\u8bca\u79d1\u9700\u6c42\u7684\u4e0b\u6e38\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag084", "journal": "RFS", "title": "Universal Portfolio Shrinkage", "authors": ["Bryan Kelly", "Semyon Malamud", "Mo Pourmohammadi", "Fabio Trojani"], "author_details": [{"name": "Bryan Kelly", "affiliations": ["Yale School of Management, AQR Capital Management, and NBER , the"]}, {"name": "Semyon Malamud", "affiliations": ["Swiss Finance Institute and EPFL , Switzerland, and , London", "CEPR , Switzerland, and , London"]}, {"name": "Mo Pourmohammadi", "affiliations": ["Yale School of Management , the"]}, {"name": "Fabio Trojani", "affiliations": ["University of Geneva and Swiss Finance Institute ,"]}], "abstract": "Abstract We introduce a nonlinear covariance shrinkage method for building optimal portfolios. Our universal portfolio shrinkage approximator (UPSA) is built from closed-form basis portfolios, is cheap to implement, and improves on existing shrinkage methods. Rather than uniformly penalizing all principal components of returns or discarding low-variance ones, UPSA instead reweights components to explicitly optimize expected out-of-sample portfolio performance. In empirical applications using a large cross-section of anomaly factors, it delivers robust improvements over alternative shrinkage methods in the literature.", "date": "2026-09-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag084", "title_zh": "\u901a\u7528\u6295\u8d44\u7ec4\u5408\u6536\u7f29\u65b9\u6cd5", "abstract_zh": "\u672c\u6587\u63d0\u51fa\u4e00\u79cd\u7528\u4e8e\u6784\u5efa\u6700\u4f18\u6295\u8d44\u7ec4\u5408\u7684\u975e\u7ebf\u6027\u534f\u65b9\u5dee\u6536\u7f29\u65b9\u6cd5\u3002\u6211\u4eec\u63d0\u51fa\u7684\u901a\u7528\u6295\u8d44\u7ec4\u5408\u6536\u7f29\u8fd1\u4f3c\u5668\uff08UPSA\uff09\u7531\u5177\u6709\u95ed\u5f0f\u89e3\u7684\u57fa\u7840\u6295\u8d44\u7ec4\u5408\u6784\u6210\uff0c\u5b9e\u65bd\u6210\u672c\u4f4e\uff0c\u5e76\u4f18\u4e8e\u73b0\u6709\u6536\u7f29\u65b9\u6cd5\u3002UPSA \u5e76\u975e\u5bf9\u6536\u76ca\u7684\u6240\u6709\u4e3b\u6210\u5206\u65bd\u52a0\u7edf\u4e00\u60e9\u7f5a\uff0c\u4e5f\u4e0d\u662f\u820d\u5f03\u4f4e\u65b9\u5dee\u4e3b\u6210\u5206\uff0c\u800c\u662f\u91cd\u65b0\u8c03\u6574\u5404\u4e3b\u6210\u5206\u7684\u6743\u91cd\uff0c\u4ee5\u76f4\u63a5\u4f18\u5316\u9884\u671f\u6837\u672c\u5916\u6295\u8d44\u7ec4\u5408\u8868\u73b0\u3002\u5728\u4f7f\u7528\u5927\u91cf\u5f02\u8c61\u56e0\u5b50\u6a2a\u622a\u9762\u7684\u5b9e\u8bc1\u5e94\u7528\u4e2d\uff0c\u8be5\u65b9\u6cd5\u76f8\u5bf9\u4e8e\u6587\u732e\u4e2d\u7684\u5176\u4ed6\u6536\u7f29\u65b9\u6cd5\u53d6\u5f97\u4e86\u7a33\u5065\u7684\u6539\u8fdb\u3002", "translation_source": "\u9996\u7248\u6837\u4f8b\uff1a\u7531 Codex \u6839\u636e\u516c\u5f00\u6458\u8981\u7ffb\u8bd1\uff0c\u975e Qwen \u8f93\u51fa", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhag087", "journal": "RFS", "title": "Affordable Housing, Unaffordable Credit? Concentration and High-Cost Lending for Manufactured Homes", "authors": ["Sebastian Doerr", "Andreas Fuster"], "author_details": [{"name": "Sebastian Doerr", "affiliations": ["Bank for International Settlements , Switzerland, and CEPR"]}, {"name": "Andreas Fuster", "affiliations": ["University of Zurich and Swiss Finance Institute , Switzerland, and CEPR"]}], "abstract": "Abstract This paper shows that high market concentration in the U.S. manufactured home loan market allows lenders to charge markedly higher interest rates than in the mortgage market for site-built homes. Borrowers in counties with higher lender concentration face significantly higher rates, and evidence from bunching at a regulatory rate threshold, an instrumental variable analysis, and a difference-in-differences analysis suggests a causal link. Integrated lenders, which play an outsized role in this market, charge particularly high rates, and we provide evidence suggesting that these lenders exploit their market power over borrowers. We discuss factors that may explain limited lender entry.", "date": "2026-09-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag087", "title_zh": "\u53ef\u8d1f\u62c5\u4f4f\u623f\uff0c\u5374\u65e0\u6cd5\u8d1f\u62c5\u7684\u4fe1\u8d37\uff1f\u5236\u9020\u623f\u5c4b\u8d37\u6b3e\u5e02\u573a\u7684\u96c6\u4e2d\u5ea6\u4e0e\u9ad8\u6210\u672c\u8d37\u6b3e", "abstract_zh": "\u672c\u6587\u8868\u660e\uff0c\u7f8e\u56fd\u5236\u9020\u623f\u5c4b\u8d37\u6b3e\u5e02\u573a\u4e2d\u7684\u9ad8\u5e02\u573a\u96c6\u4e2d\u5ea6\u4f7f\u8d37\u6b3e\u673a\u6784\u80fd\u591f\u5bf9\u5236\u9020\u623f\u5c4b\u8d37\u6b3e\u6536\u53d6\u660e\u663e\u9ad8\u4e8e\u5efa\u5740\u623f\u5c4b\u62b5\u62bc\u8d37\u6b3e\u7684\u5229\u7387\u3002\u5728\u8d37\u6b3e\u673a\u6784\u96c6\u4e2d\u5ea6\u8f83\u9ad8\u7684\u53bf\u4efd\uff0c\u501f\u6b3e\u4eba\u9762\u4e34\u663e\u8457\u66f4\u9ad8\u7684\u5229\u7387\uff0c\u57fa\u4e8e\u76d1\u7ba1\u5229\u7387\u9608\u503c\u7684\u96c6\u4e2d\u73b0\u8c61\u3001\u5de5\u5177\u53d8\u91cf\u5206\u6790\u4ee5\u53ca\u5dee\u5f02-in-\u5dee\u5f02\u5206\u6790\u7684\u8bc1\u636e\u8868\u660e\u5b58\u5728\u56e0\u679c\u5173\u7cfb\u3002\u7efc\u5408\u578b\u8d37\u6b3e\u673a\u6784\u5728\u8be5\u5e02\u573a\u4e2d\u5360\u636e\u4e3b\u5bfc\u5730\u4f4d\uff0c\u4e14\u6536\u53d6\u7279\u522b\u9ad8\u7684\u5229\u7387\uff0c\u6211\u4eec\u63d0\u4f9b\u4e86\u8bc1\u636e\u8868\u660e\u8fd9\u4e9b\u673a\u6784\u5229\u7528\u5176\u5e02\u573a\u6743\u529b\u5265\u524a\u501f\u6b3e\u4eba\u3002\u6211\u4eec\u8fd8\u8ba8\u8bba\u4e86\u53ef\u80fd\u5bfc\u81f4\u8d37\u6b3e\u673a\u6784\u8fdb\u5165\u53d7\u9650\u7684\u56e0\u7d20\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag088", "journal": "RFS", "title": "Original Sin Redux: Role of Duration Risk*", "authors": ["Carol Bertaut", "Valentina Bruno", "Hyun Song Shin"], "author_details": [{"name": "Carol Bertaut", "affiliations": ["Federal Reserve Board , the United States"]}, {"name": "Valentina Bruno", "affiliations": ["American University and NBER , the United States, and CEPR"]}, {"name": "Hyun Song Shin", "affiliations": ["Bank for International Settlements , Switzerland"]}], "abstract": "Abstract We highlight the role of duration and exchange rate risks on portfolio flows by using a unique and comprehensive database of U.S. investor flows into emerging market government bonds denominated in local currency. Borrowing long-term mitigates rollover risk but amplifies valuation changes that further interact with currency movements. Our analysis highlights the double-edged nature of long-term borrowing and draws attention to market stress dynamics due to strategic complementarities among mutual fund investors.", "date": "2026-09-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag088", "title_zh": "\u201c\u539f\u7f6a\u201d\u518d\u63a2\uff1a\u4e45\u671f\u98ce\u9669\u7684\u4f5c\u7528", "abstract_zh": "\u672c\u6587\u5229\u7528\u4e00\u4e2a\u72ec\u7279\u4e14\u5168\u9762\u7684\u6570\u636e\u5e93\uff0c\u7814\u7a76\u7f8e\u56fd\u6295\u8d44\u8005\u6d41\u5165\u4ee5\u672c\u5e01\u8ba1\u4ef7\u7684\u65b0\u5174\u5e02\u573a\u653f\u5e9c\u503a\u5238\u7684\u8d44\u91d1\uff0c\u7a81\u51fa\u4e45\u671f\u98ce\u9669\u4e0e\u6c47\u7387\u98ce\u9669\u5bf9\u6295\u8d44\u7ec4\u5408\u8d44\u91d1\u6d41\u52a8\u7684\u4f5c\u7528\u3002\u957f\u671f\u501f\u6b3e\u53ef\u4ee5\u7f13\u89e3\u518d\u878d\u8d44\u98ce\u9669\uff0c\u5374\u4f1a\u653e\u5927\u4f30\u503c\u53d8\u52a8\uff0c\u800c\u4f30\u503c\u53d8\u52a8\u53c8\u4f1a\u4e0e\u6c47\u7387\u6ce2\u52a8\u76f8\u4e92\u4f5c\u7528\u3002\u6211\u4eec\u7684\u5206\u6790\u63ed\u793a\u4e86\u957f\u671f\u501f\u6b3e\u7684\u53cc\u5203\u5251\u6027\u8d28\uff0c\u5e76\u5f3a\u8c03\u5171\u540c\u57fa\u91d1\u6295\u8d44\u8005\u4e4b\u95f4\u7684\u6218\u7565\u4e92\u8865\u6027\u6240\u5f15\u53d1\u7684\u5e02\u573a\u538b\u529b\u52a8\u6001\u3002", "translation_source": "\u9996\u7248\u6837\u4f8b\uff1a\u7531 Codex \u6839\u636e\u516c\u5f00\u6458\u8981\u7ffb\u8bd1\uff0c\u975e Qwen \u8f93\u51fa", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u8d44\u672c\u6d41\u52a8"]}, {"doi": "10.1017/s0022109026103202", "journal": "JFQA", "title": "Political Connections, Financial Constraints, and Corporate Taxation", "authors": ["Ke Na", "Terry Shevlin", "Youan Wang", "Zigan Wang"], "author_details": [{"name": "Ke Na", "affiliations": ["Cheung Kong Graduate School of Business"]}, {"name": "Terry Shevlin", "affiliations": ["University of California Irvine"]}, {"name": "Youan Wang", "affiliations": ["Xiamen University"]}, {"name": "Zigan Wang", "affiliations": ["Zhejiang University Tsinghua University"]}], "abstract": "Abstract We find that the effect of political connections on tax planning depends on firms\u2019 financial conditions. After increased political connections, financially unconstrained firms increase tax planning and spending on tax services, as documented in prior studies, whereas constrained firms decrease tax planning and spending on tax services. Moreover, decreases in tax planning are only present for constrained firms that obtain new bank loans and public debt and when the connected politicians serve on banking-related committees. Our results suggest that by facilitating access to external financing, political connections reduce financially constrained firms\u2019 use of tax planning as an internal financing tool.", "date": "2026-09-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103202", "title_zh": "\u653f\u6cbb\u5173\u8054\u3001\u8d22\u52a1\u7ea6\u675f\u4e0e\u4f01\u4e1a\u7a0e\u52a1\u7b79\u5212", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u653f\u6cbb\u5173\u8054\u5bf9\u4f01\u4e1a\u7a0e\u52a1\u7b79\u5212\u7684\u5f71\u54cd\u53d6\u51b3\u4e8e\u4f01\u4e1a\u7684\u8d22\u52a1\u72b6\u51b5\u3002\u5728\u653f\u6cbb\u5173\u8054\u589e\u5f3a\u540e\uff0c\u8d22\u52a1\u4e0d\u53d7\u9650\u5236\u7684\u4f01\u4e1a\u4f1a\u589e\u52a0\u7a0e\u52a1\u7b79\u5212\u548c\u7a0e\u52a1\u670d\u52a1\u652f\u51fa\uff0c\u8fd9\u4e0e\u4ee5\u5f80\u7814\u7a76\u4e2d\u7684\u53d1\u73b0\u4e00\u81f4\uff1b\u800c\u8d22\u52a1\u53d7\u9650\u7684\u4f01\u4e1a\u5219\u4f1a\u51cf\u5c11\u7a0e\u52a1\u7b79\u5212\u548c\u7a0e\u52a1\u670d\u52a1\u652f\u51fa\u3002\u6b64\u5916\uff0c\u53ea\u6709\u5728\u8d22\u52a1\u53d7\u9650\u4f01\u4e1a\u83b7\u5f97\u65b0\u7684\u94f6\u884c\u8d37\u6b3e\u548c\u516c\u5171\u503a\u52a1\uff0c\u5e76\u4e14\u76f8\u5173\u653f\u5ba2\u62c5\u4efb\u94f6\u884c\u4e1a\u76f8\u5173\u59d4\u5458\u4f1a\u6210\u5458\u65f6\uff0c\u624d\u4f1a\u51fa\u73b0\u7a0e\u52a1\u7b79\u5212\u7684\u51cf\u5c11\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u653f\u6cbb\u5173\u8054\u901a\u8fc7\u4fc3\u8fdb\u4f01\u4e1a\u83b7\u53d6\u5916\u90e8\u878d\u8d44\uff0c\u51cf\u5c11\u4e86\u8d22\u52a1\u53d7\u9650\u4f01\u4e1a\u5c06\u7a0e\u52a1\u7b79\u5212\u4f5c\u4e3a\u5185\u90e8\u878d\u8d44\u624b\u6bb5\u7684\u4f7f\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026103317", "journal": "JFQA", "title": "Connected Social Media", "authors": ["Zhiqian Jiang", "Baixiao Liu", "Yuchen Xu", "Bohui Zhang"], "author_details": [{"name": "Zhiqian Jiang", "affiliations": ["Xiamen University School of Management"]}, {"name": "Baixiao Liu", "affiliations": ["Peking University HSBC Business School"]}, {"name": "Yuchen Xu", "affiliations": ["University of New South Wales UNSW Business School"]}, {"name": "Bohui Zhang", "affiliations": ["The Chinese University of Hong Kong, Shenzhen (CUHK-Shenzhen), School of Management and Economics and Shenzhen Finance Institute"]}], "abstract": "Abstract We examine whether and how firms use connected social media outlets to counteract negative coverage in traditional media. Employing a sample of Chinese listed firms with ties to social media outlets, we find that connected outlets portray firms more favorably than unconnected ones. Following unfavorable coverage in traditional media, connected outlets shift attention toward long-term prospects and promote favorable narratives, consistent with an optimism-shifting mechanism. The effect is more pronounced when firms have stronger incentives to stabilize stock prices and when managers face heightened career concerns. Our findings highlight the role of connected social media outlets in shaping corporate narratives.", "date": "2026-09-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103317", "title_zh": "\u8fde\u63a5\u578b\u793e\u4ea4\u5a92\u4f53", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4f01\u4e1a\u662f\u5426\u4ee5\u53ca\u5982\u4f55\u5229\u7528\u8fde\u63a5\u578b\u793e\u4ea4\u5a92\u4f53\u5e73\u53f0\u6765\u5e94\u5bf9\u4f20\u7edf\u5a92\u4f53\u7684\u8d1f\u9762\u62a5\u9053\u3002\u57fa\u4e8e\u4e0e\u4e2d\u56fd\u4e0a\u5e02\u516c\u53f8\u5728\u793e\u4ea4\u5a92\u4f53\u5e73\u53f0\u6709\u8054\u7cfb\u7684\u6837\u672c\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u4e0e\u672a\u8fde\u63a5\u5e73\u53f0\u76f8\u6bd4\uff0c\u8fde\u63a5\u578b\u5e73\u53f0\u5bf9\u4f01\u4e1a\u5f62\u8c61\u7684\u63cf\u8ff0\u66f4\u4e3a\u79ef\u6781\u3002\u5728\u4f20\u7edf\u5a92\u4f53\u51fa\u73b0\u8d1f\u9762\u62a5\u9053\u540e\uff0c\u8fde\u63a5\u578b\u5e73\u53f0\u4f1a\u5c06\u5173\u6ce8\u70b9\u8f6c\u5411\u4f01\u4e1a\u7684\u957f\u671f\u524d\u666f\uff0c\u5e76\u4f20\u64ad\u79ef\u6781\u7684\u53d9\u4e8b\uff0c\u8fd9\u4e0e\u4e50\u89c2\u60c5\u7eea\u8f6c\u79fb\u673a\u5236\u4e00\u81f4\u3002\u5f53\u4f01\u4e1a\u6709\u66f4\u5f3a\u7684\u7a33\u5b9a\u80a1\u4ef7\u52a8\u673a\uff0c\u6216\u7ba1\u7406\u5c42\u9762\u4e34\u66f4\u4e25\u91cd\u7684\u804c\u4e1a\u98ce\u9669\u65f6\uff0c\u8be5\u6548\u5e94\u66f4\u4e3a\u663e\u8457\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u51f8\u663e\u4e86\u8fde\u63a5\u578b\u793e\u4ea4\u5a92\u4f53\u5e73\u53f0\u5728\u5851\u9020\u4f01\u4e1a\u53d9\u4e8b\u4e2d\u7684\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2025.02458", "journal": "MS", "title": "Generative Search: Evidence from a Large-Scale Field Experiment", "authors": ["Shuang Zheng", "Yuting Zhu", "Xin Ye", "Liang Shen"], "author_details": [{"name": "Shuang Zheng", "affiliations": ["School of Business, Renmin University of China, Beijing 100086, China; and DUT School of Economics and Management, Dalian University of Technology, Dalian City 116024, China; and Meituan, Beijing 100102, China"]}, {"name": "Yuting Zhu", "affiliations": ["NUS Business School, National University of Singapore, Singapore 119245"]}, {"name": "Xin Ye", "affiliations": ["DUT School of Economics and Management, Dalian University of Technology, Dalian City 116024, China"]}, {"name": "Liang Shen", "affiliations": ["Meituan, Beijing 100102, China"]}], "abstract": "Generative search is an emerging search paradigm that integrates Generative AI (GenAI) into traditional search engines by presenting users with AI-generated responses before conventional search results. Whereas keyword-based search requires consumers to translate their underlying needs into effective keyword queries, generative search lets users express those intentions directly in natural language, a shift made possible by GenAI\u2019s new mode of information presentation. This shift moves the consumer-search engine interaction upstream to the stage of problem formulation, rendering empirically observable a previously hidden phase of search behavior: the mapping from problem formulation to keyword articulation. Yet, it remains empirically unknown whether generative search increases consumer purchases and how search behavior changes when it can begin from expressed intent rather than keywords. Using a large-scale field experiment conducted on Meituan, a leading Chinese technology platform, this paper provides empirical evidence on the effectiveness of generative search. We find that generative search significantly increases consumer purchases. Further analysis reveals that generative search facilitates more effective and diverse keyword queries and reduces exploratory browsing and clicking, while concentrating evaluation within relevant categories and merchants. The empirical evidence is most consistent with a mechanism in which AI-generated answers provide information about consumers\u2019 underlying needs, while also expanding awareness of relevant attributes and shifting attention toward more relevant categories. These findings provide empirical insights for future consumer search models that allow search to originate at the intention-expressing stage.", "date": "2026-09-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.02458", "title_zh": "\u751f\u6210\u5f0f\u641c\u7d22\uff1a\u6765\u81ea\u5927\u89c4\u6a21\u5b9e\u5730\u5b9e\u9a8c\u7684\u8bc1\u636e", "abstract_zh": "\u751f\u6210\u5f0f\u641c\u7d22\u662f\u4e00\u79cd\u65b0\u5174\u7684\u641c\u7d22\u8303\u5f0f\uff0c\u5b83\u901a\u8fc7\u5728\u4f20\u7edf\u641c\u7d22\u5f15\u64ce\u4e2d\u5f15\u5165\u751f\u6210\u5f0f\u4eba\u5de5\u667a\u80fd\uff08GenAI\uff09\uff0c\u5411\u7528\u6237\u5c55\u793aAI\u751f\u6210\u7684\u54cd\u5e94\uff0c\u800c\u975e\u4f20\u7edf\u7684\u641c\u7d22\u7ed3\u679c\u3002\u4e0e\u57fa\u4e8e\u5173\u952e\u8bcd\u7684\u641c\u7d22\u8981\u6c42\u6d88\u8d39\u8005\u5c06\u81ea\u8eab\u9700\u6c42\u8f6c\u5316\u4e3a\u6709\u6548\u7684\u5173\u952e\u8bcd\u67e5\u8be2\u4e0d\u540c\uff0c\u751f\u6210\u5f0f\u641c\u7d22\u5141\u8bb8\u7528\u6237\u76f4\u63a5\u7528\u81ea\u7136\u8bed\u8a00\u8868\u8fbe\u5176\u610f\u56fe\uff0c\u8fd9\u4e00\u8f6c\u53d8\u5f97\u76ca\u4e8eGenAI\u5728\u4fe1\u606f\u5448\u73b0\u65b9\u5f0f\u4e0a\u7684\u65b0\u80fd\u529b\u3002\u8fd9\u79cd\u8f6c\u53d8\u5c06\u6d88\u8d39\u8005\u4e0e\u641c\u7d22\u5f15\u64ce\u7684\u4e92\u52a8\u63d0\u524d\u5230\u95ee\u9898\u6784\u5efa\u9636\u6bb5\uff0c\u4ece\u800c\u4f7f\u5f97\u539f\u672c\u9690\u85cf\u7684\u641c\u7d22\u884c\u4e3a\u9636\u6bb5\u2014\u2014\u4ece\u95ee\u9898\u6784\u5efa\u5230\u5173\u952e\u8bcd\u8868\u8ff0\u7684\u6620\u5c04\u2014\u2014\u53d8\u5f97\u53ef\u89c2\u5bdf\u3002\u7136\u800c\uff0c\u751f\u6210\u5f0f\u641c\u7d22\u662f\u5426\u80fd\u63d0\u5347\u6d88\u8d39\u8005\u8d2d\u4e70\u884c\u4e3a\uff0c\u4ee5\u53ca\u5f53\u641c\u7d22\u53ef\u4ee5\u59cb\u4e8e\u8868\u8fbe\u610f\u56fe\u800c\u975e\u5173\u952e\u8bcd\u65f6\uff0c\u641c\u7d22\u884c\u4e3a\u5982\u4f55\u53d8\u5316\uff0c\u4ecd\u7f3a\u4e4f\u5b9e\u8bc1\u8bc1\u636e\u3002\u672c\u8bba\u6587\u57fa\u4e8e\u5728\u4e2d\u56fd\u9886\u5148\u7684\u79d1\u6280\u5e73\u53f0\u7f8e\u56e2\u4e0a\u8fdb\u884c\u7684\u4e00\u9879\u5927\u89c4\u6a21\u5b9e\u5730\u5b9e\u9a8c\uff0c\u63d0\u4f9b\u4e86\u751f\u6210\u5f0f\u641c\u7d22\u6709\u6548\u6027\u7684\u5b9e\u8bc1\u8bc1\u636e\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u751f\u6210\u5f0f\u641c\u7d22\u663e\u8457\u63d0\u5347\u4e86\u6d88\u8d39\u8005\u7684\u8d2d\u4e70\u884c\u4e3a\u3002\u8fdb\u4e00\u6b65\u5206\u6790\u8868\u660e\uff0c\u751f\u6210\u5f0f\u641c\u7d22\u4fc3\u8fdb\u4e86\u66f4\u6709\u6548\u548c\u591a\u6837\u5316\u7684\u5173\u952e\u8bcd\u67e5\u8be2\uff0c\u51cf\u5c11\u4e86\u63a2\u7d22\u6027\u6d4f\u89c8\u548c\u70b9\u51fb\u884c\u4e3a\uff0c\u540c\u65f6\u5c06\u8bc4\u4f30\u96c6\u4e2d\u4e8e\u76f8\u5173\u7c7b\u522b\u548c\u5546\u5bb6\u3002\u5b9e\u8bc1\u7ed3\u679c\u6700\u7b26\u5408\u4ee5\u4e0b\u673a\u5236\uff1aAI\u751f\u6210\u7684\u7b54\u6848\u4e0d\u4ec5\u63ed\u793a\u4e86\u6d88\u8d39\u8005\u6f5c\u5728\u7684\u9700\u6c42\uff0c\u8fd8\u6269\u5927\u4e86\u5bf9\u76f8\u5173\u5c5e\u6027\u7684\u8ba4\u77e5\uff0c\u5e76\u5c06\u6ce8\u610f\u529b\u5f15\u5bfc\u81f3\u66f4\u76f8\u5173\u7684\u7c7b\u522b\u3002\u8fd9\u4e9b\u53d1\u73b0\u4e3a\u672a\u6765\u5141\u8bb8\u641c\u7d22\u4ece\u8868\u8fbe\u610f\u56fe\u9636\u6bb5\u5f00\u59cb\u7684\u6d88\u8d39\u8005\u641c\u7d22\u6a21\u578b\u63d0\u4f9b\u4e86\u5b9e\u8bc1\u542f\u793a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790", "AI"]}, {"doi": "10.1287/mnsc.2025.01449", "journal": "MS", "title": "Superstition Everywhere", "authors": ["Jeffery (Jinfan) Chang", "Huancheng Du"], "author_details": [{"name": "Jeffery (Jinfan) Chang", "affiliations": ["School of Management and Economics, The Chinese University of Hong Kong, Shenzhen, Shenzhen, Guangdong Province 518172, People\u2019s Republic of China"]}, {"name": "Huancheng Du", "affiliations": ["School of Finance, Central University of Finance and Economics, Beijing 102206, People\u2019s Republic of China"]}], "abstract": "In Chinese culture, the digit 8 is considered lucky and the digit 4 unlucky. We find that this numerological superstition has a significant impact across China\u2019s stock, bond, foreign exchange, and commodity futures markets, affecting asset prices in both the primary and secondary markets. The superstition effect, that is, asset prices ending in a lucky (unlucky) digit are far more (less) frequent than expected by chance, is prevalent across finance markets. We show that this phenomenon is driven by two mechanisms: sophisticated investors\u2019 reliance on superstition as an anchor to manage ambiguity, and the overoptimism of unsophisticated investors. While the superstition effect does not lead to any systematic mispricing for assets traded primarily by sophisticated investors, it is closely associated with overpricing for assets heavily traded by unsophisticated investors.", "date": "2026-09-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.01449", "title_zh": "\u8ff7\u4fe1\u65e0\u5904\u4e0d\u5728", "abstract_zh": "\u5728\u4e2d\u56fd\u6587\u5316\u4e2d\uff0c\u6570\u5b578\u88ab\u89c6\u4e3a\u5409\u5229\uff0c\u800c\u6570\u5b574\u5219\u88ab\u89c6\u4e3a\u4e0d\u5409\u5229\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u79cd\u6570\u5b57\u8ff7\u4fe1\u5728\u8986\u76d6\u4e2d\u56fd\u80a1\u7968\u3001\u503a\u5238\u3001\u5916\u6c47\u4ee5\u53ca\u5546\u54c1\u671f\u8d27\u5e02\u573a\u7684\u8d44\u4ea7\u4ef7\u683c\u4e2d\u4ea7\u751f\u4e86\u663e\u8457\u5f71\u54cd\uff0c\u8fd9\u79cd\u5f71\u54cd\u8d2f\u7a7f\u4e8e\u4e00\u7ea7\u5e02\u573a\u548c\u4e8c\u7ea7\u5e02\u573a\u3002\u8ff7\u4fe1\u6548\u5e94\uff0c\u5373\u4ee5\u5409\u5229\uff08\u4e0d\u5409\u5229\uff09\u6570\u5b57\u7ed3\u5c3e\u7684\u8d44\u4ea7\u4ef7\u683c\u51fa\u73b0\u9891\u7387\u8fdc\u9ad8\u4e8e\u968f\u673a\u9884\u671f\uff0c\u5e7f\u6cdb\u5b58\u5728\u4e8e\u5404\u7c7b\u91d1\u878d\u5e02\u573a\u4e2d\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u8fd9\u4e00\u73b0\u8c61\u7531\u4e24\u79cd\u673a\u5236\u9a71\u52a8\uff1a\u7cbe\u660e\u6295\u8d44\u8005\u5229\u7528\u8ff7\u4fe1\u4f5c\u4e3a\u951a\u70b9\u6765\u5e94\u5bf9\u4e0d\u786e\u5b9a\u6027\uff0c\u4ee5\u53ca\u975e\u7cbe\u660e\u6295\u8d44\u8005\u7684\u8fc7\u5ea6\u4e50\u89c2\u3002\u5c3d\u7ba1\u8ff7\u4fe1\u6548\u5e94\u5e76\u672a\u5bfc\u81f4\u4e3b\u8981\u7531\u7cbe\u660e\u6295\u8d44\u8005\u4ea4\u6613\u7684\u8d44\u4ea7\u51fa\u73b0\u7cfb\u7edf\u6027\u5b9a\u4ef7\u9519\u8bef\uff0c\u4f46\u5b83\u4e0e\u5927\u91cf\u7531\u975e\u7cbe\u660e\u6295\u8d44\u8005\u4ea4\u6613\u7684\u8d44\u4ea7\u51fa\u73b0\u9ad8\u4f30\u5bc6\u5207\u76f8\u5173\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag109", "journal": "REStud", "title": "Markup Estimation Using Production and Demand Data: An Application to the U.S. Brewing Industry", "authors": ["Jan De Loecker", "Paul T Scott"], "author_details": [{"name": "Jan De Loecker", "affiliations": ["KU Leuven , and , UK", "CEPR , and , UK"]}, {"name": "Paul T Scott", "affiliations": ["MIT , USA"]}], "abstract": "Abstract We compare and combine two distinct approaches to estimating market power in the U.S. brewing industry\u2014one based on production data, the other on demand. Both methods produce similar estimates of average markups and reveal a recent upward trend. We then combine the two approaches in two ways. First, we replace conventional instruments in demand estimation with a moment involving a production-based markup estimate, yielding similar results. We then evaluate the common (but controversial) assumption that retail markets operate competitively, finding that demand-based markups recovered with the assumption of competitive retail markets align with production-based estimates, as long as downstream costs are accounted for.", "date": "2026-09-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag109", "title_zh": "\u4f7f\u7528\u751f\u4ea7\u4e0e\u9700\u6c42\u6570\u636e\u4f30\u7b97 markup\uff1a\u5bf9\u7f8e\u56fd\u5564\u9152\u884c\u4e1a\u7684\u5e94\u7528", "abstract_zh": "\u6211\u4eec\u6bd4\u8f83\u5e76\u7ed3\u5408\u4e86\u4e24\u79cd\u4e0d\u540c\u7684\u65b9\u6cd5\u6765\u4f30\u7b97\u7f8e\u56fd\u5564\u9152\u884c\u4e1a\u4e2d\u7684\u5e02\u573a\u529b\u91cf\u2014\u2014\u4e00\u79cd\u57fa\u4e8e\u751f\u4ea7\u6570\u636e\uff0c\u53e6\u4e00\u79cd\u57fa\u4e8e\u9700\u6c42\u6570\u636e\u3002\u4e24\u79cd\u65b9\u6cd5\u5747\u5f97\u5230\u4e86\u76f8\u4f3c\u7684\u5e73\u5747 markup \u4f30\u8ba1\u503c\uff0c\u5e76\u663e\u793a\u51fa\u8fd1\u671f\u4e0a\u5347\u7684\u8d8b\u52bf\u3002\u6211\u4eec\u4ee5\u4e24\u79cd\u65b9\u5f0f\u7ed3\u5408\u8fd9\u4e24\u79cd\u65b9\u6cd5\u3002\u9996\u5148\uff0c\u6211\u4eec\u5c06\u9700\u6c42\u4f30\u8ba1\u4e2d\u7684\u4f20\u7edf\u5de5\u5177\u66ff\u6362\u4e3a\u4e00\u4e2a\u5305\u542b\u57fa\u4e8e\u751f\u4ea7\u6570\u636e\u7684 markup \u4f30\u8ba1\u7684\u77e9\uff0c\u7ed3\u679c\u7c7b\u4f3c\u3002\u7136\u540e\u6211\u4eec\u8bc4\u4f30\u4e86\u4e00\u4e2a\u666e\u904d\u4f46\u6709\u4e89\u8bae\u7684\u5047\u8bbe\uff0c\u5373\u96f6\u552e\u5e02\u573a\u662f\u7ade\u4e89\u6027\u7684\uff0c\u53d1\u73b0\u53ea\u8981\u8003\u8651\u4e0b\u6e38\u6210\u672c\uff0c\u57fa\u4e8e\u9700\u6c42\u6570\u636e\u7684 markup \u5728\u5047\u8bbe\u96f6\u552e\u5e02\u573a\u4e3a\u7ade\u4e89\u6027\u5e02\u573a\u7684\u60c5\u51b5\u4e0b\uff0c\u4e0e\u57fa\u4e8e\u751f\u4ea7\u6570\u636e\u7684\u4f30\u8ba1\u503c\u76f8\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70081", "journal": "JF", "title": "Justice Good as Random?", "authors": ["NIKLAS H\u00dcTHER", "KRISTOPH KLEINER"], "author_details": [{"name": "NIKLAS H\u00dcTHER", "affiliations": []}, {"name": "KRISTOPH KLEINER", "affiliations": []}], "abstract": "ABSTRACT The random assignment of judges promotes fairness and underpins causal identification across the social sciences. Analyzing Chapter 11 bankruptcies, we find sophisticated parties \u201cjudge\u2010shop\u201d: relative to secured hedge fund creditors, cases involving unsecured hedge fund creditors and equity holders are assigned judges with lower past conversion rates and higher unsecured recovery rates. Experienced legal counsel similarly influences assignment. Because judges are not assigned consecutive large cases, knowledgeable parties can judge\u2010shop by timing the filing date. We develop a method to measure the resulting bias and demonstrate the need for controls and bounded instrumental variable specifications in judge/examiner designs.", "date": "2026-09-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70081", "title_zh": "\u53f8\u6cd5\u5206\u914d\u771f\u5982\u968f\u673a\u5417\uff1f", "abstract_zh": "\u6cd5\u5b98\u7684\u968f\u673a\u5206\u914d\u6709\u52a9\u4e8e\u516c\u5e73\uff0c\u4e5f\u662f\u793e\u4f1a\u79d1\u5b66\u56e0\u679c\u8bc6\u522b\u7684\u91cd\u8981\u57fa\u7840\u3002\u5206\u6790\u7f8e\u56fd\u300a\u7834\u4ea7\u6cd5\u300b\u7b2c 11 \u7ae0\u7834\u4ea7\u6848\u4ef6\u540e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u7ecf\u9a8c\u4e30\u5bcc\u7684\u5f53\u4e8b\u65b9\u4f1a\u201c\u6311\u9009\u6cd5\u5b98\u201d\uff1a\u76f8\u8f83\u4e8e\u6d89\u53ca\u6709\u62c5\u4fdd\u5bf9\u51b2\u57fa\u91d1\u503a\u6743\u4eba\u7684\u6848\u4ef6\uff0c\u6d89\u53ca\u65e0\u62c5\u4fdd\u5bf9\u51b2\u57fa\u91d1\u503a\u6743\u4eba\u548c\u80a1\u6743\u6301\u6709\u4eba\u7684\u6848\u4ef6\uff0c\u88ab\u5206\u914d\u5230\u7684\u6cd5\u5b98\u8fc7\u53bb\u7684\u8f6c\u6e05\u7b97\u7387\u66f4\u4f4e\u3001\u65e0\u62c5\u4fdd\u503a\u6743\u56de\u6536\u7387\u66f4\u9ad8\u3002\u7ecf\u9a8c\u4e30\u5bcc\u7684\u6cd5\u5f8b\u987e\u95ee\u4e5f\u4f1a\u5f71\u54cd\u5206\u914d\u3002\u7531\u4e8e\u6cd5\u5b98\u4e0d\u4f1a\u8fde\u7eed\u63a5\u624b\u5927\u578b\u6848\u4ef6\uff0c\u638c\u63e1\u76f8\u5173\u4fe1\u606f\u7684\u5f53\u4e8b\u65b9\u53ef\u4ee5\u901a\u8fc7\u9009\u62e9\u7533\u8bf7\u65e5\u671f\u6765\u6311\u9009\u6cd5\u5b98\u3002\u6211\u4eec\u63d0\u51fa\u4e00\u79cd\u65b9\u6cd5\u6765\u8861\u91cf\u7531\u6b64\u4ea7\u751f\u7684\u504f\u8bef\uff0c\u5e76\u8bf4\u660e\u5728\u6cd5\u5b98\uff0f\u5ba1\u67e5\u5458\u7814\u7a76\u8bbe\u8ba1\u4e2d\uff0c\u6709\u5fc5\u8981\u52a0\u5165\u63a7\u5236\u53d8\u91cf\u5e76\u91c7\u7528\u6709\u754c\u5de5\u5177\u53d8\u91cf\u8bbe\u5b9a\u3002", "translation_source": "\u9996\u7248\u6837\u4f8b\uff1a\u7531 Codex \u6839\u636e\u516c\u5f00\u6458\u8981\u7ffb\u8bd1\uff0c\u975e Qwen \u8f93\u51fa", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1287/mnsc.2024.06050", "journal": "MS", "title": "Social Networks as Information Conduits for Online Credit Supply and Demand", "authors": ["Linda Allen", "Lin Peng", "Yu Shan"], "author_details": [{"name": "Linda Allen", "affiliations": ["Zicklin School of Business, Baruch College/CUNY, New York, New York 10010"]}, {"name": "Lin Peng", "affiliations": ["Zicklin School of Business, Baruch College/CUNY, New York, New York 10010"]}, {"name": "Yu Shan", "affiliations": ["Whitman School of Management, Syracuse University, Syracuse, New York 13244"]}], "abstract": "We study how intercommunity social networks influence loan demand and supply on fintech lending platforms. Demand for online loans rises following increases in online borrowing activity in geographically distant but socially connected areas. On the supply side, borrower area social proximity to deposit-rich regions increases funding likelihood and is associated with better ex post loan performance. We establish causality with shift-share instrumental variables (SSIVs) obtained from natural disasters (demand side) and financial adviser misconduct (supply side). Social connectedness expands both loan demand and supply in disadvantaged communities without increasing delinquency rates. Intercommunity social networks raise awareness of alternative lending platforms and transmit hard-to-obtain information that mitigates community-level information asymmetry.", "date": "2026-09-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06050", "title_zh": "\u793e\u4ea4\u7f51\u7edc\u4f5c\u4e3a\u5728\u7ebf\u4fe1\u8d37\u4f9b\u9700\u7684\u4fe1\u606f\u901a\u9053", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u8de8\u793e\u533a\u793e\u4ea4\u7f51\u7edc\u5982\u4f55\u5f71\u54cd\u91d1\u878d\u79d1\u6280\u501f\u8d37\u5e73\u53f0\u4e0a\u7684\u8d37\u6b3e\u9700\u6c42\u548c\u4f9b\u7ed9\u3002\u5728\u5730\u7406\u4e0a\u76f8\u8ddd\u4f46\u793e\u4f1a\u5173\u8054\u7d27\u5bc6\u7684\u5730\u533a\uff0c\u7ebf\u4e0a\u501f\u8d37\u6d3b\u52a8\u7684\u589e\u52a0\u4f1a\u63a8\u52a8\u5728\u7ebf\u8d37\u6b3e\u9700\u6c42\u4e0a\u5347\u3002\u5728\u4f9b\u7ed9\u65b9\u9762\uff0c\u501f\u6b3e\u4eba\u6240\u5728\u533a\u57df\u4e0e\u5b58\u6b3e\u4e30\u5bcc\u7684\u5730\u533a\u5728\u793e\u4f1a\u4e0a\u7684\u63a5\u8fd1\u6027\u4f1a\u63d0\u9ad8\u878d\u8d44\u7684\u53ef\u80fd\u6027\uff0c\u5e76\u4e0e\u8d37\u6b3e\u540e\u7684\u826f\u597d\u8868\u73b0\u76f8\u5173\u8054\u3002\u6211\u4eec\u901a\u8fc7\u5229\u7528\u81ea\u7136\u707e\u5bb3\uff08\u9700\u6c42\u4fa7\uff09\u548c\u91d1\u878d\u987e\u95ee\u4e0d\u5f53\u884c\u4e3a\uff08\u4f9b\u7ed9\u4fa7\uff09\u83b7\u5f97\u7684\u79fb\u4f4d\u4efd\u989d\u5de5\u5177\u53d8\u91cf\uff08SSIVs\uff09\u5efa\u7acb\u4e86\u56e0\u679c\u5173\u7cfb\u3002\u793e\u4ea4\u8fde\u63a5\u6027\u5728\u5f31\u52bf\u793e\u533a\u4e2d\u540c\u65f6\u6269\u5927\u4e86\u8d37\u6b3e\u9700\u6c42\u548c\u4f9b\u7ed9\uff0c\u4e14\u5e76\u672a\u589e\u52a0\u8fdd\u7ea6\u7387\u3002\u8de8\u793e\u533a\u7684\u793e\u4ea4\u7f51\u7edc\u63d0\u9ad8\u4e86\u5bf9\u66ff\u4ee3\u6027\u501f\u8d37\u5e73\u53f0\u7684\u8ba4\u77e5\uff0c\u5e76\u4f20\u9012\u4e86\u96be\u4ee5\u83b7\u53d6\u7684\u4fe1\u606f\uff0c\u4ece\u800c\u7f13\u89e3\u4e86\u793e\u533a\u5c42\u9762\u7684\u4fe1\u606f\u4e0d\u5bf9\u79f0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/qje/qjag045", "journal": "QJE", "title": "Bringing Work Home: Flexible Work Arrangements as Gateway Jobs for Women in West Bengal", "authors": ["Lisa Ho", "Suhani Jalota", "Anahita Karandikar"], "author_details": [{"name": "Lisa Ho", "affiliations": ["Columbia University ,"]}, {"name": "Suhani Jalota", "affiliations": ["Stanford University ,"]}, {"name": "Anahita Karandikar", "affiliations": ["University of British Columbia , Canada"]}], "abstract": "Abstract There is a large latent workforce in developing countries that consists of hundreds of millions of women who prefer to have paid work and yet are out of the labor force. Often, available job opportunities are incompatible with traditional gender roles that encourage women to stay at home. In a randomized experiment with 1,670 households, we partner with a jobs platform to offer short-term data work to women who are out of the labor force. We find three main results. First, flexible work-from-home jobs are highly effective at bringing women into paid work. Job flexibility more than triples take-up from 15% for an office job to 48% for a job that women can do from home while multitasking with childcare. Second, these jobs can act as a stepping stone to less flexible work. Trying paid work from home increases take-up of less flexible jobs two to three months later among women without previous work experience. \u201cGateway jobs\u201d are especially important for women from more traditional households: their labor supply is more likely to be marginal to flexibility, and in turn, work experience shifts their attitudes to become less traditional. Third, from the labor demand side, remote work comes with trade-offs in worker performance. Working from the office increases accuracy by 3% and speed by 18%. However, these performance drawbacks of work-from-home arrangements may be outweighed by the increase in available workers.", "date": "2026-09-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag045", "title_zh": "\u628a\u5de5\u4f5c\u5e26\u56de\u5bb6\uff1a\u7075\u6d3b\u5de5\u4f5c\u5b89\u6392\u4f5c\u4e3a\u897f\u5b5f\u52a0\u62c9\u5973\u6027\u8fdb\u5165\u52b3\u52a8\u529b\u5e02\u573a\u7684\u5165\u95e8\u5c97\u4f4d", "abstract_zh": "\u6458\u8981 \u53d1\u5c55\u4e2d\u56fd\u5bb6\u5b58\u5728\u4e00\u4e2a\u5e9e\u5927\u7684\u6f5c\u5728\u52b3\u52a8\u529b\u7fa4\u4f53\uff0c\u5176\u4e2d\u6570\u767e\u4e07\u4eba\u662f\u5973\u6027\uff0c\u5979\u4eec\u5e0c\u671b\u83b7\u5f97\u6709\u85aa\u5de5\u4f5c\uff0c\u5374\u4ecd\u5904\u4e8e\u52b3\u52a8\u529b\u4e4b\u5916\u3002\u901a\u5e38\uff0c\u73b0\u6709\u7684\u5de5\u4f5c\u673a\u4f1a\u4e0e\u4f20\u7edf\u6027\u522b\u89d2\u8272\u76f8\u51b2\u7a81\uff0c\u8fd9\u4e9b\u89d2\u8272\u9f13\u52b1\u5973\u6027\u7559\u5728\u5bb6\u4e2d\u3002\u5728\u4e00\u9879\u9488\u5bf91670\u4e2a\u5bb6\u5ead\u7684\u968f\u673a\u5b9e\u9a8c\u4e2d\uff0c\u6211\u4eec\u4e0e\u4e00\u4e2a\u5c31\u4e1a\u5e73\u53f0\u5408\u4f5c\uff0c\u4e3a\u5904\u4e8e\u52b3\u52a8\u529b\u4e4b\u5916\u7684\u5973\u6027\u63d0\u4f9b\u77ed\u671f\u6570\u636e\u5de5\u4f5c\u3002\u6211\u4eec\u5f97\u5230\u4e09\u4e2a\u4e3b\u8981\u7ed3\u679c\u3002\u7b2c\u4e00\uff0c\u7075\u6d3b\u7684\u5c45\u5bb6\u5de5\u4f5c\u804c\u4f4d\u975e\u5e38\u6709\u6548\uff0c\u80fd\u591f\u4fc3\u4f7f\u5973\u6027\u8fdb\u5165\u6709\u85aa\u5de5\u4f5c\u3002\u4e0e\u9700\u8981\u5230\u529e\u516c\u5ba4\u4e0a\u73ed\u7684\u5de5\u4f5c\u76f8\u6bd4\uff0c\u5c45\u5bb6\u53ef\u540c\u65f6\u517c\u987e\u80b2\u513f\u7684\u7075\u6d3b\u5de5\u4f5c\u804c\u4f4d\u7684\u53c2\u4e0e\u7387\u8d85\u8fc7\u4e09\u500d\uff0c\u4ece15%\u63d0\u5347\u81f348%\u3002\u7b2c\u4e8c\uff0c\u8fd9\u4e9b\u5de5\u4f5c\u53ef\u4ee5\u4f5c\u4e3a\u8fdb\u5165\u66f4\u4f20\u7edf\u5de5\u4f5c\u5f62\u5f0f\u7684\u6865\u6881\u3002\u5c1d\u8bd5\u5c45\u5bb6\u5de5\u4f5c\u4f1a\u63d0\u9ad8\u6ca1\u6709\u5148\u524d\u5de5\u4f5c\u7ecf\u5386\u7684\u5973\u6027\u5728\u4e24\u4e2a\u6708\u5230\u4e09\u4e2a\u6708\u540e\u8fdb\u5165\u66f4\u4e0d\u7075\u6d3b\u5de5\u4f5c\u7684\u53ef\u80fd\u6027\u3002\u5bf9\u4e8e\u6765\u81ea\u66f4\u4f20\u7edf\u5bb6\u5ead\u7684\u5973\u6027\u800c\u8a00\uff0c\u8fd9\u7c7b\u201c\u5165\u95e8\u5c97\u4f4d\u201d\u5c24\u4e3a\u91cd\u8981\uff1a\u5979\u4eec\u7684\u52b3\u52a8\u529b\u4f9b\u7ed9\u539f\u672c\u8f83\u4e3a\u4f9d\u8d56\u7075\u6d3b\u6027\uff0c\u800c\u4e00\u65e6\u83b7\u5f97\u5de5\u4f5c\u7ecf\u5386\uff0c\u5176\u6001\u5ea6\u4f1a\u9010\u6e10\u53d8\u5f97\u4e0d\u90a3\u4e48\u4f20\u7edf\u3002\u7b2c\u4e09\uff0c\u4ece\u52b3\u52a8\u529b\u9700\u6c42\u89d2\u5ea6\u770b\uff0c\u8fdc\u7a0b\u5de5\u4f5c\u5b58\u5728\u7ee9\u6548\u4e0a\u7684\u6743\u8861\u3002\u5728\u529e\u516c\u5ba4\u5de5\u4f5c\u6bd4\u5c45\u5bb6\u5de5\u4f5c\u63d0\u9ad8\u4e863%\u7684\u51c6\u786e\u6027\uff0c\u4ee5\u53ca18%\u7684\u901f\u5ea6\u3002\u7136\u800c\uff0c\u5c45\u5bb6\u5de5\u4f5c\u5e26\u6765\u7684\u5de5\u4eba\u6570\u91cf\u589e\u52a0\u53ef\u80fd\u62b5\u6d88\u8fd9\u4e9b\u7ee9\u6548\u52a3\u52bf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag107", "journal": "REStud", "title": "Revisiting Retirement and Social Security Claiming Decisions", "authors": ["Neha Bairoliya", "Kathleen McKiernan"], "author_details": [{"name": "Neha Bairoliya", "affiliations": ["University of Southern California"]}, {"name": "Kathleen McKiernan", "affiliations": ["Vanderbilt University"]}], "abstract": "Abstract The structure of the Social Security program presents a trade-off between benefit duration and size; individuals who claim early receive lower monthly payments. Surprisingly, even wealthy Americans with high life expectancies frequently claim benefits at the earliest eligibility age, a behavior inconsistent with conventional life-cycle theory predictions. In fact, there is a striking similarity in claiming ages across groups with vastly different life expectancies, wealth levels, and incentives to delay. This paper resolves this puzzle by introducing policy details and subjective beliefs about longevity and program rules into a rich, forward-looking life-cycle model. When included in the model, subjective beliefs substantially narrow the claiming-age gaps across education (college vs. non-college) and marital-status (married vs. single) groups. Specifically, differences in program beliefs alone account for 48.6% of the education claiming age gap and 75.1% of the marital status gap. Counterfactual policy simulations demonstrate that failing to account for these claiming mechanisms dramatically overstates individual responses to an increase in the normal retirement age and understates the resulting fiscal savings.", "date": "2026-09-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag107", "title_zh": "\u91cd\u65b0\u5ba1\u89c6\u9000\u4f11\u4e0e\u793e\u4f1a\u4fdd\u969c\u7533\u9886\u51b3\u7b56", "abstract_zh": "\u6458\u8981 \u793e\u4f1a\u4fdd\u969c\u8ba1\u5212\u7684\u7ed3\u6784\u5728\u53d7\u76ca\u671f\u9650\u548c\u91d1\u989d\u4e4b\u95f4\u5b58\u5728\u6743\u8861\uff1b\u63d0\u524d\u7533\u9886\u8005\u6bcf\u6708\u9886\u53d6\u7684\u91d1\u989d\u4f1a\u8f83\u4f4e\u3002\u4ee4\u4eba\u60ca\u8bb6\u7684\u662f\uff0c\u5373\u4f7f\u662f\u6709\u8f83\u9ad8\u5bff\u547d\u9884\u671f\u4e14\u8d22\u5bcc\u6c34\u5e73\u8f83\u9ad8\u7684\u7f8e\u56fd\u4eba\u7fa4\uff0c\u4e5f\u5e38\u5e38\u5728\u6700\u65e9\u53ef\u7533\u9886\u5e74\u9f84\u65f6\u5f00\u59cb\u9886\u53d6\u798f\u5229\uff0c\u8fd9\u4e00\u884c\u4e3a\u4e0e\u751f\u547d\u5468\u671f\u7406\u8bba\u7684\u5e38\u89c4\u9884\u6d4b\u76f8\u6096\u3002\u4e8b\u5b9e\u4e0a\uff0c\u4e0d\u540c\u751f\u547d\u9884\u671f\u3001\u8d22\u5bcc\u6c34\u5e73\u4ee5\u53ca\u5ef6\u8fdf\u7533\u9886\u6fc0\u52b1\u7684\u7fa4\u4f53\u4e4b\u95f4\uff0c\u5728\u7533\u9886\u5e74\u9f84\u4e0a\u8868\u73b0\u51fa\u663e\u8457\u76f8\u4f3c\u6027\u3002\u672c\u6587\u901a\u8fc7\u5728\u4e30\u5bcc\u7684\u524d\u77bb\u6027\u751f\u547d\u5468\u671f\u6a21\u578b\u4e2d\u5f15\u5165\u653f\u7b56\u7ec6\u8282\u4ee5\u53ca\u4e2a\u4f53\u5bf9\u5bff\u547d\u548c\u8ba1\u5212\u89c4\u5219\u7684\u4e3b\u89c2\u4fe1\u5ff5\uff0c\u89e3\u51b3\u4e86\u8fd9\u4e00\u6096\u8bba\u3002\u5f53\u8fd9\u4e9b\u4e3b\u89c2\u4fe1\u5ff5\u88ab\u7eb3\u5165\u6a21\u578b\u540e\uff0c\u6559\u80b2\u80cc\u666f\uff08\u5927\u5b66\u5b66\u5386\u4e0e\u975e\u5927\u5b66\u5b66\u5386\uff09\u548c\u5a5a\u59fb\u72b6\u51b5\uff08\u5df2\u5a5a\u4e0e\u672a\u5a5a\uff09\u7fa4\u4f53\u4e4b\u95f4\u7684\u7533\u9886\u5e74\u9f84\u5dee\u8ddd\u663e\u8457\u7f29\u5c0f\u3002\u5177\u4f53\u800c\u8a00\uff0c\u4ec5\u653f\u7b56\u4fe1\u5ff5\u7684\u5dee\u5f02\u5c31\u89e3\u91ca\u4e86\u6559\u80b2\u80cc\u666f\u7533\u9886\u5e74\u9f84\u5dee\u8ddd\u768448.6%\u548c\u5a5a\u59fb\u72b6\u51b5\u5dee\u8ddd\u768475.1%\u3002\u53cd\u4e8b\u5b9e\u7684\u653f\u7b56\u6a21\u62df\u8868\u660e\uff0c\u82e5\u4e0d\u8003\u8651\u8fd9\u4e9b\u7533\u9886\u673a\u5236\uff0c\u5c06\u4e25\u91cd\u9ad8\u4f30\u4e2a\u4f53\u5bf9\u63d0\u9ad8\u6b63\u5e38\u9000\u4f11\u5e74\u9f84\u7684\u53cd\u5e94\uff0c\u540c\u65f6\u4e25\u91cd\u4f4e\u4f30\u7531\u6b64\u5e26\u6765\u7684\u8d22\u653f\u8282\u7ea6\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.07272", "journal": "MS", "title": "Communicating Corporate Culture in Labor Markets: Evidence from Job Postings", "authors": ["Allen H. Huang", "Joseph Pacelli", "Terrence Tianshuo Shi", "Yuan Zou"], "author_details": [{"name": "Allen H. Huang", "affiliations": ["The Hong Kong University of Science and Technology, Kowloon, Hong Kong"]}, {"name": "Joseph Pacelli", "affiliations": ["Harvard Business School, Boston, Massachusetts 02163"]}, {"name": "Terrence Tianshuo Shi", "affiliations": ["UCLA Anderson School of Management, Los Angeles, California 90095"]}, {"name": "Yuan Zou", "affiliations": ["Harvard Business School, Boston, Massachusetts 02163"]}], "abstract": "We examine how culture information in job postings influences firms\u2019 hiring outcomes. We utilize machine learning methods to measure five core values present in job postings and demonstrate that culture information helps attract job seekers, as it is associated with higher worker inflows. The effect strengthens when job seekers value culture in their job searches and face frictions in learning about culture from other sources. Additional analyses indicate that individual cultural dimensions in job postings are more salient to job seekers when they have heightened preferences for that particular value. Finally, culture information is associated with a higher likelihood that interviews result in offers, and greater acceptance of those offers. Overall, our results suggest that culture information in job postings helps job seekers sort into culturally aligned firms.", "date": "2026-09-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07272", "title_zh": "\u52b3\u52a8\u5e02\u573a\u4e2d\u4f01\u4e1a\u6587\u5316\u7684\u4f20\u64ad\uff1a\u6765\u81ea\u62db\u8058\u5e7f\u544a\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u62db\u8058\u5e7f\u544a\u4e2d\u6587\u5316\u4fe1\u606f\u5982\u4f55\u5f71\u54cd\u4f01\u4e1a\u7684\u62db\u8058\u7ed3\u679c\u3002\u6211\u4eec\u5229\u7528\u673a\u5668\u5b66\u4e60\u65b9\u6cd5\u8861\u91cf\u62db\u8058\u5e7f\u544a\u4e2d\u4e94\u4e2a\u6838\u5fc3\u4ef7\u503c\u89c2\uff0c\u5e76\u8bc1\u660e\u6587\u5316\u4fe1\u606f\u6709\u52a9\u4e8e\u5438\u5f15\u6c42\u804c\u8005\uff0c\u56e0\u4e3a\u5176\u4e0e\u66f4\u9ad8\u7684\u5458\u5de5\u6d41\u5165\u91cf\u76f8\u5173\u3002\u5f53\u6c42\u804c\u8005\u5728\u6c42\u804c\u8fc7\u7a0b\u4e2d\u91cd\u89c6\u6587\u5316\u56e0\u7d20\u4e14\u96be\u4ee5\u901a\u8fc7\u5176\u4ed6\u6e20\u9053\u4e86\u89e3\u6587\u5316\u4fe1\u606f\u65f6\uff0c\u8fd9\u79cd\u6548\u5e94\u4f1a\u66f4\u52a0\u663e\u8457\u3002\u8fdb\u4e00\u6b65\u7684\u5206\u6790\u8868\u660e\uff0c\u5f53\u6c42\u804c\u8005\u5bf9\u67d0\u4e00\u7279\u5b9a\u6587\u5316\u7ef4\u5ea6\u6709\u66f4\u5f3a\u504f\u597d\u65f6\uff0c\u62db\u8058\u5e7f\u544a\u4e2d\u8be5\u7ef4\u5ea6\u7684\u4e2a\u4f53\u6587\u5316\u7279\u5f81\u4f1a\u66f4\u52a0\u7a81\u51fa\u3002\u6b64\u5916\uff0c\u6587\u5316\u4fe1\u606f\u4e0e\u9762\u8bd5\u8f6c\u5316\u4e3a\u5f55\u7528\u7684\u53ef\u80fd\u6027\u589e\u52a0\u4ee5\u53ca\u5f55\u7528\u7387\u7684\u63d0\u5347\u76f8\u5173\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u62db\u8058\u5e7f\u544a\u4e2d\u7684\u6587\u5316\u4fe1\u606f\u6709\u52a9\u4e8e\u6c42\u804c\u8005\u7b5b\u9009\u51fa\u4e0e\u81ea\u8eab\u6587\u5316\u76f8\u5339\u914d\u7684\u4f01\u4e1a\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2025.05353", "journal": "MS", "title": "Motivated Procrastination", "authors": ["Charlotte Cordes", "Jana Friedrichsen", "Simeon Schudy"], "author_details": [{"name": "Charlotte Cordes", "affiliations": ["Department of Economics, Ludwig-Maximilians-Universit\u00e4t Munich, 80539 Munich, Germany"]}, {"name": "Jana Friedrichsen", "affiliations": ["Institute of Economics and CESifo, Kiel University, 24098 Kiel, Germany"]}, {"name": "Simeon Schudy", "affiliations": ["Institute of Economics and CESifo, Ulm University, 89081 Ulm, Germany"]}], "abstract": "This study provides a rigorous empirical test for motivated memory as a cause for procrastination. In a longitudinal experiment over four weeks, individuals had to complete a cumbersome task of unknown length and receive noisy signals about their assigned workload. Varying scope for motivated memory results in more optimistic beliefs among workers who receive negative signals but not among those who receive positive ones. This suppression of negative news through motivated memory causes individuals to defer more work to the future.", "date": "2026-09-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.05353", "title_zh": "\u52a8\u673a\u6027\u62d6\u5ef6", "abstract_zh": "\u672c\u7814\u7a76\u5bf9\u52a8\u673a\u6027\u8bb0\u5fc6\u4f5c\u4e3a\u62d6\u5ef6\u539f\u56e0\u8fdb\u884c\u4e86\u4e25\u683c\u7684\u5b9e\u8bc1\u68c0\u9a8c\u3002\u5728\u4e3a\u671f\u56db\u5468\u7684\u7eb5\u5411\u5b9e\u9a8c\u4e2d\uff0c\u53c2\u4e0e\u8005\u9700\u8981\u5b8c\u6210\u4e00\u4e2a\u957f\u5ea6\u672a\u77e5\u4e14\u7e41\u7410\u7684\u4efb\u52a1\uff0c\u5e76\u63a5\u6536\u5230\u5173\u4e8e\u5176\u5206\u914d\u5de5\u4f5c\u91cf\u7684\u566a\u58f0\u4fe1\u53f7\u3002\u5f53\u52a8\u673a\u6027\u8bb0\u5fc6\u7684\u8303\u56f4\u53d8\u5316\u65f6\uff0c\u6536\u5230\u8d1f\u9762\u4fe1\u53f7\u7684\u5de5\u4eba\u8868\u73b0\u51fa\u66f4\u4e50\u89c2\u7684\u4fe1\u5ff5\uff0c\u800c\u6536\u5230\u6b63\u9762\u4fe1\u53f7\u7684\u5de5\u4eba\u5219\u6ca1\u6709\u8fd9\u79cd\u53d8\u5316\u3002\u901a\u8fc7\u52a8\u673a\u6027\u8bb0\u5fc6\u6291\u5236\u8d1f\u9762\u4fe1\u606f\uff0c\u5bfc\u81f4\u4e2a\u4f53\u5c06\u66f4\u591a\u5de5\u4f5c\u63a8\u8fdf\u5230\u672a\u6765\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35758", "journal": "NBER", "title": "Fiscal Populism and Monetary Policy Rules", "authors": ["Luis I. J\u00e1come", "Nicol\u00e1s E. Magud", "Samuel Pienknagura", "Mart\u00edn Uribe"], "author_details": [{"name": "Luis I. J\u00e1come", "affiliations": []}, {"name": "Nicol\u00e1s E. Magud", "affiliations": []}, {"name": "Samuel Pienknagura", "affiliations": []}, {"name": "Mart\u00edn Uribe", "affiliations": []}], "abstract": "We explore the historical link between populist regimes, fiscal monetization, and inflation, and how these links affect monetary policy in the 21st century. Using data for a large set of advanced economies and emerging markets since 1960, we show that, historically, left-leaning populist regimes are linked to increases in central bank lending to the central government, a gauge of deficit monetization. In turn, central bank lending is associated with marked increases in inflation. We show that past exposure to populism that relied on deficit monetization affects the conduct of monetary policy today. Countries with a history of deficit monetization and left-wing populist regimes systematically respond more strongly to deviations of inflation expectations from target. This effect persists even after controlling for the direct effect of past inflation on monetary policy rules. In the context of the literature of experienced learning, this novel finding sheds light on the persistence of past populist policies\u2014central banks operating under the shadow of past populist regimes that relied on inflation-prone deficit monetization continue today needing to send stronger signals of their independence and commitment to price stability to effectively anchor inflation expectations.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35758", "title_zh": "\u8d22\u653f\u6c11\u7cb9\u4e3b\u4e49\u4e0e\u8d27\u5e01\u653f\u7b56\u89c4\u5219", "abstract_zh": "\u6211\u4eec\u63a2\u8ba8\u4e86\u6c11\u7cb9\u653f\u6743\u3001\u8d22\u653f\u8d27\u5e01\u5316\u4e0e\u901a\u80c0\u4e4b\u95f4\u7684\u5386\u53f2\u8054\u7cfb\uff0c\u4ee5\u53ca\u8fd9\u4e9b\u8054\u7cfb\u5982\u4f55\u5f71\u54cd21\u4e16\u7eaa\u7684\u8d27\u5e01\u653f\u7b56\u3002\u5229\u75281960\u5e74\u4ee5\u6765\u5927\u91cf\u5148\u8fdb\u7ecf\u6d4e\u4f53\u548c\u65b0\u5174\u5e02\u573a\u7684\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5386\u53f2\u4e0a\u5de6\u7ffc\u6c11\u7cb9\u653f\u6743\u4e0e\u4e2d\u592e\u94f6\u884c\u5411\u4e2d\u592e\u653f\u5e9c\u653e\u8d37\uff08\u4f5c\u4e3a\u8d22\u653f\u8d64\u5b57\u8d27\u5e01\u5316\u7684\u8861\u91cf\u6307\u6807\uff09\u4e4b\u95f4\u5b58\u5728\u5173\u8054\u3002\u800c\u4e2d\u592e\u94f6\u884c\u653e\u8d37\u5219\u4e0e\u901a\u80c0\u663e\u8457\u4e0a\u5347\u76f8\u5173\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u8fc7\u53bb\u66fe\u7ecf\u5386\u8fc7\u4f9d\u8d56\u8d22\u653f\u8d64\u5b57\u8d27\u5e01\u5316\u7684\u6c11\u7cb9\u4e3b\u4e49\u653f\u7b56\uff0c\u4f1a\u5f71\u54cd\u5f53\u4eca\u7684\u8d27\u5e01\u653f\u7b56\u884c\u4e3a\u3002\u90a3\u4e9b\u66fe\u7ecf\u5386\u8fc7\u8d22\u653f\u8d64\u5b57\u8d27\u5e01\u5316\u548c\u5de6\u7ffc\u6c11\u7cb9\u653f\u6743\u7684\u56fd\u5bb6\uff0c\u7cfb\u7edf\u6027\u5730\u5bf9\u901a\u80c0\u9884\u671f\u504f\u79bb\u76ee\u6807\u503c\u505a\u51fa\u66f4\u5f3a\u7684\u53cd\u5e94\u3002\u8fd9\u4e00\u6548\u5e94\u5728\u63a7\u5236\u4e86\u8fc7\u53bb\u901a\u80c0\u5bf9\u8d27\u5e01\u653f\u7b56\u89c4\u5219\u7684\u76f4\u63a5\u5f71\u54cd\u540e\u4f9d\u7136\u5b58\u5728\u3002\u5728\u7ecf\u9a8c\u5b66\u4e60\u6587\u732e\u7684\u80cc\u666f\u4e0b\uff0c\u8fd9\u4e00\u53d1\u73b0\u63ed\u793a\u4e86\u8fc7\u53bb\u6c11\u7cb9\u653f\u7b56\u7684\u6301\u7eed\u6027\u2014\u2014\u5373\u4f7f\u5728\u4eca\u5929\uff0c\u4e2d\u592e\u94f6\u884c\u4ecd\u9700\u5728\u8fd0\u4f5c\u4e2d\u6301\u7eed\u4f20\u9012\u5176\u72ec\u7acb\u6027\u548c\u5bf9\u4ef7\u683c\u7a33\u5b9a\u7684\u627f\u8bfa\uff0c\u4ee5\u6709\u6548\u951a\u5b9a\u901a\u80c0\u9884\u671f\uff0c\u56e0\u4e3a\u5b83\u4eec\u4ecd\u5904\u4e8e\u8fc7\u53bb\u4f9d\u8d56\u901a\u80c0\u578b\u8d22\u653f\u8d64\u5b57\u8d27\u5e01\u5316\u6c11\u7cb9\u653f\u6743\u7684\u9634\u5f71\u4e4b\u4e0b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35759", "journal": "NBER", "title": "Responses to Extreme Price Changes: Evidence from the Residential Demand for Natural Gas", "authors": ["Anna Alberini", "Levan Bezhanishvili", "Milan \u0160\u010dasn\u00fd", "Roberton C. Williams III"], "author_details": [{"name": "Anna Alberini", "affiliations": []}, {"name": "Levan Bezhanishvili", "affiliations": []}, {"name": "Milan \u0160\u010dasn\u00fd", "affiliations": []}, {"name": "Roberton C. Williams III", "affiliations": []}], "abstract": "We examine the response of residential customers to an extreme price change \u2013 namely that imposed by the government in the Republic of Georgia during the pandemic lockdown in the winter of 2020 and early 2021. As of November 2020, the government paid the gas bill directly to the utility, effectively making gas free, as long as consumption was below or exactly 200 m3/month. The policy was lifted at the end of February 2021. We use quasi-experimental causal methods based on a control group comprised of permanent residents of an area along the North-South pipeline, who receive gas for free (up to the generous allowance of 700 m3/month) every winter, while the treatment group is comprised of households living in areas with similar climates and similar population density who received gas for free only during the pandemic free gas months. Controlling for the weather, the ATT of the policy is a 2-7% increase in gas consumption (in the treatment group compared to the control group). Back-of-the-envelope calculations suggest a price elasticity of demand of -6.5% to -11%.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35759", "title_zh": "\u5bf9\u6781\u7aef\u4ef7\u683c\u53d8\u52a8\u7684\u53cd\u5e94\uff1a\u6765\u81ea\u5929\u7136\u6c14\u4f4f\u5b85\u9700\u6c42\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4f4f\u5b85\u7528\u6237\u5bf9\u6781\u7aef\u4ef7\u683c\u53d8\u52a8\u7684\u53cd\u5e94\u2014\u2014\u5373\u683c\u9c81\u5409\u4e9a\u5171\u548c\u56fd\u57282020\u5e74\u51ac\u5b63\u81f32021\u5e74\u521d\u75ab\u60c5\u5c01\u9501\u671f\u95f4\u653f\u5e9c\u5b9e\u65bd\u7684\u4ef7\u683c\u653f\u7b56\u3002\u81ea2020\u5e7411\u6708\u8d77\uff0c\u653f\u5e9c\u76f4\u63a5\u5411\u516c\u7528\u4e8b\u4e1a\u516c\u53f8\u652f\u4ed8\u71c3\u6c14\u8d26\u5355\uff0c\u4f7f\u71c3\u6c14\u5728\u6bcf\u6708\u6d88\u8d39\u4e0d\u8d85\u8fc7\u6216\u6070\u597d\u4e3a200\u7acb\u65b9\u7c73\u7684\u60c5\u51b5\u4e0b\u514d\u8d39\u4f9b\u5e94\u3002\u8be5\u653f\u7b56\u4e8e2021\u5e742\u6708\u5e95\u88ab\u53d6\u6d88\u3002\u6211\u4eec\u91c7\u7528\u57fa\u4e8e\u5bf9\u7167\u7ec4\u7684\u51c6\u5b9e\u9a8c\u56e0\u679c\u65b9\u6cd5\uff0c\u5bf9\u7167\u7ec4\u4e3a\u6cbf\u5357\u5317\u8f93\u6c14\u7ba1\u9053\u6cbf\u7ebf\u7684\u5e38\u4f4f\u5c45\u6c11\uff0c\u4ed6\u4eec\u6bcf\u5e74\u51ac\u5b63\u53ef\u514d\u8d39\u83b7\u5f97\u71c3\u6c14\uff08\u6700\u591a700\u7acb\u65b9\u7c73/\u6708\uff09\uff0c\u800c\u5904\u7406\u7ec4\u4e3a\u6c14\u5019\u548c\u4eba\u53e3\u5bc6\u5ea6\u76f8\u4f3c\u7684\u5730\u533a\u5c45\u6c11\uff0c\u4ec5\u5728\u75ab\u60c5\u671f\u95f4\u83b7\u5f97\u514d\u8d39\u71c3\u6c14\u3002\u5728\u63a7\u5236\u5929\u6c14\u56e0\u7d20\u540e\uff0c\u5904\u7406\u7ec4\u76f8\u5bf9\u4e8e\u5bf9\u7167\u7ec4\u7684\u5e73\u5747\u5904\u7406\u6548\u5e94\uff08ATT\uff09\u663e\u793a\u71c3\u6c14\u6d88\u8d39\u589e\u52a0\u4e862%\u81f37%\u3002\u7c97\u7565\u4f30\u7b97\u8868\u660e\u9700\u6c42\u4ef7\u683c\u5f39\u6027\u4e3a-6.5%\u81f3-11%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35760", "journal": "NBER", "title": "Well-Being Salience in Corporate Disclosures and Worker Health", "authors": ["Riccardo Di Francesco", "Peter Hull", "Seetha Menon"], "author_details": [{"name": "Riccardo Di Francesco", "affiliations": []}, {"name": "Peter Hull", "affiliations": []}, {"name": "Seetha Menon", "affiliations": []}], "abstract": "We study how firms\u2019 orientation toward employee well-being shapes the health of their workers. Because this orientation is not directly observable, we measure it from the language Danish firms use in their public disclosures, applying language models to construct a firm-level well-being salience score. We link this score to population-wide administrative registers of health and sickness absence over 2013\u20132022, and exploit workers\u2019 mobility between firms to estimate how workers respond to a change in the salience of their employer. We find an asymmetry: workers who move to higher-salience firms take substantially more sickness absence, while their use of health care does not change. Because worsening health would raise both, the absence response suggests a behavioral change rather than deteriorating health. Broadly, our results show that firms shape not only worker health but how workers act on it, and that the language of routine corporate disclosure can reveal economically meaningful features of the workplace that administrative data leave unrecorded.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35760", "title_zh": "\u4f01\u4e1a\u62ab\u9732\u4e2d\u7684\u5458\u5de5\u798f\u7949\u5173\u6ce8\u5ea6\u4e0e\u5458\u5de5\u5065\u5eb7", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4f01\u4e1a\u5bf9\u5458\u5de5\u798f\u7949\u7684\u5173\u6ce8\u5982\u4f55\u5f71\u54cd\u5176\u5458\u5de5\u7684\u5065\u5eb7\u72b6\u51b5\u3002\u7531\u4e8e\u8fd9\u79cd\u5173\u6ce8\u65e0\u6cd5\u76f4\u63a5\u89c2\u6d4b\uff0c\u6211\u4eec\u4ece\u4e39\u9ea6\u4f01\u4e1a\u516c\u5f00\u62ab\u9732\u7684\u8bed\u8a00\u4e2d\u63d0\u53d6\u4fe1\u606f\uff0c\u5229\u7528\u8bed\u8a00\u6a21\u578b\u6784\u5efa\u4f01\u4e1a\u5c42\u9762\u7684\u798f\u7949\u5173\u6ce8\u5ea6\u5f97\u5206\u3002\u6211\u4eec\u5c06\u8be5\u5f97\u5206\u4e0e2013\u5e74\u81f32022\u5e74\u95f4\u8986\u76d6\u5168\u4f53\u4eba\u53e3\u7684\u5065\u5eb7\u548c\u75c5\u5047\u884c\u653f\u767b\u8bb0\u6570\u636e\u76f8\u8054\u7cfb\uff0c\u5e76\u5229\u7528\u5458\u5de5\u5728\u4f01\u4e1a\u95f4\u7684\u6d41\u52a8\u60c5\u51b5\uff0c\u4f30\u8ba1\u5458\u5de5\u5bf9\u96c7\u4e3b\u798f\u7949\u5173\u6ce8\u5ea6\u53d8\u5316\u7684\u53cd\u5e94\u3002\u6211\u4eec\u53d1\u73b0\u4e00\u79cd\u4e0d\u5bf9\u79f0\u6027\uff1a\u8f6c\u81f3\u66f4\u9ad8\u798f\u7949\u5173\u6ce8\u5ea6\u4f01\u4e1a\u7684\u5458\u5de5\u75c5\u5047\u663e\u8457\u589e\u52a0\uff0c\u800c\u5176\u533b\u7597\u4f7f\u7528\u60c5\u51b5\u5219\u6ca1\u6709\u53d8\u5316\u3002\u7531\u4e8e\u5065\u5eb7\u6076\u5316\u4f1a\u540c\u65f6\u5bfc\u81f4\u8fd9\u4e24\u9879\u53d8\u5316\uff0c\u75c5\u5047\u7684\u589e\u52a0\u8868\u660e\u7684\u662f\u884c\u4e3a\u6539\u53d8\u800c\u975e\u5065\u5eb7\u72b6\u51b5\u6076\u5316\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\u4f01\u4e1a\u4e0d\u4ec5\u5f71\u54cd\u5458\u5de5\u7684\u5065\u5eb7\uff0c\u8fd8\u5f71\u54cd\u5458\u5de5\u5982\u4f55\u5e94\u5bf9\u5065\u5eb7\u95ee\u9898\uff0c\u4e14\u4f01\u4e1a\u5e38\u89c4\u62ab\u9732\u7684\u8bed\u8a00\u80fd\u591f\u63ed\u793a\u884c\u653f\u6570\u636e\u672a\u8bb0\u5f55\u7684\u3001\u5177\u6709\u7ecf\u6d4e\u610f\u4e49\u7684\u804c\u573a\u7279\u5f81\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790"]}, {"doi": "10.3386/w35761", "journal": "NBER", "title": "Measuring Gender Attitudes Toward Men and Women", "authors": ["Joshua T. Dean", "Christine L. Exley", "Muriel Niederle", "Heather Sarsons"], "author_details": [{"name": "Joshua T. Dean", "affiliations": []}, {"name": "Christine L. Exley", "affiliations": []}, {"name": "Muriel Niederle", "affiliations": []}, {"name": "Heather Sarsons", "affiliations": []}], "abstract": "Gender-neutral attitudes judge a behavior the same way regardless of whether a man or a woman does it. Yet surveys of gender attitudes typically ask respondents to evaluate statements about men's or women's behaviors in isolation, never eliciting how the same behavior is evaluated when assigned to the other gender. Such responses therefore cannot reveal whether respondents perceive society as holding gender-neutral views. We introduce paired (role-reversed) elicitation, which varies the gender assigned to otherwise identical behaviors. In a representative sample of Americans, responses to standard statements suggest that few respondents perceive society as holding traditional views toward women. In isolation, this may be seen as evidence that society has moved past gender roles that confine choices. The paired elicitation, however, reveals a gender-neutrality gap: only about half of respondents report the same beliefs across the standard and role-reversed statements, even though these statements only vary in terms of which gender is assigned to which behavior. Thus, a substantial portion of respondents believe that the social acceptability of different actions depends on gender. Paired responses also uncover substantial heterogeneity and reveal broader underlying beliefs driving responses, such as beliefs about work and family rather than gender-specific views.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35761", "title_zh": "\u6d4b\u91cf\u5bf9\u7537\u6027\u548c\u5973\u6027\u7684\u6001\u5ea6", "abstract_zh": "\u4e2d\u7acb\u7684\u6027\u522b\u6001\u5ea6\u662f\u6307\u65e0\u8bba\u884c\u4e3a\u662f\u7531\u7537\u6027\u8fd8\u662f\u5973\u6027\u6267\u884c\uff0c\u90fd\u4f1a\u4ee5\u76f8\u540c\u65b9\u5f0f\u8bc4\u4ef7\u8be5\u884c\u4e3a\u3002\u7136\u800c\uff0c\u901a\u5e38\u7684\u6027\u522b\u6001\u5ea6\u8c03\u67e5\u4f1a\u8981\u6c42\u53d7\u8bbf\u8005\u5355\u72ec\u8bc4\u4f30\u5173\u4e8e\u7537\u6027\u6216\u5973\u6027\u884c\u4e3a\u7684\u9648\u8ff0\uff0c\u800c\u4ece\u672a\u8be2\u95ee\u76f8\u540c\u884c\u4e3a\u5728\u5206\u914d\u7ed9\u53e6\u4e00\u6027\u522b\u7684\u80cc\u666f\u4e0b\u4f1a\u5982\u4f55\u88ab\u8bc4\u4ef7\u3002\u56e0\u6b64\uff0c\u8fd9\u4e9b\u5355\u72ec\u7684\u56de\u7b54\u65e0\u6cd5\u63ed\u793a\u53d7\u8bbf\u8005\u662f\u5426\u8ba4\u4e3a\u793e\u4f1a\u6301\u4e2d\u7acb\u7684\u6027\u522b\u89c2\u5ff5\u3002\u6211\u4eec\u5f15\u5165\u4e86\u914d\u5bf9\uff08\u89d2\u8272\u53cd\u8f6c\uff09\u7684\u8c03\u67e5\u65b9\u6cd5\uff0c\u5373\u5728\u884c\u4e3a\u76f8\u540c\u7684\u60c5\u51b5\u4e0b\u6539\u53d8\u6027\u522b\u5f52\u5c5e\u3002\u5728\u5177\u6709\u4ee3\u8868\u6027\u7684\u7f8e\u56fd\u6837\u672c\u4e2d\uff0c\u9488\u5bf9\u6807\u51c6\u9648\u8ff0\u7684\u56de\u7b54\u8868\u660e\uff0c\u5f88\u5c11\u6709\u53d7\u8bbf\u8005\u8ba4\u4e3a\u793e\u4f1a\u5bf9\u5973\u6027\u6301\u4f20\u7edf\u89c2\u5ff5\u3002\u5355\u72ec\u6765\u770b\uff0c\u8fd9\u53ef\u80fd\u88ab\u89e3\u8bfb\u4e3a\u793e\u4f1a\u5df2\u7ecf\u8d85\u8d8a\u4e86\u9650\u5236\u9009\u62e9\u7684\u6027\u522b\u89d2\u8272\u3002\u7136\u800c\uff0c\u914d\u5bf9\u8c03\u67e5\u63ed\u793a\u4e86\u4e00\u4e2a\u6027\u522b\u4e2d\u7acb\u6027\u5dee\u8ddd\uff1a\u4ec5\u6709\u7ea6\u4e00\u534a\u7684\u53d7\u8bbf\u8005\u5728\u6807\u51c6\u9648\u8ff0\u548c\u89d2\u8272\u53cd\u8f6c\u9648\u8ff0\u4e2d\u8868\u8fbe\u4e86\u76f8\u540c\u7684\u89c2\u70b9\uff0c\u5c3d\u7ba1\u8fd9\u4e24\u7c7b\u9648\u8ff0\u4ec5\u5728\u6027\u522b\u5f52\u5c5e\u4e0a\u6709\u6240\u4e0d\u540c\u3002\u56e0\u6b64\uff0c\u76f8\u5f53\u4e00\u90e8\u5206\u53d7\u8bbf\u8005\u8ba4\u4e3a\u4e0d\u540c\u884c\u4e3a\u7684\u793e\u4f1a\u53ef\u63a5\u53d7\u6027\u53d6\u51b3\u4e8e\u6027\u522b\u3002\u914d\u5bf9\u56de\u7b54\u8fd8\u63ed\u793a\u4e86\u663e\u8457\u7684\u5f02\u8d28\u6027\uff0c\u5e76\u63ed\u793a\u4e86\u9a71\u52a8\u53d7\u8bbf\u8005\u53cd\u5e94\u7684\u66f4\u5e7f\u6cdb\u6df1\u5c42\u4fe1\u5ff5\uff0c\u5982\u5bf9\u5de5\u4f5c\u548c\u5bb6\u5ead\u7684\u770b\u6cd5\uff0c\u800c\u975e\u7279\u5b9a\u6027\u522b\u89c2\u5ff5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35762", "journal": "NBER", "title": "Digital (Killer?) Acquisitions", "authors": ["Florian Ederer", "Regina Seibel", "Timothy Simcoe"], "author_details": [{"name": "Florian Ederer", "affiliations": []}, {"name": "Regina Seibel", "affiliations": []}, {"name": "Timothy Simcoe", "affiliations": []}], "abstract": "This paper examines innovation outcomes before and after 1,200 startup acquisitions by eight major technology firms. Linking patent and workforce data to these deals, we document four main findings. First, most acquired startups hold no patents, but those with patents tend to operate in technology areas where the acquirer already has a presence and that see further acquisition activity. Second, innovation typically rises before an acquisition, continues afterward only where further acquisitions follow, and falls back once acquisition activity ends. We propose a stylized model in which beliefs about commercial viability drive both startup entry and acquisitions to explain how these patterns arise through selection rather than effects of the deals. Third, acquired patents receive significantly more citations after the acquisition than comparable patents, not only from the acquirer but also from firms that hire the targets\u2019 employees. Fourth, although 31% of employees and 23% of inventors depart within a year, inventors who stay go on to patent substantially more, while stayers and leavers were equally productive beforehand. In the aggregate, we find little evidence that acquisitions by digital incumbents suppress innovation, even though serial acquisitions go hand in hand with growing patent consolidation.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35762", "title_zh": "\u6570\u5b57\uff08\u6740\u624b\u7ea7\uff09\u6536\u8d2d", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u516b\u5bb6\u5927\u578b\u79d1\u6280\u516c\u53f8\u5bf91200\u5bb6\u521d\u521b\u4f01\u4e1a\u7684\u6536\u8d2d\u884c\u4e3a\u524d\u540e\u521b\u65b0\u6210\u679c\u7684\u53d8\u5316\u3002\u901a\u8fc7\u5c06\u4e13\u5229\u548c\u5458\u5de5\u6570\u636e\u4e0e\u8fd9\u4e9b\u4ea4\u6613\u5173\u8054\uff0c\u6211\u4eec\u5f97\u51fa\u56db\u9879\u4e3b\u8981\u53d1\u73b0\u3002\u9996\u5148\uff0c\u5927\u591a\u6570\u88ab\u6536\u8d2d\u7684\u521d\u521b\u4f01\u4e1a\u6ca1\u6709\u4e13\u5229\uff0c\u4f46\u62e5\u6709\u4e13\u5229\u7684\u4f01\u4e1a\u5f80\u5f80\u5904\u4e8e\u6536\u8d2d\u65b9\u5df2\u6709\u5e03\u5c40\u7684\u6280\u672f\u9886\u57df\uff0c\u5e76\u4e14\u8fd9\u4e9b\u9886\u57df\u4e5f\u6b63\u7ecf\u5386\u8fdb\u4e00\u6b65\u7684\u6536\u8d2d\u6d3b\u52a8\u3002\u5176\u6b21\uff0c\u521b\u65b0\u901a\u5e38\u5728\u6536\u8d2d\u524d\u4e0a\u5347\uff0c\u6536\u8d2d\u540e\u4ec5\u5728\u540e\u7eed\u51fa\u73b0\u66f4\u591a\u6536\u8d2d\u7684\u60c5\u51b5\u4e0b\u6301\u7eed\uff0c\u4e00\u65e6\u6536\u8d2d\u6d3b\u52a8\u505c\u6b62\uff0c\u521b\u65b0\u6c34\u5e73\u5219\u56de\u843d\u3002\u6211\u4eec\u63d0\u51fa\u4e00\u4e2a\u7b80\u5316\u6a21\u578b\uff0c\u8ba4\u4e3a\u5173\u4e8e\u5546\u4e1a\u53ef\u884c\u6027\u7684\u4fe1\u5ff5\u9a71\u52a8\u4e86\u521d\u521b\u4f01\u4e1a\u8fdb\u5165\u548c\u6536\u8d2d\u884c\u4e3a\uff0c\u4ece\u800c\u901a\u8fc7\u9009\u62e9\u673a\u5236\u89e3\u91ca\u8fd9\u4e9b\u6a21\u5f0f\u7684\u5f62\u6210\uff0c\u800c\u975e\u6536\u8d2d\u884c\u4e3a\u672c\u8eab\u7684\u5f71\u54cd\u3002\u7b2c\u4e09\uff0c\u88ab\u6536\u8d2d\u7684\u4e13\u5229\u5728\u6536\u8d2d\u540e\u83b7\u5f97\u663e\u8457\u66f4\u591a\u7684\u5f15\u7528\uff0c\u4e0d\u4ec5\u6765\u81ea\u6536\u8d2d\u65b9\uff0c\u4e5f\u6765\u81ea\u96c7\u4f63\u4e86\u76ee\u6807\u4f01\u4e1a\u5458\u5de5\u7684\u5176\u4ed6\u516c\u53f8\u3002\u7b2c\u56db\uff0c\u5c3d\u7ba131%\u7684\u5458\u5de5\u548c23%\u7684\u53d1\u660e\u4eba\u4e00\u5e74\u5185\u79bb\u804c\uff0c\u4f46\u7559\u4efb\u7684\u53d1\u660e\u4eba\u540e\u7eed\u83b7\u5f97\u7684\u4e13\u5229\u6570\u91cf\u663e\u8457\u589e\u52a0\uff0c\u800c\u7559\u4efb\u8005\u548c\u79bb\u804c\u8005\u5728\u6536\u8d2d\u524d\u7684\u751f\u4ea7\u529b\u6c34\u5e73\u662f\u76f8\u5f53\u7684\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u53d1\u73b0\u5927\u578b\u6570\u5b57\u4f01\u4e1a\u6536\u8d2d\u884c\u4e3a\u5e76\u672a\u663e\u8457\u6291\u5236\u521b\u65b0\uff0c\u5c3d\u7ba1\u8fde\u7eed\u6536\u8d2d\u5f80\u5f80\u4f34\u968f\u7740\u4e13\u5229\u96c6\u4e2d\u5ea6\u7684\u4e0a\u5347\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.3386/w35763", "journal": "NBER", "title": "The Impact of Fertility on Mothers\u2019 Remote Work", "authors": ["Benjamin W. Cowan", "Mohamed Hafis Zida"], "author_details": [{"name": "Benjamin W. Cowan", "affiliations": []}, {"name": "Mohamed Hafis Zida", "affiliations": []}], "abstract": "This paper estimates the causal effect of fertility on mothers\u2019 work arrangements, with a particular focus on remote work. Using harmonized individual-level data from the American Community Survey (ACS) for the period 2003--2024, we exploit exogenous variation in fertility generated by the sex composition of the first two children and twin births at the second parity. We find that fertility significantly reduces labor force participation across our sample period, consistent with existing evidence, but its effects on remote work are nuanced. Prior to the COVID-19 pandemic, an additional child increases the likelihood of working remotely. However, these effects turn negative after 2020 when remote work became common. We show that these patterns are not driven by changing selection into teleworkable occupations nor by changes in the observable characteristics of compliers over time. The limited feasibility or attractiveness of remote work for many women, combined with changes in the nature of remote work over time, are more likely explanations. Taken together, these findings suggest that remote work, in its current form, has limited potential to meaningfully reduce child penalties for higher-order births.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35763", "title_zh": "\u751f\u80b2\u5bf9\u6bcd\u4eb2\u8fdc\u7a0b\u5de5\u4f5c\u7684\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u4f30\u8ba1\u4e86\u751f\u80b2\u5bf9\u6bcd\u4eb2\u5de5\u4f5c\u5b89\u6392\u7684\u56e0\u679c\u6548\u5e94\uff0c\u7279\u522b\u662f\u8fdc\u7a0b\u5de5\u4f5c\u7684\u5f71\u54cd\u3002\u5229\u75282003\u5e74\u81f32024\u5e74\u7f8e\u56fd\u793e\u533a\u8c03\u67e5\uff08ACS\uff09\u7684\u4e2a\u4f53\u5c42\u9762\u6570\u636e\uff0c\u6211\u4eec\u5229\u7528\u7b2c\u4e00\u80ce\u548c\u7b2c\u4e8c\u80ce\u5b50\u5973\u6027\u522b\u6784\u6210\u4ee5\u53ca\u53cc\u80de\u80ce\u51fa\u751f\u8fd9\u4e00\u5916\u751f\u56e0\u7d20\uff0c\u6765\u7814\u7a76\u751f\u80b2\u5bf9\u5de5\u4f5c\u5b89\u6392\u7684\u5f71\u54cd\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u751f\u80b2\u663e\u8457\u964d\u4f4e\u4e86\u52b3\u52a8\u529b\u53c2\u4e0e\u7387\uff0c\u8fd9\u4e0e\u5df2\u6709\u8bc1\u636e\u4e00\u81f4\uff0c\u4f46\u5176\u5bf9\u8fdc\u7a0b\u5de5\u4f5c\u7684\u5f71\u54cd\u5219\u8f83\u4e3a\u590d\u6742\u3002\u5728\u65b0\u51a0\u75ab\u60c5\u4e4b\u524d\uff0c\u6bcf\u591a\u4e00\u4e2a\u5b69\u5b50\u4f1a\u589e\u52a0\u6bcd\u4eb2\u4ece\u4e8b\u8fdc\u7a0b\u5de5\u4f5c\u7684\u53ef\u80fd\u6027\u3002\u7136\u800c\uff0c\u81ea2020\u5e74\u540e\uff0c\u968f\u7740\u8fdc\u7a0b\u5de5\u4f5c\u53d8\u5f97\u666e\u904d\uff0c\u8fd9\u4e00\u6548\u5e94\u8f6c\u4e3a\u8d1f\u5411\u3002\u6211\u4eec\u8868\u660e\uff0c\u8fd9\u4e9b\u6a21\u5f0f\u5e76\u975e\u7531\u8fdb\u5165\u8fdc\u7a0b\u5de5\u4f5c\u804c\u4e1a\u7684\u9009\u62e9\u53d8\u5316\uff0c\u4e5f\u5e76\u975e\u7531\u5408\u89c4\u8005\u5728\u65f6\u95f4\u4e0a\u7684\u53ef\u89c2\u6d4b\u7279\u5f81\u53d8\u5316\u6240\u9a71\u52a8\u3002\u66f4\u53ef\u80fd\u7684\u89e3\u91ca\u662f\uff0c\u5bf9\u4e8e\u8bb8\u591a\u5973\u6027\u800c\u8a00\uff0c\u8fdc\u7a0b\u5de5\u4f5c\u7684\u53ef\u884c\u6027\u6216\u5438\u5f15\u529b\u6709\u9650\uff0c\u4ee5\u53ca\u8fdc\u7a0b\u5de5\u4f5c\u6027\u8d28\u968f\u65f6\u95f4\u7684\u53d8\u5316\u3002\u7efc\u5408\u6765\u770b\uff0c\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u5f53\u524d\u5f62\u5f0f\u7684\u8fdc\u7a0b\u5de5\u4f5c\u5728\u51cf\u5c11\u9ad8\u9636\u751f\u80b2\u5e26\u6765\u7684\u5b50\u5973\u60e9\u7f5a\u65b9\u9762\u6f5c\u529b\u6709\u9650\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35764", "journal": "NBER", "title": "Incentivizing Self-Protection From Wildfires", "authors": ["Patrick Baylis", "Judson Boomhower", "Bob Horton", "Chris Mulverhill"], "author_details": [{"name": "Patrick Baylis", "affiliations": []}, {"name": "Judson Boomhower", "affiliations": []}, {"name": "Bob Horton", "affiliations": []}, {"name": "Chris Mulverhill", "affiliations": []}], "abstract": "Losses from natural disasters can be mitigated through investments in property protection, yet adoption of low-cost risk-reducing measures remains low. In wildfire-exposed areas, managing vegetation and other fuels next to homes decreases structure vulnerability, but few properties comply with best practices despite widespread outreach efforts. We report on two randomized field experiments that incentivized thousands of Oregon homeowners to participate in pre-existing fire department programs to reduce wildfire risk. Across both experiments, financial incentives of $100 to $500 resulted in up to 12% of homeowners scheduling free defensible space assessments, while information-only approaches achieved assessment takeup rates of 3% at most. Responses to subsidies are largest among owners of more valuable homes, while baseline wildfire risk does not predict responsiveness. On-the-ground and remotely-sensed measures of vegetation provide noisy estimates of treatment effects on endline vegetation. Finally, we consider the extent to which the estimated behavioral elasticities from these experiments might shed light on potential homeowner responses to pricing of wildfire risk reductions in home insurance premiums, a practice that is becoming more common due to technological and regulatory changes.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35764", "title_zh": "\u6fc0\u52b1\u5c45\u6c11\u81ea\u6211\u9632\u62a4\u4ee5\u5e94\u5bf9\u91ce\u706b", "abstract_zh": "\u81ea\u7136\u707e\u5bb3\u9020\u6210\u7684\u635f\u5931\u53ef\u4ee5\u901a\u8fc7\u5bf9\u8d22\u4ea7\u8fdb\u884c\u4fdd\u62a4\u7684\u6295\u8d44\u6765\u7f13\u89e3\uff0c\u7136\u800c\uff0c\u91c7\u7eb3\u4f4e\u6210\u672c\u7684\u98ce\u9669\u964d\u4f4e\u63aa\u65bd\u4ecd\u5904\u4e8e\u8f83\u4f4e\u6c34\u5e73\u3002\u5728\u91ce\u706b\u9ad8\u53d1\u5730\u533a\uff0c\u7ba1\u7406\u623f\u5c4b\u5468\u8fb9\u7684\u690d\u88ab\u548c\u5176\u4ed6\u53ef\u71c3\u7269\u53ef\u4ee5\u964d\u4f4e\u5efa\u7b51\u7684\u6613\u635f\u6027\uff0c\u4f46\u5c3d\u7ba1\u8fdb\u884c\u4e86\u5e7f\u6cdb\u7684\u5ba3\u4f20\uff0c\u4ecd\u5f88\u5c11\u6709\u623f\u4ea7\u7b26\u5408\u6700\u4f73\u5b9e\u8df5\u3002\u6211\u4eec\u62a5\u544a\u4e86\u4e24\u9879\u968f\u673a\u5b9e\u5730\u5b9e\u9a8c\uff0c\u65e8\u5728\u6fc0\u52b1\u6570\u5343\u540d\u4fc4\u52d2\u5188\u5dde\u5c45\u6c11\u53c2\u4e0e\u73b0\u6709\u7684\u6d88\u9632\u90e8\u95e8\u9879\u76ee\uff0c\u4ee5\u964d\u4f4e\u91ce\u706b\u98ce\u9669\u3002\u5728\u4e24\u9879\u5b9e\u9a8c\u4e2d\uff0c\u63d0\u4f9b100\u81f3500\u7f8e\u5143\u7684\u8d22\u52a1\u6fc0\u52b1\uff0c\u4f7f\u591a\u8fbe12%\u7684\u623f\u4e3b\u5b89\u6392\u4e86\u514d\u8d39\u7684\u9632\u706b\u5e26\u8bc4\u4f30\uff0c\u800c\u4ec5\u63d0\u4f9b\u4fe1\u606f\u7684\u63aa\u65bd\u6700\u591a\u4ec5\u4f7f3%\u7684\u623f\u4e3b\u53c2\u4e0e\u8bc4\u4f30\u3002\u5bf9\u8865\u8d34\u7684\u54cd\u5e94\u5728\u623f\u5c4b\u4ef7\u503c\u66f4\u9ad8\u7684\u4e1a\u4e3b\u4e2d\u6700\u4e3a\u663e\u8457\uff0c\u800c\u57fa\u7840\u91ce\u706b\u98ce\u9669\u5e76\u4e0d\u80fd\u9884\u6d4b\u5176\u54cd\u5e94\u7a0b\u5ea6\u3002\u5b9e\u5730\u6d4b\u91cf\u548c\u9065\u611f\u6280\u672f\u5bf9\u690d\u88ab\u7684\u6d4b\u91cf\u63d0\u4f9b\u4e86\u5bf9\u6700\u7ec8\u690d\u88ab\u72b6\u51b5\u5904\u7406\u6548\u679c\u7684\u566a\u58f0\u4f30\u8ba1\u3002\u6700\u540e\uff0c\u6211\u4eec\u63a2\u8ba8\u4e86\u8fd9\u4e9b\u5b9e\u9a8c\u4e2d\u4f30\u8ba1\u7684\u884c\u4e3a\u5f39\u6027\u662f\u5426\u80fd\u4e3a\u672a\u6765\u5728\u5bb6\u5ead\u4fdd\u9669\u4fdd\u8d39\u4e2d\u5b9a\u4ef7\u91ce\u706b\u98ce\u9669\u964d\u4f4e\u63aa\u65bd\u7684\u6f5c\u5728\u5c45\u6c11\u53cd\u5e94\u63d0\u4f9b\u53c2\u8003\uff0c\u8fd9\u79cd\u505a\u6cd5\u6b63\u56e0\u6280\u672f\u8fdb\u6b65\u548c\u76d1\u7ba1\u53d8\u5316\u800c\u65e5\u76ca\u666e\u904d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35765", "journal": "NBER", "title": "The Evolving Marriage Gap in Children\u2019s Outcomes: Family Structure and Young Adult Outcomes Revisited", "authors": ["Melissa Schettini Kearney", "Phillip B. Levine", "Alden Q. Barson"], "author_details": [{"name": "Melissa Schettini Kearney", "affiliations": []}, {"name": "Phillip B. Levine", "affiliations": []}, {"name": "Alden Q. Barson", "affiliations": []}], "abstract": "Much of the existing research on the relationship between family structure and children\u2019s outcomes has focused on average effects. Kearney and Levine (2017) instead proposed a heterogeneous framework in which the gap in outcomes between children of married and unmarried parents varies according to the resource context, namely a mother\u2019s own resources, the net resources that a partner would contribute, and the outcome-specific returns to those resources. Using data from the 2013 Panel Study of Income Dynamics (PSID), they found evidence consistent with the model\u2019s predictions. We revisit this question using the 2023 PSID to examine how these relationships have changed over the past decade. We find that the association between childhood family structure and young adult poverty has greatly diminished, whereas the association with college completion persists and is concentrated among children of mothers with higher levels of education. These findings suggest that although the economic circumstances of single mothers and their children have generally improved in recent decades, disparities in household resources and higher-order educational outcomes by family structure remain.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35765", "title_zh": "\u513f\u7ae5\u7ed3\u679c\u4e2d\u5bb6\u5ead\u7ed3\u6784\u5dee\u8ddd\u7684\u6f14\u53d8\uff1a\u5bb6\u5ead\u7ed3\u6784\u4e0e\u9752\u5e74\u7ed3\u679c\u518d\u5ba1\u89c6", "abstract_zh": "\u5173\u4e8e\u5bb6\u5ead\u7ed3\u6784\u4e0e\u513f\u7ae5\u7ed3\u679c\u4e4b\u95f4\u5173\u7cfb\u7684\u73b0\u6709\u7814\u7a76\u5927\u591a\u96c6\u4e2d\u4e8e\u5e73\u5747\u6548\u5e94\u3002Kearney\u548cLevine\uff082017\uff09\u63d0\u51fa\u4e86\u4e00\u79cd\u5f02\u8d28\u6027\u6846\u67b6\uff0c\u5176\u4e2d\u5a5a\u59fb\u5bb6\u5ead\u4e0e\u975e\u5a5a\u59fb\u5bb6\u5ead\u5b50\u5973\u4e4b\u95f4\u7684\u7ed3\u679c\u5dee\u8ddd\u4f1a\u6839\u636e\u8d44\u6e90\u80cc\u666f\u800c\u53d8\u5316\uff0c\u5373\u6bcd\u4eb2\u81ea\u8eab\u7684\u8d44\u6e90\u3001\u4f34\u4fa3\u53ef\u80fd\u8d21\u732e\u7684\u51c0\u8d44\u6e90\uff0c\u4ee5\u53ca\u8fd9\u4e9b\u8d44\u6e90\u5728\u7279\u5b9a\u7ed3\u679c\u4e0a\u7684\u56de\u62a5\u7387\u3002\u4ed6\u4eec\u5229\u75282013\u5e74\u6536\u5165\u52a8\u6001\u9762\u677f\u8c03\u67e5\uff08PSID\uff09\u7684\u6570\u636e\uff0c\u53d1\u73b0\u7ed3\u679c\u4e0e\u6a21\u578b\u9884\u6d4b\u4e00\u81f4\u3002\u6211\u4eec\u4f7f\u75282023\u5e74PSID\u7684\u6570\u636e\u91cd\u65b0\u8003\u5bdf\u4e86\u8fc7\u53bb\u5341\u5e74\u4e2d\u8fd9\u4e9b\u5173\u7cfb\u7684\u53d8\u5316\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u7ae5\u5e74\u5bb6\u5ead\u7ed3\u6784\u4e0e\u9752\u5e74\u8d2b\u56f0\u4e4b\u95f4\u7684\u5173\u8054\u5df2\u663e\u8457\u51cf\u5f31\uff0c\u800c\u4e0e\u5927\u5b66\u5b8c\u6210\u7387\u7684\u5173\u8054\u4ecd\u7136\u5b58\u5728\uff0c\u4e14\u4e3b\u8981\u96c6\u4e2d\u5728\u6bcd\u4eb2\u6559\u80b2\u6c34\u5e73\u8f83\u9ad8\u7684\u5b50\u5973\u4e2d\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u5c3d\u7ba1\u5355\u4eb2\u6bcd\u4eb2\u53ca\u5176\u5b50\u5973\u7684\u7ecf\u6d4e\u72b6\u51b5\u5728\u6700\u8fd1\u51e0\u5341\u5e74\u4e2d\u603b\u4f53\u4e0a\u6709\u6240\u6539\u5584\uff0c\u4f46\u5bb6\u5ead\u7ed3\u6784\u5728\u5bb6\u5ead\u8d44\u6e90\u5206\u914d\u548c\u66f4\u9ad8\u5c42\u6b21\u6559\u80b2\u7ed3\u679c\u4e0a\u7684\u5dee\u5f02\u4f9d\u7136\u5b58\u5728\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35766", "journal": "NBER", "title": "Expectations and the Term Structure of Interest Rates", "authors": ["Pooya Molavi", "Alireza Tahbaz-Salehi", "Andrea Vedolin"], "author_details": [{"name": "Pooya Molavi", "affiliations": []}, {"name": "Alireza Tahbaz-Salehi", "affiliations": []}, {"name": "Andrea Vedolin", "affiliations": []}], "abstract": "This paper studies the relationship between subjective expectations and the term structure of interest rates. Departing from rational expectations, we allow market participants to hold arbitrary beliefs about future interest rates, and derive the condition that expected and realized interest rates must satisfy irrespective of how expectations are formed. We use this condition to decompose the sensitivity of long-term yields to the short-term interest rate into contributions from expectations and risk premia, without imposing any assumption on expectation formation. We find that, for short- and medium-maturity bonds, this sensitivity is driven primarily by movements in expectations rather than risk premia. We then study the sensitivity of expectations themselves and document systematic wedges between the response of long-term yield expectations and that of expectations of shorter-maturity yields over the same window. We argue that these wedges reflect structural inconsistency in subjective expectations, in the sense that expectations across maturities and forecast horizons are inconsistent with the equilibrium restrictions that link different interest rates.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35766", "title_zh": "\u9884\u671f\u4e0e\u5229\u7387\u671f\u9650\u7ed3\u6784", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e3b\u89c2\u9884\u671f\u4e0e\u5229\u7387\u671f\u9650\u7ed3\u6784\u4e4b\u95f4\u7684\u5173\u7cfb\u3002\u504f\u79bb\u7406\u6027\u9884\u671f\u5047\u8bbe\uff0c\u6211\u4eec\u5141\u8bb8\u5e02\u573a\u53c2\u4e0e\u8005\u5bf9\u672a\u6765\u7684\u5229\u7387\u6301\u6709\u4efb\u610f\u4fe1\u5ff5\uff0c\u5e76\u63a8\u5bfc\u51fa\u65e0\u8bba\u9884\u671f\u5982\u4f55\u5f62\u6210\uff0c\u9884\u671f\u5229\u7387\u4e0e\u5b9e\u9645\u5229\u7387\u4e4b\u95f4\u5fc5\u987b\u6ee1\u8db3\u7684\u6761\u4ef6\u3002\u6211\u4eec\u5229\u7528\u8fd9\u4e00\u6761\u4ef6\uff0c\u5c06\u957f\u671f\u6536\u76ca\u7387\u5bf9\u77ed\u671f\u5229\u7387\u7684\u654f\u611f\u6027\u5206\u89e3\u4e3a\u9884\u671f\u548c\u98ce\u9669\u6ea2\u4ef7\u7684\u8d21\u732e\uff0c\u800c\u65e0\u9700\u5bf9\u9884\u671f\u5f62\u6210\u8fc7\u7a0b\u505a\u51fa\u4efb\u4f55\u5047\u8bbe\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5bf9\u4e8e\u77ed\u671f\u548c\u4e2d\u671f\u503a\u5238\uff0c\u8fd9\u79cd\u654f\u611f\u6027\u4e3b\u8981\u7531\u9884\u671f\u7684\u53d8\u5316\u9a71\u52a8\uff0c\u800c\u975e\u98ce\u9669\u6ea2\u4ef7\u3002\u968f\u540e\uff0c\u6211\u4eec\u7814\u7a76\u9884\u671f\u672c\u8eab\u7684\u654f\u611f\u6027\uff0c\u5e76\u53d1\u73b0\u957f\u671f\u6536\u76ca\u7387\u9884\u671f\u4e0e\u76f8\u540c\u65f6\u95f4\u6bb5\u5185\u77ed\u671f\u6536\u76ca\u7387\u9884\u671f\u4e4b\u95f4\u5b58\u5728\u7cfb\u7edf\u6027\u7684\u5dee\u5f02\u3002\u6211\u4eec\u8ba4\u4e3a\uff0c\u8fd9\u4e9b\u5dee\u5f02\u53cd\u6620\u4e86\u4e3b\u89c2\u9884\u671f\u4e2d\u7684\u7ed3\u6784\u6027\u4e0d\u4e00\u81f4\u6027\uff0c\u5373\u4e0d\u540c\u671f\u9650\u548c\u9884\u6d4b\u671f\u9650\u4e4b\u95f4\u7684\u9884\u671f\u4e0e\u8fde\u63a5\u4e0d\u540c\u5229\u7387\u7684\u5747\u8861\u7ea6\u675f\u4e0d\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.3386/w35767", "journal": "NBER", "title": "Borrowing in the Shadow of China", "authors": ["Illenin O. Kondo", "C\u00e9sar Sosa-Padilla", "Zachary J. Swaziek"], "author_details": [{"name": "Illenin O. Kondo", "affiliations": []}, {"name": "C\u00e9sar Sosa-Padilla", "affiliations": []}, {"name": "Zachary J. Swaziek", "affiliations": []}], "abstract": "China's rise as a major lender to emerging economies since the early 2000s has introduced a unique form of lender power: borrowers cannot default on the subsidized loans they receive, but may still face sudden rollover demands outside their control. We argue this distinctive structure\u2014bilateral rollover risk without default risk\u2014disciplines recipient countries' borrowing on international markets. In a quantitative long-term sovereign debt model, we show that such rollover-prone nondefaultable Chinese loans expose market debt to dilution risk: governments may need to tap international lenders when repayment to China comes due, and therefore choose to deleverage from private markets when Chinese inflows arrive. Market debt and bond yield dynamics in the data are consistent with this \u201cdisciplining effect.\u201d We then use the model to study two geopolitical scenarios: a bloc-formation exercise in which China offers take-it-or-leave-it loans to induce the borrower's exit from international debt markets, and an optimal exposure-to-China problem under the risk of a permanent and sudden retrenchment of Chinese funding. Together, these results show how official finance \u00e0 la China can simultaneously improve market borrowing conditions and become a new destabilizing force to the global sovereign debt architecture as geopolitical alliances shift.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35767", "title_zh": "\u5728\u5f71\u5b50\u4e2d\u501f\u8d37\uff1a\u4e2d\u56fd\u7684\u5d1b\u8d77", "abstract_zh": "\u81ea2000\u5e74\u4ee3\u521d\u4ee5\u6765\uff0c\u4e2d\u56fd\u4f5c\u4e3a\u5bf9\u65b0\u5174\u7ecf\u6d4e\u4f53\u63d0\u4f9b\u5927\u91cf\u8d37\u6b3e\u7684\u4e3b\u8981\u8d37\u6b3e\u65b9\uff0c\u5f62\u6210\u4e86\u4e00\u79cd\u72ec\u7279\u7684\u8d37\u6b3e\u6743\u529b\uff1a\u501f\u6b3e\u4eba\u65e0\u6cd5\u5728\u83b7\u5f97\u7684\u8865\u8d34\u8d37\u6b3e\u4e0a\u8fdd\u7ea6\uff0c\u4f46\u4ecd\u53ef\u80fd\u9762\u4e34\u65e0\u6cd5\u63a7\u5236\u7684\u7a81\u7136\u7eed\u8d37\u8981\u6c42\u3002\u6211\u4eec\u4e3b\u5f20\uff0c\u8fd9\u79cd\u72ec\u7279\u7684\u7ed3\u6784\u2014\u2014\u53cc\u8fb9\u7eed\u8d37\u98ce\u9669\u800c\u65e0\u8fdd\u7ea6\u98ce\u9669\u2014\u2014\u4f1a\u7ea6\u675f\u501f\u6b3e\u56fd\u5728\u56fd\u9645\u5e02\u573a\u7684\u501f\u8d37\u884c\u4e3a\u3002\u5728\u4e00\u9879\u957f\u671f\u4e3b\u6743\u503a\u52a1\u5b9a\u91cf\u6a21\u578b\u4e2d\uff0c\u6211\u4eec\u8868\u660e\uff0c\u8fd9\u79cd\u6613\u53d1\u751f\u7eed\u8d37\u7684\u975e\u8fdd\u7ea6\u6027\u4e2d\u56fd\u8d37\u6b3e\u4f1a\u4f7f\u5e02\u573a\u503a\u52a1\u9762\u4e34\u7a00\u91ca\u98ce\u9669\uff1a\u653f\u5e9c\u53ef\u80fd\u9700\u8981\u5728\u5411\u4e2d\u56fd\u507f\u8fd8\u5230\u671f\u503a\u52a1\u65f6\u8f6c\u5411\u56fd\u9645\u8d37\u6b3e\u65b9\uff0c\u56e0\u6b64\u5728\u83b7\u5f97\u4e2d\u56fd\u8d44\u91d1\u6d41\u5165\u65f6\u4f1a\u9009\u62e9\u4ece\u79c1\u4eba\u5e02\u573a\u53bb\u6760\u6746\u3002\u6570\u636e\u4e2d\u5e02\u573a\u503a\u52a1\u548c\u503a\u5238\u6536\u76ca\u7387\u7684\u52a8\u6001\u4e0e\u8fd9\u79cd\u2018\u7ea6\u675f\u6548\u5e94\u2019\u4e00\u81f4\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u5229\u7528\u8be5\u6a21\u578b\u7814\u7a76\u4e86\u4e24\u79cd\u5730\u7f18\u653f\u6cbb\u60c5\u666f\uff1a\u4e00\u79cd\u662f\u2018\u96c6\u56e2\u5f62\u6210\u2019\u60c5\u666f\uff0c\u4e2d\u56fd\u4ee5\u2018\u5168\u6709\u6216\u5168\u65e0\u2019\u7684\u8d37\u6b3e\u6761\u4ef6\u8bf1\u5bfc\u501f\u6b3e\u56fd\u9000\u51fa\u56fd\u9645\u503a\u52a1\u5e02\u573a\uff1b\u53e6\u4e00\u79cd\u662f\u9762\u5bf9\u4e2d\u56fd\u8d44\u91d1\u7a81\u7136\u4e14\u6c38\u4e45\u6027\u64a4\u56de\u98ce\u9669\u4e0b\u7684\u6700\u4f18\u66b4\u9732\u7a0b\u5ea6\u95ee\u9898\u3002\u8fd9\u4e9b\u7ed3\u679c\u5171\u540c\u8868\u660e\uff0c\u4e2d\u56fd\u7684\u5b98\u65b9\u91d1\u878d\u6a21\u5f0f\u65e2\u80fd\u6539\u5584\u5e02\u573a\u501f\u8d37\u6761\u4ef6\uff0c\u53c8\u53ef\u80fd\u5728\u5730\u7f18\u653f\u6cbb\u8054\u76df\u53d8\u5316\u7684\u80cc\u666f\u4e0b\uff0c\u6210\u4e3a\u5168\u7403\u4e3b\u6743\u503a\u52a1\u4f53\u7cfb\u7684\u65b0\u4e0d\u7a33\u5b9a\u56e0\u7d20\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.3386/w35768", "journal": "NBER", "title": "Money and Power: Historical Lessons for Stablecoins and U.S. Dollar Dominance", "authors": ["Michael D. Bordo", "Carolyn Wilkins"], "author_details": [{"name": "Michael D. Bordo", "affiliations": []}, {"name": "Carolyn Wilkins", "affiliations": []}], "abstract": "This paper uses the history of private money to assess the conditions under which stablecoins could function safely at scale and what their growth may imply for U.S. monetary power. Historical systems of private money in the United Kingdom, the United States, Canada, Sweden, and Switzerland show that par circulation depended on institutional arrangements rather than payment technology. Drawing on the monetary history of private money, convertibility, and international currencies, the paper identifies five foundations for scalable private money: credible convertibility, high-quality and transparent backing, a uniform regulatory perimeter, par clearing infrastructure, and credible crisis management and loss allocation. Stablecoins may improve settlement speed, programmability, and cross-border access, but they do not remove these requirements. Applying this framework to contemporary stablecoins and the GENIUS Act, the paper finds that the Act addresses several of these foundations more fully than others, with crisis management and cross-border coordination less fully developed. Dollar stablecoins could extend the reach of dollar settlement, but historical experience reviewed here suggests that whether this strengthens the dollar system depends both on the institutional framework supporting stablecoins and on the deeper foundations of U.S. monetary dominance: confidence in U.S. institutions, fiscal capacity, monetary credibility, and the rule of law.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35768", "title_zh": "\u8d27\u5e01\u4e0e\u6743\u529b\uff1a\u7a33\u5b9a\u5e01\u548c\u7f8e\u5143\u4e3b\u5bfc\u5730\u4f4d\u7684\u5386\u53f2\u542f\u793a", "abstract_zh": "\u672c\u6587\u5229\u7528\u79c1\u4eba\u8d27\u5e01\u7684\u5386\u53f2\u6765\u8bc4\u4f30\u7a33\u5b9a\u5e01\u5728\u5927\u89c4\u6a21\u5b89\u5168\u8fd0\u884c\u6240\u9700\u7684\u6761\u4ef6\uff0c\u4ee5\u53ca\u5176\u53d1\u5c55\u53ef\u80fd\u5bf9\u7f8e\u56fd\u8d27\u5e01\u6743\u529b\u4ea7\u751f\u7684\u5f71\u54cd\u3002\u82f1\u56fd\u3001\u7f8e\u56fd\u3001\u52a0\u62ff\u5927\u3001\u745e\u5178\u548c\u745e\u58eb\u7684\u79c1\u4eba\u8d27\u5e01\u5386\u53f2\u8868\u660e\uff0c\u7b49\u503c\u6d41\u901a\u4f9d\u8d56\u4e8e\u5236\u5ea6\u5b89\u6392\uff0c\u800c\u975e\u652f\u4ed8\u6280\u672f\u3002\u57fa\u4e8e\u79c1\u4eba\u8d27\u5e01\u3001\u53ef\u5151\u6362\u6027\u4ee5\u53ca\u56fd\u9645\u8d27\u5e01\u7684\u8d27\u5e01\u53f2\uff0c\u672c\u6587\u8bc6\u522b\u51fa\u4e94\u9879\u53ef\u652f\u6301\u53ef\u6269\u5c55\u79c1\u4eba\u8d27\u5e01\u7684\u57fa\u7840\uff1a\u53ef\u4fe1\u7684\u53ef\u5151\u6362\u6027\u3001\u9ad8\u8d28\u91cf\u4e14\u900f\u660e\u7684\u652f\u6491\u3001\u7edf\u4e00\u7684\u76d1\u7ba1\u8fb9\u754c\u3001\u7b49\u503c\u6e05\u7b97\u57fa\u7840\u8bbe\u65bd\uff0c\u4ee5\u53ca\u53ef\u4fe1\u7684\u5371\u673a\u7ba1\u7406\u548c\u635f\u5931\u5206\u914d\u673a\u5236\u3002\u7a33\u5b9a\u5e01\u53ef\u80fd\u63d0\u5347\u7ed3\u7b97\u901f\u5ea6\u3001\u53ef\u7f16\u7a0b\u6027\u4ee5\u53ca\u8de8\u5883\u8bbf\u95ee\u80fd\u529b\uff0c\u4f46\u5e76\u4e0d\u514d\u9664\u8fd9\u4e9b\u8981\u6c42\u3002\u5c06\u8fd9\u4e00\u6846\u67b6\u5e94\u7528\u4e8e\u5f53\u524d\u7684\u7a33\u5b9a\u5e01\u548cGENIUS\u6cd5\u6848\uff0c\u672c\u6587\u53d1\u73b0\u8be5\u6cd5\u6848\u5728\u591a\u4e2a\u57fa\u7840\u65b9\u9762\u6709\u6240\u5b8c\u5584\uff0c\u4f46\u5728\u5371\u673a\u7ba1\u7406\u4e0e\u8de8\u5883\u534f\u8c03\u65b9\u9762\u4ecd\u4e0d\u5145\u5206\u3002\u7f8e\u5143\u7a33\u5b9a\u5e01\u53ef\u4ee5\u6269\u5c55\u7f8e\u5143\u7ed3\u7b97\u7684\u8303\u56f4\uff0c\u4f46\u672c\u6587\u56de\u987e\u7684\u5386\u53f2\u7ecf\u9a8c\u8868\u660e\uff0c\u8fd9\u79cd\u6269\u5c55\u662f\u5426\u80fd\u589e\u5f3a\u7f8e\u5143\u4f53\u7cfb\uff0c\u53d6\u51b3\u4e8e\u652f\u6301\u7a33\u5b9a\u5e01\u7684\u5236\u5ea6\u6846\u67b6\uff0c\u4ee5\u53ca\u66f4\u6df1\u5c42\u6b21\u7684\u7f8e\u56fd\u8d27\u5e01\u4e3b\u5bfc\u5730\u4f4d\u57fa\u7840\uff1a\u5bf9\u7f8e\u56fd\u673a\u6784\u7684\u4fe1\u5fc3\u3001\u8d22\u653f\u80fd\u529b\u3001\u8d27\u5e01\u4fe1\u8a89\u4ee5\u53ca\u6cd5\u6cbb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35769", "journal": "NBER", "title": "Diversification as a Process: Geographic Expansion and the Formation of National Insurers", "authors": ["Pawel Janas"], "author_details": [{"name": "Pawel Janas", "affiliations": []}], "abstract": "Large financial intermediaries are more stable than small ones, and the largest are also the most geographically diversified. Whether that breadth is a source of stability or a byproduct of scale is difficult to establish, since intermediaries diversify by growing large. I examine how the diversified intermediary is assembled, using a newly digitized firm-by-state panel of the near-universe of U.S. life insurers from 1888 to 1940, the largest nonbank institutional investors of the period. Over these decades, the number of insurers per state more than quadrupled and within-state concentration declined by half, yet a small number of geographically extensive insurers retained a stable share of national premiums. I decompose firm-level outcomes into the insurer\u2019s underwriting level and the composition of its book. Insurers entered new states before attaining scale, each entry constituting a small and favorably selected position with the convex payoff of a real option. The most successful decile of entries generated half of a cohort\u2019s premium. Expansion was costly on two margins: a broad insurer earned less per dollar of coverage and paid 15.1 percent more in claims than an equally large insurer writing in the same state and year. The pricing cost is attributable to the composition of a broad insurer\u2019s book, the claims cost to the insurer itself. A comparison across firms understates the claims cost, since the markets a broad insurer adds exhibit favorable claims experience of their own. Stability, by contrast, is attributable to scale, since breadth\u2019s advantages in volatility and survival vanish conditional on size. Risk pooling was bounded: approximately nine tenths of an insurer\u2019s loss-ratio variance was common to its markets. Diversification was the product of costly expansion, and the stability attributed to it is the scale that expansion produced.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35769", "title_zh": "\u591a\u5143\u5316\u4f5c\u4e3a\u8fc7\u7a0b\uff1a\u5730\u7406\u6269\u5f20\u4e0e\u56fd\u5bb6\u4fdd\u9669\u516c\u53f8\u7684\u5f62\u6210", "abstract_zh": "\u5927\u578b\u91d1\u878d\u4e2d\u4ecb\u673a\u6784\u6bd4\u5c0f\u578b\u673a\u6784\u66f4\u7a33\u5b9a\uff0c\u800c\u6700\u5927\u7684\u673a\u6784\u4e5f\u5177\u6709\u6700\u5e7f\u6cdb\u7684\u5730\u7406\u5206\u5e03\u3002\u8fd9\u79cd\u5e7f\u5ea6\u662f\u7a33\u5b9a\u6027\u6765\u6e90\uff0c\u8fd8\u662f\u89c4\u6a21\u6269\u5f20\u7684\u526f\u4ea7\u54c1\uff0c\u96be\u4ee5\u786e\u5b9a\uff0c\u56e0\u4e3a\u4e2d\u4ecb\u673a\u6784\u662f\u901a\u8fc7\u6269\u5927\u89c4\u6a21\u800c\u5b9e\u73b0\u591a\u5143\u5316\u7684\u3002\u672c\u6587\u5229\u7528\u4e00\u4e2a\u65b0\u6570\u5b57\u5316\u7684\u5dde\u7ea7\u516c\u53f8\u9762\u677f\u6570\u636e\uff0c\u6db5\u76d6\u4e861888\u5e74\u81f31940\u5e74\u95f4\u7f8e\u56fd\u51e0\u4e4e\u6240\u6709\u751f\u547d\u4fdd\u9669\u516c\u53f8\uff0c\u8fd9\u4e9b\u662f\u5f53\u65f6\u6700\u5927\u7684\u975e\u94f6\u884c\u578b\u673a\u6784\u6295\u8d44\u8005\u3002\u5728\u8fd9\u51e0\u5341\u5e74\u95f4\uff0c\u5404\u5dde\u7684\u4fdd\u9669\u516c\u53f8\u6570\u91cf\u589e\u957f\u4e86\u56db\u500d\u4ee5\u4e0a\uff0c\u800c\u5404\u5dde\u5185\u90e8\u7684\u96c6\u4e2d\u5ea6\u4e0b\u964d\u4e86\u4e00\u534a\uff0c\u4f46\u5c11\u6570\u51e0\u5bb6\u5730\u7406\u8303\u56f4\u5e7f\u6cdb\u7684\u4fdd\u9669\u516c\u53f8\u4ecd\u4fdd\u6301\u4e86\u7a33\u5b9a\u7684\u5168\u56fd\u4fdd\u8d39\u4efd\u989d\u3002\u672c\u6587\u5c06\u516c\u53f8\u5c42\u9762\u7684\u7ed3\u679c\u5206\u89e3\u4e3a\u4fdd\u9669\u516c\u53f8\u7684\u627f\u4fdd\u6c34\u5e73\u53ca\u5176\u4e1a\u52a1\u7ec4\u5408\u7684\u6784\u6210\u3002\u4fdd\u9669\u516c\u53f8\u8fdb\u5165\u65b0\u5dde\u65f6\u5c1a\u672a\u8fbe\u5230\u89c4\u6a21\uff0c\u6bcf\u6b21\u8fdb\u5165\u90fd\u6784\u6210\u4e00\u4e2a\u5c0f\u578b\u4e14\u7ecf\u8fc7\u4f18\u9009\u7684\u4ed3\u4f4d\uff0c\u5177\u6709\u5b9e\u7269\u671f\u6743\u7684\u51f8\u652f\u4ed8\u7279\u6027\u3002\u6700\u6210\u529f\u7684\u5341\u5206\u4e4b\u4e00\u7684\u8fdb\u5165\u884c\u4e3a\u4ea7\u751f\u4e86\u6574\u4e2a\u7fa4\u4f53\u4fdd\u8d39\u7684\u4e00\u534a\u3002\u6269\u5f20\u5b58\u5728\u4e24\u4e2a\u6210\u672c\uff1a\u5e7f\u57df\u4fdd\u9669\u516c\u53f8\u6bcf\u5355\u4f4d\u4fdd\u989d\u7684\u6536\u5165\u4f4e\u4e8e\u540c\u7b49\u89c4\u6a21\u7684\u4fdd\u9669\u516c\u53f8\uff0c\u4e14\u5728\u76f8\u540c\u5dde\u548c\u5e74\u4efd\u4e0b\uff0c\u5176\u8d54\u4ed8\u652f\u51fa\u9ad8\u51fa15.1%\u3002\u4ef7\u683c\u6210\u672c\u6e90\u4e8e\u5e7f\u57df\u4fdd\u9669\u516c\u53f8\u4e1a\u52a1\u7ec4\u5408\u7684\u6784\u6210\uff0c\u8d54\u4ed8\u6210\u672c\u5219\u6e90\u4e8e\u4fdd\u9669\u516c\u53f8\u81ea\u8eab\u3002\u8de8\u516c\u53f8\u6bd4\u8f83\u4f4e\u4f30\u4e86\u8d54\u4ed8\u6210\u672c\uff0c\u56e0\u4e3a\u5e7f\u57df\u4fdd\u9669\u516c\u53f8\u65b0\u589e\u7684\u5e02\u573a\u672c\u8eab\u5177\u6709\u826f\u597d\u7684\u8d54\u4ed8\u8bb0\u5f55\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u7a33\u5b9a\u6027\u6e90\u4e8e\u89c4\u6a21\uff0c\u56e0\u4e3a\u5f53\u89c4\u6a21\u6761\u4ef6\u6210\u7acb\u65f6\uff0c\u5730\u7406\u5e7f\u5ea6\u5728\u6ce2\u52a8\u6027\u548c\u751f\u5b58\u6027\u65b9\u9762\u7684\u4f18\u52bf\u6d88\u5931\u3002\u98ce\u9669\u5206\u644a\u662f\u6709\u9650\u7684\uff1a\u5927\u7ea6\u4e5d\u6210\u7684\u4fdd\u9669\u516c\u53f8\u635f\u5931\u6bd4\u7387\u65b9\u5dee\u662f\u5176\u5e02\u573a\u5171\u6709\u7684\u3002\u591a\u5143\u5316\u662f\u9ad8\u6210\u672c\u6269\u5f20\u7684\u7ed3\u679c\uff0c\u800c\u5f52\u56e0\u4e8e\u5176\u7684\u7a33\u5b9a\u6027\u5b9e\u9645\u4e0a\u662f\u6269\u5f20\u6240\u4ea7\u751f\u89c4\u6a21\u5e26\u6765\u7684\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.3386/w35770", "journal": "NBER", "title": "Advertising Claims, Pricing, and Customer Evidence", "authors": ["Joshua S. Gans"], "author_details": [{"name": "Joshua S. Gans", "affiliations": []}], "abstract": "Why might firms make different claims in advertising both with respect to themselves and to rivals? I study how claims direct consumers to different customer experiences, and how prices change the available evidence. Attributing successes to the advertiser requires a low price when its product is superior; attributing failures to the rival supports a higher price. Focussing on a single strategic advertiser, the model shows that the claim that attracts the most customers to a superior product never maximises profit. The optimal campaign raises advertiser profit but lowers consumer surplus relative to fully informed choice, and reduces total welfare whenever product reliabilities differ. When both firms choose claims and prices, competition can sustain a mix of positive and negative claims with price dispersion, restoring claims that a lone advertiser would reject. A rival's pricing response alone can make failure attribution optimal by weakening incentives to undercut. Allowing the rival to advertise can lower both prices and shift customers towards it if the incumbent retains its previous claim; allowing the incumbent to change its claim can eliminate this additional effect. Advertising, therefore, changes not only persuasion but also pricing incentives, making its market consequences different from its effects at fixed prices.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35770", "title_zh": "\u5e7f\u544a\u5ba3\u4f20\u3001\u5b9a\u4ef7\u4e0e\u987e\u5ba2\u8bc1\u636e", "abstract_zh": "\u4e3a\u4ec0\u4e48\u4f01\u4e1a\u4f1a\u5728\u5e7f\u544a\u4e2d\u5bf9\u81ea\u8eab\u548c\u7ade\u4e89\u5bf9\u624b\u505a\u51fa\u4e0d\u540c\u7684\u5ba3\u79f0\uff1f\u672c\u6587\u7814\u7a76\u4e86\u5e7f\u544a\u5ba3\u79f0\u5982\u4f55\u5f15\u5bfc\u6d88\u8d39\u8005\u4f53\u9a8c\u4e0d\u540c\u4ea7\u54c1\uff0c\u4ee5\u53ca\u4ef7\u683c\u5982\u4f55\u5f71\u54cd\u53ef\u83b7\u5f97\u7684\u8bc1\u636e\u3002\u5f53\u4ea7\u54c1\u66f4\u4f18\u8d8a\u65f6\uff0c\u5c06\u6210\u529f\u5f52\u56e0\u4e8e\u5e7f\u544a\u5546\u9700\u8981\u4e00\u4e2a\u8f83\u4f4e\u7684\u4ef7\u683c\uff1b\u5c06\u5931\u8d25\u5f52\u56e0\u4e8e\u7ade\u4e89\u5bf9\u624b\u5219\u652f\u6301\u66f4\u9ad8\u7684\u4ef7\u683c\u3002\u5728\u5355\u4e00\u6218\u7565\u5e7f\u544a\u5546\u7684\u6a21\u578b\u4e2d\uff0c\u80fd\u591f\u5438\u5f15\u6700\u591a\u987e\u5ba2\u7684\u5ba3\u79f0\u5bf9\u4e8e\u4f18\u8d8a\u4ea7\u54c1\u800c\u8a00\uff0c\u5e76\u4e0d\u4f1a\u6700\u5927\u5316\u5229\u6da6\u3002\u6700\u4f18\u5e7f\u544a\u6d3b\u52a8\u867d\u7136\u63d0\u5347\u4e86\u5e7f\u544a\u5546\u7684\u5229\u6da6\uff0c\u4f46\u76f8\u5bf9\u4e8e\u5b8c\u5168\u77e5\u60c5\u9009\u62e9\uff0c\u964d\u4f4e\u4e86\u6d88\u8d39\u8005\u5269\u4f59\uff0c\u5e76\u4e14\u5728\u4ea7\u54c1\u53ef\u9760\u6027\u5b58\u5728\u5dee\u5f02\u65f6\uff0c\u4f1a\u964d\u4f4e\u603b\u798f\u5229\u3002\u5f53\u4e24\u5bb6\u516c\u53f8\u90fd\u9009\u62e9\u5ba3\u79f0\u548c\u5b9a\u4ef7\u65f6\uff0c\u7ade\u4e89\u53ef\u4ee5\u7ef4\u6301\u6b63\u8d1f\u5ba3\u79f0\u5e76\u4f34\u968f\u4ef7\u683c\u5dee\u5f02\u7684\u6df7\u5408\u72b6\u6001\uff0c\u4ece\u800c\u6062\u590d\u5355\u4e2a\u5e7f\u544a\u5546\u6240\u62d2\u7edd\u7684\u5ba3\u79f0\u3002\u4ec5\u7ade\u4e89\u5bf9\u624b\u7684\u5b9a\u4ef7\u53cd\u5e94\u5373\u53ef\u4f7f\u5931\u8d25\u5f52\u56e0\u6210\u4e3a\u6700\u4f18\u9009\u62e9\uff0c\u901a\u8fc7\u524a\u5f31\u964d\u4ef7\u7684\u52a8\u673a\u3002\u5982\u679c\u73b0\u6709\u4f01\u4e1a\u4fdd\u7559\u5176\u539f\u6709\u5ba3\u79f0\uff0c\u5141\u8bb8\u7ade\u4e89\u5bf9\u624b\u8fdb\u884c\u5e7f\u544a\u5ba3\u4f20\uff0c\u5c06\u5bfc\u81f4\u4ef7\u683c\u4e0b\u964d\u5e76\u4f7f\u987e\u5ba2\u8f6c\u5411\u7ade\u4e89\u5bf9\u624b\uff1b\u800c\u5141\u8bb8\u73b0\u6709\u4f01\u4e1a\u66f4\u6539\u5176\u5ba3\u79f0\uff0c\u5219\u53ef\u4ee5\u6d88\u9664\u8fd9\u4e00\u989d\u5916\u6548\u5e94\u3002\u56e0\u6b64\uff0c\u5e7f\u544a\u4e0d\u4ec5\u6539\u53d8\u4e86\u8bf4\u670d\u529b\uff0c\u4e5f\u6539\u53d8\u4e86\u5b9a\u4ef7\u6fc0\u52b1\uff0c\u4f7f\u5176\u5e02\u573a\u540e\u679c\u4e0e\u5728\u56fa\u5b9a\u4ef7\u683c\u4e0b\u7684\u6548\u679c\u4e0d\u540c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35771", "journal": "NBER", "title": "Integration Without Decentralization: The Financial Geography of U.S. Life Insurance, 1880\u20131940", "authors": ["Pawel Janas"], "author_details": [{"name": "Pawel Janas", "affiliations": []}], "abstract": "This paper studies the transformation of American life insurance, the largest contractual savings institution in the United States before Social Security. As the market for insurance became national, did control over the savings it collected disperse with it? Using a newly digitized annual firm-by-state panel of premiums and losses covering nearly every U.S. life insurer from 1888 to 1940, I distinguish the geography of collection from the geography of control: where premiums were paid, and where the firms receiving them were domiciled. The industry was remade over these six decades. Real premium income rose more than twentyfold, the number of active insurers grew sixfold, incorporation shifted decisively from the Northeast toward the Midwest and South, and within-state concentration fell by nearly half. Control was rearranged, not dispersed. Chartering domestic insurers raised local retention almost entirely at the extensive margin. Across regions, this closed a large gap, as the Northeast retained nearly eleven times as much of its premium as the South in the 1890s and only twice as much by the 1930s, with nine-tenths of the convergence coming from Southern states acquiring domestic sectors where they had none. The national total held: firms domiciled where premium was raised collected just under a quarter of it in the 1890s and just over a fifth in the 1930s, even as household participation converged steadily across states. Legal permission to operate nationally sufficed to integrate the market in which insurance was sold, but not to disperse control over the investable cash it collected.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35771", "title_zh": "\u6ca1\u6709\u53bb\u4e2d\u5fc3\u5316\u7684\u6574\u5408\uff1a1880\u5e74\u81f31940\u5e74\u7f8e\u56fd\u4eba\u5bff\u4fdd\u9669\u7684\u91d1\u878d\u5730\u7406", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u7f8e\u56fd\u4eba\u5bff\u4fdd\u9669\u4e1a\u7684\u6f14\u53d8\uff0c\u8fd9\u662f\u5728\u793e\u4f1a\u4fdd\u969c\u5236\u5ea6\u51fa\u73b0\u4e4b\u524d\u7f8e\u56fd\u6700\u5927\u7684\u5951\u7ea6\u50a8\u84c4\u673a\u6784\u3002\u968f\u7740\u4fdd\u9669\u5e02\u573a\u53d8\u5f97\u5168\u56fd\u5316\uff0c\u6536\u96c6\u5230\u7684\u50a8\u84c4\u63a7\u5236\u6743\u662f\u5426\u4e5f\u968f\u4e4b\u5206\u6563\uff1f\u5229\u7528\u4e00\u4efd\u8986\u76d61888\u5e74\u81f31940\u5e74\u95f4\u51e0\u4e4e\u6240\u6709\u7f8e\u56fd\u4eba\u5bff\u4fdd\u9669\u516c\u53f8\u7684\u5e74\u5ea6\u5dde\u7ea7\u516c\u53f8\u9762\u677f\u6570\u636e\uff0c\u8be5\u6570\u636e\u5305\u542b\u4e86\u4fdd\u8d39\u548c\u8d54\u4ed8\u4fe1\u606f\uff0c\u6211\u533a\u5206\u4e86\u4fdd\u8d39\u6536\u96c6\u7684\u5730\u7406\u5206\u5e03\u4e0e\u63a7\u5236\u6743\u7684\u5730\u7406\u5206\u5e03\uff1a\u4fdd\u8d39\u652f\u4ed8\u5730\u4e0e\u4fdd\u9669\u516c\u53f8\u6ce8\u518c\u5730\u4e4b\u95f4\u7684\u5dee\u5f02\u3002\u5728\u8fd9\u4e00\u516d\u5341\u5e74\u95f4\uff0c\u884c\u4e1a\u53d1\u751f\u4e86\u6df1\u523b\u53d8\u9769\u3002\u5b9e\u9645\u4fdd\u8d39\u6536\u5165\u589e\u957f\u4e86\u4e8c\u5341\u591a\u500d\uff0c\u6d3b\u8dc3\u4fdd\u9669\u516c\u53f8\u6570\u91cf\u589e\u957f\u4e86\u516d\u500d\uff0c\u516c\u53f8\u6ce8\u518c\u5730\u4ece\u4e1c\u5317\u90e8\u663e\u8457\u5411\u4e2d\u897f\u90e8\u548c\u5357\u90e8\u8f6c\u79fb\uff0c\u5404\u5dde\u5185\u90e8\u7684\u96c6\u4e2d\u5ea6\u4e0b\u964d\u4e86\u8fd1\u4e00\u534a\u3002\u63a7\u5236\u6743\u88ab\u91cd\u65b0\u914d\u7f6e\uff0c\u800c\u975e\u5206\u6563\u3002\u5141\u8bb8\u5728\u56fd\u5185\u8fd0\u8425\u7684\u516c\u53f8\u6ce8\u518c\u663e\u8457\u63d0\u5347\u4e86\u672c\u5730\u4fdd\u8d39\u7559\u5b58\uff0c\u5c24\u5176\u662f\u5728\u5e7f\u6cdb\u6269\u5c55\u7684\u5c42\u9762\u3002\u5728\u5404\u5730\u533a\uff0c\u8fd9\u4e00\u53d8\u5316\u7f29\u5c0f\u4e86\u5de8\u5927\u5dee\u8ddd\uff1a1890\u5e74\u4ee3\uff0c\u4e1c\u5317\u90e8\u4fdd\u7559\u7684\u4fdd\u8d39\u51e0\u4e4e\u662f\u5357\u90e8\u7684\u5341\u4e00\u500d\uff0c\u52301930\u5e74\u4ee3\u4ec5\u4fdd\u7559\u4e86\u4e24\u500d\uff0c\u5176\u4e2d\u4e5d\u6210\u7684\u6536\u655b\u6765\u81ea\u5357\u90e8\u5730\u533a\u83b7\u5f97\u4e86\u6b64\u524d\u6ca1\u6709\u7684\u56fd\u5185\u4fdd\u9669\u90e8\u95e8\u3002\u5168\u56fd\u603b\u548c\u4fdd\u6301\u4e0d\u53d8\uff1a\u57281890\u5e74\u4ee3\uff0c\u6ce8\u518c\u5730\u4e0e\u4fdd\u8d39\u6765\u6e90\u5730\u4e00\u81f4\u7684\u516c\u53f8\u4ec5\u6536\u96c6\u4e86\u7ea6\u56db\u5206\u4e4b\u4e00\u7684\u4fdd\u8d39\uff0c\u52301930\u5e74\u4ee3\u5219\u4e0a\u5347\u81f3\u7565\u8d85\u8fc7\u4e94\u5206\u4e4b\u4e00\uff0c\u5c3d\u7ba1\u5bb6\u5ead\u53c2\u4e0e\u5ea6\u5728\u5404\u5dde\u4e4b\u95f4\u7a33\u6b65\u8d8b\u540c\u3002\u83b7\u5f97\u5728\u5168\u56fd\u8303\u56f4\u5185\u8fd0\u8425\u7684\u6cd5\u5f8b\u8bb8\u53ef\u8db3\u4ee5\u6574\u5408\u4fdd\u9669\u9500\u552e\u5e02\u573a\uff0c\u4f46\u4e0d\u8db3\u4ee5\u4f7f\u6536\u96c6\u5230\u7684\u53ef\u6295\u8d44\u8d44\u91d1\u7684\u63a7\u5236\u6743\u5206\u6563\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35772", "journal": "NBER", "title": "Cooler Laws, Safer Workers: Evaluating California\u2019s Heat Standard and Injury Reduction", "authors": ["Olesya Fomenko", "Melissa McInerney", "Sebastian Negrusa"], "author_details": [{"name": "Olesya Fomenko", "affiliations": []}, {"name": "Melissa McInerney", "affiliations": []}, {"name": "Sebastian Negrusa", "affiliations": []}], "abstract": "A growing body of research shows that excessive heat increases the frequency of heat-related injuries at work. While interest in mitigating occupational risks from excessive heat is high, there is little evidence on whether legislation targeting heat exposure can reduce such injuries. Using a triple-differences approach and administrative data from workers\u2019 compensation systems, we evaluate California\u2019s heat standard \u2013 adopted in 2005 - and find that the standard substantially reduces the frequency of work injuries in the construction, agriculture, and transportation industries. The effects increase with outside temperatures and are larger among younger workers. Our findings have clear implications for workplace safety and contribute to ongoing policy debates.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35772", "title_zh": "\u66f4\u4e25\u683c\u7684\u6cd5\u89c4\uff0c\u66f4\u5b89\u5168\u7684\u5de5\u4eba\uff1a\u8bc4\u4f30\u52a0\u5229\u798f\u5c3c\u4e9a\u5dde\u7684\u9ad8\u6e29\u6807\u51c6\u4e0e\u5de5\u4f24\u51cf\u5c11", "abstract_zh": "\u8d8a\u6765\u8d8a\u591a\u7684\u7814\u7a76\u8868\u660e\uff0c\u8fc7\u9ad8\u7684\u6e29\u5ea6\u4f1a\u589e\u52a0\u5de5\u4f5c\u4e2d\u4e0e\u70ed\u76f8\u5173\u7684\u4f24\u5bb3\u53d1\u751f\u9891\u7387\u3002\u5c3d\u7ba1\u4eba\u4eec\u5bf9\u51cf\u8f7b\u804c\u4e1a\u6d3b\u52a8\u4e2d\u9ad8\u6e29\u5e26\u6765\u7684\u98ce\u9669\u8868\u73b0\u51fa\u9ad8\u5ea6\u5174\u8da3\uff0c\u4f46\u5173\u4e8e\u9488\u5bf9\u70ed\u66b4\u9732\u7acb\u6cd5\u662f\u5426\u80fd\u51cf\u5c11\u6b64\u7c7b\u4f24\u5bb3\u7684\u8bc1\u636e\u5374\u5341\u5206\u6709\u9650\u3002\u6211\u4eec\u91c7\u7528\u4e09\u5dee\u5206\u65b9\u6cd5\uff0c\u5e76\u5229\u7528\u5de5\u4eba\u8d54\u507f\u7cfb\u7edf\u7684\u884c\u653f\u6570\u636e\uff0c\u8bc4\u4f30\u4e862005\u5e74\u52a0\u5229\u798f\u5c3c\u4e9a\u5dde\u5b9e\u65bd\u7684\u9ad8\u6e29\u6807\u51c6\uff0c\u53d1\u73b0\u8be5\u6807\u51c6\u663e\u8457\u964d\u4f4e\u4e86\u5efa\u7b51\u3001\u519c\u4e1a\u548c\u8fd0\u8f93\u884c\u4e1a\u7684\u5de5\u4f5c\u4f24\u5bb3\u9891\u7387\u3002\u8fd9\u79cd\u6548\u679c\u968f\u7740\u5916\u754c\u6e29\u5ea6\u7684\u5347\u9ad8\u800c\u589e\u5f3a\uff0c\u4e14\u5728\u5e74\u8f7b\u5de5\u4eba\u4e2d\u66f4\u4e3a\u660e\u663e\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u5bf9\u5de5\u4f5c\u573a\u6240\u5b89\u5168\u5177\u6709\u660e\u786e\u610f\u4e49\uff0c\u5e76\u4e3a\u5f53\u524d\u7684\u653f\u7b56\u8fa9\u8bba\u63d0\u4f9b\u4e86\u652f\u6301\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35773", "journal": "NBER", "title": "Compound Delay: The Causes and Consequences of Later Grandmotherhood", "authors": ["Dora L. Costa", "Matthew E. Kahn"], "author_details": [{"name": "Dora L. Costa", "affiliations": []}, {"name": "Matthew E. Kahn", "affiliations": []}], "abstract": "We show how fertility delays compound across generations to raise age at first grandmotherhood. Under the 1960 first-birth schedule median grandmotherhood came at 44. Under the 2024 schedule it is 57, cutting the healthy years with grandchildren from 28 to 15. Longer life does not make up the loss of years when the grandmother is healthy enough to supply money and care. Delay is most pronounced among the college-educated, with reproductive-control access accounting for over half the fall in grandmotherhood by age 55 among White college graduates. When a daughter times her first birth to maximize her own payoff, the loss her choice imposes on her mother is external to her calculation. We call this the Rotten Adult Kid Problem. Delay raises both the price of a grandmother's care and wealth per grandchild.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35773", "title_zh": "\u5ef6\u8fdf\u751f\u80b2\uff1a\u7956\u6bcd\u751f\u80b2\u63a8\u8fdf\u7684\u539f\u56e0\u4e0e\u540e\u679c", "abstract_zh": "\u6211\u4eec\u5c55\u793a\u4e86\u751f\u80b2\u63a8\u8fdf\u5982\u4f55\u5728\u4ee3\u9645\u95f4\u7d2f\u79ef\uff0c\u5bfc\u81f4\u9996\u6b21\u7956\u6bcd\u751f\u80b2\u5e74\u9f84\u4e0a\u5347\u3002\u57281960\u5e74\u7684\u521d\u751f\u65f6\u95f4\u8868\u4e0b\uff0c\u7956\u6bcd\u751f\u80b2\u7684\u4e2d\u4f4d\u5e74\u9f84\u4e3a44\u5c81\uff1b\u800c\u57282024\u5e74\u7684\u751f\u80b2\u65f6\u95f4\u8868\u4e0b\uff0c\u8fd9\u4e00\u5e74\u9f84\u4e0a\u5347\u81f357\u5c81\uff0c\u4f7f\u5f97\u7956\u6bcd\u5065\u5eb7\u53c2\u4e0e\u629a\u517b\u5b59\u8f88\u7684\u5e74\u9650\u4ece28\u5e74\u51cf\u5c11\u523015\u5e74\u3002\u5bff\u547d\u7684\u5ef6\u957f\u65e0\u6cd5\u5f25\u8865\u7956\u6bcd\u5728\u5065\u5eb7\u72b6\u6001\u4e0b\u63d0\u4f9b\u8d44\u91d1\u548c\u7167\u6599\u7684\u5e74\u6570\u51cf\u5c11\u3002\u751f\u80b2\u63a8\u8fdf\u5728\u53d7\u8fc7\u5927\u5b66\u6559\u80b2\u4eba\u7fa4\u4e2d\u5c24\u4e3a\u663e\u8457\uff0c\u5176\u4e2d\u751f\u6b96\u63a7\u5236\u6743\u7684\u83b7\u5f97\u89e3\u91ca\u4e86\u767d\u4eba\u5927\u5b66\u6bd5\u4e1a\u751f\u572855\u5c81\u65f6\u7956\u6bcd\u751f\u80b2\u5e74\u9f84\u4e0b\u964d\u8d85\u8fc7\u4e00\u534a\u3002\u5f53\u5973\u513f\u81ea\u4e3b\u9009\u62e9\u9996\u6b21\u751f\u80b2\u65f6\u95f4\u4ee5\u6700\u5927\u5316\u81ea\u8eab\u6536\u76ca\u65f6\uff0c\u5979\u5bf9\u6bcd\u4eb2\u9020\u6210\u7684\u635f\u5931\u5e76\u672a\u7eb3\u5165\u5176\u51b3\u7b56\u8003\u91cf\u3002\u6211\u4eec\u79f0\u8fd9\u79cd\u73b0\u8c61\u4e3a\u2018\u7cdf\u7cd5\u7684\u6210\u5e74\u5b50\u5973\u95ee\u9898\u2019\u3002\u751f\u80b2\u63a8\u8fdf\u4e0d\u4ec5\u63d0\u9ad8\u4e86\u7956\u6bcd\u63d0\u4f9b\u7167\u6599\u7684\u6210\u672c\uff0c\u4e5f\u964d\u4f4e\u4e86\u6bcf\u4e2a\u5b59\u8f88\u7684\u8d22\u5bcc\u6c34\u5e73\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35774", "journal": "NBER", "title": "The Returns to International Migration in a Free Mobility Setting: Evidence from Austria and Germany", "authors": ["Andrea Weber", "David Card", "Wolfgang Dauth", "Wolfgang Frimmel", "Julia Schmieder", "Rudolf Winter-Ebmer"], "author_details": [{"name": "Andrea Weber", "affiliations": []}, {"name": "David Card", "affiliations": []}, {"name": "Wolfgang Dauth", "affiliations": []}, {"name": "Wolfgang Frimmel", "affiliations": []}, {"name": "Julia Schmieder", "affiliations": []}, {"name": "Rudolf Winter-Ebmer", "affiliations": []}], "abstract": "How big are the gains to international migration? How do they vary across migrants? We study these questions using linked administrative data for Austria and Germany, focusing on migrants who were steadily employed 2-4 years before their move and using their previous co-workers as a comparison group for a difference-in-differences design. We combine data from the origin and destination countries for 5 years after the move, allowing us to assess the gains for those who remain in the destination and those who return. On average, migrants from Austria to Germany experience an immediate and persistent rise of around 13% in their daily wage relative to their matched co-workers, while migrants from Germany to Austria gain about 4%. The higher returns for Austrians are mainly driven by higher average wages in Germany, rather than by differential selection of migrants. Consistent with a dynamic learning model, the returns to migration are largest for migrants who remain in the destination country, smaller for those who return after 1-4 years, and zero or even slightly negative for those who return in less than a year. They are also larger for migrants who follow established cross-border networks between workplaces. To help interpret our findings we conduct a parallel analysis of domestic migrants who move to a larger city (Vienna or one of the 5 largest cities in Germany). \u201cBig city\u201d movers experience gains in wages of about 5% for Austrians and 10% for Germans. Again the gains are largest for those who remain in the destination city, with smaller effects for those who move on.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35774", "title_zh": "\u5728\u81ea\u7531\u6d41\u52a8\u73af\u5883\u4e0b\u7684\u56fd\u9645\u79fb\u6c11\u6536\u76ca\uff1a\u6765\u81ea\u5965\u5730\u5229\u548c\u5fb7\u56fd\u7684\u8bc1\u636e", "abstract_zh": "\u56fd\u9645\u79fb\u6c11\u5e26\u6765\u7684\u6536\u76ca\u6709\u591a\u5927\uff1f\u8fd9\u4e9b\u6536\u76ca\u5728\u4e0d\u540c\u79fb\u6c11\u7fa4\u4f53\u4e2d\u5982\u4f55\u5206\u5e03\uff1f\u6211\u4eec\u5229\u7528\u5965\u5730\u5229\u548c\u5fb7\u56fd\u7684\u8054\u63a5\u884c\u653f\u6570\u636e\uff0c\u7814\u7a76\u8fd9\u4e00\u95ee\u9898\uff0c\u91cd\u70b9\u5173\u6ce8\u5728\u8fc1\u5f99\u524d\u4e24\u5e74\u81f3\u56db\u5e74\u671f\u95f4\u6301\u7eed\u5c31\u4e1a\u7684\u79fb\u6c11\uff0c\u5e76\u4ee5\u4ed6\u4eec\u7684\u524d\u540c\u4e8b\u4f5c\u4e3a\u5bf9\u7167\u7ec4\uff0c\u91c7\u7528\u5dee\u5206-\u5dee\u5f02\u8bbe\u8ba1\u8fdb\u884c\u5206\u6790\u3002\u6211\u4eec\u7ed3\u5408\u539f\u7c4d\u56fd\u548c\u76ee\u7684\u5730\u56fd\u5728\u8fc1\u5f99\u540e\u4e94\u5e74\u5185\u7684\u6570\u636e\uff0c\u8bc4\u4f30\u90a3\u4e9b\u7559\u5728\u76ee\u7684\u5730\u56fd\u5bb6\u4ee5\u53ca\u8fd4\u56de\u539f\u7c4d\u56fd\u7684\u79fb\u6c11\u7684\u6536\u76ca\u60c5\u51b5\u3002\u603b\u4f53\u800c\u8a00\uff0c\u4ece\u5965\u5730\u5229\u8fc1\u79fb\u5230\u5fb7\u56fd\u7684\u79fb\u6c11\uff0c\u5176\u65e5\u85aa\u76f8\u5bf9\u4e8e\u5339\u914d\u7684\u524d\u540c\u4e8b\u5e73\u5747\u4e0a\u5347\u7ea613%\uff1b\u800c\u4ece\u5fb7\u56fd\u8fc1\u79fb\u5230\u5965\u5730\u5229\u7684\u79fb\u6c11\u5219\u83b7\u5f97\u7ea64%\u7684\u6536\u76ca\u3002\u5965\u5730\u5229\u79fb\u6c11\u83b7\u5f97\u66f4\u9ad8\u6536\u76ca\u7684\u4e3b\u8981\u539f\u56e0\u662f\u5fb7\u56fd\u7684\u5e73\u5747\u5de5\u8d44\u6c34\u5e73\u66f4\u9ad8\uff0c\u800c\u975e\u79fb\u6c11\u9009\u62e9\u4e0a\u7684\u5dee\u5f02\u3002\u8fd9\u4e0e\u52a8\u6001\u5b66\u4e60\u6a21\u578b\u7684\u9884\u6d4b\u4e00\u81f4\uff1a\u7559\u5728\u76ee\u7684\u5730\u56fd\u5bb6\u7684\u79fb\u6c11\u83b7\u5f97\u6700\u5927\u7684\u6536\u76ca\uff0c\u8fd4\u56de\u76ee\u7684\u5730\u56fd\u5bb61\u81f34\u5e74\u540e\u7684\u6536\u76ca\u8f83\u5c0f\uff0c\u800c\u8fd4\u56de\u65f6\u95f4\u5c11\u4e8e\u4e00\u5e74\u7684\u79fb\u6c11\u6536\u76ca\u4e3a\u96f6\u751a\u81f3\u4e3a\u8d1f\u3002\u6b64\u5916\uff0c\u90a3\u4e9b\u6cbf\u7740\u5df2\u5efa\u7acb\u7684\u8de8\u5883\u5de5\u4f5c\u7f51\u7edc\u8fc1\u79fb\u7684\u79fb\u6c11\u83b7\u5f97\u66f4\u5927\u7684\u6536\u76ca\u3002\u4e3a\u4e86\u66f4\u597d\u5730\u89e3\u91ca\u6211\u4eec\u7684\u53d1\u73b0\uff0c\u6211\u4eec\u8fd8\u5bf9\u56fd\u5185\u79fb\u6c11\uff08\u8fc1\u79fb\u5230\u7ef4\u4e5f\u7eb3\u6216\u5fb7\u56fd\u4e94\u5927\u57ce\u5e02\u4e4b\u4e00\uff09\u8fdb\u884c\u4e86\u5e73\u884c\u5206\u6790\u3002\u8fd9\u4e9b\u201c\u5927\u57ce\u5e02\u201d\u79fb\u6c11\u7684\u6536\u76ca\u7ea6\u4e3a\uff1a\u5965\u5730\u5229\u79fb\u6c11\u83b7\u5f975%\u7684\u5de5\u8d44\u63d0\u5347\uff0c\u5fb7\u56fd\u79fb\u6c11\u83b7\u5f9710%\u7684\u5de5\u8d44\u63d0\u5347\u3002\u540c\u6837\uff0c\u7559\u5728\u76ee\u7684\u5730\u57ce\u5e02\u7684\u79fb\u6c11\u6536\u76ca\u6700\u5927\uff0c\u800c\u90a3\u4e9b\u5728\u8fc1\u79fb\u540e\u518d\u6b21\u8fc1\u79fb\u7684\u79fb\u6c11\u6536\u76ca\u5219\u8f83\u5c0f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.3386/w35775", "journal": "NBER", "title": "When Tax Shields Shrink: Interest Deductibility Limitations and Corporate Innovation", "authors": ["Xinru Chen", "Mara Faccio", "Stefano Manfredonia", "Jin Xu"], "author_details": [{"name": "Xinru Chen", "affiliations": []}, {"name": "Mara Faccio", "affiliations": []}, {"name": "Stefano Manfredonia", "affiliations": []}, {"name": "Jin Xu", "affiliations": []}], "abstract": "We investigate how limiting interest deductibility under the 2017 TCJA shapes corporate innovation. Using alternative identification strategies, we show that, relative to unaffected firms, affected firms experience significant declines in patenting and narrow the technological scope of their patent portfolios. This contraction is concentrated in exploitative patents, the type of innovation most naturally supported by debt financing. By weakening firms\u2019 ability to finance innovation with long-term debt, interest limitations reveal a novel channel linking taxation to innovation, with the debt tax shield serving as an implicit subsidy. Cross-country evidence from the staggered implementation of interest limitation rules confirms negative effects.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35775", "title_zh": "\u5f53\u7a0e\u6536\u62b5\u514d\u51cf\u5c11\u65f6\uff1a\u5229\u606f\u62b5\u6263\u9650\u5236\u5bf9\u4f01\u4e1a\u521b\u65b0\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e862017\u5e74\u300a\u7a0e\u6cd5\u6539\u9769\u6cd5\u6848\u300b\u4e2d\u9650\u5236\u5229\u606f\u62b5\u6263\u5bf9\u4f01\u4e1a\u53d1\u5c55\u521b\u65b0\u7684\u5f71\u54cd\u3002\u901a\u8fc7\u91c7\u7528\u591a\u79cd\u8bc6\u522b\u7b56\u7565\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u4e0e\u672a\u53d7\u5f71\u54cd\u7684\u4f01\u4e1a\u76f8\u6bd4\uff0c\u53d7\u5230\u9650\u5236\u7684\u4f01\u4e1a\u5728\u4e13\u5229\u7533\u8bf7\u6570\u91cf\u4e0a\u663e\u8457\u4e0b\u964d\uff0c\u5e76\u4e14\u5176\u4e13\u5229\u7ec4\u5408\u7684\u6280\u672f\u8303\u56f4\u660e\u663e\u7f29\u5c0f\u3002\u8fd9\u79cd\u6536\u7f29\u73b0\u8c61\u4e3b\u8981\u96c6\u4e2d\u5728\u5229\u7528\u6027\u4e13\u5229\uff0c\u8fd9\u7c7b\u521b\u65b0\u6700\u81ea\u7136\u5730\u4f9d\u8d56\u4e8e\u503a\u52a1\u878d\u8d44\u3002\u901a\u8fc7\u524a\u5f31\u4f01\u4e1a\u5229\u7528\u957f\u671f\u503a\u52a1\u878d\u8d44\u521b\u65b0\u7684\u80fd\u529b\uff0c\u5229\u606f\u9650\u5236\u63ed\u793a\u4e86\u4e00\u4e2a\u5c06\u7a0e\u6536\u653f\u7b56\u4e0e\u521b\u65b0\u8054\u7cfb\u8d77\u6765\u7684\u65b0\u6e20\u9053\uff0c\u503a\u52a1\u7a0e\u6536\u62b5\u514d\u5728\u6b64\u5145\u5f53\u4e86\u9690\u6027\u8865\u8d34\u3002\u6765\u81ea\u4e0d\u540c\u56fd\u5bb6\u5b9e\u65bd\u5229\u606f\u9650\u5236\u89c4\u5219\u5206\u9636\u6bb5\u5b9e\u65bd\u7684\u8de8\u56fd\u8bc1\u636e\u4e5f\u8bc1\u5b9e\u4e86\u5176\u8d1f\u9762\u6548\u5e94\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.3386/w35776", "journal": "NBER", "title": "Can Early Exposure to the Teaching Profession Increase Teacher Supply and Diversity? New Evidence on the Teacher Pipeline", "authors": ["Danielle Sanderson Edwards", "Matthew A. Kraft"], "author_details": [{"name": "Danielle Sanderson Edwards", "affiliations": []}, {"name": "Matthew A. Kraft", "affiliations": []}], "abstract": "We examine whether early exposure to the teaching career has the potential to expand the size and diversity of new teacher supply. Exploiting the staggered expansion of high school education courses across Texas, we find little evidence that these courses increased new teacher supply or diversity despite course takers being substantially more diverse than the teacher workforce. High school education course takers who become teachers are similarly effective and more likely to be retained than their peers. Most course takers drop out of the teacher pipeline prior to college enrollment where racial gaps in 4-year college going serve as major barriers. Our findings suggest that early exposure without support to increase college going is unlikely to increase teacher supply or diversity.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35776", "title_zh": "\u65e9\u671f\u63a5\u89e6\u6559\u5e08\u804c\u4e1a\u662f\u5426\u80fd\u6269\u5927\u6559\u5e08\u4f9b\u7ed9\u548c\u591a\u6837\u6027\uff1f\u5173\u4e8e\u6559\u5e08\u57f9\u517b\u7ba1\u9053\u7684\u65b0\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u8003\u5bdf\u4e86\u65e9\u671f\u63a5\u89e6\u6559\u5e08\u804c\u4e1a\u662f\u5426\u6709\u53ef\u80fd\u6269\u5927\u65b0\u6559\u5e08\u7684\u4f9b\u7ed9\u548c\u591a\u6837\u6027\u3002\u5229\u7528\u5fb7\u514b\u8428\u65af\u5dde\u9ad8\u4e2d\u6559\u80b2\u8bfe\u7a0b\u5206\u9636\u6bb5\u6269\u5c55\u7684\u81ea\u7136\u5b9e\u9a8c\uff0c\u6211\u4eec\u53d1\u73b0\u8fd9\u4e9b\u8bfe\u7a0b\u5e76\u672a\u663e\u8457\u589e\u52a0\u65b0\u6559\u5e08\u7684\u4f9b\u7ed9\u6216\u591a\u6837\u6027\uff0c\u5c3d\u7ba1\u8bfe\u7a0b\u53c2\u4e0e\u8005\u6bd4\u6559\u5e08\u961f\u4f0d\u66f4\u52a0\u591a\u5143\u5316\u3002\u6700\u7ec8\u6210\u4e3a\u6559\u5e08\u7684\u9ad8\u4e2d\u6559\u80b2\u8bfe\u7a0b\u53c2\u4e0e\u8005\u5728\u6559\u5b66\u6548\u679c\u4e0a\u4e0e\u540c\u9f84\u4eba\u76f8\u5f53\uff0c\u5e76\u4e14\u66f4\u6709\u53ef\u80fd\u88ab\u4fdd\u7559\u3002\u7136\u800c\uff0c\u5927\u591a\u6570\u8bfe\u7a0b\u53c2\u4e0e\u8005\u5728\u8fdb\u5165\u5927\u5b66\u4e4b\u524d\u5c31\u9000\u51fa\u4e86\u6559\u5e08\u57f9\u517b\u7ba1\u9053\uff0c\u800c\u56db\u5e74\u5236\u5927\u5b66\u5165\u5b66\u4e2d\u7684\u79cd\u65cf\u5dee\u8ddd\u662f\u4e3b\u8981\u969c\u788d\u3002\u6211\u4eec\u7684\u53d1\u73b0\u8868\u660e\uff0c\u4ec5\u901a\u8fc7\u65e9\u671f\u63a5\u89e6\u800c\u7f3a\u4e4f\u652f\u6301\u4ee5\u63d0\u9ad8\u5927\u5b66\u5165\u5b66\u7387\uff0c\u4e0d\u592a\u53ef\u80fd\u589e\u52a0\u6559\u5e08\u7684\u4f9b\u7ed9\u6216\u591a\u6837\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35777", "journal": "NBER", "title": "Migration, Identity and Political Economy in a Globalizing World", "authors": ["Vasiliki Fouka", "Marco Tabellini"], "author_details": [{"name": "Vasiliki Fouka", "affiliations": []}, {"name": "Marco Tabellini", "affiliations": []}], "abstract": "We discuss how immigration affects identity, with implications for politics. We build on key insights from social psychology and their formalization in economics to derive predictions about how immigration changes both self-identification and categorization of others into groups. These immigration-induced identity changes can explain two recent political transformations that have characterized many Western democracies: the rise of right-wing populism and the realignment of voters and parties along a socio-cultural, rather than economic, dimension of political conflict. We also discuss how immigration can reshape group boundaries and political cleavages, depending on the characteristics of immigrants, host populations, and the local context. We highlight open questions and possible directions for future research.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35777", "title_zh": "\u79fb\u6c11\u3001\u8eab\u4efd\u4e0e\u5168\u7403\u5316\u4e16\u754c\u4e2d\u7684\u653f\u6cbb\u7ecf\u6d4e", "abstract_zh": "\u6211\u4eec\u8ba8\u8bba\u4e86\u79fb\u6c11\u5982\u4f55\u5f71\u54cd\u8eab\u4efd\uff0c\u53ca\u5176\u5bf9\u653f\u6cbb\u7684\u542b\u4e49\u3002\u6211\u4eec\u57fa\u4e8e\u793e\u4f1a\u5fc3\u7406\u5b66\u7684\u5173\u952e\u6d1e\u89c1\u53ca\u5176\u5728\u7ecf\u6d4e\u5b66\u4e2d\u7684\u5f62\u5f0f\u5316\u8868\u8fbe\uff0c\u63a8\u5bfc\u51fa\u5173\u4e8e\u79fb\u6c11\u5982\u4f55\u6539\u53d8\u4e2a\u4f53\u81ea\u6211\u8ba4\u540c\u4ee5\u53ca\u4ed6\u4eba\u5f52\u7c7b\u5230\u7fa4\u4f53\u4e2d\u7684\u9884\u6d4b\u3002\u8fd9\u4e9b\u7531\u79fb\u6c11\u5f15\u53d1\u7684\u8eab\u4efd\u53d8\u5316\u53ef\u4ee5\u89e3\u91ca\u8fd1\u5e74\u6765\u8bb8\u591a\u897f\u65b9\u6c11\u4e3b\u56fd\u5bb6\u51fa\u73b0\u7684\u4e24\u4e2a\u653f\u6cbb\u8f6c\u578b\uff1a\u53f3\u7ffc\u6c11\u7cb9\u4e3b\u4e49\u7684\u5174\u8d77\uff0c\u4ee5\u53ca\u9009\u6c11\u548c\u653f\u515a\u6cbf\u7740\u793e\u4f1a\u6587\u5316\u800c\u975e\u7ecf\u6d4e\u7ef4\u5ea6\u7684\u91cd\u65b0\u914d\u7f6e\u3002\u6211\u4eec\u8fd8\u8ba8\u8bba\u4e86\u79fb\u6c11\u5982\u4f55\u6839\u636e\u79fb\u6c11\u7279\u5f81\u3001\u5bbf\u4e3b\u7fa4\u4f53\u4ee5\u53ca\u5f53\u5730\u73af\u5883\u7684\u4e0d\u540c\uff0c\u91cd\u5851\u7fa4\u4f53\u8fb9\u754c\u548c\u653f\u6cbb\u5206\u88c2\u3002\u6211\u4eec\u6307\u51fa\u4e86\u5c1a\u672a\u89e3\u51b3\u7684\u95ee\u9898\u4ee5\u53ca\u672a\u6765\u7814\u7a76\u7684\u53ef\u80fd\u65b9\u5411\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35778", "journal": "NBER", "title": "Governing Global Externalities: Investor Voice Amid Fragmented Policy", "authors": ["Robin D\u00f6ttling", "Doron Levit", "Nadya Malenko", "Magdalena Rola-Janicka"], "author_details": [{"name": "Robin D\u00f6ttling", "affiliations": []}, {"name": "Doron Levit", "affiliations": []}, {"name": "Nadya Malenko", "affiliations": []}, {"name": "Magdalena Rola-Janicka", "affiliations": []}], "abstract": "We study whether investor voice can help address global externalities under fragmented regulation. In our setting, a multinational firm generates externalities across jurisdictions, national regulators face political frictions that can impede corrective regulation, and policy differences create scope for regulatory arbitrage and production leakage. We compare two channels of investor influence: corporate stewardship, which affects firms\u2019 global operations, and policy advocacy, which affects local regulation. Both channels can help address global externalities, but their relative effectiveness depends on political frictions abroad. When these frictions are severe enough to prevent foreign regulation, leakage weakens policy advocacy but strengthens stewardship. When foreign regulation is politically feasible, however, stewardship can crowd out foreign regulation and reinforce policy miscoordination, while local policy advocacy can crowd in foreign regulation and reduce externalities abroad.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35778", "title_zh": "\u6cbb\u7406\u5168\u7403\u5916\u90e8\u6027\uff1a\u5728\u76d1\u7ba1\u788e\u7247\u5316\u80cc\u666f\u4e0b\u6295\u8d44\u8005\u8bdd\u8bed\u6743\u7684\u4f5c\u7528", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u6295\u8d44\u8005\u8bdd\u8bed\u6743\u662f\u5426\u80fd\u5728\u76d1\u7ba1\u788e\u7247\u5316\u7684\u80cc\u666f\u4e0b\u5e2e\u52a9\u89e3\u51b3\u5168\u7403\u5916\u90e8\u6027\u95ee\u9898\u3002\u5728\u6211\u4eec\u7684\u8bbe\u5b9a\u4e2d\uff0c\u4e00\u5bb6\u8de8\u56fd\u4f01\u4e1a\u4f1a\u5728\u4e0d\u540c\u53f8\u6cd5\u7ba1\u8f96\u533a\u4ea7\u751f\u5916\u90e8\u6027\uff0c\u5404\u56fd\u76d1\u7ba1\u673a\u6784\u9762\u4e34\u653f\u6cbb\u6469\u64e6\uff0c\u53ef\u80fd\u963b\u788d\u7ea0\u6b63\u6027\u76d1\u7ba1\u7684\u5b9e\u65bd\uff0c\u653f\u7b56\u5dee\u5f02\u5219\u4e3a\u76d1\u7ba1\u5957\u5229\u548c\u751f\u4ea7\u5916\u6ea2\u63d0\u4f9b\u4e86\u7a7a\u95f4\u3002\u6211\u4eec\u6bd4\u8f83\u4e86\u4e24\u79cd\u6295\u8d44\u8005\u5f71\u54cd\u529b\u6e20\u9053\uff1a\u4f01\u4e1a\u6cbb\u7406\uff0c\u5f71\u54cd\u4f01\u4e1a\u5168\u7403\u8fd0\u8425\uff0c\u4ee5\u53ca\u653f\u7b56\u5021\u5bfc\uff0c\u5f71\u54cd\u672c\u5730\u76d1\u7ba1\u3002\u8fd9\u4e24\u79cd\u6e20\u9053\u90fd\u80fd\u591f\u5728\u4e00\u5b9a\u7a0b\u5ea6\u4e0a\u7f13\u89e3\u5168\u7403\u5916\u90e8\u6027\uff0c\u4f46\u5176\u76f8\u5bf9\u6709\u6548\u6027\u53d6\u51b3\u4e8e\u56fd\u5916\u7684\u653f\u6cbb\u6469\u64e6\u7a0b\u5ea6\u3002\u5f53\u8fd9\u4e9b\u6469\u64e6\u4e25\u91cd\u5230\u8db3\u4ee5\u963b\u6b62\u56fd\u5916\u76d1\u7ba1\u65f6\uff0c\u5916\u6ea2\u4f1a\u524a\u5f31\u653f\u7b56\u5021\u5bfc\u4f46\u5f3a\u5316\u4f01\u4e1a\u6cbb\u7406\u3002\u7136\u800c\uff0c\u5f53\u56fd\u5916\u76d1\u7ba1\u5728\u653f\u6cbb\u4e0a\u662f\u53ef\u884c\u7684\uff0c\u4f01\u4e1a\u6cbb\u7406\u53ef\u80fd\u4f1a\u524a\u5f31\u56fd\u5916\u76d1\u7ba1\u5e76\u52a0\u5267\u653f\u7b56\u534f\u8c03\u5931\u7075\uff0c\u800c\u672c\u5730\u653f\u7b56\u5021\u5bfc\u5219\u53ef\u80fd\u4fc3\u8fdb\u56fd\u5916\u76d1\u7ba1\u5e76\u51cf\u5c11\u6d77\u5916\u5916\u90e8\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35779", "journal": "NBER", "title": "Measuring and Projecting U.S. Investment in Semiconductor Manufacturing Capacity", "authors": ["David M. Byrne", "Robert J. Kurtzman", "Heidi L. Williams"], "author_details": [{"name": "David M. Byrne", "affiliations": []}, {"name": "Robert J. Kurtzman", "affiliations": []}, {"name": "Heidi L. Williams", "affiliations": []}], "abstract": "We consider official and alternative data sources for measuring and projecting the role of U.S. manufacturing in the global semiconductor manufacturing industry. We find that the government sources we consider face significant limitations for tracking semiconductor fab investment in real time: they use industry and product categories that are too broad and come with substantial publication lags. We then analyze project-level alternative data from Semiconductor Equipment and Materials International (SEMI), which provides quarterly tracking of individual fab projects with greater timeliness and specificity. Comparing SEMI data with official statistics through 2023, we find broad consistency in investment levels, validating SEMI as a credible supplement to official statistics. This work provides both a practical guide for tracking real-time trends in semiconductor manufacturing and a case study in synthesizing government and alternative data sources.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35779", "title_zh": "\u6d4b\u91cf\u548c\u9884\u6d4b\u7f8e\u56fd\u534a\u5bfc\u4f53\u5236\u9020\u80fd\u529b\u7684\u6295\u8d44", "abstract_zh": "\u6211\u4eec\u8003\u8651\u4e86\u5b98\u65b9\u548c\u66ff\u4ee3\u6570\u636e\u6e90\uff0c\u4ee5\u6d4b\u91cf\u548c\u9884\u6d4b\u7f8e\u56fd\u5236\u9020\u5728\u5168\u7403\u534a\u5bfc\u4f53\u5236\u9020\u884c\u4e1a\u4e2d\u7684\u4f5c\u7528\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u6211\u4eec\u6240\u8003\u8651\u7684\u653f\u5e9c\u6570\u636e\u6e90\u5728\u5b9e\u65f6\u8ddf\u8e2a\u534a\u5bfc\u4f53\u5de5\u5382\u6295\u8d44\u65b9\u9762\u5b58\u5728\u91cd\u5927\u5c40\u9650\uff1a\u5b83\u4eec\u4f7f\u7528\u8fc7\u4e8e\u5bbd\u6cdb\u7684\u884c\u4e1a\u548c\u4ea7\u54c1\u5206\u7c7b\uff0c\u5e76\u4f34\u6709\u663e\u8457\u7684\u53d1\u5e03\u5ef6\u8fdf\u3002\u6211\u4eec\u968f\u540e\u5206\u6790\u4e86\u6765\u81ea\u534a\u5bfc\u4f53\u8bbe\u5907\u4e0e\u6750\u6599\u56fd\u9645\u7ec4\u7ec7\uff08SEMI\uff09\u7684\u9879\u76ee\u7ea7\u66ff\u4ee3\u6570\u636e\uff0c\u8be5\u6570\u636e\u63d0\u4f9b\u4e86\u5bf9\u5355\u4e2a\u5de5\u5382\u9879\u76ee\u7684\u5b63\u5ea6\u8ddf\u8e2a\uff0c\u5177\u6709\u66f4\u9ad8\u7684\u65f6\u6548\u6027\u548c\u5177\u4f53\u6027\u3002\u901a\u8fc72023\u5e74\u7684\u6570\u636e\u5bf9\u6bd4\uff0cSEMI\u6570\u636e\u4e0e\u5b98\u65b9\u7edf\u8ba1\u6570\u636e\u5728\u6295\u8d44\u6c34\u5e73\u4e0a\u8868\u73b0\u51fa\u5e7f\u6cdb\u7684\u4e00\u81f4\u6027\uff0c\u9a8c\u8bc1\u4e86SEMI\u6570\u636e\u4f5c\u4e3a\u5b98\u65b9\u7edf\u8ba1\u6570\u636e\u53ef\u4fe1\u8865\u5145\u7684\u6709\u6548\u6027\u3002\u672c\u7814\u7a76\u65e2\u4e3a\u5b9e\u65f6\u8ddf\u8e2a\u534a\u5bfc\u4f53\u5236\u9020\u8d8b\u52bf\u63d0\u4f9b\u4e86\u5b9e\u7528\u6307\u5357\uff0c\u4e5f\u662f\u4e00\u6b21\u6574\u5408\u653f\u5e9c\u6570\u636e\u4e0e\u66ff\u4ee3\u6570\u636e\u6e90\u7684\u6848\u4f8b\u7814\u7a76\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35780", "journal": "NBER", "title": "Regulating Entrepreneurship: The Case of Capital Requirements", "authors": ["Annika Bacher", "Andreas Fagereng", "Marius A. K. Ring", "Ella Getz Wold"], "author_details": [{"name": "Annika Bacher", "affiliations": []}, {"name": "Andreas Fagereng", "affiliations": []}, {"name": "Marius A. K. Ring", "affiliations": []}, {"name": "Ella Getz Wold", "affiliations": []}], "abstract": "Governments have long imposed minimum equity requirements on new corporations. Opponents view them as barriers to entry while proponents argue that they protect stakeholders from financially unviable businesses. We study this quantity-quality trade-off using a Norwegian reform and comprehensive data linking entrepreneurs to their firms. A 70% reduction in required capital nearly doubled entrepreneurial entry, with no deterioration in survival, profitability, productivity, or interest-bearing leverage and no differences in founders\u2019 ex-ante income, liquidity, or ability. These results suggest capital requirements restrict entrepreneurship without screening on quality or liquidity. Rather, we highlight returns-to-scale heterogeneity as an important determinant of the observed entry response.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35780", "title_zh": "\u76d1\u7ba1\u521b\u4e1a\uff1a\u8d44\u672c\u8981\u6c42\u7684\u6848\u4f8b", "abstract_zh": "\u653f\u5e9c\u957f\u671f\u4ee5\u6765\u5bf9\u65b0\u516c\u53f8\u5b9e\u65bd\u6700\u4f4e\u80a1\u6743\u8981\u6c42\u3002\u53cd\u5bf9\u8005\u8ba4\u4e3a\u8fd9\u4e9b\u8981\u6c42\u662f\u8fdb\u5165\u58c1\u5792\uff0c\u800c\u652f\u6301\u8005\u5219\u8ba4\u4e3a\u5b83\u4eec\u80fd\u4fdd\u62a4\u5229\u76ca\u76f8\u5173\u8005\u514d\u53d7\u8d22\u52a1\u4e0d\u53ef\u6301\u7eed\u4f01\u4e1a\u7684\u4fb5\u5bb3\u3002\u6211\u4eec\u5229\u7528\u632a\u5a01\u7684\u4e00\u9879\u6539\u9769\u4ee5\u53ca\u5c06\u521b\u4e1a\u8005\u4e0e\u5176\u4f01\u4e1a\u5173\u8054\u7684\u5168\u9762\u6570\u636e\uff0c\u7814\u7a76\u8fd9\u4e00\u6570\u91cf\u4e0e\u8d28\u91cf\u4e4b\u95f4\u7684\u6743\u8861\u3002\u8d44\u672c\u8981\u6c42\u51cf\u5c1170%\u51e0\u4e4e\u4f7f\u521b\u4e1a\u8fdb\u5165\u91cf\u7ffb\u500d\uff0c\u4e14\u4f01\u4e1a\u5b58\u6d3b\u7387\u3001\u76c8\u5229\u80fd\u529b\u3001\u751f\u4ea7\u7387\u4ee5\u53ca\u5229\u606f\u652f\u4ed8\u6760\u6746\u5747\u672a\u6076\u5316\uff0c\u521b\u59cb\u4eba\u4e8b\u524d\u6536\u5165\u3001\u6d41\u52a8\u6027\u6216\u80fd\u529b\u4e5f\u65e0\u5dee\u5f02\u3002\u8fd9\u4e9b\u7ed3\u679c\u8868\u660e\uff0c\u8d44\u672c\u8981\u6c42\u9650\u5236\u4e86\u521b\u4e1a\u6d3b\u52a8\uff0c\u4f46\u5e76\u672a\u5bf9\u8d28\u91cf\u6216\u6d41\u52a8\u6027\u8fdb\u884c\u7b5b\u9009\u3002\u76f8\u53cd\uff0c\u6211\u4eec\u5f3a\u8c03\u89c4\u6a21\u6536\u76ca\u5f02\u8d28\u6027\u662f\u5bfc\u81f4\u89c2\u5bdf\u5230\u7684\u521b\u4e1a\u8fdb\u5165\u53cd\u5e94\u7684\u91cd\u8981\u51b3\u5b9a\u56e0\u7d20\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35781", "journal": "NBER", "title": "Risk Premia, Firm Insurance, and Endogenous Labor Income Risk", "authors": ["Maarten Meeuwis", "Dimitris Papanikolaou", "Lawrence D.W. Schmidt"], "author_details": [{"name": "Maarten Meeuwis", "affiliations": []}, {"name": "Dimitris Papanikolaou", "affiliations": []}, {"name": "Lawrence D.W. Schmidt", "affiliations": []}], "abstract": "We study how aggregate financial conditions shape firm insurance and, through it, labor income risk. In a directed search model with dynamic wage contracts and two-sided limited commitment, firm insurance against idiosyncratic shocks erodes when risk premia rise. Using U.S. administrative data, we document new evidence supporting the model: pass-through of firm shocks to earnings rises in bad times, especially for lower-paid workers near the separation margin. The model reproduces many untargeted time-series and cross-sectional features of earnings risk and implies substantial welfare costs of idiosyncratic risk, high private discount rates on human capital, and large gains from recession-contingent transfers.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35781", "title_zh": "\u98ce\u9669\u6ea2\u4ef7\u3001\u4f01\u4e1a\u98ce\u9669\u5206\u62c5\u4e0e\u5185\u751f\u52b3\u52a8\u6536\u5165\u98ce\u9669", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u6574\u4f53\u91d1\u878d\u72b6\u51b5\u5982\u4f55\u5f71\u54cd\u4f01\u4e1a\u98ce\u9669\u5206\u62c5\uff0c\u4ee5\u53ca\u7531\u6b64\u5e26\u6765\u7684\u52b3\u52a8\u6536\u5165\u98ce\u9669\u3002\u5728\u5177\u6709\u52a8\u6001\u5de5\u8d44\u5408\u540c\u548c\u53cc\u5411\u6709\u9650\u627f\u8bfa\u7684\u5b9a\u5411\u641c\u5bfb\u6a21\u578b\u4e2d\uff0c\u5f53\u98ce\u9669\u6ea2\u4ef7\u4e0a\u5347\u65f6\uff0c\u4f01\u4e1a\u5bf9\u7279\u8d28\u51b2\u51fb\u7684\u98ce\u9669\u5206\u62c5\u80fd\u529b\u4f1a\u51cf\u5f31\u3002\u5229\u7528\u7f8e\u56fd\u7684\u884c\u653f\u6570\u636e\uff0c\u6211\u4eec\u63d0\u4f9b\u4e86\u652f\u6301\u8be5\u6a21\u578b\u7684\u65b0\u8bc1\u636e\uff1a\u5728\u7ecf\u6d4e\u72b6\u51b5\u4e0d\u4f73\u65f6\uff0c\u4f01\u4e1a\u51b2\u51fb\u5411\u6536\u5165\u7684\u4f20\u5bfc\u589e\u5f3a\uff0c\u5c24\u5176\u4f53\u73b0\u5728\u6536\u5165\u8f83\u4f4e\u7684\u52b3\u52a8\u8005\u63a5\u8fd1\u79bb\u804c\u8fb9\u754c\u65f6\u3002\u8be5\u6a21\u578b\u518d\u73b0\u4e86earnings\u98ce\u9669\u7684\u8bb8\u591a\u672a\u4f5c\u4e3a\u6821\u51c6\u76ee\u6807\u7684\u65f6\u95f4\u5e8f\u5217\u548c\u6a2a\u622a\u9762\u7279\u5f81\uff0c\u5e76\u6697\u793a\u4e86\u7279\u8d28\u98ce\u9669\u5e26\u6765\u7684\u5de8\u5927\u798f\u5229\u635f\u5931\u3001\u4eba\u529b\u8d44\u672c\u7684\u9ad8\u79c1\u4eba\u8d34\u73b0\u7387\uff0c\u4ee5\u53ca\u5bf9\u7ecf\u6d4e\u8870\u9000\u6761\u4ef6\u4e0b\u7684\u8f6c\u79fb\u652f\u4ed8\u7684\u5de8\u5927\u6536\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.3386/w35783", "journal": "NBER", "title": "Unbundling Labor", "authors": ["Chris Edmond", "Simon Mongey"], "author_details": [{"name": "Chris Edmond", "affiliations": []}, {"name": "Simon Mongey", "affiliations": []}], "abstract": "Why is there so much wage inequality within occupations? Why has the overall level of within-occupation wage inequality risen? Why is the rise concentrated in cognitive-intensive occupations, while inequality has fallen in manual-intensive ones? To answer these questions we develop a general equilibrium model with heterogeneous workers who supply multiple skills jointly, as an indivisible bundle. This bundling friction allows a given skill to be priced differently in different occupations. We find in US data that differences in skill prices, not worker composition, explain why within-occupation inequality is higher in more cognitively intensive occupations and account for about a third of the rise in within-occupation inequality from 1980 to 2010. We show that a uniform increase in the productivity of cognitive skill can drive inequality up in cognitive-intensive occupations and down in manual ones, just as in the data.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35783", "title_zh": "\u89e3\u6784\u52b3\u52a8", "abstract_zh": "\u4e3a\u4ec0\u4e48\u540c\u4e00\u804c\u4e1a\u5185\u90e8\u7684\u5de5\u8d44\u4e0d\u5e73\u7b49\u73b0\u8c61\u5982\u6b64\u666e\u904d\uff1f\u4e3a\u4ec0\u4e48\u6574\u4f53\u7684\u804c\u5185\u5de5\u8d44\u4e0d\u5e73\u7b49\u7a0b\u5ea6\u5728\u4e0a\u5347\uff1f\u4e3a\u4ec0\u4e48\u8fd9\u79cd\u4e0a\u5347\u73b0\u8c61\u96c6\u4e2d\u5728\u8ba4\u77e5\u5bc6\u96c6\u578b\u804c\u4e1a\uff0c\u800c\u5728\u4f53\u529b\u5bc6\u96c6\u578b\u804c\u4e1a\u4e2d\u53cd\u800c\u4e0b\u964d\uff1f\u4e3a\u56de\u7b54\u8fd9\u4e9b\u95ee\u9898\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u4e00\u822c\u5747\u8861\u6a21\u578b\uff0c\u5176\u4e2d\u5f02\u8d28\u6027\u5de5\u4eba\u540c\u65f6\u63d0\u4f9b\u591a\u79cd\u6280\u80fd\uff0c\u8fd9\u4e9b\u6280\u80fd\u4f5c\u4e3a\u4e00\u4e2a\u4e0d\u53ef\u5206\u5272\u7684\u6574\u4f53\u8fdb\u884c\u4f9b\u7ed9\u3002\u8fd9\u79cd\u6280\u80fd\u6346\u7ed1\u6469\u64e6\u4f7f\u5f97\u540c\u4e00\u6280\u80fd\u5728\u4e0d\u540c\u804c\u4e1a\u4e2d\u53ef\u4ee5\u88ab\u5b9a\u4ef7\u4e0d\u540c\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u7f8e\u56fd\u6570\u636e\u4e2d\uff0c\u6280\u80fd\u4ef7\u683c\u7684\u5dee\u5f02\u800c\u975e\u5de5\u4eba\u6784\u6210\uff0c\u89e3\u91ca\u4e86\u4e3a\u4f55\u5728\u66f4\u8ba4\u77e5\u5bc6\u96c6\u578b\u7684\u804c\u4e1a\u4e2d\u804c\u5185\u4e0d\u5e73\u7b49\u7a0b\u5ea6\u66f4\u9ad8\uff0c\u5e76\u4e14\u89e3\u91ca\u4e861980\u5e74\u81f32010\u5e74\u95f4\u804c\u5185\u4e0d\u5e73\u7b49\u4e0a\u5347\u7ea6\u4e09\u5206\u4e4b\u4e00\u3002\u6211\u4eec\u8fd8\u8868\u660e\uff0c\u8ba4\u77e5\u6280\u80fd\u751f\u4ea7\u7387\u7684\u666e\u904d\u63d0\u5347\u4f1a\u4f7f\u5f97\u8ba4\u77e5\u5bc6\u96c6\u578b\u804c\u4e1a\u4e2d\u7684\u4e0d\u5e73\u7b49\u4e0a\u5347\uff0c\u800c\u4f53\u529b\u5bc6\u96c6\u578b\u804c\u4e1a\u4e2d\u7684\u4e0d\u5e73\u7b49\u4e0b\u964d\uff0c\u8fd9\u4e0e\u6570\u636e\u89c2\u5bdf\u5230\u7684\u73b0\u8c61\u5b8c\u5168\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35784", "journal": "NBER", "title": "The Protective Effects of a Healthy Spouse: Medicare as the Family Member of Last Resort", "authors": ["Itzik Fadlon", "Tal Gross", "Alex Hoagland", "Timothy Layton"], "author_details": [{"name": "Itzik Fadlon", "affiliations": []}, {"name": "Tal Gross", "affiliations": []}, {"name": "Alex Hoagland", "affiliations": []}, {"name": "Timothy Layton", "affiliations": []}], "abstract": "We study the value of informal care from a spouse and how access to such care shapes optimal insurance coverage for long-term care. Using Medicare claims and a novel spousal crosswalk, we examine how the sudden incapacitation of a spouse affects their partner's use of formal care. A spouse's health shock increases their partner's probability of a nursing-home stay by 30%. We document significant negative health effects for the partner, but provide evidence that their increase in nursing-home stays is largely driven by substitution from informal care to formal care. When their partners are incapacitated, Medicare recipients become less sensitive to the price of formal care, consistent with a higher valuation of that care and reduced moral hazard. We develop a framework to interpret these findings. The framework translates differences in the level and price elasticity of demand for formal care into a lower-bound estimate of the value of informal care provided by a spouse. It also suggests that optimal insurance for long-term care should be designed at the household level with more generous coverage for those who do not have access to informal care.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35784", "title_zh": "\u5065\u5eb7\u914d\u5076\u7684\u4fdd\u62a4\u4f5c\u7528\uff1a\u533b\u4fdd\u4f5c\u4e3a\u6700\u540e\u7684\u5bb6\u65cf\u6210\u5458", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u914d\u5076\u63d0\u4f9b\u7684\u975e\u6b63\u5f0f\u7167\u62a4\u7684\u4ef7\u503c\uff0c\u4ee5\u53ca\u8fd9\u79cd\u7167\u62a4\u7684\u53ef\u53ca\u6027\u5982\u4f55\u5f71\u54cd\u957f\u671f\u62a4\u7406\u7684\u6700\u4f18\u4fdd\u9669\u8986\u76d6\u3002\u5229\u7528\u533b\u4fdd\u6570\u636e\u548c\u4e00\u79cd\u65b0\u9896\u7684\u914d\u5076\u4ea4\u53c9\u5339\u914d\u65b9\u6cd5\uff0c\u6211\u4eec\u8003\u5bdf\u4e86\u914d\u5076\u7a81\u7136\u5931\u80fd\u5bf9\u5176\u4f34\u4fa3\u4f7f\u7528\u6b63\u5f0f\u7167\u62a4\u7684\u5f71\u54cd\u3002\u914d\u5076\u7684\u5065\u5eb7\u51b2\u51fb\u4f7f\u5176\u4f34\u4fa3\u5165\u4f4f\u62a4\u7406\u9662\u7684\u6982\u7387\u4e0a\u534730%\u3002\u6211\u4eec\u53d1\u73b0\u4f34\u4fa3\u5b58\u5728\u663e\u8457\u7684\u5065\u5eb7\u8d1f\u9762\u5f71\u54cd\uff0c\u4f46\u8bc1\u636e\u8868\u660e\uff0c\u5176\u5165\u4f4f\u62a4\u7406\u9662\u7684\u589e\u52a0\u4e3b\u8981\u662f\u7531\u4e8e\u4ece\u975e\u6b63\u5f0f\u7167\u62a4\u5411\u6b63\u5f0f\u7167\u62a4\u7684\u66ff\u4ee3\u3002\u5f53\u4f34\u4fa3\u5931\u80fd\u65f6\uff0c\u533b\u4fdd\u53d7\u76ca\u8005\u5bf9\u6b63\u5f0f\u7167\u62a4\u4ef7\u683c\u7684\u654f\u611f\u6027\u964d\u4f4e\uff0c\u8fd9\u4e0e\u4ed6\u4eec\u5bf9\u6b63\u5f0f\u7167\u62a4\u4ef7\u503c\u7684\u63d0\u5347\u4ee5\u53ca\u9053\u5fb7\u98ce\u9669\u7684\u51cf\u5c11\u4e00\u81f4\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6846\u67b6\u6765\u89e3\u91ca\u8fd9\u4e9b\u53d1\u73b0\u3002\u8be5\u6846\u67b6\u5c06\u6b63\u5f0f\u7167\u62a4\u9700\u6c42\u7684\u6c34\u5e73\u548c\u4ef7\u683c\u5f39\u6027\u5dee\u5f02\u8f6c\u5316\u4e3a\u5bf9\u914d\u5076\u63d0\u4f9b\u975e\u6b63\u5f0f\u7167\u62a4\u4ef7\u503c\u7684\u4e0b\u9650\u4f30\u8ba1\u3002\u8be5\u6846\u67b6\u8fd8\u8868\u660e\uff0c\u957f\u671f\u62a4\u7406\u7684\u6700\u4f18\u4fdd\u9669\u5e94\u4ee5\u5bb6\u5ead\u4e3a\u5355\u4f4d\u8bbe\u8ba1\uff0c\u5e76\u5bf9\u90a3\u4e9b\u65e0\u6cd5\u83b7\u5f97\u975e\u6b63\u5f0f\u7167\u62a4\u7684\u4eba\u7fa4\u63d0\u4f9b\u66f4\u6177\u6168\u7684\u4fdd\u969c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35785", "journal": "NBER", "title": "The Remains of the Trade: The U.S.\u2013China Trade War and its Aftermath", "authors": ["Pol Antr\u00e0s", "Adrian Kulesza", "Andrea F. Presbitero"], "author_details": [{"name": "Pol Antr\u00e0s", "affiliations": []}, {"name": "Adrian Kulesza", "affiliations": []}, {"name": "Andrea F. Presbitero", "affiliations": []}], "abstract": "We study how the U.S.-China trade war has reshaped global trade patterns, creating significant spillovers to third countries. Using recent tariff policy changes and monthly international trade flow data, we document a redirection of Chinese exports away from the U.S. market and toward third countries. To interpret the impact of these reallocations on third countries, we introduce a taxonomy that separates four exposure margins - export competition, import competition, consumer gains, and sourcing gains - and construct theoretically-derived indices that map countries into these channels. Recent work often proxies such exposure with trade-basket similarity. We show why this can be problematic: similarity measures are symmetric and omit the size of product-specific shocks, Chinese market penetration, substitution elasticities, and incidence weights. Our model-based indices therefore generate country rankings that differ substantially from conventional similarity measures.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35785", "title_zh": "\u8d38\u6613\u7684\u4f59\u6ce2\uff1a\u4e2d\u7f8e\u8d38\u6613\u4e89\u7aef\u53ca\u5176\u540e\u7eed\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e2d\u7f8e\u8d38\u6613\u4e89\u7aef\u5982\u4f55\u91cd\u5851\u5168\u7403\u8d38\u6613\u683c\u5c40\uff0c\u5e76\u5bf9\u7b2c\u4e09\u65b9\u56fd\u5bb6\u4ea7\u751f\u4e86\u663e\u8457\u7684\u5916\u6ea2\u6548\u5e94\u3002\u5229\u7528\u8fd1\u671f\u7684\u5173\u7a0e\u653f\u7b56\u8c03\u6574\u548c\u6708\u5ea6\u56fd\u9645\u8d38\u6613\u6d41\u91cf\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u4e2d\u56fd\u51fa\u53e3\u6b63\u5728\u4ece\u7f8e\u56fd\u5e02\u573a\u8f6c\u5411\u7b2c\u4e09\u65b9\u56fd\u5bb6\u3002\u4e3a\u4e86\u7406\u89e3\u8fd9\u4e9b\u91cd\u65b0\u5206\u914d\u5bf9\u7b2c\u4e09\u65b9\u56fd\u5bb6\u7684\u5f71\u54cd\uff0c\u6211\u4eec\u5f15\u5165\u4e86\u4e00\u79cd\u5206\u7c7b\u4f53\u7cfb\uff0c\u5c06\u56db\u79cd\u66b4\u9732\u7a0b\u5ea6\u2014\u2014\u51fa\u53e3\u7ade\u4e89\u3001\u8fdb\u53e3\u7ade\u4e89\u3001\u6d88\u8d39\u8005\u6536\u76ca\u548c\u91c7\u8d2d\u6536\u76ca\u2014\u2014\u533a\u5206\u5f00\u6765\uff0c\u5e76\u6784\u5efa\u4e86\u57fa\u4e8e\u7406\u8bba\u63a8\u5bfc\u7684\u6307\u6570\uff0c\u5c06\u5404\u56fd\u6620\u5c04\u5230\u8fd9\u4e9b\u6e20\u9053\u4e2d\u3002\u73b0\u6709\u7814\u7a76\u5e38\u4f7f\u7528\u8d38\u6613\u7bee\u5b50\u76f8\u4f3c\u6027\u6765\u8fd1\u4f3c\u8fd9\u79cd\u66b4\u9732\u7a0b\u5ea6\u3002\u6211\u4eec\u6307\u51fa\u8fd9\u79cd\u65b9\u6cd5\u5b58\u5728\u7f3a\u9677\uff1a\u76f8\u4f3c\u6027\u5ea6\u91cf\u662f\u5bf9\u79f0\u7684\uff0c\u4e14\u5ffd\u7565\u4e86\u4ea7\u54c1\u7279\u5b9a\u51b2\u51fb\u7684\u89c4\u6a21\u3001\u4e2d\u56fd\u5e02\u573a\u4efd\u989d\u3001\u66ff\u4ee3\u5f39\u6027\u4ee5\u53ca\u5f71\u54cd\u6743\u91cd\u3002\u56e0\u6b64\uff0c\u57fa\u4e8e\u6a21\u578b\u7684\u6307\u6570\u6240\u751f\u6210\u7684\u56fd\u5bb6\u6392\u540d\u4e0e\u4f20\u7edf\u76f8\u4f3c\u6027\u5ea6\u91cf\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.3386/w35786", "journal": "NBER", "title": "The Macroeconomic Effect of Stimulus Checks: Evidence from Postwar Veterans\u2019 Payments", "authors": ["Joao Guerreiro", "Jonathon Hazell", "Diego R. K\u00e4nzig", "Ed Manuel"], "author_details": [{"name": "Joao Guerreiro", "affiliations": []}, {"name": "Jonathon Hazell", "affiliations": []}, {"name": "Diego R. K\u00e4nzig", "affiliations": []}, {"name": "Ed Manuel", "affiliations": []}], "abstract": "Do stimulus checks\u2014one-off, deficit-financed lump-sum payments to households\u2014boost the economy? We study a natural experiment: payments to U.S. veterans after World War II that mimic stimulus checks but were plausibly exogenous to the economy. These payments led to a temporary increase in transfers and a persistent, hump-shaped increase in consumption. The transfer multiplier\u2014the cumulative response of consumption to transfers\u2014reaches 1 after six months and exceeds 2 after a year. The standard heterogeneous-agent New Keynesian model cannot match the hump-shaped consumption response. A version with imperfect expectations\u2014with households underreacting on impact but overreacting at longer horizons\u2014can match our estimates.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35786", "title_zh": "\u523a\u6fc0\u652f\u7968\u7684\u5b8f\u89c2\u7ecf\u6d4e\u6548\u5e94\uff1a\u6765\u81ea\u4e8c\u6218\u540e\u9000\u5f79\u519b\u4eba\u652f\u4ed8\u7684\u8bc1\u636e", "abstract_zh": "\u4e00\u6b21\u6027\u3001\u7531\u8d22\u653f\u8d64\u5b57\u878d\u8d44\u7684\u5bf9\u5bb6\u5ead\u7684\u73b0\u91d1\u652f\u4ed8\u662f\u5426\u80fd\u63d0\u632f\u7ecf\u6d4e\uff1f\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u4e2a\u81ea\u7136\u5b9e\u9a8c\uff1a\u4e8c\u6218\u540e\u5bf9\u7f8e\u56fd\u9000\u5f79\u519b\u4eba\u7684\u652f\u4ed8\uff0c\u8fd9\u79cd\u652f\u4ed8\u5f62\u5f0f\u7c7b\u4f3c\u4e8e\u523a\u6fc0\u652f\u7968\uff0c\u4f46\u5bf9\u7ecf\u6d4e\u800c\u8a00\u53ef\u80fd\u662f\u5916\u751f\u7684\u3002\u8fd9\u4e9b\u652f\u4ed8\u5bfc\u81f4\u4e86\u8f6c\u79fb\u652f\u4ed8\u7684\u6682\u65f6\u589e\u52a0\u4ee5\u53ca\u6d88\u8d39\u7684\u6301\u4e45\u6027\u3001\u5448\u9a7c\u5cf0\u72b6\u7684\u4e0a\u5347\u3002\u8f6c\u79fb\u4e58\u6570\u2014\u2014\u6d88\u8d39\u5bf9\u8f6c\u79fb\u652f\u4ed8\u7684\u7d2f\u79ef\u53cd\u5e94\u2014\u2014\u5728\u516d\u4e2a\u6708\u540e\u8fbe\u52301\uff0c\u4e00\u5e74\u540e\u8d85\u8fc72\u3002\u6807\u51c6\u7684\u5f02\u8d28\u6027\u4e3b\u4f53\u65b0\u51ef\u6069\u65af\u6a21\u578b\u65e0\u6cd5\u5339\u914d\u8fd9\u79cd\u9a7c\u5cf0\u72b6\u7684\u6d88\u8d39\u53cd\u5e94\u3002\u4e00\u4e2a\u5f15\u5165\u4e0d\u5b8c\u5168\u9884\u671f\u7684\u6a21\u578b\u2014\u2014\u5373\u5bb6\u5ead\u5728\u521d\u671f\u53cd\u5e94\u4e0d\u8db3\uff0c\u4f46\u5728\u957f\u671f\u53cd\u5e94\u8fc7\u5ea6\u2014\u2014\u53ef\u4ee5\u5339\u914d\u6211\u4eec\u7684\u4f30\u8ba1\u7ed3\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3386/w35787", "journal": "NBER", "title": "Using Policy Functions to Estimate Merger Impacts: An Application to JetBlue-Spirit", "authors": ["Gautam Gowrisankaran", "Christopher D. Bruegge", "Alex Gross"], "author_details": [{"name": "Gautam Gowrisankaran", "affiliations": []}, {"name": "Christopher D. Bruegge", "affiliations": []}, {"name": "Alex Gross", "affiliations": []}], "abstract": "Analyses of impacts of potential mergers in differentiated product markets often rely on non-transparent identification and strong conduct assumptions. We propose a simpler alternative: using quasi-exogenous variation in market structure to estimate equilibrium pricing policy functions. When price can appropriately capture consumer welfare, this methodology may require fewer assumptions than a structural equilibrium approach, including allowing variation in conduct. We apply this methodology to the JetBlue\u2013Spirit merger, estimating policy functions using entry events. Our counterfactual price simulations account for changes in JetBlue\u2019s capacity and Sprit\u2019s elimination. The merger would cause $2.6 billion in annual harm under our preferred specification.", "date": "2026-09-21", "date_kind": "\u5de5\u4f5c\u8bba\u6587\u53d1\u5e03", "first_seen": "2026-09-26T11:12:44+00:00", "url": "https://www.nber.org/papers/w35787", "title_zh": "\u4f7f\u7528\u653f\u7b56\u51fd\u6570\u4f30\u7b97\u5e76\u8d2d\u5f71\u54cd\uff1a\u4e00\u9879\u5173\u4e8e\u6377\u84dd-\u7cbe\u795e\u822a\u7a7a\u5e76\u8d2d\u7684\u5e94\u7528", "abstract_zh": "\u5728\u5dee\u5f02\u5316\u4ea7\u54c1\u5e02\u573a\u4e2d\u5206\u6790\u6f5c\u5728\u5e76\u8d2d\u7684\u5f71\u54cd\u65f6\uff0c\u901a\u5e38\u4f9d\u8d56\u4e8e\u4e0d\u900f\u660e\u7684\u8bc6\u522b\u65b9\u6cd5\u548c\u5f3a\u70c8\u7684\u884c\u4e1a\u884c\u4e3a\u5047\u8bbe\u3002\u6211\u4eec\u63d0\u51fa\u4e00\u79cd\u66f4\u7b80\u5355\u7684\u66ff\u4ee3\u65b9\u6cd5\uff1a\u5229\u7528\u5e02\u573a\u7ed3\u6784\u7684\u51c6\u5916\u751f\u53d8\u5316\u6765\u4f30\u8ba1\u5747\u8861\u5b9a\u4ef7\u653f\u7b56\u51fd\u6570\u3002\u5f53\u4ef7\u683c\u80fd\u591f\u9002\u5f53\u53cd\u6620\u6d88\u8d39\u8005\u798f\u5229\u65f6\uff0c\u8fd9\u79cd\u65b9\u6cd5\u53ef\u80fd\u6bd4\u7ed3\u6784\u5747\u8861\u65b9\u6cd5\u9700\u8981\u66f4\u5c11\u7684\u5047\u8bbe\uff0c\u5305\u62ec\u5141\u8bb8\u884c\u4e3a\u7684\u53d8\u5f02\u3002\u6211\u4eec\u5c06\u8be5\u65b9\u6cd5\u5e94\u7528\u4e8e\u6377\u84dd-\u7cbe\u795e\u822a\u7a7a\u7684\u5e76\u8d2d\u6848\u4f8b\uff0c\u5229\u7528\u8fdb\u5165\u4e8b\u4ef6\u4f30\u8ba1\u653f\u7b56\u51fd\u6570\u3002\u6211\u4eec\u7684\u53cd\u4e8b\u5b9e\u4ef7\u683c\u6a21\u62df\u8003\u8651\u4e86\u6377\u84dd\u5bb9\u91cf\u53d8\u5316\u4ee5\u53ca\u7cbe\u795e\u822a\u7a7a\u9000\u51fa\u7684\u5f71\u54cd\u3002\u6839\u636e\u6211\u4eec\u9996\u9009\u7684\u8bbe\u5b9a\uff0c\u8be5\u5e76\u8d2d\u6bcf\u5e74\u5c06\u9020\u621026\u4ebf\u7f8e\u5143\u7684\u635f\u5931\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1093/rfs/hhag082", "journal": "RFS", "title": "Corporate Bond Multipliers: Substitutes Matter", "authors": ["Manav Chaudhary", "Julie Zhiyu Fu", "Jian Li"], "author_details": [{"name": "Manav Chaudhary", "affiliations": ["London School of Economics ,"]}, {"name": "Julie Zhiyu Fu", "affiliations": ["Washington University in St. Louis, Olin Business School ,"]}, {"name": "Jian Li", "affiliations": ["Columbia Business School ,"]}], "abstract": "Abstract Many economic questions require estimating the price effect of demand shifts (multipliers) in the bond market. Corporate bonds have salient characteristics that distinguish between close and distant substitutes. We show that accounting for heterogeneous substitutability between bonds is critical for correctly estimating multipliers. We find that security-level multipliers are very small. In fact, an order of magnitude smaller than the estimate ignoring heterogeneous substitutability. Nonetheless, portfolio multipliers are substantially larger and monotonically increase with the aggregation level. Furthermore, we find that the multiplier is larger for high-yield bonds, longer-maturity bonds, and bonds with greater arbitrage risks.", "date": "2026-09-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag082", "title_zh": "\u516c\u53f8\u503a\u5238\u4e58\u6570\uff1a\u66ff\u4ee3\u54c1\u81f3\u5173\u91cd\u8981", "abstract_zh": "\u8bb8\u591a\u7ecf\u6d4e\u95ee\u9898\u9700\u8981\u4f30\u8ba1\u503a\u5238\u5e02\u573a\u4e2d\u9700\u6c42\u53d8\u52a8\u7684\u4ef7\u683c\u6548\u5e94\uff0c\u5373\u4e58\u6570\u3002\u516c\u53f8\u503a\u5238\u5177\u6709\u663e\u8457\u7684\u7279\u5f81\uff0c\u80fd\u591f\u533a\u5206\u5f7c\u6b64\u662f\u7d27\u5bc6\u66ff\u4ee3\u54c1\u8fd8\u662f\u8f83\u5f31\u7684\u66ff\u4ee3\u54c1\u3002\u6211\u4eec\u8868\u660e\uff0c\u8003\u8651\u503a\u5238\u4e4b\u95f4\u5f02\u8d28\u6027\u7684\u53ef\u66ff\u4ee3\u7a0b\u5ea6\uff0c\u5bf9\u4e8e\u6b63\u786e\u4f30\u8ba1\u4e58\u6570\u81f3\u5173\u91cd\u8981\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5355\u53ea\u8bc1\u5238\u5c42\u9762\u7684\u4e58\u6570\u975e\u5e38\u5c0f\uff0c\u5b9e\u9645\u4e0a\u6bd4\u5ffd\u7565\u5f02\u8d28\u6027\u53ef\u66ff\u4ee3\u7a0b\u5ea6\u65f6\u7684\u4f30\u8ba1\u503c\u4f4e\u4e00\u4e2a\u6570\u91cf\u7ea7\u3002\u7136\u800c\uff0c\u6295\u8d44\u7ec4\u5408\u5c42\u9762\u7684\u4e58\u6570\u663e\u8457\u66f4\u5927\uff0c\u5e76\u968f\u7740\u805a\u5408\u5c42\u7ea7\u63d0\u9ad8\u800c\u5355\u8c03\u589e\u52a0\u3002\u6b64\u5916\uff0c\u9ad8\u6536\u76ca\u503a\u5238\u3001\u671f\u9650\u66f4\u957f\u7684\u503a\u5238\u4ee5\u53ca\u5957\u5229\u98ce\u9669\u66f4\u5927\u7684\u503a\u5238\uff0c\u5176\u4e58\u6570\u66f4\u5927\u3002", "translation_source": "\u9996\u7248\u6837\u4f8b\uff1a\u7531 Codex \u6839\u636e\u516c\u5f00\u6458\u8981\u7ffb\u8bd1\uff0c\u975e Qwen \u8f93\u51fa", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhag081", "journal": "RFS", "title": "Adverse Selection and the Government Intervention Trap", "authors": ["Fenghua Song", "Anjan Thakor"], "author_details": [{"name": "Fenghua Song", "affiliations": ["Pennsylvania State University and FTG ,"]}, {"name": "Anjan Thakor", "affiliations": ["Washington University in St. Louis, ECGI, and FTG ,"]}], "abstract": "Abstract In a dynamic setting, high-quality firms may tolerate current adverse selection when raising financing because they expect future opportunities to profitably acquire assets from failed lower-quality firms. But search frictions in asset trading impede efficiency, inviting government intervention. Anticipation of such intervention affects ex ante adverse selection and project investment because it reduces buyers\u2019 ex post trading profits. Depending on parameter values, this anticipation can have either pernicious or salutary effects. The pernicious effect reduces participation by high-quality firms, worsens adverse selection, and depresses project investment, potentially triggering investment-enhancing government assistance (an \u201cintervention trap\u201d). The salutary effect mitigates adverse selection and increases project investment.", "date": "2026-09-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag081", "title_zh": "\u9006\u5411\u9009\u62e9\u4e0e\u653f\u5e9c\u5e72\u9884\u9677\u9631", "abstract_zh": "\u6458\u8981 \u5728\u52a8\u6001\u73af\u5883\u4e2d\uff0c\u9ad8\u8d28\u91cf\u4f01\u4e1a\u53ef\u80fd\u5bb9\u5fcd\u5f53\u524d\u7684\u9006\u5411\u9009\u62e9\u4ee5\u7b79\u96c6\u8d44\u91d1\uff0c\u56e0\u4e3a\u5b83\u4eec\u9884\u671f\u672a\u6765\u6709\u673a\u4f1a\u4ece\u5931\u8d25\u7684\u4f4e\u8d28\u91cf\u4f01\u4e1a\u90a3\u91cc\u76c8\u5229\u5730\u83b7\u53d6\u8d44\u4ea7\u3002\u7136\u800c\uff0c\u8d44\u4ea7\u4ea4\u6613\u4e2d\u7684\u641c\u5bfb\u6469\u64e6\u4f1a\u964d\u4f4e\u6548\u7387\uff0c\u4ece\u800c\u5f15\u53d1\u653f\u5e9c\u5e72\u9884\u3002\u5bf9\u4f01\u4e1a\u672a\u6765\u53ef\u80fd\u53d7\u5230\u5e72\u9884\u7684\u9884\u671f\u4f1a\u5f71\u54cd\u4e8b\u524d\u9006\u5411\u9009\u62e9\u548c\u9879\u76ee\u6295\u8d44\uff0c\u56e0\u4e3a\u8fd9\u4f1a\u51cf\u5c11\u4e70\u65b9\u4e8b\u540e\u7684\u4ea4\u6613\u5229\u6da6\u3002\u6839\u636e\u53c2\u6570\u503c\u7684\u4e0d\u540c\uff0c\u8fd9\u79cd\u9884\u671f\u53ef\u80fd\u4ea7\u751f\u6709\u5bb3\u6216\u6709\u76ca\u7684\u5f71\u54cd\u3002\u6709\u5bb3\u6548\u5e94\u4f1a\u964d\u4f4e\u9ad8\u8d28\u91cf\u4f01\u4e1a\u7684\u53c2\u4e0e\u5ea6\uff0c\u52a0\u5267\u9006\u5411\u9009\u62e9\uff0c\u5e76\u6291\u5236\u9879\u76ee\u6295\u8d44\uff0c\u53ef\u80fd\u5f15\u53d1\u6295\u8d44\u4fc3\u8fdb\u578b\u7684\u653f\u5e9c\u63f4\u52a9\uff08\u5373\u201c\u5e72\u9884\u9677\u9631\u201d\uff09\u3002\u6709\u76ca\u6548\u5e94\u5219\u80fd\u7f13\u89e3\u9006\u5411\u9009\u62e9\u5e76\u589e\u52a0\u9879\u76ee\u6295\u8d44\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag086", "journal": "RFS", "title": "The Coherence Side of Rationality: Theory and Evidence from Firm Plans", "authors": ["Pamela Giustinelli", "Stefano Rossi"], "author_details": [{"name": "Pamela Giustinelli", "affiliations": ["University of Padova , , CESifo, and IZA@LISER"]}, {"name": "Stefano Rossi", "affiliations": ["Bocconi University , , CEPR, and ECGI"]}], "abstract": "Abstract Using the Duke Survey data on firms\u2019 internal plans, we show that over 80% of Chief Financial Officer (CFO) forecasts align closely with simple heuristics taught in MBA textbooks. We introduce forecast coherence\u2014internal consistency across forecasts of jointly determined variables\u2014as a benchmark for evaluating these heuristics. Nearly half of CFOs issue forecasts closely aligned with incoherent heuristics. Such forecasts are associated with predictable reversals in forecast errors, lower firm performance, and underinvestment. We develop a parsimonious model illustrating how reliance on restricted forecasting heuristics can generate incoherence and resource misallocation within firms, consistent with our evidence", "date": "2026-09-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag086", "title_zh": "\u7406\u6027\u4e4b\u534f\u540c\u9762\uff1a\u6765\u81ea\u4f01\u4e1a\u8ba1\u5212\u7684\u7406\u8bba\u4e0e\u8bc1\u636e", "abstract_zh": "\u5229\u7528\u675c\u514b\u8c03\u67e5\u6570\u636e\u4e2d\u7684\u4f01\u4e1a\u5185\u90e8\u8ba1\u5212\uff0c\u6211\u4eec\u53d1\u73b0\u8d85\u8fc780%\u7684\u9996\u5e2d\u8d22\u52a1\u5b98\uff08CFO\uff09\u9884\u6d4b\u4e0eMBA\u6559\u6750\u4e2d\u6559\u6388\u7684\u7b80\u5355\u542f\u53d1\u5f0f\u65b9\u6cd5\u9ad8\u5ea6\u4e00\u81f4\u3002\u6211\u4eec\u5f15\u5165\u4e86\u9884\u6d4b\u4e00\u81f4\u6027\u2014\u2014\u5bf9\u76f8\u4e92\u51b3\u5b9a\u53d8\u91cf\u7684\u9884\u6d4b\u4e4b\u95f4\u7684\u4e00\u81f4\u6027\u2014\u2014\u4f5c\u4e3a\u8bc4\u4f30\u8fd9\u4e9b\u542f\u53d1\u5f0f\u65b9\u6cd5\u7684\u57fa\u51c6\u3002\u8fd1\u4e00\u534a\u7684CFO\u53d1\u5e03\u7684\u9884\u6d4b\u4e0e\u4e0d\u4e00\u81f4\u7684\u542f\u53d1\u5f0f\u65b9\u6cd5\u9ad8\u5ea6\u5951\u5408\u3002\u8fd9\u7c7b\u9884\u6d4b\u4e0e\u53ef\u9884\u6d4b\u7684\u9884\u6d4b\u8bef\u5dee\u53cd\u8f6c\u3001\u4f01\u4e1a\u7ee9\u6548\u4e0b\u964d\u4ee5\u53ca\u6295\u8d44\u4e0d\u8db3\u76f8\u5173\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u7b80\u6d01\u7684\u6a21\u578b\uff0c\u8bf4\u660e\u4f9d\u8d56\u4e8e\u53d7\u9650\u7684\u9884\u6d4b\u542f\u53d1\u5f0f\u65b9\u6cd5\u5982\u4f55\u5bfc\u81f4\u4f01\u4e1a\u5185\u90e8\u7684\u4e0d\u4e00\u81f4\u6027\u4e0e\u8d44\u6e90\u9519\u914d\uff0c\u8fd9\u4e0e\u6211\u4eec\u7684\u5b9e\u8bc1\u53d1\u73b0\u76f8\u4e00\u81f4", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag083", "journal": "RFS", "title": "Optimal Time-Consistent Debt Policies", "authors": ["Andrey Malenko", "Anton Tsoy"], "author_details": [{"name": "Andrey Malenko", "affiliations": ["Boston College , the United States"]}, {"name": "Anton Tsoy", "affiliations": ["University of Toronto ,"]}], "abstract": "Abstract We study a dynamic trade-off model where shareholders can freely adjust debt but lack commitment to future debt policies. A debt policy is time-consistent if shareholders prefer it to deviating and losing credibility ex post. We characterize the optimal time-consistent policy in a class. It includes a stable regime, where shareholders actively manage liabilities to maintain the target interest coverage ratio, and a distress regime triggered by large negative shocks, where shareholders temporarily abandon the target. This policy has realistic properties and bridges the gap between the static trade-off theory of debt and theory based on the leverage ratchet effect.", "date": "2026-09-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag083", "title_zh": "\u6700\u4f18\u4e00\u81f4\u503a\u52a1\u653f\u7b56", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u4e2a\u52a8\u6001\u6743\u8861\u6a21\u578b\uff0c\u5176\u4e2d\u80a1\u4e1c\u53ef\u4ee5\u81ea\u7531\u8c03\u6574\u503a\u52a1\uff0c\u4f46\u7f3a\u4e4f\u5bf9\u672a\u6765\u503a\u52a1\u653f\u7b56\u7684\u627f\u8bfa\u3002\u5982\u679c\u80a1\u4e1c\u504f\u597d\u67d0\u4e00\u503a\u52a1\u653f\u7b56\uff0c\u5e76\u4e14\u5728\u4e8b\u540e\u504f\u79bb\u8be5\u653f\u7b56\u4f1a\u5931\u53bb\u4fe1\u8a89\uff0c\u5219\u8be5\u653f\u7b56\u88ab\u79f0\u4e3a\u65f6\u95f4\u4e00\u81f4\u653f\u7b56\u3002\u6211\u4eec\u5728\u4e00\u4e2a\u7c7b\u4e2d\u523b\u753b\u4e86\u6700\u4f18\u65f6\u95f4\u4e00\u81f4\u653f\u7b56\u3002\u8be5\u653f\u7b56\u5305\u62ec\u4e00\u4e2a\u7a33\u5b9a\u9636\u6bb5\uff0c\u5373\u80a1\u4e1c\u4e3b\u52a8\u7ba1\u7406\u8d1f\u503a\u4ee5\u7ef4\u6301\u76ee\u6807\u5229\u606f\u8986\u76d6\u6bd4\u7387\uff0c\u4ee5\u53ca\u5728\u906d\u9047\u91cd\u5927\u8d1f\u5411\u51b2\u51fb\u65f6\u89e6\u53d1\u7684\u56f0\u5883\u9636\u6bb5\uff0c\u6b64\u65f6\u80a1\u4e1c\u6682\u65f6\u653e\u5f03\u76ee\u6807\u3002\u8be5\u653f\u7b56\u5177\u6709\u73b0\u5b9e\u7279\u5f81\uff0c\u5e76\u5f25\u5408\u4e86\u9759\u6001\u503a\u52a1\u6743\u8861\u7406\u8bba\u4e0e\u57fa\u4e8e\u6760\u6746\u722c\u5347\u6548\u5e94\u7684\u7406\u8bba\u4e4b\u95f4\u7684\u5dee\u8ddd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.05008", "journal": "MS", "title": "Index-Based Yield Protection for Smallholder Farmers", "authors": ["Kehan Lu", "Jing-Sheng Song", "Can Zhang"], "author_details": [{"name": "Kehan Lu", "affiliations": ["Fuqua School of Business, Duke University, Durham, North Carolina 27708"]}, {"name": "Jing-Sheng Song", "affiliations": ["Fuqua School of Business, Duke University, Durham, North Carolina 27708"]}, {"name": "Can Zhang", "affiliations": ["Fuqua School of Business, Duke University, Durham, North Carolina 27708"]}], "abstract": "Smallholder farmers in emerging economies are vital to the global food supply, yet they remain highly vulnerable to yield risks such as extreme weather. Whereas government subsidies that compensate farmers in low-yield scenarios are common in developed countries, such policies are often impractical in emerging economies because of the high cost of assessing yields on small farms. To address this, an innovative index-based approach has gained traction, under which payments are triggered when a predetermined index (e.g., rainfall) predicts a low yield. Yet the inevitable inaccuracy of indices in reflecting actual yields weakens the alignment between payments and actual yields, reducing risk protection for farmers. This paper analyzes how governments should design yield protection subsidies under index inaccuracy. Our analysis reveals several insights. First, unlike actual yield\u2013based policies, higher subsidies under index-based policies can inadvertently increase farmers\u2019 income variability. Building on this, we identify a nonmonotonic relationship between the optimal subsidy and index accuracy: as accuracy improves, subsidies should initially increase but then decrease once accuracy becomes sufficiently high. Second, whereas price protection subsidies (which compensate for low prices) are often viewed as strategic substitutes for yield protection as both can increase income and incentivize planting, we show that they act as strategic complements when index accuracy is low, meaning the presence of price protection warrants a higher index-based yield protection subsidy and vice versa. Finally, when governments allocate budgets between subsidy payments and improving index accuracy, we find that tighter budgets can make it especially important to prioritize index accuracy.", "date": "2026-09-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.05008", "title_zh": "\u57fa\u4e8e\u6307\u6570\u7684\u5c0f\u519c\u6237\u519c\u6c11\u6536\u6210\u4fdd\u62a4", "abstract_zh": "\u65b0\u5174\u7ecf\u6d4e\u4f53\u4e2d\u7684\u5c0f\u519c\u6237\u519c\u6c11\u5bf9\u5168\u7403\u7cae\u98df\u4f9b\u5e94\u81f3\u5173\u91cd\u8981\uff0c\u4f46\u4ed6\u4eec\u4ecd\u6781\u6613\u53d7\u5230\u6536\u6210\u98ce\u9669\uff08\u5982\u6781\u7aef\u5929\u6c14\uff09\u7684\u5f71\u54cd\u3002\u5728\u53d1\u8fbe\u56fd\u5bb6\uff0c\u653f\u5e9c\u901a\u5e38\u4f1a\u63d0\u4f9b\u8865\u507f\u63aa\u65bd\uff0c\u4ee5\u5e94\u5bf9\u4f4e\u6536\u6210\u60c5\u51b5\uff0c\u4f46\u5728\u65b0\u5174\u7ecf\u6d4e\u4f53\u4e2d\uff0c\u8fd9\u79cd\u653f\u7b56\u5f80\u5f80\u56e0\u8bc4\u4f30\u5c0f\u519c\u6237\u6536\u6210\u6210\u672c\u8fc7\u9ad8\u800c\u96be\u4ee5\u5b9e\u65bd\u3002\u4e3a\u6b64\uff0c\u4e00\u79cd\u521b\u65b0\u7684\u57fa\u4e8e\u6307\u6570\u7684\u65b9\u6cd5\u9010\u6e10\u53d7\u5230\u5173\u6ce8\uff0c\u5373\u5f53\u9884\u8bbe\u6307\u6570\uff08\u4f8b\u5982\u964d\u96e8\u91cf\uff09\u9884\u6d4b\u6536\u6210\u8f83\u4f4e\u65f6\uff0c\u89e6\u53d1\u652f\u4ed8\u3002\u7136\u800c\uff0c\u6307\u6570\u5728\u53cd\u6620\u5b9e\u9645\u6536\u6210\u65b9\u9762\u7684\u5fc5\u7136\u4e0d\u51c6\u786e\u6027\uff0c\u524a\u5f31\u4e86\u652f\u4ed8\u4e0e\u5b9e\u9645\u6536\u6210\u4e4b\u95f4\u7684\u5339\u914d\uff0c\u4ece\u800c\u964d\u4f4e\u4e86\u5bf9\u519c\u6c11\u7684\u98ce\u9669\u4fdd\u62a4\u3002\u672c\u6587\u5206\u6790\u4e86\u653f\u5e9c\u5728\u6307\u6570\u4e0d\u51c6\u786e\u6027\u80cc\u666f\u4e0b\u5e94\u5982\u4f55\u8bbe\u8ba1\u6536\u6210\u4fdd\u62a4\u8865\u8d34\u3002\u6211\u4eec\u7684\u5206\u6790\u5f97\u51fa\u82e5\u5e72\u91cd\u8981\u53d1\u73b0\uff1a\u9996\u5148\uff0c\u4e0e\u57fa\u4e8e\u5b9e\u9645\u6536\u6210\u7684\u653f\u7b56\u4e0d\u540c\uff0c\u57fa\u4e8e\u6307\u6570\u7684\u653f\u7b56\u4e2d\uff0c\u66f4\u9ad8\u7684\u8865\u8d34\u53cd\u800c\u53ef\u80fd\u65e0\u610f\u4e2d\u589e\u52a0\u519c\u6c11\u6536\u5165\u7684\u6ce2\u52a8\u6027\u3002\u57fa\u4e8e\u6b64\uff0c\u6211\u4eec\u53d1\u73b0\u6700\u4f18\u8865\u8d34\u4e0e\u6307\u6570\u51c6\u786e\u6027\u7684\u5173\u7cfb\u662f\u975e\u5355\u8c03\u7684\uff1a\u968f\u7740\u51c6\u786e\u6027\u7684\u63d0\u5347\uff0c\u8865\u8d34\u5e94\u5148\u4e0a\u5347\uff0c\u4f46\u5f53\u51c6\u786e\u6027\u8fbe\u5230\u4e00\u5b9a\u7a0b\u5ea6\u540e\uff0c\u8865\u8d34\u53cd\u800c\u4f1a\u4e0b\u964d\u3002\u5176\u6b21\uff0c\u5c3d\u7ba1\u4ef7\u683c\u4fdd\u62a4\u8865\u8d34\uff08\u8865\u507f\u4f4e\u4ef7\u60c5\u51b5\uff09\u901a\u5e38\u88ab\u89c6\u4e3a\u6536\u6210\u4fdd\u62a4\u7684\u66ff\u4ee3\u6027\u7b56\u7565\uff0c\u56e0\u4e3a\u4e24\u8005\u5747\u53ef\u63d0\u5347\u6536\u5165\u5e76\u6fc0\u52b1\u79cd\u690d\uff0c\u4f46\u6211\u4eec\u53d1\u73b0\uff0c\u5f53\u6307\u6570\u51c6\u786e\u6027\u8f83\u4f4e\u65f6\uff0c\u4ef7\u683c\u4fdd\u62a4\u8865\u8d34\u4e0e\u6536\u6210\u4fdd\u62a4\u8865\u8d34\u662f\u6218\u7565\u4e92\u8865\u5173\u7cfb\uff0c\u5373\u4ef7\u683c\u4fdd\u62a4\u7684\u5b58\u5728\u8981\u6c42\u63d0\u9ad8\u57fa\u4e8e\u6307\u6570\u7684\u6536\u6210\u4fdd\u62a4\u8865\u8d34\uff0c\u53cd\u4e4b\u4ea6\u7136\u3002\u6700\u540e\uff0c\u5f53\u653f\u5e9c\u5728\u8865\u8d34\u652f\u4ed8\u548c\u63d0\u5347\u6307\u6570\u51c6\u786e\u6027\u4e4b\u95f4\u5206\u914d\u9884\u7b97\u65f6\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u9884\u7b97\u7d27\u5f20\u7684\u60c5\u51b5\u4e0b\uff0c\u4f18\u5148\u63d0\u5347\u6307\u6570\u51c6\u786e\u6027\u663e\u5f97\u5c24\u4e3a\u91cd\u8981\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.00580", "journal": "MS", "title": "Bad News Bearers: The Negative Tilt of the Financial Press", "authors": ["Betty Liu", "Marina Niessner", "Eric C. So"], "author_details": [{"name": "Betty Liu", "affiliations": ["Kelley School of Business, Indiana University, Bloomington, Indiana 47405"]}, {"name": "Marina Niessner", "affiliations": ["Kelley School of Business, Indiana University, Bloomington, Indiana 47405"]}, {"name": "Eric C. So", "affiliations": ["Sloan School of Management, Massachusetts Institute of Technology, Cambridge, Massachusetts 02142"]}], "abstract": "We show that increased media coverage strongly predicts lower subsequently announced firm fundamentals, earnings surprises, and higher likelihoods of bankruptcy, dividend cuts, and delistings. Additionally, we find that media articles often convey negative sentiment, with investor attention increasing around the publication of negative articles, suggesting that the media tilts coverage toward negative events to drive readership. We also show that media coverage initially impedes price discovery for negative news through an attention effect and that investors respond sluggishly to the negative signal embedded in media coverage decisions, leading to a gradual incorporation of the negative information into prices and return predictability.", "date": "2026-09-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.00580", "title_zh": "\u574f\u6d88\u606f\u7684\u4f20\u64ad\u8005\uff1a\u91d1\u878d\u5a92\u4f53\u7684\u8d1f\u9762\u503e\u5411", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u5a92\u4f53\u62a5\u9053\u7684\u589e\u52a0\u5f3a\u70c8\u9884\u793a\u7740\u540e\u7eed\u516c\u53f8\u57fa\u672c\u9762\u7684\u6076\u5316\u3001\u76c8\u5229\u610f\u5916\u7684\u51cf\u5c11\uff0c\u4ee5\u53ca\u7834\u4ea7\u3001\u80a1\u606f\u524a\u51cf\u548c\u9000\u5e02\u7684\u53ef\u80fd\u6027\u4e0a\u5347\u3002\u6b64\u5916\uff0c\u6211\u4eec\u53d1\u73b0\u5a92\u4f53\u6587\u7ae0\u901a\u5e38\u4f20\u9012\u8d1f\u9762\u60c5\u7eea\uff0c\u6295\u8d44\u8005\u7684\u5173\u6ce8\u5ea6\u5728\u8d1f\u9762\u6587\u7ae0\u53d1\u5e03\u65f6\u4e0a\u5347\uff0c\u8fd9\u8868\u660e\u5a92\u4f53\u503e\u5411\u4e8e\u5c06\u62a5\u9053\u504f\u5411\u8d1f\u9762\u4e8b\u4ef6\u4ee5\u5438\u5f15\u8bfb\u8005\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0c\u5a92\u4f53\u62a5\u9053\u5728\u6700\u521d\u4f1a\u901a\u8fc7\u6ce8\u610f\u529b\u6548\u5e94\u963b\u788d\u5bf9\u8d1f\u9762\u4fe1\u606f\u7684\u4ef7\u683c\u53d1\u73b0\uff0c\u6295\u8d44\u8005\u5bf9\u5a92\u4f53\u62a5\u9053\u4e2d\u8574\u542b\u7684\u8d1f\u9762\u4fe1\u53f7\u53cd\u5e94\u8fdf\u7f13\uff0c\u5bfc\u81f4\u8d1f\u9762\u4fe1\u606f\u9010\u6e10\u88ab\u7eb3\u5165\u4ef7\u683c\u5e76\u63d0\u5347\u56de\u62a5\u7684\u53ef\u9884\u6d4b\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e02\u573a\u53cd\u9988"]}, {"doi": "10.1017/s0022109026103159", "journal": "JFQA", "title": "Private Equity and Gas Emissions: Evidence from Electric Power Plants", "authors": ["Xuanyu Bai", "Youchang Wu"], "author_details": [{"name": "Xuanyu Bai", "affiliations": ["Oslo Metropolitan University Oslo Business School"]}, {"name": "Youchang Wu", "affiliations": ["University of Oregon Lundquist College of Business"]}], "abstract": "Abstract We examine the effect of private equity buyouts on the environmental performance of U.S. fossil fuel power plants. Output-scaled CO 2 emissions are, on average, 4.2% lower after buyouts, predominantly because of fuel-saving improvements in production efficiency. Emission intensities decline more significantly following buyouts backed by pro-ESG private equity because of not only greater efficiency gains but also enhanced emission control. Our results suggest that while private equity firms are effective at implementing environmentally beneficial operational changes that also increase profitability, they do not have strong incentives to undertake environmentally beneficial changes that are privately costly, except for those with pro-ESG preferences.", "date": "2026-09-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103159", "title_zh": "\u79c1\u52df\u80a1\u6743\u4e0e\u5929\u7136\u6c14\u6392\u653e\uff1a\u6765\u81ea\u7535\u529b\u5de5\u5382\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u79c1\u52df\u80a1\u6743\u6536\u8d2d\u5bf9\u7f8e\u56fd\u5316\u77f3\u71c3\u6599\u53d1\u7535\u5382\u73af\u5883\u8868\u73b0\u7684\u5f71\u54cd\u3002\u6536\u8d2d\u540e\uff0c\u4e8c\u6c27\u5316\u78b3\u6392\u653e\u91cf\u5e73\u5747\u964d\u4f4e\u4e864.2%\uff0c\u4e3b\u8981\u5f52\u56e0\u4e8e\u751f\u4ea7\u6548\u7387\u7684\u71c3\u6599\u8282\u7ea6\u6539\u8fdb\u3002\u5728\u7531\u652f\u6301\u73af\u5883\u3001\u793e\u4f1a\u548c\u6cbb\u7406\uff08ESG\uff09\u7684\u79c1\u52df\u80a1\u6743\u652f\u6301\u7684\u6536\u8d2d\u540e\uff0c\u6392\u653e\u5f3a\u5ea6\u4e0b\u964d\u66f4\u4e3a\u663e\u8457\uff0c\u8fd9\u4e0d\u4ec5\u6e90\u4e8e\u6548\u7387\u63d0\u5347\uff0c\u8fd8\u56e0\u4e3a\u6392\u653e\u63a7\u5236\u63aa\u65bd\u5f97\u5230\u52a0\u5f3a\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u5c3d\u7ba1\u79c1\u52df\u80a1\u6743\u516c\u53f8\u80fd\u591f\u6709\u6548\u5b9e\u65bd\u65e2\u63d0\u5347\u76c8\u5229\u80fd\u529b\u53c8\u5177\u6709\u73af\u5883\u6548\u76ca\u7684\u8fd0\u8425\u6539\u8fdb\uff0c\u4f46\u5bf9\u4e8e\u90a3\u4e9b\u79c1\u4eba\u6210\u672c\u8f83\u9ad8\u7684\u73af\u5883\u53cb\u597d\u578b\u63aa\u65bd\uff0c\u5b83\u4eec\u7684\u6fc0\u52b1\u5e76\u4e0d\u5f3a\u70c8\uff0c\u9664\u975e\u8fd9\u4e9b\u79c1\u52df\u80a1\u6743\u516c\u53f8\u5177\u6709\u652f\u6301ESG\u7684\u504f\u597d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1287/mnsc.2024.08449", "journal": "MS", "title": "Beyond Value: On the Role of Symmetry in Demand for Information", "authors": ["Aniol Llorente-Saguer", "Santiago Oliveros", "Ro\u2019i Zultan"], "author_details": [{"name": "Aniol Llorente-Saguer", "affiliations": ["School of Economics and Finance, Queen Mary University of London, London E1 4NS, United Kingdom"]}, {"name": "Santiago Oliveros", "affiliations": ["Department of Economics, University of Bristol, Bristol BS8 1TU, United Kingdom"]}, {"name": "Ro\u2019i Zultan", "affiliations": ["Department of Economics, Ben-Gurion University of the Negev, Beer-Sheva 8410501, Israel"]}], "abstract": "We study demand for symmetric and asymmetric information sources in the laboratory. Although participants respond to incentives and instrumental considerations, they exhibit a systematic bias towards symmetric sources. These patterns persist among individuals with higher cognitive abilities and better task comprehension, and they are not accounted for by their elicited subjective beliefs.", "date": "2026-09-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08449", "title_zh": "\u8d85\u8d8a\u4ef7\u503c\uff1a\u5bf9\u79f0\u4fe1\u606f\u9700\u6c42\u4e2d\u7684\u5bf9\u79f0\u6027\u4f5c\u7528", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5b9e\u9a8c\u5ba4\u4e2d\u53c2\u4e0e\u8005\u5bf9\u5bf9\u79f0\u548c\u975e\u5bf9\u79f0\u4fe1\u606f\u6e90\u7684\u9700\u6c42\u3002\u5c3d\u7ba1\u53c2\u4e0e\u8005\u4f1a\u6839\u636e\u6fc0\u52b1\u548c\u5de5\u5177\u6027\u56e0\u7d20\u505a\u51fa\u53cd\u5e94\uff0c\u4f46\u4ed6\u4eec\u4ecd\u7cfb\u7edf\u6027\u5730\u504f\u597d\u5bf9\u79f0\u4fe1\u606f\u6e90\u3002\u8fd9\u79cd\u6a21\u5f0f\u5728\u8ba4\u77e5\u80fd\u529b\u8f83\u9ad8\u548c\u4efb\u52a1\u7406\u89e3\u66f4\u597d\u7684\u4e2a\u4f53\u4e2d\u4f9d\u7136\u5b58\u5728\uff0c\u4e14\u65e0\u6cd5\u901a\u8fc7\u4ed6\u4eec\u7684\u4e3b\u89c2\u4fe1\u5ff5\u6765\u89e3\u91ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag047", "journal": "QJE", "title": "Attention to the Macroeconomy", "authors": ["Sebastian Link", "Andreas Peichl", "Oliver Pf\u00e4uti", "Christopher Roth", "Johannes Wohlfart"], "author_details": [{"name": "Sebastian Link", "affiliations": ["Institute, LMU Munich, IZA@LISER, CESifo"]}, {"name": "Andreas Peichl", "affiliations": ["LMU Munich, ifo Institute"]}, {"name": "Oliver Pf\u00e4uti", "affiliations": ["University of Texas at Austin"]}, {"name": "Christopher Roth", "affiliations": ["University of Cologne, ECONtribute, CESifo, CEPR, Max-Planck Institute for Behavioral Economics Bonn"]}, {"name": "Johannes Wohlfart", "affiliations": ["University of Cologne, ECONtribute, Max-Planck Institute for Behavioral Economics, CEBI, CESifo"]}], "abstract": "Abstract We measure which economic topics are top of mind using quarterly German household and firm panels from 2020 to 2024, a period that spans the post-pandemic inflation surge and the subsequent disinflation. With these data, we study potential determinants and consequences of having inflation top of mind. In line with goal-directed attention, the likelihood that inflation is top of mind rises with proxies for its true payoff relevance. At the same time, prior experiences predict whether respondents have inflation and energy prices top of mind conditional on a large set of controls for payoff relevance, and this relationship strengthens when the environment becomes more inflationary. Having inflation top of mind predicts stronger increases in information acquisition and inflation expectations over the shock period. At odds with goal-optimality, having inflation top of mind is associated with expectations further away from multiple ex-ante benchmarks. Finally, both key determinants of having inflation top of mind\u2014payoff relevance and prior experiences\u2014are associated with stronger shifts of expectations away from these benchmarks over the shock period.", "date": "2026-09-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag047", "title_zh": "\u5bf9\u5b8f\u89c2\u7ecf\u6d4e\u7684\u5173\u6ce8", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u75282020\u5e74\u81f32024\u5e74\u671f\u95f4\u7684\u5fb7\u56fd\u5bb6\u5ead\u548c\u4f01\u4e1a\u9762\u677f\u6570\u636e\uff0c\u6d4b\u91cf\u54ea\u4e9b\u7ecf\u6d4e\u8bdd\u9898\u662f\u516c\u4f17\u6700\u5173\u6ce8\u7684\uff0c\u8fd9\u4e00\u65f6\u671f\u6db5\u76d6\u4e86\u75ab\u60c5\u540e\u7684\u901a\u8d27\u81a8\u80c0\u98d9\u5347\u4ee5\u53ca\u968f\u540e\u7684\u901a\u8d27\u7d27\u7f29\u3002\u57fa\u4e8e\u8fd9\u4e9b\u6570\u636e\uff0c\u6211\u4eec\u7814\u7a76\u4e86\u901a\u8d27\u81a8\u80c0\u6210\u4e3a\u516c\u4f17\u5173\u6ce8\u7126\u70b9\u7684\u6f5c\u5728\u51b3\u5b9a\u56e0\u7d20\u53ca\u5176\u540e\u679c\u3002\u4e0e\u76ee\u6807\u5bfc\u5411\u6ce8\u610f\u529b\u4e00\u81f4\uff0c\u901a\u8d27\u81a8\u80c0\u88ab\u5217\u4e3a\u5173\u6ce8\u7126\u70b9\u7684\u53ef\u80fd\u6027\u968f\u7740\u5176\u771f\u5b9e\u6536\u76ca\u76f8\u5173\u6027\u7684\u4ee3\u7406\u53d8\u91cf\u800c\u4e0a\u5347\u3002\u540c\u65f6\uff0c\u5148\u524d\u7684\u7ecf\u5386\u9884\u6d4b\u4e86\u5728\u63a7\u5236\u4e86\u6536\u76ca\u76f8\u5173\u6027\u7684\u4e00\u7cfb\u5217\u56e0\u7d20\u540e\uff0c\u53d7\u8bbf\u8005\u662f\u5426\u5c06\u901a\u8d27\u81a8\u80c0\u548c\u80fd\u6e90\u4ef7\u683c\u4f5c\u4e3a\u5173\u6ce8\u7126\u70b9\uff0c\u4e14\u5f53\u73af\u5883\u53d8\u5f97\u66f4\u52a0\u901a\u80c0\u5316\u65f6\uff0c\u8fd9\u79cd\u5173\u7cfb\u4f1a\u52a0\u5f3a\u3002\u62e5\u6709\u901a\u8d27\u81a8\u80c0\u5173\u6ce8\u7126\u70b9\u9884\u793a\u7740\u5728\u51b2\u51fb\u671f\u95f4\u4fe1\u606f\u83b7\u53d6\u548c\u901a\u8d27\u81a8\u80c0\u9884\u671f\u7684\u663e\u8457\u4e0a\u5347\u3002\u4e0e\u76ee\u6807\u6700\u4f18\u76f8\u6096\uff0c\u62e5\u6709\u901a\u8d27\u81a8\u80c0\u5173\u6ce8\u7126\u70b9\u4e0e\u504f\u79bb\u591a\u4e2a\u4e8b\u524d\u57fa\u51c6\u7684\u9884\u671f\u76f8\u5173\u3002\u6700\u540e\uff0c\u901a\u8d27\u81a8\u80c0\u6210\u4e3a\u5173\u6ce8\u7126\u70b9\u7684\u4e24\u4e2a\u5173\u952e\u51b3\u5b9a\u56e0\u7d20\u2014\u2014\u6536\u76ca\u76f8\u5173\u6027\u548c\u5148\u524d\u7ecf\u5386\u2014\u2014\u5747\u4e0e\u5728\u51b2\u51fb\u671f\u95f4\u9884\u671f\u504f\u79bb\u8fd9\u4e9b\u57fa\u51c6\u7684\u7a0b\u5ea6\u589e\u5f3a\u76f8\u5173\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag108", "journal": "REStud", "title": "Entry and Profits in an Aging Economy: The Role of Consumer Inertia", "authors": ["Gideon Bornstein"], "author_details": [{"name": "Gideon Bornstein", "affiliations": ["The Wharton School, University of Pennsylvania, USA; NBER ,"]}], "abstract": "Abstract Over the past four decades, the U.S. economy has seen a decline in the share of young firms alongside a rise in the profit share of GDP. This paper explores how population aging contributes to these twin trends through a demand-side channel. The core hypothesis is that younger households exhibit lower consumer inertia\u2014a tendency to stick with previously chosen products\u2014than older households. As demand shifts toward more inertial consumers, entry becomes harder, incumbents raise markups, and market share tilts toward larger firms. To quantify this mechanism, I develop and calibrate a firm dynamics model with overlapping generations of consumers who differ in their degree of inertia. Using detailed micro data, I show that younger households are significantly less inertial. The model implies that population aging accounts for 20%\u201330% of the observed decline in young firms and rise in profits. Reduced-form evidence across U.S. states and product categories supports the model\u2019s predictions.", "date": "2026-09-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag108", "title_zh": "\u5728\u8001\u9f84\u5316\u7ecf\u6d4e\u4e2d\u7684\u4f01\u4e1a\u8fdb\u5165\u4e0e\u5229\u6da6\uff1a\u6d88\u8d39\u8005\u60ef\u6027\u7684\u4f5c\u7528", "abstract_zh": "\u6458\u8981 \u8fc7\u53bb\u56db\u5341\u5e74\u6765\uff0c\u7f8e\u56fd\u7ecf\u6d4e\u4e2d\u5e74\u8f7b\u4f01\u4e1a\u7684\u4efd\u989d\u6301\u7eed\u4e0b\u964d\uff0c\u540c\u65f6GDP\u4e2d\u7684\u5229\u6da6\u4efd\u989d\u5374\u5728\u4e0a\u5347\u3002\u672c\u6587\u63a2\u8ba8\u4e86\u4eba\u53e3\u8001\u9f84\u5316\u5982\u4f55\u901a\u8fc7\u9700\u6c42\u4fa7\u6e20\u9053\u5bfc\u81f4\u8fd9\u4e00\u53cc\u91cd\u8d8b\u52bf\u3002\u6838\u5fc3\u5047\u8bbe\u662f\uff0c\u5e74\u8f7b\u5bb6\u5ead\u8868\u73b0\u51fa\u8f83\u4f4e\u7684\u6d88\u8d39\u8005\u60ef\u6027\u2014\u2014\u5373\u503e\u5411\u4e8e\u7ee7\u7eed\u4f7f\u7528\u4e4b\u524d\u9009\u62e9\u7684\u4ea7\u54c1\u2014\u2014\u800c\u8001\u5e74\u5bb6\u5ead\u5219\u8868\u73b0\u51fa\u66f4\u9ad8\u7684\u6d88\u8d39\u8005\u60ef\u6027\u3002\u968f\u7740\u9700\u6c42\u5411\u66f4\u5177\u60ef\u6027\u7684\u6d88\u8d39\u8005\u8f6c\u79fb\uff0c\u4f01\u4e1a\u8fdb\u5165\u53d8\u5f97\u66f4\u52a0\u56f0\u96be\uff0c\u73b0\u6709\u4f01\u4e1a\u63d0\u9ad8\u4ef7\u683c\u6ea2\u4ef7\uff0c\u5e02\u573a\u4efd\u989d\u5411\u89c4\u6a21\u8f83\u5927\u7684\u4f01\u4e1a\u503e\u659c\u3002\u4e3a\u4e86\u91cf\u5316\u8fd9\u4e00\u673a\u5236\uff0c\u6211\u6784\u5efa\u5e76\u6821\u51c6\u4e86\u4e00\u4e2a\u5305\u542b\u4e16\u4ee3\u91cd\u53e0\u6d88\u8d39\u8005\u7684\u52a8\u6001\u4f01\u4e1a\u6a21\u578b\uff0c\u5176\u4e2d\u6d88\u8d39\u8005\u5728\u60ef\u6027\u7a0b\u5ea6\u4e0a\u5b58\u5728\u5dee\u5f02\u3002\u5229\u7528\u8be6\u7ec6\u7684\u5fae\u89c2\u6570\u636e\uff0c\u6211\u8bc1\u660e\u5e74\u8f7b\u5bb6\u5ead\u786e\u5b9e\u8868\u73b0\u51fa\u663e\u8457\u66f4\u4f4e\u7684\u6d88\u8d39\u8005\u60ef\u6027\u3002\u6a21\u578b\u8868\u660e\uff0c\u4eba\u53e3\u8001\u9f84\u5316\u89e3\u91ca\u4e86\u89c2\u5bdf\u5230\u7684\u5e74\u8f7b\u4f01\u4e1a\u4efd\u989d\u4e0b\u964d\u548c\u5229\u6da6\u4e0a\u5347\u768420%\u81f330%\u3002\u7f8e\u56fd\u5404\u5dde\u53ca\u4e0d\u540c\u4ea7\u54c1\u7c7b\u522b\u4e2d\u7684\u7b80\u5316\u8bc1\u636e\u652f\u6301\u4e86\u6a21\u578b\u7684\u9884\u6d4b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag106", "journal": "REStud", "title": "The End of Oil", "authors": ["Ryan Kellogg"], "author_details": [{"name": "Ryan Kellogg", "affiliations": ["Harris School of Public Policy, University of Chicago and , USA", "National Bureau of Economic Research and , USA"]}], "abstract": "Abstract Even as global oil demand has increased in recent years, it is plausible to envision scenarios in which clean energy technologies or climate policies drive demand to essentially zero by the century\u2019s end. This article asks what such a demand decline, when anticipated, might mean for global oil supply. One possibility is a \u201cgreen paradox\u201d: producers accelerate extraction. However, because extraction requires durable capital investments, the opposite may occur: producers reduce their investment rate, decreasing extraction. To evaluate the relative strengths of these opposing mechanisms, I develop a model of global oil supply that incorporates both, among other industry features. For model inputs with the strongest empirical support, both effects are modest, with disinvestment typically outweighing the green paradox. In order for the green paradox to substantially increase cumulative global oil extraction, investments must have short time horizons, and producers\u2019 discount rates must be less than 4% real.", "date": "2026-09-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag106", "title_zh": "\u77f3\u6cb9\u7684\u7ec8\u7ed3", "abstract_zh": "\u5373\u4f7f\u8fd1\u5e74\u6765\u5168\u7403\u77f3\u6cb9\u9700\u6c42\u6301\u7eed\u589e\u957f\uff0c\u4e5f\u6709\u53ef\u80fd\u8bbe\u60f3\u4e00\u79cd\u60c5\u666f\uff0c\u5373\u6e05\u6d01\u80fd\u6e90\u6280\u672f\u6216\u6c14\u5019\u653f\u7b56\u5bfc\u81f4\u5230\u672c\u4e16\u7eaa\u672b\u77f3\u6cb9\u9700\u6c42\u51e0\u4e4e\u5f52\u96f6\u3002\u672c\u6587\u63a2\u8ba8\u4e86\u5f53\u8fd9\u79cd\u9700\u6c42\u4e0b\u964d\u88ab\u9884\u671f\u5230\u65f6\uff0c\u5bf9\u5168\u7403\u77f3\u6cb9\u4f9b\u5e94\u53ef\u80fd\u4ea7\u751f\u7684\u5f71\u54cd\u3002\u4e00\u79cd\u53ef\u80fd\u662f\u201c\u7eff\u8272\u6096\u8bba\u201d\uff1a\u751f\u4ea7\u5546\u52a0\u901f\u5f00\u91c7\u3002\u7136\u800c\uff0c\u7531\u4e8e\u5f00\u91c7\u9700\u8981\u957f\u671f\u8d44\u672c\u6295\u5165\uff0c\u76f8\u53cd\u7684\u60c5\u51b5\u4e5f\u53ef\u80fd\u53d1\u751f\uff1a\u751f\u4ea7\u5546\u51cf\u5c11\u6295\u8d44\uff0c\u4ece\u800c\u964d\u4f4e\u5f00\u91c7\u91cf\u3002\u4e3a\u4e86\u8bc4\u4f30\u8fd9\u4e24\u79cd\u76f8\u53cd\u673a\u5236\u7684\u76f8\u5bf9\u5f3a\u5ea6\uff0c\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u591a\u79cd\u884c\u4e1a\u7279\u5f81\u7684\u5168\u7403\u77f3\u6cb9\u4f9b\u5e94\u6a21\u578b\u3002\u5bf9\u4e8e\u5177\u6709\u6700\u5f3a\u5b9e\u8bc1\u652f\u6301\u7684\u6a21\u578b\u8f93\u5165\uff0c\u4e24\u79cd\u6548\u5e94\u90fd\u8f83\u4e3a\u5fae\u5f31\uff0c\u901a\u5e38\u60c5\u51b5\u4e0b\uff0c\u51cf\u8d44\u6548\u5e94\u5f3a\u4e8e\u7eff\u8272\u6096\u8bba\u3002\u82e5\u8981\u4f7f\u7eff\u8272\u6096\u8bba\u663e\u8457\u589e\u52a0\u5168\u7403\u77f3\u6cb9\u7684\u7d2f\u8ba1\u5f00\u91c7\u91cf\uff0c\u6295\u8d44\u5468\u671f\u5fc5\u987b\u5f88\u77ed\uff0c\u4e14\u751f\u4ea7\u5546\u7684\u8d34\u73b0\u7387\u5fc5\u987b\u4f4e\u4e8e4%\u7684\u5b9e\u9645\u5229\u7387\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag103", "journal": "REStud", "title": "Demographics, Wealth, and Global Imbalances in the Twenty-First Century", "authors": ["Adrien Auclert", "Hannes Malmberg", "Fr\u00e9d\u00e9ric Martenet", "Matthew Rognlie"], "author_details": [{"name": "Adrien Auclert", "affiliations": ["Stanford University, NBER and CEPR ,"]}, {"name": "Hannes Malmberg", "affiliations": ["University of Minnesota ,"]}, {"name": "Fr\u00e9d\u00e9ric Martenet", "affiliations": ["Capital Group ,"]}, {"name": "Matthew Rognlie", "affiliations": ["Northwestern University, Minneapolis Fed, and NBER ,"]}], "abstract": "Abstract We use a sufficient statistic approach to quantify the general equilibrium effects of population ageing on the returns to wealth, wealth accumulation, and global imbalances. Combining population forecasts with household survey data from twenty-five countries, we measure the compositional effect of ageing: how a changing age distribution affects wealth-to-GDP, holding the age profiles of wealth and labour income fixed. In a baseline overlapping generations model this statistic, in conjunction with cross-sectional information and two standard macro parameters, pins down general equilibrium outcomes. Since the compositional effect is positive, large, and heterogeneous across countries, our model predicts that population ageing will lower returns to wealth, increase wealth-to-GDP ratios, and widen global imbalances through the twenty-first century. These conclusions extend to a richer model in which bequests, individual savings, and the tax-and-transfer system all respond to demographic change.", "date": "2026-09-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag103", "title_zh": "\u4eba\u53e3\u7ed3\u6784\u3001\u8d22\u5bcc\u4e0e\u4e8c\u5341\u4e00\u4e16\u7eaa\u7684\u5168\u7403\u5931\u8861", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u91c7\u7528\u4e00\u4e2a\u5145\u5206\u7edf\u8ba1\u91cf\u65b9\u6cd5\uff0c\u91cf\u5316\u4eba\u53e3\u8001\u9f84\u5316\u5bf9\u8d22\u5bcc\u56de\u62a5\u3001\u8d22\u5bcc\u79ef\u7d2f\u4ee5\u53ca\u5168\u7403\u5931\u8861\u7684\u4e00\u822c\u5747\u8861\u6548\u5e94\u3002\u7ed3\u5408\u4eba\u53e3\u9884\u6d4b\u6570\u636e\u4e0e\u6765\u81ea\u4e8c\u5341\u4e94\u4e2a\u56fd\u5bb6\u7684\u5bb6\u5ead\u8c03\u67e5\u6570\u636e\uff0c\u6211\u4eec\u6d4b\u91cf\u4e86\u8001\u9f84\u5316\u5e26\u6765\u7684\u7ed3\u6784\u6548\u5e94\uff1a\u5373\u5e74\u9f84\u7ed3\u6784\u53d8\u5316\u5982\u4f55\u5f71\u54cd\u8d22\u5bcc\u5bf9GDP\u7684\u6bd4\u7387\uff0c\u540c\u65f6\u4fdd\u6301\u8d22\u5bcc\u548c\u52b3\u52a8\u6536\u5165\u7684\u5e74\u9f84\u5206\u5e03\u4e0d\u53d8\u3002\u5728\u57fa\u51c6\u7684\u91cd\u53e0\u4e16\u4ee3\u6a21\u578b\u4e2d\uff0c\u8be5\u7edf\u8ba1\u91cf\u7ed3\u5408\u6a2a\u622a\u9762\u4fe1\u606f\u4ee5\u53ca\u4e24\u4e2a\u6807\u51c6\u5b8f\u89c2\u53c2\u6570\uff0c\u80fd\u591f\u786e\u5b9a\u4e00\u822c\u5747\u8861\u7ed3\u679c\u3002\u7531\u4e8e\u7ed3\u6784\u6548\u5e94\u4e3a\u6b63\u3001\u663e\u8457\u4e14\u5404\u56fd\u4e4b\u95f4\u5b58\u5728\u5f02\u8d28\u6027\uff0c\u6211\u4eec\u7684\u6a21\u578b\u9884\u6d4b\uff0c\u4eba\u53e3\u8001\u9f84\u5316\u5c06\u5728\u4e8c\u5341\u4e00\u4e16\u7eaa\u5bfc\u81f4\u8d22\u5bcc\u56de\u62a5\u4e0b\u964d\u3001\u8d22\u5bcc\u5bf9GDP\u6bd4\u7387\u4e0a\u5347\u4ee5\u53ca\u5168\u7403\u5931\u8861\u7684\u6269\u5927\u3002\u8fd9\u4e9b\u7ed3\u8bba\u4e5f\u9002\u7528\u4e8e\u4e00\u4e2a\u66f4\u4e30\u5bcc\u7684\u6a21\u578b\uff0c\u5176\u4e2d\u9057\u4ea7\u3001\u4e2a\u4eba\u50a8\u84c4\u4ee5\u53ca\u7a0e\u6536\u548c\u8f6c\u79fb\u652f\u4ed8\u4f53\u7cfb\u5747\u4f1a\u54cd\u5e94\u4eba\u53e3\u7ed3\u6784\u7684\u53d8\u5316\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.04540", "journal": "MS", "title": "Sequential Search Transformer: A Deep Structural Econometric Model", "authors": ["Yicheng Song", "Tianshu Sun"], "author_details": [{"name": "Yicheng Song", "affiliations": ["Carlson School of Management, University of Minnesota, Minneapolis, Minnesota 55455"]}, {"name": "Tianshu Sun", "affiliations": ["Cheung Kong Graduate School of Business, Beijing 100006, China"]}], "abstract": "Modeling and leveraging consumers\u2019 dynamic search behaviors presents significant business opportunities. Although deep learning methods excel at processing vast consumer data for predictive tasks, their opaque nature limits interpretability and fails to explicitly model consumer decision making. In contrast, economic theory suggests that consumers follow a sequential search strategy, evaluating alternatives until they find the best match for their preferences. To bridge this gap, we propose the sequential search transformer (SST), a deep structural econometric model that integrates deep learning with sequential search theory to model search and purchase decisions. SST unifies these two approaches into an end-to-end trainable model, improving both predictive accuracy and policy evaluation capabilities. Unlike conventional deep learning models, SST explicitly models consumer decision making, and unlike existing sequential search models, it enables consumer behavior modeling across sessions and sequentially resolves utility uncertainty for searched items. We provide a theoretical analysis of the identification strategy for the SST model and show that all parameters can be identified under the proposed framework. Then, we apply SST to a data set with detailed clickstream data collected from a U.S. e-commerce website. Empirical evaluations show that SST outperforms state-of-the-art deep learning and structural models in predicting consumer searches and purchases. Moreover, policy experiments demonstrate SST\u2019s effectiveness in optimizing product recommendations and new product promotion strategies, ultimately enhancing consumers experience and driving revenue growth.", "date": "2026-09-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.04540", "title_zh": "\u987a\u5e8f\u641c\u7d22\u53d8\u6362\u5668\uff1a\u4e00\u79cd\u6df1\u5ea6\u7ed3\u6784\u8ba1\u91cf\u7ecf\u6d4e\u6a21\u578b", "abstract_zh": "\u5efa\u6a21\u548c\u5229\u7528\u6d88\u8d39\u8005\u52a8\u6001\u641c\u7d22\u884c\u4e3a\u5177\u6709\u91cd\u8981\u7684\u5546\u4e1a\u4ef7\u503c\u3002\u5c3d\u7ba1\u6df1\u5ea6\u5b66\u4e60\u65b9\u6cd5\u5728\u5904\u7406\u5927\u91cf\u6d88\u8d39\u8005\u6570\u636e\u4ee5\u5b8c\u6210\u9884\u6d4b\u4efb\u52a1\u65b9\u9762\u8868\u73b0\u51fa\u8272\uff0c\u4f46\u5176\u9ed1\u7bb1\u7279\u6027\u9650\u5236\u4e86\u53ef\u89e3\u91ca\u6027\uff0c\u4e14\u672a\u80fd\u663e\u5f0f\u5efa\u6a21\u6d88\u8d39\u8005\u7684\u51b3\u7b56\u8fc7\u7a0b\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u7ecf\u6d4e\u7406\u8bba\u6307\u51fa\uff0c\u6d88\u8d39\u8005\u9075\u5faa\u987a\u5e8f\u641c\u7d22\u7b56\u7565\uff0c\u5373\u5728\u627e\u5230\u6700\u7b26\u5408\u5176\u504f\u597d\u7684\u9009\u9879\u4e4b\u524d\uff0c\u6301\u7eed\u8bc4\u4f30\u5404\u79cd\u66ff\u4ee3\u65b9\u6848\u3002\u4e3a\u5f25\u5408\u8fd9\u4e00\u5dee\u8ddd\uff0c\u6211\u4eec\u63d0\u51fa\u4e86\u987a\u5e8f\u641c\u7d22\u53d8\u6362\u5668\uff08SST\uff09\uff0c\u4e00\u79cd\u5c06\u6df1\u5ea6\u5b66\u4e60\u4e0e\u987a\u5e8f\u641c\u7d22\u7406\u8bba\u76f8\u7ed3\u5408\u7684\u6df1\u5ea6\u7ed3\u6784\u8ba1\u91cf\u7ecf\u6d4e\u6a21\u578b\uff0c\u7528\u4e8e\u5efa\u6a21\u641c\u7d22\u4e0e\u8d2d\u4e70\u51b3\u7b56\u3002SST\u5c06\u8fd9\u4e24\u79cd\u65b9\u6cd5\u6574\u5408\u4e3a\u4e00\u4e2a\u7aef\u5230\u7aef\u53ef\u8bad\u7ec3\u7684\u6a21\u578b\uff0c\u4e0d\u4ec5\u63d0\u5347\u4e86\u9884\u6d4b\u51c6\u786e\u6027\uff0c\u4e5f\u589e\u5f3a\u4e86\u653f\u7b56\u8bc4\u4f30\u80fd\u529b\u3002\u4e0e\u4f20\u7edf\u7684\u6df1\u5ea6\u5b66\u4e60\u6a21\u578b\u4e0d\u540c\uff0cSST\u663e\u5f0f\u5730\u5efa\u6a21\u4e86\u6d88\u8d39\u8005\u7684\u51b3\u7b56\u8fc7\u7a0b\uff1b\u4e0e\u73b0\u6709\u7684\u987a\u5e8f\u641c\u7d22\u6a21\u578b\u76f8\u6bd4\uff0c\u5b83\u80fd\u591f\u8de8\u4f1a\u8bdd\u5efa\u6a21\u6d88\u8d39\u8005\u884c\u4e3a\uff0c\u5e76\u5bf9\u5df2\u641c\u7d22\u5546\u54c1\u7684\u6548\u7528\u4e0d\u786e\u5b9a\u6027\u8fdb\u884c\u987a\u5e8f\u5316\u89e3\u3002\u6211\u4eec\u5bf9SST\u6a21\u578b\u7684\u8bc6\u522b\u7b56\u7565\u8fdb\u884c\u4e86\u7406\u8bba\u5206\u6790\uff0c\u8bc1\u660e\u5728\u6240\u63d0\u51fa\u7684\u6846\u67b6\u4e0b\u6240\u6709\u53c2\u6570\u5747\u53ef\u88ab\u8bc6\u522b\u3002\u968f\u540e\uff0c\u6211\u4eec\u5c06SST\u5e94\u7528\u4e8e\u4e00\u4e2a\u6765\u81ea\u7f8e\u56fd\u7535\u5b50\u5546\u52a1\u7f51\u7ad9\u7684\u8be6\u7ec6\u70b9\u51fb\u6d41\u6570\u636e\u96c6\u3002\u5b9e\u8bc1\u8bc4\u4f30\u8868\u660e\uff0cSST\u5728\u9884\u6d4b\u6d88\u8d39\u8005\u641c\u7d22\u548c\u8d2d\u4e70\u884c\u4e3a\u65b9\u9762\u4f18\u4e8e\u5f53\u524d\u6700\u5148\u8fdb\u7684\u6df1\u5ea6\u5b66\u4e60\u548c\u7ed3\u6784\u5316\u6a21\u578b\u3002\u6b64\u5916\uff0c\u653f\u7b56\u5b9e\u9a8c\u663e\u793aSST\u5728\u4f18\u5316\u4ea7\u54c1\u63a8\u8350\u548c\u65b0\u4ea7\u54c1\u63a8\u5e7f\u7b56\u7565\u65b9\u9762\u5177\u6709\u663e\u8457\u6548\u679c\uff0c\u6700\u7ec8\u63d0\u5347\u4e86\u6d88\u8d39\u8005\u4f53\u9a8c\u5e76\u63a8\u52a8\u4e86\u6536\u5165\u589e\u957f\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2024.07171", "journal": "MS", "title": "Crossborder Carbon Taxes and Shareholder Wealth", "authors": ["Marta Alonso", "Martin Jacob", "Gaizka Ormazabal", "Robert Raney"], "author_details": [{"name": "Marta Alonso", "affiliations": ["Department of Accounting and Finance, CUNEF University, 28040 Madrid, Spain"]}, {"name": "Martin Jacob", "affiliations": ["Department of Accounting and Control, IESE Business School, 08034 Barcelona, Spain"]}, {"name": "Gaizka Ormazabal", "affiliations": ["Department of Accounting and Control, IESE Business School, 08034 Barcelona, Spain"]}, {"name": "Robert Raney", "affiliations": ["Department of Accounting and Control, IESE Business School, 08034 Barcelona, Spain"]}], "abstract": "This paper examines the effect of crossborder carbon taxes on shareholder wealth. Using stock price reactions to key announcements of the European Union (EU) carbon border adjustment mechanism (CBAM), we find that EU purchasers of CBAM-covered products experience significantly lower returns than non-European producers of such products. The effect is strongest for EU purchasers with non-EU supply chains. Further cross-sectional analyses show that these negative reactions are more pronounced when CBAM-related costs are higher and when firms have a lower ability to pass them on to their trading partners. Overall, the evidence suggests that equity markets expect crossborder carbon pricing on imports to be costly for EU firms.", "date": "2026-09-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07171", "title_zh": "\u8de8\u5883\u78b3\u7a0e\u4e0e\u80a1\u4e1c\u8d22\u5bcc", "abstract_zh": "\u672c\u6587\u7814\u7a76\u8de8\u5883\u78b3\u7a0e\u5bf9\u80a1\u4e1c\u8d22\u5bcc\u7684\u5f71\u54cd\u3002\u5229\u7528\u6b27\u76df\u78b3\u8fb9\u5883\u8c03\u8282\u673a\u5236\uff08CBAM\uff09\u5173\u952e\u516c\u544a\u5f15\u53d1\u7684\u80a1\u4ef7\u53cd\u5e94\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u8d2d\u4e70 CBAM \u8986\u76d6\u4ea7\u54c1\u7684\u6b27\u76df\u4f01\u4e1a\uff0c\u5176\u80a1\u7968\u6536\u76ca\u663e\u8457\u4f4e\u4e8e\u751f\u4ea7\u8fd9\u7c7b\u4ea7\u54c1\u7684\u975e\u6b27\u6d32\u4f01\u4e1a\u3002\u5bf9\u4e8e\u4f9b\u5e94\u94fe\u6d89\u53ca\u6b27\u76df\u4ee5\u5916\u5730\u533a\u7684\u6b27\u76df\u91c7\u8d2d\u4f01\u4e1a\uff0c\u8fd9\u4e00\u6548\u5e94\u6700\u5f3a\u3002\u8fdb\u4e00\u6b65\u7684\u6a2a\u622a\u9762\u5206\u6790\u663e\u793a\uff0c\u5f53 CBAM \u76f8\u5173\u6210\u672c\u66f4\u9ad8\u3001\u4e14\u4f01\u4e1a\u5411\u8d38\u6613\u4f19\u4f34\u8f6c\u5ac1\u8fd9\u4e9b\u6210\u672c\u7684\u80fd\u529b\u8f83\u5f31\u65f6\uff0c\u8d1f\u5411\u53cd\u5e94\u66f4\u660e\u663e\u3002\u603b\u4f53\u800c\u8a00\uff0c\u8bc1\u636e\u8868\u660e\uff0c\u80a1\u7968\u5e02\u573a\u9884\u671f\u9488\u5bf9\u8fdb\u53e3\u54c1\u7684\u8de8\u5883\u78b3\u5b9a\u4ef7\u5c06\u7ed9\u6b27\u76df\u4f01\u4e1a\u5e26\u6765\u6210\u672c\u3002", "translation_source": "\u9996\u7248\u6837\u4f8b\uff1a\u7531 Codex \u6839\u636e\u516c\u5f00\u6458\u8981\u7ffb\u8bd1\uff0c\u975e Qwen \u8f93\u51fa", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/restud/rdag105", "journal": "REStud", "title": "Machine Learning for Dynamic Incentive Problems", "authors": ["Philipp Renner", "Simon Scheidegger"], "author_details": [{"name": "Philipp Renner", "affiliations": ["Department of Economics, Lancaster University ,"]}, {"name": "Simon Scheidegger", "affiliations": ["Department of Economics, University of Lausanne , and ,", "Grantham Research Institute, LSE , and ,"]}], "abstract": "Abstract We present a flexible and scalable computational framework integrating machine learning and optimization theory to solve dynamic adverse selection models with persistent private information and many types. Our approach reformulates the model into a numerically tractable structure that bypasses set-valued dynamic programming; we formally prove that, under verifiable conditions, this relaxation yields the solution to the original problem. The recast problem is solved via a parallelized value function iteration algorithm, where high-dimensional, nonlinear functions are approximated using Gaussian process regression combined with Bayesian active learning. We apply our framework to two previously intractable models: one with persistent hidden information involving up to ten types and another incorporating multiple persistent types and overreporting. Validation against known solutions and rigorous credibility measures confirms accuracy. Allowing overreporting significantly alters long-run contract outcomes, concentrating consumption away from extremes and smoothing utility promises over time.", "date": "2026-09-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag105", "title_zh": "\u673a\u5668\u5b66\u4e60\u5728\u52a8\u6001\u6fc0\u52b1\u95ee\u9898\u4e2d\u7684\u5e94\u7528", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u7075\u6d3b\u4e14\u53ef\u6269\u5c55\u7684\u8ba1\u7b97\u6846\u67b6\uff0c\u5c06\u673a\u5668\u5b66\u4e60\u4e0e\u4f18\u5316\u7406\u8bba\u76f8\u7ed3\u5408\uff0c\u7528\u4e8e\u6c42\u89e3\u5177\u6709\u6301\u4e45\u79c1\u6709\u4fe1\u606f\u548c\u591a\u79cd\u7c7b\u578b\u7279\u5f81\u7684\u52a8\u6001\u9006\u5411\u9009\u62e9\u6a21\u578b\u3002\u6211\u4eec\u7684\u65b9\u6cd5\u5c06\u6a21\u578b\u91cd\u65b0\u8868\u8ff0\u4e3a\u4e00\u4e2a\u6570\u503c\u4e0a\u53ef\u5904\u7406\u7684\u7ed3\u6784\uff0c\u4ece\u800c\u907f\u514d\u4e86\u96c6\u5408\u503c\u52a8\u6001\u89c4\u5212\uff1b\u6211\u4eec\u6b63\u5f0f\u8bc1\u660e\uff0c\u5728\u53ef\u9a8c\u8bc1\u7684\u6761\u4ef6\u4e0b\uff0c\u8fd9\u79cd\u677e\u5f1b\u5904\u7406\u80fd\u591f\u5f97\u5230\u539f\u95ee\u9898\u7684\u89e3\u3002\u91cd\u6784\u540e\u7684\u6a21\u578b\u901a\u8fc7\u5e76\u884c\u5316\u7684\u4ef7\u503c\u51fd\u6570\u8fed\u4ee3\u7b97\u6cd5\u6c42\u89e3\uff0c\u5176\u4e2d\u9ad8\u7ef4\u975e\u7ebf\u6027\u51fd\u6570\u91c7\u7528\u9ad8\u65af\u8fc7\u7a0b\u56de\u5f52\u7ed3\u5408\u8d1d\u53f6\u65af\u4e3b\u52a8\u5b66\u4e60\u8fdb\u884c\u8fd1\u4f3c\u3002\u6211\u4eec\u5c06\u8be5\u6846\u67b6\u5e94\u7528\u4e8e\u4e24\u4e2a\u6b64\u524d\u96be\u4ee5\u6c42\u89e3\u7684\u6a21\u578b\uff1a\u4e00\u4e2a\u5305\u542b\u6700\u591a\u5341\u79cd\u7c7b\u578b\u4e14\u5b58\u5728\u6301\u4e45\u9690\u85cf\u4fe1\u606f\u7684\u6a21\u578b\uff0c\u4ee5\u53ca\u4e00\u4e2a\u5305\u542b\u591a\u79cd\u6301\u4e45\u7c7b\u578b\u5e76\u5b58\u5728\u8fc7\u5ea6\u62a5\u544a\u7684\u6a21\u578b\u3002\u901a\u8fc7\u4e0e\u5df2\u77e5\u89e3\u7684\u5bf9\u6bd4\u4ee5\u53ca\u4e25\u683c\u7684\u53ef\u4fe1\u5ea6\u5ea6\u91cf\uff0c\u9a8c\u8bc1\u4e86\u65b9\u6cd5\u7684\u51c6\u786e\u6027\u3002\u5141\u8bb8\u8fc7\u5ea6\u62a5\u544a\u663e\u8457\u6539\u53d8\u4e86\u957f\u671f\u5408\u540c\u7ed3\u679c\uff0c\u4f7f\u6d88\u8d39\u5411\u6781\u7aef\u503c\u96c6\u4e2d\uff0c\u5e76\u5728\u65f6\u95f4\u4e0a\u5e73\u6ed1\u4e86\u6548\u7528\u627f\u8bfa\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1093/restud/rdag099", "journal": "REStud", "title": "Measuring Markets for Network Goods", "authors": ["Leonardo Bursztyn", "Matthew Gentzkow", "Rafael Jim\u00e9nez-Dur\u00e1n", "Aaron Leonard", "Filip Milojevi\u0107", "Christopher Roth"], "author_details": [{"name": "Leonardo Bursztyn", "affiliations": ["University of Chicago and NBER ,"]}, {"name": "Matthew Gentzkow", "affiliations": ["Stanford University and NBER ,"]}, {"name": "Rafael Jim\u00e9nez-Dur\u00e1n", "affiliations": ["Bocconi University, IGIER, CESifo, CEPR, and Stigler Center ,"]}, {"name": "Aaron Leonard", "affiliations": ["University of Chicago ,"]}, {"name": "Filip Milojevi\u0107", "affiliations": ["Massachusetts Institute of Technology ,"]}, {"name": "Christopher Roth", "affiliations": ["University of Cologne, CESifo, and CEPR ,"]}], "abstract": "Abstract Market definition is challenging in settings with network effects, where substitution patterns depend on changes in network size. We study these effects in the context of social media. We conduct an incentivized experiment comparing substitution in response to a proposed U.S. TikTok ban, in which all users simultaneously leave the app, with substitution when only a single user deactivates. We find substantially higher valuations of alternative social apps under a collective TikTok ban than under an individual TikTok deactivation. Mechanism evidence shows that both anticipated content-supply shifts and social coordination partly explain the wedge, with the relative importance of each channel varying across platforms. We then show that a collective time limit challenge, where peers jointly reduce TikTok and Instagram use, leads to more time spent on alternative social apps than has been observed in prior individual deactivation experiments. Together, our results suggest that individual-level substitution estimates can be an unreliable guide to market definition for network goods.", "date": "2026-09-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag099", "title_zh": "\u7f51\u7edc\u5546\u54c1\u5e02\u573a\u7684\u8861\u91cf", "abstract_zh": "\u5728\u5b58\u5728\u7f51\u7edc\u6548\u5e94\u7684\u573a\u666f\u4e2d\uff0c\u5e02\u573a\u754c\u5b9a\u5177\u6709\u6311\u6218\u6027\uff0c\u56e0\u4e3a\u66ff\u4ee3\u6a21\u5f0f\u4f9d\u8d56\u4e8e\u7f51\u7edc\u89c4\u6a21\u7684\u53d8\u5316\u3002\u6211\u4eec\u4ee5\u793e\u4ea4\u5a92\u4f53\u4e3a\u80cc\u666f\u7814\u7a76\u8fd9\u4e9b\u6548\u5e94\u3002\u6211\u4eec\u8fdb\u884c\u4e86\u4e00\u9879\u6fc0\u52b1\u6027\u5b9e\u9a8c\uff0c\u6bd4\u8f83\u5728\u63d0\u8bae\u7981\u6b62\u7f8e\u56fdTikTok\u5e94\u7528\u65f6\u6240\u6709\u7528\u6237\u540c\u65f6\u9000\u51fa\u5e94\u7528\u4e0e\u4ec5\u5355\u4e2a\u7528\u6237\u9000\u51fa\u65f6\u7684\u66ff\u4ee3\u884c\u4e3a\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u96c6\u4f53\u7981\u6b62TikTok\u7684\u60c5\u51b5\u4e0b\uff0c\u7528\u6237\u5bf9\u5176\u4ed6\u793e\u4ea4\u5e94\u7528\u7684\u4f30\u503c\u663e\u8457\u9ad8\u4e8e\u4ec5\u5355\u4e2a\u7528\u6237\u9000\u51fa\u7684\u60c5\u51b5\u3002\u673a\u5236\u8bc1\u636e\u8868\u660e\uff0c\u9884\u671f\u5185\u5bb9\u4f9b\u7ed9\u53d8\u5316\u4ee5\u53ca\u793e\u4ea4\u534f\u8c03\u5728\u9020\u6210\u8fd9\u4e00\u5dee\u5f02\u4e2d\u8d77\u5230\u4e86\u90e8\u5206\u4f5c\u7528\uff0c\u4e14\u4e0d\u540c\u5e73\u53f0\u4e2d\u5404\u6e20\u9053\u7684\u91cd\u8981\u6027\u6709\u6240\u4e0d\u540c\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u53d1\u73b0\uff0c\u96c6\u4f53\u65f6\u95f4\u9650\u5236\u6311\u6218\uff08\u5373\u7528\u6237\u5171\u540c\u51cf\u5c11TikTok\u548cInstagram\u7684\u4f7f\u7528\uff09\u5bfc\u81f4\u5728\u66ff\u4ee3\u793e\u4ea4\u5e94\u7528\u4e0a\u82b1\u8d39\u7684\u65f6\u95f4\uff0c\u8d85\u8fc7\u4e86\u4ee5\u5f80\u5355\u4e2a\u9000\u51fa\u5b9e\u9a8c\u4e2d\u89c2\u5bdf\u5230\u7684\u6c34\u5e73\u3002\u7efc\u5408\u6765\u770b\uff0c\u4e2a\u4f53\u5c42\u9762\u7684\u66ff\u4ee3\u4f30\u8ba1\u53ef\u80fd\u65e0\u6cd5\u53ef\u9760\u5730\u7528\u4e8e\u7f51\u7edc\u5546\u54c1\u7684\u5e02\u573a\u754c\u5b9a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/restud/rdag102", "journal": "REStud", "title": "Company Wage Policy in a Low-Wage Labour Market", "authors": ["Giulia Giupponi", "Stephen Machin"], "author_details": [{"name": "Giulia Giupponi", "affiliations": ["Bocconi University, Italy and CEPR , France"]}, {"name": "Stephen Machin", "affiliations": ["Department of Economics and Centre for Economic Performance, London School of Economics, UK and CEPR , France"]}], "abstract": "Abstract We study how firms set wages for their employees when they can legally age-discriminate across workers. We exploit an age-specific minimum wage change in the UK, which raised the minimum applying to workers aged 25 and over, leaving unchanged the minima for younger workers. Using matched employer-employee data on a low-paying sector, we show large, positive wage spillovers on workers aged under 25, which arise within firms from company wage policy. Pay equity norms offer the most parsimonious explanation for the emergence of spillovers. The effects that we document also operate in other low-paying sectors of the UK labour market.", "date": "2026-09-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag102", "title_zh": "\u4f4e\u5de5\u8d44\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u4f01\u4e1a\u7684\u5de5\u8d44\u653f\u7b56", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u4f01\u4e1a\u5728\u5408\u6cd5\u5e74\u9f84\u6b67\u89c6\u7684\u60c5\u51b5\u4e0b\u5982\u4f55\u8bbe\u5b9a\u5458\u5de5\u5de5\u8d44\u3002\u6211\u4eec\u5229\u7528\u82f1\u56fd\u4e00\u9879\u9488\u5bf9\u7279\u5b9a\u5e74\u9f84\u7fa4\u4f53\u7684\u6700\u4f4e\u5de5\u8d44\u8c03\u6574\uff0c\u8be5\u8c03\u6574\u63d0\u9ad8\u4e8625\u5c81\u53ca\u4ee5\u4e0a\u5458\u5de5\u7684\u6700\u4f4e\u5de5\u8d44\u6807\u51c6\uff0c\u800c\u5bf9\u5e74\u8f7b\u5458\u5de5\u7684\u6700\u4f4e\u5de5\u8d44\u4fdd\u6301\u4e0d\u53d8\u3002\u57fa\u4e8e\u4f4e\u6536\u5165\u884c\u4e1a\u7684\u5339\u914d\u4f01\u4e1a-\u5458\u5de5\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u5bf925\u5c81\u4ee5\u4e0b\u5458\u5de5\u5b58\u5728\u663e\u8457\u7684\u6b63\u5411\u5de5\u8d44\u6ea2\u51fa\u6548\u5e94\uff0c\u8fd9\u4e9b\u6548\u5e94\u6e90\u4e8e\u4f01\u4e1a\u5185\u90e8\u7684\u5de5\u8d44\u653f\u7b56\u3002\u85aa\u916c\u516c\u5e73\u89c4\u8303\u4e3a\u8fd9\u79cd\u6ea2\u51fa\u6548\u5e94\u7684\u51fa\u73b0\u63d0\u4f9b\u4e86\u6700\u7b80\u6d01\u7684\u89e3\u91ca\u3002\u6211\u4eec\u6240\u89c2\u5bdf\u5230\u7684\u5f71\u54cd\u4e5f\u5b58\u5728\u4e8e\u82f1\u56fd\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u7684\u5176\u4ed6\u4f4e\u6536\u5165\u884c\u4e1a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag101", "journal": "REStud", "title": "Stockups, Stockouts, and the Role for Strategic Reserves", "authors": ["Brett Green", "Cyrus Mevorach", "Curtis R Taylor"], "author_details": [{"name": "Brett Green", "affiliations": ["Olin Business School, Washington University in St. Louis , USA"]}, {"name": "Cyrus Mevorach", "affiliations": ["Olin Business School, Washington University in St. Louis , USA"]}, {"name": "Curtis R Taylor", "affiliations": ["Department of Economics, Duke University , USA"]}], "abstract": "Abstract We study how supply disruptions interact with monopoly pricing, inventory management, and consumer stockpiling in a continuous-time model. Pre-emption incentives\u2014consumers prefer to stock up before a price hike while the firm prefers to hike before consumers stock up\u2014lead to an equilibrium with gradual stockpiling and endogenous uncertainty over the timing of a price hike, which can trigger a run at the disruption onset. Consumer storage introduces welfare losses from randomized pricing, but can also strengthen the firm\u2019s incentive to hold buffer stock. Rationing, price controls, and reserve mandates can each improve welfare, but only strategic government reserves can implement the social optimum.", "date": "2026-09-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag101", "title_zh": "\u56e4\u8d27\u3001\u7f3a\u8d27\u4e0e\u6218\u7565\u50a8\u5907\u7684\u4f5c\u7528", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4f9b\u5e94\u4e2d\u65ad\u5982\u4f55\u4e0e\u5784\u65ad\u5b9a\u4ef7\u3001\u5e93\u5b58\u7ba1\u7406\u4ee5\u53ca\u6d88\u8d39\u8005\u56e4\u8d27\u76f8\u4e92\u4f5c\u7528\uff0c\u91c7\u7528\u8fde\u7eed\u65f6\u95f4\u6a21\u578b\u8fdb\u884c\u5206\u6790\u3002\u6d88\u8d39\u8005\u503e\u5411\u4e8e\u5728\u4ef7\u683c\u4e0a\u6da8\u524d\u63d0\u524d\u56e4\u8d27\uff0c\u800c\u4f01\u4e1a\u5219\u5e0c\u671b\u5728\u6d88\u8d39\u8005\u56e4\u8d27\u4e4b\u524d\u63d0\u4ef7\uff0c\u8fd9\u79cd\u63d0\u524d\u884c\u52a8\u7684\u6fc0\u52b1\u5bfc\u81f4\u5747\u8861\u4e2d\u51fa\u73b0\u6e10\u8fdb\u5f0f\u7684\u56e4\u8d27\u884c\u4e3a\uff0c\u5e76\u4ea7\u751f\u5bf9\u4ef7\u683c\u4e0a\u8c03\u65f6\u95f4\u7684\u5185\u751f\u4e0d\u786e\u5b9a\u6027\uff0c\u8fd9\u53ef\u80fd\u5728\u4e2d\u65ad\u53d1\u751f\u65f6\u5f15\u53d1\u62a2\u8d2d\u3002\u6d88\u8d39\u8005\u50a8\u5b58\u884c\u4e3a\u5bfc\u81f4\u968f\u673a\u5b9a\u4ef7\u5e26\u6765\u7684\u798f\u5229\u635f\u5931\uff0c\u4f46\u540c\u65f6\u4e5f\u589e\u5f3a\u4e86\u4f01\u4e1a\u4fdd\u6301\u7f13\u51b2\u5e93\u5b58\u7684\u52a8\u529b\u3002\u914d\u7ed9\u3001\u4ef7\u683c\u7ba1\u5236\u548c\u50a8\u5907\u8981\u6c42\u5747\u80fd\u6539\u5584\u798f\u5229\uff0c\u4f46\u53ea\u6709\u6218\u7565\u6027\u7684\u653f\u5e9c\u50a8\u5907\u624d\u80fd\u5b9e\u73b0\u793e\u4f1a\u6700\u4f18\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag075", "journal": "RFS", "title": "Corporate Financial Constraints, Minimum Wage Policies, and Employment", "authors": ["Alona Bilokha", "Iftekhar Hasan", "Stefano Manfredonia", "Ronald W Masulis"], "author_details": [{"name": "Alona Bilokha", "affiliations": ["University of North Florida ,"]}, {"name": "Iftekhar Hasan", "affiliations": ["Fordham University, the United States, Bank of Finland , , and ,", "University of Sydney , , and ,"]}, {"name": "Stefano Manfredonia", "affiliations": ["Fordham University ,"]}, {"name": "Ronald W Masulis", "affiliations": ["University of New South Wales ,"]}], "abstract": "Abstract We examine how corporate financial constraints shape firms\u2019 employment responses to minimum wage policies. Exploiting the federal minimum wage increase during the financial crisis and variation in firms\u2019 debt maturity structures at the crisis onset, we find that financially constrained firms significantly reduce employment. To assess external validity, we analyze staggered state-level minimum wage increases over time. Consistent with the crisis evidence, employment declines in establishments of constrained firms, whereas unconstrained firms expand in areas with a larger supply of minimum-wage workers and higher turnover. Our results highlight the central role of financial constraints in mediating labor policy effects.", "date": "2026-09-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag075", "title_zh": "\u4f01\u4e1a\u8d22\u52a1\u7ea6\u675f\u3001\u6700\u4f4e\u5de5\u8d44\u653f\u7b56\u4e0e\u5c31\u4e1a", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u4f01\u4e1a\u8d22\u52a1\u7ea6\u675f\u5982\u4f55\u5f71\u54cd\u5176\u5bf9\u6700\u4f4e\u5de5\u8d44\u653f\u7b56\u7684\u5c31\u4e1a\u53cd\u5e94\u3002\u5229\u7528\u91d1\u878d\u5371\u673a\u671f\u95f4\u8054\u90a6\u6700\u4f4e\u5de5\u8d44\u4e0a\u8c03\u4ee5\u53ca\u4f01\u4e1a\u503a\u52a1\u671f\u9650\u7ed3\u6784\u5728\u5371\u673a\u521d\u671f\u7684\u5dee\u5f02\uff0c\u6211\u4eec\u53d1\u73b0\u8d22\u52a1\u53d7\u9650\u7684\u4f01\u4e1a\u663e\u8457\u51cf\u5c11\u4e86\u5c31\u4e1a\u3002\u4e3a\u4e86\u68c0\u9a8c\u5916\u90e8\u6709\u6548\u6027\uff0c\u6211\u4eec\u5206\u6790\u4e86\u5404\u5dde\u5728\u4e0d\u540c\u65f6\u671f\u5b9e\u65bd\u7684\u9636\u68af\u5f0f\u6700\u4f4e\u5de5\u8d44\u4e0a\u8c03\u3002\u7ed3\u679c\u4e0e\u91d1\u878d\u5371\u673a\u671f\u95f4\u7684\u8bc1\u636e\u4e00\u81f4\uff0c\u8d22\u52a1\u53d7\u9650\u4f01\u4e1a\u7684\u5c31\u4e1a\u51fa\u73b0\u4e0b\u964d\uff0c\u800c\u65e0\u8d22\u52a1\u7ea6\u675f\u7684\u4f01\u4e1a\u5219\u5728\u6700\u4f4e\u5de5\u8d44\u5de5\u4eba\u4f9b\u7ed9\u8f83\u591a\u4e14\u79bb\u804c\u7387\u8f83\u9ad8\u7684\u5730\u533a\u6269\u5f20\u3002\u6211\u4eec\u7684\u7ed3\u679c\u51f8\u663e\u4e86\u8d22\u52a1\u7ea6\u675f\u5728\u52b3\u52a8\u653f\u7b56\u6548\u5e94\u4f20\u5bfc\u4e2d\u7684\u6838\u5fc3\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1287/mnsc.2025.03155", "journal": "MS", "title": "From Trees to Treewidth: Inventory Management in Complex Supply Chain Networks", "authors": ["Philippe Blaettchen", "Andre P. Calmon", "Georgina Hall", "Mohit Tawarmalani"], "author_details": [{"name": "Philippe Blaettchen", "affiliations": ["Lee Kong Chian School of Business, Singapore Management University, 178899 Singapore"]}, {"name": "Andre P. Calmon", "affiliations": ["Scheller College of Business, Georgia Institute of Technology, Atlanta, Georgia 30308"]}, {"name": "Georgina Hall", "affiliations": ["Decision Sciences, INSEAD, 77305 Fontainebleau, France"]}, {"name": "Mohit Tawarmalani", "affiliations": ["Mitch Daniels School of Business, Purdue University, West Lafayette, Indiana 47907"]}], "abstract": "We propose an exact linear programming (LP)-based solution approach to the Guaranteed Service Model (GSM), one of the most widely applied models for optimizing safety stock placement in supply chain networks. Our approach handles any directed acyclic network and any cost function that depends on a stage\u2019s incoming and outgoing service times. It scales polynomially in the number of nodes n in the network, pseudo-polynomially with respect to the bit size of the maximum replenishment time M, and (for fixed M) exponentially in its treewidth, which quantifies how \u201ctree-like\u201d a network is and can be much smaller than n. This contrasts with existing approaches, which scale exponentially in n. The proof of exactness relies crucially on showing that the join of transportation-like polytopes remains integral and is more broadly applicable to other Operations Management problems. In addition to an exact formulation, our LP-based approach enables a practical solution strategy for the GSM built on a hierarchy of LP relaxations. These relaxations provide valid lower bounds, certify optimality when integral, and can strengthen existing exact methods. In our computational study, the smallest relaxation already recovers an optimal GSM solution on every real-world benchmark instance, leading to substantial speed-ups over the state-of-the-art exact algorithm and commercial general-purpose solvers. The framework also supports sensitivity analysis and accommodates additional operational constraints. Overall, our approach builds a new bridge between Operations Management and Computer Science, providing new theoretical foundations and practical tools for managing safety stocks in complex modern supply chain networks.", "date": "2026-09-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.03155", "title_zh": "\u4ece\u6811\u7ed3\u6784\u5230\u6811\u5bbd\uff1a\u590d\u6742\u4f9b\u5e94\u94fe\u7f51\u7edc\u4e2d\u7684\u5e93\u5b58\u7ba1\u7406", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u57fa\u4e8e\u7cbe\u786e\u7ebf\u6027\u89c4\u5212\uff08LP\uff09\u7684\u6c42\u89e3\u65b9\u6cd5\uff0c\u7528\u4e8e\u6c42\u89e3\u5e7f\u4e3a\u5e94\u7528\u7684\u5b89\u5168\u5e93\u5b58\u914d\u7f6e\u4f18\u5316\u6a21\u578b\u2014\u2014\u4fdd\u8bc1\u670d\u52a1\u6a21\u578b\uff08GSM\uff09\u3002\u8be5\u65b9\u6cd5\u9002\u7528\u4e8e\u4efb\u610f\u6709\u5411\u65e0\u73af\u7f51\u7edc\uff0c\u4ee5\u53ca\u4efb\u4f55\u4f9d\u8d56\u4e8e\u5404\u8282\u70b9\u8f93\u5165\u548c\u8f93\u51fa\u670d\u52a1\u65f6\u95f4\u7684\u6210\u672c\u51fd\u6570\u3002\u5176\u8ba1\u7b97\u590d\u6742\u5ea6\u5728\u8282\u70b9\u6570\u91cfn\u4e0a\u4e3a\u591a\u9879\u5f0f\uff0c\u76f8\u5bf9\u4e8e\u6700\u5927\u8865\u8d27\u65f6\u95f4M\u7684\u4f4d\u5927\u5c0f\u4e3a\u4f2a\u591a\u9879\u5f0f\uff0c\u800c\u5bf9\u4e8e\u56fa\u5b9aM\u7684\u60c5\u51b5\uff0c\u5219\u5728\u6811\u5bbd\u4e0a\u5448\u6307\u6570\u589e\u957f\uff0c\u800c\u6811\u5bbd\u91cf\u5316\u4e86\u7f51\u7edc\u7684\u2018\u6811\u72b6\u2019\u7a0b\u5ea6\uff0c\u53ef\u80fd\u8fdc\u5c0f\u4e8en\u3002\u8fd9\u4e0e\u73b0\u6709\u65b9\u6cd5\u5728\u8282\u70b9\u6570\u91cfn\u4e0a\u5448\u6307\u6570\u589e\u957f\u7684\u590d\u6742\u5ea6\u5f62\u6210\u9c9c\u660e\u5bf9\u6bd4\u3002\u7cbe\u786e\u6027\u7684\u8bc1\u660e\u5173\u952e\u5728\u4e8e\u8bc1\u660e\u8fd0\u8f93\u7c7b\u591a\u9762\u4f53\u7684\u8fde\u63a5\u4ecd\u4fdd\u6301\u6574\u6570\u6027\u8d28\uff0c\u4e14\u8be5\u65b9\u6cd5\u5728\u66f4\u5e7f\u6cdb\u7684\u8fd0\u8425\u7ba1\u7406\u95ee\u9898\u4e2d\u5177\u6709\u66f4\u5e7f\u6cdb\u7684\u5e94\u7528\u524d\u666f\u3002\u9664\u4e86\u7cbe\u786e\u7684\u5efa\u6a21\u65b9\u6cd5\uff0c\u6211\u4eec\u7684\u57fa\u4e8eLP\u7684\u6c42\u89e3\u7b56\u7565\u8fd8\u6784\u5efa\u4e86\u4e00\u79cd\u57fa\u4e8eLP\u677e\u5f1b\u5c42\u6b21\u7684\u5b9e\u7528\u6c42\u89e3\u6846\u67b6\u3002\u8fd9\u4e9b\u677e\u5f1b\u5f62\u5f0f\u63d0\u4f9b\u4e86\u6709\u6548\u7684\u4e0b\u754c\uff0c\u5f53\u89e3\u4e3a\u6574\u6570\u65f6\u53ef\u8bc1\u660e\u6700\u4f18\u6027\uff0c\u5e76\u80fd\u589e\u5f3a\u73b0\u6709\u7684\u7cbe\u786e\u6c42\u89e3\u65b9\u6cd5\u3002\u5728\u6211\u4eec\u7684\u8ba1\u7b97\u5b9e\u9a8c\u4e2d\uff0c\u6700\u5c0f\u7684\u677e\u5f1b\u5f62\u5f0f\u5df2\u5728\u6240\u6709\u5b9e\u9645\u6848\u4f8b\u57fa\u51c6\u4e0a\u6062\u590d\u51fa\u6700\u4f18\u7684GSM\u89e3\uff0c\u663e\u8457\u4f18\u4e8e\u5f53\u524d\u6700\u5148\u8fdb\u7684\u7cbe\u786e\u7b97\u6cd5\u548c\u901a\u7528\u5546\u4e1a\u6c42\u89e3\u5668\u3002\u8be5\u6846\u67b6\u8fd8\u652f\u6301\u654f\u611f\u6027\u5206\u6790\uff0c\u5e76\u53ef\u5bb9\u7eb3\u989d\u5916\u7684\u8fd0\u8425\u7ea6\u675f\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u65b9\u6cd5\u5efa\u7acb\u4e86\u8fd0\u8425\u7ba1\u7406\u4e0e\u8ba1\u7b97\u673a\u79d1\u5b66\u4e4b\u95f4\u7684\u65b0\u6865\u6881\uff0c\u4e3a\u590d\u6742\u73b0\u4ee3\u4f9b\u5e94\u94fe\u7f51\u7edc\u4e2d\u7684\u5b89\u5168\u5e93\u5b58\u7ba1\u7406\u63d0\u4f9b\u4e86\u65b0\u7684\u7406\u8bba\u57fa\u7840\u548c\u5b9e\u7528\u5de5\u5177\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/qje/qjag044", "journal": "QJE", "title": "FAIRNESS ACROSS THE WORLD", "authors": ["Ingvild Alm\u00e5s", "Alexander W Cappelen", "Erik \u00d8 S\u00f8rensen", "Bertil Tungodden"], "author_details": [{"name": "Ingvild Alm\u00e5s", "affiliations": ["University of Zurich, Switzerland; Stockholm University, Sweden; and Norwegian School of Economics ,"]}, {"name": "Alexander W Cappelen", "affiliations": ["Norwegian School of Economics ,"]}, {"name": "Erik \u00d8 S\u00f8rensen", "affiliations": ["Norwegian School of Economics ,"]}, {"name": "Bertil Tungodden", "affiliations": ["Norwegian School of Economics ,"]}], "abstract": "Abstract This article provides the first comprehensive global evidence on people\u2019s fairness and efficiency preferences, beliefs about the sources of inequality and the efficiency cost of redistribution, and policy attitudes toward redistribution. Using a globally harmonized consequential experiment with more than 65,000 individuals across 60 countries, we show that the source of inequality plays a substantially larger role for inequality acceptance than the efficiency cost of redistribution. At the global level, implemented inequality increases by 85% when inequality is caused by merit rather than luck, compared with a 14% increase when redistribution entails a 50% efficiency cost. We document substantial heterogeneity in fairness views and beliefs within and across societies. The meritocratic fairness view is most prominent in many richer Western societies, while libertarian and egalitarian fairness views are widespread in many other parts of the world. Globally, people are more likely to believe that inequality reflects luck rather than merit, while beliefs in large efficiency costs of redistribution are relatively weak. Fairness preferences and beliefs are strongly associated with redistribution attitudes and actual redistribution through taxes and transfers across countries. Our findings illustrate how the interaction between fairness views and beliefs may shape redistribution across societies, highlighting the importance of jointly understanding preferences and beliefs in the political economy of redistribution.", "date": "2026-09-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag044", "title_zh": "\u516c\u5e73\u7684\u5168\u7403\u89c6\u91ce", "abstract_zh": "\u672c\u6587\u63d0\u4f9b\u4e86\u5173\u4e8e\u4eba\u4eec\u516c\u5e73\u4e0e\u6548\u7387\u504f\u597d\u3001\u5bf9\u4e0d\u5e73\u7b49\u6765\u6e90\u7684\u770b\u6cd5\u3001\u518d\u5206\u914d\u7684\u6548\u7387\u6210\u672c\u4ee5\u53ca\u518d\u5206\u914d\u653f\u7b56\u6001\u5ea6\u7684\u9996\u4e2a\u5168\u9762\u5168\u7403\u8bc1\u636e\u3002\u901a\u8fc7\u4e00\u9879\u5728\u5168\u7403\u8303\u56f4\u5185\u7edf\u4e00\u8bbe\u8ba1\u7684\u540e\u679c\u5b9e\u9a8c\uff0c\u6d89\u53ca60\u4e2a\u56fd\u5bb6\u8d85\u8fc765,000\u540d\u4e2a\u4f53\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u4e0d\u5e73\u7b49\u7684\u6765\u6e90\u5bf9\u4e0d\u5e73\u7b49\u63a5\u53d7\u5ea6\u7684\u5f71\u54cd\u8fdc\u5927\u4e8e\u518d\u5206\u914d\u7684\u6548\u7387\u6210\u672c\u3002\u5728\u5168\u7403\u5c42\u9762\uff0c\u5f53\u4e0d\u5e73\u7b49\u6e90\u4e8e\u80fd\u529b\u800c\u975e\u8fd0\u6c14\u65f6\uff0c\u5b9e\u65bd\u7684\u4e0d\u5e73\u7b49\u7a0b\u5ea6\u4e0a\u534785%\uff0c\u800c\u5f53\u518d\u5206\u914d\u5bfc\u81f450%\u7684\u6548\u7387\u6210\u672c\u65f6\uff0c\u4e0d\u5e73\u7b49\u7a0b\u5ea6\u4ec5\u4e0a\u534714%\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u4e0d\u540c\u793e\u4f1a\u5185\u90e8\u53ca\u793e\u4f1a\u4e4b\u95f4\u5728\u516c\u5e73\u89c2\u5ff5\u548c\u4fe1\u5ff5\u4e0a\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002\u5728\u8bb8\u591a\u5bcc\u88d5\u7684\u897f\u65b9\u793e\u4f1a\uff0c\u80fd\u529b\u4e3b\u4e49\u7684\u516c\u5e73\u89c2\u5ff5\u6700\u4e3a\u7a81\u51fa\uff0c\u800c\u5728\u4e16\u754c\u5176\u4ed6\u8bb8\u591a\u5730\u533a\uff0c\u81ea\u7531\u4e3b\u4e49\u548c\u5e73\u7b49\u4e3b\u4e49\u7684\u516c\u5e73\u89c2\u5ff5\u5219\u8f83\u4e3a\u666e\u904d\u3002\u5168\u7403\u8303\u56f4\u5185\uff0c\u4eba\u4eec\u66f4\u503e\u5411\u4e8e\u8ba4\u4e3a\u4e0d\u5e73\u7b49\u53cd\u6620\u7684\u662f\u8fd0\u6c14\u800c\u975e\u80fd\u529b\uff0c\u800c\u5bf9\u518d\u5206\u914d\u5e26\u6765\u5de8\u5927\u6548\u7387\u6210\u672c\u7684\u4fe1\u5ff5\u5219\u76f8\u5bf9\u8f83\u5f31\u3002\u516c\u5e73\u504f\u597d\u548c\u4fe1\u5ff5\u4e0e\u5404\u56fd\u5bf9\u518d\u5206\u914d\u7684\u6001\u5ea6\u4ee5\u53ca\u5b9e\u9645\u7a0e\u6536\u548c\u8f6c\u79fb\u652f\u4ed8\u4e2d\u7684\u518d\u5206\u914d\u884c\u4e3a\u5bc6\u5207\u76f8\u5173\u3002\u6211\u4eec\u7684\u7814\u7a76\u5c55\u793a\u4e86\u516c\u5e73\u89c2\u5ff5\u4e0e\u4fe1\u5ff5\u4e4b\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\u5982\u4f55\u5851\u9020\u4e0d\u540c\u793e\u4f1a\u7684\u518d\u5206\u914d\u6a21\u5f0f\uff0c\u5f3a\u8c03\u4e86\u5728\u7406\u89e3\u518d\u5206\u914d\u7684\u653f\u6cbb\u7ecf\u6d4e\u5b66\u4e2d\uff0c\u5fc5\u987b\u540c\u65f6\u8003\u8651\u504f\u597d\u4e0e\u4fe1\u5ff5\u7684\u91cd\u8981\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag038", "journal": "QJE", "title": "Wealth and Property Taxation in the United States", "authors": ["Sacha Dray", "Camille Landais", "Stefanie Stantcheva"], "author_details": [{"name": "Sacha Dray", "affiliations": ["World Bank ,"]}, {"name": "Camille Landais", "affiliations": ["London School of Economics and Centre for Economic Policy and Research ,"]}, {"name": "Stefanie Stantcheva", "affiliations": ["Harvard University, National Bureau of Economic Research, and Centre for Economic Policy and Research ,"]}], "abstract": "Abstract We study the history and geography of wealth accumulation in the United States using newly collected historical property tax records from the early 1800s onward. These records come from the administration of the General Property Tax\u2014a tax that aspired to cover all types of property. We construct wealth series at the state, county, and national levels. At the state level, we use annual assessed values of wealth from state-level reports drawn from multiple sources. Because assessed values may differ from market values, we also require assessment ratios, defined as the ratio of assessed to market wealth. We obtain state-level assessment ratios from decadal U.S. Census wealth data (drawn from various census reports, including those on \u201cWealth, Debt, and Taxation\u201d), in which the census carried out detailed valuation work, complemented with information on changes in assessment practices from the state reports, to build higher-frequency series of assessment ratios. The result is long-run annual wealth series for states from 1850 (or earlier, depending on the state) to 1935. We obtain national wealth series by aggregating these state series. At the county level, we use assessed values (or market values where available) from the U.S. Census wealth data for each decade and apply either state-level or county-level assessment ratios, where available, to obtain market values of wealth for each decade from 1850 to 1930. We use these data to show, first, that the United States experienced extraordinary wealth accumulation after the Civil War and until the Great Depression. Second, spatial inequality in the United States has been large and highly persistent since the mid-1800s. We also examine the determinants of long-term wealth growth and find, among other results, that counties with a higher share of enslaved property before the Civil War or with higher wealth inequality experienced lower subsequent long-run wealth growth.", "date": "2026-09-04", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag038", "title_zh": "\u7f8e\u56fd\u7684\u8d22\u5bcc\u4e0e\u8d22\u4ea7\u7a0e", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u7528\u4ece19\u4e16\u7eaa\u521d\u81f3\u4eca\u65b0\u6536\u96c6\u7684\u5386\u53f2\u8d22\u4ea7\u7a0e\u8bb0\u5f55\uff0c\u7814\u7a76\u4e86\u7f8e\u56fd\u8d22\u5bcc\u79ef\u7d2f\u7684\u5386\u53f2\u4e0e\u5730\u7406\u5206\u5e03\u3002\u8fd9\u4e9b\u8bb0\u5f55\u6765\u81ea\u201c\u666e\u904d\u8d22\u4ea7\u7a0e\u201d\u5236\u5ea6\uff0c\u8be5\u7a0e\u79cd\u65e8\u5728\u8986\u76d6\u6240\u6709\u7c7b\u578b\u7684\u8d22\u4ea7\u3002\u6211\u4eec\u6784\u5efa\u4e86\u5dde\u3001\u53bf\u548c\u5168\u56fd\u5c42\u9762\u7684\u8d22\u5bcc\u5e8f\u5217\u3002\u5728\u5dde\u5c42\u9762\uff0c\u6211\u4eec\u4f7f\u7528\u6765\u81ea\u591a\u4e2a\u6765\u6e90\u7684\u5dde\u7ea7\u62a5\u544a\u4e2d\u7684\u5e74\u5ea6\u8d22\u5bcc\u8bc4\u4f30\u503c\u3002\u7531\u4e8e\u8bc4\u4f30\u503c\u53ef\u80fd\u4e0e\u5e02\u573a\u4ef7\u503c\u4e0d\u540c\uff0c\u6211\u4eec\u8fd8\u5f15\u5165\u4e86\u8bc4\u4f30\u6bd4\u7387\uff0c\u5373\u8bc4\u4f30\u8d22\u5bcc\u4e0e\u5e02\u573a\u8d22\u5bcc\u7684\u6bd4\u7387\u3002\u6211\u4eec\u901a\u8fc7\u5341\u5e74\u4e00\u6b21\u7684\u7f8e\u56fd\u4eba\u53e3\u666e\u67e5\u8d22\u5bcc\u6570\u636e\uff08\u6765\u81ea\u5404\u7c7b\u4eba\u53e3\u666e\u67e5\u62a5\u544a\uff0c\u5305\u62ec\u5173\u4e8e\u201c\u8d22\u5bcc\u3001\u503a\u52a1\u4e0e\u7a0e\u6536\u201d\u7684\u62a5\u544a\uff09\uff0c\u5176\u4e2d\u4eba\u53e3\u666e\u67e5\u8fdb\u884c\u4e86\u8be6\u7ec6\u7684\u4f30\u503c\u5de5\u4f5c\uff0c\u7ed3\u5408\u5dde\u7ea7\u62a5\u544a\u4e2d\u5173\u4e8e\u8bc4\u4f30\u653f\u7b56\u53d8\u5316\u7684\u4fe1\u606f\uff0c\u6784\u5efa\u4e86\u66f4\u9ad8\u9891\u7387\u7684\u8bc4\u4f30\u6bd4\u7387\u7cfb\u5217\u3002\u7ed3\u679c\u662f1850\u5e74\uff08\u6216\u66f4\u65e9\uff0c\u89c6\u5dde\u800c\u5b9a\uff09\u81f31935\u5e74\u7684\u5dde\u7ea7\u957f\u671f\u5e74\u5ea6\u8d22\u5bcc\u5e8f\u5217\u3002\u6211\u4eec\u901a\u8fc7\u6c47\u603b\u8fd9\u4e9b\u5dde\u7ea7\u5e8f\u5217\u5f97\u5230\u5168\u56fd\u8d22\u5bcc\u5e8f\u5217\u3002\u5728\u53bf\u5c42\u9762\uff0c\u6211\u4eec\u4f7f\u7528\u7f8e\u56fd\u4eba\u53e3\u666e\u67e5\u6bcf\u5341\u5e74\u7684\u8d22\u5bcc\u8bc4\u4f30\u503c\uff08\u6216\u53ef\u83b7\u5f97\u7684\u5e02\u573a\u503c\uff09\uff0c\u5e76\u5e94\u7528\u5dde\u7ea7\u6216\u53bf\u7ea7\u8bc4\u4f30\u6bd4\u7387\uff08\u5982\u53ef\u7528\uff09\u6765\u83b7\u5f971850\u5e74\u81f31930\u5e74\u95f4\u6bcf\u4e2a\u5341\u5e74\u7684\u8d22\u5bcc\u5e02\u573a\u4ef7\u503c\u3002\u6211\u4eec\u5229\u7528\u8fd9\u4e9b\u6570\u636e\u8868\u660e\uff0c\u9996\u5148\uff0c\u7f8e\u56fd\u5728\u5185\u6218\u540e\u81f3\u5927\u8427\u6761\u524d\u7ecf\u5386\u4e86\u5f02\u5e38\u663e\u8457\u7684\u8d22\u5bcc\u79ef\u7d2f\uff1b\u5176\u6b21\uff0c\u81ea19\u4e16\u7eaa\u4e2d\u53f6\u4ee5\u6765\uff0c\u7f8e\u56fd\u5728\u7a7a\u95f4\u4e0a\u7684\u4e0d\u5e73\u7b49\u73b0\u8c61\u4e00\u76f4\u663e\u8457\u4e14\u9ad8\u5ea6\u6301\u4e45\u3002\u6211\u4eec\u8fd8\u8003\u5bdf\u4e86\u957f\u671f\u8d22\u5bcc\u589e\u957f\u7684\u51b3\u5b9a\u56e0\u7d20\uff0c\u53d1\u73b0\u5176\u4e2d\u4e00\u9879\u91cd\u8981\u7ed3\u679c\u662f\uff1a\u5185\u6218\u524d\u62e5\u6709\u8f83\u9ad8\u6bd4\u4f8b\u5974\u96b6\u8d22\u4ea7\u6216\u8d22\u5bcc\u4e0d\u5e73\u7b49\u7a0b\u5ea6\u8f83\u9ad8\u7684\u53bf\uff0c\u5176\u540e\u7eed\u957f\u671f\u8d22\u5bcc\u589e\u957f\u8f83\u4f4e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2025.02735", "journal": "MS", "title": "Narrative Ambiguity Matters", "authors": ["Xinbei Wei", "Qunzi Zhang"], "author_details": [{"name": "Xinbei Wei", "affiliations": ["School of Finance, Capital University of Economics and Business, Beijing 100070, China"]}, {"name": "Qunzi Zhang", "affiliations": ["School of Economics, Shandong University, Jinan 250100, China"]}], "abstract": "By extracting information from economic news articles, this paper proposes a novel measure of narrative-based ambiguity that captures investors\u2019 attitudes toward narrative uncertainty and exhibits strong in- and out-of-sample predictive power for the stock market returns. It reveals general ambiguity aversion except in high loss probability scenarios in which ambiguity tolerance emerges. Further tests confirm the significant pricing power and distinct information of the narrative ambiguity on top of existing ambiguity measures, such as survey- and return-based ambiguity. By aligning industry-specific narrative ambiguity, we construct a superior predictor for market returns with the predictability predominantly driven by the ambiguity from consumption-, energy-, and technology-related sectors. Our findings also carry broad implications as the predictability remains significant across international markets and other asset classes.", "date": "2026-09-04", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.02735", "title_zh": "\u53d9\u4e8b\u6a21\u7cca\u6027\u5f88\u91cd\u8981", "abstract_zh": "\u901a\u8fc7\u4ece\u7ecf\u6d4e\u65b0\u95fb\u6587\u7ae0\u4e2d\u63d0\u53d6\u4fe1\u606f\uff0c\u672c\u6587\u63d0\u51fa\u4e86\u4e00\u79cd\u65b0\u7684\u57fa\u4e8e\u53d9\u4e8b\u7684\u6a21\u7cca\u6027\u5ea6\u91cf\u65b9\u6cd5\uff0c\u8be5\u65b9\u6cd5\u6355\u6349\u4e86\u6295\u8d44\u8005\u5bf9\u53d9\u4e8b\u4e0d\u786e\u5b9a\u6027\u7684\u6001\u5ea6\uff0c\u5e76\u5728\u6837\u672c\u5185\u548c\u6837\u672c\u5916\u5747\u8868\u73b0\u51fa\u5bf9\u80a1\u7968\u5e02\u573a\u56de\u62a5\u7684\u5f3a\u9884\u6d4b\u80fd\u529b\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u6295\u8d44\u8005\u666e\u904d\u8868\u73b0\u51fa\u5bf9\u6a21\u7cca\u6027\u7684\u538c\u6076\uff0c\u4f46\u5728\u9ad8\u635f\u5931\u6982\u7387\u60c5\u666f\u4e0b\uff0c\u53cd\u800c\u8868\u73b0\u51fa\u5bf9\u6a21\u7cca\u6027\u7684\u5bb9\u5fcd\u3002\u8fdb\u4e00\u6b65\u7684\u68c0\u9a8c\u8bc1\u5b9e\uff0c\u53d9\u4e8b\u6a21\u7cca\u6027\u5728\u4fe1\u606f\u542b\u91cf\u548c\u5b9a\u4ef7\u80fd\u529b\u65b9\u9762\u663e\u8457\u4f18\u4e8e\u73b0\u6709\u7684\u6a21\u7cca\u6027\u5ea6\u91cf\u65b9\u6cd5\uff0c\u5982\u8c03\u67e5\u548c\u56de\u62a5\u57fa\u7840\u7684\u6a21\u7cca\u6027\u5ea6\u91cf\u3002\u901a\u8fc7\u5c06\u884c\u4e1a\u7279\u5b9a\u7684\u53d9\u4e8b\u6a21\u7cca\u6027\u8fdb\u884c\u5bf9\u9f50\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u66f4\u4f18\u7684\u5e02\u573a\u56de\u62a5\u9884\u6d4b\u6307\u6807\uff0c\u5176\u9884\u6d4b\u80fd\u529b\u4e3b\u8981\u6765\u6e90\u4e8e\u6d88\u8d39\u3001\u80fd\u6e90\u548c\u79d1\u6280\u76f8\u5173\u884c\u4e1a\u7684\u6a21\u7cca\u6027\u3002\u672c\u7814\u7a76\u7ed3\u679c\u8fd8\u5177\u6709\u5e7f\u6cdb\u610f\u4e49\uff0c\u56e0\u4e3a\u8fd9\u79cd\u53ef\u9884\u6d4b\u6027\u5728\u56fd\u9645\u5e02\u573a\u548c\u5176\u4ed6\u8d44\u4ea7\u7c7b\u522b\u4e2d\u4f9d\u7136\u663e\u8457\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag098", "journal": "REStud", "title": "Equity Frictions and Firm Ownership", "authors": ["Alessandra Peter"], "author_details": [{"name": "Alessandra Peter", "affiliations": ["New York University, CEPR & NBER ,"]}], "abstract": "Abstract In this paper, I document systematic heterogeneity in ownership and financing of firms across Eurozone countries. To rationalize these differences, I build a quantitative general equilibrium model of workers and entrepreneurs who choose debt and equity financing of their firms, subject to rich country-specific financial frictions. The novel data on firm ownership and financing, combined with the structure of the model, allows me to quantify the level of debt and equity frictions in each country. Quantitatively, I find much larger output effects from equity frictions: harmonizing them across countries would lead to nearly four times larger output effects compared to debt frictions, and removing them would increase aggregate output by 73% more. The larger impact on output is due not only to the estimated levels and dispersion of equity frictions but also to the greater risk sharing provided by equity, which further incentivizes entrepreneurs to expand their firms. Through their effect on risk sharing, equity frictions also rationalize the observed negative relationship between equity financing and wealth inequality. Quantitatively, they are responsible for over 70% of the explained variation in top wealth shares across countries.", "date": "2026-09-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag098", "title_zh": "\u80a1\u6743\u6469\u64e6\u4e0e\u4f01\u4e1a\u6240\u6709\u6743", "abstract_zh": "\u672c\u6587\u8bb0\u5f55\u4e86\u6b27\u5143\u533a\u5404\u56fd\u4f01\u4e1a\u6240\u6709\u6743\u548c\u878d\u8d44\u4e2d\u7684\u7cfb\u7edf\u6027\u5f02\u8d28\u6027\u3002\u4e3a\u89e3\u91ca\u8fd9\u4e9b\u5dee\u5f02\uff0c\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u5de5\u4eba\u548c\u4f01\u4e1a\u5bb6\u5728\u9762\u4e34\u4e30\u5bcc\u56fd\u5bb6\u7279\u5b9a\u91d1\u878d\u6469\u64e6\u6761\u4ef6\u4e0b\u9009\u62e9\u503a\u52a1\u548c\u80a1\u6743\u878d\u8d44\u7684\u91cf\u5316\u4e00\u822c\u5747\u8861\u6a21\u578b\u3002\u7ed3\u5408\u65b0\u7684\u4f01\u4e1a\u6240\u6709\u6743\u548c\u878d\u8d44\u6570\u636e\u4ee5\u53ca\u6a21\u578b\u7ed3\u6784\uff0c\u6211\u80fd\u591f\u91cf\u5316\u6bcf\u4e2a\u56fd\u5bb6\u503a\u52a1\u548c\u80a1\u6743\u6469\u64e6\u7684\u6c34\u5e73\u3002\u5b9a\u91cf\u7ed3\u679c\u663e\u793a\uff0c\u80a1\u6743\u6469\u64e6\u5bf9\u4ea7\u51fa\u7684\u5f71\u54cd\u8fdc\u5927\u4e8e\u503a\u52a1\u6469\u64e6\uff1a\u82e5\u5c06\u5404\u56fd\u80a1\u6743\u6469\u64e6\u7edf\u4e00\uff0c\u5176\u5bf9\u4ea7\u51fa\u7684\u63d0\u5347\u6548\u679c\u5c06\u6bd4\u503a\u52a1\u6469\u64e6\u9ad8\u51fa\u8fd1\u56db\u500d\uff0c\u4e14\u6d88\u9664\u80a1\u6743\u6469\u64e6\u5c06\u4f7f\u603b\u4ea7\u51fa\u589e\u52a073%\u4ee5\u4e0a\u3002\u8fd9\u79cd\u66f4\u5927\u7684\u4ea7\u51fa\u5f71\u54cd\u4e0d\u4ec5\u6e90\u4e8e\u80a1\u6743\u6469\u64e6\u7684\u4f30\u8ba1\u6c34\u5e73\u53ca\u5176\u5206\u6563\u7a0b\u5ea6\uff0c\u8fd8\u6e90\u4e8e\u80a1\u6743\u63d0\u4f9b\u7684\u66f4\u5927\u98ce\u9669\u5206\u62c5\uff0c\u4ece\u800c\u8fdb\u4e00\u6b65\u6fc0\u52b1\u4f01\u4e1a\u5bb6\u6269\u5927\u4f01\u4e1a\u89c4\u6a21\u3002\u901a\u8fc7\u5176\u5bf9\u98ce\u9669\u5206\u62c5\u7684\u5f71\u54cd\uff0c\u80a1\u6743\u6469\u64e6\u4e5f\u89e3\u91ca\u4e86\u89c2\u5bdf\u5230\u7684\u80a1\u6743\u878d\u8d44\u4e0e\u8d22\u5bcc\u4e0d\u5e73\u7b49\u4e4b\u95f4\u7684\u8d1f\u76f8\u5173\u5173\u7cfb\u3002\u5b9a\u91cf\u4e0a\uff0c\u80a1\u6743\u6469\u64e6\u5bf9\u5404\u56fd\u9876\u5c42\u8d22\u5bcc\u4efd\u989d\u53d8\u5316\u7684\u89e3\u91ca\u7a0b\u5ea6\u8d85\u8fc770%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70073", "journal": "JF", "title": "Discretionary Announcement Timing and Stock Returns", "authors": ["KERRY BACK", "BRUCE I. CARLIN", "SEYED M. KAZEMPOUR", "CHLOE L. XIE"], "author_details": [{"name": "KERRY BACK", "affiliations": []}, {"name": "BRUCE I. CARLIN", "affiliations": []}, {"name": "SEYED M. KAZEMPOUR", "affiliations": []}, {"name": "CHLOE L. XIE", "affiliations": []}], "abstract": "ABSTRACT Discretionary announcement timing generates high conditional risk premia of stock returns and a pattern of negative drifts followed by positive jumps. Average announcement returns are much larger than unconditional risk premia. Capital Asset Pricing Model alphas turn negative when conditioning on nondisclosure because betas rise faster than risk premia prior to disclosures, but average announcement returns may appear to be too large relative to market risk when betas are estimated from past returns. The effects are amplified when multiple firms exercise discretion over the timing of correlated announcements. We present evidence that firms time earnings announcements in a manner consistent with our model.", "date": "2026-09-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70073", "title_zh": "\u81ea\u4e3b\u9009\u62e9\u516c\u544a\u65f6\u95f4\u4e0e\u80a1\u7968\u56de\u62a5", "abstract_zh": "\u6458\u8981 \u81ea\u4e3b\u9009\u62e9\u516c\u544a\u65f6\u95f4\u5bfc\u81f4\u80a1\u7968\u56de\u62a5\u7684\u6761\u4ef6\u98ce\u9669\u6ea2\u4ef7\u5347\u9ad8\uff0c\u5e76\u5448\u73b0\u51fa\u8d1f\u5411\u6f02\u79fb\u540e\u51fa\u73b0\u6b63\u5411\u8df3\u8dc3\u7684\u6a21\u5f0f\u3002\u516c\u544a\u7684\u5e73\u5747\u56de\u62a5\u8fdc\u9ad8\u4e8e\u65e0\u6761\u4ef6\u98ce\u9669\u6ea2\u4ef7\u3002\u5f53\u4ee5\u672a\u62ab\u9732\u4fe1\u606f\u4e3a\u6761\u4ef6\u65f6\uff0c\u8d44\u672c\u8d44\u4ea7\u5b9a\u4ef7\u6a21\u578b\u7684\u963f\u5c14\u6cd5\u503c\u53d8\u4e3a\u8d1f\u503c\uff0c\u56e0\u4e3a\u516c\u544a\u524d\u7684\u8d1d\u5854\u503c\u4e0a\u5347\u901f\u5ea6\u8d85\u8fc7\u98ce\u9669\u6ea2\u4ef7\uff0c\u4f46\u5f53\u8d1d\u5854\u503c\u57fa\u4e8e\u8fc7\u53bb\u56de\u62a5\u8fdb\u884c\u4f30\u8ba1\u65f6\uff0c\u516c\u544a\u7684\u5e73\u5747\u56de\u62a5\u53ef\u80fd\u770b\u8d77\u6765\u76f8\u5bf9\u4e8e\u5e02\u573a\u98ce\u9669\u8fc7\u5927\u3002\u5f53\u591a\u5bb6\u4f01\u4e1a\u5bf9\u76f8\u5173\u516c\u544a\u7684\u65f6\u95f4\u8fdb\u884c\u81ea\u4e3b\u9009\u62e9\u65f6\uff0c\u8fd9\u79cd\u6548\u5e94\u4f1a\u88ab\u8fdb\u4e00\u6b65\u653e\u5927\u3002\u6211\u4eec\u63d0\u4f9b\u4e86\u8bc1\u636e\u8868\u660e\uff0c\u4f01\u4e1a\u786e\u5b9e\u4ee5\u7b26\u5408\u6211\u4eec\u6a21\u578b\u7684\u65b9\u5f0f\u5b89\u6392\u5176\u76c8\u5229\u516c\u544a\u65f6\u95f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhag072", "journal": "RFS", "title": "Stablecoin Runs and the Centralization of Arbitrage", "authors": ["Yiming Ma", "Yao Zeng", "Anthony Lee Zhang"], "author_details": [{"name": "Yiming Ma", "affiliations": ["Columbia Business School and NBER ,"]}, {"name": "Yao Zeng", "affiliations": ["The Wharton School, University of Pennsylvania, and NBER ,"]}, {"name": "Anthony Lee Zhang", "affiliations": ["Booth School of Business, University of Chicago ,"]}], "abstract": "Abstract Stablecoins are cryptoassets designed to be pegged to the dollar, but they are backed by imperfectly liquid USD assets. We show that stablecoins feature concentrated arbitrage: the largest issuer, Tether, allows only six agents in an average month to redeem stablecoins for cash. We argue that the issuers\u2019 choice of arbitrage concentration reflects a trade-off: efficient arbitrage improves stablecoin price stability in secondary markets but amplifies run risks by reducing investors\u2019 price impact from selling stablecoins. Our findings imply that policies designed to improve stablecoin price stability may have the unintended consequence of increasing stablecoin run risks.", "date": "2026-09-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag072", "title_zh": "\u7a33\u5b9a\u5e01\u7684\u5957\u5229\u96c6\u4e2d\u4e0e\u5957\u5229\u96c6\u4e2d\u5316", "abstract_zh": "\u7a33\u5b9a\u5e01\u662f\u8bbe\u8ba1\u7528\u4e8e\u4e0e\u7f8e\u5143\u6302\u94a9\u7684\u52a0\u5bc6\u8d44\u4ea7\uff0c\u4f46\u5176\u80cc\u540e\u662f\u6d41\u52a8\u6027\u4e0d\u5b8c\u7f8e\u7684\u7f8e\u5143\u8d44\u4ea7\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u7a33\u5b9a\u5e01\u5b58\u5728\u9ad8\u5ea6\u96c6\u4e2d\u7684\u5957\u5229\u884c\u4e3a\uff1a\u6700\u5927\u7684\u53d1\u884c\u5546Tether\u6bcf\u6708\u4ec5\u5141\u8bb8\u516d\u540d\u4ee3\u7406\u4eba\u5c06\u7a33\u5b9a\u5e01\u5151\u6362\u4e3a\u73b0\u91d1\u3002\u6211\u4eec\u8ba4\u4e3a\uff0c\u53d1\u884c\u5546\u9009\u62e9\u5957\u5229\u96c6\u4e2d\u5316\u53cd\u6620\u4e86\u6743\u8861\uff1a\u9ad8\u6548\u7684\u5957\u5229\u6709\u52a9\u4e8e\u63d0\u5347\u7a33\u5b9a\u5e01\u5728\u4e8c\u7ea7\u5e02\u573a\u7684\u4ef7\u683c\u7a33\u5b9a\u6027\uff0c\u4f46\u901a\u8fc7\u964d\u4f4e\u6295\u8d44\u8005\u5356\u51fa\u7a33\u5b9a\u5e01\u65f6\u7684\u4ef7\u683c\u5f71\u54cd\uff0c\u53cd\u800c\u52a0\u5267\u4e86\u6324\u5151\u98ce\u9669\u3002\u6211\u4eec\u7684\u53d1\u73b0\u8868\u660e\uff0c\u65e8\u5728\u63d0\u5347\u7a33\u5b9a\u5e01\u4ef7\u683c\u7a33\u5b9a\u6027\u7684\u653f\u7b56\u53ef\u80fd\u4f1a\u4ea7\u751f\u610f\u5916\u540e\u679c\uff0c\u5373\u589e\u52a0\u7a33\u5b9a\u5e01\u6324\u5151\u7684\u98ce\u9669\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.04203", "journal": "MS", "title": "Learning in Lost-Sales Inventory Systems with Stochastic Lead Times and Random Supplies", "authors": ["Xin Chen", "Jiameng Lyu", "Shilin Yuan", "Yuan Zhou"], "author_details": [{"name": "Xin Chen", "affiliations": ["Naveen Jindal School of Management, The University of Texas at Dallas, Richardson, Texas 75080"]}, {"name": "Jiameng Lyu", "affiliations": ["Department of Management Science, School of Management, Fudan University, Shanghai 200433, China"]}, {"name": "Shilin Yuan", "affiliations": ["School of Management, Huazhong University of Science and Technology, Wuhan 430074, China"]}, {"name": "Yuan Zhou", "affiliations": ["Yau Mathematical Sciences Center & Department of Mathematical Sciences, Tsinghua University, Beijing 100084, China; and Beijing Institute of Mathematical Sciences and Applications, Beijing 101408, China"]}], "abstract": "Supply uncertainty, characterized by stochastic lead times and random supply quantities, has attracted increasing attention from academia, industries, and governments, particularly in the aftermath of the COVID-19 pandemic. In this paper, we consider the problem of managing lost-sales inventory systems with general supply uncertainty: stochastic lead times and random supplies. Unlike the previous studies, we assume the decision maker has no prior information on the stochastic demand and supply. We propose the first provably effective learning algorithm for inventory management problems with censored demand and supply data under general supply uncertainty. Then, we establish a cumulative regret of [Formula: see text] for this learning algorithm compared with the best constant-order policy, where [Formula: see text] is the upper bound of the random part, and L is the deterministic part of the stochastic lead times. We also conduct numerical experiments to demonstrate the effectiveness of our algorithm. Our approach lies in developing a new framework for transformed convexity. Furthermore, we address the unique challenges of our problem through new techniques, for example, estimating the long-run cost by establishing coupling and concentration results utilizing the system structures. These techniques are also of independent interest. Beyond our problem, our framework provides broad implications for other operations management (OM) problems exhibiting transformed convexity.", "date": "2026-09-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.04203", "title_zh": "\u5177\u6709\u968f\u673a\u4ea4\u8d27\u65f6\u95f4\u548c\u968f\u673a\u4f9b\u5e94\u91cf\u7684\u5931\u552e\u5e93\u5b58\u7cfb\u7edf\u4e2d\u7684\u5b66\u4e60\u95ee\u9898", "abstract_zh": "\u4f9b\u5e94\u4e0d\u786e\u5b9a\u6027\uff0c\u8868\u73b0\u4e3a\u968f\u673a\u4ea4\u8d27\u65f6\u95f4\u548c\u968f\u673a\u4f9b\u5e94\u91cf\uff0c\u8fd1\u5e74\u6765\u53d7\u5230\u5b66\u672f\u754c\u3001\u4ea7\u4e1a\u754c\u548c\u653f\u5e9c\u7684\u5e7f\u6cdb\u5173\u6ce8\uff0c\u5c24\u5176\u662f\u5728\u65b0\u51a0\u75ab\u60c5\u4e4b\u540e\u3002\u672c\u6587\u7814\u7a76\u4e86\u5177\u6709\u4e00\u822c\u4f9b\u5e94\u4e0d\u786e\u5b9a\u6027\u7684\u5931\u552e\u5e93\u5b58\u7ba1\u7406\u7cfb\u7edf\uff1a\u968f\u673a\u4ea4\u8d27\u65f6\u95f4\u548c\u968f\u673a\u4f9b\u5e94\u91cf\u3002\u4e0e\u4ee5\u5f80\u7814\u7a76\u4e0d\u540c\uff0c\u6211\u4eec\u5047\u8bbe\u51b3\u7b56\u8005\u5bf9\u968f\u673a\u9700\u6c42\u548c\u4f9b\u5e94\u6ca1\u6709\u5148\u9a8c\u4fe1\u606f\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u9996\u4e2a\u5728\u5b58\u5728\u88ab\u622a\u65ad\u7684\u9700\u6c42\u548c\u4f9b\u5e94\u6570\u636e\u6761\u4ef6\u4e0b\u3001\u9488\u5bf9\u4e00\u822c\u4f9b\u5e94\u4e0d\u786e\u5b9a\u6027\u7684\u5e93\u5b58\u7ba1\u7406\u95ee\u9898\u7684\u53ef\u8bc1\u660e\u6709\u6548\u7684\u5b66\u4e60\u7b97\u6cd5\u3002\u7136\u540e\uff0c\u6211\u4eec\u5efa\u7acb\u4e86\u8be5\u5b66\u4e60\u7b97\u6cd5\u76f8\u5bf9\u4e8e\u6700\u4f18\u6052\u5b9a\u8ba2\u8d27\u7b56\u7565\u7684\u7d2f\u8ba1\u9057\u61be\u4e3a[Formula: see text]\uff0c\u5176\u4e2d[Formula: see text]\u662f\u968f\u673a\u90e8\u5206\u7684\u4e0a\u754c\uff0cL\u662f\u968f\u673a\u4ea4\u8d27\u65f6\u95f4\u7684\u786e\u5b9a\u6027\u90e8\u5206\u3002\u6211\u4eec\u8fd8\u901a\u8fc7\u6570\u503c\u5b9e\u9a8c\u9a8c\u8bc1\u4e86\u8be5\u7b97\u6cd5\u7684\u6709\u6548\u6027\u3002\u6211\u4eec\u7684\u65b9\u6cd5\u5728\u4e8e\u6784\u5efa\u4e86\u4e00\u4e2a\u65b0\u7684\u53d8\u6362\u51f8\u6027\u6846\u67b6\u3002\u6b64\u5916\uff0c\u6211\u4eec\u901a\u8fc7\u65b0\u6280\u5de7\u89e3\u51b3\u4e86\u672c\u95ee\u9898\u7684\u72ec\u7279\u6311\u6218\uff0c\u4f8b\u5982\uff0c\u901a\u8fc7\u5229\u7528\u7cfb\u7edf\u7ed3\u6784\u5efa\u7acb\u8026\u5408\u548c\u96c6\u4e2d\u6027\u7ed3\u679c\u6765\u4f30\u8ba1\u957f\u671f\u6210\u672c\u3002\u8fd9\u4e9b\u6280\u5de7\u4e5f\u5177\u6709\u72ec\u7acb\u7684\u7814\u7a76\u4ef7\u503c\u3002\u9664\u4e86\u672c\u95ee\u9898\uff0c\u6211\u4eec\u7684\u6846\u67b6\u4e3a\u5176\u4ed6\u8868\u73b0\u51fa\u53d8\u6362\u51f8\u6027\u7684\u8fd0\u8425\u7ba1\u7406\uff08OM\uff09\u95ee\u9898\u63d0\u4f9b\u4e86\u5e7f\u6cdb\u7684\u5e94\u7528\u610f\u4e49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.07615", "journal": "MS", "title": "Immigrants in Finance: Evidence from Hedge Funds", "authors": ["Jun Chen", "Shenje Hshieh", "Melvyn Teo", "Feng Zhang"], "author_details": [{"name": "Jun Chen", "affiliations": ["College of Business Administration, University of Illinois Chicago, Chicago, Illinois 60607"]}, {"name": "Shenje Hshieh", "affiliations": ["City University of Hong Kong, Hong Kong"]}, {"name": "Melvyn Teo", "affiliations": ["Lee Kong Chian School of Business, Singapore Management University, Singapore 178899"]}, {"name": "Feng Zhang", "affiliations": ["Cox School of Business, Southern Methodist University, Dallas, Texas 75275"]}], "abstract": "We examine the value of skilled immigrants in finance by exploiting evidence from visa lotteries. We find that hedge fund management companies that secure more H-1B visas in random lotteries deliver higher alphas, Sharpe ratios, and information ratios. The superior performance of funds with high H-1B visa allocations can be attributed to well-paid and highly educated H-1B workers with quantitative skills. H-1B workers add value by helping hedge funds develop distinctive investment strategies, arbitrage prominent stock anomalies, and overcome capacity constraints. Hedge funds appear to exploit labor market frictions as alpha generation is greatest by workers from countries with the longest wait times for U.S. permanent residency.", "date": "2026-09-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07615", "title_zh": "\u79fb\u6c11\u5728\u91d1\u878d\u9886\u57df\u7684\u4ef7\u503c\uff1a\u6765\u81ea\u5bf9\u51b2\u57fa\u91d1\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u901a\u8fc7\u5229\u7528\u7b7e\u8bc1\u62bd\u7b7e\u6570\u636e\uff0c\u7814\u7a76\u4e86\u9ad8\u6280\u80fd\u79fb\u6c11\u5728\u91d1\u878d\u9886\u57df\u4e2d\u7684\u4ef7\u503c\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u968f\u673a\u62bd\u7b7e\u4e2d\u83b7\u5f97\u66f4\u591aH-1B\u7b7e\u8bc1\u7684\u5bf9\u51b2\u57fa\u91d1\u7ba1\u7406\u516c\u53f8\uff0c\u5176\u963f\u5c14\u6cd5\u503c\u3001\u590f\u666e\u6bd4\u7387\u548c\u4fe1\u606f\u6bd4\u7387\u5747\u66f4\u9ad8\u3002\u62e5\u6709\u8f83\u9ad8H-1B\u7b7e\u8bc1\u5206\u914d\u7684\u57fa\u91d1\u8868\u73b0\u66f4\u4f18\uff0c\u53ef\u5f52\u56e0\u4e8e\u85aa\u916c\u9ad8\u3001\u53d7\u6559\u80b2\u7a0b\u5ea6\u9ad8\u4e14\u5177\u5907\u91cf\u5316\u6280\u80fd\u7684H-1B\u5458\u5de5\u3002\u8fd9\u4e9bH-1B\u5458\u5de5\u901a\u8fc7\u5e2e\u52a9\u5bf9\u51b2\u57fa\u91d1\u5236\u5b9a\u72ec\u7279\u6295\u8d44\u7b56\u7565\u3001\u5229\u7528\u663e\u8457\u7684\u80a1\u7968\u5f02\u5e38\u73b0\u8c61\u8fdb\u884c\u5957\u5229\uff0c\u4ee5\u53ca\u514b\u670d\u5bb9\u91cf\u9650\u5236\uff0c\u4ece\u800c\u521b\u9020\u4ef7\u503c\u3002\u5bf9\u51b2\u57fa\u91d1\u4f3c\u4e4e\u5229\u7528\u4e86\u52b3\u52a8\u529b\u5e02\u573a\u7684\u6469\u64e6\uff0c\u5176\u4ea7\u751f\u8d85\u989d\u6536\u76ca\u7684\u7a0b\u5ea6\u5728\u6765\u81ea\u7f8e\u56fd\u6c38\u4e45\u5c45\u7559\u6743\u7b49\u5f85\u65f6\u95f4\u6700\u957f\u56fd\u5bb6\u7684\u5458\u5de5\u4e2d\u5c24\u4e3a\u660e\u663e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1287/mnsc.2025.00201", "journal": "MS", "title": "Preventing Information Leakage", "authors": ["Jonathan Brogaard", "Dan Li", "Matthew Ma", "Ryan Riordan", "Bart Zhou Yueshen"], "author_details": [{"name": "Jonathan Brogaard", "affiliations": ["David Eccles School of Business, The University of Utah, Salt Lake City, Utah 84112"]}, {"name": "Dan Li", "affiliations": ["School of Management and Economics, The Chinese University of Hong Kong, Shenzhen, Shenzhen 518172, China"]}, {"name": "Matthew Ma", "affiliations": ["College of Business, Lehigh University, Bethlehem, Pennsylvania 18015"]}, {"name": "Ryan Riordan", "affiliations": ["School of Management, LMU Munich, 80539 Munich, Germany"]}, {"name": "Bart Zhou Yueshen", "affiliations": ["LKC School of Business, Singapore Management University, Singapore 188065"]}], "abstract": "Traders devote significant resources to producing private information. The value of such information is eroded when it is leaked. We study the use of multiple brokers by institutions to help mitigate information leakage. We document that trades using multiple brokers better predict future returns and have higher future profits, consistent with information possessed by investors driving the decision to use multiple brokers. We find that trades using multiple brokers are more informed and, yet, have lower price impacts, lower implementation shortfalls, and fewer follower trades than similar single-broker trades. The results suggest that traders use multiple brokers to successfully reduce information leakage.", "date": "2026-09-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.00201", "title_zh": "\u9632\u6b62\u4fe1\u606f\u6cc4\u9732", "abstract_zh": "\u4ea4\u6613\u8005\u6295\u5165\u5927\u91cf\u8d44\u6e90\u6765\u4ea7\u751f\u79c1\u4eba\u4fe1\u606f\uff0c\u800c\u5f53\u8fd9\u4e9b\u4fe1\u606f\u88ab\u6cc4\u9732\u65f6\uff0c\u5176\u4ef7\u503c\u4f1a\u4e0b\u964d\u3002\u672c\u6587\u7814\u7a76\u4e86\u673a\u6784\u4f7f\u7528\u591a\u5bb6\u7ecf\u7eaa\u5546\u6765\u7f13\u89e3\u4fe1\u606f\u6cc4\u9732\u7684\u73b0\u8c61\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u4f7f\u7528\u591a\u5bb6\u7ecf\u7eaa\u5546\u7684\u4ea4\u6613\u66f4\u80fd\u9884\u6d4b\u672a\u6765\u7684\u6536\u76ca\u7387\uff0c\u5e76\u4e14\u5177\u6709\u66f4\u9ad8\u7684\u672a\u6765\u5229\u6da6\uff0c\u8fd9\u4e0e\u6295\u8d44\u8005\u6240\u638c\u63e1\u7684\u4fe1\u606f\u9a71\u52a8\u5176\u9009\u62e9\u4f7f\u7528\u591a\u5bb6\u7ecf\u7eaa\u5546\u7684\u60c5\u51b5\u4e00\u81f4\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u4f7f\u7528\u591a\u5bb6\u7ecf\u7eaa\u5546\u7684\u4ea4\u6613\u4fe1\u606f\u66f4\u5145\u5206\uff0c\u4f46\u4ef7\u683c\u51b2\u51fb\u66f4\u5c0f\uff0c\u5b9e\u73b0\u504f\u5dee\u66f4\u4f4e\uff0c\u8ddf\u968f\u4ea4\u6613\u4e5f\u66f4\u5c11\u3002\u7ed3\u679c\u8868\u660e\uff0c\u4ea4\u6613\u8005\u901a\u8fc7\u4f7f\u7528\u591a\u5bb6\u7ecf\u7eaa\u5546\u6210\u529f\u51cf\u5c11\u4e86\u4fe1\u606f\u6cc4\u9732\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.06051", "journal": "MS", "title": "Waiting or Acting: The Effects of Environmental Regulatory Uncertainty on Green Innovation", "authors": ["Jiawei (Brooke) Wang"], "author_details": [{"name": "Jiawei (Brooke) Wang", "affiliations": ["Farmer School of Business, Miami University, Oxford, Ohio 45056"]}], "abstract": "This paper investigates how environmental regulatory uncertainty affects green innovation in polluting firms. The findings suggest that, instead of adopting a passive \u201cwait-and-see\u201d strategy, polluting firms proactively engage in green innovation and R&D activities. To address endogeneity, I employ an instrumental variable approach using political polarization in roll-call votes on environmental and climate issues in the U.S. House of Representatives. I also exploit the proposal of the Affordable Clean Energy rule in 2018 as an exogenous shock in a difference-in-differences framework. The results are consistent with the growth options view of green innovation in polluting firms. Additional evidence suggests that environmental regulatory uncertainty leads to reductions in toxic emissions.", "date": "2026-09-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06051", "title_zh": "\u7b49\u5f85\u8fd8\u662f\u884c\u52a8\uff1a\u73af\u5883\u76d1\u7ba1\u4e0d\u786e\u5b9a\u6027\u5bf9\u6c61\u67d3\u4f01\u4e1a\u7eff\u8272\u521b\u65b0\u7684\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u73af\u5883\u76d1\u7ba1\u4e0d\u786e\u5b9a\u6027\u5982\u4f55\u5f71\u54cd\u6c61\u67d3\u4f01\u4e1a\u7684\u7eff\u8272\u521b\u65b0\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u6c61\u67d3\u4f01\u4e1a\u5e76\u975e\u91c7\u53d6\u88ab\u52a8\u7684\u201c\u89c2\u671b\u7b49\u5f85\u201d\u7b56\u7565\uff0c\u800c\u662f\u4e3b\u52a8\u5f00\u5c55\u7eff\u8272\u521b\u65b0\u548c\u7814\u53d1\u6d3b\u52a8\u3002\u4e3a\u89e3\u51b3\u5185\u751f\u6027\u95ee\u9898\uff0c\u672c\u6587\u91c7\u7528\u7f8e\u56fd\u56fd\u4f1a\u73af\u5883\u4e0e\u6c14\u5019\u8bae\u9898\u6295\u7968\u4e2d\u7684\u653f\u6cbb\u6781\u5316\u4f5c\u4e3a\u5de5\u5177\u53d8\u91cf\u3002\u540c\u65f6\uff0c\u5229\u75282018\u5e74\u300a Affordable Clean Energy \u89c4\u5219\u300b\u63d0\u8bae\u8fd9\u4e00\u5916\u751f\u51b2\u51fb\uff0c\u5728\u5dee\u5206-\u5dee\u5206\u6846\u67b6\u4e0b\u8fdb\u884c\u5206\u6790\u3002\u7ed3\u679c\u652f\u6301\u4e86\u6c61\u67d3\u4f01\u4e1a\u7eff\u8272\u521b\u65b0\u7684\u201c\u589e\u957f\u671f\u6743\u201d\u7406\u8bba\u3002\u989d\u5916\u8bc1\u636e\u8868\u660e\uff0c\u73af\u5883\u76d1\u7ba1\u4e0d\u786e\u5b9a\u6027\u4f1a\u5bfc\u81f4\u6709\u6bd2\u6392\u653e\u91cf\u4e0b\u964d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2021.00481", "journal": "MS", "title": "Do Job Applicants Consider Founder Race and Gender? Evidence from a Field Experiment", "authors": ["Kaisa Snellman", "Peter Younkin"], "author_details": [{"name": "Kaisa Snellman", "affiliations": ["INSEAD, 77300 Fontainebleau, France"]}, {"name": "Peter Younkin", "affiliations": ["University of Oregon, Eugene, Oregon 97403"]}], "abstract": "Do job seekers consider the race or gender of an employer when applying for a job? Although we have extensive research on employer-side discrimination, we know less about employee-side biases and their consequences. In this study, we examine how the gender and race of the employer shape the willingness of prospective employees to apply for a job. To examine this, we conducted a field experiment where we randomized real jobseekers into three conditions according to employer demographics. We find that job candidates were less likely to apply to a job when they learn that the founders are Black, and, when they did apply, they requested 10% higher salary. In addition, the more qualified a candidate, the less likely they were to apply to Black founders, leaving Black founders with a pool of candidates that is smaller, worse, and more expensive than their White peers. We find no gender penalty for White female founders. Findings from two survey experiments suggest that the penalty is unique to White applicants evaluating Black founders and reflects a concern among White applicants that they will be less likely to fit within a firm and that the firm is less likely to be successful in the long run. We find no evidence of a widespread applicant homophily where all applicants favor founders of their own ethnic group, nor do we find evidence of widespread statistical discrimination whereby all applicants penalize Black founders for being atypical members of the entrepreneurial class.", "date": "2026-09-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2021.00481", "title_zh": "\u6c42\u804c\u8005\u662f\u5426\u4f1a\u8003\u8651\u521b\u59cb\u4eba\u79cd\u65cf\u548c\u6027\u522b\uff1f\u4e00\u9879\u5b9e\u5730\u5b9e\u9a8c\u7684\u8bc1\u636e", "abstract_zh": "\u6c42\u804c\u8005\u5728\u7533\u8bf7\u5de5\u4f5c\u65f6\u662f\u5426\u4f1a\u8003\u8651\u96c7\u4e3b\u7684\u79cd\u65cf\u6216\u6027\u522b\uff1f\u5c3d\u7ba1\u6211\u4eec\u5bf9\u96c7\u4e3b\u65b9\u9762\u7684\u6b67\u89c6\u6709\u5927\u91cf\u7814\u7a76\uff0c\u4f46\u5bf9\u4e8e\u6c42\u804c\u8005\u65b9\u9762\u7684\u504f\u89c1\u53ca\u5176\u540e\u679c\u4e86\u89e3\u4ecd\u7136\u6709\u9650\u3002\u5728\u672c\u7814\u7a76\u4e2d\uff0c\u6211\u4eec\u8003\u5bdf\u4e86\u96c7\u4e3b\u7684\u6027\u522b\u548c\u79cd\u65cf\u5982\u4f55\u5f71\u54cd\u6f5c\u5728\u5458\u5de5\u7533\u8bf7\u5de5\u4f5c\u7684\u610f\u613f\u3002\u4e3a\u6b64\uff0c\u6211\u4eec\u8fdb\u884c\u4e86\u4e00\u9879\u5b9e\u5730\u5b9e\u9a8c\uff0c\u5c06\u771f\u5b9e\u7684\u6c42\u804c\u8005\u968f\u673a\u5206\u914d\u5230\u4e09\u79cd\u4e0d\u540c\u96c7\u4e3b\u80cc\u666f\u7684\u6761\u4ef6\u4e0b\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5f53\u6c42\u804c\u8005\u5f97\u77e5\u521b\u59cb\u4eba\u662f\u9ed1\u4eba\u65f6\uff0c\u4ed6\u4eec\u7533\u8bf7\u5de5\u4f5c\u7684\u53ef\u80fd\u6027\u4f1a\u964d\u4f4e\uff0c\u4e14\u5728\u7533\u8bf7\u65f6\u8981\u6c42\u7684\u85aa\u8d44\u9ad8\u51fa10%\u3002\u6b64\u5916\uff0c\u8d8a\u6709\u8d44\u683c\u7684\u6c42\u804c\u8005\u8d8a\u4e0d\u613f\u610f\u7533\u8bf7\u9ed1\u4eba\u521b\u59cb\u4eba\u7684\u804c\u4f4d\uff0c\u5bfc\u81f4\u9ed1\u4eba\u521b\u59cb\u4eba\u6240\u83b7\u5f97\u7684\u5019\u9009\u4eba\u6c60\u89c4\u6a21\u66f4\u5c0f\u3001\u8d28\u91cf\u66f4\u5dee\u4e14\u6210\u672c\u66f4\u9ad8\uff0c\u4e0e\u767d\u4eba\u521b\u59cb\u4eba\u7684\u5019\u9009\u4eba\u6c60\u76f8\u6bd4\u5b58\u5728\u660e\u663e\u5dee\u8ddd\u3002\u6211\u4eec\u672a\u53d1\u73b0\u5bf9\u767d\u4eba\u5973\u6027\u521b\u59cb\u4eba\u7684\u6027\u522b\u60e9\u7f5a\u3002\u4e24\u9879\u8c03\u67e5\u5b9e\u9a8c\u7684\u7ed3\u679c\u8868\u660e\uff0c\u8fd9\u79cd\u60e9\u7f5a\u4ec5\u5b58\u5728\u4e8e\u767d\u4eba\u6c42\u804c\u8005\u8bc4\u4f30\u9ed1\u4eba\u521b\u59cb\u4eba\u65f6\uff0c\u53cd\u6620\u4e86\u767d\u4eba\u6c42\u804c\u8005\u62c5\u5fc3\u81ea\u5df1\u96be\u4ee5\u878d\u5165\u4f01\u4e1a\uff0c\u4ee5\u53ca\u4f01\u4e1a\u957f\u671f\u6210\u529f\u7684\u53ef\u80fd\u6027\u8f83\u4f4e\u7684\u62c5\u5fe7\u3002\u6211\u4eec\u6ca1\u6709\u53d1\u73b0\u666e\u904d\u5b58\u5728\u7684\u6c42\u804c\u8005\u540c\u8d28\u6027\u504f\u597d\uff0c\u5373\u6240\u6709\u6c42\u804c\u8005\u90fd\u504f\u597d\u4e0e\u81ea\u5df1\u79cd\u65cf\u76f8\u540c\u7684\u521b\u59cb\u4eba\uff0c\u4e5f\u672a\u53d1\u73b0\u666e\u904d\u5b58\u5728\u7684\u7edf\u8ba1\u6b67\u89c6\u73b0\u8c61\uff0c\u5373\u6240\u6709\u6c42\u804c\u8005\u56e0\u521b\u59cb\u4eba\u5c5e\u4e8e\u521b\u4e1a\u9636\u5c42\u4e2d\u7684\u975e\u5178\u578b\u6210\u5458\u800c\u5bf9\u9ed1\u4eba\u521b\u59cb\u4eba\u8fdb\u884c\u60e9\u7f5a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.01823", "journal": "MS", "title": "The Nonstationary Newsvendor: Data-Driven Nonparametric Learning", "authors": ["N. Bora Keskin", "Xu Min", "Jing-Sheng Song"], "author_details": [{"name": "N. Bora Keskin", "affiliations": ["Fuqua School of Business, Duke University, Durham, North Carolina 27708"]}, {"name": "Xu Min", "affiliations": ["School of Business and Management, Shanghai International Studies University, Shanghai 200083, China"]}, {"name": "Jing-Sheng Song", "affiliations": ["Fuqua School of Business, Duke University, Durham, North Carolina 27708"]}], "abstract": "We study a newsvendor problem with unknown demand distribution in a nonstationary demand environment over a multiperiod time horizon. The demand in each period consists of a time-varying demand level and an additive random shock. Neither the demand level nor the random shock is separately observable. The amount of change in the demand level over the time horizon is measured by a cumulative variation metric. The problem has widespread applications, such as perishable inventory planning, staffing, and medical resource capacity planning in the wake of COVID-19. We design a family of nonparametric dynamic ordering policies, termed two-stage estimation (2SE) policies, that track the shifts in the unknown demand level while accounting for the unobservable random demand shocks. To compute the order quantity in each period, these policies only need the past demand observations, without any access to the underlying demand distribution. For a finite variation \u201cbudget,\u201d we prove that our ordering policies are first-order optimal in the sense that their regret grows at the smallest possible rate. We also extend our analysis to the case of asymptotically large variation budgets. Through case studies based on real-life data, we show that our policies can save more than 20% of overage and underage costs, relative to policies widely used for perishable inventory replenishment and nurse staffing. Moreover, our simulation experiments indicate that our policies consistently maintain superior performance across diverse patterns of nonstationary demand environments.", "date": "2026-09-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.01823", "title_zh": "\u975e\u5e73\u7a33\u65b0\u95fb\u5546\u95ee\u9898\uff1a\u6570\u636e\u9a71\u52a8\u7684\u975e\u53c2\u6570\u5b66\u4e60", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u4e2a\u5728\u975e\u5e73\u7a33\u9700\u6c42\u73af\u5883\u4e0b\u3001\u5177\u6709\u672a\u77e5\u9700\u6c42\u5206\u5e03\u7684\u591a\u671f\u65b0\u95fb\u5546\u95ee\u9898\u3002\u6bcf\u4e2a\u65f6\u671f\u7684\u9700\u6c42\u7531\u4e00\u4e2a\u968f\u65f6\u95f4\u53d8\u5316\u7684\u9700\u6c42\u6c34\u5e73\u548c\u4e00\u4e2a\u52a0\u6027\u968f\u673a\u51b2\u51fb\u7ec4\u6210\u3002\u9700\u6c42\u6c34\u5e73\u548c\u968f\u673a\u51b2\u51fb\u5747\u4e0d\u53ef\u89c2\u6d4b\u3002\u65f6\u95f4\u8de8\u5ea6\u5185\u9700\u6c42\u6c34\u5e73\u7684\u53d8\u5316\u901a\u8fc7\u7d2f\u79ef\u53d8\u5316\u5ea6\u91cf\u6765\u8861\u91cf\u3002\u8be5\u95ee\u9898\u5728\u591a\u4e2a\u9886\u57df\u5177\u6709\u5e7f\u6cdb\u5e94\u7528\uff0c\u4f8b\u5982\u6613\u8150\u5e93\u5b58\u89c4\u5212\u3001\u4eba\u5458\u914d\u7f6e\uff0c\u4ee5\u53ca\u65b0\u51a0\u75ab\u60c5\u540e\u533b\u7597\u8d44\u6e90\u5bb9\u91cf\u89c4\u5212\u3002\u6211\u4eec\u8bbe\u8ba1\u4e86\u4e00\u7c7b\u975e\u53c2\u6570\u52a8\u6001\u8ba2\u8d27\u7b56\u7565\uff0c\u79f0\u4e3a\u4e24\u9636\u6bb5\u4f30\u8ba1\uff082SE\uff09\u7b56\u7565\uff0c\u8fd9\u4e9b\u7b56\u7565\u80fd\u591f\u8ffd\u8e2a\u672a\u77e5\u9700\u6c42\u6c34\u5e73\u7684\u53d8\u5316\uff0c\u540c\u65f6\u8003\u8651\u4e0d\u53ef\u89c2\u6d4b\u7684\u968f\u673a\u9700\u6c42\u51b2\u51fb\u3002\u4e3a\u4e86\u5728\u6bcf\u4e2a\u65f6\u671f\u8ba1\u7b97\u8ba2\u8d27\u91cf\uff0c\u8fd9\u4e9b\u7b56\u7565\u4ec5\u9700\u5386\u53f2\u9700\u6c42\u89c2\u6d4b\u6570\u636e\uff0c\u800c\u65e0\u9700\u8bbf\u95ee\u6f5c\u5728\u7684\u9700\u6c42\u5206\u5e03\u3002\u5bf9\u4e8e\u6709\u9650\u53d8\u5316\u2018\u9884\u7b97\u2019\uff0c\u6211\u4eec\u8bc1\u660e\u4e86\u6211\u4eec\u7684\u8ba2\u8d27\u7b56\u7565\u5728\u7b2c\u4e00\u9636\u6700\u4f18\u610f\u4e49\u4e0a\u662f\u6700\u4f18\u7684\uff0c\u5373\u5176\u9057\u61be\u589e\u957f\u901f\u7387\u662f\u6700\u5c0f\u53ef\u80fd\u7684\u3002\u6211\u4eec\u8fd8\u5c06\u5206\u6790\u6269\u5c55\u5230\u6e10\u8fd1\u5927\u53d8\u5316\u9884\u7b97\u7684\u60c5\u51b5\u3002\u57fa\u4e8e\u771f\u5b9e\u6570\u636e\u7684\u6848\u4f8b\u7814\u7a76\u8868\u660e\uff0c\u6211\u4eec\u7684\u7b56\u7565\u76f8\u5bf9\u4e8e\u5e7f\u6cdb\u7528\u4e8e\u6613\u8150\u5e93\u5b58\u8865\u8d27\u548c\u62a4\u58eb\u914d\u7f6e\u7684\u73b0\u6709\u7b56\u7565\uff0c\u53ef\u8282\u7701\u8d85\u8fc720%\u7684\u8fc7\u5269\u548c\u77ed\u7f3a\u6210\u672c\u3002\u6b64\u5916\uff0c\u6211\u4eec\u7684\u6a21\u62df\u5b9e\u9a8c\u8868\u660e\uff0c\u6211\u4eec\u7684\u7b56\u7565\u5728\u5404\u79cd\u975e\u5e73\u7a33\u9700\u6c42\u73af\u5883\u6a21\u5f0f\u4e0b\u5747\u80fd\u4fdd\u6301\u5353\u8d8a\u7684\u6027\u80fd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20241087", "journal": "AER", "title": "Manipulation-Robust Prediction", "authors": ["Daniel Bj\u00f6rkegren", "Joshua E. Blumenstock", "Samsun Knight"], "author_details": [{"name": "Daniel Bj\u00f6rkegren", "affiliations": ["Columbia University (email: )"]}, {"name": "Joshua E. Blumenstock", "affiliations": ["UC Berkeley (email: )"]}, {"name": "Samsun Knight", "affiliations": ["University of Toronto (email: )"]}], "abstract": "An increasing number of decisions are guided by machine learning algorithms. But when consequential decisions are encoded in algorithms, individuals may strategically alter their behavior to achieve desired outcomes. This paper develops an empirical approach that adjusts decision algorithms to anticipate manipulation. By explicitly modeling incentives to manipulate, our approach produces decision rules that are stable under manipulation, even when the rules are fully transparent. We stress-test this approach through a large field experiment in Kenya. When implemented, linear strategy-robust decision rules outperform standard linear models such as LASSO. (JEL C45, C93, D12, D91, G51, O12, O16)", "date": "2026-09-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20241087", "title_zh": "\u6297\u64cd\u7eb5\u9884\u6d4b", "abstract_zh": "\u8d8a\u6765\u8d8a\u591a\u7684\u51b3\u7b56\u4f9d\u8d56\u4e8e\u673a\u5668\u5b66\u4e60\u7b97\u6cd5\u3002\u7136\u800c\uff0c\u5f53\u5177\u6709\u91cd\u5927\u5f71\u54cd\u7684\u51b3\u7b56\u88ab\u7f16\u7801\u8fdb\u7b97\u6cd5\u65f6\uff0c\u4e2a\u4f53\u53ef\u80fd\u4f1a\u6709\u7b56\u7565\u6027\u5730\u6539\u53d8\u5176\u884c\u4e3a\u4ee5\u8fbe\u5230\u671f\u671b\u7684\u7ed3\u679c\u3002\u672c\u6587\u63d0\u51fa\u4e86\u4e00\u79cd\u7ecf\u9a8c\u65b9\u6cd5\uff0c\u901a\u8fc7\u663e\u5f0f\u5efa\u6a21\u64cd\u7eb5\u7684\u6fc0\u52b1\uff0c\u8c03\u6574\u51b3\u7b56\u7b97\u6cd5\u4ee5\u9884\u6d4b\u64cd\u7eb5\u884c\u4e3a\u3002\u8fd9\u79cd\u65b9\u6cd5\u5728\u51b3\u7b56\u89c4\u5219\u5b8c\u5168\u900f\u660e\u7684\u60c5\u51b5\u4e0b\uff0c\u80fd\u591f\u4ea7\u751f\u5728\u9762\u5bf9\u64cd\u7eb5\u65f6\u4ecd\u4fdd\u6301\u7a33\u5b9a\u7684\u89c4\u5219\u3002\u6211\u4eec\u901a\u8fc7\u80af\u5c3c\u4e9a\u7684\u4e00\u9879\u5927\u89c4\u6a21\u5b9e\u5730\u5b9e\u9a8c\u5bf9\u8fd9\u4e00\u65b9\u6cd5\u8fdb\u884c\u4e86\u538b\u529b\u6d4b\u8bd5\u3002\u5f53\u5b9e\u65bd\u65f6\uff0c\u7ebf\u6027\u7b56\u7565\u7a33\u5065\u7684\u51b3\u7b56\u89c4\u5219\u5728\u6027\u80fd\u4e0a\u4f18\u4e8e\u6807\u51c6\u7684\u7ebf\u6027\u6a21\u578b\uff0c\u5982LASSO\u3002\uff08JEL C45, C93, D12, D91, G51, O12, O16\uff09", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1257/aer.20240404", "journal": "AER", "title": "Corporate Tax Cuts, Firm Growth, and Workers' Earnings", "authors": ["Patrick J. Kennedy", "Christine L. Dobridge", "Paul Landefeld", "Jacob Mortenson"], "author_details": [{"name": "Patrick J. Kennedy", "affiliations": ["UCLA, NBER, and JCT (email: )"]}, {"name": "Christine L. Dobridge", "affiliations": ["Federal Reserve Board (email: )"]}, {"name": "Paul Landefeld", "affiliations": ["JCT (email: )"]}, {"name": "Jacob Mortenson", "affiliations": ["JCT (email: )"]}], "abstract": "We study the effects of the largest corporate income tax cut in US history on firms and workers. To identify causal effects, we use employer-employee matched tax records and event studies comparing similarly sized firms in the same industry that faced divergent tax changes due to their preexisting legal status. Tax cuts cause increases in firms' investment, sales, profits, employment, and payrolls, with earnings gains concentrated among highly paid workers. In the short run, 87 percent of private income gains flow to the top 10 percent of the income distribution. (JEL D22, D31, G31, H25, H32, J23, L25)", "date": "2026-09-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240404", "title_zh": "\u4f01\u4e1a\u6240\u5f97\u7a0e\u51cf\u514d\u5bf9\u4f01\u4e1a\u53d1\u5c55\u4e0e\u5458\u5de5\u6536\u5165\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u7f8e\u56fd\u5386\u53f2\u4e0a\u6700\u5927\u7684\u4f01\u4e1a\u6240\u5f97\u7a0e\u51cf\u514d\u5bf9\u4f01\u4e1a\u53ca\u5458\u5de5\u7684\u5f71\u54cd\u3002\u4e3a\u4e86\u8bc6\u522b\u56e0\u679c\u6548\u5e94\uff0c\u6211\u4eec\u5229\u7528\u96c7\u4e3b-\u5458\u5de5\u5339\u914d\u7684\u7a0e\u52a1\u8bb0\u5f55\uff0c\u5e76\u901a\u8fc7\u6bd4\u8f83\u540c\u4e00\u884c\u4e1a\u3001\u89c4\u6a21\u76f8\u4f3c\u4f46\u56e0\u9884\u5148\u5b58\u5728\u7684\u6cd5\u5f8b\u5730\u4f4d\u800c\u9762\u4e34\u4e0d\u540c\u7a0e\u8d1f\u53d8\u5316\u7684\u4f01\u4e1a\u8fdb\u884c\u4e8b\u4ef6\u7814\u7a76\u3002\u7a0e\u6536\u51cf\u514d\u5bfc\u81f4\u4f01\u4e1a\u6295\u8d44\u3001\u9500\u552e\u989d\u3001\u5229\u6da6\u3001\u5c31\u4e1a\u548c\u5de5\u8d44\u603b\u989d\u589e\u52a0\uff0c\u6536\u5165\u589e\u957f\u4e3b\u8981\u96c6\u4e2d\u5728\u9ad8\u6536\u5165\u5458\u5de5\u7fa4\u4f53\u4e2d\u3002\u77ed\u671f\u5185\uff0c87%\u7684\u79c1\u4eba\u6536\u5165\u589e\u957f\u6d41\u5411\u6536\u5165\u5206\u5e03\u7684\u524d10%\u3002 (JEL D22, D31, G31, H25, H32, J23, L25)", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240701", "journal": "AER", "title": "Rationing by Race", "authors": ["Manasvini Singh", "Atheendar Venkataramani"], "author_details": [{"name": "Manasvini Singh", "affiliations": ["Carnegie Mellon University and NBER (email: )"]}, {"name": "Atheendar Venkataramani", "affiliations": ["University of Pennsylvania and NBER (email: )"]}], "abstract": "We document how deepening resource scarcity results in rationing on the basis of race in a high-stakes setting: health care. Using detailed, time stamped data on 107,000 inpatient admissions to a large health system, we find that in-hospital mortality increases for Black but not White patients as hospitals reach capacity. These findings are not explained by differential patient selection. We identify rationing by wait times as a mechanism, documenting that sicker Black patients wait longer for care than healthier White patients at almost all capacity levels. Text analysis of unstructured clinical notes reveals rationing of provider effort as another mechanism. (JEL I11, I12, I14, J15)", "date": "2026-09-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240701", "title_zh": "\u6309\u79cd\u65cf\u914d\u7ed9", "abstract_zh": "\u672c\u6587\u8bb0\u5f55\u4e86\u5728\u533b\u7597\u8fd9\u4e00\u5173\u7cfb\u91cd\u5927\u7684\u573a\u666f\u4e2d\uff0c\u8d44\u6e90\u65e5\u76ca\u7a00\u7f3a\u5982\u4f55\u5bfc\u81f4\u57fa\u4e8e\u79cd\u65cf\u7684\u914d\u7ed9\u3002\u5229\u7528\u67d0\u5927\u578b\u533b\u7597\u7cfb\u7edf 107,000 \u6b21\u4f4f\u9662\u7684\u8be6\u7ec6\u65f6\u95f4\u6233\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u968f\u7740\u533b\u9662\u63a5\u8fd1\u5bb9\u91cf\u4e0a\u9650\uff0c\u9ed1\u4eba\u60a3\u8005\u7684\u9662\u5185\u6b7b\u4ea1\u7387\u4e0a\u5347\uff0c\u800c\u767d\u4eba\u60a3\u8005\u6ca1\u6709\u51fa\u73b0\u8fd9\u4e00\u53d8\u5316\u3002\u8fd9\u4e9b\u53d1\u73b0\u4e0d\u80fd\u7528\u60a3\u8005\u9009\u62e9\u5dee\u5f02\u6765\u89e3\u91ca\u3002\u6211\u4eec\u8bc6\u522b\u51fa\u901a\u8fc7\u7b49\u5019\u65f6\u95f4\u8fdb\u884c\u914d\u7ed9\u8fd9\u4e00\u673a\u5236\uff1a\u5728\u51e0\u4e4e\u6240\u6709\u5bb9\u91cf\u6c34\u5e73\u4e0b\uff0c\u75c5\u60c5\u66f4\u91cd\u7684\u9ed1\u4eba\u60a3\u8005\u7b49\u5f85\u533b\u7597\u670d\u52a1\u7684\u65f6\u95f4\uff0c\u90fd\u957f\u4e8e\u75c5\u60c5\u8f83\u8f7b\u7684\u767d\u4eba\u60a3\u8005\u3002\u5bf9\u975e\u7ed3\u6784\u5316\u4e34\u5e8a\u8bb0\u5f55\u8fdb\u884c\u6587\u672c\u5206\u6790\uff0c\u8fd8\u63ed\u793a\u4e86\u53e6\u4e00\u79cd\u673a\u5236\uff0c\u5373\u5bf9\u533b\u52a1\u4eba\u5458\u6295\u5165\u7684\u52aa\u529b\u8fdb\u884c\u914d\u7ed9\u3002\uff08JEL\uff1aI11\u3001I12\u3001I14\u3001J15\uff09", "translation_source": "\u9996\u7248\u6837\u4f8b\uff1a\u7531 Codex \u6839\u636e\u516c\u5f00\u6458\u8981\u7ffb\u8bd1\uff0c\u975e Qwen \u8f93\u51fa", "topics": ["\u6587\u672c\u5206\u6790"]}, {"doi": "10.1257/aer.20230768", "journal": "AER", "title": "Optimal Public Transportation Networks: Evidence from the World's Largest Bus Rapid Transit System in Jakarta", "authors": ["Gabriel Kreindler", "Arya Gaduh", "Tilman Graff", "Rema Hanna", "Benjamin A. Olken"], "author_details": [{"name": "Gabriel Kreindler", "affiliations": ["Harvard University (email: )"]}, {"name": "Arya Gaduh", "affiliations": ["University of Arkansas (email: )"]}, {"name": "Tilman Graff", "affiliations": ["Harvard University (email: )"]}, {"name": "Rema Hanna", "affiliations": ["Harvard Kennedy School (email: )"]}, {"name": "Benjamin A. Olken", "affiliations": ["MIT (email: )"]}], "abstract": "Designing public transport networks involves trade-offs between coverage, service frequency, and direct service. We use the expansion of the bus system in Jakarta, Indonesia, to study these trade-offs. We analyze how new direct connections, changes in bus travel time, and wait-time reductions affect bus ridership and aggregate flows and estimate a transit network demand model by matching the route launch events. Commuters in Jakarta are 2\u20133 times more sensitive to wait time than bus time and inattentive to long routes. We develop a flexible framework to characterize optimal networks. A less concentrated network would increase ridership and commuter welfare. (JEL L92, L98, O18, R41, R42, R48)", "date": "2026-09-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230768", "title_zh": "\u6700\u4f18\u516c\u5171\u4ea4\u901a\u7f51\u7edc\uff1a\u6765\u81ea\u5370\u5ea6\u5c3c\u897f\u4e9a\u96c5\u52a0\u8fbe\u5168\u7403\u6700\u5927\u516c\u4ea4\u5feb\u901f\u4ea4\u901a\u7cfb\u7edf\u7684\u8bc1\u636e", "abstract_zh": "\u8bbe\u8ba1\u516c\u5171\u4ea4\u901a\u7f51\u7edc\u9700\u8981\u5728\u8986\u76d6\u8303\u56f4\u3001\u670d\u52a1\u9891\u7387\u548c\u76f4\u8fbe\u670d\u52a1\u4e4b\u95f4\u8fdb\u884c\u6743\u8861\u3002\u6211\u4eec\u5229\u7528\u5370\u5ea6\u5c3c\u897f\u4e9a\u96c5\u52a0\u8fbe\u516c\u4ea4\u7cfb\u7edf\u6269\u5c55\u7684\u6848\u4f8b\uff0c\u7814\u7a76\u8fd9\u4e9b\u6743\u8861\u3002\u6211\u4eec\u5206\u6790\u4e86\u65b0\u76f4\u8fbe\u7ebf\u8def\u7684\u5f00\u901a\u3001\u516c\u4ea4\u51fa\u884c\u65f6\u95f4\u53d8\u5316\u4ee5\u53ca\u7b49\u5f85\u65f6\u95f4\u51cf\u5c11\u5bf9\u516c\u4ea4\u4e58\u5ba2\u91cf\u548c\u603b\u4f53\u5ba2\u6d41\u7684\u5f71\u54cd\uff0c\u5e76\u901a\u8fc7\u5339\u914d\u8def\u7ebf\u5f00\u901a\u4e8b\u4ef6\uff0c\u4f30\u8ba1\u4e86\u4e00\u4e2a\u516c\u5171\u4ea4\u901a\u7f51\u7edc\u9700\u6c42\u6a21\u578b\u3002\u96c5\u52a0\u8fbe\u7684\u901a\u52e4\u8005\u5bf9\u7b49\u5f85\u65f6\u95f4\u7684\u654f\u611f\u5ea6\u662f\u516c\u4ea4\u884c\u9a76\u65f6\u95f4\u76842\u81f33\u500d\uff0c\u800c\u5bf9\u957f\u9014\u8def\u7ebf\u5219\u6f20\u4e0d\u5173\u5fc3\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u7075\u6d3b\u7684\u6846\u67b6\u6765\u523b\u753b\u6700\u4f18\u7f51\u7edc\u7ed3\u6784\u3002\u4e00\u4e2a\u5206\u5e03\u66f4\u5206\u6563\u7684\u7f51\u7edc\u5c06\u63d0\u9ad8\u4e58\u5ba2\u91cf\u548c\u901a\u52e4\u8005\u7684\u798f\u5229\u3002\uff08JEL L92, L98, O18, R41, R42, R48\uff09", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1257/aer.20240579", "journal": "AER", "title": "Contextually Private Mechanisms", "authors": ["Andreas Haupt", "Zo\u00eb Hitzig"], "author_details": [{"name": "Andreas Haupt", "affiliations": ["Stanford Digital Economy Lab (email: )"]}, {"name": "Zo\u00eb Hitzig", "affiliations": ["Harvard Society of Fellows (email: )"]}], "abstract": "A designer employs a dynamic protocol to elicit private information. Protocols produce a set of contextual privacy violations\u2014information learned that may be superfluous given the context. A protocol is maximally contextually private if there is no protocol that produces a proper subset of the violations it produces, while implementing the choice rule. Contextual privacy violations arise when a choice rule makes some agents collectively, but not individually, pivotal. In auctions, designing for contextual privacy requires choosing an initial question posed to each agent and the order for querying agents. Ascending-join protocols are maximally contextually private for k-item Vickrey auctions. (JEL D44, D82)", "date": "2026-09-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240579", "title_zh": "\u4e0a\u4e0b\u6587\u79c1\u6709\u673a\u5236", "abstract_zh": "\u8bbe\u8ba1\u8005\u91c7\u7528\u52a8\u6001\u534f\u8bae\u6765\u83b7\u53d6\u79c1\u6709\u4fe1\u606f\u3002\u534f\u8bae\u4f1a\u4ea7\u751f\u4e00\u7ec4\u4e0a\u4e0b\u6587\u9690\u79c1\u8fdd\u89c4\u2014\u2014\u5373\u5728\u7ed9\u5b9a\u60c5\u5883\u4e0b\u53ef\u80fd\u591a\u4f59\u83b7\u5f97\u7684\u4fe1\u606f\u3002\u5982\u679c\u4e0d\u5b58\u5728\u53e6\u4e00\u4e2a\u534f\u8bae\u5728\u5b9e\u73b0\u76f8\u540c\u51b3\u7b56\u89c4\u5219\u7684\u540c\u65f6\u4ea7\u751f\u4e00\u4e2a\u771f\u5b50\u96c6\u7684\u8fdd\u89c4\u4fe1\u606f\uff0c\u5219\u8be5\u534f\u8bae\u88ab\u79f0\u4e3a\u6700\u5927\u4e0a\u4e0b\u6587\u79c1\u6709\u673a\u5236\u3002\u4e0a\u4e0b\u6587\u9690\u79c1\u8fdd\u89c4\u51fa\u73b0\u5728\u51b3\u7b56\u89c4\u5219\u4f7f\u5f97\u67d0\u4e9b\u4ee3\u7406\u4eba\u96c6\u4f53\u4e0a\u5177\u6709\u5173\u952e\u6027\uff0c\u4f46\u4e2a\u4f53\u4e0a\u4e0d\u5177\u6709\u5173\u952e\u6027\u65f6\u3002\u5728\u62cd\u5356\u4e2d\uff0c\u4e3a\u4e86\u5b9e\u73b0\u4e0a\u4e0b\u6587\u9690\u79c1\uff0c\u9700\u8981\u4e3a\u6bcf\u4e2a\u4ee3\u7406\u4eba\u9009\u62e9\u521d\u59cb\u63d0\u95ee\u5185\u5bb9\u4ee5\u53ca\u67e5\u8be2\u4ee3\u7406\u4eba\u7684\u987a\u5e8f\u3002\u5bf9\u4e8ek\u9879\u7ef4\u514b\u745e\u62cd\u5356\uff0c\u4e0a\u5347\u5408\u5e76\u534f\u8bae\u662f\u6700\u5927\u4e0a\u4e0b\u6587\u79c1\u6709\u673a\u5236\u3002\uff08JEL D44\uff0cD82\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20241001", "journal": "AER", "title": "Intergenerational Impacts of Secondary Education: Experimental Evidence from Ghana", "authors": ["Esther Duflo", "Pascaline Dupas", "Elizabeth Spelke", "Mark Walsh"], "author_details": [{"name": "Esther Duflo", "affiliations": ["MIT and Coll\u00e8ge de France (email: )"]}, {"name": "Pascaline Dupas", "affiliations": ["Princeton University (email: )"]}, {"name": "Elizabeth Spelke", "affiliations": ["Harvard University (email: )"]}, {"name": "Mark Walsh", "affiliations": ["GiveWell ()"]}], "abstract": "We provide experimental evidence on the intergenerational impacts of secondary education subsidies in a low-income context, leveraging a randomized controlled trial and 15-year longitudinal follow-up. Secondary school scholarships delay fertility, reduce unwanted pregnancies, and change partner selection. Under-one mortality is reduced by half. We also document cognitive development gains of 0.24 standard deviations of test scores by age five among children of female scholarship recipients. Means-tested secondary school scholarships are a high-return investment, with a conservatively estimated US$4.1 in benefits for each US$1 the policy would cost the government in the long run. (JEL H52, I12, I21, I26, J13, J16, O15)", "date": "2026-09-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20241001", "title_zh": "\u4e2d\u7b49\u6559\u80b2\u7684\u4ee3\u9645\u5f71\u54cd\uff1a\u6765\u81ea\u52a0\u7eb3\u7684\u5b9e\u9a8c\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u57fa\u4e8e\u4e00\u9879\u968f\u673a\u5bf9\u7167\u8bd5\u9a8c\u548c\u957f\u8fbe15\u5e74\u7684\u7eb5\u5411\u8ffd\u8e2a\u7814\u7a76\uff0c\u63d0\u4f9b\u4e86\u4f4e\u6536\u5165\u80cc\u666f\u4e0b\u4e2d\u7b49\u6559\u80b2\u8865\u8d34\u4ee3\u9645\u5f71\u54cd\u7684\u5b9e\u9a8c\u8bc1\u636e\u3002\u4e2d\u7b49\u5b66\u6821\u5956\u5b66\u91d1\u5ef6\u8fdf\u4e86\u751f\u80b2\uff0c\u51cf\u5c11\u4e86\u975e\u610f\u613f\u6000\u5b55\uff0c\u5e76\u6539\u53d8\u4e86\u4f34\u4fa3\u9009\u62e9\u3002\u5a74\u5e7c\u513f\u6b7b\u4ea1\u7387\u964d\u4f4e\u4e86\u4e00\u534a\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0c\u5973\u6027\u83b7\u5f97\u5956\u5b66\u91d1\u5b50\u5973\u5728\u4e94\u5c81\u65f6\u7684\u8ba4\u77e5\u53d1\u5c55\u6c34\u5e73\u63d0\u9ad8\u4e860.24\u4e2a\u6807\u51c6\u5dee\u7684\u6d4b\u9a8c\u5206\u6570\u3002\u57fa\u4e8e\u6536\u5165\u7684\u4e2d\u7b49\u5b66\u6821\u5956\u5b66\u91d1\u662f\u4e00\u9879\u9ad8\u56de\u62a5\u7684\u6295\u8d44\uff0c\u957f\u671f\u6765\u770b\uff0c\u6bcf\u6295\u51651\u7f8e\u5143\u653f\u5e9c\u6210\u672c\uff0c\u53ef\u5e26\u6765\u4fdd\u5b88\u4f30\u8ba1\u76844.1\u7f8e\u5143\u7684\u6536\u76ca\u3002\uff08JEL H52, I12, I21, I26, J13, J16, O15\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.116.9.3197", "journal": "AER", "title": "Presidential Address: Neighborhood Effects and Missing Markets for Opportunity", "authors": ["Lawrence F. Katz"], "author_details": [{"name": "Lawrence F. Katz", "affiliations": ["Harvard University (email: )"]}], "abstract": "Experimental and quasi-experimental studies show that childhood neighborhoods have substantial causal impacts on children's adult earnings and other long-term socioeconomic outcomes. Several market failures are likely to lead to excessive residential segregation by parental income and to an undersupply of mixed-income neighborhoods. Missing markets for opportunity originate in capital market imperfections for borrowing on children's future earnings, neighbor spillovers, behavioral biases, and housing search frictions. Customized housing mobility services combined with subsidized housing vouchers can help low-income families move to higher-opportunity areas. Place-based policies that create mixed-income neighborhoods appear to increase long-term outcomes for less-advantaged children. (JEL I12, I32, I38, J13, J15, R23, R38)", "date": "2026-09-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.116.9.3197", "title_zh": "\u603b\u7edf\u6f14\u8bb2\uff1a\u90bb\u91cc\u6548\u5e94\u4e0e\u673a\u4f1a\u5e02\u573a\u7684\u7f3a\u5931", "abstract_zh": "\u5b9e\u9a8c\u6027\u53ca\u51c6\u5b9e\u9a8c\u6027\u7814\u7a76\u663e\u793a\uff0c\u513f\u7ae5\u6210\u957f\u7684\u90bb\u91cc\u73af\u5883\u5bf9\u5176\u6210\u5e74\u540e\u7684\u6536\u5165\u53ca\u5176\u4ed6\u957f\u671f\u793e\u4f1a\u7ecf\u6d4e\u7ed3\u679c\u5177\u6709\u663e\u8457\u7684\u56e0\u679c\u5f71\u54cd\u3002\u82e5\u5e72\u5e02\u573a\u5931\u7075\u53ef\u80fd\u5bfc\u81f4\u7531\u7236\u6bcd\u6536\u5165\u5f15\u53d1\u7684\u8fc7\u5ea6\u4f4f\u5b85\u9694\u79bb\uff0c\u4ee5\u53ca\u6df7\u5408\u6536\u5165\u793e\u533a\u4f9b\u7ed9\u4e0d\u8db3\u3002\u673a\u4f1a\u5e02\u573a\u7684\u7f3a\u5931\u6e90\u4e8e\u513f\u7ae5\u672a\u6765\u6536\u5165\u7684\u4fe1\u8d37\u5e02\u573a\u4e0d\u5b8c\u5584\u3001\u90bb\u91cc\u6ea2\u51fa\u6548\u5e94\u3001\u884c\u4e3a\u504f\u8bef\u4ee5\u53ca\u4f4f\u623f\u641c\u5bfb\u6469\u64e6\u3002\u7ed3\u5408\u5b9a\u5236\u5316\u7684\u4f4f\u623f\u6d41\u52a8\u6027\u670d\u52a1\u5e76\u8f85\u4ee5\u4f4f\u623f\u8865\u8d34\u5238\uff0c\u53ef\u4ee5\u5e2e\u52a9\u4f4e\u6536\u5165\u5bb6\u5ead\u8fc1\u79fb\u5230\u66f4\u9ad8\u673a\u4f1a\u533a\u57df\u3002\u57fa\u4e8e\u5730\u57df\u7684\u653f\u7b56\u4ee5\u5f62\u6210\u6df7\u5408\u6536\u5165\u793e\u533a\uff0c\u4f3c\u4e4e\u80fd\u591f\u63d0\u5347\u5f31\u52bf\u513f\u7ae5\u7684\u957f\u671f\u53d1\u5c55\u7ed3\u679c\u3002\uff08JEL I12, I32, I38, J13, J15, R23, R38\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240664", "journal": "AER", "title": "Risk-Sharing Tests and Covariate Shocks: Drought, Floods, and Pests in Uganda", "authors": ["Ethan Ligon"], "author_details": [{"name": "Ethan Ligon", "affiliations": ["University of California, Berkeley (email: )"]}], "abstract": "Efficient risk sharing implies a simple factor structure for marginal utilities of expenditure (MUEs): Pareto weights divided by a common price. The standard approach infers MUEs from total expenditures, implicitly assuming homothetic preferences, unitary income elasticities, and identical price elasticities. Risk-sharing tests using total expenditures work for idiosyncratic shocks (budgets change, but not prices), but not \u201ccovariate\u201d shocks (prices change). I describe all preferences that permit one to infer MUEs from expenditures and estimate nonhomothetic MUEs to test whether covariate shocks are shared efficiently in Uganda. This delivers sensible results; the standard approach suggests that droughts, floods, and pests are beneficial. (JEL D12, D81, O12, O13, Q12)", "date": "2026-09-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240664", "title_zh": "\u98ce\u9669\u5206\u62c5\u68c0\u9a8c\u4e0e\u534f\u53d8\u91cf\u51b2\u51fb\uff1a\u4e4c\u5e72\u8fbe\u7684\u5e72\u65f1\u3001\u6d2a\u6c34\u548c\u75c5\u866b\u5bb3", "abstract_zh": "\u6709\u6548\u7684\u98ce\u9669\u5206\u62c5\u610f\u5473\u7740\u652f\u51fa\u8fb9\u9645\u6548\u7528\uff08MUEs\uff09\u5177\u6709\u7b80\u5355\u7684\u56e0\u5b50\u7ed3\u6784\uff1a\u5e15\u7d2f\u6258\u6743\u91cd\u9664\u4ee5\u4e00\u4e2a\u5171\u540c\u7684\u4ef7\u683c\u3002\u6807\u51c6\u65b9\u6cd5\u901a\u8fc7\u603b\u652f\u51fa\u63a8\u65adMUEs\uff0c\u9690\u542b\u5047\u8bbe\u4e86\u540c\u8d28\u504f\u597d\u3001\u5355\u4f4d\u6536\u5165\u5f39\u6027\u4ee5\u53ca\u76f8\u540c\u7684\u4ef7\u683c\u5f39\u6027\u3002\u57fa\u4e8e\u603b\u652f\u51fa\u7684\u98ce\u9669\u5206\u62c5\u68c0\u9a8c\u9002\u7528\u4e8e\u7279\u8d28\u98ce\u9669\uff08\u9884\u7b97\u53d1\u751f\u53d8\u5316\uff0c\u4f46\u4ef7\u683c\u4e0d\u53d8\uff09\uff0c\u800c\u4e0d\u9002\u7528\u4e8e\u201c\u534f\u53d8\u91cf\u201d\u51b2\u51fb\uff08\u4ef7\u683c\u53d1\u751f\u53d8\u5316\uff09\u3002\u6211\u63cf\u8ff0\u4e86\u6240\u6709\u5141\u8bb8\u4ece\u652f\u51fa\u4e2d\u63a8\u65adMUEs\u7684\u504f\u597d\uff0c\u5e76\u4f30\u8ba1\u4e86\u975e\u540c\u8d28MUEs\uff0c\u4ee5\u68c0\u9a8c\u4e4c\u5e72\u8fbe\u4e2d\u5e72\u65f1\u3001\u6d2a\u6c34\u548c\u75c5\u866b\u5bb3\u7b49\u534f\u53d8\u91cf\u51b2\u51fb\u662f\u5426\u5f97\u5230\u4e86\u6709\u6548\u5206\u62c5\u3002\u7ed3\u679c\u5408\u7406\uff1b\u6807\u51c6\u65b9\u6cd5\u8868\u660e\uff0c\u5e72\u65f1\u3001\u6d2a\u6c34\u548c\u75c5\u866b\u5bb3\u662f\u5177\u6709\u76ca\u5904\u7684\u3002\uff08JEL D12, D81, O12, O13, Q12\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240756", "journal": "AER", "title": "Defying Distance? The Provision of Medical Services in the Digital Age", "authors": ["Amanda Dahlstrand"], "author_details": [{"name": "Amanda Dahlstrand", "affiliations": ["University of Zurich (email: )"]}], "abstract": "Digital platforms reduce geographic frictions, enabling better matching between service providers and users. I quantify reallocation gains in Swedish online health care, using nationwide time-conditional random assignment between patients and physicians. Matching high-risk patients with doctors effective at reducing Emergency Room visits lowers such visits by 4.4 percent (SE 1.3); reallocations also reduce Counter-Guideline antibiotics by 3.1 percent (1.4). I find limited trade-offs in matching; horizontal differentiation among doctors and varied patient needs allow improvement in multiple outcomes simultaneously. Efficiency-enhancing reallocations also affect equity. The findings highlight the potential for care reorganization aligning provider heterogeneity with patient needs when geographic constraints are lifted. (JEL C78, H51, I11, I13, I14, I18)", "date": "2026-09-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240756", "title_zh": "\u8ddd\u79bb\u7684\u6311\u6218\uff1f\u6570\u5b57\u65f6\u4ee3\u533b\u7597\u670d\u52a1\u4f53\u7cfb\u7684\u63d0\u4f9b", "abstract_zh": "\u6570\u5b57\u5e73\u53f0\u964d\u4f4e\u4e86\u5730\u7406\u969c\u788d\uff0c\u4fc3\u8fdb\u4e86\u670d\u52a1\u63d0\u4f9b\u8005\u4e0e\u7528\u6237\u4e4b\u95f4\u7684\u66f4\u597d\u5339\u914d\u3002\u6211\u5229\u7528\u745e\u5178\u5168\u56fd\u8303\u56f4\u5185\u7684\u60a3\u8005\u4e0e\u533b\u751f\u65f6\u95f4\u6761\u4ef6\u968f\u673a\u5206\u914d\uff0c\u91cf\u5316\u4e86\u5728\u7ebf\u533b\u7597\u4e2d\u7684\u518d\u5206\u914d\u6536\u76ca\u3002\u5c06\u9ad8\u98ce\u9669\u60a3\u8005\u5339\u914d\u7ed9\u80fd\u591f\u6709\u6548\u51cf\u5c11\u6025\u8bca\u5c31\u8bca\u7684\u533b\u751f\uff0c\u4f7f\u6025\u8bca\u5c31\u8bca\u91cf\u4e0b\u964d4.4%\uff08\u6807\u51c6\u8bef1.3%\uff09\uff1b\u518d\u5206\u914d\u8fd8\u4f7f\u504f\u79bb\u6307\u5357\u7684\u6297\u751f\u7d20\u4f7f\u7528\u91cf\u51cf\u5c113.1%\uff081.4%\uff09\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5339\u914d\u4e2d\u5b58\u5728\u6709\u9650\u7684\u6743\u8861\uff1b\u533b\u751f\u4e4b\u95f4\u7684\u6c34\u5e73\u5dee\u5f02\u5316\u548c\u60a3\u8005\u9700\u6c42\u7684\u591a\u6837\u6027\u4f7f\u5f97\u591a\u4e2a\u7ed3\u679c\u80fd\u591f\u540c\u65f6\u6539\u5584\u3002\u63d0\u5347\u6548\u7387\u7684\u518d\u5206\u914d\u4e5f\u5bf9\u516c\u5e73\u6027\u4ea7\u751f\u4e86\u5f71\u54cd\u3002\u7814\u7a76\u7ed3\u679c\u51f8\u663e\u4e86\u5728\u5730\u7406\u9650\u5236\u88ab\u6253\u7834\u7684\u60c5\u51b5\u4e0b\uff0c\u5c06\u670d\u52a1\u63d0\u4f9b\u8005\u7684\u5f02\u8d28\u6027\u4e0e\u60a3\u8005\u9700\u6c42\u76f8\u5339\u914d\uff0c\u8fdb\u884c\u533b\u7597\u8d44\u6e90\u914d\u7f6e\u7684\u6f5c\u529b\u3002\uff08JEL C78, H51, I11, I13, I14, I18\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20241765", "journal": "AER", "title": "The Environmental Bias of Corporate Income Taxation", "authors": ["Luigi Iovino", "Thorsten Martin", "Julien Sauvagnat"], "author_details": [{"name": "Luigi Iovino", "affiliations": ["Bocconi University (email: )"]}, {"name": "Thorsten Martin", "affiliations": ["Frankfurt School of Finance and Management (email: )"]}, {"name": "Julien Sauvagnat", "affiliations": ["Bocconi University (email: )"]}], "abstract": "We study the relationship between corporate income taxation and carbon dioxide (CO 2 ) emissions in the United States. We show CO 2 -intensive firms benefit more from the tax advantage of debt and pay lower income taxes on their capital income. Building on these new facts, we provide evidence that a cut in the corporate income tax rate leads to a larger expansion of clean firms. We develop a multisector general equilibrium model that accounts for our evidence and quantify the impact of corporate tax reforms on aggregate emissions. A policy that eliminates the tax advantage of debt could reduce aggregate emissions without affecting GDP. (JEL D22, G32, H25, H32, Q52, Q54, Q58)", "date": "2026-09-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20241765", "title_zh": "\u4f01\u4e1a\u6240\u5f97\u7a0e\u5bf9\u73af\u5883\u7684\u504f\u5411", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4f01\u4e1a\u6240\u5f97\u7a0e\u4e0e\u4e8c\u6c27\u5316\u78b3\uff08CO2\uff09\u6392\u653e\u4e4b\u95f4\u7684\u5173\u7cfb\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u9ad8\u78b3\u6392\u653e\u4f01\u4e1a\u66f4\u53d7\u76ca\u4e8e\u503a\u52a1\u7684\u7a0e\u6536\u4f18\u60e0\uff0c\u5e76\u4e14\u5728\u8d44\u672c\u6536\u5165\u65b9\u9762\u7f34\u7eb3\u66f4\u4f4e\u7684\u4f01\u4e1a\u6240\u5f97\u7a0e\u3002\u57fa\u4e8e\u8fd9\u4e9b\u65b0\u53d1\u73b0\uff0c\u6211\u4eec\u63d0\u4f9b\u4e86\u8bc1\u636e\u8868\u660e\uff0c\u964d\u4f4e\u4f01\u4e1a\u6240\u5f97\u7a0e\u7a0e\u7387\u5c06\u5bfc\u81f4\u6e05\u6d01\u4f01\u4e1a\u89c4\u6a21\u7684\u66f4\u5927\u6269\u5f20\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u591a\u90e8\u95e8\u4e00\u822c\u5747\u8861\u6a21\u578b\uff0c\u7eb3\u5165\u4e86\u8fd9\u4e9b\u8bc1\u636e\uff0c\u5e76\u91cf\u5316\u4e86\u4f01\u4e1a\u7a0e\u5236\u6539\u9769\u5bf9\u603b\u4f53\u6392\u653e\u7684\u5f71\u54cd\u3002\u4e00\u9879\u6d88\u9664\u503a\u52a1\u7a0e\u6536\u4f18\u60e0\u653f\u7b56\uff0c\u53ef\u4ee5\u5728\u4e0d\u5f71\u54cdGDP\u7684\u60c5\u51b5\u4e0b\u51cf\u5c11\u603b\u4f53\u6392\u653e\u3002\uff08JEL D22, G32, H25, H32, Q52, Q54, Q58\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20241404", "journal": "AER", "title": "Marriage, Fertility, and Cultural Integration in Italy", "authors": ["Alberto Bisin", "Giulia Tura"], "author_details": [{"name": "Alberto Bisin", "affiliations": ["New York University (email: )"]}, {"name": "Giulia Tura", "affiliations": ["LUISS University (email: )"]}], "abstract": "We study cultural integration as an equilibrium outcome of marital matching along cultural and education lines and intrahousehold investment decisions regarding fertility and cultural socialization. Our model allows us to identify cultural-ethnic-group-specific investment parameters and spousal preferences for marital matching. Structural estimates reveal a strong demand to preserve cultural identity on the part of immigrants and limited acceptance of the immigrants' cultural diversity on the part of natives. Furthermore, these estimates reveal a substantial heterogeneity of the parental value of children's education across cultures. Nonetheless, our estimates simulate substantial\u2014though heterogeneous\u2014cultural integration rates across immigrant groups. (JEL D13, J12, J13, J15, Z13)", "date": "2026-09-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20241404", "title_zh": "\u5a5a\u59fb\u3001\u751f\u80b2\u4e0e\u610f\u5927\u5229\u7684\u6587\u5316\u878d\u5408", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u6587\u5316\u878d\u5408\u4f5c\u4e3a\u5a5a\u59fb\u5339\u914d\u4e2d\u6587\u5316\u4e0e\u6559\u80b2\u5dee\u5f02\u4ee5\u53ca\u5bb6\u5ead\u5185\u90e8\u5173\u4e8e\u751f\u80b2\u548c\u6587\u5316\u793e\u4f1a\u5316\u6295\u8d44\u51b3\u7b56\u7684\u5747\u8861\u7ed3\u679c\u3002\u6211\u4eec\u7684\u6a21\u578b\u80fd\u591f\u8bc6\u522b\u51fa\u4e0d\u540c\u6587\u5316-\u65cf\u88d4\u7fa4\u4f53\u7684\u7279\u5b9a\u6295\u8d44\u53c2\u6570\u4ee5\u53ca\u914d\u5076\u5728\u5a5a\u59fb\u5339\u914d\u4e0a\u7684\u504f\u597d\u3002\u7ed3\u6784\u4f30\u8ba1\u663e\u793a\uff0c\u79fb\u6c11\u7fa4\u4f53\u5bf9\u4fdd\u6301\u81ea\u8eab\u6587\u5316\u8eab\u4efd\u6709\u5f3a\u70c8\u9700\u6c42\uff0c\u800c\u672c\u5730\u5c45\u6c11\u5bf9\u79fb\u6c11\u6587\u5316\u591a\u6837\u6027\u63a5\u53d7\u7a0b\u5ea6\u6709\u9650\u3002\u6b64\u5916\uff0c\u8fd9\u4e9b\u4f30\u8ba1\u63ed\u793a\u4e86\u4e0d\u540c\u6587\u5316\u80cc\u666f\u4e0b\u7236\u6bcd\u5bf9\u5b50\u5973\u6559\u80b2\u4ef7\u503c\u7684\u663e\u8457\u5dee\u5f02\u3002\u7136\u800c\uff0c\u6211\u4eec\u7684\u4f30\u8ba1\u6a21\u62df\u51fa\u79fb\u6c11\u7fa4\u4f53\u4e4b\u95f4\u5b58\u5728\u8f83\u5927\u5dee\u5f02\u4f46\u4f9d\u7136\u663e\u8457\u7684\u6587\u5316\u878d\u5408\u7387\u3002\uff08JEL D13, J12, J13, J15, Z13\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag080", "journal": "RFS", "title": "Flow", "authors": ["Caitlin Dannhauser", "Jeffrey Pontiff"], "author_details": [{"name": "Caitlin Dannhauser", "affiliations": ["Villanova University ,"]}, {"name": "Jeffrey Pontiff", "affiliations": ["Boston College ,"]}], "abstract": "Abstract Performance chasing is pervasive in active mutual funds, index mutual funds, and ETFs, with positive flow-performance sensitivity evident in both broad-based and niche funds and for the skill and nonskill components of returns. The sensitivity of ETFs is greatest, with insignificant differences between active and index mutual funds. The heightened sensitivity of ETFs is not explained by benchmark design or exchange trading, and is amplified by institutional ownership. Institutional trading of ETFs follows a momentum strategy, rather than flow management or benchmarking. Institutional herding and the outsourcing of investment management to model portfolios heightens the performance sensitivity of ETF flows.", "date": "2026-09-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag080", "title_zh": "\u8d44\u91d1\u6d41\u52a8", "abstract_zh": "\u8ffd\u9010\u4e1a\u7ee9\u7684\u884c\u4e3a\u666e\u904d\u5b58\u5728\u4e8e\u4e3b\u52a8\u578b\u5171\u540c\u57fa\u91d1\u3001\u6307\u6570\u578b\u5171\u540c\u57fa\u91d1\u548c ETF \u4e2d\u3002\u65e0\u8bba\u662f\u8986\u76d6\u5e7f\u6cdb\u5e02\u573a\u7684\u57fa\u91d1\u8fd8\u662f\u4e13\u95e8\u9886\u57df\u57fa\u91d1\uff0c\u4e5f\u65e0\u8bba\u6536\u76ca\u6765\u81ea\u6295\u8d44\u6280\u80fd\u8fd8\u662f\u975e\u6280\u80fd\u56e0\u7d20\uff0c\u90fd\u53ef\u4ee5\u89c2\u5bdf\u5230\u8d44\u91d1\u6d41\u91cf\u5bf9\u4e1a\u7ee9\u7684\u6b63\u5411\u654f\u611f\u6027\u3002ETF \u7684\u654f\u611f\u6027\u6700\u9ad8\uff0c\u800c\u4e3b\u52a8\u578b\u5171\u540c\u57fa\u91d1\u4e0e\u6307\u6570\u578b\u5171\u540c\u57fa\u91d1\u4e4b\u95f4\u7684\u5dee\u5f02\u4e0d\u663e\u8457\u3002ETF \u66f4\u9ad8\u7684\u654f\u611f\u6027\u4e0d\u80fd\u7531\u57fa\u51c6\u8bbe\u8ba1\u6216\u4ea4\u6613\u6240\u4ea4\u6613\u673a\u5236\u89e3\u91ca\uff0c\u800c\u4e14\u4f1a\u56e0\u673a\u6784\u6301\u6709\u800c\u589e\u5f3a\u3002\u673a\u6784\u5bf9 ETF \u7684\u4ea4\u6613\u9075\u5faa\u52a8\u91cf\u7b56\u7565\uff0c\u800c\u975e\u51fa\u4e8e\u8d44\u91d1\u6d41\u7ba1\u7406\u6216\u57fa\u51c6\u8ddf\u8e2a\u3002\u673a\u6784\u7f8a\u7fa4\u884c\u4e3a\u4ee5\u53ca\u5c06\u6295\u8d44\u7ba1\u7406\u5916\u5305\u7ed9\u6a21\u578b\u6295\u8d44\u7ec4\u5408\uff0c\u4f1a\u63d0\u9ad8 ETF \u8d44\u91d1\u6d41\u91cf\u5bf9\u4e1a\u7ee9\u7684\u654f\u611f\u6027\u3002", "translation_source": "\u9996\u7248\u6837\u4f8b\uff1a\u7531 Codex \u6839\u636e\u516c\u5f00\u6458\u8981\u7ffb\u8bd1\uff0c\u975e Qwen \u8f93\u51fa", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1287/mnsc.2022.01740", "journal": "MS", "title": "Group-Sparse Matrix Factorization for Transfer Learning of Word Embeddings", "authors": ["Kan Xu", "Xuanyi Zhao", "Hamsa Bastani", "Osbert Bastani"], "author_details": [{"name": "Kan Xu", "affiliations": ["W. P. Carey School of Business, Arizona State University, Tempe, Arizona 85281"]}, {"name": "Xuanyi Zhao", "affiliations": ["University of Pennsylvania, Philadelphia, Pennsylvania 19104"]}, {"name": "Hamsa Bastani", "affiliations": ["Wharton School, University of Pennsylvania, Philadelphia, Pennsylvania 19104"]}, {"name": "Osbert Bastani", "affiliations": ["University of Pennsylvania, Philadelphia, Pennsylvania 19104"]}], "abstract": "Unstructured text provides decision makers with a rich data source in many domains, ranging from product reviews in retail to nursing notes in healthcare. To leverage this information, words are typically translated into word embeddings\u2014vectors that encode the semantic relationships between words\u2014through unsupervised learning algorithms such as matrix factorization. However, learning word embeddings from new domains with limited training data can be challenging because the meaning/usage may be different in the new domain; for example, the word \u201cpositive\u201d typically has positive sentiment, but often has negative sentiment in medical notes because it may imply that a patient tested positive for a disease. In practice, we expect that only a small number of domain-specific words may have new meanings. We propose an intuitive two-stage estimator that exploits this structure via a group-sparse penalty to efficiently transfer learn domain-specific word embeddings by combining large-scale text corpora (such as Wikipedia) with limited domain-specific text data. We bound the generalization error of our transfer learning estimator, proving that it can achieve high accuracy with substantially less domain-specific data when only a small number of embeddings are altered between domains. Furthermore, we prove that all local minima identified by our nonconvex objective function are statistically indistinguishable from the global minimum under standard regularization conditions, implying that our estimator can be computed efficiently. Our results provide the first bounds on group-sparse matrix factorization, which may be of independent interest. We empirically evaluate our approach compared with state-of-the-art fine-tuning heuristics from natural language processing.", "date": "2026-09-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2022.01740", "title_zh": "\u7528\u4e8e\u8bcd\u5d4c\u5165\u8fc1\u79fb\u5b66\u4e60\u7684\u5206\u7ec4\u7a00\u758f\u77e9\u9635\u5206\u89e3", "abstract_zh": "\u65e0\u7ed3\u6784\u7684\u6587\u672c\u5728\u8bb8\u591a\u9886\u57df\u4e3a\u51b3\u7b56\u8005\u63d0\u4f9b\u4e86\u4e30\u5bcc\u7684\u6570\u636e\u6765\u6e90\uff0c\u4f8b\u5982\u96f6\u552e\u4e1a\u7684\u4ea7\u54c1\u8bc4\u8bba\u548c\u533b\u7597\u9886\u57df\u7684\u62a4\u7406\u8bb0\u5f55\u3002\u4e3a\u4e86\u5229\u7528\u8fd9\u4e9b\u4fe1\u606f\uff0c\u901a\u5e38\u4f1a\u901a\u8fc7\u65e0\u76d1\u7763\u5b66\u4e60\u7b97\u6cd5\uff08\u5982\u77e9\u9635\u5206\u89e3\uff09\u5c06\u8bcd\u8bed\u8f6c\u6362\u4e3a\u8bcd\u5d4c\u5165\u2014\u2014\u5373\u7f16\u7801\u8bcd\u8bed\u4e4b\u95f4\u8bed\u4e49\u5173\u7cfb\u7684\u5411\u91cf\u3002\u7136\u800c\uff0c\u4ece\u65b0\u9886\u57df\u4e2d\u4f7f\u7528\u6709\u9650\u8bad\u7ec3\u6570\u636e\u5b66\u4e60\u8bcd\u5d4c\u5165\u53ef\u80fd\u9762\u4e34\u6311\u6218\uff0c\u56e0\u4e3a\u65b0\u9886\u57df\u7684\u8bcd\u8bed\u542b\u4e49\u6216\u7528\u6cd5\u53ef\u80fd\u4e0d\u540c\uff1b\u4f8b\u5982\uff0c\u5355\u8bcd\u201cpositive\u201d\u901a\u5e38\u5177\u6709\u6b63\u9762\u60c5\u611f\uff0c\u4f46\u5728\u533b\u7597\u8bb0\u5f55\u4e2d\u5f80\u5f80\u5177\u6709\u8d1f\u9762\u60c5\u611f\uff0c\u56e0\u4e3a\u5b83\u53ef\u80fd\u610f\u5473\u7740\u60a3\u8005\u68c0\u6d4b\u51fa\u67d0\u79cd\u75be\u75c5\u3002\u5728\u5b9e\u8df5\u4e2d\uff0c\u6211\u4eec\u9884\u8ba1\u53ea\u6709\u5c11\u6570\u9886\u57df\u7279\u5b9a\u7684\u8bcd\u8bed\u4f1a\u6709\u65b0\u7684\u542b\u4e49\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u76f4\u89c2\u7684\u4e24\u9636\u6bb5\u4f30\u8ba1\u5668\uff0c\u901a\u8fc7\u5206\u7ec4\u7a00\u758f\u60e9\u7f5a\u5229\u7528\u8fd9\u4e00\u7ed3\u6784\uff0c\u9ad8\u6548\u5730\u901a\u8fc7\u5927\u89c4\u6a21\u6587\u672c\u8bed\u6599\u5e93\uff08\u5982\u7ef4\u57fa\u767e\u79d1\uff09\u4e0e\u5c11\u91cf\u9886\u57df\u7279\u5b9a\u6587\u672c\u6570\u636e\u76f8\u7ed3\u5408\u6765\u8fc1\u79fb\u5b66\u4e60\u9886\u57df\u7279\u5b9a\u7684\u8bcd\u5d4c\u5165\u3002\u6211\u4eec\u754c\u5b9a\u4e86\u8fc1\u79fb\u5b66\u4e60\u4f30\u8ba1\u5668\u7684\u6cdb\u5316\u8bef\u5dee\uff0c\u8bc1\u660e\u5f53\u4ec5\u5c11\u6570\u5d4c\u5165\u5411\u91cf\u5728\u4e0d\u540c\u9886\u57df\u95f4\u53d1\u751f\u53d8\u5316\u65f6\uff0c\u8be5\u65b9\u6cd5\u53ef\u4ee5\u5728\u663e\u8457\u51cf\u5c11\u9886\u57df\u7279\u5b9a\u6570\u636e\u7684\u60c5\u51b5\u4e0b\u5b9e\u73b0\u9ad8\u7cbe\u5ea6\u3002\u6b64\u5916\uff0c\u6211\u4eec\u8bc1\u660e\u5728\u6807\u51c6\u6b63\u5219\u5316\u6761\u4ef6\u4e0b\uff0c\u6211\u4eec\u7684\u975e\u51f8\u76ee\u6807\u51fd\u6570\u6240\u8bc6\u522b\u7684\u6240\u6709\u5c40\u90e8\u6781\u5c0f\u503c\u5728\u7edf\u8ba1\u4e0a\u5747\u65e0\u6cd5\u4e0e\u5168\u5c40\u6700\u5c0f\u503c\u533a\u5206\uff0c\u8fd9\u610f\u5473\u7740\u6211\u4eec\u7684\u4f30\u8ba1\u5668\u53ef\u4ee5\u9ad8\u6548\u8ba1\u7b97\u3002\u6211\u4eec\u7684\u7ed3\u679c\u4e3a\u5206\u7ec4\u7a00\u758f\u77e9\u9635\u5206\u89e3\u63d0\u4f9b\u4e86\u9996\u4e2a\u7406\u8bba\u754c\u9650\uff0c\u53ef\u80fd\u5177\u6709\u72ec\u7acb\u7684\u7814\u7a76\u4ef7\u503c\u3002\u6211\u4eec\u901a\u8fc7\u4e0e\u81ea\u7136\u8bed\u8a00\u5904\u7406\u9886\u57df\u6700\u5148\u8fdb\u7684\u5fae\u8c03\u542f\u53d1\u5f0f\u65b9\u6cd5\u8fdb\u884c\u5b9e\u8bc1\u8bc4\u4f30\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790"]}, {"doi": "10.1287/mnsc.2024.07050", "journal": "MS", "title": "The Impact of Gender Information on Hiring Decisions Based on Self-Set Performance Targets", "authors": ["Katharina Werner", "Susanna Grundmann", "Bettina Rockenbach"], "author_details": [{"name": "Katharina Werner", "affiliations": ["Department of Economics, Faculty of Management, Economics and Social Sciences, University of Cologne, D-50923 Cologne, Germany; and Department of Economics and Finance, OMNES Education, International University of Monaco, OMNES Education, 98000 Principality of Monaco, Monaco"]}, {"name": "Susanna Grundmann", "affiliations": ["Department of Economics, Faculty of Management, Economics and Social Sciences, University of Cologne, D-50923 Cologne, Germany"]}, {"name": "Bettina Rockenbach", "affiliations": ["Department of Economics, Faculty of Management, Economics and Social Sciences, University of Cologne, D-50923 Cologne, Germany"]}], "abstract": "Gender-anonymous hiring practices have been widely advocated as a means to reduce labor market inequalities, such as the gender wage gap and the underrepresentation of women in leadership. However, their effectiveness remains debated. This paper studies an experimental labor market where employee candidates set their own performance targets for a real-effort task and employers hire based on these self-set targets. In many professional settings, such targets serve as performance indicators and influence hiring and promotion decisions. In an online experiment with 4,674 participants, we vary in a 2 \u00d7 2 design (1) whether employers know the candidates\u2019 genders and (2) the severity of the payoff consequences if the hired employee misses their target. This allows us to examine the interaction effects of gender anonymity in hiring and the performance target\u2019s payoff relevance. We find that given equal ability, women set lower targets than men. Higher targets increase the likelihood of being hired, whereas a larger expected target-performance gap reduces hiring chances, particularly when missing the target has severe consequences for the employer. Importantly, our findings suggest that gender-anonymous applications may have unintended consequences. When gender is revealed, employers appear to adjust for gender differences in target setting, expecting a smaller target-performance gap for women than for men. As a result, women are more likely to be hired and receive higher payoffs when their gender is known. These results indicate that gender-anonymous hiring may backfire for women by preventing employers from accounting for behavioral gender differences (e.g., in self-promotion), ultimately reducing women\u2019s hiring prospects.", "date": "2026-09-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07050", "title_zh": "\u57fa\u4e8e\u81ea\u6211\u8bbe\u5b9a\u7ee9\u6548\u76ee\u6807\u7684\u6027\u522b\u4fe1\u606f\u5bf9\u62db\u8058\u51b3\u7b56\u7684\u5f71\u54cd", "abstract_zh": "\u6027\u522b\u533f\u540d\u5316\u62db\u8058\u5b9e\u8df5\u88ab\u5e7f\u6cdb\u5021\u5bfc\uff0c\u4ee5\u51cf\u5c11\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u7684\u4e0d\u5e73\u7b49\u73b0\u8c61\uff0c\u5982\u6027\u522b\u85aa\u916c\u5dee\u8ddd\u4ee5\u53ca\u5973\u6027\u5728\u9886\u5bfc\u5c97\u4f4d\u4e2d\u7684\u4ee3\u8868\u6027\u4e0d\u8db3\u3002\u7136\u800c\uff0c\u5176\u6709\u6548\u6027\u4ecd\u5b58\u5728\u4e89\u8bae\u3002\u672c\u6587\u7814\u7a76\u4e86\u4e00\u4e2a\u5b9e\u9a8c\u6027\u52b3\u52a8\u529b\u5e02\u573a\uff0c\u5728\u8be5\u5e02\u573a\u4e2d\uff0c\u6c42\u804c\u8005\u4f1a\u4e3a\u81ea\u5df1\u8bbe\u5b9a\u4e00\u4e2a\u771f\u5b9e\u52aa\u529b\u4efb\u52a1\u7684\u7ee9\u6548\u76ee\u6807\uff0c\u800c\u96c7\u4e3b\u5219\u6839\u636e\u8fd9\u4e9b\u81ea\u6211\u8bbe\u5b9a\u7684\u76ee\u6807\u8fdb\u884c\u62db\u8058\u3002\u5728\u8bb8\u591a\u4e13\u4e1a\u73af\u5883\u4e2d\uff0c\u8fd9\u7c7b\u76ee\u6807\u4f5c\u4e3a\u7ee9\u6548\u6307\u6807\uff0c\u5f71\u54cd\u7740\u62db\u8058\u548c\u664b\u5347\u51b3\u7b56\u3002\u5728\u4e00\u9879\u6d89\u53ca4674\u540d\u53c2\u4e0e\u8005\u7684\u5728\u7ebf\u5b9e\u9a8c\u4e2d\uff0c\u6211\u4eec\u91c7\u75282\u00d72\u8bbe\u8ba1\uff081\uff09\u96c7\u4e3b\u662f\u5426\u77e5\u6653\u5019\u9009\u4eba\u7684\u6027\u522b\uff0c\u4ee5\u53ca\uff082\uff09\u82e5\u88ab\u96c7\u4f63\u5458\u5de5\u672a\u80fd\u8fbe\u6210\u76ee\u6807\uff0c\u5176\u540e\u679c\u7684\u4e25\u91cd\u7a0b\u5ea6\u3002\u8fd9\u4f7f\u6211\u4eec\u80fd\u591f\u8003\u5bdf\u6027\u522b\u533f\u540d\u62db\u8058\u4e0e\u7ee9\u6548\u76ee\u6807\u540e\u679c\u76f8\u5173\u6027\u4e4b\u95f4\u7684\u4ea4\u4e92\u6548\u5e94\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u80fd\u529b\u76f8\u7b49\u7684\u60c5\u51b5\u4e0b\uff0c\u5973\u6027\u8bbe\u5b9a\u7684\u76ee\u6807\u4f4e\u4e8e\u7537\u6027\u3002\u66f4\u9ad8\u7684\u76ee\u6807\u4f1a\u589e\u52a0\u88ab\u5f55\u7528\u7684\u53ef\u80fd\u6027\uff0c\u800c\u66f4\u5927\u7684\u9884\u671f\u76ee\u6807-\u7ee9\u6548\u5dee\u8ddd\u5219\u4f1a\u964d\u4f4e\u88ab\u5f55\u7528\u7684\u6982\u7387\uff0c\u5c24\u5176\u662f\u5728\u672a\u80fd\u8fbe\u6210\u76ee\u6807\u5bf9\u96c7\u4e3b\u540e\u679c\u4e25\u91cd\u7684\u6761\u4ef6\u4e0b\u3002\u91cd\u8981\u7684\u662f\uff0c\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u6027\u522b\u533f\u540d\u7533\u8bf7\u53ef\u80fd\u4ea7\u751f\u610f\u5916\u540e\u679c\u3002\u5f53\u6027\u522b\u88ab\u63ed\u793a\u65f6\uff0c\u96c7\u4e3b\u4f3c\u4e4e\u4f1a\u6839\u636e\u6027\u522b\u5dee\u5f02\u5728\u76ee\u6807\u8bbe\u5b9a\u4e0a\u8fdb\u884c\u8c03\u6574\uff0c\u9884\u671f\u5973\u6027\u7684\u76ee\u6807-\u7ee9\u6548\u5dee\u8ddd\u4f1a\u5c0f\u4e8e\u7537\u6027\u3002\u56e0\u6b64\uff0c\u5f53\u6027\u522b\u88ab\u516c\u5f00\u65f6\uff0c\u5973\u6027\u88ab\u5f55\u7528\u7684\u6982\u7387\u66f4\u9ad8\uff0c\u5e76\u83b7\u5f97\u66f4\u9ad8\u7684\u6536\u76ca\u3002\u8fd9\u4e9b\u7ed3\u679c\u8868\u660e\uff0c\u6027\u522b\u533f\u540d\u62db\u8058\u53ef\u80fd\u5bf9\u5973\u6027\u4ea7\u751f\u53cd\u6548\u679c\uff0c\u56e0\u4e3a\u5b83\u963b\u6b62\u4e86\u96c7\u4e3b\u8003\u8651\u884c\u4e3a\u4e0a\u7684\u6027\u522b\u5dee\u5f02\uff08\u4f8b\u5982\u81ea\u6211\u63a8\u9500\uff09\uff0c\u6700\u7ec8\u524a\u5f31\u4e86\u5973\u6027\u7684\u62db\u8058\u673a\u4f1a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.08424", "journal": "MS", "title": "A Theory of Front-Line Management", "authors": ["Daniel Bird", "Alexander Frug"], "author_details": [{"name": "Daniel Bird", "affiliations": ["Eitan Berglas School of Economics, Tel Aviv University, Tel Aviv 6997801, Israel"]}, {"name": "Alexander Frug", "affiliations": ["Department of Economics and Business, Universitat Pompeu Fabra and Barcelona School of Economics, 08002 Barcelona, Spain"]}], "abstract": "Mid- and low-level managers play a significant role within the organizational hierarchy, far beyond monitoring. It is often their responsibility to respond to opportunities and threats within their units by adjusting their subordinates\u2019 assignments. Most such managers, however, lack the authority to adapt their subordinates\u2019 wages. Instead, they rely on other, more restrictive incentive schemes. We study the interaction between a front-line manager and worker and characterize the \u201cmanagerial style\u201d as a function of the players\u2019 relative patience and information.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08424", "title_zh": "\u4e00\u7ebf\u7ba1\u7406\u7684\u7406\u8bba", "abstract_zh": "\u4e2d\u5c42\u548c\u57fa\u5c42\u7ba1\u7406\u8005\u5728\u7ec4\u7ec7\u7ed3\u6784\u4e2d\u626e\u6f14\u7740\u81f3\u5173\u91cd\u8981\u7684\u89d2\u8272\uff0c\u5176\u4f5c\u7528\u8fdc\u8d85\u7b80\u5355\u7684\u76d1\u7763\u3002\u4ed6\u4eec\u901a\u5e38\u9700\u8981\u6839\u636e\u5176\u90e8\u95e8\u5185\u90e8\u7684\u673a\u4f1a\u548c\u5a01\u80c1\uff0c\u8c03\u6574\u4e0b\u5c5e\u7684\u5de5\u4f5c\u5b89\u6392\u3002\u7136\u800c\uff0c\u5927\u591a\u6570\u6b64\u7c7b\u7ba1\u7406\u8005\u5e76\u6ca1\u6709\u8c03\u6574\u4e0b\u5c5e\u5de5\u8d44\u7684\u6743\u529b\uff0c\u800c\u662f\u4f9d\u8d56\u4e8e\u5176\u4ed6\u66f4\u4e3a\u4e25\u683c\u7684\u6fc0\u52b1\u673a\u5236\u3002\u672c\u6587\u7814\u7a76\u4e86\u4e00\u7ebf\u7ba1\u7406\u8005\u4e0e\u5458\u5de5\u4e4b\u95f4\u7684\u4e92\u52a8\uff0c\u5e76\u5c06\u2018\u7ba1\u7406\u98ce\u683c\u2019\u4f5c\u4e3a\u7ba1\u7406\u8005\u4e0e\u5458\u5de5\u76f8\u5bf9\u8010\u5fc3\u7a0b\u5ea6\u548c\u4fe1\u606f\u638c\u63e1\u60c5\u51b5\u7684\u51fd\u6570\u8fdb\u884c\u523b\u753b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.07614", "journal": "MS", "title": "Learning to Optimally Stop Diffusion Processes, with Financial Applications", "authors": ["Min Dai", "Yu Sun", "Zuo Quan Xu", "Xun Yu Zhou"], "author_details": [{"name": "Min Dai", "affiliations": ["Department of Applied Mathematics at the Faculty of Computer and Mathematical Sciences and School of Accounting and Finance at the Faculty of Business, The Hong Kong Polytechnic University, Hong Kong, China"]}, {"name": "Yu Sun", "affiliations": ["Peking University HSBC Business School, Shenzhen 518055, China"]}, {"name": "Zuo Quan Xu", "affiliations": ["Department of Applied Mathematics, Faculty of Computer and Mathematical Sciences, The Hong Kong Polytechnic University, Hong Kong, China"]}, {"name": "Xun Yu Zhou", "affiliations": ["Department of Industrial Engineering and Operations Research and The Data Science Institute, Columbia University, New York, New York 10027"]}], "abstract": "We study optimal stopping for diffusion processes with unknown model primitives within the continuous-time reinforcement learning (RL) framework Wang, Zariphopoulou and Zhou [Wang H, Zariphopoulou T, Zhou XY (2020), J. Machine Learn. Res. 21(198):1-34], and present applications to option pricing and portfolio choice. By penalizing the corresponding variational inequality formulation, we transform the stopping problem into a stochastic optimal control problem with two actions. We then randomize controls into Bernoulli distributions and add an entropy regularizer to encourage exploration. We derive a semianalytical optimal Bernoulli distribution, based on which we devise RL algorithms using the martingale approach Jia and Zhou [Jia Y, Zhou XY (2022a) J. Machine Learn. Res. 23(154):1\u201355]. We establish a policy improvement theorem and prove the fast convergence of the resulting policy iterations. We demonstrate the effectiveness of the algorithms in pricing finite-horizon American put options, solving Merton\u2019s problem with transaction costs, and scaling to high-dimensional optimal stopping problems. In particular, we show that both the offline and online algorithms achieve high accuracy in learning the value functions and characterizing the associated free boundaries.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07614", "title_zh": "\u5b66\u4e60\u6700\u4f18\u505c\u6b62\u6269\u6563\u8fc7\u7a0b\u53ca\u5176\u91d1\u878d\u5e94\u7528", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u5728\u8fde\u7eed\u65f6\u95f4\u5f3a\u5316\u5b66\u4e60\uff08RL\uff09\u6846\u67b6\u4e0b\uff0c\u5177\u6709\u672a\u77e5\u6a21\u578b\u57fa\u672c\u8981\u7d20\u7684\u6269\u6563\u8fc7\u7a0b\u7684\u6700\u4f18\u505c\u6b62\u95ee\u9898\uff08Wang, Zariphopoulou \u548c Zhou [Wang H, Zariphopoulou T, Zhou XY (2020), J. Machine Learn. Res. 21(198):1-34]\uff09\uff0c\u5e76\u5c06\u5176\u5e94\u7528\u4e8e\u671f\u6743\u5b9a\u4ef7\u548c\u6295\u8d44\u7ec4\u5408\u9009\u62e9\u3002\u901a\u8fc7\u60e9\u7f5a\u76f8\u5e94\u7684\u53d8\u5206\u4e0d\u7b49\u5f0f\u516c\u5f0f\uff0c\u6211\u4eec\u5c06\u505c\u6b62\u95ee\u9898\u8f6c\u5316\u4e3a\u5177\u6709\u4e24\u4e2a\u52a8\u4f5c\u7684\u968f\u673a\u6700\u4f18\u63a7\u5236\u95ee\u9898\u3002\u7136\u540e\uff0c\u6211\u4eec\u5c06\u63a7\u5236\u968f\u673a\u5316\u4e3a\u4f2f\u52aa\u5229\u5206\u5e03\uff0c\u5e76\u6dfb\u52a0\u71b5\u6b63\u5219\u5316\u4ee5\u9f13\u52b1\u63a2\u7d22\u3002\u6211\u4eec\u63a8\u5bfc\u51fa\u4e00\u4e2a\u534a\u89e3\u6790\u7684\u6700\u4f18\u4f2f\u52aa\u5229\u5206\u5e03\uff0c\u57fa\u4e8e\u6b64\u8bbe\u8ba1\u4e86\u4f7f\u7528\u9785\u65b9\u6cd5\uff08Jia \u548c Zhou [Jia Y, Zhou XY (2022a) J. Machine Learn. Res. 23(154):1\u201355]\uff09\u7684\u5f3a\u5316\u5b66\u4e60\u7b97\u6cd5\u3002\u6211\u4eec\u5efa\u7acb\u4e86\u7b56\u7565\u6539\u8fdb\u5b9a\u7406\uff0c\u5e76\u8bc1\u660e\u4e86\u7531\u6b64\u4ea7\u751f\u7684\u7b56\u7565\u8fed\u4ee3\u5177\u6709\u5feb\u901f\u6536\u655b\u6027\u3002\u6211\u4eec\u5728\u5b9a\u4ef7\u6709\u9650\u671f\u9650\u7f8e\u5f0f\u770b\u8dcc\u671f\u6743\u3001\u89e3\u51b3\u5305\u542b\u4ea4\u6613\u6210\u672c\u7684Merton\u95ee\u9898\u4ee5\u53ca\u5904\u7406\u9ad8\u7ef4\u6700\u4f18\u505c\u6b62\u95ee\u9898\u65f6\uff0c\u5c55\u793a\u4e86\u7b97\u6cd5\u7684\u6709\u6548\u6027\u3002\u7279\u522b\u5730\uff0c\u6211\u4eec\u8868\u660e\uff0c\u79bb\u7ebf\u548c\u5728\u7ebf\u7b97\u6cd5\u5728\u5b66\u4e60\u4ef7\u503c\u51fd\u6570\u548c\u523b\u753b\u76f8\u5173\u81ea\u7531\u8fb9\u754c\u65b9\u9762\u5747\u80fd\u5b9e\u73b0\u9ad8\u7cbe\u5ea6\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1287/mnsc.2024.04342", "journal": "MS", "title": "Gender-Inclusive Language and Economic Decision-Making", "authors": ["Loukas Balafoutas", "Helena Fornwagner", "Emily Hauser", "Oliver Hauser"], "author_details": [{"name": "Loukas Balafoutas", "affiliations": ["Department of Economics, University of Exeter, Exeter EX4 4QJ, United Kingdom; and Department of Public Finance, University of Innsbruck, 6020 Innsbruck, Austria"]}, {"name": "Helena Fornwagner", "affiliations": ["Department of Economics, University of Exeter, Exeter EX4 4QJ, United Kingdom; and Austrian Institute of Economic Research (WIFO), 1030 Vienna, Austria"]}, {"name": "Emily Hauser", "affiliations": ["Department of Classics, Ancient History, Religion and Theology, University of Exeter, Exeter EX4 4QJ, United Kingdom"]}, {"name": "Oliver Hauser", "affiliations": ["Department of Economics, University of Exeter, Exeter EX4 4QJ, United Kingdom"]}], "abstract": "Providing inclusive environments has become a primary tenet of modern societies and organizations. The use of gender-inclusive language (GIL) is often considered an instrument that can promote inclusion, yet little is known about its effects on relevant economic behaviors and on gender gaps in the labor market. GIL avoids the masculine \u201cdefault\u201d (common to many languages) by either explicitly mentioning both masculine and feminine (pro)nouns, or replacing them with nongendered (pro)nouns. Here we study the causal short-run impact of GIL on competitiveness and leadership in the laboratory, with two different language samples\u2014English and German\u2014which differ, among other things, in the extent to which gender is embedded linguistically. We vary GIL in experimental instructions across three treatments ([Formula: see text]): a masculine baseline condition, a condition with feminine and masculine (pro)nouns, and a condition with nongendered (pro)nouns. We find that participants who identify as female and participants who identify as male compete, stand for leadership, and vote on leader candidates similarly across all treatments, in either language. Furthermore, we find no treatment differences in participants\u2019 feelings of inclusion and perceived entitlement. In sum, there is a lack of support for GIL having short-term causal effects on competitive and leadership behavior and inclusion perceptions.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.04342", "title_zh": "\u5305\u5bb9\u6027\u8bed\u8a00\u4e0e\u7ecf\u6d4e\u51b3\u7b56", "abstract_zh": "\u521b\u5efa\u5305\u5bb9\u6027\u73af\u5883\u5df2\u6210\u4e3a\u73b0\u4ee3\u793e\u4f1a\u548c\u7ec4\u7ec7\u7684\u6838\u5fc3\u539f\u5219\u4e4b\u4e00\u3002\u4f7f\u7528\u5305\u5bb9\u6027\u8bed\u8a00\uff08GIL\uff09\u901a\u5e38\u88ab\u8ba4\u4e3a\u662f\u4e00\u79cd\u4fc3\u8fdb\u5305\u5bb9\u6027\u7684\u5de5\u5177\uff0c\u4f46\u5173\u4e8e\u5176\u5bf9\u76f8\u5173\u7ecf\u6d4e\u884c\u4e3a\u4ee5\u53ca\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u6027\u522b\u5dee\u8ddd\u7684\u5f71\u54cd\u4ecd\u77e5\u4e4b\u751a\u5c11\u3002GIL\u901a\u8fc7\u660e\u786e\u63d0\u53ca\u7537\u5973\uff08\u4ee3\u8bcd\uff09\u6216\u4f7f\u7528\u65e0\u6027\u522b\u4ee3\u8bcd\uff0c\u907f\u514d\u4e86\u8bed\u8a00\u4e2d\u5e38\u89c1\u7684\u201c\u7537\u6027\u9ed8\u8ba4\u201d\u73b0\u8c61\u3002\u672c\u6587\u5728\u5b9e\u9a8c\u5ba4\u73af\u5883\u4e2d\u7814\u7a76\u4e86GIL\u5bf9\u7ade\u4e89\u529b\u548c\u9886\u5bfc\u529b\u7684\u77ed\u671f\u56e0\u679c\u5f71\u54cd\uff0c\u91c7\u7528\u4e86\u4e24\u79cd\u8bed\u8a00\u6837\u672c\u2014\u2014\u82f1\u8bed\u548c\u5fb7\u8bed\uff0c\u8fd9\u4e24\u79cd\u8bed\u8a00\u5728\u6027\u522b\u8bed\u8a00\u5d4c\u5165\u7a0b\u5ea6\u4e0a\u5b58\u5728\u5dee\u5f02\u3002\u6211\u4eec\u5728\u5b9e\u9a8c\u8bf4\u660e\u4e2d\u8bbe\u7f6e\u4e86\u4e09\u79cd\u5904\u7406\u6761\u4ef6\uff08[\u516c\u5f0f\u89c1\u539f\u6587]\uff09\uff1a\u7537\u6027\u9ed8\u8ba4\u6761\u4ef6\u3001\u5305\u542b\u7537\u5973\u4ee3\u8bcd\u7684\u6761\u4ef6\uff0c\u4ee5\u53ca\u4f7f\u7528\u65e0\u6027\u522b\u4ee3\u8bcd\u7684\u6761\u4ef6\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u65e0\u8bba\u5728\u4f55\u79cd\u8bed\u8a00\u4e0b\uff0c\u8ba4\u540c\u4e3a\u5973\u6027\u548c\u8ba4\u540c\u4e3a\u7537\u6027\u7684\u53c2\u4e0e\u8005\u5728\u7ade\u4e89\u3001\u53c2\u9009\u9886\u5bfc\u804c\u4f4d\u4ee5\u53ca\u5bf9\u9886\u5bfc\u5019\u9009\u4eba\u8fdb\u884c\u6295\u7968\u65b9\u9762\u5747\u65e0\u663e\u8457\u5dee\u5f02\u3002\u6b64\u5916\uff0c\u53c2\u4e0e\u8005\u5bf9\u81ea\u8eab\u5f52\u5c5e\u611f\u548c\u88ab\u8d4b\u4e88\u6743\u5229\u7684\u611f\u77e5\u4e5f\u672a\u51fa\u73b0\u5904\u7406\u6761\u4ef6\u95f4\u7684\u5dee\u5f02\u3002\u7efc\u4e0a\uff0c\u73b0\u6709\u8bc1\u636e\u4e0d\u652f\u6301\u5305\u5bb9\u6027\u8bed\u8a00\u5728\u77ed\u671f\u5185\u5bf9\u7ade\u4e89\u529b\u3001\u9886\u5bfc\u884c\u4e3a\u53ca\u5f52\u5c5e\u611f\u611f\u77e5\u4ea7\u751f\u56e0\u679c\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.06893", "journal": "MS", "title": "Hedging Permanent Income Shocks", "authors": ["Fabio C. Bagliano", "Raffaele Corvino", "Carolina Fugazza", "Giovanna Nicodano"], "author_details": [{"name": "Fabio C. Bagliano", "affiliations": ["University of Torino (ESOMAS), 10134 Torino, Italy; and CERP (Collegio Carlo Alberto), 10122 Torino, Italy"]}, {"name": "Raffaele Corvino", "affiliations": ["NEOMA Business School, 76130 Mont-Saint-Aignan, France"]}, {"name": "Carolina Fugazza", "affiliations": ["University of Torino (ESOMAS), 10134 Torino, Italy; and CERP (Collegio Carlo Alberto), 10122 Torino, Italy"]}, {"name": "Giovanna Nicodano", "affiliations": ["University of Torino (ESOMAS), 10134 Torino, Italy; and CERP (Collegio Carlo Alberto), 10122 Torino, Italy; and CEPR, London EC1R 5HL, United Kingdom; and NETSPAR, 5037 Tilburg, Netherlands"]}], "abstract": "This paper robustly connects observed portfolio choices to correlations of individual income shocks with an aggregate shock (or, equivalently, with stock market returns). The share of nonparticipating individuals displaying a positive correlation, and therefore a negative hedging demand for stocks, is above 79% in both our samples. Furthermore, correlations predict nonparticipation to the equity market, also out-of-sample and for the same individual over time. These results support the traditional hedging motive explanation for nonparticipation. Such new insight owes to the income shocks comovements across individuals, which we model and exploit to identify correlations.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06893", "title_zh": "\u5bf9\u6c38\u4e45\u6027\u6536\u5165\u51b2\u51fb\u7684\u5bf9\u51b2", "abstract_zh": "\u672c\u6587\u7a33\u5065\u5730\u5c06\u89c2\u5bdf\u5230\u7684\u6295\u8d44\u7ec4\u5408\u9009\u62e9\u4e0e\u4e2a\u4f53\u6536\u5165\u51b2\u51fb\u4e0e\u603b\u4f53\u51b2\u51fb\uff08\u6216\u7b49\u4ef7\u5730\uff0c\u4e0e\u80a1\u7968\u5e02\u573a\u56de\u62a5\uff09\u4e4b\u95f4\u7684\u76f8\u5173\u6027\u8054\u7cfb\u8d77\u6765\u3002\u5728\u6211\u4eec\u7684\u4e24\u4e2a\u6837\u672c\u4e2d\uff0c\u8868\u73b0\u51fa\u6b63\u76f8\u5173\u4e14\u56e0\u6b64\u5bf9\u80a1\u7968\u5177\u6709\u8d1f\u5bf9\u51b2\u9700\u6c42\u7684\u975e\u53c2\u4e0e\u4e2a\u4f53\u6bd4\u4f8b\u8d85\u8fc779%\u3002\u6b64\u5916\uff0c\u76f8\u5173\u6027\u80fd\u591f\u9884\u6d4b\u4e2a\u4f53\u5bf9\u80a1\u7968\u5e02\u573a\u7684\u975e\u53c2\u4e0e\u884c\u4e3a\uff0c\u4e14\u5728\u6837\u672c\u5916\u4ee5\u53ca\u5bf9\u540c\u4e00\u4e2a\u4f53\u968f\u65f6\u95f4\u7684\u53d8\u5316\u4e2d\u5747\u6210\u7acb\u3002\u8fd9\u4e9b\u7ed3\u679c\u652f\u6301\u4e86\u4f20\u7edf\u5bf9\u51b2\u52a8\u673a\u89e3\u91ca\u975e\u53c2\u4e0e\u73b0\u8c61\u3002\u8fd9\u4e00\u65b0\u89c1\u89e3\u5f97\u76ca\u4e8e\u4e2a\u4f53\u4e4b\u95f4\u6536\u5165\u51b2\u51fb\u7684\u5171\u52a8\u6027\uff0c\u6211\u4eec\u901a\u8fc7\u5efa\u6a21\u5e76\u5229\u7528\u8fd9\u4e9b\u5171\u52a8\u6027\u6765\u8bc6\u522b\u76f8\u5173\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1287/mnsc.2026.00184", "journal": "MS", "title": "Fighting Fire with Fire: Infusing Artificial Intelligence into Peer Review to Sustain Quality Scholarship", "authors": ["Hemant K. Bhargava", "Sarah H. Bana", "Zhe Zhang", "Laura Brandimarte", "Vidyanand Choudhary", "J. Frank Li", "Pantelis Loupos", "Daniel Zantedeschi"], "author_details": [{"name": "Hemant K. Bhargava", "affiliations": ["Graduate School of Management, University of California, Davis, California 95616; and Center for Analytics and Technology in Society, University of California, Davis, California 95616"]}, {"name": "Sarah H. Bana", "affiliations": ["Argyros College of Business and Economics, Chapman University, Orange, California 92866; and Stanford Digital Economy Lab, Stanford University, Stanford, California 94305; and Department of Management, London School of Economics and Political Science, London WC2A 2AE, United Kingdom"]}, {"name": "Zhe Zhang", "affiliations": ["Rady School of Management, University of California, San Diego, La Jolla, California 92093"]}, {"name": "Laura Brandimarte", "affiliations": ["Eller College of Management, University of Arizona, Tucson, Arizona 85721"]}, {"name": "Vidyanand Choudhary", "affiliations": ["Paul Merage School of Business, University of California, Irvine, California 92697"]}, {"name": "J. Frank Li", "affiliations": ["Stanford Digital Economy Lab, Stanford University, Stanford, California 94305; and Sauder School of Business, University of British Columbia, Vancouver, British Columbia V6T 1Z2, Canada"]}, {"name": "Pantelis Loupos", "affiliations": ["Graduate School of Management, University of California, Davis, California 95616"]}, {"name": "Daniel Zantedeschi", "affiliations": ["Muma College of Business, School of Information Systems, University of South Florida, Tampa, Florida 33620"]}], "abstract": "Adoption of artificial intelligence (AI) by authors has accelerated production of academic articles and increased submission rates to journals, thereby straining review capacity and hurting journal outcome metrics, such as turnaround time and decision accuracy. Academic journals face an imperative to improve review quality and productivity by incorporating generative AI tools in the review workflow. As a concrete first step toward this idea, we outline a particular workflow that deploys large language models as a structured, trained, frontline reviewer. The workflow underlines that AI-produced evaluations must be transparent and contestable by authors. We emphasize the need for AI-infused peer review to be journal specific, designed for efficiency, accuracy, and accountability, within a human-in-the-loop oversight framework. We build a mathematical model of journal operations to compare outcomes under a status quo no-AI workflow and the proposed AI-infused workflow. The model captures how governed AI reconfigures human reviewer effort and illuminates conditions under which the AI-infused workflow can improve vital metrics, such as turnaround time and decision accuracy. Our essential point is that journals need to adopt a deliberate and institutionally governed approach for using AI in the review process. We recognize that identifying an \u201coptimal\u201d AI-infused peer review workflow or even definitively projecting the consequences of one will require substantial experimentation to calibrate and configure the workflow across multiple alternative designs.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2026.00184", "title_zh": "\u4ee5\u706b\u653b\u706b\uff1a\u5c06\u4eba\u5de5\u667a\u80fd\u6ce8\u5165\u540c\u884c\u8bc4\u5ba1\u4ee5\u7ef4\u6301\u5b66\u672f\u8d28\u91cf", "abstract_zh": "\u4f5c\u8005\u91c7\u7528\u4eba\u5de5\u667a\u80fd\uff08AI\uff09\u7684\u8fdb\u7a0b\u52a0\u901f\u4e86\u5b66\u672f\u6587\u7ae0\u7684\u751f\u4ea7\uff0c\u5e76\u63d0\u9ad8\u4e86\u5411\u671f\u520a\u6295\u7a3f\u7684\u9891\u7387\uff0c\u4ece\u800c\u52a0\u5267\u4e86\u8bc4\u5ba1\u80fd\u529b\u7684\u538b\u529b\uff0c\u635f\u5bb3\u4e86\u671f\u520a\u7684\u6210\u679c\u6307\u6807\uff0c\u5982\u5904\u7406\u5468\u671f\u548c\u51b3\u7b56\u51c6\u786e\u6027\u3002\u5b66\u672f\u671f\u520a\u9762\u4e34\u8feb\u5207\u9700\u6c42\uff0c\u5373\u901a\u8fc7\u5728\u8bc4\u5ba1\u6d41\u7a0b\u4e2d\u5f15\u5165\u751f\u6210\u5f0f\u4eba\u5de5\u667a\u80fd\u5de5\u5177\u6765\u63d0\u5347\u8bc4\u5ba1\u8d28\u91cf\u548c\u6548\u7387\u3002\u4f5c\u4e3a\u8fd9\u4e00\u6784\u60f3\u7684\u4e00\u4e2a\u5177\u4f53\u521d\u6b65\u6b65\u9aa4\uff0c\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u7279\u5b9a\u7684\u5de5\u4f5c\u6d41\u7a0b\uff0c\u8be5\u6d41\u7a0b\u5c06\u5927\u578b\u8bed\u8a00\u6a21\u578b\u4f5c\u4e3a\u7ed3\u6784\u5316\u3001\u8bad\u7ec3\u8fc7\u7684\u524d\u7f6e\u8bc4\u5ba1\u5458\u3002\u8be5\u6d41\u7a0b\u5f3a\u8c03\uff0cAI\u751f\u6210\u7684\u8bc4\u4f30\u5fc5\u987b\u5bf9\u4f5c\u8005\u900f\u660e\u4e14\u53ef\u4e89\u8bae\u3002\u6211\u4eec\u5f3a\u8c03\uff0c\u878d\u5165\u4eba\u5de5\u667a\u80fd\u7684\u540c\u884c\u8bc4\u5ba1\u5fc5\u987b\u662f\u9488\u5bf9\u7279\u5b9a\u671f\u520a\u7684\uff0c\u65e8\u5728\u5b9e\u73b0\u6548\u7387\u3001\u51c6\u786e\u6027\u548c\u53ef\u95ee\u8d23\u6027\uff0c\u5e76\u5728\u4eba\u7c7b\u53c2\u4e0e\u76d1\u7763\u7684\u6846\u67b6\u4e0b\u8fd0\u884c\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u671f\u520a\u8fd0\u8425\u7684\u6570\u5b66\u6a21\u578b\uff0c\u4ee5\u6bd4\u8f83\u5728\u65e0AI\u73b0\u72b6\u6d41\u7a0b\u4e0e\u6240\u63d0\u8bae\u7684AI\u878d\u5165\u6d41\u7a0b\u4e0b\u7684\u7ed3\u679c\u3002\u8be5\u6a21\u578b\u63ed\u793a\u4e86\u53d7\u63a7\u4eba\u5de5\u667a\u80fd\u5982\u4f55\u91cd\u65b0\u914d\u7f6e\u4eba\u7c7b\u8bc4\u5ba1\u5458\u7684\u5de5\u4f5c\u91cf\uff0c\u5e76\u9610\u660e\u4e86\u5728\u4f55\u79cd\u6761\u4ef6\u4e0bAI\u878d\u5165\u6d41\u7a0b\u80fd\u591f\u6539\u5584\u5173\u952e\u6307\u6807\uff0c\u5982\u5904\u7406\u5468\u671f\u548c\u51b3\u7b56\u51c6\u786e\u6027\u3002\u6211\u4eec\u7684\u6838\u5fc3\u89c2\u70b9\u662f\uff0c\u671f\u520a\u9700\u8981\u4ee5\u5ba1\u614e\u4e14\u5236\u5ea6\u5316\u7684\u65b9\u5f0f\u4f7f\u7528\u4eba\u5de5\u667a\u80fd\u4e8e\u8bc4\u5ba1\u6d41\u7a0b\u3002\u6211\u4eec\u8ba4\u8bc6\u5230\uff0c\u786e\u5b9a\u4e00\u4e2a\u2018\u6700\u4f18\u2019\u7684AI\u878d\u5165\u540c\u884c\u8bc4\u5ba1\u6d41\u7a0b\uff0c\u751a\u81f3\u660e\u786e\u9884\u6d4b\u67d0\u4e00\u65b9\u6848\u7684\u540e\u679c\uff0c\u90fd\u9700\u8981\u5927\u91cf\u5b9e\u9a8c\u6765\u6821\u51c6\u548c\u914d\u7f6e\u591a\u79cd\u4e0d\u540c\u8bbe\u8ba1\u7684\u5de5\u4f5c\u6d41\u7a0b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790", "AI"]}, {"doi": "10.1287/mnsc.2026.02441", "journal": "MS", "title": "The Sound We Haven\u2019t Heard Before: A Commentary on \u201cFighting Fire with Fire: Infusing AI into Peer Review to Sustain Quality Scholarship\u201d", "authors": ["Tinglong Dai"], "author_details": [{"name": "Tinglong Dai", "affiliations": ["Carey Business School, Johns Hopkins University, Baltimore, Maryland 21202; and Data Science and AI Institute, Johns Hopkins University, Baltimore, Maryland 21209"]}], "abstract": "This commentary responds to \u201cFighting Fire with Fire: Infusing AI into Peer Review to Sustain Quality Scholarship\u201d [Bhargava HK, Bana S, Zhang Z, Brandimarte L, Choudary V, Li F, Loupos P, Zantedeschi D (2026) Fighting fire with fire: Infusing AI into peer review to sustain quality scholarship. Management Sci. Forthcoming.]. It shares the paper\u2019s core position, that journals should govern artificial intelligence openly rather than leave it to the shadows, but it questions the premise that rising submission volume poses an existential threat. The safeguard is human judgment. Our shared fatigue with derivative, repetitive work is a sensor more discerning than any AI detector, because a model trained on what we have already rewarded cannot produce the novelty that our community prizes. The threat to a journal like Management Science is thus more contained than the original alarm implies, provided AI remains a non-final input and humans retain ownership of novelty and contribution. One test should govern any AI workflow: does it ask more of human judgment, or less?", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2026.02441", "title_zh": "\u6211\u4eec\u5c1a\u672a\u542c\u5230\u7684\u58f0\u97f3\uff1a\u5bf9\u300a\u4ee5\u706b\u653b\u706b\uff1a\u5c06\u4eba\u5de5\u667a\u80fd\u6ce8\u5165\u540c\u884c\u8bc4\u5ba1\u4ee5\u7ef4\u6301\u5b66\u672f\u8d28\u91cf\u300b\u7684\u8bc4\u8bba", "abstract_zh": "\u672c\u6587\u8bc4\u8bba\u56de\u5e94\u4e86\u300a\u4ee5\u706b\u653b\u706b\uff1a\u5c06\u4eba\u5de5\u667a\u80fd\u6ce8\u5165\u540c\u884c\u8bc4\u5ba1\u4ee5\u7ef4\u6301\u5b66\u672f\u8d28\u91cf\u300b[Bhargava HK, Bana S, Zhang Z, Brandimarte L, Choudary V, Li F, Loupos P, Zantedeschi D (2026) Fighting fire with fire: Infusing AI into peer review to sustain quality scholarship. Management Sci. Forthcoming.]\u3002\u672c\u6587\u8d5e\u540c\u8be5\u8bba\u6587\u7684\u6838\u5fc3\u89c2\u70b9\uff0c\u5373\u671f\u520a\u5e94\u516c\u5f00\u6cbb\u7406\u4eba\u5de5\u667a\u80fd\uff0c\u800c\u975e\u5c06\u5176\u7f6e\u4e8e\u9634\u5f71\u4e4b\u4e2d\uff0c\u4f46\u8d28\u7591\u4e86\u63d0\u4ea4\u91cf\u4e0a\u5347\u6784\u6210\u751f\u5b58\u5a01\u80c1\u7684\u524d\u63d0\u3002\u4fdd\u969c\u63aa\u65bd\u662f\u4eba\u7c7b\u5224\u65ad\u3002\u6211\u4eec\u5bf9\u884d\u751f\u6027\u3001\u91cd\u590d\u6027\u5de5\u4f5c\u7684\u5171\u540c\u75b2\u60eb\uff0c\u6bd4\u4efb\u4f55\u4eba\u5de5\u667a\u80fd\u68c0\u6d4b\u5668\u90fd\u66f4\u654f\u9510\uff0c\u56e0\u4e3a\u4e00\u4e2a\u57fa\u4e8e\u6211\u4eec\u5df2\u5956\u52b1\u5185\u5bb9\u8bad\u7ec3\u7684\u6a21\u578b\uff0c\u65e0\u6cd5\u4ea7\u751f\u6211\u4eec\u793e\u533a\u6240\u73cd\u89c6\u7684\u65b0\u9896\u6027\u3002\u56e0\u6b64\uff0c\u5bf9\u4e8e\u50cf\u300a\u7ba1\u7406\u79d1\u5b66\u300b\u8fd9\u6837\u7684\u671f\u520a\u800c\u8a00\uff0c\u5a01\u80c1\u7a0b\u5ea6\u8fdc\u4f4e\u4e8e\u539f\u6587\u6240\u6697\u793a\u7684\uff0c\u524d\u63d0\u662f\u4eba\u5de5\u667a\u80fd\u4ec5\u4f5c\u4e3a\u975e\u6700\u7ec8\u8f93\u5165\uff0c\u4e14\u4eba\u7c7b\u59cb\u7ec8\u62e5\u6709\u5bf9\u65b0\u9896\u6027\u548c\u8d21\u732e\u7684\u4e3b\u5bfc\u6743\u3002\u4efb\u4f55\u4eba\u5de5\u667a\u80fd\u6d41\u7a0b\u90fd\u5e94\u9075\u5faa\u4e00\u4e2a\u6d4b\u8bd5\u6807\u51c6\uff1a\u5b83\u662f\u5426\u589e\u52a0\u4e86\u5bf9\u4eba\u7c7b\u5224\u65ad\u7684\u8981\u6c42\uff0c\u8fd8\u662f\u51cf\u5c11\u4e86\uff1f", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2024.07257", "journal": "MS", "title": "Understanding People\u2019s Preferences for Predictions: People Prioritize Being Right over Minimizing How Wrong They Are in Expectation", "authors": ["Berkeley J. Dietvorst"], "author_details": [{"name": "Berkeley J. Dietvorst", "affiliations": ["The University of Chicago Booth School of Business, Chicago, Illinois 60637"]}], "abstract": "This work explores the preferences that laypeople exhibit when making and evaluating predictions in the form of point estimates (e.g., the high temperature will be 66\u00b0). I propose that people typically have diminishing sensitivity to prediction error: the absolute difference between a prediction and a realized outcome. As a result, people often prioritize \u201cbeing right,\u201c focusing on achieving near perfect predictions and placing less emphasis on the magnitude of errors when errors occur. Across 16 studies using varying methods and stimuli, participants exhibited multiple behaviors consistent with diminishing sensitivity to prediction error: (i) predicting the mode of distributions, (ii) restricting predictions to possible outcomes, (iii) reporting decreasing reactions to increasing marginal units of error, and (iv) preferring predictive models built with diminishing sensitivity to error. This behavior diverges from traditional methods of building predictive models and common interpretations of people\u2019s predictions, which often prioritize avoiding large errors and assume that people are predicting the mean. Ultimately, this work not only highlights the discrepancies between our current practices and people\u2019s preferences for predictions but also calls for a more thorough exploration of human objectives before we build models for them to use or make inferences about their beliefs in light of a decision they made.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07257", "title_zh": "\u7406\u89e3\u4eba\u4eec\u5bf9\u9884\u6d4b\u7684\u504f\u597d\uff1a\u4eba\u4eec\u66f4\u91cd\u89c6\u2018\u6b63\u786e\u2019\u800c\u975e\u2018\u51cf\u5c11\u9519\u8bef\u2019", "abstract_zh": "\u672c\u7814\u7a76\u63a2\u8ba8\u4e86\u666e\u901a\u4eba\u505a\u51fa\u548c\u8bc4\u4f30\u70b9\u4f30\u8ba1\u9884\u6d4b\uff08\u4f8b\u5982\uff0c\u6700\u9ad8\u6e29\u5ea6\u4e3a66\u00b0\uff09\u65f6\u8868\u73b0\u51fa\u7684\u504f\u597d\u3002\u6211\u63d0\u51fa\uff0c\u4eba\u4eec\u901a\u5e38\u5bf9\u9884\u6d4b\u8bef\u5dee\uff08\u5373\u9884\u6d4b\u503c\u4e0e\u5b9e\u9645\u7ed3\u679c\u4e4b\u95f4\u7684\u7edd\u5bf9\u5dee\u503c\uff09\u5177\u6709\u9012\u51cf\u654f\u611f\u6027\u3002\u56e0\u6b64\uff0c\u4eba\u4eec\u5f80\u5f80\u66f4\u91cd\u89c6\u2018\u51c6\u786e\u65e0\u8bef\u2019\uff0c\u4e13\u6ce8\u4e8e\u5b9e\u73b0\u63a5\u8fd1\u5b8c\u7f8e\u7684\u9884\u6d4b\uff0c\u800c\u5728\u51fa\u73b0\u9519\u8bef\u65f6\u5219\u8f83\u5c11\u5173\u6ce8\u8bef\u5dee\u7684\u5927\u5c0f\u3002\u572816\u9879\u4f7f\u7528\u4e0d\u540c\u65b9\u6cd5\u548c\u523a\u6fc0\u7684\u5b9e\u9a8c\u4e2d\uff0c\u53c2\u4e0e\u8005\u8868\u73b0\u51fa\u591a\u79cd\u4e0e\u9884\u6d4b\u8bef\u5dee\u9012\u51cf\u654f\u611f\u6027\u4e00\u81f4\u7684\u884c\u4e3a\uff1a\uff08i\uff09\u9884\u6d4b\u5206\u5e03\u7684\u4f17\u6570\uff1b\uff08ii\uff09\u5c06\u9884\u6d4b\u9650\u5236\u5728\u53ef\u80fd\u7684\u7ed3\u679c\u8303\u56f4\u5185\uff1b\uff08iii\uff09\u5bf9\u8bef\u5dee\u7684\u8fb9\u9645\u589e\u91cf\u8868\u73b0\u51fa\u53cd\u5e94\u9012\u51cf\uff1b\uff08iv\uff09\u66f4\u504f\u597d\u91c7\u7528\u5bf9\u8bef\u5dee\u5177\u6709\u9012\u51cf\u654f\u611f\u6027\u7684\u9884\u6d4b\u6a21\u578b\u3002\u8fd9\u79cd\u884c\u4e3a\u4e0e\u4f20\u7edf\u9884\u6d4b\u6a21\u578b\u6784\u5efa\u65b9\u6cd5\u4ee5\u53ca\u4eba\u4eec\u5bf9\u9884\u6d4b\u7684\u5e38\u89c1\u7406\u89e3\u76f8\u6096\uff0c\u540e\u8005\u901a\u5e38\u5f3a\u8c03\u907f\u514d\u5927\u8bef\u5dee\uff0c\u5e76\u5047\u8bbe\u4eba\u4eec\u9884\u6d4b\u7684\u662f\u5747\u503c\u3002\u6700\u7ec8\uff0c\u672c\u7814\u7a76\u4e0d\u4ec5\u63ed\u793a\u4e86\u5f53\u524d\u5b9e\u8df5\u4e0e\u4eba\u4eec\u5b9e\u9645\u9884\u6d4b\u504f\u597d\u4e4b\u95f4\u7684\u5dee\u5f02\uff0c\u4e5f\u547c\u5401\u5728\u4e3a\u4eba\u4eec\u6784\u5efa\u6a21\u578b\u6216\u57fa\u4e8e\u5176\u51b3\u7b56\u63a8\u65ad\u5176\u4fe1\u5ff5\u4e4b\u524d\uff0c\u5e94\u66f4\u6df1\u5165\u5730\u63a2\u7d22\u4eba\u7c7b\u7684\u76ee\u6807\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.06067", "journal": "MS", "title": "Correlation of Rankings in Matching Markets", "authors": ["R\u00e9mi Castera", "Patrick Loiseau", "Bary S. R. Pradelski"], "author_details": [{"name": "R\u00e9mi Castera", "affiliations": ["LIG, Universit\u00e9 Grenoble Alpes, 38400 Saint-Martin-d\u2019H\u00e8res, France; and Moroccan Center for Game Theory, Mohammed VI Polytechnic University, Rabat 11103, Morocco"]}, {"name": "Patrick Loiseau", "affiliations": ["Fairplay Joint Team, Institut National de Recherche en Informatique et en Automatique Saclay-\u00cele-de-France, 91120 Palaiseau, France"]}, {"name": "Bary S. R. Pradelski", "affiliations": ["Maison Fran\u00e7aise d\u2019Oxford, CNRS, Oxford OX2 6SE, United Kingdom; and Department of Economics, University of Oxford, Oxford OX1 2JD, United Kingdom"]}], "abstract": "We study the role of correlation in matching markets, where multiple decision makers simultaneously face selection problems from the same pool of candidates. We propose a model in which a candidate\u2019s priority scores across different decision makers exhibit varying levels of correlation dependent on the candidate\u2019s sociodemographic group. Such differential correlation can arise in school choice because of the varying prevalence of selection criteria, in college admissions because of test-optional policies, or because of algorithmic monoculture, that is, when decision makers rely on the same algorithms and data sets to evaluate candidates. We show that higher correlation for one of the groups generally improves the outcome for all groups, leading to higher efficiency. However, students from a given group are more likely to remain unmatched as their own correlation level increases. This implies that it is advantageous to belong to a low-correlation group. Finally, we extend the tie-breaking literature to multiple priority classes and intermediate levels of correlation. Overall, our results point to differential correlation as a previously overlooked systemic source of group inequalities in school, university, and job admissions.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06067", "title_zh": "\u5339\u914d\u5e02\u573a\u4e2d\u6392\u540d\u76f8\u5173\u6027\u7684\u7814\u7a76", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5339\u914d\u5e02\u573a\u4e2d\u76f8\u5173\u6027\u7684\u4f5c\u7528\uff0c\u5176\u4e2d\u591a\u4e2a\u51b3\u7b56\u8005\u540c\u65f6\u4ece\u540c\u4e00\u5019\u9009\u6c60\u4e2d\u9762\u4e34\u9009\u62e9\u95ee\u9898\u3002\u6211\u4eec\u63d0\u51fa\u4e00\u4e2a\u6a21\u578b\uff0c\u5176\u4e2d\u5019\u9009\u4eba\u5728\u4e0d\u540c\u51b3\u7b56\u8005\u624b\u4e2d\u7684\u4f18\u5148\u7ea7\u8bc4\u5206\u8868\u73b0\u51fa\u56e0\u5019\u9009\u4eba\u7684\u793e\u4f1a\u4eba\u53e3\u7279\u5f81\u7fa4\u4f53\u800c\u5f02\u7684\u76f8\u5173\u6027\u6c34\u5e73\u3002\u8fd9\u79cd\u5dee\u5f02\u6027\u76f8\u5173\u6027\u53ef\u80fd\u6e90\u4e8e\u5b66\u6821\u9009\u62e9\u4e2d\u4e0d\u540c\u9009\u62e9\u6807\u51c6\u7684\u666e\u904d\u7a0b\u5ea6\uff0c\u5927\u5b66\u62db\u751f\u4e2d\u6d4b\u8bd5\u53ef\u9009\u653f\u7b56\uff0c\u6216\u7b97\u6cd5\u540c\u8d28\u5316\uff0c\u5373\u51b3\u7b56\u8005\u4f9d\u8d56\u76f8\u540c\u7684\u7b97\u6cd5\u548c\u6570\u636e\u96c6\u6765\u8bc4\u4f30\u5019\u9009\u4eba\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5bf9\u4e8e\u67d0\u4e00\u7fa4\u4f53\u800c\u8a00\uff0c\u76f8\u5173\u6027\u8d8a\u9ad8\uff0c\u901a\u5e38\u4f1a\u6539\u5584\u6240\u6709\u7fa4\u4f53\u7684\u6700\u7ec8\u7ed3\u679c\uff0c\u4ece\u800c\u63d0\u9ad8\u6548\u7387\u3002\u7136\u800c\uff0c\u67d0\u4e00\u7fa4\u4f53\u6210\u5458\u81ea\u8eab\u76f8\u5173\u6027\u4e0a\u5347\u65f6\uff0c\u66f4\u53ef\u80fd\u4fdd\u6301\u672a\u5339\u914d\u72b6\u6001\u3002\u8fd9\u8868\u660e\uff0c\u5c5e\u4e8e\u4f4e\u76f8\u5173\u6027\u7fa4\u4f53\u662f\u6709\u5229\u7684\u3002\u6700\u540e\uff0c\u6211\u4eec\u5c06\u5e73\u5c40\u5904\u7406\u6587\u732e\u6269\u5c55\u5230\u591a\u4e2a\u4f18\u5148\u7ea7\u7c7b\u522b\u548c\u4e2d\u95f4\u6c34\u5e73\u7684\u76f8\u5173\u6027\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u7ed3\u679c\u6307\u51fa\u4e86\u5dee\u5f02\u6027\u76f8\u5173\u6027\u4f5c\u4e3a\u4e4b\u524d\u88ab\u5ffd\u89c6\u7684\u7cfb\u7edf\u6027\u6765\u6e90\uff0c\u5bfc\u81f4\u5b66\u6821\u3001\u5927\u5b66\u548c\u5c31\u4e1a\u62db\u751f\u4e2d\u7684\u7fa4\u4f53\u4e0d\u5e73\u7b49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.02887", "journal": "MS", "title": "Squeezing Shorts Through Social Media Platforms", "authors": ["Franklin Allen", "Marlene Haas", "Eric Nowak", "Matteo Pirovano", "Angel Tengulov"], "author_details": [{"name": "Franklin Allen", "affiliations": ["Imperial College London, South Kensington, London SW7 2AZ, United Kingdom"]}, {"name": "Marlene Haas", "affiliations": ["Independent Scholar, Lawrence, Kansas 66047"]}, {"name": "Eric Nowak", "affiliations": ["Universit\u00e0 della Svizzera italiana (USI) and Swiss Finance Institute (SFI), 6904 Lugano, Switzerland"]}, {"name": "Matteo Pirovano", "affiliations": ["Universit\u00e0 della Svizzera italiana (USI) and Swiss Finance Institute (SFI), 6904 Lugano, Switzerland"]}, {"name": "Angel Tengulov", "affiliations": ["University of Kansas School of Business, Lawrence, Kansas 66045"]}], "abstract": "In January 2021, a group of stocks listed on U.S. stock exchanges experienced sudden price increases, which, coupled with high short interest, led to short squeezes. We find that discussions on social media fueled the association between retail trading and subsequent stock returns. Options market activity and securities lending constraints also played a central role. Using unique data from social media platforms, we provide a comprehensive account of these short squeezes. We find that they significantly impeded market quality for the stocks at issue and their competitors. Thus, the interplay between social media and retail traders may have adverse consequences for market quality and efficiency.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.02887", "title_zh": "\u901a\u8fc7\u793e\u4ea4\u5a92\u4f53\u5e73\u53f0\u6324\u538b\u7a7a\u5934\u5934\u5bf8", "abstract_zh": "2021\u5e741\u6708\uff0c\u4e00\u6279\u5728\u7f8e\u56fd\u8bc1\u5238\u4ea4\u6613\u6240\u4e0a\u5e02\u7684\u80a1\u7968\u51fa\u73b0\u4e86\u7a81\u7136\u7684\u4ef7\u683c\u4e0a\u6da8\uff0c\u7ed3\u5408\u9ad8\u7a7a\u5934\u5934\u5bf8\uff0c\u5f15\u53d1\u4e86\u7a7a\u5934\u6324\u538b\u73b0\u8c61\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u793e\u4ea4\u5a92\u4f53\u4e0a\u7684\u8ba8\u8bba\u52a0\u5267\u4e86\u96f6\u552e\u4ea4\u6613\u8005\u4e0e\u540e\u7eed\u80a1\u7968\u56de\u62a5\u4e4b\u95f4\u7684\u5173\u8054\u3002\u671f\u6743\u5e02\u573a\u6d3b\u52a8\u4ee5\u53ca\u8bc1\u5238\u501f\u8d37\u9650\u5236\u4e5f\u5728\u5176\u4e2d\u53d1\u6325\u4e86\u5173\u952e\u4f5c\u7528\u3002\u5229\u7528\u6765\u81ea\u793e\u4ea4\u5a92\u4f53\u5e73\u53f0\u7684\u72ec\u5bb6\u6570\u636e\uff0c\u6211\u4eec\u5bf9\u8fd9\u4e9b\u7a7a\u5934\u6324\u538b\u73b0\u8c61\u63d0\u4f9b\u4e86\u5168\u9762\u7684\u89e3\u91ca\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u4e9b\u73b0\u8c61\u663e\u8457\u635f\u5bb3\u4e86\u6d89\u4e8b\u80a1\u7968\u53ca\u5176\u7ade\u4e89\u5bf9\u624b\u7684\u5e02\u573a\u8d28\u91cf\u3002\u56e0\u6b64\uff0c\u793e\u4ea4\u5a92\u4f53\u4e0e\u96f6\u552e\u4ea4\u6613\u8005\u7684\u76f8\u4e92\u4f5c\u7528\u53ef\u80fd\u5bf9\u5e02\u573a\u8d28\u91cf\u548c\u6548\u7387\u4ea7\u751f\u4e0d\u5229\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1287/mnsc.2022.02435", "journal": "MS", "title": "How and When Are High-Frequency Stock Returns Predictable?", "authors": ["Yacine Ait-Sahalia", "Jianqing Fan", "Lirong Xue", "Xiaonan Zhu"], "author_details": [{"name": "Yacine Ait-Sahalia", "affiliations": ["Department of Economics, Princeton University, Princeton, New Jersey 08540; and National Bureau of Economic Research, Cambridge, Massachusetts 02138"]}, {"name": "Jianqing Fan", "affiliations": ["International School of Economics and Management, Beijing Capital University of Economics and Business, Beijing 100070, China; and Department of Operations Research and Financial Engineering, Princeton University, Princeton, New Jersey 08540"]}, {"name": "Lirong Xue", "affiliations": ["Department of Operations Research and Financial Engineering, Princeton University, Princeton, New Jersey 08540"]}, {"name": "Xiaonan Zhu", "affiliations": ["Department of Operations Research and Financial Engineering, Princeton University, Princeton, New Jersey 08540"]}], "abstract": "This paper studies the predictability of ultrahigh-frequency stock returns and durations to relevant price, volume, and transaction events using machine learning methods. We find that contrary to low-frequency and long-horizon returns, where predictability is rare and inconsistent, predictability in high-frequency returns and durations is large, systematic, and pervasive over short horizons. We identify the relevant predictors constructed from trades and quotes data, and we examine what determines the variation in predictability across the stock\u2019s own characteristics and market environments. Next, we compute how the predictability improves with the timeliness of the data on a scale of milliseconds and conversely degrades with delays, providing a valuation of each millisecond gained. Finally, we simulate the impact of getting an (imperfect) peek at the incoming order flow, a look-ahead ability that is often attributed to the fastest high-frequency traders, in terms of improving the predictability of the returns and durations.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2022.02435", "title_zh": "\u9ad8\u9891\u80a1\u7968\u6536\u76ca\u7387\u5982\u4f55\u4ee5\u53ca\u5728\u4f55\u65f6\u53ef\u9884\u6d4b\uff1f", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5229\u7528\u673a\u5668\u5b66\u4e60\u65b9\u6cd5\uff0c\u57fa\u4e8e\u4ea4\u6613\u548c\u62a5\u4ef7\u6570\u636e\u5bf9\u8d85\u9ad8\u9891\u80a1\u7968\u6536\u76ca\u7387\u548c\u6301\u7eed\u65f6\u95f4\u7684\u53ef\u9884\u6d4b\u6027\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u4e0e\u4f4e\u9891\u548c\u957f\u5468\u671f\u6536\u76ca\u7387\u7684\u53ef\u9884\u6d4b\u6027\u7f55\u89c1\u4e14\u4e0d\u4e00\u81f4\u4e0d\u540c\uff0c\u9ad8\u9891\u6536\u76ca\u7387\u548c\u6301\u7eed\u65f6\u95f4\u7684\u53ef\u9884\u6d4b\u6027\u5728\u77ed\u671f\u5185\u5177\u6709\u663e\u8457\u3001\u7cfb\u7edf\u6027\u548c\u666e\u904d\u6027\u3002\u6211\u4eec\u8bc6\u522b\u4e86\u7531\u4ea4\u6613\u548c\u62a5\u4ef7\u6570\u636e\u6784\u5efa\u7684\u76f8\u5173\u9884\u6d4b\u56e0\u5b50\uff0c\u5e76\u8003\u5bdf\u4e86\u8fd9\u4e9b\u9884\u6d4b\u6027\u5982\u4f55\u53d7\u5230\u4e2a\u80a1\u7279\u5f81\u548c\u5e02\u573a\u73af\u5883\u7684\u5f71\u54cd\u3002\u6b64\u5916\uff0c\u6211\u4eec\u8ba1\u7b97\u4e86\u9884\u6d4b\u6027\u968f\u6570\u636e\u65f6\u6548\u6027\uff08\u4ee5\u6beb\u79d2\u4e3a\u5355\u4f4d\uff09\u63d0\u5347\u800c\u589e\u5f3a\uff0c\u968f\u5ef6\u8fdf\u589e\u52a0\u800c\u51cf\u5f31\u7684\u7a0b\u5ea6\uff0c\u4ece\u800c\u8bc4\u4f30\u4e86\u6bcf\u4e00\u6beb\u79d2\u4fe1\u606f\u83b7\u53d6\u7684\u4ef7\u503c\u3002\u6700\u540e\uff0c\u6211\u4eec\u6a21\u62df\u4e86\u83b7\u5f97\uff08\u4e0d\u5b8c\u5168\u7684\uff09\u5373\u5c06\u5230\u6765\u8ba2\u5355\u6d41\u7684\u201c\u63d0\u524d\u89c2\u5bdf\u201d\u80fd\u529b\u2014\u2014\u8fd9\u79cd\u80fd\u529b\u901a\u5e38\u5f52\u56e0\u4e8e\u6700\u5feb\u901f\u7684\u9ad8\u9891\u4ea4\u6613\u8005\u2014\u2014\u5bf9\u6536\u76ca\u7387\u548c\u6301\u7eed\u65f6\u95f4\u53ef\u9884\u6d4b\u6027\u7684\u63d0\u5347\u6548\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "AI"]}, {"doi": "10.1287/mnsc.2022.00857", "journal": "MS", "title": "The Changing Nature of Firm Innovation: Short-Termism and Influential Innovation in U.S. Public Firms", "authors": ["Yuan Shi", "Rachelle C. Sampson", "Brent Goldfarb", "Rafael A. Corredoira"], "author_details": [{"name": "Yuan Shi", "affiliations": ["Cornell University, Ithaca, New York 14853"]}, {"name": "Rachelle C. Sampson", "affiliations": ["University of Maryland, College Park, Maryland 20742"]}, {"name": "Brent Goldfarb", "affiliations": ["University of Maryland, College Park, Maryland 20742"]}, {"name": "Rafael A. Corredoira", "affiliations": ["Newcastle University, Newcastle upon Tyne NE1 7RU, United Kingdom"]}], "abstract": "We examine the link between short-term pressures and technologically significant innovation in U.S. public firms in 1997\u20132015. Using a market-based measure of short-term pressure, we estimate its relationship with influential and novel patents. We find that firms facing more intense short-term pressures are less likely to patent highly influential or novel innovations. To evaluate whether this relationship is causal, we use changes in ownership styles following financial institution mergers as instruments. Our analysis suggests that changing short-term pressures from investors had a causal impact on firm innovative outcomes; this finding is robust to a wide variety of empirical specifications. While public firms as a whole retained a constant share of highly influential patents, this activity has become more concentrated in fewer firms. This shift does not appear to be fully compensated by an increase in technologically significant patents by nonpublic firms such as venture-capital (VC)-backed start-ups. These findings raise questions about capital markets\u2019 impact on firm R&D strategy and the nature of innovative activities in public firms.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2022.00857", "title_zh": "\u4f01\u4e1a\u521b\u65b0\u6027\u8d28\u7684\u6f14\u53d8\uff1a\u77ed\u671f\u4e3b\u4e49\u4e0e\u5177\u6709\u5f71\u54cd\u529b\u7684\u6280\u672f\u521b\u65b0", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u77ed\u671f\u538b\u529b\u4e0e1997\u5e74\u81f32015\u5e74\u671f\u95f4\u7f8e\u56fd\u4e0a\u5e02\u516c\u53f8\u4e2d\u5177\u6709\u6280\u672f\u91cd\u8981\u6027\u7684\u521b\u65b0\u4e4b\u95f4\u7684\u5173\u7cfb\u3002\u4f7f\u7528\u57fa\u4e8e\u5e02\u573a\u7684\u77ed\u671f\u538b\u529b\u8861\u91cf\u6307\u6807\uff0c\u6211\u4eec\u4f30\u8ba1\u4e86\u5176\u4e0e\u5177\u6709\u5f71\u54cd\u529b\u548c\u65b0\u9896\u6027\u7684\u4e13\u5229\u4e4b\u95f4\u7684\u5173\u7cfb\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u9762\u4e34\u66f4\u5f3a\u70c8\u77ed\u671f\u538b\u529b\u7684\u4f01\u4e1a\u66f4\u4e0d\u53ef\u80fd\u83b7\u5f97\u5177\u6709\u9ad8\u5ea6\u5f71\u54cd\u529b\u6216\u65b0\u9896\u6027\u7684\u4e13\u5229\u3002\u4e3a\u4e86\u8bc4\u4f30\u8fd9\u79cd\u5173\u7cfb\u662f\u5426\u5177\u6709\u56e0\u679c\u6027\uff0c\u6211\u4eec\u5229\u7528\u91d1\u878d\u673a\u6784\u5408\u5e76\u540e\u6240\u6709\u6743\u98ce\u683c\u7684\u53d8\u5316\u4f5c\u4e3a\u5de5\u5177\u53d8\u91cf\u3002\u6211\u4eec\u7684\u5206\u6790\u8868\u660e\uff0c\u6295\u8d44\u8005\u77ed\u671f\u538b\u529b\u7684\u53d8\u5316\u5bf9\u4f01\u4e1a\u521b\u65b0\u6210\u679c\u4ea7\u751f\u4e86\u56e0\u679c\u5f71\u54cd\uff1b\u8fd9\u4e00\u53d1\u73b0\u5728\u591a\u79cd\u7ecf\u9a8c\u6a21\u578b\u4e2d\u5747\u5177\u6709\u7a33\u5065\u6027\u3002\u5c3d\u7ba1\u4e0a\u5e02\u516c\u53f8\u6574\u4f53\u5728\u5177\u6709\u9ad8\u5ea6\u5f71\u54cd\u529b\u4e13\u5229\u7684\u5360\u6bd4\u4fdd\u6301\u4e0d\u53d8\uff0c\u4f46\u6b64\u7c7b\u521b\u65b0\u6d3b\u52a8\u5df2\u8d8a\u6765\u8d8a\u96c6\u4e2d\u5728\u5c11\u6570\u4f01\u4e1a\u4e2d\u3002\u8fd9\u4e00\u8d8b\u52bf\u4f3c\u4e4e\u5e76\u672a\u88ab\u98ce\u9669\u6295\u8d44\uff08VC\uff09\u652f\u6301\u7684\u521d\u521b\u4f01\u4e1a\u7b49\u975e\u4e0a\u5e02\u516c\u53f8\u4e2d\u6280\u672f\u91cd\u8981\u6027\u4e13\u5229\u7684\u589e\u52a0\u6240\u5b8c\u5168\u62b5\u6d88\u3002\u8fd9\u4e9b\u53d1\u73b0\u5f15\u53d1\u4e86\u5173\u4e8e\u8d44\u672c\u5e02\u573a\u5bf9\u4f01\u4e1a\u7814\u53d1\u6218\u7565\u4ee5\u53ca\u4e0a\u5e02\u516c\u53f8\u521b\u65b0\u6d3b\u52a8\u6027\u8d28\u5f71\u54cd\u7684\u7591\u95ee\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1287/mnsc.2022.01874", "journal": "MS", "title": "Private Equity Buyouts and Employee Health", "authors": ["Pilar Garcia-Gomez", "Ernst Maug", "Stefan Obernberger"], "author_details": [{"name": "Pilar Garcia-Gomez", "affiliations": ["Erasmus University, 3000 DR Rotterdam, Netherlands"]}, {"name": "Ernst Maug", "affiliations": ["University of Mannheim, 68131 Mannheim, Germany"]}, {"name": "Stefan Obernberger", "affiliations": ["Erasmus University, 3000 DR Rotterdam, Netherlands"]}], "abstract": "We examine the role of employee health for the restructuring of the labor force during private equity buyouts using employee-level data of 56,000 Dutch buyout employees. We find no evidence that buyouts have a negative impact on the health of buyout employees. Employees lose income and employment after buyouts, and these losses are far larger for employees in poorer health. The negative effect of buyouts on employees\u2019 incomes is buffered by social transfers, and this buffer is larger for employees in poorer health, who exit the labor market at a much higher rate. Health characteristics associated with lower wages in the general population are strongly predictive of job loss after buyouts.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2022.01874", "title_zh": "\u79c1\u52df\u80a1\u6743\u6536\u8d2d\u4e0e\u5458\u5de5\u5065\u5eb7", "abstract_zh": "\u6211\u4eec\u5229\u752856,000\u540d\u8377\u5170\u79c1\u52df\u80a1\u6743\u6536\u8d2d\u5458\u5de5\u7684\u4e2a\u4f53\u5c42\u9762\u6570\u636e\uff0c\u7814\u7a76\u4e86\u5458\u5de5\u5065\u5eb7\u72b6\u51b5\u5728\u79c1\u52df\u80a1\u6743\u6536\u8d2d\u8fc7\u7a0b\u4e2d\u52b3\u52a8\u529b\u7ed3\u6784\u91cd\u7ec4\u4e2d\u7684\u4f5c\u7528\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u79c1\u52df\u80a1\u6743\u6536\u8d2d\u5e76\u672a\u5bf9\u5458\u5de5\u5065\u5eb7\u4ea7\u751f\u8d1f\u9762\u5f71\u54cd\u3002\u5458\u5de5\u5728\u6536\u8d2d\u540e\u9762\u4e34\u6536\u5165\u548c\u5c31\u4e1a\u7684\u635f\u5931\uff0c\u4e14\u5065\u5eb7\u72b6\u51b5\u8f83\u5dee\u7684\u5458\u5de5\u6240\u906d\u53d7\u7684\u635f\u5931\u66f4\u4e3a\u4e25\u91cd\u3002\u79c1\u52df\u80a1\u6743\u6536\u8d2d\u5bf9\u5458\u5de5\u6536\u5165\u7684\u8d1f\u9762\u5f71\u54cd\u901a\u8fc7\u793e\u4f1a\u4fdd\u969c\u8f6c\u79fb\u5f97\u5230\u4e86\u7f13\u51b2\uff0c\u800c\u8fd9\u79cd\u7f13\u51b2\u4f5c\u7528\u5bf9\u5065\u5eb7\u72b6\u51b5\u8f83\u5dee\u7684\u5458\u5de5\u66f4\u4e3a\u663e\u8457\uff0c\u8fd9\u4e9b\u5458\u5de5\u66f4\u53ef\u80fd\u9000\u51fa\u52b3\u52a8\u529b\u5e02\u573a\u3002\u5728\u4e00\u822c\u4eba\u7fa4\u4e2d\u4e0e\u8f83\u4f4e\u5de5\u8d44\u76f8\u5173\u7684\u5065\u5eb7\u7279\u5f81\uff0c\u662f\u9884\u6d4b\u5458\u5de5\u5728\u79c1\u52df\u80a1\u6743\u6536\u8d2d\u540e\u5931\u4e1a\u7684\u5f3a\u9884\u6d4b\u56e0\u5b50\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1287/mnsc.2024.05773", "journal": "MS", "title": "Corporate Tax Avoidance and Sales: Microevidence and Aggregate Implications", "authors": ["Julien Martin", "Mathieu Parenti", "Farid Toubal"], "author_details": [{"name": "Julien Martin", "affiliations": ["Universit\u00e9 du Qu\u00e9bec \u00e0 Montr\u00e9al, Montr\u00e9al, Quebec H2L 2C4, Canada; and Centre for Economic Policy Research, London EC1R 5HL, United Kingdom"]}, {"name": "Mathieu Parenti", "affiliations": ["Centre for Economic Policy Research, London EC1R 5HL, United Kingdom; and Paris School of Economics, 75014 Paris, France; and Institut National de Recherche pour l'Agriculture, l'Alimentation et l'Environnement, 75338 Paris, France; and CESifo, 81679 Munich, Germany"]}, {"name": "Farid Toubal", "affiliations": ["Centre for Economic Policy Research, London EC1R 5HL, United Kingdom; and CESifo, 81679 Munich, Germany; and Universit\u00e9 Paris-Dauphine\u2013PSL, 75775 Paris, France; and CEPII, 75334 Paris, France"]}], "abstract": "This paper examines the effect of corporate tax avoidance (CTA) on U.S. firm-level sales and its aggregate implications. In theory, CTA gives a competitive edge to avoiding firms, which affects the distribution of sales in the economy. In practice, we find a causal impact of CTA on firm-level sales using a broad set of measures of tax avoidance and different identification strategies. Combining microestimates and the model, we assess how changes in CTA over the past two decades have shaped the distribution of sales across U.S. industries. Although the effects vary by sector, rising CTA among large firms has reinforced their dominant positions, contributing to increased concentration, in several key industries.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.05773", "title_zh": "\u4f01\u4e1a\u907f\u7a0e\u4e0e\u9500\u552e\uff1a\u5fae\u89c2\u8bc1\u636e\u53ca\u5176\u603b\u4f53\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u4f01\u4e1a\u907f\u7a0e\uff08CTA\uff09\u5bf9\u7f8e\u56fd\u4f01\u4e1a\u5c42\u9762\u9500\u552e\u7684\u5f71\u54cd\u53ca\u5176\u603b\u4f53\u7ecf\u6d4e\u540e\u679c\u3002\u7406\u8bba\u4e0a\uff0c\u907f\u7a0e\u884c\u4e3a\u4f7f\u907f\u7a0e\u4f01\u4e1a\u83b7\u5f97\u7ade\u4e89\u4f18\u52bf\uff0c\u4ece\u800c\u5f71\u54cd\u7ecf\u6d4e\u4e2d\u9500\u552e\u5206\u5e03\u7684\u683c\u5c40\u3002\u5728\u5b9e\u8df5\u4e2d\uff0c\u6211\u4eec\u5229\u7528\u4e00\u7cfb\u5217\u5e7f\u6cdb\u7684\u907f\u7a0e\u8861\u91cf\u6307\u6807\u548c\u4e0d\u540c\u7684\u8bc6\u522b\u7b56\u7565\uff0c\u53d1\u73b0\u4e86\u907f\u7a0e\u5bf9\u4f01\u4e1a\u5c42\u9762\u9500\u552e\u7684\u56e0\u679c\u5f71\u54cd\u3002\u7ed3\u5408\u5fae\u89c2\u4f30\u8ba1\u7ed3\u679c\u4e0e\u6a21\u578b\u5206\u6790\uff0c\u6211\u4eec\u8bc4\u4f30\u4e86\u8fc7\u53bb\u4e8c\u5341\u5e74\u4e2d\u907f\u7a0e\u884c\u4e3a\u53d8\u5316\u5982\u4f55\u5851\u9020\u4e86\u7f8e\u56fd\u5404\u884c\u4e1a\u9500\u552e\u5206\u5e03\u3002\u5c3d\u7ba1\u4e0d\u540c\u884c\u4e1a\u7684\u6548\u5e94\u5b58\u5728\u5dee\u5f02\uff0c\u4f46\u5927\u578b\u4f01\u4e1a\u907f\u7a0e\u884c\u4e3a\u7684\u4e0a\u5347\u5f3a\u5316\u4e86\u5176\u4e3b\u5bfc\u5730\u4f4d\uff0c\u5bfc\u81f4\u591a\u4e2a\u5173\u952e\u884c\u4e1a\u96c6\u4e2d\u5ea6\u7684\u4e0a\u5347\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2022.03132", "journal": "MS", "title": "Deep Learning Statistical Arbitrage", "authors": ["Jorge Guijarro-Ordonez", "Markus Pelger", "Greg Zanotti"], "author_details": [{"name": "Jorge Guijarro-Ordonez", "affiliations": ["Department of Mathematics, Stanford University, Stanford, California 94305"]}, {"name": "Markus Pelger", "affiliations": ["Department of Management Science & Engineering, Stanford University, Stanford, California 94305"]}, {"name": "Greg Zanotti", "affiliations": ["Department of Management Science & Engineering, Stanford University, Stanford, California 94305"]}], "abstract": "Statistical arbitrage exploits temporal price differences between similar assets. We develop a comprehensive conceptual framework for statistical arbitrage and a novel data-driven solution. First, we construct arbitrage portfolios of similar assets as residual portfolios from conditional latent asset pricing factors. Second, we extract their time-series signals with a powerful machine learning time-series solution, a convolutional transformer. Lastly, we use these signals to form an optimal trading policy, which maximizes risk-adjusted returns under constraints. Our comprehensive empirical study on daily U.S. equities shows a high compensation for arbitrageurs to enforce the law of one price. Our arbitrage strategies obtain considerable out-of-sample mean returns and Sharpe ratios, and outperform all benchmark approaches.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2022.03132", "title_zh": "\u6df1\u5ea6\u5b66\u4e60\u7edf\u8ba1\u5957\u5229", "abstract_zh": "\u7edf\u8ba1\u5957\u5229\u5229\u7528\u76f8\u4f3c\u8d44\u4ea7\u4e4b\u95f4\u7684\u65f6\u95f4\u4ef7\u683c\u5dee\u5f02\u3002\u6211\u4eec\u4e3a\u7edf\u8ba1\u5957\u5229\u6784\u5efa\u4e86\u4e00\u4e2a\u5168\u9762\u7684\u6982\u5ff5\u6846\u67b6\uff0c\u5e76\u63d0\u51fa\u4e86\u4e00\u79cd\u65b0\u9896\u7684\u6570\u636e\u9a71\u52a8\u89e3\u51b3\u65b9\u6848\u3002\u9996\u5148\uff0c\u6211\u4eec\u5c06\u76f8\u4f3c\u8d44\u4ea7\u6784\u9020\u4e3a\u6761\u4ef6\u6f5c\u5728\u8d44\u4ea7\u5b9a\u4ef7\u56e0\u7d20\u7684\u6b8b\u5dee\u6295\u8d44\u7ec4\u5408\u3002\u5176\u6b21\uff0c\u6211\u4eec\u4f7f\u7528\u4e00\u79cd\u5f3a\u5927\u7684\u673a\u5668\u5b66\u4e60\u65f6\u95f4\u5e8f\u5217\u65b9\u6cd5\u2014\u2014\u5377\u79ef\u53d8\u6362\u5668\uff0c\u63d0\u53d6\u8fd9\u4e9b\u6295\u8d44\u7ec4\u5408\u7684\u65f6\u95f4\u5e8f\u5217\u4fe1\u53f7\u3002\u6700\u540e\uff0c\u6211\u4eec\u5229\u7528\u8fd9\u4e9b\u4fe1\u53f7\u5236\u5b9a\u6700\u4f18\u4ea4\u6613\u7b56\u7565\uff0c\u4ee5\u5728\u7ea6\u675f\u6761\u4ef6\u4e0b\u6700\u5927\u5316\u98ce\u9669\u8c03\u6574\u540e\u7684\u6536\u76ca\u3002\u6211\u4eec\u5bf9\u7f8e\u56fd\u6bcf\u65e5\u80a1\u7968\u6570\u636e\u7684\u5168\u9762\u5b9e\u8bc1\u7814\u7a76\u8868\u660e\uff0c\u5957\u5229\u8005\u4e3a\u6267\u884c\u201c\u4e00\u4ef7\u5b9a\u5f8b\u201d\u800c\u83b7\u5f97\u663e\u8457\u7684\u56de\u62a5\u3002\u6211\u4eec\u7684\u5957\u5229\u7b56\u7565\u5728\u6837\u672c\u5916\u53d6\u5f97\u4e86\u53ef\u89c2\u7684\u5e73\u5747\u6536\u76ca\u548c\u590f\u666e\u6bd4\u7387\uff0c\u5e76\u4f18\u4e8e\u6240\u6709\u57fa\u51c6\u65b9\u6cd5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "AI"]}, {"doi": "10.1287/mnsc.2023.03880", "journal": "MS", "title": "Data-Pooling Reinforcement Learning for Preventative Healthcare Intervention", "authors": ["Xinyun Chen", "Pengyi Shi", "Shanwen Pu"], "author_details": [{"name": "Xinyun Chen", "affiliations": ["School of Data Science, School of Management and Economics, The Chinese University of Hong Kong, Shenzhen 518172, China"]}, {"name": "Pengyi Shi", "affiliations": ["Mitch Daniels School of Business, Purdue University, West Lafayette, Indiana 47907"]}, {"name": "Shanwen Pu", "affiliations": ["Shanghai University of Finance and Economics, Shanghai 200437, China"]}], "abstract": "Motivated by the emerging needs of tailored intervention for heterogeneous populations in preventative healthcare applications, we consider a multistage, dynamic decision-making problem in the online setting with unknown model parameters. To deal with the pervasive issue of small sample size in parameter estimation, we develop a novel data-pooling reinforcement learning (RL) algorithm that adaptively pools historical data, with three main innovations: (i) the weight of pooling is directly tied to the performance of the decision (measured by regret) as opposed to estimation accuracy in conventional methods; (ii) no parametric assumptions are needed between historical and current data; and (iii) requiring data-sharing only via aggregate statistics, as opposed to patient-level data. Our data-pooling algorithm framework unifies a variety of RL algorithms, and we establish a theoretical performance guarantee that quantifies the regret bound reduction from our adaptive pooling design compared with benchmarks. We substantiate the theoretical development with extensive empirical experiments via a case study in the context of postdischarge intervention to prevent unplanned readmissions, generating practical insights into healthcare management. Our algorithm enables organizations to leverage public data or published studies for patient management and supports policymakers in promoting aggregate data sharing to enhance population health outcomes.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.03880", "title_zh": "\u7528\u4e8e\u9884\u9632\u6027\u533b\u7597\u5e72\u9884\u7684\u6570\u636e\u6c60\u5316\u5f3a\u5316\u5b66\u4e60", "abstract_zh": "\u53d7\u9884\u9632\u6027\u533b\u7597\u9886\u57df\u5bf9\u5f02\u8d28\u4eba\u7fa4\u5b9a\u5236\u5316\u5e72\u9884\u65e5\u76ca\u589e\u957f\u7684\u9700\u6c42\u542f\u53d1\uff0c\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u4e2a\u5728\u7ebf\u73af\u5883\u4e0b\u5177\u6709\u672a\u77e5\u6a21\u578b\u53c2\u6570\u7684\u591a\u9636\u6bb5\u52a8\u6001\u51b3\u7b56\u95ee\u9898\u3002\u4e3a\u5e94\u5bf9\u53c2\u6570\u4f30\u8ba1\u4e2d\u666e\u904d\u5b58\u5728\u7684\u6837\u672c\u91cf\u5c0f\u95ee\u9898\uff0c\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u65b0\u9896\u7684\u6570\u636e\u6c60\u5316\u5f3a\u5316\u5b66\u4e60\uff08RL\uff09\u7b97\u6cd5\uff0c\u8be5\u7b97\u6cd5\u80fd\u591f\u81ea\u9002\u5e94\u5730\u6574\u5408\u5386\u53f2\u6570\u636e\uff0c\u4e3b\u8981\u521b\u65b0\u70b9\u5305\u62ec\uff1a\uff08i\uff09\u6570\u636e\u6c60\u5316\u7684\u6743\u91cd\u76f4\u63a5\u4e0e\u51b3\u7b56\u6027\u80fd\uff08\u901a\u8fc7\u9057\u61be\u5ea6\u8861\u91cf\uff09\u76f8\u5173\uff0c\u800c\u975e\u4f20\u7edf\u65b9\u6cd5\u4e2d\u6240\u4f9d\u8d56\u7684\u4f30\u8ba1\u51c6\u786e\u6027\uff1b\uff08ii\uff09\u65e0\u9700\u5728\u5386\u53f2\u6570\u636e\u4e0e\u5f53\u524d\u6570\u636e\u4e4b\u95f4\u5efa\u7acb\u53c2\u6570\u5047\u8bbe\uff1b\uff08iii\uff09\u4ec5\u901a\u8fc7\u6c47\u603b\u7edf\u8ba1\u91cf\u5b9e\u73b0\u6570\u636e\u5171\u4eab\uff0c\u800c\u975e\u60a3\u8005\u5c42\u9762\u7684\u6570\u636e\u3002\u6211\u4eec\u7684\u6570\u636e\u6c60\u5316\u7b97\u6cd5\u6846\u67b6\u7edf\u4e00\u4e86\u591a\u79cd\u5f3a\u5316\u5b66\u4e60\u7b97\u6cd5\uff0c\u5e76\u5efa\u7acb\u4e86\u7406\u8bba\u6027\u80fd\u4fdd\u8bc1\uff0c\u91cf\u5316\u4e86\u76f8\u6bd4\u57fa\u51c6\u65b9\u6cd5\uff0c\u901a\u8fc7\u81ea\u9002\u5e94\u6c60\u5316\u8bbe\u8ba1\u6240\u5b9e\u73b0\u7684\u9057\u61be\u5ea6\u8fb9\u754c\u964d\u4f4e\u3002\u6211\u4eec\u901a\u8fc7\u4e00\u4e2a\u5173\u4e8e\u51fa\u9662\u540e\u5e72\u9884\u4ee5\u9884\u9632\u975e\u8ba1\u5212\u518d\u5165\u9662\u7684\u6848\u4f8b\u7814\u7a76\uff0c\u8fdb\u884c\u4e86\u5e7f\u6cdb\u7684\u5b9e\u8bc1\u5b9e\u9a8c\uff0c\u4e3a\u533b\u7597\u7ba1\u7406\u63d0\u4f9b\u4e86\u5b9e\u9645\u6d1e\u5bdf\u3002\u8be5\u7b97\u6cd5\u4f7f\u7ec4\u7ec7\u80fd\u591f\u5229\u7528\u516c\u5171\u6570\u636e\u6216\u5df2\u53d1\u8868\u7684\u7814\u7a76\u6210\u679c\u8fdb\u884c\u60a3\u8005\u7ba1\u7406\uff0c\u5e76\u652f\u6301\u653f\u7b56\u5236\u5b9a\u8005\u63a8\u52a8\u6c47\u603b\u6570\u636e\u5171\u4eab\uff0c\u4ee5\u63d0\u5347\u4eba\u7fa4\u5065\u5eb7\u7ed3\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.09124", "journal": "MS", "title": "The ESG-Innovation Disconnect: Evidence from Green Patenting", "authors": ["Lauren H. Cohen", "Umit G. Gurun", "Quoc H. Nguyen"], "author_details": [{"name": "Lauren H. Cohen", "affiliations": ["Harvard Business School, Boston, Massachusetts 02163; and NBER, Cambridge, Massachusetts 02138"]}, {"name": "Umit G. Gurun", "affiliations": ["University of Texas at Dallas, Richardson, Texas 75080"]}, {"name": "Quoc H. Nguyen", "affiliations": ["DePaul University, Chicago, Illinois 60604"]}], "abstract": "We document that traditional energy firms are key innovators in the United States\u2019 green patent landscape. These firms produce more, and significantly higher-quality, green innovation. In many green technology spaces, they appear to be influential first movers and to produce ongoing foundational aspects of innovation and commercialization on which other alternative energy producers build. They additionally invest significantly in labor and capital to complement these green innovations. These traditional energy firms, however, receive significantly lower environmental, social, and governance (ESG) scores and fund flows and are not rewarded for incremental green innovation. This behavior is consistent with a competitive response by traditional energy firms to preempt obsolescence of current technology by investing in future replacement technologies.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.09124", "title_zh": "ESG\u4e0e\u521b\u65b0\u7684\u8131\u8282\uff1a\u6765\u81ea\u7eff\u8272\u4e13\u5229\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u4f20\u7edf\u80fd\u6e90\u4f01\u4e1a\u5728\u7f8e\u56fd\u7eff\u8272\u4e13\u5229\u9886\u57df\u662f\u5173\u952e\u7684\u521b\u65b0\u8005\u3002\u8fd9\u4e9b\u4f01\u4e1a\u4e0d\u4ec5\u751f\u4ea7\u66f4\u591a\uff0c\u800c\u4e14\u5176\u7eff\u8272\u521b\u65b0\u7684\u8d28\u91cf\u663e\u8457\u66f4\u9ad8\u3002\u5728\u8bb8\u591a\u7eff\u8272\u6280\u672f\u9886\u57df\uff0c\u5b83\u4eec\u4f3c\u4e4e\u8d77\u5230\u4e86\u5148\u9a71\u4f5c\u7528\uff0c\u5e76\u6301\u7eed\u4ea7\u751f\u521b\u65b0\u548c\u5546\u4e1a\u5316\u7684\u57fa\u7840\uff0c\u4e3a\u5176\u4ed6\u66ff\u4ee3\u80fd\u6e90\u751f\u4ea7\u5546\u63d0\u4f9b\u4e86\u652f\u6491\u3002\u6b64\u5916\uff0c\u8fd9\u4e9b\u4f20\u7edf\u80fd\u6e90\u4f01\u4e1a\u8fd8\u5927\u5e45\u6295\u5165\u52b3\u52a8\u548c\u8d44\u672c\u4ee5\u652f\u6301\u8fd9\u4e9b\u7eff\u8272\u521b\u65b0\u3002\u7136\u800c\uff0c\u8fd9\u4e9b\u4f20\u7edf\u80fd\u6e90\u4f01\u4e1a\u83b7\u5f97\u7684\u73af\u5883\u3001\u793e\u4f1a\u548c\u6cbb\u7406\uff08ESG\uff09\u8bc4\u5206\u4ee5\u53ca\u8d44\u91d1\u6d41\u5165\u663e\u8457\u504f\u4f4e\uff0c\u672a\u80fd\u56e0\u5176\u7eff\u8272\u521b\u65b0\u7684\u589e\u91cf\u800c\u83b7\u5f97\u56de\u62a5\u3002\u8fd9\u79cd\u884c\u4e3a\u4e0e\u4f20\u7edf\u80fd\u6e90\u4f01\u4e1a\u4e3a\u9632\u6b62\u73b0\u6709\u6280\u672f\u8fc7\u65f6\u800c\u63d0\u524d\u6295\u8d44\u672a\u6765\u66ff\u4ee3\u6280\u672f\u7684\u5e02\u573a\u7ade\u4e89\u53cd\u5e94\u662f\u4e00\u81f4\u7684\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u672c\u6d41\u52a8"]}, {"doi": "10.1287/mnsc.2024.06863", "journal": "MS", "title": "On the Expansion of Risk Pooling", "authors": ["Michail Anthropelos", "Runhuan Feng", "Seongyoon Kim"], "author_details": [{"name": "Michail Anthropelos", "affiliations": ["Department of Banking and Financial Management, University of Piraeus, Piraeus 185 34, Greece"]}, {"name": "Runhuan Feng", "affiliations": ["Department of Finance, School of Economics and Management, Tsinghua University, Beijing 100190, China"]}, {"name": "Seongyoon Kim", "affiliations": ["Department of Mathematics, University of Illinois at Urbana-Champaign, Urbana, Illinois 61801"]}], "abstract": "Risk pooling has become an increasingly critical tool for managing risks among corporations, institutions, states, and nations, with examples including multinational pooling, decentralized insurance schemes, catastrophe risk pooling, and burden sharing for nuclear accidents. Although there has been a rich literature on such practices, little is known from a theoretical viewpoint regarding the operational strategies of risk pools and, in particular, on issues about the effect of a pool\u2019s expansion on each existing member\u2019s welfare. This paper is the first to explore these issues by establishing different notions of consensus for the expansion of a risk pool: strong consensus, where both existing members and new candidates improve their risk measures due to the pool\u2019s expansion, and weak consensus, which refers to the willingness of existing members to remain in the pool. Under optimal risk sharing for each pool, we show that its properties regarding expansion\u2019s effects depend strongly on the underlying pricing rule. For instance, only with risk-adjusted equilibrium pricing are existing members willing to accept highly risky new members, whereas simple linear pricing excludes such members from the pool. Additionally, the impact of exogenous reinsurance on consensus is analyzed under both pricing rules. The established framework offers valuable managerial insights and policy implications, which we illustrate through two indicative case studies based on real data.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06863", "title_zh": "\u5173\u4e8e\u98ce\u9669\u5206\u644a\u7684\u6269\u5c55\u7814\u7a76", "abstract_zh": "\u98ce\u9669\u5206\u644a\u5df2\u6210\u4e3a\u4f01\u4e1a\u3001\u673a\u6784\u3001\u56fd\u5bb6\u4e4b\u95f4\u7ba1\u7406\u98ce\u9669\u7684\u91cd\u8981\u5de5\u5177\uff0c\u5176\u5e94\u7528\u5b9e\u4f8b\u5305\u62ec\u8de8\u56fd\u98ce\u9669\u5206\u644a\u3001\u5206\u6563\u5316\u4fdd\u9669\u65b9\u6848\u3001\u707e\u96be\u98ce\u9669\u5206\u644a\u4ee5\u53ca\u6838\u4e8b\u6545\u8d23\u4efb\u5206\u62c5\u3002\u5c3d\u7ba1\u5df2\u6709\u5927\u91cf\u5173\u4e8e\u6b64\u7c7b\u5b9e\u8df5\u7684\u6587\u732e\uff0c\u4f46\u4ece\u7406\u8bba\u89d2\u5ea6\u5bf9\u98ce\u9669\u6c60\u7684\u8fd0\u8425\u7b56\u7565\uff0c\u7279\u522b\u662f\u98ce\u9669\u6c60\u6269\u5c55\u5bf9\u73b0\u6709\u6210\u5458\u798f\u5229\u5f71\u54cd\u7684\u95ee\u9898\uff0c\u4ecd\u77e5\u4e4b\u751a\u5c11\u3002\u672c\u6587\u9996\u6b21\u7cfb\u7edf\u63a2\u8ba8\u4e86\u8fd9\u4e9b\u95ee\u9898\uff0c\u901a\u8fc7\u5efa\u7acb\u98ce\u9669\u6c60\u6269\u5c55\u7684\u4e24\u79cd\u5171\u8bc6\u6982\u5ff5\uff1a\u5f3a\u5171\u8bc6\uff0c\u5373\u73b0\u6709\u6210\u5458\u548c\u65b0\u52a0\u5165\u6210\u5458\u7684\u98ce\u9669\u6307\u6807\u5747\u56e0\u6c60\u7684\u6269\u5c55\u800c\u6539\u5584\uff1b\u5f31\u5171\u8bc6\uff0c\u6307\u73b0\u6709\u6210\u5458\u613f\u610f\u7ee7\u7eed\u7559\u5728\u98ce\u9669\u6c60\u4e2d\u7684\u610f\u613f\u3002\u5728\u6bcf\u79cd\u98ce\u9669\u5206\u62c5\u7684\u6700\u4f18\u914d\u7f6e\u4e0b\uff0c\u6211\u4eec\u53d1\u73b0\u98ce\u9669\u6c60\u6269\u5c55\u5bf9\u6210\u5458\u798f\u5229\u7684\u5f71\u54cd\u9ad8\u5ea6\u4f9d\u8d56\u4e8e\u5e95\u5c42\u5b9a\u4ef7\u89c4\u5219\u3002\u4f8b\u5982\uff0c\u53ea\u6709\u5728\u91c7\u7528\u98ce\u9669\u8c03\u6574\u5747\u8861\u5b9a\u4ef7\u7684\u60c5\u51b5\u4e0b\uff0c\u73b0\u6709\u6210\u5458\u624d\u613f\u610f\u63a5\u7eb3\u9ad8\u98ce\u9669\u7684\u65b0\u6210\u5458\uff0c\u800c\u7b80\u5355\u7684\u7ebf\u6027\u5b9a\u4ef7\u5219\u4f1a\u6392\u9664\u6b64\u7c7b\u6210\u5458\u3002\u6b64\u5916\uff0c\u672c\u6587\u8fd8\u5206\u6790\u4e86\u5916\u90e8\u518d\u4fdd\u9669\u5bf9\u4e24\u79cd\u5b9a\u4ef7\u89c4\u5219\u4e0b\u5171\u8bc6\u7684\u5f71\u54cd\u3002\u6240\u5efa\u7acb\u7684\u6846\u67b6\u4e3a\u7ba1\u7406\u51b3\u7b56\u548c\u653f\u7b56\u5236\u5b9a\u63d0\u4f9b\u4e86\u91cd\u8981\u542f\u793a\uff0c\u5e76\u901a\u8fc7\u4e24\u4e2a\u57fa\u4e8e\u771f\u5b9e\u6570\u636e\u7684\u6848\u4f8b\u7814\u7a76\u8fdb\u884c\u4e86\u8bf4\u660e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.01401", "journal": "MS", "title": "Stripping the Discount Curve\u2014A Robust Machine Learning Approach", "authors": ["Damir Filipovi\u0107", "Markus Pelger", "Ye Ye"], "author_details": [{"name": "Damir Filipovi\u0107", "affiliations": ["College of Management, \u00c9cole Polytechnique F\u00e9d\u00e9rale de Lausanne, 1015 Lausanne, Switzerland; and Swiss Finance Institute, 8006 Zurich, Switzerland"]}, {"name": "Markus Pelger", "affiliations": ["Department of Management Science & Engineering, Stanford University, Stanford, California 94305; and National Bureau of Economic Research, Cambridge, Massachusetts 02138"]}, {"name": "Ye Ye", "affiliations": ["Department of Management Science & Engineering, Stanford University, Stanford, California 94305"]}], "abstract": "We introduce a robust, flexible, and easy-to-implement method for estimating the yield curve from treasury securities. Our nonparametric method learns the discount curve in a function space that we motivate by economic principles. We show in an extensive empirical study on U.S. Treasury securities that our method strongly dominates all parametric and nonparametric benchmarks. It achieves substantially smaller out-of-sample yield and pricing errors while being robust to outliers and data selection choices. We attribute the superior performance to the optimal trade-off between flexibility and smoothness, which positions our method as the new standard for yield curve estimation.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.01401", "title_zh": "\u5265\u79bb\u6298\u73b0\u66f2\u7ebf\u2014\u2014\u4e00\u79cd\u7a33\u5065\u7684\u673a\u5668\u5b66\u4e60\u65b9\u6cd5", "abstract_zh": "\u6211\u4eec\u5f15\u5165\u4e86\u4e00\u79cd\u7a33\u5065\u3001\u7075\u6d3b\u4e14\u6613\u4e8e\u5b9e\u73b0\u7684\u65b9\u6cd5\uff0c\u7528\u4e8e\u4ece\u56fd\u503a\u8bc1\u5238\u4e2d\u4f30\u8ba1\u6536\u76ca\u7387\u66f2\u7ebf\u3002\u6211\u4eec\u7684\u975e\u53c2\u6570\u65b9\u6cd5\u5728\u7531\u7ecf\u6d4e\u539f\u7406\u6240\u652f\u6301\u7684\u529f\u80fd\u7a7a\u95f4\u4e2d\u5b66\u4e60\u6298\u73b0\u66f2\u7ebf\u3002\u6211\u4eec\u5728\u5bf9\u7f8e\u56fd\u56fd\u503a\u8bc1\u5238\u7684\u5e7f\u6cdb\u5b9e\u8bc1\u7814\u7a76\u4e2d\u8868\u660e\uff0c\u6211\u4eec\u7684\u65b9\u6cd5\u5728\u6240\u6709\u53c2\u6570\u5316\u548c\u975e\u53c2\u6570\u5316\u57fa\u51c6\u65b9\u6cd5\u4e2d\u8868\u73b0\u663e\u8457\u4f18\u8d8a\uff0c\u80fd\u591f\u5927\u5e45\u964d\u4f4e\u6837\u672c\u5916\u7684\u6536\u76ca\u7387\u548c\u5b9a\u4ef7\u8bef\u5dee\uff0c\u540c\u65f6\u5bf9\u5f02\u5e38\u503c\u548c\u6570\u636e\u9009\u62e9\u5177\u6709\u9c81\u68d2\u6027\u3002\u6211\u4eec\u5f52\u56e0\u4e8e\u65b9\u6cd5\u5728\u7075\u6d3b\u6027\u4e0e\u5e73\u6ed1\u6027\u4e4b\u95f4\u8fbe\u5230\u7684\u6700\u4f18\u6743\u8861\uff0c\u4f7f\u5176\u6210\u4e3a\u6536\u76ca\u7387\u66f2\u7ebf\u4f30\u8ba1\u7684\u65b0\u6807\u51c6\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2024.08304", "journal": "MS", "title": "Escaping Product Market Rivalry Through Innovation", "authors": ["Dandan Xia", "Bruno Cassiman", "David Wehrheim"], "author_details": [{"name": "Dandan Xia", "affiliations": ["School of Economics, Utrecht University, 3584 EC Utrecht, Netherlands"]}, {"name": "Bruno Cassiman", "affiliations": ["Department of Management, Strategy and Innovation, Faculty of Economics and Business, KU Leuven, 3000 Leuven, Belgium; and Strategic Management Department, IESE Business School, University of Navarra, 08034 Barcelona, Spain"]}, {"name": "David Wehrheim", "affiliations": ["Strategic Management Department, IESE Business School, University of Navarra, 08034 Barcelona, Spain"]}], "abstract": "This study leverages advanced text-analysis techniques to investigate how increased product market rivalry, induced by Chinese import competition, affects innovation among incumbent U.S. firms in the electronic and electrical appliance industry. We measure the similarity between the product descriptions of U.S. firms and those of Chinese importers, thus capturing firm-level competitive pressure. Employing a continuous difference-in-differences framework, we compare innovation outcomes of U.S. firms more directly competing with Chinese importers to those facing lower competitive pressure over a five-year period before and after initial Chinese market entry. We find that incumbent U.S. firms significantly increase their quality-weighted patent production, create more new-product patents, and strategically diversify into new technological and business segments when confronted with heightened competition. Our findings highlight the role of import-driven rivalry in stimulating strategic innovation and illustrate how text-based similarity measures can effectively quantify firm-level competition, providing novel methodological tools for strategy scholars.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08304", "title_zh": "\u901a\u8fc7\u521b\u65b0\u6446\u8131\u4ea7\u54c1\u5e02\u573a\u7ade\u4e89", "abstract_zh": "\u672c\u7814\u7a76\u5229\u7528\u5148\u8fdb\u7684\u6587\u672c\u5206\u6790\u6280\u672f\uff0c\u63a2\u8ba8\u4e2d\u56fd\u8fdb\u53e3\u7ade\u4e89\u52a0\u5267\u5e26\u6765\u7684\u4ea7\u54c1\u5e02\u573a\u7ade\u4e89\u5982\u4f55\u5f71\u54cd\u7f8e\u56fd\u7535\u5b50\u548c\u7535\u5668\u884c\u4e1a\u73b0\u6709\u4f01\u4e1a\u7684\u521b\u65b0\u884c\u4e3a\u3002\u6211\u4eec\u901a\u8fc7\u6bd4\u8f83\u7f8e\u56fd\u4f01\u4e1a\u4e0e\u8fdb\u53e3\u4e2d\u56fd\u4f01\u4e1a\u7684\u4ea7\u54c1\u63cf\u8ff0\u76f8\u4f3c\u6027\uff0c\u6355\u6349\u5230\u4f01\u4e1a\u5c42\u9762\u7684\u7ade\u4e89\u538b\u529b\u3002\u91c7\u7528\u8fde\u7eed\u5dee\u5206\u6cd5\uff0c\u6211\u4eec\u5c06\u7f8e\u56fd\u4f01\u4e1a\u76f4\u63a5\u9762\u5bf9\u4e2d\u56fd\u8fdb\u53e3\u7ade\u4e89\u7684\u60c5\u51b5\u4e0e\u9762\u4e34\u8f83\u4f4e\u7ade\u4e89\u538b\u529b\u7684\u4f01\u4e1a\u5728\u521d\u59cb\u4e2d\u56fd\u5e02\u573a\u8fdb\u5165\u524d\u540e\u4e94\u5e74\u5185\u7684\u521b\u65b0\u7ed3\u679c\u8fdb\u884c\u5bf9\u6bd4\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5f53\u9762\u4e34\u66f4\u5f3a\u7ade\u4e89\u538b\u529b\u65f6\uff0c\u73b0\u6709\u7f8e\u56fd\u4f01\u4e1a\u663e\u8457\u589e\u52a0\u4e86\u8d28\u91cf\u52a0\u6743\u7684\u4e13\u5229\u4ea7\u51fa\uff0c\u589e\u52a0\u4e86\u65b0\u4ea7\u54c1\u4e13\u5229\u6570\u91cf\uff0c\u5e76\u6218\u7565\u6027\u5730\u62d3\u5c55\u5230\u65b0\u7684\u6280\u672f\u548c\u4e1a\u52a1\u9886\u57df\u3002\u7814\u7a76\u7ed3\u679c\u51f8\u663e\u4e86\u8fdb\u53e3\u9a71\u52a8\u7684\u7ade\u4e89\u5728\u4fc3\u8fdb\u6218\u7565\u521b\u65b0\u4e2d\u7684\u4f5c\u7528\uff0c\u5e76\u5c55\u793a\u4e86\u57fa\u4e8e\u6587\u672c\u7684\u76f8\u4f3c\u6027\u5ea6\u91cf\u5982\u4f55\u6709\u6548\u91cf\u5316\u4f01\u4e1a\u5c42\u9762\u7684\u7ade\u4e89\uff0c\u4e3a\u6218\u7565\u5b66\u8005\u63d0\u4f9b\u4e86\u65b0\u7684\u65b9\u6cd5\u8bba\u5de5\u5177\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2021.04075", "journal": "MS", "title": "Potty Parity", "authors": ["Setareh Farajollahzadeh", "Ming Hu"], "author_details": [{"name": "Setareh Farajollahzadeh", "affiliations": ["Desautels Faculty of Management, McGill University, Montreal, Quebec H3A 1G5, Canada"]}, {"name": "Ming Hu", "affiliations": ["Rotman School of Management, University of Toronto, Toronto, Ontario M5S 3E6, Canada"]}], "abstract": "We address the issues of unequal restroom access for women and LGBTQ+ individuals, known as the potty parity problem. We propose a utility model in which users consider gender identity, wait time, and safety concerns when choosing restrooms. We evaluate different layouts\u2019 efficiency measured by the total utilities (as in the utilitarian principle) and assess their fairness using the measures of the minimum utility gain (as in the Rawlsian fairness) and the gap between maximum and minimum gains (as in the distributive fairness). When the population is sensitive to gender identity and safety concerns, although it may initially seem intuitive to assume that converting all restrooms to unisex facilities would be efficient and fair due to the pooling of servers and increased flexibility and perceived fairness due to all users standing in the same line, our findings demonstrate that this design can be neither efficient nor fair. In contrast, we show that converting some men\u2019s restrooms to unisex can enhance both efficiency and fairness of access. This highlights that a moderate level of flexibility can outperform a fully flexible system. Moreover, conventional wisdom suggests that removing a restroom unit from the men\u2019s room would negatively impact users from the men\u2019s side. However, our analysis reveals a counterintuitive insight that such a change can lead to a Pareto improvement, benefiting all users involved. We also analytically explore additional benefits of unisex restrooms under different user behaviors and situations and present practically relevant numerical results to support our findings.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2021.04075", "title_zh": "\u5395\u6240\u5e73\u7b49", "abstract_zh": "\u6211\u4eec\u89e3\u51b3\u4e86\u5973\u6027\u548cLGBTQ+\u7fa4\u4f53\u5728\u5982\u5395\u8bbe\u65bd\u8bbf\u95ee\u4e0a\u7684\u4e0d\u5e73\u7b49\u73b0\u8c61\uff0c\u5373\u6240\u8c13\u7684\u5395\u6240\u5e73\u7b49\u95ee\u9898\u3002\u6211\u4eec\u63d0\u51fa\u4e00\u4e2a\u6548\u7528\u6a21\u578b\uff0c\u5176\u4e2d\u7528\u6237\u5728\u9009\u62e9\u536b\u751f\u95f4\u65f6\u4f1a\u8003\u8651\u6027\u522b\u8ba4\u540c\u3001\u7b49\u5f85\u65f6\u95f4\u4ee5\u53ca\u5b89\u5168\u62c5\u5fe7\u3002\u6211\u4eec\u901a\u8fc7\u603b\u6548\u7528\uff08\u7b26\u5408\u529f\u5229\u4e3b\u4e49\u539f\u5219\uff09\u6765\u8861\u91cf\u4e0d\u540c\u5e03\u5c40\u7684\u6548\u7387\uff0c\u5e76\u4f7f\u7528\u6700\u5c0f\u6548\u7528\u63d0\u5347\uff08\u7b26\u5408\u7f57\u5c14\u65af\u5f0f\u516c\u5e73\uff09\u548c\u6700\u5927\u4e0e\u6700\u5c0f\u6536\u76ca\u4e4b\u95f4\u7684\u5dee\u8ddd\uff08\u7b26\u5408\u5206\u914d\u516c\u5e73\uff09\u6765\u8bc4\u4f30\u5176\u516c\u5e73\u6027\u3002\u5f53\u4eba\u7fa4\u5bf9\u6027\u522b\u8ba4\u540c\u548c\u5b89\u5168\u95ee\u9898\u654f\u611f\u65f6\uff0c\u5c3d\u7ba1\u76f4\u89c2\u4e0a\u8ba4\u4e3a\u5c06\u6240\u6709\u536b\u751f\u95f4\u6539\u4e3a\u5171\u7528\u6027\u522b\u8bbe\u65bd\u4f1a\u56e0\u8d44\u6e90\u6c60\u5316\u3001\u4f7f\u7528\u7075\u6d3b\u6027\u63d0\u5347\u4ee5\u53ca\u6240\u6709\u7528\u6237\u5728\u540c\u4e00\u961f\u4f0d\u4e2d\u800c\u663e\u5f97\u66f4\u9ad8\u6548\u4e14\u66f4\u516c\u5e73\uff0c\u4f46\u6211\u4eec\u7684\u7814\u7a76\u53d1\u73b0\uff0c\u8fd9\u79cd\u8bbe\u8ba1\u65e2\u4e0d\u9ad8\u6548\u4e5f\u4e0d\u516c\u5e73\u3002\u76f8\u53cd\uff0c\u6211\u4eec\u8bc1\u660e\u5c06\u90e8\u5206\u7537\u6027\u536b\u751f\u95f4\u6539\u4e3a\u5171\u7528\u6027\u522b\u8bbe\u65bd\u53ef\u4ee5\u540c\u65f6\u63d0\u5347\u6548\u7387\u548c\u516c\u5e73\u6027\u3002\u8fd9\u8868\u660e\u9002\u5ea6\u7684\u7075\u6d3b\u6027\u53ef\u80fd\u4f18\u4e8e\u5b8c\u5168\u7075\u6d3b\u7684\u7cfb\u7edf\u3002\u6b64\u5916\uff0c\u4f20\u7edf\u89c2\u70b9\u8ba4\u4e3a\uff0c\u4ece\u7537\u6027\u536b\u751f\u95f4\u79fb\u9664\u4e00\u4e2a\u536b\u751f\u95f4\u5355\u5143\u4f1a\u5bf9\u7537\u6027\u7528\u6237\u9020\u6210\u8d1f\u9762\u5f71\u54cd\u3002\u7136\u800c\uff0c\u6211\u4eec\u7684\u5206\u6790\u63ed\u793a\u4e86\u4e00\u4e2a\u53cd\u76f4\u89c9\u7684\u53d1\u73b0\uff1a\u8fd9\u79cd\u6539\u53d8\u53ef\u80fd\u5e26\u6765\u5e15\u7d2f\u6258\u6539\u8fdb\uff0c\u4ece\u800c\u60e0\u53ca\u6240\u6709\u76f8\u5173\u7528\u6237\u3002\u6211\u4eec\u8fd8\u4ece\u4e0d\u540c\u7528\u6237\u884c\u4e3a\u548c\u60c5\u5883\u4e0b\u5206\u6790\u4e86\u5171\u7528\u536b\u751f\u95f4\u5e26\u6765\u7684\u989d\u5916\u597d\u5904\uff0c\u5e76\u63d0\u4f9b\u4e86\u5177\u6709\u5b9e\u9645\u610f\u4e49\u7684\u6570\u503c\u7ed3\u679c\u4ee5\u652f\u6301\u6211\u4eec\u7684\u53d1\u73b0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2022.00817", "journal": "MS", "title": "What Do Trade Allowances Look Like? Evidence from Actual Payments to a Big-Box Retailer", "authors": ["Andr\u00e9s Elberg", "Carlos Noton"], "author_details": [{"name": "Andr\u00e9s Elberg", "affiliations": ["School of Management, Pontificia Universidad Cat\u00f3lica de Chile, 7820436 Santiago, Chile"]}, {"name": "Carlos Noton", "affiliations": ["School of Management, Pontificia Universidad Cat\u00f3lica de Chile, 7820436 Santiago, Chile"]}], "abstract": "We document key features of trade allowances\u2014a major component of the contracts between large retailers and manufacturers\u2014using a unique panel data set on allowance payments negotiated between two supermarket chains owned by a large retailer and its suppliers over a two-year period. We show that trade allowances are large in magnitude, are paid by the vast majority of suppliers, and vary substantially over categories and, especially, across suppliers within categories. We further study trade allowance behavior along key dimensions of the manufacturer\u2013retailer relationship. First, we report important interdependencies between allowances paid by multicategory suppliers across different categories, suggesting that single-category analysis of manufacturer\u2013retailer interactions may be misleading. Second, we show that dedicated private label manufacturers do pay allowances, and that dual branders (i.e., national brand manufacturers who in addition produce private labels) tend to pay lower allowances than fully national brand manufacturers. Third, we examine the relationship between allowance payments and price promotional activities and find that price and nonprice incentives tend to be treated as substitutes. Fourth, we document a positive relationship between allowance payments and prices, suggesting that trade allowances do not mitigate the double marginalization problem. Finally, the evidence suggests that both market power and efficiency aspects are at play in the explanation of trade allowances.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2022.00817", "title_zh": "\u8d38\u6613\u8ba9\u5229\u7a76\u7adf\u957f\u4ec0\u4e48\u6837\uff1f\u6765\u81ea\u4e00\u5bb6\u5927\u578b\u96f6\u552e\u4f01\u4e1a\u4e0e\u4f9b\u5e94\u5546\u5b9e\u9645\u4ed8\u6b3e\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u5229\u7528\u4e00\u4e2a\u72ec\u7279\u7684\u9762\u677f\u6570\u636e\u96c6\uff0c\u8be5\u6570\u636e\u96c6\u8bb0\u5f55\u4e86\u4e24\u5bb6\u7531\u5927\u578b\u96f6\u552e\u5546\u62e5\u6709\u7684\u8d85\u5e02\u8fde\u9501\u4f01\u4e1a\u4e0e\u5176\u4f9b\u5e94\u5546\u5728\u4e24\u5e74\u671f\u95f4\u5185\u534f\u5546\u7684\u8ba9\u5229\u652f\u4ed8\u60c5\u51b5\uff0c\u8be6\u7ec6\u63cf\u8ff0\u4e86\u8d38\u6613\u8ba9\u5229\u2014\u2014\u96f6\u552e\u4f01\u4e1a\u4e0e\u5236\u9020\u5546\u4e4b\u95f4\u5408\u540c\u4e2d\u7684\u91cd\u8981\u7ec4\u6210\u90e8\u5206\u2014\u2014\u7684\u5173\u952e\u7279\u5f81\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8d38\u6613\u8ba9\u5229\u7684\u89c4\u6a21\u5f88\u5927\uff0c\u7edd\u5927\u591a\u6570\u4f9b\u5e94\u5546\u90fd\u4f1a\u652f\u4ed8\u8ba9\u5229\uff0c\u5e76\u4e14\u5728\u4e0d\u540c\u54c1\u7c7b\u4e4b\u95f4\u4ee5\u53ca\u540c\u4e00\u54c1\u7c7b\u5185\u7684\u4e0d\u540c\u4f9b\u5e94\u5546\u4e4b\u95f4\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u4ece\u5236\u9020\u5546\u4e0e\u96f6\u552e\u5546\u5173\u7cfb\u7684\u5173\u952e\u7ef4\u5ea6\u7814\u7a76\u4e86\u8d38\u6613\u8ba9\u5229\u7684\u884c\u4e3a\u3002\u9996\u5148\uff0c\u6211\u4eec\u62a5\u544a\u4e86\u591a\u54c1\u7c7b\u4f9b\u5e94\u5546\u5728\u4e0d\u540c\u54c1\u7c7b\u95f4\u652f\u4ed8\u8ba9\u5229\u7684\u91cd\u8981\u76f8\u4e92\u4f9d\u8d56\u6027\uff0c\u8868\u660e\u4ec5\u5bf9\u5355\u54c1\u7c7b\u8fdb\u884c\u5236\u9020\u5546\u4e0e\u96f6\u552e\u5546\u4e92\u52a8\u5206\u6790\u53ef\u80fd\u662f\u8bef\u5bfc\u6027\u7684\u3002\u5176\u6b21\uff0c\u6211\u4eec\u53d1\u73b0\u4e13\u95e8\u751f\u4ea7\u81ea\u6709\u54c1\u724c\u7684\u5236\u9020\u5546\u4e5f\u4f1a\u652f\u4ed8\u8ba9\u5229\uff0c\u800c\u540c\u65f6\u751f\u4ea7\u81ea\u6709\u54c1\u724c\u548c\u5168\u56fd\u54c1\u724c\u4ea7\u54c1\u7684\u5236\u9020\u5546\uff08\u5373\u53cc\u54c1\u724c\u5236\u9020\u5546\uff09\u652f\u4ed8\u7684\u8ba9\u5229\u4f4e\u4e8e\u5b8c\u5168\u751f\u4ea7\u5168\u56fd\u54c1\u724c\u7684\u5236\u9020\u5546\u3002\u7b2c\u4e09\uff0c\u6211\u4eec\u8003\u5bdf\u4e86\u8ba9\u5229\u652f\u4ed8\u4e0e\u4ef7\u683c\u4fc3\u9500\u6d3b\u52a8\u4e4b\u95f4\u7684\u5173\u7cfb\uff0c\u53d1\u73b0\u4ef7\u683c\u548c\u975e\u4ef7\u683c\u6fc0\u52b1\u5f80\u5f80\u88ab\u89c6\u4e3a\u66ff\u4ee3\u54c1\u3002\u7b2c\u56db\uff0c\u6211\u4eec\u53d1\u73b0\u8ba9\u5229\u652f\u4ed8\u4e0e\u4ef7\u683c\u4e4b\u95f4\u5b58\u5728\u6b63\u5411\u5173\u7cfb\uff0c\u8868\u660e\u8d38\u6613\u8ba9\u5229\u5e76\u672a\u7f13\u89e3\u53cc\u91cd\u52a0\u4ef7\u95ee\u9898\u3002\u6700\u540e\uff0c\u8bc1\u636e\u8868\u660e\uff0c\u5e02\u573a\u529b\u91cf\u548c\u6548\u7387\u56e0\u7d20\u5728\u89e3\u91ca\u8d38\u6613\u8ba9\u5229\u65b9\u9762\u5747\u53d1\u6325\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1287/mnsc.2023.03040", "journal": "MS", "title": "Regulatory Risk Perception and Small Business Lending", "authors": ["Joseph Kalmenovitz", "Siddharth Vij"], "author_details": [{"name": "Joseph Kalmenovitz", "affiliations": ["Simon Business School, University of Rochester, Rochester, New York 14620"]}, {"name": "Siddharth Vij", "affiliations": ["Terry College of Business, University of Georgia, Athens, Georgia 30605"]}], "abstract": "We uncover a significant friction in small business lending: perception of risk by Small Business Administration (SBA) employees. Using novel data on SBA employees transferring across offices, we find that more current defaults on SBA loans in their previous location reduce SBA loans and job creation in their current location. The effect is independent of local economic conditions and the informational content of the nonlocal defaults, suggesting that SBA employees update their risk assessment irrationally. Our results are the first to document that regulators\u2019 misperception of economic conditions affects the ability of small businesses to obtain access to finance.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.03040", "title_zh": "\u76d1\u7ba1\u98ce\u9669\u611f\u77e5\u4e0e\u5c0f\u5fae\u4f01\u4e1a\u8d37\u6b3e", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\u4e86\u5c0f\u5fae\u4f01\u4e1a\u8d37\u6b3e\u4e2d\u7684\u4e00\u4e2a\u91cd\u8981\u969c\u788d\uff1a\u7f8e\u56fd\u5c0f\u4f01\u4e1a\u7ba1\u7406\u5c40\uff08SBA\uff09\u5458\u5de5\u5bf9\u98ce\u9669\u7684\u611f\u77e5\u3002\u5229\u7528SBA\u5458\u5de5\u8de8\u529e\u516c\u5ba4\u8c03\u52a8\u7684\u65b0\u578b\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5458\u5de5\u524d\u4e00\u529e\u516c\u5730\u70b9\u7684SBA\u8d37\u6b3e\u5f53\u524d\u8fdd\u7ea6\u7387\u8d8a\u9ad8\uff0c\u5176\u5f53\u524d\u529e\u516c\u5730\u70b9\u7684SBA\u8d37\u6b3e\u53d1\u653e\u548c\u5c31\u4e1a\u521b\u9020\u5c31\u4f1a\u51cf\u5c11\u3002\u8fd9\u4e00\u6548\u5e94\u4e0e\u5f53\u5730\u7ecf\u6d4e\u72b6\u51b5\u4ee5\u53ca\u975e\u672c\u5730\u8fdd\u7ea6\u4fe1\u606f\u7684\u5185\u5bb9\u65e0\u5173\uff0c\u8868\u660eSBA\u5458\u5de5\u5728\u66f4\u65b0\u98ce\u9669\u8bc4\u4f30\u65f6\u5b58\u5728\u975e\u7406\u6027\u884c\u4e3a\u3002\u672c\u7814\u7a76\u662f\u9996\u6b21\u8bc1\u5b9e\u76d1\u7ba1\u8005\u5bf9\u7ecf\u6d4e\u72b6\u51b5\u7684\u8bef\u5224\u4f1a\u5f71\u54cd\u5c0f\u5fae\u4f01\u4e1a\u83b7\u53d6\u878d\u8d44\u7684\u80fd\u529b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.04322", "journal": "MS", "title": "Long-Term Pay for Performance: Cumulative Evidence over CEO Tenure", "authors": ["Kalash Jain", "Shivaram Rajgopal", "Alfred Rappaport", "M. J. Song"], "author_details": [{"name": "Kalash Jain", "affiliations": ["Columbia Business School, Columbia University, New York, New York 10027"]}, {"name": "Shivaram Rajgopal", "affiliations": ["Columbia Business School, Columbia University, New York, New York 10027"]}, {"name": "Alfred Rappaport", "affiliations": ["Kellogg School of Management, Northwestern University, Evanston, Illinois 60208"]}, {"name": "M. J. Song", "affiliations": ["Columbia Business School, Columbia University, New York, New York 10027"]}], "abstract": "This study revisits the CEO pay-for-performance relation using two methodological innovations designed to address well-known measurement challenges. First, we aggregate pay and performance over the CEO\u2019s entire tenure, allowing us to account for ex post settling up in pay. Second, we use realized compensation rather than ex ante estimates to better capture the actual economic rewards that CEOs receive. We find strong evidence of pay for performance in the full sample with a magnitude 2\u201310 times greater than that reported in previous studies. However, the pay-for-performance relation is asymmetric. CEOs who outperform their peer firms exhibit strong pay-for-performance sensitivity; those who underperform do not. This asymmetry arises because boards offset weak performance with incremental equity grants, undoing the mechanical correlation that results from declining stock prices. Finally, we show that underperforming CEOs are significantly more likely to be dismissed, suggesting that turnover, rather than lower pay, could be a disciplinary mechanism used by boards. Collectively, our findings demonstrate that tenure-aggregated realized pay better reveals how boards structure incentives and accountability over the full horizon of a CEO\u2019s leadership.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.04322", "title_zh": "\u957f\u671f\u7ee9\u6548\u85aa\u916c\uff1aCEO\u4efb\u671f\u5185\u7684\u7d2f\u79ef\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u91cd\u65b0\u5ba1\u89c6\u4e86CEO\u85aa\u916c\u4e0e\u7ee9\u6548\u4e4b\u95f4\u7684\u5173\u7cfb\uff0c\u91c7\u7528\u4e86\u4e24\u79cd\u65b9\u6cd5\u8bba\u521b\u65b0\uff0c\u4ee5\u5e94\u5bf9\u4f17\u6240\u5468\u77e5\u7684\u6d4b\u91cf\u6311\u6218\u3002\u9996\u5148\uff0c\u6211\u4eec\u5c06\u85aa\u916c\u548c\u7ee9\u6548\u5728CEO\u6574\u4e2a\u4efb\u671f\u8303\u56f4\u5185\u8fdb\u884c\u6c47\u603b\uff0c\u4ece\u800c\u80fd\u591f\u8003\u8651\u4e8b\u540e\u85aa\u916c\u8c03\u6574\u3002\u5176\u6b21\uff0c\u6211\u4eec\u4f7f\u7528\u5b9e\u9645\u83b7\u5f97\u7684\u85aa\u916c\u800c\u975e\u4e8b\u524d\u4f30\u8ba1\u503c\uff0c\u4ee5\u66f4\u51c6\u786e\u5730\u53cd\u6620CEO\u5b9e\u9645\u83b7\u5f97\u7684\u7ecf\u6d4e\u56de\u62a5\u3002\u6211\u4eec\u5728\u5168\u6837\u672c\u4e2d\u53d1\u73b0\u4e86\u5f3a\u6709\u529b\u7684\u7ee9\u6548\u85aa\u916c\u5173\u7cfb\uff0c\u5176\u5f3a\u5ea6\u6bd4\u4ee5\u5f80\u7814\u7a76\u62a5\u544a\u7684\u9ad8\u51fa2\u81f310\u500d\u3002\u7136\u800c\uff0c\u8fd9\u4e00\u7ee9\u6548\u85aa\u916c\u5173\u7cfb\u662f\u4e0d\u5bf9\u79f0\u7684\uff1a\u8868\u73b0\u4f18\u4e8e\u540c\u884c\u4f01\u4e1a\u7684CEO\u8868\u73b0\u51fa\u5f3a\u70c8\u7684\u7ee9\u6548\u85aa\u916c\u654f\u611f\u6027\uff1b\u800c\u8868\u73b0\u4e0d\u4f73\u7684CEO\u5219\u6ca1\u6709\u8fd9\u79cd\u654f\u611f\u6027\u3002\u8fd9\u79cd\u4e0d\u5bf9\u79f0\u6027\u6e90\u4e8e\u8463\u4e8b\u4f1a\u901a\u8fc7\u589e\u52a0\u80a1\u6743\u6388\u4e88\u6765\u5f25\u8865\u4e1a\u7ee9\u4e0d\u8db3\uff0c\u4ece\u800c\u62b5\u6d88\u4e86\u56e0\u80a1\u4ef7\u4e0b\u8dcc\u800c\u4ea7\u751f\u7684\u673a\u68b0\u6027\u76f8\u5173\u6027\u3002\u6700\u540e\uff0c\u6211\u4eec\u53d1\u73b0\u8868\u73b0\u4e0d\u4f73\u7684CEO\u88ab\u89e3\u96c7\u7684\u6982\u7387\u663e\u8457\u66f4\u9ad8\uff0c\u8fd9\u8868\u660e\u8463\u4e8b\u4f1a\u53ef\u80fd\u66f4\u591a\u4f9d\u8d56\u4eba\u5458\u53d8\u52a8\u800c\u975e\u964d\u4f4e\u85aa\u916c\u4f5c\u4e3a\u7eaa\u5f8b\u673a\u5236\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u5c06\u4efb\u671f\u5185\u7684\u5b9e\u9645\u85aa\u916c\u8fdb\u884c\u6c47\u603b\uff0c\u66f4\u80fd\u63ed\u793a\u8463\u4e8b\u4f1a\u5982\u4f55\u5728CEO\u9886\u5bfc\u7684\u6574\u4e2a\u5468\u671f\u5185\u8bbe\u8ba1\u6fc0\u52b1\u673a\u5236\u548c\u95ee\u8d23\u673a\u5236\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2022.01745", "journal": "MS", "title": "Growing up Under Mao and Deng: On Politician Ideology and Corporate Policies", "authors": ["Hao Liang", "Rong Wang", "Haikun Zhu"], "author_details": [{"name": "Hao Liang", "affiliations": ["Lee Kong Chian School of Business, Singapore Management University, Singapore 178899"]}, {"name": "Rong Wang", "affiliations": ["Lee Kong Chian School of Business, Singapore Management University, Singapore 178899"]}, {"name": "Haikun Zhu", "affiliations": ["China Europe International Business School (CEIBS), Shanghai 201206, China"]}], "abstract": "We provide firm-level evidence on how politicians\u2019 ideologies shape economic outcomes, using a unique setting of ideological discontinuity in China, transitioning from Maoism to Dengism around 1978. We find that ideological exposure during a politician\u2019s early adulthood has a lasting impact on contemporary firm policies in their city. Firms governed by \u201cMaoist mayors\u201d show greater stakeholder spending, lower pay inequality, and less internationalization compared with those governed by \u201cDengist mayors.\u201d Further evidence suggests that politicians\u2019 ideologies influence corporate behaviors through nonpolicy channels, and these results cannot be fully explained by selection bias, endogenous matching, or the age of the mayor.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2022.01745", "title_zh": "\u5728\u6bdb\u6cfd\u4e1c\u548c\u9093\u5c0f\u5e73\u65f6\u4ee3\u6210\u957f\uff1a\u5173\u4e8e\u653f\u6cbb\u5bb6\u610f\u8bc6\u5f62\u6001\u5bf9\u4f01\u4e1a\u653f\u7b56\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u5229\u7528\u4e2d\u56fd\u4ece\u6bdb\u6cfd\u4e1c\u601d\u60f3\u5411\u9093\u5c0f\u5e73\u601d\u60f3\u8fc7\u6e21\uff08\u7ea61978\u5e74\uff09\u8fd9\u4e00\u72ec\u7279\u7684\u610f\u8bc6\u5f62\u6001\u65ad\u5c42\u80cc\u666f\uff0c\u63d0\u4f9b\u4e86\u4f01\u4e1a\u5c42\u9762\u7684\u8bc1\u636e\uff0c\u8bf4\u660e\u653f\u6cbb\u5bb6\u7684\u610f\u8bc6\u5f62\u6001\u5982\u4f55\u5f71\u54cd\u7ecf\u6d4e\u7ed3\u679c\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u653f\u6cbb\u5bb6\u5728\u9752\u5e74\u65f6\u671f\u6240\u63a5\u89e6\u7684\u610f\u8bc6\u5f62\u6001\u5bf9\u5176\u6240\u5728\u57ce\u5e02\u5f53\u524d\u4f01\u4e1a\u7684\u653f\u7b56\u5177\u6709\u6301\u4e45\u5f71\u54cd\u3002\u7531\u2018\u6bdb\u6cfd\u4e1c\u6d3e\u5e02\u957f\u2019\u7ba1\u7406\u7684\u4f01\u4e1a\u8868\u73b0\u51fa\u66f4\u9ad8\u7684\u5229\u76ca\u76f8\u5173\u8005\u652f\u51fa\u3001\u66f4\u4f4e\u7684\u85aa\u916c\u4e0d\u5e73\u7b49\u4ee5\u53ca\u66f4\u5c11\u7684\u56fd\u9645\u5316\u7a0b\u5ea6\uff0c\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u7531\u2018\u9093\u5c0f\u5e73\u6d3e\u5e02\u957f\u2019\u7ba1\u7406\u7684\u4f01\u4e1a\u5219\u8868\u73b0\u5f97\u66f4\u4e3a\u56fd\u9645\u5316\u3002\u8fdb\u4e00\u6b65\u7684\u8bc1\u636e\u8868\u660e\uff0c\u653f\u6cbb\u5bb6\u7684\u610f\u8bc6\u5f62\u6001\u901a\u8fc7\u975e\u653f\u7b56\u6e20\u9053\u5f71\u54cd\u4f01\u4e1a\u884c\u4e3a\uff0c\u4e14\u8fd9\u4e9b\u7ed3\u679c\u65e0\u6cd5\u88ab\u9009\u62e9\u504f\u5dee\u3001\u5185\u751f\u5339\u914d\u6216\u5e02\u957f\u5e74\u9f84\u7b49\u56e0\u7d20\u5b8c\u5168\u89e3\u91ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.07315", "journal": "MS", "title": "The Zombie Lending Channel of Monetary Policy", "authors": ["Bruno Albuquerque", "Chenyu (Sophia) Mao"], "author_details": [{"name": "Bruno Albuquerque", "affiliations": ["International Monetary Fund, Washington, District of Columbia 20431; and Centre for Business and Economics Research (CeBER), University of Coimbra, Coimbra 3004-531, Portugal"]}, {"name": "Chenyu (Sophia) Mao", "affiliations": ["World Bank, Washington, District of Columbia 20433"]}], "abstract": "We identify a new channel in the monetary policy transmission to nonfinancial corporates\u2014the zombie lending channel. Our findings show that unviable and unproductive zombie firms are less affected by contractionary monetary policy relative to other firms because of a more muted tightening in credit conditions. We rationalize this result with a strengthening in evergreening motives when interest rates rise: lenders face incentives to extend loans to zombies to prevent them from defaulting. Strengthening banks\u2019 balance sheets and curbing risky lending behavior could help mitigate zombie lending practices when financial conditions tighten.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07315", "title_zh": "\u8d27\u5e01\u653f\u7b56\u5411\u975e\u91d1\u878d\u4f01\u4e1a\u4f20\u5bfc\u7684\u50f5\u5c38\u8d37\u6b3e\u6e20\u9053", "abstract_zh": "\u6211\u4eec\u8bc6\u522b\u51fa\u8d27\u5e01\u653f\u7b56\u5411\u975e\u91d1\u878d\u4f01\u4e1a\u4f20\u5bfc\u7684\u4e00\u4e2a\u65b0\u6e20\u9053\u2014\u2014\u50f5\u5c38\u8d37\u6b3e\u6e20\u9053\u3002\u6211\u4eec\u7684\u7814\u7a76\u53d1\u73b0\uff0c\u4e0d\u53ef\u6301\u7eed\u4e14\u4f4e\u6548\u7684\u50f5\u5c38\u4f01\u4e1a\u76f8\u5bf9\u4e8e\u5176\u4ed6\u4f01\u4e1a\u5bf9\u7d27\u7f29\u6027\u8d27\u5e01\u653f\u7b56\u7684\u53cd\u5e94\u66f4\u5f31\uff0c\u56e0\u4e3a\u5176\u4fe1\u8d37\u6761\u4ef6\u7684\u6536\u7d27\u7a0b\u5ea6\u66f4\u4e3a\u6e29\u548c\u3002\u6211\u4eec\u901a\u8fc7\u5229\u7387\u4e0a\u5347\u65f6\u8d37\u6b3e\u65b9\u5b58\u5728\u5ef6\u957f\u8d37\u6b3e\u4ee5\u9632\u6b62\u50f5\u5c38\u4f01\u4e1a\u8fdd\u7ea6\u7684\u52a8\u673a\u6765\u89e3\u91ca\u8fd9\u4e00\u73b0\u8c61\u3002\u5728\u91d1\u878d\u6761\u4ef6\u6536\u7d27\u65f6\uff0c\u52a0\u5f3a\u94f6\u884c\u8d44\u4ea7\u8d1f\u503a\u8868\u7684\u7a33\u5065\u6027\u5e76\u904f\u5236\u9ad8\u98ce\u9669\u653e\u8d37\u884c\u4e3a\uff0c\u6709\u52a9\u4e8e\u7f13\u89e3\u50f5\u5c38\u8d37\u6b3e\u73b0\u8c61\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.08559", "journal": "MS", "title": "Board Fiduciary Duty, Communication, and Compensation", "authors": ["Lin Qiu"], "author_details": [{"name": "Lin Qiu", "affiliations": ["Purdue University, West Lafayette, Indiana 47907"]}], "abstract": "This paper examines the consequences of tightening board fiduciary duty rules in a setting that combines agency frictions and strategic communication. A firm needs to tailor an investment decision (e.g., mergers and acquisitions) to the state of the world. The CEO is privately informed about the state but is an empire builder. The board can learn about the firm\u2019s state through exerting a costly information gathering effort or through communication. In equilibrium, the board values communication more than the shareholders do. By granting the CEO a larger equity stake, the board fosters communication, and this reduces its need for costly information acquisition. Anticipating this, rational shareholders can adjust the board\u2019s equity stake to boost its effort incentive. Surprisingly, the benefit to shareholders from stricter fiduciary duty rules is nonmonotonic in CEO agency conflicts and can diminish as the severity of agency conflict increases. Moreover, welfare analysis shows that strengthening fiduciary duty rules can weaken board effort incentives and reduce total equity value and overall welfare. Paradoxically, these efficiency losses occur when CEO agency conflicts are severe\u2014the very situations in which stringent fiduciary duty rules are typically introduced to address such concerns. These findings suggest unintended consequences of strengthening board fiduciary duty rules and highlight the importance of taking boards as strategic, self-interested entities.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08559", "title_zh": "\u8463\u4e8b\u4f1a\u5fe0\u8bda\u4e49\u52a1\u3001\u6c9f\u901a\u4e0e\u85aa\u916c", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5728\u7ed3\u5408\u4ee3\u7406\u6469\u64e6\u548c\u6218\u7565\u6c9f\u901a\u7684\u73af\u5883\u4e2d\uff0c\u6536\u7d27\u8463\u4e8b\u4f1a\u5fe0\u8bda\u4e49\u52a1\u89c4\u5219\u6240\u4ea7\u751f\u7684\u540e\u679c\u3002\u4f01\u4e1a\u9700\u8981\u6839\u636e\u4e16\u754c\u72b6\u6001\u8c03\u6574\u6295\u8d44\u51b3\u7b56\uff08\u4f8b\u5982\u5e76\u8d2d\uff09\u3002CEO\u4e86\u89e3\u4e16\u754c\u72b6\u6001\uff0c\u4f46\u5c5e\u4e8e\u4f01\u4e1a\u6269\u5f20\u578b\u4eba\u7269\u3002\u8463\u4e8b\u4f1a\u53ef\u4ee5\u901a\u8fc7\u8fdb\u884c\u6210\u672c\u9ad8\u6602\u7684\u4fe1\u606f\u6536\u96c6\u52aa\u529b\u6216\u901a\u8fc7\u6c9f\u901a\u6765\u4e86\u89e3\u4f01\u4e1a\u7684\u72b6\u6001\u3002\u5728\u5747\u8861\u72b6\u6001\u4e0b\uff0c\u8463\u4e8b\u4f1a\u6bd4\u80a1\u4e1c\u66f4\u91cd\u89c6\u6c9f\u901a\u3002\u901a\u8fc7\u7ed9\u4e88CEO\u66f4\u5927\u7684\u80a1\u6743\u4efd\u989d\uff0c\u8463\u4e8b\u4f1a\u4fc3\u8fdb\u4e86\u6c9f\u901a\uff0c\u4ece\u800c\u51cf\u5c11\u4e86\u5176\u8fdb\u884c\u6602\u8d35\u4fe1\u606f\u83b7\u53d6\u7684\u9700\u6c42\u3002\u80a1\u4e1c\u9884\u89c1\u5230\u8fd9\u4e00\u60c5\u51b5\uff0c\u53ef\u4ee5\u76f8\u5e94\u8c03\u6574\u8463\u4e8b\u4f1a\u7684\u80a1\u6743\u4efd\u989d\u4ee5\u589e\u5f3a\u5176\u52aa\u529b\u6fc0\u52b1\u3002\u4ee4\u4eba\u60ca\u8bb6\u7684\u662f\uff0c\u80a1\u4e1c\u4ece\u66f4\u4e25\u683c\u7684\u5fe0\u8bda\u4e49\u52a1\u89c4\u5219\u4e2d\u83b7\u5f97\u7684\u6536\u76ca\u5728CEO\u4ee3\u7406\u51b2\u7a81\u52a0\u5267\u65f6\u5e76\u975e\u5355\u8c03\u9012\u589e\uff0c\u53cd\u800c\u53ef\u80fd\u968f\u7740\u4ee3\u7406\u51b2\u7a81\u4e25\u91cd\u7a0b\u5ea6\u7684\u589e\u52a0\u800c\u51cf\u5c11\u3002\u6b64\u5916\uff0c\u798f\u5229\u5206\u6790\u8868\u660e\uff0c\u52a0\u5f3a\u5fe0\u8bda\u4e49\u52a1\u89c4\u5219\u53ef\u80fd\u4f1a\u524a\u5f31\u8463\u4e8b\u4f1a\u7684\u52aa\u529b\u6fc0\u52b1\uff0c\u964d\u4f4e\u6574\u4f53\u80a1\u6743\u4ef7\u503c\u548c\u603b\u4f53\u798f\u5229\u3002\u6096\u8bba\u7684\u662f\uff0c\u8fd9\u4e9b\u6548\u7387\u635f\u5931\u51fa\u73b0\u5728CEO\u4ee3\u7406\u51b2\u7a81\u4e25\u91cd\u65f6\u2014\u2014\u800c\u8fd9\u6b63\u662f\u901a\u5e38\u5f15\u5165\u4e25\u683c\u5fe0\u8bda\u4e49\u52a1\u89c4\u5219\u4ee5\u5e94\u5bf9\u6b64\u7c7b\u95ee\u9898\u7684\u573a\u666f\u3002\u8fd9\u4e9b\u53d1\u73b0\u63ed\u793a\u4e86\u52a0\u5f3a\u8463\u4e8b\u4f1a\u5fe0\u8bda\u4e49\u52a1\u89c4\u5219\u53ef\u80fd\u5e26\u6765\u7684\u610f\u5916\u540e\u679c\uff0c\u5e76\u5f3a\u8c03\u4e86\u5c06\u8463\u4e8b\u4f1a\u89c6\u4e3a\u5177\u6709\u6218\u7565\u6027\u548c\u81ea\u6211\u5229\u76ca\u7684\u5b9e\u4f53\u7684\u91cd\u8981\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1287/mnsc.2023.02789", "journal": "MS", "title": "Political Consumerism and the Emergence of Rare Information on User-Generated Content Platforms", "authors": ["Uttara M. Ananthakrishnan", "Xingchen Xu", "Maria Mitkina", "Yong Tan"], "author_details": [{"name": "Uttara M. Ananthakrishnan", "affiliations": ["Michael G. Foster School of Business, University of Washington, Seattle, Washington 98195"]}, {"name": "Xingchen Xu", "affiliations": ["Michael G. Foster School of Business, University of Washington, Seattle, Washington 98195"]}, {"name": "Maria Mitkina", "affiliations": ["Uber Technologies, Inc., San Francisco, California 94158"]}, {"name": "Yong Tan", "affiliations": ["Michael G. Foster School of Business, University of Washington, Seattle, Washington 98195"]}], "abstract": "Consumers are increasingly supporting businesses and brands that align closely with their values, engaging in acts of political consumerism. Despite the growing demand to support minority-owned businesses, discovering these establishments through traditional channels remains challenging. In this study, we examine whether and how online reviews facilitate the discovery of Black-owned businesses. We leverage GPS-enabled foot traffic data, hand-collected data from a directory of Black-owned restaurants, online reviews from Yelp.com, and zip code-level demographic data to understand the potential mechanisms driving this behavior. Our results suggest that Black-owned restaurants receiving reviews mentioning Black ownership as a product attribute experience about a 10% increase in foot traffic compared with those that do not receive such reviews. Furthermore, we find that reviews mentioning Black ownership primarily benefit Black-owned restaurants located in cities with lower segregation and racial isolation and those where minority ownership is not easily inferable from the kind of cuisine served. Our findings also indicate that online reviews mentioning Black ownership increase foot traffic to Black-owned restaurants by enhancing interracial exposure. Non-White consumers who patronize these restaurants experience an increased likelihood of encountering White consumers after the restaurants receive a review mentioning Black ownership. Collectively, our results demonstrate the value of user-generated content in enabling political consumerism, even without targeted interventions from digital platforms or voluntary disclosure of race by business owners.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.02789", "title_zh": "\u653f\u6cbb\u6d88\u8d39\u4e3b\u4e49\u4e0e\u7528\u6237\u751f\u6210\u5185\u5bb9\u5e73\u53f0\u4e2d\u7a00\u6709\u4fe1\u606f\u7684\u51fa\u73b0", "abstract_zh": "\u6d88\u8d39\u8005\u8d8a\u6765\u8d8a\u503e\u5411\u4e8e\u652f\u6301\u4e0e\u81ea\u8eab\u4ef7\u503c\u89c2\u9ad8\u5ea6\u5951\u5408\u7684\u4f01\u4e1a\u548c\u54c1\u724c\uff0c\u4ece\u800c\u8868\u73b0\u51fa\u653f\u6cbb\u6d88\u8d39\u4e3b\u4e49\u7684\u884c\u4e3a\u3002\u5c3d\u7ba1\u793e\u4f1a\u5bf9\u652f\u6301\u5c11\u6570\u65cf\u88d4\u62e5\u6709\u7684\u4f01\u4e1a\u7684\u9700\u6c42\u65e5\u76ca\u589e\u957f\uff0c\u4f46\u901a\u8fc7\u4f20\u7edf\u6e20\u9053\u53d1\u73b0\u8fd9\u4e9b\u4f01\u4e1a\u4ecd\u7136\u9762\u4e34\u5de8\u5927\u6311\u6218\u3002\u672c\u7814\u7a76\u63a2\u8ba8\u5728\u7ebf\u8bc4\u8bba\u662f\u5426\u4ee5\u53ca\u5982\u4f55\u4fc3\u8fdb\u5bf9\u9ed1\u4eba\u62e5\u6709\u7684\u4f01\u4e1a\u7684\u53d1\u73b0\u3002\u6211\u4eec\u7ed3\u5408GPS\u5b9a\u4f4d\u7684\u5230\u5e97\u6d41\u91cf\u6570\u636e\u3001\u624b\u5de5\u6536\u96c6\u7684\u9ed1\u4eba\u62e5\u6709\u7684\u9910\u5385\u76ee\u5f55\u6570\u636e\u3001\u6765\u81eaYelp.com\u7684\u5728\u7ebf\u8bc4\u8bba\u4ee5\u53ca\u6309\u90ae\u653f\u7f16\u7801\u5212\u5206\u7684\u4eba\u53e3\u7edf\u8ba1\u6570\u636e\uff0c\u5206\u6790\u63a8\u52a8\u8fd9\u4e00\u884c\u4e3a\u7684\u6f5c\u5728\u673a\u5236\u3002\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u90a3\u4e9b\u5728\u8bc4\u8bba\u4e2d\u63d0\u53ca\u9ed1\u4eba\u6240\u6709\u6743\u4f5c\u4e3a\u4ea7\u54c1\u5c5e\u6027\u7684\u9ed1\u4eba\u62e5\u6709\u7684\u9910\u5385\uff0c\u5176\u5230\u5e97\u6d41\u91cf\u76f8\u6bd4\u672a\u83b7\u5f97\u6b64\u7c7b\u8bc4\u8bba\u7684\u9910\u5385\u5927\u7ea6\u589e\u52a0\u4e8610%\u3002\u6b64\u5916\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u63d0\u53ca\u9ed1\u4eba\u6240\u6709\u6743\u7684\u8bc4\u8bba\u4e3b\u8981\u60e0\u53ca\u90a3\u4e9b\u4f4d\u4e8e\u57ce\u5e02\u79cd\u65cf\u9694\u79bb\u7a0b\u5ea6\u8f83\u4f4e\u3001\u79cd\u65cf\u9694\u79bb\u73b0\u8c61\u8f83\u5f31\uff0c\u4e14\u4ece\u9910\u996e\u7c7b\u578b\u96be\u4ee5\u63a8\u65ad\u51fa\u5c11\u6570\u65cf\u88d4\u6240\u6709\u6743\u7684\u9ed1\u4eba\u62e5\u6709\u7684\u9910\u5385\u3002\u6211\u4eec\u7684\u7814\u7a76\u8fd8\u8868\u660e\uff0c\u63d0\u53ca\u9ed1\u4eba\u6240\u6709\u6743\u7684\u5728\u7ebf\u8bc4\u8bba\u901a\u8fc7\u589e\u5f3a\u8de8\u79cd\u65cf\u63a5\u89e6\uff0c\u63d0\u5347\u4e86\u9ed1\u4eba\u62e5\u6709\u7684\u9910\u5385\u7684\u5230\u5e97\u6d41\u91cf\u3002\u975e\u767d\u4eba\u6d88\u8d39\u8005\u5728\u8fd9\u4e9b\u9910\u5385\u6d88\u8d39\u540e\uff0c\u66f4\u6709\u53ef\u80fd\u9047\u5230\u767d\u4eba\u6d88\u8d39\u8005\u3002\u603b\u4f53\u800c\u8a00\uff0c\u672c\u7814\u7a76\u5c55\u793a\u4e86\u7528\u6237\u751f\u6210\u5185\u5bb9\u5728\u4fc3\u8fdb\u653f\u6cbb\u6d88\u8d39\u4e3b\u4e49\u65b9\u9762\u7684\u4ef7\u503c\uff0c\u5373\u4f7f\u5728\u6570\u5b57\u5e73\u53f0\u672a\u8fdb\u884c\u6709\u9488\u5bf9\u6027\u5e72\u9884\u3001\u4e14\u4f01\u4e1a\u4e3b\u672a\u4e3b\u52a8\u62ab\u9732\u79cd\u65cf\u4fe1\u606f\u7684\u60c5\u51b5\u4e0b\uff0c\u8fd9\u79cd\u4ef7\u503c\u4f9d\u7136\u5b58\u5728\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.07730", "journal": "MS", "title": "The Eco-Gender Gap in Boardrooms", "authors": ["Po-Hsuan Hsu", "Kai Li", "Yihui Pan"], "author_details": [{"name": "Po-Hsuan Hsu", "affiliations": ["Department of Quantitative Finance, College of Technology Management, National Tsing Hua University, Hsinchu City 300044, Taiwan"]}, {"name": "Kai Li", "affiliations": ["Sauder School of Business, University of British Columbia, Vancouver, British Columbia V6T 1Z2, Canada"]}, {"name": "Yihui Pan", "affiliations": ["Department of Finance, David Eccles School of Business, University of Utah, Salt Lake City, Utah 84112"]}], "abstract": "To examine what women bring to the boardroom table, we first show a significant gender gap in viewing the tradeoff between environmental and economic benefits, using the Gallup Poll. We next demonstrate that such a gender gap extends into boardrooms. Having female directors is associated with more environmentally friendly business operations, but also with higher investment in environmental protection at the same time. Results from an analysis using a California law change that imposed board gender quotas point to a potentially causal effect of female directors. Employing a rich set of director demographics and board characteristics, we show that none consistently supersedes the share of female directors in explaining corporate environmental performance, suggesting that female directors play a unique role in explaining firms\u2019 investment in environmental protection.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07730", "title_zh": "\u8463\u4e8b\u4f1a\u4e2d\u7684\u751f\u6001\u6027\u522b\u5dee\u8ddd", "abstract_zh": "\u4e3a\u4e86\u63a2\u8ba8\u5973\u6027\u5728\u8463\u4e8b\u4f1a\u4e2d\u5e26\u6765\u7684\u72ec\u7279\u8d21\u732e\uff0c\u6211\u4eec\u9996\u5148\u5229\u7528\u76d6\u6d1b\u666e\u6c11\u610f\u8c03\u67e5\u6570\u636e\u8868\u660e\uff0c\u5728\u73af\u5883\u4e0e\u7ecf\u6d4e\u5229\u76ca\u6743\u8861\u65b9\u9762\u5b58\u5728\u663e\u8457\u7684\u6027\u522b\u5dee\u5f02\u3002\u968f\u540e\u6211\u4eec\u8bc1\u660e\uff0c\u8fd9\u79cd\u6027\u522b\u5dee\u5f02\u4e5f\u5ef6\u4f38\u5230\u4e86\u8463\u4e8b\u4f1a\u5c42\u9762\u3002\u62e5\u6709\u5973\u6027\u8463\u4e8b\u7684\u4f01\u4e1a\u66f4\u503e\u5411\u4e8e\u91c7\u53d6\u73af\u4fdd\u578b\u7ecf\u8425\u65b9\u5f0f\uff0c\u540c\u65f6\u4e5f\u4f1a\u589e\u52a0\u5bf9\u73af\u5883\u4fdd\u62a4\u7684\u6295\u8d44\u3002\u57fa\u4e8e\u52a0\u5dde\u4e00\u9879\u5b9e\u65bd\u8463\u4e8b\u4f1a\u6027\u522b\u914d\u989d\u7684\u6cd5\u5f8b\u53d8\u66f4\u7684\u5206\u6790\u7ed3\u679c\uff0c\u6211\u4eec\u53d1\u73b0\u5973\u6027\u8463\u4e8b\u53ef\u80fd\u5bf9\u4f01\u4e1a\u7684\u73af\u4fdd\u884c\u4e3a\u5177\u6709\u6f5c\u5728\u7684\u56e0\u679c\u5f71\u54cd\u3002\u901a\u8fc7\u8fd0\u7528\u4e30\u5bcc\u7684\u8463\u4e8b\u4eba\u53e3\u7edf\u8ba1\u7279\u5f81\u548c\u8463\u4e8b\u4f1a\u7279\u5f81\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u6ca1\u6709\u5176\u4ed6\u5355\u4e00\u56e0\u7d20\u80fd\u591f\u66ff\u4ee3\u5973\u6027\u8463\u4e8b\u6bd4\u4f8b\u5728\u89e3\u91ca\u4f01\u4e1a\u73af\u4fdd\u8868\u73b0\u65b9\u9762\u7684\u4f5c\u7528\uff0c\u8fd9\u8868\u660e\u5973\u6027\u8463\u4e8b\u5728\u89e3\u91ca\u4f01\u4e1a\u5bf9\u73af\u5883\u4fdd\u62a4\u6295\u8d44\u65b9\u9762\u53d1\u6325\u7740\u72ec\u7279\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2022.01332", "journal": "MS", "title": "Public Signals, Default Risk, and Voluntary Disclosure", "authors": ["Davide Cianciaruso", "Dor Lee-Lo", "Sri S. Sridhar"], "author_details": [{"name": "Davide Cianciaruso", "affiliations": ["New Economic School, 121353 Moscow, Russian Federation"]}, {"name": "Dor Lee-Lo", "affiliations": ["Department of Finance, Coller School of Management, Tel Aviv University, Tel-Aviv 69978, Israel"]}, {"name": "Sri S. Sridhar", "affiliations": ["Department of Accounting Information & Management, Kellogg School of Management, Northwestern University, Evanston, Illinois 60208"]}], "abstract": "We examine how the information in public signals (e.g., earnings, analysts\u2019 forecasts) affects firms\u2019 voluntary disclosures. We consider levered firms and information structures such that investors update their beliefs about both the mean and variance of the firm\u2019s cash flows. We predict that firms that, conditional on the public signal, have a higher default risk are less likely to disclose. For firms with low ex ante default risk, larger positive surprises following the public signal initially increase the disclosure likelihood because they indicate a higher mean of cash flows. However, too large positive surprises may reduce the disclosure likelihood of these firms, because the larger surprise is also indicative of higher variance and, thus, higher probability of default. Symmetrically, larger negative surprises may increase disclosure for firms with high ex ante default risk, despite the more pessimistic inference about the mean, because the higher variance makes it more likely that these firms avoid default. Extending our analysis to multiple analysts\u2019 forecasts, we predict that not only consensus, but also dispersion affect firms\u2019 disclosure likelihood. Consensus conveys information about the mean and variance of cash flows, whereas dispersion is informative about the precision of analysts\u2019 signals, which in turn affects the information content of forecasts.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2022.01332", "title_zh": "\u516c\u5171\u4fe1\u53f7\u3001\u8fdd\u7ea6\u98ce\u9669\u4e0e\u81ea\u613f\u62ab\u9732", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u516c\u5171\u4fe1\u53f7\uff08\u4f8b\u5982\u76c8\u5229\u6570\u636e\u3001\u5206\u6790\u5e08\u9884\u6d4b\uff09\u4e2d\u7684\u4fe1\u606f\u5982\u4f55\u5f71\u54cd\u4f01\u4e1a\u7684\u81ea\u613f\u62ab\u9732\u884c\u4e3a\u3002\u6211\u4eec\u8003\u8651\u4e86\u6760\u6746\u4f01\u4e1a\u4ee5\u53ca\u6295\u8d44\u8005\u4f1a\u66f4\u65b0\u5176\u5bf9\u4f01\u4e1a\u73b0\u91d1\u6d41\u5747\u503c\u548c\u65b9\u5dee\u4fe1\u5ff5\u7684\u4fe1\u606f\u7ed3\u6784\u3002\u6211\u4eec\u9884\u6d4b\uff0c\u5bf9\u4e8e\u5728\u516c\u5171\u4fe1\u53f7\u6761\u4ef6\u4e0b\u8fdd\u7ea6\u98ce\u9669\u8f83\u9ad8\u7684\u4f01\u4e1a\uff0c\u5176\u81ea\u613f\u62ab\u9732\u7684\u53ef\u80fd\u6027\u66f4\u4f4e\u3002\u5bf9\u4e8e\u524d\u671f\u8fdd\u7ea6\u98ce\u9669\u8f83\u4f4e\u7684\u4f01\u4e1a\uff0c\u516c\u5171\u4fe1\u53f7\u540e\u51fa\u73b0\u8f83\u5927\u7684\u6b63\u5411\u610f\u5916\u53d8\u52a8\u6700\u521d\u4f1a\u63d0\u9ad8\u62ab\u9732\u7684\u53ef\u80fd\u6027\uff0c\u56e0\u4e3a\u8fd9\u8868\u660e\u73b0\u91d1\u6d41\u5747\u503c\u4e0a\u5347\uff1b\u7136\u800c\uff0c\u8fc7\u5927\u7684\u6b63\u5411\u610f\u5916\u53d8\u52a8\u53cd\u800c\u53ef\u80fd\u964d\u4f4e\u8fd9\u4e9b\u4f01\u4e1a\u7684\u62ab\u9732\u610f\u613f\uff0c\u56e0\u4e3a\u8f83\u5927\u7684\u6b63\u5411\u53d8\u52a8\u4e5f\u610f\u5473\u7740\u65b9\u5dee\u4e0a\u5347\uff0c\u4ece\u800c\u8fdd\u7ea6\u6982\u7387\u589e\u52a0\u3002\u5bf9\u79f0\u5730\uff0c\u8f83\u5927\u7684\u8d1f\u5411\u610f\u5916\u53d8\u52a8\u53ef\u80fd\u589e\u52a0\u9ad8\u524d\u671f\u8fdd\u7ea6\u98ce\u9669\u4f01\u4e1a\u7684\u62ab\u9732\u6982\u7387\uff0c\u5c3d\u7ba1\u8fd9\u610f\u5473\u7740\u5bf9\u73b0\u91d1\u6d41\u5747\u503c\u7684\u60b2\u89c2\u63a8\u65ad\uff0c\u4f46\u66f4\u9ad8\u7684\u65b9\u5dee\u4f7f\u5f97\u8fd9\u4e9b\u4f01\u4e1a\u66f4\u6709\u53ef\u80fd\u907f\u514d\u8fdd\u7ea6\u3002\u6211\u4eec\u5c06\u5206\u6790\u6269\u5c55\u5230\u591a\u4f4d\u5206\u6790\u5e08\u7684\u9884\u6d4b\uff0c\u9884\u6d4b\u4e0d\u4ec5\u5171\u8bc6\uff0c\u800c\u4e14\u9884\u6d4b\u7684\u5206\u6563\u7a0b\u5ea6\u90fd\u4f1a\u5f71\u54cd\u4f01\u4e1a\u7684\u62ab\u9732\u610f\u613f\u3002\u5171\u8bc6\u63d0\u4f9b\u4e86\u5173\u4e8e\u73b0\u91d1\u6d41\u5747\u503c\u548c\u65b9\u5dee\u7684\u4fe1\u606f\uff0c\u800c\u5206\u6563\u7a0b\u5ea6\u5219\u53cd\u6620\u4e86\u5206\u6790\u5e08\u4fe1\u53f7\u7684\u7cbe\u786e\u6027\uff0c\u8fdb\u800c\u5f71\u54cd\u9884\u6d4b\u4fe1\u606f\u7684\u542b\u91cf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.00476", "journal": "MS", "title": "The Political Economy of Antibribery Enforcement", "authors": ["Lauren H. Cohen", "Bo Li"], "author_details": [{"name": "Lauren H. Cohen", "affiliations": ["Harvard Business School, Boston, Massachusetts 02163; and National Bureau of Economic Research, Cambridge, Massachusetts 02138"]}, {"name": "Bo Li", "affiliations": ["Guanghua School of Management, Peking University, Haidian District, Beijing 100871, China"]}], "abstract": "Using exogenous variation in the timing and geographic location of U.S. Congressional elections, we find that the probability of Foreign Corrupt Practices Act (FCPA) enforcement actions against foreign firms increases significantly preceding senatorial elections, spiking more than 21%, with no commensurate increase for globally operating domestically headquartered firms in these same senators\u2019 states. Using hand-collected case-level data from the Securities and Exchange Commission (SEC) and U.S. Department of Justice (DOJ), we observe that these pre-election cases tend to be weaker overall and that they are brought significantly more often against foreign firms that operate in less-important industries in the senator\u2019s state and when they have a smaller overall U.S. presence. This spike in foreign firm targeting is accompanied by a significant spike in traditional and social media coverage coupled with sharply negative sentiment. Furthermore, these enforcement actions and media spikes are associated with electoral consequences, specifically greater vote shares and better poll results for enforcement-state senators. The FCPA enforcement actions have real impacts on firms. These include a 10% reduction in market value after enforcement actions against foreign firms and a significant decrease in credit ratings.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.00476", "title_zh": "\u53cd\u8150\u8d25\u6267\u6cd5\u7684\u653f\u6cbb\u7ecf\u6d4e\u5b66", "abstract_zh": "\u5229\u7528\u7f8e\u56fd\u56fd\u4f1a\u9009\u4e3e\u65f6\u95f4\u70b9\u548c\u5730\u7406\u533a\u57df\u7684\u5916\u751f\u53d8\u5316\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u53c2\u8bae\u5458\u9009\u4e3e\u524d\uff0c\u5bf9\u5916\u56fd\u4f01\u4e1a\u7684\u300a\u5916\u56fd\u8150\u8d25\u884c\u4e3a\u6cd5\u300b\uff08FCPA\uff09\u6267\u6cd5\u884c\u52a8\u6982\u7387\u663e\u8457\u4e0a\u5347\uff0c\u589e\u5e45\u8d85\u8fc721%\uff0c\u800c\u5bf9\u4e8e\u5728\u8fd9\u4e9b\u53c2\u8bae\u5458\u6240\u5728\u5dde\u8fd0\u8425\u7684\u5168\u7403\u6027\u672c\u571f\u4f01\u4e1a\uff0c\u5219\u672a\u51fa\u73b0\u76f8\u5e94\u7684\u589e\u52a0\u3002\u57fa\u4e8e\u5bf9\u7f8e\u56fd\u8bc1\u5238\u4ea4\u6613\u59d4\u5458\u4f1a\uff08SEC\uff09\u548c\u7f8e\u56fd\u53f8\u6cd5\u90e8\uff08DOJ\uff09\u7684\u624b\u5de5\u6536\u96c6\u7684\u6848\u4f8b\u6570\u636e\uff0c\u6211\u4eec\u89c2\u5bdf\u5230\uff0c\u8fd9\u4e9b\u9009\u4e3e\u524d\u7684\u6848\u4ef6\u6574\u4f53\u5f3a\u5ea6\u8f83\u5f31\uff0c\u4e14\u66f4\u591a\u5730\u9488\u5bf9\u5728\u53c2\u8bae\u5458\u6240\u5728\u5dde\u8fd0\u8425\u7684\u3001\u6240\u5904\u884c\u4e1a\u4e0d\u91cd\u8981\u7684\u5916\u56fd\u4f01\u4e1a\uff0c\u4ee5\u53ca\u5728\u7f8e\u56fd\u5e02\u573a\u5b58\u5728\u89c4\u6a21\u8f83\u5c0f\u7684\u5916\u56fd\u4f01\u4e1a\u3002\u8fd9\u79cd\u5bf9\u5916\u56fd\u4f01\u4e1a\u7684\u6267\u6cd5\u96c6\u4e2d\u73b0\u8c61\u4f34\u968f\u7740\u4f20\u7edf\u5a92\u4f53\u548c\u793e\u4ea4\u5a92\u4f53\u62a5\u9053\u7684\u663e\u8457\u589e\u52a0\u4ee5\u53ca\u8d1f\u9762\u60c5\u7eea\u7684\u6025\u5267\u4e0a\u5347\u3002\u6b64\u5916\uff0c\u8fd9\u4e9b\u6267\u6cd5\u884c\u52a8\u548c\u5a92\u4f53\u62a5\u9053\u7684\u6fc0\u589e\u4e0e\u9009\u4e3e\u7ed3\u679c\u76f8\u5173\uff0c\u5177\u4f53\u8868\u73b0\u4e3a\u6267\u6cd5\u5dde\u53c2\u8bae\u5458\u7684\u9009\u7968\u4efd\u989d\u589e\u52a0\u548c\u6c11\u610f\u8c03\u67e5\u7ed3\u679c\u6539\u5584\u3002FCPA\u6267\u6cd5\u884c\u52a8\u5bf9\u4f01\u4e1a\u5177\u6709\u5b9e\u9645\u5f71\u54cd\uff0c\u5305\u62ec\u5bf9\u5916\u56fd\u4f01\u4e1a\u7684\u5e02\u573a\u4ef7\u503c\u4e0b\u964d10%\u4ee5\u53ca\u4fe1\u7528\u8bc4\u7ea7\u7684\u663e\u8457\u964d\u4f4e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.00149", "journal": "MS", "title": "Forecasted vs. Actual Generosity in Image-Concern Interventions", "authors": ["Minah H. Jung", "Silvia Saccardo", "Ayelet Gneezy", "Leif D. Nelson"], "author_details": [{"name": "Minah H. Jung", "affiliations": ["New York University, New York, New York 10012"]}, {"name": "Silvia Saccardo", "affiliations": ["Carnegie Mellon University, Pittsburgh, Pennsylvania 15213"]}, {"name": "Ayelet Gneezy", "affiliations": ["University of California, San Diego, La Jolla, California 92093"]}, {"name": "Leif D. Nelson", "affiliations": ["University of California, Berkeley, Berkeley, California 94720"]}], "abstract": "Prior research and lay intuition suggest that amplifying image concerns promotes generosity. We test the impact of image-based interventions in consumer elective pricing (CEP), where individuals choose how much to pay for products or services. Across 10 studies (nine field experiments and one laboratory study, n = 3,182), we examine the effects of these interventions on payments and elicit forecasts from independent participants (n = 1,636). Forecasters predict large positive effects, yet behavioral data reveal small and inconsistent impacts. What drives the inconsistency between predictions and actual outcomes? Studies with more than 4,000 forecasters show that neither simulating the decision-making experience nor prior experience with CEP improve prediction accuracy. However, avoiding direct comparisons between experimental conditions\u2014which can artificially amplify perceived differences\u2014reduces overestimation. These findings highlight challenges associated with transferring behavioral insights across contexts and show how forecast elicitation methods shape expectations of intervention effectiveness.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.00149", "title_zh": "\u9884\u671f\u4e0e\u5b9e\u9645\u7684\u56fe\u50cf\u5173\u5207\u5e72\u9884\u6548\u679c\u5bf9\u6bd4", "abstract_zh": "\u5148\u524d\u7684\u7814\u7a76\u548c\u5927\u4f17\u76f4\u89c9\u90fd\u8868\u660e\uff0c\u589e\u5f3a\u5bf9\u5f62\u8c61\u7684\u5173\u6ce8\u4f1a\u4fc3\u8fdb\u6177\u6168\u884c\u4e3a\u3002\u6211\u4eec\u68c0\u9a8c\u4e86\u5728\u6d88\u8d39\u8005\u9009\u62e9\u6027\u5b9a\u4ef7\uff08CEP\uff09\u60c5\u5883\u4e2d\uff0c\u57fa\u4e8e\u56fe\u50cf\u7684\u5e72\u9884\u63aa\u65bd\u5bf9\u652f\u4ed8\u91d1\u989d\u7684\u5f71\u54cd\u3002\u572810\u9879\u7814\u7a76\uff089\u9879\u5b9e\u5730\u5b9e\u9a8c\u548c1\u9879\u5b9e\u9a8c\u5ba4\u5b9e\u9a8c\uff0c\u5171n=3182\u4eba\uff09\u4e2d\uff0c\u6211\u4eec\u5206\u6790\u4e86\u8fd9\u4e9b\u5e72\u9884\u63aa\u65bd\u5bf9\u652f\u4ed8\u884c\u4e3a\u7684\u5f71\u54cd\uff0c\u5e76\u4ece\u72ec\u7acb\u53c2\u4e0e\u8005\uff08n=1636\u4eba\uff09\u5904\u83b7\u53d6\u4e86\u9884\u6d4b\u6570\u636e\u3002\u9884\u6d4b\u8005\u666e\u904d\u9884\u671f\u4f1a\u4ea7\u751f\u663e\u8457\u7684\u6b63\u9762\u6548\u679c\uff0c\u4f46\u884c\u4e3a\u6570\u636e\u5374\u663e\u793a\u5b9e\u9645\u5f71\u54cd\u5fae\u5c0f\u4e14\u4e0d\u4e00\u81f4\u3002\u662f\u4ec0\u4e48\u5bfc\u81f4\u4e86\u9884\u6d4b\u4e0e\u5b9e\u9645\u7ed3\u679c\u4e4b\u95f4\u7684\u4e0d\u4e00\u81f4\uff1f\u5728\u9884\u62a5\u8005\u8d85\u8fc74000\u4eba\u7684\u7814\u7a76\u4e2d\uff0c\u6a21\u62df\u51b3\u7b56\u8fc7\u7a0b\u6216\u5148\u524d\u53c2\u4e0eCEP\u7684\u7ecf\u9a8c\u5747\u672a\u80fd\u63d0\u5347\u9884\u6d4b\u51c6\u786e\u6027\u3002\u7136\u800c\uff0c\u907f\u514d\u5728\u5b9e\u9a8c\u6761\u4ef6\u4e4b\u95f4\u8fdb\u884c\u76f4\u63a5\u6bd4\u8f83\u2014\u2014\u8fd9\u79cd\u505a\u6cd5\u53ef\u80fd\u4eba\u4e3a\u653e\u5927\u611f\u77e5\u5dee\u5f02\u2014\u2014\u53ef\u4ee5\u51cf\u5c11\u8fc7\u5ea6\u4f30\u8ba1\u3002\u8fd9\u4e9b\u53d1\u73b0\u7a81\u663e\u4e86\u5c06\u884c\u4e3a\u6d1e\u5bdf\u8de8\u60c5\u5883\u8fc1\u79fb\u6240\u9762\u4e34\u7684\u6311\u6218\uff0c\u5e76\u63ed\u793a\u4e86\u9884\u6d4b\u83b7\u53d6\u65b9\u6cd5\u5982\u4f55\u5f71\u54cd\u5bf9\u5e72\u9884\u63aa\u65bd\u6709\u6548\u6027\u7684\u9884\u671f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.06528", "journal": "MS", "title": "The Debt Capacity of a Government", "authors": ["Bernard Dumas", "Paul Ehling", "Chunyu Yang"], "author_details": [{"name": "Bernard Dumas", "affiliations": ["INSEAD, Finance Area, 77305 Fontainebleau, France; and National Bureau of Economic Research (NBER), Cambridge, Massachusetts 02138; and Centre for Economic Policy Research (CEPR), 75007 Paris, France"]}, {"name": "Paul Ehling", "affiliations": ["BI Norwegian Business School, N 0444 Oslo, Norway"]}, {"name": "Chunyu Yang", "affiliations": ["BI Norwegian Business School, N 0444 Oslo, Norway"]}], "abstract": "Fiscal costs of excessive debt should be assessed dynamically reflecting anticipated growth, deficits, and interest rates. Studying their joint behavior, with overlapping generations and structural deficits arising from social security, we define government debt capacity as the level that can be just sustained with current fiscal parameters unchanged all the way to an unstable steady state, in which primary deficits last forever. Below capacity, debt converges to a stable steady state. Above capacity, debt unravels. Exceeding capacity without unraveling requires higher future taxes or reduced expenditures, which is the true fiscal cost. With money, capacity increases with the target nominal interest rate if the Taylor coefficient is below one. Increasing capacity by subsidizing innovation is challenging as benefits hardly surpass costs.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06528", "title_zh": "\u653f\u5e9c\u7684\u503a\u52a1\u627f\u53d7\u80fd\u529b", "abstract_zh": "\u8fc7\u5ea6\u503a\u52a1\u7684\u8d22\u653f\u6210\u672c\u5e94\u52a8\u6001\u8bc4\u4f30\uff0c\u53cd\u6620\u9884\u671f\u7684\u589e\u957f\u3001\u8d64\u5b57\u548c\u5229\u7387\u3002\u5728\u8003\u8651\u4e16\u4ee3\u91cd\u53e0\u548c\u6765\u81ea\u793e\u4f1a\u4fdd\u969c\u7684\u7ed3\u6784\u6027\u8d64\u5b57\u7684\u60c5\u51b5\u4e0b\uff0c\u6211\u4eec\u5b9a\u4e49\u653f\u5e9c\u503a\u52a1\u627f\u53d7\u80fd\u529b\u4e3a\uff1a\u5728\u5f53\u524d\u8d22\u653f\u53c2\u6570\u4e0d\u53d8\u7684\u524d\u63d0\u4e0b\uff0c\u80fd\u591f\u4e00\u76f4\u7ef4\u6301\u5230\u4e00\u4e2a\u4e0d\u7a33\u5b9a\u7a33\u6001\u7684\u503a\u52a1\u6c34\u5e73\uff0c\u6b64\u65f6\u6c38\u4e45\u6027\u8d22\u653f\u8d64\u5b57\u51fa\u73b0\u3002\u4f4e\u4e8e\u8be5\u627f\u53d7\u80fd\u529b\uff0c\u503a\u52a1\u4f1a\u6536\u655b\u5230\u4e00\u4e2a\u7a33\u5b9a\u7684\u7a33\u6001\uff1b\u9ad8\u4e8e\u8be5\u627f\u53d7\u80fd\u529b\uff0c\u503a\u52a1\u5c06\u5d29\u6e83\u3002\u82e5\u8d85\u8fc7\u627f\u53d7\u80fd\u529b\u5374\u672a\u5d29\u6e83\uff0c\u5219\u9700\u8981\u672a\u6765\u63d0\u9ad8\u7a0e\u6536\u6216\u51cf\u5c11\u652f\u51fa\uff0c\u8fd9\u624d\u662f\u771f\u6b63\u7684\u8d22\u653f\u6210\u672c\u3002\u5728\u8d27\u5e01\u73af\u5883\u4e0b\uff0c\u5982\u679c\u6cf0\u52d2\u7cfb\u6570\u5c0f\u4e8e\u4e00\uff0c\u503a\u52a1\u627f\u53d7\u80fd\u529b\u968f\u76ee\u6807\u540d\u4e49\u5229\u7387\u7684\u63d0\u9ad8\u800c\u589e\u52a0\u3002\u901a\u8fc7\u8865\u8d34\u521b\u65b0\u6765\u63d0\u9ad8\u627f\u53d7\u80fd\u529b\u5177\u6709\u6311\u6218\u6027\uff0c\u56e0\u4e3a\u5176\u6536\u76ca\u51e0\u4e4e\u65e0\u6cd5\u8d85\u8fc7\u6210\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.00170", "journal": "MS", "title": "Platform Expansion Through Asset Provision: Ownership, Commitment, and Flexibility", "authors": ["Heikki Peura", "S. Alex Yang"], "author_details": [{"name": "Heikki Peura", "affiliations": ["Department of Information and Service Management, Aalto University School of Business, 00076 Aalto, Finland"]}, {"name": "S. Alex Yang", "affiliations": ["London Business School, London NW1 4SA, United Kingdom"]}], "abstract": "Service platforms connect consumers to independent providers, who typically deliver the service using their own assets (e.g., ride-hailing with suitable vehicles). To expand their services, platforms have introduced programs aimed at attracting prospective providers who lack the requisite assets. These programs diverge in terms of asset ownership and contract structures. In platform financing, the platform offers to finance providers\u2019 asset investments, serving as an alternative to bank loans. Under employment and rental schemes, by contrast, the platform itself invests in assets and offers them to providers through long-term employment-like contracts or short-term rentals. We develop a game-theoretical model to study the viability and relative performance of these mechanisms. With bank financing as benchmark, we find that although each mechanism can be profitable, they also face distinct challenges. For example, platform financing often fails to benefit the platform in its simple interest-only form and instead requires payments tied to providers\u2019 on-platform performance. Comparing these mechanisms highlights a tradeoff between the platform committing to a mutually beneficial contract with the providers and leveraging their flexibility as independent service providers. Consequently, the platform prefers the strongest commitment option\u2014employment\u2014when demand is high and investment cost is low and turns to the flexible financing or rental options as demand weakens or investment cost increases. Additionally, we find that minimum-wage regulation could benefit not only service providers but also the platform, particularly under financing or rental. Finally, when the providers\u2019 outside options rely less on access to assets, employment gains ground as the preferred expansion strategy.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.00170", "title_zh": "\u901a\u8fc7\u8d44\u4ea7\u63d0\u4f9b\u5b9e\u73b0\u5e73\u53f0\u6269\u5f20\uff1a\u6240\u6709\u6743\u3001\u627f\u8bfa\u4e0e\u7075\u6d3b\u6027", "abstract_zh": "\u670d\u52a1\u5e73\u53f0\u8fde\u63a5\u6d88\u8d39\u8005\u4e0e\u72ec\u7acb\u670d\u52a1\u63d0\u4f9b\u8005\uff0c\u540e\u8005\u901a\u5e38\u4f7f\u7528\u81ea\u8eab\u8d44\u4ea7\uff08\u4f8b\u5982\uff0c\u7f51\u7ea6\u8f66\u9700\u914d\u5907\u5408\u9002\u7684\u8f66\u8f86\uff09\u6765\u63d0\u4f9b\u670d\u52a1\u3002\u4e3a\u4e86\u6269\u5c55\u670d\u52a1\u8303\u56f4\uff0c\u5e73\u53f0\u63a8\u51fa\u4e86\u65e8\u5728\u5438\u5f15\u7f3a\u4e4f\u5fc5\u8981\u8d44\u4ea7\u7684\u6f5c\u5728\u63d0\u4f9b\u8005\u7684\u8ba1\u5212\uff0c\u8fd9\u4e9b\u8ba1\u5212\u5728\u8d44\u4ea7\u6240\u6709\u6743\u548c\u5408\u540c\u7ed3\u6784\u4e0a\u5b58\u5728\u5dee\u5f02\u3002\u5728\u5e73\u53f0\u878d\u8d44\u6a21\u5f0f\u4e2d\uff0c\u5e73\u53f0\u4e3a\u63d0\u4f9b\u8005\u8d44\u4ea7\u6295\u8d44\u63d0\u4f9b\u878d\u8d44\uff0c\u4f5c\u4e3a\u94f6\u884c\u8d37\u6b3e\u7684\u66ff\u4ee3\u65b9\u6848\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u5728\u96c7\u4f63\u548c\u79df\u8d41\u6a21\u5f0f\u4e0b\uff0c\u5e73\u53f0\u81ea\u8eab\u6295\u8d44\u8d44\u4ea7\uff0c\u5e76\u901a\u8fc7\u7c7b\u4f3c\u957f\u671f\u96c7\u4f63\u7684\u5408\u540c\u6216\u77ed\u671f\u79df\u8d41\u5411\u63d0\u4f9b\u8005\u63d0\u4f9b\u8d44\u4ea7\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u535a\u5f08\u8bba\u6a21\u578b\uff0c\u7814\u7a76\u8fd9\u4e9b\u673a\u5236\u7684\u53ef\u884c\u6027\u548c\u76f8\u5bf9\u8868\u73b0\u3002\u4ee5\u94f6\u884c\u878d\u8d44\u4e3a\u57fa\u51c6\uff0c\u6211\u4eec\u53d1\u73b0\u5c3d\u7ba1\u6bcf\u79cd\u673a\u5236\u5747\u53ef\u76c8\u5229\uff0c\u4f46\u5b83\u4eec\u4e5f\u9762\u4e34\u5404\u81ea\u72ec\u7279\u7684\u6311\u6218\u3002\u4f8b\u5982\uff0c\u5e73\u53f0\u878d\u8d44\u5728\u7b80\u5355\u7684\u5229\u606f\u652f\u4ed8\u5f62\u5f0f\u4e0b\u5f80\u5f80\u65e0\u6cd5\u4e3a\u5e73\u53f0\u5e26\u6765\u6536\u76ca\uff0c\u53cd\u800c\u9700\u8981\u4e0e\u63d0\u4f9b\u8005\u5728\u5e73\u53f0\u4e0a\u7684\u8868\u73b0\u6302\u94a9\u8fdb\u884c\u652f\u4ed8\u3002\u6bd4\u8f83\u8fd9\u4e9b\u673a\u5236\u51f8\u663e\u4e86\u5e73\u53f0\u5728\u627f\u8bfa\u4e0e\u63d0\u4f9b\u8005\u4e4b\u95f4\u5efa\u7acb\u4e92\u5229\u5408\u540c\u4e0e\u5229\u7528\u63d0\u4f9b\u8005\u4f5c\u4e3a\u72ec\u7acb\u670d\u52a1\u63d0\u4f9b\u8005\u7684\u7075\u6d3b\u6027\u4e4b\u95f4\u7684\u6743\u8861\u3002\u56e0\u6b64\uff0c\u5f53\u9700\u6c42\u65fa\u76db\u4e14\u6295\u8d44\u6210\u672c\u8f83\u4f4e\u65f6\uff0c\u5e73\u53f0\u66f4\u503e\u5411\u4e8e\u9009\u62e9\u627f\u8bfa\u6700\u5f3a\u7684\u96c7\u4f63\u6a21\u5f0f\uff1b\u5f53\u9700\u6c42\u51cf\u5f31\u6216\u6295\u8d44\u6210\u672c\u4e0a\u5347\u65f6\uff0c\u5219\u8f6c\u5411\u7075\u6d3b\u7684\u878d\u8d44\u6216\u79df\u8d41\u6a21\u5f0f\u3002\u6b64\u5916\uff0c\u6211\u4eec\u53d1\u73b0\u6700\u4f4e\u5de5\u8d44\u6cd5\u89c4\u4e0d\u4ec5\u6709\u5229\u4e8e\u670d\u52a1\u63d0\u4f9b\u8005\uff0c\u4e5f\u6709\u52a9\u4e8e\u5e73\u53f0\uff0c\u5c24\u5176\u662f\u5728\u878d\u8d44\u6216\u79df\u8d41\u6a21\u5f0f\u4e0b\u3002\u6700\u540e\uff0c\u5f53\u63d0\u4f9b\u8005\u7684\u5916\u90e8\u9009\u62e9\u8f83\u5c11\u4f9d\u8d56\u4e8e\u8d44\u4ea7\u83b7\u53d6\u65f6\uff0c\u96c7\u4f63\u6a21\u5f0f\u6210\u4e3a\u66f4\u53d7\u9752\u7750\u7684\u6269\u5f20\u7b56\u7565\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2026.02442", "journal": "MS", "title": "From Shadow AI to Governed AI Review: A Commentary on \u201cFighting Fire with Fire: Infusing AI into Peer Review to Sustain Quality Scholarship\u201d", "authors": ["Zhenhui (Jack) Jiang"], "author_details": [{"name": "Zhenhui (Jack) Jiang", "affiliations": ["HKU Business School, The University of Hong Kong, Hong Kong, China"]}], "abstract": "This commentary responds to \u201cFighting Fire with Fire: Infusing AI into Peer Review to Sustain Quality Scholarship\u201d [Bhargava et al. (2026) Management Sci. Forthcoming.]. It supports the paper\u2019s call for a governed approach to the use of AI in peer review. It argues that the key issue is not whether AI will enter peer review, but whether its use will remain informal and hidden or become transparent, auditable, and institutionally accountable. While endorsing journal-managed AI review as a response to the problem of \u201cshadow AI,\u201d the comment highlights several implementation risks, including AI hallucination, human accountability, authors\u2019 perceptions of procedural dignity, and the evolving boundary between structured assessment and value judgment. It concludes that AI-assisted peer review should be treated as an important starting point for continued experimentation and refinement.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2026.02442", "title_zh": "\u4ece\u5f71\u5b50\u4eba\u5de5\u667a\u80fd\u5230\u53d7\u76d1\u7ba1\u7684\u4eba\u5de5\u667a\u80fd\u8bc4\u8bba\uff1a\u5bf9\u300a\u4ee5\u706b\u653b\u706b\uff1a\u5c06\u4eba\u5de5\u667a\u80fd\u6ce8\u5165\u540c\u884c\u8bc4\u5ba1\u4ee5\u7ef4\u6301\u5b66\u672f\u8d28\u91cf\u300b\u7684\u8bc4\u8bba", "abstract_zh": "\u672c\u6587\u8bc4\u8bba\u56de\u5e94\u4e86Bhargava\u7b49\u4eba\uff082026\u5e74\uff09\u300a\u7ba1\u7406\u79d1\u5b66\u300b\u5373\u5c06\u53d1\u8868\u7684\u8bba\u6587\u300a\u4ee5\u706b\u653b\u706b\uff1a\u5c06\u4eba\u5de5\u667a\u80fd\u6ce8\u5165\u540c\u884c\u8bc4\u5ba1\u4ee5\u7ef4\u6301\u5b66\u672f\u8d28\u91cf\u300b\u3002\u6587\u7ae0\u652f\u6301\u8be5\u8bba\u6587\u5021\u5bfc\u7684\u5728\u540c\u884c\u8bc4\u5ba1\u4e2d\u91c7\u7528\u53d7\u76d1\u7ba1\u7684\u4eba\u5de5\u667a\u80fd\u65b9\u6cd5\u3002\u4f5c\u8005\u8ba4\u4e3a\uff0c\u5173\u952e\u95ee\u9898\u5e76\u975e\u4eba\u5de5\u667a\u80fd\u662f\u5426\u4f1a\u8fdb\u5165\u540c\u884c\u8bc4\u5ba1\uff0c\u800c\u662f\u5176\u4f7f\u7528\u662f\u5426\u4f1a\u4fdd\u6301\u975e\u6b63\u5f0f\u548c\u9690\u853d\uff0c\u8fd8\u662f\u8f6c\u53d8\u4e3a\u900f\u660e\u3001\u53ef\u5ba1\u8ba1\u4e14\u5177\u6709\u5236\u5ea6\u95ee\u8d23\u6027\u7684\u8fc7\u7a0b\u3002\u5c3d\u7ba1\u652f\u6301\u7531\u671f\u520a\u7ba1\u7406\u7684\u4eba\u5de5\u667a\u80fd\u8bc4\u5ba1\u4f5c\u4e3a\u5e94\u5bf9\u2018\u5f71\u5b50\u4eba\u5de5\u667a\u80fd\u2019\u95ee\u9898\u7684\u89e3\u51b3\u65b9\u6848\uff0c\u4f46\u8bc4\u8bba\u4e5f\u6307\u51fa\u4e86\u82e5\u5e72\u5b9e\u65bd\u98ce\u9669\uff0c\u5305\u62ec\u4eba\u5de5\u667a\u80fd\u5e7b\u89c9\u3001\u4eba\u7c7b\u95ee\u8d23\u6027\u3001\u4f5c\u8005\u5bf9\u7a0b\u5e8f\u5c0a\u4e25\u7684\u611f\u77e5\uff0c\u4ee5\u53ca\u7ed3\u6784\u5316\u8bc4\u4f30\u4e0e\u4ef7\u503c\u5224\u65ad\u4e4b\u95f4\u8fb9\u754c\u7684\u53d8\u5316\u3002\u6700\u540e\u6307\u51fa\uff0c\u4eba\u5de5\u667a\u80fd\u8f85\u52a9\u7684\u540c\u884c\u8bc4\u5ba1\u5e94\u88ab\u89c6\u4e3a\u6301\u7eed\u5b9e\u9a8c\u4e0e\u4f18\u5316\u7684\u91cd\u8981\u8d77\u70b9\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2020.00902", "journal": "MS", "title": "Commercializing the Package Flow: Cross-Sampling Physical Products Through E-Commerce Warehouses", "authors": ["Brian Rongqing Han", "Leon Yang Chu", "Tianshu Sun", "Lixia Wu"], "author_details": [{"name": "Brian Rongqing Han", "affiliations": ["Gies College of Business, University of Illinois at Urbana-Champaign, Champaign, Illinois 61820"]}, {"name": "Leon Yang Chu", "affiliations": ["Cheung Kong Graduate School of Business, Beijing 100006, China"]}, {"name": "Tianshu Sun", "affiliations": ["Cheung Kong Graduate School of Business, Beijing 100006, China"]}, {"name": "Lixia Wu", "affiliations": ["Cainiao Smart Logistics Network Ltd., Hangzhou, Zhejiang 311121, China"]}], "abstract": "Many e-commerce platforms have established their warehouses to facilitate the storage and delivery of packages. This paper studies a novel business practice\u2014cross-sampling through e-commerce warehouses\u2014that allows physical free samples provided by one (sampling) brand to be distributed with the packages of another unrelated (distributing) brand. In close collaboration with Alibaba, we implement cross-sampling through a large-scale field experiment, in which more than 55,000 free samples are distributed, to empirically examine its effectiveness in driving online sales of the sampling brand. First, we find significant increases in store visits and sales of the sampling brand both in the short term and long term up to 14 months afterward. The long-term effect is driven mainly by acquiring customers who did not purchase from the sampling brand to visit the online stores and eventually make a purchase. Second, contrary to the previous literature on within-category free sampling, we find a significant sales increase in both the sampled item and other items, which further spills over to indirect channels. Therefore, cross-sampling can also help promote the sampling brand as a whole. Finally, we illustrate the potential for personalization for cross-sampling. Cross-sampling is more effective for customers who recently viewed related products or just purchased nonessential products from the distributing brand. By taking into account the interaction among brands, items, and customers, we can further improve the profitability of cross-sampling by targeting the \u201cright\u201d packages. Overall, because cross-sampling is scalable, effective, and flexible, we demonstrate the high potential of a new business practice that combines offline logistics control and online information to generate additional business value for customers, brands, and the platform.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2020.00902", "title_zh": "\u5546\u54c1\u6d41\u7684\u5546\u4e1a\u5316\uff1a\u901a\u8fc7\u7535\u5b50\u5546\u52a1\u4ed3\u5e93\u5b9e\u73b0\u8de8\u54c1\u7c7b\u5b9e\u7269\u6837\u54c1\u5206\u53d1", "abstract_zh": "\u8bb8\u591a\u7535\u5b50\u5546\u52a1\u5e73\u53f0\u5df2\u5efa\u7acb\u4ed3\u5e93\u4ee5\u4fc3\u8fdb\u5305\u88f9\u7684\u5b58\u50a8\u4e0e\u914d\u9001\u3002\u672c\u6587\u7814\u7a76\u4e86\u4e00\u79cd\u65b0\u578b\u5546\u4e1a\u6a21\u5f0f\u2014\u2014\u901a\u8fc7\u7535\u5b50\u5546\u52a1\u4ed3\u5e93\u8fdb\u884c\u8de8\u54c1\u7c7b\u6837\u54c1\u5206\u53d1\uff0c\u5373\u8ba9\u4e00\u4e2a\uff08\u6837\u54c1\u63d0\u4f9b\uff09\u54c1\u724c\u63d0\u4f9b\u7684\u5b9e\u7269\u514d\u8d39\u6837\u54c1\u968f\u53e6\u4e00\u4e2a\u65e0\u5173\uff08\u5206\u53d1\uff09\u54c1\u724c\u7684\u5305\u88f9\u4e00\u540c\u53d1\u653e\u3002\u5728\u4e0e\u963f\u91cc\u5df4\u5df4\u7d27\u5bc6\u5408\u4f5c\u7684\u57fa\u7840\u4e0a\uff0c\u6211\u4eec\u901a\u8fc7\u4e00\u9879\u5927\u89c4\u6a21\u5b9e\u5730\u5b9e\u9a8c\uff08\u5206\u53d1\u8d85\u8fc755,000\u4e2a\u514d\u8d39\u6837\u54c1\uff09\u6765\u5b9e\u8bc1\u68c0\u9a8c\u8be5\u6a21\u5f0f\u5728\u63a8\u52a8\u6837\u54c1\u54c1\u724c\u7ebf\u4e0a\u9500\u552e\u65b9\u9762\u7684\u6709\u6548\u6027\u3002\u9996\u5148\uff0c\u6211\u4eec\u53d1\u73b0\u6837\u54c1\u54c1\u724c\u5728\u77ed\u671f\u5185\u53ca\u957f\u8fbe14\u4e2a\u6708\u540e\u7684\u957f\u671f\u671f\u5185\uff0c\u5176\u5e97\u94fa\u8bbf\u95ee\u91cf\u548c\u9500\u552e\u989d\u5747\u663e\u8457\u4e0a\u5347\uff0c\u5176\u4e2d\u957f\u671f\u6548\u5e94\u4e3b\u8981\u6e90\u4e8e\u5438\u5f15\u539f\u672c\u672a\u8d2d\u4e70\u8be5\u6837\u54c1\u54c1\u724c\u7684\u987e\u5ba2\u8bbf\u95ee\u7ebf\u4e0a\u5e97\u94fa\u5e76\u6700\u7ec8\u5b8c\u6210\u8d2d\u4e70\u3002\u5176\u6b21\uff0c\u4e0e\u4ee5\u5f80\u5173\u4e8e\u54c1\u7c7b\u5185\u514d\u8d39\u6837\u54c1\u7684\u7814\u7a76\u4e0d\u540c\uff0c\u6211\u4eec\u53d1\u73b0\u6837\u54c1\u5546\u54c1\u672c\u8eab\u53ca\u5176\u4ed6\u5546\u54c1\u7684\u9500\u552e\u5747\u663e\u8457\u589e\u957f\uff0c\u4e14\u8fd9\u79cd\u589e\u957f\u8fdb\u4e00\u6b65\u5411\u95f4\u63a5\u6e20\u9053\u6269\u6563\u3002\u56e0\u6b64\uff0c\u8de8\u54c1\u7c7b\u6837\u54c1\u5206\u53d1\u4e0d\u4ec5\u80fd\u4fc3\u8fdb\u6837\u54c1\u54c1\u724c\u672c\u8eab\u7684\u53d1\u5c55\uff0c\u8fd8\u80fd\u6574\u4f53\u63d0\u5347\u54c1\u724c\u5f71\u54cd\u529b\u3002\u6700\u540e\uff0c\u6211\u4eec\u5c55\u793a\u4e86\u8de8\u54c1\u7c7b\u6837\u54c1\u5206\u53d1\u7684\u4e2a\u6027\u5316\u6f5c\u529b\uff1a\u5bf9\u4e8e\u8fd1\u671f\u6d4f\u89c8\u8fc7\u76f8\u5173\u4ea7\u54c1\u6216\u521a\u521a\u8d2d\u4e70\u975e\u5fc5\u9700\u54c1\u7684\u5206\u53d1\u54c1\u724c\u987e\u5ba2\uff0c\u6837\u54c1\u5206\u53d1\u6548\u679c\u66f4\u4f73\u3002\u901a\u8fc7\u8003\u8651\u54c1\u724c\u3001\u5546\u54c1\u4e0e\u987e\u5ba2\u4e4b\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\uff0c\u6211\u4eec\u53ef\u4ee5\u8fdb\u4e00\u6b65\u901a\u8fc7\u7cbe\u51c6\u6295\u653e\u201c\u5408\u9002\u7684\u5305\u88f9\u201d\u6765\u63d0\u5347\u8de8\u54c1\u7c7b\u6837\u54c1\u5206\u53d1\u7684\u76c8\u5229\u80fd\u529b\u3002\u603b\u4f53\u800c\u8a00\uff0c\u7531\u4e8e\u8de8\u54c1\u7c7b\u6837\u54c1\u5206\u53d1\u5177\u6709\u53ef\u6269\u5c55\u6027\u3001\u6709\u6548\u6027\u4e0e\u7075\u6d3b\u6027\uff0c\u672c\u6587\u5c55\u793a\u4e86\u5c06\u7ebf\u4e0b\u7269\u6d41\u63a7\u5236\u4e0e\u7ebf\u4e0a\u4fe1\u606f\u7ed3\u5408\u4ee5\u521b\u9020\u989d\u5916\u5546\u4e1a\u4ef7\u503c\u7684\u65b0\u5546\u4e1a\u6a21\u5f0f\u5728\u987e\u5ba2\u3001\u54c1\u724c\u53ca\u5e73\u53f0\u5c42\u9762\u7684\u5de8\u5927\u6f5c\u529b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2022.03031", "journal": "MS", "title": "Nonprogressive Diffusion on Social Networks: Approximation and Applications", "authors": ["Yunduan Lin", "Heng Zhang", "Renyu Zhang", "Zuo-Jun Max Shen"], "author_details": [{"name": "Yunduan Lin", "affiliations": ["The Chinese University of Hong Kong Business School, The Chinese University of Hong Kong, Hong Kong"]}, {"name": "Heng Zhang", "affiliations": ["W. P. Carey School of Business, Arizona State University, Tempe, Arizona 85287"]}, {"name": "Renyu Zhang", "affiliations": ["The Chinese University of Hong Kong Business School, The Chinese University of Hong Kong, Hong Kong"]}, {"name": "Zuo-Jun Max Shen", "affiliations": ["Faculty of Engineering and Faculty of Business and Economics, University of Hong Kong, Hong Kong"]}], "abstract": "Nonprogressive diffusion models the spread of behavior on social networks, where agents are allowed to reverse their decisions as time evolves. To provide an efficient framework for evaluating and optimizing nonprogressive diffusion, we introduce a comprehensive model along with a fixed-point approximation (FPA) scheme, which admits both theoretical guarantee and computational efficiency. We show that the approximation error depends on the network structure and derive order-optimal bounds for this error based on a newly proposed network measure. Additionally, we propose two easy-to-calculate network metrics (one at the node level and the other at the network level) that serve as reliable indicators of FPA performance. Our results indicate that the FPA scheme is particularly accurate for dense and large networks, which are typically challenging to analyze via simulation. To showcase the broad applicability of our approach, we apply the FPA scheme to well-known problems, like influence maximization and optimal pricing on social networks. Finally, we conduct extensive numerical experiments on both synthetic and real-world networks. On real-world networks, the FPA scheme achieves computational speedups of 70\u2013230 times compared with na\u00efve agent-based simulation and 23\u201330 times compared with a more advanced simulation method while maintaining a mean absolute percentage error of less than 3.48%.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2022.03031", "title_zh": "\u793e\u4ea4\u7f51\u7edc\u4e2d\u975e\u6e10\u8fdb\u5f0f\u6269\u6563\uff1a\u8fd1\u4f3c\u65b9\u6cd5\u53ca\u5176\u5e94\u7528", "abstract_zh": "\u975e\u6e10\u8fdb\u5f0f\u6269\u6563\u6a21\u578b\u63cf\u8ff0\u4e86\u793e\u4ea4\u7f51\u7edc\u4e2d\u884c\u4e3a\u7684\u4f20\u64ad\u8fc7\u7a0b\uff0c\u5176\u4e2d\u4e2a\u4f53\u5728\u65f6\u95f4\u6f14\u8fdb\u8fc7\u7a0b\u4e2d\u88ab\u5141\u8bb8\u9006\u8f6c\u5176\u51b3\u7b56\u3002\u4e3a\u4e86\u9ad8\u6548\u8bc4\u4f30\u548c\u4f18\u5316\u975e\u6e10\u8fdb\u5f0f\u6269\u6563\uff0c\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u5168\u9762\u7684\u6a21\u578b\u4ee5\u53ca\u4e00\u79cd\u56fa\u5b9a\u70b9\u8fd1\u4f3c\uff08FPA\uff09\u65b9\u6848\uff0c\u8be5\u65b9\u6848\u517c\u5177\u7406\u8bba\u4fdd\u8bc1\u548c\u8ba1\u7b97\u6548\u7387\u3002\u6211\u4eec\u8bc1\u660e\u4e86\u8fd1\u4f3c\u8bef\u5dee\u4f9d\u8d56\u4e8e\u7f51\u7edc\u7ed3\u6784\uff0c\u5e76\u57fa\u4e8e\u4e00\u4e2a\u65b0\u63d0\u51fa\u7684\u7f51\u7edc\u5ea6\u91cf\uff0c\u63a8\u5bfc\u51fa\u8be5\u8bef\u5dee\u7684\u6700\u4f18\u9636\u754c\u3002\u6b64\u5916\uff0c\u6211\u4eec\u63d0\u51fa\u4e86\u4e24\u79cd\u6613\u4e8e\u8ba1\u7b97\u7684\u7f51\u7edc\u6307\u6807\uff08\u4e00\u4e2a\u8282\u70b9\u5c42\u9762\u3001\u4e00\u4e2a\u7f51\u7edc\u5c42\u9762\uff09\uff0c\u53ef\u4f5c\u4e3aFPA\u6027\u80fd\u7684\u53ef\u9760\u6307\u793a\u5668\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0cFPA\u65b9\u6848\u5728\u5bc6\u96c6\u4e14\u89c4\u6a21\u8f83\u5927\u7684\u7f51\u7edc\u4e2d\u5c24\u4e3a\u51c6\u786e\uff0c\u8fd9\u7c7b\u7f51\u7edc\u901a\u5e38\u96be\u4ee5\u901a\u8fc7\u6a21\u62df\u8fdb\u884c\u5206\u6790\u3002\u4e3a\u4e86\u5c55\u793a\u8be5\u65b9\u6cd5\u7684\u5e7f\u6cdb\u5e94\u7528\uff0c\u6211\u4eec\u5c06FPA\u65b9\u6848\u5e94\u7528\u4e8e\u5f71\u54cd\u529b\u6700\u5927\u5316\u548c\u793e\u4ea4\u7f51\u7edc\u6700\u4f18\u5b9a\u4ef7\u7b49\u7ecf\u5178\u95ee\u9898\u3002\u6700\u540e\uff0c\u6211\u4eec\u5728\u5408\u6210\u548c\u771f\u5b9e\u4e16\u754c\u7f51\u7edc\u4e0a\u8fdb\u884c\u4e86\u5e7f\u6cdb\u7684\u6570\u503c\u5b9e\u9a8c\u3002\u5728\u771f\u5b9e\u4e16\u754c\u7f51\u7edc\u4e2d\uff0cFPA\u65b9\u6848\u76f8\u6bd4\u6734\u7d20\u7684\u57fa\u4e8e\u4ee3\u7406\u7684\u6a21\u62df\u65b9\u6cd5\u5b9e\u73b0\u4e8670\u81f3230\u500d\u7684\u8ba1\u7b97\u52a0\u901f\uff0c\u76f8\u6bd4\u66f4\u5148\u8fdb\u7684\u6a21\u62df\u65b9\u6cd5\u5b9e\u73b0\u4e8623\u81f330\u500d\u7684\u52a0\u901f\uff0c\u540c\u65f6\u4fdd\u6301\u5e73\u5747\u7edd\u5bf9\u767e\u5206\u6bd4\u8bef\u5dee\u4f4e\u4e8e3.48%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1287/mnsc.2024.04372", "journal": "MS", "title": "Economic Uncertainty and the Beta Anomaly", "authors": ["Zhiqi Cao", "Wenfeng Wu", "Youchang Wu"], "author_details": [{"name": "Zhiqi Cao", "affiliations": ["Antai College of Economics and Management, Shanghai Jiao Tong University, Shanghai 200030, China"]}, {"name": "Wenfeng Wu", "affiliations": ["Antai College of Economics and Management, Shanghai Jiao Tong University, Shanghai 200030, China"]}, {"name": "Youchang Wu", "affiliations": ["Lundquist College of Business, University of Oregon, Eugene, Oregon 97403"]}], "abstract": "Using various measures of economic uncertainty, we find that the beta-alpha anomaly exists only during periods of low economic uncertainty. We argue that diminished risk appetite during high economic uncertainty eases leverage constraints of typical long-only investors, making overvaluation of high-beta stocks and undervaluation of low-beta stocks less likely. Differences in uncertainty-related beta trading activities between mutual fund investors/managers and hedge funds support this explanation. Variation of the beta anomaly within the low-uncertainty state further corroborates it: the anomaly is significant (insignificant) in stocks heavily held by actively managed mutual funds (hedge funds), and it is concentrated in the subperiods in which leverage constraints for long-only investors are likely to be more severe.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.04372", "title_zh": "\u7ecf\u6d4e\u4e0d\u786e\u5b9a\u6027\u4e0e\u8d1d\u5854\u5f02\u5e38", "abstract_zh": "\u5229\u7528\u591a\u79cd\u7ecf\u6d4e\u4e0d\u786e\u5b9a\u6027\u8861\u91cf\u6307\u6807\uff0c\u6211\u4eec\u53d1\u73b0\u8d1d\u5854-\u963f\u5c14\u6cd5\u5f02\u5e38\u4ec5\u5728\u7ecf\u6d4e\u4e0d\u786e\u5b9a\u6027\u8f83\u4f4e\u7684\u65f6\u671f\u5b58\u5728\u3002\u6211\u4eec\u8ba4\u4e3a\uff0c\u5728\u9ad8\u7ecf\u6d4e\u4e0d\u786e\u5b9a\u6027\u65f6\u671f\uff0c\u6295\u8d44\u8005\u7684\u98ce\u9669\u504f\u597d\u51cf\u5f31\uff0c\u4ece\u800c\u7f13\u89e3\u4e86\u5178\u578b\u957f\u4ed3\u6295\u8d44\u8005\u7684\u6760\u6746\u7ea6\u675f\uff0c\u4f7f\u5f97\u9ad8\u8d1d\u5854\u80a1\u7968\u88ab\u9ad8\u4f30\u3001\u4f4e\u8d1d\u5854\u80a1\u7968\u88ab\u4f4e\u4f30\u7684\u73b0\u8c61\u53d8\u5f97\u4e0d\u592a\u53ef\u80fd\u3002\u5171\u540c\u57fa\u91d1\u6295\u8d44\u8005/\u7ba1\u7406\u8005\u4e0e\u5bf9\u51b2\u57fa\u91d1\u5728\u4e0e\u4e0d\u786e\u5b9a\u6027\u76f8\u5173\u7684\u8d1d\u5854\u4ea4\u6613\u884c\u4e3a\u4e0a\u7684\u5dee\u5f02\u652f\u6301\u4e86\u8fd9\u4e00\u89e3\u91ca\u3002\u5728\u4f4e\u4e0d\u786e\u5b9a\u6027\u72b6\u6001\u4e0b\uff0c\u8d1d\u5854\u5f02\u5e38\u7684\u6ce2\u52a8\u6027\u8fdb\u4e00\u6b65\u8bc1\u5b9e\u4e86\u8fd9\u4e00\u70b9\uff1a\u8be5\u5f02\u5e38\u5728\u88ab\u4e3b\u52a8\u7ba1\u7406\u7684\u5171\u540c\u57fa\u91d1\u5927\u91cf\u6301\u6709\u7684\u80a1\u7968\u4e2d\u663e\u8457\uff08\u5728\u5bf9\u51b2\u57fa\u91d1\u4e2d\u4e0d\u663e\u8457\uff09\uff0c\u5e76\u4e14\u96c6\u4e2d\u5728\u6760\u6746\u7ea6\u675f\u5bf9\u957f\u4ed3\u6295\u8d44\u8005\u800c\u8a00\u53ef\u80fd\u66f4\u4e3a\u4e25\u683c\u7684\u5b50\u65f6\u671f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1287/mnsc.2024.05913", "journal": "MS", "title": "Dynamic Portfolio Choice with Intertemporal Hedging and Transaction Costs", "authors": ["Johannes Muhle-Karbe", "James Sefton", "Xiaofei Shi"], "author_details": [{"name": "Johannes Muhle-Karbe", "affiliations": ["Department of Mathematics, Imperial College London, London SW7 2AZ, United Kingdom"]}, {"name": "James Sefton", "affiliations": ["Imperial College London, London SW7 2AZ, United Kingdom"]}, {"name": "Xiaofei Shi", "affiliations": ["Department of Statistical Science, University of Toronto, Toronto, Ontario M5G 1Z5, Canada"]}], "abstract": "When returns are partially predictable and trading is costly, utility-maximizing investors track a target portfolio at a constant trading speed. The target portfolio is optimal for a frictionless market, where asset returns are scaled back to account for trading costs and volatilities are adjusted to proxy the \u201cexecution risk\u201d of holding assets that are costly to trade and exposed to volatile states. The trading speed solves an optimal execution problem, which describes how the legacy portfolio inherited from the past is traded toward the target portfolio in an optimal manner. Unlike for period-by-period mean-variance preferences, the target portfolio hedges changes in investment opportunities, and both it and the trading speed are linked and depend on execution risk. We set the problem out first in an \u201cabsolute\u201d framework\u2014price shocks independent of the price level, and investors have CARA preferences\u2014and then in a \u201crelative\u201d framework, with price shocks scaled by price levels and CRRA preferences. We illustrate the practical implications of these results in a model where market return predictions are based on a short-term momentum and a long-term value signal.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.05913", "title_zh": "\u5177\u6709\u8de8\u671f\u5bf9\u51b2\u548c\u4ea4\u6613\u6210\u672c\u7684\u52a8\u6001\u6295\u8d44\u7ec4\u5408\u9009\u62e9", "abstract_zh": "\u5f53\u6536\u76ca\u7387\u90e8\u5206\u53ef\u9884\u6d4b\u4e14\u4ea4\u6613\u5b58\u5728\u6210\u672c\u65f6\uff0c\u6548\u7528\u6700\u5927\u5316\u6295\u8d44\u8005\u4ee5\u6052\u5b9a\u4ea4\u6613\u901f\u5ea6\u8ddf\u8e2a\u4e00\u4e2a\u76ee\u6807\u6295\u8d44\u7ec4\u5408\u3002\u8be5\u76ee\u6807\u6295\u8d44\u7ec4\u5408\u662f\u9488\u5bf9\u65e0\u6469\u64e6\u5e02\u573a\u7684\u6700\u4f18\u89e3\uff0c\u5728\u8be5\u5e02\u573a\u4e2d\uff0c\u8d44\u4ea7\u6536\u76ca\u7387\u88ab\u8c03\u6574\u4ee5\u53cd\u6620\u4ea4\u6613\u6210\u672c\uff0c\u800c\u6ce2\u52a8\u6027\u5219\u88ab\u4fee\u6b63\u4ee5\u4ee3\u7406\u6301\u6709\u90a3\u4e9b\u4ea4\u6613\u6210\u672c\u9ad8\u4e14\u66b4\u9732\u4e8e\u6ce2\u52a8\u72b6\u6001\u7684\u8d44\u4ea7\u6240\u5e26\u6765\u7684\u2018\u6267\u884c\u98ce\u9669\u2019\u3002\u4ea4\u6613\u901f\u5ea6\u89e3\u51b3\u4e86\u6700\u4f18\u6267\u884c\u95ee\u9898\uff0c\u8be5\u95ee\u9898\u63cf\u8ff0\u4e86\u5982\u4f55\u4ee5\u6700\u4f18\u65b9\u5f0f\u5c06\u8fc7\u53bb\u7ee7\u627f\u7684\u73b0\u6709\u6295\u8d44\u7ec4\u5408\u9010\u6b65\u8c03\u6574\u81f3\u76ee\u6807\u6295\u8d44\u7ec4\u5408\u3002\u4e0e\u9010\u671f\u5747\u503c-\u65b9\u5dee\u504f\u597d\u4e0d\u540c\uff0c\u76ee\u6807\u6295\u8d44\u7ec4\u5408\u5bf9\u6295\u8d44\u673a\u4f1a\u7684\u53d8\u5316\u8fdb\u884c\u5bf9\u51b2\uff0c\u4e14\u76ee\u6807\u6295\u8d44\u7ec4\u5408\u4e0e\u4ea4\u6613\u901f\u5ea6\u5747\u4e0e\u6267\u884c\u98ce\u9669\u76f8\u5173\u8054\u3002\u6211\u4eec\u9996\u5148\u5728\u4e00\u79cd\u2018\u7edd\u5bf9\u2019\u6846\u67b6\u4e0b\u8bbe\u5b9a\u95ee\u9898\u2014\u2014\u5373\u4ef7\u683c\u51b2\u51fb\u72ec\u7acb\u4e8e\u4ef7\u683c\u6c34\u5e73\uff0c\u6295\u8d44\u8005\u5177\u6709CARA\u504f\u597d\uff1b\u7136\u540e\u5728\u4e00\u79cd\u2018\u76f8\u5bf9\u2019\u6846\u67b6\u4e0b\u8bbe\u5b9a\u95ee\u9898\u2014\u2014\u5373\u4ef7\u683c\u51b2\u51fb\u6309\u4ef7\u683c\u6c34\u5e73\u7f29\u653e\uff0c\u6295\u8d44\u8005\u5177\u6709CRRA\u504f\u597d\u3002\u6211\u4eec\u901a\u8fc7\u4e00\u4e2a\u6a21\u578b\u6765\u8bf4\u660e\u8fd9\u4e9b\u7ed3\u679c\u7684\u5b9e\u9645\u610f\u4e49\uff0c\u8be5\u6a21\u578b\u4e2d\u5e02\u573a\u6536\u76ca\u7387\u9884\u6d4b\u57fa\u4e8e\u77ed\u671f\u52a8\u91cf\u4fe1\u53f7\u548c\u957f\u671f\u4ef7\u503c\u4fe1\u53f7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1287/mnsc.2024.06771", "journal": "MS", "title": "Deep Reinforcement Learning for Equilibrium Computation in Multistage Auctions and Contests", "authors": ["Fabian R. Pieroth", "Nils Kohring", "Martin Bichler"], "author_details": [{"name": "Fabian R. Pieroth", "affiliations": ["School of Computation, Information and Technology, Technical University of Munich"]}, {"name": "Nils Kohring", "affiliations": ["School of Computation, Information and Technology, Technical University of Munich"]}, {"name": "Martin Bichler", "affiliations": ["School of Computation, Information and Technology, Technical University of Munich"]}], "abstract": "We compute equilibrium strategies in multistage games with continuous signal and action spaces as they are widely used in the management sciences and economics. Examples include sequential sales via auctions, multistage elimination contests, and Stackelberg competitions. In sequential auctions, analysts performing equilibrium analysis are required to derive not just single bids but bid functions for all possible signals or values that a bidder might have in multiple stages. Because of the continuity of the signal and action spaces, these bid functions come from an infinite dimensional space. Although such models are fundamental to game theory and its applications, equilibrium strategies are rarely known. The resulting system of nonlinear differential equations is considered intractable for all but elementary models. This has been limiting progress in game theory and is a barrier to its adoption in the field. We show that deep reinforcement learning and self-play can learn equilibrium bidding strategies for various multistage games. Verifying an equilibrium in such games is challenging because of the continuous signal and action spaces. We introduce a verification algorithm and prove that the error of this verifier decreases when considering Lipschitz continuous strategies with increasing levels of discretization and sample sizes. Leveraging the novel verification algorithm, we find equilibrium in models that have not yet been explored analytically and new asymmetric equilibrium bid functions for established models of sequential auctions.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06771", "title_zh": "\u6df1\u5ea6\u5f3a\u5316\u5b66\u4e60\u5728\u591a\u9636\u6bb5\u62cd\u5356\u548c\u7ade\u8d5b\u4e2d\u7684\u5747\u8861\u7b56\u7565\u8ba1\u7b97", "abstract_zh": "\u6211\u4eec\u8ba1\u7b97\u4e86\u5728\u8fde\u7eed\u4fe1\u53f7\u548c\u884c\u52a8\u7a7a\u95f4\u7684\u591a\u9636\u6bb5\u535a\u5f08\u4e2d\u7684\u5747\u8861\u7b56\u7565\uff0c\u8fd9\u7c7b\u6a21\u578b\u5728\u7ba1\u7406\u79d1\u5b66\u548c\u7ecf\u6d4e\u5b66\u4e2d\u88ab\u5e7f\u6cdb\u5e94\u7528\uff0c\u4f8b\u5982\u8fde\u7eed\u62cd\u5356\u3001\u591a\u9636\u6bb5\u6dd8\u6c70\u7ade\u8d5b\u4ee5\u53ca\u65af\u5854\u514b\u5c14\u4f2f\u683c\u7ade\u4e89\u3002\u5728\u8fde\u7eed\u62cd\u5356\u4e2d\uff0c\u8fdb\u884c\u5747\u8861\u5206\u6790\u7684\u5206\u6790\u5e08\u9700\u8981\u63a8\u5bfc\u51fa\u6240\u6709\u53ef\u80fd\u4fe1\u53f7\u6216\u4ef7\u503c\u7684\u6295\u6807\u51fd\u6570\uff0c\u800c\u8fd9\u4e9b\u6295\u6807\u51fd\u6570\u6765\u81ea\u65e0\u9650\u7ef4\u7a7a\u95f4\u3002\u5c3d\u7ba1\u8fd9\u7c7b\u6a21\u578b\u5bf9\u535a\u5f08\u8bba\u53ca\u5176\u5e94\u7528\u81f3\u5173\u91cd\u8981\uff0c\u4f46\u5747\u8861\u7b56\u7565\u901a\u5e38\u672a\u77e5\u3002\u7531\u6b64\u4ea7\u751f\u7684\u975e\u7ebf\u6027\u5fae\u5206\u65b9\u7a0b\u7cfb\u7edf\u5bf9\u4e8e\u9664\u7b80\u5355\u6a21\u578b\u5916\u7684\u6240\u6709\u60c5\u51b5\u90fd\u96be\u4ee5\u6c42\u89e3\uff0c\u8fd9\u9650\u5236\u4e86\u535a\u5f08\u8bba\u7684\u53d1\u5c55\uff0c\u5e76\u963b\u788d\u4e86\u5176\u5728\u8be5\u9886\u57df\u7684\u5e94\u7528\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u901a\u8fc7\u6df1\u5ea6\u5f3a\u5316\u5b66\u4e60\u548c\u81ea\u5bf9\u5f08\uff0c\u53ef\u4ee5\u5b66\u4e60\u5404\u79cd\u591a\u9636\u6bb5\u535a\u5f08\u7684\u5747\u8861\u6295\u6807\u7b56\u7565\u3002\u7531\u4e8e\u4fe1\u53f7\u548c\u884c\u52a8\u7a7a\u95f4\u7684\u8fde\u7eed\u6027\uff0c\u9a8c\u8bc1\u8fd9\u7c7b\u535a\u5f08\u4e2d\u7684\u5747\u8861\u5177\u6709\u6311\u6218\u6027\u3002\u6211\u4eec\u5f15\u5165\u4e86\u4e00\u79cd\u9a8c\u8bc1\u7b97\u6cd5\uff0c\u5e76\u8bc1\u660e\u5f53\u8003\u8651\u5229\u666e\u5e0c\u8328\u8fde\u7eed\u7b56\u7565\u65f6\uff0c\u968f\u7740\u79bb\u6563\u5316\u7a0b\u5ea6\u548c\u6837\u672c\u91cf\u7684\u589e\u52a0\uff0c\u9a8c\u8bc1\u5668\u7684\u8bef\u5dee\u4f1a\u51cf\u5c0f\u3002\u501f\u52a9\u8fd9\u4e00\u65b0\u9896\u7684\u9a8c\u8bc1\u7b97\u6cd5\uff0c\u6211\u4eec\u53d1\u73b0\u4e86\u5c1a\u672a\u88ab\u89e3\u6790\u7814\u7a76\u8fc7\u7684\u6a21\u578b\u4e2d\u7684\u5747\u8861\uff0c\u5e76\u4e3a\u5df2\u6709\u7684\u8fde\u7eed\u62cd\u5356\u6a21\u578b\u53d1\u73b0\u4e86\u65b0\u7684\u975e\u5bf9\u79f0\u5747\u8861\u6295\u6807\u51fd\u6570\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2026.02443", "journal": "MS", "title": "Don\u2019t Build a Better Fax Machine: A Commentary on \u201cFighting Fire with Fire: Infusing AI into Peer Review to Sustain Quality Scholarship\u201d", "authors": ["Christian Terwiesch"], "author_details": [{"name": "Christian Terwiesch", "affiliations": ["Operations, Information and Decisions Department, The Wharton School, University of Pennsylvania, Philadelphia, Pennsylvania 19104; and The Mack Institute for Innovation Management, The Wharton School, University of Pennsylvania, Philadelphia, Pennsylvania 19104"]}], "abstract": "Artificial intelligence is increasingly being proposed as a tool to improve the efficiency of academic peer review. While such applications may alleviate reviewer shortages and enhance productivity, they largely preserve the existing architecture of scientific publishing. In this commentary I propose that AI also creates an opportunity to reimagine more fundamental aspects of how knowledge is evaluated and disseminated. Drawing on concepts from operations management and innovation, I propose disruptive alternatives that challenge the underlying design of the current process. Rather than simply helping referees review papers faster, AI may enable new models of scientific communication that are more open, timely, and adaptive to the needs of modern scholarship.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2026.02443", "title_zh": "\u522b\u9020\u4e00\u53f0\u66f4\u597d\u7684\u4f20\u771f\u673a\uff1a\u5bf9\u300a\u4ee5\u706b\u653b\u706b\uff1a\u5c06\u4eba\u5de5\u667a\u80fd\u6ce8\u5165\u540c\u884c\u8bc4\u5ba1\u4ee5\u7ef4\u6301\u5b66\u672f\u8d28\u91cf\u300b\u7684\u8bc4\u8bba", "abstract_zh": "\u4eba\u5de5\u667a\u80fd\u6b63\u8d8a\u6765\u8d8a\u591a\u5730\u88ab\u63d0\u51fa\u4f5c\u4e3a\u63d0\u9ad8\u5b66\u672f\u540c\u884c\u8bc4\u5ba1\u6548\u7387\u7684\u5de5\u5177\u3002\u5c3d\u7ba1\u6b64\u7c7b\u5e94\u7528\u53ef\u80fd\u7f13\u89e3\u8bc4\u5ba1\u4eba\u5458\u77ed\u7f3a\u5e76\u63d0\u5347\u751f\u4ea7\u529b\uff0c\u4f46\u5b83\u4eec\u5728\u5f88\u5927\u7a0b\u5ea6\u4e0a\u4fdd\u7559\u4e86\u73b0\u6709\u79d1\u5b66\u51fa\u7248\u67b6\u6784\u3002\u5728\u672c\u8bc4\u8bba\u4e2d\uff0c\u6211\u63d0\u51fa\u4eba\u5de5\u667a\u80fd\u4e5f\u63d0\u4f9b\u4e86\u91cd\u65b0\u6784\u60f3\u77e5\u8bc6\u8bc4\u4f30\u4e0e\u4f20\u64ad\u57fa\u672c\u6a21\u5f0f\u7684\u673a\u4f1a\u3002\u501f\u9274\u8fd0\u8425\u7ba1\u7406\u4e0e\u521b\u65b0\u9886\u57df\u7684\u6982\u5ff5\uff0c\u6211\u63d0\u51fa\u4e86\u5177\u6709\u98a0\u8986\u6027\u7684\u66ff\u4ee3\u65b9\u6848\uff0c\u6311\u6218\u5f53\u524d\u6d41\u7a0b\u7684\u6839\u672c\u8bbe\u8ba1\u3002\u4e0e\u5176\u4ec5\u4ec5\u5e2e\u52a9\u5ba1\u7a3f\u4eba\u66f4\u5feb\u5730\u5ba1\u9605\u8bba\u6587\uff0c\u4eba\u5de5\u667a\u80fd\u53ef\u80fd\u4fc3\u6210\u66f4\u52a0\u5f00\u653e\u3001\u53ca\u65f6\u4e14\u80fd\u9002\u5e94\u73b0\u4ee3\u5b66\u672f\u9700\u6c42\u7684\u65b0\u79d1\u5b66\u4f20\u64ad\u6a21\u5f0f\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2024.04482", "journal": "MS", "title": "On the Impossibility of Statistically Improving Empirical Optimization: A Second Order Stochastic Dominance Perspective", "authors": ["Henry Lam"], "author_details": [{"name": "Henry Lam", "affiliations": ["Department of Industrial Engineering and Operations Research, Columbia University, New York, New York 10027"]}], "abstract": "When the underlying probability distribution in a stochastic optimization is observed only through data, various data-driven formulations have been studied to obtain approximate optimal solutions. We show that no such formulations can, in a sense, theoretically improve the statistical quality of the solution obtained from empirical optimization. We argue this by proving that the first order behavior of the optimality gap against the oracle best solution, which includes both the bias and variance, for any data-driven solution second order stochastically dominates that from empirical optimization as long as suitable smoothness holds with respect to the underlying distribution. We demonstrate this impossibility of improvement in examples ranging across regularized optimization, distributionally robust optimization, parametric optimization, and Bayesian generalizations. We also discuss the connections of our results to other perspectives in statistics and data-driven optimization and illustrate practical implications in choosing among data-driven formulations.", "date": "2026-09", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.04482", "title_zh": "\u5173\u4e8e\u65e0\u6cd5\u901a\u8fc7\u7edf\u8ba1\u624b\u6bb5\u63d0\u5347\u7ecf\u9a8c\u4f18\u5316\u7684\u4e0d\u53ef\u80fd\u6027\uff1a\u57fa\u4e8e\u4e8c\u9636\u968f\u673a\u4e3b\u5bfc\u6027\u7684\u89c6\u89d2", "abstract_zh": "\u5f53\u968f\u673a\u4f18\u5316\u4e2d\u7684\u57fa\u7840\u6982\u7387\u5206\u5e03\u4ec5\u901a\u8fc7\u6570\u636e\u89c2\u6d4b\u65f6\uff0c\u5df2\u7814\u7a76\u4e86\u591a\u79cd\u6570\u636e\u9a71\u52a8\u7684\u516c\u5f0f\u4ee5\u83b7\u5f97\u8fd1\u4f3c\u6700\u4f18\u89e3\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u4ece\u7406\u8bba\u4e0a\u8bb2\uff0c\u4efb\u4f55\u8fd9\u6837\u7684\u6570\u636e\u9a71\u52a8\u65b9\u6cd5\u90fd\u65e0\u6cd5\u5728\u67d0\u79cd\u610f\u4e49\u4e0a\u63d0\u5347\u7ecf\u9a8c\u4f18\u5316\u6240\u83b7\u5f97\u89e3\u7684\u7edf\u8ba1\u8d28\u91cf\u3002\u6211\u4eec\u901a\u8fc7\u8bc1\u660e\uff0c\u5728\u6ee1\u8db3\u5173\u4e8e\u57fa\u7840\u5206\u5e03\u7684\u9002\u5f53\u5149\u6ed1\u6027\u6761\u4ef6\u4e0b\uff0c\u4efb\u4f55\u6570\u636e\u9a71\u52a8\u89e3\u7684\u6700\u4f18\u6027\u5dee\u8ddd\u76f8\u5bf9\u4e8e\u7406\u60f3\u6700\u4f18\u89e3\u7684\u4e00\u9636\u884c\u4e3a\uff0c\u4ee5\u4e8c\u9636\u968f\u673a\u4e3b\u5bfc\u7684\u65b9\u5f0f\u4f18\u4e8e\u7ecf\u9a8c\u4f18\u5316\u6240\u5f97\u7ed3\u679c\uff0c\u8be5\u7ed3\u679c\u540c\u65f6\u5305\u542b\u4e86\u504f\u5dee\u548c\u65b9\u5dee\u3002\u6211\u4eec\u5728\u6b63\u5219\u5316\u4f18\u5316\u3001\u5206\u5e03\u9c81\u68d2\u4f18\u5316\u3001\u53c2\u6570\u5316\u4f18\u5316\u4ee5\u53ca\u8d1d\u53f6\u65af\u63a8\u5e7f\u7b49\u4e0d\u540c\u573a\u666f\u4e2d\u5c55\u793a\u4e86\u8fd9\u79cd\u65e0\u6cd5\u63d0\u5347\u7684\u4e0d\u53ef\u80fd\u6027\u3002\u6211\u4eec\u8fd8\u63a2\u8ba8\u4e86\u6211\u4eec\u7684\u7ed3\u679c\u4e0e\u5176\u4ed6\u7edf\u8ba1\u5b66\u548c\u6570\u636e\u9a71\u52a8\u4f18\u5316\u89c6\u89d2\u4e4b\u95f4\u7684\u8054\u7cfb\uff0c\u5e76\u8bf4\u660e\u4e86\u5728\u9009\u62e9\u4e0d\u540c\u6570\u636e\u9a71\u52a8\u516c\u5f0f\u65f6\u7684\u5b9e\u9645\u610f\u4e49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag079", "journal": "RFS", "title": "Long Rates, Life Insurers, and Credit Spreads", "authors": ["Ziang Li"], "author_details": [{"name": "Ziang Li", "affiliations": ["Imperial College London ,"]}], "abstract": "Abstract This paper proposes a new channel through which long-term interest rates transmit to credit spreads. When life insurers carry negative duration gaps, higher rates reduce their liabilities more than assets. Rate increases therefore boost equity and risk-bearing capacity, lowering equilibrium credit spreads. Empirically, I test this channel with bond-level yields and a maturity-based discontinuity in bond ownership. Insurers\u2019 trades confirm the mechanism: after rates rise, insurers shift portfolios towards riskier, high-yield bonds. As rates increase, bonds more heavily held by life insurers experience greater spread reductions. The results show that institutional duration mismatch shapes credit spreads and corporate financing conditions.", "date": "2026-08-31", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag079", "title_zh": "\u957f\u671f\u5229\u7387\u3001\u4eba\u5bff\u4fdd\u9669\u516c\u53f8\u4e0e\u4fe1\u7528\u5229\u5dee", "abstract_zh": "\u672c\u6587\u63d0\u51fa\u4e86\u4e00\u6761\u957f\u671f\u5229\u7387\u5f71\u54cd\u4fe1\u7528\u5229\u5dee\u7684\u65b0\u6e20\u9053\u3002\u5f53\u4eba\u5bff\u4fdd\u9669\u516c\u53f8\u5b58\u5728\u8d1f\u4e45\u671f\u7f3a\u53e3\u65f6\uff0c\u5229\u7387\u4e0a\u5347\u4f1a\u4f7f\u5176\u8d1f\u503a\u7684\u51cf\u5c11\u5e45\u5ea6\u5927\u4e8e\u8d44\u4ea7\u7684\u51cf\u5c11\u5e45\u5ea6\u3002\u56e0\u6b64\uff0c\u5229\u7387\u4e0a\u5347\u4f1a\u589e\u5f3a\u80a1\u6743\u4ef7\u503c\u548c\u98ce\u9669\u627f\u53d7\u80fd\u529b\uff0c\u4ece\u800c\u964d\u4f4e\u5747\u8861\u4fe1\u7528\u5229\u5dee\u3002\u901a\u8fc7\u503a\u5238\u5c42\u9762\u7684\u6536\u76ca\u7387\u548c\u57fa\u4e8e\u671f\u9650\u7684\u503a\u5238\u6301\u6709\u91cf\u65ad\u70b9\uff0c\u672c\u6587\u5b9e\u8bc1\u68c0\u9a8c\u4e86\u8fd9\u4e00\u673a\u5236\u3002\u4fdd\u9669\u516c\u53f8\u7684\u4ea4\u6613\u6570\u636e\u8bc1\u5b9e\u4e86\u8be5\u673a\u5236\uff1a\u5728\u5229\u7387\u4e0a\u5347\u540e\uff0c\u4fdd\u9669\u516c\u53f8\u4f1a\u5c06\u5176\u6295\u8d44\u7ec4\u5408\u8f6c\u5411\u66f4\u5177\u98ce\u9669\u3001\u6536\u76ca\u7387\u66f4\u9ad8\u7684\u503a\u5238\u3002\u968f\u7740\u5229\u7387\u4e0a\u5347\uff0c\u88ab\u4eba\u5bff\u4fdd\u9669\u516c\u53f8\u6301\u6709\u8f83\u591a\u7684\u503a\u5238\u5176\u4fe1\u7528\u5229\u5dee\u7684\u7f29\u5c0f\u66f4\u4e3a\u663e\u8457\u3002\u7ed3\u679c\u8868\u660e\uff0c\u673a\u6784\u7684\u4e45\u671f\u9519\u914d\u4f1a\u5f71\u54cd\u4fe1\u7528\u5229\u5dee\u548c\u4f01\u4e1a\u878d\u8d44\u6761\u4ef6\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag097", "journal": "REStud", "title": "Public Employee Pensions and Municipal Insolvency", "authors": ["Sean Myers"], "author_details": [{"name": "Sean Myers", "affiliations": ["The Wharton School, University of Pennsylvania ,"]}], "abstract": "Abstract This paper studies how municipal governments jointly manage spending, credit market borrowing, and a public employee pension system. I model governments as levered investors who must meet non-defaultable pension obligations and may value government spending more than citizens. I quantify the model using data on California cities, including a new record of fiscal emergencies, tax increases required to maintain essential city services. After the financial crisis depleted pension funds, cities engaged in excessive risk-taking: the fiscal emergency option encouraged gambling for resurrection that kept cities vulnerable to shocks well into the recovery. To correct this problem, a savings requirement works better than a restriction on risk-taking or a pension funding requirement. The policy experiments emphasize that effective policies need to target the combined pension and bond finances, as policies that only target one, such as a pension funding requirement, are undermined by endogenous changes to the other.", "date": "2026-08-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag097", "title_zh": "\u516c\u5171\u5458\u5de5\u517b\u8001\u91d1\u4e0e\u5e02\u653f\u7834\u4ea7", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5e02\u653f\u653f\u5e9c\u5982\u4f55\u5171\u540c\u7ba1\u7406\u652f\u51fa\u3001\u4fe1\u8d37\u5e02\u573a\u501f\u8d37\u4ee5\u53ca\u516c\u5171\u5458\u5de5\u517b\u8001\u91d1\u4f53\u7cfb\u3002\u6211\u5c06\u653f\u5e9c\u5efa\u6a21\u4e3a\u5177\u6709\u6760\u6746\u7684\u6295\u8d44\u8005\uff0c\u5fc5\u987b\u5c65\u884c\u4e0d\u53ef\u8fdd\u7ea6\u7684\u517b\u8001\u91d1\u4e49\u52a1\uff0c\u5e76\u53ef\u80fd\u6bd4\u516c\u6c11\u66f4\u91cd\u89c6\u653f\u5e9c\u652f\u51fa\u3002\u6211\u5229\u7528\u52a0\u5229\u798f\u5c3c\u4e9a\u57ce\u5e02\u7684\u6570\u636e\u5bf9\u6a21\u578b\u8fdb\u884c\u91cf\u5316\uff0c\u5305\u62ec\u4e00\u9879\u65b0\u7684\u8d22\u653f\u7d27\u6025\u60c5\u51b5\u8bb0\u5f55\uff0c\u4ee5\u53ca\u4e3a\u7ef4\u6301\u57fa\u672c\u57ce\u5e02\u670d\u52a1\u800c\u9700\u8981\u63d0\u9ad8\u7a0e\u6536\u7684\u60c5\u51b5\u3002\u5728\u91d1\u878d\u5371\u673a\u671f\u95f4\uff0c\u517b\u8001\u91d1\u57fa\u91d1\u88ab\u8017\u5c3d\u540e\uff0c\u57ce\u5e02\u51fa\u73b0\u4e86\u8fc7\u5ea6\u5192\u9669\u884c\u4e3a\uff1a\u8d22\u653f\u7d27\u6025\u9009\u9879\u9f13\u52b1\u4e86\u201c\u590d\u6d3b\u8d4c\u535a\u201d\uff0c\u4f7f\u57ce\u5e02\u5728\u590d\u82cf\u8fc7\u7a0b\u4e2d\u4ecd\u957f\u671f\u9762\u4e34\u51b2\u51fb\u3002\u4e3a\u89e3\u51b3\u8fd9\u4e00\u95ee\u9898\uff0c\u50a8\u84c4\u8981\u6c42\u6bd4\u9650\u5236\u98ce\u9669\u627f\u62c5\u6216\u517b\u8001\u91d1\u7b79\u8d44\u8981\u6c42\u66f4\u6709\u6548\u3002\u653f\u7b56\u5b9e\u9a8c\u8868\u660e\uff0c\u6709\u6548\u7684\u653f\u7b56\u5fc5\u987b\u540c\u65f6\u9488\u5bf9\u517b\u8001\u91d1\u548c\u503a\u5238\u8d22\u52a1\u8fdb\u884c\u8c03\u6574\uff0c\u4ec5\u9488\u5bf9\u5355\u4e00\u65b9\u9762\u7684\u653f\u7b56\uff08\u5982\u517b\u8001\u91d1\u7b79\u8d44\u8981\u6c42\uff09\u4f1a\u56e0\u53e6\u4e00\u90e8\u5206\u7684\u5185\u751f\u53d8\u5316\u800c\u5931\u6548\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005", "\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1287/mnsc.2024.05042", "journal": "MS", "title": "Public Enforcement and Initial Public Offering Reporting Quality in Weak Institutional Environments: Evidence from a Random Experiment in China", "authors": ["Manyi Fan", "Kai Guo", "Bin Ke"], "author_details": [{"name": "Manyi Fan", "affiliations": ["Department of Accountancy, City University of Hong Kong, Kowloon, Hong Kong"]}, {"name": "Kai Guo", "affiliations": ["Department of Accounting, Antai College of Economics & Management, Shanghai Jiao Tong University, Shanghai, 200030 China"]}, {"name": "Bin Ke", "affiliations": ["Department of Accounting, National University of Singapore Business School, National University of Singapore, Singapore 119245"]}], "abstract": "Using China\u2019s randomized pre-initial public offering on-site inspection program, we examine the causal effects of proactive public enforcement on the financial reporting quality of initial public offering applicants. Our analysis shows that the program enhances the reporting quality of selected applicants by screening out firms with questionable financial disclosures. More importantly, it generates a significant deterrence effect, discouraging future applicants from submitting low-quality financial reports. However, we also find that public enforcement can lead to the rejection of some firms that may otherwise merit approval. These findings highlight both the benefits and costs of employing public enforcement to improve financial reporting in settings with weak institutional oversight.", "date": "2026-08-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.05042", "title_zh": "\u516c\u5171\u6267\u6cd5\u5728\u5236\u5ea6\u8584\u5f31\u73af\u5883\u4e0b\u7684\u9996\u6b21\u516c\u5f00\u52df\u80a1\u4fe1\u606f\u62ab\u9732\u8d28\u91cf\uff1a\u6765\u81ea\u4e2d\u56fd\u7684\u4e00\u9879\u968f\u673a\u5b9e\u9a8c\u8bc1\u636e", "abstract_zh": "\u5229\u7528\u4e2d\u56fd\u5728\u9996\u6b21\u516c\u5f00\u52df\u80a1\u524d\u8fdb\u884c\u73b0\u573a\u68c0\u67e5\u7684\u968f\u673a\u5316\u7a0b\u5e8f\uff0c\u6211\u4eec\u7814\u7a76\u4e86\u4e3b\u52a8\u516c\u5171\u6267\u6cd5\u5bf9\u9996\u6b21\u516c\u5f00\u52df\u80a1\u7533\u8bf7\u4eba\u8d22\u52a1\u4fe1\u606f\u62ab\u9732\u8d28\u91cf\u7684\u56e0\u679c\u5f71\u54cd\u3002\u6211\u4eec\u7684\u5206\u6790\u8868\u660e\uff0c\u8be5\u7a0b\u5e8f\u901a\u8fc7\u7b5b\u9009\u51fa\u8d22\u52a1\u62ab\u9732\u5b58\u7591\u7684\u516c\u53f8\uff0c\u63d0\u5347\u4e86\u88ab\u9009\u4e2d\u7533\u8bf7\u4eba\u7684\u4fe1\u606f\u62ab\u9732\u8d28\u91cf\u3002\u66f4\u91cd\u8981\u7684\u662f\uff0c\u5b83\u4ea7\u751f\u4e86\u663e\u8457\u7684\u5a01\u6151\u6548\u5e94\uff0c\u6291\u5236\u4e86\u672a\u6765\u7533\u8bf7\u4eba\u63d0\u4ea4\u4f4e\u8d28\u91cf\u8d22\u52a1\u62a5\u544a\u7684\u884c\u4e3a\u3002\u7136\u800c\uff0c\u6211\u4eec\u4e5f\u53d1\u73b0\uff0c\u516c\u5171\u6267\u6cd5\u53ef\u80fd\u5bfc\u81f4\u4e00\u4e9b\u672c\u5e94\u83b7\u5f97\u6279\u51c6\u7684\u516c\u53f8\u88ab\u62d2\u4e4b\u95e8\u5916\u3002\u8fd9\u4e9b\u53d1\u73b0\u51f8\u663e\u4e86\u5728\u5236\u5ea6\u76d1\u7763\u8584\u5f31\u7684\u73af\u5883\u4e2d\uff0c\u91c7\u7528\u516c\u5171\u6267\u6cd5\u6539\u5584\u8d22\u52a1\u4fe1\u606f\u62ab\u9732\u6240\u5e26\u6765\u7684\u76ca\u5904\u4e0e\u6210\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.06477", "journal": "MS", "title": "Harmonizing Safety and Speed: A Human-Algorithm Approach to Enhance the FDA\u2019s Medical Device Clearance Policy", "authors": ["Mohammad Zhalechian", "Soroush Saghafian", "Omar Robles"], "author_details": [{"name": "Mohammad Zhalechian", "affiliations": ["Kelley School of Business, Indiana University, Bloomington, Indiana 47405"]}, {"name": "Soroush Saghafian", "affiliations": ["Harvard Kennedy School, Harvard University, Cambridge, Massachusetts 02138"]}, {"name": "Omar Robles", "affiliations": ["Emerging Health Consulting, Armonk, New York 10504"]}], "abstract": "The United States Food and Drug Administration (FDA)\u2019s 510(k) pathway allows manufacturers to gain medical device approval by demonstrating substantial equivalence to a legally marketed device. However, the inherent ambiguity of this regulatory procedure has been associated with high recall among many devices cleared through this pathway, raising significant safety concerns. In this paper, we develop a combined human-algorithm approach to assist the FDA in improving its 510(k) medical device clearance process by reducing recall risk and regulatory workload. We first develop machine learning methods to estimate the risk of recall of 510(k) medical devices based on the information available at the time of submission. We then propose a data-driven clearance policy that recommends acceptance, rejection, or deferral to FDA\u2019s committees for in-depth evaluation. We conduct an empirical study using a unique data set of over 31,000 submissions that we assembled based on data sources from the FDA and Centers for Medicare and Medicaid Services. Compared to the FDA\u2019s current practice, which has a recall rate of 10.3% and a normalized workload measure of 100%, a conservative evaluation of our policy shows a 32.9% improvement in the recall rate and a 40.5% reduction in the workload. Our analyses further suggest annual cost savings of approximately $1.7 billion for the healthcare system driven by avoided replacement costs, which is equivalent to 1.1% of the entire United States annual medical device expenditure. Our findings highlight the value of a holistic and data-driven approach to improve the FDA\u2019s current 510(k) pathway.", "date": "2026-08-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06477", "title_zh": "\u5b89\u5168\u4e0e\u6548\u7387\u7684\u548c\u8c10\u7edf\u4e00\uff1a\u4e00\u79cd\u4eba\u673a\u534f\u540c\u65b9\u6cd5\u4ee5\u4f18\u5316FDA\u533b\u7597\u5668\u68b0\u6e05\u5173\u653f\u7b56", "abstract_zh": "\u7f8e\u56fd\u98df\u54c1\u836f\u54c1\u76d1\u7763\u7ba1\u7406\u5c40\uff08FDA\uff09\u7684510(k)\u9014\u5f84\u5141\u8bb8\u5236\u9020\u5546\u901a\u8fc7\u8bc1\u660e\u5176\u533b\u7597\u5668\u68b0\u4e0e\u5df2\u4e0a\u5e02\u5408\u6cd5\u4ea7\u54c1\u5177\u6709\u5b9e\u8d28\u7b49\u6548\u6027\u6765\u83b7\u5f97\u6279\u51c6\u3002\u7136\u800c\uff0c\u8be5\u76d1\u7ba1\u7a0b\u5e8f\u56fa\u6709\u7684\u6a21\u7cca\u6027\u4e0e\u5927\u91cf\u901a\u8fc7\u8be5\u9014\u5f84\u83b7\u6279\u7684\u533b\u7597\u5668\u68b0\u53ec\u56de\u4e8b\u4ef6\u76f8\u5173\u8054\uff0c\u5f15\u53d1\u4e86\u4e25\u91cd\u7684\u5b89\u5168\u62c5\u5fe7\u3002\u672c\u6587\u63d0\u51fa\u4e00\u79cd\u7ed3\u5408\u4eba\u7c7b\u4e0e\u7b97\u6cd5\u7684\u65b9\u6cd5\uff0c\u4ee5\u534f\u52a9FDA\u6539\u8fdb\u5176510(k)\u533b\u7597\u5668\u68b0\u6e05\u5173\u6d41\u7a0b\uff0c\u964d\u4f4e\u53ec\u56de\u98ce\u9669\u5e76\u51cf\u8f7b\u76d1\u7ba1\u5de5\u4f5c\u8d1f\u62c5\u3002\u6211\u4eec\u9996\u5148\u5f00\u53d1\u4e86\u673a\u5668\u5b66\u4e60\u65b9\u6cd5\uff0c\u57fa\u4e8e\u63d0\u4ea4\u65f6\u53ef\u83b7\u5f97\u7684\u4fe1\u606f\u6765\u4f30\u7b97510(k)\u533b\u7597\u5668\u68b0\u7684\u53ec\u56de\u98ce\u9669\u3002\u968f\u540e\uff0c\u6211\u4eec\u63d0\u51fa\u4e00\u79cd\u6570\u636e\u9a71\u52a8\u7684\u6e05\u5173\u653f\u7b56\uff0c\u5efa\u8baeFDA\u59d4\u5458\u4f1a\u63a5\u53d7\u3001\u62d2\u7edd\u6216\u63a8\u8fdf\u8bc4\u4f30\u4ee5\u8fdb\u884c\u6df1\u5165\u5ba1\u67e5\u3002\u6211\u4eec\u57fa\u4e8eFDA\u548c\u533b\u7597\u4fdd\u9669\u4e0e\u533b\u7597\u63f4\u52a9\u670d\u52a1\u4e2d\u5fc3\u7684\u6570\u636e\u6e90\uff0c\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u8d85\u8fc731,000\u4e2a\u63d0\u4ea4\u6848\u4f8b\u7684\u72ec\u5bb6\u6570\u636e\u96c6\u3002\u4e0eFDA\u73b0\u884c\u505a\u6cd5\u76f8\u6bd4\uff0c\u5176\u53ec\u56de\u7387\u4e3a10.3%\uff0c\u5de5\u4f5c\u91cf\u6807\u51c6\u5316\u6307\u6807\u4e3a100%\uff0c\u6211\u4eec\u4fdd\u5b88\u8bc4\u4f30\u7684\u653f\u7b56\u663e\u793a\u53ec\u56de\u7387\u964d\u4f4e\u4e8632.9%\uff0c\u5de5\u4f5c\u91cf\u51cf\u5c11\u4e8640.5%\u3002\u6211\u4eec\u7684\u5206\u6790\u8fdb\u4e00\u6b65\u8868\u660e\uff0c\u901a\u8fc7\u907f\u514d\u66ff\u6362\u6210\u672c\uff0c\u6bcf\u5e74\u53ef\u4e3a\u533b\u7597\u4f53\u7cfb\u8282\u7701\u7ea617\u4ebf\u7f8e\u5143\uff0c\u76f8\u5f53\u4e8e\u7f8e\u56fd\u5168\u5e74\u533b\u7597\u5668\u68b0\u652f\u51fa\u76841.1%\u3002\u672c\u7814\u7a76\u51f8\u663e\u4e86\u91c7\u7528\u6574\u4f53\u6027\u3001\u6570\u636e\u9a71\u52a8\u65b9\u6cd5\u6539\u8fdbFDA\u73b0\u884c510(k)\u9014\u5f84\u7684\u4ef7\u503c\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2024.04439", "journal": "MS", "title": "Disintermediation Governance and Complementor Innovation: An Empirical Look at Amazon.com", "authors": ["Xia Han", "Gaoyang Cai", "Grace Gu"], "author_details": [{"name": "Xia Han", "affiliations": ["Faculty of Business for Science and Technology, School of Management, University of Science and Technology of China, Hefei 230026, China"]}, {"name": "Gaoyang Cai", "affiliations": ["Department of Marketing, Business School, The Chinese University of Hong Kong, Hong Kong 999077, China"]}, {"name": "Grace Gu", "affiliations": ["Marshall School of Business, University of Southern California, Los Angeles, California 90089"]}], "abstract": "This study investigates how the platform\u2019s disintermediation governance policy (i.e., the policy that disciplines complementors and consumers circumventing the platform to transact directly) affects complementors\u2019 product innovation and launching strategies. We leverage a change in the Communication Guideline on Amazon.com (i.e., the focal platform), which prohibits complementors (i.e., sellers) from sending external website links, telephone numbers, and email addresses to buyers in direct messaging, as a policy shock to Amazon complementors. By conducting a difference-in-differences analysis, we find that the governance policy significantly reduces product innovation on the focal platform among complementors with direct selling channels as measured by the number of new products and the innovativeness of new products. These main effects are mitigated by complementor reputation on Amazon and complementor multihoming. Mechanism analyses show that complementors with direct selling channels increase the number of new products launched through those channels after the policy change (i.e., the switching effect). Moreover, complementors tend to strategically switch innovative and high-value products away from the focal platform while leaving less innovative but price-competitive products on it to attract Amazon consumers before diverting to their direct selling channels (i.e., the bait effect). Our results have implications for platform governance policies regarding disintermediation and its impact on complementor product innovation and launch strategies both on and off the focal platform.", "date": "2026-08-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.04439", "title_zh": "\u53bb\u4e2d\u4ecb\u5316\u6cbb\u7406\u4e0e\u4e92\u8865\u8005\u521b\u65b0\uff1a\u5bf9\u4e9a\u9a6c\u900a\u5e73\u53f0\u7684\u5b9e\u8bc1\u7814\u7a76", "abstract_zh": "\u672c\u7814\u7a76\u63a2\u8ba8\u4e86\u5e73\u53f0\u53bb\u4e2d\u4ecb\u5316\u6cbb\u7406\u653f\u7b56\uff08\u5373\u5bf9\u7ed5\u8fc7\u5e73\u53f0\u76f4\u63a5\u4ea4\u6613\u7684\u4e92\u8865\u8005\u548c\u6d88\u8d39\u8005\u8fdb\u884c\u7ea6\u675f\u7684\u653f\u7b56\uff09\u5982\u4f55\u5f71\u54cd\u4e92\u8865\u8005\u7684\u4ea7\u54c1\u521b\u65b0\u53ca\u4ea7\u54c1\u53d1\u5e03\u7b56\u7565\u3002\u6211\u4eec\u5229\u7528\u4e9a\u9a6c\u900a\u5e73\u53f0\uff08\u5373\u6838\u5fc3\u5e73\u53f0\uff09\u901a\u4fe1\u6307\u5357\u7684\u53d8\u66f4\u4f5c\u4e3a\u653f\u7b56\u51b2\u51fb\uff0c\u8be5\u6307\u5357\u7981\u6b62\u4e92\u8865\u8005\uff08\u5373\u5356\u5bb6\uff09\u5728\u76f4\u63a5\u6d88\u606f\u4e2d\u5411\u4e70\u5bb6\u63d0\u4f9b\u5916\u90e8\u7f51\u7ad9\u94fe\u63a5\u3001\u7535\u8bdd\u53f7\u7801\u548c\u7535\u5b50\u90ae\u4ef6\u5730\u5740\u3002\u901a\u8fc7\u5dee\u5206\u5dee\u5206\u5206\u6790\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u8be5\u6cbb\u7406\u653f\u7b56\u663e\u8457\u964d\u4f4e\u4e86\u62e5\u6709\u76f4\u63a5\u9500\u552e\u6e20\u9053\u7684\u4e92\u8865\u8005\u5728\u6838\u5fc3\u5e73\u53f0\u4e0a\u7684\u4ea7\u54c1\u521b\u65b0\uff0c\u5177\u4f53\u8868\u73b0\u4e3a\u65b0\u4ea7\u54c1\u6570\u91cf\u548c\u65b0\u4ea7\u54c1\u7684\u521b\u65b0\u6027\u5747\u4e0b\u964d\u3002\u8fd9\u4e00\u4e3b\u8981\u6548\u5e94\u53d7\u5230\u4e92\u8865\u8005\u5728\u4e9a\u9a6c\u900a\u5e73\u53f0\u58f0\u8a89\u4ee5\u53ca\u4e92\u8865\u8005\u591a\u6e20\u9053\u7ecf\u8425\u7a0b\u5ea6\u7684\u7f13\u89e3\u3002\u673a\u5236\u5206\u6790\u8868\u660e\uff0c\u62e5\u6709\u76f4\u63a5\u9500\u552e\u6e20\u9053\u7684\u4e92\u8865\u8005\u5728\u653f\u7b56\u53d8\u66f4\u540e\uff0c\u901a\u8fc7\u8fd9\u4e9b\u6e20\u9053\u589e\u52a0\u4e86\u65b0\u4ea7\u54c1\u7684\u53d1\u5e03\u6570\u91cf\uff08\u5373\u5207\u6362\u6548\u5e94\uff09\u3002\u6b64\u5916\uff0c\u4e92\u8865\u8005\u503e\u5411\u4e8e\u6218\u7565\u6027\u5730\u5c06\u521b\u65b0\u6027\u5f3a\u4e14\u4ef7\u503c\u9ad8\u7684\u4ea7\u54c1\u4ece\u6838\u5fc3\u5e73\u53f0\u8f6c\u79fb\u51fa\u53bb\uff0c\u540c\u65f6\u4fdd\u7559\u521b\u65b0\u6027\u8f83\u4f4e\u4f46\u4ef7\u683c\u66f4\u5177\u7ade\u4e89\u529b\u7684\u4ea7\u54c1\u7559\u5728\u5e73\u53f0\u4ee5\u5438\u5f15\u4e9a\u9a6c\u900a\u6d88\u8d39\u8005\uff0c\u7136\u540e\u518d\u5c06\u5176\u8f6c\u79fb\u5230\u76f4\u63a5\u9500\u552e\u6e20\u9053\uff08\u5373\u8bf1\u9975\u6548\u5e94\uff09\u3002\u672c\u7814\u7a76\u7ed3\u679c\u5bf9\u5e73\u53f0\u5173\u4e8e\u53bb\u4e2d\u4ecb\u5316\u7684\u6cbb\u7406\u653f\u7b56\u53ca\u5176\u5bf9\u4e92\u8865\u8005\u4ea7\u54c1\u521b\u65b0\u548c\u53d1\u5e03\u7b56\u7565\u5728\u5e73\u53f0\u5185\u5916\u7684\u5f71\u54cd\u5177\u6709\u91cd\u8981\u542f\u793a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.03801", "journal": "MS", "title": "Managing Perishable Inventory Systems with Positive Lead Times: Inventory Position vs. Projected Inventory Level", "authors": ["Jinzhi Bu", "Xiting Gong", "Huanyu Yin"], "author_details": [{"name": "Jinzhi Bu", "affiliations": ["Department of Logistics and Maritime Studies, Faculty of Business, The Hong Kong Polytechnic University, Hung Hom, Kowloon, Hong Kong"]}, {"name": "Xiting Gong", "affiliations": ["Department of Decisions, Operations and Technology, CUHK Business School, The Chinese University of Hong Kong, Shatin, New Territories, Hong Kong"]}, {"name": "Huanyu Yin", "affiliations": ["Department of Supply Chain Management, College of Economics, Shenzhen University, Shenzhen, Guangdong 518060, China"]}], "abstract": "We study periodic review perishable inventory systems with a fixed product lifetime, positive replenishment lead times, and a general issuance policy under the average cost criterion. The optimal replenishment policy for such systems is notoriously complex and computationally intractable because of the curse of dimensionality. To address this challenge, we propose a class of projected inventory level (PIL) policies, which maintain a constant expected on-hand inventory level, and compare them with conventional base-stock (BS) policies that maintain a constant inventory position. For both backlogging and lost-sales systems, we show that the best PIL policy is asymptotically optimal with large unit penalty costs for a broad class of unbounded demand distributions. When demand is bounded and the unit penalty cost is sufficiently large, we prove that the best BS policy is optimal under first-in-first-out issuance, whereas the best PIL policy is optimal under last-in-first-out issuance (under certain conditions). Furthermore, we show that both policies are asymptotically optimal as the demand population size grows large, and their optimality gaps diminish exponentially fast in backlogging systems under a broad range of issuance policies. To facilitate computation, we introduce a class of approximate PIL (APIL) policies and extend most theoretical results for PIL to the APIL policy. Numerical results show that both PIL and APIL policies perform very close to optimal and significantly outperform BS policies.", "date": "2026-08-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.03801", "title_zh": "\u5177\u6709\u6b63\u8865\u8d27\u5468\u671f\u65f6\u95f4\u7684\u6613\u8150\u5e93\u5b58\u7cfb\u7edf\uff1a\u5e93\u5b58\u4f4d\u7f6e\u4e0e\u6295\u5f71\u5e93\u5b58\u6c34\u5e73", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5177\u6709\u56fa\u5b9a\u4ea7\u54c1\u5bff\u547d\u3001\u6b63\u8865\u8d27\u5468\u671f\u65f6\u95f4\u548c\u4e00\u822c\u53d1\u653e\u653f\u7b56\u7684\u5468\u671f\u6027\u5ba1\u67e5\u6613\u8150\u5e93\u5b58\u7cfb\u7edf\uff0c\u5728\u5e73\u5747\u6210\u672c\u51c6\u5219\u4e0b\u3002\u6b64\u7c7b\u7cfb\u7edf\u7684\u6700\u4f18\u8865\u8d27\u7b56\u7565\u56e0\u5176\u7ef4\u5ea6\u707e\u96be\u800c\u4f17\u6240\u5468\u77e5\u5730\u590d\u6742\u4e14\u8ba1\u7b97\u4e0a\u4e0d\u53ef\u884c\u3002\u4e3a\u5e94\u5bf9\u8fd9\u4e00\u6311\u6218\uff0c\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u7c7b\u6295\u5f71\u5e93\u5b58\u6c34\u5e73\uff08PIL\uff09\u7b56\u7565\uff0c\u5373\u7ef4\u6301\u6052\u5b9a\u7684\u9884\u671f\u5728\u5e93\u5e93\u5b58\u6c34\u5e73\uff0c\u5e76\u5c06\u5176\u4e0e\u4f20\u7edf\u7684\u57fa\u5e93\u5b58\uff08BS\uff09\u7b56\u7565\uff08\u5373\u7ef4\u6301\u6052\u5b9a\u7684\u5e93\u5b58\u4f4d\u7f6e\uff09\u8fdb\u884c\u6bd4\u8f83\u3002\u5bf9\u4e8e\u5141\u8bb8\u7f3a\u8d27\u548c\u4e22\u5931\u9500\u552e\u7684\u7cfb\u7edf\uff0c\u6211\u4eec\u8bc1\u660e\uff0c\u5728\u5355\u4f4d\u60e9\u7f5a\u6210\u672c\u8f83\u5927\u65f6\uff0c\u5bf9\u4e8e\u4e00\u5927\u7c7b\u65e0\u754c\u9700\u6c42\u5206\u5e03\uff0c\u6700\u4f73PIL\u7b56\u7565\u5728\u6e10\u8fd1\u610f\u4e49\u4e0a\u662f\u6700\u4f18\u7684\u3002\u5f53\u9700\u6c42\u6709\u754c\u4e14\u5355\u4f4d\u60e9\u7f5a\u6210\u672c\u8db3\u591f\u5927\u65f6\uff0c\u6211\u4eec\u8bc1\u660e\u5728\u5148\u8fdb\u5148\u51fa\uff08FIFO\uff09\u53d1\u653e\u4e0b\uff0c\u6700\u4f73BS\u7b56\u7565\u662f\u6700\u4f18\u7684\uff0c\u800c\u5728\u540e\u8fdb\u5148\u51fa\uff08LIFO\uff09\u53d1\u653e\u4e0b\uff0c\u6700\u4f73PIL\u7b56\u7565\u662f\u6700\u4f18\u7684\uff08\u5728\u67d0\u4e9b\u6761\u4ef6\u4e0b\uff09\u3002\u6b64\u5916\uff0c\u6211\u4eec\u8bc1\u660e\u5f53\u9700\u6c42\u7fa4\u4f53\u89c4\u6a21\u589e\u5927\u65f6\uff0c\u4e24\u79cd\u7b56\u7565\u5728\u6e10\u8fd1\u610f\u4e49\u4e0a\u90fd\u662f\u6700\u4f18\u7684\uff0c\u4e14\u5728\u7f3a\u8d27\u7cfb\u7edf\u4e2d\uff0c\u5176\u6700\u4f18\u6027\u5dee\u8ddd\u5728\u5e7f\u6cdb\u53d1\u653e\u7b56\u7565\u4e0b\u4ee5\u6307\u6570\u901f\u5ea6\u9012\u51cf\u3002\u4e3a\u4e86\u4fbf\u4e8e\u8ba1\u7b97\uff0c\u6211\u4eec\u5f15\u5165\u4e86\u4e00\u7c7b\u8fd1\u4f3cPIL\uff08APIL\uff09\u7b56\u7565\uff0c\u5e76\u5c06\u5927\u591a\u6570\u5173\u4e8ePIL\u7684\u7406\u8bba\u7ed3\u679c\u6269\u5c55\u5230APIL\u7b56\u7565\u4e0a\u3002\u6570\u503c\u7ed3\u679c\u8868\u660e\uff0cPIL\u548cAPIL\u7b56\u7565\u7684\u6027\u80fd\u975e\u5e38\u63a5\u8fd1\u6700\u4f18\uff0c\u5e76\u663e\u8457\u4f18\u4e8eBS\u7b56\u7565\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2025.02314", "journal": "MS", "title": "Centralization vs. Decentralization: First Evidence from the Laboratory", "authors": ["Gabriele Camera", "Gary Charness", "Nir Chemaya"], "author_details": [{"name": "Gabriele Camera", "affiliations": ["Economic Science Institute, Chapman University, Orange, California 92866"]}, {"name": "Gary Charness", "affiliations": ["Department of Economics, University of California, Santa Barbara, California 93106"]}, {"name": "Nir Chemaya", "affiliations": ["Department of Economics, Ben Gurion University of the Negev, Beer Sheva 8410501, Israel"]}], "abstract": "The future architecture of financial systems is a subject of contention, with centralized and decentralized governance proponents. Here, we ask the following question. Would the architecture affect the quality of decision making? We propose a game where financial network participants demarcate the ownership of claims to income. This governance task can be decentralized (shared authority), centralized (single authority), or hybrid (alternating authority). Without communication, all architectures supported poor outcomes. With communication, decentralization ensured good governance and maximum profits, whereas centralization did not\u2014lowering communication\u2019s potency in promoting socially optimal decisions. This indicates that there is scope for decentralization in innovating financial institutions.", "date": "2026-08-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.02314", "title_zh": "\u96c6\u4e2d\u5316 vs. \u5206\u6563\u5316\uff1a\u6765\u81ea\u5b9e\u9a8c\u5ba4\u7684\u9996\u4e2a\u8bc1\u636e", "abstract_zh": "\u91d1\u878d\u7cfb\u7edf\u7684\u672a\u6765\u67b6\u6784\u662f\u4e89\u8bae\u7684\u7126\u70b9\uff0c\u96c6\u4e2d\u6cbb\u7406\u4e0e\u5206\u6563\u6cbb\u7406\u7684\u652f\u6301\u8005\u5404\u6267\u4e00\u8bcd\u3002\u672c\u6587\u63d0\u51fa\u4e00\u4e2a\u95ee\u9898\uff1a\u67b6\u6784\u662f\u5426\u4f1a\u5f71\u54cd\u51b3\u7b56\u8d28\u91cf\uff1f\u6211\u4eec\u8bbe\u8ba1\u4e86\u4e00\u4e2a\u535a\u5f08\uff0c\u5176\u4e2d\u91d1\u878d\u7f51\u7edc\u53c2\u4e0e\u8005\u5212\u5206\u5bf9\u6536\u5165\u4e3b\u5f20\u7684\u6240\u6709\u6743\u3002\u8fd9\u4e00\u6cbb\u7406\u4efb\u52a1\u53ef\u4ee5\u662f\u5206\u6563\u5316\uff08\u5171\u4eab\u6743\u529b\uff09\u3001\u96c6\u4e2d\u5316\uff08\u5355\u4e00\u6743\u529b\uff09\u6216\u6df7\u5408\u5316\uff08\u4ea4\u66ff\u6743\u529b\uff09\u3002\u5728\u6ca1\u6709\u6c9f\u901a\u7684\u60c5\u51b5\u4e0b\uff0c\u6240\u6709\u67b6\u6784\u90fd\u5bfc\u81f4\u4e86\u4e0d\u826f\u7ed3\u679c\uff1b\u5728\u6709\u6c9f\u901a\u7684\u60c5\u51b5\u4e0b\uff0c\u5206\u6563\u5316\u786e\u4fdd\u4e86\u826f\u597d\u7684\u6cbb\u7406\u548c\u6700\u5927\u5229\u6da6\uff0c\u800c\u96c6\u4e2d\u5316\u5219\u672a\u80fd\u5b9e\u73b0\u2014\u2014\u8fd9\u8868\u660e\u6c9f\u901a\u5728\u4fc3\u8fdb\u793e\u4f1a\u6700\u4f18\u51b3\u7b56\u65b9\u9762\u7684\u4f5c\u7528\u6709\u9650\u3002\u8fd9\u8868\u660e\u5728\u521b\u65b0\u91d1\u878d\u673a\u6784\u65b9\u9762\u5b58\u5728\u5206\u6563\u5316\u7684\u7a7a\u95f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/restud/rdag082", "journal": "REStud", "title": "Labor Supply and the Pension Contribution-Benefit Link", "authors": ["Eric French", "Attila Lindner", "Cormac O\u2019Dea", "Tom Zawisza"], "author_details": [{"name": "Eric French", "affiliations": ["Cambridge and IFS"]}, {"name": "Attila Lindner", "affiliations": ["UCL and IFS"]}, {"name": "Cormac O\u2019Dea", "affiliations": ["Yale, NBER, IFS"]}, {"name": "Tom Zawisza", "affiliations": ["OECD and IFS"]}], "abstract": "Abstract We estimate the impact of public pension incentives on labor supply far from the normal retirement age by exploiting Poland's switch from a Defined Benefit to a Notional Defined Contribution (NDC) scheme. This reform created a sharp cohort-based discontinuity in the link between current pension contributions and future benefits. Using this discontinuity and the universe of taxpayers, we estimate an employment elasticity with respect to the net return to work of 0.51 for men at ages 51-54. We estimate a lifecycle model to match these responses and discuss the broader implications of the reform. The shift to NDC reallocates work incentives over the lifecycle, strengthening incentives at younger ages, when labor supply is relatively inelastic, and weakening them at older ages, when labor supply is more elastic. This reallocation of work incentives tends to reduce aggregate lifecycle labor supply, which highlights the advantage of targeting pension incentives towards ages at which labor supply is most responsive.", "date": "2026-08-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag082", "title_zh": "\u52b3\u52a8\u4f9b\u7ed9\u4e0e\u517b\u8001\u91d1\u7f34\u8d39-\u798f\u5229\u5173\u8054", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u7528\u6ce2\u5170\u4ece\u786e\u5b9a\u6536\u76ca\u8ba1\u5212\u8f6c\u5411\u540d\u4e49\u786e\u5b9a\u7f34\u8d39\uff08NDC\uff09\u8ba1\u5212\u7684\u6539\u9769\uff0c\u4f30\u8ba1\u4e86\u516c\u5171\u517b\u8001\u91d1\u6fc0\u52b1\u5bf9\u8fdc\u4f4e\u4e8e\u6b63\u5e38\u9000\u4f11\u5e74\u9f84\u7684\u52b3\u52a8\u4f9b\u7ed9\u7684\u5f71\u54cd\u3002\u8fd9\u4e00\u6539\u9769\u5728\u5f53\u524d\u517b\u8001\u91d1\u7f34\u8d39\u4e0e\u672a\u6765\u798f\u5229\u4e4b\u95f4\u521b\u9020\u4e86\u660e\u663e\u7684\u961f\u5217\u65ad\u70b9\u3002\u5229\u7528\u8fd9\u4e00\u65ad\u70b9\u4ee5\u53ca\u7eb3\u7a0e\u4eba\u6570\u636e\uff0c\u6211\u4eec\u4f30\u8ba1\u4e8651\u81f354\u5c81\u7537\u6027\u5bf9\u5de5\u4f5c\u51c0\u56de\u62a5\u7684\u5c31\u4e1a\u5f39\u6027\u4e3a0.51\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u751f\u547d\u5468\u671f\u6a21\u578b\u4ee5\u5339\u914d\u8fd9\u4e9b\u53cd\u5e94\uff0c\u5e76\u8ba8\u8bba\u4e86\u8be5\u6539\u9769\u7684\u66f4\u5e7f\u6cdb\u5f71\u54cd\u3002\u8f6c\u5411NDC\u8ba1\u5212\u5728\u751f\u547d\u5468\u671f\u5185\u91cd\u65b0\u5206\u914d\u4e86\u5de5\u4f5c\u6fc0\u52b1\uff0c\u589e\u5f3a\u4e86\u5e74\u8f7b\u5e74\u9f84\u9636\u6bb5\u7684\u5de5\u4f5c\u6fc0\u52b1\uff08\u6b64\u65f6\u52b3\u52a8\u4f9b\u7ed9\u76f8\u5bf9\u7f3a\u4e4f\u5f39\u6027\uff09\uff0c\u800c\u5728\u5e74\u957f\u5e74\u9f84\u9636\u6bb5\u5219\u524a\u5f31\u4e86\u6fc0\u52b1\uff08\u6b64\u65f6\u52b3\u52a8\u4f9b\u7ed9\u66f4\u5bcc\u6709\u5f39\u6027\uff09\u3002\u8fd9\u79cd\u5de5\u4f5c\u6fc0\u52b1\u7684\u91cd\u65b0\u5206\u914d\u503e\u5411\u4e8e\u51cf\u5c11\u6574\u4f53\u751f\u547d\u5468\u671f\u5185\u7684\u52b3\u52a8\u4f9b\u7ed9\uff0c\u8fd9\u51f8\u663e\u4e86\u5c06\u517b\u8001\u91d1\u6fc0\u52b1\u5b9a\u5411\u81f3\u52b3\u52a8\u4f9b\u7ed9\u6700\u654f\u611f\u7684\u5e74\u9f84\u9636\u6bb5\u7684\u4f18\u52bf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag092", "journal": "REStud", "title": "Early-Career Discrimination: Spiralling or Self-Correcting?", "authors": ["Arjada Bardhi", "Yingni Guo", "Bruno Strulovici"], "author_details": [{"name": "Arjada Bardhi", "affiliations": ["Department of Economics, New York University ,"]}, {"name": "Yingni Guo", "affiliations": ["Department of Economics, Duke University ,"]}, {"name": "Bruno Strulovici", "affiliations": ["Department of Economics, Northwestern University ,"]}], "abstract": "Abstract Do workers from social groups with comparable productivity distributions obtain comparable lifetime earnings? We study how a small amount of early-career discrimination propagates over time when workers\u2019 productivity is revealed through employment. In breakdown learning environments that primarily track on-the-job failures, such discrimination spirals into a substantial lifetime earnings gap for groups of comparable productivity, whereas in breakthrough learning environments that track successes, early-career discrimination can be self-corrected, so comparable groups obtain comparable lifetime earnings. This contrast persists in large labour markets and with flexible wages, inconclusive learning, and misspecified employer beliefs.", "date": "2026-08-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag092", "title_zh": "\u65e9\u671f\u804c\u4e1a\u6b67\u89c6\uff1a\u6076\u6027\u5faa\u73af\u8fd8\u662f\u81ea\u6211\u7ea0\u6b63\uff1f", "abstract_zh": "\u6458\u8981 \u5728\u751f\u4ea7\u529b\u5206\u5e03\u76f8\u4f3c\u7684\u793e\u4f1a\u7fa4\u4f53\u4e2d\uff0c\u5de5\u4eba\u662f\u5426\u80fd\u83b7\u5f97\u76f8\u4f3c\u7684\u7ec8\u8eab\u6536\u5165\uff1f\u6211\u4eec\u7814\u7a76\u4e86\u5f53\u5de5\u4eba\u7684\u751f\u4ea7\u529b\u901a\u8fc7\u5c31\u4e1a\u8868\u73b0\u88ab\u63ed\u793a\u65f6\uff0c\u5c11\u91cf\u65e9\u671f\u804c\u4e1a\u6b67\u89c6\u5982\u4f55\u968f\u65f6\u95f4\u4f20\u64ad\u3002\u5728\u4e3b\u8981\u5173\u6ce8\u5728\u804c\u5931\u8d25\u7684\u7834\u5c40\u5b66\u4e60\u73af\u5883\u4e2d\uff0c\u8fd9\u79cd\u6b67\u89c6\u4f1a\u6f14\u53d8\u4e3a\u751f\u4ea7\u529b\u76f8\u5f53\u7fa4\u4f53\u4e4b\u95f4\u663e\u8457\u7684\u7ec8\u8eab\u6536\u5165\u5dee\u8ddd\uff1b\u800c\u5728\u5173\u6ce8\u6210\u529f\u7ecf\u9a8c\u7684\u7a81\u7834\u5b66\u4e60\u73af\u5883\u4e2d\uff0c\u65e9\u671f\u804c\u4e1a\u6b67\u89c6\u53ef\u4ee5\u88ab\u81ea\u6211\u7ea0\u6b63\uff0c\u4ece\u800c\u4f7f\u751f\u4ea7\u529b\u76f8\u5f53\u7684\u7fa4\u4f53\u83b7\u5f97\u76f8\u4f3c\u7684\u7ec8\u8eab\u6536\u5165\u3002\u8fd9\u4e00\u5bf9\u6bd4\u5728\u5927\u578b\u52b3\u52a8\u529b\u5e02\u573a\u3001\u7075\u6d3b\u5de5\u8d44\u3001\u4e0d\u660e\u786e\u7684\u5b66\u4e60\u8fc7\u7a0b\u4ee5\u53ca\u96c7\u4e3b\u4fe1\u5ff5\u8bef\u5224\u7684\u60c5\u51b5\u4e0b\u4f9d\u7136\u6210\u7acb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag094", "journal": "REStud", "title": "Paying to Match: Decentralized Markets with Information Frictions", "authors": ["Marina Agranov", "Ahrash Dianat", "Larry Samuelson", "Leeat Yariv"], "author_details": [{"name": "Marina Agranov", "affiliations": ["Division of the Humanities and Social Sciences, California Institute of Technology , USA"]}, {"name": "Ahrash Dianat", "affiliations": ["Department of Economics, University of Essex , UK"]}, {"name": "Larry Samuelson", "affiliations": ["Department of Economics, Yale University , USA"]}, {"name": "Leeat Yariv", "affiliations": ["Department of Economics, Princeton University , USA"]}], "abstract": "Abstract We experimentally study decentralized one-to-one matching markets with transfers. We vary the information available to participants, complete or incomplete, and the surplus structure, supermodular or submodular. Several insights emerge. First, while markets often culminate in efficient matchings, stability is more elusive, reflecting the difficulty of arranging attendant transfers. Second, incomplete information and submodularity present hurdles to efficiency and especially stability; their combination drastically diminishes stability\u2019s likelihood. Third, matchings form \u201cfrom the top down\u201d in complete-information supermodular markets, but exhibit many more and less-obviously ordered offers otherwise. Last, participants\u2019 market positions matter far more than their dynamic bargaining styles for outcomes.", "date": "2026-08-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag094", "title_zh": "\u652f\u4ed8\u4ee5\u5339\u914d\uff1a\u5b58\u5728\u4fe1\u606f\u6469\u64e6\u7684\u53bb\u4e2d\u5fc3\u5316\u5e02\u573a", "abstract_zh": "\u6211\u4eec\u901a\u8fc7\u5b9e\u9a8c\u7814\u7a76\u4e86\u5177\u6709\u8f6c\u79fb\u652f\u4ed8\u7684\u53bb\u4e2d\u5fc3\u5316\u4e00\u5bf9\u4e00\u5339\u914d\u5e02\u573a\u3002\u6211\u4eec\u6539\u53d8\u4e86\u53c2\u4e0e\u8005\u53ef\u83b7\u5f97\u7684\u4fe1\u606f\u662f\u5b8c\u6574\u8fd8\u662f\u4e0d\u5b8c\u6574\uff0c\u4ee5\u53ca\u76c8\u4f59\u7ed3\u6784\u662f\u8d85\u6a21\u8fd8\u662f\u4e9a\u6a21\u3002\u5f97\u51fa\u82e5\u5e72\u91cd\u8981\u53d1\u73b0\u3002\u9996\u5148\uff0c\u5c3d\u7ba1\u5e02\u573a\u5f80\u5f80\u6700\u7ec8\u5f62\u6210\u6709\u6548\u5339\u914d\uff0c\u4f46\u7a33\u5b9a\u6027\u66f4\u96be\u4ee5\u5b9e\u73b0\uff0c\u53cd\u6620\u51fa\u5b89\u6392\u4f34\u968f\u7684\u8f6c\u79fb\u652f\u4ed8\u7684\u96be\u5ea6\u3002\u5176\u6b21\uff0c\u4e0d\u5b8c\u6574\u4fe1\u606f\u548c\u4e9a\u6a21\u6027\u5bf9\u6548\u7387\u4ee5\u53ca\u5c24\u5176\u662f\u7a33\u5b9a\u6027\u6784\u6210\u4e86\u969c\u788d\uff1b\u5b83\u4eec\u7684\u7ed3\u5408\u4f1a\u663e\u8457\u964d\u4f4e\u7a33\u5b9a\u6027\u7684\u53ef\u80fd\u6027\u3002\u7b2c\u4e09\uff0c\u5728\u4fe1\u606f\u5b8c\u6574\u4e14\u4e3a\u8d85\u6a21\u7ed3\u6784\u7684\u5e02\u573a\u4e2d\uff0c\u5339\u914d\u5448\u73b0\u51fa\u201c\u81ea\u4e0a\u800c\u4e0b\u201d\u7684\u5f62\u6210\u65b9\u5f0f\uff0c\u800c\u5728\u5176\u4ed6\u60c5\u51b5\u4e0b\u5219\u8868\u73b0\u51fa\u66f4\u591a\u4e14\u66f4\u4e0d\u660e\u663e\u7684\u6709\u5e8f\u62a5\u4ef7\u3002\u6700\u540e\uff0c\u53c2\u4e0e\u8005\u5728\u5e02\u573a\u4e2d\u7684\u4f4d\u7f6e\u6bd4\u5176\u52a8\u6001\u8ba8\u4ef7\u8fd8\u4ef7\u7684\u98ce\u683c\u5bf9\u6700\u7ec8\u7ed3\u679c\u5f71\u54cd\u66f4\u5927\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag093", "journal": "REStud", "title": "Why Veil? Religious Headscarves and the Economic Role of Women", "authors": ["Naila Maya Shofia"], "author_details": [{"name": "Naila Maya Shofia", "affiliations": ["National University of Singapore ,"]}], "abstract": "Abstract We show that the emergence of new economic opportunities that draw women away from their traditional domestic roles has significantly influenced the adoption of religious veiling. We measure the prevalence of veiling among young women across Indonesia\u2019s districts for more than two decades by hand-coding around a quarter million photographs attached to Indonesia\u2019s public high school registers. To establish causality, we exploit exogenous variation generated by international demand for Indonesia\u2019s products, interacted with the gender and sectoral composition of local industries. Districts exposed to stronger positive economic shocks\u2014and thus greater economic opportunities for women\u2014exhibit higher rates of veiling adoption. Our findings suggest that veiling facilitates young women\u2019s participation in formal labour markets while safeguarding their personal and social image in society.", "date": "2026-08-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag093", "title_zh": "\u4e3a\u4ec0\u4e48\u662f\u9762\u7eb1\uff1f\u5b97\u6559\u5934\u5dfe\u4e0e\u5973\u6027\u7684\u7ecf\u6d4e\u89d2\u8272", "abstract_zh": "\u6211\u4eec\u8868\u660e\uff0c\u65b0\u7684\u7ecf\u6d4e\u673a\u4f1a\u5438\u5f15\u5973\u6027\u8131\u79bb\u4f20\u7edf\u5bb6\u5ead\u89d2\u8272\uff0c\u663e\u8457\u5f71\u54cd\u4e86\u5b97\u6559\u9762\u7eb1\u7684\u91c7\u7528\u3002\u6211\u4eec\u901a\u8fc7\u624b\u52a8\u7f16\u7801\u8d85\u8fc7\u4e8c\u5341\u4e94\u4e07\u5f20\u9644\u5c5e\u4e8e\u5370\u5ea6\u5c3c\u897f\u4e9a\u516c\u7acb\u9ad8\u4e2d\u6ce8\u518c\u6863\u6848\u7684\u7167\u7247\uff0c\u6d4b\u91cf\u4e86\u5370\u5ea6\u5c3c\u897f\u4e9a\u5404\u5730\u533a\u5e74\u8f7b\u5973\u6027\u9762\u7eb1\u4f69\u6234\u7684\u666e\u904d\u7a0b\u5ea6\u3002\u4e3a\u5efa\u7acb\u56e0\u679c\u5173\u7cfb\uff0c\u6211\u4eec\u5229\u7528\u56fd\u9645\u5bf9\u5370\u5ea6\u5c3c\u897f\u4e9a\u4ea7\u54c1\u9700\u6c42\u53d8\u5316\u4ea7\u751f\u7684\u5916\u751f\u53d8\u5f02\uff0c\u5e76\u7ed3\u5408\u5f53\u5730\u4ea7\u4e1a\u7684\u6027\u522b\u548c\u90e8\u95e8\u6784\u6210\u8fdb\u884c\u5206\u6790\u3002\u53d7\u5230\u66f4\u5f3a\u6b63\u5411\u7ecf\u6d4e\u51b2\u51fb\u2014\u2014\u5373\u5973\u6027\u83b7\u5f97\u66f4\u591a\u7ecf\u6d4e\u673a\u4f1a\u2014\u2014\u7684\u5730\u533a\uff0c\u5176\u9762\u7eb1\u91c7\u7528\u7387\u66f4\u9ad8\u3002\u6211\u4eec\u7684\u53d1\u73b0\u8868\u660e\uff0c\u9762\u7eb1\u6709\u52a9\u4e8e\u5e74\u8f7b\u5973\u6027\u8fdb\u5165\u6b63\u89c4\u52b3\u52a8\u529b\u5e02\u573a\uff0c\u540c\u65f6\u4fdd\u62a4\u5176\u4e2a\u4eba\u548c\u793e\u4f1a\u5f62\u8c61\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70077", "journal": "JF", "title": "Longevity, Health, and Housing Risk Management in Retirement", "authors": ["PIERRE\u2010CARL MICHAUD", "PASCAL ST\u2010AMOUR"], "author_details": [{"name": "PIERRE\u2010CARL MICHAUD", "affiliations": []}, {"name": "PASCAL ST\u2010AMOUR", "affiliations": []}], "abstract": "ABSTRACT Annuities, long\u2010term care insurance, and reverse mortgages remain puzzlingly unpopular to manage post\u2010retirement longevity, health, and housing price risks. We use a flexible life\u2010cycle model structurally estimated with a unique stated\u2010preference survey experiment of Canadian households to understand why. Key factors include high risk aversion, concern over long\u2010run risks, strong discounting of valuation in disability states, imperfect housing substitutability, and bequest motives. The remaining disinterest is accounted for by information frictions and inertia. We also document evidence of public insurance crowding out, spousal co\u2010insurance, and responsiveness to product bundling.", "date": "2026-08-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70077", "title_zh": "\u957f\u5bff\u3001\u5065\u5eb7\u4e0e\u4f4f\u623f\u98ce\u9669\u5728\u9000\u4f11\u9636\u6bb5\u7684\u7ba1\u7406", "abstract_zh": "\u6458\u8981\uff1a\u5e74\u91d1\u3001\u957f\u671f\u62a4\u7406\u4fdd\u9669\u548c\u53cd\u5411\u62b5\u62bc\u8d37\u6b3e\u5728\u7ba1\u7406\u9000\u4f11\u540e\u957f\u5bff\u3001\u5065\u5eb7\u548c\u4f4f\u623f\u4ef7\u683c\u98ce\u9669\u65b9\u9762\u4ecd\u7136\u4ee4\u4eba\u8d39\u89e3\u5730\u4e0d\u53d7\u6b22\u8fce\u3002\u6211\u4eec\u4f7f\u7528\u4e00\u4e2a\u7075\u6d3b\u7684\u751f\u547d\u5468\u671f\u6a21\u578b\uff0c\u5e76\u7ed3\u5408\u4e00\u9879\u9488\u5bf9\u52a0\u62ff\u5927\u5bb6\u5ead\u7684\u72ec\u7279\u9648\u8ff0\u504f\u597d\u8c03\u67e5\u5b9e\u9a8c\uff0c\u5bf9\u8fd9\u4e00\u73b0\u8c61\u8fdb\u884c\u4e86\u7ed3\u6784\u4f30\u8ba1\u5206\u6790\u3002\u5173\u952e\u56e0\u7d20\u5305\u62ec\u9ad8\u98ce\u9669\u538c\u6076\u3001\u5bf9\u957f\u671f\u98ce\u9669\u7684\u62c5\u5fe7\u3001\u5728\u6b8b\u75be\u72b6\u6001\u4e0b\u5bf9\u4f30\u503c\u7684\u5f3a\u70c8\u6298\u73b0\u3001\u4f4f\u623f\u66ff\u4ee3\u6027\u7684\u4e0d\u5b8c\u5168\u6027\u4ee5\u53ca\u9057\u4ea7\u52a8\u673a\u3002\u5269\u4f59\u7684\u4e0d\u611f\u5174\u8da3\u5219\u5f52\u56e0\u4e8e\u4fe1\u606f\u6469\u64e6\u548c\u60ef\u6027\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\u4e86\u516c\u5171\u4fdd\u9669\u6324\u51fa\u3001\u592b\u59bb\u5171\u540c\u4fdd\u9669\u4ee5\u53ca\u5bf9\u4ea7\u54c1\u6346\u7ed1\u7684\u54cd\u5e94\u6027\u8bc1\u636e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70078", "journal": "JF", "title": "The Market for ESG Ratings", "authors": ["EHSAN AZARMSA", "JOEL SHAPIRO"], "author_details": [{"name": "EHSAN AZARMSA", "affiliations": []}, {"name": "JOEL SHAPIRO", "affiliations": []}], "abstract": "ABSTRACT We present a model of competition between environmental, social, and governance (ESG) raters who acquire information about multiple unrelated categories and sell ratings. Raters specializing in different categories maximize the amount of information transmitted and surplus, and can be an equilibrium outcome. When investors place a high value on ESG performance across multiple categories, the unique equilibrium is for the raters to generalize\u2014splitting their effort among the categories, resulting in less informative ratings. Greenwashing by firms can make generalization the only equilibrium. We also demonstrate that specialization maximizes ratings disagreement, and thus empirical measures of disagreement may be poor measures of surplus.", "date": "2026-08-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70078", "title_zh": "ESG\u8bc4\u7ea7\u5e02\u573a\u7684\u7ade\u4e89", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u73af\u5883\u3001\u793e\u4f1a\u548c\u6cbb\u7406\uff08ESG\uff09\u8bc4\u7ea7\u673a\u6784\u4e4b\u95f4\u7ade\u4e89\u7684\u6a21\u578b\uff0c\u8fd9\u4e9b\u8bc4\u7ea7\u673a\u6784\u83b7\u53d6\u5173\u4e8e\u591a\u4e2a\u65e0\u5173\u7c7b\u522b\u7684\u4fe1\u606f\u5e76\u51fa\u552e\u8bc4\u7ea7\u3002\u4e13\u6ce8\u4e8e\u4e0d\u540c\u7c7b\u522b\u7684\u8bc4\u7ea7\u673a\u6784\u901a\u8fc7\u6700\u5927\u5316\u4fe1\u606f\u4f20\u9012\u91cf\u548c\u5269\u4f59\u6536\u76ca\u6765\u5b9e\u73b0\u5747\u8861\uff0c\u8fd9\u79cd\u4e13\u4e1a\u5316\u53ef\u4ee5\u6210\u4e3a\u5747\u8861\u7ed3\u679c\u3002\u5f53\u6295\u8d44\u8005\u5bf9\u591a\u4e2a\u7c7b\u522b\u4e2d\u7684ESG\u8868\u73b0\u9ad8\u5ea6\u91cd\u89c6\u65f6\uff0c\u552f\u4e00\u5747\u8861\u7ed3\u679c\u662f\u8bc4\u7ea7\u673a\u6784\u8fdb\u884c\u6cdb\u5316\u2014\u2014\u5c06\u52aa\u529b\u5206\u6563\u5230\u5404\u4e2a\u7c7b\u522b\u4e2d\uff0c\u5bfc\u81f4\u8bc4\u7ea7\u4fe1\u606f\u91cf\u51cf\u5c11\u3002\u4f01\u4e1a\u7eff\u8272\u6d17\u724c\u884c\u4e3a\u53ef\u80fd\u4f7f\u6cdb\u5316\u6210\u4e3a\u552f\u4e00\u5747\u8861\u3002\u6211\u4eec\u8fd8\u8bc1\u660e\uff0c\u4e13\u4e1a\u5316\u80fd\u591f\u6700\u5927\u5316\u8bc4\u7ea7\u4e4b\u95f4\u7684\u5206\u6b67\uff0c\u56e0\u6b64\uff0c\u57fa\u4e8e\u5206\u6b67\u7684\u5b9e\u8bc1\u6d4b\u91cf\u53ef\u80fd\u5e76\u975e\u5269\u4f59\u6536\u76ca\u7684\u826f\u597d\u8861\u91cf\u6307\u6807\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag095", "journal": "REStud", "title": "Affective Polarization, Media Outlets, and Opinion Dynamics", "authors": ["Sebastiano Della Lena", "Luca Paolo Merlino", "Yves Zenou"], "author_details": [{"name": "Sebastiano Della Lena", "affiliations": ["Department of Economics, Monash University ,"]}, {"name": "Luca Paolo Merlino", "affiliations": ["ECARES, Universit\u00e9 libre de Bruxelles ,"]}, {"name": "Yves Zenou", "affiliations": ["Department of Economics, Monash University ,", "University of Southampton ,"]}], "abstract": "Abstract We study opinion dynamics in a social network consisting of two groups. Agents update their opinions by conforming to members of their own group while rejecting the views of the opposing group (affective polarization), and by listening to a media outlet that may provide biased information. We characterize the long-run opinions and identify when affective polarization and media bias lead to ideological polarization, persistent disagreement, or failures of learning. We also derive when information interventions or censorship improve the accuracy of average opinions and reduce disagreement, and when they backfire: better information helps only under specific media bias configurations and when directed to the agents we identify as most effective at propagating it through the network.", "date": "2026-08-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag095", "title_zh": "\u60c5\u611f\u6781\u5316\u3001\u5a92\u4f53\u6e20\u9053\u4e0e\u610f\u89c1\u52a8\u6001", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e00\u4e2a\u7531\u4e24\u4e2a\u7fa4\u4f53\u7ec4\u6210\u7684\u793e\u4ea4\u7f51\u7edc\u4e2d\u7684\u610f\u89c1\u52a8\u6001\u3002\u4ee3\u7406\u4eba\u901a\u8fc7\u8ba4\u540c\u672c\u7fa4\u4f53\u6210\u5458\u7684\u89c2\u70b9\u800c\u62d2\u7edd\u5bf9\u7acb\u7fa4\u4f53\u7684\u89c2\u70b9\uff08\u60c5\u611f\u6781\u5316\uff09\uff0c\u5e76\u542c\u53d6\u53ef\u80fd\u63d0\u4f9b\u504f\u9887\u4fe1\u606f\u7684\u5a92\u4f53\u6e20\u9053\u6765\u66f4\u65b0\u5176\u89c2\u70b9\u3002\u6211\u4eec\u523b\u753b\u4e86\u957f\u671f\u610f\u89c1\u7684\u6f14\u5316\u8fc7\u7a0b\uff0c\u5e76\u8bc6\u522b\u51fa\u5728\u60c5\u611f\u6781\u5316\u548c\u5a92\u4f53\u504f\u89c1\u7684\u60c5\u51b5\u4e0b\uff0c\u5bfc\u81f4\u610f\u8bc6\u5f62\u6001\u6781\u5316\u3001\u6301\u7eed\u5206\u6b67\u6216\u5b66\u4e60\u5931\u8d25\u7684\u6761\u4ef6\u3002\u6211\u4eec\u8fd8\u63a8\u5bfc\u51fa\u4fe1\u606f\u5e72\u9884\u6216\u5ba1\u67e5\u5728\u4f55\u79cd\u60c5\u51b5\u4e0b\u80fd\u591f\u63d0\u5347\u5e73\u5747\u610f\u89c1\u7684\u51c6\u786e\u6027\u5e76\u51cf\u5c11\u5206\u6b67\uff0c\u4ee5\u53ca\u5728\u4f55\u79cd\u60c5\u51b5\u4e0b\u4f1a\u9002\u5f97\u5176\u53cd\uff1a\u53ea\u6709\u5728\u7279\u5b9a\u7684\u5a92\u4f53\u504f\u89c1\u914d\u7f6e\u4e0b\uff0c\u4e14\u4fe1\u606f\u5b9a\u5411\u4f20\u9012\u7ed9\u7f51\u7edc\u4e2d\u6211\u4eec\u8bc6\u522b\u51fa\u7684\u6700\u6709\u6548\u4f20\u64ad\u8005\u65f6\uff0c\u66f4\u597d\u7684\u4fe1\u606f\u624d\u80fd\u53d1\u6325\u79ef\u6781\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1287/mnsc.2024.04409", "journal": "MS", "title": "The Salience of Entrepreneurship: Evidence from Online Business", "authors": ["Yi Huang", "Chen Lin", "Sibo Liu", "Gustavo Manso"], "author_details": [{"name": "Yi Huang", "affiliations": ["Bank for International Settlements and CEPR, 4000 Basel, Switzerland"]}, {"name": "Chen Lin", "affiliations": ["The University of Hong Kong, Hong Kong"]}, {"name": "Sibo Liu", "affiliations": ["The Hong Kong Polytechnic University, Hong Kong"]}, {"name": "Gustavo Manso", "affiliations": ["University of California, Berkeley, California 94720"]}], "abstract": "We examine the decision to become an entrepreneur in the context of online business. Using data on entrepreneurs from a large e-commerce marketplace in China, we find that individuals are more likely to start online businesses after observing the salient success of nearby stores. Leveraging the platform\u2019s store rating system and detailed geographic information in rural China, we show that an upgrade in a local store\u2019s rating leads to a significant increase in new store entries nearby. This effect diminishes with physical distance and intensifies with the salience of the upgrade. However, these entry decisions appear to be suboptimal; entrants driven by local upgrade events underperform in sales and are more likely to exit, especially during downturns in overall market conditions. Our findings are consistent with salience-based theories of decision making, in which individuals overweight highly visible local information.", "date": "2026-08-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.04409", "title_zh": "\u521b\u4e1a\u7684\u663e\u8457\u6027\uff1a\u6765\u81ea\u5728\u7ebf\u5546\u4e1a\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5728\u5728\u7ebf\u5546\u4e1a\u80cc\u666f\u4e0b\u6210\u4e3a\u521b\u4e1a\u8005\u7684\u51b3\u7b56\u3002\u5229\u7528\u4e2d\u56fd\u5927\u578b\u7535\u5546\u5e73\u53f0\u4e0a\u7684\u521b\u4e1a\u8005\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u4e2a\u4f53\u5728\u89c2\u5bdf\u5230\u9644\u8fd1\u5e97\u94fa\u663e\u8457\u6210\u529f\u540e\uff0c\u66f4\u6709\u53ef\u80fd\u542f\u52a8\u5728\u7ebf\u4e1a\u52a1\u3002\u501f\u52a9\u5e73\u53f0\u7684\u5e97\u94fa\u8bc4\u5206\u7cfb\u7edf\u4ee5\u53ca\u4e2d\u56fd\u519c\u6751\u5730\u533a\u7684\u8be6\u7ec6\u5730\u7406\u4fe1\u606f\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5f53\u5730\u5e97\u94fa\u8bc4\u5206\u63d0\u5347\u4f1a\u663e\u8457\u589e\u52a0\u9644\u8fd1\u65b0\u5e97\u94fa\u7684\u8bbe\u7acb\u3002\u8fd9\u4e00\u6548\u5e94\u968f\u7740\u7269\u7406\u8ddd\u79bb\u7684\u589e\u52a0\u800c\u51cf\u5f31\uff0c\u968f\u7740\u5347\u7ea7\u7684\u663e\u8457\u6027\u589e\u5f3a\u800c\u52a0\u5f3a\u3002\u7136\u800c\uff0c\u8fd9\u4e9b\u8fdb\u5165\u51b3\u7b56\u4f3c\u4e4e\u5e76\u4e0d\u7406\u60f3\uff1a\u53d7\u5f53\u5730\u5347\u7ea7\u4e8b\u4ef6\u9a71\u52a8\u7684\u521b\u4e1a\u8005\u5728\u9500\u552e\u8868\u73b0\u4e0a\u8868\u73b0\u4e0d\u4f73\uff0c\u4e14\u5728\u6574\u4f53\u5e02\u573a\u72b6\u51b5\u6076\u5316\u65f6\u66f4\u53ef\u80fd\u9000\u51fa\u3002\u6211\u4eec\u7684\u53d1\u73b0\u4e0e\u57fa\u4e8e\u663e\u8457\u6027\u7684\u51b3\u7b56\u7406\u8bba\u4e00\u81f4\uff0c\u5373\u4e2a\u4f53\u503e\u5411\u4e8e\u8fc7\u5ea6\u91cd\u89c6\u9ad8\u5ea6\u53ef\u89c1\u7684\u672c\u5730\u4fe1\u606f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.04499", "journal": "MS", "title": "Leveraging Collective Advice-Taking Behavior to Infer Accuracy and Improve the Wisdom of Crowds", "authors": ["Yunhao Zhang"], "author_details": [{"name": "Yunhao Zhang", "affiliations": ["School of Management, University College London, London, United Kingdom; and Sloan School of Management, Massachusetts Institute of Technology, Cambridge, Massachusetts; and Haas School of Business, University of California, Berkeley, Berkeley, California 94720"]}], "abstract": "Wisdom of crowds estimates can be compromised when some agents\u2019 predictions are systematically biased. A natural remedy is to aggregate predictions from a subset of more accurate agents rather than the entire crowd. I propose cluster weight on advice (CWOA), a novel \u201ctwo-shot\u201d algorithm to identify a more accurate subgroup in a single-prediction-problem context. CWOA first applies kernel density estimation to identify clusters of similar initial predictions. If multiple clusters emerge\u2014indicating potential heterogeneity in agents\u2019 information\u2014the algorithm proceeds to present a piece of numerical advice (e.g., the group mean) and elicit updated predictions. This enables the calculation of the weight on advice (WOA)\u2014the scaled magnitude of each agent\u2019s belief revision. CWOA then averages the updated predictions within the cluster with the lowest mean WOA. A behavioral model and simulations explain both why and when cluster-level WOA signals accuracy. Better-informed agents\u2014having already incorporated higher-quality information\u2014perceive less corrective value in the advice and therefore, exhibit lower WOA. CWOA does not require agents to know the true biases or the composition of the crowd; a modest relative advantage in perceived estimation bias by better-informed agents may be sufficient, even under misperceptions of variance, advice quality, and psychological biases in advice taking. Empirically, I first test and confirm the model\u2019s key insight in a controlled experimental setting. I then validate CWOA\u2019s performance across multiple preregistered and archival data sets, including a study in which numerical advice comes from artificial intelligence. CWOA consistently outperforms benchmarks, including the state-of-the-art metaprediction-based methods.", "date": "2026-08-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.04499", "title_zh": "\u5229\u7528\u96c6\u4f53\u54a8\u8be2\u884c\u4e3a\u63a8\u65ad\u51c6\u786e\u6027\u5e76\u63d0\u5347\u7fa4\u4f53\u667a\u6167", "abstract_zh": "\u7fa4\u4f53\u667a\u6167\u4f30\u8ba1\u5728\u67d0\u4e9b\u53c2\u4e0e\u8005\u9884\u6d4b\u5b58\u5728\u7cfb\u7edf\u6027\u504f\u8bef\u65f6\u53ef\u80fd\u53d7\u5230\u635f\u5bb3\u3002\u4e00\u79cd\u81ea\u7136\u7684\u89e3\u51b3\u65b9\u6cd5\u662f\u4ec5\u805a\u5408\u66f4\u51c6\u786e\u53c2\u4e0e\u8005\u7fa4\u4f53\u7684\u9884\u6d4b\uff0c\u800c\u975e\u6574\u4e2a\u7fa4\u4f53\u7684\u9884\u6d4b\u3002\u6211\u63d0\u51fa\u4e86\u4e00\u79cd\u540d\u4e3a\u2018\u96c6\u7fa4\u5efa\u8bae\u6743\u91cd\u2019\uff08CWOA\uff09\u7684\u65b0\u578b\u2018\u4e24\u9636\u6bb5\u2019\u7b97\u6cd5\uff0c\u7528\u4e8e\u5728\u5355\u6b21\u9884\u6d4b\u95ee\u9898\u60c5\u5883\u4e0b\u8bc6\u522b\u51fa\u66f4\u51c6\u786e\u7684\u5b50\u7fa4\u4f53\u3002CWOA\u9996\u5148\u4f7f\u7528\u6838\u5bc6\u5ea6\u4f30\u8ba1\u6cd5\u8bc6\u522b\u51fa\u521d\u59cb\u9884\u6d4b\u76f8\u4f3c\u7684\u9884\u6d4b\u96c6\u7fa4\u3002\u82e5\u51fa\u73b0\u591a\u4e2a\u96c6\u7fa4\u2014\u2014\u8868\u660e\u53c2\u4e0e\u8005\u4fe1\u606f\u53ef\u80fd\u5b58\u5728\u5f02\u8d28\u6027\u2014\u2014\u5219\u7b97\u6cd5\u4f1a\u63d0\u4f9b\u4e00\u4e2a\u6570\u503c\u5efa\u8bae\uff08\u4f8b\u5982\u7fa4\u4f53\u5747\u503c\uff09\uff0c\u5e76\u83b7\u53d6\u66f4\u65b0\u540e\u7684\u9884\u6d4b\u3002\u8fd9\u4f7f\u5f97\u53ef\u4ee5\u8ba1\u7b97\u51fa\u2018\u5efa\u8bae\u6743\u91cd\u2019\uff08WOA\uff09\u2014\u2014\u5373\u6bcf\u4f4d\u53c2\u4e0e\u8005\u4fe1\u5ff5\u4fee\u6b63\u7684\u52a0\u6743\u5e45\u5ea6\u3002CWOA\u968f\u540e\u5bf9\u5177\u6709\u6700\u4f4e\u5747\u503cWOA\u7684\u96c6\u7fa4\u5185\u66f4\u65b0\u540e\u7684\u9884\u6d4b\u8fdb\u884c\u52a0\u6743\u5e73\u5747\u3002\u4e00\u4e2a\u884c\u4e3a\u6a21\u578b\u548c\u6a21\u62df\u89e3\u91ca\u4e86\u4e3a\u4f55\u4ee5\u53ca\u5728\u4f55\u79cd\u60c5\u51b5\u4e0b\u96c6\u7fa4\u5c42\u9762\u7684WOA\u80fd\u591f\u53cd\u6620\u51c6\u786e\u6027\u3002\u4fe1\u606f\u66f4\u5145\u5206\u7684\u53c2\u4e0e\u8005\u5df2\u7ecf\u6574\u5408\u4e86\u66f4\u9ad8\u8d28\u91cf\u7684\u4fe1\u606f\uff0c\u56e0\u6b64\u5bf9\u5efa\u8bae\u7684\u4fee\u6b63\u4ef7\u503c\u611f\u77e5\u8f83\u4f4e\uff0c\u4ece\u800c\u8868\u73b0\u51fa\u66f4\u4f4e\u7684WOA\u3002CWOA\u4e0d\u9700\u8981\u53c2\u4e0e\u8005\u4e86\u89e3\u771f\u5b9e\u504f\u8bef\u6216\u7fa4\u4f53\u6784\u6210\uff1b\u5373\u4f7f\u5728\u5bf9\u65b9\u5dee\u3001\u5efa\u8bae\u8d28\u91cf\u4ee5\u53ca\u54a8\u8be2\u884c\u4e3a\u4e2d\u7684\u5fc3\u7406\u504f\u8bef\u5b58\u5728\u8bef\u5224\u7684\u60c5\u51b5\u4e0b\uff0c\u53ea\u8981\u5b58\u5728\u4fe1\u606f\u66f4\u5145\u5206\u7684\u53c2\u4e0e\u8005\u5bf9\u4f30\u8ba1\u504f\u8bef\u7684\u76f8\u5bf9\u611f\u77e5\u4f18\u52bf\uff0c\u5c31\u8db3\u4ee5\u53d1\u6325\u4f5c\u7528\u3002\u5b9e\u8bc1\u4e0a\uff0c\u6211\u9996\u5148\u5728\u53d7\u63a7\u5b9e\u9a8c\u73af\u5883\u4e2d\u9a8c\u8bc1\u5e76\u786e\u8ba4\u4e86\u8be5\u6a21\u578b\u7684\u6838\u5fc3\u89c1\u89e3\u3002\u968f\u540e\uff0c\u6211\u5c06CWOA\u5728\u591a\u4e2a\u9884\u5148\u6ce8\u518c\u548c\u5b58\u6863\u6570\u636e\u96c6\u4e2d\u8fdb\u884c\u9a8c\u8bc1\uff0c\u5305\u62ec\u4e00\u9879\u6570\u503c\u5efa\u8bae\u6765\u81ea\u4eba\u5de5\u667a\u80fd\u7684\u7814\u7a76\u3002CWOA\u5728\u6240\u6709\u60c5\u51b5\u4e0b\u5747\u4f18\u4e8e\u57fa\u51c6\u65b9\u6cd5\uff0c\u5305\u62ec\u5f53\u524d\u6700\u5148\u8fdb\u7684\u5143\u9884\u6d4b\u65b9\u6cd5\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1287/mnsc.2025.00480", "journal": "MS", "title": "Goals, Expectations, and Performance", "authors": ["Avner Strulov-Shlain", "Alexandra Steiny Wellsjo"], "author_details": [{"name": "Avner Strulov-Shlain", "affiliations": ["University of Chicago Booth School of Business, Chicago, Illinois 60637"]}, {"name": "Alexandra Steiny Wellsjo", "affiliations": ["Rady School of Management, University of California San Diego, La Jolla, California 92093"]}], "abstract": "People and organizations often set goals to self-motivate and achieve better outcomes in challenging tasks. But goals\u2014and their effectiveness\u2014might depend on what people expect to happen. Do goals reflect expectations, or do goals set expectations? How do goals and expectations affect performance? These distinctions are important for motivation and intervention design. We run an online real-effort task to answer these two questions by introducing exogenous variation in goals and expectations. First, we find that goals mostly reflect existing expectations rather than set expectations. Second, practicing an easier version of a task leads to higher expectations and higher performance. Third, eliciting a goal also leads to higher average performance, and changing the goal level has local effects that pull people toward the goal. However, revising goals has little effect on average performance. Our findings imply that increasing expectations is an important motivating tool that increases goals and performance. Having any goal helps performance; however, people cannot fool themselves into expecting and doing more simply by choosing a different goal.", "date": "2026-08-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.00480", "title_zh": "\u76ee\u6807\u3001\u9884\u671f\u4e0e\u8868\u73b0", "abstract_zh": "\u4eba\u4eec\u548c\u7ec4\u7ec7\u5e38\u5e38\u8bbe\u5b9a\u76ee\u6807\u4ee5\u81ea\u6211\u6fc0\u52b1\uff0c\u5e76\u5728\u5177\u6709\u6311\u6218\u6027\u7684\u4efb\u52a1\u4e2d\u53d6\u5f97\u66f4\u597d\u7684\u6210\u679c\u3002\u7136\u800c\uff0c\u76ee\u6807\u53ca\u5176\u6709\u6548\u6027\u53ef\u80fd\u53d6\u51b3\u4e8e\u4eba\u4eec\u6240\u9884\u671f\u4f1a\u53d1\u751f\u7684\u4e8b\u60c5\u3002\u76ee\u6807\u662f\u53cd\u6620\u9884\u671f\uff0c\u8fd8\u662f\u8bbe\u5b9a\u9884\u671f\uff1f\u76ee\u6807\u548c\u9884\u671f\u5982\u4f55\u5f71\u54cd\u8868\u73b0\uff1f\u8fd9\u4e9b\u533a\u522b\u5bf9\u4e8e\u52a8\u673a\u548c\u5e72\u9884\u8bbe\u8ba1\u81f3\u5173\u91cd\u8981\u3002\u6211\u4eec\u901a\u8fc7\u5f15\u5165\u5916\u751f\u7684\u76ee\u6807\u548c\u9884\u671f\u53d8\u5316\uff0c\u8fdb\u884c\u4e86\u4e00\u9879\u5728\u7ebf\u771f\u5b9e\u52aa\u529b\u4efb\u52a1\uff0c\u4ee5\u56de\u7b54\u8fd9\u4e24\u4e2a\u95ee\u9898\u3002\u9996\u5148\uff0c\u6211\u4eec\u53d1\u73b0\u76ee\u6807\u4e3b\u8981\u53cd\u6620\u73b0\u6709\u7684\u9884\u671f\uff0c\u800c\u975e\u8bbe\u5b9a\u9884\u671f\u3002\u5176\u6b21\uff0c\u7ec3\u4e60\u4e00\u4e2a\u66f4\u7b80\u5355\u7684\u4efb\u52a1\u4f1a\u63d0\u9ad8\u9884\u671f\u548c\u8868\u73b0\u3002\u7b2c\u4e09\uff0c\u63d0\u51fa\u76ee\u6807\u4e5f\u4f1a\u63d0\u5347\u5e73\u5747\u8868\u73b0\uff0c\u4e14\u8c03\u6574\u76ee\u6807\u6c34\u5e73\u4f1a\u4ea7\u751f\u5c40\u90e8\u6548\u5e94\uff0c\u5c06\u4eba\u4eec\u5411\u76ee\u6807\u62c9\u8fd1\u3002\u7136\u800c\uff0c\u4fee\u6539\u76ee\u6807\u5bf9\u5e73\u5747\u8868\u73b0\u51e0\u4e4e\u6ca1\u6709\u5f71\u54cd\u3002\u6211\u4eec\u7684\u53d1\u73b0\u8868\u660e\uff0c\u63d0\u9ad8\u9884\u671f\u662f\u4e00\u79cd\u91cd\u8981\u7684\u6fc0\u52b1\u5de5\u5177\uff0c\u80fd\u591f\u63d0\u5347\u76ee\u6807\u548c\u8868\u73b0\u3002\u62e5\u6709\u4efb\u4f55\u76ee\u6807\u90fd\u6709\u52a9\u4e8e\u63d0\u5347\u8868\u73b0\uff1b\u7136\u800c\uff0c\u4eba\u4eec\u65e0\u6cd5\u4ec5\u4ec5\u901a\u8fc7\u9009\u62e9\u4e0d\u540c\u7684\u76ee\u6807\uff0c\u5c31\u6b3a\u9a97\u81ea\u5df1\u53bb\u9884\u671f\u5e76\u5b9e\u73b0\u66f4\u591a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2025.02111", "journal": "MS", "title": "Evolution of Discrimination on Online Platforms", "authors": ["Peibo Zhang", "Xinyu Cao", "Ruomeng Cui", "Dennis J. Zhang"], "author_details": [{"name": "Peibo Zhang", "affiliations": ["Information Systems and Operations Management, Goizueta Business School, Emory University, Atlanta, Georgia 30322"]}, {"name": "Xinyu Cao", "affiliations": ["Department of Marketing, The Chinese University of Hong Kong, Hong Kong SAR, China"]}, {"name": "Ruomeng Cui", "affiliations": ["Information Systems and Operations Management, Goizueta Business School, Emory University, Atlanta, Georgia 30322"]}, {"name": "Dennis J. Zhang", "affiliations": ["Olin Business School, Washington University in St. Louis, St. Louis, Missouri 63130"]}], "abstract": "Research on discrimination has predominantly relied on audit studies, which provide clean causal estimates through randomized profile testing but offer only static snapshots of bias. We adopt a dynamic perspective to examine how racial discrimination evolves over time. Using observational panel data from an online educational platform, we first find that African-American teachers receive 30.2% fewer bookings, and their opened classes are 3.3% less likely to be booked compared with their White counterparts during their first week on the platform, a gap that may indicate initial discrimination. Employing individual fixed effects models, we estimate how this gap evolves over time. The results show a striking 1,007% widening of the initial gap over the 12-week period. Our mechanism analysis shows that new students are significantly less likely to book classes with African-American teachers than with White teachers, even when African-American and White teachers have minimal or comparable reputation metrics. As a result, African-American teachers accumulate reputation metrics and customers more slowly than White teachers. Over time, the growing gaps in reputation and customer base further exacerbate the booking gap, driven by both new and repeat students. Our findings suggest that traditional audit studies may significantly underestimate the long-term consequences of early-stage discrimination and highlight how reputation and repeat customer accumulation serve as bias amplifiers on online platforms. We also show that this amplification mechanism operates regardless of whether the initial gap stems from racial discrimination and thus generalizes to other contexts.", "date": "2026-08-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.02111", "title_zh": "\u5728\u7ebf\u5e73\u53f0\u4e2d\u6b67\u89c6\u7684\u6f14\u53d8", "abstract_zh": "\u5173\u4e8e\u6b67\u89c6\u7684\u7814\u7a76\u957f\u671f\u4ee5\u6765\u4e3b\u8981\u4f9d\u8d56\u5ba1\u8ba1\u7814\u7a76\uff0c\u8fd9\u7c7b\u7814\u7a76\u901a\u8fc7\u968f\u673a\u7684\u4e2a\u4eba\u8d44\u6599\u6d4b\u8bd5\u63d0\u4f9b\u4e86\u5e72\u51c0\u7684\u56e0\u679c\u4f30\u8ba1\uff0c\u4f46\u4ec5\u80fd\u63d0\u4f9b\u9759\u6001\u7684\u504f\u89c1\u5feb\u7167\u3002\u6211\u4eec\u4ece\u52a8\u6001\u89c6\u89d2\u51fa\u53d1\uff0c\u8003\u5bdf\u79cd\u65cf\u6b67\u89c6\u5982\u4f55\u968f\u65f6\u95f4\u6f14\u53d8\u3002\u5229\u7528\u4e00\u4e2a\u5728\u7ebf\u6559\u80b2\u5e73\u53f0\u7684\u89c2\u5bdf\u6027\u9762\u677f\u6570\u636e\uff0c\u6211\u4eec\u9996\u5148\u53d1\u73b0\uff0c\u975e\u6d32\u88d4\u7f8e\u56fd\u6559\u5e08\u5728\u9996\u6b21\u4e0a\u7ebf\u7b2c\u4e00\u5468\u5185\u83b7\u5f97\u7684\u9884\u7ea6\u6570\u91cf\u6bd4\u767d\u4eba\u6559\u5e08\u5c1130.2%\uff0c\u5176\u5f00\u8bbe\u7684\u8bfe\u7a0b\u88ab\u9884\u8ba2\u7684\u6982\u7387\u4e5f\u4f4e3.3%\uff0c\u8fd9\u4e00\u5dee\u8ddd\u53ef\u80fd\u8868\u660e\u5b58\u5728\u521d\u59cb\u6b67\u89c6\u3002\u901a\u8fc7\u4e2a\u4f53\u56fa\u5b9a\u6548\u5e94\u6a21\u578b\uff0c\u6211\u4eec\u4f30\u8ba1\u4e86\u8fd9\u4e00\u5dee\u8ddd\u572812\u5468\u5185\u7684\u6f14\u53d8\u8fc7\u7a0b\u3002\u7ed3\u679c\u8868\u660e\uff0c\u521d\u59cb\u5dee\u8ddd\u572812\u5468\u5185\u663e\u8457\u6269\u5927\u4e861007%\u3002\u673a\u5236\u5206\u6790\u663e\u793a\uff0c\u65b0\u5b66\u751f\u5728\u9009\u62e9\u975e\u6d32\u88d4\u7f8e\u56fd\u6559\u5e08\u6388\u8bfe\u65f6\uff0c\u6bd4\u9009\u62e9\u767d\u4eba\u6559\u5e08\u66f4\u4e0d\u613f\u610f\u9884\u8ba2\u8bfe\u7a0b\uff0c\u5373\u4f7f\u975e\u6d32\u88d4\u7f8e\u56fd\u6559\u5e08\u548c\u767d\u4eba\u6559\u5e08\u7684\u58f0\u8a89\u6307\u6807\u51e0\u4e4e\u76f8\u540c\u6216\u76f8\u5f53\u3002\u56e0\u6b64\uff0c\u975e\u6d32\u88d4\u7f8e\u56fd\u6559\u5e08\u79ef\u7d2f\u58f0\u8a89\u6307\u6807\u548c\u5ba2\u6237\u7684\u901f\u5ea6\u660e\u663e\u6162\u4e8e\u767d\u4eba\u6559\u5e08\u3002\u968f\u7740\u65f6\u95f4\u63a8\u79fb\uff0c\u58f0\u8a89\u548c\u5ba2\u6237\u57fa\u7840\u7684\u5dee\u8ddd\u4e0d\u65ad\u6269\u5927\uff0c\u8fdb\u4e00\u6b65\u52a0\u5267\u4e86\u9884\u7ea6\u5dee\u8ddd\uff0c\u8fd9\u4e00\u8fc7\u7a0b\u65e2\u6d89\u53ca\u65b0\u5b66\u751f\u4e5f\u6d89\u53ca\u56de\u5934\u5b66\u751f\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u4f20\u7edf\u7684\u5ba1\u8ba1\u7814\u7a76\u53ef\u80fd\u4e25\u91cd\u4f4e\u4f30\u4e86\u65e9\u671f\u6b67\u89c6\u7684\u957f\u671f\u540e\u679c\uff0c\u5e76\u63ed\u793a\u4e86\u58f0\u8a89\u548c\u56de\u5934\u5ba2\u6237\u79ef\u7d2f\u5982\u4f55\u5728\u5728\u7ebf\u5e73\u53f0\u4e0a\u653e\u5927\u504f\u89c1\u3002\u6211\u4eec\u8fd8\u8868\u660e\uff0c\u8fd9\u79cd\u653e\u5927\u673a\u5236\u65e0\u8bba\u521d\u59cb\u5dee\u8ddd\u662f\u5426\u6e90\u4e8e\u79cd\u65cf\u6b67\u89c6\uff0c\u5747\u5177\u6709\u666e\u904d\u6027\uff0c\u56e0\u6b64\u53ef\u63a8\u5e7f\u81f3\u5176\u4ed6\u60c5\u5883\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.03696", "journal": "MS", "title": "Training Frontline Health Workers in Low- and Middle-Income Countries to Reduce Contraceptive Stock-Outs: Evidence from Indonesia", "authors": ["Amir Karimi", "Anant Mishra", "Karthik V. Natarajan", "Kingshuk K. Sinha", "Omar Balsara", "Barbara Lamphere"], "author_details": [{"name": "Amir Karimi", "affiliations": ["Alvarez College of Business, The University of Texas at San Antonio, San Antonio, Texas 78249"]}, {"name": "Anant Mishra", "affiliations": ["College of Business and Management and Center for Innovation in Health Sciences, VinUniversity, Hanoi, Vietnam"]}, {"name": "Karthik V. Natarajan", "affiliations": ["Carlson School of Management, University of Minnesota, Minneapolis, Minnesota 55455"]}, {"name": "Kingshuk K. Sinha", "affiliations": ["Carlson School of Management, University of Minnesota, Minneapolis, Minnesota 55455"]}, {"name": "Omar Balsara", "affiliations": ["JSI Research & Training Institute, Inc., Arlington, Virginia 22202"]}, {"name": "Barbara Lamphere", "affiliations": ["Independent Researcher, Betterton, Maryland 21610"]}], "abstract": "Frontline health workers are an indispensable asset in the healthcare ecosystem of low- and middle-income countries (LMICs). They not only provide clinical care to patients but also frequently shoulder nonclinical responsibilities such as inventory management. However, many lack the necessary skills to effectively manage inventories, leading to the pervasive problem of health commodity stock-outs. To address this problem, several LMICs have launched training programs aimed at enhancing the inventory management skills and capabilities of frontline health workers. Leveraging fine-grained data over a five-year period (2015\u20132019) from approximately 17,000 health facilities across Indonesia\u2014where the public health supply chain operates as a hybrid push\u2013pull model\u2014we evaluate the impact of a large-scale inventory management training program on contraceptive stock-outs. Applying difference-in-differences estimations, we find that the training program is associated with a significant reduction in stock-outs (i.e., 6.52 percentage points, or approximately 30%). Our numerical calculations suggest that the training program prevents, on average, more than 800 unintended pregnancies and saves 4.25 maternal and newborn lives per 100,000 women of reproductive age within the catchment area of a treated health facility. A counterfactual benefit\u2013cost analysis shows that on-site delivery of the training program (i.e., on the job within a health facility) yields operational and public health benefits that significantly exceed those achieved through off-site delivery (i.e., outside the health facility in a classroom). Our research highlights the practicality and scalability of human-capital-focused interventions in improving health commodity availability and public health outcomes in LMICs.", "date": "2026-08-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.03696", "title_zh": "\u5728\u4f4e\u6536\u5165\u548c\u4e2d\u7b49\u6536\u5165\u56fd\u5bb6\u57f9\u8bad\u57fa\u5c42\u536b\u751f\u5de5\u4f5c\u8005\u4ee5\u51cf\u5c11\u907f\u5b55\u836f\u54c1\u77ed\u7f3a\uff1a\u6765\u81ea\u5370\u5ea6\u5c3c\u897f\u4e9a\u7684\u8bc1\u636e", "abstract_zh": "\u57fa\u5c42\u536b\u751f\u5de5\u4f5c\u8005\u662f\u4f4e\u6536\u5165\u548c\u4e2d\u7b49\u6536\u5165\u56fd\u5bb6\uff08LMICs\uff09\u533b\u7597\u536b\u751f\u4f53\u7cfb\u4e2d\u4e0d\u53ef\u6216\u7f3a\u7684\u8d44\u4ea7\u3002\u4ed6\u4eec\u4e0d\u4ec5\u4e3a\u60a3\u8005\u63d0\u4f9b\u4e34\u5e8a\u670d\u52a1\uff0c\u8fd8\u7ecf\u5e38\u627f\u62c5\u975e\u4e34\u5e8a\u804c\u8d23\uff0c\u5982\u5e93\u5b58\u7ba1\u7406\u3002\u7136\u800c\uff0c\u8bb8\u591a\u57fa\u5c42\u536b\u751f\u5de5\u4f5c\u8005\u7f3a\u4e4f\u6709\u6548\u7ba1\u7406\u5e93\u5b58\u6240\u9700\u7684\u80fd\u529b\uff0c\u5bfc\u81f4\u907f\u5b55\u836f\u54c1\u9891\u7e41\u77ed\u7f3a\u3002\u4e3a\u89e3\u51b3\u8fd9\u4e00\u95ee\u9898\uff0c\u591a\u4e2aLMICs\u63a8\u51fa\u4e86\u65e8\u5728\u63d0\u5347\u57fa\u5c42\u536b\u751f\u5de5\u4f5c\u8005\u5e93\u5b58\u7ba1\u7406\u6280\u80fd\u7684\u57f9\u8bad\u9879\u76ee\u3002\u6211\u4eec\u5229\u7528\u5370\u5ea6\u5c3c\u897f\u4e9a\u7ea617000\u5bb6\u536b\u751f\u8bbe\u65bd\u57282015\u5e74\u81f32019\u5e74\u671f\u95f4\u7684\u7cbe\u7ec6\u6570\u636e\u2014\u2014\u8be5\u56fd\u516c\u5171\u536b\u751f\u4f9b\u5e94\u94fe\u91c7\u7528\u6df7\u5408\u7684\u63a8\u2013\u62c9\u6a21\u5f0f\u2014\u2014\u8bc4\u4f30\u4e86\u5927\u89c4\u6a21\u5e93\u5b58\u7ba1\u7406\u57f9\u8bad\u9879\u76ee\u5bf9\u907f\u5b55\u836f\u54c1\u77ed\u7f3a\u7684\u5f71\u54cd\u3002\u901a\u8fc7\u53cc\u91cd\u5dee\u5206\u6cd5\u5206\u6790\uff0c\u6211\u4eec\u53d1\u73b0\u8be5\u57f9\u8bad\u9879\u76ee\u4e0e\u907f\u5b55\u836f\u54c1\u77ed\u7f3a\u663e\u8457\u51cf\u5c11\u76f8\u5173\uff08\u5373\u51cf\u5c116.52\u4e2a\u767e\u5206\u70b9\uff0c\u7ea630%\uff09\u3002\u6211\u4eec\u7684\u6570\u503c\u8ba1\u7b97\u8868\u660e\uff0c\u8be5\u9879\u76ee\u5e73\u5747\u6bcf\u5e74\u53ef\u907f\u514d\u8d85\u8fc7800\u4f8b\u610f\u5916\u6000\u5b55\uff0c\u5e76\u5728\u6bcf10\u4e07\u540d\u80b2\u9f84\u5987\u5973\u7684\u8986\u76d6\u533a\u57df\u5185\u633d\u65514.25\u4e2a\u6bcd\u4eb2\u548c\u65b0\u751f\u513f\u751f\u547d\u3002\u53cd\u4e8b\u5b9e\u7684\u6548\u76ca\u2013\u6210\u672c\u5206\u6790\u663e\u793a\uff0c\u73b0\u573a\u57f9\u8bad\uff08\u5373\u5728\u536b\u751f\u8bbe\u65bd\u5185\u8fdb\u884c\uff09\u5728\u8fd0\u8425\u6548\u7387\u548c\u516c\u5171\u536b\u751f\u6548\u76ca\u65b9\u9762\u663e\u8457\u4f18\u4e8e\u79bb\u573a\u57f9\u8bad\uff08\u5373\u5728\u6559\u5ba4\u5916\u8fdb\u884c\uff09\u3002\u672c\u7814\u7a76\u5f3a\u8c03\u4e86\u4ee5\u4eba\u529b\u8d44\u672c\u4e3a\u6838\u5fc3\u7684\u5e72\u9884\u63aa\u65bd\u5728\u6539\u5584LMICs\u4e2d\u5065\u5eb7\u5546\u54c1\u53ef\u53ca\u6027\u53ca\u516c\u5171\u536b\u751f\u7ed3\u679c\u65b9\u9762\u7684\u53ef\u884c\u6027\u548c\u53ef\u6269\u5c55\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/restud/rdag091", "journal": "REStud", "title": "Recruiting Talent", "authors": ["Simon Board", "Moritz Meyer-ter-Vehn", "Tomasz Sadzik"], "author_details": [{"name": "Simon Board", "affiliations": ["Department of Economics, UCLA ,"]}, {"name": "Moritz Meyer-ter-Vehn", "affiliations": ["Department of Economics, UCLA ,"]}, {"name": "Tomasz Sadzik", "affiliations": ["Department of Economics, UCLA ,"]}], "abstract": "Abstract We study a parsimonious model of a competitive labour market in which firms privately screen workers to identify talent. The equilibrium exhibits dispersion in wages and productivity; when talent is scarce, firms with superior screening skills post higher wages, attract better applicants, and recruit more talented workers. High-wage firms impose a compositional externality on low-wage firms, leading to equilibrium inefficiency: Welfare would be higher if low-skilled firms posted high wages and selected first. We also provide a micro-foundation for firms' heterogeneous screening skills. When talented workers are better at screening (e.g. via superior referrals), a dynamic version of the economy converges to a unique steady state in which differences in talent, profits and screening skills persist forever.", "date": "2026-08-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag091", "title_zh": "\u62db\u8058\u4eba\u624d", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u4e2a\u7b80\u6d01\u7684\u7ade\u4e89\u6027\u52b3\u52a8\u529b\u5e02\u573a\u6a21\u578b\uff0c\u5176\u4e2d\u4f01\u4e1a\u79c1\u4e0b\u7b5b\u9009\u5458\u5de5\u4ee5\u8bc6\u522b\u4eba\u624d\u3002\u5747\u8861\u72b6\u6001\u4e0b\u5b58\u5728\u5de5\u8d44\u548c\u751f\u4ea7\u7387\u7684\u5206\u6563\uff1b\u5f53\u4eba\u624d\u7a00\u7f3a\u65f6\uff0c\u7b5b\u9009\u80fd\u529b\u66f4\u5f3a\u7684\u4f01\u4e1a\u4f1a\u63d0\u51fa\u66f4\u9ad8\u7684\u5de5\u8d44\uff0c\u5438\u5f15\u66f4\u4f18\u79c0\u7684\u7533\u8bf7\u8005\uff0c\u5e76\u62db\u8058\u5230\u66f4\u4f18\u79c0\u7684\u4eba\u624d\u3002\u9ad8\u5de5\u8d44\u4f01\u4e1a\u5bf9\u4f4e\u5de5\u8d44\u4f01\u4e1a\u4ea7\u751f\u7ec4\u6210\u6027\u5916\u90e8\u6027\uff0c\u5bfc\u81f4\u5747\u8861\u6548\u7387\u4f4e\u4e0b\uff1a\u5982\u679c\u4f4e\u6280\u80fd\u4f01\u4e1a\u4e5f\u63d0\u51fa\u9ad8\u5de5\u8d44\u5e76\u4f18\u5148\u9009\u62e9\u5458\u5de5\uff0c\u798f\u5229\u5c06\u66f4\u9ad8\u3002\u6211\u4eec\u8fd8\u4e3a\u4f01\u4e1a\u95f4\u5f02\u8d28\u6027\u7684\u7b5b\u9009\u80fd\u529b\u63d0\u4f9b\u4e86\u5fae\u89c2\u57fa\u7840\u3002\u5f53\u6709\u624d\u534e\u7684\u5458\u5de5\u5728\u7b5b\u9009\u65b9\u9762\u8868\u73b0\u66f4\u4f18\uff08\u4f8b\u5982\u901a\u8fc7\u66f4\u51fa\u8272\u7684\u63a8\u8350\uff09\uff0c\u52a8\u6001\u7ecf\u6d4e\u5c06\u6536\u655b\u5230\u4e00\u4e2a\u552f\u4e00\u7684\u7a33\u5b9a\u72b6\u6001\uff0c\u5728\u8be5\u72b6\u6001\u4e0b\uff0c\u4eba\u624d\u5dee\u5f02\u3001\u5229\u6da6\u5dee\u5f02\u548c\u7b5b\u9009\u80fd\u529b\u5dee\u5f02\u5c06\u6c38\u8fdc\u6301\u7eed\u5b58\u5728\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70079", "journal": "JF", "title": "Reference\u2010Dependent Preferences and Sentiment\u2010Driven Asset Prices", "authors": ["JESS BENHABIB", "ZHAORUI LI", "XUEWEN LIU", "PENGFEI WANG"], "author_details": [{"name": "JESS BENHABIB", "affiliations": []}, {"name": "ZHAORUI LI", "affiliations": []}, {"name": "XUEWEN LIU", "affiliations": []}, {"name": "PENGFEI WANG", "affiliations": []}], "abstract": "ABSTRACT This paper studies asset pricing under expectations\u2010based reference\u2010dependent preferences in a general equilibrium framework. We show that reference\u2010dependent preferences can generate self\u2010fulfilling risk panics, producing sentiment\u2010driven asset price fluctuations through a feedback loop between current prices and perceived future downside risk\u2014dynamics impossible under standard expected utility. The model helps explain empirical puzzles including (i) excess volatility, (ii) asymmetric volatility, (iii) asymmetric sentiment over the business cycle, (iv) excess asset price comovement, and (v) weak correlations between stock returns and economic fundamentals, alongside a sizable equity premium. Additional empirical evidence based on closed\u2010end fund discounts and quantitative analysis support the theory.", "date": "2026-08-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70079", "title_zh": "\u53c2\u7167\u4f9d\u8d56\u504f\u597d\u4e0e\u60c5\u7eea\u9a71\u52a8\u7684\u8d44\u4ea7\u4ef7\u683c", "abstract_zh": "\u6458\u8981 \u672c\u6587\u5728\u4e00\u822c\u5747\u8861\u6846\u67b6\u4e0b\u7814\u7a76\u57fa\u4e8e\u671f\u671b\u7684\u53c2\u7167\u4f9d\u8d56\u504f\u597d\u4e0b\u7684\u8d44\u4ea7\u5b9a\u4ef7\u95ee\u9898\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u53c2\u7167\u4f9d\u8d56\u504f\u597d\u53ef\u4ee5\u5f15\u53d1\u81ea\u6211\u5b9e\u73b0\u7684\u98ce\u9669\u6050\u614c\uff0c\u901a\u8fc7\u5f53\u524d\u4ef7\u683c\u4e0e\u611f\u77e5\u5230\u7684\u672a\u6765\u4e0b\u884c\u98ce\u9669\u4e4b\u95f4\u7684\u53cd\u9988\u5faa\u73af\uff0c\u4ea7\u751f\u7531\u60c5\u7eea\u9a71\u52a8\u7684\u8d44\u4ea7\u4ef7\u683c\u6ce2\u52a8\u2014\u2014\u8fd9\u79cd\u52a8\u6001\u5728\u6807\u51c6\u671f\u671b\u6548\u7528\u7406\u8bba\u4e2d\u662f\u65e0\u6cd5\u5b9e\u73b0\u7684\u3002\u8be5\u6a21\u578b\u6709\u52a9\u4e8e\u89e3\u91ca\u4e00\u7cfb\u5217\u5b9e\u8bc1\u96be\u9898\uff0c\u5305\u62ec\uff08i\uff09\u8d85\u989d\u6ce2\u52a8\u6027\uff0c\uff08ii\uff09\u6ce2\u52a8\u6027\u7684\u4e0d\u5bf9\u79f0\u6027\uff0c\uff08iii\uff09\u5468\u671f\u5185\u7684\u60c5\u7eea\u4e0d\u5bf9\u79f0\u6027\uff0c\uff08iv\uff09\u8d44\u4ea7\u4ef7\u683c\u8fc7\u5ea6\u5171\u52a8\uff0c\u4ee5\u53ca\uff08v\uff09\u80a1\u7968\u6536\u76ca\u4e0e\u7ecf\u6d4e\u57fa\u672c\u9762\u4e4b\u95f4\u7684\u5f31\u76f8\u5173\u6027\uff0c\u540c\u65f6\u4f34\u968f\u7740\u663e\u8457\u7684\u80a1\u6743\u6ea2\u4ef7\u3002\u57fa\u4e8e\u5c01\u95ed\u5f0f\u57fa\u91d1\u6298\u4ef7\u548c\u5b9a\u91cf\u5206\u6790\u7684\u989d\u5916\u5b9e\u8bc1\u8bc1\u636e\u652f\u6301\u4e86\u8fd9\u4e00\u7406\u8bba\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u5e02\u573a\u53cd\u9988"]}, {"doi": "10.1111/jofi.70075", "journal": "JF", "title": "The Unintended Consequences of #MeToo: Evidence from Research Collaborations in Economics and Finance", "authors": ["MARINA GERTSBERG"], "author_details": [{"name": "MARINA GERTSBERG", "affiliations": []}], "abstract": "ABSTRACT How did #MeToo alter collaboration between women and men? I show junior female researchers start fewer projects after #MeToo. A decrease in collaborations with male coauthors\u2014especially new senior male coauthors at the same institution\u2014largely explains the decline. The decrease is larger at universities with higher perceived harassment accusation risk and smaller where both women and men publicly express greater awareness of gender issues. I find no evidence that reduced collaboration improves research outcomes for junior female researchers. The results suggest that #MeToo led to a breakdown in trust that came at a cost for junior women's career opportunities.", "date": "2026-08-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70075", "title_zh": "#MeToo\u7684\u610f\u5916\u540e\u679c\uff1a\u6765\u81ea\u7ecf\u6d4e\u5b66\u548c\u91d1\u878d\u5b66\u7814\u7a76\u5408\u4f5c\u7684\u8bc1\u636e", "abstract_zh": "\u6458\u8981 #MeToo\u5982\u4f55\u6539\u53d8\u4e86\u5973\u6027\u4e0e\u7537\u6027\u4e4b\u95f4\u7684\u5408\u4f5c\uff1f\u6211\u53d1\u73b0\uff0c\u5728#MeToo\u4e4b\u540e\uff0c\u5e74\u8f7b\u5973\u6027\u7814\u7a76\u4eba\u5458\u542f\u52a8\u7684\u9879\u76ee\u6570\u91cf\u51cf\u5c11\u4e86\u3002\u4e0e\u7537\u6027\u5408\u4f5c\u8005\uff08\u5c24\u5176\u662f\u540c\u4e00\u673a\u6784\u7684\u65b0\u4efb\u8d44\u6df1\u7537\u6027\u5408\u4f5c\u8005\uff09\u7684\u5408\u4f5c\u51cf\u5c11\uff0c\u5f88\u5927\u7a0b\u5ea6\u4e0a\u89e3\u91ca\u4e86\u8fd9\u4e00\u4e0b\u964d\u8d8b\u52bf\u3002\u5728\u88ab\u8ba4\u4e3a\u5b58\u5728\u66f4\u9ad8\u6027\u9a9a\u6270\u6307\u63a7\u98ce\u9669\u7684\u5927\u5b66\u4e2d\uff0c\u8fd9\u79cd\u51cf\u5c11\u66f4\u4e3a\u663e\u8457\uff0c\u800c\u5728\u5973\u6027\u548c\u7537\u6027\u90fd\u516c\u5f00\u8868\u73b0\u51fa\u66f4\u5f3a\u6027\u522b\u95ee\u9898\u610f\u8bc6\u7684\u5730\u533a\uff0c\u8fd9\u79cd\u51cf\u5c11\u5219\u66f4\u5c0f\u3002\u6211\u5e76\u672a\u53d1\u73b0\u5408\u4f5c\u51cf\u5c11\u5bf9\u5e74\u8f7b\u5973\u6027\u7814\u7a76\u4eba\u5458\u7814\u7a76\u6210\u679c\u6709\u6539\u5584\u4f5c\u7528\u3002\u7ed3\u679c\u8868\u660e\uff0c#MeToo\u5bfc\u81f4\u4e86\u4fe1\u4efb\u7684\u7834\u88c2\uff0c\u8fd9\u5bf9\u5e74\u8f7b\u5973\u6027\u7684\u804c\u4e1a\u53d1\u5c55\u9020\u6210\u4e86\u4ee3\u4ef7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.06968", "journal": "MS", "title": "Dissecting Anomalies in Conditional Asset Pricing", "authors": ["Valentina Raponi", "Paolo Zaffaroni"], "author_details": [{"name": "Valentina Raponi", "affiliations": ["IESE Business School, Department of Financial Management, University of Navarra, 08034 Barcelona, Spain"]}, {"name": "Paolo Zaffaroni", "affiliations": ["Imperial College Business School, Finance Department, Imperial College London, London SW7 2AZ, United Kingdom; and Department of Economics and Law, Sapienza University of Rome, 00161 Rome, Italy"]}], "abstract": "This paper introduces a novel methodology for analyzing anomalies in conditional asset pricing models with time-varying risk exposures and premia. Our approach extends the conventional two-pass methodology to include both ordinary and weighted least-squares estimation in a conditional setting. We establish closed-form standard errors to statistically dissect anomalies, including a version robust to global misspecification. We introduce a novel R 2 criterion to quantify the joint contribution of large anomaly sets in explaining cross-sectional stock return variations. Our analysis highlights the significant impact of anomalies during economic and financial crises, linking them closely with market conditions.", "date": "2026-08-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06968", "title_zh": "\u5206\u89e3\u6761\u4ef6\u8d44\u4ea7\u5b9a\u4ef7\u4e2d\u7684\u5f02\u5e38\u73b0\u8c61", "abstract_zh": "\u672c\u6587\u63d0\u51fa\u4e86\u4e00\u79cd\u5206\u6790\u5177\u6709\u65f6\u95f4\u53d8\u5316\u98ce\u9669\u66b4\u9732\u548c\u6ea2\u4ef7\u7684\u6761\u4ef6\u8d44\u4ea7\u5b9a\u4ef7\u6a21\u578b\u4e2d\u5f02\u5e38\u73b0\u8c61\u7684\u65b0\u65b9\u6cd5\u3002\u6211\u4eec\u7684\u65b9\u6cd5\u5c06\u4f20\u7edf\u7684\u4e24\u6b65\u6cd5\u6269\u5c55\u5230\u6761\u4ef6\u8bbe\u7f6e\u4e2d\uff0c\u5305\u542b\u4e86\u666e\u901a\u6700\u5c0f\u4e8c\u4e58\u6cd5\u548c\u52a0\u6743\u6700\u5c0f\u4e8c\u4e58\u6cd5\u7684\u4f30\u8ba1\u3002\u6211\u4eec\u5efa\u7acb\u4e86\u95ed\u5f0f\u6807\u51c6\u8bef\uff0c\u4ee5\u7edf\u8ba1\u4e0a\u5206\u89e3\u5f02\u5e38\u73b0\u8c61\uff0c\u5305\u62ec\u4e00\u79cd\u5bf9\u5168\u5c40\u6a21\u578b\u8bbe\u5b9a\u9519\u8bef\u5177\u6709\u9c81\u68d2\u6027\u7684\u7248\u672c\u3002\u6211\u4eec\u5f15\u5165\u4e86\u4e00\u79cd\u65b0\u7684R\u00b2\u51c6\u5219\uff0c\u7528\u4e8e\u91cf\u5316\u5927\u91cf\u5f02\u5e38\u96c6\u5408\u5171\u540c\u89e3\u91ca\u8de8\u622a\u9762\u80a1\u7968\u56de\u62a5\u53d8\u5f02\u7684\u8d21\u732e\u3002\u6211\u4eec\u7684\u5206\u6790\u5f3a\u8c03\u4e86\u5f02\u5e38\u73b0\u8c61\u5728\u7ecf\u6d4e\u548c\u91d1\u878d\u5371\u673a\u671f\u95f4\u7684\u663e\u8457\u5f71\u54cd\uff0c\u5e76\u5c06\u5176\u4e0e\u5e02\u573a\u72b6\u51b5\u7d27\u5bc6\u5173\u8054\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1287/mnsc.2024.08851", "journal": "MS", "title": "The Factor Multiverse: The Role of Interest Rates in Factor Return Measurement", "authors": ["Liang Ma"], "author_details": [{"name": "Liang Ma", "affiliations": ["Department of Finance, Fowler College of Business, San Diego State University, San Diego, California 92182"]}], "abstract": "We study the equity factor zoo using a duration-matching return-decomposition approach that adjusts factor returns by subtracting returns on duration-matched government bond portfolios. By doing so, we remove the component of factor returns attributable to interest rate movements while preserving shocks to expected growth and risk premia observed in the data. Among commonly used factors, the value, investment, and profitability premia increase after duration matching, while the market and size premia decrease, over the post-1981 sample period. Furthermore, the effect of duration matching on mean factor returns depends importantly on the interest rate environment, consistent with our return decomposition framework.", "date": "2026-08-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08851", "title_zh": "\u56e0\u5b50\u591a\u5143\u5b87\u5b99\uff1a\u5229\u7387\u5728\u56e0\u5b50\u6536\u76ca\u6d4b\u91cf\u4e2d\u7684\u4f5c\u7528", "abstract_zh": "\u6211\u4eec\u91c7\u7528\u4e00\u79cd\u671f\u9650\u5339\u914d\u7684\u6536\u76ca\u5206\u89e3\u65b9\u6cd5\u6765\u7814\u7a76\u80a1\u6743\u56e0\u5b50\u4f53\u7cfb\uff0c\u8be5\u65b9\u6cd5\u901a\u8fc7\u4ece\u56e0\u5b50\u6536\u76ca\u4e2d\u51cf\u53bb\u671f\u9650\u5339\u914d\u7684\u653f\u5e9c\u503a\u5238\u7ec4\u5408\u7684\u6536\u76ca\uff0c\u4ece\u800c\u5254\u9664\u7531\u5229\u7387\u53d8\u52a8\u5f15\u8d77\u7684\u56e0\u5b50\u6536\u76ca\u6210\u5206\uff0c\u540c\u65f6\u4fdd\u7559\u6570\u636e\u4e2d\u89c2\u5bdf\u5230\u7684\u9884\u671f\u589e\u957f\u548c\u98ce\u9669\u6ea2\u4ef7\u7684\u51b2\u51fb\u3002\u5728\u5e38\u7528\u7684\u56e0\u5b50\u4e2d\uff0c\u4ef7\u503c\u3001\u6295\u8d44\u548c\u76c8\u5229\u80fd\u529b\u6ea2\u4ef7\u5728\u671f\u9650\u5339\u914d\u540e\u4e0a\u5347\uff0c\u800c\u5e02\u573a\u548c\u89c4\u6a21\u6ea2\u4ef7\u5219\u4e0b\u964d\uff0c\u8fd9\u4e00\u73b0\u8c61\u51fa\u73b0\u57281981\u5e74\u4e4b\u540e\u7684\u6837\u672c\u671f\u5185\u3002\u6b64\u5916\uff0c\u671f\u9650\u5339\u914d\u5bf9\u5e73\u5747\u56e0\u5b50\u6536\u76ca\u7684\u5f71\u54cd\u5728\u5f88\u5927\u7a0b\u5ea6\u4e0a\u53d6\u51b3\u4e8e\u5229\u7387\u73af\u5883\uff0c\u8fd9\u4e0e\u6211\u4eec\u7684\u6536\u76ca\u5206\u89e3\u6846\u67b6\u76f8\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhag078", "journal": "RFS", "title": "Carbon Emissions and the Bank-Lending Channel", "authors": ["Marcin Kacperczyk", "Jos\u00e9-Luis Peydr\u00f3"], "author_details": [{"name": "Marcin Kacperczyk", "affiliations": ["Imperial College London, UK, CEPR, and ECGI"]}, {"name": "Jos\u00e9-Luis Peydr\u00f3", "affiliations": ["Luiss University, Italy, EIEF, and CEPR"]}], "abstract": "Abstract We study how firm-level carbon emissions affect bank lending and real outcomes in a sample of global firms with syndicated loans. We exploit bank-level climate commitments as firm-level shocks to lending relationships, using firms' prior credit exposures to identify credit supply effects. Firms with higher emissions that previously borrowed from committed banks receive less bank credit. Evidence from lending volumes, prices, and within-firm-time loan-level data indicates a supply-side shift away from high-emission firms, not explained by borrower risk. Affected firms reduce debt, leverage, size, and investment, yet we find no reduction in future emissions, instead documenting evidence consistent with greenwashing.", "date": "2026-08-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag078", "title_zh": "\u78b3\u6392\u653e\u4e0e\u94f6\u884c\u4fe1\u8d37\u6e20\u9053", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u4f01\u4e1a\u5c42\u9762\u7684\u78b3\u6392\u653e\u5982\u4f55\u5f71\u54cd\u94f6\u884c\u8d37\u6b3e\u548c\u5b9e\u9645\u7ecf\u6d4e\u7ed3\u679c\uff0c\u6837\u672c\u4e3a\u5177\u6709\u94f6\u56e2\u8d37\u6b3e\u7684\u5168\u7403\u4f01\u4e1a\u3002\u6211\u4eec\u5229\u7528\u94f6\u884c\u5c42\u9762\u7684\u6c14\u5019\u627f\u8bfa\u4f5c\u4e3a\u4f01\u4e1a\u5c42\u9762\u7684\u51b2\u51fb\uff0c\u901a\u8fc7\u4f01\u4e1a\u5148\u524d\u7684\u4fe1\u8d37\u66b4\u9732\u6765\u8bc6\u522b\u4fe1\u8d37\u4f9b\u7ed9\u6548\u5e94\u3002\u78b3\u6392\u653e\u8f83\u9ad8\u7684\u4f01\u4e1a\u82e5\u6b64\u524d\u66fe\u4ece\u627f\u8bfa\u94f6\u884c\u501f\u6b3e\uff0c\u5219\u83b7\u5f97\u7684\u94f6\u884c\u4fe1\u8d37\u66f4\u5c11\u3002\u6765\u81ea\u8d37\u6b3e\u89c4\u6a21\u3001\u8d37\u6b3e\u4ef7\u683c\u4ee5\u53ca\u4f01\u4e1a\u5185\u90e8\u65f6\u95f4\u7ef4\u5ea6\u8d37\u6b3e\u5c42\u9762\u7684\u6570\u636e\u8868\u660e\uff0c\u4fe1\u8d37\u4f9b\u7ed9\u51fa\u73b0\u4e86\u5411\u9ad8\u6392\u653e\u4f01\u4e1a\u503e\u659c\u7684\u8f6c\u53d8\uff0c\u8fd9\u4e00\u73b0\u8c61\u65e0\u6cd5\u7528\u501f\u6b3e\u4eba\u7684\u98ce\u9669\u6c34\u5e73\u6765\u89e3\u91ca\u3002\u53d7\u5f71\u54cd\u7684\u4f01\u4e1a\u51cf\u5c11\u4e86\u503a\u52a1\u3001\u6760\u6746\u7387\u3001\u89c4\u6a21\u548c\u6295\u8d44\uff0c\u4f46\u6211\u4eec\u5e76\u672a\u53d1\u73b0\u672a\u6765\u6392\u653e\u91cf\u7684\u4e0b\u964d\uff0c\u53cd\u800c\u53d1\u73b0\u4e86\u4e0e\u7eff\u8272\u6d17\u724c\u4e00\u81f4\u7684\u8bc1\u636e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.05504", "journal": "MS", "title": "Media Sentiment on Foreign Countries and International Asset Allocation", "authors": ["Baixiao Liu", "Linlin Ma"], "author_details": [{"name": "Baixiao Liu", "affiliations": ["Peking University HSBC Business School, University Town, Nanshan District, Shenzhen, Guangdong 518055, China"]}, {"name": "Linlin Ma", "affiliations": ["Peking University HSBC Business School, University Town, Nanshan District, Shenzhen, Guangdong 518055, China"]}], "abstract": "We examine whether U.S. media sentiment on foreign countries influences domestic investors\u2019 international asset allocation. Using flows to country-specific mutual funds as a proxy for investor demand, we find that negative media sentiment, measured by the interaction of negative tone and media attention given to foreign countries, is strongly associated with reduced investor flows into funds targeting those countries. This relationship is driven, at least in part, by media sentiment that is unrelated to the economic fundamentals of the targeted countries. We employ The Wall Street Journal\u2019s acquisition by News Corp to support the causal interpretation of our findings. Our results highlight the perception-shaping role of media narratives in driving global investment decisions.", "date": "2026-08-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.05504", "title_zh": "\u5916\u56fd\u56fd\u5bb6\u7684\u5a92\u4f53\u60c5\u7eea\u5bf9\u56fd\u9645\u8d44\u4ea7\u914d\u7f6e\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u7f8e\u56fd\u5a92\u4f53\u5bf9\u5916\u56fd\u56fd\u5bb6\u7684\u60c5\u7eea\u662f\u5426\u4f1a\u5f71\u54cd\u56fd\u5185\u6295\u8d44\u8005\u7684\u56fd\u9645\u8d44\u4ea7\u914d\u7f6e\u3002\u5229\u7528\u6d41\u5411\u7279\u5b9a\u56fd\u5bb6\u5171\u540c\u57fa\u91d1\u7684\u91d1\u989d\u4f5c\u4e3a\u6295\u8d44\u8005\u9700\u6c42\u7684\u4ee3\u7406\u53d8\u91cf\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u8d1f\u9762\u5a92\u4f53\u60c5\u7eea\u2014\u2014\u5373\u8d1f\u9762\u8bed\u6c14\u4e0e\u5bf9\u5916\u56fd\u56fd\u5bb6\u7684\u5a92\u4f53\u5173\u6ce8\u5ea6\u7684\u4ea4\u4e92\u4f5c\u7528\u2014\u2014\u4e0e\u6295\u8d44\u8005\u5bf9\u8fd9\u4e9b\u56fd\u5bb6\u76ee\u6807\u57fa\u91d1\u7684\u6d41\u5165\u51cf\u5c11\u663e\u8457\u76f8\u5173\u3002\u8fd9\u79cd\u5173\u7cfb\u5728\u4e00\u5b9a\u7a0b\u5ea6\u4e0a\u662f\u7531\u4e0e\u76ee\u6807\u56fd\u5bb6\u7ecf\u6d4e\u57fa\u672c\u9762\u65e0\u5173\u7684\u5a92\u4f53\u60c5\u7eea\u9a71\u52a8\u7684\u3002\u6211\u4eec\u5229\u7528\u300a\u534e\u5c14\u8857\u65e5\u62a5\u300b\u88ab\u65b0\u95fb\u96c6\u56e2\u6536\u8d2d\u8fd9\u4e00\u4e8b\u4ef6\u6765\u652f\u6301\u6211\u4eec\u7814\u7a76\u7ed3\u679c\u7684\u56e0\u679c\u89e3\u91ca\u3002\u672c\u7814\u7a76\u5f3a\u8c03\u4e86\u5a92\u4f53\u53d9\u4e8b\u5728\u5851\u9020\u5168\u7403\u6295\u8d44\u51b3\u7b56\u4e2d\u7684\u611f\u77e5\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1287/mnsc.2023.00773", "journal": "MS", "title": "Entrepreneurial Teams: Prior Industry Experience and Early-Stage Growth", "authors": ["Francesco D\u2019Acunto", "Geoffrey Tate", "Liu Yang"], "author_details": [{"name": "Francesco D\u2019Acunto", "affiliations": ["McDonough School of Business, Georgetown University, Washington, District of Columbia 20009"]}, {"name": "Geoffrey Tate", "affiliations": ["University of Maryland, College Park, Maryland 20742; and NBER, Cambridge, Massachusetts 02138"]}, {"name": "Liu Yang", "affiliations": ["University of Maryland, College Park, Maryland 20742"]}], "abstract": "We use career backgrounds of initial employees from a full cohort of U.S. startups to measure founding teams\u2019 skillsets. Startups with more diverse prior industry experience grow faster than same-industry local peers. One-standard-deviation-higher diversity is associated with 16% (10%) higher five-year employment (sales) growth, controlling for demographic diversity, prestartup wages, and other observables. Startups in innovative industries and facing lower coordination costs among team members drive the results. To address endogeneity, we exploit shocks in which teams suddenly lose members with unduplicated skills. Overall, combining individual specialization with team-level diversification allows teams to act as \u201cjacks of all trades and masters of each.\u201d", "date": "2026-08-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.00773", "title_zh": "\u521b\u4e1a\u56e2\u961f\uff1a\u5148\u524d\u884c\u4e1a\u7ecf\u9a8c\u4e0e\u65e9\u671f\u6210\u957f", "abstract_zh": "\u6211\u4eec\u5229\u7528\u7f8e\u56fd\u521d\u521b\u4f01\u4e1a\u521d\u59cb\u5458\u5de5\u7684\u804c\u4e1a\u80cc\u666f\uff0c\u6765\u8861\u91cf\u521b\u4e1a\u56e2\u961f\u7684\u6280\u80fd\u6784\u6210\u3002\u76f8\u6bd4\u540c\u884c\u4e1a\u672c\u5730\u540c\u884c\uff0c\u62e5\u6709\u66f4\u591a\u5148\u524d\u884c\u4e1a\u7ecf\u9a8c\u591a\u6837\u6027\u7684\u521d\u521b\u4f01\u4e1a\u6210\u957f\u901f\u5ea6\u66f4\u5feb\u3002\u5728\u63a7\u5236\u4e86\u4eba\u53e3\u7edf\u8ba1\u5b66\u591a\u6837\u6027\u3001\u521b\u4e1a\u524d\u5de5\u8d44\u53ca\u5176\u4ed6\u53ef\u89c2\u6d4b\u53d8\u91cf\u540e\uff0c\u884c\u4e1a\u7ecf\u9a8c\u591a\u6837\u6027\u9ad8\u51fa\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u4e0e\u4e94\u5e74\u5185\u5c31\u4e1a\uff08\u9500\u552e\u989d\uff09\u589e\u957f\u9ad8\u51fa16%\uff0810%\uff09\u76f8\u5173\u3002\u5728\u521b\u65b0\u884c\u4e1a\u4e14\u56e2\u961f\u6210\u5458\u95f4\u534f\u8c03\u6210\u672c\u8f83\u4f4e\u7684\u521d\u521b\u4f01\u4e1a\u4e2d\uff0c\u8fd9\u4e00\u7ed3\u679c\u66f4\u4e3a\u663e\u8457\u3002\u4e3a\u89e3\u51b3\u5185\u751f\u6027\u95ee\u9898\uff0c\u6211\u4eec\u5229\u7528\u56e2\u961f\u6210\u5458\u7a81\u7136\u5931\u53bb\u5177\u6709\u72ec\u7279\u6280\u80fd\u6210\u5458\u7684\u51b2\u51fb\u4e8b\u4ef6\u3002\u603b\u4f53\u800c\u8a00\uff0c\u7ed3\u5408\u4e2a\u4f53\u4e13\u4e1a\u6280\u80fd\u4e0e\u56e2\u961f\u5c42\u9762\u7684\u591a\u6837\u5316\uff0c\u4f7f\u56e2\u961f\u80fd\u591f\u5b9e\u73b0\u2018\u901a\u624d\u901a\u6653\uff0c\u4e13\u624d\u7cbe\u901a\u2019\u7684\u6548\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2025.00669", "journal": "MS", "title": "An Analysis of Heritability in Preferences Using Behavioral Models of Decision Making", "authors": ["Nathan Kettlewell", "Agnieszka Tymula", "Hong Il Yoo"], "author_details": [{"name": "Nathan Kettlewell", "affiliations": ["School of Economics and Marketing, University of Technology Sydney, Ultimo, New South Wales 2007, Australia"]}, {"name": "Agnieszka Tymula", "affiliations": ["School of Economics, The University of Sydney, Sydney, New South Wales 2006, Australia"]}, {"name": "Hong Il Yoo", "affiliations": ["Loughborough Business School, Loughborough University, Leicestershire LE11 3TU, United Kingdom"]}], "abstract": "We investigate the heritability of risk, uncertainty, and time preferences using a large-scale field experiment with adult twins, complemented by a comprehensive meta-analysis of prior studies. Our research introduces a novel empirical approach that integrates behavioral genetics with structural econometrics, enabling us to directly quantify the heritability of latent preference parameters in behavioral models of decision making, without relying on observed proxies. Our incentive-compatible experiment is the first to simultaneously elicit all three types of preferences within the same individuals in a twin study. Our findings reveal a stronger genetic influence on risk and uncertainty preferences than previously reported. We demonstrate that conventional proxy measures for preferences and simplified structural models tend to overstate the influence of unique environmental factors. These results help contextualize preference heterogeneity as a driver of persistent differences in decision making across individuals, leaders, and organizations.", "date": "2026-08-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.00669", "title_zh": "\u4f7f\u7528\u884c\u4e3a\u51b3\u7b56\u6a21\u578b\u7814\u7a76\u504f\u597d\u9057\u4f20\u6027\u5206\u6790", "abstract_zh": "\u6211\u4eec\u5229\u7528\u5927\u89c4\u6a21\u73b0\u573a\u5b9e\u9a8c\u4e0e\u6210\u4eba\u53cc\u80de\u80ce\u7814\u7a76\u76f8\u7ed3\u5408\u7684\u5168\u9762\u5143\u5206\u6790\uff0c\u63a2\u8ba8\u4e86\u98ce\u9669\u3001\u4e0d\u786e\u5b9a\u6027\u4ee5\u53ca\u65f6\u95f4\u504f\u597d\u7684\u9057\u4f20\u6027\u3002\u672c\u7814\u7a76\u5f15\u5165\u4e86\u4e00\u79cd\u65b0\u9896\u7684\u5b9e\u8bc1\u65b9\u6cd5\uff0c\u5c06\u884c\u4e3a\u9057\u4f20\u5b66\u4e0e\u7ed3\u6784\u8ba1\u91cf\u7ecf\u6d4e\u5b66\u76f8\u7ed3\u5408\uff0c\u4ece\u800c\u80fd\u591f\u76f4\u63a5\u91cf\u5316\u884c\u4e3a\u51b3\u7b56\u6a21\u578b\u4e2d\u6f5c\u5728\u504f\u597d\u53c2\u6570\u7684\u9057\u4f20\u6027\uff0c\u800c\u65e0\u9700\u4f9d\u8d56\u89c2\u5bdf\u5230\u7684\u4ee3\u7406\u53d8\u91cf\u3002\u6211\u4eec\u7684\u6fc0\u52b1\u76f8\u5bb9\u5b9e\u9a8c\u662f\u9996\u4e2a\u5728\u540c\u4e00\u53cc\u80de\u80ce\u7814\u7a76\u4e2d\u540c\u65f6\u4ece\u4e2a\u4f53\u5c42\u9762\u63d0\u53d6\u98ce\u9669\u3001\u4e0d\u786e\u5b9a\u6027\u548c\u65f6\u95f4\u504f\u597d\u7684\u5b9e\u9a8c\u3002\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u98ce\u9669\u548c\u4e0d\u786e\u5b9a\u6027\u504f\u597d\u7684\u9057\u4f20\u5f71\u54cd\u5f3a\u4e8e\u4ee5\u5f80\u62a5\u544a\u7684\u7ed3\u679c\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u4f20\u7edf\u504f\u597d\u4ee3\u7406\u6307\u6807\u548c\u7b80\u5316\u7ed3\u6784\u6a21\u578b\u5f80\u5f80\u9ad8\u4f30\u4e86\u72ec\u7279\u73af\u5883\u56e0\u7d20\u7684\u5f71\u54cd\u3002\u8fd9\u4e9b\u7ed3\u679c\u6709\u52a9\u4e8e\u5c06\u504f\u597d\u5f02\u8d28\u6027\u89e3\u91ca\u4e3a\u4e2a\u4f53\u3001\u9886\u5bfc\u8005\u548c\u7ec4\u7ec7\u95f4\u6301\u7eed\u51b3\u7b56\u5dee\u5f02\u7684\u9a71\u52a8\u56e0\u7d20\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.05424", "journal": "MS", "title": "A Nonparametric Framework for Online Stochastic Matching with Correlated Arrivals", "authors": ["Ali Aouad", "Will Ma"], "author_details": [{"name": "Ali Aouad", "affiliations": ["Sloan School of Management, Massachusetts Institute of Technology, Cambridge, Massachusetts 02139"]}, {"name": "Will Ma", "affiliations": ["Graduate School of Business and Data Science Institute, Columbia University, New York, New York 10027"]}], "abstract": "The design of online algorithms for matching markets and revenue management settings is usually bound by the assumption that the demand process is formed by a fixed-length sequence of queries with unknown types, each drawn independently. This notion of serial independence implies that the demand of each type, that is, the number of queries of a given type, has low variance and is approximately Poisson distributed. This paper proposes a nonparametric framework for modeling arrival sequences in online stochastic matching that departs from the serial independent assumption. We propose two models, Indep and Correl, that capture different forms of serial correlations by combining a nonparametric distribution for the demand with standard assumptions on the arrival patterns: adversarial or random order. The Indep model can capture arbitrary serial correlations within each customer type but assumes cross-sectional independence across types, whereas the Correl model captures common shocks across customer types. We demonstrate that fluid relaxations, which rely solely on demand expectations, have arbitrarily bad performance guarantees. In contrast, we develop new algorithms that achieve optimal (constant factor) performance guarantees in each model. Our mathematical analysis includes tighter linear programming (LP) relaxations that leverage distribution knowledge and a new lossless randomized LP rounding scheme for Indep. We test our new LP relaxations and rounding scheme in simulations on real and synthetic data and find that they consistently outperform well-established matching algorithms, especially on real data sequences that exhibit greater demand variance.", "date": "2026-08-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.05424", "title_zh": "\u4e00\u79cd\u7528\u4e8e\u5177\u6709\u76f8\u5173\u5230\u8fbe\u7684\u5728\u7ebf\u968f\u673a\u5339\u914d\u7684\u975e\u53c2\u6570\u6846\u67b6", "abstract_zh": "\u5728\u7ebf\u5339\u914d\u5e02\u573a\u548c\u6536\u5165\u7ba1\u7406\u573a\u666f\u4e2d\u8bbe\u8ba1\u5728\u7ebf\u7b97\u6cd5\u901a\u5e38\u53d7\u9650\u4e8e\u9700\u6c42\u8fc7\u7a0b\u7531\u56fa\u5b9a\u957f\u5ea6\u7684\u67e5\u8be2\u5e8f\u5217\u7ec4\u6210\uff0c\u4e14\u6bcf\u4e2a\u67e5\u8be2\u7684\u7c7b\u578b\u662f\u672a\u77e5\u7684\uff0c\u4e14\u72ec\u7acb\u62bd\u53d6\u8fd9\u4e00\u5047\u8bbe\u3002\u8fd9\u79cd\u5e8f\u5217\u72ec\u7acb\u6027\u610f\u5473\u7740\u6bcf\u79cd\u7c7b\u578b\u7684\u9700\u6c42\uff0c\u5373\u7ed9\u5b9a\u7c7b\u578b\u7684\u67e5\u8be2\u6570\u91cf\uff0c\u65b9\u5dee\u8f83\u4f4e\u4e14\u8fd1\u4f3c\u4e8e\u6cca\u677e\u5206\u5e03\u3002\u672c\u6587\u63d0\u51fa\u4e86\u4e00\u79cd\u7528\u4e8e\u5efa\u6a21\u5728\u7ebf\u968f\u673a\u5339\u914d\u4e2d\u5230\u8fbe\u5e8f\u5217\u7684\u975e\u53c2\u6570\u6846\u67b6\uff0c\u6253\u7834\u4e86\u5e8f\u5217\u72ec\u7acb\u6027\u7684\u5047\u8bbe\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u4e24\u79cd\u6a21\u578b\uff0cIndep \u548c Correl\uff0c\u901a\u8fc7\u7ed3\u5408\u5bf9\u9700\u6c42\u7684\u975e\u53c2\u6570\u5206\u5e03\u4e0e\u6807\u51c6\u5230\u8fbe\u6a21\u5f0f\uff08\u5bf9\u6297\u6027\u6216\u968f\u673a\u987a\u5e8f\uff09\u7684\u5047\u8bbe\uff0c\u6355\u6349\u4e86\u4e0d\u540c\u5f62\u5f0f\u7684\u5e8f\u5217\u76f8\u5173\u6027\u3002Indep \u6a21\u578b\u53ef\u4ee5\u5728\u6bcf\u79cd\u5ba2\u6237\u7c7b\u578b\u5185\u90e8\u6355\u6349\u4efb\u610f\u7684\u5e8f\u5217\u76f8\u5173\u6027\uff0c\u4f46\u5047\u8bbe\u4e0d\u540c\u7c7b\u578b\u4e4b\u95f4\u5177\u6709\u6a2a\u622a\u9762\u72ec\u7acb\u6027\uff1b\u800c Correl \u6a21\u578b\u5219\u6355\u6349\u4e86\u5ba2\u6237\u7c7b\u578b\u4e4b\u95f4\u7684\u5171\u540c\u51b2\u51fb\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u4ec5\u4f9d\u8d56\u9700\u6c42\u671f\u671b\u7684\u6d41\u677e\u5f1b\u65b9\u6cd5\uff0c\u5176\u6027\u80fd\u4fdd\u8bc1\u662f\u4efb\u610f\u5dee\u7684\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u6211\u4eec\u5f00\u53d1\u4e86\u5728\u6bcf\u4e2a\u6a21\u578b\u4e2d\u5747\u80fd\u5b9e\u73b0\u6700\u4f18\uff08\u5e38\u6570\u56e0\u5b50\uff09\u6027\u80fd\u4fdd\u8bc1\u7684\u65b0\u7b97\u6cd5\u3002\u6211\u4eec\u7684\u6570\u5b66\u5206\u6790\u5305\u62ec\u5229\u7528\u5206\u5e03\u77e5\u8bc6\u7684\u66f4\u7d27\u7ebf\u6027\u89c4\u5212\uff08LP\uff09\u677e\u5f1b\u65b9\u6cd5\uff0c\u4ee5\u53ca\u4e3a Indep \u6a21\u578b\u8bbe\u8ba1\u7684\u4e00\u79cd\u65e0\u635f\u968f\u673a LP \u5706\u6574\u65b9\u6848\u3002\u6211\u4eec\u5728\u771f\u5b9e\u548c\u5408\u6210\u6570\u636e\u4e0a\u7684\u6a21\u62df\u4e2d\u6d4b\u8bd5\u4e86\u65b0\u7684 LP \u677e\u5f1b\u548c\u5706\u6574\u65b9\u6848\uff0c\u53d1\u73b0\u5b83\u4eec\u5728\u8868\u73b0\u4e0a\u59cb\u7ec8\u4f18\u4e8e\u5df2\u5efa\u7acb\u7684\u5339\u914d\u7b97\u6cd5\uff0c\u5c24\u5176\u662f\u5728\u90a3\u4e9b\u8868\u73b0\u51fa\u66f4\u9ad8\u9700\u6c42\u65b9\u5dee\u7684\u771f\u5b9e\u6570\u636e\u5e8f\u5217\u4e0a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70076", "journal": "JF", "title": "Can Small Businesses Survive Chapter 11?", "authors": ["EDITH HOTCHKISS", "BENJAMIN IVERSON", "XIANG ZHENG"], "author_details": [{"name": "EDITH HOTCHKISS", "affiliations": []}, {"name": "BENJAMIN IVERSON", "affiliations": []}, {"name": "XIANG ZHENG", "affiliations": []}], "abstract": "ABSTRACT A majority of small U.S. businesses attempting to reorganize in bankruptcy fail to do so. Subchapter V of Chapter 11 (SubV) streamlines bankruptcy for small firms by reducing bankruptcy costs and negotiation frictions, and enables entrepreneurs to retain ownership. We show that many businesses reorganize under SubV that otherwise would liquidate. Creditor recoveries and postbankruptcy survival rates are at least as high in SubV as in traditional Chapter 11s. Our results show the increase in reorganizations is not associated with continuation of unviable firms, and that creditors are not harmed by a shift in bargaining power toward small business owners.", "date": "2026-08-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70076", "title_zh": "\u5c0f\u578b\u4f01\u4e1a\u80fd\u901a\u8fc7\u7b2c11\u7ae0\u7834\u4ea7\u7a0b\u5e8f\u751f\u5b58\u5417\uff1f", "abstract_zh": "\u6458\u8981 \u5927\u591a\u6570\u8bd5\u56fe\u901a\u8fc7\u7834\u4ea7\u91cd\u7ec4\u6765\u91cd\u65b0\u7ec4\u7ec7\u7684\u7f8e\u56fd\u5c0f\u578b\u4f01\u4e1a\u6700\u7ec8\u672a\u80fd\u6210\u529f\u91cd\u7ec4\u3002\u7b2c11\u7ae0\u7684\u5b50\u7ae0\u8282V\uff08SubV\uff09\u901a\u8fc7\u964d\u4f4e\u7834\u4ea7\u6210\u672c\u548c\u8c08\u5224\u6469\u64e6\uff0c\u5e76\u5141\u8bb8\u4f01\u4e1a\u5bb6\u4fdd\u7559\u6240\u6709\u6743\uff0c\u7b80\u5316\u4e86\u5c0f\u578b\u4f01\u4e1a\u7684\u7834\u4ea7\u7a0b\u5e8f\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8bb8\u591a\u4f01\u4e1a\u9009\u62e9\u5728SubV\u4e0b\u8fdb\u884c\u91cd\u7ec4\uff0c\u800c\u8fd9\u4e9b\u4f01\u4e1a\u82e5\u672a\u91c7\u7528SubV\u5219\u4f1a\u76f4\u63a5\u6e05\u7b97\u3002\u5728SubV\u4e0b\u7684\u503a\u6743\u4eba\u56de\u6536\u91d1\u989d\u548c\u7834\u4ea7\u540e\u7684\u751f\u5b58\u7387\u81f3\u5c11\u4e0e\u4f20\u7edf\u7b2c11\u7ae0\u7834\u4ea7\u7a0b\u5e8f\u76f8\u5f53\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u91cd\u7ec4\u6570\u91cf\u7684\u589e\u52a0\u4e0e\u4e0d\u53ef\u6301\u7eed\u4f01\u4e1a\u7ee7\u7eed\u8fd0\u8425\u65e0\u5173\uff0c\u4e14\u503a\u6743\u4eba\u5e76\u672a\u56e0\u8c08\u5224\u6743\u529b\u5411\u5c0f\u578b\u4f01\u4e1a\u6240\u6709\u8005\u8f6c\u79fb\u800c\u53d7\u5230\u635f\u5bb3\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70074", "journal": "JF", "title": "Marginal Q", "authors": ["VITO D. GALA", "JOAO F. GOMES", "TONG LIU"], "author_details": [{"name": "VITO D. GALA", "affiliations": []}, {"name": "JOAO F. GOMES", "affiliations": []}, {"name": "TONG LIU", "affiliations": []}], "abstract": "ABSTRACT We propose a new method to estimate the marginal value of capital under minimal assumptions. By combining asset prices with fundamentals, our method provides a quasi\u2010model\u2010free marginal q together with a simple correction for measurement error in (average) Tobin's Q using linear regressions. Marginal q yields plausible and robust estimates of adjustment costs and investment sensitivities to fundamentals. The widening gap between marginal q and Tobin's Q is driven primarily by market power and intangible capital. Our novel findings strongly support the neoclassical theory of investment and challenge the widespread use of Tobin's Q as proxy for investment opportunities.", "date": "2026-08-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70074", "title_zh": "\u8fb9\u9645Q", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u5728\u6700\u5c11\u5047\u8bbe\u6761\u4ef6\u4e0b\u4f30\u8ba1\u8d44\u672c\u8fb9\u9645\u4ef7\u503c\u7684\u65b0\u65b9\u6cd5\u3002\u901a\u8fc7\u7ed3\u5408\u8d44\u4ea7\u4ef7\u683c\u4e0e\u57fa\u672c\u9762\u4fe1\u606f\uff0c\u8be5\u65b9\u6cd5\u63d0\u4f9b\u4e86\u8fd1\u4f3c\u65e0\u6a21\u578b\u7684\u8fb9\u9645Q\uff0c\u5e76\u5229\u7528\u7ebf\u6027\u56de\u5f52\u5bf9\uff08\u5e73\u5747\uff09\u6258\u5bbeQ\u4e2d\u7684\u6d4b\u91cf\u8bef\u5dee\u8fdb\u884c\u7b80\u5355\u4fee\u6b63\u3002\u8fb9\u9645Q\u80fd\u591f\u7ed9\u51fa\u5408\u7406\u4e14\u7a33\u5065\u7684\u8c03\u6574\u6210\u672c\u548c\u6295\u8d44\u5bf9\u57fa\u672c\u9762\u654f\u611f\u6027\u7684\u4f30\u8ba1\u3002\u8fb9\u9645Q\u4e0e\u6258\u5bbeQ\u4e4b\u95f4\u7684\u5dee\u8ddd\u6269\u5927\u4e3b\u8981\u7531\u5e02\u573a\u529b\u91cf\u548c\u65e0\u5f62\u8d44\u672c\u9a71\u52a8\u3002\u6211\u4eec\u7684\u65b0\u53d1\u73b0\u6709\u529b\u652f\u6301\u4e86\u6295\u8d44\u7684\u65b0\u53e4\u5178\u7406\u8bba\uff0c\u5e76\u6311\u6218\u4e86\u6258\u5bbeQ\u4f5c\u4e3a\u6295\u8d44\u673a\u4f1a\u4ee3\u7406\u6307\u6807\u7684\u666e\u904d\u4f7f\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1287/mnsc.2023.02150", "journal": "MS", "title": "The Engineering of Consumer Experiences Under Affect Assimilation and Quality Contrast", "authors": ["Abhishek Deshmane", "Victor Mart\u00ednez-de-Alb\u00e9niz", "Guillaume Roels"], "author_details": [{"name": "Abhishek Deshmane", "affiliations": ["Scheller College of Business, Georgia Institute of Technology, Atlanta, Georgia 30308"]}, {"name": "Victor Mart\u00ednez-de-Alb\u00e9niz", "affiliations": ["IESE Business School, University of Navarra, 08034 Barcelona, Spain"]}, {"name": "Guillaume Roels", "affiliations": ["INSEAD, Boulevard de Constance, 77305 Fontainebleau, France"]}], "abstract": "Consumer experiences are inherently dynamic. When engaging in a sequence of activities, consumers are influenced by past experiences in two ways: negatively by their objective quality, through quality contrast; and positively by their subjective appreciation of them, through affect assimilation. How should experience curators sequence activities to maximize consumer satisfaction in the presence of such intertemporal effects? We formulate an experience curator\u2019s problem as a dynamic optimization program. We show that, because of affect assimilation, the best activity may be scheduled at the beginning or in the middle of an experience, in contrast to the common peak-end rule\u2014this provides a rationale for the saying that \u201cfirst impressions matter.\u201d Under uncertainty, it may be valuable to save the best activity as a \u201cwild card\u201d to recover from bad outcomes. We calibrate our model to four distinct experiential contexts (namely, watching movies, reading books, visiting touristic attractions, and eating out) and consistently find the presence of both quality contrast and affect assimilation. Through a counterfactual study in the context of touristic tours, we show that experience curators may significantly benefit from offering different fixed sequences to different types of consumers, but they tend to gain little from dynamically adjusting them.", "date": "2026-08-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.02150", "title_zh": "\u5728\u60c5\u611f\u540c\u5316\u4e0e\u8d28\u91cf\u5bf9\u6bd4\u4e0b\u7684\u6d88\u8d39\u8005\u4f53\u9a8c\u5de5\u7a0b", "abstract_zh": "\u6d88\u8d39\u8005\u4f53\u9a8c\u672c\u8d28\u4e0a\u662f\u52a8\u6001\u7684\u3002\u5728\u8fdb\u884c\u4e00\u7cfb\u5217\u6d3b\u52a8\u65f6\uff0c\u6d88\u8d39\u8005\u4f1a\u53d7\u5230\u8fc7\u5f80\u4f53\u9a8c\u7684\u53cc\u91cd\u5f71\u54cd\uff1a\u4e00\u65b9\u9762\uff0c\u901a\u8fc7\u5b9e\u9645\u8d28\u91cf\u4ea7\u751f\u8d28\u91cf\u5bf9\u6bd4\u7684\u8d1f\u9762\u5f71\u54cd\uff1b\u53e6\u4e00\u65b9\u9762\uff0c\u901a\u8fc7\u4e3b\u89c2\u611f\u53d7\u4ea7\u751f\u60c5\u611f\u540c\u5316\u5e26\u6765\u7684\u6b63\u9762\u5f71\u54cd\u3002\u5728\u5b58\u5728\u8fd9\u79cd\u8de8\u65f6\u95f4\u6548\u5e94\u7684\u60c5\u51b5\u4e0b\uff0c\u4f53\u9a8c\u7b56\u5212\u8005\u5e94\u5982\u4f55\u5b89\u6392\u6d3b\u52a8\u4ee5\u6700\u5927\u5316\u6d88\u8d39\u8005\u6ee1\u610f\u5ea6\uff1f\u6211\u4eec\u5c06\u4f53\u9a8c\u7b56\u5212\u8005\u7684\u51b3\u7b56\u95ee\u9898\u5efa\u6a21\u4e3a\u4e00\u4e2a\u52a8\u6001\u4f18\u5316\u95ee\u9898\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u7531\u4e8e\u60c5\u611f\u540c\u5316\u7684\u4f5c\u7528\uff0c\u6700\u4f18\u6d3b\u52a8\u53ef\u80fd\u5b89\u6392\u5728\u4f53\u9a8c\u7684\u5f00\u5934\u6216\u4e2d\u95f4\uff0c\u8fd9\u4e0e\u5e38\u89c1\u7684\u5cf0\u7ec8\u6cd5\u5219\u76f8\u6096\uff0c\u4ece\u800c\u4e3a\u2018\u7b2c\u4e00\u5370\u8c61\u81f3\u5173\u91cd\u8981\u2019\u8fd9\u4e00\u8bf4\u6cd5\u63d0\u4f9b\u4e86\u7406\u8bba\u4f9d\u636e\u3002\u5728\u4e0d\u786e\u5b9a\u6027\u6761\u4ef6\u4e0b\uff0c\u4fdd\u7559\u6700\u4f73\u6d3b\u52a8\u4f5c\u4e3a\u2018\u5907\u9009\u65b9\u6848\u2019\u4ee5\u5e94\u5bf9\u4e0d\u826f\u7ed3\u679c\u53ef\u80fd\u662f\u6709\u4ef7\u503c\u7684\u3002\u6211\u4eec\u5c06\u6a21\u578b\u6821\u51c6\u5230\u56db\u4e2a\u4e0d\u540c\u7684\u4f53\u9a8c\u573a\u666f\uff08\u5373\u89c2\u770b\u7535\u5f71\u3001\u9605\u8bfb\u4e66\u7c4d\u3001\u53c2\u89c2\u65c5\u6e38\u666f\u70b9\u548c\u5916\u51fa\u5c31\u9910\uff09\uff0c\u5e76\u4e00\u81f4\u53d1\u73b0\u8d28\u91cf\u5bf9\u6bd4\u548c\u60c5\u611f\u540c\u5316\u5747\u5b58\u5728\u3002\u901a\u8fc7\u5728\u65c5\u6e38\u884c\u7a0b\u573a\u666f\u4e2d\u7684\u53cd\u4e8b\u5b9e\u7814\u7a76\uff0c\u6211\u4eec\u8868\u660e\u4f53\u9a8c\u7b56\u5212\u8005\u53ef\u4ee5\u901a\u8fc7\u4e3a\u4e0d\u540c\u7c7b\u578b\u7684\u6d88\u8d39\u8005\u63d0\u4f9b\u4e0d\u540c\u7684\u56fa\u5b9a\u5e8f\u5217\u663e\u8457\u83b7\u76ca\uff0c\u4f46\u52a8\u6001\u8c03\u6574\u8fd9\u4e9b\u5e8f\u5217\u7684\u6536\u76ca\u5219\u76f8\u5bf9\u6709\u9650\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.06147", "journal": "MS", "title": "Microfoundations of Absorptive Capacity as Revealed by Inventor Deaths", "authors": ["Benjamin Balsmeier", "Lee Fleming", "Sonja L\u00fcck"], "author_details": [{"name": "Benjamin Balsmeier", "affiliations": ["Department of Economics and Management, University of Luxembourg, 2721 Luxembourg City, Luxembourg"]}, {"name": "Lee Fleming", "affiliations": ["College of Engineering, Haas School of Business, University of California, Berkeley, California 94550"]}, {"name": "Sonja L\u00fcck", "affiliations": ["Faculty of Business Administration and Economics, Department of Economics, Paderborn University, 33098 Paderborn, Germany"]}], "abstract": "We return to the theoretical foundations of absorptive capacity and test the idea that personal experience in a field makes it easier for a firm\u2019s inventors to recognize and build upon knowledge in that field from other local firms. We propose a new empirical model of localized knowledge diffusion, which (1) measures a firm\u2019s absorptive capacity by its inventors\u2019 prior experience in a field, (2) uses a death instrument to exogenously vary the availability of knowledge of the same collaborative patent in different regions, and (3) estimates the difference in citation likelihood from all subsequent inventors across both regions as a function of a potentially citing inventor\u2019s prior experience in the field. Consistent with the original theory of absorptive capacity, firms whose inventors have prior experience in a field are more likely to use locally available interpersonal knowledge from other firms; furthermore, this effect declines monotonically with distance. Although the effects strengthen for more recent experience and multidisciplinary knowledge, the greatest benefits accrue to firms in the interaction\u2014those whose inventors have more recent experience and that seek to absorb multidisciplinary knowledge. Interpersonal absorptive capacity within firms does not appear to localize.", "date": "2026-08-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06147", "title_zh": "\u901a\u8fc7\u53d1\u660e\u8005\u6b7b\u4ea1\u63ed\u793a\u5438\u6536\u80fd\u529b\u7684\u5fae\u89c2\u57fa\u7840", "abstract_zh": "\u6211\u4eec\u56de\u5230\u5438\u6536\u80fd\u529b\u7684\u7406\u8bba\u57fa\u7840\uff0c\u5e76\u68c0\u9a8c\u4e2a\u4eba\u5728\u67d0\u4e00\u9886\u57df\u4e2d\u7684\u7ecf\u9a8c\u662f\u5426\u4f7f\u4f01\u4e1a\u53d1\u660e\u8005\u66f4\u5bb9\u6613\u8bc6\u522b\u5e76\u5229\u7528\u540c\u5730\u533a\u5176\u4ed6\u4f01\u4e1a\u4e2d\u7684\u77e5\u8bc6\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u65b0\u7684\u672c\u5730\u5316\u77e5\u8bc6\u6269\u6563\u7ecf\u9a8c\u6a21\u578b\uff0c\u8be5\u6a21\u578b\uff081\uff09\u901a\u8fc7\u53d1\u660e\u8005\u5728\u67d0\u4e00\u9886\u57df\u7684\u5148\u524d\u7ecf\u9a8c\u6765\u8861\u91cf\u4f01\u4e1a\u7684\u5438\u6536\u80fd\u529b\uff1b\uff082\uff09\u4f7f\u7528\u6b7b\u4ea1\u5de5\u5177\uff0c\u4ee5\u5916\u751f\u65b9\u5f0f\u6539\u53d8\u540c\u4e00\u534f\u4f5c\u4e13\u5229\u5728\u4e0d\u540c\u5730\u533a\u77e5\u8bc6\u53ef\u83b7\u5f97\u6027\u7684\u5dee\u5f02\uff1b\uff083\uff09\u5c06\u540e\u7eed\u53d1\u660e\u8005\u5bf9\u6240\u6709\u4e13\u5229\u7684\u5f15\u7528\u53ef\u80fd\u6027\u5dee\u5f02\uff0c\u4f5c\u4e3a\u6f5c\u5728\u5f15\u7528\u53d1\u660e\u8005\u5728\u8be5\u9886\u57df\u5148\u524d\u7ecf\u9a8c\u7684\u51fd\u6570\u8fdb\u884c\u4f30\u8ba1\u3002\u7ed3\u679c\u4e0e\u5438\u6536\u80fd\u529b\u7684\u539f\u59cb\u7406\u8bba\u4e00\u81f4\uff1a\u62e5\u6709\u9886\u57df\u5185\u5148\u524d\u7ecf\u9a8c\u7684\u4f01\u4e1a\u7684\u53d1\u660e\u8005\u66f4\u53ef\u80fd\u5229\u7528\u672c\u5730\u5176\u4ed6\u4f01\u4e1a\u95f4\u7684\u4eba\u9645\u77e5\u8bc6\uff1b\u4e14\u8fd9\u79cd\u6548\u5e94\u968f\u8ddd\u79bb\u589e\u52a0\u800c\u5355\u8c03\u9012\u51cf\u3002\u5c3d\u7ba1\u8fd1\u671f\u7ecf\u9a8c\u4ee5\u53ca\u8de8\u5b66\u79d1\u77e5\u8bc6\u7684\u6548\u5e94\u6709\u6240\u589e\u5f3a\uff0c\u4f46\u6700\u5927\u6536\u76ca\u6765\u81ea\u90a3\u4e9b\u62e5\u6709\u8fd1\u671f\u7ecf\u9a8c\u4e14\u5bfb\u6c42\u5438\u6536\u8de8\u5b66\u79d1\u77e5\u8bc6\u7684\u4e92\u52a8\u4f01\u4e1a\u3002\u4f01\u4e1a\u5185\u90e8\u7684\u4eba\u9645\u5438\u6536\u80fd\u529b\u4f3c\u4e4e\u5e76\u672a\u8868\u73b0\u51fa\u672c\u5730\u5316\u7279\u5f81\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.07450", "journal": "MS", "title": "Beyond the Black Box: Unraveling the Role of Explainability in Human-Artificial Intelligence Collaboration", "authors": ["Tamer Boyac\u0131", "Caner Canyakmaz", "Francis de V\u00e9ricourt"], "author_details": [{"name": "Tamer Boyac\u0131", "affiliations": ["Management Science, European School of Management and Technology Berlin, 10178 Berlin, Germany"]}, {"name": "Caner Canyakmaz", "affiliations": ["Information, Operations and Management Sciences, TBS Business School, 31000 Toulouse, France"]}, {"name": "Francis de V\u00e9ricourt", "affiliations": ["Management Science, European School of Management and Technology Berlin, 10178 Berlin, Germany"]}], "abstract": "Explainable artificial intelligence (AI) models have been proposed to mitigate overreliance and underreliance on AI, which reduce the effectiveness of human-AI collaborative tools. Yet, empirical evidence is mixed, and the impact of explainable AI on the cognitive effort and fatigue of a decision maker (DM) is often overlooked. This paper offers a theoretical perspective on these issues. We develop an analytical model that incorporates the defining features of human and machine intelligence, capturing the limited but flexible nature of human cognition with imperfect machine recommendations. Crucially, we represent how AI-based explanations influence the DM\u2019s belief in the algorithm\u2019s predictive quality. Our results indicate that explainable AI has varying effects depending on the level of explainability provided. Although low explainability levels have no impact on decision accuracy and reliance behavior, they lessen the cognitive burden on the DM. In contrast, higher explainability levels enhance accuracy by improving overreliance but at the expense of increased underreliance. Further, the relative impact of explainability is higher when the DM is more cognitively constrained, when the decision task is sufficiently complex, or when the stakes are lower. Importantly, higher explainability levels can escalate the DM\u2019s cognitive burden (and hence, overall processing time and fatigue) precisely when explanations are most needed (i.e., when the DM is pressed for time to complete a complex task and doubts the machine\u2019s quality). Our study clarifies how explainability affects decision outcomes and cognitive effort, informing the design of effective human-AI systems across decision environments.", "date": "2026-08-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07450", "title_zh": "\u8d85\u8d8a\u9ed1\u7bb1\uff1a\u89e3\u6790\u53ef\u89e3\u91ca\u6027\u5728\u4eba\u673a\u534f\u4f5c\u4e2d\u7684\u4f5c\u7528", "abstract_zh": "\u53ef\u89e3\u91ca\u7684\u4eba\u5de5\u667a\u80fd\uff08AI\uff09\u6a21\u578b\u88ab\u63d0\u51fa\u4ee5\u7f13\u89e3\u5bf9AI\u7684\u8fc7\u5ea6\u4f9d\u8d56\u548c\u4e0d\u8db3\u4f9d\u8d56\uff0c\u4ece\u800c\u63d0\u5347\u4eba\u673a\u534f\u4f5c\u5de5\u5177\u7684\u6709\u6548\u6027\u3002\u7136\u800c\uff0c\u5b9e\u8bc1\u8bc1\u636e\u5b58\u5728\u5206\u6b67\uff0c\u4e14\u53ef\u89e3\u91caAI\u5bf9\u51b3\u7b56\u8005\uff08DM\uff09\u8ba4\u77e5\u8d1f\u62c5\u548c\u75b2\u52b3\u7684\u5f71\u54cd\u5f80\u5f80\u88ab\u5ffd\u89c6\u3002\u672c\u6587\u4ece\u7406\u8bba\u89d2\u5ea6\u63a2\u8ba8\u4e86\u8fd9\u4e9b\u95ee\u9898\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5206\u6790\u6a21\u578b\uff0c\u878d\u5408\u4e86\u4eba\u7c7b\u4e0e\u673a\u5668\u667a\u80fd\u7684\u7279\u5f81\uff0c\u4ee5\u6355\u6349\u4eba\u7c7b\u8ba4\u77e5\u7684\u6709\u9650\u4f46\u7075\u6d3b\u7279\u6027\uff0c\u5e76\u7ed3\u5408\u673a\u5668\u63a8\u8350\u7684\u4e0d\u5b8c\u7f8e\u6027\u3002\u5173\u952e\u5728\u4e8e\uff0c\u6211\u4eec\u523b\u753b\u4e86\u57fa\u4e8eAI\u7684\u89e3\u91ca\u5982\u4f55\u5f71\u54cd\u51b3\u7b56\u8005\u5bf9\u7b97\u6cd5\u9884\u6d4b\u8d28\u91cf\u7684\u4fe1\u4efb\u7a0b\u5ea6\u3002\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u53ef\u89e3\u91caAI\u7684\u6548\u679c\u968f\u63d0\u4f9b\u7684\u53ef\u89e3\u91ca\u6027\u6c34\u5e73\u800c\u53d8\u5316\u3002\u5c3d\u7ba1\u4f4e\u6c34\u5e73\u7684\u53ef\u89e3\u91ca\u6027\u5bf9\u51b3\u7b56\u51c6\u786e\u6027\u53ca\u4f9d\u8d56\u884c\u4e3a\u65e0\u5f71\u54cd\uff0c\u5374\u80fd\u51cf\u8f7b\u51b3\u7b56\u8005\u7684\u8ba4\u77e5\u8d1f\u62c5\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u9ad8\u6c34\u5e73\u7684\u53ef\u89e3\u91ca\u6027\u901a\u8fc7\u6539\u5584\u8fc7\u5ea6\u4f9d\u8d56\u800c\u63d0\u5347\u51c6\u786e\u6027\uff0c\u4f46\u4ee5\u589e\u52a0\u4e0d\u8db3\u4f9d\u8d56\u4e3a\u4ee3\u4ef7\u3002\u6b64\u5916\uff0c\u5f53\u51b3\u7b56\u8005\u8ba4\u77e5\u80fd\u529b\u53d7\u9650\u3001\u51b3\u7b56\u4efb\u52a1\u8db3\u591f\u590d\u6742\u6216\u98ce\u9669\u8f83\u4f4e\u65f6\uff0c\u53ef\u89e3\u91ca\u6027\u7684\u76f8\u5bf9\u5f71\u54cd\u66f4\u4e3a\u663e\u8457\u3002\u91cd\u8981\u7684\u662f\uff0c\u5f53\u89e3\u91ca\u6700\u4e3a\u9700\u8981\u65f6\uff08\u5373\u51b3\u7b56\u8005\u65f6\u95f4\u7d27\u8feb\u4e14\u5bf9\u673a\u5668\u8d28\u91cf\u5b58\u7591\u65f6\uff09\uff0c\u9ad8\u6c34\u5e73\u7684\u53ef\u89e3\u91ca\u6027\u53cd\u800c\u4f1a\u52a0\u5267\u51b3\u7b56\u8005\u7684\u8ba4\u77e5\u8d1f\u62c5\uff08\u8fdb\u800c\u5bfc\u81f4\u6574\u4f53\u5904\u7406\u65f6\u95f4\u548c\u75b2\u52b3\u589e\u52a0\uff09\u3002\u672c\u7814\u7a76\u9610\u660e\u4e86\u53ef\u89e3\u91ca\u6027\u5982\u4f55\u5f71\u54cd\u51b3\u7b56\u7ed3\u679c\u548c\u8ba4\u77e5\u52aa\u529b\uff0c\u4e3a\u4e0d\u540c\u51b3\u7b56\u73af\u5883\u4e0b\u7684\u9ad8\u6548\u4eba\u673a\u7cfb\u7edf\u8bbe\u8ba1\u63d0\u4f9b\u4e86\u6307\u5bfc\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1093/rfs/hhag077", "journal": "RFS", "title": "Underrepresentation of Women CEOs", "authors": ["Li He", "Toni M Whited"], "author_details": [{"name": "Li He", "affiliations": ["EDHEC , France"]}, {"name": "Toni M Whited", "affiliations": ["University of Michigan and NBER ,"]}], "abstract": "Abstract Why do so few women become CEOs? To understand this glass ceiling, we estimate a dynamic model of the CEO gender decision, which contains perceived gender productivity differences, search costs reflecting limited female labor supply, and employer disutility from discrimination. The key factor is the shortage of suitable female candidates, as boards prefer hiring women, and productivity differences between genders are minimal. We find no evidence of a glass cliff in which women become CEOs just as firms are failing. While better governance is associated with women becoming CEOs, the importance of limited female labor supply is unrelated to governance.", "date": "2026-08-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag077", "title_zh": "\u5973\u6027\u9996\u5e2d\u6267\u884c\u5b98\u7684\u4ee3\u8868\u6027\u4e0d\u8db3", "abstract_zh": "\u6458\u8981 \u4e3a\u4ec0\u4e48\u5973\u6027\u6210\u4e3a\u9996\u5e2d\u6267\u884c\u5b98\u7684\u4eba\u6570\u5982\u6b64\u4e4b\u5c11\uff1f\u4e3a\u4e86\u7406\u89e3\u8fd9\u4e00\u73bb\u7483\u5929\u82b1\u677f\u73b0\u8c61\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u52a8\u6001\u7684\u9996\u5e2d\u6267\u884c\u5b98\u6027\u522b\u51b3\u7b56\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u5305\u542b\u4e86\u5bf9\u6027\u522b\u751f\u4ea7\u7387\u5dee\u5f02\u7684\u611f\u77e5\u3001\u53cd\u6620\u5973\u6027\u52b3\u52a8\u529b\u4f9b\u5e94\u6709\u9650\u7684\u641c\u5bfb\u6210\u672c\uff0c\u4ee5\u53ca\u96c7\u4e3b\u56e0\u6b67\u89c6\u800c\u4ea7\u751f\u7684\u4e0d\u9002\u611f\u3002\u5173\u952e\u56e0\u7d20\u662f\u5408\u683c\u5973\u6027\u5019\u9009\u4eba\u7684\u77ed\u7f3a\uff0c\u8463\u4e8b\u4f1a\u66f4\u503e\u5411\u4e8e\u62db\u8058\u5973\u6027\uff0c\u800c\u6027\u522b\u4e4b\u95f4\u7684\u751f\u4ea7\u7387\u5dee\u5f02\u6781\u5c0f\u3002\u6211\u4eec\u672a\u53d1\u73b0\u6240\u8c13\u2018\u73bb\u7483\u60ac\u5d16\u2019\u73b0\u8c61\uff0c\u5373\u5973\u6027\u4ec5\u5728\u516c\u53f8\u6fd2\u4e34\u5931\u8d25\u65f6\u624d\u88ab\u4efb\u547d\u4e3aCEO\u3002\u867d\u7136\u66f4\u597d\u7684\u516c\u53f8\u6cbb\u7406\u4e0e\u5973\u6027\u62c5\u4efbCEO\u76f8\u5173\uff0c\u4f46\u5973\u6027\u52b3\u52a8\u529b\u4f9b\u5e94\u6709\u9650\u7684\u91cd\u8981\u6027\u4e0e\u516c\u53f8\u6cbb\u7406\u65e0\u5173\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2025.00782", "journal": "MS", "title": "Trade-Offs Between Ranking Objectives: Descriptive Evidence and Structural Estimation", "authors": ["Rafael P. Greminger"], "author_details": [{"name": "Rafael P. Greminger", "affiliations": ["UCL School of Management, University College London, London E14 5AA, United Kingdom"]}], "abstract": "When designing product rankings, online retailers and platforms choose which outcome to maximize: revenues from commissions or markups, the number of transactions, or consumer welfare. These objectives need not align, creating potential trade-offs. This paper studies how rankings differ between objectives and quantifies the resulting trade-offs. I provide descriptive evidence showing that lower-priced and high-utility alternatives gain more demand when ranked higher, suggesting that ranking them higher increases transactions and consumer welfare but may decrease revenues. To quantify these trade-offs, I develop and estimate a structural demand model in which consumers search and discover products, and construct rankings for each objective. The results show that these counterfactual rankings all increase consumer welfare, transactions, and platform revenues relative to a neutral benchmark and the status quo and that trade-offs between these rankings are limited.", "date": "2026-08-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.00782", "title_zh": "\u6392\u540d\u76ee\u6807\u4e4b\u95f4\u7684\u6743\u8861\uff1a\u63cf\u8ff0\u6027\u8bc1\u636e\u4e0e\u7ed3\u6784\u4f30\u8ba1", "abstract_zh": "\u5728\u8bbe\u8ba1\u4ea7\u54c1\u6392\u540d\u65f6\uff0c\u7ebf\u4e0a\u96f6\u552e\u5546\u548c\u5e73\u53f0\u9700\u8981\u51b3\u5b9a\u6700\u5927\u5316\u54ea\u79cd\u7ed3\u679c\uff1a\u4f63\u91d1\u6216\u6ea2\u4ef7\u5e26\u6765\u7684\u6536\u5165\u3001\u4ea4\u6613\u6570\u91cf\uff0c\u8fd8\u662f\u6d88\u8d39\u8005\u798f\u5229\u3002\u8fd9\u4e9b\u76ee\u6807\u672a\u5fc5\u4e00\u81f4\uff0c\u4ece\u800c\u4ea7\u751f\u6f5c\u5728\u7684\u6743\u8861\u3002\u672c\u6587\u7814\u7a76\u4e86\u4e0d\u540c\u76ee\u6807\u4e0b\u6392\u540d\u7684\u5dee\u5f02\uff0c\u5e76\u91cf\u5316\u4e86\u7531\u6b64\u4ea7\u751f\u7684\u6743\u8861\u3002\u6211\u63d0\u4f9b\u4e86\u63cf\u8ff0\u6027\u8bc1\u636e\uff0c\u8868\u660e\u4f4e\u4ef7\u4e14\u9ad8\u6548\u7684\u66ff\u4ee3\u54c1\u5728\u6392\u540d\u66f4\u9ad8\u65f6\u83b7\u5f97\u66f4\u591a\u7684\u9700\u6c42\uff0c\u8fd9\u8868\u660e\u5c06\u5b83\u4eec\u6392\u5728\u66f4\u9ad8\u4f4d\u7f6e\u53ef\u4ee5\u589e\u52a0\u4ea4\u6613\u6570\u91cf\u548c\u6d88\u8d39\u8005\u798f\u5229\uff0c\u4f46\u53ef\u80fd\u964d\u4f4e\u6536\u5165\u3002\u4e3a\u4e86\u91cf\u5316\u8fd9\u4e9b\u6743\u8861\uff0c\u6211\u6784\u5efa\u5e76\u4f30\u8ba1\u4e86\u4e00\u4e2a\u7ed3\u6784\u9700\u6c42\u6a21\u578b\uff0c\u5176\u4e2d\u6d88\u8d39\u8005\u8fdb\u884c\u4ea7\u54c1\u641c\u7d22\u5e76\u53d1\u73b0\u4ea7\u54c1\uff0c\u540c\u65f6\u4e3a\u4e0d\u540c\u76ee\u6807\u6784\u5efa\u76f8\u5e94\u7684\u6392\u540d\u3002\u7ed3\u679c\u8868\u660e\uff0c\u6240\u6709\u8fd9\u4e9b\u53cd\u4e8b\u5b9e\u6392\u540d\u76f8\u5bf9\u4e8e\u4e2d\u7acb\u57fa\u51c6\u548c\u73b0\u72b6\u5747\u63d0\u9ad8\u4e86\u6d88\u8d39\u8005\u798f\u5229\u3001\u4ea4\u6613\u6570\u91cf\u548c\u5e73\u53f0\u6536\u5165\uff0c\u4e14\u8fd9\u4e9b\u6392\u540d\u4e4b\u95f4\u7684\u6743\u8861\u6709\u9650\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.02419", "journal": "MS", "title": "Assortment Optimization for the Multinomial Logit Model with Repeated Customer Interactions", "authors": ["Chenhao Wang", "Ningyuan Chen", "Pin Gao", "Yao Wang", "Su Zhao"], "author_details": [{"name": "Chenhao Wang", "affiliations": ["School of Economics and Management, Tongji University, Shanghai 200092, China; and Laboratory of High Quality Urban Development and Strategic Decision, Tongji University, Shanghai 200092, China"]}, {"name": "Ningyuan Chen", "affiliations": ["Rotman School of Management, University of Toronto, Toronto, Ontario M5S 3E6, Canada"]}, {"name": "Pin Gao", "affiliations": ["School of Data Science, School of Management and Economics, The Chinese University of Hong Kong, Shenzhen, Guangdong 518172, China"]}, {"name": "Yao Wang", "affiliations": ["School of Management, Xi\u2019an Jiaotong University, Xi\u2019an, Shaanxi 710049, China"]}, {"name": "Su Zhao", "affiliations": ["Meituan, Beijing 100102, China"]}], "abstract": "This paper presents the multinomial logit model with repeated customer interactions. In each period, the same customer selects a product from the recommended assortment or opts out. From the seller\u2019s perspective, the choice probability in the current period is updated based on the purchase history of the customer. We derive this conditional choice probability and study the adaptive assortment recommendation strategy. Although the problem is generally intractable, we discover the structures of the optimal assortment when the customer interacts with the seller for two periods and the available products to recommend are identical in the two periods. For a general number of periods, we find that the optimal fixed assortments that are not adapted to the purchase history can achieve 50% of the optimal expected revenue, and the approximation ratio increases to 68.47% when the available products across periods are disjoint. Using real-world data sets, we demonstrate that the model with repeated customer interactions can better predict the purchase behavior and generate higher revenues.", "date": "2026-08-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.02419", "title_zh": "\u5177\u6709\u91cd\u590d\u5ba2\u6237\u4e92\u52a8\u7684\u591a\u9879Logit\u6a21\u578b\u7684\u7ec4\u5408\u4f18\u5316", "abstract_zh": "\u672c\u6587\u63d0\u51fa\u4e86\u5177\u6709\u91cd\u590d\u5ba2\u6237\u4e92\u52a8\u7684\u591a\u9879Logit\u6a21\u578b\u3002\u5728\u6bcf\u4e2a\u65f6\u671f\uff0c\u540c\u4e00\u5ba2\u6237\u4ece\u63a8\u8350\u7684\u7ec4\u5408\u4e2d\u9009\u62e9\u4e00\u4e2a\u4ea7\u54c1\u6216\u9009\u62e9\u653e\u5f03\u3002\u4ece\u5356\u5bb6\u7684\u89d2\u5ea6\u6765\u770b\uff0c\u5f53\u524d\u65f6\u671f\u7684\u9009\u54c1\u6982\u7387\u57fa\u4e8e\u5ba2\u6237\u7684\u8d2d\u4e70\u5386\u53f2\u8fdb\u884c\u66f4\u65b0\u3002\u6211\u4eec\u63a8\u5bfc\u4e86\u8fd9\u4e00\u6761\u4ef6\u4e0b\u7684\u9009\u54c1\u6982\u7387\uff0c\u5e76\u7814\u7a76\u4e86\u81ea\u9002\u5e94\u63a8\u8350\u7ec4\u5408\u7b56\u7565\u3002\u5c3d\u7ba1\u8be5\u95ee\u9898\u901a\u5e38\u4e0d\u53ef\u89e3\uff0c\u4f46\u6211\u4eec\u53d1\u73b0\u5f53\u5ba2\u6237\u4e0e\u5356\u5bb6\u4e92\u52a8\u4ec5\u4e24\u4e2a\u65f6\u671f\u4e14\u4e24\u4e2a\u65f6\u671f\u53ef\u63a8\u8350\u7684\u4ea7\u54c1\u96c6\u5408\u76f8\u540c\u65f6\uff0c\u6700\u4f18\u7ec4\u5408\u7684\u7ed3\u6784\u3002\u5bf9\u4e8e\u4e00\u822c\u65f6\u671f\u6570\uff0c\u6211\u4eec\u53d1\u73b0\u4e0d\u4f9d\u8d56\u8d2d\u4e70\u5386\u53f2\u7684\u56fa\u5b9a\u7ec4\u5408\u53ef\u4ee5\u8fbe\u5230\u6700\u4f18\u9884\u671f\u6536\u5165\u768450%\uff0c\u5f53\u5404\u65f6\u671f\u53ef\u63a8\u8350\u4ea7\u54c1\u4e92\u4e0d\u76f8\u4ea4\u65f6\uff0c\u8fd1\u4f3c\u6bd4\u7387\u63d0\u5347\u81f368.47%\u3002\u5229\u7528\u771f\u5b9e\u4e16\u754c\u6570\u636e\u96c6\uff0c\u6211\u4eec\u8bc1\u660e\u4e86\u5177\u6709\u91cd\u590d\u5ba2\u6237\u4e92\u52a8\u7684\u6a21\u578b\u80fd\u591f\u66f4\u51c6\u786e\u5730\u9884\u6d4b\u8d2d\u4e70\u884c\u4e3a\u5e76\u4ea7\u751f\u66f4\u9ad8\u7684\u6536\u5165\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.08526", "journal": "MS", "title": "How Important Is Internal Information Asymmetry for Firm-Level Productivity?", "authors": ["Vishal P. Baloria", "Trent J. Krupa", "David P. Weber"], "author_details": [{"name": "Vishal P. Baloria", "affiliations": ["University of Connecticut, Storrs, Connecticut 06269"]}, {"name": "Trent J. Krupa", "affiliations": ["The Pennsylvania State University, University Park, Pennsylvania 16802"]}, {"name": "David P. Weber", "affiliations": ["University of Connecticut, Storrs, Connecticut 06269"]}], "abstract": "Theoretical research suggests internal information asymmetry (IIA) between top managers and divisional managers can reduce productivity by distorting internal resource allocation. The net effect, however, is unclear because IIA also reflects valuable private information within divisions, and empirical evidence is limited because of the unobservability of managers\u2019 private information sets. Using a measure of IIA that exploits differences in returns to insider trading by top and divisional managers, we find that higher IIA is associated with lower total factor productivity. A one standard deviation increase in IIA corresponds to a 2.6% decrease in productivity relative to industry peers. This effect is comparable in magnitude to other important internal informational frictions, such as internal control weaknesses, and is distinct from internal information quality. Cross-sectional analyses indicate that the negative association is stronger when curative measures are limited and when agency conflicts between top managers and shareholders are greater. Mechanism tests indicate that IIA reduces internal capital market efficiency and increases underinvestment. Finally, using brokerage mergers and closures as a plausibly exogenous shock, we find that increases in IIA lead to declines in productivity. Overall, we provide empirical evidence that IIA is an economically important determinant of firm-level productivity.", "date": "2026-08-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08526", "title_zh": "\u5185\u90e8\u4fe1\u606f\u4e0d\u5bf9\u79f0\u5bf9\u4f01\u4e1a\u5c42\u9762\u751f\u4ea7\u7387\u6709\u591a\u91cd\u8981\uff1f", "abstract_zh": "\u7406\u8bba\u7814\u7a76\u8ba4\u4e3a\uff0c\u9ad8\u5c42\u7ba1\u7406\u8005\u4e0e\u4e8b\u4e1a\u90e8\u7ba1\u7406\u8005\u4e4b\u95f4\u7684\u5185\u90e8\u4fe1\u606f\u4e0d\u5bf9\u79f0\uff08IIA\uff09\u4f1a\u901a\u8fc7\u626d\u66f2\u5185\u90e8\u8d44\u6e90\u5206\u914d\u6765\u964d\u4f4e\u751f\u4ea7\u7387\u3002\u7136\u800c\uff0c\u5176\u51c0\u6548\u5e94\u5c1a\u4e0d\u660e\u786e\uff0c\u56e0\u4e3aIIA\u4e5f\u53cd\u6620\u4e86\u5404\u4e8b\u4e1a\u90e8\u5185\u90e8\u7684\u6709\u4ef7\u503c\u79c1\u6709\u4fe1\u606f\uff0c\u4e14\u7531\u4e8e\u7ba1\u7406\u8005\u79c1\u6709\u4fe1\u606f\u96c6\u7684\u4e0d\u53ef\u89c2\u6d4b\u6027\uff0c\u5b9e\u8bc1\u8bc1\u636e\u8f83\u4e3a\u6709\u9650\u3002\u6211\u4eec\u91c7\u7528\u4e00\u79cd\u57fa\u4e8e\u9ad8\u5c42\u7ba1\u7406\u8005\u4e0e\u4e8b\u4e1a\u90e8\u7ba1\u7406\u8005\u5185\u5e55\u4ea4\u6613\u56de\u62a5\u5dee\u5f02\u7684IIA\u8861\u91cf\u65b9\u6cd5\uff0c\u53d1\u73b0IIA\u6c34\u5e73\u8d8a\u9ad8\uff0c\u603b\u8981\u7d20\u751f\u4ea7\u7387\u8d8a\u4f4e\u3002IIA\u6bcf\u589e\u52a0\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u76f8\u5bf9\u4e8e\u884c\u4e1a\u540c\u884c\uff0c\u751f\u4ea7\u7387\u4e0b\u964d2.6%\u3002\u8fd9\u4e00\u6548\u5e94\u7684\u89c4\u6a21\u4e0e\u5185\u90e8\u4fe1\u606f\u6469\u64e6\u7684\u5176\u4ed6\u91cd\u8981\u56e0\u7d20\uff08\u5982\u5185\u90e8\u63a7\u5236\u7f3a\u9677\uff09\u76f8\u5f53\uff0c\u5e76\u4e14\u4e0e\u5185\u90e8\u4fe1\u606f\u8d28\u91cf\u4e0d\u540c\u3002\u6a2a\u622a\u9762\u5206\u6790\u8868\u660e\uff0c\u5f53\u7ea0\u6b63\u63aa\u65bd\u6709\u9650\u4e14\u9ad8\u5c42\u7ba1\u7406\u8005\u4e0e\u80a1\u4e1c\u4e4b\u95f4\u7684\u4ee3\u7406\u51b2\u7a81\u66f4\u5f3a\u70c8\u65f6\uff0c\u8d1f\u5411\u5173\u8054\u66f4\u4e3a\u663e\u8457\u3002\u673a\u5236\u68c0\u9a8c\u663e\u793a\uff0cIIA\u4f1a\u964d\u4f4e\u5185\u90e8\u8d44\u672c\u5e02\u573a\u6548\u7387\u5e76\u52a0\u5267\u6295\u8d44\u4e0d\u8db3\u3002\u6700\u540e\uff0c\u5229\u7528\u5238\u5546\u5e76\u8d2d\u4e0e\u5173\u95ed\u4f5c\u4e3a\u53ef\u80fd\u7684\u5916\u751f\u51b2\u51fb\uff0c\u6211\u4eec\u53d1\u73b0IIA\u7684\u4e0a\u5347\u4f1a\u5bfc\u81f4\u751f\u4ea7\u7387\u4e0b\u964d\u3002\u603b\u4f53\u800c\u8a00\uff0c\u672c\u6587\u63d0\u4f9b\u4e86IIA\u662f\u4f01\u4e1a\u5c42\u9762\u751f\u4ea7\u7387\u7684\u91cd\u8981\u51b3\u5b9a\u56e0\u7d20\u7684\u5b9e\u8bc1\u8bc1\u636e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1287/mnsc.2025.03520", "journal": "MS", "title": "E-ledgers Carbon Accounting", "authors": ["Robert S. Kaplan", "Karthik Ramanna"], "author_details": [{"name": "Robert S. Kaplan", "affiliations": ["Harvard Business School, Boston, Massachusetts 02163"]}, {"name": "Karthik Ramanna", "affiliations": ["Blavatnik School of Government, University of Oxford, Oxford OX2 6GG, United Kingdom"]}], "abstract": "In prior publications, we introduced a global system of interconnected E-ledgers that produces\u2014in as close to real time as practicable\u2014accurate, comparable, and verifiable accounts of the cradle-to-gate (net) greenhouse gas emissions in any product or service that transacts in the economy. In this paper, we delve more deeply into the accounting infrastructure required for the E-ledgers system, including the specific journal entries for recording E-liabilities and E-assets. We explain how the E-ledgers of different entities in the economy articulate with each other and how they connect with jurisdictional E-ledgers that record emissions from end consumers. These entity and jurisdictional E-ledgers can be aggregated into a geological master ledger that tracks anthropogenic GHG emissions and removals, as debits and credits, to a geological carbon equity account. We also provide summary insights from computational technology and pilot studies to guide rapid and cost-effective E-ledgers deployment at scale.", "date": "2026-08-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.03520", "title_zh": "E\u8d26\u672c\u78b3\u4f1a\u8ba1", "abstract_zh": "\u5728\u5148\u524d\u7684\u51fa\u7248\u7269\u4e2d\uff0c\u6211\u4eec\u4ecb\u7ecd\u4e86\u4e00\u5957\u5168\u7403\u4e92\u8054\u7684E\u8d26\u672c\u7cfb\u7edf\uff0c\u8be5\u7cfb\u7edf\u80fd\u591f\u4ee5\u5c3d\u53ef\u80fd\u63a5\u8fd1\u5b9e\u65f6\u7684\u65b9\u5f0f\uff0c\u751f\u6210\u51c6\u786e\u3001\u53ef\u6bd4\u4e14\u53ef\u9a8c\u8bc1\u7684\u4efb\u4f55\u4ea7\u54c1\u6216\u670d\u52a1\u5728\u6574\u4e2a\u7ecf\u6d4e\u4ea4\u6613\u8fc7\u7a0b\u4e2d\u7684\u5168\u751f\u547d\u5468\u671f\uff08\u51c0\uff09\u6e29\u5ba4\u6c14\u4f53\u6392\u653e\u8d26\u76ee\u3002\u5728\u672c\u6587\u4e2d\uff0c\u6211\u4eec\u66f4\u6df1\u5165\u5730\u63a2\u8ba8\u4e86E\u8d26\u672c\u7cfb\u7edf\u6240\u9700\u7684\u4f1a\u8ba1\u57fa\u7840\u8bbe\u65bd\uff0c\u5305\u62ec\u8bb0\u5f55E\u8d1f\u503a\u548cE\u8d44\u4ea7\u7684\u5177\u4f53\u4f1a\u8ba1\u5206\u5f55\u3002\u6211\u4eec\u89e3\u91ca\u4e86\u7ecf\u6d4e\u4e0d\u540c\u5b9e\u4f53\u7684E\u8d26\u672c\u5982\u4f55\u76f8\u4e92\u5173\u8054\uff0c\u4ee5\u53ca\u5b83\u4eec\u5982\u4f55\u4e0e\u8bb0\u5f55\u7ec8\u7aef\u6d88\u8d39\u8005\u6392\u653e\u7684\u53f8\u6cd5\u7ba1\u8f96\u533aE\u8d26\u672c\u76f8\u8fde\u63a5\u3002\u8fd9\u4e9b\u5b9e\u4f53\u548c\u53f8\u6cd5\u7ba1\u8f96\u533a\u7684E\u8d26\u672c\u53ef\u4ee5\u6c47\u603b\u4e3a\u4e00\u4e2a\u5730\u8d28\u4e3b\u8d26\u672c\uff0c\u8be5\u8d26\u672c\u4ee5\u501f\u65b9\u548c\u8d37\u65b9\u8bb0\u5f55\u4eba\u4e3a\u6e29\u5ba4\u6c14\u4f53\u6392\u653e\u548c\u79fb\u9664\u60c5\u51b5\uff0c\u5e76\u8ba1\u5165\u5730\u8d28\u78b3\u6743\u76ca\u8d26\u6237\u3002\u6211\u4eec\u8fd8\u63d0\u4f9b\u4e86\u6765\u81ea\u8ba1\u7b97\u6280\u672f\u53ca\u8bd5\u70b9\u7814\u7a76\u7684\u603b\u7ed3\u6027\u89c1\u89e3\uff0c\u4ee5\u6307\u5bfc\u5927\u89c4\u6a21\u3001\u5feb\u901f\u4e14\u4f4e\u6210\u672c\u5730\u90e8\u7f72E\u8d26\u672c\u7cfb\u7edf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.00913", "journal": "MS", "title": "Why Context Influences Preferences Elicited with Willingness to Pay Less Than Preferences Elicited with Choice", "authors": ["Chang-Yuan Lee", "Nina Mazar", "Carey K. Morewedge"], "author_details": [{"name": "Chang-Yuan Lee", "affiliations": ["Rotman School of Management, University of Toronto, Toronto, Ontario M5S 3E6, Canada"]}, {"name": "Nina Mazar", "affiliations": ["Questrom School of Business, Boston University, Boston, Massachusetts 02215"]}, {"name": "Carey K. Morewedge", "affiliations": ["Questrom School of Business, Boston University, Boston, Massachusetts 02215"]}], "abstract": "Normative theories assume that people have stable preferences across logically equivalent decision contexts. Preference reversals, cases where preferred options vary across decision contexts, violate this assumption and suggest that preferences are constructed during the decision-making process. We contribute to this literature by identifying a boundary condition for these context effects. We theorize that monetary preference elicitations, such as willingness to pay (WTP) and willingness to accept (WTA), evoke comparisons to external out-of-context standards, such as the market price of similar goods. These out-of-context comparisons should weaken the influence of the local context. Our theory predicts that context effects will be weaker for (1) monetary versus nonmonetary preference elicitations (e.g., WTP/WTA versus choice) and when (2) options differ on attributes highly correlated with market prices of similar goods and services. Across 22 studies, we find support for these predictions using three canonical decision context effects (intertemporal tradeoffs, framing effects, and attraction effects), incentive-compatible and stated preferences, and different response formats (binary, continuous, and mixed). Preferences for a wide range of goods and services\u2014including baked goods, apartments, and lotteries\u2014exhibit these patterns. Our theory explains substantial variance in context effects and offers testable predictions for when context effects will arise in research and practice.", "date": "2026-08-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.00913", "title_zh": "\u4e3a\u4ec0\u4e48\u60c5\u5883\u4f1a\u5f71\u54cd\u57fa\u4e8e\u652f\u4ed8\u610f\u613f\u7684\u504f\u597d\uff0c\u800c\u975e\u57fa\u4e8e\u9009\u62e9\u7684\u504f\u597d", "abstract_zh": "\u89c4\u8303\u6027\u7406\u8bba\u5047\u8bbe\u4eba\u4eec\u5728\u903b\u8f91\u7b49\u4ef7\u7684\u51b3\u7b56\u60c5\u5883\u4e2d\u5177\u6709\u7a33\u5b9a\u7684\u504f\u597d\u3002\u5f53\u504f\u597d\u5728\u4e0d\u540c\u60c5\u5883\u4e2d\u53d1\u751f\u53d8\u5316\u65f6\uff08\u5373\u504f\u597d\u53cd\u8f6c\uff09\uff0c\u8fd9\u8fdd\u80cc\u4e86\u8be5\u5047\u8bbe\uff0c\u8868\u660e\u504f\u597d\u662f\u5728\u51b3\u7b56\u8fc7\u7a0b\u4e2d\u6784\u5efa\u7684\u3002\u6211\u4eec\u901a\u8fc7\u8bc6\u522b\u8fd9\u79cd\u60c5\u5883\u6548\u5e94\u7684\u4e00\u4e2a\u8fb9\u754c\u6761\u4ef6\uff0c\u4e3a\u8fd9\u4e00\u9886\u57df\u505a\u51fa\u4e86\u8d21\u732e\u3002\u6211\u4eec\u63d0\u51fa\uff0c\u57fa\u4e8e\u8d27\u5e01\u7684\u504f\u597d\u83b7\u53d6\uff08\u4f8b\u5982\u652f\u4ed8\u610f\u613fWTP\u548c\u63a5\u53d7\u610f\u613fWTA\uff09\u4f1a\u5f15\u53d1\u4e0e\u5916\u90e8\u60c5\u5883\u5916\u6807\u51c6\u7684\u6bd4\u8f83\uff0c\u4f8b\u5982\u7c7b\u4f3c\u5546\u54c1\u7684\u5e02\u573a\u4ef7\u683c\u3002\u8fd9\u79cd\u8131\u79bb\u60c5\u5883\u7684\u6bd4\u8f83\u5e94\u5f53\u524a\u5f31\u5c40\u90e8\u60c5\u5883\u7684\u5f71\u54cd\u3002\u6211\u4eec\u7684\u7406\u8bba\u9884\u6d4b\uff0c\u60c5\u5883\u6548\u5e94\u5728\u4ee5\u4e0b\u4e24\u79cd\u60c5\u51b5\u4e0b\u4f1a\u51cf\u5f31\uff1a\uff081\uff09\u8d27\u5e01\u6027\u504f\u597d\u83b7\u53d6\u4e0e\u975e\u8d27\u5e01\u6027\u504f\u597d\u83b7\u53d6\u4e4b\u95f4\uff08\u4f8b\u5982WTP/WTA\u4e0e\u9009\u62e9\uff09\uff1b\uff082\uff09\u5f53\u9009\u9879\u5728\u4e0e\u7c7b\u4f3c\u5546\u54c1\u548c\u670d\u52a1\u5e02\u573a\u4ef7\u683c\u9ad8\u5ea6\u76f8\u5173\u7684\u5c5e\u6027\u4e0a\u5b58\u5728\u5dee\u5f02\u65f6\u3002\u572822\u9879\u7814\u7a76\u4e2d\uff0c\u6211\u4eec\u4f7f\u7528\u4e09\u79cd\u5178\u578b\u7684\u51b3\u7b56\u60c5\u5883\u6548\u5e94\uff08\u8de8\u65f6\u95f4\u6743\u8861\u3001\u6846\u67b6\u6548\u5e94\u548c\u5438\u5f15\u529b\u6548\u5e94\uff09\u3001\u6fc0\u52b1\u76f8\u5bb9\u548c\u9648\u8ff0\u6027\u504f\u597d\uff0c\u4ee5\u53ca\u4e0d\u540c\u7684\u56de\u7b54\u683c\u5f0f\uff08\u4e8c\u5143\u3001\u8fde\u7eed\u548c\u6df7\u5408\u683c\u5f0f\uff09\uff0c\u9a8c\u8bc1\u4e86\u8fd9\u4e9b\u9884\u6d4b\u3002\u6db5\u76d6\u70d8\u7119\u98df\u54c1\u3001\u516c\u5bd3\u548c\u5f69\u7968\u7b49\u591a\u79cd\u5546\u54c1\u548c\u670d\u52a1\u7684\u504f\u597d\u5747\u8868\u73b0\u51fa\u8fd9\u4e9b\u6a21\u5f0f\u3002\u6211\u4eec\u7684\u7406\u8bba\u89e3\u91ca\u4e86\u60c5\u5883\u6548\u5e94\u7684\u663e\u8457\u53d8\u5f02\uff0c\u5e76\u4e3a\u7814\u7a76\u548c\u5b9e\u8df5\u4e2d\u60c5\u5883\u6548\u5e94\u4f55\u65f6\u4f1a\u51fa\u73b0\u63d0\u4f9b\u4e86\u53ef\u68c0\u9a8c\u7684\u9884\u6d4b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag042", "journal": "QJE", "title": "The Employment Effects of a Guaranteed Income: Experimental Evidence from Two U.S. States", "authors": ["Eva Vivalt", "Elizabeth Rhodes", "Alexander Bartik", "David Broockman", "Patrick Krause", "Sarah Miller"], "author_details": [{"name": "Eva Vivalt", "affiliations": ["University of Toronto ,"]}, {"name": "Elizabeth Rhodes", "affiliations": ["OpenResearch ,"]}, {"name": "Alexander Bartik", "affiliations": ["University of Illinois, Urbana-Champaign ,"]}, {"name": "David Broockman", "affiliations": ["University of California, Berkeley ,"]}, {"name": "Patrick Krause", "affiliations": ["OpenResearch ,"]}, {"name": "Sarah Miller", "affiliations": ["University of Michigan Ross School of Business ,"]}], "abstract": "Abstract We study the causal effects of income on a rich array of employment outcomes, leveraging an experiment in which 1,000 low-income individuals were randomized into receiving $1,000 per month unconditionally for three years, with a control group of 2,000 participants receiving $50/month. We gather detailed survey data, administrative records, and data from a mobile phone app. The transfer caused total individual income excluding the transfers to fall by about $1,900/year relative to the control group and a 4.2 percentage point decrease in labor market participation. Participants reduced their work hours as a result of the transfers by 1\u20132 hours/week and participants\u2019 partners reduced their work hours by a comparable amount. Among other categories of time use, the greatest increase generated by the transfer was in time spent on leisure. Despite asking detailed questions about amenities, we find no effect on quality of employment, and our confidence intervals can rule out even small improvements. Treated participants broadly increase expenditures, led by spending on nondurable goods and services, with smaller increases in spending on durable goods and human capital. We observe no significant effects on degree attainment, though the magnitudes of the estimated effects generally appear larger among younger participants. Measures of subjective well-being are higher among treated participants in the first year of the transfers but then revert to control-group levels. Overall, our results suggest a moderate labor supply effect that does not appear offset by other productive activities.", "date": "2026-08-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag042", "title_zh": "\u4fdd\u8bc1\u6536\u5165\u5bf9\u5c31\u4e1a\u7684\u5f71\u54cd\uff1a\u6765\u81ea\u7f8e\u56fd\u4e24\u4e2a\u5dde\u7684\u5b9e\u9a8c\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u6536\u5165\u5bf9\u591a\u79cd\u5c31\u4e1a\u7ed3\u679c\u7684\u56e0\u679c\u6548\u5e94\uff0c\u5229\u7528\u4e00\u9879\u5b9e\u9a8c\uff0c\u5c061000\u540d\u4f4e\u6536\u5165\u4e2a\u4f53\u968f\u673a\u5206\u914d\u5230\u6bcf\u6708\u65e0\u6761\u4ef6\u83b7\u5f971000\u7f8e\u5143\u3001\u6301\u7eed\u4e09\u5e74\u7684\u7fa4\u4f53\u4e2d\uff0c\u5bf9\u7167\u7ec42000\u540d\u53c2\u4e0e\u8005\u6bcf\u6708\u4ec5\u83b7\u5f9750\u7f8e\u5143\u3002\u6211\u4eec\u6536\u96c6\u4e86\u8be6\u7ec6\u7684\u8c03\u67e5\u6570\u636e\u3001\u884c\u653f\u8bb0\u5f55\u4ee5\u53ca\u6765\u81ea\u79fb\u52a8\u5e94\u7528\u7a0b\u5e8f\u7684\u6570\u636e\u3002\u8be5\u8f6c\u79fb\u5bfc\u81f4\u53d7\u8bd5\u8005\u5728\u6263\u9664\u8f6c\u79fb\u6b3e\u9879\u540e\u7684\u5e74\u603b\u6536\u5165\u6bd4\u5bf9\u7167\u7ec4\u4f4e\u7ea61900\u7f8e\u5143\uff0c\u52b3\u52a8\u5e02\u573a\u53c2\u4e0e\u7387\u4e0b\u964d4.2\u4e2a\u767e\u5206\u70b9\u3002\u53d7\u8bd5\u8005\u6bcf\u5468\u5de5\u4f5c\u65f6\u95f4\u56e0\u8f6c\u79fb\u800c\u51cf\u5c111\u81f32\u5c0f\u65f6\uff0c\u5176\u914d\u5076\u7684\u5de5\u4f5c\u65f6\u95f4\u4e5f\u76f8\u5e94\u51cf\u5c11\u76f8\u540c\u6570\u91cf\u3002\u5728\u5176\u4ed6\u65f6\u95f4\u4f7f\u7528\u7c7b\u522b\u4e2d\uff0c\u8f6c\u79fb\u5e26\u6765\u7684\u6700\u5927\u589e\u52a0\u662f\u4f11\u95f2\u65f6\u95f4\u3002\u5c3d\u7ba1\u6211\u4eec\u8be6\u7ec6\u8be2\u95ee\u4e86\u751f\u6d3b\u4fbf\u5229\u8bbe\u65bd\u7684\u60c5\u51b5\uff0c\u4f46\u5e76\u672a\u53d1\u73b0\u5bf9\u5c31\u4e1a\u8d28\u91cf\u6709\u4efb\u4f55\u5f71\u54cd\uff0c\u6211\u4eec\u7684\u7f6e\u4fe1\u533a\u95f4\u6392\u9664\u4e86\u5373\u4f7f\u662f\u5fae\u5c0f\u6539\u5584\u7684\u53ef\u80fd\u6027\u3002\u53d7\u8bd5\u8005\u6574\u4f53\u652f\u51fa\u589e\u52a0\uff0c\u4e3b\u8981\u4f53\u73b0\u5728\u975e\u8010\u7528\u54c1\u548c\u670d\u52a1\u4e1a\u7684\u652f\u51fa\u4e0a\uff0c\u8010\u7528\u54c1\u548c\u4eba\u529b\u8d44\u672c\u652f\u51fa\u7684\u589e\u52a0\u8f83\u5c0f\u3002\u6211\u4eec\u672a\u89c2\u5bdf\u5230\u5bf9\u5b66\u4f4d\u83b7\u53d6\u7684\u663e\u8457\u5f71\u54cd\uff0c\u5c3d\u7ba1\u4f30\u8ba1\u6548\u5e94\u7684\u5927\u5c0f\u5728\u5e74\u8f7b\u53c2\u4e0e\u8005\u4e2d\u666e\u904d\u66f4\u5927\u3002\u4e3b\u89c2\u5e78\u798f\u611f\u5728\u8f6c\u79fb\u7684\u7b2c\u4e00\u5e74\u4e2d\u8f83\u9ad8\uff0c\u4f46\u968f\u540e\u56de\u843d\u81f3\u5bf9\u7167\u7ec4\u6c34\u5e73\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\u5b58\u5728\u4e2d\u7b49\u7a0b\u5ea6\u7684\u52b3\u52a8\u529b\u4f9b\u7ed9\u6548\u5e94\uff0c\u4f46\u5e76\u672a\u88ab\u5176\u4ed6\u751f\u4ea7\u6027\u6d3b\u52a8\u6240\u62b5\u6d88\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag073", "journal": "RFS", "title": "The Real Effects of Environmental Activist Investing", "authors": ["S Lakshmi Naaraayanan", "Kunal Sachdeva", "Varun Sharma"], "author_details": [{"name": "S Lakshmi Naaraayanan", "affiliations": ["London Business School , , and", "CEPR , , and"]}, {"name": "Kunal Sachdeva", "affiliations": ["University of Michigan ,"]}, {"name": "Varun Sharma", "affiliations": ["Indiana University ,"]}], "abstract": "Abstract We study the real effects of environmental activist investing. Using plant-chemical-level data, we find that targeted firms reduce their production-related emissions. Air quality improvements in the vicinity of targeted plants suggest potentially significant externalities for local economies. Reductions come from increased abatement expenditures and on-site source reduction initiatives, which negatively affect the financial performance of targeted firms. We rule out alternative explanations, including declines in production and plant closures, and provide evidence that firms respond to the specific demands of activists. Our findings suggest that environmental activism is an effective tool for long-term shareholders to address climate change risks.", "date": "2026-08-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag073", "title_zh": "\u73af\u5883\u6d3b\u52a8\u6295\u8d44\u8005\u7684\u73b0\u5b9e\u6548\u5e94", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u73af\u5883\u6d3b\u52a8\u6295\u8d44\u8005\u7684\u73b0\u5b9e\u6548\u5e94\u3002\u5229\u7528\u690d\u7269-\u5316\u5b66\u54c1\u5c42\u9762\u7684\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u9488\u5bf9\u7279\u5b9a\u4f01\u4e1a\u7684\u516c\u53f8\u51cf\u5c11\u4e86\u4e0e\u5176\u751f\u4ea7\u76f8\u5173\u7684\u6392\u653e\u3002\u76ee\u6807\u5de5\u5382\u5468\u8fb9\u7a7a\u6c14\u8d28\u91cf\u7684\u6539\u5584\u8868\u660e\uff0c\u8fd9\u4e9b\u53d8\u5316\u53ef\u80fd\u5bf9\u5f53\u5730\u7ecf\u6d4e\u4ea7\u751f\u663e\u8457\u7684\u5916\u90e8\u6027\u3002\u51cf\u6392\u6e90\u4e8e\u589e\u52a0\u7684\u51cf\u6392\u652f\u51fa\u548c\u73b0\u573a\u6e90\u5934\u524a\u51cf\u63aa\u65bd\uff0c\u8fd9\u4e9b\u63aa\u65bd\u5bf9\u76ee\u6807\u4f01\u4e1a\u7684\u8d22\u52a1\u8868\u73b0\u4ea7\u751f\u4e86\u8d1f\u9762\u5f71\u54cd\u3002\u6211\u4eec\u6392\u9664\u4e86\u5176\u4ed6\u89e3\u91ca\uff0c\u5305\u62ec\u751f\u4ea7\u4e0b\u964d\u548c\u5de5\u5382\u5173\u95ed\uff0c\u63d0\u4f9b\u4e86\u8bc1\u636e\u8868\u660e\u4f01\u4e1a\u4f1a\u54cd\u5e94\u6d3b\u52a8\u5bb6\u7684\u5177\u4f53\u8981\u6c42\u3002\u6211\u4eec\u7684\u53d1\u73b0\u8868\u660e\uff0c\u73af\u5883\u6d3b\u52a8\u662f\u957f\u671f\u80a1\u4e1c\u5e94\u5bf9\u6c14\u5019\u53d8\u5316\u98ce\u9669\u7684\u6709\u6548\u5de5\u5177\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.02165", "journal": "MS", "title": "Does Renewable Energy Renew Energy Efficiency?", "authors": ["Amrou Awaysheh", "Christopher J. Chen", "Owen Q. Wu"], "author_details": [{"name": "Amrou Awaysheh", "affiliations": ["Kelley School of Business, Indiana University Indianapolis, Indianapolis, Indiana 46202"]}, {"name": "Christopher J. Chen", "affiliations": ["Kelley School of Business, Indiana University Bloomington, Bloomington, Indiana 47405"]}, {"name": "Owen Q. Wu", "affiliations": ["Kelley School of Business, Indiana University Bloomington, Bloomington, Indiana 47405"]}], "abstract": "Since 2015, global progress in improving energy efficiency has lagged behind the targets set by the United Nations Sustainable Development Goals, in part due to behavioral barriers to such improvement. Rising renewable energy adoption may impact energy efficiency improvement by raising or lowering these barriers. The well-documented rebound effect\u2014where renewable energy adoption may increase energy consumption\u2014could hinder efficiency gains, whereas renewable energy adoption may also raise awareness of energy use, thereby driving efficiency improvement. This paper examines whether and how renewable energy adoption influences energy efficiency improvement. Using data from 183 sites of a multinational industrial conglomerate from 2015 to 2020, we estimate the impact of changes in renewable energy usage and procurement methods on energy efficiency improvement. We find that using renewable energy to satisfy an additional 10% of a site\u2019s energy demand caused an additional 2.8%\u20136.1% improvement in energy efficiency. However, the impact varies significantly depending on the procurement approach. Sourcing off-site renewable energy led to energy efficiency improvement, whereas installing on-site renewable energy generation had either no effect or a negative effect. To understand the mechanism, we surveyed site managers and conducted further analysis by leveraging variations in on-site generation costs. Our results indicate that the rebound effect prevailed when sites adopted renewable energy with low ongoing costs. For corporations expanding renewable energy usage, we offer evidence of additional energy efficiency benefits, but capitalizing on these benefits requires careful consideration of the procurement approach. For policymakers, we provide guidance on prioritizing certain procurement methods to accelerate progress toward net-zero.", "date": "2026-08-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.02165", "title_zh": "\u53ef\u518d\u751f\u80fd\u6e90\u662f\u5426\u80fd\u63d0\u5347\u80fd\u6e90\u6548\u7387\uff1f", "abstract_zh": "\u81ea2015\u5e74\u4ee5\u6765\uff0c\u5168\u7403\u5728\u63d0\u9ad8\u80fd\u6e90\u6548\u7387\u65b9\u9762\u7684\u8fdb\u5c55\u672a\u80fd\u8fbe\u5230\u8054\u5408\u56fd\u53ef\u6301\u7eed\u53d1\u5c55\u76ee\u6807\u8bbe\u5b9a\u7684\u6c34\u5e73\uff0c\u90e8\u5206\u539f\u56e0\u5728\u4e8e\u5b58\u5728\u6539\u5584\u80fd\u6e90\u6548\u7387\u7684\u884c\u4e3a\u969c\u788d\u3002\u53ef\u518d\u751f\u80fd\u6e90\u7684\u666e\u53ca\u53ef\u80fd\u901a\u8fc7\u63d0\u9ad8\u6216\u964d\u4f4e\u8fd9\u4e9b\u969c\u788d\u6765\u5f71\u54cd\u80fd\u6e90\u6548\u7387\u7684\u63d0\u5347\u3002\u5df2\u5e7f\u6cdb\u8bb0\u5f55\u7684\u2018\u53cd\u5f39\u6548\u5e94\u2019\u2014\u2014\u5373\u53ef\u518d\u751f\u80fd\u6e90\u7684\u91c7\u7528\u53ef\u80fd\u589e\u52a0\u80fd\u6e90\u6d88\u8d39\u2014\u2014\u53ef\u80fd\u4f1a\u963b\u788d\u6548\u7387\u7684\u63d0\u5347\uff0c\u800c\u53ef\u518d\u751f\u80fd\u6e90\u7684\u91c7\u7528\u4e5f\u53ef\u80fd\u63d0\u9ad8\u4eba\u4eec\u5bf9\u80fd\u6e90\u4f7f\u7528\u7684\u8ba4\u8bc6\uff0c\u4ece\u800c\u63a8\u52a8\u6548\u7387\u6539\u5584\u3002\u672c\u6587\u7814\u7a76\u4e86\u53ef\u518d\u751f\u80fd\u6e90\u91c7\u7528\u662f\u5426\u4ee5\u53ca\u5982\u4f55\u5f71\u54cd\u80fd\u6e90\u6548\u7387\u7684\u63d0\u5347\u3002\u5229\u7528\u4e00\u5bb6\u8de8\u56fd\u5de5\u4e1a\u96c6\u56e2183\u4e2a\u7ad9\u70b92015\u5e74\u81f32020\u5e74\u7684\u6570\u636e\uff0c\u6211\u4eec\u4f30\u8ba1\u4e86\u53ef\u518d\u751f\u80fd\u6e90\u4f7f\u7528\u548c\u91c7\u8d2d\u65b9\u5f0f\u53d8\u5316\u5bf9\u80fd\u6e90\u6548\u7387\u63d0\u5347\u7684\u5f71\u54cd\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u7528\u53ef\u518d\u751f\u80fd\u6e90\u6ee1\u8db3\u4e00\u4e2a\u7ad9\u70b9\u989d\u591610%\u7684\u80fd\u6e90\u9700\u6c42\uff0c\u53ef\u5e26\u6765\u989d\u59162.8%\u81f36.1%\u7684\u80fd\u6e90\u6548\u7387\u63d0\u5347\u3002\u7136\u800c\uff0c\u8fd9\u79cd\u5f71\u54cd\u5728\u91c7\u8d2d\u65b9\u5f0f\u4e0a\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002\u91c7\u8d2d\u79bb\u5cb8\u53ef\u518d\u751f\u80fd\u6e90\u6709\u52a9\u4e8e\u63d0\u5347\u80fd\u6e90\u6548\u7387\uff0c\u800c\u5efa\u8bbe\u672c\u5730\u53ef\u518d\u751f\u80fd\u6e90\u53d1\u7535\u8bbe\u65bd\u5219\u53ef\u80fd\u6ca1\u6709\u6548\u679c\uff0c\u751a\u81f3\u4ea7\u751f\u8d1f\u9762\u5f71\u54cd\u3002\u4e3a\u4e86\u7406\u89e3\u5176\u4f5c\u7528\u673a\u5236\uff0c\u6211\u4eec\u5bf9\u7ad9\u70b9\u7ecf\u7406\u8fdb\u884c\u4e86\u95ee\u5377\u8c03\u67e5\uff0c\u5e76\u901a\u8fc7\u5206\u6790\u672c\u5730\u53d1\u7535\u6210\u672c\u7684\u5dee\u5f02\u8fdb\u884c\u4e86\u8fdb\u4e00\u6b65\u7814\u7a76\u3002\u7ed3\u679c\u8868\u660e\uff0c\u5f53\u7ad9\u70b9\u91c7\u7528\u6210\u672c\u8f83\u4f4e\u7684\u53ef\u518d\u751f\u80fd\u6e90\u65f6\uff0c\u53cd\u5f39\u6548\u5e94\u5360\u4e3b\u5bfc\u5730\u4f4d\u3002\u5bf9\u4e8e\u6b63\u5728\u6269\u5927\u53ef\u518d\u751f\u80fd\u6e90\u4f7f\u7528\u7684\u516c\u53f8\uff0c\u6211\u4eec\u63d0\u4f9b\u4e86\u989d\u5916\u80fd\u6e90\u6548\u7387\u6536\u76ca\u7684\u8bc1\u636e\uff0c\u4f46\u8981\u5b9e\u73b0\u8fd9\u4e9b\u6536\u76ca\uff0c\u5fc5\u987b\u4ed4\u7ec6\u8003\u8651\u91c7\u8d2d\u65b9\u5f0f\u3002\u5bf9\u4e8e\u653f\u7b56\u5236\u5b9a\u8005\uff0c\u6211\u4eec\u63d0\u4f9b\u4e86\u4f18\u5148\u9009\u62e9\u7279\u5b9a\u91c7\u8d2d\u65b9\u5f0f\u4ee5\u52a0\u901f\u5b9e\u73b0\u51c0\u96f6\u76ee\u6807\u7684\u5efa\u8bae\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag089", "journal": "REStud", "title": "An Optimal Test for Strategic Interaction in Network Formation Games", "authors": ["Andrin Pelican", "Bryan S Graham"], "author_details": [{"name": "Andrin Pelican", "affiliations": ["Independent Scholar ,"]}, {"name": "Bryan S Graham", "affiliations": ["National Bureau of Economic Research Department of Economics, University of California \u2014 Berkeley and ,"]}], "abstract": "Abstract Consider a setting where N players, partitioned into K observable types, form a directed network. Agents\u2019 preferences over the form of the network consist of an arbitrary network benefit function (e.g. agents may have preferences over their network centrality) and a private, or dyadic, component which is additively separable in own links. This latter component allows for unobserved heterogeneity in the costs of sending and receiving links across agents (respectively out- and in- degree heterogeneity) as well as homophily/heterophily across the K types of agents. In contrast, the network benefit function allows agents\u2019 preferences over links to vary with the presence or absence of links elsewhere in the network (and hence with the link formation behavior of their peers). In the null model, which excludes the network benefit function, links form independently across dyads in the manner described by Charbonneau, 2017, Econometrics Journal, 20, S1\u2013S13 among others. Under the alternative, there is interdependence across linking decisions (i.e. strategic interaction). We show how to test the null with power optimized in specific directions. These alternative directions include many common models of strategic network formation (e.g. \u201cconnections\u201d models, \u201cstructural hole\u201d models etc.). Our random utility specification induces an exponential family structure under the null which we exploit to construct a similar test which exactly controls size (despite the the null being a composite one with many nuisance parameters). We further show how to construct locally best tests for specific alternatives without making any assumptions about equilibrium selection. To make our tests feasible, we introduce a new MCMC algorithm for simulating the null distributions of our test statistics.", "date": "2026-08-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag089", "title_zh": "\u7f51\u7edc\u5f62\u6210\u535a\u5f08\u4e2d\u6218\u7565\u4e92\u52a8\u7684\u6700\u4f18\u68c0\u9a8c", "abstract_zh": "\u8003\u8651\u4e00\u4e2a\u7531N\u4e2a\u73a9\u5bb6\u7ec4\u6210\u7684\u573a\u666f\uff0c\u8fd9\u4e9b\u73a9\u5bb6\u88ab\u5212\u5206\u4e3aK\u79cd\u53ef\u89c2\u5bdf\u7c7b\u578b\uff0c\u5e76\u5f62\u6210\u6709\u5411\u7f51\u7edc\u3002\u73a9\u5bb6\u5bf9\u7f51\u7edc\u7ed3\u6784\u7684\u504f\u597d\u7531\u4e00\u4e2a\u4efb\u610f\u7684\u7f51\u7edc\u6536\u76ca\u51fd\u6570\uff08\u4f8b\u5982\uff0c\u73a9\u5bb6\u53ef\u80fd\u504f\u597d\u5176\u7f51\u7edc\u4e2d\u5fc3\u6027\uff09\u4ee5\u53ca\u4e00\u4e2a\u79c1\u6709\u7684\u3001\u53ef\u52a0\u6027\u7684\u53cc\u8fb9\u6210\u5206\u6784\u6210\u3002\u540e\u8005\u5141\u8bb8\u5728\u53d1\u9001\u548c\u63a5\u6536\u94fe\u63a5\u7684\u6210\u672c\u4e0a\u5b58\u5728\u672a\u89c2\u6d4b\u5230\u7684\u5f02\u8d28\u6027\uff08\u5373\u51fa\u5ea6\u548c\u5165\u5ea6\u5f02\u8d28\u6027\uff09\uff0c\u4ee5\u53caK\u79cd\u7c7b\u578b\u73a9\u5bb6\u4e4b\u95f4\u7684\u540c\u8d28\u6027\u6216\u5f02\u8d28\u6027\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u7f51\u7edc\u6536\u76ca\u51fd\u6570\u5141\u8bb8\u73a9\u5bb6\u5bf9\u94fe\u63a5\u7684\u504f\u597d\u968f\u7f51\u7edc\u4e2d\u5176\u4ed6\u5730\u65b9\u94fe\u63a5\u7684\u5b58\u5728\u6216\u7f3a\u5931\u800c\u53d8\u5316\uff08\u5373\u968f\u5176\u540c\u4f34\u7684\u94fe\u63a5\u5f62\u6210\u884c\u4e3a\u800c\u53d8\u5316\uff09\u3002\u5728\u96f6\u6a21\u578b\u4e2d\uff0c\u5373\u6392\u9664\u7f51\u7edc\u6536\u76ca\u51fd\u6570\u7684\u60c5\u51b5\u4e0b\uff0c\u94fe\u63a5\u5728\u5404\u53cc\u8fb9\u5bf9\u4e4b\u95f4\u72ec\u7acb\u5f62\u6210\uff0c\u5176\u5f62\u6210\u65b9\u5f0f\u5982Charbonneau\uff082017\uff09\uff0c\u300a\u8ba1\u91cf\u7ecf\u6d4e\u5b66\u6742\u5fd7\u300b\uff0c20\u5377\uff0cS1\u2013S13\u4e2d\u6240\u8ff0\u3002\u5728\u5907\u62e9\u6a21\u578b\u4e2d\uff0c\u5b58\u5728\u94fe\u63a5\u51b3\u7b56\u4e4b\u95f4\u7684\u76f8\u4e92\u4f9d\u8d56\u6027\uff08\u5373\u6218\u7565\u4e92\u52a8\uff09\u3002\u6211\u4eec\u5c55\u793a\u4e86\u5982\u4f55\u5728\u7279\u5b9a\u65b9\u5411\u4e0a\u4f18\u5316\u68c0\u9a8c\u96f6\u5047\u8bbe\u7684\u6548\u529b\u3002\u8fd9\u4e9b\u5907\u62e9\u65b9\u5411\u5305\u62ec\u8bb8\u591a\u5e38\u89c1\u7684\u6218\u7565\u7f51\u7edc\u5f62\u6210\u6a21\u578b\uff08\u4f8b\u5982\u201c\u8fde\u63a5\u201d\u6a21\u578b\u3001\u201c\u7ed3\u6784\u7a7a\u9699\u201d\u6a21\u578b\u7b49\uff09\u3002\u6211\u4eec\u7684\u968f\u673a\u6548\u7528\u89c4\u8303\u5728\u96f6\u5047\u8bbe\u4e0b\u8bf1\u5bfc\u51fa\u6307\u6570\u65cf\u7ed3\u6784\uff0c\u6211\u4eec\u5229\u7528\u8fd9\u4e00\u7ed3\u6784\u6784\u9020\u4e86\u4e00\u4e2a\u7cbe\u786e\u63a7\u5236\u663e\u8457\u6027\u7684\u68c0\u9a8c\uff08\u5c3d\u7ba1\u96f6\u5047\u8bbe\u662f\u4e00\u4e2a\u5305\u542b\u591a\u4e2a\u5197\u4f59\u53c2\u6570\u7684\u590d\u5408\u5047\u8bbe\uff09\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u5c55\u793a\u4e86\u5982\u4f55\u5728\u4e0d\u5047\u8bbe\u5747\u8861\u9009\u62e9\u7684\u60c5\u51b5\u4e0b\uff0c\u4e3a\u7279\u5b9a\u5907\u62e9\u6a21\u578b\u6784\u9020\u5c40\u90e8\u6700\u4f18\u68c0\u9a8c\u3002\u4e3a\u4f7f\u6211\u4eec\u7684\u68c0\u9a8c\u53ef\u884c\uff0c\u6211\u4eec\u5f15\u5165\u4e86\u4e00\u79cd\u65b0\u7684MCMC\u7b97\u6cd5\uff0c\u7528\u4e8e\u6a21\u62df\u68c0\u9a8c\u7edf\u8ba1\u91cf\u5728\u96f6\u5047\u8bbe\u4e0b\u7684\u5206\u5e03\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/restud/rdag083", "journal": "REStud", "title": "Informative Certification: Screening versus Acquisition", "authors": ["Gorkem Celik", "Roland Strausz"], "author_details": [{"name": "Gorkem Celik", "affiliations": ["ESSEC Business School & THEMA Research Center , France"]}, {"name": "Roland Strausz", "affiliations": ["Humboldt Universit\u00e4t zu Berlin & Berlin School of Economics , Germany"]}], "abstract": "Abstract We study monopolistic certification in markets where sellers possess partial private information about product quality. A certifier can provide information through two channels: screening sellers\u2019 private information (soft information) and acquiring new quality data (hard information). We prove that any certification menu achieving less than maximal screening is Pareto dominated by one with full screening. Among Pareto-efficient menus, the certifier\u2019s profit-maximizing menu provides maximal soft information while restricting hard information provision. The two channels diverge because screening creates value the certifier can fully capture, whereas hard information amplifies costly information rents. Using power value functions, we derive comparative statics showing that information restrictions target low-quality sellers when information value is moderate, but high-quality sellers receive perfect quality revelation when information value is high.", "date": "2026-08-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag083", "title_zh": "\u4fe1\u606f\u6027\u8ba4\u8bc1\uff1a\u7b5b\u9009\u4e0e\u83b7\u53d6", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u5728\u5356\u65b9\u5bf9\u4ea7\u54c1\u54c1\u8d28\u62e5\u6709\u90e8\u5206\u79c1\u4eba\u4fe1\u606f\u7684\u5784\u65ad\u8ba4\u8bc1\u5e02\u573a\u4e2d\uff0c\u8ba4\u8bc1\u673a\u6784\u53ef\u4ee5\u901a\u8fc7\u4e24\u79cd\u6e20\u9053\u63d0\u4f9b\u4fe1\u606f\uff1a\u7b5b\u9009\u5356\u65b9\u7684\u79c1\u4eba\u4fe1\u606f\uff08\u8f6f\u4fe1\u606f\uff09\u548c\u83b7\u53d6\u65b0\u7684\u54c1\u8d28\u6570\u636e\uff08\u786c\u4fe1\u606f\uff09\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u4efb\u4f55\u5b9e\u73b0\u4f4e\u4e8e\u6700\u5927\u7b5b\u9009\u6c34\u5e73\u7684\u8ba4\u8bc1\u65b9\u6848\u5747\u88ab\u5b8c\u5168\u7b5b\u9009\u7684\u65b9\u6848\u5e15\u7d2f\u6258\u652f\u914d\u3002\u5728\u5e15\u7d2f\u6258\u6709\u6548\u7684\u65b9\u6848\u4e2d\uff0c\u8ba4\u8bc1\u673a\u6784\u5229\u6da6\u6700\u5927\u5316\u65b9\u6848\u63d0\u4f9b\u6700\u5927\u91cf\u7684\u8f6f\u4fe1\u606f\uff0c\u540c\u65f6\u9650\u5236\u786c\u4fe1\u606f\u7684\u63d0\u4f9b\u3002\u4e24\u79cd\u6e20\u9053\u5b58\u5728\u5206\u6b67\uff0c\u56e0\u4e3a\u7b5b\u9009\u4ea7\u751f\u7684\u4ef7\u503c\u53ef\u4ee5\u88ab\u8ba4\u8bc1\u673a\u6784\u5b8c\u5168\u6355\u83b7\uff0c\u800c\u786c\u4fe1\u606f\u4f1a\u653e\u5927\u4fe1\u606f\u79df\u91d1\u7684\u6210\u672c\u3002\u5229\u7528\u6743\u529b\u4ef7\u503c\u51fd\u6570\uff0c\u6211\u4eec\u63a8\u5bfc\u51fa\u6bd4\u8f83\u9759\u6001\u7ed3\u679c\uff0c\u8868\u660e\u5f53\u4fe1\u606f\u4ef7\u503c\u9002\u4e2d\u65f6\uff0c\u4fe1\u606f\u9650\u5236\u9488\u5bf9\u4f4e\u8d28\u91cf\u5356\u65b9\uff0c\u800c\u5f53\u4fe1\u606f\u4ef7\u503c\u8f83\u9ad8\u65f6\uff0c\u9ad8\u8d28\u91cf\u5356\u65b9\u83b7\u5f97\u5b8c\u5168\u7684\u54c1\u8d28\u63ed\u793a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag088", "journal": "REStud", "title": "Capital Unemployment", "authors": ["Pablo Ottonello"], "author_details": [{"name": "Pablo Ottonello", "affiliations": ["Brown University and NBER"]}], "abstract": "Abstract This paper studies the unemployment of physical capital\u2014defined as idle units searching to be traded\u2014and its macroeconomic implications. I provide evidence documenting that capital unemployment is large, volatile, and increases during economic downturns. I construct a capital-accumulation model that explains these patterns, with trading frictions in capital markets, which give rise to equilibrium capital unemployment, and financial shocks, which lead to large fluctuations in trading probabilities and capital unemployment. Using the model, I show that trading frictions and capital unemployment matter for aggregate dynamics. First, unemployed capital affects aggregate investment dynamics: Downturns characterized by large increases in unemployed capital are followed by investment slumps, because the economy tends to recover by absorbing existing unemployed capital rather than by producing new capital goods. Second, capital unemployment constitutes a propagation mechanism from financial shocks to economic activity, which shows up at the aggregate level as measured total factor productivity.", "date": "2026-08-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag088", "title_zh": "\u8d44\u672c\u5931\u4e1a", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5b9e\u7269\u8d44\u672c\u7684\u5931\u4e1a\u95ee\u9898\u2014\u2014\u5373\u95f2\u7f6e\u7684\u8d44\u672c\u5355\u4f4d\u5728\u5bfb\u627e\u4ea4\u6613\u8fc7\u7a0b\u4e2d\u7684\u5931\u4e1a\u72b6\u6001\u2014\u2014\u53ca\u5176\u5b8f\u89c2\u7ecf\u6d4e\u5f71\u54cd\u3002\u6211\u63d0\u4f9b\u4e86\u8bc1\u636e\u8868\u660e\uff0c\u8d44\u672c\u5931\u4e1a\u89c4\u6a21\u5e9e\u5927\u3001\u6ce2\u52a8\u6027\u5f3a\uff0c\u5e76\u5728\u7ecf\u6d4e\u8870\u9000\u671f\u95f4\u663e\u8457\u4e0a\u5347\u3002\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u8d44\u672c\u79ef\u7d2f\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u901a\u8fc7\u8d44\u672c\u5e02\u573a\u7684\u4ea4\u6613\u6469\u64e6\u89e3\u91ca\u4e86\u8fd9\u4e9b\u73b0\u8c61\uff0c\u8fd9\u4e9b\u6469\u64e6\u5bfc\u81f4\u4e86\u5747\u8861\u72b6\u6001\u4e0b\u7684\u8d44\u672c\u5931\u4e1a\uff0c\u800c\u91d1\u878d\u51b2\u51fb\u5219\u5f15\u53d1\u4ea4\u6613\u6982\u7387\u548c\u8d44\u672c\u5931\u4e1a\u7684\u5927\u5e45\u6ce2\u52a8\u3002\u5229\u7528\u8be5\u6a21\u578b\uff0c\u6211\u8868\u660e\u4ea4\u6613\u6469\u64e6\u548c\u8d44\u672c\u5931\u4e1a\u5bf9\u6574\u4f53\u7ecf\u6d4e\u52a8\u6001\u5177\u6709\u91cd\u8981\u5f71\u54cd\u3002\u9996\u5148\uff0c\u5931\u4e1a\u8d44\u672c\u5f71\u54cd\u6574\u4f53\u6295\u8d44\u52a8\u6001\uff1a\u5728\u8d44\u672c\u5931\u4e1a\u5927\u5e45\u589e\u52a0\u7684\u8870\u9000\u671f\uff0c\u6295\u8d44\u968f\u4e4b\u4e0b\u6ed1\uff0c\u56e0\u4e3a\u7ecf\u6d4e\u590d\u82cf\u5f80\u5f80\u901a\u8fc7\u5438\u6536\u73b0\u6709\u7684\u95f2\u7f6e\u8d44\u672c\u800c\u975e\u751f\u4ea7\u65b0\u7684\u8d44\u672c\u54c1\u6765\u5b9e\u73b0\u3002\u5176\u6b21\uff0c\u8d44\u672c\u5931\u4e1a\u6210\u4e3a\u91d1\u878d\u51b2\u51fb\u5411\u7ecf\u6d4e\u6d3b\u52a8\u4f20\u5bfc\u7684\u673a\u5236\uff0c\u5728\u6574\u4f53\u5c42\u9762\u8868\u73b0\u4e3a\u603b\u8981\u7d20\u751f\u4ea7\u7387\u7684\u53d8\u52a8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag074", "journal": "RFS", "title": "What Do Impact Investors Do Differently?", "authors": ["Shawn Cole", "Leslie Jeng", "Josh Lerner", "Natalia Rigol", "Benjamin N Roth"], "author_details": [{"name": "Shawn Cole", "affiliations": ["Harvard University and NBER ,"]}, {"name": "Leslie Jeng", "affiliations": ["Harvard University ,"]}, {"name": "Josh Lerner", "affiliations": ["Harvard University and NBER ,"]}, {"name": "Natalia Rigol", "affiliations": ["Harvard University and NBER ,"]}, {"name": "Benjamin N Roth", "affiliations": ["Harvard University ,"]}], "abstract": "Abstract Do impact investors seek impact, or merely \u201cimpact wash\u201d? We provide systematic evidence on the nonfinancial determinants of impact investing. Impact investors focus on firms aligned with the priorities of the federal government and disproportionately invest in economically disadvantaged regions. While we find high levels of coinvestment between impact and traditional investors, we also show that impact investors influence the strategies of their traditional coinvestors, are more likely to fund firms in nascent industries, and invest countercyclically. Finally, we characterize investment heterogeneity based on a novel classification of impact investment theses, with a focus on climate, environment, and jobs and equity.", "date": "2026-08-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag074", "title_zh": "\u5f71\u54cd\u529b\u6295\u8d44\u8005\u7a76\u7adf\u505a\u4e86\u4ec0\u4e48\u4e0d\u540c\u4e4b\u5904\uff1f", "abstract_zh": "\u6458\u8981 \u5f71\u54cd\u529b\u6295\u8d44\u8005\u8ffd\u6c42\u5f71\u54cd\u529b\uff0c\u8fd8\u662f\u4ec5\u4ec5\u8fdb\u884c\u2018\u5f71\u54cd\u529b\u6d17\u724c\u2019\uff1f\u6211\u4eec\u63d0\u4f9b\u4e86\u5173\u4e8e\u5f71\u54cd\u529b\u6295\u8d44\u975e\u8d22\u52a1\u51b3\u5b9a\u56e0\u7d20\u7684\u7cfb\u7edf\u6027\u8bc1\u636e\u3002\u5f71\u54cd\u529b\u6295\u8d44\u8005\u503e\u5411\u4e8e\u6295\u8d44\u4e0e\u8054\u90a6\u653f\u5e9c\u4f18\u5148\u4e8b\u9879\u76f8\u4e00\u81f4\u7684\u516c\u53f8\uff0c\u5e76\u5728\u7ecf\u6d4e\u5f31\u52bf\u5730\u533a\u6295\u5165\u66f4\u591a\u8d44\u91d1\u3002\u5c3d\u7ba1\u6211\u4eec\u53d1\u73b0\u5f71\u54cd\u529b\u6295\u8d44\u8005\u4e0e\u4f20\u7edf\u6295\u8d44\u8005\u4e4b\u95f4\u5b58\u5728\u9ad8\u6c34\u5e73\u7684\u5171\u540c\u6295\u8d44\uff0c\u4f46\u6211\u4eec\u8fd8\u8868\u660e\uff0c\u5f71\u54cd\u529b\u6295\u8d44\u8005\u4f1a\u5f71\u54cd\u5176\u4f20\u7edf\u5171\u540c\u6295\u8d44\u65b9\u7684\u7b56\u7565\uff0c\u66f4\u53ef\u80fd\u6295\u8d44\u4e8e\u65b0\u5174\u884c\u4e1a\uff0c\u5e76\u4e14\u5177\u6709\u9006\u5468\u671f\u6295\u8d44\u7684\u7279\u5f81\u3002\u6700\u540e\uff0c\u6211\u4eec\u57fa\u4e8e\u4e00\u79cd\u65b0\u9896\u7684\u5f71\u54cd\u529b\u6295\u8d44\u7406\u8bba\u5206\u7c7b\u65b9\u6cd5\uff0c\u5bf9\u6295\u8d44\u5f02\u8d28\u6027\u8fdb\u884c\u4e86\u523b\u753b\uff0c\u91cd\u70b9\u5173\u6ce8\u6c14\u5019\u3001\u73af\u5883\u4ee5\u53ca\u5c31\u4e1a\u548c\u80a1\u6743\u9886\u57df\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag076", "journal": "RFS", "title": "Personal Bankruptcy Protection and Household Debt", "authors": ["Felipe Severino", "Meta Brown", "Rajashri Chakrabarti"], "author_details": [{"name": "Felipe Severino", "affiliations": ["Dartmouth College ,"]}, {"name": "Meta Brown", "affiliations": ["Ohio State University ,"]}, {"name": "Rajashri Chakrabarti", "affiliations": ["Federal Reserve Bank of New York ,"]}], "abstract": "Abstract Increasing personal bankruptcy protection raises consumers\u2019 desire to borrow and lenders\u2019 cost of extending credit; the impact on equilibrium borrowing is ambiguous. Using bankruptcy protection changes between 1999 and 2005 across U.S. states, we find that borrowers respond to greater protection by increasing their unsecured debt. Border county estimates suggest that local economic conditions do not drive these results. Borrowers pay more for protection through higher interest rates, yet delinquency is unaffected. Our results indicate that rising borrower demand outstripped decreasing supply. Increased protections did not reduce the aggregate level of household debt but affected the composition of borrowing.", "date": "2026-08-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag076", "title_zh": "\u4e2a\u4eba\u7834\u4ea7\u4fdd\u62a4\u4e0e\u5bb6\u5ead\u503a\u52a1", "abstract_zh": "\u6458\u8981 \u4e2a\u4eba\u7834\u4ea7\u4fdd\u62a4\u7684\u589e\u52a0\u4f1a\u63d0\u9ad8\u6d88\u8d39\u8005\u501f\u6b3e\u7684\u610f\u613f\uff0c\u5e76\u63d0\u9ad8\u8d37\u6b3e\u65b9\u63d0\u4f9b\u4fe1\u8d37\u7684\u6210\u672c\uff1b\u5176\u5bf9\u5747\u8861\u501f\u6b3e\u7684\u5f71\u54cd\u5c1a\u4e0d\u660e\u786e\u3002\u5229\u75281999\u5e74\u81f32005\u5e74\u95f4\u7f8e\u56fd\u5404\u5dde\u7834\u4ea7\u4fdd\u62a4\u653f\u7b56\u7684\u53d8\u5316\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u501f\u6b3e\u4eba\u5728\u83b7\u5f97\u66f4\u5f3a\u4fdd\u62a4\u540e\u4f1a\u589e\u52a0\u5176\u65e0\u62c5\u4fdd\u503a\u52a1\u3002\u8fb9\u5883\u53bf\u7684\u4f30\u8ba1\u8868\u660e\uff0c\u5f53\u5730\u7ecf\u6d4e\u6761\u4ef6\u5e76\u672a\u9a71\u52a8\u8fd9\u4e9b\u7ed3\u679c\u3002\u501f\u6b3e\u4eba\u901a\u8fc7\u66f4\u9ad8\u7684\u5229\u7387\u4e3a\u4fdd\u62a4\u652f\u4ed8\u4e86\u66f4\u591a\u8d39\u7528\uff0c\u4f46\u8fdd\u7ea6\u7387\u5e76\u672a\u53d7\u5230\u5f71\u54cd\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u501f\u6b3e\u9700\u6c42\u7684\u4e0a\u5347\u8d85\u8fc7\u4e86\u4fe1\u8d37\u4f9b\u7ed9\u7684\u4e0b\u964d\u3002\u66f4\u5f3a\u7684\u4fdd\u62a4\u5e76\u672a\u964d\u4f4e\u5bb6\u5ead\u503a\u52a1\u7684\u603b\u4f53\u6c34\u5e73\uff0c\u800c\u662f\u6539\u53d8\u4e86\u501f\u6b3e\u7684\u7ed3\u6784\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2025.00761", "journal": "MS", "title": "Consumer Inferences from Product Rankings: The Role of Beliefs in Search Behavior", "authors": ["Jessica Fong", "Olivia R. Natan", "Ranmit Pantle"], "author_details": [{"name": "Jessica Fong", "affiliations": ["Ross School of Business, University of Michigan, Ann Arbor, Michigan 48109"]}, {"name": "Olivia R. Natan", "affiliations": ["Haas School of Business, University of California, Berkeley, Berkeley, California 94720"]}, {"name": "Ranmit Pantle", "affiliations": ["Kellogg School of Management, Northwestern University, Evanston, Illinois 60208"]}], "abstract": "In online markets, consumers tend to search and purchase prominently positioned products. We develop an experimental paradigm to distinguish between two mechanisms driving this behavior: position-specific search costs and beliefs about expected returns to search. Using incentivized experiments, we find that both mechanisms exist, and short-term randomization of rankings alone does not separate the two mechanisms. Failing to account for beliefs leads to biased estimates of search costs and incorrect consumer welfare predictions under alternative recommendation systems, such as platform self-preferencing. We discuss solutions for estimating unbiased search costs in real-world search settings.", "date": "2026-08-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.00761", "title_zh": "\u6d88\u8d39\u8005\u4ece\u4ea7\u54c1\u6392\u540d\u4e2d\u63a8\u65ad\u51fa\u7684\u4fe1\u5ff5\uff1a\u4fe1\u5ff5\u5728\u641c\u7d22\u884c\u4e3a\u4e2d\u7684\u4f5c\u7528", "abstract_zh": "\u5728\u5728\u7ebf\u5e02\u573a\u4e2d\uff0c\u6d88\u8d39\u8005\u5f80\u5f80\u503e\u5411\u4e8e\u641c\u7d22\u548c\u8d2d\u4e70\u4f4d\u7f6e\u7a81\u51fa\u7684\u4ea7\u54c1\u3002\u6211\u4eec\u8bbe\u8ba1\u4e86\u4e00\u79cd\u5b9e\u9a8c\u8303\u5f0f\uff0c\u4ee5\u533a\u5206\u9a71\u52a8\u8fd9\u4e00\u884c\u4e3a\u7684\u4e24\u79cd\u673a\u5236\uff1a\u4f4d\u7f6e\u7279\u5b9a\u7684\u641c\u7d22\u6210\u672c\u4ee5\u53ca\u6d88\u8d39\u8005\u5bf9\u641c\u7d22\u9884\u671f\u56de\u62a5\u7684\u4fe1\u5ff5\u3002\u901a\u8fc7\u6fc0\u52b1\u6027\u5b9e\u9a8c\uff0c\u6211\u4eec\u53d1\u73b0\u8fd9\u4e24\u79cd\u673a\u5236\u5747\u5b58\u5728\uff0c\u4ec5\u5bf9\u6392\u540d\u8fdb\u884c\u77ed\u671f\u968f\u673a\u5316\u65e0\u6cd5\u5c06\u4e8c\u8005\u533a\u5206\u5f00\u3002\u82e5\u5ffd\u7565\u4fe1\u5ff5\u56e0\u7d20\uff0c\u4f1a\u5bfc\u81f4\u5bf9\u641c\u7d22\u6210\u672c\u7684\u504f\u8bef\u4f30\u8ba1\uff0c\u4ee5\u53ca\u5728\u5e73\u53f0\u81ea\u6211\u504f\u597d\u7b49\u66ff\u4ee3\u63a8\u8350\u7cfb\u7edf\u4e0b\u6d88\u8d39\u8005\u798f\u5229\u9884\u6d4b\u7684\u9519\u8bef\u3002\u6211\u4eec\u8ba8\u8bba\u4e86\u5728\u73b0\u5b9e\u641c\u7d22\u73af\u5883\u4e2d\u5982\u4f55\u4f30\u8ba1\u65e0\u504f\u641c\u7d22\u6210\u672c\u7684\u89e3\u51b3\u65b9\u6848\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag090", "journal": "REStud", "title": "Embracing the Enemy", "authors": ["\u00c1lvaro Delgado-Vega", "Johannes Schneider"], "author_details": [{"name": "\u00c1lvaro Delgado-Vega", "affiliations": ["University of Chicago ,"]}, {"name": "Johannes Schneider", "affiliations": ["Johannes Kepler University , Linz, Austria"]}], "abstract": "Abstract A principal (such as a centrist political party) can partially influence the allocation of power between two competing parties. The principal is closer to one party, the \u201cFriend\u201d, than to the other, the \u201cEnemy\u201d. The principal\u2019s optimal contract initially seeks to exclude the Enemy. However, once the Enemy gains power, the principal embraces him in exchange for policy moderation. Moderation also disciplines the Friend, inducing him to move closer to the principal\u2019s preferred policy. Principals close to the Friend fully embrace the Enemy; more centrist principals divide their support. Commitment benefits the principal only if she is close to the Friend and parties value power little.", "date": "2026-08-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag090", "title_zh": "\u62e5\u62b1\u654c\u4eba", "abstract_zh": "\u6458\u8981 \u4e00\u4e2a\u4e3b\u8981\u65b9\uff08\u4f8b\u5982\u4e00\u4e2a\u4e2d\u95f4\u6d3e\u653f\u515a\uff09\u53ef\u4ee5\u90e8\u5206\u5f71\u54cd\u4e24\u4e2a\u7ade\u4e89\u6027\u653f\u515a\u4e4b\u95f4\u7684\u6743\u529b\u5206\u914d\u3002\u8be5\u4e3b\u8981\u65b9\u66f4\u63a5\u8fd1\u4e00\u65b9\u653f\u515a\uff0c\u5373\u201c\u670b\u53cb\u201d\uff0c\u800c\u975e\u53e6\u4e00\u65b9\uff0c\u5373\u201c\u654c\u4eba\u201d\u3002\u4e3b\u8981\u65b9\u7684\u6700\u4f18\u5408\u540c\u6700\u521d\u65e8\u5728\u6392\u9664\u654c\u4eba\u3002\u7136\u800c\uff0c\u4e00\u65e6\u654c\u4eba\u83b7\u5f97\u6743\u529b\uff0c\u4e3b\u8981\u65b9\u4fbf\u8f6c\u800c\u652f\u6301\u4ed6\uff0c\u4ee5\u6362\u53d6\u653f\u7b56\u4e0a\u7684\u6e29\u548c\u5316\u3002\u8fd9\u79cd\u6e29\u548c\u5316\u4e5f\u5bf9\u670b\u53cb\u4ea7\u751f\u7ea6\u675f\u4f5c\u7528\uff0c\u4fc3\u4f7f\u670b\u53cb\u5411\u4e3b\u8981\u65b9\u504f\u597d\u7684\u653f\u7b56\u65b9\u5411\u79fb\u52a8\u3002\u5982\u679c\u4e3b\u8981\u65b9\u66f4\u63a5\u8fd1\u670b\u53cb\uff0c\u90a3\u4e48\u4e3b\u8981\u65b9\u4f1a\u5b8c\u5168\u652f\u6301\u654c\u4eba\uff1b\u800c\u66f4\u52a0\u4e2d\u95f4\u7acb\u573a\u7684\u4e3b\u8981\u65b9\u5219\u4f1a\u5c06\u652f\u6301\u5747\u5206\u3002\u53ea\u6709\u5f53\u4e3b\u8981\u65b9\u63a5\u8fd1\u670b\u53cb\u4e14\u5404\u653f\u515a\u5bf9\u6743\u529b\u7684\u91cd\u89c6\u7a0b\u5ea6\u8f83\u4f4e\u65f6\uff0c\u627f\u8bfa\u624d\u80fd\u4e3a\u4e3b\u8981\u65b9\u5e26\u6765\u5229\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.08333", "journal": "MS", "title": "Small Business Judging Judges", "authors": ["Mehmet I. Canayaz", "Matthew T. Gustafson"], "author_details": [{"name": "Mehmet I. Canayaz", "affiliations": ["Carl H. Lindner College of Business, University of Cincinnati, Cincinnati, Ohio 45221"]}, {"name": "Matthew T. Gustafson", "affiliations": ["Smeal College of Business, The Pennsylvania State University, University Park, Pennsylvania 16802"]}], "abstract": "We find that shifts toward more liberal (i.e., less probusiness) courts predict reductions in local small business activity. A one-standard-deviation increase in liberal ideology predicts a 1% reduction in firm count relative to bordering counties in different federal court jurisdictions. This effect has more than doubled since 2000 and is particularly pronounced in circuit-years with elevated small business\u2013related federal cases or public attention to the legal environment. The effect manifests predominantly through the exit of young firms, not firm relocations, and coincides with a shift away from litigation-sensitive industries. In summary, we provide the first evidence that small businesses consider judicial ideology, and the accompanying variation in expected litigation costs, when deciding whether or where to operate.", "date": "2026-08-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08333", "title_zh": "\u4e2d\u5c0f\u4f01\u4e1a\u8bc4\u5224\u6cd5\u5b98", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u6cd5\u9662\u7acb\u573a\u53d8\u5f97\u66f4\u52a0\u81ea\u7531\u4e3b\u4e49\uff08\u5373\u66f4\u4e0d\u5229\u4e8e\u4f01\u4e1a\uff09\u7684\u8d8b\u52bf\u9884\u793a\u7740\u5f53\u5730\u4e2d\u5c0f\u4f01\u4e1a\u6d3b\u52a8\u7684\u51cf\u5c11\u3002\u5728\u4e0d\u540c\u8054\u90a6\u6cd5\u9662\u53f8\u6cd5\u8f96\u533a\u4e2d\uff0c\u610f\u8bc6\u5f62\u6001\u81ea\u7531\u4e3b\u4e49\u7a0b\u5ea6\u589e\u52a0\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u76f8\u5bf9\u4e8e\u90bb\u8fd1\u53bf\u7684\u4e2d\u5c0f\u4f01\u4e1a\u6570\u91cf\u4f1a\u51cf\u5c111%\u3002\u8fd9\u4e00\u6548\u5e94\u81ea2000\u5e74\u4ee5\u6765\u5df2\u8d85\u8fc7\u7ffb\u500d\uff0c\u4e14\u5728\u8054\u90a6\u6cd5\u9662\u6848\u4ef6\u6570\u91cf\u8f83\u591a\u6216\u516c\u4f17\u5bf9\u6cd5\u5f8b\u73af\u5883\u5173\u6ce8\u5ea6\u8f83\u9ad8\u7684\u5de1\u56de\u5e74\u4efd\u4e2d\u5c24\u4e3a\u663e\u8457\u3002\u8be5\u6548\u5e94\u4e3b\u8981\u8868\u73b0\u4e3a\u5e74\u8f7b\u4f01\u4e1a\u7684\u9000\u51fa\uff0c\u800c\u975e\u4f01\u4e1a\u8fc1\u79fb\uff0c\u5e76\u4f34\u968f\u5bf9\u8bc9\u8bbc\u654f\u611f\u884c\u4e1a\u7684\u51cf\u5c11\u3002\u603b\u4e4b\uff0c\u6211\u4eec\u9996\u6b21\u63d0\u4f9b\u4e86\u8bc1\u636e\u8868\u660e\uff0c\u4e2d\u5c0f\u4f01\u4e1a\u5728\u51b3\u5b9a\u662f\u5426\u4ee5\u53ca\u5728\u4f55\u5904\u7ecf\u8425\u65f6\uff0c\u4f1a\u8003\u8651\u53f8\u6cd5\u7406\u5ff5\u53ca\u5176\u5e26\u6765\u7684\u9884\u671f\u8bc9\u8bbc\u6210\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.08448", "journal": "MS", "title": "The Impact of Relative Performance Information on Employees\u2019 Persistence in Voluntary Training", "authors": ["Philip Autenrieth", "Christoph Feichter", "Mischa Seiter", "Markus Wabnegg"], "author_details": [{"name": "Philip Autenrieth", "affiliations": ["Institute of Business Analytics, Ulm University, 89081 Ulm, Germany"]}, {"name": "Christoph Feichter", "affiliations": ["Institute for Strategy and Managerial Accounting, Vienna University of Economics and Business, 1020 Vienna, Austria"]}, {"name": "Mischa Seiter", "affiliations": ["Institute of Business Analytics, Ulm University, 89081 Ulm, Germany"]}, {"name": "Markus Wabnegg", "affiliations": ["Department for Management and Economics, University for Continuing Education Krems, 3500 Krems, Austria"]}], "abstract": "Firms increasingly rely on voluntary training programs to enhance employees\u2019 skills, yet such initiatives often suffer from high dropout rates. We investigate whether providing employees with information about their relative training performance affects their persistence in voluntary training. Social comparison theory suggests that relative performance information (RPI) addresses employees\u2019 inherent need to assess their ability relative to others and maintain a positive self-image by improving their standing. However, whether RPI on training performance is sufficient to increase persistence in voluntary training in the field is unclear. Besides particularly low barriers for dropping out, voluntary training is typically noncore to employees\u2019 primary tasks and often lacks a meaningful comparison group because participants come from a large, heterogeneous, and largely anonymous pool of employees. This calls into question whether the conditions required for social comparison mechanisms are sufficiently met for RPI to take effect. We study this question using a field experiment in a firm offering a voluntary online training program. During the training, employees either receive RPI about their training performance relative to others or only their own performance score. We show that RPI significantly increases employees\u2019 persistence in the training. Consistent with our proposed theoretical mechanism, this effect is particularly pronounced for more competitive individuals. We further find that the likelihood of completing the training is higher and people return to the training quicker if they receive RPI. Our study highlights a simple and cost-effective way to enhance the effectiveness of voluntary training.", "date": "2026-08-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08448", "title_zh": "\u76f8\u5bf9\u7ee9\u6548\u4fe1\u606f\u5bf9\u5458\u5de5\u53c2\u4e0e\u81ea\u613f\u57f9\u8bad\u6301\u7eed\u6027\u7684\u5f71\u54cd", "abstract_zh": "\u4f01\u4e1a\u8d8a\u6765\u8d8a\u4f9d\u8d56\u81ea\u613f\u57f9\u8bad\u9879\u76ee\u6765\u63d0\u5347\u5458\u5de5\u6280\u80fd\uff0c\u4f46\u6b64\u7c7b\u9879\u76ee\u5f80\u5f80\u9762\u4e34\u8f83\u9ad8\u7684\u9000\u51fa\u7387\u3002\u672c\u6587\u7814\u7a76\u4e86\u5411\u5458\u5de5\u63d0\u4f9b\u5173\u4e8e\u5176\u76f8\u5bf9\u57f9\u8bad\u8868\u73b0\u7684\u4fe1\u606f\u662f\u5426\u80fd\u63d0\u9ad8\u5176\u5728\u81ea\u613f\u57f9\u8bad\u4e2d\u7684\u6301\u7eed\u53c2\u4e0e\u5ea6\u3002\u793e\u4f1a\u6bd4\u8f83\u7406\u8bba\u8ba4\u4e3a\uff0c\u76f8\u5bf9\u7ee9\u6548\u4fe1\u606f\uff08RPI\uff09\u80fd\u591f\u6ee1\u8db3\u5458\u5de5\u8bc4\u4f30\u81ea\u8eab\u80fd\u529b\u76f8\u5bf9\u4e8e\u4ed6\u4eba\u5e76\u7ef4\u6301\u79ef\u6781\u81ea\u6211\u5f62\u8c61\u7684\u9700\u6c42\uff0c\u4ece\u800c\u63d0\u5347\u5176\u5730\u4f4d\u3002\u7136\u800c\uff0c\u8fd9\u79cd\u76f8\u5bf9\u7ee9\u6548\u4fe1\u606f\u5728\u5b9e\u9645\u73af\u5883\u4e2d\u662f\u5426\u8db3\u4ee5\u63d0\u9ad8\u5458\u5de5\u5728\u81ea\u613f\u57f9\u8bad\u4e2d\u7684\u6301\u7eed\u53c2\u4e0e\u5ea6\u4ecd\u4e0d\u660e\u786e\u3002\u6b64\u5916\uff0c\u81ea\u613f\u57f9\u8bad\u901a\u5e38\u9000\u51fa\u95e8\u69db\u8f83\u4f4e\uff0c\u4e14\u5f80\u5f80\u4e0d\u662f\u5458\u5de5\u4e3b\u8981\u4efb\u52a1\u7684\u4e00\u90e8\u5206\uff0c\u540c\u65f6\u7531\u4e8e\u53c2\u4e0e\u8005\u6765\u81ea\u4e00\u4e2a\u89c4\u6a21\u5e9e\u5927\u3001\u5f02\u8d28\u6027\u5f3a\u4e14\u57fa\u672c\u533f\u540d\u7684\u5458\u5de5\u7fa4\u4f53\uff0c\u7f3a\u4e4f\u6709\u610f\u4e49\u7684\u6bd4\u8f83\u7fa4\u4f53\u3002\u8fd9\u4f7f\u5f97\u793e\u4f1a\u6bd4\u8f83\u673a\u5236\u6240\u4f9d\u8d56\u7684\u6761\u4ef6\u662f\u5426\u5145\u5206\u5b58\u5728\u7591\u95ee\u3002\u6211\u4eec\u901a\u8fc7\u4e00\u5bb6\u63d0\u4f9b\u81ea\u613f\u5728\u7ebf\u57f9\u8bad\u9879\u76ee\u7684\u4f01\u4e1a\u7684\u5b9e\u5730\u5b9e\u9a8c\u6765\u7814\u7a76\u8fd9\u4e00\u95ee\u9898\u3002\u5728\u57f9\u8bad\u8fc7\u7a0b\u4e2d\uff0c\u5458\u5de5\u8981\u4e48\u83b7\u5f97\u5173\u4e8e\u5176\u76f8\u5bf9\u4e8e\u4ed6\u4eba\u7684\u57f9\u8bad\u8868\u73b0\u7684\u76f8\u5bf9\u7ee9\u6548\u4fe1\u606f\uff08RPI\uff09\uff0c\u8981\u4e48\u4ec5\u83b7\u5f97\u81ea\u5df1\u7684\u4e2a\u4eba\u8868\u73b0\u8bc4\u5206\u3002\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u76f8\u5bf9\u7ee9\u6548\u4fe1\u606f\u663e\u8457\u63d0\u9ad8\u4e86\u5458\u5de5\u5728\u57f9\u8bad\u4e2d\u7684\u6301\u7eed\u53c2\u4e0e\u5ea6\u3002\u4e0e\u6211\u4eec\u63d0\u51fa\u7684\u7406\u8bba\u673a\u5236\u4e00\u81f4\uff0c\u8fd9\u4e00\u6548\u5e94\u5728\u66f4\u5177\u7ade\u4e89\u6027\u7684\u4e2a\u4f53\u4e2d\u5c24\u4e3a\u660e\u663e\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0c\u83b7\u5f97\u76f8\u5bf9\u7ee9\u6548\u4fe1\u606f\u7684\u5458\u5de5\u5b8c\u6210\u57f9\u8bad\u7684\u53ef\u80fd\u6027\u66f4\u9ad8\uff0c\u5e76\u4e14\u5728\u8fd4\u56de\u57f9\u8bad\u65f6\u4e5f\u66f4\u8fc5\u901f\u3002\u672c\u7814\u7a76\u5f3a\u8c03\u4e86\u4e00\u79cd\u7b80\u5355\u4e14\u6210\u672c\u6548\u76ca\u9ad8\u7684\u65b9\u6cd5\uff0c\u53ef\u7528\u4e8e\u63d0\u5347\u81ea\u613f\u57f9\u8bad\u7684\u6709\u6548\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.02505", "journal": "MS", "title": "Realized Illiquidity", "authors": ["Demetrio Lacava", "Angelo Ranaldo", "Paolo Santucci de Magistris"], "author_details": [{"name": "Demetrio Lacava", "affiliations": ["Department of Economics, University of Messina, 98122 Messina, Italy"]}, {"name": "Angelo Ranaldo", "affiliations": ["University of Basel and Swiss Finance Institute, 4002 Basel, Switzerland"]}, {"name": "Paolo Santucci de Magistris", "affiliations": ["Department of Economics and Financial Markets, Luiss University, 00197 Roma, Italy"]}], "abstract": "We develop a simple theory of realized illiquidity, defined as the ratio of realized volatility to trading volume. Building on the widely used price impact measure of Amihud (2002), we introduce the realized Amihud, which significantly improves measurement accuracy. Our theoretical and numerical results show that it robustly captures cumulative intraday price sensitivity to trading, accounting for stochastic volatility, microstructure noise, and information jumps. Empirically, we uncover distinct time-series patterns in realized stock illiquidity\u2014heterogeneous clustering, leverage effects\u2014and show that it predicts short-term returns.", "date": "2026-08-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.02505", "title_zh": "\u5b9e\u9645\u975e\u6d41\u52a8\u6027", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u7b80\u5355\u7684\u5b9e\u9645\u975e\u6d41\u52a8\u6027\u7406\u8bba\uff0c\u5b9e\u9645\u975e\u6d41\u52a8\u6027\u5b9a\u4e49\u4e3a\u5b9e\u9645\u6ce2\u52a8\u7387\u4e0e\u4ea4\u6613\u91cf\u7684\u6bd4\u503c\u3002\u57fa\u4e8eAmihud\uff082002\uff09\u5e7f\u6cdb\u4f7f\u7528\u7684\u4ef7\u683c\u5f71\u54cd\u5ea6\u91cf\u65b9\u6cd5\uff0c\u6211\u4eec\u5f15\u5165\u4e86\u5b9e\u9645Amihud\uff0c\u663e\u8457\u63d0\u5347\u4e86\u6d4b\u91cf\u7cbe\u5ea6\u3002\u6211\u4eec\u7684\u7406\u8bba\u548c\u6570\u503c\u7ed3\u679c\u8868\u660e\uff0c\u5b83\u7a33\u5065\u5730\u6355\u6349\u4e86\u65e5\u5185\u4ef7\u683c\u5bf9\u4ea4\u6613\u7684\u7d2f\u79ef\u654f\u611f\u6027\uff0c\u8003\u8651\u4e86\u968f\u673a\u6ce2\u52a8\u7387\u3001\u5fae\u89c2\u7ed3\u6784\u566a\u58f0\u4ee5\u53ca\u4fe1\u606f\u8df3\u8dc3\u3002\u5b9e\u8bc1\u4e0a\uff0c\u6211\u4eec\u53d1\u73b0\u4e86\u80a1\u7968\u5b9e\u9645\u975e\u6d41\u52a8\u6027\u7684\u65f6\u95f4\u5e8f\u5217\u6a21\u5f0f\u2014\u2014\u5f02\u8d28\u6027\u805a\u7c7b\u548c\u6760\u6746\u6548\u5e94\uff0c\u5e76\u8bc1\u660e\u5176\u80fd\u591f\u9884\u6d4b\u77ed\u671f\u6536\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag086", "journal": "REStud", "title": "How You Pay Drives What You Choose: Mental Accounting in Health Insurance Plan Choice", "authors": ["Jonathan Gruber", "Mengyun Lin", "Haoming Liu", "Junjian Yi"], "author_details": [{"name": "Jonathan Gruber", "affiliations": ["MIT and NBER ,"]}, {"name": "Mengyun Lin", "affiliations": ["Xiamen University ,"]}, {"name": "Haoming Liu", "affiliations": ["National University of Singapore ,"]}, {"name": "Junjian Yi", "affiliations": ["Peking University ,"]}], "abstract": "Abstract We document that the source of funds for paying health insurance premiums has a dramatic impact on plan choices. We focus on the MediSave programme in Singapore, a medical savings account that is used to pay out-of-pocket medical spending. Residents can also pay their health insurance premiums with cash or MediSave funds, but are subject to limits that vary by age and over time. By exploiting variations in those limits, we consistently find that when individuals are able to pay their health insurance premiums with MediSave funds, they are less price sensitive and more willing to enrol in more generous plans. We develop and estimate a mental accounting model which explains these patterns. We embed and reject alternative explanations such as hassle costs and liquidity constraints. We then extend this model and show that mental accounting can explain much, but not all, of the misweighting of premiums relative to out-of-pocket expenses in health insurance choice. We also find that allowing MediSave payment for both premiums and out-of-pocket expenses (e.g. putting them in the same mental account) enhances individual welfare and reduces adverse selection.", "date": "2026-08-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag086", "title_zh": "\u4f60\u5982\u4f55\u4ed8\u6b3e\u51b3\u5b9a\u4e86\u4f60\u7684\u9009\u62e9\uff1a\u5065\u5eb7\u4fdd\u9669\u8ba1\u5212\u9009\u62e9\u4e2d\u7684\u5fc3\u7406\u8d26\u6237", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u652f\u4ed8\u5065\u5eb7\u4fdd\u9669\u4fdd\u8d39\u7684\u8d44\u91d1\u6765\u6e90\u5bf9\u8ba1\u5212\u9009\u62e9\u5177\u6709\u663e\u8457\u5f71\u54cd\u3002\u6211\u4eec\u4ee5\u65b0\u52a0\u5761\u7684MediSave\u8ba1\u5212\u4e3a\u7814\u7a76\u5bf9\u8c61\uff0c\u8be5\u8ba1\u5212\u662f\u4e00\u79cd\u7528\u4e8e\u652f\u4ed8\u81ea\u4ed8\u533b\u7597\u652f\u51fa\u7684\u533b\u7597\u50a8\u84c4\u8d26\u6237\u3002\u5c45\u6c11\u53ef\u4ee5\u4f7f\u7528\u73b0\u91d1\u6216MediSave\u8d44\u91d1\u652f\u4ed8\u5065\u5eb7\u4fdd\u9669\u4fdd\u8d39\uff0c\u4f46\u4f1a\u53d7\u5230\u6839\u636e\u5e74\u9f84\u548c\u65f6\u95f4\u53d8\u5316\u7684\u9650\u5236\u3002\u901a\u8fc7\u5229\u7528\u8fd9\u4e9b\u9650\u5236\u7684\u5dee\u5f02\uff0c\u6211\u4eec\u4e00\u81f4\u53d1\u73b0\uff0c\u5f53\u4e2a\u4eba\u80fd\u591f\u4f7f\u7528MediSave\u8d44\u91d1\u652f\u4ed8\u5065\u5eb7\u4fdd\u9669\u4fdd\u8d39\u65f6\uff0c\u4ed6\u4eec\u5bf9\u4ef7\u683c\u7684\u654f\u611f\u6027\u964d\u4f4e\uff0c\u66f4\u613f\u610f\u9009\u62e9\u66f4\u4e3a\u6177\u6168\u7684\u4fdd\u9669\u8ba1\u5212\u3002\u6211\u4eec\u6784\u5efa\u5e76\u4f30\u8ba1\u4e86\u4e00\u4e2a\u5fc3\u7406\u8d26\u6237\u6a21\u578b\uff0c\u4ee5\u89e3\u91ca\u8fd9\u4e9b\u73b0\u8c61\u3002\u8be5\u6a21\u578b\u5d4c\u5165\u5e76\u6392\u9664\u4e86\u8bf8\u5982\u64cd\u4f5c\u6210\u672c\u548c\u6d41\u52a8\u6027\u7ea6\u675f\u7b49\u66ff\u4ee3\u6027\u89e3\u91ca\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u6269\u5c55\u8be5\u6a21\u578b\uff0c\u8868\u660e\u5fc3\u7406\u8d26\u6237\u53ef\u4ee5\u89e3\u91ca\u5065\u5eb7\u4fdd\u9669\u9009\u62e9\u4e2d\u4fdd\u8d39\u4e0e\u81ea\u4ed8\u652f\u51fa\u4e4b\u95f4\u6743\u91cd\u5931\u8861\u7684\u5927\u90e8\u5206\uff0c\u4f46\u5e76\u975e\u5168\u90e8\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0c\u5141\u8bb8\u4f7f\u7528MediSave\u8d44\u91d1\u540c\u65f6\u652f\u4ed8\u4fdd\u8d39\u548c\u81ea\u4ed8\u652f\u51fa\uff08\u4f8b\u5982\uff0c\u5c06\u4e24\u8005\u7f6e\u4e8e\u540c\u4e00\u5fc3\u7406\u8d26\u6237\u4e2d\uff09\u80fd\u591f\u63d0\u5347\u4e2a\u4eba\u798f\u5229\uff0c\u5e76\u51cf\u5c11\u9006\u5411\u9009\u62e9\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70068", "journal": "JF", "title": "Sequential Search for Corporate Bonds", "authors": ["MAHYAR KARGAR", "BENJAMIN LESTER", "S\u00c9BASTIEN PLANTE", "PIERRE\u2010OLIVIER WEILL"], "author_details": [{"name": "MAHYAR KARGAR", "affiliations": []}, {"name": "BENJAMIN LESTER", "affiliations": []}, {"name": "S\u00c9BASTIEN PLANTE", "affiliations": []}, {"name": "PIERRE\u2010OLIVIER WEILL", "affiliations": []}], "abstract": "ABSTRACT Customers in over\u2010the\u2010counter (OTC) markets must find a counterparty to trade. Little is known about this process, however, because existing data consist of transaction records, which only reveal the outcome of a search. Using data from a trading platform for corporate bonds, we unpack the search process. We analyze how long it takes customers to trade and how dealers' offers evolve across repeated inquiries. We estimate that it takes two to three days to complete a transaction after an unsuccessful attempt, with substantial variation across trade and customer characteristics. Our analysis offers insights into the sources of trading delays in OTC markets.", "date": "2026-08-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70068", "title_zh": "\u4f01\u4e1a\u503a\u5238\u7684\u987a\u5e8f\u641c\u7d22", "abstract_zh": "\u6458\u8981 \u5728\u573a\u5916\u5e02\u573a\uff08OTC\uff09\u4e2d\uff0c\u5ba2\u6237\u5fc5\u987b\u627e\u5230\u4ea4\u6613\u5bf9\u624b\u65b9\u3002\u7136\u800c\uff0c\u5173\u4e8e\u8fd9\u4e00\u8fc7\u7a0b\u7684\u4e86\u89e3\u4ecd\u7136\u5f88\u5c11\uff0c\u56e0\u4e3a\u73b0\u6709\u6570\u636e\u4ec5\u5305\u542b\u4ea4\u6613\u8bb0\u5f55\uff0c\u8fd9\u4e9b\u8bb0\u5f55\u53ea\u80fd\u53cd\u6620\u641c\u7d22\u7684\u7ed3\u679c\u3002\u5229\u7528\u4e00\u4e2a\u4f01\u4e1a\u503a\u5238\u4ea4\u6613\u5e73\u53f0\u7684\u6570\u636e\uff0c\u6211\u4eec\u62c6\u89e3\u4e86\u641c\u7d22\u8fc7\u7a0b\u3002\u6211\u4eec\u5206\u6790\u4e86\u5ba2\u6237\u5b8c\u6210\u4ea4\u6613\u6240\u9700\u7684\u65f6\u95f4\uff0c\u4ee5\u53ca\u5728\u591a\u6b21\u67e5\u8be2\u4e2d\u4ea4\u6613\u5546\u62a5\u4ef7\u7684\u53d8\u5316\u60c5\u51b5\u3002\u6211\u4eec\u7684\u5206\u6790\u8868\u660e\uff0c\u4e00\u6b21\u5931\u8d25\u5c1d\u8bd5\u540e\uff0c\u5b8c\u6210\u4ea4\u6613\u901a\u5e38\u9700\u8981\u4e24\u5929\u5230\u4e09\u5929\uff0c\u4e14\u5728\u4e0d\u540c\u4ea4\u6613\u548c\u5ba2\u6237\u7279\u5f81\u4e4b\u95f4\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002\u672c\u7814\u7a76\u4e3a\u7406\u89e3\u573a\u5916\u5e02\u573a\u4e2d\u7684\u4ea4\u6613\u5ef6\u8fdf\u63d0\u4f9b\u4e86\u65b0\u7684\u89c1\u89e3\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.06339", "journal": "MS", "title": "When Consumer Financial Protection Spills Over: Student Loan Borrowing Under the CARD Act", "authors": ["Alexander L. Brown", "Daniel Grodzicki", "Paolina C. Medina"], "author_details": [{"name": "Alexander L. Brown", "affiliations": ["Department of Economics, Texas A&M University, College Station, Texas 77843"]}, {"name": "Daniel Grodzicki", "affiliations": ["Bank Policy Institute, Washington, District of Columbia 20005"]}, {"name": "Paolina C. Medina", "affiliations": ["Department of Finance, C.T. Bauer College of Business, University of Houston, Houston, Texas 77204"]}], "abstract": "Credit card use among college students declined sharply following the enactment of the Credit Card Accountability, Responsibility, and Disclosure Act of 2009. Title 3, Section 304 of the Act specifically restricted the marketing and sale of credit cards on college campuses. Using a difference-in-differences approach that treats incoming freshmen who would have been unaffected by this marketing as the control group, we document an apparent spillover that increased student loan borrowing by 8.4%, and by 14% for less affluent students. A survey of students matched to their administrative records finds evidence of this substitutability between credit cards and student loans; further, it reveals that a lack of financial literacy and knowledge of financial history are correlated with the misallocation of debt between them. Using these combined empirical findings, we develop and calibrate a model of optimal student borrowing to assess the benefits of the spillovers and find the policy increased welfare. A complementary analysis indicates improvements in grade point averages and on-time graduation rates subsequent to the Act.", "date": "2026-08-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.06339", "title_zh": "\u6d88\u8d39\u8005\u91d1\u878d\u4fdd\u62a4\u7684\u6ea2\u51fa\u6548\u5e94\uff1a\u5361\u5fb7\u6cd5\u6848\u4e0b\u7684\u5b66\u751f\u8d37\u6b3e\u501f\u8d37", "abstract_zh": "2009\u5e74\u300a\u4fe1\u7528\u5361\u95ee\u8d23\u3001\u8d23\u4efb\u4e0e\u62ab\u9732\u6cd5\u6848\u300b\uff08CARD Act\uff09\u5b9e\u65bd\u540e\uff0c\u5927\u5b66\u751f\u7684\u4fe1\u7528\u5361\u4f7f\u7528\u663e\u8457\u4e0b\u964d\u3002\u8be5\u6cd5\u6848\u7b2c\u4e09\u7ae0\u7b2c304\u6761\u7279\u522b\u9650\u5236\u4e86\u5728\u5927\u5b66\u6821\u56ed\u5185\u4fe1\u7528\u5361\u7684\u8425\u9500\u548c\u9500\u552e\u3002\u6211\u4eec\u91c7\u7528\u5dee\u5206-\u5dee\u5206\u65b9\u6cd5\uff0c\u5c06\u90a3\u4e9b\u672c\u4e0d\u4f1a\u53d7\u5230\u8be5\u8425\u9500\u5f71\u54cd\u7684\u65b0\u751f\u4f5c\u4e3a\u5bf9\u7167\u7ec4\uff0c\u53d1\u73b0\u5b58\u5728\u4e00\u79cd\u6ea2\u51fa\u6548\u5e94\uff0c\u5bfc\u81f4\u5b66\u751f\u8d37\u6b3e\u501f\u8d37\u589e\u52a0\u4e868.4%\uff0c\u5bf9\u4e8e\u7ecf\u6d4e\u72b6\u51b5\u8f83\u5dee\u7684\u5b66\u751f\uff0c\u8fd9\u4e00\u589e\u5e45\u8fbe\u523014%\u3002\u4e00\u9879\u5339\u914d\u5b66\u751f\u8c03\u67e5\u6570\u636e\u4e0e\u884c\u653f\u8bb0\u5f55\u7684\u7814\u7a76\u53d1\u73b0\uff0c\u4fe1\u7528\u5361\u4e0e\u5b66\u751f\u8d37\u6b3e\u4e4b\u95f4\u5b58\u5728\u53ef\u66ff\u4ee3\u6027\uff1b\u6b64\u5916\uff0c\u7814\u7a76\u8fd8\u53d1\u73b0\uff0c\u91d1\u878d\u7d20\u517b\u7f3a\u4e4f\u4ee5\u53ca\u5bf9\u91d1\u878d\u5386\u53f2\u77e5\u8bc6\u7684\u6b20\u7f3a\uff0c\u4e0e\u5b66\u751f\u5728\u4e24\u8005\u4e4b\u95f4\u9519\u8bef\u5206\u914d\u503a\u52a1\u5bc6\u5207\u76f8\u5173\u3002\u57fa\u4e8e\u8fd9\u4e9b\u7efc\u5408\u5b9e\u8bc1\u53d1\u73b0\uff0c\u6211\u4eec\u6784\u5efa\u5e76\u6821\u51c6\u4e86\u4e00\u4e2a\u6700\u4f18\u5b66\u751f\u501f\u8d37\u6a21\u578b\uff0c\u4ee5\u8bc4\u4f30\u6ea2\u51fa\u6548\u5e94\u5e26\u6765\u7684\u798f\u5229\u63d0\u5347\uff0c\u7ed3\u679c\u8868\u660e\u8be5\u653f\u7b56\u63d0\u5347\u4e86\u6574\u4f53\u798f\u5229\u3002\u4e00\u9879\u8865\u5145\u5206\u6790\u663e\u793a\uff0c\u6cd5\u6848\u5b9e\u65bd\u540e\uff0c\u5b66\u751f\u7684\u5e73\u5747\u7ee9\u70b9\u548c\u6309\u65f6\u6bd5\u4e1a\u7387\u5747\u6709\u6240\u6539\u5584\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.08235", "journal": "MS", "title": "Design-Based Confidence Sequences: A General Approach to Risk Mitigation in Panel Experiments", "authors": ["Dae Woong Ham", "Michael Lindon", "Martin Tingley", "Iavor Bojinov"], "author_details": [{"name": "Dae Woong Ham", "affiliations": ["Ross Business School, University of Michigan, Ann Arbor, Michigan 48109"]}, {"name": "Michael Lindon", "affiliations": ["Netflix, Los Gatos, California 95032"]}, {"name": "Martin Tingley", "affiliations": ["Netflix, Los Gatos, California 95032"]}, {"name": "Iavor Bojinov", "affiliations": ["Harvard Business School, Harvard University, Boston, Massachusetts 02163"]}], "abstract": "Randomized experiments have become the standard method for companies to evaluate the performance of new products or services. Beyond aiding managerial decision making, experiments mitigate risk by limiting the proportion of customers exposed to innovations. Because many experiments are conducted sequentially over time, an emerging strategy to further derisk the process is to allow managers to \u201cpeek\u201d at the results as new data become available and stop the test if the results are statistically significant. The class of statistical methods that allow managers to peek and still provide valid inference are often called anytime valid because they maintain proper uniform type 1 error guarantees. In this paper, we extend existing anytime-valid approaches to accommodate the more complex yet standard settings in time series, switchback, and panel experiments. To achieve this, we leverage the design-based approach to focus on assumption-light and managerially relevant finite-sample estimands defined on the study participants as a direct measure of the risks incurred by companies. As a special case, our (asymptotic) results also provide a robust method for achieving always-valid inference in A/B tests. We further provide a variance reduction technique incorporating modeling assumptions and covariates. Finally, we demonstrate the effectiveness of our proposed approach through a simulation study and three real-world applications from Netflix. Our results show that using our confidence sequence, harmful experiments could be stopped after observing only a handful of units; for instance, our method would have stopped a 30,000-person Netflix experiment after the first 100 people.", "date": "2026-08-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08235", "title_zh": "\u57fa\u4e8e\u8bbe\u8ba1\u7684\u7f6e\u4fe1\u5e8f\u5217\uff1a\u9762\u677f\u5b9e\u9a8c\u4e2d\u98ce\u9669\u63a7\u5236\u7684\u901a\u7528\u65b9\u6cd5", "abstract_zh": "\u968f\u673a\u5b9e\u9a8c\u5df2\u6210\u4e3a\u4f01\u4e1a\u8bc4\u4f30\u65b0\u4ea7\u54c1\u6216\u670d\u52a1\u8868\u73b0\u7684\u6807\u51c6\u65b9\u6cd5\u3002\u9664\u4e86\u8f85\u52a9\u7ba1\u7406\u5c42\u51b3\u7b56\u5916\uff0c\u5b9e\u9a8c\u901a\u8fc7\u9650\u5236\u63a5\u89e6\u521b\u65b0\u7684\u5ba2\u6237\u6bd4\u4f8b\u6765\u964d\u4f4e\u98ce\u9669\u3002\u7531\u4e8e\u8bb8\u591a\u5b9e\u9a8c\u662f\u6309\u65f6\u95f4\u987a\u5e8f\u8fdb\u884c\u7684\uff0c\u4e00\u79cd\u65b0\u5174\u7b56\u7565\u662f\u5141\u8bb8\u7ba1\u7406\u8005\u5728\u65b0\u6570\u636e\u51fa\u73b0\u65f6\u201c\u67e5\u770b\u201d\u5b9e\u9a8c\u7ed3\u679c\uff0c\u5e76\u5728\u7ed3\u679c\u5177\u6709\u7edf\u8ba1\u663e\u8457\u6027\u65f6\u63d0\u524d\u7ec8\u6b62\u5b9e\u9a8c\u3002\u80fd\u591f\u5b9e\u73b0\u8fd9\u79cd\u201c\u67e5\u770b\u201d\u529f\u80fd\u4e14\u4ecd\u80fd\u63d0\u4f9b\u6709\u6548\u63a8\u65ad\u7684\u7edf\u8ba1\u65b9\u6cd5\u901a\u5e38\u88ab\u79f0\u4e3a\u201c\u968f\u65f6\u6709\u6548\u201d\uff0c\u56e0\u4e3a\u5b83\u4eec\u80fd\u4fdd\u6301\u7edf\u4e00\u7684\u4e00\u7c7b\u9519\u8bef\u63a7\u5236\u3002\u672c\u6587\u6269\u5c55\u4e86\u73b0\u6709\u7684\u968f\u65f6\u6709\u6548\u65b9\u6cd5\uff0c\u4ee5\u9002\u5e94\u65f6\u95f4\u5e8f\u5217\u3001\u5207\u6362\u56de\u9000\u548c\u9762\u677f\u5b9e\u9a8c\u4e2d\u66f4\u4e3a\u590d\u6742\u4f46\u5e38\u89c1\u7684\u8bbe\u7f6e\u3002\u4e3a\u6b64\uff0c\u6211\u4eec\u91c7\u7528\u57fa\u4e8e\u8bbe\u8ba1\u7684\u65b9\u6cd5\uff0c\u805a\u7126\u4e8e\u8f7b\u5047\u8bbe\u3001\u5bf9\u7ba1\u7406\u5c42\u5177\u6709\u5b9e\u9645\u610f\u4e49\u7684\u6709\u9650\u6837\u672c\u4f30\u8ba1\u91cf\uff0c\u8fd9\u4e9b\u4f30\u8ba1\u91cf\u76f4\u63a5\u8861\u91cf\u4f01\u4e1a\u6240\u627f\u62c5\u7684\u98ce\u9669\u3002\u4f5c\u4e3a\u7279\u6b8a\u60c5\u51b5\uff0c\u6211\u4eec\u7684\uff08\u6e10\u8fd1\uff09\u7ed3\u679c\u4e5f\u63d0\u4f9b\u4e86\u4e00\u79cd\u5728A/B\u6d4b\u8bd5\u4e2d\u5b9e\u73b0\u59cb\u7ec8\u6709\u6548\u63a8\u65ad\u7684\u7a33\u5065\u65b9\u6cd5\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u63d0\u51fa\u4e86\u4e00\u79cd\u7ed3\u5408\u5efa\u6a21\u5047\u8bbe\u548c\u534f\u53d8\u91cf\u7684\u65b9\u5dee\u7f29\u51cf\u6280\u672f\u3002\u6700\u540e\uff0c\u6211\u4eec\u901a\u8fc7\u6a21\u62df\u7814\u7a76\u548c\u6765\u81eaNetflix\u7684\u4e09\u4e2a\u5b9e\u9645\u5e94\u7528\uff0c\u5c55\u793a\u4e86\u6240\u63d0\u51fa\u65b9\u6cd5\u7684\u6709\u6548\u6027\u3002\u7ed3\u679c\u8868\u660e\uff0c\u4f7f\u7528\u6211\u4eec\u7684\u7f6e\u4fe1\u5e8f\u5217\uff0c\u6709\u5bb3\u5b9e\u9a8c\u53ef\u4ee5\u5728\u89c2\u5bdf\u5230\u5c11\u6570\u5355\u4f4d\u6570\u636e\u540e\u5373\u88ab\u7ec8\u6b62\uff1b\u4f8b\u5982\uff0c\u6211\u4eec\u7684\u65b9\u6cd5\u4f1a\u5728Netflix\u4e00\u4e2a\u6d89\u53ca3\u4e07\u4eba\u7684\u5b9e\u9a8c\u4e2d\uff0c\u4ec5\u5728\u524d100\u540d\u7528\u6237\u6570\u636e\u51fa\u73b0\u540e\u5c31\u7ec8\u6b62\u8be5\u5b9e\u9a8c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.07930", "journal": "MS", "title": "The Impact of Manipulated Clinical Decision Support Algorithm on Opioid Prescribing Decision", "authors": ["Xuelin Li", "Meizi Zhou"], "author_details": [{"name": "Xuelin Li", "affiliations": ["Graduate School of Business, Columbia University, New York, New York 10027"]}, {"name": "Meizi Zhou", "affiliations": ["Questrom School of Business, Boston University, Boston, Massachusetts 02215"]}], "abstract": "We document that interactions with manipulated clinical decision support (CDS) systems can induce not only short-term, but also long-term changes in physicians\u2019 opioid prescribing behavior. Physicians in our sample adopted electronic health record software from a list of federally certified vendors in 2011. Between 2016 and Spring 2019, one vendor secretly embedded a biased CDS function designed to promote extended-release opioid sales. Affected physicians not only increased opioid claims relative to the control group during the treatment window, but also maintained a higher propensity to prescribe opioids, even after the biased function was removed. This long-term behavioral change persisted even after affected physicians moved to new locations, changed their affiliations, or faced stricter state-level opioid regulations. Increasing physician awareness helped mitigate this impact. Using machine-learning algorithms, we estimate that decision-making distortion accounts for approximately 54% of the treatment effects in a physician decision model with dynamic learning.", "date": "2026-08-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.07930", "title_zh": "manipulated\u4e34\u5e8a\u51b3\u7b56\u652f\u6301\u7b97\u6cd5\u5bf9\u963f\u7247\u7c7b\u836f\u7269\u5904\u65b9\u51b3\u7b56\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u4e0e\u88ab\u64cd\u7eb5\u7684\u4e34\u5e8a\u51b3\u7b56\u652f\u6301\uff08CDS\uff09\u7cfb\u7edf\u4e92\u52a8\u4e0d\u4ec5\u4f1a\u5f15\u53d1\u533b\u751f\u963f\u7247\u7c7b\u836f\u7269\u5904\u65b9\u884c\u4e3a\u7684\u77ed\u671f\u53d8\u5316\uff0c\u8fd8\u4f1a\u5bfc\u81f4\u957f\u671f\u53d8\u5316\u3002\u6837\u672c\u4e2d\u7684\u533b\u751f\u57282011\u5e74\u4ece\u8054\u90a6\u8ba4\u8bc1\u4f9b\u5e94\u5546\u4e2d\u9009\u62e9\u4e86\u7535\u5b50\u5065\u5eb7\u8bb0\u5f55\u8f6f\u4ef6\u30022016\u5e74\u81f32019\u5e74\u6625\u5b63\u671f\u95f4\uff0c\u4e00\u5bb6\u4f9b\u5e94\u5546\u79d8\u5bc6\u5d4c\u5165\u4e86\u4e00\u4e2a\u65e8\u5728\u4fc3\u8fdb\u7f13\u91ca\u963f\u7247\u7c7b\u836f\u7269\u9500\u552e\u7684\u6709\u504f\u89c1\u7684CDS\u529f\u80fd\u3002\u53d7\u5f71\u54cd\u7684\u533b\u751f\u5728\u6cbb\u7597\u671f\u95f4\u4e0d\u4ec5\u76f8\u8f83\u4e8e\u5bf9\u7167\u7ec4\u589e\u52a0\u4e86\u963f\u7247\u7c7b\u836f\u7269\u7684\u7533\u9886\u91cf\uff0c\u800c\u4e14\u5728\u79fb\u9664\u8be5\u6709\u504f\u89c1\u529f\u80fd\u540e\uff0c\u4ecd\u6301\u7eed\u8868\u73b0\u51fa\u66f4\u9ad8\u7684\u963f\u7247\u7c7b\u836f\u7269\u5904\u65b9\u503e\u5411\u3002\u8fd9\u79cd\u957f\u671f\u884c\u4e3a\u6539\u53d8\u5373\u4f7f\u5728\u533b\u751f\u8f6c\u81f3\u65b0\u5730\u533a\u3001\u66f4\u6362\u6240\u5c5e\u673a\u6784\u6216\u9762\u4e34\u66f4\u4e25\u683c\u7684\u5dde\u7ea7\u963f\u7247\u7c7b\u836f\u7269\u76d1\u7ba1\u653f\u7b56\u540e\u4f9d\u7136\u6301\u7eed\u5b58\u5728\u3002\u63d0\u9ad8\u533b\u751f\u7684\u610f\u8bc6\u6709\u52a9\u4e8e\u7f13\u89e3\u8fd9\u4e00\u5f71\u54cd\u3002\u5229\u7528\u673a\u5668\u5b66\u4e60\u7b97\u6cd5\uff0c\u6211\u4eec\u4f30\u8ba1\uff0c\u5728\u4e00\u4e2a\u5177\u6709\u52a8\u6001\u5b66\u4e60\u7684\u533b\u751f\u51b3\u7b56\u6a21\u578b\u4e2d\uff0c\u51b3\u7b56\u8fc7\u7a0b\u7684\u626d\u66f2\u7ea6\u5360\u6cbb\u7597\u6548\u5e94\u768454%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2025.03120", "journal": "MS", "title": "The Diminishing Value of Bundling Under Inventory Scarcity", "authors": ["Tarek Abdallah", "Josh Reed"], "author_details": [{"name": "Tarek Abdallah", "affiliations": ["Operations Department, Kellogg School of Management, Northwestern University, Evanston, Illinois 60208"]}, {"name": "Josh Reed", "affiliations": ["Department of Technology, Operations, and Statistics, Leonard N. Stern School of Business, New York University, New York, New York 10012"]}], "abstract": "We study the impact of inventory constraints on bundling in a dynamic pricing setting, challenging the classical view that bundling consistently enhances revenue. Traditional bundling theory, which typically assumes abundant inventory and static pricing, often asserts that bundling generates higher revenue than selling products individually. However, we show that limited inventory, in fact, distorts the revenue-extraction capability of bundling, favoring the sale of products or services separately. We study the optimal dynamic mixed bundling strategy in a large market regime where the market size grows relative to limited inventory. Leveraging this framework, we derive optimal dynamic pricing policies and value functions for commonly used bundling strategies, including mixed bundling, pure bundling, bundle size pricing, and component pricing. Our analysis reveals that as inventory becomes more constrained relative to market size, the optimal dynamic mixed bundling strategy converges to a dynamic component pricing strategy, outperforming both dynamic bundle size pricing and dynamic pure bundling. Moreover, the performance gap between these strategies increases with the number of items, a factor typically viewed as favoring bundling when inventory is abundant. Notably, our numerical experiments reveal that these structural insights extend to policies derived from the standard fluid regime. As the market size grows relative to the inventory, the dynamic mixed bundling policy obtained by resolving the deterministic fluid problem also reduces to a dynamic component pricing policy.", "date": "2026-08-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.03120", "title_zh": "\u5728\u5e93\u5b58\u77ed\u7f3a\u60c5\u51b5\u4e0b\u6346\u7ed1\u7b56\u7565\u4ef7\u503c\u7684\u9012\u51cf", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5e93\u5b58\u7ea6\u675f\u5bf9\u52a8\u6001\u5b9a\u4ef7\u73af\u5883\u4e0b\u6346\u7ed1\u7b56\u7565\u7684\u5f71\u54cd\uff0c\u6311\u6218\u4e86\u4f20\u7edf\u89c2\u70b9\uff0c\u5373\u6346\u7ed1\u7b56\u7565\u59cb\u7ec8\u80fd\u63d0\u5347\u6536\u76ca\u3002\u4f20\u7edf\u7684\u6346\u7ed1\u7406\u8bba\u901a\u5e38\u5047\u8bbe\u5e93\u5b58\u5145\u8db3\u4e14\u5b9a\u4ef7\u9759\u6001\uff0c\u8ba4\u4e3a\u6346\u7ed1\u9500\u552e\u6bd4\u5355\u72ec\u9500\u552e\u4ea7\u54c1\u80fd\u5e26\u6765\u66f4\u9ad8\u7684\u6536\u76ca\u3002\u7136\u800c\uff0c\u6211\u4eec\u8bc1\u660e\uff0c\u5728\u5e93\u5b58\u6709\u9650\u7684\u60c5\u51b5\u4e0b\uff0c\u6346\u7ed1\u7b56\u7565\u7684\u6536\u76ca\u63d0\u53d6\u80fd\u529b\u5b9e\u9645\u4e0a\u4f1a\u53d7\u5230\u626d\u66f2\uff0c\u66f4\u503e\u5411\u4e8e\u5355\u72ec\u9500\u552e\u4ea7\u54c1\u6216\u670d\u52a1\u3002\u6211\u4eec\u5728\u4e00\u4e2a\u5927\u578b\u5e02\u573a\u73af\u5883\u4e2d\u7814\u7a76\u4e86\u5728\u5e02\u573a\u89c4\u6a21\u76f8\u5bf9\u4e8e\u6709\u9650\u5e93\u5b58\u589e\u957f\u65f6\u7684\u6700\u4f18\u52a8\u6001\u6df7\u5408\u6346\u7ed1\u7b56\u7565\u3002\u57fa\u4e8e\u8fd9\u4e00\u6846\u67b6\uff0c\u6211\u4eec\u63a8\u5bfc\u4e86\u5e38\u7528\u6346\u7ed1\u7b56\u7565\u7684\u6700\u4f18\u52a8\u6001\u5b9a\u4ef7\u653f\u7b56\u548c\u4ef7\u503c\u51fd\u6570\uff0c\u5305\u62ec\u6df7\u5408\u6346\u7ed1\u3001\u7eaf\u6346\u7ed1\u3001\u6346\u7ed1\u6570\u91cf\u5b9a\u4ef7\u4ee5\u53ca\u7ec4\u4ef6\u5b9a\u4ef7\u3002\u6211\u4eec\u7684\u5206\u6790\u8868\u660e\uff0c\u968f\u7740\u5e93\u5b58\u76f8\u5bf9\u4e8e\u5e02\u573a\u89c4\u6a21\u7684\u7ea6\u675f\u7a0b\u5ea6\u589e\u52a0\uff0c\u6700\u4f18\u52a8\u6001\u6df7\u5408\u6346\u7ed1\u7b56\u7565\u4f1a\u6536\u655b\u5230\u4e00\u79cd\u52a8\u6001\u7ec4\u4ef6\u5b9a\u4ef7\u7b56\u7565\uff0c\u5176\u8868\u73b0\u4f18\u4e8e\u52a8\u6001\u6346\u7ed1\u6570\u91cf\u5b9a\u4ef7\u548c\u52a8\u6001\u7eaf\u6346\u7ed1\u7b56\u7565\u3002\u6b64\u5916\uff0c\u968f\u7740\u4ea7\u54c1\u6570\u91cf\u7684\u589e\u52a0\uff0c\u8fd9\u4e9b\u7b56\u7565\u4e4b\u95f4\u7684\u6027\u80fd\u5dee\u8ddd\u4e5f\u6269\u5927\uff0c\u800c\u8fd9\u4e00\u56e0\u7d20\u5728\u5e93\u5b58\u5145\u8db3\u65f6\u901a\u5e38\u88ab\u8ba4\u4e3a\u6709\u5229\u4e8e\u6346\u7ed1\u3002\u503c\u5f97\u6ce8\u610f\u7684\u662f\uff0c\u6211\u4eec\u7684\u6570\u503c\u5b9e\u9a8c\u8868\u660e\uff0c\u8fd9\u4e9b\u7ed3\u6784\u6d1e\u5bdf\u4e5f\u9002\u7528\u4e8e\u7531\u6807\u51c6\u6d41\u4f53\u6a21\u578b\u63a8\u5bfc\u51fa\u7684\u653f\u7b56\u3002\u5f53\u5e02\u573a\u89c4\u6a21\u76f8\u5bf9\u4e8e\u5e93\u5b58\u589e\u957f\u65f6\uff0c\u901a\u8fc7\u6c42\u89e3\u786e\u5b9a\u6027\u6d41\u4f53\u95ee\u9898\u5f97\u5230\u7684\u52a8\u6001\u6df7\u5408\u6346\u7ed1\u7b56\u7565\u4e5f\u6700\u7ec8\u8f6c\u5316\u4e3a\u52a8\u6001\u7ec4\u4ef6\u5b9a\u4ef7\u7b56\u7565\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2024.08306", "journal": "MS", "title": "Experimenting Under Stochastic Congestion", "authors": ["Shuangning Li", "Ramesh Johari", "Xu Kuang", "Stefan Wager"], "author_details": [{"name": "Shuangning Li", "affiliations": ["Booth School of Business, The University of Chicago"]}, {"name": "Ramesh Johari", "affiliations": ["Department of Management Science and Engineering, Stanford University"]}, {"name": "Xu Kuang", "affiliations": ["Graduate School of Business, Stanford University"]}, {"name": "Stefan Wager", "affiliations": ["Graduate School of Business, Stanford University"]}], "abstract": "We study randomized experiments in a service system when stochastic congestion can arise from temporarily limited supply or excess demand. Such congestion gives rise to cross-unit interference between the waiting customers, and analytic strategies that do not account for this interference may be biased. In current practice, one of the most widely used ways to address stochastic congestion is to use switchback experiments that turn a target intervention on and off for the whole system in alternation. We find, however, that under a queueing model for stochastic congestion, the standard way of analyzing switchbacks is inefficient and that estimators that leverage the queueing model can be materially more accurate. Additionally, we show how the queueing model enables estimation of total policy gradients from unit-level randomized experiments, thus giving practitioners an alternative experimental approach they can use without needing to precommit to a fixed switchback length before data collection.", "date": "2026-08-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2024.08306", "title_zh": "\u5728\u968f\u673a\u5b9e\u9a8c\u4e2d\u5e94\u5bf9\u968f\u673a\u62e5\u5835", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5728\u670d\u52a1\u7cfb\u7edf\u4e2d\u51fa\u73b0\u968f\u673a\u62e5\u5835\u7684\u968f\u673a\u5b9e\u9a8c\uff0c\u8fd9\u79cd\u62e5\u5835\u53ef\u80fd\u6e90\u4e8e\u4e34\u65f6\u4f9b\u5e94\u4e0d\u8db3\u6216\u9700\u6c42\u8fc7\u5269\u3002\u8fd9\u79cd\u62e5\u5835\u4f1a\u5bfc\u81f4\u7b49\u5f85\u5ba2\u6237\u4e4b\u95f4\u7684\u4ea4\u53c9\u5e72\u6270\uff0c\u800c\u672a\u8003\u8651\u8fd9\u79cd\u5e72\u6270\u7684\u5206\u6790\u7b56\u7565\u53ef\u80fd\u4f1a\u4ea7\u751f\u504f\u5dee\u3002\u5728\u5f53\u524d\u5b9e\u8df5\u4e2d\uff0c\u6700\u5e38\u7528\u7684\u65b9\u6cd5\u662f\u91c7\u7528\u5207\u6362\u5b9e\u9a8c\uff0c\u5373\u5728\u7cfb\u7edf\u5c42\u9762\u4ea4\u66ff\u5f00\u542f\u548c\u5173\u95ed\u76ee\u6807\u5e72\u9884\u63aa\u65bd\u3002\u7136\u800c\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u9488\u5bf9\u968f\u673a\u62e5\u5835\u7684\u6392\u961f\u6a21\u578b\u4e0b\uff0c\u6807\u51c6\u7684\u5207\u6362\u5b9e\u9a8c\u5206\u6790\u65b9\u6cd5\u6548\u7387\u4f4e\u4e0b\uff0c\u5229\u7528\u6392\u961f\u6a21\u578b\u7684\u4f30\u8ba1\u65b9\u6cd5\u53ef\u4ee5\u663e\u8457\u63d0\u9ad8\u51c6\u786e\u6027\u3002\u6b64\u5916\uff0c\u6211\u4eec\u5c55\u793a\u4e86\u5982\u4f55\u901a\u8fc7\u6392\u961f\u6a21\u578b\u4ece\u5355\u4f4d\u5c42\u9762\u7684\u968f\u673a\u5b9e\u9a8c\u4e2d\u4f30\u8ba1\u603b\u4f53\u653f\u7b56\u68af\u5ea6\uff0c\u4ece\u800c\u4e3a\u4ece\u4e1a\u8005\u63d0\u4f9b\u4e00\u79cd\u65e0\u9700\u5728\u6570\u636e\u6536\u96c6\u524d\u9884\u5148\u786e\u5b9a\u56fa\u5b9a\u5207\u6362\u5468\u671f\u7684\u66ff\u4ee3\u5b9e\u9a8c\u65b9\u6cd5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70064", "journal": "JF", "title": "Personal Costs of Executive Turnovers", "authors": ["KASPER MEISNER NIELSEN"], "author_details": [{"name": "KASPER MEISNER NIELSEN", "affiliations": []}], "abstract": "ABSTRACT This study examines the income loss following forced CEO turnovers using income data from the official records at the Danish Tax Authority. We find that dismissed CEOs\u2019 personal income is 40% lower in the five years following forced turnovers. The decline is driven by labor market outcomes: labor and entrepreneurial incomes decline, while other sources of income increase. We find larger declines in income for executives with poor performance during their tenures, consistent with the executive labor market being the main channel for the lower income. Overall, the findings suggest that executives face significant personal costs from forced turnovers.", "date": "2026-08-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70064", "title_zh": "\u9ad8\u7ba1\u88ab\u5f3a\u5236\u66f4\u6362\u7684\u4e2a\u4eba\u6210\u672c", "abstract_zh": "\u6458\u8981 \u672c\u7814\u7a76\u5229\u7528\u4e39\u9ea6\u7a0e\u52a1\u673a\u6784\u7684\u5b98\u65b9\u6536\u5165\u8bb0\u5f55\uff0c\u8003\u5bdf\u4e86\u56e0\u88ab\u5f3a\u5236\u66f4\u6362\u800c\u79bb\u804c\u7684CEO\u5728\u4e94\u5e74\u5185\u7684\u6536\u5165\u635f\u5931\u60c5\u51b5\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u88ab\u89e3\u96c7\u7684CEO\u5728\u5f3a\u5236\u66f4\u6362\u540e\u7684\u4e94\u5e74\u5185\uff0c\u5176\u4e2a\u4eba\u6536\u5165\u964d\u4f4e\u4e8640%\u3002\u8fd9\u4e00\u4e0b\u964d\u4e3b\u8981\u7531\u52b3\u52a8\u529b\u5e02\u573a\u7ed3\u679c\u5f15\u8d77\uff1a\u52b3\u52a8\u6536\u5165\u548c\u521b\u4e1a\u6536\u5165\u4e0b\u964d\uff0c\u800c\u5176\u4ed6\u6536\u5165\u6765\u6e90\u5219\u4e0a\u5347\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u90a3\u4e9b\u5728\u804c\u671f\u95f4\u8868\u73b0\u4e0d\u4f73\u7684\u9ad8\u7ba1\u6536\u5165\u4e0b\u964d\u5e45\u5ea6\u66f4\u5927\uff0c\u8fd9\u8868\u660e\u9ad8\u7ba1\u52b3\u52a8\u529b\u5e02\u573a\u662f\u5bfc\u81f4\u6536\u5165\u4e0b\u964d\u7684\u4e3b\u8981\u6e20\u9053\u3002\u603b\u4f53\u800c\u8a00\uff0c\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u9ad8\u7ba1\u5728\u88ab\u5f3a\u5236\u66f4\u6362\u65f6\u9762\u4e34\u663e\u8457\u7684\u4e2a\u4eba\u6210\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag040", "journal": "QJE", "title": "Clause and Effect: Theory and Field Experimental Evidence on Noncompete Clauses", "authors": ["Bo Cowgill", "Brandon Freiberg", "Evan Starr"], "author_details": [{"name": "Bo Cowgill", "affiliations": ["University of Toronto ,"]}, {"name": "Brandon Freiberg", "affiliations": ["INSEAD ,"]}, {"name": "Evan Starr", "affiliations": ["University of Maryland ,"]}], "abstract": "Abstract We study worker noncompete clauses in a large field experiment with two finance firms. Across ~14,000 job offers to freelance recruiters on short-term contracts, we randomize wages and the presence, salience, and duration of noncompetes (all contracts also included a nondisclosure agreement). Removing a noncompete increases mobility between competing employers by 36%\u201352% and raises workers\u2019 total earnings from the two firms by 12%\u201317%. We find no evidence\u2014rejecting even small effects\u2014that removing noncompetes generates secret leakage. We also find no evidence that workers choose noncompete jobs for higher pay. Many workers appear unaware of noncompetes before firms\u2019 post-employment communication. The results align with a model of inattention and uncertainty about enforcement.", "date": "2026-08-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag040", "title_zh": "\u6761\u6b3e\u4e0e\u6548\u679c\uff1a\u5173\u4e8e\u975e\u7ade\u4e89\u6761\u6b3e\u7684\u7406\u8bba\u4e0e\u5b9e\u5730\u5b9e\u9a8c\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u5728\u4e00\u4e2a\u6d89\u53ca\u4e24\u5bb6\u91d1\u878d\u516c\u53f8\u7684\u5927\u89c4\u6a21\u5b9e\u5730\u5b9e\u9a8c\u4e2d\u7814\u7a76\u4e86\u5458\u5de5\u7684\u975e\u7ade\u4e89\u6761\u6b3e\u3002\u5728\u7ea614,000\u4efd\u9762\u5411\u81ea\u7531\u804c\u4e1a\u62db\u8058\u8005\u7684\u77ed\u671f\u5408\u540c\u5de5\u4f5c\u63d0\u8bae\u4e2d\uff0c\u6211\u4eec\u968f\u673a\u5206\u914d\u5de5\u8d44\u4ee5\u53ca\u975e\u7ade\u4e89\u6761\u6b3e\u7684\u5b58\u5728\u3001\u663e\u8457\u6027\u53ca\u5176\u6301\u7eed\u65f6\u95f4\uff08\u6240\u6709\u5408\u540c\u5747\u5305\u542b\u4fdd\u5bc6\u534f\u8bae\uff09\u3002\u53d6\u6d88\u975e\u7ade\u4e89\u6761\u6b3e\u4f7f\u5458\u5de5\u5728\u4e0d\u540c\u96c7\u4e3b\u4e4b\u95f4\u7684\u6d41\u52a8\u6027\u63d0\u9ad836%\u81f352%\uff0c\u5e76\u4f7f\u5458\u5de5\u4ece\u4e24\u5bb6\u516c\u53f8\u83b7\u5f97\u7684\u603b\u6536\u5165\u589e\u52a012%\u81f317%\u3002\u6211\u4eec\u672a\u53d1\u73b0\u2014\u2014\u5373\u4f7f\u6392\u9664\u5fae\u5c0f\u6548\u5e94\u2014\u2014\u53d6\u6d88\u975e\u7ade\u4e89\u6761\u6b3e\u4f1a\u5bfc\u81f4\u673a\u5bc6\u4fe1\u606f\u5916\u6cc4\u7684\u8bc1\u636e\u3002\u6211\u4eec\u4e5f\u672a\u53d1\u73b0\u5de5\u4eba\u9009\u62e9\u5305\u542b\u975e\u7ade\u4e89\u6761\u6b3e\u7684\u5de5\u4f5c\u662f\u4e3a\u4e86\u83b7\u5f97\u66f4\u9ad8\u85aa\u916c\u3002\u8bb8\u591a\u5de5\u4eba\u5728\u4f01\u4e1a\u5165\u804c\u540e\u7684\u6c9f\u901a\u4e4b\u524d\u5e76\u672a\u610f\u8bc6\u5230\u5b58\u5728\u975e\u7ade\u4e89\u6761\u6b3e\u3002\u7ed3\u679c\u4e0e\u5173\u4e8e\u6ce8\u610f\u529b\u4e0d\u8db3\u548c\u5bf9\u6267\u884c\u60c5\u51b5\u4e0d\u786e\u5b9a\u6027\u7684\u6a21\u578b\u76f8\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag072", "journal": "REStud", "title": "College, Cognitive Ability, and Socioeconomic Disadvantage: Policy Lessons from the U.K. in 1960\u20132004", "authors": ["Andrea Ichino", "Aldo Rustichini", "Giulio Zanella"], "author_details": [{"name": "Andrea Ichino", "affiliations": ["European University Institute and University of Bologna ,"]}, {"name": "Aldo Rustichini", "affiliations": ["University of Minnesota ,"]}, {"name": "Giulio Zanella", "affiliations": ["University of Bologna ,"]}], "abstract": "Abstract University access has significantly expanded in OECD countries, and further growth figures prominently in political agendas. We study possible consequences of historical and future expansions in a stochastic, general equilibrium Roy model where tertiary educational attainment is determined by cognitive ability and socioeconomic disadvantage. In our analysis, individual productivity depends not only on education but also directly on cognitive ability. The expansion of university access in the U.K. that started in the 1960s provides an ideal case study to draw lessons for the future. We find that this expansion led to the selection into college of progressively less talented students from advantaged backgrounds. Appropriate counterfactual policies existed that would have achieved the dual goal of increasing college graduates\u2019 cognitive ability while improving tertiary education opportunities for the disadvantaged.", "date": "2026-08-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag072", "title_zh": "\u5927\u5b66\u3001\u8ba4\u77e5\u80fd\u529b\u4e0e\u793e\u4f1a\u7ecf\u6d4e\u52a3\u52bf\uff1a\u6765\u81ea1960\u20132004\u5e74\u82f1\u56fd\u7684\u653f\u7b56\u542f\u793a", "abstract_zh": "\u6458\u8981 \u5728\u7ecf\u5408\u7ec4\u7ec7\u56fd\u5bb6\uff0c\u5927\u5b66\u5165\u5b66\u673a\u4f1a\u663e\u8457\u6269\u5927\uff0c\u8fd9\u4e00\u8d8b\u52bf\u5728\u653f\u6cbb\u8bae\u7a0b\u4e2d\u5c24\u4e3a\u7a81\u51fa\u3002\u6211\u4eec\u57fa\u4e8e\u4e00\u4e2a\u968f\u673a\u4e00\u822c\u5747\u8861Roy\u6a21\u578b\uff0c\u7814\u7a76\u5386\u53f2\u548c\u672a\u6765\u5927\u5b66\u5165\u5b66\u6269\u5f20\u53ef\u80fd\u5e26\u6765\u7684\u540e\u679c\uff0c\u5176\u4e2d\u9ad8\u7b49\u6559\u80b2\u6210\u5c31\u7531\u8ba4\u77e5\u80fd\u529b\u548c\u793e\u4f1a\u7ecf\u6d4e\u52a3\u52bf\u51b3\u5b9a\u3002\u5728\u6211\u4eec\u7684\u5206\u6790\u4e2d\uff0c\u4e2a\u4f53\u751f\u4ea7\u7387\u4e0d\u4ec5\u53d6\u51b3\u4e8e\u6559\u80b2\u6c34\u5e73\uff0c\u8fd8\u76f4\u63a5\u4f9d\u8d56\u4e8e\u8ba4\u77e5\u80fd\u529b\u300220\u4e16\u7eaa60\u5e74\u4ee3\u4ee5\u6765\u82f1\u56fd\u5927\u5b66\u5165\u5b66\u673a\u4f1a\u7684\u6269\u5927\u4e3a\u672a\u6765\u653f\u7b56\u63d0\u4f9b\u4e86\u7406\u60f3\u7684\u6848\u4f8b\u7814\u7a76\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u4e00\u6269\u5f20\u5bfc\u81f4\u8d8a\u6765\u8d8a\u591a\u6765\u81ea\u4f18\u52bf\u80cc\u666f\u7684\u3001\u8ba4\u77e5\u80fd\u529b\u8f83\u4f4e\u7684\u5b66\u751f\u8fdb\u5165\u5927\u5b66\u3002\u5b58\u5728\u9002\u5f53\u7684\u53cd\u4e8b\u5b9e\u653f\u7b56\uff0c\u80fd\u591f\u540c\u65f6\u63d0\u5347\u5927\u5b66\u6bd5\u4e1a\u751f\u7684\u8ba4\u77e5\u80fd\u529b\uff0c\u5e76\u6539\u5584\u793e\u4f1a\u7ecf\u6d4e\u5f31\u52bf\u7fa4\u4f53\u7684\u9ad8\u7b49\u6559\u80b2\u673a\u4f1a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2022.02682", "journal": "MS", "title": "Crowdsourcing from Hackers: Strategic Coopetition and Governance in Bug Bounty Programs", "authors": ["Jiali Zhou", "Kai-Lung Hui"], "author_details": [{"name": "Jiali Zhou", "affiliations": ["Kogod School of Business, American University, Washington, District of Columbia 20016"]}, {"name": "Kai-Lung Hui", "affiliations": ["School of Business and Management, The Hong Kong University of Science and Technology, Clear Water Bay, Hong Kong, China"]}], "abstract": "In a bug bounty program (BBP), organizations incentivize hackers\u2014who could otherwise be \u201cenemies\u201d\u2014to report security vulnerabilities by publicly offering monetary rewards. This paper develops an analytical framework to characterize BBPs and their strategic and economic impacts. Strategically, BBPs induce some hackers to self-select into cooperative vulnerability discovery and reporting, diverting them away from attacking (attack diversion) and delegating part of the protection effort to them (protection delegation). We show that (i) BBPs can be beneficial even when hackers are inefficient at vulnerability identification, yet more participants might make BBPs less attractive to firms. (ii) Although BBPs improve security, they might encourage competitive hackers (i.e., attackers) to exert more efforts. (iii) The coopetition dynamics can render a firm\u2019s provision of rewards and in-house efforts socially inefficient. Common cybersecurity regulations, such as breach penalties and bounty reward subsidies, may exacerbate the inefficiency. We find complementarity between bounty subsidies and breach penalties, suggesting that combining and customizing them according to firm characteristics could enhance BBP efficiency. (iv) Contrary to the conventional wisdom that crowdsourcing rewards increase with participant size, we identify scenarios in which a firm should reduce or make nonmonotonic adjustments to a bounty reward as participant size increases. (v) Legal safe harbor for security testing or policies that reduce duplicate report submissions can lower firm payoffs under BBPs. We draw related implications for research and practice in information security and crowdsourcing.", "date": "2026-08-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2022.02682", "title_zh": "\u9ed1\u5ba2\u4f17\u5305\uff1a\u6f0f\u6d1e\u8d4f\u91d1\u8ba1\u5212\u4e2d\u7684\u6218\u7565\u7ade\u5408\u4e0e\u6cbb\u7406", "abstract_zh": "\u5728\u6f0f\u6d1e\u8d4f\u91d1\u8ba1\u5212\uff08BBP\uff09\u4e2d\uff0c\u7ec4\u7ec7\u901a\u8fc7\u516c\u5f00\u63d0\u4f9b\u8d27\u5e01\u5956\u52b1\u6765\u6fc0\u52b1\u9ed1\u5ba2\u2014\u2014\u8fd9\u4e9b\u9ed1\u5ba2\u672c\u53ef\u80fd\u6210\u4e3a\u2018\u654c\u4eba\u2019\u2014\u2014\u62a5\u544a\u5b89\u5168\u6f0f\u6d1e\u3002\u672c\u6587\u6784\u5efa\u4e86\u4e00\u4e2a\u5206\u6790\u6846\u67b6\uff0c\u4ee5\u523b\u753bBBP\u53ca\u5176\u6218\u7565\u4e0e\u7ecf\u6d4e\u5f71\u54cd\u3002\u4ece\u6218\u7565\u89d2\u5ea6\u770b\uff0cBBP\u4f1a\u4fc3\u4f7f\u90e8\u5206\u9ed1\u5ba2\u81ea\u6211\u9009\u62e9\u8fdb\u5165\u5408\u4f5c\u6027\u7684\u6f0f\u6d1e\u53d1\u73b0\u4e0e\u62a5\u544a\u884c\u4e3a\uff0c\u4ece\u800c\u5c06\u5176\u4ece\u653b\u51fb\u884c\u4e3a\u4e2d\u5206\u6d41\uff08\u653b\u51fb\u5206\u6d41\uff09\uff0c\u5e76\u5c06\u90e8\u5206\u9632\u62a4\u5de5\u4f5c\u59d4\u6258\u7ed9\u8fd9\u4e9b\u9ed1\u5ba2\uff08\u9632\u62a4\u59d4\u6258\uff09\u3002\u6211\u4eec\u53d1\u73b0\uff1a\uff08i\uff09\u5373\u4f7f\u9ed1\u5ba2\u5728\u6f0f\u6d1e\u8bc6\u522b\u65b9\u9762\u6548\u7387\u4f4e\u4e0b\uff0cBBP\u4ecd\u53ef\u80fd\u6709\u76ca\uff0c\u4f46\u53c2\u4e0e\u8005\u6570\u91cf\u589e\u52a0\u53ef\u80fd\u4f7fBBP\u5bf9\u4f01\u4e1a\u7684\u5438\u5f15\u529b\u4e0b\u964d\uff1b\uff08ii\uff09\u5c3d\u7ba1BBP\u63d0\u5347\u4e86\u5b89\u5168\u6027\uff0c\u4f46\u53ef\u80fd\u4fc3\u4f7f\u7ade\u4e89\u578b\u9ed1\u5ba2\uff08\u5373\u653b\u51fb\u8005\uff09\u6295\u5165\u66f4\u591a\u52aa\u529b\uff1b\uff08iii\uff09\u7ade\u5408\u52a8\u6001\u53ef\u80fd\u5bfc\u81f4\u4f01\u4e1a\u5bf9\u5956\u52b1\u7684\u63d0\u4f9b\u53ca\u5185\u90e8\u9632\u62a4\u6295\u5165\u4ea7\u751f\u793e\u4f1a\u65e0\u6548\u7387\u3002\u5e38\u89c1\u7684\u7f51\u7edc\u5b89\u5168\u76d1\u7ba1\u63aa\u65bd\uff0c\u5982\u6570\u636e\u6cc4\u9732\u5904\u7f5a\u548c\u8d4f\u91d1\u5956\u52b1\u8865\u8d34\uff0c\u53ef\u80fd\u52a0\u5267\u8fd9\u79cd\u65e0\u6548\u7387\u3002\u6211\u4eec\u53d1\u73b0\u8d4f\u91d1\u8865\u8d34\u4e0e\u6570\u636e\u6cc4\u9732\u5904\u7f5a\u4e4b\u95f4\u5b58\u5728\u4e92\u8865\u6027\uff0c\u8868\u660e\u6839\u636e\u4f01\u4e1a\u7279\u5f81\u5b9a\u5236\u5e76\u7ed3\u5408\u4f7f\u7528\u8fd9\u4e9b\u63aa\u65bd\uff0c\u53ef\u4ee5\u63d0\u5347BBP\u7684\u6548\u7387\uff1b\uff08iv\uff09\u4e0e\u4f20\u7edf\u89c2\u70b9\u8ba4\u4e3a\u4f17\u5305\u5956\u52b1\u968f\u53c2\u4e0e\u8005\u6570\u91cf\u589e\u52a0\u800c\u4e0a\u5347\u4e0d\u540c\uff0c\u6211\u4eec\u53d1\u73b0\u5728\u67d0\u4e9b\u60c5\u5883\u4e0b\uff0c\u4f01\u4e1a\u5e94\u968f\u7740\u53c2\u4e0e\u8005\u6570\u91cf\u7684\u589e\u52a0\u800c\u51cf\u5c11\u6216\u8fdb\u884c\u975e\u5355\u8c03\u8c03\u6574\u5176\u8d4f\u91d1\u5956\u52b1\uff1b\uff08v\uff09\u9488\u5bf9\u5b89\u5168\u6d4b\u8bd5\u7684\u6cd5\u5f8b\u514d\u8d23\u6761\u6b3e\u6216\u51cf\u5c11\u91cd\u590d\u62a5\u544a\u63d0\u4ea4\u7684\u653f\u7b56\uff0c\u53ef\u80fd\u964d\u4f4e\u4f01\u4e1a\u5728BBP\u4e0b\u7684\u6536\u76ca\u3002\u672c\u6587\u5bf9\u4fe1\u606f\u5b89\u5168\u90e8\u95e8\u548c\u4f17\u5305\u9886\u57df\u7684\u7814\u7a76\u4e0e\u5b9e\u8df5\u5177\u6709\u76f8\u5173\u542f\u793a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag085", "journal": "REStud", "title": "Foreign Exchange Intervention with UIP and CIP Deviations", "authors": ["Philippe Bacchetta", "Kenza Benhima", "Brendan Berthold"], "author_details": [{"name": "Philippe Bacchetta", "affiliations": ["University of Lausanne, Swiss Finance Institute, Switzerland, CEPR ,"]}, {"name": "Kenza Benhima", "affiliations": ["University of Lausanne, Switzerland, CEPR , UK"]}, {"name": "Brendan Berthold", "affiliations": ["Zurich Insurance, Group Investment Management , Switzerland"]}], "abstract": "Abstract We examine the welfare-based opportunity cost of foreign exchange (FX) intervention when both covered interest rate parity (CIP) and uncovered interest rate parity (UIP) deviations are present. We consider a small open economy that receives international capital flows through constrained international financial intermediaries. Deviations from CIP come from limited arbitrage or through a convenience yield, while UIP deviations are also affected by global risk. We show that the sign of CIP and UIP deviations may differ for safe haven countries. We find that FX reserves may provide a net benefit, rather than a cost, when international intermediaries value the safe-haven properties of a currency more than domestic households. We show that this has been the case for the Swiss franc and the Japanese Yen. We examine the optimal policy of a constrained central bank planner in this context.", "date": "2026-08-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag085", "title_zh": "\u5916\u6c47\u5e72\u9884\u4e0e\u5229\u7387\u5e73\u4ef7\u504f\u79bb", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5728\u5b58\u5728\u8986\u76d6\u5229\u7387\u5e73\u4ef7\uff08CIP\uff09\u548c\u672a\u8986\u76d6\u5229\u7387\u5e73\u4ef7\uff08UIP\uff09\u504f\u79bb\u7684\u60c5\u51b5\u4e0b\uff0c\u57fa\u4e8e\u798f\u5229\u7684\u5916\u6c47\u5e72\u9884\u673a\u4f1a\u6210\u672c\u3002\u6211\u4eec\u8003\u8651\u4e00\u4e2a\u901a\u8fc7\u53d7\u9650\u5236\u7684\u56fd\u9645\u91d1\u878d\u4e2d\u4ecb\u673a\u6784\u63a5\u6536\u56fd\u9645\u8d44\u672c\u6d41\u52a8\u7684\u5c0f\u578b\u5f00\u653e\u7ecf\u6d4e\u4f53\u3002CIP\u504f\u79bb\u6e90\u4e8e\u5957\u5229\u53d7\u9650\u6216\u4fbf\u5229\u6536\u76ca\uff0c\u800cUIP\u504f\u79bb\u4e5f\u53d7\u5230\u5168\u7403\u98ce\u9669\u7684\u5f71\u54cd\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5bf9\u4e8e\u907f\u9669\u56fd\u5bb6\uff0cCIP\u548cUIP\u504f\u79bb\u7684\u7b26\u53f7\u53ef\u80fd\u4e0d\u540c\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5f53\u56fd\u9645\u91d1\u878d\u4e2d\u4ecb\u673a\u6784\u66f4\u91cd\u89c6\u8d27\u5e01\u7684\u907f\u9669\u5c5e\u6027\uff0c\u800c\u975e\u56fd\u5185\u5c45\u6c11\u65f6\uff0c\u5916\u6c47\u50a8\u5907\u53ef\u80fd\u5e26\u6765\u51c0\u6536\u76ca\uff0c\u800c\u975e\u6210\u672c\u3002\u6211\u4eec\u53d1\u73b0\u8fd9\u79cd\u60c5\u51b5\u5728\u745e\u58eb\u6cd5\u90ce\u548c\u65e5\u5143\u4e2d\u5df2\u7ecf\u5b58\u5728\u3002\u6211\u4eec\u5728\u6b64\u80cc\u666f\u4e0b\u7814\u7a76\u4e86\u53d7\u7ea6\u675f\u4e2d\u592e\u94f6\u884c\u51b3\u7b56\u8005\u7684\u6700\u4f18\u653f\u7b56\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u672c\u6d41\u52a8"]}, {"doi": "10.1093/restud/rdag087", "journal": "REStud", "title": "Marriage, Assortative Mating, and Wealth Inequality", "authors": ["Andreas Fagereng", "Luigi Guiso", "Luigi Pistaferri"], "author_details": [{"name": "Andreas Fagereng", "affiliations": ["BI Norwegian Business School and CEPR , Norway"]}, {"name": "Luigi Guiso", "affiliations": ["Einaudi Institute for Economics and Finance (EIEF) and CEPR , Italy"]}, {"name": "Luigi Pistaferri", "affiliations": ["Stanford University, SIEPR, NBER and CEPR , USA"]}], "abstract": "Abstract We use population data on capital income and wealth holdings for Norway to measure asset positions and wealth returns before individuals marry and after the household is formed. These data allow us to establish a number of novel facts. First, individuals sort on personal wealth rather than parental wealth. Second, people match also on their personal returns to wealth, and assortative mating on returns is as strong as that on wealth. Third, post-marriage returns on family wealth reflect in equal part the pre-marriage returns of the two spouses. However, for households at the top of the wealth distribution at marriage, family wealth is largely managed by the spouse with the highest potential to grow it, providing a microfoundation for the scale dependence in wealth returns documented in several empirical papers. Fourth, marriage lowers the degree of wealth inequality as well as the heterogeneity in returns relative to the counterfactual case of no marriages. We use a simple framework to illustrate how the inequality-attenuating role of marriage is affected by assortative mating on wealth and returns and by wealth management task allocation between spouses.", "date": "2026-08-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag087", "title_zh": "\u5a5a\u59fb\u3001\u62e9\u5076\u504f\u597d\u4e0e\u8d22\u5bcc\u4e0d\u5e73\u7b49", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u7528\u632a\u5a01\u5173\u4e8e\u8d44\u672c\u6536\u5165\u548c\u8d22\u5bcc\u6301\u6709\u60c5\u51b5\u7684\u7fa4\u4f53\u6570\u636e\uff0c\u6d4b\u91cf\u4e2a\u4f53\u7ed3\u5a5a\u524d\u548c\u5a5a\u59fb\u540e\u5bb6\u5ead\u7684\u8d44\u4ea7\u72b6\u51b5\u53ca\u8d22\u5bcc\u56de\u62a5\u3002\u8fd9\u4e9b\u6570\u636e\u4f7f\u6211\u4eec\u80fd\u591f\u5f97\u51fa\u4e00\u7cfb\u5217\u65b0\u53d1\u73b0\u3002\u9996\u5148\uff0c\u4e2a\u4f53\u4f9d\u636e\u4e2a\u4eba\u8d22\u5bcc\u800c\u975e\u7236\u6bcd\u8d22\u5bcc\u8fdb\u884c\u62e9\u5076\u5339\u914d\u3002\u5176\u6b21\uff0c\u4eba\u4eec\u4e5f\u6839\u636e\u81ea\u8eab\u7684\u8d22\u5bcc\u56de\u62a5\u8fdb\u884c\u5339\u914d\uff0c\u8d22\u5bcc\u56de\u62a5\u7684\u62e9\u5076\u504f\u597d\u5f3a\u5ea6\u4e0e\u8d22\u5bcc\u672c\u8eab\u7684\u62e9\u5076\u504f\u597d\u5f3a\u5ea6\u76f8\u5f53\u3002\u7b2c\u4e09\uff0c\u5a5a\u59fb\u540e\u7684\u5bb6\u5ead\u8d22\u5bcc\u56de\u62a5\u5728\u76f8\u5f53\u7a0b\u5ea6\u4e0a\u53cd\u6620\u4e86\u592b\u59bb\u53cc\u65b9\u5a5a\u524d\u5404\u81ea\u7684\u8d22\u5bcc\u56de\u62a5\u3002\u7136\u800c\uff0c\u5bf9\u4e8e\u5a5a\u59fb\u65f6\u5904\u4e8e\u8d22\u5bcc\u5206\u5e03\u9876\u7aef\u7684\u5bb6\u5ead\uff0c\u5bb6\u5ead\u8d22\u5bcc\u4e3b\u8981\u7531\u5177\u5907\u66f4\u9ad8\u589e\u957f\u6f5c\u529b\u7684\u914d\u5076\u6765\u7ba1\u7406\uff0c\u8fd9\u4e3a\u6587\u732e\u4e2d\u591a\u6b21\u62a5\u544a\u7684\u8d22\u5bcc\u56de\u62a5\u89c4\u6a21\u4f9d\u8d56\u6027\u63d0\u4f9b\u4e86\u5fae\u89c2\u57fa\u7840\u3002\u7b2c\u56db\uff0c\u5a5a\u59fb\u964d\u4f4e\u4e86\u8d22\u5bcc\u4e0d\u5e73\u7b49\u7a0b\u5ea6\u4ee5\u53ca\u56de\u62a5\u7684\u5f02\u8d28\u6027\uff0c\u76f8\u8f83\u4e8e\u6ca1\u6709\u5a5a\u59fb\u7684\u5bf9\u7167\u60c5\u666f\u3002\u6211\u4eec\u91c7\u7528\u4e00\u4e2a\u7b80\u5355\u7684\u6846\u67b6\uff0c\u8bf4\u660e\u5a5a\u59fb\u5728\u964d\u4f4e\u4e0d\u5e73\u7b49\u65b9\u9762\u7684\u6548\u5e94\u5982\u4f55\u53d7\u5230\u8d22\u5bcc\u548c\u56de\u62a5\u7684\u62e9\u5076\u504f\u597d\u4ee5\u53ca\u592b\u59bb\u95f4\u8d22\u5bcc\u7ba1\u7406\u4efb\u52a1\u5206\u914d\u7684\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag054", "journal": "RFS", "title": "International Arbitrage Premia", "authors": ["Mirela Sandulescu", "Paul Schneider"], "author_details": [{"name": "Mirela Sandulescu", "affiliations": ["University of North Carolina at Chapel Hill ,"]}, {"name": "Paul Schneider", "affiliations": ["USI Lugano and Swiss Finance Institute ,"]}], "abstract": "Abstract We introduce the nonlinear arbitrage correction (NAC), the residual that renders a linear benchmark model arbitrage-free while preserving the law of one price. The price of NAC captures the marginal Sharpe ratio increase consistent with no-arbitrage and upper-bounds the constrained Hansen\u2013Jagannathan distance. Using four decades of international equity, currency, and factor returns, NAC is strongly countercyclical, peaking during crises when linear models turn negative. The implied Sharpe ratio increase reaches 0.3, underscoring its economic relevance. While linear models perform well on average, they fail in distressed states, underpricing nonlinear payoffs. Incorporating NAC restores positivity and stabilizes pricing across regimes.", "date": "2026-08-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag054", "title_zh": "\u56fd\u9645\u5957\u5229\u6ea2\u4ef7", "abstract_zh": "\u6211\u4eec\u5f15\u5165\u4e86\u975e\u7ebf\u6027\u5957\u5229\u4fee\u6b63\uff08NAC\uff09\uff0c\u5b83\u662f\u5728\u4fdd\u6301\u4ef7\u683c\u4e00\u81f4\u6027\u7684\u524d\u63d0\u4e0b\uff0c\u4f7f\u7ebf\u6027\u57fa\u51c6\u6a21\u578b\u65e0\u5957\u5229\u7684\u6b8b\u5dee\u3002NAC\u7684\u4ef7\u683c\u53cd\u6620\u4e86\u4e0e\u65e0\u5957\u5229\u4e00\u81f4\u7684\u8fb9\u9645\u590f\u666e\u6bd4\u7387\u63d0\u5347\uff0c\u5e76\u5bf9\u53d7\u9650\u7684\u6c49\u68ee-\u8d3e\u52a0\u7eb3athan\u8ddd\u79bb\u63d0\u4f9b\u4e0a\u754c\u3002\u57fa\u4e8e\u56db\u5341\u5e74\u7684\u56fd\u9645\u80a1\u7968\u3001\u8d27\u5e01\u548c\u56e0\u5b50\u56de\u62a5\u6570\u636e\uff0cNAC\u8868\u73b0\u51fa\u5f3a\u70c8\u7684\u5468\u671f\u6027\u9006\u5411\u7279\u5f81\uff0c\u5728\u5371\u673a\u671f\u95f4\u8fbe\u5230\u5cf0\u503c\uff0c\u6b64\u65f6\u7ebf\u6027\u6a21\u578b\u4f1a\u53d8\u4e3a\u8d1f\u503c\u3002NAC\u6240\u9690\u542b\u7684\u590f\u666e\u6bd4\u7387\u63d0\u5347\u8fbe\u52300.3\uff0c\u51f8\u663e\u4e86\u5176\u7ecf\u6d4e\u610f\u4e49\u3002\u5c3d\u7ba1\u7ebf\u6027\u6a21\u578b\u5728\u5e73\u5747\u8868\u73b0\u4e0a\u8868\u73b0\u826f\u597d\uff0c\u4f46\u5728\u56f0\u5883\u72b6\u6001\u4e0b\u5374\u5931\u6548\uff0c\u4f4e\u4f30\u4e86\u975e\u7ebf\u6027\u652f\u4ed8\u3002\u5f15\u5165NAC\u53ef\u6062\u590d\u6b63\u6027\u5e76\u7a33\u5b9a\u4e0d\u540c\u72b6\u6001\u4e0b\u7684\u5b9a\u4ef7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2023.01924", "journal": "MS", "title": "Rational Abandonment from Observable Priority Queues: Equilibrium Strategy, Performance, and Pricing Implications", "authors": ["Philipp Af\u00e8che", "Vahid Sarhangian"], "author_details": [{"name": "Philipp Af\u00e8che", "affiliations": ["Rotman School of Management, University of Toronto, Toronto, Ontario M5S 3E6, Canada"]}, {"name": "Vahid Sarhangian", "affiliations": ["Department of Mechanical and Industrial Engineering, University of Toronto, Toronto, Ontario M5S 3E6, Canada"]}], "abstract": "Observable priority queues, where some customers are served ahead of others, are prevalent in many service systems, ranging from the entertainment industry to emergency departments (EDs). In this paper, we study the rational abandonment behavior of utility-maximizing customers in the context of an observable two-class priority queue and identify novel performance and pricing implications. We first characterize the structure of the rational abandonment strategy and show that it has a threshold-based last-come, first-abandon structure. We then examine the steady-state performance of the system under the rational abandonment strategy and in contrast with an exogenous abandonment model commonly used in the literature. We show that using the exogenous abandonment model could result in highly suboptimal decisions when considering capacity planning to meet target waiting times and/or abandonment rates. We further investigate optimal pricing strategies under rational abandonment. Our results highlight the importance of the timing of payments. We show that welfare maximization requires charging only a service fee and no entrance fee. In contrast, revenue maximization generally requires a combination of both an entrance and a service fee. Furthermore, welfare-maximizing prices always involve abandonment, whereas revenue maximization may require pricing strategies that prevent abandonment. Finally, we discuss the implications of our results for our motivating applications, including the perils of charging nonurgent ED patients upfront.", "date": "2026-08-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2023.01924", "title_zh": "\u53ef\u89c2\u5bdf\u4f18\u5148\u961f\u5217\u4e2d\u7684\u7406\u6027\u653e\u5f03\u884c\u4e3a\uff1a\u5747\u8861\u7b56\u7565\u3001\u6027\u80fd\u53ca\u5b9a\u4ef7\u542b\u4e49", "abstract_zh": "\u5728\u8bb8\u591a\u670d\u52a1\u7cfb\u7edf\u4e2d\uff0c\u5982\u5a31\u4e50\u884c\u4e1a\u548c\u6025\u8bca\u90e8\u95e8\uff08ED\uff09\uff0c\u5b58\u5728\u4e00\u4e9b\u987e\u5ba2\u5728\u4ed6\u4eba\u4e4b\u524d\u88ab\u670d\u52a1\u7684\u53ef\u89c2\u5bdf\u4f18\u5148\u961f\u5217\u3002\u672c\u6587\u7814\u7a76\u4e86\u5728\u53ef\u89c2\u5bdf\u7684\u4e24\u7c7b\u4f18\u5148\u961f\u5217\u4e2d\uff0c\u6548\u7528\u6700\u5927\u5316\u987e\u5ba2\u7684\u7406\u6027\u653e\u5f03\u884c\u4e3a\uff0c\u5e76\u8bc6\u522b\u51fa\u65b0\u7684\u6027\u80fd\u548c\u5b9a\u4ef7\u542b\u4e49\u3002\u6211\u4eec\u9996\u5148\u523b\u753b\u4e86\u7406\u6027\u653e\u5f03\u7b56\u7565\u7684\u7ed3\u6784\uff0c\u8868\u660e\u5176\u5177\u6709\u57fa\u4e8e\u9608\u503c\u7684\u2018\u540e\u5230\u5148\u5f03\u2019\u7279\u5f81\u3002\u63a5\u7740\uff0c\u6211\u4eec\u8003\u5bdf\u4e86\u5728\u7406\u6027\u653e\u5f03\u7b56\u7565\u4e0b\u7684\u7cfb\u7edf\u7a33\u6001\u6027\u80fd\uff0c\u5e76\u4e0e\u6587\u732e\u4e2d\u5e38\u7528\u7684\u5916\u751f\u653e\u5f03\u6a21\u578b\u8fdb\u884c\u5bf9\u6bd4\u3002\u7ed3\u679c\u8868\u660e\uff0c\u5f53\u8003\u8651\u5bb9\u91cf\u89c4\u5212\u4ee5\u6ee1\u8db3\u76ee\u6807\u7b49\u5f85\u65f6\u95f4\u548c/\u6216\u653e\u5f03\u7387\u65f6\uff0c\u4f7f\u7528\u5916\u751f\u653e\u5f03\u6a21\u578b\u53ef\u80fd\u5bfc\u81f4\u4e25\u91cd\u6b21\u4f18\u51b3\u7b56\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u7814\u7a76\u4e86\u5728\u7406\u6027\u653e\u5f03\u60c5\u51b5\u4e0b\u7684\u6700\u4f18\u5b9a\u4ef7\u7b56\u7565\u3002\u7ed3\u679c\u5f3a\u8c03\u4e86\u4ed8\u6b3e\u65f6\u673a\u7684\u91cd\u8981\u6027\uff1a\u4e3a\u4e86\u5b9e\u73b0\u798f\u5229\u6700\u5927\u5316\uff0c\u4ec5\u9700\u6536\u53d6\u670d\u52a1\u8d39\u800c\u65e0\u9700\u6536\u53d6\u5165\u573a\u8d39\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u4e3a\u4e86\u5b9e\u73b0\u6536\u5165\u6700\u5927\u5316\uff0c\u901a\u5e38\u9700\u8981\u540c\u65f6\u6536\u53d6\u5165\u573a\u8d39\u548c\u670d\u52a1\u8d39\u3002\u6b64\u5916\uff0c\u798f\u5229\u6700\u5927\u5316\u7684\u5b9a\u4ef7\u7b56\u7565\u59cb\u7ec8\u6d89\u53ca\u653e\u5f03\u884c\u4e3a\uff0c\u800c\u6536\u5165\u6700\u5927\u5316\u53ef\u80fd\u9700\u8981\u8bbe\u8ba1\u51fa\u9632\u6b62\u653e\u5f03\u7684\u5b9a\u4ef7\u7b56\u7565\u3002\u6700\u540e\uff0c\u6211\u4eec\u8ba8\u8bba\u4e86\u8fd9\u4e9b\u7ed3\u679c\u5bf9\u9a71\u52a8\u5e94\u7528\u7684\u542f\u793a\uff0c\u5305\u62ec\u5bf9\u63d0\u524d\u5411\u975e\u7d27\u6025\u6025\u8bca\u60a3\u8005\u6536\u8d39\u53ef\u80fd\u5e26\u6765\u7684\u98ce\u9669\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1287/mnsc.2025.00611", "journal": "MS", "title": "Aggregate Confusion in Crypto Market Data", "authors": ["Gustavo Schwenkler", "Aakash Shah", "Darren Yang"], "author_details": [{"name": "Gustavo Schwenkler", "affiliations": ["Santa Clara University, Santa Clara, California 95053"]}, {"name": "Aakash Shah", "affiliations": ["Indicia Labs, San Jose, California 95113"]}, {"name": "Darren Yang", "affiliations": ["Indicia Labs, San Jose, California 95113"]}], "abstract": "We present one of the first systematic audits of cryptocurrency market data quality across leading vendors. We document pervasive mislabeling, identifier instability, and large cross-provider discrepancies in prices, market caps, and volumes. To address these issues, we develop an aggregation method that yields asymptotically correct data by autonomously identifying and filtering unreliable observations. Using this framework, we construct an index to measure data quality over time and a grading system to benchmark providers. Our findings show that data inconsistencies can materially distort empirical research and investment analysis. They highlight possible oversight gaps in the market for crypto data.", "date": "2026-08-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1287/mnsc.2025.00611", "title_zh": "\u52a0\u5bc6\u8d27\u5e01\u5e02\u573a\u6570\u636e\u4e2d\u7684\u603b\u4f53\u6df7\u6dc6", "abstract_zh": "\u6211\u4eec\u5bf9\u4e3b\u6d41\u4f9b\u5e94\u5546\u7684\u52a0\u5bc6\u8d27\u5e01\u5e02\u573a\u6570\u636e\u8d28\u91cf\u8fdb\u884c\u4e86\u9996\u6b21\u7cfb\u7edf\u6027\u5ba1\u8ba1\u3002\u6211\u4eec\u8bb0\u5f55\u4e86\u6807\u7b7e\u9519\u8bef\u3001\u6807\u8bc6\u7b26\u4e0d\u7a33\u5b9a\u4ee5\u53ca\u4ef7\u683c\u3001\u5e02\u503c\u548c\u4ea4\u6613\u91cf\u5728\u4e0d\u540c\u4f9b\u5e94\u5546\u4e4b\u95f4\u5b58\u5728\u5de8\u5927\u5dee\u5f02\u7b49\u95ee\u9898\u3002\u4e3a\u89e3\u51b3\u8fd9\u4e9b\u95ee\u9898\uff0c\u6211\u4eec\u5f00\u53d1\u4e86\u4e00\u79cd\u805a\u5408\u65b9\u6cd5\uff0c\u8be5\u65b9\u6cd5\u80fd\u591f\u901a\u8fc7\u81ea\u4e3b\u8bc6\u522b\u5e76\u8fc7\u6ee4\u4e0d\u53ef\u9760\u7684\u89c2\u6d4b\u503c\uff0c\u5b9e\u73b0\u6e10\u8fd1\u6b63\u786e\u7684\u6570\u636e\u3002\u57fa\u4e8e\u8fd9\u4e00\u6846\u67b6\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u8861\u91cf\u6570\u636e\u8d28\u91cf\u968f\u65f6\u95f4\u53d8\u5316\u7684\u6307\u6570\uff0c\u4ee5\u53ca\u4e00\u4e2a\u7528\u4e8e\u8bc4\u4f30\u4f9b\u5e94\u5546\u8868\u73b0\u7684\u8bc4\u7ea7\u4f53\u7cfb\u3002\u6211\u4eec\u7684\u7814\u7a76\u53d1\u73b0\uff0c\u6570\u636e\u4e0d\u4e00\u81f4\u53ef\u80fd\u4e25\u91cd\u626d\u66f2\u5b9e\u8bc1\u7814\u7a76\u548c\u6295\u8d44\u5206\u6790\u3002\u8fd9\u4e9b\u53d1\u73b0\u51f8\u663e\u4e86\u52a0\u5bc6\u8d27\u5e01\u6570\u636e\u5e02\u573a\u4e2d\u53ef\u80fd\u5b58\u5728\u7684\u4e00\u4e9b\u76d1\u7ba1\u758f\u6f0f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag084", "journal": "REStud", "title": "Optimal Age-Based Policies for Pandemics: An Economic Analysis of COVID-19 and Beyond", "authors": ["Luiz Brotherhood", "Philipp Kircher", "Cezar Santos", "Mich\u00e8le Tertilt"], "author_details": [{"name": "Luiz Brotherhood", "affiliations": ["Universitat de Barcelona & BEAT ,"]}, {"name": "Philipp Kircher", "affiliations": ["Cornell University, NBER and CEPR ,"]}, {"name": "Cezar Santos", "affiliations": ["Inter-American Development Bank & CEPR ,"]}, {"name": "Mich\u00e8le Tertilt", "affiliations": ["University of Mannheim & CEPR ,"]}], "abstract": "Abstract This paper investigates the importance of the age composition for pandemic policy design. To do so, it introduces an economic framework with age heterogeneity, individual choice, and incomplete information, emphasising the value of testing. Calibrating the model to the U.S. COVID-19 pandemic reveals an 80% reduction in the death toll due to voluntary actions and the lockdown implemented in the US. The optimal lockdown, however, is more stringent than what was implemented. Moreover, the social planner follows an asymmetric approach by locking down the young relatively more than the old. We highlight the role of testing in reducing deaths, lowering economic costs, and allowing for a less restrictive lockdown. A social planner would choose a faster ramp-up in testing capacity relative to what occurred in the US. We use the framework to provide insights into pandemics caused by different viruses (including the Spanish flu) and underline the influence of economic conditions on optimal policies.", "date": "2026-08-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag084", "title_zh": "\u57fa\u4e8e\u5e74\u9f84\u7684\u75ab\u60c5\u653f\u7b56\u6700\u4f18\u8bbe\u8ba1\uff1a\u5173\u4e8e\u65b0\u51a0\u75ab\u60c5\u53ca\u672a\u6765\u7684\u7ecf\u6d4e\u5206\u6790", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u4eba\u53e3\u5e74\u9f84\u7ed3\u6784\u5bf9\u75ab\u60c5\u653f\u7b56\u8bbe\u8ba1\u7684\u91cd\u8981\u6027\u3002\u4e3a\u6b64\uff0c\u5f15\u5165\u4e86\u4e00\u4e2a\u5305\u542b\u5e74\u9f84\u5f02\u8d28\u6027\u3001\u4e2a\u4f53\u9009\u62e9\u548c\u4fe1\u606f\u4e0d\u5b8c\u5168\u6027\u7684\u7ecf\u6d4e\u6846\u67b6\uff0c\u5f3a\u8c03\u4e86\u68c0\u6d4b\u7684\u4ef7\u503c\u3002\u5c06\u6a21\u578b\u6821\u51c6\u81f3\u7f8e\u56fd\u65b0\u51a0\u75ab\u60c5\u53d1\u73b0\uff0c\u7531\u4e8e\u81ea\u613f\u884c\u4e3a\u548c\u7f8e\u56fd\u5b9e\u65bd\u7684\u5c01\u9501\u63aa\u65bd\uff0c\u6b7b\u4ea1\u4eba\u6570\u51cf\u5c11\u4e8680%\u3002\u7136\u800c\uff0c\u6700\u4f18\u5c01\u9501\u63aa\u65bd\u6bd4\u5b9e\u9645\u5b9e\u65bd\u7684\u66f4\u4e3a\u4e25\u683c\u3002\u793e\u4f1a\u89c4\u5212\u8005\u91c7\u53d6\u4e86\u975e\u5bf9\u79f0\u7b56\u7565\uff0c\u5bf9\u5e74\u8f7b\u4eba\u7684\u5c01\u9501\u7a0b\u5ea6\u9ad8\u4e8e\u8001\u5e74\u4eba\u3002\u6211\u4eec\u5f3a\u8c03\u4e86\u68c0\u6d4b\u5728\u51cf\u5c11\u6b7b\u4ea1\u3001\u964d\u4f4e\u7ecf\u6d4e\u6210\u672c\u4ee5\u53ca\u5b9e\u73b0\u66f4\u5bbd\u677e\u5c01\u9501\u65b9\u9762\u7684\u4f5c\u7528\u3002\u793e\u4f1a\u89c4\u5212\u8005\u4f1a\u9009\u62e9\u6bd4\u7f8e\u56fd\u5b9e\u9645\u53d1\u751f\u7684\u66f4\u5feb\u63d0\u5347\u68c0\u6d4b\u80fd\u529b\u3002\u6211\u4eec\u5229\u7528\u8be5\u6846\u67b6\u4e3a\u7531\u4e0d\u540c\u75c5\u6bd2\u5f15\u8d77\u7684\u75ab\u60c5\uff08\u5305\u62ec1918\u5e74\u897f\u73ed\u7259\u6d41\u611f\uff09\u63d0\u4f9b\u6d1e\u89c1\uff0c\u5e76\u5f3a\u8c03\u7ecf\u6d4e\u72b6\u51b5\u5bf9\u6700\u4f18\u653f\u7b56\u7684\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag071", "journal": "RFS", "title": "Size-Based Regulation and Bank Fragility: Evidence from the Wells Fargo Asset Cap", "authors": ["Tianyue Ruan", "Siddharth Vij"], "author_details": [{"name": "Tianyue Ruan", "affiliations": ["Faculty of Business and Economics, University of Hong Kong , Hong Kong SAR,"]}, {"name": "Siddharth Vij", "affiliations": ["Terry College of Business, University of Georgia ,"]}], "abstract": "Abstract We argue that heightened regulation on large banks contributed to the rise in fragility of smaller banks revealed by the 2023 regional bank crisis. In 2018, regulators restricted Wells Fargo, the third largest U.S. bank, from growing its total assets. We estimate this asset cap led Wells Fargo to give up deposits amounting to 2.2% of aggregate bank deposits. These deposits, primarily uninsured, were reallocated to banks geographically proximate to Wells Fargo, including smaller, less regulated banks. In turn, these banks experienced higher deposit outflows once monetary tightening commenced and saw their stock prices plummet during the 2023 stress.", "date": "2026-08-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag071", "title_zh": "\u57fa\u4e8e\u89c4\u6a21\u7684\u76d1\u7ba1\u4e0e\u94f6\u884c\u8106\u5f31\u6027\uff1a\u6765\u81ea\u5bcc\u56fd\u94f6\u884c\u8d44\u4ea7\u4e0a\u9650\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u4e3b\u5f20\uff0c\u5bf9\u5927\u578b\u94f6\u884c\u7684\u52a0\u5f3a\u76d1\u7ba1\u5bfc\u81f4\u4e862023\u5e74\u533a\u57df\u6027\u94f6\u884c\u5371\u673a\u4e2d\u8f83\u5c0f\u94f6\u884c\u8106\u5f31\u6027\u7684\u4e0a\u5347\u30022018\u5e74\uff0c\u76d1\u7ba1\u673a\u6784\u9650\u5236\u4e86\u7f8e\u56fd\u7b2c\u4e09\u5927\u94f6\u884c\u5bcc\u56fd\u94f6\u884c\u6269\u5927\u5176\u603b\u8d44\u4ea7\u3002\u6211\u4eec\u4f30\u8ba1\uff0c\u8fd9\u4e00\u8d44\u4ea7\u4e0a\u9650\u5bfc\u81f4\u5bcc\u56fd\u94f6\u884c\u653e\u5f03\u4e86\u76f8\u5f53\u4e8e\u5168\u90e8\u94f6\u884c\u5b58\u6b3e2.2%\u7684\u5b58\u6b3e\u3002\u8fd9\u4e9b\u5b58\u6b3e\u4e3b\u8981\u672a\u6295\u4fdd\uff0c\u88ab\u91cd\u65b0\u5206\u914d\u5230\u5730\u7406\u4e0a\u9760\u8fd1\u5bcc\u56fd\u94f6\u884c\u7684\u94f6\u884c\uff0c\u5305\u62ec\u89c4\u6a21\u8f83\u5c0f\u4e14\u76d1\u7ba1\u8f83\u5f31\u7684\u94f6\u884c\u3002\u968f\u540e\uff0c\u5728\u8d27\u5e01\u653f\u7b56\u6536\u7d27\u5f00\u59cb\u65f6\uff0c\u8fd9\u4e9b\u94f6\u884c\u7ecf\u5386\u4e86\u66f4\u9ad8\u7684\u5b58\u6b3e\u6d41\u51fa\uff0c\u5e76\u57282023\u5e74\u7684\u538b\u529b\u671f\u95f4\u80a1\u4ef7\u5927\u5e45\u4e0b\u8dcc\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70072", "journal": "JF", "title": "Board Dynamics over the Startup Life Cycle", "authors": ["MICHAEL EWENS", "NADYA MALENKO"], "author_details": [{"name": "MICHAEL EWENS", "affiliations": []}, {"name": "NADYA MALENKO", "affiliations": []}], "abstract": "ABSTRACT We explore the dynamics of venture capital (VC)\u2010backed startup boards using novel data on director entry, exit, and characteristics. At formation, a typical board is entrepreneur\u2010controlled. Independent directors join the median board after the second financing and hold a tie\u2010breaking vote. Their presence is particularly likely when potential VC\u2010entrepreneur conflicts are larger. At later stages, control switches to VCs and independent director characteristics change. These patterns align with key financial contracting theories, but also highlight unique roles of independent directors over the life cycle: mediation followed by advising. Independent directors thus represent another potential source of value\u2010add to startup performance.", "date": "2026-08-02", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70072", "title_zh": "\u521b\u4e1a\u516c\u53f8\u751f\u547d\u5468\u671f\u4e2d\u7684\u8463\u4e8b\u4f1a\u52a8\u6001", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u7528\u5173\u4e8e\u8463\u4e8b\u8fdb\u5165\u3001\u9000\u51fa\u53ca\u5176\u7279\u5f81\u7684\u65b0\u578b\u6570\u636e\uff0c\u7814\u7a76\u4e86\u88ab\u98ce\u9669\u6295\u8d44\u652f\u6301\u7684\u521b\u4e1a\u516c\u53f8\u8463\u4e8b\u4f1a\u7684\u52a8\u6001\u53d8\u5316\u3002\u5728\u516c\u53f8\u6210\u7acb\u521d\u671f\uff0c\u5178\u578b\u7684\u8463\u4e8b\u4f1a\u7531\u521b\u59cb\u4eba\u63a7\u5236\u3002\u5728\u7b2c\u4e8c\u6b21\u878d\u8d44\u4e4b\u540e\uff0c\u72ec\u7acb\u8463\u4e8b\u8fdb\u5165\u8463\u4e8b\u4f1a\u7684\u4e2d\u4f4d\u6570\u60c5\u51b5\uff0c\u5e76\u83b7\u5f97\u6295\u7968\u5236\u8861\u6743\u3002\u5f53\u6f5c\u5728\u7684\u98ce\u9669\u6295\u8d44\u4e0e\u521b\u59cb\u4eba\u4e4b\u95f4\u7684\u51b2\u7a81\u8f83\u5927\u65f6\uff0c\u72ec\u7acb\u8463\u4e8b\u7684\u52a0\u5165\u6982\u7387\u66f4\u9ad8\u3002\u5728\u540e\u671f\u9636\u6bb5\uff0c\u63a7\u5236\u6743\u8f6c\u79fb\u81f3\u98ce\u9669\u6295\u8d44\u65b9\uff0c\u72ec\u7acb\u8463\u4e8b\u7684\u7279\u5f81\u4e5f\u53d1\u751f\u6539\u53d8\u3002\u8fd9\u4e9b\u6a21\u5f0f\u4e0e\u5173\u952e\u7684\u91d1\u878d\u5951\u7ea6\u7406\u8bba\u76f8\u4e00\u81f4\uff0c\u540c\u65f6\u4e5f\u51f8\u663e\u4e86\u72ec\u7acb\u8463\u4e8b\u5728\u516c\u53f8\u751f\u547d\u5468\u671f\u4e2d\u72ec\u7279\u7684\u89d2\u8272\uff1a\u5148\u8fdb\u884c\u8c03\u89e3\uff0c\u540e\u63d0\u4f9b\u5efa\u8bae\u3002\u56e0\u6b64\uff0c\u72ec\u7acb\u8463\u4e8b\u662f\u521b\u4e1a\u516c\u53f8\u7ee9\u6548\u4e2d\u53e6\u4e00\u4e2a\u6f5c\u5728\u7684\u4ef7\u503c\u6765\u6e90\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20250295", "journal": "AER", "title": "Additionality and Asymmetric Information in Environmental Markets: Evidence from Conservation Auctions", "authors": ["Karl M. Aspelund", "Anna Russo"], "author_details": [{"name": "Karl M. Aspelund", "affiliations": ["Yale School of the Environment (email: )"]}, {"name": "Anna Russo", "affiliations": ["Harvard University (email: )"]}], "abstract": "Mechanisms that aim to reduce environmental degradation at low cost can be undermined when participants' conservation actions are not marginal to the incentive\u2014or \u201cadditional\u201d\u2014as the lowest-cost participants may not be the highest social value. We investigate this challenge in the Conservation Reserve Program's auction mechanism for ecosystem services, linking bids to satellite-derived land use. Three-quarters of marginal auction winners are not additional. The heterogeneity in counterfactual land use introduces adverse selection. We develop a model of bidding and additionality to quantify welfare implications. Alternative auctions increase efficiency by using scoring rules that incorporate expected land use impacts. (JEL D44, D82, Q24, Q57, R14)", "date": "2026-08-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20250295", "title_zh": "\u73af\u5883\u5e02\u573a\u4e2d\u7684\u9644\u52a0\u6027\u4e0e\u4fe1\u606f\u4e0d\u5bf9\u79f0\uff1a\u6765\u81ea\u751f\u6001\u4fdd\u62a4\u62cd\u5356\u7684\u8bc1\u636e", "abstract_zh": "\u65e8\u5728\u4ee5\u4f4e\u6210\u672c\u51cf\u5c11\u73af\u5883\u9000\u5316\u7684\u673a\u5236\uff0c\u5f53\u53c2\u4e0e\u8005\u7684\u884c\u4e3a\u5e76\u975e\u8fb9\u9645\u6027\u2014\u2014\u5373\u7f3a\u4e4f\u2018\u9644\u52a0\u6027\u2019\u2014\u2014\u65f6\uff0c\u53ef\u80fd\u88ab\u524a\u5f31\uff0c\u56e0\u4e3a\u6210\u672c\u6700\u4f4e\u7684\u53c2\u4e0e\u8005\u672a\u5fc5\u5177\u6709\u6700\u9ad8\u7684\u793e\u4f1a\u4ef7\u503c\u3002\u6211\u4eec\u7814\u7a76\u4e86\u8fd9\u4e00\u6311\u6218\uff0c\u4ee5\u7f8e\u56fd\u751f\u6001\u4fdd\u62a4\u50a8\u5907\u8ba1\u5212\u4e2d\u7684\u751f\u6001\u7cfb\u7edf\u670d\u52a1\u62cd\u5356\u673a\u5236\u4e3a\u4f8b\uff0c\u5c06\u6295\u6807\u4e0e\u536b\u661f\u9065\u611f\u7684\u571f\u5730\u5229\u7528\u6570\u636e\u76f8\u8054\u7cfb\u3002\u5728\u8fb9\u9645\u62cd\u5356\u4e2d\u6807\u8005\u4e2d\uff0c\u6709\u56db\u5206\u4e4b\u4e09\u5e76\u975e\u771f\u6b63\u5177\u6709\u9644\u52a0\u6027\u3002\u53cd\u4e8b\u5b9e\u571f\u5730\u5229\u7528\u7684\u5f02\u8d28\u6027\u5bfc\u81f4\u4e86\u9006\u5411\u9009\u62e9\u95ee\u9898\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6295\u6807\u4e0e\u9644\u52a0\u6027\u76f8\u5173\u7684\u6a21\u578b\uff0c\u4ee5\u91cf\u5316\u798f\u5229\u5f71\u54cd\u3002\u91c7\u7528\u5c06\u9884\u671f\u571f\u5730\u5229\u7528\u5f71\u54cd\u7eb3\u5165\u5176\u4e2d\u7684\u8bc4\u5206\u89c4\u5219\u7684\u66ff\u4ee3\u6027\u62cd\u5356\u673a\u5236\uff0c\u80fd\u591f\u63d0\u5347\u6548\u7387\u3002\uff08JEL D44, D82, Q24, Q57, R14\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20250305", "journal": "AER", "title": "Community Engagement and Public Safety: Evidence from Crime Enforcement Targeting Immigrants", "authors": ["Felipe Gon\u00e7alves", "Elisa J\u00e1come", "Emily Weisburst"], "author_details": [{"name": "Felipe Gon\u00e7alves", "affiliations": ["University of California, Los Angeles and NBER (email: )"]}, {"name": "Elisa J\u00e1come", "affiliations": ["Northwestern University and NBER (email: )"]}, {"name": "Emily Weisburst", "affiliations": ["University of California, Los Angeles and NBER (email: )"]}], "abstract": "We study the role of victim reporting in the production of public safety. We examine the Secure Communities program, a crime-reduction policy that involved police in detecting unauthorized immigrants and increased deportation fears in immigrant communities. We find that the policy reduced the likelihood that Hispanic victims report crimes to police and increased offending against Hispanics. The number of reported crimes is unchanged, masking these opposing effects. We show that reduced reporting drives the offending increase and provide the first elasticity of offending to victim reporting in the literature, calculating that a 10 percent decline in reporting increases offending by 7.9 percent. (JEL J15, K37, K42)", "date": "2026-08-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20250305", "title_zh": "\u793e\u533a\u53c2\u4e0e\u4e0e\u516c\u5171\u5b89\u5168\uff1a\u6765\u81ea\u5bf9\u79fb\u6c11\u5b9e\u65bd\u72af\u7f6a\u6267\u6cd5\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u53d7\u5bb3\u8005\u62a5\u6848\u5728\u516c\u5171\u5b89\u5168\u5f62\u6210\u4e2d\u7684\u4f5c\u7528\u3002\u6211\u4eec\u8003\u5bdf\u4e86\u2018\u5b89\u5168\u793e\u533a\u2019\u8ba1\u5212\uff0c\u8fd9\u662f\u4e00\u4e2a\u6d89\u53ca\u8b66\u65b9\u53d1\u73b0\u65e0\u8bc1\u79fb\u6c11\u5e76\u52a0\u5267\u79fb\u6c11\u793e\u533a\u9063\u8fd4\u6050\u60e7\u7684\u72af\u7f6a\u51cf\u5c11\u653f\u7b56\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8be5\u653f\u7b56\u964d\u4f4e\u4e86\u897f\u73ed\u7259\u88d4\u53d7\u5bb3\u8005\u5411\u8b66\u65b9\u62a5\u6848\u7684\u53ef\u80fd\u6027\uff0c\u5e76\u589e\u52a0\u4e86\u5bf9\u897f\u73ed\u7259\u88d4\u7fa4\u4f53\u7684\u72af\u7f6a\u884c\u4e3a\u3002\u62a5\u544a\u7684\u72af\u7f6a\u6570\u91cf\u672a\u53d1\u751f\u53d8\u5316\uff0c\u63a9\u76d6\u4e86\u8fd9\u4e9b\u76f8\u53cd\u7684\u5f71\u54cd\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u62a5\u6848\u51cf\u5c11\u662f\u72af\u7f6a\u589e\u52a0\u7684\u539f\u56e0\uff0c\u5e76\u5728\u6587\u732e\u4e2d\u9996\u6b21\u63d0\u4f9b\u4e86\u72af\u7f6a\u884c\u4e3a\u5bf9\u53d7\u5bb3\u8005\u62a5\u6848\u7684\u5f39\u6027\uff0c\u8ba1\u7b97\u51fa\u62a5\u6848\u4e0b\u964d10%\u5c06\u5bfc\u81f4\u72af\u7f6a\u884c\u4e3a\u589e\u52a07.9%\u3002\uff08JEL J15, K37, K42\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20231414", "journal": "AER", "title": "Remote Work and City Structure", "authors": ["Ferdinando Monte", "Charly Porcher", "Esteban Rossi-Hansberg"], "author_details": [{"name": "Ferdinando Monte", "affiliations": ["McDonough School of Business, Georgetown University (email: )"]}, {"name": "Charly Porcher", "affiliations": ["Georgetown McDonough School of Business, Georgetown University (email: )"]}, {"name": "Esteban Rossi-Hansberg", "affiliations": ["University of Chicago (email: )"]}], "abstract": "Relative to remote work, working downtown facilitates valuable interactions with other in-office workers but entails commuting costs. The resulting coordination mechanism can lead to multiple stationary equilibria with varying levels of remote work. Temporary reductions in commuters, as in the COVID-19 pandemic, can lead to persistently large fractions of remote workers. Cell phone-based mobility data for the United States shows commuting trips in the largest cities, which are more likely to exhibit multiplicity, have stabilized at only 60 percent of prepandemic levels, while they are fully back in smaller cities. Cities with permanently low commuting experience average welfare losses of 2.3 percent. (JEL I12, J22, M54, R23, R31)", "date": "2026-08-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20231414", "title_zh": "\u8fdc\u7a0b\u529e\u516c\u4e0e\u57ce\u5e02\u7ed3\u6784", "abstract_zh": "\u4e0e\u8fdc\u7a0b\u529e\u516c\u76f8\u6bd4\uff0c\u524d\u5f80\u5e02\u4e2d\u5fc3\u529e\u516c\u6709\u52a9\u4e8e\u4e0e\u5176\u4ed6\u5728\u5c97\u5458\u5de5\u8fdb\u884c\u6709\u4ef7\u503c\u7684\u4e92\u52a8\uff0c\u4f46\u9700\u8981\u627f\u62c5\u901a\u52e4\u6210\u672c\u3002\u8fd9\u79cd\u534f\u8c03\u673a\u5236\u53ef\u80fd\u5bfc\u81f4\u8fdc\u7a0b\u529e\u516c\u6bd4\u4f8b\u5b58\u5728\u591a\u4e2a\u7a33\u5b9a\u5747\u8861\u72b6\u6001\u3002\u65b0\u51a0\u75ab\u60c5\u5bfc\u81f4\u7684\u901a\u52e4\u8005\u77ed\u671f\u51cf\u5c11\uff0c\u53ef\u80fd\u4f7f\u8fdc\u7a0b\u529e\u516c\u6bd4\u4f8b\u957f\u671f\u7ef4\u6301\u5728\u8f83\u9ad8\u6c34\u5e73\u3002\u7f8e\u56fd\u57fa\u4e8e\u624b\u673a\u7684\u79fb\u52a8\u6570\u636e\u8868\u660e\uff0c\u5927\u57ce\u5e02\u4e2d\u7684\u901a\u52e4 trips \u5df2\u7a33\u5b9a\u5728\u75ab\u60c5\u524d\u6c34\u5e73\u768460%\uff0c\u800c\u8f83\u5c0f\u57ce\u5e02\u5219\u5df2\u5b8c\u5168\u6062\u590d\u81f3\u75ab\u60c5\u524d\u6c34\u5e73\u3002\u90a3\u4e9b\u957f\u671f\u901a\u52e4\u91cf\u8f83\u4f4e\u7684\u57ce\u5e02\u5e73\u5747\u798f\u5229\u635f\u5931\u4e3a2.3%\u3002\uff08JEL I12, J22, M54, R23, R31\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240617", "journal": "AER", "title": "Designing Dynamic Reassignment Mechanisms: Evidence from GP Allocation", "authors": ["Ingrid Huitfeldt", "Victoria Marone", "Daniel Waldinger"], "author_details": [{"name": "Ingrid Huitfeldt", "affiliations": ["Department of Economics, BI Norwegian Business School (email: )"]}, {"name": "Victoria Marone", "affiliations": ["Department of Economics, Yale University (email: )"]}, {"name": "Daniel Waldinger", "affiliations": ["Department of Economics, New York University (email: )"]}], "abstract": "We study the problem of designing a dynamic reassignment mechanism when agents' preferences over objects change over time. In the context of Norway's system for (re)assigning patients to general practitioners (GPs), we provide direct evidence of misallocation under the current mechanism\u2014patients waiting for each others' GPs, but who cannot trade\u2014and estimate a structural model of GP-switching behavior to evaluate alternatives. Introducing top trading cycles (TTC) would, on average, reduce waiting times and increase patient welfare. However, patients endowed with less desirable GPs would be harmed. Prioritizing these patients can avoid these harms while preserving most of the gains from TTC. (JEL D82, H51, I11, I13, I18)", "date": "2026-08-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240617", "title_zh": "\u8bbe\u8ba1\u52a8\u6001\u91cd\u65b0\u5206\u914d\u673a\u5236\uff1a\u6765\u81eaGP\u5206\u914d\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5f53\u4ee3\u7406\u4eba\u5bf9\u7269\u54c1\u7684\u504f\u597d\u968f\u65f6\u95f4\u53d8\u5316\u65f6\uff0c\u8bbe\u8ba1\u52a8\u6001\u91cd\u65b0\u5206\u914d\u673a\u5236\u7684\u95ee\u9898\u3002\u5728\u632a\u5a01\u5c06\u60a3\u8005\u91cd\u65b0\u5206\u914d\u7ed9\u5168\u79d1\u533b\u751f\uff08GP\uff09\u7684\u7cfb\u7edf\u80cc\u666f\u4e0b\uff0c\u6211\u4eec\u63d0\u4f9b\u4e86\u5f53\u524d\u673a\u5236\u4e0b\u8bef\u5206\u914d\u7684\u76f4\u63a5\u8bc1\u636e\u2014\u2014\u60a3\u8005\u7b49\u5f85\u5f7c\u6b64\u7684GP\uff0c\u4f46\u65e0\u6cd5\u8fdb\u884c\u4ea4\u6362\u2014\u2014\u5e76\u6784\u5efa\u4e86\u4e00\u4e2aGP\u66f4\u6362\u884c\u4e3a\u7684\u7ed3\u6784\u6a21\u578b\uff0c\u4ee5\u8bc4\u4f30\u66ff\u4ee3\u65b9\u6848\u3002\u5f15\u5165\u9876\u7ea7\u4ea4\u6613\u5faa\u73af\uff08TTC\uff09\u5c06\u5e73\u5747\u51cf\u5c11\u7b49\u5f85\u65f6\u95f4\u5e76\u63d0\u9ad8\u60a3\u8005\u798f\u5229\u3002\u7136\u800c\uff0c\u90a3\u4e9b\u62e5\u6709\u8f83\u4e0d\u7406\u60f3GP\u7684\u60a3\u8005\u5c06\u53d7\u5230\u4f24\u5bb3\u3002\u4f18\u5148\u8003\u8651\u8fd9\u4e9b\u60a3\u8005\u53ef\u4ee5\u907f\u514d\u8fd9\u4e9b\u4f24\u5bb3\uff0c\u540c\u65f6\u4fdd\u7559TTC\u5e26\u6765\u7684\u5927\u90e8\u5206\u6536\u76ca\u3002\uff08JEL D82, H51, I11, I13, I18\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20220264", "journal": "AER", "title": "Talent Hoarding in Organizations", "authors": ["Ingrid Haegele"], "author_details": [{"name": "Ingrid Haegele", "affiliations": ["LMU Munich (email: )"]}], "abstract": "Most organizations rely on managers to identify talented workers. However, managers who are evaluated on team performance have an incentive to hoard workers. This study provides the first empirical evidence of talent hoarding using personnel records and survey evidence from a large firm. Talent hoarding is self-reported by three-fourths of managers, is detectable in manager ratings of worker talent, and occurs more frequently under stronger hoarding incentives, proxied by performance-related pay, team size, and talent visibility. Using quasi-random exposure to talent hoarding, I show that hoarding deters internal job applications, inhibiting career progression and altering talent allocation in the firm. (JEL D22, J23, L60, M12, M51, M54)", "date": "2026-08-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20220264", "title_zh": "\u7ec4\u7ec7\u4e2d\u7684\u4eba\u624d\u56e4\u79ef", "abstract_zh": "\u5927\u591a\u6570\u7ec4\u7ec7\u4f9d\u8d56\u7ba1\u7406\u8005\u6765\u8bc6\u522b\u6709\u624d\u80fd\u7684\u5458\u5de5\u3002\u7136\u800c\uff0c\u90a3\u4e9b\u6839\u636e\u56e2\u961f\u7ee9\u6548\u8fdb\u884c\u8bc4\u4f30\u7684\u7ba1\u7406\u8005\u5b58\u5728\u56e4\u79ef\u4eba\u624d\u7684\u52a8\u673a\u3002\u672c\u7814\u7a76\u5229\u7528\u4e00\u5bb6\u5927\u578b\u4f01\u4e1a\u7684\u4eba\u5458\u8bb0\u5f55\u548c\u8c03\u67e5\u6570\u636e\uff0c\u9996\u6b21\u63d0\u4f9b\u4e86\u5173\u4e8e\u4eba\u624d\u56e4\u79ef\u7684\u5b9e\u8bc1\u8bc1\u636e\u3002\u56db\u5206\u4e4b\u4e09\u7684\u7ba1\u7406\u8005\u81ea\u62a5\u5b58\u5728\u4eba\u624d\u56e4\u79ef\u884c\u4e3a\uff0c\u8fd9\u79cd\u884c\u4e3a\u5728\u7ba1\u7406\u8005\u5bf9\u5458\u5de5\u624d\u80fd\u7684\u8bc4\u4ef7\u4e2d\u53ef\u4ee5\u88ab\u68c0\u6d4b\u5230\uff0c\u5e76\u4e14\u5728\u56e4\u79ef\u6fc0\u52b1\u66f4\u5f3a\u7684\u60c5\u51b5\u4e0b\u66f4\u4e3a\u666e\u904d\uff0c\u8fd9\u4e9b\u6fc0\u52b1\u901a\u8fc7\u4e0e\u7ee9\u6548\u6302\u94a9\u7684\u85aa\u916c\u3001\u56e2\u961f\u89c4\u6a21\u4ee5\u53ca\u4eba\u624d\u53ef\u89c1\u6027\u6765\u8861\u91cf\u3002\u901a\u8fc7\u51c6\u968f\u673a\u66b4\u9732\u4e8e\u4eba\u624d\u56e4\u79ef\uff0c\u6211\u8bc1\u660e\u4e86\u4eba\u624d\u56e4\u79ef\u4f1a\u6291\u5236\u5185\u90e8\u5c97\u4f4d\u7533\u8bf7\uff0c\u963b\u788d\u5458\u5de5\u804c\u4e1a\u53d1\u5c55\uff0c\u5e76\u6539\u53d8\u4f01\u4e1a\u4e2d\u4eba\u624d\u7684\u5206\u914d\u3002\uff08JEL D22, J23, L60, M12, M51, M54\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240712", "journal": "AER", "title": "Random Utility with Unobservable Alternatives", "authors": ["Haruki Kono", "Kota Saito", "Alec Sandroni"], "author_details": [{"name": "Haruki Kono", "affiliations": ["MIT (email: )"]}, {"name": "Kota Saito", "affiliations": ["Caltech (email: )"]}, {"name": "Alec Sandroni", "affiliations": ["Caltech (email: )"]}], "abstract": "The random utility model (RUM), a cornerstone in economics, is typically studied under the assumption that choice frequencies of all alternatives are observable. In practice, however, some alternatives have unobservable choice frequencies and are commonly aggregated into a single category called an outside option. We study RUM in such environments and derive a finite, nonredundant system of inequality constraints on observed choice frequencies that characterizes RU-rationalizability. We show that the conventional practice of aggregating unobserved alternatives can miss key information leading to incorrect conclusions such as that observed choices are rationalizable, even when no RUM is consistent with them. (JEL D11, D44, D83)", "date": "2026-08-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240712", "title_zh": "\u968f\u673a\u6548\u7528\u6a21\u578b\u4e2d\u7684\u4e0d\u53ef\u89c2\u6d4b\u66ff\u4ee3\u54c1", "abstract_zh": "\u968f\u673a\u6548\u7528\u6a21\u578b\uff08RUM\uff09\u662f\u7ecf\u6d4e\u5b66\u4e2d\u7684\u4e00\u4e2a\u57fa\u77f3\uff0c\u901a\u5e38\u5728\u6240\u6709\u66ff\u4ee3\u54c1\u7684\u9009\u62e9\u9891\u7387\u5747\u53ef\u89c2\u6d4b\u7684\u5047\u8bbe\u4e0b\u8fdb\u884c\u7814\u7a76\u3002\u7136\u800c\uff0c\u5728\u5b9e\u8df5\u4e2d\uff0c\u67d0\u4e9b\u66ff\u4ee3\u54c1\u7684\u9009\u62e9\u9891\u7387\u662f\u4e0d\u53ef\u89c2\u6d4b\u7684\uff0c\u901a\u5e38\u88ab\u805a\u5408\u4e3a\u4e00\u4e2a\u79f0\u4e3a\u5916\u90e8\u9009\u62e9\u7684\u5355\u4e00\u7c7b\u522b\u3002\u6211\u4eec\u7814\u7a76\u6b64\u7c7b\u73af\u5883\u4e0b\u7684RUM\uff0c\u5e76\u63a8\u5bfc\u51fa\u4e00\u4e2a\u6709\u9650\u4e14\u975e\u5197\u4f59\u7684\u4e0d\u7b49\u5f0f\u7ea6\u675f\u7cfb\u7edf\uff0c\u8be5\u7cfb\u7edf\u57fa\u4e8e\u89c2\u6d4b\u5230\u7684\u9009\u62e9\u9891\u7387\u523b\u753b\u4e86RUM\u7684\u53ef\u7406\u6027\u5316\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5c06\u4e0d\u53ef\u89c2\u6d4b\u7684\u66ff\u4ee3\u54c1\u8fdb\u884c\u805a\u5408\u7684\u4f20\u7edf\u505a\u6cd5\u53ef\u80fd\u4f1a\u9057\u6f0f\u5173\u952e\u4fe1\u606f\uff0c\u4ece\u800c\u5bfc\u81f4\u9519\u8bef\u7ed3\u8bba\uff0c\u4f8b\u5982\u8ba4\u4e3a\u89c2\u6d4b\u5230\u7684\u9009\u62e9\u662f\u53ef\u7406\u6027\u5316\u7684\uff0c\u5373\u4f7f\u6ca1\u6709\u4efb\u4f55RUM\u80fd\u591f\u89e3\u91ca\u8fd9\u4e9b\u9009\u62e9\u3002\uff08JEL D11, D44, D83\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20241007", "journal": "AER", "title": "The Productivity of Professions: Evidence from the Emergency Department", "authors": ["David Chan", "Yiqun Chen"], "author_details": [{"name": "David Chan", "affiliations": ["US Department of Veterans Affairs, UC Berkeley, and NBER (email: )"]}, {"name": "Yiqun Chen", "affiliations": []}], "abstract": "This paper studies the productivity of nurse practitioners (NPs) and physicians, two professions performing overlapping tasks but with starkly different backgrounds, training, and pay. Using quasi-experimental variation in patient assignment to NPs versus physicians in Veterans Health Administration emergency departments, we find that, on average, NPs use more resources and exhibit a higher 30-day preventable hospitalization rate than physicians. However, the NP-physician performance difference varies by case complexity and severity. Importantly, even larger productivity variation exists within each profession, leading to substantial overlap between the productivity distributions of the two professions; NPs outperform physicians in 38 percent of random pairs. (JEL I11, I18, J24, J44, M53)", "date": "2026-08-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20241007", "title_zh": "\u804c\u4e1a\u7684\u751f\u4ea7\u7387\uff1a\u6765\u81ea\u6025\u8bca\u79d1\u7684\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u62a4\u58eb\u6267\u4e1a\u8005\uff08NPs\uff09\u548c\u533b\u751f\u4e24\u79cd\u804c\u4e1a\u7684\u751f\u4ea7\u7387\uff0c\u8fd9\u4e24\u79cd\u804c\u4e1a\u6267\u884c\u7684\u4efb\u52a1\u6709\u91cd\u53e0\uff0c\u4f46\u80cc\u666f\u3001\u57f9\u8bad\u548c\u85aa\u916c\u5374\u622a\u7136\u4e0d\u540c\u3002\u5229\u7528\u7f8e\u56fd\u9000\u4f0d\u519b\u4eba\u5065\u5eb7\u7ba1\u7406\u5c40\u6025\u8bca\u79d1\u60a3\u8005\u5206\u914d\u5230NPs\u4e0e\u533b\u751f\u4e4b\u95f4\u7684\u51c6\u5b9e\u9a8c\u6027\u53d8\u5f02\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5e73\u5747\u800c\u8a00\uff0cNPs\u4f7f\u7528\u7684\u8d44\u6e90\u66f4\u591a\uff0c\u4e1430\u5929\u5185\u53ef\u9884\u9632\u6027\u4f4f\u9662\u7387\u9ad8\u4e8e\u533b\u751f\u3002\u7136\u800c\uff0cNPs\u4e0e\u533b\u751f\u4e4b\u95f4\u7684\u8868\u73b0\u5dee\u5f02\u4f1a\u56e0\u75c5\u4f8b\u7684\u590d\u6742\u6027\u548c\u4e25\u91cd\u7a0b\u5ea6\u800c\u53d8\u5316\u3002\u91cd\u8981\u7684\u662f\uff0c\u6bcf\u4e2a\u804c\u4e1a\u5185\u90e8\u90fd\u5b58\u5728\u663e\u8457\u7684\u751f\u4ea7\u7387\u5dee\u5f02\uff0c\u5bfc\u81f4\u4e24\u79cd\u804c\u4e1a\u7684\u751f\u4ea7\u7387\u5206\u5e03\u6709\u5927\u91cf\u91cd\u53e0\uff1b\u5728\u968f\u673a\u914d\u5bf9\u4e2d\uff0cNPs\u572838%\u7684\u60c5\u51b5\u4e0b\u8868\u73b0\u4f18\u4e8e\u533b\u751f\u3002\uff08JEL I11, I18, J24, J44, M53\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240056", "journal": "AER", "title": "Uncertainty and Change: Survey Evidence of Firms' Subjective Beliefs", "authors": ["R\u00fcdiger Bachmann", "Kai Carstensen", "Stefan Lautenbacher", "Manuel Menkhoff", "Martin Schneider"], "author_details": [{"name": "R\u00fcdiger Bachmann", "affiliations": ["University of Michigan, CEPR, CESifo, ifo Institute, DIW, and IZA (email: )"]}, {"name": "Kai Carstensen", "affiliations": ["Kiel University, CESifo, and ifo Institute (email: )"]}, {"name": "Stefan Lautenbacher", "affiliations": ["Formerly ifo Institute and LMU Munich (email: )"]}, {"name": "Manuel Menkhoff", "affiliations": ["University of Copenhagen, ifo Institute, CESifo, and CEBI (email: )"]}, {"name": "Martin Schneider", "affiliations": ["Stanford University, CEPR, and NBER (email: )"]}], "abstract": "This paper studies how managers plan under uncertainty. In a new panel survey of German manufacturing firms, we observe both forecasts of sales growth and a quantitative measure of subjective uncertainty. We show that subjective uncertainty reflects change experienced by firms: It is high when growth is either unusually low or unusually high. Subjective uncertainty is more than conditional volatility; while more volatile firms are typically more uncertain, experienced change alone increases uncertainty, consistent with a model of learning. Uncertainty over our sample is mostly idiosyncratic but varies substantially over time and leads managers to plan lower employment and prices. (JEL C83, D22, E20, E23)", "date": "2026-08-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240056", "title_zh": "\u4e0d\u786e\u5b9a\u6027\u4e0e\u53d8\u5316\uff1a\u4f01\u4e1a\u4e3b\u89c2\u4fe1\u5ff5\u7684\u8c03\u67e5\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u7ba1\u7406\u8005\u5728\u4e0d\u786e\u5b9a\u6027\u4e0b\u7684\u89c4\u5212\u884c\u4e3a\u3002\u5728\u4e00\u9879\u9488\u5bf9\u5fb7\u56fd\u5236\u9020\u4e1a\u4f01\u4e1a\u7684\u65b0\u578b\u9762\u677f\u8c03\u67e5\u4e2d\uff0c\u6211\u4eec\u89c2\u5bdf\u5230\u9500\u552e\u589e\u957f\u7684\u9884\u6d4b\u4ee5\u53ca\u4e3b\u89c2\u4e0d\u786e\u5b9a\u6027\u7684\u91cf\u5316\u6307\u6807\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u4e3b\u89c2\u4e0d\u786e\u5b9a\u6027\u53cd\u6620\u4e86\u4f01\u4e1a\u6240\u7ecf\u5386\u7684\u53d8\u5316\uff1a\u5f53\u589e\u957f\u5f02\u5e38\u4f4e\u6216\u5f02\u5e38\u9ad8\u65f6\uff0c\u4e0d\u786e\u5b9a\u6027\u6c34\u5e73\u8f83\u9ad8\u3002\u4e3b\u89c2\u4e0d\u786e\u5b9a\u6027\u4e0d\u4ec5\u5305\u62ec\u6761\u4ef6\u6ce2\u52a8\uff0c\u800c\u4e14\u5373\u4f7f\u6ce2\u52a8\u6027\u8f83\u9ad8\u7684\u4f01\u4e1a\u901a\u5e38\u4e5f\u66f4\u4e0d\u786e\u5b9a\uff0c\u4f46\u4f01\u4e1a\u6240\u7ecf\u5386\u7684\u53d8\u5316\u672c\u8eab\u4e5f\u4f1a\u63d0\u5347\u4e0d\u786e\u5b9a\u6027\uff0c\u8fd9\u4e0e\u5b66\u4e60\u6a21\u578b\u76f8\u4e00\u81f4\u3002\u6837\u672c\u4e2d\u7684\u4e0d\u786e\u5b9a\u6027\u4e3b\u8981\u4e3a\u7279\u8d28\u98ce\u9669/\u51b2\u51fb\uff0c\u4f46\u968f\u65f6\u95f4\u663e\u8457\u53d8\u5316\uff0c\u5e76\u5bfc\u81f4\u7ba1\u7406\u8005\u964d\u4f4e\u5c31\u4e1a\u548c\u4ef7\u683c\u7684\u8ba1\u5212\u3002\uff08JEL C83, D22, E20, E23\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240497", "journal": "AER", "title": "Merger Effects and Antitrust Enforcement: Evidence from US Consumer Packaged Goods", "authors": ["Vivek Bhattacharya", "Gast\u00f3n Illanes", "David Stillerman"], "author_details": [{"name": "Vivek Bhattacharya", "affiliations": ["Department of Economics, Northwestern University, and NBER (email: )"]}, {"name": "Gast\u00f3n Illanes", "affiliations": ["Department of Economics, Northwestern University, and NBER (email: )"]}, {"name": "David Stillerman", "affiliations": ["Kogod School of Business, American University (email: )"]}], "abstract": "We document the effects of a comprehensive set of mergers of consumer packaged goods manufacturers on prices, quantities, and product assortment. Across specifications, we find a small average price effect of mergers (\u22120.5\u22121.1 percent) but substantial heterogeneity, with a standard deviation between 3.9 and 7.6 percentage points. Through a model of enforcement, we find that agencies act as if they challenge mergers they expect would increase prices more than 4.8 to 6.3 percent. Increases in stringency would reduce prices and the prevalence of completed price-increasing mergers, with minimal impacts on blocked price-decreasing mergers, at significantly greater agency burden. (JEL D43, G34, K21, L13, L41, L66)", "date": "2026-08-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240497", "title_zh": "\u5e76\u8d2d\u6548\u5e94\u4e0e\u53cd\u5784\u65ad\u6267\u6cd5\uff1a\u6765\u81ea\u7f8e\u56fd\u6d88\u8d39\u7c7b\u5305\u88c5\u5546\u54c1\u884c\u4e1a\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u8bb0\u5f55\u4e86\u6d88\u8d39\u7c7b\u5305\u88c5\u5546\u54c1\u5236\u9020\u5546\u4e00\u7cfb\u5217\u5e76\u8d2d\u5bf9\u4ef7\u683c\u3001\u6570\u91cf\u548c\u4ea7\u54c1\u7ec4\u5408\u7684\u5f71\u54cd\u3002\u5728\u4e0d\u540c\u6a21\u578b\u8bbe\u5b9a\u4e0b\uff0c\u6211\u4eec\u53d1\u73b0\u5e76\u8d2d\u7684\u5e73\u5747\u4ef7\u683c\u6548\u5e94\u8f83\u5c0f\uff08\u22120.5\u81f3\u22121.1\u4e2a\u767e\u5206\u70b9\uff09\uff0c\u4f46\u5b58\u5728\u663e\u8457\u5f02\u8d28\u6027\uff0c\u6807\u51c6\u5dee\u57283.9\u81f37.6\u4e2a\u767e\u5206\u70b9\u4e4b\u95f4\u3002\u901a\u8fc7\u53cd\u5784\u65ad\u6267\u6cd5\u6a21\u578b\uff0c\u6211\u4eec\u53d1\u73b0\u76d1\u7ba1\u673a\u6784\u7684\u884c\u4e3a\u7c7b\u4f3c\u4e8e\u5bf9\u9884\u8ba1\u4f1a\u63d0\u9ad8\u4ef7\u683c\u8d85\u8fc74.8\u81f36.3\u4e2a\u767e\u5206\u70b9\u7684\u5e76\u8d2d\u63d0\u51fa\u6311\u6218\u3002\u6267\u6cd5\u529b\u5ea6\u7684\u63d0\u5347\u5c06\u964d\u4f4e\u4ef7\u683c\u5e76\u51cf\u5c11\u5df2\u5b8c\u6210\u7684\u63d0\u4ef7\u5e76\u8d2d\uff0c\u5bf9\u88ab\u963b\u6b62\u7684\u964d\u4ef7\u5e76\u8d2d\u5f71\u54cd\u6781\u5c0f\uff0c\u4f46\u4f1a\u663e\u8457\u589e\u52a0\u76d1\u7ba1\u673a\u6784\u7684\u8d1f\u62c5\u3002\uff08JEL D43, G34, K21, L13, L41, L66\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1257/aer.20240094", "journal": "AER", "title": "Energy Transitions in Regulated Markets", "authors": ["Gautam Gowrisankaran", "Ashley Langer", "Mar Reguant"], "author_details": [{"name": "Gautam Gowrisankaran", "affiliations": ["Columbia University, CEPR, and NBER (email: )"]}, {"name": "Ashley Langer", "affiliations": ["University of Arizona and NBER (email: )"]}, {"name": "Mar Reguant", "affiliations": ["ICREA-IAE-CSIC, BSE, CEPR, and NBER (email: )"]}], "abstract": "Natural gas has replaced coal as the dominant fuel for US electricity generation. However, utilities in regulated US states have retired coal more slowly than others. We build a structural model of rate-of-return regulation during an energy transition where utilities face trade-offs between lowering costs and maintaining and using legacy capacity. A regulated utility facing carbon taxes lowers short-run coal generation 48 percent as much as a cost minimizer would. Thirty years after a sudden energy transition, a cost minimizer has retired 71 percent more coal capacity than the regulated utility. Alternative regulations may jeopardize affordability and reliability goals during energy transitions. (JEL D24, L94, L98, Q35, Q48)", "date": "2026-08-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240094", "title_zh": "\u53d7\u76d1\u7ba1\u5e02\u573a\u4e2d\u7684\u80fd\u6e90\u8f6c\u578b", "abstract_zh": "\u5929\u7136\u6c14\u5df2\u53d6\u4ee3\u7164\u70ad\u6210\u4e3a\u7f8e\u56fd\u7535\u529b\u53d1\u7535\u7684\u4e3b\u8981\u71c3\u6599\u3002\u7136\u800c\uff0c\u7f8e\u56fd\u53d7\u76d1\u7ba1\u5dde\u7684\u516c\u7528\u4e8b\u4e1a\u516c\u53f8\u6dd8\u6c70\u7164\u70ad\u7684\u901f\u5ea6\u6bd4\u5176\u4ed6\u5730\u533a\u66f4\u6162\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5173\u4e8e\u5728\u80fd\u6e90\u8f6c\u578b\u8fc7\u7a0b\u4e2d\u5b9e\u65bd\u6536\u76ca\u7387\u76d1\u7ba1\u7684\u7ed3\u6784\u5316\u6a21\u578b\uff0c\u5176\u4e2d\u516c\u7528\u4e8b\u4e1a\u516c\u53f8\u5728\u964d\u4f4e\u6210\u672c\u4e0e\u7ef4\u6301\u548c\u4f7f\u7528\u539f\u6709\u4ea7\u80fd\u4e4b\u95f4\u9762\u4e34\u6743\u8861\u3002\u5728\u9762\u4e34\u78b3\u7a0e\u7684\u60c5\u51b5\u4e0b\uff0c\u53d7\u76d1\u7ba1\u7684\u516c\u7528\u4e8b\u4e1a\u516c\u53f8\u51cf\u5c11\u77ed\u671f\u7164\u70ad\u53d1\u7535\u91cf\u7684\u7a0b\u5ea6\uff0c\u4ec5\u4e3a\u6210\u672c\u6700\u5c0f\u5316\u8005\u768448%\u3002\u5728\u80fd\u6e90\u8f6c\u578b\u7a81\u7136\u53d1\u751f30\u5e74\u540e\uff0c\u6210\u672c\u6700\u5c0f\u5316\u8005\u6dd8\u6c70\u7684\u7164\u70ad\u4ea7\u80fd\u6bd4\u53d7\u76d1\u7ba1\u7684\u516c\u7528\u4e8b\u4e1a\u516c\u53f8\u591a\u51fa71%\u3002\u5176\u4ed6\u7c7b\u578b\u7684\u76d1\u7ba1\u53ef\u80fd\u5728\u80fd\u6e90\u8f6c\u578b\u8fc7\u7a0b\u4e2d\u5371\u53ca\u53ef\u8d1f\u62c5\u6027\u548c\u53ef\u9760\u6027\u76ee\u6807\u3002\uff08JEL D24, L94, L98, Q35, Q48\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20231696", "journal": "AER", "title": "Professional Motivations in the Public Sector: Evidence from Police Officers", "authors": ["Aaron Chalfin", "Felipe Gon\u00e7alves"], "author_details": [{"name": "Aaron Chalfin", "affiliations": ["University of Pennsylvania and NBER (email: )"]}, {"name": "Felipe Gon\u00e7alves", "affiliations": ["University of California, Los Angeles and NBER (email: )"]}], "abstract": "We study how public sector workers balance their professional motivations with private economic concerns, focusing on police arrests. Arrests made near the end of an officer's shift typically require overtime work, and officers respond by reducing arrest frequency but increasing arrest quality. Days in which an officer works a second job after their police shift have higher opportunity cost, also reducing late-shift arrests. Combining our estimates in a dynamic model identifies officer preferences over workplace activity and overtime work. Our results indicate that officers' private costs of arrests have a first-order impact on the quantity and quality of enforcement. (JEL K42, J33, J45)", "date": "2026-08-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20231696", "title_zh": "\u516c\u5171\u90e8\u95e8\u5de5\u4f5c\u4eba\u5458\u7684\u804c\u4e1a\u52a8\u673a\u4e0e\u79c1\u4eba\u7ecf\u6d4e\u8003\u91cf\uff1a\u6765\u81ea\u8b66\u5bdf\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u516c\u5171\u90e8\u95e8\u5de5\u4f5c\u4eba\u5458\u5982\u4f55\u5728\u804c\u4e1a\u52a8\u673a\u4e0e\u79c1\u4eba\u7ecf\u6d4e\u5173\u5207\u4e4b\u95f4\u53d6\u5f97\u5e73\u8861\uff0c\u91cd\u70b9\u5173\u6ce8\u8b66\u5bdf\u7684\u902e\u6355\u884c\u4e3a\u3002\u5728\u6267\u52e4\u7ed3\u675f\u9644\u8fd1\u8fdb\u884c\u7684\u902e\u6355\u901a\u5e38\u9700\u8981\u52a0\u73ed\uff0c\u8b66\u5bdf\u56e0\u6b64\u4f1a\u51cf\u5c11\u902e\u6355\u9891\u7387\u4f46\u63d0\u9ad8\u902e\u6355\u8d28\u91cf\u3002\u5728\u6267\u52e4\u540e\u4ece\u4e8b\u7b2c\u4e8c\u4efd\u5de5\u4f5c\u7684\u65e5\u5b50\u91cc\uff0c\u673a\u4f1a\u6210\u672c\u66f4\u9ad8\uff0c\u4e5f\u4f1a\u51cf\u5c11\u665a\u73ed\u7684\u902e\u6355\u884c\u4e3a\u3002\u5c06\u6211\u4eec\u7684\u4f30\u8ba1\u7ed3\u679c\u7eb3\u5165\u52a8\u6001\u6a21\u578b\uff0c\u8bc6\u522b\u51fa\u8b66\u5bdf\u5bf9\u5de5\u4f5c\u6d3b\u52a8\u548c\u52a0\u73ed\u5de5\u4f5c\u7684\u504f\u597d\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u8b66\u5bdf\u5bf9\u902e\u6355\u7684\u79c1\u4eba\u6210\u672c\u5bf9\u5176\u6267\u6cd5\u6570\u91cf\u548c\u8d28\u91cf\u5177\u6709\u9996\u8981\u5f71\u54cd\u3002(JEL K42, J33, J45)", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag070", "journal": "RFS", "title": "Stocks as Lotteries? An Experimental Test of Expected Utility versus Behavioral Models", "authors": ["Brice Corgnet", "Yao Thibaut Kpegli", "Jacopo Magnani"], "author_details": [{"name": "Brice Corgnet", "affiliations": ["Emlyon Business School, CNRS, Universit\u00e9 Lumi\u00e8re Lyon 2, Universit\u00e9 Jean Monnet Saint-Etienne ,"]}, {"name": "Yao Thibaut Kpegli", "affiliations": ["Universit\u00e9 de Pau et des Pays de l\u2019Adour ,"]}, {"name": "Jacopo Magnani", "affiliations": ["Norwegian University of Science and Technology ,"]}], "abstract": "Abstract Our study provides the first causal test of classical and behavioral asset pricing models that incorporate skewness pricing. In line with these models, our experimental markets show that skewness is systematically priced. Our findings also reveal that positively skewed assets available in small supply exhibit negative expected returns, which is consistent with prospect theory, but not with expected utility models. Furthermore, in line with the mechanism underlying prospect theory, we show that the negative returns of the positively skewed asset are most pronounced during market sessions where traders overweight the low probability of receiving a large payoff.", "date": "2026-07-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag070", "title_zh": "\u80a1\u7968\u662f\u5f69\u7968\u5417\uff1f\u4e00\u79cd\u9884\u671f\u6548\u7528\u4e0e\u884c\u4e3a\u6a21\u578b\u7684\u5b9e\u9a8c\u68c0\u9a8c", "abstract_zh": "\u6211\u4eec\u7684\u7814\u7a76\u9996\u6b21\u5bf9\u5305\u542b\u504f\u5ea6\u5b9a\u4ef7\u7684\u7ecf\u5178\u548c\u884c\u4e3a\u8d44\u4ea7\u5b9a\u4ef7\u6a21\u578b\u8fdb\u884c\u4e86\u56e0\u679c\u68c0\u9a8c\u3002\u6839\u636e\u8fd9\u4e9b\u6a21\u578b\uff0c\u6211\u4eec\u7684\u5b9e\u9a8c\u5e02\u573a\u663e\u793a\uff0c\u504f\u5ea6\u786e\u5b9e\u88ab\u7cfb\u7edf\u6027\u5730\u5b9a\u4ef7\u3002\u6211\u4eec\u7684\u53d1\u73b0\u8fd8\u8868\u660e\uff0c\u4f9b\u5e94\u91cf\u8f83\u5c0f\u7684\u6b63\u504f\u6001\u8d44\u4ea7\u8868\u73b0\u51fa\u8d1f\u7684\u9884\u671f\u6536\u76ca\u7387\uff0c\u8fd9\u4e0e\u524d\u666f\u7406\u8bba\u4e00\u81f4\uff0c\u4f46\u4e0e\u9884\u671f\u6548\u7528\u6a21\u578b\u4e0d\u7b26\u3002\u6b64\u5916\uff0c\u7b26\u5408\u524d\u666f\u7406\u8bba\u673a\u5236\uff0c\u6211\u4eec\u53d1\u73b0\u6b63\u504f\u6001\u8d44\u4ea7\u5728\u4ea4\u6613\u8005\u8fc7\u5ea6\u91cd\u89c6\u4f4e\u6982\u7387\u83b7\u5f97\u5927\u6536\u76ca\u7684\u5e02\u573a\u65f6\u6bb5\u4e2d\uff0c\u5176\u8d1f\u6536\u76ca\u7387\u6700\u4e3a\u663e\u8457\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag080", "journal": "REStud", "title": "An Evaluation of Protected Area Policies in the European Union", "authors": ["Tristan Earle Grupp", "Prakash Mishra", "Mathias Reynaert", "Arthur A van Benthem"], "author_details": [{"name": "Tristan Earle Grupp", "affiliations": ["University of Pennsylvania ,"]}, {"name": "Prakash Mishra", "affiliations": ["California Institute of Technology ,"]}, {"name": "Mathias Reynaert", "affiliations": ["Toulouse School of Economics, University of Toulouse Capitole ,"]}, {"name": "Arthur A van Benthem", "affiliations": ["University of Pennsylvania ,"]}], "abstract": "Abstract The European Union (EU) designates 26% of its landmass as protected areas, limiting economic development for biodiversity. We use the staggered introduction of protected areas between 1985 and 2019 to study the selection of protected land and the causal effect of protection on vegetation cover and nightlights. We find no meaningful impacts on either outcome across four decades, countries, protection cohorts, or land characteristics. These null effects are consistent with the political economy of EU land protection: weak incentives to internalize biodiversity gains, green-glow motives, and area-based targets shape local siting and stringency choices. In practice, strict protection is applied where development pressure is low\u2013so that protection has little bite\u2014while in high-pressure regions, protection is typically weak, imposing only limited constraints on economic activity.", "date": "2026-07-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag080", "title_zh": "\u5bf9\u6b27\u76df\u4fdd\u62a4\u533a\u653f\u7b56\u7684\u8bc4\u4f30", "abstract_zh": "\u6458\u8981 \u6b27\u76df\u5c0626%\u7684\u9646\u5730\u9762\u79ef\u5212\u4e3a\u4fdd\u62a4\u533a\uff0c\u9650\u5236\u4e86\u751f\u7269\u591a\u6837\u6027\u7684\u53d1\u5c55\u3002\u6211\u4eec\u5229\u75281985\u5e74\u81f32019\u5e74\u95f4\u4fdd\u62a4\u533a\u5206\u9636\u6bb5\u5f15\u5165\u7684\u7279\u5f81\uff0c\u7814\u7a76\u4fdd\u62a4\u533a\u9009\u5740\u4ee5\u53ca\u4fdd\u62a4\u5bf9\u690d\u88ab\u8986\u76d6\u548c\u591c\u5149\u4eae\u5ea6\u7684\u56e0\u679c\u6548\u5e94\u3002\u5728\u56db\u5341\u5e74\u3001\u56fd\u5bb6\u3001\u4fdd\u62a4\u6279\u6b21\u4ee5\u53ca\u571f\u5730\u7279\u5f81\u65b9\u9762\uff0c\u6211\u4eec\u5747\u672a\u53d1\u73b0\u5bf9\u4efb\u4e00\u7ed3\u679c\u7684\u663e\u8457\u5f71\u54cd\u3002\u8fd9\u4e9b\u96f6\u6548\u5e94\u4e0e\u6b27\u76df\u571f\u5730\u4fdd\u62a4\u7684\u653f\u6cbb\u7ecf\u6d4e\u5b66\u4e00\u81f4\uff1a\u5185\u90e8\u5316\u751f\u7269\u591a\u6837\u6027\u6536\u76ca\u7684\u6fc0\u52b1\u8584\u5f31\u3001\u7eff\u8272\u5149\u8292\u52a8\u673a\u4ee5\u53ca\u57fa\u4e8e\u9762\u79ef\u7684\u76ee\u6807\uff0c\u5f71\u54cd\u4e86\u5730\u65b9\u7684\u9009\u5740\u548c\u4e25\u683c\u7a0b\u5ea6\u9009\u62e9\u3002\u5b9e\u9645\u4e0a\uff0c\u4e25\u683c\u4fdd\u62a4\u63aa\u65bd\u901a\u5e38\u5728\u5f00\u53d1\u538b\u529b\u8f83\u4f4e\u7684\u5730\u533a\u5b9e\u65bd\u2014\u2014\u56e0\u6b64\u4fdd\u62a4\u7684\u5b9e\u9645\u4f5c\u7528\u6709\u9650\uff1b\u800c\u5728\u5f00\u53d1\u538b\u529b\u9ad8\u7684\u5730\u533a\uff0c\u4fdd\u62a4\u63aa\u65bd\u901a\u5e38\u8f83\u5f31\uff0c\u4ec5\u5bf9\u7ecf\u6d4e\u6d3b\u52a8\u65bd\u52a0\u6709\u9650\u7ea6\u675f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag081", "journal": "REStud", "title": "Macro Shocks and Firm Dynamics with Oligopolistic Financial Intermediaries", "authors": ["Alessandro T Villa"], "author_details": [{"name": "Alessandro T Villa", "affiliations": ["Federal Reserve Bank of Chicago ,"]}], "abstract": "Abstract Motivated by a secular increase in the concentration of the U.S. banking industry, I develop a new macroeconomic model with oligopolistic financial intermediaries and heterogeneous firms. Market power allows banks to price discriminate and charge firm-specific markups, exerting greater market power over productive and more financially constrained firms. This dampens capital accumulation and amplifies the effects of macroeconomic shocks. During a crisis, banks exploit the higher share of financially constrained firms to extract higher markups, inducing a larger decline in real activity. When a large bank fails, the remaining banks use their increased market power to restrict credit supply, worsening and prolonging the downturn.", "date": "2026-07-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag081", "title_zh": "\u5b8f\u89c2\u51b2\u51fb\u4e0e\u5be1\u5934\u91d1\u878d\u4e2d\u4ecb\u673a\u6784\u4e0b\u7684\u4f01\u4e1a\u52a8\u6001", "abstract_zh": "\u6458\u8981 \u9274\u4e8e\u7f8e\u56fd\u94f6\u884c\u4e1a\u96c6\u4e2d\u5ea6\u7684\u957f\u671f\u4e0a\u5347\u8d8b\u52bf\uff0c\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u5be1\u5934\u91d1\u878d\u4e2d\u4ecb\u673a\u6784\u548c\u5f02\u8d28\u6027\u4f01\u4e1a\u7684\u65b0\u5b8f\u89c2\u7ecf\u6d4e\u6a21\u578b\u3002\u5e02\u573a\u529b\u91cf\u4f7f\u94f6\u884c\u80fd\u591f\u5b9e\u65bd\u4ef7\u683c\u6b67\u89c6\u5e76\u9488\u5bf9\u4f01\u4e1a\u6536\u53d6\u7279\u5b9a\u7684\u6ea2\u4ef7\uff0c\u4ece\u800c\u5bf9\u4f01\u4e1a\u751f\u4ea7\u6d3b\u52a8\u548c\u8d22\u52a1\u7ea6\u675f\u66f4\u5f3a\u7684\u4f01\u4e1a\u65bd\u52a0\u66f4\u5927\u7684\u5e02\u573a\u5f71\u54cd\u529b\u3002\u8fd9\u6291\u5236\u4e86\u8d44\u672c\u79ef\u7d2f\uff0c\u5e76\u653e\u5927\u4e86\u5b8f\u89c2\u7ecf\u6d4e\u51b2\u51fb\u7684\u5f71\u54cd\u3002\u5728\u5371\u673a\u671f\u95f4\uff0c\u94f6\u884c\u5229\u7528\u8d22\u52a1\u7ea6\u675f\u66f4\u4e25\u91cd\u7684\u4f01\u4e1a\u5360\u6bd4\u4e0a\u5347\uff0c\u63d0\u53d6\u66f4\u9ad8\u7684\u6ea2\u4ef7\uff0c\u5bfc\u81f4\u5b9e\u9645\u7ecf\u6d4e\u6d3b\u52a8\u7684\u66f4\u5927\u4e0b\u6ed1\u3002\u5f53\u5927\u578b\u94f6\u884c\u5012\u95ed\u65f6\uff0c\u5269\u4f59\u94f6\u884c\u5229\u7528\u5176\u589e\u5f3a\u7684\u5e02\u573a\u529b\u91cf\u9650\u5236\u4fe1\u8d37\u4f9b\u7ed9\uff0c\u4f7f\u7ecf\u6d4e\u8870\u9000\u52a0\u5267\u5e76\u6301\u7eed\u66f4\u4e45\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag069", "journal": "RFS", "title": "Learning by Investing: Entrepreneurial Spillovers from Venture Capital", "authors": ["Josh Lerner", "Jinlin Li", "Tong Liu"], "author_details": [{"name": "Josh Lerner", "affiliations": ["Harvard University and National Bureau of Economic Research ,"]}, {"name": "Jinlin Li", "affiliations": ["China Institute of Finance and Capital Markets , China Securities Regulatory Commission,"]}, {"name": "Tong Liu", "affiliations": ["MIT Sloan School of Management ,"]}], "abstract": "Abstract This paper studies how investing in venture capital (VC) affects the entrepreneurial outcomes of individual limited partners (LPs). Using comprehensive administrative data on entrepreneurial activities and VC fundraising and investments in China, we find that after investing in a successfully launched VC fund, individual LPs create significantly more ventures than do LPs in funds that failed to launch. These new ventures tend to be high-tech firms with better employment outcomes and more patent activity. Our results suggest that venture investments are a channel through which individual LPs learn. (JEL D83, G23, G24, L25, L26)", "date": "2026-07-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag069", "title_zh": "\u6295\u8d44\u5b66\u4e60\uff1a\u6765\u81ea\u98ce\u9669\u6295\u8d44\u7684\u521b\u4e1a\u6ea2\u51fa\u6548\u5e94", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u6295\u8d44\u98ce\u9669\u8d44\u672c\uff08VC\uff09\u5982\u4f55\u5f71\u54cd\u4e2a\u4f53\u6709\u9650\u5408\u4f19\u4eba\uff08LP\uff09\u7684\u521b\u4e1a\u6210\u679c\u3002\u5229\u7528\u4e2d\u56fd\u5173\u4e8e\u521b\u4e1a\u6d3b\u52a8\u548c\u98ce\u9669\u8d44\u672c\u52df\u8d44\u4e0e\u6295\u8d44\u7684\u5168\u9762\u884c\u653f\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u6210\u529f\u542f\u52a8\u7684\u98ce\u9669\u8d44\u672c\u57fa\u91d1\u4e2d\u6295\u8d44\u540e\uff0c\u4e2a\u4f53LP\u521b\u529e\u7684\u521b\u4e1a\u4f01\u4e1a\u6570\u91cf\u663e\u8457\u591a\u4e8e\u90a3\u4e9b\u6295\u8d44\u4e8e\u672a\u80fd\u542f\u52a8\u57fa\u91d1\u7684LP\u3002\u8fd9\u4e9b\u65b0\u4f01\u4e1a\u591a\u4e3a\u9ad8\u79d1\u6280\u4f01\u4e1a\uff0c\u5c31\u4e1a\u6548\u679c\u66f4\u597d\uff0c\u4e13\u5229\u6d3b\u52a8\u4e5f\u66f4\u9891\u7e41\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u98ce\u9669\u6295\u8d44\u662f\u4e2a\u4ebaLP\u5b66\u4e60\u7684\u4e00\u4e2a\u6e20\u9053\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026103305", "journal": "JFQA", "title": "Inflation and Corporate Credit Risk: Global Evidence", "authors": ["Buhui Qiu", "Thomas To", "Gaiyan Zhang"], "author_details": [{"name": "Buhui Qiu", "affiliations": ["University of Sydney Business School, The University of Sydney"]}, {"name": "Thomas To", "affiliations": ["University of Sydney Business School, The University of Sydney"]}, {"name": "Gaiyan Zhang", "affiliations": ["Ed G. Smith College of Business, University of Missouri-St. Louis"]}], "abstract": "Abstract We provide novel international evidence that inflation is positively associated with corporate credit risk on average. A 1-standard-deviation increase in inflation is associated with a 21-basis-point increase in next-year credit default swap spreads. Importantly, this relationship is convex: it is negative or weak at low inflation levels but much more positive in high-inflation environments. The positive relation between inflation and credit risk is stronger for firms with greater refinancing vulnerability and more rigid operating cash flows, and in countries with more inflation-responsive monetary regimes and weaker institutional environments. Our findings are consistent with opposing roles for debt rigidity and operating rigidity.", "date": "2026-07-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103305", "title_zh": "\u901a\u80c0\u4e0e\u4f01\u4e1a\u4fe1\u8d37\u98ce\u9669\uff1a\u5168\u7403\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u63d0\u4f9b\u4e86\u65b0\u7684\u56fd\u9645\u8bc1\u636e\uff0c\u8868\u660e\u901a\u80c0\u4e0e\u4f01\u4e1a\u4fe1\u8d37\u98ce\u9669\u5728\u603b\u4f53\u4e0a\u5448\u6b63\u76f8\u5173\u5173\u7cfb\u3002\u901a\u80c0\u6bcf\u589e\u52a0\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u660e\u5e74\u4fe1\u7528\u8fdd\u7ea6\u4e92\u6362\u5229\u5dee\u5c06\u4e0a\u534721\u4e2a\u57fa\u70b9\u3002\u91cd\u8981\u7684\u662f\uff0c\u8fd9\u79cd\u5173\u7cfb\u662f\u51f8\u5f62\u7684\uff1a\u5728\u4f4e\u901a\u80c0\u6c34\u5e73\u4e0b\u8868\u73b0\u4e3a\u8d1f\u76f8\u5173\u6216\u8f83\u5f31\uff0c\u800c\u5728\u9ad8\u901a\u80c0\u73af\u5883\u4e0b\u5219\u663e\u8457\u589e\u5f3a\u3002\u5bf9\u4e8e\u90a3\u4e9b\u878d\u8d44\u518d\u878d\u8d44\u8106\u5f31\u6027\u8f83\u9ad8\u3001\u8fd0\u8425\u73b0\u91d1\u6d41\u66f4\u521a\u6027\u7684\u4f01\u4e1a\uff0c\u4ee5\u53ca\u5728\u66f4\u5177\u901a\u80c0\u54cd\u5e94\u6027\u7684\u8d27\u5e01\u653f\u7b56\u4f53\u7cfb\u548c\u66f4\u8584\u5f31\u7684\u5236\u5ea6\u73af\u5883\u4e0b\u7684\u56fd\u5bb6\uff0c\u8fd9\u79cd\u901a\u80c0\u4e0e\u4fe1\u8d37\u98ce\u9669\u4e4b\u95f4\u7684\u6b63\u76f8\u5173\u5173\u7cfb\u66f4\u4e3a\u660e\u663e\u3002\u6211\u4eec\u7684\u53d1\u73b0\u4e0e\u503a\u52a1\u521a\u6027\u4e0e\u8fd0\u8425\u521a\u6027\u4e4b\u95f4\u7684\u5bf9\u7acb\u4f5c\u7528\u76f8\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026103329", "journal": "JFQA", "title": "Macroeconomic Fundamentals and the Shape of Sovereign Credit Risk", "authors": ["Daniele Bianchi", "Teng Jiao"], "author_details": [{"name": "Daniele Bianchi", "affiliations": ["School of Economics and Finance, Queen Mary University of London"]}, {"name": "Teng Jiao", "affiliations": ["School of Economics and Finance, Queen Mary University of London"]}], "abstract": "Abstract Sovereign credit default swaps spreads price the credit risk embedded in government borrowing. We ask how macroeconomic fundamentals predict that risk, and whether a linear mapping from fundamentals to spreads is adequate. Across a large panel of OECD economies, linear methods perform well across countries but lose predictive accuracy after 2022 and fail to capture how spreads vary across maturities. Nonlinear methods recover both. While linear forecasts mainly rely on fiscal ratios, nonlinear predictions draw on the term-structure slope throughout, inflation during the 2022\u20132024 monetary tightening, and consumer confidence during the Eurozone crisis. These predictive relationships hold panel-wide rather than country-by-country.", "date": "2026-07-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103329", "title_zh": "\u5b8f\u89c2\u7ecf\u6d4e\u57fa\u672c\u9762\u4e0e\u4e3b\u6743\u4fe1\u7528\u98ce\u9669\u7684\u5f62\u6001", "abstract_zh": "\u6458\u8981\uff1a\u4e3b\u6743\u4fe1\u7528\u8fdd\u7ea6\u4e92\u6362\u5229\u5dee\u53cd\u6620\u4e86\u653f\u5e9c\u501f\u8d37\u4e2d\u7684\u4fe1\u7528\u98ce\u9669\u3002\u6211\u4eec\u63a2\u8ba8\u5b8f\u89c2\u7ecf\u6d4e\u57fa\u672c\u9762\u5982\u4f55\u9884\u6d4b\u8fd9\u79cd\u98ce\u9669\uff0c\u4ee5\u53ca\u7ebf\u6027\u6620\u5c04\u4ece\u57fa\u672c\u9762\u5230\u5229\u5dee\u662f\u5426\u8db3\u591f\u3002\u5728\u6db5\u76d6\u5927\u91cfOECD\u56fd\u5bb6\u7684\u9762\u677f\u6570\u636e\u4e2d\uff0c\u7ebf\u6027\u65b9\u6cd5\u5728\u5404\u56fd\u8868\u73b0\u826f\u597d\uff0c\u4f46\u57282022\u5e74\u540e\u9884\u6d4b\u51c6\u786e\u6027\u4e0b\u964d\uff0c\u4e14\u65e0\u6cd5\u6355\u6349\u5229\u5dee\u5728\u4e0d\u540c\u671f\u9650\u4e0a\u7684\u53d8\u5316\u3002\u975e\u7ebf\u6027\u65b9\u6cd5\u5219\u80fd\u591f\u6062\u590d\u8fd9\u4e9b\u7279\u5f81\u3002\u5c3d\u7ba1\u7ebf\u6027\u9884\u6d4b\u4e3b\u8981\u4f9d\u8d56\u8d22\u653f\u6bd4\u7387\uff0c\u975e\u7ebf\u6027\u9884\u6d4b\u5219\u5229\u7528\u4e86\u6574\u4e2a\u671f\u9650\u7ed3\u6784\u7684\u659c\u7387\u30012022\u81f32024\u5e74\u8d27\u5e01\u653f\u7b56\u7d27\u7f29\u671f\u95f4\u7684\u901a\u80c0\u60c5\u51b5\uff0c\u4ee5\u53ca\u6b27\u5143\u533a\u5371\u673a\u671f\u95f4\u7684\u6d88\u8d39\u8005\u4fe1\u5fc3\u3002\u8fd9\u4e9b\u9884\u6d4b\u5173\u7cfb\u5728\u9762\u677f\u5c42\u9762\u800c\u975e\u56fd\u5bb6\u5c42\u9762\u5747\u6210\u7acb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag041", "journal": "QJE", "title": "Capital Services in Global Value Chains", "authors": ["Xiang Ding"], "author_details": [{"name": "Xiang Ding", "affiliations": ["Georgetown University ,"]}], "abstract": "Abstract This article constructs the first global data set on intersectoral capital service expenditures. I use these data to disaggregate capital services and intermediate inputs in a dynamic multisector trade model. Steady-state allocations and responses to shocks are determined by a capital-augmented global input-output matrix. Two properties of the measured network deliver larger long-run consumption gains from globalization than existing estimates, as well as larger gains in more capital-intensive countries. First, more trade-exposed sectors supply capital to more consumption-influential producers. Second, heterogeneity in the network reallocates sectoral expenditures toward producers with larger declines in capital rental prices. These reallocations raise capital incomes and lower consumption price indices.", "date": "2026-07-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag041", "title_zh": "\u8d44\u672c\u670d\u52a1\u5728\u5168\u7403\u4ef7\u503c\u94fe\u4e2d\u7684\u4f5c\u7528", "abstract_zh": "\u672c\u6587\u6784\u5efa\u4e86\u9996\u4e2a\u5173\u4e8e\u90e8\u95e8\u95f4\u8d44\u672c\u670d\u52a1\u652f\u51fa\u7684\u5168\u7403\u6570\u636e\u96c6\u3002\u5229\u7528\u8fd9\u4e9b\u6570\u636e\uff0c\u6211\u5c06\u8d44\u672c\u670d\u52a1\u4e0e\u4e2d\u95f4\u6295\u5165\u54c1\u5728\u52a8\u6001\u591a\u90e8\u95e8\u8d38\u6613\u6a21\u578b\u4e2d\u8fdb\u884c\u7ec6\u5206\u3002\u7a33\u6001\u5206\u914d\u53ca\u5bf9\u51b2\u51fb\u7684\u54cd\u5e94\u7531\u8d44\u672c\u589e\u5f3a\u7684\u5168\u7403\u6295\u5165\u4ea7\u51fa\u77e9\u9635\u51b3\u5b9a\u3002\u6d4b\u91cf\u5230\u7684\u7f51\u7edc\u5177\u6709\u4e24\u4e2a\u7279\u6027\uff0c\u4f7f\u5f97\u5168\u7403\u5316\u5e26\u6765\u7684\u957f\u671f\u6d88\u8d39\u589e\u957f\u5e45\u5ea6\u8d85\u8fc7\u73b0\u6709\u4f30\u8ba1\uff0c\u5c24\u5176\u5728\u8d44\u672c\u5bc6\u96c6\u578b\u56fd\u5bb6\u4e2d\u589e\u957f\u66f4\u4e3a\u663e\u8457\u3002\u9996\u5148\uff0c\u66f4\u591a\u53c2\u4e0e\u8d38\u6613\u7684\u90e8\u95e8\u5411\u5bf9\u6d88\u8d39\u5f71\u54cd\u66f4\u5927\u7684\u751f\u4ea7\u8005\u63d0\u4f9b\u8d44\u672c\u3002\u5176\u6b21\uff0c\u7f51\u7edc\u4e2d\u7684\u5f02\u8d28\u6027\u5c06\u90e8\u95e8\u652f\u51fa\u91cd\u65b0\u5206\u914d\u81f3\u8d44\u672c\u79df\u91d1\u4ef7\u683c\u4e0b\u964d\u5e45\u5ea6\u66f4\u5927\u7684\u751f\u4ea7\u8005\u3002\u8fd9\u79cd\u91cd\u65b0\u5206\u914d\u63d0\u9ad8\u4e86\u8d44\u672c\u6536\u5165\uff0c\u964d\u4f4e\u4e86\u6d88\u8d39\u4ef7\u683c\u6307\u6570\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1111/jofi.70066", "journal": "JF", "title": "The Rising Tide Lifts Some Interest Rates: Climate Change, Natural Disasters, and Loan Pricing", "authors": ["RICARDO CORREA", "AI HE", "CHRISTOPH HERPFER", "UGUR LEL"], "author_details": [{"name": "RICARDO CORREA", "affiliations": []}, {"name": "AI HE", "affiliations": []}, {"name": "CHRISTOPH HERPFER", "affiliations": []}, {"name": "UGUR LEL", "affiliations": []}], "abstract": "ABSTRACT Banks adjust loan spreads after observing natural disasters linked to climate change. We isolate this updating process by identifying loans to borrowers at risk of, but not directly affected by, such disasters. Loan spreads for these borrowers spike in both primary and secondary markets, while no such updating occurs for non\u2013climate\u2010related disasters. Evidence suggests a heightened perceived credit risk, which nonetheless cannot fully explain the increase in rates. Taken altogether, increased spreads are explained primarily by salience bias, as they are short\u2010lived and amplified by media attention. This salience impacts financial decisions at bank\u2010dependent firms.", "date": "2026-07-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70066", "title_zh": "\u6c14\u5019\u53d8\u8fc1\u3001\u81ea\u7136\u707e\u5bb3\u4e0e\u8d37\u6b3e\u5b9a\u4ef7\uff1a\u6f6e\u6c34\u4e0a\u6da8\u4e5f\u62ac\u9ad8\u4e86\u4e00\u4e9b\u5229\u7387", "abstract_zh": "\u6458\u8981 \u94f6\u884c\u5728\u89c2\u5bdf\u5230\u4e0e\u6c14\u5019\u53d8\u5316\u76f8\u5173\u7684\u81ea\u7136\u707e\u5bb3\u540e\uff0c\u4f1a\u8c03\u6574\u8d37\u6b3e\u5229\u5dee\u3002\u6211\u4eec\u901a\u8fc7\u8bc6\u522b\u90a3\u4e9b\u9762\u4e34\u81ea\u7136\u707e\u5bb3\u98ce\u9669\u4f46\u672a\u76f4\u63a5\u53d7\u5230\u5f71\u54cd\u7684\u501f\u6b3e\u4eba\u7684\u8d37\u6b3e\uff0c\u6765\u5206\u79bb\u8fd9\u4e00\u8c03\u6574\u8fc7\u7a0b\u3002\u8fd9\u4e9b\u501f\u6b3e\u4eba\u7684\u8d37\u6b3e\u5229\u5dee\u5728\u4e00\u7ea7\u548c\u4e8c\u7ea7\u5e02\u573a\u5747\u51fa\u73b0\u4e0a\u5347\uff0c\u800c\u4e0e\u6c14\u5019\u65e0\u5173\u7684\u81ea\u7136\u707e\u5bb3\u5219\u6ca1\u6709\u6b64\u7c7b\u8c03\u6574\u73b0\u8c61\u3002\u8bc1\u636e\u8868\u660e\uff0c\u4fe1\u7528\u98ce\u9669\u7684\u611f\u77e5\u6709\u6240\u63d0\u5347\uff0c\u4f46\u8fd9\u4e00\u63d0\u5347\u5e76\u4e0d\u80fd\u5b8c\u5168\u89e3\u91ca\u5229\u5dee\u7684\u6269\u5927\u3002\u7efc\u5408\u6765\u770b\uff0c\u5229\u5dee\u7684\u4e0a\u5347\u4e3b\u8981\u7531\u663e\u8457\u6027\u504f\u5dee\u5f15\u8d77\uff0c\u56e0\u4e3a\u8fd9\u79cd\u4e0a\u5347\u662f\u77ed\u6682\u7684\uff0c\u5e76\u53d7\u5230\u5a92\u4f53\u62a5\u9053\u7684\u653e\u5927\u3002\u8fd9\u79cd\u663e\u8457\u6027\u5f71\u54cd\u4e86\u4f9d\u8d56\u94f6\u884c\u7684\u4f01\u4e1a\u7684\u91d1\u878d\u51b3\u7b56\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70069", "journal": "JF", "title": "Dynamic Self\u2010Fulfilling Fire Sales", "authors": ["PAYMON KHORRAMI", "FERNANDO MENDO"], "author_details": [{"name": "PAYMON KHORRAMI", "affiliations": []}, {"name": "FERNANDO MENDO", "affiliations": []}], "abstract": "ABSTRACT Why do fire sales occur if many risks are hedgeable? We study a version of Brunnermeier and Sannikov (2014, American Economic Review 104, 379\u2013421) in which all fundamental risks can be hedged frictionlessly. Our analysis shows that fire sales are inherently self\u2010fulfilling. Fundamental shocks can never cause fire sales, and an efficient, safe equilibrium exists. On the other hand, there exists an equilibrium in which agents coordinate fire sales on nonfundamental shocks. A simple refinement based on vanishingly small perceived fundamental risk eliminates the safe equilibrium and selects the fire\u2010sale equilibrium as the unique outcome.", "date": "2026-07-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70069", "title_zh": "\u52a8\u6001\u81ea\u6211\u5b9e\u73b0\u7684\u629b\u552e\u884c\u4e3a", "abstract_zh": "\u6458\u8981 \u4e3a\u4f55\u5728\u8bb8\u591a\u98ce\u9669\u5747\u53ef\u5bf9\u51b2\u7684\u60c5\u51b5\u4e0b\u4ecd\u4f1a\u51fa\u73b0\u629b\u552e\u884c\u4e3a\uff1f\u6211\u4eec\u7814\u7a76\u4e86Brunnermeier\u548cSannikov\uff082014\u5e74\uff0c\u300a\u7f8e\u56fd\u7ecf\u6d4e\u8bc4\u8bba\u300b104\u5377\uff0c\u7b2c379-421\u9875\uff09\u63d0\u51fa\u7684\u4e00\u79cd\u6a21\u578b\uff0c\u5728\u8be5\u6a21\u578b\u4e2d\u6240\u6709\u57fa\u672c\u9762\u98ce\u9669\u5747\u53ef\u65e0\u6469\u64e6\u5730\u5bf9\u51b2\u3002\u6211\u4eec\u7684\u5206\u6790\u8868\u660e\uff0c\u629b\u552e\u884c\u4e3a\u672c\u8d28\u4e0a\u662f\u81ea\u6211\u5b9e\u73b0\u7684\u3002\u57fa\u672c\u9762\u51b2\u51fb\u6c38\u8fdc\u4e0d\u4f1a\u5f15\u53d1\u629b\u552e\u884c\u4e3a\uff0c\u4e14\u5b58\u5728\u4e00\u4e2a\u9ad8\u6548\u4e14\u5b89\u5168\u7684\u5747\u8861\u3002\u53e6\u4e00\u65b9\u9762\uff0c\u5b58\u5728\u4e00\u79cd\u5747\u8861\uff0c\u5176\u4e2d\u53c2\u4e0e\u8005\u4f1a\u534f\u8c03\u5728\u975e\u57fa\u672c\u9762\u51b2\u51fb\u4e0a\u53d1\u751f\u629b\u552e\u884c\u4e3a\u3002\u4e00\u79cd\u57fa\u4e8e\u611f\u77e5\u57fa\u672c\u9762\u98ce\u9669\u8d8b\u8fd1\u4e8e\u96f6\u7684\u7b80\u5355\u7cbe\u70bc\u65b9\u6cd5\uff0c\u6d88\u9664\u4e86\u5b89\u5168\u5747\u8861\uff0c\u5e76\u5c06\u629b\u552e\u5747\u8861\u4f5c\u4e3a\u552f\u4e00\u7ed3\u679c\u9009\u62e9\u51fa\u6765\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag073", "journal": "REStud", "title": "When is Separate Sales Optimal?", "authors": ["Changhyun Kwak"], "author_details": [{"name": "Changhyun Kwak", "affiliations": ["Institute of Economics, Academia Sinica ,"]}], "abstract": "Abstract This paper studies a multi-product monopolist facing a privately informed consumer with additive and type-increasing valuations. Separate monopoly pricing is robustly optimal with respect to the type distribution if and only if the marginal rate of substitution between each pair of goods is monotone. This result is obtained by extending the conventional Myersonian approach.", "date": "2026-07-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag073", "title_zh": "\u4f55\u65f6\u5355\u72ec\u9500\u552e\u662f\u6700\u4f18\u7684\uff1f", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u4e00\u4e2a\u591a\u4ea7\u54c1\u5784\u65ad\u8005\u9762\u5bf9\u5177\u6709\u79c1\u6709\u4fe1\u606f\u7684\u6d88\u8d39\u8005\uff0c\u4e14\u6d88\u8d39\u8005\u5bf9\u5546\u54c1\u7684\u4f30\u503c\u5177\u6709\u53ef\u52a0\u6027\u548c\u7c7b\u578b\u9012\u589e\u6027\u7684\u60c5\u51b5\u3002\u5728\u7c7b\u578b\u5206\u5e03\u4e0b\uff0c\u5355\u72ec\u5784\u65ad\u5b9a\u4ef7\u5728\u4f55\u79cd\u6761\u4ef6\u4e0b\u662f\u7a33\u5065\u6700\u4f18\u7684\uff0c\u5f53\u4e14\u4ec5\u5f53\u6bcf\u5bf9\u5546\u54c1\u4e4b\u95f4\u7684\u8fb9\u9645\u66ff\u4ee3\u7387\u662f\u5355\u8c03\u7684\u3002\u8fd9\u4e00\u7ed3\u679c\u662f\u901a\u8fc7\u6269\u5c55\u4f20\u7edf\u7684Myerson\u65b9\u6cd5\u5f97\u5230\u7684\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag068", "journal": "RFS", "title": "Pension Liquidity Risk", "authors": ["Kristy A E Jansen", "Sven Klingler", "Angelo Ranaldo", "Patty Duijm"], "author_details": [{"name": "Kristy A E Jansen", "affiliations": ["Marshall School of Business, University of Southern California, CEPR, and De Nederlandsche Bank , USA and Netherlands"]}, {"name": "Sven Klingler", "affiliations": ["Frankfurt School of Finance and Management ,"]}, {"name": "Angelo Ranaldo", "affiliations": ["University of Basel and Swiss Finance Institute ,"]}, {"name": "Patty Duijm", "affiliations": ["De Nederlandsche Bank ,"]}], "abstract": "Abstract Pension funds use interest rate swaps to hedge the interest rate risk arising from their liabilities. Analyzing regulatory data on Dutch pension funds, we show that pension funds with worse funding ratios, indicating greater fragility, use swaps more aggressively. These swap positions expose pension funds to the risk of margin calls, which can exceed 6% of their total assets, when interest rates rise. Pension funds respond to realized margin calls by selling safe government bonds with medium-term maturities. This procyclical selling behavior adversely affects the prices of the sold bonds and thereby exposes pension funds to market liquidity risk.", "date": "2026-07-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag068", "title_zh": "\u517b\u8001\u91d1\u6d41\u52a8\u6027\u98ce\u9669", "abstract_zh": "\u517b\u8001\u91d1\u57fa\u91d1\u5229\u7528\u5229\u7387\u4e92\u6362\u5bf9\u51b2\u5176\u56e0\u8d1f\u503a\u4ea7\u751f\u7684\u5229\u7387\u98ce\u9669\u3002\u57fa\u4e8e\u5bf9\u8377\u5170\u517b\u8001\u91d1\u57fa\u91d1\u7684\u76d1\u7ba1\u6570\u636e\u8fdb\u884c\u5206\u6790\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u90a3\u4e9b\u8d44\u91d1\u8986\u76d6\u7387\u8f83\u5dee\u3001\u8868\u660e\u66f4\u8106\u5f31\u7684\u517b\u8001\u91d1\u57fa\u91d1\uff0c\u4f1a\u66f4\u79ef\u6781\u5730\u4f7f\u7528\u4e92\u6362\u5de5\u5177\u3002\u8fd9\u4e9b\u4e92\u6362\u5934\u5bf8\u5728\u5229\u7387\u4e0a\u5347\u65f6\u4f1a\u9762\u4e34\u4fdd\u8bc1\u91d1\u88ab\u8981\u6c42\u7684\u98ce\u9669\uff0c\u8be5\u98ce\u9669\u53ef\u80fd\u8d85\u8fc7\u5176\u603b\u8d44\u4ea7\u76846%\u3002\u5f53\u517b\u8001\u91d1\u57fa\u91d1\u9762\u4e34\u5b9e\u9645\u7684\u4fdd\u8bc1\u91d1\u8981\u6c42\u65f6\uff0c\u4f1a\u51fa\u552e\u4e2d\u957f\u671f\u671f\u9650\u7684\u653f\u5e9c\u5b89\u5168\u503a\u5238\u3002\u8fd9\u79cd\u987a\u5468\u671f\u7684\u5356\u51fa\u884c\u4e3a\u4f1a\u538b\u4f4e\u6240\u552e\u503a\u5238\u7684\u4ef7\u683c\uff0c\u4ece\u800c\u4f7f\u517b\u8001\u91d1\u57fa\u91d1\u9762\u4e34\u5e02\u573a\u6d41\u52a8\u6027\u98ce\u9669\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1093/rfs/hhag067", "journal": "RFS", "title": "Dollar Asset Holdings and Hedging around the Globe", "authors": ["Wenxin Du", "Amy W Huber"], "author_details": [{"name": "Wenxin Du", "affiliations": ["Harvard Business School and NBER ,"]}, {"name": "Amy W Huber", "affiliations": ["The Wharton School of the University of Pennsylvania ,"]}], "abstract": "Abstract We collect and analyze detailed filings from global institutional investors to estimate foreign investors\u2019 U.S. dollar (USD) security holdings and currency hedging. Over two decades, foreign USD holdings grew sixfold, while hedge ratios rose by 15 percentage points after the 2008\u20132009 crisis. Currency hedging across mutual funds, pensions, and insurance reached $2 trillion by 2019. Hedging demand varies across investors, currency areas, and banking systems. We show that expected FX returns, beyond variance minimization, drive currency exposure in portfolios. Finally, we demonstrate and quantify how aggregate hedging demand affects hedging costs in the presence of constrained intermediaries.", "date": "2026-07-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag067", "title_zh": "\u5168\u7403\u7f8e\u5143\u8d44\u4ea7\u6301\u6709\u4e0e\u5bf9\u51b2", "abstract_zh": "\u6211\u4eec\u6536\u96c6\u5e76\u5206\u6790\u4e86\u5168\u7403\u673a\u6784\u6295\u8d44\u8005\u7684\u8be6\u7ec6\u6587\u4ef6\uff0c\u4ee5\u4f30\u7b97\u5916\u56fd\u6295\u8d44\u8005\u5bf9\u7f8e\u56fd\u7f8e\u5143\uff08USD\uff09\u8bc1\u5238\u7684\u6301\u6709\u91cf\u53ca\u5176\u8d27\u5e01\u5bf9\u51b2\u884c\u4e3a\u3002\u5728\u4e8c\u5341\u5e74\u95f4\uff0c\u5916\u56fd\u7f8e\u5143\u8d44\u4ea7\u6301\u6709\u91cf\u589e\u957f\u4e86\u516d\u500d\uff0c2008-2009\u5e74\u91d1\u878d\u5371\u673a\u540e\uff0c\u5bf9\u51b2\u6bd4\u7387\u63d0\u9ad8\u4e8615\u4e2a\u767e\u5206\u70b9\u3002\u52302019\u5e74\uff0c\u4e92\u57fa\u91d1\u3001\u517b\u8001\u91d1\u548c\u4fdd\u9669\u673a\u6784\u7684\u8d27\u5e01\u5bf9\u51b2\u89c4\u6a21\u5df2\u8fbe\u52302\u4e07\u4ebf\u7f8e\u5143\u3002\u5bf9\u51b2\u9700\u6c42\u5728\u4e0d\u540c\u6295\u8d44\u8005\u3001\u4e0d\u540c\u8d27\u5e01\u533a\u57df\u548c\u94f6\u884c\u4f53\u7cfb\u4e4b\u95f4\u5b58\u5728\u5dee\u5f02\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u9664\u4e86\u65b9\u5dee\u6700\u5c0f\u5316\u5916\uff0c\u9884\u671f\u6c47\u7387\u56de\u62a5\u662f\u9a71\u52a8\u6295\u8d44\u7ec4\u5408\u8d27\u5e01\u655e\u53e3\u7684\u5173\u952e\u56e0\u7d20\u3002\u6700\u540e\uff0c\u6211\u4eec\u5c55\u793a\u4e86\u5e76\u91cf\u5316\u4e86\u6574\u4f53\u5bf9\u51b2\u9700\u6c42\u5982\u4f55\u5728\u5b58\u5728\u53d7\u9650\u4e2d\u4ecb\u673a\u6784\u7684\u60c5\u51b5\u4e0b\u5f71\u54cd\u5bf9\u51b2\u6210\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1093/qje/qjag039", "journal": "QJE", "title": "Mental Models of the Stock Market", "authors": ["Peter Andre", "Philipp Schirmer", "Johannes Wohlfart"], "author_details": [{"name": "Peter Andre", "affiliations": ["Leibniz Institute for Financial Research SAFE and Goethe University Frankfurt ,"]}, {"name": "Philipp Schirmer", "affiliations": ["University of Bonn ,"]}, {"name": "Johannes Wohlfart", "affiliations": ["University of Cologne ,"]}], "abstract": "Abstract Investors\u2019 return expectations are pivotal in stock markets, but the reasoning behind these expectations is not well understood. This article explores economic agents\u2019 mental models of what drives returns. We survey the general population, retail investors, financial professionals, and academic experts to investigate how they forecast and explain future returns in scenarios with stale news about future company earnings. We find that investors strongly disagree in their forecasts and reasoning. Most academic experts view markets as efficient. By contrast, most households express a perspective we call \u201cexpected earnings reasoning\u201d: they directly equate higher expected earnings with higher expected returns. Professionals are split between market efficiency, mispricing, and expected earnings reasoning. In detailed experiments, we dissect why households adopt expected earnings reasoning. We show that it arises from inattention to how stock price changes affect investor costs\u2014that is, how much investors must pay to acquire a claim to future cash flows\u2014because the typical format and context of investment problems obscure these cost implications. Our results help connect a series of previously documented anomalies in expectation and trading data and highlight the importance of selective attention and context in shaping reasoning and belief formation.", "date": "2026-07-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag039", "title_zh": "\u80a1\u7968\u5e02\u573a\u7684\u5fc3\u7406\u6a21\u578b", "abstract_zh": "\u6458\u8981 \u6295\u8d44\u8005\u7684\u6536\u76ca\u9884\u671f\u5bf9\u80a1\u7968\u5e02\u573a\u81f3\u5173\u91cd\u8981\uff0c\u4f46\u5176\u80cc\u540e\u7684\u63a8\u7406\u673a\u5236\u5c1a\u4e0d\u660e\u786e\u3002\u672c\u6587\u63a2\u8ba8\u4e86\u7ecf\u6d4e\u4e3b\u4f53\u5bf9\u6536\u76ca\u9a71\u52a8\u56e0\u7d20\u7684\u5fc3\u7406\u6a21\u578b\u3002\u6211\u4eec\u5bf9\u4e00\u822c\u516c\u4f17\u3001\u96f6\u552e\u6295\u8d44\u8005\u3001\u91d1\u878d\u4e13\u4e1a\u4eba\u58eb\u4ee5\u53ca\u5b66\u672f\u4e13\u5bb6\u8fdb\u884c\u8c03\u67e5\uff0c\u7814\u7a76\u4ed6\u4eec\u5728\u672a\u6765\u516c\u53f8\u76c8\u5229\u4fe1\u606f\u4e0d\u53d8\u7684\u60c5\u51b5\u4e0b\u5982\u4f55\u9884\u6d4b\u548c\u89e3\u91ca\u672a\u6765\u7684\u6536\u76ca\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u6295\u8d44\u8005\u5728\u9884\u6d4b\u548c\u63a8\u7406\u4e0a\u5b58\u5728\u663e\u8457\u5206\u6b67\u3002\u5927\u591a\u6570\u5b66\u672f\u4e13\u5bb6\u8ba4\u4e3a\u5e02\u573a\u662f\u6709\u6548\u7684\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u5927\u591a\u6570\u5bb6\u5ead\u6295\u8d44\u8005\u8868\u73b0\u51fa\u6211\u4eec\u79f0\u4e4b\u4e3a\u201c\u9884\u671f\u6536\u76ca\u63a8\u7406\u201d\u7684\u89c2\u70b9\uff1a\u4ed6\u4eec\u76f4\u63a5\u5c06\u66f4\u9ad8\u7684\u9884\u671f\u6536\u76ca\u7b49\u540c\u4e8e\u66f4\u9ad8\u7684\u9884\u671f\u56de\u62a5\u3002\u4e13\u4e1a\u4eba\u58eb\u5219\u5728\u5e02\u573a\u6709\u6548\u6027\u3001\u5b9a\u4ef7\u9519\u8bef\u548c\u9884\u671f\u6536\u76ca\u63a8\u7406\u4e4b\u95f4\u5b58\u5728\u5206\u6b67\u3002\u5728\u8be6\u7ec6\u5b9e\u9a8c\u4e2d\uff0c\u6211\u4eec\u5256\u6790\u4e86\u5bb6\u5ead\u6295\u8d44\u8005\u4e3a\u4f55\u91c7\u7528\u9884\u671f\u6536\u76ca\u63a8\u7406\u3002\u7814\u7a76\u8868\u660e\uff0c\u8fd9\u79cd\u63a8\u7406\u6e90\u4e8e\u5bf9\u80a1\u7968\u4ef7\u683c\u53d8\u52a8\u5982\u4f55\u5f71\u54cd\u6295\u8d44\u8005\u6210\u672c\u7684\u5ffd\u89c6\u2014\u2014\u5373\u6295\u8d44\u8005\u4e3a\u83b7\u5f97\u672a\u6765\u73b0\u91d1\u6d41\u6743\u5229\u5fc5\u987b\u652f\u4ed8\u7684\u91d1\u989d\u2014\u2014\u56e0\u4e3a\u6295\u8d44\u95ee\u9898\u7684\u5178\u578b\u683c\u5f0f\u548c\u80cc\u666f\u63a9\u76d6\u4e86\u8fd9\u4e9b\u6210\u672c\u5f71\u54cd\u3002\u6211\u4eec\u7684\u7ed3\u679c\u6709\u52a9\u4e8e\u8fde\u63a5\u4e00\u7cfb\u5217\u5148\u524d\u89c2\u5bdf\u5230\u7684\u9884\u671f\u548c\u4ea4\u6613\u6570\u636e\u4e2d\u7684\u5f02\u5e38\u73b0\u8c61\uff0c\u5e76\u5f3a\u8c03\u4e86\u9009\u62e9\u6027\u6ce8\u610f\u548c\u80cc\u666f\u5728\u5851\u9020\u63a8\u7406\u548c\u4fe1\u5ff5\u5f62\u6210\u8fc7\u7a0b\u4e2d\u7684\u91cd\u8981\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/qje/qjag037", "journal": "QJE", "title": "The Transmission of Reliable and Unreliable Information", "authors": ["Thomas Graeber", "Shakked Noy", "Christopher Roth"], "author_details": [{"name": "Thomas Graeber", "affiliations": ["University of Zurich ,", "Massachusetts Institute of Technology ,", "University of Cologne, Econtribute, CESifo, Max-Planck Institute for Behavioral Economics ,"]}, {"name": "Shakked Noy", "affiliations": ["University of Zurich ,", "Massachusetts Institute of Technology ,", "University of Cologne, Econtribute, CESifo, Max-Planck Institute for Behavioral Economics ,"]}, {"name": "Christopher Roth", "affiliations": ["University of Zurich ,", "Massachusetts Institute of Technology ,", "University of Cologne, Econtribute, CESifo, Max-Planck Institute for Behavioral Economics ,"]}], "abstract": "Abstract Information often spreads and influences beliefs regardless of its reliability. We show that this occurs in part because indicators of reliability tend to be lost in the process of word-of-mouth transmission. We conduct controlled experiments where participants listen to economic forecasts and pass them on through voice messages. Other participants listen either to original or transmitted audio recordings and report incentivized beliefs. Across various transmitter incentive schemes, a claim\u2019s reliability is lost in transmission much more than the claim itself. Reliable and unreliable information, once filtered through transmission, affect listeners\u2019 beliefs similarly. Mechanism experiments show that reliability is lost not because it is perceived as less relevant or harder to transmit but because it is less likely to come to mind during transmission. Evidence from our experiments, a large corpus of everyday conversations, and economic TV news shows that contextual cues can bring reliability to mind and induce its transmission, but situations in which people share information seldom contain such cues.", "date": "2026-07-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag037", "title_zh": "\u53ef\u9760\u4e0e\u4e0d\u53ef\u9760\u4fe1\u606f\u7684\u4f20\u9012", "abstract_zh": "\u4fe1\u606f\u5f80\u5f80\u5728\u4f20\u64ad\u8fc7\u7a0b\u4e2d\u5f71\u54cd\u4eba\u4eec\u7684\u4fe1\u5ff5\uff0c\u65e0\u8bba\u5176\u53ef\u9760\u6027\u5982\u4f55\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u5728\u4e00\u5b9a\u7a0b\u5ea6\u4e0a\u662f\u56e0\u4e3a\u53ef\u9760\u6027\u6307\u6807\u5728\u53e3\u53e3\u76f8\u4f20\u7684\u8fc7\u7a0b\u4e2d\u5bb9\u6613\u88ab\u4e22\u5931\u3002\u6211\u4eec\u8bbe\u8ba1\u4e86\u53d7\u63a7\u5b9e\u9a8c\uff0c\u53c2\u4e0e\u8005\u542c\u53d6\u7ecf\u6d4e\u9884\u6d4b\u5e76\u901a\u8fc7\u8bed\u97f3\u6d88\u606f\u4f20\u9012\u7ed9\u4ed6\u4eba\u3002\u5176\u4ed6\u53c2\u4e0e\u8005\u542c\u53d6\u539f\u59cb\u6216\u5df2\u4f20\u9012\u7684\u97f3\u9891\u8bb0\u5f55\uff0c\u5e76\u62a5\u544a\u5176\u6709\u6fc0\u52b1\u7684\u4fe1\u5ff5\u3002\u5728\u5404\u79cd\u4f20\u9012\u8005\u6fc0\u52b1\u65b9\u6848\u4e0b\uff0c\u4fe1\u606f\u7684\u53ef\u9760\u6027\u5728\u4f20\u9012\u8fc7\u7a0b\u4e2d\u6bd4\u4fe1\u606f\u672c\u8eab\u635f\u5931\u5f97\u66f4\u591a\u3002\u4e00\u65e6\u7ecf\u8fc7\u4f20\u9012\uff0c\u53ef\u9760\u548c\u4e0d\u53ef\u9760\u7684\u4fe1\u606f\u5bf9\u542c\u4f17\u4fe1\u5ff5\u7684\u5f71\u54cd\u53d8\u5f97\u76f8\u540c\u3002\u673a\u5236\u5b9e\u9a8c\u8868\u660e\uff0c\u53ef\u9760\u6027\u4e22\u5931\u5e76\u975e\u56e0\u4e3a\u4eba\u4eec\u8ba4\u4e3a\u5176\u76f8\u5173\u6027\u8f83\u4f4e\u6216\u66f4\u96be\u4f20\u9012\uff0c\u800c\u662f\u56e0\u4e3a\u53ef\u9760\u6027\u5728\u4f20\u9012\u8fc7\u7a0b\u4e2d\u4e0d\u5bb9\u6613\u88ab\u60f3\u8d77\u3002\u6765\u81ea\u5b9e\u9a8c\u3001\u5927\u91cf\u65e5\u5e38\u5bf9\u8bdd\u6570\u636e\u4ee5\u53ca\u7ecf\u6d4e\u7535\u89c6\u65b0\u95fb\u8282\u76ee\u7684\u8bc1\u636e\u8868\u660e\uff0c\u4e0a\u4e0b\u6587\u7ebf\u7d22\u53ef\u4ee5\u5524\u8d77\u4eba\u4eec\u5bf9\u53ef\u9760\u6027\u7684\u6ce8\u610f\u5e76\u4fc3\u8fdb\u5176\u4f20\u64ad\uff0c\u4f46\u4eba\u4eec\u5728\u5206\u4eab\u4fe1\u606f\u7684\u60c5\u5883\u4e2d\u5f88\u5c11\u5305\u542b\u8fd9\u6837\u7684\u7ebf\u7d22\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70070", "journal": "JF", "title": "Do Equity and Options Markets Agree about Volatility?", "authors": ["CARSTEN H. CHONG", "VIKTOR TODOROV"], "author_details": [{"name": "CARSTEN H. CHONG", "affiliations": []}, {"name": "VIKTOR TODOROV", "affiliations": []}], "abstract": "ABSTRACT We derive tight pricing kernel restrictions from options with same\u2010day expiration (\u201c0DTEs\u201d). These restrictions concern the volatility of small and frequent asset price moves that the equity and options markets must agree on in a frictionless economy. Their violation leads to pseudo\u2010arbitrage opportunities, characterized by nontrivial reward\u2010to\u2010risk ratios over arbitrarily short horizons and achieved by a combined position in 0DTEs and the underlying asset. Empirically, we find no evidence of feasible pseudo\u2010arbitrage opportunities, as transaction costs, estimation risk, and short\u2010term volatility risk prevent investors from taking advantage of small and infrequent disagreements about volatility between equity and options markets.", "date": "2026-07-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70070", "title_zh": "\u80a1\u7968\u548c\u671f\u6743\u5e02\u573a\u5bf9\u6ce2\u52a8\u7387\u7684\u770b\u6cd5\u4e00\u81f4\u5417\uff1f", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u4ece\u5177\u6709\u5f53\u65e5\u5230\u671f\uff08\"0DTE\"\uff09\u7684\u671f\u6743\u4e2d\u63a8\u5bfc\u51fa\u4e25\u683c\u7684\u5b9a\u4ef7\u6838\u9650\u5236\u3002\u8fd9\u4e9b\u9650\u5236\u6d89\u53ca\u80a1\u7968\u5e02\u573a\u548c\u671f\u6743\u5e02\u573a\u5728\u65e0\u6469\u64e6\u7ecf\u6d4e\u4e2d\u5fc5\u987b\u4e00\u81f4\u8ba4\u53ef\u7684\u5c0f\u5e45\u4e14\u9891\u7e41\u7684\u8d44\u4ea7\u4ef7\u683c\u6ce2\u52a8\u7684\u6ce2\u52a8\u7387\u3002\u82e5\u8fd9\u4e9b\u4e00\u81f4\u6027\u88ab\u8fdd\u53cd\uff0c\u5219\u4f1a\u4ea7\u751f\u4f2a\u5957\u5229\u673a\u4f1a\uff0c\u8868\u73b0\u4e3a\u5728\u4efb\u610f\u77ed\u65f6\u95f4\u8303\u56f4\u5185\u5177\u6709\u975e\u5e73\u51e1\u7684\u98ce\u9669\u56de\u62a5\u6bd4\u7387\uff0c\u901a\u8fc7\u57280DTE\u671f\u6743\u548c\u6807\u7684\u8d44\u4ea7\u4e0a\u7ec4\u5408\u6301\u4ed3\u5373\u53ef\u5b9e\u73b0\u3002\u5b9e\u8bc1\u7ed3\u679c\u8868\u660e\uff0c\u6ca1\u6709\u53d1\u73b0\u53ef\u884c\u7684\u4f2a\u5957\u5229\u673a\u4f1a\uff0c\u56e0\u4e3a\u4ea4\u6613\u6210\u672c\u3001\u4f30\u8ba1\u98ce\u9669\u4ee5\u53ca\u77ed\u671f\u6ce2\u52a8\u98ce\u9669\u963b\u6b62\u4e86\u6295\u8d44\u8005\u5229\u7528\u80a1\u7968\u5e02\u573a\u548c\u671f\u6743\u5e02\u573a\u4e4b\u95f4\u5173\u4e8e\u6ce2\u52a8\u7387\u7684\u5c0f\u5e45\u4e14\u4e0d\u9891\u7e41\u7684\u5206\u6b67\u83b7\u5229\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1111/jofi.70071", "journal": "JF", "title": "Climate Change, Demand Uncertainty, and Firms' Investments: Evidence from Planned Power Plants", "authors": ["CHEN LIN", "THOMAS SCHMID", "MICHAEL S. WEISBACH"], "author_details": [{"name": "CHEN LIN", "affiliations": []}, {"name": "THOMAS SCHMID", "affiliations": []}, {"name": "MICHAEL S. WEISBACH", "affiliations": []}], "abstract": "ABSTRACT How does demand uncertainty affect firms' investment decisions? We examine this question in the context of electricity\u2010producing firms' planned investments in new power plants. We measure uncertainty about future electricity demand using plausibly exogenous variation in temperature projections across scientific climate models. The results show that uncertainty increases investment in power plants with flexible production technologies, while reducing investment in less flexible technologies. Overall, the net effect of uncertainty on investment is positive when firms have access to flexible investment opportunities. These findings are consistent with models in which production flexibility shapes the investment response to demand uncertainty.", "date": "2026-07-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70071", "title_zh": "\u6c14\u5019\u53d8\u5316\u3001\u9700\u6c42\u4e0d\u786e\u5b9a\u6027\u4e0e\u4f01\u4e1a\u7684\u6295\u8d44\uff1a\u6765\u81ea\u89c4\u5212\u7535\u529b\u9879\u76ee\u7684\u8bc1\u636e", "abstract_zh": "\u6458\u8981 \u9700\u6c42\u4e0d\u786e\u5b9a\u6027\u5982\u4f55\u5f71\u54cd\u4f01\u4e1a\u7684\u6295\u8d44\u51b3\u7b56\uff1f\u6211\u4eec\u4ee5\u7535\u529b\u751f\u4ea7\u4f01\u4e1a\u7684\u65b0\u5efa\u7535\u5382\u6295\u8d44\u51b3\u7b56\u4e3a\u7814\u7a76\u80cc\u666f\uff0c\u5229\u7528\u4e0d\u540c\u79d1\u5b66\u6c14\u5019\u6a21\u578b\u5bf9\u6e29\u5ea6\u9884\u6d4b\u7684\u5916\u751f\u53d8\u5316\u6765\u8861\u91cf\u672a\u6765\u7535\u529b\u9700\u6c42\u7684\u4e0d\u786e\u5b9a\u6027\u3002\u7ed3\u679c\u8868\u660e\uff0c\u4e0d\u786e\u5b9a\u6027\u4f1a\u589e\u52a0\u91c7\u7528\u7075\u6d3b\u751f\u4ea7\u6280\u672f\u7684\u7535\u5382\u7684\u6295\u8d44\uff0c\u800c\u51cf\u5c11\u5bf9\u7075\u6d3b\u6027\u8f83\u4f4e\u6280\u672f\u7684\u6295\u8d44\u3002\u603b\u4f53\u800c\u8a00\uff0c\u5f53\u4f01\u4e1a\u62e5\u6709\u7075\u6d3b\u6295\u8d44\u673a\u4f1a\u65f6\uff0c\u4e0d\u786e\u5b9a\u6027\u5bf9\u6295\u8d44\u7684\u51c0\u6548\u5e94\u4e3a\u6b63\u3002\u8fd9\u4e9b\u53d1\u73b0\u4e0e\u751f\u4ea7\u7075\u6d3b\u6027\u5f71\u54cd\u4f01\u4e1a\u5728\u9700\u6c42\u4e0d\u786e\u5b9a\u6027\u4e0b\u6295\u8d44\u53cd\u5e94\u7684\u6a21\u578b\u76f8\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70067", "journal": "JF", "title": "The Cross\u2010Section of Household Preferences", "authors": ["LAURENT E. CALVET", "JOHN Y. CAMPBELL", "FRANCISCO GOMES", "PAOLO SODINI"], "author_details": [{"name": "LAURENT E. CALVET", "affiliations": []}, {"name": "JOHN Y. CAMPBELL", "affiliations": []}, {"name": "FRANCISCO GOMES", "affiliations": []}, {"name": "PAOLO SODINI", "affiliations": []}], "abstract": "ABSTRACT This paper estimates the cross\u2010sectional distribution of Epstein\u2010Zin preferences using the wealth and risky portfolio shares of a large panel of Swedish households. We find modestly heterogeneous risk aversion (standard deviation 0.97, median 7.50) and a meaningfully heterogeneous and right\u2010skewed time preference rate (TPR; standard deviation 7.31%, median 4.08%) and elasticity of intertemporal substitution (EIS; standard deviation 3.17, median 0.70). Risk aversion and the EIS are only very weakly negatively correlated. We estimate lower risk aversion for households with riskier labor income, and a higher TPR and lower EIS for households that enter our sample with low wealth.", "date": "2026-07-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70067", "title_zh": "\u5bb6\u5ead\u504f\u597d\u6a2a\u622a\u9762\u7814\u7a76", "abstract_zh": "\u6458\u8981 \u672c\u6587\u5229\u7528\u745e\u5178\u5927\u91cf\u5bb6\u5ead\u7684\u8d22\u5bcc\u548c\u98ce\u9669\u8d44\u4ea7\u6301\u6709\u6bd4\u4f8b\uff0c\u4f30\u8ba1\u4e86Epstein-Zin\u504f\u597d\u5728\u6a2a\u622a\u9762\u4e0a\u7684\u5206\u5e03\u3002\u6211\u4eec\u53d1\u73b0\u98ce\u9669\u538c\u6076\u7a0b\u5ea6\u5b58\u5728\u9002\u5ea6\u5f02\u8d28\u6027\uff08\u6807\u51c6\u5dee\u4e3a0.97\uff0c\u4e2d\u4f4d\u6570\u4e3a7.50\uff09\uff0c\u65f6\u95f4\u504f\u597d\u7387\uff08TPR\uff09\u548c\u8de8\u671f\u66ff\u4ee3\u5f39\u6027\uff08EIS\uff09\u5b58\u5728\u663e\u8457\u5f02\u8d28\u6027\u4e14\u5448\u53f3\u504f\u5206\u5e03\uff08TPR\u6807\u51c6\u5dee\u4e3a7.31%\uff0c\u4e2d\u4f4d\u6570\u4e3a4.08%\uff1bEIS\u6807\u51c6\u5dee\u4e3a3.17\uff0c\u4e2d\u4f4d\u6570\u4e3a0.70\uff09\u3002\u98ce\u9669\u538c\u6076\u7a0b\u5ea6\u4e0eEIS\u4e4b\u95f4\u4ec5\u5b58\u5728\u975e\u5e38\u5f31\u7684\u8d1f\u76f8\u5173\u5173\u7cfb\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u52b3\u52a8\u6536\u5165\u98ce\u9669\u8f83\u9ad8\u7684\u5bb6\u5ead\u98ce\u9669\u538c\u6076\u7a0b\u5ea6\u8f83\u4f4e\uff0c\u800c\u521d\u59cb\u8d22\u5bcc\u8f83\u4f4e\u7684\u5bb6\u5ead\u5177\u6709\u66f4\u9ad8\u7684\u65f6\u95f4\u504f\u597d\u7387\u548c\u66f4\u4f4e\u7684\u8de8\u671f\u66ff\u4ee3\u5f39\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhag025", "journal": "RFS", "title": "Sovereign Default and the Decline in Interest Rates", "authors": ["Max Miller", "James D Paron", "Jessica A Wachter"], "author_details": [{"name": "Max Miller", "affiliations": ["Finance Unit, Harvard Business School, Harvard University ,"]}, {"name": "James D Paron", "affiliations": ["Stanford University ,"]}, {"name": "Jessica A Wachter", "affiliations": ["Wharton School, University of Pennsylvania ,"]}], "abstract": "Abstract Sovereign debt yields have undergone a historic decline over the last half century. Standard explanations, including aging populations and increases in asset demand from abroad, encounter difficulties when confronted with the full range of evidence. We propose an explanation based on a decline in inflation and default risk. We show that a model with sovereign default captures the decline in interest rates, the stability of equity valuation ratios, and the reduction in investment and output growth. Calibrations of the model post-COVID suggest that sovereign default risk may have returned.", "date": "2026-07-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag025", "title_zh": "\u4e3b\u6743\u8fdd\u7ea6\u4e0e\u5229\u7387\u7684\u4e0b\u964d", "abstract_zh": "\u6458\u8981 \u8fc7\u53bb\u534a\u4e2a\u4e16\u7eaa\uff0c\u4e3b\u6743\u503a\u52a1\u6536\u76ca\u7387\u7ecf\u5386\u4e86\u5386\u53f2\u6027\u4e0b\u964d\u3002\u6807\u51c6\u89e3\u91ca\uff0c\u5982\u4eba\u53e3\u8001\u9f84\u5316\u548c\u6d77\u5916\u8d44\u4ea7\u9700\u6c42\u589e\u52a0\uff0c\u5728\u9762\u5bf9\u5168\u90e8\u8bc1\u636e\u65f6\u9047\u5230\u4e86\u56f0\u96be\u3002\u6211\u4eec\u63d0\u51fa\u4e00\u4e2a\u57fa\u4e8e\u901a\u8d27\u81a8\u80c0\u7387\u4e0b\u964d\u548c\u8fdd\u7ea6\u98ce\u9669\u964d\u4f4e\u7684\u89e3\u91ca\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5305\u542b\u4e3b\u6743\u8fdd\u7ea6\u7684\u6a21\u578b\u80fd\u591f\u89e3\u91ca\u5229\u7387\u7684\u4e0b\u964d\u3001\u80a1\u6743\u4f30\u503c\u6bd4\u7387\u7684\u7a33\u5b9a\u4ee5\u53ca\u6295\u8d44\u548c\u4ea7\u51fa\u589e\u957f\u7684\u51cf\u5c11\u3002\u5bf9\u75ab\u60c5\u540e\u6a21\u578b\u7684\u6821\u51c6\u8868\u660e\uff0c\u4e3b\u6743\u8fdd\u7ea6\u98ce\u9669\u53ef\u80fd\u5df2\u7ecf\u56de\u5f52\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026103299", "journal": "JFQA", "title": "Location, Location, Location: Senate Trading and Seat Proximity", "authors": ["Dane M. Christensen", "Hengda Jin", "Beverly R. Walther", "Laura A. Wellman"], "author_details": [{"name": "Dane M. Christensen", "affiliations": ["University of Oregon Charles H Lundquist College of Business"]}, {"name": "Hengda Jin", "affiliations": ["Texas A&M University Mays Business School"]}, {"name": "Beverly R. Walther", "affiliations": ["Northwestern University Kellogg School of Management"]}, {"name": "Laura A. Wellman", "affiliations": ["University of Oregon Charles H Lundquist College of Business"]}], "abstract": "Abstract Using the distance between two Senators\u2019 desks to capture the proclivity to share information, we find that when two Senators sit closer together in the Senate Chamber, they are more likely to trade stocks in the same industry and earn larger returns, especially when they belong to the same political party. This association varies with Senators\u2019 information sources and power and the scrutiny they face. We perform multiple identification tests to support our inference that Senators share private trading information gleaned from their positions in Congress. Moreover, we provide the first evidence on the career benefits associated with sharing information.", "date": "2026-07-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103299", "title_zh": "\u4f4d\u7f6e\uff0c\u4f4d\u7f6e\uff0c\u4f4d\u7f6e\uff1a\u53c2\u8bae\u9662\u4ea4\u6613\u4e0e\u5ea7\u4f4d\u4e34\u8fd1", "abstract_zh": "\u5229\u7528\u4e24\u4f4d\u53c2\u8bae\u5458\u529e\u516c\u684c\u4e4b\u95f4\u7684\u8ddd\u79bb\u6765\u6355\u6349\u4ed6\u4eec\u5206\u4eab\u4fe1\u606f\u7684\u503e\u5411\uff0c\u6211\u4eec\u53d1\u73b0\u5f53\u4e24\u4f4d\u53c2\u8bae\u5458\u5728\u53c2\u8bae\u9662\u5927\u5385\u4e2d\u5750\u5f97\u66f4\u8fd1\u65f6\uff0c\u4ed6\u4eec\u66f4\u53ef\u80fd\u5728\u76f8\u540c\u884c\u4e1a\u4e2d\u8fdb\u884c\u80a1\u7968\u4ea4\u6613\uff0c\u5e76\u83b7\u5f97\u66f4\u9ad8\u7684\u56de\u62a5\uff0c\u5c24\u5176\u662f\u5728\u4ed6\u4eec\u5c5e\u4e8e\u540c\u4e00\u653f\u6cbb\u515a\u6d3e\u7684\u60c5\u51b5\u4e0b\u3002\u8fd9\u79cd\u5173\u8054\u4f1a\u968f\u7740\u53c2\u8bae\u5458\u7684\u4fe1\u606f\u6765\u6e90\u3001\u6743\u529b\u4ee5\u53ca\u4ed6\u4eec\u6240\u9762\u4e34\u7684\u76d1\u7763\u7a0b\u5ea6\u800c\u53d8\u5316\u3002\u6211\u4eec\u8fdb\u884c\u4e86\u591a\u79cd\u8bc6\u522b\u68c0\u9a8c\uff0c\u4ee5\u652f\u6301\u6211\u4eec\u7684\u63a8\u65ad\uff0c\u5373\u53c2\u8bae\u5458\u4eec\u4f1a\u4ece\u4ed6\u4eec\u5728\u56fd\u4f1a\u4e2d\u7684\u804c\u4f4d\u4e2d\u83b7\u53d6\u5e76\u5171\u4eab\u79c1\u4eba\u4ea4\u6613\u4fe1\u606f\u3002\u6b64\u5916\uff0c\u6211\u4eec\u9996\u6b21\u63d0\u4f9b\u4e86\u5206\u4eab\u4fe1\u606f\u4e0e\u804c\u4e1a\u6536\u76ca\u4e4b\u95f4\u5173\u8054\u7684\u8bc1\u636e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70065", "journal": "JF", "title": "M&As, Employee Costs, and Labor Reallocation", "authors": ["SPYRIDON LAGARAS"], "author_details": [{"name": "SPYRIDON LAGARAS", "affiliations": []}], "abstract": "ABSTRACT Mergers are associated with large and persistent earnings declines for incumbent employees in target firms. Linking employer\u2010employee administrative data with information on merger activity in Brazil, I find the negative effects concentrate on employees who exit target firms and reflect displacement in the short run and wage declines in the long run. Low\u2010skilled, managerial, and older employees fare worse. Overall, I conclude that mergers are followed by substantial reallocation costs reflecting losses of firm\u2010specific wage premiums, matching inefficiencies, and industry\u2010specific human capital depreciation, with employees transitioning to lower paying firms considered to be of lower productivity and employment value.", "date": "2026-07-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70065", "title_zh": "\u5e76\u8d2d\u3001\u5458\u5de5\u6210\u672c\u4e0e\u52b3\u52a8\u518d\u914d\u7f6e", "abstract_zh": "\u6458\u8981 \u5e76\u8d2d\u4e0e\u76ee\u6807\u516c\u53f8\u73b0\u6709\u5458\u5de5\u7684\u6536\u76ca\u4e0b\u964d\u5bc6\u5207\u76f8\u5173\u3002\u901a\u8fc7\u5c06\u96c7\u4e3b-\u5458\u5de5\u884c\u653f\u6570\u636e\u4e0e\u5df4\u897f\u5e76\u8d2d\u6d3b\u52a8\u4fe1\u606f\u76f8\u7ed3\u5408\uff0c\u6211\u53d1\u73b0\u8fd9\u79cd\u8d1f\u9762\u6548\u5e94\u4e3b\u8981\u96c6\u4e2d\u5728\u9000\u51fa\u76ee\u6807\u516c\u53f8\u7684\u5458\u5de5\u8eab\u4e0a\uff0c\u77ed\u671f\u5185\u8868\u73b0\u4e3a\u5c97\u4f4d\u66ff\u4ee3\uff0c\u957f\u671f\u5219\u8868\u73b0\u4e3a\u5de5\u8d44\u4e0b\u964d\u3002\u4f4e\u6280\u80fd\u3001\u7ba1\u7406\u5c42\u53ca\u5e74\u957f\u5458\u5de5\u7684\u5904\u5883\u66f4\u5dee\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u5f97\u51fa\u7ed3\u8bba\uff1a\u5e76\u8d2d\u540e\u4f1a\u4ea7\u751f\u5de8\u5927\u7684\u518d\u914d\u7f6e\u6210\u672c\uff0c\u8fd9\u4e9b\u6210\u672c\u6e90\u4e8e\u4f01\u4e1a\u7279\u5b9a\u5de5\u8d44\u6ea2\u4ef7\u7684\u4e27\u5931\u3001\u5339\u914d\u6548\u7387\u4f4e\u4e0b\u4ee5\u53ca\u884c\u4e1a\u7279\u5b9a\u4eba\u529b\u8d44\u672c\u7684\u8d2c\u503c\uff0c\u800c\u8f6c\u81f3\u85aa\u916c\u8f83\u4f4e\u516c\u53f8\u7684\u5458\u5de5\u88ab\u8ba4\u4e3a\u751f\u4ea7\u7387\u548c\u5c31\u4e1a\u4ef7\u503c\u66f4\u4f4e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1093/rfs/hhag062", "journal": "RFS", "title": "What Hundreds of Economic News Events Say About Belief Overreaction in the Stock Market", "authors": ["Francesco Bianchi", "Sydney C Ludvigson", "Sai Ma"], "author_details": [{"name": "Francesco Bianchi", "affiliations": ["Johns Hopkins, CEPR, and NBER ,"]}, {"name": "Sydney C Ludvigson", "affiliations": ["NYU, CEPR, and NBER ,"]}, {"name": "Sai Ma", "affiliations": ["Federal Reserve Board ,"]}], "abstract": "Abstract We measure the nature and severity of a variety of belief distortions in market reactions to hundreds of economic news events by synthesizing structural estimation with algorithmic machine learning to quantify bias. We find that investors systematically overreact to perceptions about multiple fundamental shocks, a phenomenon we show often dampens rather than amplifies market volatility via a \u201cshock composition effect.\u201d Such effects imply that the stock market can underreact to news, even when investors overreact to all shocks.", "date": "2026-07-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag062", "title_zh": "\u6570\u767e\u4e2a\u7ecf\u6d4e\u65b0\u95fb\u4e8b\u4ef6\u63ed\u793a\u4e86\u6295\u8d44\u8005\u4fe1\u5ff5\u8fc7\u5ea6\u53cd\u5e94\u5728\u80a1\u5e02\u4e2d\u7684\u8868\u73b0", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u901a\u8fc7\u7ed3\u5408\u7ed3\u6784\u4f30\u8ba1\u4e0e\u7b97\u6cd5\u673a\u5668\u5b66\u4e60\u6280\u672f\uff0c\u91cf\u5316\u4e86\u6295\u8d44\u8005\u5bf9\u6570\u767e\u4e2a\u7ecf\u6d4e\u65b0\u95fb\u4e8b\u4ef6\u4e2d\u591a\u79cd\u4fe1\u5ff5\u626d\u66f2\u7684\u6027\u8d28\u548c\u4e25\u91cd\u7a0b\u5ea6\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u6295\u8d44\u8005\u7cfb\u7edf\u6027\u5730\u5bf9\u591a\u91cd\u57fa\u672c\u9762\u51b2\u51fb\u7684\u611f\u77e5\u8fc7\u5ea6\u53cd\u5e94\uff0c\u6211\u4eec\u8bc1\u660e\u8fd9\u79cd\u73b0\u8c61\u5f80\u5f80\u901a\u8fc7\u201c\u51b2\u51fb\u7ec4\u6210\u6548\u5e94\u201d\u6291\u5236\u800c\u975e\u653e\u5927\u5e02\u573a\u6ce2\u52a8\u3002\u8fd9\u79cd\u6548\u5e94\u610f\u5473\u7740\uff0c\u5373\u4f7f\u6295\u8d44\u8005\u5bf9\u6240\u6709\u51b2\u51fb\u90fd\u5b58\u5728\u8fc7\u5ea6\u53cd\u5e94\uff0c\u80a1\u5e02\u4e5f\u53ef\u80fd\u5bf9\u65b0\u95fb\u4fe1\u606f\u53cd\u5e94\u4e0d\u8db3\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1093/restud/rdag078", "journal": "REStud", "title": "Industrial Clusters in the Long Run: Evidence from Million-Rouble Plants in China", "authors": ["Stephan Heblich", "Marlon Seror", "Hao Xu", "Yanos Zylberberg"], "author_details": [{"name": "Stephan Heblich", "affiliations": ["University of Toronto , Canada, NBER ,"]}, {"name": "Marlon Seror", "affiliations": ["Universit\u00e9 du Qu\u00e9bec \u00e0 Montr\u00e9al ,"]}, {"name": "Hao Xu", "affiliations": ["China Construction Bank ,"]}, {"name": "Yanos Zylberberg", "affiliations": ["University of Bristol , CEPR ,"]}], "abstract": "Abstract We study the impact of large, successful manufacturing plants on other local producers in China, focusing on \u201cMillion-Rouble Plants\u201d built in the 1950s during a brief alliance with the U.S.S.R. The ephemeral geopolitical situation and the locations of allied and enemy airbases provide exogenous variation in plant siting. We find a boom-and-bust pattern: Counties hosting these plants were 80% more productive than control counties in 1982 but 20% less productive by 2010. This decline reflects the performance of local establishments, which exhibit low productivity, limited innovation, and high markup. Specialization hindered spillovers, preventing the emergence of new clusters and local entrepreneurship.", "date": "2026-07-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag078", "title_zh": "\u957f\u671f\u89c6\u89d2\u4e0b\u7684\u4ea7\u4e1a\u96c6\u7fa4\uff1a\u6765\u81ea\u4e2d\u56fd\u767e\u4e07\u4eba\u6c11\u5e01\u5de5\u5382\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e2d\u56fd\u5927\u578b\u6210\u529f\u5236\u9020\u5de5\u5382\u5bf9\u5f53\u5730\u5176\u4ed6\u751f\u4ea7\u4f01\u4e1a\u7684\u5f71\u54cd\u529b\uff0c\u91cd\u70b9\u5173\u6ce81950\u5e74\u4ee3\u5728\u4e0e\u4e2d\u56fd\u82cf\u8054\u77ed\u6682\u5408\u4f5c\u671f\u95f4\u5efa\u7acb\u7684\u201c\u767e\u4e07\u4eba\u6c11\u5e01\u5de5\u5382\u201d\u3002\u77ed\u6682\u7684\u5730\u7f18\u653f\u6cbb\u5c40\u52bf\u4ee5\u53ca\u76df\u53cb\u4e0e\u654c\u5bf9\u56fd\u5bb6\u7a7a\u519b\u57fa\u5730\u7684\u5206\u5e03\u4e3a\u5de5\u5382\u9009\u5740\u63d0\u4f9b\u4e86\u5916\u751f\u53d8\u5f02\u3002\u6211\u4eec\u53d1\u73b0\u4e86\u4e00\u79cd\u5174\u8870\u4ea4\u66ff\u7684\u6a21\u5f0f\uff1a\u62e5\u6709\u8fd9\u4e9b\u5de5\u5382\u7684\u53bf\u57281982\u5e74\u6bd4\u5bf9\u7167\u53bf\u7684\u751f\u4ea7\u529b\u9ad8\u51fa80%\uff0c\u4f46\u52302010\u5e74\u5374\u4e0b\u964d\u4e8620%\u3002\u8fd9\u79cd\u4e0b\u964d\u53cd\u6620\u4e86\u5f53\u5730\u4f01\u4e1a\u7684\u8868\u73b0\uff0c\u8fd9\u4e9b\u4f01\u4e1a\u8868\u73b0\u51fa\u4f4e\u751f\u4ea7\u7387\u3001\u521b\u65b0\u6709\u9650\u4ee5\u53ca\u9ad8\u6ea2\u4ef7\u3002\u4e13\u4e1a\u5316\u963b\u788d\u4e86\u6ea2\u51fa\u6548\u5e94\uff0c\u6291\u5236\u4e86\u65b0\u96c6\u7fa4\u7684\u5f62\u6210\u548c\u672c\u5730\u521b\u4e1a\u7684\u51fa\u73b0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.1093/restud/rdag079", "journal": "REStud", "title": "The Long Shadow of Housing Discrimination: Evidence from Racial Covenants", "authors": ["Aradhya Sood", "Kevin Ehrman-Solberg"], "author_details": [{"name": "Aradhya Sood", "affiliations": ["University of Toronto , Canada"]}, {"name": "Kevin Ehrman-Solberg", "affiliations": ["Mapping Prejudice , USA"]}], "abstract": "Abstract Racial covenants in housing deeds were widely used in the United States during the early 20th century to segregate neighbourhoods. In 1948, the Supreme Court decision in Shelley v. Kraemer made racial covenants unenforceable in court, stopping short of prohibiting them entirely. We surmise that even after losing their judicial enforceability, such covenants could have shaped segregation if they served as a focal point for coordination on an initial equilibrium in neighbourhood formation, a context characterised by investment durability and path dependency. To test this hypothesis, we assemble novel parcel-level data on racial covenants and develop a quasi-experimental design that exploits delays between covenant execution and housing construction to isolate exposure to enforceable covenants at the time neighbourhoods were built. Covenant enforceability indeed affected early-stage neighbourhood formation in terms of housing characteristics, public infrastructure placement, and the composition of initial residents. These early differences proved durable: A one standard deviation increase in neighborhood exposure to enforceable covenants accounts for 6%\u201324% of the observed neighbourhood racial segregation from 1980 to 2020 and 3.1%\u20134.4% of housing price differentials in the 21st century. We conclude that by coordinating beliefs and decisions during neighbourhood formation, the law generated spatial inequality that has long outlived racial covenants themselves.", "date": "2026-07-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag079", "title_zh": "\u4f4f\u623f\u6b67\u89c6\u7684\u957f\u671f\u9634\u5f71\uff1a\u6765\u81ea\u79cd\u65cf\u5951\u7ea6\u7684\u8bc1\u636e", "abstract_zh": "\u6458\u8981 20\u4e16\u7eaa\u65e9\u671f\uff0c\u7f8e\u56fd\u5e7f\u6cdb\u4f7f\u7528\u4f4f\u623f\u5951\u7ea6\u4e2d\u7684\u79cd\u65cf\u5951\u7ea6\u6765\u5212\u5206\u793e\u533a\u30021948\u5e74\uff0c\u7f8e\u56fd\u6700\u9ad8\u6cd5\u9662\u5728Shelley v. Kraemer\u6848\u4e2d\u88c1\u5b9a\u79cd\u65cf\u5951\u7ea6\u5728\u6cd5\u9662\u4e2d\u4e0d\u53ef\u6267\u884c\uff0c\u4f46\u5e76\u672a\u5b8c\u5168\u7981\u6b62\u5176\u4f7f\u7528\u3002\u6211\u4eec\u63a8\u6d4b\uff0c\u5373\u4f7f\u5728\u5931\u53bb\u53f8\u6cd5\u6267\u884c\u529b\u540e\uff0c\u8fd9\u4e9b\u5951\u7ea6\u4ecd\u53ef\u80fd\u901a\u8fc7\u4f5c\u4e3a\u90bb\u91cc\u5f62\u6210\u521d\u671f\u5747\u8861\u534f\u8c03\u7684\u7126\u70b9\uff0c\u5f71\u54cd\u793e\u533a\u7684\u9694\u79bb\u73b0\u8c61\uff0c\u8fd9\u79cd\u60c5\u5883\u5177\u6709\u6295\u8d44\u7684\u6301\u4e45\u6027\u548c\u8def\u5f84\u4f9d\u8d56\u6027\u3002\u4e3a\u4e86\u68c0\u9a8c\u8fd9\u4e00\u5047\u8bbe\uff0c\u6211\u4eec\u6536\u96c6\u4e86\u5173\u4e8e\u79cd\u65cf\u5951\u7ea6\u7684\u5168\u65b0\u5730\u5757\u7ea7\u6570\u636e\uff0c\u5e76\u8bbe\u8ba1\u4e86\u4e00\u4e2a\u51c6\u5b9e\u9a8c\u65b9\u6cd5\uff0c\u5229\u7528\u5951\u7ea6\u6267\u884c\u4e0e\u4f4f\u623f\u5efa\u8bbe\u4e4b\u95f4\u7684\u65f6\u95f4\u5dee\uff0c\u6765\u8bc6\u522b\u5728\u793e\u533a\u5efa\u6210\u521d\u671f\u6240\u66b4\u9732\u4e8e\u53ef\u6267\u884c\u5951\u7ea6\u7684\u60c5\u51b5\u3002\u7ed3\u679c\u8868\u660e\uff0c\u5951\u7ea6\u7684\u53ef\u6267\u884c\u6027\u786e\u5b9e\u5f71\u54cd\u4e86\u793e\u533a\u65e9\u671f\u5f62\u6210\u9636\u6bb5\u7684\u7279\u5f81\uff0c\u5305\u62ec\u4f4f\u623f\u5c5e\u6027\u3001\u516c\u5171\u57fa\u7840\u8bbe\u65bd\u7684\u5e03\u5c40\u4ee5\u53ca\u521d\u59cb\u5c45\u6c11\u7684\u6784\u6210\u3002\u8fd9\u4e9b\u65e9\u671f\u5dee\u5f02\u5177\u6709\u6301\u4e45\u6027\uff1a\u793e\u533a\u5bf9\u53ef\u6267\u884c\u5951\u7ea6\u7684\u66b4\u9732\u7a0b\u5ea6\u6bcf\u589e\u52a0\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u53ef\u89e3\u91ca1980\u5e74\u81f32020\u5e74\u95f4\u793e\u533a\u79cd\u65cf\u9694\u79bb\u73b0\u8c61\u76846%\u81f324%\uff0c\u4ee5\u53ca21\u4e16\u7eaa\u4f4f\u623f\u4ef7\u683c\u5dee\u5f02\u76843.1%\u81f34.4%\u3002\u6211\u4eec\u5f97\u51fa\u7ed3\u8bba\uff0c\u901a\u8fc7\u5728\u793e\u533a\u5f62\u6210\u521d\u671f\u534f\u8c03\u4eba\u4eec\u7684\u4fe1\u5ff5\u548c\u51b3\u7b56\uff0c\u6cd5\u5f8b\u4ea7\u751f\u4e86\u957f\u671f\u6301\u7eed\u7684\u7a7a\u95f4\u4e0d\u5e73\u7b49\uff0c\u8fd9\u79cd\u4e0d\u5e73\u7b49\u8fdc\u8fdc\u8d85\u8fc7\u4e86\u79cd\u65cf\u5951\u7ea6\u672c\u8eab\u7684\u5b58\u5728\u65f6\u95f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag058", "journal": "RFS", "title": "Government Intervention in the Financial Market", "authors": ["Jiang Wang"], "author_details": [{"name": "Jiang Wang", "affiliations": ["Massachusetts Institute of Technology and NBER ,"]}], "abstract": "Abstract Government intervention in the financial market through its own trading fundamentally changes the market\u2019s structure, function, and outcome. I develop a general equilibrium framework to study the impact of government trading on investor welfare. I show that with incompleteness and information asymmetry, the market equilibrium is in general suboptimal, and government intervention can potentially improve investor welfare even with no additional information. However, the actual welfare impact of government intervention is sensitive to the details of the economy and the policy design. Popular policy targets such as price stability, market liquidity, and informational efficiency can have different welfare implications.", "date": "2026-07-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag058", "title_zh": "\u653f\u5e9c\u5bf9\u91d1\u878d\u5e02\u573a\u7684\u5e72\u9884", "abstract_zh": "\u6458\u8981 \u653f\u5e9c\u901a\u8fc7\u81ea\u8eab\u4ea4\u6613\u5e72\u9884\u91d1\u878d\u5e02\u573a\uff0c\u4ece\u6839\u672c\u4e0a\u6539\u53d8\u4e86\u5e02\u573a\u7684\u7ed3\u6784\u3001\u529f\u80fd\u548c\u7ed3\u679c\u3002\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u4e00\u822c\u5747\u8861\u6846\u67b6\uff0c\u7814\u7a76\u653f\u5e9c\u4ea4\u6613\u5bf9\u6295\u8d44\u8005\u798f\u5229\u7684\u5f71\u54cd\u3002\u6211\u8bc1\u660e\uff0c\u5728\u4e0d\u5b8c\u5168\u6027\u548c\u4fe1\u606f\u4e0d\u5bf9\u79f0\u7684\u60c5\u51b5\u4e0b\uff0c\u5e02\u573a\u5747\u8861\u901a\u5e38\u5904\u4e8e\u975e\u6700\u4f18\u72b6\u6001\uff0c\u5373\u4f7f\u6ca1\u6709\u989d\u5916\u4fe1\u606f\uff0c\u653f\u5e9c\u5e72\u9884\u4e5f\u6709\u53ef\u80fd\u63d0\u5347\u6295\u8d44\u8005\u798f\u5229\u3002\u7136\u800c\uff0c\u653f\u5e9c\u5e72\u9884\u7684\u5b9e\u9645\u798f\u5229\u6548\u5e94\u5bf9\u7ecf\u6d4e\u7ec6\u8282\u548c\u653f\u7b56\u8bbe\u8ba1\u975e\u5e38\u654f\u611f\u3002\u5e38\u89c1\u7684\u653f\u7b56\u76ee\u6807\uff0c\u5982\u4ef7\u683c\u7a33\u5b9a\u3001\u5e02\u573a\u6d41\u52a8\u6027\u4ee5\u53ca\u4fe1\u606f\u6548\u7387\uff0c\u53ef\u80fd\u5e26\u6765\u4e0d\u540c\u7684\u798f\u5229\u540e\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e02\u573a\u53cd\u9988"]}, {"doi": "10.1093/restud/rdag077", "journal": "REStud", "title": "Smooth Diagnostic Expectations", "authors": ["Francesco Bianchi", "Cosmin Ilut", "Hikaru Saijo"], "author_details": [{"name": "Francesco Bianchi", "affiliations": ["Johns Hopkins University, CEPR and NBER , USA"]}, {"name": "Cosmin Ilut", "affiliations": ["Duke University, NBER ,"]}, {"name": "Hikaru Saijo", "affiliations": ["UC Santa Cruz , USA"]}], "abstract": "Abstract We show that the formalization of representativeness (Kahneman and Tversky, 1972, Cognitive Psychology, 3, 430\u2013454) developed by Gennaioli and Shleifer (2010, The Quarterly Journal of Economics, 125, 1399\u20131433) features an intrinsic connection between uncertainty and overreaction. In the time series domain, we develop this connection in a smooth version of diagnostic expectations (DE), where overreaction varies smoothly with uncertainty. Intuitively, under smoothness, lower uncertainty leaves less room for representativeness to distort beliefs. Smooth DE provides a joint, parsimonious micro-foundation for key features of survey data: overreaction to news, stronger overreaction at longer horizons, overconfidence in subjective uncertainty, and a new stylized fact documented here\u2014overreaction intensifies with higher uncertainty. An analytical Real Business Cycle model with Smooth DE accounts for survey overreaction and overconfidence, as well as three salient business cycle properties: asymmetry, countercyclical macro volatility, and countercyclical micro volatility.", "date": "2026-07-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag077", "title_zh": "\u5e73\u6ed1\u7684\u8bca\u65ad\u9884\u671f", "abstract_zh": "\u6211\u4eec\u8bc1\u660e\u4e86Gennaioli\u548cShleifer\uff082010\u5e74\uff0c\u300a\u5b63\u5ea6\u7ecf\u6d4e\u8bc4\u8bba\u300b\uff0c125\u5377\uff0c\u7b2c1399-1433\u9875\uff09\u5bf9Kahneman\u548cTversky\uff081972\u5e74\uff0c\u300a\u8ba4\u77e5\u5fc3\u7406\u5b66\u300b\uff0c3\u5377\uff0c\u7b2c430-454\u9875\uff09\u63d0\u51fa\u7684\u4ee3\u8868\u6027\u6982\u5ff5\u7684\u6b63\u5f0f\u5316\uff0c\u5177\u6709\u4e0d\u786e\u5b9a\u6027\u4e0e\u8fc7\u5ea6\u53cd\u5e94\u4e4b\u95f4\u7684\u5185\u5728\u8054\u7cfb\u3002\u5728\u65f6\u95f4\u5e8f\u5217\u9886\u57df\uff0c\u6211\u4eec\u57fa\u4e8e\u5e73\u6ed1\u7684\u8bca\u65ad\u9884\u671f\uff08DE\uff09\u6a21\u578b\u53d1\u5c55\u4e86\u8fd9\u4e00\u8054\u7cfb\uff0c\u5176\u4e2d\u8fc7\u5ea6\u53cd\u5e94\u968f\u4e0d\u786e\u5b9a\u6027\u5e73\u6ed1\u53d8\u5316\u3002\u76f4\u89c2\u4e0a\uff0c\u5728\u5e73\u6ed1\u6027\u6761\u4ef6\u4e0b\uff0c\u8f83\u4f4e\u7684\u4e0d\u786e\u5b9a\u6027\u4e3a\u4ee3\u8868\u6027\u626d\u66f2\u4fe1\u5ff5\u7559\u4e0b\u7684\u7a7a\u95f4\u66f4\u5c0f\u3002\u5e73\u6ed1\u7684DE\u4e3a\u8c03\u67e5\u6570\u636e\u4e2d\u7684\u5173\u952e\u7279\u5f81\u63d0\u4f9b\u4e86\u7edf\u4e00\u4e14\u7b80\u6d01\u7684\u5fae\u89c2\u57fa\u7840\uff1a\u5bf9\u65b0\u95fb\u7684\u8fc7\u5ea6\u53cd\u5e94\u3001\u5728\u66f4\u957f\u5468\u671f\u5185\u66f4\u5f3a\u7684\u8fc7\u5ea6\u53cd\u5e94\u3001\u5bf9\u4e3b\u89c2\u4e0d\u786e\u5b9a\u6027\u7684\u8fc7\u5ea6\u81ea\u4fe1\uff0c\u4ee5\u53ca\u672c\u6587\u65b0\u53d1\u73b0\u7684\u4e00\u4e2a\u98ce\u683c\u4e8b\u5b9e\u2014\u2014\u8fc7\u5ea6\u53cd\u5e94\u968f\u7740\u4e0d\u786e\u5b9a\u6027\u589e\u52a0\u800c\u52a0\u5267\u3002\u4e00\u4e2a\u5177\u6709\u5e73\u6ed1\u8bca\u65ad\u9884\u671f\u7684\u5206\u6790\u578b\u73b0\u5b9e\u5546\u4e1a\u5468\u671f\u6a21\u578b\u80fd\u591f\u89e3\u91ca\u8c03\u67e5\u6570\u636e\u4e2d\u7684\u8fc7\u5ea6\u53cd\u5e94\u548c\u8fc7\u5ea6\u81ea\u4fe1\uff0c\u4ee5\u53ca\u4e09\u4e2a\u663e\u8457\u7684\u5546\u4e1a\u5468\u671f\u7279\u5f81\uff1a\u4e0d\u5bf9\u79f0\u6027\u3001\u9006\u5468\u671f\u7684\u5b8f\u89c2\u7ecf\u6d4e\u6ce2\u52a8\u548c\u9006\u5468\u671f\u7684\u5fae\u89c2\u7ecf\u6d4e\u6ce2\u52a8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag065", "journal": "RFS", "title": "Voting Choice", "authors": ["Andrey Malenko", "Nadya Malenko"], "author_details": [{"name": "Andrey Malenko", "affiliations": ["Boston College ,"]}, {"name": "Nadya Malenko", "affiliations": ["Boston College ,"]}], "abstract": "Abstract Traditionally, fund managers cast votes on behalf of fund investors. Recently, there is a shift toward \u201cpass-through voting,\u201d with funds offering investors a choice: delegate votes to the fund or vote themselves. We develop a framework to study the implications of voting choice. While it helps reflect heterogeneous investor preferences, it also shapes the informational content of the vote, and these forces can conflict. When interests are aligned, voting choice improves information aggregation and investor welfare. With preference heterogeneity or costly information, however, it can make investors worse off by weakening informed decision making and fund managers\u2019 incentives to acquire information.", "date": "2026-07-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag065", "title_zh": "\u6295\u7968\u9009\u62e9", "abstract_zh": "\u4f20\u7edf\u4e0a\uff0c\u57fa\u91d1\u7ecf\u7406\u4ee3\u8868\u57fa\u91d1\u6295\u8d44\u8005\u884c\u4f7f\u6295\u7968\u6743\u3002\u8fd1\u5e74\u6765\uff0c\u51fa\u73b0\u4e86\u5411\u2018\u6295\u7968\u6743\u4f20\u9012\u2019\u8f6c\u53d8\u7684\u8d8b\u52bf\uff0c\u57fa\u91d1\u4e3a\u6295\u8d44\u8005\u63d0\u4f9b\u9009\u62e9\uff1a\u5c06\u6295\u7968\u6743\u59d4\u6258\u7ed9\u57fa\u91d1\uff0c\u6216\u7531\u6295\u8d44\u8005\u81ea\u884c\u6295\u7968\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6846\u67b6\u6765\u7814\u7a76\u6295\u7968\u9009\u62e9\u7684\u540e\u679c\u3002\u867d\u7136\u8fd9\u6709\u52a9\u4e8e\u53cd\u6620\u6295\u8d44\u8005\u504f\u597d\u7684\u5f02\u8d28\u6027\uff0c\u4f46\u4e5f\u4f1a\u5f71\u54cd\u6295\u7968\u4fe1\u606f\u7684\u5185\u5bb9\uff0c\u8fd9\u4e24\u65b9\u9762\u7684\u4f5c\u7528\u53ef\u80fd\u5b58\u5728\u51b2\u7a81\u3002\u5f53\u5229\u76ca\u4e00\u81f4\u65f6\uff0c\u6295\u7968\u9009\u62e9\u6709\u52a9\u4e8e\u63d0\u5347\u4fe1\u606f\u805a\u5408\u7a0b\u5ea6\u548c\u6295\u8d44\u8005\u798f\u5229\u3002\u7136\u800c\uff0c\u5f53\u5b58\u5728\u504f\u597d\u5f02\u8d28\u6027\u6216\u4fe1\u606f\u83b7\u53d6\u6210\u672c\u65f6\uff0c\u5b83\u53ef\u80fd\u4f7f\u6295\u8d44\u8005\u5904\u5883\u6076\u5316\uff0c\u56e0\u4e3a\u4f1a\u524a\u5f31\u77e5\u60c5\u51b3\u7b56\u548c\u57fa\u91d1\u7ecf\u7406\u83b7\u53d6\u4fe1\u606f\u7684\u6fc0\u52b1\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag064", "journal": "RFS", "title": "Generative AI and Data Quality: Implications for Productivity, Labor Displacement, and Policy", "authors": ["Zhifeng Cai"], "author_details": [{"name": "Zhifeng Cai", "affiliations": ["Rutgers University ,"]}], "abstract": "Abstract Generative artificial intelligence (AI) is increasingly consuming and producing huge amounts of data. We propose a social learning model of AI, emphasizing a data-AI feedback loop: data quality affects AI productivity, which influences AI adoption and, consequently, the composition (AI versus human-generated) and quality of future data. Calibrated to evidence on synthetic training loops, the model predicts hump-shaped labor dynamics\u2014short-term displacement that partially reverses as data quality deteriorates. A Grossman\u2013Stiglitz-style externality emerges: AI adopters free-ride on the human-generated actions that supply the novel information on which AI itself relies. In a competitive market, AI should be taxed to correct the data-quality externality; a concentrated AI industry overcorrects, making a subsidy optimal.", "date": "2026-07-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag064", "title_zh": "\u751f\u6210\u5f0f\u4eba\u5de5\u667a\u80fd\u4e0e\u6570\u636e\u8d28\u91cf\uff1a\u5bf9\u751f\u4ea7\u7387\u3001\u52b3\u52a8\u529b\u66ff\u4ee3\u53ca\u653f\u7b56\u7684\u5f71\u54cd", "abstract_zh": "\u62bd\u8c61 \u751f\u6210\u5f0f\u4eba\u5de5\u667a\u80fd\uff08AI\uff09\u6b63\u8d8a\u6765\u8d8a\u591a\u5730\u6d88\u8017\u548c\u751f\u6210\u5927\u91cf\u6570\u636e\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u4eba\u5de5\u667a\u80fd\u7684\u793e\u4f1a\u5b66\u4e60\u6a21\u578b\uff0c\u5f3a\u8c03\u6570\u636e\u4e0eAI\u4e4b\u95f4\u7684\u53cd\u9988\u5faa\u73af\uff1a\u6570\u636e\u8d28\u91cf\u5f71\u54cdAI\u7684\u751f\u4ea7\u7387\uff0c\u8fdb\u800c\u5f71\u54cdAI\u7684\u91c7\u7eb3\uff0c\u4ece\u800c\u6539\u53d8\u672a\u6765\u6570\u636e\u7684\u6784\u6210\uff08AI\u751f\u6210\u4e0e\u4eba\u7c7b\u751f\u6210\uff09\u53ca\u5176\u8d28\u91cf\u3002\u8be5\u6a21\u578b\u57fa\u4e8e\u5408\u6210\u8bad\u7ec3\u5faa\u73af\u7684\u5b9e\u8bc1\u8bc1\u636e\u8fdb\u884c\u6821\u51c6\uff0c\u9884\u6d4b\u51fa\u52b3\u52a8\u5e02\u573a\u7684\u9a7c\u5cf0\u578b\u52a8\u6001\u2014\u2014\u77ed\u671f\u5185\u51fa\u73b0\u52b3\u52a8\u529b\u66ff\u4ee3\uff0c\u4f46\u968f\u7740\u6570\u636e\u8d28\u91cf\u4e0b\u964d\uff0c\u8fd9\u79cd\u66ff\u4ee3\u90e8\u5206\u9006\u8f6c\u3002\u4e00\u79cd\u7c7b\u4f3c\u683c\u7f57\u65af\u66fc-\u65af\u8482\u683c\u5c14\u7684\u5916\u90e8\u6027\u51fa\u73b0\uff1aAI\u91c7\u7eb3\u8005\u65e0\u507f\u4eab\u53d7\u4eba\u7c7b\u884c\u4e3a\u6240\u4ea7\u751f\u7684\u65b0\u4fe1\u606f\uff0c\u8fd9\u4e9b\u4fe1\u606f\u662fAI\u81ea\u8eab\u4f9d\u8d56\u7684\u57fa\u7840\u3002\u5728\u7ade\u4e89\u6027\u5e02\u573a\u4e2d\uff0c\u5e94\u5bf9AI\u5f81\u7a0e\u4ee5\u7ea0\u6b63\u6570\u636e\u8d28\u91cf\u7684\u5916\u90e8\u6027\uff1b\u800c\u5728\u96c6\u4e2d\u5316\u7684AI\u4ea7\u4e1a\u4e2d\uff0c\u8fd9\u79cd\u7ea0\u6b63\u8fc7\u5ea6\uff0c\u56e0\u6b64\u8865\u8d34\u6210\u4e3a\u6700\u4f18\u9009\u62e9\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e02\u573a\u53cd\u9988", "AI"]}, {"doi": "10.1017/s0022109026103238", "journal": "JFQA", "title": "The Impact of a Principles-Based Approach to Director Gender Diversity", "authors": ["Tor-Erik Bakke", "Laura Casares Field", "Hamed Mahmudi", "Aazam Virani"], "author_details": [{"name": "Tor-Erik Bakke", "affiliations": ["University of Illinois Chicago"]}, {"name": "Laura Casares Field", "affiliations": ["University of Delaware"]}, {"name": "Hamed Mahmudi", "affiliations": ["University of Nevada Las Vegas"]}, {"name": "Aazam Virani", "affiliations": []}], "abstract": "Abstract We study the impact of a principles-based regulatory approach to female board representation, requiring firms to disclose a gender diversity policy or explain its absence. Post-regulation, firms respond with more female-friendly disclosures. However, those with less access to female directors often justify their lack of diversity. Although the regulation does not mandate increasing female board representation, the fraction of female directors increases by 38% relative to control groups after the regulation. Investors respond to the disclosures, increasingly engaging firms and voting against boards with low female representation. Firms most likely impacted by the regulation exhibit positive abnormal announcement returns.", "date": "2026-07-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103238", "title_zh": "\u57fa\u4e8e\u539f\u5219\u7684\u8463\u4e8b\u6027\u522b\u591a\u6837\u6027\u63aa\u65bd\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u57fa\u4e8e\u539f\u5219\u7684\u76d1\u7ba1\u63aa\u65bd\u5bf9\u5973\u6027\u8463\u4e8b\u4f1a\u6210\u5458\u6bd4\u4f8b\u7684\u5f71\u54cd\uff0c\u8be5\u63aa\u65bd\u8981\u6c42\u4f01\u4e1a\u62ab\u9732\u6027\u522b\u591a\u6837\u6027\u653f\u7b56\u6216\u8bf4\u660e\u5176\u7f3a\u5931\u3002\u76d1\u7ba1\u5b9e\u65bd\u540e\uff0c\u4f01\u4e1a\u66f4\u503e\u5411\u4e8e\u53d1\u5e03\u6709\u5229\u4e8e\u5973\u6027\u7684\u62ab\u9732\u5185\u5bb9\u3002\u7136\u800c\uff0c\u90a3\u4e9b\u83b7\u53d6\u5973\u6027\u8463\u4e8b\u8d44\u6e90\u8f83\u5c11\u7684\u4f01\u4e1a\u5f80\u5f80\u4ee5\u7f3a\u4e4f\u591a\u6837\u6027\u4e3a\u7531\u8fdb\u884c\u8fa9\u62a4\u3002\u5c3d\u7ba1\u8be5\u76d1\u7ba1\u63aa\u65bd\u5e76\u672a\u5f3a\u5236\u8981\u6c42\u589e\u52a0\u5973\u6027\u8463\u4e8b\u4f1a\u6210\u5458\u7684\u6bd4\u4f8b\uff0c\u4f46\u5728\u76d1\u7ba1\u4e4b\u540e\uff0c\u5973\u6027\u8463\u4e8b\u7684\u6bd4\u4f8b\u76f8\u6bd4\u5bf9\u7167\u7ec4\u63d0\u9ad8\u4e8638%\u3002\u6295\u8d44\u8005\u5bf9\u8fd9\u4e9b\u62ab\u9732\u5185\u5bb9\u4f5c\u51fa\u53cd\u5e94\uff0c\u66f4\u52a0\u79ef\u6781\u5730\u53c2\u4e0e\u4f01\u4e1a\u6d3b\u52a8\uff0c\u5e76\u5bf9\u5973\u6027\u4ee3\u8868\u6bd4\u4f8b\u8f83\u4f4e\u7684\u8463\u4e8b\u4f1a\u6295\u51fa\u53cd\u5bf9\u7968\u3002\u53d7\u5230\u8be5\u76d1\u7ba1\u63aa\u65bd\u5f71\u54cd\u6700\u5927\u7684\u4f01\u4e1a\uff0c\u5728\u516c\u544a\u671f\u95f4\u8868\u73b0\u51fa\u6b63\u5411\u5f02\u5e38\u56de\u62a5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s002210902610324x", "journal": "JFQA", "title": "Continuity and Change on Corporate Boards", "authors": ["Peter Cziraki", "Adriana Z. Robertson"], "author_details": [{"name": "Peter Cziraki", "affiliations": ["Texas A&M University Mays Business School"]}, {"name": "Adriana Z. Robertson", "affiliations": ["University of Chicago Law School"]}], "abstract": "Abstract The number of women on public company boards has increased dramatically in recent years. We study where these women directors came from and how they were absorbed. Since 2018, women with board experience have obtained significantly more board seats than their male counterparts. Women directors are also more likely to have no previous board experience than men, indicating movement on both the intensive and extensive margins. Adding a woman director is associated with a transitory increase in board size roughly one third of the time. This increase is offset when an existing director rolls off, which typically happens within 1 year.", "date": "2026-07-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s002210902610324x", "title_zh": "\u516c\u53f8\u8463\u4e8b\u4f1a\u4e2d\u7684\u8fde\u7eed\u6027\u4e0e\u53d8\u9769", "abstract_zh": "\u6458\u8981 \u8fd1\u5e74\u6765\uff0c\u4e0a\u5e02\u516c\u53f8\u8463\u4e8b\u4f1a\u4e2d\u7684\u5973\u6027\u6210\u5458\u6570\u91cf\u663e\u8457\u589e\u52a0\u3002\u6211\u4eec\u7814\u7a76\u4e86\u8fd9\u4e9b\u5973\u6027\u8463\u4e8b\u7684\u6765\u6e90\u4ee5\u53ca\u5979\u4eec\u662f\u5982\u4f55\u88ab\u5438\u7eb3\u8fdb\u8463\u4e8b\u4f1a\u7684\u3002\u81ea2018\u5e74\u4ee5\u6765\uff0c\u5177\u6709\u8463\u4e8b\u4f1a\u7ecf\u9a8c\u7684\u5973\u6027\u8463\u4e8b\u83b7\u5f97\u7684\u8463\u4e8b\u4f1a\u5e2d\u4f4d\u663e\u8457\u591a\u4e8e\u7537\u6027\u8463\u4e8b\u3002\u5973\u6027\u8463\u4e8b\u66f4\u6709\u53ef\u80fd\u6ca1\u6709\u5148\u524d\u7684\u8463\u4e8b\u4f1a\u7ecf\u9a8c\uff0c\u8fd9\u8868\u660e\u5728\u5bc6\u96c6\u6027\u548c\u5e7f\u5ea6\u4e0a\u5747\u51fa\u73b0\u4e86\u53d8\u5316\u3002\u589e\u52a0\u4e00\u540d\u5973\u6027\u8463\u4e8b\u5927\u7ea6\u6709\u4e09\u5206\u4e4b\u4e00\u7684\u65f6\u95f4\u4f1a\u5e26\u6765\u8463\u4e8b\u4f1a\u89c4\u6a21\u7684\u6682\u65f6\u6027\u4e0a\u5347\u3002\u8fd9\u79cd\u4e0a\u5347\u901a\u5e38\u5728\u73b0\u6709\u8463\u4e8b\u79bb\u804c\u540e\u5f97\u5230\u62b5\u6d88\uff0c\u800c\u8463\u4e8b\u79bb\u804c\u901a\u5e38\u53d1\u751f\u5728\u4e00\u5e74\u4e4b\u5185\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026103251", "journal": "JFQA", "title": "Labor Exposure to Climate Risk, Productivity Loss, and Capital Deepening", "authors": ["Zhanbing Xiao"], "author_details": [{"name": "Zhanbing Xiao", "affiliations": ["City University of Hong Kong"]}], "abstract": "Abstract I find that exposed firms address heat challenges by shifting toward more capital-intensive production functions, increasing capital expenditures and R&D expenses, acquiring robotics-related human capital, and developing automation-related technologies. These effects are concentrated among firms facing large long-run temperature increases and among financially unconstrained firms. I further show that reduced labor efficiency relative to capital is one important mechanism underlying capital deepening and related automation investments. Finally, these capital responses mitigate heat-induced productivity losses, and investors appear to value firms\u2019 adaptation capacity.", "date": "2026-07-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103251", "title_zh": "\u52b3\u52a8\u529b\u5bf9\u6c14\u5019\u98ce\u9669\u7684\u66b4\u9732\u3001\u751f\u4ea7\u7387\u635f\u5931\u4e0e\u8d44\u672c\u6df1\u5316", "abstract_zh": "\u6211\u53d1\u73b0\uff0c\u9762\u4e34\u9ad8\u6e29\u6311\u6218\u7684\u4f01\u4e1a\u901a\u8fc7\u8f6c\u5411\u66f4\u8d44\u672c\u5bc6\u96c6\u7684\u751f\u4ea7\u51fd\u6570\u3001\u589e\u52a0\u8d44\u672c\u652f\u51fa\u548c\u7814\u53d1\u8d39\u7528\u3001\u83b7\u53d6\u4e0e\u673a\u5668\u4eba\u76f8\u5173\u7684\u52b3\u52a8\u529b\u8d44\u672c\uff0c\u4ee5\u53ca\u5f00\u53d1\u4e0e\u81ea\u52a8\u5316\u76f8\u5173\u7684\u6280\u672f\u6765\u5e94\u5bf9\u3002\u8fd9\u4e9b\u6548\u5e94\u4e3b\u8981\u96c6\u4e2d\u5728\u9762\u4e34\u957f\u671f\u6e29\u5ea6\u5927\u5e45\u4e0a\u5347\u4ee5\u53ca\u8d22\u52a1\u4e0a\u4e0d\u53d7\u7ea6\u675f\u7684\u4f01\u4e1a\u4e2d\u3002\u6211\u8fdb\u4e00\u6b65\u8868\u660e\uff0c\u76f8\u5bf9\u4e8e\u8d44\u672c\u800c\u8a00\u52b3\u52a8\u529b\u6548\u7387\u7684\u4e0b\u964d\u662f\u5bfc\u81f4\u8d44\u672c\u6df1\u5316\u53ca\u76f8\u5173\u81ea\u52a8\u5316\u6295\u8d44\u7684\u4e00\u4e2a\u91cd\u8981\u673a\u5236\u3002\u6700\u540e\uff0c\u8fd9\u4e9b\u8d44\u672c\u8c03\u6574\u63aa\u65bd\u7f13\u89e3\u4e86\u9ad8\u6e29\u5f15\u8d77\u7684\u751f\u4ea7\u7387\u635f\u5931\uff0c\u6295\u8d44\u8005\u4f3c\u4e4e\u4e5f\u91cd\u89c6\u4f01\u4e1a\u5e94\u5bf9\u6c14\u5019\u53d8\u5316\u7684\u80fd\u529b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag076", "journal": "REStud", "title": "The Selective Disclosure of Evidence: An Experiment", "authors": ["Agata Farina", "Guillaume R Fr\u00e9chette", "Alessandro Ispano", "Alessandro Lizzeri", "Jacopo Perego"], "author_details": [{"name": "Agata Farina", "affiliations": ["University of Chicago Booth School of Business, , USA"]}, {"name": "Guillaume R Fr\u00e9chette", "affiliations": ["New York University , USA"]}, {"name": "Alessandro Ispano", "affiliations": ["Universit\u00e9 Paris Dauphine PSL, CNRS, LEDa, and Institut Universitaire de France ,"]}, {"name": "Alessandro Lizzeri", "affiliations": ["Princeton University , USA"]}, {"name": "Jacopo Perego", "affiliations": ["Columbia University , USA"]}], "abstract": "Abstract We conduct an experimental analysis of selective disclosure in communication. In the model, an informed sender aims to influence a receiver by disclosing verifiable evidence that is selected from a larger pool of available evidence. Our experimental design leverages this model\u2019s rich comparative statics, allowing us to systematically quantify the effects of selection relative to concealment. Our findings confirm the key qualitative predictions of the theory, suggesting that selection, rather than concealment, is often the dominant distortion in communication. We also identify deviations from the theory: Some senders are \u201cdeception averse\u201d and overcommunicate relative to predictions; receivers respond too optimistically to both concealed and selected evidence, with errors of similar magnitude. Yet selection generates greater overall distortion in receiver behaviour because it is far more prevalent than concealment.", "date": "2026-07-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag076", "title_zh": "\u8bc1\u636e\u7684\u6709\u9009\u62e9\u62ab\u9732\uff1a\u4e00\u9879\u5b9e\u9a8c", "abstract_zh": "\u6211\u4eec\u5bf9\u6c9f\u901a\u4e2d\u7684\u6709\u9009\u62e9\u62ab\u9732\u8fdb\u884c\u4e86\u5b9e\u9a8c\u5206\u6790\u3002\u5728\u6a21\u578b\u4e2d\uff0c\u4e00\u4e2a\u4fe1\u606f\u5145\u5206\u7684\u53d1\u9001\u65b9\u65e8\u5728\u901a\u8fc7\u4ece\u5927\u91cf\u53ef\u7528\u8bc1\u636e\u4e2d\u9009\u62e9\u53ef\u9a8c\u8bc1\u7684\u8bc1\u636e\u6765\u5f71\u54cd\u63a5\u6536\u65b9\u3002\u6211\u4eec\u7684\u5b9e\u9a8c\u8bbe\u8ba1\u5229\u7528\u4e86\u8be5\u6a21\u578b\u7684\u4e30\u5bcc\u6bd4\u8f83\u9759\u6001\u5206\u6790\uff0c\u80fd\u591f\u7cfb\u7edf\u5730\u91cf\u5316\u9009\u62e9\u62ab\u9732\u76f8\u5bf9\u4e8e\u9690\u7792\u7684\u5f71\u54cd\u3002\u6211\u4eec\u7684\u53d1\u73b0\u9a8c\u8bc1\u4e86\u7406\u8bba\u4e2d\u7684\u5173\u952e\u5b9a\u6027\u9884\u6d4b\uff0c\u8868\u660e\u9009\u62e9\u62ab\u9732\u800c\u975e\u9690\u7792\u5f80\u5f80\u662f\u6c9f\u901a\u4e2d\u7684\u4e3b\u8981\u626d\u66f2\u56e0\u7d20\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\u4e86\u5bf9\u7406\u8bba\u7684\u504f\u79bb\uff1a\u4e00\u4e9b\u53d1\u9001\u65b9\u8868\u73b0\u51fa\u201c\u6b3a\u9a97\u538c\u6076\u201d\u503e\u5411\uff0c\u5176\u62ab\u9732\u91cf\u8d85\u8fc7\u7406\u8bba\u9884\u6d4b\uff1b\u63a5\u6536\u65b9\u5bf9\u88ab\u9690\u7792\u548c\u88ab\u9009\u62e9\u7684\u8bc1\u636e\u90fd\u53cd\u5e94\u8fc7\u4e8e\u4e50\u89c2\uff0c\u4e14\u8bef\u5dee\u5e45\u5ea6\u76f8\u4f3c\u3002\u7136\u800c\uff0c\u7531\u4e8e\u9009\u62e9\u62ab\u9732\u8fdc\u6bd4\u9690\u7792\u66f4\u4e3a\u666e\u904d\uff0c\u5b83\u5728\u63a5\u6536\u65b9\u884c\u4e3a\u4e0a\u7684\u603b\u4f53\u626d\u66f2\u6548\u5e94\u66f4\u5927\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026103214", "journal": "JFQA", "title": "Misconduct and Market Implications of Honest Advisers\u2019 Decisions", "authors": ["Michael Gelman", "Amir Shoham"], "author_details": [{"name": "Michael Gelman", "affiliations": ["University of Delaware Finance"]}, {"name": "Amir Shoham", "affiliations": ["Temple University Finance"]}], "abstract": "Abstract Most financial advisers have no history of misconduct, yet little is known about how honest advisers respond to misconduct at their firms. In this article, we show that honest advisers are more likely to leave firms experiencing elevated misconduct and transition to firms with lower tolerance for misconduct. We demonstrate that in an industry where reputation and trust are central, affiliation with a firm experiencing higher misconduct generates reputational spillovers. These individual decisions of honest advisers aggregate to the market level, contributing to the sorting of honest (dishonest) advisers into firms that are less (more) tolerant of misconduct.", "date": "2026-07-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103214", "title_zh": "\u8bda\u5b9e\u987e\u95ee\u51b3\u7b56\u4e2d\u7684\u4e0d\u5f53\u884c\u4e3a\u53ca\u5176\u5e02\u573a\u5f71\u54cd", "abstract_zh": "\u5927\u591a\u6570\u91d1\u878d\u987e\u95ee\u90fd\u6ca1\u6709\u8fc7\u4e0d\u5f53\u884c\u4e3a\u8bb0\u5f55\uff0c\u4f46\u5173\u4e8e\u8bda\u5b9e\u987e\u95ee\u5982\u4f55\u5e94\u5bf9\u6240\u5728\u673a\u6784\u7684\u4e0d\u5f53\u884c\u4e3a\uff0c\u76ee\u524d\u4e86\u89e3\u751a\u5c11\u3002\u672c\u6587\u8868\u660e\uff0c\u8bda\u5b9e\u987e\u95ee\u66f4\u53ef\u80fd\u79bb\u5f00\u5b58\u5728\u9ad8\u7a0b\u5ea6\u4e0d\u5f53\u884c\u4e3a\u7684\u673a\u6784\uff0c\u5e76\u8f6c\u5165\u5bf9\u4e0d\u5f53\u884c\u4e3a\u5bb9\u5fcd\u5ea6\u8f83\u4f4e\u7684\u673a\u6784\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5728\u4e00\u4e2a\u58f0\u8a89\u548c\u4fe1\u4efb\u81f3\u5173\u91cd\u8981\u884c\u4e1a\u4e2d\uff0c\u4e0e\u5b58\u5728\u8f83\u9ad8\u4e0d\u5f53\u884c\u4e3a\u7684\u673a\u6784\u5173\u8054\u4f1a\u4ea7\u751f\u58f0\u8a89\u5916\u6ea2\u6548\u5e94\u3002\u8fd9\u4e9b\u8bda\u5b9e\u987e\u95ee\u7684\u4e2a\u4f53\u51b3\u7b56\u5728\u5e02\u573a\u5c42\u9762\u6c47\u805a\uff0c\u5bfc\u81f4\u8bda\u5b9e\uff08\u4e0d\u8bda\u5b9e\uff09\u987e\u95ee\u88ab\u5206\u6d41\u5165\u5bf9\u4e0d\u5f53\u884c\u4e3a\u5bb9\u5fcd\u5ea6\u8f83\u4f4e\uff08\u8f83\u9ad8\uff09\u7684\u673a\u6784\u4e2d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag074", "journal": "REStud", "title": "A Model of the Data Economy", "authors": ["Maryam Farboodi", "Laura Veldkamp"], "author_details": [{"name": "Maryam Farboodi", "affiliations": ["MIT Sloan School of Management, NBER, and CEPR , 100 Main Street, Cambridge, MA 02142 ,"]}, {"name": "Laura Veldkamp", "affiliations": ["Columbia Graduate School of Business, NBER, and CEPR , 665 West 130th Street, New York, NY 10027, USA"]}], "abstract": "Abstract In a data economy, transactions of goods and services generate data, which is stored, traded and depreciates. How are the economics of this economy different from traditional production economies? How do these differences matter for measurement of GDP, firm values, depreciation rates, welfare and externalities? We incorporate active experimentation and data as an intangible asset to devise a tractable recursive representation of the data economy. The model rationalizes why apps are often \u201cfree\u201d and why even non-digital economic activity might be greater than GDP suggests. Calibrating the model using a combination of macroeconomic and financial moments suggests that the mis-measurement in U.S. GDP due to missing value of data has been as high as 6% in 2018.", "date": "2026-07-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag074", "title_zh": "\u6570\u636e\u7ecf\u6d4e\u6a21\u578b", "abstract_zh": "\u6458\u8981 \u5728\u6570\u636e\u7ecf\u6d4e\u4e2d\uff0c\u5546\u54c1\u548c\u670d\u52a1\u7684\u4ea4\u6613\u4f1a\u4ea7\u751f\u6570\u636e\uff0c\u8fd9\u4e9b\u6570\u636e\u88ab\u5b58\u50a8\u3001\u4ea4\u6613\u5e76\u53d1\u751f\u8d2c\u503c\u3002\u4e0e\u4f20\u7edf\u751f\u4ea7\u7ecf\u6d4e\u76f8\u6bd4\uff0c\u6570\u636e\u7ecf\u6d4e\u7684\u7ecf\u6d4e\u7279\u5f81\u6709\u4f55\u4e0d\u540c\uff1f\u8fd9\u4e9b\u5dee\u5f02\u5bf9GDP\u6d4b\u91cf\u3001\u4f01\u4e1a\u4ef7\u503c\u3001\u6298\u65e7\u7387\u3001\u798f\u5229\u548c\u5916\u90e8\u6027\u6709\u4f55\u5f71\u54cd\uff1f\u6211\u4eec\u901a\u8fc7\u5f15\u5165\u4e3b\u52a8\u5b9e\u9a8c\u548c\u6570\u636e\u4f5c\u4e3a\u65e0\u5f62\u8d44\u4ea7\uff0c\u6784\u5efa\u4e86\u4e00\u4e2a\u53ef\u5904\u7406\u7684\u9012\u5f52\u8868\u793a\u6a21\u578b\u6765\u63cf\u8ff0\u6570\u636e\u7ecf\u6d4e\u3002\u8be5\u6a21\u578b\u89e3\u91ca\u4e86\u4e3a\u4f55\u5e94\u7528\u7a0b\u5e8f\u901a\u5e38\u201c\u514d\u8d39\u201d\uff0c\u4ee5\u53ca\u4e3a\u4f55\u975e\u6570\u5b57\u5316\u7ecf\u6d4e\u6d3b\u52a8\u53ef\u80fd\u8d85\u8fc7GDP\u6240\u53cd\u6620\u7684\u6c34\u5e73\u3002\u5229\u7528\u5b8f\u89c2\u7ecf\u6d4e\u548c\u91d1\u878d\u77e9\u7684\u7ec4\u5408\u6821\u51c6\u6a21\u578b\u8868\u660e\uff0c\u7531\u4e8e\u6570\u636e\u4ef7\u503c\u7f3a\u5931\uff0c2018\u5e74\u7f8e\u56fdGDP\u7684\u6d4b\u91cf\u8bef\u5dee\u9ad8\u8fbe6%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag075", "journal": "REStud", "title": "Structural Change in Production Networks and Economic Growth", "authors": ["Paul Gaggl", "Aspen Gorry", "Christian vom Lehn"], "author_details": [{"name": "Paul Gaggl", "affiliations": ["Department of Economics, Belk College of Business, University of North Carolina at Charlotte ,"]}, {"name": "Aspen Gorry", "affiliations": ["John E. Walker Department of Economics, Wilbur O. and Ann Powers College of Business, Clemson University ,"]}, {"name": "Christian vom Lehn", "affiliations": ["Department of Economics, Brigham Young University ,"]}], "abstract": "Abstract We study structural change in production networks for intermediate inputs (input\u2013output network) and new capital (investment network). For each network, we document that the share of output produced by services (relative to goods) is rising over time. While the relative prices of services that produce intermediates and consumption are rising, we find that the relative price of services that produce investment is falling over time. We then develop a multi-sector growth model to study these trends and their implications for economic growth. To match the relative price trends, inputs to intermediates production are complements and inputs to investment production are substitutes. Hence, structural change endogenously reallocates resources to the slowest growing intermediates producers and the fastest growing investment producers. Growth accounting exercises reveal that investment-specific technical change accounts for an increasing share of U.S. aggregate growth, with 20% of aggregate growth since 2000 due to investment structural change. Growth projections from our model show that structural change within investment networks alone can offset stagnating or declining growth in other sectors due to Baumol\u2019s cost disease.", "date": "2026-07-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag075", "title_zh": "\u751f\u4ea7\u7f51\u7edc\u4e2d\u7684\u7ed3\u6784\u53d8\u5316\u4e0e\u7ecf\u6d4e\u589e\u957f", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e2d\u95f4\u6295\u5165\u54c1\uff08\u6295\u5165-\u4ea7\u51fa\u7f51\u7edc\uff09\u548c\u65b0\u8d44\u672c\uff08\u6295\u8d44\u7f51\u7edc\uff09\u751f\u4ea7\u7f51\u7edc\u4e2d\u7684\u7ed3\u6784\u53d8\u5316\u3002\u5bf9\u4e8e\u6bcf\u4e2a\u7f51\u7edc\uff0c\u6211\u4eec\u53d1\u73b0\u670d\u52a1\u90e8\u95e8\u4ea7\u51fa\u5360\u6bd4\uff08\u76f8\u5bf9\u4e8e\u5546\u54c1\u90e8\u95e8\uff09\u968f\u65f6\u95f4\u63a8\u79fb\u800c\u4e0a\u5347\u3002\u5c3d\u7ba1\u751f\u4ea7\u4e2d\u95f4\u54c1\u548c\u670d\u52a1\u6d88\u8d39\u7684\u670d\u52a1\u76f8\u5bf9\u4ef7\u683c\u5728\u4e0a\u5347\uff0c\u4f46\u6211\u4eec\u53d1\u73b0\u751f\u4ea7\u6295\u8d44\u7684\u670d\u52a1\u76f8\u5bf9\u4ef7\u683c\u6b63\u5728\u4e0b\u964d\u3002\u968f\u540e\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u591a\u90e8\u95e8\u589e\u957f\u6a21\u578b\u6765\u7814\u7a76\u8fd9\u4e9b\u8d8b\u52bf\u53ca\u5176\u5bf9\u7ecf\u6d4e\u589e\u957f\u7684\u5f71\u54cd\u3002\u4e3a\u5339\u914d\u76f8\u5bf9\u4ef7\u683c\u8d8b\u52bf\uff0c\u751f\u4ea7\u4e2d\u95f4\u54c1\u7684\u6295\u5165\u662f\u4e92\u8865\u7684\uff0c\u800c\u751f\u4ea7\u6295\u8d44\u7684\u6295\u5165\u662f\u66ff\u4ee3\u7684\u3002\u56e0\u6b64\uff0c\u7ed3\u6784\u53d8\u5316\u5185\u751f\u5730\u5c06\u8d44\u6e90\u91cd\u65b0\u914d\u7f6e\u5230\u589e\u957f\u6700\u7f13\u6162\u7684\u4e2d\u95f4\u54c1\u751f\u4ea7\u8005\u548c\u589e\u957f\u6700\u5feb\u7684\u6295\u8d44\u8005\u751f\u4ea7\u8005\u3002\u589e\u957f\u6838\u7b97\u8868\u660e\uff0c\u6295\u8d44\u7279\u5b9a\u7684\u6280\u672f\u8fdb\u6b65\u5728\u7f8e\u56fd\u5bb6\u5ead\u603b\u589e\u957f\u4e2d\u7684\u5360\u6bd4\u4e0d\u65ad\u4e0a\u5347\uff0c\u81ea2000\u5e74\u4ee5\u6765\uff0c\u670920%\u7684\u603b\u589e\u957f\u5f52\u56e0\u4e8e\u6295\u8d44\u7ed3\u6784\u53d8\u5316\u3002\u6839\u636e\u6211\u4eec\u6a21\u578b\u7684\u9884\u6d4b\uff0c\u6295\u8d44\u7f51\u7edc\u5185\u90e8\u7684\u7ed3\u6784\u53d8\u5316\u8db3\u4ee5\u62b5\u6d88\u5176\u4ed6\u90e8\u95e8\u56e0\u9c8d\u83ab\u5c14\u6210\u672c\u75be\u75c5\u5bfc\u81f4\u7684\u505c\u6ede\u6216\u4e0b\u964d\u7684\u7ecf\u6d4e\u589e\u957f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/rfs/hhag063", "journal": "RFS", "title": "Corporate Green Pledges", "authors": ["Michael Bauer", "Daniel Huber", "Eric Offner", "Ole Wilms"], "author_details": [{"name": "Michael Bauer", "affiliations": ["Federal Reserve Bank of San Francisco , ; CEPR"]}, {"name": "Daniel Huber", "affiliations": ["Arval BNP Paribas ,"]}, {"name": "Eric Offner", "affiliations": ["Frankfurt School of Finance and Management ,"]}, {"name": "Ole Wilms", "affiliations": ["University of Hamburg and Tilburg University , and"]}], "abstract": "Abstract We build a novel data set of time-stamped corporate decarbonization commitments\u2014green pledges\u2014for U.S. public firms by classifying news articles with large language models and human validation. Firms announcing green pledges tend to be larger and browner than other firms, both within and across industries. Green pledges significantly raise stock prices, consistent with a reduction in the carbon premium, and predict sizable declines in future carbon emissions and emission intensities. These effects tend to be strongest for firms in brown industries. Green pledges thus appear credible, convey relevant new information to investors, and provide meaningful financial incentives to decarbonize.", "date": "2026-07-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag063", "title_zh": "\u4f01\u4e1a\u7eff\u8272\u627f\u8bfa", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u65f6\u95f4\u6233\u7684\u7f8e\u56fd\u4e0a\u5e02\u516c\u53f8\u53bb\u78b3\u5316\u627f\u8bfa\u2014\u2014\u7eff\u8272\u627f\u8bfa\u2014\u2014\u7684\u65b0\u578b\u6570\u636e\u96c6\uff0c\u901a\u8fc7\u5927\u578b\u8bed\u8a00\u6a21\u578b\u5bf9\u65b0\u95fb\u6587\u7ae0\u8fdb\u884c\u5206\u7c7b\u5e76\u7ed3\u5408\u4eba\u5de5\u9a8c\u8bc1\u5b9e\u73b0\u3002\u5ba3\u5e03\u7eff\u8272\u627f\u8bfa\u7684\u4f01\u4e1a\u5f80\u5f80\u6bd4\u5176\u4ed6\u4f01\u4e1a\u89c4\u6a21\u66f4\u5927\u3001\u78b3\u6392\u653e\u66f4\u9ad8\uff0c\u65e0\u8bba\u662f\u540c\u4e00\u884c\u4e1a\u5185\u8fd8\u662f\u8de8\u884c\u4e1a\u3002\u7eff\u8272\u627f\u8bfa\u663e\u8457\u63d0\u5347\u4e86\u80a1\u4ef7\uff0c\u8fd9\u4e0e\u78b3\u6ea2\u4ef7\u7684\u964d\u4f4e\u4e00\u81f4\uff0c\u5e76\u80fd\u9884\u6d4b\u672a\u6765\u78b3\u6392\u653e\u548c\u6392\u653e\u5f3a\u5ea6\u7684\u5927\u5e45\u4e0b\u964d\u3002\u8fd9\u4e9b\u6548\u5e94\u5728\u68d5\u8272\u884c\u4e1a\u7684\u4f01\u4e1a\u4e2d\u5c24\u4e3a\u660e\u663e\u3002\u56e0\u6b64\uff0c\u7eff\u8272\u627f\u8bfa\u4f3c\u4e4e\u5177\u6709\u53ef\u4fe1\u5ea6\uff0c\u5411\u6295\u8d44\u8005\u4f20\u9012\u4e86\u76f8\u5173\u7684\u65b0\u4fe1\u606f\uff0c\u5e76\u4e3a\u4f01\u4e1a\u53bb\u78b3\u5316\u63d0\u4f9b\u4e86\u5b9e\u8d28\u6027\u7684\u8d22\u52a1\u6fc0\u52b1\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790", "AI"]}, {"doi": "10.1017/s0022109026103135", "journal": "JFQA", "title": "The Effects of Open Banking on FinTech Firms\u2019 Dynamics and Funding Structure", "authors": ["Andr\u00e9s Alonso-Robisco", "Jos\u00e9 Manuel Carb\u00f3", "Pedro Jes\u00fas Cuadros-Solas", "Jara Quintanero"], "author_details": [{"name": "Andr\u00e9s Alonso-Robisco", "affiliations": ["Banco de Espa\u00f1a"]}, {"name": "Jos\u00e9 Manuel Carb\u00f3", "affiliations": ["Banco de Espa\u00f1a"]}, {"name": "Pedro Jes\u00fas Cuadros-Solas", "affiliations": ["CUNEF Universidad and Funcas"]}, {"name": "Jara Quintanero", "affiliations": ["Banco de Espa\u00f1a"]}], "abstract": "Abstract This article investigates the impact of open banking on the dynamics of fintech firms. Using a unique data set of Spanish fintech firms from 2014 to 2022, we exploit differential exposure to Europe\u2019s open banking regulation between payment-focused fintech firms and other fintech firms. Following the regulation, payment-service fintechs exhibit improved performance and a restructuring of their funding, characterized by reduced reliance on long-term bank debt and increased use of market-based equity. These firms also increase liquidity, reduce labor intensity, raise labor costs, and enhance productivity. These findings provide novel firm-level evidence on the effects of data-sharing regulation in financial markets.", "date": "2026-07-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103135", "title_zh": "\u5f00\u653e\u94f6\u884c\u5bf9\u91d1\u878d\u79d1\u6280\u4f01\u4e1a\u52a8\u6001\u53ca\u878d\u8d44\u7ed3\u6784\u7684\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5f00\u653e\u94f6\u884c\u5bf9\u91d1\u878d\u79d1\u6280\u4f01\u4e1a\u52a8\u6001\u7684\u5f71\u54cd\u3002\u57fa\u4e8e2014\u5e74\u81f32022\u5e74\u897f\u73ed\u7259\u91d1\u878d\u79d1\u6280\u4f01\u4e1a\u7684\u72ec\u7279\u6570\u636e\u96c6\uff0c\u6211\u4eec\u5229\u7528\u652f\u4ed8\u5bfc\u5411\u578b\u91d1\u878d\u79d1\u6280\u4f01\u4e1a\u4e0e\u5176\u4ed6\u91d1\u878d\u79d1\u6280\u4f01\u4e1a\u4e4b\u95f4\u5728\u6b27\u6d32\u5f00\u653e\u94f6\u884c\u76d1\u7ba1\u4e2d\u66b4\u9732\u5dee\u5f02\u7684\u7279\u5f81\u3002\u5728\u76d1\u7ba1\u5b9e\u65bd\u540e\uff0c\u652f\u4ed8\u670d\u52a1\u578b\u91d1\u878d\u79d1\u6280\u4f01\u4e1a\u8868\u73b0\u51fa\u66f4\u597d\u7684\u7ee9\u6548\uff0c\u5e76\u5bf9\u5176\u878d\u8d44\u7ed3\u6784\u8fdb\u884c\u4e86\u8c03\u6574\uff0c\u8868\u73b0\u4e3a\u5bf9\u957f\u671f\u94f6\u884c\u503a\u52a1\u7684\u4f9d\u8d56\u51cf\u5c11\uff0c\u5e02\u573a\u57fa\u4e8e\u80a1\u6743\u7684\u4f7f\u7528\u589e\u52a0\u3002\u8fd9\u4e9b\u4f01\u4e1a\u8fd8\u63d0\u9ad8\u4e86\u6d41\u52a8\u6027\uff0c\u964d\u4f4e\u4e86\u52b3\u52a8\u5f3a\u5ea6\uff0c\u63d0\u9ad8\u4e86\u52b3\u52a8\u529b\u6210\u672c\uff0c\u5e76\u63d0\u5347\u4e86\u751f\u4ea7\u7387\u3002\u8fd9\u4e9b\u53d1\u73b0\u4e3a\u91d1\u878d\u5e02\u573a\u7684\u6570\u636e\u5171\u4eab\u76d1\u7ba1\u5bf9\u4f01\u4e1a\u5c42\u9762\u7684\u5f71\u54cd\u63d0\u4f9b\u4e86\u65b0\u7684\u8bc1\u636e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag033", "journal": "QJE", "title": "In Their Shoes: Empathy Through Information", "authors": ["Marianne Andries", "Leonardo Bursztyn", "Thomas Chaney", "Milena Djourelova", "Alex Imas"], "author_details": [{"name": "Marianne Andries", "affiliations": ["University of Southern California, United States; and Centre for Economic Policy and Research ,", "University of Chicago and National Bureau of Economic Research ,", "University of Southern California and National Bureau of Economic Research, United States; and Centre for Economic Policy and Research ,", "University of Southern California, United States; and CESifo ,", "University of Chicago Booth School of Business and National Bureau of Economic Research ,"]}, {"name": "Leonardo Bursztyn", "affiliations": ["University of Southern California, United States; and Centre for Economic Policy and Research ,", "University of Chicago and National Bureau of Economic Research ,", "University of Southern California and National Bureau of Economic Research, United States; and Centre for Economic Policy and Research ,", "University of Southern California, United States; and CESifo ,", "University of Chicago Booth School of Business and National Bureau of Economic Research ,"]}, {"name": "Thomas Chaney", "affiliations": ["University of Southern California, United States; and Centre for Economic Policy and Research ,", "University of Chicago and National Bureau of Economic Research ,", "University of Southern California and National Bureau of Economic Research, United States; and Centre for Economic Policy and Research ,", "University of Southern California, United States; and CESifo ,", "University of Chicago Booth School of Business and National Bureau of Economic Research ,"]}, {"name": "Milena Djourelova", "affiliations": ["University of Southern California, United States; and Centre for Economic Policy and Research ,", "University of Chicago and National Bureau of Economic Research ,", "University of Southern California and National Bureau of Economic Research, United States; and Centre for Economic Policy and Research ,", "University of Southern California, United States; and CESifo ,", "University of Chicago Booth School of Business and National Bureau of Economic Research ,"]}, {"name": "Alex Imas", "affiliations": ["University of Southern California, United States; and Centre for Economic Policy and Research ,", "University of Chicago and National Bureau of Economic Research ,", "University of Southern California and National Bureau of Economic Research, United States; and Centre for Economic Policy and Research ,", "University of Southern California, United States; and CESifo ,", "University of Chicago Booth School of Business and National Bureau of Economic Research ,"]}], "abstract": "Abstract We explore the mechanics of empathy. We show that information about an outgroup can activate and magnify empathy when presented in conjunction with an experience simulating their struggles. This response increases the willingness to help the struggling group. We provide evidence for this effect in an immersive virtual reality experiment where participants (witnesses) experience a simulation of the struggle of unauthorized migrants (protagonists), then replicate these results in a series of controlled lab experiments. We show that information enhances the witnesses\u2019 empathetic response and drives them to engage in more prosocial behavior when it increases their perceived interpersonal similarity, or relatability to the protagonist\u2014an effect we trace to attention: eye-tracking data reveal that information provision concentrates witnesses\u2019 gaze on the struggles of the protagonist instead of searching through peripheral elements of the scene. Conversely, only information packages that strengthen perceived relatability\u2014an effect that can vary across subgroups with heterogeneous attributes\u2014magnify empathy. Together, our evidence suggests that the ability to put oneself in the shoes of another person or group can be enhanced by activating empathy through simple, targeted, information provision.", "date": "2026-07-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag033", "title_zh": "\u6362\u4f4d\u601d\u8003\uff1a\u901a\u8fc7\u4fe1\u606f\u5b9e\u73b0\u5171\u60c5", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u63a2\u8ba8\u4e86\u5171\u60c5\u7684\u673a\u5236\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5f53\u5173\u4e8e\u5916\u90e8\u7fa4\u4f53\u7684\u4fe1\u606f\u4e0e\u6a21\u62df\u5176\u56f0\u5883\u7684\u4f53\u9a8c\u76f8\u7ed3\u5408\u65f6\uff0c\u80fd\u591f\u6fc0\u6d3b\u5e76\u653e\u5927\u5171\u60c5\u53cd\u5e94\uff0c\u4ece\u800c\u63d0\u5347\u5bf9\u56f0\u5883\u7fa4\u4f53\u7684\u63f4\u52a9\u610f\u613f\u3002\u6211\u4eec\u5728\u6c89\u6d78\u5f0f\u865a\u62df\u73b0\u5b9e\u5b9e\u9a8c\u4e2d\u53d1\u73b0\uff0c\u53c2\u4e0e\u8005\uff08\u89c1\u8bc1\u8005\uff09\u4f53\u9a8c\u4e86\u672a\u7ecf\u6388\u6743\u79fb\u6c11\uff08\u4e3b\u89d2\uff09\u7684\u56f0\u5883\u6a21\u62df\u540e\uff0c\u968f\u540e\u5728\u4e00\u7cfb\u5217\u53d7\u63a7\u7684\u5b9e\u9a8c\u5ba4\u5b9e\u9a8c\u4e2d\u590d\u73b0\u4e86\u8fd9\u4e00\u7ed3\u679c\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u4fe1\u606f\u80fd\u591f\u589e\u5f3a\u89c1\u8bc1\u8005\u7684\u5171\u60c5\u53cd\u5e94\uff0c\u5e76\u5728\u63d0\u5347\u5176\u5bf9\u4e3b\u89d2\u7684\u611f\u77e5\u4eba\u9645\u76f8\u4f3c\u6027\u6216\u53ef\u4eb2\u8fd1\u6027\u65f6\uff0c\u4fc3\u4f7f\u4ed6\u4eec\u8868\u73b0\u51fa\u66f4\u591a\u7684\u5229\u4ed6\u884c\u4e3a\u2014\u2014\u8fd9\u4e00\u6548\u5e94\u53ef\u8ffd\u6eaf\u81f3\u6ce8\u610f\u529b\uff1a\u773c\u52a8\u6570\u636e\u8868\u660e\uff0c\u4fe1\u606f\u63d0\u4f9b\u4f1a\u4f7f\u89c1\u8bc1\u8005\u7684\u89c6\u7ebf\u96c6\u4e2d\u4e8e\u4e3b\u89d2\u7684\u56f0\u5883\uff0c\u800c\u975e\u5206\u6563\u5728\u573a\u666f\u7684\u5916\u56f4\u5143\u7d20\u4e0a\u3002\u76f8\u53cd\uff0c\u53ea\u6709\u90a3\u4e9b\u589e\u5f3a\u611f\u77e5\u53ef\u4eb2\u8fd1\u6027\u7684\u4fe1\u606f\u5305\u624d\u80fd\u653e\u5927\u5171\u60c5\u6548\u5e94\uff0c\u800c\u8fd9\u79cd\u6548\u5e94\u53ef\u80fd\u56e0\u5177\u6709\u5f02\u8d28\u5c5e\u6027\u7684\u5b50\u7fa4\u4f53\u800c\u6709\u6240\u4e0d\u540c\u3002\u7efc\u5408\u6211\u4eec\u7684\u8bc1\u636e\u8868\u660e\uff0c\u901a\u8fc7\u7b80\u5355\u3001\u6709\u9488\u5bf9\u6027\u7684\u4fe1\u606f\u63d0\u4f9b\uff0c\u53ef\u4ee5\u589e\u5f3a\u4eba\u4eec\u201c\u8bbe\u8eab\u5904\u5730\u201d\u7406\u89e3\u4ed6\u4eba\u6216\u7fa4\u4f53\u7684\u80fd\u529b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag071", "journal": "REStud", "title": "How Do People React to Income-Based Fines? Evidence from Speeding Tickets Discontinuities", "authors": ["Martti Kaila"], "author_details": [{"name": "Martti Kaila", "affiliations": ["University of Glasgow ,"]}], "abstract": "Abstract This article studies the impact of income-based criminal punishments on crime. In Finland, speeding tickets become income-dependent if the driver\u2019s speed exceeds the speeding limit by more than 20 km/h, leading to a substantial jump in the size of the speeding ticket. Contrary to predictions of a traditional Becker model, individuals do not bunch below the fine hike. Instead, the speeding distributions are smooth at the cutoff. However, I demonstrate that the size of the realized speeding ticket has sizable, but short-lived, impacts on reoffending. I use a regression discontinuity design to show that fines that are, on average, 200 euros larger decrease reoffending by 15% in the following 6 months. The drop in reoffending is driven by high-income individuals facing the highest fine at the cutoff. I estimate that a fixed fine hike that matches the current deterrence effect would raise the fine increase faced by the bottom income quartile by about 300% at the cutoff, relative to the increase they face under the current income-based schedule. My empirical results are consistent with an explanation that people operate under information frictions. To illustrate this, I construct a Becker model with misperception and learning that can explain all the empirical findings.", "date": "2026-07-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag071", "title_zh": "\u4eba\u4eec\u5982\u4f55\u5e94\u5bf9\u57fa\u4e8e\u6536\u5165\u7684\u7f5a\u6b3e\uff1f\u6765\u81ea\u8d85\u901f\u7f5a\u5355\u65ad\u70b9\u7684\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u57fa\u4e8e\u6536\u5165\u7684\u5211\u4e8b\u60e9\u7f5a\u5bf9\u72af\u7f6a\u884c\u4e3a\u7684\u5f71\u54cd\u3002\u5728\u82ac\u5170\uff0c\u5f53\u9a7e\u9a76\u8005\u7684\u8f66\u901f\u8d85\u8fc7\u9650\u901f20\u516c\u91cc/\u5c0f\u65f6\u4ee5\u4e0a\u65f6\uff0c\u8d85\u901f\u7f5a\u5355\u4f1a\u53d8\u4e3a\u4e0e\u6536\u5165\u76f8\u5173\uff0c\u5bfc\u81f4\u7f5a\u5355\u91d1\u989d\u51fa\u73b0\u663e\u8457\u8df3\u8dc3\u3002\u4e0e\u4f20\u7edf\u8d1d\u514b\u5c14\u6a21\u578b\u7684\u9884\u6d4b\u76f8\u53cd\uff0c\u4e2a\u4f53\u5e76\u672a\u5728\u7f5a\u6b3e\u589e\u52a0\u70b9\u4e0b\u65b9\u805a\u96c6\uff0c\u800c\u662f\u8d85\u901f\u5206\u5e03\u5448\u73b0\u51fa\u5e73\u6ed1\u72b6\u6001\u3002\u7136\u800c\uff0c\u6211\u8bc1\u660e\u4e86\u5b9e\u9645\u6536\u5230\u7684\u8d85\u901f\u7f5a\u5355\u91d1\u989d\u5bf9\u518d\u6b21\u8fdd\u89c4\u5177\u6709\u663e\u8457\u4f46\u77ed\u6682\u7684\u5f71\u54cd\u3002\u6211\u91c7\u7528\u56de\u5f52\u65ad\u70b9\u8bbe\u8ba1\u53d1\u73b0\uff0c\u5e73\u5747\u800c\u8a00\u6bd4\u539f\u7f5a\u5355\u9ad8\u51fa200\u6b27\u5143\u7684\u7f5a\u6b3e\uff0c\u5728\u63a5\u4e0b\u67656\u4e2a\u6708\u5185\u53ef\u4f7f\u518d\u8fdd\u89c4\u7387\u4e0b\u964d15%\u3002\u8fd9\u4e00\u518d\u8fdd\u89c4\u7387\u7684\u4e0b\u964d\u4e3b\u8981\u7531\u9762\u4e34\u6700\u9ad8\u7f5a\u6b3e\u7684\u9ad8\u6536\u5165\u4e2a\u4f53\u9a71\u52a8\u3002\u6211\u4f30\u8ba1\uff0c\u82e5\u5c06\u5f53\u524d\u5a01\u6151\u6548\u679c\u7684\u56fa\u5b9a\u7f5a\u6b3e\u63d0\u5347\u5e45\u5ea6\u5e94\u7528\u4e8e\u73b0\u884c\u57fa\u4e8e\u6536\u5165\u7684\u7f5a\u5355\u5236\u5ea6\uff0c\u5e95\u7aef\u6536\u5165\u56db\u5206\u4f4d\u7fa4\u4f53\u5728\u65ad\u70b9\u5904\u9762\u4e34\u7684\u7f5a\u6b3e\u589e\u5e45\u5c06\u6bd4\u73b0\u884c\u5236\u5ea6\u4e0b\u9ad8\u51fa\u7ea6300%\u3002\u6211\u7684\u5b9e\u8bc1\u7ed3\u679c\u4e0e\u4eba\u4eec\u5728\u4fe1\u606f\u6469\u64e6\u4e0b\u51b3\u7b56\u7684\u89e3\u91ca\u4e00\u81f4\u3002\u4e3a\u4e86\u8bf4\u660e\u8fd9\u4e00\u70b9\uff0c\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u8bef\u5224\u548c\u5b66\u4e60\u673a\u5236\u7684\u8d1d\u514b\u5c14\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u80fd\u591f\u89e3\u91ca\u6240\u6709\u5b9e\u8bc1\u53d1\u73b0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag023", "journal": "RFS", "title": "All Clear for Takeoff: Evidence from Airports on the Effects of Infrastructure Privatization", "authors": ["Sabrina T Howell", "Yeejin Jang", "Hyeik Kim", "Michael S Weisbach"], "author_details": [{"name": "Sabrina T Howell", "affiliations": ["Harvard Business School & NBER ,"]}, {"name": "Yeejin Jang", "affiliations": ["University of New South Wales ,"]}, {"name": "Hyeik Kim", "affiliations": ["University of California , Riverside,"]}, {"name": "Michael S Weisbach", "affiliations": ["Ohio State University, NBER, & ECGI ,"]}], "abstract": "Abstract We study privatization and corporate ownership in transportation infrastructure, focusing on global airports. Privatization in general does not improve performance. However, private equity (PE) ownership has strong and persistent positive effects on efficiency, volume, and quality, with positive externalities for the local economy. We address selection using close auctions where PE and non-PE firms bid. PE funds expand physical capacity and encourage larger planes while adding low-cost carriers and international routes. They are especially effective in countries with more corruption or state-owned flag carriers. In contrast, the poorer performance of non-PE acquirers may reflect private benefits and historical state ties.", "date": "2026-07-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag023", "title_zh": "\u4e00\u5207\u5c31\u7eea\uff0c\u8d77\u98de\uff1a\u6765\u81ea\u673a\u573a\u7684\u57fa\u7840\u8bbe\u65bd\u79c1\u6709\u5316\u6548\u5e94\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u8fd0\u8f93\u57fa\u7840\u8bbe\u65bd\u4e2d\u7684\u79c1\u6709\u5316\u548c\u4f01\u4e1a\u6240\u6709\u6743\uff0c\u91cd\u70b9\u805a\u7126\u4e8e\u5168\u7403\u673a\u573a\u3002\u603b\u4f53\u800c\u8a00\uff0c\u79c1\u6709\u5316\u5e76\u672a\u63d0\u5347\u7ee9\u6548\u3002\u7136\u800c\uff0c\u79c1\u52df\u80a1\u6743\uff08PE\uff09\u6240\u6709\u6743\u5bf9\u6548\u7387\u3001\u8fd0\u91cf\u548c\u8d28\u91cf\u5177\u6709\u663e\u8457\u4e14\u6301\u4e45\u7684\u6b63\u5411\u5f71\u54cd\uff0c\u5e76\u5bf9\u5f53\u5730\u7ecf\u6d4e\u4ea7\u751f\u6b63\u5916\u90e8\u6027\u3002\u6211\u4eec\u901a\u8fc7PE\u4f01\u4e1a\u548c\u975ePE\u4f01\u4e1a\u53c2\u4e0e\u7684\u7ade\u6807\u62cd\u5356\u6765\u5904\u7406\u9009\u62e9\u504f\u5dee\u3002PE\u57fa\u91d1\u6269\u5927\u4e86\u7269\u7406\u5bb9\u91cf\uff0c\u9f13\u52b1\u4f7f\u7528\u66f4\u5927\u673a\u578b\uff0c\u540c\u65f6\u5f15\u5165\u4f4e\u6210\u672c\u822a\u7a7a\u516c\u53f8\u548c\u56fd\u9645\u822a\u7ebf\u3002\u5b83\u4eec\u5728\u8150\u8d25\u7a0b\u5ea6\u8f83\u9ad8\u6216\u62e5\u6709\u56fd\u6709\u9aa8\u5e72\u822a\u7a7a\u516c\u53f8\u7684\u56fd\u5bb6\u4e2d\u5c24\u4e3a\u6709\u6548\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u975ePE\u6536\u8d2d\u65b9\u8868\u73b0\u8f83\u5dee\uff0c\u53ef\u80fd\u53cd\u6620\u4e86\u79c1\u4eba\u5229\u76ca\u548c\u4e0e\u5386\u53f2\u56fd\u6709\u5173\u7cfb\u7684\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1093/rfs/hhag056", "journal": "RFS", "title": "Institutional Synergies and the Fragility of Loan Funds", "authors": ["Mustafa Emin", "Christopher James", "Tao Li", "Jing Lu"], "author_details": [{"name": "Mustafa Emin", "affiliations": ["Culverhouse College of Business, University of Alabama ,"]}, {"name": "Christopher James", "affiliations": ["Warrington College of Business, University of Florida ,"]}, {"name": "Tao Li", "affiliations": ["Warrington College of Business, University of Florida , , and", "ECGI , , and"]}, {"name": "Jing Lu", "affiliations": ["University of New South Wales ,"]}], "abstract": "Abstract There are two major institutional investors in the syndicated loan market: collateralized loan obligations (CLOs) and loan mutual funds. CLOs are closed-end funds while loan funds are open-end funds that issue claims that are redeemable on demand. In this paper, we examine whether CLOs provide arbitrage capital that contributes to the resilience of loan funds. We find that CLOs act as shock absorbers, providing liquidity through par-building trades when loan funds experience large outflows. However, CLO-provided liquidity is limited to par build\u2013eligible loans, leading to potential flow-induced fire sales among par build\u2013ineligible loans.", "date": "2026-07-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag056", "title_zh": "\u673a\u6784\u534f\u540c\u4e0e\u8d37\u6b3e\u57fa\u91d1\u7684\u8106\u5f31\u6027", "abstract_zh": "\u6458\u8981 \u5728\u8d37\u6b3e\u5e02\u573a\u4e2d\uff0c\u6709\u4e24\u4e2a\u4e3b\u8981\u7684\u673a\u6784\u6295\u8d44\u8005\uff1a\u62c5\u4fdd\u8d37\u6b3e\u4e49\u52a1\uff08CLOs\uff09\u548c\u8d37\u6b3e\u57fa\u91d1\u3002CLOs\u662f\u5c01\u95ed\u5f0f\u57fa\u91d1\uff0c\u800c\u8d37\u6b3e\u57fa\u91d1\u662f\u5f00\u653e\u5f0f\u57fa\u91d1\uff0c\u5176\u53d1\u884c\u7684\u6743\u76ca\u53ef\u968f\u65f6\u8d4e\u56de\u3002\u672c\u6587\u7814\u7a76CLO\u662f\u5426\u63d0\u4f9b\u5957\u5229\u8d44\u672c\uff0c\u4ece\u800c\u589e\u5f3a\u8d37\u6b3e\u57fa\u91d1\u7684\u97e7\u6027\u3002\u6211\u4eec\u53d1\u73b0\uff0cCLO\u5728\u8d37\u6b3e\u57fa\u91d1\u906d\u9047\u5927\u89c4\u6a21\u8d4e\u56de\u65f6\uff0c\u4f1a\u4f5c\u4e3a\u7f13\u51b2\u673a\u5236\uff0c\u901a\u8fc7\u5e73\u4ef7\u6784\u5efa\u4ea4\u6613\u63d0\u4f9b\u6d41\u52a8\u6027\u3002\u7136\u800c\uff0cCLO\u63d0\u4f9b\u7684\u6d41\u52a8\u6027\u4ec5\u9650\u4e8e\u53ef\u53c2\u4e0e\u5e73\u4ef7\u6784\u5efa\u7684\u8d37\u6b3e\uff0c\u5bfc\u81f4\u65e0\u6cd5\u53c2\u4e0e\u5e73\u4ef7\u6784\u5efa\u7684\u8d37\u6b3e\u53ef\u80fd\u56e0\u6d41\u52a8\u6027\u538b\u529b\u800c\u5f15\u53d1\u4ef7\u683c\u4e0b\u8dcc\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1093/qje/qjag030", "journal": "QJE", "title": "Global Working Hours", "authors": ["Amory Gethin", "Emmanuel Saez"], "author_details": [{"name": "Amory Gethin", "affiliations": ["Development Research Group, World Bank ,"]}, {"name": "Emmanuel Saez", "affiliations": ["University of California, Berkeley ,"]}], "abstract": "Abstract This article uses labor force surveys from 160 countries to build a new microdatabase on hours worked covering 97% of the world population in cross section. We also construct time series spanning over 20 years in 86 countries. Hours worked per adult slightly decline with GDP per capita but are weakly correlated with development overall. Hours worked by the young (aged 15\u201319) and elderly (aged 60+) fall with development, driven entirely by growing school attendance and public pension coverage. Hours worked among prime-age adults (aged 20\u201359) are stable with development but undergo a great gender reshuffling: falling hours per male worker have been exactly offset by increases in female labor force participation in many countries. Labor income taxes are strongly negatively related to hours worked across countries. This correlation is attenuated when controlling for social spending and disappears when further controlling for working hours regulations. Both social spending and working hours regulations are associated with lower hours worked.", "date": "2026-07-02", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag030", "title_zh": "\u5168\u7403\u5de5\u4f5c\u65f6\u957f", "abstract_zh": "\u672c\u6587\u5229\u7528160\u4e2a\u56fd\u5bb6\u7684\u52b3\u52a8\u529b\u8c03\u67e5\u6570\u636e\uff0c\u6784\u5efa\u4e86\u4e00\u4e2a\u6db5\u76d6\u5168\u740397%\u4eba\u53e3\u7684\u5168\u65b0\u5fae\u89c2\u6570\u636e\u5e93\uff0c\u8bb0\u5f55\u4e86\u5de5\u4f5c\u65f6\u957f\u7684\u6a2a\u622a\u9762\u6570\u636e\u3002\u6211\u4eec\u8fd8\u4e3a86\u4e2a\u56fd\u5bb6\u6784\u5efa\u4e86\u8de8\u8d8a20\u591a\u5e74\u7684\u65f6\u5e8f\u6570\u636e\u3002\u6bcf\u540d\u6210\u5e74\u4eba\u7684\u5de5\u4f5c\u65f6\u957f\u968f\u4eba\u5747GDP\u7565\u6709\u4e0b\u964d\uff0c\u4f46\u6574\u4f53\u4e0a\u4e0e\u7ecf\u6d4e\u53d1\u5c55\u6c34\u5e73\u7684\u76f8\u5173\u6027\u8f83\u5f31\u300215\u81f319\u5c81\u9752\u5e74\u548c60\u5c81\u4ee5\u4e0a\u8001\u5e74\u4eba\u7684\u5de5\u4f5c\u65f6\u957f\u968f\u53d1\u5c55\u6c34\u5e73\u4e0b\u964d\uff0c\u8fd9\u4e00\u8d8b\u52bf\u5b8c\u5168\u7531\u5b66\u6821\u5165\u5b66\u7387\u4e0a\u5347\u548c\u516c\u5171\u517b\u8001\u91d1\u8986\u76d6\u8303\u56f4\u6269\u5927\u6240\u9a71\u52a8\u300220\u81f359\u5c81\u4e3b\u8981\u52b3\u52a8\u5e74\u9f84\u4eba\u7fa4\u7684\u5de5\u4f5c\u65f6\u957f\u5728\u7ecf\u6d4e\u53d1\u5c55\u8fc7\u7a0b\u4e2d\u4fdd\u6301\u7a33\u5b9a\uff0c\u4f46\u5448\u73b0\u51fa\u663e\u8457\u7684\u6027\u522b\u7ed3\u6784\u53d8\u5316\uff1a\u7537\u6027\u52b3\u52a8\u8005\u7684\u5de5\u4f5c\u65f6\u957f\u4e0b\u964d\uff0c\u88ab\u5973\u6027\u52b3\u52a8\u53c2\u4e0e\u7387\u7684\u663e\u8457\u4e0a\u5347\u6240\u62b5\u6d88\u3002\u52b3\u52a8\u6536\u5165\u7a0e\u4e0e\u5de5\u4f5c\u65f6\u957f\u5728\u5404\u56fd\u4e4b\u95f4\u5448\u73b0\u5f3a\u70c8\u8d1f\u76f8\u5173\u5173\u7cfb\u3002\u5f53\u63a7\u5236\u793e\u4f1a\u652f\u51fa\u540e\uff0c\u8fd9\u79cd\u76f8\u5173\u6027\u51cf\u5f31\uff1b\u8fdb\u4e00\u6b65\u63a7\u5236\u5de5\u4f5c\u65f6\u957f\u6cd5\u89c4\u540e\uff0c\u76f8\u5173\u6027\u5b8c\u5168\u6d88\u5931\u3002\u793e\u4f1a\u652f\u51fa\u548c\u5de5\u4f5c\u65f6\u957f\u6cd5\u89c4\u5747\u4e0e\u5de5\u4f5c\u65f6\u957f\u7684\u51cf\u5c11\u76f8\u5173\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag070", "journal": "REStud", "title": "Subjective Earnings Risk", "authors": ["Andrew Caplin", "Victoria Gregory", "Eungik Lee", "S\u00f8ren Leth-Petersen", "Johan S\u00e6verud"], "author_details": [{"name": "Andrew Caplin", "affiliations": ["New York University and NBER ,"]}, {"name": "Victoria Gregory", "affiliations": ["Federal Reserve Bank of St. Louis , USA"]}, {"name": "Eungik Lee", "affiliations": ["Federal Reserve Bank of New York , USA"]}, {"name": "S\u00f8ren Leth-Petersen", "affiliations": ["University of Copenhagen, CEBI, and CEPR ,"]}, {"name": "Johan S\u00e6verud", "affiliations": ["University of Copenhagen and CEBI ,"]}], "abstract": "Abstract We introduce a survey instrument to measure earnings risk allowing for the possibility of quitting or being fired from the current job. We find these transitions to be the key drivers of subjective risk. A link with administrative data provides multiple credibility checks and reveals that subjective earnings risk varies systematically across the population. It is also many times smaller than traditional estimates even when conditioning richly on demographics and job history. We show that subjective earnings risk can help explain why many hold limited liquid assets.", "date": "2026-07-02", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag070", "title_zh": "\u4e3b\u89c2\u6536\u5165\u98ce\u9669", "abstract_zh": "\u6211\u4eec\u8bbe\u8ba1\u4e86\u4e00\u79cd\u8c03\u67e5\u5de5\u5177\u6765\u8861\u91cf\u6536\u5165\u98ce\u9669\uff0c\u8be5\u5de5\u5177\u8003\u8651\u4e86\u79bb\u804c\u6216\u88ab\u89e3\u96c7\u7684\u53ef\u80fd\u6027\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u8fd9\u4e9b\u804c\u4e1a\u8f6c\u6362\u662f\u4e3b\u89c2\u98ce\u9669\u7684\u4e3b\u8981\u9a71\u52a8\u56e0\u7d20\u3002\u4e0e\u884c\u653f\u6570\u636e\u7684\u5173\u8054\u63d0\u4f9b\u4e86\u591a\u91cd\u53ef\u4fe1\u5ea6\u68c0\u9a8c\uff0c\u63ed\u793a\u4e86\u4e3b\u89c2\u6536\u5165\u98ce\u9669\u5728\u4eba\u53e3\u4e2d\u7684\u7cfb\u7edf\u6027\u5dee\u5f02\u3002\u6b64\u5916\uff0c\u5373\u4f7f\u5728\u5145\u5206\u8003\u8651\u4eba\u53e3\u7edf\u8ba1\u7279\u5f81\u548c\u5c31\u4e1a\u5386\u53f2\u7684\u60c5\u51b5\u4e0b\uff0c\u4e3b\u89c2\u6536\u5165\u98ce\u9669\u4e5f\u5f80\u5f80\u8fdc\u4f4e\u4e8e\u4f20\u7edf\u4f30\u8ba1\u503c\u3002\u6211\u4eec\u8868\u660e\uff0c\u4e3b\u89c2\u6536\u5165\u98ce\u9669\u53ef\u4ee5\u89e3\u91ca\u4e3a\u4f55\u8bb8\u591a\u4eba\u6301\u6709\u8f83\u5c11\u7684\u6d41\u52a8\u6027\u8d44\u4ea7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20241925", "journal": "AER", "title": "Monetary Policy without Commitment", "authors": ["Hassan Afrouzi", "Marina Halac", "Kenneth Rogoff", "Pierre Yared"], "author_details": [{"name": "Hassan Afrouzi", "affiliations": ["Columbia University, Department of Economics and NBER (email: )"]}, {"name": "Marina Halac", "affiliations": ["Yale University, Department of Economics and CEPR (email: )"]}, {"name": "Kenneth Rogoff", "affiliations": ["Harvard University, Department of Economics and NBER (email: )"]}, {"name": "Pierre Yared", "affiliations": ["Columbia University, Graduate School of Business and NBER (email: )"]}], "abstract": "This paper studies the implications of central bank credibility for long-run inflation and inflation dynamics. We introduce central bank lack of commitment into a standard nonlinear New Keynesian economy with sticky-price monopolistically competitive firms. Inflation is driven by the interaction of lack of commitment and the economic environment. We show that long-run inflation increases following an unanticipated permanent increase in the labor wedge or decrease in the elasticity of substitution across varieties. In the transition, inflation overshoots and then gradually declines. Quantitatively, inflation overshooting is persistent, and the welfare loss from lack of commitment relative to inflation targeting is large. (JEL D43, E12, E23, E24, E31, E52, E58)", "date": "2026-07-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20241925", "title_zh": "\u6ca1\u6709\u627f\u8bfa\u7684\u8d27\u5e01\u653f\u7b56", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u4e2d\u592e\u94f6\u884c\u4fe1\u8a89\u5bf9\u957f\u671f\u901a\u8d27\u81a8\u80c0\u53ca\u901a\u8d27\u81a8\u80c0\u52a8\u6001\u7684\u5f71\u54cd\u3002\u6211\u4eec\u5728\u6807\u51c6\u7684\u975e\u7ebf\u6027\u65b0\u51ef\u6069\u65af\u6a21\u578b\u4e2d\u5f15\u5165\u4e86\u4e2d\u592e\u94f6\u884c\u7f3a\u4e4f\u627f\u8bfa\u7684\u7279\u5f81\uff0c\u8be5\u6a21\u578b\u5305\u542b\u5177\u6709\u7c98\u6027\u4ef7\u683c\u7684\u5784\u65ad\u7ade\u4e89\u4f01\u4e1a\u3002\u901a\u8d27\u81a8\u80c0\u7531\u7f3a\u4e4f\u627f\u8bfa\u4e0e\u7ecf\u6d4e\u73af\u5883\u7684\u76f8\u4e92\u4f5c\u7528\u9a71\u52a8\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5f53\u52b3\u52a8\u6954\u5b50\u51fa\u73b0\u672a\u9884\u671f\u7684\u6c38\u4e45\u6027\u4e0a\u5347\uff0c\u6216\u4ea7\u54c1\u95f4\u66ff\u4ee3\u5f39\u6027\u4e0b\u964d\u65f6\uff0c\u957f\u671f\u901a\u8d27\u81a8\u80c0\u4f1a\u968f\u4e4b\u4e0a\u5347\u3002\u5728\u8fc7\u6e21\u8fc7\u7a0b\u4e2d\uff0c\u901a\u8d27\u81a8\u80c0\u4f1a\u5148\u51fa\u73b0\u8d85\u8c03\uff0c\u7136\u540e\u9010\u6e10\u56de\u843d\u3002\u4ece\u6570\u91cf\u4e0a\u770b\uff0c\u901a\u8d27\u81a8\u80c0\u7684\u8d85\u8c03\u662f\u6301\u4e45\u7684\uff0c\u7f3a\u4e4f\u627f\u8bfa\u76f8\u5bf9\u4e8e\u901a\u80c0\u76ee\u6807\u5236\u6240\u5e26\u6765\u7684\u798f\u5229\u635f\u5931\u5f88\u5927\u3002\uff08JEL D43, E12, E23, E24, E31, E52, E58\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20231415", "journal": "AER", "title": "The Effect of High-Tech Clusters on the Productivity of Top Inventors: Comment", "authors": ["Michael Wiebe"], "author_details": [{"name": "Michael Wiebe", "affiliations": ["Independent (email: )"]}], "abstract": "Moretti (2021) reports a positive elasticity between technology cluster size and patenting, and uses an event study and instrumental variables regressions to justify a causal interpretation. The event study does not use the variation generated by inventors moving across cities, and the instrument is constructed incorrectly due to a coding error. I run a corrected event study and fix the coding error, and find null effects. The reported elasticity may not be causal. (JEL J24, L60, O31, O34, R32)", "date": "2026-07-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20231415", "title_zh": "\u9ad8\u79d1\u6280\u96c6\u7fa4\u5bf9\u9876\u5c16\u53d1\u660e\u5bb6\u751f\u4ea7\u7387\u5f71\u54cd\u7684\u8bc4\u8bba", "abstract_zh": "Moretti\uff082021\uff09\u62a5\u544a\u4e86\u6280\u672f\u96c6\u7fa4\u89c4\u6a21\u4e0e\u4e13\u5229\u6570\u91cf\u4e4b\u95f4\u7684\u6b63\u5f39\u6027\uff0c\u5e76\u901a\u8fc7\u4e8b\u4ef6\u7814\u7a76\u548c\u5de5\u5177\u53d8\u91cf\u56de\u5f52\u6765\u652f\u6301\u56e0\u679c\u89e3\u91ca\u3002\u7136\u800c\uff0c\u8be5\u4e8b\u4ef6\u7814\u7a76\u672a\u5229\u7528\u53d1\u660e\u5bb6\u8de8\u57ce\u5e02\u8fc1\u79fb\u4ea7\u751f\u7684\u53d8\u5f02\uff0c\u4e14\u5de5\u5177\u53d8\u91cf\u56e0\u7f16\u7801\u9519\u8bef\u800c\u6784\u5efa\u4e0d\u5f53\u3002\u6211\u8fdb\u884c\u4e86\u4fee\u6b63\u540e\u7684\u4e8b\u4ef6\u7814\u7a76\u5e76\u4fee\u590d\u4e86\u7f16\u7801\u9519\u8bef\uff0c\u7ed3\u679c\u53d1\u73b0\u5e76\u65e0\u663e\u8457\u6548\u5e94\u3002\u56e0\u6b64\uff0c\u6240\u62a5\u544a\u7684\u5f39\u6027\u53ef\u80fd\u5e76\u975e\u56e0\u679c\u5173\u7cfb\u3002\uff08JEL J24, L60, O31, O34, R32\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20231521", "journal": "AER", "title": "Germs in the Family: The Short- and Long-Term Consequences of Intrahousehold Disease Spread", "authors": ["N. Meltem Daysal", "Hui Ding", "Maya Rossin-Slater", "Hannes Schwandt"], "author_details": [{"name": "N. Meltem Daysal", "affiliations": ["Department of Economics, University of Copenhagen, CEBI, CESifo, IZA (email: )"]}, {"name": "Hui Ding", "affiliations": ["School of Economics, Fudan University; Shanghai Institute of International Finance and Economics (email: )"]}, {"name": "Maya Rossin-Slater", "affiliations": ["Department of Health Policy, Stanford University School of Medicine, NBER, IZA (email: )"]}, {"name": "Hannes Schwandt", "affiliations": ["School of Education and Social Policy, Northwestern University, NBER, CEPR, IZA (email: )"]}], "abstract": "Preschool-aged children get sick frequently and spread disease to other family members. Despite the universality of this experience, there is limited causal evidence on the magnitudes and consequences of these externalities, especially for infant siblings with developing immune systems and brains. We show in Danish administrative data that during infancy, younger siblings have two to three times higher hospitalization rates for respiratory conditions than older siblings. We combine birth order and within-municipality variation in respiratory disease prevalence among young children, finding lasting differential impacts of early-life respiratory disease exposure on younger siblings' earnings, educational attainment, chronic respiratory health, and mental health-related outcomes. (JEL D13, D62, I12, J12, J13, J24, J31)", "date": "2026-07-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20231521", "title_zh": "\u5bb6\u5ead\u4e2d\u7684\u75c5\u83cc\uff1a\u5bb6\u5ead\u5185\u90e8\u75be\u75c5\u4f20\u64ad\u7684\u77ed\u671f\u4e0e\u957f\u671f\u540e\u679c", "abstract_zh": "\u5b66\u9f84\u524d\u513f\u7ae5\u7ecf\u5e38\u751f\u75c5\uff0c\u5e76\u5c06\u75be\u75c5\u4f20\u67d3\u7ed9\u5bb6\u5ead\u5176\u4ed6\u6210\u5458\u3002\u5c3d\u7ba1\u8fd9\u79cd\u7ecf\u5386\u666e\u904d\u5b58\u5728\uff0c\u4f46\u5173\u4e8e\u8fd9\u4e9b\u5916\u90e8\u6027\u5f71\u54cd\u7684\u5927\u5c0f\u548c\u540e\u679c\uff0c\u5c24\u5176\u662f\u5bf9\u514d\u75ab\u7cfb\u7edf\u548c\u5927\u8111\u5c1a\u672a\u53d1\u80b2\u5b8c\u5168\u7684\u5a74\u513f\u5144\u5f1f\u59d0\u59b9\u7684\u5f71\u54cd\uff0c\u76ee\u524d\u7f3a\u4e4f\u56e0\u679c\u8bc1\u636e\u3002\u6211\u4eec\u5229\u7528\u4e39\u9ea6\u7684\u884c\u653f\u6570\u636e\u53d1\u73b0\uff0c\u5728\u5a74\u513f\u671f\uff0c\u5e74\u5e7c\u7684\u5144\u5f1f\u59d0\u59b9\u56e0\u547c\u5438\u7cfb\u7edf\u75be\u75c5\u4f4f\u9662\u7684\u9891\u7387\u662f\u5e74\u957f\u5144\u5f1f\u59d0\u59b9\u7684\u4e24\u5230\u4e09\u500d\u3002\u6211\u4eec\u7ed3\u5408\u51fa\u751f\u987a\u5e8f\u4ee5\u53ca\u540c\u4e00\u57ce\u5e02\u5185\u5b66\u9f84\u524d\u513f\u7ae5\u547c\u5438\u7cfb\u7edf\u75be\u75c5\u6d41\u884c\u7387\u7684\u5dee\u5f02\uff0c\u53d1\u73b0\u65e9\u671f\u751f\u547d\u9636\u6bb5\u547c\u5438\u7cfb\u7edf\u75be\u75c5\u66b4\u9732\u5bf9\u5e74\u5e7c\u5144\u5f1f\u59d0\u59b9\u7684\u6536\u5165\u3001\u6559\u80b2\u6c34\u5e73\u3001\u6162\u6027\u547c\u5438\u5065\u5eb7\u72b6\u51b5\u4ee5\u53ca\u4e0e\u5fc3\u7406\u5065\u5eb7\u76f8\u5173\u7684\u7ed3\u679c\u5177\u6709\u6301\u4e45\u7684\u5dee\u5f02\u5316\u5f71\u54cd\u3002\uff08JEL D13, D62, I12, J12, J13, J24, J31\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240642", "journal": "AER", "title": "Self-Fulfilling Fluctuations in HANK Economies", "authors": ["Sushant Acharya", "Jess Benhabib"], "author_details": [{"name": "Sushant Acharya", "affiliations": ["University of Melbourne and CEPR (email: )"]}, {"name": "Jess Benhabib", "affiliations": ["New York University and NBER (email: )"]}], "abstract": "We show that in heterogeneous agent New Keynesian (HANK) economies with countercyclical risk, the natural interest rate is endogenous and co-moves with output, leaving the economy susceptible to self-fulfilling fluctuations. Unlike in representative agent New Keynesian models, the Taylor principle is not sufficient to guarantee uniqueness of equilibrium in HANK if risk is even mildly countercyclical: Multiple bounded equilibria exist, no matter how strongly monetary policy responds to changes in inflation. For an active monetary policy to eliminate self-fulfilling fluctuations, it must stabilize the endogenous natural rate fluctuations. Alternatively, a passive monetary and active fiscal regime can also eliminate equilibrium multiplicity. (JEL E12, E23, E31, E32, E43, E52, E62)", "date": "2026-07-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240642", "title_zh": "HANK\u6a21\u578b\u4e2d\u7684\u81ea\u6211\u5b9e\u73b0\u6ce2\u52a8", "abstract_zh": "\u6211\u4eec\u8bc1\u660e\uff0c\u5728\u5177\u6709\u9006\u5468\u671f\u98ce\u9669\u7684\u5f02\u8d28\u6027\u4e3b\u4f53\u65b0\u51ef\u6069\u65af\u6a21\u578b\uff08HANK\uff09\u4e2d\uff0c\u81ea\u7136\u5229\u7387\u662f\u5185\u751f\u7684\uff0c\u5e76\u4e0e\u4ea7\u51fa\u540c\u6b65\u53d8\u52a8\uff0c\u4f7f\u7ecf\u6d4e\u5bb9\u6613\u51fa\u73b0\u81ea\u6211\u5b9e\u73b0\u7684\u6ce2\u52a8\u3002\u4e0e\u4ee3\u8868\u6027\u4e3b\u4f53\u65b0\u51ef\u6069\u65af\u6a21\u578b\u4e0d\u540c\uff0c\u5373\u4f7f\u98ce\u9669\u4ec5\u8f7b\u5fae\u5448\u9006\u5468\u671f\u6027\uff0c\u6cf0\u52d2\u539f\u5219\u4e5f\u5e76\u4e0d\u80fd\u4fdd\u8bc1\u5747\u8861\u7684\u552f\u4e00\u6027\uff1a\u65e0\u8bba\u8d27\u5e01\u653f\u7b56\u5bf9\u901a\u80c0\u53d8\u5316\u7684\u53cd\u5e94\u591a\u4e48\u5f3a\u70c8\uff0c\u90fd\u53ef\u80fd\u5b58\u5728\u591a\u4e2a\u6709\u754c\u5747\u8861\u3002\u82e5\u8981\u6d88\u9664\u81ea\u6211\u5b9e\u73b0\u7684\u6ce2\u52a8\uff0c\u79ef\u6781\u7684\u8d27\u5e01\u653f\u7b56\u5fc5\u987b\u7a33\u5b9a\u5185\u751f\u7684\u81ea\u7136\u5229\u7387\u6ce2\u52a8\u3002\u6216\u8005\uff0c\u4e5f\u53ef\u4ee5\u91c7\u7528\u88ab\u52a8\u8d27\u5e01\u653f\u7b56\u4e0e\u79ef\u6781\u8d22\u653f\u653f\u7b56\u76f8\u7ed3\u5408\u7684\u5236\u5ea6\u6765\u6d88\u9664\u5747\u8861\u7684\u591a\u91cd\u6027\u3002\uff08JEL E12, E23, E31, E32, E43, E52, E62\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20231613", "journal": "AER", "title": "Market Opacity and Fragility: Why Liquidity Evaporates When It Is Most Needed", "authors": ["Giovanni Cespa", "Xavier Vives"], "author_details": [{"name": "Giovanni Cespa", "affiliations": ["Bayes Business School, City St George's, University of London, and CEPR (email: )"]}, {"name": "Xavier Vives", "affiliations": ["IESE Business School (email: )"]}], "abstract": "Lack of market transparency can impair the liquidity provision of nonstandard liquidity suppliers and make liquidity demand increasing in illiquidity. This can yield strategic complementarities and induce multiple equilibria. Then an initial dearth of liquidity may degenerate into a liquidity rout (as in a \u201cflash crash\u201d), and traders faced with the largest cost of trading are those trading more intensely at equilibrium. An increase in order flow transparency and/or in the mass of dealers who are in the market at all times has a positive impact on total welfare. (JEL G12, G14, G41)", "date": "2026-07-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20231613", "title_zh": "\u5e02\u573a\u4e0d\u900f\u660e\u6027\u4e0e\u8106\u5f31\u6027\uff1a\u4e3a\u4f55\u6d41\u52a8\u6027\u5728\u6700\u9700\u8981\u65f6\u4f1a\u6d88\u5931", "abstract_zh": "\u5e02\u573a\u900f\u660e\u5ea6\u7684\u7f3a\u4e4f\u4f1a\u635f\u5bb3\u975e\u6807\u51c6\u6d41\u52a8\u6027\u63d0\u4f9b\u8005\u7684\u6d41\u52a8\u6027\u4f9b\u7ed9\u80fd\u529b\uff0c\u5e76\u4f7f\u6d41\u52a8\u6027\u9700\u6c42\u968f\u7740\u975e\u6d41\u52a8\u6027\u7a0b\u5ea6\u7684\u4e0a\u5347\u800c\u589e\u52a0\u3002\u8fd9\u53ef\u80fd\u5bfc\u81f4\u6218\u7565\u4e92\u8865\u6027\u5e76\u5f15\u53d1\u591a\u91cd\u5747\u8861\u3002\u56e0\u6b64\uff0c\u521d\u59cb\u6d41\u52a8\u6027\u77ed\u7f3a\u53ef\u80fd\u6f14\u53d8\u4e3a\u6d41\u52a8\u6027\u5371\u673a\uff08\u5982\u540c\"\u95ea\u5d29\"\uff09\uff0c\u800c\u5728\u5747\u8861\u72b6\u6001\u4e0b\uff0c\u4ea4\u6613\u6210\u672c\u6700\u9ad8\u7684\u4ea4\u6613\u8005\u6070\u6070\u662f\u4ea4\u6613\u6700\u9891\u7e41\u7684\u4ea4\u6613\u8005\u3002\u63d0\u9ad8\u8ba2\u5355\u6d41\u900f\u660e\u5ea6\u4ee5\u53ca/\u6216\u589e\u52a0\u59cb\u7ec8\u5904\u4e8e\u5e02\u573a\u4e2d\u7684\u4ea4\u6613\u5546\u6570\u91cf\uff0c\u5bf9\u603b\u798f\u5229\u5177\u6709\u79ef\u6781\u5f71\u54cd\u3002\uff08JEL G12, G14, G41\uff09", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1257/aer.20250064", "journal": "AER", "title": "A Theory of Price Caps on Nonrenewable Resources", "authors": ["Simon Johnson", "Lukasz Rachel", "Catherine Wolfram"], "author_details": [{"name": "Simon Johnson", "affiliations": ["MIT Sloan School of Management and NBER (email: )"]}, {"name": "Lukasz Rachel", "affiliations": ["University College London and CEPR (email: )"]}, {"name": "Catherine Wolfram", "affiliations": ["MIT Sloan School of Management and NBER (email: )"]}], "abstract": "What is the optimal response of a resource exporter when a price cap is imposed on its main export? This paper develops a dynamic framework incorporating stochastic prices, financial frictions, and market power to study this novel tool of statecraft. With the right design, a price cap can incentivize increased extraction, stabilizing prices in the global market. But the stabilizing effects diminish when there is leakage outside the cap. Consequently, weak enforcement of the policy worsens the trade-off faced by the sanctioning policymaker. We provide a systematic approach to setting and enforcing an optimal cap level in these circumstances. (JEL F12, F14, F51, L71, P28, P33, Q35)", "date": "2026-07-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20250064", "title_zh": "\u4e00\u79cd\u975e\u53ef\u518d\u751f\u8d44\u6e90\u4ef7\u683c\u4e0a\u9650\u7684\u7406\u8bba", "abstract_zh": "\u5f53\u4e3b\u8981\u51fa\u53e3\u5546\u54c1\u53d7\u5230\u4ef7\u683c\u4e0a\u9650\u9650\u5236\u65f6\uff0c\u8d44\u6e90\u51fa\u53e3\u56fd\u7684\u6700\u4f18\u53cd\u5e94\u662f\u4ec0\u4e48\uff1f\u672c\u6587\u5efa\u7acb\u4e86\u4e00\u4e2a\u52a8\u6001\u6846\u67b6\uff0c\u7eb3\u5165\u4e86\u968f\u673a\u4ef7\u683c\u3001\u91d1\u878d\u6469\u64e6\u548c\u5e02\u573a\u529b\u91cf\uff0c\u4ee5\u7814\u7a76\u8fd9\u4e00\u65b0\u578b\u56fd\u5bb6\u884c\u4e3a\u5de5\u5177\u3002\u5728\u9002\u5f53\u8bbe\u8ba1\u4e0b\uff0c\u4ef7\u683c\u4e0a\u9650\u53ef\u4ee5\u6fc0\u52b1\u589e\u52a0\u5f00\u91c7\uff0c\u4ece\u800c\u7a33\u5b9a\u5168\u7403\u5e02\u573a\u4ef7\u683c\u3002\u4f46\u5f53\u5b58\u5728\u4ef7\u683c\u4e0a\u9650\u4e4b\u5916\u7684\u6cc4\u6f0f\u65f6\uff0c\u8fd9\u79cd\u7a33\u5b9a\u6548\u5e94\u4f1a\u51cf\u5f31\u3002\u56e0\u6b64\uff0c\u653f\u7b56\u6267\u884c\u529b\u5ea6\u8584\u5f31\u4f1a\u6076\u5316\u5236\u88c1\u653f\u7b56\u5236\u5b9a\u8005\u9762\u4e34\u7684\u6743\u8861\u3002\u672c\u6587\u4e3a\u5728\u8fd9\u4e9b\u60c5\u51b5\u4e0b\u8bbe\u5b9a\u548c\u6267\u884c\u6700\u4f18\u4ef7\u683c\u4e0a\u9650\u63d0\u4f9b\u4e86\u4e00\u79cd\u7cfb\u7edf\u6027\u65b9\u6cd5\u3002\uff08JEL F12, F14, F51, L71, P28, P33, Q35\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.1257/aer.20230849", "journal": "AER", "title": "The Aggregate Costs of Uninsurable Business Risk", "authors": ["Corina Boar", "Denis Gorea", "Virgiliu Midrigan"], "author_details": [{"name": "Corina Boar", "affiliations": ["New York University and NBER (email: )"]}, {"name": "Denis Gorea", "affiliations": ["Bank for International Settlements (email: )"]}, {"name": "Virgiliu Midrigan", "affiliations": ["New York University and NBER (email: )"]}], "abstract": "We use firm-level data to document that private businesses experience large fluctuations in their profit shares. These are due to large, fat-tailed, and transitory changes in output that are not fully accompanied by changes in their inputs. We interpret this evidence using a model of entrepreneurial dynamics. Because firms can limit their exposure to risk by operating at a smaller scale, our model predicts large macroeconomic losses from uninsurable business risk, much larger than those stemming from credit constraints. While self-financing allows entrepreneurs to quickly overcome credit constraints, even wealthy entrepreneurs remain considerably exposed to risk. (JEL D33, E02, E44, G32, L25, L26)", "date": "2026-07-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230849", "title_zh": "\u4e0d\u53ef\u4fdd\u9669\u5546\u4e1a\u98ce\u9669\u7684\u603b\u4f53\u6210\u672c", "abstract_zh": "\u6211\u4eec\u5229\u7528\u4f01\u4e1a\u5c42\u9762\u7684\u6570\u636e\u8868\u660e\uff0c\u79c1\u8425\u4f01\u4e1a\u9762\u4e34\u663e\u8457\u7684\u5229\u6da6\u4efd\u989d\u6ce2\u52a8\u3002\u8fd9\u4e9b\u6ce2\u52a8\u6e90\u4e8e\u4ea7\u51fa\u4e2d\u51fa\u73b0\u7684\u5927\u89c4\u6a21\u3001\u539a\u5c3e\u5206\u5e03\u4e14\u77ed\u6682\u7684\u53d8\u52a8\uff0c\u800c\u8fd9\u4e9b\u53d8\u52a8\u5e76\u672a\u5b8c\u5168\u4f34\u968f\u7740\u6295\u5165\u7684\u76f8\u5e94\u53d8\u5316\u3002\u6211\u4eec\u57fa\u4e8e\u521b\u4e1a\u52a8\u6001\u6a21\u578b\u89e3\u91ca\u8fd9\u4e00\u73b0\u8c61\u3002\u7531\u4e8e\u4f01\u4e1a\u53ef\u4ee5\u901a\u8fc7\u7f29\u5c0f\u7ecf\u8425\u89c4\u6a21\u6765\u964d\u4f4e\u98ce\u9669\u66b4\u9732\uff0c\u6211\u4eec\u7684\u6a21\u578b\u9884\u6d4b\uff0c\u4e0d\u53ef\u4fdd\u9669\u7684\u5546\u4e1a\u98ce\u9669\u5bf9\u5b8f\u89c2\u7ecf\u6d4e\u9020\u6210\u7684\u635f\u5931\u8fdc\u5927\u4e8e\u7531\u4fe1\u8d37\u7ea6\u675f\u5f15\u8d77\u7684\u635f\u5931\u3002\u5c3d\u7ba1\u81ea\u6211\u878d\u8d44\u4f7f\u521b\u4e1a\u8005\u80fd\u591f\u8fc5\u901f\u514b\u670d\u4fe1\u8d37\u7ea6\u675f\uff0c\u4f46\u5373\u4f7f\u8d22\u5bcc\u96c4\u539a\u7684\u521b\u4e1a\u8005\u4ecd\u9762\u4e34\u663e\u8457\u7684\u98ce\u9669\u66b4\u9732\u3002\uff08JEL D33\uff0cE02\uff0cE44\uff0cG32\uff0cL25\uff0cL26\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20250166", "journal": "AER", "title": "A Welfare Analysis of Policies Impacting Climate Change", "authors": ["Robert W. Hahn", "Nathaniel Hendren", "Robert D. Metcalfe", "Ben Sprung-Keyser"], "author_details": [{"name": "Robert W. Hahn", "affiliations": ["University of Oxford and Carnegie Mellon University (email: )"]}, {"name": "Nathaniel Hendren", "affiliations": ["Massachusetts Institute of Technology and Policy Impacts (email: )"]}, {"name": "Robert D. Metcalfe", "affiliations": ["Columbia University and NBER (email: )"]}, {"name": "Ben Sprung-Keyser", "affiliations": ["Wharton School, University of Pennsylvania and Policy Impacts (email: )"]}], "abstract": "We study the welfare impacts of 96 climate-related tax and spending policies. We extend and apply the marginal value of public funds (MVPF) framework, most notably providing a new method for incorporating learning-by-doing spillovers. We find subsidies for the production of clean energy (such as wind production tax credits) have higher MVPFs than all other subsidies in our sample, including EV subsidies. Conservation nudges have large MVPFs when targeting regions with dirty grids. Fuel taxes and cap-and-trade policies are highly efficient means of raising revenue. We also construct traditional cost-per-ton estimates and compare and contrast the lessons they provide. (JEL D83, H23, H25, L62, Q42, Q54, Q58)", "date": "2026-07-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20250166", "title_zh": "\u6c14\u5019\u53d8\u5316\u653f\u7b56\u798f\u5229\u6548\u5e94\u5206\u6790", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e8696\u9879\u4e0e\u6c14\u5019\u53d8\u5316\u76f8\u5173\u7684\u7a0e\u6536\u548c\u652f\u51fa\u653f\u7b56\u7684\u798f\u5229\u5f71\u54cd\u3002\u6211\u4eec\u6269\u5c55\u5e76\u5e94\u7528\u4e86\u516c\u5171\u8d44\u91d1\u8fb9\u9645\u4ef7\u503c\uff08MVPF\uff09\u6846\u67b6\uff0c\u7279\u522b\u662f\u63d0\u51fa\u4e86\u4e00\u79cd\u7eb3\u5165\u2018\u901a\u8fc7\u5b9e\u8df5\u5b66\u4e60\u7684\u6ea2\u51fa\u6548\u5e94\u2019\u7684\u65b0\u65b9\u6cd5\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u6e05\u6d01\u80fd\u6e90\u751f\u4ea7\u8865\u8d34\uff08\u5982\u98ce\u80fd\u751f\u4ea7\u7a0e\u62b5\u514d\uff09\u7684MVPF\u9ad8\u4e8e\u6837\u672c\u4e2d\u6240\u6709\u5176\u4ed6\u8865\u8d34\uff0c\u5305\u62ec\u7535\u52a8\u6c7d\u8f66\u8865\u8d34\u3002\u5f53\u9488\u5bf9\u7535\u7f51\u6c61\u67d3\u7a0b\u5ea6\u9ad8\u7684\u5730\u533a\u65f6\uff0c\u8282\u80fd\u5f15\u5bfc\u63aa\u65bd\u5177\u6709\u8f83\u5927\u7684MVPF\u3002\u71c3\u6cb9\u7a0e\u548c\u78b3\u6392\u653e\u4ea4\u6613\u653f\u7b56\u662f\u9ad8\u6548\u7b79\u96c6\u6536\u5165\u7684\u624b\u6bb5\u3002\u6211\u4eec\u8fd8\u6784\u5efa\u4e86\u4f20\u7edf\u6bcf\u5428\u6210\u672c\u4f30\u7b97\uff0c\u5e76\u5bf9\u6bd4\u4e86\u8fd9\u4e9b\u4f30\u7b97\u6240\u63d0\u4f9b\u7684\u542f\u793a\u3002\uff08JEL D83, H23, H25, L62, Q42, Q54, Q58\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.1257/aer.20240673", "journal": "AER", "title": "Ideological Alignment and Evidence-Based Policy Adoption", "authors": ["Jorge Garc\u00eda-Hombrados", "Marcel Jansen", "\u00c1ngel Mart\u00ednez", "Berkay \u00d6zcan", "Pedro Rey-Biel", "Antonio Rold\u00e1n-Mon\u00e9s"], "author_details": [{"name": "Jorge Garc\u00eda-Hombrados", "affiliations": ["Universidad Aut\u00f3noma de Madrid and Instituto de Econom\u00eda, Universidad Carlos III de Madrid (email: )"]}, {"name": "Marcel Jansen", "affiliations": ["Universidad Aut\u00f3noma de Madrid and IZA (email: )"]}, {"name": "\u00c1ngel Mart\u00ednez", "affiliations": ["Esade EcPol, ESADE-URL (email: )"]}, {"name": "Berkay \u00d6zcan", "affiliations": ["London School of Economics and Political Science and New York University Abu Dhabi (email: )"]}, {"name": "Pedro Rey-Biel", "affiliations": ["Universidad Ram\u00f3n Llull, ESADE-URL (email: )"]}, {"name": "Antonio Rold\u00e1n-Mon\u00e9s", "affiliations": ["School of Politics, Economics and Global Affairs (SPEGA), IE University (email: )"]}], "abstract": "The implementation of evidence-based policies hinges on the dissemination of evidence to policymakers, a process influenced by the attributes of the sender. We conducted a nationwide RCT with ideologically opposite think tanks, major newspapers, and a research institution with nonsalient ideology to communicate a nonideological, cost-effective policy to local policymakers. Results show a 65 percent increase in policy adoption when informing institutions align ideologically with policymakers. We compare the impact of think tanks versus media outlets on implementation, finding both equally effective when ideologically aligned. We explore three actions where ideology may influence adoption: information exposure, belief updating and implementation. (JEL C93, D72, D78, D83, I23)", "date": "2026-07-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240673", "title_zh": "\u610f\u8bc6\u5f62\u6001\u4e00\u81f4\u6027\u4e0e\u57fa\u4e8e\u8bc1\u636e\u7684\u653f\u7b56\u91c7\u7eb3", "abstract_zh": "\u57fa\u4e8e\u8bc1\u636e\u7684\u653f\u7b56\u5b9e\u65bd\u4f9d\u8d56\u4e8e\u8bc1\u636e\u5411\u653f\u7b56\u5236\u5b9a\u8005\u7684\u4f20\u64ad\uff0c\u800c\u8fd9\u4e00\u8fc7\u7a0b\u53d7\u5230\u4fe1\u606f\u63d0\u4f9b\u8005\u5c5e\u6027\u7684\u5f71\u54cd\u3002\u6211\u4eec\u5f00\u5c55\u4e86\u4e00\u9879\u5168\u56fd\u6027\u7684\u968f\u673a\u5bf9\u7167\u8bd5\u9a8c\uff0c\u8ba9\u5177\u6709\u76f8\u53cd\u610f\u8bc6\u5f62\u6001\u7684\u667a\u5e93\u3001\u4e3b\u8981\u62a5\u7eb8\u4ee5\u53ca\u4e00\u4e2a\u65e0\u660e\u663e\u610f\u8bc6\u5f62\u6001\u7684\u7814\u7a76\u673a\u6784\u5411\u5730\u65b9\u653f\u7b56\u5236\u5b9a\u8005\u4f20\u8fbe\u4e00\u9879\u975e\u610f\u8bc6\u5f62\u6001\u4e14\u6210\u672c\u6548\u76ca\u9ad8\u7684\u653f\u7b56\u3002\u7ed3\u679c\u8868\u660e\uff0c\u5f53\u4fe1\u606f\u63d0\u4f9b\u673a\u6784\u5728\u610f\u8bc6\u5f62\u6001\u4e0a\u4e0e\u653f\u7b56\u5236\u5b9a\u8005\u4e00\u81f4\u65f6\uff0c\u653f\u7b56\u91c7\u7eb3\u7387\u63d0\u9ad8\u4e8665%\u3002\u6211\u4eec\u6bd4\u8f83\u4e86\u667a\u5e93\u4e0e\u5a92\u4f53\u673a\u6784\u5bf9\u653f\u7b56\u5b9e\u65bd\u7684\u5f71\u54cd\uff0c\u53d1\u73b0\u5f53\u4e24\u8005\u5728\u610f\u8bc6\u5f62\u6001\u4e0a\u4e00\u81f4\u65f6\uff0c\u5176\u6548\u679c\u76f8\u5f53\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u63a2\u8ba8\u4e86\u610f\u8bc6\u5f62\u6001\u53ef\u80fd\u5f71\u54cd\u653f\u7b56\u91c7\u7eb3\u7684\u4e09\u4e2a\u73af\u8282\uff1a\u4fe1\u606f\u66b4\u9732\u3001\u4fe1\u5ff5\u66f4\u65b0\u548c\u653f\u7b56\u5b9e\u65bd\u3002\uff08JEL C93, D72, D78, D83, I23\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20230344", "journal": "AER", "title": "Understanding High-Wage Firms: Monopoly, Monopsony, and Bargaining Power", "authors": ["Horng Chern Wong"], "author_details": [{"name": "Horng Chern Wong", "affiliations": ["Stockholm University (email: )"]}], "abstract": "I study how firm market power and worker bargaining power shape wages and welfare. Using French micro-data, I document patterns linking wages and firm market power that existing models cannot explain. A model in which firms produce vertically differentiated goods and share profits with workers explains those patterns. The model (i) reveals new challenges in estimating monopsony and bargaining power, proposing an alternative approach; (ii) shows that the passthrough of firm-specific shocks to wages depends on the type of shock; (iii) explains how markups shape firm wage premia; and (iv) formalizes how strengthening worker bargaining power affects wages and welfare. (JEL D22, J31, J42, J52, L12, L22)", "date": "2026-07-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230344", "title_zh": "\u7406\u89e3\u9ad8\u5de5\u8d44\u4f01\u4e1a\u7684\u5f62\u6210\uff1a\u5784\u65ad\u3001\u5784\u65ad\u7ade\u4e89\u4e0e\u8c08\u5224\u529b\u91cf", "abstract_zh": "\u6211\u7814\u7a76\u4e86\u4f01\u4e1a\u5e02\u573a\u529b\u91cf\u548c\u52b3\u52a8\u8005\u8c08\u5224\u529b\u91cf\u5982\u4f55\u5f71\u54cd\u5de5\u8d44\u548c\u798f\u5229\u3002\u5229\u7528\u6cd5\u56fd\u5fae\u89c2\u6570\u636e\uff0c\u6211\u53d1\u73b0\u4e86\u73b0\u6709\u6a21\u578b\u65e0\u6cd5\u89e3\u91ca\u7684\u5de5\u8d44\u4e0e\u4f01\u4e1a\u5e02\u573a\u529b\u91cf\u4e4b\u95f4\u7684\u5173\u8054\u6a21\u5f0f\u3002\u4e00\u4e2a\u5047\u8bbe\u4f01\u4e1a\u751f\u4ea7\u5782\u76f4\u5dee\u5f02\u5316\u4ea7\u54c1\u5e76\u5c06\u5176\u5229\u6da6\u4e0e\u5458\u5de5\u5171\u4eab\u7684\u6a21\u578b\uff0c\u80fd\u591f\u89e3\u91ca\u8fd9\u4e9b\u6a21\u5f0f\u3002\u8be5\u6a21\u578b\uff08i\uff09\u63ed\u793a\u4e86\u5728\u4f30\u8ba1\u5784\u65ad\u548c\u8c08\u5224\u529b\u91cf\u65f6\u9762\u4e34\u7684\u65b0\u6311\u6218\uff0c\u63d0\u51fa\u4e86\u66ff\u4ee3\u6027\u65b9\u6cd5\uff1b\uff08ii\uff09\u8868\u660e\u4f01\u4e1a\u7279\u5b9a\u51b2\u51fb\u5bf9\u5de5\u8d44\u7684\u4f20\u5bfc\u53d6\u51b3\u4e8e\u51b2\u51fb\u7684\u7c7b\u578b\uff1b\uff08iii\uff09\u89e3\u91ca\u4e86\u5229\u6da6\u7387\u5982\u4f55\u5f71\u54cd\u4f01\u4e1a\u5de5\u8d44\u6ea2\u4ef7\uff1b\uff08iv\uff09\u6b63\u5f0f\u8bf4\u660e\u4e86\u589e\u5f3a\u52b3\u52a8\u8005\u8c08\u5224\u529b\u91cf\u5982\u4f55\u5f71\u54cd\u5de5\u8d44\u548c\u798f\u5229\u3002\uff08JEL D22, J31, J42, J52, L12, L22\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20230242", "journal": "AER", "title": "The Effect of Omitted Variables on the Sign of Regression Coefficients", "authors": ["Matthew A. Masten", "Alexandre Poirier"], "author_details": [{"name": "Matthew A. Masten", "affiliations": ["Department of Economics, Duke University (email: )"]}, {"name": "Alexandre Poirier", "affiliations": ["Department of Economics, Georgetown University (email: )"]}], "abstract": "We show that, depending on how the impact of omitted variables is measured, it can be substantially easier for omitted variables to flip coefficient signs than to drive them to zero. This behavior occurs with \u201cOster's delta\u201d (Oster 2019a), a widely reported robustness measure. Consequently, any time this measure is large\u2014suggesting omitted variables may be unimportant\u2014a much smaller value reverses the sign of the parameter of interest. We propose a modified measure of robustness to address this concern. We illustrate our results in four empirical applications and two meta-analyses. We implement our methods in the companion Stata module \u201cregsensitivity.\u201d (JEL C18, C21, C52)", "date": "2026-07-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230242", "title_zh": "\u9057\u6f0f\u53d8\u91cf\u5bf9\u56de\u5f52\u7cfb\u6570\u7b26\u53f7\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u8bc1\u660e\uff0c\u6839\u636e\u9057\u6f0f\u53d8\u91cf\u5f71\u54cd\u7684\u6d4b\u91cf\u65b9\u5f0f\u4e0d\u540c\uff0c\u9057\u6f0f\u53d8\u91cf\u5bfc\u81f4\u7cfb\u6570\u7b26\u53f7\u53cd\u8f6c\u7684\u60c5\u51b5\u53ef\u80fd\u8fdc\u6bd4\u4f7f\u5176\u8d8b\u8fd1\u4e8e\u96f6\u66f4\u5bb9\u6613\u53d1\u751f\u3002\u8fd9\u79cd\u73b0\u8c61\u5728\u2018Oster\u7684delta\u2019\uff08Oster 2019a\uff09\u8fd9\u4e00\u5e7f\u6cdb\u4f7f\u7528\u7684\u7a33\u5065\u6027\u5ea6\u91cf\u4e2d\u5c24\u4e3a\u660e\u663e\u3002\u56e0\u6b64\uff0c\u6bcf\u5f53\u8be5\u5ea6\u91cf\u503c\u8f83\u5927\u2014\u2014\u8868\u660e\u9057\u6f0f\u53d8\u91cf\u53ef\u80fd\u5e76\u4e0d\u91cd\u8981\u65f6\uff0c\u4e00\u4e2a\u6570\u503c\u8f83\u5c0f\u7684\u503c\u53cd\u800c\u4f1a\u53cd\u8f6c\u53c2\u6570\u7684\u7b26\u53f7\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u6539\u8fdb\u7684\u7a33\u5065\u6027\u5ea6\u91cf\u6765\u5e94\u5bf9\u8fd9\u4e00\u95ee\u9898\u3002\u6211\u4eec\u5728\u56db\u4e2a\u5b9e\u8bc1\u7814\u7a76\u548c\u4e24\u9879\u5143\u5206\u6790\u4e2d\u5c55\u793a\u4e86\u6211\u4eec\u7684\u7ed3\u679c\uff0c\u5e76\u5728\u914d\u5957\u7684Stata\u6a21\u5757\u201cregsensitivity\u201d\u4e2d\u5b9e\u73b0\u4e86\u6211\u4eec\u7684\u65b9\u6cd5\u3002\uff08JEL C18, C21, C52\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag034", "journal": "QJE", "title": "Who Pays for Unions?", "authors": ["Samuel Dodini", "Anna Stansbury", "Alexander Will\u00e9n"], "author_details": [{"name": "Samuel Dodini", "affiliations": ["Federal Reserve Bank of Dallas ,"]}, {"name": "Anna Stansbury", "affiliations": ["MIT Sloan School of Management ,"]}, {"name": "Alexander Will\u00e9n", "affiliations": ["Norwegian School of Economics ,"]}], "abstract": "Abstract If unions raise worker wages, who pays? We provide a comprehensive assessment of firm responses to increased unionization, using changes in the tax deductibility of union dues in Norway as a quasi-exogenous source of variation in firm-level union density. In the average private sector firm, higher union density raises labor costs and leads firms to contract employment and production, lowering profits without increasing the labor share. The incidence is shared: consumers bear part of the cost through higher prices, shareholders through lower profits, and the remainder is offset by productivity improvements. The total wage bill falls, with losses concentrated among less attached \u201coutsider\u201d workers. Firm responses vary systematically by the degree of market competition. In manufacturing, where firms operate in less competitive product and labor markets, the response is reversed: the average firm expands employment and production, reduces labor markdowns, and does not experience profit declines. Instead, higher labor costs are largely passed on to consumers through higher prices, with the remainder offset by productivity gains. Workers benefit as both wages and employment rise. These patterns suggest that unions can offset employer monopsony power and that firm responses\u2014and therefore who ultimately bears the cost\u2014depend importantly on market structure. Overall, unionization in this setting primarily redistributes from consumers rather than shareholders and has effects that differ sharply across firms, including a reallocation toward larger and more productive firms. We rationalize these patterns using a partial-equilibrium model of union bargaining with product- and labor-market power.", "date": "2026-07-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag034", "title_zh": "\u8c01\u4e3a\u5de5\u4f1a\u4e70\u5355\uff1f", "abstract_zh": "\u6458\u8981 \u5982\u679c\u5de5\u4f1a\u63d0\u9ad8\u4e86\u5de5\u4eba\u7684\u5de5\u8d44\uff0c\u8c01\u6765\u627f\u62c5\u8fd9\u7b14\u8d39\u7528\uff1f\u6211\u4eec\u5229\u7528\u632a\u5a01\u5bf9\u5de5\u4f1a\u4f1a\u8d39\u7a0e\u524d\u6263\u9664\u8d44\u683c\u7684\u53d8\u5316\u4f5c\u4e3a\u4f01\u4e1a\u5c42\u9762\u5de5\u4f1a\u5bc6\u5ea6\u7684\u51c6\u5916\u751f\u53d8\u5316\u6765\u6e90\uff0c\u5bf9\u4f01\u4e1a\u5728\u5de5\u4f1a\u5316\u7a0b\u5ea6\u63d0\u9ad8\u540e\u7684\u53cd\u5e94\u8fdb\u884c\u4e86\u5168\u9762\u8bc4\u4f30\u3002\u5728\u5e73\u5747\u79c1\u8425\u4f01\u4e1a\u4e2d\uff0c\u5de5\u4f1a\u5bc6\u5ea6\u7684\u4e0a\u5347\u4f1a\u63d0\u9ad8\u52b3\u52a8\u529b\u6210\u672c\uff0c\u5bfc\u81f4\u4f01\u4e1a\u51cf\u5c11\u96c7\u4f63\u548c\u751f\u4ea7\uff0c\u5229\u6da6\u4e0b\u964d\u4f46\u52b3\u52a8\u6536\u5165\u4efd\u989d\u5e76\u672a\u4e0a\u5347\u3002\u6210\u672c\u5206\u644a\u662f\u5171\u4eab\u7684\uff1a\u6d88\u8d39\u8005\u901a\u8fc7\u4ef7\u683c\u4e0a\u6da8\u627f\u62c5\u90e8\u5206\u6210\u672c\uff0c\u80a1\u4e1c\u901a\u8fc7\u5229\u6da6\u4e0b\u964d\u627f\u62c5\u90e8\u5206\u6210\u672c\uff0c\u5176\u4f59\u90e8\u5206\u5219\u901a\u8fc7\u751f\u4ea7\u7387\u63d0\u5347\u5f97\u5230\u62b5\u6d88\u3002\u603b\u5de5\u8d44\u652f\u51fa\u4e0b\u964d\uff0c\u635f\u5931\u4e3b\u8981\u96c6\u4e2d\u5728\u4e0e\u4f01\u4e1a\u5173\u8054\u5ea6\u8f83\u4f4e\u7684\u201c\u5916\u6765\u201d\u5de5\u4eba\u8eab\u4e0a\u3002\u4f01\u4e1a\u53cd\u5e94\u7cfb\u7edf\u6027\u5730\u53d6\u51b3\u4e8e\u5e02\u573a\u7ade\u4e89\u7a0b\u5ea6\u3002\u5728\u5236\u9020\u4e1a\u4e2d\uff0c\u7531\u4e8e\u4f01\u4e1a\u5728\u4ea7\u54c1\u548c\u52b3\u52a8\u529b\u5e02\u573a\u4e0a\u7684\u7ade\u4e89\u7a0b\u5ea6\u8f83\u4f4e\uff0c\u53cd\u5e94\u5448\u73b0\u76f8\u53cd\u8d8b\u52bf\uff1a\u5e73\u5747\u4f01\u4e1a\u6269\u5927\u96c7\u4f63\u548c\u751f\u4ea7\uff0c\u51cf\u5c11\u52b3\u52a8\u529b\u6298\u6263\uff0c\u4e14\u5229\u6da6\u672a\u4e0b\u964d\u3002\u66f4\u9ad8\u7684\u52b3\u52a8\u529b\u6210\u672c\u4e3b\u8981\u901a\u8fc7\u4ef7\u683c\u4e0a\u6da8\u8f6c\u5ac1\u7ed9\u6d88\u8d39\u8005\uff0c\u5176\u4f59\u90e8\u5206\u5219\u901a\u8fc7\u751f\u4ea7\u7387\u63d0\u5347\u5f97\u5230\u62b5\u6d88\u3002\u5de5\u4eba\u7684\u5de5\u8d44\u548c\u5c31\u4e1a\u5747\u6709\u6240\u63d0\u9ad8\u3002\u8fd9\u4e9b\u6a21\u5f0f\u8868\u660e\uff0c\u5de5\u4f1a\u53ef\u4ee5\u62b5\u6d88\u96c7\u4e3b\u7684\u5784\u65ad\u4e70\u65b9\u6743\u529b\uff0c\u800c\u4f01\u4e1a\u7684\u53cd\u5e94\u2014\u2014\u5373\u6700\u7ec8\u8c01\u627f\u62c5\u6210\u672c\u2014\u2014\u5728\u5f88\u5927\u7a0b\u5ea6\u4e0a\u53d6\u51b3\u4e8e\u5e02\u573a\u7ed3\u6784\u3002\u603b\u4f53\u800c\u8a00\uff0c\u5728\u8fd9\u4e00\u60c5\u5883\u4e0b\uff0c\u5de5\u4f1a\u5316\u4e3b\u8981\u4ece\u6d88\u8d39\u8005\u5411\u80a1\u4e1c\u8fdb\u884c\u518d\u5206\u914d\uff0c\u4e14\u5bf9\u4f01\u4e1a\u7684\u5f71\u54cd\u5b58\u5728\u663e\u8457\u5dee\u5f02\uff0c\u5305\u62ec\u5411\u89c4\u6a21\u66f4\u5927\u3001\u751f\u4ea7\u7387\u66f4\u9ad8\u7684\u4f01\u4e1a\u503e\u659c\u3002\u6211\u4eec\u901a\u8fc7\u4e00\u4e2a\u4ea7\u54c1\u5e02\u573a\u548c\u52b3\u52a8\u529b\u5e02\u573a\u6743\u529b\u7684\u5c40\u90e8\u5747\u8861\u5de5\u4f1a\u8c08\u5224\u6a21\u578b\u6765\u89e3\u91ca\u8fd9\u4e9b\u6a21\u5f0f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag061", "journal": "RFS", "title": "Too Good to Be True: Look-Ahead Bias in Empirical Options Research", "authors": ["Jefferson Duarte", "Christopher S Jones", "Mehdi Khorram", "Haitao Mo", "Junbo L Wang"], "author_details": [{"name": "Jefferson Duarte", "affiliations": ["Jesse H. Jones School of Business, Rice University ,"]}, {"name": "Christopher S Jones", "affiliations": ["Marshall School of Business, University of Southern California ,"]}, {"name": "Mehdi Khorram", "affiliations": ["Ivy College of Business, Iowa State University ,"]}, {"name": "Haitao Mo", "affiliations": ["School of Business, University of Kansas ,"]}, {"name": "Junbo L Wang", "affiliations": ["Ourso College of Business, Louisiana State University ,"]}], "abstract": "Abstract Numerous trading strategies examined in options research exhibit remarkably high mean returns and Sharpe ratios. We show some of these seemingly \u201cgood deals\u201d are due to look-ahead biases. These biases stem from using information unavailable at the portfolio formation time to filter out observations suspected of being noisy or erroneous. Our results suggest that elevated Sharpe ratios may serve as potential indicators of such look-ahead biases. Furthermore, deviating from previous literature findings, we show that illiquidity is not strongly priced in stock options and that only a small set of stock characteristics are in fact associated with option expected returns.", "date": "2026-06-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag061", "title_zh": "\u592a\u597d\u4ee5\u81f3\u4e8e\u4e0d\u771f\u5b9e\uff1a\u5b9e\u8bc1\u671f\u6743\u7814\u7a76\u4e2d\u7684\u524d\u77bb\u504f\u89c1", "abstract_zh": "\u6458\u8981 \u591a\u4e2a\u5728\u671f\u6743\u7814\u7a76\u4e2d\u88ab\u68c0\u9a8c\u7684\u4ea4\u6613\u7b56\u7565\u8868\u73b0\u51fa\u5f02\u5e38\u9ad8\u7684\u5e73\u5747\u6536\u76ca\u7387\u548c\u590f\u666e\u6bd4\u7387\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u4e00\u4e9b\u770b\u4f3c\u201c\u7edd\u4f73\u673a\u4f1a\u201d\u7684\u7b56\u7565\u5b9e\u9645\u4e0a\u6e90\u4e8e\u524d\u77bb\u504f\u89c1\u3002\u8fd9\u79cd\u504f\u89c1\u6765\u81ea\u4e8e\u5728\u7ec4\u5408\u5f62\u6210\u65f6\u95f4\u70b9\u4e4b\u524d\u65e0\u6cd5\u83b7\u53d6\u7684\u4fe1\u606f\uff0c\u7528\u4e8e\u7b5b\u9009\u90a3\u4e9b\u53ef\u80fd\u542b\u6709\u566a\u58f0\u6216\u9519\u8bef\u7684\u89c2\u6d4b\u6570\u636e\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u8f83\u9ad8\u7684\u590f\u666e\u6bd4\u7387\u53ef\u80fd\u6210\u4e3a\u8bc6\u522b\u6b64\u7c7b\u524d\u77bb\u504f\u89c1\u7684\u6f5c\u5728\u6307\u6807\u3002\u6b64\u5916\uff0c\u4e0e\u4ee5\u5f80\u6587\u732e\u53d1\u73b0\u4e0d\u540c\uff0c\u6211\u4eec\u8868\u660e\u6d41\u52a8\u6027\u5728\u80a1\u7968\u671f\u6743\u4e2d\u5e76\u672a\u88ab\u663e\u8457\u5b9a\u4ef7\uff0c\u4e14\u5b9e\u9645\u4e0a\u53ea\u6709\u5c11\u6570\u80a1\u7968\u7279\u5f81\u4e0e\u671f\u6743\u9884\u671f\u6536\u76ca\u7387\u76f8\u5173\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhag060", "journal": "RFS", "title": "Emission Caps and Investment in Green Technologies", "authors": ["Bruno Biais", "Augustin Landier"], "author_details": [{"name": "Bruno Biais", "affiliations": ["HEC Paris ,"]}, {"name": "Augustin Landier", "affiliations": ["HEC Paris ,"]}], "abstract": "Abstract We study the interaction between firms, which can invest in green technologies, and a government, which can impose emission caps but has limited commitment power. Investment in green technologies generates innovation spillovers, reducing the cost of further investments. Spillovers generate intertemporal strategic complementarities between firms and government, and equilibrium multiplicity. In a \u201cgreen equilibrium\u201d, firms, anticipating caps, invest in green technologies, which reduces the cost of further investment, making the government willing to cap emissions. In a \u201cbrown equilibrium\u201d, firms, anticipating no caps, don\u2019t invest, so green technologies remain costly and the government gives up on emission caps.", "date": "2026-06-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag060", "title_zh": "\u6392\u653e\u4e0a\u9650\u4e0e\u7eff\u8272\u6280\u672f\u6295\u8d44", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u53ef\u4ee5\u6295\u8d44\u7eff\u8272\u6280\u672f\u7684\u4f01\u4e1a\u4e0e\u53ef\u4ee5\u5b9e\u65bd\u6392\u653e\u4e0a\u9650\u4f46\u627f\u8bfa\u80fd\u529b\u6709\u9650\u7684\u653f\u5e9c\u4e4b\u95f4\u7684\u4e92\u52a8\u3002\u7eff\u8272\u6280\u672f\u6295\u8d44\u4f1a\u4ea7\u751f\u521b\u65b0\u6ea2\u51fa\u6548\u5e94\uff0c\u964d\u4f4e\u540e\u7eed\u6295\u8d44\u7684\u6210\u672c\u3002\u6ea2\u51fa\u6548\u5e94\u5728\u4f01\u4e1a\u548c\u653f\u5e9c\u4e4b\u95f4\u4ea7\u751f\u8de8\u65f6\u671f\u7684\u6218\u7565\u4e92\u8865\u6027\uff0c\u5e76\u5bfc\u81f4\u5747\u8861\u7684\u591a\u91cd\u6027\u3002\u5728\u201c\u7eff\u8272\u5747\u8861\u201d\u4e2d\uff0c\u4f01\u4e1a\u9884\u89c1\u5230\u6392\u653e\u4e0a\u9650\u7684\u5b58\u5728\uff0c\u56e0\u800c\u6295\u8d44\u4e8e\u7eff\u8272\u6280\u672f\uff0c\u8fd9\u964d\u4f4e\u4e86\u540e\u7eed\u6295\u8d44\u7684\u6210\u672c\uff0c\u4f7f\u653f\u5e9c\u613f\u610f\u5b9e\u65bd\u6392\u653e\u4e0a\u9650\u3002\u5728\u201c\u68d5\u8272\u5747\u8861\u201d\u4e2d\uff0c\u4f01\u4e1a\u9884\u89c1\u5230\u6ca1\u6709\u6392\u653e\u4e0a\u9650\uff0c\u56e0\u800c\u4e0d\u8fdb\u884c\u6295\u8d44\uff0c\u5bfc\u81f4\u7eff\u8272\u6280\u672f\u6210\u672c\u5c45\u9ad8\u4e0d\u4e0b\uff0c\u653f\u5e9c\u6700\u7ec8\u653e\u5f03\u5b9e\u65bd\u6392\u653e\u4e0a\u9650\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag068", "journal": "REStud", "title": "Skill-Replacing Technology and Bottom-Half Inequality", "authors": ["Oren Danieli"], "author_details": [{"name": "Oren Danieli", "affiliations": ["Tel Aviv University, CEPR and IZA ,"]}], "abstract": "Abstract I propose a model of skill-replacing routine-biased technological change (SR-RBTC). In this model, technology substitutes for the use of skill in routine tasks, in contrast to standard RBTC models, which assume that technology replaces the workers themselves. The SR-RBTC model explains three key trends that are inconsistent with standard RBTC models: (1) why specifically middle wages declined even though workers in routine occupations are dispersed across the entire bottom half of the wage distribution, (2) why middle wages stopped declining while technological change continued, and (3) why there is no substantial decline in the average wage of workers in routine occupations. I derive two new testable predictions from the model: a decrease in the return to skill and a decrease in skill level in routine occupations. I use an interactive fixed-effects model to confirm both predictions. Since SR-RBTC violates the ignorability assumption required by standard decomposition methods, I introduce a \u201cskewness decomposition\u201d to show that SR-RBTC is the main driver of bottom-half inequality trends.", "date": "2026-06-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag068", "title_zh": "\u6280\u80fd\u66ff\u4ee3\u6280\u672f\u4e0e\u5e95\u5c42\u4e0d\u5e73\u7b49", "abstract_zh": "\u6211\u63d0\u51fa\u4e86\u4e00\u79cd\u6280\u80fd\u66ff\u4ee3\u578b\u4f8b\u884c\u504f\u5411\u6280\u672f\u53d8\u9769\uff08SR-RBTC\uff09\u7684\u6a21\u578b\u3002\u5728\u8be5\u6a21\u578b\u4e2d\uff0c\u6280\u672f\u66ff\u4ee3\u7684\u662f\u6280\u80fd\u5728\u4f8b\u884c\u4efb\u52a1\u4e2d\u7684\u4f7f\u7528\uff0c\u4e0e\u6807\u51c6\u7684\u4f8b\u884c\u504f\u5411\u6280\u672f\u53d8\u9769\uff08RBTC\uff09\u6a21\u578b\u5047\u8bbe\u6280\u672f\u66ff\u4ee3\u5de5\u4eba\u672c\u8eab\u4e0d\u540c\u3002SR-RBTC\u6a21\u578b\u89e3\u91ca\u4e86\u4e09\u4e2a\u4e0e\u6807\u51c6RBTC\u6a21\u578b\u4e0d\u4e00\u81f4\u7684\u5173\u952e\u8d8b\u52bf\uff1a\uff081\uff09\u4e3a\u4ec0\u4e48\u4e2d\u7b49\u5de5\u8d44\u6c34\u5e73\u4e0b\u964d\uff0c\u5c3d\u7ba1\u4f8b\u884c\u804c\u4e1a\u5de5\u4eba\u7684\u5de5\u8d44\u5206\u5e03\u5728\u5e95\u5c42\u4e00\u534a\u7684\u5de5\u8d44\u5206\u5e03\u4e2d\uff1b\uff082\uff09\u4e3a\u4ec0\u4e48\u5728\u6280\u672f\u53d8\u9769\u6301\u7eed\u7684\u60c5\u51b5\u4e0b\uff0c\u4e2d\u7b49\u5de5\u8d44\u505c\u6b62\u4e0b\u964d\uff1b\uff083\uff09\u4e3a\u4ec0\u4e48\u4f8b\u884c\u804c\u4e1a\u5de5\u4eba\u7684\u5e73\u5747\u5de5\u8d44\u6ca1\u6709\u663e\u8457\u4e0b\u964d\u3002\u6211\u4ece\u8be5\u6a21\u578b\u4e2d\u63a8\u5bfc\u51fa\u4e24\u4e2a\u53ef\u68c0\u9a8c\u7684\u9884\u6d4b\uff1a\u4f8b\u884c\u804c\u4e1a\u4e2d\u6280\u80fd\u7684\u56de\u62a5\u4e0b\u964d\u4ee5\u53ca\u4f8b\u884c\u804c\u4e1a\u4e2d\u6280\u80fd\u6c34\u5e73\u7684\u4e0b\u964d\u3002\u6211\u4f7f\u7528\u4ea4\u4e92\u56fa\u5b9a\u6548\u5e94\u6a21\u578b\u9a8c\u8bc1\u4e86\u8fd9\u4e24\u4e2a\u9884\u6d4b\u3002\u7531\u4e8eSR-RBTC\u8fdd\u53cd\u4e86\u6807\u51c6\u5206\u89e3\u65b9\u6cd5\u6240\u8981\u6c42\u7684\u53ef\u5ffd\u7565\u6027\u5047\u8bbe\uff0c\u6211\u5f15\u5165\u4e86\u4e00\u79cd\u201c\u504f\u5ea6\u5206\u89e3\u201d\u65b9\u6cd5\uff0c\u4ee5\u8868\u660eSR-RBTC\u662f\u5e95\u5c42\u4e0d\u5e73\u7b49\u8d8b\u52bf\u7684\u4e3b\u8981\u9a71\u52a8\u56e0\u7d20\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag059", "journal": "RFS", "title": "Mutual Fund Flows at Long Horizons", "authors": ["Hendrik Bessembinder", "Shuaiyu Chen", "Michael J Cooper", "Jinming Xue", "Feng Zhang"], "author_details": [{"name": "Hendrik Bessembinder", "affiliations": ["W. P. Carey School of Business, Arizona State University ,"]}, {"name": "Shuaiyu Chen", "affiliations": ["Darden School of Business, University of Virginia ,"]}, {"name": "Michael J Cooper", "affiliations": ["David Eccles School of Business, University of Utah ,"]}, {"name": "Jinming Xue", "affiliations": ["Cox School of Business, Southern Methodist University ,"]}, {"name": "Feng Zhang", "affiliations": ["Cox School of Business, Southern Methodist University ,"]}], "abstract": "Abstract We show that positive flows to active mutual funds with high recent returns partially reverse at longer horizons. This outcome is robust across a broad range of alternative specifications. Reversal occurs from greater outflows associated with high prior returns, not reduced inflows. We test theories to explain the reversal: investment life cycles, tax loss selling, and a behavioral \u201cdisappointment\u201d hypothesis based on investors\u2019 overreaction to positive returns. While both tax loss selling and short investor life cycles can contribute, the evidence supports a role for investor disappointment, whereby investors redeem their capital when return performance fails to meet expectations.", "date": "2026-06-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag059", "title_zh": "\u957f\u671f\u89c6\u89d2\u4e0b\u7684\u5171\u540c\u57fa\u91d1\u6d41\u52a8\u60c5\u51b5", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u5bf9\u8fd1\u671f\u8868\u73b0\u4f18\u5f02\u7684\u4e3b\u52a8\u578b\u5171\u540c\u57fa\u91d1\u7684\u6b63\u5411\u8d44\u91d1\u6d41\u5165\uff0c\u5728\u66f4\u957f\u7684\u65f6\u95f4\u8303\u56f4\u5185\u4f1a\u90e8\u5206\u9006\u8f6c\u3002\u8fd9\u4e00\u7ed3\u679c\u5728\u591a\u79cd\u4e0d\u540c\u8bbe\u5b9a\u4e0b\u5747\u5177\u6709\u7a33\u5065\u6027\u3002\u8fd9\u79cd\u9006\u8f6c\u6e90\u4e8e\u4e0e\u9ad8\u524d\u671f\u56de\u62a5\u76f8\u5173\u8054\u7684\u66f4\u5927\u6d41\u51fa\uff0c\u800c\u975e\u6d41\u5165\u51cf\u5c11\u3002\u6211\u4eec\u68c0\u9a8c\u4e86\u591a\u79cd\u7406\u8bba\u6765\u89e3\u91ca\u8fd9\u79cd\u9006\u8f6c\u73b0\u8c61\uff1a\u6295\u8d44\u751f\u547d\u5468\u671f\u7406\u8bba\u3001\u7a0e\u52a1\u4e8f\u635f\u51fa\u552e\u7406\u8bba\uff0c\u4ee5\u53ca\u57fa\u4e8e\u6295\u8d44\u8005\u5bf9\u6b63\u5411\u56de\u62a5\u8fc7\u5ea6\u53cd\u5e94\u7684\u201c\u5931\u671b\u201d\u884c\u4e3a\u7406\u8bba\u3002\u867d\u7136\u7a0e\u52a1\u4e8f\u635f\u51fa\u552e\u548c\u77ed\u671f\u6295\u8d44\u8005\u751f\u547d\u5468\u671f\u7406\u8bba\u53ef\u80fd\u8d77\u5230\u4e00\u5b9a\u4f5c\u7528\uff0c\u4f46\u8bc1\u636e\u66f4\u652f\u6301\u6295\u8d44\u8005\u5931\u671b\u7406\u8bba\uff0c\u5373\u5f53\u5b9e\u9645\u56de\u62a5\u672a\u80fd\u8fbe\u5230\u6295\u8d44\u8005\u9884\u671f\u65f6\uff0c\u6295\u8d44\u8005\u4f1a\u8d4e\u56de\u5176\u8d44\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005", "\u8d44\u672c\u6d41\u52a8"]}, {"doi": "10.1017/s002210902610310x", "journal": "JFQA", "title": "Securing Debt in the Knowledge Economy: Evidence from Intellectual Property Registers", "authors": ["Laurie Ciaramella", "David Heller", "Leo Leitzinger"], "author_details": [{"name": "Laurie Ciaramella", "affiliations": ["CREST\u2014Institut Polytechnique de Paris and Max Planck Institute for Innovation and Competition"]}, {"name": "David Heller", "affiliations": ["Politecnico di Milano and Max Planck Institute for Innovation and Competition"]}, {"name": "Leo Leitzinger", "affiliations": ["Goethe University Frankfurt"]}], "abstract": "Abstract This study examines the role of intellectual property (IP) rights as loan collateral in debt financing. We use novel data from French IP registers combined with firm-level financial information to systematically document the characteristics of IP-backed loans and IP-pledging firms. Exploiting a major reform of French security law as a quasi-natural experiment, our analysis shows that IP collateral facilitates access to debt financing in knowledge-based economies, particularly for small, intangible-intensive private firms. We further provide evidence that trademarks and patents can be meaningful components of collateral packages and that the legal framework plays a central role in shaping their use.", "date": "2026-06-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s002210902610310x", "title_zh": "\u77e5\u8bc6\u7ecf\u6d4e\u4e2d\u7684\u503a\u52a1\u4fdd\u969c\uff1a\u6765\u81ea\u77e5\u8bc6\u4ea7\u6743\u767b\u8bb0\u7684\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u77e5\u8bc6\u4ea7\u6743\uff08IP\uff09\u6743\u5229\u4f5c\u4e3a\u8d37\u6b3e\u62b5\u62bc\u54c1\u5728\u503a\u52a1\u878d\u8d44\u4e2d\u7684\u4f5c\u7528\u3002\u6211\u4eec\u5229\u7528\u6765\u81ea\u6cd5\u56fd\u77e5\u8bc6\u4ea7\u6743\u767b\u8bb0\u7684\u65b0\u578b\u6570\u636e\uff0c\u5e76\u7ed3\u5408\u4f01\u4e1a\u5c42\u9762\u7684\u8d22\u52a1\u4fe1\u606f\uff0c\u7cfb\u7edf\u5730\u8bb0\u5f55\u4e86\u4ee5\u77e5\u8bc6\u4ea7\u6743\u4e3a\u62b5\u62bc\u7684\u8d37\u6b3e\u4ee5\u53ca\u8d28\u62bc\u77e5\u8bc6\u4ea7\u6743\u4f01\u4e1a\u7684\u7279\u5f81\u3002\u5229\u7528\u6cd5\u56fd\u8bc1\u5238\u6cd5\u7684\u4e00\u9879\u91cd\u5927\u6539\u9769\u4f5c\u4e3a\u51c6\u81ea\u7136\u5b9e\u9a8c\uff0c\u6211\u4eec\u7684\u5206\u6790\u8868\u660e\uff0c\u77e5\u8bc6\u4ea7\u6743\u62b5\u62bc\u6709\u52a9\u4e8e\u77e5\u8bc6\u578b\u7ecf\u6d4e\u4f53\u4e2d\u4f01\u4e1a\uff0c\u7279\u522b\u662f\u5c0f\u578b\u3001\u65e0\u5f62\u8d44\u4ea7\u5bc6\u96c6\u7684\u79c1\u8425\u4f01\u4e1a\u83b7\u53d6\u503a\u52a1\u878d\u8d44\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u63d0\u4f9b\u4e86\u8bc1\u636e\uff0c\u8868\u660e\u5546\u6807\u548c\u4e13\u5229\u53ef\u4ee5\u4f5c\u4e3a\u62b5\u62bc\u54c1\u7ec4\u5408\u4e2d\u7684\u91cd\u8981\u7ec4\u6210\u90e8\u5206\uff0c\u5e76\u4e14\u6cd5\u5f8b\u6846\u67b6\u5728\u5851\u9020\u5176\u4f7f\u7528\u4e2d\u8d77\u7740\u6838\u5fc3\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026103123", "journal": "JFQA", "title": "Unlocking ESG Premium from Options", "authors": ["Jie (Jay) Cao", "Amit Goyal", "Xintong (Eunice) Zhan", "Weiming (Elaine) Zhang"], "author_details": [{"name": "Jie (Jay) Cao", "affiliations": ["Hong Kong Polytechnic University"]}, {"name": "Amit Goyal", "affiliations": ["University of Lausanne, Swiss Finance Institute"]}, {"name": "Xintong (Eunice) Zhan", "affiliations": ["Fudan University School of Management"]}, {"name": "Weiming (Elaine) Zhang", "affiliations": ["Hong Kong Baptist University School of Business"]}], "abstract": "Abstract We find that option expensiveness, measured by delta-hedged option returns, is higher for low-ESG stocks, indicating that investors pay a premium in the options market to hedge against ESG-related uncertainty. We estimate that this ESG premium is about 0.2% for 50 days. All three components of ESG contribute to option pricing. We find that investors pay the ESG premium to hedge against jump risks, but not volatility risks. The effect of ESG performance is more prominent during periods when attention to ESG is higher and for firms that are more subject to ESG-related risks.", "date": "2026-06-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103123", "title_zh": "\u4ece\u671f\u6743\u4e2d\u91ca\u653eESG\u6ea2\u4ef7", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u4ee5delta\u5bf9\u51b2\u671f\u6743\u56de\u62a5\u8861\u91cf\u7684\u671f\u6743\u6210\u672c\uff0c\u5bf9\u4e8e\u4f4eESG\u8bc4\u7ea7\u7684\u80a1\u7968\u66f4\u9ad8\uff0c\u8868\u660e\u6295\u8d44\u8005\u4e3a\u4e86\u5bf9\u51b2\u4e0eESG\u76f8\u5173\u7684\u4e0d\u786e\u5b9a\u6027\uff0c\u5728\u671f\u6743\u5e02\u573a\u652f\u4ed8\u4e86\u6ea2\u4ef7\u3002\u6211\u4eec\u4f30\u8ba1\uff0c\u8fd9\u4e00ESG\u6ea2\u4ef7\u7ea6\u4e3a50\u5929\u76840.2%\u3002ESG\u7684\u4e09\u4e2a\u7ec4\u6210\u90e8\u5206\u5747\u5bf9\u671f\u6743\u5b9a\u4ef7\u4ea7\u751f\u5f71\u54cd\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u6295\u8d44\u8005\u652f\u4ed8ESG\u6ea2\u4ef7\u662f\u4e3a\u4e86\u5bf9\u51b2\u8df3\u8dc3\u98ce\u9669\uff0c\u800c\u975e\u6ce2\u52a8\u7387\u98ce\u9669\u3002ESG\u8868\u73b0\u7684\u5f71\u54cd\u5728ESG\u5173\u6ce8\u5ea6\u8f83\u9ad8\u7684\u65f6\u671f\u4ee5\u53ca\u5bf9ESG\u76f8\u5173\u98ce\u9669\u66f4\u654f\u611f\u7684\u516c\u53f8\u4e2d\u66f4\u4e3a\u663e\u8457\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1111/jofi.70058", "journal": "JF", "title": "Twin Defaults and Bank Capital Requirements", "authors": ["CATERINA MENDICINO", "KALIN NIKOLOV", "JUAN RUBIO\u2010RAMIREZ", "JAVIER SUAREZ", "DOMINIK SUPERA"], "author_details": [{"name": "CATERINA MENDICINO", "affiliations": []}, {"name": "KALIN NIKOLOV", "affiliations": []}, {"name": "JUAN RUBIO\u2010RAMIREZ", "affiliations": []}, {"name": "JAVIER SUAREZ", "affiliations": []}, {"name": "DOMINIK SUPERA", "affiliations": []}], "abstract": "ABSTRACT We examine optimal capital requirements in a quantitative general equilibrium model with banks exposed to nondiversifiable borrower default risk. Contrary to standard models of bank default risk, our framework captures the limited upside, but significant downside risk of loan portfolio returns. This helps to reproduce the frequency and severity of twin defaults : simultaneously high firm and bank defaults. Hence, the optimal bank capital requirement, which trades off a lower frequency of twin defaults against restricting credit provision, is higher than under default risk models which underestimate the impact of borrower default on bank solvency.", "date": "2026-06-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70058", "title_zh": "\u53cc\u91cd\u8fdd\u7ea6\u4e0e\u94f6\u884c\u8d44\u672c\u8981\u6c42", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5728\u4e00\u4e2a\u5305\u542b\u94f6\u884c\u9762\u4e34\u4e0d\u53ef\u5206\u6563\u501f\u6b3e\u4eba\u8fdd\u7ea6\u98ce\u9669\u7684\u91cf\u5316\u4e00\u822c\u5747\u8861\u6a21\u578b\u4e2d\uff0c\u7814\u7a76\u6700\u4f18\u8d44\u672c\u8981\u6c42\u3002\u4e0e\u6807\u51c6\u7684\u94f6\u884c\u8fdd\u7ea6\u98ce\u9669\u6a21\u578b\u4e0d\u540c\uff0c\u6211\u4eec\u7684\u6846\u67b6\u6355\u6349\u4e86\u8d37\u6b3e\u7ec4\u5408\u56de\u62a5\u7684\u6709\u9650\u4e0a\u884c\u7a7a\u95f4\u4f46\u663e\u8457\u4e0b\u884c\u98ce\u9669\u3002\u8fd9\u6709\u52a9\u4e8e\u518d\u73b0\u53cc\u91cd\u8fdd\u7ea6\u7684\u9891\u7387\u548c\u4e25\u91cd\u6027\uff1a\u5373\u4f01\u4e1a\u4e0e\u94f6\u884c\u540c\u65f6\u8fdd\u7ea6\u7684\u73b0\u8c61\u3002\u56e0\u6b64\uff0c\u6700\u4f18\u94f6\u884c\u8d44\u672c\u8981\u6c42\u2014\u2014\u5728\u964d\u4f4e\u53cc\u91cd\u8fdd\u7ea6\u9891\u7387\u4e0e\u9650\u5236\u4fe1\u8d37\u4f9b\u7ed9\u4e4b\u95f4\u8fdb\u884c\u6743\u8861\u2014\u2014\u9ad8\u4e8e\u90a3\u4e9b\u4f4e\u4f30\u501f\u6b3e\u4eba\u8fdd\u7ea6\u5bf9\u94f6\u884c\u507f\u4ed8\u80fd\u529b\u5f71\u54cd\u7684\u8fdd\u7ea6\u98ce\u9669\u6a21\u578b\u6240\u63d0\u51fa\u7684\u6c34\u5e73\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1017/s0022109026103147", "journal": "JFQA", "title": "Measuring the Cost of Regulation: A Text-Based Approach", "authors": ["Charles W. Calomiris", "Harry Mamaysky", "Ruoke Yang"], "author_details": [{"name": "Charles W. Calomiris", "affiliations": ["Andersen Institute for Finance and Economics and National Bureau of Economic Research (NBER)"]}, {"name": "Harry Mamaysky", "affiliations": ["Columbia University Business School"]}, {"name": "Ruoke Yang", "affiliations": ["U.S. Securities and Exchange Commission"]}], "abstract": "Abstract We derive a measure of firm-level regulatory exposure from corporate earnings calls text and study its effects on growth, leverage, profitability, and equity returns. Higher regulatory exposure results in slower sales and asset growth, lower leverage, reduced profitability, and higher post-call equity returns. Most of these effects are mitigated for larger firms. We validate our measure by showing its explanatory power for cross-sectional stock returns during the 2016 Presidential election.", "date": "2026-06-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103147", "title_zh": "\u901a\u8fc7\u6587\u672c\u65b9\u6cd5\u8861\u91cf\u76d1\u7ba1\u6210\u672c", "abstract_zh": "\u6211\u4eec\u4ece\u4f01\u4e1a\u8d22\u62a5\u7535\u8bdd\u4f1a\u8bae\u6587\u672c\u4e2d\u63a8\u5bfc\u51fa\u4f01\u4e1a\u5c42\u9762\u7684\u76d1\u7ba1\u66b4\u9732\u5ea6\u91cf\uff0c\u5e76\u7814\u7a76\u5176\u5bf9\u589e\u957f\u3001\u6760\u6746\u7387\u3001\u76c8\u5229\u80fd\u529b\u4ee5\u53ca\u80a1\u6743\u56de\u62a5\u7684\u5f71\u54cd\u3002\u76d1\u7ba1\u66b4\u9732\u8d8a\u9ad8\uff0c\u9500\u552e\u548c\u8d44\u4ea7\u589e\u957f\u8d8a\u6162\uff0c\u6760\u6746\u7387\u8d8a\u4f4e\uff0c\u76c8\u5229\u80fd\u529b\u4e0b\u964d\uff0c\u7535\u8bdd\u4f1a\u8bae\u540e\u7684\u80a1\u6743\u56de\u62a5\u7387\u8d8a\u9ad8\u3002\u8fd9\u4e9b\u6548\u5e94\u5728\u5927\u578b\u4f01\u4e1a\u4e2d\u5f97\u5230\u4e86\u5f88\u5927\u7a0b\u5ea6\u7684\u7f13\u89e3\u3002\u6211\u4eec\u901a\u8fc7\u5c55\u793a\u8be5\u5ea6\u91cf\u57282016\u5e74\u603b\u7edf\u9009\u4e3e\u671f\u95f4\u6a2a\u622a\u9762\u80a1\u7968\u56de\u62a5\u4e2d\u7684\u89e3\u91ca\u529b\uff0c\u9a8c\u8bc1\u4e86\u5176\u6709\u6548\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag063", "journal": "REStud", "title": "Insurer Risk and Public Risk-Sharing: Quantifying the Value of Reinsurance", "authors": ["Paul H S Kim", "Anran Li"], "author_details": [{"name": "Paul H S Kim", "affiliations": ["Department of Economics, Michigan State University ,"]}, {"name": "Anran Li", "affiliations": ["Department of Economics, University of Minnesota\u2014Twin Cities and NBER ,"]}], "abstract": "Abstract We study the role of public risk-sharing in markets where firms face substantial cost uncertainty, focusing on public reinsurance in health insurance. We develop a model where insurers internalize cost uncertainty through risk charges that raise effective marginal costs and create a role for reinsurance. Public reinsurance lowers both expected costs and cost volatility, particularly for smaller insurers, reducing prices and enhancing competition. Using an event study of staggered state-level reinsurance programs, we show that public reinsurance leads insurers to lower prices and private reinsurance purchases, benefiting financially constrained insurers the most. Structural estimates indicate that risk charges account for a substantial share of the premium-cost wedge and highlight public reinsurance\u2019s comparative advantage over premium subsidies by providing risk protection and enhancing competition. Our results underscore the importance of accounting for firms\u2019 risk exposure in policy design and provide a general framework for understanding public risk-sharing policies.", "date": "2026-06-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag063", "title_zh": "\u4fdd\u9669\u98ce\u9669\u4e0e\u516c\u5171\u98ce\u9669\u5206\u62c5\uff1a\u518d\u4fdd\u9669\u4ef7\u503c\u7684\u91cf\u5316", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4f01\u4e1a\u5728\u9762\u4e34\u91cd\u5927\u6210\u672c\u4e0d\u786e\u5b9a\u6027\u65f6\uff0c\u516c\u5171\u98ce\u9669\u5206\u62c5\u5728\u5e02\u573a\u4e2d\u7684\u4f5c\u7528\uff0c\u91cd\u70b9\u63a2\u8ba8\u5065\u5eb7\u4fdd\u9669\u9886\u57df\u4e2d\u7684\u516c\u5171\u518d\u4fdd\u9669\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6a21\u578b\uff0c\u5176\u4e2d\u4fdd\u9669\u516c\u53f8\u901a\u8fc7\u98ce\u9669\u8d39\u7528\u5185\u90e8\u5316\u6210\u672c\u4e0d\u786e\u5b9a\u6027\uff0c\u63d0\u9ad8\u4e86\u6709\u6548\u8fb9\u9645\u6210\u672c\uff0c\u4ece\u800c\u4e3a\u518d\u4fdd\u9669\u521b\u9020\u4e86\u89d2\u8272\u3002\u516c\u5171\u518d\u4fdd\u9669\u80fd\u591f\u964d\u4f4e\u9884\u671f\u6210\u672c\u548c\u6210\u672c\u6ce2\u52a8\u6027\uff0c\u5c24\u5176\u5bf9\u89c4\u6a21\u8f83\u5c0f\u7684\u4fdd\u9669\u516c\u53f8\u800c\u8a00\uff0c\u8fd9\u6709\u52a9\u4e8e\u964d\u4f4e\u4ef7\u683c\u5e76\u63d0\u5347\u7ade\u4e89\u3002\u57fa\u4e8e\u5bf9\u5206\u9636\u6bb5\u5b9e\u65bd\u7684\u5dde\u7ea7\u516c\u5171\u518d\u4fdd\u9669\u8ba1\u5212\u7684\u4e8b\u4ef6\u7814\u7a76\uff0c\u6211\u4eec\u53d1\u73b0\u516c\u5171\u518d\u4fdd\u9669\u5bfc\u81f4\u4fdd\u9669\u516c\u53f8\u964d\u4f4e\u4ef7\u683c\u548c\u79c1\u4eba\u518d\u4fdd\u9669\u8d2d\u4e70\uff0c\u5bf9\u8d22\u52a1\u53d7\u9650\u7684\u4fdd\u9669\u516c\u53f8\u76ca\u5904\u6700\u5927\u3002\u7ed3\u6784\u4f30\u8ba1\u8868\u660e\uff0c\u98ce\u9669\u8d39\u7528\u5360\u4fdd\u8d39\u4e0e\u6210\u672c\u5dee\u989d\u7684\u76f8\u5f53\u5927\u6bd4\u4f8b\uff0c\u51f8\u663e\u4e86\u516c\u5171\u518d\u4fdd\u9669\u76f8\u8f83\u4e8e\u4fdd\u8d39\u8865\u8d34\u7684\u6bd4\u8f83\u4f18\u52bf\uff0c\u5373\u63d0\u4f9b\u98ce\u9669\u4fdd\u62a4\u5e76\u589e\u5f3a\u7ade\u4e89\u3002\u6211\u4eec\u7684\u7ed3\u679c\u5f3a\u8c03\u4e86\u5728\u653f\u7b56\u8bbe\u8ba1\u4e2d\u8003\u8651\u4f01\u4e1a\u98ce\u9669\u66b4\u9732\u7684\u91cd\u8981\u6027\uff0c\u5e76\u4e3a\u7406\u89e3\u516c\u5171\u98ce\u9669\u5206\u62c5\u653f\u7b56\u63d0\u4f9b\u4e86\u901a\u7528\u6846\u67b6\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag031", "journal": "QJE", "title": "What Jobs Come to Mind? Stereotypes About Fields of Study", "authors": ["John J Conlon", "Dev Patel"], "author_details": [{"name": "John J Conlon", "affiliations": ["The Ohio State University ,"]}, {"name": "Dev Patel", "affiliations": ["Brown University ,"]}], "abstract": "Abstract We test for stereotyping\u2014the exaggeration of representative traits\u2014in a high-stakes economic environment. Using surveys administered among undergraduates at the Ohio State University as well as large-scale nationally representative data, we measure how U.S. first-year students perceive the relationship between college majors and occupations. We show that students greatly overestimate the likelihood that majors lead to their representative jobs (e.g., counselor for psychology, journalist for journalism). Using an implicit association test, we show that students associate majors with their representative careers and that these associations strongly predict belief biases, in line with a stereotyping mechanism. A simple equilibrium model of the labor market predicts that stereotyping reduces welfare by increasing misallocation, which we corroborate with correlational evidence on job/major mismatch. In a field experiment, we test a light-touch policy to reduce stereotyping and find significant effects on students\u2019 intentions about what to study as well as the classes and majors they enroll in.", "date": "2026-06-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag031", "title_zh": "\u4ec0\u4e48\u5de5\u4f5c\u4f1a\u6d6e\u73b0\u5728\u8111\u6d77\u4e2d\uff1f\u5173\u4e8e\u4e13\u4e1a\u9886\u57df\u7684\u523b\u677f\u5370\u8c61", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u68c0\u9a8c\u4e86\u523b\u677f\u5370\u8c61\u2014\u2014\u5373\u5bf9\u4ee3\u8868\u6027\u7279\u5f81\u7684\u5938\u5927\u2014\u2014\u5728\u9ad8\u98ce\u9669\u7ecf\u6d4e\u73af\u5883\u4e2d\u7684\u8868\u73b0\u3002\u5229\u7528\u5728\u4fc4\u4ea5\u4fc4\u5dde\u7acb\u5927\u5b66\u672c\u79d1\u751f\u4e2d\u8fdb\u884c\u7684\u8c03\u67e5\u4ee5\u53ca\u5927\u89c4\u6a21\u5168\u56fd\u4ee3\u8868\u6027\u6570\u636e\uff0c\u6211\u4eec\u6d4b\u91cf\u4e86\u7f8e\u56fd\u5927\u4e00\u5b66\u751f\u5bf9\u5927\u5b66\u4e13\u4e1a\u4e0e\u804c\u4e1a\u4e4b\u95f4\u5173\u7cfb\u7684\u611f\u77e5\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5b66\u751f\u4e25\u91cd\u9ad8\u4f30\u4e86\u4e13\u4e1a\u4e0e\u5176\u4ee3\u8868\u6027\u804c\u4e1a\u4e4b\u95f4\u7684\u5173\u8054\u6982\u7387\uff08\u4f8b\u5982\uff0c\u5fc3\u7406\u5b66\u4e13\u4e1a\u4f1a\u6210\u4e3a\u54a8\u8be2\u5e08\uff0c\u65b0\u95fb\u4e13\u4e1a\u4f1a\u6210\u4e3a\u8bb0\u8005\uff09\u3002\u901a\u8fc7\u9690\u6027\u8054\u60f3\u6d4b\u8bd5\uff0c\u6211\u4eec\u53d1\u73b0\u5b66\u751f\u5c06\u4e13\u4e1a\u4e0e\u4ee3\u8868\u6027\u804c\u4e1a\u76f8\u8054\u7cfb\uff0c\u4e14\u8fd9\u79cd\u5173\u8054\u5f3a\u70c8\u9884\u6d4b\u4e86\u4fe1\u5ff5\u504f\u5dee\uff0c\u7b26\u5408\u523b\u677f\u5370\u8c61\u673a\u5236\u7684\u89e3\u91ca\u3002\u4e00\u4e2a\u7b80\u5355\u7684\u52b3\u52a8\u529b\u5e02\u573a\u5747\u8861\u6a21\u578b\u8868\u660e\uff0c\u523b\u677f\u5370\u8c61\u4f1a\u901a\u8fc7\u589e\u52a0\u8d44\u6e90\u914d\u7f6e\u9519\u8bef\u800c\u964d\u4f4e\u798f\u5229\uff0c\u6211\u4eec\u901a\u8fc7\u804c\u4e1a\u4e0e\u4e13\u4e1a\u5339\u914d\u7684\u5173\u8054\u6027\u8bc1\u636e\u9a8c\u8bc1\u4e86\u8fd9\u4e00\u70b9\u3002\u5728\u4e00\u9879\u5b9e\u5730\u5b9e\u9a8c\u4e2d\uff0c\u6211\u4eec\u6d4b\u8bd5\u4e86\u4e00\u79cd\u8f7b\u5ea6\u5e72\u9884\u653f\u7b56\u4ee5\u51cf\u5c11\u523b\u677f\u5370\u8c61\uff0c\u53d1\u73b0\u8be5\u653f\u7b56\u663e\u8457\u5f71\u54cd\u4e86\u5b66\u751f\u5bf9\u6240\u5b66\u4e13\u4e1a\u7684\u610f\u5411\uff0c\u4ee5\u53ca\u4ed6\u4eec\u9009\u62e9\u7684\u8bfe\u7a0b\u548c\u4e13\u4e1a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag065", "journal": "REStud", "title": "School Choice and the Housing Market", "authors": ["Aram Grigoryan"], "author_details": [{"name": "Aram Grigoryan", "affiliations": ["UC San Diego ,"]}], "abstract": "Abstract I develop a unified theoretical framework with schools and residential choices to study the welfare consequences of public schools\u2019 switching from the traditional neighbourhood assignment to the deferred acceptance mechanism. I find that when families receive higher priorities at neighbourhood schools, the deferred acceptance mechanism creates higher aggregate or utilitarian welfare than neighbourhood assignment. Under a common school ranking assumption, I also show that the deferred acceptance creates higher aggregate welfare with neighbourhood priorities than without them.", "date": "2026-06-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag065", "title_zh": "\u5b66\u6821\u9009\u62e9\u4e0e\u623f\u5730\u4ea7\u5e02\u573a", "abstract_zh": "\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u7edf\u4e00\u7684\u7406\u8bba\u6846\u67b6\uff0c\u5c06\u5b66\u6821\u9009\u62e9\u4e0e\u4f4f\u5b85\u9009\u62e9\u7ed3\u5408\u8d77\u6765\uff0c\u7814\u7a76\u516c\u7acb\u5b66\u6821\u4ece\u4f20\u7edf\u7684\u90bb\u91cc\u5206\u914d\u673a\u5236\u8f6c\u5411\u5ef6\u671f\u63a5\u53d7\u673a\u5236\u6240\u5e26\u6765\u7684\u798f\u5229\u5f71\u54cd\u3002\u6211\u53d1\u73b0\uff0c\u5f53\u5bb6\u5ead\u5728\u90bb\u91cc\u5b66\u6821\u83b7\u5f97\u66f4\u9ad8\u4f18\u5148\u7ea7\u65f6\uff0c\u5ef6\u671f\u63a5\u53d7\u673a\u5236\u6240\u521b\u9020\u7684\u603b\u4f53\u6216\u529f\u5229\u4e3b\u4e49\u798f\u5229\u9ad8\u4e8e\u90bb\u91cc\u5206\u914d\u673a\u5236\u3002\u5728\u5047\u8bbe\u5b66\u6821\u6392\u540d\u666e\u904d\u4e00\u81f4\u7684\u60c5\u51b5\u4e0b\uff0c\u6211\u8fd8\u8bc1\u660e\u4e86\uff0c\u5f53\u5b58\u5728\u90bb\u91cc\u4f18\u5148\u7ea7\u65f6\uff0c\u5ef6\u671f\u63a5\u53d7\u673a\u5236\u6240\u521b\u9020\u7684\u603b\u4f53\u798f\u5229\u9ad8\u4e8e\u4e0d\u5b58\u5728\u90bb\u91cc\u4f18\u5148\u7ea7\u7684\u60c5\u51b5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag013", "journal": "RFS", "title": "Can Discount Window Stigma Be Cured? An Experimental Investigation", "authors": ["Olivier Armantier", "Charles Holt"], "author_details": [{"name": "Olivier Armantier", "affiliations": ["Economic Science Institute, Chapman University ,"]}, {"name": "Charles Holt", "affiliations": ["University of Virginia ,"]}], "abstract": "Abstract A core responsibility of the Federal Reserve is to ensure financial stability by acting as the lender of last resort through its Discount Window (DW). The DW, however, has not been effective because its usage is stigmatized. In this paper, we use theory and experiments to study how such stigma can be cured. We find that behavioral inertia makes it difficult to fix a stigmatized DW, but adding a new backstop facility can help mitigate stigma. These results are consistent with the Federal Reserve\u2019s experience.", "date": "2026-06-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag013", "title_zh": "\u6298\u6263\u7a97\u53e3\u504f\u89c1\u80fd\u5426\u88ab\u6cbb\u6108\uff1f\u4e00\u9879\u5b9e\u9a8c\u7814\u7a76", "abstract_zh": "\u6458\u8981 \u7f8e\u56fd\u8054\u90a6\u50a8\u5907\u7cfb\u7edf\u7684\u4e00\u9879\u6838\u5fc3\u804c\u8d23\u662f\u901a\u8fc7\u5176\u6298\u6263\u7a97\u53e3\uff08DW\uff09\u786e\u4fdd\u91d1\u878d\u7a33\u5b9a\uff0c\u5145\u5f53\u6700\u540e\u8d37\u6b3e\u4eba\u3002\u7136\u800c\uff0c\u7531\u4e8e\u5176\u4f7f\u7528\u5b58\u5728\u504f\u89c1\uff0c\u6298\u6263\u7a97\u53e3\u7684\u6548\u679c\u5e76\u4e0d\u7406\u60f3\u3002\u672c\u6587\u7ed3\u5408\u7406\u8bba\u5206\u6790\u548c\u5b9e\u9a8c\u7814\u7a76\uff0c\u63a2\u8ba8\u5982\u4f55\u6d88\u9664\u8fd9\u79cd\u504f\u89c1\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u884c\u4e3a\u60ef\u6027\u4f7f\u5f97\u4fee\u590d\u5e26\u6709\u504f\u89c1\u7684\u6298\u6263\u7a97\u53e3\u53d8\u5f97\u56f0\u96be\uff0c\u4f46\u5f15\u5165\u4e00\u4e2a\u65b0\u7684\u5907\u7528\u8bbe\u65bd\u6709\u52a9\u4e8e\u7f13\u89e3\u504f\u89c1\u3002\u8fd9\u4e9b\u7ed3\u679c\u4e0e\u8054\u90a6\u50a8\u5907\u7cfb\u7edf\u7684\u5b9e\u9645\u7ecf\u9a8c\u76f8\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag032", "journal": "QJE", "title": "Beliefs About the Economy Are Excessively Sensitive to Household-Level Shocks: Evidence from Linked Survey and Administrative Data", "authors": ["Dmitry Taubinsky", "Luigi Butera", "Matteo Saccarola", "Chen Lian"], "author_details": [{"name": "Dmitry Taubinsky", "affiliations": ["University of California, Berkeley, and National Bureau of Economic Research ,"]}, {"name": "Luigi Butera", "affiliations": ["Copenhagen Business School ,"]}, {"name": "Matteo Saccarola", "affiliations": ["University of California, Berkeley ,"]}, {"name": "Chen Lian", "affiliations": ["University of California, Berkeley, and National Bureau of Economic Research ,"]}], "abstract": "Abstract We study how people\u2019s beliefs about the economy covary with household-level events, using a unique link between Danish administrative data and a large-scale survey of consumer expectations. We find that compared to actual inflation, people\u2019s inflation forecasts covary much more strongly (and negatively) with both recently realized household income changes and measures of expected future household income changes. We formally establish that these findings are stark deviations from the Bayesian rational expectations benchmark. Similar results hold for perceptions of past inflation (backcasts), suggesting that imperfect recall is a key mechanism for biased forecasts. Building on this, a series of additional tests, some of which use data on adverse health events, suggests that the forecast biases are at least partly due to affect-cued recall. That is, negative (positive) household-level events cue negative (positive) recollections, which lead to pessimistic (optimistic) forecasts.", "date": "2026-06-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag032", "title_zh": "\u5bf9\u7ecf\u6d4e\u7684\u4fe1\u5ff5\u8fc7\u5ea6\u654f\u611f\u4e8e\u5bb6\u5ead\u5c42\u9762\u7684\u51b2\u51fb\uff1a\u6765\u81ea\u8054\u7ed3\u8c03\u67e5\u4e0e\u884c\u653f\u6570\u636e\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u5229\u7528\u4e39\u9ea6\u884c\u653f\u6570\u636e\u4e0e\u5927\u89c4\u6a21\u6d88\u8d39\u8005\u9884\u671f\u8c03\u67e5\u4e4b\u95f4\u7684\u72ec\u7279\u8054\u7ed3\uff0c\u7814\u7a76\u4eba\u4eec\u5173\u4e8e\u7ecf\u6d4e\u7684\u4fe1\u5ff5\u5982\u4f55\u4e0e\u5bb6\u5ead\u5c42\u9762\u4e8b\u4ef6\u76f8\u5173\u8054\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u4e0e\u5b9e\u9645\u901a\u80c0\u76f8\u6bd4\uff0c\u4eba\u4eec\u7684\u901a\u80c0\u9884\u6d4b\u4e0e\u8fd1\u671f\u5b9e\u73b0\u7684\u5bb6\u5ead\u6536\u5165\u53d8\u5316\u4ee5\u53ca\u5bf9\u672a\u6765\u5bb6\u5ead\u6536\u5165\u53d8\u5316\u7684\u9884\u671f\u53d8\u5316\u4e4b\u95f4\u5177\u6709\u66f4\u5f3a\uff08\u4e14\u4e3a\u8d1f\u5411\uff09\u7684\u76f8\u5173\u6027\u3002\u6211\u4eec\u6b63\u5f0f\u8bc1\u660e\uff0c\u8fd9\u4e9b\u53d1\u73b0\u4e0e\u8d1d\u53f6\u65af\u7406\u6027\u9884\u671f\u57fa\u51c6\u5b58\u5728\u663e\u8457\u504f\u79bb\u3002\u7c7b\u4f3c\u7684\u7ed3\u679c\u4e5f\u9002\u7528\u4e8e\u5bf9\u8fc7\u53bb\u901a\u80c0\u7684\u611f\u77e5\uff08\u56de\u6eaf\u9884\u6d4b\uff09\uff0c\u8fd9\u8868\u660e\u8bb0\u5fc6\u4e0d\u5b8c\u7f8e\u662f\u5bfc\u81f4\u9884\u6d4b\u504f\u5dee\u7684\u5173\u952e\u673a\u5236\u3002\u57fa\u4e8e\u6b64\uff0c\u6211\u4eec\u8fdb\u884c\u4e86\u4e00\u7cfb\u5217\u989d\u5916\u7684\u68c0\u9a8c\uff0c\u5176\u4e2d\u4e00\u4e9b\u4f7f\u7528\u4e86\u5173\u4e8e\u4e0d\u5229\u5065\u5eb7\u4e8b\u4ef6\u7684\u6570\u636e\uff0c\u8868\u660e\u9884\u6d4b\u504f\u5dee\u5728\u5f88\u5927\u7a0b\u5ea6\u4e0a\u6e90\u4e8e\u60c5\u7eea\u89e6\u53d1\u7684\u8bb0\u5fc6\u3002\u4e5f\u5c31\u662f\u8bf4\uff0c\u8d1f\u9762\uff08\u6b63\u9762\uff09\u7684\u5bb6\u5ead\u4e8b\u4ef6\u4f1a\u5f15\u53d1\u8d1f\u9762\uff08\u6b63\u9762\uff09\u7684\u56de\u5fc6\uff0c\u4ece\u800c\u5bfc\u81f4\u60b2\u89c2\uff08\u4e50\u89c2\uff09\u7684\u9884\u6d4b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag056", "journal": "REStud", "title": "Unemployment Insurance, Starting Salaries, and Jobs: Evidence from Multi-state Firms", "authors": ["Gordon B Dahl", "Matthew Knepper"], "author_details": [{"name": "Gordon B Dahl", "affiliations": ["UC San Diego, USA, Norwegian School of Economics, NBER, ifo Institute, CESifo, CEPR, RFBerlin, IZA"]}, {"name": "Matthew Knepper", "affiliations": ["Amazon ,"]}], "abstract": "Abstract We study the labour market effects of permanent 30%\u201364% reductions on unemployment insurance benefits available in seven states. Leveraging linked firm-establishment data, we find that establishments based on reform states experience employment increases that are 0.8%\u20131.3% larger than those of the same firm\u2019s establishments in other states. Using a similar multi-state firm design, starting salaries are 1.2%\u20135.5% lower in reform states and posted salaries for the same job fall by 3.2%\u20133.5%. The negative co-movement of employment and wages after the reform suggests a labour supply shock and mitigates against confounding changes in labour demand driving the results. Our findings are consistent with workers lowering their reservation wages as outside options fall, and employers take advantage of this by offering lower wages and increasing employment.", "date": "2026-06-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag056", "title_zh": "\u5931\u4e1a\u4fdd\u9669\u3001\u8d77\u85aa\u4e0e\u5c31\u4e1a\uff1a\u6765\u81ea\u591a\u5dde\u4f01\u4e1a\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e03\u4e2a\u5dde\u6c38\u4e45\u6027\u964d\u4f4e\u5931\u4e1a\u4fdd\u9669\u798f\u5229\u5e45\u5ea6\uff0830%\u201364%\uff09\u5bf9\u52b3\u52a8\u529b\u5e02\u573a\u7684\u5f71\u54cd\u3002\u5229\u7528\u5173\u8054\u7684\u516c\u53f8\u8bbe\u7acb\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u4f4d\u4e8e\u6539\u9769\u5dde\u7684\u516c\u53f8\u5c31\u4e1a\u589e\u957f\u5e45\u5ea6\u6bd4\u540c\u4e00\u516c\u53f8\u5728\u5176\u4ed6\u5dde\u7684\u5206\u652f\u673a\u6784\u9ad8\u51fa0.8%\u20131.3%\u3002\u91c7\u7528\u7c7b\u4f3c\u7684\u591a\u5dde\u4f01\u4e1a\u8bbe\u8ba1\uff0c\u6539\u9769\u5dde\u7684\u8d77\u85aa\u6bd4\u5176\u4ed6\u5dde\u4f4e1.2%\u20135.5%\uff0c\u76f8\u540c\u804c\u4f4d\u7684\u6302\u724c\u85aa\u8d44\u4e0b\u964d3.2%\u20133.5%\u3002\u6539\u9769\u540e\u5c31\u4e1a\u4e0e\u5de5\u8d44\u7684\u8d1f\u5411\u8054\u52a8\u8868\u660e\u5b58\u5728\u52b3\u52a8\u529b\u4f9b\u7ed9\u51b2\u51fb\uff0c\u4ece\u800c\u6392\u9664\u4e86\u52b3\u52a8\u529b\u9700\u6c42\u53d8\u5316\u5bfc\u81f4\u7ed3\u679c\u7684\u53ef\u80fd\u3002\u6211\u4eec\u7684\u53d1\u73b0\u4e0e\u5de5\u4eba\u56e0\u5916\u90e8\u9009\u62e9\u51cf\u5c11\u800c\u964d\u4f4e\u5176\u4fdd\u7559\u5de5\u8d44\uff0c\u4ee5\u53ca\u96c7\u4e3b\u501f\u6b64\u63d0\u4f9b\u66f4\u4f4e\u85aa\u8d44\u5e76\u589e\u52a0\u5c31\u4e1a\u7684\u60c5\u51b5\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag062", "journal": "REStud", "title": "Competitive Advertising and Pricing", "authors": ["Ilwoo Hwang", "Kyungmin Kim", "Raphael Boleslavsky"], "author_details": [{"name": "Ilwoo Hwang", "affiliations": ["Department of Economics, Seoul National University, Republic of Korea"]}, {"name": "Kyungmin Kim", "affiliations": ["Department of Economics, Emory University ,"]}, {"name": "Raphael Boleslavsky", "affiliations": ["Kelley School of Business, Indiana University ,"]}], "abstract": "Abstract We consider an oligopoly model in which each firm chooses not only its price but also its advertising strategy regarding how much, and what, product information to provide. To highlight firms\u2019 strategic incentives, we impose no structural restrictions on feasible advertising content, so that each firm can disclose or conceal any information. We obtain a comprehensive characterization of the equilibrium advertising strategy and provide some sufficient conditions for the existence of symmetric pure-price equilibria. We show that intense competition induces firms to provide accurate product information; firms usually obfuscate consumers\u2019 relatively low or high values; and requiring firms to provide more product information can reduce social surplus and also be harmful to consumers.", "date": "2026-06-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag062", "title_zh": "\u7ade\u4e89\u6027\u5e7f\u544a\u4e0e\u5b9a\u4ef7", "abstract_zh": "\u6211\u4eec\u8003\u8651\u4e00\u4e2a\u5be1\u5934\u6a21\u578b\uff0c\u5176\u4e2d\u6bcf\u5bb6\u4f01\u4e1a\u4e0d\u4ec5\u9009\u62e9\u4ef7\u683c\uff0c\u8fd8\u9009\u62e9\u5176\u5e7f\u544a\u7b56\u7565\uff0c\u5373\u51b3\u5b9a\u63d0\u4f9b\u591a\u5c11\u4ee5\u53ca\u4f55\u79cd\u4ea7\u54c1\u4fe1\u606f\u3002\u4e3a\u4e86\u7a81\u51fa\u4f01\u4e1a\u7684\u6218\u7565\u6fc0\u52b1\uff0c\u6211\u4eec\u5bf9\u53ef\u884c\u7684\u5e7f\u544a\u5185\u5bb9\u4e0d\u52a0\u4efb\u4f55\u7ed3\u6784\u9650\u5236\uff0c\u4f7f\u5f97\u6bcf\u5bb6\u4f01\u4e1a\u53ef\u4ee5\u62ab\u9732\u6216\u9690\u7792\u4efb\u4f55\u4fe1\u606f\u3002\u6211\u4eec\u5bf9\u5747\u8861\u5e7f\u544a\u7b56\u7565\u8fdb\u884c\u4e86\u5168\u9762\u523b\u753b\uff0c\u5e76\u63d0\u4f9b\u4e86\u5bf9\u79f0\u7eaf\u4ef7\u683c\u5747\u8861\u5b58\u5728\u7684\u5145\u5206\u6761\u4ef6\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u6fc0\u70c8\u7ade\u4e89\u4f1a\u4fc3\u4f7f\u4f01\u4e1a\u63d0\u4f9b\u51c6\u786e\u7684\u4ea7\u54c1\u4fe1\u606f\uff1b\u4f01\u4e1a\u901a\u5e38\u4f1a\u63a9\u76d6\u6d88\u8d39\u8005\u76f8\u5bf9\u8f83\u4f4e\u6216\u8f83\u9ad8\u7684\u4ef7\u503c\uff1b\u800c\u8981\u6c42\u4f01\u4e1a\u63d0\u4f9b\u66f4\u591a\u4ea7\u54c1\u4fe1\u606f\u53ef\u80fd\u4f1a\u51cf\u5c11\u793e\u4f1a\u5269\u4f59\uff0c\u4e5f\u5bf9\u6d88\u8d39\u8005\u4e0d\u5229\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag055", "journal": "RFS", "title": "Green Investing and Political Behavior", "authors": ["Florian Heeb", "Julian F K\u00f6lbel", "Stefano Ramelli", "Anna Vasileva"], "author_details": [{"name": "Florian Heeb", "affiliations": ["Leibniz Institute for Financial Research SAFE, Goethe University Frankfurt, Germany, and ,", "MIT Sloan Frankfurt, Germany, and ,"]}, {"name": "Julian F K\u00f6lbel", "affiliations": ["University of St. Gallen, Swiss Finance Institute , , and ,", "MIT Sloan , , and ,"]}, {"name": "Stefano Ramelli", "affiliations": ["University of St. Gallen and Swiss Finance Institute ,"]}, {"name": "Anna Vasileva", "affiliations": ["University of Zurich ,"]}], "abstract": "Abstract A fundamental concern about green investing is that it may crowd out political support for public policies addressing negative externalities. We examine this concern in a preregistered experiment conducted shortly before a real referendum on a climate law in Switzerland. We find that offering an opportunity to invest in a climate-friendly fund does not reduce individual support for climate regulation, measured by political donations and voting intentions. A replication of the experiment in the United Kingdom yields similar results. Our estimates reject a crowding-out effect, suggesting instead a modest crowding-in effect of green investing on political support for green policies.", "date": "2026-06-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag055", "title_zh": "\u7eff\u8272\u6295\u8d44\u4e0e\u653f\u6cbb\u884c\u4e3a", "abstract_zh": "\u6458\u8981 \u5173\u4e8e\u7eff\u8272\u6295\u8d44\u53ef\u80fd\u6324\u51fa\u5bf9\u89e3\u51b3\u8d1f\u5916\u90e8\u6027\u516c\u5171\u653f\u7b56\u7684\u653f\u6cbb\u652f\u6301\uff0c\u6211\u4eec\u5728\u4e00\u4e2a\u9884\u5148\u6ce8\u518c\u7684\u5b9e\u9a8c\u4e2d\u8fdb\u884c\u4e86\u68c0\u9a8c\uff0c\u8be5\u5b9e\u9a8c\u5728\u745e\u58eb\u4e00\u9879\u5173\u4e8e\u6c14\u5019\u6cd5\u6848\u7684\u771f\u5b9e\u516c\u6295\u4e4b\u524d\u4e0d\u4e45\u5f00\u5c55\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u63d0\u4f9b\u6295\u8d44\u4e8e\u73af\u4fdd\u57fa\u91d1\u7684\u673a\u4f1a\uff0c\u5e76\u4e0d\u4f1a\u964d\u4f4e\u4e2a\u4eba\u5bf9\u6c14\u5019\u76d1\u7ba1\u7684\u652f\u6301\u7a0b\u5ea6\uff0c\u8fd9\u4e00\u652f\u6301\u7a0b\u5ea6\u901a\u8fc7\u653f\u6cbb\u6350\u6b3e\u548c\u6295\u7968\u610f\u5411\u6765\u8861\u91cf\u3002\u5728\u82f1\u56fd\u5bf9\u5b9e\u9a8c\u8fdb\u884c\u7684\u91cd\u590d\u7814\u7a76\u4e5f\u5f97\u51fa\u4e86\u7c7b\u4f3c\u7ed3\u679c\u3002\u6211\u4eec\u7684\u4f30\u8ba1\u7ed3\u679c\u62d2\u7edd\u4e86\u6324\u51fa\u6548\u5e94\u7684\u5b58\u5728\uff0c\u53cd\u800c\u8868\u660e\u7eff\u8272\u6295\u8d44\u5bf9\u7eff\u8272\u653f\u7b56\u7684\u653f\u6cbb\u652f\u6301\u5177\u6709\u5fae\u5f31\u7684\u4fc3\u8fdb\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag064", "journal": "REStud", "title": "Competition in a Spatially Differentiated Product Market with Negotiated Prices", "authors": ["Walter Beckert", "Howard Smith", "Yuya Takahashi"], "author_details": [{"name": "Walter Beckert", "affiliations": ["Birkbeck College, University of London and Institute for Fiscal Studies , UK"]}, {"name": "Howard Smith", "affiliations": ["Department of Economics, Oxford University, CEPR and Institute for Fiscal Studies ,"]}, {"name": "Yuya Takahashi", "affiliations": ["University of Washington-Seattle , USA"]}], "abstract": "Abstract In many markets, buyers make discrete choices between differentiated products and negotiate prices that are specific to the choice. We develop for estimation a model for this class of markets which is consistent with non-cooperative models of bargaining between a buyer and competing sellers. We show that when the buyer\u2019s utility has GEV disturbances, the model has a tractable likelihood function which can be used with transaction-level data giving the selected product and its price. We estimate the model using data from the UK brick industry and use it to measure market power and analyse mergers. We analyse how spatial differentiation and ownership concentration affect the distribution of market power across transactions. In counterfactuals we find that switching from individually negotiated to uniform pricing causes markups, and merger price effects, to increase on average but to decrease for a minority of transactions.", "date": "2026-06-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag064", "title_zh": "\u5728\u5177\u6709\u8c08\u5224\u4ef7\u683c\u7684\u7a7a\u95f4\u5dee\u5f02\u5316\u4ea7\u54c1\u5e02\u573a\u4e2d\u7684\u7ade\u4e89", "abstract_zh": "\u6458\u8981 \u5728\u8bb8\u591a\u5e02\u573a\u4e2d\uff0c\u4e70\u5bb6\u5728\u5dee\u5f02\u5316\u4ea7\u54c1\u4e4b\u95f4\u505a\u51fa\u79bb\u6563\u9009\u62e9\uff0c\u5e76\u4e0e\u7279\u5b9a\u5356\u5bb6\u5c31\u4ef7\u683c\u8fdb\u884c\u8c08\u5224\u3002\u6211\u4eec\u4e3a\u8fd9\u4e00\u7c7b\u5e02\u573a\u6784\u5efa\u4e86\u4e00\u4e2a\u53ef\u4f30\u8ba1\u7684\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u4e0e\u4e70\u65b9\u548c\u7ade\u4e89\u5356\u5bb6\u4e4b\u95f4\u7684\u975e\u5408\u4f5c\u8ba8\u4ef7\u8fd8\u4ef7\u6a21\u578b\u4e00\u81f4\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5f53\u4e70\u65b9\u6548\u7528\u5177\u6709GEV\u6270\u52a8\u65f6\uff0c\u8be5\u6a21\u578b\u5177\u6709\u53ef\u5904\u7406\u7684\u4f3c\u7136\u51fd\u6570\uff0c\u53ef\u7528\u4e8e\u5177\u6709\u6240\u9009\u4ea7\u54c1\u53ca\u5176\u4ef7\u683c\u7684\u4ea4\u6613\u7ea7\u6570\u636e\u3002\u6211\u4eec\u5229\u7528\u82f1\u56fd\u7816\u4e1a\u7684\u6570\u636e\u5bf9\u6a21\u578b\u8fdb\u884c\u4f30\u8ba1\uff0c\u5e76\u7528\u5176\u8861\u91cf\u5e02\u573a\u529b\u91cf\u5e76\u5206\u6790\u5e76\u8d2d\u884c\u4e3a\u3002\u6211\u4eec\u5206\u6790\u4e86\u7a7a\u95f4\u5dee\u5f02\u5316\u548c\u6240\u6709\u6743\u96c6\u4e2d\u5982\u4f55\u5f71\u54cd\u4ea4\u6613\u5c42\u9762\u7684\u5e02\u573a\u529b\u91cf\u5206\u5e03\u3002\u5728\u53cd\u4e8b\u5b9e\u5206\u6790\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\u4ece\u4e2a\u522b\u8c08\u5224\u4ef7\u683c\u8f6c\u5411\u7edf\u4e00\u4ef7\u683c\uff0c\u4f1a\u5bfc\u81f4\u5e73\u5747\u7684\u6ea2\u4ef7\u548c\u5e76\u8d2d\u4ef7\u683c\u6548\u5e94\u4e0a\u5347\uff0c\u4f46\u5bf9\u5c11\u6570\u4ea4\u6613\u800c\u8a00\u5219\u4e0b\u964d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1093/restud/rdag061", "journal": "REStud", "title": "State Capacity as an Organizational Problem", "authors": ["Nicola Mastrorocco", "Edoardo Teso"], "author_details": [{"name": "Nicola Mastrorocco", "affiliations": ["University of Bologna, Italy and CEPR"]}, {"name": "Edoardo Teso", "affiliations": ["Bocconi University, Italy, Kellogg School of Management, Northwestern University, NBER, USA, and CEPR"]}], "abstract": "Abstract We investigate how technologies that reduce the costs of monitoring by central authorities have shaped the historical transition from small patrimonial states to large bureaucratic organizations. Our analysis is based on a novel dataset that traces changes in the organizational structure and geographic presence of the U.S. federal government over the 19th century. To identify causal effects, we develop a new identification strategy that exploits the expansion of the railroad network as a source of variation in the travel time\u2014and thus monitoring costs\u2014between Washington D.C. and other locations. We present three main findings. First, reductions in travel time to Washington D.C. significantly increased the likelihood of federal government presence in a location. Second, this effect is stronger for occupations and tasks characterized by more severe agency problems. Third, decreases in travel time to Washington D.C. are associated with a decline in patrimonial features of the federal government in the location, in line with enhanced monitoring capacity reducing dependence on personal trust and connections.", "date": "2026-06-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag061", "title_zh": "\u56fd\u5bb6\u80fd\u529b\u4f5c\u4e3a\u7ec4\u7ec7\u95ee\u9898", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u51cf\u5c11\u4e2d\u592e\u5f53\u5c40\u76d1\u7763\u6210\u672c\u7684\u6280\u672f\u5982\u4f55\u5851\u9020\u4e86\u4ece\u5c0f\u578b\u4e16\u88ad\u56fd\u5bb6\u5411\u5927\u578b\u5b98\u50da\u7ec4\u7ec7\u8f6c\u53d8\u7684\u5386\u53f2\u8fc7\u7a0b\u3002\u6211\u4eec\u7684\u5206\u6790\u57fa\u4e8e\u4e00\u4e2a\u65b0\u6784\u5efa\u7684\u6570\u636e\u96c6\uff0c\u8be5\u6570\u636e\u96c6\u8ffd\u8e2a\u4e8619\u4e16\u7eaa\u7f8e\u56fd\u8054\u90a6\u653f\u5e9c\u5728\u7ec4\u7ec7\u7ed3\u6784\u548c\u5730\u7406\u5b58\u5728\u65b9\u9762\u7684\u53d8\u5316\u3002\u4e3a\u8bc6\u522b\u56e0\u679c\u6548\u5e94\uff0c\u6211\u4eec\u5f00\u53d1\u4e86\u4e00\u79cd\u65b0\u7684\u8bc6\u522b\u7b56\u7565\uff0c\u5229\u7528\u94c1\u8def\u7f51\u7edc\u7684\u6269\u5c55\u4f5c\u4e3a\u65c5\u884c\u65f6\u95f4\u2014\u2014\u4ece\u800c\u662f\u76d1\u7763\u6210\u672c\u2014\u2014\u53d8\u5316\u7684\u6765\u6e90\uff0c\u6765\u5206\u6790\u534e\u76db\u987f\u7279\u533a\u4e0e\u5176\u4ed6\u5730\u533a\u4e4b\u95f4\u7684\u8ddd\u79bb\u53d8\u5316\u3002\u6211\u4eec\u5f97\u51fa\u4e09\u4e2a\u4e3b\u8981\u53d1\u73b0\u3002\u7b2c\u4e00\uff0c\u5230\u8fbe\u534e\u76db\u987f\u7279\u533a\u7684\u65c5\u884c\u65f6\u95f4\u663e\u8457\u51cf\u5c11\uff0c\u589e\u52a0\u4e86\u8054\u90a6\u653f\u5e9c\u5728\u67d0\u4e00\u5730\u533a\u7684\u5b58\u5728\u53ef\u80fd\u6027\u3002\u7b2c\u4e8c\uff0c\u8fd9\u4e00\u6548\u5e94\u5728\u90a3\u4e9b\u4ee3\u7406\u95ee\u9898\u66f4\u4e3a\u4e25\u91cd\u7684\u804c\u4f4d\u548c\u4efb\u52a1\u4e2d\u66f4\u4e3a\u663e\u8457\u3002\u7b2c\u4e09\uff0c\u5230\u8fbe\u534e\u76db\u987f\u7279\u533a\u7684\u65c5\u884c\u65f6\u95f4\u51cf\u5c11\u4e0e\u8be5\u5730\u533a\u8054\u90a6\u653f\u5e9c\u4e2d\u4e16\u88ad\u7279\u5f81\u7684\u51cf\u5f31\u76f8\u5173\uff0c\u8fd9\u4e0e\u76d1\u7763\u80fd\u529b\u7684\u589e\u5f3a\u51cf\u5c11\u4e86\u5bf9\u4e2a\u4eba\u4fe1\u4efb\u548c\u5173\u7cfb\u7684\u4f9d\u8d56\u76f8\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/restud/rdag060", "journal": "REStud", "title": "Customer Acquisition, Business Dynamism, and Aggregate Growth", "authors": ["Marek Ignaszak", "Petr Sedl\u00e1\u010dek"], "author_details": [{"name": "Marek Ignaszak", "affiliations": ["European Commission, Joint Research Centre , Ispra ,"]}, {"name": "Petr Sedl\u00e1\u010dek", "affiliations": ["University of New South Wales , Sydney ,"]}], "abstract": "Abstract Business dynamism\u2014the process of firm entry, growth and exit\u2014lies at the heart of modern endogenous growth models. While productivity differences have traditionally been seen as the main driving forces of business dynamism, a growing body of evidence suggests that customer acquisition is at least as important. In light of this evidence, we propose a novel endogenous growth model in which innovating firms must first acquire customers to sell their products. Estimating our model with aggregate and firm-level data, we find that expansions of firms\u2019 customer bases (market sizes) boost their incentives to innovate and shift resources towards high-growth businesses (\u201cgazelles\u201d). Combined, these effects explain over 40% of aggregate growth and substantially change predictions about the efficacy of growth policies. Finally, we document support for key model predictions using firm-level micro-data.", "date": "2026-06-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag060", "title_zh": "\u5ba2\u6237\u83b7\u53d6\u3001\u4f01\u4e1a\u6d3b\u529b\u4e0e\u603b\u4f53\u589e\u957f", "abstract_zh": "\u6458\u8981 \u4f01\u4e1a\u6d3b\u529b\u2014\u2014\u5373\u4f01\u4e1a\u8fdb\u5165\u3001\u6210\u957f\u548c\u9000\u51fa\u7684\u8fc7\u7a0b\u2014\u2014\u662f\u73b0\u4ee3\u5185\u751f\u589e\u957f\u6a21\u578b\u7684\u6838\u5fc3\u3002\u5c3d\u7ba1\u4f20\u7edf\u4e0a\u8ba4\u4e3a\u751f\u4ea7\u7387\u5dee\u5f02\u662f\u4f01\u4e1a\u6d3b\u529b\u7684\u4e3b\u8981\u9a71\u52a8\u529b\uff0c\u4f46\u8d8a\u6765\u8d8a\u591a\u7684\u8bc1\u636e\u8868\u660e\uff0c\u5ba2\u6237\u83b7\u53d6\u81f3\u5c11\u540c\u6837\u91cd\u8981\u3002\u57fa\u4e8e\u8fd9\u4e00\u8bc1\u636e\uff0c\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u65b0\u7684\u5185\u751f\u589e\u957f\u6a21\u578b\uff0c\u5728\u8be5\u6a21\u578b\u4e2d\uff0c\u521b\u65b0\u4f01\u4e1a\u5fc5\u987b\u9996\u5148\u83b7\u53d6\u5ba2\u6237\u624d\u80fd\u9500\u552e\u5176\u4ea7\u54c1\u3002\u5229\u7528\u5b8f\u89c2\u548c\u4f01\u4e1a\u5c42\u9762\u7684\u6570\u636e\u5bf9\u6a21\u578b\u8fdb\u884c\u4f30\u8ba1\uff0c\u6211\u4eec\u53d1\u73b0\u4f01\u4e1a\u5ba2\u6237\u57fa\u7840\uff08\u5e02\u573a\u89c4\u6a21\uff09\u7684\u6269\u5f20\u4f1a\u589e\u5f3a\u5176\u521b\u65b0\u52a8\u529b\uff0c\u5e76\u5c06\u8d44\u6e90\u8f6c\u5411\u9ad8\u589e\u957f\u4f01\u4e1a\uff08\u5373\u201c\u72ec\u89d2\u517d\u201d\u4f01\u4e1a\uff09\u3002\u8fd9\u4e9b\u6548\u5e94\u5171\u540c\u89e3\u91ca\u4e86\u8d85\u8fc740%\u7684\u603b\u4f53\u589e\u957f\uff0c\u5e76\u663e\u8457\u6539\u53d8\u4e86\u5173\u4e8e\u589e\u957f\u653f\u7b56\u6709\u6548\u6027\u7684\u9884\u6d4b\u3002\u6700\u540e\uff0c\u6211\u4eec\u5229\u7528\u4f01\u4e1a\u5c42\u9762\u7684\u5fae\u89c2\u6570\u636e\u9a8c\u8bc1\u4e86\u6a21\u578b\u4e2d\u7684\u5173\u952e\u9884\u6d4b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag066", "journal": "REStud", "title": "The Micro and Macro Dynamics of Capital Flows", "authors": ["Felipe Saffie", "Liliana Varela", "Kei-Mu Yi"], "author_details": [{"name": "Felipe Saffie", "affiliations": ["University of Virginia Darden School of Business and NBER ,"]}, {"name": "Liliana Varela", "affiliations": ["London School of Economics and CEPR , UK"]}, {"name": "Kei-Mu Yi", "affiliations": ["Federal Reserve Bank of Dallas, U. of Houston and NBER ,"]}], "abstract": "Abstract We study empirically and theoretically the effects of international financial flows on resource allocation. Using the universe of firms in Hungary, we show that removing capital controls lowers firms\u2019 cost of capital and increases household consumption, with the latter playing a dominant role. The consumption channel leads to reallocation of resources toward high expenditure elasticity activities\u2014such as services\u2014promoting both the expansion of incumbents and firm entry. A multi-sector heterogeneous firm model replicates these dynamics. Our model shows that nonhomotheticity in consumption can quantitatively account for the reallocation of resources towards services and successfully replicates the dynamics of aggregate productivity following episodes of financial openness.", "date": "2026-06-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag066", "title_zh": "\u8d44\u672c\u6d41\u52a8\u7684\u5fae\u89c2\u4e0e\u5b8f\u89c2\u52a8\u6001", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u4ece\u5b9e\u8bc1\u548c\u7406\u8bba\u89d2\u5ea6\u7814\u7a76\u56fd\u9645\u91d1\u878d\u6d41\u52a8\u5bf9\u8d44\u6e90\u914d\u7f6e\u7684\u5f71\u54cd\u3002\u5229\u7528\u5308\u7259\u5229\u6240\u6709\u4f01\u4e1a\u7684\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u53d6\u6d88\u8d44\u672c\u7ba1\u5236\u4f1a\u964d\u4f4e\u4f01\u4e1a\u7684\u8d44\u672c\u6210\u672c\uff0c\u5e76\u63d0\u9ad8\u5bb6\u5ead\u6d88\u8d39\uff0c\u540e\u8005\u8d77\u4e3b\u5bfc\u4f5c\u7528\u3002\u6d88\u8d39\u6e20\u9053\u4fc3\u4f7f\u8d44\u6e90\u5411\u652f\u51fa\u5f39\u6027\u8f83\u9ad8\u7684\u6d3b\u52a8\u2014\u2014\u5982\u670d\u52a1\u4e1a\u2014\u2014\u91cd\u65b0\u914d\u7f6e\uff0c\u4ece\u800c\u63a8\u52a8\u73b0\u6709\u4f01\u4e1a\u7684\u6269\u5f20\u548c\u65b0\u4f01\u4e1a\u7684\u8fdb\u5165\u3002\u4e00\u4e2a\u591a\u90e8\u95e8\u5f02\u8d28\u6027\u4f01\u4e1a\u6a21\u578b\u518d\u73b0\u4e86\u8fd9\u4e9b\u52a8\u6001\u3002\u6211\u4eec\u7684\u6a21\u578b\u8868\u660e\uff0c\u6d88\u8d39\u7684\u975e\u540c\u8d28\u6027\u53ef\u4ee5\u5b9a\u91cf\u89e3\u91ca\u8d44\u6e90\u5411\u670d\u52a1\u4e1a\u7684\u91cd\u65b0\u914d\u7f6e\uff0c\u5e76\u6210\u529f\u518d\u73b0\u4e86\u91d1\u878d\u5f00\u653e\u4e8b\u4ef6\u540e\u6574\u4f53\u751f\u4ea7\u7387\u7684\u52a8\u6001\u53d8\u5316\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u672c\u6d41\u52a8"]}, {"doi": "10.1093/restud/rdag067", "journal": "REStud", "title": "Market Segmentation Through Information", "authors": ["Matthew Elliott", "Andrea Galeotti", "Andrew Koh", "Wenhao Li"], "author_details": [{"name": "Matthew Elliott", "affiliations": ["University of Cambridge ,"]}, {"name": "Andrea Galeotti", "affiliations": ["London Business School ,"]}, {"name": "Andrew Koh", "affiliations": ["Massachusetts Institute of Technology ,"]}, {"name": "Wenhao Li", "affiliations": ["Faculty of Business and Economics, The University of Hong Kong, Pokfulam Road ,"]}], "abstract": "Abstract We explore the power that precise information about consumers\u2019 preferences grants an intermediary in shaping competition. We think of an intermediary as an information designer who chooses what information to reveal to firms, which then compete \u00e0 la Bertrand in a differentiated product market. We analyse the information designs that maximize consumer and producer surplus and uncover systematic differences in how information can be used to intensify or soften competition. Our analysis demonstrates the power that users\u2019 data can endow intermediaries with and speaks directly to current regulatory debates regarding digital marketplaces.", "date": "2026-06-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag067", "title_zh": "\u901a\u8fc7\u4fe1\u606f\u5b9e\u73b0\u5e02\u573a\u7ec6\u5206", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u63a2\u8ba8\u4e86\u5173\u4e8e\u6d88\u8d39\u8005\u504f\u597d\u7684\u7cbe\u786e\u4fe1\u606f\u5982\u4f55\u8d4b\u4e88\u4e2d\u4ecb\u5728\u5851\u9020\u7ade\u4e89\u4e2d\u5f3a\u5927\u7684\u6743\u529b\u3002\u6211\u4eec\u5c06\u4e2d\u4ecb\u89c6\u4e3a\u4e00\u4e2a\u4fe1\u606f\u8bbe\u8ba1\u8005\uff0c\u5176\u9009\u62e9\u5411\u4f01\u4e1a\u62ab\u9732\u4f55\u79cd\u4fe1\u606f\uff0c\u4f01\u4e1a\u968f\u540e\u5728\u5dee\u5f02\u5316\u4ea7\u54c1\u5e02\u573a\u4e2d\u8fdb\u884c\u4f2f\u7279\u5170\u5f0f\u7ade\u4e89\u3002\u6211\u4eec\u5206\u6790\u4e86\u80fd\u591f\u6700\u5927\u5316\u6d88\u8d39\u8005\u548c\u751f\u4ea7\u8005\u5269\u4f59\u7684\u4fe1\u606f\u8bbe\u8ba1\u65b9\u6848\uff0c\u5e76\u63ed\u793a\u4e86\u4fe1\u606f\u5982\u4f55\u7cfb\u7edf\u6027\u5730\u88ab\u7528\u6765\u52a0\u5267\u6216\u7f13\u548c\u7ade\u4e89\u3002\u6211\u4eec\u7684\u5206\u6790\u5c55\u793a\u4e86\u7528\u6237\u6570\u636e\u5982\u4f55\u8d4b\u4e88\u4e2d\u4ecb\u5f3a\u5927\u80fd\u529b\uff0c\u5e76\u76f4\u63a5\u56de\u5e94\u4e86\u5f53\u524d\u5173\u4e8e\u6570\u5b57\u5e02\u573a\u5e73\u53f0\u7684\u76d1\u7ba1\u4e89\u8bae\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70062", "journal": "JF", "title": "Learning to Navigate a New Financial Technology", "authors": ["EMILY BREZA", "MARTIN KANZ", "LEORA KLAPPER"], "author_details": [{"name": "EMILY BREZA", "affiliations": []}, {"name": "MARTIN KANZ", "affiliations": []}, {"name": "LEORA KLAPPER", "affiliations": []}], "abstract": "ABSTRACT We present results from a field experiment that introduced digital payroll accounts to unbanked factory workers to examine how inexperienced consumers learn to use a new financial technology. We find that exposure to payroll accounts leads to increased account use, accelerated learning, and avoidance of common consumer protection risks. Those receiving electronic wage payments gradually build trust in the technology, learn to use accounts without assistance, and avoid illicit fees. Using experimental variation in assignment to bank versus mobile money accounts, we show that these impacts are concentrated in mobile money accounts, the newer, more complex, and less trusted financial technology.", "date": "2026-06-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70062", "title_zh": "\u5b66\u4e60\u4f7f\u7528\u4e00\u79cd\u65b0\u7684\u91d1\u878d\u79d1\u6280", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5f00\u5c55\u4e86\u4e00\u9879\u5b9e\u5730\u5b9e\u9a8c\uff0c\u5c06\u6570\u5b57\u5de5\u8d44\u8d26\u6237\u5f15\u5165\u672a\u88ab\u94f6\u884c\u670d\u52a1\u8986\u76d6\u7684\u5de5\u5382\u5de5\u4eba\u4e2d\uff0c\u4ee5\u7814\u7a76\u7ecf\u9a8c\u4e0d\u8db3\u7684\u6d88\u8d39\u8005\u5982\u4f55\u5b66\u4e60\u4f7f\u7528\u4e00\u79cd\u65b0\u7684\u91d1\u878d\u6280\u672f\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u63a5\u89e6\u5de5\u8d44\u8d26\u6237\u4f1a\u4fc3\u8fdb\u8d26\u6237\u4f7f\u7528\u7387\u7684\u63d0\u5347\u3001\u5b66\u4e60\u901f\u5ea6\u7684\u52a0\u5feb\u4ee5\u53ca\u5bf9\u5e38\u89c1\u6d88\u8d39\u8005\u4fdd\u62a4\u98ce\u9669\u7684\u89c4\u907f\u3002\u63a5\u53d7\u7535\u5b50\u5de5\u8d44\u652f\u4ed8\u7684\u53c2\u4e0e\u8005\u9010\u6e10\u5efa\u7acb\u8d77\u5bf9\u6280\u672f\u7684\u4fe1\u4efb\uff0c\u5b66\u4f1a\u5728\u6ca1\u6709\u5e2e\u52a9\u7684\u60c5\u51b5\u4e0b\u4f7f\u7528\u8d26\u6237\uff0c\u5e76\u907f\u514d\u975e\u6cd5\u8d39\u7528\u3002\u901a\u8fc7\u5b9e\u9a8c\u4e2d\u5bf9\u94f6\u884c\u8d26\u6237\u4e0e\u79fb\u52a8\u652f\u4ed8\u8d26\u6237\u5206\u914d\u7684\u5dee\u5f02\uff0c\u6211\u4eec\u53d1\u73b0\u8fd9\u4e9b\u5f71\u54cd\u4e3b\u8981\u96c6\u4e2d\u5728\u79fb\u52a8\u652f\u4ed8\u8d26\u6237\u4e0a\uff0c\u5373\u8fd9\u79cd\u8f83\u65b0\u3001\u66f4\u590d\u6742\u4e14\u4fe1\u4efb\u5ea6\u8f83\u4f4e\u7684\u91d1\u878d\u6280\u672f\u4e2d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026103093", "journal": "JFQA", "title": "Portfolio Choice with Nonfungible Brokerage Cash", "authors": ["Xindi He", "Ning Zhu"], "author_details": [{"name": "Xindi He", "affiliations": ["Georgia Institute of Technology, Scheller College of Business"]}, {"name": "Ning Zhu", "affiliations": ["Shanghai Jiao Tong University, Shanghai Advanced Institute of Finance (SAIF)"]}], "abstract": "Abstract Standard portfolio-choice models treat cash as fungible. Using positions and transfer records for 46,016 Chinese investors, we show that brokerage cash is nonfungible and that cash-source effects refresh and decay. We label inflows from savings transfers as \u201ccold\u201d and trading-recycled funds as \u201chot\u201d and construct a cash-temperature measure tracking these dynamics. Investors allocate colder cash to safer stocks, controlling for gains and losses, trading intensity, and rebalancing. Quasi-experimental variation from China\u2019s 2016 IPO reform supports a causal interpretation. A preregistered experiment links cold framing to loss aversion; a model with temperature-dependent sensitivity to gains and losses rationalizes the evidence.", "date": "2026-06-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103093", "title_zh": "\u975e\u540c\u8d28\u5316\u5238\u5546\u73b0\u91d1\u4e0b\u7684\u6295\u8d44\u7ec4\u5408\u9009\u62e9", "abstract_zh": "\u6807\u51c6\u7684\u6295\u8d44\u7ec4\u5408\u9009\u62e9\u6a21\u578b\u5c06\u73b0\u91d1\u89c6\u4e3a\u53ef\u66ff\u4ee3\u7684\u3002\u57fa\u4e8e46,016\u540d\u4e2d\u56fd\u6295\u8d44\u8005\u7684\u6301\u4ed3\u548c\u8d44\u91d1\u8f6c\u79fb\u8bb0\u5f55\uff0c\u6211\u4eec\u53d1\u73b0\u5238\u5546\u73b0\u91d1\u662f\u975e\u540c\u8d28\u5316\u7684\uff0c\u5e76\u4e14\u73b0\u91d1\u6765\u6e90\u6548\u5e94\u5177\u6709\u5237\u65b0\u548c\u8870\u51cf\u7684\u8fc7\u7a0b\u3002\u6211\u4eec\u5c06\u6765\u81ea\u50a8\u84c4\u8f6c\u8d26\u7684\u6d41\u5165\u79f0\u4e3a\u201c\u51b7\u201d\u73b0\u91d1\uff0c\u5c06\u6765\u81ea\u4ea4\u6613\u5faa\u73af\u7684\u8d44\u91d1\u79f0\u4e3a\u201c\u70ed\u201d\u73b0\u91d1\uff0c\u5e76\u6784\u5efa\u4e86\u4e00\u4e2a\u8ffd\u8e2a\u8fd9\u4e9b\u52a8\u6001\u7684\u201c\u73b0\u91d1\u6e29\u5ea6\u201d\u6307\u6807\u3002\u5728\u63a7\u5236\u6536\u76ca\u548c\u635f\u5931\u3001\u4ea4\u6613\u9891\u7387\u4ee5\u53ca\u518d\u5e73\u8861\u884c\u4e3a\u7684\u60c5\u51b5\u4e0b\uff0c\u6295\u8d44\u8005\u5c06\u201c\u51b7\u201d\u73b0\u91d1\u5206\u914d\u5230\u66f4\u5b89\u5168\u7684\u80a1\u7968\u4e2d\u3002\u4e2d\u56fd2016\u5e74IPO\u6539\u9769\u5e26\u6765\u7684\u51c6\u5b9e\u9a8c\u6027\u53d8\u5316\u652f\u6301\u4e86\u56e0\u679c\u89e3\u91ca\u3002\u4e00\u9879\u9884\u5148\u6ce8\u518c\u7684\u5b9e\u9a8c\u5c06\u51b7\u6846\u67b6\u4e0e\u635f\u5931\u538c\u6076\u8054\u7cfb\u8d77\u6765\uff1b\u4e00\u4e2a\u5177\u6709\u6e29\u5ea6\u4f9d\u8d56\u6027\u6536\u76ca\u548c\u635f\u5931\u654f\u611f\u6027\u7684\u6a21\u578b\u80fd\u591f\u89e3\u91ca\u8fd9\u4e9b\u8bc1\u636e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag058", "journal": "REStud", "title": "Competing under Information Heterogeneity: Evidence from Auto Insurance", "authors": ["Marco Cosconati", "Yi Xin", "Fan Wu", "Yizhou Jin"], "author_details": [{"name": "Marco Cosconati", "affiliations": ["IVASS and Bank of Italy, Rome ,"]}, {"name": "Yi Xin", "affiliations": ["Division of the Humanities and Social Sciences, California Institute of Technology , Pasadena ,"]}, {"name": "Fan Wu", "affiliations": ["Peking University, Shenzhen HSBC Business School, ,"]}, {"name": "Yizhou Jin", "affiliations": ["Rotman School of Management, University of Toronto Department of Management (UTSC) and , Toronto, Canada Cosconati and Xin are co-first authors, listed alphabetically"]}], "abstract": "Abstract This article studies competition under information heterogeneity in selection markets and examines the impact of public information regulations aimed at reducing information asymmetries between competing firms. We develop a novel model and introduce new empirical strategies to analyse imperfect competition in markets where firms have heterogeneous information about consumers, vary in cost structures, and offer differentiated products. Using data from the Italian auto insurance market, we find substantial differences in the precision of risk ratings across insurers, and those with less accurate risk-rating algorithms tend to have more efficient cost structures. We assess the equilibrium effects of giving firms equal access to aggregated risk information from a centralized bureau. This policy significantly reduces prices by increasing competition, leading to a 15.7% boost in consumer surplus, almost reaching the efficiency benchmark where firms have full knowledge of consumers\u2019 true risk. Aggregating information through the bureau favours low-risk consumers and reduces average costs by 12 euros per contract through more efficient insurer\u2013insuree matching.", "date": "2026-06-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag058", "title_zh": "\u4fe1\u606f\u5f02\u8d28\u6027\u4e0b\u7684\u7ade\u4e89\uff1a\u6765\u81ea\u6c7d\u8f66\u4fdd\u9669\u5e02\u573a\u7684\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5728\u9009\u62e9\u5e02\u573a\u4e2d\u4fe1\u606f\u5f02\u8d28\u6027\u4e0b\u7684\u7ade\u4e89\uff0c\u5e76\u8003\u5bdf\u4e86\u65e8\u5728\u51cf\u5c11\u7ade\u4e89\u4f01\u4e1a\u4e4b\u95f4\u4fe1\u606f\u4e0d\u5bf9\u79f0\u7684\u516c\u5171\u4fe1\u606f\u76d1\u7ba1\u653f\u7b56\u7684\u5f71\u54cd\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u65b0\u9896\u7684\u6a21\u578b\uff0c\u5e76\u5f15\u5165\u4e86\u65b0\u7684\u5b9e\u8bc1\u7b56\u7565\uff0c\u4ee5\u5206\u6790\u4f01\u4e1a\u5728\u62e5\u6709\u6d88\u8d39\u8005\u4fe1\u606f\u5f02\u8d28\u6027\u3001\u6210\u672c\u7ed3\u6784\u4e0d\u540c\u4ee5\u53ca\u63d0\u4f9b\u5dee\u5f02\u5316\u4ea7\u54c1\u7684\u60c5\u51b5\u4e0b\u5b58\u5728\u7684\u4e0d\u5b8c\u5168\u7ade\u4e89\u3002\u5229\u7528\u610f\u5927\u5229\u6c7d\u8f66\u4fdd\u9669\u5e02\u573a\u7684\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u5404\u4fdd\u9669\u516c\u53f8\u7684\u98ce\u9669\u8bc4\u7ea7\u7cbe\u5ea6\u5b58\u5728\u663e\u8457\u5dee\u5f02\uff0c\u90a3\u4e9b\u98ce\u9669\u8bc4\u7ea7\u7b97\u6cd5\u7cbe\u5ea6\u8f83\u4f4e\u7684\u4fdd\u9669\u516c\u53f8\u5f80\u5f80\u5177\u6709\u66f4\u9ad8\u6548\u7684\u6210\u672c\u7ed3\u6784\u3002\u6211\u4eec\u8bc4\u4f30\u4e86\u7ed9\u4e88\u4f01\u4e1a\u5e73\u7b49\u8bbf\u95ee\u7531\u4e2d\u592e\u673a\u6784\u63d0\u4f9b\u7684\u6c47\u603b\u98ce\u9669\u4fe1\u606f\u7684\u5747\u8861\u6548\u5e94\u3002\u8fd9\u4e00\u653f\u7b56\u901a\u8fc7\u589e\u5f3a\u7ade\u4e89\u663e\u8457\u964d\u4f4e\u4e86\u4ef7\u683c\uff0c\u4f7f\u6d88\u8d39\u8005\u5269\u4f59\u63d0\u9ad8\u4e8615.7%\uff0c\u51e0\u4e4e\u8fbe\u5230\u4e86\u4f01\u4e1a\u5b8c\u5168\u638c\u63e1\u6d88\u8d39\u8005\u771f\u5b9e\u98ce\u9669\u7684\u6548\u7387\u57fa\u51c6\u6c34\u5e73\u3002\u901a\u8fc7\u4e2d\u592e\u673a\u6784\u6c47\u603b\u4fe1\u606f\uff0c\u6709\u5229\u4e8e\u4f4e\u98ce\u9669\u6d88\u8d39\u8005\uff0c\u5e76\u901a\u8fc7\u66f4\u9ad8\u6548\u7684\u4fdd\u9669\u516c\u53f8\u4e0e\u6295\u4fdd\u4eba\u5339\u914d\uff0c\u4f7f\u6bcf\u4efd\u5408\u540c\u7684\u5e73\u5747\u6210\u672c\u964d\u4f4e\u4e8612\u6b27\u5143\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag059", "journal": "REStud", "title": "Peer Effects in Consideration and Preferences", "authors": ["Nail Kashaev", "Natalia Lazzati", "Ruli Xiao"], "author_details": [{"name": "Nail Kashaev", "affiliations": ["University of Western Ontario ,"]}, {"name": "Natalia Lazzati", "affiliations": ["University of California, Santa Cruz ,"]}, {"name": "Ruli Xiao", "affiliations": ["Indiana University ,"]}], "abstract": "Abstract We develop a general model of discrete choice that incorporates peer effects in preferences and consideration sets. We characterize the equilibrium behaviour and establish conditions under which all parts of the model can be recovered from a sequence of choices. We allow peers to affect preferences, consideration, or both. We show that these peer-effect mechanisms have different behavioural implications in the data. This allows us to recover the set and the type of connections between the agents in the network. We then use this information to recover each agent\u2019s preferences and consideration mechanisms. These nonparametric identification results allow for general forms of heterogeneity across agents and do not rely on the variation of either exogenous covariates or the set of available options (menus). We apply our results to model expansion decisions by tea chains and find evidence of limited consideration. We simulate counterfactual predictions and show how limited consideration slows market penetration and competition.", "date": "2026-06-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag059", "title_zh": "\u504f\u597d\u4e0e\u9009\u62e9\u96c6\u4e2d\u7684\u540c\u4f34\u6548\u5e94", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u504f\u597d\u548c\u9009\u62e9\u96c6\u540c\u4f34\u6548\u5e94\u7684\u4e00\u822c\u6027\u79bb\u6563\u9009\u62e9\u6a21\u578b\u3002\u6211\u4eec\u523b\u753b\u4e86\u5747\u8861\u884c\u4e3a\uff0c\u5e76\u5efa\u7acb\u4e86\u5728\u4e00\u7cfb\u5217\u9009\u62e9\u5e8f\u5217\u4e0b\u80fd\u591f\u6062\u590d\u6a21\u578b\u6240\u6709\u7ec4\u6210\u90e8\u5206\u7684\u6761\u4ef6\u3002\u6211\u4eec\u5141\u8bb8\u540c\u4f34\u5f71\u54cd\u504f\u597d\u3001\u9009\u62e9\u96c6\uff0c\u6216\u4e24\u8005\u540c\u65f6\u5f71\u54cd\u3002\u6211\u4eec\u8bc1\u660e\u4e86\u8fd9\u4e9b\u540c\u4f34\u6548\u5e94\u673a\u5236\u5728\u6570\u636e\u4e2d\u5177\u6709\u4e0d\u540c\u7684\u884c\u4e3a\u542b\u4e49\uff0c\u4ece\u800c\u80fd\u591f\u6062\u590d\u53c2\u4e0e\u8005\u4e4b\u95f4\u7f51\u7edc\u7684\u8fde\u63a5\u96c6\u5408\u53ca\u5176\u7c7b\u578b\u3002\u968f\u540e\uff0c\u6211\u4eec\u5229\u7528\u8fd9\u4e9b\u4fe1\u606f\u6062\u590d\u6bcf\u4e2a\u53c2\u4e0e\u8005\u7684\u504f\u597d\u548c\u9009\u62e9\u673a\u5236\u3002\u8fd9\u4e9b\u975e\u53c2\u6570\u8bc6\u522b\u7ed3\u679c\u5141\u8bb8\u5728\u4e2a\u4f53\u95f4\u5b58\u5728\u4e00\u822c\u5f62\u5f0f\u7684\u5f02\u8d28\u6027\uff0c\u5e76\u4e14\u4e0d\u4f9d\u8d56\u4e8e\u5916\u751f\u534f\u53d8\u91cf\u7684\u53d8\u5316\u6216\u53ef\u9009\u65b9\u6848\uff08\u83dc\u5355\uff09\u7684\u96c6\u5408\u53d8\u5316\u3002\u6211\u4eec\u5c06\u7ed3\u679c\u5e94\u7528\u4e8e\u8336\u53f6\u8fde\u9501\u4f01\u4e1a\u7684\u6269\u5f20\u51b3\u7b56\uff0c\u53d1\u73b0\u5b58\u5728\u6709\u9650\u7684\u9009\u62e9\u8303\u56f4\u3002\u6211\u4eec\u8fdb\u884c\u4e86\u53cd\u4e8b\u5b9e\u9884\u6d4b\u6a21\u62df\uff0c\u5c55\u793a\u4e86\u6709\u9650\u9009\u62e9\u5982\u4f55\u51cf\u7f13\u5e02\u573a\u6e17\u900f\u548c\u7ade\u4e89\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1017/s0022109026103081", "journal": "JFQA", "title": "Do Banks Overreact to Disaster Risk?", "authors": ["Qianqian Huang", "Feng Jiang", "Yuhai Xuan", "Tao Yuan"], "author_details": [{"name": "Qianqian Huang", "affiliations": ["City University of Hong Kong"]}, {"name": "Feng Jiang", "affiliations": ["University at Buffalo"]}, {"name": "Yuhai Xuan", "affiliations": ["University of California Irvine The Paul Merage School of Business"]}, {"name": "Tao Yuan", "affiliations": ["City University of Macau School of Finance"]}], "abstract": "Abstract We examine how banks respond to natural disasters when borrowers are in proximity to affected areas. We find robust evidence that banks impose significantly higher loan spreads on firms in these areas following a disaster compared to other borrowers. This effect diminishes over time and is stronger for loans with concentrated syndicates, disasters with greater media coverage, and cases in which loan officers are geographically closer to disaster sites. The increased financing costs result in capital constraints for affected firms. Overall, our findings highlight a salience bias in banks\u2019 evaluation of borrowers\u2019 disaster risk, with adverse effects on borrowing firms.", "date": "2026-06-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103081", "title_zh": "\u94f6\u884c\u662f\u5426\u8fc7\u5ea6\u53cd\u5e94\u4e8e\u707e\u96be\u98ce\u9669\uff1f", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5f53\u501f\u6b3e\u4eba\u4f4d\u4e8e\u53d7\u707e\u533a\u57df\u9644\u8fd1\u65f6\uff0c\u94f6\u884c\u5982\u4f55\u5e94\u5bf9\u81ea\u7136\u707e\u5bb3\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u94f6\u884c\u5728\u707e\u96be\u53d1\u751f\u540e\uff0c\u5bf9\u8fd9\u4e9b\u533a\u57df\u5185\u7684\u4f01\u4e1a\u65bd\u52a0\u4e86\u663e\u8457\u66f4\u9ad8\u7684\u8d37\u6b3e\u5229\u5dee\uff0c\u76f8\u6bd4\u5176\u4ed6\u501f\u6b3e\u4eba\u3002\u8fd9\u79cd\u6548\u5e94\u968f\u65f6\u95f4\u63a8\u79fb\u800c\u51cf\u5f31\uff0c\u5e76\u5728\u8d37\u6b3e\u7531\u96c6\u4e2d\u627f\u9500\u56e2\u53d1\u653e\u3001\u707e\u96be\u5a92\u4f53\u62a5\u9053\u66f4\u5e7f\u6cdb\u4ee5\u53ca\u8d37\u6b3e\u7ecf\u529e\u4eba\u5458\u5730\u7406\u4e0a\u66f4\u63a5\u8fd1\u53d7\u707e\u5730\u70b9\u7684\u60c5\u51b5\u4e0b\u66f4\u4e3a\u660e\u663e\u3002\u8fd9\u4e9b\u878d\u8d44\u6210\u672c\u7684\u4e0a\u5347\u5bfc\u81f4\u53d7\u5f71\u54cd\u4f01\u4e1a\u7684\u8d44\u672c\u7ea6\u675f\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u53d1\u73b0\u8868\u660e\u94f6\u884c\u5728\u8bc4\u4f30\u501f\u6b3e\u4eba\u707e\u96be\u98ce\u9669\u65f6\u5b58\u5728\u663e\u8457\u7684\u7a81\u51fa\u6027\u504f\u5dee\uff0c\u5bf9\u501f\u6b3e\u4f01\u4e1a\u4ea7\u751f\u4e86\u4e0d\u5229\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1093/rfs/hhag057", "journal": "RFS", "title": "The Variance Premium and Seasonal Momentum in Option Returns", "authors": ["Steven L Heston", "Christopher S Jones", "Mehdi Khorram", "Shuaiqi Li", "Haitao Mo"], "author_details": [{"name": "Steven L Heston", "affiliations": ["Smith School of Business, University of Maryland ,"]}, {"name": "Christopher S Jones", "affiliations": ["Marshall School of Business, University of Southern California ,"]}, {"name": "Mehdi Khorram", "affiliations": ["Ivy College of Business, Iowa State University ,"]}, {"name": "Shuaiqi Li", "affiliations": ["Department of Economics and Finance, City University of Hong Kong ,"]}, {"name": "Haitao Mo", "affiliations": ["School of Business, University of Kansas ,"]}], "abstract": "Abstract We develop a model-free measure of the variance premium by constructing option portfolios whose returns are highly correlated with realized stock variance. This effectively decomposes returns into realized variance minus implied variance. We apply this decomposition to document a novel quarterly cross-sectional continuation pattern in both realized variance and implied variance of individual stocks. Implied variance underanticipates the seasonality of realized variance, so options that performed well at quarterly lags continue to earn high returns in the future. Quarterly periodicity in realized stock variance only occurs on days with analyst earning revisions, suggesting an informational channel for this pattern.", "date": "2026-06-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag057", "title_zh": "\u65b9\u5dee\u6ea2\u4ef7\u4e0e\u671f\u6743\u56de\u62a5\u4e2d\u7684\u5b63\u8282\u6027\u52a8\u91cf", "abstract_zh": "\u6211\u4eec\u901a\u8fc7\u6784\u5efa\u56de\u62a5\u4e0e\u5b9e\u9645\u80a1\u7968\u6ce2\u52a8\u7387\u9ad8\u5ea6\u76f8\u5173\u7684\u671f\u6743\u7ec4\u5408\uff0c\u5f00\u53d1\u4e86\u4e00\u79cd\u65e0\u6a21\u578b\u7684\u65b9\u5dee\u6ea2\u4ef7\u8861\u91cf\u65b9\u6cd5\u3002\u8be5\u65b9\u6cd5\u6709\u6548\u5730\u5c06\u56de\u62a5\u5206\u89e3\u4e3a\u5b9e\u9645\u6ce2\u52a8\u7387\u51cf\u53bb\u9690\u542b\u6ce2\u52a8\u7387\u3002\u6211\u4eec\u5c06\u8fd9\u4e00\u5206\u89e3\u5e94\u7528\u4e8e\u63ed\u793a\u4e2a\u4f53\u80a1\u7968\u5b9e\u9645\u6ce2\u52a8\u7387\u548c\u9690\u542b\u6ce2\u52a8\u7387\u4e2d\u7684\u4e00\u4e2a\u65b0\u9896\u5b63\u5ea6\u4ea4\u53c9\u622a\u9762\u5ef6\u7eed\u6a21\u5f0f\u3002\u9690\u542b\u6ce2\u52a8\u7387\u4f4e\u4f30\u4e86\u5b9e\u9645\u6ce2\u52a8\u7387\u7684\u5b63\u8282\u6027\uff0c\u56e0\u6b64\u5728\u5b63\u5ea6\u6ede\u540e\u671f\u8868\u73b0\u826f\u597d\u7684\u671f\u6743\u5728\u672a\u6765\u4ecd\u80fd\u83b7\u5f97\u9ad8\u56de\u62a5\u3002\u5b9e\u9645\u80a1\u7968\u6ce2\u52a8\u7387\u4e2d\u7684\u5b63\u5ea6\u5468\u671f\u6027\u4ec5\u51fa\u73b0\u5728\u5206\u6790\u5e08\u4e1a\u7ee9\u4fee\u8ba2\u65e5\uff0c\u8fd9\u8868\u660e\u4e86\u8be5\u6a21\u5f0f\u7684\u4fe1\u606f\u4f20\u5bfc\u6e20\u9053\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag057", "journal": "REStud", "title": "Spatial Implications of Telecommuting", "authors": ["Matthew J Delventhal", "Andrii Parkhomenko"], "author_details": [{"name": "Matthew J Delventhal", "affiliations": ["Cotality and University of Southern California , USA"]}, {"name": "Andrii Parkhomenko", "affiliations": ["University of Southern California ,"]}], "abstract": "Abstract We build a quantitative spatial model in which some workers can substitute on-site effort with work done from home. Ability and propensity to telecommute vary by education and industry. We quantify our framework to match the distribution of jobs and residents across 4,502 U.S. locations. Then, we simulate permanent increases in the attractiveness and productivity of telework that lead to greater adoption of hybrid and fully remote work. To validate our model, we show that our results are positively correlated with local changes in residents, jobs, and housing costs since 2019. The rise of telework results in a rich non-monotonic pattern of reallocations of residents and jobs within and across cities. Workers who can telecommute experience welfare gains, and those who cannot suffer losses. Broader access to jobs reduces wage inequality across residential locations, and heralds a partial reversal in the spatial concentration of talent and spending power known as the \u201cGreat Divergence\u201d.", "date": "2026-06-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag057", "title_zh": "\u8fdc\u7a0b\u529e\u516c\u7684\u7a7a\u95f4\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5b9a\u91cf\u7a7a\u95f4\u6a21\u578b\uff0c\u5176\u4e2d\u90e8\u5206\u5de5\u4eba\u53ef\u4ee5\u5c06\u73b0\u573a\u5de5\u4f5c\u66ff\u6362\u4e3a\u5728\u5bb6\u5de5\u4f5c\u3002\u8fdc\u7a0b\u529e\u516c\u7684\u80fd\u529b\u548c\u503e\u5411\u56e0\u6559\u80b2\u6c34\u5e73\u548c\u884c\u4e1a\u800c\u5f02\u3002\u6211\u4eec\u5bf9\u6a21\u578b\u8fdb\u884c\u4e86\u91cf\u5316\u6821\u51c6\uff0c\u4ee5\u5339\u914d\u7f8e\u56fd4502\u4e2a\u5730\u70b9\u7684\u5c31\u4e1a\u5c97\u4f4d\u548c\u5c45\u6c11\u5206\u5e03\u3002\u7136\u540e\uff0c\u6211\u4eec\u6a21\u62df\u4e86\u8fdc\u7a0b\u5de5\u4f5c\u5438\u5f15\u529b\u548c\u751f\u4ea7\u7387\u6c38\u4e45\u6027\u63d0\u5347\u6240\u5e26\u6765\u7684\u6df7\u5408\u5de5\u4f5c\u548c\u5b8c\u5168\u8fdc\u7a0b\u5de5\u4f5c\u91c7\u7528\u7387\u589e\u52a0\u60c5\u51b5\u3002\u4e3a\u9a8c\u8bc1\u6a21\u578b\uff0c\u6211\u4eec\u53d1\u73b0\u6a21\u578b\u7ed3\u679c\u4e0e2019\u5e74\u4ee5\u6765\u5404\u5730\u533a\u5c45\u6c11\u3001\u5c31\u4e1a\u5c97\u4f4d\u548c\u4f4f\u623f\u6210\u672c\u7684\u53d8\u5316\u5448\u6b63\u76f8\u5173\u3002\u8fdc\u7a0b\u529e\u516c\u5bfc\u81f4\u5c45\u6c11\u548c\u5c31\u4e1a\u5c97\u4f4d\u5728\u57ce\u5e02\u5185\u90e8\u53ca\u57ce\u5e02\u4e4b\u95f4\u7684\u91cd\u65b0\u5206\u914d\u5448\u73b0\u51fa\u4e30\u5bcc\u4e14\u975e\u5355\u8c03\u7684\u6a21\u5f0f\u3002\u80fd\u591f\u8fdc\u7a0b\u529e\u516c\u7684\u5de5\u4eba\u83b7\u5f97\u798f\u5229\uff0c\u800c\u65e0\u6cd5\u8fdc\u7a0b\u529e\u516c\u7684\u5de5\u4eba\u5219\u906d\u53d7\u635f\u5931\u3002\u66f4\u5e7f\u6cdb\u5730\u83b7\u5f97\u5c31\u4e1a\u673a\u4f1a\u51cf\u5c11\u4e86\u4e0d\u540c\u5c45\u4f4f\u5730\u4e4b\u95f4\u7684\u5de5\u8d44\u4e0d\u5e73\u7b49\uff0c\u6807\u5fd7\u7740\u88ab\u79f0\u4e3a\u2018\u5927\u5206\u5316\u2019\u7684\u7a7a\u95f4\u4eba\u624d\u548c\u6d88\u8d39\u80fd\u529b\u96c6\u4e2d\u73b0\u8c61\u7684\u90e8\u5206\u9006\u8f6c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag055", "journal": "REStud", "title": "A Temporary VAT Cut as Unconventional Fiscal Policy", "authors": ["R\u00fcdiger Bachmann", "Benjamin Born", "Olga Goldfayn-Frank", "Georgi Kocharkov", "Ralph Luetticke", "Michael Weber"], "author_details": [{"name": "R\u00fcdiger Bachmann", "affiliations": ["University of Michigan, CEPR, CESifo, ifo Institute, and IZA ,"]}, {"name": "Benjamin Born", "affiliations": ["University of Bonn, CEPR, CESifo, and ifo Institute ,"]}, {"name": "Olga Goldfayn-Frank", "affiliations": ["Deutsche Bundesbank and CEPR ,"]}, {"name": "Georgi Kocharkov", "affiliations": ["Deutsche Bundesbank and European Central Bank ,"]}, {"name": "Ralph Luetticke", "affiliations": ["University of T\u00fcbingen and CEPR ,"]}, {"name": "Michael Weber", "affiliations": ["Purdue University, Daniels School of Business, ESMT Berlin, NBER, and CEPR ,"]}], "abstract": "Abstract We exploit Germany\u2019s temporary three-percentage-point value-added tax (VAT) cut in the second half of 2020 to study the spending response to unconventional fiscal policy. We use survey and scanner data on household consumption expenditures and their perceived pass-through of the tax change into prices, and a HANK model to quantify the effects of this VAT policy. The survey and scanner data show that the temporary VAT reduction led to a relative increase in durable and, to a lesser extent, semi-durable spending for individuals with high perceived pass-through. According to the HANK model, the VAT policy increased total aggregate consumption spending by 4.4% on impact.", "date": "2026-06-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag055", "title_zh": "\u4e34\u65f6\u589e\u503c\u7a0e\u51cf\u514d\u4f5c\u4e3a\u975e\u5e38\u89c4\u8d22\u653f\u653f\u7b56", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u7528\u5fb7\u56fd\u57282020\u5e74\u4e0b\u534a\u5e74\u5b9e\u65bd\u7684\u4e34\u65f6\u4e09\u4e2a\u767e\u5206\u70b9\u589e\u503c\u7a0e\u51cf\u514d\uff0c\u7814\u7a76\u4e86\u975e\u5e38\u89c4\u8d22\u653f\u653f\u7b56\u5bf9\u652f\u51fa\u7684\u53cd\u5e94\u3002\u6211\u4eec\u4f7f\u7528\u5173\u4e8e\u5bb6\u5ead\u6d88\u8d39\u652f\u51fa\u53ca\u5176\u5bf9\u7a0e\u6539\u4ef7\u683c\u4f20\u5bfc\u611f\u77e5\u7684\u8c03\u67e5\u548c\u626b\u63cf\u6570\u636e\uff0c\u5e76\u7ed3\u5408HANK\u6a21\u578b\u91cf\u5316\u4e86\u8fd9\u4e00\u589e\u503c\u7a0e\u653f\u7b56\u7684\u5f71\u54cd\u3002\u8c03\u67e5\u548c\u626b\u63cf\u6570\u636e\u663e\u793a\uff0c\u4e34\u65f6\u589e\u503c\u7a0e\u51cf\u514d\u5bfc\u81f4\u5bf9\u4ef7\u683c\u4f20\u5bfc\u611f\u77e5\u8f83\u9ad8\u7684\u4e2a\u4f53\u5728\u8010\u7528\u6d88\u8d39\u54c1\u548c\u4e00\u5b9a\u7a0b\u5ea6\u4e0a\u5728\u534a\u8010\u7528\u6d88\u8d39\u54c1\u4e0a\u7684\u652f\u51fa\u76f8\u5bf9\u589e\u52a0\u3002\u6839\u636eHANK\u6a21\u578b\uff0c\u8be5\u589e\u503c\u7a0e\u653f\u7b56\u5728\u5b9e\u65bd\u65f6\u4f7f\u603b\u6d88\u8d39\u652f\u51fa\u589e\u52a0\u4e864.4%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s002210902610307x", "journal": "JFQA", "title": "Common Idiosyncratic Quantile Factors and Asset Prices", "authors": ["Jozef Barun\u00edk", "Mat\u011bj Nevrla"], "author_details": [{"name": "Jozef Barun\u00edk", "affiliations": ["Charles University Institute of Economic Studies and The Czech Academy of Sciences Institute of Information Theory and Automation"]}, {"name": "Mat\u011bj Nevrla", "affiliations": ["University of Liverpool Management School and The Czech Academy of Sciences Institute of Information Theory and Automation"]}], "abstract": "Abstract We investigate whether the tails of firm-level idiosyncratic return distributions are driven by common shocks. We use quantile factor analysis to extract such common idiosyncratic quantile factors with asymmetric pricing effects, and we find a significant premium for innovations to the lower-tail factor: high-exposure stocks outperform low-exposure stocks by approximately 7%\u20138% per year. This premium remains significant even when controlling for standard factors, idiosyncratic volatility, and tail-risk measures. The downside factor strengthens when intermediary capital is weak and market liquidity is low, and the associated increase in risk predicts higher aggregate market excess returns.", "date": "2026-06-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s002210902610307x", "title_zh": "\u5171\u540c\u7684\u7279\u8d28\u98ce\u9669\u5206\u4f4d\u6570\u56e0\u5b50\u4e0e\u8d44\u4ea7\u4ef7\u683c", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4f01\u4e1a\u5c42\u9762\u7279\u8d28\u56de\u62a5\u5206\u5e03\u5c3e\u90e8\u662f\u5426\u7531\u5171\u540c\u51b2\u51fb\u9a71\u52a8\u3002\u6211\u4eec\u4f7f\u7528\u5206\u4f4d\u6570\u56e0\u5b50\u5206\u6790\u63d0\u53d6\u5177\u6709\u975e\u5bf9\u79f0\u5b9a\u4ef7\u6548\u5e94\u7684\u5171\u540c\u7279\u8d28\u5206\u4f4d\u6570\u56e0\u5b50\uff0c\u5e76\u53d1\u73b0\u5bf9\u4e0b\u5c3e\u56e0\u5b50\u521b\u65b0\u5b58\u5728\u663e\u8457\u6ea2\u4ef7\uff1a\u9ad8\u66b4\u9732\u80a1\u7968\u6bcf\u5e74\u76f8\u5bf9\u4e8e\u4f4e\u66b4\u9732\u80a1\u7968\u8868\u73b0\u9ad8\u51fa\u7ea67%\u20138%\u3002\u8fd9\u4e00\u6ea2\u4ef7\u5728\u63a7\u5236\u6807\u51c6\u56e0\u5b50\u3001\u7279\u8d28\u6ce2\u52a8\u7387\u548c\u5c3e\u90e8\u98ce\u9669\u5ea6\u91cf\u540e\u4f9d\u7136\u663e\u8457\u3002\u5f53\u4e2d\u95f4\u8d44\u672c\u8584\u5f31\u4e14\u5e02\u573a\u6d41\u52a8\u6027\u8f83\u4f4e\u65f6\uff0c\u4e0b\u884c\u56e0\u5b50\u4f1a\u589e\u5f3a\uff0c\u5176\u4f34\u968f\u7684\u98ce\u9669\u4e0a\u5347\u9884\u6d4b\u4e86\u6574\u4f53\u5e02\u573a\u8d85\u989d\u6536\u76ca\u7684\u589e\u52a0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag054", "journal": "REStud", "title": "Liquidity Traps, Prudential Policies, and International Spillovers", "authors": ["Javier Bianchi", "Louphou Coulibaly"], "author_details": [{"name": "Javier Bianchi", "affiliations": ["Federal Reserve Bank of Minneapolis, United States"]}, {"name": "Louphou Coulibaly", "affiliations": ["University of Wisconsin-Madison and NBER"]}], "abstract": "Abstract We investigate optimal monetary and macroprudential policies in an open economy with aggregate demand externalities and an occasionally binding zero lower bound constraint. Our analysis highlights that the optimal policy balances output stabilization and capital flow management. When macroprudential policy is available, monetary policy stabilizes the output gap. By contrast, when macroprudential policy is not available, monetary policy is used prudentially. However, contrary to a widespread view, raising the interest rate is not necessarily the optimal prudential policy. Finally, we show that international spillovers operate through the world real rate, but macroprudential policies provide insulation from the adverse effects of foreign policies.", "date": "2026-06-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag054", "title_zh": "\u6d41\u52a8\u6027\u9677\u9631\u3001\u5ba1\u614e\u653f\u7b56\u4e0e\u56fd\u9645\u6ea2\u51fa\u6548\u5e94", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u4e2a\u5b58\u5728\u603b\u9700\u6c42\u5916\u90e8\u6027\u4e14\u5076\u5c14\u9762\u4e34\u96f6\u4e0b\u9650\u7ea6\u675f\u7684\u5f00\u653e\u7ecf\u6d4e\u4e2d\u8d27\u5e01\u653f\u7b56\u4e0e\u5b8f\u89c2\u5ba1\u614e\u653f\u7b56\u7684\u6700\u4f18\u7ec4\u5408\u3002\u6211\u4eec\u7684\u5206\u6790\u8868\u660e\uff0c\u6700\u4f18\u653f\u7b56\u5728\u4ea7\u51fa\u7a33\u5b9a\u4e0e\u8d44\u672c\u6d41\u52a8\u7ba1\u7406\u4e4b\u95f4\u53d6\u5f97\u5e73\u8861\u3002\u5f53\u5b58\u5728\u5b8f\u89c2\u5ba1\u614e\u653f\u7b56\u65f6\uff0c\u8d27\u5e01\u653f\u7b56\u7528\u4e8e\u7a33\u5b9a\u4ea7\u51fa\u7f3a\u53e3\u3002\u76f8\u53cd\uff0c\u5f53\u7f3a\u4e4f\u5b8f\u89c2\u5ba1\u614e\u653f\u7b56\u65f6\uff0c\u8d27\u5e01\u653f\u7b56\u88ab\u7528\u4e8e\u5ba1\u614e\u7ba1\u7406\u3002\u7136\u800c\uff0c\u4e0e\u666e\u904d\u89c2\u70b9\u76f8\u53cd\uff0c\u63d0\u9ad8\u5229\u7387\u5e76\u4e0d\u4e00\u5b9a\u662f\u6700\u4f18\u7684\u5ba1\u614e\u653f\u7b56\u3002\u6700\u540e\uff0c\u6211\u4eec\u8bc1\u660e\u56fd\u9645\u6ea2\u51fa\u6548\u5e94\u901a\u8fc7\u5168\u7403\u5b9e\u9645\u5229\u7387\u53d1\u6325\u4f5c\u7528\uff0c\u800c\u5b8f\u89c2\u5ba1\u614e\u653f\u7b56\u80fd\u591f\u62b5\u5fa1\u5916\u56fd\u653f\u7b56\u5e26\u6765\u7684\u4e0d\u5229\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u672c\u6d41\u52a8"]}, {"doi": "10.1111/jofi.70060", "journal": "JF", "title": "The Debt\u2010Equity Spread", "authors": ["HUI CHEN", "ZHIYAO CHEN", "JUN LI"], "author_details": [{"name": "HUI CHEN", "affiliations": []}, {"name": "ZHIYAO CHEN", "affiliations": []}, {"name": "JUN LI", "affiliations": []}], "abstract": "ABSTRACT We propose a measure of the valuation gap between debt and equity\u2014debt\u2010equity spread (DES)\u2014based on the difference between actual and equity\u2010implied credit spreads. DES predicts cross\u2010sectional stock and bond returns in opposite directions. This predictability is unique compared to existing mispricing measures and cannot be explained by exposures to various risk factors. High\u2010DES firms are more likely to issue equity and retire debt, and have more insider equity selling. These findings are consistent with DES capturing relative mispricing between debt and equity, and provide empirical support for the model of partially segmented markets in Greenwood, Hanson, and Liao (2018, Review of Financial Studies 31, 3307\u20133343).", "date": "2026-06-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70060", "title_zh": "\u503a\u52a1\u4e0e\u80a1\u6743\u6ea2\u4ef7", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u8861\u91cf\u503a\u52a1\u4e0e\u80a1\u6743\u4f30\u503c\u5dee\u8ddd\u7684\u6307\u6807\u2014\u2014\u503a\u52a1-\u80a1\u6743\u6ea2\u4ef7\uff08DES\uff09\uff0c\u8be5\u6307\u6807\u57fa\u4e8e\u5b9e\u9645\u4fe1\u7528\u5229\u5dee\u4e0e\u80a1\u6743\u9690\u542b\u4fe1\u7528\u5229\u5dee\u4e4b\u95f4\u7684\u5dee\u5f02\u3002DES\u80fd\u591f\u9884\u6d4b\u80a1\u7968\u548c\u503a\u5238\u7684\u6a2a\u622a\u9762\u56de\u62a5\uff0c\u4e14\u65b9\u5411\u76f8\u53cd\u3002\u8fd9\u79cd\u53ef\u9884\u6d4b\u6027\u5728\u73b0\u6709\u8bef\u5b9a\u4ef7\u6307\u6807\u4e2d\u662f\u72ec\u4e00\u65e0\u4e8c\u7684\uff0c\u4e5f\u65e0\u6cd5\u901a\u8fc7\u5404\u79cd\u98ce\u9669\u56e0\u5b50\u7684\u66b4\u9732\u6765\u89e3\u91ca\u3002\u9ad8DES\u4f01\u4e1a\u66f4\u53ef\u80fd\u53d1\u884c\u80a1\u6743\u5e76\u507f\u8fd8\u503a\u52a1\uff0c\u4e14\u5185\u90e8\u4eba\u80a1\u6743\u51fa\u552e\u884c\u4e3a\u4e5f\u66f4\u9891\u7e41\u3002\u8fd9\u4e9b\u53d1\u73b0\u4e0eDES\u6355\u6349\u503a\u52a1\u4e0e\u80a1\u6743\u4e4b\u95f4\u7684\u76f8\u5bf9\u8bef\u5b9a\u4ef7\u4e00\u81f4\uff0c\u5e76\u4e3aGreenwood\u3001Hanson\u548cLiao\uff082018\u5e74\uff0c\u300a\u91d1\u878d\u7814\u7a76\u8bc4\u8bba\u300b31\u5377\uff0c\u7b2c3307\u20133343\u9875\uff09\u63d0\u51fa\u7684\u90e8\u5206\u5206\u5272\u5e02\u573a\u6a21\u578b\u63d0\u4f9b\u4e86\u5b9e\u8bc1\u652f\u6301\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag024", "journal": "REStud", "title": "Quantifying Supply-Side Climate Policies", "authors": ["Lassi Ahlvik", "J\u00f8rgen Juel Andersen", "Jonas Hveding Hamang", "Torfinn Harding"], "author_details": [{"name": "Lassi Ahlvik", "affiliations": ["University of Helsinki ,"]}, {"name": "J\u00f8rgen Juel Andersen", "affiliations": ["BI Norwegian Business School ,"]}, {"name": "Jonas Hveding Hamang", "affiliations": ["Kristiania University of Applied Sciences ,"]}, {"name": "Torfinn Harding", "affiliations": ["Kristiania University of Applied Sciences ,"]}], "abstract": "Abstract What are the effects of supply-side climate policies in the oil market? We use global company-level data to estimate the impact of 84 reforms of production taxes between 2000 and 2019 on oil production, exploration, and discoveries. We find that higher taxes primarily reduce companies\u2019 exploration expenditures and oil discoveries, and also reduce short-term production of unconventional oil. We then quantify the implications for the oil market using a short- and medium-term dynamic model extending until the end of the century. Imposing a global climate royalty surcharge of 20 percentage points on oil producers reduces average annual emissions from oil by 5\u20137% in the first 5 years, and 9\u201320% in the medium term. If only OECD countries adopt this policy, 47\u201373% of the total emission reductions would be offset by increased production in non-OECD countries in the medium term.", "date": "2026-06-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag024", "title_zh": "\u91cf\u5316\u4f9b\u7ed9\u4fa7\u6c14\u5019\u653f\u7b56", "abstract_zh": "\u6458\u8981 \u4f9b\u7ed9\u4fa7\u6c14\u5019\u653f\u7b56\u5bf9\u77f3\u6cb9\u5e02\u573a\u6709\u4f55\u5f71\u54cd\uff1f\u6211\u4eec\u5229\u7528\u5168\u7403\u516c\u53f8\u5c42\u9762\u7684\u6570\u636e\uff0c\u4f30\u8ba1\u4e862000\u5e74\u81f32019\u5e74\u95f484\u9879\u751f\u4ea7\u7a0e\u6539\u9769\u5bf9\u77f3\u6cb9\u751f\u4ea7\u3001\u52d8\u63a2\u548c\u53d1\u73b0\u7684\u5f71\u54cd\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u66f4\u9ad8\u7684\u7a0e\u6536\u4e3b\u8981\u51cf\u5c11\u4e86\u4f01\u4e1a\u7684\u52d8\u63a2\u652f\u51fa\u548c\u77f3\u6cb9\u53d1\u73b0\uff0c\u540c\u65f6\u4e5f\u51cf\u5c11\u4e86\u975e\u5e38\u89c4\u77f3\u6cb9\u7684\u77ed\u671f\u751f\u4ea7\u3002\u968f\u540e\uff0c\u6211\u4eec\u4f7f\u7528\u4e00\u4e2a\u6db5\u76d6\u81f3\u672c\u4e16\u7eaa\u672b\u7684\u77ed\u671f\u548c\u4e2d\u671f\u52a8\u6001\u6a21\u578b\uff0c\u91cf\u5316\u4e86\u8fd9\u4e9b\u653f\u7b56\u5bf9\u77f3\u6cb9\u5e02\u573a\u7684\u5f71\u54cd\u3002\u5bf9\u5168\u7403\u77f3\u6cb9\u751f\u4ea7\u8005\u5f81\u653620\u4e2a\u767e\u5206\u70b9\u7684\u6c14\u5019\u7279\u8bb8\u7a0e\uff0c\u53ef\u5728\u524d\u4e94\u5e74\u5c06\u77f3\u6cb9\u5e73\u5747\u5e74\u6392\u653e\u91cf\u51cf\u5c115\u81f37%\uff0c\u4e2d\u671f\u5219\u51cf\u5c119\u81f320%\u3002\u5982\u679c\u4ec5\u6709\u7ecf\u5408\u7ec4\u7ec7\u56fd\u5bb6\u5b9e\u65bd\u8be5\u653f\u7b56\uff0c\u4e2d\u671f\u65f6\u975e\u7ecf\u5408\u7ec4\u7ec7\u56fd\u5bb6\u7684\u4ea7\u91cf\u589e\u52a0\u5c06\u62b5\u6d88\u603b\u51cf\u6392\u91cf\u768447\u81f373%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70043", "journal": "JF", "title": "Private Equity and Pay Gaps Inside the Firm", "authors": ["LILY FANG", "JIM GOLDMAN", "ALEXANDRA ROULET"], "author_details": [{"name": "LILY FANG", "affiliations": []}, {"name": "JIM GOLDMAN", "affiliations": []}, {"name": "ALEXANDRA ROULET", "affiliations": []}], "abstract": "ABSTRACT Using two decades of French administrative data, we find that post\u2010leveraged buyout (LBO), target firms reduce within\u2010firm pay gaps while increasing profitability relative to control firms. Employee turnover drives the pay\u2010gap reduction. In target and control firms alike, turnovers reduce average pay more at the top of the wage distribution than at the bottom because separated employees are paid more\u2014new joiners less\u2014than similar employees, especially among skilled employees. LBOs amplify this effect through increased turnover among managers. Post\u2010buyout, p90/p10, gender, age, and managers/non\u2010managers pay gaps decline by 3%, 9%, 21%, and 4% and the employee pool becomes younger.", "date": "2026-06-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70043", "title_zh": "\u79c1\u52df\u80a1\u6743\u4e0e\u4f01\u4e1a\u5185\u90e8\u85aa\u916c\u5dee\u8ddd", "abstract_zh": "\u6458\u8981 \u5229\u7528\u4e8c\u5341\u5e74\u6cd5\u56fd\u884c\u653f\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u6760\u6746\u6536\u8d2d\uff08LBO\uff09\u4e4b\u540e\uff0c\u76ee\u6807\u516c\u53f8\u5185\u90e8\u85aa\u916c\u5dee\u8ddd\u7f29\u5c0f\uff0c\u540c\u65f6\u76f8\u5bf9\u4e8e\u63a7\u5236\u516c\u53f8\uff0c\u76c8\u5229\u80fd\u529b\u63d0\u5347\u3002\u5458\u5de5\u6d41\u52a8\u662f\u5bfc\u81f4\u85aa\u916c\u5dee\u8ddd\u7f29\u5c0f\u7684\u539f\u56e0\u3002\u5728\u76ee\u6807\u516c\u53f8\u548c\u63a7\u5236\u516c\u53f8\u4e2d\uff0c\u79bb\u804c\u5458\u5de5\u7684\u5e73\u5747\u85aa\u916c\u5728\u5de5\u8d44\u5206\u5e03\u7684\u9876\u7aef\u6bd4\u4f4e\u7aef\u4e0b\u964d\u66f4\u591a\uff0c\u56e0\u4e3a\u79bb\u804c\u5458\u5de5\u7684\u85aa\u916c\u66f4\u9ad8\uff0c\u800c\u65b0\u5165\u804c\u5458\u5de5\u7684\u85aa\u916c\u66f4\u4f4e\uff0c\u5c24\u5176\u5728\u6280\u80fd\u578b\u5458\u5de5\u4e2d\u66f4\u4e3a\u660e\u663e\u3002\u6760\u6746\u6536\u8d2d\u901a\u8fc7\u589e\u52a0\u7ba1\u7406\u5c42\u7684\u6d41\u52a8\u7387\u653e\u5927\u4e86\u8fd9\u4e00\u6548\u5e94\u3002\u6536\u8d2d\u540e\uff0cp90/p10\u3001\u6027\u522b\u3001\u5e74\u9f84\u4ee5\u53ca\u7ba1\u7406\u5c42\u4e0e\u975e\u7ba1\u7406\u5c42\u4e4b\u95f4\u7684\u85aa\u916c\u5dee\u8ddd\u5206\u522b\u4e0b\u964d3%\u30019%\u300121%\u548c4%\uff0c\u5458\u5de5\u7fa4\u4f53\u4e5f\u53d8\u5f97\u66f4\u52a0\u5e74\u8f7b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1017/s0022109026103056", "journal": "JFQA", "title": "Appointing Charity Directors in Response to ESG Incidents", "authors": ["Marina Gertsberg", "Hae Won (Henny) Jung", "Yuyang Zhang"], "author_details": [{"name": "Marina Gertsberg", "affiliations": ["University of Melbourne Department of Finance"]}, {"name": "Hae Won (Henny) Jung", "affiliations": ["University of Melbourne Department of Finance"]}, {"name": "Yuyang Zhang", "affiliations": ["University of Sydney School of Finance"]}], "abstract": "Abstract This article examines how companies respond to negative ESG incidents by appointing directors with charitable organization experience. Firms are more likely to make these appointments following high-profile ESG incidents, especially those involving social issues. The market reacts positively, particularly when directors\u2019 biographies emphasize their charity experience. Using the local supply of charity directors as an instrumental variable, we show that incidents, particularly workforce-related incidents, decline after these appointments, with effects driven by nonoverboarded directors. Overall, our study documents a value-enhancing human capital channel through which firms address ESG concerns.", "date": "2026-06-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103056", "title_zh": "\u5bf9ESG\u4e8b\u4ef6\u4efb\u547d\u6148\u5584\u7ec4\u7ec7\u9ad8\u7ba1", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u4f01\u4e1a\u5728\u906d\u9047\u8d1f\u9762ESG\u4e8b\u4ef6\u65f6\uff0c\u4efb\u547d\u5177\u6709\u6148\u5584\u7ec4\u7ec7\u7ecf\u9a8c\u7684\u8463\u4e8b\u7684\u884c\u4e3a\u3002\u4f01\u4e1a\u5728\u53d1\u751f\u9ad8\u8c03\u7684ESG\u4e8b\u4ef6\uff0c\u5c24\u5176\u662f\u6d89\u53ca\u793e\u4f1a\u95ee\u9898\u7684\u4e8b\u4ef6\u540e\uff0c\u66f4\u6709\u53ef\u80fd\u505a\u51fa\u6b64\u7c7b\u4efb\u547d\u3002\u5e02\u573a\u5bf9\u6b64\u7c7b\u4efb\u547d\u53cd\u5e94\u79ef\u6781\uff0c\u7279\u522b\u662f\u5f53\u8463\u4e8b\u7684\u5c65\u5386\u7a81\u51fa\u5f3a\u8c03\u5176\u6148\u5584\u7ec4\u7ec7\u7ecf\u9a8c\u65f6\u3002\u6211\u4eec\u5229\u7528\u6148\u5584\u8463\u4e8b\u7684\u672c\u5730\u4f9b\u7ed9\u4f5c\u4e3a\u5de5\u5177\u53d8\u91cf\uff0c\u53d1\u73b0\u8fd9\u4e9b\u4e8b\u4ef6\uff0c\u5c24\u5176\u662f\u4e0e\u52b3\u52a8\u529b\u76f8\u5173\u7684\u95ee\u9898\uff0c\u53d1\u751f\u540e\u4f1a\u6709\u6240\u4e0b\u964d\uff0c\u4e14\u8fd9\u79cd\u6548\u679c\u4e3b\u8981\u7531\u975e\u517c\u4efb\u8463\u4e8b\u9a71\u52a8\u3002\u603b\u4f53\u800c\u8a00\uff0c\u672c\u7814\u7a76\u63ed\u793a\u4e86\u4f01\u4e1a\u901a\u8fc7\u4eba\u529b\u8d44\u672c\u6e20\u9053\u5e94\u5bf9ESG\u95ee\u9898\u6240\u5e26\u6765\u7684\u4ef7\u503c\u63d0\u5347\u673a\u5236\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026103068", "journal": "JFQA", "title": "The Effect of Tax Incentives on Local Private Investments and Entrepreneurship: Evidence from the Tax Cuts and Jobs Act of 2017", "authors": ["Jiajie Xu"], "author_details": [{"name": "Jiajie Xu", "affiliations": ["The University of Iowa Tippie College of Business"]}], "abstract": "Abstract This article examines how place-based tax incentives impact local private investments and entrepreneurship by studying the U.S. Opportunity Zone program targeting economically disadvantaged neighborhoods. Using a difference-in-differences approach across census tracts, I find that while the policy increases investment deals in treated areas by 10.5%, it leads to a 1.8% decline in business formation, particularly in the non-tradable sector where firms compete locally. Opportunity Zone investors prefer older, established firms, which in turn discourages business formation. Furthermore, the decline in entrepreneurship is associated with a 1.7% reduction in local employment and decreased market competition, suggesting negative real economic impact.", "date": "2026-06-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103068", "title_zh": "\u7a0e\u6536\u6fc0\u52b1\u5bf9\u5730\u65b9\u79c1\u4eba\u6295\u8d44\u548c\u521b\u4e1a\u7684\u5f71\u54cd\uff1a\u6765\u81ea2017\u5e74\u51cf\u7a0e\u4e0e\u5c31\u4e1a\u6cd5\u6848\u7684\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u57fa\u4e8e\u5730\u57df\u7684\u7a0e\u6536\u6fc0\u52b1\u5982\u4f55\u5f71\u54cd\u5730\u65b9\u79c1\u4eba\u6295\u8d44\u548c\u521b\u4e1a\uff0c\u4ee5\u7f8e\u56fd\u673a\u4f1a\u533a\u8ba1\u5212\u4e3a\u4f8b\uff0c\u8be5\u8ba1\u5212\u65e8\u5728\u652f\u6301\u7ecf\u6d4e\u6b20\u53d1\u8fbe\u5730\u533a\u3002\u91c7\u7528\u666e\u67e5\u533a\u4e4b\u95f4\u7684\u5dee\u5f02-in-\u5dee\u5f02\u65b9\u6cd5\uff0c\u7814\u7a76\u53d1\u73b0\uff0c\u5c3d\u7ba1\u8be5\u653f\u7b56\u4f7f\u5904\u7406\u533a\u57df\u7684\u6295\u8d44\u4ea4\u6613\u589e\u52a0\u4e8610.5%\uff0c\u4f46\u5728\u975e\u53ef\u4ea4\u6613\u90e8\u95e8\uff08\u4f01\u4e1a\u672c\u5730\u7ade\u4e89\uff09\u4e2d\uff0c\u4f01\u4e1a\u6210\u7acb\u6570\u91cf\u4e0b\u964d\u4e861.8%\u3002\u673a\u4f1a\u533a\u6295\u8d44\u8005\u66f4\u504f\u597d\u6210\u719f\u3001\u5df2\u5efa\u7acb\u7684\u4f01\u4e1a\uff0c\u8fd9\u53cd\u8fc7\u6765\u6291\u5236\u4e86\u65b0\u4f01\u4e1a\u7684\u5f62\u6210\u3002\u6b64\u5916\uff0c\u521b\u4e1a\u51cf\u5c11\u4e0e\u5f53\u5730\u5c31\u4e1a\u4e0b\u964d1.7%\u4ee5\u53ca\u5e02\u573a\u7ade\u4e89\u51cf\u5f31\u76f8\u5173\uff0c\u8868\u660e\u8be5\u653f\u7b56\u5bf9\u5b9e\u4f53\u7ecf\u6d4e\u4ea7\u751f\u4e86\u8d1f\u9762\u6548\u5e94\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag023", "journal": "QJE", "title": "A Cognitive Theory of Reasoning and Choice", "authors": ["Pedro Bordalo", "Nicola Gennaioli", "Giacomo Lanzani", "Andrei Shleifer"], "author_details": [{"name": "Pedro Bordalo", "affiliations": ["University of Oxford ,"]}, {"name": "Nicola Gennaioli", "affiliations": ["Bocconi University ,"]}, {"name": "Giacomo Lanzani", "affiliations": ["University of California Berkeley ,"]}, {"name": "Andrei Shleifer", "affiliations": ["Harvard University ,"]}], "abstract": "Abstract We present a theory of choice in which attention to the features of options is determined by the decision maker\u2019s categorization of the current problem in a set of problems she solved in the past. Categorization depends on goal-relevant and contextual problem-level features. The model yields heterogeneity in attention and choice in a given problem based on different past experiences and instability when changes in irrelevant context cause recategorization. We show that heterogeneous and unstable representations of a choice problem unify major biases in judgment and decision making.", "date": "2026-06-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag023", "title_zh": "\u4e00\u79cd\u5173\u4e8e\u63a8\u7406\u4e0e\u9009\u62e9\u7684\u8ba4\u77e5\u7406\u8bba", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u9009\u62e9\u7406\u8bba\uff0c\u5176\u4e2d\u51b3\u7b56\u8005\u5bf9\u9009\u9879\u7279\u5f81\u7684\u6ce8\u610f\u529b\u7531\u5176\u8fc7\u53bb\u89e3\u51b3\u7684\u95ee\u9898\u96c6\u5408\u4e2d\u7684\u95ee\u9898\u5206\u7c7b\u51b3\u5b9a\u3002\u5206\u7c7b\u4f9d\u8d56\u4e8e\u4e0e\u76ee\u6807\u76f8\u5173\u548c\u4e0a\u4e0b\u6587\u5c42\u9762\u7684\u95ee\u9898\u7279\u5f81\u3002\u8be5\u6a21\u578b\u57fa\u4e8e\u4e0d\u540c\u7684\u8fc7\u53bb\u7ecf\u9a8c\u5bfc\u81f4\u540c\u4e00\u95ee\u9898\u4e2d\u6ce8\u610f\u529b\u548c\u9009\u62e9\u7684\u5f02\u8d28\u6027\uff0c\u5e76\u5728\u65e0\u5173\u4e0a\u4e0b\u6587\u53d8\u5316\u5f15\u53d1\u91cd\u65b0\u5206\u7c7b\u65f6\u8868\u73b0\u51fa\u4e0d\u7a33\u5b9a\u6027\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5bf9\u9009\u62e9\u95ee\u9898\u7684\u5f02\u8d28\u6027\u548c\u4e0d\u7a33\u5b9a\u6027\u8868\u5f81\u80fd\u591f\u7edf\u4e00\u5224\u65ad\u4e0e\u51b3\u7b56\u4e2d\u7684\u4e3b\u8981\u504f\u5dee\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag021", "journal": "REStud", "title": "Unpacking Aggregate Welfare in a Spatial Economy", "authors": ["Eric Donald", "Masao Fukui", "Yuhei Miyauchi"], "author_details": [{"name": "Eric Donald", "affiliations": ["University of Pittsburgh ,"]}, {"name": "Masao Fukui", "affiliations": ["Boston University ,"]}, {"name": "Yuhei Miyauchi", "affiliations": ["Boston University ,"]}], "abstract": "Abstract How do regional productivity shocks or transportation infrastructure improvements affect aggregate welfare? In a general class of spatial equilibrium models, we provide a formula for aggregate welfare changes, decomposed into terms associated with (i) technology [Fogel (1964), Railroads and American Economic Growth (Baltimore: Johns Hopkins Press), Hulten (1978) \u201cGrowth Accounting with Intermediate Inputs\u201d, The Review of Economic Studies, 45, 511\u2013518], (ii) spatial dispersion of marginal utility, (iii) fiscal externalities, (iv) technological externalities, and (v) redistribution. We further use this decomposition to derive a general formula for optimal spatial transfers and show that, whenever optimal transfers are in place, the technology term alone captures the aggregate welfare effects of technological shocks. We apply our framework to study welfare gains from improving the US highway network. We find that changes in the spatial dispersion of marginal utility are as important as technological externalities in accounting for the deviations from the Fogel-Hulten benchmark to assess welfare gains.", "date": "2026-06-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag021", "title_zh": "\u5728\u7a7a\u95f4\u7ecf\u6d4e\u4e2d\u89e3\u6790\u603b\u4f53\u798f\u5229", "abstract_zh": "\u6458\u8981 \u533a\u57df\u751f\u4ea7\u7387\u51b2\u51fb\u6216\u4ea4\u901a\u57fa\u7840\u8bbe\u65bd\u6539\u5584\u5982\u4f55\u5f71\u54cd\u603b\u4f53\u798f\u5229\uff1f\u5728\u4e00\u7c7b\u4e00\u822c\u6027\u7684\u7a7a\u95f4\u5747\u8861\u6a21\u578b\u4e2d\uff0c\u6211\u4eec\u7ed9\u51fa\u4e86\u603b\u4f53\u798f\u5229\u53d8\u5316\u7684\u516c\u5f0f\uff0c\u8be5\u516c\u5f0f\u5c06\u5f71\u54cd\u5206\u89e3\u4e3a\u4e0e\uff08i\uff09\u6280\u672f\u76f8\u5173\uff08Fogel\uff081964\uff09\uff0c\u300a\u94c1\u8def\u4e0e\u7f8e\u56fd\u7ecf\u6d4e\u589e\u957f\u300b\uff08\u5df4\u5c14\u7684\u6469\uff1a\u7ea6\u7ff0\u65af\u00b7\u970d\u666e\u91d1\u65af\u51fa\u7248\u793e\uff09\uff0cHulten\uff081978\uff09\u300a\u4f7f\u7528\u4e2d\u95f4\u6295\u5165\u54c1\u7684\u7ecf\u6d4e\u589e\u957f\u6838\u7b97\u300b\uff0c\u300a\u7ecf\u6d4e\u7814\u7a76\u8bc4\u8bba\u300b\uff0c45\uff0c511\u2013518\uff09\uff0c\uff08ii\uff09\u8fb9\u9645\u6548\u7528\u7684\u7a7a\u95f4\u5206\u6563\u6027\uff0c\uff08iii\uff09\u8d22\u653f\u5916\u90e8\u6027\uff0c\uff08iv\uff09\u6280\u672f\u5916\u90e8\u6027\uff0c\u4ee5\u53ca\uff08v\uff09\u518d\u5206\u914d\u76f8\u5173\u7684\u5404\u9879\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u5229\u7528\u8fd9\u4e00\u5206\u89e3\u63a8\u5bfc\u51fa\u4e00\u822c\u6027\u7684\u6700\u4f18\u7a7a\u95f4\u8f6c\u79fb\u516c\u5f0f\uff0c\u5e76\u8bc1\u660e\uff0c\u5f53\u6700\u4f18\u8f6c\u79fb\u63aa\u65bd\u5230\u4f4d\u65f6\uff0c\u6280\u672f\u9879\u5355\u72ec\u5c31\u80fd\u6355\u6349\u6280\u672f\u51b2\u51fb\u5bf9\u603b\u4f53\u798f\u5229\u7684\u5f71\u54cd\u3002\u6211\u4eec\u5c06\u8be5\u6846\u67b6\u5e94\u7528\u4e8e\u7814\u7a76\u6539\u5584\u7f8e\u56fd\u9ad8\u901f\u516c\u8def\u7f51\u7edc\u5e26\u6765\u7684\u798f\u5229\u63d0\u5347\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5728\u89e3\u91ca\u798f\u5229\u589e\u76ca\u4e0eFogel-Hulten\u57fa\u51c6\u7684\u504f\u5dee\u65f6\uff0c\u8fb9\u9645\u6548\u7528\u7684\u7a7a\u95f4\u5206\u6563\u6027\u4e0e\u6280\u672f\u5916\u90e8\u6027\u540c\u7b49\u91cd\u8981\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/rfs/hhag051", "journal": "RFS", "title": "Voting on Public Goods: Citizens vs Shareholders", "authors": ["Robin D\u00f6ttling", "Doron Levit", "Nadya Malenko", "Magdalena Rola-Janicka"], "author_details": [{"name": "Robin D\u00f6ttling", "affiliations": ["Erasmus University Rotterdam ,"]}, {"name": "Doron Levit", "affiliations": ["University of Washington ,"]}, {"name": "Nadya Malenko", "affiliations": ["Boston College ,"]}, {"name": "Magdalena Rola-Janicka", "affiliations": ["Imperial College London ,"]}], "abstract": "Abstract We study the interplay between a \u201cone person-one vote\u201d political system and a \u201cone share-one vote\u201d corporate governance regime. If shareholders push firms for more prosocial policies, political backlash may arise, undoing these initiatives. If public policy is frictionless, shareholder democracy becomes irrelevant: the political system fully offsets shareholder influence. With public policy frictions, prosocial corporations can mitigate regulatory shortcomings and enhance corporate public goods provision. Nevertheless, shareholder democracy can hurt citizens due to the representation problem: it favors the preferences of the wealthy. Investor diversification, pass-through voting, and corporate greenwashing have important implications for these trade-offs of shareholder democracy.", "date": "2026-06-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag051", "title_zh": "\u516c\u5171\u7269\u54c1\u7684\u6295\u7968\uff1a\u516c\u6c11\u4e0e\u80a1\u4e1c", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u201c\u4e00\u4eba\u4e00\u7968\u201d\u7684\u653f\u6cbb\u5236\u5ea6\u4e0e\u201c\u4e00\u80a1\u4e00\u7968\u201d\u7684\u516c\u53f8\u6cbb\u7406\u5236\u5ea6\u4e4b\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\u3002\u5982\u679c\u80a1\u4e1c\u63a8\u52a8\u4f01\u4e1a\u5b9e\u65bd\u66f4\u591a\u5229\u4ed6\u653f\u7b56\uff0c\u53ef\u80fd\u4f1a\u5f15\u53d1\u653f\u6cbb\u53cd\u5f39\uff0c\u4ece\u800c\u62b5\u6d88\u8fd9\u4e9b\u4e3e\u63aa\u3002\u5982\u679c\u516c\u5171\u653f\u7b56\u662f\u65e0\u6469\u64e6\u7684\uff0c\u80a1\u4e1c\u6c11\u4e3b\u5c06\u53d8\u5f97\u65e0\u5173\u7d27\u8981\uff1a\u653f\u6cbb\u4f53\u7cfb\u4f1a\u5b8c\u5168\u62b5\u6d88\u80a1\u4e1c\u7684\u5f71\u54cd\u3002\u5728\u5b58\u5728\u516c\u5171\u653f\u7b56\u6469\u64e6\u7684\u60c5\u51b5\u4e0b\uff0c\u5177\u6709\u5229\u4ed6\u503e\u5411\u7684\u4f01\u4e1a\u53ef\u4ee5\u5f25\u8865\u76d1\u7ba1\u4e0d\u8db3\uff0c\u5e76\u63d0\u5347\u4f01\u4e1a\u5bf9\u516c\u5171\u7269\u54c1\u7684\u4f9b\u7ed9\u3002\u7136\u800c\uff0c\u80a1\u4e1c\u6c11\u4e3b\u53ef\u80fd\u5bf9\u516c\u6c11\u9020\u6210\u4f24\u5bb3\uff0c\u56e0\u4e3a\u5176\u5b58\u5728\u4ee3\u8868\u95ee\u9898\uff1a\u5b83\u66f4\u503e\u5411\u4e8e\u6ee1\u8db3\u5bcc\u4eba\u7684\u504f\u597d\u3002\u6295\u8d44\u8005\u5206\u6563\u6295\u8d44\u3001\u6295\u7968\u6743\u4f20\u9012\u4ee5\u53ca\u4f01\u4e1a\u7eff\u8272\u6d17\u724c\u5bf9\u8fd9\u4e9b\u80a1\u4e1c\u6c11\u4e3b\u7684\u6743\u8861\u5177\u6709\u91cd\u8981\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026103044", "journal": "JFQA", "title": "Get the Money Somehow: The Effect of Missing Performance Goals on Insider Trading", "authors": ["Meng Gao"], "author_details": [{"name": "Meng Gao", "affiliations": ["University of Connecticut School of Business"]}], "abstract": "Abstract This article uses a regression discontinuity design to identify the effect of compensation shocks on insider trading. I find that CEOs who narrowly miss relative performance goals and hence suffer a loss in compensation subsequently earn higher abnormal profits from their insider trades than otherwise similar CEOs who narrowly beat such goals. CEOs who narrowly miss relative performance goals also become less likely to provide earnings and sales guidance. These results suggest that managers can use insider trading to make up for compensation losses due to missing relative performance goals, which could reduce the incentive effect of performance-based pay.", "date": "2026-06-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103044", "title_zh": "somehow\uff1a\u7f3a\u5931\u7ee9\u6548\u76ee\u6807\u5bf9\u5185\u5e55\u4ea4\u6613\u7684\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u91c7\u7528\u56de\u5f52\u65ad\u70b9\u8bbe\u8ba1\uff0c\u8bc6\u522b\u4e86\u85aa\u916c\u51b2\u51fb\u5bf9\u5185\u5e55\u4ea4\u6613\u7684\u5f71\u54cd\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u90a3\u4e9b narrowly miss \u76f8\u5bf9\u7ee9\u6548\u76ee\u6807\u56e0\u800c\u906d\u53d7\u85aa\u916c\u635f\u5931\u7684\u9996\u5e2d\u6267\u884c\u5b98\uff0c\u5176\u540e\u7eed\u901a\u8fc7\u5185\u5e55\u4ea4\u6613\u83b7\u5f97\u7684\u5f02\u5e38\u5229\u6da6\uff0c\u9ad8\u4e8e\u90a3\u4e9b narrowly beat \u76f8\u540c\u7ee9\u6548\u76ee\u6807\u7684\u7c7b\u4f3c\u9996\u5e2d\u6267\u884c\u5b98\u3002\u6b64\u5916\uff0c\u90a3\u4e9b narrowly miss \u76f8\u5bf9\u7ee9\u6548\u76ee\u6807\u7684\u9996\u5e2d\u6267\u884c\u5b98\uff0c\u4e5f\u66f4\u4e0d\u53ef\u80fd\u63d0\u4f9b\u76c8\u5229\u548c\u9500\u552e\u6307\u5f15\u3002\u8fd9\u4e9b\u7ed3\u679c\u8868\u660e\uff0c\u7ba1\u7406\u8005\u53ef\u80fd\u5229\u7528\u5185\u5e55\u4ea4\u6613\u6765\u5f25\u8865\u56e0\u672a\u8fbe\u6210\u76f8\u5bf9\u7ee9\u6548\u76ee\u6807\u800c\u5bfc\u81f4\u7684\u85aa\u916c\u635f\u5931\uff0c\u8fd9\u53ef\u80fd\u524a\u5f31\u57fa\u4e8e\u7ee9\u6548\u7684\u85aa\u916c\u6fc0\u52b1\u6548\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag035", "journal": "REStud", "title": "Manager Pay Inequality and Market Power", "authors": ["Renjie Bao", "Jan De Loecker", "Jan Eeckhout"], "author_details": [{"name": "Renjie Bao", "affiliations": ["Princeton , USA"]}, {"name": "Jan De Loecker", "affiliations": ["KU Leuven , Belgium"]}, {"name": "Jan Eeckhout", "affiliations": ["UPF Barcelona and , Spain", "ICREA-BSE-CREI and , Spain"]}], "abstract": "Abstract Manager pay has increased considerably since 1980, and so has inequality in manager pay. Over the same period, there has been a sharp rise in market power. We start from the premise that the role of managers is to increase firm productivity. When markets are imperfectly competitive, productivity not only helps firm grow in size, productivity also affects market power. We model how imperfect competition in product markets affects manager pay, and break down the contributions of firm size and market power to compensation. We find that market power, on average, accounts for 45.2% of total manager pay. Notably, there is substantial variation across managers. Top managers are disproportionately employed by firms with market power, and they benefit from it: in 2019, 80.3% of top manager pay is attributable to market power. Our main conclusion is that rise of market power explains half of the increase in average manager pay, and nearly all of the increase in manager pay inequality.", "date": "2026-06-04", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag035", "title_zh": "\u7ecf\u7406\u85aa\u916c\u4e0d\u5e73\u7b49\u4e0e\u5e02\u573a\u529b\u91cf", "abstract_zh": "\u6458\u8981 \u81ea1980\u5e74\u4ee5\u6765\uff0c\u7ecf\u7406\u85aa\u916c\u663e\u8457\u4e0a\u5347\uff0c\u85aa\u916c\u4e0d\u5e73\u7b49\u4e5f\u540c\u6b65\u52a0\u5267\u3002\u4e0e\u6b64\u540c\u65f6\uff0c\u5e02\u573a\u529b\u91cf\u51fa\u73b0\u4e86\u6025\u5267\u4e0a\u5347\u3002\u6211\u4eec\u57fa\u4e8e\u4e00\u4e2a\u524d\u63d0\uff1a\u7ecf\u7406\u7684\u804c\u8d23\u662f\u63d0\u5347\u4f01\u4e1a\u751f\u4ea7\u7387\u3002\u5728\u5e02\u573a\u4e0d\u5b8c\u5168\u7ade\u4e89\u7684\u60c5\u51b5\u4e0b\uff0c\u751f\u4ea7\u7387\u4e0d\u4ec5\u6709\u52a9\u4e8e\u4f01\u4e1a\u89c4\u6a21\u6269\u5f20\uff0c\u8fd8\u4f1a\u5f71\u54cd\u5e02\u573a\u529b\u91cf\u3002\u6211\u4eec\u6784\u5efa\u4e86\u6a21\u578b\uff0c\u5206\u6790\u4ea7\u54c1\u5e02\u573a\u4e2d\u7684\u4e0d\u5b8c\u5168\u7ade\u4e89\u5982\u4f55\u5f71\u54cd\u7ecf\u7406\u85aa\u916c\uff0c\u5e76\u5206\u89e3\u4e86\u4f01\u4e1a\u89c4\u6a21\u548c\u5e02\u573a\u529b\u91cf\u5bf9\u4f01\u4e1a\u85aa\u916c\u7684\u8d21\u732e\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5e02\u573a\u529b\u91cf\u5e73\u5747\u5360\u7ecf\u7406\u85aa\u916c\u768445.2%\u3002\u503c\u5f97\u6ce8\u610f\u7684\u662f\uff0c\u4e0d\u540c\u7ecf\u7406\u4e4b\u95f4\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002\u9ad8\u5c42\u7ecf\u7406\u4e3b\u8981\u88ab\u5e02\u573a\u529b\u91cf\u5f3a\u7684\u4f01\u4e1a\u96c7\u4f63\uff0c\u5e76\u4ece\u4e2d\u53d7\u76ca\uff1a2019\u5e74\uff0c80.3%\u7684\u9ad8\u5c42\u7ecf\u7406\u85aa\u916c\u53ef\u5f52\u56e0\u4e8e\u5e02\u573a\u529b\u91cf\u3002\u6211\u4eec\u7684\u4e3b\u8981\u7ed3\u8bba\u662f\uff0c\u5e02\u573a\u529b\u91cf\u7684\u4e0a\u5347\u89e3\u91ca\u4e86\u5e73\u5747\u7ecf\u7406\u85aa\u916c\u589e\u957f\u7684\u4e00\u534a\uff0c\u4ee5\u53ca\u7ecf\u7406\u85aa\u916c\u4e0d\u5e73\u7b49\u589e\u957f\u7684\u51e0\u4e4e\u5168\u90e8\u90e8\u5206\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag053", "journal": "REStud", "title": "Income Inequality and Job Creation", "authors": ["Sebastian Doerr", "Thomas Drechsel", "Donggyu Lee"], "author_details": [{"name": "Sebastian Doerr", "affiliations": ["Bank for International Settlements & CEPR ,"]}, {"name": "Thomas Drechsel", "affiliations": ["University of Maryland, NBER & CEPR ,"]}, {"name": "Donggyu Lee", "affiliations": ["Federal Reserve Bank of New York ,"]}], "abstract": "Abstract We propose a novel channel through which rising income inequality affects job creation and macroeconomic outcomes. High-income households save relatively more in stocks and bonds but less in bank deposits. A rising top income share thereby increases the relative financing cost for bank-dependent firms, which in turn create fewer jobs compared to other firms. Exploiting variation in top income shares across US states and an instrumental variable strategy, we provide evidence for this channel. We then build a general equilibrium macroeconomic model with heterogeneous households and heterogeneous firms and calibrate it to our empirical estimates. The model shows that the secular rise in top incomes accounts for 13% of the decline in the employment share of small firms since 1980. Through the new channel, rising inequality also reduces the labour share and aggregate output. Model experiments show that ignoring the link between inequality and job creation understates welfare effects of income redistribution.", "date": "2026-06-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag053", "title_zh": "\u6536\u5165\u4e0d\u5e73\u7b49\u4e0e\u5c31\u4e1a\u521b\u9020", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u6761\u65b0\u7684\u6e20\u9053\uff0c\u8bf4\u660e\u6536\u5165\u4e0d\u5e73\u7b49\u4e0a\u5347\u5982\u4f55\u5f71\u54cd\u5c31\u4e1a\u521b\u9020\u548c\u5b8f\u89c2\u7ecf\u6d4e\u7ed3\u679c\u3002\u9ad8\u6536\u5165\u5bb6\u5ead\u66f4\u503e\u5411\u4e8e\u5c06\u6536\u5165\u5b58\u5165\u80a1\u7968\u548c\u503a\u5238\uff0c\u800c\u8f83\u5c11\u5b58\u5165\u94f6\u884c\u5b58\u6b3e\u3002\u56e0\u6b64\uff0c\u9876\u5c42\u6536\u5165\u4efd\u989d\u7684\u4e0a\u5347\u4f1a\u63d0\u9ad8\u4f9d\u8d56\u94f6\u884c\u878d\u8d44\u7684\u4f01\u4e1a\u76f8\u5bf9\u878d\u8d44\u6210\u672c\uff0c\u4ece\u800c\u5bfc\u81f4\u8fd9\u4e9b\u4f01\u4e1a\u521b\u9020\u7684\u5c31\u4e1a\u5c97\u4f4d\u5c11\u4e8e\u5176\u4ed6\u4f01\u4e1a\u3002\u6211\u4eec\u5229\u7528\u7f8e\u56fd\u5404\u5dde\u9876\u5c42\u6536\u5165\u4efd\u989d\u7684\u5dee\u5f02\uff0c\u5e76\u91c7\u7528\u5de5\u5177\u53d8\u91cf\u65b9\u6cd5\uff0c\u63d0\u4f9b\u4e86\u8fd9\u4e00\u6e20\u9053\u7684\u8bc1\u636e\u3002\u968f\u540e\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u5f02\u8d28\u6027\u5bb6\u5ead\u548c\u5f02\u8d28\u6027\u4f01\u4e1a\u7684\u4e00\u822c\u5747\u8861\u5b8f\u89c2\u7ecf\u6d4e\u6a21\u578b\uff0c\u5e76\u5c06\u5176\u6821\u51c6\u5230\u6211\u4eec\u7684\u5b9e\u8bc1\u4f30\u8ba1\u7ed3\u679c\u3002\u6a21\u578b\u663e\u793a\uff0c\u81ea1980\u5e74\u4ee5\u6765\u9876\u5c42\u6536\u5165\u6301\u7eed\u4e0a\u5347\uff0c\u5bfc\u81f4\u5c0f\u578b\u4f01\u4e1a\u5c31\u4e1a\u4efd\u989d\u4e0b\u964d\u4e8613%\u3002\u901a\u8fc7\u8fd9\u4e00\u65b0\u6e20\u9053\uff0c\u6536\u5165\u4e0d\u5e73\u7b49\u7684\u4e0a\u5347\u4e5f\u964d\u4f4e\u4e86\u52b3\u52a8\u4efd\u989d\u548c\u603b\u4ea7\u51fa\u3002\u6a21\u578b\u5b9e\u9a8c\u8868\u660e\uff0c\u5ffd\u7565\u6536\u5165\u4e0d\u5e73\u7b49\u4e0e\u5c31\u4e1a\u521b\u9020\u4e4b\u95f4\u7684\u8054\u7cfb\uff0c\u4f1a\u4f4e\u4f30\u6536\u5165\u518d\u5206\u914d\u5bf9\u798f\u5229\u7684\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag051", "journal": "REStud", "title": "Pigovian Transport Pricing in Practice", "authors": ["Beat Hintermann", "Beaumont Schoeman", "Joseph Molloy", "Thomas G\u00f6tschi", "Alberto Castro", "Christopher Tchervenkov", "Uros Tomic", "Kay W Axhausen"], "author_details": [{"name": "Beat Hintermann", "affiliations": ["University of Basel ,"]}, {"name": "Beaumont Schoeman", "affiliations": ["University of Hamburg University of Basel, Switzerland and ,"]}, {"name": "Joseph Molloy", "affiliations": ["FAIRTIQ AG ,"]}, {"name": "Thomas G\u00f6tschi", "affiliations": ["University of Oregon University of Basel, Switzerland and ,"]}, {"name": "Alberto Castro", "affiliations": ["Swiss Tropical and Public Health Institute University of Basel, Switzerland and ,"]}, {"name": "Christopher Tchervenkov", "affiliations": ["Division Mobilit\u00e9 , Cit\u00e9 de Lausanne ,"]}, {"name": "Uros Tomic", "affiliations": ["Zurich School of Applied Sciences ,"]}, {"name": "Kay W Axhausen", "affiliations": ["ETH Z\u00fcrich ,"]}], "abstract": "Abstract We implement Pigovian transport pricing in a field experiment in urban agglomerations of Switzerland over the course of 8 weeks. Our pricing considers the external costs from climate damages, health outcomes from pollution, accidents and physical activity, and congestion. It varies across time, space, and mode of transport and is deducted from a budget provided to GPS-tracked participants. The treatment significantly reduces the external costs of transport during the course of the experiment. The main underlying mechanism is a shift away from driving towards other modes, such as public transport, walking, and cycling. Providing information about the external costs of transport alone is insufficient to change the transport behaviour for the sample majority. A time-invariant tax on CO2 and health-related externalities would capture most of the welfare gains associated with the first-best policy.", "date": "2026-06-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag051", "title_zh": "\u5b9e\u8df5\u4e2d\u7684\u5e87\u53e4\u5f0f\u4ea4\u901a\u5b9a\u4ef7", "abstract_zh": "\u6211\u4eec\u5728\u4e00\u4e2a\u4e3a\u671f\u516b\u5468\u7684\u745e\u58eb\u57ce\u5e02\u805a\u96c6\u4f53\u9a8c\u4e2d\u5b9e\u65bd\u4e86\u5e87\u53e4\u5f0f\u4ea4\u901a\u5b9a\u4ef7\u3002\u6211\u4eec\u7684\u5b9a\u4ef7\u8003\u8651\u4e86\u6c14\u5019\u53d8\u5316\u635f\u5bb3\u3001\u6c61\u67d3\u5bfc\u81f4\u7684\u5065\u5eb7\u540e\u679c\u3001\u4e8b\u6545\u4ee5\u53ca\u4f53\u529b\u6d3b\u52a8\u65b9\u9762\u7684\u5916\u90e8\u6210\u672c\uff0c\u4ee5\u53ca\u4ea4\u901a\u62e5\u5835\u3002\u8be5\u5b9a\u4ef7\u5728\u65f6\u95f4\u3001\u7a7a\u95f4\u548c\u4ea4\u901a\u65b9\u5f0f\u4e0a\u6709\u6240\u4e0d\u540c\uff0c\u5e76\u4eceGPS\u8ffd\u8e2a\u53c2\u4e0e\u8005\u63d0\u4f9b\u7684\u9884\u7b97\u4e2d\u6263\u9664\u3002\u5b9e\u9a8c\u671f\u95f4\uff0c\u8be5\u5b9a\u4ef7\u663e\u8457\u964d\u4f4e\u4e86\u4ea4\u901a\u7684\u5916\u90e8\u6210\u672c\u3002\u4e3b\u8981\u673a\u5236\u662f\u51fa\u884c\u884c\u4e3a\u4ece\u9a7e\u9a76\u8f6c\u5411\u5176\u4ed6\u6a21\u5f0f\uff0c\u5982\u516c\u5171\u4ea4\u901a\u3001\u6b65\u884c\u548c\u9a91\u884c\u3002\u4ec5\u63d0\u4f9b\u4ea4\u901a\u5916\u90e8\u6210\u672c\u4fe1\u606f\u5bf9\u4e8e\u6837\u672c\u4e2d\u7684\u5927\u591a\u6570\u53c2\u4e0e\u8005\u6539\u53d8\u51fa\u884c\u884c\u4e3a\u662f\u4e0d\u591f\u7684\u3002\u5bf9\u4e8c\u6c27\u5316\u78b3\u548c\u4e0e\u5065\u5eb7\u76f8\u5173\u7684\u5916\u90e8\u6027\u5f81\u6536\u4e00\u4e2a\u65f6\u95f4\u4e0d\u53d8\u7684\u7a0e\uff0c\u5c06\u6355\u83b7\u4e0e\u6700\u4f18\u653f\u7b56\u76f8\u5173\u7684\u5927\u90e8\u5206\u798f\u5229\u6536\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag021", "journal": "RFS", "title": "Thematic Concentration and Mutual Fund Performance", "authors": ["John (Jianqiu) Bai", "Yuehua Tang", "Chi Wan", "H Zafer Y\u00fcksel"], "author_details": [{"name": "John (Jianqiu) Bai", "affiliations": ["The Hong Kong Polytechnic University"]}, {"name": "Yuehua Tang", "affiliations": ["Warrington College of Business, University of Florida ,"]}, {"name": "Chi Wan", "affiliations": ["Fowler College of Business, San Diego State University ,"]}, {"name": "H Zafer Y\u00fcksel", "affiliations": ["College of Business, University of Rhode Island ,"]}], "abstract": "Abstract This study examines whether mutual fund managers generate alpha through thematic investment strategies that select stocks poised to benefit from specific themes. Using textual analysis of 10-K filings, we identify stocks\u2019 thematic exposures and construct each fund\u2019s thematic concentration index (TCI) from its holdings. High-TCI funds significantly outperform, with a top-minus-bottom decile spread of 4.26% in annualized four-factor alpha. Managers\u2019 thematic expertise is related to their undergraduate field of study. Outperformance arises from superior stock selection rather than theme-related timing, with an informational advantage on firm earnings, particularly in stocks exposed to themes related to managers\u2019 undergraduate training.", "date": "2026-06-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag021", "title_zh": "\u4e3b\u9898\u96c6\u4e2d\u4e0e\u5171\u540c\u57fa\u91d1\u8868\u73b0", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5171\u540c\u57fa\u91d1\u7ecf\u7406\u662f\u5426\u901a\u8fc7\u4e3b\u9898\u6295\u8d44\u7b56\u7565\u2014\u2014\u9009\u62e9\u6709\u671b\u4ece\u7279\u5b9a\u4e3b\u9898\u4e2d\u53d7\u76ca\u7684\u80a1\u7968\u2014\u2014\u4ea7\u751f\u963f\u5c14\u6cd5\u3002\u5229\u7528\u5bf910-K\u6587\u4ef6\u7684\u6587\u672c\u5206\u6790\uff0c\u6211\u4eec\u8bc6\u522b\u51fa\u80a1\u7968\u7684\u4e3b\u9898\u66b4\u9732\uff0c\u5e76\u57fa\u4e8e\u5176\u6301\u4ed3\u6784\u5efa\u6bcf\u53ea\u57fa\u91d1\u7684\u4e3b\u9898\u96c6\u4e2d\u5ea6\u6307\u6570\uff08TCI\uff09\u3002\u9ad8TCI\u57fa\u91d1\u8868\u73b0\u663e\u8457\u4f18\u4e8e\u4f4eTCI\u57fa\u91d1\uff0c\u5e74\u5ea6\u5316\u56db\u56e0\u5b50\u963f\u5c14\u6cd5\u7684\u524d\u5341\u5206\u4f4d\u4e0e\u540e\u5341\u5206\u4f4d\u4e4b\u95f4\u7684\u5dee\u8ddd\u4e3a4.26%\u3002\u57fa\u91d1\u7ecf\u7406\u7684\u4e3b\u9898\u4e13\u957f\u4e0e\u5176\u672c\u79d1\u4e13\u4e1a\u9886\u57df\u76f8\u5173\u3002\u8d85\u989d\u6536\u76ca\u6e90\u4e8e\u66f4\u4f18\u7684\u4e2a\u80a1\u9009\u62e9\uff0c\u800c\u975e\u4e0e\u4e3b\u9898\u76f8\u5173\u7684\u62e9\u65f6\u51b3\u7b56\uff0c\u57fa\u91d1\u7ecf\u7406\u5728\u4f01\u4e1a\u76c8\u5229\u4fe1\u606f\u65b9\u9762\u5177\u6709\u4fe1\u606f\u4f18\u52bf\uff0c\u5c24\u5176\u4f53\u73b0\u5728\u90a3\u4e9b\u4e0e\u57fa\u91d1\u7ecf\u7406\u672c\u79d1\u4e13\u4e1a\u76f8\u5173\u7684\u4e3b\u9898\u66b4\u9732\u7684\u80a1\u7968\u4e0a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790"]}, {"doi": "10.1093/rfs/hhag053", "journal": "RFS", "title": "Partial Equilibrium Thinking, Extrapolation, and Bubbles", "authors": ["Francesca Bastianello", "Paul Fontanier"], "author_details": [{"name": "Francesca Bastianello", "affiliations": ["University of Chicago, Booth School of Business , the"]}, {"name": "Paul Fontanier", "affiliations": ["Yale University, School of Management , the"]}], "abstract": "Abstract We develop a dynamic theory of \u201cPartial Equilibrium Thinking\u201d (PET), which micro-founds time-varying return extrapolation: extrapolative beliefs are present at all times, but only sometimes manifest themselves in explosive ways. We formalize the distinction between normal times shocks and \u201cdisplacement shocks,\u201d and study their interaction with extrapolative beliefs. In normal times, PET generates constant extrapolation and momentum. After a displacement shock that increases uncertainty, PET leads to stronger and time-varying extrapolation, triggering bubbles and endogenous crashes. Our theory sheds light on both market dynamics in normal times and Kindleberger\u2019s narrative of bubbles within a unified framework.", "date": "2026-06-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag053", "title_zh": "\u90e8\u5206\u5747\u8861\u601d\u7ef4\u3001\u5916\u63a8\u4e0e\u6ce1\u6cab", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u52a8\u6001\u7684\u201c\u90e8\u5206\u5747\u8861\u601d\u7ef4\u201d\uff08PET\uff09\u7406\u8bba\uff0c\u8be5\u7406\u8bba\u4ece\u5fae\u89c2\u5c42\u9762\u89e3\u91ca\u4e86\u65f6\u95f4\u53d8\u5316\u7684\u6536\u76ca\u5916\u63a8\u73b0\u8c61\uff1a\u5916\u63a8\u6027\u4fe1\u5ff5\u59cb\u7ec8\u5b58\u5728\uff0c\u4f46\u4ec5\u5728\u67d0\u4e9b\u60c5\u51b5\u4e0b\u4ee5\u7206\u70b8\u6027\u65b9\u5f0f\u8868\u73b0\u51fa\u6765\u3002\u6211\u4eec\u6b63\u5f0f\u533a\u5206\u4e86\u6b63\u5e38\u65f6\u671f\u4e2d\u7684\u51b2\u51fb\u4e0e\u201c\u4f4d\u79fb\u51b2\u51fb\u201d\uff0c\u5e76\u7814\u7a76\u5b83\u4eec\u4e0e\u5916\u63a8\u6027\u4fe1\u5ff5\u7684\u76f8\u4e92\u4f5c\u7528\u3002\u5728\u6b63\u5e38\u65f6\u671f\uff0cPET \u4ea7\u751f\u6301\u7eed\u7684\u5916\u63a8\u548c\u52a8\u91cf\u6548\u5e94\u3002\u5728\u4f4d\u79fb\u51b2\u51fb\u53d1\u751f\u540e\uff0c\u8be5\u51b2\u51fb\u63d0\u9ad8\u4e86\u4e0d\u786e\u5b9a\u6027\uff0cPET \u5bfc\u81f4\u5916\u63a8\u5f3a\u5ea6\u589e\u5f3a\u4e14\u968f\u65f6\u95f4\u53d8\u5316\uff0c\u4ece\u800c\u5f15\u53d1\u6ce1\u6cab\u548c\u5185\u751f\u6027\u5d29\u76d8\u3002\u672c\u7406\u8bba\u5728\u4e00\u4e2a\u7edf\u4e00\u6846\u67b6\u4e0b\u63ed\u793a\u4e86\u6b63\u5e38\u65f6\u671f\u5e02\u573a\u52a8\u6001\u4ee5\u53caKindleberger\u5173\u4e8e\u6ce1\u6cab\u7684\u53d9\u8ff0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag052", "journal": "RFS", "title": "The Real Effect of Sociopolitical Racial/Ethnic Animus: Mutual Fund Manager Performance during AAPI Hate", "authors": ["Vikas Agarwal", "Wei Jiang", "Yuchen Luo", "Hong Zou"], "author_details": [{"name": "Vikas Agarwal", "affiliations": ["J. Mack Robinson College of Business, Georgia State University ,"]}, {"name": "Wei Jiang", "affiliations": ["Goizueta Business School, Emory University , ,", "ECGI and NBER , ,"]}, {"name": "Yuchen Luo", "affiliations": ["School of Business Administration, Oakland University ,"]}, {"name": "Hong Zou", "affiliations": ["Faculty of Business and Economics, University of Hong Kong ,"]}], "abstract": "Abstract During the 2020\u20132021 \u201cAAPI Hate,\u201d mutual funds led by female managers perceived as East Asian underperformed relative to other female managers. This effect is stronger in states with higher anti-Asian animus, among more actively managed funds, and when these managers hold sole or senior roles. Factors concurrent with COVID-19, including childcare challenges, concerns for overseas families, marketplace and workplace discrimination, and exposure to the Chinese economy, cannot explain the effect. Underperformance is traceable to poor stock picking due to impairments in generating private information. Racial-ethnic animosity, even outside workplace or marketplace, hinders productivity and decision-making in high-skill professions.", "date": "2026-06-02", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag052", "title_zh": "\u79cd\u65cf/\u6c11\u65cf\u504f\u89c1\u7684\u73b0\u5b9e\u5f71\u54cd\uff1a2020\u20132021\u5e74\u9488\u5bf9\u4e9a\u88d4\u7f8e\u56fd\u4eba\u7684\u4ec7\u6068\u4e8b\u4ef6\u4e2d\u5171\u540c\u57fa\u91d1\u7ecf\u7406\u7ee9\u6548", "abstract_zh": "\u6458\u8981 \u57282020\u20132021\u5e74\u2018\u9488\u5bf9\u4e9a\u88d4\u7f8e\u56fd\u4eba\u7684\u4ec7\u6068\u2019\u671f\u95f4\uff0c\u88ab\u611f\u77e5\u4e3a\u4e1c\u4e9a\u80cc\u666f\u7684\u5973\u6027\u57fa\u91d1\u7ecf\u7406\u7ba1\u7406\u7684\u5171\u540c\u57fa\u91d1\u8868\u73b0\u900a\u4e8e\u5176\u4ed6\u5973\u6027\u57fa\u91d1\u7ecf\u7406\u3002\u8fd9\u4e00\u6548\u5e94\u5728\u53cd\u4e9a\u88d4\u60c5\u7eea\u8f83\u9ad8\u7684\u5dde\u66f4\u4e3a\u663e\u8457\uff0c\u5728\u7ba1\u7406\u66f4\u4e3a\u79ef\u6781\u7684\u57fa\u91d1\u4e2d\u66f4\u4e3a\u660e\u663e\uff0c\u4e14\u5f53\u8fd9\u4e9b\u57fa\u91d1\u7ecf\u7406\u62c5\u4efb\u552f\u4e00\u6216\u9ad8\u7ea7\u804c\u4f4d\u65f6\u66f4\u4e3a\u7a81\u51fa\u3002\u4e0e\u65b0\u51a0\u75ab\u60c5\u76f8\u5173\u7684\u56e0\u7d20\uff0c\u5982\u80b2\u513f\u56f0\u96be\u3001\u5bf9\u6d77\u5916\u5bb6\u5ead\u7684\u62c5\u5fe7\u3001\u5e02\u573a\u548c\u804c\u573a\u6b67\u89c6\u4ee5\u53ca\u5bf9\u4e2d\u56fd\u7ecf\u6d4e\u7684\u63a5\u89e6\uff0c\u5747\u65e0\u6cd5\u89e3\u91ca\u8fd9\u4e00\u73b0\u8c61\u3002\u8868\u73b0\u4e0d\u4f73\u53ef\u8ffd\u6eaf\u5230\u7531\u4e8e\u79cd\u65cf-\u6c11\u65cf\u504f\u89c1\u5bfc\u81f4\u7684\u4fe1\u606f\u83b7\u53d6\u80fd\u529b\u4e0b\u964d\uff0c\u4ece\u800c\u5f71\u54cd\u4e86\u80a1\u7968\u9009\u62e9\u3002\u79cd\u65cf-\u6c11\u65cf\u504f\u89c1\uff0c\u5373\u4f7f\u5728\u5de5\u4f5c\u573a\u6240\u6216\u5e02\u573a\u4e4b\u5916\uff0c\u4e5f\u4f1a\u963b\u788d\u9ad8\u6280\u80fd\u804c\u4e1a\u4e2d\u7684\u751f\u4ea7\u6548\u7387\u548c\u51b3\u7b56\u80fd\u529b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1257/aer.20230376", "journal": "AER", "title": "Quota versus Quality? Long-Term Gains from an Unusual Gender Quota", "authors": ["Ursina Schaede", "Ville Mankki"], "author_details": [{"name": "Ursina Schaede", "affiliations": ["Tufts University (Corresponding author) (email: )"]}, {"name": "Ville Mankki", "affiliations": ["University of Jyv\u00e4skyl\u00e4 (email: )"]}], "abstract": "We evaluate equity-efficiency trade-offs from admissions quotas by examining effects on output once beneficiaries start producing in the relevant industry. We estimate the impact of abolishing a 40 percent quota for male primary school teachers on their pupils\u2019 long-run outcomes. We combine this reform with the timing of union-bargained teacher retirements to isolate quasi-random variation in male quota teachers. Pupils exposed to male quota teachers transition more smoothly to postcompulsory education and have higher educational attainment and labor force attachment at age 25. Evidence suggests the quota improved the allocation of talent by mending imperfections in the unconstrained selection process. (JEL I21, I23, I28, J16, J24, J45)", "date": "2026-06-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230376", "title_zh": "\u914d\u989d\u8fd8\u662f\u8d28\u91cf\uff1f\u4e00\u9879\u4e0d\u5bfb\u5e38\u7684\u6027\u522b\u914d\u989d\u5e26\u6765\u7684\u957f\u671f\u6536\u76ca", "abstract_zh": "\u6211\u4eec\u901a\u8fc7\u8003\u5bdf\u53d7\u76ca\u8005\u5f00\u59cb\u5728\u76f8\u5173\u884c\u4e1a\u751f\u4ea7\u540e\u7684\u4ea7\u51fa\u60c5\u51b5\uff0c\u6765\u8bc4\u4f30\u62db\u751f\u914d\u989d\u5728\u516c\u5e73\u4e0e\u6548\u7387\u4e4b\u95f4\u7684\u6743\u8861\u3002\u6211\u4eec\u4f30\u8ba1\u4e86\u53d6\u6d88\u7537\u6027\u5c0f\u5b66\u6559\u5e0840%\u914d\u989d\u5bf9\u5b66\u751f\u4ea7\u751f\u7684\u957f\u671f\u5f71\u54cd\u3002\u6211\u4eec\u5c06\u8fd9\u4e00\u6539\u9769\u4e0e\u5de5\u4f1a\u534f\u5546\u7684\u6559\u5e08\u9000\u4f11\u65f6\u95f4\u76f8\u7ed3\u5408\uff0c\u4ee5\u9694\u79bb\u7537\u6027\u914d\u989d\u6559\u5e08\u7684\u51c6\u968f\u673a\u53d8\u5316\u3002\u63a5\u53d7\u7537\u6027\u914d\u989d\u6559\u5e08\u6559\u80b2\u7684\u5b66\u751f\u5728\u8fdb\u5165\u975e\u4e49\u52a1\u6559\u80b2\u9636\u6bb5\u65f6\u8fc7\u6e21\u66f4\u5e73\u7a33\uff0c25\u5c81\u65f6\u6559\u80b2\u6c34\u5e73\u66f4\u9ad8\uff0c\u4e14\u52b3\u52a8\u529b\u53c2\u4e0e\u7387\u4e5f\u66f4\u9ad8\u3002\u8bc1\u636e\u8868\u660e\uff0c\u914d\u989d\u901a\u8fc7\u5f25\u8865\u65e0\u7ea6\u675f\u9009\u62d4\u8fc7\u7a0b\u4e2d\u7684\u7f3a\u9677\uff0c\u6539\u5584\u4e86\u4eba\u624d\u7684\u914d\u7f6e\u3002\uff08JEL I21, I23, I28, J16, J24, J45\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20230541", "journal": "AER", "title": "The Private Provision of Public Services: Evidence from Random Assignment in Medicaid", "authors": ["Danil Agafiev Macambira", "Michael Geruso", "Anthony Lollo", "Chima D. Ndumele", "Jacob Wallace"], "author_details": [{"name": "Danil Agafiev Macambira", "affiliations": ["Yale School of Public Health (email: )"]}, {"name": "Michael Geruso", "affiliations": ["University of Texas at Austin (email: )"]}, {"name": "Anthony Lollo", "affiliations": ["Yale School of Public Health (email: )"]}, {"name": "Chima D. Ndumele", "affiliations": ["Yale School of Public Health (email: )"]}, {"name": "Jacob Wallace", "affiliations": ["Yale School of Public Health (email: )"]}], "abstract": "This paper examines the effects of privatizing social health insurance. We exploit a natural experiment in Medicaid, wherein nearly 100,000 enrollees were randomly assigned between a publicly operated fee-for-service system and private managed care. Managed care reduced costs by 5.6 percent via cost-effective substitutions among prescription drugs and via lower prices for outpatient services. We present evidence that pharmacy utilization management was the key mechanism reducing overuse and encouraging substitution to lower-cost drugs without decreasing observed quality. In contrast, privatizing medical benefits led to only modest savings and was associated with decreased health care quality and consumer satisfaction. (JEL G22, H41, I13, I18, I38)", "date": "2026-06-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230541", "title_zh": "\u516c\u5171\u670d\u52a1\u7684\u79c1\u4eba\u63d0\u4f9b\uff1a\u6765\u81ea\u533b\u7597\u4fdd\u9669\u968f\u673a\u5206\u914d\u7684\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u793e\u4f1a\u5065\u5eb7\u4fdd\u9669\u79c1\u6709\u5316\u7684\u5f71\u54cd\u3002\u6211\u4eec\u5229\u7528\u533b\u7597\u4fdd\u9669\u4e2d\u7684\u4e00\u9879\u81ea\u7136\u5b9e\u9a8c\uff0c\u5176\u4e2d\u8fd110\u4e07\u540d\u53c2\u4fdd\u4eba\u88ab\u968f\u673a\u5206\u914d\u5230\u7531\u653f\u5e9c\u8fd0\u8425\u7684\u6309\u670d\u52a1\u6536\u8d39\u7cfb\u7edf\u6216\u79c1\u4eba\u7ba1\u7406\u5f0f\u533b\u7597\u7cfb\u7edf\u4e4b\u95f4\u3002\u7ba1\u7406\u5f0f\u533b\u7597\u901a\u8fc7\u5904\u65b9\u836f\u4e2d\u7684\u6210\u672c\u6548\u76ca\u66ff\u4ee3\u4ee5\u53ca\u95e8\u8bca\u670d\u52a1\u4ef7\u683c\u964d\u4f4e\uff0c\u4f7f\u6210\u672c\u4e0b\u964d\u4e865.6%\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u836f\u54c1\u4f7f\u7528\u7ba1\u7406\u662f\u51cf\u5c11\u8fc7\u5ea6\u7528\u836f\u5e76\u4fc3\u8fdb\u5411\u4f4e\u6210\u672c\u836f\u7269\u8f6c\u6362\u7684\u5173\u952e\u673a\u5236\uff0c\u4e14\u5728\u4e0d\u964d\u4f4e\u89c2\u5bdf\u5230\u7684\u8d28\u91cf\u7684\u524d\u63d0\u4e0b\u5b9e\u73b0\u4e86\u8fd9\u4e00\u6548\u679c\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u533b\u7597\u798f\u5229\u7684\u79c1\u6709\u5316\u4ec5\u5e26\u6765\u5fae\u5c0f\u7684\u8282\u7ea6\uff0c\u5e76\u4e0e\u533b\u7597\u8d28\u91cf\u4e0b\u964d\u548c\u6d88\u8d39\u8005\u6ee1\u610f\u5ea6\u964d\u4f4e\u76f8\u5173\u3002\uff08JEL G22, H41, I13, I18, I38\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20231699", "journal": "AER", "title": "Spatial Spillovers of Conflict in Somalia", "authors": ["Marco Alfano", "Thomas Cornelissen"], "author_details": [{"name": "Marco Alfano", "affiliations": ["University of Southampton and RFBerlin (email: )"]}, {"name": "Thomas Cornelissen", "affiliations": ["University of Essex and RFBerlin (email: )"]}], "abstract": "Conflict along transportation routes during Somalia\u2019s al-Shabaab insurgency significantly increases maize prices at distant locations, decreasing food security, health, and education. Estimated conflict risk has strong price effects independently of realized conflict, highlighting the importance of safety concerns. A model of least-cost route choice in the presence of conflict reveals that more and shorter alternative routes to circumvent conflict can lower prices but their effectiveness diminishes as violence becomes more correlated across routes. Alternatively, securing key transportation routes would alleviate price increases. A market access approach suggests spatial spillovers of conflict also matter for prices of more general baskets of food and nonfood items. (JEL D74, I15, I25, O15, O17, Q11, R41)", "date": "2026-06-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20231699", "title_zh": "\u7d22\u9a6c\u91cc\u51b2\u7a81\u7684\u7a7a\u95f4\u6ea2\u51fa\u6548\u5e94", "abstract_zh": "\u7d22\u9a6c\u91cc\u2018\u6c99\u5df4\u5e03\u2019\u53db\u4e71\u671f\u95f4\uff0c\u6cbf\u4ea4\u901a\u8def\u7ebf\u7684\u51b2\u7a81\u663e\u8457\u63d0\u9ad8\u4e86\u504f\u8fdc\u5730\u533a\u7684\u7389\u7c73\u4ef7\u683c\uff0c\u4ece\u800c\u964d\u4f4e\u7cae\u98df\u5b89\u5168\u3001\u5065\u5eb7\u548c\u6559\u80b2\u6c34\u5e73\u3002\u4f30\u7b97\u7684\u51b2\u7a81\u98ce\u9669\u5728\u72ec\u7acb\u4e8e\u5b9e\u9645\u51b2\u7a81\u53d1\u751f\u7684\u60c5\u51b5\u4e0b\uff0c\u5bf9\u4ef7\u683c\u5177\u6709\u663e\u8457\u5f71\u54cd\uff0c\u51f8\u663e\u4e86\u5b89\u5168\u62c5\u5fe7\u7684\u91cd\u8981\u6027\u3002\u5728\u5b58\u5728\u51b2\u7a81\u7684\u60c5\u51b5\u4e0b\uff0c\u5173\u4e8e\u6700\u4f4e\u6210\u672c\u8def\u7ebf\u9009\u62e9\u7684\u6a21\u578b\u8868\u660e\uff0c\u5b58\u5728\u66f4\u591a\u4e14\u66f4\u77ed\u7684\u7ed5\u884c\u8def\u7ebf\u53ef\u4ee5\u964d\u4f4e\u4ef7\u683c\uff0c\u4f46\u5f53\u66b4\u529b\u5728\u4e0d\u540c\u8def\u7ebf\u4e4b\u95f4\u76f8\u5173\u6027\u589e\u5f3a\u65f6\uff0c\u8fd9\u4e9b\u8def\u7ebf\u7684\u6548\u7528\u4f1a\u51cf\u5f31\u3002\u53e6\u4e00\u79cd\u65b9\u6848\u662f\u52a0\u5f3a\u5173\u952e\u4ea4\u901a\u8def\u7ebf\u7684\u5b89\u5168\u6027\uff0c\u4ee5\u7f13\u89e3\u4ef7\u683c\u4e0a\u6da8\u3002\u57fa\u4e8e\u5e02\u573a\u51c6\u5165\u7684\u5206\u6790\u8868\u660e\uff0c\u51b2\u7a81\u7684\u7a7a\u95f4\u6ea2\u51fa\u6548\u5e94\u4e5f\u4f1a\u5f71\u54cd\u66f4\u5e7f\u6cdb\u7684\u98df\u7269\u53ca\u975e\u98df\u7269\u5546\u54c1\u7684\u4ef7\u683c\u3002\uff08JEL D74, I15, I25, O15, O17, Q11, R41\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20230017", "journal": "AER", "title": "Mergers, Foreign Competition, and Jobs: Evidence from the US Appliance Industry", "authors": ["Felix Montag"], "author_details": [{"name": "Felix Montag", "affiliations": ["NYU Stern School of Business and CEPR (email: )"]}], "abstract": "Policy choices often create trade-offs between workers and consumers. I examine how foreign competition alters the consumer welfare and domestic employment effects of mergers. I construct a model incorporating consumer demand, endogenous product portfolios, and employment decisions. Applying the model to Whirlpool\u2019s acquisition of Maytag in the appliance industry, I compare the observed merger to a counterfactual acquisition by a foreign buyer. Although Whirlpool\u2019s acquisition decreased consumer welfare by $271 million annually, it preserved 797 domestic jobs. These jobs must therefore be valued at more than $344, 000 per year for the domestic employment benefits to offset the consumer harm. (JEL E24, F23, G34, J30, L13, L68, R23)", "date": "2026-06-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230017", "title_zh": "\u5e76\u8d2d\u3001\u5916\u56fd\u7ade\u4e89\u4e0e\u5c31\u4e1a\uff1a\u6765\u81ea\u7f8e\u56fd\u5bb6\u7535\u884c\u4e1a\u7684\u8bc1\u636e", "abstract_zh": "\u653f\u7b56\u9009\u62e9\u5f80\u5f80\u5728\u5de5\u4eba\u548c\u6d88\u8d39\u8005\u4e4b\u95f4\u4ea7\u751f\u6743\u8861\u3002\u672c\u6587\u7814\u7a76\u4e86\u5916\u56fd\u7ade\u4e89\u5982\u4f55\u6539\u53d8\u5e76\u8d2d\u5bf9\u6d88\u8d39\u8005\u798f\u5229\u548c\u56fd\u5185\u5c31\u4e1a\u7684\u5f71\u54cd\u3002\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u6d88\u8d39\u8005\u9700\u6c42\u3001\u5185\u751f\u4ea7\u54c1\u7ec4\u5408\u4ee5\u53ca\u5c31\u4e1a\u51b3\u7b56\u7684\u6a21\u578b\u3002\u5c06\u8be5\u6a21\u578b\u5e94\u7528\u4e8e\u60e0\u800c\u6d66\u6536\u8d2dMaytag\u7684\u5bb6\u7535\u884c\u4e1a\u6848\u4f8b\uff0c\u6211\u5c06\u5176\u4e0e\u7531\u5916\u56fd\u4e70\u5bb6\u8fdb\u884c\u7684\u6536\u8d2d\u60c5\u666f\u8fdb\u884c\u4e86\u5bf9\u6bd4\u3002\u5c3d\u7ba1\u60e0\u800c\u6d66\u7684\u6536\u8d2d\u6bcf\u5e74\u4f7f\u6d88\u8d39\u8005\u798f\u5229\u51cf\u5c11\u4e862.71\u4ebf\u7f8e\u5143\uff0c\u4f46\u5176\u4fdd\u7559\u4e86797\u4e2a\u56fd\u5185\u5c31\u4e1a\u5c97\u4f4d\u3002\u56e0\u6b64\uff0c\u8fd9\u4e9b\u5c31\u4e1a\u5c97\u4f4d\u7684\u5e74\u5ea6\u4ef7\u503c\u5fc5\u987b\u8d85\u8fc734.4\u4e07\u7f8e\u5143\uff0c\u624d\u80fd\u62b5\u6d88\u5bf9\u6d88\u8d39\u8005\u9020\u6210\u7684\u635f\u5bb3\u3002\uff08JEL E24, F23, G34, J30, L13, L68, R23\uff09", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u5e76\u8d2d"]}, {"doi": "10.1257/aer.20231344", "journal": "AER", "title": "Friendship Networks and Political Opinions", "authors": ["Yann Algan", "Nicol\u00f2 Dalvit", "Quoc-Anh Do", "Alexis Le Chapelain", "Yves Zenou"], "author_details": [{"name": "Yann Algan", "affiliations": ["HEC and CEPR (email: )"]}, {"name": "Nicol\u00f2 Dalvit", "affiliations": ["World Bank (email: )"]}, {"name": "Quoc-Anh Do", "affiliations": ["Monash University, CEPR, and CESifo (email: )"]}, {"name": "Alexis Le Chapelain", "affiliations": ["(email: )"]}, {"name": "Yves Zenou", "affiliations": ["Monash University, University of Southampton, and CEPR (email: )"]}], "abstract": "We examine how social interactions and friendships shape students\u2019 political opinions in a natural experiment at Sciences Po, a leading French university specializing in social and political sciences. The quasi-random assignment of students into short-term integration groups before their academic curriculum reduces political opinion gaps and fosters friendship formation. Using same-group membership as an instrumental variable for friendship, we find that friendship reduces opinion differences by 44 percent of the mean opinion gap. Our evidence supports a homophily-enforced mechanism: Friendships form among initially politically similar students, leading them to join political associations together, reinforcing their similarity. (JEL C93, D72, Z13)", "date": "2026-06-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20231344", "title_zh": "\u53cb\u8c0a\u7f51\u7edc\u4e0e\u653f\u6cbb\u89c2\u70b9", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u793e\u4f1a\u4e92\u52a8\u548c\u53cb\u8c0a\u5982\u4f55\u5f71\u54cd Sciences Po \u5927\u5b66\u5b66\u751f\u653f\u6cbb\u89c2\u70b9\uff0c\u8be5\u5927\u5b66\u662f\u6cd5\u56fd\u4e00\u6240\u4e13\u6ce8\u4e8e\u793e\u4f1a\u79d1\u5b66\u548c\u653f\u6cbb\u79d1\u5b66\u7684\u9876\u5c16\u5927\u5b66\u3002\u5728\u5b66\u751f\u6b63\u5f0f\u8fdb\u5165\u5b66\u672f\u8bfe\u7a0b\u524d\uff0c\u901a\u8fc7\u77ed\u671f\u6574\u5408\u5c0f\u7ec4\u7684\u51c6\u968f\u673a\u5206\u914d\uff0c\u51cf\u5c11\u4e86\u5b66\u751f\u4e4b\u95f4\u7684\u653f\u6cbb\u89c2\u70b9\u5dee\u5f02\u5e76\u4fc3\u8fdb\u4e86\u53cb\u8c0a\u7684\u5f62\u6210\u3002\u5229\u7528\u540c\u7ec4\u6210\u5458\u8eab\u4efd\u4f5c\u4e3a\u53cb\u8c0a\u7684\u5de5\u5177\u53d8\u91cf\uff0c\u6211\u4eec\u53d1\u73b0\u53cb\u8c0a\u5c06\u89c2\u70b9\u5dee\u5f02\u51cf\u5c11\u4e86\u5e73\u5747\u89c2\u70b9\u5dee\u8ddd\u768444%\u3002\u6211\u4eec\u7684\u8bc1\u636e\u652f\u6301\u4e86\u4e00\u79cd\u7531\u76f8\u4f3c\u6027\u9a71\u52a8\u7684\u673a\u5236\uff1a\u53cb\u8c0a\u5728\u6700\u521d\u653f\u6cbb\u89c2\u70b9\u76f8\u4f3c\u7684\u5b66\u751f\u4e4b\u95f4\u5f62\u6210\uff0c\u4fc3\u4f7f\u4ed6\u4eec\u5171\u540c\u52a0\u5165\u653f\u6cbb\u7ec4\u7ec7\uff0c\u4ece\u800c\u8fdb\u4e00\u6b65\u5f3a\u5316\u4e86\u4ed6\u4eec\u7684\u76f8\u4f3c\u6027\u3002\uff08JEL C93, D72, Z13\uff09", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1257/aer.20221351", "journal": "AER", "title": "Identifying Preference for Early Resolution from Asset Prices", "authors": ["Hengjie Ai", "Ravi Bansal", "Hongye Guo", "Amir Yaron"], "author_details": [{"name": "Hengjie Ai", "affiliations": ["University of Wisconsin-Madison (email: )"]}, {"name": "Ravi Bansal", "affiliations": ["Duke University and NBER (email: )"]}, {"name": "Hongye Guo", "affiliations": ["University of Hong Kong (email: )"]}, {"name": "Amir Yaron", "affiliations": ["Bank of Israel (email: )"]}], "abstract": "This paper develops an asset market-based test for preference for the timing of resolution of uncertainty. Our main theorem provides a characterization of preference for early resolution of uncertainty in terms of the risk premium realized during the period when the informativeness of macroeconomic announcements is resolved. Empirically, we find support for preference for early resolution of uncertainty based on evidence on the dynamics of the implied volatility of S&P 500 index options before Federal Open Market Committee announcements. (JEL D81, D83, G13, G14, G41)", "date": "2026-06-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20221351", "title_zh": "\u4ece\u8d44\u4ea7\u4ef7\u683c\u8bc6\u522b\u5bf9\u65e9\u671f\u89e3\u51b3\u4e0d\u786e\u5b9a\u6027\u7684\u504f\u597d", "abstract_zh": "\u672c\u6587\u6784\u5efa\u4e86\u4e00\u4e2a\u57fa\u4e8e\u8d44\u4ea7\u5e02\u573a\u7684\u6d4b\u8bd5\u65b9\u6cd5\uff0c\u7528\u4e8e\u68c0\u9a8c\u5bf9\u4e0d\u786e\u5b9a\u6027\u89e3\u51b3\u65f6\u673a\u7684\u504f\u597d\u3002\u6211\u4eec\u7684\u4e3b\u8981\u5b9a\u7406\u5c06\u5bf9\u65e9\u671f\u89e3\u51b3\u4e0d\u786e\u5b9a\u6027\u7684\u504f\u597d\u8868\u8ff0\u4e3a\u5728\u5b8f\u89c2\u7ecf\u6d4e\u516c\u544a\u4fe1\u606f\u542b\u91cf\u88ab\u786e\u5b9a\u671f\u95f4\u6240\u5b9e\u73b0\u7684\u98ce\u9669\u6ea2\u4ef7\u3002\u5b9e\u8bc1\u4e0a\uff0c\u6211\u4eec\u57fa\u4e8e\u6807\u666e500\u6307\u6570\u671f\u6743\u9690\u542b\u6ce2\u52a8\u7387\u5728\u7f8e\u8054\u50a8\u516c\u5f00\u5e02\u573a\u59d4\u5458\u4f1a\u516c\u544a\u524d\u7684\u52a8\u6001\u53d8\u5316\uff0c\u53d1\u73b0\u4e86\u5bf9\u65e9\u671f\u89e3\u51b3\u4e0d\u786e\u5b9a\u6027\u7684\u504f\u597d\u7684\u652f\u6301\u3002\uff08JEL D81, D83, G13, G14, G41\uff09", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1257/aer.20230766", "journal": "AER", "title": "Quality Adjustment at Scale: Hedonic versus Exact Demand-Based Price Indices", "authors": ["Gabriel Ehrlich", "John Haltiwanger", "Ron Jarmin", "David Johnson", "Ed Olivares", "Luke Pardue", "Matthew D. Shapiro", "Laura Yi Zhao"], "author_details": [{"name": "Gabriel Ehrlich", "affiliations": ["University of Michigan (email: )"]}, {"name": "John Haltiwanger", "affiliations": ["University of Maryland and NBER (email: )"]}, {"name": "Ron Jarmin", "affiliations": ["US Census Bureau (email: )"]}, {"name": "David Johnson", "affiliations": ["University of Michigan and International Association for Research in Income and Wealth (email: )"]}, {"name": "Ed Olivares", "affiliations": ["University of Maryland and US Treasury (email: )"]}, {"name": "Luke Pardue", "affiliations": ["University of Maryland and Aspen Economic Strategy Group (email: )"]}, {"name": "Matthew D. Shapiro", "affiliations": ["University of Michigan and NBER (email: )"]}, {"name": "Laura Yi Zhao", "affiliations": ["University of Maryland and Bank of Canada (email: )"]}], "abstract": "Item-level transactions data yield cost-of-living indices that can account for quality change and consumer substitution. Transactions data require confronting the rapid turnover of items because prices of new and existing products are interrelated in equilibrium. This paper evaluates multiple approaches to measuring quality change at scale. It shows that a hedonic superlative approach\u2014using econometrics or machine learning for hedonic estimation combined with index formulas that require simultaneous observation of item-level price and expenditure\u2014yields improved measures of the cost of living. Accounting for ubiquitous quality change and for consumer substitution yields lower measures of inflation than traditional, official methods. (JEL C43, C45, E31, L15, L81)", "date": "2026-06-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230766", "title_zh": "\u5927\u89c4\u6a21\u573a\u666f\u4e0b\u7684\u8d28\u91cf\u8c03\u6574\uff1a\u4eab\u4e50\u6cd5\u4e0e\u7cbe\u786e\u9700\u6c42\u57fa\u7840\u4ef7\u683c\u6307\u6570\u7684\u6bd4\u8f83", "abstract_zh": "\u5546\u54c1\u7ea7\u4ea4\u6613\u6570\u636e\u80fd\u591f\u751f\u6210\u8003\u8651\u8d28\u91cf\u53d8\u5316\u548c\u6d88\u8d39\u8005\u66ff\u4ee3\u884c\u4e3a\u7684\u751f\u6d3b\u6210\u672c\u6307\u6570\u3002\u4ea4\u6613\u6570\u636e\u9700\u8981\u5e94\u5bf9\u5546\u54c1\u5feb\u901f\u66f4\u66ff\u7684\u95ee\u9898\uff0c\u56e0\u4e3a\u65b0\u65e7\u5546\u54c1\u7684\u4ef7\u683c\u5728\u5747\u8861\u72b6\u6001\u4e0b\u662f\u76f8\u4e92\u5173\u8054\u7684\u3002\u672c\u6587\u8bc4\u4f30\u4e86\u591a\u79cd\u5728\u5927\u89c4\u6a21\u573a\u666f\u4e0b\u8861\u91cf\u8d28\u91cf\u53d8\u5316\u7684\u65b9\u6cd5\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u91c7\u7528\u4eab\u4e50\u6cd5\u8d85\u7ef4\u65b9\u6cd5\u2014\u2014\u5373\u5229\u7528\u8ba1\u91cf\u7ecf\u6d4e\u5b66\u6216\u673a\u5668\u5b66\u4e60\u8fdb\u884c\u4eab\u4e50\u4f30\u8ba1\uff0c\u5e76\u7ed3\u5408\u9700\u8981\u540c\u65f6\u89c2\u5bdf\u5546\u54c1\u7ea7\u4ef7\u683c\u548c\u652f\u51fa\u7684\u6307\u6570\u516c\u5f0f\u2014\u2014\u80fd\u591f\u83b7\u5f97\u66f4\u51c6\u786e\u7684\u751f\u6d3b\u6210\u672c\u8861\u91cf\u3002\u8003\u8651\u5230\u8d28\u91cf\u53d8\u5316\u7684\u666e\u904d\u6027\u4ee5\u53ca\u6d88\u8d39\u8005\u66ff\u4ee3\u884c\u4e3a\uff0c\u6240\u5f97\u7684\u901a\u80c0\u7387\u4f4e\u4e8e\u4f20\u7edf\u5b98\u65b9\u65b9\u6cd5\u3002\uff08JEL C43, C45, E31, L15, L81\uff09", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1257/aer.20230802", "journal": "AER", "title": "Elite Universities and the Intergenerational Transmission of Human and Social Capital", "authors": ["Andr\u00e9s Barrios-Fern\u00e1ndez", "Christopher Neilson", "Seth Zimmerman"], "author_details": [{"name": "Andr\u00e9s Barrios-Fern\u00e1ndez", "affiliations": ["Universidad de los Andes (email: )"]}, {"name": "Christopher Neilson", "affiliations": ["Yale University (email: )"]}, {"name": "Seth Zimmerman", "affiliations": ["Yale University (email: )"]}], "abstract": "Do elite colleges help talented students join the social elite or help incumbent elites retain their positions? We combine intergenerationally linked data from Chile with a regression discontinuity design to show that, looking across generations, elite colleges do both. Lower-status individuals who gain admission to elite college programs transform their children\u2019s social environment. Children become more likely to attend high-status private schools and colleges and to live near and befriend high-status peers. In contrast, academic achievement is unaffected. Simulations combining descriptive and quasi-experimental findings show that elite colleges tighten the link between social and human capital while decreasing intergenerational social mobility. (JEL I23, I26, J24, J62, O15, Z13)", "date": "2026-06-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230802", "title_zh": "\u7cbe\u82f1\u5927\u5b66\u4e0e\u4eba\u529b\u8d44\u672c\u548c\u793e\u4f1a\u8d44\u672c\u7684\u4ee3\u9645\u4f20\u9012", "abstract_zh": "\u7cbe\u82f1\u5927\u5b66\u662f\u5e2e\u52a9\u6709\u624d\u80fd\u7684\u5b66\u751f\u8fdb\u5165\u793e\u4f1a\u7cbe\u82f1\u9636\u5c42\uff0c\u8fd8\u662f\u5e2e\u52a9\u73b0\u6709\u7cbe\u82f1\u7ef4\u6301\u5176\u5730\u4f4d\uff1f\u6211\u4eec\u7ed3\u5408\u667a\u5229\u7684\u4ee3\u9645\u5173\u8054\u6570\u636e\uff0c\u5e76\u91c7\u7528\u56de\u5f52\u65ad\u70b9\u8bbe\u8ba1\uff0c\u53d1\u73b0\u4ece\u4ee3\u9645\u89d2\u5ea6\u770b\uff0c\u7cbe\u82f1\u5927\u5b66\u786e\u5b9e\u505a\u5230\u4e86\u8fd9\u4e24\u70b9\u3002\u5730\u4f4d\u8f83\u4f4e\u7684\u4e2a\u4f53\u8fdb\u5165\u7cbe\u82f1\u5927\u5b66\u9879\u76ee\u540e\uff0c\u5176\u5b50\u5973\u7684\u793e\u4f1a\u73af\u5883\u53d1\u751f\u6539\u53d8\u3002\u5b50\u5973\u66f4\u53ef\u80fd\u8fdb\u5165\u9ad8\u5730\u4f4d\u7684\u79c1\u7acb\u5b66\u6821\u548c\u5927\u5b66\uff0c\u5e76\u4e0e\u9ad8\u5730\u4f4d\u7684\u540c\u9f84\u4eba\u5c45\u4f4f\u548c\u4ea4\u5f80\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u5b66\u672f\u6210\u5c31\u5e76\u672a\u53d7\u5230\u5f71\u54cd\u3002\u7ed3\u5408\u63cf\u8ff0\u6027\u5206\u6790\u548c\u51c6\u5b9e\u9a8c\u7814\u7a76\u7684\u6a21\u62df\u7ed3\u679c\u8868\u660e\uff0c\u7cbe\u82f1\u5927\u5b66\u52a0\u5f3a\u4e86\u793e\u4f1a\u8d44\u672c\u4e0e\u4eba\u529b\u8d44\u672c\u4e4b\u95f4\u7684\u8054\u7cfb\uff0c\u540c\u65f6\u964d\u4f4e\u4e86\u4ee3\u9645\u793e\u4f1a\u6d41\u52a8\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70047", "journal": "JF", "title": "Detecting Informed Trading Risk from Undercutting Activity", "authors": ["YASHAR H. BARARDEHI", "PETER DIXON", "QIYU LIU"], "author_details": [{"name": "YASHAR H. BARARDEHI", "affiliations": []}, {"name": "PETER DIXON", "affiliations": []}, {"name": "QIYU LIU", "affiliations": []}], "abstract": "ABSTRACT We introduce a simple measure of informed trading risk, , the residual to liquidity quote\u2010improvement\u2010to\u2010deterioration ratio times . When facing with increased informed trading risk, liquidity providers compete less to provide liquidity, reducing their undercutting activity. Reductions in undercutting leave footprints in trade and quote data that are captured by . Unlike prior measures, is easy to construct, can be computed intraday, and is orthogonal to liquidity. The measure outperforms prominent existing alternatives in reflecting the extent of information asymmetry before earnings announcements, predicting unscheduled press releases, and identifying informed trading spillovers around them.", "date": "2026-06-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70047", "title_zh": "\u4ece undercutting \u6d3b\u52a8\u4e2d\u68c0\u6d4b\u77e5\u60c5\u4ea4\u6613\u98ce\u9669", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5f15\u5165\u4e86\u4e00\u4e2a\u7b80\u5355\u7684\u77e5\u60c5\u4ea4\u6613\u98ce\u9669\u5ea6\u91cf\u65b9\u6cd5\uff0c\u5373\u6d41\u52a8\u6027\u62a5\u4ef7\u6539\u5584\u4e0e\u6076\u5316\u6bd4\u7387\u7684\u6b8b\u5dee\u4e58\u4ee5\u3002\u5f53\u9762\u4e34\u77e5\u60c5\u4ea4\u6613\u98ce\u9669\u4e0a\u5347\u65f6\uff0c\u6d41\u52a8\u6027\u63d0\u4f9b\u8005\u63d0\u4f9b\u6d41\u52a8\u6027\u7684\u7ade\u4e89\u51cf\u5c11\uff0c\u5176 undercutting \u6d3b\u52a8\u4e5f\u968f\u4e4b\u4e0b\u964d\u3002\u8fd9\u79cd undercutting \u6d3b\u52a8\u7684\u51cf\u5c11\u5728\u4ea4\u6613\u548c\u62a5\u4ef7\u6570\u636e\u4e2d\u7559\u4e0b\u4e86\u75d5\u8ff9\uff0c\u8fd9\u4e9b\u75d5\u8ff9\u88ab\u6240\u6355\u6349\u3002\u4e0e\u4ee5\u5f80\u7684\u5ea6\u91cf\u65b9\u6cd5\u4e0d\u540c\uff0c\u8be5\u65b9\u6cd5\u6613\u4e8e\u6784\u5efa\uff0c\u53ef\u4ee5\u5b9e\u73b0\u65e5\u5185\u8ba1\u7b97\uff0c\u5e76\u4e14\u4e0e\u6d41\u52a8\u6027\u76f8\u4e92\u72ec\u7acb\u3002\u8be5\u5ea6\u91cf\u65b9\u6cd5\u5728\u53cd\u6620\u8d22\u62a5\u516c\u544a\u524d\u7684\u4fe1\u606f\u4e0d\u5bf9\u79f0\u7a0b\u5ea6\u3001\u9884\u6d4b\u975e\u8ba1\u5212\u6027\u65b0\u95fb\u53d1\u5e03\u4ee5\u53ca\u8bc6\u522b\u516c\u544a\u5468\u8fb9\u7684\u77e5\u60c5\u4ea4\u6613\u6ea2\u51fa\u6548\u5e94\u65b9\u9762\uff0c\u4f18\u4e8e\u73b0\u6709\u7684\u4e3b\u8981\u66ff\u4ee3\u65b9\u6cd5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70059", "journal": "JF", "title": "Cash Heterogeneity and the Payout Channel of Monetary Policy", "authors": ["ALTAN PAZARBA\u015eI"], "author_details": [{"name": "ALTAN PAZARBA\u015eI", "affiliations": []}], "abstract": "ABSTRACT This paper provides novel empirical evidence that cash\u2010rich firms have higher equity payouts and higher stock prices in response to expansionary monetary policy surprises. Stock prices rise despite weak cash\u2010flow, investment, and credit responses to monetary policy. I rationalize the empirical evidence in a heterogeneous\u2010firm New Keynesian model where firms finance investment with cash and equity issuance. Monetary easing weakens precautionary cash demand, leading cash\u2010rich firms to optimally allocate excess funds to shareholders. Since payouts are procyclical, cash\u2010rich firms earn higher returns in expansionary periods. My findings highlight a payout channel through which monetary policy impacts asset prices.", "date": "2026-06-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70059", "title_zh": "\u73b0\u91d1\u5f02\u8d28\u6027\u4e0e\u8d27\u5e01\u653f\u7b56\u7684\u5206\u7ea2\u6e20\u9053", "abstract_zh": "\u672c\u6587\u63d0\u4f9b\u4e86\u65b0\u7684\u5b9e\u8bc1\u8bc1\u636e\uff0c\u8868\u660e\u73b0\u91d1\u5145\u88d5\u7684\u4f01\u4e1a\u5728\u9762\u5bf9\u6269\u5f20\u6027\u8d27\u5e01\u653f\u7b56\u610f\u5916\u65f6\uff0c\u5176\u80a1\u6743\u5206\u7ea2\u548c\u80a1\u4ef7\u6c34\u5e73\u66f4\u9ad8\u3002\u5c3d\u7ba1\u73b0\u91d1\u6d41\u3001\u6295\u8d44\u548c\u4fe1\u8d37\u5bf9\u8d27\u5e01\u653f\u7b56\u7684\u53cd\u5e94\u8f83\u5f31\uff0c\u80a1\u4ef7\u4ecd\u4f1a\u4e0a\u5347\u3002\u6211\u5728\u4e00\u4e2a\u5f02\u8d28\u6027\u4f01\u4e1a\u7684\u65b0\u51ef\u6069\u65af\u6a21\u578b\u4e2d\u89e3\u91ca\u4e86\u8fd9\u4e00\u5b9e\u8bc1\u73b0\u8c61\uff1a\u4f01\u4e1a\u901a\u8fc7\u73b0\u91d1\u548c\u80a1\u6743\u53d1\u884c\u6765\u878d\u8d44\u6295\u8d44\u3002\u8d27\u5e01\u653f\u7b56\u5bbd\u677e\u4f1a\u964d\u4f4e\u4f01\u4e1a\u7684\u9884\u9632\u6027\u73b0\u91d1\u9700\u6c42\uff0c\u5bfc\u81f4\u73b0\u91d1\u5145\u88d5\u7684\u4f01\u4e1a\u5c06\u591a\u4f59\u7684\u73b0\u91d1\u6700\u4f18\u5730\u5206\u914d\u7ed9\u80a1\u4e1c\u3002\u7531\u4e8e\u5206\u7ea2\u5177\u6709\u5468\u671f\u6027\uff0c\u73b0\u91d1\u5145\u88d5\u7684\u4f01\u4e1a\u5728\u6269\u5f20\u671f\u83b7\u5f97\u66f4\u9ad8\u7684\u56de\u62a5\u3002\u6211\u7684\u7814\u7a76\u63ed\u793a\u4e86\u8d27\u5e01\u653f\u7b56\u901a\u8fc7\u5206\u7ea2\u6e20\u9053\u5f71\u54cd\u8d44\u4ea7\u4ef7\u683c\u7684\u673a\u5236\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1017/s0022109026103032", "journal": "JFQA", "title": "Resolution Design and Investment in Banking Groups", "authors": ["Albert Banal-Esta\u00f1ol", "Gy\u00f6ngyi L\u00f3r\u00e1nth", "David Pothier"], "author_details": [{"name": "Albert Banal-Esta\u00f1ol", "affiliations": ["Universitat Pompeu Fabra"]}, {"name": "Gy\u00f6ngyi L\u00f3r\u00e1nth", "affiliations": ["University of Vienna"]}, {"name": "David Pothier", "affiliations": ["University of Vienna"]}], "abstract": "Abstract We study how resolution regimes affect investment in banking groups with subsidiaries of varying financial strength. Centralized regimes that preserve the group\u2019s structure enable ex post support for weaker units but may constrain ex ante investment. Decentralized regimes that resolve units separately may enhance ex ante investment but limit risk-sharing ex post. The relative efficiency of each approach depends on the group\u2019s risk profile and profitability. Allowing both regimes to coexist improves efficiency relative to imposing a uniform regime across all groups. However, a decentralized regime may not be credible if the regulator cannot commit to limit ex post risk-sharing.", "date": "2026-06-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103032", "title_zh": "\u5316\u89e3\u8bbe\u8ba1\u4e0e\u94f6\u884c\u96c6\u56e2\u6295\u8d44", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5316\u89e3\u5236\u5ea6\u5982\u4f55\u5f71\u54cd\u5177\u6709\u4e0d\u540c\u91d1\u878d\u5b9e\u529b\u5b50\u516c\u53f8\u7684\u94f6\u884c\u96c6\u56e2\u7684\u6295\u8d44\u884c\u4e3a\u3002\u96c6\u4e2d\u5316\u5236\u5ea6\u4fdd\u6301\u96c6\u56e2\u7ed3\u6784\uff0c\u6709\u52a9\u4e8e\u4e8b\u540e\u7684\u5f31\u5355\u4f4d\u652f\u6301\uff0c\u4f46\u53ef\u80fd\u9650\u5236\u4e8b\u524d\u6295\u8d44\u3002\u53bb\u4e2d\u5fc3\u5316\u5236\u5ea6\u5c06\u5404\u5355\u4f4d\u5355\u72ec\u5316\u89e3\uff0c\u53ef\u80fd\u4fc3\u8fdb\u4e8b\u524d\u6295\u8d44\uff0c\u4f46\u4f1a\u9650\u5236\u4e8b\u540e\u98ce\u9669\u5206\u62c5\u3002\u4e24\u79cd\u5236\u5ea6\u7684\u76f8\u5bf9\u6548\u7387\u53d6\u51b3\u4e8e\u96c6\u56e2\u7684\u98ce\u9669\u7279\u5f81\u548c\u76c8\u5229\u80fd\u529b\u3002\u5141\u8bb8\u4e24\u79cd\u5236\u5ea6\u5e76\u5b58\uff0c\u76f8\u6bd4\u5bf9\u6240\u6709\u96c6\u56e2\u5b9e\u65bd\u7edf\u4e00\u5236\u5ea6\uff0c\u80fd\u63d0\u5347\u6574\u4f53\u6548\u7387\u3002\u7136\u800c\uff0c\u5982\u679c\u76d1\u7ba1\u673a\u6784\u65e0\u6cd5\u627f\u8bfa\u9650\u5236\u4e8b\u540e\u98ce\u9669\u5206\u62c5\uff0c\u53bb\u4e2d\u5fc3\u5316\u5236\u5ea6\u53ef\u80fd\u7f3a\u4e4f\u53ef\u4fe1\u5ea6\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026103020", "journal": "JFQA", "title": "Pension Fund Equity Investment and Firm Productivity", "authors": ["Roel Beetsma", "Svend Erik Hougaard Jensen", "David Pinkus", "Dario Pozzoli"], "author_details": [{"name": "Roel Beetsma", "affiliations": ["University of Amsterdam"]}, {"name": "Svend Erik Hougaard Jensen", "affiliations": ["Copenhagen Business School"]}, {"name": "David Pinkus", "affiliations": ["Coller Pensions Institute"]}, {"name": "Dario Pozzoli", "affiliations": ["Copenhagen Business School"]}], "abstract": "Abstract This article examines how domestic pension fund equity investment relates to productivity in unlisted firms, using detailed ownership data linked to Danish administrative registers. Pension fund entry is associated with a 3%\u20135% higher level of productivity in the years following entry. The association is stronger when pension funds hold larger stakes, invest for longer, and are closer in the ownership chain. Pension fund entry is also associated with a subsequent increase in the number of a firm\u2019s additional investors. We find no investment productivity association for listed firms.", "date": "2026-06-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026103020", "title_zh": "\u517b\u8001\u91d1\u57fa\u91d1\u80a1\u6743\u6295\u8d44\u4e0e\u4f01\u4e1a\u751f\u4ea7\u7387", "abstract_zh": "\u672c\u6587\u5229\u7528\u4e0e\u4e39\u9ea6\u884c\u653f\u8bb0\u5f55\u5173\u8054\u7684\u8be6\u7ec6\u6301\u80a1\u6570\u636e\uff0c\u7814\u7a76\u4e86\u56fd\u5185\u517b\u8001\u91d1\u57fa\u91d1\u80a1\u6743\u6295\u8d44\u5bf9\u4f01\u4e1a\u751f\u4ea7\u7387\u7684\u5f71\u54cd\u3002\u517b\u8001\u91d1\u57fa\u91d1\u8fdb\u5165\u540e\uff0c\u4f01\u4e1a\u751f\u4ea7\u7387\u5728\u968f\u540e\u51e0\u5e74\u63d0\u9ad8\u4e863%\u81f35%\u3002\u5f53\u517b\u8001\u91d1\u57fa\u91d1\u6301\u80a1\u6bd4\u4f8b\u66f4\u5927\u3001\u6295\u8d44\u65f6\u95f4\u66f4\u957f\uff0c\u4e14\u5728\u6240\u6709\u6743\u94fe\u6761\u4e2d\u66f4\u63a5\u8fd1\u4f01\u4e1a\u65f6\uff0c\u8fd9\u79cd\u5173\u8054\u6027\u66f4\u5f3a\u3002\u517b\u8001\u91d1\u57fa\u91d1\u7684\u8fdb\u5165\u8fd8\u4e0e\u4f01\u4e1a\u65b0\u589e\u6295\u8d44\u8005\u6570\u91cf\u7684\u589e\u52a0\u76f8\u5173\u3002\u5bf9\u4e8e\u4e0a\u5e02\u4f01\u4e1a\uff0c\u6211\u4eec\u672a\u53d1\u73b0\u6295\u8d44\u4e0e\u751f\u4ea7\u7387\u4e4b\u95f4\u7684\u5173\u8054\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1093/qje/qjag029", "journal": "QJE", "title": "Business, Liquidity, and Information Cycles", "authors": ["Gorkem Bostanci", "Guillermo Ordo\u00f1ez"], "author_details": [{"name": "Gorkem Bostanci", "affiliations": ["University of British Columbia ,"]}, {"name": "Guillermo Ordo\u00f1ez", "affiliations": ["University of Pennsylvania and National Bureau of Economic Research ,"]}], "abstract": "Abstract Stock markets play a dual role: they provide information about firms\u2019 fundamentals, which improves resource allocations, and they provide liquidity. We propose a setting in which these two roles interact: if stocks are used more intensively for liquidity, then prices reveal less information about fundamentals. We structurally estimate stock price informativeness for several countries and show that it declines when alternative liquidity sources, such as banks, are in distress. To study the real effects of this mechanism, we devise a strategy to integrate our stock-trading module into a dynamic general equilibrium model with heterogeneous firms. We calibrate the model to the United States and simulate recessions with and without banking distress. In a standalone recession, prices become more informative and allocation improves, mitigating output losses by 4.4%. If the recession coincides with banking distress, agents rely more on stock markets to obtain liquidity, prices become less informative, and allocation deteriorates, magnifying output losses by 22%.", "date": "2026-05-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag029", "title_zh": "\u4f01\u4e1a\u3001\u6d41\u52a8\u6027\u4e0e\u4fe1\u606f\u5468\u671f", "abstract_zh": "\u80a1\u7968\u5e02\u573a\u5177\u6709\u53cc\u91cd\u529f\u80fd\uff1a\u4e00\u65b9\u9762\u63d0\u4f9b\u5173\u4e8e\u4f01\u4e1a\u57fa\u672c\u9762\u7684\u4fe1\u606f\uff0c\u4ece\u800c\u6539\u5584\u8d44\u6e90\u914d\u7f6e\uff1b\u53e6\u4e00\u65b9\u9762\u63d0\u4f9b\u6d41\u52a8\u6027\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u4e24\u8005\u7684\u76f8\u4e92\u4f5c\u7528\u673a\u5236\uff1a\u5982\u679c\u80a1\u7968\u88ab\u66f4\u591a\u5730\u7528\u4e8e\u6d41\u52a8\u6027\u9700\u6c42\uff0c\u5219\u4ef7\u683c\u6240\u63ed\u793a\u7684\u57fa\u672c\u9762\u4fe1\u606f\u4f1a\u51cf\u5c11\u3002\u6211\u4eec\u57fa\u4e8e\u7ed3\u6784\u6a21\u578b\u5bf9\u591a\u4e2a\u56fd\u5bb6\u7684\u80a1\u4ef7\u4fe1\u606f\u542b\u91cf\u8fdb\u884c\u4e86\u4f30\u8ba1\uff0c\u7ed3\u679c\u8868\u660e\uff0c\u5f53\u94f6\u884c\u7b49\u5176\u4ed6\u6d41\u52a8\u6027\u6765\u6e90\u51fa\u73b0\u56f0\u5883\u65f6\uff0c\u80a1\u4ef7\u7684\u4fe1\u606f\u542b\u91cf\u4f1a\u4e0b\u964d\u3002\u4e3a\u4e86\u7814\u7a76\u8fd9\u4e00\u673a\u5236\u7684\u73b0\u5b9e\u5f71\u54cd\uff0c\u6211\u4eec\u8bbe\u8ba1\u4e86\u4e00\u79cd\u7b56\u7565\uff0c\u5c06\u6211\u4eec\u7684\u80a1\u7968\u4ea4\u6613\u6a21\u5757\u878d\u5165\u4e00\u4e2a\u5305\u542b\u5f02\u8d28\u6027\u4f01\u4e1a\u7684\u52a8\u6001\u4e00\u822c\u5747\u8861\u6a21\u578b\u4e2d\u3002\u6211\u4eec\u5c06\u6a21\u578b\u6821\u51c6\u81f3\u7f8e\u56fd\uff0c\u5e76\u6a21\u62df\u4e86\u5305\u542b\u548c\u4e0d\u5305\u542b\u94f6\u884c\u56f0\u5883\u7684\u7ecf\u6d4e\u8870\u9000\u60c5\u666f\u3002\u5728\u5355\u72ec\u7684\u7ecf\u6d4e\u8870\u9000\u4e2d\uff0c\u4ef7\u683c\u53d8\u5f97\u66f4\u52a0\u5177\u6709\u4fe1\u606f\u542b\u91cf\uff0c\u8d44\u6e90\u914d\u7f6e\u5f97\u5230\u6539\u5584\uff0c\u4ece\u800c\u5c06\u4ea7\u51fa\u635f\u5931\u51cf\u5c11\u4e864.4%\u3002\u5982\u679c\u7ecf\u6d4e\u8870\u9000\u540c\u65f6\u4f34\u968f\u7740\u94f6\u884c\u56f0\u5883\uff0c\u6295\u8d44\u8005\u66f4\u591a\u4f9d\u8d56\u80a1\u7968\u5e02\u573a\u83b7\u53d6\u6d41\u52a8\u6027\uff0c\u4ef7\u683c\u4fe1\u606f\u542b\u91cf\u4e0b\u964d\uff0c\u8d44\u6e90\u914d\u7f6e\u6076\u5316\uff0c\u4ea7\u51fa\u635f\u5931\u56e0\u6b64\u6269\u5927\u4e8622%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e02\u573a\u53cd\u9988"]}, {"doi": "10.1093/restud/rdag052", "journal": "REStud", "title": "The Architecture of Social Networks and the Diffusion of Innovations", "authors": ["Bryony Reich"], "author_details": [{"name": "Bryony Reich", "affiliations": ["University of Cambridge, UK and Northwestern University ,"]}], "abstract": "Abstract For many technologies and behaviours, an agent\u2019s benefit from adopting depends on his contacts adopting, and the benefit to his contacts of adopting depends on their contacts adopting. This paper examines how the architecture of these connections shapes the success or failure of the diffusion of innovations. We start with a standard model of diffusion with the key addition that some agents can coordinate their decisions. This captures the idea that people often talk and make decisions together with friends or family to adopt technologies. We show that insularity of connections, that is, the extent to which agents tend to concentrate their connections to a narrow set of other agents, determines contagion. However, whether insularity helps or hinders depends on the technology being diffused. For technologies that are valuable even without many contacts adopting, we find insular connections hinder adoption, but for technologies that are valuable only when many contacts adopt, insular connections facilitate adoption.", "date": "2026-05-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag052", "title_zh": "\u793e\u4f1a\u7f51\u7edc\u7684\u7ed3\u6784\u4e0e\u521b\u65b0\u6269\u6563", "abstract_zh": "\u6458\u8981 \u5bf9\u4e8e\u8bb8\u591a\u6280\u672f\u548c\u884c\u4e3a\u800c\u8a00\uff0c\u4e00\u4e2a\u4ee3\u7406\u5728\u91c7\u7eb3\u65f6\u7684\u6536\u76ca\u53d6\u51b3\u4e8e\u5176\u8054\u7cfb\u4eba\u662f\u5426\u91c7\u7eb3\uff0c\u800c\u5176\u8054\u7cfb\u4eba\u5728\u91c7\u7eb3\u65f6\u7684\u6536\u76ca\u5219\u53d6\u51b3\u4e8e\u4ed6\u4eec\u7684\u8054\u7cfb\u4eba\u662f\u5426\u91c7\u7eb3\u3002\u672c\u6587\u7814\u7a76\u4e86\u8fd9\u4e9b\u8054\u7cfb\u7ed3\u6784\u5982\u4f55\u5f71\u54cd\u521b\u65b0\u7684\u4f20\u64ad\u6210\u529f\u6216\u5931\u8d25\u3002\u6211\u4eec\u4ece\u6807\u51c6\u7684\u6269\u6563\u6a21\u578b\u51fa\u53d1\uff0c\u5173\u952e\u65b0\u589e\u7684\u662f\u67d0\u4e9b\u4ee3\u7406\u53ef\u4ee5\u534f\u8c03\u5176\u51b3\u7b56\u3002\u8fd9\u53cd\u6620\u4e86\u4eba\u4eec\u5e38\u5e38\u4e0e\u670b\u53cb\u6216\u5bb6\u4eba\u8ba8\u8bba\u5e76\u5171\u540c\u505a\u51fa\u91c7\u7eb3\u6280\u672f\u7684\u51b3\u5b9a\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fde\u63a5\u7684\u5b64\u7acb\u6027\uff0c\u5373\u4ee3\u7406\u503e\u5411\u4e8e\u5c06\u8054\u7cfb\u96c6\u4e2d\u5728\u5c11\u6570\u5176\u4ed6\u4ee3\u7406\u4e0a\u7684\u7a0b\u5ea6\uff0c\u51b3\u5b9a\u4e86\u4f20\u67d3\u6548\u5e94\u3002\u7136\u800c\uff0c\u5b64\u7acb\u6027\u662f\u5426\u6709\u52a9\u4e8e\u6216\u963b\u788d\u6269\u6563\uff0c\u53d6\u51b3\u4e8e\u6240\u4f20\u64ad\u7684\u6280\u672f\u7c7b\u578b\u3002\u5bf9\u4e8e\u90a3\u4e9b\u5373\u4f7f\u5728\u5c11\u6570\u8054\u7cfb\u4eba\u91c7\u7eb3\u65f6\u4e5f\u5177\u6709\u4ef7\u503c\u7684\u6280\u672f\uff0c\u6211\u4eec\u53d1\u73b0\u5b64\u7acb\u7684\u8fde\u63a5\u4f1a\u963b\u788d\u91c7\u7eb3\uff1b\u800c\u5bf9\u4e8e\u90a3\u4e9b\u53ea\u6709\u5728\u5927\u91cf\u8054\u7cfb\u4eba\u91c7\u7eb3\u65f6\u624d\u5177\u6709\u4ef7\u503c\u7684\u6280\u672f\uff0c\u5b64\u7acb\u7684\u8fde\u63a5\u5219\u6709\u52a9\u4e8e\u91c7\u7eb3\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1017/s0022109026102750", "journal": "JFQA", "title": "Careers in Finance", "authors": ["Andrew Ellul", "Marco Pagano", "Annalisa Scognamiglio"], "author_details": [{"name": "Andrew Ellul", "affiliations": ["Indiana University Kelley School of Business"]}, {"name": "Marco Pagano", "affiliations": ["University of Naples Federico II"]}, {"name": "Annalisa Scognamiglio", "affiliations": ["University of Naples Federico II"]}], "abstract": "Abstract Past research has documented a substantial finance wage premium. We examine whether this premium reflects differences in lifetime career opportunities. Using resume data, we reconstruct career trajectories in finance and nonfinance sectors and build synthetic measures of career attractiveness that account for compensation levels, growth, and risk. We find that asset management and investment banking provide a sizable risk-adjusted career premium relative to banking, insurance, and other sectors. This premium has declined across cohorts, particularly relative to high tech. Labor-market entry patterns respond to these premia: potential entrants treat finance and high-tech careers as substitutes when choosing where to start.", "date": "2026-05-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102750", "title_zh": "\u91d1\u878d\u884c\u4e1a\u7684\u804c\u4e1a\u53d1\u5c55", "abstract_zh": "\u6458\u8981 \u4ee5\u5f80\u7814\u7a76\u53d1\u73b0\u91d1\u878d\u884c\u4e1a\u5b58\u5728\u663e\u8457\u7684\u85aa\u8d44\u6ea2\u4ef7\u3002\u6211\u4eec\u8003\u5bdf\u8fd9\u4e00\u6ea2\u4ef7\u662f\u5426\u53cd\u6620\u4e86\u4e0d\u540c\u804c\u4e1a\u751f\u547d\u5468\u671f\u4e2d\u7684\u673a\u4f1a\u5dee\u5f02\u3002\u5229\u7528\u7b80\u5386\u6570\u636e\uff0c\u6211\u4eec\u91cd\u5efa\u4e86\u91d1\u878d\u4e0e\u975e\u91d1\u878d\u884c\u4e1a\u7684\u804c\u4e1a\u8f68\u8ff9\uff0c\u5e76\u6784\u5efa\u4e86\u8003\u8651\u85aa\u916c\u6c34\u5e73\u3001\u6210\u957f\u6027\u548c\u98ce\u9669\u7684\u5408\u6210\u804c\u4e1a\u5438\u5f15\u529b\u6307\u6807\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u8d44\u4ea7\u7ba1\u7406\u4e0e\u6295\u8d44\u94f6\u884c\u76f8\u8f83\u4e8e\u94f6\u884c\u3001\u4fdd\u9669\u53ca\u5176\u4ed6\u884c\u4e1a\u63d0\u4f9b\u4e86\u663e\u8457\u7684\u98ce\u9669\u8c03\u6574\u540e\u804c\u4e1a\u6ea2\u4ef7\u3002\u8fd9\u4e00\u6ea2\u4ef7\u5728\u4e0d\u540c\u4e16\u4ee3\u4e2d\u6709\u6240\u4e0b\u964d\uff0c\u5c24\u5176\u76f8\u5bf9\u4e8e\u9ad8\u79d1\u6280\u884c\u4e1a\u3002\u52b3\u52a8\u529b\u5e02\u573a\u8fdb\u5165\u6a21\u5f0f\u53cd\u6620\u4e86\u8fd9\u4e9b\u6ea2\u4ef7\uff1a\u6f5c\u5728\u6c42\u804c\u8005\u5728\u9009\u62e9\u804c\u4e1a\u8d77\u70b9\u65f6\uff0c\u5c06\u91d1\u878d\u884c\u4e1a\u548c\u9ad8\u79d1\u6280\u884c\u4e1a\u89c6\u4e3a\u66ff\u4ee3\u9009\u9879\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag033", "journal": "REStud", "title": "Monopsony Makes Firms Not Only Small but Also Unproductive: Why East Germany has Not Converged", "authors": ["R\u00fcdiger Bachmann", "Christian Bayer", "Heiko St\u00fcber", "Felix Wellschmied"], "author_details": [{"name": "R\u00fcdiger Bachmann", "affiliations": ["University of Michigan, CEPR, CESifo, ifo, and IZA ,"]}, {"name": "Christian Bayer", "affiliations": ["Rheinische Friedrich-Wilhelms-Universit\u00e4t Bonn, CEPR, CESifo, and IZA ,"]}, {"name": "Heiko St\u00fcber", "affiliations": ["Hochschule der Bundesagentur f\u00fcr Arbeit, IAB, and IZA ,"]}, {"name": "Felix Wellschmied", "affiliations": ["Universidad Carlos III de Madrid and IZA , Spain"]}], "abstract": "Abstract When employers face a trade-off between being large and paying low wages\u2014and in this sense have monopsony power\u2014some productive employers decide against building large business networks, forgo sales, and remain small. These decisions have adverse consequences for aggregate labour productivity. Using high-quality administrative data from Germany, we document that East German plants (compared to West German ones) face steeper size-wage curves, invest less in their business networks, remain smaller, and are less productive. A model with labour market monopsony, product market power, and business network investments matching these features of the data predicts a 10% lower aggregate labour productivity in East Germany.", "date": "2026-05-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag033", "title_zh": "\u5784\u65ad\u4f7f\u4f01\u4e1a\u4e0d\u4ec5\u89c4\u6a21\u5c0f\u800c\u4e14\u4f4e\u6548\uff1a\u89e3\u91ca\u4e1c\u5fb7\u4e3a\u4f55\u672a\u5b9e\u73b0\u6536\u655b", "abstract_zh": "\u5f53\u96c7\u4e3b\u9762\u4e34\u89c4\u6a21\u6269\u5927\u4e0e\u652f\u4ed8\u4f4e\u5de5\u8d44\u4e4b\u95f4\u7684\u6743\u8861\u2014\u2014\u5373\u5177\u6709\u5784\u65ad\u4e70\u65b9\u6743\u529b\u65f6\u2014\u2014\u4e00\u4e9b\u5177\u6709\u751f\u4ea7\u6027\u7684\u4f01\u4e1a\u9009\u62e9\u4e0d\u5efa\u7acb\u5927\u578b\u5546\u4e1a\u7f51\u7edc\uff0c\u653e\u5f03\u9500\u552e\uff0c\u4fdd\u6301\u89c4\u6a21\u5c0f\u3002\u8fd9\u4e9b\u51b3\u7b56\u5bf9\u6574\u4f53\u52b3\u52a8\u751f\u4ea7\u7387\u4ea7\u751f\u4e86\u4e0d\u5229\u5f71\u54cd\u3002\u5229\u7528\u6765\u81ea\u5fb7\u56fd\u7684\u9ad8\u8d28\u91cf\u884c\u653f\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u4e1c\u5fb7\u5de5\u5382\uff08\u4e0e\u897f\u5fb7\u5de5\u5382\u76f8\u6bd4\uff09\u9762\u4e34\u66f4\u9661\u7684\u89c4\u6a21-\u5de5\u8d44\u66f2\u7ebf\uff0c\u5bf9\u5546\u4e1a\u7f51\u7edc\u7684\u6295\u8d44\u66f4\u5c11\uff0c\u89c4\u6a21\u66f4\u5c0f\uff0c\u751f\u4ea7\u7387\u4e5f\u66f4\u4f4e\u3002\u4e00\u4e2a\u5305\u542b\u52b3\u52a8\u529b\u5e02\u573a\u5784\u65ad\u3001\u4ea7\u54c1\u5e02\u573a\u6743\u529b\u4ee5\u53ca\u5546\u4e1a\u7f51\u7edc\u6295\u8d44\u7684\u6a21\u578b\uff0c\u80fd\u591f\u89e3\u91ca\u6570\u636e\u4e2d\u7684\u8fd9\u4e9b\u7279\u5f81\uff0c\u5e76\u9884\u6d4b\u4e1c\u5fb7\u6574\u4f53\u52b3\u52a8\u751f\u4ea7\u7387\u6bd4\u897f\u5fb7\u4f4e10%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1111/jofi.70054", "journal": "JF", "title": "Hedger of Last Resort: Evidence from Brazilian FX Interventions, Local Credit, and Global Financial Cycles", "authors": ["RODRIGO BARBONE GONZALEZ", "DMITRY KHAMETSHIN", "JOS\u00c9\u2010LUIS PEYDR\u00d3", "ANDREA POLO"], "author_details": [{"name": "RODRIGO BARBONE GONZALEZ", "affiliations": []}, {"name": "DMITRY KHAMETSHIN", "affiliations": []}, {"name": "JOS\u00c9\u2010LUIS PEYDR\u00d3", "affiliations": []}, {"name": "ANDREA POLO", "affiliations": []}], "abstract": "ABSTRACT We show that FX interventions can be effective, particularly in attenuating global financial spillovers. We exploit global financial shocks and Brazilian central bank interventions in FX derivatives using three matched administrative registers: bank credit (to firms), foreign credit to banks, and employer\u2010employees. After the U.S. Taper Tantrum (followed by emerging markets' FX turbulence), Brazilian banks with more foreign debt cut credit supply, reducing firm\u2010level employment. A subsequent large policy intervention supplying derivatives against FX risks \u2014 hedger of last resort \u2014 halved the negative effects. A 2008 to 2015 panel exploiting global FX shocks and local FX interventions confirms the results and the hedging channel. However, the FX policy entails fiscal and moral hazard costs.", "date": "2026-05-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70054", "title_zh": "\u6700\u540e\u7684\u5bf9\u51b2\u8005\uff1a\u6765\u81ea\u5df4\u897f\u5916\u6c47\u5e72\u9884\u3001\u672c\u5730\u4fe1\u8d37\u548c\u5168\u7403\u91d1\u878d\u5468\u671f\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u8bc1\u660e\u5916\u6c47\u5e72\u9884\u53ef\u4ee5\u6709\u6548\uff0c\u5c24\u5176\u662f\u5728\u51cf\u8f7b\u5168\u7403\u91d1\u878d\u5916\u6ea2\u65b9\u9762\u3002\u6211\u4eec\u5229\u7528\u5168\u7403\u91d1\u878d\u51b2\u51fb\u548c\u5df4\u897f\u592e\u884c\u5728\u5916\u6c47\u884d\u751f\u54c1\u5e02\u573a\u7684\u5e72\u9884\uff0c\u7ed3\u5408\u4e09\u4e2a\u5339\u914d\u7684\u884c\u653f\u767b\u8bb0\u6570\u636e\uff1a\u5bf9\u4f01\u4e1a\u63d0\u4f9b\u7684\u94f6\u884c\u4fe1\u8d37\u3001\u94f6\u884c\u7684\u5916\u5e01\u4fe1\u8d37\u4ee5\u53ca\u96c7\u4e3b\u4e0e\u96c7\u5458\u4e4b\u95f4\u7684\u5173\u7cfb\u3002\u5728\u7f8e\u56fd\u7f29\u8868\u6050\u614c\uff08\u968f\u540e\u662f\u65b0\u5174\u5e02\u573a\u5916\u6c47\u52a8\u8361\uff09\u4e4b\u540e\uff0c\u5916\u5e01\u503a\u52a1\u8f83\u9ad8\u7684\u5df4\u897f\u94f6\u884c\u51cf\u5c11\u4e86\u4fe1\u8d37\u4f9b\u7ed9\uff0c\u5bfc\u81f4\u4f01\u4e1a\u5c42\u9762\u7684\u5c31\u4e1a\u4e0b\u964d\u3002\u968f\u540e\u7684\u4e00\u6b21\u5927\u89c4\u6a21\u653f\u7b56\u5e72\u9884\uff0c\u5373\u63d0\u4f9b\u5bf9\u51b2\u5916\u6c47\u98ce\u9669\u7684\u884d\u751f\u54c1\u2014\u2014\u6700\u540e\u7684\u5bf9\u51b2\u8005\u2014\u2014\u5c06\u8fd9\u79cd\u8d1f\u9762\u6548\u5e94\u51cf\u534a\u30022008\u5e74\u81f32015\u5e74\u7684\u9762\u677f\u6570\u636e\u5229\u7528\u5168\u7403\u5916\u6c47\u51b2\u51fb\u548c\u672c\u5730\u5916\u6c47\u5e72\u9884\u8fdb\u4e00\u6b65\u8bc1\u5b9e\u4e86\u7ed3\u679c\u548c\u5bf9\u51b2\u6e20\u9053\u3002\u7136\u800c\uff0c\u5916\u6c47\u653f\u7b56\u5e26\u6765\u4e86\u8d22\u653f\u548c\u9053\u5fb7\u98ce\u9669\u6210\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70048", "journal": "JF", "title": "Quote Competition in Corporate Bonds", "authors": ["TERRENCE HENDERSHOTT", "DAN LI", "DMITRY LIVDAN", "NORMAN SCH\u00dcRHOFF", "KUMAR VENKATARAMAN"], "author_details": [{"name": "TERRENCE HENDERSHOTT", "affiliations": []}, {"name": "DAN LI", "affiliations": []}, {"name": "DMITRY LIVDAN", "affiliations": []}, {"name": "NORMAN SCH\u00dcRHOFF", "affiliations": []}, {"name": "KUMAR VENKATARAMAN", "affiliations": []}], "abstract": "ABSTRACT Dealer quotes in corporate bonds, though indicative, lower trading costs and increase trading volume. Dealers offering higher quality quotes attract more order flow and execute trades at favorable prices. Dealers advertise quotes to manage their inventories and attract orders from nonrelationship clients. However, quote competition is imperfect. The best quotes often fail to attract orders, and trade\u2010throughs are common. Nevertheless, quote competition is important as clients exploit quotes from other dealers in negotiations, forcing dealers with lower quality quotes to offer price improvements. Quoting is not a zero\u2010sum game, as more active bond\u2010level quoting leads to more bond\u2010level trading.", "date": "2026-05-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70048", "title_zh": "\u4f01\u4e1a\u503a\u5238\u4e2d\u7684\u62a5\u4ef7\u7ade\u4e89", "abstract_zh": "\u6458\u8981 \u4f01\u4e1a\u503a\u5238\u7684\u7ecf\u7eaa\u5546\u62a5\u4ef7\u867d\u7136\u5177\u6709\u53c2\u8003\u6027\uff0c\u4f46\u80fd\u591f\u964d\u4f4e\u4ea4\u6613\u6210\u672c\u5e76\u589e\u52a0\u4ea4\u6613\u91cf\u3002\u63d0\u4f9b\u9ad8\u8d28\u91cf\u62a5\u4ef7\u7684\u7ecf\u7eaa\u5546\u80fd\u591f\u5438\u5f15\u66f4\u591a\u7684\u8ba2\u5355\uff0c\u5e76\u4ee5\u66f4\u6709\u5229\u7684\u4ef7\u683c\u6267\u884c\u4ea4\u6613\u3002\u7ecf\u7eaa\u5546\u901a\u8fc7\u5e7f\u544a\u62a5\u4ef7\u6765\u7ba1\u7406\u5e93\u5b58\uff0c\u5e76\u5438\u5f15\u975e\u5173\u7cfb\u5ba2\u6237\u7684\u8ba2\u5355\u3002\u7136\u800c\uff0c\u62a5\u4ef7\u7ade\u4e89\u662f\u4e0d\u5b8c\u7f8e\u7684\u3002\u6700\u4f73\u62a5\u4ef7\u5f80\u5f80\u65e0\u6cd5\u5438\u5f15\u8ba2\u5355\uff0c\u4e14\u4ea4\u6613\u901a\u8fc7\u73b0\u8c61\u666e\u904d\u5b58\u5728\u3002\u5c3d\u7ba1\u5982\u6b64\uff0c\u62a5\u4ef7\u7ade\u4e89\u4ecd\u7136\u91cd\u8981\uff0c\u56e0\u4e3a\u5ba2\u6237\u4f1a\u5229\u7528\u5176\u4ed6\u7ecf\u7eaa\u5546\u7684\u62a5\u4ef7\u8fdb\u884c\u8c08\u5224\uff0c\u8feb\u4f7f\u62a5\u4ef7\u8d28\u91cf\u8f83\u4f4e\u7684\u7ecf\u7eaa\u5546\u63d0\u9ad8\u62a5\u4ef7\u3002\u62a5\u4ef7\u5e76\u975e\u96f6\u548c\u535a\u5f08\uff0c\u56e0\u4e3a\u66f4\u6d3b\u8dc3\u7684\u503a\u5238\u5c42\u9762\u62a5\u4ef7\u4f1a\u5e26\u6765\u66f4\u591a\u7684\u503a\u5238\u5c42\u9762\u4ea4\u6613\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag040", "journal": "RFS", "title": "Global Capital and Local Assets: House Prices, Quantities, and Elasticities", "authors": ["Caitlin S Gorback", "Benjamin J Keys"], "author_details": [{"name": "Caitlin S Gorback", "affiliations": ["McCombs School of Business, University of Texas at Austin ,"]}, {"name": "Benjamin J Keys", "affiliations": ["The Wharton School, University of Pennsylvania, and NBER ,"]}], "abstract": "Abstract We estimate price elasticities of housing supply for U.S. cities by examining the impact of foreign purchases on housing prices and quantities. After other countries introduced foreign-buyer taxes beginning in 2011, both house prices and quantities increased more in locations with high foreign-born populations. An increase in global capital inflows, instrumented with tax policy changes scaled by immigrant exposure, increased prices and quantities over 2011\u20132018. We combine these estimates to construct new local supply elasticities, which average 0.26 and range from 0.06 to 0.9. Compared to prior estimates, our elasticities are more inelastic and change cities\u2019 relative rankings.", "date": "2026-05-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag040", "title_zh": "\u5168\u7403\u8d44\u672c\u4e0e\u672c\u5730\u8d44\u4ea7\uff1a\u623f\u4ef7\u3001\u6570\u91cf\u53ca\u5f39\u6027", "abstract_zh": "\u6211\u4eec\u901a\u8fc7\u8003\u5bdf\u5916\u56fd\u8d2d\u623f\u8005\u5bf9\u623f\u4ef7\u548c\u4f4f\u623f\u6570\u91cf\u7684\u5f71\u54cd\uff0c\u4f30\u8ba1\u4e86\u7f8e\u56fd\u57ce\u5e02\u4f4f\u623f\u4f9b\u5e94\u7684\u4ef7\u683c\u5f39\u6027\u3002\u57282011\u5e74\u5176\u4ed6\u56fd\u5bb6\u5f00\u59cb\u5bf9\u5916\u56fd\u8d2d\u623f\u8005\u5f81\u6536\u7a0e\u8d39\u540e\uff0c\u5916\u56fd\u51fa\u751f\u4eba\u53e3\u6bd4\u4f8b\u8f83\u9ad8\u7684\u5730\u533a\uff0c\u623f\u4ef7\u548c\u4f4f\u623f\u6570\u91cf\u5747\u51fa\u73b0\u663e\u8457\u4e0a\u5347\u3002\u4ee5\u79fb\u6c11\u66b4\u9732\u7a0b\u5ea6\u4e3a\u6743\u91cd\u7684\u7a0e\u6536\u653f\u7b56\u53d8\u5316\u6240\u4ee3\u8868\u7684\u5168\u7403\u8d44\u672c\u6d41\u5165\uff0c\u4f7f2011\u5e74\u81f32018\u5e74\u95f4\u623f\u4ef7\u548c\u4f4f\u623f\u6570\u91cf\u4e0a\u5347\u3002\u6211\u4eec\u5c06\u8fd9\u4e9b\u4f30\u8ba1\u7ed3\u679c\u7ed3\u5408\u8d77\u6765\uff0c\u6784\u5efa\u4e86\u65b0\u7684\u672c\u5730\u4f9b\u5e94\u5f39\u6027\uff0c\u5e73\u5747\u503c\u4e3a0.26\uff0c\u8303\u56f4\u57280.06\u81f30.9\u4e4b\u95f4\u3002\u4e0e\u4ee5\u5f80\u4f30\u8ba1\u76f8\u6bd4\uff0c\u6211\u4eec\u7684\u5f39\u6027\u503c\u66f4\u4e3a\u4e0d\u654f\u611f\uff0c\u5e76\u6539\u53d8\u4e86\u5404\u57ce\u5e02\u7684\u76f8\u5bf9\u6392\u5e8f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102993", "journal": "JFQA", "title": "Treasury Bills and Bonds: Where (and When) Is the Demand?", "authors": ["Olivier Sirello", "Miklos Vari"], "author_details": [{"name": "Olivier Sirello", "affiliations": ["Bank for International Settlements"]}, {"name": "Miklos Vari", "affiliations": ["ESSEC Business School"]}], "abstract": "Abstract Using the re-issuance policy of the French Treasury, we show that issuances of long-term debt (bonds) increase yields four times as much as issuances of short-term debt (bills). Surprisingly, the modest price impact of bills is not due to differences in secondary market liquidity or the dash for cash during crises. Duration alone cannot explain the higher price impact of bond issuances. The different properties of bills and bonds stem from preferred habitat investors who need time to absorb additional bond issuance compared to the elastic demand of foreign investors for bills. Governments thus rely on bills when they need cash quickly.", "date": "2026-05-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102993", "title_zh": "\u56fd\u5e93\u5238\u4e0e\u56fd\u503a\uff1a\u9700\u6c42\u51fa\u73b0\u5728\u54ea\u91cc\uff08\u4ee5\u53ca\u4f55\u65f6\u51fa\u73b0\uff09\uff1f", "abstract_zh": "\u5229\u7528\u6cd5\u56fd\u56fd\u5e93\u7684\u518d\u53d1\u884c\u653f\u7b56\uff0c\u6211\u4eec\u53d1\u73b0\u957f\u671f\u503a\u52a1\uff08\u56fd\u503a\uff09\u7684\u53d1\u884c\u4f7f\u6536\u76ca\u7387\u4e0a\u5347\u7684\u7a0b\u5ea6\uff0c\u662f\u77ed\u671f\u503a\u52a1\uff08\u56fd\u5e93\u5238\uff09\u53d1\u884c\u7684\u56db\u500d\u3002\u4ee4\u4eba\u60ca\u8bb6\u7684\u662f\uff0c\u56fd\u5e93\u5238\u4ef7\u683c\u5f71\u54cd\u8f83\u5c0f\uff0c\u5e76\u975e\u6e90\u4e8e\u4e8c\u7ea7\u5e02\u573a\u6d41\u52a8\u6027\u5dee\u5f02\u6216\u5371\u673a\u671f\u95f4\u7684\u73b0\u91d1\u62a2\u8d2d\u3002\u4ec5\u51ed\u4e45\u671f\u672c\u8eab\u65e0\u6cd5\u89e3\u91ca\u56fd\u503a\u53d1\u884c\u5bf9\u4ef7\u683c\u7684\u66f4\u5927\u5f71\u54cd\u3002\u56fd\u5e93\u5238\u4e0e\u56fd\u503a\u4e4b\u95f4\u7684\u5dee\u5f02\u6e90\u4e8e\u504f\u597d\u6816\u606f\u5730\u7684\u6295\u8d44\u8005\u9700\u8981\u65f6\u95f4\u6765\u5438\u6536\u989d\u5916\u7684\u503a\u5238\u53d1\u884c\uff0c\u800c\u5916\u56fd\u6295\u8d44\u8005\u5bf9\u56fd\u5e93\u5238\u7684\u9700\u6c42\u5219\u66f4\u4e3a\u5f39\u6027\u3002\u56e0\u6b64\uff0c\u653f\u5e9c\u5728\u9700\u8981\u5feb\u901f\u83b7\u5f97\u73b0\u91d1\u65f6\uff0c\u4f1a\u4f9d\u8d56\u56fd\u5e93\u5238\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102944", "journal": "JFQA", "title": "Trust in Cultural Institutions and Interfirm Cooperation: Evidence from Religious Scandals", "authors": ["Quentin Dupont", "Kayla M. Freeman"], "author_details": [{"name": "Quentin Dupont", "affiliations": ["Georgetown University McDonough School of Business"]}, {"name": "Kayla M. Freeman", "affiliations": ["Colorado State University College of Business and University of Georgia Terry College of Business"]}], "abstract": "Abstract We study how trust in cultural institutions affects cooperation between firms, employing local religious scandals for identification. We focus on trade credit as a trust-intensive aspect of supply chain relationships. In a triple-difference estimation, we find that firms located in scandal areas where the affected religion is prominent reduce trade credit to customers (relative to sales) by 5 percentage points. Consistent with the scandal damaging local norms of cooperation, results are stronger in relationships with limited history, greater geographic barriers, or transaction complexity. Our findings offer novel causal evidence of the influence of local culture on interfirm relationships.", "date": "2026-05-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102944", "title_zh": "\u5bf9\u6587\u5316\u673a\u6784\u7684\u4fe1\u4efb\u4e0e\u4f01\u4e1a\u95f4\u5408\u4f5c\uff1a\u6765\u81ea\u5b97\u6559\u4e11\u95fb\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5bf9\u6587\u5316\u673a\u6784\u7684\u4fe1\u4efb\u5982\u4f55\u5f71\u54cd\u4f01\u4e1a\u4e4b\u95f4\u7684\u5408\u4f5c\uff0c\u5229\u7528\u5f53\u5730\u5b97\u6559\u4e11\u95fb\u8fdb\u884c\u8bc6\u522b\u3002\u6211\u4eec\u91cd\u70b9\u5173\u6ce8\u4f9b\u5e94\u94fe\u5173\u7cfb\u4e2d\u7684\u8d38\u6613\u4fe1\u7528\u8fd9\u4e00\u9ad8\u5ea6\u4f9d\u8d56\u4fe1\u4efb\u7684\u65b9\u9762\u3002\u5728\u4e09\u5dee\u5206\u4f30\u8ba1\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\u4f4d\u4e8e\u53d7\u5f71\u54cd\u5b97\u6559\u5360\u4e3b\u5bfc\u5730\u4f4d\u7684\u4e11\u95fb\u5730\u533a\u7684\u4f01\u4e1a\uff0c\u5176\u5bf9\u5ba2\u6237\u7684\u8d38\u6613\u4fe1\u7528\uff08\u76f8\u5bf9\u4e8e\u9500\u552e\u989d\uff09\u51cf\u5c11\u4e865\u4e2a\u767e\u5206\u70b9\u3002\u7ed3\u679c\u4e0e\u4e11\u95fb\u635f\u5bb3\u5f53\u5730\u5408\u4f5c\u89c4\u8303\u4e00\u81f4\uff0c\u4e14\u5728\u5173\u7cfb\u5386\u53f2\u6709\u9650\u3001\u5730\u7406\u969c\u788d\u8f83\u5927\u6216\u4ea4\u6613\u590d\u6742\u5ea6\u8f83\u9ad8\u7684\u60c5\u51b5\u4e0b\uff0c\u6548\u5e94\u66f4\u4e3a\u663e\u8457\u3002\u6211\u4eec\u7684\u53d1\u73b0\u63d0\u4f9b\u4e86\u5173\u4e8e\u5f53\u5730\u6587\u5316\u5982\u4f55\u5f71\u54cd\u4f01\u4e1a\u95f4\u5173\u7cfb\u7684\u5168\u65b0\u56e0\u679c\u8bc1\u636e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/restud/rdag041", "journal": "REStud", "title": "Money Markets, Collateral, and Monetary Policy", "authors": ["Fiorella De Fiore", "Marie Hoerova", "Ciaran Rogers", "Harald Uhlig"], "author_details": [{"name": "Fiorella De Fiore", "affiliations": ["Monetary and Economic Department, Bank for International Settlements, Switzerland ; and CEPR, UK"]}, {"name": "Marie Hoerova", "affiliations": ["Directorate General Research , European Central Bank, Germany ; and CEPR, UK"]}, {"name": "Ciaran Rogers", "affiliations": ["HEC Paris, France"]}, {"name": "Harald Uhlig", "affiliations": ["Kenneth C. Griffin Department of Economics , University of Chicago, USA ; and CEPR, UK"]}], "abstract": "Abstract We document dramatic changes in euro area interbank money markets during the financial and sovereign debt crises: unsecured borrowing declined across the euro area, while secured market haircuts on sovereign bonds increased, and bank borrowing from the European Central Bank rose in southern countries. We construct a quantitative general equilibrium model to assess the macroeconomic impact of these developments and the associated policy response. Our model features heterogeneous banks and sovereign bonds, secured and unsecured money markets, and a central bank. We compare a benchmark policy\u2014the central bank providing collateralized lending to banks at haircuts lower than the market\u2014with an alternative policy that maintains a constant central bank balance sheet. We show that the fall in output, investment, and capital would have been twice as high under the alternative policy.", "date": "2026-05-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag041", "title_zh": "\u8d27\u5e01\u5e02\u573a\u3001\u62b5\u62bc\u54c1\u4e0e\u8d27\u5e01\u653f\u7b56", "abstract_zh": "\u6211\u4eec\u8bb0\u5f55\u4e86\u5728\u91d1\u878d\u5371\u673a\u548c\u4e3b\u6743\u503a\u52a1\u5371\u673a\u671f\u95f4\uff0c\u6b27\u5143\u533a\u94f6\u884c\u95f4\u8d27\u5e01\u5e02\u573a\u53d1\u751f\u7684\u663e\u8457\u53d8\u5316\uff1a\u65e0\u62c5\u4fdd\u501f\u6b3e\u5728\u6b27\u5143\u533a\u8303\u56f4\u5185\u666e\u904d\u4e0b\u964d\uff0c\u800c\u5bf9\u4e3b\u6743\u503a\u5238\u7684\u6709\u62c5\u4fdd\u5e02\u573a\u6298\u6263\u7387\u4e0a\u5347\uff0c\u5357\u6b27\u56fd\u5bb6\u4ece\u6b27\u6d32\u4e2d\u592e\u94f6\u884c\u7684\u501f\u6b3e\u589e\u52a0\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u91cf\u5316\u4e00\u822c\u5747\u8861\u6a21\u578b\uff0c\u4ee5\u8bc4\u4f30\u8fd9\u4e9b\u53d8\u5316\u53ca\u5176\u76f8\u5173\u653f\u7b56\u5e94\u5bf9\u7684\u5b8f\u89c2\u7ecf\u6d4e\u5f71\u54cd\u3002\u8be5\u6a21\u578b\u5305\u542b\u5f02\u8d28\u6027\u94f6\u884c\u3001\u4e3b\u6743\u503a\u5238\u3001\u6709\u62c5\u4fdd\u548c\u65e0\u62c5\u4fdd\u8d27\u5e01\u5e02\u573a\u4ee5\u53ca\u4e2d\u592e\u94f6\u884c\u3002\u6211\u4eec\u6bd4\u8f83\u4e86\u57fa\u51c6\u653f\u7b56\u2014\u2014\u5373\u4e2d\u592e\u94f6\u884c\u4ee5\u4f4e\u4e8e\u5e02\u573a\u7684\u6298\u6263\u7387\u5411\u94f6\u884c\u63d0\u4f9b\u62b5\u62bc\u8d37\u6b3e\u2014\u2014\u4e0e\u53e6\u4e00\u79cd\u653f\u7b56\uff0c\u5373\u4e2d\u592e\u94f6\u884c\u4fdd\u6301\u8d44\u4ea7\u8d1f\u503a\u8868\u4e0d\u53d8\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u540e\u8005\u653f\u7b56\u4e0b\uff0c\u4ea7\u51fa\u3001\u6295\u8d44\u548c\u8d44\u672c\u7684\u4e0b\u964d\u5e45\u5ea6\u5c06\u662f\u524d\u8005\u653f\u7b56\u7684\u4e24\u500d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/restud/rdag047", "journal": "REStud", "title": "Technology Transfer and Early Industrial Development: Evidence from the Sino-Soviet Alliance", "authors": ["Michela Giorcelli", "Bo Li"], "author_details": [{"name": "Michela Giorcelli", "affiliations": ["University of California, Los Angeles, NBER, CEPR, CESifo, IZA, J-PAL ,"]}, {"name": "Bo Li", "affiliations": ["Guanghua School of Management, Peking University ,"]}], "abstract": "Abstract This paper studies the long-term effects of technology and know-how transfers on structural transformations. In the 1950s, the Soviet Union supported the construction of the 156 Projects, which were large-scale, capital-intensive industrial clusters in China. These projects included a technology transfer, consisting of state-of-the-art Soviet machinery and equipment, and a know-how transfer, via the training of Chinese engineers, production supervisors, and high-skilled technicians by Soviet experts. We use newly assembled data that follow steel plants for over four decades, and we exploit natural variation in the transfers they eventually received. We find that, while production advantages stemming from Soviet technology faded away if not complemented with training, the know-how transfer had a long-lasting impact on plant performance, stimulated technology upgrade when China was a closed economy, and increased exports to the Western world when China engaged in international trade. The know-how transfer also generated productivity and technology spillovers onto complementary establishments.", "date": "2026-05-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag047", "title_zh": "\u6280\u672f\u8f6c\u8ba9\u4e0e\u65e9\u671f\u5de5\u4e1a\u53d1\u5c55\uff1a\u6765\u81ea\u4e2d\u82cf\u540c\u76df\u7684\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u6280\u672f\u4e0e\u77e5\u8bc6\u8f6c\u79fb\u5bf9\u7ed3\u6784\u8f6c\u578b\u7684\u957f\u671f\u5f71\u54cd\u300220\u4e16\u7eaa50\u5e74\u4ee3\uff0c\u82cf\u8054\u652f\u6301\u4e86\u4e2d\u56fd156\u9879\u5de5\u7a0b\u7684\u5efa\u8bbe\uff0c\u8fd9\u4e9b\u5de5\u7a0b\u662f\u5927\u89c4\u6a21\u3001\u8d44\u672c\u5bc6\u96c6\u578b\u7684\u5de5\u4e1a\u96c6\u7fa4\u3002\u8fd9\u4e9b\u9879\u76ee\u5305\u62ec\u6700\u5148\u8fdb\u7684\u82cf\u8054\u673a\u68b0\u8bbe\u5907\u548c\u8bbe\u5907\u7684\u8f6c\u79fb\uff0c\u4ee5\u53ca\u901a\u8fc7\u82cf\u8054\u4e13\u5bb6\u5bf9\u4e2d\u56fd\u7684\u5de5\u7a0b\u5e08\u3001\u751f\u4ea7\u4e3b\u7ba1\u548c\u9ad8\u6280\u80fd\u6280\u672f\u4eba\u5458\u8fdb\u884c\u57f9\u8bad\u800c\u5b9e\u73b0\u7684\u77e5\u8bc6\u8f6c\u79fb\u3002\u6211\u4eec\u5229\u7528\u65b0\u6574\u7406\u7684\u3001\u8ffd\u8e2a\u94a2\u94c1\u5382\u8d85\u8fc7\u56db\u5341\u5e74\u7684\u6570\u636e\uff0c\u5e76\u5229\u7528\u6280\u672f\u8f6c\u79fb\u63a5\u6536\u60c5\u51b5\u7684\u81ea\u7136\u53d8\u5f02\u8fdb\u884c\u5206\u6790\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5982\u679c\u672a\u8f85\u4ee5\u57f9\u8bad\uff0c\u6e90\u4e8e\u82cf\u8054\u6280\u672f\u7684\u751f\u4ea7\u4f18\u52bf\u4f1a\u9010\u6e10\u6d88\u5931\uff0c\u4f46\u77e5\u8bc6\u8f6c\u79fb\u5bf9\u5de5\u5382\u7ee9\u6548\u4ea7\u751f\u4e86\u6301\u4e45\u5f71\u54cd\uff0c\u5728\u4e2d\u56fd\u5c01\u95ed\u7ecf\u6d4e\u65f6\u671f\u4fc3\u8fdb\u4e86\u6280\u672f\u5347\u7ea7\uff0c\u5e76\u5728\u5f00\u5c55\u56fd\u9645\u8d38\u6613\u65f6\u589e\u52a0\u4e86\u5bf9\u897f\u65b9\u5e02\u573a\u7684\u51fa\u53e3\u3002\u6b64\u5916\uff0c\u77e5\u8bc6\u8f6c\u79fb\u8fd8\u4ea7\u751f\u4e86\u5bf9\u4e92\u8865\u4f01\u4e1a\u7684\u751f\u4ea7\u7387\u548c\u6280\u672f\u5916\u6ea2\u6548\u5e94\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag043", "journal": "REStud", "title": "Eliciting Multiple Prior Beliefs", "authors": ["Mohammed Abdellaoui", "Philippe Colo", "Brian Hill"], "author_details": [{"name": "Mohammed Abdellaoui", "affiliations": ["CNRS and HEC Paris ,"]}, {"name": "Philippe Colo", "affiliations": ["ETH Zurich, Oeschger Center for Climate Research and Institute for Philosophy, Universit\u00e4t Bern ,"]}, {"name": "Brian Hill", "affiliations": ["CNRS and HEC Paris ,"]}], "abstract": "Abstract Despite the increasing importance of multiple priors in various domains of economics, choice-based incentive-compatible multiple-prior elicitation remains an open problem. This paper develops a solution, comprising a preference-based identification of a subject\u2019s probability interval for an event, and a method for eliciting it. The method applies under weak decision-theoretic assumptions, with no need for probabilistic sophistication. To demonstrate its feasibility, we implement it in three incentivized experiments on artificial and natural sources of uncertainty. Intervals elicited by our method are sensitive to the direction and amount of information and are typically consistent with \u201cobjective\u201d probabilities where available. We find a predominance of non-degenerate probability intervals, with intervals being wider when there is less information or predictability. The probability intervals elicited with our method are similar to those stated by subjects on aggregate, suggesting that the method can provide behavioural foundations for the use of stated probability-interval techniques in the field.", "date": "2026-05-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag043", "title_zh": "\u83b7\u53d6\u591a\u91cd\u5148\u9a8c\u4fe1\u5ff5", "abstract_zh": "\u5c3d\u7ba1\u591a\u91cd\u5148\u9a8c\u5728\u7ecf\u6d4e\u5b66\u5404\u4e2a\u9886\u57df\u4e2d\u7684\u91cd\u8981\u6027\u65e5\u76ca\u589e\u52a0\uff0c\u57fa\u4e8e\u9009\u62e9\u7684\u3001\u6fc0\u52b1\u76f8\u5bb9\u7684\u591a\u91cd\u5148\u9a8c\u83b7\u53d6\u4ecd\u662f\u4e00\u4e2a\u5f00\u653e\u6027\u95ee\u9898\u3002\u672c\u6587\u63d0\u51fa\u4e86\u4e00\u79cd\u89e3\u51b3\u65b9\u6848\uff0c\u5305\u62ec\u57fa\u4e8e\u504f\u597d\u7684\u4e3b\u4f53\u5bf9\u4e8b\u4ef6\u6982\u7387\u533a\u95f4\u7684\u8bc6\u522b\u65b9\u6cd5\uff0c\u4ee5\u53ca\u83b7\u53d6\u8be5\u533a\u95f4\u7684\u5177\u4f53\u65b9\u6cd5\u3002\u8be5\u65b9\u6cd5\u5728\u5f31\u51b3\u7b56\u7406\u8bba\u5047\u8bbe\u4e0b\u6210\u7acb\uff0c\u65e0\u9700\u4e3b\u4f53\u5177\u5907\u6982\u7387\u63a8\u7406\u80fd\u529b\u3002\u4e3a\u4e86\u9a8c\u8bc1\u5176\u53ef\u884c\u6027\uff0c\u6211\u4eec\u5728\u4e09\u4e2a\u6fc0\u52b1\u6027\u5b9e\u9a8c\u4e2d\u5bf9\u4eba\u5de5\u548c\u81ea\u7136\u6765\u6e90\u7684\u4e0d\u786e\u5b9a\u6027\u8fdb\u884c\u4e86\u5e94\u7528\u3002\u901a\u8fc7\u672c\u65b9\u6cd5\u83b7\u53d6\u7684\u6982\u7387\u533a\u95f4\u5bf9\u4fe1\u606f\u7684\u65b9\u5411\u548c\u6570\u91cf\u53d8\u5316\u654f\u611f\uff0c\u4e14\u5728\u5df2\u6709\u5ba2\u89c2\u6982\u7387\u53ef\u5f97\u7684\u60c5\u51b5\u4e0b\u901a\u5e38\u4e0e\u4e4b\u4fdd\u6301\u4e00\u81f4\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5927\u591a\u6570\u6982\u7387\u533a\u95f4\u662f\u975e\u9000\u5316\u7684\uff0c\u5f53\u4fe1\u606f\u8f83\u5c11\u6216\u53ef\u9884\u6d4b\u6027\u8f83\u5f31\u65f6\uff0c\u533a\u95f4\u5bbd\u5ea6\u66f4\u5927\u3002\u901a\u8fc7\u672c\u65b9\u6cd5\u83b7\u53d6\u7684\u6982\u7387\u533a\u95f4\u4e0e\u4e3b\u4f53\u5728\u6574\u4f53\u4e0a\u9648\u8ff0\u7684\u6982\u7387\u533a\u95f4\u76f8\u4f3c\uff0c\u8868\u660e\u8be5\u65b9\u6cd5\u53ef\u4e3a\u9886\u57df\u4e2d\u9648\u8ff0\u6982\u7387\u533a\u95f4\u6280\u672f\u7684\u5e94\u7528\u63d0\u4f9b\u884c\u4e3a\u5b66\u57fa\u7840\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag048", "journal": "REStud", "title": "Closing Gender Gaps Through Workplace Diversity: The Intergenerational Effects of World War I", "authors": ["Abhay Aneja", "Silvia Farina", "Guo Xu"], "author_details": [{"name": "Abhay Aneja", "affiliations": ["School of Law, UC Berkeley & NBER ,"]}, {"name": "Silvia Farina", "affiliations": ["Haas School of Business, UC Berkeley ,"]}, {"name": "Guo Xu", "affiliations": ["Haas School of Business, UC Berkeley & NBER ,"]}], "abstract": "Abstract This article combines personnel records of the U.S. government with census data to study how exposure to greater female representation at work can persistently reduce intergenerational gender gaps in labour market outcomes. Exploiting city-by-department variation in the sudden expansion of female employment during World War I, we find that daughters of civil servants exposed to female co-workers are more likely to work later in life. This intergenerational effect operates through exposed fathers and extends beyond the public sector, reducing the earnings gap by 12%. Consistent with a broader shift in attitudes towards working women, exposure to female co-workers also made male civil servants more likely to marry working women. We show that cities exposed to larger increases in female federal workers saw persistently higher female labour force participation in both the public and the private sector. Increasing gender representation within the public sector can thus have broader labour market implications.", "date": "2026-05-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag048", "title_zh": "\u901a\u8fc7\u804c\u573a\u591a\u6837\u6027\u7f29\u5c0f\u6027\u522b\u5dee\u8ddd\uff1a\u7b2c\u4e00\u6b21\u4e16\u754c\u5927\u6218\u7684\u4ee3\u9645\u6548\u5e94", "abstract_zh": "\u672c\u6587\u7ed3\u5408\u7f8e\u56fd\u653f\u5e9c\u7684\u4eba\u5458\u8bb0\u5f55\u4e0e\u4eba\u53e3\u666e\u67e5\u6570\u636e\uff0c\u7814\u7a76\u804c\u573a\u4e2d\u5973\u6027\u4ee3\u8868\u6027\u7684\u63d0\u5347\u5982\u4f55\u6301\u4e45\u5730\u51cf\u5c11\u4ee3\u9645\u6027\u522b\u5dee\u8ddd\u5728\u52b3\u52a8\u529b\u5e02\u573a\u7ed3\u679c\u4e2d\u7684\u8868\u73b0\u3002\u5229\u7528\u7b2c\u4e00\u6b21\u4e16\u754c\u5927\u6218\u671f\u95f4\u5404\u57ce\u5e02\u5404\u90e8\u95e8\u5973\u6027\u5c31\u4e1a\u7a81\u7136\u6269\u5f20\u7684\u5dee\u5f02\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u66fe\u4e0e\u5973\u6027\u540c\u4e8b\u5171\u4e8b\u7684\u516c\u52a1\u5458\u5973\u513f\u5728\u665a\u5e74\u66f4\u6709\u53ef\u80fd\u4ece\u4e8b\u5de5\u4f5c\u3002\u8fd9\u4e00\u4ee3\u9645\u6548\u5e94\u901a\u8fc7\u7236\u4eb2\u7684\u66b4\u9732\u800c\u53d1\u6325\u4f5c\u7528\uff0c\u5e76\u8d85\u8d8a\u4e86\u516c\u5171\u90e8\u95e8\uff0c\u4f7f\u6536\u5165\u5dee\u8ddd\u7f29\u5c0f12%\u3002\u4e0e\u5bf9\u5973\u6027\u5de5\u4f5c\u8005\u6001\u5ea6\u7684\u66f4\u5e7f\u6cdb\u8f6c\u53d8\u4e00\u81f4\uff0c\u4e0e\u5973\u6027\u540c\u4e8b\u5171\u4e8b\u4f7f\u7537\u6027\u516c\u52a1\u5458\u66f4\u53ef\u80fd\u4e0e\u4ece\u4e8b\u5de5\u4f5c\u7684\u5973\u6027\u7ed3\u5a5a\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5973\u6027\u8054\u90a6\u5458\u5de5\u589e\u52a0\u5e45\u5ea6\u8f83\u5927\u7684\u57ce\u5e02\uff0c\u5176\u516c\u5171\u548c\u79c1\u8425\u90e8\u95e8\u7684\u5973\u6027\u52b3\u52a8\u529b\u53c2\u4e0e\u7387\u5747\u957f\u671f\u4fdd\u6301\u8f83\u9ad8\u6c34\u5e73\u3002\u56e0\u6b64\uff0c\u516c\u5171\u90e8\u95e8\u4e2d\u5973\u6027\u4ee3\u8868\u6027\u7684\u63d0\u5347\u53ef\u4ea7\u751f\u66f4\u5e7f\u6cdb\u7684\u52b3\u52a8\u529b\u5e02\u573a\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70055", "journal": "JF", "title": "Investing with Purpose: Evidence from Private Foundations", "authors": ["MATTEO BINFAR\u00c8", "KYLE E. ZIMMERSCHIED"], "author_details": [{"name": "MATTEO BINFAR\u00c8", "affiliations": []}, {"name": "KYLE E. ZIMMERSCHIED", "affiliations": []}], "abstract": "ABSTRACT We study the asset allocation and investment performance of U.S. private foundations that support the charitable sector. Large foundations generated positive risk\u2010adjusted returns before 2008, driven by early access to private equity and venture capital funds, but have underperformed since. The median foundation underperforms by more than 100 bps. Foundations with concentrated stock holdings achieve higher returns but assume more risk. Due to the constraints imposed by the 5% minimum spending rule and accommodating monetary policy, foundations increase risk\u2010taking and reach for yield. Over time, a conservative asset allocation decreases real wealth, reducing charitable giving.", "date": "2026-05-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70055", "title_zh": "\u4e3a\u4f7f\u547d\u800c\u6295\u8d44\uff1a\u6765\u81ea\u79c1\u4eba\u57fa\u91d1\u4f1a\u7684\u8bc1\u636e", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u652f\u6301\u6148\u5584\u884c\u4e1a\u7684\u7f8e\u56fd\u79c1\u4eba\u57fa\u91d1\u4f1a\u7684\u8d44\u4ea7\u914d\u7f6e\u548c\u6295\u8d44\u8868\u73b0\u3002\u57282008\u5e74\u4e4b\u524d\uff0c\u5927\u578b\u57fa\u91d1\u4f1a\u5b9e\u73b0\u4e86\u6b63\u7684\u98ce\u9669\u8c03\u6574\u56de\u62a5\uff0c\u8fd9\u5f97\u76ca\u4e8e\u5176\u65e9\u671f\u83b7\u5f97\u79c1\u52df\u80a1\u6743\u548c\u98ce\u9669\u6295\u8d44\u57fa\u91d1\u7684\u51c6\u5165\u4f18\u52bf\uff0c\u4f46\u6b64\u540e\u8868\u73b0\u5219\u6709\u6240\u4e0b\u6ed1\u3002\u4e2d\u4f4d\u6570\u57fa\u91d1\u4f1a\u7684\u56de\u62a5\u4f4e\u4e8e\u57fa\u51c6\u8d85\u8fc7100\u4e2a\u57fa\u70b9\u3002\u6301\u80a1\u96c6\u4e2d\u7684\u57fa\u91d1\u4f1a\u83b7\u5f97\u4e86\u66f4\u9ad8\u7684\u56de\u62a5\uff0c\u4f46\u627f\u62c5\u4e86\u66f4\u591a\u98ce\u9669\u3002\u7531\u4e8e\u53d7\u52305%\u6700\u4f4e\u652f\u51fa\u89c4\u5219\u4ee5\u53ca\u8d27\u5e01\u653f\u7b56\u73af\u5883\u7684\u5236\u7ea6\uff0c\u57fa\u91d1\u4f1a\u589e\u52a0\u4e86\u98ce\u9669\u627f\u62c5\u884c\u4e3a\u5e76\u5bfb\u6c42\u66f4\u9ad8\u6536\u76ca\u3002\u968f\u7740\u65f6\u95f4\u63a8\u79fb\uff0c\u4fdd\u5b88\u7684\u8d44\u4ea7\u914d\u7f6e\u5bfc\u81f4\u5b9e\u9645\u8d22\u5bcc\u51cf\u5c11\uff0c\u4ece\u800c\u524a\u5f31\u4e86\u6148\u5584\u6350\u8d60\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag020", "journal": "RFS", "title": "Do Mutual Funds Walk the Talk? Evidence from Fund Risk Disclosure", "authors": ["Jinfei Sheng", "Nan Xu", "Lu Zheng"], "author_details": [{"name": "Jinfei Sheng", "affiliations": ["Merage School of Business, University of California Irvine ,"]}, {"name": "Nan Xu", "affiliations": ["Dishui Lake Advanced Finance Institute, Shanghai University of Finance and Economics ,"]}, {"name": "Lu Zheng", "affiliations": ["Merage School of Business, University of California Irvine ,"]}], "abstract": "Abstract We examine the informativeness of fund risk disclosure by combining fund returns and textual data. We develop a novel measure, INF, to capture the explanatory power of disclosed risks for fund returns. Average INF is 55% after controlling for market risk and remains 26\u201329% after excluding risks related to fund name or strategy. We explain variations in INF through disclosure costs and benefits: (1) Funds with less informative disclosures face SEC comment letters and reduced flow, (2) informative disclosures attract institutional flows, and (3) performance concerns may disincentivize disclosure. Overall, funds face trade-offs between transparency and maintaining their competitive advantage.", "date": "2026-05-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag020", "title_zh": "\u5171\u540c\u57fa\u91d1\u662f\u5426\u8a00\u51fa\u5fc5\u884c\uff1f\u6765\u81ea\u57fa\u91d1\u98ce\u9669\u62ab\u9732\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u901a\u8fc7\u7ed3\u5408\u57fa\u91d1\u56de\u62a5\u548c\u6587\u672c\u6570\u636e\uff0c\u8003\u5bdf\u57fa\u91d1\u98ce\u9669\u62ab\u9732\u7684\u4fe1\u606f\u542b\u91cf\u3002\u6211\u4eec\u5f00\u53d1\u4e86\u4e00\u79cd\u65b0\u7684\u5ea6\u91cf\u6307\u6807INF\uff0c\u7528\u4e8e\u8861\u91cf\u62ab\u9732\u7684\u98ce\u9669\u5bf9\u57fa\u91d1\u56de\u62a5\u7684\u89e3\u91ca\u529b\u3002\u5728\u63a7\u5236\u5e02\u573a\u98ce\u9669\u540e\uff0c\u5e73\u5747INF\u4e3a55%\uff0c\u6392\u9664\u4e0e\u57fa\u91d1\u540d\u79f0\u6216\u7b56\u7565\u76f8\u5173\u7684\u98ce\u9669\u540e\uff0c\u4ecd\u4e3a26%\u81f329%\u3002\u6211\u4eec\u901a\u8fc7\u62ab\u9732\u6210\u672c\u4e0e\u6536\u76ca\u89e3\u91ca\u4e86INF\u7684\u5dee\u5f02\uff1a\uff081\uff09\u62ab\u9732\u4fe1\u606f\u8f83\u5c11\u7684\u57fa\u91d1\u9762\u4e34SEC\u7684\u8bc4\u8bba\u4fe1\u548c\u6d41\u91cf\u51cf\u5c11\uff1b\uff082\uff09\u4fe1\u606f\u4e30\u5bcc\u7684\u62ab\u9732\u5438\u5f15\u673a\u6784\u6295\u8d44\u8005\u7684\u6d41\u5165\uff1b\uff083\uff09\u4e1a\u7ee9\u62c5\u5fe7\u53ef\u80fd\u6291\u5236\u62ab\u9732\u884c\u4e3a\u3002\u603b\u4f53\u800c\u8a00\uff0c\u57fa\u91d1\u5728\u900f\u660e\u5ea6\u4e0e\u4fdd\u6301\u7ade\u4e89\u4f18\u52bf\u4e4b\u95f4\u9762\u4e34\u6743\u8861\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790"]}, {"doi": "10.1093/restud/rdag050", "journal": "REStud", "title": "Jackknife Standard Errors for Clustered Regression", "authors": ["Bruce E Hansen"], "author_details": [{"name": "Bruce E Hansen", "affiliations": ["University of Wisconsin ,"]}], "abstract": "Abstract This article presents a theoretical case for replacement of conventional heteroskedasticity-consistent and cluster-robust variance estimators with jackknife variance estimators, in the context of linear regression with heteroskedastic and/or cluster-dependent observations. We examine the bias of variance estimation and the coverage probabilities of confidence intervals. Concerning bias, we show that conventional variance estimators have full downward worst-case bias, while our jackknife variance estimator is never downward biased. Concerning confidence intervals, we show that intervals based on conventional standard errors have worst-case coverage equalling zero, while the jackknife-based confidence interval has coverage probability bounded by the Cauchy distribution, under the auxiliary assumption of normal errors. We also extend the Bell and McCaffrey (2002) student t approximation to our jackknife t-ratio, resulting in confidence intervals with improved coverage probabilities. Our theory holds under broad assumptions, allowing arbitrary cluster sizes, regressor leverage, within-cluster correlation, heteroskedasticity, regression with a single treated cluster, fixed effects, and delete-cluster invertibility failures. Our theoretical findings are consistent with the extensive simulation literature investigating heteroskedasticity-consistent and cluster-robust variance estimation.", "date": "2026-05-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag050", "title_zh": "\u7528\u4e8e\u805a\u7c7b\u56de\u5f52\u7684\u6770\u5361\u5fb7\u6807\u51c6\u8bef", "abstract_zh": "\u672c\u6587\u5728\u5177\u6709\u5f02\u65b9\u5dee\u548c/\u6216\u805a\u7c7b\u4f9d\u8d56\u89c2\u6d4b\u503c\u7684\u7ebf\u6027\u56de\u5f52\u80cc\u666f\u4e0b\uff0c\u63d0\u51fa\u4e86\u7528\u6770\u5361\u5fb7\u65b9\u5dee\u4f30\u8ba1\u91cf\u66ff\u4ee3\u4f20\u7edf\u5f02\u65b9\u5dee\u4e00\u81f4\u548c\u805a\u7c7b\u7a33\u5065\u65b9\u5dee\u4f30\u8ba1\u91cf\u7684\u7406\u8bba\u4f9d\u636e\u3002\u6211\u4eec\u8003\u5bdf\u4e86\u65b9\u5dee\u4f30\u8ba1\u7684\u504f\u5dee\u4ee5\u53ca\u7f6e\u4fe1\u533a\u95f4\u7684\u8986\u76d6\u6982\u7387\u3002\u5173\u4e8e\u504f\u5dee\uff0c\u6211\u4eec\u8bc1\u660e\u4f20\u7edf\u65b9\u5dee\u4f30\u8ba1\u91cf\u5b58\u5728\u5b8c\u5168\u5411\u4e0b\u7684\u6700\u574f\u60c5\u51b5\u504f\u5dee\uff0c\u800c\u6211\u4eec\u7684\u6770\u5361\u5fb7\u65b9\u5dee\u4f30\u8ba1\u91cf\u6c38\u8fdc\u4e0d\u4f1a\u51fa\u73b0\u5411\u4e0b\u7684\u504f\u5dee\u3002\u5173\u4e8e\u7f6e\u4fe1\u533a\u95f4\uff0c\u6211\u4eec\u8868\u660e\u57fa\u4e8e\u4f20\u7edf\u6807\u51c6\u8bef\u7684\u533a\u95f4\u5177\u6709\u6700\u574f\u60c5\u51b5\u8986\u76d6\u6982\u7387\u7b49\u4e8e\u96f6\uff0c\u800c\u57fa\u4e8e\u6770\u5361\u5fb7\u65b9\u6cd5\u7684\u7f6e\u4fe1\u533a\u95f4\u5728\u8f85\u52a9\u5047\u8bbe\u4e3a\u6b63\u6001\u8bef\u5dee\u7684\u6761\u4ef6\u4e0b\uff0c\u5176\u8986\u76d6\u6982\u7387\u88ab\u67ef\u897f\u5206\u5e03\u6240\u9650\u5236\u3002\u6211\u4eec\u8fd8\u5c06\u8d1d\u5c14\u548c\u9ea6\u5361\u5f17\u91cc\uff082002\uff09\u7684t\u5206\u5e03\u8fd1\u4f3c\u6269\u5c55\u5230\u6211\u4eec\u7684\u6770\u5361\u5fb7t\u7edf\u8ba1\u91cf\uff0c\u4ece\u800c\u5f97\u5230\u8986\u76d6\u6982\u7387\u66f4\u4f18\u7684\u7f6e\u4fe1\u533a\u95f4\u3002\u6211\u4eec\u7684\u7406\u8bba\u5728\u5e7f\u6cdb\u5047\u8bbe\u4e0b\u6210\u7acb\uff0c\u5141\u8bb8\u4efb\u610f\u7684\u805a\u7c7b\u89c4\u6a21\u3001\u81ea\u53d8\u91cf\u6760\u6746\u6548\u5e94\u3001\u805a\u7c7b\u5185\u90e8\u76f8\u5173\u6027\u3001\u5f02\u65b9\u5dee\u6027\u3001\u5355\u4e2a\u5904\u7406\u805a\u7c7b\u56de\u5f52\u3001\u56fa\u5b9a\u6548\u5e94\u4ee5\u53ca\u5220\u9664\u805a\u7c7b\u53ef\u9006\u6027\u5931\u8d25\u7684\u60c5\u51b5\u3002\u6211\u4eec\u7684\u7406\u8bba\u53d1\u73b0\u4e0e\u5927\u91cf\u5173\u4e8e\u5f02\u65b9\u5dee\u4e00\u81f4\u548c\u805a\u7c7b\u7a33\u5065\u65b9\u5dee\u4f30\u8ba1\u7684\u6a21\u62df\u7814\u7a76\u7ed3\u679c\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag049", "journal": "REStud", "title": "The Dynamics of Internal Migration: A New Fact and its Implications", "authors": ["Greg Howard", "Hansen Shao"], "author_details": [{"name": "Greg Howard", "affiliations": ["University of Illinois Urbana-Champaign ,"]}, {"name": "Hansen Shao", "affiliations": ["University of Illinois Urbana-Champaign ,"]}], "abstract": "Abstract We propose a new model of internal migration, based on persistent and spatially correlated idiosyncratic utility. The model is motivated by a new fact in the data that simple moving cost models struggle to match: the t-year interstate migration rate is proportional to the square root of t. The new model maintains the tractability and flexibility of standard migration models, but better matches the dynamics of migration, including the new fact. It has substantially different welfare implications and makes different counterfactual predictions, especially in terms of dynamic adjustment and long-run responses.", "date": "2026-05-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag049", "title_zh": "\u5185\u90e8\u8fc1\u79fb\u7684\u52a8\u6001\uff1a\u4e00\u4e2a\u65b0\u4e8b\u5b9e\u53ca\u5176\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u57fa\u4e8e\u6301\u4e45\u4e14\u7a7a\u95f4\u76f8\u5173\u7684\u7279\u8d28\u6548\u7528\u7684\u65b0\u8fc1\u79fb\u6a21\u578b\u3002\u8be5\u6a21\u578b\u53d7\u5230\u6570\u636e\u4e2d\u4e00\u4e2a\u65b0\u4e8b\u5b9e\u7684\u542f\u53d1\uff0c\u5373\u7b80\u5355\u7684\u79fb\u52a8\u6210\u672c\u6a21\u578b\u96be\u4ee5\u89e3\u91ca\uff1at\u5e74\u95f4\u7684\u5dde\u9645\u8fc1\u79fb\u7387\u4e0et\u7684\u5e73\u65b9\u6839\u6210\u6b63\u6bd4\u3002\u65b0\u6a21\u578b\u5728\u4fdd\u6301\u6807\u51c6\u8fc1\u79fb\u6a21\u578b\u7684\u53ef\u5904\u7406\u6027\u548c\u7075\u6d3b\u6027\u7684\u540c\u65f6\uff0c\u66f4\u597d\u5730\u5339\u914d\u4e86\u8fc1\u79fb\u7684\u52a8\u6001\u7279\u5f81\uff0c\u5305\u62ec\u8fd9\u4e00\u65b0\u4e8b\u5b9e\u3002\u8be5\u6a21\u578b\u5728\u798f\u5229\u5f71\u54cd\u548c\u4e0d\u540c\u53cd\u4e8b\u5b9e\u9884\u6d4b\u65b9\u9762\u6709\u663e\u8457\u5dee\u5f02\uff0c\u5c24\u5176\u662f\u5728\u52a8\u6001\u8c03\u6574\u548c\u957f\u671f\u53cd\u5e94\u65b9\u9762\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70050", "journal": "JF", "title": "Why Have CEO Pay Levels Become Less Diverse?", "authors": ["TORSTEN JOCHEM", "GAIZKA ORMAZABAL", "ANJANA RAJAMANI"], "author_details": [{"name": "TORSTEN JOCHEM", "affiliations": []}, {"name": "GAIZKA ORMAZABAL", "affiliations": []}, {"name": "ANJANA RAJAMANI", "affiliations": []}], "abstract": "ABSTRACT This paper documents a new stylized fact: the cross\u2010sectional variation in CEO pay levels has declined precipitously in recent years. We offer one explanation for this decline, namely, firms are increasingly benchmarking CEO compensation to industry peers closest in size, thereby creating pay clusters. Our empirical tests provide support for this explanation and suggest that the rise of industry\u2010size benchmarking is driven by three institutional factors: the mandatory disclosure of compensation peer groups, proxy advisory influence, and say\u2010on\u2010pay regulation. Our findings highlight a consequence of adopting a one\u2010size\u2010fits\u2010all standard in the pay\u2010setting process.", "date": "2026-05-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70050", "title_zh": "\u4e3a\u4ec0\u4e48\u9996\u5e2d\u6267\u884c\u5b98\u85aa\u916c\u7684\u5dee\u5f02\u6027\u5728\u4e0b\u964d\uff1f", "abstract_zh": "\u6458\u8981 \u672c\u6587\u8bb0\u5f55\u4e86\u4e00\u4e2a\u65b0\u7684\u4e8b\u5b9e\uff1a\u8fd1\u5e74\u6765\uff0c\u9996\u5e2d\u6267\u884c\u5b98\u85aa\u916c\u7684\u8de8\u622a\u9762\u5dee\u5f02\u6025\u5267\u4e0b\u964d\u3002\u6211\u4eec\u63d0\u51fa\u4e00\u4e2a\u89e3\u91ca\uff1a\u4f01\u4e1a\u8d8a\u6765\u8d8a\u5c06\u9996\u5e2d\u6267\u884c\u5b98\u7684\u85aa\u916c\u4e0e\u89c4\u6a21\u76f8\u8fd1\u7684\u884c\u4e1a\u540c\u884c\u8fdb\u884c\u5bf9\u6bd4\uff0c\u4ece\u800c\u5f62\u6210\u85aa\u916c\u96c6\u7fa4\u3002\u6211\u4eec\u7684\u5b9e\u8bc1\u68c0\u9a8c\u652f\u6301\u4e86\u8fd9\u4e00\u89e3\u91ca\uff0c\u5e76\u8868\u660e\u884c\u4e1a\u89c4\u6a21\u5bf9\u6bd4\u7684\u5174\u8d77\u662f\u7531\u4e09\u4e2a\u5236\u5ea6\u56e0\u7d20\u9a71\u52a8\u7684\uff1a\u85aa\u916c\u540c\u884c\u7ec4\u7684\u5f3a\u5236\u62ab\u9732\u3001\u80a1\u4e1c\u987e\u95ee\u7684\u5f71\u54cd\u4ee5\u53ca\u5173\u4e8e\u85aa\u916c\u7684\u6295\u7968\u6743\u76d1\u7ba1\u3002\u6211\u4eec\u7684\u53d1\u73b0\u51f8\u663e\u4e86\u5728\u85aa\u916c\u8bbe\u5b9a\u8fc7\u7a0b\u4e2d\u91c7\u7528\u4e00\u5200\u5207\u6807\u51c6\u6240\u5e26\u6765\u7684\u540e\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s002210902610297x", "journal": "JFQA", "title": "Political Affiliation and Media Distrust: Evidence from Stock Market Investors", "authors": ["Mancy Luo", "Alberto Manconi", "Massimo Massa"], "author_details": [{"name": "Mancy Luo", "affiliations": ["City University of London Bayes Business School"]}, {"name": "Alberto Manconi", "affiliations": ["Bocconi University"]}, {"name": "Massimo Massa", "affiliations": ["INSEAD"]}], "abstract": "Abstract Does distrust in politically affiliated media induce a bias in investor beliefs? We study the acquisition of Dow Jones & Co. by News Corporation in 2007 as a shock to the political affiliation of Dow Jones outlets. Following the acquisition, the prices of Republican- (Democrat-) aligned stocks become less sensitive to favorable (unfavorable) Dow Jones Newswires (DJNW) sentiment, consistent with the market attaching less credibility to a politically affiliated source. There is, however, no evidence of change in DJNW sentiment, coverage, or language about Republican/Democrat stocks, suggesting a loss of stock price informativeness. Consistent with this view, a portfolio exploiting the attenuated reaction to DJNW news earns abnormal returns following 2007.", "date": "2026-05-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s002210902610297x", "title_zh": "\u653f\u6cbb\u503e\u5411\u4e0e\u5a92\u4f53\u4e0d\u4fe1\u4efb\uff1a\u6765\u81ea\u80a1\u7968\u6295\u8d44\u8005\u7684\u8bc1\u636e", "abstract_zh": "\u62bd\u8c61 \u653f\u6cbb\u503e\u5411\u5a92\u4f53\u7684\u4e0d\u4fe1\u4efb\u662f\u5426\u4f1a\u5bfc\u81f4\u6295\u8d44\u8005\u4fe1\u5ff5\u7684\u504f\u5dee\uff1f\u6211\u4eec\u4ee52007\u5e74\u9053\u743c\u65af\u516c\u53f8\u88ab\u65b0\u95fb\u96c6\u56e2\u6536\u8d2d\u8fd9\u4e00\u4e8b\u4ef6\u4e3a\u51b2\u51fb\u70b9\uff0c\u7814\u7a76\u4e86\u8fd9\u4e00\u4e8b\u4ef6\u5bf9\u9053\u743c\u65af\u65b0\u95fb\uff08DJNW\uff09\u653f\u6cbb\u503e\u5411\u5185\u5bb9\u7684\u5f71\u54cd\u529b\u3002\u6536\u8d2d\u540e\uff0c\u652f\u6301\u5171\u548c\u515a\uff08\u6c11\u4e3b\u515a\uff09\u7684\u80a1\u7968\u5bf9\u9053\u743c\u65af\u65b0\u95fb\uff08DJNW\uff09\u79ef\u6781\uff08\u6d88\u6781\uff09\u60c5\u7eea\u7684\u53cd\u5e94\u51cf\u5f31\uff0c\u8fd9\u8868\u660e\u5e02\u573a\u5bf9\u5177\u6709\u653f\u6cbb\u503e\u5411\u7684\u5a92\u4f53\u6765\u6e90\u7684\u4fe1\u4efb\u5ea6\u4e0b\u964d\u3002\u7136\u800c\uff0cDJNW\u5bf9\u5171\u548c\u515a/\u6c11\u4e3b\u515a\u80a1\u7968\u7684\u62a5\u9053\u60c5\u7eea\u3001\u5185\u5bb9\u6216\u8bed\u8a00\u5e76\u672a\u53d1\u751f\u6539\u53d8\uff0c\u8868\u660e\u5176\u80a1\u4ef7\u4fe1\u606f\u542b\u91cf\u7684\u4e0b\u964d\u3002\u4e0e\u6b64\u4e00\u81f4\uff0c\u4e00\u4e2a\u5229\u7528\u6536\u8d2d\u540e\u5bf9DJNW\u65b0\u95fb\u53cd\u5e94\u51cf\u5f31\u7684\u7b56\u7565\uff0c\u57282007\u5e74\u540e\u83b7\u5f97\u4e86\u5f02\u5e38\u6536\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u5e02\u573a\u53cd\u9988"]}, {"doi": "10.1017/s0022109026102981", "journal": "JFQA", "title": "Stock Buybacks, Speculative Trading, and Shareholder Welfare", "authors": ["Alvin Chen"], "author_details": [{"name": "Alvin Chen", "affiliations": ["Stockholm School of Economics Department of Finance"]}], "abstract": "Abstract This article studies buybacks with two informed parties: a manager and an outside speculator. Buybacks introduce two countervailing forces. A competition effect reduces speculator profits when buybacks compete against speculative trades. A dispersion effect increases speculator profits: buying undervalued shares generates gains, while buying overvalued shares generates losses, widening the dispersion in per-share value across states. Sufficiently informed buybacks benefit shareholders; uninformed buybacks harm them. These effects vary with shareholders\u2019 liquidity exposures. The desirability of informed buybacks depends on the prevalence of speculation. Authorization depends on ownership, governance, and market conditions. Shareholders might welcome informed buybacks\u2014not merely tolerate them.", "date": "2026-05-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102981", "title_zh": "\u80a1\u7968\u56de\u8d2d\u3001\u6295\u673a\u4ea4\u6613\u4e0e\u80a1\u4e1c\u798f\u5229", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u7531\u7ba1\u7406\u8005\u548c\u5916\u90e8\u6295\u673a\u8005\u4e24\u65b9\u77e5\u60c5\u53c2\u4e0e\u7684\u56de\u8d2d\u884c\u4e3a\u3002\u56de\u8d2d\u884c\u4e3a\u5f15\u5165\u4e86\u4e24\u79cd\u76f8\u53cd\u7684\u4f5c\u7528\uff1a\u7ade\u4e89\u6548\u5e94\u4f1a\u964d\u4f4e\u6295\u673a\u8005\u5229\u6da6\uff0c\u56e0\u4e3a\u56de\u8d2d\u884c\u4e3a\u4e0e\u6295\u673a\u4ea4\u6613\u76f8\u4e92\u7ade\u4e89\uff1b\u5206\u6563\u6548\u5e94\u5219\u4f1a\u63d0\u5347\u6295\u673a\u8005\u5229\u6da6\uff1a\u4e70\u5165\u88ab\u4f4e\u4f30\u7684\u80a1\u7968\u4f1a\u4ea7\u751f\u6536\u76ca\uff0c\u800c\u4e70\u5165\u88ab\u9ad8\u4f30\u7684\u80a1\u7968\u4f1a\u4ea7\u751f\u635f\u5931\uff0c\u4ece\u800c\u6269\u5927\u4e0d\u540c\u72b6\u6001\u4e0b\u7684\u6bcf\u80a1\u4ef7\u503c\u5dee\u5f02\u3002\u5145\u5206\u77e5\u60c5\u7684\u56de\u8d2d\u884c\u4e3a\u6709\u5229\u4e8e\u80a1\u4e1c\uff1b\u800c\u7f3a\u4e4f\u77e5\u60c5\u7684\u56de\u8d2d\u884c\u4e3a\u5219\u635f\u5bb3\u80a1\u4e1c\u5229\u76ca\u3002\u8fd9\u4e9b\u6548\u5e94\u4f1a\u968f\u80a1\u4e1c\u7684\u6d41\u52a8\u6027\u66b4\u9732\u7a0b\u5ea6\u800c\u53d8\u5316\u3002\u77e5\u60c5\u56de\u8d2d\u884c\u4e3a\u7684\u53ef\u53d6\u6027\u53d6\u51b3\u4e8e\u6295\u673a\u884c\u4e3a\u7684\u666e\u904d\u7a0b\u5ea6\u3002\u6388\u6743\u51b3\u7b56\u53d6\u51b3\u4e8e\u6240\u6709\u6743\u7ed3\u6784\u3001\u6cbb\u7406\u673a\u5236\u4ee5\u53ca\u5e02\u573a\u72b6\u51b5\u3002\u80a1\u4e1c\u53ef\u80fd\u4f1a\u6b22\u8fce\u77e5\u60c5\u7684\u56de\u8d2d\u884c\u4e3a\u2014\u2014\u800c\u4e0d\u4ec5\u4ec5\u662f\u5bb9\u5fcd\u5b83\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag025", "journal": "REStud", "title": "Catastrophes, Delays, and Learning", "authors": ["Matti Liski", "Fran\u00e7ois Salani\u00e9"], "author_details": [{"name": "Matti Liski", "affiliations": ["Department of Economics, Aalto University, and Helsinki GSE ,"]}, {"name": "Fran\u00e7ois Salani\u00e9", "affiliations": ["Toulouse School of Economics, INRAE, Universit\u00e9 Toulouse Capitole , Toulouse ,"]}], "abstract": "Abstract We propose a simple and general model of experimentation in which reaching untried levels of a stock variable may, after a stochastic delay, lead to a catastrophe. Hence, at any point in time a catastrophe might well be under way, due to past experiments. We show how to measure this legacy of the past from prior beliefs and the chronicle of stock levels. We characterize the optimal policy as a function of the legacy and show that it leads to a new protocol for planning that applies to a general class of problems, encompassing the study of pandemics or climate change. Several original policy predictions follow, e.g. experimentation can stop but resume later.", "date": "2026-05-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag025", "title_zh": "\u707e\u96be\u3001\u5ef6\u8fdf\u4e0e\u5b66\u4e60", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u7b80\u5355\u4e14\u901a\u7528\u7684\u5b9e\u9a8c\u6a21\u578b\uff0c\u5728\u8be5\u6a21\u578b\u4e2d\uff0c\u80a1\u7968\u53d8\u91cf\u8fbe\u5230\u672a\u5c1d\u8bd5\u8fc7\u7684\u6c34\u5e73\u540e\uff0c\u53ef\u80fd\u5728\u968f\u673a\u5ef6\u8fdf\u4e4b\u540e\u5f15\u53d1\u4e00\u573a\u707e\u96be\u3002\u56e0\u6b64\uff0c\u5728\u4efb\u4f55\u65f6\u523b\uff0c\u7531\u4e8e\u8fc7\u53bb\u7684\u5b9e\u9a8c\uff0c\u707e\u96be\u90fd\u53ef\u80fd\u6b63\u5728\u53d1\u751f\u3002\u6211\u4eec\u5c55\u793a\u4e86\u5982\u4f55\u4ece\u5148\u524d\u7684\u4fe1\u5ff5\u548c\u80a1\u7968\u6c34\u5e73\u7684\u5386\u53f2\u8bb0\u5f55\u4e2d\u8861\u91cf\u8fd9\u79cd\u5386\u53f2\u9057\u7559\u6548\u5e94\u3002\u6211\u4eec\u628a\u6700\u4f18\u7b56\u7565\u8868\u5f81\u4e3a\u5bf9\u8fd9\u4e00\u9057\u7559\u6548\u5e94\u7684\u51fd\u6570\uff0c\u5e76\u8868\u660e\u8be5\u7b56\u7565\u5bfc\u81f4\u4e86\u4e00\u79cd\u9002\u7528\u4e8e\u4e00\u822c\u7c7b\u95ee\u9898\u7684\u65b0\u89c4\u5212\u534f\u8bae\uff0c\u6db5\u76d6\u5bf9\u6d41\u884c\u75c5\u6216\u6c14\u5019\u53d8\u5316\u7684\u7814\u7a76\u3002\u7531\u6b64\u5f97\u51fa\u82e5\u5e72\u65b0\u7684\u653f\u7b56\u9884\u6d4b\uff0c\u4f8b\u5982\u5b9e\u9a8c\u53ef\u4ee5\u505c\u6b62\u4f46\u7a0d\u540e\u91cd\u65b0\u5f00\u59cb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70051", "journal": "JF", "title": "Bank Competition Amid Digital Disruption: Implications for Financial Inclusion", "authors": ["ERICA XUEWEI JIANG", "GLORIA YANG YU", "JINYUAN ZHANG"], "author_details": [{"name": "ERICA XUEWEI JIANG", "affiliations": []}, {"name": "GLORIA YANG YU", "affiliations": []}, {"name": "JINYUAN ZHANG", "affiliations": []}], "abstract": "ABSTRACT We examine how digital disruption affects bank competition using the staggered rollout of 3G mobile networks. 3G expansion increased mobile banking adoption among tech\u2010savvy households, reducing branch networks\u2014especially in younger counties. Banks' strategies diverged: Less branch\u2010reliant banks closed branches and competed on price, while more branch\u2010reliant banks maintained branches but raised spreads. A structural model shows that perceived digital service improvements among younger consumers drove these shifts, reducing welfare for older savers. Counterfactuals demonstrate that subsidizing adoption for older savers can cost\u2010effectively reduce these disparities, facilitating a smoother digital transition.", "date": "2026-05-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70051", "title_zh": "\u6570\u5b57\u98a0\u8986\u80cc\u666f\u4e0b\u94f6\u884c\u7ade\u4e89\u5bf9\u91d1\u878d\u5305\u5bb9\u6027\u7684\u5f71\u54cd", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u75283G\u79fb\u52a8\u7f51\u7edc\u5206\u9636\u6bb5\u90e8\u7f72\u7684\u6570\u636e\uff0c\u7814\u7a76\u4e86\u6570\u5b57\u98a0\u8986\u5982\u4f55\u5f71\u54cd\u94f6\u884c\u7ade\u4e89\u30023G\u7f51\u7edc\u7684\u6269\u5c55\u63d0\u9ad8\u4e86\u6280\u672f\u5a34\u719f\u5bb6\u5ead\u7684\u79fb\u52a8\u94f6\u884c\u4f7f\u7528\u7387\uff0c\u5bfc\u81f4\u5206\u652f\u673a\u6784\u7f51\u7edc\u2014\u2014\u5c24\u5176\u662f\u5728\u5e74\u8f7b\u5730\u533a\u2014\u2014\u5927\u5e45\u7f29\u51cf\u3002\u94f6\u884c\u7684\u7b56\u7565\u51fa\u73b0\u5206\u5316\uff1a\u8f83\u5c11\u4f9d\u8d56\u5206\u652f\u673a\u6784\u7684\u94f6\u884c\u5173\u95ed\u4e86\u5206\u652f\u673a\u6784\u5e76\u8f6c\u5411\u4ef7\u683c\u7ade\u4e89\uff0c\u800c\u66f4\u591a\u4f9d\u8d56\u5206\u652f\u673a\u6784\u7684\u94f6\u884c\u5219\u7ef4\u6301\u4e86\u5206\u652f\u673a\u6784\u4f46\u63d0\u9ad8\u4e86\u5229\u5dee\u3002\u7ed3\u6784\u6a21\u578b\u8868\u660e\uff0c\u5e74\u8f7b\u6d88\u8d39\u8005\u5bf9\u6570\u5b57\u670d\u52a1\u6539\u5584\u7684\u611f\u77e5\u63a8\u52a8\u4e86\u8fd9\u4e9b\u7b56\u7565\u8f6c\u53d8\uff0c\u4ece\u800c\u964d\u4f4e\u4e86\u8001\u5e74\u50a8\u6237\u7684\u798f\u5229\u3002\u53cd\u4e8b\u5b9e\u5206\u6790\u663e\u793a\uff0c\u4e3a\u8001\u5e74\u50a8\u6237\u63d0\u4f9b\u91c7\u7528\u8865\u8d34\u53ef\u4ee5\u5728\u964d\u4f4e\u8fd9\u4e9b\u5dee\u8ddd\u7684\u540c\u65f6\u5b9e\u73b0\u6210\u672c\u6548\u76ca\uff0c\u6709\u52a9\u4e8e\u5b9e\u73b0\u66f4\u5e73\u7a33\u7684\u6570\u5b57\u5316\u8f6c\u578b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/restud/rdag042", "journal": "REStud", "title": "Monetary Policy and Endogenous Financial Crises", "authors": ["F Boissay", "F Collard", "J Gal\u00ed", "C Manea"], "author_details": [{"name": "F Boissay", "affiliations": ["Bank for International Settlements ,"]}, {"name": "F Collard", "affiliations": ["Toulouse School of Economics (CNRS) , France"]}, {"name": "J Gal\u00ed", "affiliations": ["CREI, Universitat Pompeu Fabra and Barcelona School of Economics ,"]}, {"name": "C Manea", "affiliations": ["Bank for International Settlements ,"]}], "abstract": "Abstract What are the channels through which monetary policy affects financial stability? Can (and should) central banks prevent financial crises by deviating from price stability? To what extent may monetary policy itself unintentionally breed financial vulnerabilities? We answer these questions using a New Keynesian model with capital accumulation and endogenous financial crises due to adverse selection and moral hazard in credit markets. Our findings are threefold. First, monetary policy affects the probability of a crisis both in the short run (via aggregate demand) and in the medium run (via capital accumulation). Second, the central bank can reduce the incidence of crises in the medium run by tolerating higher inflation volatility in the short run. Third, prolonged periods of loose monetary policy followed by a sharp tightening can lead to financial crises.", "date": "2026-05-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag042", "title_zh": "\u8d27\u5e01\u653f\u7b56\u4e0e\u5185\u751f\u91d1\u878d\u5371\u673a", "abstract_zh": "\u6458\u8981 \u8d27\u5e01\u653f\u7b56\u5982\u4f55\u5f71\u54cd\u91d1\u878d\u7a33\u5b9a\uff1f\u4e2d\u592e\u94f6\u884c\u662f\u5426\uff08\u4ee5\u53ca\u5e94\u5f53\uff09\u901a\u8fc7\u504f\u79bb\u4ef7\u683c\u7a33\u5b9a\u6765\u9884\u9632\u91d1\u878d\u5371\u673a\uff1f\u8d27\u5e01\u653f\u7b56\u672c\u8eab\u662f\u5426\u4f1a\u65e0\u610f\u4e2d\u50ac\u751f\u91d1\u878d\u8106\u5f31\u6027\uff1f\u6211\u4eec\u5229\u7528\u4e00\u4e2a\u5305\u542b\u8d44\u672c\u79ef\u7d2f\u4ee5\u53ca\u7531\u4fe1\u8d37\u5e02\u573a\u4e2d\u7684\u9006\u5411\u9009\u62e9\u548c\u9053\u5fb7\u98ce\u9669\u5f15\u53d1\u7684\u5185\u751f\u91d1\u878d\u5371\u673a\u7684\u65b0\u51ef\u6069\u65af\u6a21\u578b\u6765\u56de\u7b54\u8fd9\u4e9b\u95ee\u9898\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u6709\u4e09\u70b9\uff1a\u7b2c\u4e00\uff0c\u8d27\u5e01\u653f\u7b56\u901a\u8fc7\u603b\u9700\u6c42\u5728\u77ed\u671f\u5185\u4ee5\u53ca\u901a\u8fc7\u8d44\u672c\u79ef\u7d2f\u5728\u4e2d\u671f\u5185\u5f71\u54cd\u91d1\u878d\u5371\u673a\u53d1\u751f\u7684\u6982\u7387\uff1b\u7b2c\u4e8c\uff0c\u4e2d\u592e\u94f6\u884c\u53ef\u4ee5\u901a\u8fc7\u5728\u77ed\u671f\u5185\u5bb9\u5fcd\u66f4\u9ad8\u7684\u901a\u8d27\u81a8\u80c0\u6ce2\u52a8\u6027\u6765\u964d\u4f4e\u4e2d\u671f\u5185\u91d1\u878d\u5371\u673a\u7684\u53d1\u751f\u9891\u7387\uff1b\u7b2c\u4e09\uff0c\u957f\u671f\u5bbd\u677e\u8d27\u5e01\u653f\u7b56\u540e\u7a81\u7136\u7d27\u7f29\u53ef\u80fd\u5f15\u53d1\u91d1\u878d\u5371\u673a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1093/restud/rdag032", "journal": "REStud", "title": "Financial Intermediation and Aggregate Demand: A Sufficient Statistics Approach", "authors": ["Yu-Ting Chiang", "Piotr Zoch"], "author_details": [{"name": "Yu-Ting Chiang", "affiliations": ["Federal Reserve Bank of St. Louis ,"]}, {"name": "Piotr Zoch", "affiliations": ["University of Warsaw and FAME \u2223 GRAPE ,"]}], "abstract": "Abstract We show that the financial sector\u2019s asset supply elasticities are sufficient statistics summarizing its macroeconomic effects for a large class of financial frictions. These elasticities are crucial for a wide range of policy questions, ranging from the size of fiscal multipliers to the relative effectiveness of asset purchases targeting the financial sector versus tax cuts targeting households. Workhorse macroeconomic models imply different values of these elasticities, generating output responses to policies that differ by orders of magnitude. We construct empirical measures of these elasticities and evaluate their policy implications in a quantitative model with household heterogeneity and illiquidity.", "date": "2026-05-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag032", "title_zh": "\u91d1\u878d\u4e2d\u4ecb\u4e0e\u603b\u9700\u6c42\uff1a\u4e00\u4e2a\u5145\u5206\u7edf\u8ba1\u65b9\u6cd5", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u8bc1\u660e\u4e86\u91d1\u878d\u90e8\u95e8\u7684\u8d44\u4ea7\u4f9b\u7ed9\u5f39\u6027\u662f\u603b\u7ed3\u5176\u5b8f\u89c2\u7ecf\u6d4e\u6548\u5e94\u7684\u5145\u5206\u7edf\u8ba1\u91cf\uff0c\u9002\u7528\u4e8e\u4e00\u5927\u7c7b\u91d1\u878d\u6469\u64e6\u60c5\u5f62\u3002\u8fd9\u4e9b\u5f39\u6027\u5bf9\u4e8e\u5e7f\u6cdb\u653f\u7b56\u95ee\u9898\u81f3\u5173\u91cd\u8981\uff0c\u4f8b\u5982\u8d22\u653f\u4e58\u6570\u7684\u5927\u5c0f\uff0c\u4ee5\u53ca\u9488\u5bf9\u91d1\u878d\u90e8\u95e8\u7684\u8d44\u4ea7\u8d2d\u4e70\u4e0e\u9488\u5bf9\u5bb6\u5ead\u7684\u51cf\u7a0e\u5728\u653f\u7b56\u6548\u679c\u4e0a\u7684\u76f8\u5bf9\u6709\u6548\u6027\u3002\u4e3b\u6d41\u5b8f\u89c2\u7ecf\u6d4e\u6a21\u578b\u5bf9\u8fd9\u4e9b\u5f39\u6027\u7ed9\u51fa\u4e86\u4e0d\u540c\u7684\u6570\u503c\uff0c\u5bfc\u81f4\u653f\u7b56\u5bf9\u4ea7\u51fa\u7684\u54cd\u5e94\u5dee\u5f02\u8fbe\u6570\u91cf\u7ea7\u3002\u6211\u4eec\u6784\u5efa\u4e86\u8fd9\u4e9b\u5f39\u6027\u7684\u5b9e\u8bc1\u5ea6\u91cf\uff0c\u5e76\u5728\u5305\u542b\u5bb6\u5ead\u5f02\u8d28\u6027\u548c\u975e\u6d41\u52a8\u6027\u7684\u91cf\u5316\u6a21\u578b\u4e2d\u8bc4\u4f30\u5176\u653f\u7b56\u542b\u4e49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag044", "journal": "REStud", "title": "Loose Monetary Policy and Financial Instability", "authors": ["Maximilian Grimm", "\u00d2scar Jord\u00e0", "Moritz Schularick", "Alan M Taylor"], "author_details": [{"name": "Maximilian Grimm", "affiliations": ["Federal Reserve Board ,"]}, {"name": "\u00d2scar Jord\u00e0", "affiliations": ["Federal Reserve Bank of San Francisco and University of California, Davis, USA; and CEPR ,"]}, {"name": "Moritz Schularick", "affiliations": ["Kiel Institute, Germany; Sciences Po Paris, France; and CEPR , UK"]}, {"name": "Alan M Taylor", "affiliations": ["Bank of England, UK; Columbia University and NBER, USA; and CEPR , UK"]}], "abstract": "Abstract Do periods of persistently loose monetary policy increase financial fragility and the likelihood of a financial crisis? This is a central question for policymakers, yet the literature does not provide systematic empirical evidence about this link at the aggregate level. In this article, we fill this gap by analysing long-run historical data. We find that when the stance of monetary policy is accommodative over an extended period, the likelihood of financial turmoil in the medium term increases considerably. We investigate the causal pathways that lead to this result and argue that credit creation and asset price overheating are important intermediating channels.", "date": "2026-05-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag044", "title_zh": "\u5bbd\u677e\u8d27\u5e01\u653f\u7b56\u4e0e\u91d1\u878d\u4e0d\u7a33\u5b9a", "abstract_zh": "\u6458\u8981 \u5bbd\u677e\u8d27\u5e01\u653f\u7b56\u6301\u7eed\u5b58\u5728\u662f\u5426\u4f1a\u5bfc\u81f4\u91d1\u878d\u8106\u5f31\u6027\u4e0a\u5347\u4ee5\u53ca\u91d1\u878d\u5371\u673a\u53d1\u751f\u7684\u53ef\u80fd\u6027\u589e\u52a0\uff1f\u8fd9\u662f\u653f\u7b56\u5236\u5b9a\u8005\u9762\u4e34\u7684\u6838\u5fc3\u95ee\u9898\uff0c\u7136\u800c\u73b0\u6709\u6587\u732e\u5e76\u672a\u5728\u6574\u4f53\u5c42\u9762\u63d0\u4f9b\u7cfb\u7edf\u7684\u5b9e\u8bc1\u8bc1\u636e\u6765\u8bf4\u660e\u8fd9\u4e00\u5173\u8054\u3002\u672c\u6587\u901a\u8fc7\u5206\u6790\u957f\u671f\u5386\u53f2\u6570\u636e\u586b\u8865\u4e86\u8fd9\u4e00\u7a7a\u767d\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5f53\u8d27\u5e01\u653f\u7b56\u7acb\u573a\u5728\u8f83\u957f\u65f6\u671f\u5185\u4fdd\u6301\u5bbd\u677e\u65f6\uff0c\u4e2d\u671f\u5185\u51fa\u73b0\u91d1\u878d\u52a8\u8361\u7684\u53ef\u80fd\u6027\u663e\u8457\u4e0a\u5347\u3002\u6211\u4eec\u63a2\u8ba8\u4e86\u5bfc\u81f4\u8fd9\u4e00\u7ed3\u679c\u7684\u56e0\u679c\u8def\u5f84\uff0c\u5e76\u8ba4\u4e3a\u4fe1\u8d37\u6269\u5f20\u548c\u8d44\u4ea7\u4ef7\u683c\u8fc7\u70ed\u662f\u91cd\u8981\u7684\u4e2d\u4ecb\u6e20\u9053\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1111/jofi.70044", "journal": "JF", "title": "Consumption in Asset Returns", "authors": ["SVETLANA BRYZGALOVA", "JIANTAO HUANG", "CHRISTIAN JULLIARD"], "author_details": [{"name": "SVETLANA BRYZGALOVA", "affiliations": []}, {"name": "JIANTAO HUANG", "affiliations": []}, {"name": "CHRISTIAN JULLIARD", "affiliations": []}], "abstract": "ABSTRACT Using information in returns, we identify the stochastic process of consumption. We find that aggregate consumption reacts over multiple quarters to innovations spanned by financial markets. This persistent component accounts for over a quarter of consumption variation. These shocks command a large and significant risk premium, driving a large share of stocks' and a small yet significant fraction of bonds' time\u2010series variation. Nevertheless, we find no support for stochastic volatility of consumption driving time\u2010varying risk premia. Finally, an otherwise standard recursive utility model based on our estimated process explains equity premium and risk\u2010free rate puzzles with low\u2010risk aversion.", "date": "2026-05-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70044", "title_zh": "\u8d44\u4ea7\u56de\u62a5\u4e2d\u7684\u6d88\u8d39", "abstract_zh": "\u4f7f\u7528\u56de\u62a5\u4fe1\u606f\uff0c\u6211\u4eec\u8bc6\u522b\u51fa\u6d88\u8d39\u7684\u968f\u673a\u8fc7\u7a0b\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u603b\u6d88\u8d39\u5bf9\u91d1\u878d\u5e02\u573a\u7684\u521b\u65b0\u5728\u591a\u4e2a\u5b63\u5ea6\u5185\u4ea7\u751f\u53cd\u5e94\u3002\u8fd9\u4e00\u6301\u7eed\u6027\u6210\u5206\u89e3\u91ca\u4e86\u6d88\u8d39\u53d8\u5f02\u7684\u56db\u5206\u4e4b\u4e00\u4ee5\u4e0a\u3002\u8fd9\u4e9b\u51b2\u51fb\u5e26\u6765\u4e86\u663e\u8457\u4e14\u5de8\u5927\u7684\u98ce\u9669\u6ea2\u4ef7\uff0c\u9a71\u52a8\u4e86\u80a1\u7968\u5e02\u573a\u5927\u90e8\u5206\u7684\u65f6\u95f4\u5e8f\u5217\u53d8\u5f02\uff0c\u4ee5\u53ca\u503a\u5238\u5e02\u573a\u4e2d\u4e00\u5c0f\u90e8\u5206\u4f46\u663e\u8457\u7684\u53d8\u5f02\u3002\u7136\u800c\uff0c\u6211\u4eec\u5e76\u672a\u53d1\u73b0\u6d88\u8d39\u7684\u968f\u673a\u6ce2\u52a8\u6027\u80fd\u591f\u89e3\u91ca\u65f6\u95f4\u53d8\u5316\u7684\u98ce\u9669\u6ea2\u4ef7\u3002\u6700\u540e\uff0c\u57fa\u4e8e\u6211\u4eec\u4f30\u8ba1\u8fc7\u7a0b\u7684\u5e38\u89c4\u9012\u5f52\u6548\u7528\u6a21\u578b\uff0c\u5373\u4f7f\u5728\u98ce\u9669\u538c\u6076\u7a0b\u5ea6\u8f83\u4f4e\u7684\u60c5\u51b5\u4e0b\uff0c\u4e5f\u80fd\u89e3\u91ca\u80a1\u6743\u6ea2\u4ef7\u548c\u65e0\u98ce\u9669\u5229\u7387\u4e4b\u8c1c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1111/jofi.70049", "journal": "JF", "title": "The Drivers and Implications of Retail Margin Trading", "authors": ["JIANGZE BIAN", "ZHI DA", "ZHIGUO HE", "DONG LOU", "KELLY SHUE", "HAO ZHOU"], "author_details": [{"name": "JIANGZE BIAN", "affiliations": []}, {"name": "ZHI DA", "affiliations": []}, {"name": "ZHIGUO HE", "affiliations": []}, {"name": "DONG LOU", "affiliations": []}, {"name": "KELLY SHUE", "affiliations": []}, {"name": "HAO ZHOU", "affiliations": []}], "abstract": "ABSTRACT Using granular data covering both regulated (brokerage\u2010financed) and unregulated (shadow\u2010financed) margin accounts in China, we provide novel evidence on retail investors' margin trading behavior and its price implications. We first show that retail investors' decisions to lever up in stock trading despite the hefty borrowing cost is related to their lottery preferences. We then show that margin borrowing affects investors' trading behavior\u2014investors are more likely to liquidate their holdings as they approach margin calls. Finally, we show that margin\u2010induced trading aggregates to affect asset prices and contributes to shock spillovers across stocks (e.g., from lottery stocks to nonlottery stocks).", "date": "2026-05-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70049", "title_zh": "\u96f6\u552e\u6760\u6746\u4ea4\u6613\u7684\u9a71\u52a8\u56e0\u7d20\u53ca\u5176\u5f71\u54cd", "abstract_zh": "\u6458\u8981 \u4f7f\u7528\u8986\u76d6\u4e2d\u56fd\u76d1\u7ba1\uff08\u7ecf\u7eaa\u878d\u8d44\uff09\u548c\u975e\u76d1\u7ba1\uff08\u5f71\u5b50\u878d\u8d44\uff09\u6760\u6746\u8d26\u6237\u7684\u7ec6\u7c92\u5ea6\u6570\u636e\uff0c\u6211\u4eec\u63d0\u4f9b\u4e86\u5173\u4e8e\u96f6\u552e\u6295\u8d44\u8005\u6760\u6746\u4ea4\u6613\u884c\u4e3a\u53ca\u5176\u4ef7\u683c\u5f71\u54cd\u7684\u5168\u65b0\u8bc1\u636e\u3002\u6211\u4eec\u9996\u5148\u53d1\u73b0\uff0c\u5c3d\u7ba1\u501f\u8d37\u6210\u672c\u8f83\u9ad8\uff0c\u96f6\u552e\u6295\u8d44\u8005\u4ecd\u9009\u62e9\u5728\u80a1\u7968\u4ea4\u6613\u4e2d\u589e\u52a0\u6760\u6746\uff0c\u8fd9\u4e0e\u5176\u5f69\u7968\u504f\u597d\u6709\u5173\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u53d1\u73b0\uff0c\u6760\u6746\u501f\u6b3e\u4f1a\u5f71\u54cd\u6295\u8d44\u8005\u7684\u4ea4\u6613\u884c\u4e3a\u2014\u2014\u5f53\u6295\u8d44\u8005\u63a5\u8fd1\u8ffd\u52a0\u4fdd\u8bc1\u91d1\u901a\u77e5\u65f6\uff0c\u66f4\u53ef\u80fd\u5e73\u4ed3\u5176\u6301\u4ed3\u3002\u6700\u540e\uff0c\u6211\u4eec\u53d1\u73b0\u7531\u6760\u6746\u5f15\u53d1\u7684\u4ea4\u6613\u603b\u91cf\u4f1a\u5bf9\u8d44\u4ea7\u4ef7\u683c\u4ea7\u751f\u5f71\u54cd\uff0c\u5e76\u5bfc\u81f4\u80a1\u7968\u4e4b\u95f4\u7684\u51b2\u51fb\u6ea2\u51fa\uff08\u4f8b\u5982\uff0c\u4ece\u5f69\u7968\u80a1\u5230\u975e\u5f69\u7968\u80a1\uff09\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag046", "journal": "REStud", "title": "Optimal Labour Income Taxation: A Flexible Moral Hazard Approach", "authors": ["Narayana R Kocherlakota"], "author_details": [{"name": "Narayana R Kocherlakota", "affiliations": ["University of Rochester and NBER , USA"]}], "abstract": "Abstract This article reconsiders the question of optimal labour income taxes for the very rich in the context of a flexible moral hazard model. In this setting, risk is not exogenous. Rather, each agent can affect the probabilities of all possible income outcomes by allocating a fixed time endowment across a variety of distinct tasks. I prove that the optimal income tax rates on high-end earners and the optimal Pareto tail index of the pre-tax labour income distribution are both endogenously determined by agent preferences. In particular, a society with less risk-averse agents will find it optimal to impose a lower tax rate on the rich, even though its members\u2019 choices give rise to a smaller Pareto right tail index. In contrast, this kind of negative co-movement between inequality and optimal tax rates is a suboptimal response in the classical Mirrlees (1971)\u2013Diamond (1998)\u2013Saez (2001) setup to changes in the exogenous distribution of skills.", "date": "2026-05-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag046", "title_zh": "\u6700\u4f18\u52b3\u52a8\u6536\u5165\u7a0e\u6536\uff1a\u4e00\u79cd\u7075\u6d3b\u7684\u9053\u5fb7\u98ce\u9669\u65b9\u6cd5", "abstract_zh": "\u672c\u6587\u5728\u4e00\u79cd\u7075\u6d3b\u7684\u9053\u5fb7\u98ce\u9669\u6a21\u578b\u80cc\u666f\u4e0b\u91cd\u65b0\u5ba1\u89c6\u5bf9\u9ad8\u6536\u5165\u7fa4\u4f53\u5f81\u6536\u6700\u4f18\u52b3\u52a8\u6536\u5165\u7a0e\u6536\u7684\u95ee\u9898\u3002\u5728\u8be5\u6a21\u578b\u4e2d\uff0c\u98ce\u9669\u5e76\u975e\u5916\u751f\u7ed9\u5b9a\uff0c\u800c\u662f\u6bcf\u4e2a\u4e2a\u4f53\u901a\u8fc7\u5c06\u56fa\u5b9a\u7684\u65f6\u95f4\u7980\u8d4b\u5206\u914d\u5230\u591a\u79cd\u4e0d\u540c\u4efb\u52a1\u4e2d\uff0c\u80fd\u591f\u5f71\u54cd\u6240\u6709\u53ef\u80fd\u6536\u5165\u7ed3\u679c\u7684\u6982\u7387\u3002\u6211\u8bc1\u660e\uff0c\u5bf9\u9ad8\u6536\u5165\u7fa4\u4f53\u7684\u6700\u4f18\u6536\u5165\u7a0e\u7387\u4ee5\u53ca\u9884\u7a0e\u52b3\u52a8\u6536\u5165\u5206\u5e03\u7684\u5e15\u7d2f\u6258\u5c3e\u90e8\u6307\u6570\uff0c\u90fd\u662f\u7531\u4e2a\u4f53\u504f\u597d\u5185\u751f\u51b3\u5b9a\u7684\u3002\u5177\u4f53\u800c\u8a00\uff0c\u4e00\u4e2a\u98ce\u9669\u538c\u6076\u7a0b\u5ea6\u8f83\u4f4e\u7684\u793e\u4f1a\u4f1a\u53d1\u73b0\uff0c\u5bf9\u5bcc\u4eba\u5f81\u6536\u66f4\u4f4e\u7684\u7a0e\u7387\u662f\u66f4\u4f18\u9009\u62e9\uff0c\u5373\u4f7f\u5176\u6210\u5458\u7684\u9009\u62e9\u5bfc\u81f4\u5e15\u7d2f\u6258\u53f3\u5c3e\u6307\u6570\u66f4\u5c0f\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u5728\u7ecf\u5178\u7684Mirrlees\uff081971\uff09\u2014Diamond\uff081998\uff09\u2014Saez\uff082001\uff09\u6a21\u578b\u4e2d\uff0c\u5916\u751f\u6280\u80fd\u5206\u5e03\u53d8\u5316\u6240\u5f15\u53d1\u7684\u4e0d\u5e73\u7b49\u4e0e\u6700\u4f18\u7a0e\u7387\u4e4b\u95f4\u7684\u8d1f\u76f8\u5173\u5173\u7cfb\u662f\u4e00\u79cd\u6b21\u4f18\u53cd\u5e94\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag031", "journal": "REStud", "title": "Input Sourcing under Climate Risk: Evidence from U.S. Manufacturing Firms", "authors": ["Joaquin Blaum", "Federico Esposito", "Sebastian Heise"], "author_details": [{"name": "Joaquin Blaum", "affiliations": ["Boston University ,"]}, {"name": "Federico Esposito", "affiliations": ["Fordham University ,"]}, {"name": "Sebastian Heise", "affiliations": ["Federal Reserve Bank of New York ,"]}], "abstract": "Abstract We study the effect of risk on how firms organize their supply chains. We use transaction-level data on U.S. manufacturing imports to construct a novel measure of input sourcing risk based on the historical volatility of ocean shipping times. Our measure isolates the unexpected component of shipping times that is induced by weather conditions along more than 331,000 maritime routes. We first document that unexpected shipping delays significantly reduce importers\u2019 sales, profits, and employment. We then show that firms actively diversify weather risk by using more routes and foreign suppliers, although their import values decline. To rationalize these findings, we introduce shipping time risk into a general equilibrium model of importing with firm heterogeneity. Our quantitative analysis predicts substantial costs for the U.S. economy associated with supply chain risk.", "date": "2026-05-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag031", "title_zh": "\u6c14\u5019\u98ce\u9669\u4e0b\u7684\u8f93\u5165\u91c7\u8d2d\uff1a\u6765\u81ea\u7f8e\u56fd\u5236\u9020\u4e1a\u4f01\u4e1a\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u98ce\u9669\u5982\u4f55\u5f71\u54cd\u4f01\u4e1a\u7ec4\u7ec7\u5176\u4f9b\u5e94\u94fe\u7684\u65b9\u5f0f\u3002\u6211\u4eec\u5229\u7528\u7f8e\u56fd\u5236\u9020\u4e1a\u8fdb\u53e3\u7684\u4ea4\u6613\u7ea7\u6570\u636e\uff0c\u6784\u5efa\u4e86\u4e00\u4e2a\u57fa\u4e8e\u5386\u53f2\u6d77\u6d0b\u822a\u8fd0\u65f6\u95f4\u6ce2\u52a8\u6027\u7684\u65b0\u578b\u8f93\u5165\u91c7\u8d2d\u98ce\u9669\u8861\u91cf\u6307\u6807\u3002\u8be5\u6307\u6807\u5206\u79bb\u51fa\u7531\u5929\u6c14\u6761\u4ef6\u5f15\u8d77\u7684\u3001\u6cbf331,000\u591a\u6761\u6d77\u4e0a\u822a\u7ebf\u4ea7\u751f\u7684\u822a\u8fd0\u65f6\u95f4\u610f\u5916\u5ef6\u8fdf\u90e8\u5206\u3002\u6211\u4eec\u9996\u5148\u53d1\u73b0\uff0c\u610f\u5916\u7684\u822a\u8fd0\u5ef6\u8bef\u663e\u8457\u964d\u4f4e\u4e86\u8fdb\u53e3\u5546\u7684\u9500\u552e\u989d\u3001\u5229\u6da6\u548c\u5c31\u4e1a\u6c34\u5e73\u3002\u968f\u540e\u6211\u4eec\u8868\u660e\uff0c\u4f01\u4e1a\u901a\u8fc7\u589e\u52a0\u822a\u7ebf\u548c\u5916\u56fd\u4f9b\u5e94\u5546\u6765\u4e3b\u52a8\u5206\u6563\u5929\u6c14\u98ce\u9669\uff0c\u5c3d\u7ba1\u5176\u8fdb\u53e3\u989d\u4e0b\u964d\u3002\u4e3a\u4e86\u89e3\u91ca\u8fd9\u4e9b\u53d1\u73b0\uff0c\u6211\u4eec\u5c06\u5728\u5305\u542b\u4f01\u4e1a\u5f02\u8d28\u6027\u7684\u8fdb\u53e3\u4e00\u822c\u5747\u8861\u6a21\u578b\u4e2d\u5f15\u5165\u822a\u8fd0\u65f6\u95f4\u98ce\u9669\u3002\u6211\u4eec\u7684\u5b9a\u91cf\u5206\u6790\u9884\u6d4b\u4e86\u4f9b\u5e94\u94fe\u98ce\u9669\u5bf9\u7f8e\u56fd\u7ecf\u6d4e\u5e26\u6765\u7684\u91cd\u5927\u6210\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/restud/rdag029", "journal": "REStud", "title": "When is TSLS Actually LATE?", "authors": ["Christine Blandhol", "John Bonney", "Magne Mogstad", "Alexander Torgovitsky"], "author_details": [{"name": "Christine Blandhol", "affiliations": ["Department of Economics, Princeton University ,"]}, {"name": "John Bonney", "affiliations": ["Department of Economics, Stanford University ,"]}, {"name": "Magne Mogstad", "affiliations": ["Kenneth C. Griffin Department of Economics, University of Chicago, USA; Statistics Norway, Norway; and NBER ,"]}, {"name": "Alexander Torgovitsky", "affiliations": ["Kenneth C. Griffin Department of Economics, University of Chicago ,"]}], "abstract": "Abstract Linear instrumental variable estimators, such as two-stage least squares (TSLS), are commonly interpreted as estimating non-negatively weighted averages of causal effects, referred to as local average treatment effects (LATEs). We examine whether the LATE interpretation actually applies to the types of TSLS specifications that are used in practice. We show that if the specification includes covariates\u2014which most empirical work does\u2014then the LATE interpretation does not apply in general. Instead, the TSLS estimator will, in general, reflect treatment effects for both compliers and always/never-takers, and some treatment effects for the always/never-takers will necessarily be negatively weighted. We show that the only specifications that have a LATE interpretation are \u201csaturated\u201d specifications that control for covariates nonparametrically, implying that such specifications are both sufficient and necessary for TSLS to have a LATE interpretation, at least without additional parametric assumptions. This result is concerning because, as we document, empirical researchers almost never control for covariates nonparametrically, and rarely discuss or justify parametric specifications of covariates. We apply our results to thirteen empirical studies and find strong evidence that the LATE interpretation of TSLS is far from accurate for the types of specifications actually used in practice. We offer concrete recommendations for practice motivated by our theoretical and empirical results.", "date": "2026-05-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag029", "title_zh": "TSLS \u4f55\u65f6\u624d\u771f\u6b63\u662f LATE\uff1f", "abstract_zh": "\u7ebf\u6027\u5de5\u5177\u53d8\u91cf\u4f30\u8ba1\u91cf\uff0c\u5982\u4e24\u9636\u6bb5\u6700\u5c0f\u4e8c\u4e58\u6cd5\uff08TSLS\uff09\uff0c\u901a\u5e38\u88ab\u89e3\u91ca\u4e3a\u4f30\u8ba1\u56e0\u679c\u6548\u5e94\u7684\u975e\u8d1f\u52a0\u6743\u5e73\u5747\u503c\uff0c\u5373\u5c40\u90e8\u5e73\u5747\u5904\u7406\u6548\u5e94\uff08LATE\uff09\u3002\u6211\u4eec\u8003\u5bdf\u4e86TSLS\u5728\u5b9e\u9645\u5e94\u7528\u4e2d\u6240\u91c7\u7528\u7684\u89c4\u683c\u8bbe\u5b9a\u4e0b\uff0cLATE\u89e3\u91ca\u662f\u5426\u6210\u7acb\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5982\u679c\u89c4\u683c\u4e2d\u5305\u542b\u534f\u53d8\u91cf\u2014\u2014\u800c\u8fd9\u5728\u5927\u591a\u6570\u5b9e\u8bc1\u7814\u7a76\u4e2d\u90fd\u662f\u5982\u6b64\u2014\u2014\u90a3\u4e48LATE\u89e3\u91ca\u4e00\u822c\u4e0d\u6210\u7acb\u3002\u76f8\u53cd\uff0cTSLS\u4f30\u8ba1\u91cf\u901a\u5e38\u4f1a\u53cd\u6620\u5408\u89c4\u8005\u548c\u59cb\u7ec8\u63a5\u53d7/\u59cb\u7ec8\u62d2\u7edd\u5904\u7406\u8005\u7684\u5904\u7406\u6548\u5e94\uff0c\u4e14\u5bf9\u59cb\u7ec8\u63a5\u53d7/\u59cb\u7ec8\u62d2\u7edd\u5904\u7406\u8005\u7684\u90e8\u5206\u5904\u7406\u6548\u5e94\u5fc5\u7136\u5e26\u6709\u8d1f\u6743\u91cd\u3002\u6211\u4eec\u6307\u51fa\uff0c\u53ea\u6709\u5728\u534f\u53d8\u91cf\u975e\u53c2\u6570\u5316\u63a7\u5236\u7684\u201c\u9971\u548c\u201d\u89c4\u683c\u4e2d\uff0cTSLS\u624d\u5177\u6709LATE\u89e3\u91ca\uff0c\u8fd9\u610f\u5473\u7740\u6b64\u7c7b\u89c4\u683c\u65e2\u662fTSLS\u5177\u6709LATE\u89e3\u91ca\u7684\u5145\u5206\u6761\u4ef6\uff0c\u4e5f\u662f\u5fc5\u8981\u6761\u4ef6\uff08\u81f3\u5c11\u5728\u4e0d\u5f15\u5165\u989d\u5916\u53c2\u6570\u5047\u8bbe\u7684\u524d\u63d0\u4e0b\uff09\u3002\u8fd9\u4e00\u7ed3\u679c\u4ee4\u4eba\u62c5\u5fe7\uff0c\u56e0\u4e3a\u6211\u4eec\u53d1\u73b0\uff0c\u5b9e\u8bc1\u7814\u7a76\u8005\u51e0\u4e4e\u4ece\u4e0d\u91c7\u7528\u975e\u53c2\u6570\u5316\u63a7\u5236\u534f\u53d8\u91cf\uff0c\u4e14\u5f88\u5c11\u8ba8\u8bba\u6216\u8bba\u8bc1\u534f\u53d8\u91cf\u7684\u53c2\u6570\u5316\u8bbe\u5b9a\u3002\u6211\u4eec\u5c06\u7ed3\u679c\u5e94\u7528\u4e8e\u5341\u4e09\u9879\u5b9e\u8bc1\u7814\u7a76\uff0c\u53d1\u73b0TSLS\u7684LATE\u89e3\u91ca\u5728\u5b9e\u9645\u4f7f\u7528\u7684\u89c4\u683c\u4e2d\u8fdc\u975e\u51c6\u786e\u3002\u6211\u4eec\u57fa\u4e8e\u7406\u8bba\u548c\u5b9e\u8bc1\u7ed3\u679c\uff0c\u63d0\u51fa\u5177\u4f53\u7684\u5b9e\u8df5\u5efa\u8bae\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag026", "journal": "REStud", "title": "A Model of Multiple Hypothesis Testing", "authors": ["Davide Viviano", "Kaspar W\u00fcthrich", "Paul Niehaus"], "author_details": [{"name": "Davide Viviano", "affiliations": ["Harvard University ,"]}, {"name": "Kaspar W\u00fcthrich", "affiliations": ["University of Michigan ,"]}, {"name": "Paul Niehaus", "affiliations": ["UC San Diego, USA"]}], "abstract": "Abstract Multiple hypothesis testing (MHT) practices vary widely, without consensus on which are appropriate when. This article provides an economic foundation for these practices designed to capture leading examples, such as regulatory approval on the basis of clinical trials. MHT adjustments are appropriate in our framework to the extent that research costs are invariant to the number of hypotheses. Control of average size, as for example via a Bonferroni correction, emerges in the limit case where all costs are fixed; in the opposite limit, where costs vary in proportion to the hypothesis count, no correction is needed. We illustrate implications by calculating explicit critical values using data on actual costs in the drug approval process and in program evaluation research; these suggest that some MHT adjustment is warranted in these applications, but not as much as implied by standard practice.", "date": "2026-05-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag026", "title_zh": "\u591a\u91cd\u5047\u8bbe\u68c0\u9a8c\u7684\u6a21\u578b", "abstract_zh": "\u591a\u91cd\u5047\u8bbe\u68c0\u9a8c\uff08MHT\uff09\u7684\u5b9e\u8df5\u5b58\u5728\u5f88\u5927\u5dee\u5f02\uff0c\u5c1a\u672a\u5f62\u6210\u5173\u4e8e\u4f55\u65f6\u5e94\u91c7\u7528\u4f55\u79cd\u65b9\u6cd5\u7684\u5171\u8bc6\u3002\u672c\u6587\u4e3a\u8fd9\u4e9b\u5b9e\u8df5\u63d0\u4f9b\u4e86\u7ecf\u6d4e\u57fa\u7840\uff0c\u65e8\u5728\u6355\u6349\u8bf8\u5982\u57fa\u4e8e\u4e34\u5e8a\u8bd5\u9a8c\u7684\u76d1\u7ba1\u5ba1\u6279\u7b49\u5178\u578b\u4f8b\u5b50\u3002\u5728\u6211\u4eec\u7684\u6846\u67b6\u4e2d\uff0c\u5f53\u7814\u7a76\u6210\u672c\u4e0e\u5047\u8bbe\u6570\u91cf\u65e0\u5173\u65f6\uff0c\u591a\u91cd\u5047\u8bbe\u68c0\u9a8c\u7684\u6821\u6b63\u624d\u662f\u9002\u5f53\u7684\u3002\u5f53\u6240\u6709\u6210\u672c\u56fa\u5b9a\u65f6\uff0c\u5e73\u5747\u663e\u8457\u6027\u6c34\u5e73\u7684\u63a7\u5236\uff08\u4f8b\u5982\u901a\u8fc7Bonferroni\u6821\u6b63\uff09\u5728\u6781\u9650\u60c5\u51b5\u4e0b\u51fa\u73b0\uff1b\u800c\u5728\u6210\u672c\u4e0e\u5047\u8bbe\u6570\u91cf\u6210\u6bd4\u4f8b\u7684\u76f8\u53cd\u6781\u9650\u60c5\u51b5\u4e0b\uff0c\u5219\u65e0\u9700\u6821\u6b63\u3002\u6211\u4eec\u901a\u8fc7\u5229\u7528\u836f\u7269\u5ba1\u6279\u8fc7\u7a0b\u548c\u9879\u76ee\u8bc4\u4f30\u7814\u7a76\u4e2d\u7684\u5b9e\u9645\u6210\u672c\u6570\u636e\uff0c\u8ba1\u7b97\u4e86\u5177\u4f53\u7684\u4e34\u754c\u503c\uff1b\u7ed3\u679c\u8868\u660e\uff0c\u5728\u8fd9\u4e9b\u5e94\u7528\u4e2d\uff0c\u786e\u5b9e\u9700\u8981\u4e00\u5b9a\u7a0b\u5ea6\u7684\u591a\u91cd\u5047\u8bbe\u68c0\u9a8c\u6821\u6b63\uff0c\u4f46\u7a0b\u5ea6\u8fdc\u4f4e\u4e8e\u6807\u51c6\u505a\u6cd5\u6240\u6697\u793a\u7684\u6c34\u5e73\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag045", "journal": "REStud", "title": "Markov-Perfect Equilibria in Differential Games\u2014With an Application to Climate Policy", "authors": ["Niko Jaakkola", "Florian Wagener"], "author_details": [{"name": "Niko Jaakkola", "affiliations": ["University of Bologna , ; CESifo, Germany"]}, {"name": "Florian Wagener", "affiliations": ["CeNDEF , Amsterdam School of Economics, University of Amsterdam , ; Tinbergen Institute, The Netherlands; CESifo, Germany"]}], "abstract": "Abstract We analyse discontinuous Markovian strategies for differential games. The best response correspondence uniquely maps almost all profiles of opponents\u2019 strategies back to the strategy space. We thus make Markov-perfect equilibria in a wide class of differential games well-behaved, resolving a long-standing open problem. We provide a readily applicable necessary and sufficient condition for best responses and Markov-perfect Nash equilibria. We demonstrate our methods in a canonical model of non-cooperative mitigation of climate change. Our approach provides novel, economically important results: we obtain the entire set of symmetric Markov-perfect equilibria and demonstrate that the best equilibria can yield a major welfare improvement over the equilibrium which previous literature has focused on. International climate negotiations can be seen as being about coordination on good equilibria, rather than about bargaining over the limited surplus available in a dynamic prisoner\u2019s dilemma.", "date": "2026-05-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag045", "title_zh": "\u5fae\u5206\u535a\u5f08\u4e2d\u7684\u9a6c\u5c14\u53ef\u592b\u5b8c\u7f8e\u5747\u8861\u2014\u2014\u4e00\u4e2a\u5173\u4e8e\u6c14\u5019\u653f\u7b56\u7684\u5e94\u7528", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5206\u6790\u4e86\u5fae\u5206\u535a\u5f08\u4e2d\u4e0d\u8fde\u7eed\u7684\u9a6c\u5c14\u53ef\u592b\u7b56\u7565\u3002\u6700\u4f73\u53cd\u5e94\u5bf9\u5e94\u5173\u7cfb\u51e0\u4e4e\u5c06\u6240\u6709\u5bf9\u624b\u7b56\u7565\u914d\u7f6e\u552f\u4e00\u6620\u5c04\u56de\u7b56\u7565\u7a7a\u95f4\u3002\u56e0\u6b64\uff0c\u6211\u4eec\u5728\u5e7f\u6cdb\u7684\u5fae\u5206\u535a\u5f08\u7c7b\u4e2d\u4f7f\u9a6c\u5c14\u53ef\u592b\u5b8c\u7f8e\u5747\u8861\u53d8\u5f97\u826f\u597d\u5b9a\u4e49\uff0c\u89e3\u51b3\u4e86\u957f\u671f\u5b58\u5728\u7684\u5f00\u653e\u95ee\u9898\u3002\u6211\u4eec\u4e3a\u6700\u4f73\u53cd\u5e94\u548c\u9a6c\u5c14\u53ef\u592b\u5b8c\u7f8e\u7eb3\u4ec0\u5747\u8861\u63d0\u4f9b\u4e86\u6613\u4e8e\u5e94\u7528\u7684\u5fc5\u8981\u4e14\u5145\u5206\u6761\u4ef6\u3002\u6211\u4eec\u5728\u4e00\u4e2a\u5178\u578b\u7684\u975e\u5408\u4f5c\u6c14\u5019\u7f13\u89e3\u6a21\u578b\u4e2d\u5c55\u793a\u4e86\u6211\u4eec\u7684\u65b9\u6cd5\u3002\u6211\u4eec\u7684\u65b9\u6cd5\u5f97\u5230\u4e86\u5177\u6709\u7ecf\u6d4e\u91cd\u8981\u6027\u7684\u65b0\u7ed3\u679c\uff1a\u6211\u4eec\u83b7\u5f97\u4e86\u6240\u6709\u5bf9\u79f0\u9a6c\u5c14\u53ef\u592b\u5b8c\u7f8e\u5747\u8861\u7684\u5b8c\u6574\u96c6\u5408\uff0c\u5e76\u8bc1\u660e\u4e86\u6700\u4f18\u5747\u8861\u76f8\u6bd4\u4ee5\u5f80\u6587\u732e\u6240\u5173\u6ce8\u7684\u5747\u8861\u80fd\u591f\u5e26\u6765\u663e\u8457\u7684\u798f\u5229\u6539\u5584\u3002\u56fd\u9645\u6c14\u5019\u8c08\u5224\u53ef\u4ee5\u88ab\u770b\u4f5c\u662f\u5173\u4e8e\u534f\u8c03\u8fbe\u6210\u826f\u597d\u5747\u8861\uff0c\u800c\u975e\u5173\u4e8e\u5728\u52a8\u6001\u56da\u5f92\u56f0\u5883\u4e2d\u4e89\u593a\u6709\u9650\u5269\u4f59\u7684\u8c08\u5224\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag034", "journal": "RFS", "title": "Proud to Not Own Stocks: How Identity Shapes Financial Decisions", "authors": ["Luca Henkel", "Christian Pugnaghi-Zimpelmann"], "author_details": [{"name": "Luca Henkel", "affiliations": ["Erasmus University Rotterdam, ERIM, CESifo, JILAEE, IZA@LISER, and Tinbergen Institute ,"]}, {"name": "Christian Pugnaghi-Zimpelmann", "affiliations": ["University of Hamburg and IZA@LISER ,"]}], "abstract": "Abstract This paper introduces a key factor influencing households\u2019 decision to invest in the stock market: how people view stockholders. Using surveys we conducted with nearly 8,500 individuals from 11 countries, we document that a large majority hold negative views of stockholders based on identity-relevant characteristics. Linking survey and administrative data, we find that negative perceptions strongly predict households\u2019 stock market participation. We show that negative perceptions causally influence household decision-making and provide evidence supporting identity concerns as the underlying mechanism. Our findings provide new perspectives on the malleability of financial decision-making and a novel explanation for low stock market participation.", "date": "2026-05-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag034", "title_zh": "\u81ea\u8c6a\u4e8e\u4e0d\u6301\u6709\u80a1\u7968\uff1a\u8eab\u4efd\u5982\u4f55\u5851\u9020\u91d1\u878d\u51b3\u7b56", "abstract_zh": "\u672c\u6587\u5f15\u5165\u4e86\u4e00\u4e2a\u5f71\u54cd\u5bb6\u5ead\u662f\u5426\u6295\u8d44\u80a1\u7968\u5e02\u573a\u7684\u91cd\u8981\u56e0\u7d20\uff1a\u4eba\u4eec\u5982\u4f55\u770b\u5f85\u80a1\u4e1c\u3002\u57fa\u4e8e\u5bf9\u6765\u81ea11\u4e2a\u56fd\u5bb6\u8fd18500\u540d\u4e2a\u4f53\u7684\u8c03\u67e5\uff0c\u6211\u4eec\u53d1\u73b0\u5927\u591a\u6570\u4eba\u7684\u80a1\u4e1c\u89c2\u57fa\u4e8e\u8eab\u4efd\u76f8\u5173\u7279\u5f81\u800c\u6301\u8d1f\u9762\u6001\u5ea6\u3002\u901a\u8fc7\u5c06\u8c03\u67e5\u6570\u636e\u4e0e\u884c\u653f\u6570\u636e\u76f8\u7ed3\u5408\uff0c\u6211\u4eec\u53d1\u73b0\u5bf9\u80a1\u4e1c\u7684\u8d1f\u9762\u770b\u6cd5\u5f3a\u70c8\u9884\u6d4b\u4e86\u5bb6\u5ead\u53c2\u4e0e\u80a1\u7968\u5e02\u573a\u7684\u884c\u4e3a\u3002\u6211\u4eec\u8bc1\u660e\u4e86\u8fd9\u4e9b\u8d1f\u9762\u770b\u6cd5\u5bf9\u5bb6\u5ead\u51b3\u7b56\u5177\u6709\u56e0\u679c\u5f71\u54cd\uff0c\u5e76\u63d0\u4f9b\u4e86\u652f\u6301\u8eab\u4efd\u5173\u5207\u4f5c\u4e3a\u5176\u5185\u5728\u673a\u5236\u7684\u8bc1\u636e\u3002\u6211\u4eec\u7684\u7814\u7a76\u4e3a\u91d1\u878d\u51b3\u7b56\u7684\u53ef\u5851\u6027\u63d0\u4f9b\u4e86\u65b0\u7684\u89c6\u89d2\uff0c\u5e76\u4e3a\u80a1\u7968\u5e02\u573a\u53c2\u4e0e\u5ea6\u4f4e\u63d0\u4f9b\u4e86\u65b0\u9896\u7684\u89e3\u91ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag049", "journal": "RFS", "title": "Firm-Level Labor Shortage Exposure", "authors": ["Jarrad Harford", "Qiyang He", "Buhui Qiu"], "author_details": [{"name": "Jarrad Harford", "affiliations": ["University of Washington ,"]}, {"name": "Qiyang He", "affiliations": ["Deakin University ,"]}, {"name": "Buhui Qiu", "affiliations": ["University of Sydney ,"]}], "abstract": "Abstract We extract information from earnings call transcripts to develop a comprehensive and reliable measure of labor shortage exposure. After validating the measure at the state, industry, and firm levels, we show that firms with labor shortage exposures experience lower earnings call CARs, future stock returns and operating performance. Firms respond to labor shortages by substituting labor with capital and R&D investments, and by producing more production-process patents. Such responses help mitigate the negative effects on future performance. Our measure has broad applicability, and our findings provide new insight into labor-capital substitution in imperfectly competitive labor markets.", "date": "2026-05-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag049", "title_zh": "\u4f01\u4e1a\u5c42\u9762\u7684\u52b3\u52a8\u529b\u77ed\u7f3a\u66b4\u9732", "abstract_zh": "\u6211\u4eec\u4ece\u8d22\u62a5\u4f1a\u8bae\u8bb0\u5f55\u4e2d\u63d0\u53d6\u4fe1\u606f\uff0c\u6784\u5efa\u4e86\u4e00\u4e2a\u5168\u9762\u4e14\u53ef\u9760\u7684\u52b3\u52a8\u529b\u77ed\u7f3a\u66b4\u9732\u8861\u91cf\u6307\u6807\u3002\u5728\u5dde\u3001\u884c\u4e1a\u548c\u4f01\u4e1a\u5c42\u9762\u9a8c\u8bc1\u8be5\u6307\u6807\u540e\uff0c\u6211\u4eec\u53d1\u73b0\u5177\u6709\u52b3\u52a8\u529b\u77ed\u7f3a\u66b4\u9732\u7684\u4f01\u4e1a\u5728\u8d22\u62a5\u4f1a\u8bae\u4e2d\u7684\u7d2f\u8ba1\u5f02\u5e38\u6536\u76ca\u7387\u3001\u672a\u6765\u80a1\u4ef7\u8868\u73b0\u548c\u8fd0\u8425\u7ee9\u6548\u5747\u8f83\u4f4e\u3002\u4f01\u4e1a\u901a\u8fc7\u5c06\u52b3\u52a8\u529b\u66ff\u6362\u4e3a\u8d44\u672c\u548c\u7814\u53d1\u6295\u8d44\uff0c\u5e76\u589e\u52a0\u751f\u4ea7\u6d41\u7a0b\u4e13\u5229\u7684\u4ea7\u51fa\u6765\u5e94\u5bf9\u52b3\u52a8\u529b\u77ed\u7f3a\uff0c\u8fd9\u4e9b\u63aa\u65bd\u6709\u52a9\u4e8e\u7f13\u89e3\u5bf9\u672a\u6765\u7ee9\u6548\u7684\u8d1f\u9762\u5f71\u54cd\u3002\u6211\u4eec\u7684\u6307\u6807\u5177\u6709\u5e7f\u6cdb\u7684\u9002\u7528\u6027\uff0c\u7814\u7a76\u7ed3\u679c\u4e3a\u4e0d\u5b8c\u5168\u7ade\u4e89\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u7684\u52b3\u52a8\u529b\u4e0e\u8d44\u672c\u66ff\u4ee3\u63d0\u4f9b\u4e86\u65b0\u7684\u6d1e\u89c1\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1017/s0022109026102968", "journal": "JFQA", "title": "Optimal Retirement Saving and Dissaving", "authors": ["Claus Munk"], "author_details": [{"name": "Claus Munk", "affiliations": ["Copenhagen Business School"]}], "abstract": "Abstract Applying a rich model of individuals\u2019 life-cycle utility maximization, I comprehensively evaluate retirement saving plans. Across a range of individual characteristics, access to basic plans with constant expected payouts and no or full annuitization leads to individual utility gains of up to 5.07% of initial wealth and lifetime income ($43,800 in present value terms), and almost all individuals prefer full annuitization and a target-date fund investment strategy. With flexible plans allowing for partial annuitization and non-constant expected payouts, utility gains go up to 5.81%, and most individuals prefer a high degree of annuitization and expected payouts being increasing through retirement.", "date": "2026-05-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102968", "title_zh": "\u6700\u4f18\u9000\u4f11\u50a8\u84c4\u4e0e\u6d88\u8d39", "abstract_zh": "\u6458\u8981 \u57fa\u4e8e\u4e2a\u4f53\u751f\u547d\u5468\u671f\u6548\u7528\u6700\u5927\u5316\u6a21\u578b\uff0c\u6211\u5168\u9762\u8bc4\u4f30\u4e86\u9000\u4f11\u50a8\u84c4\u8ba1\u5212\u3002\u5728\u591a\u79cd\u4e2a\u4f53\u7279\u5f81\u4e0b\uff0c\u91c7\u7528\u5177\u6709\u6052\u5b9a\u9884\u671f\u652f\u4ed8\u4e14\u65e0\u6216\u5b8c\u5168\u5e74\u91d1\u5316\u7684\u57fa\u672c\u8ba1\u5212\uff0c\u53ef\u4f7f\u4e2a\u4f53\u6548\u7528\u63d0\u5347\u9ad8\u8fbe\u521d\u59cb\u8d22\u5bcc\u548c\u7ec8\u8eab\u6536\u5165\u76845.07%\uff08\u76f8\u5f53\u4e8e43,800\u7f8e\u5143\u7684\u73b0\u503c\uff09\uff0c\u51e0\u4e4e\u6240\u6709\u4e2a\u4f53\u66f4\u503e\u5411\u4e8e\u5b8c\u5168\u5e74\u91d1\u5316\u548c\u76ee\u6807\u65e5\u671f\u57fa\u91d1\u6295\u8d44\u7b56\u7565\u3002\u5728\u5141\u8bb8\u90e8\u5206\u5e74\u91d1\u5316\u548c\u975e\u6052\u5b9a\u9884\u671f\u652f\u4ed8\u7684\u7075\u6d3b\u8ba1\u5212\u4e0b\uff0c\u6548\u7528\u63d0\u5347\u53ef\u8fbe5.81%\uff0c\u5927\u591a\u6570\u4e2a\u4f53\u66f4\u504f\u597d\u9ad8\u7a0b\u5ea6\u7684\u5e74\u91d1\u5316\u4ee5\u53ca\u9884\u671f\u652f\u4ed8\u5728\u9000\u4f11\u671f\u95f4\u6301\u7eed\u4e0a\u5347\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag024", "journal": "RFS", "title": "Collective Moral Hazard, Risk Sharing, and Banking Unions", "authors": ["Anatoli Segura", "Sergio Vicente"], "author_details": [{"name": "Anatoli Segura", "affiliations": ["Banca d\u2019Italia, Italy, and CEPR"]}, {"name": "Sergio Vicente", "affiliations": ["University of Luxembourg ,"]}], "abstract": "Abstract We analyze optimal cross-country risk sharing and bank capital requirements amid collective moral hazard by governments and banks. Transfers provide insurance but weaken fiscal discipline. Since lenient fiscal policies amplify banks\u2019 risk-shifting, optimal support must be contingent on banking system health. For fiscally weak countries, support is larger in sovereign crises with solvent banks. For fiscally strong countries, support is larger in joint sovereign and bank crises, requiring deposit insurance mutualization. Optimal contracts feature lower capital requirements than without cross-country transfers, raising the cost of joint sovereign and bank crises to strengthen fiscal discipline and enable greater risk sharing.", "date": "2026-05-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag024", "title_zh": "\u96c6\u4f53\u9053\u5fb7\u98ce\u9669\u3001\u98ce\u9669\u5206\u62c5\u4e0e\u94f6\u884c\u8054\u76df", "abstract_zh": "\u6211\u4eec\u5206\u6790\u4e86\u5728\u653f\u5e9c\u548c\u94f6\u884c\u5b58\u5728\u96c6\u4f53\u9053\u5fb7\u98ce\u9669\u7684\u60c5\u51b5\u4e0b\uff0c\u8de8\u56fd\u98ce\u9669\u5206\u62c5\u4ee5\u53ca\u94f6\u884c\u8d44\u672c\u8981\u6c42\u7684\u6700\u4f18\u5b89\u6392\u3002\u8f6c\u79fb\u652f\u4ed8\u63d0\u4f9b\u4e86\u4fdd\u9669\uff0c\u4f46\u4f1a\u524a\u5f31\u8d22\u653f\u7eaa\u5f8b\u3002\u7531\u4e8e\u5bbd\u677e\u7684\u8d22\u653f\u653f\u7b56\u4f1a\u52a0\u5267\u94f6\u884c\u7684\u98ce\u9669\u8f6c\u79fb\uff0c\u56e0\u6b64\u6700\u4f18\u652f\u6301\u5fc5\u987b\u53d6\u51b3\u4e8e\u94f6\u884c\u4f53\u7cfb\u7684\u5065\u5eb7\u72b6\u51b5\u3002\u5bf9\u4e8e\u8d22\u653f\u8584\u5f31\u7684\u56fd\u5bb6\uff0c\u5728\u4e3b\u6743\u5371\u673a\u4f46\u94f6\u884c\u4ecd\u5065\u5eb7\u7684\u72b6\u51b5\u4e0b\uff0c\u652f\u6301\u7a0b\u5ea6\u66f4\u5927\uff1b\u5bf9\u4e8e\u8d22\u653f\u5f3a\u5927\u7684\u56fd\u5bb6\uff0c\u5728\u4e3b\u6743\u548c\u94f6\u884c\u540c\u65f6\u5371\u673a\u7684\u60c5\u51b5\u4e0b\uff0c\u652f\u6301\u7a0b\u5ea6\u66f4\u5927\uff0c\u9700\u8981\u5b9e\u73b0\u5b58\u6b3e\u4fdd\u9669\u7684\u5171\u4eab\u3002\u6700\u4f18\u5408\u540c\u4e2d\uff0c\u94f6\u884c\u8d44\u672c\u8981\u6c42\u4f4e\u4e8e\u6ca1\u6709\u8de8\u56fd\u8f6c\u79fb\u652f\u4ed8\u7684\u60c5\u51b5\uff0c\u8fd9\u63d0\u9ad8\u4e86\u8054\u5408\u4e3b\u6743\u4e0e\u94f6\u884c\u5371\u673a\u7684\u6210\u672c\uff0c\u4ece\u800c\u5f3a\u5316\u4e86\u8d22\u653f\u7eaa\u5f8b\uff0c\u5e76\u4fc3\u8fdb\u4e86\u66f4\u5927\u7684\u98ce\u9669\u5206\u62c5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag025", "journal": "QJE", "title": "International Reserve Management Under Rollover Crises", "authors": ["Mauricio Barbosa-Alves", "Javier Bianchi", "C\u00e9sar Sosa-Padilla"], "author_details": [{"name": "Mauricio Barbosa-Alves", "affiliations": ["University of Kentucky ,"]}, {"name": "Javier Bianchi", "affiliations": ["Federal Reserve Bank of Minneapolis ,"]}, {"name": "C\u00e9sar Sosa-Padilla", "affiliations": ["University of Notre Dame and National Bureau of Economic Research ,"]}], "abstract": "Abstract This article investigates how a government should manage international reserves when it faces the risk of a rollover crisis. We ask: Should the government accumulate reserves or reduce debt to make itself less vulnerable? We show that the optimal policy entails initially reducing debt, followed by a subsequent increase in both debt and reserves as the government approaches a safe zone. Furthermore, we find that issuing additional debt to accumulate reserves can lead to a reduction in sovereign spreads. Evidence from a panel of emerging economies is consistent with these predictions: increases in reserves financed by public external borrowing are associated with lower spreads, and reserve holdings are not systematically drawn down during crisis episodes.", "date": "2026-05-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag025", "title_zh": "\u56fd\u9645\u50a8\u5907\u7ba1\u7406\u4e2d\u7684\u6eda\u52a8\u5371\u673a", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5f53\u653f\u5e9c\u9762\u4e34\u6eda\u52a8\u5371\u673a\u98ce\u9669\u65f6\uff0c\u5e94\u5982\u4f55\u7ba1\u7406\u56fd\u9645\u50a8\u5907\u3002\u6211\u4eec\u63d0\u51fa\u95ee\u9898\uff1a\u653f\u5e9c\u662f\u5e94\u8be5\u79ef\u7d2f\u50a8\u5907\u8fd8\u662f\u51cf\u5c11\u503a\u52a1\u4ee5\u964d\u4f4e\u8106\u5f31\u6027\uff1f\u6211\u4eec\u53d1\u73b0\uff0c\u6700\u4f18\u653f\u7b56\u662f\u5148\u51cf\u5c11\u503a\u52a1\uff0c\u968f\u540e\u5728\u653f\u5e9c\u63a5\u8fd1\u5b89\u5168\u533a\u57df\u65f6\uff0c\u540c\u65f6\u589e\u52a0\u503a\u52a1\u548c\u50a8\u5907\u3002\u6b64\u5916\uff0c\u6211\u4eec\u53d1\u73b0\u901a\u8fc7\u53d1\u884c\u989d\u5916\u503a\u52a1\u6765\u79ef\u7d2f\u50a8\u5907\uff0c\u53ef\u4ee5\u5bfc\u81f4\u4e3b\u6743\u5229\u5dee\u6536\u7a84\u3002\u5bf9\u65b0\u5174\u7ecf\u6d4e\u4f53\u9762\u677f\u6570\u636e\u7684\u5b9e\u8bc1\u7ed3\u679c\u652f\u6301\u4e86\u8fd9\u4e9b\u9884\u6d4b\uff1a\u7531\u516c\u5171\u5916\u90e8\u501f\u6b3e\u878d\u8d44\u7684\u50a8\u5907\u589e\u52a0\u4e0e\u5229\u5dee\u4e0b\u964d\u76f8\u5173\uff0c\u4e14\u5728\u5371\u673a\u671f\u95f4\u50a8\u5907\u6301\u6709\u91cf\u5e76\u672a\u7cfb\u7edf\u6027\u88ab\u524a\u51cf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag027", "journal": "QJE", "title": "The Power of Proximity to Coworkers", "authors": ["Natalia Emanuel", "Emma Harrington", "Amanda Pallais"], "author_details": [{"name": "Natalia Emanuel", "affiliations": ["Federal Reserve Bank of New York ,"]}, {"name": "Emma Harrington", "affiliations": ["University of Virginia ,"]}, {"name": "Amanda Pallais", "affiliations": ["Harvard University and the National Bureau of Economic Research ,"]}], "abstract": "Abstract How does proximity to coworkers affect training and productivity? We study software engineers at a Fortune 500 firm from 2019 to 2024, leveraging two shocks to proximity: the office closures in 2020 and the subsequent return-to-office mandates in 2022 and 2023. In both cases, co-located teams experienced bigger changes in proximity than distributed ones, facilitating difference-in-differences designs. We find that sitting near teammates increases coding feedback by 18.3% and improves code quality. Gains are concentrated among less-tenured and younger employees, who are building human capital. However, there is a trade-off: experienced engineers write less code when sitting near teammates. In national U.S. data, we find evidence that the rise of remote work has had scarring effects on young college graduates. In remotable jobs, young graduates\u2019 unemployment rate increased relative to older graduates\u2019 post-pandemic (2022\u20132024) compared to pre-pandemic (2017\u20132019), a pattern we do not observe in non-remotable jobs.", "date": "2026-05-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag027", "title_zh": "\u4e0e\u540c\u4e8b\u7684\u8fd1\u8ddd\u79bb\u63a5\u89e6\u5e26\u6765\u7684\u529b\u91cf", "abstract_zh": "\u8fd1\u8ddd\u79bb\u63a5\u89e6\u540c\u4e8b\u5982\u4f55\u5f71\u54cd\u57f9\u8bad\u548c\u751f\u4ea7\u7387\uff1f\u6211\u4eec\u7814\u7a76\u4e862019\u5e74\u81f32024\u5e74\u95f4\u4e00\u5bb6\u300a\u8d22\u5bcc\u300b500\u5f3a\u516c\u53f8\u8f6f\u4ef6\u5de5\u7a0b\u5e08\u7684\u60c5\u51b5\uff0c\u5229\u7528\u4e86\u4e24\u4e2a\u4e0e\u8ddd\u79bb\u76f8\u5173\u7684\u51b2\u51fb\u4e8b\u4ef6\uff1a2020\u5e74\u7684\u529e\u516c\u5ba4\u5173\u95ed\u4ee5\u53ca2022\u5e74\u548c2023\u5e74\u6062\u590d\u529e\u516c\u5ba4\u529e\u516c\u7684\u6307\u4ee4\u3002\u5728\u8fd9\u4e24\u79cd\u60c5\u51b5\u4e0b\uff0c\u540c\u5904\u529e\u516c\u5ba4\u7684\u56e2\u961f\u6bd4\u5206\u5e03\u5f0f\u56e2\u961f\u7ecf\u5386\u4e86\u66f4\u5927\u7684\u8ddd\u79bb\u53d8\u5316\uff0c\u4ece\u800c\u4fbf\u4e8e\u91c7\u7528\u5dee\u5206\u6cd5\u8bbe\u8ba1\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u4e0e\u540c\u4e8b\u5750\u5728\u4e00\u8d77\u4f1a\u5c06\u7f16\u7801\u53cd\u9988\u63d0\u9ad818.3%\uff0c\u5e76\u63d0\u5347\u4ee3\u7801\u8d28\u91cf\u3002\u8fd9\u4e9b\u6536\u76ca\u4e3b\u8981\u96c6\u4e2d\u5728\u4efb\u804c\u65f6\u95f4\u8f83\u77ed\u548c\u5e74\u9f84\u8f83\u5c0f\u7684\u5458\u5de5\u8eab\u4e0a\uff0c\u4ed6\u4eec\u6b63\u5728\u79ef\u7d2f\u4eba\u529b\u8d44\u672c\u3002\u7136\u800c\uff0c\u5b58\u5728\u6743\u8861\uff1a\u7ecf\u9a8c\u4e30\u5bcc\u7684\u5de5\u7a0b\u5e08\u5728\u4e0e\u540c\u4e8b\u5750\u5728\u4e00\u8d77\u65f6\u5199\u4ee3\u7801\u7684\u91cf\u53cd\u800c\u51cf\u5c11\u3002\u5728\u5168\u7f8e\u6570\u636e\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\u8fdc\u7a0b\u5de5\u4f5c\u5174\u8d77\u5bf9\u5e74\u8f7b\u5927\u5b66\u6bd5\u4e1a\u751f\u4ea7\u751f\u4e86\u957f\u671f\u8d1f\u9762\u5f71\u54cd\u3002\u5728\u53ef\u8fdc\u7a0b\u5de5\u4f5c\u7684\u5c97\u4f4d\u4e0a\uff0c\u5e74\u8f7b\u6bd5\u4e1a\u751f\u5728\u75ab\u60c5\u540e\uff082022\u20132024\u5e74\uff09\u7684\u5931\u4e1a\u7387\u76f8\u6bd4\u75ab\u60c5\u524d\uff082017\u20132019\u5e74\uff09\u7684\u540c\u9f84\u4eba\u6709\u6240\u4e0a\u5347\uff0c\u800c\u5728\u4e0d\u53ef\u8fdc\u7a0b\u5de5\u4f5c\u7684\u5c97\u4f4d\u4e0a\uff0c\u6211\u4eec\u5e76\u672a\u89c2\u5bdf\u5230\u8fd9\u4e00\u73b0\u8c61\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag028", "journal": "QJE", "title": "Public Services Under Private Management", "authors": ["Ma\u00edra Coube", "Luiz Felipe Fontes", "Rudi Rocha"], "author_details": [{"name": "Ma\u00edra Coube", "affiliations": ["INSPER\u2013Institute of Education and Research ,"]}, {"name": "Luiz Felipe Fontes", "affiliations": ["INSPER\u2013Institute of Education and Research ,"]}, {"name": "Rudi Rocha", "affiliations": ["FGV\u2013S\u00e3o Paulo School of Business Administration, Brazil, IEPS\u2013Institute for Health Policy Studies ,"]}], "abstract": "Abstract Theory predicts that outsourcing public services to the private sector can reduce costs and improve efficiency but can also induce cost-cutting and compromise quality. We assess the Brazilian Organiza\u00e7\u00f5es Sociais de Saude model (OSS), which outsources management of public hospital services to the private sector while the state remains the residual claimant. We show that this enhances hospital production and operational efficiency without adverse effects on hospital quality and equity. Increased inpatient production addresses previously unmet demand, expanding local access to hospital care and reducing population mortality. Performance gains arise from improved operational efficiency achieved through increased hospital management capacity. This facilitates staffing adjustments, favoring higher-skilled personnel, dismissing lower-productivity staff, and adopting flexible, performance-tied employment contracts. Effects are larger among private organizations with more management experience, underscoring returns to managerial capacity. Our findings show that incentive-ownership structures can address the quantity-quality trade-off in public service delivery, even when contracts are incomplete and quality is hard to measure.", "date": "2026-05-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag028", "title_zh": "\u516c\u5171\u670d\u52a1\u7684\u79c1\u8425\u7ba1\u7406", "abstract_zh": "\u7406\u8bba\u9884\u6d4b\uff0c\u5c06\u516c\u5171\u670d\u52a1\u5916\u5305\u7ed9\u79c1\u8425\u90e8\u95e8\u53ef\u4ee5\u964d\u4f4e\u6210\u672c\u5e76\u63d0\u9ad8\u6548\u7387\uff0c\u4f46\u4e5f\u53ef\u80fd\u5f15\u53d1\u6210\u672c\u524a\u51cf\u5e76\u635f\u5bb3\u670d\u52a1\u8d28\u91cf\u3002\u6211\u4eec\u8bc4\u4f30\u4e86\u5df4\u897f\u7684\u536b\u751f\u793e\u4f1a\u7ec4\u7ec7\uff08OSS\uff09\u6a21\u5f0f\uff0c\u8be5\u6a21\u5f0f\u5c06\u516c\u7acb\u533b\u9662\u670d\u52a1\u7684\u7ba1\u7406\u5916\u5305\u7ed9\u79c1\u8425\u90e8\u95e8\uff0c\u800c\u56fd\u5bb6\u4ecd\u4fdd\u7559\u5269\u4f59\u7d22\u53d6\u6743\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u79cd\u6a21\u5f0f\u63d0\u5347\u4e86\u533b\u9662\u7684\u751f\u4ea7\u6548\u7387\u548c\u8fd0\u8425\u6548\u7387\uff0c\u4e14\u4e0d\u4f1a\u5bf9\u533b\u9662\u7684\u8d28\u91cf\u548c\u516c\u5e73\u6027\u4ea7\u751f\u4e0d\u5229\u5f71\u54cd\u3002\u4f4f\u9662\u60a3\u8005\u6570\u91cf\u7684\u589e\u52a0\u89e3\u51b3\u4e86\u4ee5\u5f80\u672a\u6ee1\u8db3\u7684\u9700\u6c42\uff0c\u6269\u5927\u4e86\u5f53\u5730\u5bf9\u533b\u9662\u533b\u7597\u670d\u52a1\u7684\u53ef\u53ca\u6027\uff0c\u5e76\u964d\u4f4e\u4e86\u4eba\u53e3\u6b7b\u4ea1\u7387\u3002\u7ee9\u6548\u63d0\u5347\u6e90\u4e8e\u901a\u8fc7\u589e\u5f3a\u533b\u9662\u7ba1\u7406\u80fd\u529b\u5b9e\u73b0\u7684\u8fd0\u8425\u6548\u7387\u6539\u5584\u3002\u8fd9\u4fc3\u8fdb\u4e86\u4eba\u5458\u914d\u7f6e\u7684\u8c03\u6574\uff0c\u6709\u5229\u4e8e\u5f15\u8fdb\u66f4\u9ad8\u6280\u80fd\u7684\u5458\u5de5\uff0c\u8f9e\u9000\u4f4e\u751f\u4ea7\u7387\u7684\u5458\u5de5\uff0c\u5e76\u91c7\u7528\u4e0e\u7ee9\u6548\u6302\u94a9\u7684\u7075\u6d3b\u96c7\u4f63\u5408\u540c\u3002\u5728\u7ba1\u7406\u7ecf\u9a8c\u66f4\u4e30\u5bcc\u7684\u79c1\u8425\u673a\u6784\u4e2d\uff0c\u8fd9\u79cd\u6548\u679c\u66f4\u4e3a\u663e\u8457\uff0c\u51f8\u663e\u4e86\u7ba1\u7406\u80fd\u529b\u7684\u56de\u62a5\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u5373\u4f7f\u5408\u540c\u4e0d\u5b8c\u5168\u4e14\u670d\u52a1\u8d28\u91cf\u96be\u4ee5\u8861\u91cf\uff0c\u6fc0\u52b1\u6027\u6240\u6709\u6743\u7ed3\u6784\u4e5f\u80fd\u89e3\u51b3\u516c\u5171\u670d\u52a1\u4f9b\u7ed9\u4e2d\u7684\u6570\u91cf\u4e0e\u8d28\u91cf\u4e4b\u95f4\u7684\u6743\u8861\u95ee\u9898\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag038", "journal": "REStud", "title": "Open Rule Legislative Bargaining", "authors": ["Volker Britz", "Hans Gersbach"], "author_details": [{"name": "Volker Britz", "affiliations": ["CER-ETH, ETH Zurich ,"]}, {"name": "Hans Gersbach", "affiliations": ["KOF Swiss Economic Institute and CEPR, ETH Zurich ,"]}], "abstract": "Abstract The seminal paper by Baron and Ferejohn (1989, \u201cBargaining in Legislatures\u201d, American Political Science Review, 83, 1181\u20131206) leaves significant gaps in our understanding of open rule bargaining. We aim to fill these gaps by providing a fresh analysis of open rule bargaining. Our approach relies on an appealing class of stationary equilibria. In this class, we show that delays tend to be longer and allocations tend to be less egalitarian than originally predicted by Baron and Ferejohn. Our results shed new light on the efficiency and fairness implications of using an open vs. closed rule in legislatures and of bargaining processes in general.", "date": "2026-05-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag038", "title_zh": "\u5f00\u653e\u89c4\u5219\u7acb\u6cd5\u535a\u5f08", "abstract_zh": "\u6458\u8981 \u5df4\u9f99\u548c\u8d39\u5c14\u7ea6\u7ff0\uff081989\u5e74\uff0c\u300a\u7acb\u6cd5\u673a\u6784\u4e2d\u7684\u535a\u5f08\u300b\uff0c\u300a\u7f8e\u56fd\u653f\u6cbb\u79d1\u5b66\u8bc4\u8bba\u300b\uff0c83\u5377\uff0c1181\u20131206\u9875\uff09\u5173\u4e8e\u5f00\u653e\u89c4\u5219\u535a\u5f08\u7684\u7814\u7a76\u7559\u4e0b\u4e86\u8bf8\u591a\u7406\u89e3\u4e0a\u7684\u7a7a\u767d\u3002\u672c\u6587\u65e8\u5728\u586b\u8865\u8fd9\u4e9b\u7a7a\u767d\uff0c\u901a\u8fc7\u63d0\u4f9b\u5bf9\u5f00\u653e\u89c4\u5219\u535a\u5f08\u7684\u5168\u65b0\u5206\u6790\u6765\u89e3\u51b3\u8fd9\u4e00\u95ee\u9898\u3002\u6211\u4eec\u7684\u65b9\u6cd5\u4f9d\u8d56\u4e8e\u4e00\u7c7b\u5177\u6709\u5438\u5f15\u529b\u7684\u5e73\u7a33\u5747\u8861\u3002\u5728\u8fd9\u4e00\u7c7b\u5747\u8861\u4e2d\uff0c\u6211\u4eec\u8bc1\u660e\u5ef6\u8fdf\u65f6\u95f4\u5f80\u5f80\u6bd4\u5df4\u9f99\u548c\u8d39\u5c14\u7ea6\u7ff0\u6700\u521d\u9884\u6d4b\u7684\u66f4\u957f\uff0c\u800c\u5206\u914d\u7ed3\u679c\u5f80\u5f80\u6bd4\u539f\u9884\u6d4b\u66f4\u4e0d\u5e73\u7b49\u3002\u6211\u4eec\u7684\u7814\u7a76\u4e3a\u5f00\u653e\u89c4\u5219\u4e0e\u5c01\u95ed\u89c4\u5219\u5728\u7acb\u6cd5\u673a\u6784\u4e2d\u7684\u6548\u7387\u548c\u516c\u5e73\u6027\u5f71\u54cd\uff0c\u4ee5\u53ca\u4e00\u822c\u535a\u5f08\u8fc7\u7a0b\u4e2d\u7684\u76f8\u5173\u95ee\u9898\u63d0\u4f9b\u4e86\u65b0\u7684\u6d1e\u89c1\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag050", "journal": "RFS", "title": "Generative AI and Asset Management", "authors": ["Jinfei Sheng", "Zheng Sun", "Baozhong Yang", "Alan L Zhang"], "author_details": [{"name": "Jinfei Sheng", "affiliations": ["Merage School of Business, University of California , Irvine,"]}, {"name": "Zheng Sun", "affiliations": ["Merage School of Business, University of California , Irvine,"]}, {"name": "Baozhong Yang", "affiliations": ["J. Mack Robinson College of Business, Georgia State University ,"]}, {"name": "Alan L Zhang", "affiliations": ["Ivy College of Business, Iowa State University ,"]}], "abstract": "Abstract Using a novel measure of investment companies\u2019 reliance on generative artificial intelligence (GenAI), we document a sharp increase in GenAI usage by hedge funds after ChatGPT\u2019s 2022 launch. A difference-in-differences test shows that hedge funds adopting GenAI earn 2-4% higher annualized abnormal returns than nonadopters, while non-hedge funds do not benefit. The outperformance originates from funds\u2019 AI talent and ChatGPT\u2019s strength in analyzing firm-specific information. We conduct a new survey of fund managers\u2019 GenAI usage to provide direct validation of our measure and offer additional new insights on how managers adopt GenAI tools in their practice.", "date": "2026-05-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag050", "title_zh": "\u751f\u6210\u5f0f\u4eba\u5de5\u667a\u80fd\u4e0e\u8d44\u4ea7\u7ba1\u7406", "abstract_zh": "\u4f7f\u7528\u4e00\u79cd\u65b0\u7684\u8861\u91cf\u6295\u8d44\u516c\u53f8\u5bf9\u751f\u6210\u5f0f\u4eba\u5de5\u667a\u80fd\uff08GenAI\uff09\u4f9d\u8d56\u7a0b\u5ea6\u7684\u6307\u6807\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5728ChatGPT\u4e8e2022\u5e74\u53d1\u5e03\u540e\uff0c\u5bf9\u51b2\u57fa\u91d1\u5bf9GenAI\u7684\u4f7f\u7528\u663e\u8457\u589e\u52a0\u3002\u5dee\u5f02-\u5dee\u5f02\u68c0\u9a8c\u663e\u793a\uff0c\u91c7\u7528GenAI\u7684\u5bf9\u51b2\u57fa\u91d1\u76f8\u6bd4\u672a\u91c7\u7528\u8005\u5e74\u5316\u5f02\u5e38\u6536\u76ca\u7387\u9ad8\u51fa2-4%\uff0c\u800c\u975e\u5bf9\u51b2\u57fa\u91d1\u5219\u672a\u83b7\u5f97\u6536\u76ca\u63d0\u5347\u3002\u8fd9\u79cd\u8d85\u989d\u8868\u73b0\u6e90\u4e8e\u57fa\u91d1\u56e2\u961f\u7684\u4eba\u5de5\u667a\u80fd\u4eba\u624d\u4ee5\u53caChatGPT\u5728\u5206\u6790\u4f01\u4e1a\u7279\u5b9a\u4fe1\u606f\u65b9\u9762\u7684\u4f18\u52bf\u3002\u6211\u4eec\u5f00\u5c55\u4e86\u4e00\u9879\u5173\u4e8e\u57fa\u91d1\u7ecf\u7406GenAI\u4f7f\u7528\u60c5\u51b5\u7684\u65b0\u8c03\u67e5\uff0c\u4ee5\u76f4\u63a5\u9a8c\u8bc1\u6211\u4eec\u7684\u8861\u91cf\u65b9\u6cd5\uff0c\u5e76\u8fdb\u4e00\u6b65\u63ed\u793a\u57fa\u91d1\u7ecf\u7406\u5728\u5b9e\u9645\u64cd\u4f5c\u4e2d\u91c7\u7528GenAI\u5de5\u5177\u7684\u7ec6\u8282\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005", "AI"]}, {"doi": "10.1093/qje/qjag026", "journal": "QJE", "title": "Praying for Rain", "authors": ["Jos\u00e9-Antonio Esp\u00edn-S\u00e1nchez", "Salvador Gil-Guirado", "Nicholas Ryan"], "author_details": [{"name": "Jos\u00e9-Antonio Esp\u00edn-S\u00e1nchez", "affiliations": ["Yale University ,"]}, {"name": "Salvador Gil-Guirado", "affiliations": ["University of Murcia ,"]}, {"name": "Nicholas Ryan", "affiliations": ["Yale University ,"]}], "abstract": "Abstract We study rainmaking as an instrumental religious belief. We present a model in which a religious leader tries to persuade people to believe. Praying for rain can persuade only where the hazard of rainfall during a dry spell is increasing over time, so that prayer is most likely to succeed when people most want rain. We present evidence from prayers for rain in Murcia, Spain, where the hazard rate is increasing, that the church\u2019s prayers for rain predict rainfall over two centuries. To generalize this finding, we gather an original data set of whether ethnic groups around the world traditionally prayed for rain. We find that ethnic groups facing an increasing rainfall hazard are 47% more likely to pray for rain, consistent with our model\u2019s prediction that societies are more likely to pray for rain where prayer is persuasive.", "date": "2026-05-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag026", "title_zh": "\u7948\u6c42\u964d\u96e8", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u964d\u96e8\u7948\u6c42\u4f5c\u4e3a\u4e00\u79cd\u5de5\u5177\u6027\u7684\u5b97\u6559\u4fe1\u5ff5\u3002\u6211\u4eec\u63d0\u51fa\u4e00\u4e2a\u6a21\u578b\uff0c\u5176\u4e2d\u5b97\u6559\u9886\u8896\u8bd5\u56fe\u8bf4\u670d\u4eba\u4eec\u76f8\u4fe1\u3002\u53ea\u6709\u5f53\u5e72\u65f1\u671f\u95f4\u964d\u96e8\u7684\u5371\u9669\u7387\u968f\u65f6\u95f4\u589e\u52a0\u65f6\uff0c\u7948\u7977\u624d\u80fd\u4ea7\u751f\u6548\u679c\uff0c\u56e0\u6b64\u7948\u7977\u6700\u6709\u53ef\u80fd\u6210\u529f\u7684\u60c5\u51b5\u662f\u4eba\u4eec\u6700\u9700\u8981\u964d\u96e8\u7684\u65f6\u5019\u3002\u6211\u4eec\u57fa\u4e8e\u897f\u73ed\u7259\u7a46\u5c14\u897f\u4e9a\u5730\u533a\u4e24\u767e\u5e74\u7684\u964d\u96e8\u7948\u7977\u6570\u636e\uff0c\u53d1\u73b0\u6559\u4f1a\u7684\u7948\u96e8\u884c\u4e3a\u80fd\u591f\u9884\u6d4b\u964d\u96e8\u60c5\u51b5\u3002\u4e3a\u4e86\u5c06\u8fd9\u4e00\u53d1\u73b0\u63a8\u5e7f\uff0c\u6211\u4eec\u6536\u96c6\u4e86\u5168\u7403\u5404\u6c11\u65cf\u4f20\u7edf\u4e0a\u662f\u5426\u7948\u6c42\u964d\u96e8\u7684\u539f\u59cb\u6570\u636e\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u9762\u5bf9\u964d\u96e8\u5371\u9669\u7387\u4e0a\u5347\u7684\u6c11\u65cf\u7fa4\u4f53\uff0c\u7948\u6c42\u964d\u96e8\u7684\u53ef\u80fd\u6027\u9ad8\u51fa47%\uff0c\u8fd9\u4e0e\u6211\u4eec\u7684\u6a21\u578b\u9884\u6d4b\u4e00\u81f4\uff0c\u5373\u793e\u4f1a\u5728\u7948\u7977\u5177\u6709\u8bf4\u670d\u529b\u7684\u5730\u65b9\u66f4\u53ef\u80fd\u8fdb\u884c\u7948\u96e8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag040", "journal": "REStud", "title": "The Dynamics of Verification when Searching for Quality", "authors": ["Zihao Li", "Jonathan Libgober"], "author_details": [{"name": "Zihao Li", "affiliations": ["Columbia University ,"]}, {"name": "Jonathan Libgober", "affiliations": ["University of Southern California ,"]}], "abstract": "Abstract An agent samples projects over time, observing quality for each, while a principal can select at most one. The principal values quality, whereas the agent only wants a project chosen. Transfers are unavailable, but the principal can verify quality by paying a cost. We fully characterize the dynamics of verification by determining optimal mechanisms for this problem. With a low verification cost and a long horizon, the optimal mechanism involves a deterministic selection rule that initially discriminates on quality but chooses a project irrespective of its quality at a deadline. Verification occurs with an intermediate probability before the deadline, declining over time. We show how these conclusions change if the verification cost is high or the horizon is short, and under certain forms of imperfect commitment. Our analysis provides guidelines on how dynamics interact with the benefits of verification.", "date": "2026-05-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag040", "title_zh": "\u5bfb\u627e\u8d28\u91cf\u8fc7\u7a0b\u4e2d\u7684\u9a8c\u8bc1\u52a8\u6001", "abstract_zh": "\u6458\u8981 \u4e00\u4e2a\u4ee3\u7406\u4eba\u968f\u7740\u65f6\u95f4\u63a8\u79fb\u91c7\u6837\u9879\u76ee\uff0c\u5e76\u89c2\u5bdf\u6bcf\u4e2a\u9879\u76ee\u7684\u8d28\u91cf\uff0c\u800c\u59d4\u6258\u4eba\u6700\u591a\u53ea\u80fd\u9009\u62e9\u4e00\u4e2a\u9879\u76ee\u3002\u59d4\u6258\u4eba\u91cd\u89c6\u9879\u76ee\u8d28\u91cf\uff0c\u800c\u4ee3\u7406\u4eba\u53ea\u5e0c\u671b\u6709\u4e00\u4e2a\u9879\u76ee\u88ab\u9009\u4e2d\u3002\u4e0d\u5b58\u5728\u8f6c\u79fb\u652f\u4ed8\uff0c\u4f46\u59d4\u6258\u4eba\u53ef\u4ee5\u901a\u8fc7\u652f\u4ed8\u6210\u672c\u6765\u9a8c\u8bc1\u9879\u76ee\u8d28\u91cf\u3002\u6211\u4eec\u5b8c\u5168\u523b\u753b\u4e86\u9a8c\u8bc1\u7684\u52a8\u6001\u8fc7\u7a0b\uff0c\u901a\u8fc7\u786e\u5b9a\u8be5\u95ee\u9898\u7684\u6700\u4f18\u673a\u5236\u6765\u5b9e\u73b0\u3002\u5f53\u9a8c\u8bc1\u6210\u672c\u8f83\u4f4e\u4e14\u65f6\u95f4\u8de8\u5ea6\u8f83\u957f\u65f6\uff0c\u6700\u4f18\u673a\u5236\u5305\u542b\u4e00\u4e2a\u786e\u5b9a\u6027\u7684\u9009\u62e9\u89c4\u5219\uff1a\u521d\u59cb\u9636\u6bb5\u6839\u636e\u8d28\u91cf\u8fdb\u884c\u533a\u5206\uff0c\u4f46\u5728\u622a\u6b62\u65e5\u671f\u524d\u65e0\u8bba\u8d28\u91cf\u5982\u4f55\u90fd\u9009\u62e9\u4e00\u4e2a\u9879\u76ee\u3002\u5728\u622a\u6b62\u65e5\u671f\u524d\uff0c\u9a8c\u8bc1\u4ee5\u4e2d\u95f4\u6982\u7387\u53d1\u751f\uff0c\u4e14\u968f\u65f6\u95f4\u63a8\u79fb\u800c\u9012\u51cf\u3002\u6211\u4eec\u5c55\u793a\u4e86\u5f53\u9a8c\u8bc1\u6210\u672c\u8f83\u9ad8\u6216\u65f6\u95f4\u8de8\u5ea6\u8f83\u77ed\uff0c\u4ee5\u53ca\u5728\u67d0\u4e9b\u4e0d\u5b8c\u5168\u627f\u8bfa\u5f62\u5f0f\u4e0b\uff0c\u8fd9\u4e9b\u7ed3\u8bba\u5982\u4f55\u53d1\u751f\u53d8\u5316\u3002\u6211\u4eec\u7684\u5206\u6790\u4e3a\u9a8c\u8bc1\u52a8\u6001\u4e0e\u9a8c\u8bc1\u6536\u76ca\u4e4b\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\u63d0\u4f9b\u4e86\u6307\u5bfc\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag039", "journal": "REStud", "title": "Counterfactual Analysis for Structural Dynamic Discrete Choice Models", "authors": ["Myrto Kalouptsidi", "Yuichi Kitamura", "Lucas Lima", "Eduardo Souza-Rodrigues"], "author_details": [{"name": "Myrto Kalouptsidi", "affiliations": ["Harvard University, USA, CEPR, UK, and NBER, USA Department of Economics,"]}, {"name": "Yuichi Kitamura", "affiliations": ["Yale University, USA Department of Economics,"]}, {"name": "Lucas Lima", "affiliations": ["PUC-Rio Department of Economics, , Brazil"]}, {"name": "Eduardo Souza-Rodrigues", "affiliations": ["University of Toronto, Canada, and CEPR Department of Economics, , UK"]}], "abstract": "Abstract Discrete choice data allow researchers to recover differences in utilities, but these differences may not suffice to identify policy-relevant counterfactuals of interest. In fact, in the case of dynamic discrete choice models, only a narrow set of counterfactuals are point-identified. In this paper, we explore how much one can learn about counterfactual outcomes of interest within this framework. We focus on the partial identification of counterfactuals, while allowing for (mild) model restrictions that can gradually shrink the identified set. We derive bounds for low-dimensional objects (such as average welfare) as arguments of optimization programmes, along with a uniformly valid inference procedure. Furthermore, we develop new and tractable computational tools and algorithms suitable for dealing with high-dimensional problems like this. Finally, we illustrate in Monte Carlos, as well as an empirical exercise of firms\u2019 export decisions, the informativeness of the identified sets, and we assess the impact of (common) model restrictions on results.", "date": "2026-05-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag039", "title_zh": "\u7ed3\u6784\u52a8\u6001\u79bb\u6563\u9009\u62e9\u6a21\u578b\u7684\u53cd\u4e8b\u5b9e\u5206\u6790", "abstract_zh": "\u79bb\u6563\u9009\u62e9\u6570\u636e\u4f7f\u7814\u7a76\u4eba\u5458\u80fd\u591f\u6062\u590d\u6548\u7528\u5dee\u5f02\uff0c\u4f46\u8fd9\u4e9b\u5dee\u5f02\u53ef\u80fd\u4e0d\u8db3\u4ee5\u8bc6\u522b\u611f\u5174\u8da3\u7684\u653f\u7b56\u76f8\u5173\u53cd\u4e8b\u5b9e\u3002\u4e8b\u5b9e\u4e0a\uff0c\u5728\u52a8\u6001\u79bb\u6563\u9009\u62e9\u6a21\u578b\u4e2d\uff0c\u53ea\u6709\u5c11\u6570\u53cd\u4e8b\u5b9e\u662f\u70b9\u53ef\u8bc6\u522b\u7684\u3002\u672c\u6587\u63a2\u8ba8\u4e86\u5728\u6b64\u6846\u67b6\u4e0b\u53ef\u4ee5\u83b7\u53d6\u591a\u5c11\u5173\u4e8e\u611f\u5174\u8da3\u53cd\u4e8b\u5b9e\u7ed3\u679c\u7684\u4fe1\u606f\u3002\u6211\u4eec\u5173\u6ce8\u53cd\u4e8b\u5b9e\u7684\u4e0d\u5b8c\u5168\u8bc6\u522b\uff0c\u5e76\u5141\u8bb8\u5f15\u5165\uff08\u6e29\u548c\u7684\uff09\u6a21\u578b\u9650\u5236\uff0c\u4ee5\u9010\u6b65\u7f29\u5c0f\u53ef\u8bc6\u522b\u96c6\u3002\u6211\u4eec\u4e3a\u4f4e\u7ef4\u5bf9\u8c61\uff08\u5982\u5e73\u5747\u798f\u5229\uff09\u63a8\u5bfc\u51fa\u4f5c\u4e3a\u4f18\u5316\u7a0b\u5e8f\u53c2\u6570\u7684\u754c\u9650\uff0c\u5e76\u63d0\u51fa\u4e00\u79cd\u7edf\u4e00\u6709\u6548\u7684\u63a8\u65ad\u7a0b\u5e8f\u3002\u6b64\u5916\uff0c\u6211\u4eec\u5f00\u53d1\u4e86\u65b0\u7684\u3001\u53ef\u64cd\u4f5c\u7684\u8ba1\u7b97\u5de5\u5177\u548c\u7b97\u6cd5\uff0c\u9002\u7528\u4e8e\u5904\u7406\u6b64\u7c7b\u9ad8\u7ef4\u95ee\u9898\u3002\u6700\u540e\uff0c\u6211\u4eec\u901a\u8fc7\u8499\u7279\u5361\u6d1b\u6a21\u62df\u4ee5\u53ca\u4f01\u4e1a\u51fa\u53e3\u51b3\u7b56\u7684\u5b9e\u8bc1\u7814\u7a76\uff0c\u5c55\u793a\u4e86\u53ef\u8bc6\u522b\u96c6\u7684\u4fe1\u606f\u542b\u91cf\uff0c\u5e76\u8bc4\u4f30\u4e86\uff08\u5171\u540c\u7684\uff09\u6a21\u578b\u9650\u5236\u5bf9\u7ed3\u679c\u7684\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70046", "journal": "JF", "title": "The Equilibrium Effects of Eviction Policies", "authors": ["BOAZ ABRAMSON"], "author_details": [{"name": "BOAZ ABRAMSON", "affiliations": []}], "abstract": "ABSTRACT I propose a dynamic equilibrium model of rental markets that endogenously gives rise to defaults on rents and evictions. In the model, eviction protections make it harder to evict delinquent renters, but higher default costs to landlords increase equilibrium rents. I quantify the model using micro data on evictions, rents, and homelessness. I find that stronger eviction protections exacerbate housing insecurity and lower welfare. The key empirical driver of this result is the persistent nature of risk underlying rent delinquencies. Rental assistance reduces housing insecurity and improves welfare because it lowers the likelihood that renters default ex ante.", "date": "2026-05-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70046", "title_zh": "\u9a71\u9010\u653f\u7b56\u7684\u5747\u8861\u6548\u5e94", "abstract_zh": "\u6211\u63d0\u51fa\u4e00\u4e2a\u52a8\u6001\u5747\u8861\u7684\u79df\u8d41\u5e02\u573a\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u5185\u751f\u5730\u4ea7\u751f\u79df\u91d1\u62d6\u6b20\u548c\u9a71\u9010\u884c\u4e3a\u3002\u5728\u6a21\u578b\u4e2d\uff0c\u9a71\u9010\u4fdd\u62a4\u63aa\u65bd\u4f7f\u9a71\u9010\u62d6\u6b20\u79df\u5ba2\u53d8\u5f97\u66f4\u52a0\u56f0\u96be\uff0c\u4f46\u623f\u4e1c\u7684\u8fdd\u7ea6\u6210\u672c\u4e0a\u5347\u4f1a\u5bfc\u81f4\u5747\u8861\u79df\u91d1\u63d0\u9ad8\u3002\u6211\u5229\u7528\u5173\u4e8e\u9a71\u9010\u3001\u79df\u91d1\u548c\u65e0\u5bb6\u53ef\u5f52\u72b6\u51b5\u7684\u5fae\u89c2\u6570\u636e\u5bf9\u6a21\u578b\u8fdb\u884c\u91cf\u5316\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u66f4\u5f3a\u7684\u9a71\u9010\u4fdd\u62a4\u63aa\u65bd\u4f1a\u52a0\u5267\u4f4f\u623f\u4e0d\u5b89\u5168\u72b6\u51b5\u5e76\u964d\u4f4e\u798f\u5229\u3002\u8fd9\u4e00\u7ed3\u679c\u7684\u5173\u952e\u7ecf\u9a8c\u9a71\u52a8\u56e0\u7d20\u662f\u79df\u91d1\u62d6\u6b20\u80cc\u540e\u98ce\u9669\u7684\u6301\u4e45\u6027\u3002\u79df\u8d41\u63f4\u52a9\u80fd\u591f\u964d\u4f4e\u4f4f\u623f\u4e0d\u5b89\u5168\u72b6\u51b5\u5e76\u63d0\u5347\u798f\u5229\uff0c\u56e0\u4e3a\u5b83\u964d\u4f4e\u4e86\u79df\u5ba2\u63d0\u524d\u8fdd\u7ea6\u7684\u53ef\u80fd\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70045", "journal": "JF", "title": "Risk\u2010Free Rates and Convenience Yields around the World", "authors": ["William Diamond", "Peter Van Tassel"], "author_details": [{"name": "William Diamond", "affiliations": []}, {"name": "Peter Van Tassel", "affiliations": []}], "abstract": "ABSTRACT We infer risk\u2010free rates from index option prices to estimate safe asset convenience yields in 10 G11 currencies. Countries' convenience yields increase with the level of their interest rates, with U.S. convenience yields fifth largest. During financial crises, convenience yields grow, but the difference between United States and foreign convenience yields generally does not. Covered interest parity (CIP) deviations using our option\u2010implied rates are a similar size between the United States and each other country. A model in which convenience yields depend on domestic financial intermediaries, but CIP deviations reflect the funding costs of international arbitrageurs financed with dollar\u2010denominated debt, explains these results.", "date": "2026-05-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70045", "title_zh": "\u5168\u7403\u65e0\u98ce\u9669\u5229\u7387\u4e0e\u4fbf\u5229\u6536\u76ca", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u4ece\u6307\u6570\u671f\u6743\u4ef7\u683c\u4e2d\u63a8\u65ad\u51fa10\u4e2aG11\u8d27\u5e01\u7684\u65e0\u98ce\u9669\u5229\u7387\uff0c\u4ee5\u4f30\u7b97\u5b89\u5168\u8d44\u4ea7\u7684\u4fbf\u5229\u6536\u76ca\u3002\u5404\u56fd\u7684\u4fbf\u5229\u6536\u76ca\u968f\u5176\u5229\u7387\u6c34\u5e73\u4e0a\u5347\uff0c\u5176\u4e2d\u7f8e\u56fd\u7684\u4fbf\u5229\u6536\u76ca\u6392\u540d\u7b2c\u4e94\u3002\u5728\u91d1\u878d\u5371\u673a\u671f\u95f4\uff0c\u4fbf\u5229\u6536\u76ca\u4e0a\u5347\uff0c\u4f46\u7f8e\u56fd\u4e0e\u5176\u4ed6\u56fd\u5bb6\u4e4b\u95f4\u7684\u4fbf\u5229\u6536\u76ca\u5dee\u5f02\u901a\u5e38\u4e0d\u5927\u3002\u4f7f\u7528\u6211\u4eec\u57fa\u4e8e\u671f\u6743\u9690\u542b\u5229\u7387\u7684\u8986\u76d6\u5229\u7387\u5e73\u4ef7\uff08CIP\uff09\u504f\u5dee\uff0c\u7f8e\u56fd\u4e0e\u5176\u4ed6\u5404\u56fd\u4e4b\u95f4\u7684\u5dee\u5f02\u76f8\u4f3c\u3002\u4e00\u4e2a\u6a21\u578b\u8868\u660e\uff0c\u4fbf\u5229\u6536\u76ca\u53d6\u51b3\u4e8e\u56fd\u5185\u91d1\u878d\u4e2d\u4ecb\u673a\u6784\uff0c\u800cCIP\u504f\u5dee\u5219\u53cd\u6620\u4e86\u56fd\u9645\u5957\u5229\u8005\u4f7f\u7528\u7f8e\u5143\u8ba1\u4ef7\u503a\u52a1\u6240\u627f\u62c5\u7684\u8d44\u91d1\u6210\u672c\uff0c\u8fd9\u4e00\u6a21\u578b\u80fd\u591f\u89e3\u91ca\u4e0a\u8ff0\u7ed3\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1093/rfs/hhag048", "journal": "RFS", "title": "Mutual Fund Flows and the Supply of Capital in Municipal Financing", "authors": ["Manuel Adelino", "Sophia Chiyoung Cheong", "Jaewon Choi", "Ji Yeol Jimmy Oh"], "author_details": [{"name": "Manuel Adelino", "affiliations": ["Duke University, CEPR and NBER ,"]}, {"name": "Sophia Chiyoung Cheong", "affiliations": ["Hang Seng University of Hong Kong , Hong Kong"]}, {"name": "Jaewon Choi", "affiliations": ["Seoul National University ,"]}, {"name": "Ji Yeol Jimmy Oh", "affiliations": ["Korea University Business School ,"]}], "abstract": "Abstract This paper investigates how capital supply from mutual funds affects municipal bond financing, making three key contributions. First, we introduce an identification strategy using the rule-based update of Morningstar ratings for 5-year-old funds, isolating supply-side effects from fund and issuer fundamentals. The results indicate that exogenous fund flows increase bond issuance probability and decrease yields. Second, these fund flows lead to more issuances when funds and issuers are connected through underwriters, highlighting relationship lending in municipal bond financing. Third, municipal issuers leverage favorable financing conditions for new issuance of revenue bonds, which translates into higher local house prices.", "date": "2026-05-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag048", "title_zh": "\u5171\u540c\u57fa\u91d1\u6d41\u52a8\u4e0e\u5e02\u653f\u878d\u8d44\u4e2d\u7684\u8d44\u672c\u4f9b\u7ed9", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5171\u540c\u57fa\u91d1\u8d44\u672c\u4f9b\u7ed9\u5982\u4f55\u5f71\u54cd\u5e02\u653f\u503a\u5238\u878d\u8d44\uff0c\u505a\u51fa\u4e86\u4e09\u4e2a\u5173\u952e\u8d21\u732e\u3002\u9996\u5148\uff0c\u6211\u4eec\u91c7\u7528\u6668\u661f\u8bc4\u7ea7\u5bf95\u5e74\u671f\u57fa\u91d1\u8fdb\u884c\u89c4\u5219\u5316\u66f4\u65b0\u7684\u65b9\u6cd5\uff0c\u6784\u5efa\u4e86\u8bc6\u522b\u7b56\u7565\uff0c\u5c06\u4f9b\u7ed9\u4fa7\u6548\u5e94\u4e0e\u57fa\u91d1\u548c\u53d1\u884c\u65b9\u7684\u57fa\u672c\u9762\u56e0\u7d20\u5206\u79bb\u3002\u7ed3\u679c\u8868\u660e\uff0c\u5916\u751f\u6027\u7684\u57fa\u91d1\u6d41\u52a8\u4f1a\u63d0\u9ad8\u503a\u5238\u53d1\u884c\u6982\u7387\u5e76\u964d\u4f4e\u53d1\u884c\u5229\u7387\u3002\u5176\u6b21\uff0c\u5f53\u57fa\u91d1\u4e0e\u53d1\u884c\u65b9\u901a\u8fc7\u627f\u9500\u5546\u76f8\u8fde\u65f6\uff0c\u8fd9\u4e9b\u57fa\u91d1\u6d41\u52a8\u4f1a\u4fc3\u8fdb\u66f4\u591a\u53d1\u884c\uff0c\u51f8\u663e\u4e86\u5e02\u653f\u503a\u5238\u878d\u8d44\u4e2d\u7684\u5173\u7cfb\u8d37\u6b3e\u73b0\u8c61\u3002\u7b2c\u4e09\uff0c\u5e02\u653f\u53d1\u884c\u65b9\u4f1a\u5229\u7528\u6709\u5229\u7684\u878d\u8d44\u6761\u4ef6\u8fdb\u884c\u6536\u5165\u503a\u5238\u7684\u65b0\u53d1\u884c\uff0c\u4ece\u800c\u63a8\u9ad8\u5f53\u5730\u623f\u4ef7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005", "\u8d44\u672c\u6d41\u52a8"]}, {"doi": "10.1111/jofi.70042", "journal": "JF", "title": "Partisan Entrepreneurship", "authors": ["JOSEPH ENGELBERG", "JORGE GUZMAN", "RUNJING LU", "WILLIAM MULLINS"], "author_details": [{"name": "JOSEPH ENGELBERG", "affiliations": []}, {"name": "JORGE GUZMAN", "affiliations": []}, {"name": "RUNJING LU", "affiliations": []}, {"name": "WILLIAM MULLINS", "affiliations": []}], "abstract": "ABSTRACT Republicans start more firms than Democrats. In a sample of 40 million party\u2010identified Americans between 2005 and 2017, we find that 5.5% of Republicans and 3.7% of Democrats become entrepreneurs. This partisan entrepreneurship gap is time\u2010varying\u2014Republicans increase their relative entrepreneurship during Republican administrations and decrease it during Democratic administrations, amounting to a partisan reallocation of 170,000 new firms over our 13\u2010year sample. We find sharp changes in partisan entrepreneurship around the elections of President Obama and President Trump, with the strongest effects among the most politically active partisans: those that donate and vote.", "date": "2026-05-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70042", "title_zh": "\u515a\u6d3e\u521b\u4e1a", "abstract_zh": "\u6458\u8981 \u5171\u548c\u515a\u4eba\u521b\u529e\u7684\u4f01\u4e1a\u6570\u91cf\u591a\u4e8e\u6c11\u4e3b\u515a\u4eba\u3002\u57282005\u5e74\u81f32017\u5e74\u95f4\uff0c\u5bf94000\u4e07\u540d\u6709\u515a\u6d3e\u5f52\u5c5e\u7684\u7f8e\u56fd\u4eba\u7684\u6837\u672c\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\u5171\u548c\u515a\u4eba\u4e2d\u67095.5%\u6210\u4e3a\u521b\u4e1a\u8005\uff0c\u800c\u6c11\u4e3b\u515a\u4eba\u4e2d\u4ec5\u67093.7%\u3002\u8fd9\u79cd\u515a\u6d3e\u521b\u4e1a\u5dee\u8ddd\u662f\u968f\u65f6\u95f4\u53d8\u5316\u7684\u2014\u2014\u5728\u5171\u548c\u515a\u6267\u653f\u671f\u95f4\uff0c\u5171\u548c\u515a\u4eba\u7684\u76f8\u5bf9\u521b\u4e1a\u6bd4\u4f8b\u4e0a\u5347\uff1b\u5728\u6c11\u4e3b\u515a\u6267\u653f\u671f\u95f4\u5219\u4e0b\u964d\uff0c\u6574\u4e2a13\u5e74\u6837\u672c\u671f\u5185\uff0c\u8fd9\u4e00\u515a\u6d3e\u521b\u4e1a\u518d\u5206\u914d\u5171\u4ea7\u751f\u4e8617\u4e07\u5bb6\u4f01\u4e1a\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u5965\u5df4\u9a6c\u548c\u7279\u6717\u666e\u603b\u7edf\u7684\u9009\u4e3e\u524d\u540e\uff0c\u515a\u6d3e\u521b\u4e1a\u884c\u4e3a\u51fa\u73b0\u663e\u8457\u53d8\u5316\uff0c\u4e14\u5728\u6700\u79ef\u6781\u53c2\u4e0e\u653f\u6cbb\u7684\u7fa4\u4f53\u4e2d\uff08\u5982\u6350\u6b3e\u548c\u6295\u7968\u8005\uff09\u6548\u5e94\u6700\u4e3a\u660e\u663e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70040", "journal": "JF", "title": "Learning in the Limit: Income Inference from Credit Extensions", "authors": ["XIAO YIN"], "author_details": [{"name": "XIAO YIN", "affiliations": []}], "abstract": "ABSTRACT Combining a randomized controlled trial with administrative and survey data, this paper shows that credit limit extensions significantly increase total spending and income expectations. By controlling for changes in personal income expectations, the spending response to credit limit extensions weakens by approximately 30%. For financially unconstrained consumers, expectation changes account for around two\u2010thirds of the spending responses to limit extensions. These findings are consistent with consumers inferring future income from credit supply.", "date": "2026-05-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70040", "title_zh": "\u6781\u9650\u5b66\u4e60\uff1a\u4ece\u4fe1\u8d37\u6269\u5c55\u4e2d\u63a8\u65ad\u6536\u5165", "abstract_zh": "\u6458\u8981 \u672c\u6587\u7ed3\u5408\u968f\u673a\u5bf9\u7167\u8bd5\u9a8c\u4e0e\u884c\u653f\u548c\u8c03\u67e5\u6570\u636e\uff0c\u8868\u660e\u4fe1\u8d37\u989d\u5ea6\u6269\u5c55\u663e\u8457\u63d0\u9ad8\u4e86\u603b\u652f\u51fa\u548c\u6536\u5165\u9884\u671f\u3002\u5728\u63a7\u5236\u4e2a\u4eba\u6536\u5165\u9884\u671f\u53d8\u5316\u540e\uff0c\u4fe1\u8d37\u989d\u5ea6\u6269\u5c55\u5bf9\u652f\u51fa\u7684\u54cd\u5e94\u51cf\u5f31\u4e86\u7ea630%\u3002\u5bf9\u4e8e\u8d22\u52a1\u65e0\u7ea6\u675f\u7684\u6d88\u8d39\u8005\uff0c\u9884\u671f\u53d8\u5316\u89e3\u91ca\u4e86\u989d\u5ea6\u6269\u5c55\u5bf9\u652f\u51fa\u54cd\u5e94\u7684\u7ea6\u4e09\u5206\u4e4b\u4e8c\u3002\u8fd9\u4e9b\u53d1\u73b0\u652f\u6301\u6d88\u8d39\u8005\u4ece\u4fe1\u8d37\u4f9b\u7ed9\u4e2d\u63a8\u65ad\u672a\u6765\u6536\u5165\u7684\u89c2\u70b9\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhaf079", "journal": "RFS", "title": "Macroeconomic Expectations and Credit Card Spending", "authors": ["Mikhail Galashin", "Martin Kanz", "Ricardo Perez-Truglia"], "author_details": [{"name": "Mikhail Galashin", "affiliations": ["University of California , Los Angeles"]}, {"name": "Martin Kanz", "affiliations": ["World Bank and CEPR"]}, {"name": "Ricardo Perez-Truglia", "affiliations": ["University of California, Los Angeles and NBER"]}], "abstract": "Abstract We examine how macroeconomic expectations affect consumer decisions, using an experiment with 2,872 credit card customers at a large commercial bank. In the experiment, participants are randomized into receiving expert forecasts of inflation and the nominal exchange rate. We find that forecasts shift inflation and exchange rate expectations, but do not change spending or self-reported consumption plans as predicted by standard models of intertemporal choice. Results from a supplementary survey experiment suggest that consumers are sophisticated enough to anticipate nominal rigidities and reduce spending on durables for precautionary reasons, counteracting the effects predicted by standard models of intertemporal optimization.", "date": "2026-05-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf079", "title_zh": "\u5b8f\u89c2\u7ecf\u6d4e\u9884\u671f\u4e0e\u4fe1\u7528\u5361\u6d88\u8d39", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u5b8f\u89c2\u7ecf\u6d4e\u9884\u671f\u5982\u4f55\u5f71\u54cd\u6d88\u8d39\u8005\u51b3\u7b56\uff0c\u901a\u8fc7\u4e00\u9879\u6d89\u53ca\u5927\u578b\u5546\u4e1a\u94f6\u884c2872\u540d\u4fe1\u7528\u5361\u5ba2\u6237\u7684\u7814\u7a76\u5b9e\u9a8c\u3002\u5728\u5b9e\u9a8c\u4e2d\uff0c\u53c2\u4e0e\u8005\u88ab\u968f\u673a\u5206\u914d\u63a5\u6536\u5173\u4e8e\u901a\u80c0\u7387\u548c\u540d\u4e49\u6c47\u7387\u7684\u4e13\u5bb6\u9884\u6d4b\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u4e9b\u9884\u6d4b\u786e\u5b9e\u6539\u53d8\u4e86\u4eba\u4eec\u5bf9\u901a\u80c0\u548c\u6c47\u7387\u7684\u9884\u671f\uff0c\u4f46\u5e76\u672a\u6539\u53d8\u6d88\u8d39\u884c\u4e3a\u6216\u81ea\u6211\u62a5\u544a\u7684\u6d88\u8d39\u8ba1\u5212\uff0c\u8fd9\u4e0e\u6807\u51c6\u7684\u8de8\u671f\u9009\u62e9\u6a21\u578b\u9884\u6d4b\u4e0d\u7b26\u3002\u8865\u5145\u7684\u8c03\u67e5\u5b9e\u9a8c\u7ed3\u679c\u8868\u660e\uff0c\u6d88\u8d39\u8005\u5177\u5907\u8db3\u591f\u7684\u5224\u65ad\u529b\uff0c\u80fd\u591f\u9884\u89c1\u5230\u540d\u4e49\u521a\u6027\uff0c\u5e76\u51fa\u4e8e\u9884\u9632\u6027\u8003\u8651\u51cf\u5c11\u5bf9\u8010\u7528\u54c1\u7684\u652f\u51fa\uff0c\u4ece\u800c\u62b5\u6d88\u4e86\u6807\u51c6\u8de8\u671f\u4f18\u5316\u6a21\u578b\u6240\u9884\u6d4b\u7684\u6548\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag047", "journal": "RFS", "title": "A Dynamic Model of the Racial Wealth Gap", "authors": ["Sylvain Catherine", "Ellen Jiayang Lu", "James D Paron"], "author_details": [{"name": "Sylvain Catherine", "affiliations": ["The Wharton School, University of Pennsylvania ,"]}, {"name": "Ellen Jiayang Lu", "affiliations": ["The Wharton School, University of Pennsylvania ,"]}, {"name": "James D Paron", "affiliations": ["Stanford Graduate School of Business ,"]}], "abstract": "Abstract What explains wealth and portfolio differences between black and white Americans? We find that disparities in economic factors explain portfolios well, but only partly explain the wealth gap. In a dynamic setting, economic factors often change optimal saving rates in ways that offset their effects on income and returns. Consequently, their net wealth effect is often limited, making the wealth gap harder to explain. We estimate that differences in income levels, income risk, family structures, mortality, health expenditures, property taxes, mortgage rates, and asset returns explain half of the differential between the racial wealth gap and the racial income gap.", "date": "2026-05-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag047", "title_zh": "\u79cd\u65cf\u8d22\u5bcc\u5dee\u8ddd\u7684\u52a8\u6001\u6a21\u578b", "abstract_zh": "\u6458\u8981 \u4ec0\u4e48\u89e3\u91ca\u4e86\u7f8e\u56fd\u9ed1\u4eba\u548c\u767d\u4eba\u4e4b\u95f4\u7684\u8d22\u5bcc\u53ca\u6295\u8d44\u7ec4\u5408\u5dee\u5f02\uff1f\u6211\u4eec\u53d1\u73b0\uff0c\u7ecf\u6d4e\u56e0\u7d20\u7684\u5dee\u5f02\u80fd\u591f\u8f83\u597d\u5730\u89e3\u91ca\u6295\u8d44\u7ec4\u5408\u7684\u5dee\u5f02\uff0c\u4f46\u4ec5\u90e8\u5206\u89e3\u91ca\u4e86\u79cd\u65cf\u8d22\u5bcc\u5dee\u8ddd\u3002\u5728\u52a8\u6001\u73af\u5883\u4e2d\uff0c\u7ecf\u6d4e\u56e0\u7d20\u5f80\u5f80\u901a\u8fc7\u6539\u53d8\u6700\u4f18\u50a8\u84c4\u7387\uff0c\u4ece\u800c\u62b5\u6d88\u5176\u5bf9\u6536\u5165\u548c\u6536\u76ca\u7684\u5f71\u54cd\u3002\u56e0\u6b64\uff0c\u8fd9\u4e9b\u56e0\u7d20\u7684\u51c0\u8d22\u5bcc\u6548\u5e94\u901a\u5e38\u6709\u9650\uff0c\u4f7f\u5f97\u79cd\u65cf\u8d22\u5bcc\u5dee\u8ddd\u7684\u89e3\u91ca\u53d8\u5f97\u66f4\u52a0\u56f0\u96be\u3002\u6211\u4eec\u4f30\u8ba1\uff0c\u6536\u5165\u6c34\u5e73\u3001\u6536\u5165\u98ce\u9669\u3001\u5bb6\u5ead\u7ed3\u6784\u3001\u6b7b\u4ea1\u7387\u3001\u533b\u7597\u652f\u51fa\u3001\u623f\u4ea7\u7a0e\u3001\u623f\u8d37\u5229\u7387\u4ee5\u53ca\u8d44\u4ea7\u56de\u62a5\u7b49\u65b9\u9762\u7684\u5dee\u5f02\uff0c\u89e3\u91ca\u4e86\u79cd\u65cf\u8d22\u5bcc\u5dee\u8ddd\u4e0e\u79cd\u65cf\u6536\u5165\u5dee\u8ddd\u4e4b\u95f4\u5dee\u5f02\u7684\u4e00\u534a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1017/s0022109025102524", "journal": "JFQA", "title": "Household Finance at the Origin: Home Ownership as a Cultural Heritage from Agriculture", "authors": ["Guillaume Vuillemey"], "author_details": [{"name": "Guillaume Vuillemey", "affiliations": ["HEC Paris"]}], "abstract": "Abstract I show that home ownership decisions across countries and individuals are shaped by a cultural heritage from agriculture. For centuries, dominant assets in preindustrial economies were either land or cattle. Consequently, the type of farming prevailing locally shaped preferences and beliefs about the relative value of immovable and movable assets. This cultural heritage had long-lasting consequences. Today, individuals originating from societies with a history of crop agriculture\u2014where the dominant asset was land\u2014are more likely to be homeowners. For identification, I rely both on home ownership decisions of second-generation immigrants in the United States and on an instrument.", "date": "2026-05-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102524", "title_zh": "\u5bb6\u5ead\u91d1\u878d\u7684\u8d77\u6e90\uff1a\u4f4f\u623f\u6240\u6709\u6743\u4f5c\u4e3a\u519c\u4e1a\u6587\u5316\u7684\u9057\u4ea7", "abstract_zh": "\u6211\u8bc1\u660e\uff0c\u5404\u56fd\u548c\u4e2a\u4eba\u7684\u4f4f\u623f\u6240\u6709\u6743\u51b3\u7b56\u53d7\u5230\u519c\u4e1a\u6587\u5316\u9057\u4ea7\u7684\u5f71\u54cd\u3002\u6570\u767e\u5e74\u6765\uff0c\u524d\u5de5\u4e1a\u793e\u4f1a\u4e2d\u7684\u4e3b\u8981\u8d44\u4ea7\u8981\u4e48\u662f\u571f\u5730\uff0c\u8981\u4e48\u662f\u7272\u755c\u3002\u56e0\u6b64\uff0c\u5f53\u5730\u76db\u884c\u7684\u8015\u4f5c\u65b9\u5f0f\u5851\u9020\u4e86\u4eba\u4eec\u5bf9\u4e0d\u52a8\u4ea7\u548c\u52a8\u4ea7\u76f8\u5bf9\u4ef7\u503c\u7684\u504f\u597d\u548c\u4fe1\u5ff5\u3002\u8fd9\u79cd\u6587\u5316\u9057\u4ea7\u4ea7\u751f\u4e86\u957f\u671f\u5f71\u54cd\u3002\u4eca\u5929\uff0c\u6765\u81ea\u4ee5\u571f\u5730\u4e3a\u4e3b\u8981\u8d44\u4ea7\u7684\u4f5c\u7269\u519c\u4e1a\u5386\u53f2\u793e\u4f1a\u7684\u4e2a\u4f53\uff0c\u66f4\u6709\u53ef\u80fd\u62e5\u6709\u4f4f\u623f\u3002\u4e3a\u4e86\u8bc6\u522b\uff0c\u6211\u4f9d\u8d56\u7f8e\u56fd\u7b2c\u4e8c\u4ee3\u79fb\u6c11\u7684\u4f4f\u623f\u6240\u6709\u6743\u51b3\u7b56\u4ee5\u53ca\u4e00\u4e2a\u5de5\u5177\u53d8\u91cf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag024", "journal": "QJE", "title": "Why Doesn\u2019t the United States Have National Health Insurance? The Political Role of the American Medical Association", "authors": ["Marcella Alsan", "Yousra Neberai"], "author_details": [{"name": "Marcella Alsan", "affiliations": ["Stanford University and National Bureau of Economic Research ,"]}, {"name": "Yousra Neberai", "affiliations": ["Harvard University ,"]}], "abstract": "Abstract This article examines how the American Medical Association (AMA) helped shape the development of the U.S. health insurance system in the critical period after World War II. Working with the political public relations firm Campaigns, Inc., the AMA launched a nationwide campaign to weaken support for national health insurance by framing it as \u201csocialized medicine,\u201d while simultaneously enrolling people in private health insurance plans to shift demand away from a public alternative. Drawing on newly assembled archival data, we find that greater exposure to the campaign explains about 20% of the rise in private health insurance enrollment and a comparable decline in public support for a national program. The campaign also appears to have influenced policy making through coordinated messaging, resolutions passed by civic organizations, congressional rhetoric, and political donations. These findings suggest that the rise of private health insurance in the United States was not solely due to macroeconomic forces or collective bargaining; rather, it was also enabled by a strategic, interest group\u2013financed effort to shape citizen views and influence policy.", "date": "2026-05-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag024", "title_zh": "\u4e3a\u4ec0\u4e48\u7f8e\u56fd\u6ca1\u6709\u5168\u56fd\u533b\u7597\u4fdd\u9669\uff1f\u7f8e\u56fd\u533b\u5b66\u4f1a\u7684\u653f\u6cbb\u4f5c\u7528", "abstract_zh": "\u672c\u6587\u8003\u5bdf\u4e86\u7f8e\u56fd\u533b\u5b66\u4f1a\uff08AMA\uff09\u5982\u4f55\u5728\u4e8c\u6218\u540e\u5173\u952e\u65f6\u671f\u5f71\u54cd\u7f8e\u56fd\u5065\u5eb7\u4fdd\u9669\u4f53\u7cfb\u7684\u5f62\u6210\u3002AMA\u4e0e\u653f\u6cbb\u516c\u5171\u5173\u7cfb\u516c\u53f8Campaigns, Inc.\u5408\u4f5c\uff0c\u5c55\u5f00\u5168\u56fd\u6027\u5ba3\u4f20\u8fd0\u52a8\uff0c\u5c06\u5168\u56fd\u533b\u7597\u4fdd\u9669\u63cf\u7ed8\u4e3a\u201c\u793e\u4f1a\u5316\u7684\u533b\u7597\u201d\uff0c\u540c\u65f6\u901a\u8fc7\u63a8\u52a8\u4eba\u4eec\u52a0\u5165\u79c1\u4eba\u5065\u5eb7\u4fdd\u9669\u8ba1\u5212\uff0c\u5c06\u9700\u6c42\u4ece\u516c\u5171\u66ff\u4ee3\u65b9\u6848\u8f6c\u79fb\u81f3\u79c1\u4eba\u65b9\u6848\u3002\u57fa\u4e8e\u65b0\u6536\u96c6\u7684\u6863\u6848\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5bf9\u8fd9\u4e00\u5ba3\u4f20\u7684\u63a5\u89e6\u7a0b\u5ea6\u89e3\u91ca\u4e86\u7ea620%\u7684\u79c1\u4eba\u5065\u5eb7\u4fdd\u9669\u53c2\u4fdd\u4eba\u6570\u589e\u957f\uff0c\u4ee5\u53ca\u7c7b\u4f3c\u7a0b\u5ea6\u7684\u516c\u4f17\u5bf9\u5168\u56fd\u6027\u533b\u7597\u8ba1\u5212\u652f\u6301\u7684\u4e0b\u964d\u3002\u8be5\u5ba3\u4f20\u8fd0\u52a8\u4f3c\u4e4e\u8fd8\u901a\u8fc7\u534f\u8c03\u4fe1\u606f\u4f20\u64ad\u3001\u516c\u6c11\u7ec4\u7ec7\u901a\u8fc7\u7684\u51b3\u8bae\u3001\u56fd\u4f1a\u8a00\u8bba\u4ee5\u53ca\u653f\u6cbb\u6350\u6b3e\u7b49\u65b9\u5f0f\u5f71\u54cd\u4e86\u653f\u7b56\u5236\u5b9a\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u7f8e\u56fd\u79c1\u4eba\u5065\u5eb7\u4fdd\u9669\u7684\u5174\u8d77\u5e76\u975e\u4ec5\u7531\u5b8f\u89c2\u7ecf\u6d4e\u56e0\u7d20\u6216\u96c6\u4f53\u8c08\u5224\u9020\u6210\uff0c\u800c\u662f\u4e5f\u5f97\u76ca\u4e8e\u4e00\u4e2a\u7531\u5229\u76ca\u96c6\u56e2\u8d44\u52a9\u3001\u65e8\u5728\u5851\u9020\u516c\u4f17\u89c2\u70b9\u5e76\u5f71\u54cd\u653f\u7b56\u7684\u6709\u7b56\u7565\u884c\u52a8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag037", "journal": "REStud", "title": "Racial Disparities in Federal Sentencing: Evidence from Drug Mandatory Minimums", "authors": ["Cody Tuttle"], "author_details": [{"name": "Cody Tuttle", "affiliations": ["Department of Economics, University of Texas at Austin ,"]}], "abstract": "Abstract I study racial disparities in the criminal justice system by analysing abnormal bunching in the distribution of crack-cocaine amounts used in federal sentencing. I compare cases sentenced before and after the Fair Sentencing Act, a 2010 law that changed the 10-year mandatory minimum threshold for crack-cocaine from 50 g to 280 g. First, I find that after 2010, there is a sharp increase in the fraction of cases sentenced at 280 g (the point that now triggers a 10-year mandatory minimum), and that this increase is disproportionately large for black and Hispanic offenders. I then explore several possible explanations for the observed racial disparities, including racial discrimination that occurs after entry into the criminal justice system. I analyse data from multiple stages in the criminal justice system and find that the increased bunching for minority offenders is driven by prosecutorial discretion, specifically as used by about 20\u201330% of prosecutors. Moreover, the fraction of cases at 280 g falls in 2013 when evidentiary standards become stricter. Finally, the racial disparity in the increase cannot be explained by differences in education, sex, age, criminal history, seized drug amount, or other elements of the crime, but it can be largely explained by a measure of state-level racial animus. These results shed light on the role of prosecutorial discretion and racial discrimination as causes of racial disparities in sentencing.", "date": "2026-05-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag037", "title_zh": "\u8054\u90a6\u91cf\u5211\u4e2d\u7684\u79cd\u65cf\u5dee\u5f02\uff1a\u6765\u81ea\u6bd2\u54c1\u5f3a\u5236\u6700\u4f4e\u5211\u7f5a\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u901a\u8fc7\u5206\u6790\u8054\u90a6\u91cf\u5211\u4e2d\u53ef\u5361\u56e0\u542b\u91cf\u5206\u5e03\u4e2d\u7684\u5f02\u5e38\u96c6\u4e2d\u73b0\u8c61\uff0c\u7814\u7a76\u5211\u4e8b\u53f8\u6cd5\u7cfb\u7edf\u4e2d\u7684\u79cd\u65cf\u5dee\u5f02\u3002\u6211\u6bd4\u8f83\u4e86\u300a\u516c\u5e73\u91cf\u5211\u6cd5\u6848\u300b\uff082010\u5e74\uff09\u5b9e\u65bd\u524d\u540e\u7684\u6570\u636e\uff0c\u8be5\u6cd5\u6848\u5c06\u53ef\u5361\u56e010\u5e74\u5f3a\u5236\u6700\u4f4e\u5211\u7f5a\u7684\u95e8\u69db\u4ece50\u514b\u63d0\u9ad8\u5230280\u514b\u3002\u9996\u5148\uff0c\u6211\u53d1\u73b02010\u5e74\u540e\uff0c\u88ab\u5224\u5904280\u514b\uff08\u73b0\u5728\u89e6\u53d110\u5e74\u5f3a\u5236\u6700\u4f4e\u5211\u7f5a\uff09\u7684\u6848\u4ef6\u6bd4\u4f8b\u663e\u8457\u4e0a\u5347\uff0c\u4e14\u8fd9\u4e00\u4e0a\u5347\u8d8b\u52bf\u5728\u9ed1\u4eba\u548c\u897f\u73ed\u7259\u88d4\u7f6a\u72af\u4e2d\u5c24\u4e3a\u660e\u663e\u3002\u968f\u540e\uff0c\u6211\u63a2\u8ba8\u4e86\u89c2\u5bdf\u5230\u7684\u79cd\u65cf\u5dee\u5f02\u7684\u51e0\u79cd\u53ef\u80fd\u89e3\u91ca\uff0c\u5305\u62ec\u8fdb\u5165\u5211\u4e8b\u53f8\u6cd5\u7cfb\u7edf\u540e\u53d1\u751f\u7684\u79cd\u65cf\u6b67\u89c6\u3002\u6211\u5206\u6790\u4e86\u5211\u4e8b\u53f8\u6cd5\u7cfb\u7edf\u591a\u4e2a\u9636\u6bb5\u7684\u6570\u636e\uff0c\u53d1\u73b0\u5c11\u6570\u65cf\u88d4\u7f6a\u72af\u4e2d280\u514b\u91cf\u5211\u6bd4\u4f8b\u7684\u4e0a\u5347\u4e3b\u8981\u7531\u68c0\u5bdf\u5b98\u7684\u81ea\u7531\u88c1\u91cf\u6743\u9a71\u52a8\uff0c\u7279\u522b\u662f\u7ea620%\u81f330%\u7684\u68c0\u5bdf\u5b98\u6240\u884c\u4f7f\u7684\u88c1\u91cf\u6743\u3002\u6b64\u5916\uff0c2013\u5e74\u5f53\u8bc1\u636e\u6807\u51c6\u53d8\u5f97\u66f4\u52a0\u4e25\u683c\u65f6\uff0c280\u514b\u91cf\u5211\u7684\u6bd4\u4f8b\u4e0b\u964d\u3002\u6700\u540e\uff0c\u79cd\u65cf\u5dee\u5f02\u65e0\u6cd5\u901a\u8fc7\u6559\u80b2\u6c34\u5e73\u3001\u6027\u522b\u3001\u5e74\u9f84\u3001\u72af\u7f6a\u8bb0\u5f55\u3001\u7f34\u83b7\u6bd2\u54c1\u6570\u91cf\u6216\u5176\u4ed6\u6848\u4ef6\u8981\u7d20\u6765\u89e3\u91ca\uff0c\u4f46\u53ef\u4ee5\u5f88\u5927\u7a0b\u5ea6\u4e0a\u901a\u8fc7\u8861\u91cf\u5404\u5dde\u5c42\u9762\u7684\u79cd\u65cf\u504f\u89c1\u7a0b\u5ea6\u6765\u89e3\u91ca\u3002\u8fd9\u4e9b\u7ed3\u679c\u63ed\u793a\u4e86\u68c0\u5bdf\u5b98\u81ea\u7531\u88c1\u91cf\u6743\u548c\u79cd\u65cf\u6b67\u89c6\u5728\u91cf\u5211\u79cd\u65cf\u5dee\u5f02\u4e2d\u7684\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20231107", "journal": "AER", "title": "The Gender Pay Gap: Micro Sources and Macro Consequences", "authors": ["Iacopo Morchio", "Christian Moser"], "author_details": [{"name": "Iacopo Morchio", "affiliations": ["University of Bristol (email: )"]}, {"name": "Christian Moser", "affiliations": ["Columbia University, NBER, CEPR, CESifo, and IZA@LISER (email: )"]}], "abstract": "Using linked employer-employee data from Brazil, we document a significant gender pay gap, which is largely attributed to women working at lower-paying employers. To interpret this fact, we develop an equilibrium search model with endogenous firm pay, amenities, and hiring. We provide a constructive proof of identification of all model parameters. The estimated model suggests that amenities are important for both men and women, and that compensating differentials account for half of the gender pay gap. Equal treatment policies partly close gender gaps but are not output- or welfare-improving. (JEL E24, J16, J23, J31, J32, M51, O15)", "date": "2026-05-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20231107", "title_zh": "\u6027\u522b\u85aa\u916c\u5dee\u8ddd\uff1a\u5fae\u89c2\u6765\u6e90\u4e0e\u5b8f\u89c2\u5f71\u54cd", "abstract_zh": "\u5229\u7528\u6765\u81ea\u5df4\u897f\u7684\u96c7\u4e3b-\u5458\u5de5\u5173\u8054\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u5b58\u5728\u663e\u8457\u7684\u6027\u522b\u85aa\u916c\u5dee\u8ddd\uff0c\u8fd9\u4e00\u5dee\u8ddd\u4e3b\u8981\u5f52\u56e0\u4e8e\u5973\u6027\u5728\u85aa\u916c\u8f83\u4f4e\u7684\u96c7\u4e3b\u5904\u5de5\u4f5c\u3002\u4e3a\u4e86\u89e3\u91ca\u8fd9\u4e00\u73b0\u8c61\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5747\u8861\u641c\u5bfb\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u5305\u542b\u5185\u751f\u7684\u516c\u53f8\u85aa\u916c\u3001\u798f\u5229\u548c\u62db\u8058\u884c\u4e3a\u3002\u6211\u4eec\u4e3a\u6a21\u578b\u4e2d\u6240\u6709\u53c2\u6570\u7684\u8bc6\u522b\u63d0\u4f9b\u4e86\u6784\u9020\u6027\u8bc1\u660e\u3002\u4f30\u8ba1\u7684\u6a21\u578b\u8868\u660e\uff0c\u798f\u5229\u5bf9\u7537\u6027\u548c\u5973\u6027\u90fd\u5177\u6709\u91cd\u8981\u5f71\u54cd\uff0c\u4e14\u8865\u507f\u6027\u5dee\u5f02\u89e3\u91ca\u4e86\u6027\u522b\u85aa\u916c\u5dee\u8ddd\u7684\u4e00\u534a\u3002\u5e73\u7b49\u5bf9\u5f85\u653f\u7b56\u90e8\u5206\u7f29\u5c0f\u4e86\u6027\u522b\u85aa\u916c\u5dee\u8ddd\uff0c\u4f46\u5e76\u672a\u63d0\u5347\u4ea7\u51fa\u6216\u798f\u5229\u6c34\u5e73\u3002\uff08JEL E24, J16, J23, J31, J32, M51, O15\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240850", "journal": "AER", "title": "The Attention-Information Trade-Off", "authors": ["Marta Serra-Garcia"], "author_details": [{"name": "Marta Serra-Garcia", "affiliations": ["University of California, San Diego and CESifo (email: )"]}], "abstract": "How does information transmission change when it requires attracting the attention of receivers? This paper combines an experiment that varies freelance professionals\u2019 incentives to attract attention about scientific findings, with several online experiments that exogenously expose receivers to the content created. Attention incentives lead to significantly less information being transmitted, but not more factually inaccurate content. These incentives increase information demand and the knowledge of interested receivers. However, among the majority of receivers who do not demand more information, attention incentives lower knowledge and increase biases in beliefs, revealing a channel through which misperceptions can arise: missing information. (JEL C91, D83, D91)", "date": "2026-05-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240850", "title_zh": "\u6ce8\u610f\u529b\u4e0e\u4fe1\u606f\u7684\u6743\u8861", "abstract_zh": "\u5f53\u4fe1\u606f\u4f20\u9012\u9700\u8981\u5438\u5f15\u63a5\u6536\u8005\u7684\u6ce8\u610f\u529b\u65f6\uff0c\u4fe1\u606f\u4f20\u8f93\u4f1a\u53d1\u751f\u600e\u6837\u7684\u53d8\u5316\uff1f\u672c\u6587\u7ed3\u5408\u4e86\u4e00\u4e2a\u5b9e\u9a8c\uff0c\u8be5\u5b9e\u9a8c\u6539\u53d8\u4e86\u81ea\u7531\u804c\u4e1a\u8005\u5728\u79d1\u5b66\u53d1\u73b0\u65b9\u9762\u5438\u5f15\u6ce8\u610f\u529b\u7684\u6fc0\u52b1\uff0c\u4ee5\u53ca\u591a\u4e2a\u5728\u7ebf\u5b9e\u9a8c\uff0c\u8fd9\u4e9b\u5b9e\u9a8c\u5916\u751f\u5730\u4f7f\u63a5\u6536\u8005\u63a5\u89e6\u5230\u6240\u521b\u5efa\u7684\u5185\u5bb9\u3002\u6ce8\u610f\u529b\u6fc0\u52b1\u5bfc\u81f4\u4f20\u9012\u7684\u4fe1\u606f\u663e\u8457\u51cf\u5c11\uff0c\u4f46\u5e76\u672a\u589e\u52a0\u4e8b\u5b9e\u4e0a\u7684\u4e0d\u51c6\u786e\u5185\u5bb9\u3002\u8fd9\u4e9b\u6fc0\u52b1\u63d0\u9ad8\u4e86\u4fe1\u606f\u9700\u6c42\u4ee5\u53ca\u5bf9\u76f8\u5173\u4fe1\u606f\u611f\u5174\u8da3\u7684\u63a5\u6536\u8005\u7684\u77e5\u8bc6\u6c34\u5e73\u3002\u7136\u800c\uff0c\u5728\u5927\u591a\u6570\u4e0d\u4e3b\u52a8\u5bfb\u6c42\u66f4\u591a\u4fe1\u606f\u7684\u63a5\u6536\u8005\u4e2d\uff0c\u6ce8\u610f\u529b\u6fc0\u52b1\u964d\u4f4e\u4e86\u4ed6\u4eec\u7684\u77e5\u8bc6\u6c34\u5e73\u5e76\u589e\u52a0\u4e86\u4fe1\u5ff5\u504f\u89c1\uff0c\u63ed\u793a\u4e86\u8bef\u89e3\u53ef\u80fd\u4ea7\u751f\u7684\u4e00\u4e2a\u6e20\u9053\uff1a\u4fe1\u606f\u7f3a\u5931\u3002\uff08JEL C91\uff0cD83\uff0cD91\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240432", "journal": "AER", "title": "Effects of Parental Death on Labor Market Outcomes", "authors": ["Mathias Fj\u00e6llegaard Jensen", "Ning Zhang"], "author_details": [{"name": "Mathias Fj\u00e6llegaard Jensen", "affiliations": ["University of Oxford (email: )"]}, {"name": "Ning Zhang", "affiliations": ["The Chinese University of Hong Kong (email: )"]}], "abstract": "We use Danish administrative data to examine the effects of parental death on labor market outcomes. Leveraging the timing of sudden, first parental deaths and a matched-control difference-in-differences strategy, we find that men\u2019s earnings decline by 2 percent, while women\u2019s earnings decline by 3 percent following a parental death. Both women and men experience mental health deterioration, leading to increased use of psychological assistance and prescriptions for mental health conditions and opioids. Women with young children experience a comparatively larger earnings decline (around 4 percent) likely due to the loss of informal childcare. (JEL D91, I12, J13, J16, J31)", "date": "2026-05-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240432", "title_zh": "\u7236\u6bcd\u6b7b\u4ea1\u5bf9\u52b3\u52a8\u529b\u5e02\u573a\u7ed3\u679c\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u5229\u7528\u4e39\u9ea6\u7684\u884c\u653f\u6570\u636e\uff0c\u7814\u7a76\u7236\u6bcd\u6b7b\u4ea1\u5bf9\u52b3\u52a8\u529b\u5e02\u573a\u7ed3\u679c\u7684\u5f71\u54cd\u3002\u901a\u8fc7\u5229\u7528\u7a81\u53d1\u6027\u9996\u6b21\u7236\u6bcd\u6b7b\u4ea1\u7684\u65f6\u95f4\u70b9\uff0c\u5e76\u91c7\u7528\u5339\u914d\u5bf9\u7167\u7684\u53cc\u91cd\u5dee\u5206\u7b56\u7565\uff0c\u6211\u4eec\u53d1\u73b0\u7537\u6027\u6536\u5165\u4e0b\u964d2\u4e2a\u767e\u5206\u70b9\uff0c\u5973\u6027\u6536\u5165\u4e0b\u964d3\u4e2a\u767e\u5206\u70b9\u3002\u7537\u5973\u53cc\u65b9\u5747\u51fa\u73b0\u5fc3\u7406\u5065\u5eb7\u72b6\u51b5\u6076\u5316\uff0c\u5bfc\u81f4\u5fc3\u7406\u63f4\u52a9\u4f7f\u7528\u589e\u52a0\u4ee5\u53ca\u7cbe\u795e\u75be\u75c5\u548c\u963f\u7247\u7c7b\u836f\u7269\u5904\u65b9\u91cf\u4e0a\u5347\u3002\u6709\u5e74\u5e7c\u5b50\u5973\u7684\u5973\u6027\u6536\u5165\u4e0b\u964d\u5e45\u5ea6\u76f8\u5bf9\u66f4\u5927\uff08\u7ea64\u4e2a\u767e\u5206\u70b9\uff09\uff0c\u8fd9\u53ef\u80fd\u662f\u56e0\u4e3a\u5931\u53bb\u4e86\u975e\u6b63\u5f0f\u7684\u80b2\u513f\u7167\u62a4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20201088", "journal": "AER", "title": "Production and Financial Networks in Interplay", "authors": ["Kenan Huremovi\u0107", "Gabriel Jim\u00e9nez", "Enrique Moral-Benito", "Jos\u00e9-Luis Peydr\u00f3", "Fernando Vega-Redondo"], "author_details": [{"name": "Kenan Huremovi\u0107", "affiliations": ["IMT School for Advanced Studies Lucca (email: )"]}, {"name": "Gabriel Jim\u00e9nez", "affiliations": ["Banco de Espa\u00f1a (email: )"]}, {"name": "Enrique Moral-Benito", "affiliations": ["Banco de Espa\u00f1a (email: )"]}, {"name": "Jos\u00e9-Luis Peydr\u00f3", "affiliations": ["LUISS University, EIEF, CEPR (email: )"]}, {"name": "Fernando Vega-Redondo", "affiliations": ["Department of Economics, The Chinese University of Hong Kong (email: )"]}], "abstract": "We show that bank shocks to firms propagate along the production network with stronger upstream than downstream effects. Our identification relies on (i) administrative datasets from Spain covering supplier-customer transactions and bank loans, (ii) bank credit supply shocks from the global financial crisis, and (iii) a general equilibrium model of a production network with financial frictions, estimated structurally. We find network propagation amplifies the impact of bank shocks on GDP growth by nearly 50 percent. Moreover, bank shocks to firms\u2019 distant suppliers and customers contribute similarly to this aggregate effect as bank shocks to firms\u2019 direct customers and suppliers. (JEL D22, D85, E23, G01, G21, G32, L14)", "date": "2026-05-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20201088", "title_zh": "\u751f\u4ea7\u4e0e\u91d1\u878d\u7f51\u7edc\u7684\u76f8\u4e92\u4f5c\u7528", "abstract_zh": "\u6211\u4eec\u8bc1\u660e\uff0c\u94f6\u884c\u5bf9\u4f01\u4e1a\u7684\u51b2\u51fb\u4f1a\u6cbf\u7740\u751f\u4ea7\u7f51\u7edc\u4f20\u64ad\uff0c\u4e14\u4e0a\u6e38\u5f71\u54cd\u5f3a\u4e8e\u4e0b\u6e38\u5f71\u54cd\u3002\u6211\u4eec\u7684\u8bc6\u522b\u4f9d\u8d56\u4e8e\uff08i\uff09\u6765\u81ea\u897f\u73ed\u7259\u7684\u884c\u653f\u6570\u636e\uff0c\u6db5\u76d6\u4f9b\u5e94\u5546-\u5ba2\u6237\u4ea4\u6613\u548c\u94f6\u884c\u8d37\u6b3e\u4fe1\u606f\uff0c\uff08ii\uff09\u5168\u7403\u91d1\u878d\u5371\u673a\u671f\u95f4\u7684\u94f6\u884c\u4fe1\u8d37\u4f9b\u7ed9\u51b2\u51fb\uff0c\u4ee5\u53ca\uff08iii\uff09\u4e00\u4e2a\u5305\u542b\u91d1\u878d\u6469\u64e6\u7684\u751f\u4ea7\u7f51\u7edc\u4e00\u822c\u5747\u8861\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u8fdb\u884c\u4e86\u7ed3\u6784\u4f30\u8ba1\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u7f51\u7edc\u4f20\u64ad\u5c06\u94f6\u884c\u51b2\u51fb\u5bf9GDP\u589e\u957f\u7684\u5f71\u54cd\u653e\u5927\u4e86\u8fd150\u4e2a\u767e\u5206\u70b9\u3002\u6b64\u5916\uff0c\u5bf9\u4f01\u4e1a\u548c\u5176\u8fdc\u7aef\u4f9b\u5e94\u5546\u53ca\u5ba2\u6237\u7684\u94f6\u884c\u51b2\u51fb\uff0c\u5bf9\u6574\u4f53\u5f71\u54cd\u7684\u8d21\u732e\u4e0e\u5bf9\u76f4\u63a5\u4f9b\u5e94\u5546\u548c\u5ba2\u6237\u7684\u94f6\u884c\u51b2\u51fb\u76f8\u5f53\u3002\uff08JEL D22, D85, E23, G01, G21, G32, L14\uff09", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc", "\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1257/aer.20241127", "journal": "AER", "title": "Internal versus Institutional Barriers to Gender Equality: Evidence from British Politics", "authors": ["Noor Kumar", "Uyseok Lee", "Matt Lowe", "Olaitan Ogunnote"], "author_details": [{"name": "Noor Kumar", "affiliations": ["Princeton (email: )"]}, {"name": "Uyseok Lee", "affiliations": ["University of British Columbia (email: )"]}, {"name": "Matt Lowe", "affiliations": ["University of British Columbia (email: )"]}, {"name": "Olaitan Ogunnote", "affiliations": ["University of British Columbia (email: )"]}], "abstract": "Weekly lotteries determine which politicians ask the UK prime minister a question in front of a male-dominated, noisy chamber. Lottery winners receive 4 percent higher vote margin in the next election, but women are 12 percent less likely to submit questions than same-cohort men. The gender gap does not close with lottery-induced experience asking a question, but it closes after a format change, with questions asked to a smaller, quieter audience. The switch differentially draws in women with quieter voices. Our findings support institutional change, rather than experience, as a response to gender gaps in adversarial settings like the UK Parliament. (JEL D44, D72, J16)", "date": "2026-05-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20241127", "title_zh": "\u5185\u90e8\u969c\u788d\u4e0e\u5236\u5ea6\u969c\u788d\u5bf9\u6027\u522b\u5e73\u7b49\u7684\u5236\u7ea6\uff1a\u6765\u81ea\u82f1\u56fd\u653f\u6cbb\u7684\u8bc1\u636e", "abstract_zh": "\u6bcf\u5468\u5f69\u7968\u51b3\u5b9a\u54ea\u4e9b\u653f\u6cbb\u4eba\u7269\u5728\u7537\u6027\u4e3b\u5bfc\u4e14\u5608\u6742\u7684\u8bae\u4f1a\u5927\u5385\u4e2d\u5411\u82f1\u56fd\u9996\u76f8\u63d0\u95ee\u3002\u4e2d\u5f69\u7968\u7684\u5019\u9009\u4eba\u4e0b\u4e00\u6b21\u9009\u4e3e\u4e2d\u7684\u9009\u7968\u4f18\u52bf\u9ad8\u51fa4%\uff0c\u4f46\u5973\u6027\u63d0\u51fa\u95ee\u9898\u7684\u6982\u7387\u6bd4\u540c\u5c4a\u7537\u6027\u4f4e12%\u3002\u5373\u4f7f\u901a\u8fc7\u5f69\u7968\u673a\u5236\u83b7\u5f97\u63d0\u95ee\u7ecf\u9a8c\uff0c\u6027\u522b\u5dee\u8ddd\u4e5f\u5e76\u672a\u7f29\u5c0f\uff0c\u4f46\u5728\u63d0\u95ee\u5f62\u5f0f\u6539\u53d8\u540e\uff0c\u5373\u5728\u8f83\u5c0f\u4e14\u5b89\u9759\u7684\u542c\u4f17\u73af\u5883\u4e2d\u63d0\u95ee\uff0c\u6027\u522b\u5dee\u8ddd\u5f97\u4ee5\u7f29\u5c0f\u3002\u8fd9\u4e00\u53d8\u5316\u7279\u522b\u5438\u5f15\u4e86\u58f0\u97f3\u8f83\u8f7b\u7684\u5973\u6027\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u652f\u6301\u5728\u5bf9\u6297\u6027\u73af\u5883\u4e2d\uff08\u5982\u82f1\u56fd\u8bae\u4f1a\uff09\u89e3\u51b3\u6027\u522b\u5dee\u8ddd\u5e94\u4f9d\u9760\u5236\u5ea6\u53d8\u9769\uff0c\u800c\u975e\u4e2a\u4eba\u7ecf\u9a8c\u3002\uff08JEL D44, D72, J16\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20220865", "journal": "AER", "title": "Labor Market Competition and the Assimilation of Immigrants", "authors": ["Christoph Albert", "Albrecht Glitz", "Joan Llull"], "author_details": [{"name": "Christoph Albert", "affiliations": ["University of Turin and Collegio Carlo Alberto (email: )"]}, {"name": "Albrecht Glitz", "affiliations": ["Universitat Pompeu Fabra, Barcelona School of Economics, IPEG and ROCKWOOL Foundation Berlin (email: )"]}, {"name": "Joan Llull", "affiliations": ["(Institute of Economic Analysis (IAE-CSIC) and Barcelona School of Economics (email: )"]}], "abstract": "This paper shows that the wage assimilation of immigrants is the result of the intricate interplay between individual skill accumulation and dynamic labor market equilibrium effects. When immigrants and natives are imperfect substitutes, rising immigrant inflows widen the wage gap between them. Using a production function framework in which workers supply both general and host-country-specific skills, we show that this labor market competition channel explains about one-fifth of the large increase in the average immigrant\u2013native wage gap across arrival cohorts in the United States since the 1960s. The results further reveal substantial heterogeneity across different groups of immigrants. (JEL J22, J23, J24, J31, J61, K37, O33)", "date": "2026-05-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20220865", "title_zh": "\u52b3\u52a8\u529b\u5e02\u573a\u7ade\u4e89\u4e0e\u79fb\u6c11\u7684\u540c\u5316", "abstract_zh": "\u672c\u6587\u8868\u660e\uff0c\u79fb\u6c11\u7684\u5de5\u8d44\u540c\u5316\u662f\u4e2a\u4eba\u6280\u80fd\u79ef\u7d2f\u4e0e\u52a8\u6001\u52b3\u52a8\u529b\u5e02\u573a\u5747\u8861\u6548\u5e94\u4e4b\u95f4\u590d\u6742\u76f8\u4e92\u4f5c\u7528\u7684\u7ed3\u679c\u3002\u5f53\u79fb\u6c11\u4e0e\u672c\u5730\u5c45\u6c11\u4e0d\u662f\u5b8c\u5168\u66ff\u4ee3\u54c1\u65f6\uff0c\u79fb\u6c11\u6d41\u5165\u7684\u589e\u52a0\u4f1a\u6269\u5927\u4e24\u8005\u4e4b\u95f4\u7684\u5de5\u8d44\u5dee\u8ddd\u3002\u5728\u4e00\u79cd\u751f\u4ea7\u51fd\u6570\u6846\u67b6\u4e0b\uff0c\u5de5\u4eba\u540c\u65f6\u63d0\u4f9b\u901a\u7528\u6280\u80fd\u548c\u5bbf\u56fd\u7279\u5b9a\u6280\u80fd\uff0c\u6211\u4eec\u8bc1\u660e\uff0c\u8fd9\u4e00\u52b3\u52a8\u529b\u5e02\u573a\u7ade\u4e89\u6e20\u9053\u89e3\u91ca\u4e86\u81ea20\u4e16\u7eaa60\u5e74\u4ee3\u4ee5\u6765\u7f8e\u56fd\u5404\u79fb\u6c11\u5230\u8fbe\u7fa4\u4f53\u95f4\u5e73\u5747\u79fb\u6c11-\u672c\u5730\u5c45\u6c11\u5de5\u8d44\u5dee\u8ddd\u5927\u5e45\u4e0a\u5347\u7684\u7ea6\u4e94\u5206\u4e4b\u4e00\u3002\u7814\u7a76\u7ed3\u679c\u8fd8\u63ed\u793a\u4e86\u4e0d\u540c\u79fb\u6c11\u7fa4\u4f53\u4e4b\u95f4\u663e\u8457\u7684\u5f02\u8d28\u6027\u3002\uff08JEL J22, J23, J24, J31, J61, K37, O33\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20231016", "journal": "AER", "title": "Conservation Priorities and Environmental Offsets: Markets for Florida Wetlands", "authors": ["Daniel Aronoff", "Will Rafey"], "author_details": [{"name": "Daniel Aronoff", "affiliations": ["MIT Department of Economics and MIT Laboratory for Economic Analysis and Design ()"]}, {"name": "Will Rafey", "affiliations": ["UCLA Department of Economics and NBER ()"]}], "abstract": "We introduce an empirical framework for valuing markets in environmental offsets. Using newly collected data on wetland conservation and offsets, we apply this framework to evaluate a set of decentralized markets in Florida, where land developers purchase offsets from long-lived producers who restore wetlands over time. We find offsets led to substantial private gains from trade, creating $2.4 billion of net surplus from 1995 to 2020 relative to direct conservation. Offset trading also generated new hydrological externalities. A locally differentiated Pigouvian tax would have prevented $1.6 billion of new flood damage while preserving more than two-thirds of the private gains from trade. (JEL D47, D62, H23, Q24, Q54, Q57, R14)", "date": "2026-05-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20231016", "title_zh": "\u4fdd\u62a4\u4f18\u5148\u7ea7\u4e0e\u73af\u5883\u8865\u507f\uff1a\u4f5b\u7f57\u91cc\u8fbe\u6e7f\u5730\u5e02\u573a\u7684\u7814\u7a76", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u4e2a\u7528\u4e8e\u8bc4\u4f30\u73af\u5883\u8865\u507f\u5e02\u573a\u4ef7\u503c\u7684\u5b9e\u8bc1\u6846\u67b6\u3002\u5229\u7528\u65b0\u6536\u96c6\u7684\u6e7f\u5730\u4fdd\u62a4\u4e0e\u8865\u507f\u6570\u636e\uff0c\u6211\u4eec\u5c06\u8be5\u6846\u67b6\u5e94\u7528\u4e8e\u4f5b\u7f57\u91cc\u8fbe\u5dde\u7684\u4e00\u7cfb\u5217\u5206\u6563\u5f0f\u5e02\u573a\uff0c\u5176\u4e2d\u571f\u5730\u5f00\u53d1\u5546\u4ece\u957f\u671f\u6e7f\u5730\u6062\u590d\u751f\u4ea7\u8005\u5904\u8d2d\u4e70\u8865\u507f\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u8865\u507f\u673a\u5236\u5e26\u6765\u4e86\u663e\u8457\u7684\u79c1\u4eba\u4ea4\u6613\u6536\u76ca\uff0c1995\u5e74\u81f32020\u5e74\u95f4\u76f8\u5bf9\u4e8e\u76f4\u63a5\u4fdd\u62a4\uff0c\u521b\u9020\u4e8624\u4ebf\u7f8e\u5143\u7684\u51c0\u6536\u76ca\u3002\u8865\u507f\u4ea4\u6613\u8fd8\u4ea7\u751f\u4e86\u65b0\u7684\u6c34\u6587\u5916\u90e8\u6027\u3002\u4e00\u4e2a\u672c\u5730\u5dee\u5f02\u5316\u5e87\u53e4\u7a0e\u53ef\u4ee5\u9632\u6b6216\u4ebf\u7f8e\u5143\u7684\u65b0\u6d2a\u6c34\u635f\u5bb3\uff0c\u540c\u65f6\u4fdd\u7559\u8d85\u8fc7\u4e09\u5206\u4e4b\u4e8c\u7684\u79c1\u4eba\u4ea4\u6613\u6536\u76ca\u3002\uff08JEL D47, D62, H23, Q24, Q54, Q57, R14\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240785", "journal": "AER", "title": "The Effect of Field Training Officers on Police Use of Force", "authors": ["Chandon Adger", "Matthew B. Ross", "CarlyWill Sloan"], "author_details": [{"name": "Chandon Adger", "affiliations": ["Texas A&M University (email: )"]}, {"name": "Matthew B. Ross", "affiliations": ["Northeastern University (email: )"]}, {"name": "CarlyWill Sloan", "affiliations": ["United States Military Academy at West Point (email: )"]}], "abstract": "The influence of on-the-job training and supervisors, especially in high-stakes settings like policing, is poorly understood. Examining a central behavior in the debate surrounding police reform, we investigate the impact of a field training officer (FTO) on a recruit\u2019s use of force. Leveraging a setting with conditional as-good-as-random assignment, we demonstrate a causal link between FTO and recruit use of force. A 1 standard deviation increase in FTO force propensity leads to a 14 to 18 percent rise in recruit force, persisting for at least two years. This underscores field training\u2019s impact and reveals a promising avenue for reform. (JEL D91, J24, J45, K42, M53)", "date": "2026-05-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240785", "title_zh": "\u73b0\u573a\u8bad\u7ec3\u5b98\u5bf9\u8b66\u5bdf\u4f7f\u7528\u6b66\u529b\u7684\u5f71\u54cd", "abstract_zh": "\u5728\u804c\u57f9\u8bad\u548c\u4e0a\u7ea7\u6307\u5bfc\uff0c\u5c24\u5176\u662f\u5728\u9ad8\u98ce\u9669\u9886\u57df\u5982\u8b66\u52a1\u5de5\u4f5c\u4e2d\u7684\u5f71\u54cd\uff0c\u76ee\u524d\u7406\u89e3\u751a\u5c11\u3002\u5728\u5173\u4e8e\u8b66\u5bdf\u6539\u9769\u7684\u4e89\u8bba\u4e2d\uff0c\u6211\u4eec\u8003\u5bdf\u4e86\u73b0\u573a\u8bad\u7ec3\u5b98\uff08FTO\uff09\u5bf9\u65b0\u8b66\u5458\u4f7f\u7528\u6b66\u529b\u884c\u4e3a\u7684\u5f71\u54cd\u3002\u5229\u7528\u4e00\u4e2a\u5177\u6709\u6761\u4ef6\u8fd1\u4f3c\u968f\u673a\u5206\u914d\u7684\u73af\u5883\uff0c\u6211\u4eec\u8bc1\u660e\u4e86\u73b0\u573a\u8bad\u7ec3\u5b98\u4e0e\u65b0\u8b66\u5458\u4f7f\u7528\u6b66\u529b\u4e4b\u95f4\u5b58\u5728\u56e0\u679c\u5173\u7cfb\u3002\u73b0\u573a\u8bad\u7ec3\u5b98\u4f7f\u7528\u6b66\u529b\u503e\u5411\u6bcf\u589e\u52a0\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u65b0\u8b66\u5458\u4f7f\u7528\u6b66\u529b\u7684\u6bd4\u4f8b\u5c06\u4e0a\u534714\u81f318\u4e2a\u767e\u5206\u70b9\uff0c\u4e14\u8fd9\u79cd\u5f71\u54cd\u6301\u7eed\u81f3\u5c11\u4e24\u5e74\u3002\u8fd9\u51f8\u663e\u4e86\u73b0\u573a\u57f9\u8bad\u7684\u91cd\u8981\u6027\uff0c\u5e76\u63ed\u793a\u4e86\u6539\u9769\u7684\u4e00\u4e2a\u6709\u524d\u666f\u7684\u9014\u5f84\u3002\uff08JEL D91, J24, J45, K42, M53\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240919", "journal": "AER", "title": "Efficiency Criteria, Income Taxation, and Heterogeneous Elasticities", "authors": ["John Sturm Becko", "Andr\u00e9 Sztutman"], "author_details": [{"name": "John Sturm Becko", "affiliations": ["Princeton (email: )"]}, {"name": "Andr\u00e9 Sztutman", "affiliations": ["Carnegie Mellon (email: )"]}], "abstract": "A common interpretation of Pareto-efficient policies is that, for some cardinal utility representations of preferences, they maximize utilitarian welfare. We show in the context of income taxation that such cardinalizations are often extreme, requiring unbounded curvature of utility with respect to consumption. Taxes can be justified as utilitarian without these extreme cardinalizations if and only if revenues are decreasing and concave in a class of narrowly targeted tax cuts. We reformulate this condition as a sufficient-statistics test. The test fails whenever elasticities of taxable income are too heterogeneous within some income level, as we argue is empirically likely. (JEL D81, H21, H23, H24, J22, J31)", "date": "2026-05-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240919", "title_zh": "\u6548\u7387\u6807\u51c6\u3001\u6536\u5165\u7a0e\u6536\u4e0e\u5f02\u8d28\u5f39\u6027", "abstract_zh": "\u5bf9\u5e15\u7d2f\u6258\u6709\u6548\u653f\u7b56\u7684\u5e38\u89c1\u89e3\u91ca\u662f\uff0c\u5bf9\u4e8e\u67d0\u4e9b\u6548\u7528\u7684\u57fa\u6570\u8868\u793a\uff0c\u8fd9\u4e9b\u653f\u7b56\u80fd\u591f\u6700\u5927\u5316\u529f\u5229\u4e3b\u4e49\u798f\u5229\u3002\u6211\u4eec\u5728\u6536\u5165\u7a0e\u6536\u7684\u80cc\u666f\u4e0b\u8868\u660e\uff0c\u8fd9\u6837\u7684\u57fa\u6570\u8868\u793a\u901a\u5e38\u6781\u4e3a\u6781\u7aef\uff0c\u9700\u8981\u6548\u7528\u5bf9\u6d88\u8d39\u7684\u66f2\u7387\u65e0\u754c\u3002\u5982\u679c\u7a0e\u6536\u6536\u5165\u5728\u67d0\u4e00\u7c7b\u7cbe\u51c6\u9488\u5bf9\u7684\u51cf\u7a0e\u63aa\u65bd\u4e2d\u662f\u9012\u51cf\u4e14\u51f9\u7684\uff0c\u5219\u65e0\u9700\u8fd9\u4e9b\u6781\u7aef\u57fa\u6570\u8868\u793a\u5373\u53ef\u4ece\u529f\u5229\u4e3b\u4e49\u89d2\u5ea6\u8bc1\u660e\u7a0e\u6536\u7684\u5408\u7406\u6027\u3002\u6211\u4eec\u5c06\u8fd9\u4e00\u6761\u4ef6\u91cd\u65b0\u8868\u8ff0\u4e3a\u4e00\u4e2a\u5145\u5206\u7edf\u8ba1\u91cf\u68c0\u9a8c\u3002\u5f53\u67d0\u4e9b\u6536\u5165\u6c34\u5e73\u5185\u53ef\u7a0e\u6536\u5165\u7684\u5f39\u6027\u8fc7\u4e8e\u5f02\u8d28\u65f6\uff0c\u8be5\u68c0\u9a8c\u5c06\u5931\u8d25\uff0c\u800c\u6211\u4eec\u8ba4\u4e3a\u8fd9\u79cd\u60c5\u51b5\u5728\u7ecf\u9a8c\u4e0a\u662f\u53ef\u80fd\u53d1\u751f\u7684\u3002\uff08JEL D81, H21, H23, H24, J22, J31\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20211491", "journal": "AER", "title": "Social Preferences over Ordinal Outcomes", "authors": ["Sandro Ambuehl", "B. Douglas Bernheim"], "author_details": [{"name": "Sandro Ambuehl", "affiliations": ["Department of Economics and UBS Center for Economics in Society, University of Zurich (email: )"]}, {"name": "B. Douglas Bernheim", "affiliations": ["Department of Economics, Stanford University (email: )"]}], "abstract": "We study social preferences in settings where someone who chooses on behalf of others knows how those individuals rank the available options but may lack cardinal information concerning those comparisons. Contrary to majoritarian principles, most people place more weight on preventing least preferred outcomes for others than on enabling most preferred outcomes. Ranks matter both intrinsically and because they provide a basis for inferring cardinal utility. Ordinal aggregation principles are stable across domains and countries with divergent political traditions. Designing attractive social choice mechanisms is challenging in practice partly because aggregation principles that make manipulation difficult yield outcomes people consider normatively unappealing. (JEL C91, D71, D72)", "date": "2026-05-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20211491", "title_zh": "\u5bf9\u5e8f\u6570\u7ed3\u679c\u7684\u793e\u4f1a\u504f\u597d", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5728\u6709\u4eba\u4ee3\u8868\u4ed6\u4eba\u505a\u51fa\u9009\u62e9\u7684\u60c5\u51b5\u4e0b\uff0c\u5f53\u8be5\u4eba\u77e5\u9053\u4ed6\u4eba\u5bf9\u53ef\u9009\u65b9\u6848\u7684\u6392\u5e8f\u4f46\u53ef\u80fd\u7f3a\u4e4f\u5173\u4e8e\u8fd9\u4e9b\u6bd4\u8f83\u7684\u57fa\u6570\u4fe1\u606f\u65f6\u7684\u793e\u4f1a\u504f\u597d\u3002\u4e0e\u591a\u6570\u539f\u5219\u76f8\u53cd\uff0c\u5927\u591a\u6570\u4eba\u66f4\u91cd\u89c6\u9632\u6b62\u4ed6\u4eba\u6700\u4e0d\u559c\u597d\u7684\u7ed3\u679c\uff0c\u800c\u975e\u4fc3\u8fdb\u4ed6\u4eba\u6700\u559c\u597d\u7684\u7ed3\u679c\u3002\u6392\u5e8f\u672c\u8eab\u5177\u6709\u91cd\u8981\u6027\uff0c\u540c\u65f6\u4e5f\u56e0\u4e3a\u63d0\u4f9b\u4e86\u63a8\u65ad\u57fa\u6570\u6548\u7528\u7684\u57fa\u7840\u3002\u5e8f\u6570\u805a\u5408\u539f\u5219\u5728\u4e0d\u540c\u9886\u57df\u548c\u653f\u6cbb\u4f20\u7edf\u7684\u56fd\u5bb6\u4e2d\u90fd\u8868\u73b0\u51fa\u7a33\u5b9a\u6027\u3002\u5728\u5b9e\u8df5\u4e2d\u8bbe\u8ba1\u4ee4\u4eba\u6ee1\u610f\u7684\u793e\u4f1a\u9009\u62e9\u673a\u5236\u5177\u6709\u6311\u6218\u6027\uff0c\u90e8\u5206\u539f\u56e0\u5728\u4e8e\u90a3\u4e9b\u4f7f\u64cd\u7eb5\u56f0\u96be\u7684\u805a\u5408\u539f\u5219\u6240\u4ea7\u751f\u7684\u7ed3\u679c\u5728\u89c4\u8303\u4e0a\u5e76\u4e0d\u4ee4\u4eba\u6ee1\u610f\u3002\uff08JEL C91\uff0cD71\uff0cD72\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag036", "journal": "REStud", "title": "Identification and Estimation of Dynamic Random Coefficient Models", "authors": ["Wooyong Lee"], "author_details": [{"name": "Wooyong Lee", "affiliations": ["University of Technology Sydney ,"]}], "abstract": "Abstract I study linear panel data models with predetermined regressors (such as lagged dependent variables) where coefficients are individual-specific, allowing for heterogeneity in the effects of the regressors on the dependent variable. I show that the model is not point-identified in a short panel context but rather partially identified, and I characterize the identified sets for the mean, variance, and CDF of the coefficient distribution. This characterization is general, accommodating discrete, continuous, and unbounded data, and it leads to computationally tractable estimation and inference procedures. I apply the method to study lifecycle earnings dynamics among U.S. households using the Panel Study of Income Dynamics (PSID) dataset. The results suggest the presence of unobserved heterogeneity in earnings persistence, implying that households face varying levels of earnings risk which, in turn, contribute to heterogeneity in their consumption and savings behaviours.", "date": "2026-04-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag036", "title_zh": "\u52a8\u6001\u968f\u673a\u7cfb\u6570\u6a21\u578b\u7684\u8bc6\u522b\u4e0e\u4f30\u8ba1", "abstract_zh": "\u6211\u7814\u7a76\u5305\u542b\u9884\u5b9a\u56de\u5f52\u53d8\u91cf\uff08\u5982\u6ede\u540e\u56e0\u53d8\u91cf\uff09\u7684\u7ebf\u6027\u9762\u677f\u6570\u636e\u6a21\u578b\uff0c\u5176\u4e2d\u7cfb\u6570\u662f\u4e2a\u4f53\u7279\u5b9a\u7684\uff0c\u5141\u8bb8\u56de\u5f52\u53d8\u91cf\u5bf9\u56e0\u53d8\u91cf\u7684\u5f71\u54cd\u5b58\u5728\u5f02\u8d28\u6027\u3002\u6211\u8bc1\u660e\u5728\u77ed\u9762\u677f\u60c5\u5883\u4e0b\uff0c\u8be5\u6a21\u578b\u5e76\u975e\u70b9\u8bc6\u522b\uff0c\u800c\u662f\u90e8\u5206\u8bc6\u522b\uff0c\u5e76\u5bf9\u7cfb\u6570\u5206\u5e03\u7684\u5747\u503c\u3001\u65b9\u5dee\u548c\u7d2f\u79ef\u5206\u5e03\u51fd\u6570\uff08CDF\uff09\u7684\u8bc6\u522b\u96c6\u8fdb\u884c\u4e86\u523b\u753b\u3002\u8fd9\u4e00\u523b\u753b\u5177\u6709\u666e\u904d\u6027\uff0c\u9002\u7528\u4e8e\u79bb\u6563\u3001\u8fde\u7eed\u53ca\u65e0\u754c\u6570\u636e\uff0c\u5e76\u7531\u6b64\u5bfc\u51fa\u8ba1\u7b97\u4e0a\u53ef\u884c\u7684\u4f30\u8ba1\u4e0e\u63a8\u65ad\u7a0b\u5e8f\u3002\u6211\u5c06\u8be5\u65b9\u6cd5\u5e94\u7528\u4e8e\u5229\u7528\u7f8e\u56fd\u5bb6\u5ead\u6536\u5165\u52a8\u6001\u9762\u677f\u7814\u7a76\uff08PSID\uff09\u6570\u636e\u7814\u7a76\u5bb6\u5ead\u751f\u547d\u5468\u671f\u6536\u5165\u52a8\u6001\u3002\u7ed3\u679c\u8868\u660e\uff0c\u6536\u5165\u6301\u7eed\u6027\u4e2d\u5b58\u5728\u672a\u89c2\u6d4b\u5230\u7684\u5f02\u8d28\u6027\uff0c\u610f\u5473\u7740\u5bb6\u5ead\u9762\u4e34\u4e0d\u540c\u6c34\u5e73\u7684\u6536\u5165\u98ce\u9669\uff0c\u800c\u8fd9\u8fdb\u4e00\u6b65\u5bfc\u81f4\u4e86\u5176\u6d88\u8d39\u548c\u50a8\u84c4\u884c\u4e3a\u7684\u5dee\u5f02\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag034", "journal": "REStud", "title": "Local Projection-Based Inference under General Conditions", "authors": ["Ke-Li Xu"], "author_details": [{"name": "Ke-Li Xu", "affiliations": ["Department of Economics, Indiana University , Bloomington ,"]}], "abstract": "Abstract This article develops the uniform asymptotic theory for local projection (LP) regression when the true lag order of the model is unknown and potentially infinite. The theory allows for varying degrees of persistence in the data, growing response horizons, and general conditionally heteroskedastic martingale-difference shocks. Based on the theory, we make two main contributions. First, we show that LPs can achieve semiparametric efficiency at a given horizon under classical assumptions on the data, provided that the controlled lag order diverges. Thus, the commonly perceived efficiency loss of LPs can become asymptotically negligible with many controls. Second, we propose LP-based inference procedures for (level and cumulated) impulse responses that possess robustness properties not shared by existing methods. Inference methods using two distinct standard errors are considered. The uniform validity for the first method depends on a zero fourth-order cumulant condition on shocks, while that of the second holds more generally for conditionally heteroskedastic martingale-difference shocks. We propose a bootstrap procedure that improves finite-sample performance and extend the standard error construction to structural responses.", "date": "2026-04-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag034", "title_zh": "\u5728\u4e00\u822c\u6761\u4ef6\u4e0b\u57fa\u4e8e\u5c40\u90e8\u6295\u5f71\u7684\u63a8\u65ad", "abstract_zh": "\u672c\u6587\u5728\u771f\u5b9e\u6ede\u540e\u9636\u6570\u672a\u77e5\u4e14\u53ef\u80fd\u4e3a\u65e0\u7a77\u65f6\uff0c\u53d1\u5c55\u4e86\u5c40\u90e8\u6295\u5f71\uff08LP\uff09\u56de\u5f52\u7684\u7edf\u4e00\u6e10\u8fd1\u7406\u8bba\u3002\u8be5\u7406\u8bba\u5141\u8bb8\u6570\u636e\u4e2d\u5b58\u5728\u4e0d\u540c\u7a0b\u5ea6\u7684\u6301\u7eed\u6027\u3001\u54cd\u5e94\u65f6\u95f4\u8303\u56f4\u7684\u6269\u5c55\uff0c\u4ee5\u53ca\u4e00\u822c\u6761\u4ef6\u5f02\u65b9\u5dee\u7684\u9785\u5dee\u51b2\u51fb\u3002\u57fa\u4e8e\u8be5\u7406\u8bba\uff0c\u672c\u6587\u505a\u51fa\u4e24\u9879\u4e3b\u8981\u8d21\u732e\u3002\u9996\u5148\uff0c\u6211\u4eec\u5728\u7ecf\u5178\u6570\u636e\u5047\u8bbe\u4e0b\u8bc1\u660e\uff0c\u5f53\u63a7\u5236\u7684\u6ede\u540e\u9636\u6570\u53d1\u6563\u65f6\uff0c\u5c40\u90e8\u6295\u5f71\u53ef\u4ee5\u5728\u7ed9\u5b9a\u65f6\u95f4\u8303\u56f4\u5185\u5b9e\u73b0\u534a\u53c2\u6570\u6548\u7387\uff0c\u56e0\u6b64\u4eba\u4eec\u666e\u904d\u8ba4\u4e3a\u7684\u5c40\u90e8\u6295\u5f71\u6548\u7387\u635f\u5931\uff0c\u968f\u7740\u63a7\u5236\u53d8\u91cf\u7684\u589e\u591a\u53ef\u4ee5\u6e10\u8fd1\u5730\u53d8\u5f97\u53ef\u4ee5\u5ffd\u7565\u3002\u5176\u6b21\uff0c\u6211\u4eec\u63d0\u51fa\u4e86\u9002\u7528\u4e8e\uff08\u6c34\u5e73\u548c\u7d2f\u79ef\uff09\u51b2\u51fb\u54cd\u5e94\u7684\u57fa\u4e8e\u5c40\u90e8\u6295\u5f71\u7684\u63a8\u65ad\u65b9\u6cd5\uff0c\u8fd9\u4e9b\u65b9\u6cd5\u5177\u5907\u73b0\u6709\u65b9\u6cd5\u6240\u4e0d\u5177\u5907\u7684\u7a33\u5065\u6027\u3002\u8003\u8651\u4e86\u4e24\u79cd\u4e0d\u540c\u7684\u6807\u51c6\u8bef\u63a8\u65ad\u65b9\u6cd5\uff1a\u7b2c\u4e00\u79cd\u65b9\u6cd5\u7684\u7edf\u4e00\u6709\u6548\u6027\u4f9d\u8d56\u4e8e\u51b2\u51fb\u7684\u56db\u9636\u7d2f\u79ef\u77e9\u4e3a\u96f6\u7684\u6761\u4ef6\uff0c\u800c\u7b2c\u4e8c\u79cd\u65b9\u6cd5\u5728\u66f4\u4e00\u822c\u6761\u4ef6\u4e0b\u5bf9\u6761\u4ef6\u5f02\u65b9\u5dee\u7684\u9785\u5dee\u51b2\u51fb\u6709\u6548\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u81ea\u52a9\u6cd5\u4ee5\u6539\u5584\u5c0f\u6837\u672c\u8868\u73b0\uff0c\u5e76\u5c06\u6807\u51c6\u8bef\u7684\u6784\u9020\u6269\u5c55\u81f3\u7ed3\u6784\u54cd\u5e94\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102919", "journal": "JFQA", "title": "Do Product Market Threats Discipline Corporate Misconduct?", "authors": ["Jie Chen", "Xunhua Su", "Xuan Tian", "Bin Xu", "Xiaoyu Zhang"], "author_details": [{"name": "Jie Chen", "affiliations": ["University of Leeds"]}, {"name": "Xunhua Su", "affiliations": ["Norwegian School of Economics"]}, {"name": "Xuan Tian", "affiliations": ["Peking University"]}, {"name": "Bin Xu", "affiliations": ["University of Reading"]}, {"name": "Xiaoyu Zhang", "affiliations": ["Vrije Universiteit Amsterdam"]}], "abstract": "Abstract We examine the efficacy of product market discipline as a deterrent to corporate misconduct. Firms that are subject to greater competitive threats in the product market are less likely to commit violations and pay lower penalties. Stakeholders react negatively to various types of violations, with product market competition amplifying these stakeholder reactions. In response, firms under competitive pressure are more likely to incorporate ESG-related incentives into executive compensation, demonstrate better worker safety practices, invest in green innovation, and use credible auditors. Our findings suggest that product market competition deters misconduct by increasing the expected costs associated with violations.", "date": "2026-04-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102919", "title_zh": "\u4ea7\u54c1\u5e02\u573a\u7ade\u4e89\u662f\u5426\u80fd\u7ea6\u675f\u4f01\u4e1a\u4e0d\u5f53\u884c\u4e3a\uff1f", "abstract_zh": "\u6211\u4eec\u8003\u5bdf\u4e86\u4ea7\u54c1\u5e02\u573a\u7ade\u4e89\u5bf9\u904f\u5236\u4f01\u4e1a\u4e0d\u5f53\u884c\u4e3a\u7684\u6709\u6548\u6027\u3002\u5728\u4ea7\u54c1\u5e02\u573a\u4e0a\u9762\u4e34\u66f4\u5927\u7ade\u4e89\u5a01\u80c1\u7684\u4f01\u4e1a\uff0c\u66f4\u4e0d\u53ef\u80fd\u53d1\u751f\u8fdd\u89c4\u884c\u4e3a\uff0c\u4e14\u6240\u652f\u4ed8\u7684\u7f5a\u6b3e\u4e5f\u66f4\u4f4e\u3002\u5404\u5229\u76ca\u76f8\u5173\u65b9\u5bf9\u4e0d\u540c\u7c7b\u578b\u7684\u8fdd\u89c4\u884c\u4e3a\u5747\u8868\u73b0\u51fa\u8d1f\u9762\u53cd\u5e94\uff0c\u800c\u4ea7\u54c1\u5e02\u573a\u7ade\u4e89\u4f1a\u52a0\u5267\u8fd9\u79cd\u53cd\u5e94\u3002\u56e0\u6b64\uff0c\u9762\u4e34\u7ade\u4e89\u538b\u529b\u7684\u4f01\u4e1a\u66f4\u6709\u53ef\u80fd\u5c06ESG\u76f8\u5173\u6fc0\u52b1\u7eb3\u5165\u9ad8\u7ba1\u85aa\u916c\uff0c\u6539\u5584\u5458\u5de5\u5b89\u5168\u63aa\u65bd\uff0c\u6295\u8d44\u7eff\u8272\u521b\u65b0\uff0c\u5e76\u8058\u7528\u6709\u4fe1\u8a89\u7684\u5ba1\u8ba1\u673a\u6784\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u4ea7\u54c1\u5e02\u573a\u7ade\u4e89\u901a\u8fc7\u63d0\u9ad8\u8fdd\u89c4\u884c\u4e3a\u7684\u9884\u671f\u6210\u672c\u6765\u6291\u5236\u4e0d\u5f53\u884c\u4e3a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag046", "journal": "RFS", "title": "The Cost of Regulatory Compliance in the United States", "authors": ["Francesco Trebbi", "Miao Ben Zhang", "Michael Simkovic"], "author_details": [{"name": "Francesco Trebbi", "affiliations": ["University of California Berkeley Haas School of Business, CEPR, and NBER ,"]}, {"name": "Miao Ben Zhang", "affiliations": ["University of Southern California Marshall School of Business ,"]}, {"name": "Michael Simkovic", "affiliations": ["University of Southern California Gould School of Law ,"]}], "abstract": "Abstract A key question for studying business dynamism is whether the costs of regulatory compliance fall homogeneously on small and large businesses. Using comprehensive establishment-level occupational microdata and occupation task information, we quantify a firm\u2019s compliance costs as the share of wage bill for performing regulatory compliance tasks (RegIndex). We reveal an inverted-U relationship between firms\u2019 RegIndex and their size: On average, RegIndex for mid-sized firms with around 500 employees is about 47% greater than that of the smallest firms and 18% greater than that of the largest firms. We further develop a shift-share methodology to disentangle the influence of regulatory requirements and enforcement on driving firms\u2019 compliance costs.", "date": "2026-04-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag046", "title_zh": "\u7f8e\u56fd\u76d1\u7ba1\u5408\u89c4\u7684\u6210\u672c", "abstract_zh": "\u6458\u8981 \u7814\u7a76\u4f01\u4e1a\u52a8\u6001\u6027\u7684\u4e00\u4e2a\u5173\u952e\u95ee\u9898\u662f\uff0c\u76d1\u7ba1\u5408\u89c4\u6210\u672c\u662f\u5426\u5747\u5300\u5730\u843d\u5728\u5c0f\u578b\u4f01\u4e1a\u548c\u5927\u578b\u4f01\u4e1a\u8eab\u4e0a\u3002\u5229\u7528\u5168\u9762\u7684\u4f01\u4e1a\u7ea7\u804c\u4e1a\u5fae\u89c2\u6570\u636e\u548c\u804c\u4e1a\u4efb\u52a1\u4fe1\u606f\uff0c\u6211\u4eec\u5c06\u4f01\u4e1a\u7684\u5408\u89c4\u6210\u672c\u91cf\u5316\u4e3a\u6267\u884c\u76d1\u7ba1\u5408\u89c4\u4efb\u52a1\u6240\u5360\u5de5\u8d44\u652f\u51fa\u7684\u6bd4\u4f8b\uff08RegIndex\uff09\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u4f01\u4e1aRegIndex\u4e0e\u4f01\u4e1a\u89c4\u6a21\u4e4b\u95f4\u5b58\u5728\u5012U\u578b\u5173\u7cfb\uff1a\u5e73\u5747\u800c\u8a00\uff0c\u62e5\u6709\u7ea6500\u540d\u5458\u5de5\u7684\u4e2d\u7b49\u89c4\u6a21\u4f01\u4e1a\u7684RegIndex\u6bd4\u6700\u5c0f\u89c4\u6a21\u4f01\u4e1a\u9ad8\u51fa\u7ea647%\uff0c\u6bd4\u6700\u5927\u89c4\u6a21\u4f01\u4e1a\u9ad8\u51fa\u7ea618%\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u5f00\u53d1\u4e86\u4e00\u79cd\u79fb\u4f4d\u4efd\u989d\u65b9\u6cd5\uff0c\u4ee5\u5206\u79bb\u76d1\u7ba1\u8981\u6c42\u548c\u6267\u6cd5\u5bf9\u4f01\u4e1a\u5408\u89c4\u6210\u672c\u7684\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70041", "journal": "JF", "title": "The Effect of Advisors' Incentives on Clients' Investments", "authors": ["DIEGO BATTISTON", "JORDI BLANES I VIDAL", "RAFAEL HORTALA\u2010VALLVE", "DONG LOU"], "author_details": [{"name": "DIEGO BATTISTON", "affiliations": []}, {"name": "JORDI BLANES I VIDAL", "affiliations": []}, {"name": "RAFAEL HORTALA\u2010VALLVE", "affiliations": []}, {"name": "DONG LOU", "affiliations": []}], "abstract": "ABSTRACT We use granular data from an investment firm and a credible identification strategy to estimate the effect of financial advisors' incentives on client investments. Exploiting a natural experiment triggered by the 2018 implementation of Markets in Financial Instruments Directive II (MiFID II), we find that clients' investments respond strongly to changes in advisor incentives. Advisors react through multiple mechanisms: (i) inducing existing clients to bring in new money, (ii) channeling it to high\u2010incentive funds, and (iii) attracting more new clients. We also find that the MiFID II reform generated more balanced incentives, which translated into higher portfolio efficiency through lower average fees and stronger portfolio diversification.", "date": "2026-04-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70041", "title_zh": "\u987e\u95ee\u6fc0\u52b1\u5bf9\u5ba2\u6237\u6295\u8d44\u7684\u5f71\u54cd", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u7528\u4e00\u5bb6\u6295\u8d44\u516c\u53f8\u7684\u8be6\u7ec6\u6570\u636e\uff0c\u5e76\u91c7\u7528\u53ef\u4fe1\u7684\u8bc6\u522b\u7b56\u7565\uff0c\u4f30\u8ba1\u4e86\u91d1\u878d\u987e\u95ee\u6fc0\u52b1\u5bf9\u5ba2\u6237\u6295\u8d44\u7684\u5f71\u54cd\u3002\u501f\u52a92018\u5e74\u5b9e\u65bd\u300a\u91d1\u878d\u5de5\u5177\u5e02\u573a\u6307\u4ee4II\u300b\uff08MiFID II\uff09\u5f15\u53d1\u7684\u81ea\u7136\u5b9e\u9a8c\uff0c\u6211\u4eec\u53d1\u73b0\u5ba2\u6237\u6295\u8d44\u5bf9\u987e\u95ee\u6fc0\u52b1\u7684\u53d8\u5316\u53cd\u5e94\u5f3a\u70c8\u3002\u987e\u95ee\u901a\u8fc7\u591a\u79cd\u673a\u5236\u53d1\u6325\u4f5c\u7528\uff1a\uff08i\uff09\u4fc3\u4f7f\u73b0\u6709\u5ba2\u6237\u5e26\u6765\u65b0\u8d44\u91d1\uff1b\uff08ii\uff09\u5c06\u8d44\u91d1\u5f15\u5bfc\u81f3\u9ad8\u6fc0\u52b1\u57fa\u91d1\uff1b\uff08iii\uff09\u5438\u5f15\u66f4\u591a\u7684\u65b0\u5ba2\u6237\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0cMiFID II\u6539\u9769\u5e26\u6765\u4e86\u66f4\u5747\u8861\u7684\u6fc0\u52b1\u7ed3\u6784\uff0c\u4ece\u800c\u901a\u8fc7\u964d\u4f4e\u5e73\u5747\u8d39\u7528\u548c\u589e\u5f3a\u6295\u8d44\u7ec4\u5408\u591a\u5143\u5316\uff0c\u63d0\u5347\u4e86\u6295\u8d44\u7ec4\u5408\u7684\u6548\u7387\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhag039", "journal": "RFS", "title": "Smokestacks and the Swamp", "authors": ["Emilio Bisetti", "Stefan Lewellen", "Arkodipta Sarkar", "Xiao Zhao"], "author_details": [{"name": "Emilio Bisetti", "affiliations": ["Hong Kong University of Science and Technology , Hong Kong SAR,"]}, {"name": "Stefan Lewellen", "affiliations": ["Pennsylvania State University and ECGI , and"]}, {"name": "Arkodipta Sarkar", "affiliations": ["National University of Singapore ,"]}, {"name": "Xiao Zhao", "affiliations": ["Shanghai Advanced Institute of Finance, Shanghai Jiao Tong University ,"]}], "abstract": "Abstract We examine whether politicians affect local firms\u2019 industrial pollution, and whether such effects are transmitted through plant-level networks to affect pollution in other regions. We first document that close Democrat wins in U.S. congressional races are associated with lower emissions and higher abatement at the plant level, especially when politicians have strong pro-environmental preferences. We also find evidence of reallocation: firms shift emissions away from areas represented by Democrats. However, reallocation is imperfect: firm-level costs are higher and market-to-book ratios lower if firms\u2019 representation is more Democratic. Lower pollution-related illnesses around plants in Democratic districts suggest pass-through effects on local communities.", "date": "2026-04-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag039", "title_zh": "\u70df\u56f1\u4e0e\u6cbc\u6cfd", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u653f\u6cbb\u5bb6\u662f\u5426\u4f1a\u5f71\u54cd\u5f53\u5730\u4f01\u4e1a\u7684\u5de5\u4e1a\u6c61\u67d3\uff0c\u4ee5\u53ca\u8fd9\u79cd\u5f71\u54cd\u662f\u5426\u901a\u8fc7\u4f01\u4e1a\u5c42\u9762\u7684\u7f51\u7edc\u4f20\u9012\uff0c\u4ece\u800c\u5f71\u54cd\u5176\u4ed6\u5730\u533a\u7684\u6c61\u67d3\u6c34\u5e73\u3002\u6211\u4eec\u9996\u5148\u53d1\u73b0\uff0c\u5728\u7f8e\u56fd\u56fd\u4f1a\u9009\u4e3e\u4e2d\u6c11\u4e3b\u515a\u5019\u9009\u4eba\u83b7\u80dc\u7684\u5730\u533a\uff0c\u4f01\u4e1a\u6392\u653e\u91cf\u66f4\u4f4e\uff0c\u51cf\u6392\u6c34\u5e73\u66f4\u9ad8\uff0c\u5c24\u5176\u662f\u5728\u653f\u6cbb\u5bb6\u5177\u6709\u5f3a\u70c8\u73af\u4fdd\u504f\u597d\u65f6\u66f4\u4e3a\u660e\u663e\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\u4e86\u6392\u653e\u518d\u5206\u914d\u7684\u73b0\u8c61\uff1a\u4f01\u4e1a\u4f1a\u5c06\u6392\u653e\u4ece\u6c11\u4e3b\u515a\u4ee3\u8868\u7684\u5730\u533a\u8f6c\u79fb\u5230\u5176\u4ed6\u5730\u533a\u3002\u7136\u800c\uff0c\u8fd9\u79cd\u518d\u5206\u914d\u662f\u4e0d\u5b8c\u5168\u7684\uff1a\u5982\u679c\u4f01\u4e1a\u7684\u4ee3\u8868\u66f4\u504f\u5411\u6c11\u4e3b\u515a\uff0c\u5176\u4f01\u4e1a\u5c42\u9762\u7684\u6210\u672c\u4f1a\u66f4\u9ad8\uff0c\u5e02\u573a\u5e02\u503c\u4e0e\u8d26\u9762\u4ef7\u503c\u6bd4\u7387\u4e5f\u4f1a\u66f4\u4f4e\u3002\u5728\u6c11\u4e3b\u515a\u9009\u533a\u9644\u8fd1\u7684\u6c61\u67d3\u76f8\u5173\u75be\u75c5\u53d1\u751f\u7387\u8f83\u4f4e\uff0c\u8868\u660e\u8fd9\u79cd\u5f71\u54cd\u5df2\u4f20\u9012\u81f3\u5f53\u5730\u793e\u533a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1017/s0022109026102920", "journal": "JFQA", "title": "Intra-Household Risk Sharing in Collective Portfolio Choice Models", "authors": ["Joachim Inkmann", "Alexander Michaelides", "Yuxin Zhang"], "author_details": [{"name": "Joachim Inkmann", "affiliations": ["University of Melbourne Graduate School of Business and Economics"]}, {"name": "Alexander Michaelides", "affiliations": ["Imperial College London Department of Finance"]}, {"name": "Yuxin Zhang", "affiliations": ["University of Nottingham Ningbo China Department of Finance, Accounting and Economics"]}], "abstract": "Abstract Using a calibrated, collective life-cycle portfolio choice model for a dual-income couple, we show that an increase in the ability to share risk within the household due to a mean-preserving spread in the partners\u2019 coefficients of relative risk aversion leads to a substantial increase in financial risk-taking. Importantly, we show that risk sharing has a larger economic impact on portfolio choice than risk diversification. While unitary models usually do not fully replicate the optimal portfolio choice of collective models, we propose approximations that work reasonably well for moderate background risk. We provide strong empirical support for our key findings.", "date": "2026-04-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102920", "title_zh": "\u5bb6\u5ead\u5185\u90e8\u98ce\u9669\u5206\u62c5\u5728\u96c6\u4f53\u6295\u8d44\u7ec4\u5408\u9009\u62e9\u6a21\u578b\u4e2d\u7684\u7814\u7a76", "abstract_zh": "\u4f7f\u7528\u4e00\u4e2a\u6821\u51c6\u8fc7\u7684\u3001\u9002\u7528\u4e8e\u53cc\u6536\u5165\u5bb6\u5ead\u751f\u547d\u5468\u671f\u6295\u8d44\u7ec4\u5408\u9009\u62e9\u7684\u96c6\u4f53\u6a21\u578b\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u7531\u4e8e\u914d\u5076\u4eec\u76f8\u5bf9\u98ce\u9669\u538c\u6076\u7cfb\u6570\u51fa\u73b0\u5747\u503c\u4fdd\u6301\u6269\u5c55\u7684\u975e\u6d41\u52a8\u6027\uff0c\u5bb6\u5ead\u5185\u90e8\u98ce\u9669\u5206\u62c5\u80fd\u529b\u7684\u63d0\u5347\u4f1a\u5bfc\u81f4\u91d1\u878d\u98ce\u9669\u627f\u62c5\u663e\u8457\u589e\u52a0\u3002\u91cd\u8981\u7684\u662f\uff0c\u6211\u4eec\u8bc1\u660e\u98ce\u9669\u5206\u62c5\u5bf9\u6295\u8d44\u7ec4\u5408\u9009\u62e9\u7684\u7ecf\u6d4e\u5f71\u54cd\u5927\u4e8e\u98ce\u9669\u5206\u6563\u3002\u5c3d\u7ba1\u5355\u4eba\u6a21\u578b\u901a\u5e38\u65e0\u6cd5\u5b8c\u5168\u590d\u5236\u96c6\u4f53\u6a21\u578b\u7684\u6700\u4f18\u6295\u8d44\u7ec4\u5408\u9009\u62e9\uff0c\u6211\u4eec\u4e3a\u4e2d\u7b49\u80cc\u666f\u98ce\u9669\u60c5\u51b5\u63d0\u51fa\u4e86\u5408\u7406\u7684\u8fd1\u4f3c\u65b9\u6cd5\u3002\u6211\u4eec\u4e3a\u5173\u952e\u53d1\u73b0\u63d0\u4f9b\u4e86\u5f3a\u6709\u529b\u7684\u5b9e\u8bc1\u652f\u6301\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1017/s0022109026102907", "journal": "JFQA", "title": "Politically Polarized Depositors", "authors": ["Jinoug Jeung"], "author_details": [{"name": "Jinoug Jeung", "affiliations": ["The Chinese University of Hong Kong CUHK Business School"]}], "abstract": "Abstract Exploiting an exogenous increase in public awareness of banks\u2019 lending to the gun industry, this article documents significant deposit outflows from gun lenders. These outflows are stronger in Democratic-leaning markets and for Republican-leaning lenders. In contrast, anti-gun lenders experience limited and insignificant outflows, consistent with policy alignment with depositor values. Outflows tighten funding constraints, prompting gun lenders to reduce deposit spreads and branches in Democratic-leaning markets. While large gun lenders remain resilient, small gun lenders significantly reduce their CRA loan volumes. The findings highlight political value misalignment as a driver of depositor behavior and its real effects on bank operations.", "date": "2026-04-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102907", "title_zh": "\u653f\u6cbb\u6781\u5316\u7684\u5b58\u6b3e\u4eba", "abstract_zh": "\u5229\u7528\u516c\u4f17\u5bf9\u94f6\u884c\u5411\u67aa\u652f\u884c\u4e1a\u653e\u8d37\u884c\u4e3a\u7684\u5916\u751f\u6027\u5173\u6ce8\u5ea6\u63d0\u5347\uff0c\u672c\u6587\u53d1\u73b0\u67aa\u652f\u8d37\u6b3e\u94f6\u884c\u51fa\u73b0\u4e86\u663e\u8457\u7684\u5b58\u6b3e\u6d41\u51fa\u3002\u8fd9\u4e9b\u6d41\u51fa\u5728\u6c11\u4e3b\u515a\u503e\u5411\u7684\u5e02\u573a\u4e2d\u66f4\u4e3a\u660e\u663e\uff0c\u4e14\u51fa\u73b0\u5728\u5171\u548c\u515a\u503e\u5411\u7684\u8d37\u6b3e\u673a\u6784\u4e2d\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u53cd\u67aa\u652f\u8d37\u6b3e\u673a\u6784\u5e76\u672a\u51fa\u73b0\u663e\u8457\u7684\u5b58\u6b3e\u6d41\u51fa\uff0c\u8fd9\u4e0e\u5b58\u6b3e\u4eba\u4ef7\u503c\u89c2\u4e0e\u653f\u7b56\u7acb\u573a\u4e00\u81f4\u76f8\u543b\u5408\u3002\u5b58\u6b3e\u6d41\u51fa\u52a0\u5267\u4e86\u8d44\u91d1\u7ea6\u675f\uff0c\u4fc3\u4f7f\u67aa\u652f\u8d37\u6b3e\u94f6\u884c\u5728\u6c11\u4e3b\u515a\u503e\u5411\u5e02\u573a\u4e2d\u964d\u4f4e\u5b58\u6b3e\u5229\u5dee\u548c\u5206\u652f\u673a\u6784\u6570\u91cf\u3002\u5c3d\u7ba1\u5927\u578b\u67aa\u652f\u8d37\u6b3e\u673a\u6784\u4ecd\u8868\u73b0\u51fa\u97e7\u6027\uff0c\u4f46\u5c0f\u578b\u67aa\u652f\u8d37\u6b3e\u673a\u6784\u663e\u8457\u51cf\u5c11\u4e86\u5176\u4fe1\u8d37\u914d\u989d\uff08CRA\uff09\u8d37\u6b3e\u89c4\u6a21\u3002\u7814\u7a76\u7ed3\u679c\u51f8\u663e\u4e86\u653f\u6cbb\u4ef7\u503c\u89c2\u9519\u4f4d\u4f5c\u4e3a\u5b58\u6b3e\u4eba\u884c\u4e3a\u9a71\u52a8\u56e0\u7d20\u53ca\u5176\u5bf9\u94f6\u884c\u8fd0\u8425\u7684\u5b9e\u9645\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag022", "journal": "QJE", "title": "The Effects of Mandatory Profit-Sharing on Workers and Firms: Evidence from France", "authors": ["Elio Nimier-David", "David Sraer", "David Thesmar"], "author_details": [{"name": "Elio Nimier-David", "affiliations": ["Cornell University ,"]}, {"name": "David Sraer", "affiliations": ["University of California, Berkeley and National Bureau of Economic Research ,", "Centre for Economic Policy Research ,"]}, {"name": "David Thesmar", "affiliations": ["Massachusetts Institute of Technology and National Bureau of Economic Research ,", "Centre for Economic Policy Research ,"]}], "abstract": "Abstract Since 1967, all French firms with more than 100 employees have been required to share a fraction of their excess profits with their employees. Through this scheme, firms with excess profits distribute, on average, 10.5% of their pretax income to workers. In 1990, the eligibility threshold was reduced to 50 employees. We exploit this regulatory change to identify the effects of mandated profit-sharing on firms and their employees. The cost of mandated profit-sharing for firms is evident in the significant bunching at the 100-employee threshold observed prior to the reform, which completely disappears post-reform. Using a difference-in-differences strategy, we find that at the firm level, mandated profit-sharing (i) increases the labor share by 1.8 percentage points, (ii) reduces the profit share by 1.4 percentage points, and (iii) has small to nonexistent effects on investment and productivity. At the employee level, mandated profit-sharing increases lower-skilled workers\u2019 total compensation and leaves high-skilled workers\u2019 total compensation unchanged. Overall, mandated profit-sharing redistributes excess profits to lower-skilled workers in the firm without generating significant distortions or productivity effects.", "date": "2026-04-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag022", "title_zh": "\u5f3a\u5236\u5229\u6da6\u5206\u4eab\u5bf9\u5458\u5de5\u548c\u4f01\u4e1a\u7684\u5f71\u54cd\uff1a\u6765\u81ea\u6cd5\u56fd\u7684\u8bc1\u636e", "abstract_zh": "\u81ea1967\u5e74\u4ee5\u6765\uff0c\u6240\u6709\u62e5\u6709100\u540d\u4ee5\u4e0a\u5458\u5de5\u7684\u6cd5\u56fd\u4f01\u4e1a\u90fd\u88ab\u8981\u6c42\u5c06\u90e8\u5206\u8d85\u989d\u5229\u6da6\u5206\u4eab\u7ed9\u5458\u5de5\u3002\u901a\u8fc7\u8fd9\u4e00\u65b9\u6848\uff0c\u62e5\u6709\u8d85\u989d\u5229\u6da6\u7684\u4f01\u4e1a\u5e73\u5747\u5c06\u9884\u7a0e\u6536\u5165\u768410.5%\u5206\u914d\u7ed9\u5458\u5de5\u30021990\u5e74\uff0c\u8d44\u683c\u95e8\u69db\u88ab\u964d\u4f4e\u81f350\u540d\u5458\u5de5\u3002\u6211\u4eec\u5229\u7528\u8fd9\u4e00\u76d1\u7ba1\u53d8\u5316\u6765\u8bc6\u522b\u5f3a\u5236\u5229\u6da6\u5206\u4eab\u5bf9\u4f01\u4e1a\u53ca\u5176\u5458\u5de5\u7684\u5f71\u54cd\u3002\u5f3a\u5236\u5229\u6da6\u5206\u4eab\u5bf9\u4f01\u4e1a\u9020\u6210\u7684\u6210\u672c\u4f53\u73b0\u5728\u6539\u9769\u524d\u5728100\u540d\u5458\u5de5\u95e8\u69db\u5904\u51fa\u73b0\u663e\u8457\u7684\u96c6\u4e2d\u73b0\u8c61\uff0c\u800c\u6539\u9769\u540e\u8fd9\u4e00\u73b0\u8c61\u5b8c\u5168\u6d88\u5931\u3002\u91c7\u7528\u5dee\u5206\u5dee\u5206\u6cd5\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u4f01\u4e1a\u5c42\u9762\uff0c\u5f3a\u5236\u5229\u6da6\u5206\u4eab\uff08i\uff09\u4f7f\u52b3\u52a8\u4efd\u989d\u63d0\u9ad81.8\u4e2a\u767e\u5206\u70b9\uff0c\uff08ii\uff09\u4f7f\u5229\u6da6\u4efd\u989d\u51cf\u5c111.4\u4e2a\u767e\u5206\u70b9\uff0c\uff08iii\uff09\u5bf9\u6295\u8d44\u548c\u751f\u4ea7\u7387\u7684\u5f71\u54cd\u5fae\u5c0f\u6216\u4e0d\u5b58\u5728\u3002\u5728\u5458\u5de5\u5c42\u9762\uff0c\u5f3a\u5236\u5229\u6da6\u5206\u4eab\u63d0\u9ad8\u4e86\u4f4e\u6280\u80fd\u5de5\u4eba\u7684\u603b\u62a5\u916c\uff0c\u800c\u5bf9\u9ad8\u6280\u80fd\u5de5\u4eba\u7684\u603b\u62a5\u916c\u6ca1\u6709\u5f71\u54cd\u3002\u603b\u4f53\u800c\u8a00\uff0c\u5f3a\u5236\u5229\u6da6\u5206\u4eab\u5c06\u8d85\u989d\u5229\u6da6\u5411\u4f01\u4e1a\u4e2d\u7684\u4f4e\u6280\u80fd\u5de5\u4eba\u91cd\u65b0\u5206\u914d\uff0c\u800c\u672a\u4ea7\u751f\u663e\u8457\u7684\u626d\u66f2\u6216\u751f\u4ea7\u7387\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag045", "journal": "RFS", "title": "Broken Relationships: Derisking by Correspondent Banks and International Trade", "authors": ["Lea Borchert", "Ralph De Haas", "Karolin Kirschenmann", "Alison Schultz"], "author_details": [{"name": "Lea Borchert", "affiliations": ["ZEW, University of Mannheim"]}, {"name": "Ralph De Haas", "affiliations": ["EBRD, KU Leuven, CEPR"]}, {"name": "Karolin Kirschenmann", "affiliations": ["ZEW, Johannes Gutenberg University Mainz"]}, {"name": "Alison Schultz", "affiliations": ["Tax Justice Network"]}], "abstract": "Abstract We study how terminated correspondent banking relationships affect international trade. Drawing on firm-level export data from emerging Europe, we show that when local banks lose access to correspondent services, their corporate clients, especially small- and medium-sized enterprises, experience significant export declines. Firms only partially offset lost exports with higher domestic sales, resulting in lower total revenues and employment. Other firms cease operations entirely. These firm-level impacts aggregate to lower product-level exports from countries more exposed to correspondent bank retrenchment.", "date": "2026-04-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag045", "title_zh": "\u65ad\u88c2\u7684\u5173\u7cfb\uff1a\u5bf9\u5e94\u94f6\u884c\u9000\u51fa\u4e0e\u56fd\u9645\u8d38\u6613", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u7ec8\u6b62\u5bf9\u5e94\u94f6\u884c\u5173\u7cfb\u5982\u4f55\u5f71\u54cd\u56fd\u9645\u8d38\u6613\u3002\u57fa\u4e8e\u65b0\u5174\u6b27\u6d32\u7684\u516c\u53f8\u51fa\u53e3\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u5f53\u672c\u5730\u94f6\u884c\u5931\u53bb\u5bf9\u5e94\u94f6\u884c\u670d\u52a1\u7684\u8bbf\u95ee\u6743\u9650\u65f6\uff0c\u5176\u4f01\u4e1a\u5ba2\u6237\uff0c\u5c24\u5176\u662f\u4e2d\u5c0f\u578b\u4f01\u4e1a\uff0c\u4f1a\u7ecf\u5386\u663e\u8457\u7684\u51fa\u53e3\u4e0b\u964d\u3002\u4f01\u4e1a\u4ec5\u90e8\u5206\u901a\u8fc7\u63d0\u9ad8\u56fd\u5185\u9500\u552e\u6765\u62b5\u6d88\u51fa\u53e3\u635f\u5931\uff0c\u5bfc\u81f4\u603b\u8425\u6536\u548c\u5c31\u4e1a\u6c34\u5e73\u4e0b\u964d\u3002\u5176\u4ed6\u4f01\u4e1a\u5219\u5b8c\u5168\u505c\u6b62\u8fd0\u8425\u3002\u8fd9\u4e9b\u4f01\u4e1a\u5c42\u9762\u7684\u5f71\u54cd\u6700\u7ec8\u5bfc\u81f4\u90a3\u4e9b\u66f4\u53d7\u5bf9\u5e94\u94f6\u884c\u6536\u7f29\u5f71\u54cd\u7684\u56fd\u5bb6\u5728\u4ea7\u54c1\u5c42\u9762\u7684\u51fa\u53e3\u4e0b\u964d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102865", "journal": "JFQA", "title": "Mutual Fund Strategy: Swing for the Fences or Bat for Average", "authors": ["John Chalmers", "Arash Dayani"], "author_details": [{"name": "John Chalmers", "affiliations": ["University of Oregon Charles H. Lundquist College of Business"]}, {"name": "Arash Dayani", "affiliations": ["Clemson University Wilbur O. and Ann Powers College of Business"]}], "abstract": "Abstract We document two distinct mutual fund strategies: \u201cSwinging for the Fences\u201d (SF), in which managers hold stocks with extreme style-adjusted returns on either tail of the return distribution, and \u201cBatting for Average\u201d (BA), in which managers seek stocks with consistently moderate performance. We provide evidence that these strategies are persistent and deliberate. Existing measures of active management and known asset-pricing factors do not explain the strategies. SF attracts more flow, particularly when funds mention specific stock holdings in shareholder reports. SF funds charge higher fees and hold riskier portfolios; yet, they fail to deliver higher risk-adjusted returns. In falsification tests, SF strategies are not present in passive funds, supporting our conclusion that SF and BA are intentional strategies.", "date": "2026-04-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102865", "title_zh": "\u5171\u540c\u57fa\u91d1\u7b56\u7565\uff1a\u8ffd\u6c42\u9ad8\u98ce\u9669\u8fd8\u662f\u8ffd\u6c42\u5e73\u5747\u8868\u73b0", "abstract_zh": "\u6211\u4eec\u8bb0\u5f55\u4e86\u4e24\u79cd\u4e0d\u540c\u7684\u5171\u540c\u57fa\u91d1\u7b56\u7565\uff1a\u2018\u8ffd\u6c42\u9ad8\u98ce\u9669\u2019\uff08SF\uff09\uff0c\u5373\u57fa\u91d1\u7ecf\u7406\u6301\u6709\u98ce\u683c\u8c03\u6574\u540e\u56de\u62a5\u5904\u4e8e\u56de\u62a5\u5206\u5e03\u4e24\u7aef\u6781\u7aef\u503c\u7684\u80a1\u7968\uff1b\u4ee5\u53ca\u2018\u8ffd\u6c42\u5e73\u5747\u8868\u73b0\u2019\uff08BA\uff09\uff0c\u5373\u57fa\u91d1\u7ecf\u7406\u5bfb\u6c42\u8868\u73b0\u7a33\u5b9a\u4e14\u4e2d\u7b49\u7684\u80a1\u7968\u3002\u6211\u4eec\u63d0\u4f9b\u4e86\u8bc1\u636e\u8868\u660e\uff0c\u8fd9\u4e24\u79cd\u7b56\u7565\u5177\u6709\u6301\u7eed\u6027\u548c\u4e3b\u52a8\u6027\u3002\u73b0\u6709\u7684\u4e3b\u52a8\u7ba1\u7406\u8861\u91cf\u6307\u6807\u4ee5\u53ca\u5df2\u77e5\u7684\u8d44\u4ea7\u5b9a\u4ef7\u56e0\u7d20\u5747\u65e0\u6cd5\u89e3\u91ca\u8fd9\u4e9b\u7b56\u7565\u3002\u2018\u8ffd\u6c42\u9ad8\u98ce\u9669\u2019\u7684\u57fa\u91d1\u5438\u5f15\u66f4\u591a\u7684\u8d44\u91d1\u6d41\u5165\uff0c\u5c24\u5176\u662f\u5728\u57fa\u91d1\u5728\u80a1\u4e1c\u62a5\u544a\u4e2d\u660e\u786e\u63d0\u53ca\u5177\u4f53\u6301\u4ed3\u65f6\u66f4\u4e3a\u660e\u663e\u3002\u8fd9\u7c7b\u57fa\u91d1\u6536\u53d6\u66f4\u9ad8\u7684\u8d39\u7528\uff0c\u5e76\u6301\u6709\u98ce\u9669\u66f4\u9ad8\u7684\u6295\u8d44\u7ec4\u5408\uff1b\u7136\u800c\uff0c\u5b83\u4eec\u5e76\u672a\u5e26\u6765\u66f4\u9ad8\u7684\u98ce\u9669\u8c03\u6574\u540e\u56de\u62a5\u3002\u5728\u53cd\u4e8b\u5b9e\u68c0\u9a8c\u4e2d\uff0c\u88ab\u52a8\u57fa\u91d1\u4e2d\u4e0d\u5b58\u5728\u2018\u8ffd\u6c42\u9ad8\u98ce\u9669\u2019\u7b56\u7565\uff0c\u8fd9\u652f\u6301\u4e86\u6211\u4eec\u7684\u7ed3\u8bba\uff1aSF\u548cBA\u662f\u57fa\u91d1\u7ecf\u7406\u6709\u610f\u91c7\u53d6\u7684\u7b56\u7565\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1093/rfs/hhag043", "journal": "RFS", "title": "The Effect of Primary Dealer Constraints on Intermediation in the Treasury Market", "authors": ["Falk Br\u00e4uning", "Hillary Stein"], "author_details": [{"name": "Falk Br\u00e4uning", "affiliations": ["Federal Reserve Bank of Boston"]}, {"name": "Hillary Stein", "affiliations": ["Federal Reserve Bank of Boston"]}], "abstract": "Abstract Using confidential microdata, we show that shocks to primary dealers\u2019 constraints have significant effects on the U.S. Treasury securities market. We consider two types of constraints: the supplementary leverage ratio and trading desk value-at-risk constraints. In response to tighter constraints, dealers reduce their Treasury positions, triggering a reduction in aggregate turnover and an increase in dealer intermediation margin. Impaired intermediation also amplifies the yield response to net demand shifts and weakens Treasury auction outcomes. Our estimates suggest that the (shadow) cost of dealer constraints is as high as 9% of dealers\u2019 profit margins.", "date": "2026-04-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag043", "title_zh": "\u521d\u7ea7\u4ea4\u6613\u5546\u7ea6\u675f\u5bf9\u56fd\u503a\u5e02\u573a\u4e2d\u4ecb\u4f5c\u7528\u7684\u5f71\u54cd", "abstract_zh": "\u5229\u7528\u4fdd\u5bc6\u7684\u5fae\u89c2\u6570\u636e\uff0c\u6211\u4eec\u8868\u660e\u521d\u7ea7\u4ea4\u6613\u5546\u7ea6\u675f\u7684\u51b2\u51fb\u5bf9\u7f8e\u56fd\u56fd\u503a\u8bc1\u5238\u5e02\u573a\u6709\u663e\u8457\u5f71\u54cd\u3002\u6211\u4eec\u8003\u8651\u4e24\u79cd\u7c7b\u578b\u7684\u7ea6\u675f\uff1a\u8865\u5145\u6760\u6746\u7387\u548c\u4ea4\u6613\u53f0\u98ce\u9669\u4ef7\u503c\u7ea6\u675f\u3002\u9762\u5bf9\u66f4\u4e25\u683c\u7684\u7ea6\u675f\uff0c\u4ea4\u6613\u5546\u51cf\u5c11\u5176\u56fd\u503a\u5934\u5bf8\uff0c\u5bfc\u81f4\u6574\u4f53\u4ea4\u6613\u91cf\u4e0b\u964d\u4ee5\u53ca\u4ea4\u6613\u5546\u4e2d\u4ecb\u5229\u6da6\u7387\u4e0a\u5347\u3002\u4e2d\u4ecb\u529f\u80fd\u53d7\u635f\u8fd8\u4f1a\u653e\u5927\u51c0\u9700\u6c42\u53d8\u52a8\u5bf9\u6536\u76ca\u7387\u7684\u53cd\u5e94\uff0c\u5e76\u524a\u5f31\u56fd\u503a\u62cd\u5356\u7684\u7ed3\u679c\u3002\u6211\u4eec\u7684\u4f30\u8ba1\u8868\u660e\uff0c\u4ea4\u6613\u5546\u7ea6\u675f\u7684\uff08\u5f71\u5b50\uff09\u6210\u672c\u9ad8\u8fbe\u4ea4\u6613\u5546\u5229\u6da6 margins \u76849%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag028", "journal": "REStud", "title": "Testing Mechanisms", "authors": ["Soonwoo Kwon", "Jonathan Roth"], "author_details": [{"name": "Soonwoo Kwon", "affiliations": ["Brown University ,"]}, {"name": "Jonathan Roth", "affiliations": ["Brown University ,"]}], "abstract": "Abstract Economists are often interested in the mechanisms by which a treatment affects an outcome. We develop tests for the \u201csharp null of full mediation\u201d that a treatment D affects an outcome Y only through a particular mechanism (or set of mechanisms) M. Our approach exploits connections between mediation analysis and the econometric literature on testing instrument validity. We also provide tools for quantifying the magnitude of alternative mechanisms when the sharp null is rejected: we derive sharp lower bounds on the fraction of individuals whose outcome is affected by the treatment despite having the same value of M under both treatments (\u201calways-takers\u201d), as well as sharp bounds on the average effect of the treatment for such always-takers. An advantage of our approach relative to existing tools for mediation analysis is that it does not require stringent assumptions about how M is assigned. We illustrate our methodology in two empirical applications.", "date": "2026-04-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag028", "title_zh": "\u673a\u5236\u68c0\u9a8c", "abstract_zh": "\u7ecf\u6d4e\u5b66\u5bb6\u901a\u5e38\u5173\u6ce8\u6cbb\u7597\u5982\u4f55\u901a\u8fc7\u67d0\u79cd\u673a\u5236\u5f71\u54cd\u7ed3\u679c\u3002\u6211\u4eec\u4e3a\u201c\u5b8c\u5168\u4e2d\u4ecb\u7684\u9510null\u5047\u8bbe\u201d\u5f00\u53d1\u4e86\u68c0\u9a8c\u65b9\u6cd5\uff0c\u5373\u6cbb\u7597D\u4ec5\u901a\u8fc7\u7279\u5b9a\u673a\u5236\uff08\u6216\u4e00\u7ec4\u673a\u5236\uff09M\u5f71\u54cd\u7ed3\u679cY\u3002\u6211\u4eec\u7684\u65b9\u6cd5\u5229\u7528\u4e86\u4e2d\u4ecb\u5206\u6790\u4e0e\u8ba1\u91cf\u7ecf\u6d4e\u5b66\u4e2d\u5173\u4e8e\u5de5\u5177\u53d8\u91cf\u6709\u6548\u6027\u68c0\u9a8c\u4e4b\u95f4\u7684\u8054\u7cfb\u3002\u6211\u4eec\u8fd8\u63d0\u4f9b\u4e86\u5728\u9510null\u5047\u8bbe\u88ab\u62d2\u7edd\u65f6\uff0c\u91cf\u5316\u5176\u4ed6\u673a\u5236\u5e45\u5ea6\u7684\u5de5\u5177\uff1a\u6211\u4eec\u63a8\u5bfc\u51fa\u4e2a\u4f53\u5728\u4e24\u79cd\u6cbb\u7597\u4e0bM\u503c\u76f8\u540c\u7684\u60c5\u51b5\u4e0b\u4ecd\u53d7\u5230\u6cbb\u7597\u5f71\u54cd\u7684\u6bd4\u4f8b\u7684\u7cbe\u786e\u4e0b\u754c\uff08\u5373\u201c\u59cb\u7ec8\u63a5\u53d7\u8005\u201d\uff09\uff0c\u4ee5\u53ca\u8fd9\u7c7b\u59cb\u7ec8\u63a5\u53d7\u8005\u7684\u6cbb\u7597\u5e73\u5747\u6548\u5e94\u7684\u7cbe\u786e\u754c\u9650\u3002\u4e0e\u73b0\u6709\u4e2d\u4ecb\u5206\u6790\u5de5\u5177\u76f8\u6bd4\uff0c\u6211\u4eec\u7684\u65b9\u6cd5\u4f18\u52bf\u5728\u4e8e\u4e0d\u9700\u8981\u5bf9M\u7684\u5206\u914d\u505a\u51fa\u4e25\u683c\u5047\u8bbe\u3002\u6211\u4eec\u901a\u8fc7\u4e24\u4e2a\u5b9e\u8bc1\u5e94\u7528\u5c55\u793a\u4e86\u6211\u4eec\u7684\u65b9\u6cd5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag044", "journal": "RFS", "title": "What Drives Variation in Investor Portfolios? Estimating the Roles of Beliefs and Risk Preferences", "authors": ["Mark Egan", "Alexander MacKay", "Hanbin Yang"], "author_details": [{"name": "Mark Egan", "affiliations": ["Harvard Business School, Harvard University ,"]}, {"name": "Alexander MacKay", "affiliations": ["University of Virginia ,"]}, {"name": "Hanbin Yang", "affiliations": ["London Business School ,"]}], "abstract": "Abstract We present a portfolio choice demand model that allows for the nonparametric estimation of investors\u2019 (subjective) expectations and risk preferences. Using comprehensive 401(k)-plan-level data from 2009 through 2019, we explore heterogeneity in asset allocations using our empirical framework. We recover investors\u2019 beliefs about each asset and examine the implications and potential sources of those beliefs. Heterogeneity in expectations across investors accounts for twice as much variation in portfolio holdings as heterogeneity in risk aversion. Belief heterogeneity is partly driven by investors\u2019 characteristics and experiences, reflecting local sources of information such as county-level GDP and employers\u2019 past performance.", "date": "2026-04-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag044", "title_zh": "\u662f\u4ec0\u4e48\u9a71\u52a8\u4e86\u6295\u8d44\u8005\u6295\u8d44\u7ec4\u5408\u7684\u5dee\u5f02\uff1f\u4f30\u8ba1\u4fe1\u5ff5\u4e0e\u98ce\u9669\u504f\u597d\u4f5c\u7528", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u6295\u8d44\u7ec4\u5408\u9009\u62e9\u9700\u6c42\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u5141\u8bb8\u975e\u53c2\u6570\u4f30\u8ba1\u6295\u8d44\u8005\u7684\uff08\u4e3b\u89c2\uff09\u9884\u671f\u548c\u98ce\u9669\u504f\u597d\u3002\u5229\u75282009\u5e74\u81f32019\u5e74\u671f\u95f4\u5168\u9762\u7684401(k)\u8ba1\u5212\u5c42\u9762\u6570\u636e\uff0c\u6211\u4eec\u4f7f\u7528\u8be5\u7ecf\u9a8c\u6846\u67b6\u63a2\u8ba8\u6295\u8d44\u8005\u8d44\u4ea7\u914d\u7f6e\u7684\u5f02\u8d28\u6027\u3002\u6211\u4eec\u6062\u590d\u4e86\u6295\u8d44\u8005\u5bf9\u5404\u7c7b\u8d44\u4ea7\u7684\u4fe1\u5ff5\uff0c\u5e76\u8003\u5bdf\u4e86\u8fd9\u4e9b\u4fe1\u5ff5\u7684\u542b\u4e49\u53ca\u5176\u6f5c\u5728\u6765\u6e90\u3002\u6295\u8d44\u8005\u9884\u671f\u7684\u5f02\u8d28\u6027\u5bf9\u6295\u8d44\u7ec4\u5408\u6301\u4ed3\u7684\u89e3\u91ca\u4f5c\u7528\u662f\u98ce\u9669\u538c\u6076\u5f02\u8d28\u6027\u7684\u4e24\u500d\u3002\u4fe1\u5ff5\u7684\u5f02\u8d28\u6027\u90e8\u5206\u7531\u6295\u8d44\u8005\u7684\u7279\u5f81\u548c\u7ecf\u5386\u9a71\u52a8\uff0c\u53cd\u6620\u4e86\u672c\u5730\u4fe1\u606f\u6765\u6e90\uff0c\u5982\u53bf\u7ea7GDP\u548c\u96c7\u4e3b\u8fc7\u5f80\u4e1a\u7ee9\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhag042", "journal": "RFS", "title": "Machine Forecast Disagreement", "authors": ["Turan G Bali", "Bryan T Kelly", "Mathis M\u00f6rke", "Jamil Rahman"], "author_details": [{"name": "Turan G Bali", "affiliations": ["Georgetown University , the"]}, {"name": "Bryan T Kelly", "affiliations": ["Yale University, AQR Capital Management, and NBER , the"]}, {"name": "Mathis M\u00f6rke", "affiliations": ["ESCP Business School Paris ,"]}, {"name": "Jamil Rahman", "affiliations": ["Yale University , the"]}], "abstract": "Abstract We propose a statistical model of heterogeneous beliefs wherein investors are represented as different machine learning model specifications. Investors form return forecasts from their individual models using common data inputs. We measure disagreement as forecast dispersion across investor-models (MFD). Our measure aligns with analyst forecast disagreement but more powerfully predicts returns. We document a large and robust association between belief disagreement and future returns. A decile spread portfolio that sells stocks with high disagreement and buys stocks with low disagreement earns a value-weighted return of 13% per year. Further analyses suggest MFD-alpha is mispricing induced by short-sale costs and limits-to-arbitrage.", "date": "2026-04-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag042", "title_zh": "\u673a\u5668\u9884\u6d4b\u5206\u6b67", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u5f02\u8d28\u4fe1\u5ff5\u7684\u7edf\u8ba1\u6a21\u578b\uff0c\u5176\u4e2d\u6295\u8d44\u8005\u88ab\u8868\u793a\u4e3a\u4e0d\u540c\u7684\u673a\u5668\u5b66\u4e60\u6a21\u578b\u89c4\u683c\u3002\u6295\u8d44\u8005\u5229\u7528\u5171\u540c\u7684\u6570\u636e\u8f93\u5165\u4ece\u5404\u81ea\u7684\u6a21\u578b\u4e2d\u5f62\u6210\u6536\u76ca\u9884\u6d4b\u3002\u6211\u4eec\u5c06\u5206\u6b67\u5b9a\u4e49\u4e3a\u6295\u8d44\u8005\u6a21\u578b\u4e4b\u95f4\u7684\u9884\u6d4b\u5206\u6563\u7a0b\u5ea6\uff08MFD\uff09\u3002\u8be5\u5ea6\u91cf\u4e0e\u5206\u6790\u5e08\u9884\u6d4b\u5206\u6b67\u4e00\u81f4\uff0c\u4f46\u66f4\u80fd\u9884\u6d4b\u6536\u76ca\u3002\u6211\u4eec\u53d1\u73b0\u4fe1\u5ff5\u5206\u6b67\u4e0e\u672a\u6765\u6536\u76ca\u4e4b\u95f4\u5b58\u5728\u663e\u8457\u4e14\u7a33\u5065\u7684\u5173\u8054\u3002\u4e00\u4e2a\u6309\u5341\u5206\u4f4d\u6570\u5206\u7ec4\u7684\u7ec4\u5408\uff0c\u5356\u51fa\u9ad8\u5206\u6b67\u80a1\u7968\u3001\u4e70\u5165\u4f4e\u5206\u6b67\u80a1\u7968\uff0c\u6bcf\u5e74\u83b7\u5f9713%\u7684\u4ef7\u503c\u52a0\u6743\u56de\u62a5\u3002\u8fdb\u4e00\u6b65\u5206\u6790\u8868\u660e\uff0cMFD-\u963f\u5c14\u6cd5\u662f\u7531\u77ed\u5356\u6210\u672c\u548c\u5957\u5229\u9650\u5236\u5f15\u8d77\u7684\u8bef\u5b9a\u4ef7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "AI"]}, {"doi": "10.1093/rfs/hhag038", "journal": "RFS", "title": "The True Colors of Money: Racial Representation and Asset Management", "authors": ["Lina Han", "Xing Huang", "Ohad Kadan", "Jimmy Wu"], "author_details": [{"name": "Lina Han", "affiliations": ["The University of Massachusetts Amherst ,"]}, {"name": "Xing Huang", "affiliations": ["Washington University in St. Louis and Cornell University ,"]}, {"name": "Ohad Kadan", "affiliations": ["Arizona State University ,"]}, {"name": "Jimmy Wu", "affiliations": ["University of Iowa and Washington University in St. Louis ,"]}], "abstract": "Abstract We examine the role of race and ethnicity in the mutual fund context at two distinct levels. At the fund manager level, we document a co-racial tilt\u2014funds managed by minority-dominant (White-dominant) teams allocate larger portfolio weights to minority-led (White-led) firms. This tilt is not associated with superior performance. It diminishes as fund managers gain experience, suggesting the presence of inaccurate statistical discrimination. At the investor level, we find that minority-dominant funds are penalized similarly to White-dominant funds for poor performance but are not rewarded as much for superior performance. Overall, our results uncover race-related investment choices at both levels.", "date": "2026-04-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag038", "title_zh": "\u91d1\u94b1\u7684\u771f\u5b9e\u8272\u5f69\uff1a\u79cd\u65cf\u4ee3\u8868\u4e0e\u8d44\u4ea7\u7ba1\u7406", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5728\u4e92\u6362\u57fa\u91d1\u7684\u80cc\u666f\u4e0b\uff0c\u4ece\u4e24\u4e2a\u4e0d\u540c\u5c42\u9762\u8003\u5bdf\u79cd\u65cf\u548c\u65cf\u88d4\u7684\u5f71\u54cd\u3002\u5728\u57fa\u91d1\u7ecf\u7406\u5c42\u9762\uff0c\u6211\u4eec\u53d1\u73b0\u4e86\u4e00\u79cd\u5171\u65cf\u503e\u5411\u2014\u2014\u7531\u5c11\u6570\u65cf\u88d4\u4e3b\u5bfc\uff08\u767d\u4eba\u4e3b\u5bfc\uff09\u7684\u56e2\u961f\u7ba1\u7406\u7684\u57fa\u91d1\uff0c\u5176\u6295\u8d44\u7ec4\u5408\u4e2d\u5bf9\u5c11\u6570\u65cf\u88d4\u9886\u5bfc\uff08\u767d\u4eba\u9886\u5bfc\uff09\u4f01\u4e1a\u7684\u6743\u91cd\u66f4\u5927\u3002\u8fd9\u79cd\u503e\u5411\u4e0e\u66f4\u4f18\u7684\u4e1a\u7ee9\u65e0\u5173\u8054\u3002\u968f\u7740\u57fa\u91d1\u7ecf\u7406\u7ecf\u9a8c\u7684\u589e\u52a0\uff0c\u8fd9\u79cd\u503e\u5411\u9010\u6e10\u51cf\u5f31\uff0c\u8868\u660e\u5b58\u5728\u4e0d\u51c6\u786e\u7684\u7edf\u8ba1\u6027\u6b67\u89c6\u3002\u5728\u6295\u8d44\u8005\u5c42\u9762\uff0c\u6211\u4eec\u53d1\u73b0\u5c11\u6570\u65cf\u88d4\u4e3b\u5bfc\u7684\u57fa\u91d1\u5728\u4e1a\u7ee9\u4e0d\u4f73\u65f6\u53d7\u5230\u7684\u60e9\u7f5a\u4e0e\u767d\u4eba\u4e3b\u5bfc\u57fa\u91d1\u76f8\u5f53\uff0c\u4f46\u5728\u4e1a\u7ee9\u4f18\u5f02\u65f6\u83b7\u5f97\u7684\u5956\u52b1\u5374\u8f83\u5c11\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u7814\u7a76\u63ed\u793a\u4e86\u5728\u4e24\u4e2a\u5c42\u9762\u90fd\u5b58\u5728\u7684\u4e0e\u79cd\u65cf\u76f8\u5173\u7684\u6295\u8d44\u51b3\u7b56\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1093/rfs/hhag041", "journal": "RFS", "title": "Dynamics of Asset Demands with Confidence Heterogeneity", "authors": ["Adrian Buss", "Raman Uppal", "Grigory Vilkov"], "author_details": [{"name": "Adrian Buss", "affiliations": ["Frankfurt School of Finance & Management and CEPR , Frankfurt,"]}, {"name": "Raman Uppal", "affiliations": ["Edhec Business School and CEPR , London,"]}, {"name": "Grigory Vilkov", "affiliations": ["Frankfurt School of Finance & Management , Frankfurt,"]}], "abstract": "Abstract To understand the dynamics of investors\u2019 asset demands, we develop a general-equilibrium model driven by a single latent variable: heterogeneity in investors\u2019 confidence about mean endowment growth. The model predicts persistent heterogeneity in asset demands and concentrated portfolios. Consistent with the data, limited confidence reduces investors\u2019 demand elasticities and makes stock prices excessively volatile\u2014driven by latent demand rather than observable characteristics. The underlying economic mechanisms are driven primarily by investors\u2019 desire to hedge changes in future beliefs instead of current disagreement. Finally, consistent with survey data, investors\u2019 expectations correlate positively with past returns and negatively with future returns.", "date": "2026-04-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag041", "title_zh": "\u4fe1\u5fc3\u5f02\u8d28\u6027\u4e0b\u7684\u8d44\u4ea7\u9700\u6c42\u52a8\u6001", "abstract_zh": "\u4e3a\u4e86\u7406\u89e3\u6295\u8d44\u8005\u8d44\u4ea7\u9700\u6c42\u7684\u52a8\u6001\u8fc7\u7a0b\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u7531\u5355\u4e00\u6f5c\u5728\u53d8\u91cf\u9a71\u52a8\u7684\u4e00\u822c\u5747\u8861\u6a21\u578b\uff1a\u6295\u8d44\u8005\u5bf9\u672a\u6765\u6536\u5165\u589e\u957f\u9884\u671f\u7684\u5f02\u8d28\u6027\u3002\u8be5\u6a21\u578b\u9884\u6d4b\u8d44\u4ea7\u9700\u6c42\u4e2d\u5b58\u5728\u6301\u4e45\u7684\u5f02\u8d28\u6027\u4ee5\u53ca\u96c6\u4e2d\u5316\u7684\u6295\u8d44\u7ec4\u5408\u3002\u4e0e\u6570\u636e\u4e00\u81f4\uff0c\u4fe1\u5fc3\u4e0d\u8db3\u4f1a\u964d\u4f4e\u6295\u8d44\u8005\u5bf9\u8d44\u4ea7\u9700\u6c42\u7684\u5f39\u6027\uff0c\u5e76\u5bfc\u81f4\u80a1\u4ef7\u8fc7\u5ea6\u6ce2\u52a8\u2014\u2014\u8fd9\u79cd\u6ce2\u52a8\u6e90\u4e8e\u6f5c\u5728\u9700\u6c42\u800c\u975e\u53ef\u89c2\u5bdf\u7279\u5f81\u3002\u5176\u80cc\u540e\u7684\u7ecf\u6d4e\u673a\u5236\u4e3b\u8981\u6e90\u4e8e\u6295\u8d44\u8005\u5bf9\u5c06\u6765\u4fe1\u5ff5\u53d8\u5316\u7684\u98ce\u9669\u5bf9\u51b2\u9700\u6c42\uff0c\u800c\u975e\u5f53\u524d\u89c2\u70b9\u7684\u5206\u6b67\u3002\u6700\u540e\uff0c\u4e0e\u8c03\u67e5\u6570\u636e\u4e00\u81f4\uff0c\u6295\u8d44\u8005\u7684\u9884\u671f\u4e0e\u8fc7\u53bb\u6536\u76ca\u5448\u6b63\u76f8\u5173\uff0c\u4e0e\u672a\u6765\u6536\u76ca\u5448\u8d1f\u76f8\u5173\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag030", "journal": "REStud", "title": "Political Pressure on the Fed", "authors": ["Thomas Drechsel"], "author_details": [{"name": "Thomas Drechsel", "affiliations": ["University of Maryland, NBER & CEPR ,"]}], "abstract": "Abstract This paper combines new data and a narrative approach to identify variation in political pressure on the Federal Reserve. From archival records, I build a data set of personal interactions between U.S. Presidents and Fed officials between 1933 and 2016. Since personal interactions do not necessarily reflect political pressure, I develop a narrative identification strategy based on President Nixon\u2019s pressure on Fed Chair Burns. I exploit this narrative through restrictions on a structural vector autoregression that includes the President-Fed interaction data. I find that political pressure to ease monetary policy (i) increases the price level strongly and persistently, (ii) does not lead to positive effects on real economic activity, (iii) contributed to inflationary episodes outside of the Nixon era, and (iv) transmits differently from a typical monetary policy easing, by having a stronger effect on inflation expectations. Quantitatively, increasing political pressure by half as much as Nixon, for six months, raises the price level by about 7% over the following decade.", "date": "2026-04-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag030", "title_zh": "\u653f\u6cbb\u5bf9\u7f8e\u8054\u50a8\u7684\u538b\u529b", "abstract_zh": "\u672c\u6587\u7ed3\u5408\u65b0\u6570\u636e\u548c\u53d9\u4e8b\u65b9\u6cd5\uff0c\u8bc6\u522b\u51fa\u653f\u6cbb\u5bf9\u8054\u90a6\u50a8\u5907\u7cfb\u7edf\u538b\u529b\u7684\u5dee\u5f02\u3002\u4ece\u6863\u6848\u8bb0\u5f55\u4e2d\uff0c\u6211\u6784\u5efa\u4e861933\u5e74\u81f32016\u5e74\u95f4\u7f8e\u56fd\u603b\u7edf\u4e0e\u7f8e\u8054\u50a8\u5b98\u5458\u4e4b\u95f4\u4e2a\u4eba\u4e92\u52a8\u7684\u6570\u636e\u96c6\u3002\u7531\u4e8e\u4e2a\u4eba\u4e92\u52a8\u5e76\u4e0d\u4e00\u5b9a\u53cd\u6620\u653f\u6cbb\u538b\u529b\uff0c\u6211\u57fa\u4e8e\u5c3c\u514b\u677e\u5bf9\u7f8e\u8054\u50a8\u4e3b\u5e2d\u4f2f\u6069\u65af\u7684\u538b\u529b\u53d1\u5c55\u4e86\u4e00\u79cd\u53d9\u4e8b\u8bc6\u522b\u7b56\u7565\u3002\u6211\u901a\u8fc7\u5728\u5305\u542b\u603b\u7edf\u4e0e\u7f8e\u8054\u50a8\u4e92\u52a8\u6570\u636e\u7684\u7ed3\u6784\u5411\u91cf\u81ea\u56de\u5f52\u6a21\u578b\u4e2d\u65bd\u52a0\u9650\u5236\u6765\u5229\u7528\u8fd9\u4e00\u53d9\u4e8b\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u653f\u6cbb\u538b\u529b\u63a8\u52a8\u8d27\u5e01\u653f\u7b56\u653e\u677e\uff08i\uff09\u4f1a\u663e\u8457\u4e14\u6301\u4e45\u5730\u63a8\u9ad8\u4ef7\u683c\u6c34\u5e73\uff0c\uff08ii\uff09\u4e0d\u4f1a\u5bf9\u5b9e\u9645\u7ecf\u6d4e\u6d3b\u52a8\u4ea7\u751f\u79ef\u6781\u5f71\u54cd\uff0c\uff08iii\uff09\u4fc3\u6210\u4e86\u5c3c\u514b\u677e\u65f6\u4ee3\u4ee5\u5916\u7684\u901a\u80c0\u4e8b\u4ef6\uff0c\uff08iv\uff09\u5176\u4f20\u5bfc\u65b9\u5f0f\u4e0e\u5178\u578b\u7684\u8d27\u5e01\u653f\u7b56\u653e\u677e\u4e0d\u540c\uff0c\u5bf9\u901a\u80c0\u9884\u671f\u7684\u51b2\u51fb\u66f4\u5f3a\u3002\u5b9a\u91cf\u4e0a\uff0c\u82e5\u653f\u6cbb\u538b\u529b\u6bd4\u5c3c\u514b\u677e\u65f6\u671f\u9ad8\u51fa\u4e00\u534a\uff0c\u6301\u7eed\u516d\u4e2a\u6708\uff0c\u63a5\u4e0b\u6765\u5341\u5e74\u4ef7\u683c\u6c34\u5e73\u5c06\u4e0a\u5347\u7ea67%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag037", "journal": "RFS", "title": "Remeasuring Scale in Active Management", "authors": ["Shiyang Huang", "Xu Lu", "Yang Song", "Hong Xiang"], "author_details": [{"name": "Shiyang Huang", "affiliations": ["Faculty of Business and Economics (HKU Business School), The University of Hong Kong , Hong Kong"]}, {"name": "Xu Lu", "affiliations": ["Foster School of Business, The University of Washington , the United States"]}, {"name": "Yang Song", "affiliations": ["Foster School of Business, The University of Washington , the United States"]}, {"name": "Hong Xiang", "affiliations": ["School of Accounting and Finance, Faculty of Business (PolyU Business School), The Hong Kong Polytechnic University , Hong Kong"]}], "abstract": "Abstract We show that scale in active equity portfolios is understated by at least 65% because the majority of mutual funds have \u201ctwin\u201d institutional vehicles (IVs) managed under the same strategies. Omitting these IVs can severely skew crucial estimates in asset management research: by including IV assets, diminishing returns to scale of active investments is significantly reduced, and dollar value added of active strategies is more substantial and persistent than previously suggested. We further show that IV assets meaningfully influence managers\u2019 portfolio decisions. In addition, these measurement issues apply to common flow measures and extend to passive funds and bond funds.", "date": "2026-04-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag037", "title_zh": "\u91cd\u65b0\u8861\u91cf\u4e3b\u52a8\u7ba1\u7406\u4e2d\u7684\u89c4\u6a21", "abstract_zh": "\u6211\u4eec\u8868\u660e\uff0c\u4e3b\u52a8\u6743\u76ca\u6295\u8d44\u7ec4\u5408\u7684\u89c4\u6a21\u81f3\u5c11\u88ab\u4f4e\u4f30\u4e8665%\uff0c\u56e0\u4e3a\u5927\u591a\u6570\u5171\u540c\u57fa\u91d1\u90fd\u62e5\u6709\u7531\u76f8\u540c\u7b56\u7565\u7ba1\u7406\u7684\u201c\u53cc\u673a\u6784\u201d\u6295\u8d44\u5de5\u5177\uff08IVs\uff09\u3002\u5ffd\u7565\u8fd9\u4e9bIVs\u4f1a\u4e25\u91cd\u626d\u66f2\u8d44\u4ea7\u7ba1\u7406\u7814\u7a76\u4e2d\u7684\u5173\u952e\u4f30\u8ba1\u503c\uff1a\u901a\u8fc7\u7eb3\u5165IV\u8d44\u4ea7\uff0c\u4e3b\u52a8\u6295\u8d44\u7684\u89c4\u6a21\u62a5\u916c\u9012\u51cf\u6548\u5e94\u663e\u8457\u964d\u4f4e\uff0c\u4e14\u4e3b\u52a8\u7b56\u7565\u7684\u7f8e\u5143\u4ef7\u503c\u589e\u52a0\u66f4\u4e3a\u663e\u8457\u548c\u6301\u4e45\uff0c\u8fd9\u6bd4\u4ee5\u5f80\u6240\u8ba4\u4e3a\u7684\u66f4\u4e3a\u7a81\u51fa\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u8868\u660e\uff0cIV\u8d44\u4ea7\u5bf9\u57fa\u91d1\u7ecf\u7406\u7684\u7ec4\u5408\u51b3\u7b56\u5177\u6709\u5b9e\u8d28\u6027\u5f71\u54cd\u3002\u6b64\u5916\uff0c\u8fd9\u4e9b\u95ee\u9898\u540c\u6837\u9002\u7528\u4e8e\u5e38\u89c1\u7684\u6d41\u91cf\u6307\u6807\uff0c\u5e76\u5ef6\u4f38\u81f3\u88ab\u52a8\u57fa\u91d1\u548c\u503a\u5238\u57fa\u91d1\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1017/s0022109026102610", "journal": "JFQA", "title": "Star Firms, Information Spillovers, and Predictable Industry-Level Outcomes", "authors": ["Vidhi Chhaochharia", "Alok Kumar", "Mehrshad Motahari", "Ville Rantala"], "author_details": [{"name": "Vidhi Chhaochharia", "affiliations": ["University of Miami Herbert Business School"]}, {"name": "Alok Kumar", "affiliations": ["University of Miami Herbert Business School"]}, {"name": "Mehrshad Motahari", "affiliations": ["City St George\u2019s University of London Bayes Business School"]}, {"name": "Ville Rantala", "affiliations": ["University of Miami Herbert Business School"]}], "abstract": "Abstract We study the aggregate impact of information spillovers emerging from industry star firms. Changes in stars\u2019 relative earnings growth predict future earnings growth, consensus earnings surprises, and job postings of same-industry nonstar firms. Star-firm performance also predicts industry-level GDP and employment growth. Price markup and innovation spillovers are potential channels underlying these patterns. Our results further show that this performance predictability is not fully incorporated into nonstars\u2019 stock prices. A long\u2013short portfolio based on star firms\u2019 earnings growth earns an annualized 6-factor alpha of 8.7%. Together, our findings provide consistent evidence of the economic importance of star firms.", "date": "2026-04-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102610", "title_zh": "\u660e\u661f\u4f01\u4e1a\u3001\u4fe1\u606f\u6ea2\u51fa\u4e0e\u53ef\u9884\u6d4b\u7684\u884c\u4e1a\u5c42\u9762\u7ed3\u679c", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u6765\u81ea\u884c\u4e1a\u660e\u661f\u4f01\u4e1a\u7684\u4fe1\u606f\u6ea2\u51fa\u5bf9\u6574\u4f53\u7ecf\u6d4e\u7684\u5f71\u54cd\u3002\u660e\u661f\u4f01\u4e1a\u76f8\u5bf9\u6536\u76ca\u589e\u957f\u7684\u53d8\u5316\u53ef\u4ee5\u9884\u6d4b\u540c\u884c\u4e1a\u975e\u660e\u661f\u4f01\u4e1a\u7684\u672a\u6765\u6536\u76ca\u589e\u957f\u3001\u5171\u8bc6\u6536\u76ca\u610f\u5916\u60c5\u51b5\u4ee5\u53ca\u5c31\u4e1a\u5c97\u4f4d\u53d1\u5e03\u3002\u660e\u661f\u4f01\u4e1a\u7684\u8868\u73b0\u4e5f\u80fd\u591f\u9884\u6d4b\u6574\u4e2a\u884c\u4e1a\u7684GDP\u548c\u5c31\u4e1a\u589e\u957f\u3002\u4ef7\u683c\u6ea2\u4ef7\u548c\u521b\u65b0\u6ea2\u51fa\u53ef\u80fd\u662f\u8fd9\u4e9b\u73b0\u8c61\u80cc\u540e\u7684\u4f5c\u7528\u673a\u5236\u3002\u6211\u4eec\u7684\u7814\u7a76\u8fdb\u4e00\u6b65\u8868\u660e\uff0c\u8fd9\u79cd\u8868\u73b0\u53ef\u9884\u6d4b\u6027\u5e76\u672a\u5b8c\u5168\u53cd\u6620\u5728\u975e\u660e\u661f\u4f01\u4e1a\u7684\u80a1\u4ef7\u4e2d\u3002\u57fa\u4e8e\u660e\u661f\u4f01\u4e1a\u6536\u76ca\u589e\u957f\u6784\u5efa\u7684\u957f\u4ed3\u77ed\u4ed3\u7ec4\u5408\uff0c\u6bcf\u5e74\u83b7\u5f978.7%\u76846\u56e0\u5b50alpha\u6536\u76ca\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u53d1\u73b0\u4e3a\u660e\u661f\u4f01\u4e1a\u7684\u7ecf\u6d4e\u91cd\u8981\u6027\u63d0\u4f9b\u4e86\u6301\u7eed\u4e00\u81f4\u7684\u8bc1\u636e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhag019", "journal": "RFS", "title": "Mutual Fund Clienteles", "authors": ["Daniel Fricke", "Stephan Jank", "Hannes Wilke"], "author_details": [{"name": "Daniel Fricke", "affiliations": ["Deutsche Bundesbank ,"]}, {"name": "Stephan Jank", "affiliations": ["Deutsche Bundesbank ,"]}, {"name": "Hannes Wilke", "affiliations": ["Deutsche Bundesbank ,"]}], "abstract": "Abstract Using a unique data set on the ownership composition of euro area equity funds, we find substantial differences in the flow-performance sensitivity across mutual fund clienteles. Households, followed by insurers, display the weakest sensitivity, whereas investment funds\u2014as investors in mutual funds\u2014exhibit the strongest sensitivity. Crucially, these behavioral differences hold within the same fund-quarter, ruling out heterogeneity across funds as a potential driver. We relate these clientele effects to monitoring incentives and balance sheet constraints. Lastly, we find that households respond more strongly to poor performance when surrounded by more performance-sensitive investors, indicating strategic interactions in investor flows.", "date": "2026-04-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag019", "title_zh": "\u5171\u540c\u57fa\u91d1\u5ba2\u6237\u7fa4", "abstract_zh": "\u5229\u7528\u4e00\u4e2a\u5173\u4e8e\u6b27\u5143\u533a\u80a1\u7968\u57fa\u91d1\u6240\u6709\u6743\u7ed3\u6784\u7684\u72ec\u7279\u6570\u636e\u96c6\uff0c\u6211\u4eec\u53d1\u73b0\u4e0d\u540c\u5171\u540c\u57fa\u91d1\u5ba2\u6237\u7fa4\u5728\u6d41\u52a8\u6027\u548c\u8868\u73b0\u654f\u611f\u6027\u65b9\u9762\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002\u5bb6\u5ead\u6295\u8d44\u8005\u548c\u4fdd\u9669\u673a\u6784\u8868\u73b0\u51fa\u6700\u5f31\u7684\u654f\u611f\u6027\uff0c\u800c\u4f5c\u4e3a\u5171\u540c\u57fa\u91d1\u6295\u8d44\u8005\u7684\u6295\u8d44\u57fa\u91d1\u5219\u8868\u73b0\u51fa\u6700\u5f3a\u7684\u654f\u611f\u6027\u3002\u5173\u952e\u7684\u662f\uff0c\u8fd9\u4e9b\u884c\u4e3a\u5dee\u5f02\u5728\u540c\u4e00\u53ea\u57fa\u91d1\u7684\u540c\u4e00\u5b63\u5ea6\u5185\u4ecd\u7136\u6210\u7acb\uff0c\u6392\u9664\u4e86\u57fa\u91d1\u95f4\u5f02\u8d28\u6027\u4f5c\u4e3a\u6f5c\u5728\u9a71\u52a8\u56e0\u7d20\u7684\u53ef\u80fd\u6027\u3002\u6211\u4eec\u5c06\u8fd9\u4e9b\u5ba2\u6237\u7fa4\u6548\u5e94\u4e0e\u76d1\u7763\u6fc0\u52b1\u548c\u8d44\u4ea7\u8d1f\u503a\u7ea6\u675f\u8054\u7cfb\u8d77\u6765\u3002\u6b64\u5916\uff0c\u6211\u4eec\u53d1\u73b0\u5f53\u5bb6\u5ead\u6295\u8d44\u8005\u5468\u56f4\u5b58\u5728\u66f4\u591a\u5bf9\u8868\u73b0\u654f\u611f\u7684\u6295\u8d44\u8005\u65f6\uff0c\u4ed6\u4eec\u5bf9\u8868\u73b0\u4e0d\u4f73\u7684\u53cd\u5e94\u66f4\u4e3a\u5f3a\u70c8\uff0c\u8868\u660e\u6295\u8d44\u8005\u6d41\u52a8\u4e4b\u95f4\u5b58\u5728\u6218\u7565\u4e92\u52a8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1093/rfs/hhag029", "journal": "RFS", "title": "New Frontiers in Household Finance", "authors": ["Francisco Gomes", "Michael Haliassos", "Tarun Ramadorai"], "author_details": [{"name": "Francisco Gomes", "affiliations": ["London Business School and CEPR ,"]}, {"name": "Michael Haliassos", "affiliations": ["Goethe University Frankfurt and CEPR ,"]}, {"name": "Tarun Ramadorai", "affiliations": ["London School of Economics, Imperial College Business School, and CEPR ,"]}], "abstract": "Abstract We present and discuss the papers in this special issue. We use the themes that these papers study to illustrate interesting new directions that are being pursued in the household finance literature and highlight open questions on which more work is needed.", "date": "2026-04-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag029", "title_zh": "\u5bb6\u5ead\u91d1\u878d\u7684\u65b0\u524d\u6cbf", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u4ecb\u7ecd\u4e86\u5e76\u8ba8\u8bba\u4e86\u672c\u7279\u520a\u4e2d\u7684\u8bba\u6587\u3002\u6211\u4eec\u901a\u8fc7\u8fd9\u4e9b\u8bba\u6587\u7814\u7a76\u7684\u4e3b\u9898\uff0c\u5c55\u793a\u4e86\u5bb6\u5ead\u91d1\u878d\u6587\u732e\u4e2d\u6b63\u5728\u63a2\u7d22\u7684\u4e00\u4e9b\u6709\u8da3\u65b0\u65b9\u5411\uff0c\u5e76\u6307\u51fa\u4e86\u5c1a\u9700\u8fdb\u4e00\u6b65\u7814\u7a76\u7684\u5f00\u653e\u6027\u95ee\u9898\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s002210902610283x", "journal": "JFQA", "title": "Shaped by Confucius: The Cultural Origin of Corporate Behavior", "authors": ["Zhihui Gu", "Hao Liang", "Hanyu Zhang"], "author_details": [{"name": "Zhihui Gu", "affiliations": ["Nankai University Business School"]}, {"name": "Hao Liang", "affiliations": ["Singapore Management University"]}, {"name": "Hanyu Zhang", "affiliations": ["Nankai University Business School"]}], "abstract": "Abstract We examine how Confucian culture operates as an informal institution by fostering relational contracts that substitute for formal legal frameworks in shaping corporate behavior. Using data on historical Confucian academies near firms\u2019 headquarters in China, we find that greater cultural exposure is associated with higher investment in stakeholder relationships\u2014measured by social contribution, stakeholder protection, courtesy expenses, patenting, and trade credit. These effects persist after controlling for human capital and alternative cultural influences, and weaken in regions with stronger formal institutions. Our findings highlight the enduring role of culture in supporting trust-based governance when formal contracting is limited.", "date": "2026-04-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s002210902610283x", "title_zh": "\u5b54\u5b50\u7684\u5f71\u54cd\uff1a\u4f01\u4e1a\u884c\u4e3a\u7684\u6587\u5316\u8d77\u6e90", "abstract_zh": "\u6211\u4eec\u8003\u5bdf\u4e86\u5112\u5bb6\u6587\u5316\u5982\u4f55\u4f5c\u4e3a\u4e00\u79cd\u975e\u6b63\u5f0f\u5236\u5ea6\uff0c\u901a\u8fc7\u4fc3\u8fdb\u5173\u7cfb\u578b\u5408\u540c\u6765\u66ff\u4ee3\u6b63\u5f0f\u6cd5\u5f8b\u6846\u67b6\uff0c\u4ece\u800c\u5851\u9020\u4f01\u4e1a\u884c\u4e3a\u3002\u5229\u7528\u4e2d\u56fd\u516c\u53f8\u603b\u90e8\u9644\u8fd1\u5386\u53f2\u5112\u5bb6\u5b66\u5e9c\u7684\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u6587\u5316\u63a5\u89e6\u7a0b\u5ea6\u8d8a\u9ad8\uff0c\u4f01\u4e1a\u5bf9\u5229\u76ca\u76f8\u5173\u8005\u7684\u6295\u5165\u5c31\u8d8a\u9ad8\u2014\u2014\u8fd9\u4e00\u6307\u6807\u5305\u62ec\u793e\u4f1a\u8d21\u732e\u3001\u5229\u76ca\u76f8\u5173\u8005\u4fdd\u62a4\u3001\u793c\u8c8c\u652f\u51fa\u3001\u4e13\u5229\u7533\u8bf7\u548c\u8d38\u6613\u4fe1\u7528\u3002\u8fd9\u4e9b\u6548\u5e94\u5728\u63a7\u5236\u4e86\u4eba\u529b\u8d44\u672c\u548c\u5176\u5b83\u6587\u5316\u5f71\u54cd\u56e0\u7d20\u540e\u4ecd\u7136\u5b58\u5728\uff0c\u5e76\u5728\u6b63\u5f0f\u5236\u5ea6\u8f83\u5f3a\u7684\u5730\u533a\u6709\u6240\u51cf\u5f31\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u51f8\u663e\u4e86\u6587\u5316\u5728\u6b63\u5f0f\u5408\u540c\u6709\u9650\u7684\u60c5\u51b5\u4e0b\uff0c\u652f\u6301\u57fa\u4e8e\u4fe1\u4efb\u7684\u6cbb\u7406\u6240\u53d1\u6325\u7684\u6301\u4e45\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag027", "journal": "REStud", "title": "The Confederate Diaspora", "authors": ["Samuel Bazzi", "Andreas Ferrara", "Martin Fiszbein", "Thomas Pearson", "Patrick A Testa"], "author_details": [{"name": "Samuel Bazzi", "affiliations": ["UC San Diego, School of Global Policy and Strategy and Department of Economics, CEPR, and NBER ,"]}, {"name": "Andreas Ferrara", "affiliations": ["Department of Economics, University of Pittsburgh, and NBER ,"]}, {"name": "Martin Fiszbein", "affiliations": ["Department of Economics, Boston University, and NBER ,"]}, {"name": "Thomas Pearson", "affiliations": ["Department of Economics, Syracuse University ,"]}, {"name": "Patrick A Testa", "affiliations": ["Department of Economics and the Murphy Institute, Tulane University, and NBER ,"]}], "abstract": "Abstract This paper develops a new framework for understanding when and how migrants shape culture, applying it to the Confederate diaspora\u2014a small migrant group that left a large cultural imprint. Southern Whites that migrated after the Civil War played a pivotal role in spreading Confederate symbols and racial norms across the U.S. by the early 20th century. Their far-reaching influence stemmed from two key conditions: (i) an ideological intensity rooted in their experiences of slavery, secession, and military defeat and (ii) access to malleable power structures during westward expansion and post-war reconciliation. These conditions enabled them to transmit Confederate culture to both kin and non-Southern neighbours and to expand their reach by mobilising civil society organisation and leveraging positions of authority. They shaped policies and institutions that helped entrench racial norms and inequalities in labour markets, housing, and the criminal justice system. Our findings provide empirical foundations for understanding how migrants can transform local culture, rather than merely assimilate.", "date": "2026-04-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag027", "title_zh": "\u90a6\u8054\u6d41\u6563\u7fa4\u4f53", "abstract_zh": "\u672c\u6587\u63d0\u51fa\u4e00\u4e2a\u65b0\u6846\u67b6\uff0c\u7528\u4ee5\u7406\u89e3\u79fb\u6c11\u5728\u4f55\u65f6\u4ee5\u53ca\u5982\u4f55\u5851\u9020\u6587\u5316\uff0c\u5c06\u5176\u5e94\u7528\u4e8e\u90a6\u8054\u6d41\u6563\u7fa4\u4f53\u2014\u2014\u4e00\u4e2a\u89c4\u6a21\u8f83\u5c0f\u4f46\u5bf9\u6587\u5316\u4ea7\u751f\u4e86\u6df1\u8fdc\u5f71\u54cd\u7684\u79fb\u6c11\u7fa4\u4f53\u3002\u5185\u6218\u540e\u8fc1\u5f99\u81f3\u7f8e\u56fd\u7684\u5357\u65b9\u767d\u4eba\uff0c\u572820\u4e16\u7eaa\u521d\u53d1\u6325\u4e86\u5173\u952e\u4f5c\u7528\uff0c\u5c06\u90a6\u8054\u8c61\u5f81\u548c\u79cd\u65cf\u89c4\u8303\u4f20\u64ad\u81f3\u5168\u7f8e\u5404\u5730\u3002\u4ed6\u4eec\u7684\u5e7f\u6cdb\u5f71\u54cd\u6e90\u4e8e\u4e24\u4e2a\u5173\u952e\u6761\u4ef6\uff1a\uff08i\uff09\u6839\u690d\u4e8e\u5974\u96b6\u5236\u3001\u8131\u79bb\u8054\u90a6\u548c\u519b\u4e8b\u5931\u8d25\u7ecf\u5386\u4e2d\u7684\u5f3a\u70c8\u610f\u8bc6\u5f62\u6001\uff1b\uff08ii\uff09\u5728\u5411\u897f\u6269\u5f20\u53ca\u6218\u540e\u548c\u89e3\u8fc7\u7a0b\u4e2d\uff0c\u80fd\u591f\u63a5\u89e6\u5230\u53ef\u5851\u7684\u6743\u529b\u7ed3\u6784\u3002\u8fd9\u4e9b\u6761\u4ef6\u4f7f\u4ed6\u4eec\u80fd\u591f\u5c06\u90a6\u8054\u6587\u5316\u4f20\u9012\u7ed9\u4eb2\u5c5e\u548c\u975e\u5357\u65b9\u90bb\u5c45\uff0c\u5e76\u901a\u8fc7\u52a8\u5458\u6c11\u95f4\u793e\u4f1a\u7ec4\u7ec7\u4ee5\u53ca\u5229\u7528\u6743\u5a01\u5730\u4f4d\u6269\u5927\u5f71\u54cd\u529b\u3002\u4ed6\u4eec\u5851\u9020\u4e86\u76f8\u5173\u653f\u7b56\u548c\u5236\u5ea6\uff0c\u6709\u52a9\u4e8e\u5728\u52b3\u52a8\u529b\u5e02\u573a\u3001\u4f4f\u623f\u4ee5\u53ca\u53f8\u6cd5\u7cfb\u7edf\u4e2d\u56fa\u5316\u79cd\u65cf\u89c4\u8303\u4e0e\u4e0d\u5e73\u7b49\u3002\u672c\u7814\u7a76\u4e3a\u7406\u89e3\u79fb\u6c11\u5982\u4f55\u6539\u53d8\u5f53\u5730\u6587\u5316\uff0c\u800c\u975e\u7b80\u5355\u5730\u540c\u5316\uff0c\u63d0\u4f9b\u4e86\u5b9e\u8bc1\u57fa\u7840\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag035", "journal": "RFS", "title": "Voting and Trading on Public Information", "authors": ["Markus Parlasca", "Paul Voss"], "author_details": [{"name": "Markus Parlasca", "affiliations": ["WU Vienna University of Economics and Business and Vienna Graduate School of Finance , ,", "Leibniz Institute for Financial Research SAFE, Germany, and Finance Theory Group , ,"]}, {"name": "Paul Voss", "affiliations": ["HEC Paris, France, and Finance Theory Group"]}], "abstract": "Abstract This paper studies how public information, such as proxy advice, affects shareholder voting and, thus, corporate decision-making. We find that while public information improves the voting decisions of uninformed shareholders, it also induces privately informed shareholders to exit rather than to exercise their voice (vote). As a result, public information impairs information aggregation by voting but improves information aggregation by trading. Overall, public information can undermine corporate decision-making. Furthermore, slightly more precise public information can lead to a discontinuous reduction in firm value. Our results give rise to new empirical predictions and have implications for regulation.", "date": "2026-04-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag035", "title_zh": "\u5173\u4e8e\u516c\u5171\u4fe1\u606f\u5bf9\u6295\u7968\u4e0e\u4ea4\u6613\u7684\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u516c\u5171\u4fe1\u606f\uff08\u5982\u80a1\u4e1c\u5efa\u8bae\uff09\u5982\u4f55\u5f71\u54cd\u80a1\u4e1c\u6295\u7968\uff0c\u4ece\u800c\u5f71\u54cd\u4f01\u4e1a\u51b3\u7b56\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5c3d\u7ba1\u516c\u5171\u4fe1\u606f\u6539\u5584\u4e86\u672a\u83b7\u5145\u5206\u4fe1\u606f\u80a1\u4e1c\u7684\u6295\u7968\u51b3\u7b56\uff0c\u4f46\u5b83\u4e5f\u4fc3\u4f7f\u62e5\u6709\u79c1\u6709\u4fe1\u606f\u7684\u80a1\u4e1c\u9009\u62e9\u9000\u51fa\u800c\u975e\u884c\u4f7f\u6295\u7968\u6743\u3002\u56e0\u6b64\uff0c\u516c\u5171\u4fe1\u606f\u4f1a\u524a\u5f31\u901a\u8fc7\u6295\u7968\u5b9e\u73b0\u7684\u4fe1\u606f\u805a\u5408\uff0c\u4f46\u4f1a\u63d0\u5347\u901a\u8fc7\u4ea4\u6613\u5b9e\u73b0\u7684\u4fe1\u606f\u805a\u5408\u3002\u603b\u4f53\u800c\u8a00\uff0c\u516c\u5171\u4fe1\u606f\u53ef\u80fd\u635f\u5bb3\u4f01\u4e1a\u51b3\u7b56\u3002\u6b64\u5916\uff0c\u7a0d\u4e3a\u7cbe\u786e\u7684\u516c\u5171\u4fe1\u606f\u53ef\u80fd\u5bfc\u81f4\u516c\u53f8\u4ef7\u503c\u51fa\u73b0\u4e0d\u8fde\u7eed\u7684\u4e0b\u964d\u3002\u6211\u4eec\u7684\u7ed3\u679c\u63d0\u51fa\u4e86\u65b0\u7684\u5b9e\u8bc1\u9884\u6d4b\uff0c\u5e76\u5bf9\u4f01\u4e1a\u76d1\u7ba1\u5177\u6709\u91cd\u8981\u542f\u793a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102841", "journal": "JFQA", "title": "Blockchain Currency Markets", "authors": ["Angelo Ranaldo", "Ganesh Viswanath-Natraj", "Junxuan Wang"], "author_details": [{"name": "Angelo Ranaldo", "affiliations": ["University of Basel and Swiss Finance Institute"]}, {"name": "Ganesh Viswanath-Natraj", "affiliations": ["Warwick Business School and Gillmore Centre for Financial Technology"]}, {"name": "Junxuan Wang", "affiliations": ["Hong Kong University of Science and Technology (Guangzhou)"]}], "abstract": "Abstract We conduct the first comprehensive study of blockchain currencies\u2014stablecoins pegged to fiat currencies and traded on decentralized exchanges (DEXs). Using transaction-level data linked to wallet characteristics, we show that prices in these markets are generally efficient, though constrained by blockchain frictions such as gas fees and Ether volatility. DEX rates closely track traditional currency markets through arbitrage and informed trading. Traders with substantial market share and access to primary markets exert greater price impact, reflecting informational advantages. While blockchain markets may improve access for customers excluded from traditional venues, their scalability depends on addressing frictions inherent to decentralized trading.", "date": "2026-04-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102841", "title_zh": "\u533a\u5757\u94fe\u8d27\u5e01\u5e02\u573a", "abstract_zh": "\u6211\u4eec\u5bf9\u533a\u5757\u94fe\u8d27\u5e01\u2014\u2014\u5373\u4e0e\u6cd5\u5e01\u6302\u94a9\u7684\u7a33\u5b9a\u5e01\uff0c\u5e76\u5728\u53bb\u4e2d\u5fc3\u5316\u4ea4\u6613\u6240\uff08DEX\uff09\u4e0a\u4ea4\u6613\u2014\u2014\u8fdb\u884c\u4e86\u9996\u6b21\u5168\u9762\u7814\u7a76\u3002\u5229\u7528\u4e0e\u94b1\u5305\u7279\u5f81\u5173\u8054\u7684\u4ea4\u6613\u7ea7\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u8fd9\u4e9b\u5e02\u573a\u7684\u4ef7\u683c\u603b\u4f53\u4e0a\u662f\u9ad8\u6548\u7684\uff0c\u4f46\u53d7\u5230\u533a\u5757\u94fe\u6469\u64e6\uff08\u5982Gas\u8d39\u7528\u548c\u4ee5\u592a\u5e01\u6ce2\u52a8\u6027\uff09\u7684\u9650\u5236\u3002\u53bb\u4e2d\u5fc3\u5316\u4ea4\u6613\u6240\u7684\u4ea4\u6613\u4ef7\u683c\u901a\u8fc7\u5957\u5229\u548c\u77e5\u60c5\u4ea4\u6613\u7d27\u5bc6\u8ddf\u8e2a\u4f20\u7edf\u8d27\u5e01\u5e02\u573a\u3002\u62e5\u6709\u8f83\u5927\u5e02\u573a\u4efd\u989d\u5e76\u80fd\u8bbf\u95ee\u4e00\u7ea7\u5e02\u573a\u7684\u4ea4\u6613\u8005\u5bf9\u4ef7\u683c\u4ea7\u751f\u66f4\u5927\u5f71\u54cd\uff0c\u53cd\u6620\u51fa\u5176\u4fe1\u606f\u4f18\u52bf\u3002\u5c3d\u7ba1\u533a\u5757\u94fe\u5e02\u573a\u53ef\u80fd\u4e3a\u4f20\u7edf\u6e20\u9053\u4e2d\u88ab\u6392\u9664\u7684\u5ba2\u6237\u5e26\u6765\u66f4\u5e7f\u6cdb\u7684\u53c2\u4e0e\u673a\u4f1a\uff0c\u4f46\u5176\u53ef\u6269\u5c55\u6027\u53d6\u51b3\u4e8e\u89e3\u51b3\u53bb\u4e2d\u5fc3\u5316\u4ea4\u6613\u56fa\u6709\u7684\u6469\u64e6\u95ee\u9898\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102798", "journal": "JFQA", "title": "Social Capital and the Boundary of the Firm: Evidence from Relationship-Specific Investments", "authors": ["Jarrad Harford", "Xing Li", "Jiaren Pang", "Haibin Wu", "Liu Zheng"], "author_details": [{"name": "Jarrad Harford", "affiliations": ["University of Washington Foster School of Business"]}, {"name": "Xing Li", "affiliations": ["University of Science and Technology of China Faculty of Business for Science and Technology, School of Management"]}, {"name": "Jiaren Pang", "affiliations": ["Tsinghua University School of Economics and Management"]}, {"name": "Haibin Wu", "affiliations": ["City University of Hong Kong College of Business"]}, {"name": "Liu Zheng", "affiliations": ["City University of Hong Kong College of Business"]}], "abstract": "Abstract We investigate the role of social capital in mitigating hold-up problems along the supply chain. We find that supplier firms are more willing to make relationship-specific investments (proxied by their citations to customers\u2019 patents) when transacting with customers headquartered in high social capital areas. This effect is more pronounced when the potential for expropriation by the customer is greatest: when the supplier has a weak bargaining position, faces high asset specificity, or the customer is in poor financial condition. High social capital firms are less vertically integrated and are more likely to form (longer-lasting) trading relationships with each other.", "date": "2026-04-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102798", "title_zh": "\u793e\u4f1a\u8d44\u672c\u4e0e\u4f01\u4e1a\u8fb9\u754c\uff1a\u6765\u81ea\u5173\u7cfb\u7279\u5b9a\u6295\u8d44\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u793e\u4f1a\u8d44\u672c\u5728\u7f13\u89e3\u4f9b\u5e94\u94fe\u4e2d\u642d\u4fbf\u8f66\u95ee\u9898\u4e2d\u7684\u4f5c\u7528\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5f53\u4f9b\u5e94\u5546\u4e0e\u603b\u90e8\u4f4d\u4e8e\u9ad8\u793e\u4f1a\u8d44\u672c\u533a\u57df\u7684\u5ba2\u6237\u4ea4\u6613\u65f6\uff0c\u66f4\u613f\u610f\u8fdb\u884c\u5173\u7cfb\u7279\u5b9a\u6295\u8d44\uff08\u4ee5\u5bf9\u5ba2\u6237\u4e13\u5229\u7684\u5f15\u7528\u6570\u91cf\u4f5c\u4e3a\u4ee3\u7406\u53d8\u91cf\uff09\u3002\u8fd9\u79cd\u6548\u5e94\u5728\u5ba2\u6237\u5b58\u5728\u6700\u5927\u63a0\u593a\u98ce\u9669\u65f6\u66f4\u4e3a\u663e\u8457\uff1a\u5f53\u4f9b\u5e94\u5546\u5904\u4e8e\u5f31\u52bf\u8c08\u5224\u5730\u4f4d\u3001\u9762\u4e34\u9ad8\u8d44\u4ea7\u4e13\u7528\u6027\uff0c\u6216\u5ba2\u6237\u8d22\u52a1\u72b6\u51b5\u4e0d\u4f73\u65f6\u3002\u793e\u4f1a\u8d44\u672c\u8f83\u9ad8\u7684\u4f01\u4e1a\u66f4\u5c11\u8fdb\u884c\u7eb5\u5411\u6574\u5408\uff0c\u5e76\u66f4\u53ef\u80fd\u4e0e\u5f7c\u6b64\u5efa\u7acb\uff08\u957f\u671f\u6301\u7eed\u7684\uff09\u4ea4\u6613\u5173\u7cfb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/qje/qjag020", "journal": "QJE", "title": "Collusion with Optimal Information Disclosure", "authors": ["Takuo Sugaya", "Alexander Wolitzky"], "author_details": [{"name": "Takuo Sugaya", "affiliations": ["Stanford Graduate School of Business ,"]}, {"name": "Alexander Wolitzky", "affiliations": ["Massachusetts Institute of Technology ,"]}], "abstract": "Abstract Motivated by recent concerns surrounding the use of third-party pricing algorithms by competing firms, we study repeated Bertrand competition where market demand or the cost of serving the market is observed by an intermediary (or \u201calgorithm\u201d) that selectively discloses demand or cost information to maximize firms\u2019 collusive profit. We show that an upper censorship disclosure policy is optimal, which leads to price rigidity and supra-monopoly prices in some states. Improving the algorithm\u2019s accuracy reduces expected consumer surplus whenever it does so under monopoly pricing. When the state is positively correlated over time, the algorithm discloses more information when recent demand was lower or costs were higher. The analysis extends to a generalized model that accommodates product differentiation and capacity constraints. We relate our findings to recent antitrust cases.", "date": "2026-04-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag020", "title_zh": "\u6700\u4f18\u4fe1\u606f\u62ab\u9732\u4e0b\u7684\u5408\u8c0b\u884c\u4e3a", "abstract_zh": "\u6458\u8981 \u9488\u5bf9\u8fd1\u671f\u5173\u4e8e\u7ade\u4e89\u4f01\u4e1a\u4f7f\u7528\u7b2c\u4e09\u65b9\u5b9a\u4ef7\u7b97\u6cd5\u7684\u62c5\u5fe7\uff0c\u6211\u4eec\u7814\u7a76\u4e86\u91cd\u590d\u7684\u4f2f\u7279\u5170\u7ade\u4e89\u6a21\u578b\uff0c\u5176\u4e2d\u5e02\u573a\u9700\u6c42\u6216\u670d\u52a1\u5e02\u573a\u7684\u6210\u672c\u7531\u4e00\u4e2a\u4e2d\u4ecb\uff08\u6216\u201c\u7b97\u6cd5\u201d\uff09\u89c2\u5bdf\uff0c\u5e76\u9009\u62e9\u6027\u5730\u62ab\u9732\u9700\u6c42\u6216\u6210\u672c\u4fe1\u606f\u4ee5\u6700\u5927\u5316\u4f01\u4e1a\u5408\u8c0b\u5229\u6da6\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u4e0a\u754c\u5c01\u9501\u62ab\u9732\u7b56\u7565\u662f\u6700\u4f18\u7684\uff0c\u8fd9\u5728\u67d0\u4e9b\u72b6\u6001\u4e0b\u5bfc\u81f4\u4ef7\u683c\u521a\u6027\u4ee5\u53ca\u8d85\u8fc7\u5784\u65ad\u6c34\u5e73\u7684\u4ef7\u683c\u3002\u5f53\u7b97\u6cd5\u7684\u51c6\u786e\u6027\u63d0\u5347\u65f6\uff0c\u53ea\u8981\u5176\u5728\u5784\u65ad\u5b9a\u4ef7\u4e0b\u63d0\u5347\uff0c\u6d88\u8d39\u8005\u5269\u4f59\u7684\u9884\u671f\u5c31\u4f1a\u4e0b\u964d\u3002\u5f53\u72b6\u6001\u5728\u65f6\u95f4\u4e0a\u5448\u6b63\u76f8\u5173\u65f6\uff0c\u7b97\u6cd5\u5728\u8fd1\u671f\u9700\u6c42\u8f83\u4f4e\u6216\u6210\u672c\u8f83\u9ad8\u7684\u60c5\u51b5\u4e0b\u62ab\u9732\u66f4\u591a\u4fe1\u606f\u3002\u8be5\u5206\u6790\u6269\u5c55\u5230\u4e00\u4e2a\u66f4\u4e00\u822c\u7684\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u5305\u542b\u4e86\u4ea7\u54c1\u5dee\u5f02\u5316\u548c\u4ea7\u80fd\u7ea6\u675f\u3002\u6211\u4eec\u8fd8\u5c06\u7814\u7a76\u7ed3\u679c\u4e0e\u8fd1\u671f\u7684\u53cd\u5784\u65ad\u6848\u4ef6\u8054\u7cfb\u8d77\u6765\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag021", "journal": "QJE", "title": "Codification, Technology Absorption, and the Globalization of the Industrial Revolution", "authors": ["R\u00e9ka Juh\u00e1sz", "Shogo Sakabe", "David E Weinstein"], "author_details": [{"name": "R\u00e9ka Juh\u00e1sz", "affiliations": ["University of British Columbia ,", "Centre for Economic Policy Research ,", "National Bureau of Economic Research ,"]}, {"name": "Shogo Sakabe", "affiliations": ["AI Lab, CyberAgent ,"]}, {"name": "David E Weinstein", "affiliations": ["Columbia University and National Bureau of Economic Research ,", "Centre for Economic Policy Research ,"]}], "abstract": "Abstract This article examines the global adoption of technology in the late nineteenth century. We construct several novel data sets to test the idea that the codification of technical knowledge in the vernacular was necessary for countries to absorb the technologies of the first Industrial Revolution. We find that comparative advantage shifted to industries that could benefit from these technologies in countries and colonies with access to codified technical knowledge, but not in other regions. Using the rapid and unprecedented codification of technical knowledge in Meiji Japan as a natural experiment, we show that this pattern emerged only after the Japanese government codified vast amounts of technical knowledge. Our findings shed new light on the frictions associated with technological diffusion and offer a novel explanation for why Meiji Japan was unique among non-Western countries in successfully industrializing during the first wave of globalization.", "date": "2026-04-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag021", "title_zh": "\u7f16\u7801\u3001\u6280\u672f\u5438\u6536\u4e0e\u5de5\u4e1a\u9769\u547d\u7684\u5168\u7403\u5316", "abstract_zh": "\u672c\u6587\u8003\u5bdf\u4e8619\u4e16\u7eaa\u540e\u671f\u6280\u672f\u5728\u5168\u7403\u8303\u56f4\u5185\u7684\u91c7\u7eb3\u60c5\u51b5\u3002\u6211\u4eec\u6784\u5efa\u4e86\u51e0\u4e2a\u65b0\u7684\u6570\u636e\u96c6\uff0c\u4ee5\u68c0\u9a8c\u6280\u672f\u77e5\u8bc6\u5728\u672c\u5730\u8bed\u8a00\u4e2d\u7684\u7f16\u7801\u662f\u5426\u662f\u56fd\u5bb6\u5438\u6536\u7b2c\u4e00\u6b21\u5de5\u4e1a\u9769\u547d\u6280\u672f\u6240\u5fc5\u9700\u7684\u6761\u4ef6\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u6bd4\u8f83\u4f18\u52bf\u8f6c\u79fb\u5230\u80fd\u591f\u4ece\u8fd9\u4e9b\u6280\u672f\u4e2d\u83b7\u76ca\u7684\u4ea7\u4e1a\uff0c\u4ec5\u51fa\u73b0\u5728\u62e5\u6709\u7f16\u7801\u6280\u672f\u77e5\u8bc6\u7684\u56fd\u5bb6\u548c\u6b96\u6c11\u5730\uff0c\u800c\u5728\u5176\u4ed6\u5730\u533a\u5219\u672a\u51fa\u73b0\u8fd9\u79cd\u8f6c\u79fb\u3002\u5229\u7528\u660e\u6cbb\u65f6\u671f\u65e5\u672c\u6280\u672f\u77e5\u8bc6\u8fc5\u901f\u4e14\u5927\u89c4\u6a21\u7f16\u7801\u7684\u81ea\u7136\u5b9e\u9a8c\uff0c\u6211\u4eec\u8bc1\u660e\uff0c\u8fd9\u79cd\u6a21\u5f0f\u4ec5\u5728\u65e5\u672c\u653f\u5e9c\u5927\u89c4\u6a21\u7f16\u7801\u5927\u91cf\u6280\u672f\u77e5\u8bc6\u4e4b\u540e\u624d\u51fa\u73b0\u3002\u672c\u7814\u7a76\u4e3a\u6280\u672f\u6269\u6563\u8fc7\u7a0b\u4e2d\u5b58\u5728\u7684\u6469\u64e6\u63d0\u4f9b\u4e86\u65b0\u7684\u89c1\u89e3\uff0c\u5e76\u4e3a\u660e\u6cbb\u65e5\u672c\u4f5c\u4e3a\u975e\u897f\u65b9\u56fd\u5bb6\u4e2d\u552f\u4e00\u5728\u7b2c\u4e00\u6b21\u5168\u7403\u5316\u6d6a\u6f6e\u4e2d\u6210\u529f\u5b9e\u73b0\u5de5\u4e1a\u5316\u7684\u56fd\u5bb6\u63d0\u4f9b\u4e86\u65b0\u9896\u7684\u89e3\u91ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102762", "journal": "JFQA", "title": "Financial Consequences of the Belt and Road Initiative", "authors": ["Mehmet Ihsan Canayaz"], "author_details": [{"name": "Mehmet Ihsan Canayaz", "affiliations": ["Pennsylvania State University Smeal College of Business and University of Cincinnati Carl H. Lindner College of Business"]}], "abstract": "Abstract China\u2019s Belt and Road Initiative (BRI) aims to create economic corridors encompassing two-thirds of the world\u2019s population and 40% of global GDP. Using the inauguration of a railway tunnel between Europe and Asia as a quasi-natural experiment, I demonstrate that countries gaining access to BRI\u2019s freight routes issue significant amounts of high-yield debt. This debt is largely absorbed domestically, reallocating capital away from firms without translating into infrastructure investment. State-owned enterprises appear insulated from tightening financial conditions. I document mechanisms involving political alignment with China, exposure to trade policy uncertainty, and topographic fit based on historical Orient Express routes.", "date": "2026-04-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102762", "title_zh": "\u4e00\u5e26\u4e00\u8def\u5021\u8bae\u7684\u91d1\u878d\u5f71\u54cd", "abstract_zh": "\u4e2d\u56fd\u7684\u4e00\u5e26\u4e00\u8def\u5021\u8bae\uff08BRI\uff09\u65e8\u5728\u6784\u5efa\u8986\u76d6\u5168\u7403\u4e09\u5206\u4e4b\u4e8c\u4eba\u53e3\u548c40%\u5168\u7403GDP\u7684\u7ecf\u6d4e\u8d70\u5eca\u3002\u5229\u7528\u6b27\u6d32\u4e0e\u4e9a\u6d32\u4e4b\u95f4\u94c1\u8def\u96a7\u9053\u5f00\u901a\u4f5c\u4e3a\u4e00\u4e2a\u51c6\u81ea\u7136\u5b9e\u9a8c\uff0c\u6211\u8bc1\u660e\u90a3\u4e9b\u83b7\u5f97BRI\u8d27\u8fd0\u8def\u7ebf\u7684\u56fd\u5bb6\u4f1a\u5927\u91cf\u53d1\u884c\u9ad8\u6536\u76ca\u503a\u52a1\u3002\u8fd9\u4e9b\u503a\u52a1\u4e3b\u8981\u5728\u56fd\u5185\u88ab\u5438\u6536\uff0c\u8d44\u672c\u88ab\u91cd\u65b0\u914d\u7f6e\uff0c\u4f46\u5e76\u672a\u8f6c\u5316\u4e3a\u57fa\u7840\u8bbe\u65bd\u6295\u8d44\u3002\u56fd\u6709\u4f01\u4e1a\u4f3c\u4e4e\u4e0d\u53d7\u91d1\u878d\u7d27\u7f29\u7684\u5f71\u54cd\u3002\u6211\u63ed\u793a\u4e86\u6d89\u53ca\u4e0e\u4e2d\u56fd\u653f\u6cbb\u5951\u5408\u3001\u66b4\u9732\u4e8e\u8d38\u6613\u653f\u7b56\u4e0d\u786e\u5b9a\u6027\u4ee5\u53ca\u57fa\u4e8e\u5386\u53f2\u4e1c\u65b9\u5feb\u8f66\u8def\u7ebf\u7684\u5730\u5f62\u9002\u914d\u7b49\u673a\u5236\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.1111/jofi.70039", "journal": "JF", "title": "Funding Black High\u2010Growth Startups", "authors": ["LISA D. COOK", "MATT MARX", "EMMANUEL YIMFOR"], "author_details": [{"name": "LISA D. COOK", "affiliations": []}, {"name": "MATT MARX", "affiliations": []}, {"name": "EMMANUEL YIMFOR", "affiliations": []}], "abstract": "ABSTRACT We classify the race of over 160,000 U.S. founders and investors and study the venture capital (VC) funding gap for Black entrepreneurs. Only 3.1% of VC\u2010funded startups are Black\u2010owned, and they raise half as much VC funding as others. We attribute much of this gap to Black founders having fewer traditional success markers, like patents or entrepreneurial experience. This disparity also affects matching: Black VC partners invest more in Black founders, and these investments have higher successful exit rates. We attribute this outperformance to lower information asymmetries due to network overlap and \u201cscreening discrimination,\u201d whereby Black VCs better differentiate among Black founders.", "date": "2026-04-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70039", "title_zh": "\u8d44\u52a9\u975e\u6d32\u88d4\u9ad8\u589e\u957f\u521d\u521b\u4f01\u4e1a", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5bf9\u8d85\u8fc716\u4e07\u7f8e\u56fd\u521b\u59cb\u4eba\u548c\u6295\u8d44\u8005\u7684\u79cd\u65cf\u8fdb\u884c\u4e86\u5206\u7c7b\uff0c\u5e76\u7814\u7a76\u4e86\u975e\u6d32\u88d4\u521b\u4e1a\u8005\u5728\u98ce\u9669\u6295\u8d44\uff08VC\uff09\u878d\u8d44\u4e2d\u7684\u5dee\u8ddd\u3002\u53ea\u67093.1%\u7684VC\u878d\u8d44\u521d\u521b\u4f01\u4e1a\u7531\u975e\u6d32\u88d4\u6240\u6709\uff0c\u4e14\u5b83\u4eec\u83b7\u5f97\u7684VC\u8d44\u91d1\u4ec5\u4e3a\u5176\u4ed6\u521b\u4e1a\u8005\u7684\u4e00\u534a\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u79cd\u5dee\u8ddd\u5f88\u5927\u7a0b\u5ea6\u4e0a\u6e90\u4e8e\u975e\u6d32\u88d4\u521b\u59cb\u4eba\u7f3a\u4e4f\u4f20\u7edf\u6210\u529f\u6807\u5fd7\uff0c\u5982\u4e13\u5229\u6216\u521b\u4e1a\u7ecf\u9a8c\u3002\u8fd9\u79cd\u5dee\u5f02\u4e5f\u5f71\u54cd\u4e86\u5339\u914d\u60c5\u51b5\uff1a\u975e\u6d32\u88d4VC\u5408\u4f19\u4eba\u5bf9\u975e\u6d32\u88d4\u521b\u59cb\u4eba\u7684\u6295\u8d44\u66f4\u591a\uff0c\u4e14\u8fd9\u4e9b\u6295\u8d44\u7684\u9000\u51fa\u6210\u529f\u7387\u66f4\u9ad8\u3002\u6211\u4eec\u5c06\u5176\u8868\u73b0\u4f18\u5f02\u5f52\u56e0\u4e8e\u7f51\u7edc\u91cd\u53e0\u5bfc\u81f4\u7684\u4fe1\u606f\u4e0d\u5bf9\u79f0\u964d\u4f4e\uff0c\u4ee5\u53ca\u201c\u7b5b\u9009\u6b67\u89c6\u201d\uff0c\u5373\u975e\u6d32\u88d4VC\u5408\u4f19\u4eba\u80fd\u591f\u66f4\u6709\u6548\u5730\u533a\u5206\u975e\u6d32\u88d4\u521b\u59cb\u4eba\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1111/jofi.70034", "journal": "JF", "title": "Deposit Franchise Runs", "authors": ["ITAMAR DRECHSLER", "ALEXI SAVOV", "PHILIPP SCHNABL", "OLIVIER WANG"], "author_details": [{"name": "ITAMAR DRECHSLER", "affiliations": []}, {"name": "ALEXI SAVOV", "affiliations": []}, {"name": "PHILIPP SCHNABL", "affiliations": []}, {"name": "OLIVIER WANG", "affiliations": []}], "abstract": "ABSTRACT The deposit franchise is valuable because banks pay below\u2010market deposit rates. However, if depositors leave, its value vanishes. This can trigger runs by uninsured depositors, even if banks hold fully liquid assets. Because the franchise value increases with interest rates, runs are more harmful, and hence likelier, when rates are high. Banks can deter runs by shortening asset duration, but this risks insolvency if rates fall. Avoiding both runs and insolvency requires capital covering the potential loss of the uninsured deposit franchise. We estimate deposit franchise values and use them to identify vulnerable banks during the 2023 regional bank crisis.", "date": "2026-04-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70034", "title_zh": "\u5b58\u6b3e\u7279\u8bb8\u6743\u5371\u673a", "abstract_zh": "\u6458\u8981 \u5b58\u6b3e\u7279\u8bb8\u6743\u5177\u6709\u4ef7\u503c\uff0c\u56e0\u4e3a\u94f6\u884c\u652f\u4ed8\u7684\u5b58\u6b3e\u5229\u7387\u4f4e\u4e8e\u5e02\u573a\u5229\u7387\u3002\u7136\u800c\uff0c\u5982\u679c\u5b58\u6b3e\u4eba\u64a4\u51fa\uff0c\u5176\u4ef7\u503c\u5c06\u6d88\u5931\u3002\u8fd9\u53ef\u80fd\u5f15\u53d1\u672a\u6295\u4fdd\u5b58\u6b3e\u4eba\u7684\u6324\u5151\uff0c\u5373\u4f7f\u94f6\u884c\u6301\u6709\u5b8c\u5168\u6d41\u52a8\u7684\u8d44\u4ea7\u3002\u7531\u4e8e\u7279\u8bb8\u6743\u4ef7\u503c\u968f\u5229\u7387\u4e0a\u5347\u800c\u589e\u52a0\uff0c\u5229\u7387\u8f83\u9ad8\u65f6\u6324\u5151\u7684\u5371\u5bb3\u66f4\u5927\uff0c\u53d1\u751f\u7684\u53ef\u80fd\u6027\u4e5f\u66f4\u9ad8\u3002\u94f6\u884c\u53ef\u4ee5\u901a\u8fc7\u7f29\u77ed\u8d44\u4ea7\u4e45\u671f\u6765\u6291\u5236\u6324\u5151\uff0c\u4f46\u82e5\u5229\u7387\u4e0b\u964d\uff0c\u8fd9\u79cd\u505a\u6cd5\u53ef\u80fd\u5bfc\u81f4\u7834\u4ea7\u3002\u8981\u540c\u65f6\u907f\u514d\u6324\u5151\u548c\u7834\u4ea7\uff0c\u9700\u8981\u8d44\u672c\u6765\u8986\u76d6\u672a\u6295\u4fdd\u5b58\u6b3e\u7279\u8bb8\u6743\u53ef\u80fd\u9020\u6210\u7684\u635f\u5931\u3002\u6211\u4eec\u4f30\u8ba1\u4e86\u5b58\u6b3e\u7279\u8bb8\u6743\u7684\u4ef7\u503c\uff0c\u5e76\u5229\u7528\u8fd9\u4e9b\u4ef7\u503c\u8bc6\u522b\u4e862023\u5e74\u533a\u57df\u94f6\u884c\u5371\u673a\u4e2d\u6613\u53d7\u51b2\u51fb\u7684\u94f6\u884c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70038", "journal": "JF", "title": "The (Missing) Relation between Acquisition Announcement Returns and Value Creation", "authors": ["ITZHAK BEN\u2010DAVID", "UTPAL BHATTACHARYA", "RUIDI HUANG", "STACEY JACOBSEN"], "author_details": [{"name": "ITZHAK BEN\u2010DAVID", "affiliations": []}, {"name": "UTPAL BHATTACHARYA", "affiliations": []}, {"name": "RUIDI HUANG", "affiliations": []}, {"name": "STACEY JACOBSEN", "affiliations": []}], "abstract": "ABSTRACT Cumulative abnormal returns (CARs) computed around acquisition announcements are widely considered to be market\u2010based assessments of expected value creation. We show, however, that announcement returns do not correlate with commonly used and new measures of ex post outcomes. A simple characteristics\u2010based model using standard information known at the announcement date can predict these outcomes reasonably well, yet CAR even fails to capture the predictions from this model. Evidence suggests that information about the stand\u2010alone acquirer dominates CAR, making it virtually impossible to extract deal\u2010related information. We conclude that CAR is an unreliable measure of expected value creation.", "date": "2026-04-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70038", "title_zh": "\u6536\u8d2d\u516c\u544a\u56de\u62a5\u4e0e\u4ef7\u503c\u521b\u9020\u4e4b\u95f4\u7684\uff08\u7f3a\u5931\uff09\u5173\u7cfb", "abstract_zh": "\u6458\u8981\uff1a\u56f4\u7ed5\u6536\u8d2d\u516c\u544a\u8ba1\u7b97\u7684\u7d2f\u8ba1\u5f02\u5e38\u56de\u62a5\uff08CAR\uff09\u88ab\u5e7f\u6cdb\u89c6\u4e3a\u5e02\u573a\u5bf9\u9884\u671f\u4ef7\u503c\u521b\u9020\u7684\u8bc4\u4f30\u3002\u7136\u800c\uff0c\u6211\u4eec\u53d1\u73b0\u516c\u544a\u56de\u62a5\u4e0e\u5e38\u7528\u7684\u4ee5\u53ca\u65b0\u7684\u4e8b\u540e\u7ed3\u679c\u8861\u91cf\u6307\u6807\u4e4b\u95f4\u5e76\u65e0\u76f8\u5173\u6027\u3002\u4e00\u4e2a\u57fa\u4e8e\u7b80\u5355\u7279\u5f81\u7684\u6a21\u578b\uff0c\u5229\u7528\u516c\u544a\u65e5\u5df2\u77e5\u7684\u6807\u51c6\u4fe1\u606f\uff0c\u80fd\u591f\u8f83\u4e3a\u51c6\u786e\u5730\u9884\u6d4b\u8fd9\u4e9b\u7ed3\u679c\uff0c\u4f46CAR\u751a\u81f3\u65e0\u6cd5\u6355\u6349\u8be5\u6a21\u578b\u7684\u9884\u6d4b\u7ed3\u679c\u3002\u8bc1\u636e\u8868\u660e\uff0c\u6536\u8d2d\u65b9\u72ec\u7acb\u8fd0\u8425\u7684\u4fe1\u606f\u4e3b\u5bfc\u4e86CAR\uff0c\u4f7f\u5f97\u51e0\u4e4e\u65e0\u6cd5\u63d0\u53d6\u4e0e\u4ea4\u6613\u76f8\u5173\u7684\u4fe1\u606f\u3002\u56e0\u6b64\uff0c\u6211\u4eec\u5f97\u51fa\u7ed3\u8bba\uff1aCAR\u4f5c\u4e3a\u9884\u671f\u4ef7\u503c\u521b\u9020\u7684\u8861\u91cf\u6307\u6807\u662f\u4e0d\u53ef\u9760\u7684\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1093/rfs/hhag036", "journal": "RFS", "title": "What Drives Momentum and Reversal? Evidence from Day and Night Signals", "authors": ["Yashar H Barardehi", "Vincent Bogousslavsky", "Dmitriy Muravyev"], "author_details": [{"name": "Yashar H Barardehi", "affiliations": ["Virginia Tech ,"]}, {"name": "Vincent Bogousslavsky", "affiliations": ["Boston College ,"]}, {"name": "Dmitriy Muravyev", "affiliations": ["University of Illinois Urbana-Champaign ,"]}], "abstract": "Abstract We study how intraday and overnight components of past returns predict future stock returns from 1926 to 2019. Portfolios formed on past intraday returns display momentum without long-term reversal, whereas portfolios formed on past overnight returns display no momentum. We link this asymmetric day-night pattern to the fact that most trading occurs intraday, which has remained stable over time. Evidence from international stock markets, intraday intervals, and analyst expectations suggests that investors underreact to private information revealed through trading. This underreaction mechanism is most consistent with Hong and Stein\u2019s (1999) theory of momentum.", "date": "2026-04-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag036", "title_zh": "\u662f\u4ec0\u4e48\u9a71\u52a8\u4e86\u52a8\u91cf\u4e0e\u53cd\u8f6c\uff1f\u6765\u81ea\u65e5\u95f4\u548c\u591c\u95f4\u4fe1\u53f7\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u65e5\u5185\u548c\u9694\u591c\u8fc7\u53bb\u6536\u76ca\u7387\u5982\u4f55\u9884\u6d4b1926\u5e74\u81f32019\u5e74\u671f\u95f4\u7684\u672a\u6765\u80a1\u7968\u6536\u76ca\u7387\u3002\u57fa\u4e8e\u8fc7\u53bb\u65e5\u5185\u6536\u76ca\u7387\u6784\u5efa\u7684\u7ec4\u5408\u8868\u73b0\u51fa\u52a8\u91cf\u6548\u5e94\uff0c\u4f46\u6ca1\u6709\u957f\u671f\u53cd\u8f6c\uff1b\u800c\u57fa\u4e8e\u8fc7\u53bb\u9694\u591c\u6536\u76ca\u7387\u6784\u5efa\u7684\u7ec4\u5408\u5219\u6ca1\u6709\u52a8\u91cf\u6548\u5e94\u3002\u6211\u4eec\u628a\u8fd9\u79cd\u65e5\u95f4-\u591c\u95f4\u6a21\u5f0f\u7684\u4e0d\u5bf9\u79f0\u6027\u5f52\u56e0\u4e8e\u5927\u90e8\u5206\u4ea4\u6613\u53d1\u751f\u5728\u65e5\u5185\uff0c\u4e14\u8fd9\u4e00\u7279\u5f81\u5728\u65f6\u95f4\u4e0a\u4fdd\u6301\u7a33\u5b9a\u3002\u6765\u81ea\u56fd\u9645\u80a1\u7968\u5e02\u573a\u3001\u65e5\u5185\u65f6\u6bb5\u4ee5\u53ca\u5206\u6790\u5e08\u9884\u671f\u7684\u8bc1\u636e\u8868\u660e\uff0c\u6295\u8d44\u8005\u5bf9\u901a\u8fc7\u4ea4\u6613\u62ab\u9732\u7684\u79c1\u4eba\u4fe1\u606f\u5b58\u5728\u53cd\u5e94\u4e0d\u8db3\u3002\u8fd9\u79cd\u53cd\u5e94\u4e0d\u8db3\u673a\u5236\u4e0eHong\u548cStein\uff081999\uff09\u7684\u52a8\u91cf\u7406\u8bba\u6700\u4e3a\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1017/s0022109026102804", "journal": "JFQA", "title": "Attentive Options Traders: Textual Changes to 10-Ks and Option Volatility Smirk", "authors": ["Hua Cheng", "Steve Liu", "Zheng Qiao", "Z. Jay Wang"], "author_details": [{"name": "Hua Cheng", "affiliations": ["Sun Yat-sen University International School of Business and Finance and University of Texas at Austin"]}, {"name": "Steve Liu", "affiliations": ["University of Rhode Island College of Business"]}, {"name": "Zheng Qiao", "affiliations": ["Xi\u2019an Jiaotong University School of Management"]}, {"name": "Z. Jay Wang", "affiliations": ["University of Oregon Lundquist College of Business"]}], "abstract": "Abstract In contrast to the \u201clazy prices\u201d phenomenon in the stock market, more 10-K textual changes lead to larger increases in volatility smirks\u2014consistent with options traders buying more out-of-the-money put options based on negative information disclosed in textual changes. Moreover, the lazy-prices effect is mainly driven by stocks with tradable options, suggesting that limits to arbitrage lead to a delayed response of stock prices. Finally, the return predictability of textual changes is stronger for stocks with larger option volatility smirk changes. Sophisticated options traders, therefore, demonstrate superior skills at extracting relevant information from public filings.", "date": "2026-04-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102804", "title_zh": "\u5173\u6ce8\u671f\u6743\u4ea4\u6613\u5458\uff1a10-K\u6587\u4ef6\u7684\u6587\u672c\u53d8\u66f4\u4e0e\u671f\u6743\u6ce2\u52a8\u7387\u5fae\u7b11", "abstract_zh": "\u4e0e\u80a1\u7968\u5e02\u573a\u4e2d\u7684\u2018\u61d2\u60f0\u4ef7\u683c\u2019\u73b0\u8c61\u76f8\u53cd\uff0c10-K\u6587\u4ef6\u4e2d\u66f4\u591a\u7684\u6587\u672c\u53d8\u66f4\u4f1a\u5bfc\u81f4\u6ce2\u52a8\u7387\u5fae\u7b11\u7684\u66f4\u5927\u4e0a\u5347\u2014\u2014\u8fd9\u4e0e\u671f\u6743\u4ea4\u6613\u5458\u57fa\u4e8e\u6587\u672c\u53d8\u66f4\u4e2d\u62ab\u9732\u7684\u8d1f\u9762\u4fe1\u606f\u800c\u589e\u6301\u770b\u8dcc\u671f\u6743\u7684\u884c\u4e3a\u4e00\u81f4\u3002\u6b64\u5916\uff0c\u61d2\u60f0\u4ef7\u683c\u6548\u5e94\u4e3b\u8981\u4f53\u73b0\u5728\u5177\u6709\u53ef\u4ea4\u6613\u671f\u6743\u7684\u80a1\u7968\u4e0a\uff0c\u8868\u660e\u5957\u5229\u9650\u5236\u5bfc\u81f4\u80a1\u4ef7\u53cd\u5e94\u5b58\u5728\u5ef6\u8fdf\u3002\u6700\u540e\uff0c\u6587\u672c\u53d8\u66f4\u7684\u6536\u76ca\u7387\u53ef\u9884\u6d4b\u6027\u5728\u671f\u6743\u6ce2\u52a8\u7387\u5fae\u7b11\u53d8\u5316\u8f83\u5927\u7684\u80a1\u7968\u4e2d\u66f4\u5f3a\u3002\u56e0\u6b64\uff0c\u7ecf\u9a8c\u4e30\u5bcc\u7684\u671f\u6743\u4ea4\u6613\u5458\u5c55\u73b0\u51fa\u4ece\u516c\u5f00\u6587\u4ef6\u4e2d\u63d0\u53d6\u76f8\u5173\u4fe1\u606f\u7684\u5353\u8d8a\u80fd\u529b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790"]}, {"doi": "10.1111/jofi.70036", "journal": "JF", "title": "Size, Returns, and Value: Do Private Equity Firms Allocate Capital According to Manager Skill?", "authors": ["REINER BRAUN", "NILS DORAU", "TIM JENKINSON", "DANIEL URBAN"], "author_details": [{"name": "REINER BRAUN", "affiliations": []}, {"name": "NILS DORAU", "affiliations": []}, {"name": "TIM JENKINSON", "affiliations": []}, {"name": "DANIEL URBAN", "affiliations": []}], "abstract": "ABSTRACT Using a novel data set linking private equity (PE) deals to individual managers, we document evidence of manager skill in terms of generating net present value (NPV), a performance measure that captures both scale and returns. PE firms have strong economic incentives to raise larger funds and execute larger deals. While relative returns decline with scale, NPV persists and even increases. Skilled managers are entrusted with more capital and achieve better career outcomes, and approximately 40% of NPV is attributable to internal capital allocation decisions. These findings highlight the role of PE firms in creating value through performance\u2010based capital deployment.", "date": "2026-04-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70036", "title_zh": "\u89c4\u6a21\u3001\u6536\u76ca\u4e0e\u4ef7\u503c\uff1a\u79c1\u52df\u80a1\u6743\u516c\u53f8\u662f\u5426\u6839\u636e\u7ba1\u7406\u80fd\u529b\u5206\u914d\u8d44\u672c\uff1f", "abstract_zh": "\u6458\u8981\uff1a\u5229\u7528\u4e00\u4e2a\u5c06\u79c1\u52df\u80a1\u6743\uff08PE\uff09\u4ea4\u6613\u4e0e\u4e2a\u522b\u7ba1\u7406\u8005\u5173\u8054\u8d77\u6765\u7684\u65b0\u578b\u6570\u636e\u96c6\uff0c\u6211\u4eec\u53d1\u73b0\u4e86\u7ba1\u7406\u8005\u5728\u521b\u9020\u51c0\u73b0\u503c\uff08NPV\uff09\u65b9\u9762\u7684\u6280\u80fd\uff0c\u8fd9\u662f\u4e00\u79cd\u540c\u65f6\u6355\u6349\u89c4\u6a21\u548c\u6536\u76ca\u7684\u7ee9\u6548\u8861\u91cf\u6307\u6807\u3002\u79c1\u52df\u80a1\u6743\u516c\u53f8\u6709\u5f3a\u70c8\u7684\u7ecf\u6d4e\u52a8\u673a\u53bb\u52df\u96c6\u66f4\u5927\u89c4\u6a21\u7684\u8d44\u91d1\u5e76\u6267\u884c\u66f4\u5927\u89c4\u6a21\u7684\u4ea4\u6613\u3002\u5c3d\u7ba1\u76f8\u5bf9\u6536\u76ca\u968f\u7740\u89c4\u6a21\u7684\u589e\u52a0\u800c\u4e0b\u964d\uff0c\u4f46\u51c0\u73b0\u503c\u5374\u6301\u7eed\u5b58\u5728\uff0c\u751a\u81f3\u6709\u6240\u4e0a\u5347\u3002\u6709\u6280\u80fd\u7684\u7ba1\u7406\u8005\u88ab\u8d4b\u4e88\u66f4\u591a\u8d44\u672c\uff0c\u5e76\u83b7\u5f97\u66f4\u597d\u7684\u804c\u4e1a\u53d1\u5c55\u7ed3\u679c\uff0c\u5176\u4e2d\u7ea640%\u7684\u51c0\u73b0\u503c\u5f52\u56e0\u4e8e\u5185\u90e8\u8d44\u672c\u5206\u914d\u51b3\u7b56\u3002\u8fd9\u4e9b\u53d1\u73b0\u51f8\u663e\u4e86\u79c1\u52df\u80a1\u6743\u516c\u53f8\u5728\u901a\u8fc7\u57fa\u4e8e\u7ee9\u6548\u7684\u8d44\u672c\u914d\u7f6e\u521b\u9020\u4ef7\u503c\u65b9\u9762\u7684\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag032", "journal": "RFS", "title": "Who Clears the Market When Passive Investors Trade?", "authors": ["Marco Sammon", "John J Shim"], "author_details": [{"name": "Marco Sammon", "affiliations": ["Harvard Business School, Harvard University , the United States"]}, {"name": "John J Shim", "affiliations": ["Mendoza College of Business, University of Notre Dame , the United States"]}], "abstract": "Abstract We find that firms are the primary sellers who clear the market for index fund buying, providing shares at a nearly one-for-one rate. Most demand-side institutions trade in the same direction as index funds rather than accommodating passive demand. We use two instruments for index fund demand and show that firms causally respond to exogenous passive demand, with prices serving as the coordinating mechanism. Firms satisfy passive demand mostly through nonprimary market issuance, for example, through employee stock-based compensation. Our results suggest that passive investing has systematically supplied capital to firms by enabling equity issuance over the last two decades.", "date": "2026-04-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag032", "title_zh": "\u5f53\u88ab\u52a8\u6295\u8d44\u8005\u4ea4\u6613\u65f6\uff0c\u8c01\u6765\u6e05\u7406\u5e02\u573a\uff1f", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u4f01\u4e1a\u5728\u6307\u6570\u57fa\u91d1\u4e70\u5165\u8fc7\u7a0b\u4e2d\u662f\u4e3b\u8981\u7684\u5356\u65b9\uff0c\u4ee5\u51e0\u4e4e\u4e00\u5bf9\u4e00\u7684\u6bd4\u4f8b\u63d0\u4f9b\u80a1\u7968\u3002\u5927\u591a\u6570\u9700\u6c42\u4fa7\u673a\u6784\u7684\u4ea4\u6613\u65b9\u5411\u4e0e\u6307\u6570\u57fa\u91d1\u4e00\u81f4\uff0c\u800c\u975e\u6ee1\u8db3\u88ab\u52a8\u9700\u6c42\u3002\u6211\u4eec\u4f7f\u7528\u4e24\u79cd\u6307\u6570\u57fa\u91d1\u9700\u6c42\u7684\u5de5\u5177\uff0c\u8bc1\u660e\u4f01\u4e1a\u5728\u9762\u5bf9\u5916\u751f\u88ab\u52a8\u9700\u6c42\u65f6\u4f1a\u505a\u51fa\u56e0\u679c\u53cd\u5e94\uff0c\u4ef7\u683c\u8d77\u5230\u4e86\u534f\u8c03\u4f5c\u7528\u3002\u4f01\u4e1a\u4e3b\u8981\u901a\u8fc7\u975e\u4e00\u7ea7\u5e02\u573a\u53d1\u884c\u6765\u6ee1\u8db3\u88ab\u52a8\u9700\u6c42\uff0c\u4f8b\u5982\u901a\u8fc7\u5458\u5de5\u80a1\u6743\u6fc0\u52b1\u8ba1\u5212\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u8fc7\u53bb\u4e8c\u5341\u5e74\u4e2d\uff0c\u88ab\u52a8\u6295\u8d44\u7cfb\u7edf\u6027\u5730\u4e3a\u516c\u53f8\u63d0\u4f9b\u4e86\u8d44\u672c\uff0c\u4fc3\u8fdb\u4e86\u80a1\u6743\u53d1\u884c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag033", "journal": "RFS", "title": "Borrowing from a Bigtech Platform", "authors": ["Jian Li", "Stefano Pegoraro"], "author_details": [{"name": "Jian Li", "affiliations": ["Columbia Business School ,"]}, {"name": "Stefano Pegoraro", "affiliations": ["University of Notre Dame ,"]}], "abstract": "Abstract We model credit competition between a bigtech platform and a bank lending to a merchant under limited commitment and asymmetric information about the merchant\u2019s incentives to default. The platform leverages its control over a marketplace to enforce partial loan repayments, enabling it to serve certain unbanked borrowers. When directly competing with the bank, the platform gains an endogenous screening advantage as borrowers with stronger incentives to default self-select into bank loans to avoid the platform\u2019s enforcement. Whereas the platform improves financial inclusion for unbanked borrowers, social welfare may decline because the bank tightens credit in response to adverse screening.", "date": "2026-04-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag033", "title_zh": "\u4ece\u5927\u578b\u79d1\u6280\u5e73\u53f0\u501f\u6b3e", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6a21\u578b\uff0c\u63cf\u8ff0\u5927\u578b\u79d1\u6280\u5e73\u53f0\u4e0e\u94f6\u884c\u5728\u5411\u5546\u6237\u653e\u8d37\u65f6\u7684\u4fe1\u8d37\u7ade\u4e89\uff0c\u5b58\u5728\u6709\u9650\u627f\u8bfa\u548c\u5bf9\u5546\u6237\u8fdd\u7ea6\u52a8\u673a\u7684\u4e0d\u5bf9\u79f0\u4fe1\u606f\u3002\u5e73\u53f0\u5229\u7528\u5176\u5bf9\u5e02\u573a\u7684\u63a7\u5236\u6743\uff0c\u5b9e\u65bd\u90e8\u5206\u8d37\u6b3e\u507f\u8fd8\uff0c\u4ece\u800c\u80fd\u591f\u670d\u52a1\u67d0\u4e9b\u672a\u88ab\u94f6\u884c\u8986\u76d6\u7684\u501f\u6b3e\u4eba\u3002\u5f53\u76f4\u63a5\u4e0e\u94f6\u884c\u7ade\u4e89\u65f6\uff0c\u5e73\u53f0\u7531\u4e8e\u501f\u6b3e\u4eba\u4e2d\u90a3\u4e9b\u6709\u66f4\u5f3a\u8fdd\u7ea6\u52a8\u673a\u7684\u4e2a\u4f53\u4e3b\u52a8\u9009\u62e9\u94f6\u884c\u8d37\u6b3e\u4ee5\u89c4\u907f\u5e73\u53f0\u7684\u6267\u884c\u63aa\u65bd\uff0c\u83b7\u5f97\u4e86\u5185\u751f\u6027\u7684\u7b5b\u9009\u4f18\u52bf\u3002\u5c3d\u7ba1\u5e73\u53f0\u63d0\u5347\u4e86\u672a\u88ab\u94f6\u884c\u670d\u52a1\u501f\u6b3e\u4eba\u7684\u91d1\u878d\u5305\u5bb9\u6027\uff0c\u4f46\u793e\u4f1a\u798f\u5229\u53ef\u80fd\u56e0\u94f6\u884c\u56e0\u4e0d\u5229\u7b5b\u9009\u800c\u6536\u7d27\u4fe1\u8d37\u800c\u4e0b\u964d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70033", "journal": "JF", "title": "Leader\u2010Follower Dynamics in Shareholder Activism", "authors": ["DORUK CETEMEN", "GONZALO CISTERNAS", "AARON KOLB", "S. VISWANATHAN"], "author_details": [{"name": "DORUK CETEMEN", "affiliations": []}, {"name": "GONZALO CISTERNAS", "affiliations": []}, {"name": "AARON KOLB", "affiliations": []}, {"name": "S. VISWANATHAN", "affiliations": []}], "abstract": "ABSTRACT We propose a theory of coordination and influence among blockholders. Privately informed activists time their trades in sequence to lower acquisition costs, prompting a strategic use of order flows: leader activists create trading gains for their followers, ultimately influencing their willingness to bear greater value\u2010enhancing intervention costs. Through this channel, informed trades can exhibit predictability, in sharp contrast with Kyle (1985, Econometrica 53, 1315\u20131335). We explain how this novel predictability shapes free\u2010rider problems affecting governance, and how it produces price abnormalities analogous to those documented empirically. We also uncover how private information interdependence can be a key catalyst for the mechanism studied.", "date": "2026-04-02", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70033", "title_zh": "\u80a1\u4e1c activism \u4e2d\u7684\u9886\u5bfc\u8005-\u8ffd\u968f\u8005\u52a8\u6001", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u4e2a\u5173\u4e8e\u5927\u80a1\u4e1c\u4e4b\u95f4\u534f\u8c03\u4e0e\u5f71\u54cd\u7684\u7406\u8bba\u3002\u62e5\u6709\u79c1\u6709\u4fe1\u606f\u7684\u6d3b\u8dc3\u6295\u8d44\u8005\u4f1a\u4f9d\u6b21\u9009\u62e9\u4ea4\u6613\u65f6\u673a\u4ee5\u964d\u4f4e\u6536\u8d2d\u6210\u672c\uff0c\u4ece\u800c\u4ea7\u751f\u4e00\u79cd\u6218\u7565\u6027\u7684\u4ea4\u6613\u6d41\uff1a\u9886\u5bfc\u8005\u6295\u8d44\u8005\u901a\u8fc7\u521b\u9020\u4ea4\u6613\u6536\u76ca\u6765\u5f71\u54cd\u8ffd\u968f\u8005\uff0c\u6700\u7ec8\u5f71\u54cd\u4ed6\u4eec\u627f\u62c5\u66f4\u5927\u4ef7\u503c\u63d0\u5347\u5e72\u9884\u6210\u672c\u7684\u610f\u613f\u3002\u901a\u8fc7\u8fd9\u4e00\u6e20\u9053\uff0c\u79c1\u6709\u4fe1\u606f\u7684\u4ea4\u6613\u8868\u73b0\u51fa\u53ef\u9884\u6d4b\u6027\uff0c\u8fd9\u4e0eKyle\uff081985\uff0cEconometrica 53\uff0c1315\u20131335\uff09\u7684\u7814\u7a76\u5f62\u6210\u9c9c\u660e\u5bf9\u6bd4\u3002\u6211\u4eec\u89e3\u91ca\u4e86\u8fd9\u79cd\u65b0\u51fa\u73b0\u7684\u53ef\u9884\u6d4b\u6027\u5982\u4f55\u5f71\u54cd\u6cbb\u7406\u4e2d\u7684\u642d\u4fbf\u8f66\u95ee\u9898\uff0c\u4ee5\u53ca\u5982\u4f55\u4ea7\u751f\u4e0e\u5b9e\u8bc1\u7814\u7a76\u4e2d\u89c2\u5bdf\u5230\u7684\u4ef7\u683c\u5f02\u5e38\u7c7b\u4f3c\u7684\u73b0\u8c61\u3002\u6211\u4eec\u8fd8\u63ed\u793a\u4e86\u79c1\u6709\u4fe1\u606f\u76f8\u4e92\u4f9d\u8d56\u6027\u53ef\u80fd\u662f\u8fd9\u4e00\u673a\u5236\u7684\u5173\u952e\u50ac\u5316\u5242\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240880", "journal": "AER", "title": "Spillovers in State Capacity Building: Evidence from the Digitization of Land Records in Pakistan", "authors": ["Shan Aman-Rana", "Clement Minaudier"], "author_details": [{"name": "Shan Aman-Rana", "affiliations": ["Department of Economics, University of Virginia (email: )"]}, {"name": "Clement Minaudier", "affiliations": ["Department of Economics, City St George\u2019s, University of London (email: )"]}], "abstract": "Digitization reforms have been hailed as an effective way of strengthening state capacity. However, digitization can also fundamentally reshape the organization of bureaucracies. Using a unique administrative dataset on agricultural taxation and surveys of local bureaucrats from Punjab, Pakistan, we show that digitization reforms can have unintended consequences for state capacity. We exploit the staggered rollout of the digitization of land records in Punjab to show that digitization had a negative effect on tax collection. The fall in taxes was not due to a decrease in the tax base. Instead, digitization affected the bureaucrats\u2019 capacity to collect taxes. (JEL D73, H11, H71, O12, O17)", "date": "2026-04-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240880", "title_zh": "\u5dde\u80fd\u529b\u6784\u5efa\u4e2d\u7684\u6ea2\u51fa\u6548\u5e94\uff1a\u6765\u81ea\u5df4\u57fa\u65af\u5766\u571f\u5730\u8bb0\u5f55\u6570\u5b57\u5316\u7684\u8bc1\u636e", "abstract_zh": "\u6570\u5b57\u5316\u6539\u9769\u88ab\u89c6\u4e3a\u52a0\u5f3a\u56fd\u5bb6\u80fd\u529b\u7684\u6709\u6548\u9014\u5f84\u3002\u7136\u800c\uff0c\u6570\u5b57\u5316\u4e5f\u53ef\u80fd\u4ece\u6839\u672c\u4e0a\u6539\u53d8\u5b98\u50da\u673a\u6784\u7684\u7ec4\u7ec7\u7ed3\u6784\u3002\u6211\u4eec\u5229\u7528\u5df4\u57fa\u65af\u5766\u65c1\u906e\u666e\u7701\u519c\u4e1a\u7a0e\u6536\u7684\u884c\u653f\u6570\u636e\u4ee5\u53ca\u5bf9\u5f53\u5730\u5b98\u50da\u7684\u8c03\u67e5\uff0c\u8868\u660e\u6570\u5b57\u5316\u6539\u9769\u53ef\u80fd\u5bf9\u56fd\u5bb6\u80fd\u529b\u4ea7\u751f\u610f\u5916\u540e\u679c\u3002\u6211\u4eec\u5229\u7528\u65c1\u906e\u666e\u7701\u571f\u5730\u8bb0\u5f55\u6570\u5b57\u5316\u5206\u9636\u6bb5\u63a8\u8fdb\u7684\u7279\u5f81\uff0c\u53d1\u73b0\u6570\u5b57\u5316\u5bf9\u7a0e\u6536\u5f81\u7f34\u4ea7\u751f\u4e86\u8d1f\u9762\u5f71\u54cd\u3002\u7a0e\u6536\u4e0b\u964d\u5e76\u975e\u7531\u4e8e\u7a0e\u57fa\u7f29\u5c0f\uff0c\u800c\u662f\u7531\u4e8e\u6570\u5b57\u5316\u5f71\u54cd\u4e86\u5b98\u50da\u673a\u6784\u5f81\u7a0e\u7684\u80fd\u529b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20241465", "journal": "AER", "title": "Abundance from Abroad: Migrant Income and Long-Run Economic Development", "authors": ["Gaurav Khanna", "Emir Murathanoglu", "Caroline Theoharides", "Dean Yang"], "author_details": [{"name": "Gaurav Khanna", "affiliations": ["University of California\u2013San Diego (email: )"]}, {"name": "Emir Murathanoglu", "affiliations": ["Oberlin College (email: )"]}, {"name": "Caroline Theoharides", "affiliations": ["Amherst College (email: )"]}, {"name": "Dean Yang", "affiliations": ["University of Michigan, NBER, and BREAD (email: )"]}], "abstract": "We study how international migrant income prospects affect long-run development in origin areas. We leverage the 1997 Asian Financial Crisis exchange rate shocks in a shift-share identification strategy across Philippine provinces. Initial migrant income shocks are magnified six-fold over time, increasing domestic income, education levels, migrant skills, and high-skilled migration. Remarkably, 74.9 percent of long-run income gains come from domestic rather than migrant income. Trade driven impacts of exchange rate shocks are orthogonal to effects via migrant income. A structural model reveals that 19.7 percent of long-run income gains stem from educational investments. International migration fosters broad economic development in origin communities. (JEL F22, F31, G01, J24, J82, O15, O16)", "date": "2026-04-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20241465", "title_zh": "\u6d77\u5916\u4e30\u88d5\uff1a\u79fb\u6c11\u6536\u5165\u4e0e\u957f\u671f\u7ecf\u6d4e\u53d1\u5c55", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u56fd\u9645\u79fb\u6c11\u6536\u5165\u524d\u666f\u5982\u4f55\u5f71\u54cd\u539f\u7c4d\u5730\u533a\u7684\u957f\u671f\u53d1\u5c55\u3002\u6211\u4eec\u5229\u75281997\u5e74\u4e9a\u6d32\u91d1\u878d\u5371\u673a\u4e2d\u7684\u6c47\u7387\u51b2\u51fb\uff0c\u901a\u8fc7\u83f2\u5f8b\u5bbe\u5404\u7701\u4efd\u7684\u79fb\u4f4d\u4efd\u989d\u8bc6\u522b\u7b56\u7565\u8fdb\u884c\u5206\u6790\u3002\u521d\u59cb\u7684\u79fb\u6c11\u6536\u5165\u51b2\u51fb\u5728\u65f6\u95f4\u4e0a\u88ab\u653e\u5927\u516d\u500d\uff0c\u63d0\u5347\u4e86\u56fd\u5185\u6536\u5165\u3001\u6559\u80b2\u6c34\u5e73\u3001\u79fb\u6c11\u6280\u80fd\u4ee5\u53ca\u9ad8\u6280\u80fd\u79fb\u6c11\u6570\u91cf\u3002\u4ee4\u4eba\u60ca\u8bb6\u7684\u662f\uff0c74.9%\u7684\u957f\u671f\u6536\u5165\u589e\u957f\u6765\u81ea\u56fd\u5185\u6536\u5165\u800c\u975e\u79fb\u6c11\u6536\u5165\u3002\u6c47\u7387\u51b2\u51fb\u901a\u8fc7\u8d38\u6613\u9a71\u52a8\u7684\u5f71\u54cd\u4e0e\u901a\u8fc7\u79fb\u6c11\u6536\u5165\u4f20\u5bfc\u7684\u5f71\u54cd\u76f8\u4e92\u72ec\u7acb\u3002\u4e00\u4e2a\u7ed3\u6784\u6a21\u578b\u663e\u793a\uff0c19.7%\u7684\u957f\u671f\u6536\u5165\u589e\u957f\u6e90\u4e8e\u6559\u80b2\u6295\u8d44\u3002\u56fd\u9645\u79fb\u6c11\u4fc3\u8fdb\u4e86\u539f\u7c4d\u793e\u533a\u7684\u5e7f\u6cdb\u7ecf\u6d4e\u53d1\u5c55\u3002\uff08JEL F22, F31, G01, J24, J82, O15, O16\uff09", "translation_source": "journal-qwen4b", "topics": ["\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1257/aer.20211548", "journal": "AER", "title": "A Long and a Short Leg Make for a Wobbly Equilibrium", "authors": ["Nicolae G\u00e2rleanu", "Stavros Panageas", "Geoffery Zheng"], "author_details": [{"name": "Nicolae G\u00e2rleanu", "affiliations": ["(email: )"]}, {"name": "Stavros Panageas", "affiliations": ["(email: )"]}, {"name": "Geoffery Zheng", "affiliations": ["(email: )"]}], "abstract": "We provide a model to explain how the interaction between the spot and lending markets for stocks can lead to abrupt changes in short selling activity. Furthermore, rational short sellers may choose to abandon the market even as mispricing widens. We document empirically that the dynamics of short selling are fat tailed and subject to abrupt changes, especially for the stocks that the model identifies as susceptible to such dynamics. (JEL G11, G12, G14, G41)", "date": "2026-04-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20211548", "title_zh": "\u957f\u817f\u4e0e\u77ed\u817f\u5171\u540c\u5bfc\u81f4\u4e0d\u7a33\u5b9a\u7684\u5747\u8861", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6a21\u578b\uff0c\u89e3\u91ca\u80a1\u7968\u73b0\u8d27\u5e02\u573a\u4e0e\u501f\u8d37\u5e02\u573a\u4e4b\u95f4\u7684\u4e92\u52a8\u5982\u4f55\u5bfc\u81f4\u77ed\u5356\u6d3b\u52a8\u7684\u7a81\u7136\u53d8\u5316\u3002\u6b64\u5916\uff0c\u7406\u6027\u77ed\u5356\u8005\u53ef\u80fd\u5728\u4ef7\u683c\u8bef\u5224\u52a0\u5267\u7684\u60c5\u51b5\u4e0b\u9009\u62e9\u9000\u51fa\u5e02\u573a\u3002\u6211\u4eec\u5b9e\u8bc1\u53d1\u73b0\uff0c\u77ed\u5356\u884c\u4e3a\u7684\u52a8\u6001\u5177\u6709\u539a\u5c3e\u7279\u5f81\uff0c\u5e76\u4e14\u5bb9\u6613\u53d1\u751f\u7a81\u7136\u53d8\u5316\uff0c\u5c24\u5176\u662f\u5728\u6a21\u578b\u8bc6\u522b\u51fa\u6613\u53d7\u6b64\u7c7b\u52a8\u6001\u5f71\u54cd\u7684\u80a1\u7968\u4e2d\u8868\u73b0\u660e\u663e\u3002\uff08JEL G11, G12, G14, G41\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20211820", "journal": "AER", "title": "Real Credit Cycles", "authors": ["Pedro Bordalo", "Nicola Gennaioli", "Andrei Shleifer", "Stephen J. Terry"], "author_details": [{"name": "Pedro Bordalo", "affiliations": ["University of Oxford (email: )"]}, {"name": "Nicola Gennaioli", "affiliations": ["University of Bocconi (email: )"]}, {"name": "Andrei Shleifer", "affiliations": ["Harvard University (email: )"]}, {"name": "Stephen J. Terry", "affiliations": ["University of Michigan (email: )"]}], "abstract": "We embed diagnostic expectations in a workhorse neoclassical model with heterogeneous firms and risky debt. A realistic degree of overreaction estimated from US firms\u2019 earnings forecasts generates realistic credit cycles. Good times produce economic and financial fragility, predicting future disappointment of expectations, low bond returns, and investment declines. To generate the size of spread increases observed during 2007\u20132009, the model requires only moderate negative shocks. Diagnostic expectations offer a realistic, parsimonious way to produce financial reversals in business cycle models. (JEL D84, E13, E22, E32, E44, G12, G32)", "date": "2026-04-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20211820", "title_zh": "\u771f\u5b9e\u4fe1\u8d37\u5468\u671f", "abstract_zh": "\u6211\u4eec\u5c06\u8bca\u65ad\u6027\u9884\u671f\u5d4c\u5165\u4e00\u4e2a\u5305\u542b\u5f02\u8d28\u4f01\u4e1a\u4e0e\u98ce\u9669\u503a\u52a1\u7684\u4e3b\u6d41\u65b0\u53e4\u5178\u6a21\u578b\u4e2d\u3002\u4ece\u7f8e\u56fd\u4f01\u4e1a\u76c8\u5229\u9884\u6d4b\u4e2d\u4f30\u8ba1\u5230\u7684\u5408\u7406\u8fc7\u5ea6\u53cd\u5e94\u7a0b\u5ea6\uff0c\u80fd\u591f\u4ea7\u751f\u7b26\u5408\u73b0\u5b9e\u7684\u4fe1\u8d37\u5468\u671f\u3002\u7e41\u8363\u65f6\u671f\u4f1a\u5f15\u53d1\u7ecf\u6d4e\u548c\u91d1\u878d\u8106\u5f31\u6027\uff0c\u9884\u793a\u672a\u6765\u9884\u671f\u7684\u843d\u7a7a\u3001\u503a\u5238\u6536\u76ca\u7387\u4e0b\u964d\u4ee5\u53ca\u6295\u8d44\u51cf\u5c11\u3002\u4e3a\u4e86\u4ea7\u751f2007\u5e74\u81f32009\u5e74\u671f\u95f4\u89c2\u5bdf\u5230\u7684\u5229\u5dee\u6269\u5927\uff0c\u6a21\u578b\u4ec5\u9700\u9002\u5ea6\u7684\u8d1f\u5411\u51b2\u51fb\u3002\u8bca\u65ad\u6027\u9884\u671f\u4e3a\u5546\u4e1a\u5468\u671f\u6a21\u578b\u4e2d\u7684\u91d1\u878d\u9006\u8f6c\u63d0\u4f9b\u4e86\u4e00\u79cd\u73b0\u5b9e\u4e14\u7b80\u6d01\u7684\u89e3\u91ca\u65b9\u5f0f\u3002\uff08JEL D84, E13, E22, E32, E44, G12, G32\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240246", "journal": "AER", "title": "Robust Misspecified Models", "authors": ["Cuimin Ba"], "author_details": [{"name": "Cuimin Ba", "affiliations": ["University of Pittsburgh (email: )"]}], "abstract": "This paper studies which misspecified models are likely to persist when decision-makers compare them with competing models. The main result characterizes such models based on two features that can be derived from primitives: The model\u2019s asymptotic accuracy in predicting the equilibrium distribution of observed outcomes and the \u201ctightness\u201d of the prior around such equilibria. Misspecified models can be robust, persisting against any arbitrary competing model\u2014including the true model\u2014despite decision-makers observing an infinite amount of data. Moreover, simple misspecified models equipped with entrenched priors can be more robust than complex correctly specified models. (JEL C11, C52, D11, L82)", "date": "2026-04-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240246", "title_zh": "\u9c81\u68d2\u7684\u8bef\u6307\u5b9a\u6a21\u578b", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5728\u51b3\u7b56\u8005\u5c06\u6a21\u578b\u4e0e\u7ade\u4e89\u6027\u6a21\u578b\u8fdb\u884c\u6bd4\u8f83\u65f6\uff0c\u54ea\u4e9b\u8bef\u6307\u5b9a\u6a21\u578b\u53ef\u80fd\u6301\u7eed\u5b58\u5728\u3002\u4e3b\u8981\u7ed3\u679c\u57fa\u4e8e\u53ef\u4ee5\u4ece\u57fa\u672c\u5047\u8bbe\u4e2d\u63a8\u5bfc\u51fa\u7684\u4e24\u4e2a\u7279\u5f81\u5bf9\u8fd9\u7c7b\u6a21\u578b\u8fdb\u884c\u4e86\u523b\u753b\uff1a\u6a21\u578b\u5728\u9884\u6d4b\u89c2\u6d4b\u7ed3\u679c\u5747\u8861\u5206\u5e03\u65b9\u9762\u7684\u6e10\u8fd1\u51c6\u786e\u6027\uff0c\u4ee5\u53ca\u5148\u9a8c\u5206\u5e03\u56f4\u7ed5\u8fd9\u4e9b\u5747\u8861\u7684\u201c\u7d27\u5bc6\u7a0b\u5ea6\u201d\u3002\u5373\u4f7f\u51b3\u7b56\u8005\u89c2\u5bdf\u5230\u65e0\u9650\u91cf\u7684\u6570\u636e\uff0c\u8bef\u6307\u5b9a\u6a21\u578b\u4ecd\u53ef\u80fd\u5177\u6709\u9c81\u68d2\u6027\uff0c\u6301\u7eed\u5b58\u5728\uff0c\u751a\u81f3\u5728\u9762\u5bf9\u4efb\u4f55\u4efb\u610f\u7684\u7ade\u4e89\u6027\u6a21\u578b\uff08\u5305\u62ec\u771f\u5b9e\u6a21\u578b\uff09\u65f6\u4e5f\u5982\u6b64\u3002\u6b64\u5916\uff0c\u914d\u5907\u6709\u6839\u6df1\u8482\u56fa\u5148\u9a8c\u7684\u7b80\u5355\u8bef\u6307\u5b9a\u6a21\u578b\u53ef\u80fd\u6bd4\u6b63\u786e\u6307\u5b9a\u7684\u590d\u6742\u6a21\u578b\u66f4\u5177\u9c81\u68d2\u6027\u3002\uff08JEL C11, C52, D11, L82\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20241459", "journal": "AER", "title": "Making Bricks from Straw: Resources and Productivity in Health Care", "authors": ["Edward N. Okeke"], "author_details": [{"name": "Edward N. Okeke", "affiliations": ["RAND School of Public Policy and Department of Economics, Sociology, and Statistics (email: )"]}], "abstract": "Why do health facilities in developing countries do so poorly? This paper examines the role of financial constraints. I describe an experiment in which we surprised health workers in randomly selected public health clinics in Nigeria with a \u20a6600,000 grant paid out in installments over one year. Its administration was left entirely to health workers. The award led to large productivity gains. Using expenditure data combined with novel textual data, I provide an explanation for these effects. I show the award increased investments in physical and human capital, led to lower prices for patients, and inspired health workers to do better. (JEL D24, G31, H75, I11, J24, J31, O15)", "date": "2026-04-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20241459", "title_zh": "\u7528\u79f8\u79c6\u9020\u7816\uff1a\u8d44\u6e90\u4e0e\u751f\u4ea7\u7387\u5728\u533b\u7597\u4fdd\u5065\u4e2d\u7684\u4f5c\u7528", "abstract_zh": "\u4e3a\u4ec0\u4e48\u53d1\u5c55\u4e2d\u56fd\u5bb6\u7684\u533b\u7597\u8bbe\u65bd\u8868\u73b0\u5982\u6b64\u7cdf\u7cd5\uff1f\u672c\u6587\u8003\u5bdf\u4e86\u8d22\u52a1\u7ea6\u675f\u7684\u4f5c\u7528\u3002\u6211\u63cf\u8ff0\u4e86\u4e00\u9879\u5b9e\u9a8c\uff0c\u5176\u4e2d\u6211\u4eec\u5bf9\u5c3c\u65e5\u5229\u4e9a\u968f\u673a\u9009\u5b9a\u7684\u516c\u5171\u533b\u7597\u8bca\u6240\u7684\u533b\u62a4\u4eba\u5458\u7a81\u7136\u53d1\u653e\u4e86\u4e00\u7b14600,000\u5948\u62c9\u7684\u8d44\u52a9\uff0c\u520612\u4e2a\u6708\u652f\u4ed8\u3002\u8d44\u52a9\u7684\u7ba1\u7406\u5b8c\u5168\u4ea4\u7531\u533b\u62a4\u4eba\u5458\u81ea\u884c\u51b3\u5b9a\u3002\u8be5\u8d44\u52a9\u5e26\u6765\u4e86\u663e\u8457\u7684\u751f\u4ea7\u7387\u63d0\u5347\u3002\u901a\u8fc7\u652f\u51fa\u6570\u636e\u7ed3\u5408\u65b0\u9896\u7684\u6587\u672c\u6570\u636e\uff0c\u6211\u89e3\u91ca\u4e86\u8fd9\u4e9b\u6548\u679c\u3002\u6211\u8868\u660e\uff0c\u8d44\u52a9\u589e\u52a0\u4e86\u5bf9\u5b9e\u7269\u8d44\u672c\u548c\u4eba\u529b\u8d44\u672c\u7684\u6295\u8d44\uff0c\u964d\u4f4e\u4e86\u60a3\u8005\u4ef7\u683c\uff0c\u5e76\u6fc0\u52b1\u533b\u62a4\u4eba\u5458\u63d0\u5347\u670d\u52a1\u8d28\u91cf\u3002\uff08JEL D24, G31, H75, I11, J24, J31, O15\uff09", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790"]}, {"doi": "10.1257/aer.20240763", "journal": "AER", "title": "Games on Multiplex Networks", "authors": ["Yves Zenou", "Junjie Zhou"], "author_details": [{"name": "Yves Zenou", "affiliations": ["Monash University (email: )"]}, {"name": "Junjie Zhou", "affiliations": ["Tsinghua University (email: )"]}], "abstract": "We develop a simple multilayer network model in which agents allocate effort across layers with heterogeneous structures, subject to an aggregate effort constraint. Incentives are shaped by agents\u2019 network positions within each layer, and equilibrium behavior reflects both within- and cross-layer interactions. We analyze how shocks propagate through the network and characterize optimal targeting interventions. Our results show that effective policy design must account for effort allocation across layers. We also demonstrate that predictions from monolayer models can diverge sharply from those of multilayer models, underscoring the importance of accounting for network complexity in both empirical and policy analyses. (JEL C70, D78, D82, D85, H41, Z13)", "date": "2026-04-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240763", "title_zh": "\u591a\u91cd\u7f51\u7edc\u4e0a\u7684\u535a\u5f08", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u7b80\u5355\u7684\u591a\u91cd\u7f51\u7edc\u6a21\u578b\uff0c\u5176\u4e2d\u4ee3\u7406\u4eba\u5c06\u5728\u7ed3\u6784\u5f02\u8d28\u7684\u5404\u5c42\u7f51\u7edc\u4e2d\u5206\u914d\u52aa\u529b\uff0c\u4e14\u53d7\u5230\u603b\u52aa\u529b\u7ea6\u675f\u3002\u6fc0\u52b1\u7531\u4ee3\u7406\u4eba\u5404\u81ea\u5728\u7f51\u7edc\u5c42\u4e2d\u7684\u4f4d\u7f6e\u51b3\u5b9a\uff0c\u5747\u8861\u884c\u4e3a\u53cd\u6620\u4e86\u5c42\u5185\u548c\u8de8\u5c42\u4e4b\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\u3002\u6211\u4eec\u5206\u6790\u4e86\u51b2\u51fb\u5728\u7f51\u7edc\u4e2d\u7684\u4f20\u64ad\u65b9\u5f0f\uff0c\u5e76\u523b\u753b\u4e86\u6700\u4f18\u7684\u5b9a\u5411\u5e72\u9884\u7b56\u7565\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u6709\u6548\u7684\u653f\u7b56\u8bbe\u8ba1\u5fc5\u987b\u8003\u8651\u52aa\u529b\u5728\u5404\u5c42\u4e4b\u95f4\u7684\u5206\u914d\u3002\u6211\u4eec\u8fd8\u8bc1\u660e\uff0c\u5355\u5c42\u6a21\u578b\u7684\u9884\u6d4b\u53ef\u80fd\u4e0e\u591a\u91cd\u7f51\u7edc\u6a21\u578b\u7684\u9884\u6d4b\u51fa\u73b0\u663e\u8457\u5dee\u5f02\uff0c\u5f3a\u8c03\u4e86\u5728\u5b9e\u8bc1\u5206\u6790\u548c\u653f\u7b56\u5206\u6790\u4e2d\u8003\u8651\u7f51\u7edc\u590d\u6742\u6027\u7684\u91cd\u8981\u6027\u3002\uff08JEL C70, D78, D82, D85, H41, Z13\uff09", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1257/aer.20241056", "journal": "AER", "title": "Similarity of Information and Collective Action", "authors": ["Deepal Basak", "Joyee Deb", "Aditya Kuvalekar"], "author_details": [{"name": "Deepal Basak", "affiliations": ["Indiana University (email: )"]}, {"name": "Joyee Deb", "affiliations": ["New York University (email: )"]}, {"name": "Aditya Kuvalekar", "affiliations": ["University of Essex (email: )"]}], "abstract": "We study a canonical collective action game with incomplete information. Individuals attempt to coordinate to achieve a shared goal, while also facing a temptation to free-ride. More similar information can help them coordinate, but it can also exacerbate free-riding. Our main result shows that more similar information facilitates (impedes) achieving the common goal when it is sufficiently challenging (easy). We apply this insight to show why less powerful authoritarian governments may face larger protests if they restrict press freedom, when committee diversity is beneficial in costly voting, and when a more diverse community contributes more to public good provision. (JEL C71, D71, D72, D81, D82, D83, H41)", "date": "2026-04-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20241056", "title_zh": "\u4fe1\u606f\u76f8\u4f3c\u6027\u4e0e\u96c6\u4f53\u884c\u52a8", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u4e2a\u5177\u6709\u4e0d\u5b8c\u5168\u4fe1\u606f\u7684\u5178\u578b\u96c6\u4f53\u884c\u52a8\u535a\u5f08\u3002\u4e2a\u4f53\u8bd5\u56fe\u534f\u8c03\u4ee5\u5b9e\u73b0\u5171\u540c\u76ee\u6807\uff0c\u540c\u65f6\u9762\u4e34\u642d\u4fbf\u8f66\u7684\u8bf1\u60d1\u3002\u4fe1\u606f\u8d8a\u76f8\u4f3c\uff0c\u6709\u52a9\u4e8e\u534f\u8c03\uff0c\u4f46\u4e5f\u53ef\u80fd\u52a0\u5267\u642d\u4fbf\u8f66\u884c\u4e3a\u3002\u6211\u4eec\u7684\u4e3b\u8981\u7ed3\u679c\u8868\u660e\uff0c\u5f53\u5171\u540c\u76ee\u6807\u8db3\u591f\u5177\u6709\u6311\u6218\u6027\u65f6\uff0c\u4fe1\u606f\u76f8\u4f3c\u6027\u6709\u52a9\u4e8e\u5b9e\u73b0\u8be5\u76ee\u6807\uff1b\u5f53\u76ee\u6807\u76f8\u5bf9\u5bb9\u6613\u65f6\uff0c\u4fe1\u606f\u76f8\u4f3c\u6027\u5219\u4f1a\u963b\u788d\u76ee\u6807\u7684\u5b9e\u73b0\u3002\u6211\u4eec\u57fa\u4e8e\u8fd9\u4e00\u6d1e\u5bdf\uff0c\u89e3\u91ca\u4e86\u4e3a\u4f55\u6743\u529b\u8f83\u5f31\u7684\u5a01\u6743\u653f\u5e9c\u82e5\u9650\u5236\u65b0\u95fb\u81ea\u7531\uff0c\u53ef\u80fd\u4f1a\u9762\u4e34\u66f4\u5927\u7684\u6297\u8bae\u6d3b\u52a8\uff0c\u5c24\u5176\u662f\u5728\u59d4\u5458\u4f1a\u591a\u6837\u6027\u6709\u52a9\u4e8e\u6210\u672c\u9ad8\u6602\u7684\u6295\u7968\u51b3\u7b56\uff0c\u4ee5\u53ca\u66f4\u591a\u5143\u5316\u7684\u793e\u533a\u5bf9\u516c\u5171\u7269\u54c1\u4f9b\u7ed9\u8d21\u732e\u66f4\u5927\u7684\u60c5\u51b5\u4e0b\u3002\uff08JEL C71, D71, D72, D81, D82, D83, H41\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240636", "journal": "AER", "title": "Negative Control Falsification Tests for Instrumental Variable Designs", "authors": ["Oren Danieli", "Daniel Nevo", "Itai Walk", "Bar Weinstein", "Dan Zeltzer"], "author_details": [{"name": "Oren Danieli", "affiliations": ["Tel Aviv University (email: )"]}, {"name": "Daniel Nevo", "affiliations": ["Tel Aviv University (email: )"]}, {"name": "Itai Walk", "affiliations": ["Tel Aviv University (email: )"]}, {"name": "Bar Weinstein", "affiliations": ["Tel Aviv University (email: )"]}, {"name": "Dan Zeltzer", "affiliations": ["Tel Aviv University and University of California, Berkeley (email: )"]}], "abstract": "The validity of instrumental variable (IV) designs is typically tested using two types of falsification tests. We characterize these tests as conditional independence tests between negative control variables\u2014proxies for unobserved variables posing a threat to the identification\u2014and the IV or the outcome. We describe the conditions variables must satisfy in order to serve as negative controls. We show these falsification tests examine not only independence and the exclusion restriction but also functional form assumptions. Our analysis reveals conventional applications of these tests may flag problems even in valid IV designs. We offer implementation guidance to address these issues. (JEL C12, C18, C26, C52)", "date": "2026-04-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240636", "title_zh": "\u5de5\u5177\u53d8\u91cf\u8bbe\u8ba1\u7684\u8d1f\u63a7\u5236 falsification \u6d4b\u8bd5", "abstract_zh": "\u5de5\u5177\u53d8\u91cf\uff08IV\uff09\u8bbe\u8ba1\u7684\u6709\u6548\u6027\u901a\u5e38\u901a\u8fc7\u4e24\u79cd\u7c7b\u578b\u7684\u9a8c\u8bc1\u6d4b\u8bd5\u6765\u68c0\u9a8c\u3002\u6211\u4eec\u5c06\u8fd9\u4e9b\u6d4b\u8bd5\u63cf\u8ff0\u4e3a\u8d1f\u63a7\u5236\u53d8\u91cf\u2014\u2014\u5373\u6f5c\u5728\u672a\u89c2\u6d4b\u53d8\u91cf\u5a01\u80c1\u5230\u8bc6\u522b\u7684\u4ee3\u7406\u53d8\u91cf\u2014\u2014\u4e0e\u5de5\u5177\u53d8\u91cf\u6216\u7ed3\u679c\u4e4b\u95f4\u7684\u6761\u4ef6\u72ec\u7acb\u6027\u6d4b\u8bd5\u3002\u6211\u4eec\u9610\u8ff0\u4e86\u53d8\u91cf\u4f5c\u4e3a\u8d1f\u63a7\u5236\u53d8\u91cf\u5fc5\u987b\u6ee1\u8db3\u7684\u6761\u4ef6\u3002\u6211\u4eec\u8868\u660e\uff0c\u8fd9\u4e9b\u9a8c\u8bc1\u6d4b\u8bd5\u4e0d\u4ec5\u68c0\u9a8c\u72ec\u7acb\u6027\u548c\u6392\u9664\u9650\u5236\uff0c\u8fd8\u68c0\u9a8c\u51fd\u6570\u5f62\u5f0f\u5047\u8bbe\u3002\u6211\u4eec\u7684\u5206\u6790\u53d1\u73b0\uff0c\u4f20\u7edf\u5e94\u7528\u8fd9\u4e9b\u6d4b\u8bd5\u53ef\u80fd\u4f1a\u5728\u6709\u6548IV\u8bbe\u8ba1\u4e2d\u4e5f\u6807\u8bb0\u51fa\u95ee\u9898\u3002\u6211\u4eec\u63d0\u4f9b\u4e86\u5b9e\u65bd\u6307\u5bfc\u4ee5\u89e3\u51b3\u8fd9\u4e9b\u95ee\u9898\u3002\uff08JEL C12\uff0cC18\uff0cC26\uff0cC52\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20231202", "journal": "AER", "title": "Market Power and Capital Constraints", "authors": ["Milena Wittwer", "Jason Allen"], "author_details": [{"name": "Milena Wittwer", "affiliations": ["Columbia University, NBER, and CEPR (email: )"]}, {"name": "Jason Allen", "affiliations": ["Bank of Canada and University of Wisconsin School of Business (email: )"]}], "abstract": "We explore how traders\u2019 equity capitalization influences asset prices in a framework that accounts for market power. In our model, traders with capital constraints engage in transactions in an imperfectly competitive market. We demonstrate that looser capital constraints elevate both asset prices and price impact, the latter diminishing market liquidity. Using Canadian Treasury auction data, we illustrate how to apply our model to quantify these effects. We estimate the shadow costs of capital constraints by leveraging a temporary policy exemption during 2020\u20132021. We show that while these constraints are only infrequently binding, their relative impact when activated can be sizable. (JEL E63, G12, G14, G23, G41, L13)", "date": "2026-04-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20231202", "title_zh": "\u5e02\u573a\u529b\u91cf\u4e0e\u8d44\u672c\u7ea6\u675f", "abstract_zh": "\u6211\u4eec\u63a2\u8ba8\u4e86\u4ea4\u6613\u8005\u80a1\u6743\u8d44\u672c\u5982\u4f55\u5f71\u54cd\u8d44\u4ea7\u4ef7\u683c\uff0c\u8be5\u6846\u67b6\u8003\u8651\u4e86\u5e02\u573a\u529b\u91cf\u3002\u5728\u6211\u4eec\u7684\u6a21\u578b\u4e2d\uff0c\u5177\u6709\u8d44\u672c\u7ea6\u675f\u7684\u4ea4\u6613\u8005\u5728\u4e0d\u5b8c\u5168\u7ade\u4e89\u5e02\u573a\u4e2d\u8fdb\u884c\u4ea4\u6613\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u66f4\u5bbd\u677e\u7684\u8d44\u672c\u7ea6\u675f\u4f1a\u63d0\u9ad8\u8d44\u4ea7\u4ef7\u683c\u548c\u4ef7\u683c\u5f71\u54cd\uff0c\u540e\u8005\u4f1a\u964d\u4f4e\u5e02\u573a\u6d41\u52a8\u6027\u3002\u5229\u7528\u52a0\u62ff\u5927\u56fd\u503a\u62cd\u5356\u6570\u636e\uff0c\u6211\u4eec\u5c55\u793a\u4e86\u5982\u4f55\u5c06\u8be5\u6a21\u578b\u5e94\u7528\u4e8e\u91cf\u5316\u8fd9\u4e9b\u6548\u5e94\u3002\u6211\u4eec\u901a\u8fc7\u5229\u75282020\u20132021\u5e74\u671f\u95f4\u7684\u4e00\u9879\u4e34\u65f6\u653f\u7b56\u8c41\u514d\uff0c\u4f30\u8ba1\u4e86\u8d44\u672c\u7ea6\u675f\u7684\u5f71\u5b50\u6210\u672c\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5c3d\u7ba1\u8fd9\u4e9b\u7ea6\u675f\u5f88\u5c11\u88ab\u89e6\u53d1\uff0c\u4f46\u4e00\u65e6\u88ab\u6fc0\u6d3b\uff0c\u5176\u76f8\u5bf9\u5f71\u54cd\u53ef\u80fd\u76f8\u5f53\u663e\u8457\u3002\uff08JEL E63, G12, G14, G23, G41, L13\uff09", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/qje/qjag019", "journal": "QJE", "title": "\u201cCompensate the Losers?\u201d Economic Policy and the Origins of U.S. Partisan Realignment", "authors": ["Ilyana Kuziemko", "Nicolas Longuet-Marx", "Suresh Naidu"], "author_details": [{"name": "Ilyana Kuziemko", "affiliations": ["Princeton University ,"]}, {"name": "Nicolas Longuet-Marx", "affiliations": ["Stanford University ,"]}, {"name": "Suresh Naidu", "affiliations": ["Columbia University ,"]}], "abstract": "Abstract We argue that the Democratic Party\u2019s evolution on economic policy helps explain partisan realignment by education. First, we document that educated Americans differentially oppose \u201cpredistribution\u201d (e.g., job guarantees, higher minimum wages, protectionism, and stronger unions), while the educational gradient for redistribution (taxes and transfers) is close to zero. These relationships have been largely unchanged since the 1940s. Second, focusing on politicians and donors as key party actors, we show that the Democratic Party has moved away from predistribution since the 1970s. The number of predistribution bills introduced by Democratic House Speakers has declined by half since the 1970s. Unions\u2014the traditional lobbying force for predistribution\u2014see their share of Democratic Party PAC donations decline from 90% to 40% from 1968 to 1980, following 1970s legislation that facilitated corporate PAC donations. From 1980 onward, the Democrats rely increasingly on individual contributions from educated donors relative to the Republicans. We show the increased reliance on corporate PACs and educated donors is driven by the rise of a self-described \u201cNew Democrat\u2019\u2019 faction particularly conservative on predistribution and social issues. Finally, we trace the reaction of voters to these changes in the Democratic Party. Less-educated Americans begin to leave the party in the 1970s, after decades of serving as its base. We also show that in the crucial transition period of the 1970s through 1990s, New Democrat candidates outperform other Democrats among more-educated voters in both survey questions and actual Congressional elections. As the New Democrats are more socially conservative than other Democrats, their success with educated voters suggests that social issues alone cannot explain educational realignment.", "date": "2026-04-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag019", "title_zh": "\u201c\u8865\u507f\u5931\u8d25\u8005\u201d\uff1f\u7ecf\u6d4e\u653f\u7b56\u4e0e\u7f8e\u56fd\u653f\u515a\u9635\u8425\u91cd\u7ec4\u7684\u8d77\u6e90", "abstract_zh": "\u6211\u4eec\u4e3b\u5f20\uff0c\u6c11\u4e3b\u515a\u5728\u7ecf\u6d4e\u653f\u7b56\u4e0a\u7684\u6f14\u53d8\u6709\u52a9\u4e8e\u89e3\u91ca\u7531\u6559\u80b2\u6c34\u5e73\u5f15\u53d1\u7684\u653f\u515a\u91cd\u7ec4\u3002\u9996\u5148\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u53d7\u8fc7\u6559\u80b2\u7684\u7f8e\u56fd\u4eba\u5bf9\u201c\u4e8b\u524d\u5206\u914d\u201d\uff08\u4f8b\u5982\u5c31\u4e1a\u5c97\u4f4d\u4fdd\u969c\u3001\u63d0\u9ad8\u6700\u4f4e\u5de5\u8d44\u3001\u4fdd\u62a4\u4e3b\u4e49\u548c\u66f4\u5f3a\u7684\u5de5\u4f1a\uff09\u6301\u5dee\u5f02\u5316\u53cd\u5bf9\u6001\u5ea6\uff0c\u800c\u6559\u80b2\u6c34\u5e73\u4e0e\u518d\u5206\u914d\uff08\u7a0e\u6536\u548c\u8f6c\u79fb\u652f\u4ed8\uff09\u4e4b\u95f4\u7684\u5173\u7cfb\u5219\u63a5\u8fd1\u4e8e\u96f6\u3002\u8fd9\u4e9b\u5173\u7cfb\u81ea20\u4e16\u7eaa40\u5e74\u4ee3\u4ee5\u6765\u57fa\u672c\u4fdd\u6301\u4e0d\u53d8\u3002\u5176\u6b21\uff0c\u805a\u7126\u4e8e\u653f\u6cbb\u4eba\u7269\u548c\u6350\u52a9\u8005\u4f5c\u4e3a\u653f\u515a\u4e2d\u7684\u5173\u952e\u89d2\u8272\uff0c\u6211\u4eec\u8868\u660e\uff0c\u81ea20\u4e16\u7eaa70\u5e74\u4ee3\u4ee5\u6765\uff0c\u6c11\u4e3b\u515a\u5df2\u9010\u6e10\u8fdc\u79bb\u4e8b\u524d\u5206\u914d\u653f\u7b56\u3002\u81ea1970\u5e74\u4ee3\u4ee5\u6765\uff0c\u6c11\u4e3b\u515a\u4f17\u8bae\u9662\u8bae\u957f\u63d0\u51fa\u7684\u201c\u4e8b\u524d\u5206\u914d\u201d\u6cd5\u6848\u6570\u91cf\u51cf\u5c11\u4e86\u534a\u6570\u3002\u5de5\u4f1a\u2014\u2014\u8fc7\u53bb\u63a8\u52a8\u4e8b\u524d\u5206\u914d\u7684\u4e3b\u8981\u6e38\u8bf4\u529b\u91cf\u2014\u2014\u5728\u6c11\u4e3b\u515a\u515a\u56e2\u6350\u6b3e\u4e2d\u7684\u4efd\u989d\u4ece1968\u5e74\u52301980\u5e74\u768490%\u4e0b\u964d\u81f340%\uff0c\u8fd9\u4e00\u53d8\u5316\u53d1\u751f\u57281970\u5e74\u4ee3\u901a\u8fc7\u4fc3\u8fdb\u4f01\u4e1aPAC\u6350\u6b3e\u7684\u7acb\u6cd5\u4e4b\u540e\u3002\u81ea1980\u5e74\u8d77\uff0c\u6c11\u4e3b\u515a\u8d8a\u6765\u8d8a\u4f9d\u8d56\u53d7\u8fc7\u6559\u80b2\u7684\u4e2a\u4eba\u6350\u6b3e\uff0c\u800c\u975e\u5171\u548c\u515a\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5bf9\u4f01\u4e1a\u548c\u53d7\u8fc7\u6559\u80b2\u7684\u6350\u8d60\u8005\u65e5\u76ca\u4f9d\u8d56\u7684\u73b0\u8c61\uff0c\u662f\u7531\u4e00\u4e2a\u81ea\u79f0\u201c\u65b0\u6c11\u4e3b\u515a\u4eba\u201d\u7684\u6d3e\u7cfb\u5d1b\u8d77\u6240\u9a71\u52a8\u7684\uff0c\u8be5\u6d3e\u7cfb\u5728\u4e8b\u524d\u5206\u914d\u548c\u793e\u4f1a\u8bae\u9898\u4e0a\u5c24\u4e3a\u4fdd\u5b88\u3002\u6700\u540e\uff0c\u6211\u4eec\u8ffd\u8e2a\u4e86\u9009\u6c11\u5bf9\u6c11\u4e3b\u515a\u653f\u7b56\u53d8\u5316\u7684\u53cd\u5e94\u300220\u4e16\u7eaa70\u5e74\u4ee3\u8d77\uff0c\u53d7\u6559\u80b2\u7a0b\u5ea6\u8f83\u4f4e\u7684\u7f8e\u56fd\u4eba\u5f00\u59cb\u79bb\u5f00\u8be5\u515a\uff0c\u8fd9\u5728\u51e0\u5341\u5e74\u6765\u4ed6\u4eec\u4e00\u76f4\u662f\u8be5\u515a\u57fa\u7840\u7684\u80cc\u666f\u4e0b\u53d1\u751f\u3002\u6b64\u5916\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u57281970\u5e74\u4ee3\u81f31990\u5e74\u4ee3\u7684\u5173\u952e\u8f6c\u578b\u671f\uff0c\u65b0\u6c11\u4e3b\u515a\u5019\u9009\u4eba\u76f8\u5bf9\u4e8e\u5176\u4ed6\u6c11\u4e3b\u515a\u5019\u9009\u4eba\uff0c\u5728\u8c03\u67e5\u95ee\u5377\u548c\u5b9e\u9645\u56fd\u4f1a\u9009\u4e3e\u4e2d\u5747\u5728\u53d7\u8fc7\u6559\u80b2\u7684\u9009\u6c11\u4e2d\u8868\u73b0\u66f4\u4f73\u3002\u7531\u4e8e\u65b0\u6c11\u4e3b\u515a\u4eba\u6bd4\u5176\u4ed6\u6c11\u4e3b\u515a\u4eba\u66f4\u4e3a\u793e\u4f1a\u4fdd\u5b88\uff0c\u4ed6\u4eec\u5728\u53d7\u6559\u80b2\u9009\u6c11\u4e2d\u7684\u6210\u529f\u8868\u660e\uff0c\u793e\u4f1a\u8bae\u9898\u672c\u8eab\u65e0\u6cd5\u89e3\u91ca\u6559\u80b2\u6c34\u5e73\u7684\u653f\u515a\u91cd\u7ec4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70035", "journal": "JF", "title": "Corporate M&As and Labor Market Concentration: Efficiency Gains or Power Grabs?", "authors": ["DAVID CICERO", "MO SHEN", "JAIDEEP SHENOY"], "author_details": [{"name": "DAVID CICERO", "affiliations": []}, {"name": "MO SHEN", "affiliations": []}, {"name": "JAIDEEP SHENOY", "affiliations": []}], "abstract": "ABSTRACT Mergers of firms that share labor markets increase labor market concentration which can lead to labor efficiency gains and/or create labor market power for the merged firms. Using a novel measure based on establishment\u2010level employment data, we find that merger\u2010induced increases in labor market concentration explain value creation in a sample of completed U.S. public firm mergers from 1991 to 2016. Analysis of the stock market reactions of rival, supplier, and customer firms, as well as firm\u2010 and establishment\u2010level real effects in the merging firms, supports a labor efficiency explanation of these merger gains.", "date": "2026-04-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70035", "title_zh": "\u4f01\u4e1a\u5e76\u8d2d\u4e0e\u52b3\u52a8\u529b\u5e02\u573a\u96c6\u4e2d\u5ea6\uff1a\u6548\u7387\u63d0\u5347\u8fd8\u662f\u6743\u529b\u6269\u5f20\uff1f", "abstract_zh": "\u6458\u8981 \u5e02\u573a\u4e2d\u5171\u4eab\u52b3\u52a8\u529b\u5e02\u573a\u7684\u4f01\u4e1a\u5408\u5e76\u4f1a\u63d0\u9ad8\u52b3\u52a8\u529b\u5e02\u573a\u7684\u96c6\u4e2d\u5ea6\uff0c\u8fd9\u53ef\u80fd\u5bfc\u81f4\u52b3\u52a8\u529b\u6548\u7387\u63d0\u5347\uff0c\u6216\u4f7f\u5408\u5e76\u4f01\u4e1a\u83b7\u5f97\u52b3\u52a8\u529b\u5e02\u573a\u6743\u529b\u3002\u57fa\u4e8e\u4f01\u4e1a\u5c42\u9762\u5c31\u4e1a\u6570\u636e\u7684\u65b0\u578b\u6307\u6807\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u57281991\u5e74\u81f32016\u5e74\u671f\u95f4\u5b8c\u6210\u7684\u7f8e\u56fd\u4e0a\u5e02\u516c\u53f8\u5e76\u8d2d\u6848\u4f8b\u4e2d\uff0c\u7531\u5e76\u8d2d\u5f15\u53d1\u7684\u52b3\u52a8\u529b\u5e02\u573a\u96c6\u4e2d\u5ea6\u63d0\u5347\u89e3\u91ca\u4e86\u4f01\u4e1a\u4ef7\u503c\u7684\u521b\u9020\u3002\u5bf9\u7ade\u4e89\u5bf9\u624b\u3001\u4f9b\u5e94\u5546\u548c\u5ba2\u6237\u4f01\u4e1a\u7684\u80a1\u7968\u5e02\u573a\u53cd\u5e94\uff0c\u4ee5\u53ca\u5408\u5e76\u4f01\u4e1a\u4e2d\u4f01\u4e1a\u5c42\u9762\u548c\u7ecf\u8425\u573a\u6240\u5c42\u9762\u7684\u5b9e\u9645\u7ecf\u6d4e\u6548\u5e94\u7684\u5206\u6790\uff0c\u652f\u6301\u4e86\u5e76\u8d2d\u6536\u76ca\u6e90\u4e8e\u52b3\u52a8\u529b\u6548\u7387\u63d0\u5347\u7684\u89e3\u91ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc", "\u5e76\u8d2d"]}, {"doi": "10.1017/s0022109026102816", "journal": "JFQA", "title": "Why Do Bank Boards Have Risk Committees?", "authors": ["Ren\u00e9 M. Stulz", "James Tompkins", "Rohan Williamson", "Zhongxia (Shelly) Ye"], "author_details": [{"name": "Ren\u00e9 M. Stulz", "affiliations": ["The Ohio State University Department of Finance"]}, {"name": "James Tompkins", "affiliations": ["Kennesaw State University"]}, {"name": "Rohan Williamson", "affiliations": ["Georgetown University"]}, {"name": "Zhongxia (Shelly) Ye", "affiliations": ["The University of Texas at San Antonio"]}], "abstract": "Abstract While the Dodd\u2013Frank Act (DFA) mandates board risk committees for large banks, we argue that such committees do not benefit all banks. Banks forced by the DFA to adopt a board risk committee do not experience a reduction in risk following adoption. In contrast, banks that voluntarily established risk committees before the DFA exhibit lower risk, especially when these committees possess greater risk expertise. Using unique interview data, we find that board risk committees serve as active monitors rather than merely rubber-stamping management proposals. However, regulatory-mandated tasks limit their monitoring role.", "date": "2026-04-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102816", "title_zh": "\u4e3a\u4ec0\u4e48\u94f6\u884c\u8463\u4e8b\u4f1a\u8981\u8bbe\u7acb\u98ce\u9669\u59d4\u5458\u4f1a\uff1f", "abstract_zh": "\u5c3d\u7ba1\u300a\u591a\u5fb7-\u5f17\u5170\u514b\u6cd5\u6848\u300b\uff08DFA\uff09\u8981\u6c42\u5927\u578b\u94f6\u884c\u8bbe\u7acb\u8463\u4e8b\u4f1a\u98ce\u9669\u59d4\u5458\u4f1a\uff0c\u4f46\u6211\u4eec\u8ba4\u4e3a\u8fd9\u7c7b\u59d4\u5458\u4f1a\u5bf9\u6240\u6709\u94f6\u884c\u800c\u8a00\u5e76\u4e0d\u4e00\u5b9a\u6709\u76ca\u3002\u88abDFA\u5f3a\u5236\u8bbe\u7acb\u98ce\u9669\u59d4\u5458\u4f1a\u7684\u94f6\u884c\u5728\u91c7\u7eb3\u540e\u5e76\u672a\u51fa\u73b0\u98ce\u9669\u4e0b\u964d\u3002\u76f8\u53cd\uff0c\u90a3\u4e9b\u5728DFA\u5b9e\u65bd\u524d\u81ea\u613f\u8bbe\u7acb\u98ce\u9669\u59d4\u5458\u4f1a\u7684\u94f6\u884c\uff0c\u5176\u98ce\u9669\u6c34\u5e73\u66f4\u4f4e\uff0c\u5c24\u5176\u662f\u5f53\u8fd9\u4e9b\u59d4\u5458\u4f1a\u5177\u5907\u66f4\u5f3a\u7684\u98ce\u9669\u4e13\u4e1a\u80fd\u529b\u65f6\u3002\u57fa\u4e8e\u72ec\u7279\u7684\u8bbf\u8c08\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u8463\u4e8b\u4f1a\u98ce\u9669\u59d4\u5458\u4f1a\u5b9e\u9645\u4e0a\u626e\u6f14\u7740\u79ef\u6781\u76d1\u7763\u7684\u89d2\u8272\uff0c\u800c\u975e\u7b80\u5355\u5730\u6279\u51c6\u7ba1\u7406\u5c42\u7684\u63d0\u6848\u3002\u7136\u800c\uff0c\u76d1\u7ba1\u5f3a\u5236\u6027\u4efb\u52a1\u9650\u5236\u4e86\u5176\u76d1\u7763\u529f\u80fd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag028", "journal": "RFS", "title": "The Product Market Effects of Index Inclusion", "authors": ["Varun Sharma"], "author_details": [{"name": "Varun Sharma", "affiliations": ["Indiana University Kelley School of Business,"]}], "abstract": "Abstract I investigate how index membership affects firms\u2019 product-market strategy. After plausibly exogenous index inclusion, firms gain market share by reducing product prices, giving better trade credit, and increasing sales and marketing expenses. Firms reduce prices for products with low market share and higher switching costs and habits. This comes at the cost of lower profitability, which increases in subsequent periods. Further analysis suggests that managerial learning about an improved funding environment from the post\u2013index inclusion stock price increase is the underlying channel that leads to the observed increase in investment to gain market share. A model further corroborates these findings.", "date": "2026-03-31", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag028", "title_zh": "\u6307\u6570\u7eb3\u5165\u5bf9\u4f01\u4e1a\u4ea7\u54c1\u5e02\u573a\u7b56\u7565\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u7814\u7a76\u4e86\u6307\u6570\u6210\u5458\u8d44\u683c\u5982\u4f55\u5f71\u54cd\u4f01\u4e1a\u7684\u4ea7\u54c1\u5e02\u573a\u7b56\u7565\u3002\u5728\u5408\u7406\u5916\u751f\u7684\u6307\u6570\u7eb3\u5165\u4e4b\u540e\uff0c\u4f01\u4e1a\u901a\u8fc7\u964d\u4f4e\u4ea7\u54c1\u4ef7\u683c\u3001\u63d0\u4f9b\u66f4\u597d\u7684\u8d38\u6613\u4fe1\u7528\u4ee5\u53ca\u589e\u52a0\u9500\u552e\u548c\u8425\u9500\u652f\u51fa\u6765\u83b7\u5f97\u5e02\u573a\u4efd\u989d\u3002\u4f01\u4e1a\u5bf9\u5e02\u573a\u4efd\u989d\u8f83\u4f4e\u4e14\u5207\u6362\u6210\u672c\u8f83\u9ad8\u6216\u5177\u6709\u4e60\u60ef\u6027\u7684\u4ea7\u54c1\u964d\u4f4e\u4ef7\u683c\uff0c\u8fd9\u5bfc\u81f4\u76c8\u5229\u80fd\u529b\u4e0b\u964d\uff0c\u5e76\u5728\u540e\u7eed\u671f\u95f4\u8fdb\u4e00\u6b65\u6076\u5316\u3002\u8fdb\u4e00\u6b65\u5206\u6790\u8868\u660e\uff0c\u7ba1\u7406\u5c42\u4ece\u6307\u6570\u7eb3\u5165\u540e\u80a1\u4ef7\u4e0a\u6da8\u4e2d\u83b7\u5f97\u5bf9\u878d\u8d44\u73af\u5883\u6539\u5584\u7684\u4e86\u89e3\uff0c\u662f\u5bfc\u81f4\u4f01\u4e1a\u589e\u52a0\u6295\u8d44\u4ee5\u83b7\u53d6\u5e02\u573a\u4efd\u989d\u7684\u6f5c\u5728\u673a\u5236\u3002\u4e00\u4e2a\u6a21\u578b\u8fdb\u4e00\u6b65\u8bc1\u5b9e\u4e86\u8fd9\u4e9b\u53d1\u73b0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag018", "journal": "RFS", "title": "Bond Convenience Yields in the Eurozone Currency Union", "authors": ["Zhengyang Jiang", "Hanno Lustig", "Stijn Van Nieuwerburgh", "Mindy Z Xiaolan"], "author_details": [{"name": "Zhengyang Jiang", "affiliations": ["Kellogg School of Management, Northwestern University, NBER ,"]}, {"name": "Hanno Lustig", "affiliations": ["Graduate School of Business, Stanford University, NBER, SIEPR ,"]}, {"name": "Stijn Van Nieuwerburgh", "affiliations": ["Columbia Business School, Columbia University, NBER, CEPR ,"]}, {"name": "Mindy Z Xiaolan", "affiliations": ["McCombs School of Business, University of Texas at Austin ,"]}], "abstract": "Abstract In a monetary union, the risk-free rate cannot adjust to country-level fiscal positions, leaving only default spreads and convenience yields to respond. Empirically, we find that convenience yields explain a large share of the variation in eurozone (EZ) sovereign bond yields. EZ sovereign bonds earn larger convenience yields when their governments run larger surpluses. Since convenience yields generate substantial seigniorage revenue from debt issuance, our estimates imply economically large fiscal costs from low convenience yields for peripheral countries in the EZ.", "date": "2026-03-31", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag018", "title_zh": "\u6b27\u5143\u533a\u8d27\u5e01\u8054\u76df\u4e2d\u7684\u503a\u5238\u4fbf\u5229\u6536\u76ca\u7387", "abstract_zh": "\u5728\u8d27\u5e01\u8054\u76df\u4e2d\uff0c\u65e0\u98ce\u9669\u5229\u7387\u65e0\u6cd5\u8c03\u6574\u4ee5\u53cd\u6620\u5404\u56fd\u7684\u8d22\u653f\u72b6\u51b5\uff0c\u53ea\u80fd\u901a\u8fc7\u8fdd\u7ea6\u5229\u5dee\u548c\u4fbf\u5229\u6536\u76ca\u7387\u6765\u5e94\u5bf9\u3002\u5b9e\u8bc1\u7814\u7a76\u8868\u660e\uff0c\u4fbf\u5229\u6536\u76ca\u7387\u89e3\u91ca\u4e86\u6b27\u5143\u533a\uff08EZ\uff09\u4e3b\u6743\u503a\u5238\u6536\u76ca\u7387\u7684\u5927\u90e8\u5206\u53d8\u5316\u3002\u5f53\u653f\u5e9c\u8d22\u653f\u51fa\u73b0\u8f83\u5927\u76c8\u4f59\u65f6\uff0c\u6b27\u5143\u533a\u4e3b\u6743\u503a\u5238\u7684\u4fbf\u5229\u6536\u76ca\u7387\u66f4\u9ad8\u3002\u7531\u4e8e\u4fbf\u5229\u6536\u76ca\u7387\u4ece\u503a\u52a1\u53d1\u884c\u4e2d\u4ea7\u751f\u5927\u91cf\u94f8\u5e01\u7a0e\u6536\u5165\uff0c\u6211\u4eec\u7684\u4f30\u8ba1\u8868\u660e\uff0c\u6b27\u5143\u533a\u5916\u56f4\u56fd\u5bb6\u7684\u4fbf\u5229\u6536\u76ca\u7387\u504f\u4f4e\u4f1a\u5e26\u6765\u5de8\u5927\u7684\u8d22\u653f\u6210\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70037", "journal": "JF", "title": "The Voting Premium", "authors": ["DORON LEVIT", "NADYA MALENKO", "ERNST MAUG"], "author_details": [{"name": "DORON LEVIT", "affiliations": []}, {"name": "NADYA MALENKO", "affiliations": []}, {"name": "ERNST MAUG", "affiliations": []}], "abstract": "ABSTRACT We develop a unified theory of blockholder governance and the voting premium in a setting without takeovers or controlling shareholders. A voting premium emerges when a minority blockholder can influence shareholder composition by accumulating votes and buying shares from dissenting shareholders. Our theory reconciles conflicting empirical findings by showing that standard measures of the voting premium often misrepresent the true value of voting rights, increased conflicts between the blockholder and small shareholders do not necessarily raise the voting premium, and the voting premium can even turn negative when small shareholders free\u2010ride on the blockholder's trades.", "date": "2026-03-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70037", "title_zh": "\u6295\u7968\u6ea2\u4ef7", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5728\u6ca1\u6709\u5e76\u8d2d\u6216\u63a7\u80a1\u80a1\u4e1c\u7684\u60c5\u51b5\u4e0b\uff0c\u6784\u5efa\u4e86\u4e00\u4e2a\u7edf\u4e00\u7684\u5757\u6301\u6709\u8005\u6cbb\u7406\u548c\u6295\u7968\u6ea2\u4ef7\u7406\u8bba\u3002\u5f53\u5c11\u6570\u5757\u6301\u6709\u8005\u901a\u8fc7\u79ef\u7d2f\u6295\u7968\u6743\u5e76\u4ece\u6301\u4e0d\u540c\u610f\u89c1\u7684\u80a1\u4e1c\u5904\u8d2d\u4e70\u80a1\u4efd\u6765\u5f71\u54cd\u80a1\u4e1c\u6784\u6210\u65f6\uff0c\u5c31\u4f1a\u51fa\u73b0\u6295\u7968\u6ea2\u4ef7\u3002\u6211\u4eec\u7684\u7406\u8bba\u901a\u8fc7\u8868\u660e\uff0c\u6807\u51c6\u7684\u6295\u7968\u6ea2\u4ef7\u8861\u91cf\u65b9\u6cd5\u5f80\u5f80\u65e0\u6cd5\u51c6\u786e\u53cd\u6620\u6295\u7968\u6743\u7684\u771f\u5b9e\u4ef7\u503c\uff0c\u5757\u6301\u6709\u8005\u4e0e\u5c0f\u80a1\u4e1c\u4e4b\u95f4\u51b2\u7a81\u7684\u589e\u52a0\u5e76\u4e0d\u5fc5\u7136\u5bfc\u81f4\u6295\u7968\u6ea2\u4ef7\u4e0a\u5347\uff0c\u751a\u81f3\u5728\u5c0f\u80a1\u4e1c\u642d\u4fbf\u8f66\u5229\u7528\u5757\u6301\u6709\u8005\u7684\u4ea4\u6613\u884c\u4e3a\u65f6\uff0c\u6295\u7968\u6ea2\u4ef7\u53ef\u80fd\u53d8\u4e3a\u8d1f\u503c\uff0c\u4ece\u800c\u8c03\u548c\u4e86\u4ee5\u5f80\u7814\u7a76\u4e2d\u7684\u77db\u76fe\u53d1\u73b0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1093/rfs/hhag011", "journal": "RFS", "title": "Beliefs and Portfolios: Causal Evidence", "authors": ["Johannes Beutel", "Michael Weber"], "author_details": [{"name": "Johannes Beutel", "affiliations": ["Deutsche Bundesbank ,"]}, {"name": "Michael Weber", "affiliations": ["Purdue University Daniels School of Business and NBER ,"]}], "abstract": "Abstract We causally test alternative theories of expectation formation. Using a randomized information experiment we show overreaction is a key feature of individuals\u2019 return expectations, and individuals\u2019 response to the price-earnings ratio is opposite of academic consensus. Our evidence is inconsistent with standard models of expectation formation, but subjective mental models that deviate from objective benchmarks can jointly explain the updating behavior in the experiment, the link between individuals\u2019 prior perceptions and expectations, and the heterogeneity of updating. Conditional on their beliefs, individuals\u2019 sensitivity of equity shares in a hypothetical portfolio choice experiment is consistent with the standard Merton model.", "date": "2026-03-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag011", "title_zh": "\u4fe1\u5ff5\u4e0e\u6295\u8d44\u7ec4\u5408\uff1a\u56e0\u679c\u8bc1\u636e", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u901a\u8fc7\u968f\u673a\u4fe1\u606f\u5b9e\u9a8c\u5bf9\u9884\u671f\u5f62\u6210\u7684\u4e0d\u540c\u7406\u8bba\u8fdb\u884c\u4e86\u56e0\u679c\u68c0\u9a8c\u3002\u5b9e\u9a8c\u7ed3\u679c\u663e\u793a\uff0c\u8fc7\u5ea6\u53cd\u5e94\u662f\u4e2a\u4eba\u5bf9\u56de\u62a5\u9884\u671f\u7684\u4e00\u4e2a\u5173\u952e\u7279\u5f81\uff0c\u4e2a\u4eba\u5bf9\u5e02\u76c8\u7387\u7684\u53cd\u5e94\u4e0e\u5b66\u672f\u754c\u7684\u5171\u8bc6\u76f8\u53cd\u3002\u6211\u4eec\u7684\u8bc1\u636e\u4e0e\u6807\u51c6\u9884\u671f\u5f62\u6210\u6a21\u578b\u4e0d\u4e00\u81f4\uff0c\u4f46\u4e3b\u89c2\u5fc3\u7406\u6a21\u578b\u82e5\u504f\u79bb\u5ba2\u89c2\u57fa\u51c6\uff0c\u5219\u53ef\u4ee5\u5171\u540c\u89e3\u91ca\u5b9e\u9a8c\u4e2d\u7684\u66f4\u65b0\u884c\u4e3a\u3001\u4e2a\u4f53\u5148\u9a8c\u611f\u77e5\u4e0e\u9884\u671f\u4e4b\u95f4\u7684\u8054\u7cfb\uff0c\u4ee5\u53ca\u66f4\u65b0\u884c\u4e3a\u7684\u5f02\u8d28\u6027\u3002\u5728\u4fe1\u5ff5\u6761\u4ef6\u4e0b\uff0c\u4e2a\u4eba\u5728\u5047\u8bbe\u6295\u8d44\u7ec4\u5408\u9009\u62e9\u5b9e\u9a8c\u4e2d\u5bf9\u80a1\u7968\u4efd\u989d\u7684\u654f\u611f\u6027\u4e0e\u6807\u51c6Merton\u6a21\u578b\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1111/jofi.70032", "journal": "JF", "title": "Specialization in Banking", "authors": ["KRISTIAN BLICKLE", "CECILIA PARLATORE", "ANTHONY SAUNDERS"], "author_details": [{"name": "KRISTIAN BLICKLE", "affiliations": []}, {"name": "CECILIA PARLATORE", "affiliations": []}, {"name": "ANTHONY SAUNDERS", "affiliations": []}], "abstract": "ABSTRACT Using supervisory data on the loan portfolios of large U.S. banks, we document that these banks specialize by concentrating their lending disproportionately in a few industries. This specialization is consistent with banks having industry\u2010specific knowledge, reflected in reduced risk of loan defaults, lower aggregate charge\u2010offs, and higher propensity to lend to opaque firms in the preferred industry. Banks attract high\u2010quality borrowers by offering generous loan terms in their specialized industry, especially to borrowers with alternative options. Banks focus on their preferred industry in times of instability and relatively lower Tier 1 capital as well as after surges in deposits.", "date": "2026-03-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70032", "title_zh": "\u94f6\u884c\u4e1a\u52a1\u7684\u4e13\u4e1a\u5316", "abstract_zh": "\u4f7f\u7528\u5bf9\u5927\u578b\u7f8e\u56fd\u94f6\u884c\u8d37\u6b3e\u7ec4\u5408\u7684\u76d1\u7ba1\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u8fd9\u4e9b\u94f6\u884c\u901a\u8fc7\u5c06\u8d37\u6b3e\u96c6\u4e2d\u4e8e\u5c11\u6570\u51e0\u4e2a\u884c\u4e1a\u6765\u5b9e\u73b0\u4e13\u4e1a\u5316\u3002\u8fd9\u79cd\u4e13\u4e1a\u5316\u4e0e\u94f6\u884c\u5177\u5907\u884c\u4e1a\u7279\u5b9a\u77e5\u8bc6\u76f8\u4e00\u81f4\uff0c\u8868\u73b0\u4e3a\u8d37\u6b3e\u8fdd\u7ea6\u98ce\u9669\u964d\u4f4e\u3001\u6574\u4f53\u574f\u8d26\u7387\u4e0b\u964d\uff0c\u4ee5\u53ca\u66f4\u503e\u5411\u4e8e\u5411\u5176\u9996\u9009\u884c\u4e1a\u7684\u4e0d\u900f\u660e\u4f01\u4e1a\u53d1\u653e\u8d37\u6b3e\u3002\u94f6\u884c\u901a\u8fc7\u5728\u4e13\u4e1a\u5316\u884c\u4e1a\u4e2d\u63d0\u4f9b\u4f18\u539a\u7684\u8d37\u6b3e\u6761\u4ef6\uff0c\u7279\u522b\u662f\u5bf9\u62e5\u6709\u5176\u4ed6\u878d\u8d44\u9009\u62e9\u7684\u501f\u6b3e\u4eba\uff0c\u5438\u5f15\u9ad8\u8d28\u91cf\u7684\u501f\u6b3e\u4eba\u3002\u5728\u5e02\u573a\u4e0d\u7a33\u5b9a\u65f6\u671f\u3001\u4e00\u7ea7\u8d44\u672c\u76f8\u5bf9\u8f83\u4f4e\u4ee5\u53ca\u5b58\u6b3e\u5927\u5e45\u589e\u957f\u4e4b\u540e\uff0c\u94f6\u884c\u4f1a\u66f4\u52a0\u4e13\u6ce8\u4e8e\u5176\u9996\u9009\u884c\u4e1a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhag031", "journal": "RFS", "title": "The Response of Mortgage Supply to Expected Flood Insurance Lapses", "authors": ["Zhongchen Hu"], "author_details": [{"name": "Zhongchen Hu", "affiliations": ["The Chinese University of Hong Kong , Shenzhen,"]}], "abstract": "Abstract Flooding is among the costliest natural disasters in many countries. To protect collateral, many mortgage borrowers in the United States are legally required to maintain flood insurance. However, lax enforcement leads to frequent policy lapses. This paper shows that lenders provide credit contingent on borrowers\u2019 insurance incentives. Exploiting exogenous premium rises ($266 annually) that disincentivize insurance take-up, I find mortgage denial rates dramatically increase by 0.49\u20130.81 pp. By comparison, lowering income by $266 has an effect of only 0.01 pp. Mortgage applicants\u2019 composition remains unchanged, refuting demand-side explanations. Evidence suggests lenders internalize ex-post monitoring costs into ex-ante credit restrictions.", "date": "2026-03-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag031", "title_zh": "\u9884\u671f\u6d2a\u6c34\u4fdd\u9669\u5931\u6548\u5bf9\u62b5\u62bc\u8d37\u6b3e\u4f9b\u7ed9\u7684\u53cd\u5e94", "abstract_zh": "\u6d2a\u6c34\u662f\u8bb8\u591a\u56fd\u5bb6\u6210\u672c\u6700\u9ad8\u7684\u81ea\u7136\u707e\u5bb3\u4e4b\u4e00\u3002\u4e3a\u4e86\u4fdd\u62a4\u62b5\u62bc\u54c1\uff0c\u7f8e\u56fd\u8bb8\u591a\u623f\u8d37\u501f\u6b3e\u4eba\u88ab\u6cd5\u5f8b\u8981\u6c42\u8d2d\u4e70\u6d2a\u6c34\u4fdd\u9669\u3002\u7136\u800c\uff0c\u6267\u884c\u4e0d\u4e25\u5bfc\u81f4\u4fdd\u9669\u5931\u6548\u9891\u7e41\u53d1\u751f\u3002\u672c\u6587\u8868\u660e\uff0c\u8d37\u6b3e\u673a\u6784\u4f1a\u6839\u636e\u501f\u6b3e\u4eba\u7684\u4fdd\u9669\u6fc0\u52b1\u60c5\u51b5\u63d0\u4f9b\u4fe1\u8d37\u3002\u5229\u7528\u5916\u751f\u6027\u7684\u4fdd\u8d39\u4e0a\u6da8\uff08\u6bcf\u5e74266\u7f8e\u5143\uff09\u8fd9\u4e00\u56e0\u7d20\uff0c\u8be5\u56e0\u7d20\u4f1a\u524a\u5f31\u6295\u4fdd\u610f\u613f\uff0c\u6211\u53d1\u73b0\u62b5\u62bc\u8d37\u6b3e\u62d2\u7edd\u7387\u663e\u8457\u4e0a\u53470.49\u81f30.81\u4e2a\u767e\u5206\u70b9\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u5c06\u6536\u5165\u964d\u4f4e266\u7f8e\u5143\u4ec5\u5bfc\u81f40.01\u4e2a\u767e\u5206\u70b9\u7684\u5f71\u54cd\u3002\u7533\u8bf7\u4eba\u7684\u6784\u6210\u672a\u53d1\u751f\u6539\u53d8\uff0c\u9a73\u65a5\u4e86\u9700\u6c42\u4fa7\u89e3\u91ca\u3002\u8bc1\u636e\u8868\u660e\uff0c\u8d37\u6b3e\u673a\u6784\u5df2\u5c06\u4e8b\u540e\u76d1\u63a7\u6210\u672c\u5185\u5316\u4e3a\u4e8b\u524d\u4fe1\u8d37\u9650\u5236\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag030", "journal": "RFS", "title": "Who Bears Flood Risk? Evidence from Mortgage Markets in Florida", "authors": ["Parinitha Sastry"], "author_details": [{"name": "Parinitha Sastry", "affiliations": ["The Wharton School, University of Pennsylvania ,"]}], "abstract": "Abstract Government-provided flood insurance contracts have strict coverage limits, leaving some households underinsured against flood risk. This paper exploits these strict coverage limits as well as staggered flood map updates to show that mortgage lenders screen for uninsurable flood risk by requiring lower loan-to-value ratios at origination. This credit rationing leads delinquency rates to equalize inside and outside of flood zones, and shifts the composition of mortgage borrowers in flood zones toward richer and higher credit quality individuals. I conclude that lenders reduce credit supply when they retain residual uninsured exposures to flood risk, which has distributional consequences for flood zones.", "date": "2026-03-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag030", "title_zh": "\u8c01\u627f\u62c5\u6d2a\u6c34\u98ce\u9669\uff1f\u6765\u81ea\u4f5b\u7f57\u91cc\u8fbe\u5dde\u62b5\u62bc\u5e02\u573a\u7684\u8bc1\u636e", "abstract_zh": "\u653f\u5e9c\u63d0\u4f9b\u7684\u6d2a\u6c34\u4fdd\u9669\u5408\u540c\u6709\u4e25\u683c\u7684\u8d54\u4ed8\u9650\u989d\uff0c\u5bfc\u81f4\u90e8\u5206\u5bb6\u5ead\u5bf9\u6d2a\u6c34\u98ce\u9669\u7f3a\u4e4f\u5145\u5206\u4fdd\u969c\u3002\u672c\u6587\u5229\u7528\u8fd9\u4e9b\u4e25\u683c\u7684\u8d54\u4ed8\u9650\u989d\u4ee5\u53ca\u6d2a\u6c34\u5730\u56fe\u66f4\u65b0\u7684\u5206\u9636\u6bb5\u7279\u5f81\uff0c\u53d1\u73b0\u62b5\u62bc\u8d37\u6b3e\u673a\u6784\u901a\u8fc7\u5728\u8d37\u6b3e\u521d\u59cb\u9636\u6bb5\u8981\u6c42\u66f4\u4f4e\u7684\u8d37\u6b3e\u4ef7\u503c\u6bd4\u6765\u7b5b\u9009\u65e0\u6cd5\u6295\u4fdd\u7684\u6d2a\u6c34\u98ce\u9669\u3002\u8fd9\u79cd\u4fe1\u8d37\u914d\u7ed9\u5bfc\u81f4\u6d2a\u6c34\u533a\u5185\u5916\u7684\u903e\u671f\u7387\u8d8b\u4e8e\u76f8\u7b49\uff0c\u5e76\u4f7f\u6d2a\u6c34\u533a\u5185\u7684\u62b5\u62bc\u8d37\u6b3e\u501f\u6b3e\u4eba\u7ed3\u6784\u5411\u6536\u5165\u66f4\u9ad8\u3001\u4fe1\u7528\u8d28\u91cf\u66f4\u597d\u7684\u4e2a\u4f53\u503e\u659c\u3002\u6211\u5f97\u51fa\u7ed3\u8bba\uff1a\u5f53\u8d37\u6b3e\u673a\u6784\u4fdd\u7559\u672a\u6295\u4fdd\u7684\u6d2a\u6c34\u98ce\u9669\u66b4\u9732\u65f6\uff0c\u4f1a\u51cf\u5c11\u4fe1\u8d37\u4f9b\u7ed9\uff0c\u4ece\u800c\u5bf9\u6d2a\u6c34\u533a\u7684\u5c45\u6c11\u4ea7\u751f\u5206\u914d\u6027\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag016", "journal": "QJE", "title": "The Effects of Gender Integration on Men: Evidence from the U.S. Military", "authors": ["Kyle Greenberg", "Melanie Wasserman", "E Anna Weber"], "author_details": [{"name": "Kyle Greenberg", "affiliations": ["West Point and National Bureau of Economic Research ,"]}, {"name": "Melanie Wasserman", "affiliations": ["University of California, Los Angeles, and National Bureau of Economic Research ,"]}, {"name": "E Anna Weber", "affiliations": ["West Point ,"]}], "abstract": "Abstract Do men negatively respond when women first enter an occupation? We answer this question by studying the end of one of the final explicit occupational barriers to women in the United States: in 2016, the U.S. military opened all positions to women, including historically male-only combat occupations. We exploit the staggered integration of women into combat units to estimate the causal effects of the introduction of female colleagues on men\u2019s job performance, behavior, and perceptions of workplace quality, using monthly administrative personnel records and rich survey responses. We find that integrating women into previously all-male units does not negatively affect men\u2019s performance or behavioral outcomes, including retention, promotions, demotions, separations for misconduct, criminal investigations, and medical conditions. Most of our results are precise enough to rule out small detrimental effects. However, there is a wedge between men\u2019s perceptions and performance. The integration of women causes a negative shift in male soldiers\u2019 perceptions of workplace quality. The decline is driven by units integrated with female officers, likely arising from female officers increasing men\u2019s awareness of workplace problems or from men\u2019s dissatisfaction from working with women in positions of authority\u2014even though men in such units show some performance gains. If male-dominated workplaces are reluctant to incorporate women due to expectations that men will become less productive, our paper provides evidence to weigh against that notion.", "date": "2026-03-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag016", "title_zh": "\u5973\u6027\u53c2\u4e0e\u5bf9\u7537\u6027\u7684\u5f71\u54cd\uff1a\u6765\u81ea\u7f8e\u56fd\u519b\u961f\u7684\u8bc1\u636e", "abstract_zh": "\u6458\u8981 \u5f53\u5973\u6027\u9996\u6b21\u8fdb\u5165\u67d0\u4e00\u804c\u4e1a\u65f6\uff0c\u7537\u6027\u662f\u5426\u4f1a\u4ea7\u751f\u8d1f\u9762\u53cd\u5e94\uff1f\u6211\u4eec\u901a\u8fc7\u7814\u7a76\u7f8e\u56fd\u519b\u961f\u6d88\u9664\u5bf9\u5973\u6027\u804c\u4e1a\u9650\u5236\u7684\u6700\u540e\u4e00\u6b65\u6765\u56de\u7b54\u8fd9\u4e00\u95ee\u9898\uff1a2016\u5e74\uff0c\u7f8e\u56fd\u519b\u961f\u5f00\u653e\u4e86\u6240\u6709\u804c\u4f4d\u7ed9\u5973\u6027\uff0c\u5305\u62ec\u5386\u53f2\u4e0a\u4ec5\u9650\u7537\u6027\u62c5\u4efb\u7684\u6218\u6597\u5c97\u4f4d\u3002\u6211\u4eec\u5229\u7528\u5973\u6027\u9010\u6b65\u8fdb\u5165\u6218\u6597\u5355\u4f4d\u8fd9\u4e00\u81ea\u7136\u5b9e\u9a8c\uff0c\u5229\u7528\u6bcf\u6708\u7684\u884c\u653f\u4eba\u4e8b\u8bb0\u5f55\u548c\u4e30\u5bcc\u7684\u8c03\u67e5\u6570\u636e\uff0c\u4f30\u8ba1\u5973\u6027\u540c\u4e8b\u8fdb\u5165\u5bf9\u7537\u6027\u5728\u5de5\u4f5c\u8868\u73b0\u3001\u884c\u4e3a\u4ee5\u53ca\u5bf9\u5de5\u4f5c\u73af\u5883\u611f\u77e5\u65b9\u9762\u7684\u5f71\u54cd\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5c06\u5973\u6027\u7eb3\u5165\u6b64\u524d\u4ec5\u9650\u7537\u6027\u7684\u5355\u4f4d\uff0c\u5e76\u672a\u5bf9\u7537\u6027\u7684\u7ee9\u6548\u6216\u884c\u4e3a\u7ed3\u679c\u4ea7\u751f\u8d1f\u9762\u5f71\u54cd\uff0c\u5305\u62ec\u7559\u4efb\u3001\u664b\u5347\u3001\u964d\u804c\u3001\u56e0\u8fdd\u7eaa\u800c\u79bb\u804c\u3001\u5211\u4e8b\u8c03\u67e5\u4ee5\u53ca\u533b\u7597\u72b6\u51b5\u3002\u6211\u4eec\u7684\u5927\u90e8\u5206\u7ed3\u679c\u8db3\u591f\u7cbe\u786e\uff0c\u53ef\u4ee5\u6392\u9664\u5fae\u5c0f\u7684\u8d1f\u9762\u6548\u5e94\u3002\u7136\u800c\uff0c\u7537\u6027\u8868\u73b0\u4e0e\u611f\u77e5\u4e4b\u95f4\u5b58\u5728\u5dee\u8ddd\u3002\u5973\u6027\u7684\u52a0\u5165\u5bfc\u81f4\u7537\u6027\u58eb\u5175\u5bf9\u5de5\u4f5c\u73af\u5883\u8d28\u91cf\u7684\u611f\u77e5\u51fa\u73b0\u8d1f\u5411\u53d8\u5316\uff0c\u8fd9\u4e00\u53d8\u5316\u4e3b\u8981\u51fa\u73b0\u5728\u5973\u6027\u519b\u5b98\u53c2\u4e0e\u7684\u5355\u4f4d\u4e2d\uff0c\u53ef\u80fd\u6e90\u4e8e\u5973\u6027\u519b\u5b98\u63d0\u9ad8\u4e86\u7537\u6027\u5bf9\u5de5\u4f5c\u95ee\u9898\u7684\u610f\u8bc6\uff0c\u6216\u6e90\u4e8e\u7537\u6027\u5bf9\u4e0e\u5973\u6027\u5728\u6743\u5a01\u5c97\u4f4d\u4e0a\u5171\u4e8b\u7684\u4e0d\u6ee1\u2014\u2014\u5c3d\u7ba1\u8fd9\u4e9b\u5355\u4f4d\u4e2d\u7684\u7537\u6027\u5728\u7ee9\u6548\u4e0a\u6709\u6240\u63d0\u5347\u3002\u5982\u679c\u7537\u6027\u4e3b\u5bfc\u7684\u5de5\u4f5c\u573a\u6240\u56e0\u62c5\u5fc3\u7537\u6027\u751f\u4ea7\u529b\u4e0b\u964d\u800c\u62d2\u7edd\u5f15\u5165\u5973\u6027\uff0c\u672c\u7814\u7a76\u63d0\u4f9b\u4e86\u53cd\u9a73\u8fd9\u4e00\u89c2\u70b9\u7684\u8bc1\u636e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag008", "journal": "RFS", "title": "Incentivizing Effort and Informing Investment: The Dual Role of Stock Prices", "authors": ["Snehal Banerjee", "Jesse Davis", "Naveen Gondhi"], "author_details": [{"name": "Snehal Banerjee", "affiliations": ["University of Michigan ,"]}, {"name": "Jesse Davis", "affiliations": ["University of North Carolina , Chapel Hill,"]}, {"name": "Naveen Gondhi", "affiliations": ["INSEAD ,"]}], "abstract": "Abstract Stock prices aggregate investor information about investment opportunities and reflect managerial performance. These dual roles may be in tension: when prices are more informative about investment opportunities, they may be less effective at incentivizing managerial effort. This tradeoff has novel consequences. Lower information costs can lead to both more efficient investment but lower firm value. The principal may strictly prefer to delegate investment to a manager who has no informational advantage and makes ex-post inefficient choices. Investment in diversifying and (ex-ante) negative NPV projects mitigate agency problems. Finally, standard measures of price efficiency provide an incomplete picture of firm value.", "date": "2026-03-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag008", "title_zh": "\u6fc0\u52b1\u52aa\u529b\u4e0e\u4f20\u9012\u6295\u8d44\u4fe1\u606f\uff1a\u80a1\u4ef7\u7684\u53cc\u91cd\u4f5c\u7528", "abstract_zh": "\u80a1\u4ef7\u6c47\u96c6\u4e86\u6295\u8d44\u8005\u5173\u4e8e\u6295\u8d44\u673a\u4f1a\u7684\u4fe1\u606f\uff0c\u5e76\u53cd\u6620\u4e86\u7ba1\u7406\u5c42\u7684\u8868\u73b0\u3002\u8fd9\u4e24\u79cd\u4f5c\u7528\u53ef\u80fd\u5b58\u5728\u77db\u76fe\uff1a\u5f53\u80a1\u4ef7\u66f4\u51c6\u786e\u5730\u53cd\u6620\u6295\u8d44\u673a\u4f1a\u4fe1\u606f\u65f6\uff0c\u5b83\u4eec\u53ef\u80fd\u5728\u6fc0\u52b1\u7ba1\u7406\u5c42\u52aa\u529b\u65b9\u9762\u6548\u679c\u51cf\u5f31\u3002\u8fd9\u79cd\u6743\u8861\u5177\u6709\u65b0\u7684\u540e\u679c\u3002\u4fe1\u606f\u6210\u672c\u964d\u4f4e\u53ef\u80fd\u5bfc\u81f4\u6295\u8d44\u66f4\u6709\u6548\u7387\uff0c\u4f46\u4f01\u4e1a\u4ef7\u503c\u53cd\u800c\u4e0b\u964d\u3002\u59d4\u6258\u4eba\u53ef\u80fd\u4e25\u683c\u504f\u597d\u5c06\u6295\u8d44\u59d4\u6258\u7ed9\u4e00\u4e2a\u6ca1\u6709\u4fe1\u606f\u4f18\u52bf\u3001\u4e14\u4e8b\u540e\u505a\u51fa\u4f4e\u6548\u51b3\u7b56\u7684\u7ba1\u7406\u8005\u3002\u5bf9\u591a\u6837\u5316\u4ee5\u53ca\u4e8b\u524d\u51c0\u73b0\u503c\u4e3a\u8d1f\u7684\u6295\u8d44\u8fdb\u884c\u6295\u8d44\uff0c\u53ef\u4ee5\u7f13\u89e3\u4ee3\u7406\u95ee\u9898\u3002\u6700\u540e\uff0c\u6807\u51c6\u7684\u4ef7\u683c\u6548\u7387\u8861\u91cf\u6307\u6807\u5bf9\u4f01\u4e1a\u4ef7\u503c\u7684\u523b\u753b\u662f\u4e0d\u5b8c\u6574\u7684\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag027", "journal": "RFS", "title": "The Covenant-Defeasance Option in Corporate Bonds", "authors": ["Carsten Bienz", "Zsuzsanna Fluck", "Karin S Thorburn"], "author_details": [{"name": "Carsten Bienz", "affiliations": ["NHH Norwegian School of Economics ,"]}, {"name": "Zsuzsanna Fluck", "affiliations": ["Michigan State University ,"]}, {"name": "Karin S Thorburn", "affiliations": ["NHH Norwegian School of Economics, CEPR, and ECGI , Norway, , and"]}], "abstract": "Abstract Corporate bonds include restrictive covenants that may prevent firms from pursuing valuable growth opportunities ex post and are virtually impossible to renegotiate. We study a common but little-known contractual provision\u2014the defeasance option\u2014which allows issuers to immediately remove all covenants without retiring the bond. Our theoretical model predicts, and our empirical analysis confirms, that defeasance inclusion is more likely when covenants are numerous and issuers face financial constraints, uncertainty, and growth opportunities. We also show that investors require lower yields when defeasance is included in noncallable bonds, and higher yields in fixed-price callable bonds, where it raises call risk.", "date": "2026-03-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag027", "title_zh": "\u4f01\u4e1a\u503a\u5238\u4e2d\u7684\u8c41\u514d\u6761\u6b3e\u9009\u62e9\u6743", "abstract_zh": "\u4f01\u4e1a\u503a\u5238\u5305\u542b\u9650\u5236\u6027\u6761\u6b3e\uff0c\u8fd9\u4e9b\u6761\u6b3e\u53ef\u80fd\u5728\u4e8b\u540e\u963b\u6b62\u4f01\u4e1a\u8ffd\u6c42\u6709\u4ef7\u503c\u7684\u589e\u957f\u673a\u4f1a\uff0c\u4e14\u51e0\u4e4e\u65e0\u6cd5\u91cd\u65b0\u8c08\u5224\u3002\u6211\u4eec\u7814\u7a76\u4e00\u79cd\u5e38\u89c1\u4f46\u9c9c\u4e3a\u4eba\u77e5\u7684\u5408\u540c\u6761\u6b3e\u2014\u2014\u8c41\u514d\u6761\u6b3e\u9009\u62e9\u6743\uff0c\u8be5\u6761\u6b3e\u5141\u8bb8\u53d1\u884c\u4eba\u7acb\u5373\u53d6\u6d88\u6240\u6709\u9650\u5236\u6027\u6761\u6b3e\uff0c\u800c\u65e0\u9700\u8d4e\u56de\u503a\u5238\u3002\u6211\u4eec\u7684\u7406\u8bba\u6a21\u578b\u9884\u6d4b\uff0c\u5e76\u901a\u8fc7\u5b9e\u8bc1\u5206\u6790\u8bc1\u5b9e\uff0c\u5f53\u9650\u5236\u6027\u6761\u6b3e\u8f83\u591a\u4e14\u53d1\u884c\u4eba\u9762\u4e34\u8d22\u52a1\u7ea6\u675f\u3001\u4e0d\u786e\u5b9a\u6027\u4ee5\u53ca\u589e\u957f\u673a\u4f1a\u65f6\uff0c\u5305\u542b\u8c41\u514d\u6761\u6b3e\u7684\u53ef\u80fd\u6027\u66f4\u9ad8\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0c\u5f53\u8c41\u514d\u6761\u6b3e\u5305\u542b\u5728\u975e\u53ef\u8d4e\u56de\u503a\u5238\u4e2d\u65f6\uff0c\u6295\u8d44\u8005\u8981\u6c42\u7684\u6536\u76ca\u7387\u8f83\u4f4e\uff1b\u800c\u5728\u56fa\u5b9a\u4ef7\u683c\u53ef\u8d4e\u56de\u503a\u5238\u4e2d\uff0c\u8c41\u514d\u6761\u6b3e\u4f1a\u589e\u52a0\u8d4e\u56de\u98ce\u9669\uff0c\u5bfc\u81f4\u6295\u8d44\u8005\u8981\u6c42\u66f4\u9ad8\u7684\u6536\u76ca\u7387\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag014", "journal": "RFS", "title": "The Broader Role of Venture Capital Due Diligence", "authors": ["Juanita Gonz\u00e1lez-Uribe", "Robyn Klingler-Vidra", "Su Wang", "Xiang Yin"], "author_details": [{"name": "Juanita Gonz\u00e1lez-Uribe", "affiliations": ["London School of Economics and Political Science (LSE) ,"]}, {"name": "Robyn Klingler-Vidra", "affiliations": ["King\u2019s College London ,"]}, {"name": "Su Wang", "affiliations": ["Shanghai Tech University ,"]}, {"name": "Xiang Yin", "affiliations": ["Tsinghua University ,"]}], "abstract": "Abstract Analyzing approximately 2,000 applicants to a U.K. seed fund, this study examines how venture capital (VC) due diligence affects startup outcomes independent of funding decisions. Leveraging random reviewer assignment, we find that due diligence increases 2-year growth but lowers continuation rates among nonfunded applicants, reflecting a dynamic of accelerated scaling or exit. Evidence points to a learning mechanism: due diligence exposes founders to advanced website technologies, prompting capability building in digital skills. Firms selected for due diligence adopt these technologies, even before raising external capital. The findings highlight VC due diligence as a formative process influencing startups beyond the funded few.", "date": "2026-03-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag014", "title_zh": "\u98ce\u9669\u6295\u8d44\u5c3d\u804c\u8c03\u67e5\u7684\u66f4\u5e7f\u6cdb\u4f5c\u7528", "abstract_zh": "\u6458\u8981 \u672c\u7814\u7a76\u57fa\u4e8e\u5bf9\u7ea62000\u5bb6\u7533\u8bf7\u82f1\u56fd\u79cd\u5b50\u57fa\u91d1\u7684\u521d\u521b\u4f01\u4e1a\u7684\u5206\u6790\uff0c\u63a2\u8ba8\u4e86\u98ce\u9669\u6295\u8d44\uff08VC\uff09\u5c3d\u804c\u8c03\u67e5\u5982\u4f55\u72ec\u7acb\u4e8e\u878d\u8d44\u51b3\u7b56\u5f71\u54cd\u521d\u521b\u4f01\u4e1a\u7684\u53d1\u5c55\u7ed3\u679c\u3002\u5229\u7528\u968f\u673a\u5206\u914d\u8bc4\u5ba1\u5458\u7684\u65b9\u6cd5\uff0c\u7814\u7a76\u53d1\u73b0\u5c3d\u804c\u8c03\u67e5\u63d0\u9ad8\u4e86\u4f01\u4e1a\u4e24\u5e74\u5185\u7684\u589e\u957f\uff0c\u4f46\u964d\u4f4e\u4e86\u672a\u83b7\u878d\u8d44\u7533\u8bf7\u4f01\u4e1a\u7684\u6301\u7eed\u8fd0\u8425\u7387\uff0c\u53cd\u6620\u51fa\u4f01\u4e1a\u52a0\u901f\u6269\u5f20\u6216\u9000\u51fa\u7684\u52a8\u6001\u7279\u5f81\u3002\u8bc1\u636e\u8868\u660e\u5b58\u5728\u4e00\u79cd\u5b66\u4e60\u673a\u5236\uff1a\u5c3d\u804c\u8c03\u67e5\u4f7f\u521b\u59cb\u4eba\u63a5\u89e6\u5230\u5148\u8fdb\u7684\u7f51\u7ad9\u6280\u672f\uff0c\u4ece\u800c\u63a8\u52a8\u5176\u5728\u6570\u5b57\u6280\u80fd\u65b9\u9762\u7684\u80fd\u529b\u5efa\u8bbe\u3002\u88ab\u9009\u4e2d\u8fdb\u884c\u5c3d\u804c\u8c03\u67e5\u7684\u4f01\u4e1a\u5373\u4f7f\u5728\u672a\u7b79\u96c6\u5916\u90e8\u8d44\u91d1\u4e4b\u524d\uff0c\u4e5f\u91c7\u7eb3\u4e86\u8fd9\u4e9b\u6280\u672f\u3002\u7814\u7a76\u7ed3\u679c\u51f8\u663e\u4e86\u98ce\u9669\u6295\u8d44\u5c3d\u804c\u8c03\u67e5\u4f5c\u4e3a\u4e00\u79cd\u5f62\u6210\u6027\u8fc7\u7a0b\uff0c\u5bf9\u521d\u521b\u4f01\u4e1a\u7684\u5f71\u54cd\u4e0d\u4ec5\u9650\u4e8e\u83b7\u5f97\u878d\u8d44\u7684\u5c11\u6570\u4f01\u4e1a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag015", "journal": "RFS", "title": "How Financial Markets Create Superstars", "authors": ["Spyros Terovitis", "Vladimir Vladimirov"], "author_details": [{"name": "Spyros Terovitis", "affiliations": ["University of Amsterdam ,"]}, {"name": "Vladimir Vladimirov", "affiliations": ["University of Amsterdam, the Netherlands, and CEPR"]}], "abstract": "Abstract By aggregating information into stock prices, financial markets help guide the allocation of resources. We show that speculators without information about firms\u2019 fundamentals can exploit this role of prices and profit from inflating firm valuations. Uninformed speculation is profitable because high valuations attract employees, business partners, and investors, creating value at targeted firms at the cost of diverting resources from better firms. Both large and small speculators, without pre-existing stock positions, can profit from uninformed speculation, particularly when targeting firms with moderate Q, operating in \u201cnormal\u201d (neither hot nor cold) markets, and using performance pay or equity to attract stakeholders.", "date": "2026-03-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag015", "title_zh": "\u91d1\u878d\u5e02\u573a\u5982\u4f55\u50ac\u751f\u8d85\u7ea7\u660e\u661f", "abstract_zh": "\u6458\u8981 \u901a\u8fc7\u5c06\u4fe1\u606f\u805a\u5408\u5230\u80a1\u4ef7\u4e2d\uff0c\u91d1\u878d\u5e02\u573a\u6709\u52a9\u4e8e\u5f15\u5bfc\u8d44\u6e90\u7684\u914d\u7f6e\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5373\u4f7f\u6ca1\u6709\u5173\u4e8e\u4f01\u4e1a\u57fa\u672c\u9762\u4fe1\u606f\u7684\u6295\u673a\u8005\uff0c\u4e5f\u53ef\u4ee5\u5229\u7528\u80a1\u4ef7\u8fd9\u4e00\u4fe1\u606f\u805a\u5408\u673a\u5236\uff0c\u901a\u8fc7\u62ac\u9ad8\u4f01\u4e1a\u4f30\u503c\u6765\u83b7\u5229\u3002\u65e0\u4fe1\u606f\u7684\u6295\u673a\u4e4b\u6240\u4ee5\u6709\u5229\u53ef\u56fe\uff0c\u662f\u56e0\u4e3a\u9ad8\u4f30\u503c\u4f1a\u5438\u5f15\u5458\u5de5\u3001\u5546\u4e1a\u4f19\u4f34\u548c\u6295\u8d44\u8005\uff0c\u4ece\u800c\u5728\u76ee\u6807\u4f01\u4e1a\u4e2d\u521b\u9020\u4ef7\u503c\uff0c\u800c\u8fd9\u79cd\u4ef7\u503c\u521b\u9020\u662f\u4ee5\u727a\u7272\u5bf9\u66f4\u597d\u4f01\u4e1a\u8d44\u6e90\u914d\u7f6e\u4e3a\u4ee3\u4ef7\u7684\u3002\u65e0\u8bba\u662f\u5927\u578b\u8fd8\u662f\u5c0f\u578b\u6295\u673a\u8005\uff0c\u53ea\u8981\u6ca1\u6709\u9884\u5148\u6301\u6709\u7684\u80a1\u7968\u5934\u5bf8\uff0c\u90fd\u53ef\u4ee5\u4ece\u65e0\u4fe1\u606f\u6295\u673a\u4e2d\u83b7\u5229\uff0c\u5c24\u5176\u662f\u5728\u9488\u5bf9\u4f30\u503c\u9002\u4e2d\uff08Q\u503c\u4e2d\u7b49\uff09\u3001\u5904\u4e8e\u2018\u6b63\u5e38\u2019\uff08\u65e2\u975e\u8fc7\u70ed\u4e5f\u975e\u8fc7\u51b7\uff09\u5e02\u573a\u73af\u5883\u4e2d\u7684\u4f01\u4e1a\uff0c\u5e76\u901a\u8fc7\u7ee9\u6548\u85aa\u916c\u6216\u80a1\u6743\u6fc0\u52b1\u5438\u5f15\u5229\u76ca\u76f8\u5173\u8005\u65f6\uff0c\u8fd9\u79cd\u83b7\u5229\u6548\u5e94\u5c24\u4e3a\u660e\u663e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag026", "journal": "RFS", "title": "Excess Commitment in R&D", "authors": ["Marius Guenzel", "Tong Liu"], "author_details": [{"name": "Marius Guenzel", "affiliations": ["The Wharton School, University of Pennsylvania ,"]}, {"name": "Tong Liu", "affiliations": ["MIT Sloan School of Management ,"]}], "abstract": "Abstract We document that firms exhibit \u201cexcess\u201d commitment to R&D projects and examine its consequences for innovation outcomes. Using detailed data on pharmaceutical firms\u2019 clinical trial projects, we find that trial delays, empirically uncorrelated with multiple project-quality measures, substantially reduce firms\u2019 subsequent project-termination propensity. This result remains robust when we use variation in clinical trial site congestion to instrument for unexpected delays. Excess commitment intensifies when CEO compensation has greater stock-price sensitivity and the CEO is responsible for the project\u2019s initiation. Our findings have broader implications: delay-driven commitment reduces new drug project initiations, with further evidence suggesting efficiency losses for firms.", "date": "2026-03-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag026", "title_zh": "\u7814\u53d1\u4e2d\u7684\u8fc7\u5ea6\u627f\u8bfa", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\u4f01\u4e1a\u5bf9\u7814\u53d1\u9879\u76ee\u8868\u73b0\u51fa\u201c\u8fc7\u5ea6\u201d\u627f\u8bfa\uff0c\u5e76\u8003\u5bdf\u4e86\u8fd9\u79cd\u627f\u8bfa\u5bf9\u521b\u65b0\u7ed3\u679c\u7684\u5f71\u54cd\u3002\u5229\u7528\u5236\u836f\u4f01\u4e1a\u4e34\u5e8a\u8bd5\u9a8c\u9879\u76ee\u7684\u8be6\u7ec6\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u8bd5\u9a8c\u5ef6\u8fdf\u4e0e\u591a\u4e2a\u9879\u76ee\u8d28\u91cf\u6307\u6807\u5728\u7ecf\u9a8c\u4e0a\u65e0\u5173\uff0c\u5374\u663e\u8457\u964d\u4f4e\u4e86\u4f01\u4e1a\u540e\u7eed\u7ec8\u6b62\u9879\u76ee\u7684\u503e\u5411\u3002\u5f53\u4f7f\u7528\u4e34\u5e8a\u8bd5\u9a8c\u7ad9\u70b9\u62e5\u5835\u7684\u53d8\u5316\u4f5c\u4e3a\u610f\u5916\u5ef6\u8fdf\u7684\u5de5\u5177\u53d8\u91cf\u65f6\uff0c\u8fd9\u4e00\u7ed3\u679c\u4f9d\u7136\u7a33\u5065\u3002\u5f53CEO\u7684\u85aa\u916c\u66f4\u654f\u611f\u4e8e\u80a1\u4ef7\u53d8\u5316\uff0c\u4e14CEO\u8d1f\u8d23\u9879\u76ee\u7684\u542f\u52a8\u65f6\uff0c\u8fc7\u5ea6\u627f\u8bfa\u73b0\u8c61\u4f1a\u52a0\u5267\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u5177\u6709\u66f4\u5e7f\u6cdb\u7684\u542b\u4e49\uff1a\u7531\u5ef6\u8fdf\u9a71\u52a8\u7684\u627f\u8bfa\u5bfc\u81f4\u65b0\u836f\u9879\u76ee\u542f\u52a8\u51cf\u5c11\uff0c\u8fdb\u4e00\u6b65\u7684\u8bc1\u636e\u8868\u660e\u4f01\u4e1a\u5b58\u5728\u6548\u7387\u635f\u5931\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102786", "journal": "JFQA", "title": "M&As Efficiency Gains: Evidence from Branch-Level Data", "authors": ["Lucas Argentieri Mariani", "Bernardo Ricca"], "author_details": [{"name": "Lucas Argentieri Mariani", "affiliations": ["Bocconi University, BAFFI and IGIER"]}, {"name": "Bernardo Ricca", "affiliations": ["Insper"]}], "abstract": "Abstract We examine how banks reallocate employees following mergers and acquisitions (M&As) and the resulting effects on productivity. Using matched employee\u2013branch data combined with branch-level financial information, we show that M&As expand internal labor markets and trigger substantial worker redeployment. Newly consolidated banks reassign high-ability loan officers to acquirer branches, increasing productivity. Target branches also experience productivity improvements, primarily driven by restructuring and cost reductions. These effects are strongest in municipalities where the combined pre-merger internal labor markets of the target and acquirer were larger, highlighting the central role of internal labor markets in generating efficiency gains from consolidation.", "date": "2026-03-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102786", "title_zh": "\u5e76\u8d2d\u540e\u7684\u6548\u7387\u63d0\u5347\uff1a\u6765\u81ea\u5206\u652f\u673a\u6784\u5c42\u9762\u7684\u6570\u636e\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u94f6\u884c\u5728\u5e76\u8d2d\u540e\u5982\u4f55\u91cd\u65b0\u5206\u914d\u5458\u5de5\u4ee5\u53ca\u7531\u6b64\u5e26\u6765\u7684\u751f\u4ea7\u7387\u53d8\u5316\u3002\u5229\u7528\u5339\u914d\u7684\u5458\u5de5-\u5206\u652f\u673a\u6784\u6570\u636e\u7ed3\u5408\u5206\u652f\u673a\u6784\u7684\u8d22\u52a1\u4fe1\u606f\uff0c\u6211\u4eec\u53d1\u73b0\u5e76\u8d2d\u4f1a\u6269\u5927\u5185\u90e8\u52b3\u52a8\u529b\u5e02\u573a\uff0c\u5e76\u5f15\u53d1\u5927\u89c4\u6a21\u7684\u5458\u5de5\u91cd\u65b0\u914d\u7f6e\u3002\u65b0\u5408\u5e76\u7684\u94f6\u884c\u5c06\u9ad8\u80fd\u529b\u7684\u8d37\u6b3e\u4e13\u5458\u8c03\u6d3e\u5230\u6536\u8d2d\u65b9\u5206\u652f\u673a\u6784\uff0c\u4ece\u800c\u63d0\u5347\u751f\u4ea7\u7387\u3002\u76ee\u6807\u5206\u652f\u673a\u6784\u4e5f\u5b9e\u73b0\u4e86\u751f\u4ea7\u7387\u7684\u63d0\u5347\uff0c\u4e3b\u8981\u5f97\u76ca\u4e8e\u91cd\u7ec4\u548c\u6210\u672c\u524a\u51cf\u3002\u8fd9\u4e9b\u6548\u5e94\u5728\u76ee\u6807\u548c\u6536\u8d2d\u65b9\u5e76\u8d2d\u524d\u5185\u90e8\u52b3\u52a8\u529b\u5e02\u573a\u8f83\u5927\u7684\u57ce\u5e02\u4e2d\u5c24\u4e3a\u663e\u8457\uff0c\u51f8\u663e\u4e86\u5185\u90e8\u52b3\u52a8\u529b\u5e02\u573a\u5728\u5e76\u8d2d\u5e26\u6765\u7684\u6548\u7387\u63d0\u5347\u4e2d\u6240\u8d77\u7684\u6838\u5fc3\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1093/rfs/hhag007", "journal": "RFS", "title": "Debt Maturity Management", "authors": ["Yunzhi Hu", "Felipe Varas", "Chao Ying"], "author_details": [{"name": "Yunzhi Hu", "affiliations": ["Kenan-Flagler Business School, University of North Carolina at Chapel Hill, Chapel Hill, North Carolina, USA The School of Business and Management is the business school of the Hong Kong University of Science and Technology, Hong Kong"]}, {"name": "Felipe Varas", "affiliations": ["Naveen Jindal School of Management, University of Texas at Dallas"]}, {"name": "Chao Ying", "affiliations": ["CUHK Business School"]}], "abstract": "Abstract This paper studies how a borrower issues long- and short-term debt in response to shocks to the fundamental value. Short-term debt protects creditors from future dilution and incentivizes the borrower to reduce leverage after small negative shocks. Long-term debt postpones default and allows the borrower time to recover after large negative shocks. When borrowers are in distress, they rely on short-term debt; however, they issue both types of debt during more normal periods. Our model generates novel implications for the dynamic adjustment of debt maturities.", "date": "2026-03-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag007", "title_zh": "\u503a\u52a1\u671f\u9650\u7ba1\u7406", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u501f\u6b3e\u4eba\u5982\u4f55\u5728\u57fa\u672c\u9762\u4ef7\u503c\u53d7\u5230\u51b2\u51fb\u65f6\u53d1\u884c\u957f\u671f\u548c\u77ed\u671f\u503a\u52a1\u3002\u77ed\u671f\u503a\u52a1\u4fdd\u62a4\u503a\u6743\u4eba\u514d\u53d7\u672a\u6765\u7a00\u91ca\uff0c\u5e76\u6fc0\u52b1\u501f\u6b3e\u4eba\u5728\u906d\u53d7\u5c0f\u5e45\u8d1f\u9762\u51b2\u51fb\u540e\u964d\u4f4e\u6760\u6746\u3002\u957f\u671f\u503a\u52a1\u63a8\u8fdf\u8fdd\u7ea6\uff0c\u4e3a\u501f\u6b3e\u4eba\u63d0\u4f9b\u5728\u906d\u53d7\u91cd\u5927\u8d1f\u9762\u51b2\u51fb\u540e\u6062\u590d\u7684\u65f6\u95f4\u3002\u5f53\u501f\u6b3e\u4eba\u9677\u5165\u56f0\u5883\u65f6\uff0c\u4ed6\u4eec\u4f9d\u8d56\u77ed\u671f\u503a\u52a1\uff1b\u7136\u800c\uff0c\u5728\u6b63\u5e38\u65f6\u671f\uff0c\u4ed6\u4eec\u540c\u65f6\u53d1\u884c\u4e24\u79cd\u7c7b\u578b\u7684\u503a\u52a1\u3002\u6211\u4eec\u7684\u6a21\u578b\u4e3a\u503a\u52a1\u671f\u9650\u7684\u52a8\u6001\u8c03\u6574\u4ea7\u751f\u4e86\u65b0\u7684\u542f\u793a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag016", "journal": "RFS", "title": "Too Many Managers: The Strategic Use of Titles to Avoid Overtime Payments", "authors": ["Lauren H Cohen", "Umit G Gurun", "N Bugra Ozel"], "author_details": [{"name": "Lauren H Cohen", "affiliations": ["Harvard Business School, the United States, and NBER"]}, {"name": "Umit G Gurun", "affiliations": ["University of Texas at Dallas ,"]}, {"name": "N Bugra Ozel", "affiliations": ["University of Texas at Dallas ,"]}], "abstract": "Abstract We find widespread evidence that firms avoid overtime payments by strategically assigning \u201cmanagerial\u201d titles. Exploiting the exemption threshold under the Fair Labor Standards Act (FLSA), we find managerial titles increase almost fivefold just above the overtime pay cutoff, including suspect listings, such as \u201cDirector of First Impressions\u201d for a role equivalent to \u201cFront-Desk Clerk.\u201d Avoidance is higher when firms have more bargaining power and are financially constrained. It is also more common in occupations with volatile demand and unpredictable worker scheduling. Patterns align with litigation and Department of Labor enforcement. Firms avoid roughly 13.5% in compensation costs, hiring strategic \u201cmanagers.\u201d", "date": "2026-03-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag016", "title_zh": "\u7ecf\u7406\u5934\u8854\u8fc7\u591a\uff1a\u901a\u8fc7\u6218\u7565\u4f7f\u7528\u5934\u8854\u6765\u89c4\u907f\u52a0\u73ed\u8d39", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\u4f01\u4e1a\u666e\u904d\u901a\u8fc7\u6218\u7565\u6027\u5730\u8d4b\u4e88\u2018\u7ba1\u7406\u5c42\u2019\u5934\u8854\u6765\u89c4\u907f\u52a0\u73ed\u8d39\u3002\u5229\u7528\u300a\u516c\u5e73\u52b3\u52a8\u6807\u51c6\u6cd5\u300b\uff08FLSA\uff09\u7684\u8c41\u514d\u95e8\u69db\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u52a0\u73ed\u8d39\u652f\u4ed8\u95e8\u69db\u4e4b\u4e0a\uff0c\u7ba1\u7406\u5c42\u5934\u8854\u7684\u4f7f\u7528\u51e0\u4e4e\u589e\u52a0\u4e86\u4e94\u500d\uff0c\u5305\u62ec\u8bf8\u5982\u2018\u7b2c\u4e00\u5370\u8c61\u603b\u76d1\u2019\u8fd9\u6837\u7684\u53ef\u7591\u804c\u4f4d\uff0c\u5176\u5b9e\u9645\u5de5\u4f5c\u5185\u5bb9\u76f8\u5f53\u4e8e\u2018\u524d\u53f0\u63a5\u5f85\u5458\u2019\u3002\u5f53\u4f01\u4e1a\u62e5\u6709\u66f4\u5f3a\u7684\u8c08\u5224\u80fd\u529b\u6216\u9762\u4e34\u8d22\u52a1\u7ea6\u675f\u65f6\uff0c\u89c4\u907f\u884c\u4e3a\u66f4\u4e3a\u663e\u8457\uff1b\u5728\u9700\u6c42\u6ce2\u52a8\u5927\u4e14\u5de5\u4eba\u6392\u73ed\u4e0d\u53ef\u9884\u6d4b\u7684\u804c\u4e1a\u4e2d\uff0c\u8fd9\u79cd\u884c\u4e3a\u4e5f\u66f4\u4e3a\u666e\u904d\u3002\u8fd9\u4e9b\u6a21\u5f0f\u4e0e\u8bc9\u8bbc\u6848\u4ef6\u53ca\u52b3\u5de5\u90e8\u7684\u6267\u6cd5\u884c\u52a8\u76f8\u543b\u5408\u3002\u4f01\u4e1a\u901a\u8fc7\u6218\u7565\u6027\u62db\u8058\u2018\u7ecf\u7406\u2019\uff0c\u5e73\u5747\u89c4\u907f\u4e86\u7ea613.5%\u7684\u85aa\u916c\u652f\u51fa\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag012", "journal": "RFS", "title": "Risk Managers in Banks", "authors": ["Matthias Efing", "Patrick Kampk\u00f6tter", "Vincent Maurin"], "author_details": [{"name": "Matthias Efing", "affiliations": ["HEC Paris ,"]}, {"name": "Patrick Kampk\u00f6tter", "affiliations": ["University of T\u00fcbingen ,"]}, {"name": "Vincent Maurin", "affiliations": ["HEC Paris ,"]}], "abstract": "Abstract Some bank regulators require that performance bonuses for risk managers (RMs) and for employees in front offices (FOs) be linked to distinct performance metrics, as correlated pay incentives could lead RMs to rubber-stamp risky investments. We theoretically show that a positive correlation between FOs and RMs is optimal for banks, but can be socially excessive in leveraged institutions. Using data from German bank employees, we show empirically that incentive pay is indeed positively correlated between RMs and FOs. Consistent with our predictions, bonus correlations are higher in banks with higher leverage and weaker performance during the Great Financial Crisis.", "date": "2026-03-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag012", "title_zh": "\u94f6\u884c\u4e2d\u7684\u98ce\u9669\u7ba1\u7406\u4eba\u5458", "abstract_zh": "\u6458\u8981 \u4e00\u4e9b\u94f6\u884c\u76d1\u7ba1\u673a\u6784\u8981\u6c42\u5c06\u98ce\u9669\u7ba1\u7406\u4eba\u5458\uff08RM\uff09\u548c\u524d\u53f0\u5458\u5de5\uff08FO\uff09\u7684\u7ee9\u6548\u5956\u91d1\u4e0e\u4e0d\u540c\u7684\u7ee9\u6548\u6307\u6807\u6302\u94a9\uff0c\u56e0\u4e3a\u76f8\u5173\u6027\u85aa\u916c\u6fc0\u52b1\u53ef\u80fd\u5bfc\u81f4\u98ce\u9669\u7ba1\u7406\u4eba\u5458\u5bf9\u9ad8\u98ce\u9669\u6295\u8d44\u91c7\u53d6\u201c\u5f62\u5f0f\u6279\u51c6\u201d\u7684\u6001\u5ea6\u3002\u6211\u4eec\u4ece\u7406\u8bba\u4e0a\u8bc1\u660e\uff0c\u524d\u53f0\u4e0e\u98ce\u9669\u7ba1\u7406\u4eba\u5458\u4e4b\u95f4\u7684\u6b63\u76f8\u5173\u6027\u5bf9\u94f6\u884c\u800c\u8a00\u662f\u6700\u4f73\u7684\uff0c\u4f46\u5728\u6760\u6746\u7387\u8f83\u9ad8\u7684\u673a\u6784\u4e2d\u53ef\u80fd\u5bf9\u793e\u4f1a\u9020\u6210\u8fc7\u5ea6\u5f71\u54cd\u3002\u5229\u7528\u5fb7\u56fd\u94f6\u884c\u5458\u5de5\u7684\u6570\u636e\uff0c\u6211\u4eec\u5b9e\u8bc1\u53d1\u73b0\u98ce\u9669\u7ba1\u7406\u4eba\u5458\u4e0e\u524d\u53f0\u5458\u5de5\u7684\u6fc0\u52b1\u85aa\u916c\u786e\u5b9e\u5b58\u5728\u6b63\u76f8\u5173\u6027\u3002\u4e0e\u6211\u4eec\u7684\u9884\u6d4b\u4e00\u81f4\uff0c\u6760\u6746\u7387\u8d8a\u9ad8\u4e14\u57282008\u5e74\u91d1\u878d\u5371\u673a\u671f\u95f4\u8868\u73b0\u8d8a\u5f31\u7684\u94f6\u884c\uff0c\u5176\u5956\u91d1\u76f8\u5173\u6027\u4e5f\u8d8a\u9ad8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1017/s0022109026102774", "journal": "JFQA", "title": "Rewriting CRSP\u2019s History: Impact of Altered Monthly Returns on Asset Pricing", "authors": ["Patrick Schwarz", "Dominik Walter", "Patrick Weiss"], "author_details": [{"name": "Patrick Schwarz", "affiliations": ["University of Li\u00e8ge HEC Li\u00e8ge"]}, {"name": "Dominik Walter", "affiliations": ["University of Konstanz"]}, {"name": "Patrick Weiss", "affiliations": ["Reykjavik University"]}], "abstract": "Abstract In January 2025, CRSP discontinued the existing stock tape used in many published papers. This transition rewrites 9.62% of monthly returns by more than 1 basis point (bp), primarily due to a change in the dividend reinvestment assumption. Analyzing the impact for a comprehensive set of premia in several thousand sorting specifications reveals that, on average, 11.43% of all monthly long-short returns differ by more than 10 bp\u2014especially in early periods, NBER recessions, and return-based sorts. Reassuringly, average premia and their significance remain largely unaffected, suggesting CRSP changes mainly introduce unsystematic variation without altering key asset pricing conclusions.", "date": "2026-03-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102774", "title_zh": "\u91cd\u5199CRSP\u7684\u5386\u53f2\uff1a\u4fee\u6b63\u6708\u5ea6\u6536\u76ca\u7387\u5bf9\u8d44\u4ea7\u5b9a\u4ef7\u7684\u5f71\u54cd", "abstract_zh": "\u6458\u8981 2025\u5e741\u6708\uff0cCRSP\u505c\u6b62\u4f7f\u7528\u6b64\u524d\u8bb8\u591a\u53d1\u8868\u8bba\u6587\u4e2d\u6240\u91c7\u7528\u7684\u80a1\u7968\u6570\u636e\u8bb0\u5f55\u3002\u8fd9\u4e00\u8f6c\u53d8\u4f7f9.62%\u7684\u6708\u5ea6\u6536\u76ca\u7387\u53d1\u751f\u4e86\u8d85\u8fc71\u4e2a\u57fa\u70b9\uff08bp\uff09\u7684\u53d8\u52a8\uff0c\u4e3b\u8981\u539f\u56e0\u662f\u80a1\u606f\u518d\u6295\u8d44\u5047\u8bbe\u7684\u6539\u53d8\u3002\u901a\u8fc7\u5bf9\u6570\u5343\u79cd\u6392\u5e8f\u89c4\u8303\u4e0b\u7684\u4e00\u7cfb\u5217\u98ce\u9669\u6ea2\u4ef7\u8fdb\u884c\u5206\u6790\u53d1\u73b0\uff0c\u5e73\u5747\u800c\u8a00\uff0c11.43%\u7684\u6708\u5ea6\u957f\u77ed\u671f\u6536\u76ca\u7387\u5dee\u5f02\u8d85\u8fc710\u4e2a\u57fa\u70b9\u2014\u2014\u5c24\u5176\u662f\u5728\u65e9\u671f\u65f6\u671f\u3001NBER\u7ecf\u6d4e\u8870\u9000\u671f\u4ee5\u53ca\u57fa\u4e8e\u6536\u76ca\u7684\u6392\u5e8f\u4e2d\u3002\u4ee4\u4eba\u6b23\u6170\u7684\u662f\uff0c\u5404\u7c7b\u98ce\u9669\u6ea2\u4ef7\u7684\u5e73\u5747\u503c\u53ca\u5176\u663e\u8457\u6027\u57fa\u672c\u672a\u53d7\u5f71\u54cd\uff0c\u8868\u660eCRSP\u7684\u53d8\u66f4\u4e3b\u8981\u5f15\u5165\u4e86\u975e\u7cfb\u7edf\u6027\u6ce2\u52a8\uff0c\u800c\u5e76\u672a\u6539\u53d8\u5173\u952e\u7684\u8d44\u4ea7\u5b9a\u4ef7\u7ed3\u8bba\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1017/s0022109026102725", "journal": "JFQA", "title": "Credibility of Mandatory Disclosure by Credit Rating Agencies and Market Feedback", "authors": ["Jaewoo Kim", "Seyoung Park", "Ryan Wilson"], "author_details": [{"name": "Jaewoo Kim", "affiliations": ["University of Oregon Lundquist College of Business"]}, {"name": "Seyoung Park", "affiliations": ["Georgetown University McDonough School of Business"]}, {"name": "Ryan Wilson", "affiliations": ["University of Iowa Tippie College of Business"]}], "abstract": "Abstract Using the Credit Rating Agency Reform Act of 2006, we examine the effect of the credibility of mandatory disclosure by credit rating agencies (CRAs) on market feedback. We find an increase in investment-price sensitivity for firms affected by the act, and the increase is enhanced when managers have greater incentives to glean information from prices\u2014when firms are exposed to multiple dimensions of uncertainty, have higher growth options, face more competition, have less informed managers, or have higher accounting fraud risk. Our findings suggest that the greater credibility of CRA mandatory disclosure improves managerial learning from stock prices.", "date": "2026-03-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102725", "title_zh": "\u4fe1\u7528\u8bc4\u7ea7\u673a\u6784\u5f3a\u5236\u62ab\u9732\u53ef\u4fe1\u5ea6\u5bf9\u5e02\u573a\u53cd\u9988\u7684\u5f71\u54cd", "abstract_zh": "\u5229\u75282006\u5e74\u300a\u4fe1\u7528\u8bc4\u7ea7\u673a\u6784\u6539\u9769\u6cd5\u6848\u300b\uff0c\u6211\u4eec\u7814\u7a76\u4e86\u4fe1\u7528\u8bc4\u7ea7\u673a\u6784\uff08CRAs\uff09\u5f3a\u5236\u62ab\u9732\u53ef\u4fe1\u5ea6\u5bf9\u5e02\u573a\u53cd\u9988\u7684\u5f71\u54cd\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u53d7\u8be5\u6cd5\u6848\u5f71\u54cd\u7684\u516c\u53f8\u6295\u8d44\u4ef7\u683c\u654f\u611f\u6027\u6709\u6240\u63d0\u9ad8\uff0c\u4e14\u5f53\u7ba1\u7406\u5c42\u4ece\u4ef7\u683c\u4e2d\u83b7\u53d6\u4fe1\u606f\u7684\u6fc0\u52b1\u66f4\u5f3a\u65f6\uff0c\u8fd9\u79cd\u63d0\u5347\u66f4\u4e3a\u663e\u8457\u2014\u2014\u5177\u4f53\u8868\u73b0\u4e3a\u516c\u53f8\u9762\u4e34\u591a\u7ef4\u5ea6\u4e0d\u786e\u5b9a\u6027\u3001\u589e\u957f\u9009\u9879\u8f83\u9ad8\u3001\u7ade\u4e89\u66f4\u6fc0\u70c8\u3001\u7ba1\u7406\u5c42\u4fe1\u606f\u4e0d\u8db3\u6216\u4f1a\u8ba1\u6b3a\u8bc8\u98ce\u9669\u8f83\u9ad8\u7684\u60c5\u51b5\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u4fe1\u7528\u8bc4\u7ea7\u673a\u6784\u5f3a\u5236\u62ab\u9732\u7684\u53ef\u4fe1\u5ea6\u63d0\u5347\u6709\u52a9\u4e8e\u7ba1\u7406\u5c42\u4ece\u80a1\u4ef7\u4e2d\u83b7\u5f97\u5b66\u4e60\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e02\u573a\u53cd\u9988"]}, {"doi": "10.1017/s0022109026102749", "journal": "JFQA", "title": "Personal Financial Information Presentation and Consumer Spending", "authors": ["Yaron Levi"], "author_details": [{"name": "Yaron Levi", "affiliations": ["The University of Oklahoma Price College of Business"]}], "abstract": "Abstract We study whether information design influences consumer behavior in a randomized field experiment with users of an online account aggregation app. Participants received a personalized index representing their net worth as a lifetime monthly cash flow. The presentation of this index varied across treatments in its framing and the salience of its display. Consumers exposed to a consumption-oriented frame and a salient comparison of the index with their past spending reduced discretionary spending. These findings show that minor variations in information presentation can significantly affect financial behavior, highlighting the power of design in promoting saving and informing policy and regulation.", "date": "2026-03-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102749", "title_zh": "\u4e2a\u4eba\u8d22\u52a1\u4fe1\u606f\u5448\u73b0\u4e0e\u6d88\u8d39\u8005\u652f\u51fa", "abstract_zh": "\u6211\u4eec\u901a\u8fc7\u4e00\u9879\u968f\u673a\u5b9e\u5730\u5b9e\u9a8c\u7814\u7a76\u4e86\u4fe1\u606f\u8bbe\u8ba1\u5bf9\u6d88\u8d39\u8005\u884c\u4e3a\u7684\u5f71\u54cd\uff0c\u5b9e\u9a8c\u5bf9\u8c61\u662f\u4f7f\u7528\u5728\u7ebf\u8d26\u6237\u805a\u5408\u5e94\u7528\u7684\u7528\u6237\u3002\u53c2\u4e0e\u8005\u6536\u5230\u4e86\u4e00\u4e2a\u4ee3\u8868\u5176\u7ec8\u8eab\u6708\u73b0\u91d1\u6d41\u51c0\u503c\u7684\u4e2a\u6027\u5316\u6307\u6570\u3002\u8be5\u6307\u6570\u7684\u5448\u73b0\u65b9\u5f0f\u5728\u4e0d\u540c\u5904\u7406\u7ec4\u4e2d\u56e0\u6846\u67b6\u9009\u62e9\u548c\u663e\u793a\u663e\u8457\u6027\u800c\u6709\u6240\u4e0d\u540c\u3002\u63a5\u53d7\u4ee5\u6d88\u8d39\u4e3a\u5bfc\u5411\u6846\u67b6\u4ee5\u53ca\u5c06\u8be5\u6307\u6570\u4e0e\u8fc7\u53bb\u652f\u51fa\u8fdb\u884c\u663e\u8457\u5bf9\u6bd4\u7684\u6d88\u8d39\u8005\uff0c\u5176\u81ea\u4e3b\u9009\u62e9\u652f\u51fa\u51cf\u5c11\u4e86\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u4fe1\u606f\u5448\u73b0\u7684\u5fae\u5c0f\u53d8\u5316\u53ef\u4ee5\u663e\u8457\u5f71\u54cd\u8d22\u52a1\u884c\u4e3a\uff0c\u51f8\u663e\u4e86\u8bbe\u8ba1\u5728\u4fc3\u8fdb\u50a8\u84c4\u4ee5\u53ca\u6307\u5bfc\u653f\u7b56\u548c\u76d1\u7ba1\u65b9\u9762\u7684\u529b\u91cf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag018", "journal": "QJE", "title": "Technology Sophistication Across Establishments", "authors": ["Xavier Cirera", "Diego Comin", "Marcio Cruz"], "author_details": [{"name": "Xavier Cirera", "affiliations": ["World Bank"]}, {"name": "Diego Comin", "affiliations": ["Dartmouth College ,"]}, {"name": "Marcio Cruz", "affiliations": ["International Finance Corporation, World Bank Group"]}], "abstract": "Abstract We study technology sophistication using a novel approach that measures the sophistication of the most advanced (MAX) and the most widely used (MOST) technologies in key business functions within establishments. Using data from over 21,000 establishments across 15 countries, we find that establishments generally underutilize the most sophisticated technologies available in a business function. These MAX-MOST gaps are persistent and strongly associated with productivity both across establishments and countries. At the establishment level, there is substantial variation in both MAX and MOST, with MOST showing a more skewed distribution. MAX and MOST follow different life cycle patterns in low-income countries and among small establishments, and they exhibit different associations with several establishment characteristics and performance indicators. This evidence underscores the different nature of the technology upgrading processes that drive MAX and MOST.", "date": "2026-03-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag018", "title_zh": "\u4f01\u4e1a\u5c42\u9762\u7684\u6280\u672f\u590d\u6742\u5ea6", "abstract_zh": "\u6211\u4eec\u91c7\u7528\u4e00\u79cd\u65b0\u65b9\u6cd5\uff0c\u901a\u8fc7\u8861\u91cf\u4f01\u4e1a\u5173\u952e\u4e1a\u52a1\u804c\u80fd\u4e2d\u6700\u5148\u8fdb\uff08MAX\uff09\u548c\u6280\u672f\u6700\u5e7f\u6cdb\u4f7f\u7528\uff08MOST\uff09\u7684\u6280\u672f\u6c34\u5e73\u6765\u7814\u7a76\u6280\u672f\u590d\u6742\u5ea6\u3002\u57fa\u4e8e\u6765\u81ea15\u4e2a\u56fd\u5bb6\u8d85\u8fc721,000\u5bb6\u4f01\u4e1a\u7684\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u4f01\u4e1a\u901a\u5e38\u672a\u80fd\u5145\u5206\u5229\u7528\u5176\u4e1a\u52a1\u804c\u80fd\u4e2d\u53ef\u83b7\u5f97\u7684\u6700\u5148\u8fdb\u6280\u672f\u3002\u8fd9\u79cdMAX-MOST\u5dee\u8ddd\u5177\u6709\u6301\u7eed\u6027\uff0c\u5e76\u4e14\u5728\u4f01\u4e1a\u4e4b\u95f4\u4ee5\u53ca\u56fd\u5bb6\u4e4b\u95f4\u90fd\u4e0e\u751f\u4ea7\u7387\u5bc6\u5207\u76f8\u5173\u3002\u5728\u4f01\u4e1a\u5c42\u9762\uff0cMAX\u548cMOST\u5747\u8868\u73b0\u51fa\u663e\u8457\u5dee\u5f02\uff0c\u5176\u4e2dMOST\u7684\u5206\u5e03\u66f4\u4e3a\u504f\u659c\u3002\u5728\u4f4e\u6536\u5165\u56fd\u5bb6\u548c\u5c0f\u578b\u4f01\u4e1a\u4e2d\uff0cMAX\u548cMOST\u8868\u73b0\u51fa\u4e0d\u540c\u7684\u751f\u547d\u5468\u671f\u6a21\u5f0f\uff0c\u5e76\u4e0e\u591a\u79cd\u4f01\u4e1a\u7279\u5f81\u548c\u7ee9\u6548\u6307\u6807\u5448\u73b0\u4e0d\u540c\u7684\u5173\u8054\u5173\u7cfb\u3002\u8fd9\u4e00\u8bc1\u636e\u51f8\u663e\u4e86\u9a71\u52a8MAX\u548cMOST\u7684\u6280\u672f\u5347\u7ea7\u8fc7\u7a0b\u5177\u6709\u4e0d\u540c\u7684\u6027\u8d28\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag017", "journal": "QJE", "title": "Making the Invisible Hand Visible: Managers and the Allocation of Workers to Jobs", "authors": ["Virginia Minni"], "author_details": [{"name": "Virginia Minni", "affiliations": ["University of Chicago Booth School of Business ,"]}], "abstract": "Abstract Why do managers matter for firm performance? This article provides evidence of the critical role of managers in matching workers to jobs within the firm using the universe of personnel records from a large multinational firm. The data cover 200,000 white-collar workers and 30,000 managers over 11 years in 100 countries. I identify good managers by their speed of promotion and leverage exogenous variation induced by the rotation of managers across teams. I find that good managers cause workers to reallocate within the firm through lateral and vertical transfers and generate large and persistent gains in workers\u2019 career progression and productivity. My results imply that the visible hands of managers match workers\u2019 specific skills to specialized jobs, leading to an improvement in the productivity of existing workers that outlasts the managers\u2019 time at the firm.", "date": "2026-03-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag017", "title_zh": "\u8ba9\u770b\u4e0d\u89c1\u7684\u624b\u53d8\u5f97\u53ef\u89c1\uff1a\u7ba1\u7406\u8005\u4e0e\u5458\u5de5\u5c97\u4f4d\u5206\u914d", "abstract_zh": "\u4e3a\u4ec0\u4e48\u7ba1\u7406\u8005\u5bf9\u4f01\u4e1a\u7684\u7ee9\u6548\u81f3\u5173\u91cd\u8981\uff1f\u672c\u6587\u5229\u7528\u4e00\u5bb6\u5927\u578b\u8de8\u56fd\u516c\u53f8\u7684\u4eba\u4e8b\u8bb0\u5f55\u6570\u636e\uff0c\u63d0\u4f9b\u4e86\u7ba1\u7406\u8005\u5728\u4f01\u4e1a\u5185\u90e8\u5c06\u5458\u5de5\u5339\u914d\u5230\u4e0d\u540c\u5c97\u4f4d\u4e2d\u7684\u5173\u952e\u4f5c\u7528\u7684\u8bc1\u636e\u3002\u6570\u636e\u6db5\u76d6100\u4e2a\u56fd\u5bb6\u300111\u5e74\u671f\u95f4\u768420\u4e07\u540d\u767d\u9886\u5458\u5de5\u548c3000\u540d\u7ba1\u7406\u8005\u3002\u6211\u901a\u8fc7\u5458\u5de5\u664b\u5347\u901f\u5ea6\u6765\u8bc6\u522b\u4f18\u79c0\u7684\u7ba1\u7406\u8005\uff0c\u5e76\u5229\u7528\u7ba1\u7406\u8005\u5728\u56e2\u961f\u95f4\u8f6e\u6362\u5f15\u53d1\u7684\u5916\u751f\u53d8\u5f02\u6765\u52a0\u4ee5\u9a8c\u8bc1\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u4f18\u79c0\u7684\u7ba1\u7406\u8005\u4f1a\u4fc3\u4f7f\u5458\u5de5\u5728\u4f01\u4e1a\u5185\u90e8\u8fdb\u884c\u6a2a\u5411\u548c\u7eb5\u5411\u7684\u5c97\u4f4d\u8c03\u6574\uff0c\u663e\u8457\u4e14\u6301\u4e45\u5730\u63d0\u5347\u5458\u5de5\u7684\u804c\u4e1a\u53d1\u5c55\u548c\u751f\u4ea7\u7387\u3002\u8fd9\u4e9b\u7ed3\u679c\u8868\u660e\uff0c\u7ba1\u7406\u8005\u7684\u2018\u770b\u5f97\u89c1\u7684\u624b\u2019\u80fd\u591f\u5c06\u5458\u5de5\u7684\u7279\u5b9a\u6280\u80fd\u4e0e\u4e13\u4e1a\u5316\u5c97\u4f4d\u76f8\u5339\u914d\uff0c\u4ece\u800c\u63d0\u5347\u73b0\u6709\u5458\u5de5\u7684\u751f\u4ea7\u7387\uff0c\u4e14\u8fd9\u79cd\u63d0\u5347\u6548\u679c\u6301\u7eed\u5b58\u5728\uff0c\u8fdc\u8d85\u7ba1\u7406\u8005\u5728\u4f01\u4e1a\u4efb\u804c\u7684\u65f6\u95f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70030", "journal": "JF", "title": "Consumer Choice and Corporate Bankruptcy", "authors": ["SAMUEL ANTILL", "MEGAN HUNTER"], "author_details": [{"name": "SAMUEL ANTILL", "affiliations": []}, {"name": "MEGAN HUNTER", "affiliations": []}], "abstract": "ABSTRACT We estimate the indirect costs of corporate bankruptcy associated with lost customers. In incentivized experiments, randomly informing consumers about a firm's Chapter 11 reorganization lowers their willingness to pay for the firm's products by 17% to 28%. Consumers worry that bankruptcy could reduce product quality or prevent future interactions with the bankrupt firm. On average, 38% of consumers are aware of major bankruptcies. Using our experiments to estimate a structural model, we show that these indirect costs of bankruptcy amount to 12% to 15% of a firm's value. We show that these costs are unlikely to arise before bankruptcy.", "date": "2026-03-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70030", "title_zh": "\u6d88\u8d39\u8005\u9009\u62e9\u4e0e\u4f01\u4e1a\u7834\u4ea7", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u4f30\u8ba1\u4e86\u4e0e\u5ba2\u6237\u6d41\u5931\u76f8\u5173\u7684\u516c\u53f8\u7834\u4ea7\u7684\u95f4\u63a5\u6210\u672c\u3002\u5728\u6fc0\u52b1\u6027\u5b9e\u9a8c\u4e2d\uff0c\u968f\u673a\u5411\u6d88\u8d39\u8005\u544a\u77e5\u4f01\u4e1a\u8fdb\u5165\u7b2c11\u7ae0\u91cd\u7ec4\uff0c\u4f1a\u4f7f\u6d88\u8d39\u8005\u5bf9\u8be5\u516c\u53f8\u4ea7\u54c1\u652f\u4ed8\u610f\u613f\u964d\u4f4e17%\u81f328%\u3002\u6d88\u8d39\u8005\u62c5\u5fc3\u7834\u4ea7\u53ef\u80fd\u5bfc\u81f4\u4ea7\u54c1\u8d28\u91cf\u4e0b\u964d\u6216\u4e2d\u65ad\u4e0e\u8be5\u7834\u4ea7\u4f01\u4e1a\u7684\u672a\u6765\u4e92\u52a8\u3002\u5e73\u5747\u800c\u8a00\uff0c38%\u7684\u6d88\u8d39\u8005\u77e5\u6653\u91cd\u5927\u7834\u4ea7\u4e8b\u4ef6\u3002\u5229\u7528\u5b9e\u9a8c\u7ed3\u679c\u6784\u5efa\u7ed3\u6784\u6a21\u578b\uff0c\u6211\u4eec\u53d1\u73b0\u7834\u4ea7\u5e26\u6765\u7684\u95f4\u63a5\u6210\u672c\u5360\u4f01\u4e1a\u4ef7\u503c\u768412%\u81f315%\u3002\u6211\u4eec\u8868\u660e\uff0c\u8fd9\u4e9b\u6210\u672c\u5728\u7834\u4ea7\u53d1\u751f\u4e4b\u524d\u4e0d\u592a\u53ef\u80fd\u51fa\u73b0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag022", "journal": "REStud", "title": "Normal Approximation in Large Network Models", "authors": ["Michael P Leung", "Hyungsik Roger Moon"], "author_details": [{"name": "Michael P Leung", "affiliations": ["Department of Economics, UC Santa Cruz ,"]}, {"name": "Hyungsik Roger Moon", "affiliations": ["Department of Economics, University of Southern California, USA; and Yonsei University, South Korea"]}], "abstract": "Abstract We prove a central limit theorem for network formation models with strategic interactions and homophilous agents. Since data often consists of observations on a single large network, we consider an asymptotic framework in which the network size diverges. We argue that a modification of \u201cstabilization\u201d conditions from the literature on geometric graphs provides a useful high-level formulation of weak dependence which we utilize to establish an abstract central limit theorem. Using results in branching process theory, we derive interpretable primitive conditions for stabilization. The main conditions restrict the strength of strategic interactions and equilibrium selection mechanism. We discuss practical inference procedures justified by our results.", "date": "2026-03-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag022", "title_zh": "\u5927\u7f51\u7edc\u6a21\u578b\u4e2d\u7684\u6b63\u6001\u8fd1\u4f3c", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u4e3a\u5177\u6709\u6218\u7565\u4e92\u52a8\u548c\u540c\u8d28\u6027\u4ee3\u7406\u7684\u7f51\u7edc\u5f62\u6210\u6a21\u578b\u8bc1\u660e\u4e86\u4e00\u4e2a\u4e2d\u5fc3\u6781\u9650\u5b9a\u7406\u3002\u7531\u4e8e\u6570\u636e\u901a\u5e38\u4ec5\u5305\u542b\u5355\u4e2a\u5927\u578b\u7f51\u7edc\u7684\u89c2\u6d4b\uff0c\u6211\u4eec\u8003\u8651\u7f51\u7edc\u89c4\u6a21\u8d8b\u4e8e\u65e0\u7a77\u7684\u6e10\u8fd1\u6846\u67b6\u3002\u6211\u4eec\u8ba4\u4e3a\uff0c\u5bf9\u51e0\u4f55\u56fe\u6587\u732e\u4e2d\u201c\u7a33\u5b9a\u5316\u201d\u6761\u4ef6\u7684\u4fee\u6539\u63d0\u4f9b\u4e86\u4e00\u79cd\u63cf\u8ff0\u5f31\u4f9d\u8d56\u6027\u7684\u9ad8\u5c42\u6b21\u8868\u8ff0\uff0c\u6211\u4eec\u5229\u7528\u8fd9\u4e00\u8868\u8ff0\u5efa\u7acb\u4e86\u62bd\u8c61\u7684\u4e2d\u5fc3\u6781\u9650\u5b9a\u7406\u3002\u901a\u8fc7\u5206\u652f\u8fc7\u7a0b\u7406\u8bba\u7684\u7ed3\u679c\uff0c\u6211\u4eec\u63a8\u5bfc\u51fa\u53ef\u89e3\u91ca\u7684\u539f\u59cb\u6761\u4ef6\u4ee5\u5b9e\u73b0\u7a33\u5b9a\u5316\u3002\u4e3b\u8981\u6761\u4ef6\u9650\u5236\u4e86\u6218\u7565\u4e92\u52a8\u7684\u5f3a\u5ea6\u4ee5\u53ca\u5747\u8861\u9009\u62e9\u673a\u5236\u3002\u6211\u4eec\u8ba8\u8bba\u4e86\u7531\u6211\u4eec\u7684\u7ed3\u679c\u6240\u652f\u6301\u7684\u5b9e\u7528\u63a8\u65ad\u7a0b\u5e8f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/restud/rdag023", "journal": "REStud", "title": "De Gustibus and Disputes about Reference Dependence", "authors": ["Pol Campos-Mercade", "Lorenz Goette", "Thomas Graeber", "Alexandre Kellogg", "Charles Sprenger"], "author_details": [{"name": "Pol Campos-Mercade", "affiliations": ["Department of Economics, Lund University ,"]}, {"name": "Lorenz Goette", "affiliations": ["Department of Economics, National University of Singapore ,"]}, {"name": "Thomas Graeber", "affiliations": ["Department of Economics, University of Zurich ,"]}, {"name": "Alexandre Kellogg", "affiliations": ["Google ,"]}, {"name": "Charles Sprenger", "affiliations": ["Division of Humanities and Social Sciences, California Institute of Technology ,"]}], "abstract": "Abstract Existing tests of reference-dependent preferences assume universal loss aversion. This paper examines the implications of heterogeneity in gain-loss attitudes for such tests. In experiments on labour supply and exchange behaviour, we first measure gain-loss attitudes and then study a canonical treatment effect that distinguishes different models of reference dependence. We document substantial heterogeneity in gain-loss attitudes and evidence against universal loss aversion. Moreover, we find heterogeneous treatment effects over gain-loss attitudes consistent with formulations of expectations-based reference points. Assuming homogeneous preferences would lead to different and potentially incorrect conclusions in these tests. Our findings provide foundational support for reference points derived from expectations and help reconcile inconsistencies in prior empirical exercises.", "date": "2026-03-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag023", "title_zh": "\u5173\u4e8e\u53e3\u5473\u504f\u597d\u4e0e\u53c2\u7167\u4f9d\u8d56\u7684\u4e89\u8bae", "abstract_zh": "\u73b0\u6709\u53c2\u7167\u4f9d\u8d56\u504f\u597d\u7684\u68c0\u9a8c\u5747\u5047\u8bbe\u666e\u904d\u7684\u635f\u5931\u538c\u6076\u3002\u672c\u6587\u8003\u5bdf\u4e86\u6536\u76ca-\u635f\u5931\u6001\u5ea6\u5f02\u8d28\u6027\u5bf9\u8fd9\u7c7b\u68c0\u9a8c\u7684\u542b\u4e49\u3002\u5728\u5173\u4e8e\u52b3\u52a8\u529b\u4f9b\u7ed9\u548c\u4ea4\u6362\u884c\u4e3a\u7684\u5b9e\u9a8c\u4e2d\uff0c\u6211\u4eec\u9996\u5148\u6d4b\u91cf\u6536\u76ca-\u635f\u5931\u6001\u5ea6\uff0c\u7136\u540e\u7814\u7a76\u4e00\u4e2a\u5178\u578b\u7684\u5904\u7406\u6548\u5e94\uff0c\u4ee5\u533a\u5206\u4e0d\u540c\u7c7b\u578b\u7684\u53c2\u7167\u4f9d\u8d56\u6a21\u578b\u3002\u6211\u4eec\u53d1\u73b0\u6536\u76ca-\u635f\u5931\u6001\u5ea6\u5b58\u5728\u663e\u8457\u5f02\u8d28\u6027\uff0c\u5e76\u4e14\u53cd\u5bf9\u666e\u904d\u635f\u5931\u538c\u6076\u7684\u5047\u8bbe\u3002\u6b64\u5916\uff0c\u6211\u4eec\u53d1\u73b0\u6536\u76ca-\u635f\u5931\u6001\u5ea6\u4e0a\u7684\u5904\u7406\u6548\u5e94\u5b58\u5728\u5f02\u8d28\u6027\uff0c\u8fd9\u4e0e\u57fa\u4e8e\u9884\u671f\u7684\u53c2\u7167\u70b9\u6a21\u578b\u76f8\u4e00\u81f4\u3002\u82e5\u5047\u8bbe\u504f\u597d\u5747\u8d28\uff0c\u5c06\u53ef\u80fd\u5bfc\u81f4\u7ed3\u8bba\u4e0d\u540c\u751a\u81f3\u9519\u8bef\u3002\u6211\u4eec\u7684\u53d1\u73b0\u4e3a\u57fa\u4e8e\u9884\u671f\u7684\u53c2\u7167\u70b9\u63d0\u4f9b\u4e86\u57fa\u7840\u652f\u6301\uff0c\u5e76\u6709\u52a9\u4e8e\u89e3\u51b3\u4ee5\u5f80\u5b9e\u8bc1\u7814\u7a76\u4e2d\u7684\u4e0d\u4e00\u81f4\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70029", "journal": "JF", "title": "Pricing of Climate Risk Insurance: Regulation and Cross\u2010Subsidies", "authors": ["SANGMIN S. OH", "ISHITA SEN", "ANA\u2010MARIA TENEKEDJIEVA"], "author_details": [{"name": "SANGMIN S. OH", "affiliations": []}, {"name": "ISHITA SEN", "affiliations": []}, {"name": "ANA\u2010MARIA TENEKEDJIEVA", "affiliations": []}], "abstract": "ABSTRACT Homeowners insurance is central to managing the rising losses from climate\u2010related disasters. We show that insurance premiums are subject to starkly different regulations across states, creating persistent cross\u2010subsidies and price distortions. We employ states' regulatory rules in an instrumental variable estimation and a border discontinuity design to show insurers do not adjust rates in highly regulated states and compensate by raising rates in less regulated states. Rates and risks diverge in the long run, distorting cross\u2010state risk\u2010sharing and increasing insurer exits from highly regulated states. We argue these patterns stem from the interactions between rate regulation and insurers' financing constraints.", "date": "2026-03-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70029", "title_zh": "\u6c14\u5019\u98ce\u9669\u4fdd\u9669\u5b9a\u4ef7\uff1a\u76d1\u7ba1\u4e0e\u4ea4\u53c9\u8865\u8d34", "abstract_zh": "\u6458\u8981 \u623f\u5c4b\u4fdd\u9669\u5728\u5e94\u5bf9\u6c14\u5019\u76f8\u5173\u707e\u5bb3\u5e26\u6765\u7684\u65e5\u76ca\u589e\u957f\u7684\u635f\u5931\u65b9\u9762\u8d77\u7740\u6838\u5fc3\u4f5c\u7528\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5404\u5dde\u5bf9\u4fdd\u9669\u8d39\u7387\u7684\u76d1\u7ba1\u5b58\u5728\u663e\u8457\u5dee\u5f02\uff0c\u5bfc\u81f4\u957f\u671f\u7684\u4ea4\u53c9\u8865\u8d34\u548c\u4ef7\u683c\u626d\u66f2\u3002\u6211\u4eec\u5229\u7528\u5404\u5dde\u7684\u76d1\u7ba1\u89c4\u5219\uff0c\u901a\u8fc7\u5de5\u5177\u53d8\u91cf\u4f30\u8ba1\u548c\u8fb9\u754c\u65ad\u70b9\u8bbe\u8ba1\uff0c\u8868\u660e\u4fdd\u9669\u516c\u53f8\u5e76\u672a\u5728\u76d1\u7ba1\u4e25\u683c\u7684\u5dde\u8c03\u6574\u8d39\u7387\uff0c\u53cd\u800c\u901a\u8fc7\u63d0\u9ad8\u5728\u76d1\u7ba1\u8f83\u5bbd\u677e\u5dde\u7684\u8d39\u7387\u6765\u5f25\u8865\u3002\u957f\u671f\u6765\u770b\uff0c\u8d39\u7387\u4e0e\u98ce\u9669\u5728\u5404\u5dde\u4e4b\u95f4\u51fa\u73b0\u504f\u79bb\uff0c\u626d\u66f2\u4e86\u8de8\u5dde\u7684\u98ce\u9669\u5206\u62c5\uff0c\u5e76\u5bfc\u81f4\u4fdd\u9669\u516c\u53f8\u9000\u51fa\u76d1\u7ba1\u4e25\u683c\u7684\u5dde\u3002\u6211\u4eec\u8ba4\u4e3a\uff0c\u8fd9\u79cd\u73b0\u8c61\u6e90\u4e8e\u76d1\u7ba1\u4e0e\u4fdd\u9669\u516c\u53f8\u878d\u8d44\u7ea6\u675f\u4e4b\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag022", "journal": "RFS", "title": "Machine Learning and the Implementable Efficient Frontier", "authors": ["Theis Ingerslev Jensen", "Bryan Kelly", "Semyon Malamud", "Lasse Heje Pedersen"], "author_details": [{"name": "Theis Ingerslev Jensen", "affiliations": ["Yale School of Management ,"]}, {"name": "Bryan Kelly", "affiliations": ["Yale School of Management, AQR Capital Management, and NBER ,"]}, {"name": "Semyon Malamud", "affiliations": ["Swiss Finance Institute, Switzerland, EPFL, and CEPR"]}, {"name": "Lasse Heje Pedersen", "affiliations": ["AQR Capital Management, Copenhagen Business School, Denmark, and CEPR"]}], "abstract": "Abstract We propose that investment strategies should be evaluated based on their net-of-trading-cost return for each level of risk, which we term the \u201cimplementable efficient frontier.\u201d While numerous studies use machine learning return forecasts to generate portfolios, their agnosticism toward trading costs leads to excessive reliance on fleeting small-scale characteristics, resulting in poor net returns. We develop a framework that produces a superior frontier by integrating trading-cost-aware portfolio optimization with machine learning. The superior net-of-cost performance is achieved by learning directly about portfolio weights using an economic objective. Further, our model gives rise to a new measure of \u201ceconomic feature importance.\u201d", "date": "2026-03-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag022", "title_zh": "\u673a\u5668\u5b66\u4e60\u4e0e\u53ef\u5b9e\u65bd\u7684\u6709\u6548\u524d\u6cbf", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\uff0c\u6295\u8d44\u7b56\u7565\u5e94\u57fa\u4e8e\u6bcf\u79cd\u98ce\u9669\u6c34\u5e73\u4e0b\u7684\u51c0\u4ea4\u6613\u6210\u672c\u56de\u62a5\u8fdb\u884c\u8bc4\u4f30\uff0c\u8fd9\u4e00\u6982\u5ff5\u88ab\u79f0\u4e3a\u201c\u53ef\u5b9e\u65bd\u7684\u6709\u6548\u524d\u6cbf\u201d\u3002\u5c3d\u7ba1\u8bb8\u591a\u7814\u7a76\u5229\u7528\u673a\u5668\u5b66\u4e60\u7684\u56de\u62a5\u9884\u6d4b\u6765\u6784\u5efa\u6295\u8d44\u7ec4\u5408\uff0c\u4f46\u5176\u5bf9\u4ea4\u6613\u6210\u672c\u7684\u6f20\u89c6\u5bfc\u81f4\u8fc7\u5ea6\u4f9d\u8d56\u77ed\u6682\u7684\u3001\u5c0f\u89c4\u6a21\u7684\u7279\u5f81\uff0c\u4ece\u800c\u4ea7\u751f\u8f83\u5dee\u7684\u51c0\u56de\u62a5\u3002\u6211\u4eec\u5f00\u53d1\u4e86\u4e00\u79cd\u6846\u67b6\uff0c\u901a\u8fc7\u5c06\u8003\u8651\u4ea4\u6613\u6210\u672c\u7684\u7ec4\u5408\u4f18\u5316\u4e0e\u673a\u5668\u5b66\u4e60\u76f8\u7ed3\u5408\uff0c\u751f\u6210\u66f4\u4f18\u7684\u524d\u6cbf\u3002\u8be5\u6846\u67b6\u901a\u8fc7\u4f7f\u7528\u7ecf\u6d4e\u76ee\u6807\u76f4\u63a5\u5b66\u4e60\u7ec4\u5408\u6743\u91cd\uff0c\u5b9e\u73b0\u4e86\u66f4\u4f18\u7684\u51c0\u4ea4\u6613\u6210\u672c\u8868\u73b0\u3002\u6b64\u5916\uff0c\u6211\u4eec\u7684\u6a21\u578b\u5f15\u51fa\u4e86\u201c\u7ecf\u6d4e\u7279\u5f81\u91cd\u8981\u6027\u201d\u8fd9\u4e00\u65b0\u5ea6\u91cf\u6807\u51c6\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "AI"]}, {"doi": "10.1093/restud/rdag020", "journal": "REStud", "title": "Gendered Spheres of Learning and Household Decision-Making over Fertility", "authors": ["Nava Ashraf", "Maxim Bakhtin", "Erica Field", "Alessandra Voena", "Roberta Ziparo"], "author_details": [{"name": "Nava Ashraf", "affiliations": ["London School of Economics and Political Science, CEPR and BREAD ,"]}, {"name": "Maxim Bakhtin", "affiliations": ["Analysis Group, Inc. ,"]}, {"name": "Erica Field", "affiliations": ["Duke University, NBER and BREAD ,"]}, {"name": "Alessandra Voena", "affiliations": ["Stanford University, NBER, CEPR, SIEPR and BREAD ,"]}, {"name": "Roberta Ziparo", "affiliations": ["Aix-Marseille University, CNRS, EHESS, Central Marseille, IRD, AMSE , Marseille ,"]}], "abstract": "Abstract While men and women make joint decisions about fertility, women give birth and are more likely to learn about a significant cost of childbearing\u2014maternal health risk. Within couples in Zambia, men have systematically lower awareness of maternal risk factors and higher desire for children than their wives. We develop a model in which information asymmetries between partners over maternal health risk can persist in equilibrium due to strategic incentives and can generate disagreement over fertility that cannot be resolved with transfers. To study the effect of communication barriers on fertility, we design an experiment that varies whether the husband or the wife receives information about maternal health risk. One year after the intervention, men told about such risk exhibit significant gains in knowledge, report lower demand for children, and communicate this information to their wives, who also update their beliefs. Pregnancy falls significantly, while transfers remain unchanged relative to the control group. Meanwhile, when women are told about risk, they update their beliefs, but fail to transmit the information to their husbands, who do not change their demand for children. While pregnancy also falls among these couples, the decline is accompanied by a significant reduction in transfers and support to the wife. When childbearing costs, particularly those borne by one party, cannot be easily communicated within the household, targeting information can help overcome asymmetries and improve household decision-making.", "date": "2026-03-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag020", "title_zh": "\u5b66\u4e60\u9886\u57df\u4e0e\u5bb6\u5ead\u751f\u80b2\u51b3\u7b56\u4e2d\u7684\u6027\u522b\u5dee\u5f02", "abstract_zh": "\u5c3d\u7ba1\u7537\u5973\u5171\u540c\u53c2\u4e0e\u751f\u80b2\u51b3\u7b56\uff0c\u4f46\u5973\u6027\u4f1a\u5206\u5a29\uff0c\u5e76\u66f4\u53ef\u80fd\u4e86\u89e3\u5230\u751f\u80b2\u5e26\u6765\u7684\u91cd\u5927\u6210\u672c\u2014\u2014\u6bcd\u4f53\u5065\u5eb7\u98ce\u9669\u3002\u5728\u8d5e\u6bd4\u4e9a\u7684\u592b\u59bb\u4e2d\uff0c\u7537\u6027\u5bf9\u6bcd\u4f53\u98ce\u9669\u56e0\u7d20\u7684\u4e86\u89e3\u660e\u663e\u4f4e\u4e8e\u5973\u6027\uff0c\u4e14\u5bf9\u5b50\u5973\u6570\u91cf\u7684\u6e34\u671b\u66f4\u9ad8\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6a21\u578b\uff0c\u8bf4\u660e\u7531\u4e8e\u4f34\u4fa3\u4e4b\u95f4\u5173\u4e8e\u6bcd\u4f53\u5065\u5eb7\u98ce\u9669\u7684\u4fe1\u606f\u4e0d\u5bf9\u79f0\uff0c\u53ef\u80fd\u5728\u5747\u8861\u4e2d\u6301\u7eed\u5b58\u5728\uff0c\u8fd9\u79cd\u4e0d\u5bf9\u79f0\u4f1a\u56e0\u6218\u7565\u6fc0\u52b1\u800c\u4ea7\u751f\u751f\u80b2\u51b3\u7b56\u4e0a\u7684\u5206\u6b67\uff0c\u4e14\u65e0\u6cd5\u901a\u8fc7\u8f6c\u79fb\u652f\u4ed8\u89e3\u51b3\u3002\u4e3a\u4e86\u7814\u7a76\u6c9f\u901a\u969c\u788d\u5bf9\u751f\u80b2\u7684\u5f71\u54cd\uff0c\u6211\u4eec\u8bbe\u8ba1\u4e86\u4e00\u4e2a\u5b9e\u9a8c\uff0c\u5206\u522b\u8ba9\u4e08\u592b\u6216\u59bb\u5b50\u4e86\u89e3\u6bcd\u4f53\u5065\u5eb7\u98ce\u9669\u3002\u5e72\u9884\u4e00\u5e74\u540e\uff0c\u88ab\u544a\u77e5\u98ce\u9669\u7684\u7537\u6027\u5728\u77e5\u8bc6\u6c34\u5e73\u4e0a\u663e\u8457\u63d0\u5347\uff0c\u62a5\u544a\u5b50\u5973\u9700\u6c42\u51cf\u5c11\uff0c\u5e76\u5c06\u8fd9\u4e00\u4fe1\u606f\u4f20\u9012\u7ed9\u59bb\u5b50\uff0c\u59bb\u5b50\u4e5f\u66f4\u65b0\u4e86\u81ea\u8eab\u4fe1\u5ff5\u3002\u751f\u80b2\u7387\u663e\u8457\u4e0b\u964d\uff0c\u800c\u8f6c\u79fb\u652f\u4ed8\u4e0e\u5bf9\u7167\u7ec4\u76f8\u6bd4\u4fdd\u6301\u4e0d\u53d8\u3002\u7136\u800c\uff0c\u5f53\u5973\u6027\u88ab\u544a\u77e5\u98ce\u9669\u65f6\uff0c\u5979\u4eec\u4f1a\u66f4\u65b0\u4fe1\u5ff5\uff0c\u4f46\u672a\u80fd\u5c06\u4fe1\u606f\u4f20\u9012\u7ed9\u4e08\u592b\uff0c\u4e08\u592b\u7684\u5b50\u5973\u9700\u6c42\u672a\u53d1\u751f\u6539\u53d8\u3002\u8fd9\u4e9b\u592b\u59bb\u7684\u751f\u80b2\u7387\u4e5f\u4e0b\u964d\uff0c\u4f46\u4f34\u968f\u663e\u8457\u51cf\u5c11\u7684\u8f6c\u79fb\u652f\u4ed8\u548c\u5bf9\u59bb\u5b50\u7684\u652f\u6301\u3002\u5f53\u751f\u80b2\u6210\u672c\uff0c\u5c24\u5176\u662f\u7531\u4e00\u65b9\u627f\u62c5\u7684\u6210\u672c\uff0c\u96be\u4ee5\u5728\u5bb6\u5ead\u5185\u90e8\u6709\u6548\u6c9f\u901a\u65f6\uff0c\u6709\u9488\u5bf9\u6027\u7684\u4fe1\u606f\u4f20\u9012\u6709\u52a9\u4e8e\u6d88\u9664\u4fe1\u606f\u4e0d\u5bf9\u79f0\uff0c\u6539\u5584\u5bb6\u5ead\u51b3\u7b56\u8fc7\u7a0b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhaf103", "journal": "RFS", "title": "Asset Overhang and Technological Change", "authors": ["Hans Degryse", "Tarik Roukny", "Joris Tielens"], "author_details": [{"name": "Hans Degryse", "affiliations": ["KU Leuven and CEPR ,"]}, {"name": "Tarik Roukny", "affiliations": ["KU Leuven ,"]}, {"name": "Joris Tielens", "affiliations": ["National Bank of Belgium ,"]}], "abstract": "Abstract Investors face reduced incentives to finance technological change that devalues their legacy investments. We formalize this \u201casset overhang\u201d and apply our framework to the climate-banking nexus. Leveraging (1) firm-level data on green innovation and diffusion and (2) the sets of product and technology market peers, we implement a shift-share design that identifies banks\u2019 credit facilities impacted by green firm activities. We find that green firms imposing an asset overhang across all lenders are 3 to 7 percentage points more likely to report tight credit supply conditions. The presence of legacy-free investors mitigates the asset overhang problem, thereby facilitating technological change.", "date": "2026-03-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf103", "title_zh": "\u8d44\u4ea7\u8fc7\u5269\u4e0e\u6280\u672f\u53d8\u9769", "abstract_zh": "\u6295\u8d44\u8005\u5728\u9762\u5bf9\u53ef\u80fd\u8d2c\u635f\u5176\u539f\u6709\u6295\u8d44\u4ef7\u503c\u7684\u6280\u672f\u53d8\u9769\u65f6\uff0c\u5176\u878d\u8d44\u6fc0\u52b1\u4f1a\u964d\u4f4e\u3002\u6211\u4eec\u6b63\u5f0f\u63d0\u51fa\u4e86\u8fd9\u4e00\u2018\u8d44\u4ea7\u8fc7\u5269\u2019\u73b0\u8c61\uff0c\u5e76\u5c06\u5176\u6846\u67b6\u5e94\u7528\u4e8e\u6c14\u5019\u4e0e\u94f6\u884c\u4e1a\u4e4b\u95f4\u7684\u5173\u7cfb\u3002\u5229\u7528\uff081\uff09\u4f01\u4e1a\u5c42\u9762\u7684\u7eff\u8272\u521b\u65b0\u53ca\u6269\u6563\u6570\u636e\uff0c\u4ee5\u53ca\uff082\uff09\u4ea7\u54c1\u548c\u79d1\u6280\u5e02\u573a\u540c\u884c\u96c6\u5408\uff0c\u6211\u4eec\u5b9e\u65bd\u4e86\u4e00\u79cd\u79fb\u4f4d\u4efd\u989d\u8bbe\u8ba1\uff0c\u4ee5\u8bc6\u522b\u94f6\u884c\u4fe1\u8d37\u8bbe\u65bd\u53d7\u7eff\u8272\u4f01\u4e1a\u6d3b\u52a8\u5f71\u54cd\u7684\u7a0b\u5ea6\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5bf9\u6240\u6709\u8d37\u6b3e\u65b9\u5747\u4ea7\u751f\u8d44\u4ea7\u8fc7\u5269\u6548\u5e94\u7684\u7eff\u8272\u4f01\u4e1a\uff0c\u5176\u62a5\u544a\u7d27\u7f29\u4fe1\u8d37\u4f9b\u5e94\u72b6\u51b5\u7684\u6982\u7387\u9ad8\u51fa3\u81f37\u4e2a\u767e\u5206\u70b9\u3002\u5b58\u5728\u65e0\u9057\u7559\u8d44\u4ea7\u6295\u8d44\u8005\u7684\u60c5\u51b5\u53ef\u7f13\u89e3\u8d44\u4ea7\u8fc7\u5269\u95ee\u9898\uff0c\u4ece\u800c\u4fc3\u8fdb\u6280\u672f\u53d8\u9769\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag019", "journal": "REStud", "title": "Should Monetary Policy Care about Redistribution? Optimal Monetary and Fiscal Policy with Heterogeneous Agents", "authors": ["Fran\u00e7ois Le Grand", "Ala\u00efs Martin-Baillon", "Xavier Ragot"], "author_details": [{"name": "Fran\u00e7ois Le Grand", "affiliations": ["ESSEC Business School and Thema ,"]}, {"name": "Ala\u00efs Martin-Baillon", "affiliations": ["NYUAD and CEPR, The"]}, {"name": "Xavier Ragot", "affiliations": ["SciencesPo-CNRS, OFCE, and CEPR ,"]}], "abstract": "Abstract We present a method to determine optimal monetary policy in heterogeneous-agent economies with nominal frictions and aggregate shocks, under various assumptions regarding fiscal policy. We analyze models with either sticky prices or sticky wages. In the sticky-price economy, when fiscal policy is optimally set, optimal monetary policy implements price stability. Inflation volatility remains low when fiscal policy follows empirically relevant rules. The inflation response is more pronounced when the Phillips curve is steep and profits are skewed toward highly productive agents. In the sticky-wage economy, optimal price inflation becomes significantly more volatile, while wage inflation remains small. Under both types of nominal rigidity, agents with lower productivity tend to benefit more from optimal monetary policy.", "date": "2026-03-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag019", "title_zh": "\u8d27\u5e01\u653f\u7b56\u662f\u5426\u5e94\u5173\u6ce8\u518d\u5206\u914d\uff1f\u5177\u6709\u5f02\u8d28\u6027\u4e3b\u4f53\u7684\u6700\u4f18\u8d27\u5e01\u653f\u7b56\u4e0e\u8d22\u653f\u653f\u7b56", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u5728\u5b58\u5728\u540d\u4e49\u6469\u64e6\u548c\u603b\u51b2\u51fb\u7684\u5f02\u8d28\u6027\u4e3b\u4f53\u7ecf\u6d4e\u4e2d\uff0c\u6839\u636e\u4e0d\u540c\u8d22\u653f\u653f\u7b56\u5047\u8bbe\u6765\u786e\u5b9a\u6700\u4f18\u8d27\u5e01\u653f\u7b56\u7684\u65b9\u6cd5\u3002\u6211\u4eec\u5206\u6790\u4e86\u5177\u6709\u7c98\u6027\u4ef7\u683c\u6216\u7c98\u6027\u5de5\u8d44\u7684\u6a21\u578b\u3002\u5728\u7c98\u6027\u4ef7\u683c\u7ecf\u6d4e\u4e2d\uff0c\u5f53\u8d22\u653f\u653f\u7b56\u88ab\u6700\u4f18\u8bbe\u5b9a\u65f6\uff0c\u6700\u4f18\u8d27\u5e01\u653f\u7b56\u5b9e\u73b0\u4ef7\u683c\u7a33\u5b9a\u3002\u5f53\u8d22\u653f\u653f\u7b56\u9075\u5faa\u7ecf\u9a8c\u4e0a\u76f8\u5173\u7684\u89c4\u5219\u65f6\uff0c\u901a\u80c0\u6ce2\u52a8\u6027\u4fdd\u6301\u8f83\u4f4e\u6c34\u5e73\u3002\u5f53\u83f2\u5229\u666e\u65af\u66f2\u7ebf\u8f83\u9661\u4e14\u5229\u6da6\u5411\u9ad8\u751f\u4ea7\u7387\u4e3b\u4f53\u503e\u659c\u65f6\uff0c\u901a\u80c0\u53cd\u5e94\u66f4\u4e3a\u663e\u8457\u3002\u5728\u7c98\u6027\u5de5\u8d44\u7ecf\u6d4e\u4e2d\uff0c\u6700\u4f18\u4ef7\u683c\u901a\u80c0\u53d8\u5f97\u663e\u8457\u66f4\u6ce2\u52a8\uff0c\u800c\u5de5\u8d44\u901a\u80c0\u5219\u4fdd\u6301\u8f83\u5c0f\u3002\u5728\u4e24\u79cd\u540d\u4e49\u521a\u6027\u60c5\u51b5\u4e0b\uff0c\u751f\u4ea7\u7387\u8f83\u4f4e\u7684\u4e3b\u4f53\u4ece\u6700\u4f18\u8d27\u5e01\u653f\u7b56\u4e2d\u83b7\u76ca\u66f4\u591a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag015", "journal": "QJE", "title": "Peer Effects and the Gender Gap in Corporate Leadership: Evidence from MBA Students", "authors": ["Menaka Hampole", "Francesca Truffa", "Ashley Wong"], "author_details": [{"name": "Menaka Hampole", "affiliations": ["Yale School of Management ,"]}, {"name": "Francesca Truffa", "affiliations": ["University of Michigan Ross School of Business, United States, and CESIFO ,"]}, {"name": "Ashley Wong", "affiliations": ["Barnard College of Columbia University, United States, and CESIFO ,"]}], "abstract": "Abstract Women continue to be underrepresented in corporate leadership positions. This article studies the role of social connections in women\u2019s career advancement. We investigate whether access to a larger share of female peers in business school affects the gender gap in senior managerial positions. Merging administrative data from a top 10 U.S. business school with public LinkedIn profiles, we first document that female MBAs are 24% less likely than male MBAs to enter senior management within 15 years of graduation. Next we use the exogenous assignment of students into sections to show that a larger proportion of female MBA section peers increases the likelihood of entering senior management for women but not for men. This effect is driven by female-friendly firms, such as those with more generous maternity leave policies and greater work-schedule flexibility. A larger proportion of female MBA peers induces women to transition to these firms where they attain senior management roles. A survey of female MBA alumnae reveals three key mechanisms: (i) information sharing, especially related to gender-specific advice, (ii) higher ambitions and self-confidence, and (iii) increasing support from male MBA peers. These findings highlight the role of social connections in reducing the gender gap in senior management positions.", "date": "2026-03-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag015", "title_zh": "\u540c\u4f34\u6548\u5e94\u4e0e\u4f01\u4e1a\u9886\u5bfc\u5c42\u4e2d\u7684\u6027\u522b\u5dee\u8ddd\uff1a\u6765\u81eaMBA\u5b66\u751f\u7684\u8bc1\u636e", "abstract_zh": "\u5973\u6027\u5728\u4f01\u4e1a\u9886\u5bfc\u804c\u4f4d\u4e2d\u7684\u4ee3\u8868\u6027\u4ecd\u7136\u4e0d\u8db3\u3002\u672c\u6587\u7814\u7a76\u4e86\u793e\u4ea4\u5173\u7cfb\u5728\u5973\u6027\u804c\u4e1a\u53d1\u5c55\u4e2d\u7684\u4f5c\u7528\u3002\u6211\u4eec\u8003\u5bdf\u4e86\u5728\u5546\u5b66\u9662\u4e2d\u62e5\u6709\u66f4\u591a\u5973\u6027\u540c\u4f34\u662f\u5426\u4f1a\u5f71\u54cd\u4f01\u4e1a\u9ad8\u5c42\u7ba1\u7406\u804c\u4f4d\u4e2d\u7684\u6027\u522b\u5dee\u8ddd\u3002\u901a\u8fc7\u5c06\u4e00\u6240\u7f8e\u56fd\u9876\u7ea7\u5546\u5b66\u9662\u7684\u884c\u653f\u6570\u636e\u4e0e\u516c\u5f00\u7684LinkedIn\u8d44\u6599\u5408\u5e76\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5973\u6027MBA\u6bd5\u4e1a\u751f\u5728\u6bd5\u4e1a\u540e15\u5e74\u5185\u8fdb\u5165\u9ad8\u5c42\u7ba1\u7406\u804c\u4f4d\u7684\u6982\u7387\u6bd4\u7537\u6027MBA\u6bd5\u4e1a\u751f\u4f4e24%\u3002\u63a5\u7740\uff0c\u6211\u4eec\u5229\u7528\u5b66\u751f\u88ab\u968f\u673a\u5206\u914d\u5230\u73ed\u7ea7\u7684\u5916\u751f\u6027\uff0c\u53d1\u73b0\u5973\u6027MBA\u73ed\u7ea7\u4e2d\u5973\u6027\u540c\u4f34\u6bd4\u4f8b\u8d8a\u9ad8\uff0c\u5973\u6027\u8fdb\u5165\u9ad8\u5c42\u7ba1\u7406\u804c\u4f4d\u7684\u53ef\u80fd\u6027\u5c31\u8d8a\u5927\uff0c\u800c\u5bf9\u7537\u6027\u5219\u65e0\u6b64\u5f71\u54cd\u3002\u8fd9\u79cd\u6548\u5e94\u4e3b\u8981\u4f53\u73b0\u5728\u5bf9\u5973\u6027\u53cb\u597d\u7684\u4f01\u4e1a\u4e2d\uff0c\u4f8b\u5982\u63d0\u4f9b\u66f4\u6177\u6168\u4ea7\u5047\u653f\u7b56\u548c\u66f4\u7075\u6d3b\u5de5\u4f5c\u65f6\u95f4\u5b89\u6392\u7684\u4f01\u4e1a\u3002\u5973\u6027MBA\u540c\u4f34\u6bd4\u4f8b\u7684\u589e\u52a0\u4fc3\u4f7f\u5973\u6027\u8f6c\u5411\u8fd9\u4e9b\u4f01\u4e1a\uff0c\u5e76\u5728\u5176\u4e2d\u83b7\u5f97\u9ad8\u5c42\u7ba1\u7406\u804c\u4f4d\u3002\u5bf9\u5973\u6027MBA\u6821\u53cb\u7684\u8c03\u67e5\u663e\u793a\uff0c\u5b58\u5728\u4e09\u4e2a\u5173\u952e\u673a\u5236\uff1a\uff08i\uff09\u4fe1\u606f\u5171\u4eab\uff0c\u5c24\u5176\u662f\u4e0e\u6027\u522b\u7279\u5b9a\u5efa\u8bae\u76f8\u5173\u7684\u4fe1\u606f\uff1b\uff08ii\uff09\u66f4\u9ad8\u7684\u804c\u4e1a\u62b1\u8d1f\u548c\u81ea\u4fe1\u5fc3\uff1b\uff08iii\uff09\u6765\u81ea\u7537\u6027MBA\u540c\u4f34\u7684\u652f\u6301\u589e\u5f3a\u3002\u8fd9\u4e9b\u53d1\u73b0\u51f8\u663e\u4e86\u793e\u4ea4\u5173\u7cfb\u5728\u7f29\u5c0f\u9ad8\u5c42\u7ba1\u7406\u804c\u4f4d\u6027\u522b\u5dee\u8ddd\u4e2d\u7684\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102737", "journal": "JFQA", "title": "Swimming Against the Current: Contrarian Retail Trading", "authors": ["Brad Cannon", "Hannes Mohrschladt"], "author_details": [{"name": "Brad Cannon", "affiliations": ["Binghamton University"]}, {"name": "Hannes Mohrschladt", "affiliations": ["University of Potsdam Faculty of Economics and Social Sciences and University of M\u00fcnster Finance Center M\u00fcnster"]}], "abstract": "Abstract Retail investor contrarian selling depends on whether a position is at a gain or a loss. Selling propensity increases in daily returns for positions with unrealized gains (contrarian selling) and decreases in returns for loss positions (trend-following selling). This pattern is consistent with behavioral arguments that investors update their beliefs when stock prices move away from their purchase prices. In line with increased liquidity from contrarian selling, illiquid stocks exhibit weaker short-term reversals when investors have higher unrealized capital gains. Our findings diminish following stock splits, suggesting that unrealized capital gains are central to contrarian behavior, particularly when investors perceive them clearly.", "date": "2026-03-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102737", "title_zh": "\u9006\u6d41\u800c\u884c\uff1a\u6563\u6237\u7684\u53cd\u5411\u4ea4\u6613", "abstract_zh": "\u6458\u8981 \u6563\u6237\u6295\u8d44\u8005\u7684\u53cd\u5411\u5356\u51fa\u884c\u4e3a\u53d6\u51b3\u4e8e\u6301\u4ed3\u662f\u76c8\u5229\u8fd8\u662f\u4e8f\u635f\u3002\u5bf9\u4e8e\u5c1a\u672a\u5b9e\u73b0\u76c8\u5229\u7684\u5934\u5bf8\uff0c\u5f53\u6bcf\u65e5\u6536\u76ca\u7387\u4e0a\u5347\u65f6\uff0c\u5356\u51fa\u610f\u613f\u589e\u5f3a\uff08\u53cd\u5411\u5356\u51fa\uff09\uff1b\u800c\u5bf9\u4e8e\u4e8f\u635f\u5934\u5bf8\uff0c\u5f53\u6536\u76ca\u7387\u4e0a\u5347\u65f6\uff0c\u5356\u51fa\u610f\u613f\u51cf\u5f31\uff08\u8d8b\u52bf\u8ddf\u968f\u5356\u51fa\uff09\u3002\u8fd9\u4e00\u6a21\u5f0f\u4e0e\u884c\u4e3a\u91d1\u878d\u5b66\u89c2\u70b9\u4e00\u81f4\uff0c\u5373\u6295\u8d44\u8005\u5728\u80a1\u4ef7\u8fdc\u79bb\u4e70\u5165\u4ef7\u65f6\u4f1a\u66f4\u65b0\u5176\u4fe1\u5ff5\u3002\u4e0e\u53cd\u5411\u5356\u51fa\u5e26\u6765\u7684\u6d41\u52a8\u6027\u63d0\u5347\u76f8\u4e00\u81f4\uff0c\u5f53\u6295\u8d44\u8005\u6301\u6709\u8f83\u5927\u672a\u5b9e\u73b0\u8d44\u672c\u6536\u76ca\u65f6\uff0c\u6d41\u52a8\u6027\u8f83\u5dee\u7684\u80a1\u7968\u8868\u73b0\u51fa\u66f4\u5f31\u7684\u77ed\u671f\u53cd\u8f6c\u73b0\u8c61\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u524a\u5f31\u4e86\u5173\u4e8e\u80a1\u606f\u5206\u5272\u540e\u884c\u4e3a\u7684\u89e3\u91ca\uff0c\u8868\u660e\u672a\u5b9e\u73b0\u8d44\u672c\u6536\u76ca\u5728\u53cd\u5411\u4ea4\u6613\u884c\u4e3a\u4e2d\u8d77\u6838\u5fc3\u4f5c\u7528\uff0c\u5c24\u5176\u662f\u5728\u6295\u8d44\u8005\u80fd\u591f\u6e05\u6670\u611f\u77e5\u5230\u8fd9\u4e9b\u6536\u76ca\u65f6\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102592", "journal": "JFQA", "title": "Price Impact in Closing Auctions, Opening Auctions, and Continuous Markets: A Benchmark for Cost of Trading on Anomalies", "authors": ["Amit Goyal", "Narasimhan Jegadeesh", "Yanbin Wu"], "author_details": [{"name": "Amit Goyal", "affiliations": ["University of Lausanne Swiss Finance Institute"]}, {"name": "Narasimhan Jegadeesh", "affiliations": ["Emory University Goizueta Business School"]}, {"name": "Yanbin Wu", "affiliations": ["University of Florida Warrington College of Business"]}], "abstract": "Abstract Closing auctions account for about 10% of daily trading volume and offer a potentially attractive alternative to trading in the continuous market. We find that the price impact is lower in closing auctions than in the continuous market for all stocks except Nasdaq microcaps. Opening auctions are illiquid. We compute trading costs for anomalies based strategies by strategically placing orders in the lower cost mechanism. The annualized trading costs for long/short portfolios based on financial ratios such as profitability and investment range from 17 to 41 basis points (bps). Excluding microcaps, these costs fall to 9\u201321 bps in closing auctions.", "date": "2026-03-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102592", "title_zh": "\u6536\u76d8\u62cd\u5356\u3001\u5f00\u76d8\u62cd\u5356\u548c\u8fde\u7eed\u5e02\u573a\u4e2d\u7684\u4ef7\u683c\u5f71\u54cd\uff1a\u57fa\u4e8e\u5f02\u5e38\u4ea4\u6613\u7684\u4ea4\u6613\u6210\u672c\u57fa\u51c6", "abstract_zh": "\u6536\u76d8\u62cd\u5356\u5360\u6bcf\u65e5\u4ea4\u6613\u91cf\u7684\u7ea610%\uff0c\u53ef\u80fd\u6210\u4e3a\u8fde\u7eed\u5e02\u573a\u4ea4\u6613\u7684\u4e00\u4e2a\u6709\u5438\u5f15\u529b\u7684\u66ff\u4ee3\u9009\u62e9\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5bf9\u4e8e\u6240\u6709\u80a1\u7968\u800c\u8a00\uff0c\u6536\u76d8\u62cd\u5356\u7684\u4ef7\u683c\u5f71\u54cd\u5747\u4f4e\u4e8e\u8fde\u7eed\u5e02\u573a\uff0c\u552f\u72ec\u7eb3\u65af\u8fbe\u514b\u5fae\u5c0f\u516c\u53f8\u9664\u5916\u3002\u5f00\u76d8\u62cd\u5356\u6d41\u52a8\u6027\u8f83\u5dee\u3002\u6211\u4eec\u901a\u8fc7\u6218\u7565\u6027\u5730\u5728\u6210\u672c\u8f83\u4f4e\u7684\u673a\u5236\u4e2d\u4e0b\u5355\uff0c\u8ba1\u7b97\u57fa\u4e8e\u5f02\u5e38\u7b56\u7565\u7684\u4ea4\u6613\u6210\u672c\u3002\u57fa\u4e8e\u76c8\u5229\u80fd\u529b\u3001\u6295\u8d44\u7b49\u8d22\u52a1\u6bd4\u7387\u6784\u5efa\u7684\u591a\u7a7a\u7ec4\u5408\u7684\u5e74\u5316\u4ea4\u6613\u6210\u672c\u8303\u56f4\u4e3a17\u81f341\u57fa\u70b9\uff08bps\uff09\u3002\u6392\u9664\u5fae\u5c0f\u516c\u53f8\u540e\uff0c\u6536\u76d8\u62cd\u5356\u4e2d\u7684\u4ea4\u6613\u6210\u672c\u964d\u81f39\u81f321\u57fa\u70b9\uff08bps\uff09", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag018", "journal": "REStud", "title": "Identification of Time-Inconsistent Models: The Case of Insecticide-Treated Nets", "authors": ["Aprajit Mahajan", "Christian Michel", "Alessandro Tarozzi"], "author_details": [{"name": "Aprajit Mahajan", "affiliations": ["Dept. of Agricultural and Resource Economics, UC Berkeley ,"]}, {"name": "Christian Michel", "affiliations": ["Barcelona School of Economics ,"]}, {"name": "Alessandro Tarozzi", "affiliations": ["Department of Economics, European University Institute , ; , ; and CEPR", "Universitat Pompeu Fabra and Barcelona School of Economics , ; , ; and CEPR"]}], "abstract": "Abstract Time-inconsistency may play a central role in explaining inter-temporal behaviour, particularly among poor households. However, little is known about the distribution of time-inconsistent agents, and time-preference parameters are typically not identified in standard dynamic choice models. We formulate a dynamic discrete choice model in an unobservedly heterogeneous population of possibly time-inconsistent agents. We provide conditions under which all population type probabilities and preferences for both time-consistent and sophisticated agents are point-identified and sharp set-identification results for na\u00efve and partially sophisticated agents. Estimating the model using data from a health intervention providing insecticide-treated nets (ITNs) in rural Odisha, India, we find that about two-thirds of our sample comprises time-inconsistent agents and that both sophisticated and na\u00efve agents are considerably present-biased. Counterfactuals show that the under-investment in ITNs attributable to present-bias leads to substantial costs that are about four times the price of an ITN.", "date": "2026-03-04", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag018", "title_zh": "\u65f6\u95f4\u4e0d\u4e00\u81f4\u6a21\u578b\u7684\u8bc6\u522b\uff1a\u4ee5\u6740\u866b\u7f51\u4e3a\u4f8b", "abstract_zh": "\u65f6\u95f4\u4e0d\u4e00\u81f4\u6027\u53ef\u80fd\u5728\u89e3\u91ca\u5bb6\u5ead\u8de8\u671f\u884c\u4e3a\uff0c\u5c24\u5176\u662f\u8d2b\u56f0\u5bb6\u5ead\u7684\u884c\u4e3a\u4e2d\u8d77\u6838\u5fc3\u4f5c\u7528\u3002\u7136\u800c\uff0c\u5173\u4e8e\u65f6\u95f4\u4e0d\u4e00\u81f4\u4e2a\u4f53\u7684\u5206\u5e03\u60c5\u51b5\u77e5\u4e4b\u751a\u5c11\uff0c\u4e14\u5728\u6807\u51c6\u52a8\u6001\u9009\u62e9\u6a21\u578b\u4e2d\uff0c\u65f6\u95f4\u504f\u597d\u53c2\u6570\u901a\u5e38\u65e0\u6cd5\u88ab\u8bc6\u522b\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5728\u672a\u89c2\u6d4b\u5230\u7684\u5f02\u8d28\u6027\u4eba\u7fa4\u4e2d\u5305\u542b\u53ef\u80fd\u65f6\u95f4\u4e0d\u4e00\u81f4\u4e2a\u4f53\u7684\u52a8\u6001\u79bb\u6563\u9009\u62e9\u6a21\u578b\u3002\u6211\u4eec\u63d0\u4f9b\u4e86\u6240\u6709\u7fa4\u4f53\u7c7b\u578b\u6982\u7387\u4ee5\u53ca\u65f6\u95f4\u4e00\u81f4\u548c\u7cbe\u660e\u65f6\u95f4\u4e0d\u4e00\u81f4\u4e2a\u4f53\u504f\u597d\u80fd\u591f\u70b9\u8bc6\u522b\u7684\u6761\u4ef6\uff0c\u5e76\u5bf9\u5929\u771f\u548c\u90e8\u5206\u7cbe\u660e\u7684\u4e2a\u4f53\u7ed9\u51fa\u4e86\u7cbe\u786e\u7684\u96c6\u5408\u8bc6\u522b\u7ed3\u679c\u3002\u5229\u7528\u6765\u81ea\u5370\u5ea6\u5965\u91cc\u8428\u90a6\u519c\u6751\u5730\u533a\u4e00\u9879\u63d0\u4f9b\u6740\u866b\u7f51\uff08ITNs\uff09\u5065\u5eb7\u5e72\u9884\u9879\u76ee\u7684\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u6837\u672c\u4e2d\u7ea6\u6709\u4e09\u5206\u4e4b\u4e8c\u7684\u4e2a\u4f53\u5c5e\u4e8e\u65f6\u95f4\u4e0d\u4e00\u81f4\u8005\uff0c\u4e14\u5929\u771f\u548c\u90e8\u5206\u7cbe\u660e\u7684\u4e2a\u4f53\u5747\u8868\u73b0\u51fa\u660e\u663e\u7684\u73b0\u65f6\u504f\u597d\u3002\u53cd\u4e8b\u5b9e\u5206\u6790\u8868\u660e\uff0c\u7531\u4e8e\u73b0\u65f6\u504f\u597d\u7684\u5b58\u5728\u5bfc\u81f4\u6740\u866b\u7f51\u6295\u8d44\u4e0d\u8db3\uff0c\u6240\u9020\u6210\u7684\u6210\u672c\u7ea6\u4e3a\u6740\u866b\u7f51\u4ef7\u683c\u7684\u56db\u500d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag017", "journal": "REStud", "title": "Optimal Decision Rules When Payoffs are Partially Identified", "authors": ["Timothy Christensen", "Hyungsik Roger Moon", "Frank Schorfheide"], "author_details": [{"name": "Timothy Christensen", "affiliations": ["Yale University ,"]}, {"name": "Hyungsik Roger Moon", "affiliations": ["University of Southern California ,"]}, {"name": "Frank Schorfheide", "affiliations": ["University of Pennsylvania ,"]}], "abstract": "Abstract We derive asymptotically optimal statistical decision rules for discrete choice problems when payoffs depend on a partially-identified parameter \u03b8 and the decision maker can use a point-identified parameter \u03bc to deduce restrictions on \u03b8. Examples include treatment choice under partial identification and pricing with rich unobserved heterogeneity. Our notion of optimality combines a minimax approach to handle the ambiguity from partial identification of \u03b8 given \u03bc with an average risk minimization approach for \u03bc. We show how to implement optimal decision rules using the bootstrap and (quasi-)Bayesian methods in both parametric and semiparametric settings. We provide detailed applications to treatment choice and optimal pricing. Our asymptotic approach is well suited for realistic empirical settings in which the derivation of finite-sample optimal rules is intractable.", "date": "2026-03-02", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag017", "title_zh": "\u5f53\u6536\u76ca\u90e8\u5206\u8bc6\u522b\u65f6\u7684\u6700\u4f18\u51b3\u7b56\u89c4\u5219", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u4e3a\u79bb\u6563\u9009\u62e9\u95ee\u9898\u63a8\u5bfc\u4e86\u5728\u6536\u76ca\u4f9d\u8d56\u4e8e\u90e8\u5206\u8bc6\u522b\u7684\u53c2\u6570\u03b8\u4e14\u51b3\u7b56\u8005\u53ef\u4ee5\u5229\u7528\u4e00\u4e2a\u70b9\u8bc6\u522b\u7684\u53c2\u6570\u03bc\u6765\u63a8\u65ad\u03b8\u7684\u9650\u5236\u6761\u4ef6\u4e0b\uff0c\u6e10\u8fd1\u6700\u4f18\u7684\u7edf\u8ba1\u51b3\u7b56\u89c4\u5219\u3002\u4f8b\u5b50\u5305\u62ec\u5728\u90e8\u5206\u8bc6\u522b\u4e0b\u7684\u6cbb\u7597\u9009\u62e9\u4ee5\u53ca\u5728\u5b58\u5728\u4e30\u5bcc\u672a\u89c2\u6d4b\u5f02\u8d28\u6027\u60c5\u51b5\u4e0b\u7684\u5b9a\u4ef7\u3002\u6211\u4eec\u5bf9\u6700\u4f18\u6027\u7684\u5b9a\u4e49\u7ed3\u5408\u4e86\u6700\u5c0f\u6700\u5927\u65b9\u6cd5\u4ee5\u5904\u7406\u03b8\u7684\u90e8\u5206\u8bc6\u522b\u5e26\u6765\u7684\u4e0d\u786e\u5b9a\u6027\uff0c\u4ee5\u53ca\u9488\u5bf9\u03bc\u7684\u5e73\u5747\u98ce\u9669\u6700\u5c0f\u5316\u65b9\u6cd5\u3002\u6211\u4eec\u5c55\u793a\u4e86\u5982\u4f55\u5728\u53c2\u6570\u548c\u534a\u53c2\u6570\u8bbe\u5b9a\u4e0b\uff0c\u5229\u7528\u81ea\u52a9\u6cd5\u548c\uff08\u51c6\uff09\u8d1d\u53f6\u65af\u65b9\u6cd5\u6765\u5b9e\u73b0\u6700\u4f18\u51b3\u7b56\u89c4\u5219\u3002\u6211\u4eec\u63d0\u4f9b\u4e86\u6cbb\u7597\u9009\u62e9\u548c\u6700\u4f18\u5b9a\u4ef7\u7684\u8be6\u7ec6\u5e94\u7528\u3002\u6211\u4eec\u7684\u6e10\u8fd1\u65b9\u6cd5\u9002\u7528\u4e8e\u73b0\u5b9e\u4e2d\u7684\u7ecf\u9a8c\u7814\u7a76\u573a\u666f\uff0c\u5728\u8fd9\u4e9b\u573a\u666f\u4e2d\uff0c\u63a8\u5bfc\u6709\u9650\u6837\u672c\u6700\u4f18\u89c4\u5219\u662f\u4e0d\u53ef\u884c\u7684\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20221703", "journal": "AER", "title": "Why Is Workplace Sexual Harassment Underreported? The Value of Outside Options amid the Threat of Retaliation", "authors": ["Gordon B. Dahl", "Matthew Knepper"], "author_details": [{"name": "Gordon B. Dahl", "affiliations": ["UC San Diego, NBER, ifo Institute, CESifo, IZA, CEPR, RFBerlin (email: )"]}, {"name": "Matthew Knepper", "affiliations": ["Amazon (email: )"]}], "abstract": "Why is workplace sexual harassment chronically underreported? We hypothesize that employers coerce victims into silence through the threat of a retaliatory firing. To test this, we estimate how two external shocks that reduce workers\u2019 outside options\u2014unemployment rate increases and sharp cuts to unemployment insurance benefits\u2014affect the selectivity of sexual harassment charges filed with the Equal Employment Opportunity Commission. We find that both shocks increase selectivity, which implies an increase in underreporting. Bolstering these findings, anonymous Google searches for \u201csexual harassment in the workplace\u201d (total prevalence) spike relative to charges filed (reported prevalence) during the Great Recession. (JEL J71, J78)", "date": "2026-03-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20221703", "title_zh": "\u4e3a\u4ec0\u4e48\u804c\u573a\u6027\u9a9a\u6270\u88ab\u4f4e\u4f30\uff1f\u5728\u9762\u4e34\u62a5\u590d\u5a01\u80c1\u65f6\u5916\u90e8\u9009\u62e9\u7684\u4ef7\u503c", "abstract_zh": "\u4e3a\u4ec0\u4e48\u804c\u573a\u6027\u9a9a\u6270\u957f\u671f\u88ab\u4f4e\u4f30\uff1f\u6211\u4eec\u5047\u8bbe\u96c7\u4e3b\u901a\u8fc7\u5a01\u80c1\u5bf9\u53d7\u5bb3\u8005\u8fdb\u884c\u62a5\u590d\u6027\u89e3\u96c7\u6765\u8feb\u4f7f\u53d7\u5bb3\u8005\u4fdd\u6301\u6c89\u9ed8\u3002\u4e3a\u4e86\u68c0\u9a8c\u8fd9\u4e00\u5047\u8bbe\uff0c\u6211\u4eec\u5206\u6790\u4e86\u4e24\u79cd\u5916\u90e8\u51b2\u51fb\u2014\u2014\u5931\u4e1a\u7387\u4e0a\u5347\u548c\u5931\u4e1a\u4fdd\u9669\u798f\u5229\u5927\u5e45\u524a\u51cf\u2014\u2014\u5982\u4f55\u5f71\u54cd\u5411\u5e73\u7b49\u5c31\u4e1a\u673a\u4f1a\u59d4\u5458\u4f1a\u63d0\u4ea4\u7684\u6027\u9a9a\u6270\u6307\u63a7\u7684\u9009\u62e9\u6027\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u4e24\u79cd\u51b2\u51fb\u90fd\u4f1a\u589e\u52a0\u9009\u62e9\u6027\uff0c\u8fd9\u610f\u5473\u7740\u4e3e\u62a5\u7387\u4e0b\u964d\uff0c\u5373\u6027\u9a9a\u6270\u88ab\u4f4e\u4f30\u3002\u8fd9\u4e9b\u53d1\u73b0\u5f97\u5230\u4e86\u8fdb\u4e00\u6b65\u652f\u6301\uff1a\u5728\u5927\u8427\u6761\u671f\u95f4\uff0c\u5bf9\u201c\u804c\u573a\u6027\u9a9a\u6270\u201d\uff08\u603b\u4f53\u53d1\u751f\u7387\uff09\u7684\u533f\u540d\u8c37\u6b4c\u641c\u7d22\u6570\u91cf\u76f8\u5bf9\u4e8e\u5b9e\u9645\u63d0\u4ea4\u7684\u6307\u63a7\uff08\u62a5\u544a\u53d1\u751f\u7387\uff09\u663e\u8457\u4e0a\u5347\u3002\uff08JEL J71\uff0cJ78\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20211601", "journal": "AER", "title": "Immigration, Innovation, and Growth", "authors": ["Stephen J. Terry", "Thomas Chaney", "Konrad B. Burchardi", "Lisa Tarquinio", "Tarek A. Hassan"], "author_details": [{"name": "Stephen J. Terry", "affiliations": ["University of Michigan and NBER (email: )"]}, {"name": "Thomas Chaney", "affiliations": ["University of Southern California, Sciences Po, and CEPR (email: )"]}, {"name": "Konrad B. Burchardi", "affiliations": ["Institute for International Economic Studie (email: )"]}, {"name": "Lisa Tarquinio", "affiliations": ["University of Western Ontario (email: )"]}, {"name": "Tarek A. Hassan", "affiliations": ["Boston University, NBER, and CEPR (email: )"]}], "abstract": "We propose a novel identification strategy to isolate exogenous immigration shocks across US counties, by interacting quasi-random variations in the composition of ancestry across counties with the contemporaneous inflow of migrants from different countries. We show a positive causal impact of immigration on local innovation and wages at the five-year horizon. The positive dynamic impact of immigration on innovation and wages dominates the short-run negative impact of increased labor supply. A structural estimation of a model of endogenous growth and migrations suggests the increased immigration to the United States since 1965 may have increased innovation and wages by 5 percent. (JEL J15, J22, J31, J61, O31, R11, R23)", "date": "2026-03-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20211601", "title_zh": "\u79fb\u6c11\u3001\u521b\u65b0\u4e0e\u589e\u957f", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u65b0\u7684\u8bc6\u522b\u7b56\u7565\uff0c\u901a\u8fc7\u5c06\u7f8e\u56fd\u5404\u53bf\u65cf\u88d4\u6784\u6210\u7684\u51c6\u968f\u673a\u53d8\u5316\u4e0e\u4e0d\u540c\u56fd\u5bb6\u79fb\u6c11\u7684\u540c\u671f\u6d41\u5165\u76f8\u7ed3\u5408\uff0c\u6765\u5206\u79bb\u5916\u751f\u7684\u79fb\u6c11\u51b2\u51fb\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u79fb\u6c11\u5bf9\u672c\u5730\u521b\u65b0\u548c\u5de5\u8d44\u5728\u4e94\u5e74\u65f6\u95f4\u8303\u56f4\u5185\u5177\u6709\u6b63\u5411\u56e0\u679c\u5f71\u54cd\u3002\u79fb\u6c11\u5bf9\u521b\u65b0\u548c\u5de5\u8d44\u7684\u52a8\u6001\u6b63\u5411\u5f71\u54cd\u8d85\u8fc7\u4e86\u77ed\u671f\u5185\u52b3\u52a8\u529b\u4f9b\u7ed9\u589e\u52a0\u5e26\u6765\u7684\u8d1f\u5411\u5f71\u54cd\u3002\u5bf9\u5185\u751f\u589e\u957f\u548c\u79fb\u6c11\u6a21\u578b\u7684\u7ed3\u6784\u4f30\u8ba1\u8868\u660e\uff0c\u81ea1965\u5e74\u4ee5\u6765\u7f8e\u56fd\u79fb\u6c11\u589e\u52a0\u53ef\u80fd\u4f7f\u521b\u65b0\u548c\u5de5\u8d44\u63d0\u9ad8\u4e865\u4e2a\u767e\u5206\u70b9\u3002(JEL J15, J22, J31, J61, O31, R11, R23)", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20250278", "journal": "AER", "title": "The Value of Clean Water: Experimental Evidence from Rural India", "authors": ["Fiona Burlig", "Amir Jina", "Anant Sudarshan"], "author_details": [{"name": "Fiona Burlig", "affiliations": ["Harris School of Public Policy and Energy Policy Institute (EPIC) (email: )"]}, {"name": "Amir Jina", "affiliations": ["Harris School of Public Policy and EPIC, University of Chicago, and NBER (email: )"]}, {"name": "Anant Sudarshan", "affiliations": ["Department of Economics, University of Warwick (email: )"]}], "abstract": "Over 2 billion people lack clean drinking water. Existing solutions face high costs (piped water) or low demand (point-of-use chlorine). Using a 60,000 household cluster-randomized experiment, we test an alternative approach: decentralized treatment and home delivery of clean water to the rural poor. At low prices, take-up exceeds 90 percent, sustained throughout the experiment. High prices reduce take-up but are privately profitable. We experimentally recover revealed-preference measures of valuation. Willingness-to-pay is several times higher than prior indirect estimates; willingness-to-accept is larger and exceeds marginal cost. Self-reported health measures improve accordingly. On a cost-per-DALY basis, free water delivery regimes appear highly cost effective. (JEL I12, O12, O13, O18, Q25, Q51, Q53)", "date": "2026-03-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20250278", "title_zh": "\u6e05\u6d01\u6c34\u7684\u4ef7\u503c\uff1a\u6765\u81ea\u5370\u5ea6\u519c\u6751\u7684\u5b9e\u9a8c\u8bc1\u636e", "abstract_zh": "\u5168\u7403\u6709\u8d85\u8fc720\u4ebf\u4eba\u7f3a\u4e4f\u6e05\u6d01\u996e\u7528\u6c34\u3002\u73b0\u6709\u89e3\u51b3\u65b9\u6848\u8981\u4e48\u6210\u672c\u9ad8\u6602\uff08\u7ba1\u9053\u4f9b\u6c34\uff09\uff0c\u8981\u4e48\u9700\u6c42\u4e0d\u8db3\uff08\u70b9\u6e90\u6c2f\u5316\uff09\u3002\u6211\u4eec\u901a\u8fc7\u4e00\u9879\u6d89\u53ca6\u4e07\u6237\u5bb6\u5ead\u7684\u96c6\u7fa4\u968f\u673a\u5b9e\u9a8c\uff0c\u6d4b\u8bd5\u4e86\u4e00\u79cd\u66ff\u4ee3\u65b9\u6848\uff1a\u5c06\u6e05\u6d01\u6c34\u4ee5\u5206\u6563\u5316\u65b9\u5f0f\u5e76\u76f4\u63a5\u9001\u5230\u519c\u6751\u8d2b\u56f0\u4eba\u53e3\u5bb6\u4e2d\u3002\u5728\u4f4e\u4ef7\u60c5\u51b5\u4e0b\uff0c\u63a5\u53d7\u7387\u8d85\u8fc790%\uff0c\u4e14\u5728\u6574\u4e2a\u5b9e\u9a8c\u671f\u95f4\u4fdd\u6301\u7a33\u5b9a\u3002\u9ad8\u4ef7\u4f1a\u964d\u4f4e\u63a5\u53d7\u7387\uff0c\u4f46\u5bf9\u4e2a\u4eba\u800c\u8a00\u4ecd\u662f\u76c8\u5229\u7684\u3002\u6211\u4eec\u901a\u8fc7\u5b9e\u9a8c\u6062\u590d\u4e86\u6d88\u8d39\u8005\u504f\u597d\u6d4b\u5ea6\u3002\u6d88\u8d39\u8005\u613f\u610f\u652f\u4ed8\u7684\u4ef7\u683c\u662f\u4ee5\u5f80\u95f4\u63a5\u4f30\u8ba1\u7684\u6570\u500d\uff1b\u6d88\u8d39\u8005\u613f\u610f\u63a5\u53d7\u7684\u4ef7\u683c\u66f4\u9ad8\uff0c\u5e76\u8d85\u8fc7\u8fb9\u9645\u6210\u672c\u3002\u81ea\u6211\u62a5\u544a\u7684\u5065\u5eb7\u72b6\u51b5\u76f8\u5e94\u6539\u5584\u3002\u4ece\u6bcfDALY\u6210\u672c\u6765\u770b\uff0c\u514d\u8d39\u4f9b\u6c34\u65b9\u6848\u663e\u5f97\u9ad8\u5ea6\u6210\u672c\u6709\u6548\u3002\uff08JEL I12, O12, O13, O18, Q25, Q51, Q53\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20230309", "journal": "AER", "title": "Sequential Cursed Equilibrium", "authors": ["Shani Cohen", "Shengwu Li"], "author_details": [{"name": "Shani Cohen", "affiliations": ["Hebrew University (email: )"]}, {"name": "Shengwu Li", "affiliations": ["Harvard University (email: )"]}], "abstract": "We propose an extensive-form solution concept, with players who neglect information from hypothetical events but make inferences from observed events. Our concept modifies cursed equilibrium (Eyster and Rabin 2005) and allows that players can be cursed about endogenous information. (JEL C73, D44, D71, D81, D83, D91)", "date": "2026-03-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230309", "title_zh": "\u987a\u5e8f\u8bc5\u5492\u5747\u8861", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u6269\u5c55\u5f62\u5f0f\u7684\u5747\u8861\u6982\u5ff5\uff0c\u5176\u4e2d\u73a9\u5bb6\u5ffd\u89c6\u6765\u81ea\u5047\u8bbe\u4e8b\u4ef6\u7684\u4fe1\u606f\uff0c\u4f46\u4f1a\u4ece\u89c2\u5bdf\u5230\u7684\u4e8b\u4ef6\u4e2d\u8fdb\u884c\u63a8\u65ad\u3002\u8be5\u6982\u5ff5\u4fee\u6539\u4e86\u8bc5\u5492\u5747\u8861\uff08Eyster\u548cRabin\uff0c2005\uff09\uff0c\u5e76\u5141\u8bb8\u73a9\u5bb6\u5bf9\u5185\u751f\u4fe1\u606f\u4ea7\u751f\u8bc5\u5492\u3002\uff08JEL C73\uff0cD44\uff0cD71\uff0cD81\uff0cD83\uff0cD91\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20230832", "journal": "AER", "title": "Equal Pay for Similar Work", "authors": ["Diego Gentile Passaro", "Fuhito Kojima", "Bobak Pakzad-Hurson"], "author_details": [{"name": "Diego Gentile Passaro", "affiliations": ["Amazon Science (email: )"]}, {"name": "Fuhito Kojima", "affiliations": ["Department of Economics, University of Tokyo (email: )"]}, {"name": "Bobak Pakzad-Hurson", "affiliations": ["Department of Economics, Brown University (email: )"]}], "abstract": "Equal pay laws increasingly require that workers with different group identities doing \u201csimilar\u201d work are paid equal wages within firm. We study such \u201cequal pay for similar work\u201d (EPSW) policies theoretically and test our models\u2019 predictions empirically using evidence from a 2009 gender-based Chilean EPSW. Under EPSW, firms segregate their workforce by gender. When there are more men than women in a labor market, EPSW increases the gender wage gap. (JEL J16, J31, J38, K31, O15)", "date": "2026-03-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230832", "title_zh": "\u540c\u5de5\u540c\u916c", "abstract_zh": "\u540c\u5de5\u540c\u916c\u6cd5\u5f8b\u65e5\u76ca\u8981\u6c42\uff0c\u5728\u4e0d\u540c\u7fa4\u4f53\u8eab\u4efd\u7684\u52b3\u52a8\u8005\u4ece\u4e8b\u2018\u76f8\u4f3c\u2019\u5de5\u4f5c\u65f6\uff0c\u4f01\u4e1a\u5fc5\u987b\u5728\u5185\u90e8\u652f\u4ed8\u540c\u7b49\u5de5\u8d44\u3002\u6211\u4eec\u4ece\u7406\u8bba\u4e0a\u7814\u7a76\u4e86\u6b64\u7c7b\u2018\u540c\u5de5\u540c\u916c\u2019\uff08EPSW\uff09\u653f\u7b56\uff0c\u5e76\u5229\u75282009\u5e74\u57fa\u4e8e\u6027\u522b\u7684\u667a\u5229\u540c\u5de5\u540c\u916c\u6848\u4f8b\u6570\u636e\uff0c\u5bf9\u6a21\u578b\u9884\u6d4b\u8fdb\u884c\u5b9e\u8bc1\u68c0\u9a8c\u3002\u5728\u540c\u5de5\u540c\u916c\u653f\u7b56\u4e0b\uff0c\u4f01\u4e1a\u4f1a\u6309\u6027\u522b\u5bf9\u52b3\u52a8\u529b\u8fdb\u884c\u5206\u9694\u3002\u5f53\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u7537\u6027\u591a\u4e8e\u5973\u6027\u65f6\uff0c\u540c\u5de5\u540c\u916c\u653f\u7b56\u4f1a\u6269\u5927\u6027\u522b\u5de5\u8d44\u5dee\u8ddd\u3002\uff08JEL J16, J31, J38, K31, O15\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240692", "journal": "AER", "title": "Zero-Sum Thinking and the Roots of US Political Differences", "authors": ["Sahil Chinoy", "Nathan Nunn", "Sandra Sequeira", "Stefanie Stantcheva"], "author_details": [{"name": "Sahil Chinoy", "affiliations": ["Harvard University (email: )"]}, {"name": "Nathan Nunn", "affiliations": ["University of British Columbia and CIFAR (email: )"]}, {"name": "Sandra Sequeira", "affiliations": ["London School of Economics (email: )"]}, {"name": "Stefanie Stantcheva", "affiliations": ["Harvard University (email: )"]}], "abstract": "We investigate the origins and implications of zero-sum thinking: the belief that gains for one individual or group tend to come at the cost of others. Using a new survey of 20,400 US residents, we measure zero-sum thinking, political preferences, policy views, and a rich array of ancestral information spanning four generations. We find that a more zero-sum mindset is strongly associated with more support for government redistribution, race- and gender-based affirmative action, and more restrictive immigration policies. Zero-sum thinking can be traced back to the experiences of both the individual and their ancestors, encompassing factors such as the degree of intergenerational upward mobility they experienced, whether they immigrated to the United States or lived in a location with more immigrants, and whether they were enslaved or lived in a location with more enslavement. (JEL C83, D72, D91, H23, J15, J16, Z13)", "date": "2026-03-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240692", "title_zh": "\u96f6\u548c\u601d\u7ef4\u4e0e\u7f8e\u56fd\u653f\u6cbb\u5206\u6b67\u7684\u6839\u6e90", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u96f6\u548c\u601d\u7ef4\u7684\u8d77\u6e90\u53ca\u5176\u5f71\u54cd\uff1a\u5373\u8ba4\u4e3a\u67d0\u4e2a\u4eba\u6216\u7fa4\u4f53\u7684\u6536\u76ca\u5f80\u5f80\u4ee5\u4ed6\u4eba\u635f\u5931\u4e3a\u4ee3\u4ef7\u3002\u57fa\u4e8e\u5bf920,400\u540d\u7f8e\u56fd\u5c45\u6c11\u7684\u65b0\u8c03\u67e5\uff0c\u6211\u4eec\u6d4b\u91cf\u4e86\u96f6\u548c\u601d\u7ef4\u3001\u653f\u6cbb\u504f\u597d\u3001\u653f\u7b56\u89c2\u70b9\u4ee5\u53ca\u8de8\u8d8a\u56db\u4ee3\u7684\u4e30\u5bcc\u7956\u5148\u4fe1\u606f\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u96f6\u548c\u601d\u7ef4\u7a0b\u5ea6\u8d8a\u5f3a\uff0c\u8d8a\u652f\u6301\u653f\u5e9c\u518d\u5206\u914d\u3001\u57fa\u4e8e\u79cd\u65cf\u548c\u6027\u522b\u7684\u4eba\u4e8b\u4f18\u5f85\u653f\u7b56\uff0c\u4ee5\u53ca\u66f4\u4e25\u683c\u7684\u79fb\u6c11\u653f\u7b56\u3002\u96f6\u548c\u601d\u7ef4\u53ef\u4ee5\u8ffd\u6eaf\u5230\u4e2a\u4f53\u53ca\u5176\u7956\u5148\u7684\u7ecf\u5386\uff0c\u5305\u62ec\u4ed6\u4eec\u6240\u7ecf\u5386\u7684\u4ee3\u9645\u5411\u4e0a\u6d41\u52a8\u7a0b\u5ea6\u3001\u662f\u5426\u79fb\u6c11\u5230\u7f8e\u56fd\u6216\u5c45\u4f4f\u5728\u79fb\u6c11\u8f83\u591a\u7684\u5730\u533a\uff0c\u4ee5\u53ca\u662f\u5426\u66fe\u88ab\u5974\u5f79\u6216\u751f\u6d3b\u5728\u5974\u5f79\u8f83\u591a\u7684\u5730\u533a\u3002\uff08JEL C83, D72, D91, H23, J15, J16, Z13\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240513", "journal": "AER", "title": "Dynamics of the Long-Term Housing Yield: Evidence from Natural Experiments", "authors": ["Ver\u00f3nica B\u00e4cker-Peral", "Jonathon Hazell", "Atif Mian"], "author_details": [{"name": "Ver\u00f3nica B\u00e4cker-Peral", "affiliations": ["Princeton (email: )"]}, {"name": "Jonathon Hazell", "affiliations": ["London School of Economics (email: )"]}, {"name": "Atif Mian", "affiliations": ["Princeton and NBER (email: )"]}], "abstract": "Each month, a fraction of UK property leases are extended by 90 years or more. We construct a new dataset using thousands of these natural experiments since 2000 and estimate the expected long-term housing yield, y * . After remaining steady at around 5 percent, y * starts to decline when the Great Recession hits and reaches a low of 2.7 percent in 2024. The decline is steeper in inelastic markets, while y * remains higher in regions more exposed to long-run climate risk. Our estimate of y * is updated in real time using public data. (JEL E32, G12, Q54, R31, R38)", "date": "2026-03-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240513", "title_zh": "\u957f\u671f\u4f4f\u623f\u6536\u76ca\u7387\u7684\u52a8\u529b\u5b66\uff1a\u6765\u81ea\u81ea\u7136\u5b9e\u9a8c\u7684\u8bc1\u636e", "abstract_zh": "\u6bcf\u6708\uff0c\u82f1\u56fd\u90e8\u5206\u623f\u4ea7\u79df\u8d41\u5408\u540c\u4f1a\u88ab\u5ef6\u957f90\u5e74\u6216\u66f4\u4e45\u3002\u6211\u4eec\u5229\u7528\u81ea2000\u5e74\u4ee5\u6765\u6570\u5343\u4e2a\u6b64\u7c7b\u81ea\u7136\u5b9e\u9a8c\u6784\u5efa\u4e86\u4e00\u4e2a\u65b0\u6570\u636e\u96c6\uff0c\u5e76\u4f30\u8ba1\u4e86\u9884\u671f\u957f\u671f\u4f4f\u623f\u6536\u76ca\u7387y*\u3002\u5728Great Recession\u53d1\u751f\u524d\uff0cy*\u4e00\u76f4\u7a33\u5b9a\u5728\u7ea65%\u7684\u6c34\u5e73\uff0c\u6b64\u540e\u5f00\u59cb\u4e0b\u964d\uff0c\u52302024\u5e74\u964d\u81f32.7%\u3002\u5728\u9700\u6c42\u5f39\u6027\u8f83\u4f4e\u7684\u5e02\u573a\u4e2d\uff0cy*\u7684\u4e0b\u964d\u66f4\u4e3a\u5267\u70c8\uff0c\u800c\u5728\u957f\u671f\u66b4\u9732\u4e8e\u6c14\u5019\u98ce\u9669\u7684\u5730\u533a\uff0cy*\u5219\u4fdd\u6301\u8f83\u9ad8\u6c34\u5e73\u3002\u6211\u4eec\u7684y*\u4f30\u8ba1\u503c\u5229\u7528\u516c\u5f00\u6570\u636e\u5b9e\u65f6\u66f4\u65b0\u3002\uff08JEL E32, G12, Q54, R31, R38\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20241355", "journal": "AER", "title": "The Price of War", "authors": ["Jonathan Federle", "Andr\u00e9 Meier", "Gernot J. M\u00fcller", "Willi Mutschler", "Moritz Schularick"], "author_details": [{"name": "Jonathan Federle", "affiliations": ["Kiel Institute (email: )"]}, {"name": "Andr\u00e9 Meier", "affiliations": ["Tudor Capital Europe LLP (email: )"]}, {"name": "Gernot J. M\u00fcller", "affiliations": ["Department of Economics, University of T\u00fcbingen, CEPR, and CESifo (email: )"]}, {"name": "Willi Mutschler", "affiliations": ["Department of Economics, University of T\u00fcbingen, and Dynare Team (email: )"]}, {"name": "Moritz Schularick", "affiliations": ["Kiel Institute, Sciences Po, and CEPR (email: )"]}], "abstract": "We assemble a new dataset spanning 150 years and 60 countries to study the economic toll of war. A war of average intensity is associated with an output drop of close to 10 percent in the war-site economy, while consumer prices rise by approximately 20 percent. The capital stock, total factor productivity, and equity returns all decline sharply. The economic ramifications of war are not confined to the war site. The evidence points to adverse economic outcomes in other belligerent and third-party countries if they are exposed to the war site through trade linkages or share a common border. (JEL D74, E23, E32, F43, F51, N40)", "date": "2026-03-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20241355", "title_zh": "\u6218\u4e89\u7684\u4ef7\u683c", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6db5\u76d6150\u5e74\u548c60\u4e2a\u56fd\u5bb6\u7684\u65b0\u6570\u636e\u96c6\uff0c\u4ee5\u7814\u7a76\u6218\u4e89\u7684\u7ecf\u6d4e\u4ee3\u4ef7\u3002\u5e73\u5747\u5f3a\u5ea6\u7684\u6218\u4e89\u4f1a\u4f7f\u6218\u533a\u7ecf\u6d4e\u4f53\u7684\u4ea7\u51fa\u4e0b\u964d\u8fd110\u4e2a\u767e\u5206\u70b9\uff0c\u6d88\u8d39\u8005\u4ef7\u683c\u4e0a\u5347\u7ea620\u4e2a\u767e\u5206\u70b9\u3002\u8d44\u672c\u5b58\u91cf\u3001\u5168\u8981\u7d20\u751f\u4ea7\u7387\u548c\u80a1\u7968\u56de\u62a5\u5747\u663e\u8457\u4e0b\u964d\u3002\u6218\u4e89\u7684\u7ecf\u6d4e\u5f71\u54cd\u4e0d\u4ec5\u9650\u4e8e\u6218\u533a\u3002\u8bc1\u636e\u8868\u660e\uff0c\u5982\u679c\u5176\u4ed6\u56fd\u5bb6\u901a\u8fc7\u8d38\u6613\u8054\u7cfb\u6216\u5171\u4eab\u8fb9\u5883\u63a5\u89e6\u5230\u6218\u533a\uff0c\u4e5f\u4f1a\u9762\u4e34\u4e0d\u5229\u7684\u7ecf\u6d4e\u540e\u679c\u3002\uff08JEL D74, E23, E32, F43, F51, N40\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20220749", "journal": "AER", "title": "Temporary Layoffs, Loss-of-Recall, and Cyclical Unemployment Dynamics", "authors": ["Mark Gertler", "Christopher Huckfeldt", "Antonella Trigari"], "author_details": [{"name": "Mark Gertler", "affiliations": ["New York University and NBER (email: )"]}, {"name": "Christopher Huckfeldt", "affiliations": ["Board of Governors of the Federal Reserve System (email: )"]}, {"name": "Antonella Trigari", "affiliations": ["Bocconi University, CEPR, and IGIER (email: )"]}], "abstract": "We revisit the role of temporary layoffs in the business cycle. While some have emphasized a stabilizing effect due to recall hiring, we quantify from the data an important countercyclical destabilizing effect due to \u201closs-of-recall,\u201d whereby workers in temporary-layoff unemployment lose their job permanently. We develop a quantitative model allowing for endogenous flows of workers across employment and both temporary-layoff and jobless unemployment. The model captures both pre- and post-pandemic unemployment dynamics, including the contractionary role of loss-of-recall. We use our structural model to show that the Paycheck Protection Program generated sizable employment gains, in part by significantly reducing loss-of-recall. (JEL E24, E32, I12, J41, J63, J64)", "date": "2026-03-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20220749", "title_zh": "\u4e34\u65f6\u88c1\u5458\u3001\u5931\u4e1a\u8bb0\u5fc6\u4e27\u5931\u4e0e\u5468\u671f\u6027\u5931\u4e1a\u52a8\u6001", "abstract_zh": "\u6211\u4eec\u91cd\u65b0\u5ba1\u89c6\u4e86\u4e34\u65f6\u88c1\u5458\u5728\u5546\u4e1a\u5468\u671f\u4e2d\u7684\u4f5c\u7528\u3002\u5c3d\u7ba1\u4e00\u4e9b\u7814\u7a76\u5f3a\u8c03\u4e86\u7531\u4e8e\u91cd\u65b0\u96c7\u7528\u800c\u4ea7\u751f\u7684\u7a33\u5b9a\u6548\u5e94\uff0c\u4f46\u6211\u4eec\u4ece\u6570\u636e\u4e2d\u91cf\u5316\u4e86\u4e00\u4e2a\u91cd\u8981\u7684\u9006\u5468\u671f\u7834\u574f\u6027\u6548\u5e94\uff0c\u5373\u5904\u4e8e\u4e34\u65f6\u88c1\u5458\u5931\u4e1a\u72b6\u6001\u7684\u5de5\u4eba\u4f1a\u6c38\u4e45\u5931\u53bb\u5de5\u4f5c\u673a\u4f1a\uff08\u5373\u2018\u5931\u4e1a\u8bb0\u5fc6\u4e27\u5931\u2019\uff09\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u80fd\u591f\u5185\u751f\u5316\u5de5\u4eba\u5728\u5c31\u4e1a\u72b6\u6001\u4e4b\u95f4\u6d41\u52a8\u7684\u91cf\u5316\u6a21\u578b\uff0c\u6db5\u76d6\u4e34\u65f6\u88c1\u5458\u5931\u4e1a\u4e0e\u65e0\u4e1a\u5931\u4e1a\u4e4b\u95f4\u7684\u8f6c\u6362\u3002\u8be5\u6a21\u578b\u80fd\u591f\u89e3\u91ca\u75ab\u60c5\u524d\u548c\u75ab\u60c5\u540e\u7684\u5931\u4e1a\u52a8\u6001\uff0c\u5305\u62ec\u2018\u5931\u4e1a\u8bb0\u5fc6\u4e27\u5931\u2019\u7684\u6536\u7f29\u6027\u4f5c\u7528\u3002\u6211\u4eec\u5229\u7528\u8be5\u7ed3\u6784\u6a21\u578b\u8868\u660e\uff0c\u6551\u63f4\u652f\u7968\u4fdd\u62a4\u8ba1\u5212\u5e26\u6765\u4e86\u663e\u8457\u7684\u5c31\u4e1a\u589e\u957f\uff0c\u90e8\u5206\u539f\u56e0\u5728\u4e8e\u663e\u8457\u964d\u4f4e\u4e86\u2018\u5931\u4e1a\u8bb0\u5fc6\u4e27\u5931\u2019\u7684\u53d1\u751f\u7387\u3002\uff08JEL E24, E32, I12, J41, J63, J64\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20250053", "journal": "AER", "title": "What You Don\u2019t Know May Be Good for You", "authors": ["Johannes H\u00f6rner", "Larry Samuelson"], "author_details": [{"name": "Johannes H\u00f6rner", "affiliations": ["CNRS, Toulouse-Capitole (email: )"]}, {"name": "Larry Samuelson", "affiliations": ["Yale University (email: )"]}], "abstract": "We consider an economy in which long-lived experts are matched with short-lived clients. Experts choose the type of client with whom they match, unobserved by the market. The interaction outcome depends on both the expert\u2019s and the client\u2019s type. We study the effects of supplying information about otherwise unobservable outcomes, such as \u201cmedical report cards,\u201d to help clients identify better experts. Such information can lead to inefficient matches, as experts reject risky clients to build their reputation. Hence, information can reduce welfare. Withholding information can mitigate these perverse incentives at the cost of misallocating experts known to be inept. (JEL C78, D82, D83)", "date": "2026-03-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20250053", "title_zh": "\u4f60\u4e0d\u77e5\u9053\u7684\u53ef\u80fd\u5bf9\u4f60\u6709\u76ca", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e00\u4e2a\u957f\u671f\u4e13\u5bb6\u4e0e\u77ed\u671f\u5ba2\u6237\u5339\u914d\u7684\u7ecf\u6d4e\u73af\u5883\u3002\u4e13\u5bb6\u9009\u62e9\u4e0e\u4e4b\u5339\u914d\u7684\u5ba2\u6237\u7c7b\u578b\uff0c\u8fd9\u4e00\u884c\u4e3a\u5bf9\u5e02\u573a\u800c\u8a00\u662f\u4e0d\u53ef\u89c2\u6d4b\u7684\u3002\u4e92\u52a8\u7ed3\u679c\u53d6\u51b3\u4e8e\u4e13\u5bb6\u548c\u5ba2\u6237\u7684\u7c7b\u578b\u3002\u6211\u4eec\u8003\u5bdf\u4e86\u5411\u5ba2\u6237\u62ab\u9732\u539f\u672c\u4e0d\u53ef\u89c2\u6d4b\u7684\u7ed3\u679c\uff08\u5982\"\u533b\u7597\u62a5\u544a\u5361\"\uff09\u6240\u5e26\u6765\u7684\u5f71\u54cd\uff0c\u4ee5\u5e2e\u52a9\u5ba2\u6237\u8bc6\u522b\u66f4\u4f18\u79c0\u7684\u4e13\u5bb6\u3002\u6b64\u7c7b\u4fe1\u606f\u53ef\u80fd\u5bfc\u81f4\u4f4e\u6548\u5339\u914d\uff0c\u56e0\u4e3a\u4e13\u5bb6\u4e3a\u4e86\u5efa\u7acb\u58f0\u8a89\u800c\u62d2\u7edd\u98ce\u9669\u8f83\u9ad8\u7684\u5ba2\u6237\u3002\u56e0\u6b64\uff0c\u4fe1\u606f\u53ef\u80fd\u964d\u4f4e\u6574\u4f53\u798f\u5229\u3002\u9690\u7792\u4fe1\u606f\u53ef\u4ee5\u7f13\u89e3\u8fd9\u4e9b\u626d\u66f2\u7684\u6fc0\u52b1\uff0c\u4f46\u4ee3\u4ef7\u662f\u5c06\u672c\u5e94\u8868\u73b0\u4e0d\u4f73\u7684\u4e13\u5bb6\u9519\u914d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag011", "journal": "REStud", "title": "Jumpstarting an International Currency", "authors": ["Saleem Bahaj", "Ricardo Reis"], "author_details": [{"name": "Saleem Bahaj", "affiliations": ["University College London ,"]}, {"name": "Ricardo Reis", "affiliations": ["London School of Economics ,"]}], "abstract": "Abstract While the USD dominates cross-border transactions today, a few other currencies are also used internationally. This paper shows that central bank policies that reduce the volatility of borrowing costs for foreign firms in domestic currency can trigger a jumpstart of the currency\u2019s international status, because firms\u2019 choices of the currency of their working capital complement their sales invoicing. Empirically, the creation of swap lines by the People\u2019s Bank of China between 2009 and 2018 supports this theoretical claim. Signing a swap line with a country is associated with an increase in the probability that the country would use the RMB at all by 12%, and a four-fold increase in the value of the country\u2019s RMB payments.", "date": "2026-02-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag011", "title_zh": "\u542f\u52a8\u4e00\u79cd\u56fd\u9645\u8d27\u5e01", "abstract_zh": "\u5c3d\u7ba1\u7f8e\u5143\u76ee\u524d\u4e3b\u5bfc\u8de8\u5883\u4ea4\u6613\uff0c\u4f46\u5c11\u6570\u5176\u4ed6\u8d27\u5e01\u4e5f\u88ab\u7528\u4e8e\u56fd\u9645\u4ea4\u6613\u3002\u672c\u6587\u8868\u660e\uff0c\u4e2d\u592e\u94f6\u884c\u901a\u8fc7\u964d\u4f4e\u5916\u56fd\u4f01\u4e1a\u5728\u672c\u56fd\u8d27\u5e01\u4e2d\u501f\u6b3e\u6210\u672c\u7684\u6ce2\u52a8\u6027\u800c\u5236\u5b9a\u7684\u653f\u7b56\uff0c\u53ef\u4ee5\u63a8\u52a8\u8be5\u8d27\u5e01\u56fd\u9645\u5730\u4f4d\u7684\u8fc5\u901f\u63d0\u5347\uff0c\u56e0\u4e3a\u4f01\u4e1a\u5bf9\u5de5\u4f5c\u8d44\u672c\u7684\u8d27\u5e01\u9009\u62e9\u4e0e\u5176\u9500\u552e\u53d1\u7968\u8d27\u5e01\u76f8\u4e92\u8865\u3002\u5b9e\u8bc1\u7814\u7a76\u8868\u660e\uff0c\u4e2d\u56fd\u4eba\u6c11\u94f6\u884c\u57282009\u5e74\u81f32018\u5e74\u95f4\u5efa\u7acb\u7684\u5916\u6c47\u4e92\u6362\u5b89\u6392\u652f\u6301\u4e86\u8fd9\u4e00\u7406\u8bba\u89c2\u70b9\u3002\u4e0e\u67d0\u56fd\u7b7e\u8ba2\u5916\u6c47\u4e92\u6362\u5b89\u6392\uff0c\u4f1a\u4f7f\u8be5\u56fd\u4f7f\u7528\u4eba\u6c11\u5e01\u7684\u6982\u7387\u63d0\u9ad812%\uff0c\u4e14\u8be5\u56fd\u4eba\u6c11\u5e01\u652f\u4ed8\u989d\u589e\u52a0\u56db\u500d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag013", "journal": "QJE", "title": "Trust and Innovation Within the Firm: Evidence from Matched CEO-Firm Data", "authors": ["Kieu-Trang Nguyen"], "author_details": [{"name": "Kieu-Trang Nguyen", "affiliations": ["University of Melbourne ,"]}], "abstract": "Abstract This article shows that a CEO\u2019s trust enhances innovation within a firm, providing a novel micro-foundation for the well-known trust-growth relationship. I build a new matched CEO-firm-patent data set covering 5,753 CEOs in 3,598 U.S. public firms and 700,000 patents during 2000\u20132011. I exploit variation in generalized trust across CEO ethnic origins, inferred from their last names using deanonymized historical censuses. Following CEO turnovers, a one standard deviation increase in a CEO\u2019s generalized trust is associated with 6% more future patents and 4%\u20136% higher average patent quality, driven entirely by higher-quality patents. Text analysis of employee reviews shows that the CEO\u2019s trust enhances a firm\u2019s trust culture. These results are consistent with insights from qualitative interviews suggesting that the CEO's trust and the firm\u2019s trust culture encourage researchers to undertake high-risk explorative research and development. In addition, changes in the CEO\u2019s bilateral trust toward inventors in different countries have comparable effects on inventors\u2019 patenting, controlling for CEO and other fixed effects.", "date": "2026-02-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag013", "title_zh": "\u4fe1\u4efb\u4e0e\u4f01\u4e1a\u521b\u65b0\uff1a\u6765\u81ea\u5339\u914dCEO-\u4f01\u4e1a\u6570\u636e\u7684\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u8868\u660e\uff0cCEO\u7684\u4e2a\u4eba\u4fe1\u4efb\u80fd\u591f\u4fc3\u8fdb\u4f01\u4e1a\u5185\u7684\u521b\u65b0\uff0c\u4e3a\u4f17\u6240\u5468\u77e5\u7684\u4fe1\u4efb\u4e0e\u6210\u957f\u5173\u7cfb\u63d0\u4f9b\u4e86\u65b0\u7684\u5fae\u89c2\u57fa\u7840\u3002\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u65b0\u7684\u5339\u914dCEO-\u4f01\u4e1a-\u4e13\u5229\u6570\u636e\u96c6\uff0c\u6db5\u76d62000\u5e74\u81f32011\u5e74\u95f43598\u5bb6\u7f8e\u56fd\u4e0a\u5e02\u516c\u53f8\u4e2d\u76845753\u540dCEO\u548c700\u4e07\u9879\u4e13\u5229\u3002\u6211\u5229\u7528CEO\u7684\u65cf\u88d4\u80cc\u666f\u4e2d\u63a8\u65ad\u51fa\u7684\u5e7f\u4e49\u4fe1\u4efb\u6c34\u5e73\uff08\u901a\u8fc7\u89e3\u533f\u540d\u5316\u7684\u5386\u53f2\u4eba\u53e3\u666e\u67e5\u6570\u636e\u4e2d\u7684\u59d3\u6c0f\u8fdb\u884c\u63a8\u65ad\uff09\uff0c\u53d1\u73b0CEO\u66f4\u66ff\u540e\uff0cCEO\u5e7f\u4e49\u4fe1\u4efb\u6bcf\u589e\u52a0\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u5176\u672a\u6765\u4e13\u5229\u6570\u91cf\u5c06\u589e\u52a06%\uff0c\u5e73\u5747\u4e13\u5229\u8d28\u91cf\u63d0\u9ad84%\u81f36%\uff0c\u8fd9\u4e00\u6548\u5e94\u5b8c\u5168\u7531\u9ad8\u8d28\u91cf\u4e13\u5229\u9a71\u52a8\u3002\u5bf9\u5458\u5de5\u8bc4\u4ef7\u7684\u6587\u672c\u5206\u6790\u663e\u793a\uff0cCEO\u7684\u4e2a\u4eba\u4fe1\u4efb\u6709\u52a9\u4e8e\u63d0\u5347\u4f01\u4e1a\u6574\u4f53\u7684\u4fe1\u4efb\u6587\u5316\u3002\u8fd9\u4e9b\u7ed3\u679c\u4e0e\u5b9a\u6027\u8bbf\u8c08\u4e2d\u7684\u89c2\u70b9\u4e00\u81f4\uff0c\u5373CEO\u7684\u4fe1\u4efb\u4ee5\u53ca\u4f01\u4e1a\u4fe1\u4efb\u6587\u5316\u7684\u5efa\u7acb\uff0c\u4f1a\u9f13\u52b1\u7814\u7a76\u4eba\u5458\u5f00\u5c55\u9ad8\u98ce\u9669\u7684\u63a2\u7d22\u6027\u7814\u53d1\u6d3b\u52a8\u3002\u6b64\u5916\uff0c\u5728\u63a7\u5236CEO\u53ca\u5176\u4ed6\u56fa\u5b9a\u6548\u5e94\u540e\uff0cCEO\u5bf9\u4e0d\u540c\u56fd\u5bb6\u53d1\u660e\u4eba\u53cc\u8fb9\u4fe1\u4efb\u7684\u53d8\u5316\uff0c\u5bf9\u53d1\u660e\u4eba\u4e13\u5229\u7533\u8bf7\u7684\u5f71\u54cd\u4e0e\u4e4b\u76f8\u5f53\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790"]}, {"doi": "10.1093/qje/qjag014", "journal": "QJE", "title": "Complete Pass-Through in Levels", "authors": ["Kunal Sangani"], "author_details": [{"name": "Kunal Sangani", "affiliations": ["Northwestern University ,"]}], "abstract": "Abstract Empirical studies find that the pass-through of input cost changes to prices is incomplete: a 10% increase in costs causes downstream prices to rise less than 10%, even at long horizons. Using microdata from gas stations, food products, and manufacturing industries, I find that incomplete pass-through in percentages often disguises complete pass-through in levels: a $1/unit increase in input costs leads to $1/unit higher downstream prices. Pass-through appears incomplete in percentages due to a gap between prices and costs. Complete pass-through in levels contrasts with workhorse macroeconomic models that feature homothetic industry demand systems. I identify an alternative class of demand systems that yields pass-through in levels and highlight four implications. First, measuring pass-through in percentages can lead to spurious evidence of asymmetry and size dependence. Second, pass-through in levels leads to systematic fluctuations in relative price and markup dispersion that are not associated with changes in allocative efficiency. Third, pass-through in levels can explain dynamics of industry gross margins, operating profits, and entry in the data that are at odds with workhorse models. Finally, incorporating pass-through in levels into an input-output model of the U.S. economy better matches the volatility of consumer price inflation and the response of inflation to identified shocks.", "date": "2026-02-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag014", "title_zh": "\u6c34\u5e73\u4e0a\u7684\u5b8c\u5168\u4f20\u5bfc", "abstract_zh": "\u5b9e\u8bc1\u7814\u7a76\u53d1\u73b0\uff0c\u6295\u5165\u6210\u672c\u53d8\u5316\u5411\u4ef7\u683c\u7684\u4f20\u5bfc\u662f\u4e0d\u5b8c\u5168\u7684\uff1a\u6210\u672c\u4e0a\u534710%\u65f6\uff0c\u4e0b\u6e38\u4ef7\u683c\u7684\u6da8\u5e45\u5c0f\u4e8e10%\uff0c\u5373\u4f7f\u5728\u957f\u671f\u4e2d\u4e5f\u662f\u5982\u6b64\u3002\u5229\u7528\u52a0\u6cb9\u7ad9\u3001\u98df\u54c1\u4ea7\u54c1\u548c\u5236\u9020\u4e1a\u7684\u5fae\u89c2\u6570\u636e\uff0c\u6211\u53d1\u73b0\uff0c\u767e\u5206\u6bd4\u610f\u4e49\u4e0a\u7684\u4f20\u5bfc\u4e0d\u5b8c\u5168\u5f80\u5f80\u63a9\u76d6\u4e86\u6c34\u5e73\u4e0a\u7684\u5b8c\u5168\u4f20\u5bfc\uff1a\u6295\u5165\u6210\u672c\u6bcf\u589e\u52a01\u7f8e\u5143/\u5355\u4f4d\uff0c\u4e0b\u6e38\u4ef7\u683c\u4e5f\u76f8\u5e94\u63d0\u9ad81\u7f8e\u5143/\u5355\u4f4d\u3002\u767e\u5206\u6bd4\u610f\u4e49\u4e0a\u7684\u4f20\u5bfc\u4e0d\u5b8c\u5168\u6e90\u4e8e\u4ef7\u683c\u4e0e\u6210\u672c\u4e4b\u95f4\u7684\u5dee\u8ddd\u3002\u6c34\u5e73\u4e0a\u7684\u5b8c\u5168\u4f20\u5bfc\u4e0e\u4e3b\u6d41\u5b8f\u89c2\u7ecf\u6d4e\u6a21\u578b\u4e2d\u5047\u8bbe\u7684\u540c\u8d28\u6027\u884c\u4e1a\u9700\u6c42\u7cfb\u7edf\u76f8\u6096\u3002\u6211\u63d0\u51fa\u4e86\u4e00\u7c7b\u65b0\u7684\u9700\u6c42\u7cfb\u7edf\uff0c\u80fd\u591f\u5b9e\u73b0\u6c34\u5e73\u4e0a\u7684\u5b8c\u5168\u4f20\u5bfc\uff0c\u5e76\u6307\u51fa\u5176\u56db\u4e2a\u542b\u4e49\u3002\u9996\u5148\uff0c\u4ee5\u767e\u5206\u6bd4\u8861\u91cf\u4f20\u5bfc\u53ef\u80fd\u4ea7\u751f\u865a\u5047\u7684\u4e0d\u5bf9\u79f0\u6027\u548c\u89c4\u6a21\u4f9d\u8d56\u6027\u8bc1\u636e\u3002\u5176\u6b21\uff0c\u6c34\u5e73\u4e0a\u7684\u5b8c\u5168\u4f20\u5bfc\u4f1a\u5bfc\u81f4\u76f8\u5bf9\u4ef7\u683c\u548c\u5229\u6da6\u7387\u5206\u6563\u7684\u7cfb\u7edf\u6027\u6ce2\u52a8\uff0c\u8fd9\u4e9b\u6ce2\u52a8\u4e0e\u8d44\u6e90\u914d\u7f6e\u6548\u7387\u7684\u53d8\u5316\u65e0\u5173\u3002\u7b2c\u4e09\uff0c\u6c34\u5e73\u4e0a\u7684\u5b8c\u5168\u4f20\u5bfc\u53ef\u4ee5\u89e3\u91ca\u884c\u4e1a\u6bdb\u5229\u7387\u3001\u8fd0\u8425\u5229\u6da6\u4ee5\u53ca\u5e02\u573a\u8fdb\u5165\u7b49\u6570\u636e\u4e2d\u7684\u52a8\u6001\u73b0\u8c61\uff0c\u8fd9\u4e9b\u73b0\u8c61\u4e0e\u4e3b\u6d41\u6a21\u578b\u76f8\u77db\u76fe\u3002\u6700\u540e\uff0c\u5c06\u6c34\u5e73\u4e0a\u7684\u5b8c\u5168\u4f20\u5bfc\u7eb3\u5165\u7f8e\u56fd\u7ecf\u6d4e\u7684\u6295\u5165\u4ea7\u51fa\u6a21\u578b\uff0c\u80fd\u591f\u66f4\u597d\u5730\u5339\u914d\u6d88\u8d39\u8005\u4ef7\u683c\u901a\u80c0\u7684\u6ce2\u52a8\u6027\u4ee5\u53ca\u5bf9\u8bc6\u522b\u51fa\u7684\u51b2\u51fb\u7684\u53cd\u5e94\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1017/s0022109026102713", "journal": "JFQA", "title": "Housing Speculation and Investment in Children\u2019s Education: Evidence from House Purchase Restrictions in China", "authors": ["Geng Niu", "Xuefeng Xiang", "Liuming Yang", "Yang Zhou"], "author_details": [{"name": "Geng Niu", "affiliations": ["Southwestern University of Finance and Economics Research Institute of Economics and Management"]}, {"name": "Xuefeng Xiang", "affiliations": ["Southwestern University of Finance and Economics Research Institute of Economics and Management"]}, {"name": "Liuming Yang", "affiliations": ["The Chinese University of Hong Kong Business School"]}, {"name": "Yang Zhou", "affiliations": ["Wuhan University Economics and Management School"]}], "abstract": "Abstract Housing and human capital represent two major forms of household wealth. This article investigates the potential for housing speculation to crowd out household investment in children\u2019s education, an endeavor that only pays off in the long run. To address endogeneity concerns, we exploit the unintended spillover effect of staggered house purchase restrictions (HPR) in China. Using a difference-in-differences approach, we find that HPR reduce educational investment of households in nearby unregulated cities. We also provide evidence consistent with a housing speculation channel. These findings shed new light on the socioeconomic consequences of housing market booms.", "date": "2026-02-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102713", "title_zh": "\u4f4f\u623f\u6295\u673a\u4e0e\u5b50\u5973\u6559\u80b2\u6295\u8d44\uff1a\u6765\u81ea\u4e2d\u56fd\u8d2d\u623f\u9650\u5236\u7684\u8bc1\u636e", "abstract_zh": "\u4f4f\u623f\u4e0e\u4eba\u529b\u8d44\u672c\u662f\u5bb6\u5ead\u8d22\u5bcc\u7684\u4e24\u5927\u7ec4\u6210\u90e8\u5206\u3002\u672c\u6587\u63a2\u8ba8\u4e86\u4f4f\u623f\u6295\u673a\u53ef\u80fd\u6324\u51fa\u5bb6\u5ead\u5728\u5b50\u5973\u6559\u80b2\u4e0a\u7684\u6295\u8d44\uff0c\u800c\u8fd9\u79cd\u6295\u8d44\u53ea\u6709\u5728\u957f\u671f\u624d\u80fd\u83b7\u5f97\u56de\u62a5\u3002\u4e3a\u89e3\u51b3\u5185\u751f\u6027\u95ee\u9898\uff0c\u6211\u4eec\u5229\u7528\u4e2d\u56fd staggered house purchase restrictions\uff08HPR\uff09\u7684\u610f\u5916\u6ea2\u51fa\u6548\u5e94\u3002\u91c7\u7528\u5dee\u5206-\u5dee\u5206\u65b9\u6cd5\uff0c\u6211\u4eec\u53d1\u73b0HPR\u964d\u4f4e\u4e86\u90bb\u8fd1\u672a\u53d7\u76d1\u7ba1\u57ce\u5e02\u5bb6\u5ead\u7684\u6559\u80b2\u6295\u8d44\u3002\u6211\u4eec\u8fd8\u63d0\u4f9b\u4e86\u652f\u6301\u4f4f\u623f\u6295\u673a\u6e20\u9053\u7684\u8bc1\u636e\u3002\u8fd9\u4e9b\u53d1\u73b0\u4e3a\u4f4f\u623f\u5e02\u573a\u7e41\u8363\u7684\u7ecf\u6d4e\u793e\u4f1a\u540e\u679c\u63d0\u4f9b\u4e86\u65b0\u7684\u89c6\u89d2\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102658", "journal": "JFQA", "title": "Silencing Pollution: The Environmental Consequences of Anti-SLAPP Laws", "authors": ["Xikai Chen", "Jinjun (Ricky) Ke", "Yu Flora Kuang"], "author_details": [{"name": "Xikai Chen", "affiliations": ["California State University Fresno"]}, {"name": "Jinjun (Ricky) Ke", "affiliations": ["Xiamen University", "University of Technology Sydney"]}, {"name": "Yu Flora Kuang", "affiliations": ["The University of Melbourne", "Tilburg University"]}], "abstract": "Abstract We examine whether free-speech protections influence corporate environmental performance. Using the staggered enactment of U.S. anti-SLAPP statutes in a stacked difference-in-differences design from 1990 to 2019, we find that these laws significantly reduce firms\u2019 toxic emissions without curbing economic activity. Anti-SLAPP enactments also promote environmental investment through green innovation, abatement spending, and waste reduction management, and strengthen governance via improved sustainability oversight, ESG-linked executive pay, employee training, and supply chain management. The effects are stronger when stakeholder monitoring is stronger and when managerial incentives embed sustainability goals. Overall, free-speech protections generate powerful environmental benefits.", "date": "2026-02-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102658", "title_zh": "\u6c89\u9ed8\u6c61\u67d3\uff1a\u53cdSLAPP\u6cd5\u5f8b\u7684\u73af\u5883\u540e\u679c", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u8a00\u8bba\u81ea\u7531\u4fdd\u62a4\u662f\u5426\u4f1a\u5f71\u54cd\u4f01\u4e1a\u7684\u73af\u5883\u8868\u73b0\u3002\u5229\u75281990\u5e74\u81f32019\u5e74\u95f4\u7f8e\u56fd\u53cdSLAPP\u6cd5\u89c4\u5206\u9636\u6bb5\u5b9e\u65bd\u7684\u53e0\u52a0\u53cc\u91cd\u5dee\u5206\u8bbe\u8ba1\uff0c\u6211\u4eec\u53d1\u73b0\u8fd9\u4e9b\u6cd5\u5f8b\u663e\u8457\u964d\u4f4e\u4e86\u4f01\u4e1a\u7684\u6709\u6bd2\u6392\u653e\uff0c\u4e14\u5e76\u672a\u6291\u5236\u7ecf\u6d4e\u6d3b\u52a8\u3002\u53cdSLAPP\u6cd5\u89c4\u7684\u5b9e\u65bd\u8fd8\u901a\u8fc7\u7eff\u8272\u521b\u65b0\u3001\u51cf\u6392\u652f\u51fa\u548c\u5e9f\u7269\u51cf\u5c11\u7ba1\u7406\u4fc3\u8fdb\u4e86\u73af\u5883\u6295\u8d44\uff0c\u5e76\u901a\u8fc7\u6539\u5584\u53ef\u6301\u7eed\u6027\u76d1\u7763\u3001\u4e0eESG\u76f8\u5173\u7684\u9ad8\u7ba1\u85aa\u916c\u3001\u5458\u5de5\u57f9\u8bad\u4ee5\u53ca\u4f9b\u5e94\u94fe\u7ba1\u7406\u52a0\u5f3a\u4e86\u6cbb\u7406\u3002\u5f53\u5229\u76ca\u76f8\u5173\u8005\u76d1\u7763\u66f4\u5f3a\u4e14\u7ba1\u7406\u5c42\u6fc0\u52b1\u4e2d\u5305\u542b\u53ef\u6301\u7eed\u53d1\u5c55\u76ee\u6807\u65f6\uff0c\u8fd9\u4e9b\u6548\u5e94\u66f4\u4e3a\u663e\u8457\u3002\u603b\u4f53\u800c\u8a00\uff0c\u8a00\u8bba\u81ea\u7531\u4fdd\u62a4\u5e26\u6765\u4e86\u5f3a\u5927\u7684\u73af\u5883\u6548\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/qje/qjag012", "journal": "QJE", "title": "Monetary Policy and Sovereign Risk in Emerging Economies (NK-Default)", "authors": ["Cristina Arellano", "Yan Bai", "Gabriel Mihalache"], "author_details": [{"name": "Cristina Arellano", "affiliations": ["Federal Reserve Bank of Minneapolis and the University of Minnesota ,"]}, {"name": "Yan Bai", "affiliations": ["University of Rochester and the National Bureau of Economic Research, United States, The Chinese University of Hong Kong, Hong Kong, and The Centre for Economic Policy Research ,"]}, {"name": "Gabriel Mihalache", "affiliations": ["The Ohio State University ,"]}], "abstract": "Abstract This article develops a New Keynesian model with sovereign default risk. Inflation is set by forward-looking firms, monetary policy is an interest rate rule, and the fiscal government borrows externally, long-term, with an option to default. In this framework, default risk creates inflation pressures through an expectations channel, and tight monetary policy disincentivizes fiscal overborrowing. The model sheds light on temporary inflation events in emerging-market data: short-lived spikes in inflation, spreads, and domestic policy rates. As spreads rise, firms increase their prices in expectation of higher future inflation and low consumption during default. Monetary policy tightens, which reduces inflation and helps bring spreads down by disciplining government borrowing. These monetary-fiscal interactions imply that delivering the flexible-prices allocation may not be optimal for monetary policy.", "date": "2026-02-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag012", "title_zh": "\u8d27\u5e01\u653f\u7b56\u4e0e\u65b0\u5174\u7ecf\u6d4e\u4f53\u4e3b\u6743\u98ce\u9669\uff08NK-\u8fdd\u7ea6\uff09", "abstract_zh": "\u672c\u6587\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u4e3b\u6743\u8fdd\u7ea6\u98ce\u9669\u7684\u65b0\u51ef\u6069\u65af\u6a21\u578b\u3002\u901a\u80c0\u7531\u5177\u6709\u524d\u77bb\u6027\u7684\u4f01\u4e1a\u51b3\u5b9a\uff0c\u8d27\u5e01\u653f\u7b56\u91c7\u7528\u5229\u7387\u89c4\u5219\uff0c\u8d22\u653f\u653f\u5e9c\u957f\u671f\u5916\u503a\u878d\u8d44\uff0c\u5e76\u62e5\u6709\u8fdd\u7ea6\u9009\u62e9\u6743\u3002\u5728\u6b64\u6846\u67b6\u4e0b\uff0c\u8fdd\u7ea6\u98ce\u9669\u901a\u8fc7\u9884\u671f\u6e20\u9053\u5f15\u53d1\u901a\u80c0\u538b\u529b\uff0c\u7d27\u7f29\u7684\u8d27\u5e01\u653f\u7b56\u4f1a\u6291\u5236\u8d22\u653f\u8fc7\u5ea6\u4e3e\u503a\u3002\u8be5\u6a21\u578b\u6709\u52a9\u4e8e\u89e3\u91ca\u65b0\u5174\u5e02\u573a\u6570\u636e\u4e2d\u7684\u77ed\u671f\u901a\u80c0\u4e8b\u4ef6\uff1a\u77ed\u671f\u5185\u901a\u80c0\u3001\u5229\u5dee\u548c\u56fd\u5185\u653f\u7b56\u5229\u7387\u7684\u6025\u5267\u4e0a\u5347\u3002\u968f\u7740\u5229\u5dee\u6269\u5927\uff0c\u4f01\u4e1a\u9884\u671f\u672a\u6765\u901a\u80c0\u4e0a\u5347\u4ee5\u53ca\u8fdd\u7ea6\u671f\u95f4\u6d88\u8d39\u4e0b\u964d\uff0c\u56e0\u800c\u63d0\u9ad8\u4ef7\u683c\u3002\u8d27\u5e01\u653f\u7b56\u968f\u4e4b\u6536\u7d27\uff0c\u4ece\u800c\u964d\u4f4e\u901a\u80c0\uff0c\u5e76\u901a\u8fc7\u7ea6\u675f\u653f\u5e9c\u4e3e\u503a\u884c\u4e3a\u6765\u964d\u4f4e\u5229\u5dee\u3002\u8fd9\u4e9b\u8d27\u5e01\u653f\u7b56\u4e0e\u8d22\u653f\u653f\u7b56\u7684\u4e92\u52a8\u8868\u660e\uff0c\u5b9e\u73b0\u7075\u6d3b\u4ef7\u683c\u914d\u7f6e\u53ef\u80fd\u5e76\u975e\u8d27\u5e01\u653f\u7b56\u7684\u6700\u4f18\u76ee\u6807\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag003", "journal": "REStud", "title": "Selection in Surveys: Using Randomized Incentives to Detect and Account for Nonresponse Bias", "authors": ["Deniz Dutz", "Ingrid Huitfeldt", "Santiago Lacouture", "Magne Mogstad", "Alexander Torgovitsky", "Winnie van Dijk"], "author_details": [{"name": "Deniz Dutz", "affiliations": ["University of Chicago ,"]}, {"name": "Ingrid Huitfeldt", "affiliations": ["BI Norwegian Business School and Statistics Norway ,"]}, {"name": "Santiago Lacouture", "affiliations": ["University of Chicago ,"]}, {"name": "Magne Mogstad", "affiliations": ["University of Chicago and NBER, USA; Statistics Norway ,"]}, {"name": "Alexander Torgovitsky", "affiliations": ["University of Chicago ,"]}, {"name": "Winnie van Dijk", "affiliations": ["Yale University and NBER ,"]}], "abstract": "Abstract We show how to use randomized participation incentives to test and account for nonresponse bias in surveys. We first use data from a survey about labour market conditions, linked to full-population administrative data, to provide evidence of large differences in labour market outcomes between survey participants and nonparticipants, differences which would not be observable to an analyst who only has access to the survey data. These differences persist even after correcting for observable characteristics. We then use the randomized incentives in our survey to directly test for nonresponse bias and find evidence of substantial bias. Next, we apply a range of existing methods that account for nonresponse bias and find they produce bounds (or point estimates) that are either wide or far from the ground truth. We investigate the failure of these methods by taking a closer look at the determinants of participation, finding that the composition of participants changes in opposite directions in response to incentives and reminder emails. We develop a model of participation that allows for two dimensions of unobserved heterogeneity in the participation decision. Applying the model to our data produces bounds (or point estimates) that are narrower and closer to the ground truth than the other methods. Our results highlight the benefits of including randomized participation incentives in surveys. Both the testing procedure and the methods for bias adjustment may be attractive tools for researchers who are able to embed randomized incentives into their survey.", "date": "2026-02-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag003", "title_zh": "\u95ee\u5377\u8c03\u67e5\u4e2d\u7684\u9009\u62e9\u6027\u504f\u5dee\uff1a\u5229\u7528\u968f\u673a\u6fc0\u52b1\u68c0\u6d4b\u5e76\u4fee\u6b63\u975e\u54cd\u5e94\u504f\u5dee", "abstract_zh": "\u6211\u4eec\u5c55\u793a\u4e86\u5982\u4f55\u5229\u7528\u968f\u673a\u5316\u7684\u53c2\u4e0e\u6fc0\u52b1\u6765\u68c0\u9a8c\u5e76\u4fee\u6b63\u95ee\u5377\u4e2d\u7684\u975e\u54cd\u5e94\u504f\u5dee\u3002\u6211\u4eec\u9996\u5148\u5229\u7528\u4e00\u9879\u5173\u4e8e\u52b3\u52a8\u529b\u5e02\u573a\u72b6\u51b5\u7684\u8c03\u67e5\u6570\u636e\uff0c\u5e76\u5c06\u5176\u4e0e\u5168\u4eba\u53e3\u884c\u653f\u6570\u636e\u5173\u8054\uff0c\u53d1\u73b0\u53c2\u4e0e\u8005\u4e0e\u975e\u53c2\u4e0e\u8005\u4e4b\u95f4\u5b58\u5728\u663e\u8457\u7684\u52b3\u52a8\u529b\u5e02\u573a\u7ed3\u679c\u5dee\u5f02\uff0c\u8fd9\u4e9b\u5dee\u5f02\u65e0\u6cd5\u901a\u8fc7\u4ec5\u8bbf\u95ee\u8c03\u67e5\u6570\u636e\u7684\u5206\u6790\u4eba\u5458\u89c2\u5bdf\u5230\u3002\u5373\u4f7f\u5728\u63a7\u5236\u4e86\u53ef\u89c2\u6d4b\u7279\u5f81\u540e\uff0c\u8fd9\u4e9b\u5dee\u5f02\u4f9d\u7136\u5b58\u5728\u3002\u63a5\u7740\uff0c\u6211\u4eec\u5229\u7528\u8c03\u67e5\u4e2d\u8bbe\u7f6e\u7684\u968f\u673a\u6fc0\u52b1\u76f4\u63a5\u68c0\u9a8c\u975e\u54cd\u5e94\u504f\u5dee\uff0c\u53d1\u73b0\u5b58\u5728\u663e\u8457\u7684\u504f\u5dee\u3002\u968f\u540e\uff0c\u6211\u4eec\u5e94\u7528\u4e86\u4e00\u7cfb\u5217\u73b0\u6709\u7684\u4fee\u6b63\u975e\u54cd\u5e94\u504f\u5dee\u7684\u65b9\u6cd5\uff0c\u53d1\u73b0\u8fd9\u4e9b\u65b9\u6cd5\u4ea7\u751f\u7684\u7f6e\u4fe1\u533a\u95f4\uff08\u6216\u70b9\u4f30\u8ba1\u503c\uff09\u8981\u4e48\u975e\u5e38\u5bbd\u6cdb\uff0c\u8981\u4e48\u4e0e\u771f\u5b9e\u503c\u76f8\u5dee\u751a\u8fdc\u3002\u6211\u4eec\u901a\u8fc7\u6df1\u5165\u5206\u6790\u53c2\u4e0e\u51b3\u7b56\u7684\u5f71\u54cd\u56e0\u7d20\uff0c\u53d1\u73b0\u53c2\u4e0e\u8005\u7684\u6784\u6210\u5bf9\u6fc0\u52b1\u548c\u63d0\u9192\u90ae\u4ef6\u7684\u54cd\u5e94\u65b9\u5411\u76f8\u53cd\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u53c2\u4e0e\u51b3\u7b56\u7684\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u5141\u8bb8\u5b58\u5728\u4e24\u4e2a\u7ef4\u5ea6\u7684\u672a\u89c2\u6d4b\u5f02\u8d28\u6027\u3002\u5c06\u8be5\u6a21\u578b\u5e94\u7528\u4e8e\u6211\u4eec\u7684\u6570\u636e\u540e\uff0c\u5f97\u5230\u7684\u7f6e\u4fe1\u533a\u95f4\uff08\u6216\u70b9\u4f30\u8ba1\u503c\uff09\u6bd4\u5176\u4ed6\u65b9\u6cd5\u66f4\u7a84\uff0c\u4e14\u66f4\u63a5\u8fd1\u771f\u5b9e\u503c\u3002\u6211\u4eec\u7684\u7ed3\u679c\u5f3a\u8c03\u4e86\u5728\u95ee\u5377\u4e2d\u7eb3\u5165\u968f\u673a\u53c2\u4e0e\u6fc0\u52b1\u7684\u91cd\u8981\u6027\u3002\u65e0\u8bba\u662f\u68c0\u9a8c\u7a0b\u5e8f\u8fd8\u662f\u504f\u5dee\u4fee\u6b63\u65b9\u6cd5\uff0c\u90fd\u53ef\u80fd\u6210\u4e3a\u80fd\u591f\u5c06\u968f\u673a\u6fc0\u52b1\u5d4c\u5165\u8c03\u67e5\u7814\u7a76\u4e2d\u7684\u7814\u7a76\u4eba\u5458\u7684\u6709\u529b\u5de5\u5177\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.13495", "journal": "JF", "title": "The Benefits of Access: Evidence from Private Meetings with Portfolio Firms", "authors": ["MARCO BECHT", "JULIAN FRANKS", "HANNES F. WAGNER"], "author_details": [{"name": "MARCO BECHT", "affiliations": []}, {"name": "JULIAN FRANKS", "affiliations": []}, {"name": "HANNES F. WAGNER", "affiliations": []}], "abstract": "ABSTRACT We use large language models to analyze the content of 4,700 private meetings between a large active asset manager and its portfolio firms. The high\u2010level meetings convey mostly soft information about the firm, and little about industry or market. Fund manager meetings focus on business models and financial metrics, while governance specialist meetings focus on environmental, social, and governance risks; 0.4% of meetings discuss material nonpublic information. Trades by fund managers increase with meetings attended by senior management, rated as unusually good or bad, where the tone is significantly positive or negative, or assessed as creating consensus. Meeting\u2010informed portfolios can generate significant outperformance.", "date": "2026-02-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.13495", "title_zh": "\u83b7\u53d6\u7684\u76ca\u5904\uff1a\u6765\u81ea\u5bf9\u6295\u8d44\u7ec4\u5408\u516c\u53f8\u79c1\u4eba\u4f1a\u8bae\u7684\u8bc1\u636e", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u7528\u5927\u578b\u8bed\u8a00\u6a21\u578b\u5206\u6790\u4e86\u5927\u578b\u6d3b\u8dc3\u8d44\u4ea7\u7ba1\u7406\u516c\u53f8\u4e0e\u5176\u6295\u8d44\u7ec4\u5408\u516c\u53f8\u4e4b\u95f44700\u573a\u79c1\u4eba\u4f1a\u8bae\u7684\u5185\u5bb9\u3002\u9ad8\u5c42\u4f1a\u8bae\u4e3b\u8981\u4f20\u9012\u5173\u4e8e\u4f01\u4e1a\u7684\u8f6f\u4fe1\u606f\uff0c\u800c\u5173\u4e8e\u884c\u4e1a\u6216\u5e02\u573a\u7684\u4fe1\u606f\u5219\u8f83\u5c11\u3002\u57fa\u91d1\u7ecf\u7406\u7684\u4f1a\u8bae\u4fa7\u91cd\u4e8e\u5546\u4e1a\u6a21\u5f0f\u548c\u8d22\u52a1\u6307\u6807\uff0c\u800c\u6cbb\u7406\u4e13\u5bb6\u7684\u4f1a\u8bae\u5219\u4fa7\u91cd\u4e8e\u73af\u5883\u3001\u793e\u4f1a\u548c\u6cbb\u7406\u98ce\u9669\uff1b0.4%\u7684\u4f1a\u8bae\u6d89\u53ca\u91cd\u5927\u975e\u516c\u5f00\u4fe1\u606f\u3002\u57fa\u91d1\u7ecf\u7406\u7684\u4ea4\u6613\u91cf\u968f\u7740\u9ad8\u7ea7\u7ba1\u7406\u4eba\u5458\u51fa\u5e2d\u7684\u4f1a\u8bae\u6570\u91cf\u589e\u52a0\u3001\u4f1a\u8bae\u88ab\u8bc4\u4ef7\u4e3a\u5f02\u5e38\u597d\u6216\u5f02\u5e38\u5dee\u3001\u4f1a\u8bae\u8bed\u6c14\u663e\u8457\u79ef\u6781\u6216\u6d88\u6781\uff0c\u6216\u88ab\u8bc4\u4f30\u4e3a\u5f62\u6210\u5171\u8bc6\u800c\u589e\u52a0\u3002\u57fa\u4e8e\u4f1a\u8bae\u4fe1\u606f\u6784\u5efa\u7684\u6295\u8d44\u7ec4\u5408\u80fd\u591f\u5b9e\u73b0\u663e\u8457\u7684\u8d85\u989d\u6536\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "AI"]}, {"doi": "10.1093/restud/rdag012", "journal": "REStud", "title": "Do The Effects of Nudges Persist? Theory and Evidence from 38 Natural Field Experiments", "authors": ["Alec Brandon", "Paul J Ferraro", "John A List", "Robert D Metcalfe", "Michael K Price", "Florian Rundhammer"], "author_details": [{"name": "Alec Brandon", "affiliations": ["Johns Hopkins University ,"]}, {"name": "Paul J Ferraro", "affiliations": ["Johns Hopkins University ,"]}, {"name": "John A List", "affiliations": ["University of Chicago, ANU, & NBER ,"]}, {"name": "Robert D Metcalfe", "affiliations": ["Columbia University & NBER ,"]}, {"name": "Michael K Price", "affiliations": ["University of Alabama, ANU, RWI-Essen, & NBER ,"]}, {"name": "Florian Rundhammer", "affiliations": ["Georgia State University ,"]}], "abstract": "Abstract We formalize a research design to uncover the mechanisms underlying long-term reductions in energy consumption caused by a widely implemented nudge. We consider two channels: technology adoption and habit formation. Using data from 38 natural field experiments, we isolate the role of technology adoption by comparing treatment and control homes after the initial resident moves, which discontinues the treatment for a home. We find that fully half of energy reductions persist in the home after treatment ends and show this persistence is consonant with a technology adoption channel. The role of technology in creating persistent behaviour change has important implications for designing behavioural interventions and evaluating their long-term social impacts.", "date": "2026-02-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag012", "title_zh": "\u52a9\u63a8\u6548\u679c\u662f\u5426\u6301\u4e45\uff1f\u6765\u81ea38\u4e2a\u81ea\u7136\u573a\u5b9e\u9a8c\u7684\u7406\u8bba\u4e0e\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u6b63\u5f0f\u6784\u5efa\u4e86\u4e00\u79cd\u7814\u7a76\u8bbe\u8ba1\uff0c\u4ee5\u63ed\u793a\u5e7f\u6cdb\u5b9e\u65bd\u7684\u52a9\u63a8\u63aa\u65bd\u5bfc\u81f4\u957f\u671f\u80fd\u6e90\u6d88\u8017\u51cf\u5c11\u80cc\u540e\u7684\u673a\u5236\u3002\u6211\u4eec\u8003\u8651\u4e86\u4e24\u79cd\u6e20\u9053\uff1a\u6280\u672f\u91c7\u7eb3\u548c\u4e60\u60ef\u5f62\u6210\u3002\u5229\u7528\u6765\u81ea38\u4e2a\u81ea\u7136\u573a\u5b9e\u9a8c\u7684\u6570\u636e\uff0c\u6211\u4eec\u901a\u8fc7\u6bd4\u8f83\u5c45\u6c11\u642c\u79bb\u540e\u5904\u7406\u7ec4\u548c\u5bf9\u7167\u7ec4\u7684\u4f4f\u5b85\uff0c\u6765\u5206\u79bb\u6280\u672f\u91c7\u7eb3\u7684\u4f5c\u7528\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u4e00\u534a\u7684\u80fd\u6e90\u51cf\u5c11\u5728\u5904\u7406\u7ed3\u675f\u540e\u7684\u4f4f\u5b85\u4e2d\u4ecd\u7136\u6301\u7eed\uff0c\u8fd9\u4e00\u6301\u4e45\u6027\u4e0e\u6280\u672f\u91c7\u7eb3\u6e20\u9053\u4e00\u81f4\u3002\u6280\u672f\u5728\u4fc3\u6210\u6301\u4e45\u884c\u4e3a\u6539\u53d8\u65b9\u9762\u7684\u4f5c\u7528\uff0c\u5bf9\u8bbe\u8ba1\u884c\u4e3a\u5e72\u9884\u63aa\u65bd\u4ee5\u53ca\u8bc4\u4f30\u5176\u957f\u671f\u793e\u4f1a\u5f71\u54cd\u5177\u6709\u91cd\u8981\u610f\u4e49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhaf108", "journal": "RFS", "title": "Payment for Order Flow and Option Internalization", "authors": ["Thomas Ernst", "Chester Spatt"], "author_details": [{"name": "Thomas Ernst", "affiliations": ["Robert H. Smith School of Business, University of Maryland ,"]}, {"name": "Chester Spatt", "affiliations": ["Tepper School of Business, Carnegie Mellon University ,"]}], "abstract": "Abstract Option wholesalers specialize in purchasing and executing against retail option order flow. Orders are internalized via auctions (which provide price improvement) and the limit order book. Designated market makers (DMMs) have a key advantage in internalizing limit order book trades: they obtain the first five contracts of any order they bring to an exchange where they are a DMM. We exploit variation in DMM assignments and allocation rules to highlight how these rules create a barrier to entry in option wholesaling that does not exist for equity wholesaling, protecting wholesaler profits and high option PFOF.", "date": "2026-02-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf108", "title_zh": "\u8ba2\u5355\u6d41\u652f\u4ed8\u4e0e\u671f\u6743\u5185\u90e8\u5316", "abstract_zh": "\u671f\u6743\u6279\u53d1\u5546\u4e13\u95e8\u4ece\u4e8b\u8d2d\u4e70\u548c\u6267\u884c\u96f6\u552e\u671f\u6743\u8ba2\u5355\u6d41\u3002\u8ba2\u5355\u901a\u8fc7\u62cd\u5356\uff08\u63d0\u4f9b\u4ef7\u683c\u6539\u5584\uff09\u548c\u9650\u4ef7\u8ba2\u5355\u7c3f\u8fdb\u884c\u5185\u90e8\u5316\u3002\u6307\u5b9a\u5e02\u573a\u505a\u5e02\u5546\uff08DMM\uff09\u5728\u5185\u90e8\u5316\u9650\u4ef7\u8ba2\u5355\u7c3f\u4ea4\u6613\u65b9\u9762\u5177\u6709\u5173\u952e\u4f18\u52bf\uff1a\u5f53\u4ed6\u4eec\u5c06\u8ba2\u5355\u5e26\u5165\u4ea4\u6613\u6240\u5e76\u62c5\u4efbDMM\u65f6\uff0c\u53ef\u4ee5\u83b7\u5f97\u8be5\u8ba2\u5355\u524d\u4e94\u4e2a\u5408\u7ea6\u3002\u6211\u4eec\u5229\u7528\u6307\u5b9a\u5e02\u573a\u505a\u5e02\u5546\u5206\u914d\u548c\u5206\u914d\u89c4\u5219\u7684\u5dee\u5f02\uff0c\u63ed\u793a\u8fd9\u4e9b\u89c4\u5219\u5728\u671f\u6743\u6279\u53d1\u9886\u57df\u5f62\u6210\u4e86\u8fdb\u5165\u58c1\u5792\uff0c\u800c\u8fd9\u79cd\u58c1\u5792\u5728\u80a1\u7968\u6279\u53d1\u9886\u57df\u5e76\u4e0d\u5b58\u5728\uff0c\u4ece\u800c\u4fdd\u62a4\u4e86\u6279\u53d1\u5546\u7684\u5229\u6da6\u548c\u9ad8\u671f\u6743\u8ba2\u5355\u6d41\u652f\u4ed8\uff08PFOF\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag011", "journal": "QJE", "title": "The Macroeconomic Impact of Climate Change: Global Versus Local Temperature", "authors": ["Adrien Bilal", "Diego R K\u00e4nzig"], "author_details": [{"name": "Adrien Bilal", "affiliations": ["Stanford University, National Bureau of Economic Research, United States; Centre for Economic Policy Research ,"]}, {"name": "Diego R K\u00e4nzig", "affiliations": ["Northwestern University, National Bureau of Economic Research, United States; Centre for Economic Policy Research ,"]}], "abstract": "Abstract This article estimates that the macroeconomic damages from climate change are an order of magnitude larger than previously thought. Exploiting natural global temperature variability, we find that 1\u00baC warming reduces world GDP by over 20% in the long run. Global temperature correlates strongly with extreme climatic events, unlike country-level temperature used in previous work, explaining our larger estimate. We use this evidence to estimate damage functions in a neoclassical growth model. Business-as-usual warming implies a present welfare loss of more than 30%, and a social cost of carbon in excess of $1,200 per ton. These impacts suggest that unilateral decarbonization policy is cost-effective for large countries such as the United States.", "date": "2026-02-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag011", "title_zh": "\u6c14\u5019\u53d8\u5316\u7684\u5b8f\u89c2\u7ecf\u6d4e\u5f71\u54cd\uff1a\u5168\u7403\u6e29\u5ea6\u4e0e\u5c40\u90e8\u6e29\u5ea6\u7684\u6bd4\u8f83", "abstract_zh": "\u672c\u6587\u4f30\u8ba1\uff0c\u6c14\u5019\u53d8\u5316\u5e26\u6765\u7684\u5b8f\u89c2\u7ecf\u6d4e\u635f\u5bb3\u6bd4\u4ee5\u5f80\u8ba4\u4e3a\u7684\u8981\u5927\u4e00\u4e2a\u6570\u91cf\u7ea7\u3002\u5229\u7528\u81ea\u7136\u5168\u7403\u6e29\u5ea6\u7684\u6ce2\u52a8\u6027\uff0c\u6211\u4eec\u53d1\u73b0\u6c14\u6e29\u4e0a\u53471\u00baC\u5728\u957f\u671f\u5185\u4f1a\u4f7f\u5168\u7403GDP\u4e0b\u964d\u8d85\u8fc720%\u3002\u5168\u7403\u6e29\u5ea6\u4e0e\u6781\u7aef\u6c14\u5019\u4e8b\u4ef6\u9ad8\u5ea6\u76f8\u5173\uff0c\u800c\u4ee5\u5f80\u7814\u7a76\u4e2d\u4f7f\u7528\u7684\u662f\u56fd\u5bb6\u5c42\u9762\u7684\u6e29\u5ea6\u6570\u636e\uff0c\u8fd9\u89e3\u91ca\u4e86\u6211\u4eec\u5f97\u51fa\u7684\u66f4\u5927\u4f30\u8ba1\u503c\u3002\u6211\u4eec\u57fa\u4e8e\u8fd9\u4e00\u8bc1\u636e\uff0c\u5728\u65b0\u53e4\u5178\u589e\u957f\u6a21\u578b\u4e2d\u4f30\u8ba1\u4e86\u635f\u5bb3\u51fd\u6570\u3002\u5728\u4e1a\u52a1\u7167\u5e38\u5347\u6e29\u60c5\u666f\u4e0b\uff0c\u5f53\u524d\u798f\u5229\u635f\u5931\u8d85\u8fc730%\uff0c\u793e\u4f1a\u78b3\u6210\u672c\u8d85\u8fc7\u6bcf\u54281200\u7f8e\u5143\u3002\u8fd9\u4e9b\u5f71\u54cd\u8868\u660e\uff0c\u5bf9\u4e8e\u50cf\u7f8e\u56fd\u8fd9\u6837\u7684\u5927\u56fd\u800c\u8a00\uff0c\u5355\u8fb9\u53bb\u78b3\u5316\u653f\u7b56\u662f\u6210\u672c\u6548\u76ca\u9ad8\u7684\u9009\u62e9\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhaf027", "journal": "RFS", "title": "When Do Judges Throw the Book at Companies? The Influence of Partisanship in Corporate Prosecutions", "authors": ["Todd A Gormley", "Mahsa Kaviani", "Hosein I Maleki"], "author_details": [{"name": "Todd A Gormley", "affiliations": ["Washington University in St. Louis ,"]}, {"name": "Mahsa Kaviani", "affiliations": ["University of Delaware ,"]}, {"name": "Hosein I Maleki", "affiliations": ["Rutgers University ,"]}], "abstract": "Abstract We document that judges\u2019 political affiliations are strongly associated with the level of judicial penalties levied against companies. For example, Republican-appointed judges impose larger fines for hiring illegal immigrants, while Democrat-appointed judges impose larger fines for pollution- and environment-related violations. Time-series variation suggests that political partisanship, not fixed ideological differences, drives these findings. The differences become amplified when higher-court judicial vacancies exist and in the months before national elections. Our findings highlight the importance of political polarization for U.S. companies and illustrate how judicial composition can affect firms\u2019 incentive to avoid violating laws connected to partisan issues.", "date": "2026-02-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf027", "title_zh": "\u6cd5\u5b98\u4f55\u65f6\u5bf9\u4e0a\u5e02\u516c\u53f8\u4e25\u60e9\uff1f\u653f\u6cbb\u7acb\u573a\u5728\u4f01\u4e1a\u6267\u6cd5\u4e2d\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u6cd5\u5b98\u7684\u653f\u6cbb\u503e\u5411\u4e0e\u5176\u5bf9\u4f01\u4e1a\u65bd\u52a0\u7684\u53f8\u6cd5\u5904\u7f5a\u7a0b\u5ea6\u5bc6\u5207\u76f8\u5173\u3002\u4f8b\u5982\uff0c\u7531\u5171\u548c\u515a\u4efb\u547d\u7684\u6cd5\u5b98\u5728\u5904\u7406\u96c7\u4f63\u975e\u6cd5\u79fb\u6c11\u6848\u4ef6\u65f6\u65bd\u52a0\u7684\u7f5a\u6b3e\u66f4\u9ad8\uff0c\u800c\u7531\u6c11\u4e3b\u515a\u4efb\u547d\u7684\u6cd5\u5b98\u5728\u5904\u7406\u6c61\u67d3\u53ca\u73af\u5883\u76f8\u5173\u8fdd\u89c4\u884c\u4e3a\u65f6\u65bd\u52a0\u7684\u7f5a\u6b3e\u66f4\u9ad8\u3002\u65f6\u95f4\u5e8f\u5217\u6570\u636e\u663e\u793a\uff0c\u8fd9\u79cd\u5dee\u5f02\u4e3b\u8981\u7531\u653f\u6cbb\u7acb\u573a\u7684\u53d8\u52a8\u800c\u975e\u56fa\u5b9a\u7684\u610f\u8bc6\u5f62\u6001\u5dee\u5f02\u5f15\u8d77\u3002\u5f53\u9ad8\u7ea7\u6cd5\u9662\u51fa\u73b0\u6cd5\u5b98\u7a7a\u7f3a\u65f6\uff0c\u4ee5\u53ca\u5728\u56fd\u5bb6\u5927\u9009\u524d\u51e0\u4e2a\u6708\uff0c\u8fd9\u79cd\u5dee\u5f02\u4f1a\u66f4\u52a0\u663e\u8457\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u51f8\u663e\u4e86\u653f\u6cbb\u6781\u5316\u5bf9\u7f8e\u56fd\u4f01\u4e1a\u7684\u91cd\u8981\u6027\uff0c\u5e76\u8bf4\u660e\u4e86\u53f8\u6cd5\u4eba\u5458\u6784\u6210\u5982\u4f55\u5f71\u54cd\u4f01\u4e1a\u907f\u514d\u8fdd\u53cd\u4e0e\u653f\u6cbb\u7acb\u573a\u76f8\u5173\u6cd5\u5f8b\u7684\u52a8\u529b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag016", "journal": "REStud", "title": "Coarse Bayesian Updating", "authors": ["Alexander M Jakobsen"], "author_details": [{"name": "Alexander M Jakobsen", "affiliations": ["Kellogg MEDS, Northwestern University ,"]}], "abstract": "Abstract Studies have shown that the standard law of belief updating\u2014Bayes\u2019 rule\u2014is descriptively invalid in various settings. In this paper, I introduce and analyse a generalization of Bayes\u2019 rule\u2014Coarse Bayesian updating\u2014accommodating much of the empirical evidence. I characterize the model axiomatically, show how it generates several well-known biases, and derive its main implications in static and dynamic settings. Each axiom expresses a property of Bayes\u2019 rule but, conditional on the others, stops just short of making the agent fully Bayesian. The model employs standard primitives, making it suitable for applications; I demonstrate this by applying it to a standard setting of decision under risk, leading to a close relationship with the Blackwell information ordering and comparative measures of cognitive sophistication and bias.", "date": "2026-02-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag016", "title_zh": "\u7c97\u7565\u8d1d\u53f6\u65af\u66f4\u65b0", "abstract_zh": "\u7814\u7a76\u663e\u793a\uff0c\u6807\u51c6\u7684\u4fe1\u5ff5\u66f4\u65b0\u6cd5\u5219\u2014\u2014\u8d1d\u53f6\u65af\u6cd5\u5219\u2014\u2014\u5728\u591a\u79cd\u60c5\u5883\u4e0b\u5177\u6709\u63cf\u8ff0\u6027\u65e0\u6548\u6027\u3002\u672c\u6587\u5f15\u5165\u5e76\u5206\u6790\u4e86\u8d1d\u53f6\u65af\u6cd5\u5219\u7684\u4e00\u4e2a\u5e7f\u4e49\u5f62\u5f0f\u2014\u2014\u7c97\u7565\u8d1d\u53f6\u65af\u66f4\u65b0\uff0c\u8be5\u5f62\u5f0f\u80fd\u591f\u5bb9\u7eb3\u5927\u91cf\u5b9e\u8bc1\u8bc1\u636e\u3002\u6211\u4ece\u516c\u7406\u89d2\u5ea6\u523b\u753b\u4e86\u8be5\u6a21\u578b\uff0c\u5c55\u793a\u4e86\u5176\u5982\u4f55\u4ea7\u751f\u82e5\u5e72\u5df2\u77e5\u7684\u504f\u89c1\uff0c\u5e76\u63a8\u5bfc\u51fa\u5176\u5728\u9759\u6001\u548c\u52a8\u6001\u60c5\u5883\u4e0b\u7684\u4e3b\u8981\u542b\u4e49\u3002\u6bcf\u4e2a\u516c\u7406\u8868\u8fbe\u7684\u662f\u8d1d\u53f6\u65af\u6cd5\u5219\u7684\u4e00\u4e2a\u6027\u8d28\uff0c\u4f46\u5728\u5176\u4ed6\u516c\u7406\u6210\u7acb\u7684\u6761\u4ef6\u4e0b\uff0c\u4ec5\u6b62\u6b65\u4e8e\u4e0d\u4f7f\u4ee3\u7406\u4eba\u5b8c\u5168\u8d1d\u53f6\u65af\u5316\u3002\u8be5\u6a21\u578b\u4f7f\u7528\u6807\u51c6\u7684\u539f\u59cb\u5047\u8bbe\uff0c\u4f7f\u5176\u9002\u7528\u4e8e\u5b9e\u9645\u5e94\u7528\uff1b\u6211\u901a\u8fc7\u5c06\u5176\u5e94\u7528\u4e8e\u98ce\u9669\u51b3\u7b56\u7684\u6807\u51c6\u60c5\u5883\u4e2d\uff0c\u5c55\u793a\u4e86\u5176\u4e0e\u9ed1well\u4fe1\u606f\u5e8f\u4ee5\u53ca\u8ba4\u77e5\u590d\u6742\u6027\u4e0e\u504f\u89c1\u7684\u6bd4\u8f83\u5ea6\u91cf\u4e4b\u95f4\u7684\u5bc6\u5207\u5173\u7cfb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdaf102", "journal": "REStud", "title": "Latent Heterogeneity in the Marginal Propensity to Consume", "authors": ["Daniel Lewis", "Davide Melcangi", "Laura Pilossoph"], "author_details": [{"name": "Daniel Lewis", "affiliations": ["University College London and CEPR ,"]}, {"name": "Davide Melcangi", "affiliations": ["Federal Reserve Bank of New York, USA"]}, {"name": "Laura Pilossoph", "affiliations": ["Duke University ,"]}], "abstract": "Abstract We estimate the unconditional distribution of the marginal propensity to consume (MPC) using clustering regression applied to the 2008 economic stimulus payments. By deviating from the standard approach of estimating MPC heterogeneity using interactions with observables, we can recover the full distribution of MPCs. We find households spent between 4 and 133% of the rebate within a quarter, and individual households used rebates for different goods. While many observable characteristics correlate individually with our estimated MPCs, most of these relationships disappear when tested jointly. Notable exceptions are income and the average propensity to consume, which correlate positively with the MPC. Household observable characteristics explain only 8% of MPC variation, highlighting the role of latent heterogeneity.", "date": "2026-02-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdaf102", "title_zh": "\u8fb9\u9645\u6d88\u8d39\u503e\u5411\u4e2d\u7684\u6f5c\u5728\u5f02\u8d28\u6027", "abstract_zh": "\u6211\u4eec\u5229\u75282008\u5e74\u7ecf\u6d4e\u523a\u6fc0\u652f\u4ed8\u6570\u636e\uff0c\u901a\u8fc7\u805a\u7c7b\u56de\u5f52\u65b9\u6cd5\u4f30\u8ba1\u4e86\u8fb9\u9645\u6d88\u8d39\u503e\u5411\uff08MPC\uff09\u7684\u65e0\u6761\u4ef6\u5206\u5e03\u3002\u4e0e\u4f20\u7edf\u65b9\u6cd5\u4ec5\u901a\u8fc7\u53ef\u89c2\u6d4b\u53d8\u91cf\u7684\u4ea4\u4e92\u9879\u6765\u4f30\u8ba1MPC\u5f02\u8d28\u6027\u4e0d\u540c\uff0c\u6211\u4eec\u7684\u65b9\u6cd5\u80fd\u591f\u6062\u590dMPC\u7684\u5b8c\u6574\u5206\u5e03\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5bb6\u5ead\u5728\u56db\u4e2a\u6708\u5185\u5c06\u523a\u6fc0\u91d1\u652f\u51fa\u6bd4\u4f8b\u4ecb\u4e8e4%\u5230133%\u4e4b\u95f4\uff0c\u4e14\u4e0d\u540c\u5bb6\u5ead\u5c06\u8865\u8d34\u7528\u4e8e\u4e0d\u540c\u7684\u5546\u54c1\u3002\u5c3d\u7ba1\u8bb8\u591a\u53ef\u89c2\u6d4b\u7279\u5f81\u4e0e\u6211\u4eec\u4f30\u8ba1\u7684MPC\u5728\u4e2a\u4f53\u5c42\u9762\u76f8\u5173\uff0c\u4f46\u5f53\u8fd9\u4e9b\u5173\u7cfb\u8054\u5408\u68c0\u9a8c\u65f6\uff0c\u5927\u591a\u6570\u90fd\u6d88\u5931\u3002\u503c\u5f97\u6ce8\u610f\u7684\u662f\uff0c\u6536\u5165\u548c\u5e73\u5747\u6d88\u8d39\u503e\u5411\u4e0eMPC\u5448\u6b63\u76f8\u5173\u3002\u5bb6\u5ead\u7684\u53ef\u89c2\u6d4b\u7279\u5f81\u4ec5\u89e3\u91ca\u4e86MPC\u53d8\u5f02\u76848%\uff0c\u51f8\u663e\u4e86\u6f5c\u5728\u5f02\u8d28\u6027\u7684\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag014", "journal": "REStud", "title": "Narratives about the Macroeconomy", "authors": ["Peter Andre", "Ingar Haaland", "Christopher Roth", "Mirko Wiederholt", "Johannes Wohlfart"], "author_details": [{"name": "Peter Andre", "affiliations": ["Leibniz Institute for Financial Research SAFE, Germany; Goethe University Frankfurt ,"]}, {"name": "Ingar Haaland", "affiliations": ["NHH Norwegian School of Economics, Norway; NTNU Business School ,"]}, {"name": "Christopher Roth", "affiliations": ["University of Cologne, Germany; ECONtribute, Germany; Max Planck Institute for Behavioral Economics, Germany; NHH Norwegian School of Economics ,"]}, {"name": "Mirko Wiederholt", "affiliations": ["LMU Munich ,"]}, {"name": "Johannes Wohlfart", "affiliations": ["University of Cologne, Germany; ECONtribute, Germany; Max Planck Institute for Behavioral Economics ,"]}], "abstract": "Abstract We study narratives about the macroeconomy\u2014the stories people tell to explain macroeconomic phenomena\u2014in the context of a historic surge in inflation. In our empirical analysis, we field surveys with more than 10,000 U.S. households and 100 academic experts, measure economic narratives in open-ended questions, and represent them as directed acyclic graphs. Households\u2019 narratives are strongly heterogeneous, coarser than experts\u2019 narratives, focus more on the supply than the demand side, and often feature politically charged explanations. Moreover, narratives shape how households form inflation expectations and interpret new information, which we demonstrate in a series of experiments. Informed by these findings, our theoretical analysis incorporates narratives into an otherwise conventional New Keynesian model and demonstrates their importance for aggregate outcomes through their effect on agents\u2019 expectations.", "date": "2026-02-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag014", "title_zh": "\u5173\u4e8e\u5b8f\u89c2\u7ecf\u6d4e\u7684\u53d9\u4e8b", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5173\u4e8e\u5b8f\u89c2\u7ecf\u6d4e\u7684\u53d9\u4e8b\u2014\u2014\u4eba\u4eec\u7528\u6765\u89e3\u91ca\u5b8f\u89c2\u7ecf\u6d4e\u73b0\u8c61\u7684\u6545\u4e8b\u2014\u2014\u5728\u901a\u80c0\u6025\u5267\u4e0a\u5347\u7684\u5386\u53f2\u80cc\u666f\u4e0b\u7684\u60c5\u51b5\u3002\u5728\u6211\u4eec\u7684\u5b9e\u8bc1\u5206\u6790\u4e2d\uff0c\u6211\u4eec\u5bf9\u8d85\u8fc710,000\u4e2a\u7f8e\u56fd\u5bb6\u5ead\u548c100\u540d\u5b66\u672f\u4e13\u5bb6\u8fdb\u884c\u4e86\u95ee\u5377\u8c03\u67e5\uff0c\u901a\u8fc7\u5f00\u653e\u6027\u95ee\u9898\u6d4b\u91cf\u7ecf\u6d4e\u53d9\u4e8b\uff0c\u5e76\u5c06\u5176\u8868\u793a\u4e3a\u6709\u5411\u65e0\u73af\u56fe\u3002\u5bb6\u5ead\u7684\u53d9\u4e8b\u8868\u73b0\u51fa\u663e\u8457\u7684\u5f02\u8d28\u6027\uff0c\u6bd4\u4e13\u5bb6\u7684\u53d9\u4e8b\u66f4\u7c97\u7565\uff0c\u66f4\u5173\u6ce8\u4f9b\u7ed9\u4fa7\u800c\u975e\u9700\u6c42\u4fa7\uff0c\u4e14\u5e38\u5e38\u5305\u542b\u653f\u6cbb\u8272\u5f69\u7684\u89e3\u91ca\u3002\u6b64\u5916\uff0c\u53d9\u4e8b\u5f71\u54cd\u4e86\u5bb6\u5ead\u5982\u4f55\u5f62\u6210\u901a\u80c0\u9884\u671f\u4ee5\u53ca\u5982\u4f55\u89e3\u8bfb\u65b0\u4fe1\u606f\uff0c\u6211\u4eec\u5728\u4e00\u7cfb\u5217\u5b9e\u9a8c\u4e2d\u8bc1\u660e\u4e86\u8fd9\u4e00\u70b9\u3002\u57fa\u4e8e\u8fd9\u4e9b\u53d1\u73b0\uff0c\u6211\u4eec\u7684\u7406\u8bba\u5206\u6790\u5c06\u53d9\u4e8b\u7eb3\u5165\u4e00\u4e2a\u4f20\u7edf\u7684\u65b0\u51ef\u6069\u65af\u6a21\u578b\u4e2d\uff0c\u5e76\u901a\u8fc7\u5176\u5bf9\u4e2a\u4f53\u9884\u671f\u7684\u5f71\u54cd\uff0c\u5c55\u793a\u4e86\u53d9\u4e8b\u5bf9\u6574\u4f53\u7ecf\u6d4e\u7ed3\u679c\u7684\u91cd\u8981\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.13472", "journal": "JF", "title": "Dynamic Trading with Realization Utility", "authors": ["MIN DAI", "CONG QIN", "NENG WANG"], "author_details": [{"name": "MIN DAI", "affiliations": []}, {"name": "CONG QIN", "affiliations": []}, {"name": "NENG WANG", "affiliations": []}], "abstract": "ABSTRACT An investor receives utility bursts from realizing gains and losses at the individual stock level and dynamically allocates his mental budget between risky and risk\u2010free assets at the trading account level. Using savings, he reduces his stockholdings and is more willing to realize losses. Using leverage, he increases his stockholdings beyond his mental budget and is more reluctant to realize losses. While leverage strengthens the disposition effect, introducing leverage constraints mitigates it. Our model predicts that investors with stocks in deep losses sell them either immediately or after stocks rebound a little.", "date": "2026-02-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.13472", "title_zh": "\u5177\u6709\u5b9e\u73b0\u6548\u7528\u7684\u52a8\u6001\u4ea4\u6613", "abstract_zh": "\u6458\u8981 \u6295\u8d44\u8005\u4ece\u4e2a\u80a1\u7684\u76c8\u4e8f\u5b9e\u73b0\u4e2d\u83b7\u5f97\u6548\u7528\uff0c\u5e76\u5728\u4ea4\u6613\u8d26\u6237\u5c42\u9762\u52a8\u6001\u5206\u914d\u5176\u5fc3\u7406\u9884\u7b97\uff0c\u7528\u4e8e\u5728\u98ce\u9669\u8d44\u4ea7\u548c\u65e0\u98ce\u9669\u8d44\u4ea7\u4e4b\u95f4\u8fdb\u884c\u914d\u7f6e\u3002\u901a\u8fc7\u50a8\u84c4\uff0c\u4ed6\u51cf\u5c11\u6301\u80a1\u91cf\uff0c\u4ece\u800c\u66f4\u613f\u610f\u5b9e\u73b0\u4e8f\u635f\uff1b\u901a\u8fc7\u6760\u6746\uff0c\u4ed6\u5c06\u6301\u80a1\u91cf\u589e\u52a0\u5230\u8d85\u8fc7\u5176\u5fc3\u7406\u9884\u7b97\uff0c\u56e0\u800c\u66f4\u4e0d\u613f\u610f\u5b9e\u73b0\u4e8f\u635f\u3002\u5c3d\u7ba1\u6760\u6746\u5f3a\u5316\u4e86\u5904\u7f6e\u6548\u5e94\uff0c\u4f46\u5f15\u5165\u6760\u6746\u7ea6\u675f\u53ef\u4ee5\u7f13\u89e3\u8fd9\u4e00\u6548\u5e94\u3002\u6211\u4eec\u7684\u6a21\u578b\u9884\u6d4b\uff0c\u6301\u6709\u6df1\u5ea6\u4e8f\u635f\u80a1\u7968\u7684\u6295\u8d44\u8005\u8981\u4e48\u7acb\u5373\u5356\u51fa\uff0c\u8981\u4e48\u5728\u80a1\u4ef7\u5c0f\u5e45\u56de\u5347\u540e\u624d\u5356\u51fa\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag015", "journal": "REStud", "title": "Decision Theory for Treatment Choice Problems with Partial Identification", "authors": ["Jos\u00e9 Luis Montiel Olea", "Chen Qiu", "J\u00f6rg Stoye"], "author_details": [{"name": "Jos\u00e9 Luis Montiel Olea", "affiliations": ["Department of Economics, Cornell University ,"]}, {"name": "Chen Qiu", "affiliations": ["Department of Economics, Cornell University ,"]}, {"name": "J\u00f6rg Stoye", "affiliations": ["Department of Economics, Cornell University ,"]}], "abstract": "Abstract We apply classical statistical decision theory to a large class of treatment choice problems with partial identification. We show that, in a general class of problems with Gaussian likelihood, all decision rules are admissible; it is maximin-welfare optimal to ignore all data; and, for severe enough partial identification, there are infinitely many minimax-regret optimal decision rules, all of which sometimes randomize the policy recommendation. We uniquely characterize the minimax-regret optimal rule that least frequently randomizes, and show that, in some cases, it can outperform other minimax-regret optimal rules in terms of what we call profiled regret. We analyse the implications of our results in the aggregation of experimental estimates for policy adoption, extrapolation of Local Average Treatment Effects, and policy making in the presence of omitted variable bias.", "date": "2026-02-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag015", "title_zh": "\u5177\u6709\u90e8\u5206\u8bc6\u522b\u7684\u6cbb\u7597\u9009\u62e9\u95ee\u9898\u7684\u51b3\u7b56\u7406\u8bba", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5c06\u7ecf\u5178\u7edf\u8ba1\u51b3\u7b56\u7406\u8bba\u5e94\u7528\u4e8e\u4e00\u5927\u7c7b\u5177\u6709\u90e8\u5206\u8bc6\u522b\u7684\u6cbb\u7597\u9009\u62e9\u95ee\u9898\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5728\u4e00\u7c7b\u5177\u6709\u9ad8\u65af\u4f3c\u7136\u7684\u901a\u7528\u95ee\u9898\u4e2d\uff0c\u6240\u6709\u51b3\u7b56\u89c4\u5219\u90fd\u662f\u53ef\u63a5\u53d7\u7684\uff1b\u5ffd\u7565\u6240\u6709\u6570\u636e\u5bf9\u6700\u5927\u6700\u5c0f\u798f\u5229\u6700\u4f18\uff1b\u5bf9\u4e8e\u4e25\u91cd\u7684\u90e8\u5206\u8bc6\u522b\uff0c\u5b58\u5728\u65e0\u9650\u591a\u4e2a\u6700\u5c0f\u5316\u540e\u6094\u7684\u6700\u4f18\u51b3\u7b56\u89c4\u5219\uff0c\u8fd9\u4e9b\u89c4\u5219\u6709\u65f6\u4f1a\u968f\u673a\u5316\u653f\u7b56\u5efa\u8bae\u3002\u6211\u4eec\u552f\u4e00\u5730\u523b\u753b\u4e86\u6700\u4e0d\u5e38\u968f\u673a\u5316\u7684\u6700\u5c0f\u5316\u540e\u6094\u6700\u4f18\u89c4\u5219\uff0c\u5e76\u8868\u660e\u5728\u67d0\u4e9b\u60c5\u51b5\u4e0b\uff0c\u8be5\u89c4\u5219\u5728\u6211\u4eec\u79f0\u4e4b\u4e3a\u201c\u8f6e\u5ed3\u540e\u6094\u201d\u7684\u6307\u6807\u4e0a\u53ef\u4ee5\u4f18\u4e8e\u5176\u4ed6\u6700\u5c0f\u5316\u540e\u6094\u6700\u4f18\u89c4\u5219\u3002\u6211\u4eec\u5206\u6790\u4e86\u8fd9\u4e9b\u7ed3\u679c\u5728\u5b9e\u9a8c\u4f30\u8ba1\u805a\u5408\u4ee5\u8fdb\u884c\u653f\u7b56\u91c7\u7eb3\u3001\u5c40\u90e8\u5e73\u5747\u5904\u7406\u6548\u5e94\u7684\u5916\u63a8\u4ee5\u53ca\u5b58\u5728\u9057\u6f0f\u53d8\u91cf\u504f\u5dee\u60c5\u51b5\u4e0b\u7684\u653f\u7b56\u5236\u5b9a\u4e2d\u7684\u542b\u4e49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhaf102", "journal": "RFS", "title": "Financial Intermediaries and the Yield Curve", "authors": ["Andr\u00e9s Schneider"], "author_details": [{"name": "Andr\u00e9s Schneider", "affiliations": ["Board of Governors of the Federal Reserve System"]}], "abstract": "Abstract I study the yield curve dynamics in a general equilibrium model with financial intermediaries facing financing constraints. When constraints bind, intermediaries reallocate their portfolios, causing deadweight losses in aggregate consumption, thus affecting savers\u2019 marginal utility. Because the yield curve is a forecast of marginal utility, intermediaries\u2019 constraints show up, via general equilibrium forces, in long-term yields. I show that the mechanism connecting intermediaries\u2019 constraints and long-term yields produces highly nonlinear interest rate dynamics and a positive real term premium in equilibrium. I extend the analysis to the nominal yield curve using a simple Taylor rule.", "date": "2026-02-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf102", "title_zh": "\u91d1\u878d\u4e2d\u4ecb\u673a\u6784\u4e0e\u6536\u76ca\u7387\u66f2\u7ebf", "abstract_zh": "\u6211\u7814\u7a76\u4e86\u4e00\u4e2a\u5305\u542b\u91d1\u878d\u4e2d\u4ecb\u673a\u6784\u9762\u4e34\u878d\u8d44\u7ea6\u675f\u7684\u4e00\u822c\u5747\u8861\u6a21\u578b\u4e2d\u7684\u6536\u76ca\u7387\u66f2\u7ebf\u52a8\u6001\u3002\u5f53\u7ea6\u675f\u751f\u6548\u65f6\uff0c\u4e2d\u4ecb\u673a\u6784\u4f1a\u91cd\u65b0\u914d\u7f6e\u5176\u6295\u8d44\u7ec4\u5408\uff0c\u5bfc\u81f4\u6574\u4f53\u6d88\u8d39\u4e2d\u7684\u65e0\u8c13\u635f\u5931\uff0c\u4ece\u800c\u5f71\u54cd\u50a8\u84c4\u8005\u7684\u8fb9\u9645\u6548\u7528\u3002\u7531\u4e8e\u6536\u76ca\u7387\u66f2\u7ebf\u662f\u8fb9\u9645\u6548\u7528\u7684\u9884\u6d4b\uff0c\u4e2d\u4ecb\u673a\u6784\u7684\u7ea6\u675f\u901a\u8fc7\u4e00\u822c\u5747\u8861\u673a\u5236\u53cd\u6620\u5728\u957f\u671f\u6536\u76ca\u7387\u4e2d\u3002\u6211\u8bc1\u660e\u4e86\u4e2d\u4ecb\u673a\u6784\u7ea6\u675f\u4e0e\u957f\u671f\u6536\u76ca\u7387\u4e4b\u95f4\u7684\u673a\u5236\u4f1a\u4ea7\u751f\u9ad8\u5ea6\u975e\u7ebf\u6027\u7684\u5229\u7387\u52a8\u6001\uff0c\u5e76\u5728\u5747\u8861\u4e2d\u4ea7\u751f\u6b63\u7684\u5b9e\u7269\u671f\u9650\u6ea2\u4ef7\u3002\u6211\u8fdb\u4e00\u6b65\u5c06\u5206\u6790\u6269\u5c55\u5230\u540d\u4e49\u6536\u76ca\u7387\u66f2\u7ebf\uff0c\u91c7\u7528\u4e00\u4e2a\u7b80\u5355\u7684\u6cf0\u52d2\u89c4\u5219\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhaf101", "journal": "RFS", "title": "Cooling Auction Fever: Evidence from the Housing Market", "authors": ["Antonio Gargano", "Marco Giacoletti"], "author_details": [{"name": "Antonio Gargano", "affiliations": ["University of Houston and University of Melbourne, USA and Australia"]}, {"name": "Marco Giacoletti", "affiliations": ["USC Marshall ,"]}], "abstract": "Abstract We study the effects of underquoting, the practice of setting listing prices below sellers\u2019 reservation values, on housing auctions. Laws introduced in Australia to deter underquoting lead to higher listing prices, but also to declines in sales prices and sales probabilities. We develop a quantitative model to formalize predictions under different assumptions about bidders\u2019 information and rationality. The effects of the laws are matched by a version of the model in which participating bidders overbid. While both behavioral biases arising during the auction and switching costs can explain overbidding, empirical and survey evidence points to behavioral biases as the main mechanism.", "date": "2026-02-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf101", "title_zh": "\u964d\u6e29\u62cd\u5356\u70ed\u6f6e\uff1a\u6765\u81ea\u623f\u5730\u4ea7\u5e02\u573a\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5b9a\u4ef7\u4f4e\u4e8e\u5356\u5bb6\u4fdd\u7559\u4ef7\u503c\u7684\u62a5\u4ef7\u884c\u4e3a\uff08\u5373\u62a5\u4ef7\u4e0d\u8db3\uff09\u5bf9\u623f\u5730\u4ea7\u62cd\u5356\u7684\u5f71\u54cd\u3002\u6fb3\u5927\u5229\u4e9a\u4e3a\u904f\u5236\u62a5\u4ef7\u4e0d\u8db3\u800c\u51fa\u53f0\u7684\u6cd5\u5f8b\u5bfc\u81f4\u4e86\u6302\u724c\u4ef7\u683c\u7684\u4e0a\u5347\uff0c\u4f46\u4e5f\u5e26\u6765\u4e86\u9500\u552e\u4ef7\u683c\u548c\u9500\u552e\u6982\u7387\u7684\u4e0b\u964d\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5b9a\u91cf\u6a21\u578b\uff0c\u4ee5\u5728\u4e0d\u540c\u5173\u4e8e\u4e70\u5bb6\u4fe1\u606f\u548c\u7406\u6027\u7684\u5047\u8bbe\u4e0b\u6b63\u5f0f\u5316\u5404\u79cd\u9884\u6d4b\u3002\u6cd5\u5f8b\u6548\u679c\u5728\u4e00\u79cd\u53c2\u4e0e\u8005\u8fc7\u5ea6\u51fa\u4ef7\u7684\u6a21\u578b\u7248\u672c\u4e2d\u5f97\u5230\u5339\u914d\u3002\u867d\u7136\u62cd\u5356\u8fc7\u7a0b\u4e2d\u7684\u884c\u4e3a\u504f\u5dee\u548c\u8f6c\u6362\u6210\u672c\u90fd\u53ef\u80fd\u5f15\u53d1\u8fc7\u5ea6\u51fa\u4ef7\uff0c\u4f46\u5b9e\u8bc1\u548c\u8c03\u67e5\u8bc1\u636e\u8868\u660e\uff0c\u884c\u4e3a\u504f\u5dee\u662f\u4e3b\u8981\u673a\u5236\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag010", "journal": "RFS", "title": "Algorithmic Pricing and Liquidity in Securities Markets", "authors": ["Jean-Edouard Colliard", "Thierry Foucault", "Stefano Lovo"], "author_details": [{"name": "Jean-Edouard Colliard", "affiliations": ["HEC Paris ,"]}, {"name": "Thierry Foucault", "affiliations": ["HEC Paris ,"]}, {"name": "Stefano Lovo", "affiliations": ["HEC Paris ,"]}], "abstract": "Abstract We study \u201cAlgorithmic Market Makers\u201d (AMs) that use Q-learning algorithms to set prices for a risky asset. We find that while AMs successfully adapt to adverse selection, they struggle to learn competitive pricing strategies. This failure is driven by limited experimentation and noisy feedback regarding the profitability of undercutting a competitor. Consequently, an increase in AMs\u2019 profit volatility tends to result in less competitive market outcomes. These features leave identifiable patterns: for example, AMs earn higher rents in the absence of adverse selection, and their bid-ask spreads respond asymmetrically to symmetric shocks to their costs.", "date": "2026-02-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag010", "title_zh": "\u7b97\u6cd5\u5b9a\u4ef7\u4e0e\u8bc1\u5238\u5e02\u573a\u6d41\u52a8\u6027", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u4f7f\u7528Q\u5b66\u4e60\u7b97\u6cd5\u4e3a\u98ce\u9669\u8d44\u4ea7\u8bbe\u5b9a\u4ef7\u683c\u7684\u201c\u7b97\u6cd5\u5e02\u573a\u505a\u5e02\u5546\u201d\uff08AMs\uff09\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5c3d\u7ba1AMs\u80fd\u591f\u9002\u5e94\u9006\u5411\u9009\u62e9\uff0c\u4f46\u5728\u5b66\u4e60\u5177\u6709\u7ade\u4e89\u529b\u7684\u5b9a\u4ef7\u7b56\u7565\u65b9\u9762\u5b58\u5728\u56f0\u96be\u3002\u8fd9\u79cd\u5931\u8d25\u6e90\u4e8e\u5b9e\u9a8c\u673a\u4f1a\u6709\u9650\uff0c\u4ee5\u53ca\u5173\u4e8e\u4f4e\u4e8e\u7ade\u4e89\u5bf9\u624b\u4ef7\u683c\u6240\u5e26\u6765\u7684\u76c8\u5229\u6027\u53cd\u9988\u5b58\u5728\u566a\u58f0\u3002\u56e0\u6b64\uff0cAMs\u5229\u6da6\u6ce2\u52a8\u6027\u589e\u52a0\u5f80\u5f80\u5bfc\u81f4\u5e02\u573a\u7ade\u4e89\u6027\u4e0b\u964d\u3002\u8fd9\u4e9b\u7279\u5f81\u8868\u73b0\u51fa\u53ef\u8bc6\u522b\u7684\u6a21\u5f0f\uff1a\u4f8b\u5982\uff0c\u5728\u6ca1\u6709\u9006\u5411\u9009\u62e9\u7684\u60c5\u51b5\u4e0b\uff0cAMs\u83b7\u5f97\u66f4\u9ad8\u7684\u79df\u91d1\uff0c\u4e14\u5b83\u4eec\u7684\u4e70\u5356\u4ef7\u5dee\u5bf9\u6210\u672c\u7684\u5bf9\u79f0\u51b2\u51fb\u8868\u73b0\u51fa\u975e\u5bf9\u79f0\u53cd\u5e94\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhaf112", "journal": "RFS", "title": "The Present Value of Future Market Power", "authors": ["Thummim Cho", "Marco Grotteria", "Lukas Kremens", "Howard Kung"], "author_details": [{"name": "Thummim Cho", "affiliations": ["Korea University Business School ,"]}, {"name": "Marco Grotteria", "affiliations": ["London Business School, the United Kingdom, and CEPR"]}, {"name": "Lukas Kremens", "affiliations": ["University of Washington, the United States"]}, {"name": "Howard Kung", "affiliations": ["London Business School, the United Kingdom, and CEPR"]}], "abstract": "Abstract We introduce a present-value identity relating a firm\u2019s market value to expected future markups, output growth, discount rates, and investments. Distinguishing current from expected markups reveals five empirical facts: (1) Expected markups account for half the rise in U.S. firm values since 1980. (2) The rise in aggregate expected markups reflects market-share reallocation toward high-expected-markup firms and within-firm increases. (3) Expected markups are linked to intangible investments. (4) They relate negatively to discount rates over time but (5) positively to abnormal returns across firms. Finally, variation in long-term expected markups is primarily associated with asset prices rather than current markups.", "date": "2026-02-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf112", "title_zh": "\u672a\u6765\u5e02\u573a\u529b\u91cf\u7684\u73b0\u503c", "abstract_zh": "\u6211\u4eec\u5f15\u5165\u4e86\u4e00\u4e2a\u5c06\u4f01\u4e1a\u5e02\u573a\u4ef7\u503c\u4e0e\u9884\u671f\u672a\u6765\u6ea2\u4ef7\u3001\u4ea7\u51fa\u589e\u957f\u3001\u6298\u73b0\u7387\u548c\u6295\u8d44\u8054\u7cfb\u8d77\u6765\u7684\u73b0\u503c\u6052\u7b49\u5f0f\u3002\u533a\u5206\u5f53\u524d\u6ea2\u4ef7\u4e0e\u9884\u671f\u6ea2\u4ef7\u63ed\u793a\u4e86\u4e94\u4e2a\u5b9e\u8bc1\u4e8b\u5b9e\uff1a\uff081\uff09\u9884\u671f\u6ea2\u4ef7\u89e3\u91ca\u4e861980\u5e74\u4ee5\u6765\u7f8e\u56fd\u4f01\u4e1a\u4ef7\u503c\u589e\u957f\u7684\u4e00\u534a\uff1b\uff082\uff09\u603b\u4f53\u9884\u671f\u6ea2\u4ef7\u7684\u4e0a\u5347\u53cd\u6620\u4e86\u5e02\u573a\u4efd\u989d\u5411\u9ad8\u9884\u671f\u6ea2\u4ef7\u4f01\u4e1a\u8f6c\u79fb\u4ee5\u53ca\u4f01\u4e1a\u5185\u90e8\u7684\u6ea2\u4ef7\u589e\u957f\uff1b\uff083\uff09\u9884\u671f\u6ea2\u4ef7\u4e0e\u65e0\u5f62\u8d44\u4ea7\u6295\u8d44\u76f8\u5173\uff1b\uff084\uff09\u9884\u671f\u6ea2\u4ef7\u968f\u65f6\u95f4\u8d1f\u5411\u5173\u8054\u6298\u73b0\u7387\uff0c\u4f46\u5bf9\u4f01\u4e1a\u5f02\u5e38\u56de\u62a5\u5448\u6b63\u5411\u5173\u8054\uff1b\u6700\u540e\uff0c\u957f\u671f\u9884\u671f\u6ea2\u4ef7\u7684\u6ce2\u52a8\u4e3b\u8981\u4e0e\u8d44\u4ea7\u4ef7\u683c\u76f8\u5173\uff0c\u800c\u975e\u5f53\u524d\u6ea2\u4ef7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1017/s0022109026102701", "journal": "JFQA", "title": "Real Disinvestments and the Distress Anomaly: Evidence from Stocks, Bonds, and Loans", "authors": ["Shuwen Yang", "Kevin Aretz", "Yafei Zhang"], "author_details": [{"name": "Shuwen Yang", "affiliations": ["USTB: University of Science and Technology Beijing"]}, {"name": "Kevin Aretz", "affiliations": ["The University of Manchester Alliance Manchester Business School"]}, {"name": "Yafei Zhang", "affiliations": ["American University of Sharjah"]}], "abstract": "Abstract We argue that firms\u2019 ability to disinvest real assets helps rationalize the negative distress premiums in stocks, bonds, and, as we show, loans and firm assets. Using a real options model in which shareholders and debtholders share disinvestment proceeds, the model suggests that the stock (debt) distress premium becomes more negative with the proceeds paid out to that class, and that both premiums can be negative when debtholders receive most of the proceeds. Using hard-asset disinvestment-ability proxies, the stock (bond or loan) distress premium becomes less (more) negative with those proxies, possibly suggesting that shareholders benefit more strongly from nonsecured-asset disinvestments.", "date": "2026-02-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102701", "title_zh": "\u5b9e\u7269\u51cf\u8d44\u4e0e\u56f0\u5883\u6ea2\u4ef7\uff1a\u6765\u81ea\u80a1\u7968\u3001\u503a\u5238\u548c\u8d37\u6b3e\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u4e3b\u5f20\uff0c\u4f01\u4e1a\u5904\u7f6e\u5b9e\u7269\u8d44\u4ea7\u7684\u80fd\u529b\u6709\u52a9\u4e8e\u89e3\u91ca\u80a1\u7968\u3001\u503a\u5238\u4ee5\u53ca\u6211\u4eec\u6240\u5c55\u793a\u7684\u8d37\u6b3e\u548c\u4f01\u4e1a\u8d44\u4ea7\u4e2d\u7684\u8d1f\u56f0\u5883\u6ea2\u4ef7\u3002\u5728\u80a1\u4e1c\u548c\u503a\u6743\u4eba\u5171\u540c\u5206\u4eab\u51cf\u8d44\u6536\u76ca\u7684\u5b9e\u7269\u671f\u6743\u6a21\u578b\u4e2d\uff0c\u6a21\u578b\u8868\u660e\uff0c\u5f53\u6536\u76ca\u652f\u4ed8\u7ed9\u67d0\u4e00\u7c7b\u6295\u8d44\u8005\u65f6\uff0c\u8be5\u7c7b\u6295\u8d44\u8005\u7684\u80a1\u7968\uff08\u503a\u52a1\uff09\u56f0\u5883\u6ea2\u4ef7\u4f1a\u53d8\u5f97\u66f4\u8d1f\uff0c\u4e14\u5f53\u503a\u6743\u4eba\u83b7\u5f97\u5927\u90e8\u5206\u6536\u76ca\u65f6\uff0c\u4e24\u7c7b\u6ea2\u4ef7\u90fd\u53ef\u80fd\u4e3a\u8d1f\u3002\u4f7f\u7528\u5b9e\u7269\u8d44\u4ea7\u51cf\u8d44\u80fd\u529b\u7684\u4ee3\u7406\u53d8\u91cf\uff0c\u80a1\u7968\uff08\u503a\u5238\u6216\u8d37\u6b3e\uff09\u7684\u56f0\u5883\u6ea2\u4ef7\u968f\u7740\u8fd9\u4e9b\u4ee3\u7406\u53d8\u91cf\u7684\u589e\u52a0\u800c\u51cf\u5c11\uff08\u589e\u52a0\uff09\uff0c\u8fd9\u53ef\u80fd\u8868\u660e\u80a1\u4e1c\u4ece\u65e0\u62b5\u62bc\u8d44\u4ea7\u51cf\u8d44\u4e2d\u83b7\u76ca\u66f4\u4e3a\u663e\u8457\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102683", "journal": "JFQA", "title": "Expected and Realized Returns on Volatility", "authors": ["Guanglian Hu", "Kris Jacobs"], "author_details": [{"name": "Guanglian Hu", "affiliations": ["The University of Sydney Business School"]}, {"name": "Kris Jacobs", "affiliations": ["University of Houston"]}], "abstract": "Abstract Expected returns on market volatility, which can be obtained from VIX futures prices in closed form using standard models, positively predict subsequent realized volatility returns. Volatility returns are negative on average. Following increases in volatility, expected volatility returns and subsequent realized volatility returns become more negative. Because realized volatility returns are negatively correlated with index returns, expected volatility returns also negatively predict S&P 500 index returns, but these results are less significant. The results are robust to a wide range of variations in the empirical setup and to small-sample biases.", "date": "2026-02-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102683", "title_zh": "\u6ce2\u52a8\u7387\u7684\u9884\u671f\u6536\u76ca\u4e0e\u5b9e\u9645\u6536\u76ca", "abstract_zh": "\u6458\u8981 \u901a\u8fc7\u6807\u51c6\u6a21\u578b\u53ef\u4ee5\u4eceVIX\u671f\u8d27\u4ef7\u683c\u4e2d\u4ee5\u5c01\u95ed\u5f62\u5f0f\u83b7\u5f97\u5e02\u573a\u6ce2\u52a8\u7387\u7684\u9884\u671f\u6536\u76ca\uff0c\u8fd9\u4e9b\u9884\u671f\u6536\u76ca\u80fd\u591f\u6b63\u5411\u9884\u6d4b\u540e\u7eed\u7684\u5b9e\u9645\u6ce2\u52a8\u7387\u6536\u76ca\u3002\u6ce2\u52a8\u7387\u6536\u76ca\u5e73\u5747\u4e3a\u8d1f\u3002\u5728\u6ce2\u52a8\u7387\u4e0a\u5347\u4e4b\u540e\uff0c\u9884\u671f\u6ce2\u52a8\u7387\u6536\u76ca\u548c\u968f\u540e\u7684\u5b9e\u9645\u6ce2\u52a8\u7387\u6536\u76ca\u53d8\u5f97\u66f4\u52a0\u8d1f\u503c\u3002\u7531\u4e8e\u5b9e\u9645\u6ce2\u52a8\u7387\u6536\u76ca\u4e0e\u6307\u6570\u6536\u76ca\u5448\u8d1f\u76f8\u5173\uff0c\u9884\u671f\u6ce2\u52a8\u7387\u6536\u76ca\u4e5f\u80fd\u591f\u8d1f\u5411\u9884\u6d4b\u6807\u666e500\u6307\u6570\u6536\u76ca\uff0c\u4f46\u8fd9\u4e9b\u7ed3\u679c\u7684\u663e\u8457\u6027\u8f83\u4f4e\u3002\u8fd9\u4e9b\u7ed3\u679c\u5728\u5e7f\u6cdb\u7684\u5b9e\u8bc1\u8bbe\u5b9a\u53d8\u5316\u4ee5\u53ca\u5c0f\u6837\u672c\u504f\u5dee\u60c5\u51b5\u4e0b\u5747\u5177\u6709\u7a33\u5065\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1017/s0022109026102634", "journal": "JFQA", "title": "Management Disclosure and Media Coverage", "authors": ["Hamid Boustanifar", "Sasan Mansouri"], "author_details": [{"name": "Hamid Boustanifar", "affiliations": ["EDHEC Business School"]}, {"name": "Sasan Mansouri", "affiliations": ["University of Groningen"]}], "abstract": "Abstract We examine how management disclosure affects media coverage by analyzing firms\u2019 responses in earnings call Q&A sessions. Using a machine-learning-based \u201cnonanswer\u201d score, we find that evasive managerial responses reduce subsequent media attention, particularly from professional outlets generating original content. This supports a supply-driven view of media coverage: poor disclosure limits journalistic content creation. Reduced coverage, in turn, is associated with lower investor engagement and weaker stock performance. Our findings highlight the critical role of a firm\u2019s information environment in shaping the level and nature of subsequent media coverage, with implications for broader financial market outcomes.", "date": "2026-02-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102634", "title_zh": "\u7ba1\u7406\u4fe1\u606f\u62ab\u9732\u4e0e\u5a92\u4f53\u62a5\u9053", "abstract_zh": "\u6211\u4eec\u901a\u8fc7\u5206\u6790\u4f01\u4e1a\u8d22\u62a5\u7535\u8bdd\u4f1a\u8bae\u95ee\u7b54\u73af\u8282\u4e2d\u7684\u56de\u5e94\uff0c\u7814\u7a76\u4e86\u7ba1\u7406\u4fe1\u606f\u62ab\u9732\u5982\u4f55\u5f71\u54cd\u5a92\u4f53\u62a5\u9053\u3002\u91c7\u7528\u57fa\u4e8e\u673a\u5668\u5b66\u4e60\u7684\u201c\u672a\u4f5c\u7b54\u201d\u8bc4\u5206\uff0c\u6211\u4eec\u53d1\u73b0\u7ba1\u7406\u5c42\u56de\u907f\u6027\u56de\u7b54\u4f1a\u964d\u4f4e\u540e\u7eed\u5a92\u4f53\u5173\u6ce8\uff0c\u5c24\u5176\u662f\u6765\u81ea\u5236\u4f5c\u539f\u521b\u5185\u5bb9\u7684\u4e13\u4e1a\u5a92\u4f53\u3002\u8fd9\u652f\u6301\u4e86\u5a92\u4f53\u62a5\u9053\u7684\u4f9b\u7ed9\u9a71\u52a8\u89c2\u70b9\uff1a\u4fe1\u606f\u62ab\u9732\u4e0d\u8db3\u4f1a\u9650\u5236\u65b0\u95fb\u5185\u5bb9\u7684\u751f\u4ea7\u3002\u5a92\u4f53\u62a5\u9053\u51cf\u5c11\u8fdb\u800c\u4e0e\u6295\u8d44\u8005\u53c2\u4e0e\u5ea6\u4e0b\u964d\u53ca\u80a1\u4ef7\u8868\u73b0\u75b2\u8f6f\u76f8\u5173\u3002\u6211\u4eec\u7684\u7814\u7a76\u5f3a\u8c03\u4e86\u4f01\u4e1a\u4fe1\u606f\u73af\u5883\u5728\u5851\u9020\u5a92\u4f53\u62a5\u9053\u6c34\u5e73\u548c\u6027\u8d28\u4e2d\u7684\u5173\u952e\u4f5c\u7528\uff0c\u5bf9\u66f4\u5e7f\u6cdb\u7684\u91d1\u878d\u5e02\u573a\u7ed3\u679c\u5177\u6709\u542f\u793a\u610f\u4e49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102695", "journal": "JFQA", "title": "Investment Functions with q in the Presence of Unobserved Persistent Shocks", "authors": ["Kyoo il Kim", "Suyong Song", "Jiawei (Brooke) Wang"], "author_details": [{"name": "Kyoo il Kim", "affiliations": ["Michigan State University"]}, {"name": "Suyong Song", "affiliations": ["University of Iowa"]}, {"name": "Jiawei (Brooke) Wang", "affiliations": ["Miami University"]}], "abstract": "Abstract We study the classical relationship between a firm\u2019s investment and q , for which an unobserved persistent shock is an important factor in the investment decision. In our setting, besides the potential measurement problem of q , controlling for the unobserved shock becomes a new challenge. We develop an estimation method that addresses both econometric issues given timing and information set assumptions. Using 16,256 unique public firms in the United States from 1975 to 2021, we find that q remains a significant factor of investment even after controlling for the unobserved shock and measurement error.", "date": "2026-02-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102695", "title_zh": "q\u7684\u5b58\u5728\u4e0b\u672a\u89c2\u6d4b\u6301\u4e45\u51b2\u51fb\u4e0b\u7684\u6295\u8d44\u51fd\u6570", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u4f01\u4e1a\u6295\u8d44\u4e0eq\u4e4b\u95f4\u7684\u7ecf\u5178\u5173\u7cfb\uff0c\u5176\u4e2d\u672a\u89c2\u6d4b\u7684\u6301\u4e45\u51b2\u51fb\u662f\u6295\u8d44\u51b3\u7b56\u4e2d\u7684\u91cd\u8981\u56e0\u7d20\u3002\u5728\u6211\u4eec\u7684\u8bbe\u5b9a\u4e2d\uff0c\u9664\u4e86q\u7684\u6f5c\u5728\u6d4b\u91cf\u95ee\u9898\u5916\uff0c\u63a7\u5236\u672a\u89c2\u6d4b\u51b2\u51fb\u6210\u4e3a\u4e00\u4e2a\u65b0\u7684\u6311\u6218\u3002\u6211\u4eec\u5f00\u53d1\u4e86\u4e00\u79cd\u4f30\u8ba1\u65b9\u6cd5\uff0c\u8be5\u65b9\u6cd5\u5728\u7ed9\u5b9a\u65f6\u70b9\u548c\u4fe1\u606f\u96c6\u5047\u8bbe\u6761\u4ef6\u4e0b\u89e3\u51b3\u4e86\u8fd9\u4e24\u4e2a\u8ba1\u91cf\u7ecf\u6d4e\u5b66\u95ee\u9898\u3002\u5229\u75281975\u5e74\u81f32021\u5e74\u95f4\u7f8e\u56fd16,256\u5bb6\u72ec\u7279\u7684\u516c\u5f00\u516c\u53f8\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u5373\u4f7f\u5728\u63a7\u5236\u4e86\u672a\u89c2\u6d4b\u51b2\u51fb\u548c\u6d4b\u91cf\u8bef\u5dee\u4e4b\u540e\uff0cq\u4ecd\u7136\u662f\u5f71\u54cd\u6295\u8d44\u7684\u91cd\u8981\u56e0\u7d20\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag009", "journal": "QJE", "title": "Civil War\u2013Induced Displacement and Human Capital", "authors": ["Giorgio Chiovelli", "Stelios Michalopoulos", "Elias Papaioannou", "Sandra Sequeira"], "author_details": [{"name": "Giorgio Chiovelli", "affiliations": ["Universidad de Montevideo ,"]}, {"name": "Stelios Michalopoulos", "affiliations": ["Brown University ,"]}, {"name": "Elias Papaioannou", "affiliations": ["London Business School ,"]}, {"name": "Sandra Sequeira", "affiliations": ["London School of Economics and Political Science ,"]}], "abstract": "Abstract We study the effect of conflict-induced displacement on human capital and occupational shifts, focusing on the Mozambican civil war (1977\u20131992), during which millions of civilians were forced to flee to the countryside, cities, and neighboring countries. Reconstructing the wartime mobility histories of the surviving population, we examine the consequences of multiple displacement trajectories in a unified framework. First, we characterize the education and sectoral employment of the universe of (non-)displaced. Second, we exploit differences in relocation trajectories among extended kin members during their schooling years. Displacement is associated with significant gains in education. Third, using a movers design, we show that minors displaced earlier to better districts experienced an increase in educational attainment. Focusing on moves during the intensification of the war and when comparing members of the same household, regional childhood exposure effects remain strong, whereas spatial sorting becomes negligible. Fourth, we jointly estimate place-based, spatial sorting, and uprootedness effects, showing that all forces are at play. Fifth, a small survey in Mozambique\u2019s largest northern city reveals long-term effects: internally displaced people report higher education than their siblings who stayed behind but lower social capital and worse mental health relative to locals. Our findings demonstrate that displacement shocks can foster human capital accumulation, even in very low-income settings, albeit at the cost of enduring social and psychological traumas.", "date": "2026-02-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag009", "title_zh": "\u5185\u6218\u5f15\u53d1\u7684\u6d41\u79bb\u5931\u6240\u4e0e\u4eba\u529b\u8d44\u672c", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u56e0\u51b2\u7a81\u5bfc\u81f4\u7684\u6d41\u79bb\u5931\u6240\u5bf9\u4eba\u529b\u8d44\u672c\u548c\u804c\u4e1a\u8f6c\u6362\u7684\u5f71\u54cd\uff0c\u91cd\u70b9\u5173\u6ce8\u83ab\u6851\u6bd4\u514b\u5185\u6218\uff081977\u20131992\u5e74\uff09\u671f\u95f4\uff0c\u6570\u767e\u4e07\u5e73\u6c11\u88ab\u8feb\u8fc1\u5f80\u519c\u6751\u3001\u57ce\u5e02\u4ee5\u53ca\u90bb\u56fd\u7684\u60c5\u51b5\u3002\u901a\u8fc7\u91cd\u5efa\u5e78\u5b58\u4eba\u53e3\u5728\u6218\u4e89\u671f\u95f4\u7684\u8fc1\u79fb\u5386\u53f2\uff0c\u6211\u4eec\u5728\u4e00\u4e2a\u7edf\u4e00\u7684\u6846\u67b6\u4e0b\u8003\u5bdf\u4e86\u591a\u79cd\u6d41\u79bb\u5931\u6240\u8def\u5f84\u7684\u540e\u679c\u3002\u9996\u5148\uff0c\u6211\u4eec\u523b\u753b\u4e86\uff08\u975e\uff09\u6d41\u79bb\u5931\u6240\u4eba\u7fa4\u7684\u6559\u80b2\u6c34\u5e73\u548c\u884c\u4e1a\u5c31\u4e1a\u60c5\u51b5\u3002\u5176\u6b21\uff0c\u6211\u4eec\u5229\u7528\u5728\u6c42\u5b66\u671f\u95f4\u4e0d\u540c\u4eb2\u5c5e\u6210\u5458\u8fc1\u79fb\u8def\u5f84\u7684\u5dee\u5f02\uff0c\u53d1\u73b0\u6d41\u79bb\u5931\u6240\u4e0e\u6559\u80b2\u6c34\u5e73\u663e\u8457\u63d0\u5347\u76f8\u5173\u3002\u7b2c\u4e09\uff0c\u901a\u8fc7\u201c\u8fc1\u5f99\u8bbe\u8ba1\u201d\uff0c\u6211\u4eec\u53d1\u73b0\u65e9\u671f\u8fc1\u5f80\u6559\u80b2\u6761\u4ef6\u66f4\u597d\u7684\u5730\u533a\u7684\u5c0f\u5b69\uff0c\u5176\u6559\u80b2\u6c34\u5e73\u6709\u6240\u63d0\u9ad8\u3002\u5728\u6218\u4e89\u52a0\u5267\u9636\u6bb5\u4ee5\u53ca\u5728\u6bd4\u8f83\u540c\u4e00\u5bb6\u5ead\u6210\u5458\u65f6\uff0c\u7ae5\u5e74\u65f6\u671f\u533a\u57df\u66b4\u9732\u6548\u5e94\u4f9d\u7136\u663e\u8457\uff0c\u800c\u7a7a\u95f4\u5206\u5c42\u6548\u5e94\u5219\u53d8\u5f97\u5fae\u4e0d\u8db3\u9053\u3002\u7b2c\u56db\uff0c\u6211\u4eec\u8054\u5408\u4f30\u8ba1\u4e86\u57fa\u4e8e\u5730\u70b9\u7684\u6548\u5e94\u3001\u7a7a\u95f4\u5206\u5c42\u6548\u5e94\u548c\u6d41\u79bb\u5931\u6240\u6548\u5e94\uff0c\u8868\u660e\u6240\u6709\u56e0\u7d20\u5747\u5728\u53d1\u6325\u4f5c\u7528\u3002\u7b2c\u4e94\uff0c\u83ab\u6851\u6bd4\u514b\u6700\u5927\u5317\u90e8\u57ce\u5e02\u7684\u4e00\u9879\u5c0f\u578b\u8c03\u67e5\u663e\u793a\uff1a\u6d41\u79bb\u5931\u6240\u8005\u62a5\u544a\u7684\u6559\u80b2\u6c34\u5e73\u9ad8\u4e8e\u7559\u5728\u539f\u5730\u7684\u5144\u5f1f\u59d0\u59b9\uff0c\u4f46\u5176\u793e\u4f1a\u8d44\u672c\u8f83\u4f4e\uff0c\u5fc3\u7406\u5065\u5eb7\u72b6\u51b5\u4e5f\u6bd4\u5f53\u5730\u5c45\u6c11\u66f4\u5dee\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u5373\u4f7f\u5728\u4f4e\u6536\u5165\u73af\u5883\u4e2d\uff0c\u6d41\u79bb\u5931\u6240\u51b2\u51fb\u4e5f\u53ef\u80fd\u4fc3\u8fdb\u4eba\u529b\u8d44\u672c\u79ef\u7d2f\uff0c\u4f46\u540c\u65f6\u4e5f\u4f34\u968f\u7740\u957f\u671f\u7684\u793e\u4f1a\u548c\u5fc3\u7406\u521b\u4f24\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag010", "journal": "QJE", "title": "Disaggregated Economic Accounts", "authors": ["Asger Lau Andersen", "Kilian Huber", "Niels Johannesen", "Ludwig Straub", "Emil Toft Vestergaard"], "author_details": [{"name": "Asger Lau Andersen", "affiliations": ["Danish Finance Institute and CEBI, University of Copenhagen ,"]}, {"name": "Kilian Huber", "affiliations": ["University of Chicago and NBER ,"]}, {"name": "Niels Johannesen", "affiliations": ["University of Oxford, United Kingdom, and CEBI, University of Copenhagen ,"]}, {"name": "Ludwig Straub", "affiliations": ["Harvard University and NBER ,"]}, {"name": "Emil Toft Vestergaard", "affiliations": ["Danmarks Nationalbank ,"]}], "abstract": "Abstract We develop a system of disaggregated economic accounts. The system breaks down national accounting positions into bilateral flows between consistently defined groups of consumers (consumer cells), groups of producers (producer cells), the government, and the rest of the world. We disaggregate the full circular flow of money, including consumer spending, labor compensation, firm profits, intermediates trade, foreign trade, and government transactions, while satisfying all national accounting identities. We implement the disaggregated system for small region-by-industry cells in Denmark and present stylized facts, such as variation in domestic spending, local and urban bias in consumer spending, and a pattern of triangular flows across regions. Cell-level measures of spending intensity capture how much spending by a cell contributes to the income of cells experiencing unemployment after a shock. Using a general equilibrium model, we show that fiscal transfers raise aggregate GDP by more when they target cells with high spending intensity on unemployed cells. The disaggregated economic accounts help governments select more effective policies.", "date": "2026-02-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag010", "title_zh": "\u5206\u9879\u7ecf\u6d4e\u8d26\u6237", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u6784\u5efa\u4e86\u4e00\u5957\u5206\u9879\u7ecf\u6d4e\u8d26\u6237\u4f53\u7cfb\u3002\u8be5\u4f53\u7cfb\u5c06\u56fd\u5bb6\u8d26\u6237\u4e2d\u7684\u5404\u9879\u4f4d\u7f6e\u5206\u89e3\u4e3a\u6d88\u8d39\u8005\u7fa4\u4f53\uff08\u6d88\u8d39\u8005\u5355\u5143\uff09\u3001\u751f\u4ea7\u8005\u7fa4\u4f53\uff08\u751f\u4ea7\u8005\u5355\u5143\uff09\u3001\u653f\u5e9c\u4ee5\u53ca\u4e16\u754c\u5176\u4ed6\u5730\u533a\u7684\u53cc\u8fb9\u6d41\u52a8\u3002\u6211\u4eec\u5bf9\u5b8c\u6574\u7684\u8d27\u5e01\u5faa\u73af\u6d41\u7a0b\u8fdb\u884c\u4e86\u5206\u9879\u5206\u89e3\uff0c\u5305\u62ec\u6d88\u8d39\u8005\u652f\u51fa\u3001\u52b3\u52a8\u62a5\u916c\u3001\u4f01\u4e1a\u5229\u6da6\u3001\u4e2d\u95f4\u54c1\u8d38\u6613\u3001\u56fd\u9645\u8d38\u6613\u548c\u653f\u5e9c\u4ea4\u6613\uff0c\u540c\u65f6\u6ee1\u8db3\u6240\u6709\u56fd\u5bb6\u4f1a\u8ba1\u6052\u7b49\u5f0f\u3002\u6211\u4eec\u4e3a\u4e39\u9ea6\u7684\u5730\u533a-\u884c\u4e1a\u5c42\u9762\u5355\u5143\u5b9e\u65bd\u4e86\u8be5\u5206\u9879\u4f53\u7cfb\uff0c\u5e76\u5448\u73b0\u4e86\u82e5\u5e72\u5178\u578b\u4e8b\u5b9e\uff0c\u4f8b\u5982\u56fd\u5185\u652f\u51fa\u7684\u5dee\u5f02\u3001\u6d88\u8d39\u8005\u652f\u51fa\u4e2d\u7684\u5730\u65b9\u6027\u548c\u57ce\u5e02\u504f\u5411\uff0c\u4ee5\u53ca\u5730\u533a\u95f4\u4e09\u89d2\u6d41\u52a8\u7684\u6a21\u5f0f\u3002\u5728\u5355\u5143\u5c42\u9762\u7684\u652f\u51fa\u5f3a\u5ea6\u6307\u6807\u80fd\u591f\u53cd\u6620\u67d0\u4e2a\u5355\u5143\u7684\u652f\u51fa\u5bf9\u5931\u4e1a\u540e\u5176\u4ed6\u5355\u5143\u6536\u5165\u7684\u8d21\u732e\u7a0b\u5ea6\u3002\u901a\u8fc7\u4e00\u822c\u5747\u8861\u6a21\u578b\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5f53\u8d22\u653f\u8f6c\u79fb\u652f\u4ed8\u9488\u5bf9\u5931\u4e1a\u5355\u5143\u4e2d\u652f\u51fa\u5f3a\u5ea6\u9ad8\u7684\u5355\u5143\u65f6\uff0c\u5bf9\u6574\u4f53GDP\u7684\u63d0\u5347\u66f4\u4e3a\u663e\u8457\u3002\u5206\u9879\u7ecf\u6d4e\u8d26\u6237\u6709\u52a9\u4e8e\u653f\u5e9c\u9009\u62e9\u66f4\u6709\u6548\u7684\u653f\u7b56\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102470", "journal": "JFQA", "title": "Does General Solicitation Improve Access to Equity Capital for Small Businesses? Evidence from the JOBS Act", "authors": ["Anup Agrawal", "Yuree Lim"], "author_details": [{"name": "Anup Agrawal", "affiliations": ["University of Alabama Culverhouse College of Business"]}, {"name": "Yuree Lim", "affiliations": ["Texas Woman\u2019s University Merrilee Alexander Kick College of Business & Entrepreneurship"]}], "abstract": "Abstract Under Title II of the Jumpstart Our Business Startups Act, firms can sell private placement securities to the public via general solicitation (GS) or privately (non-GS). We find that equity offerings under GS tend to be riskier than under non-GS. After accounting for selection, GS issuers are less likely to succeed in i) raising capital, ii) getting venture capital (VC) funding, and iii) exiting via IPO or mergers and acquisitions, and incur substantial brokerage costs for advertising and verifying investor accreditation. However, GS appears to help new entrants and offerings that use registered brokers. The success of Form D financing improves future VC financing and exit outcomes.", "date": "2026-02-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102470", "title_zh": "\u666e\u904d\u62db\u52df\u662f\u5426\u80fd\u6539\u5584\u4e2d\u5c0f\u4f01\u4e1a\u5bf9\u80a1\u6743\u8d44\u672c\u7684\u83b7\u53d6\uff1f\u6765\u81ea\u300a\u542f\u52a8\u4f01\u4e1a\u521b\u4e1a\u6cd5\u6848\u300b\u7684\u8bc1\u636e", "abstract_zh": "\u6458\u8981 \u6839\u636e\u300a\u542f\u52a8\u4f01\u4e1a\u521b\u4e1a\u6cd5\u6848\u300b\u7b2c\u4e8c\u6807\u9898\u7684\u89c4\u5b9a\uff0c\u4f01\u4e1a\u53ef\u4ee5\u901a\u8fc7\u666e\u904d\u62db\u52df\uff08GS\uff09\u6216\u79c1\u4e0b\u65b9\u5f0f\uff08\u975eGS\uff09\u5411\u516c\u4f17\u51fa\u552e\u79c1\u52df\u8bc1\u5238\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u901a\u8fc7\u666e\u904d\u62db\u52df\u8fdb\u884c\u7684\u80a1\u6743\u53d1\u884c\u901a\u5e38\u6bd4\u975e\u666e\u904d\u62db\u52df\u7684\u53d1\u884c\u98ce\u9669\u66f4\u9ad8\u3002\u5728\u8003\u8651\u9009\u62e9\u6027\u504f\u5dee\u540e\uff0c\u91c7\u7528GS\u7684\u53d1\u884c\u4eba\u66f4\u4e0d\u53ef\u80fd\u5b9e\u73b0\u4ee5\u4e0b\u76ee\u6807\uff1ai\uff09\u6210\u529f\u7b79\u96c6\u8d44\u672c\uff0cii\uff09\u83b7\u5f97\u98ce\u9669\u6295\u8d44\uff08VC\uff09\u8d44\u91d1\uff0ciii\uff09\u901a\u8fc7\u9996\u6b21\u516c\u5f00\u52df\u80a1\uff08IPO\uff09\u6216\u5e76\u8d2d\u5b9e\u73b0\u9000\u51fa\uff0c\u4e14\u9700\u627f\u62c5\u8f83\u9ad8\u7684\u7ecf\u7eaa\u8d39\u7528\u7528\u4e8e\u5e7f\u544a\u548c\u9a8c\u8bc1\u6295\u8d44\u8005\u8d44\u683c\u3002\u7136\u800c\uff0c\u666e\u904d\u62db\u52df\u4f3c\u4e4e\u6709\u52a9\u4e8e\u65b0\u8fdb\u5165\u8005\u4ee5\u53ca\u4f7f\u7528\u6ce8\u518c\u7ecf\u7eaa\u4eba\u7684\u53d1\u884c\u6d3b\u52a8\u3002Form D\u878d\u8d44\u7684\u6210\u529f\u80fd\u591f\u6539\u5584\u672a\u6765\u98ce\u9669\u6295\u8d44\u548c\u9000\u51fa\u7ed3\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1017/s0022109026102671", "journal": "JFQA", "title": "Dr Jekyll and Mr Hyde: Feedback and Welfare When Hedgers Can Acquire Information", "authors": ["Jacques Olivier"], "author_details": [{"name": "Jacques Olivier", "affiliations": ["HEC Paris"]}], "abstract": "Abstract I ask whether hedgers who speculate should be regulated differently from other speculators in a model where information acquisition is endogenous, and information has real effects. Hedging benefits and feedback effects generate strategic complementarities between market-maker, firm manager, and trader, which causes multiple equilibria. Gains from trade are lower when hedgers acquire information, while speculators may produce less information than socially desirable. A \u201cVolcker rule\u201d separating hedging and speculative activities may help select the higher welfare equilibrium. When too little information is produced, contracts whereby a firm subsidizes losses of designated market-makers (DMM) to make prices more informative increase welfare.", "date": "2026-02-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102671", "title_zh": "\u6770\u514b\u00b7\u4f26\u6566\u4e0e\u6d77\u5fb7\u5148\u751f\uff1a\u5f53\u5bf9\u51b2\u8005\u53ef\u4ee5\u83b7\u53d6\u4fe1\u606f\u65f6\uff0c\u53cd\u9988\u6548\u5e94\u4e0e\u798f\u5229\u95ee\u9898", "abstract_zh": "\u6211\u63a2\u8ba8\u5728\u4fe1\u606f\u83b7\u53d6\u662f\u5185\u751f\u7684\u3001\u4e14\u4fe1\u606f\u5177\u6709\u5b9e\u9645\u5f71\u54cd\u7684\u6a21\u578b\u4e2d\uff0c\u5bf9\u51b2\u8005\u6295\u673a\u884c\u4e3a\u662f\u5426\u5e94\u4e0e\u5176\u4ed6\u6295\u673a\u8005\u53d7\u5230\u4e0d\u540c\u7684\u76d1\u7ba1\u3002\u5bf9\u51b2\u5e26\u6765\u7684\u6536\u76ca\u548c\u53cd\u9988\u6548\u5e94\u5728\u5e02\u573a\u505a\u5e02\u5546\u3001\u4f01\u4e1a\u7ecf\u7406\u548c\u4ea4\u6613\u8005\u4e4b\u95f4\u4ea7\u751f\u6218\u7565\u4e92\u8865\u6027\uff0c\u5bfc\u81f4\u591a\u91cd\u5747\u8861\u3002\u5f53\u5bf9\u51b2\u8005\u83b7\u53d6\u4fe1\u606f\u65f6\uff0c\u4ea4\u6613\u5e26\u6765\u7684\u6536\u76ca\u4e0b\u964d\uff0c\u800c\u6295\u673a\u8005\u53ef\u80fd\u4ea7\u751f\u7684\u4fe1\u606f\u91cf\u4f4e\u4e8e\u793e\u4f1a\u6240\u671f\u671b\u7684\u6c34\u5e73\u3002\u4e00\u79cd\u5c06\u5bf9\u51b2\u4e0e\u6295\u673a\u6d3b\u52a8\u5206\u5f00\u7684\u2018\u6c83\u5c14\u514b\u89c4\u5219\u2019\u53ef\u80fd\u6709\u52a9\u4e8e\u9009\u62e9\u66f4\u9ad8\u798f\u5229\u7684\u5747\u8861\u3002\u5f53\u4fe1\u606f\u4ea7\u751f\u4e0d\u8db3\u65f6\uff0c\u901a\u8fc7\u4f01\u4e1a\u5bf9\u6307\u5b9a\u505a\u5e02\u5546\uff08DMM\uff09\u7684\u635f\u5931\u8fdb\u884c\u8865\u8d34\u7684\u5408\u540c\uff0c\u53ef\u4ee5\u63d0\u5347\u4ef7\u683c\u7684\u53ef\u4fe1\u606f\u6027\uff0c\u4ece\u800c\u63d0\u9ad8\u798f\u5229\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e02\u573a\u53cd\u9988"]}, {"doi": "10.1017/s002210902610266x", "journal": "JFQA", "title": "A Shared Interest: Do Bonds Strengthen Equity Monitoring?", "authors": ["Todd A. Gormley", "Manish Jha"], "author_details": [{"name": "Todd A. Gormley", "affiliations": ["Washington University in Saint Louis and National Bureau of Economic Research"]}, {"name": "Manish Jha", "affiliations": ["Georgia State University"]}], "abstract": "Abstract Institutional investors conduct more governance research and are less likely to follow proxy advisor vote recommendations when a company\u2019s bonds comprise a larger share of their assets. These findings are driven by bond holdings, shareholder proposals, and companies where fixed-income managers are more likely to be attentive and share an interest with equity investors in improving governance. The findings do not concentrate on companies or shareholder proposals where creditor\u2013shareholder conflicts are likely. Overall, the findings suggest that corporate bond holdings influence how actively institutions monitor their equity positions and contribute to institutions\u2019 overall incentive to be engaged stewards.", "date": "2026-02-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s002210902610266x", "title_zh": "\u5171\u540c\u5229\u76ca\uff1a\u503a\u5238\u662f\u5426\u589e\u5f3a\u4e86\u80a1\u6743\u76d1\u7763\uff1f", "abstract_zh": "\u673a\u6784\u6295\u8d44\u8005\u5728\u516c\u53f8\u503a\u5238\u5360\u5176\u8d44\u4ea7\u6bd4\u4f8b\u8f83\u5927\u7684\u60c5\u51b5\u4e0b\uff0c\u4f1a\u8fdb\u884c\u66f4\u591a\u7684\u516c\u53f8\u6cbb\u7406\u7814\u7a76\uff0c\u5e76\u4e14\u66f4\u5c11\u5730\u9075\u5faa\u4ee3\u7406\u987e\u95ee\u7684\u6295\u7968\u5efa\u8bae\u3002\u8fd9\u4e9b\u53d1\u73b0\u6e90\u4e8e\u503a\u5238\u6301\u4ed3\u3001\u80a1\u4e1c\u63d0\u6848\u4ee5\u53ca\u56fa\u5b9a\u6536\u76ca\u7ecf\u7406\u66f4\u5173\u6ce8\u4e14\u4e0e\u80a1\u6743\u6295\u8d44\u8005\u5177\u6709\u5171\u540c\u5229\u76ca\u4ee5\u6539\u5584\u516c\u53f8\u6cbb\u7406\u7684\u516c\u53f8\u3002\u8fd9\u4e9b\u53d1\u73b0\u5e76\u672a\u96c6\u4e2d\u5728\u503a\u6743\u4eba\u4e0e\u80a1\u4e1c\u4e4b\u95f4\u53ef\u80fd\u5b58\u5728\u51b2\u7a81\u7684\u516c\u53f8\u6216\u80a1\u4e1c\u63d0\u6848\u4e0a\u3002\u603b\u4f53\u800c\u8a00\uff0c\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u516c\u53f8\u503a\u5238\u6301\u4ed3\u4f1a\u5f71\u54cd\u673a\u6784\u5bf9\u80a1\u6743\u6301\u4ed3\u7684\u4e3b\u52a8\u76d1\u7763\u7a0b\u5ea6\uff0c\u5e76\u589e\u5f3a\u4e86\u673a\u6784\u4f5c\u4e3a\u79ef\u6781\u53c2\u4e0e\u6cbb\u7406\u65b9\u7684\u6574\u4f53\u6fc0\u52b1\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1111/jofi.70022", "journal": "JF", "title": "Carbon Pricing versus Green Finance", "authors": ["LASSE HEJE PEDERSEN"], "author_details": [{"name": "LASSE HEJE PEDERSEN", "affiliations": []}], "abstract": "ABSTRACT Green finance\u2014including environmental, social, and governance investing and sustainable finance regulations\u2014is widespread, but can it substitute for carbon pricing in fighting climate change? In a unified model, I show that (i) when carbon prices reflect the social cost of carbon, green finance should not be used; (ii) when carbon prices are too low, green finance can implement the social optimum if each firm's cost of capital can be set to its sustainable discount rate , which increases with the ratio of carbon emissions to firm value. I provide calibrations, analyze stranded assets, and present implementations through subsidies or preferential financing for green firms.", "date": "2026-02-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70022", "title_zh": "\u78b3\u5b9a\u4ef7\u4e0e\u7eff\u8272\u91d1\u878d", "abstract_zh": "\u6458\u8981 \u7eff\u8272\u91d1\u878d\u2014\u2014\u5305\u62ec\u73af\u5883\u3001\u793e\u4f1a\u548c\u6cbb\u7406\u6295\u8d44\u4ee5\u53ca\u53ef\u6301\u7eed\u91d1\u878d\u76d1\u7ba1\u2014\u2014\u5df2\u5e7f\u6cdb\u5b58\u5728\uff0c\u4f46\u5b83\u80fd\u5426\u66ff\u4ee3\u78b3\u5b9a\u4ef7\u4ee5\u5e94\u5bf9\u6c14\u5019\u53d8\u5316\uff1f\u5728\u7edf\u4e00\u6a21\u578b\u4e2d\uff0c\u6211\u8868\u660e\uff1a\uff08i\uff09\u5f53\u78b3\u4ef7\u53cd\u6620\u793e\u4f1a\u78b3\u6210\u672c\u65f6\uff0c\u4e0d\u5e94\u4f7f\u7528\u7eff\u8272\u91d1\u878d\uff1b\uff08ii\uff09\u5f53\u78b3\u4ef7\u8fc7\u4f4e\u65f6\uff0c\u82e5\u6bcf\u5bb6\u4f01\u4e1a\u7684\u8d44\u672c\u6210\u672c\u53ef\u8bbe\u5b9a\u4e3a\u5176\u53ef\u6301\u7eed\u6298\u73b0\u7387\uff0c\u4e14\u8be5\u6298\u73b0\u7387\u968f\u78b3\u6392\u653e\u4e0e\u4f01\u4e1a\u4ef7\u503c\u4e4b\u6bd4\u7684\u4e0a\u5347\u800c\u589e\u52a0\uff0c\u5219\u7eff\u8272\u91d1\u878d\u53ef\u4ee5\u5b9e\u73b0\u793e\u4f1a\u6700\u4f18\u3002\u6211\u63d0\u4f9b\u4e86\u53c2\u6570\u6821\u51c6\uff0c\u5206\u6790\u4e86\u6401\u6d45\u8d44\u4ea7\uff0c\u5e76\u901a\u8fc7\u4e3a\u7eff\u8272\u4f01\u4e1a\u63d0\u4f9b\u7684\u8865\u8d34\u6216\u4f18\u5148\u878d\u8d44\u65b9\u6848\u63d0\u51fa\u4e86\u5b9e\u65bd\u8def\u5f84\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1111/jofi.70028", "journal": "JF", "title": "Competition Enforcement and Accounting for Intangible Capital", "authors": ["JOHN D. KEPLER", "CHARLES G. MCCLURE", "CHRISTOPHER R. STEWART"], "author_details": [{"name": "JOHN D. KEPLER", "affiliations": []}, {"name": "CHARLES G. MCCLURE", "affiliations": []}, {"name": "CHRISTOPHER R. STEWART", "affiliations": []}], "abstract": "ABSTRACT Antitrust laws mandate review of mergers and acquisitions (M&As) that exceed an asset size threshold based on accounting standards that exclude most intangible capital. We show that this exclusion leads to thousands of intangible\u2010intensive M&As being nonreportable. Acquirers in nonreportable deals achieve higher equity values and price markups, especially when consolidating product markets. Furthermore, nonreportable pharmaceutical deals are three times more likely to involve overlapping drug projects, which are subsequently 40% more likely to be terminated. Our results suggest that the growth of intangible assets may exacerbate market power through nonreportable consolidation of the sectors most concerning for consumers.", "date": "2026-02-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70028", "title_zh": "\u7ade\u4e89\u6267\u6cd5\u4e0e\u65e0\u5f62\u8d44\u672c\u7684\u4f1a\u8ba1\u5904\u7406", "abstract_zh": "\u6458\u8981 \u53cd\u5784\u65ad\u6cd5\u8981\u6c42\u5bf9\u8d85\u8fc7\u8d44\u4ea7\u89c4\u6a21\u9608\u503c\u7684\u5e76\u8d2d\u4ea4\u6613\u8fdb\u884c\u5ba1\u67e5\uff0c\u800c\u73b0\u884c\u4f1a\u8ba1\u6807\u51c6\u5927\u591a\u6392\u9664\u4e86\u65e0\u5f62\u8d44\u672c\u7684\u8ba1\u91cf\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u79cd\u6392\u9664\u5bfc\u81f4\u6570\u5343\u7b14\u4ee5\u65e0\u5f62\u8d44\u4ea7\u4e3a\u4e3b\u5bfc\u7684\u5e76\u8d2d\u4ea4\u6613\u65e0\u6cd5\u88ab\u62a5\u544a\u3002\u5728\u65e0\u6cd5\u62a5\u544a\u7684\u4ea4\u6613\u4e2d\uff0c\u6536\u8d2d\u65b9\u5b9e\u73b0\u7684\u80a1\u6743\u4ef7\u503c\u548c\u4ef7\u683c\u6ea2\u4ef7\u66f4\u9ad8\uff0c\u5c24\u5176\u662f\u5728\u5408\u5e76\u4ea7\u54c1\u5e02\u573a\u7684\u60c5\u51b5\u4e0b\u3002\u6b64\u5916\uff0c\u672a\u88ab\u62a5\u544a\u7684\u5236\u836f\u884c\u4e1a\u5e76\u8d2d\u4ea4\u6613\u4e2d\uff0c\u5b58\u5728\u91cd\u53e0\u836f\u7269\u9879\u76ee\u7684\u53ef\u80fd\u6027\u662f\u666e\u901a\u60c5\u51b5\u7684\u4e09\u500d\uff0c\u800c\u8fd9\u4e9b\u91cd\u53e0\u9879\u76ee\u540e\u7eed\u88ab\u7ec8\u6b62\u7684\u6982\u7387\u9ad8\u51fa40%\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u65e0\u5f62\u8d44\u4ea7\u7684\u589e\u957f\u53ef\u80fd\u901a\u8fc7\u672a\u88ab\u62a5\u544a\u7684\u5e02\u573a\u96c6\u4e2d\u884c\u4e3a\uff0c\u52a0\u5267\u5bf9\u6d88\u8d39\u8005\u6700\u4e0d\u5229\u884c\u4e1a\u7684\u5e02\u573a\u529b\u91cf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1017/s0022109026102609", "journal": "JFQA", "title": "Is the Value Premium Dead? Forecasting Value\u2013Growth Cycles with the Implied Value Premium", "authors": ["Yan Li", "David Tat-Chee Ng", "Bhaskaran Swaminathan"], "author_details": [{"name": "Yan Li", "affiliations": ["Temple University"]}, {"name": "David Tat-Chee Ng", "affiliations": ["Cornell University Johnson College of Business Dyson School"]}, {"name": "Bhaskaran Swaminathan", "affiliations": []}], "abstract": "Abstract We introduce the implied value premium ( IVP ), the difference between the implied costs of capital of value and growth stocks, to predict time variation in the ex post value premium. During 1977\u20132023, IVP is the strongest predictor of the ex post value premium. It also predicts the investment premium, consistent with the Investment CAPM. However, IVP \u2019s ability to predict the difference in cumulative abnormal returns around quarterly earnings announcements of value and growth stocks suggests that mispricing may also play a role. Overall, our results suggest that recent value underperformance reflects cyclical variation rather than a permanent shift.", "date": "2026-02-04", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102609", "title_zh": "\u4ef7\u503c\u6ea2\u4ef7\u662f\u5426\u5df2\u7ec8\u7ed3\uff1f\u57fa\u4e8e\u9690\u542b\u4ef7\u503c\u6ea2\u4ef7\u7684\u4f30\u503c-\u589e\u957f\u5468\u671f\u9884\u6d4b", "abstract_zh": "\u6211\u4eec\u5f15\u5165\u4e86\u9690\u542b\u4ef7\u503c\u6ea2\u4ef7\uff08IVP\uff09\uff0c\u5373\u4ef7\u503c\u80a1\u4e0e\u6210\u957f\u80a1\u9690\u542b\u8d44\u672c\u6210\u672c\u4e4b\u95f4\u7684\u5dee\u5f02\uff0c\u4ee5\u9884\u6d4b\u5916\u751f\u4ef7\u503c\u6ea2\u4ef7\u7684\u65f6\u95f4\u53d8\u5316\u3002\u57281977\u5e74\u81f32023\u5e74\u671f\u95f4\uff0cIVP\u662f\u9884\u6d4b\u5916\u751f\u4ef7\u503c\u6ea2\u4ef7\u6700\u5f3a\u7684\u6307\u6807\u3002\u5b83\u4e5f\u80fd\u591f\u9884\u6d4b\u6295\u8d44\u6ea2\u4ef7\uff0c\u8fd9\u4e0e\u6295\u8d44CAPM\u4e00\u81f4\u3002\u7136\u800c\uff0cIVP\u5bf9\u4ef7\u503c\u80a1\u4e0e\u6210\u957f\u80a1\u5728\u5b63\u5ea6\u8d22\u62a5\u516c\u544a\u524d\u540e\u7d2f\u8ba1\u5f02\u5e38\u6536\u76ca\u7387\u5dee\u5f02\u7684\u9884\u6d4b\u8868\u660e\uff0c\u5b9a\u4ef7\u9519\u8bef\u4e5f\u53ef\u80fd\u53d1\u6325\u4f5c\u7528\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u8fd1\u671f\u4ef7\u503c\u80a1\u8868\u73b0\u4e0d\u4f73\u662f\u5468\u671f\u6027\u6ce2\u52a8\u6240\u81f4\uff0c\u800c\u975e\u6c38\u4e45\u6027\u8f6c\u53d8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag005", "journal": "QJE", "title": "Insuring Peace: Index-Based Livestock Insurance, Droughts, and Conflict", "authors": ["Kai Gehring", "Paul Schaudt"], "author_details": [{"name": "Kai Gehring", "affiliations": ["Wyss Academy for Nature, University of Bern, and CESifo ,"]}, {"name": "Paul Schaudt", "affiliations": ["KU Leuven ,"]}], "abstract": "Abstract We provide quasi-experimental evidence of how an innovative market-based solution using remote-sensing technology can mitigate drought-induced conflict. Droughts are a major driver of conflict in Africa, particularly between transhumant pastoralists and sedentary farmers. Index-Based Livestock Insurance (IBLI), a program piloted in Kenya, provides automated, preemptive payouts to pastoralists affected by droughts. Combining variation in rainfall and the staggered rollout of IBLI in Kenya over 2000\u20132020, we find that IBLI strongly reduces drought-induced conflict. Key mechanisms include a reduction in herd sizes, as well as income smoothing and asset price stabilization, contributing to an overall reduced migratory pressure for pastoralists. Our study suggests that market-based solutions are a scalable, cost-effective pathway to mitigate conflict, complementing political solutions such as power-sharing agreements and institutional reforms.", "date": "2026-02-02", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag005", "title_zh": "\u4fdd\u9669\u548c\u5e73\uff1a\u57fa\u4e8e\u6307\u6570\u7684\u7272\u755c\u4fdd\u9669\u3001\u5e72\u65f1\u4e0e\u51b2\u7a81", "abstract_zh": "\u6211\u4eec\u63d0\u4f9b\u4e86\u5173\u4e8e\u4e00\u79cd\u5229\u7528\u9065\u611f\u6280\u672f\u7684\u521b\u65b0\u5e02\u573a\u89e3\u51b3\u65b9\u6848\u5982\u4f55\u7f13\u89e3\u5e72\u65f1\u5f15\u53d1\u51b2\u7a81\u7684\u51c6\u5b9e\u9a8c\u8bc1\u636e\u3002\u5e72\u65f1\u662f\u975e\u6d32\u51b2\u7a81\u7684\u4e3b\u8981\u9a71\u52a8\u56e0\u7d20\uff0c\u5c24\u5176\u662f\u5728\u6e38\u7267\u7267\u6c11\u4e0e\u5b9a\u5c45\u519c\u6c11\u4e4b\u95f4\u3002\u57fa\u4e8e\u6307\u6570\u7684\u7272\u755c\u4fdd\u9669\uff08IBLI\uff09\u662f\u4e00\u9879\u5728\u80af\u5c3c\u4e9a\u8bd5\u70b9\u7684\u9879\u76ee\uff0c\u5b83\u4e3a\u53d7\u5e72\u65f1\u5f71\u54cd\u7684\u7267\u6c11\u63d0\u4f9b\u81ea\u52a8\u5316\u7684\u3001\u4e8b\u524d\u8d54\u4ed8\u3002\u7ed3\u5408\u964d\u96e8\u91cf\u7684\u53d8\u5316\u4ee5\u53caIBLI\u57282000\u5e74\u81f32020\u5e74\u95f4\u5206\u9636\u6bb5\u5b9e\u65bd\u7684\u5dee\u5f02\uff0c\u6211\u4eec\u53d1\u73b0IBLI\u663e\u8457\u51cf\u5c11\u4e86\u7531\u5e72\u65f1\u5f15\u53d1\u7684\u51b2\u7a81\u3002\u5173\u952e\u673a\u5236\u5305\u62ec\u7272\u755c\u6570\u91cf\u7684\u51cf\u5c11\uff0c\u4ee5\u53ca\u6536\u5165\u5e73\u6ed1\u548c\u8d44\u4ea7\u4ef7\u683c\u7a33\u5b9a\uff0c\u4ece\u800c\u6574\u4f53\u4e0a\u964d\u4f4e\u4e86\u7267\u6c11\u7684\u8fc1\u5f99\u538b\u529b\u3002\u6211\u4eec\u7684\u7814\u7a76\u8868\u660e\uff0c\u5e02\u573a\u89e3\u51b3\u65b9\u6848\u662f\u4e00\u79cd\u53ef\u6269\u5c55\u4e14\u6210\u672c\u6548\u76ca\u9ad8\u7684\u7f13\u89e3\u51b2\u7a81\u9014\u5f84\uff0c\u53ef\u4ee5\u8865\u5145\u653f\u6cbb\u89e3\u51b3\u65b9\u6848\uff0c\u5982\u6743\u529b\u5171\u4eab\u534f\u8bae\u548c\u5236\u5ea6\u6539\u9769\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/restud/rdag009", "journal": "REStud", "title": "Organizational Change and Reference-Dependent Preferences", "authors": ["Klaus M Schmidt", "Jonas von Wangenheim"], "author_details": [{"name": "Klaus M Schmidt", "affiliations": ["Department of Economics, University of Munich , M\u00fcnchen ,", "CESifo, and CEPR"]}, {"name": "Jonas von Wangenheim", "affiliations": ["Department of Economics, University of Bonn , Bonn ,"]}], "abstract": "Abstract Reference-dependent preferences can explain several puzzling observations about organizational change. We introduce a dynamic model in which a firm bargains with loss-averse workers about organizational change and wages. We show that change is often stagnant or slow for many periods, followed by a sudden boost in productivity triggered by a crisis. In a crisis, workers concede to organizational change but resist nominal wage reductions. In addition, the model explains why different firms in the same industry often have significant productivity differences. Finally, the model demonstrates the importance of expectations management even if all parties have rational expectations.", "date": "2026-02-02", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag009", "title_zh": "\u7ec4\u7ec7\u53d8\u9769\u4e0e\u53c2\u7167\u4f9d\u8d56\u504f\u597d", "abstract_zh": "\u53c2\u7167\u4f9d\u8d56\u504f\u597d\u53ef\u4ee5\u89e3\u91ca\u5173\u4e8e\u7ec4\u7ec7\u53d8\u9769\u7684\u591a\u4e2a\u4ee4\u4eba\u56f0\u60d1\u7684\u89c2\u5bdf\u73b0\u8c61\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u52a8\u6001\u6a21\u578b\uff0c\u5176\u4e2d\u4f01\u4e1a\u4e0e\u635f\u5931\u538c\u6076\u7684\u5458\u5de5\u5c31\u7ec4\u7ec7\u53d8\u9769\u548c\u5de5\u8d44\u8fdb\u884c\u8c08\u5224\u3002\u6a21\u578b\u663e\u793a\uff0c\u7ec4\u7ec7\u53d8\u9769\u5f80\u5f80\u5728\u8bb8\u591a\u65f6\u671f\u5185\u505c\u6ede\u6216\u8fdb\u5c55\u7f13\u6162\uff0c\u968f\u540e\u5728\u5371\u673a\u4e2d\u7a81\u7136\u51fa\u73b0\u751f\u4ea7\u529b\u7684\u63d0\u5347\u3002\u5728\u5371\u673a\u4e2d\uff0c\u5458\u5de5\u613f\u610f\u63a5\u53d7\u7ec4\u7ec7\u53d8\u9769\uff0c\u4f46\u62b5\u5236\u540d\u4e49\u5de5\u8d44\u7684\u524a\u51cf\u3002\u6b64\u5916\uff0c\u8be5\u6a21\u578b\u89e3\u91ca\u4e86\u4e3a\u4f55\u540c\u4e00\u884c\u4e1a\u5185\u7684\u4e0d\u540c\u4f01\u4e1a\u5f80\u5f80\u5b58\u5728\u663e\u8457\u7684\u751f\u4ea7\u529b\u5dee\u5f02\u3002\u6700\u540e\uff0c\u6a21\u578b\u8868\u660e\uff0c\u5373\u4f7f\u6240\u6709\u53c2\u4e0e\u8005\u90fd\u5177\u6709\u7406\u6027\u9884\u671f\uff0c\u9884\u671f\u7ba1\u7406\u4ecd\u7136\u5177\u6709\u91cd\u8981\u610f\u4e49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102646", "journal": "JFQA", "title": "Depositing Corporate Payout", "authors": ["Leming Lin"], "author_details": [{"name": "Leming Lin", "affiliations": ["University of Pittsburgh"]}], "abstract": "Abstract This article studies the flow of payout funds in the financial system. Using various data sources and empirical strategies, it provides evidence that a significant portion of payouts enters the banking sector as deposits, which are then intermediated to bank borrowers. The findings highlight an important channel through which corporate payout policies shape capital allocation in the economy and suggest that policies aimed at restricting payouts may distort this process by limiting the flow of funds from large and profitable corporations to small, bank-dependent firms and households.", "date": "2026-02-02", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102646", "title_zh": "\u4f01\u4e1a\u5206\u7ea2\u8d44\u91d1\u7684\u5b58\u5165", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u4f01\u4e1a\u5206\u7ea2\u8d44\u91d1\u5728\u91d1\u878d\u4f53\u7cfb\u4e2d\u7684\u6d41\u52a8\u60c5\u51b5\u3002\u5229\u7528\u591a\u79cd\u6570\u636e\u6765\u6e90\u548c\u5b9e\u8bc1\u65b9\u6cd5\uff0c\u7814\u7a76\u53d1\u73b0\u76f8\u5f53\u4e00\u90e8\u5206\u5206\u7ea2\u8d44\u91d1\u4ee5\u5b58\u6b3e\u5f62\u5f0f\u8fdb\u5165\u94f6\u884c\u4f53\u7cfb\uff0c\u968f\u540e\u88ab\u8f6c\u4ecb\u7ed9\u94f6\u884c\u8d37\u6b3e\u501f\u6b3e\u4eba\u3002\u7814\u7a76\u7ed3\u679c\u51f8\u663e\u4e86\u4f01\u4e1a\u5206\u7ea2\u653f\u7b56\u5728\u7ecf\u6d4e\u8d44\u672c\u914d\u7f6e\u4e2d\u7684\u4e00\u4e2a\u91cd\u8981\u6e20\u9053\uff0c\u5e76\u8868\u660e\u65e8\u5728\u9650\u5236\u5206\u7ea2\u7684\u653f\u7b56\u53ef\u80fd\u4f1a\u901a\u8fc7\u9650\u5236\u5927\u989d\u76c8\u5229\u4f01\u4e1a\u8d44\u91d1\u6d41\u5411\u4f9d\u8d56\u94f6\u884c\u7684\u5c0f\u578b\u4f01\u4e1a\u53ca\u5bb6\u5ead\uff0c\u4ece\u800c\u626d\u66f2\u8fd9\u4e00\u8fc7\u7a0b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20230432", "journal": "AER", "title": "Consumer Credit and the Incidence of Tariffs: Evidence from the Auto Industry", "authors": ["Kristine W. Hankins", "Morteza Momeni", "David Sovich"], "author_details": [{"name": "Kristine W. Hankins", "affiliations": ["University of Kentucky (email: )"]}, {"name": "Morteza Momeni", "affiliations": ["Tennessee Tech University (email: )"]}, {"name": "David Sovich", "affiliations": ["University of Kentucky (email: )"]}], "abstract": "Captive finance subsidiaries create a channel for trade policy to affect consumer credit. Examining the impact of the Trump administration\u2019s metal tariffs on captive automobile lenders, we find that consumers received higher interest rates from captive lenders after the tariffs relative to unaffected noncaptive lenders. Further, we document a disparate impact on low-income borrowers and in areas with less lending competition. Our results suggest that tariffs may impact not only the price of goods but also the financing terms of purchases. Thus, focusing solely on directly affected product prices may underestimate tariff pass-through significantly. (JEL F13, F14, G21, L22, L61, L62)", "date": "2026-02-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230432", "title_zh": "\u6d88\u8d39\u8005\u4fe1\u8d37\u4e0e\u5173\u7a0e\u5f71\u54cd\uff1a\u6765\u81ea\u6c7d\u8f66\u884c\u4e1a\u7684\u8bc1\u636e", "abstract_zh": "\u9644\u5c5e\u91d1\u878d\u5b50\u516c\u53f8\u4e3a\u8d38\u6613\u653f\u7b56\u5f71\u54cd\u6d88\u8d39\u8005\u4fe1\u8d37\u63d0\u4f9b\u4e86\u6e20\u9053\u3002\u6211\u4eec\u7814\u7a76\u4e86\u7279\u6717\u666e\u653f\u5e9c\u5bf9\u91d1\u5c5e\u5f81\u6536\u5173\u7a0e\u5bf9\u9644\u5c5e\u6c7d\u8f66\u8d37\u6b3e\u673a\u6784\u7684\u5f71\u54cd\uff0c\u53d1\u73b0\u6d88\u8d39\u8005\u5728\u5173\u7a0e\u5b9e\u65bd\u540e\u4ece\u9644\u5c5e\u8d37\u6b3e\u673a\u6784\u83b7\u5f97\u7684\u5229\u7387\u9ad8\u4e8e\u672a\u53d7\u5f71\u54cd\u7684\u975e\u9644\u5c5e\u8d37\u6b3e\u673a\u6784\u3002\u6b64\u5916\uff0c\u6211\u4eec\u53d1\u73b0\u4f4e\u6536\u5165\u501f\u6b3e\u4eba\u4ee5\u53ca\u8d37\u6b3e\u7ade\u4e89\u8f83\u5c11\u5730\u533a\u7684\u6d88\u8d39\u8005\u53d7\u5230\u7684\u51b2\u51fb\u66f4\u4e3a\u663e\u8457\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u5173\u7a0e\u4e0d\u4ec5\u4f1a\u5f71\u54cd\u5546\u54c1\u4ef7\u683c\uff0c\u8fd8\u53ef\u80fd\u5f71\u54cd\u8d2d\u4e70\u7684\u878d\u8d44\u6761\u4ef6\u3002\u56e0\u6b64\uff0c\u4ec5\u5173\u6ce8\u76f4\u63a5\u53d7\u5f71\u54cd\u4ea7\u54c1\u4ef7\u683c\u53ef\u80fd\u4f1a\u663e\u8457\u4f4e\u4f30\u5173\u7a0e\u7684\u4f20\u5bfc\u6548\u679c\u3002\uff08JEL F13, F14, G21, L22, L61, L62\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.1257/aer.20231619", "journal": "AER", "title": "Work from Home and the Office Real Estate Apocalypse", "authors": ["Arpit Gupta", "Vrinda Mittal", "Stijn Van Nieuwerburgh"], "author_details": [{"name": "Arpit Gupta", "affiliations": ["Department of Finance, NYU Stern School of Business (email: )"]}, {"name": "Vrinda Mittal", "affiliations": ["Department of Finance, Kenan-Flagler Business School, University of North Carolina at Chapel Hill (email: )"]}, {"name": "Stijn Van Nieuwerburgh", "affiliations": ["Columbia University Graduate School of Business, NBER, and CEPR (email: )"]}], "abstract": "We show remote work led to large drops in lease revenues, occupancy, and market rents in the commercial office sector. We revalue New York City office buildings, taking into account both the cash flow and discount rate implications of these shocks, and find a 46 percent decline in long-run value. For all US office markets combined, we find a $556.8 billion value destruction. Higher-quality buildings were buffered against these trends due to a flight to quality, while lower-quality offices are at risk of becoming a stranded asset. These valuation changes have repercussions for financial stability and local public finances. (JEL E31, E32, G12, J22, M51, R33)", "date": "2026-02-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20231619", "title_zh": "\u8fdc\u7a0b\u529e\u516c\u4e0e\u529e\u516c\u5ba4\u623f\u5730\u4ea7\u7684\u7ec8\u7ed3", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\u8fdc\u7a0b\u529e\u516c\u5bfc\u81f4\u5546\u4e1a\u529e\u516c\u9886\u57df\u79df\u8d41\u6536\u5165\u3001 occupancy\uff08\u5360\u7528\u7387\uff09\u548c\u5e02\u573a\u79df\u91d1\u5927\u5e45\u4e0b\u964d\u3002\u6211\u4eec\u91cd\u65b0\u8bc4\u4f30\u4e86\u7ebd\u7ea6\u5e02\u7684\u529e\u516c\u697c\uff0c\u8003\u8651\u4e86\u8fd9\u4e9b\u51b2\u51fb\u5bf9\u73b0\u91d1\u6d41\u548c\u6298\u73b0\u7387\u7684\u5f71\u54cd\uff0c\u53d1\u73b0\u5176\u957f\u671f\u4ef7\u503c\u4e0b\u964d\u4e8646%\u3002\u5bf9\u4e8e\u5168\u7f8e\u6240\u6709\u529e\u516c\u5e02\u573a\u5408\u8ba1\uff0c\u6211\u4eec\u53d1\u73b0\u4ef7\u503c\u635f\u5931\u8fbe5568\u4ebf\u7f8e\u5143\u3002\u9ad8\u8d28\u91cf\u5efa\u7b51\u7531\u4e8e\u2018\u8d8b\u4f18\u907f\u52a3\u2019\u6548\u5e94\u800c\u53d7\u5230\u7f13\u51b2\uff0c\u800c\u4f4e\u8d28\u91cf\u529e\u516c\u697c\u5219\u9762\u4e34\u6210\u4e3a\u6401\u6d45\u8d44\u4ea7\u7684\u98ce\u9669\u3002\u8fd9\u4e9b\u4f30\u503c\u53d8\u5316\u5bf9\u91d1\u878d\u7a33\u5b9a\u548c\u5730\u65b9\u516c\u5171\u8d22\u653f\u4ea7\u751f\u4e86\u5f71\u54cd\u3002\uff08JEL E31, E32, G12, J22, M51, R33\uff09", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1257/aer.20230264", "journal": "AER", "title": "Take the Goods and Run: Contracting Frictions and Market Power in Supply Chains", "authors": ["Felipe Brugu\u00e9s"], "author_details": [{"name": "Felipe Brugu\u00e9s", "affiliations": ["The Business School, Instituto Tecnol\u00f3gico Aut\u00f3nomo de M\u00e9xico (email: )"]}], "abstract": "This paper studies the efficiency of self-enforced relational agreements, a common solution to contracting frictions, when sellers have market power and contracts cannot be externally enforced. To this end, I develop a dynamic contracting model with limited enforcement in which buyers can default on their trade credit debt and estimate it using a novel dataset from the Ecuadorian manufacturing supply chain. The key empirical finding is that bilateral trade is inefficiently low in early periods of the relationship, but converges toward efficiency over time, despite sellers\u2019 market power. Counterfactual simulations imply that both market power and enforcement contribute to inefficiencies in trade. (JEL D86, G32, K12, L14, L60, O14)", "date": "2026-02-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20230264", "title_zh": "\u5e26\u8d70\u8d27\u7269\u5e76\u9003\u8dd1\uff1a\u4f9b\u5e94\u94fe\u4e2d\u5408\u540c\u6469\u64e6\u4e0e\u5e02\u573a\u529b\u91cf", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5f53\u5356\u65b9\u5177\u6709\u5e02\u573a\u529b\u91cf\u4e14\u5408\u540c\u65e0\u6cd5\u5916\u90e8\u6267\u884c\u65f6\uff0c\u81ea\u6211\u6267\u884c\u7684\u5173\u8054\u534f\u8bae\u6548\u7387\u95ee\u9898\uff0c\u8fd9\u662f\u4e00\u79cd\u89e3\u51b3\u5408\u540c\u6469\u64e6\u7684\u5e38\u89c1\u65b9\u6848\u3002\u4e3a\u6b64\uff0c\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u5177\u6709\u6709\u9650\u6267\u884c\u80fd\u529b\u7684\u52a8\u6001\u5408\u540c\u6a21\u578b\uff0c\u5176\u4e2d\u4e70\u65b9\u53ef\u4ee5\u8fdd\u7ea6\u5e76\u5bf9\u5176\u8d38\u6613\u4fe1\u7528\u503a\u52a1\u8fdb\u884c\u4f30\u8ba1\uff0c\u4f7f\u7528\u6765\u81ea\u5384\u74dc\u591a\u5c14\u5236\u9020\u4e1a\u4f9b\u5e94\u94fe\u7684\u4e00\u4e2a\u65b0\u9896\u6570\u636e\u96c6\u3002\u4e3b\u8981\u5b9e\u8bc1\u53d1\u73b0\u662f\uff0c\u5728\u5173\u7cfb\u65e9\u671f\u9636\u6bb5\uff0c\u53cc\u8fb9\u8d38\u6613\u6548\u7387\u504f\u4f4e\uff0c\u4f46\u968f\u7740\u65f6\u95f4\u63a8\u79fb\u9010\u6e10\u8d8b\u4e8e\u6548\u7387\uff0c\u5373\u4f7f\u5356\u65b9\u5177\u6709\u5e02\u573a\u529b\u91cf\u3002\u53cd\u4e8b\u5b9e\u6a21\u62df\u8868\u660e\uff0c\u5e02\u573a\u529b\u91cf\u548c\u6267\u884c\u80fd\u529b\u5747\u4f1a\u52a0\u5267\u8d38\u6613\u7684\u4f4e\u6548\u6027\u3002\uff08JEL D86, G32, K12, L14, L60, O14\uff09", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1257/aer.20211324", "journal": "AER", "title": "Raising the Stakes: Physician Facility Investments and Provider Agency", "authors": ["Elizabeth L. Munnich", "Michael R. Richards", "Christopher M. Whaley", "Xiaoxi Zhao"], "author_details": [{"name": "Elizabeth L. Munnich", "affiliations": ["Department of Economics, University of Louisville (email: )"]}, {"name": "Michael R. Richards", "affiliations": ["Jeb E. Brooks School of Public Policy, Cornell University, and NBER (email: )"]}, {"name": "Christopher M. Whaley", "affiliations": ["Department of Health Services, Policy, and Practice, School of Public Health, Brown University (email: )"]}, {"name": "Xiaoxi Zhao", "affiliations": ["RAND Corporation (email: )"]}], "abstract": "Principal-agent problems often extend beyond what can be directly addressed through conventional incentive arrangements. We examine a context where physicians are likely under-incentivized to minimize total medical costs until their private financial interests align with those of patients. Leveraging novel data on physician ownership of ambulatory surgery centers\u2014\u2014that is, same-day facilities\u2014\u2014we show that these equity holdings cause a substitution away from higher cost, rival settings that lowers Medicare spending by 10\u201340 percent per physician. We find no clear evidence of perverse behavior following these investments. Instead, our findings demonstrate how entrepreneurial activity can indirectly limit principal-agent problems and improve efficiency. (JEL D82, D91, G51, I11, I18, L84)", "date": "2026-02-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20211324", "title_zh": "\u63d0\u9ad8 stakes\uff1a\u533b\u751f\u8bbe\u65bd\u6295\u8d44\u4e0e\u63d0\u4f9b\u8005\u81ea\u4e3b\u6027", "abstract_zh": "\u4ee3\u7406\u95ee\u9898\u5f80\u5f80\u8d85\u51fa\u4e86\u4f20\u7edf\u6fc0\u52b1\u5b89\u6392\u6240\u80fd\u76f4\u63a5\u89e3\u51b3\u7684\u8303\u56f4\u3002\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u4e2a\u533b\u751f\u53ef\u80fd\u56e0\u7f3a\u4e4f\u8db3\u591f\u6fc0\u52b1\u800c\u672a\u80fd\u6709\u6548\u964d\u4f4e\u603b\u533b\u7597\u6210\u672c\u7684\u573a\u666f\uff0c\u76f4\u5230\u5176\u79c1\u4eba\u8d22\u52a1\u5229\u76ca\u4e0e\u60a3\u8005\u5229\u76ca\u76f8\u4e00\u81f4\u3002\u5229\u7528\u5173\u4e8e\u533b\u751f\u5bf9\u95e8\u8bca\u624b\u672f\u4e2d\u5fc3\u2014\u2014\u5373\u5f53\u65e5\u8bbe\u65bd\u2014\u2014\u6240\u6709\u6743\u7684\u65b0\u578b\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u8fd9\u4e9b\u80a1\u6743\u6301\u6709\u5bfc\u81f4\u533b\u751f\u8f6c\u5411\u6210\u672c\u66f4\u4f4e\u3001\u7ade\u4e89\u6027\u66f4\u5c0f\u7684\u8bbe\u7f6e\uff0c\u4ece\u800c\u4f7f Medicare \u652f\u51fa\u6bcf\u540d\u533b\u751f\u51cf\u5c11 10\u201340%\u3002\u6211\u4eec\u672a\u53d1\u73b0\u8fd9\u4e9b\u6295\u8d44\u540e\u5b58\u5728\u660e\u663e\u7684\u8d1f\u9762\u884c\u4e3a\u3002\u76f8\u53cd\uff0c\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u521b\u4e1a\u6d3b\u52a8\u53ef\u4ee5\u95f4\u63a5\u7f13\u89e3\u4ee3\u7406\u95ee\u9898\u5e76\u63d0\u5347\u6548\u7387\u3002\uff08JEL D82, D91, G51, I11, I18, L84\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20241718", "journal": "AER", "title": "Gender Differences in Economics Seminars", "authors": ["Pascaline Dupas", "Amy Handlan", "Alicia Sasser Modestino", "Muriel Niederle", "Mateo Ser\u00e9", "Haoyu Sheng", "Justin Wolfers", "the Seminar Dynamics Collective"], "author_details": [{"name": "Pascaline Dupas", "affiliations": ["Princeton, NBER (email: )"]}, {"name": "Amy Handlan", "affiliations": ["Brown (email: )"]}, {"name": "Alicia Sasser Modestino", "affiliations": ["Northeastern (email: )"]}, {"name": "Muriel Niederle", "affiliations": ["Stanford, NBER (email: )"]}, {"name": "Mateo Ser\u00e9", "affiliations": ["University College London (email: )"]}, {"name": "Haoyu Sheng", "affiliations": ["Brown (email: )"]}, {"name": "Justin Wolfers", "affiliations": ["Michigan, NBER (email: )"]}, {"name": "the Seminar Dynamics Collective", "affiliations": []}], "abstract": "We assess whether men and women are treated differently when presenting their economics research. We collected data across thousands of seminars, job market talks, and conference presentations, leveraging human judgment and audio-processing algorithms to measure the number, tone, and type of interruptions. Within a seminar series, women are interrupted more than men. This holds when controlling for characteristics of the presenter, paper, and audience. Interruptions that are negative in tenor or tone or cut off the presenter mid-sentence increase for women presenters. We also find greater engagement of female audience members with female presenters, suggesting a potential role model effect. (JEL A11, C45, J16, J44)", "date": "2026-02-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20241718", "title_zh": "\u7ecf\u6d4e\u5b66\u7814\u8ba8\u4f1a\u4e2d\u6027\u522b\u5dee\u5f02", "abstract_zh": "\u6211\u4eec\u8bc4\u4f30\u4e86\u5728\u5c55\u793a\u7ecf\u6d4e\u5b66\u7814\u7a76\u65f6\uff0c\u7537\u6027\u548c\u5973\u6027\u662f\u5426\u53d7\u5230\u4e0d\u540c\u7684\u5bf9\u5f85\u3002\u6211\u4eec\u6536\u96c6\u4e86\u6570\u5343\u573a\u7814\u8ba8\u4f1a\u3001\u6c42\u804c\u5e02\u573a\u6f14\u8bb2\u548c\u4f1a\u8bae\u6f14\u8bb2\u7684\u6570\u636e\uff0c\u5229\u7528\u4eba\u7c7b\u5224\u65ad\u548c\u97f3\u9891\u5904\u7406\u7b97\u6cd5\u6765\u8861\u91cf\u4e2d\u65ad\u7684\u6b21\u6570\u3001\u8bed\u6c14\u548c\u7c7b\u578b\u3002\u5728\u540c\u4e00\u4e2a\u7814\u8ba8\u4f1a\u7cfb\u5217\u4e2d\uff0c\u5973\u6027\u6f14\u8bb2\u8005\u6bd4\u7537\u6027\u88ab\u4e2d\u65ad\u66f4\u591a\u3002\u8fd9\u4e00\u73b0\u8c61\u5728\u63a7\u5236\u6f14\u8bb2\u8005\u81ea\u8eab\u7279\u5f81\u3001\u8bba\u6587\u5185\u5bb9\u548c\u89c2\u4f17\u7279\u5f81\u540e\u4f9d\u7136\u6210\u7acb\u3002\u9488\u5bf9\u5973\u6027\u6f14\u8bb2\u8005\u7684\u8d1f\u9762\u8bed\u6c14\u6216\u60c5\u7eea\u7684\u4e2d\u65ad\uff0c\u4ee5\u53ca\u5728\u6f14\u8bb2\u4e2d\u9014\u88ab\u622a\u65ad\u7684\u60c5\u51b5\u66f4\u4e3a\u9891\u7e41\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0c\u5973\u6027\u89c2\u4f17\u5bf9\u5973\u6027\u6f14\u8bb2\u8005\u7684\u53c2\u4e0e\u5ea6\u66f4\u9ad8\uff0c\u8fd9\u53ef\u80fd\u8868\u660e\u5b58\u5728\u699c\u6837\u6548\u5e94\u3002\uff08JEL A11, C45, J16, J44\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20221345", "journal": "AER", "title": "Competition under Incomplete Contracts and the Design of Procurement Policies", "authors": ["Rodrigo Carril", "Andres Gonzalez-Lira", "Michael S. Walker"], "author_details": [{"name": "Rodrigo Carril", "affiliations": ["Universitat Pompeu Fabra and Barcelona School of Economics (email: )"]}, {"name": "Andres Gonzalez-Lira", "affiliations": ["Pontificia Universidad Cat\u00f3lica de Chile, Business School (email: )"]}, {"name": "Michael S. Walker", "affiliations": ["US Department of Defense (DOD) (email: )"]}], "abstract": "We study the effects of intensifying competition for contracts in the context of US Defense procurement. Leveraging a discontinuous regulation that mandates agencies to publicize certain contract opportunities, we document that expanding the set of bidders reduces award prices but deteriorates post-award performance in terms of cost overruns and delays. We develop and estimate an auction model with endogenous entry and stochastic execution performance, in which the buyer endogenously chooses the intensity of competition. Model estimates indicate substantial heterogeneity in performance across contractors and show that simple adjustments to the current regulation could provide significant savings in procurement spending. (JEL D22, D24, D44, D82, D86, H56, H57)", "date": "2026-02-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20221345", "title_zh": "\u4e0d\u5b8c\u5168\u5408\u540c\u4e0b\u7684\u7ade\u4e89\u4e0e\u91c7\u8d2d\u653f\u7b56\u8bbe\u8ba1", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5728\u7f8e\u56fd\u56fd\u9632\u91c7\u8d2d\u4e2d\u52a0\u5f3a\u5408\u540c\u7ade\u4e89\u7684\u5f71\u54cd\u3002\u5229\u7528\u4e00\u9879\u5177\u6709\u65ad\u70b9\u7279\u5f81\u7684\u76d1\u7ba1\u89c4\u5b9a\uff0c\u5373\u8981\u6c42\u673a\u6784\u516c\u5f00\u67d0\u4e9b\u5408\u540c\u673a\u4f1a\uff0c\u6211\u4eec\u53d1\u73b0\u6269\u5927\u6295\u6807\u8005\u7fa4\u4f53\u867d\u964d\u4f4e\u4e86\u4e2d\u6807\u4ef7\u683c\uff0c\u4f46\u5bfc\u81f4\u5408\u540c\u6267\u884c\u540e\u7684\u6210\u672c\u8d85\u652f\u548c\u5ef6\u671f\u60c5\u51b5\u6076\u5316\u3002\u6211\u4eec\u6784\u5efa\u5e76\u4f30\u8ba1\u4e86\u4e00\u4e2a\u5177\u6709\u5185\u751f\u8fdb\u5165\u548c\u968f\u673a\u6267\u884c\u8868\u73b0\u7684\u62cd\u5356\u6a21\u578b\uff0c\u5176\u4e2d\u4e70\u65b9\u5185\u751f\u5730\u9009\u62e9\u7ade\u4e89\u5f3a\u5ea6\u3002\u6a21\u578b\u4f30\u8ba1\u663e\u793a\uff0c\u5404\u627f\u5305\u5546\u4e4b\u95f4\u7684\u8868\u73b0\u5b58\u5728\u663e\u8457\u5f02\u8d28\u6027\uff0c\u8868\u660e\u5bf9\u73b0\u884c\u76d1\u7ba1\u7684\u7b80\u5355\u8c03\u6574\u53ef\u5e26\u6765\u663e\u8457\u7684\u91c7\u8d2d\u652f\u51fa\u8282\u7ea6\u3002\uff08JEL D22, D24, D44, D82, D86, H56, H57\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20211219", "journal": "AER", "title": "Financial Frictions: Micro versus Macro Volatility", "authors": ["Renato Faccini", "Seungcheol Lee", "Ralph Luetticke", "Morten O. Ravn", "Tobias Renkin"], "author_details": [{"name": "Renato Faccini", "affiliations": ["Danmarks Nationalbank (email: )"]}, {"name": "Seungcheol Lee", "affiliations": ["Bank of Korea (email: )"]}, {"name": "Ralph Luetticke", "affiliations": ["University of Tuebingen and CEPR (email: )"]}, {"name": "Morten O. Ravn", "affiliations": ["University College London and CEPR (email: )"]}, {"name": "Tobias Renkin", "affiliations": ["Danmarks Nationalbank (email: )"]}], "abstract": "We argue that consumer credit spreads matter for household choices and that time-varying spreads have important distributional consequences. Studying Danish household data, we show that consumer credit spreads have heterogeneous impact on asset dynamics and consumption choices across the wealth distribution and that time-varying spreads induce a countercyclical marginal propensity to consume. We study a HANK model where banks provide consumer credit and corporate loans. Through countercyclical credit spreads, frictional finance amplifies aggregate shocks and induces consumption inequality. Economies with less leveraged banks experience reduced aggregate volatility but may face higher volatility and lower welfare at the household level. (JEL D12, D31, E12, E21, E32, E52, G51)", "date": "2026-02-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20211219", "title_zh": "\u91d1\u878d\u6469\u64e6\uff1a\u5fae\u89c2\u4e0e\u5b8f\u89c2\u6ce2\u52a8", "abstract_zh": "\u6211\u4eec\u8ba4\u4e3a\u6d88\u8d39\u8005\u4fe1\u8d37\u5229\u5dee\u5bf9\u5bb6\u5ead\u51b3\u7b56\u5177\u6709\u91cd\u8981\u5f71\u54cd\uff0c\u4e14\u968f\u65f6\u95f4\u53d8\u5316\u7684\u5229\u5dee\u5bf9\u6536\u5165\u5206\u914d\u5177\u6709\u91cd\u8981\u5f71\u54cd\u3002\u57fa\u4e8e\u4e39\u9ea6\u5bb6\u5ead\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u6d88\u8d39\u8005\u4fe1\u8d37\u5229\u5dee\u5bf9\u8d44\u4ea7\u52a8\u6001\u548c\u6d88\u8d39\u9009\u62e9\u5728\u8d22\u5bcc\u5206\u5e03\u4e0a\u5b58\u5728\u5f02\u8d28\u6027\uff0c\u4e14\u968f\u65f6\u95f4\u53d8\u5316\u7684\u5229\u5dee\u4f1a\u5f15\u53d1\u9006\u5468\u671f\u7684\u8fb9\u9645\u6d88\u8d39\u503e\u5411\u3002\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u4e2aHANK\u6a21\u578b\uff0c\u5176\u4e2d\u94f6\u884c\u63d0\u4f9b\u6d88\u8d39\u8005\u4fe1\u8d37\u548c\u4f01\u4e1a\u8d37\u6b3e\u3002\u901a\u8fc7\u9006\u5468\u671f\u7684\u4fe1\u8d37\u5229\u5dee\uff0c\u91d1\u878d\u6469\u64e6\u653e\u5927\u4e86\u6574\u4f53\u51b2\u51fb\u5e76\u5bfc\u81f4\u6d88\u8d39\u4e0d\u5e73\u7b49\u3002\u6760\u6746\u7387\u8f83\u4f4e\u7684\u94f6\u884c\u4f53\u7cfb\u867d\u7136\u51cf\u5c11\u4e86\u6574\u4f53\u6ce2\u52a8\uff0c\u4f46\u53ef\u80fd\u9762\u4e34\u5bb6\u5ead\u5c42\u9762\u6ce2\u52a8\u6027\u66f4\u9ad8\u548c\u798f\u5229\u6c34\u5e73\u66f4\u4f4e\u7684\u95ee\u9898\u3002\uff08JEL D12, D31, E12, E21, E32, E52, G51\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20190874", "journal": "AER", "title": "Evaluating the Impact of Urban Transit Infrastructure: Evidence from Bogot\u00e1\u2019s TransMilenio", "authors": ["Nick Tsivanidis"], "author_details": [{"name": "Nick Tsivanidis", "affiliations": ["Haas School of Business, University of California, Berkeley (email: )"]}], "abstract": "This paper estimates the effects of improving public transit infrastructure on city structure and welfare. It develops a quantitative urban model with multiple worker groups and transit modes, and derives a special case yielding sufficient statistics for aggregate welfare in a broad class of models. The paper estimates reduced-form elasticities to implement the approach using data spanning construction of the world\u2019s largest Bus Rapid Transit system in Bogot\u00e1, Colombia. This class of models explains observed adjustments in economic activity. Standard value-of-time calculations capture only 52 percent of welfare gains. Accounting for reallocation and general equilibrium effects, distributional impacts are modest. (JEL H76, L92, L98, O18, R42, R53)", "date": "2026-02-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20190874", "title_zh": "\u8bc4\u4f30\u57ce\u5e02\u4ea4\u901a\u57fa\u7840\u8bbe\u65bd\u5efa\u8bbe\u7684\u5f71\u54cd\uff1a\u6765\u81ea\u6ce2\u54e5\u5927TransMilenio\u7684\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u4f30\u8ba1\u4e86\u6539\u5584\u516c\u5171\u4ea4\u901a\u57fa\u7840\u8bbe\u65bd\u5bf9\u57ce\u5e02\u7ed3\u6784\u548c\u798f\u5229\u7684\u5f71\u54cd\u3002\u5b83\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u591a\u4e2a\u5de5\u4eba\u7fa4\u4f53\u548c\u4ea4\u901a\u65b9\u5f0f\u7684\u5b9a\u91cf\u57ce\u5e02\u6a21\u578b\uff0c\u5e76\u63a8\u5bfc\u51fa\u4e00\u4e2a\u7279\u4f8b\uff0c\u8be5\u7279\u4f8b\u4e3a\u4e00\u5927\u7c7b\u6a21\u578b\u4e2d\u7684\u603b\u4f53\u798f\u5229\u63d0\u4f9b\u4e86\u5145\u5206\u7edf\u8ba1\u91cf\u3002\u672c\u6587\u5229\u7528\u6db5\u76d6\u4e16\u754c\u4e0a\u6700\u5927\u7684\u5feb\u901f\u516c\u4ea4\u7cfb\u7edf\uff08TransMilenio\uff09\u5efa\u8bbe\u8fc7\u7a0b\u7684\u6570\u636e\uff0c\u4f30\u8ba1\u4e86\u7b80\u5316\u5f62\u5f0f\u7684\u5f39\u6027\u4ee5\u5b9e\u65bd\u8be5\u65b9\u6cd5\u3002\u8fd9\u7c7b\u6a21\u578b\u80fd\u591f\u89e3\u91ca\u7ecf\u6d4e\u6d3b\u52a8\u4e2d\u7684\u89c2\u5bdf\u5230\u7684\u8c03\u6574\u3002\u6807\u51c6\u7684\u65f6\u95f4\u4ef7\u503c\u8ba1\u7b97\u4ec5\u6355\u6349\u5230\u798f\u5229\u589e\u76ca\u768452%\u3002\u8003\u8651\u8d44\u6e90\u914d\u7f6e\u548c\u4e00\u822c\u5747\u8861\u6548\u5e94\u540e\uff0c\u5206\u914d\u5f71\u54cd\u8f83\u4e3a\u6709\u9650\u3002\uff08JEL H76, L92, L98, O18, R43, R53\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240443", "journal": "AER", "title": "A Theory of Supply Function Choice and Aggregate Supply", "authors": ["Joel P. Flynn", "George Nikolakoudis", "Karthik A. Sastry"], "author_details": [{"name": "Joel P. Flynn", "affiliations": ["Yale University (email: )"]}, {"name": "George Nikolakoudis", "affiliations": ["University of Chicago (email: )"]}, {"name": "Karthik A. Sastry", "affiliations": ["Princeton University (email: )"]}], "abstract": "Modern theories of aggregate supply are built on the foundation that firms set prices and commit to producing whatever the market demands. We remove this strategic restriction and allow firms to choose supply functions, mappings that describe the prices charged at each quantity of production. Theoretically, we characterize firms\u2019 optimal supply function choices in general equilibrium and study the resulting implications for aggregate supply. Aggregate supply flattens under lower inflation uncertainty, higher idiosyncratic demand uncertainty, and less elastic demand. Quantitatively, our theory can rationalize the flattening of aggregate supply during the Great Moderation and steepening during the 1970s and 2020s. (JEL D21, D43, E13, E23, E31, E32)", "date": "2026-02-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240443", "title_zh": "\u4f9b\u7ed9\u51fd\u6570\u9009\u62e9\u4e0e\u603b\u4f9b\u7ed9\u7684\u7406\u8bba", "abstract_zh": "\u73b0\u4ee3\u603b\u4f9b\u7ed9\u7406\u8bba\u5efa\u7acb\u5728\u4f01\u4e1a\u8bbe\u5b9a\u4ef7\u683c\u5e76\u627f\u8bfa\u6839\u636e\u5e02\u573a\u9700\u6c42\u8fdb\u884c\u751f\u4ea7\u7684\u57fa\u7840\u4e4b\u4e0a\u3002\u6211\u4eec\u53d6\u6d88\u4e86\u8fd9\u4e00\u6218\u7565\u9650\u5236\uff0c\u5141\u8bb8\u4f01\u4e1a\u9009\u62e9\u4f9b\u7ed9\u51fd\u6570\uff0c\u5373\u63cf\u8ff0\u5728\u6bcf\u4e2a\u4ea7\u91cf\u6c34\u5e73\u4e0b\u6240\u6536\u53d6\u4ef7\u683c\u7684\u6620\u5c04\u5173\u7cfb\u3002\u7406\u8bba\u4e0a\uff0c\u6211\u4eec\u523b\u753b\u4e86\u4f01\u4e1a\u5728\u4e00\u822c\u5747\u8861\u4e0b\u7684\u6700\u4f18\u4f9b\u7ed9\u51fd\u6570\u9009\u62e9\uff0c\u5e76\u7814\u7a76\u7531\u6b64\u4ea7\u751f\u7684\u603b\u4f9b\u7ed9\u5f71\u54cd\u3002\u5728\u901a\u80c0\u4e0d\u786e\u5b9a\u6027\u964d\u4f4e\u3001\u7279\u8d28\u9700\u6c42\u4e0d\u786e\u5b9a\u6027\u5347\u9ad8\u4ee5\u53ca\u9700\u6c42\u5f39\u6027\u8f83\u4f4e\u7684\u60c5\u51b5\u4e0b\uff0c\u603b\u4f9b\u7ed9\u8d8b\u4e8e\u5e73\u5766\u3002\u5b9a\u91cf\u4e0a\uff0c\u6211\u4eec\u7684\u7406\u8bba\u80fd\u591f\u89e3\u91ca\u5728\u201c\u5927\u7a33\u5065\u201d\u65f6\u671f\u603b\u4f9b\u7ed9\u7684\u5e73\u5766\u5316\uff0c\u4ee5\u53ca\u57281970\u5e74\u4ee3\u548c2020\u5e74\u4ee3\u603b\u4f9b\u7ed9\u7684\u9661\u5ced\u5316\u3002\uff08JEL D21, D43, E13, E23, E31, E32\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20220831", "journal": "AER", "title": "\u201cPotential\u201d and the Gender Promotion Gap", "authors": ["Alan Benson", "Danielle Li", "Kelly Shue"], "author_details": [{"name": "Alan Benson", "affiliations": ["University of Minnesota (email: )"]}, {"name": "Danielle Li", "affiliations": ["Massachusetts Institute of Technology and NBER (email: )"]}, {"name": "Kelly Shue", "affiliations": ["Yale University and NBER (email: )"]}], "abstract": "We show that subjective assessments of employee \u201cpotential\u201d contribute to gender gaps in promotion and pay. Using data on 29,809 management-track employees from a large retail chain, we find that women receive substantially lower potential ratings despite receiving higher performance ratings. Differences in potential ratings account for approximately half of the gender promotion gap. Women\u2019s lower potential ratings do not reflect accurate forecasts of future performance: Women subsequently outperform male colleagues, both on average and on the margin of promotion. We highlight two mechanisms driving the gender potential gap: strategic retention and stereotyping. (JEL J16, J31, J71, L81, M12, M51)", "date": "2026-02-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20220831", "title_zh": "\u6f5c\u529b\u201d\u4e0e\u6027\u522b\u664b\u5347\u5dee\u8ddd", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u5458\u5de5\u5bf9\u2018\u6f5c\u529b\u2019\u7684\u4e3b\u89c2\u8bc4\u4f30\u5bfc\u81f4\u4e86\u6027\u522b\u5728\u664b\u5347\u548c\u85aa\u916c\u4e0a\u7684\u5dee\u8ddd\u3002\u57fa\u4e8e\u4e00\u5bb6\u5927\u578b\u96f6\u552e\u8fde\u9501\u4f01\u4e1a29,809\u540d\u7ba1\u7406\u5c97\u4f4d\u5458\u5de5\u7684\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u5973\u6027\u83b7\u5f97\u7684\u6f5c\u529b\u8bc4\u5206\u663e\u8457\u4f4e\u4e8e\u7537\u6027\uff0c\u5c3d\u7ba1\u5979\u4eec\u7684\u7ee9\u6548\u8bc4\u5206\u66f4\u9ad8\u3002\u6f5c\u529b\u8bc4\u5206\u7684\u5dee\u5f02\u89e3\u91ca\u4e86\u5927\u7ea6\u4e00\u534a\u7684\u6027\u522b\u664b\u5347\u5dee\u8ddd\u3002\u5973\u6027\u8f83\u4f4e\u7684\u6f5c\u529b\u8bc4\u5206\u5e76\u4e0d\u80fd\u51c6\u786e\u9884\u6d4b\u5176\u672a\u6765\u8868\u73b0\uff1a\u5728\u5e73\u5747\u8868\u73b0\u548c\u664b\u5347\u8fb9\u7f18\u4e0a\uff0c\u5973\u6027\u540e\u7eed\u8868\u73b0\u5747\u4f18\u4e8e\u7537\u6027\u540c\u4e8b\u3002\u6211\u4eec\u6307\u51fa\u4e86\u4e24\u79cd\u9a71\u52a8\u6027\u522b\u6f5c\u529b\u5dee\u8ddd\u7684\u673a\u5236\uff1a\u6218\u7565\u6027\u4fdd\u7559\u548c\u523b\u677f\u5370\u8c61\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag007", "journal": "QJE", "title": "A Theory of How Workers Keep up with Inflation", "authors": ["Hassan Afrouzi", "Andres Blanco", "Andres Drenik", "Erik Hurst"], "author_details": [{"name": "Hassan Afrouzi", "affiliations": ["Columbia University and NBER ,"]}, {"name": "Andres Blanco", "affiliations": ["Federal Reserve Bank of Atlanta and Emory University ,"]}, {"name": "Andres Drenik", "affiliations": ["University of Texas at Austin and NBER ,"]}, {"name": "Erik Hurst", "affiliations": ["University of Chicago Booth School of Business and NBER ,"]}], "abstract": "Abstract We develop a model that integrates modern theories of labor market flows with nominal wage rigidities to study the consequences of inflation on the labor market. Nominal wage stickiness incentivizes workers to engage in job-to-job transitions after an unexpected increase in the price level. Such dynamics lead to a rise in aggregate vacancies associating a seemingly tight labor market with lower real wages\u2014two facts observed during the recent inflation period. The calibrated model jointly matches aggregate and cross-sectional trends in worker flows and wages during the 2021\u20132024 period. Using historical data, we show that prior periods of high inflation were also associated with increasing vacancies and upward shifts in the Beveridge curve. Our results suggest that policy makers and academics should be cautious about viewing the rise in the vacancy-to-unemployment rate as a sign of a tight labor market during inflationary periods without holistically looking at other labor market indicators.", "date": "2026-01-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag007", "title_zh": "\u5de5\u4eba\u5982\u4f55\u8ddf\u4e0a\u901a\u8d27\u81a8\u80c0\u7684\u7406\u8bba", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6a21\u578b\uff0c\u5c06\u73b0\u4ee3\u52b3\u52a8\u529b\u5e02\u573a\u6d41\u52a8\u7406\u8bba\u4e0e\u540d\u4e49\u5de5\u8d44\u521a\u6027\u7ed3\u5408\u8d77\u6765\uff0c\u7814\u7a76\u901a\u8d27\u81a8\u80c0\u5bf9\u52b3\u52a8\u529b\u5e02\u573a\u7684\u5f71\u54cd\u3002\u540d\u4e49\u5de5\u8d44\u7684\u521a\u6027\u4fc3\u4f7f\u5de5\u4eba\u5728\u4ef7\u683c\u6c34\u5e73\u610f\u5916\u4e0a\u5347\u540e\u8fdb\u884c\u5de5\u4f5c\u8f6c\u6362\u3002\u8fd9\u79cd\u52a8\u6001\u5bfc\u81f4\u6574\u4f53\u7a7a\u7f3a\u804c\u4f4d\u589e\u52a0\uff0c\u8868\u73b0\u4e3a\u52b3\u52a8\u529b\u5e02\u573a\u770b\u4f3c\u7d27\u5f20\u7684\u540c\u65f6\u5b9e\u9645\u5de5\u8d44\u4e0b\u964d\u2014\u2014\u8fd9\u6b63\u662f\u8fd1\u5e74\u6765\u901a\u8d27\u81a8\u80c0\u671f\u95f4\u89c2\u5bdf\u5230\u7684\u4e24\u4e2a\u73b0\u8c61\u3002\u7ecf\u8fc7\u6821\u51c6\u7684\u6a21\u578b\u57282021\u5e74\u81f32024\u5e74\u671f\u95f4\u540c\u65f6\u5339\u914d\u4e86\u52b3\u52a8\u529b\u6d41\u52a8\u548c\u5de5\u8d44\u7684\u5b8f\u89c2\u4e0e\u6a2a\u622a\u9762\u8d8b\u52bf\u3002\u5229\u7528\u5386\u53f2\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u4ee5\u5f80\u9ad8\u901a\u80c0\u65f6\u671f\u4e5f\u4f34\u968f\u7740\u7a7a\u7f3a\u804c\u4f4d\u7684\u589e\u52a0\u548c\u8d1d\u5f17\u91cc\u5947\u66f2\u7ebf\u7684\u4e0a\u79fb\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u653f\u7b56\u5236\u5b9a\u8005\u548c\u5b66\u8005\u5728\u901a\u80c0\u671f\u95f4\u5e94\u8c28\u614e\u5730\u5c06\u7a7a\u7f3a\u804c\u4f4d\u4e0e\u5931\u4e1a\u7387\u4e4b\u6bd4\u4e0a\u5347\u89c6\u4e3a\u52b3\u52a8\u529b\u5e02\u573a\u7d27\u5f20\u7684\u4fe1\u53f7\uff0c\u800c\u5e94\u5168\u9762\u8003\u5bdf\u5176\u4ed6\u52b3\u52a8\u529b\u5e02\u573a\u6307\u6807\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag006", "journal": "QJE", "title": "Automation and Rent Dissipation: Implications for Wages, Inequality, and Productivity", "authors": ["Daron Acemoglu", "Pascual Restrepo"], "author_details": [{"name": "Daron Acemoglu", "affiliations": ["Massachusetts Institute of Technology ,"]}, {"name": "Pascual Restrepo", "affiliations": ["Yale University ,"]}], "abstract": "Abstract This article studies the effects of automation in a task-based economy in which some jobs pay workers rents\u2014wages above workers' outside options. We show that automation targets high-rent tasks, dissipating rents, amplifying wage losses, and reducing within-group wage dispersion in exposed groups. This form of rent dissipation is inefficient and offsets the productivity gains from automation. Using U.S. data from 1980 to 2016, we find evidence of sizable rent dissipation and reduced within-group wage dispersion due to automation. Automation accounts for 52% of the increase in between-group inequality since 1980, with rent dissipation explaining one-fifth of this total. Our estimates imply that inefficient rent dissipation has offset 60%\u201390% of the productivity gains from automation over this period.", "date": "2026-01-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag006", "title_zh": "\u81ea\u52a8\u5316\u4e0e\u79df\u91d1\u8017\u6563\uff1a\u5bf9\u5de5\u8d44\u3001\u4e0d\u5e73\u7b49\u548c\u751f\u4ea7\u7387\u7684\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5728\u57fa\u4e8e\u4efb\u52a1\u7684\u7ecf\u6d4e\u4e2d\uff0c\u81ea\u52a8\u5316\u5bf9\u652f\u4ed8\u5de5\u4eba\u79df\u91d1\uff08\u5373\u5de5\u8d44\u9ad8\u4e8e\u5de5\u4eba\u5916\u90e8\u9009\u62e9\uff09\u7684\u5de5\u4f5c\u5c97\u4f4d\u7684\u5f71\u54cd\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u81ea\u52a8\u5316\u4f1a\u9488\u5bf9\u9ad8\u79df\u91d1\u4efb\u52a1\u8fdb\u884c\u4f5c\u7528\uff0c\u5bfc\u81f4\u79df\u91d1\u8017\u6563\uff0c\u52a0\u5267\u66b4\u9732\u7fa4\u4f53\u7684\u5de5\u8d44\u635f\u5931\uff0c\u5e76\u51cf\u5c11\u8be5\u7fa4\u4f53\u5185\u90e8\u7684\u5de5\u8d44\u5dee\u5f02\u3002\u8fd9\u79cd\u79df\u91d1\u8017\u6563\u662f\u4f4e\u6548\u7684\uff0c\u4f1a\u62b5\u6d88\u81ea\u52a8\u5316\u5e26\u6765\u7684\u751f\u4ea7\u7387\u63d0\u5347\u3002\u5229\u75281980\u5e74\u81f32016\u5e74\u7f8e\u56fd\u7684\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u5b58\u5728\u663e\u8457\u7684\u79df\u91d1\u8017\u6563\u4ee5\u53ca\u7531\u4e8e\u81ea\u52a8\u5316\u5bfc\u81f4\u7684\u7fa4\u4f53\u5185\u90e8\u5de5\u8d44\u5dee\u5f02\u4e0b\u964d\u3002\u81ea\u52a8\u5316\u89e3\u91ca\u4e861980\u5e74\u4ee5\u6765\u7ec4\u95f4\u4e0d\u5e73\u7b49\u4e0a\u5347\u768452%\uff0c\u5176\u4e2d\u79df\u91d1\u8017\u6563\u8d21\u732e\u4e86\u5176\u4e2d\u7684\u4e94\u5206\u4e4b\u4e00\u3002\u6211\u4eec\u7684\u4f30\u8ba1\u8868\u660e\uff0c\u4f4e\u6548\u7684\u79df\u91d1\u8017\u6563\u5df2\u62b5\u6d88\u4e86\u8be5\u65f6\u671f\u81ea\u52a8\u5316\u5e26\u6765\u7684\u751f\u4ea7\u7387\u63d0\u5347\u768460%\u81f390%\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/restud/rdag013", "journal": "REStud", "title": "Dynamic Regulation with Firm Linkages: Evidence from Texas", "authors": ["Matthew Leisten", "Nicholas Vreugdenhil"], "author_details": [{"name": "Matthew Leisten", "affiliations": ["Federal Trade Commission ,"]}, {"name": "Nicholas Vreugdenhil", "affiliations": ["Arizona State University ,"]}], "abstract": "Abstract We evaluate the efficiency of dynamic linked environmental regulation. Linked regulation allows inspectors who uncover violations at one plant to increase future enforcement at other plants that share a common owner. When compliance costs are correlated, regulators can then target scarce enforcement resources towards bad actors without inspecting everyone. We develop an empirical framework of dynamic moral hazard under linked regulation that allows for large portfolios of plants and for choices to be interdependent within the portfolio of plants and across time. Using the framework we evaluate a linked regulation scheme in Texas and find that linked regulation performs substantially better than both unlinked regulation and untargeted regulation. We test two alternative theoretical mechanisms that underpin the benefit\u2014a \u201cfirm-wide moral hazard mechanism\u201d and a \u201ccorrelated targeting mechanism\u201d\u2014and find that a large share of the value of linked regulation is due to the former.", "date": "2026-01-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag013", "title_zh": "\u5177\u6709\u4f01\u4e1a\u5173\u8054\u7684\u52a8\u6001\u76d1\u7ba1\uff1a\u6765\u81ea\u5fb7\u514b\u8428\u65af\u5dde\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u8bc4\u4f30\u4e86\u52a8\u6001\u5173\u8054\u73af\u5883\u76d1\u7ba1\u7684\u6548\u7387\u3002\u5173\u8054\u76d1\u7ba1\u5141\u8bb8\u5728\u4e00\u5bb6\u5de5\u5382\u53d1\u73b0\u8fdd\u89c4\u884c\u4e3a\u7684\u68c0\u67e5\u4eba\u5458\uff0c\u5bf9\u5171\u4eab\u540c\u4e00\u6240\u6709\u8005\u7684\u5176\u4ed6\u5de5\u5382\u589e\u52a0\u672a\u6765\u7684\u6267\u6cd5\u529b\u5ea6\u3002\u5f53\u5408\u89c4\u6210\u672c\u76f8\u5173\u65f6\uff0c\u76d1\u7ba1\u673a\u6784\u53ef\u4ee5\u5c06\u7a00\u7f3a\u7684\u6267\u6cd5\u8d44\u6e90\u6709\u9488\u5bf9\u6027\u5730\u96c6\u4e2d\u4e8e\u4e0d\u826f\u4f01\u4e1a\uff0c\u800c\u65e0\u9700\u5bf9\u6240\u6709\u4f01\u4e1a\u8fdb\u884c\u68c0\u67e5\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u52a8\u6001\u9053\u5fb7\u98ce\u9669\u4e0b\u7684\u5173\u8054\u76d1\u7ba1\u7ecf\u9a8c\u6846\u67b6\uff0c\u8be5\u6846\u67b6\u652f\u6301\u5927\u91cf\u5de5\u5382\u7ec4\u5408\uff0c\u5e76\u5141\u8bb8\u5de5\u5382\u7ec4\u5408\u5185\u4ee5\u53ca\u8de8\u65f6\u95f4\u7684\u51b3\u7b56\u76f8\u4e92\u4f9d\u8d56\u3002\u5229\u7528\u8be5\u6846\u67b6\uff0c\u6211\u4eec\u8bc4\u4f30\u4e86\u5fb7\u514b\u8428\u65af\u5dde\u7684\u5173\u8054\u76d1\u7ba1\u65b9\u6848\uff0c\u53d1\u73b0\u5173\u8054\u76d1\u7ba1\u5728\u6548\u7387\u4e0a\u663e\u8457\u4f18\u4e8e\u65e0\u5173\u8054\u76d1\u7ba1\u548c\u65e0\u76ee\u6807\u76d1\u7ba1\u3002\u6211\u4eec\u68c0\u9a8c\u4e86\u4e24\u79cd\u652f\u6491\u5176\u6548\u76ca\u7684\u7406\u8bba\u673a\u5236\u2014\u2014\u201c\u4f01\u4e1a\u6574\u4f53\u9053\u5fb7\u98ce\u9669\u673a\u5236\u201d\u548c\u201c\u76f8\u5173\u6027\u76ee\u6807\u673a\u5236\u201d\uff0c\u7ed3\u679c\u53d1\u73b0\u5173\u8054\u76d1\u7ba1\u5927\u90e8\u5206\u4ef7\u503c\u6765\u6e90\u4e8e\u524d\u8005\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1017/s0022109026102622", "journal": "JFQA", "title": "Judge Ideology and Corporate Tax Planning", "authors": ["Travis Chow", "Allen H. Huang", "Kai Wai Hui", "Terry Shevlin"], "author_details": [{"name": "Travis Chow", "affiliations": ["University of Hong Kong"]}, {"name": "Allen H. Huang", "affiliations": ["The Hong Kong University of Science and Technology"]}, {"name": "Kai Wai Hui", "affiliations": ["University of Hong Kong"]}, {"name": "Terry Shevlin", "affiliations": ["University of California Irvine"]}], "abstract": "Abstract We investigate whether judges\u2019 political ideology affects corporate tax behaviors. We find that firms engaging in less aggressive tax planning when Circuit Court judges are more liberal. Cross-sectionally, the deterrent effect of liberal judge ideology is more pronounced for firms that engage in judiciary-sensitive tax strategies, face higher enforcement risk from the Internal Revenue Service (IRS), or have larger reputational costs from tax disputes. Our findings further suggest that liberal judge ideology reduces firms\u2019 R&D investments and market value by constraining tax planning. Overall, our evidence highlights the importance of judge ideology for firm behavior in the context of corporate tax planning.", "date": "2026-01-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102622", "title_zh": "\u6cd5\u5b98\u610f\u8bc6\u5f62\u6001\u4e0e\u4f01\u4e1a\u7a0e\u52a1\u7b79\u5212", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u6cd5\u5b98\u7684\u653f\u6cbb\u610f\u8bc6\u5f62\u6001\u662f\u5426\u4f1a\u5f71\u54cd\u4f01\u4e1a\u7684\u7a0e\u52a1\u884c\u4e3a\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5f53\u5de1\u56de\u6cd5\u9662\u6cd5\u5b98\u66f4\u4e3a\u81ea\u7531\u6d3e\u65f6\uff0c\u4f01\u4e1a\u8fdb\u884c\u7684\u6fc0\u8fdb\u7a0e\u52a1\u7b79\u5212\u4f1a\u51cf\u5c11\u3002\u5728\u6a2a\u622a\u9762\u4e0a\uff0c\u81ea\u7531\u6d3e\u6cd5\u5b98\u610f\u8bc6\u5f62\u6001\u7684\u5a01\u6151\u6548\u5e94\u5728\u90a3\u4e9b\u91c7\u7528\u53f8\u6cd5\u654f\u611f\u578b\u7a0e\u52a1\u7b56\u7565\u3001\u9762\u4e34\u7f8e\u56fd\u56fd\u7a0e\u5c40\uff08IRS\uff09\u66f4\u9ad8\u6267\u6cd5\u98ce\u9669\u6216\u56e0\u7a0e\u52a1\u4e89\u8bae\u4ea7\u751f\u66f4\u5927\u58f0\u8a89\u6210\u672c\u7684\u4f01\u4e1a\u4e2d\u66f4\u4e3a\u663e\u8457\u3002\u6211\u4eec\u7684\u53d1\u73b0\u8fd8\u8868\u660e\uff0c\u81ea\u7531\u6d3e\u6cd5\u5b98\u610f\u8bc6\u5f62\u6001\u901a\u8fc7\u9650\u5236\u7a0e\u52a1\u7b79\u5212\uff0c\u51cf\u5c11\u4e86\u4f01\u4e1a\u7684\u7814\u53d1\u6295\u5165\u548c\u5e02\u573a\u4ef7\u503c\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u8bc1\u636e\u51f8\u663e\u4e86\u6cd5\u5b98\u610f\u8bc6\u5f62\u6001\u5728\u4f01\u4e1a\u7a0e\u52a1\u7b79\u5212\u80cc\u666f\u4e0b\u7684\u91cd\u8981\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag004", "journal": "RFS", "title": "Is Fraud Contagious? Social Connections and the Looting of COVID Relief Programs", "authors": ["John M Griffin", "Samuel Kruger", "Prateek Mahajan"], "author_details": [{"name": "John M Griffin", "affiliations": ["McCombs School of Business, University of Texas at Austin ,"]}, {"name": "Samuel Kruger", "affiliations": ["McCombs School of Business, University of Texas at Austin ,"]}, {"name": "Prateek Mahajan", "affiliations": ["McCombs School of Business, University of Texas at Austin ,"]}], "abstract": "Abstract Fraud indicators within the Paycheck Protection Program (PPP), a major COVID relief program, are highly geographically concentrated. ZIP codes and counties with high rates of suspicious PPP loans are strongly socially connected, with evidence that fraud spreads spatially over time through social networks. Individuals in suspicious social media groups have higher rates of PPP fraud, and socially connected ZIP codes frequently use the same specific FinTech lenders, consistent with social networks influencing detailed loan decisions. Our findings suggest that more proactive data analysis is needed for fraud prevention, detection, and prosecution to prevent the social spread of fraudulent schemes.", "date": "2026-01-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag004", "title_zh": "\u6b3a\u8bc8\u5177\u6709\u4f20\u67d3\u6027\u5417\uff1f\u793e\u4f1a\u8054\u7cfb\u4e0e\u65b0\u51a0\u75ab\u60c5\u6551\u6d4e\u8ba1\u5212\u7684\u63a0\u593a", "abstract_zh": "\u5728\u7f8e\u56fd\u65b0\u51a0\u75ab\u60c5\u6551\u6d4e\u8ba1\u5212\u2018\u85aa\u8d44\u4fdd\u62a4\u8ba1\u5212\u2019\uff08PPP\uff09\u4e2d\uff0c\u6b3a\u8bc8\u6307\u6807\u5728\u5730\u7406\u4e0a\u9ad8\u5ea6\u96c6\u4e2d\u3002\u9ad8\u6b3a\u8bc8\u7387\u7684\u90ae\u653f\u7f16\u7801\u548c\u53bf\u4e0e\u793e\u4f1a\u7f51\u7edc\u4e2d\u7684\u5176\u4ed6\u5730\u533a\u5b58\u5728\u5f3a\u70c8\u7684\u793e\u4f1a\u8054\u7cfb\uff0c\u8bc1\u636e\u8868\u660e\u6b3a\u8bc8\u884c\u4e3a\u901a\u8fc7\u793e\u4f1a\u7f51\u7edc\u5728\u65f6\u95f4\u4e0a\u53d1\u751f\u7a7a\u95f4\u4f20\u64ad\u3002\u5728\u53ef\u7591\u793e\u4ea4\u5a92\u4f53\u7fa4\u4f53\u4e2d\u7684\u4eba\u7fa4\u5177\u6709\u66f4\u9ad8\u7684PPP\u6b3a\u8bc8\u7387\uff0c\u4e14\u793e\u4f1a\u8054\u7cfb\u7d27\u5bc6\u7684\u90ae\u653f\u7f16\u7801\u7ecf\u5e38\u4f7f\u7528\u76f8\u540c\u7684\u91d1\u878d\u79d1\u6280\u8d37\u6b3e\u673a\u6784\uff0c\u8fd9\u4e0e\u793e\u4f1a\u7f51\u7edc\u5f71\u54cd\u5177\u4f53\u8d37\u6b3e\u51b3\u7b56\u4e00\u81f4\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u9700\u8981\u66f4\u52a0\u4e3b\u52a8\u7684\u6570\u636e\u5206\u6790\u6765\u9884\u9632\u3001\u68c0\u6d4b\u548c\u8d77\u8bc9\u6b3a\u8bc8\u884c\u4e3a\uff0c\u4ee5\u9632\u6b62\u6b3a\u8bc8\u65b9\u6848\u5728\u793e\u4f1a\u4e2d\u4f20\u64ad\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/restud/rdag002", "journal": "REStud", "title": "Education and the Margins of Cyclical Adjustment in the Labour Market", "authors": ["Cynthia L Doniger"], "author_details": [{"name": "Cynthia L Doniger", "affiliations": ["Federal Reserve Board ,"]}], "abstract": "Abstract Allocative wages\u2014the labour costs considered when deciding to form or dissolve a long-term employment relationship\u2014are more sensitive to cyclical conditions for more educated workers. Specifically, college-educated workers\u2019 allocative wages are highly pro-cyclical, while high school dropouts\u2019 wages exhibit only moderate cyclicality. Further, as education increases, an increasing share of the sensitivity of allocative wages is driven by the persistent scarring effects of the cyclical position at the time of hiring on the wages associated with higher levels of tenure, amounting to more than a third of the overall sensitivity for the college educated. The greater job stability of the more educated\u2014and therefore the exposure to scarring\u2014contributes to these differences. In addition, more significant scarring at each horizon of tenure amplifies the effect. In service of documenting these facts, I develop new methods for inferring the sensitivity of labour costs to shocks when agents are forward-looking and wages may be intertemporally smoothed.", "date": "2026-01-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/restud/rdag002", "title_zh": "\u6559\u80b2\u4e0e\u52b3\u52a8\u529b\u5e02\u573a\u5468\u671f\u8c03\u6574\u7684\u8fb9\u7f18", "abstract_zh": "\u6458\u8981 \u5206\u914d\u6027\u5de5\u8d44\u2014\u2014\u5373\u5728\u51b3\u5b9a\u5efa\u7acb\u6216\u7ec8\u6b62\u957f\u671f\u96c7\u4f63\u5173\u7cfb\u65f6\u6240\u8003\u8651\u7684\u52b3\u52a8\u529b\u6210\u672c\u2014\u2014\u5bf9\u5468\u671f\u6027\u6761\u4ef6\u7684\u654f\u611f\u6027\u5728\u53d7\u8fc7\u66f4\u591a\u6559\u80b2\u7684\u5de5\u4eba\u4e2d\u66f4\u9ad8\u3002\u5177\u4f53\u800c\u8a00\uff0c\u5927\u5b66\u6bd5\u4e1a\u751f\u7684\u5206\u914d\u6027\u5de5\u8d44\u8868\u73b0\u51fa\u663e\u8457\u7684\u987a\u5468\u671f\u6027\uff0c\u800c\u9ad8\u4e2d\u8f8d\u5b66\u8005\u7684\u5de5\u8d44\u4ec5\u8868\u73b0\u51fa\u4e2d\u7b49\u7a0b\u5ea6\u7684\u5468\u671f\u6027\u3002\u6b64\u5916\uff0c\u968f\u7740\u6559\u80b2\u6c34\u5e73\u7684\u63d0\u9ad8\uff0c\u5206\u914d\u6027\u5de5\u8d44\u5bf9\u5468\u671f\u6027\u6761\u4ef6\u7684\u654f\u611f\u6027\u4e2d\uff0c\u8d8a\u6765\u8d8a\u591a\u7684\u90e8\u5206\u662f\u7531\u96c7\u4f63\u65f6\u7684\u5468\u671f\u6027\u4f4d\u7f6e\u7684\u6301\u4e45\u6027\u75a4\u75d5\u6548\u5e94\u6240\u9a71\u52a8\u7684\uff0c\u5bf9\u4e8e\u5927\u5b66\u6bd5\u4e1a\u751f\u800c\u8a00\uff0c\u8fd9\u4e00\u6548\u5e94\u5360\u6574\u4f53\u654f\u611f\u6027\u7684\u4e09\u5206\u4e4b\u4e00\u4ee5\u4e0a\u3002\u66f4\u53d7\u6559\u80b2\u7fa4\u4f53\u7684\u5c31\u4e1a\u7a33\u5b9a\u6027\u66f4\u9ad8\uff0c\u56e0\u800c\u66f4\u6613\u53d7\u5230\u75a4\u75d5\u6548\u5e94\u7684\u5f71\u54cd\uff0c\u8fd9\u89e3\u91ca\u4e86\u8fd9\u4e9b\u5dee\u5f02\u3002\u6b64\u5916\uff0c\u5728\u6bcf\u4e2a\u4efb\u671f\u9636\u6bb5\u4e2d\u75a4\u75d5\u6548\u5e94\u7684\u52a0\u5267\u8fdb\u4e00\u6b65\u653e\u5927\u4e86\u8fd9\u4e00\u5f71\u54cd\u3002\u4e3a\u8bb0\u5f55\u8fd9\u4e9b\u4e8b\u5b9e\uff0c\u6211\u5f00\u53d1\u4e86\u65b0\u7684\u65b9\u6cd5\uff0c\u7528\u4e8e\u63a8\u65ad\u5f53\u4e2a\u4f53\u5177\u6709\u524d\u77bb\u6027\u4e14\u5de5\u8d44\u53ef\u80fd\u5728\u65f6\u95f4\u4e0a\u5e73\u6ed1\u65f6\uff0c\u52b3\u52a8\u529b\u6210\u672c\u5bf9\u51b2\u51fb\u7684\u654f\u611f\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70021", "journal": "JF", "title": "Monetary Policy and Wealth Effects: The Role of Risk and Heterogeneity", "authors": ["NICOLAS CARAMP", "DEJANIR H. SILVA"], "author_details": [{"name": "NICOLAS CARAMP", "affiliations": []}, {"name": "DEJANIR H. SILVA", "affiliations": []}], "abstract": "ABSTRACT We study the role of asset revaluation in the monetary transmission mechanism. We build an analytical heterogeneous\u2010agents model with two main ingredients: (i) rare disasters and (ii) heterogeneous beliefs. The model captures time\u2010varying risk premia and precautionary savings in a setting that nests the textbook New Keynesian model. The model generates large movements in asset prices after a monetary shock but these movements can be neutral on real variables. Real effects depend on the redistribution among agents with heterogeneous precautionary motives. In quantitative analysis, we find that this channel can account for a large fraction of the transmission to aggregate consumption.", "date": "2026-01-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70021", "title_zh": "\u8d27\u5e01\u653f\u7b56\u4e0e\u8d22\u5bcc\u6548\u5e94\uff1a\u98ce\u9669\u4e0e\u5f02\u8d28\u6027\u7684\u4f5c\u7528", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u8d44\u4ea7\u91cd\u4f30\u5728\u8d27\u5e01\u653f\u7b56\u4f20\u5bfc\u673a\u5236\u4e2d\u7684\u4f5c\u7528\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u4e24\u4e2a\u4e3b\u8981\u8981\u7d20\u7684\u5206\u6790\u6027\u5f02\u8d28\u6027\u4e3b\u4f53\u6a21\u578b\uff1a\uff08i\uff09\u7f55\u89c1\u707e\u96be\u4e8b\u4ef6\uff0c\u4ee5\u53ca\uff08ii\uff09\u5f02\u8d28\u6027\u4fe1\u5ff5\u3002\u8be5\u6a21\u578b\u5728\u5305\u542b\u6559\u79d1\u4e66\u65b0\u51ef\u6069\u65af\u6a21\u578b\u7684\u6846\u67b6\u4e0b\uff0c\u6355\u6349\u4e86\u65f6\u95f4\u53d8\u5316\u7684\u98ce\u9669\u6ea2\u4ef7\u548c\u9884\u9632\u6027\u50a8\u84c4\u3002\u6a21\u578b\u663e\u793a\uff0c\u5728\u8d27\u5e01\u653f\u7b56\u51b2\u51fb\u540e\u8d44\u4ea7\u4ef7\u683c\u4f1a\u51fa\u73b0\u5927\u5e45\u6ce2\u52a8\uff0c\u4f46\u8fd9\u4e9b\u6ce2\u52a8\u5bf9\u5b9e\u9645\u53d8\u91cf\u53ef\u80fd\u65e0\u5f71\u54cd\u3002\u5b9e\u9645\u6548\u5e94\u53d6\u51b3\u4e8e\u5177\u6709\u5f02\u8d28\u6027\u9884\u9632\u6027\u52a8\u673a\u7684\u4e3b\u4f53\u4e4b\u95f4\u7684\u518d\u5206\u914d\u3002\u5728\u5b9a\u91cf\u5206\u6790\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\u8fd9\u4e00\u6e20\u9053\u53ef\u4ee5\u89e3\u91ca\u76f8\u5f53\u5927\u6bd4\u4f8b\u7684\u5bf9\u603b\u6d88\u8d39\u7684\u4f20\u5bfc\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1111/jofi.70023", "journal": "JF", "title": "Monetary Policy, Inflation, and Crises: Evidence from History and Administrative Data", "authors": ["GABRIEL JIM\u00c9NEZ", "DMITRY KUVSHINOV", "JOS\u00c9\u2010LUIS PEYDR\u00d3", "BJ\u00d6RN RICHTER"], "author_details": [{"name": "GABRIEL JIM\u00c9NEZ", "affiliations": []}, {"name": "DMITRY KUVSHINOV", "affiliations": []}, {"name": "JOS\u00c9\u2010LUIS PEYDR\u00d3", "affiliations": []}, {"name": "BJ\u00d6RN RICHTER", "affiliations": []}], "abstract": "ABSTRACT We show that a U\u2010shaped monetary rate path increases banking crisis risk, via credit and asset price cycles, analyzing 17 countries over 150 years. Rate hikes (raw or instrumented) increase crisis risk, but only if preceded by prolonged cuts. These patterns are unique to banking crises, unlike noncrisis recessions. Regarding the mechanism, prolonged cuts raise the likelihood of large credit and asset price booms, consistent with higher credit supply and risk\u2010taking. Subsequent hikes strongly reduce credit and asset prices, and increase banks' realized credit risk, rather than interest rate risk. We find consistent results in administrative loan\u2010level data for Spain.", "date": "2026-01-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70023", "title_zh": "\u8d27\u5e01\u653f\u7b56\u3001\u901a\u8d27\u81a8\u80c0\u4e0e\u5371\u673a\uff1a\u6765\u81ea\u5386\u53f2\u6570\u636e\u548c\u884c\u653f\u6570\u636e\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u5448U\u5f62\u7684\u5229\u7387\u8def\u5f84\u4f1a\u901a\u8fc7\u4fe1\u8d37\u548c\u8d44\u4ea7\u4ef7\u683c\u5468\u671f\u589e\u52a0\u94f6\u884c\u5371\u673a\u98ce\u9669\uff0c\u5206\u6790\u4e8617\u4e2a\u56fd\u5bb6150\u5e74\u95f4\u7684\u6570\u636e\u3002\u5229\u7387\u4e0a\u5347\uff08\u65e0\u8bba\u662f\u539f\u59cb\u6570\u636e\u8fd8\u662f\u5de5\u5177\u53d8\u91cf\u6570\u636e\uff09\u4f1a\u589e\u52a0\u5371\u673a\u98ce\u9669\uff0c\u4f46\u524d\u63d0\u662f\u6b64\u524d\u7ecf\u5386\u4e86\u957f\u671f\u7684\u5229\u7387\u4e0b\u964d\u3002\u8fd9\u79cd\u6a21\u5f0f\u4ec5\u5728\u94f6\u884c\u5371\u673a\u4e2d\u51fa\u73b0\uff0c\u800c\u975e\u5728\u975e\u5371\u673a\u6027\u7ecf\u6d4e\u8870\u9000\u4e2d\u3002\u5728\u673a\u5236\u65b9\u9762\uff0c\u957f\u671f\u7684\u5229\u7387\u4e0b\u964d\u4f1a\u63d0\u9ad8\u4fe1\u8d37\u548c\u8d44\u4ea7\u4ef7\u683c\u6ce1\u6cab\u7684\u53d1\u751f\u6982\u7387\uff0c\u8fd9\u4e0e\u4fe1\u8d37\u4f9b\u7ed9\u589e\u52a0\u548c\u98ce\u9669\u627f\u62c5\u4e0a\u5347\u4e00\u81f4\u3002\u968f\u540e\u7684\u5229\u7387\u4e0a\u5347\u4f1a\u663e\u8457\u964d\u4f4e\u4fe1\u8d37\u548c\u8d44\u4ea7\u4ef7\u683c\uff0c\u5e76\u589e\u52a0\u94f6\u884c\u7684\u5b9e\u9645\u4fe1\u8d37\u98ce\u9669\uff0c\u800c\u975e\u5229\u7387\u98ce\u9669\u3002\u6211\u4eec\u5728\u897f\u73ed\u7259\u7684\u884c\u653f\u8d37\u6b3e\u5c42\u9762\u6570\u636e\u4e2d\u53d1\u73b0\u4e86\u4e0e\u4e4b\u76f8\u4e00\u81f4\u7684\u7ed3\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1111/jofi.70025", "journal": "JF", "title": "The Dollar during the Great Recession: The Information Channel of U.S. Monetary Policy and the \u201cFlight to Safety\u201d", "authors": ["VANIA STAVRAKEVA", "JENNY TANG"], "author_details": [{"name": "VANIA STAVRAKEVA", "affiliations": []}, {"name": "JENNY TANG", "affiliations": []}], "abstract": "ABSTRACT Conventional wisdom holds that lowering a home country's interest rate relative to another's will depreciate the domestic currency. We document that, at business\u2010cycle frequencies, U.S. forward guidance monetary policy easings had the opposite effect during the Great Recession. We attribute this effect to calendar\u2010based forward guidance that signaled economic weakness, resulting in a \u201cflight\u2010to\u2010safety\u201d effect and lower expected U.S. inflation. We also document cross\u2010currency heterogeneity: a surprise U.S. rate cut induced a larger appreciation of the dollar against currencies that typically depreciate more when the world economy is contracting. We build a model that can reconcile these findings.", "date": "2026-01-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70025", "title_zh": "\u5927\u8870\u9000\u671f\u95f4\u7f8e\u5143\u7684\u8d70\u52bf\uff1a\u7f8e\u56fd\u8d27\u5e01\u653f\u7b56\u7684\u4fe1\u606f\u6e20\u9053\u4e0e\"\u907f\u9669\u6d41\u52a8\"\u73b0\u8c61", "abstract_zh": "\u6458\u8981 \u4f20\u7edf\u89c2\u70b9\u8ba4\u4e3a\uff0c\u5c06\u4e00\u56fd\u5229\u7387\u76f8\u5bf9\u4e8e\u5176\u4ed6\u56fd\u5bb6\u964d\u4f4e\u4f1a\u5bfc\u81f4\u672c\u56fd\u8d27\u5e01\u8d2c\u503c\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u5468\u671f\u6027\u9891\u7387\u4e0b\uff0c\u5927\u8870\u9000\u671f\u95f4\u7f8e\u56fd\u7684\u524d\u77bb\u6027\u6307\u5f15\u8d27\u5e01\u653f\u7b56\u653e\u677e\u4ea7\u751f\u4e86\u76f8\u53cd\u7684\u6548\u679c\u3002\u6211\u4eec\u5c06\u5176\u5f52\u56e0\u4e8e\u57fa\u4e8e\u65e5\u5386\u7684\u524d\u77bb\u6027\u6307\u5f15\u4fe1\u53f7\u8868\u660e\u7ecf\u6d4e\u75b2\u8f6f\uff0c\u4ece\u800c\u5f15\u53d1\"\u907f\u9669\u6d41\u52a8\"\u6548\u5e94\u5e76\u964d\u4f4e\u9884\u671f\u7f8e\u56fd\u901a\u80c0\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\u8d27\u5e01\u95f4\u7684\u5f02\u8d28\u6027\uff1a\u7f8e\u56fd\u610f\u5916\u964d\u606f\u5bfc\u81f4\u7f8e\u5143\u5bf9\u901a\u5e38\u5728\u4e16\u754c\u7ecf\u6d4e\u6536\u7f29\u65f6\u8d2c\u503c\u66f4\u591a\u7684\u8d27\u5e01\u51fa\u73b0\u66f4\u5927\u7a0b\u5ea6\u7684\u5347\u503c\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u80fd\u591f\u89e3\u91ca\u8fd9\u4e9b\u53d1\u73b0\u7684\u6a21\u578b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag006", "journal": "RFS", "title": "The Impact of Carcinogenic Risk Exposure on Housing Values: Estimates from Chemical Reclassifications", "authors": ["Jules van Binsbergen", "Jo\u00e3o F Cocco", "Marco Grotteria", "S Lakshmi Naaraayanan"], "author_details": [{"name": "Jules van Binsbergen", "affiliations": ["University of Pennsylvania, the United States, CEPR and NBER"]}, {"name": "Jo\u00e3o F Cocco", "affiliations": ["London Business School, the United Kingdom, and CEPR"]}, {"name": "Marco Grotteria", "affiliations": ["London Business School, the United Kingdom, and CEPR"]}, {"name": "S Lakshmi Naaraayanan", "affiliations": ["London Business School, the United Kingdom, and CEPR"]}], "abstract": "Abstract We quantify the impact of perceived cancer risk on housing values using widely advertised national reclassifications of chemical carcinogenicity in the United States. Combining these information events with an empirical design that compares changes in house values closer to affected toxic plants against those farther away isolates the effect of cancer risk news from other local factors. Focusing on plants previously emitting reclassified carcinogenic chemicals, we estimate a 1\u20132% decline in housing values within a 3-mile radius compared to those located farther away. The effects are stronger in areas with higher media presence underscoring the role of salience as a mechanism.", "date": "2026-01-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag006", "title_zh": "\u81f4\u764c\u98ce\u9669\u66b4\u9732\u5bf9\u623f\u4ef7\u5f71\u54cd\u7684\u4f30\u8ba1\uff1a\u6765\u81ea\u7f8e\u56fd\u5316\u5b66\u81f4\u764c\u6027\u91cd\u65b0\u5206\u7c7b\u7684\u6570\u636e", "abstract_zh": "\u6211\u4eec\u5229\u7528\u7f8e\u56fd\u5e7f\u6cdb\u5ba3\u4f20\u7684\u5316\u5b66\u81f4\u764c\u6027\u91cd\u65b0\u5206\u7c7b\u4fe1\u606f\u4e8b\u4ef6\uff0c\u91cf\u5316\u4e86\u4eba\u4eec\u5bf9\u764c\u75c7\u98ce\u9669\u611f\u77e5\u5bf9\u623f\u4ef7\u7684\u5f71\u54cd\u3002\u901a\u8fc7\u5c06\u8fd9\u4e9b\u4fe1\u606f\u4e8b\u4ef6\u4e0e\u4e00\u79cd\u5b9e\u8bc1\u8bbe\u8ba1\u76f8\u7ed3\u5408\uff0c\u6bd4\u8f83\u9760\u8fd1\u53d7\u5f71\u54cd\u6709\u6bd2\u5de5\u5382\u7684\u623f\u5c4b\u4ef7\u503c\u53d8\u5316\u4e0e\u8fdc\u79bb\u8fd9\u4e9b\u5de5\u5382\u7684\u623f\u5c4b\u4ef7\u503c\u53d8\u5316\uff0c\u4ece\u800c\u5c06\u764c\u75c7\u98ce\u9669\u65b0\u95fb\u7684\u5f71\u54cd\u4e0e\u5176\u4ed6\u672c\u5730\u56e0\u7d20\u5206\u79bb\u3002\u805a\u7126\u4e8e\u6b64\u524d\u6392\u653e\u88ab\u91cd\u65b0\u5206\u7c7b\u4e3a\u81f4\u764c\u7269\u8d28\u7684\u5de5\u5382\uff0c\u6211\u4eec\u4f30\u8ba1\u57283\u82f1\u91cc\u534a\u5f84\u8303\u56f4\u5185\uff0c\u623f\u4ef7\u76f8\u6bd4\u66f4\u8fdc\u5730\u533a\u7684\u623f\u5c4b\u4e0b\u964d\u4e861%\u81f32%\u3002\u5728\u5a92\u4f53\u66dd\u5149\u5ea6\u8f83\u9ad8\u7684\u5730\u533a\uff0c\u8fd9\u4e00\u6548\u5e94\u66f4\u4e3a\u663e\u8457\uff0c\u51f8\u663e\u4e86\u663e\u8457\u6027\u4f5c\u4e3a\u8fd9\u4e00\u673a\u5236\u7684\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102580", "journal": "JFQA", "title": "A Catering Theory of Earnings Guidance: Empirical Evidence and Stock Market Implications", "authors": ["Nils Lohmeier", "Hannes Mohrschladt"], "author_details": [{"name": "Nils Lohmeier", "affiliations": ["University of M\u00fcnster Finance Center M\u00fcnster"]}, {"name": "Hannes Mohrschladt", "affiliations": ["University of Potsdam Faculty of Economics and Social Sciences and University of M\u00fcnster Finance Center M\u00fcnster"]}], "abstract": "Abstract We propose and test a catering theory of earnings guidance. As predicted by our model, managers cater to reference point-dependent investor preferences by issuing excessively optimistic earnings forecasts if their investors have experienced poor stock returns. Moreover, earnings guidance is most biased when managers strongly discount future outcomes, when the stock\u2019s payoff uncertainty is high, and when managers face low costs for issuing inaccurate forecasts. Catering via earnings guidance succeeds in moving stock market prices and induces mispricing which is partially corrected around the corresponding final earnings announcement.", "date": "2026-01-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102580", "title_zh": "\u76c8\u4f59\u6307\u5f15\u7684\u9910\u996e\u7406\u8bba\uff1a\u5b9e\u8bc1\u8bc1\u636e\u53ca\u80a1\u5e02\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e86\u5e76\u68c0\u9a8c\u4e86\u4e00\u79cd\u76c8\u4f59\u6307\u5f15\u7684\u9910\u996e\u7406\u8bba\u3002\u6839\u636e\u6211\u4eec\u7684\u6a21\u578b\u9884\u6d4b\uff0c\u7ba1\u7406\u8005\u4f1a\u6839\u636e\u6295\u8d44\u8005\u7684\u53c2\u7167\u4f9d\u8d56\u504f\u597d\u8c03\u6574\u76c8\u4f59\u6307\u5f15\uff0c\u5f53\u6295\u8d44\u8005\u7ecf\u5386\u8f83\u5dee\u7684\u80a1\u7968\u56de\u62a5\u65f6\uff0c\u7ba1\u7406\u8005\u4f1a\u53d1\u5e03\u8fc7\u4e8e\u4e50\u89c2\u7684\u76c8\u4f59\u9884\u6d4b\u3002\u6b64\u5916\uff0c\u5f53\u7ba1\u7406\u8005\u5bf9\u672a\u6765\u7684\u7ed3\u679c\u5927\u5e45\u6298\u73b0\u3001\u80a1\u7968\u6536\u76ca\u4e0d\u786e\u5b9a\u6027\u8f83\u9ad8\uff0c\u4ee5\u53ca\u7ba1\u7406\u8005\u53d1\u5e03\u4e0d\u51c6\u786e\u9884\u6d4b\u7684\u6210\u672c\u8f83\u4f4e\u65f6\uff0c\u76c8\u4f59\u6307\u5f15\u7684\u504f\u5dee\u6700\u4e3a\u663e\u8457\u3002\u901a\u8fc7\u76c8\u4f59\u6307\u5f15\u8fdb\u884c\u7684\u201c\u9910\u996e\u201d\u884c\u4e3a\u80fd\u591f\u63a8\u52a8\u80a1\u4ef7\u53d8\u52a8\uff0c\u5e76\u5bfc\u81f4\u5b9a\u4ef7\u504f\u5dee\uff0c\u800c\u8fd9\u79cd\u504f\u5dee\u5728\u6700\u7ec8\u76c8\u4f59\u516c\u544a\u65f6\u90e8\u5206\u5f97\u5230\u4fee\u6b63\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhag005", "journal": "RFS", "title": "Remotely Productive: The Efficacy of Remote Work for Executives", "authors": ["Ran Duchin", "Denis Sosyura"], "author_details": [{"name": "Ran Duchin", "affiliations": ["Boston College ,"]}, {"name": "Denis Sosyura", "affiliations": ["Arizona State University ,"]}], "abstract": "Abstract We study the efficacy of remote arrangements between CEOs and firms. Such arrangements attract executive talent and overcome labor market segmentation but introduce frictions. Remote arrangements are associated with lower operating performance, firm valuation, and insider reviews. Using the private costs from uprooting the CEO\u2019s spouse as an instrument for the CEO\u2019s decision to seek remote work, we find similar negative effects. The performance decline increases for CEOs who live further away and who cross multiple time zones. The mechanisms include the CEO\u2019s loss of information, short-termism, and consumption of leisure, such as recreational boats and beach homes.", "date": "2026-01-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag005", "title_zh": "\u8fdc\u7a0b\u9ad8\u6548\uff1a\u9ad8\u7ba1\u8fdc\u7a0b\u5de5\u4f5c\u5b89\u6392\u7684\u6709\u6548\u6027", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86CEO\u4e0e\u4f01\u4e1a\u4e4b\u95f4\u8fdc\u7a0b\u5de5\u4f5c\u5b89\u6392\u7684\u6709\u6548\u6027\u3002\u6b64\u7c7b\u5b89\u6392\u5438\u5f15\u4e86\u9ad8\u7ba1\u4eba\u624d\uff0c\u5e76\u514b\u670d\u4e86\u52b3\u52a8\u529b\u5e02\u573a\u7684\u5206\u5272\uff0c\u4f46\u540c\u65f6\u4e5f\u5f15\u5165\u4e86\u6469\u64e6\u3002\u8fdc\u7a0b\u5de5\u4f5c\u5b89\u6392\u4e0e\u8f83\u4f4e\u7684\u8fd0\u8425\u7ee9\u6548\u3001\u4f01\u4e1a\u4f30\u503c\u4ee5\u53ca\u5185\u90e8\u4eba\u5458\u8bc4\u4ef7\u76f8\u5173\u8054\u3002\u5229\u7528CEO\u914d\u5076\u642c\u8fc1\u5e26\u6765\u7684\u79c1\u4eba\u6210\u672c\u4f5c\u4e3aCEO\u9009\u62e9\u8fdc\u7a0b\u5de5\u4f5c\u7684\u5de5\u5177\u53d8\u91cf\uff0c\u6211\u4eec\u53d1\u73b0\u7c7b\u4f3c\u7684\u8d1f\u9762\u6548\u5e94\u3002\u7ee9\u6548\u4e0b\u964d\u5728CEO\u5c45\u4f4f\u8ddd\u79bb\u66f4\u8fdc\u4e14\u8de8\u8d8a\u591a\u4e2a\u65f6\u533a\u7684\u60c5\u51b5\u4e0b\u66f4\u4e3a\u663e\u8457\u3002\u5176\u673a\u5236\u5305\u62ecCEO\u4fe1\u606f\u83b7\u53d6\u7684\u4e27\u5931\u3001\u77ed\u671f\u884c\u4e3a\u4ee5\u53ca\u5bf9\u4f11\u95f2\u6d3b\u52a8\uff08\u5982\u6e38\u8247\u548c\u6d77\u6ee8\u522b\u5885\uff09\u7684\u6d88\u8d39\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70026", "journal": "JF", "title": "Bank Monitoring with On\u2010Site Inspections", "authors": ["Amanda Rae Heitz", "Christopher Martin", "Alexander Ufier"], "author_details": [{"name": "Amanda Rae Heitz", "affiliations": []}, {"name": "Christopher Martin", "affiliations": []}, {"name": "Alexander Ufier", "affiliations": []}], "abstract": "ABSTRACT Using proprietary transaction\u2010level data on nonsyndicated construction loans, we provide some of the first empirical evidence on the drivers and consequences of bank monitoring through on\u2010site inspections. Banks trade off monitoring intensity with favorable origination terms. Monitoring intensity escalates in response to local economic downturns or the bank's financial instability. Borrowers with negative inspection reports have more draw requests denied, suggesting that monitoring outcomes impact credit decisions. Both the occurrence and threat of increased inspection frequency correspond to reduced defaults. Overall, our results provide empirical support for a substantial body of theoretical literature on bank monitoring.", "date": "2026-01-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70026", "title_zh": "\u94f6\u884c\u73b0\u573a\u68c0\u67e5\u7684\u76d1\u63a7\u884c\u4e3a", "abstract_zh": "\u6458\u8981\uff1a\u5229\u7528\u5173\u4e8e\u975e\u6253\u5305\u65bd\u5de5\u8d37\u6b3e\u7684\u4e13\u6709\u4ea4\u6613\u7ea7\u6570\u636e\uff0c\u6211\u4eec\u63d0\u4f9b\u4e86\u5173\u4e8e\u94f6\u884c\u901a\u8fc7\u73b0\u573a\u68c0\u67e5\u8fdb\u884c\u76d1\u63a7\u7684\u9a71\u52a8\u56e0\u7d20\u53ca\u5176\u540e\u679c\u7684\u4e00\u4e9b\u65e9\u671f\u5b9e\u8bc1\u8bc1\u636e\u3002\u94f6\u884c\u5728\u76d1\u63a7\u5f3a\u5ea6\u4e0e\u6709\u5229\u7684\u8d37\u6b3e\u521d\u59cb\u6761\u6b3e\u4e4b\u95f4\u8fdb\u884c\u6743\u8861\u3002\u5f53\u5f53\u5730\u7ecf\u6d4e\u51fa\u73b0\u8870\u9000\u6216\u94f6\u884c\u81ea\u8eab\u8d22\u52a1\u4e0d\u7a33\u5b9a\u65f6\uff0c\u76d1\u63a7\u5f3a\u5ea6\u4f1a\u589e\u5f3a\u3002\u62e5\u6709\u8d1f\u9762\u68c0\u67e5\u62a5\u544a\u7684\u501f\u6b3e\u4eba\u5c06\u9762\u4e34\u66f4\u591a\u7684\u63d0\u6b3e\u8bf7\u6c42\u88ab\u62d2\u7edd\uff0c\u8fd9\u8868\u660e\u76d1\u63a7\u7ed3\u679c\u4f1a\u5f71\u54cd\u4fe1\u8d37\u51b3\u7b56\u3002\u65e0\u8bba\u662f\u68c0\u67e5\u53d1\u751f\u7684\u5b9e\u9645\u60c5\u5f62\u8fd8\u662f\u68c0\u67e5\u9891\u7387\u589e\u52a0\u7684\u5a01\u80c1\uff0c\u90fd\u4e0e\u8fdd\u7ea6\u7387\u4e0b\u964d\u76f8\u5173\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u7ed3\u679c\u4e3a\u5173\u4e8e\u94f6\u884c\u76d1\u63a7\u7684\u5927\u91cf\u7406\u8bba\u6587\u732e\u63d0\u4f9b\u4e86\u5b9e\u8bc1\u652f\u6301\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhaf107", "journal": "RFS", "title": "The Impact of Bank Consolidation on Credit Supply and Performance", "authors": ["Sergio Mayordomo", "Nicola Pavanini", "Emanuele Tarantino"], "author_details": [{"name": "Sergio Mayordomo", "affiliations": ["Banco de Espa\u00f1a ,"]}, {"name": "Nicola Pavanini", "affiliations": ["Tilburg University ,"]}, {"name": "Emanuele Tarantino", "affiliations": ["Luiss and EIEF, Italy, and European Commission ,"]}], "abstract": "Abstract Between 2009 and 2011, the Spanish banking system underwent a restructuring process based on savings banks\u2019 consolidation. The program\u2019s design allows us to study how banks\u2019 consolidation affects credit supply and performance. We propose a quasi-experimental analysis showing that bank mergers restrict credit supply and set higher interest rates but also reject fewer applicants and report fewer nonperforming loans. We then estimate a structural model of credit in which banks set interest rates and lending standards. We find that, despite the relaxation in their lending standards, merged banks\u2019 credit performance improved thanks to a significant drop in their screening costs.", "date": "2026-01-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf107", "title_zh": "\u94f6\u884c\u5408\u5e76\u5bf9\u4fe1\u8d37\u4f9b\u7ed9\u4e0e\u7ee9\u6548\u7684\u5f71\u54cd", "abstract_zh": "\u6458\u8981 2009\u5e74\u81f32011\u5e74\u671f\u95f4\uff0c\u897f\u73ed\u7259\u94f6\u884c\u4e1a\u7ecf\u5386\u4e86\u57fa\u4e8e\u50a8\u84c4\u94f6\u884c\u5408\u5e76\u7684\u91cd\u7ec4\u8fc7\u7a0b\u3002\u8be5\u8ba1\u5212\u7684\u8bbe\u8ba1\u4f7f\u6211\u4eec\u80fd\u591f\u7814\u7a76\u94f6\u884c\u5408\u5e76\u5982\u4f55\u5f71\u54cd\u4fe1\u8d37\u4f9b\u7ed9\u548c\u7ee9\u6548\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u51c6\u5b9e\u9a8c\u5206\u6790\uff0c\u8868\u660e\u94f6\u884c\u5408\u5e76\u4f1a\u9650\u5236\u4fe1\u8d37\u4f9b\u7ed9\u5e76\u63d0\u9ad8\u5229\u7387\uff0c\u4f46\u540c\u65f6\u4e5f\u62d2\u7edd\u66f4\u5c11\u7684\u7533\u8bf7\u4eba\uff0c\u5e76\u62a5\u544a\u66f4\u5c11\u7684\u4e0d\u826f\u8d37\u6b3e\u3002\u968f\u540e\uff0c\u6211\u4eec\u5efa\u7acb\u4e86\u4e00\u4e2a\u4fe1\u8d37\u7ed3\u6784\u6a21\u578b\uff0c\u5176\u4e2d\u94f6\u884c\u8bbe\u5b9a\u5229\u7387\u548c\u4fe1\u8d37\u6807\u51c6\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5c3d\u7ba1\u5408\u5e76\u94f6\u884c\u5728\u4fe1\u8d37\u6807\u51c6\u4e0a\u6709\u6240\u653e\u677e\uff0c\u4f46\u5176\u4fe1\u8d37\u7ee9\u6548\u4ecd\u56e0\u7b5b\u9009\u6210\u672c\u663e\u8457\u4e0b\u964d\u800c\u5f97\u5230\u6539\u5584\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1093/qje/qjag004", "journal": "QJE", "title": "How Do You Identify a Good Manager?", "authors": ["Ben Weidmann", "Joseph Vecci", "Farah Said", "Sonia Bhalotra", "Achyuta Adhvaryu", "Anant Nyshadham", "Jorge Tamayo", "David Deming"], "author_details": [{"name": "Ben Weidmann", "affiliations": ["University College London and London School of Economics ,"]}, {"name": "Joseph Vecci", "affiliations": ["University of Gothenburg ,"]}, {"name": "Farah Said", "affiliations": ["Lahore University of Management Sciences ,"]}, {"name": "Sonia Bhalotra", "affiliations": ["University of Warwick, Institute for Fiscal Studies, Centre for Economic Policy and Research, United Kingdom, CESifo, Institute of Labor Economics ,"]}, {"name": "Achyuta Adhvaryu", "affiliations": ["University of California San Diego, National Bureau of Economic Research, Abdul Latif Jameel Poverty Action Lab, Bureau for Research & Economic Analysis of Development, Good Business Lab ,"]}, {"name": "Anant Nyshadham", "affiliations": ["University of Michigan, National Bureau of Economic Research, Abdul Latif Jameel Poverty Action Lab, Bureau for Research & Economic Analysis of Development, Good Business Lab ,"]}, {"name": "Jorge Tamayo", "affiliations": ["Harvard Business School and Digital Reskilling Lab ,"]}, {"name": "David Deming", "affiliations": ["Harvard Kennedy School and National Bureau of Economic Research ,"]}], "abstract": "Abstract We introduce and validate a novel approach to identifying good managers. In a preregistered lab experiment, we causally identify managerial contributions by randomly assigning managers to teams and controlling for individual skill. We find that manager contributions are crucial for team success, and that people who self-select into management roles perform worse than randomly assigned managers. Managerial performance is strongly predicted by economic decision-making skill but not by demographic characteristics. Two validation studies support our experimental results. Participants who succeed in the lab receive more real-world promotions and, in a separate study of retail store managers, skill measures strongly predict store sales. A one standard deviation increase in manager quality increases annual per store sales by US$4.1 million (25% increase). Selecting managers on skills rather than demographic characteristics or the desire to lead could substantially improve organizational performance.", "date": "2026-01-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag004", "title_zh": "\u5982\u4f55\u8bc6\u522b\u4e00\u4f4d\u4f18\u79c0\u7684\u7ba1\u7406\u8005\uff1f", "abstract_zh": "\u6211\u4eec\u5f15\u5165\u5e76\u9a8c\u8bc1\u4e86\u4e00\u79cd\u8bc6\u522b\u4f18\u79c0\u7ba1\u7406\u8005\u7684\u5168\u65b0\u65b9\u6cd5\u3002\u5728\u4e00\u9879\u9884\u5148\u6ce8\u518c\u7684\u5b9e\u9a8c\u5ba4\u5b9e\u9a8c\u4e2d\uff0c\u6211\u4eec\u901a\u8fc7\u968f\u673a\u5c06\u7ba1\u7406\u8005\u5206\u914d\u7ed9\u56e2\u961f\uff0c\u5e76\u63a7\u5236\u4e2a\u4f53\u80fd\u529b\uff0c\u5b9e\u73b0\u4e86\u5bf9\u7ba1\u7406\u8d21\u732e\u7684\u56e0\u679c\u8bc6\u522b\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u7ba1\u7406\u8005\u7684\u8d21\u732e\u5bf9\u56e2\u961f\u6210\u529f\u81f3\u5173\u91cd\u8981\uff0c\u4e14\u81ea\u613f\u8fdb\u5165\u7ba1\u7406\u5c97\u4f4d\u7684\u4eba\u8868\u73b0\u4e0d\u5982\u968f\u673a\u5206\u914d\u7684\u7ba1\u7406\u8005\u3002\u7ba1\u7406\u8005\u7684\u7ee9\u6548\u5f3a\u70c8\u7531\u7ecf\u6d4e\u51b3\u7b56\u80fd\u529b\u9884\u6d4b\uff0c\u800c\u975e\u4eba\u53e3\u7edf\u8ba1\u7279\u5f81\u3002\u4e24\u9879\u9a8c\u8bc1\u7814\u7a76\u652f\u6301\u4e86\u6211\u4eec\u7684\u5b9e\u9a8c\u7ed3\u679c\u3002\u5728\u5b9e\u9a8c\u5ba4\u4e2d\u8868\u73b0\u4f18\u5f02\u7684\u53c2\u4e0e\u8005\u5728\u73b0\u5b9e\u4e16\u754c\u4e2d\u83b7\u5f97\u66f4\u591a\u7684\u664b\u5347\u673a\u4f1a\uff0c\u800c\u5728\u5bf9\u96f6\u552e\u5e97\u7ba1\u7406\u8005\u7684\u72ec\u7acb\u7814\u7a76\u4e2d\uff0c\u80fd\u529b\u6307\u6807\u663e\u8457\u9884\u6d4b\u95e8\u5e97\u9500\u552e\u989d\u3002\u7ba1\u7406\u8005\u8d28\u91cf\u6bcf\u63d0\u9ad8\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u6bcf\u5e74\u6bcf\u5e97\u9500\u552e\u989d\u5c06\u589e\u52a0410\u4e07\u7f8e\u5143\uff08\u589e\u957f25%\uff09\u3002\u57fa\u4e8e\u80fd\u529b\u800c\u975e\u4eba\u53e3\u7edf\u8ba1\u7279\u5f81\u6216\u9886\u5bfc\u6b32\u671b\u6765\u9009\u62d4\u7ba1\u7406\u8005\uff0c\u53ef\u80fd\u663e\u8457\u63d0\u5347\u7ec4\u7ec7\u7ee9\u6548\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70007", "journal": "JF", "title": "Deposit Inflows and Outflows in Failing Banks: The Role of Deposit Insurance", "authors": ["CHRISTOPHER MARTIN", "MANJU PURI", "ALEXANDER UFIER"], "author_details": [{"name": "CHRISTOPHER MARTIN", "affiliations": []}, {"name": "MANJU PURI", "affiliations": []}, {"name": "ALEXANDER UFIER", "affiliations": []}], "abstract": "ABSTRACT Using unique, daily, account\u2010level data, we investigate deposit outflows and inflows in a distressed bank. We observe an outflow of uninsured depositors following bad regulatory news. Both regular and temporary deposit insurance reduce outflows. We provide important new evidence that, simultaneous with deposit outflows, deposit inflows are first order. Uninsured deposit outflows were largely offset with new insured deposit inflows as the bank approached failure, with the bank increasing term deposit rates. This phenomenon holds in a large sample of banks that faced regulatory action, suggesting that insured deposit inflows are an important mechanism that weakens depositor discipline.", "date": "2026-01-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70007", "title_zh": "\u5728\u7834\u4ea7\u94f6\u884c\u4e2d\u5b58\u6b3e\u6d41\u5165\u4e0e\u6d41\u51fa\uff1a\u5b58\u6b3e\u4fdd\u9669\u7684\u4f5c\u7528", "abstract_zh": "\u6458\u8981\uff1a\u5229\u7528\u72ec\u7279\u3001\u6bcf\u65e5\u3001\u8d26\u6237\u7ea7\u522b\u7684\u6570\u636e\uff0c\u6211\u4eec\u7814\u7a76\u4e86\u5728\u9762\u4e34\u56f0\u5883\u7684\u94f6\u884c\u4e2d\u5b58\u6b3e\u7684\u6d41\u51fa\u4e0e\u6d41\u5165\u60c5\u51b5\u3002\u6211\u4eec\u89c2\u5bdf\u5230\uff0c\u5728\u6536\u5230\u4e0d\u826f\u76d1\u7ba1\u6d88\u606f\u540e\uff0c\u672a\u6295\u4fdd\u7684\u5b58\u6b3e\u4eba\u4f1a\u51fa\u73b0\u5b58\u6b3e\u6d41\u51fa\u3002\u65e0\u8bba\u662f\u5e38\u89c4\u8fd8\u662f\u4e34\u65f6\u6027\u7684\u5b58\u6b3e\u4fdd\u9669\u90fd\u80fd\u6709\u6548\u51cf\u5c11\u8fd9\u79cd\u6d41\u51fa\u3002\u6211\u4eec\u63d0\u4f9b\u4e86\u91cd\u8981\u65b0\u8bc1\u636e\uff0c\u5373\u5728\u5b58\u6b3e\u6d41\u51fa\u7684\u540c\u65f6\uff0c\u5b58\u6b3e\u6d41\u5165\u5177\u6709\u9996\u8981\u4f5c\u7528\u3002\u5f53\u94f6\u884c\u63a5\u8fd1\u7834\u4ea7\u65f6\uff0c\u672a\u6295\u4fdd\u5b58\u6b3e\u4eba\u7684\u6d41\u51fa\u5728\u5f88\u5927\u7a0b\u5ea6\u4e0a\u88ab\u65b0\u7684\u6295\u4fdd\u5b58\u6b3e\u6d41\u5165\u6240\u62b5\u6d88\uff0c\u4e14\u94f6\u884c\u63d0\u9ad8\u4e86\u5b9a\u671f\u5b58\u6b3e\u5229\u7387\u3002\u8fd9\u4e00\u73b0\u8c61\u5728\u5927\u91cf\u9762\u4e34\u76d1\u7ba1\u884c\u52a8\u7684\u94f6\u884c\u6837\u672c\u4e2d\u5747\u6210\u7acb\uff0c\u8868\u660e\u6295\u4fdd\u5b58\u6b3e\u6d41\u5165\u662f\u524a\u5f31\u5b58\u6b3e\u4eba\u7eaa\u5f8b\u7684\u91cd\u8981\u673a\u5236\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70027", "journal": "JF", "title": "Model Ambiguity versus Model Misspecification in Dynamic Portfolio Choice", "authors": ["PASCAL J. MAENHOUT", "HAO XING", "ANNE G. BALTER"], "author_details": [{"name": "PASCAL J. MAENHOUT", "affiliations": []}, {"name": "HAO XING", "affiliations": []}, {"name": "ANNE G. BALTER", "affiliations": []}], "abstract": "ABSTRACT We study aversion to model ambiguity and misspecification in dynamic portfolio choice. Risk\u2010averse investors (relative risk aversion ) fear return persistence, while risk\u2010tolerant investors () fear mean reversion, when confronting model misspecification concerns of identically and independently distributed (IID) returns. The intuition is that risk\u2010averse investors, who want to hedge intertemporally, endogenously fear return persistence, which precludes hedging. A log investor is myopic and unaffected by model misspecification, therefore only worrying about model ambiguity. Our model can generate belief scarring, nonparticipation in equity markets, and extrapolative return expectations. Extending beyond IID returns, we study model misspecification for a mean\u2010reverting Sharpe ratio.", "date": "2026-01-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70027", "title_zh": "\u52a8\u6001\u6295\u8d44\u7ec4\u5408\u9009\u62e9\u4e2d\u6a21\u578b\u4e0d\u786e\u5b9a\u6027\u4e0e\u6a21\u578b\u8bbe\u5b9a\u504f\u5dee\u7684\u7814\u7a76", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u6295\u8d44\u8005\u5bf9\u6a21\u578b\u4e0d\u786e\u5b9a\u6027\u4e0e\u6a21\u578b\u8bbe\u5b9a\u504f\u5dee\u7684\u56de\u907f\u884c\u4e3a\u3002\u98ce\u9669\u538c\u6076\u7684\u6295\u8d44\u8005\uff08\u76f8\u5bf9\u98ce\u9669\u538c\u6076\u7cfb\u6570\uff09\u62c5\u5fe7\u6536\u76ca\u7387\u7684\u6301\u7eed\u6027\uff0c\u800c\u98ce\u9669\u5bb9\u5fcd\u7684\u6295\u8d44\u8005\u5219\u62c5\u5fe7\u5747\u503c\u56de\u5f52\uff0c\u5f53\u9762\u5bf9\u72ec\u7acb\u540c\u5206\u5e03\uff08IID\uff09\u6536\u76ca\u7387\u7684\u6a21\u578b\u8bbe\u5b9a\u504f\u5dee\u65f6\u3002\u5176\u76f4\u89c9\u5728\u4e8e\uff0c\u98ce\u9669\u538c\u6076\u7684\u6295\u8d44\u8005\u5e0c\u671b\u8fdb\u884c\u8de8\u671f\u5bf9\u51b2\uff0c\u56e0\u6b64\u4f1a\u5185\u751f\u5730\u62c5\u5fe7\u6536\u76ca\u7387\u7684\u6301\u7eed\u6027\uff0c\u8fd9\u4f1a\u963b\u788d\u5bf9\u51b2\u884c\u4e3a\u3002\u5bf9\u6570\u6295\u8d44\u8005\u662f\u77ed\u89c6\u7684\uff0c\u4e0d\u53d7\u6a21\u578b\u8bbe\u5b9a\u504f\u5dee\u7684\u5f71\u54cd\uff0c\u56e0\u6b64\u4ec5\u62c5\u5fe7\u6a21\u578b\u4e0d\u786e\u5b9a\u6027\u3002\u6211\u4eec\u7684\u6a21\u578b\u53ef\u4ee5\u4ea7\u751f\u4fe1\u5ff5\u75a4\u75d5\u3001\u5bf9\u80a1\u7968\u5e02\u573a\u7684\u4e0d\u53c2\u4e0e\u4ee5\u53ca\u5916\u63a8\u6027\u7684\u6536\u76ca\u7387\u9884\u671f\u3002\u5728\u8d85\u8d8a\u72ec\u7acb\u540c\u5206\u5e03\u6536\u76ca\u7387\u7684\u57fa\u7840\u4e0a\uff0c\u6211\u4eec\u7814\u7a76\u4e86\u5747\u503c\u56de\u5f52\u7684\u590f\u666e\u6bd4\u7387\u7684\u6a21\u578b\u8bbe\u5b9a\u504f\u5dee\u95ee\u9898\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1111/jofi.70024", "journal": "JF", "title": "Investor Composition and the Liquidity Component in the U.S. Corporate Bond Market", "authors": ["JIAN LI", "HAIYUE YU"], "author_details": [{"name": "JIAN LI", "affiliations": []}, {"name": "HAIYUE YU", "affiliations": []}], "abstract": "ABSTRACT The link between corporate bond credit spreads and secondary market illiquidity in the cross section has grown stronger since 2005, resulting in a higher liquidity component in credit spreads. Using U.S. investor holdings data, we show that short\u2010term investors (e.g., mutual funds/exchange\u2010traded funds [ETFs]) increase trading activities in the secondary market, amplifying the effect of secondary market frictions on prices. We provide a model featuring heterogeneous investors with different trading needs and heterogeneous bonds to investigate the impact of the rapid\u2010growing mutual fund/ETF sector on the corporate bond market. We find the change in investor composition can quantitatively explain the aggregate trend.", "date": "2026-01-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70024", "title_zh": "\u6295\u8d44\u8005\u7ed3\u6784\u4e0e\u7f8e\u56fd\u4f01\u4e1a\u503a\u5238\u5e02\u573a\u4e2d\u7684\u6d41\u52a8\u6027\u6210\u5206", "abstract_zh": "\u6458\u8981 \u81ea2005\u5e74\u4ee5\u6765\uff0c\u4f01\u4e1a\u503a\u5238\u4fe1\u7528\u5229\u5dee\u4e0e\u4e8c\u7ea7\u5e02\u573a\u975e\u6d41\u52a8\u6027\u4e4b\u95f4\u7684\u4ea4\u53c9\u622a\u9762\u5173\u7cfb\u53d8\u5f97\u66f4\u52a0\u7d27\u5bc6\uff0c\u5bfc\u81f4\u4fe1\u7528\u5229\u5dee\u4e2d\u7684\u6d41\u52a8\u6027\u6210\u5206\u4e0a\u5347\u3002\u5229\u7528\u7f8e\u56fd\u6295\u8d44\u8005\u6301\u4ed3\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u77ed\u671f\u6295\u8d44\u8005\uff08\u5982\u5171\u540c\u57fa\u91d1/\u4ea4\u6613\u6240\u4ea4\u6613\u57fa\u91d1[ETF]\uff09\u589e\u52a0\u4e86\u4e8c\u7ea7\u5e02\u573a\u7684\u4ea4\u6613\u6d3b\u52a8\uff0c\u4ece\u800c\u653e\u5927\u4e86\u4e8c\u7ea7\u5e02\u573a\u6469\u64e6\u5bf9\u4ef7\u683c\u7684\u5f71\u54cd\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u5177\u6709\u4e0d\u540c\u4ea4\u6613\u9700\u6c42\u7684\u5f02\u8d28\u6027\u6295\u8d44\u8005\u4ee5\u53ca\u5f02\u8d28\u6027\u503a\u5238\u7684\u6a21\u578b\uff0c\u4ee5\u7814\u7a76\u5feb\u901f\u589e\u957f\u7684\u5171\u540c\u57fa\u91d1/ETF\u90e8\u95e8\u5bf9\u4f01\u4e1a\u503a\u5238\u5e02\u573a\u7684\u5f71\u54cd\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u6295\u8d44\u8005\u7ed3\u6784\u7684\u53d8\u5316\u80fd\u591f\u5b9a\u91cf\u89e3\u91ca\u6574\u4f53\u8d8b\u52bf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1093/qje/qjag003", "journal": "QJE", "title": "(Not) Thinking About the Future: Financial Information and Maternal Labor Supply", "authors": ["Ana Costa-Ram\u00f3n", "Michaela Slotwinski", "Ursina Schaede", "Anne Ardila Bren\u00f8e"], "author_details": [{"name": "Ana Costa-Ram\u00f3n", "affiliations": ["University of Zurich, Switzerland and Centre for Economic Policy Research ,"]}, {"name": "Michaela Slotwinski", "affiliations": ["University of Neuch\u00e2tel, University of Zurich, University of Basel, Switzerland and CESifo ,"]}, {"name": "Ursina Schaede", "affiliations": ["Tufts University ,"]}, {"name": "Anne Ardila Bren\u00f8e", "affiliations": ["University of Zurich ,"]}], "abstract": "Abstract Does information about the long-run financial costs of reduced labor supply increase mothers\u2019 working hours? We document descriptively that long-term financial factors are not top of mind when mothers decide on their employment level. Moreover, a substantial share of women holds overly optimistic expectations about pension receipt and wage growth under part-time work. In a large-scale field experiment in Switzerland, we randomly assign mothers working part-time as teachers to receive objective information about the long-run costs of reduced labor supply. The treatment increases both demand for financial information and future labor supply plans, in particular among women who underestimate the costs of part-time work. Leveraging linked employer administrative data one year post-intervention, we find that this group of mothers increases working hours by 7%. These findings underscore that policies reducing information frictions in labor supply decisions may help address remaining gender gaps in the labor market.", "date": "2026-01-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag003", "title_zh": "(\u5e76\u975e) \u601d\u8003\u672a\u6765\uff1a\u8d22\u52a1\u4fe1\u606f\u4e0e\u6bcd\u4eb2\u52b3\u52a8\u4f9b\u7ed9", "abstract_zh": "\u6458\u8981 \u957f\u671f\u8d22\u52a1\u6210\u672c\u964d\u4f4e\u52b3\u52a8\u4f9b\u7ed9\u7684\u4fe1\u606f\u662f\u5426\u80fd\u589e\u52a0\u6bcd\u4eb2\u7684\u5de5\u4f5c\u65f6\u95f4\uff1f\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u6bcd\u4eb2\u51b3\u5b9a\u5c31\u4e1a\u6c34\u5e73\u65f6\uff0c\u957f\u671f\u8d22\u52a1\u56e0\u7d20\u5e76\u4e0d\u5904\u4e8e\u4f18\u5148\u8003\u8651\u4f4d\u7f6e\u3002\u6b64\u5916\uff0c\u76f8\u5f53\u4e00\u90e8\u5206\u5973\u6027\u5bf9\u5728\u517c\u804c\u5de5\u4f5c\u4e0b\u83b7\u5f97\u517b\u8001\u91d1\u548c\u5de5\u8d44\u589e\u957f\u7684\u9884\u671f\u8fc7\u4e8e\u4e50\u89c2\u3002\u5728\u745e\u58eb\u4e00\u9879\u5927\u89c4\u6a21\u5b9e\u5730\u5b9e\u9a8c\u4e2d\uff0c\u6211\u4eec\u968f\u673a\u5411\u517c\u804c\u6559\u5e08\u6bcd\u4eb2\u7fa4\u4f53\u63d0\u4f9b\u5173\u4e8e\u51cf\u5c11\u52b3\u52a8\u4f9b\u7ed9\u957f\u671f\u8d22\u52a1\u6210\u672c\u7684\u5ba2\u89c2\u4fe1\u606f\u3002\u5b9e\u9a8c\u7ec4\u5728\u5bf9\u8d22\u52a1\u4fe1\u606f\u7684\u9700\u6c42\u4ee5\u53ca\u5bf9\u672a\u6765\u52b3\u52a8\u4f9b\u7ed9\u8ba1\u5212\u7684\u89c4\u5212\u65b9\u9762\u5747\u6709\u663e\u8457\u63d0\u5347\uff0c\u5c24\u5176\u4f53\u73b0\u5728\u90a3\u4e9b\u4f4e\u4f30\u517c\u804c\u5de5\u4f5c\u957f\u671f\u6210\u672c\u7684\u5973\u6027\u4e2d\u3002\u5229\u7528\u5e72\u9884\u4e00\u5e74\u540e\u94fe\u63a5\u7684\u96c7\u4e3b\u884c\u653f\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u8fd9\u4e00\u7fa4\u4f53\u7684\u6bcd\u4eb2\u5de5\u4f5c\u65f6\u95f4\u589e\u52a0\u4e867%\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u51cf\u5c11\u52b3\u52a8\u4f9b\u7ed9\u51b3\u7b56\u4e2d\u7684\u4fe1\u606f\u6469\u64e6\u7684\u653f\u7b56\uff0c\u53ef\u80fd\u6709\u52a9\u4e8e\u7f13\u89e3\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u7684\u6027\u522b\u5dee\u8ddd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag001", "journal": "RFS", "title": "ESG Shocks in Global Supply Chains", "authors": ["Emilio Bisetti", "Guoman She", "Alminas \u017daldokas"], "author_details": [{"name": "Emilio Bisetti", "affiliations": ["Hong Kong University of Science and Technology , Hong Kong SAR,"]}, {"name": "Guoman She", "affiliations": ["National University of Singapore ,"]}, {"name": "Alminas \u017daldokas", "affiliations": ["National University of Singapore ,"]}], "abstract": "Abstract We show that U.S. firms cut imports by 31.8% when their international suppliers experience environmental and social (E&S) incidents. These trade cuts are larger for publicly listed U.S. importers facing high E&S investor pressure and lead to cross-country supplier reallocation, suggesting that E&S preferences in capital markets can be privately costly but have real effects for foreign suppliers. Larger trade cuts around the incident result in better supplier E&S performance in subsequent years and in the eventual resumption of trade. Our results highlight the role of investors in ensuring suppliers\u2019 E&S compliance along global supply chains.", "date": "2026-01-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag001", "title_zh": "\u5168\u7403\u4f9b\u5e94\u94fe\u4e2d\u7684ESG\u51b2\u51fb", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u5f53\u7f8e\u56fd\u4f01\u4e1a\u7684\u56fd\u9645\u4f9b\u5e94\u5546\u906d\u9047\u73af\u5883\u548c\u793e\u4f1a\uff08E&S\uff09\u4e8b\u4ef6\u65f6\uff0c\u8fd9\u4e9b\u7f8e\u56fd\u4f01\u4e1a\u4f1a\u524a\u51cf\u8fdb\u53e3\u91cf31.8%\u3002\u5bf9\u4e8e\u9762\u4e34\u8f83\u9ad8E&S\u6295\u8d44\u8005\u538b\u529b\u7684\u516c\u5f00\u4e0a\u5e02\u516c\u53f8\u8fdb\u53e3\u5546\u800c\u8a00\uff0c\u8fd9\u79cd\u8d38\u6613\u524a\u51cf\u66f4\u4e3a\u663e\u8457\uff0c\u5e76\u5bfc\u81f4\u8de8\u56fd\u4f9b\u5e94\u5546\u7684\u91cd\u65b0\u914d\u7f6e\uff0c\u8868\u660e\u8d44\u672c\u5e02\u573a\u7684E&S\u504f\u597d\u53ef\u80fd\u5bf9\u4f01\u4e1a\u5e26\u6765\u79c1\u4eba\u6210\u672c\uff0c\u4f46\u5bf9\u5916\u56fd\u4f9b\u5e94\u5546\u5177\u6709\u5b9e\u9645\u5f71\u54cd\u3002\u5728\u4e8b\u4ef6\u53d1\u751f\u540e\uff0c\u8d38\u6613\u524a\u51cf\u5e45\u5ea6\u8d8a\u5927\uff0c\u540e\u7eed\u5e74\u4efd\u4e2d\u4f9b\u5e94\u5546\u7684E&S\u8868\u73b0\u4e5f\u8d8a\u597d\uff0c\u6700\u7ec8\u8d38\u6613\u4f1a\u6062\u590d\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u51f8\u663e\u4e86\u6295\u8d44\u8005\u5728\u786e\u4fdd\u5168\u7403\u4f9b\u5e94\u94fe\u4e2d\u4f9b\u5e94\u5546E&S\u5408\u89c4\u65b9\u9762\u6240\u8d77\u7684\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/qje/qjag002", "journal": "QJE", "title": "The Future in Mind: Aspirations and Long-Term Outcomes in Rural Ethiopia", "authors": ["Tanguy Bernard", "Stefan Dercon", "Kate Orkin", "Giulio Schinaia", "Alemayehu Seyoum Taffesse"], "author_details": [{"name": "Tanguy Bernard", "affiliations": ["Bordeaux School of Economics (BxSE) \u2013 University of Bordeaux and Centre National de la Recherche Scientifique (CNRS) and Institut National de Recherche pour l'Agriculture, l'Alimentation et l'Environnement (INRAE) ,"]}, {"name": "Stefan Dercon", "affiliations": ["University of Oxford and Centre for Economic Policy and Research (CEPR), United Kingdom and Bureau for Research and Economic Analysis of Development (BREAD) ,"]}, {"name": "Kate Orkin", "affiliations": ["University of Oxford and Centre for Economic Policy and Research (CEPR) ,"]}, {"name": "Giulio Schinaia", "affiliations": ["University of Chicago ,"]}, {"name": "Alemayehu Seyoum Taffesse", "affiliations": ["International Food Policy Research Institute ,"]}], "abstract": "Abstract Aspirations may condition the future-oriented choices of individuals and thus may play a role in the persistence of poverty or the effort to break out of it. We run a randomized controlled trial in remote, rural Ethiopia to explore this and evaluate an intervention that aims to change how poor people perceive their future opportunities, alter their aspirations, and through that, modify their investment decisions. A treatment group was shown video documentaries featuring individuals from similar communities who escaped poverty through their own efforts and who serve as relatable role models. Five years after the screening took place, the treated households had increased future-oriented investments in agriculture, children\u2019s education, and assets. The results can be explained by an increase in aspirations in terms of lifetime goals. Overall, this research uniquely provides evidence that a light-touch behavioural intervention can have persistent economic impacts on a poor population.", "date": "2026-01-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag002", "title_zh": "\u5fc3\u4e2d\u6709\u672a\u6765\uff1a\u57c3\u585e\u4fc4\u6bd4\u4e9a\u519c\u6751\u5730\u533a\u7684\u76ee\u6807\u4e0e\u957f\u671f\u7ed3\u679c", "abstract_zh": "\u76ee\u6807\u53ef\u80fd\u4f1a\u5f71\u54cd\u4e2a\u4f53\u5bf9\u672a\u6765\u7684\u9009\u62e9\uff0c\u4ece\u800c\u5728\u8d2b\u56f0\u7684\u6301\u7eed\u6216\u6446\u8131\u8d2b\u56f0\u7684\u52aa\u529b\u4e2d\u53d1\u6325\u91cd\u8981\u4f5c\u7528\u3002\u6211\u4eec\u4e8e\u57c3\u585e\u4fc4\u6bd4\u4e9a\u504f\u8fdc\u519c\u6751\u5730\u533a\u5f00\u5c55\u4e86\u4e00\u9879\u968f\u673a\u5bf9\u7167\u8bd5\u9a8c\uff0c\u4ee5\u63a2\u8ba8\u8fd9\u4e00\u73b0\u8c61\uff0c\u5e76\u8bc4\u4f30\u4e00\u79cd\u65e8\u5728\u6539\u53d8\u8d2b\u56f0\u4eba\u53e3\u5bf9\u672a\u6765\u673a\u4f1a\u7684\u8ba4\u77e5\u3001\u8c03\u6574\u5176\u76ee\u6807\uff0c\u5e76\u901a\u8fc7\u8fd9\u4e00\u8fc7\u7a0b\u6539\u53d8\u5176\u6295\u8d44\u51b3\u7b56\u7684\u5e72\u9884\u63aa\u65bd\u3002\u5b9e\u9a8c\u7ec4\u5bb6\u5ead\u89c2\u770b\u4e86\u5c55\u793a\u6765\u81ea\u7c7b\u4f3c\u793e\u533a\u3001\u901a\u8fc7\u81ea\u8eab\u52aa\u529b\u6446\u8131\u8d2b\u56f0\u7684\u4e2a\u4f53\u7684\u89c6\u9891\u7eaa\u5f55\u7247\uff0c\u8fd9\u4e9b\u4e2a\u4f53\u4f5c\u4e3a\u53ef\u7406\u89e3\u7684\u89d2\u8272\u699c\u6837\u3002\u5728\u653e\u6620\u4e94\u5e74\u540e\uff0c\u63a5\u53d7\u5e72\u9884\u7684\u5bb6\u5ead\u5728\u519c\u4e1a\u6295\u8d44\u3001\u5b50\u5973\u6559\u80b2\u548c\u8d44\u4ea7\u79ef\u7d2f\u65b9\u9762\u8868\u73b0\u51fa\u66f4\u5f3a\u7684\u672a\u6765\u5bfc\u5411\u6027\u3002\u8fd9\u4e00\u7ed3\u679c\u53ef\u5f52\u56e0\u4e8e\u7ec8\u8eab\u76ee\u6807\u8bbe\u5b9a\u7684\u63d0\u5347\u3002\u672c\u7814\u7a76\u72ec\u7279\u5730\u63d0\u4f9b\u4e86\u8bc1\u636e\uff0c\u8868\u660e\u4e00\u79cd\u8f7b\u91cf\u7ea7\u7684\u884c\u4e3a\u5e72\u9884\u63aa\u65bd\u80fd\u591f\u5bf9\u8d2b\u56f0\u4eba\u53e3\u4ea7\u751f\u6301\u4e45\u7684\u7ecf\u6d4e\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhag002", "journal": "RFS", "title": "Price Discovery on Decentralized Exchanges", "authors": ["Agostino Capponi", "Ruizhe Jia", "Shihao Yu"], "author_details": [{"name": "Agostino Capponi", "affiliations": ["Columbia University the United States"]}, {"name": "Ruizhe Jia", "affiliations": ["Stanford University the United States"]}, {"name": "Shihao Yu", "affiliations": ["Singapore Management University Singapore"]}], "abstract": "Abstract Decentralized exchanges (DEXs) allow traders to express their willingness to pay for quick execution through a public priority fee bidding mechanism. We provide evidence that high-fee DEX trades are more informative and contribute more to price discovery. Using address-level blockchain transaction data, we show that informed traders persistently bid higher fees to secure early execution, revealing a strong willingness to pay for execution priority. Further, analysis of Ethereum mempool data demonstrates that informed traders employ a \u201cjump bidding\u201d strategy, placing high initial bids to deter potential competitors.", "date": "2026-01-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag002", "title_zh": "\u53bb\u4e2d\u5fc3\u5316\u4ea4\u6613\u6240\u7684\u4ef7\u683c\u53d1\u73b0", "abstract_zh": "\u6458\u8981 \u53bb\u4e2d\u5fc3\u5316\u4ea4\u6613\u6240\uff08DEX\uff09\u5141\u8bb8\u4ea4\u6613\u8005\u901a\u8fc7\u516c\u5f00\u7684\u4f18\u5148\u8d39\u51fa\u4ef7\u673a\u5236\u8868\u8fbe\u5176\u5bf9\u5feb\u901f\u6267\u884c\u7684\u652f\u4ed8\u610f\u613f\u3002\u6211\u4eec\u63d0\u4f9b\u4e86\u8bc1\u636e\u8868\u660e\uff0c\u9ad8\u8d39\u7528\u7684DEX\u4ea4\u6613\u66f4\u5177\u4fe1\u606f\u542b\u91cf\uff0c\u5e76\u5bf9\u4ef7\u683c\u53d1\u73b0\u8d21\u732e\u66f4\u5927\u3002\u5229\u7528\u5730\u5740\u7ea7\u522b\u7684\u533a\u5757\u94fe\u4ea4\u6613\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u77e5\u60c5\u4ea4\u6613\u8005\u6301\u7eed\u4ee5\u66f4\u9ad8\u7684\u8d39\u7528\u51fa\u4ef7\u4ee5\u786e\u4fdd\u65e9\u671f\u6267\u884c\uff0c\u663e\u793a\u51fa\u5f3a\u70c8\u7684\u652f\u4ed8\u610f\u613f\u4ee5\u83b7\u53d6\u6267\u884c\u4f18\u5148\u6743\u3002\u6b64\u5916\uff0c\u5bf9\u4ee5\u592a\u574a\u5185\u5b58\u6c60\u6570\u636e\u7684\u5206\u6790\u8868\u660e\uff0c\u77e5\u60c5\u4ea4\u6613\u8005\u91c7\u7528\u4e00\u79cd\u201c\u8df3\u8dc3\u51fa\u4ef7\u201d\u7b56\u7565\uff0c\u5373\u5728\u521d\u671f\u63d0\u51fa\u9ad8\u989d\u62a5\u4ef7\u4ee5\u963b\u6b62\u6f5c\u5728\u7ade\u4e89\u8005\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e02\u573a\u53cd\u9988"]}, {"doi": "10.1093/rfs/hhaf110", "journal": "RFS", "title": "Dividend Momentum and Stock Return Predictability: A Bayesian Approach", "authors": ["Juan Antol\u00edn-D\u00edaz", "Ivan Petrella", "Juan Rubio-Ram\u00edrez"], "author_details": [{"name": "Juan Antol\u00edn-D\u00edaz", "affiliations": ["Massachusetts Institute of Technology ,"]}, {"name": "Ivan Petrella", "affiliations": ["Collegio Carlo Alberto, University of Turin ,"]}, {"name": "Juan Rubio-Ram\u00edrez", "affiliations": ["Emory University and Federal Reserve Bank of Atlanta ,"]}], "abstract": "Abstract A long tradition in macro-finance studies the dynamics of aggregate stock returns and dividends using vector autoregressions, imposing the restrictions implied by the Campbell-Shiller (CS) identity to sharpen inference. We develop Bayesian methods that encode a priori skepticism about return predictability while imposing the restrictions. We highlight that persistence in dividend growth induces \u201cdividend momentum,\u201d a previously overlooked channel for return predictability. By combining Bayesian shrinkage and the CS restrictions, we obtain more plausible degrees of return predictability, superior out-of-sample forecasts, and Sharpe ratios, which cannot be obtained by using either shrinkage or the CS restrictions on their own.", "date": "2026-01-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf110", "title_zh": "\u80a1\u606f\u52a8\u91cf\u4e0e\u80a1\u7968\u6536\u76ca\u7387\u53ef\u9884\u6d4b\u6027\uff1a\u4e00\u79cd\u8d1d\u53f6\u65af\u65b9\u6cd5", "abstract_zh": "\u6458\u8981 \u5728\u5b8f\u89c2\u91d1\u878d\u7814\u7a76\u4e2d\uff0c\u957f\u671f\u4f20\u7edf\u4f7f\u7528\u5411\u91cf\u81ea\u56de\u5f52\u6a21\u578b\u6765\u7814\u7a76\u6574\u4f53\u80a1\u7968\u6536\u76ca\u7387\u548c\u80a1\u606f\u7684\u52a8\u6001\uff0c\u5e76\u65bd\u52a0\u574e\u8d1d\u5c14-\u5e0c\u5c14\uff08CS\uff09\u6052\u7b49\u5f0f\u6240\u9690\u542b\u7684\u9650\u5236\u4ee5\u589e\u5f3a\u63a8\u65ad\u3002\u6211\u4eec\u5f00\u53d1\u4e86\u8d1d\u53f6\u65af\u65b9\u6cd5\uff0c\u8fd9\u4e9b\u65b9\u6cd5\u5728\u65bd\u52a0\u9650\u5236\u7684\u540c\u65f6\uff0c\u4f53\u73b0\u5bf9\u6536\u76ca\u7387\u53ef\u9884\u6d4b\u6027\u7684\u5148\u9a8c\u6000\u7591\u3002\u6211\u4eec\u6307\u51fa\uff0c\u80a1\u606f\u589e\u957f\u7387\u7684\u6301\u7eed\u6027\u4f1a\u5f15\u53d1\u201c\u80a1\u606f\u52a8\u91cf\u201d\uff0c\u8fd9\u662f\u4e00\u79cd\u6b64\u524d\u88ab\u5ffd\u89c6\u7684\u6536\u76ca\u7387\u53ef\u9884\u6d4b\u6027\u6e20\u9053\u3002\u901a\u8fc7\u7ed3\u5408\u8d1d\u53f6\u65af\u6536\u7f29\u548cCS\u9650\u5236\uff0c\u6211\u4eec\u5f97\u5230\u4e86\u66f4\u5408\u7406\u7684\u6536\u76ca\u7387\u53ef\u9884\u6d4b\u7a0b\u5ea6\uff0c\u4ee5\u53ca\u4f18\u4e8e\u4ec5\u4f7f\u7528\u6536\u7f29\u6216\u4ec5\u4f7f\u7528CS\u9650\u5236\u7684\u6837\u672c\u5916\u9884\u6d4b\u548c\u590f\u666e\u6bd4\u7387\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/rfs/hhag003", "journal": "RFS", "title": "Investor-Driven Corporate Finance: Evidence from Insurance Markets", "authors": ["Christian Kubitza"], "author_details": [{"name": "Christian Kubitza", "affiliations": ["European Central Bank ,"]}], "abstract": "Abstract I study the effect of bond investor demand on the financing and investment decisions of nonfinancial firms using granular data on the bond transactions of insurance companies. Liquidity inflows from insurance premiums combined with insurers\u2019 persistent investment preferences identify bond demand shifts in the secondary market. These raise bond prices and reduce firms\u2019 financing costs. In response, firms issue more bonds, especially when they have well-connected bond underwriters. The proceeds are used for investment activities, particularly by financially constrained firms. My findings emphasize that bond investors significantly affect corporate decisions through their price impact.", "date": "2026-01-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhag003", "title_zh": "\u6295\u8d44\u8005\u9a71\u52a8\u7684\u4f01\u4e1a\u91d1\u878d\uff1a\u6765\u81ea\u4fdd\u9669\u5e02\u573a\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u5229\u7528\u4fdd\u9669\u516c\u53f8\u503a\u5238\u4ea4\u6613\u7684\u8be6\u7ec6\u6570\u636e\uff0c\u7814\u7a76\u4e86\u503a\u5238\u6295\u8d44\u8005\u9700\u6c42\u5bf9\u4f01\u4e1a\u975e\u91d1\u878d\u4f01\u4e1a\u7684\u878d\u8d44\u548c\u6295\u8d44\u51b3\u7b56\u7684\u5f71\u54cd\u3002\u6765\u81ea\u4fdd\u9669\u4fdd\u8d39\u7684\u6d41\u52a8\u6027\u6d41\u5165\uff0c\u7ed3\u5408\u4fdd\u9669\u516c\u53f8\u6301\u7eed\u7684\u6295\u8d44\u504f\u597d\uff0c\u80fd\u591f\u8bc6\u522b\u4e8c\u7ea7\u5e02\u573a\u4e0a\u7684\u503a\u5238\u9700\u6c42\u53d8\u5316\u3002\u8fd9\u4e9b\u53d8\u5316\u4f1a\u63a8\u9ad8\u503a\u5238\u4ef7\u683c\uff0c\u964d\u4f4e\u4f01\u4e1a\u7684\u878d\u8d44\u6210\u672c\u3002\u4f5c\u4e3a\u56de\u5e94\uff0c\u4f01\u4e1a\u53d1\u884c\u66f4\u591a\u503a\u5238\uff0c\u5c24\u5176\u662f\u90a3\u4e9b\u62e5\u6709\u826f\u597d\u503a\u5238\u627f\u9500\u5546\u7f51\u7edc\u7684\u4f01\u4e1a\u3002\u6240\u5f97\u8d44\u91d1\u4e3b\u8981\u7528\u4e8e\u6295\u8d44\u6d3b\u52a8\uff0c\u7279\u522b\u662f\u5bf9\u8d22\u52a1\u53d7\u9650\u7684\u4f01\u4e1a\u800c\u8a00\u3002\u6211\u7684\u7814\u7a76\u7ed3\u679c\u5f3a\u8c03\uff0c\u503a\u5238\u6295\u8d44\u8005\u901a\u8fc7\u5176\u4ef7\u683c\u5f71\u54cd\uff0c\u663e\u8457\u5f71\u54cd\u4f01\u4e1a\u7684\u51b3\u7b56\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70009", "journal": "JF", "title": "Institutional Investor Attention", "authors": ["ALAN KWAN", "YUKUN LIU", "BEN MATTHIES"], "author_details": [{"name": "ALAN KWAN", "affiliations": []}, {"name": "YUKUN LIU", "affiliations": []}, {"name": "BEN MATTHIES", "affiliations": []}], "abstract": "ABSTRACT Using data on Internet news reading, we measure fund\u2010level attention to both aggregate and firm\u2010specific news and relate it to fund portfolio allocation decisions. In the time series, we find that funds shift attention toward macroeconomic news during periods of high aggregate volatility. Those funds that exhibit stronger attention\u2010reallocation patterns earn higher future returns. In the cross\u2010section of fund portfolios, fund attention is positively related to stock holdings. Furthermore, fund attention to a stock increases the value\u2010add of that position to the fund's performance. This relationship is stronger using fund attention to more value\u2010relevant news articles.", "date": "2026-01-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70009", "title_zh": "\u673a\u6784\u6295\u8d44\u8005\u5173\u6ce8", "abstract_zh": "\u6458\u8981 \u4f7f\u7528\u4e92\u8054\u7f51\u65b0\u95fb\u9605\u8bfb\u6570\u636e\uff0c\u6211\u4eec\u6d4b\u91cf\u4e86\u57fa\u91d1\u5c42\u9762\u5bf9\u4e8e\u5b8f\u89c2\u7ecf\u6d4e\u548c\u516c\u53f8\u7279\u5b9a\u65b0\u95fb\u7684\u5173\u6ce8\u7a0b\u5ea6\uff0c\u5e76\u5c06\u5176\u4e0e\u57fa\u91d1\u7684\u6295\u8d44\u7ec4\u5408\u51b3\u7b56\u76f8\u5173\u8054\u3002\u5728\u65f6\u95f4\u5e8f\u5217\u5206\u6790\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u5b8f\u89c2\u7ecf\u6d4e\u6ce2\u52a8\u6027\u8f83\u9ad8\u7684\u65f6\u671f\uff0c\u57fa\u91d1\u4f1a\u5c06\u5173\u6ce8\u8f6c\u5411\u5b8f\u89c2\u7ecf\u6d4e\u65b0\u95fb\u3002\u8868\u73b0\u51fa\u66f4\u5f3a\u5173\u6ce8\u91cd\u65b0\u5206\u914d\u6a21\u5f0f\u7684\u57fa\u91d1\uff0c\u5176\u672a\u6765\u6536\u76ca\u66f4\u9ad8\u3002\u5728\u57fa\u91d1\u6295\u8d44\u7ec4\u5408\u7684\u6a2a\u622a\u9762\u5206\u6790\u4e2d\uff0c\u57fa\u91d1\u7684\u5173\u6ce8\u7a0b\u5ea6\u4e0e\u80a1\u7968\u6301\u4ed3\u5448\u6b63\u76f8\u5173\u5173\u7cfb\u3002\u6b64\u5916\uff0c\u57fa\u91d1\u5bf9\u67d0\u53ea\u80a1\u7968\u7684\u5173\u6ce8\u7a0b\u5ea6\u4f1a\u63d0\u9ad8\u8be5\u80a1\u7968\u5728\u57fa\u91d1\u6574\u4f53\u8868\u73b0\u4e2d\u7684\u4ef7\u503c\u8d21\u732e\u3002\u8fd9\u4e00\u5173\u7cfb\u5728\u4f7f\u7528\u66f4\u5177\u6709\u4ef7\u503c\u76f8\u5173\u6027\u7684\u65b0\u95fb\u6587\u7ae0\u4f5c\u4e3a\u5173\u6ce8\u5bf9\u8c61\u65f6\u66f4\u4e3a\u663e\u8457\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1017/s0022109025102391", "journal": "JFQA", "title": "Who Prices Credit Rating Inflation?", "authors": ["Christoph Herpfer", "Gonzalo Maturana"], "author_details": [{"name": "Christoph Herpfer", "affiliations": ["University of Virginia Darden School of Business"]}, {"name": "Gonzalo Maturana", "affiliations": ["Emory University Goizueta Business School"]}], "abstract": "Abstract Credit rating agencies (CRAs) are less likely and slower to downgrade firms with performance-sensitive debt (PSD) if these downgrades increase borrowing costs. This effect is stronger when CRAs rate their most profitable clients and is not driven by selection into PSD contracts, by borrowers adjusting their leverage, or by borrowers hiding information. Originating banks price the CRAs\u2019 conflicts of interest and sell loans with more embedded conflicts more frequently. In contrast, secondary market participants do not price conflicts of interest to the same extent. The recent settlements between the major CRAs and the U.S. government do not prevent rating inflation.", "date": "2026-01-16", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102391", "title_zh": "\u8c01\u4e3a\u4fe1\u7528\u8bc4\u7ea7\u901a\u80c0\u5b9a\u4ef7\uff1f", "abstract_zh": "\u4fe1\u7528\u8bc4\u7ea7\u673a\u6784\uff08CRAs\uff09\u5728\u503a\u52a1\u8868\u73b0\u654f\u611f\u578b\uff08PSD\uff09\u4f01\u4e1a\u51fa\u73b0\u8fdd\u7ea6\u65f6\uff0c\u66f4\u4e0d\u613f\u610f\u4e14\u66f4\u7f13\u6162\u5730\u4e0b\u8c03\u5176\u8bc4\u7ea7\uff0c\u56e0\u4e3a\u6b64\u7c7b\u4e0b\u8c03\u4f1a\u589e\u52a0\u501f\u6b3e\u6210\u672c\u3002\u8fd9\u4e00\u6548\u5e94\u5728\u8bc4\u7ea7\u673a\u6784\u4e3b\u8981\u4e3a\u6700\u76c8\u5229\u5ba2\u6237\u8bc4\u7ea7\u65f6\u66f4\u4e3a\u663e\u8457\uff0c\u5e76\u4e14\u5e76\u975e\u7531\u9009\u62e9\u8fdb\u5165PSD\u5408\u540c\u3001\u501f\u6b3e\u4eba\u8c03\u6574\u6760\u6746\u6216\u501f\u6b3e\u4eba\u9690\u85cf\u4fe1\u606f\u6240\u9a71\u52a8\u3002\u53d1\u8d37\u94f6\u884c\u4f1a\u5b9a\u4ef7\u8bc4\u7ea7\u673a\u6784\u7684\u5229\u76ca\u51b2\u7a81\uff0c\u5e76\u66f4\u9891\u7e41\u5730\u51fa\u552e\u5305\u542b\u66f4\u591a\u5229\u76ca\u51b2\u7a81\u7684\u8d37\u6b3e\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u4e8c\u7ea7\u5e02\u573a\u53c2\u4e0e\u8005\u5e76\u672a\u4ee5\u540c\u7b49\u7a0b\u5ea6\u5bf9\u5229\u76ca\u51b2\u7a81\u8fdb\u884c\u5b9a\u4ef7\u3002\u6700\u8fd1\u7f8e\u56fd\u653f\u5e9c\u4e0e\u4e3b\u8981\u4fe1\u7528\u8bc4\u7ea7\u673a\u6784\u8fbe\u6210\u7684\u548c\u89e3\u534f\u8bae\u5e76\u672a\u963b\u6b62\u8bc4\u7ea7\u901a\u80c0\u7684\u51fa\u73b0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjag001", "journal": "QJE", "title": "Leveraging Virtual Contact and Social Networks to Foster Interethnic Harmony", "authors": ["Abu Siddique", "Michael Vlassopoulos", "Yves Zenou"], "author_details": [{"name": "Abu Siddique", "affiliations": ["Royal Holloway University of London; Institute for Fiscal Studies; and Institute of Labor Economics ,"]}, {"name": "Michael Vlassopoulos", "affiliations": ["University of Southampton; Institute for Fiscal Studies; and Institute of Labor Economics ,"]}, {"name": "Yves Zenou", "affiliations": ["Monash University; Center for Economic Policy and Research; and Institute of Labor Economics ,"]}], "abstract": "Abstract This article investigates whether virtual contact, initiated through a documentary film, can promote interethnic harmony. We carried out a cluster-randomized field experiment involving over 3,300 households across 121 multiethnic villages in Bangladesh. We find that a documentary film, designed to humanize the ethnic-minority Santals and evoke empathy among the ethnic majority Bengalis, increased the ethnic majority\u2019s prosociality toward minorities, though the strength of the evidence varies by treatment arm and outcome. Using emotion-detecting software to analyze facial expressions during the film viewing suggests that the documentary elicited emotional responses consistent with empathy. We do not find evidence that the intervention reduced the prevalence of negative stereotypes and discriminatory opinions toward minorities. In villages assigned to target network-central people, we find positive behavioral effects on untreated individuals, including Santals, and village-level administrative data suggest a reduction in police complaints in those villages. About five months after the intervention, we conducted a casual-work field experiment involving 720 participants from the main intervention. In this task, pairs of ethnic-majority and minority participants jointly produced paper bags for a local supplier under a piece-rate compensation scheme. We find positive treatment effects on productivity for both ethnic groups, with effects concentrated in villages where network-central people were treated. For the ethnic majority, increased prosociality, and for the ethnic minority, reciprocity or peer pressure may have contributed to increased productivity. Overall, our findings suggest that virtual contact and social networks may help promote harmony in multiethnic communities.", "date": "2026-01-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjag001", "title_zh": "\u5229\u7528\u865a\u62df\u63a5\u89e6\u548c\u793e\u4f1a\u7f51\u7edc\u4fc3\u8fdb\u8de8\u65cf\u7fa4\u548c\u8c10", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u901a\u8fc7\u7eaa\u5f55\u7247\u5f15\u53d1\u7684\u865a\u62df\u63a5\u89e6\u662f\u5426\u80fd\u591f\u4fc3\u8fdb\u8de8\u65cf\u7fa4\u548c\u8c10\u3002\u6211\u4eec\u5bf9\u5b5f\u52a0\u62c9\u56fd121\u4e2a\u591a\u5143\u65cf\u7fa4\u6751\u5e84\u4e2d\u7684\u8d85\u8fc73300\u6237\u5bb6\u5ead\u8fdb\u884c\u4e86\u96c6\u7fa4\u968f\u673a\u5b9e\u5730\u5b9e\u9a8c\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u65e8\u5728\u4eba\u6027\u5316\u63cf\u7ed8\u5c11\u6570\u65cf\u7fa4\u6851\u5854\u5c14\u4eba\u5e76\u6fc0\u53d1\u591a\u6570\u65cf\u7fa4\u5b5f\u52a0\u62c9\u4eba\u5171\u60c5\u7684\u7eaa\u5f55\u7247\uff0c\u786e\u5b9e\u63d0\u5347\u4e86\u591a\u6570\u65cf\u7fa4\u5bf9\u5c11\u6570\u65cf\u7fa4\u7684\u5229\u4ed6\u884c\u4e3a\uff0c\u4f46\u4e0d\u540c\u5904\u7406\u7ec4\u548c\u7ed3\u679c\u4e4b\u95f4\u7684\u8bc1\u636e\u5f3a\u5ea6\u5b58\u5728\u5dee\u5f02\u3002\u901a\u8fc7\u5206\u6790\u89c2\u5f71\u8fc7\u7a0b\u4e2d\u9762\u90e8\u8868\u60c5\u7684\u8f6f\u4ef6\u68c0\u6d4b\u53d1\u73b0\uff0c\u7eaa\u5f55\u7247\u786e\u5b9e\u5f15\u53d1\u4e86\u4e0e\u5171\u60c5\u4e00\u81f4\u7684\u60c5\u611f\u53cd\u5e94\u3002\u7136\u800c\uff0c\u6211\u4eec\u5e76\u672a\u53d1\u73b0\u8be5\u5e72\u9884\u63aa\u65bd\u80fd\u591f\u51cf\u5c11\u5bf9\u5c11\u6570\u65cf\u7fa4\u7684\u8d1f\u9762\u523b\u677f\u5370\u8c61\u548c\u6b67\u89c6\u6027\u89c2\u70b9\u3002\u5728\u6307\u5b9a\u9488\u5bf9\u7f51\u7edc\u4e2d\u5fc3\u4eba\u7269\u7684\u6751\u5e84\u4e2d\uff0c\u6211\u4eec\u89c2\u5bdf\u5230\u5bf9\u672a\u63a5\u53d7\u5904\u7406\u7684\u4e2a\u4f53\uff08\u5305\u62ec\u6851\u5854\u5c14\u4eba\uff09\u4ea7\u751f\u4e86\u79ef\u6781\u7684\u884c\u4e3a\u6548\u5e94\uff0c\u4e14\u6751\u5e84\u5c42\u9762\u7684\u884c\u653f\u6570\u636e\u8868\u660e\u8fd9\u4e9b\u6751\u5e84\u7684\u8b66\u5bdf\u6295\u8bc9\u6570\u91cf\u6709\u6240\u4e0b\u964d\u3002\u5e72\u9884\u540e\u7ea6\u4e94\u4e2a\u6708\uff0c\u6211\u4eec\u5bf9\u4e3b\u8981\u5e72\u9884\u7ec4\u4e2d\u7684720\u540d\u53c2\u4e0e\u8005\u8fdb\u884c\u4e86\u4e34\u65f6\u6027\u5de5\u4f5c\u5b9e\u5730\u5b9e\u9a8c\uff0c\u53c2\u4e0e\u8005\u4ee5\u5c0f\u7ec4\u5f62\u5f0f\u4e3a\u5f53\u5730\u4f9b\u5e94\u5546\u5171\u540c\u5236\u4f5c\u7eb8\u888b\uff0c\u5e76\u91c7\u7528\u8ba1\u4ef6\u62a5\u916c\u5236\u5ea6\u3002\u5b9e\u9a8c\u7ed3\u679c\u663e\u793a\uff0c\u65e0\u8bba\u591a\u6570\u65cf\u7fa4\u8fd8\u662f\u5c11\u6570\u65cf\u7fa4\uff0c\u5176\u751f\u4ea7\u6548\u7387\u5747\u6709\u6240\u63d0\u5347\uff0c\u4e14\u6548\u679c\u4e3b\u8981\u96c6\u4e2d\u5728\u88ab\u5904\u7406\u7684\u7f51\u7edc\u4e2d\u5fc3\u4eba\u7269\u6240\u5728\u7684\u6751\u5e84\u3002\u5bf9\u4e8e\u591a\u6570\u65cf\u7fa4\u800c\u8a00\uff0c\u5176\u751f\u4ea7\u6548\u7387\u7684\u63d0\u5347\u53ef\u80fd\u6e90\u4e8e\u5171\u60c5\u884c\u4e3a\u7684\u589e\u5f3a\uff1b\u800c\u5bf9\u4e8e\u5c11\u6570\u65cf\u7fa4\u800c\u8a00\uff0c\u751f\u4ea7\u6548\u7387\u7684\u63d0\u5347\u53ef\u80fd\u6e90\u4e8e\u4e92\u60e0\u884c\u4e3a\u6216\u540c\u4f34\u538b\u529b\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u865a\u62df\u63a5\u89e6\u548c\u793e\u4f1a\u7f51\u7edc\u53ef\u80fd\u6709\u52a9\u4e8e\u4fc3\u8fdb\u591a\u5143\u65cf\u7fa4\u793e\u533a\u4e2d\u7684\u548c\u8c10\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/qje/qjaf056", "journal": "QJE", "title": "Growth Experiences and Trust in Government", "authors": ["Timothy Besley", "Christopher Dann", "Sacha Dray"], "author_details": [{"name": "Timothy Besley", "affiliations": ["London School of Economics and Political Science ,"]}, {"name": "Christopher Dann", "affiliations": ["Stanford University ,"]}, {"name": "Sacha Dray", "affiliations": ["The World Bank ,"]}], "abstract": "Abstract This article explores the relationship between economic growth and trust in government using variation in GDP growth experienced over a lifetime since birth. We assemble a newly harmonized global data set across 11 major opinion surveys, comprising 3.3 million respondents in 166 countries since 1990. Exploiting cohort-level variation, we find that people who have experienced higher GDP growth are more prone to trust their governments, with larger effects found in democracies. Higher-growth experiences are also associated with improved perceptions of government performance and living standards. We find no similar channel between growth experience and interpersonal trust. Second, more recent growth experiences appear to matter most for trust in government, with no detectable effect of growth experienced during one\u2019s formative years, closer to birth, or before birth. Third, we find evidence of a \u201ctrust paradox\u201d whereby average trust in government is lower in democracies than in autocracies. Our results are robust to a range of falsification exercises, robustness checks, and single-country evidence using the American National Election Studies and the Swiss Household Panel.", "date": "2026-01-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf056", "title_zh": "\u7ecf\u6d4e\u589e\u957f\u4e0e\u653f\u5e9c\u4fe1\u4efb", "abstract_zh": "\u672c\u6587\u63a2\u8ba8\u4e86\u7ecf\u6d4e\u589e\u957f\u4e0e\u653f\u5e9c\u4fe1\u4efb\u4e4b\u95f4\u7684\u5173\u7cfb\uff0c\u5229\u7528\u4e2a\u4f53\u81ea\u51fa\u751f\u4ee5\u6765\u4e00\u751f\u4e2d\u7ecf\u5386\u7684GDP\u589e\u957f\u5dee\u5f02\u8fdb\u884c\u5206\u6790\u3002\u6211\u4eec\u6574\u5408\u4e8611\u4e2a\u4e3b\u8981\u6c11\u610f\u8c03\u67e5\u7684\u5168\u7403\u6570\u636e\uff0c\u6db5\u76d6\u81ea1990\u5e74\u4ee5\u6765166\u4e2a\u56fd\u5bb6\u7684330\u4e07\u53d7\u8bbf\u8005\u3002\u5229\u7528\u961f\u5217\u5c42\u9762\u7684\u53d8\u5f02\uff0c\u6211\u4eec\u53d1\u73b0\u90a3\u4e9b\u7ecf\u5386\u66f4\u9ad8GDP\u589e\u957f\u7684\u4eba\u66f4\u503e\u5411\u4e8e\u4fe1\u4efb\u653f\u5e9c\uff0c\u4e14\u5728\u6c11\u4e3b\u56fd\u5bb6\u4e2d\u8fd9\u4e00\u6548\u5e94\u66f4\u4e3a\u663e\u8457\u3002\u8f83\u9ad8\u7684\u589e\u957f\u7ecf\u5386\u4e5f\u4e0e\u5bf9\u653f\u5e9c\u7ee9\u6548\u548c\u751f\u6d3b\u6807\u51c6\u7684\u66f4\u79ef\u6781\u8bc4\u4ef7\u76f8\u5173\u3002\u6211\u4eec\u672a\u53d1\u73b0\u7ecf\u6d4e\u589e\u957f\u7ecf\u5386\u4e0e\u4eba\u9645\u4fe1\u4efb\u4e4b\u95f4\u5b58\u5728\u7c7b\u4f3c\u5173\u8054\u3002\u5176\u6b21\uff0c\u6700\u8fd1\u7684\u7ecf\u6d4e\u589e\u957f\u7ecf\u5386\u5bf9\u653f\u5e9c\u4fe1\u4efb\u7684\u5f71\u54cd\u6700\u4e3a\u663e\u8457\uff0c\u800c\u51fa\u751f\u524d\u540e\u6216\u65e9\u671f\u6210\u957f\u9636\u6bb5\u7ecf\u5386\u7684\u589e\u957f\u5219\u65e0\u660e\u663e\u5f71\u54cd\u3002\u7b2c\u4e09\uff0c\u6211\u4eec\u53d1\u73b0\u4e86\u201c\u4fe1\u4efb\u6096\u8bba\u201d\u73b0\u8c61\uff0c\u5373\u6c11\u4e3b\u56fd\u5bb6\u7684\u653f\u5e9c\u5e73\u5747\u4fe1\u4efb\u5ea6\u4f4e\u4e8e\u4e13\u5236\u56fd\u5bb6\u3002\u6211\u4eec\u7684\u7ed3\u679c\u5728\u591a\u79cd\u53cd\u4e8b\u5b9e\u68c0\u9a8c\u3001\u7a33\u5065\u6027\u68c0\u67e5\u4ee5\u53ca\u7f8e\u56fd\u5168\u56fd\u9009\u4e3e\u7814\u7a76\u548c\u745e\u58eb\u5bb6\u5ead\u9762\u677f\u7684\u5355\u56fd\u6570\u636e\u4e2d\u5747\u4fdd\u6301\u7a33\u5065\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109026102579", "journal": "JFQA", "title": "Match to Grow", "authors": ["Nasim Sabah", "Michael Zheng"], "author_details": [{"name": "Nasim Sabah", "affiliations": ["Louisiana Tech University"]}, {"name": "Michael Zheng", "affiliations": ["Missouri State University"]}], "abstract": "Abstract This study proposes a specific channel through which labor markets facilitate firm growth: the occupational alignment between an establishment\u2019s workforce and local skills. Using occupational employment statistics, we construct an index that compares each establishment\u2019s occupational mix to that of its local market. Establishments with higher alignment grow faster in sales and employment. This growth comes primarily through lower adjustment costs and higher capital investment. We also show that the effects are most pronounced in establishments with a higher share of skilled workers and industries with higher idiosyncratic cash flow risk. This employee\u2013firm matching channel helps explain how local labor markets translate into competitive advantage.", "date": "2026-01-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109026102579", "title_zh": "\u5339\u914d\u4ee5\u589e\u957f", "abstract_zh": "\u672c\u6587\u63d0\u51fa\u4e86\u52b3\u52a8\u529b\u5e02\u573a\u4fc3\u8fdb\u4f01\u4e1a\u6210\u957f\u7684\u4e00\u4e2a\u5177\u4f53\u6e20\u9053\uff1a\u4f01\u4e1a\u5458\u5de5\u961f\u4f0d\u4e0e\u5f53\u5730\u6280\u80fd\u7ed3\u6784\u4e4b\u95f4\u7684\u804c\u4e1a\u5339\u914d\u3002\u5229\u7528\u804c\u4e1a\u5c31\u4e1a\u7edf\u8ba1\u6570\u636e\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6307\u6570\uff0c\u5c06\u6bcf\u5bb6\u4f01\u4e1a\u5458\u5de5\u7684\u804c\u4e1a\u6784\u6210\u4e0e\u5176\u6240\u5728\u5730\u533a\u5e02\u573a\u7684\u804c\u4e1a\u6784\u6210\u8fdb\u884c\u5bf9\u6bd4\u3002\u804c\u4e1a\u5339\u914d\u5ea6\u8f83\u9ad8\u7684\u4f01\u4e1a\uff0c\u5176\u9500\u552e\u989d\u548c\u5c31\u4e1a\u4eba\u6570\u589e\u957f\u66f4\u5feb\u3002\u8fd9\u79cd\u589e\u957f\u4e3b\u8981\u6e90\u4e8e\u8c03\u6574\u6210\u672c\u7684\u964d\u4f4e\u548c\u8d44\u672c\u6295\u8d44\u7684\u589e\u52a0\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0c\u8fd9\u79cd\u6548\u5e94\u5728\u9ad8\u6bd4\u4f8b\u62e5\u6709\u6280\u80fd\u5de5\u4eba\u4f01\u4e1a\u4ee5\u53ca\u5177\u6709\u8f83\u9ad8\u7279\u8d28\u73b0\u91d1\u6d41\u98ce\u9669\u7684\u884c\u4e1a\u4e2d\u66f4\u4e3a\u663e\u8457\u3002\u8fd9\u4e00\u5458\u5de5\u4e0e\u4f01\u4e1a\u5339\u914d\u673a\u5236\u6709\u52a9\u4e8e\u89e3\u91ca\u5f53\u5730\u52b3\u52a8\u529b\u5e02\u573a\u5982\u4f55\u8f6c\u5316\u4e3a\u7ade\u4e89\u4f18\u52bf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102500", "journal": "JFQA", "title": "Debt and Taxes: The Role of Tax Avoidance", "authors": ["Peter Brok"], "author_details": [{"name": "Peter Brok", "affiliations": ["Copenhagen Business School and Danish Finance Institute"]}], "abstract": "Abstract Empirically, the effect of corporate tax rates on leverage has been smaller than expected based on trade-off theory. In this article, I show that tax avoidance functions as a non-debt tax shield, reducing the benefits of the debt tax shield. I find that higher tax rates cause higher non-debt tax avoidance, which crowds out the debt tax shield. Moreover, I show that the strength of the relationship between debt and tax rates depends on the level of tax avoidance. A 1-standard-deviation higher tax rate implies 2.8% higher leverage for low tax avoidance firms, but has a negative effect for high tax avoidance firms.", "date": "2026-01-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102500", "title_zh": "\u503a\u52a1\u4e0e\u7a0e\u6536\uff1a\u7a0e\u6536\u907f\u7a0e\u7684\u4f5c\u7528", "abstract_zh": "\u5b9e\u8bc1\u7814\u7a76\u8868\u660e\uff0c\u4f01\u4e1a\u6240\u5f97\u7a0e\u7387\u5bf9\u6760\u6746\u6bd4\u7387\u7684\u5f71\u54cd\u5c0f\u4e8e\u57fa\u4e8e\u6743\u8861\u7406\u8bba\u7684\u9884\u671f\u3002\u672c\u6587\u8868\u660e\uff0c\u7a0e\u6536\u907f\u7a0e\u4f5c\u4e3a\u4e00\u79cd\u975e\u503a\u52a1\u7a0e\u6536\u4fdd\u62a4\u63aa\u65bd\uff0c\u524a\u5f31\u4e86\u503a\u52a1\u7a0e\u6536\u62b5\u514d\u7684\u6548\u76ca\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u7a0e\u7387\u8d8a\u9ad8\uff0c\u4f01\u4e1a\u8fdb\u884c\u7684\u975e\u503a\u52a1\u7a0e\u6536\u907f\u7a0e\u884c\u4e3a\u4e5f\u8d8a\u591a\uff0c\u4ece\u800c\u62b5\u6d88\u4e86\u503a\u52a1\u7a0e\u6536\u62b5\u514d\u7684\u4f5c\u7528\u3002\u6b64\u5916\uff0c\u503a\u52a1\u4e0e\u7a0e\u7387\u4e4b\u95f4\u7684\u5173\u7cfb\u5f3a\u5ea6\u53d6\u51b3\u4e8e\u7a0e\u6536\u907f\u7a0e\u7684\u6c34\u5e73\uff1a\u5bf9\u4e8e\u7a0e\u6536\u907f\u7a0e\u8f83\u4f4e\u7684\u4f01\u4e1a\uff0c\u7a0e\u7387\u63d0\u9ad81\u4e2a\u6807\u51c6\u5dee\u4f1a\u4f7f\u6760\u6746\u6bd4\u7387\u4e0a\u53472.8%\uff1b\u4f46\u5bf9\u4e8e\u7a0e\u6536\u907f\u7a0e\u8f83\u9ad8\u7684\u4f01\u4e1a\uff0c\u7a0e\u7387\u63d0\u9ad8\u5219\u4f1a\u4ea7\u751f\u8d1f\u5411\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102445", "journal": "JFQA", "title": "The Crash Risk in Individual Stocks Embedded in Skewness Swap Returns", "authors": ["Paola Pederzoli"], "author_details": [{"name": "Paola Pederzoli", "affiliations": ["University of Houston CT Bauer College of Business"]}], "abstract": "Abstract This article investigates crash risk premiums in individual stocks using skewness swaps. These swaps involve buying a stock\u2019s risk-neutral skewness and receiving the realized skewness as a payoff. The strategy\u2019s returns, which measure the skewness risk premium, are found to be consistently large and positive. This suggests investors are concerned about potential crashes in individual stocks and require substantial compensation for bearing this risk. Notably, significant results are mainly observed after the 2007/2009 financial crisis, indicating changes in post-crisis option market dynamics. Cross-sectional determinants of skewness swap returns include measures of systematic crash risk and stock overvaluation.", "date": "2026-01-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102445", "title_zh": "\u5d4c\u5165\u504f\u5ea6\u4e92\u6362\u56de\u62a5\u7684\u4e2a\u80a1\u5d29\u76d8\u98ce\u9669", "abstract_zh": "\u672c\u6587\u5229\u7528\u504f\u5ea6\u4e92\u6362\u7814\u7a76\u4e2a\u80a1\u7684\u5d29\u76d8\u98ce\u9669\u6ea2\u4ef7\u3002\u8fd9\u4e9b\u4e92\u6362\u6d89\u53ca\u4e70\u5165\u80a1\u7968\u7684\u98ce\u9669\u4e2d\u6027\u504f\u5ea6\u5e76\u4ee5\u5b9e\u9645\u5b9e\u73b0\u7684\u504f\u5ea6\u4f5c\u4e3a\u56de\u62a5\u3002\u8be5\u7b56\u7565\u7684\u56de\u62a5\uff0c\u5373\u504f\u5ea6\u98ce\u9669\u6ea2\u4ef7\uff0c\u88ab\u53d1\u73b0\u59cb\u7ec8\u8f83\u5927\u4e14\u4e3a\u6b63\uff0c\u8868\u660e\u6295\u8d44\u8005\u5bf9\u4e2a\u80a1\u6f5c\u5728\u5d29\u76d8\u98ce\u9669\u9ad8\u5ea6\u5173\u6ce8\uff0c\u5e76\u9700\u8981\u663e\u8457\u7684\u8865\u507f\u6765\u627f\u62c5\u8fd9\u4e00\u98ce\u9669\u3002\u503c\u5f97\u6ce8\u610f\u7684\u662f\uff0c\u663e\u8457\u7ed3\u679c\u4e3b\u8981\u51fa\u73b0\u57282007/2009\u91d1\u878d\u5371\u673a\u4e4b\u540e\uff0c\u8868\u660e\u5371\u673a\u540e\u671f\u6743\u5e02\u573a\u52a8\u6001\u53d1\u751f\u4e86\u53d8\u5316\u3002\u504f\u5ea6\u4e92\u6362\u56de\u62a5\u7684\u6a2a\u622a\u9762\u51b3\u5b9a\u56e0\u7d20\u5305\u62ec\u7cfb\u7edf\u6027\u5d29\u76d8\u98ce\u9669\u548c\u80a1\u7968\u9ad8\u4f30\u7a0b\u5ea6\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1093/qje/qjaf057", "journal": "QJE", "title": "Changing Opportunity: Sociological Mechanisms Underlying Growing Class Gaps and Shrinking Race Gaps in Economic Mobility", "authors": ["Raj Chetty", "Will Dobbie", "Benjamin Goldman", "Sonya R Porter", "Crystal S Yang"], "author_details": [{"name": "Raj Chetty", "affiliations": ["Harvard University and Opportunity Insights ,"]}, {"name": "Will Dobbie", "affiliations": ["Harvard University and Opportunity Insights ,"]}, {"name": "Benjamin Goldman", "affiliations": ["Cornell University and Opportunity Insights ,"]}, {"name": "Sonya R Porter", "affiliations": ["U.S. Census Bureau ,"]}, {"name": "Crystal S Yang", "affiliations": ["Harvard University and Opportunity Insights ,"]}], "abstract": "Abstract We show that intergenerational mobility changed rapidly by race and class in recent decades in the United States and study the causal mechanisms underlying those changes. Between the 1978 and 1992 birth cohorts, earnings increased for white children from high-income families relative to white children from low-income families, increasing earnings gaps by parental income (class) by 30%. Earnings increased for Black children at all parental income levels, reducing white-Black earnings gaps for children from low-income families by 30%. Class gaps grew and race gaps shrank similarly for nonmonetary outcomes such as educational attainment, standardized test scores, and mortality rates. Using a quasi-experimental design, we show that the divergent trends in economic mobility were caused by differential changes in childhood environments, as proxied by parental employment rates, in local communities defined by race, class, and childhood county. Outcomes improve across birth cohorts for children who grow up in communities with increasing parental employment rates, with larger effects for children who move to such communities at younger ages. Children\u2019s outcomes are most strongly related to the parental employment rates of peers they are more likely to interact with, such as those in their own birth cohort, suggesting that the relationship between children\u2019s outcomes and parental employment rates is mediated by social interaction.", "date": "2026-01-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf057", "title_zh": "\u673a\u4f1a\u7684\u8f6c\u53d8\uff1a\u5bfc\u81f4\u7f8e\u56fd\u7ecf\u6d4e\u6d41\u52a8\u6027\u9636\u7ea7\u5dee\u8ddd\u6269\u5927\u4e0e\u79cd\u65cf\u5dee\u8ddd\u7f29\u5c0f\u7684\u793e\u4f1a\u5b66\u673a\u5236", "abstract_zh": "\u6211\u4eec\u5c55\u793a\u4e86\u8fd1\u5e74\u6765\u7f8e\u56fd\u4ee3\u9645\u6d41\u52a8\u6027\u5728\u79cd\u65cf\u548c\u9636\u7ea7\u4e0a\u7684\u5feb\u901f\u53d8\u5316\uff0c\u5e76\u7814\u7a76\u4e86\u8fd9\u4e9b\u53d8\u5316\u80cc\u540e\u7684\u56e0\u679c\u673a\u5236\u3002\u57281978\u5e74\u81f31992\u5e74\u51fa\u751f\u7684\u7fa4\u4f53\u4e2d\uff0c\u9ad8\u6536\u5165\u5bb6\u5ead\u767d\u4eba\u513f\u7ae5\u7684\u6536\u5165\u76f8\u5bf9\u4e8e\u4f4e\u6536\u5165\u5bb6\u5ead\u767d\u4eba\u513f\u7ae5\u4e0a\u5347\uff0c\u5bfc\u81f4\u7531\u7236\u6bcd\u6536\u5165\uff08\u9636\u7ea7\uff09\u51b3\u5b9a\u7684\u6536\u5165\u5dee\u8ddd\u6269\u5927\u4e8630%\u3002\u9ed1\u4eba\u513f\u7ae5\u5728\u6240\u6709\u7236\u6bcd\u6536\u5165\u6c34\u5e73\u4e0a\u6536\u5165\u5747\u4e0a\u5347\uff0c\u4f7f\u5f97\u4f4e\u6536\u5165\u5bb6\u5ead\u9ed1\u4eba\u513f\u7ae5\u4e0e\u767d\u4eba\u513f\u7ae5\u4e4b\u95f4\u7684\u6536\u5165\u5dee\u8ddd\u7f29\u5c0f\u4e8630%\u3002\u5728\u6559\u80b2\u6210\u5c31\u3001\u6807\u51c6\u5316\u8003\u8bd5\u6210\u7ee9\u548c\u6b7b\u4ea1\u7387\u7b49\u975e\u8d27\u5e01\u6027\u7ed3\u679c\u65b9\u9762\uff0c\u9636\u7ea7\u5dee\u8ddd\u6269\u5927\u800c\u79cd\u65cf\u5dee\u8ddd\u7f29\u5c0f\u7684\u8d8b\u52bf\u4e5f\u7c7b\u4f3c\u3002\u901a\u8fc7\u51c6\u5b9e\u9a8c\u8bbe\u8ba1\uff0c\u6211\u4eec\u53d1\u73b0\u7ecf\u6d4e\u6d41\u52a8\u6027\u5dee\u5f02\u7684\u8d8b\u52bf\u662f\u7531\u4e0d\u540c\u7fa4\u4f53\u7ae5\u5e74\u73af\u5883\u7684\u53d8\u5316\u6240\u5bfc\u81f4\u7684\uff0c\u8fd9\u4e9b\u73af\u5883\u901a\u8fc7\u79cd\u65cf\u3001\u9636\u7ea7\u548c\u7ae5\u5e74\u6240\u5728\u53bf\u7684\u793e\u533a\u4e2d\u7684\u7236\u6bcd\u5c31\u4e1a\u7387\u6765\u4f53\u73b0\u3002\u513f\u7ae5\u5728\u6210\u957f\u8fc7\u7a0b\u4e2d\uff0c\u82e5\u6240\u5904\u793e\u533a\u7684\u7236\u6bcd\u5c31\u4e1a\u7387\u4e0a\u5347\uff0c\u5176\u7ed3\u679c\u4f1a\u6539\u5584\uff0c\u4e14\u5728\u66f4\u5e74\u5e7c\u65f6\u8fc1\u5165\u6b64\u7c7b\u793e\u533a\u7684\u513f\u7ae5\u6548\u679c\u66f4\u4e3a\u663e\u8457\u3002\u513f\u7ae5\u7684\u7ed3\u679c\u4e0e\u4ed6\u4eec\u66f4\u53ef\u80fd\u4e92\u52a8\u7684\u540c\u9f84\u4eba\u7236\u6bcd\u5c31\u4e1a\u7387\u5bc6\u5207\u76f8\u5173\uff0c\u4f8b\u5982\u4e0e\u540c\u4e00\u5e74\u51fa\u751f\u7684\u540c\u9f84\u4eba\uff0c\u8fd9\u8868\u660e\u513f\u7ae5\u7ed3\u679c\u4e0e\u7236\u6bcd\u5c31\u4e1a\u7387\u4e4b\u95f4\u7684\u5173\u7cfb\u662f\u901a\u8fc7\u793e\u4f1a\u4e92\u52a8\u6765\u4e2d\u4ecb\u7684\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70008", "journal": "JF", "title": "Corporate ESG Profiles and Investor Horizons", "authors": ["LAURA T. STARKS", "PARTH VENKAT", "QIFEI ZHU"], "author_details": [{"name": "LAURA T. STARKS", "affiliations": []}, {"name": "PARTH VENKAT", "affiliations": []}, {"name": "QIFEI ZHU", "affiliations": []}], "abstract": "ABSTRACT We find that long\u2010term institutional investors tilt their portfolios toward firms with better Environmental, Social, and Governance (ESG) profiles, in the cross sections of both institutional investor portfolios and the ownership of firms. We test whether several theoretically motivated mechanisms can explain this relationship. Our results that long\u2010term investors exhibit patience with firms around poor earnings announcements, but quickly sell portfolio firms after negative ES incidents, support the view that long\u2010 and short\u2010term investors evaluate information differently. Our evidence shows that limits\u2010to\u2010arbitrage play a role, as we find that investors' ESG tilt weakens following regulatory shocks that shorten their horizon.", "date": "2026-01-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70008", "title_zh": "\u4f01\u4e1aESG\u753b\u50cf\u4e0e\u6295\u8d44\u8005\u6295\u8d44\u671f\u9650", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u53d1\u73b0\uff0c\u957f\u671f\u673a\u6784\u6295\u8d44\u8005\u5728\u673a\u6784\u6295\u8d44\u8005\u7ec4\u5408\u548c\u4f01\u4e1a\u6240\u6709\u6743\u7684\u6a2a\u622a\u9762\u4e0a\uff0c\u503e\u5411\u4e8e\u5c06\u8d44\u91d1\u914d\u7f6e\u4e8eESG\u8868\u73b0\u66f4\u597d\u7684\u4f01\u4e1a\u3002\u6211\u4eec\u68c0\u9a8c\u4e86\u82e5\u5e72\u7406\u8bba\u4e0a\u5408\u7406\u7684\u673a\u5236\u80fd\u5426\u89e3\u91ca\u8fd9\u4e00\u5173\u7cfb\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u957f\u671f\u6295\u8d44\u8005\u5728\u4f01\u4e1a\u51fa\u73b0\u4e0d\u4f73\u8d22\u62a5\u516c\u544a\u65f6\u8868\u73b0\u51fa\u8010\u5fc3\uff0c\u4f46\u5728\u906d\u9047\u8d1f\u9762ES\u4e8b\u4ef6\u540e\u4f1a\u8fc5\u901f\u629b\u552e\u5176\u6301\u4ed3\u4f01\u4e1a\uff0c\u8fd9\u652f\u6301\u4e86\u957f\u671f\u548c\u77ed\u671f\u6295\u8d44\u8005\u4ee5\u4e0d\u540c\u65b9\u5f0f\u8bc4\u4f30\u4fe1\u606f\u7684\u89c2\u70b9\u3002\u6211\u4eec\u7684\u8bc1\u636e\u8868\u660e\uff0c\u9650\u5236\u6027\u5957\u5229\u53d1\u6325\u4e86\u4f5c\u7528\uff0c\u56e0\u4e3a\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u76d1\u7ba1\u51b2\u51fb\u7f29\u77ed\u6295\u8d44\u8005\u6295\u8d44\u671f\u9650\u4e4b\u540e\uff0c\u6295\u8d44\u8005\u5bf9ESG\u7684\u504f\u597d\u503e\u5411\u4f1a\u51cf\u5f31\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1017/s002210902510255x", "journal": "JFQA", "title": "CEO Compensation Changes Following Acquisitions", "authors": ["Leonce Bargeron", "David J. Denis"], "author_details": [{"name": "Leonce Bargeron", "affiliations": ["University of Kentucky"]}, {"name": "David J. Denis", "affiliations": ["University of Pittsburgh School of Business"]}], "abstract": "Abstract We find that CEO compensation increases following acquisitions only in those deals in which acquirer stock is used as the method of payment. These compensation increases are driven by increases in equity-based compensation and are concentrated in riskier acquirers, in riskier acquisitions, and in acquirers whose CEOs have low exposure to the stock price. We find little support for traditional agency cost explanations of changes in CEO pay following acquisitions. However, our findings are broadly consistent with compensation changes representing a contracting solution to a two-sided adverse selection problem that is present only in stock acquisitions.", "date": "2026-01-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s002210902510255x", "title_zh": "\u6536\u8d2d\u540eCEO\u85aa\u916c\u7684\u53d8\u5316", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u53ea\u6709\u5728\u6536\u8d2d\u65b9\u4f7f\u7528\u80a1\u7968\u4f5c\u4e3a\u652f\u4ed8\u65b9\u5f0f\u7684\u60c5\u51b5\u4e0b\uff0cCEO\u7684\u85aa\u916c\u624d\u4f1a\u5728\u6536\u8d2d\u540e\u589e\u52a0\u3002\u8fd9\u79cd\u85aa\u916c\u589e\u957f\u4e3b\u8981\u7531\u80a1\u6743\u6fc0\u52b1\u90e8\u5206\u7684\u589e\u52a0\u6240\u9a71\u52a8\uff0c\u5e76\u96c6\u4e2d\u5728\u98ce\u9669\u66f4\u9ad8\u7684\u6536\u8d2d\u65b9\u3001\u98ce\u9669\u66f4\u9ad8\u7684\u6536\u8d2d\u4ea4\u6613\u4ee5\u53caCEO\u5bf9\u80a1\u4ef7\u66b4\u9732\u8f83\u4f4e\u7684\u6536\u8d2d\u65b9\u4e2d\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u5bf9\u4f20\u7edf\u4ee3\u7406\u6210\u672c\u89e3\u91caCEO\u85aa\u916c\u53d8\u5316\u7684\u652f\u6301\u6709\u9650\u3002\u7136\u800c\uff0c\u6211\u4eec\u7684\u53d1\u73b0\u4e0e\u85aa\u916c\u8c03\u6574\u4f5c\u4e3a\u89e3\u51b3\u4ec5\u5b58\u5728\u4e8e\u80a1\u7968\u6536\u8d2d\u4e2d\u7684\u53cc\u8fb9\u4fe1\u606f\u4e0d\u5bf9\u79f0\u95ee\u9898\u7684\u5408\u540c\u5b89\u6392\u8fd9\u4e00\u89c2\u70b9\u57fa\u672c\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1111/jofi.70014", "journal": "JF", "title": "Default Risk and the Pricing of U.S. Sovereign Bonds", "authors": ["ROBERT F. DITTMAR", "ALEX HSU", "GUILLAUME ROUSSELLET", "PETER SIMASEK"], "author_details": [{"name": "ROBERT F. DITTMAR", "affiliations": []}, {"name": "ALEX HSU", "affiliations": []}, {"name": "GUILLAUME ROUSSELLET", "affiliations": []}, {"name": "PETER SIMASEK", "affiliations": []}], "abstract": "ABSTRACT We examine the relative pricing of nominal Treasury bonds and Treasury inflation\u2010protected securities in the presence of U.S. default risk. Hedged breakeven inflation is significantly positively related to U.S. default risk, driven by correlation between shocks to default risk and both shocks to inflation swap premia and Treasury yields. To understand the mechanisms through which default risk is related to inflation swaps and sovereign yields, we estimate an affine term structure model to capture their joint dynamics. Our estimation implies that the interaction between inflation dynamics and default is the primary source of differential pricing.", "date": "2026-01-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70014", "title_zh": "\u8fdd\u7ea6\u98ce\u9669\u4e0e\u7f8e\u56fd\u4e3b\u6743\u503a\u5238\u7684\u5b9a\u4ef7", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5728\u8003\u8651\u7f8e\u56fd\u8fdd\u7ea6\u98ce\u9669\u7684\u60c5\u51b5\u4e0b\uff0c\u7814\u7a76\u4e86\u540d\u4e49\u56fd\u503a\u4e0e\u901a\u80c0\u4fdd\u503c\u56fd\u503a\u4e4b\u95f4\u7684\u76f8\u5bf9\u5b9a\u4ef7\u3002\u7ecf\u98ce\u9669\u5bf9\u51b2\u540e\u7684\u901a\u80c0\u5dee\u4ef7\u4e0e\u7f8e\u56fd\u8fdd\u7ea6\u98ce\u9669\u663e\u8457\u6b63\u76f8\u5173\uff0c\u8fd9\u4e00\u5173\u7cfb\u7531\u8fdd\u7ea6\u98ce\u9669\u51b2\u51fb\u4e0e\u901a\u80c0\u4e92\u6362\u6ea2\u4ef7\u53ca\u56fd\u503a\u6536\u76ca\u7387\u51b2\u51fb\u4e4b\u95f4\u7684\u76f8\u5173\u6027\u9a71\u52a8\u3002\u4e3a\u4e86\u7406\u89e3\u8fdd\u7ea6\u98ce\u9669\u5982\u4f55\u5f71\u54cd\u901a\u80c0\u4e92\u6362\u548c\u4e3b\u6743\u503a\u5238\u6536\u76ca\u7387\uff0c\u6211\u4eec\u4f30\u8ba1\u4e86\u4e00\u4e2a\u4eff\u5c04\u671f\u9650\u7ed3\u6784\u6a21\u578b\u4ee5\u6355\u6349\u5b83\u4eec\u7684\u8054\u5408\u52a8\u6001\u3002\u6211\u4eec\u7684\u4f30\u8ba1\u7ed3\u679c\u8868\u660e\uff0c\u901a\u80c0\u52a8\u6001\u4e0e\u8fdd\u7ea6\u4e4b\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\u662f\u5bfc\u81f4\u5b9a\u4ef7\u5dee\u5f02\u7684\u4e3b\u8981\u539f\u56e0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102561", "journal": "JFQA", "title": "Can Lending Hierarchies Balance Bias? The Role of Personal Environmental Values in Credit to Green Firms", "authors": ["Di Bu", "Matti Keloharju", "Yin Liao", "Steven Ongena"], "author_details": [{"name": "Di Bu", "affiliations": ["Macquarie University"]}, {"name": "Matti Keloharju", "affiliations": ["Aalto University School of BusinessCentre for Economic Policy Research (CEPR) Research Institute of Industrial Economics (IFN)"]}, {"name": "Yin Liao", "affiliations": ["Macquarie University"]}, {"name": "Steven Ongena", "affiliations": ["University of ZurichSwiss Finance Institute, KU Leuven, NTNU Business School Centre for Economic Policy Research (CEPR)"]}], "abstract": "Abstract How do bankers treat green firms? Using unique loan application and banker preference data from a mid-sized bank, we find that customer managers, serving as front-line bankers, give more favorable recommendations to green firms, especially when they hold green values themselves. However, a minority of environmentally skeptical loan officers, aware through internal training that customer managers generally have greener preferences, counter this by downgrading positive evaluations of green firms. Despite not knowing the customer manager\u2019s identity, these officers use their discretion to mitigate what they perceive as green biases, demonstrating the significant moderating role of superiors within the bank\u2019s hierarchy.", "date": "2026-01-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102561", "title_zh": "\u4fe1\u8d37\u5c42\u7ea7\u80fd\u5426\u5e73\u8861\u504f\u89c1\uff1f\u4e2a\u4eba\u73af\u5883\u4ef7\u503c\u89c2\u5728\u7eff\u8272\u4f01\u4e1a\u4fe1\u8d37\u4e2d\u7684\u4f5c\u7528", "abstract_zh": "\u94f6\u884c\u5bb6\u5982\u4f55\u5bf9\u5f85\u7eff\u8272\u4f01\u4e1a\uff1f\u5229\u7528\u4e00\u5bb6\u4e2d\u578b\u94f6\u884c\u72ec\u7279\u7684\u8d37\u6b3e\u7533\u8bf7\u548c\u94f6\u884c\u5bb6\u504f\u597d\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5ba2\u6237\u7ecf\u7406\u4f5c\u4e3a\u4e00\u7ebf\u94f6\u884c\u5bb6\uff0c\u5bf9\u6301\u6709\u7eff\u8272\u4ef7\u503c\u89c2\u7684\u81ea\u8eab\u66f4\u503e\u5411\u4e8e\u7ed9\u4e88\u79ef\u6781\u7684\u63a8\u8350\u3002\u7136\u800c\uff0c\u5c11\u6570\u73af\u5883\u6301\u6000\u7591\u6001\u5ea6\u7684\u8d37\u6b3e\u5b98\u5458\uff0c\u901a\u8fc7\u5185\u90e8\u57f9\u8bad\u4e86\u89e3\u5230\u5ba2\u6237\u7ecf\u7406\u666e\u904d\u5177\u6709\u66f4\u73af\u4fdd\u7684\u504f\u597d\uff0c\u4f1a\u4e3b\u52a8\u4e0b\u8c03\u5bf9\u7eff\u8272\u4f01\u4e1a\u7684\u6b63\u9762\u8bc4\u4ef7\u3002\u5c3d\u7ba1\u4ed6\u4eec\u5e76\u4e0d\u77e5\u9053\u5ba2\u6237\u7ecf\u7406\u7684\u5177\u4f53\u8eab\u4efd\uff0c\u4f46\u8fd9\u4e9b\u5b98\u5458\u4ecd\u4f1a\u81ea\u4e3b\u9009\u62e9\u65f6\u70b9\uff0c\u4ee5\u62b5\u6d88\u4ed6\u4eec\u6240\u611f\u77e5\u5230\u7684\u7eff\u8272\u504f\u89c1\uff0c\u8fd9\u8868\u660e\u94f6\u884c\u5c42\u7ea7\u4e2d\u7684\u4e0a\u7ea7\u5728\u5e73\u8861\u504f\u89c1\u65b9\u9762\u53d1\u6325\u4e86\u91cd\u8981\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20200108", "journal": "AER", "title": "The Opportunity Atlas: Mapping the Childhood Roots of Social Mobility", "authors": ["Raj Chetty", "John N. Friedman", "Nathaniel Hendren", "Maggie R. Jones", "Sonya R. Porter"], "author_details": [{"name": "Raj Chetty", "affiliations": ["Harvard University and NBER (email: )"]}, {"name": "John N. Friedman", "affiliations": ["Brown University and NBER (email: )"]}, {"name": "Nathaniel Hendren", "affiliations": ["Massachusetts Institute of Technology and NBER (email: )"]}, {"name": "Maggie R. Jones", "affiliations": ["US Census Bureau (email: )"]}, {"name": "Sonya R. Porter", "affiliations": ["US Census Bureau (email: )"]}], "abstract": "We construct a public atlas of mean outcomes in adulthood by childhood census tract. Outcomes vary sharply across neighborhoods: For children whose parents earn $27,000, the standard deviation of mean household income in adulthood is $10,420 across tracts within counties. Only half the variation in outcomes is explained by traditional measures of neighborhood opportunity like poverty rates. Experimental and quasi-experimental estimates indicate 60 percent of the variation in outcomes across neighborhoods is driven by causal effects. We demonstrate how our statistics can be applied to better target policies to improve low-opportunity areas and help families move to affordable high-opportunity areas. (JEL G51, I32, I38, J12, R23)", "date": "2026-01-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20200108", "title_zh": "\u673a\u4f1a\u5730\u56fe\uff1a\u63cf\u7ed8\u513f\u7ae5\u671f\u793e\u4f1a\u6d41\u52a8\u7684\u6839\u6e90", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5173\u4e8e\u6210\u5e74\u671f\u5e73\u5747\u7ed3\u679c\u6309\u513f\u7ae5\u51fa\u751f\u666e\u67e5\u533a\u5212\u5206\u7684\u516c\u5f00\u5730\u56fe\u3002\u4e0d\u540c\u793e\u533a\u4e4b\u95f4\u7684\u7ed3\u679c\u5dee\u5f02\u663e\u8457\uff1a\u5bf9\u4e8e\u7236\u6bcd\u6536\u5165\u4e3a27000\u7f8e\u5143\u7684\u513f\u7ae5\uff0c\u6210\u5e74\u540e\u7684\u5bb6\u5ead\u6536\u5165\u5747\u503c\u5728\u53bf\u5185\u4e0d\u540c\u8857\u533a\u4e4b\u95f4\u7684\u6807\u51c6\u5dee\u4e3a10420\u7f8e\u5143\u3002\u4ec5\u6709\u4e00\u534a\u7684\u6210\u679c\u5dee\u5f02\u80fd\u591f\u88ab\u4f20\u7edf\u90bb\u91cc\u673a\u4f1a\u6307\u6807\uff08\u5982\u8d2b\u56f0\u7387\uff09\u89e3\u91ca\u3002\u5b9e\u9a8c\u548c\u51c6\u5b9e\u9a8c\u4f30\u8ba1\u8868\u660e\uff0c\u793e\u533a\u95f4\u6210\u679c\u5dee\u5f02\u768460%\u662f\u7531\u56e0\u679c\u6548\u5e94\u9a71\u52a8\u7684\u3002\u6211\u4eec\u5c55\u793a\u4e86\u5982\u4f55\u5229\u7528\u8fd9\u4e9b\u7edf\u8ba1\u6570\u636e\uff0c\u66f4\u7cbe\u51c6\u5730\u9488\u5bf9\u4f4e\u673a\u4f1a\u5730\u533a\u5b9e\u65bd\u653f\u7b56\uff0c\u5e2e\u52a9\u5bb6\u5ead\u8fc1\u79fb\u5230\u8d1f\u62c5\u5f97\u8d77\u7684\u9ad8\u673a\u4f1a\u5730\u533a\u3002\uff08JEL G51, I32, I38, J12, R23\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20231018", "journal": "AER", "title": "Monetary Cooperation during Global Inflation Surges", "authors": ["Luca Fornaro", "Federica Romei"], "author_details": [{"name": "Luca Fornaro", "affiliations": ["CREI, Universitat Pompeu Fabra, Barcelona School of Economics, and CEPR (email: )"]}, {"name": "Federica Romei", "affiliations": ["University of Oxford and CEPR (email: )"]}], "abstract": "We study optimal monetary policy during times of global scarcity of tradable goods. The optimal monetary response entails a surge in inflation, which helps rebalance production toward the tradable sector. While the inflation costs are fully borne domestically, however, the gains in terms of higher supply of tradable goods partly spill over to the rest of the world. National central banks may thus fall into a coordination trap and implement an excessively tight monetary policy causing an unnecessarily sharp global contraction. (JEL E24, E31, E32, E52, F11, F31, F42)", "date": "2026-01-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20231018", "title_zh": "\u5168\u7403\u901a\u80c0\u98d9\u5347\u65f6\u671f\u7684\u8d27\u5e01\u5408\u4f5c", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5728\u5168\u7403\u53ef\u4ea4\u6613\u5546\u54c1\u77ed\u7f3a\u65f6\u671f\u6700\u4f18\u7684\u8d27\u5e01\u653f\u7b56\u3002\u6700\u4f18\u7684\u8d27\u5e01\u653f\u7b56\u8868\u73b0\u4e3a\u901a\u80c0\u7387\u7684\u4e0a\u5347\uff0c\u8fd9\u6709\u52a9\u4e8e\u5c06\u751f\u4ea7\u91cd\u65b0\u8c03\u6574\u5230\u53ef\u4ea4\u6613\u90e8\u95e8\u3002\u5c3d\u7ba1\u901a\u80c0\u5e26\u6765\u7684\u6210\u672c\u5b8c\u5168\u7531\u56fd\u5185\u627f\u62c5\uff0c\u4f46\u53ef\u4ea4\u6613\u5546\u54c1\u4f9b\u5e94\u7684\u589e\u52a0\u90e8\u5206\u60e0\u53ca\u5168\u7403\u5176\u4ed6\u5730\u533a\u3002\u56e0\u6b64\uff0c\u5404\u56fd\u4e2d\u592e\u94f6\u884c\u53ef\u80fd\u9677\u5165\u534f\u8c03\u9677\u9631\uff0c\u91c7\u53d6\u8fc7\u4e8e\u7d27\u7f29\u7684\u8d27\u5e01\u653f\u7b56\uff0c\u5bfc\u81f4\u5168\u7403\u4e0d\u5fc5\u8981\u7684\u7ecf\u6d4e\u6536\u7f29\u3002\uff08JEL E24, E31, E32, E52, F11, F31, F42\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20211217", "journal": "AER", "title": "Risk Preferences and Field Behavior: The Relevance of Higher-Order Risk Preferences", "authors": ["Sebastian O. Schneider", "Matthias Sutter"], "author_details": [{"name": "Sebastian O. Schneider", "affiliations": ["Max Planck Institute for Behavioral Economics, University of Cologne and University of Innsbruck (email:"]}, {"name": "Matthias Sutter", "affiliations": ["Max Planck Institute for Behavioral Economics, University of Cologne and University of Innsbruck (email:"]}], "abstract": "Using new methods, we measure the intensities of higher-order risk preferences (prudence and temperance) in an incentivized experiment with 658 adolescents. Aligned with theory, we find that higher-order risk preferences are strongly related to field behavior, including prevention, health, addictive behavior, and financial decision-making. Most importantly, we show that ignoring prudence and temperance can yield misleading conclusions about the relation of risk preferences to field behavior, and that survey measures of risk tolerance often relate to field behavior because they capture higher-order risk preferences. (JEL C83, D81, D91, J13)", "date": "2026-01-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20211217", "title_zh": "\u98ce\u9669\u504f\u597d\u4e0e\u5b9e\u9645\u884c\u4e3a\uff1a\u66f4\u9ad8\u9636\u98ce\u9669\u504f\u597d\u7684\u76f8\u5173\u6027", "abstract_zh": "\u901a\u8fc7\u65b0\u7684\u65b9\u6cd5\uff0c\u6211\u4eec\u5728\u4e00\u9879\u5305\u542b658\u540d\u9752\u5c11\u5e74\u7684\u6fc0\u52b1\u5b9e\u9a8c\u4e2d\u6d4b\u91cf\u4e86\u8c28\u614e\u6027\u548c\u8282\u5236\u6027\u7b49\u66f4\u9ad8\u9636\u98ce\u9669\u504f\u597d\u7684\u5f3a\u5ea6\u3002\u4e0e\u7406\u8bba\u4e00\u81f4\uff0c\u6211\u4eec\u53d1\u73b0\u66f4\u9ad8\u9636\u98ce\u9669\u504f\u597d\u4e0e\u5b9e\u9645\u884c\u4e3a\u5bc6\u5207\u76f8\u5173\uff0c\u5305\u62ec\u9884\u9632\u884c\u4e3a\u3001\u5065\u5eb7\u884c\u4e3a\u3001\u6210\u763e\u884c\u4e3a\u4ee5\u53ca\u8d22\u52a1\u51b3\u7b56\u3002\u6700\u91cd\u8981\u7684\u662f\uff0c\u6211\u4eec\u8bc1\u660e\u4e86\u5ffd\u89c6\u8c28\u614e\u6027\u548c\u8282\u5236\u6027\u53ef\u80fd\u5bfc\u81f4\u5bf9\u98ce\u9669\u504f\u597d\u4e0e\u5b9e\u9645\u884c\u4e3a\u5173\u7cfb\u7684\u8bef\u89e3\uff0c\u800c\u8c03\u67e5\u4e2d\u6d4b\u5f97\u7684\u98ce\u9669\u5bb9\u5fcd\u5ea6\u5f80\u5f80\u4e0e\u5b9e\u9645\u884c\u4e3a\u76f8\u5173\uff0c\u662f\u56e0\u4e3a\u8fd9\u4e9b\u8c03\u67e5\u6307\u6807\u5b9e\u9645\u4e0a\u6355\u6349\u4e86\u66f4\u9ad8\u9636\u98ce\u9669\u504f\u597d\u3002\uff08JEL C83, D81, D91, J13\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240327", "journal": "AER", "title": "Racial Disparities in Housing Returns", "authors": ["Amir Kermani", "Francis Wong"], "author_details": [{"name": "Amir Kermani", "affiliations": ["UC Berkeley and NBER (email: )"]}, {"name": "Francis Wong", "affiliations": ["LMU Munich (email: )"]}], "abstract": "We show that higher rates of distressed home sales (i.e., foreclosures and short sales) among Black and Hispanic homeowners severely reduce realized housing returns for these groups\u2014in particular, to a level below that realized by White homeowners. Yet absent financial distress, houses owned by minorities do not appreciate at substantially slower rates than houses owned by nonminorities. Racial differences in liquidity and income stability, which are imperfectly observed by lenders, are important determinants of differences in distress. Policies that prevent foreclosure among distressed minorities can mitigate the racial gap in returns. (JEL D31, G51, J15, R31)", "date": "2026-01-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240327", "title_zh": "\u4f4f\u623f\u56de\u62a5\u4e2d\u7684\u79cd\u65cf\u5dee\u5f02", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u9ed1\u4eba\u548c\u897f\u73ed\u7259\u88d4\u5bb6\u5ead\u4e2d\u66f4\u9891\u7e41\u51fa\u73b0\u56f0\u5883\u623f\u4ea7\u9500\u552e\uff08\u5373\u6cd5\u62cd\u548c\u77ed\u552e\uff09\u4e25\u91cd\u964d\u4f4e\u4e86\u8fd9\u4e9b\u7fa4\u4f53\u7684\u5b9e\u9645\u4f4f\u623f\u56de\u62a5\u2014\u2014\u7279\u522b\u662f\u4f7f\u5176\u4f4e\u4e8e\u767d\u4eba\u5bb6\u5ead\u7684\u56de\u62a5\u6c34\u5e73\u3002\u7136\u800c\uff0c\u5728\u6ca1\u6709\u8d22\u52a1\u56f0\u5883\u7684\u60c5\u51b5\u4e0b\uff0c\u5c11\u6570\u65cf\u88d4\u62e5\u6709\u7684\u623f\u4ea7\u589e\u503c\u901f\u5ea6\u5e76\u4e0d\u663e\u8457\u4f4e\u4e8e\u975e\u5c11\u6570\u65cf\u88d4\u62e5\u6709\u7684\u623f\u4ea7\u3002\u79cd\u65cf\u5728\u6d41\u52a8\u6027\u53ca\u6536\u5165\u7a33\u5b9a\u6027\u65b9\u9762\u7684\u5dee\u5f02\uff08\u8fd9\u4e9b\u5dee\u5f02\u5bf9\u8d37\u6b3e\u4eba\u800c\u8a00\u96be\u4ee5\u51c6\u786e\u89c2\u6d4b\uff09\u662f\u5bfc\u81f4\u56f0\u5883\u5dee\u5f02\u7684\u91cd\u8981\u56e0\u7d20\u3002\u9488\u5bf9\u56f0\u5883\u4e2d\u7684\u5c11\u6570\u65cf\u88d4\u5b9e\u65bd\u9632\u6b62\u6cd5\u62cd\u7684\u653f\u7b56\uff0c\u53ef\u4ee5\u7f13\u89e3\u79cd\u65cf\u5728\u56de\u62a5\u4e0a\u7684\u5dee\u8ddd\u3002\uff08JEL D31, G51, J15, R31\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1257/aer.20240461", "journal": "AER", "title": "Tying with Network Effects", "authors": ["Jay Pil Choi", "Doh-Shin Jeon", "Michael D. Whinston"], "author_details": [{"name": "Jay Pil Choi", "affiliations": ["Michigan State University (email: )"]}, {"name": "Doh-Shin Jeon", "affiliations": ["Toulouse School of Economics, University of Toulouse Capitole (email: )"]}, {"name": "Michael D. Whinston", "affiliations": ["MIT (email: )"]}], "abstract": "We develop a leverage theory of tying in markets with network effects. When a monopolist in one market cannot perfectly extract surplus from consumers, tying can be a mechanism through which unexploited consumer surplus is used as a demand-side leverage to create a \u201cquasi-installed base\u201d advantage in another market characterized by network effects. Our mechanism does not require any precommitment to tying; rather, tying emerges as a best response that lowers the quality of tied-market rivals. While tying can lead to exclusion of tied-market rivals, it can also expand use of the tying product, leading to ambiguous welfare effects. (JEL D41, D85, K21, L15, L40)", "date": "2026-01-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240461", "title_zh": "\u6346\u7ed1\u4e0e\u7f51\u7edc\u6548\u5e94", "abstract_zh": "\u6211\u4eec\u53d1\u5c55\u4e86\u4e00\u79cd\u5173\u4e8e\u5b58\u5728\u7f51\u7edc\u6548\u5e94\u5e02\u573a\u7684\u6346\u7ed1\u7406\u8bba\u3002\u5f53\u5784\u65ad\u4f01\u4e1a\u5728\u67d0\u4e00\u5e02\u573a\u65e0\u6cd5\u5b8c\u5168\u4ece\u6d88\u8d39\u8005\u90a3\u91cc\u63d0\u53d6\u5269\u4f59\u6536\u76ca\u65f6\uff0c\u6346\u7ed1\u53ef\u4ee5\u4f5c\u4e3a\u4e00\u79cd\u673a\u5236\uff0c\u5229\u7528\u672a\u88ab\u5229\u7528\u7684\u6d88\u8d39\u8005\u5269\u4f59\u4f5c\u4e3a\u9700\u6c42\u4fa7\u6760\u6746\uff0c\u5728\u5177\u6709\u7f51\u7edc\u6548\u5e94\u7684\u53e6\u4e00\u5e02\u573a\u4e2d\u5f62\u6210\u4e00\u79cd\u2018\u51c6\u5b89\u88c5\u57fa\u7840\u2019\u4f18\u52bf\u3002\u6211\u4eec\u7684\u673a\u5236\u4e0d\u9700\u8981\u5bf9\u6346\u7ed1\u8fdb\u884c\u9884\u5148\u627f\u8bfa\uff1b\u76f8\u53cd\uff0c\u6346\u7ed1\u4f5c\u4e3a\u4e00\u79cd\u6700\u4f73\u53cd\u5e94\uff0c\u4f1a\u964d\u4f4e\u7ade\u4e89\u5bf9\u624b\u5728\u6346\u7ed1\u5e02\u573a\u4e2d\u7684\u4ea7\u54c1\u8d28\u91cf\u3002\u867d\u7136\u6346\u7ed1\u53ef\u80fd\u5bfc\u81f4\u5bf9\u6346\u7ed1\u5e02\u573a\u7ade\u4e89\u5bf9\u624b\u7684\u6392\u9664\uff0c\u4f46\u5b83\u4e5f\u53ef\u80fd\u6269\u5927\u6346\u7ed1\u4ea7\u54c1\u7684\u4f7f\u7528\uff0c\u4ece\u800c\u5bfc\u81f4\u798f\u5229\u6548\u5e94\u7684\u4e0d\u786e\u5b9a\u6027\u3002\uff08JEL D41, D85, K21, L15, L40\uff09", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1257/aer.20240167", "journal": "AER", "title": "Gender-Biased Technological Change: Milking Machines and the Exodus of Women from Farming", "authors": ["Philipp Ager", "Marc Go\u00f1i", "Kjell G. Salvanes"], "author_details": [{"name": "Philipp Ager", "affiliations": ["University of Mannheim and CEPR (email: )"]}, {"name": "Marc Go\u00f1i", "affiliations": ["University of Bergen and CEPR (email: )"]}, {"name": "Kjell G. Salvanes", "affiliations": ["Norwegian School of Economics (email: )"]}], "abstract": "This paper studies how gender-biased technological change in agriculture affected women\u2019s work in twentieth-century Norway. In the 1950s, dairy farms began widely adopting milking machines to replace milking cows by hand, a task typically performed by young women. We show that the machines pushed rural young women in dairy-intensive areas out of farming. The displaced women moved to cities where they acquired more education and found better-paying, skilled employment. Our results suggest that the adoption of milking machines broke up allocative inefficiencies associated with moving costs across sectors, which improved the economic status of women relative to men. (JEL J16, J24, J43, J61, N34, N54, O33)", "date": "2026-01-01", "date_kind": "\u7eb8\u520a\u65e5\u671f", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1257/aer.20240167", "title_zh": "\u6280\u672f\u53d8\u9769\u4e2d\u7684\u6027\u522b\u504f\u89c1\uff1a\u6324\u5976\u673a\u4e0e\u5973\u6027\u4ece\u519c\u4e1a\u4e2d\u7684\u9000\u51fa", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e8620\u4e16\u7eaa\u632a\u5a01\u519c\u4e1a\u4e2d\u6027\u522b\u504f\u89c1\u7684\u6280\u672f\u53d8\u9769\u5982\u4f55\u5f71\u54cd\u5973\u6027\u7684\u52b3\u52a8\u72b6\u51b5\u300220\u4e16\u7eaa50\u5e74\u4ee3\uff0c\u5976\u725b\u573a\u5f00\u59cb\u5e7f\u6cdb\u91c7\u7528\u6324\u5976\u673a\u66ff\u4ee3\u624b\u5de5\u6324\u5976\uff0c\u800c\u8fd9\u4e00\u5de5\u4f5c\u901a\u5e38\u7531\u5e74\u8f7b\u5973\u6027\u627f\u62c5\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u6324\u5976\u673a\u7684\u666e\u53ca\u5bfc\u81f4\u4e86\u519c\u6751\u5730\u533a\u5976\u725b\u517b\u6b96\u533a\u7684\u5e74\u8f7b\u5973\u6027\u9000\u51fa\u519c\u4e1a\u3002\u88ab\u66ff\u4ee3\u7684\u5973\u6027\u8fc1\u5f80\u57ce\u5e02\uff0c\u83b7\u5f97\u4e86\u66f4\u591a\u7684\u6559\u80b2\uff0c\u5e76\u627e\u5230\u4e86\u85aa\u8d44\u66f4\u9ad8\u3001\u6280\u672f\u8981\u6c42\u66f4\u9ad8\u7684\u5de5\u4f5c\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u6324\u5976\u673a\u7684\u91c7\u7528\u6253\u7834\u4e86\u8de8\u884c\u4e1a\u6d41\u52a8\u6210\u672c\u5bfc\u81f4\u7684\u8d44\u6e90\u914d\u7f6e\u4f4e\u6548\uff0c\u4ece\u800c\u63d0\u5347\u4e86\u5973\u6027\u76f8\u5bf9\u4e8e\u7537\u6027\u7684\u7ecf\u6d4e\u5730\u4f4d\u3002\uff08JEL J16, J24, J43, J61, N34, N54, O33\uff09", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22974", "journal": "ECTA", "title": "The Complexity of Multidimensional Learning in Agriculture", "authors": ["Rachid Laajaj", "Karen Macours"], "author_details": [{"name": "Rachid Laajaj", "affiliations": ["Department of Economics, Universidad de Los Andes"]}, {"name": "Karen Macours", "affiliations": ["Paris School of Economics", "INRAE"]}], "abstract": "Studies on agricultural technology adoption often focus on one input, practice, or package, which is analytically useful, but may overlook the complexities involved with multidimensional learning needed for a lot of agricultural decisions. In Kenya, we study farmers' dynamic learning (from oneself and others) and adoption decisions over six seasons after randomly inviting them to participate in agronomic research trials, comparing different combinations of inputs during three consecutive seasons. As a response to the trials, adoption increases steadily despite the absence of positive profits multiple seasons after exposure to the trials. Know\u2010how increases rapidly and faster for high skill farmers who experiment the most, at the cost of making new mistakes. The findings are consistent with a theoretical model with multidimensionality of input and practice decisions and differential learning from one's own experience by skills, where complementarities imply that adoption of an input requires finding how to re\u2010optimize other dimensions, which adds to the cost of adoption.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22974", "title_zh": "\u519c\u4e1a\u4e2d\u591a\u7ef4\u5b66\u4e60\u7684\u590d\u6742\u6027", "abstract_zh": "\u519c\u4e1a\u6280\u672f\u91c7\u7528\u7814\u7a76\u5f80\u5f80\u805a\u7126\u4e8e\u5355\u4e00\u6295\u5165\u3001\u505a\u6cd5\u6216\u6280\u672f\u7ec4\u5408\uff0c\u8fd9\u6709\u5229\u4e8e\u5206\u6790\uff0c\u5374\u53ef\u80fd\u5ffd\u7565\u8bb8\u591a\u519c\u4e1a\u51b3\u7b56\u6240\u9700\u591a\u7ef4\u5b66\u4e60\u7684\u590d\u6742\u6027\u3002\u5728\u80af\u5c3c\u4e9a\uff0c\u6211\u4eec\u968f\u673a\u9080\u8bf7\u519c\u6c11\u53c2\u52a0\u519c\u827a\u7814\u7a76\u8bd5\u9a8c\uff0c\u5728\u8fde\u7eed\u4e09\u4e2a\u79cd\u690d\u5b63\u6bd4\u8f83\u4e0d\u540c\u6295\u5165\u7ec4\u5408\uff0c\u5e76\u5728\u516d\u4e2a\u79cd\u690d\u5b63\u4e2d\u7814\u7a76\u4ed6\u4eec\u4ece\u81ea\u8eab\u548c\u4ed6\u4eba\u7ecf\u9a8c\u4e2d\u52a8\u6001\u5b66\u4e60\u4ee5\u53ca\u91c7\u7528\u6280\u672f\u7684\u51b3\u7b56\u3002\u8bd5\u9a8c\u5f00\u5c55\u540e\uff0c\u5373\u4f7f\u63a5\u89e6\u8bd5\u9a8c\u540e\u7684\u591a\u4e2a\u79cd\u690d\u5b63\u90fd\u6ca1\u6709\u5b9e\u73b0\u6b63\u5229\u6da6\uff0c\u91c7\u7528\u7387\u4ecd\u7a33\u6b65\u63d0\u9ad8\u3002\u5b9e\u64cd\u77e5\u8bc6\u8fc5\u901f\u589e\u957f\uff0c\u589e\u957f\u6700\u5feb\u7684\u662f\u5c1d\u8bd5\u6700\u591a\u7684\u9ad8\u6280\u80fd\u519c\u6c11\uff0c\u4f46\u5176\u4ee3\u4ef7\u662f\u72af\u4e0b\u65b0\u7684\u9519\u8bef\u3002\u7814\u7a76\u53d1\u73b0\u4e0e\u4e00\u4e2a\u7406\u8bba\u6a21\u578b\u76f8\u4e00\u81f4\uff1a\u6295\u5165\u548c\u5b9e\u8df5\u51b3\u7b56\u5177\u6709\u591a\u7ef4\u6027\uff0c\u4e0d\u540c\u6280\u80fd\u6c34\u5e73\u7684\u4eba\u4ece\u81ea\u8eab\u7ecf\u9a8c\u4e2d\u5b66\u4e60\u7684\u65b9\u5f0f\u4e0d\u540c\uff1b\u7531\u4e8e\u5404\u7ef4\u5ea6\u4e4b\u95f4\u5b58\u5728\u4e92\u8865\u6027\uff0c\u91c7\u7528\u67d0\u9879\u6295\u5165\u9700\u8981\u627e\u5230\u91cd\u65b0\u4f18\u5316\u5176\u4ed6\u7ef4\u5ea6\u7684\u65b9\u6cd5\uff0c\u4ece\u800c\u589e\u52a0\u91c7\u7528\u6210\u672c\u3002", "translation_source": "\u9996\u7248\u6837\u4f8b\uff1a\u7531 Codex \u6839\u636e\u516c\u5f00\u6458\u8981\u7ffb\u8bd1\uff0c\u975e Qwen \u8f93\u51fa", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta20428", "journal": "ECTA", "title": "The Role of Trade in Premature Deindustrialization and Industry Polarization", "authors": ["Michael Sposi", "Kei-Mu Yi", "Jing Zhang"], "author_details": [{"name": "Michael Sposi", "affiliations": ["Department of Economics, Southern Methodist University"]}, {"name": "Kei-Mu Yi", "affiliations": ["University of Houston, Federal Reserve Bank of Dallas, and NBER"]}, {"name": "Jing Zhang", "affiliations": ["Research Department, Federal Reserve Bank of Chicago"]}], "abstract": "We document two key patterns of structural change: premature deindustrialization and rising industry polarization. Using a dynamic open\u2010economy model with sector\u2010biased technological change (SBTC), we evaluate the role of trade in these shifts. Trade alone does not cause premature deindustrialization, but its interaction with SBTC\u2014transmitting global technological change, amplifying the decline in manufacturing's relative price over time, and generating manufacturing trade imbalances across countries\u2014deepens premature deindustrialization over time. Industry polarization, by contrast, emerges only through trade\u2010driven specialization, as countries diverge along lines of comparative advantage.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta20428", "title_zh": "\u8d38\u6613\u5728\u65e9\u671f\u53bb\u5de5\u4e1a\u5316\u548c\u4ea7\u4e1a\u6781\u5316\u4e2d\u7684\u4f5c\u7528", "abstract_zh": "\u6211\u4eec\u8bb0\u5f55\u4e86\u7ed3\u6784\u6027\u53d8\u5316\u7684\u4e24\u4e2a\u5173\u952e\u7279\u5f81\uff1a\u65e9\u671f\u53bb\u5de5\u4e1a\u5316\u548c\u4ea7\u4e1a\u6781\u5316\u7684\u4e0a\u5347\u3002\u5229\u7528\u4e00\u4e2a\u5177\u6709\u90e8\u95e8\u504f\u5411\u6027\u6280\u672f\u53d8\u9769\uff08SBTC\uff09\u7684\u52a8\u6001\u5f00\u653e\u7ecf\u6d4e\u6a21\u578b\uff0c\u6211\u4eec\u8bc4\u4f30\u4e86\u8d38\u6613\u5728\u8fd9\u4e9b\u53d8\u5316\u4e2d\u7684\u4f5c\u7528\u3002\u8d38\u6613\u672c\u8eab\u5e76\u4e0d\u4f1a\u5bfc\u81f4\u65e9\u671f\u53bb\u5de5\u4e1a\u5316\uff0c\u4f46\u5176\u4e0eSBTC\u7684\u76f8\u4e92\u4f5c\u7528\u2014\u2014\u4f20\u9012\u5168\u7403\u6280\u672f\u53d8\u9769\u3001\u653e\u5927\u5236\u9020\u4e1a\u76f8\u5bf9\u4ef7\u683c\u7684\u4e0b\u964d\u8d8b\u52bf\uff0c\u5e76\u5728\u5404\u56fd\u4e4b\u95f4\u4ea7\u751f\u5236\u9020\u4e1a\u8d38\u6613\u5931\u8861\u2014\u2014\u4f1a\u968f\u7740\u65f6\u95f4\u63a8\u79fb\u52a0\u6df1\u65e9\u671f\u53bb\u5de5\u4e1a\u5316\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u4ea7\u4e1a\u6781\u5316\u4ec5\u901a\u8fc7\u8d38\u6613\u9a71\u52a8\u7684\u4e13\u4e1a\u5316\u4ea7\u751f\uff0c\u5373\u5404\u56fd\u6cbf\u7740\u6bd4\u8f83\u4f18\u52bf\u7684\u5dee\u5f02\u800c\u5206\u5316\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22022", "journal": "ECTA", "title": "Outside Options, Reputations, and the Partial Success of the Coase Conjecture", "authors": ["Jack Fanning"], "author_details": [{"name": "Jack Fanning", "affiliations": ["Department of Economics, Brown University"]}], "abstract": "A buyer and seller bargain in continuous time over a good. Bargainers can be rational or committed to some fixed price. A rational buyer has a private value and outside option. If the set of buyer values and commitment types is rich and the probability of commitment vanishes, outcomes are partially consistent with the Coase conjecture: the seller chooses a price below the maximum of the lowest outside option and half the lowest value; the buyer immediately accepts or takes his outside option.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22022", "title_zh": "\u5916\u90e8\u9009\u62e9\u3001\u58f0\u8a89\u4e0e\u79d1\u65af\u731c\u60f3\u7684\u90e8\u5206\u6210\u529f", "abstract_zh": "\u4e70\u65b9\u548c\u5356\u65b9\u5728\u8fde\u7eed\u65f6\u95f4\u4e2d\u5c31\u67d0\u5546\u54c1\u8fdb\u884c\u8c08\u5224\u3002\u8c08\u5224\u8005\u53ef\u4ee5\u662f\u7406\u6027\u4eba\uff0c\u4e5f\u53ef\u4ee5\u662f\u575a\u6301\u56fa\u5b9a\u4ef7\u683c\u7684\u627f\u8bfa\u8005\u3002\u4e00\u4e2a\u7406\u6027\u7684\u4e70\u65b9\u62e5\u6709\u79c1\u4eba\u4ef7\u503c\u548c\u5916\u90e8\u9009\u62e9\u9009\u9879\u3002\u5982\u679c\u4e70\u65b9\u4ef7\u503c\u5206\u5e03\u548c\u627f\u8bfa\u7c7b\u578b\u96c6\u5408\u8db3\u591f\u4e30\u5bcc\uff0c\u4e14\u627f\u8bfa\u53d1\u751f\u7684\u6982\u7387\u8d8b\u4e8e\u96f6\uff0c\u90a3\u4e48\u7ed3\u679c\u90e8\u5206\u7b26\u5408\u79d1\u65af\u731c\u60f3\uff1a\u5356\u65b9\u9009\u62e9\u7684\u4ef7\u683c\u4f4e\u4e8e\u6700\u4f4e\u5916\u90e8\u9009\u62e9\u9009\u9879\u548c\u6700\u4f4e\u4ef7\u503c\u7684\u4e00\u534a\u4e4b\u95f4\u7684\u6700\u5927\u503c\uff1b\u4e70\u65b9\u7acb\u5373\u63a5\u53d7\u8be5\u4ef7\u683c\u6216\u9009\u62e9\u5176\u5916\u90e8\u9009\u9879\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23897", "journal": "ECTA", "title": "Causal Inference With Noisy Covariates: Heteroscedastic Measurement Error and Differential Privacy", "authors": ["Anish Agarwal", "Rahul Singh"], "author_details": [{"name": "Anish Agarwal", "affiliations": ["Department of Industrial Engineering and Operations Research, Columbia University"]}, {"name": "Rahul Singh", "affiliations": ["Society of Fellows and Department of Economics, Harvard University"]}], "abstract": "We study causal inference with high\u2010dimensional covariates, observed with various types of heteroscedastic noise. Our main assumption is that the true covariates are low rank, which we empirically evaluate with plots and interpret as approximate repeated measurements. This assumption delivers semiparametric inference on the causal parameter, as precisely as if the true covariates were available. A methodological contribution is to introduce an error\u2010in\u2010variable balancing weight for estimation and inference on cross\u2010sectional causal parameters with heterogeneous effects.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23897", "title_zh": "\u5b58\u5728\u566a\u58f0\u534f\u53d8\u91cf\u7684\u56e0\u679c\u63a8\u65ad\uff1a\u5f02\u8d28\u6027\u6d4b\u91cf\u8bef\u5dee\u4e0e\u5dee\u5206\u9690\u79c1", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5728\u9ad8\u7ef4\u534f\u53d8\u91cf\u4e2d\u5b58\u5728\u5404\u79cd\u7c7b\u578b\u5f02\u8d28\u6027\u566a\u58f0\u60c5\u51b5\u4e0b\u7684\u56e0\u679c\u63a8\u65ad\u3002\u6211\u4eec\u7684\u4e3b\u8981\u5047\u8bbe\u662f\u771f\u5b9e\u534f\u53d8\u91cf\u5177\u6709\u4f4e\u79e9\u6027\uff0c\u6211\u4eec\u901a\u8fc7\u56fe\u8868\u8fdb\u884c\u7ecf\u9a8c\u8bc4\u4f30\uff0c\u5e76\u5c06\u5176\u89e3\u91ca\u4e3a\u8fd1\u4f3c\u7684\u91cd\u590d\u6d4b\u91cf\u3002\u8fd9\u4e00\u5047\u8bbe\u80fd\u591f\u5b9e\u73b0\u5bf9\u56e0\u679c\u53c2\u6570\u7684\u534a\u53c2\u6570\u63a8\u65ad\uff0c\u5176\u7cbe\u5ea6\u76f8\u5f53\u4e8e\u5728\u771f\u5b9e\u534f\u53d8\u91cf\u5b8c\u5168\u53ef\u5f97\u7684\u60c5\u51b5\u4e0b\u3002\u65b9\u6cd5\u4e0a\u7684\u8d21\u732e\u662f\u5f15\u5165\u4e86\u4e00\u79cd\u8bef\u5dee-\u53d8\u91cf\u5e73\u8861\u6743\u91cd\uff0c\u7528\u4e8e\u4f30\u8ba1\u548c\u63a8\u65ad\u5177\u6709\u5f02\u8d28\u6548\u5e94\u7684\u6a2a\u622a\u9762\u56e0\u679c\u53c2\u6570\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22733", "journal": "ECTA", "title": "The Hitchhiker's Guide to Markup Estimation: Assessing Estimates From Financial Data", "authors": ["Maarten De Ridder", "Basile Grassi", "Giovanni Morzenti"], "author_details": [{"name": "Maarten De Ridder", "affiliations": ["Department of Economics, London School of Economics", "CFM", "POID", "CEPR"]}, {"name": "Basile Grassi", "affiliations": ["Department of Economics, Bocconi University", "IGIER", "OFCE", "CEPR"]}, {"name": "Giovanni Morzenti", "affiliations": ["Analysis Group"]}], "abstract": "Macroeconomic outcomes depend on the distribution of markups across firms and over time, making firm\u2010level markup estimates key for macroeconomic analysis. Methods to obtain these estimates require data on the prices that firms charge. Firm\u2010level data with wide coverage, however, primarily come from financial statements, which lack information on prices. We use an analytical framework to show that trends in markups over time or the dispersion of markups across firms can still be well\u2010measured with such data. Measuring the average level of the markup does require pricing data, and we propose a consistent estimator for such settings. We validate the analytical results using simulations of a quantitative macroeconomic model and offer supporting evidence from firm\u2010level administrative production and pricing data. Our analysis supports the use of financial data to measure trends in aggregate markups.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22733", "title_zh": "\u4ef7\u683c markup \u4f30\u7b97\u6307\u5357\uff1a\u57fa\u4e8e\u91d1\u878d\u6570\u636e\u7684\u4f30\u7b97\u8bc4\u4f30", "abstract_zh": "\u5b8f\u89c2\u7ecf\u6d4e\u7ed3\u679c\u53d6\u51b3\u4e8e\u4f01\u4e1a\u95f4\u53ca\u968f\u65f6\u95f4\u53d8\u5316\u7684 markup \u5206\u5e03\uff0c\u56e0\u6b64\u4f01\u4e1a\u5c42\u9762\u7684 markup \u4f30\u7b97\u5bf9\u4e8e\u5b8f\u89c2\u7ecf\u6d4e\u5206\u6790\u81f3\u5173\u91cd\u8981\u3002\u76ee\u524d\u83b7\u53d6\u8fd9\u4e9b\u4f30\u7b97\u7684\u65b9\u6cd5\u9700\u8981\u4f01\u4e1a\u5b9a\u4ef7\u6570\u636e\u3002\u7136\u800c\uff0c\u5e7f\u6cdb\u8986\u76d6\u7684\u4f01\u4e1a\u5c42\u9762\u6570\u636e\u4e3b\u8981\u6765\u81ea\u8d22\u52a1\u62a5\u8868\uff0c\u8fd9\u4e9b\u6570\u636e\u7f3a\u4e4f\u4ef7\u683c\u4fe1\u606f\u3002\u6211\u4eec\u91c7\u7528\u4e00\u4e2a\u5206\u6790\u6846\u67b6\uff0c\u8868\u660e\u5373\u4f7f\u5728\u6ca1\u6709\u4ef7\u683c\u6570\u636e\u7684\u60c5\u51b5\u4e0b\uff0c\u4e5f\u53ef\u4ee5\u5f88\u597d\u5730\u8861\u91cf markup \u968f\u65f6\u95f4\u7684\u53d8\u5316\u8d8b\u52bf\u6216\u4f01\u4e1a\u95f4 markup \u7684\u5206\u6563\u7a0b\u5ea6\u3002\u8981\u8861\u91cf markup \u7684\u5e73\u5747\u6c34\u5e73\u5219\u4ecd\u9700\u4ef7\u683c\u6570\u636e\uff0c\u6211\u4eec\u4e3a\u6b64\u63d0\u51fa\u4e86\u4e00\u79cd\u4e00\u81f4\u7684\u4f30\u8ba1\u65b9\u6cd5\u3002\u6211\u4eec\u901a\u8fc7\u91cf\u5316\u5b8f\u89c2\u7ecf\u6d4e\u6a21\u578b\u7684\u6a21\u62df\u4ee5\u53ca\u6765\u81ea\u4f01\u4e1a\u5c42\u9762\u884c\u653f\u751f\u4ea7\u4e0e\u5b9a\u4ef7\u6570\u636e\u7684\u652f\u6301\u6027\u8bc1\u636e\uff0c\u9a8c\u8bc1\u4e86\u5206\u6790\u7ed3\u679c\u3002\u6211\u4eec\u7684\u5206\u6790\u652f\u6301\u4f7f\u7528\u91d1\u878d\u6570\u636e\u6765\u8861\u91cf\u6574\u4f53 markup \u7684\u8d8b\u52bf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta21849", "journal": "ECTA", "title": "Work Hours Mismatch", "authors": ["Marta Lachowska", "Alexandre Mas", "Raffaele Saggio", "Stephen A. Woodbury"], "author_details": [{"name": "Marta Lachowska", "affiliations": ["Economic Research, Federal Reserve Bank of Chicago"]}, {"name": "Alexandre Mas", "affiliations": ["Haas School of Business, University of California, Berkeley", "NBER"]}, {"name": "Raffaele Saggio", "affiliations": ["Department of Economics, University of British Columbia", "NBER"]}, {"name": "Stephen A. Woodbury", "affiliations": ["Department of Economics, Michigan State University", "W.E. Upjohn Institute for Employment Research"]}], "abstract": "We apply a revealed preference approach to administrative data from Washington to show that constraints on work hours are widespread: Workers have limited discretion over hours at a given employer, and there is substantial mismatch of workers who prefer long hours to employers that provide short hours. Voluntary job transitions imply a ratio of the marginal rate of substitution of earnings for hours to the wage rate of 0.5\u20130.6 for prime\u2010age workers. The average absolute deviation between observed and optimal hours is about 15%, and low\u2010wage workers face particularly acute constraints on hours. On average, observed hours tend to be less than preferred levels, and workers would require a 12% higher wage with their current employer to be as well off as with an employer offering ideal hours. These findings suggest that hour constraints are an equilibrium feature of the labor market because long\u2010hour jobs are costly to employers.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21849", "title_zh": "\u5de5\u4f5c\u65f6\u95f4\u9519\u914d", "abstract_zh": "\u6211\u4eec\u91c7\u7528\u63ed\u793a\u6027\u504f\u597d\u65b9\u6cd5\uff0c\u57fa\u4e8e\u534e\u76db\u987f\u7684\u884c\u653f\u6570\u636e\uff0c\u8868\u660e\u5de5\u4f5c\u65f6\u95f4\u7684\u7ea6\u675f\u666e\u904d\u5b58\u5728\uff1a\u5de5\u4eba\u5728\u7279\u5b9a\u96c7\u4e3b\u5904\u5bf9\u5de5\u4f5c\u65f6\u95f4\u7684\u81ea\u4e3b\u9009\u62e9\u53d7\u5230\u9650\u5236\uff0c\u4e14\u5927\u91cf\u504f\u597d\u957f\u65f6\u95f4\u5de5\u4f5c\u7684\u4eba\u4e0e\u63d0\u4f9b\u77ed\u65f6\u95f4\u5de5\u4f5c\u96c7\u4e3b\u4e4b\u95f4\u5b58\u5728\u663e\u8457\u9519\u914d\u3002\u81ea\u613f\u7684\u5c31\u4e1a\u8f6c\u6362\u610f\u5473\u7740\u5728\u4e3b\u8981\u52b3\u52a8\u5e74\u9f84\u7fa4\u4f53\u4e2d\uff0c\u6536\u5165\u5bf9\u5de5\u4f5c\u65f6\u95f4\u7684\u8fb9\u9645\u66ff\u4ee3\u7387\u4e0e\u5de5\u8d44\u7387\u4e4b\u6bd4\u4e3a0.5\u81f30.6\u3002\u89c2\u5bdf\u5230\u7684\u5de5\u4f5c\u65f6\u95f4\u4e0e\u6700\u4f18\u5de5\u4f5c\u65f6\u95f4\u4e4b\u95f4\u7684\u5e73\u5747\u7edd\u5bf9\u504f\u5dee\u7ea6\u4e3a15%\uff0c\u4f4e\u6536\u5165\u5de5\u4eba\u9762\u4e34\u5c24\u4e3a\u4e25\u91cd\u7684\u5de5\u4f5c\u65f6\u95f4\u9650\u5236\u3002\u603b\u4f53\u800c\u8a00\uff0c\u89c2\u5bdf\u5230\u7684\u5de5\u4f5c\u65f6\u95f4\u901a\u5e38\u4f4e\u4e8e\u4e2a\u4eba\u504f\u597d\u6c34\u5e73\uff0c\u5de5\u4eba\u9700\u8981\u5728\u5f53\u524d\u96c7\u4e3b\u5904\u83b7\u5f9712%\u66f4\u9ad8\u7684\u5de5\u8d44\uff0c\u624d\u80fd\u4e0e\u63d0\u4f9b\u7406\u60f3\u5de5\u4f5c\u65f6\u95f4\u7684\u96c7\u4e3b\u76f8\u6bd4\u5904\u4e8e\u540c\u7b49\u798f\u5229\u6c34\u5e73\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u5de5\u4f5c\u65f6\u95f4\u7684\u7ea6\u675f\u662f\u52b3\u52a8\u529b\u5e02\u573a\u5747\u8861\u7684\u7279\u5f81\uff0c\u56e0\u4e3a\u957f\u65f6\u95f4\u5de5\u4f5c\u5bf9\u96c7\u4e3b\u800c\u8a00\u6210\u672c\u8f83\u9ad8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta21366", "journal": "ECTA", "title": "Security Design Under Common\u2010Value Competition", "authors": ["Yue Yuan"], "author_details": [{"name": "Yue Yuan", "affiliations": ["School of Management and Department of Economics, University College London"]}], "abstract": "This paper studies security design by bidders with dispersed information about a common\u2010value investment opportunity. Among a broad set of securities, bidders offer debt financing\u2014the flattest securities. A first reason is that debt mitigates bidders' exposure to the winner's curse when there are two bidders. Second, the entrepreneur either has an informational advantage initially or gains one by inferring from the bids, and is more likely to select debt offers when optimistic about the project. While a bidder's choice of security also has a signaling effect, this effect is dominated by the winner's curse and informed\u2010selection effects, and does not affect the equilibrium outcome. These results contrast sharply with security design by a monopolistic investor, as well as with DeMarzo, Kremer, and Skrzypacz's (2005) results under private\u2010value competition. The entrepreneur's ability to commit to an ordered set of securities does not improve revenue.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21366", "title_zh": "\u5171\u540c\u4ef7\u503c\u7ade\u4e89\u4e0b\u7684\u8bc1\u5238\u8bbe\u8ba1", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u5728\u5bf9\u4e00\u4e2a\u5171\u540c\u4ef7\u503c\u6295\u8d44\u673a\u4f1a\u62e5\u6709\u5206\u6563\u4fe1\u606f\u7684\u6295\u6807\u8005\u4e4b\u95f4\uff0c\u8bc1\u5238\u7684\u8bbe\u8ba1\u95ee\u9898\u3002\u5728\u4e00\u7cfb\u5217\u5e7f\u6cdb\u8bc1\u5238\u4e2d\uff0c\u6295\u6807\u8005\u63d0\u4f9b\u503a\u52a1\u878d\u8d44\u2014\u2014\u8fd9\u662f\u6700\u5e73\u5766\u7684\u8bc1\u5238\u3002\u7b2c\u4e00\u4e2a\u539f\u56e0\u662f\uff0c\u5f53\u6709\u4e24\u4f4d\u6295\u6807\u8005\u65f6\uff0c\u503a\u52a1\u53ef\u4ee5\u51cf\u8f7b\u6295\u6807\u8005\u906d\u53d7\u8d62\u5bb6\u8bc5\u5492\u7684\u98ce\u9669\u3002\u5176\u6b21\uff0c\u4f01\u4e1a\u5bb6\u6700\u521d\u53ef\u80fd\u62e5\u6709\u4fe1\u606f\u4f18\u52bf\uff0c\u6216\u8005\u901a\u8fc7\u4ece\u6295\u6807\u4e2d\u63a8\u65ad\u51fa\u4fe1\u606f\u4f18\u52bf\uff0c\u5e76\u4e14\u5728\u5bf9\u9879\u76ee\u6301\u4e50\u89c2\u6001\u5ea6\u65f6\u66f4\u53ef\u80fd\u9009\u62e9\u503a\u52a1\u878d\u8d44\u3002\u867d\u7136\u6295\u6807\u8005\u9009\u62e9\u8bc1\u5238\u4e5f\u5177\u6709\u4fe1\u53f7\u6548\u5e94\uff0c\u4f46\u8fd9\u79cd\u6548\u5e94\u88ab\u8d62\u5bb6\u8bc5\u5492\u548c\u4fe1\u606f\u4f18\u52bf\u9009\u62e9\u6548\u5e94\u6240\u4e3b\u5bfc\uff0c\u4e0d\u4f1a\u5f71\u54cd\u5747\u8861\u7ed3\u679c\u3002\u8fd9\u4e9b\u7ed3\u679c\u4e0e\u5784\u65ad\u6295\u8d44\u8005\u7684\u8bc1\u5238\u8bbe\u8ba1\u7ed3\u679c\uff0c\u4ee5\u53caDeMarzo\u3001Kremer\u548cSkrzypacz\uff082005\uff09\u5728\u79c1\u6709\u4ef7\u503c\u7ade\u4e89\u4e0b\u7684\u7ed3\u679c\u5f62\u6210\u9c9c\u660e\u5bf9\u6bd4\u3002\u4f01\u4e1a\u5bb6\u80fd\u591f\u627f\u8bfa\u9009\u62e9\u4e00\u7ec4\u6709\u5e8f\u8bc1\u5238\u7684\u80fd\u529b\u5e76\u4e0d\u80fd\u63d0\u9ad8\u6536\u5165\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta21180", "journal": "ECTA", "title": "Choosing Who Chooses: Selection\u2010Driven Targeting in Energy Rebate Programs", "authors": ["Takanori Ida", "Takunori Ishihara", "Koichiro Ito", "Daido Kido", "Toru Kitagawa", "Shosei Sakaguchi", "Shusaku Sasaki"], "author_details": [{"name": "Takanori Ida", "affiliations": ["Graduate School of Economics, Kyoto University"]}, {"name": "Takunori Ishihara", "affiliations": ["Faculty of Economics and Business Administration, Kyoto University of Advanced Science"]}, {"name": "Koichiro Ito", "affiliations": ["Harris School of Public Policy, University of Chicago"]}, {"name": "Daido Kido", "affiliations": ["Department of Economics, Otaru University of Commerce"]}, {"name": "Toru Kitagawa", "affiliations": ["Department of Economics, Brown University"]}, {"name": "Shosei Sakaguchi", "affiliations": ["Faculty of Economics, University of Tokyo"]}, {"name": "Shusaku Sasaki", "affiliations": ["Center for Infectious Disease Education and Research, University of Osaka"]}], "abstract": "We develop an optimal policy assignment rule that integrates two distinctive approaches commonly used in economics\u2014targeting by observables and targeting through self\u2010selection . Our method can be used with experimental or quasi\u2010experimental data to identify who should be treated, be untreated, and self\u2010select to achieve a policymaker's objective. Applying this method to a randomized controlled trial on a residential energy rebate program, we find that targeting that optimally exploits both observable data and self\u2010selection outperforms conventional targeting. We use the Local Average Treatment Effect (LATE) framework (Imbens and Angrist (1994)) to investigate the mechanism in our approach. By estimating several key LATEs based on the random variation created by our experiment, we demonstrate how our method allows policymakers to identify whose self\u2010selection would be valuable and harmful to social welfare.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21180", "title_zh": "\u9009\u62e9\u8c01\u6765\u9009\u62e9\uff1a\u80fd\u6e90\u8865\u8d34\u8ba1\u5212\u4e2d\u7684\u9009\u62e9\u9a71\u52a8\u578b\u5b9a\u5411", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u79cd\u6700\u4f18\u653f\u7b56\u5206\u914d\u89c4\u5219\uff0c\u5c06\u7ecf\u6d4e\u5b66\u4e2d\u4e24\u79cd\u5e38\u7528\u65b9\u6cd5\u2014\u2014\u57fa\u4e8e\u53ef\u89c2\u6d4b\u7279\u5f81\u7684\u5b9a\u5411\u548c\u901a\u8fc7\u81ea\u6211\u9009\u62e9\u7684\u5b9a\u5411\u2014\u2014\u7ed3\u5408\u8d77\u6765\u3002\u8be5\u65b9\u6cd5\u53ef\u5e94\u7528\u4e8e\u5b9e\u9a8c\u6216\u51c6\u5b9e\u9a8c\u6570\u636e\uff0c\u4ee5\u8bc6\u522b\u5e94\u63a5\u53d7\u5e72\u9884\u3001\u672a\u63a5\u53d7\u5e72\u9884\u4ee5\u53ca\u81ea\u6211\u9009\u62e9\u7684\u7fa4\u4f53\uff0c\u4ece\u800c\u5b9e\u73b0\u653f\u7b56\u5236\u5b9a\u8005\u7684\u76ee\u6807\u3002\u6211\u4eec\u5c06\u8fd9\u4e00\u65b9\u6cd5\u5e94\u7528\u4e8e\u4e00\u9879\u5173\u4e8e\u4f4f\u5b85\u80fd\u6e90\u8865\u8d34\u8ba1\u5212\u7684\u968f\u673a\u5bf9\u7167\u8bd5\u9a8c\uff0c\u53d1\u73b0\u80fd\u591f\u540c\u65f6\u5145\u5206\u5229\u7528\u53ef\u89c2\u6d4b\u6570\u636e\u548c\u81ea\u6211\u9009\u62e9\u7684\u5b9a\u5411\u7b56\u7565\uff0c\u4f18\u4e8e\u4f20\u7edf\u5b9a\u5411\u65b9\u6cd5\u3002\u6211\u4eec\u91c7\u7528\u5c40\u90e8\u5e73\u5747\u5904\u7406\u6548\u5e94\uff08LATE\uff09\u6846\u67b6\uff08Imbens\u548cAngrist\uff081994\uff09\uff09\u6765\u5206\u6790\u672c\u65b9\u6cd5\u7684\u673a\u5236\u3002\u901a\u8fc7\u57fa\u4e8e\u5b9e\u9a8c\u4e2d\u4ea7\u751f\u7684\u968f\u673a\u53d8\u5f02\u4f30\u8ba1\u591a\u4e2a\u5173\u952eLATE\uff0c\u6211\u4eec\u5c55\u793a\u4e86\u8be5\u65b9\u6cd5\u5982\u4f55\u5e2e\u52a9\u653f\u7b56\u5236\u5b9a\u8005\u8bc6\u522b\u81ea\u6211\u9009\u62e9\u5bf9\u793e\u4f1a\u798f\u5229\u5177\u6709\u4ef7\u503c\u548c\u6709\u5bb3\u7684\u7fa4\u4f53\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22524", "journal": "ECTA", "title": "Curtailing False News, Amplifying Truth", "authors": ["Sergei Guriev", "Emeric Henry", "Th\u00e9o Marquis", "Ekaterina Zhuravskaya"], "author_details": [{"name": "Sergei Guriev", "affiliations": ["Department of Economics, London Business School", "CEPR"]}, {"name": "Emeric Henry", "affiliations": ["Department of Economics, Sciences Po Paris", "CEPR"]}, {"name": "Th\u00e9o Marquis", "affiliations": ["Economics and Management Department, Nantes University"]}, {"name": "Ekaterina Zhuravskaya", "affiliations": ["Paris School of Economics (EHESS)", "CEPR"]}], "abstract": "We develop a comprehensive framework to evaluate policy interventions aimed at curbing false news dissemination on social media. Using a randomized experiment on Twitter and X during the 2022 and 2024 U.S. elections, we assess priming for misinformation awareness, fact\u2010checking, confirmation clicks, and content consideration prompts. Priming proves most effective in reducing false\u2010news sharing while preserving true news dissemination. We build and structurally estimate a model of sharing, motivated by partisan persuasion, partisan signaling, and reputational concerns. We identify three channels through which policies influence sharing: (i) updating perceived veracity and partisanship of content, (ii) raising salience of reputation, and (iii) increasing engagement costs. Differences in the effects of policies are explained by the salience and cost channels. Content\u2010neutral priming is best at enhancing salience of reputation at minimal cost and almost as effective as fact\u2010checking in updating veracity. Salience channel is stronger when users encounter uncontroversially true content.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22524", "title_zh": "\u904f\u5236\u865a\u5047\u65b0\u95fb\uff0c\u653e\u5927\u771f\u76f8", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5168\u9762\u7684\u6846\u67b6\uff0c\u7528\u4e8e\u8bc4\u4f30\u65e8\u5728\u904f\u5236\u793e\u4ea4\u5a92\u4f53\u4e0a\u865a\u5047\u65b0\u95fb\u4f20\u64ad\u7684\u653f\u7b56\u5e72\u9884\u63aa\u65bd\u3002\u901a\u8fc7\u57282022\u5e74\u548c2024\u5e74\u7f8e\u56fd\u5927\u9009\u671f\u95f4\u5bf9Twitter\u548cX\u5e73\u53f0\u8fdb\u884c\u968f\u673a\u5b9e\u9a8c\uff0c\u6211\u4eec\u8bc4\u4f30\u4e86\u63d0\u5347\u5bf9\u865a\u5047\u4fe1\u606f\u8ba4\u77e5\u3001\u4e8b\u5b9e\u6838\u67e5\u3001\u786e\u8ba4\u70b9\u51fb\u4ee5\u53ca\u5185\u5bb9\u8003\u8651\u63d0\u793a\u7684\u6548\u679c\u3002\u7ed3\u679c\u663e\u793a\uff0c\u63d0\u793a\u63aa\u65bd\u5728\u51cf\u5c11\u865a\u5047\u65b0\u95fb\u4f20\u64ad\u65b9\u9762\u6700\u4e3a\u6709\u6548\uff0c\u540c\u65f6\u4fdd\u6301\u4e86\u771f\u5b9e\u65b0\u95fb\u7684\u4f20\u64ad\u3002\u6211\u4eec\u57fa\u4e8e\u515a\u6d3e\u8bf4\u670d\u3001\u515a\u6d3e\u4fe1\u53f7\u4f20\u9012\u548c\u58f0\u8a89\u5173\u5207\uff0c\u6784\u5efa\u5e76\u7ed3\u6784\u5316\u4f30\u8ba1\u4e86\u5185\u5bb9\u4f20\u64ad\u6a21\u578b\u3002\u6211\u4eec\u8bc6\u522b\u51fa\u653f\u7b56\u5f71\u54cd\u4f20\u64ad\u7684\u4e09\u4e2a\u6e20\u9053\uff1a\uff08i\uff09\u66f4\u65b0\u7528\u6237\u5bf9\u5185\u5bb9\u771f\u5b9e\u6027\u548c\u515a\u6d3e\u5c5e\u6027\u7684\u611f\u77e5\uff0c\uff08ii\uff09\u63d0\u5347\u58f0\u8a89\u7684\u663e\u8457\u6027\uff0c\uff08iii\uff09\u589e\u52a0\u4e92\u52a8\u6210\u672c\u3002\u653f\u7b56\u6548\u679c\u7684\u5dee\u5f02\u7531\u663e\u8457\u6027\u548c\u6210\u672c\u6e20\u9053\u89e3\u91ca\u3002\u4e2d\u7acb\u5185\u5bb9\u63d0\u793a\u5728\u63d0\u5347\u58f0\u8a89\u663e\u8457\u6027\u65b9\u9762\u6548\u679c\u6700\u4f73\uff0c\u4e14\u6210\u672c\u6700\u4f4e\uff0c\u5176\u6548\u679c\u51e0\u4e4e\u4e0e\u4e8b\u5b9e\u6838\u67e5\u5728\u66f4\u65b0\u5185\u5bb9\u771f\u5b9e\u6027\u65b9\u9762\u76f8\u5f53\u3002\u663e\u8457\u6027\u6e20\u9053\u5728\u7528\u6237\u63a5\u89e6\u5230\u65e0\u4e89\u8bae\u771f\u5b9e\u5185\u5bb9\u65f6\u66f4\u4e3a\u5f3a\u52b2\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta18759", "journal": "ECTA", "title": "Promoting Women to Managerial Roles in the Bangladeshi Garment Sector", "authors": ["Rocco Macchiavello", "Andreas Menzel", "Atonu Rabbani", "Christopher Woodruff"], "author_details": [{"name": "Rocco Macchiavello", "affiliations": ["Department of Management, London School of Economics"]}, {"name": "Andreas Menzel", "affiliations": ["Department of Economics, University of Padova"]}, {"name": "Atonu Rabbani", "affiliations": ["Department of Economics, University of Dhaka"]}, {"name": "Christopher Woodruff", "affiliations": ["Department of Economics, University of Oxford"]}], "abstract": "Women remain disadvantaged in promotion to managerial positions. We conduct a field experiment with 24 large garment factories in Bangladesh to test for inefficient representation of women among line supervisors. We identify the marginal female and male candidates for supervisory positions and randomly assign them to manage production lines. We document four findings: (1) In contrast to widespread negative beliefs about women's ability as supervisors at baseline, female candidates selected by the factories had similar skills to males; (2) during the trial, females performed worse than males, which we show is related to negative bias against them; (3) after the trial, however, many female candidates were retained as supervisors and, conditional on that, performed similar to males; and (4) after the end of our intervention, factories permanently increased the share of women among newly appointed supervisors. A conceptual framework of experimentation over discrimination rationalizes all these facts and cautions against the standard logic to test for discrimination: when there is uncertainty about the performance of the discriminated group, equal\u2014or even worse\u2014performance of the marginal candidates of that group is no longer sufficient to rule out inefficient discrimination.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta18759", "title_zh": "\u63a8\u52a8\u5b5f\u52a0\u62c9\u56fd\u670d\u88c5\u884c\u4e1a\u5973\u6027\u664b\u5347\u7ba1\u7406\u5c42\u804c\u4f4d", "abstract_zh": "\u5973\u6027\u5728\u664b\u5347\u7ba1\u7406\u5c42\u804c\u4f4d\u65b9\u9762\u4ecd\u5904\u4e8e\u4e0d\u5229\u5730\u4f4d\u3002\u6211\u4eec\u5bf9\u5b5f\u52a0\u62c9\u56fd24\u5bb6\u5927\u578b\u670d\u88c5\u5de5\u5382\u5f00\u5c55\u5b9e\u5730\u5b9e\u9a8c\uff0c\u68c0\u9a8c\u5973\u6027\u5728\u4e00\u7ebf\u4e3b\u7ba1\u804c\u4f4d\u4e2d\u7684\u4ee3\u8868\u6027\u662f\u5426\u4e0d\u8db3\u3002\u6211\u4eec\u8bc6\u522b\u51fa\u5de5\u5382\u4e2d\u8fb9\u9645\u5316\u7684\u5973\u6027\u548c\u7537\u6027\u5019\u9009\u4eba\uff0c\u5e76\u968f\u673a\u5c06\u4ed6\u4eec\u5206\u914d\u81f3\u7ba1\u7406\u751f\u4ea7\u7ebf\u3002\u6211\u4eec\u5f97\u51fa\u56db\u9879\u53d1\u73b0\uff1a\uff081\uff09\u4e0e\u57fa\u7ebf\u9636\u6bb5\u666e\u904d\u5b58\u5728\u7684\u5bf9\u5973\u6027\u4f5c\u4e3a\u4e3b\u7ba1\u80fd\u529b\u7684\u8d1f\u9762\u770b\u6cd5\u76f8\u53cd\uff0c\u88ab\u5de5\u5382\u9009\u4e2d\u7684\u5973\u6027\u5019\u9009\u4eba\u7684\u6280\u80fd\u4e0e\u7537\u6027\u76f8\u5f53\uff1b\uff082\uff09\u5728\u5b9e\u9a8c\u671f\u95f4\uff0c\u5973\u6027\u7684\u8868\u73b0\u900a\u4e8e\u7537\u6027\uff0c\u6211\u4eec\u8bc1\u660e\u8fd9\u79cd\u5dee\u5f02\u4e0e\u5bf9\u5973\u6027\u7684\u8d1f\u9762\u504f\u89c1\u6709\u5173\uff1b\uff083\uff09\u5b9e\u9a8c\u7ed3\u675f\u540e\uff0c\u8bb8\u591a\u5973\u6027\u5019\u9009\u4eba\u88ab\u4fdd\u7559\u4e3a\u4e3b\u7ba1\uff0c\u5e76\u4e14\u5728\u4fdd\u7559\u6761\u4ef6\u4e0b\uff0c\u5176\u8868\u73b0\u4e0e\u7537\u6027\u76f8\u5f53\uff1b\uff084\uff09\u5b9e\u9a8c\u7ed3\u675f\u540e\uff0c\u5de5\u5382\u5728\u65b0\u4efb\u547d\u7684\u4e3b\u7ba1\u4e2d\u5973\u6027\u6bd4\u4f8b\u6c38\u4e45\u6027\u5730\u4e0a\u5347\u3002\u4e00\u4e2a\u5173\u4e8e\u5b9e\u9a8c\u4e2d\u6b67\u89c6\u7684\u7406\u8bba\u6846\u67b6\u89e3\u91ca\u4e86\u6240\u6709\u8fd9\u4e9b\u73b0\u8c61\uff0c\u5e76\u8b66\u793a\u4eba\u4eec\u4e0d\u8981\u7b80\u5355\u5730\u91c7\u7528\u6807\u51c6\u903b\u8f91\u6765\u68c0\u9a8c\u6b67\u89c6\uff1a\u5f53\u5bf9\u88ab\u6b67\u89c6\u7fa4\u4f53\u7684\u8868\u73b0\u5b58\u5728\u4e0d\u786e\u5b9a\u6027\u65f6\uff0c\u8be5\u7fa4\u4f53\u8fb9\u9645\u5019\u9009\u4eba\u7684\u8868\u73b0\u76f8\u7b49\u751a\u81f3\u66f4\u5dee\uff0c\u5e76\u4e0d\u8db3\u4ee5\u6392\u9664\u4f4e\u6548\u6b67\u89c6\u7684\u5b58\u5728\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta20506", "journal": "ECTA", "title": "Firm\u2010to\u2010Firm Trade: Imports, Exports, and the Labor Market", "authors": ["Jonathan Eaton", "Samuel Kortum", "Francis Kramarz"], "author_details": [{"name": "Jonathan Eaton", "affiliations": ["Department of Economics, Pennsylvania State University"]}, {"name": "Samuel Kortum", "affiliations": ["Department of Economics, Yale University"]}, {"name": "Francis Kramarz", "affiliations": ["Innovation Lab, Coll\u00e8ge de France", "Department of Economics, Uppsala University"]}], "abstract": "Customs data reveal the heterogeneity and granularity of relationships among buyers and sellers, showing how more exports to a destination break down into more firms selling there and more buyers per exporter. We develop a quantitative general equilibrium model of firm\u2010to\u2010firm matching that builds on this insight to separate the roles of iceberg costs and matching frictions in gravity. In the cross section, we find matching frictions as important as iceberg costs in impeding trade, and more sensitive to distance. Because domestic and imported intermediates compete directly with labor in performing production tasks, our model also fits the heterogeneity of labor shares across French producers. Applying the framework to the 2004 expansion of the European Union, reduced iceberg costs and reduced matching frictions contributed equally to the increase in French exports to the new members. While workers benefited overall, those competing most directly with imports gained less, even losing in some countries entering the EU.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta20506", "title_zh": "\u4f01\u4e1a\u5bf9\u4f01\u4e1a\u8d38\u6613\uff1a\u8fdb\u53e3\u3001\u51fa\u53e3\u4e0e\u52b3\u52a8\u529b\u5e02\u573a", "abstract_zh": "\u6d77\u5173\u6570\u636e\u63ed\u793a\u4e86\u4e70\u65b9\u548c\u5356\u65b9\u4e4b\u95f4\u5173\u7cfb\u7684\u5f02\u8d28\u6027\u548c\u7ec6\u7c92\u5ea6\uff0c\u663e\u793a\u51fa\u53e3\u5230\u67d0\u4e00\u76ee\u7684\u5730\u7684\u589e\u52a0\u4f1a\u5206\u89e3\u4e3a\u66f4\u591a\u4f01\u4e1a\u5728\u8be5\u5730\u9500\u552e\u4ee5\u53ca\u6bcf\u4e2a\u51fa\u53e3\u5546\u7684\u4e70\u65b9\u6570\u91cf\u589e\u52a0\u3002\u6211\u4eec\u57fa\u4e8e\u8fd9\u4e00\u6d1e\u5bdf\uff0c\u6784\u5efa\u4e86\u4e00\u4e2a\u4f01\u4e1a\u5bf9\u4f01\u4e1a\u5339\u914d\u7684\u5b9a\u91cf\u4e00\u822c\u5747\u8861\u6a21\u578b\uff0c\u4ee5\u533a\u5206\u51b0\u5c71\u6210\u672c\u548c\u5339\u914d\u6469\u64e6\u5728\u5f15\u529b\u6a21\u578b\u4e2d\u7684\u4f5c\u7528\u3002\u5728\u6a2a\u622a\u9762\u5206\u6790\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\u5339\u914d\u6469\u64e6\u4e0e\u51b0\u5c71\u6210\u672c\u5728\u963b\u788d\u8d38\u6613\u65b9\u9762\u540c\u6837\u91cd\u8981\uff0c\u4e14\u5bf9\u8ddd\u79bb\u66f4\u4e3a\u654f\u611f\u3002\u7531\u4e8e\u56fd\u5185\u548c\u8fdb\u53e3\u4e2d\u95f4\u4ea7\u54c1\u5728\u6267\u884c\u751f\u4ea7\u4efb\u52a1\u65f6\u76f4\u63a5\u4e0e\u52b3\u52a8\u529b\u7ade\u4e89\uff0c\u6211\u4eec\u7684\u6a21\u578b\u4e5f\u80fd\u591f\u89e3\u91ca\u6cd5\u56fd\u751f\u4ea7\u8005\u4e4b\u95f4\u52b3\u52a8\u4efd\u989d\u7684\u5f02\u8d28\u6027\u3002\u5c06\u8be5\u6846\u67b6\u5e94\u7528\u4e8e2004\u5e74\u6b27\u76df\u6269\u5927\uff0c\u51b0\u5c71\u6210\u672c\u7684\u51cf\u5c11\u548c\u5339\u914d\u6469\u64e6\u7684\u964d\u4f4e\u5bf9\u6cd5\u56fd\u5bf9\u65b0\u6210\u5458\u56fd\u51fa\u53e3\u7684\u589e\u957f\u8d21\u732e\u76f8\u7b49\u3002\u5c3d\u7ba1\u603b\u4f53\u4e0a\u5de5\u4eba\u53d7\u76ca\uff0c\u4f46\u90a3\u4e9b\u4e0e\u8fdb\u53e3\u4ea7\u54c1\u7ade\u4e89\u6700\u76f4\u63a5\u7684\u7fa4\u4f53\u6536\u76ca\u51cf\u5c11\uff0c\u751a\u81f3\u5728\u4e00\u4e9b\u8fdb\u5165\u6b27\u76df\u7684\u56fd\u5bb6\u4e2d\u51fa\u73b0\u4e8f\u635f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta24060", "journal": "ECTA", "title": "Existence of Myopic\u2010Farsighted Stable Sets in Matching Markets", "authors": ["Battal Dogan", "Lars Ehlers"], "author_details": [{"name": "Battal Dogan", "affiliations": ["School of Economics, University of Bristol"]}, {"name": "Lars Ehlers", "affiliations": ["D\u00e9partement de sciences \u00e9conomiques and CIREQ, Universit\u00e9 de Montr\u00e9al"]}], "abstract": "In the context of one\u2010to\u2010one matching markets, we study myopic\u2010farsighted stable sets , which are internally and externally stable when myopic agents consider immediate payoffs from their deviations, while farsighted agents anticipate counter\u2010deviations and consider final payoffs. We constructively prove the existence of a (rational expectations) myopic\u2010farsighted stable set, in which farsighted agents receive a single payoff while myopic agents may receive multiple payoffs. Our existence result extends to settings with enforcing coalitions of arbitrary size, yielding coalitional myopic\u2010farsighted stable sets , and to settings where not all members of an enforcing coalition must strictly gain, yielding myopic\u2010farsighted weakly stable sets . When all farsighted agents have unit demand, our results also extend to many\u2010to\u2010one matching markets. As a key corollary, we provide a foundation for the efficiency\u2010adjusted deferred acceptance algorithm by showing that its outcome constitutes a singleton myopic\u2010farsighted stable set when one side is farsighted and the other is myopic.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta24060", "title_zh": "\u5339\u914d\u5e02\u573a\u4e2d\u77ed\u89c6-\u8fdc\u89c6\u7a33\u5b9a\u96c6\u7684\u5b58\u5728\u6027", "abstract_zh": "\u5728\u4e00\u5bf9\u4e00\u5339\u914d\u5e02\u573a\u80cc\u666f\u4e0b\uff0c\u6211\u4eec\u7814\u7a76\u77ed\u89c6-\u8fdc\u89c6\u7a33\u5b9a\u96c6\uff0c\u5176\u4e2d\u77ed\u89c6\u53c2\u4e0e\u8005\u4ec5\u8003\u8651\u5176\u504f\u79bb\u884c\u4e3a\u7684\u5373\u65f6\u6536\u76ca\uff0c\u800c\u8fdc\u89c6\u53c2\u4e0e\u8005\u5219\u9884\u89c1\u5230\u5bf9\u65b9\u7684\u53cd\u5411\u504f\u79bb\u5e76\u8003\u8651\u6700\u7ec8\u6536\u76ca\u3002\u6211\u4eec\u901a\u8fc7\u6784\u9020\u6027\u8bc1\u660e\u4e86\u5b58\u5728\u4e00\u4e2a\uff08\u7406\u6027\u9884\u671f\uff09\u77ed\u89c6-\u8fdc\u89c6\u7a33\u5b9a\u96c6\uff0c\u5728\u8be5\u96c6\u4e2d\u8fdc\u89c6\u53c2\u4e0e\u8005\u83b7\u5f97\u5355\u4e00\u6536\u76ca\uff0c\u800c\u77ed\u89c6\u53c2\u4e0e\u8005\u53ef\u80fd\u83b7\u5f97\u591a\u4e2a\u6536\u76ca\u3002\u6211\u4eec\u7684\u5b58\u5728\u6027\u7ed3\u679c\u53ef\u6269\u5c55\u81f3\u4efb\u610f\u89c4\u6a21\u7684\u8054\u76df\u5f3a\u5236\u60c5\u5f62\uff0c\u5f97\u5230\u8054\u76df\u77ed\u89c6-\u8fdc\u89c6\u7a33\u5b9a\u96c6\uff0c\u5e76\u8fdb\u4e00\u6b65\u6269\u5c55\u81f3\u8054\u76df\u6210\u5458\u5e76\u975e\u5168\u90e8\u4e25\u683c\u83b7\u76ca\u7684\u60c5\u5f62\uff0c\u5f97\u5230\u77ed\u89c6-\u8fdc\u89c6\u5f31\u7a33\u5b9a\u96c6\u3002\u5f53\u6240\u6709\u8fdc\u89c6\u53c2\u4e0e\u8005\u5177\u6709\u5355\u4f4d\u9700\u6c42\u65f6\uff0c\u6211\u4eec\u7684\u7ed3\u679c\u4e5f\u9002\u7528\u4e8e\u591a\u5bf9\u4e00\u5339\u914d\u5e02\u573a\u3002\u4f5c\u4e3a\u5173\u952e\u63a8\u8bba\uff0c\u6211\u4eec\u4e3a\u6548\u7387\u8c03\u6574\u7684\u5ef6\u671f\u63a5\u53d7\u7b97\u6cd5\u63d0\u4f9b\u4e86\u57fa\u7840\uff0c\u8bc1\u660e\u5f53\u4e00\u65b9\u4e3a\u8fdc\u89c6\u53c2\u4e0e\u8005\u3001\u53e6\u4e00\u65b9\u4e3a\u77ed\u89c6\u53c2\u4e0e\u8005\u65f6\uff0c\u8be5\u7b97\u6cd5\u7684\u8f93\u51fa\u6784\u6210\u4e00\u4e2a\u5355\u70b9\u77ed\u89c6-\u8fdc\u89c6\u7a33\u5b9a\u96c6\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23174", "journal": "ECTA", "title": "Identification in Instrumental Variables Models: The Central Role of Abadie's Kappa", "authors": ["Manu Navjeevan", "Rodrigo Pinto", "Andres Santos"], "author_details": [{"name": "Manu Navjeevan", "affiliations": ["Department of Economics, TAMU"]}, {"name": "Rodrigo Pinto", "affiliations": ["Department of Economics, USF"]}, {"name": "Andres Santos", "affiliations": ["Department of Economics, UCLA"]}], "abstract": "We study instrumental variables models characterized by: (i) Unobserved heterogeneity consisting of potential outcomes and response types that describe how the instrument determines treatment choice; (ii) Conditional independence of the instrument and the unobserved heterogeneity; and (iii) Convex restrictions on the distribution of unobserved heterogeneity. We show certain causal parameters are identified in these models if and only if a version of the kappa of Abadie (2003) exists. Our identification results are constructive in yielding estimating moment conditions. Focusing on a leading special case, we develop asymptotically normal estimators based on a doubly robust version of these moment conditions.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23174", "title_zh": "\u5de5\u5177\u53d8\u91cf\u6a21\u578b\u4e2d\u7684\u8bc6\u522b\uff1a\u963f\u5df4\u8fea kappa \u7684\u6838\u5fc3\u4f5c\u7528", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u7c7b\u5177\u6709\u4ee5\u4e0b\u7279\u5f81\u7684\u5de5\u5177\u53d8\u91cf\u6a21\u578b\uff1a(i) \u672a\u89c2\u6d4b\u5f02\u8d28\u6027\uff0c\u5305\u62ec\u6f5c\u5728\u7ed3\u679c\u548c\u54cd\u5e94\u7c7b\u578b\uff0c\u63cf\u8ff0\u4e86\u5de5\u5177\u53d8\u91cf\u5982\u4f55\u51b3\u5b9a\u5904\u7406\u9009\u62e9\uff1b(ii) \u5de5\u5177\u53d8\u91cf\u4e0e\u672a\u89c2\u6d4b\u5f02\u8d28\u6027\u5728\u6761\u4ef6\u4e0b\u7684\u72ec\u7acb\u6027\uff1b(iii) \u5bf9\u672a\u89c2\u6d4b\u5f02\u8d28\u6027\u5206\u5e03\u7684\u51f8\u6027\u9650\u5236\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5728\u8fd9\u4e9b\u6a21\u578b\u4e2d\uff0c\u67d0\u4e9b\u56e0\u679c\u53c2\u6570\u7684\u8bc6\u522b\u7b49\u4ef7\u4e8e\u963f\u5df4\u8fea\uff082003\uff09\u7684 kappa \u5b58\u5728\u3002\u6211\u4eec\u7684\u8bc6\u522b\u7ed3\u679c\u5177\u6709\u6784\u9020\u6027\uff0c\u80fd\u591f\u5bfc\u51fa\u4f30\u8ba1\u7684\u77e9\u6761\u4ef6\u3002\u9488\u5bf9\u4e00\u4e2a\u4e3b\u8981\u7684\u7279\u4f8b\uff0c\u6211\u4eec\u57fa\u4e8e\u8fd9\u4e9b\u77e9\u6761\u4ef6\u7684\u53cc\u91cd\u7a33\u5065\u7248\u672c\uff0c\u5f00\u53d1\u4e86\u6e10\u8fd1\u6b63\u6001\u7684\u4f30\u8ba1\u91cf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23125", "journal": "ECTA", "title": "Food Policy in a Warming World", "authors": ["Allan Hsiao", "Jacob Moscona", "Karthik A. Sastry"], "author_details": [{"name": "Allan Hsiao", "affiliations": ["Department of Economics, Stanford University"]}, {"name": "Jacob Moscona", "affiliations": ["Department of Economics, Massachusetts Institute of Technology"]}, {"name": "Karthik A. Sastry", "affiliations": ["Department of Economics, Princeton University"]}], "abstract": "This paper studies how governments intervene in agricultural markets to reshape the economic consequences of climate extremes. We construct a global dataset of agricultural policies and extreme heat exposure by country and crop since 1980. Extreme heat shocks to domestic production lead to policies that assist consumers by lowering domestic food prices. This effect is persistent, primarily implemented via border policies, and stronger during election years. Shocks to foreign production induce the opposite response: policies that assist producers by raising prices. These findings can be rationalized by a model in which governments use agricultural policy to redistribute among domestic interest groups. Our estimates imply that policy responses shield domestic consumers, while exacerbating losses for domestic producers and foreign consumers. Policy responses have regressive consequences globally, disproportionately harming poor and heat\u2010exposed countries.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23125", "title_zh": "\u5728\u4e00\u4e2a\u53d8\u6696\u7684\u4e16\u754c\u4e2d\u98df\u54c1\u653f\u7b56\u7684\u7814\u7a76", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u653f\u5e9c\u5982\u4f55\u901a\u8fc7\u5e72\u9884\u519c\u4e1a\u5e02\u573a\u6765\u6539\u53d8\u6c14\u5019\u6781\u7aef\u4e8b\u4ef6\u7684\u7ecf\u6d4e\u540e\u679c\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u81ea1980\u5e74\u4ee5\u6765\u6309\u56fd\u5bb6\u548c\u4f5c\u7269\u5212\u5206\u7684\u5168\u7403\u519c\u4e1a\u653f\u7b56\u4e0e\u6781\u7aef\u9ad8\u6e29\u66b4\u9732\u6570\u636e\u96c6\u3002\u56fd\u5185\u751f\u4ea7\u53d7\u5230\u6781\u7aef\u9ad8\u6e29\u51b2\u51fb\u65f6\uff0c\u653f\u5e9c\u4f1a\u51fa\u53f0\u653f\u7b56\u964d\u4f4e\u56fd\u5185\u98df\u54c1\u4ef7\u683c\u4ee5\u5e2e\u52a9\u6d88\u8d39\u8005\u3002\u8fd9\u79cd\u6548\u5e94\u5177\u6709\u6301\u7eed\u6027\uff0c\u4e3b\u8981\u901a\u8fc7\u8fb9\u5883\u653f\u7b56\u5b9e\u65bd\uff0c\u5e76\u5728\u9009\u4e3e\u5e74\u66f4\u4e3a\u663e\u8457\u3002\u800c\u5bf9\u56fd\u5916\u751f\u4ea7\u9020\u6210\u7684\u51b2\u51fb\u5219\u5f15\u53d1\u76f8\u53cd\u7684\u53cd\u5e94\uff1a\u653f\u5e9c\u91c7\u53d6\u63aa\u65bd\u63d0\u9ad8\u4ef7\u683c\u4ee5\u652f\u6301\u751f\u4ea7\u8005\u3002\u8fd9\u4e9b\u53d1\u73b0\u53ef\u4ee5\u901a\u8fc7\u4e00\u4e2a\u653f\u5e9c\u5229\u7528\u519c\u4e1a\u653f\u7b56\u5728\u4e0d\u540c\u56fd\u5185\u5229\u76ca\u7fa4\u4f53\u4e4b\u95f4\u8fdb\u884c\u518d\u5206\u914d\u7684\u6a21\u578b\u6765\u89e3\u91ca\u3002\u6211\u4eec\u7684\u4f30\u8ba1\u8868\u660e\uff0c\u653f\u7b56\u54cd\u5e94\u5728\u4fdd\u62a4\u56fd\u5185\u6d88\u8d39\u8005\u7684\u540c\u65f6\uff0c\u52a0\u5267\u4e86\u56fd\u5185\u751f\u4ea7\u8005\u548c\u5916\u56fd\u6d88\u8d39\u8005\u7684\u635f\u5931\u3002\u653f\u7b56\u54cd\u5e94\u5728\u5168\u7403\u8303\u56f4\u5185\u5177\u6709\u7d2f\u9000\u6027\uff0c\u5bf9\u8d2b\u56f0\u4eba\u53e3\u548c\u53d7\u9ad8\u6e29\u5f71\u54cd\u7684\u56fd\u5bb6\u9020\u6210\u4e0d\u6210\u6bd4\u4f8b\u7684\u4f24\u5bb3\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23373", "journal": "ECTA", "title": "Dynamic Incentives in Incompletely Specified Environments", "authors": ["Gabriel Carroll"], "author_details": [{"name": "Gabriel Carroll", "affiliations": ["Department of Economics, University of Toronto"]}], "abstract": "Consider a repeated interaction where it is unknown which of various stage games will be played each period. This framework separates the basic logic of intertemporal incentives from the requirement that any given strategy profile yields a well\u2010defined payoff vector. A natural solution concept is ex post perfect equilibrium: strategies must form a subgame\u2010perfect equilibrium for any realization of the sequence of stage games. When there is one long\u2010run player and others are short\u2010run, and public randomization is available, we can adapt the standard recursive approach to determine the maximum feasible gap between reward and punishment for the long\u2010run player. This allows us to identify which actions can be played in equilibrium and, assuming perfect monitoring, to fully characterize what outcome paths can arise. With multiple long\u2010run players or no public randomization, the approach fails; a diagnostic of this failure is that optimal penal codes may no longer exist.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23373", "title_zh": "\u4e0d\u5b8c\u5168\u6307\u5b9a\u73af\u5883\u4e2d\u7684\u52a8\u6001\u6fc0\u52b1", "abstract_zh": "\u8003\u8651\u4e00\u4e2a\u91cd\u590d\u4e92\u52a8\u573a\u666f\uff0c\u5176\u4e2d\u6bcf\u4e2a\u65f6\u671f\u5c06\u73a9\u7684\u5177\u4f53\u9636\u6bb5\u535a\u5f08\u662f\u672a\u77e5\u7684\u3002\u8be5\u6846\u67b6\u5c06\u8de8\u671f\u6fc0\u52b1\u7684\u57fa\u672c\u903b\u8f91\u4e0e\u4efb\u4f55\u7ed9\u5b9a\u7b56\u7565\u7ec4\u5408\u4ea7\u751f\u660e\u786e\u5b9a\u4e49\u7684\u652f\u4ed8\u5411\u91cf\u7684\u9700\u6c42\u533a\u5206\u5f00\u6765\u3002\u4e00\u4e2a\u81ea\u7136\u7684\u5747\u8861\u6982\u5ff5\u662f\u4e8b\u540e\u5b8c\u7f8e\u5747\u8861\uff1a\u7b56\u7565\u5fc5\u987b\u5728\u4efb\u4f55\u9636\u6bb5\u535a\u5f08\u5e8f\u5217\u7684\u5b9e\u73b0\u4e0b\u6784\u6210\u5b50\u535a\u5f08\u5b8c\u7f8e\u5747\u8861\u3002\u5f53\u5b58\u5728\u4e00\u4e2a\u957f\u671f\u53c2\u4e0e\u8005\u800c\u5176\u4ed6\u53c2\u4e0e\u8005\u4e3a\u77ed\u671f\u53c2\u4e0e\u8005\uff0c\u5e76\u4e14\u5b58\u5728\u516c\u5171\u968f\u673a\u5316\u65f6\uff0c\u6211\u4eec\u53ef\u4ee5\u91c7\u7528\u6807\u51c6\u7684\u9012\u5f52\u65b9\u6cd5\uff0c\u6765\u786e\u5b9a\u957f\u671f\u53c2\u4e0e\u8005\u7684\u5956\u52b1\u4e0e\u60e9\u7f5a\u4e4b\u95f4\u7684\u6700\u5927\u53ef\u884c\u5dee\u8ddd\u3002\u8fd9\u4f7f\u5f97\u6211\u4eec\u80fd\u591f\u8bc6\u522b\u54ea\u4e9b\u884c\u52a8\u53ef\u4ee5\u5728\u5747\u8861\u4e2d\u88ab\u5b9e\u65bd\uff0c\u5e76\u4e14\u5728\u5b8c\u5168\u76d1\u63a7\u7684\u5047\u8bbe\u4e0b\uff0c\u5b8c\u5168\u523b\u753b\u53ef\u80fd\u51fa\u73b0\u7684\u7ed3\u679c\u8def\u5f84\u3002\u5f53\u5b58\u5728\u591a\u4e2a\u957f\u671f\u53c2\u4e0e\u8005\u6216\u6ca1\u6709\u516c\u5171\u968f\u673a\u5316\u65f6\uff0c\u8be5\u65b9\u6cd5\u5931\u6548\uff1b\u8fd9\u79cd\u5931\u6548\u7684\u8bca\u65ad\u6807\u5fd7\u662f\uff0c\u6700\u4f18\u60e9\u7f5a\u673a\u5236\u53ef\u80fd\u4e0d\u518d\u5b58\u5728\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23709", "journal": "ECTA", "title": "Monotonicity and Robust Implementation Under Forward\u2010Induction Reasoning", "authors": ["Pierpaolo Battigalli", "Emiliano Catonini"], "author_details": [{"name": "Pierpaolo Battigalli", "affiliations": ["Department of Decision Sciences, Bocconi University", "IGIER"]}, {"name": "Emiliano Catonini", "affiliations": ["New York University Shanghai"]}], "abstract": "In sequential games, the set of paths consistent with rationality and forward\u2010induction reasoning may change nonmonotonically when adding transparent restrictions on players' beliefs. Yet, we prove that\u2014in an incomplete\u2010information environment\u2014predictions become sharper when the restrictions only concern initial beliefs about types. Thus, strong rationalizability for games with payoff uncertainty characterizes the path predictions of forward\u2010induction reasoning across all possible restrictions on players' hierarchies of exogenous beliefs. With this, we can solve an open problem: the implementation of social choice functions through sequential mechanisms under forward\u2010induction reasoning\u2014which considerably expands the realm of implementable functions compared with simultaneous mechanisms (M\u00fcller (2016))\u2014is indeed robust in the sense of Bergemann and Morris (2009).", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23709", "title_zh": "\u5355\u8c03\u6027\u4e0e\u5728\u524d\u5411\u5f52\u7eb3\u63a8\u7406\u4e0b\u7684\u9c81\u68d2\u5b9e\u65bd", "abstract_zh": "\u5728\u5e8f\u8d2f\u535a\u5f08\u4e2d\uff0c\u5f53\u5bf9\u73a9\u5bb6\u4fe1\u5ff5\u65bd\u52a0\u900f\u660e\u7684\u9650\u5236\u65f6\uff0c\u4e0e\u7406\u6027\u53ca\u524d\u5411\u5f52\u7eb3\u63a8\u7406\u4e00\u81f4\u7684\u8def\u5f84\u96c6\u5408\u53ef\u80fd\u975e\u5355\u8c03\u53d8\u5316\u3002\u7136\u800c\uff0c\u6211\u4eec\u8bc1\u660e\uff0c\u5728\u4e0d\u5b8c\u5168\u4fe1\u606f\u73af\u5883\u4e2d\uff0c\u5f53\u9650\u5236\u4ec5\u6d89\u53ca\u73a9\u5bb6\u5bf9\u7c7b\u578b\u521d\u59cb\u4fe1\u5ff5\u7684\u8bbe\u5b9a\u65f6\uff0c\u9884\u6d4b\u4f1a\u53d8\u5f97\u66f4\u52a0\u7cbe\u786e\u3002\u56e0\u6b64\uff0c\u5177\u6709\u6536\u76ca\u4e0d\u786e\u5b9a\u6027\u7684\u535a\u5f08\u4e2d\u7684\u5f3a\u7406\u6027\u5316\uff0c\u523b\u753b\u4e86\u524d\u5411\u5f52\u7eb3\u63a8\u7406\u5728\u6240\u6709\u53ef\u80fd\u7684\u73a9\u5bb6\u5916\u751f\u4fe1\u5ff5\u5c42\u7ea7\u9650\u5236\u4e0b\u7684\u8def\u5f84\u9884\u6d4b\u3002\u501f\u6b64\uff0c\u6211\u4eec\u89e3\u51b3\u4e86\u4e00\u4e2a\u5f00\u653e\u6027\u95ee\u9898\uff1a\u5728\u524d\u5411\u5f52\u7eb3\u63a8\u7406\u4e0b\u901a\u8fc7\u5e8f\u8d2f\u673a\u5236\u5b9e\u65bd\u793e\u4f1a\u9009\u62e9\u51fd\u6570\uff0c\u786e\u5b9e\u5177\u5907Bergemann\u548cMorris\uff082009\uff09\u6240\u5b9a\u4e49\u7684\u9c81\u68d2\u6027\uff0c\u8fd9\u5728\u5b9e\u65bd\u8303\u56f4\u4e0a\u663e\u8457\u6269\u5c55\u4e86\u76f8\u5bf9\u4e8e\u540c\u65f6\u673a\u5236\uff08M\u00fcller\uff082016\uff09\uff09\u7684\u53ef\u5b9e\u65bd\u51fd\u6570\u96c6\u5408\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23334", "journal": "ECTA", "title": "The Inference\u2010Forecast Gap in Belief Updating", "authors": ["Tony Q. Fan", "Yucheng Liang", "Cameron Peng"], "author_details": [{"name": "Tony Q. Fan", "affiliations": ["Department of Economics, College of Business, Lehigh University"]}, {"name": "Yucheng Liang", "affiliations": ["Tepper School of Business, Carnegie Mellon University"]}, {"name": "Cameron Peng", "affiliations": ["Department of Finance, London School of Economics and Political Science"]}], "abstract": "Evidence from the laboratory and the field has uncovered both underreaction and overreaction to new information. We provide new experimental evidence on the underlying mechanisms of under\u2010 and overreaction by comparing how people make inferences and revise forecasts in the same information environment. Participants underreact to signals when inferring about underlying states, but overreact to the same signals when revising forecasts about future outcomes\u2014a phenomenon we term \u201cthe inference\u2010forecast gap.\u201d We show that this gap is largely driven by different simplifying heuristics used in the two tasks. Additional treatments suggest that the choice of heuristics is affected by the similarity between statistics in the information environment and the statistic elicited by the belief\u2010updating problem.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23334", "title_zh": "\u4fe1\u5ff5\u66f4\u65b0\u4e2d\u7684\u63a8\u65ad-\u9884\u6d4b\u5dee\u8ddd", "abstract_zh": "\u5b9e\u9a8c\u5ba4\u548c\u5b9e\u5730\u7684\u8bc1\u636e\u63ed\u793a\u4e86\u4eba\u4eec\u5bf9\u65b0\u4fe1\u606f\u7684\u53cd\u5e94\u4e0d\u8db3\u548c\u8fc7\u5ea6\u53cd\u5e94\u3002\u6211\u4eec\u901a\u8fc7\u5728\u76f8\u540c\u4fe1\u606f\u73af\u5883\u4e0b\u6bd4\u8f83\u4eba\u4eec\u5728\u63a8\u65ad\u57fa\u672c\u72b6\u6001\u548c\u4fee\u6b63\u5bf9\u672a\u6765\u7ed3\u679c\u7684\u9884\u6d4b\u65f6\u7684\u884c\u4e3a\uff0c\u63d0\u4f9b\u4e86\u5173\u4e8e\u53cd\u5e94\u4e0d\u8db3\u548c\u8fc7\u5ea6\u53cd\u5e94\u80cc\u540e\u673a\u5236\u7684\u65b0\u5b9e\u9a8c\u8bc1\u636e\u3002\u53c2\u4e0e\u8005\u5728\u63a8\u65ad\u57fa\u672c\u72b6\u6001\u65f6\u5bf9\u4fe1\u53f7\u53cd\u5e94\u4e0d\u8db3\uff0c\u4f46\u5728\u4fee\u6b63\u5bf9\u672a\u6765\u7ed3\u679c\u7684\u9884\u6d4b\u65f6\u5bf9\u540c\u4e00\u4fe1\u53f7\u53cd\u5e94\u8fc7\u5ea6\u2014\u2014\u6211\u4eec\u79f0\u8fd9\u79cd\u73b0\u8c61\u4e3a\u201c\u63a8\u65ad-\u9884\u6d4b\u5dee\u8ddd\u201d\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u4e00\u5dee\u8ddd\u4e3b\u8981\u7531\u63a8\u65ad\u548c\u9884\u6d4b\u4efb\u52a1\u4e2d\u4f7f\u7528\u7684\u4e0d\u540c\u7b80\u5316\u542f\u53d1\u5f0f\u65b9\u6cd5\u6240\u9a71\u52a8\u3002\u989d\u5916\u7684\u5b9e\u9a8c\u5904\u7406\u8868\u660e\uff0c\u542f\u53d1\u5f0f\u65b9\u6cd5\u7684\u9009\u62e9\u53d7\u5230\u4fe1\u606f\u73af\u5883\u4e2d\u7684\u7edf\u8ba1\u7279\u5f81\u4e0e\u4fe1\u5ff5\u66f4\u65b0\u95ee\u9898\u6240\u8981\u6c42\u7684\u7edf\u8ba1\u7279\u5f81\u4e4b\u95f4\u76f8\u4f3c\u6027\u7684\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta24210", "journal": "ECTA", "title": "Comment on \u2018Fisher\u2013Schultz Lecture: Contracting Over Pharmaceutical Formularies and Rebates\u2019 by Kate Ho and Robin Lee", "authors": ["Rena M. Conti"], "author_details": [{"name": "Rena M. Conti", "affiliations": ["Department of Markets, Public Policy and Law, Questrom School of Business, Boston University"]}], "abstract": "Biopharmaceuticals advance health and economic growth. Unlike central bargaining abroad, the United States uses private firms, pharmacy benefit managers (PBMs), to manage medicine access and spending. Yet, PBMs' roles in advancing efficiency are understudied. Ho and Lee model PBMs' use of tiered formularies, lists of covered medicines, without the use of proprietary data on the price concessions drug makers offer for preferred placement. They find PBMs' use of tiered formularies generate significant payor savings through competition. Complementing Ho and Lee, Feng and Maini (2024) model how patient demand inertia limits PBMs' ability to extract price concessions from drug makers which consequently erodes the efficacy gains of PBM formularies. Conti, Frandsen, Powell, and Rebitzer (2021) model formulary auctions where PBM size drives payor savings, but also spurs endogenously set high list prices, reducing patient access. Future economic research should focus on PBM market entry and vertical integration, pharmacy steering, and effects on innovation.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta24210", "title_zh": "\u5bf9Kate Ho\u548cRobin Lee\u300a\u83f2\u820d\u5c14-\u8212\u5c14\u8328\u8bb2\u5ea7\uff1a\u5173\u4e8e\u836f\u54c1\u76ee\u5f55\u548c\u56de\u6263\u7684\u5408\u540c\u300b\u4e00\u6587\u7684\u8bc4\u8bba", "abstract_zh": "\u751f\u7269\u5236\u836f\u63a8\u52a8\u5065\u5eb7\u548c\u7ecf\u6d4e\u589e\u957f\u3002\u4e0d\u540c\u4e8e\u56fd\u5916\u7684\u4e2d\u592e\u8c08\u5224\u673a\u5236\uff0c\u7f8e\u56fd\u901a\u8fc7\u79c1\u8425\u4f01\u4e1a\u3001\u836f\u54c1\u798f\u5229\u7ba1\u7406\u516c\u53f8\uff08PBMs\uff09\u6765\u7ba1\u7406\u836f\u54c1\u7684\u53ef\u53ca\u6027\u548c\u652f\u51fa\u3002\u7136\u800c\uff0cPBMs\u5728\u63d0\u5347\u6548\u7387\u65b9\u9762\u7684\u4f5c\u7528\u4ecd\u88ab\u7814\u7a76\u4e0d\u8db3\u3002Ho\u548cLee\u6784\u5efa\u4e86\u4e00\u4e2a\u6a21\u578b\uff0c\u7814\u7a76PBMs\u5728\u4e0d\u4f7f\u7528\u5236\u836f\u4f01\u4e1a\u4e3a\u4f18\u5148\u4f4d\u7f6e\u63d0\u4f9b\u7684\u4e13\u6709\u4ef7\u683c\u8ba9\u6b65\u6570\u636e\u7684\u60c5\u51b5\u4e0b\uff0c\u5982\u4f55\u5229\u7528\u5206\u5c42\u76ee\u5f55\uff08\u5373\u8986\u76d6\u836f\u54c1\u6e05\u5355\uff09\u6765\u5b9e\u73b0\u663e\u8457\u7684\u652f\u4ed8\u65b9\u8282\u7701\uff0c\u901a\u8fc7\u7ade\u4e89\u5b9e\u73b0\u6548\u7387\u63d0\u5347\u3002\u5728Ho\u548cLee\u7814\u7a76\u7684\u57fa\u7840\u4e0a\uff0cFeng\u548cMaini\uff082024\uff09\u7814\u7a76\u4e86\u60a3\u8005\u9700\u6c42\u60ef\u6027\u5982\u4f55\u9650\u5236PBMs\u4ece\u5236\u836f\u4f01\u4e1a\u63d0\u53d6\u4ef7\u683c\u8ba9\u6b65\u7684\u80fd\u529b\uff0c\u4ece\u800c\u524a\u5f31\u4e86PBM\u76ee\u5f55\u4f53\u7cfb\u7684\u6548\u76ca\u3002Conti\u3001Frandsen\u3001Powell\u548cRebitzer\uff082021\uff09\u5219\u7814\u7a76\u4e86\u76ee\u5f55\u62cd\u5356\u673a\u5236\uff0c\u53d1\u73b0PBM\u89c4\u6a21\u867d\u7136\u80fd\u5e26\u6765\u652f\u4ed8\u65b9\u8282\u7701\uff0c\u4f46\u4e5f\u5bfc\u81f4\u4e86\u5185\u751f\u8bbe\u5b9a\u7684\u9ad8\u76ee\u5f55\u4ef7\u683c\uff0c\u4ece\u800c\u964d\u4f4e\u60a3\u8005\u53ef\u53ca\u6027\u3002\u672a\u6765\u7ecf\u6d4e\u7814\u7a76\u5e94\u805a\u7126\u4e8ePBM\u5e02\u573a\u8fdb\u5165\u548c\u5782\u76f4\u6574\u5408\u3001\u836f\u623f\u5f15\u5bfc\u4f5c\u7528\u4ee5\u53ca\u5bf9\u521b\u65b0\u7684\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta21097", "journal": "ECTA", "title": "Assortative Matching on Income", "authors": ["Pierre-Andr\u00e9 Chiappori", "Carlo Fiorio", "Alfred Galichon", "Stefano Verzillo"], "author_details": [{"name": "Pierre-Andr\u00e9 Chiappori", "affiliations": ["Department of Economics, Columbia University"]}, {"name": "Carlo Fiorio", "affiliations": ["Department of Economics, Management and Quantitative Methods, Universit\u00e0 degli Studi di Milano", "IRVAPP, FBK"]}, {"name": "Alfred Galichon", "affiliations": ["Economics and Mathematics Departments, New York University", "Economics Department, Sciences Po"]}, {"name": "Stefano Verzillo", "affiliations": ["Competence Centre on Microeconomic Evaluation (CC-ME), European Commission, Joint Research Centre (JRC)"]}], "abstract": "We analyze marital matching on income using an extremely rich Dutch data set containing all income tax files over seven years. We develop a novel methodology that directly extends previous contributions to allow for highly flexible matching patterns. Investigating all marriages that took place between 2013 and 2019, we find that marital patterns are particularly intriguing. While a majority of couples match assortatively, a small but significant minority display negative assortative matching. We also show that standard approaches, which consider all married couples using current incomes (as opposed to pre\u2010marriage incomes used in our approach), may generate misleading conclusions.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21097", "title_zh": "\u6536\u5165\u4e0a\u7684\u62e9\u5076\u5339\u914d", "abstract_zh": "\u6211\u4eec\u5229\u7528\u4e00\u4e2a\u6781\u4e3a\u4e30\u5bcc\u7684\u8377\u5170\u6570\u636e\u96c6\u2014\u2014\u5305\u542b\u4e03\u5e74\u6240\u6709\u6536\u5165\u7a0e\u8bb0\u5f55\u2014\u2014\u5206\u6790\u5a5a\u59fb\u4e2d\u7684\u6536\u5165\u5339\u914d\u60c5\u51b5\u3002\u6211\u4eec\u5f00\u53d1\u4e86\u4e00\u79cd\u65b0\u9896\u7684\u65b9\u6cd5\uff0c\u8be5\u65b9\u6cd5\u76f4\u63a5\u6269\u5c55\u4e86\u4ee5\u5f80\u7684\u7814\u7a76\uff0c\u5141\u8bb8\u9ad8\u5ea6\u7075\u6d3b\u7684\u5339\u914d\u6a21\u5f0f\u3002\u5728\u7814\u7a762013\u5e74\u81f32019\u5e74\u95f4\u6240\u6709\u5a5a\u59fb\u65f6\uff0c\u6211\u4eec\u53d1\u73b0\u5a5a\u59fb\u5339\u914d\u6a21\u5f0f\u5c24\u4e3a\u5f15\u4eba\u6ce8\u76ee\uff1a\u5c3d\u7ba1\u5927\u591a\u6570\u592b\u59bb\u5448\u73b0\u6b63\u5411\u62e9\u5076\u5339\u914d\uff0c\u4f46\u6709\u4e00\u5c0f\u90e8\u5206\u5374\u8868\u73b0\u51fa\u8d1f\u5411\u62e9\u5076\u5339\u914d\u3002\u6211\u4eec\u8fd8\u8868\u660e\uff0c\u6807\u51c6\u65b9\u6cd5\u2014\u2014\u5373\u4f7f\u7528\u5f53\u524d\u6536\u5165\u800c\u975e\u5a5a\u524d\u6536\u5165\u6765\u5206\u6790\u5df2\u5a5a\u592b\u5987\u2014\u2014\u53ef\u80fd\u4f1a\u5f97\u51fa\u8bef\u5bfc\u6027\u7684\u7ed3\u8bba\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22565", "journal": "ECTA", "title": "Firm Accommodation After Workplace Disability: Labor Market Impacts and Implications for Subsidy Design", "authors": ["Naoki Aizawa", "Corina Mommaerts", "Stephanie Rennane"], "author_details": [{"name": "Naoki Aizawa", "affiliations": ["Department of Economics, University of Wisconsin-Madison", "NBER"]}, {"name": "Corina Mommaerts", "affiliations": ["Department of Economics, University of Wisconsin-Madison", "NBER"]}, {"name": "Stephanie Rennane", "affiliations": ["RAND Corporation"]}], "abstract": "This paper studies the labor market impacts of firm accommodation decisions after workplace disability and assesses implications for the design of firm subsidies. We leverage a workers' compensation (WC) program in Oregon that provides wage subsidies to firms for accommodating workers with workplace disabilities. Leveraging rich administrative data and a policy change to the wage subsidy, we show that accommodation rates respond to the subsidy rate and that receipt of accommodation leads to a significant increase in employment and earnings a year later. To explore welfare implications, we develop and estimate a frictional labor market model of accommodation as a form of human capital investment. Worker turnover and imperfect experience rating in WC lead to underaccommodation and inefficient labor market outcomes after workplace disability. Counterfactual simulations show that subsidizing accommodation not only improves long\u2010run labor market outcomes of workers experiencing work\u2010related disability but also yields welfare gains for most workers.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22565", "title_zh": "\u5de5\u4f5c\u573a\u6240\u6b8b\u75be\u540e\u4f01\u4e1a\u9002\u5e94\u63aa\u65bd\u7684\u52b3\u52a8\u529b\u5e02\u573a\u5f71\u54cd\u53ca\u5bf9\u8865\u8d34\u8bbe\u8ba1\u7684\u542f\u793a", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u4f01\u4e1a\u5728\u5de5\u4f5c\u573a\u6240\u6b8b\u75be\u540e\u91c7\u53d6\u9002\u5e94\u63aa\u65bd\u7684\u52b3\u52a8\u529b\u5e02\u573a\u5f71\u54cd\uff0c\u5e76\u8bc4\u4f30\u4e86\u8fd9\u5bf9\u4f01\u4e1a\u8865\u8d34\u8bbe\u8ba1\u7684\u542f\u793a\u3002\u6211\u4eec\u5229\u7528\u4fc4\u52d2\u5188\u5dde\u7684\u4e00\u9879\u5de5\u4f24\u8d54\u507f\uff08WC\uff09\u8ba1\u5212\uff0c\u8be5\u8ba1\u5212\u4e3a\u4f01\u4e1a\u63d0\u4f9b\u5de5\u8d44\u8865\u8d34\u4ee5\u652f\u6301\u6b8b\u75be\u5458\u5de5\u7684\u9002\u5e94\u63aa\u65bd\u3002\u57fa\u4e8e\u4e30\u5bcc\u7684\u884c\u653f\u6570\u636e\u4ee5\u53ca\u5bf9\u5de5\u8d44\u8865\u8d34\u653f\u7b56\u7684\u8c03\u6574\uff0c\u6211\u4eec\u53d1\u73b0\u9002\u5e94\u7387\u4f1a\u968f\u8865\u8d34\u7387\u7684\u53d8\u5316\u800c\u53d8\u5316\uff0c\u4e14\u83b7\u5f97\u9002\u5e94\u63aa\u65bd\u540e\uff0c\u5458\u5de5\u5728\u4e00\u5e74\u540e\u7684\u5c31\u4e1a\u7387\u548c\u6536\u5165\u5747\u663e\u8457\u63d0\u9ad8\u3002\u4e3a\u4e86\u63a2\u8ba8\u798f\u5229\u5f71\u54cd\uff0c\u6211\u4eec\u6784\u5efa\u5e76\u4f30\u8ba1\u4e86\u4e00\u4e2a\u6469\u64e6\u6027\u52b3\u52a8\u529b\u5e02\u573a\u6a21\u578b\uff0c\u5c06\u9002\u5e94\u63aa\u65bd\u89c6\u4e3a\u4eba\u529b\u8d44\u672c\u6295\u8d44\u7684\u4e00\u79cd\u5f62\u5f0f\u3002\u5de5\u4eba\u6d41\u52a8\u6027\u548c\u5de5\u4f24\u4fdd\u9669\u4e2d\u7684\u4e0d\u5b8c\u5168\u7ecf\u9a8c\u8bc4\u7ea7\u5bfc\u81f4\u4e86\u9002\u5e94\u4e0d\u8db3\u548c\u52b3\u52a8\u5e02\u573a\u6548\u7387\u4f4e\u4e0b\u3002\u53cd\u4e8b\u5b9e\u6a21\u62df\u8868\u660e\uff0c\u5bf9\u9002\u5e94\u63aa\u65bd\u8fdb\u884c\u8865\u8d34\u4e0d\u4ec5\u6539\u5584\u4e86\u7ecf\u5386\u5de5\u4f5c\u76f8\u5173\u6b8b\u75be\u5458\u5de5\u7684\u957f\u671f\u52b3\u52a8\u529b\u5e02\u573a\u7ed3\u679c\uff0c\u4e5f\u5bf9\u5927\u591a\u6570\u5458\u5de5\u5e26\u6765\u4e86\u798f\u5229\u63d0\u5347\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22613", "journal": "ECTA", "title": "Communicating Scientific Uncertainty via Approximate Posteriors", "authors": ["Isaiah Andrews", "Jesse M. Shapiro"], "author_details": [{"name": "Isaiah Andrews", "affiliations": ["MIT", "NBER"]}, {"name": "Jesse M. Shapiro", "affiliations": ["Harvard University", "NBER"]}], "abstract": "We cast the problem of communicating scientific uncertainty as one of reporting a posterior distribution on an unknown parameter to an audience of Bayesian decision\u2010makers. We establish novel bounds on the audience's regret when the analyst reports an approximation to a posterior that the audience treats as exact. Under a palatable restriction on the audience's decision problems, the bounds take an especially convenient form. Under a further restriction on the audience's priors, a bootstrap distribution can be used as a stand\u2010in posterior. We propose a practical recipe for checking whether a conventional statistical report (say, a normal parameterized by a point estimate and standard error) is a good approximation, and for improving the report if it is not. We illustrate our proposals using the articles in the 2021 American Economic Review that use a bootstrap for inference.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22613", "title_zh": "\u901a\u8fc7\u8fd1\u4f3c\u540e\u9a8c\u5206\u5e03\u4f20\u64ad\u79d1\u5b66\u4e0d\u786e\u5b9a\u6027", "abstract_zh": "\u6211\u4eec\u5c06\u4f20\u64ad\u79d1\u5b66\u4e0d\u786e\u5b9a\u6027\u7684\u95ee\u9898\u8868\u8ff0\u4e3a\uff1a\u5411\u4e00\u7ec4\u8d1d\u53f6\u65af\u51b3\u7b56\u8005\u62a5\u544a\u4e00\u4e2a\u672a\u77e5\u53c2\u6570\u7684\u540e\u9a8c\u5206\u5e03\u3002\u6211\u4eec\u5efa\u7acb\u4e86\u5f53\u5206\u6790\u5e08\u62a5\u544a\u4e00\u4e2a\u540e\u9a8c\u5206\u5e03\u7684\u8fd1\u4f3c\u7248\u672c\uff0c\u800c\u53d7\u4f17\u5c06\u5176\u89c6\u4e3a\u7cbe\u786e\u65f6\uff0c\u53d7\u4f17\u540e\u6094\u7a0b\u5ea6\u7684\u65b0\u578b\u754c\u9650\u3002\u5728\u53d7\u4f17\u51b3\u7b56\u95ee\u9898\u6ee1\u8db3\u4e00\u4e2a\u5408\u7406\u9650\u5236\u7684\u6761\u4ef6\u4e0b\uff0c\u8fd9\u4e9b\u754c\u9650\u5448\u73b0\u51fa\u7279\u522b\u4fbf\u5229\u7684\u5f62\u5f0f\u3002\u5728\u53d7\u4f17\u5148\u9a8c\u6ee1\u8db3\u8fdb\u4e00\u6b65\u9650\u5236\u7684\u6761\u4ef6\u4e0b\uff0c\u53ef\u4ee5\u4f7f\u7528\u81ea\u52a9\u5206\u5e03\u4f5c\u4e3a\u540e\u9a8c\u5206\u5e03\u7684\u66ff\u4ee3\u3002\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u5b9e\u7528\u7684\u6d41\u7a0b\uff0c\u7528\u4e8e\u68c0\u9a8c\u4f20\u7edf\u7edf\u8ba1\u62a5\u544a\uff08\u4f8b\u5982\uff0c\u7531\u70b9\u4f30\u8ba1\u548c\u6807\u51c6\u8bef\u5dee\u53c2\u6570\u5316\u7684\u6b63\u6001\u5206\u5e03\uff09\u662f\u5426\u662f\u4e00\u4e2a\u826f\u597d\u7684\u8fd1\u4f3c\uff0c\u5e76\u5728\u5176\u4e0d\u6ee1\u8db3\u65f6\u8fdb\u884c\u6539\u8fdb\u3002\u6211\u4eec\u5229\u75282021\u5e74\u300a\u7f8e\u56fd\u7ecf\u6d4e\u8bc4\u8bba\u300b\u4e2d\u4f7f\u7528\u81ea\u52a9\u6cd5\u8fdb\u884c\u63a8\u65ad\u7684\u6587\u7ae0\u6765\u8bf4\u660e\u6211\u4eec\u7684\u5efa\u8bae\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22145", "journal": "ECTA", "title": "Subgroup Decomposition of the Gini Coefficient: A New Solution to an Old Problem", "authors": ["Vesa-Matti Heikkuri", "Matthias Schief"], "author_details": [{"name": "Vesa-Matti Heikkuri", "affiliations": ["Faculty of Management and Business, Tampere University"]}, {"name": "Matthias Schief", "affiliations": ["Economics Department, OECD"]}], "abstract": "We derive a novel decomposition of the Gini coefficient into within\u2010 and between\u2010group inequality terms that sum to the aggregate Gini coefficient. This decomposition is derived from a set of axioms that ensure desirable behavior for the within\u2010 and between\u2010group inequality terms. The decomposition of the Gini coefficient is unique given our axioms, easy to compute, and can be interpreted geometrically.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22145", "title_zh": "\u57fa\u5c3c\u7cfb\u6570\u7684\u5b50\u7ec4\u5206\u89e3\uff1a\u5bf9\u4e00\u4e2a\u53e4\u8001\u95ee\u9898\u7684\u65b0\u89e3\u51b3\u65b9\u6848", "abstract_zh": "\u6211\u4eec\u63a8\u5bfc\u51fa\u4e00\u79cd\u65b0\u9896\u7684\u57fa\u5c3c\u7cfb\u6570\u5206\u89e3\u65b9\u6cd5\uff0c\u5c06\u5176\u5206\u89e3\u4e3a\u7ec4\u5185\u4e0d\u5e73\u7b49\u548c\u7ec4\u95f4\u4e0d\u5e73\u7b49\u4e24\u9879\uff0c\u8fd9\u4e24\u9879\u4e4b\u548c\u7b49\u4e8e\u603b\u4f53\u57fa\u5c3c\u7cfb\u6570\u3002\u8be5\u5206\u89e3\u57fa\u4e8e\u4e00\u7ec4\u516c\u7406\uff0c\u786e\u4fdd\u7ec4\u5185\u548c\u7ec4\u95f4\u4e0d\u5e73\u7b49\u9879\u5177\u6709\u826f\u597d\u7684\u884c\u4e3a\u7279\u6027\u3002\u5728\u7ed9\u5b9a\u516c\u7406\u7684\u524d\u63d0\u4e0b\uff0c\u57fa\u5c3c\u7cfb\u6570\u7684\u5206\u89e3\u662f\u552f\u4e00\u7684\uff0c\u8ba1\u7b97\u7b80\u4fbf\uff0c\u5e76\u4e14\u53ef\u4ee5\u8fdb\u884c\u51e0\u4f55\u89e3\u91ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta21926", "journal": "ECTA", "title": "Mechanism Design for Personalized Policy: A Field Experiment Incentivizing Exercise", "authors": ["Rebecca Dizon-Ross", "Ariel Zucker"], "author_details": [{"name": "Rebecca Dizon-Ross", "affiliations": ["Booth School of Business, University of Chicago"]}, {"name": "Ariel Zucker", "affiliations": ["Department of Economics, University of California"]}], "abstract": "Personalizing policies can theoretically increase their effectiveness. However, personalization is difficult when individual types are unobservable and the preferences of policymakers and individuals are not aligned, which could cause individuals to misreport their type. Mechanism design offers a strategy to overcome this issue: offer an \u201cincentive\u2010compatible\u201d menu of policy choices designed to induce participants to select the variant intended for their type. Using a field experiment that personalized incentives for exercise among 6,800 adults with diabetes and hypertension in urban India, we show that personalizing with an incentive\u2010compatible choice menu substantially improves program performance, increasing the treatment effect of incentives on exercise by 80% without increasing incentive costs relative to a one\u2010size\u2010fits\u2010all benchmark. Offering choice achieves similar performance to personalizing with an extensive set of observable variables, but without the same data requirements.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21926", "title_zh": "\u9762\u5411\u4e2a\u6027\u5316\u653f\u7b56\u7684\u673a\u5236\u8bbe\u8ba1\uff1a\u4e00\u9879\u6fc0\u52b1\u953b\u70bc\u7684\u5b9e\u5730\u5b9e\u9a8c", "abstract_zh": "\u4e2a\u6027\u5316\u653f\u7b56\u5728\u7406\u8bba\u4e0a\u53ef\u4ee5\u63d0\u9ad8\u5176\u6709\u6548\u6027\u3002\u7136\u800c\uff0c\u5f53\u4e2a\u4f53\u7c7b\u578b\u4e0d\u53ef\u89c2\u6d4b\u4e14\u653f\u7b56\u5236\u5b9a\u8005\u4e0e\u4e2a\u4f53\u7684\u504f\u597d\u4e0d\u4e00\u81f4\u65f6\uff0c\u4e2a\u4eba\u53ef\u80fd\u4f1a\u9519\u8bef\u62a5\u544a\u81ea\u5df1\u7684\u7c7b\u578b\uff0c\u8fd9\u4f7f\u5f97\u4e2a\u6027\u5316\u9762\u4e34\u56f0\u96be\u3002\u673a\u5236\u8bbe\u8ba1\u63d0\u4f9b\u4e86\u4e00\u79cd\u89e3\u51b3\u65b9\u6848\uff1a\u8bbe\u8ba1\u4e00\u4e2a\u201c\u6fc0\u52b1\u76f8\u5bb9\u201d\u7684\u653f\u7b56\u9009\u62e9\u83dc\u5355\uff0c\u4ee5\u5f15\u5bfc\u53c2\u4e0e\u8005\u9009\u62e9\u9002\u5408\u5176\u7c7b\u578b\u7684\u653f\u7b56\u53d8\u4f53\u3002\u901a\u8fc7\u4e00\u9879\u9488\u5bf9\u5370\u5ea6\u57ce\u5e026800\u540d\u7cd6\u5c3f\u75c5\u548c\u9ad8\u8840\u538b\u60a3\u8005\u7684\u5b9e\u5730\u5b9e\u9a8c\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u91c7\u7528\u6fc0\u52b1\u76f8\u5bb9\u7684\u9009\u62e9\u83dc\u5355\u663e\u8457\u63d0\u5347\u4e86\u9879\u76ee\u8868\u73b0\uff0c\u4f7f\u6fc0\u52b1\u5bf9\u953b\u70bc\u7684\u6cbb\u7597\u6548\u679c\u63d0\u9ad8\u4e8680%\uff0c\u4e14\u76f8\u5bf9\u4e8e\u7edf\u4e00\u653f\u7b56\u57fa\u51c6\uff0c\u6fc0\u52b1\u6210\u672c\u5e76\u672a\u589e\u52a0\u3002\u63d0\u4f9b\u9009\u62e9\u65b9\u6848\u7684\u8868\u73b0\u4e0e\u57fa\u4e8e\u5927\u91cf\u53ef\u89c2\u5bdf\u53d8\u91cf\u8fdb\u884c\u4e2a\u6027\u5316\u7684\u6548\u679c\u76f8\u5f53\uff0c\u4f46\u65e0\u9700\u76f8\u540c\u7684\u6570\u636e\u8981\u6c42\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta20608", "journal": "ECTA", "title": "Coordination and Commitment in International Climate Action: Evidence From Palm Oil", "authors": ["Allan Hsiao"], "author_details": [{"name": "Allan Hsiao", "affiliations": ["Department of Economics, Stanford University"]}], "abstract": "Weak environmental regulation has global consequences. When domestic regulation fails, the international community can target emitters with trade policy. I develop a dynamic empirical framework for evaluating trade policy as a substitute for domestic regulation, and I apply the framework to the market for palm oil, a major driver of deforestation and global CO 2 emissions. Relative to business as usual, a domestic production tax of 50% reduces CO 2 emissions by 7.4 Gt from 1988 to 2016, amounting to 0.26 Gt annually. Coordinated, committed import tariffs of similar magnitude reduce emissions by 5.4 Gt over the same period. The cost of these import tariffs is only $15 per ton of CO 2 , even accounting for compensating transfers that recognize welfare losses for producing countries. Without coordination and commitment, import tariffs have more limited effects. Alternative policies include domestic export taxes, which are fiscally appealing independent of emission concerns, and a carbon border adjustment mechanism, which encourages domestic regulation.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta20608", "title_zh": "\u56fd\u9645\u6c14\u5019\u884c\u52a8\u4e2d\u7684\u534f\u8c03\u4e0e\u627f\u8bfa\uff1a\u6765\u81ea\u68d5\u6988\u6cb9\u5e02\u573a\u7684\u8bc1\u636e", "abstract_zh": "\u73af\u5883\u76d1\u7ba1\u8584\u5f31\u5177\u6709\u5168\u7403\u6027\u540e\u679c\u3002\u5f53\u56fd\u5185\u76d1\u7ba1\u5931\u6548\u65f6\uff0c\u56fd\u9645\u793e\u4f1a\u53ef\u4ee5\u901a\u8fc7\u8d38\u6613\u653f\u7b56\u9488\u5bf9\u6392\u653e\u6e90\u8fdb\u884c\u5e72\u9884\u3002\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u52a8\u6001\u7ecf\u9a8c\u6846\u67b6\uff0c\u7528\u4e8e\u8bc4\u4f30\u8d38\u6613\u653f\u7b56\u4f5c\u4e3a\u56fd\u5185\u76d1\u7ba1\u66ff\u4ee3\u65b9\u6848\u7684\u6709\u6548\u6027\uff0c\u5e76\u5c06\u8be5\u6846\u67b6\u5e94\u7528\u4e8e\u68d5\u6988\u6cb9\u5e02\u573a\uff0c\u8be5\u5e02\u573a\u662f\u5bfc\u81f4\u68ee\u6797\u780d\u4f10\u548c\u5168\u7403\u4e8c\u6c27\u5316\u78b3\u6392\u653e\u7684\u4e3b\u8981\u9a71\u52a8\u56e0\u7d20\u4e4b\u4e00\u3002\u76f8\u8f83\u4e8e\u4e1a\u52a1\u5e38\u6001\uff0c\u56fd\u5185\u751f\u4ea7\u7a0e\u63d0\u9ad850%\u53ef\u4f7f1988\u5e74\u81f32016\u5e74\u95f4\u4e8c\u6c27\u5316\u78b3\u6392\u653e\u51cf\u5c117.4\u5409\u5428\uff0c\u5373\u6bcf\u5e74\u51cf\u5c110.26\u5409\u5428\u3002\u76f8\u4f3c\u89c4\u6a21\u7684\u534f\u8c03\u4e14\u5177\u6709\u627f\u8bfa\u7684\u8fdb\u53e3\u5173\u7a0e\u53ef\u4f7f\u540c\u671f\u6392\u653e\u51cf\u5c115.4\u5409\u5428\u3002\u8fd9\u4e9b\u8fdb\u53e3\u5173\u7a0e\u7684\u6210\u672c\u4ec5\u4e3a\u6bcf\u5428\u4e8c\u6c27\u5316\u78b315\u7f8e\u5143\uff0c\u5373\u4f7f\u8003\u8651\u5bf9\u751f\u4ea7\u56fd\u9020\u6210\u7684\u798f\u5229\u635f\u5931\u8fdb\u884c\u8865\u507f\u8f6c\u79fb\u3002\u5728\u7f3a\u4e4f\u534f\u8c03\u548c\u627f\u8bfa\u7684\u60c5\u51b5\u4e0b\uff0c\u8fdb\u53e3\u5173\u7a0e\u7684\u51cf\u6392\u6548\u679c\u66f4\u4e3a\u6709\u9650\u3002\u5176\u4ed6\u653f\u7b56\u9009\u62e9\u5305\u62ec\u56fd\u5185\u51fa\u53e3\u7a0e\uff0c\u8fd9\u79cd\u653f\u7b56\u5728\u8d22\u653f\u4e0a\u5177\u6709\u5438\u5f15\u529b\uff0c\u4e14\u4e0d\u4f9d\u8d56\u4e8e\u51cf\u6392\u76ee\u6807\uff0c\u4ee5\u53ca\u78b3\u8fb9\u5883\u8c03\u8282\u673a\u5236\uff0c\u8be5\u673a\u5236\u6709\u52a9\u4e8e\u63a8\u52a8\u56fd\u5185\u76d1\u7ba1\u7684\u5b9e\u65bd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.3982/ecta22486", "journal": "ECTA", "title": "Optimally\u2010Transported Generalized Method of Moments", "authors": ["Susanne Schennach", "Vincent Starck"], "author_details": [{"name": "Susanne Schennach", "affiliations": ["Economics Department, Brown University"]}, {"name": "Vincent Starck", "affiliations": ["Department of Statistics, LMU Munich"]}], "abstract": "We propose a novel optimal transport\u2010based version of the Generalized Method of Moment (GMM). Instead of handling overidentification by reweighting the data to satisfy the moment conditions (as in Generalized Empirical Likelihood methods), this method proceeds by allowing for errors in the variables of the least mean\u2010square magnitude necessary to simultaneously satisfy all moment conditions. This approach, based on the notions of optimal transport and Wasserstein metric, aims to address the problem of assigning a logical interpretation to GMM results even when overidentification tests reject the null, a situation that cannot always be avoided in applications. We illustrate the method by revisiting Duranton, Morrow and Turner's (2014) study of the relationship between a city's exports and the extent of its transportation infrastructure. Our results corroborate theirs under weaker assumptions and provide insight into the error structure of the variables.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22486", "title_zh": "\u6700\u4f18\u4f20\u8f93\u5e7f\u4e49\u77e9\u6cd5", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u57fa\u4e8e\u6700\u4f18\u4f20\u8f93\u7684\u5e7f\u4e49\u77e9\u6cd5\uff08GMM\uff09\u7684\u65b0\u7248\u672c\u3002\u4e0e\u4f20\u7edf\u7684\u5e7f\u4e49\u7ecf\u9a8c\u4f3c\u7136\u65b9\u6cd5\u901a\u8fc7\u91cd\u65b0\u52a0\u6743\u6570\u636e\u4ee5\u6ee1\u8db3\u77e9\u6761\u4ef6\u4e0d\u540c\uff0c\u672c\u65b9\u6cd5\u5141\u8bb8\u5f15\u5165\u6700\u5c0f\u5747\u65b9\u8bef\u5dee\uff0c\u4ee5\u540c\u65f6\u6ee1\u8db3\u6240\u6709\u77e9\u6761\u4ef6\u3002\u8be5\u65b9\u6cd5\u57fa\u4e8e\u6700\u4f18\u4f20\u8f93\u548c\u74e6\u745f\u65af\u5766\u5ea6\u91cf\u7684\u7406\u8bba\uff0c\u65e8\u5728\u89e3\u51b3\u5f53\u8fc7\u5ea6\u8bc6\u522b\u68c0\u9a8c\u62d2\u7edd\u539f\u5047\u8bbe\u65f6\uff0c\u5982\u4f55\u4e3aGMM\u7ed3\u679c\u8d4b\u4e88\u5408\u7406\u89e3\u91ca\u7684\u95ee\u9898\uff0c\u8fd9\u79cd\u60c5\u51b5\u5728\u5b9e\u9645\u5e94\u7528\u4e2d\u5f80\u5f80\u96be\u4ee5\u907f\u514d\u3002\u6211\u4eec\u901a\u8fc7\u91cd\u65b0\u5ba1\u89c6Duranton\u3001Morrow\u548cTurner\uff082014\uff09\u5173\u4e8e\u57ce\u5e02\u51fa\u53e3\u4e0e\u5176\u4ea4\u901a\u8fd0\u8f93\u57fa\u7840\u8bbe\u65bd\u7a0b\u5ea6\u5173\u7cfb\u7684\u7814\u7a76\u6765\u8bf4\u660e\u8be5\u65b9\u6cd5\u3002\u6211\u4eec\u7684\u7ed3\u679c\u5728\u66f4\u5f31\u7684\u5047\u8bbe\u4e0b\u652f\u6301\u4e86\u4ed6\u4eec\u7684\u7ed3\u8bba\uff0c\u5e76\u63d0\u4f9b\u4e86\u5bf9\u53d8\u91cf\u8bef\u5dee\u7ed3\u6784\u7684\u6d1e\u5bdf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22542", "journal": "ECTA", "title": "Job Ladder and Wealth Dynamics in General Equilibrium", "authors": ["Leo Kaas", "Etienne Lal\u00e9", "Nawid Siassi"], "author_details": [{"name": "Leo Kaas", "affiliations": ["Department of Economics, European University Institute"]}, {"name": "Etienne Lal\u00e9", "affiliations": ["Department of Economics, York University"]}, {"name": "Nawid Siassi", "affiliations": ["Institute of Statistics and Mathematical Methods in Economics, TU Wien"]}], "abstract": "This paper develops a macroeconomic model that combines an incomplete\u2010markets overlapping\u2010generations economy with a job ladder featuring sequential wage bargaining, endogenous search effort of employed and non\u2010employed workers, and differences in match quality. With these ingredients, our model provides a joint microfoundation for the three main inputs in aggregate production: capital, employment, and labor efficiency. The calibrated model offers a good fit to the empirical age profiles of search activity, job\u2010finding rates, wages, and savings. We use the model to analyze the impact of tax and transfer policies for labor market dynamics and aggregate economic activity via capital, employment, and labor efficiency channels. Lower unemployment benefits and a less progressive tax schedule bring about welfare losses for a newborn worker which are mainly driven by higher consumption risk and costlier search effort; both policies have differential effects along the age, income, and wealth dimensions.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22542", "title_zh": "\u804c\u4e1a\u9636\u68af\u4e0e\u4e00\u822c\u5747\u8861\u4e0b\u7684\u8d22\u5bcc\u52a8\u6001", "abstract_zh": "\u672c\u6587\u6784\u5efa\u4e86\u4e00\u4e2a\u5b8f\u89c2\u7ecf\u6d4e\u6a21\u578b\uff0c\u5c06\u4e0d\u5b8c\u5168\u5e02\u573a\u4e0b\u7684\u91cd\u53e0\u4e16\u4ee3\u7ecf\u6d4e\u4e0e\u5305\u542b\u5e8f\u8d2f\u5de5\u8d44\u8c08\u5224\u3001\u96c7\u5458\u53ca\u5931\u4e1a\u5de5\u4eba\u5185\u751f\u641c\u5bfb\u52aa\u529b\u4ee5\u53ca\u5339\u914d\u8d28\u91cf\u5dee\u5f02\u7684\u804c\u4e1a\u9636\u68af\u76f8\u7ed3\u5408\u3002\u901a\u8fc7\u8fd9\u4e9b\u8981\u7d20\uff0c\u672c\u6a21\u578b\u4e3a\u603b\u4ea7\u51fa\u7684\u4e09\u5927\u7ec4\u6210\u90e8\u5206\u2014\u2014\u8d44\u672c\u3001\u5c31\u4e1a\u548c\u52b3\u52a8\u6548\u7387\u2014\u2014\u63d0\u4f9b\u4e86\u7edf\u4e00\u7684\u5fae\u89c2\u57fa\u7840\u3002\u6821\u51c6\u540e\u7684\u6a21\u578b\u80fd\u591f\u5f88\u597d\u5730\u62df\u5408\u641c\u5bfb\u6d3b\u52a8\u3001\u5c31\u4e1a\u53d1\u73b0\u7387\u3001\u5de5\u8d44\u548c\u50a8\u84c4\u7684\u5e74\u9f84\u5206\u5e03\u7279\u5f81\u3002\u6211\u4eec\u5229\u7528\u8be5\u6a21\u578b\u5206\u6790\u7a0e\u6536\u548c\u8f6c\u79fb\u652f\u4ed8\u653f\u7b56\u5bf9\u52b3\u52a8\u529b\u5e02\u573a\u52a8\u6001\u53ca\u603b\u4f53\u7ecf\u6d4e\u6d3b\u52a8\u7684\u5f71\u54cd\uff0c\u901a\u8fc7\u8d44\u672c\u3001\u5c31\u4e1a\u548c\u52b3\u52a8\u6548\u7387\u7684\u4f20\u5bfc\u8def\u5f84\u3002\u964d\u4f4e\u5931\u4e1a\u6551\u6d4e\u91d1\u548c\u4f7f\u7a0e\u6536\u5236\u5ea6\u66f4\u4e0d\u8fdb\u6b65\u7684\u653f\u7b56\uff0c\u4f1a\u4f7f\u5f97\u65b0\u751f\u513f\u52b3\u52a8\u8005\u9762\u4e34\u798f\u5229\u635f\u5931\uff0c\u5176\u4e3b\u8981\u539f\u56e0\u662f\u6d88\u8d39\u98ce\u9669\u4e0a\u5347\u548c\u641c\u5bfb\u6210\u672c\u589e\u52a0\uff1b\u8fd9\u4e24\u9879\u653f\u7b56\u5728\u5e74\u9f84\u3001\u6536\u5165\u548c\u8d22\u5bcc\u7ef4\u5ea6\u4e0a\u5177\u6709\u5dee\u5f02\u6027\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta24284", "journal": "ECTA", "title": "Genetic Prediction and Adverse Selection", "authors": ["Eduardo Azevedo", "Jonathan P. Beauchamp", "Richard Karlsson Linn\u00e9r"], "author_details": [{"name": "Eduardo Azevedo", "affiliations": ["The Wharton School, University of Pennsylvania"]}, {"name": "Jonathan P. Beauchamp", "affiliations": ["Interdisciplinary Center for Economic Science and Department of Economics, George Mason University"]}, {"name": "Richard Karlsson Linn\u00e9r", "affiliations": ["Department of Economics, Leiden University"]}], "abstract": "Recent advances have substantially improved our ability to predict disease risk with genetic data. In response, many countries have banned insurers from using genetic data, despite concerns about adverse selection. This paper measures adverse selection in a market where insurers can underwrite only on nongenetic information while consumers also have access to genetic information. We do so by combining methods from quantitative genetics, selection measures from economic theory, and genetic and electronic health record data on nearly 500,000 individuals in the UK Biobank. We focus on the critical illness insurance market and consider scenarios in which consumers have access to current or expected future genetic prediction technology. We find noticeable levels of selection with current prediction technology, and potentially crippling selection with expected future technology.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta24284", "title_zh": "\u57fa\u56e0\u9884\u6d4b\u4e0e\u9006\u5411\u9009\u62e9", "abstract_zh": "\u8fd1\u5e74\u6765\uff0c\u57fa\u4e8e\u9057\u4f20\u6570\u636e\u7684\u75be\u75c5\u98ce\u9669\u9884\u6d4b\u80fd\u529b\u53d6\u5f97\u4e86\u663e\u8457\u8fdb\u6b65\u3002\u5bf9\u6b64\uff0c\u8bb8\u591a\u56fd\u5bb6\u5df2\u7981\u6b62\u4fdd\u9669\u516c\u53f8\u4f7f\u7528\u9057\u4f20\u6570\u636e\uff0c\u5c3d\u7ba1\u5b58\u5728\u9006\u5411\u9009\u62e9\u7684\u62c5\u5fe7\u3002\u672c\u6587\u5728\u4fdd\u9669\u516c\u53f8\u4ec5\u80fd\u57fa\u4e8e\u975e\u9057\u4f20\u4fe1\u606f\u8fdb\u884c\u627f\u4fdd\u3001\u800c\u6d88\u8d39\u8005\u540c\u65f6\u62e5\u6709\u9057\u4f20\u4fe1\u606f\u7684\u5e02\u573a\u4e2d\uff0c\u6d4b\u91cf\u4e86\u9006\u5411\u9009\u62e9\u7684\u7a0b\u5ea6\u3002\u6211\u4eec\u7ed3\u5408\u5b9a\u91cf\u9057\u4f20\u5b66\u65b9\u6cd5\u3001\u7ecf\u6d4e\u5b66\u4e2d\u7684\u9009\u62e9\u5ea6\u91cf\u65b9\u6cd5\uff0c\u4ee5\u53ca\u82f1\u56fd\u751f\u7269\u94f6\u884c\u8fd150\u4e07\u540d\u4e2a\u4f53\u7684\u9057\u4f20\u548c\u7535\u5b50\u5065\u5eb7\u8bb0\u5f55\u6570\u636e\uff0c\u805a\u7126\u4e8e\u91cd\u5927\u75be\u75c5\u4fdd\u9669\u5e02\u573a\uff0c\u5e76\u8003\u8651\u6d88\u8d39\u8005\u5728\u5f53\u524d\u6216\u672a\u6765\u9884\u671f\u7684\u57fa\u56e0\u9884\u6d4b\u6280\u672f\u4e0b\u7684\u4e0d\u540c\u60c5\u5f62\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5f53\u524d\u57fa\u56e0\u9884\u6d4b\u6280\u672f\u5df2\u5bfc\u81f4\u660e\u663e\u7684\u9006\u5411\u9009\u62e9\uff0c\u800c\u672a\u6765\u9884\u671f\u7684\u57fa\u56e0\u9884\u6d4b\u6280\u672f\u53ef\u80fd\u5f15\u53d1\u707e\u96be\u6027\u7684\u9006\u5411\u9009\u62e9\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23622", "journal": "ECTA", "title": "Multidimensional Screening With Precise Seller Information", "authors": ["Mira Frick", "Ryota Iijima", "Yuhta Ishii"], "author_details": [{"name": "Mira Frick", "affiliations": ["Department of Economics, Princeton University"]}, {"name": "Ryota Iijima", "affiliations": ["Department of Economics, Princeton University"]}, {"name": "Yuhta Ishii", "affiliations": ["Department of Economics, Pennsylvania State University"]}], "abstract": "A multi\u2010product monopolist faces a buyer who is privately informed about his valuations for the goods. As is well known, optimal mechanisms are in general complicated, while simple mechanisms\u2014such as pure bundling or separate sales\u2014can be far from optimal and do not admit clear\u2010cut comparisons. We show that this changes if the monopolist has sufficiently precise information about the buyer's valuations: Now, pure bundling always outperforms separate sales; moreover, there is a sense in which pure bundling performs essentially as well as the optimal mechanism. To formalize this, we characterize how fast the corresponding revenues converge to the first\u2010best revenue as the monopolist's information grows precise: Pure bundling achieves the same convergence rate to the first\u2010best as optimal mechanisms; in contrast, the convergence rate under separate sales is suboptimal.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23622", "title_zh": "\u5177\u6709\u7cbe\u786e\u5356\u65b9\u4fe1\u606f\u7684\u591a\u7ef4\u7b5b\u9009", "abstract_zh": "\u4e00\u4e2a\u591a\u4ea7\u54c1\u5784\u65ad\u8005\u9762\u5bf9\u4e00\u4e2a\u5bf9\u5176\u5546\u54c1\u4f30\u503c\u5b58\u5728\u79c1\u4eba\u4fe1\u606f\u7684\u4e70\u5bb6\u3002\u4f17\u6240\u5468\u77e5\uff0c\u6700\u4f18\u673a\u5236\u901a\u5e38\u975e\u5e38\u590d\u6742\uff0c\u800c\u7b80\u5355\u7684\u673a\u5236\u2014\u2014\u4f8b\u5982\u7eaf\u6346\u7ed1\u9500\u552e\u6216\u5355\u72ec\u9500\u552e\u2014\u2014\u5f80\u5f80\u8fdc\u4e0d\u5982\u6700\u4f18\u673a\u5236\uff0c\u5e76\u4e14\u7f3a\u4e4f\u660e\u786e\u7684\u6bd4\u8f83\u3002\u7136\u800c\uff0c\u5f53\u5784\u65ad\u8005\u5bf9\u4e70\u5bb6\u4f30\u503c\u62e5\u6709\u8db3\u591f\u7cbe\u786e\u7684\u4fe1\u606f\u65f6\uff0c\u8fd9\u4e00\u60c5\u51b5\u4f1a\u53d1\u751f\u6539\u53d8\uff1a\u7eaf\u6346\u7ed1\u9500\u552e\u59cb\u7ec8\u4f18\u4e8e\u5355\u72ec\u9500\u552e\uff1b\u800c\u4e14\u4ece\u67d0\u79cd\u610f\u4e49\u4e0a\u8bf4\uff0c\u7eaf\u6346\u7ed1\u9500\u552e\u7684\u6027\u80fd\u51e0\u4e4e\u4e0e\u6700\u4f18\u673a\u5236\u76f8\u5f53\u3002\u4e3a\u4e86\u5f62\u5f0f\u5316\u8fd9\u4e00\u70b9\uff0c\u6211\u4eec\u523b\u753b\u4e86\u5f53\u5784\u65ad\u8005\u5bf9\u4e70\u5bb6\u4fe1\u606f\u7684\u7cbe\u786e\u5ea6\u63d0\u5347\u65f6\uff0c\u76f8\u5e94\u6536\u76ca\u8d8b\u8fd1\u4e8e\u7b2c\u4e00\u6700\u4f73\u6536\u76ca\u7684\u901f\u5ea6\uff1a\u7eaf\u6346\u7ed1\u9500\u552e\u8fbe\u5230\u7b2c\u4e00\u6700\u4f73\u6536\u76ca\u7684\u6536\u655b\u901f\u5ea6\u4e0e\u6700\u4f18\u673a\u5236\u76f8\u540c\uff1b\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u5355\u72ec\u9500\u552e\u7684\u6536\u655b\u901f\u5ea6\u662f\u6b21\u4f18\u7684\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23049", "journal": "ECTA", "title": "Dynamic Screening of Buyers With Heterogeneous Purchase Frequency", "authors": ["Johannes H\u00f6rner", "Anna Sanktjohanser"], "author_details": [{"name": "Johannes H\u00f6rner", "affiliations": ["CNRS, Department of Economics, Toulouse School of Economics"]}, {"name": "Anna Sanktjohanser", "affiliations": ["Department of Economics, Toulouse School of Economics"]}], "abstract": "We consider a dynamic buyer\u2013seller interaction. Instead of the buyer's valuation, it is the frequency with which he needs to trade that is the buyer's private information. The difference matters. With commitment, full surplus extraction is possible, for instance via limited\u2010time offers. Without commitment, ratcheting is mitigated, as not buying is not necessarily a sign of strength. Because time is informative, the seller learns and may adjust her behavior over time. When finding a suitable alternative seller is easy, she starts with a pooling offer before permanently switching to a screening offer. When finding a suitable alternative seller takes time, she starts with a pooling offer before occasionally experimenting with separating offers.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23049", "title_zh": "\u5177\u6709\u5f02\u8d28\u8d2d\u4e70\u9891\u7387\u7684\u4e70\u5bb6\u52a8\u6001\u7b5b\u9009", "abstract_zh": "\u6211\u4eec\u8003\u8651\u4e00\u4e2a\u52a8\u6001\u7684\u4e70\u65b9-\u5356\u65b9\u4e92\u52a8\u3002\u4e0e\u4e70\u65b9\u7684\u4f30\u503c\u4e0d\u540c\uff0c\u662f\u5176\u9700\u8981\u4ea4\u6613\u7684\u9891\u7387\u8fd9\u4e00\u4fe1\u606f\u4f5c\u4e3a\u4e70\u65b9\u7684\u79c1\u6709\u4fe1\u606f\u3002\u8fd9\u4e00\u70b9\u81f3\u5173\u91cd\u8981\u3002\u5728\u6709\u627f\u8bfa\u7684\u60c5\u51b5\u4e0b\uff0c\u53ef\u4ee5\u901a\u8fc7\u9650\u65f6\u62a5\u4ef7\u7b49\u65b9\u5f0f\u5b9e\u73b0\u5b8c\u5168\u5269\u4f59\u63d0\u53d6\u3002\u5728\u6ca1\u6709\u627f\u8bfa\u7684\u60c5\u51b5\u4e0b\uff0c\u9012\u589e\u73b0\u8c61\u88ab\u7f13\u89e3\uff0c\u56e0\u4e3a\u4e0d\u8d2d\u4e70\u5e76\u4e0d\u4e00\u5b9a\u8868\u660e\u4e70\u65b9\u5b9e\u529b\u5f3a\u3002\u7531\u4e8e\u65f6\u95f4\u5177\u6709\u4fe1\u606f\u6027\uff0c\u5356\u65b9\u80fd\u591f\u5b66\u4e60\u5e76\u968f\u7740\u65f6\u95f4\u8c03\u6574\u5176\u884c\u4e3a\u3002\u5f53\u627e\u5230\u5408\u9002\u7684\u66ff\u4ee3\u5356\u65b9\u5bb9\u6613\u65f6\uff0c\u5979\u4f1a\u5148\u63d0\u4f9b\u5408\u5e76\u62a5\u4ef7\uff0c\u7136\u540e\u6c38\u4e45\u8f6c\u5411\u7b5b\u9009\u62a5\u4ef7\uff1b\u5f53\u627e\u5230\u5408\u9002\u7684\u66ff\u4ee3\u5356\u65b9\u8017\u65f6\u8f83\u957f\u65f6\uff0c\u5979\u4f1a\u5148\u63d0\u4f9b\u5408\u5e76\u62a5\u4ef7\uff0c\u7136\u540e\u5076\u5c14\u5c1d\u8bd5\u4f7f\u7528\u5206\u79bb\u62a5\u4ef7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta20884", "journal": "ECTA", "title": "Physician Behavior in the Presence of a Secondary Market: The Case of Prescription Opioids", "authors": ["Molly Schnell"], "author_details": [{"name": "Molly Schnell", "affiliations": ["Department of Economics, Northwestern University", "NBER"]}], "abstract": "This paper examines how drug diversion influences the prescribing practices of physicians and the equilibrium health impacts of prescription medications. Focusing on the case of prescription opioids, a commonly prescribed and frequently diverted medication at the heart of the worst drug crisis in U.S. history, I design and estimate a model of physician behavior in the presence of a secondary market with patient search. To access prescription opioids for medical purposes or misuse, patients search over physicians on the legal primary market or turn to an illegal secondary market. Physicians, who care both about their impact on population health and their revenue from office visits, take into account the possibility that patients might resell their prescriptions on the secondary market when prescribing. The model demonstrates that the potential for diversion will tend to make strict physicians more hesitant in their prescribing while leading lenient prescribers to loosen their prescription thresholds, thereby exacerbating prescribing differences between more and less lenient physicians. Estimates reveal that the presence of a secondary market induces most physicians to be more careful in their prescribing, which brings prescriptions closer to their optimal level, but also causes harm through the reallocation of prescriptions for abuse.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta20884", "title_zh": "\u5728\u5b58\u5728\u4e8c\u7ea7\u5e02\u573a\u7684\u6761\u4ef6\u4e0b\u533b\u751f\u7684\u884c\u4e3a\uff1a\u4ee5\u5904\u65b9\u963f\u7247\u7c7b\u836f\u7269\u4e3a\u4f8b", "abstract_zh": "\u672c\u6587\u7814\u7a76\u836f\u7269\u6ee5\u7528\u5982\u4f55\u5f71\u54cd\u533b\u751f\u7684\u5904\u65b9\u884c\u4e3a\u4ee5\u53ca\u5904\u65b9\u836f\u7269\u5bf9\u6574\u4f53\u5065\u5eb7\u7684\u5f71\u54cd\u3002\u4ee5\u5904\u65b9\u963f\u7247\u7c7b\u836f\u7269\u4e3a\u4f8b\uff0c\u8fd9\u7c7b\u836f\u7269\u662f\u7f8e\u56fd\u5386\u53f2\u4e0a\u6700\u4e25\u91cd\u7684\u836f\u7269\u5371\u673a\u7684\u6838\u5fc3\uff0c\u5e38\u5e38\u88ab\u6ee5\u7528\u3002\u6211\u6784\u5efa\u5e76\u4f30\u8ba1\u4e86\u4e00\u4e2a\u5728\u5b58\u5728\u4e8c\u7ea7\u5e02\u573a\u4e14\u60a3\u8005\u8fdb\u884c\u533b\u751f\u641c\u7d22\u6761\u4ef6\u4e0b\u7684\u533b\u751f\u884c\u4e3a\u6a21\u578b\u3002\u60a3\u8005\u4e3a\u4e86\u83b7\u5f97\u7528\u4e8e\u533b\u7597\u76ee\u7684\u6216\u6ee5\u7528\u7684\u5904\u65b9\u963f\u7247\u7c7b\u836f\u7269\uff0c\u8981\u4e48\u5728\u5408\u6cd5\u7684\u521d\u7ea7\u5e02\u573a\u4e2d\u641c\u7d22\u533b\u751f\uff0c\u8981\u4e48\u8f6c\u5411\u975e\u6cd5\u7684\u4e8c\u7ea7\u5e02\u573a\u3002\u533b\u751f\u65e2\u5173\u5fc3\u5bf9\u4eba\u7fa4\u5065\u5eb7\u7684\u5f71\u54cd\uff0c\u4e5f\u5173\u5fc3\u6765\u81ea\u95e8\u8bca\u5c31\u8bca\u7684\u6536\u5165\uff0c\u56e0\u6b64\u5728\u5f00\u5904\u65b9\u65f6\u4f1a\u8003\u8651\u60a3\u8005\u53ef\u80fd\u5c06\u5904\u65b9\u8f6c\u552e\u5230\u4e8c\u7ea7\u5e02\u573a\u7684\u53ef\u80fd\u6027\u3002\u6a21\u578b\u8868\u660e\uff0c\u6ee5\u7528\u7684\u6f5c\u5728\u98ce\u9669\u4f1a\u4f7f\u4e25\u683c\u6301\u5b88\u89c4\u8303\u7684\u533b\u751f\u5728\u5f00\u5904\u65b9\u65f6\u66f4\u52a0\u72b9\u8c6b\uff0c\u800c\u4f7f\u5bbd\u677e\u7684\u5904\u65b9\u533b\u751f\u964d\u4f4e\u5904\u65b9\u95e8\u69db\uff0c\u4ece\u800c\u52a0\u5267\u4e86\u4e0d\u540c\u4e25\u683c\u7a0b\u5ea6\u533b\u751f\u4e4b\u95f4\u7684\u5904\u65b9\u5dee\u5f02\u3002\u4f30\u8ba1\u7ed3\u679c\u8868\u660e\uff0c\u4e8c\u7ea7\u5e02\u573a\u7684\u5b58\u5728\u4f7f\u5927\u591a\u6570\u533b\u751f\u5728\u5f00\u5904\u65b9\u65f6\u66f4\u52a0\u8c28\u614e\uff0c\u4f7f\u5904\u65b9\u91cf\u66f4\u63a5\u8fd1\u5176\u6700\u4f18\u6c34\u5e73\uff0c\u4f46\u540c\u65f6\u4e5f\u901a\u8fc7\u5c06\u5904\u65b9\u91cd\u65b0\u5206\u914d\u7ed9\u6ee5\u7528\u884c\u4e3a\u5e26\u6765\u4e86\u5371\u5bb3\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22363", "journal": "ECTA", "title": "Screening Property Rights for Innovation", "authors": ["William Matcham", "Mark Schankerman"], "author_details": [{"name": "William Matcham", "affiliations": ["Department of Economics, Royal Holloway University of London"]}, {"name": "Mark Schankerman", "affiliations": ["Department of Economics, London School of Economics", "CEPR"]}], "abstract": "We develop a dynamic structural model of patent screening incorporating incentives, intrinsic motivation, and multiround negotiation. We use natural language processing to create a measure of patent distance, which together with detailed data on examiner decisions, enables us to estimate the model and study strategic decisions by applicants and examiners. Using the estimated model, we quantify the effectiveness of the U.S. Patent Office and evaluate counterfactual policy reforms. We find that patent screening is moderately effective, given the existing standards for patentability. Examiners exhibit substantial intrinsic motivation that strongly improves screening quality. We quantify the annual social costs of patent screening at $15.38bn, equivalent to 5% of total private sector R&D in the U.S. and show that reforms limiting the number of rounds of negotiation significantly reduce social costs.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22363", "title_zh": "\u521b\u65b0\u4e2d\u7684\u4ea7\u6743\u7b5b\u9009", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u52a8\u6001\u7ed3\u6784\u6a21\u578b\uff0c\u7528\u4e8e\u7eb3\u5165\u4e13\u5229\u7b5b\u9009\u4e2d\u7684\u6fc0\u52b1\u673a\u5236\u3001\u5185\u5728\u52a8\u673a\u4ee5\u53ca\u591a\u8f6e\u8c08\u5224\u8fc7\u7a0b\u3002\u6211\u4eec\u5229\u7528\u81ea\u7136\u8bed\u8a00\u5904\u7406\u6280\u672f\u521b\u5efa\u4e86\u4e00\u9879\u4e13\u5229\u8ddd\u79bb\u7684\u8861\u91cf\u6307\u6807\uff0c\u5e76\u7ed3\u5408\u5ba1\u67e5\u5458\u51b3\u7b56\u7684\u8be6\u7ec6\u6570\u636e\uff0c\u5bf9\u6a21\u578b\u8fdb\u884c\u4f30\u8ba1\uff0c\u7814\u7a76\u7533\u8bf7\u4eba\u548c\u5ba1\u67e5\u5458\u7684\u6218\u7565\u51b3\u7b56\u3002\u57fa\u4e8e\u4f30\u8ba1\u7684\u6a21\u578b\uff0c\u6211\u4eec\u91cf\u5316\u4e86\u7f8e\u56fd\u4e13\u5229\u5c40\u7684\u7b5b\u9009\u6709\u6548\u6027\uff0c\u5e76\u8bc4\u4f30\u4e86\u82e5\u5e72\u53cd\u4e8b\u5b9e\u653f\u7b56\u6539\u9769\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5728\u73b0\u6709\u4e13\u5229\u53ef\u4e13\u5229\u6027\u6807\u51c6\u4e0b\uff0c\u4e13\u5229\u7b5b\u9009\u5177\u6709\u4e2d\u7b49\u6709\u6548\u6027\u3002\u5ba1\u67e5\u5458\u8868\u73b0\u51fa\u663e\u8457\u7684\u5185\u5728\u52a8\u673a\uff0c\u8fd9\u6781\u5927\u5730\u63d0\u5347\u4e86\u7b5b\u9009\u8d28\u91cf\u3002\u6211\u4eec\u8ba1\u7b97\u51fa\u4e13\u5229\u7b5b\u9009\u6bcf\u5e74\u7684\u793e\u4f1a\u6210\u672c\u4e3a153.8\u4ebf\u7f8e\u5143\uff0c\u76f8\u5f53\u4e8e\u7f8e\u56fd\u79c1\u8425\u90e8\u95e8\u7814\u53d1\u652f\u51fa\u76845%\uff0c\u5e76\u53d1\u73b0\u9650\u5236\u8c08\u5224\u8f6e\u6b21\u6570\u91cf\u7684\u6539\u9769\u80fd\u663e\u8457\u964d\u4f4e\u793e\u4f1a\u6210\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790"]}, {"doi": "10.3982/ecta22570", "journal": "ECTA", "title": "Equilibrium Existence in First\u2010Price Auctions With Private Values", "authors": ["Wojciech Olszewski", "Philip J. Reny", "Ron Siegel"], "author_details": [{"name": "Wojciech Olszewski", "affiliations": ["Department of Economics, Northwestern University"]}, {"name": "Philip J. Reny", "affiliations": ["Department of Economics, University of Chicago"]}, {"name": "Ron Siegel", "affiliations": ["Department of Economics, The Pennsylvania State University"]}], "abstract": "We provide sufficient conditions for equilibrium existence in first\u2010price auctions with private values that accommodate non quasi\u2010linear utilities and value\u2010distributions that contain atoms and exhibit positive or negative correlation. These conditions show that equilibrium existence often turns on properties of a single statistic of the joint distribution of values, namely, the minimum value in the support of the high\u2010value distribution (the mHV). We also show that modifying the standard tie\u2010breaking rule only at the mHV is enough to guarantee equilibrium existence without our sufficient conditions. Our results also apply to Bertrand price competition when each firm's constant marginal cost is private information.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22570", "title_zh": "\u5177\u6709\u79c1\u4eba\u4ef7\u503c\u7684\u7b2c\u4e00\u6b21\u62cd\u5356\u4e2d\u5747\u8861\u5b58\u5728\u7684\u6761\u4ef6", "abstract_zh": "\u6211\u4eec\u4e3a\u5177\u6709\u975e\u51c6\u7ebf\u6027\u6548\u7528\u548c\u5305\u542b\u539f\u5b50\u4e14\u8868\u73b0\u51fa\u6b63\u8d1f\u76f8\u5173\u6027\u7684\u4ef7\u503c\u5206\u5e03\u7684\u7b2c\u4e00\u6b21\u62cd\u5356\u4e2d\u5747\u8861\u5b58\u5728\u7684\u5145\u5206\u6761\u4ef6\u63d0\u4f9b\u4e86\u8bf4\u660e\u3002\u8fd9\u4e9b\u6761\u4ef6\u8868\u660e\uff0c\u5747\u8861\u7684\u5b58\u5728\u5f80\u5f80\u53d6\u51b3\u4e8e\u8054\u5408\u4ef7\u503c\u5206\u5e03\u652f\u6301\u96c6\u5185\u9ad8\u4ef7\u503c\u5206\u5e03\u7684\u6700\u5c0f\u503c\uff08\u5373mHV\uff09\u8fd9\u4e00\u7edf\u8ba1\u91cf\u7684\u6027\u8d28\u3002\u6211\u4eec\u8fd8\u8bc1\u660e\uff0c\u4ec5\u5728mHV\u5904\u4fee\u6539\u6807\u51c6\u7684\u5e73\u5c40\u5904\u7406\u89c4\u5219\uff0c\u5c31\u8db3\u4ee5\u5728\u4e0d\u4f9d\u8d56\u6211\u4eec\u5145\u5206\u6761\u4ef6\u7684\u60c5\u51b5\u4e0b\u4fdd\u8bc1\u5747\u8861\u5b58\u5728\u3002\u6211\u4eec\u7684\u7ed3\u679c\u4e5f\u9002\u7528\u4e8e\u5f53\u5404\u4f01\u4e1a\u7684\u5e38\u6570\u8fb9\u9645\u6210\u672c\u4e3a\u79c1\u4eba\u4fe1\u606f\u7684\u4f2f\u7279\u5170\u4ef7\u683c\u7ade\u4e89\u60c5\u5f62\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23206", "journal": "ECTA", "title": "A Framework for Geoeconomics", "authors": ["Christopher Clayton", "Matteo Maggiori", "Jesse Schreger"], "author_details": [{"name": "Christopher Clayton", "affiliations": ["School of Management, Yale University"]}, {"name": "Matteo Maggiori", "affiliations": ["Graduate School of Business, Stanford University"]}, {"name": "Jesse Schreger", "affiliations": ["Economics Division, Columbia Business School"]}], "abstract": "Governments use their countries' economic strength from financial and trade relationships to achieve geopolitical and economic goals. We provide a model of the sources of geoeconomic power and how it is wielded. The source of this power is the ability of a hegemonic country to coordinate threats across disparate economic relationships as a means of enforcement on foreign entities. The hegemon wields this power to demand costly actions out of the targeted entities, including mark\u2010ups, import restrictions, tariffs, and political concessions. The hegemon uses its power to change targeted entities' activities to manipulate the global equilibrium in its favor and increase its power. A sector is strategic either in helping the hegemon form threats or in manipulating the world equilibrium via input\u2010output amplification. The hegemon acts a global enforcer, thus adding value to the world economy, but destroys value by distorting the equilibrium in its favor.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23206", "title_zh": "\u5730\u7f18\u7ecf\u6d4e\u5b66\u6846\u67b6", "abstract_zh": "\u5404\u56fd\u653f\u5e9c\u5229\u7528\u5176\u5728\u91d1\u878d\u548c\u8d38\u6613\u5173\u7cfb\u4e2d\u7684\u7ecf\u6d4e\u5b9e\u529b\uff0c\u4ee5\u5b9e\u73b0\u5730\u7f18\u653f\u6cbb\u548c\u7ecf\u6d4e\u76ee\u6807\u3002\u672c\u6587\u6784\u5efa\u4e86\u4e00\u4e2a\u5173\u4e8e\u5730\u7f18\u7ecf\u6d4e\u529b\u91cf\u6765\u6e90\u53ca\u5176\u8fd0\u7528\u7684\u6a21\u578b\u3002\u8fd9\u79cd\u529b\u91cf\u7684\u6839\u6e90\u5728\u4e8e\u9738\u6743\u56fd\u5bb6\u80fd\u591f\u534f\u8c03\u5176\u4e0d\u540c\u7ecf\u6d4e\u5173\u7cfb\u4e2d\u7684\u5a01\u80c1\uff0c\u4f5c\u4e3a\u5bf9\u5916\u56fd\u5b9e\u4f53\u65bd\u52a0\u7ea6\u675f\u7684\u624b\u6bb5\u3002\u9738\u6743\u56fd\u5bb6\u5229\u7528\u8fd9\u79cd\u529b\u91cf\uff0c\u5411\u76ee\u6807\u5b9e\u4f53\u65bd\u52a0\u6210\u672c\u9ad8\u6602\u7684\u884c\u52a8\u8981\u6c42\uff0c\u5305\u62ec\u4ef7\u683c\u52a0\u6210\u3001\u8fdb\u53e3\u9650\u5236\u3001\u5173\u7a0e\u548c\u653f\u6cbb\u8ba9\u6b65\u3002\u9738\u6743\u56fd\u5bb6\u901a\u8fc7\u6539\u53d8\u76ee\u6807\u5b9e\u4f53\u7684\u884c\u4e3a\uff0c\u64cd\u7eb5\u5168\u7403\u5747\u8861\u4ee5\u5229\u4e8e\u81ea\u8eab\uff0c\u4ece\u800c\u589e\u5f3a\u5176\u6743\u529b\u3002\u67d0\u4e00\u4ea7\u4e1a\u662f\u5426\u5177\u6709\u6218\u7565\u610f\u4e49\uff0c\u53d6\u51b3\u4e8e\u5b83\u662f\u5426\u6709\u52a9\u4e8e\u9738\u6743\u56fd\u5bb6\u5f62\u6210\u5a01\u80c1\uff0c\u6216\u662f\u5426\u901a\u8fc7\u6295\u5165\u4ea7\u51fa\u653e\u5927\u6548\u5e94\u5f71\u54cd\u5168\u7403\u5747\u8861\u3002\u9738\u6743\u56fd\u5bb6\u5145\u5f53\u5168\u7403\u6267\u884c\u8005\uff0c\u56e0\u6b64\u4e3a\u4e16\u754c\u7ecf\u6d4e\u53d1\u5c55\u5e26\u6765\u4ef7\u503c\uff0c\u4f46\u540c\u65f6\u4e5f\u901a\u8fc7\u626d\u66f2\u5747\u8861\u6765\u7834\u574f\u4ef7\u503c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb"]}, {"doi": "10.3982/ecta22935", "journal": "ECTA", "title": "Empirical Bayes When Estimation Precision Predicts Parameters", "authors": ["Jiafeng Chen"], "author_details": [{"name": "Jiafeng Chen", "affiliations": ["Department of Economics, Stanford University"]}], "abstract": "Gaussian empirical Bayes methods usually maintain a precision independence assumption: The unknown parameters of interest are independent from the known standard errors of the estimates. This assumption is often theoretically questionable and empirically rejected. This paper proposes to model the conditional distribution of the parameter given the standard errors as a flexibly parameterized location\u2010scale family of distributions, leading to a family of methods that we call close . The close framework unifies and generalizes several proposals under precision dependence. We argue that the most flexible member of the close family is a minimalist and computationally efficient default for accounting for precision dependence. We analyze this method and show that it is competitive in terms of the regret of subsequent decision rules. Empirically, using close leads to sizable gains for selecting high\u2010mobility Census tracts.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22935", "title_zh": "\u5f53\u4f30\u8ba1\u7cbe\u5ea6\u9884\u6d4b\u53c2\u6570\u65f6\u7684\u7ecf\u9a8c\u8d1d\u53f6\u65af\u65b9\u6cd5", "abstract_zh": "\u9ad8\u65af\u7ecf\u9a8c\u8d1d\u53f6\u65af\u65b9\u6cd5\u901a\u5e38\u5047\u8bbe\u611f\u5174\u8da3\u7684\u672a\u77e5\u53c2\u6570\u4e0e\u5df2\u77e5\u7684\u4f30\u8ba1\u6807\u51c6\u8bef\u5dee\u76f8\u4e92\u72ec\u7acb\u3002\u8fd9\u4e00\u5047\u8bbe\u5728\u7406\u8bba\u4e0a\u5e38\u5e38\u5b58\u7591\uff0c\u5e76\u4e14\u5728\u5b9e\u8bc1\u4e0a\u88ab\u62d2\u7edd\u3002\u672c\u6587\u63d0\u51fa\u5c06\u53c2\u6570\u5728\u5df2\u77e5\u6807\u51c6\u8bef\u5dee\u4e0b\u7684\u6761\u4ef6\u5206\u5e03\u5efa\u6a21\u4e3a\u4e00\u4e2a\u7075\u6d3b\u53c2\u6570\u5316\u7684\u4f4d\u7f6e-\u5c3a\u5ea6\u65cf\u5206\u5e03\uff0c\u4ece\u800c\u5f62\u6210\u4e00\u4e2a\u79f0\u4e3aclose\u7684\u65b9\u6cd5\u5bb6\u65cf\u3002close\u6846\u67b6\u7edf\u4e00\u5e76\u63a8\u5e7f\u4e86\u591a\u79cd\u5173\u4e8e\u7cbe\u5ea6\u4f9d\u8d56\u6027\u7684\u63d0\u8bae\u3002\u6211\u4eec\u8ba4\u4e3a\uff0cclose\u5bb6\u65cf\u4e2d\u6700\u7075\u6d3b\u7684\u6210\u5458\u662f\u4e00\u79cd\u7b80\u6d01\u4e14\u8ba1\u7b97\u6548\u7387\u9ad8\u7684\u9ed8\u8ba4\u65b9\u6cd5\uff0c\u7528\u4e8e\u5904\u7406\u7cbe\u5ea6\u4f9d\u8d56\u6027\u3002\u6211\u4eec\u5206\u6790\u4e86\u8be5\u65b9\u6cd5\uff0c\u5e76\u8868\u660e\u5176\u5728\u540e\u7eed\u51b3\u7b56\u89c4\u5219\u7684\u540e\u6094\u503c\u65b9\u9762\u5177\u6709\u7ade\u4e89\u529b\u3002\u5b9e\u8bc1\u7ed3\u679c\u8868\u660e\uff0c\u4f7f\u7528close\u65b9\u6cd5\u5728\u9009\u62e9\u9ad8\u6d41\u52a8\u6027\u7684\u4eba\u53e3\u666e\u67e5\u533a\u65f6\u5e26\u6765\u4e86\u663e\u8457\u6536\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta19378", "journal": "ECTA", "title": "Trade and Domestic Distortions: The Case of Informality", "authors": ["Rafael Dix-Carneiro", "Pinelopi Goldberg", "Costas Meghir", "Gabriel Ulyssea"], "author_details": [{"name": "Rafael Dix-Carneiro", "affiliations": ["Department of Economics, Duke University"]}, {"name": "Pinelopi Goldberg", "affiliations": ["Department of Economics, Yale University"]}, {"name": "Costas Meghir", "affiliations": ["Department of Economics, Yale University"]}, {"name": "Gabriel Ulyssea", "affiliations": ["Department of Economics, University College London"]}], "abstract": "We examine the effects of international trade in the presence of a set of domestic distortions giving rise to informality, a prevalent phenomenon in developing countries. In our quantitative model, the informal sector arises from burdensome taxes and regulations that are imperfectly enforced by the government. In equilibrium, smaller, less productive firms face fewer distortions than larger, more productive ones, potentially leading to substantial misallocation. We show that in settings with a large informal sector, the gains from trade are significantly amplified, as reductions in trade barriers imply a reallocation of resources from initially less distorted to more distorted firms. We confirm findings from earlier reduced\u2010form studies that the informal sector mitigates the impact of negative labor demand shocks on unemployment. Nonetheless, the informal sector can exacerbate the adverse real income effects of economic downturns, amplifying misallocation. Last, our research sheds light on the relationship between trade openness and cross\u2010firm wage inequality.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta19378", "title_zh": "\u8d38\u6613\u4e0e\u56fd\u5185\u626d\u66f2\uff1a\u975e\u6b63\u5f0f\u7ecf\u6d4e\u7684\u6848\u4f8b", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5728\u5b58\u5728\u5bfc\u81f4\u975e\u6b63\u5f0f\u7ecf\u6d4e\u73b0\u8c61\u7684\u56fd\u5185\u626d\u66f2\u6761\u4ef6\u4e0b\uff0c\u56fd\u9645\u8d38\u6613\u7684\u5f71\u54cd\u3002\u5728\u6211\u4eec\u7684\u5b9a\u91cf\u6a21\u578b\u4e2d\uff0c\u975e\u6b63\u5f0f\u90e8\u95e8\u6e90\u4e8e\u653f\u5e9c\u5bf9\u6c89\u91cd\u7a0e\u6536\u548c\u76d1\u7ba1\u63aa\u65bd\u7684\u4e0d\u5b8c\u5168\u6267\u884c\u3002\u5728\u5747\u8861\u72b6\u6001\u4e0b\uff0c\u89c4\u6a21\u8f83\u5c0f\u3001\u751f\u4ea7\u7387\u8f83\u4f4e\u7684\u4f01\u4e1a\u9762\u4e34\u7684\u626d\u66f2\u8f83\u5c11\uff0c\u800c\u89c4\u6a21\u8f83\u5927\u3001\u751f\u4ea7\u7387\u8f83\u9ad8\u7684\u4f01\u4e1a\u5219\u9762\u4e34\u66f4\u591a\u626d\u66f2\uff0c\u8fd9\u53ef\u80fd\u5bfc\u81f4\u4e25\u91cd\u7684\u8d44\u6e90\u914d\u7f6e\u5931\u5f53\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u975e\u6b63\u5f0f\u90e8\u95e8\u89c4\u6a21\u8f83\u5927\u7684\u60c5\u51b5\u4e0b\uff0c\u8d38\u6613\u5e26\u6765\u7684\u6536\u76ca\u88ab\u663e\u8457\u653e\u5927\uff0c\u56e0\u4e3a\u8d38\u6613\u58c1\u5792\u7684\u964d\u4f4e\u610f\u5473\u7740\u8d44\u6e90\u4ece\u6700\u521d\u626d\u66f2\u8f83\u5c0f\u7684\u4f01\u4e1a\u5411\u626d\u66f2\u8f83\u5927\u7684\u4f01\u4e1a\u91cd\u65b0\u914d\u7f6e\u3002\u6211\u4eec\u8bc1\u5b9e\u4e86\u5148\u524d\u7b80\u5316\u5f62\u5f0f\u7814\u7a76\u7684\u53d1\u73b0\uff0c\u5373\u975e\u6b63\u5f0f\u90e8\u95e8\u53ef\u4ee5\u7f13\u89e3\u8d1f\u5411\u52b3\u52a8\u9700\u6c42\u51b2\u51fb\u5bf9\u5931\u4e1a\u7387\u7684\u5f71\u54cd\u3002\u7136\u800c\uff0c\u975e\u6b63\u5f0f\u90e8\u95e8\u4e5f\u53ef\u80fd\u52a0\u5267\u7ecf\u6d4e\u8870\u9000\u5e26\u6765\u7684\u4e0d\u5229\u6536\u5165\u5f71\u54cd\uff0c\u4ece\u800c\u653e\u5927\u8d44\u6e90\u914d\u7f6e\u5931\u5f53\u3002\u6700\u540e\uff0c\u6211\u4eec\u7684\u7814\u7a76\u63ed\u793a\u4e86\u8d38\u6613\u5f00\u653e\u7a0b\u5ea6\u4e0e\u4f01\u4e1a\u95f4\u5de5\u8d44\u4e0d\u5e73\u7b49\u4e4b\u95f4\u7684\u5173\u7cfb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23345", "journal": "ECTA", "title": "Double Robustness of Local Projections and Some Unpleasant VARithmetic", "authors": ["Jos\u00e9 Luis Montiel Olea", "Mikkel Plagborg-M\u00f8ller", "Eric Qian", "Christian K. Wolf"], "author_details": [{"name": "Jos\u00e9 Luis Montiel Olea", "affiliations": ["Department of Economics, Cornell University"]}, {"name": "Mikkel Plagborg-M\u00f8ller", "affiliations": ["Department of Economics, University of Chicago"]}, {"name": "Eric Qian", "affiliations": ["Department of Economics, Princeton University"]}, {"name": "Christian K. Wolf", "affiliations": ["Department of Economics, MIT", "NBER"]}], "abstract": "We consider impulse response inference in a locally misspecified vector autoregression (VAR) model. The conventional local projection (LP) confidence interval has correct coverage even when the misspecification is so large that it can be detected with probability approaching 1. This result follows from a \u201cdouble robustness\u201d property analogous to that of popular partially linear regression estimators. By contrast, the conventional VAR confidence interval with short\u2010to\u2010moderate lag length can severely undercover for misspecification that is small, difficult to detect statistically, and cannot be ruled out based on economic theory. The VAR confidence interval has robust coverage if, and only if, the lag length is so large that the interval is as wide as the LP interval.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23345", "title_zh": "\u5c40\u90e8\u6295\u5f71\u7684\u53cc\u91cd\u7a33\u5065\u6027\u53ca\u4e00\u4e9b\u4e0d\u6109\u5feb\u7684VAR\u8fd0\u7b97", "abstract_zh": "\u6211\u4eec\u8003\u8651\u5728\u5c40\u90e8\u8bbe\u5b9a\u9519\u8bef\u7684\u5411\u91cf\u81ea\u56de\u5f52\uff08VAR\uff09\u6a21\u578b\u4e2d\u51b2\u51fb\u54cd\u5e94\u7684\u63a8\u65ad\u3002\u4f20\u7edf\u7684\u5c40\u90e8\u6295\u5f71\uff08LP\uff09\u7f6e\u4fe1\u533a\u95f4\u5373\u4f7f\u5728\u8bbe\u5b9a\u9519\u8bef\u975e\u5e38\u4e25\u91cd\u7684\u60c5\u51b5\u4e0b\uff08\u4ee5\u81f3\u4e8e\u4ee5\u6982\u7387\u8d8b\u8fd1\u4e8e1\u88ab\u68c0\u6d4b\u5230\uff09\uff0c\u5176\u8986\u76d6\u6982\u7387\u4ecd\u7136\u662f\u6b63\u786e\u7684\u3002\u8fd9\u4e00\u7ed3\u679c\u6e90\u4e8e\u4e00\u79cd\u7c7b\u4f3c\u4e8e\u6d41\u884c\u90e8\u5206\u7ebf\u6027\u56de\u5f52\u4f30\u8ba1\u91cf\u7684\u2018\u53cc\u91cd\u7a33\u5065\u6027\u2019\u6027\u8d28\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u4f20\u7edfVAR\u7f6e\u4fe1\u533a\u95f4\u5728\u77ed\u5230\u4e2d\u7b49\u6ede\u540e\u957f\u5ea6\u4e0b\uff0c\u5bf9\u4e8e\u90a3\u4e9b\u8f83\u5c0f\u3001\u96be\u4ee5\u901a\u8fc7\u7edf\u8ba1\u65b9\u6cd5\u68c0\u6d4b\u4e14\u65e0\u6cd5\u6839\u636e\u7ecf\u6d4e\u7406\u8bba\u6392\u9664\u7684\u8bbe\u5b9a\u9519\u8bef\uff0c\u53ef\u80fd\u4f1a\u4e25\u91cd\u4f4e\u4f30\u5176\u8986\u76d6\u8303\u56f4\u3002\u53ea\u6709\u5f53\u6ede\u540e\u957f\u5ea6\u8db3\u591f\u5927\uff0c\u4f7f\u5f97\u7f6e\u4fe1\u533a\u95f4\u5bbd\u5ea6\u8fbe\u5230LP\u533a\u95f4\u5bbd\u5ea6\u65f6\uff0cVAR\u7f6e\u4fe1\u533a\u95f4\u624d\u5177\u6709\u7a33\u5065\u7684\u8986\u76d6\u6027\u80fd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta21854", "journal": "ECTA", "title": "Rural Migrants and Urban Informality: Evidence From Brazil", "authors": ["Clement Imbert", "Gabriel Ulyssea"], "author_details": [{"name": "Clement Imbert", "affiliations": ["Department of Economics, Sciences Po"]}, {"name": "Gabriel Ulyssea", "affiliations": ["Department of Economics, University College London"]}], "abstract": "This paper studies the economic effects of rural\u2010urban migration on Brazilian cities. Using a shift\u2010share IV design, we show that, over a decade, drought\u2010induced immigration reduces informality, has no effect on unemployment, and increases the number of formal firms and jobs. Downward formal wage adjustments play a key role, as these long\u2010run effects are weaker in regions with stronger wage rigidity. In the short run, when wage rigidity is strongest, we replicate the informality\u2010increasing effects documented in the literature. We develop and estimate a model of firm dynamics and informality that rationalizes these results. The counterfactuals reveal that, in the short run, the informal sector absorbs the expanding labor force and acts as a \u201cstepping\u2010stone\u201d to formality for firms and workers. In the long run, however, it reduces the aggregate benefits from immigration by allowing the least productive firms to survive.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21854", "title_zh": "\u519c\u6751\u79fb\u6c11\u4e0e\u57ce\u5e02\u975e\u6b63\u89c4\u7ecf\u6d4e\uff1a\u6765\u81ea\u5df4\u897f\u7684\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u519c\u6751\u5411\u57ce\u5e02\u8fc1\u79fb\u5bf9\u5df4\u897f\u57ce\u5e02\u7ecf\u6d4e\u7684\u5f71\u54cd\u3002\u91c7\u7528\u79fb\u4f4d\u4efd\u989d\u5de5\u5177\u53d8\u91cf\u6cd5\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u5341\u5e74\u95f4\uff0c\u7531\u5e72\u65f1\u5f15\u53d1\u7684\u79fb\u6c11\u51cf\u5c11\u4e86\u975e\u6b63\u89c4\u7ecf\u6d4e\u7684\u5b58\u5728\uff0c\u5bf9\u5931\u4e1a\u7387\u6ca1\u6709\u5f71\u54cd\uff0c\u5e76\u589e\u52a0\u4e86\u6b63\u5f0f\u4f01\u4e1a\u7684\u6570\u91cf\u548c\u5c31\u4e1a\u5c97\u4f4d\u3002\u5411\u4e0b\u8c03\u6574\u6b63\u5f0f\u5de5\u8d44\u5728\u5176\u4e2d\u53d1\u6325\u4e86\u5173\u952e\u4f5c\u7528\uff0c\u56e0\u4e3a\u5de5\u8d44\u521a\u6027\u8f83\u5f3a\u7684\u5730\u533a\uff0c\u8fd9\u4e9b\u957f\u671f\u6548\u5e94\u8f83\u5f31\u3002\u5728\u77ed\u671f\u5185\uff0c\u5f53\u5de5\u8d44\u521a\u6027\u6700\u5f3a\u65f6\uff0c\u6211\u4eec\u91cd\u73b0\u4e86\u6587\u732e\u4e2d\u8bb0\u5f55\u7684\u975e\u6b63\u89c4\u7ecf\u6d4e\u6269\u5f20\u6548\u5e94\u3002\u6211\u4eec\u6784\u5efa\u5e76\u4f30\u8ba1\u4e86\u4e00\u4e2a\u4f01\u4e1a\u52a8\u6001\u4e0e\u975e\u6b63\u89c4\u7ecf\u6d4e\u7684\u6a21\u578b\uff0c\u4ee5\u89e3\u91ca\u8fd9\u4e9b\u7ed3\u679c\u3002\u53cd\u4e8b\u5b9e\u5206\u6790\u8868\u660e\uff0c\u5728\u77ed\u671f\u5185\uff0c\u975e\u6b63\u89c4\u90e8\u95e8\u5438\u6536\u4e86\u6269\u5f20\u7684\u52b3\u52a8\u529b\uff0c\u5e76\u4f5c\u4e3a\u4f01\u4e1a\u4e0e\u52b3\u52a8\u8005\u8fdb\u5165\u6b63\u89c4\u90e8\u95e8\u7684\"\u4e2d\u95f4\u73af\u8282\"\u3002\u7136\u800c\uff0c\u5728\u957f\u671f\u6765\u770b\uff0c\u5b83\u901a\u8fc7\u4f7f\u751f\u4ea7\u6548\u7387\u6700\u4f4e\u7684\u4f01\u4e1a\u5f97\u4ee5\u5b58\u6d3b\uff0c\u524a\u5f31\u4e86\u79fb\u6c11\u5e26\u6765\u7684\u6574\u4f53\u6536\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta21084", "journal": "ECTA", "title": "Holding up Green Energy: Counterparty Risk in the Indian Solar Power Market", "authors": ["Nicholas Ryan"], "author_details": [{"name": "Nicholas Ryan", "affiliations": ["Department of Economics, Yale University"]}], "abstract": "This paper studies how the risk of hold\u2010up affects procurement. I use data on the universe of solar power auctions in India. The Indian context allows clean estimates of counterparty risk, because solar plants set up in the same states, by the same firms, are procured in auctions intermediated by either risky states themselves or the trusted central government. I find that the counterparty risk of an average state increases solar prices by 10%. This risk premium sharply reduces investment, because demand for green energy is elastic. Contract intermediation by the central government eliminates the counterparty risk premium.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21084", "title_zh": "\u7eff\u8272\u80fd\u6e90\u7684\u6301\u6709\u98ce\u9669\uff1a\u5370\u5ea6\u592a\u9633\u80fd\u5e02\u573a\u7684\u5bf9\u624b\u65b9\u98ce\u9669", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u6301\u6709\u98ce\u9669\u5982\u4f55\u5f71\u54cd\u91c7\u8d2d\u884c\u4e3a\u3002\u6211\u4f7f\u7528\u4e86\u5370\u5ea6\u592a\u9633\u80fd\u62cd\u5356\u7684\u5168\u90e8\u6570\u636e\u3002\u5370\u5ea6\u7684\u80cc\u666f\u4f7f\u5f97\u80fd\u591f\u5bf9\u5bf9\u624b\u65b9\u98ce\u9669\u8fdb\u884c\u6e05\u6670\u7684\u4f30\u7b97\uff0c\u56e0\u4e3a\u540c\u4e00\u5dde\u5185\u3001\u7531\u540c\u4e00\u4f01\u4e1a\u5efa\u8bbe\u7684\u592a\u9633\u80fd\u7535\u7ad9\uff0c\u5176\u91c7\u8d2d\u901a\u8fc7\u7531\u98ce\u9669\u8f83\u9ad8\u7684\u5dde\u81ea\u8eab\u6216\u53d7\u4fe1\u4efb\u7684\u4e2d\u592e\u653f\u5e9c\u4e2d\u4ecb\u7684\u62cd\u5356\u8fdb\u884c\u3002\u6211\u53d1\u73b0\uff0c\u4e00\u4e2a\u5e73\u5747\u5dde\u7684\u5bf9\u624b\u65b9\u98ce\u9669\u4f1a\u4f7f\u592a\u9633\u80fd\u4ef7\u683c\u4e0a\u534710%\u3002\u8fd9\u79cd\u98ce\u9669\u6ea2\u4ef7\u4f1a\u663e\u8457\u964d\u4f4e\u6295\u8d44\uff0c\u56e0\u4e3a\u7eff\u8272\u80fd\u6e90\u7684\u9700\u6c42\u662f\u5bcc\u6709\u5f39\u6027\u7684\u3002\u7531\u4e2d\u592e\u653f\u5e9c\u8fdb\u884c\u5408\u540c\u4e2d\u4ecb\u53ef\u4ee5\u6d88\u9664\u5bf9\u624b\u65b9\u98ce\u9669\u6ea2\u4ef7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.3982/ecta22488", "journal": "ECTA", "title": "Fisher\u2013Schultz Lecture: Contracting Over Pharmaceutical Formularies and Rebates", "authors": ["Kate Ho", "Robin S. Lee"], "author_details": [{"name": "Kate Ho", "affiliations": ["Department of Economics, Princeton University"]}, {"name": "Robin S. Lee", "affiliations": ["Department of Economics, Harvard University"]}], "abstract": "We investigate how formularies used by pharmacy benefit managers (PBMs) affect equilibrium manufacturer rebates for branded drugs through tiering and exclusion. We develop a theoretical model of multidimensional contracting in which a PBM negotiates with drug manufacturers over menus of formulary\u2010contingent rebates and chooses a formulary. We then estimate consumer demand responses to tier placement for statins using claims data from Princeton University, a large employer contracting with a single PBM to offer prescription drug coverage to its employees. Combining the theoretical model with demand estimates and observed list prices, we quantify how allowing for differential tier placement and exclusion affect equilibrium rebates. Our predictions are consistent with available aggregate rebate data, and we find that allowing a PBM to place branded drugs on preferred\u2010 and non\u2010preferred tiers can substantially increase negotiated rebate payments.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22488", "title_zh": "\u8d39\u820d\u5c14-\u8212\u5c14\u8328\u8bb2\u5ea7\uff1a\u5173\u4e8e\u836f\u54c1\u76ee\u5f55\u548c\u56de\u6263\u7684\u5408\u540c\u5b89\u6392", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u836f\u623f\u798f\u5229\u7ba1\u7406\u516c\u53f8\uff08PBMs\uff09\u4f7f\u7528\u7684\u76ee\u5f55\u5982\u4f55\u901a\u8fc7\u5206\u5c42\u548c\u6392\u9664\u5f71\u54cd\u54c1\u724c\u836f\u7269\u5728\u5747\u8861\u72b6\u6001\u4e0b\u7684\u5236\u9020\u5546\u56de\u6263\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u591a\u7ef4\u5408\u540c\u7684\u7406\u8bba\u6a21\u578b\uff0c\u5176\u4e2dPBMs\u4e0e\u5236\u836f\u516c\u53f8\u5c31\u57fa\u4e8e\u76ee\u5f55\u7684\u56de\u6263\u83dc\u5355\u8fdb\u884c\u8c08\u5224\uff0c\u5e76\u9009\u62e9\u4e00\u4e2a\u76ee\u5f55\u3002\u7136\u540e\uff0c\u6211\u4eec\u5229\u7528\u666e\u6797\u65af\u987f\u5927\u5b66\u7684\u7d22\u8d54\u6570\u636e\uff0c\u4f30\u8ba1\u4e86\u5458\u5de5\u5bf9\u4ed6\u6c40\u7c7b\u836f\u7269\u5206\u5c42\u4f4d\u7f6e\u7684\u6d88\u8d39\u9700\u6c42\u54cd\u5e94\uff0c\u8be5\u6570\u636e\u6765\u81ea\u4e00\u5bb6\u4e0e\u5355\u4e00PBM\u7b7e\u8ba2\u534f\u8bae\u3001\u4e3a\u5176\u5458\u5de5\u63d0\u4f9b\u5904\u65b9\u836f\u8986\u76d6\u7684\u5927\u578b\u96c7\u4e3b\u3002\u7ed3\u5408\u7406\u8bba\u6a21\u578b\u3001\u9700\u6c42\u4f30\u8ba1\u548c\u89c2\u5bdf\u5230\u7684\u76ee\u5f55\u4ef7\u683c\uff0c\u6211\u4eec\u91cf\u5316\u4e86\u5141\u8bb8\u5bf9\u54c1\u724c\u836f\u7269\u5728\u4f18\u9009\u548c\u975e\u4f18\u9009\u5c42\u7ea7\u4e4b\u95f4\u7684\u5dee\u5f02\u5316\u653e\u7f6e\u4ee5\u53ca\u6392\u9664\u5bf9\u5747\u8861\u56de\u6263\u7684\u5f71\u54cd\u3002\u6211\u4eec\u7684\u9884\u6d4b\u4e0e\u73b0\u6709\u7684\u603b\u4f53\u56de\u6263\u6570\u636e\u4e00\u81f4\uff0c\u5e76\u53d1\u73b0\u5141\u8bb8PBMs\u5c06\u54c1\u724c\u836f\u7269\u653e\u7f6e\u5728\u4f18\u9009\u548c\u975e\u4f18\u9009\u5c42\u7ea7\u4e0a\uff0c\u53ef\u4ee5\u663e\u8457\u63d0\u9ad8\u534f\u5546\u8fbe\u6210\u7684\u56de\u6263\u91d1\u989d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta21571", "journal": "ECTA", "title": "Causal Inference for Spatial Treatments", "authors": ["Michael Pollmann"], "author_details": [{"name": "Michael Pollmann", "affiliations": ["Department of Economics, Duke University"]}], "abstract": "Many events and policies (treatments) occur at specific spatial locations, with researchers interested in their effects on nearby units. I approach the spatial treatment setting from an experimental perspective: What ideal experiment would we design to estimate the causal effects of spatial treatments? This perspective motivates a comparison between units near realized treatment locations and units near counterfactual (unrealized) candidate locations, which differs from current empirical practice. I derive design\u2010based standard errors that are straightforward to compute. For observational data, I propose machine learning methods to find counterfactual candidate locations when observable characteristics, rather than potential outcomes, determine treatment probabilities. To accommodate methods for high\u2010dimensional data in the theory, I extend a double machine learning result to the design\u2010based framework with spatial correlations. I apply the proposed methods to study the causal effects of grocery stores on foot traffic to nearby businesses during COVID\u201019 shelter\u2010in\u2010place policies, finding a large positive effect at very short distances, with no effect at larger distances.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21571", "title_zh": "\u7a7a\u95f4\u5904\u7406\u7684\u56e0\u679c\u63a8\u65ad", "abstract_zh": "\u8bb8\u591a\u4e8b\u4ef6\u548c\u653f\u7b56\uff08\u5904\u7406\uff09\u53d1\u751f\u5728\u7279\u5b9a\u7684\u7a7a\u95f4\u4f4d\u7f6e\uff0c\u7814\u7a76\u4eba\u5458\u5173\u6ce8\u5176\u5bf9\u9644\u8fd1\u5355\u4f4d\u7684\u5f71\u54cd\u3002\u6211\u4ece\u5b9e\u9a8c\u7684\u89d2\u5ea6\u51fa\u53d1\uff1a\u4e3a\u4e86\u4f30\u8ba1\u7a7a\u95f4\u5904\u7406\u7684\u56e0\u679c\u6548\u5e94\uff0c\u6211\u4eec\u5e94\u8bbe\u8ba1\u600e\u6837\u7684\u7406\u60f3\u5b9e\u9a8c\uff1f\u8fd9\u4e00\u89c6\u89d2\u4fc3\u4f7f\u6211\u4eec\u6bd4\u8f83\u5b9e\u9645\u5904\u7406\u4f4d\u7f6e\u9644\u8fd1\u5355\u4f4d\u4e0e\u53cd\u4e8b\u5b9e\uff08\u672a\u5b9e\u73b0\uff09\u5019\u9009\u4f4d\u7f6e\u9644\u8fd1\u5355\u4f4d\uff0c\u8fd9\u4e0e\u5f53\u524d\u7684\u5b9e\u8bc1\u5b9e\u8df5\u6709\u6240\u4e0d\u540c\u3002\u6211\u63a8\u5bfc\u51fa\u6613\u4e8e\u8ba1\u7b97\u7684\u8bbe\u8ba1\u578b\u6807\u51c6\u8bef\u3002\u5bf9\u4e8e\u89c2\u5bdf\u6027\u6570\u636e\uff0c\u6211\u63d0\u51fa\u673a\u5668\u5b66\u4e60\u65b9\u6cd5\uff0c\u5f53\u53ef\u89c2\u6d4b\u7279\u5f81\u800c\u975e\u6f5c\u5728\u7ed3\u679c\u51b3\u5b9a\u5904\u7406\u6982\u7387\u65f6\uff0c\u7528\u4e8e\u5bfb\u627e\u53cd\u4e8b\u5b9e\u5019\u9009\u4f4d\u7f6e\u3002\u4e3a\u4e86\u9002\u5e94\u9ad8\u7ef4\u6570\u636e\u65b9\u6cd5\u7684\u7406\u8bba\uff0c\u6211\u5c06\u53cc\u91cd\u673a\u5668\u5b66\u4e60\u7ed3\u679c\u6269\u5c55\u5230\u5177\u6709\u7a7a\u95f4\u76f8\u5173\u6027\u7684\u8bbe\u8ba1\u6846\u67b6\u4e2d\u3002\u6211\u5c06\u6240\u63d0\u51fa\u7684\u65b9\u6cd5\u5e94\u7528\u4e8e\u7814\u7a76\u65b0\u51a0\u75ab\u60c5\u5c45\u5bb6\u4ee4\u671f\u95f4\u8d85\u5e02\u5bf9\u9644\u8fd1\u4f01\u4e1a\u5ba2\u6d41\u7684\u56e0\u679c\u6548\u5e94\uff0c\u53d1\u73b0\u975e\u5e38\u8fd1\u8ddd\u79bb\u5185\u5b58\u5728\u663e\u8457\u7684\u6b63\u5411\u6548\u5e94\uff0c\u800c\u5728\u66f4\u5927\u8ddd\u79bb\u4e0a\u5219\u65e0\u663e\u8457\u6548\u5e94\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.3982/ecta21835", "journal": "ECTA", "title": "Training Specificity and Occupational Mobility: Evidence From German Apprenticeships", "authors": ["Dita Eckardt"], "author_details": [{"name": "Dita Eckardt", "affiliations": ["Department of Economics, University of Warwick"]}], "abstract": "Apprenticeships play a key role in enabling successful school\u2010to\u2010work transitions in many countries, but in the presence of imperfect information, the specificity of this type of training may entail important costs for those working outside their training fields. I study this issue in one of the most prominent training settings, the German apprenticeship system. Using administrative data and a broad occupational classification, I find that 40% of individuals work in occupations different from their training. I estimate the cost of mismatch using vacancy instruments and extend methodological approaches in high\u2010dimensional selection settings. Lacking training in one's occupation entails an average wage penalty of 14%, the equivalent of two years of work experience. The penalty increases with the task distance between training and occupation. My findings suggest that retraining is crucial to mitigate the adverse consequences from imperfect information in specialized training settings.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21835", "title_zh": "\u57f9\u8bad\u7279\u5f02\u6027\u4e0e\u804c\u4e1a\u6d41\u52a8\uff1a\u6765\u81ea\u5fb7\u56fd\u5b66\u5f92\u5236\u7684\u8bc1\u636e", "abstract_zh": "\u5b66\u5f92\u5236\u5728\u8bb8\u591a\u56fd\u5bb6\u4e2d\u5bf9\u4e8e\u5b9e\u73b0\u4ece\u5b66\u6821\u5230\u5de5\u4f5c\u7684\u987a\u5229\u8fc7\u6e21\u5177\u6709\u91cd\u8981\u4f5c\u7528\uff0c\u4f46\u5728\u4fe1\u606f\u4e0d\u5b8c\u5168\u7684\u60c5\u51b5\u4e0b\uff0c\u8fd9\u79cd\u57f9\u8bad\u7684\u7279\u5f02\u6027\u53ef\u80fd\u5bf9\u90a3\u4e9b\u5728\u57f9\u8bad\u9886\u57df\u4e4b\u5916\u5de5\u4f5c\u7684\u4eba\u5e26\u6765\u91cd\u8981\u6210\u672c\u3002\u672c\u6587\u7814\u7a76\u4e86\u5fb7\u56fd\u6700\u5177\u4ee3\u8868\u6027\u7684\u57f9\u8bad\u4f53\u7cfb\u4e2d\u7684\u8fd9\u4e00\u95ee\u9898\u3002\u5229\u7528\u884c\u653f\u6570\u636e\u548c\u5e7f\u6cdb\u7684\u804c\u4e1a\u5206\u7c7b\uff0c\u6211\u53d1\u73b040%\u7684\u4e2a\u4f53\u4ece\u4e8b\u7684\u804c\u4e1a\u4e0e\u5176\u57f9\u8bad\u9886\u57df\u4e0d\u540c\u3002\u6211\u4f7f\u7528\u804c\u4f4d\u7a7a\u7f3a\u5de5\u5177\u4f30\u8ba1\u4e86\u9519\u914d\u7684\u6210\u672c\uff0c\u5e76\u5728\u9ad8\u7ef4\u9009\u62e9\u60c5\u5883\u4e0b\u6269\u5c55\u4e86\u65b9\u6cd5\u8bba\u3002\u7f3a\u4e4f\u804c\u4e1a\u57f9\u8bad\u4f1a\u5bfc\u81f4\u5e73\u5747\u5de5\u8d44\u60e9\u7f5a14%\uff0c\u76f8\u5f53\u4e8e\u4e24\u5e74\u7684\u5de5\u4f5c\u7ecf\u9a8c\u3002\u8fd9\u4e00\u60e9\u7f5a\u968f\u7740\u57f9\u8bad\u4e0e\u804c\u4e1a\u4e4b\u95f4\u7684\u4efb\u52a1\u8ddd\u79bb\u589e\u52a0\u800c\u4e0a\u5347\u3002\u6211\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u5728\u7279\u5f02\u6027\u57f9\u8bad\u73af\u5883\u4e2d\uff0c\u518d\u57f9\u8bad\u5bf9\u4e8e\u7f13\u89e3\u56e0\u4fe1\u606f\u4e0d\u5b8c\u5168\u5e26\u6765\u7684\u4e0d\u5229\u5f71\u54cd\u81f3\u5173\u91cd\u8981\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta24365", "journal": "ECTA", "title": "Comment on \u2018Asset Bubbles and Overlapping Generations\u2019 by Jean Tirole", "authors": ["Ngoc-Sang Pham", "Alexis Akira Toda"], "author_details": [{"name": "Ngoc-Sang Pham", "affiliations": ["EM Normandie Business School, M\u00e9tis Lab"]}, {"name": "Alexis Akira Toda", "affiliations": ["Department of Economics, Emory University"]}], "abstract": "Tirole (1985) studied an overlapping generations model with capital accumulation and showed that the emergence of asset bubbles solves the capital over\u2010accumulation problem. His Proposition 1(c) claims that if the dividend growth rate is above the bubbleless interest rate (the steady\u2010state interest rate in the economy without the asset) but below the population growth rate, then bubbles are necessary in the sense that there exists no bubbleless equilibrium but there exists a unique bubbly equilibrium. We show that this result (as stated) is incorrect by presenting an example economy that satisfies all assumptions of Proposition 1(c) but its unique equilibrium is bubbleless. We also restore Proposition 1(c) under the additional assumptions that initial capital is sufficiently large and dividends are sufficiently small. We show through examples that these conditions are essential.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta24365", "title_zh": "\u5bf9Jean Tirole\u300a\u8d44\u4ea7\u6ce1\u6cab\u4e0e\u4e16\u4ee3\u91cd\u53e0\u300b\u4e00\u6587\u7684\u8bc4\u8bba", "abstract_zh": "Tirole\uff081985\uff09\u7814\u7a76\u4e86\u4e00\u4e2a\u5305\u542b\u8d44\u672c\u79ef\u7d2f\u7684\u4e16\u4ee3\u91cd\u53e0\u6a21\u578b\uff0c\u8868\u660e\u8d44\u4ea7\u6ce1\u6cab\u7684\u51fa\u73b0\u53ef\u4ee5\u89e3\u51b3\u8d44\u672c\u8fc7\u5ea6\u79ef\u7d2f\u95ee\u9898\u3002\u4ed6\u7684\u547d\u98981(c)\u58f0\u79f0\uff0c\u5982\u679c\u80a1\u606f\u589e\u957f\u7387\u9ad8\u4e8e\u65e0\u6ce1\u6cab\u5229\u7387\uff08\u5373\u6ca1\u6709\u8d44\u4ea7\u7684\u7ecf\u6d4e\u7a33\u6001\u5229\u7387\uff09\uff0c\u4f46\u4f4e\u4e8e\u4eba\u53e3\u589e\u957f\u7387\uff0c\u90a3\u4e48\u6ce1\u6cab\u662f\u5fc5\u8981\u7684\uff0c\u5373\u4e0d\u5b58\u5728\u65e0\u6ce1\u6cab\u5747\u8861\uff0c\u4f46\u5b58\u5728\u552f\u4e00\u7684\u6ce1\u6cab\u5747\u8861\u3002\u6211\u4eec\u901a\u8fc7\u6784\u9020\u4e00\u4e2a\u6ee1\u8db3\u547d\u98981(c)\u6240\u6709\u5047\u8bbe\u7684\u7ecf\u6d4e\u4f53\u5b9e\u4f8b\uff0c\u8bc1\u660e\u4e86\u8fd9\u4e00\u7ed3\u8bba\uff08\u5982\u539f\u6587\u6240\u8ff0\uff09\u662f\u9519\u8bef\u7684\uff0c\u8be5\u7ecf\u6d4e\u4f53\u7684\u552f\u4e00\u5747\u8861\u662f\u65e0\u6ce1\u6cab\u7684\u3002\u6211\u4eec\u8fd8\u5728\u521d\u59cb\u8d44\u672c\u8db3\u591f\u5927\u4e14\u80a1\u606f\u8db3\u591f\u5c0f\u7684\u9644\u52a0\u5047\u8bbe\u4e0b\uff0c\u6062\u590d\u4e86\u547d\u98981(c)\u7684\u6709\u6548\u6027\uff0c\u5e76\u901a\u8fc7\u5b9e\u4f8b\u8868\u660e\u8fd9\u4e9b\u6761\u4ef6\u662f\u5fc5\u4e0d\u53ef\u5c11\u7684\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23609", "journal": "ECTA", "title": "The Economics of Partisan Gerrymandering", "authors": ["Anton Kolotilin", "Alexander Wolitzky"], "author_details": [{"name": "Anton Kolotilin", "affiliations": ["School of Economics, UNSW Business School"]}, {"name": "Alexander Wolitzky", "affiliations": ["Department of Economics, MIT"]}], "abstract": "We study the problem of a partisan gerrymanderer who assigns voters to equipopulous districts to maximize his party's expected seat share. The designer faces both aggregate, district\u2010level uncertainty (how many votes his party will receive) and idiosyncratic, voter\u2010level uncertainty (which voters will vote for his party). Segregate\u2010pair districting , where weaker districts contain one type of voter, while stronger districts contain two, is optimal for the gerrymanderer. The optimal form of segregate\u2010pair districting depends on the designer's popularity and the relative amounts of aggregate and idiosyncratic uncertainty. When idiosyncratic uncertainty dominates, a designer with majority support pairs all voters, while a designer with minority support segregates opposing voters and pairs more favorable voters; these plans resemble uniform districting and \u201cpacking\u2010and\u2010cracking,\u201d respectively. When aggregate uncertainty dominates, the designer segregates moderate voters and pairs extreme voters; this \u201cmatching slices\u201d plan has received some attention in the literature. Estimating the model using precinct\u2010level returns from recent U.S. House elections shows that, in practice, idiosyncratic uncertainty dominates. We discuss implications for redistricting reform, political polarization, and detecting gerrymandering. Methodologically, we exploit a formal connection between gerrymandering\u2014partitioning voters into districts\u2014and information design\u2014partitioning states of the world into signals.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23609", "title_zh": "\u515a\u6d3e\u9009\u533a\u91cd\u5212\u7684\u7ecf\u6d4e\u5b66", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u540d\u515a\u6d3e\u9009\u533a\u91cd\u5212\u8005\u5982\u4f55\u5c06\u9009\u6c11\u5206\u914d\u5230\u4eba\u53e3\u76f8\u7b49\u7684\u9009\u533a\uff0c\u4ee5\u6700\u5927\u5316\u5176\u653f\u515a\u9884\u671f\u5e2d\u4f4d\u4efd\u989d\u7684\u95ee\u9898\u3002\u8be5\u8bbe\u8ba1\u8005\u9762\u4e34\u4e24\u79cd\u4e0d\u786e\u5b9a\u6027\uff1a\u6574\u4f53\u5c42\u9762\u7684\u9009\u533a\u7ea7\u4e0d\u786e\u5b9a\u6027\uff08\u5176\u653f\u515a\u5c06\u83b7\u5f97\u591a\u5c11\u9009\u7968\uff09\u548c\u4e2a\u4f53\u5c42\u9762\u7684\u9009\u6c11\u4e0d\u786e\u5b9a\u6027\uff08\u54ea\u4e9b\u9009\u6c11\u4f1a\u652f\u6301\u5176\u653f\u515a\uff09\u3002\u5728\u2018\u5206\u79bb\u914d\u5bf9\u2019\u9009\u533a\u5212\u5206\u4e2d\uff0c\u8f83\u5f31\u7684\u9009\u533a\u5305\u542b\u4e00\u79cd\u7c7b\u578b\u7684\u9009\u6c11\uff0c\u800c\u8f83\u5f3a\u7684\u9009\u533a\u5305\u542b\u4e24\u79cd\u7c7b\u578b\uff0c\u8fd9\u5bf9\u9009\u533a\u91cd\u5212\u8005\u800c\u8a00\u662f\u6700\u4f73\u7b56\u7565\u3002\u6700\u4f18\u7684\u5206\u79bb\u914d\u5bf9\u9009\u533a\u5212\u5206\u5f62\u5f0f\u53d6\u51b3\u4e8e\u8bbe\u8ba1\u8005\u7684\u652f\u6301\u7a0b\u5ea6\u4ee5\u53ca\u6574\u4f53\u4e0d\u786e\u5b9a\u6027\u4e0e\u4e2a\u4f53\u4e0d\u786e\u5b9a\u6027\u4e4b\u95f4\u7684\u76f8\u5bf9\u5927\u5c0f\u3002\u5f53\u4e2a\u4f53\u4e0d\u786e\u5b9a\u6027\u5360\u4e3b\u5bfc\u65f6\uff0c\u62e5\u6709\u591a\u6570\u652f\u6301\u7684\u8bbe\u8ba1\u8005\u4f1a\u5c06\u6240\u6709\u9009\u6c11\u914d\u5bf9\uff0c\u800c\u62e5\u6709\u5c11\u6570\u652f\u6301\u7684\u8bbe\u8ba1\u8005\u5219\u4f1a\u5c06\u5bf9\u7acb\u9009\u6c11\u5206\u79bb\uff0c\u5e76\u5c06\u66f4\u6709\u5229\u4e8e\u81ea\u5df1\u7684\u9009\u6c11\u914d\u5bf9\uff1b\u8fd9\u4e24\u79cd\u65b9\u6848\u5206\u522b\u7c7b\u4f3c\u4e8e\u5747\u5300\u9009\u533a\u5212\u5206\u548c\u2018\u96c6\u4e2d-\u5206\u6563\u2019\u7b56\u7565\u3002\u5f53\u6574\u4f53\u4e0d\u786e\u5b9a\u6027\u5360\u4e3b\u5bfc\u65f6\uff0c\u8bbe\u8ba1\u8005\u4f1a\u5c06\u4e2d\u95f4\u9009\u6c11\u5206\u79bb\uff0c\u5e76\u5c06\u6781\u7aef\u9009\u6c11\u914d\u5bf9\uff1b\u8fd9\u79cd\u2018\u5339\u914d\u5207\u7247\u2019\u7b56\u7565\u5728\u6587\u732e\u4e2d\u5df2\u53d7\u5230\u4e00\u5b9a\u5173\u6ce8\u3002\u5229\u7528\u6700\u8fd1\u7f8e\u56fd\u4f17\u8bae\u9662\u9009\u4e3e\u7684 precinct \u7ea7\u6570\u636e\u5bf9\u6a21\u578b\u8fdb\u884c\u4f30\u8ba1\u8868\u660e\uff0c\u5b9e\u8df5\u4e2d\u4e2a\u4f53\u4e0d\u786e\u5b9a\u6027\u5360\u4e3b\u5bfc\u5730\u4f4d\u3002\u6211\u4eec\u8ba8\u8bba\u4e86\u8fd9\u4e00\u7ed3\u679c\u5bf9\u9009\u533a\u91cd\u5212\u6539\u9769\u3001\u653f\u6cbb\u6781\u5316\u4ee5\u53ca\u68c0\u6d4b\u9009\u533a\u91cd\u5212\u884c\u4e3a\u7684\u542f\u793a\u3002\u65b9\u6cd5\u4e0a\uff0c\u6211\u4eec\u5229\u7528\u4e86\u9009\u533a\u91cd\u5212\uff08\u5c06\u9009\u6c11\u5212\u5206\u4e3a\u9009\u533a\uff09\u4e0e\u4fe1\u606f\u8bbe\u8ba1\uff08\u5c06\u4e16\u754c\u72b6\u6001\u5212\u5206\u4e3a\u4fe1\u53f7\uff09\u4e4b\u95f4\u7684\u6b63\u5f0f\u8054\u7cfb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23358", "journal": "ECTA", "title": "The Class Gap in Career Progression: Evidence From U.S. Academia", "authors": ["Anna Stansbury", "Kyra Rodriguez"], "author_details": [{"name": "Anna Stansbury", "affiliations": ["Sloan School of Management, MIT"]}, {"name": "Kyra Rodriguez", "affiliations": ["Haas School of Business, UC Berkeley"]}], "abstract": "Unlike gender or race, class background is rarely a focus of research on career progression, or of DEI efforts in elite occupations. Should it be? In this paper, we document a large class gap in career progression in one occupation\u2014U.S. tenure\u2010track academia\u2014using parental education to proxy for class background. First\u2010generation college graduates are 10% less likely to be tenured at an R1, are tenured at institutions ranked 11% lower, earn 3% less, and report 5% lower job satisfaction, than their former PhD classmates (from the same institution and field) with a parent with a non\u2010PhD graduate degree. Neither selection out of academia nor different preferences explain this gap; differential research productivity also plays little role. Instead, likely drivers are differences in cultural and social capital. We also find a class gap in career progression for PhDs who work in industry, suggesting this phenomenon generalizes outside academia.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23358", "title_zh": "\u804c\u4e1a\u664b\u5347\u4e2d\u7684\u9636\u7ea7\u5dee\u8ddd\uff1a\u6765\u81ea\u7f8e\u56fd\u5b66\u672f\u754c\u7684\u8bc1\u636e", "abstract_zh": "\u4e0e\u6027\u522b\u6216\u79cd\u65cf\u4e0d\u540c\uff0c\u9636\u7ea7\u80cc\u666f\u5f88\u5c11\u6210\u4e3a\u804c\u4e1a\u664b\u5347\u7814\u7a76\u6216\u7cbe\u82f1\u804c\u4e1a\u4e2d\u591a\u5143\u5316\u3001\u516c\u5e73\u4e0e\u5305\u5bb9\uff08DEI\uff09\u52aa\u529b\u7684\u5173\u6ce8\u7126\u70b9\u3002\u8fd9\u79cd\u5ffd\u89c6\u662f\u5426\u5e94\u88ab\u7ea0\u6b63\uff1f\u672c\u6587\u5229\u7528\u7236\u6bcd\u6559\u80b2\u6c34\u5e73\u6765\u4ee3\u7406\u9636\u7ea7\u80cc\u666f\uff0c\u63ed\u793a\u4e86\u7f8e\u56fd tenure-track \u5b66\u672f\u754c\u4e2d\u663e\u8457\u7684\u9636\u7ea7\u5dee\u8ddd\u3002\u4e0e\u6765\u81ea\u540c\u4e00\u673a\u6784\u548c\u9886\u57df\u7684\u535a\u58eb\u751f\u540c\u5b66\u76f8\u6bd4\uff0c\u7b2c\u4e00\u4ee3\u5927\u5b66\u751f\u6bd5\u4e1a\u751f\u6210\u4e3a R1 \u673a\u6784\u7ec8\u8eab\u6559\u804c\u7684\u51e0\u7387\u4f4e 10%\uff0c\u5176\u4efb\u804c\u673a\u6784\u6392\u540d\u4f4e 11%\uff0c\u6536\u5165\u4f4e 3%\uff0c\u5de5\u4f5c\u6ee1\u610f\u5ea6\u4f4e 5%\u3002\u8fd9\u79cd\u5dee\u8ddd\u65e2\u4e0d\u80fd\u7531\u9009\u62e9\u9000\u51fa\u5b66\u672f\u754c\u89e3\u91ca\uff0c\u4e5f\u4e0d\u80fd\u7531\u504f\u597d\u5dee\u5f02\u89e3\u91ca\uff1b\u7814\u7a76\u4ea7\u51fa\u7684\u5dee\u5f02\u4e5f\u8d77\u4f5c\u7528\u751a\u5fae\u3002\u66f4\u53ef\u80fd\u7684\u9a71\u52a8\u56e0\u7d20\u662f\u6587\u5316\u8d44\u672c\u548c\u793e\u4f1a\u8d44\u672c\u7684\u5dee\u5f02\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0c\u4ece\u4e8b\u4ea7\u4e1a\u5de5\u4f5c\u7684\u535a\u58eb\u751f\u5728\u804c\u4e1a\u664b\u5347\u4e2d\u4e5f\u5b58\u5728\u9636\u7ea7\u5dee\u8ddd\uff0c\u8868\u660e\u8fd9\u4e00\u73b0\u8c61\u53ef\u80fd\u4e0d\u4ec5\u9650\u4e8e\u5b66\u672f\u754c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23230", "journal": "ECTA", "title": "The Random Priority Mechanism Is Uniquely Simple, Efficient, and Fair", "authors": ["Marek Pycia", "Peter Troyan"], "author_details": [{"name": "Marek Pycia", "affiliations": ["Department of Economics, University of Zurich"]}, {"name": "Peter Troyan", "affiliations": ["Department of Economics, University of Virginia"]}], "abstract": "Random Priority is a popular mechanism used to allocate a set of objects to a set of agents without the use of monetary transfers. Random Priority is appealing because it satisfies desirable efficiency, fairness, and incentive properties. Is it the only mechanism with these properties? We answer this long\u2010standing question in the positive: Random Priority is the unique mechanism that is Pareto efficient, symmetric, and obviously strategy\u2010proof.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23230", "title_zh": "\u968f\u673a\u4f18\u5148\u673a\u5236\u662f\u552f\u4e00\u7b80\u5355\u3001\u9ad8\u6548\u4e14\u516c\u5e73\u7684\u673a\u5236", "abstract_zh": "\u968f\u673a\u4f18\u5148\u662f\u4e00\u79cd\u7528\u4e8e\u5728\u4e0d\u4f7f\u7528\u8d27\u5e01\u8f6c\u79fb\u7684\u60c5\u51b5\u4e0b\u5c06\u4e00\u7ec4\u7269\u54c1\u5206\u914d\u7ed9\u4e00\u7ec4\u4ee3\u7406\u4eba\u7684\u6d41\u884c\u673a\u5236\u3002\u968f\u673a\u4f18\u5148\u673a\u5236\u4e4b\u6240\u4ee5\u53d7\u6b22\u8fce\uff0c\u662f\u56e0\u4e3a\u5b83\u6ee1\u8db3\u4e86\u6548\u7387\u3001\u516c\u5e73\u6027\u548c\u6fc0\u52b1\u65b9\u9762\u7684\u7406\u60f3\u5c5e\u6027\u3002\u5b83\u662f\u5426\u662f\u552f\u4e00\u5177\u6709\u8fd9\u4e9b\u5c5e\u6027\u7684\u673a\u5236\uff1f\u6211\u4eec\u5bf9\u8fd9\u4e00\u957f\u671f\u5b58\u5728\u7684\u95ee\u9898\u7ed9\u51fa\u4e86\u80af\u5b9a\u7b54\u6848\uff1a\u968f\u673a\u4f18\u5148\u662f\u552f\u4e00\u4e00\u4e2a\u540c\u65f6\u6ee1\u8db3\u5e15\u7d2f\u6258\u6548\u7387\u3001\u5bf9\u79f0\u6027\u548c\u660e\u663e\u7b56\u7565\u65e0\u6fc0\u52b1\u6027\u8d28\u7684\u673a\u5236\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta21839", "journal": "ECTA", "title": "Information Design in Common Value Auction With Moral Hazard: Application to OCS Leasing Auctions", "authors": ["Anh Nguyen"], "author_details": [{"name": "Anh Nguyen", "affiliations": ["Tepper School of Business, Carnegie Mellon University"]}], "abstract": "This paper explores the impact of information design on the auctioneer's revenue in the U.S. offshore oil/gas lease auctions where, post\u2010auction, the winner decides whether to explore the auctioned tract and must pay the government a royalty on its production value. I first document that there is a positive correlation between the exploration rate and publicly observed losing bids. This suggests that the winning bidder uses the rivals' bids to infer their private information about the tract's potential. I then characterize the equilibrium bidding strategy when the auctioneer designs and commits to how to reveal information on losing bids to the winning bidder. Counterfactual exercises reveal that alternative bid disclosure policies significantly improve auctioneer revenue.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21839", "title_zh": "\u5728\u5b58\u5728\u9053\u5fb7\u98ce\u9669\u7684\u5171\u540c\u4ef7\u503c\u62cd\u5356\u4e2d\u7684\u4fe1\u606f\u8bbe\u8ba1\uff1a\u5e94\u7528\u4e8e\u6d77\u6d0b\u6cb9\u6c14\u79df\u8d41\u62cd\u5356", "abstract_zh": "\u672c\u6587\u63a2\u8ba8\u4e86\u4fe1\u606f\u8bbe\u8ba1\u5bf9\u7f8e\u56fd\u6d77\u4e0a\u6cb9\u6c14\u79df\u8d41\u62cd\u5356\u62cd\u5356\u4eba\u6536\u5165\u7684\u5f71\u54cd\uff0c\u5176\u4e2d\u83b7\u80dc\u6295\u6807\u4eba\u9700\u51b3\u5b9a\u662f\u5426\u52d8\u63a2\u62cd\u5356\u5730\u5757\uff0c\u5e76\u5411\u653f\u5e9c\u652f\u4ed8\u751f\u4ea7\u4ef7\u503c\u7684\u7279\u8bb8\u6743\u8d39\u3002\u6211\u9996\u5148\u53d1\u73b0\u52d8\u63a2\u7387\u4e0e\u516c\u5f00\u89c2\u5bdf\u5230\u7684\u5931\u8d25\u6295\u6807\u4e4b\u95f4\u5b58\u5728\u6b63\u76f8\u5173\u5173\u7cfb\uff0c\u8fd9\u8868\u660e\u83b7\u80dc\u6295\u6807\u4eba\u5229\u7528\u7ade\u4e89\u5bf9\u624b\u7684\u62a5\u4ef7\u6765\u63a8\u65ad\u5176\u5bf9\u5730\u5757\u6f5c\u529b\u7684\u79c1\u4eba\u4fe1\u606f\u3002\u7136\u540e\uff0c\u6211\u523b\u753b\u4e86\u5f53\u62cd\u5356\u4eba\u8bbe\u8ba1\u5e76\u627f\u8bfa\u5411\u83b7\u80dc\u6295\u6807\u4eba\u62ab\u9732\u5931\u8d25\u6295\u6807\u4fe1\u606f\u7684\u65b9\u5f0f\u65f6\u7684\u5747\u8861\u6295\u6807\u7b56\u7565\u3002\u53cd\u4e8b\u5b9e\u5206\u6790\u8868\u660e\uff0c\u4e0d\u540c\u7684\u6295\u6807\u62ab\u9732\u653f\u7b56\u663e\u8457\u63d0\u9ad8\u4e86\u62cd\u5356\u4eba\u7684\u6536\u5165\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23862", "journal": "ECTA", "title": "Continuity of the Distribution Function of the argmax of a Gaussian Process", "authors": ["Matias D. Cattaneo", "Gregory F. Cox", "Michael Jansson", "Kenichi Nagasawa"], "author_details": [{"name": "Matias D. Cattaneo", "affiliations": ["Department of Operations Research and Financial Engineering, Princeton University"]}, {"name": "Gregory F. Cox", "affiliations": ["Department of Economics, National University of Singapore"]}, {"name": "Michael Jansson", "affiliations": ["Department of Economics, UC Berkeley and ACE"]}, {"name": "Kenichi Nagasawa", "affiliations": ["Department of Economics, University of Warwick"]}], "abstract": "Certain extremum estimators have asymptotic distributions that are non\u2010Gaussian, yet characterizable as the distribution of the arg max of a Gaussian process. This paper presents high\u2010level sufficient conditions under which such asymptotic distributions admit a continuous distribution function. The plausibility of the sufficient conditions is demonstrated by verifying them in three examples, namely, maximum score estimation, empirical risk minimization, and threshold regression estimation. In turn, the continuity result buttresses several recently proposed inference procedures whose validity seems to require a result of the kind established herein. A notable feature of the high\u2010level assumptions is that one of them is designed to enable us to employ the Cameron\u2013Martin theorem. In a leading special case, the assumption in question is demonstrably weak and appears to be close to minimal.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23862", "title_zh": "\u9ad8\u65af\u8fc7\u7a0bargmax\u5206\u5e03\u51fd\u6570\u7684\u8fde\u7eed\u6027", "abstract_zh": "\u67d0\u4e9b\u6781\u503c\u4f30\u8ba1\u91cf\u7684\u6e10\u8fd1\u5206\u5e03\u662f\u975e\u9ad8\u65af\u5206\u5e03\uff0c\u4f46\u53ef\u4ee5\u8868\u5f81\u4e3a\u9ad8\u65af\u8fc7\u7a0barg max\u7684\u5206\u5e03\u3002\u672c\u6587\u63d0\u51fa\u4e86\u82e5\u5e72\u9ad8\u5c42\u5145\u5206\u6761\u4ef6\uff0c\u4ee5\u786e\u4fdd\u6b64\u7c7b\u6e10\u8fd1\u5206\u5e03\u5177\u6709\u8fde\u7eed\u7684\u5206\u5e03\u51fd\u6570\u3002\u901a\u8fc7\u5728\u6700\u5927\u5206\u6570\u4f30\u8ba1\u3001\u7ecf\u9a8c\u98ce\u9669\u6700\u5c0f\u5316\u548c\u9608\u503c\u56de\u5f52\u4f30\u8ba1\u4e09\u4e2a\u4f8b\u5b50\u4e2d\u9a8c\u8bc1\u8fd9\u4e9b\u5145\u5206\u6761\u4ef6\u7684\u5408\u7406\u6027\uff0c\u5c55\u793a\u4e86\u5176\u53ef\u884c\u6027\u3002\u53cd\u8fc7\u6765\uff0c\u8be5\u8fde\u7eed\u6027\u7ed3\u679c\u652f\u6301\u4e86\u8fd1\u671f\u63d0\u51fa\u7684\u82e5\u5e72\u63a8\u65ad\u7a0b\u5e8f\u7684\u6709\u6548\u6027\uff0c\u8fd9\u4e9b\u7a0b\u5e8f\u7684\u6b63\u786e\u6027\u4f3c\u4e4e\u4f9d\u8d56\u4e8e\u672c\u6587\u5efa\u7acb\u7684\u7ed3\u679c\u3002\u8fd9\u4e9b\u9ad8\u5c42\u5047\u8bbe\u7684\u4e00\u4e2a\u663e\u8457\u7279\u70b9\u662f\uff0c\u5176\u4e2d\u4e00\u4e2a\u5047\u8bbe\u65e8\u5728\u4f7f\u6211\u4eec\u80fd\u591f\u5e94\u7528Cameron\u2013Martin\u5b9a\u7406\u3002\u5728\u4e3b\u8981\u7684\u7279\u4f8b\u4e2d\uff0c\u8be5\u5047\u8bbe\u88ab\u8bc1\u660e\u662f\u76f8\u5f53\u5f31\u7684\uff0c\u5e76\u4e14\u4f3c\u4e4e\u63a5\u8fd1\u6700\u5c0f\u5316\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta19350", "journal": "ECTA", "title": "Spatial Economics for Granular Settings", "authors": ["Jonathan I. Dingel", "Felix Tintelnot"], "author_details": [{"name": "Jonathan I. Dingel", "affiliations": ["Department of Economics, Columbia University", "NBER", "CEPR"]}, {"name": "Felix Tintelnot", "affiliations": ["Department of Economics, Duke University", "NBER", "CEPR"]}], "abstract": "We examine the application of quantitative spatial models to the growing body of fine spatial data used to study local economic outcomes. In granular settings in which people choose from a large set of potential residence\u2010workplace pairs, observed outcomes in part reflect idiosyncratic choices. Using analytical examples, Monte Carlo simulations, and event studies of neighborhood employment booms, we demonstrate that calibration procedures that equate observed shares and modeled probabilities perform very poorly in these high\u2010dimensional settings. Parsimonious specifications of spatial linkages deliver better counterfactual predictions. To quantify the uncertainty about counterfactual outcomes induced by the idiosyncratic component of individuals' decisions, we introduce a quantitative spatial model with a finite number of individuals. Applying this model to Amazon's proposed second headquarters in New York City reveals that its predicted consequences for most neighborhoods vary substantially across realizations of the individual idiosyncrasies.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta19350", "title_zh": "\u7ec6\u7c92\u5ea6\u60c5\u5883\u4e0b\u7684\u7a7a\u95f4\u7ecf\u6d4e\u5b66", "abstract_zh": "\u6211\u4eec\u8003\u5bdf\u4e86\u5b9a\u91cf\u7a7a\u95f4\u6a21\u578b\u5728\u7528\u4e8e\u7814\u7a76\u672c\u5730\u7ecf\u6d4e\u7ed3\u679c\u7684\u65e5\u76ca\u4e30\u5bcc\u7684\u7ec6\u7c92\u5ea6\u7a7a\u95f4\u6570\u636e\u4e2d\u7684\u5e94\u7528\u3002\u5728\u4eba\u4eec\u4ece\u5927\u91cf\u6f5c\u5728\u7684\u5c45\u4f4f-\u5de5\u4f5c\u5730\u70b9\u914d\u5bf9\u4e2d\u8fdb\u884c\u9009\u62e9\u7684\u7ec6\u7c92\u5ea6\u60c5\u5883\u4e2d\uff0c\u89c2\u5bdf\u5230\u7684\u7ed3\u679c\u5728\u4e00\u5b9a\u7a0b\u5ea6\u4e0a\u53cd\u6620\u4e86\u4e2a\u4f53\u7684\u7279\u6709\u9009\u62e9\u3002\u901a\u8fc7\u5206\u6790\u793a\u4f8b\u3001\u8499\u7279\u5361\u6d1b\u6a21\u62df\u4ee5\u53ca\u5bf9\u90bb\u91cc\u5c31\u4e1a\u7e41\u8363\u4e8b\u4ef6\u7684\u7814\u7a76\uff0c\u6211\u4eec\u8bc1\u660e\u4e86\u5c06\u89c2\u5bdf\u5230\u7684\u6bd4\u4f8b\u4e0e\u6a21\u578b\u6982\u7387\u76f8\u7b49\u7684\u6821\u51c6\u7a0b\u5e8f\u5728\u8fd9\u4e9b\u9ad8\u7ef4\u60c5\u5883\u4e2d\u8868\u73b0\u975e\u5e38\u5dee\u3002\u7b80\u6d01\u7684\u7a7a\u95f4\u8054\u7cfb\u8bbe\u5b9a\u80fd\u591f\u63d0\u4f9b\u66f4\u597d\u7684\u53cd\u4e8b\u5b9e\u9884\u6d4b\u3002\u4e3a\u4e86\u91cf\u5316\u7531\u4e2a\u4f53\u51b3\u7b56\u4e2d\u7684\u7279\u6709\u6210\u5206\u6240\u5f15\u8d77\u7684\u53cd\u4e8b\u5b9e\u7ed3\u679c\u7684\u4e0d\u786e\u5b9a\u6027\uff0c\u6211\u4eec\u5f15\u5165\u4e86\u4e00\u4e2a\u5305\u542b\u6709\u9650\u6570\u91cf\u4e2a\u4f53\u7684\u5b9a\u91cf\u7a7a\u95f4\u6a21\u578b\u3002\u5c06\u8be5\u6a21\u578b\u5e94\u7528\u4e8e\u4e9a\u9a6c\u900a\u5728\u7ebd\u7ea6\u5e02\u63d0\u8bae\u7684\u7b2c\u4e8c\u603b\u90e8\u9879\u76ee\uff0c\u53d1\u73b0\u5176\u5bf9\u5927\u591a\u6570\u90bb\u91cc\u9884\u6d4b\u540e\u679c\u5728\u4e2a\u4f53\u7279\u6709\u6027\u4e0d\u540c\u5b9e\u73b0\u4e4b\u95f4\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23242", "journal": "ECTA", "title": "Locally Robust Semiparametrically Efficient Bayesian Inference", "authors": ["Ulrich M\u00fcller", "Andriy Norets"], "author_details": [{"name": "Ulrich M\u00fcller", "affiliations": ["Economics Department, Princeton University"]}, {"name": "Andriy Norets", "affiliations": ["Economics Department, Brown University"]}], "abstract": "We propose a framework for making Bayesian parametric models robust to local misspecification. Suppose in a baseline parametric model, a parameter of interest has an interpretation in an encompassing semiparametric model. Bayesian and maximum likelihood estimators are generally biased under local misspecification. We propose to augment the baseline likelihood by a multiplicative factor that involves scores for the baseline model, the efficient scores for the encompassing semiparametric model, and an auxiliary parameter that has the same dimension as the parameter of interest. We show that the marginal posterior for the parameter of interest in the augmented model is asymptotically normal with mean equal to the semiparametrically efficient estimator and variance equal to the semiparametric efficiency bound. The suggested augmentation robustifies the baseline parametric model to local misspecification, while preserving the appeal of Bayesian inference. We develop an MCMC algorithm for the augmented model and illustrate the approach in applications.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23242", "title_zh": "\u5c40\u90e8\u7a33\u5065\u7684\u534a\u53c2\u6570\u5316\u9ad8\u6548\u8d1d\u53f6\u65af\u63a8\u65ad", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u4f7f\u8d1d\u53f6\u65af\u53c2\u6570\u6a21\u578b\u5bf9\u5c40\u90e8\u89c4\u683c\u9519\u8bef\u5177\u6709\u9c81\u68d2\u6027\u7684\u6846\u67b6\u3002\u5047\u8bbe\u5728\u57fa\u51c6\u53c2\u6570\u6a21\u578b\u4e2d\uff0c\u4e00\u4e2a\u611f\u5174\u8da3\u7684\u53c2\u6570\u5728\u5305\u542b\u6027\u7684\u534a\u53c2\u6570\u6a21\u578b\u4e2d\u6709\u660e\u786e\u7684\u89e3\u91ca\u3002\u5728\u5c40\u90e8\u89c4\u683c\u9519\u8bef\u4e0b\uff0c\u8d1d\u53f6\u65af\u548c\u6700\u5927\u4f3c\u7136\u4f30\u8ba1\u901a\u5e38\u5b58\u5728\u504f\u501a\u3002\u6211\u4eec\u5efa\u8bae\u901a\u8fc7\u4e00\u4e2a\u4e58\u6cd5\u56e0\u5b50\u6765\u6269\u5c55\u57fa\u51c6\u4f3c\u7136\u51fd\u6570\uff0c\u8be5\u56e0\u5b50\u5305\u542b\u57fa\u51c6\u6a21\u578b\u7684\u5f97\u5206\u3001\u5305\u542b\u6027\u534a\u53c2\u6570\u6a21\u578b\u7684\u9ad8\u6548\u5f97\u5206\u4ee5\u53ca\u4e00\u4e2a\u4e0e\u611f\u5174\u8da3\u7684\u53c2\u6570\u7ef4\u5ea6\u76f8\u540c\u7684\u8f85\u52a9\u53c2\u6570\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5728\u6269\u5c55\u6a21\u578b\u4e2d\uff0c\u5bf9\u611f\u5174\u8da3\u7684\u53c2\u6570\u7684\u8fb9\u9645\u540e\u9a8c\u5206\u5e03\u662f\u6e10\u8fd1\u6b63\u6001\u7684\uff0c\u5176\u5747\u503c\u7b49\u4e8e\u534a\u53c2\u6570\u5316\u9ad8\u6548\u4f30\u8ba1\u91cf\uff0c\u65b9\u5dee\u7b49\u4e8e\u534a\u53c2\u6570\u5316\u6548\u7387\u4e0b\u9650\u3002\u6240\u63d0\u51fa\u7684\u6269\u5c55\u65b9\u6cd5\u4f7f\u57fa\u51c6\u53c2\u6570\u6a21\u578b\u5bf9\u5c40\u90e8\u89c4\u683c\u9519\u8bef\u5177\u6709\u9c81\u68d2\u6027\uff0c\u540c\u65f6\u4fdd\u7559\u4e86\u8d1d\u53f6\u65af\u63a8\u65ad\u7684\u5438\u5f15\u529b\u3002\u6211\u4eec\u4e3a\u6269\u5c55\u6a21\u578b\u5f00\u53d1\u4e86\u4e00\u79cdMCMC\u7b97\u6cd5\uff0c\u5e76\u5728\u5e94\u7528\u4e2d\u5c55\u793a\u4e86\u8be5\u65b9\u6cd5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22979", "journal": "ECTA", "title": "The Equilibrium Effects of Campaign Finance Deregulation on U.S. Elections", "authors": ["Christian Cox"], "author_details": [{"name": "Christian Cox", "affiliations": ["Department of Economics, University of Arizona"]}], "abstract": "The U.S. Supreme Court's 2010 decision in Citizens United v. Federal Election Commission deregulated campaign finance, enabling the rise of a new political action committee (the Super PAC) with broad freedom to raise and spend money. This led to an unprecedented surge in spending in primary and general elections. To evaluate the impact of Super PACs, I estimate a multistage model of political competition using data from U.S. Congressional elections between 2010 and 2020. I find that Super PAC spending by both sides prompts offsetting responses, resulting in limited net equilibrium effects. However, by amplifying the role of donors, Super PACs still have the potential to reshape the electoral landscape.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22979", "title_zh": "\u7ade\u9009\u8d44\u91d1 deregulation \u5bf9\u7f8e\u56fd\u9009\u4e3e\u5747\u8861\u6548\u5e94\u7684\u7814\u7a76", "abstract_zh": "\u7f8e\u56fd\u6700\u9ad8\u6cd5\u96622010\u5e74\u5728\u2018Citizens United v. \u8054\u90a6\u9009\u4e3e\u59d4\u5458\u4f1a\u2019\u6848\u4e2d\u7684\u88c1\u51b3\u53d6\u6d88\u4e86\u7ade\u9009\u8d44\u91d1\u7684\u76d1\u7ba1\uff0c\u4f7f\u5f97\u4e00\u79cd\u65b0\u7684\u653f\u6cbb\u884c\u52a8\u59d4\u5458\u4f1a\uff08\u5373\u8d85\u7ea7\u653f\u6cbb\u884c\u52a8\u59d4\u5458\u4f1a\uff0cSuper PAC\uff09\u5f97\u4ee5\u51fa\u73b0\uff0c\u5176\u5728\u7b79\u96c6\u548c\u652f\u51fa\u8d44\u91d1\u65b9\u9762\u62e5\u6709\u5e7f\u6cdb\u81ea\u7531\u3002\u8fd9\u5bfc\u81f4\u4e86\u521d\u9009\u548c\u5927\u9009\u4e2d\u652f\u51fa\u7684\u7a7a\u524d\u6fc0\u589e\u3002\u4e3a\u4e86\u8bc4\u4f30\u8d85\u7ea7\u653f\u6cbb\u884c\u52a8\u59d4\u5458\u4f1a\u7684\u5f71\u54cd\uff0c\u6211\u5229\u75282010\u5e74\u81f32020\u5e74\u671f\u95f4\u7f8e\u56fd\u56fd\u4f1a\u8bae\u5458\u9009\u4e3e\u7684\u6570\u636e\uff0c\u6784\u5efa\u4e86\u4e00\u4e2a\u591a\u9636\u6bb5\u653f\u6cbb\u7ade\u4e89\u6a21\u578b\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u53cc\u65b9\u8d85\u7ea7\u653f\u6cbb\u884c\u52a8\u59d4\u5458\u4f1a\u7684\u652f\u51fa\u4f1a\u5f15\u53d1\u76f8\u4e92\u62b5\u6d88\u7684\u53cd\u5e94\uff0c\u5bfc\u81f4\u6574\u4f53\u5747\u8861\u6548\u5e94\u6709\u9650\u3002\u7136\u800c\uff0c\u8d85\u7ea7\u653f\u6cbb\u884c\u52a8\u59d4\u5458\u4f1a\u901a\u8fc7\u653e\u5927\u6350\u8d60\u8005\u7684\u4f5c\u7528\uff0c\u4ecd\u6709\u53ef\u80fd\u91cd\u5851\u9009\u4e3e\u683c\u5c40\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22110", "journal": "ECTA", "title": "Economic Growth and the Rise of Large Firms", "authors": ["Zhang Chen"], "author_details": [{"name": "Zhang Chen", "affiliations": ["Department of Economics, The Hong Kong University of Science and Technology"]}], "abstract": "I document that the right tail of the firm size distribution systematically thickens with economic development. To rationalize this fact, I develop a parsimonious idea search model in which both aggregate growth and the firm size distribution are endogenously determined. The model features an asymptotic balanced growth path along which Gibrat's law holds at each date, and the right tail of the firm size distribution thickens monotonically toward Zipf's law. The model also implies that policies favoring large firms can improve welfare by better utilizing the diffusion externalities arising from idea search.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22110", "title_zh": "\u7ecf\u6d4e\u589e\u957f\u4e0e\u5927\u578b\u4f01\u4e1a\u7684\u5174\u8d77", "abstract_zh": "\u6211\u8bc1\u660e\u4e86\u4f01\u4e1a\u89c4\u6a21\u5206\u5e03\u7684\u53f3\u5c3e\u968f\u7740\u7ecf\u6d4e\u53d1\u5c55\u7cfb\u7edf\u6027\u5730\u53d8\u539a\u3002\u4e3a\u89e3\u91ca\u8fd9\u4e00\u73b0\u8c61\uff0c\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u7b80\u6d01\u7684\u521b\u65b0\u641c\u7d22\u6a21\u578b\uff0c\u5176\u4e2d\u7ecf\u6d4e\u589e\u957f\u548c\u4f01\u4e1a\u89c4\u6a21\u5206\u5e03\u90fd\u662f\u5185\u751f\u51b3\u5b9a\u7684\u3002\u8be5\u6a21\u578b\u5177\u6709\u6e10\u8fd1\u5e73\u8861\u589e\u957f\u8def\u5f84\uff0c\u5728\u8be5\u8def\u5f84\u4e0a\u6bcf\u4e2a\u65f6\u671f\u90fd\u6ee1\u8db3\u683c\u62c9\u5e03\u7279\u5b9a\u5f8b\uff0c\u4e14\u4f01\u4e1a\u89c4\u6a21\u5206\u5e03\u7684\u53f3\u5c3e\u5355\u8c03\u5730\u8d8b\u8fd1\u4e8e\u9f50\u592b\u5b9a\u5f8b\u3002\u6a21\u578b\u8fd8\u8868\u660e\uff0c\u6709\u5229\u4e8e\u5927\u578b\u4f01\u4e1a\u7684\u653f\u7b56\u53ef\u4ee5\u901a\u8fc7\u66f4\u6709\u6548\u5730\u5229\u7528\u521b\u65b0\u641c\u7d22\u4ea7\u751f\u7684\u6269\u6563\u5916\u90e8\u6027\u6765\u63d0\u5347\u798f\u5229\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22160", "journal": "ECTA", "title": "An Experimental Evaluation of Deferred Acceptance: Evidence From Over 100 Army Officer Labor Markets", "authors": ["Jonathan M.V. Davis", "Kyle Greenberg", "Damon Jones"], "author_details": [{"name": "Jonathan M.V. Davis", "affiliations": ["Department of Economics, University of Oregon"]}, {"name": "Kyle Greenberg", "affiliations": ["Department of Social Sciences, West Point", "NBER", "IZA"]}, {"name": "Damon Jones", "affiliations": ["Harris School of Public Policy, University of Chicago"]}], "abstract": "Internal labor markets are increasingly important for matching workers to jobs within organizations. We present evidence from a randomized trial that compares matching workers to jobs using the deferred acceptance (DA) algorithm to the traditional manager\u2010directed matching process. Our setting is the U.S. Army's internal labor market, which matches over 14,000 officers to units annually. We find that DA reduces administrative burden and increases match quality as measured by reduced justified envy, increased truthful preference reporting, and officers' and units' preferences over their matches. The overall impact of DA on officer retention and performance in the two years after officers started their new jobs is limited by strategic preference coordination between officers and units. However, DA leads to significant improvements in officer retention and promotions in markets with inexperienced managers. Our findings suggest that cross\u2010market communication between agents in internal labor markets can attenuate the benefits of strategyproof matching algorithms.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22160", "title_zh": "\u4e00\u79cd\u5b9e\u9a8c\u8bc4\u4f30\uff1a\u6765\u81ea\u8d85\u8fc7100\u4e2a\u9646\u519b\u519b\u5b98\u52b3\u52a8\u529b\u5e02\u573a\u7684deferred acceptance\u8bc1\u636e", "abstract_zh": "\u5185\u90e8\u52b3\u52a8\u529b\u5e02\u573a\u5728\u7ec4\u7ec7\u5185\u90e8\u5339\u914d\u5458\u5de5\u4e0e\u5c97\u4f4d\u65b9\u9762\u65e5\u76ca\u91cd\u8981\u3002\u6211\u4eec\u57fa\u4e8e\u4e00\u9879\u968f\u673a\u8bd5\u9a8c\uff0c\u6bd4\u8f83\u4e86\u4f7f\u7528deferred acceptance\uff08DA\uff09\u7b97\u6cd5\u4e0e\u4f20\u7edf\u7531\u7ba1\u7406\u8005\u76f4\u63a5\u4e3b\u5bfc\u7684\u5339\u914d\u8fc7\u7a0b\u3002\u6211\u4eec\u7684\u7814\u7a76\u573a\u666f\u662f\u7f8e\u56fd\u9646\u519b\u7684\u5185\u90e8\u52b3\u52a8\u529b\u5e02\u573a\uff0c\u6bcf\u5e74\u5c06\u8d85\u8fc714,000\u540d\u519b\u5b98\u5339\u914d\u5230\u4e0d\u540c\u7684\u5355\u4f4d\u3002\u7814\u7a76\u53d1\u73b0\uff0cDA\u7b97\u6cd5\u964d\u4f4e\u4e86\u884c\u653f\u8d1f\u62c5\uff0c\u5e76\u63d0\u9ad8\u4e86\u5339\u914d\u8d28\u91cf\uff0c\u8868\u73b0\u4e3a\u51cf\u5c11\u5408\u7406\u5ac9\u5992\u3001\u63d0\u9ad8\u504f\u597d\u62a5\u544a\u7684\u771f\u5b9e\u6027\uff0c\u4ee5\u53ca\u519b\u5b98\u548c\u5355\u4f4d\u5bf9\u5339\u914d\u7ed3\u679c\u7684\u6ee1\u610f\u5ea6\u3002\u7136\u800c\uff0cDA\u5bf9\u519b\u5b98\u5728\u5165\u804c\u540e\u4e24\u5e74\u5185\u7684\u7559\u4efb\u7387\u548c\u7ee9\u6548\u7684\u5f71\u54cd\u53d7\u5230\u519b\u5b98\u4e0e\u5355\u4f4d\u4e4b\u95f4\u7b56\u7565\u6027\u504f\u597d\u534f\u8c03\u7684\u9650\u5236\u3002\u4e0d\u8fc7\uff0c\u5728\u7f3a\u4e4f\u7ecf\u9a8c\u7684\u7ba1\u7406\u8005\u4e3b\u5bfc\u7684\u5e02\u573a\u4e2d\uff0cDA\u663e\u8457\u63d0\u5347\u4e86\u519b\u5b98\u7684\u7559\u4efb\u7387\u548c\u664b\u5347\u7387\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u5185\u90e8\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u4ee3\u7406\u4e4b\u95f4\u7684\u8de8\u5e02\u573a\u6c9f\u901a\u53ef\u80fd\u4f1a\u524a\u5f31\u7b56\u7565\u6027\u5339\u914d\u7b97\u6cd5\u7684\u6548\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta23874", "journal": "ECTA", "title": "Why Do Workers Dislike Inflation? Wage Erosion and Conflict Costs", "authors": ["Joao Guerreiro", "Jonathon Hazell", "Chen Lian", "Christina Patterson"], "author_details": [{"name": "Joao Guerreiro", "affiliations": ["Department of Economics, UCLA", "NBER"]}, {"name": "Jonathon Hazell", "affiliations": ["Department of Economics, London School of Economics", "CEPR"]}, {"name": "Chen Lian", "affiliations": ["Department of Economics, UC Berkeley", "NBER"]}, {"name": "Christina Patterson", "affiliations": ["Booth School of Business, University of Chicago", "NBER"]}], "abstract": "How costly is inflation to workers? Answers to this question have focused on the path of real wages during inflationary periods. We argue that workers must take costly actions (\u201cconflict\u201d) to have nominal wages catch up with inflation, meaning there are welfare costs even if real wages do not fall as inflation rises. We study a menu\u2010cost style model, where workers choose whether to engage in conflict with employers to secure a wage increase. We show that, following a rise in inflation, wage catch\u2010up resulting from more frequent conflict does not raise welfare. Instead, the impact of inflation on worker welfare is determined by what we call \u201cwage erosion\u201d\u2014how inflation would lower real wages if workers' conflict decisions did not respond to inflation. As a result, using observed wage growth to measure worker welfare understates the costs of inflation. We conduct a survey showing that workers are willing to sacrifice around 1.75% of their wages to avoid conflict. Calibrating the model to survey data, we find that incorporating conflict significantly raises the costs of inflation for workers.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta23874", "title_zh": "\u5de5\u4eba\u4e3a\u4ec0\u4e48\u538c\u6076\u901a\u80c0\uff1f\u5de5\u8d44\u4fb5\u8680\u4e0e\u51b2\u7a81\u6210\u672c", "abstract_zh": "\u901a\u80c0\u5bf9\u5de5\u4eba\u7684\u6210\u672c\u6709\u591a\u5927\uff1f\u4ee5\u5f80\u5bf9\u6b64\u95ee\u9898\u7684\u56de\u7b54\u4e3b\u8981\u96c6\u4e2d\u5728\u901a\u80c0\u671f\u95f4\u5b9e\u9645\u5de5\u8d44\u7684\u53d8\u5316\u8def\u5f84\u4e0a\u3002\u6211\u4eec\u6307\u51fa\uff0c\u5de5\u4eba\u5fc5\u987b\u91c7\u53d6\u4ee3\u4ef7\u9ad8\u6602\u7684\u884c\u52a8\uff08\u201c\u51b2\u7a81\u201d\uff09\u6765\u4f7f\u540d\u4e49\u5de5\u8d44\u8ddf\u4e0a\u901a\u80c0\uff0c\u8fd9\u610f\u5473\u7740\u5373\u4f7f\u5b9e\u9645\u5de5\u8d44\u5728\u901a\u80c0\u4e0a\u5347\u8fc7\u7a0b\u4e2d\u6ca1\u6709\u4e0b\u964d\uff0c\u4e5f\u5b58\u5728\u798f\u5229\u635f\u5931\u3002\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u79cd\u83dc\u5355\u6210\u672c\u6a21\u578b\uff0c\u5176\u4e2d\u5de5\u4eba\u9009\u62e9\u662f\u5426\u4e0e\u96c7\u4e3b\u53d1\u751f\u51b2\u7a81\u4ee5\u4e89\u53d6\u5de5\u8d44\u4e0a\u6da8\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u901a\u80c0\u4e0a\u5347\u540e\uff0c\u7531\u4e8e\u51b2\u7a81\u9891\u7387\u589e\u52a0\u800c\u5bfc\u81f4\u7684\u5de5\u8d44\u8ffd\u8d76\u5e76\u4e0d\u4f1a\u63d0\u5347\u5de5\u4eba\u7684\u798f\u5229\u3002\u76f8\u53cd\uff0c\u901a\u80c0\u5bf9\u5de5\u4eba\u798f\u5229\u7684\u5f71\u54cd\u7531\u6211\u4eec\u79f0\u4e4b\u4e3a\u201c\u5de5\u8d44\u4fb5\u8680\u201d\u7684\u56e0\u7d20\u51b3\u5b9a\u2014\u2014\u5373\u5728\u5de5\u4eba\u4e0d\u56e0\u901a\u80c0\u8c03\u6574\u5176\u51b2\u7a81\u51b3\u7b56\u7684\u60c5\u51b5\u4e0b\uff0c\u901a\u80c0\u4f1a\u964d\u4f4e\u5b9e\u9645\u5de5\u8d44\u3002\u56e0\u6b64\uff0c\u4ec5\u4f7f\u7528\u89c2\u5bdf\u5230\u7684\u5de5\u8d44\u589e\u957f\u6765\u8861\u91cf\u5de5\u4eba\u7684\u798f\u5229\uff0c\u4f1a\u4f4e\u4f30\u901a\u80c0\u7684\u6210\u672c\u3002\u6211\u4eec\u8fdb\u884c\u4e86\u4e00\u9879\u8c03\u67e5\uff0c\u53d1\u73b0\u5de5\u4eba\u613f\u610f\u727a\u7272\u7ea61.75%\u7684\u5de5\u8d44\u4ee5\u907f\u514d\u51b2\u7a81\u3002\u5c06\u6a21\u578b\u6821\u51c6\u5230\u8c03\u67e5\u6570\u636e\u540e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u7eb3\u5165\u51b2\u7a81\u56e0\u7d20\u4f1a\u663e\u8457\u63d0\u9ad8\u901a\u80c0\u5bf9\u5de5\u4eba\u7684\u6210\u672c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22451", "journal": "ECTA", "title": "Walras\u2013Bowley Lecture: Climate Policy in the Wide World", "authors": ["John Hassler", "Per Krusell", "Conny Olovsson"], "author_details": [{"name": "John Hassler", "affiliations": ["IIES, Stockholm University"]}, {"name": "Per Krusell", "affiliations": ["IIES, Stockholm University"]}, {"name": "Conny Olovsson", "affiliations": ["Research Division, Sveriges Riksbank"]}], "abstract": "We construct a dynamic integrated assessment model of climate and the economy with very high geographic resolution. Migration is free within, but not allowed across, countries. The model parameterization uses a wealth of data, including the distribution of output, population, energy sources and use, and estimates of the local damages from climate change. It implies very large geographic dispersion in damages from warming. We conduct three kinds of policy experiments. In one, we note that a modest, uniform carbon tax limits global warming and damages around the world substantially. In a second experiment, we let the poorest countries not tax carbon, while the rest compensate by setting higher taxes; the efficiency losses are large. In a final experiment, we find that fast green technology growth alone is a poor substitute for carbon taxes, whether globally available or not.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22451", "title_zh": "\u74e6\u5c14\u62c9\u65af-\u535a\u5229\u8bb2\u5ea7\uff1a\u5168\u7403\u8303\u56f4\u5185\u7684\u6c14\u5019\u653f\u7b56", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5177\u6709\u6781\u9ad8\u5730\u7406\u5206\u8fa8\u7387\u7684\u52a8\u6001\u7efc\u5408\u8bc4\u4f30\u6a21\u578b\uff0c\u7528\u4e8e\u5206\u6790\u6c14\u5019\u4e0e\u7ecf\u6d4e\u7684\u5173\u7cfb\u3002\u4eba\u53e3\u5728\u56fd\u5883\u5185\u53ef\u4ee5\u81ea\u7531\u8fc1\u79fb\uff0c\u4f46\u4e0d\u5141\u8bb8\u8de8\u56fd\u8fc1\u79fb\u3002\u6a21\u578b\u7684\u53c2\u6570\u8bbe\u5b9a\u5229\u7528\u4e86\u5927\u91cf\u6570\u636e\uff0c\u5305\u62ec\u4ea7\u51fa\u5206\u5e03\u3001\u4eba\u53e3\u5206\u5e03\u3001\u80fd\u6e90\u6765\u6e90\u4e0e\u4f7f\u7528\u60c5\u51b5\uff0c\u4ee5\u53ca\u6c14\u5019\u53d8\u5316\u5bf9\u5404\u5730\u9020\u6210\u7684\u635f\u5bb3\u4f30\u8ba1\u3002\u8be5\u6a21\u578b\u8868\u660e\uff0c\u6c14\u5019\u53d8\u5316\u5e26\u6765\u7684\u635f\u5bb3\u5728\u5730\u7406\u4e0a\u5177\u6709\u6781\u5927\u7684\u5206\u6563\u6027\u3002\u6211\u4eec\u8fdb\u884c\u4e86\u4e09\u79cd\u653f\u7b56\u5b9e\u9a8c\u3002\u5728\u7b2c\u4e00\u79cd\u5b9e\u9a8c\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u4e00\u4e2a\u9002\u5ea6\u4e14\u7edf\u4e00\u7684\u78b3\u7a0e\u80fd\u591f\u663e\u8457\u9650\u5236\u5168\u7403\u53d8\u6696\u53ca\u5176\u5e26\u6765\u7684\u635f\u5bb3\u3002\u5728\u7b2c\u4e8c\u79cd\u5b9e\u9a8c\u4e2d\uff0c\u6211\u4eec\u8ba9\u6700\u8d2b\u7a77\u7684\u56fd\u5bb6\u4e0d\u5f81\u6536\u78b3\u7a0e\uff0c\u800c\u5176\u4f59\u56fd\u5bb6\u901a\u8fc7\u63d0\u9ad8\u78b3\u7a0e\u8fdb\u884c\u8865\u507f\uff0c\u7ed3\u679c\u5bfc\u81f4\u5de8\u5927\u7684\u6548\u7387\u635f\u5931\u3002\u5728\u6700\u7ec8\u7684\u5b9e\u9a8c\u4e2d\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5373\u4f7f\u7eff\u8272\u6280\u672f\u53d1\u5c55\u8fc5\u901f\uff0c\u4ec5\u9760\u6280\u672f\u8fdb\u6b65\u4e5f\u96be\u4ee5\u66ff\u4ee3\u78b3\u7a0e\uff0c\u65e0\u8bba\u662f\u5168\u7403\u8303\u56f4\u5185\u53ef\u83b7\u5f97\u8fd8\u662f\u4e0d\u53ef\u83b7\u5f97\u7684\u60c5\u51b5\u4e0b\u90fd\u662f\u5982\u6b64\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22386", "journal": "ECTA", "title": "Optimal Shrinkage Estimation of Fixed Effects in Linear Panel Data Models", "authors": ["Soonwoo Kwon"], "author_details": [{"name": "Soonwoo Kwon", "affiliations": ["Department of Economics, Brown University"]}], "abstract": "Shrinkage methods are frequently used to improve the precision of least squares estimators of fixed effects. However, widely used shrinkage estimators guarantee improved precision only under strong distributional assumptions. I develop an estimator for the fixed effects that obtains the best possible mean squared error within a class of shrinkage estimators. This class includes conventional shrinkage estimators and the optimality does not require distributional assumptions. The estimator has an intuitive form and is easy to implement. Moreover, the fixed effects are allowed to vary with time and to be serially correlated, in which case the shrinkage optimally incorporates the underlying correlation structure. I also provide a method to forecast fixed effects one period ahead in this setting.", "date": "2026", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22386", "title_zh": "\u7ebf\u6027\u9762\u677f\u6570\u636e\u6a21\u578b\u4e2d\u56fa\u5b9a\u6548\u5e94\u7684\u6700\u4f18\u6536\u7f29\u4f30\u8ba1", "abstract_zh": "\u6536\u7f29\u65b9\u6cd5\u5e38\u88ab\u7528\u4e8e\u63d0\u9ad8\u56fa\u5b9a\u6548\u5e94\u6700\u5c0f\u4e8c\u4e58\u4f30\u8ba1\u7684\u7cbe\u5ea6\u3002\u7136\u800c\uff0c\u5e7f\u6cdb\u4f7f\u7528\u7684\u6536\u7f29\u4f30\u8ba1\u91cf\u4ec5\u5728\u5f3a\u5206\u5e03\u5047\u8bbe\u4e0b\u624d\u80fd\u4fdd\u8bc1\u7cbe\u5ea6\u63d0\u5347\u3002\u672c\u6587\u63d0\u51fa\u4e86\u4e00\u79cd\u56fa\u5b9a\u6548\u5e94\u7684\u4f30\u8ba1\u91cf\uff0c\u8be5\u4f30\u8ba1\u91cf\u5728\u4e00\u7c7b\u6536\u7f29\u4f30\u8ba1\u91cf\u4e2d\u5b9e\u73b0\u4e86\u6700\u5c0f\u7684\u5747\u65b9\u8bef\u5dee\u3002\u8fd9\u4e00\u7c7b\u4f30\u8ba1\u91cf\u5305\u542b\u4f20\u7edf\u6536\u7f29\u4f30\u8ba1\u91cf\uff0c\u4e14\u5176\u6700\u4f18\u6027\u65e0\u9700\u4f9d\u8d56\u5206\u5e03\u5047\u8bbe\u3002\u8be5\u4f30\u8ba1\u91cf\u5f62\u5f0f\u76f4\u89c2\uff0c\u6613\u4e8e\u5b9e\u65bd\u3002\u6b64\u5916\uff0c\u56fa\u5b9a\u6548\u5e94\u5141\u8bb8\u968f\u65f6\u95f4\u53d8\u5316\u4e14\u5b58\u5728\u5e8f\u5217\u76f8\u5173\u6027\uff0c\u5728\u8fd9\u79cd\u60c5\u51b5\u4e0b\uff0c\u6536\u7f29\u4f30\u8ba1\u91cf\u80fd\u591f\u6700\u4f18\u5730\u7eb3\u5165\u6f5c\u5728\u7684\u5e8f\u5217\u76f8\u5173\u7ed3\u6784\u3002\u6211\u8fd8\u63d0\u4f9b\u4e86\u4e00\u79cd\u5728\u6b64\u8bbe\u5b9a\u4e0b\u5bf9\u56fa\u5b9a\u6548\u5e94\u8fdb\u884c\u4e00\u671f\u524d\u5411\u9884\u6d4b\u7684\u65b9\u6cd5\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhaf114", "journal": "RFS", "title": "When Two Become One: Foreign Capital and Household Credit Expansion", "authors": ["Lukas Diebold", "Bj\u00f6rn Richter"], "author_details": [{"name": "Lukas Diebold", "affiliations": ["University Carlos III of Madrid ,"]}, {"name": "Bj\u00f6rn Richter", "affiliations": ["Nova School of Business and Economics, Portugal, and UPF-BSE ,"]}], "abstract": "Abstract Rapid credit expansions predict lower output growth and banking crises, but does it matter who finances them? We identify the ultimate counterparties financing credit expansions in a panel of 33 advanced economies and find that foreign-financed household credit expansions predict lower GDP growth and higher crisis risk, but domestically financed credit expansions do not. Studying the mechanisms, we find that foreign-financed household credit expansions are accompanied by higher supply of foreign capital (reflected in low credit spreads), are followed by elevated credit cycle reversal risk, and lead to higher debt service payments to foreigners which depress aggregate demand.", "date": "2025-12-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf114", "title_zh": "\u4e8c\u5408\u4e3a\u4e00\uff1a\u5916\u56fd\u8d44\u672c\u4e0e\u5bb6\u5ead\u4fe1\u8d37\u6269\u5f20", "abstract_zh": "\u6458\u8981 \u4fe1\u8d37\u6269\u5f20\u901a\u5e38\u9884\u793a\u7740\u4ea7\u51fa\u589e\u957f\u653e\u7f13\u548c\u94f6\u884c\u5371\u673a\uff0c\u4f46\u7531\u8c01\u6765\u878d\u8d44\u5219\u81f3\u5173\u91cd\u8981\uff1f\u6211\u4eec\u57fa\u4e8e33\u4e2a\u53d1\u8fbe\u7ecf\u6d4e\u4f53\u7684\u9762\u677f\u6570\u636e\uff0c\u8bc6\u522b\u4e86\u4fe1\u8d37\u6269\u5f20\u7684\u6700\u7ec8\u5bf9\u51b2\u65b9\uff0c\u53d1\u73b0\u7531\u5916\u56fd\u8d44\u672c\u878d\u8d44\u7684\u5bb6\u5ead\u4fe1\u8d37\u6269\u5f20\u4f1a\u5e26\u6765\u66f4\u4f4e\u7684GDP\u589e\u957f\u548c\u66f4\u9ad8\u7684\u5371\u673a\u98ce\u9669\uff0c\u800c\u7531\u56fd\u5185\u8d44\u672c\u878d\u8d44\u7684\u4fe1\u8d37\u6269\u5f20\u5219\u4e0d\u4f1a\u3002\u901a\u8fc7\u5206\u6790\u673a\u5236\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u7531\u5916\u56fd\u8d44\u672c\u878d\u8d44\u7684\u5bb6\u5ead\u4fe1\u8d37\u6269\u5f20\u4f34\u968f\u7740\u5916\u56fd\u8d44\u672c\u4f9b\u7ed9\u7684\u589e\u52a0\uff08\u8868\u73b0\u4e3a\u4fe1\u8d37\u5229\u5dee\u8f83\u4f4e\uff09\uff0c\u968f\u540e\u51fa\u73b0\u4fe1\u8d37\u5468\u671f\u9006\u8f6c\u7684\u98ce\u9669\u4e0a\u5347\uff0c\u5e76\u5bfc\u81f4\u5bf9\u5916\u56fd\u7684\u503a\u52a1\u507f\u4ed8\u589e\u52a0\uff0c\u4ece\u800c\u6291\u5236\u603b\u9700\u6c42\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1093/rfs/hhaf116", "journal": "RFS", "title": "The Intangibles Song in Takeover Announcements: Good Tempo, Hollow Tune", "authors": ["Zoran M Filipovi\u0107", "Alexander F Wagner"], "author_details": [{"name": "Zoran M Filipovi\u0107", "affiliations": ["Universit\u00e9 Paris Dauphine - PSL"]}, {"name": "Alexander F Wagner", "affiliations": ["University of Zurich, CEPR, ECGI, and Swiss Finance Institute"]}], "abstract": "Abstract Mergers and acquisitions are often motivated by an intention to create value from intangible assets. We develop a word list of intangibles and apply it to takeover announcements. One standard deviation more in intangible-related language (\u201cintangibles talk\u201d) lowers announcement returns for the acquirer by 0.53 percentage points and predicts worse operating performance. Bidder managers appear to believe in the deals nonetheless, as evidenced by insider trades, payment choices, and completion probabilities and speed. Overall, takeover announcement texts reveal important information about hard-to-measure aspects of deal quality.", "date": "2025-12-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf116", "title_zh": "\u5e76\u8d2d\u516c\u544a\u4e2d\u7684\u65e0\u5f62\u8d44\u4ea7\u4e4b\u6b4c\uff1a\u8282\u594f\u826f\u597d\uff0c\u65cb\u5f8b\u7a7a\u6d1e", "abstract_zh": "\u5e76\u8d2d\u901a\u5e38\u65e8\u5728\u901a\u8fc7\u65e0\u5f62\u8d44\u4ea7\u521b\u9020\u4ef7\u503c\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u65e0\u5f62\u8d44\u4ea7\u8bcd\u6c47\u8868\uff0c\u5e76\u5c06\u5176\u5e94\u7528\u4e8e\u5e76\u8d2d\u516c\u544a\u3002\u4e0e\u57fa\u51c6\u6c34\u5e73\u76f8\u6bd4\uff0c\u65e0\u5f62\u8d44\u4ea7\u76f8\u5173\u8bed\u8a00\uff08\"\u65e0\u5f62\u8d44\u4ea7\u8a00\u8bba\"\uff09\u589e\u52a0\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u4f1a\u4f7f\u6536\u8d2d\u65b9\u7684\u516c\u544a\u56de\u62a5\u964d\u4f4e0.53\u4e2a\u767e\u5206\u70b9\uff0c\u5e76\u9884\u793a\u8fd0\u8425\u8868\u73b0\u66f4\u5dee\u3002\u7136\u800c\uff0c\u51fa\u4ef7\u65b9\u7ba1\u7406\u8005\u4f3c\u4e4e\u4ecd\u76f8\u4fe1\u8fd9\u4e9b\u4ea4\u6613\uff0c\u8fd9\u4e00\u70b9\u4ece\u5185\u5e55\u4ea4\u6613\u3001\u4ed8\u6b3e\u9009\u62e9\u4ee5\u53ca\u4ea4\u6613\u5b8c\u6210\u7684\u6982\u7387\u548c\u901f\u5ea6\u4e2d\u53ef\u4ee5\u5f97\u5230\u4f53\u73b0\u3002\u603b\u4f53\u800c\u8a00\uff0c\u5e76\u8d2d\u516c\u544a\u6587\u672c\u63ed\u793a\u4e86\u5173\u4e8e\u4ea4\u6613\u8d28\u91cf\u4e2d\u96be\u4ee5\u8861\u91cf\u7684\u65b9\u9762\u7684\u91cd\u8981\u4fe1\u606f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1017/s0022109025102536", "journal": "JFQA", "title": "Agglomeration Effects in Initial Public Offerings", "authors": ["Shahram Amini", "Andrew MacKinlay", "Johan Sulaeman", "Chishen Wei"], "author_details": [{"name": "Shahram Amini", "affiliations": ["University of Denver, Daniels College of Business"]}, {"name": "Andrew MacKinlay", "affiliations": ["Louisiana State University, Ourso College of Business"]}, {"name": "Johan Sulaeman", "affiliations": ["National University of Singapore, NUS Business School"]}, {"name": "Chishen Wei", "affiliations": ["Hong Kong Polytechnic University, Faculty of Business"]}], "abstract": "Abstract We show that the decision to go public is influenced by spatial variation in the supply of equity financing. We measure the amount of capital of equity investors in each U.S. region and document that the incidence of initial public offerings (IPOs) by intangible-intensive resident firms increases significantly when regional equity capital is abundant. Using a novel empirical strategy and hand-collected data on out-of-state pension flows, we confirm that our findings are not due to underlying regional factors.", "date": "2025-12-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102536", "title_zh": "\u521d\u59cb\u516c\u5f00\u52df\u80a1\u4e2d\u7684\u96c6\u805a\u6548\u5e94", "abstract_zh": "\u6211\u4eec\u8bc1\u660e\uff0c\u4f01\u4e1a\u9009\u62e9\u4e0a\u5e02\u7684\u51b3\u7b56\u53d7\u5230\u5730\u533a\u80a1\u6743\u878d\u8d44\u4f9b\u7ed9\u7a7a\u95f4\u5dee\u5f02\u7684\u5f71\u54cd\u3002\u6211\u4eec\u6d4b\u91cf\u4e86\u7f8e\u56fd\u5404\u5730\u533a\u6295\u8d44\u8005\u7684\u80a1\u6743\u8d44\u672c\u89c4\u6a21\uff0c\u5e76\u53d1\u73b0\u5f53\u5730\u533a\u80a1\u6743\u8d44\u672c\u5145\u88d5\u65f6\uff0c\u4ee5\u65e0\u5f62\u8d44\u4ea7\u5bc6\u96c6\u578b\u4f01\u4e1a\u4e3a\u4e3b\u7684\u521d\u59cb\u516c\u5f00\u52df\u80a1\uff08IPO\uff09\u53d1\u751f\u7387\u663e\u8457\u4e0a\u5347\u3002\u901a\u8fc7\u4e00\u79cd\u65b0\u9896\u7684\u5b9e\u8bc1\u7b56\u7565\uff0c\u5e76\u7ed3\u5408\u5bf9\u8de8\u5dde\u517b\u8001\u91d1\u6d41\u52a8\u7684\u5b9e\u5730\u6536\u96c6\u6570\u636e\uff0c\u6211\u4eec\u8bc1\u5b9e\u4e86\u6211\u4eec\u7684\u53d1\u73b0\u5e76\u975e\u7531\u5730\u533a\u5c42\u9762\u7684\u6f5c\u5728\u56e0\u7d20\u5f15\u8d77\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102512", "journal": "JFQA", "title": "Price Rigidities and Credit Risk", "authors": ["Patrick Augustin", "Linxiao Francis Cong", "Alexandre Corhay", "Michael Weber"], "author_details": [{"name": "Patrick Augustin", "affiliations": ["McGill University Desautels Faculty of Management and Canadian Derivatives Institute"]}, {"name": "Linxiao Francis Cong", "affiliations": ["McGill University Desautels Faculty of Management"]}, {"name": "Alexandre Corhay", "affiliations": ["University of Toronto Rotman School of Management"]}, {"name": "Michael Weber", "affiliations": ["Purdue University Daniels School of Business, NBER, and CEPR"]}], "abstract": "Abstract We develop a capital structure model in which firms differ in their ability to adjust output prices. Firms with inflexible prices are more exposed to nominal and real shocks, leading to lower leverage, shorter debt maturity, higher cost of debt, tighter covenants, and greater precautionary cash holdings. Shocks to cash flow volatility raise the cost of debt more for firms with less pricing flexibility. We empirically confirm these predictions: Firms with inflexible prices experience significantly larger increases in credit spreads following monetary policy shocks and the 2008 Lehman Brothers bankruptcy, especially when they face high preshock rollover risk.", "date": "2025-12-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102512", "title_zh": "\u4ef7\u683c\u521a\u6027\u4e0e\u4fe1\u8d37\u98ce\u9669", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u8d44\u672c\u7ed3\u6784\u6a21\u578b\uff0c\u5176\u4e2d\u4f01\u4e1a\u56e0\u5176\u8c03\u6574\u4ea7\u51fa\u4ef7\u683c\u7684\u80fd\u529b\u4e0d\u540c\u800c\u5b58\u5728\u5dee\u5f02\u3002\u4ef7\u683c\u4e0d\u7075\u6d3b\u7684\u4f01\u4e1a\u66f4\u6613\u53d7\u5230\u540d\u4e49\u548c\u5b9e\u9645\u51b2\u51fb\u7684\u5f71\u54cd\uff0c\u4ece\u800c\u5bfc\u81f4\u6760\u6746\u7387\u8f83\u4f4e\u3001\u503a\u52a1\u671f\u9650\u8f83\u77ed\u3001\u503a\u52a1\u6210\u672c\u8f83\u9ad8\u3001\u5951\u7ea6\u6761\u6b3e\u66f4\u4e25\u683c\u4ee5\u53ca\u66f4\u591a\u7684\u9884\u9632\u6027\u73b0\u91d1\u6301\u6709\u3002\u73b0\u91d1\u6d41\u6ce2\u52a8\u6027\u51b2\u51fb\u5bf9\u4ef7\u683c\u7075\u6d3b\u6027\u8f83\u4f4e\u4f01\u4e1a\u7684\u503a\u52a1\u6210\u672c\u63d0\u5347\u66f4\u4e3a\u663e\u8457\u3002\u6211\u4eec\u901a\u8fc7\u5b9e\u8bc1\u9a8c\u8bc1\u4e86\u8fd9\u4e9b\u9884\u6d4b\uff1a\u4ef7\u683c\u4e0d\u7075\u6d3b\u7684\u4f01\u4e1a\u5728\u9762\u5bf9\u8d27\u5e01\u653f\u7b56\u51b2\u51fb\u4ee5\u53ca2008\u5e74\u96f7\u66fc\u5144\u5f1f\u7834\u4ea7\u65f6\uff0c\u4fe1\u7528\u5229\u5dee\u7684\u4e0a\u5347\u5e45\u5ea6\u663e\u8457\u66f4\u5927\uff0c\u5c24\u5176\u662f\u5728\u8fd9\u4e9b\u4f01\u4e1a\u9762\u4e34\u8f83\u9ad8\u524d\u671f\u6eda\u52a8\u98ce\u9669\u7684\u60c5\u51b5\u4e0b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhaf115", "journal": "RFS", "title": "Mortgage Design, Repayment Schedules, and Household Borrowing", "authors": ["Claes B\u00e4ckman", "Patrick Moran", "Peter van Santen"], "author_details": [{"name": "Claes B\u00e4ckman", "affiliations": ["Leibniz Institute for Financial Research SAFE ,"]}, {"name": "Patrick Moran", "affiliations": ["Federal Reserve Board, United States, Institute for Fiscal Studies , , and ,", "CEBI , , and ,"]}, {"name": "Peter van Santen", "affiliations": ["University of Groningen ,"]}], "abstract": "Abstract How does the design of debt repayment schedules affect household borrowing? To answer this question, we exploit a Swedish policy reform that eliminated interest-only mortgages for loan-to-value ratios above 50%. We document substantial bunching at the threshold, leading to 5% lower borrowing. Wealthy borrowers drive the results, challenging credit constraints as the primary explanation. We develop a model to evaluate the mechanisms driving household behavior and find that much of the effect comes from households experiencing ongoing flow disutility to amortization payments. Our results indicate that mortgage contracts with low initial payments substantially increase household borrowing and lifetime interest costs.", "date": "2025-12-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf115", "title_zh": "\u62b5\u62bc\u8d37\u6b3e\u8bbe\u8ba1\u3001\u8fd8\u6b3e\u8ba1\u5212\u4e0e\u5bb6\u5ead\u501f\u8d37", "abstract_zh": "\u6458\u8981 \u62b5\u62bc\u8d37\u6b3e\u7684\u8fd8\u6b3e\u8ba1\u5212\u8bbe\u8ba1\u5982\u4f55\u5f71\u54cd\u5bb6\u5ead\u501f\u8d37\u884c\u4e3a\uff1f\u4e3a\u56de\u7b54\u8fd9\u4e00\u95ee\u9898\uff0c\u6211\u4eec\u5229\u7528\u745e\u5178\u4e00\u9879\u653f\u7b56\u6539\u9769\u7684\u6848\u4f8b\uff0c\u8be5\u6539\u9769\u53d6\u6d88\u4e86\u8d37\u6b3e\u4ef7\u503c\u6bd4\u7387\u8d85\u8fc750%\u7684\u8d37\u6b3e\u4e2d\u4ec5\u4ed8\u5229\u606f\u7684\u62b5\u62bc\u8d37\u6b3e\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u9608\u503c\u5904\u5b58\u5728\u663e\u8457\u7684\u96c6\u4e2d\u73b0\u8c61\uff0c\u5bfc\u81f4\u5bb6\u5ead\u501f\u8d37\u51cf\u5c11\u4e865%\u3002\u5bcc\u88d5\u7684\u501f\u6b3e\u4eba\u662f\u8fd9\u4e00\u7ed3\u679c\u7684\u4e3b\u8981\u9a71\u52a8\u56e0\u7d20\uff0c\u8fd9\u6311\u6218\u4e86\u4fe1\u7528\u7ea6\u675f\u662f\u4e3b\u8981\u89e3\u91ca\u7684\u5047\u8bbe\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6a21\u578b\u6765\u8bc4\u4f30\u9a71\u52a8\u5bb6\u5ead\u884c\u4e3a\u7684\u673a\u5236\uff0c\u53d1\u73b0\u5927\u90e8\u5206\u6548\u5e94\u6e90\u4e8e\u5bb6\u5ead\u5728\u6301\u7eed\u9762\u4e34\u507f\u8fd8\u672c\u91d1\u7684\u73b0\u91d1\u6d41\u4e0d\u9002\u611f\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u5177\u6709\u8f83\u4f4e\u521d\u59cb\u8fd8\u6b3e\u989d\u7684\u62b5\u62bc\u8d37\u6b3e\u5408\u540c\u663e\u8457\u589e\u52a0\u4e86\u5bb6\u5ead\u7684\u501f\u8d37\u91d1\u989d\u548c\u7ec8\u8eab\u5229\u606f\u652f\u51fa\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhaf113", "journal": "RFS", "title": "Financial Restructuring and Resolution of Banks", "authors": ["Jean-Edouard Colliard", "Denis Gromb"], "author_details": [{"name": "Jean-Edouard Colliard", "affiliations": ["HEC Paris ,"]}, {"name": "Denis Gromb", "affiliations": ["HEC Paris ,"]}], "abstract": "Abstract How do resolution frameworks affect the private restructuring of distressed banks? We model a bank\u2019s shareholders and creditors negotiating a restructuring, under two frictions: asymmetric information about asset quality and externalities on the government. High-quality banks signal themselves by delaying the negotiation, which is socially inefficient. Public policies can improve welfare if they reduce the signaling motive or increase the negotiation surplus. Stricter bail-in rules make debt more information sensitive and increase delays. The bank chooses a capital structure with too little renegotiable debt, giving a new rationale, for example, for Total Loss Absorbing Capacity requirements.", "date": "2025-12-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf113", "title_zh": "\u94f6\u884c\u8d22\u52a1\u91cd\u7ec4\u4e0e\u94f6\u884c\u5904\u7f6e\u6846\u67b6", "abstract_zh": "\u6458\u8981 \u89e3\u51b3\u65b9\u6848\u6846\u67b6\u5982\u4f55\u5f71\u54cd\u9677\u5165\u56f0\u5883\u94f6\u884c\u7684\u79c1\u4eba\u91cd\u7ec4\uff1f\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u94f6\u884c\u80a1\u4e1c\u548c\u503a\u6743\u4eba\u8c08\u5224\u91cd\u7ec4\u7684\u6a21\u578b\uff0c\u5176\u4e2d\u5b58\u5728\u4e24\u4e2a\u6469\u64e6\uff1a\u8d44\u4ea7\u8d28\u91cf\u4fe1\u606f\u4e0d\u5bf9\u79f0\u4ee5\u53ca\u5bf9\u653f\u5e9c\u7684\u5916\u90e8\u6027\u3002\u9ad8\u8d28\u91cf\u94f6\u884c\u901a\u8fc7\u5ef6\u8fdf\u8c08\u5224\u6765\u4f20\u9012\u4fe1\u53f7\uff0c\u8fd9\u79cd\u884c\u4e3a\u5728\u793e\u4f1a\u4e0a\u662f\u4f4e\u6548\u7684\u3002\u5982\u679c\u516c\u5171\u653f\u7b56\u80fd\u591f\u51cf\u5c11\u8fd9\u79cd\u4fe1\u53f7\u4f20\u9012\u52a8\u673a\u6216\u63d0\u9ad8\u8c08\u5224\u5269\u4f59\uff0c\u5c31\u80fd\u6539\u5584\u6574\u4f53\u798f\u5229\u3002\u66f4\u4e25\u683c\u7684\u7834\u4ea7\u5438\u6536\u89c4\u5219\u4f1a\u4f7f\u503a\u52a1\u5bf9\u4fe1\u606f\u7684\u654f\u611f\u6027\u589e\u52a0\uff0c\u5e76\u5bfc\u81f4\u8c08\u5224\u5ef6\u8fdf\u3002\u94f6\u884c\u9009\u62e9\u7684\u8d44\u672c\u7ed3\u6784\u4e2d\u53ef\u91cd\u65b0\u8c08\u5224\u7684\u503a\u52a1\u8fc7\u5c11\uff0c\u8fd9\u4e3a\u603b\u635f\u5931\u5438\u6536\u80fd\u529b\u7684\u8981\u6c42\u63d0\u4f9b\u4e86\u65b0\u7684\u7406\u8bba\u4f9d\u636e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102548", "journal": "JFQA", "title": "Bank Lending and Market-Based Finance for Corporations: The Effects of Minibond Issuances for Unlisted Firms", "authors": ["Steven Ongena", "Sara Pinoli", "Paola Rossi", "Alessandro Scopelliti"], "author_details": [{"name": "Steven Ongena", "affiliations": ["University of Zurich"]}, {"name": "Sara Pinoli", "affiliations": ["Banca d\u2019Italia"]}, {"name": "Paola Rossi", "affiliations": ["Banca d\u2019Italia"]}, {"name": "Alessandro Scopelliti", "affiliations": ["KU Leuven"]}], "abstract": "Abstract What are the benefits of access to the bond market for unlisted firms, and how does it affect their bank lending conditions? Using a regulatory reform that allowed unlisted firms to issue minibonds, we address these questions comparing new bank loans to issuers with concurrent loans to matched non-issuers. After the first minibond issuance, issuers obtain lower interest rates on bank loans of similar maturity, largely reflecting a shift in the seniority structure of corporate debt, and reduce the use of bank loans while increasing their total financial debt. They also increase turnover, total and fixed assets, particularly intangible assets.", "date": "2025-12-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102548", "title_zh": "\u94f6\u884c\u8d37\u6b3e\u4e0e\u5e02\u573a\u878d\u8d44\u5bf9\u4f01\u4e1a\uff1a\u672a\u4e0a\u5e02\u516c\u53f8\u53d1\u884c\u8ff7\u4f60\u503a\u5238\u7684\u5f71\u54cd", "abstract_zh": "\u6458\u8981 \u672a\u4e0a\u5e02\u516c\u53f8\u83b7\u5f97\u503a\u5238\u5e02\u573a\u51c6\u5165\u5e26\u6765\u4e86\u54ea\u4e9b\u597d\u5904\uff1f\u8fd9\u53c8\u5982\u4f55\u5f71\u54cd\u5176\u94f6\u884c\u8d37\u6b3e\u6761\u4ef6\uff1f\u6211\u4eec\u5229\u7528\u4e00\u9879\u5141\u8bb8\u672a\u4e0a\u5e02\u516c\u53f8\u53d1\u884c\u8ff7\u4f60\u503a\u5238\u7684\u76d1\u7ba1\u6539\u9769\uff0c\u901a\u8fc7\u6bd4\u8f83\u53d1\u884c\u8ff7\u4f60\u503a\u5238\u4f01\u4e1a\u4e0e\u5339\u914d\u7684\u975e\u53d1\u884c\u4f01\u4e1a\u540c\u671f\u7684\u94f6\u884c\u8d37\u6b3e\uff0c\u6765\u56de\u7b54\u8fd9\u4e9b\u95ee\u9898\u3002\u5728\u9996\u6b21\u53d1\u884c\u8ff7\u4f60\u503a\u5238\u540e\uff0c\u53d1\u884c\u4eba\u83b7\u5f97\u4e0e\u5230\u671f\u65f6\u95f4\u76f8\u4f3c\u7684\u94f6\u884c\u8d37\u6b3e\u5229\u7387\u4e0b\u964d\uff0c\u8fd9\u4e3b\u8981\u53cd\u6620\u4e86\u4f01\u4e1a\u503a\u52a1\u5c42\u7ea7\u7ed3\u6784\u7684\u53d8\u5316\uff0c\u540c\u65f6\u51cf\u5c11\u4e86\u94f6\u884c\u8d37\u6b3e\u7684\u4f7f\u7528\uff0c\u589e\u52a0\u4e86\u603b\u91d1\u878d\u503a\u52a1\u3002\u6b64\u5916\uff0c\u5b83\u4eec\u8fd8\u63d0\u9ad8\u4e86\u8fd0\u8425\u5468\u8f6c\u7387\u3001\u603b\u8d44\u4ea7\u548c\u56fa\u5b9a\u8d44\u4ea7\uff0c\u5c24\u5176\u662f\u65e0\u5f62\u8d44\u4ea7\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1111/jofi.70006", "journal": "JF", "title": "The Long\u2010Lasting Effects of Experiencing Communism on Attitudes toward Financial Markets", "authors": ["CHRISTINE LAUDENBACH", "ULRIKE MALMENDIER", "ALEXANDRA NIESSEN\u2010RUENZI"], "author_details": [{"name": "CHRISTINE LAUDENBACH", "affiliations": []}, {"name": "ULRIKE MALMENDIER", "affiliations": []}, {"name": "ALEXANDRA NIESSEN\u2010RUENZI", "affiliations": []}], "abstract": "ABSTRACT We show that exposure to anti\u2010capitalist ideology can exert a lasting influence on attitudes toward capital markets and stock market participation. Using novel survey, bank, and broker data, we document that, decades after Germany's reunification, East Germans invest significantly less in stocks and hold more negative views on capital markets. Effects vary by personal experience under communism. Results are strongest for individuals who remember life in the German Democratic Republic positively, for example, those living in a \u201cshowcase city.\u201d Results reverse for those with negative experiences like environmental pollution or lack of Western TV entertainment.", "date": "2025-12-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70006", "title_zh": "\u7ecf\u5386\u5171\u4ea7\u4e3b\u4e49\u5bf9\u91d1\u878d\u5e02\u573a\u6001\u5ea6\u7684\u957f\u671f\u5f71\u54cd", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u8868\u660e\uff0c\u63a5\u89e6\u53cd\u8d44\u672c\u4e3b\u4e49\u610f\u8bc6\u5f62\u6001\u53ef\u80fd\u5bf9\u5bf9\u8d44\u672c\u5e02\u573a\u548c\u80a1\u7968\u5e02\u573a\u53c2\u4e0e\u7684\u6001\u5ea6\u4ea7\u751f\u6301\u4e45\u5f71\u54cd\u3002\u5229\u7528\u65b0\u7684\u8c03\u67e5\u3001\u94f6\u884c\u548c\u7ecf\u7eaa\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u5fb7\u56fd\u7edf\u4e00\u51e0\u5341\u5e74\u540e\uff0c\u4e1c\u5fb7\u4eba\u4ecd\u663e\u8457\u8f83\u5c11\u6295\u8d44\u4e8e\u80a1\u7968\uff0c\u5e76\u5bf9\u8d44\u672c\u5e02\u573a\u6301\u6709\u66f4\u8d1f\u9762\u7684\u770b\u6cd5\u3002\u8fd9\u79cd\u5f71\u54cd\u56e0\u4e2a\u4eba\u5728\u5171\u4ea7\u4e3b\u4e49\u65f6\u671f\u7684\u751f\u6d3b\u7ecf\u5386\u800c\u5f02\u3002\u7ed3\u679c\u5bf9\u4e8e\u90a3\u4e9b\u5bf9\u4e1c\u5fb7\u6c11\u4e3b\u5171\u548c\u56fd\u65f6\u671f\u751f\u6d3b\u6301\u79ef\u6781\u6001\u5ea6\u7684\u4e2a\u4f53\u5c24\u4e3a\u660e\u663e\uff0c\u4f8b\u5982\u5c45\u4f4f\u5728\u201c\u793a\u8303\u57ce\u5e02\u201d\u7684\u4eba\u3002\u800c\u5bf9\u4e8e\u90a3\u4e9b\u7ecf\u5386\u8fc7\u73af\u5883\u6c61\u67d3\u6216\u7f3a\u4e4f\u897f\u65b9\u7535\u89c6\u5a31\u4e50\u7b49\u8d1f\u9762\u7ecf\u5386\u7684\u4e2a\u4f53\uff0c\u8fd9\u79cd\u5f71\u54cd\u5219\u76f8\u53cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70010", "journal": "JF", "title": "Investment under Upstream and Downstream Uncertainty", "authors": ["FOTIS GRIGORIS", "GILL SEGAL"], "author_details": [{"name": "FOTIS GRIGORIS", "affiliations": []}, {"name": "GILL SEGAL", "affiliations": []}], "abstract": "ABSTRACT The impact of uncertainty shocks on firm\u2010level economic activity depends on their origin in supply chains. Upstream (downstream) uncertainty from suppliers (customers) is associated with variability over future input (output) prices. Consequently, a real\u2010option production model with time\u2010to\u2010build suggests that only upstream uncertainty suppresses investment, since upstream (downstream) uncertainty affects the shorter (longer) run. Production network data show that upstream uncertainty negatively affects firm\u2010level outcomes. Conversely, downstream uncertainty affects firm\u2010level outcomes more weakly but positively. At the macro level, these two uncertainties oppositely predict aggregate growth and asset prices. Overall, downstream uncertainty has an expansionary effect, in contrast to other facets of uncertainty.", "date": "2025-12-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70010", "title_zh": "\u5728\u4e0a\u6e38\u548c\u4e0b\u6e38\u4e0d\u786e\u5b9a\u6027\u4e0b\u7684\u6295\u8d44\u884c\u4e3a", "abstract_zh": "\u6458\u8981 \u4e0d\u786e\u5b9a\u6027\u51b2\u51fb\u5bf9\u4f01\u4e1a\u7684\u7ecf\u6d4e\u6d3b\u52a8\u5f71\u54cd\u53d6\u51b3\u4e8e\u5176\u5728\u4f9b\u5e94\u94fe\u4e2d\u7684\u6765\u6e90\u3002\u6765\u81ea\u4f9b\u5e94\u5546\uff08\u5ba2\u6237\uff09\u7684\u4e0a\u6e38\uff08\u4e0b\u6e38\uff09\u4e0d\u786e\u5b9a\u6027\u4e0e\u672a\u6765\u6295\u5165\uff08\u4ea7\u51fa\uff09\u4ef7\u683c\u7684\u6ce2\u52a8\u6027\u76f8\u5173\u3002\u56e0\u6b64\uff0c\u57fa\u4e8e\u65f6\u95f4\u5efa\u9020\u671f\u7684\u5b9e\u7269\u671f\u6743\u751f\u4ea7\u6a21\u578b\u8868\u660e\uff0c\u53ea\u6709\u4e0a\u6e38\u4e0d\u786e\u5b9a\u6027\u4f1a\u6291\u5236\u6295\u8d44\uff0c\u56e0\u4e3a\u4e0a\u6e38\uff08\u4e0b\u6e38\uff09\u4e0d\u786e\u5b9a\u6027\u5f71\u54cd\u7684\u662f\u77ed\u671f\uff08\u957f\u671f\uff09\u8fd0\u884c\u3002\u751f\u4ea7\u7f51\u7edc\u6570\u636e\u8868\u660e\uff0c\u4e0a\u6e38\u4e0d\u786e\u5b9a\u6027\u5bf9\u4f01\u4e1a\u5c42\u9762\u7684\u7ed3\u679c\u5177\u6709\u8d1f\u9762\u5f71\u54cd\u3002\u76f8\u53cd\uff0c\u4e0b\u6e38\u4e0d\u786e\u5b9a\u6027\u5bf9\u4f01\u4e1a\u5c42\u9762\u7684\u7ed3\u679c\u5f71\u54cd\u8f83\u5f31\u4f46\u5448\u6b63\u5411\u4f5c\u7528\u3002\u5728\u5b8f\u89c2\u5c42\u9762\uff0c\u8fd9\u4e24\u79cd\u4e0d\u786e\u5b9a\u6027\u5bf9\u6574\u4f53\u7ecf\u6d4e\u589e\u957f\u548c\u8d44\u4ea7\u4ef7\u683c\u7684\u9884\u6d4b\u65b9\u5411\u76f8\u53cd\u3002\u603b\u4f53\u800c\u8a00\uff0c\u4e0b\u6e38\u4e0d\u786e\u5b9a\u6027\u5177\u6709\u6269\u5f20\u6548\u5e94\uff0c\u4e0e\u5176\u4ed6\u7c7b\u578b\u7684\u4e0d\u786e\u5b9a\u6027\u5f62\u6210\u5bf9\u6bd4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u7f51\u7edc"]}, {"doi": "10.1093/rfs/hhaf111", "journal": "RFS", "title": "The Structure of Leveraged Buyouts and the Free-Rider Problem", "authors": ["Mike Burkart", "Samuel Lee", "Henrik Petri"], "author_details": [{"name": "Mike Burkart", "affiliations": ["London School of Economics, Swedish House of Finance, CEPR, ECGI, and FTG , , Sweden, and Belgium"]}, {"name": "Samuel Lee", "affiliations": ["Santa Clara University, Swedish House of Finance and ECGI , , Sweden, and Belgium"]}, {"name": "Henrik Petri", "affiliations": ["University of Gothenburg ,"]}], "abstract": "Abstract We study the structure of public firm buyouts in a model that features the Berle-Means problem (lack of incentives) and the Grossman-Hart problem (holdout). We find that bootstrapping, debt in excess of funding needs, and upfront fees to bidders are socially optimal and increase buyout premiums. These elements make LBO financing tantamount to a \u201cmanagement contract\u201d arranged by an outside manager to receive cash and incentives to manage a firm\u2014except the cash is funded by excess debt imposed on the firm. Our model also rationalizes why PE firms collect fees from their equity partnerships and directly from target firms.", "date": "2025-12-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf111", "title_zh": "\u6760\u6746\u6536\u8d2d\u7684\u7ed3\u6784\u4e0e\u642d\u4fbf\u8f66\u95ee\u9898", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5728\u4e00\u4e2a\u5305\u542b\u4f2f\u5c14-\u6885\u6069\u95ee\u9898\uff08\u6fc0\u52b1\u7f3a\u5931\uff09\u548c\u683c\u7f57\u65af\u66fc-\u54c8\u7279\u95ee\u9898\uff08\u6301\u4efd\u4eba\u963b\u6320\uff09\u7684\u6a21\u578b\u4e2d\u7814\u7a76\u4e86\u516c\u5f00\u516c\u53f8\u6536\u8d2d\u7684\u7ed3\u6784\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u542f\u52a8\u8d44\u91d1\u3001\u8d85\u51fa\u8d44\u91d1\u9700\u6c42\u7684\u503a\u52a1\u4ee5\u53ca\u5411\u6295\u6807\u65b9\u652f\u4ed8\u7684\u524d\u671f\u8d39\u7528\u5728\u793e\u4f1a\u610f\u4e49\u4e0a\u662f\u6700\u4f18\u7684\uff0c\u5e76\u80fd\u63d0\u9ad8\u6536\u8d2d\u6ea2\u4ef7\u3002\u8fd9\u4e9b\u8981\u7d20\u4f7f\u5f97\u6760\u6746\u6536\u8d2d\u7684\u878d\u8d44\u65b9\u5f0f\u7b49\u540c\u4e8e\u7531\u5916\u90e8\u7ba1\u7406\u8005\u5b89\u6392\u7684\u4e00\u9879\u201c\u7ba1\u7406\u5408\u540c\u201d\uff0c\u8be5\u5408\u540c\u65e8\u5728\u83b7\u5f97\u73b0\u91d1\u548c\u7ba1\u7406\u6fc0\u52b1\u2014\u2014\u53ea\u4e0d\u8fc7\u8fd9\u4e9b\u73b0\u91d1\u662f\u901a\u8fc7\u5f3a\u52a0\u5728\u516c\u53f8\u8eab\u4e0a\u7684\u8d85\u989d\u503a\u52a1\u6765\u878d\u8d44\u7684\u3002\u6211\u4eec\u7684\u6a21\u578b\u8fd8\u89e3\u91ca\u4e86\u4e3a\u4ec0\u4e48\u79c1\u52df\u80a1\u6743\u516c\u53f8\u4f1a\u4ece\u5176\u80a1\u6743\u5408\u4f19\u4eba\u4ee5\u53ca\u76ee\u6807\u516c\u53f8\u5904\u6536\u53d6\u8d39\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1111/jofi.70003", "journal": "JF", "title": "FinTech Lending and Cashless Payments", "authors": ["PULAK GHOSH", "BORIS VALLEE", "YAO ZENG"], "author_details": [{"name": "PULAK GHOSH", "affiliations": []}, {"name": "BORIS VALLEE", "affiliations": []}, {"name": "YAO ZENG", "affiliations": []}], "abstract": "ABSTRACT Borrowers' use of cashless payments improves their access to capital from FinTech lenders and predicts a lower probability of default. These relationships are stronger for cashless technologies providing more precise information, and for outflows. Cashless payment usage complements other signals of borrower quality. We rationalize these empirical findings using a framework in which borrowers signal their lower likelihood of diverting cash flows through payment technology choice, and screening accuracy is further strengthened by informational complementarities. The informational synergy we uncover provides a rationale for the joint rise of cashless payments and FinTech lending, as well as for open banking.", "date": "2025-12-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70003", "title_zh": "\u91d1\u878d\u79d1\u6280\u8d37\u6b3e\u4e0e\u65e0\u73b0\u91d1\u652f\u4ed8", "abstract_zh": "\u6458\u8981 \u501f\u6b3e\u4eba\u4f7f\u7528\u65e0\u73b0\u91d1\u652f\u4ed8\u65b9\u5f0f\u63d0\u9ad8\u4e86\u5176\u4ece\u91d1\u878d\u79d1\u6280\u8d37\u6b3e\u673a\u6784\u83b7\u5f97\u8d44\u672c\u7684\u53ef\u53ca\u6027\uff0c\u5e76\u9884\u793a\u7740\u66f4\u4f4e\u7684\u8fdd\u7ea6\u6982\u7387\u3002\u8fd9\u4e9b\u5173\u7cfb\u5728\u63d0\u4f9b\u66f4\u7cbe\u786e\u4fe1\u606f\u7684\u65e0\u73b0\u91d1\u6280\u672f\u4ee5\u53ca\u8d44\u91d1\u6d41\u51fa\u65b9\u9762\u66f4\u4e3a\u663e\u8457\u3002\u65e0\u73b0\u91d1\u652f\u4ed8\u7684\u4f7f\u7528\u4e0e\u501f\u6b3e\u4eba\u8d28\u91cf\u7684\u5176\u4ed6\u4fe1\u53f7\u76f8\u8865\u5145\u3002\u6211\u4eec\u901a\u8fc7\u4e00\u4e2a\u501f\u6b3e\u4eba\u901a\u8fc7\u9009\u62e9\u652f\u4ed8\u6280\u672f\u6765\u4f20\u9012\u5176\u73b0\u91d1\u6d41\u4e0d\u88ab\u632a\u7528\u53ef\u80fd\u6027\u8f83\u4f4e\u7684\u4fe1\u53f7\u7684\u6846\u67b6\uff0c\u89e3\u91ca\u4e86\u8fd9\u4e9b\u5b9e\u8bc1\u53d1\u73b0\uff0c\u5e76\u6307\u51fa\u4fe1\u606f\u4e92\u8865\u6027\u8fdb\u4e00\u6b65\u589e\u5f3a\u4e86\u7b5b\u9009\u7684\u51c6\u786e\u6027\u3002\u6211\u4eec\u63ed\u793a\u7684\u4fe1\u606f\u534f\u540c\u6548\u5e94\u4e3a\u65e0\u73b0\u91d1\u652f\u4ed8\u4e0e\u91d1\u878d\u79d1\u6280\u8d37\u6b3e\u7684\u5171\u540c\u5174\u8d77\uff0c\u4ee5\u53ca\u5f00\u653e\u94f6\u884c\u7684\u53d1\u5c55\u63d0\u4f9b\u4e86\u5408\u7406\u89e3\u91ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70013", "journal": "JF", "title": "What Drives Investors' Portfolio Choices? Separating Risk Preferences from Frictions", "authors": ["TAHA CHOUKHMANE", "TIM DE SILVA"], "author_details": [{"name": "TAHA CHOUKHMANE", "affiliations": []}, {"name": "TIM DE SILVA", "affiliations": []}], "abstract": "ABSTRACT We study the role of risk preferences and frictions in portfolio choice using variation in 401(k) default options. Patterns of active choice in response to different default funds imply that, absent participation frictions, 94% of investors prefer holding stocks, with an equity share of retirement wealth declining with age\u2014patterns markedly different from observed allocations. We use this quasi\u2010experiment to estimate a life\u2010cycle model and find a relative risk aversion of 2.5, elasticity of intertemporal substitution (EIS) of 0.25, and $160 portfolio adjustment cost. The results suggest that low levels of stock market participation in retirement accounts are due to participation frictions rather than nonstandard preferences such as loss aversion.", "date": "2025-12-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70013", "title_zh": "\u662f\u4ec0\u4e48\u9a71\u52a8\u6295\u8d44\u8005\u7684\u8d44\u4ea7\u914d\u7f6e\uff1f\u5206\u79bb\u98ce\u9669\u504f\u597d\u4e0e\u6469\u64e6\u56e0\u7d20", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u7528401(k)\u8ba1\u5212\u4e2d\u9ed8\u8ba4\u9009\u9879\u7684\u5dee\u5f02\uff0c\u7814\u7a76\u98ce\u9669\u504f\u597d\u548c\u6469\u64e6\u56e0\u7d20\u5728\u8d44\u4ea7\u914d\u7f6e\u4e2d\u7684\u4f5c\u7528\u3002\u5bf9\u4e0d\u540c\u9ed8\u8ba4\u57fa\u91d1\u7684\u4e3b\u52a8\u9009\u62e9\u6a21\u5f0f\u8868\u660e\uff0c\u5728\u6ca1\u6709\u53c2\u4e0e\u6469\u64e6\u7684\u60c5\u51b5\u4e0b\uff0c94%\u7684\u6295\u8d44\u8005\u66f4\u503e\u5411\u4e8e\u6301\u6709\u80a1\u7968\uff0c\u5176\u9000\u4f11\u8d22\u5bcc\u4e2d\u7684\u80a1\u7968\u6bd4\u4f8b\u968f\u5e74\u9f84\u589e\u957f\u800c\u4e0b\u964d\u2014\u2014\u8fd9\u4e00\u6a21\u5f0f\u4e0e\u5b9e\u9645\u89c2\u5bdf\u5230\u7684\u914d\u7f6e\u60c5\u51b5\u622a\u7136\u4e0d\u540c\u3002\u6211\u4eec\u5229\u7528\u8fd9\u4e00\u51c6\u5b9e\u9a8c\u8bbe\u8ba1\u4f30\u8ba1\u4e86\u4e00\u4e2a\u751f\u547d\u5468\u671f\u6a21\u578b\uff0c\u5f97\u51fa\u76f8\u5bf9\u98ce\u9669\u538c\u6076\u7cfb\u6570\u4e3a2.5\uff0c\u8de8\u671f\u66ff\u4ee3\u5f39\u6027\uff08EIS\uff09\u4e3a0.25\uff0c\u4ee5\u53ca160\u7f8e\u5143\u7684\u8d44\u4ea7\u7ec4\u5408\u8c03\u6574\u6210\u672c\u3002\u7ed3\u679c\u8868\u660e\uff0c\u9000\u4f11\u8d26\u6237\u4e2d\u80a1\u7968\u5e02\u573a\u7684\u53c2\u4e0e\u5ea6\u8f83\u4f4e\u4e3b\u8981\u662f\u7531\u4e8e\u53c2\u4e0e\u6469\u64e6\uff0c\u800c\u975e\u975e\u6807\u51c6\u504f\u597d\uff08\u5982\u635f\u5931\u538c\u6076\uff09\u6240\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1111/jofi.70004", "journal": "JF", "title": "An Economic View of Corporate Social Impact", "authors": ["HUNT ALLCOTT", "GIOVANNI MONTANARI", "BORA OZALTUN", "BRANDON TAN"], "author_details": [{"name": "HUNT ALLCOTT", "affiliations": []}, {"name": "GIOVANNI MONTANARI", "affiliations": []}, {"name": "BORA OZALTUN", "affiliations": []}, {"name": "BRANDON TAN", "affiliations": []}], "abstract": "ABSTRACT Growing discussions of impact investing and stakeholder capitalism have increased interest in measuring companies' social impact. We conceptualize corporate social impact as the welfare loss that would be caused by a firm's exit. To illustrate, we quantify the social impacts of 74 firms in 12 industries using a new survey measuring consumer and worker substitution patterns combined with models of product and labor markets. We find that consumer surplus is the primary component of social impact, suggesting that consumer impacts deserve more attention from impact investors. Existing environmental, social, and governance (ESG) and social impact ratings are essentially unrelated to our economically grounded measures.", "date": "2025-12-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70004", "title_zh": "\u4f01\u4e1a\u793e\u4f1a\u8d23\u4efb\u7684\u7ecf\u6d4e\u5b66\u89c6\u89d2", "abstract_zh": "\u6458\u8981 \u968f\u7740\u5f71\u54cd\u529b\u6295\u8d44\u548c\u5229\u76ca\u76f8\u5173\u8005\u8d44\u672c\u4e3b\u4e49\u7684\u8ba8\u8bba\u65e5\u76ca\u589e\u591a\uff0c\u4eba\u4eec\u5f00\u59cb\u5173\u6ce8\u5982\u4f55\u8861\u91cf\u4f01\u4e1a\u5bf9\u793e\u4f1a\u7684\u5f71\u54cd\u3002\u6211\u4eec\u5c06\u4f01\u4e1a\u793e\u4f1a\u8d23\u4efb\u5b9a\u4e49\u4e3a\u516c\u53f8\u9000\u51fa\u6240\u5bfc\u81f4\u7684\u798f\u5229\u635f\u5931\u3002\u4ee5\u4e3e\u4f8b\u8bf4\u660e\uff0c\u6211\u4eec\u5229\u7528\u4e00\u9879\u65b0\u7684\u8c03\u67e5\uff0c\u6d4b\u91cf\u6d88\u8d39\u8005\u548c\u5458\u5de5\u7684\u66ff\u4ee3\u6a21\u5f0f\uff0c\u5e76\u7ed3\u5408\u4ea7\u54c1\u548c\u52b3\u52a8\u529b\u5e02\u573a\u7684\u6a21\u578b\uff0c\u5bf912\u4e2a\u884c\u4e1a\u4e2d74\u5bb6\u4f01\u4e1a\u7684\u793e\u4f1a\u5f71\u54cd\u8fdb\u884c\u4e86\u91cf\u5316\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u6d88\u8d39\u8005\u5269\u4f59\u662f\u793e\u4f1a\u5f71\u54cd\u7684\u4e3b\u8981\u7ec4\u6210\u90e8\u5206\uff0c\u8fd9\u8868\u660e\u5f71\u54cd\u529b\u6295\u8d44\u8005\u5e94\u66f4\u52a0\u91cd\u89c6\u6d88\u8d39\u8005\u5c42\u9762\u7684\u5f71\u54cd\u3002\u73b0\u6709\u7684\u73af\u5883\u3001\u793e\u4f1a\u548c\u6cbb\u7406\uff08ESG\uff09\u4ee5\u53ca\u793e\u4f1a\u5f71\u54cd\u529b\u8bc4\u7ea7\uff0c\u4e0e\u6211\u4eec\u57fa\u4e8e\u7ecf\u6d4e\u5b66\u57fa\u7840\u7684\u8861\u91cf\u65b9\u6cd5\u57fa\u672c\u65e0\u5173\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/rfs/hhaf109", "journal": "RFS", "title": "Cross-Border M&A Flows, Economic Growth, and Foreign Exchange Rates", "authors": ["Steven J Riddiough", "Huizhong Zhang"], "author_details": [{"name": "Steven J Riddiough", "affiliations": ["University of Toronto Scarborough, and Rotman School of Management, University of Toronto ,"]}, {"name": "Huizhong Zhang", "affiliations": ["Monash Business School, Monash University ,"]}], "abstract": "Abstract We extract information about future economic conditions from firms\u2019 cross-border merger and acquisition announcements, and show it predicts changes in relative economic growth rates and foreign exchange rate returns. We find the predictability is driven by the acquisition decisions of domestic firms, which signal turning points in local economic growth. The findings are motivated by a simple model of exchange rate determination with heterogeneous expectations and support the theorized relationship between foreign exchange rates and macroeconomic fundamentals. The results provide new tools for policy makers seeking to predict economic activity and offer global investors a novel source of portfolio diversification.", "date": "2025-12-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/rfs/hhaf109", "title_zh": "\u8de8\u5883\u5e76\u8d2d\u6d41\u52a8\u3001\u7ecf\u6d4e\u589e\u957f\u4e0e\u5916\u6c47\u6c47\u7387", "abstract_zh": "\u6211\u4eec\u4ece\u4f01\u4e1a\u8de8\u5883\u5e76\u8d2d\u516c\u544a\u4e2d\u63d0\u53d6\u5173\u4e8e\u672a\u6765\u7ecf\u6d4e\u72b6\u51b5\u7684\u4fe1\u606f\uff0c\u5e76\u8868\u660e\u8fd9\u4e9b\u4fe1\u606f\u80fd\u591f\u9884\u6d4b\u76f8\u5bf9\u7ecf\u6d4e\u589e\u957f\u7387\u548c\u5916\u6c47\u6c47\u7387\u56de\u62a5\u7684\u53d8\u5316\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u79cd\u53ef\u9884\u6d4b\u6027\u4e3b\u8981\u7531\u56fd\u5185\u4f01\u4e1a\u7684\u5e76\u8d2d\u51b3\u7b56\u9a71\u52a8\uff0c\u8fd9\u4e9b\u51b3\u7b56\u53cd\u6620\u4e86\u5f53\u5730\u7ecf\u6d4e\u589e\u957f\u7684\u5173\u952e\u8f6c\u6298\u70b9\u3002\u7814\u7a76\u7ed3\u679c\u57fa\u4e8e\u4e00\u4e2a\u5305\u542b\u5f02\u8d28\u6027\u9884\u671f\u7684\u7b80\u5355\u6c47\u7387\u51b3\u5b9a\u6a21\u578b\uff0c\u652f\u6301\u4e86\u5916\u6c47\u6c47\u7387\u4e0e\u5b8f\u89c2\u7ecf\u6d4e\u57fa\u672c\u9762\u4e4b\u95f4\u7406\u8bba\u4e0a\u7684\u5173\u7cfb\u3002\u7814\u7a76\u7ed3\u679c\u4e3a\u5bfb\u6c42\u9884\u6d4b\u7ecf\u6d4e\u6d3b\u52a8\u7684\u653f\u7b56\u5236\u5b9a\u8005\u63d0\u4f9b\u4e86\u65b0\u5de5\u5177\uff0c\u5e76\u4e3a\u5168\u7403\u6295\u8d44\u8005\u63d0\u4f9b\u4e86\u65b0\u7684\u8d44\u4ea7\u914d\u7f6e\u6765\u6e90\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u5e76\u8d2d"]}, {"doi": "10.1111/jofi.70002", "journal": "JF", "title": "Second Chance: Life with Less Student Debt", "authors": ["MARCO DI MAGGIO", "ANKIT KALDA", "VINCENT YAO"], "author_details": [{"name": "MARCO DI MAGGIO", "affiliations": []}, {"name": "ANKIT KALDA", "affiliations": []}, {"name": "VINCENT YAO", "affiliations": []}], "abstract": "ABSTRACT We exploit an episode of plausibly random debt discharge due to the loss of paperwork for thousands of defaulted borrowers to examine the effects of private student debt relief on borrower outcomes. We find that borrowers who receive debt relief (treated) experience declines in debt balances and delinquency rates on other accounts, and increases in mobility and income relative to those who bear the costs of default like wage garnishment and collections (control). Borrowers in both groups contribute to our findings through different mechanisms. While our estimates may not directly apply to blanket student loan forgiveness, they speak to the benefits of forgiveness in reducing the consequences of debt burden for distressed borrowers.", "date": "2025-12-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70002", "title_zh": "\u7b2c\u4e8c\u6b21\u673a\u4f1a\uff1a\u51cf\u5c11\u5b66\u751f\u503a\u52a1\u7684\u751f\u6d3b", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u7528\u4e00\u573a\u7531\u4e8e\u6210\u5343\u4e0a\u4e07\u8fdd\u7ea6\u501f\u6b3e\u4eba\u4e22\u5931\u6587\u4ef6\u800c\u5bfc\u81f4\u7684\u770b\u4f3c\u968f\u673a\u7684\u503a\u52a1\u51cf\u514d\u4e8b\u4ef6\uff0c\u6765\u7814\u7a76\u79c1\u4eba\u5b66\u751f\u503a\u52a1\u51cf\u514d\u5bf9\u501f\u6b3e\u4eba\u7ed3\u679c\u7684\u5f71\u54cd\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u83b7\u5f97\u503a\u52a1\u51cf\u514d\uff08\u5904\u7406\u7ec4\uff09\u7684\u501f\u6b3e\u4eba\u5176\u503a\u52a1\u4f59\u989d\u548c\u5176\u5b83\u8d26\u6237\u7684\u903e\u671f\u7387\u4e0b\u964d\uff0c\u800c\u6d41\u52a8\u6027\u4e0e\u6536\u5165\u6c34\u5e73\u5219\u76f8\u5bf9\u90a3\u4e9b\u627f\u62c5\u8fdd\u7ea6\u540e\u679c\uff08\u5982\u5de5\u8d44\u6263\u62bc\u548c\u50ac\u6536\uff09\u7684\u501f\u6b3e\u4eba\uff08\u5bf9\u7167\u7ec4\uff09\u6709\u6240\u63d0\u9ad8\u3002\u4e24\u7ec4\u501f\u6b3e\u4eba\u90fd\u901a\u8fc7\u4e0d\u540c\u7684\u673a\u5236\u8d21\u732e\u4e86\u6211\u4eec\u7684\u7814\u7a76\u53d1\u73b0\u3002\u5c3d\u7ba1\u6211\u4eec\u7684\u4f30\u8ba1\u53ef\u80fd\u4e0d\u76f4\u63a5\u9002\u7528\u4e8e\u5927\u89c4\u6a21\u7684\u5b66\u751f\u8d37\u6b3e\u51cf\u514d\uff0c\u4f46\u8fd9\u4e9b\u7ed3\u679c\u8bf4\u660e\u4e86\u51cf\u514d\u5bf9\u51cf\u8f7b\u56f0\u5883\u501f\u6b3e\u4eba\u503a\u52a1\u8d1f\u62c5\u540e\u679c\u7684\u76ca\u5904\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70005", "journal": "JF", "title": "Losing Control? The Two\u2010Decade Decline in Loan Covenant Violations", "authors": ["THOMAS P. GRIFFIN", "GREG NINI", "DAVID C. SMITH"], "author_details": [{"name": "THOMAS P. GRIFFIN", "affiliations": []}, {"name": "GREG NINI", "affiliations": []}, {"name": "DAVID C. SMITH", "affiliations": []}], "abstract": "ABSTRACT The annual proportion of U.S. public firms that reported a financial covenant violation fell roughly 70% between 1997 and 2019. To understand this trend, we develop an estimable model of covenant design that depends on the ability to differentiate between distressed and nondistressed borrowers and the relative costs associated with screening incorrectly. We find that the drop in violations is best explained by an increased willingness to forgo early detection of distressed borrowers in exchange for fewer inconsequential violations, which we attribute largely to a shift in the composition of public borrowers and partly to heightened investor sentiment during the 2010s.", "date": "2025-12-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70005", "title_zh": "\u5931\u53bb\u63a7\u5236\uff1f\u8d37\u6b3e\u5951\u7ea6\u8fdd\u89c4\u7387\u4e8c\u5341\u5e74\u4e0b\u964d", "abstract_zh": "\u6458\u8981 1997\u5e74\u81f32019\u5e74\u95f4\uff0c\u7f8e\u56fd\u4e0a\u5e02\u516c\u53f8\u62a5\u544a\u8d22\u52a1\u5951\u7ea6\u8fdd\u89c4\u7684\u6bd4\u4f8b\u4e0b\u964d\u4e86\u7ea670%\u3002\u4e3a\u4e86\u7406\u89e3\u8fd9\u4e00\u8d8b\u52bf\uff0c\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u53ef\u4f30\u8ba1\u7684\u5951\u7ea6\u8bbe\u8ba1\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u4f9d\u8d56\u4e8e\u533a\u5206\u56f0\u5883\u501f\u6b3e\u4eba\u4e0e\u975e\u56f0\u5883\u501f\u6b3e\u4eba\u80fd\u529b\uff0c\u4ee5\u53ca\u9519\u8bef\u7b5b\u67e5\u6240\u5173\u8054\u7684\u76f8\u5bf9\u6210\u672c\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fdd\u89c4\u7387\u7684\u4e0b\u964d\u4e3b\u8981\u5f52\u56e0\u4e8e\u4f01\u4e1a\u66f4\u613f\u610f\u653e\u5f03\u5bf9\u56f0\u5883\u501f\u6b3e\u4eba\u7684\u65e9\u671f\u8bc6\u522b\uff0c\u4ee5\u6362\u53d6\u66f4\u5c11\u7684\u65e0\u5b9e\u8d28\u5f71\u54cd\u7684\u8fdd\u89c4\uff0c\u8fd9\u4e00\u73b0\u8c61\u4e3b\u8981\u6e90\u4e8e\u4e0a\u5e02\u516c\u53f8\u501f\u6b3e\u4eba\u7ed3\u6784\u7684\u53d8\u5316\uff0c\u90e8\u5206\u4e5f\u6e90\u4e8e2010\u5e74\u4ee3\u6295\u8d44\u8005\u60c5\u7eea\u7684\u9ad8\u6da8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102494", "journal": "JFQA", "title": "Financing Innovation Under Ambiguity", "authors": ["Wenbin Cao", "Xiaoman Duan", "Hening Liu"], "author_details": [{"name": "Wenbin Cao", "affiliations": ["Sam Houston State University Department of Finance and Banking"]}, {"name": "Xiaoman Duan", "affiliations": ["Sam Houston State University Department of Finance and Banking"]}, {"name": "Hening Liu", "affiliations": ["University of Manchester Alliance Manchester Business School"]}], "abstract": "Abstract We develop a real options model in which an entrepreneur facing ambiguity makes optimal investment and financing decisions for an innovation project. We introduce jumps in innovation returns and model investors\u2019 aversion to ambiguity in both diffusion and jump risks. Debt accelerates investment by lowering the threshold and shortening expected waiting time, thereby increasing project value. This effect strengthens under greater ambiguity, offering a novel rationale for why debt\u2014not equity\u2014fosters innovation. Our results provide a coherent explanation for recent empirical findings on debt\u2019s role in innovation and contribute to the broader literature on investment under uncertainty.", "date": "2025-12-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102494", "title_zh": "\u5728\u4e0d\u786e\u5b9a\u6027\u4e0b\u7684\u521b\u65b0\u878d\u8d44", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5b9e\u7269\u671f\u6743\u6a21\u578b\uff0c\u7814\u7a76\u5728\u9762\u4e34\u4e0d\u786e\u5b9a\u6027\u65f6\uff0c\u4f01\u4e1a\u5bb6\u5982\u4f55\u5bf9\u521b\u65b0\u9879\u76ee\u505a\u51fa\u6700\u4f18\u7684\u6295\u8d44\u548c\u878d\u8d44\u51b3\u7b56\u3002\u6211\u4eec\u5f15\u5165\u4e86\u521b\u65b0\u56de\u62a5\u4e2d\u7684\u8df3\u8dc3\uff0c\u5e76\u5efa\u6a21\u6295\u8d44\u8005\u5bf9\u6269\u6563\u98ce\u9669\u548c\u8df3\u8dc3\u98ce\u9669\u7684\u4e0d\u786e\u5b9a\u6027\u538c\u6076\u3002\u503a\u52a1\u901a\u8fc7\u964d\u4f4e\u6295\u8d44\u95e8\u69db\u5e76\u7f29\u77ed\u9884\u671f\u7b49\u5f85\u65f6\u95f4\uff0c\u4ece\u800c\u63d0\u5347\u9879\u76ee\u4ef7\u503c\u3002\u8fd9\u4e00\u6548\u5e94\u5728\u4e0d\u786e\u5b9a\u6027\u66f4\u5927\u7684\u60c5\u51b5\u4e0b\u66f4\u52a0\u663e\u8457\uff0c\u4e3a\u503a\u52a1\u2014\u2014\u800c\u975e\u80a1\u6743\u2014\u2014\u4fc3\u8fdb\u521b\u65b0\u63d0\u4f9b\u4e86\u65b0\u7684\u7406\u8bba\u4f9d\u636e\u3002\u6211\u4eec\u7684\u7ed3\u679c\u4e3a\u8fd1\u671f\u5173\u4e8e\u503a\u52a1\u5728\u521b\u65b0\u4e2d\u4f5c\u7528\u7684\u5b9e\u8bc1\u53d1\u73b0\u63d0\u4f9b\u4e86\u8fde\u8d2f\u7684\u89e3\u91ca\uff0c\u5e76\u4e30\u5bcc\u4e86\u5173\u4e8e\u4e0d\u786e\u5b9a\u6027\u4e0b\u6295\u8d44\u7684\u73b0\u6709\u6587\u732e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102482", "journal": "JFQA", "title": "Does Litigation Risk Deter Insider Trading? Evidence from Universal Demand Laws", "authors": ["Binay K. Adhikari", "Anup Agrawal", "Bina Sharma"], "author_details": [{"name": "Binay K. Adhikari", "affiliations": ["UTSA: The University of Texas at San Antonio"]}, {"name": "Anup Agrawal", "affiliations": ["University of Alabama Culverhouse College of Business"]}, {"name": "Bina Sharma", "affiliations": ["Southern Utah University"]}], "abstract": "Abstract We exploit U.S. states\u2019 staggered adoption of Universal Demand (UD) laws to study how the risk of shareholder lawsuits affects insider trading. UD laws, which make it harder for shareholders to bring derivative lawsuits against directors and officers, lead to more profitable insider trades, especially sales. This effect is stronger among smaller firms and firms with lower institutional monitoring. After UD laws, the timing of insiders\u2019 trades also appears more opportunistic and riskier, for example, sales increase before negative earnings surprises. Overall, our study offers clean evidence that the threat of shareholder litigation deters opportunistic insider trading.", "date": "2025-12-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102482", "title_zh": "\u8bc9\u8bbc\u98ce\u9669\u662f\u5426\u6291\u5236\u5185\u5e55\u4ea4\u6613\uff1f\u6765\u81ea\u666e\u904d\u9700\u6c42\u6cd5\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u5229\u7528\u7f8e\u56fd\u5404\u5dde\u666e\u904d\u9700\u6c42\u6cd5\uff08UD\uff09\u5b9e\u65bd\u65f6\u95f4\u7684\u5dee\u5f02\u6027\uff0c\u7814\u7a76\u80a1\u4e1c\u8bc9\u8bbc\u98ce\u9669\u5982\u4f55\u5f71\u54cd\u5185\u5e55\u4ea4\u6613\u3002\u666e\u904d\u9700\u6c42\u6cd5\u901a\u8fc7\u4f7f\u80a1\u4e1c\u96be\u4ee5\u5bf9\u8463\u4e8b\u548c\u9ad8\u7ba1\u63d0\u8d77\u884d\u751f\u8bc9\u8bbc\uff0c\u5bfc\u81f4\u5185\u5e55\u4ea4\u6613\u66f4\u52a0\u76c8\u5229\uff0c\u5c24\u5176\u662f\u5356\u51fa\u4ea4\u6613\u3002\u8fd9\u4e00\u6548\u5e94\u5728\u89c4\u6a21\u8f83\u5c0f\u7684\u4f01\u4e1a\u4ee5\u53ca\u673a\u6784\u76d1\u7763\u8f83\u5f31\u7684\u4f01\u4e1a\u4e2d\u66f4\u4e3a\u663e\u8457\u3002\u5728\u5b9e\u65bd\u666e\u904d\u9700\u6c42\u6cd5\u4e4b\u540e\uff0c\u5185\u5e55\u4ea4\u6613\u7684\u65f6\u95f4\u70b9\u663e\u5f97\u66f4\u52a0\u81ea\u4e3b\u9009\u62e9\u4e14\u98ce\u9669\u66f4\u9ad8\uff0c\u4f8b\u5982\uff0c\u5356\u51fa\u4ea4\u6613\u5728\u8d1f\u9762\u8d22\u62a5\u610f\u5916\u53d1\u751f\u4e4b\u524d\u589e\u52a0\u3002\u603b\u4f53\u800c\u8a00\uff0c\u6211\u4eec\u7684\u7814\u7a76\u63d0\u4f9b\u4e86\u6e05\u6670\u7684\u8bc1\u636e\u8868\u660e\uff0c\u80a1\u4e1c\u8bc9\u8bbc\u7684\u5a01\u80c1\u4f1a\u6291\u5236\u6295\u673a\u6027\u7684\u5185\u5e55\u4ea4\u6613\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf055", "journal": "QJE", "title": "Marginal Returns to Public Universities", "authors": ["Jack Mountjoy"], "author_details": [{"name": "Jack Mountjoy", "affiliations": ["University of Chicago Booth School of Business and National Bureau of Economic Research ,"]}], "abstract": "Abstract This article studies the returns to enrolling in U.S. public universities by comparing the long-term outcomes of barely admitted versus barely rejected applicants. I use administrative admission records spanning all 35 public universities in Texas, which collectively enroll 10% of all American public university students, to systematically identify and employ decentralized cutoffs in SAT/ACT scores that generate discontinuities in admission and enrollment. The typical marginally admitted student gains an additional year of education in the four-year sector, becomes 12 percentage points more likely to ever earn a bachelor\u2019s degree, and eventually earns 8% more than their marginally rejected but otherwise identical counterpart. Marginally admitted students pay no additional tuition costs thanks to offsetting grant aid; cost-benefit calculations show internal rates of return of 26% for the marginal students themselves, 16% for society (which must pay for the additional education), and 7% for the government budget. Earnings gains are similar across admitting institutions of varying selectivity, but smaller for students from low-income families, who spend more time enrolled but complete fewer degrees and major in less lucrative fields. Finally, I develop a method to separately identify effects for students on the extensive margin of attending any university versus those on the margin of attending a more selective one, revealing larger effects on the extensive margin.", "date": "2025-12-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf055", "title_zh": "\u516c\u7acb\u5927\u5b66\u5165\u5b66\u7684\u8fb9\u9645\u6536\u76ca", "abstract_zh": "\u672c\u6587\u901a\u8fc7\u6bd4\u8f83 barely admitted\uff08 barely \u88ab\u5f55\u53d6\uff09\u4e0e barely rejected\uff08 barely \u88ab\u62d2\uff09\u7533\u8bf7\u8005\u7684\u957f\u671f\u7ed3\u679c\uff0c\u7814\u7a76\u8fdb\u5165\u7f8e\u56fd\u516c\u7acb\u5927\u5b66\u7684\u6536\u76ca\u3002\u6211\u5229\u7528\u8986\u76d6\u5f97\u6089\u5f97\u6240\u670935\u6240\u5fb7\u514b\u8428\u65af\u516c\u7acb\u5927\u5b66\u7684\u884c\u653f\u5165\u5b66\u8bb0\u5f55\uff08\u8fd9\u4e9b\u5927\u5b66\u5171\u62db\u6536\u4e86\u7f8e\u56fd\u516c\u7acb\u5927\u5b66\u5b66\u751f\u603b\u6570\u768410%\uff09\uff0c\u7cfb\u7edf\u6027\u5730\u8bc6\u522b\u5e76\u4f7f\u7528SAT/ACT\u5206\u6570\u4e2d\u7684\u5206\u6563\u5f0f\u622a\u6b62\u7ebf\uff0c\u4ea7\u751f\u5165\u5b66\u548c\u6ce8\u518c\u7684\u4e0d\u8fde\u7eed\u6027\u3002\u901a\u5e38\u60c5\u51b5\u4e0b\uff0c\u52c9\u5f3a\u88ab\u5f55\u53d6\u7684\u5b66\u751f\u591a\u83b7\u5f97\u4e00\u5e74\u7684\u56db\u5e74\u5236\u6559\u80b2\uff0c\u83b7\u5f97\u5b66\u58eb\u5b66\u4f4d\u7684\u53ef\u80fd\u6027\u63d0\u9ad812\u4e2a\u767e\u5206\u70b9\uff0c\u5e76\u6700\u7ec8\u6bd4\u5176\u52c9\u5f3a\u88ab\u62d2\u4f46\u5176\u4ed6\u6761\u4ef6\u5b8c\u5168\u76f8\u540c\u7684\u540c\u5b66\u591a\u8d5a8%\u3002\u52c9\u5f3a\u88ab\u5f55\u53d6\u7684\u5b66\u751f\u65e0\u9700\u989d\u5916\u652f\u4ed8\u5b66\u8d39\uff0c\u56e0\u4e3a\u6709\u62b5\u6d88\u6027\u7684\u52a9\u5b66\u91d1\uff1b\u6210\u672c\u6548\u76ca\u5206\u6790\u663e\u793a\uff0c\u5bf9\u8fb9\u9645\u5b66\u751f\u4e2a\u4eba\u800c\u8a00\uff0c\u5185\u90e8\u6536\u76ca\u7387\u4e3a26%\uff0c\u5bf9\u793e\u4f1a\uff08\u9700\u627f\u62c5\u989d\u5916\u6559\u80b2\u6210\u672c\uff09\u4e3a16%\uff0c\u5bf9\u653f\u5e9c\u9884\u7b97\u4e3a7%\u3002\u5728\u4e0d\u540c\u5f55\u53d6\u9009\u62e9\u6027\u673a\u6784\u4e2d\uff0c\u6536\u76ca\u76f8\u4f3c\uff0c\u4f46\u5bf9\u4e8e\u4f4e\u6536\u5165\u5bb6\u5ead\u5b66\u751f\u800c\u8a00\uff0c\u6536\u76ca\u8f83\u5c0f\uff0c\u4ed6\u4eec\u5728\u6821\u65f6\u95f4\u66f4\u957f\uff0c\u4f46\u5b8c\u6210\u7684\u5b66\u4f4d\u66f4\u5c11\uff0c\u4e14\u4e3b\u4fee\u9886\u57df\u6536\u5165\u8f83\u4f4e\u3002\u6700\u540e\uff0c\u6211\u5f00\u53d1\u4e86\u4e00\u79cd\u65b9\u6cd5\uff0c\u53ef\u4ee5\u5206\u522b\u8bc6\u522b\u90a3\u4e9b\u5728\u662f\u5426\u4e0a\u5927\u5b66\uff08\u5e7f\u6cdb\u8fb9\u9645\uff09\u4e0a\u7684\u5b66\u751f\u4e0e\u90a3\u4e9b\u5728\u662f\u5426\u8fdb\u5165\u66f4\u9009\u62e9\u6027\u5927\u5b66\u4e0a\u7684\u5b66\u751f\u7684\u5f71\u54cd\uff0c\u7ed3\u679c\u663e\u793a\u5728\u5e7f\u6cdb\u8fb9\u9645\u4e0a\u7684\u5f71\u54cd\u66f4\u5927\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf053", "journal": "QJE", "title": "Who\u2019s Afraid of the Minimum Wage? Measuring the Impacts on Independent Businesses Using Matched U.S. Tax Returns", "authors": ["Nirupama L Rao", "Max Risch"], "author_details": [{"name": "Nirupama L Rao", "affiliations": ["Ross School of Business, University of Michigan ,"]}, {"name": "Max Risch", "affiliations": ["Tepper School of Business, Carnegie Mellon University ,"]}], "abstract": "Abstract A common concern surrounding minimum wage policies is their impact on independent businesses, which are often feared to be less able to bear or pass on cost increases. We examine how these typically small and medium-size firms accommodate minimum wage increases along product and labor market margins using a matched owner-firm-worker panel data set drawn from the universe of U.S. tax records over a 10-year period, and using state minimum wage changes as identifying variation. We find that on average, firms in highly exposed industries do not substantially reduce employment\u2014they do not lay off workers but moderately reduce part-time hiring. Instead, these firms are able to fully finance the new labor costs with new revenues, leaving average owner profits unchanged. Higher wage floors, however, forestall entry, particularly for less productive firms, reducing the number of independent firms operating in these industries by roughly 2%. Yet these industries do not shrink; instead, incumbent responses and strong positive selection among entrants reshape industries that rely heavily on low-wage workers, yielding fewer but more productive firms after the cost shock. We also take a worker-level perspective to examine how potentially vulnerable individuals are affected by minimum wage increases. Using panels of low-earning and young workers, we find that their average earnings rise substantially with the minimum wage, while they are no less likely to be employed. Worker transitions indicate that minimum wage increases boost retention and that worker reallocation from independent firms toward corporations buffers disemployment impacts from reduced hiring at independent firms.", "date": "2025-12-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf053", "title_zh": "\u6700\u4f4e\u5de5\u8d44\u8c01\u5bb3\u6015\uff1f\u5229\u7528\u5339\u914d\u7684\u7f8e\u56fd\u7a0e\u52a1\u8bb0\u5f55\u8861\u91cf\u5176\u5bf9\u72ec\u7acb\u4f01\u4e1a\u7684\u51b2\u51fb", "abstract_zh": "\u6458\u8981 \u5173\u4e8e\u6700\u4f4e\u5de5\u8d44\u653f\u7b56\u7684\u5e38\u89c1\u62c5\u5fe7\u662f\u5176\u5bf9\u72ec\u7acb\u4f01\u4e1a\u7684\u51b2\u51fb\uff0c\u8fd9\u4e9b\u4f01\u4e1a\u901a\u5e38\u88ab\u8ba4\u4e3a\u66f4\u96be\u4ee5\u627f\u53d7\u6216\u8f6c\u5ac1\u6210\u672c\u589e\u52a0\u3002\u6211\u4eec\u5229\u7528\u4e00\u4e2a\u6765\u81ea\u7f8e\u56fd\u7a0e\u52a1\u8bb0\u5f55\u5168\u6837\u672c\u7684\u5339\u914d\u4f01\u4e1a\u6240\u6709\u8005-\u5458\u5de5\u9762\u677f\u6570\u636e\u96c6\uff0c\u8986\u76d610\u5e74\u671f\uff0c\u7ed3\u5408\u5404\u5dde\u6700\u4f4e\u5de5\u8d44\u53d8\u5316\u4f5c\u4e3a\u8bc6\u522b\u53d8\u91cf\uff0c\u7814\u7a76\u4e86\u8fd9\u4e9b\u901a\u5e38\u89c4\u6a21\u8f83\u5c0f\u548c\u4e2d\u7b49\u7684\u4f01\u4e1a\u5982\u4f55\u5728\u4ea7\u54c1\u5e02\u573a\u548c\u52b3\u52a8\u529b\u5e02\u573a\u65b9\u9762\u5e94\u5bf9\u6700\u4f4e\u5de5\u8d44\u4e0a\u6da8\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u9ad8\u5ea6\u66b4\u9732\u4e8e\u6700\u4f4e\u5de5\u8d44\u4e0a\u6da8\u7684\u884c\u4e1a\u4f01\u4e1a\u5e73\u5747\u5e76\u672a\u5927\u5e45\u51cf\u5c11\u96c7\u4f63\u2014\u2014\u6ca1\u6709\u88c1\u5458\uff0c\u4f46\u9002\u5ea6\u51cf\u5c11\u4e86\u517c\u804c\u62db\u8058\u3002\u8fd9\u4e9b\u4f01\u4e1a\u80fd\u591f\u901a\u8fc7\u65b0\u589e\u6536\u5165\u5b8c\u5168\u8986\u76d6\u65b0\u589e\u7684\u52b3\u52a8\u529b\u6210\u672c\uff0c\u4ece\u800c\u4fdd\u6301\u5e73\u5747\u6240\u6709\u8005\u5229\u6da6\u4e0d\u53d8\u3002\u7136\u800c\uff0c\u66f4\u9ad8\u7684\u5de5\u8d44\u95e8\u69db\u6291\u5236\u4e86\u65b0\u4f01\u4e1a\u7684\u8fdb\u5165\uff0c\u5c24\u5176\u662f\u5bf9\u751f\u4ea7\u7387\u8f83\u4f4e\u7684\u4f01\u4e1a\uff0c\u5bfc\u81f4\u8fd9\u4e9b\u884c\u4e1a\u8fd0\u8425\u7684\u72ec\u7acb\u4f01\u4e1a\u6570\u91cf\u51cf\u5c11\u7ea62%\u3002\u4f46\u8fd9\u4e9b\u884c\u4e1a\u5e76\u672a\u840e\u7f29\uff1b\u76f8\u53cd\uff0c\u73b0\u6709\u4f01\u4e1a\u7684\u5e94\u5bf9\u4ee5\u53ca\u65b0\u8fdb\u5165\u4f01\u4e1a\u4e2d\u7684\u79ef\u6781\u7b5b\u9009\u91cd\u5851\u4e86\u4f9d\u8d56\u4f4e\u85aa\u5de5\u4eba\u7684\u884c\u4e1a\u683c\u5c40\uff0c\u6700\u7ec8\u5f62\u6210\u6570\u91cf\u66f4\u5c11\u4f46\u751f\u4ea7\u7387\u66f4\u9ad8\u7684\u4f01\u4e1a\u3002\u6211\u4eec\u8fd8\u4ece\u52b3\u52a8\u8005\u5c42\u9762\u8003\u5bdf\u4e86\u6700\u4f4e\u5de5\u8d44\u4e0a\u6da8\u5bf9\u53ef\u80fd\u8106\u5f31\u7fa4\u4f53\u7684\u5f71\u54cd\u3002\u5229\u7528\u4f4e\u6536\u5165\u548c\u5e74\u8f7b\u5de5\u4eba\u7684\u9762\u677f\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u4ed6\u4eec\u7684\u5e73\u5747\u6536\u5165\u663e\u8457\u4e0a\u5347\uff0c\u4e14\u5c31\u4e1a\u6982\u7387\u5e76\u672a\u964d\u4f4e\u3002\u5de5\u4eba\u6d41\u52a8\u6570\u636e\u663e\u793a\uff0c\u6700\u4f4e\u5de5\u8d44\u4e0a\u6da8\u63d0\u9ad8\u4e86\u5458\u5de5\u7559\u5b58\u7387\uff0c\u540c\u65f6\u5de5\u4eba\u4ece\u72ec\u7acb\u4f01\u4e1a\u5411\u4f01\u4e1a\u7684\u8f6c\u79fb\u7f13\u89e3\u4e86\u72ec\u7acb\u4f01\u4e1a\u62db\u8058\u51cf\u5c11\u5e26\u6765\u7684\u5931\u4e1a\u51b2\u51fb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70011", "journal": "JF", "title": "Adverse Selection in Corporate Loan Markets", "authors": ["MEHDI BEYHAGHI", "CESARE FRACASSI", "GREGORY WEITZNER"], "author_details": [{"name": "MEHDI BEYHAGHI", "affiliations": []}, {"name": "CESARE FRACASSI", "affiliations": []}, {"name": "GREGORY WEITZNER", "affiliations": []}], "abstract": "ABSTRACT Theories of competition typically predict a positive relationship between market concentration and prices. However, in loan markets, adverse selection can reverse this relationship as riskier borrowers become more likely to receive funding. Using supervisory data, we show that interest rates, borrower risk, and lending volume are higher in markets with more banks. We also create a novel measure of markup that is orthogonal to borrower risk, and find that, consistent with adverse selection, markups are higher after repeated borrowing relationships. Finally, we use a shock to large banks' lending costs to provide further support for the adverse selection channel.", "date": "2025-12-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70011", "title_zh": "\u4f01\u4e1a\u8d37\u6b3e\u5e02\u573a\u4e2d\u7684\u9006\u5411\u9009\u62e9", "abstract_zh": "\u6458\u8981 \u901a\u5e38\u7684\u5e02\u573a\u7ade\u4e89\u7406\u8bba\u9884\u6d4b\u5e02\u573a\u96c6\u4e2d\u5ea6\u4e0e\u4ef7\u683c\u4e4b\u95f4\u5448\u6b63\u76f8\u5173\u5173\u7cfb\u3002\u7136\u800c\uff0c\u5728\u8d37\u6b3e\u5e02\u573a\u4e2d\uff0c\u9006\u5411\u9009\u62e9\u53ef\u80fd\u5bfc\u81f4\u8fd9\u4e00\u5173\u7cfb\u53cd\u8f6c\uff0c\u5373\u98ce\u9669\u66f4\u9ad8\u7684\u501f\u6b3e\u4eba\u66f4\u6709\u53ef\u80fd\u83b7\u5f97\u878d\u8d44\u3002\u5229\u7528\u76d1\u7ba1\u6570\u636e\uff0c\u6211\u4eec\u53d1\u73b0\u94f6\u884c\u6570\u91cf\u8d8a\u591a\u7684\u5e02\u573a\u4e2d\uff0c\u5229\u7387\u3001\u501f\u6b3e\u4eba\u98ce\u9669\u4ee5\u53ca\u8d37\u6b3e\u89c4\u6a21\u5747\u66f4\u9ad8\u3002\u6211\u4eec\u8fd8\u521b\u5efa\u4e86\u4e00\u4e2a\u4e0e\u501f\u6b3e\u4eba\u98ce\u9669\u65e0\u5173\u7684\u65b0\u578b\u6ea2\u4ef7\u6307\u6807\uff0c\u7ed3\u679c\u8868\u660e\uff0c\u5728\u91cd\u590d\u501f\u8d37\u5173\u7cfb\u4e4b\u540e\uff0c\u6ea2\u4ef7\u6c34\u5e73\u66f4\u9ad8\uff0c\u8fd9\u4e0e\u9006\u5411\u9009\u62e9\u7684\u673a\u5236\u4e00\u81f4\u3002\u6700\u540e\uff0c\u6211\u4eec\u5229\u7528\u5927\u578b\u94f6\u884c\u8d37\u6b3e\u6210\u672c\u7a81\u7136\u4e0a\u5347\u7684\u51b2\u51fb\uff0c\u8fdb\u4e00\u6b65\u652f\u6301\u4e86\u9006\u5411\u9009\u62e9\u7684\u4f5c\u7528\u6e20\u9053\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70001", "journal": "JF", "title": "Paying Too Much? Borrower Sophistication and Overpayment in the U.S. Mortgage Market", "authors": ["NEIL BHUTTA", "ANDREAS FUSTER", "AUREL HIZMO"], "author_details": [{"name": "NEIL BHUTTA", "affiliations": []}, {"name": "ANDREAS FUSTER", "affiliations": []}, {"name": "AUREL HIZMO", "affiliations": []}], "abstract": "ABSTRACT Comparing mortgage rates that borrowers obtain to rates that lenders could offer for the same loan, we find that many homeowners significantly overpay for their mortgage, with overpayment varying across borrower types and with market interest rates. Survey data reveal that borrowers' mortgage knowledge and shopping behavior strongly correlate with the rates they secure. We also document substantial variation in how expensive and profitable lenders are, without any evidence that expensive loans are associated with a better borrower experience. Despite many lenders operating in the U.S. mortgage market, limited borrower sophistication may provide lenders with market power.", "date": "2025-12-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70001", "title_zh": "\u652f\u4ed8\u8fc7\u591a\uff1f\u501f\u6b3e\u4eba\u6210\u719f\u5ea6\u4e0e\u7f8e\u56fd\u623f\u8d37\u5e02\u573a\u8fc7\u5ea6\u652f\u4ed8", "abstract_zh": "\u6458\u8981 \u6bd4\u8f83\u501f\u6b3e\u4eba\u5b9e\u9645\u83b7\u5f97\u7684\u623f\u8d37\u5229\u7387\u4e0e\u8d37\u6b3e\u673a\u6784\u5bf9\u76f8\u540c\u8d37\u6b3e\u53ef\u63d0\u4f9b\u7684\u5229\u7387\uff0c\u6211\u4eec\u53d1\u73b0\u8bb8\u591a\u623f\u4e3b\u4e3a\u5176\u623f\u8d37\u652f\u4ed8\u4e86\u8fc7\u591a\u6b3e\u9879\uff0c\u4e14\u8fc7\u5ea6\u652f\u4ed8\u5728\u4e0d\u540c\u501f\u6b3e\u4eba\u7c7b\u578b\u548c\u5e02\u573a\u5229\u7387\u6c34\u5e73\u4e0b\u5b58\u5728\u5dee\u5f02\u3002\u8c03\u67e5\u6570\u636e\u8868\u660e\uff0c\u501f\u6b3e\u4eba\u7684\u623f\u8d37\u77e5\u8bc6\u548c\u8d2d\u7269\u884c\u4e3a\u4e0e\u5176\u6240\u83b7\u5f97\u7684\u5229\u7387\u5bc6\u5207\u76f8\u5173\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\u8d37\u6b3e\u673a\u6784\u5728\u8d37\u6b3e\u4ef7\u683c\u4e0a\u7684\u5dee\u5f02\u663e\u8457\uff0c\u4f46\u6ca1\u6709\u4efb\u4f55\u8bc1\u636e\u8868\u660e\u9ad8\u4ef7\u8d37\u6b3e\u4e0e\u66f4\u597d\u7684\u501f\u6b3e\u4eba\u4f53\u9a8c\u76f8\u5173\u3002\u5c3d\u7ba1\u7f8e\u56fd\u623f\u8d37\u5e02\u573a\u5b58\u5728\u4f17\u591a\u8d37\u6b3e\u673a\u6784\uff0c\u4f46\u501f\u6b3e\u4eba\u77e5\u8bc6\u6c34\u5e73\u6709\u9650\u53ef\u80fd\u4e3a\u8d37\u6b3e\u673a\u6784\u63d0\u4f9b\u4e86\u5e02\u573a\u6743\u529b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70012", "journal": "JF", "title": "Going Public and the Internal Organization of the Firm", "authors": ["DANIEL BIAS", "BENJAMIN LOCHNER", "STEFAN OBERNBERGER", "MERIH SEVILIR"], "author_details": [{"name": "DANIEL BIAS", "affiliations": []}, {"name": "BENJAMIN LOCHNER", "affiliations": []}, {"name": "STEFAN OBERNBERGER", "affiliations": []}, {"name": "MERIH SEVILIR", "affiliations": []}], "abstract": "ABSTRACT This paper examines how initial public offerings (IPOs) affect firms' internal organization. We find that IPO firms become more hierarchical and standardized organizations, characterized by additional layers, more managers, smaller control spans, and larger administrative functions. These changes occur mostly in preparation for the IPO and can be only partially explained by growth. IPO firms with greater human capital risk experience larger hierarchical changes. Hierarchical changes help firms standardize employee roles and formalize internal processes. Our results suggest that firms reorganize to reduce their dependence on key individuals' human capital when transitioning to public markets.", "date": "2025-12-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70012", "title_zh": "\u4e0a\u5e02\u4e0e\u4f01\u4e1a\u5185\u90e8\u7ec4\u7ec7\u7ed3\u6784", "abstract_zh": "\u6458\u8981 \u672c\u6587\u7814\u7a76\u4e86\u9996\u6b21\u516c\u5f00\u52df\u80a1\uff08IPO\uff09\u5bf9\u4f01\u4e1a\u5185\u90e8\u7ec4\u7ec7\u7ed3\u6784\u7684\u5f71\u54cd\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u4e0a\u5e02\u4f01\u4e1a\u53d8\u5f97\u66f4\u52a0\u5c42\u7ea7\u5316\u548c\u6807\u51c6\u5316\uff0c\u8868\u73b0\u4e3a\u7ba1\u7406\u5c42\u7ea7\u589e\u52a0\u3001\u7ba1\u7406\u4eba\u5458\u589e\u591a\u3001\u7ba1\u7406\u8de8\u5ea6\u7f29\u5c0f\u4ee5\u53ca\u884c\u653f\u804c\u80fd\u6269\u5927\u3002\u8fd9\u4e9b\u53d8\u5316\u4e3b\u8981\u53d1\u751f\u5728\u4e0a\u5e02\u51c6\u5907\u9636\u6bb5\uff0c\u4e14\u90e8\u5206\u53ef\u7531\u4f01\u4e1a\u6210\u957f\u89e3\u91ca\u3002\u90a3\u4e9b\u9762\u4e34\u66f4\u5927\u4eba\u529b\u8d44\u672c\u98ce\u9669\u7684\u4e0a\u5e02\u4f01\u4e1a\uff0c\u5176\u5c42\u7ea7\u5316\u53d8\u5316\u66f4\u4e3a\u663e\u8457\u3002\u5c42\u7ea7\u5316\u53d8\u9769\u6709\u52a9\u4e8e\u4f01\u4e1a\u6807\u51c6\u5316\u5458\u5de5\u804c\u8d23\u5e76\u6b63\u5f0f\u5316\u5185\u90e8\u6d41\u7a0b\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u4f01\u4e1a\u5728\u5411\u516c\u5f00\u5e02\u573a\u8fc7\u6e21\u65f6\uff0c\u4f1a\u8fdb\u884c\u91cd\u7ec4\u4ee5\u964d\u4f4e\u5bf9\u5173\u952e\u4e2a\u4f53\u4eba\u529b\u8d44\u672c\u7684\u4f9d\u8d56\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102469", "journal": "JFQA", "title": "Women in Politics: The Effect on Board Diversity", "authors": ["Simi Kedia", "Ankur Pareek"], "author_details": [{"name": "Simi Kedia", "affiliations": ["Rutgers University"]}, {"name": "Ankur Pareek", "affiliations": ["Bucknell University"]}], "abstract": "Abstract We use a sharp regression discontinuity design (RDD) to show that victories by women candidates in close House, Senate, and gubernatorial elections lead to an increase in female directors in firms located in the candidates\u2019 districts. The causal effect is higher when the media coverage of the woman candidate is higher, when voter turnout is high, and when firms have more local directors and local institutional investors. The heterogeneous regression discontinuity (RD) effects suggest that electoral wins may influence local gender norms and firms\u2019 board diversity through multiple channels, including conveying majority views on gender-related social norms, increasing exposure to exemplar women, and facilitating learning about women\u2019s different but effective leadership styles. The evidence suggests a potential spillover effect from women\u2019s political leadership to the corporate world.", "date": "2025-12-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102469", "title_zh": "\u5973\u6027\u53c2\u653f\u5bf9\u8463\u4e8b\u4f1a\u591a\u6837\u6027\u7684\u5f71\u54cd", "abstract_zh": "\u6211\u4eec\u91c7\u7528\u4e00\u79cd\u7cbe\u786e\u7684\u56de\u5f52\u65ad\u70b9\u8bbe\u8ba1\uff08RDD\uff09\uff0c\u53d1\u73b0\u5973\u6027\u5019\u9009\u4eba\u8d62\u5f97\u7d27\u90bb\u7684\u56fd\u4f1a\u8bae\u5458\u3001\u53c2\u8bae\u5458\u548c\u5dde\u957f\u9009\u4e3e\u540e\uff0c\u5176\u6240\u5728\u9009\u533a\u5185\u7684\u4f01\u4e1a\u5973\u6027\u8463\u4e8b\u6bd4\u4f8b\u4f1a\u663e\u8457\u4e0a\u5347\u3002\u5f53\u5973\u6027\u5019\u9009\u4eba\u7684\u5a92\u4f53\u62a5\u9053\u7a0b\u5ea6\u66f4\u9ad8\u3001\u9009\u6c11\u53c2\u4e0e\u5ea6\u66f4\u9ad8\uff0c\u4ee5\u53ca\u4f01\u4e1a\u62e5\u6709\u66f4\u591a\u672c\u5730\u8463\u4e8b\u548c\u672c\u5730\u673a\u6784\u6295\u8d44\u8005\u65f6\uff0c\u8fd9\u79cd\u56e0\u679c\u6548\u5e94\u66f4\u4e3a\u663e\u8457\u3002\u5f02\u8d28\u6027\u56de\u5f52\u65ad\u70b9\uff08RD\uff09\u5206\u6790\u8868\u660e\uff0c\u9009\u4e3e\u80dc\u5229\u53ef\u80fd\u901a\u8fc7\u591a\u79cd\u6e20\u9053\u5f71\u54cd\u5f53\u5730\u6027\u522b\u89c4\u8303\u4ee5\u53ca\u4f01\u4e1a\u8463\u4e8b\u4f1a\u7684\u591a\u6837\u6027\uff0c\u5305\u62ec\u4f20\u9012\u5173\u4e8e\u6027\u522b\u76f8\u5173\u793e\u4f1a\u89c4\u8303\u7684\u591a\u6570\u89c2\u70b9\u3001\u589e\u52a0\u5bf9\u5973\u6027\u5178\u8303\u7684\u63a5\u89e6\uff0c\u4ee5\u53ca\u4fc3\u8fdb\u5bf9\u4f01\u4e1a\u5973\u6027\u4e0d\u540c\u4f46\u6709\u6548\u9886\u5bfc\u98ce\u683c\u7684\u8ba4\u77e5\u3002\u8fd9\u4e9b\u8bc1\u636e\u8868\u660e\uff0c\u5973\u6027\u653f\u6cbb\u9886\u5bfc\u53ef\u80fd\u5bf9\u5546\u4e1a\u4e16\u754c\u4ea7\u751f\u6ea2\u51fa\u6548\u5e94\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1017/s0022109025102457", "journal": "JFQA", "title": "Optimal Portfolio Size Under Parameter Uncertainty", "authors": ["Nathan Lassance", "Rodolphe Vanderveken", "Fr\u00e9d\u00e9ric Vrins"], "author_details": [{"name": "Nathan Lassance", "affiliations": ["UCLouvain LFIN/LIDAM"]}, {"name": "Rodolphe Vanderveken", "affiliations": ["UCLouvain LFIN/LIDAM"]}, {"name": "Fr\u00e9d\u00e9ric Vrins", "affiliations": ["UCLouvain LFIN/LIDAM", "HEC Montr\u00e9al"]}], "abstract": "Abstract We introduce a method to determine the investor\u2019s optimal portfolio size that maximizes the expected out-of-sample utility under parameter uncertainty. This portfolio size trades off between accessing investment opportunities and limiting the number of estimated parameters. Unlike sparse methods such as lasso, which exclude assets during the optimization step, our approach fixes the optimal number of assets before optimizing the portfolio weights, which improves robustness and provides greater flexibility in practical implementations. Empirically, our size-optimized portfolios outperform their counterparts applied to all available assets. Our methodology renders portfolio theory valuable even when the data-set dimension and sample size are comparable.", "date": "2025-12-04", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102457", "title_zh": "\u53c2\u6570\u4e0d\u786e\u5b9a\u6027\u4e0b\u7684\u6700\u4f18\u6295\u8d44\u7ec4\u5408\u89c4\u6a21", "abstract_zh": "\u6211\u4eec\u63d0\u51fa\u4e00\u79cd\u65b9\u6cd5\uff0c\u4ee5\u5728\u53c2\u6570\u4e0d\u786e\u5b9a\u6027\u4e0b\u6700\u5927\u5316\u6837\u672c\u5916\u9884\u671f\u6548\u7528\u6765\u786e\u5b9a\u6295\u8d44\u8005\u7684\u6700\u4f18\u6295\u8d44\u7ec4\u5408\u89c4\u6a21\u3002\u8be5\u6295\u8d44\u7ec4\u5408\u89c4\u6a21\u5728\u83b7\u53d6\u6295\u8d44\u673a\u4f1a\u4e0e\u9650\u5236\u4f30\u8ba1\u53c2\u6570\u6570\u91cf\u4e4b\u95f4\u8fdb\u884c\u6743\u8861\u3002\u4e0d\u540c\u4e8elasso\u7b49\u7a00\u758f\u65b9\u6cd5\u5728\u4f18\u5316\u6b65\u9aa4\u4e2d\u6392\u9664\u8d44\u4ea7\uff0c\u6211\u4eec\u7684\u65b9\u6cd5\u5728\u4f18\u5316\u6295\u8d44\u7ec4\u5408\u6743\u91cd\u4e4b\u524d\u56fa\u5b9a\u6700\u4f18\u8d44\u4ea7\u6570\u91cf\uff0c\u4ece\u800c\u63d0\u9ad8\u4e86\u7a33\u5065\u6027\uff0c\u5e76\u5728\u5b9e\u9645\u5e94\u7528\u4e2d\u63d0\u4f9b\u4e86\u66f4\u5927\u7684\u7075\u6d3b\u6027\u3002\u5b9e\u8bc1\u7ed3\u679c\u8868\u660e\uff0c\u6211\u4eec\u7684\u89c4\u6a21\u4f18\u5316\u6295\u8d44\u7ec4\u5408\u5728\u5e94\u7528\u4e8e\u6240\u6709\u53ef\u7528\u8d44\u4ea7\u7684\u5bf9\u5e94\u7ec4\u5408\u4e2d\u8868\u73b0\u66f4\u4f18\u3002\u6211\u4eec\u7684\u65b9\u6cd5\u4f7f\u5f97\u6295\u8d44\u7ec4\u5408\u7406\u8bba\u5728\u6570\u636e\u96c6\u7ef4\u5ea6\u4e0e\u6837\u672c\u91cf\u76f8\u5f53\u7684\u60c5\u51b5\u4e0b\u4f9d\u7136\u5177\u6709\u4ef7\u503c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1093/qje/qjaf054", "journal": "QJE", "title": "Enlightenment Ideals and Belief in Progress in the Run-up to the Industrial Revolution: A Textual Analysis", "authors": ["Ali Almelhem", "Murat Iyigun", "Austin Kennedy", "Jared Rubin"], "author_details": [{"name": "Ali Almelhem", "affiliations": ["Ministry of Economy and Planning ,"]}, {"name": "Murat Iyigun", "affiliations": ["University of Colorado, Boulder, and Institue of Labor Economics ,"]}, {"name": "Austin Kennedy", "affiliations": ["NRG Energy ,"]}, {"name": "Jared Rubin", "affiliations": ["Chapman University ,"]}], "abstract": "Abstract We trace the evolution of the language of science, religion, and political economy in the centuries leading to the British Industrial Revolution. Using textual analysis of 264,443 works printed in England between 1500 and 1900, we test whether British culture manifested a belief in progress associated with science and industry. Our analysis yields three main findings. First, there was a separation in the languages of science and religion beginning in the mid-eighteenth century. Second, volumes using language at the nexus of science and political economy became more progress-oriented during the Enlightenment. Third, volumes using industrial language\u2014especially those at the science-political economy nexus\u2014were more progress-oriented beginning in the eighteenth century.", "date": "2025-11-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf054", "title_zh": "\u542f\u8499\u601d\u60f3\u4e0e\u8fdb\u6b65\u4fe1\u5ff5\u5728\u5de5\u4e1a\u9769\u547d\u524d\u591c\u7684\u6f14\u53d8\uff1a\u4e00\u9879\u6587\u672c\u5206\u6790", "abstract_zh": "\u6211\u4eec\u8ffd\u6eaf\u4e86\u79d1\u5b66\u3001\u5b97\u6559\u548c\u653f\u6cbb\u7ecf\u6d4e\u5b66\u8bed\u8a00\u5728\u901a\u5f80\u82f1\u56fd\u5de5\u4e1a\u9769\u547d\u51e0\u4e2a\u4e16\u7eaa\u4e2d\u7684\u6f14\u53d8\u3002\u901a\u8fc7\u5bf91500\u5e74\u81f31900\u5e74\u95f4\u82f1\u683c\u5170\u51fa\u7248\u7684264,443\u90e8\u4f5c\u54c1\u8fdb\u884c\u6587\u672c\u5206\u6790\uff0c\u6211\u4eec\u68c0\u9a8c\u4e86\u82f1\u56fd\u6587\u5316\u662f\u5426\u8868\u73b0\u51fa\u4e0e\u79d1\u5b66\u548c\u5de5\u4e1a\u76f8\u5173\u7684\u8fdb\u6b65\u4fe1\u5ff5\u3002\u6211\u4eec\u7684\u5206\u6790\u5f97\u51fa\u4e09\u4e2a\u4e3b\u8981\u53d1\u73b0\u3002\u7b2c\u4e00\uff0c\u79d1\u5b66\u4e0e\u5b97\u6559\u7684\u8bed\u8a00\u5728\u5341\u516b\u4e16\u7eaa\u4e2d\u671f\u5f00\u59cb\u51fa\u73b0\u5206\u79bb\u3002\u7b2c\u4e8c\uff0c\u878d\u5408\u79d1\u5b66\u4e0e\u653f\u6cbb\u7ecf\u6d4e\u5b66\u8bed\u8a00\u7684\u4f5c\u54c1\u5728\u542f\u8499\u65f6\u671f\u53d8\u5f97\u66f4\u52a0\u5177\u6709\u8fdb\u6b65\u5bfc\u5411\u3002\u7b2c\u4e09\uff0c\u4f7f\u7528\u5de5\u4e1a\u8bed\u8a00\u2014\u2014\u5c24\u5176\u662f\u5904\u4e8e\u79d1\u5b66\u4e0e\u653f\u6cbb\u7ecf\u6d4e\u5b66\u4ea4\u754c\u5904\u7684\u4f5c\u54c1\u2014\u2014\u4ece\u5341\u516b\u4e16\u7eaa\u5f00\u59cb\u8868\u73b0\u51fa\u66f4\u5f3a\u7684\u8fdb\u5c55\u5bfc\u5411\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6587\u672c\u5206\u6790"]}, {"doi": "10.1111/jofi.13508", "journal": "JF", "title": "Can Social Media Inform Corporate Decisions? Evidence from Merger Withdrawals", "authors": ["J. ANTHONY COOKSON", "MARINA NIESSNER", "CHRISTOPH SCHILLER"], "author_details": [{"name": "J. ANTHONY COOKSON", "affiliations": []}, {"name": "MARINA NIESSNER", "affiliations": []}, {"name": "CHRISTOPH SCHILLER", "affiliations": []}], "abstract": "ABSTRACT This paper studies whether social media sentiment predicts merger withdrawals. We find that a one\u2010standard\u2010deviation increase in social media sentiment after a merger announcement is associated with a 0.64 percentage point lower probability of withdrawal (16.6% of the average). This effect is unexplained by abnormal price reactions, traditional news, and analyst recommendations. Consistent with manager learning, the informativeness of social media strengthens after firms start corporate Twitter accounts. The informativeness is driven by longer acquisition\u2010related tweets by fundamental investors, rather than memes and price trend tweets. These findings suggest that social media signals can be important for corporate decisions.", "date": "2025-11-25", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.13508", "title_zh": "\u793e\u4ea4\u5a92\u4f53\u80fd\u5426\u5f71\u54cd\u4f01\u4e1a\u51b3\u7b56\uff1f\u6765\u81ea\u5e76\u8d2d\u64a4\u56de\u7684\u8bc1\u636e", "abstract_zh": "\u6458\u8981 \u672c\u6587\u7814\u7a76\u793e\u4ea4\u5a92\u4f53\u60c5\u7eea\u662f\u5426\u80fd\u9884\u6d4b\u5e76\u8d2d\u64a4\u56de\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5e76\u8d2d\u516c\u544a\u540e\u793e\u4ea4\u5a92\u4f53\u60c5\u7eea\u589e\u52a0\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u4f1a\u4f7f\u64a4\u56de\u6982\u7387\u964d\u4f4e0.64\u4e2a\u767e\u5206\u70b9\uff08\u5e73\u5747\u4e3a16.6%\uff09\u3002\u8fd9\u4e00\u6548\u5e94\u65e0\u6cd5\u901a\u8fc7\u5f02\u5e38\u4ef7\u683c\u53cd\u5e94\u3001\u4f20\u7edf\u65b0\u95fb\u548c\u5206\u6790\u5e08\u5efa\u8bae\u6765\u89e3\u91ca\u3002\u4e0e\u7ba1\u7406\u5c42\u5b66\u4e60\u4e00\u81f4\uff0c\u793e\u4ea4\u5a92\u4f53\u4fe1\u606f\u7684\u6709\u6548\u6027\u5728\u4f01\u4e1a\u5f00\u59cb\u4f7f\u7528\u4f01\u4e1a\u63a8\u7279\u8d26\u6237\u540e\u589e\u5f3a\u3002\u8fd9\u79cd\u4fe1\u606f\u6709\u6548\u6027\u4e3b\u8981\u7531\u57fa\u672c\u9762\u6295\u8d44\u8005\u53d1\u5e03\u7684\u66f4\u957f\u7684\u4e0e\u6536\u8d2d\u76f8\u5173\u7684\u63a8\u6587\u9a71\u52a8\uff0c\u800c\u975e\u8ff7\u56e0\u548c\u4ef7\u683c\u8d8b\u52bf\u63a8\u6587\u3002\u8fd9\u4e9b\u53d1\u73b0\u8868\u660e\uff0c\u793e\u4ea4\u5a92\u4f53\u4fe1\u53f7\u5bf9\u4f01\u4e1a\u51b3\u7b56\u53ef\u80fd\u5177\u6709\u91cd\u8981\u610f\u4e49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e76\u8d2d"]}, {"doi": "10.1017/s0022109025101853", "journal": "JFQA", "title": "Real(istic) Time-Varying Probability of Consumption Disasters", "authors": ["Xiaoyu Huang", "Tao Jin", "Hao Zhou"], "author_details": [{"name": "Xiaoyu Huang", "affiliations": ["Wuhan University of Technology School of Economics"]}, {"name": "Tao Jin", "affiliations": ["Capital University of Economics and Business"]}, {"name": "Hao Zhou", "affiliations": ["Tsinghua University PBC School of Finance, and Southern University of Science and Technology School of Business"]}], "abstract": "Abstract We model the time-varying probability of consumption disasters with international risk interactions and estimate the model using national accounts data of 42 countries back to 1833. The estimated world and country-specific disaster probabilities accord well with historical macroeconomic disasters. A match of the equity premium requires a relative risk aversion coefficient of approximately 5, which is significantly lower than previous estimates. Furthermore, the model provides notably better fits for equity volatility compared with alternative rare-disaster models. Finally, the disaster probability index estimated from the model demonstrates significant out-of-sample predictive power over long horizons, performing well not only over time but also across countries.", "date": "2025-11-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025101853", "title_zh": "\u73b0\u5b9e\u7684\u6d88\u8d39\u707e\u96be\u65f6\u95f4\u53ef\u53d8\u6982\u7387", "abstract_zh": "\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u56fd\u9645\u98ce\u9669\u76f8\u4e92\u4f5c\u7528\u7684\u6d88\u8d39\u707e\u96be\u65f6\u95f4\u53ef\u53d8\u6982\u7387\u6a21\u578b\uff0c\u5e76\u5229\u75281833\u5e74\u4ee5\u676542\u4e2a\u56fd\u5bb6\u7684\u56fd\u6c11\u8d26\u6237\u6570\u636e\u5bf9\u6a21\u578b\u8fdb\u884c\u4f30\u8ba1\u3002\u4f30\u8ba1\u51fa\u7684\u5168\u7403\u53ca\u5404\u56fd\u7279\u5b9a\u7684\u707e\u96be\u6982\u7387\u4e0e\u5386\u53f2\u5b8f\u89c2\u7ecf\u6d4e\u707e\u96be\u60c5\u51b5\u76f8\u543b\u5408\u3002\u8981\u5339\u914d\u80a1\u6743\u6ea2\u4ef7\uff0c\u9700\u8981\u7ea65\u7684\u76f8\u5bf9\u98ce\u9669\u538c\u6076\u7cfb\u6570\uff0c\u8fd9\u4e00\u6570\u503c\u663e\u8457\u4f4e\u4e8e\u4ee5\u5f80\u4f30\u8ba1\u3002\u6b64\u5916\uff0c\u8be5\u6a21\u578b\u5728\u89e3\u91ca\u80a1\u6743\u6ce2\u52a8\u6027\u65b9\u9762\u660e\u663e\u4f18\u4e8e\u5176\u4ed6\u7a00\u6709\u707e\u96be\u6a21\u578b\u3002\u6700\u540e\uff0c\u4ece\u6a21\u578b\u4e2d\u4f30\u8ba1\u51fa\u7684\u707e\u96be\u6982\u7387\u6307\u6570\u5728\u957f\u5468\u671f\u5916\u63a8\u9884\u6d4b\u4e2d\u8868\u73b0\u51fa\u663e\u8457\u7684\u9884\u6d4b\u80fd\u529b\uff0c\u4e0d\u4ec5\u5728\u65f6\u95f4\u7ef4\u5ea6\u4e0a\u8868\u73b0\u826f\u597d\uff0c\u800c\u4e14\u5728\u4e0d\u540c\u56fd\u5bb6\u4e4b\u95f4\u4e5f\u8868\u73b0\u4f18\u5f02\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102433", "journal": "JFQA", "title": "Collateral Damage: Low-Income Borrowers Depend on Income-Based Lending", "authors": ["Mark Garmaise", "Mark Jansen", "Adam Winegar"], "author_details": [{"name": "Mark Garmaise", "affiliations": ["UCLA Anderson School of Management"]}, {"name": "Mark Jansen", "affiliations": ["University of Utah David Eccles School of Business"]}, {"name": "Adam Winegar", "affiliations": ["BI Norwegian Business School \u2013 Oslo Campus (Handelshoyskolen BI \u2013 Campus Oslo)"]}], "abstract": "Abstract We use negative durability shocks from vehicle discontinuations to study asset-backed lending and income-based lending (IBL) in auto finance. Discontinuations lead to increased down payments, higher loan-to-value ratios, and larger post-default personal recoveries. These results all indicate that economically disadvantaged consumers are relatively more reliant on unsecured IBL, in stark contrast to corporate financing patterns. Vehicle recoveries on discontinued cars are lower for borrowers who purchase after discontinuations, implying that depreciation is partially borrower-dependent. Our findings suggest that lower-income borrowers, in particular, benefit from technologies that facilitate IBL, such as income monitoring.", "date": "2025-11-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102433", "title_zh": "collateral damage\uff1a\u4f4e\u6536\u5165\u501f\u6b3e\u4eba\u4f9d\u8d56\u4e8e\u57fa\u4e8e\u6536\u5165\u7684\u8d37\u6b3e", "abstract_zh": "\u6211\u4eec\u5229\u7528\u6c7d\u8f66\u505c\u4ea7\u5e26\u6765\u7684\u8d1f\u8010\u4e45\u6027\u51b2\u51fb\uff0c\u7814\u7a76\u4e86\u6c7d\u8f66\u91d1\u878d\u4e2d\u7684\u8d44\u4ea7\u652f\u6301\u8d37\u6b3e\u548c\u57fa\u4e8e\u6536\u5165\u7684\u8d37\u6b3e\uff08IBL\uff09\u3002\u505c\u4ea7\u5bfc\u81f4\u9996\u4ed8\u589e\u52a0\u3001\u8d37\u6b3e\u4ef7\u503c\u6bd4\u7387\u4e0a\u5347\u4ee5\u53ca\u8fdd\u7ea6\u540e\u4e2a\u4eba\u56de\u6536\u91d1\u989d\u589e\u5927\u3002\u8fd9\u4e9b\u7ed3\u679c\u5747\u8868\u660e\uff0c\u7ecf\u6d4e\u5f31\u52bf\u6d88\u8d39\u8005\u76f8\u5bf9\u66f4\u4f9d\u8d56\u65e0\u62c5\u4fdd\u7684IBL\uff0c\u8fd9\u4e0e\u4f01\u4e1a\u878d\u8d44\u6a21\u5f0f\u5f62\u6210\u9c9c\u660e\u5bf9\u6bd4\u3002\u5728\u505c\u4ea7\u4e4b\u540e\u8d2d\u4e70\u8f66\u8f86\u7684\u501f\u6b3e\u4eba\u7684\u8f66\u8f86\u56de\u6536\u91d1\u989d\u8f83\u4f4e\uff0c\u8bf4\u660e\u6298\u65e7\u5728\u4e00\u5b9a\u7a0b\u5ea6\u4e0a\u5177\u6709\u501f\u6b3e\u4eba\u4f9d\u8d56\u6027\u3002\u6211\u4eec\u7684\u7814\u7a76\u53d1\u73b0\uff0c\u7279\u522b\u662f\u4f4e\u6536\u5165\u501f\u6b3e\u4eba\uff0c\u80fd\u591f\u4ece\u4fc3\u8fdbIBL\u7684\u6280\u672f\uff08\u5982\u6536\u5165\u76d1\u63a7\uff09\u4e2d\u83b7\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025101671", "journal": "JFQA", "title": "Optimal Ownership and Capital Structure with Agency Conflicts", "authors": ["Yunzhi Hu", "Zhaojun Yang", "Nanhui Zhu"], "author_details": [{"name": "Yunzhi Hu", "affiliations": ["University of North Carolina at Chapel Hill Kenan-Flagler Business School"]}, {"name": "Zhaojun Yang", "affiliations": ["Southern University of Science and Technology Department of Finance"]}, {"name": "Nanhui Zhu", "affiliations": ["University of International Business and Economics China School of Banking and Finance Southern University of Science and Technology"]}], "abstract": "Abstract We develop a continuous-time model examining agency conflicts among controlling shareholders (managers), minority shareholders, and creditors in corporate investment decisions. The manager\u2019s private benefits encourage overinvestment, while their equity stake and debt overhang lead to underinvestment. We show these offsetting incentive effects can achieve optimal investment timing under certain conditions. Agency costs exhibit U-shaped relationships with private benefits, tax rates, volatility, managerial ownership, and leverage. The model reveals how the interplay among agency conflicts, tax benefits, and bankruptcy costs shapes optimal ownership and capital structure, explaining several documented empirical patterns in corporate finance.", "date": "2025-11-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025101671", "title_zh": "\u6700\u4f18\u6240\u6709\u6743\u4e0e\u8d44\u672c\u7ed3\u6784\u4e2d\u7684\u4ee3\u7406\u51b2\u7a81", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u8fde\u7eed\u65f6\u95f4\u6a21\u578b\uff0c\u7814\u7a76\u63a7\u80a1\u80a1\u4e1c\uff08\u7ecf\u7406\u4eba\uff09\u3001\u5c11\u6570\u80a1\u4e1c\u548c\u503a\u6743\u4eba\u4e4b\u95f4\u5728\u4f01\u4e1a\u6295\u8d44\u51b3\u7b56\u4e2d\u7684\u4ee3\u7406\u51b2\u7a81\u3002\u7ecf\u7406\u4eba\u7684\u79c1\u4eba\u5229\u76ca\u4f1a\u5f15\u53d1\u8fc7\u5ea6\u6295\u8d44\uff0c\u800c\u5176\u80a1\u6743\u6bd4\u4f8b\u548c\u503a\u52a1\u8fc7\u91cd\u5219\u4f1a\u5bfc\u81f4\u6295\u8d44\u4e0d\u8db3\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5728\u7279\u5b9a\u6761\u4ef6\u4e0b\uff0c\u8fd9\u4e9b\u76f8\u4e92\u62b5\u6d88\u7684\u6fc0\u52b1\u6548\u5e94\u53ef\u4ee5\u5b9e\u73b0\u6700\u4f18\u7684\u6295\u8d44\u65f6\u673a\u3002\u4ee3\u7406\u6210\u672c\u4e0e\u79c1\u4eba\u5229\u76ca\u3001\u7a0e\u7387\u3001\u6ce2\u52a8\u6027\u3001\u7ba1\u7406\u5c42\u6301\u80a1\u6bd4\u4f8b\u548c\u6760\u6746\u4e4b\u95f4\u5448\u73b0\u51faU\u5f62\u5173\u7cfb\u3002\u8be5\u6a21\u578b\u63ed\u793a\u4e86\u4ee3\u7406\u51b2\u7a81\u3001\u7a0e\u6536\u4f18\u60e0\u548c\u7834\u4ea7\u6210\u672c\u4e4b\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\u5982\u4f55\u5f71\u54cd\u6700\u4f18\u7684\u6240\u6709\u6743\u7ed3\u6784\u548c\u8d44\u672c\u7ed3\u6784\uff0c\u4ece\u800c\u89e3\u91ca\u4e86\u4f01\u4e1a\u91d1\u878d\u9886\u57df\u4e2d\u591a\u4e2a\u5df2\u8bb0\u5f55\u7684\u5b9e\u8bc1\u73b0\u8c61\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102366", "journal": "JFQA", "title": "The Entrepreneurial Finance of Fintech Firms and the Effect of Investments in Fintech Startups on the Performance of Corporate Investors", "authors": ["Thomas J. Chemmanur", "Michael B. Imerman", "Harshit Rajaiya", "Qianqian Yu"], "author_details": [{"name": "Thomas J. Chemmanur", "affiliations": ["Boston College Carroll School of Management"]}, {"name": "Michael B. Imerman", "affiliations": ["University of California at Irvine Paul Merage School of Business"]}, {"name": "Harshit Rajaiya", "affiliations": ["University of Ottawa Telfer School of Management"]}, {"name": "Qianqian Yu", "affiliations": ["Lehigh University College of Business"]}], "abstract": "Abstract We analyze how corporate direct investments in fintech startups affect startup performance and that of investing firms. Corporate investment in fintech startups is associated with a greater likelihood of successful exit, more and higher-quality innovation, and a greater inflow of high-quality inventors. A stacked difference-in-differences analysis shows that direct investments enhance the operating performance and equity-market valuation of corporate investors in the financial services sector, but not those in the nonfinancial sector. We establish two channels that drive fintech startups\u2019 performance improvements: strategic alliance formation between investors and startups, and enhanced startup monitoring by corporate investors.", "date": "2025-11-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102366", "title_zh": "\u91d1\u878d\u79d1\u6280\u4f01\u4e1a\u7684\u521b\u4e1a\u878d\u8d44\u53ca\u5176\u5bf9\u6bcd\u516c\u53f8\u6295\u8d44\u8005\u7ee9\u6548\u7684\u5f71\u54cd", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5206\u6790\u4e86\u4f01\u4e1a\u76f4\u63a5\u6295\u8d44\u4e8e\u91d1\u878d\u79d1\u6280\u521d\u521b\u4f01\u4e1a\u5982\u4f55\u5f71\u54cd\u521d\u521b\u4f01\u4e1a\u7684\u8868\u73b0\u4ee5\u53ca\u6295\u8d44\u4f01\u4e1a\u7684\u8868\u73b0\u3002\u4f01\u4e1a\u5bf9\u91d1\u878d\u79d1\u6280\u521d\u521b\u4f01\u4e1a\u7684\u6295\u8d44\u4e0e\u66f4\u9ad8\u7684\u6210\u529f\u9000\u51fa\u6982\u7387\u3001\u66f4\u591a\u4e14\u8d28\u91cf\u66f4\u9ad8\u7684\u521b\u65b0\uff0c\u4ee5\u53ca\u66f4\u9ad8\u8d28\u91cf\u7684\u53d1\u660e\u8005\u6d41\u5165\u76f8\u5173\u8054\u3002\u901a\u8fc7\u5206\u5c42\u53cc\u91cd\u5dee\u5206\u5206\u6790\u53d1\u73b0\uff0c\u76f4\u63a5\u6295\u8d44\u63d0\u5347\u4e86\u91d1\u878d\u670d\u52a1\u884c\u4e1a\u6295\u8d44\u8005\u7684\u8fd0\u8425\u7ee9\u6548\u548c\u80a1\u6743\u5e02\u573a\u4f30\u503c\uff0c\u4f46\u5bf9\u975e\u91d1\u878d\u884c\u4e1a\u6295\u8d44\u8005\u5e76\u65e0\u6b64\u5f71\u54cd\u3002\u6211\u4eec\u786e\u7acb\u4e86\u4e24\u4e2a\u63a8\u52a8\u91d1\u878d\u79d1\u6280\u521d\u521b\u4f01\u4e1a\u8868\u73b0\u63d0\u5347\u7684\u6e20\u9053\uff1a\u6295\u8d44\u8005\u4e0e\u521d\u521b\u4f01\u4e1a\u4e4b\u95f4\u7684\u6218\u7565\u8054\u76df\u5f62\u6210\uff0c\u4ee5\u53ca\u4f01\u4e1a\u6295\u8d44\u8005\u5bf9\u521d\u521b\u4f01\u4e1a\u7684\u76d1\u7763\u80fd\u529b\u589e\u5f3a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102421", "journal": "JFQA", "title": "Consistent Backtesting Systemic Risk Measures", "authors": ["Soon Heng Leong"], "author_details": [{"name": "Soon Heng Leong", "affiliations": ["ESCP Business School"]}], "abstract": "Abstract This article offers two novel backtests to evaluate the adequacy of well-known systemic risk measures such as CoVaR, MES, SES, and SRISK. Both the new backtests are robust to estimation risk (i.e., their null distributions remain invariant in the presence of estimation risk). While existing backtest is consistent against divergence from the null hypothesis up to a finite order, the article shows that the new backtests are fully consistent. The real-world implications brought by the new backtests are economically significant as they reveal significantly more cases of inadequate systemic risk modeling among the major financial institutions.", "date": "2025-11-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102421", "title_zh": "\u4e00\u81f4\u7684\u56de\u6d4b\u7cfb\u7edf\u6027\u98ce\u9669\u5ea6\u91cf", "abstract_zh": "\u672c\u6587\u63d0\u51fa\u4e86\u4e24\u79cd\u65b0\u7684\u56de\u6d4b\u65b9\u6cd5\uff0c\u7528\u4e8e\u8bc4\u4f30\u5df2\u77e5\u7684\u7cfb\u7edf\u6027\u98ce\u9669\u5ea6\u91cf\uff08\u5982CoVaR\u3001MES\u3001SES\u548cSRISK\uff09\u7684\u5145\u5206\u6027\u3002\u8fd9\u4e24\u79cd\u65b0\u56de\u6d4b\u65b9\u6cd5\u5bf9\u4f30\u8ba1\u98ce\u9669\u5177\u6709\u9c81\u68d2\u6027\uff08\u5373\u5728\u5b58\u5728\u4f30\u8ba1\u98ce\u9669\u7684\u60c5\u51b5\u4e0b\uff0c\u5176\u96f6\u5206\u5e03\u4fdd\u6301\u4e0d\u53d8\uff09\u3002\u867d\u7136\u73b0\u6709\u56de\u6d4b\u65b9\u6cd5\u5728\u6709\u9650\u9636\u4e0a\u80fd\u591f\u4e00\u81f4\u5730\u68c0\u6d4b\u5230\u4e0e\u96f6\u5047\u8bbe\u7684\u504f\u79bb\uff0c\u672c\u6587\u8bc1\u660e\u65b0\u56de\u6d4b\u65b9\u6cd5\u662f\u5b8c\u5168\u4e00\u81f4\u7684\u3002\u65b0\u56de\u6d4b\u65b9\u6cd5\u5e26\u6765\u7684\u73b0\u5b9e\u610f\u4e49\u91cd\u5927\uff0c\u56e0\u4e3a\u5b83\u4eec\u63ed\u793a\u4e86\u4e3b\u8981\u91d1\u878d\u673a\u6784\u4e2d\u7cfb\u7edf\u6027\u98ce\u9669\u5efa\u6a21\u5b58\u5728\u663e\u8457\u4e0d\u8db3\u7684\u6848\u4f8b\u6570\u91cf\u66f4\u591a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1017/s0022109025102408", "journal": "JFQA", "title": "Capital Allocation and the Market for Mutual Funds: Inspecting the Mechanism", "authors": ["Jules H. van Binsbergen", "Jeong Ho (John) Kim", "Soohun Kim"], "author_details": [{"name": "Jules H. van Binsbergen", "affiliations": ["University of Pennsylvania Wharton School"]}, {"name": "Jeong Ho (John) Kim", "affiliations": ["Florida State University College of Business"]}, {"name": "Soohun Kim", "affiliations": ["KAIST College of Business"]}], "abstract": "Abstract We exploit heterogeneity in decreasing returns to scale (DRS) parameters across mutual funds to analyze the importance of scalability for investors\u2019 capital allocation decisions. We find strong evidence that steeper DRS attenuate flow sensitivity to performance. We calibrate a rational model of active fund management and show that a large fraction of cross-sectional variation in assets-under-management is due to investors anticipating the effects of scale on return performance. We conclude that DRS play a key role in achieving equilibrium in the intermediated investment management market.", "date": "2025-11-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102408", "title_zh": "\u8d44\u672c\u914d\u7f6e\u4e0e\u5171\u540c\u57fa\u91d1\u5e02\u573a\uff1a\u68c0\u9a8c\u5176\u673a\u5236", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u7528\u5171\u540c\u57fa\u91d1\u4e4b\u95f4\u89c4\u6a21\u62a5\u916c\u9012\u51cf\uff08DRS\uff09\u53c2\u6570\u7684\u5f02\u8d28\u6027\uff0c\u5206\u6790\u53ef\u6269\u5c55\u6027\u5bf9\u6295\u8d44\u8005\u8d44\u672c\u914d\u7f6e\u51b3\u7b56\u7684\u91cd\u8981\u6027\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u66f4\u9661\u7684\u89c4\u6a21\u62a5\u916c\u9012\u51cf\u4f1a\u51cf\u5f31\u8d44\u91d1\u6d41\u52a8\u5bf9\u4e1a\u7ee9\u7684\u654f\u611f\u6027\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u7406\u6027\u4e3b\u52a8\u57fa\u91d1\u7ba1\u7406\u6a21\u578b\uff0c\u5e76\u8868\u660e\uff0c\u8d44\u4ea7\u7ba1\u7406\u89c4\u6a21\u7684\u8de8\u622a\u9762\u5dee\u5f02\u4e2d\uff0c\u5f88\u5927\u4e00\u90e8\u5206\u6e90\u4e8e\u6295\u8d44\u8005\u9884\u671f\u89c4\u6a21\u5bf9\u56de\u62a5\u8868\u73b0\u7684\u5f71\u54cd\u3002\u6211\u4eec\u5f97\u51fa\u7ed3\u8bba\uff1a\u89c4\u6a21\u62a5\u916c\u9012\u51cf\u5728\u4e2d\u4ecb\u6295\u8d44\u7ba1\u7406\u5e02\u573a\u8fbe\u5230\u5747\u8861\u4e2d\u53d1\u6325\u5173\u952e\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1017/s002210902510238x", "journal": "JFQA", "title": "Decoding Momentum Spillover Effects", "authors": ["Huaixin Wang"], "author_details": [{"name": "Huaixin Wang", "affiliations": ["University of Macau, Faculty of Business Administration"]}], "abstract": "Abstract This article studies the making of return predictability among economically linked firms. I characterize an asymmetric cross-firm tug-of-war: i) High peer overnight returns are followed by elevated overnight returns for focal stocks, which fully reverse during intraday, and ii) high peer intraday returns are followed by high intraday returns but minor overnight price reactions. This pattern aligns with the story that individuals\u2019 persistent trading on salient information distorts opening prices, while slow-moving arbitrage by professional investors gradually corrects mispricing. Mutual fund and hedge fund flows exhibit distinct associations with the tug-of-war, supporting the hypothesis that heterogeneous demand drives the return predictability.", "date": "2025-11-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s002210902510238x", "title_zh": "\u89e3\u7801\u52a8\u91cf\u6ea2\u51fa\u6548\u5e94", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u7ecf\u6d4e\u4e0a\u76f8\u4e92\u5173\u8054\u4f01\u4e1a\u4e4b\u95f4\u6536\u76ca\u53ef\u9884\u6d4b\u6027\u7684\u5f62\u6210\u673a\u5236\u3002\u6211\u523b\u753b\u4e86\u4e00\u79cd\u4e0d\u5bf9\u79f0\u7684\u8de8\u4f01\u4e1a\u62c9\u952f\u73b0\u8c61\uff1a\u4e00\u662f\u9ad8\u540c\u884c\u5f53\u65e5\u5f00\u76d8\u540e\u7684\u6536\u76ca\u4f1a\u5f15\u53d1\u76ee\u6807\u80a1\u7968\u5f53\u65e5\u5f00\u76d8\u540e\u7684\u6536\u76ca\u4e0a\u5347\uff0c\u4f46\u5728\u65e5\u5185\u4ea4\u6613\u8fc7\u7a0b\u4e2d\u8be5\u6548\u5e94\u5b8c\u5168\u53cd\u8f6c\uff1b\u4e8c\u662f\u540c\u884c\u65e5\u5185\u6536\u76ca\u8f83\u9ad8\u65f6\uff0c\u76ee\u6807\u80a1\u7968\u7684\u65e5\u5185\u6536\u76ca\u4e5f\u4f1a\u5347\u9ad8\uff0c\u4f46\u5bf9\u5f53\u65e5\u5f00\u76d8\u4ef7\u7684\u53cd\u5e94\u8f83\u5c0f\u3002\u8fd9\u4e00\u73b0\u8c61\u4e0e\u4e2a\u4f53\u6301\u7eed\u57fa\u4e8e\u663e\u8457\u4fe1\u606f\u8fdb\u884c\u4ea4\u6613\u5bfc\u81f4\u5f00\u76d8\u4ef7\u5931\u771f\uff0c\u800c\u4e13\u4e1a\u6295\u8d44\u8005\u7f13\u6162\u8fdb\u884c\u5957\u5229\u4ece\u800c\u9010\u6b65\u7ea0\u6b63\u8bef\u5b9a\u4ef7\u7684\u89e3\u91ca\u76f8\u543b\u5408\u3002\u5171\u540c\u57fa\u91d1\u548c\u5bf9\u51b2\u57fa\u91d1\u7684\u6d41\u52a8\u8868\u73b0\u51fa\u4e0e\u62c9\u952f\u73b0\u8c61\u4e0d\u540c\u7684\u5173\u8054\u6027\uff0c\u652f\u6301\u4e86\u5f02\u8d28\u6027\u9700\u6c42\u9a71\u52a8\u6536\u76ca\u53ef\u9884\u6d4b\u6027\u7684\u5047\u8bbe\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005", "\u8d44\u672c\u6d41\u52a8"]}, {"doi": "10.1017/s0022109025102378", "journal": "JFQA", "title": "ETF Sampling and Index Arbitrage", "authors": ["Jonathan Brogaard", "Davidson Heath", "Da Huang"], "author_details": [{"name": "Jonathan Brogaard", "affiliations": ["University of Utah David Eccles School of Business"]}, {"name": "Davidson Heath", "affiliations": ["University of Utah David Eccles School of Business"]}, {"name": "Da Huang", "affiliations": ["Northeastern University D\u2019Amore-McKim School of Business"]}], "abstract": "Abstract This article shows that exchange-traded funds (ETFs) \u201csample\u201d their indexes, systematically underweighting or omitting illiquid index stocks. As a result, arbitrage activity between the ETF and its index has heterogeneous effects on underlying asset markets. Using an instrumental variables approach, we find that the trading activity of ETFs reduces liquidity and price efficiency and increases volatility and co-movement for liquid stocks but has no effect on illiquid stocks. Our results demonstrate that the effects of passive investing on asset markets depend on how passive funds replicate their target index.", "date": "2025-11-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102378", "title_zh": "ETF\u62bd\u6837\u4e0e\u6307\u6570\u5957\u5229", "abstract_zh": "\u672c\u6587\u8868\u660e\uff0c\u4ea4\u6613\u6240\u4ea4\u6613\u57fa\u91d1\uff08ETF\uff09\u4f1a\u7cfb\u7edf\u6027\u5730\u4f4e\u4f30\u6216\u9057\u6f0f\u975e\u6d41\u52a8\u6027\u6307\u6570\u80a1\u7968\uff0c\u5373\u8fdb\u884c\u2018\u62bd\u6837\u2019\u3002\u56e0\u6b64\uff0cETF\u4e0e\u5176\u6307\u6570\u4e4b\u95f4\u7684\u5957\u5229\u6d3b\u52a8\u5bf9\u57fa\u7840\u8d44\u4ea7\u5e02\u573a\u5177\u6709\u5f02\u8d28\u6027\u5f71\u54cd\u3002\u91c7\u7528\u5de5\u5177\u53d8\u91cf\u6cd5\uff0c\u6211\u4eec\u53d1\u73b0ETF\u7684\u4ea4\u6613\u6d3b\u52a8\u4f1a\u964d\u4f4e\u6d41\u52a8\u6027\u53ca\u4ef7\u683c\u6548\u7387\uff0c\u589e\u52a0\u6d41\u52a8\u6027\u80a1\u7968\u7684\u6ce2\u52a8\u6027\u548c\u8054\u52a8\u6027\uff0c\u4f46\u5bf9\u975e\u6d41\u52a8\u6027\u80a1\u7968\u5219\u65e0\u5f71\u54cd\u3002\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u88ab\u52a8\u6295\u8d44\u5bf9\u8d44\u4ea7\u5e02\u573a\u7684\u5f71\u54cd\u53d6\u51b3\u4e8e\u88ab\u52a8\u57fa\u91d1\u5982\u4f55\u590d\u5236\u5176\u76ee\u6807\u6307\u6570\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1017/s0022109025101877", "journal": "JFQA", "title": "Competition and Debt Conservatism", "authors": ["Seth Armitage", "Woon Sau Leung"], "author_details": [{"name": "Seth Armitage", "affiliations": ["University of Edinburgh Business School"]}, {"name": "Woon Sau Leung", "affiliations": ["University of Southampton Business School"]}], "abstract": "Abstract Exploiting changes in countries\u2019 competition laws, we find that competition increases firms\u2019 propensity to use zero leverage (ZL). We test the financial-flexibility, financial-constraint, and quiet-life explanations for this result, concluding that desire for flexibility is the one most likely. The relation between competition and ZL strengthens with cash-flow volatility, which supports the flexibility motive. Adoption of ZL by firms is accompanied by increases in payouts, so it is unlikely that ZL adopters are constrained. Proxies for governance have no effect on the relation between competition and ZL, suggesting that desire for a quiet life is not the explanation either.", "date": "2025-11-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025101877", "title_zh": "\u7ade\u4e89\u4e0e\u503a\u52a1\u4fdd\u5b88\u4e3b\u4e49", "abstract_zh": "\u6458\u8981 \u5229\u7528\u5404\u56fd\u7ade\u4e89\u6cd5\u89c4\u53d8\u5316\u7684\u5951\u673a\uff0c\u6211\u4eec\u53d1\u73b0\u7ade\u4e89\u7a0b\u5ea6\u7684\u63d0\u9ad8\u4f1a\u589e\u5f3a\u4f01\u4e1a\u91c7\u7528\u96f6\u6760\u6746\uff08ZL\uff09\u7684\u503e\u5411\u3002\u6211\u4eec\u68c0\u9a8c\u4e86\u91d1\u878d\u7075\u6d3b\u6027\u3001\u91d1\u878d\u7ea6\u675f\u4ee5\u53ca\u5b89\u9759\u751f\u6d3b\u7b49\u89e3\u91ca\uff0c\u8ba4\u4e3a\u5bf9\u7075\u6d3b\u6027\u7684\u9700\u6c42\u662f\u6700\u6709\u53ef\u80fd\u7684\u3002\u7ade\u4e89\u4e0eZL\u4e4b\u95f4\u7684\u5173\u7cfb\u5728\u73b0\u91d1\u6d41\u6ce2\u52a8\u6027\u589e\u5f3a\u65f6\u66f4\u52a0\u663e\u8457\uff0c\u8fd9\u652f\u6301\u4e86\u7075\u6d3b\u6027\u52a8\u673a\u3002\u4f01\u4e1a\u91c7\u7528ZL\u7684\u540c\u65f6\u4f34\u968f\u7740\u80a1\u5229\u652f\u4ed8\u7684\u589e\u52a0\uff0c\u56e0\u6b64ZL\u91c7\u7528\u8005\u5e76\u4e0d\u5904\u4e8e\u7ea6\u675f\u72b6\u6001\u3002\u6cbb\u7406\u7ed3\u6784\u7684\u4ee3\u7406\u53d8\u91cf\u5bf9\u7ade\u4e89\u4e0eZL\u4e4b\u95f4\u7684\u5173\u7cfb\u6ca1\u6709\u5f71\u54cd\uff0c\u8868\u660e\u201c\u5b89\u9759\u751f\u6d3b\u201d\u5e76\u975e\u89e3\u91ca\u539f\u56e0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf051", "journal": "QJE", "title": "Republican Support and Economic Hardship: The Enduring Effects of the Opioid Epidemic", "authors": ["Carolina Arteaga", "Victoria Barone"], "author_details": [{"name": "Carolina Arteaga", "affiliations": ["University of Toronto and National Bureau of Economic Research ,"]}, {"name": "Victoria Barone", "affiliations": ["University of Notre Dame ,"]}], "abstract": "Abstract In this article, we establish a causal connection between two of the most salient social developments in the United States over the past decades: the opioid epidemic and the political realignment between the Republican and Democratic parties. Drawing on unsealed records from litigation against Purdue Pharma, we uncover rich geographic variation in the marketing of prescription opioids that serves as a quasi-exogenous source of exposure to the epidemic. We use this variation to document significant increases in drug-related mortality and greater reliance on public transfer programs. This induced economic hardship led to substantial changes in the political landscape of the communities most affected by the opioid epidemic. We estimate that from the mid-2000s to 2022, exposure to the opioid epidemic continuously increased the Republican vote share in House, presidential, and gubernatorial elections. By the 2022 House elections, a one-standard-deviation increase in our measure of exposure led to a 4.5 percentage point increase in the Republican vote share. From 2012 until 2022, this increase in the House vote share translated into Republicans winning additional seats.", "date": "2025-11-04", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf051", "title_zh": "\u5171\u548c\u515a\u652f\u6301\u4e0e\u7ecf\u6d4e\u56f0\u5883\uff1a\u963f\u7247\u7c7b\u836f\u7269\u5371\u673a\u7684\u6301\u4e45\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u5efa\u7acb\u4e86\u8fc7\u53bb\u51e0\u5341\u5e74\u4e2d\u7f8e\u56fd\u6700\u5177\u4ee3\u8868\u6027\u7684\u4e24\u9879\u793e\u4f1a\u53d8\u8fc1\u4e4b\u95f4\u7684\u56e0\u679c\u5173\u7cfb\uff1a\u963f\u7247\u7c7b\u836f\u7269\u5371\u673a\u4e0e\u5171\u548c\u515a\u4e0e\u6c11\u4e3b\u515a\u4e4b\u95f4\u7684\u653f\u6cbb\u91cd\u7ec4\u3002\u6211\u4eec\u57fa\u4e8e\u5bf9\u666e\u9c81\u5fb7\u5236\u836f\u8bc9\u8bbc\u6848\u7684\u672a\u5c01\u5b58\u8bb0\u5f55\uff0c\u53d1\u73b0\u4e86\u5904\u65b9\u963f\u7247\u7c7b\u836f\u7269\u8425\u9500\u5728\u5730\u7406\u4e0a\u7684\u663e\u8457\u5dee\u5f02\uff0c\u8fd9\u4e00\u5dee\u5f02\u6784\u6210\u4e86\u5bf9\u963f\u7247\u7c7b\u836f\u7269\u5371\u673a\u66b4\u9732\u7684\u51c6\u5916\u751f\u6765\u6e90\u3002\u6211\u4eec\u5229\u7528\u8fd9\u4e00\u5dee\u5f02\uff0c\u8bc1\u5b9e\u4e86\u836f\u7269\u76f8\u5173\u6b7b\u4ea1\u7387\u663e\u8457\u4e0a\u5347\u4ee5\u53ca\u5bf9\u516c\u5171\u8f6c\u79fb\u8ba1\u5212\u4f9d\u8d56\u7a0b\u5ea6\u589e\u52a0\u7684\u73b0\u8c61\u3002\u8fd9\u79cd\u7531\u6b64\u5f15\u53d1\u7684\u7ecf\u6d4e\u56f0\u5883\u5bfc\u81f4\u4e86\u53d7\u963f\u7247\u7c7b\u836f\u7269\u5371\u673a\u5f71\u54cd\u6700\u4e25\u91cd\u7684\u793e\u533a\u653f\u6cbb\u683c\u5c40\u53d1\u751f\u91cd\u5927\u53d8\u5316\u3002\u6211\u4eec\u4f30\u8ba1\uff0c\u4ece2000\u5e74\u4ee3\u4e2d\u671f\u52302022\u5e74\uff0c\u5bf9\u963f\u7247\u7c7b\u836f\u7269\u5371\u673a\u7684\u66b4\u9732\u6301\u7eed\u589e\u52a0\u4e86\u9009\u6c11\u5bf9\u5171\u548c\u515a\u7684\u652f\u6301\u7387\uff0c\u57282022\u5e74\u4f17\u8bae\u9662\u9009\u4e3e\u4e2d\uff0c\u6211\u4eec\u7684\u66b4\u9732\u7a0b\u5ea6\u6bcf\u589e\u52a0\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u5171\u548c\u515a\u9009\u7968\u4efd\u989d\u5c31\u4e0a\u53474.5\u4e2a\u767e\u5206\u70b9\u3002\u4ece2012\u5e74\u52302022\u5e74\uff0c\u8fd9\u4e00\u4f17\u8bae\u9662\u9009\u7968\u4efd\u989d\u7684\u589e\u52a0\u8f6c\u5316\u4e3a\u5171\u548c\u515a\u8d62\u5f97\u66f4\u591a\u8bae\u5e2d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf052", "journal": "QJE", "title": "Permanent Capital Losses after Banking Crises", "authors": ["Matthew Baron", "Luc Laeven", "Julien P\u00e9nasse", "Yevhenii Usenko"], "author_details": [{"name": "Matthew Baron", "affiliations": ["McDonough School of Business, Georgetown University ,"]}, {"name": "Luc Laeven", "affiliations": ["European Central Bank, Germany; Tilburg University, Netherlands; and Centre for Economic Policy and Research ,"]}, {"name": "Julien P\u00e9nasse", "affiliations": ["University of Luxembourg ,"]}, {"name": "Yevhenii Usenko", "affiliations": ["MIT Sloan School of Management ,"]}], "abstract": "Abstract We study the mechanisms driving bank losses across historical banking crises in 46 economies and the effectiveness of policy interventions in restoring bank capitalization. We find that bank stocks experience large, permanent declines at the onset of crises. These losses predict commensurate long-term declines in banks\u2019 earnings and dividends, rather than elevated future equity returns. Bank losses are primarily driven by write-downs of nonperforming assets, not asset sales during panics. Forceful liquidity-based interventions during crises predict only small, temporary increases in bank market value. Overall, these results suggest that bank losses during crises are not primarily due to temporary price dislocations. Early liquidity interventions can avert banking crises, but only under specific conditions. Once large bank equity declines have occurred, policy responses have historically failed to prevent persistent undercapitalization in the banking sector.", "date": "2025-11-04", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf052", "title_zh": "\u94f6\u884c\u5371\u673a\u540e\u7684\u6c38\u4e45\u8d44\u672c\u635f\u5931", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u5386\u53f2\u94f6\u884c\u5371\u673a\u4e2d46\u4e2a\u7ecf\u6d4e\u4f53\u94f6\u884c\u635f\u5931\u7684\u9a71\u52a8\u673a\u5236\uff0c\u4ee5\u53ca\u653f\u7b56\u5e72\u9884\u5728\u6062\u590d\u94f6\u884c\u8d44\u672c\u5316\u65b9\u9762\u7684\u6709\u6548\u6027\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u94f6\u884c\u80a1\u4ef7\u5728\u5371\u673a\u521d\u671f\u51fa\u73b0\u5927\u5e45\u4e14\u6301\u4e45\u7684\u4e0b\u8dcc\u3002\u8fd9\u4e9b\u635f\u5931\u9884\u793a\u7740\u94f6\u884c\u672a\u6765\u76c8\u5229\u548c\u80a1\u606f\u7684\u957f\u671f\u4e0b\u964d\uff0c\u800c\u975e\u672a\u6765\u80a1\u6743\u56de\u62a5\u7684\u63d0\u5347\u3002\u94f6\u884c\u635f\u5931\u4e3b\u8981\u6e90\u4e8e\u5bf9\u4e0d\u826f\u8d44\u4ea7\u7684\u8ba1\u63d0\uff0c\u800c\u975e\u5371\u673a\u671f\u95f4\u7684\u8d44\u4ea7\u51fa\u552e\u3002\u5728\u5371\u673a\u4e2d\u5b9e\u65bd\u5f3a\u5236\u6027\u7684\u6d41\u52a8\u6027\u5e72\u9884\u4ec5\u80fd\u5e26\u6765\u5fae\u5c0f\u4e14\u77ed\u6682\u7684\u94f6\u884c\u5e02\u573a\u4ef7\u503c\u63d0\u5347\u3002\u603b\u4f53\u800c\u8a00\uff0c\u8fd9\u4e9b\u7ed3\u679c\u8868\u660e\u94f6\u884c\u5728\u5371\u673a\u4e2d\u7684\u635f\u5931\u5e76\u975e\u4e3b\u8981\u7531\u77ed\u671f\u4ef7\u683c\u6ce2\u52a8\u5f15\u8d77\u3002\u65e9\u671f\u7684\u6d41\u52a8\u6027\u5e72\u9884\u53ef\u4ee5\u5728\u7279\u5b9a\u6761\u4ef6\u4e0b\u907f\u514d\u94f6\u884c\u5371\u673a\u7684\u53d1\u751f\u3002\u7136\u800c\uff0c\u4e00\u65e6\u5927\u578b\u94f6\u884c\u80a1\u6743\u4ef7\u503c\u5927\u5e45\u4e0b\u8dcc\uff0c\u5386\u53f2\u4e0a\u653f\u7b56\u5e94\u5bf9\u63aa\u65bd\u5f80\u5f80\u672a\u80fd\u963b\u6b62\u94f6\u884c\u4e1a\u957f\u671f\u7684\u8d44\u672c\u4e0d\u8db3\u95ee\u9898\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1017/s0022109025102226", "journal": "JFQA", "title": "Climate-Triggered Institutional Price Pressure: Does It Affect Firms\u2019 Cost of Equity?", "authors": ["George Skiadopoulos", "Cheng Xue"], "author_details": [{"name": "George Skiadopoulos", "affiliations": ["University of Piraeus, Department of Banking and Financial Management Queen Mary University of London, School of Economics and Finance"]}, {"name": "Cheng Xue", "affiliations": ["Nanjing Agricultural University, College of Finance"]}], "abstract": "Abstract We document that climate-triggered institutional portfolio rebalancing affects S&P 500 firms\u2019 cost of equity through climate change price pressure (CCPP). Using a demand-based asset pricing framework, we estimate firm-level CCPP from physical and transition exposures over 2005\u20132021. A one-standard-deviation intensification of CCPP raises the cost of equity by up to 6% of its average, with banks and insurers as the main drivers. Yet firms do not subsequently improve environmental performance, indicating that the statistically significant effect of CCPP on cost of equity is ineffective to alter corporate behavior. Our CCPP metrics can help policymakers and investors design targeted environmental strategies.", "date": "2025-11-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102226", "title_zh": "\u6c14\u5019\u5f15\u53d1\u7684\u673a\u6784\u6295\u8d44\u7ec4\u5408\u518d\u5e73\u8861\u662f\u5426\u5f71\u54cd\u4f01\u4e1a\u7684\u80a1\u6743\u6210\u672c\uff1f", "abstract_zh": "\u6211\u4eec\u53d1\u73b0\uff0c\u7531\u6c14\u5019\u53d8\u5316\u5f15\u53d1\u7684\u673a\u6784\u6295\u8d44\u7ec4\u5408\u518d\u5e73\u8861\u901a\u8fc7\u6c14\u5019\u53d8\u5316\u4ef7\u683c\u538b\u529b\uff08CCPP\uff09\u5f71\u54cd\u6807\u666e500\u516c\u53f8\u80a1\u6743\u6210\u672c\u3002\u57fa\u4e8e\u9700\u6c42\u5bfc\u5411\u7684\u8d44\u4ea7\u5b9a\u4ef7\u6846\u67b6\uff0c\u6211\u4eec\u4ece2005\u5e74\u81f32021\u5e74\u671f\u95f4\u4f30\u8ba1\u4e86\u4f01\u4e1a\u5c42\u9762\u7684CCPP\uff0c\u6db5\u76d6\u7269\u7406\u548c\u8f6c\u578b\u66b4\u9732\u3002CCPP\u5f3a\u5ea6\u589e\u52a0\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u4f1a\u4f7f\u80a1\u6743\u6210\u672c\u4e0a\u5347\u81f3\u5176\u5e73\u5747\u6c34\u5e73\u76846%\uff0c\u5176\u4e2d\u94f6\u884c\u548c\u4fdd\u9669\u516c\u53f8\u662f\u4e3b\u8981\u9a71\u52a8\u56e0\u7d20\u3002\u7136\u800c\uff0c\u4f01\u4e1a\u5e76\u672a\u56e0\u6b64\u6539\u5584\u5176\u73af\u5883\u8868\u73b0\uff0c\u8868\u660eCCPP\u5bf9\u80a1\u6743\u6210\u672c\u7684\u663e\u8457\u5f71\u54cd\u5728\u6539\u53d8\u4f01\u4e1a\u884c\u4e3a\u65b9\u9762\u662f\u65e0\u6548\u7684\u3002\u6211\u4eec\u7684CCPP\u6307\u6807\u53ef\u5e2e\u52a9\u653f\u7b56\u5236\u5b9a\u8005\u548c\u6295\u8d44\u8005\u8bbe\u8ba1\u6709\u9488\u5bf9\u6027\u7684\u73af\u5883\u7b56\u7565\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.1017/s0022109025102330", "journal": "JFQA", "title": "Transmission of Information from Private to Public Markets", "authors": ["Shrijata Chattopadhyay", "John J. McConnell", "Timothy E. Trombley", "Mehmet Deniz Yavuz"], "author_details": [{"name": "Shrijata Chattopadhyay", "affiliations": ["Binghamton University School of Management"]}, {"name": "John J. McConnell", "affiliations": ["Purdue University Daniels School of Business"]}, {"name": "Timothy E. Trombley", "affiliations": ["Illinois State University College of Business"]}, {"name": "Mehmet Deniz Yavuz", "affiliations": ["Purdue University Daniels School of Business"]}], "abstract": "Abstract We report evidence consistent with institutional investors using industry-level information that they obtain from their investments in venture capital (VC) funds to earn excess returns in publicly traded stocks. We use court rulings regarding the Freedom of Information Act as an exogenous shock affecting the information flow between VC funds and institutional investors to show that the excess returns are explained by information received via this channel. Thus, institutional investors serve as conduits of information from private to public markets. In the process, institutional investors earn higher returns from their VC investments than implied by the cash flows received therefrom.", "date": "2025-11-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102330", "title_zh": "\u79c1\u4eba\u5e02\u573a\u5411\u516c\u5f00\u5e02\u573a\u4fe1\u606f\u4f20\u9012", "abstract_zh": "\u6211\u4eec\u62a5\u544a\u4e86\u8bc1\u636e\uff0c\u8868\u660e\u673a\u6784\u6295\u8d44\u8005\u5229\u7528\u4ed6\u4eec\u5728\u98ce\u9669\u6295\u8d44\uff08VC\uff09\u57fa\u91d1\u4e2d\u7684\u6295\u8d44\u6240\u83b7\u5f97\u7684\u884c\u4e1a\u7ea7\u4fe1\u606f\uff0c\u5728\u516c\u5f00\u4ea4\u6613\u80a1\u7968\u4e2d\u83b7\u5f97\u8d85\u989d\u6536\u76ca\u3002\u6211\u4eec\u5229\u7528\u5173\u4e8e\u300a\u4fe1\u606f\u81ea\u7531\u6cd5\u300b\u7684\u6cd5\u9662\u5224\u51b3\u4f5c\u4e3a\u5f71\u54cdVC\u57fa\u91d1\u4e0e\u673a\u6784\u6295\u8d44\u8005\u4e4b\u95f4\u4fe1\u606f\u6d41\u52a8\u7684\u5916\u751f\u51b2\u51fb\uff0c\u8868\u660e\u8fd9\u4e9b\u8d85\u989d\u6536\u76ca\u662f\u7531\u901a\u8fc7\u8be5\u6e20\u9053\u83b7\u5f97\u7684\u4fe1\u606f\u6240\u89e3\u91ca\u7684\u3002\u56e0\u6b64\uff0c\u673a\u6784\u6295\u8d44\u8005\u5145\u5f53\u4e86\u79c1\u4eba\u5e02\u573a\u5411\u516c\u5f00\u5e02\u573a\u4f20\u9012\u4fe1\u606f\u7684\u6e20\u9053\u3002\u5728\u6b64\u8fc7\u7a0b\u4e2d\uff0c\u673a\u6784\u6295\u8d44\u8005\u4ece\u5176VC\u6295\u8d44\u4e2d\u83b7\u5f97\u7684\u56de\u62a5\u9ad8\u4e8e\u5176\u73b0\u91d1\u6d41\u6240\u6697\u793a\u7684\u6c34\u5e73\u3002", "translation_source": "journal-qwen4b", "topics": ["\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1017/s0022109025102299", "journal": "JFQA", "title": "Market Feedback Effect on CEO Pay: Evidence from Peers\u2019 Say-on-Pay Voting Failures", "authors": ["C.S. Agnes Cheng", "Iftekhar Hasan", "Feng Tang", "Jing Xie"], "author_details": [{"name": "C.S. Agnes Cheng", "affiliations": ["The University of Oklahoma Price College of Business Steed School of Accounting"]}, {"name": "Iftekhar Hasan", "affiliations": ["Fordham University, Bank of Finland, and University of Sydney"]}, {"name": "Feng Tang", "affiliations": ["University of Macau and Hang Seng University of Hong Kong"]}, {"name": "Jing Xie", "affiliations": ["University of Macau Department of Finance and Business Economics"]}], "abstract": "Abstract This article shows that when a compensation peer firm experiences a significant failure in its say-on-pay (SOP) voting, the focal firm\u2019s stock price is adversely affected, resulting in reduced CEO pay in the subsequent period. This pay-reduction effect is amplified when the board is more powerful, when proxy advisors express concerns about CEO pay, and when the compensation consultant lacks quality. Directors who react to the price drop and cut the CEO\u2019s pay receive higher votes in future director elections, implying a market feedback effect for directors of the focal firm triggered by their peers\u2019 SOP voting failure.", "date": "2025-11-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102299", "title_zh": "\u5e02\u573a\u53cd\u9988\u6548\u5e94\u5bf9CEO\u85aa\u916c\u7684\u5f71\u54cd\uff1a\u6765\u81ea\u540c\u884c\u8bf4\u5426\u85aa\u916c\u6295\u7968\u5931\u8d25\u7684\u8bc1\u636e", "abstract_zh": "\u672c\u6587\u8868\u660e\uff0c\u5f53\u4e00\u5bb6\u540c\u884c\u4f01\u4e1a\u5728\u8bf4\u5426\u85aa\u916c\uff08SOP\uff09\u6295\u7968\u4e2d\u51fa\u73b0\u91cd\u5927\u5931\u8d25\u65f6\uff0c\u76ee\u6807\u4f01\u4e1a\u7684\u80a1\u4ef7\u4f1a\u53d7\u5230\u8d1f\u9762\u5f71\u54cd\uff0c\u4ece\u800c\u5bfc\u81f4\u5176CEO\u85aa\u916c\u5728\u540e\u7eed\u65f6\u671f\u4e0b\u964d\u3002\u8fd9\u79cd\u85aa\u916c\u524a\u51cf\u6548\u5e94\u5728\u8463\u4e8b\u4f1a\u6743\u529b\u66f4\u5f3a\u3001\u4ee3\u7406\u987e\u95ee\u5bf9CEO\u85aa\u916c\u8868\u793a\u62c5\u5fe7\uff0c\u4ee5\u53ca\u85aa\u916c\u987e\u95ee\u8d28\u91cf\u8f83\u4f4e\u7684\u60c5\u51b5\u4e0b\u88ab\u653e\u5927\u3002\u90a3\u4e9b\u5bf9\u80a1\u4ef7\u4e0b\u8dcc\u4f5c\u51fa\u53cd\u5e94\u5e76\u524a\u51cfCEO\u85aa\u916c\u7684\u8463\u4e8b\uff0c\u5728\u672a\u6765\u7684\u8463\u4e8b\u9009\u4e3e\u4e2d\u83b7\u5f97\u66f4\u9ad8\u7684\u9009\u7968\uff0c\u8fd9\u8868\u660e\u76ee\u6807\u4f01\u4e1a\u8463\u4e8b\u56e0\u540c\u884cSOP\u6295\u7968\u5931\u8d25\u800c\u89e6\u53d1\u4e86\u5e02\u573a\u53cd\u9988\u6548\u5e94\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5e02\u573a\u53cd\u9988"]}, {"doi": "10.1093/qje/qjaf050", "journal": "QJE", "title": "Diversifying Society\u2019s Leaders? The Determinants and Causal Effects of Admission to Highly Selective Private Colleges", "authors": ["Raj Chetty", "David J Deming", "John N Friedman"], "author_details": [{"name": "Raj Chetty", "affiliations": ["Harvard University and National Bureau of Economic Research ,"]}, {"name": "David J Deming", "affiliations": ["Harvard University and National Bureau of Economic Research ,"]}, {"name": "John N Friedman", "affiliations": ["Brown University and National Bureau of Economic Research ,"]}], "abstract": "Abstract We use anonymized admissions data from several colleges linked to income tax records and SAT and ACT test scores to study the determinants and causal effects of attending Ivy-Plus colleges (Ivy League, Stanford, MIT, Duke, and Chicago). Children from families in the top 1% are more than twice as likely to attend an Ivy-Plus college as those from middle-class families with comparable SAT/ACT scores. Two-thirds of this gap is due to higher admission rates for students with comparable test scores from high-income families; the remaining third is due to differences in rates of application and matriculation. In contrast, children from high-income families have no admissions advantage at flagship public colleges. The high-income admissions advantage at Ivy-Plus colleges is driven by three factors: (i) preferences for children of alumni, (ii) weight placed on nonacademic credentials, and (iii) athletic recruitment. Using a new research design that isolates idiosyncratic variation in admissions decisions for waitlisted applicants, we show that attending an Ivy-Plus college instead of the average flagship public college increases students\u2019 chances of reaching the top 1% of the earnings distribution by 50%, nearly doubles their chances of attending an elite graduate school, and almost triples their chances of working at a prestigious firm. The three factors that give children from high-income families an admissions advantage are uncorrelated or negatively correlated with postcollege outcomes, whereas academic credentials such as SAT/ACT scores are highly predictive of postcollege success.", "date": "2025-10-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf050", "title_zh": "\u591a\u5143\u5316\u793e\u4f1a\u9886\u8896\uff1f\u8fdb\u5165\u9876\u5c16\u79c1\u7acb\u5b66\u9662\u7684\u51b3\u5b9a\u56e0\u7d20\u53ca\u5176\u56e0\u679c\u6548\u5e94", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u7528\u591a\u4e2a\u5b66\u9662\u7684\u533f\u540d\u5f55\u53d6\u6570\u636e\uff0c\u5e76\u7ed3\u5408\u6536\u5165\u7a0e\u8bb0\u5f55\u548cSAT\u3001ACT\u8003\u8bd5\u6210\u7ee9\uff0c\u7814\u7a76\u8fdb\u5165\u201c\u5e38\u6625\u85e4+\u201d\u5b66\u9662\uff08\u5e38\u6625\u85e4\u8054\u76df\u3001\u65af\u5766\u798f\u5927\u5b66\u3001\u9ebb\u7701\u7406\u5de5\u5b66\u9662\u3001\u675c\u514b\u5927\u5b66\u548c\u829d\u52a0\u54e5\u5927\u5b66\uff09\u7684\u51b3\u5b9a\u56e0\u7d20\u53ca\u5176\u56e0\u679c\u6548\u5e94\u3002\u5bb6\u5ead\u6536\u5165\u5904\u4e8e\u524d1%\u7684\u513f\u7ae5\uff0c\u5176\u8fdb\u5165\u201c\u5e38\u6625\u85e4+\u201d\u5b66\u9662\u7684\u6982\u7387\u662f\u4e2d\u4ea7\u5bb6\u5ead\u513f\u7ae5\u7684\u4e24\u500d\u4ee5\u4e0a\uff0c\u4e14\u5728SAT/ACT\u6210\u7ee9\u76f8\u5f53\u7684\u60c5\u51b5\u4e0b\uff0c\u8fd9\u4e00\u5dee\u8ddd\u7684\u4e09\u5206\u4e4b\u4e8c\u6e90\u4e8e\u9ad8\u6536\u5165\u5bb6\u5ead\u5b66\u751f\u66f4\u9ad8\u7684\u5f55\u53d6\u7387\uff0c\u5269\u4e0b\u7684\u4e09\u5206\u4e4b\u4e00\u5219\u6e90\u4e8e\u7533\u8bf7\u548c\u5165\u5b66\u7387\u7684\u5dee\u5f02\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u9ad8\u6536\u5165\u5bb6\u5ead\u513f\u7ae5\u5728\u65d7\u8230\u516c\u7acb\u5b66\u9662\u7684\u5f55\u53d6\u4e0a\u5e76\u65e0\u4f18\u52bf\u3002\u5728\u201c\u5e38\u6625\u85e4+\u201d\u5b66\u9662\u4e2d\uff0c\u9ad8\u6536\u5165\u5bb6\u5ead\u513f\u7ae5\u7684\u5f55\u53d6\u4f18\u52bf\u7531\u4e09\u4e2a\u56e0\u7d20\u9a71\u52a8\uff1a\uff08i\uff09\u5bf9\u6821\u53cb\u5b50\u5973\u7684\u504f\u597d\uff0c\uff08ii\uff09\u5bf9\u975e\u5b66\u672f\u80cc\u666f\u8d44\u8d28\u7684\u91cd\u89c6\uff0c\u4ee5\u53ca\uff08iii\uff09\u4f53\u80b2\u62db\u751f\u3002\u901a\u8fc7\u4e00\u79cd\u65b0\u7684\u7814\u7a76\u8bbe\u8ba1\uff0c\u8be5\u8bbe\u8ba1\u9694\u79bb\u4e86\u7b49\u5f85\u5f55\u53d6\u540d\u5355\u4e0a\u7533\u8bf7\u8005\u7684\u5f55\u53d6\u51b3\u7b56\u4e2d\u7684\u4e2a\u4f53\u5dee\u5f02\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u76f8\u8f83\u4e8e\u5e73\u5747\u65d7\u8230\u516c\u7acb\u5b66\u9662\uff0c\u8fdb\u5165\u201c\u5e38\u6625\u85e4+\u201d\u5b66\u9662\u7684\u5b66\u751f\u5176\u8fdb\u5165\u6536\u5165\u5206\u5e03\u524d1%\u7684\u6982\u7387\u63d0\u9ad8\u4e8650%\uff0c\u8fdb\u5165\u9876\u5c16\u7814\u7a76\u751f\u9662\u7684\u53ef\u80fd\u6027\u51e0\u4e4e\u7ffb\u500d\uff0c\u8fdb\u5165\u77e5\u540d\u4f01\u4e1a\u7684\u53ef\u80fd\u6027\u51e0\u4e4e\u589e\u957f\u4e09\u500d\u3002\u7ed9\u4e88\u9ad8\u6536\u5165\u5bb6\u5ead\u513f\u7ae5\u5f55\u53d6\u4f18\u52bf\u7684\u8fd9\u4e09\u4e2a\u56e0\u7d20\u4e0e\u5927\u5b66\u6bd5\u4e1a\u540e\u7684\u53d1\u5c55\u7ed3\u679c\u65e0\u76f8\u5173\u6027\u6216\u5448\u8d1f\u76f8\u5173\uff0c\u800cSAT/ACT\u7b49\u5b66\u672f\u6210\u7ee9\u5219\u9ad8\u5ea6\u9884\u6d4b\u6bd5\u4e1a\u540e\u6210\u529f\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf049", "journal": "QJE", "title": "Bargaining and Inequality in the Labor Market", "authors": ["Sydnee Caldwell", "Ingrid Haegele", "J\u00f6rg Heining"], "author_details": [{"name": "Sydnee Caldwell", "affiliations": ["University of California, Berkeley, and National Bureau of Economic Research ,"]}, {"name": "Ingrid Haegele", "affiliations": ["Ludwig Maximilian University of Munich and Institute for Employment Research ,"]}, {"name": "J\u00f6rg Heining", "affiliations": ["Institute for Employment Research ,"]}], "abstract": "Abstract We use novel surveys of firms and workers, linked to administrative employer-employee data, to study the prevalence and importance of individual bargaining in wage determination. We show that simple survey questions accurately elicit firms\u2019 bargaining strategies. Using the elicited strategies for 772 German firms, we document that the majority of firms are willing to engage in individual wage bargaining. Labor market factors predict firms\u2019 strategies better than firm characteristics. Survey responses from nearly 10,000 full-time workers indicate that most workers provide their salary expectations before they receive a job offer. Most outside offers are rejected, with the worker remaining at the incumbent firm. There is substantial heterogeneity in workers\u2019 bargaining behavior, which translates into within-firm wage inequality. Firms that set pay via individual bargaining have a 3 percentage point higher gender wage gap.", "date": "2025-10-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf049", "title_zh": "\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u7684\u8ba8\u4ef7\u8fd8\u4ef7\u4e0e\u4e0d\u5e73\u7b49", "abstract_zh": "\u6211\u4eec\u5229\u7528\u4f01\u4e1a\u4e0e\u5458\u5de5\u7684\u65b0\u578b\u8c03\u67e5\u6570\u636e\uff0c\u5e76\u4e0e\u884c\u653f\u96c7\u4e3b-\u5458\u5de5\u6570\u636e\u76f8\u94fe\u63a5\uff0c\u7814\u7a76\u4e2a\u4f53\u8ba8\u4ef7\u8fd8\u4ef7\u5728\u5de5\u8d44\u786e\u5b9a\u4e2d\u7684\u666e\u904d\u6027\u53ca\u5176\u91cd\u8981\u6027\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u7b80\u5355\u7684\u8c03\u67e5\u95ee\u9898\u80fd\u591f\u51c6\u786e\u83b7\u53d6\u4f01\u4e1a\u8ba8\u4ef7\u8fd8\u4ef7\u7b56\u7565\u3002\u57fa\u4e8e\u5bf9772\u5bb6\u5fb7\u56fd\u4f01\u4e1a\u7684\u8c03\u67e5\u7b56\u7565\uff0c\u6211\u4eec\u53d1\u73b0\u5927\u591a\u6570\u4f01\u4e1a\u90fd\u613f\u610f\u8fdb\u884c\u4e2a\u4f53\u5de5\u8d44\u8ba8\u4ef7\u8fd8\u4ef7\u3002\u52b3\u52a8\u529b\u5e02\u573a\u56e0\u7d20\u6bd4\u4f01\u4e1a\u7279\u5f81\u66f4\u80fd\u9884\u6d4b\u4f01\u4e1a\u7684\u8ba8\u4ef7\u8fd8\u4ef7\u7b56\u7565\u3002\u6765\u81ea\u8fd11\u4e07\u540d\u5168\u804c\u5458\u5de5\u7684\u8c03\u67e5\u7ed3\u679c\u663e\u793a\uff0c\u5927\u591a\u6570\u5458\u5de5\u5728\u6536\u5230\u5de5\u4f5coffer\u4e4b\u524d\u4f1a\u63d0\u51fa\u81ea\u5df1\u7684\u85aa\u8d44\u671f\u671b\uff0c\u4e14\u5927\u591a\u6570\u5916\u90e8offer\u88ab\u62d2\u7edd\uff0c\u5458\u5de5\u6700\u7ec8\u7559\u5728\u539f\u4f01\u4e1a\u3002\u5458\u5de5\u5728\u8ba8\u4ef7\u8fd8\u4ef7\u884c\u4e3a\u4e0a\u5b58\u5728\u663e\u8457\u5f02\u8d28\u6027\uff0c\u8fd9\u5bfc\u81f4\u4e86\u4f01\u4e1a\u5185\u90e8\u7684\u5de5\u8d44\u4e0d\u5e73\u7b49\u3002\u901a\u8fc7\u4e2a\u4f53\u8ba8\u4ef7\u8fd8\u4ef7\u8bbe\u5b9a\u85aa\u916c\u7684\u4f01\u4e1a\uff0c\u5176\u6027\u522b\u5de5\u8d44\u5dee\u8ddd\u9ad8\u51fa3\u4e2a\u767e\u5206\u70b9\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1017/s0022109025102317", "journal": "JFQA", "title": "Do Shareholder Leverage Constraints Affect Debtholders?", "authors": ["Xiaoran Huang", "Massimo Massa", "Lei Zhang"], "author_details": [{"name": "Xiaoran Huang", "affiliations": ["Xiamen University School of Economics WISE"]}, {"name": "Massimo Massa", "affiliations": ["INSEAD Finance Department"]}, {"name": "Lei Zhang", "affiliations": ["City University of Hong Kong College of Business Department of Economics and Finance"]}], "abstract": "Abstract We examine the relationship between shareholder leverage constraints and corporate risk-taking, focusing on its impact on debtholders. Our findings show that mutual fund leverage constraints are related to more risk-taking activities of portfolio companies, inducing higher credit risk and greater risk-shifting concerns for the firms\u2019 debtholders. In response, the debtholders raise borrowing costs and tighten lending conditions. These effects intensify for firms facing higher levels of conflict between debtholders and shareholders and when mutual funds exert greater influence over firms. Econometric analyses, including instrumental variable specifications and asset management company mergers, support a causal interpretation.", "date": "2025-10-30", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1017/s0022109025102317", "title_zh": "\u80a1\u4e1c\u6760\u6746\u7ea6\u675f\u4f1a\u5f71\u54cd\u503a\u6743\u4eba\u5417\uff1f", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u80a1\u4e1c\u6760\u6746\u7ea6\u675f\u4e0e\u4f01\u4e1a\u98ce\u9669\u627f\u62c5\u4e4b\u95f4\u7684\u5173\u7cfb\uff0c\u91cd\u70b9\u5173\u6ce8\u5176\u5bf9\u4f01\u4e1a\u503a\u6743\u4eba\u7684\u5f71\u54cd\u3002\u6211\u4eec\u7684\u53d1\u73b0\u8868\u660e\uff0c\u5171\u540c\u57fa\u91d1\u7684\u6760\u6746\u7ea6\u675f\u4e0e\u6295\u8d44\u7ec4\u5408\u516c\u53f8\u66f4\u6fc0\u8fdb\u7684\u98ce\u9669\u627f\u62c5\u884c\u4e3a\u76f8\u5173\uff0c\u5bfc\u81f4\u4f01\u4e1a\u4fe1\u7528\u98ce\u9669\u4e0a\u5347\uff0c\u503a\u6743\u4eba\u7684\u98ce\u9669\u8f6c\u79fb\u62c5\u5fe7\u52a0\u5267\u3002\u4f5c\u4e3a\u56de\u5e94\uff0c\u503a\u6743\u4eba\u63d0\u9ad8\u4e86\u501f\u8d37\u6210\u672c\u5e76\u6536\u7d27\u4e86\u8d37\u6b3e\u6761\u4ef6\u3002\u5f53\u4f01\u4e1a\u80a1\u4e1c\u4e0e\u503a\u6743\u4eba\u4e4b\u95f4\u7684\u51b2\u7a81\u7a0b\u5ea6\u66f4\u9ad8\uff0c\u4e14\u5171\u540c\u57fa\u91d1\u5bf9\u4f01\u4e1a\u7684\u5f71\u54cd\u66f4\u5927\u65f6\uff0c\u8fd9\u4e9b\u6548\u5e94\u4f1a\u66f4\u52a0\u663e\u8457\u3002\u5305\u62ec\u5de5\u5177\u53d8\u91cf\u8bbe\u5b9a\u548c\u8d44\u4ea7\u7ba1\u7406\u516c\u53f8\u5408\u5e76\u7684\u8ba1\u91cf\u5206\u6790\u652f\u6301\u4e86\u8fd9\u4e00\u5173\u7cfb\u7684\u56e0\u679c\u89e3\u91ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u5e76\u8d2d"]}, {"doi": "10.1093/qje/qjaf048", "journal": "QJE", "title": "Digital Distractions with Peer Influence: The Impact of Mobile App Usage on Academic and Labor Market Outcomes", "authors": ["Panle Jia Barwick", "Siyu Chen", "Chao Fu", "Teng Li"], "author_details": [{"name": "Panle Jia Barwick", "affiliations": ["University of Wisconsin-Madison and National Bureau of Economic Research, United States, Centre for Economic Policy and Research ,"]}, {"name": "Siyu Chen", "affiliations": ["Jinan University ,"]}, {"name": "Chao Fu", "affiliations": ["University of Wisconsin-Madison and National Bureau of Economic Research ,"]}, {"name": "Teng Li", "affiliations": ["Sun Yat-sen University ,"]}], "abstract": "Abstract Concerns about excessive mobile phone use among youth are mounting. We present estimates of behavioral and contextual peer effects, along with comprehensive evidence on how students\u2019 own and their peers\u2019 app usage affect academic performance, physical health, and labor market outcomes. Our analysis draws on administrative data from a Chinese university covering three student cohorts over four years. We exploit random roommate assignments, differential exposure to a policy shock (gaming restrictions for minors), and differential exposure to a discrete event (the introduction of a blockbuster video game) for identification. App usage is contagious: a one s.d. increase in roommates\u2019 in-college app usage raises own usage by 5.8%. High app usage is harmful across all measured outcomes. A one s.d. increase in app usage reduces GPAs by 36.2% of a within-cohort-major s.d. and lowers wages by 2.3%. Roommates\u2019 app usage reduces a student\u2019s GPA and wages through both disruptions and behavioral spillovers, generating a total negative effect that exceeds half the magnitude of the impact from the student\u2019s own app usage. Extending China\u2019s three-hour-per-week gaming restriction for minors to college students would boost their initial wages by 0.9%. High-frequency GPS and app usage data show that heavy app users spend less time in study halls, are more frequently late or absent from class, and get less sleep.", "date": "2025-10-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf048", "title_zh": "\u6570\u5b57\u5e72\u6270\u4e0e\u540c\u4f34\u5f71\u54cd\uff1a\u79fb\u52a8\u5e94\u7528\u4f7f\u7528\u5bf9\u5b66\u672f\u8868\u73b0\u548c\u52b3\u52a8\u529b\u5e02\u573a\u7ed3\u679c\u7684\u5f71\u54cd", "abstract_zh": "\u6458\u8981 \u5173\u4e8e\u9752\u5c11\u5e74\u8fc7\u5ea6\u4f7f\u7528\u624b\u673a\u7684\u62c5\u5fe7\u65e5\u76ca\u589e\u52a0\u3002\u672c\u6587\u63d0\u4f9b\u4e86\u5173\u4e8e\u884c\u4e3a\u548c\u60c5\u5883\u6027\u540c\u4f34\u6548\u5e94\u7684\u4f30\u8ba1\uff0c\u5e76\u5168\u9762\u8003\u5bdf\u4e86\u5b66\u751f\u81ea\u8eab\u53ca\u5176\u540c\u4f34\u7684\u79fb\u52a8\u5e94\u7528\u4f7f\u7528\u5982\u4f55\u5f71\u54cd\u5b66\u4e1a\u6210\u7ee9\u3001\u8eab\u4f53\u5065\u5eb7\u4ee5\u53ca\u52b3\u52a8\u529b\u5e02\u573a\u7ed3\u679c\u3002\u6211\u4eec\u7684\u5206\u6790\u57fa\u4e8e\u4e2d\u56fd\u4e00\u6240\u5927\u5b66\u8986\u76d6\u4e09\u4e2a\u5b66\u751f\u7fa4\u4f53\u56db\u5e74\u671f\u7684\u884c\u653f\u6570\u636e\u3002\u6211\u4eec\u5229\u7528\u968f\u673a\u5206\u914d\u7684\u5ba4\u53cb\u3001\u5bf9\u672a\u6210\u5e74\u4eba\u6e38\u620f\u9650\u5236\u653f\u7b56\u7684\u5dee\u5f02\u5316\u66b4\u9732\u4ee5\u53ca\u5bf9\u4e00\u6b3e\u70ed\u95e8\u89c6\u9891\u6e38\u620f\u63a8\u51fa\u7684\u5dee\u5f02\u5316\u66b4\u9732\u6765\u8fdb\u884c\u8bc6\u522b\u3002\u5e94\u7528\u4f7f\u7528\u5177\u6709\u4f20\u67d3\u6027\uff1a\u5ba4\u53cb\u5728\u5927\u5b66\u671f\u95f4\u5e94\u7528\u4f7f\u7528\u7684\u6807\u51c6\u5dee\u589e\u52a01\u4e2a\u5355\u4f4d\uff0c\u4f1a\u4f7f\u5f97\u81ea\u8eab\u5e94\u7528\u4f7f\u7528\u91cf\u4e0a\u53475.8%\u3002\u9ad8\u9891\u7387\u7684\u5e94\u7528\u4f7f\u7528\u5728\u6240\u6709\u8861\u91cf\u7ed3\u679c\u4e0a\u5747\u5177\u6709\u8d1f\u9762\u5f71\u54cd\u3002\u5e94\u7528\u4f7f\u7528\u91cf\u589e\u52a0\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u4f1a\u964d\u4f4eGPA\u8fbe\u540c\u4e13\u4e1a\u7fa4\u4f53\u5185\u6807\u51c6\u5dee\u768436.2%\uff0c\u5e76\u4f7f\u5de5\u8d44\u964d\u4f4e2.3%\u3002\u5ba4\u53cb\u7684\u5e94\u7528\u4f7f\u7528\u901a\u8fc7\u5e72\u6270\u548c\u884c\u4e3a\u5916\u6ea2\u6548\u5e94\u964d\u4f4e\u5b66\u751f\u7684GPA\u548c\u5de5\u8d44\uff0c\u603b\u8d1f\u9762\u5f71\u54cd\u8d85\u8fc7\u81ea\u8eab\u5e94\u7528\u4f7f\u7528\u5f71\u54cd\u7684\u4e00\u534a\u3002\u5c06\u4e2d\u56fd\u5bf9\u672a\u6210\u5e74\u4eba\u7684\u6bcf\u5468\u4e09\u5c0f\u65f6\u6e38\u620f\u9650\u5236\u6269\u5c55\u81f3\u5927\u5b66\u751f\uff0c\u5c06\u4f7f\u4ed6\u4eec\u7684\u521d\u59cb\u5de5\u8d44\u63d0\u9ad80.9%\u3002\u9ad8\u9891GPS\u548c\u5e94\u7528\u4f7f\u7528\u6570\u636e\u8868\u660e\uff0c\u91cd\u5ea6\u5e94\u7528\u7528\u6237\u5728\u81ea\u4e60\u5ba4\u505c\u7559\u65f6\u95f4\u66f4\u5c11\uff0c\u66f4\u9891\u7e41\u5730\u8fdf\u5230\u6216\u7f3a\u8bfe\uff0c\u5e76\u4e14\u7761\u7720\u65f6\u95f4\u66f4\u77ed\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.70000", "journal": "JF", "title": "Presidential Address: Housing Betas", "authors": ["MONIKA PIAZZESI"], "author_details": [{"name": "MONIKA PIAZZESI", "affiliations": []}], "abstract": "ABSTRACT This paper documents new stylized facts about returns and cashflow growth rates on stocks and housing over decade\u2010long holding periods. While cashflow growth rates on the two assets comove positively, their returns comove negatively until the Global Financial Crisis and positively thereafter. These facts present a puzzle for representative\u2010agent models that imply positive return comovement for assets with similar cashflows. I consider a heterogeneous\u2010agent model with segmented stock and housing markets connected through credit. News about the aggregate economy generates negative return comovement. Recent shifts such as wealthier homebuyers and institutional housing purchases reduce the importance of credit and segmentation.", "date": "2025-10-17", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.70000", "title_zh": "\u603b\u7edf\u6f14\u8bb2\uff1a\u4f4f\u623f\u8d1d\u5854", "abstract_zh": "\u6458\u8981 \u672c\u6587\u8bb0\u5f55\u4e86\u5173\u4e8e\u80a1\u7968\u548c\u4f4f\u623f\u5728\u5341\u5e74\u6301\u6709\u671f\u5185\u6536\u76ca\u53ca\u73b0\u91d1\u6d41\u589e\u957f\u7387\u7684\u65b0\u4e8b\u5b9e\u3002\u5c3d\u7ba1\u4e24\u79cd\u8d44\u4ea7\u7684\u73b0\u91d1\u6d41\u589e\u957f\u7387\u5448\u6b63\u5411\u5171\u52a8\uff0c\u4f46\u5b83\u4eec\u7684\u6536\u76ca\u5728\u91d1\u878d\u5371\u673a\u4e4b\u524d\u5448\u8d1f\u5411\u5171\u52a8\uff0c\u6b64\u540e\u5219\u5448\u6b63\u5411\u5171\u52a8\u3002\u8fd9\u4e9b\u4e8b\u5b9e\u5bf9\u5047\u8bbe\u5177\u6709\u76f8\u4f3c\u73b0\u91d1\u6d41\u7684\u8d44\u4ea7\u5e94\u5448\u73b0\u6b63\u5411\u6536\u76ca\u5171\u52a8\u7684\u4ee3\u8868\u6027\u4e3b\u4f53\u6a21\u578b\u6784\u6210\u4e86\u4e00\u4e2a\u96be\u9898\u3002\u6211\u8003\u8651\u4e86\u4e00\u4e2a\u5f02\u8d28\u6027\u4e3b\u4f53\u6a21\u578b\uff0c\u5176\u4e2d\u80a1\u7968\u548c\u4f4f\u623f\u5e02\u573a\u901a\u8fc7\u4fe1\u8d37\u76f8\u4e92\u8fde\u63a5\u3002\u5173\u4e8e\u6574\u4f53\u7ecf\u6d4e\u7684\u65b0\u95fb\u4f1a\u5f15\u53d1\u8d1f\u5411\u6536\u76ca\u5171\u52a8\u3002\u8fd1\u5e74\u6765\uff0c\u8d22\u5bcc\u66f4\u4e30\u5bcc\u7684\u8d2d\u623f\u8005\u548c\u673a\u6784\u4f4f\u623f\u8d2d\u4e70\u884c\u4e3a\u51cf\u5c11\u4e86\u4fe1\u8d37\u548c\u5e02\u573a\u5206\u5272\u7684\u91cd\u8981\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1111/jofi.13496", "journal": "JF", "title": "Privacy and Team Incentives", "authors": ["ANDREA M. BUFFA", "QING LIU", "LUCY WHITE"], "author_details": [{"name": "ANDREA M. BUFFA", "affiliations": []}, {"name": "QING LIU", "affiliations": []}, {"name": "LUCY WHITE", "affiliations": []}], "abstract": "ABSTRACT Real\u2010world contracts are typically private, observed only by their direct signatories, so agents working together are vulnerable to the principal opportunistically reducing other agents' incentives. The principal can mitigate this commitment problem by giving the most skilled agent a budget and delegating authority to write other agents' contracts. This endogenous hierarchy, never optimal with public contracts, raises effort, output, and compensation but allows rent extraction. The principal prefers it when contracts are opaque enough, skill is sufficiently heterogeneous across agents, and joint output is sensitive enough to effort. Our model provides novel predictions for the structure of banking syndicates.", "date": "2025-10-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.13496", "title_zh": "\u9690\u79c1\u4e0e\u56e2\u961f\u6fc0\u52b1", "abstract_zh": "\u6458\u8981 \u5b9e\u9645\u4e2d\u7684\u5408\u540c\u901a\u5e38\u662f\u79c1\u5bc6\u7684\uff0c\u4ec5\u88ab\u76f4\u63a5\u7b7e\u7f72\u65b9\u6240\u77e5\u6653\uff0c\u56e0\u6b64\u5408\u4f5c\u4e2d\u7684\u4ee3\u7406\u4eba\u5bb9\u6613\u53d7\u5230\u59d4\u6258\u4eba\u673a\u4f1a\u4e3b\u4e49\u884c\u4e3a\u7684\u5f71\u54cd\uff0c\u5373\u59d4\u6258\u4eba\u53ef\u80fd\u65e0\u7aef\u964d\u4f4e\u5176\u4ed6\u4ee3\u7406\u4eba\u7684\u6fc0\u52b1\u3002\u59d4\u6258\u4eba\u53ef\u4ee5\u901a\u8fc7\u4e3a\u6700\u64c5\u957f\u7684\u4ee3\u7406\u4eba\u5206\u914d\u9884\u7b97\uff0c\u5e76\u6388\u6743\u5176\u8d77\u8349\u5176\u4ed6\u4ee3\u7406\u4eba\u7684\u5408\u540c\u6765\u7f13\u89e3\u8fd9\u4e00\u627f\u8bfa\u95ee\u9898\u3002\u8fd9\u79cd\u5185\u751f\u5f62\u6210\u7684\u5c42\u7ea7\u7ed3\u6784\uff0c\u5728\u516c\u5f00\u5408\u540c\u60c5\u51b5\u4e0b\u4ece\u6765\u4e0d\u662f\u6700\u4f18\u7684\uff0c\u5b83\u63d0\u9ad8\u4e86\u52aa\u529b\u7a0b\u5ea6\u3001\u4ea7\u51fa\u548c\u62a5\u916c\uff0c\u4f46\u540c\u65f6\u4e5f\u5141\u8bb8\u79df\u91d1\u63d0\u53d6\u3002\u5f53\u5408\u540c\u8db3\u591f\u79c1\u5bc6\u3001\u4ee3\u7406\u4eba\u4e4b\u95f4\u7684\u6280\u80fd\u5dee\u5f02\u8db3\u591f\u663e\u8457\uff0c\u4e14\u8054\u5408\u4ea7\u51fa\u5bf9\u52aa\u529b\u7a0b\u5ea6\u8db3\u591f\u654f\u611f\u65f6\uff0c\u59d4\u6258\u4eba\u66f4\u503e\u5411\u4e8e\u8fd9\u79cd\u7ed3\u6784\u3002\u6211\u4eec\u7684\u6a21\u578b\u4e3a\u94f6\u884c\u8054\u5408\u4f53\u7684\u7ed3\u6784\u63d0\u4f9b\u4e86\u65b0\u7684\u9884\u6d4b\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.13500", "journal": "JF", "title": "The Imperfect Intermediation of Money\u2010Like Assets", "authors": ["JEREMY C. STEIN", "JONATHAN WALLEN"], "author_details": [{"name": "JEREMY C. STEIN", "affiliations": []}, {"name": "JONATHAN WALLEN", "affiliations": []}], "abstract": "ABSTRACT We study supply\u2010and\u2010demand effects in the U.S. Treasury bill market by comparing the returns on T\u2010bills to the policy rate on the Federal Reserve's reverse repurchase (RRP) facility. We develop and test a simple model where the RRP\u2010bill spread is policed both by heterogeneously elastic money funds and by corporate treasurers who derive collateral benefits from holding T\u2010bills. In response to shifts in T\u2010bill supply, money funds act as front\u2010line arbitrageurs. However, when T\u2010bills become extremely scarce, less elastic corporate treasurers become the marginal investors and supply shifts have a larger effect on T\u2010bill rates.", "date": "2025-10-14", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.13500", "title_zh": "\u8d27\u5e01\u7c7b\u8d44\u4ea7\u7684\u4e0d\u5b8c\u5168\u4e2d\u4ecb", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u901a\u8fc7\u5c06\u56fd\u5e93\u5238\u7684\u56de\u62a5\u4e0e\u7f8e\u8054\u50a8\u56de\u8d2d\u9006\u56de\u8d2d\uff08RRP\uff09\u8bbe\u65bd\u7684\u653f\u7b56\u5229\u7387\u8fdb\u884c\u6bd4\u8f83\uff0c\u7814\u7a76\u4e86\u7f8e\u56fd\u56fd\u5e93\u5238\u5e02\u573a\u4e2d\u7684\u4f9b\u9700\u6548\u5e94\u3002\u6211\u4eec\u6784\u5efa\u5e76\u68c0\u9a8c\u4e86\u4e00\u4e2a\u7b80\u5355\u6a21\u578b\uff0c\u5176\u4e2dRRP-\u56fd\u5e93\u5238\u5229\u5dee\u53d7\u5230\u5f39\u6027\u4e0d\u540c\u7684\u8d27\u5e01\u57fa\u91d1\u4ee5\u53ca\u4ece\u6301\u6709\u56fd\u5e93\u5238\u4e2d\u83b7\u5f97\u62b5\u62bc\u54c1\u6536\u76ca\u7684\u516c\u53f8\u8d22\u52a1\u4e3b\u7ba1\u7684\u53cc\u91cd\u76d1\u7ba1\u3002\u5f53\u56fd\u5e93\u5238\u4f9b\u5e94\u91cf\u53d1\u751f\u53d8\u5316\u65f6\uff0c\u8d27\u5e01\u57fa\u91d1\u5145\u5f53\u4e86\u7b2c\u4e00\u7ebf\u7684\u5957\u5229\u8005\u3002\u7136\u800c\uff0c\u5f53\u56fd\u5e93\u5238\u53d8\u5f97\u6781\u5ea6\u7a00\u7f3a\u65f6\uff0c\u5f39\u6027\u8f83\u5c0f\u7684\u516c\u53f8\u8d22\u52a1\u4e3b\u7ba1\u6210\u4e3a\u8fb9\u9645\u6295\u8d44\u8005\uff0c\u4f9b\u5e94\u91cf\u7684\u53d8\u5316\u5bf9\u56fd\u5e93\u5238\u5229\u7387\u7684\u5f71\u54cd\u4e5f\u968f\u4e4b\u589e\u5927\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf047", "journal": "QJE", "title": "The Price of Housing in the United States, 1890\u20132006", "authors": ["Ronan C Lyons", "Allison Shertzer", "Rowena Gray", "David Agorastos"], "author_details": [{"name": "Ronan C Lyons", "affiliations": ["Trinity College Dublin ,"]}, {"name": "Allison Shertzer", "affiliations": ["Federal Reserve Bank of Philadelphia ,"]}, {"name": "Rowena Gray", "affiliations": ["University of California, Merced ,"]}, {"name": "David Agorastos", "affiliations": []}], "abstract": "Abstract We construct the first annual market rent and home sales price series for American cities over the twentieth century using 2.7 million newspaper real estate listings. Our findings revise several stylized facts about U.S. housing markets. Real market rents did not fall during the postwar period in most cities and rose nationally by 60% from 1890 to 2006. We also document higher sales price growth between 1953 and 1987 relative to previous series. Real prices reached almost four times their 1890 level by 2006. Prices grew most in metros with high demand and low levels of construction. We find that the rent-to-price ratio fell from about 8% in the early twentieth century to 3% by 2006, consistent with declines in the cost of owning housing relative to renting. For the typical year in our period, the annual return to owning housing was 9%, driven mostly by rental returns of 7.7%, with capital gains contributing only 1.3%. While capital gains were close to zero from 1890 to 1940, they grew to nearly a third of total returns from 1970 to 2006.", "date": "2025-10-10", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf047", "title_zh": "\u7f8e\u56fd\u4f4f\u623f\u4ef7\u683c1890\u20132006\u5e74", "abstract_zh": "\u6211\u4eec\u5229\u7528270\u4e07\u4efd\u62a5\u7eb8\u623f\u5730\u4ea7\u5e7f\u544a\uff0c\u6784\u5efa\u4e86\u7f8e\u56fd\u57ce\u5e0220\u4e16\u7eaa\u5e74\u5ea6\u5e02\u573a\u79df\u91d1\u548c\u623f\u5c4b\u9500\u552e\u4ef7\u683c\u7cfb\u5217\uff0c\u8fd9\u662f\u9996\u6b21\u5bf9\u7f8e\u56fd\u57ce\u5e02\u4f4f\u623f\u5e02\u573a\u7684\u5e74\u5ea6\u6570\u636e\u3002\u6211\u4eec\u7684\u7814\u7a76\u4fee\u6b63\u4e86\u5173\u4e8e\u7f8e\u56fd\u4f4f\u623f\u5e02\u573a\u7684\u82e5\u5e72\u4f20\u7edf\u89c2\u70b9\u3002\u5927\u591a\u6570\u57ce\u5e02\u7684\u5b9e\u9645\u5e02\u573a\u79df\u91d1\u5728\u6218\u540e\u65f6\u671f\u5e76\u672a\u4e0b\u964d\uff0c\u800c\u5168\u56fd\u8303\u56f4\u5185\u79df\u91d1\u4ece1890\u5e74\u52302006\u5e74\u4e0a\u6da8\u4e8660%\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0c1953\u5e74\u81f31987\u5e74\u95f4\u7684\u623f\u4ef7\u589e\u957f\u901f\u5ea6\u9ad8\u4e8e\u4ee5\u5f80\u7cfb\u5217\u6240\u663e\u793a\u7684\u6c34\u5e73\u3002\u52302006\u5e74\uff0c\u623f\u4ef7\u51e0\u4e4e\u8fbe\u5230\u4e861890\u5e74\u6c34\u5e73\u7684\u56db\u500d\u3002\u623f\u4ef7\u589e\u957f\u6700\u663e\u8457\u7684\u5730\u533a\u662f\u9700\u6c42\u9ad8\u800c\u5efa\u8bbe\u6c34\u5e73\u4f4e\u7684\u5927\u90fd\u5e02\u533a\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u79df\u91d1\u4e0e\u623f\u4ef7\u6bd4\u7387\u4ece20\u4e16\u7eaa\u521d\u7684\u7ea68%\u4e0b\u964d\u52302006\u5e74\u76843%\uff0c\u8fd9\u8868\u660e\u76f8\u5bf9\u4e8e\u79df\u623f\uff0c\u62e5\u6709\u4f4f\u623f\u7684\u6210\u672c\u5728\u4e0b\u964d\u3002\u5728\u6211\u4eec\u7814\u7a76\u671f\u95f4\u7684\u5178\u578b\u5e74\u4efd\uff0c\u62e5\u6709\u4f4f\u623f\u7684\u5e74\u5316\u56de\u62a5\u7387\u4e3a9%\uff0c\u5176\u4e2d\u79df\u91d1\u56de\u62a5\u53607.7%\uff0c\u8d44\u672c\u6536\u76ca\u4ec5\u8d21\u732e1.3%\u30021890\u5e74\u81f31940\u5e74\u95f4\uff0c\u8d44\u672c\u6536\u76ca\u63a5\u8fd1\u96f6\uff0c\u4f46\u4ece1970\u5e74\u52302006\u5e74\uff0c\u8d44\u672c\u6536\u76ca\u589e\u957f\u81f3\u603b\u56de\u62a5\u7684\u8fd1\u4e09\u5206\u4e4b\u4e00\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.13505", "journal": "JF", "title": "Value without Employment", "authors": ["SIMCHA BARKAI", "STAVROS PANAGEAS"], "author_details": [{"name": "SIMCHA BARKAI", "affiliations": []}, {"name": "STAVROS PANAGEAS", "affiliations": []}], "abstract": "ABSTRACT Young firms' contribution to aggregate employment has been underwhelming. We show that a similar trend is not apparent, however, in their contribution to aggregate sales or stock market capitalization, implying that these firms have exhibited a high average\u2010to\u2010marginal revenue product of labor. We study the implications of a gradual shift in the average\u2010to\u2010marginal revenue product of labor within a model of dynamic firm heterogeneity. We show that this shift provides (i) a unified explanation for several aspects of the decline in dynamism and (ii) a possible explanation for why large declines in young\u2010firm employment may have only a moderate effect on aggregate output and consumption.", "date": "2025-10-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.13505", "title_zh": "\u6ca1\u6709\u5c31\u4e1a\u7684\u4ef7\u503c", "abstract_zh": "\u6458\u8981 \u5e74\u8f7b\u4f01\u4e1a\u7684\u5c31\u4e1a\u8d21\u732e\u4e00\u76f4\u8868\u73b0\u5e73\u5e73\u3002\u7136\u800c\uff0c\u5728\u5176\u5bf9\u603b\u9500\u552e\u989d\u6216\u80a1\u7968\u5e02\u573a\u8d44\u672c\u5316\u65b9\u9762\u7684\u8d21\u732e\u4e0a\uff0c\u5e76\u672a\u663e\u793a\u51fa\u7c7b\u4f3c\u8d8b\u52bf\uff0c\u8fd9\u8868\u660e\u8fd9\u4e9b\u4f01\u4e1a\u8868\u73b0\u51fa\u8f83\u9ad8\u7684\u52b3\u52a8\u5e73\u5747\u4ea7\u51fa\u4e0e\u8fb9\u9645\u4ea7\u51fa\u4e4b\u6bd4\u3002\u6211\u4eec\u7814\u7a76\u4e86\u5728\u52a8\u6001\u4f01\u4e1a\u5f02\u8d28\u6027\u6a21\u578b\u4e2d\uff0c\u52b3\u52a8\u5e73\u5747\u4ea7\u51fa\u4e0e\u8fb9\u9645\u4ea7\u51fa\u4e4b\u6bd4\u9010\u6e10\u53d8\u5316\u7684\u542b\u4e49\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u79cd\u53d8\u5316\u4e3a\u591a\u4e2a\u52a8\u6001\u51cf\u5f31\u73b0\u8c61\u63d0\u4f9b\u4e86\u7edf\u4e00\u89e3\u91ca\uff0c\u5e76\u4e14\u53ef\u80fd\u89e3\u91ca\u4e86\u4e3a\u4f55\u5e74\u8f7b\u4f01\u4e1a\u5c31\u4e1a\u7684\u5927\u5e45\u4e0b\u964d\u5bf9\u6574\u4f53\u4ea7\u51fa\u548c\u6d88\u8d39\u7684\u5f71\u54cd\u76f8\u5bf9\u6709\u9650\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.13507", "journal": "JF", "title": "Asset Pricing and Risk\u2010Sharing Implications of Alternative Pension Plan Systems", "authors": ["NUNO COIMBRA", "FRANCISCO GOMES", "ALEXANDER MICHAELIDES", "JIALU SHEN"], "author_details": [{"name": "NUNO COIMBRA", "affiliations": []}, {"name": "FRANCISCO GOMES", "affiliations": []}, {"name": "ALEXANDER MICHAELIDES", "affiliations": []}, {"name": "JIALU SHEN", "affiliations": []}], "abstract": "ABSTRACT We show that incorporating defined benefit pension funds in an incomplete markets asset pricing model improves its ability to match the historical equity premium and riskless rate and has important risk\u2010sharing implications. We document the importance of the pension fund's size and asset demands, and a new risk channel arising from fluctuations in the fund's returns. We use our calibrated model to study the implications of a shift to an economy with defined contribution plans. The new steady state is characterized by a higher riskless rate and a lower equity premium. Consumption volatility increases for retirees but decreases for workers.", "date": "2025-10-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.13507", "title_zh": "\u4e0d\u540c\u517b\u8001\u91d1\u8ba1\u5212\u4f53\u7cfb\u7684\u8d44\u4ea7\u5b9a\u4ef7\u4e0e\u98ce\u9669\u5206\u62c5\u542b\u4e49", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u8bc1\u660e\uff0c\u5728\u4e0d\u5b8c\u5168\u5e02\u573a\u8d44\u4ea7\u5b9a\u4ef7\u6a21\u578b\u4e2d\u5f15\u5165\u5b9a\u4e49\u6536\u76ca\u578b\u517b\u8001\u91d1\u57fa\u91d1\uff0c\u80fd\u591f\u63d0\u5347\u6a21\u578b\u5bf9\u5386\u53f2\u80a1\u6743\u6ea2\u4ef7\u548c\u65e0\u98ce\u9669\u5229\u7387\u7684\u62df\u5408\u80fd\u529b\uff0c\u5e76\u5177\u6709\u91cd\u8981\u7684\u98ce\u9669\u5206\u62c5\u542b\u4e49\u3002\u6211\u4eec\u8bc1\u5b9e\u4e86\u517b\u8001\u91d1\u57fa\u91d1\u89c4\u6a21\u53ca\u5176\u8d44\u4ea7\u9700\u6c42\u7684\u91cd\u8981\u6027\uff0c\u4ee5\u53ca\u57fa\u91d1\u56de\u62a5\u6ce2\u52a8\u5f15\u53d1\u7684\u4e00\u79cd\u65b0\u98ce\u9669\u4f20\u5bfc\u6e20\u9053\u3002\u6211\u4eec\u5229\u7528\u6821\u51c6\u540e\u7684\u6a21\u578b\u7814\u7a76\u4e86\u5411\u5b9a\u4e49\u8d21\u732e\u578b\u517b\u8001\u91d1\u8ba1\u5212\u7ecf\u6d4e\u8f6c\u578b\u7684\u540e\u679c\u3002\u65b0\u7a33\u6001\u8868\u73b0\u4e3a\u65e0\u98ce\u9669\u5229\u7387\u4e0a\u5347\uff0c\u80a1\u6743\u6ea2\u4ef7\u4e0b\u964d\u3002\u9000\u4f11\u4eba\u5458\u7684\u6d88\u8d39\u6ce2\u52a8\u6027\u4e0a\u5347\uff0c\u800c\u5de5\u4eba\u7684\u6d88\u8d39\u6ce2\u52a8\u6027\u4e0b\u964d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005"]}, {"doi": "10.1111/jofi.13497", "journal": "JF", "title": "CEO Stress, Aging, and Death", "authors": ["MARK BORGSCHULTE", "MARIUS GUENZEL", "CANYAO LIU", "ULRIKE MALMENDIER"], "author_details": [{"name": "MARK BORGSCHULTE", "affiliations": []}, {"name": "MARIUS GUENZEL", "affiliations": []}, {"name": "CANYAO LIU", "affiliations": []}, {"name": "ULRIKE MALMENDIER", "affiliations": []}], "abstract": "ABSTRACT We assess the long\u2010term effects of managerial stress on aging and mortality. Using a difference\u2010in\u2010differences design, we apply neural network\u2013based machine\u2010learning techniques to CEOs' facial images and show that exposure to industry distress shocks during the Great Recession produces visible signs of aging. We estimate a one\u2010year increase in \u201capparent\u201d age. Moreover, using data on CEOs since the mid\u20101970s, we estimate a 1.1\u2010year decrease in life expectancy after an industry distress shock, but a two\u2010year increase when antitakeover laws insulate CEOs from market discipline. The estimated health costs are significant, both in absolute terms and relative to other health risks.", "date": "2025-10-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.13497", "title_zh": "CEO\u538b\u529b\u3001\u8870\u8001\u4e0e\u6b7b\u4ea1", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u8bc4\u4f30\u4e86\u7ba1\u7406\u5c42\u538b\u529b\u5bf9\u8870\u8001\u548c\u6b7b\u4ea1\u7684\u957f\u671f\u5f71\u54cd\u3002\u91c7\u7528\u5dee\u5206-\u5dee\u5f02\u8bbe\u8ba1\uff0c\u6211\u4eec\u5229\u7528\u57fa\u4e8e\u795e\u7ecf\u7f51\u7edc\u7684\u673a\u5668\u5b66\u4e60\u6280\u672f\u5206\u6790CEO\u7684\u9762\u90e8\u56fe\u50cf\uff0c\u53d1\u73b0\u5728\u5168\u7403\u91d1\u878d\u5371\u673a\u671f\u95f4\u906d\u9047\u884c\u4e1a\u56f0\u5883\u51b2\u51fb\uff0c\u4f1a\u5e26\u6765\u660e\u663e\u7684\u8870\u8001\u8ff9\u8c61\uff0c\u8868\u73b0\u4e3a\u201c\u8868\u89c2\u5e74\u9f84\u201d\u589e\u52a0\u4e00\u5e74\u3002\u6b64\u5916\uff0c\u5229\u75281970\u5e74\u4ee3\u4e2d\u671f\u4ee5\u6765\u7684CEO\u6570\u636e\uff0c\u6211\u4eec\u4f30\u8ba1\u5728\u7ecf\u5386\u884c\u4e1a\u56f0\u5883\u51b2\u51fb\u540e\uff0c\u751f\u547d\u9884\u671f\u4f1a\u4e0b\u964d1.1\u5e74\uff1b\u800c\u5728\u53cd\u6536\u8d2d\u6cd5\u5f8b\u4fdd\u62a4CEO\u514d\u53d7\u5e02\u573a\u76d1\u7763\u7684\u60c5\u51b5\u4e0b\uff0c\u751f\u547d\u9884\u671f\u5219\u4f1a\u589e\u52a0\u4e24\u5e74\u3002\u8fd9\u4e9b\u4f30\u8ba1\u7684\u5065\u5eb7\u6210\u672c\u5728\u7edd\u5bf9\u503c\u548c\u4e0e\u5176\u4ed6\u5065\u5eb7\u98ce\u9669\u76f8\u6bd4\u65b9\u9762\u5747\u5177\u6709\u663e\u8457\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc", "AI"]}, {"doi": "10.1093/qje/qjaf039", "journal": "QJE", "title": "The Macroeconomic Consequences of Exchange Rate Depreciations", "authors": ["Masao Fukui", "Emi Nakamura", "J\u00f3n Steinsson"], "author_details": [{"name": "Masao Fukui", "affiliations": ["Boston University ,"]}, {"name": "Emi Nakamura", "affiliations": ["University of California , Berkeley ,"]}, {"name": "J\u00f3n Steinsson", "affiliations": ["University of California , Berkeley ,"]}], "abstract": "Abstract We study the consequences of \u201cregime-induced\u201d exchange rate depreciations by comparing outcomes for peggers versus floaters to the U.S. dollar in response to a dollar depreciation. Pegger currencies depreciate relative to floater currencies and these depreciations are strongly expansionary. The boom is associated with a fall in net exports, and (if anything) an increase in interest rates in the pegger countries. This suggests that expenditure switching and domestic monetary policy are not the main drivers of the boom. We show that a large class of existing models cannot match our estimated responses and develop a model with imperfect financial openness that can. Following a depreciation, uncovered interest parity deviations lower the costs of borrowing from abroad and stimulate the economy, as in the data. The model is consistent with (unconditional) exchange rate disconnect and the Mussa fact, even though exchange rates have large effects on the economy.", "date": "2025-10-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf039", "title_zh": "\u6c47\u7387\u8d2c\u503c\u7684\u5b8f\u89c2\u7ecf\u6d4e\u540e\u679c", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u7531\u201c\u5236\u5ea6\u5f15\u53d1\u201d\u7684\u6c47\u7387\u8d2c\u503c\u5bf9\u9489\u4f4f\u7f8e\u5143\u56fd\u5bb6\u4e0e\u6d6e\u52a8\u6c47\u7387\u56fd\u5bb6\u7684\u5b8f\u89c2\u7ecf\u6d4e\u5f71\u54cd\uff0c\u901a\u8fc7\u6bd4\u8f83\u8fd9\u4e24\u79cd\u56fd\u5bb6\u5728\u7f8e\u5143\u8d2c\u503c\u80cc\u666f\u4e0b\u7684\u53cd\u5e94\u3002\u9489\u4f4f\u7f8e\u5143\u7684\u8d27\u5e01\u76f8\u5bf9\u4e8e\u6d6e\u52a8\u8d27\u5e01\u51fa\u73b0\u8d2c\u503c\uff0c\u8fd9\u79cd\u8d2c\u503c\u5177\u6709\u663e\u8457\u7684\u6269\u5f20\u6548\u5e94\u3002\u7e41\u8363\u671f\u4f34\u968f\u7740\u51c0\u51fa\u53e3\u7684\u4e0b\u964d\uff0c\u4e14\u5728\u9489\u4f4f\u56fd\u4e2d\uff0c\u5229\u7387\u53ef\u80fd\u5e76\u672a\u4e0a\u5347\uff0c\u751a\u81f3\u6709\u6240\u63d0\u9ad8\u3002\u8fd9\u8868\u660e\u652f\u51fa\u7ed3\u6784\u8f6c\u6362\u548c\u56fd\u5185\u8d27\u5e01\u653f\u7b56\u5e76\u975e\u7e41\u8363\u7684\u4e3b\u8981\u9a71\u52a8\u56e0\u7d20\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5927\u91cf\u73b0\u6709\u7684\u6a21\u578b\u65e0\u6cd5\u5339\u914d\u6211\u4eec\u4f30\u8ba1\u7684\u53cd\u5e94\u7ed3\u679c\uff0c\u5e76\u6784\u5efa\u4e86\u4e00\u4e2a\u5177\u6709\u4e0d\u5b8c\u5168\u91d1\u878d\u5f00\u653e\u6027\u7684\u6a21\u578b\u6765\u89e3\u91ca\u8fd9\u4e9b\u73b0\u8c61\u3002\u5728\u6c47\u7387\u8d2c\u503c\u4e4b\u540e\uff0c\u672a\u8986\u76d6\u7684\u5229\u7387\u5e73\u4ef7\u504f\u5dee\u964d\u4f4e\u4e86\u4ece\u56fd\u5916\u501f\u6b3e\u7684\u6210\u672c\uff0c\u4ece\u800c\u523a\u6fc0\u4e86\u7ecf\u6d4e\u6d3b\u52a8\uff0c\u8fd9\u4e0e\u6570\u636e\u4e00\u81f4\u3002\u8be5\u6a21\u578b\u4e0e\uff08\u65e0\u6761\u4ef6\uff09\u6c47\u7387\u8131\u94a9\u73b0\u8c61\u4ee5\u53ca\u7a46\u8428\u4e8b\u5b9e\u76f8\u4e00\u81f4\uff0c\u5c3d\u7ba1\u6c47\u7387\u5bf9\u7ecf\u6d4e\u5177\u6709\u663e\u8457\u5f71\u54cd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.13506", "journal": "JF", "title": "Subtle Discrimination", "authors": ["ELENA S. PIKULINA", "DANIEL FERREIRA"], "author_details": [{"name": "ELENA S. PIKULINA", "affiliations": []}, {"name": "DANIEL FERREIRA", "affiliations": []}], "abstract": "ABSTRACT We introduce the concept of subtle discrimination \u2014biased acts that cannot be objectively ascertained as discriminatory. When candidates compete for promotions by investing in skills, firms' subtle biases induce discriminated candidates to overinvest when promotions are low\u2010stakes (to distinguish themselves from favored candidates) but underinvest in high\u2010stakes settings (anticipating low promotion probabilities). This asymmetry implies that subtle discrimination raises profits in low\u2010productivity firms but lowers them in high\u2010productivity firms. Although subtle biases are small, they generate large gaps in skills and promotion outcomes. We derive further predictions in contexts such as equity analysis, lending, fund flows, banking careers, and entrepreneurial finance.", "date": "2025-10-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.13506", "title_zh": "\u5fae\u5999\u7684\u6b67\u89c6", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5f15\u5165\u4e86\u201c\u5fae\u5999\u6b67\u89c6\u201d\u7684\u6982\u5ff5\u2014\u2014\u90a3\u4e9b\u65e0\u6cd5\u5ba2\u89c2\u8ba4\u5b9a\u4e3a\u6b67\u89c6\u6027\u7684\u504f\u89c1\u884c\u4e3a\u3002\u5f53\u5019\u9009\u4eba\u901a\u8fc7\u6295\u8d44\u6280\u80fd\u6765\u4e89\u53d6\u664b\u5347\u65f6\uff0c\u4f01\u4e1a\u4e2d\u7684\u5fae\u5999\u504f\u89c1\u4f1a\u5bfc\u81f4\u88ab\u6b67\u89c6\u7684\u5019\u9009\u4eba\uff0c\u5728\u664b\u5347\u98ce\u9669\u8f83\u4f4e\u7684\u60c5\u51b5\u4e0b\u8fc7\u5ea6\u6295\u8d44\uff08\u4ee5\u533a\u522b\u4e8e\u88ab\u504f\u7231\u7684\u5019\u9009\u4eba\uff09\uff0c\u800c\u5728\u9ad8\u98ce\u9669\u60c5\u5883\u4e0b\u5219\u51cf\u5c11\u6295\u8d44\uff08\u9884\u671f\u664b\u5347\u6982\u7387\u8f83\u4f4e\uff09\u3002\u8fd9\u79cd\u4e0d\u5bf9\u79f0\u6027\u610f\u5473\u7740\uff0c\u5fae\u5999\u6b67\u89c6\u4f1a\u63d0\u9ad8\u4f4e\u751f\u4ea7\u7387\u4f01\u4e1a\u7684\u5229\u6da6\uff0c\u4f46\u964d\u4f4e\u9ad8\u751f\u4ea7\u7387\u4f01\u4e1a\u7684\u5229\u6da6\u3002\u5c3d\u7ba1\u5fae\u5999\u504f\u89c1\u672c\u8eab\u5f88\u5c0f\uff0c\u5374\u4f1a\u5f15\u53d1\u6280\u80fd\u548c\u664b\u5347\u7ed3\u679c\u4e4b\u95f4\u5de8\u5927\u7684\u5dee\u8ddd\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u63a8\u5bfc\u4e86\u5728\u80a1\u6743\u5206\u6790\u3001\u8d37\u6b3e\u3001\u8d44\u91d1\u6d41\u52a8\u3001\u94f6\u884c\u4e1a\u52a1\u751f\u6daf\u4ee5\u53ca\u521b\u4e1a\u91d1\u878d\u7b49\u60c5\u5883\u4e0b\u7684\u9884\u6d4b\u7ed3\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u672c\u6d41\u52a8"]}, {"doi": "10.1111/jofi.13502", "journal": "JF", "title": "The Stock Market and Bank Risk\u2010Taking", "authors": ["ANTONIO FALATO", "DAVID SCHARFSTEIN"], "author_details": [{"name": "ANTONIO FALATO", "affiliations": []}, {"name": "DAVID SCHARFSTEIN", "affiliations": []}], "abstract": "ABSTRACT Using confidential supervisory risk ratings, we document that banks increase risk after going public compared to a control group of banks that filed to go public but withdrew their filings for plausibly exogenous reasons. The increase in risk improves short\u2010term performance at the expense of long\u2010term performance. We argue that the increase in risk stems from pressure to maximize short\u2010term stock prices and earnings once the bank is publicly traded. After going public, banks owned by investors that place greater value on short\u2010term performance increase risk more, and those managed by CEOs with more short\u2010term compensation also increase risk more.", "date": "2025-10-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.13502", "title_zh": "\u80a1\u7968\u5e02\u573a\u4e0e\u94f6\u884c\u98ce\u9669\u627f\u62c5", "abstract_zh": "\u4f7f\u7528\u4fdd\u5bc6\u7684\u76d1\u7ba1\u98ce\u9669\u8bc4\u7ea7\uff0c\u6211\u4eec\u53d1\u73b0\u94f6\u884c\u5728\u4e0a\u5e02\u540e\u76f8\u6bd4\u4e00\u7ec4\u539f\u672c\u7533\u8bf7\u4e0a\u5e02\u4f46\u56e0\u53ef\u80fd\u7684\u5916\u751f\u539f\u56e0\u64a4\u56de\u7533\u8bf7\u7684\u94f6\u884c\uff0c\u98ce\u9669\u6c34\u5e73\u663e\u8457\u4e0a\u5347\u3002\u8fd9\u79cd\u98ce\u9669\u4e0a\u5347\u867d\u7136\u63d0\u5347\u4e86\u77ed\u671f\u8868\u73b0\uff0c\u5374\u635f\u5bb3\u4e86\u957f\u671f\u8868\u73b0\u3002\u6211\u4eec\u8ba4\u4e3a\uff0c\u8fd9\u79cd\u98ce\u9669\u4e0a\u5347\u6e90\u4e8e\u94f6\u884c\u4e0a\u5e02\u540e\u4e3a\u6700\u5927\u5316\u80a1\u4ef7\u548c\u76c8\u5229\u7684\u77ed\u671f\u8868\u73b0\u800c\u53d7\u5230\u7684\u538b\u529b\u3002\u5728\u4e0a\u5e02\u540e\uff0c\u90a3\u4e9b\u80a1\u4e1c\u66f4\u91cd\u89c6\u77ed\u671f\u8868\u73b0\u7684\u94f6\u884c\u589e\u52a0\u98ce\u9669\u7684\u7a0b\u5ea6\u66f4\u5927\uff0c\u800c\u7531\u62e5\u6709\u66f4\u591a\u77ed\u671f\u85aa\u916c\u7684CEO\u7ba1\u7406\u7684\u94f6\u884c\u4e5f\u8868\u73b0\u51fa\u66f4\u5927\u7684\u98ce\u9669\u4e0a\u5347\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1111/jofi.13503", "journal": "JF", "title": "Going for Broke: Bank Reputation and the Performance of Opaque Securities", "authors": ["ABE DE JONG", "TIM KOOIJMANS", "PETER KOUDIJS"], "author_details": [{"name": "ABE DE JONG", "affiliations": []}, {"name": "TIM KOOIJMANS", "affiliations": []}, {"name": "PETER KOUDIJS", "affiliations": []}], "abstract": "ABSTRACT Can banks\u2019 reputational concerns improve the quality of opaque, off\u2010balance sheet securities, such as mortgage\u2010backed securities? We study this question in a uniquely parsimonious setting. In the 1760s, Dutch banking partnerships securitized West\u2010Indian plantation mortgages that were risky and opaque. High\u2010reputation banks originated better mortgages and issued securities that, on average, retained 17.5% more of their value during a market collapse. Reputational effects are attenuated when the managing partners were married into wealth or received a large share of profits in the short term, suggesting that bank reputation only works if bankers are personally exposed to (long\u2010run) reputational losses.", "date": "2025-10-06", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1111/jofi.13503", "title_zh": "\u94e4\u800c\u8d70\u9669\uff1a\u94f6\u884c\u58f0\u8a89\u4e0e\u975e\u6d41\u52a8\u6027\u8bc1\u5238\u7684\u8868\u73b0", "abstract_zh": "\u6458\u8981 \u94f6\u884c\u7684\u58f0\u8a89\u62c5\u5fe7\u662f\u5426\u80fd\u63d0\u5347\u98ce\u9669\u9ad8\u4e14\u4fe1\u606f\u4e0d\u900f\u660e\u7684\u79bb\u8868\u8bc1\u5238\uff08\u5982\u62b5\u62bc\u8d37\u6b3e\u652f\u6301\u8bc1\u5238\uff09\u7684\u8d28\u91cf\uff1f\u6211\u4eec\u5728\u4e00\u4e2a\u72ec\u7279\u4e14\u7b80\u6d01\u7684\u8bbe\u5b9a\u4e2d\u7814\u7a76\u4e86\u8fd9\u4e00\u95ee\u9898\u30021760\u5e74\u4ee3\uff0c\u8377\u5170\u94f6\u884c\u5408\u4f19\u4f01\u4e1a\u5c06\u897f\u5370\u5ea6\u79cd\u690d\u56ed\u62b5\u62bc\u8d37\u6b3e\u8fdb\u884c\u4e86\u8bc1\u5238\u5316\uff0c\u8fd9\u4e9b\u8d37\u6b3e\u5177\u6709\u9ad8\u98ce\u9669\u548c\u4fe1\u606f\u4e0d\u900f\u660e\u6027\u3002\u58f0\u8a89\u8f83\u9ad8\u7684\u94f6\u884c\u53d1\u884c\u4e86\u8d28\u91cf\u66f4\u597d\u7684\u62b5\u62bc\u8d37\u6b3e\uff0c\u5e76\u5728\u5e02\u573a\u5d29\u6e83\u671f\u95f4\uff0c\u5176\u53d1\u884c\u7684\u8bc1\u5238\u5e73\u5747\u4fdd\u7559\u4e8617.5%\u7684\u5e02\u503c\u3002\u5f53\u7ba1\u7406\u5408\u4f19\u4eba\u4e0e\u5bcc\u4eba\u901a\u5a5a\u6216\u5728\u77ed\u671f\u5185\u83b7\u5f97\u5927\u91cf\u5229\u6da6\u65f6\uff0c\u58f0\u8a89\u6548\u5e94\u4f1a\u51cf\u5f31\uff0c\u8fd9\u8868\u660e\u94f6\u884c\u58f0\u8a89\u53ea\u6709\u5728\u94f6\u884c\u5bb6\u4e2a\u4eba\u9762\u4e34\uff08\u957f\u671f\uff09\u58f0\u8a89\u635f\u5931\u65f6\u624d\u80fd\u53d1\u6325\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf046", "journal": "QJE", "title": "Vanguard: Black Veterans and Civil Rights After World War I", "authors": ["Desmond Ang", "Sahil Chinoy"], "author_details": [{"name": "Desmond Ang", "affiliations": ["Harvard University ,"]}, {"name": "Sahil Chinoy", "affiliations": ["Harvard University ,"]}], "abstract": "Abstract Nearly 400,000 Black men were drafted into the National Army during World War I, where they toiled primarily as menial laborers in segregated units. Leveraging novel variation from the World War I draft lottery and millions of digitized military and NAACP records, we document the pioneering role these men played in the early civil rights movement. Relative to observably similar individuals from the same draft board, Black men randomly inducted into the Army were significantly more likely to join the nascent NAACP and become prominent community leaders in the New Negro era. We find little evidence that these effects are explained by migration or improved socioeconomic status. Rather, corroborating historical accounts about the catalyzing influence of institutional racism in the military, we show that increased civic activism was driven by soldiers who experienced the most discriminatory treatment while serving their country.", "date": "2025-09-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf046", "title_zh": "\u5148\u950b\uff1a\u4e00\u6218\u671f\u95f4\u7684\u975e\u88d4\u8001\u5175\u4e0e\u6c11\u6743\u8fd0\u52a8", "abstract_zh": "\u6458\u8981 \u5728\u7b2c\u4e00\u6b21\u4e16\u754c\u5927\u6218\u671f\u95f4\uff0c\u8fd140\u4e07\u975e\u88d4\u7537\u6027\u88ab\u5f81\u53ec\u8fdb\u5165\u56fd\u6c11\u519b\uff0c\u4ed6\u4eec\u5728\u88ab\u9694\u79bb\u7684\u90e8\u961f\u4e2d\u4e3b\u8981\u62c5\u4efb\u4f4e\u7ea7\u4f53\u529b\u52b3\u52a8\u5de5\u4f5c\u3002\u6211\u4eec\u5229\u7528\u7b2c\u4e00\u6b21\u4e16\u754c\u5927\u6218\u5f81\u5175\u62bd\u7b7e\u7684\u65b0\u578b\u53d8\u5f02\u6570\u636e\uff0c\u4ee5\u53ca\u6570\u767e\u4e07\u4efd\u6570\u5b57\u5316\u7684\u519b\u4e8b\u8bb0\u5f55\u548c\u5168\u56fd\u975e\u88d4\u7f8e\u56fd\u4eba\u534f\u4f1a\uff08NAACP\uff09\u6863\u6848\uff0c\u63ed\u793a\u4e86\u8fd9\u4e9b\u7537\u6027\u5728\u65e9\u671f\u6c11\u6743\u8fd0\u52a8\u4e2d\u7684\u5f00\u521b\u6027\u4f5c\u7528\u3002\u4e0e\u6765\u81ea\u540c\u4e00\u5f81\u5175\u529e\u516c\u5ba4\u7684\u53ef\u89c2\u5bdf\u5230\u7684\u76f8\u4f3c\u4e2a\u4f53\u76f8\u6bd4\uff0c\u88ab\u968f\u673a\u5f81\u53ec\u5165\u4f0d\u7684\u975e\u88d4\u7537\u6027\u663e\u8457\u66f4\u6709\u53ef\u80fd\u52a0\u5165\u65b0\u5174\u7684NAACP\uff0c\u5e76\u5728\u201c\u65b0\u9ed1\u4eba\u201d\u65f6\u4ee3\u6210\u4e3a\u793e\u533a\u4e2d\u7684\u91cd\u8981\u9886\u5bfc\u8005\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u4e9b\u6548\u5e94\u4e0d\u592a\u53ef\u80fd\u662f\u7531\u8fc1\u79fb\u6216\u7ecf\u6d4e\u72b6\u51b5\u6539\u5584\u6240\u89e3\u91ca\u3002\u76f8\u53cd\uff0c\u8fd9\u4e0e\u5386\u53f2\u8bb0\u8f7d\u4e2d\u5173\u4e8e\u519b\u4e8b\u673a\u6784\u79cd\u65cf\u6b67\u89c6\u5177\u6709\u50ac\u5316\u4f5c\u7528\u7684\u8bf4\u6cd5\u76f8\u543b\u5408\uff0c\u8868\u660e\u90a3\u4e9b\u5728\u670d\u5f79\u671f\u95f4\u906d\u53d7\u6700\u4e25\u91cd\u6b67\u89c6\u7684\u58eb\u5175\uff0c\u5176\u516c\u6c11\u53c2\u4e0e\u5ea6\u663e\u8457\u63d0\u9ad8\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf043", "journal": "QJE", "title": "Dollar Dominance and the Transmission of Monetary Policy", "authors": ["Michael McLeay", "Silvana Tenreyro"], "author_details": [{"name": "Michael McLeay", "affiliations": ["Bank of England ,"]}, {"name": "Silvana Tenreyro", "affiliations": ["London School of Economics ,"]}], "abstract": "Abstract Has the dominance of the dollar in global trade rendered monetary policy ineffective? An emerging view contends that if a country invoices its exports in dollars, exchange rates cannot stabilize economic activity, as the classical expenditure-switching channel is muted. This view rests on the premise that export prices are sticky in dollars, breaking the link between export demand and depreciations. But this assumption is not borne out by the data: goods priced in dollars tend to have more flexible prices, along with higher elasticities of substitution. We propose a model with more realistic assumptions and show that even with dollar pricing, depreciating the currency by loosening monetary policy can still boost exports and activity materially. The limit to any expansion is not demand, but supply capacity. We also show that low exchange rate pass-through to dollar prices is not informative about price stickiness. The price response to exchange rates is small when demand elasticities are high, even with flexible prices: low pass-through is an equilibrium result, not evidence of a nominal friction.", "date": "2025-09-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf043", "title_zh": "\u7f8e\u5143\u4e3b\u5bfc\u4e0e\u8d27\u5e01\u653f\u7b56\u7684\u4f20\u5bfc", "abstract_zh": "\u7f8e\u5143\u5728\u56fd\u9645\u8d38\u6613\u4e2d\u7684\u4e3b\u5bfc\u5730\u4f4d\u662f\u5426\u4f7f\u8d27\u5e01\u653f\u7b56\u5931\u6548\uff1f\u4e00\u79cd\u65b0\u5174\u89c2\u70b9\u8ba4\u4e3a\uff0c\u5982\u679c\u4e00\u56fd\u4ee5\u7f8e\u5143\u8ba1\u4ef7\u5176\u51fa\u53e3\uff0c\u6c47\u7387\u65e0\u6cd5\u7a33\u5b9a\u7ecf\u6d4e\u6d3b\u52a8\uff0c\u56e0\u4e3a\u7ecf\u5178\u7684\u652f\u51fa\u8f6c\u6362\u6e20\u9053\u88ab\u524a\u5f31\u3002\u8fd9\u4e00\u89c2\u70b9\u57fa\u4e8e\u51fa\u53e3\u4ef7\u683c\u4ee5\u7f8e\u5143\u8ba1\u4ef7\u4e14\u5177\u6709\u7c98\u6027\u7684\u5047\u8bbe\uff0c\u4ece\u800c\u5207\u65ad\u4e86\u51fa\u53e3\u9700\u6c42\u4e0e\u8d2c\u503c\u4e4b\u95f4\u7684\u8054\u7cfb\u3002\u4f46\u8fd9\u4e00\u5047\u8bbe\u5e76\u672a\u5f97\u5230\u6570\u636e\u652f\u6301\uff1a\u4ee5\u7f8e\u5143\u8ba1\u4ef7\u7684\u5546\u54c1\u5f80\u5f80\u5177\u6709\u66f4\u7075\u6d3b\u7684\u4ef7\u683c\uff0c\u4ee5\u53ca\u66f4\u9ad8\u7684\u66ff\u4ee3\u5f39\u6027\u3002\u6211\u4eec\u63d0\u51fa\u4e00\u4e2a\u66f4\u5177\u73b0\u5b9e\u6027\u7684\u6a21\u578b\uff0c\u8868\u660e\u5373\u4f7f\u5728\u4ee5\u7f8e\u5143\u8ba1\u4ef7\u7684\u60c5\u51b5\u4e0b\uff0c\u901a\u8fc7\u5bbd\u677e\u8d27\u5e01\u653f\u7b56\u8d2c\u503c\u8d27\u5e01\u4ecd\u80fd\u663e\u8457\u63d0\u5347\u51fa\u53e3\u548c\u7ecf\u6d4e\u6d3b\u52a8\u3002\u6269\u5f20\u7684\u6781\u9650\u5e76\u975e\u9700\u6c42\uff0c\u800c\u662f\u4f9b\u7ed9\u80fd\u529b\u3002\u6211\u4eec\u8fd8\u8868\u660e\uff0c\u7f8e\u5143\u4ef7\u683c\u5bf9\u6c47\u7387\u7684\u4f20\u5bfc\u7387\u8f83\u4f4e\uff0c\u5e76\u4e0d\u80fd\u53cd\u6620\u4ef7\u683c\u7c98\u6027\u3002\u5f53\u9700\u6c42\u5f39\u6027\u8f83\u9ad8\u65f6\uff0c\u5373\u4f7f\u4ef7\u683c\u662f\u7075\u6d3b\u7684\uff0c\u6c47\u7387\u5bf9\u4ef7\u683c\u7684\u5f71\u54cd\u4e5f\u8f83\u5c0f\uff1a\u4f4e\u4f20\u5bfc\u7387\u662f\u5747\u8861\u7ed3\u679c\uff0c\u800c\u975e\u540d\u4e49\u6469\u64e6\u7684\u8bc1\u636e\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf044", "journal": "QJE", "title": "Failing Banks", "authors": ["Sergio Correia", "Stephan Luck", "Emil Verner"], "author_details": [{"name": "Sergio Correia", "affiliations": ["Federal Reserve Bank of Richmond ,"]}, {"name": "Stephan Luck", "affiliations": ["Federal Reserve Bank of New York ,"]}, {"name": "Emil Verner", "affiliations": ["MIT Sloan School of Management ,"]}], "abstract": "Abstract Why do banks fail? We create a panel covering most commercial banks from 1863 through 2024 to study the history of failing banks in the United States. Failing banks are characterized by rising asset losses, deteriorating solvency, and an increasing reliance on expensive noncore funding. These commonalities imply that bank failures are highly predictable using simple accounting metrics from publicly available financial statements. Failures with runs were common before deposit insurance, but these failures are strongly related to weak fundamentals, casting doubt on the importance of non-fundamental runs. Furthermore, low recovery rates on failed banks\u2019 assets suggest that most failed banks subject to runs were fundamentally insolvent, barring large value destruction of receiverships. Altogether, our evidence suggests that the primary cause of bank failures and banking crises is almost always and everywhere a deterioration of bank fundamentals.", "date": "2025-09-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf044", "title_zh": "\u5012\u95ed\u94f6\u884c", "abstract_zh": "\u4e3a\u4ec0\u4e48\u94f6\u884c\u4f1a\u5012\u95ed\uff1f\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u8986\u76d61863\u5e74\u81f32024\u5e74\u7f8e\u56fd\u5927\u591a\u6570\u5546\u4e1a\u94f6\u884c\u7684\u9762\u677f\u6570\u636e\uff0c\u4ee5\u7814\u7a76\u7f8e\u56fd\u5386\u53f2\u4e0a\u94f6\u884c\u5012\u95ed\u7684\u89c4\u5f8b\u3002\u5012\u95ed\u94f6\u884c\u901a\u5e38\u8868\u73b0\u4e3a\u8d44\u4ea7\u635f\u5931\u4e0a\u5347\u3001\u507f\u4ed8\u80fd\u529b\u6076\u5316\u4ee5\u53ca\u5bf9\u6602\u8d35\u7684\u975e\u6838\u5fc3\u8d44\u91d1\u6765\u6e90\u7684\u4f9d\u8d56\u52a0\u5267\u3002\u8fd9\u4e9b\u5171\u540c\u7279\u5f81\u8868\u660e\uff0c\u94f6\u884c\u5012\u95ed\u53ef\u4ee5\u901a\u8fc7\u7b80\u5355\u4e14\u57fa\u4e8e\u516c\u5f00\u8d22\u52a1\u62a5\u8868\u7684\u4f1a\u8ba1\u6307\u6807\u8fdb\u884c\u9ad8\u5ea6\u9884\u6d4b\u3002\u5728\u5b58\u6b3e\u4fdd\u9669\u5236\u5ea6\u5efa\u7acb\u4e4b\u524d\uff0c\u94f6\u884c\u6324\u5151\u4e8b\u4ef6\u8f83\u4e3a\u666e\u904d\uff0c\u4f46\u8fd9\u4e9b\u4e8b\u4ef6\u4e0e\u57fa\u672c\u9762\u8584\u5f31\u5bc6\u5207\u76f8\u5173\uff0c\u8d28\u7591\u4e86\u975e\u57fa\u672c\u9762\u56e0\u7d20\u5728\u6324\u5151\u4e2d\u7684\u91cd\u8981\u6027\u3002\u6b64\u5916\uff0c\u5012\u95ed\u94f6\u884c\u8d44\u4ea7\u7684\u56de\u6536\u7387\u666e\u904d\u8f83\u4f4e\uff0c\u8868\u660e\u5927\u591a\u6570\u53d1\u751f\u6324\u5151\u7684\u94f6\u884c\u5b9e\u9645\u4e0a\u5df2\u57fa\u672c\u9762\u4e8f\u635f\uff0c\u4ece\u800c\u6392\u9664\u4e86\u63a5\u6536\u673a\u6784\u9020\u6210\u5de8\u5927\u4ef7\u503c\u635f\u5931\u7684\u53ef\u80fd\u6027\u3002\u7efc\u4e0a\u6240\u8ff0\uff0c\u6211\u4eec\u7684\u8bc1\u636e\u8868\u660e\uff0c\u94f6\u884c\u5012\u95ed\u548c\u94f6\u884c\u5371\u673a\u7684\u4e3b\u8981\u539f\u56e0\u51e0\u4e4e\u603b\u662f\u4e14\u5728\u4e16\u754c\u5404\u5730\u90fd\u6e90\u4e8e\u94f6\u884c\u57fa\u672c\u9762\u7684\u6076\u5316\u3002", "translation_source": "journal-qwen4b", "topics": ["\u6781\u7aef\u98ce\u9669"]}, {"doi": "10.1093/qje/qjaf045", "journal": "QJE", "title": "Political Foundations of Racial Violence in the Post-Reconstruction South", "authors": ["Patrick A Testa", "Jhacova Williams"], "author_details": [{"name": "Patrick A Testa", "affiliations": ["Tulane University and National Bureau of Economic Research ,"]}, {"name": "Jhacova Williams", "affiliations": ["American University ,"]}], "abstract": "Abstract Election results act as powerful signals, shaping social behavior in ways that can be dramatic and even violent. This article shows how racial violence in the post-Reconstruction U.S. South was tied to the local performance of the anti-Black Democratic Party in presidential elections. Using a regression discontinuity design based on close presidential vote shares, we find that Southern counties where Democrats lost the popular vote between 1880 and 1900 were nearly twice as likely to experience Black lynchings in the following four years. Despite no corresponding changes in local office holding, these defeats were salient among local elites. We show that Southern newspapers, closely aligned with the Democratic Party, amplified narratives of Black criminality in the aftermath of Democratic losses. Such accusations were, in turn, frequently invoked by lynch mobs. These findings point to the strategic use of racial violence by Democratic elites, foreshadowing the institutionalized vote suppression of Jim Crow.", "date": "2025-09-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf045", "title_zh": "\u91cd\u5efa\u540e\u5357\u65b9\u79cd\u65cf\u66b4\u529b\u7684\u653f\u6cbb\u6839\u6e90", "abstract_zh": "\u9009\u4e3e\u7ed3\u679c\u4f5c\u4e3a\u5f3a\u6709\u529b\u7684\u4fe1\u53f7\uff0c\u80fd\u591f\u4ee5\u620f\u5267\u6027\u751a\u81f3\u66b4\u529b\u7684\u65b9\u5f0f\u5f71\u54cd\u793e\u4f1a\u884c\u4e3a\u3002\u672c\u6587\u8868\u660e\uff0c\u91cd\u5efa\u540e\u7f8e\u56fd\u5357\u65b9\u7684\u79cd\u65cf\u66b4\u529b\u4e0e\u53cd\u9ed1\u4eba\u6c11\u4e3b\u515a\u5728\u603b\u7edf\u9009\u4e3e\u4e2d\u7684\u5730\u65b9\u8868\u73b0\u5bc6\u5207\u76f8\u5173\u3002\u57fa\u4e8e\u603b\u7edf\u9009\u4e3e\u5f97\u7968\u7387\u7684\u56de\u5f52\u65ad\u70b9\u8bbe\u8ba1\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u57281880\u5e74\u81f31900\u5e74\u95f4\uff0c\u6c11\u4e3b\u515a\u5728\u5357\u65b9\u53bf\u4efd\u4e2d\u5931\u53bb\u666e\u9009\u7968\u7684\u5730\u533a\uff0c\u5728\u63a5\u4e0b\u6765\u7684\u56db\u5e74\u91cc\u53d1\u751f\u9ed1\u4eba\u88ab\u7ede\u6740\u4e8b\u4ef6\u7684\u6982\u7387\u51e0\u4e4e\u9ad8\u51fa\u4e00\u500d\u3002\u5c3d\u7ba1\u8fd9\u4e9b\u5730\u533a\u5e76\u672a\u51fa\u73b0\u5730\u65b9\u5b98\u5458\u66f4\u66ff\uff0c\u4f46\u8fd9\u4e9b\u5931\u5229\u5728\u5730\u65b9\u7cbe\u82f1\u4e2d\u5177\u6709\u663e\u8457\u5f71\u54cd\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u4e0e\u6c11\u4e3b\u515a\u5bc6\u5207\u76f8\u5173\u7684\u5357\u65b9\u62a5\u7eb8\u5728\u6c11\u4e3b\u515a\u5931\u5229\u540e\uff0c\u4f1a\u5f3a\u5316\u5173\u4e8e\u9ed1\u4eba\u72af\u7f6a\u7684\u53d9\u4e8b\u3002\u8fd9\u4e9b\u6307\u63a7\u968f\u540e\u7ecf\u5e38\u88ab\u7ede\u6740\u66b4\u5f92\u5f15\u7528\u3002\u8fd9\u4e9b\u53d1\u73b0\u63ed\u793a\u4e86\u6c11\u4e3b\u515a\u7cbe\u82f1\u6218\u7565\u6027\u4f7f\u7528\u79cd\u65cf\u66b4\u529b\u7684\u884c\u4e3a\uff0c\u9884\u793a\u4e86\u5409\u59c6\u00b7\u514b\u52b3\u5236\u5ea6\u4e0b\u7cfb\u7edf\u6027\u7684\u9009\u6c11\u538b\u5236\u7684\u51fa\u73b0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf042", "journal": "QJE", "title": "Ideas Have Consequences: The Impact of Law and Economics on American Justice", "authors": ["Elliott Ash", "Daniel L Chen", "Suresh Naidu"], "author_details": [{"name": "Elliott Ash", "affiliations": ["ETH Zurich ,"]}, {"name": "Daniel L Chen", "affiliations": ["Toulouse School of Economics ,"]}, {"name": "Suresh Naidu", "affiliations": ["Columbia University ,"]}], "abstract": "Abstract This article empirically studies the effects of the early law and economics movement on the U.S. judiciary. We focus on the Manne Economics Institute for Federal Judges, an intensive economics course that trained almost half of federal judges between 1976 and 1999. Using the universe of published opinions in U.S. Circuit Courts and 1 million District Court criminal sentencing decisions, we estimate the within-judge effect of Manne program attendance. Selection into attendance was limited, as the program was popular among judges of all backgrounds, frequently oversubscribed, and admitted participants on a first-come, first-served basis. We find that after attending economics training, participating judges use more economics language in their opinions, rule against regulatory agencies more often, and impose more severe criminal sentences. We argue that economics, as a rigorous social science, was especially effective in persuading judges.", "date": "2025-08-26", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf042", "title_zh": "\u601d\u60f3\u6709\u540e\u679c\uff1a\u6cd5\u5f8b\u4e0e\u7ecf\u6d4e\u5b66\u5bf9\u7f8e\u56fd\u53f8\u6cd5\u7684\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u901a\u8fc7\u5b9e\u8bc1\u7814\u7a76\u63a2\u8ba8\u4e86\u65e9\u671f\u6cd5\u5f8b\u4e0e\u7ecf\u6d4e\u5b66\u8fd0\u52a8\u5bf9\u7f8e\u56fd\u53f8\u6cd5\u4f53\u7cfb\u7684\u5f71\u54cd\u3002\u6211\u4eec\u805a\u7126\u4e8e\u66fc\u5c3c\u8054\u90a6\u6cd5\u5b98\u7ecf\u6d4e\u5b66\u7814\u7a76\u6240\uff0c\u8fd9\u662f\u4e00\u4e2a\u4e3a\u8054\u90a6\u6cd5\u5b98\u63d0\u4f9b\u5bc6\u96c6\u7ecf\u6d4e\u5b66\u57f9\u8bad\u7684\u9879\u76ee\uff0c\u8be5\u9879\u76ee\u57281976\u5e74\u81f31999\u5e74\u95f4\u57f9\u8bad\u4e86\u8fd1\u4e00\u534a\u7684\u8054\u90a6\u6cd5\u5b98\u3002\u5229\u7528\u7f8e\u56fd\u4e0a\u8bc9\u6cd5\u9662\u53d1\u5e03\u7684\u5224\u51b3\u610f\u89c1\u4ee5\u53ca100\u4e07\u4efd\u5730\u533a\u6cd5\u9662\u5211\u4e8b\u91cf\u5211\u51b3\u5b9a\u7684\u5b8c\u6574\u6570\u636e\u96c6\uff0c\u6211\u4eec\u4f30\u8ba1\u4e86\u6cd5\u5b98\u53c2\u52a0\u66fc\u5c3c\u9879\u76ee\u57f9\u8bad\u540e\u7684\u5185\u90e8\u6548\u5e94\u3002\u7531\u4e8e\u8be5\u9879\u76ee\u5728\u4e0d\u540c\u80cc\u666f\u7684\u6cd5\u5b98\u4e2d\u90fd\u5341\u5206\u53d7\u6b22\u8fce\uff0c\u7ecf\u5e38\u51fa\u73b0\u62a5\u540d\u4eba\u6570\u8d85\u8fc7\u540d\u989d\u7684\u60c5\u51b5\uff0c\u4e14\u91c7\u7528\u5148\u5230\u5148\u5f97\u7684\u5f55\u53d6\u65b9\u5f0f\uff0c\u56e0\u6b64\u5165\u9009\u5177\u6709\u4e00\u5b9a\u7684\u9650\u5236\u6027\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u53c2\u52a0\u7ecf\u6d4e\u5b66\u57f9\u8bad\u540e\uff0c\u53c2\u4e0e\u7684\u6cd5\u5b98\u5728\u5176\u5224\u51b3\u610f\u89c1\u4e2d\u4f7f\u7528\u66f4\u591a\u7ecf\u6d4e\u5b66\u672f\u8bed\uff0c\u66f4\u9891\u7e41\u5730\u53cd\u5bf9\u76d1\u7ba1\u673a\u6784\u7684\u88c1\u51b3\uff0c\u5e76\u5bf9\u5211\u4e8b\u7f6a\u72af\u65bd\u52a0\u66f4\u4e25\u5389\u7684\u91cf\u5211\u3002\u6211\u4eec\u8ba4\u4e3a\uff0c\u4f5c\u4e3a\u4e00\u95e8\u4e25\u8c28\u7684\u793e\u4f1a\u79d1\u5b66\uff0c\u7ecf\u6d4e\u5b66\u5728\u8bf4\u670d\u6cd5\u5b98\u65b9\u9762\u5c24\u5176\u6709\u6548\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf032", "journal": "QJE", "title": "Aggregation and the Estimation of Quality Change: Application to U.S. Import Prices", "authors": ["Marco Errico", "Danial Lashkari"], "author_details": [{"name": "Marco Errico", "affiliations": ["Bank of Italy ,"]}, {"name": "Danial Lashkari", "affiliations": ["Federal Reserve Bank of New York ,"]}], "abstract": "Abstract We characterize the contribution of changes in quality, price, and variety entry/exit to the aggregate price index for smooth, invertible demand systems, generalizing the standard results derived in the CES case. The results require the knowledge of heterogeneous cross-product elasticities of substitution. To apply them in practice, we also show how to identify rich demand systems using data only on prices and market shares, without the need for external cost-shock instruments or strong assumptions on the covariance between supply and demand shocks. Using this approach, we compute the U.S. import price index based on the Kimball demand system. We find that quality change on average lowered the inflation in import prices by around 0.007 log points annually (1989\u20132016). To further validate our approach, we show that it estimates price elasticities and quality changes similar to those found by the standard mixed logit (BLP) demand in data on the U.S. auto market.", "date": "2025-08-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf032", "title_zh": "\u8d28\u91cf\u53d8\u5316\u7684\u805a\u5408\u4e0e\u4f30\u8ba1\uff1a\u7f8e\u56fd\u8fdb\u53e3\u4ef7\u683c\u7684\u5e94\u7528", "abstract_zh": "\u6211\u4eec\u523b\u753b\u4e86\u8d28\u91cf\u3001\u4ef7\u683c\u4ee5\u53ca\u4ea7\u54c1\u79cd\u7c7b\u8fdb\u5165/\u9000\u51fa\u53d8\u5316\u5bf9\u5e73\u6ed1\u4e14\u53ef\u9006\u9700\u6c42\u7cfb\u7edf\u4e2d\u603b\u4f53\u4ef7\u683c\u6307\u6570\u7684\u8d21\u732e\uff0c\u63a8\u5e7f\u4e86\u5728CES\u6a21\u578b\u4e2d\u5f97\u51fa\u7684\u6807\u51c6\u7ed3\u679c\u3002\u8fd9\u4e9b\u7ed3\u679c\u9700\u8981\u4e86\u89e3\u4e0d\u540c\u4ea7\u54c1\u4e4b\u95f4\u7684\u5f02\u8d28\u6027\u66ff\u4ee3\u5f39\u6027\u3002\u4e3a\u4e86\u5728\u5b9e\u8df5\u4e2d\u5e94\u7528\uff0c\u6211\u4eec\u8fd8\u5c55\u793a\u4e86\u5982\u4f55\u4ec5\u5229\u7528\u4ef7\u683c\u548c\u5e02\u573a\u4efd\u989d\u6570\u636e\uff0c\u8bc6\u522b\u51fa\u4e30\u5bcc\u7684\u9700\u6c42\u7cfb\u7edf\uff0c\u800c\u65e0\u9700\u5916\u90e8\u6210\u672c\u51b2\u51fb\u5de5\u5177\u6216\u5bf9\u4f9b\u7ed9\u4e0e\u9700\u6c42\u51b2\u51fb\u534f\u65b9\u5dee\u7684\u5f3a\u5047\u8bbe\u3002\u91c7\u7528\u8fd9\u79cd\u65b9\u6cd5\uff0c\u6211\u4eec\u57fa\u4e8eKimball\u9700\u6c42\u7cfb\u7edf\u8ba1\u7b97\u4e86\u7f8e\u56fd\u8fdb\u53e3\u4ef7\u683c\u6307\u6570\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u5e73\u5747\u800c\u8a00\uff0c\u8d28\u91cf\u53d8\u5316\u6bcf\u5e74\u4f7f\u8fdb\u53e3\u4ef7\u683c\u7684\u901a\u80c0\u964d\u4f4e\u4e86\u7ea60.007\u4e2a\u5bf9\u6570\u70b9\uff081989\u20132016\u5e74\uff09\u3002\u4e3a\u8fdb\u4e00\u6b65\u9a8c\u8bc1\u6211\u4eec\u7684\u65b9\u6cd5\uff0c\u6211\u4eec\u8868\u660e\uff0c\u8be5\u65b9\u6cd5\u5728\u4f30\u7b97\u7f8e\u56fd\u6c7d\u8f66\u5e02\u573a\u7684\u4ef7\u683c\u5f39\u6027\u4e0e\u8d28\u91cf\u53d8\u5316\u65f6\uff0c\u7ed3\u679c\u4e0e\u6807\u51c6\u6df7\u5408\u903b\u8f91\uff08BLP\uff09\u9700\u6c42\u7cfb\u7edf\u6240\u5f97\u5230\u7684\u7ed3\u679c\u76f8\u4f3c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf041", "journal": "QJE", "title": "Traditional Institutions in Modern Times: Dowries as Pensions When Sons Migrate", "authors": ["Natalie Bau", "Gaurav Khanna", "Corinne Low", "Alessandra Voena"], "author_details": [{"name": "Natalie Bau", "affiliations": ["University of California, Los Angeles, National Bureau of Economic Research, and Bureau for Research and Economic Analysis of Development, United States, Centre for Economic Policy and Research ,"]}, {"name": "Gaurav Khanna", "affiliations": ["University of California, San Diego ,"]}, {"name": "Corinne Low", "affiliations": ["University of Pennsylvania and National Bureau of Economic Research ,"]}, {"name": "Alessandra Voena", "affiliations": ["Stanford University, National Bureau of Economic Research, Stanford Institute for Economic Policy Research, and Bureau for Research and Economic Analysis of Development, United States, Centre for Economic Policy and Research, United Kingdom, Center for Household, Income, Labour and Demographic Economics ,"]}], "abstract": "Abstract This paper uses newly collected data on the allocation of dowry to examine its role in resolving intergenerational frictions around migration in India. Migration disrupts traditional elderly support structures, in which sons live near their parents and care for them in old age. We develop a model in which dowry can promote migration by allowing sons to make upfront transfers to their parents and ease constraints on income sharing. To test this hypothesis, we collect two new data sets that measure the distribution of dowry between family members. We document for the first time that net transfers of dowry to a man\u2019s parents are common but far from universal. Consistent with using dowry for income sharing, such transfers occur more often when sons migrate, especially when they work in higher-earning occupations. In nationally representative data, migration rates are higher in areas with stronger historical dowry traditions. Finally, exploiting a large-scale highway construction program, we show that men from areas with stronger historical dowry traditions migrate more when migration costs fall. Our findings provide some clues as to why dowry persists despite its well-documented adverse consequences.", "date": "2025-08-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf041", "title_zh": "\u73b0\u4ee3\u65f6\u4ee3\u7684\u4f20\u7edf\u5236\u5ea6\uff1a\u513f\u5b50\u8fc1\u79fb\u65f6\u7684\u8058\u793c\u4f5c\u4e3a\u517b\u8001\u91d1", "abstract_zh": "\u672c\u6587\u5229\u7528\u65b0\u6536\u96c6\u7684\u5173\u4e8e\u8058\u793c\u5206\u914d\u7684\u6570\u636e\uff0c\u8003\u5bdf\u5176\u5728\u5370\u5ea6\u513f\u5b50\u8fc1\u79fb\u80cc\u666f\u4e0b\u89e3\u51b3\u4ee3\u9645\u6469\u64e6\u4e2d\u7684\u4f5c\u7528\u3002\u8fc1\u79fb\u7834\u574f\u4e86\u4f20\u7edf\u7684\u8001\u5e74\u652f\u6301\u7ed3\u6784\uff0c\u5373\u513f\u5b50\u4e0e\u7236\u6bcd\u540c\u4f4f\u5e76\u4e3a\u5176\u517b\u8001\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6a21\u578b\uff0c\u5176\u4e2d\u8058\u793c\u53ef\u4ee5\u901a\u8fc7\u5141\u8bb8\u513f\u5b50\u5411\u7236\u6bcd\u63d0\u524d\u652f\u4ed8\u6b3e\u9879\uff0c\u7f13\u89e3\u6536\u5165\u5171\u4eab\u7684\u7ea6\u675f\uff0c\u4ece\u800c\u4fc3\u8fdb\u8fc1\u79fb\u3002\u4e3a\u68c0\u9a8c\u8fd9\u4e00\u5047\u8bbe\uff0c\u6211\u4eec\u6536\u96c6\u4e86\u4e24\u4e2a\u65b0\u7684\u6570\u636e\u96c6\uff0c\u7528\u4e8e\u6d4b\u91cf\u5bb6\u5ead\u6210\u5458\u4e4b\u95f4\u8058\u793c\u7684\u5206\u914d\u60c5\u51b5\u3002\u6211\u4eec\u9996\u6b21\u53d1\u73b0\uff0c\u5411\u7537\u6027\u7236\u6bcd\u7684\u51c0\u8058\u793c\u8f6c\u79fb\u8f83\u4e3a\u666e\u904d\uff0c\u4f46\u5e76\u975e\u666e\u904d\u5b58\u5728\u3002\u4e0e\u7528\u4e8e\u6536\u5165\u5171\u4eab\u7684\u673a\u5236\u4e00\u81f4\uff0c\u5f53\u513f\u5b50\u8fc1\u79fb\uff0c\u5c24\u5176\u662f\u4ece\u4e8b\u9ad8\u6536\u5165\u804c\u4e1a\u65f6\uff0c\u6b64\u7c7b\u8f6c\u79fb\u66f4\u4e3a\u9891\u7e41\u3002\u5728\u5177\u6709\u5168\u56fd\u4ee3\u8868\u6027\u7684\u6570\u636e\u4e2d\uff0c\u8fc1\u79fb\u7387\u5728\u5386\u53f2\u4e0a\u8058\u793c\u4f20\u7edf\u8f83\u5f3a\u7684\u5730\u533a\u66f4\u9ad8\u3002\u6700\u540e\uff0c\u5229\u7528\u4e00\u9879\u5927\u89c4\u6a21\u9ad8\u901f\u516c\u8def\u5efa\u8bbe\u8ba1\u5212\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5728\u5386\u53f2\u4e0a\u8058\u793c\u4f20\u7edf\u8f83\u5f3a\u7684\u5730\u533a\uff0c\u5f53\u8fc1\u79fb\u6210\u672c\u4e0b\u964d\u65f6\uff0c\u7537\u6027\u8fc1\u79fb\u7387\u66f4\u9ad8\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u4e3a\u89e3\u91ca\u8058\u793c\u4e3a\u4f55\u5728\u6709\u660e\u786e\u8d1f\u9762\u540e\u679c\u7684\u60c5\u51b5\u4e0b\u4ecd\u6301\u7eed\u5b58\u5728\u63d0\u4f9b\u4e86\u4e00\u4e9b\u7ebf\u7d22\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf038", "journal": "QJE", "title": "The Economics of Spatial Mobility: Theory and Evidence Using Smartphone Data", "authors": ["Yuhei Miyauchi", "Kentaro Nakajima", "Stephen J Redding"], "author_details": [{"name": "Yuhei Miyauchi", "affiliations": ["Boston University ,"]}, {"name": "Kentaro Nakajima", "affiliations": ["Hitotsubashi University ,"]}, {"name": "Stephen J Redding", "affiliations": ["Stanford University and National Bureau of Economic Research, United States, Centre for Economic Policy and Research ,"]}], "abstract": "ABSTRACT We develop a tractable quantitative framework for modeling the rich patterns of spatial mobility observed in smartphone data. We show that travel is frequently undertaken as part of a travel itinerary, defined as a journey starting and ending at home that can include more than one intermediate stop on a given day. We show that these travel itineraries provide microfoundations for consumption externalities and generate both complementarity and substitutability between locations. We show that the consumption externalities implied by travel itineraries are central to matching quasi-experimental evidence from the shift to working from home. We find that these consumption externalities are key drivers of the agglomeration of economic activity in central cities and shape the relative welfare gains from alternative transport improvements in favor of investments in central cities.", "date": "2025-08-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf038", "title_zh": "\u7a7a\u95f4\u79fb\u52a8\u7684\u7ecf\u6d4e\u5b66\uff1a\u57fa\u4e8e\u667a\u80fd\u624b\u673a\u6570\u636e\u7684\u7406\u8bba\u4e0e\u5b9e\u8bc1", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u53ef\u5904\u7406\u7684\u91cf\u5316\u6846\u67b6\uff0c\u7528\u4e8e\u5efa\u6a21\u667a\u80fd\u624b\u673a\u6570\u636e\u4e2d\u89c2\u5bdf\u5230\u7684\u4e30\u5bcc\u7a7a\u95f4\u79fb\u52a8\u6a21\u5f0f\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u51fa\u884c\u901a\u5e38\u4f5c\u4e3a\u65c5\u884c\u884c\u7a0b\u7684\u4e00\u90e8\u5206\u8fdb\u884c\uff0c\u6240\u8c13\u65c5\u884c\u884c\u7a0b\u662f\u6307\u4e00\u5929\u5185\u4ece\u5bb6\u51fa\u53d1\u53c8\u56de\u5230\u5bb6\u7684\u65c5\u7a0b\uff0c\u9014\u4e2d\u53ef\u80fd\u5305\u542b\u591a\u4e2a\u4e2d\u9014\u505c\u7559\u70b9\u3002\u6211\u4eec\u8868\u660e\uff0c\u8fd9\u4e9b\u65c5\u884c\u884c\u7a0b\u4e3a\u6d88\u8d39\u5916\u90e8\u6027\u63d0\u4f9b\u4e86\u5fae\u89c2\u57fa\u7840\uff0c\u5e76\u5728\u4e0d\u540c\u5730\u70b9\u4e4b\u95f4\u4ea7\u751f\u4e86\u4e92\u8865\u6027\u548c\u66ff\u4ee3\u6027\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u53d1\u73b0\uff0c\u7531\u65c5\u884c\u884c\u7a0b\u6240\u9690\u542b\u7684\u6d88\u8d39\u5916\u90e8\u6027\u662f\u5339\u914d\u6765\u81ea\u5c45\u5bb6\u529e\u516c\u6a21\u5f0f\u8f6c\u53d8\u7684\u51c6\u5b9e\u9a8c\u8bc1\u636e\u7684\u5173\u952e\u56e0\u7d20\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u4e9b\u6d88\u8d39\u5916\u90e8\u6027\u662f\u7ecf\u6d4e\u6d3b\u52a8\u5728\u5e02\u4e2d\u5fc3\u96c6\u805a\u7684\u6838\u5fc3\u9a71\u52a8\u529b\uff0c\u5e76\u51b3\u5b9a\u4e86\u4e0d\u540c\u4ea4\u901a\u6539\u5584\u63aa\u65bd\u5e26\u6765\u7684\u76f8\u5bf9\u798f\u5229\u589e\u76ca\uff0c\u4ece\u800c\u652f\u6301\u5bf9\u5e02\u4e2d\u5fc3\u4ea4\u901a\u6295\u8d44\u7684\u4f18\u5148\u6027\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf037", "journal": "QJE", "title": "What Drives Risky Prescription Opioid Use? Evidence From Migration", "authors": ["Amy Finkelstein", "Matthew Gentzkow", "Dean Li"], "author_details": [{"name": "Amy Finkelstein", "affiliations": ["Massachusetts Institute of Technology, National Bureau of Economic Research, and J-PAL North America ,"]}, {"name": "Matthew Gentzkow", "affiliations": ["Stanford University and National Bureau of Economic Research ,"]}, {"name": "Dean Li", "affiliations": ["Massachusetts Institute of Technology ,"]}], "abstract": "ABSTRACT We develop and estimate a dynamic model of risky prescription opioid use that allows us to unpack the role of person- and place-specific drivers of the opioid epidemic and assess the impact of state opioid policies. Event studies indicate that among adults receiving federal disability insurance from 2006 to 2019, moves to states with higher rates of risky use produce an immediate jump in the probability of risky use, followed by an additional gradual increase for the next several years. Using a potential-outcomes framework, we show how these results map to the person- and place-specific factors in the model. Model estimates imply large effects of place on both the likelihood of transitioning to addiction and the availability of prescription opioids; they also indicate that these place effects change significantly when state laws restricting pain clinics are enacted. A one standard deviation reduction in all place effects would have reduced risky use by about 40% over our study period. One particular source of place effects, pain clinic laws, reduced risky use by 5%, but could have reduced it by 30% if they had been enacted earlier, with much of this magnification operating through the dynamics of addiction.", "date": "2025-08-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf037", "title_zh": "\u662f\u4ec0\u4e48\u9a71\u52a8\u4e86\u9ad8\u98ce\u9669\u5904\u65b9\u963f\u7247\u7c7b\u836f\u7269\u4f7f\u7528\uff1f\u6765\u81ea\u8fc1\u79fb\u7684\u8bc1\u636e", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u6784\u5efa\u5e76\u4f30\u8ba1\u4e86\u4e00\u4e2a\u52a8\u6001\u6a21\u578b\uff0c\u7528\u4e8e\u89e3\u6790\u4e2a\u4f53\u548c\u5730\u57df\u56e0\u7d20\u5bf9\u963f\u7247\u7c7b\u836f\u7269\u5371\u673a\u7684\u5f71\u54cd\uff0c\u5e76\u8bc4\u4f30\u5404\u5dde\u963f\u7247\u7c7b\u836f\u7269\u653f\u7b56\u7684\u6548\u679c\u3002\u4e8b\u4ef6\u7814\u7a76\u663e\u793a\uff0c\u57282006\u5e74\u81f32019\u5e74\u671f\u95f4\u83b7\u5f97\u8054\u90a6\u6b8b\u75be\u4fdd\u9669\u7684\u6210\u5e74\u4eba\uff0c\u8fc1\u79fb\u5230\u9ad8\u98ce\u9669\u4f7f\u7528\u7387\u5dde\u540e\uff0c\u5176\u9ad8\u98ce\u9669\u4f7f\u7528\u6982\u7387\u4f1a\u7acb\u5373\u4e0a\u5347\uff0c\u968f\u540e\u5728\u63a5\u4e0b\u6765\u7684\u51e0\u5e74\u4e2d\u6301\u7eed\u7f13\u6162\u589e\u52a0\u3002\u57fa\u4e8e\u6f5c\u5728\u7ed3\u679c\u6846\u67b6\uff0c\u6211\u4eec\u5c55\u793a\u4e86\u8fd9\u4e9b\u7ed3\u679c\u5982\u4f55\u5bf9\u5e94\u4e8e\u6a21\u578b\u4e2d\u7684\u4e2a\u4f53\u548c\u5730\u57df\u56e0\u7d20\u3002\u6a21\u578b\u4f30\u8ba1\u8868\u660e\uff0c\u5730\u57df\u56e0\u7d20\u5bf9\u8fdb\u5165\u6210\u763e\u72b6\u6001\u7684\u53ef\u80fd\u6027\u4ee5\u53ca\u5904\u65b9\u963f\u7247\u7c7b\u836f\u7269\u7684\u53ef\u83b7\u5f97\u6027\u5177\u6709\u663e\u8457\u5f71\u54cd\uff1b\u6b64\u5916\uff0c\u5f53\u5404\u5dde\u51fa\u53f0\u9650\u5236\u75bc\u75db\u8bca\u6240\u7684\u6cd5\u5f8b\u65f6\uff0c\u8fd9\u4e9b\u5730\u57df\u6548\u5e94\u4f1a\u53d1\u751f\u663e\u8457\u53d8\u5316\u3002\u5982\u679c\u6240\u6709\u5730\u57df\u6548\u5e94\u51cf\u5c11\u4e00\u4e2a\u6807\u51c6\u5dee\uff0c\u6574\u4e2a\u7814\u7a76\u671f\u95f4\u9ad8\u98ce\u9669\u4f7f\u7528\u5c06\u51cf\u5c11\u7ea640%\u3002\u5176\u4e2d\u4e00\u79cd\u5730\u57df\u6548\u5e94\u6765\u6e90\u2014\u2014\u75bc\u75db\u8bca\u6240\u6cd5\u5f8b\u2014\u2014\u51cf\u5c11\u4e865%\u7684\u9ad8\u98ce\u9669\u4f7f\u7528\uff0c\u4f46\u5982\u679c\u8fd9\u4e9b\u6cd5\u5f8b\u66f4\u65e9\u5b9e\u65bd\uff0c\u5176\u51cf\u5c11\u6548\u679c\u53ef\u63d0\u5347\u81f330%\uff0c\u5176\u4e2d\u5927\u90e8\u5206\u6548\u679c\u901a\u8fc7\u6210\u763e\u7684\u52a8\u6001\u8fc7\u7a0b\u5b9e\u73b0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf040", "journal": "QJE", "title": "Conviction, Incarceration, and Recidivism: Understanding the Revolving Door", "authors": ["John Eric Humphries", "Aur\u00e9lie Ouss", "Kamelia Stavreva", "Megan T Stevenson", "Winnie van Dijk"], "author_details": [{"name": "John Eric Humphries", "affiliations": ["Yale University and National Bureau of Economic Research ,"]}, {"name": "Aur\u00e9lie Ouss", "affiliations": ["University of Pennsylvania and National Bureau of Economic Research ,"]}, {"name": "Kamelia Stavreva", "affiliations": ["Columbia University ,"]}, {"name": "Megan T Stevenson", "affiliations": ["University of Virginia ,"]}, {"name": "Winnie van Dijk", "affiliations": ["Yale University and National Bureau of Economic Research ,"]}], "abstract": "Abstract Noncarceral conviction is a common outcome of criminal court cases: for every person incarcerated, there are approximately three who were recently convicted but not sentenced to prison or jail. We extend the binary-treatment judge IV framework to settings with multiple treatments and use it to study the consequences of noncarceral conviction. We outline assumptions under which widely used 2SLS regressions recover margin-specific treatment effects, relate these assumptions to models of judge decision-making, and derive an expression that provides intuition about the direction and magnitude of asymptotic bias when a key assumption on judge decision-making is not met. We find that noncarceral conviction (relative to dismissal) leads to a large and long-lasting increase in recidivism for felony defendants in Virginia. In contrast, incarceration (relative to noncarceral conviction) leads to a short-run reduction in recidivism, consistent with incapacitation. Our empirical results suggest that noncarceral felony conviction is an important and overlooked driver of recidivism.", "date": "2025-08-07", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf040", "title_zh": "\u4fe1\u5ff5\u3001\u76d1\u7981\u4e0e\u518d\u72af\uff1a\u7406\u89e3\u53cd\u590d\u8fdb\u51fa\u76d1\u72f1\u7684\u673a\u5236", "abstract_zh": "\u6458\u8981 \u975e\u76d1\u7981\u5b9a\u7f6a\u662f\u5211\u4e8b\u6cd5\u9662\u6848\u4ef6\u4e2d\u7684\u5e38\u89c1\u7ed3\u679c\uff1a\u5bf9\u4e8e\u6bcf\u4e00\u540d\u88ab\u76d1\u7981\u7684\u4eba\uff0c\u5927\u7ea6\u6709\u4e09\u4eba\u6700\u8fd1\u88ab\u5b9a\u7f6a\u4f46\u672a\u88ab\u5224\u5904\u76d1\u7981\u6216\u62d8\u7559\u3002\u6211\u4eec\u6269\u5c55\u4e86\u4e8c\u5143\u5904\u7406\u6cd5\u5b98\u5de5\u5177\u53d8\u91cf\u6846\u67b6\uff0c\u7528\u4e8e\u7814\u7a76\u975e\u76d1\u7981\u5b9a\u7f6a\u7684\u540e\u679c\u3002\u6211\u4eec\u9610\u8ff0\u4e86\u5728\u4f55\u79cd\u5047\u8bbe\u4e0b\u5e7f\u6cdb\u4f7f\u7528\u76842SLS\u56de\u5f52\u80fd\u591f\u6062\u590d\u7279\u5b9a\u5904\u7406\u6548\u5e94\uff0c\u5e76\u5c06\u8fd9\u4e9b\u5047\u8bbe\u4e0e\u6cd5\u5b98\u51b3\u7b56\u6a21\u578b\u8054\u7cfb\u8d77\u6765\uff0c\u63a8\u5bfc\u51fa\u4e00\u4e2a\u8868\u8fbe\u5f0f\uff0c\u4ee5\u63d0\u4f9b\u5173\u4e8e\u5f53\u6cd5\u5b98\u51b3\u7b56\u5047\u8bbe\u672a\u6ee1\u8db3\u65f6\u6e10\u8fd1\u504f\u8bef\u65b9\u5411\u548c\u5927\u5c0f\u7684\u76f4\u89c2\u7406\u89e3\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u76f8\u8f83\u4e8e\u88ab\u9a73\u56de\uff0c\u975e\u76d1\u7981\u5b9a\u7f6a\uff08\u5c24\u5176\u662f\u91cd\u7f6a\u88ab\u544a\uff09\u4f1a\u5bfc\u81f4\u663e\u8457\u4e14\u6301\u4e45\u7684\u518d\u72af\u7387\u4e0a\u5347\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u76d1\u7981\u76f8\u8f83\u4e8e\u975e\u76d1\u7981\u5b9a\u7f6a\u5728\u77ed\u671f\u5185\u964d\u4f4e\u4e86\u518d\u72af\u7387\uff0c\u8fd9\u4e0e\u76d1\u7981\u7684\u5a01\u6151\u4f5c\u7528\u4e00\u81f4\u3002\u6211\u4eec\u7684\u5b9e\u8bc1\u7ed3\u679c\u8868\u660e\uff0c\u975e\u76d1\u7981\u91cd\u7f6a\u5b9a\u7f6a\u662f\u518d\u72af\u7684\u91cd\u8981\u4e14\u88ab\u5ffd\u89c6\u7684\u9a71\u52a8\u56e0\u7d20\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf036", "journal": "QJE", "title": "Insurance Versus Moral Hazard in Income-Contingent Student Loan Repayment", "authors": ["Tim de Silva"], "author_details": [{"name": "Tim de Silva", "affiliations": ["Stanford University, Graduate School of Business ,"]}], "abstract": "Abstract Student loans with income-contingent repayment insure borrowers against income risk but can reduce their incentives to earn more. Using a change in Australia\u2019s income-contingent repayment schedule, I show that borrowers reduce their labor supply to lower their repayments. These responses are larger among borrowers with more hourly flexibility, a lower probability of repayment, and tighter liquidity constraints. I use these responses to estimate a dynamic model of labor supply with frictions that generate imperfect adjustment. My estimates imply that the labor supply responses to income-contingent repayment limit the optimal amount of insurance in government-provided student loans. However, these responses are too small to justify fixed-repayment contracts: restructuring existing student loans from fixed repayment to a constrained-optimal income-contingent loan\u2014while keeping the tax and transfer system unchanged\u2014increases borrower welfare by the equivalent of a 0.8% increase in lifetime consumption at no additional fiscal cost.", "date": "2025-08-04", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf036", "title_zh": "\u4fdd\u9669\u4e0e\u9053\u5fb7\u98ce\u9669\u5728\u6536\u5165\u6302\u94a9\u5b66\u751f\u8d37\u6b3e\u8fd8\u6b3e\u4e2d\u7684\u6743\u8861", "abstract_zh": "\u6458\u8981 \u5b66\u751f\u8d37\u6b3e\u91c7\u7528\u6536\u5165\u6302\u94a9\u8fd8\u6b3e\u65b9\u5f0f\u53ef\u4ee5\u4e3a\u501f\u6b3e\u4eba\u63d0\u4f9b\u6536\u5165\u98ce\u9669\u7684\u4fdd\u9669\uff0c\u4f46\u53ef\u80fd\u964d\u4f4e\u5176\u52aa\u529b\u5de5\u4f5c\u7684\u6fc0\u52b1\u3002\u5229\u7528\u6fb3\u5927\u5229\u4e9a\u6536\u5165\u6302\u94a9\u8fd8\u6b3e\u8ba1\u5212\u7684\u8c03\u6574\uff0c\u6211\u8bc1\u660e\u501f\u6b3e\u4eba\u7684\u52b3\u52a8\u4f9b\u7ed9\u51cf\u5c11\u4e86\uff0c\u4ee5\u964d\u4f4e\u8fd8\u6b3e\u989d\u3002\u8fd9\u79cd\u53cd\u5e94\u5728\u501f\u6b3e\u4eba\u5177\u6709\u66f4\u9ad8\u5c0f\u65f6\u7075\u6d3b\u6027\u3001\u66f4\u4f4e\u7684\u8fd8\u6b3e\u6982\u7387\u4ee5\u53ca\u66f4\u7d27\u7684\u6d41\u52a8\u6027\u7ea6\u675f\u60c5\u51b5\u4e0b\u66f4\u4e3a\u663e\u8457\u3002\u6211\u5229\u7528\u8fd9\u4e9b\u53cd\u5e94\u4f30\u8ba1\u4e86\u4e00\u4e2a\u5305\u542b\u6469\u64e6\u7684\u52a8\u6001\u52b3\u52a8\u4f9b\u7ed9\u6a21\u578b\uff0c\u8be5\u6a21\u578b\u80fd\u591f\u4ea7\u751f\u4e0d\u5b8c\u5168\u8c03\u6574\u3002\u6211\u7684\u4f30\u8ba1\u8868\u660e\uff0c\u6536\u5165\u6302\u94a9\u8fd8\u6b3e\u5bf9\u52b3\u52a8\u4f9b\u7ed9\u7684\u6291\u5236\u4f5c\u7528\u9650\u5236\u4e86\u653f\u5e9c\u63d0\u4f9b\u5b66\u751f\u8d37\u6b3e\u4e2d\u4fdd\u9669\u7684\u6700\u4f18\u6c34\u5e73\u3002\u7136\u800c\uff0c\u8fd9\u4e9b\u53cd\u5e94\u4e0d\u8db3\u4ee5\u652f\u6301\u56fa\u5b9a\u8fd8\u6b3e\u5408\u540c\uff1a\u5c06\u73b0\u6709\u5b66\u751f\u8d37\u6b3e\u4ece\u56fa\u5b9a\u8fd8\u6b3e\u6539\u4e3a\u57fa\u4e8e\u7ea6\u675f\u6700\u4f18\u7684\u6536\u5165\u6302\u94a9\u8fd8\u6b3e\u2014\u2014\u540c\u65f6\u4fdd\u6301\u7a0e\u6536\u548c\u8f6c\u79fb\u652f\u4ed8\u4f53\u7cfb\u4e0d\u53d8\u2014\u2014\u80fd\u591f\u4f7f\u501f\u6b3e\u4eba\u7684\u798f\u5229\u63d0\u9ad8\u76f8\u5f53\u4e8e\u7ec8\u8eab\u6d88\u8d39\u589e\u52a00.8%\uff0c\u4e14\u65e0\u9700\u989d\u5916\u8d22\u653f\u652f\u51fa\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf035", "journal": "QJE", "title": "Investor Memory and Biased Beliefs: Evidence from the Field", "authors": ["Zhengyang Jiang", "Hongqi Liu", "Cameron Peng", "Hongjun Yan"], "author_details": [{"name": "Zhengyang Jiang", "affiliations": ["Kellogg School of Management, Northwestern University, and National Bureau of Economic Research ,"]}, {"name": "Hongqi Liu", "affiliations": ["Shenzhen Finance Institute and School of Management and Economics, The Chinese University of Hong Kong, Shenzhen ,"]}, {"name": "Cameron Peng", "affiliations": ["London School of Economics and Political Science and Centre for Economic Policy and Research ,"]}, {"name": "Hongjun Yan", "affiliations": ["DePaul University ,"]}], "abstract": "Abstract We survey a large, representative sample of retail investors in China to elicit their memories of stock market investments and their return expectations. We merge these survey data with administrative transaction data to test a model in which investors selectively recall past experiences to form their beliefs. Our analysis uncovers new facts about investor memory and highlights similarity-based recall as a key mechanism of belief formation in financial markets. A rising market prompts investors to recall their past experiences more positively, leading to more optimistic forecasts of future returns. Recalled experiences can explain cross-investor variation in return expectations and, in our setting, dominate actual experiences in their explanatory power. In the transaction data, we confirm that recalled experiences are reflected in investors\u2019 trading decisions through a belief channel.", "date": "2025-07-28", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf035", "title_zh": "\u6295\u8d44\u8005\u8bb0\u5fc6\u4e0e\u504f\u8bef\u4fe1\u5ff5\uff1a\u6765\u81ea\u5e02\u573a\u7684\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u5bf9\u4e2d\u56fd\u4e00\u4e2a\u5927\u89c4\u6a21\u3001\u5177\u6709\u4ee3\u8868\u6027\u7684\u96f6\u552e\u6295\u8d44\u8005\u7fa4\u4f53\u8fdb\u884c\u4e86\u8c03\u67e5\uff0c\u4ee5\u83b7\u53d6\u4ed6\u4eec\u5bf9\u80a1\u7968\u5e02\u573a\u6295\u8d44\u7684\u8bb0\u5fc6\u4ee5\u53ca\u5bf9\u672a\u6765\u6536\u76ca\u7684\u9884\u671f\u3002\u6211\u4eec\u5c06\u8fd9\u4e9b\u8c03\u67e5\u6570\u636e\u4e0e\u884c\u653f\u4ea4\u6613\u6570\u636e\u76f8\u7ed3\u5408\uff0c\u68c0\u9a8c\u4e00\u4e2a\u6295\u8d44\u8005\u4f1a\u9009\u62e9\u6027\u5730\u56de\u5fc6\u8fc7\u53bb\u7ecf\u5386\u4ee5\u5f62\u6210\u5176\u4fe1\u5ff5\u7684\u6a21\u578b\u3002\u6211\u4eec\u7684\u5206\u6790\u63ed\u793a\u4e86\u5173\u4e8e\u6295\u8d44\u8005\u8bb0\u5fc6\u7684\u65b0\u4e8b\u5b9e\uff0c\u5e76\u5f3a\u8c03\u4e86\u76f8\u4f3c\u6027\u56de\u5fc6\u4f5c\u4e3a\u91d1\u878d\u5e02\u573a\u4e2d\u4fe1\u5ff5\u5f62\u6210\u7684\u5173\u952e\u673a\u5236\u3002\u5e02\u573a\u4e0a\u6da8\u4f1a\u4fc3\u4f7f\u6295\u8d44\u8005\u66f4\u79ef\u6781\u5730\u56de\u5fc6\u8fc7\u53bb\u7684\u7ecf\u5386\uff0c\u4ece\u800c\u5bf9\u672a\u6765\u6536\u76ca\u505a\u51fa\u66f4\u4e50\u89c2\u7684\u9884\u6d4b\u3002\u56de\u5fc6\u4e2d\u7684\u7ecf\u5386\u53ef\u4ee5\u89e3\u91ca\u4e0d\u540c\u6295\u8d44\u8005\u5bf9\u672a\u6765\u6536\u76ca\u9884\u671f\u7684\u5dee\u5f02\uff0c\u5728\u672c\u7814\u7a76\u4e2d\uff0c\u5176\u89e3\u91ca\u529b\u751a\u81f3\u8d85\u8fc7\u4e86\u5b9e\u9645\u7ecf\u5386\u672c\u8eab\u3002\u5728\u4ea4\u6613\u6570\u636e\u4e2d\uff0c\u6211\u4eec\u8bc1\u5b9e\u4e86\u56de\u5fc6\u4e2d\u7684\u7ecf\u5386\u901a\u8fc7\u4fe1\u5ff5\u6e20\u9053\u53cd\u6620\u5728\u6295\u8d44\u8005\u7684\u4ea4\u6613\u51b3\u7b56\u4e2d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf033", "journal": "QJE", "title": "Distributional Growth Accounting: Education and the Reduction of Global Poverty, 1980\u20132019", "authors": ["Amory Gethin"], "author_details": [{"name": "Amory Gethin", "affiliations": ["Development Research Group, World Bank ,"]}], "abstract": "Abstract This article quantifies the role played by education in the reduction of global poverty. I propose tools for identifying the contribution of schooling to economic growth by income group, integrating imperfect substitution between skill groups into a macroeconomic growth decomposition. I bring this \u201cdistributional growth accounting\u201d framework to the data by exploiting a new microdatabase representative of nearly all of the world\u2019s population, new estimates of the private returns to schooling, and historical income distribution statistics. Education can account for about 45% of global economic growth and 60% of pretax income growth among the world\u2019s poorest 20% from 1980 to 2019. A significant fraction of these gains was made possible by skill-biased technical change amplifying the returns to education. Because they ignore the distributional effects of schooling, standard growth accounting methods substantially underestimate economic benefits of education for the global poor.", "date": "2025-07-22", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf033", "title_zh": "\u5206\u914d\u6027\u589e\u957f\u6838\u7b97\uff1a\u6559\u80b2\u4e0e\u5168\u7403\u8d2b\u56f0\u51cf\u5c11\uff0c1980\u20132019", "abstract_zh": "\u672c\u6587\u91cf\u5316\u4e86\u6559\u80b2\u5728\u51cf\u5c11\u5168\u7403\u8d2b\u56f0\u4e2d\u7684\u4f5c\u7528\u3002\u6211\u63d0\u51fa\u4e86\u8bc6\u522b\u4e0d\u540c\u6536\u5165\u7fa4\u4f53\u4e2d\u6559\u80b2\u5bf9\u7ecf\u6d4e\u589e\u957f\u8d21\u732e\u7684\u5de5\u5177\uff0c\u901a\u8fc7\u5c06\u6280\u80fd\u7fa4\u4f53\u4e4b\u95f4\u7684\u4e0d\u5b8c\u5168\u66ff\u4ee3\u7eb3\u5165\u5b8f\u89c2\u7ecf\u6d4e\u589e\u957f\u5206\u89e3\u6846\u67b6\u3002\u5229\u7528\u4e00\u4e2a\u4ee3\u8868\u5168\u7403\u8fd1\u5168\u90e8\u4eba\u53e3\u7684\u5168\u65b0\u5fae\u89c2\u6570\u636e\u5e93\u3001\u6559\u80b2\u7684\u79c1\u4eba\u56de\u62a5\u65b0\u4f30\u8ba1\u503c\u4ee5\u53ca\u5386\u53f2\u6536\u5165\u5206\u5e03\u7edf\u8ba1\u6570\u636e\uff0c\u5c06\u8fd9\u4e00\u201c\u5206\u914d\u6027\u589e\u957f\u6838\u7b97\u201d\u6846\u67b6\u5e94\u7528\u4e8e\u6570\u636e\u3002\u6559\u80b2\u53ef\u89e3\u91ca1980\u81f32019\u5e74\u95f4\u5168\u7403\u7ecf\u6d4e\u589e\u957f\u7684\u7ea645%\uff0c\u4ee5\u53ca\u5168\u7403\u6700\u8d2b\u56f0\u4eba\u53e3\uff08\u524d20%\uff09\u7a0e\u524d\u6536\u5165\u589e\u957f\u7684\u7ea660%\u3002\u5176\u4e2d\u76f8\u5f53\u4e00\u90e8\u5206\u589e\u957f\u5f97\u76ca\u4e8e\u6280\u80fd\u504f\u5411\u578b\u6280\u672f\u53d8\u9769\u653e\u5927\u4e86\u6559\u80b2\u7684\u56de\u62a5\u3002\u7531\u4e8e\u6807\u51c6\u589e\u957f\u6838\u7b97\u65b9\u6cd5\u5ffd\u7565\u4e86\u6559\u80b2\u7684\u5206\u914d\u6548\u5e94\uff0c\u56e0\u6b64\u4e25\u91cd\u4f4e\u4f30\u4e86\u6559\u80b2\u5bf9\u5168\u7403\u8d2b\u56f0\u4eba\u53e3\u7684\u7ecf\u6d4e\u6536\u76ca\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf034", "journal": "QJE", "title": "From Public Labs to Private Firms: Magnitude And Channels of Local R&D Spillovers", "authors": ["Antonin Bergeaud", "Arthur Guillouzouic", "Emeric Henry", "Cl\u00e9ment Malgouyres"], "author_details": [{"name": "Antonin Bergeaud", "affiliations": ["HEC Paris, France; Centre for Economic Performance and Centre for Economic Policy Research ,"]}, {"name": "Arthur Guillouzouic", "affiliations": ["Aix-Marseille School of Economics, Centre National de la Recherche Scientifique, and Paris School of Economics\u2013Institut des Politiques Publiques ,"]}, {"name": "Emeric Henry", "affiliations": ["Sciences Po, France; Centre for Economic Policy Research ,"]}, {"name": "Cl\u00e9ment Malgouyres", "affiliations": ["Center for Research in Economics and Statistics, Centre National de la Recherche Scientifique, and Paris School of Economics\u2013Institut des Politiques Publiques ,"]}], "abstract": "Abstract Introducing a new measure of scientific proximity between private firms and public research groups and exploiting a multibillion-euro financing program of academic clusters in France, we provide causal evidence of local spillovers from academic research to firms in the private sector. Our main estimate suggests that each \u20ac1 spent in academic research through this program spurred an additional \u20ac0.81 in private R&D expenditures. We also show that this shock increased the average quality of patents. We exploit reports produced by funded clusters, complemented by data on firm creation, labor mobility, and R&D public\u2013private partnerships, to provide evidence on the channels for these spillovers. We discuss the policy implications of funding academic research to stimulate private R&D.", "date": "2025-07-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf034", "title_zh": "\u4ece\u516c\u5171\u5b9e\u9a8c\u5ba4\u5230\u79c1\u8425\u4f01\u4e1a\uff1a\u672c\u5730\u7814\u53d1\u6ea2\u51fa\u6548\u5e94\u7684\u89c4\u6a21\u4e0e\u4f20\u5bfc\u6e20\u9053", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5f15\u5165\u4e86\u4e00\u9879\u8861\u91cf\u79c1\u8425\u4f01\u4e1a\u4e0e\u516c\u5171\u7814\u7a76\u673a\u6784\u4e4b\u95f4\u79d1\u5b66\u63a5\u8fd1\u7a0b\u5ea6\u7684\u65b0\u6307\u6807\uff0c\u5e76\u5229\u7528\u6cd5\u56fd\u4e00\u9879\u6d89\u53ca\u6570\u5341\u4ebf\u6b27\u5143\u7684\u5b66\u672f\u96c6\u7fa4\u878d\u8d44\u8ba1\u5212\uff0c\u63d0\u4f9b\u4e86\u5b66\u672f\u7814\u7a76\u5411\u79c1\u8425\u4f01\u4e1a\u4f20\u5bfc\u7684\u56e0\u679c\u8bc1\u636e\u3002\u6211\u4eec\u7684\u4e3b\u8981\u4f30\u8ba1\u7ed3\u679c\u8868\u660e\uff0c\u6bcf\u6295\u51651\u6b27\u5143\u7528\u4e8e\u5b66\u672f\u7814\u7a76\uff0c\u5c31\u4f1a\u5e26\u52a8\u79c1\u8425\u90e8\u95e8\u989d\u5916\u589e\u52a00.81\u6b27\u5143\u7684\u7814\u53d1\u652f\u51fa\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0c\u8fd9\u4e00\u51b2\u51fb\u63d0\u9ad8\u4e86\u4e13\u5229\u7684\u5e73\u5747\u8d28\u91cf\u3002\u6211\u4eec\u7ed3\u5408\u53d7\u8d44\u52a9\u96c6\u7fa4\u7684\u62a5\u544a\u6570\u636e\uff0c\u4ee5\u53ca\u4f01\u4e1a\u6210\u7acb\u3001\u52b3\u52a8\u529b\u6d41\u52a8\u548c\u7814\u53d1\u516c\u79c1\u5408\u4f5c\u7b49\u6570\u636e\uff0c\u63ed\u793a\u4e86\u8fd9\u4e9b\u6ea2\u51fa\u6548\u5e94\u7684\u4f20\u5bfc\u8def\u5f84\u3002\u6211\u4eec\u8fdb\u4e00\u6b65\u8ba8\u8bba\u4e86\u901a\u8fc7\u8d44\u52a9\u5b66\u672f\u7814\u7a76\u4ee5\u4fc3\u8fdb\u79c1\u8425\u90e8\u95e8\u7814\u53d1\u7684\u653f\u7b56\u542b\u4e49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf030", "journal": "QJE", "title": "Present Bias Unconstrained: Consumption, Welfare, and the Present-Bias Dilemma", "authors": ["Peter Maxted"], "author_details": [{"name": "Peter Maxted", "affiliations": ["Haas School of Business, University of California , Berkeley ,"]}], "abstract": "Abstract By augmenting the continuous-time specification of Harris and Laibson (2013) with the assumption that hard borrowing constraints do not bind in equilibrium, present bias can be tractably incorporated into rich consumption-saving models featuring stochastic income, risky and illiquid assets, and costly borrowing. I present closed-form expressions characterizing how present bias affects consumption, illiquid asset demand, and welfare. This welfare analysis specifies the channels through which present bias can matter for policy and uncovers the present-bias dilemma: present bias can have large welfare costs, but individuals have little ability to alleviate these costs using financial commitment devices like illiquid assets.", "date": "2025-07-08", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf030", "title_zh": "\u65e0\u7ea6\u675f\u7684\u73b0\u65f6\u504f\u89c1\uff1a\u6d88\u8d39\u3001\u798f\u5229\u4e0e\u73b0\u65f6\u504f\u89c1\u56f0\u5883", "abstract_zh": "\u6458\u8981 \u901a\u8fc7\u5728Harris\u548cLaibson\uff082013\uff09\u7684\u8fde\u7eed\u65f6\u95f4\u6a21\u578b\u57fa\u7840\u4e0a\u5f15\u5165\u786c\u6027\u501f\u8d37\u7ea6\u675f\u5728\u5747\u8861\u4e2d\u4e0d\u751f\u6548\u8fd9\u4e00\u5047\u8bbe\uff0c\u53ef\u4ee5\u5c06\u73b0\u65f6\u504f\u89c1\u6709\u6761\u4e0d\u7d0a\u5730\u7eb3\u5165\u5305\u542b\u968f\u673a\u6536\u5165\u3001\u98ce\u9669\u8d44\u4ea7\u548c\u975e\u6d41\u52a8\u6027\u8d44\u4ea7\u4ee5\u53ca\u501f\u8d37\u6210\u672c\u7684\u590d\u6742\u6d88\u8d39\u50a8\u84c4\u6a21\u578b\u4e2d\u3002\u672c\u6587\u7ed9\u51fa\u4e86\u73b0\u65f6\u504f\u89c1\u5982\u4f55\u5f71\u54cd\u6d88\u8d39\u3001\u975e\u6d41\u52a8\u6027\u8d44\u4ea7\u9700\u6c42\u548c\u798f\u5229\u7684\u95ed\u5f0f\u8868\u8fbe\u3002\u8be5\u798f\u5229\u5206\u6790\u9610\u660e\u4e86\u73b0\u65f6\u504f\u89c1\u5bf9\u653f\u7b56\u53ef\u80fd\u4ea7\u751f\u7684\u5f71\u54cd\uff0c\u5e76\u63ed\u793a\u4e86\u73b0\u65f6\u504f\u89c1\u56f0\u5883\uff1a\u73b0\u65f6\u504f\u89c1\u53ef\u80fd\u5e26\u6765\u663e\u8457\u7684\u798f\u5229\u635f\u5931\uff0c\u4f46\u4e2a\u4f53\u5728\u5229\u7528\u975e\u6d41\u52a8\u6027\u8d44\u4ea7\u7b49\u91d1\u878d\u627f\u8bfa\u5de5\u5177\u6765\u7f13\u89e3\u8fd9\u4e9b\u635f\u5931\u65b9\u9762\u80fd\u529b\u6709\u9650\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf031", "journal": "QJE", "title": "Barriers to Global Capital Allocation", "authors": ["Bruno Pellegrino", "Enrico Spolaore", "Romain Wacziarg"], "author_details": [{"name": "Bruno Pellegrino", "affiliations": ["Columbia Business School, National Bureau of Economic Research, and CESifo ,", "Tufts University, National Bureau of Economic Research, and CESifo ,", "University of California, Los Angeles, and National Bureau of Economic Research ,"]}, {"name": "Enrico Spolaore", "affiliations": ["Columbia Business School, National Bureau of Economic Research, and CESifo ,", "Tufts University, National Bureau of Economic Research, and CESifo ,", "University of California, Los Angeles, and National Bureau of Economic Research ,"]}, {"name": "Romain Wacziarg", "affiliations": ["Columbia Business School, National Bureau of Economic Research, and CESifo ,", "Tufts University, National Bureau of Economic Research, and CESifo ,", "University of California, Los Angeles, and National Bureau of Economic Research ,"]}], "abstract": "ABSTRACT Observed international investment positions and cross-country heterogeneity in rates of return to capital are hard to reconcile with frictionless capital markets. This article develops a theory of international capital allocation: a multi-country dynamic spatial general equilibrium model in which the entire network of cross-border investment is endogenously determined. Our model features cross-country heterogeneity in fundamental risk, a demand system for international assets, and frictions that cause segmentation in international capital markets. We measure frictions affecting international investment and apply our model to data from nearly 100 countries, using a new dataset of international capital taxes and cultural, linguistic, and geographic distances between countries (geopoliticaldistance.org). Our model performs well in reproducing the composition of international portfolios, the cross section of home bias and rates of return to capital, and other key features of international capital markets. Finally, we carry out counterfactual exercises: we show that barriers to international investment reduce world output by 7% and raise the cross-country dispersion of capital per employee, contributing in a meaningful way to global inequality.", "date": "2025-06-23", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf031", "title_zh": "\u5168\u7403\u8d44\u672c\u914d\u7f6e\u7684\u969c\u788d", "abstract_zh": "\u6458\u8981 \u89c2\u6d4b\u5230\u7684\u56fd\u9645\u6295\u8d44\u5730\u4f4d\u4ee5\u53ca\u5404\u56fd\u8d44\u672c\u56de\u62a5\u7387\u7684\u5f02\u8d28\u6027\uff0c\u96be\u4ee5\u4e0e\u65e0\u6469\u64e6\u7684\u8d44\u672c\u5e02\u573a\u76f8\u8c03\u548c\u3002\u672c\u6587\u6784\u5efa\u4e86\u4e00\u4e2a\u591a\u56fd\u52a8\u6001\u7a7a\u95f4\u4e00\u822c\u5747\u8861\u6a21\u578b\uff0c\u5176\u4e2d\u8de8\u5883\u6295\u8d44\u7684\u6574\u4e2a\u7f51\u7edc\u662f\u5185\u751f\u51b3\u5b9a\u7684\u3002\u8be5\u6a21\u578b\u5305\u542b\u5404\u56fd\u57fa\u672c\u9762\u98ce\u9669\u7684\u5f02\u8d28\u6027\u3001\u56fd\u9645\u8d44\u4ea7\u7684\u9700\u6c42\u4f53\u7cfb\uff0c\u4ee5\u53ca\u5bfc\u81f4\u56fd\u9645\u8d44\u672c\u5e02\u573a\u5206\u5272\u7684\u6469\u64e6\u3002\u6211\u4eec\u6d4b\u91cf\u4e86\u5f71\u54cd\u56fd\u9645\u6295\u8d44\u7684\u6469\u64e6\uff0c\u5e76\u5229\u7528\u6765\u81ea\u8fd1100\u4e2a\u56fd\u5bb6\u7684\u6570\u636e\uff0c\u7ed3\u5408\u4e00\u4e2a\u65b0\u6784\u5efa\u7684\u56fd\u9645\u8d44\u672c\u7a0e\u6570\u636e\u96c6\u4ee5\u53ca\u5404\u56fd\u95f4\u6587\u5316\u3001\u8bed\u8a00\u548c\u5730\u7406\u8ddd\u79bb\uff08geopoliticaldistance.org\uff09\u7684\u6570\u636e\uff0c\u5bf9\u6a21\u578b\u8fdb\u884c\u5e94\u7528\u3002\u6a21\u578b\u5728\u518d\u73b0\u56fd\u9645\u6295\u8d44\u7ec4\u5408\u7684\u6784\u6210\u3001\u5404\u56fd\u672c\u571f\u504f\u597d\u548c\u8d44\u672c\u56de\u62a5\u7387\u7684\u6a2a\u622a\u9762\u7279\u5f81\u4ee5\u53ca\u5176\u4ed6\u56fd\u9645\u8d44\u672c\u5e02\u573a\u5173\u952e\u7279\u5f81\u65b9\u9762\u8868\u73b0\u826f\u597d\u3002\u6700\u540e\uff0c\u6211\u4eec\u8fdb\u884c\u4e86\u53cd\u4e8b\u5b9e\u5206\u6790\uff1a\u6211\u4eec\u53d1\u73b0\uff0c\u56fd\u9645\u6295\u8d44\u969c\u788d\u4f1a\u4f7f\u5168\u7403\u4ea7\u51fa\u51cf\u5c117%\uff0c\u5e76\u589e\u52a0\u5404\u56fd\u4eba\u5747\u8d44\u672c\u7684\u5dee\u5f02\uff0c\u4ece\u800c\u5728\u4e00\u5b9a\u7a0b\u5ea6\u4e0a\u52a0\u5267\u5168\u7403\u4e0d\u5e73\u7b49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u7f51\u7edc", "\u8d44\u672c\u6d41\u52a8"]}, {"doi": "10.1093/qje/qjaf029", "journal": "QJE", "title": "Bottom-Up Markup Fluctuations", "authors": ["Ariel T Burstein", "Vasco M Carvalho", "Basile Grassi"], "author_details": [{"name": "Ariel T Burstein", "affiliations": ["University California, Los Angeles, and National Bureau of Economic Research ,"]}, {"name": "Vasco M Carvalho", "affiliations": ["University of Cambridge and Center for Economic Policy and Research ,"]}, {"name": "Basile Grassi", "affiliations": ["Bocconi University and Innocenzo Gasparini Institute for Economic Research ,", "Observatoire Fran\u00e7ais des Conjonctures \u00c9conomiques ,", "Center for Economic Policy and Research ,"]}], "abstract": "Abstract We study markup cyclicality in a granular macroeconomic model with oligopolistic competition. We first characterize how firm, sectoral, and aggregate markups comove with output at different levels of aggregation in response to firm-level shocks. We quantify the model\u2019s ability to reproduce salient features of the cyclical properties of measured markups in French administrative firm-level data from the bottom (firm) level to the aggregate level. We document that (i) firm-level markups rise with market share and sector-level markups with concentration, (ii) the relationship between markups and sectoral output varies by firm size\u2014negative for small firms but positive for large ones, (iii) sector-level markups move positively with sectoral output, and (iv) sectoral markups show no systematic relationship with aggregate output. Our model helps rationalize these seemingly conflicting patterns of markup cyclicality in the data.", "date": "2025-06-19", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf029", "title_zh": "\u81ea\u4e0b\u800c\u4e0a\u7684\u52a0\u4ef7\u6ce2\u52a8", "abstract_zh": "\u6211\u4eec\u7814\u7a76\u4e86\u4e00\u4e2a\u5177\u6709\u5be1\u5934\u7ade\u4e89\u7684\u7ec6\u7c92\u5ea6\u5b8f\u89c2\u7ecf\u6d4e\u6a21\u578b\u4e2d\u7684\u52a0\u4ef7\u5468\u671f\u6027\u3002\u6211\u4eec\u9996\u5148\u523b\u753b\u4e86\u5728\u4e0d\u540c\u805a\u5408\u6c34\u5e73\u4e0a\uff0c\u4f01\u4e1a\u3001\u884c\u4e1a\u548c\u603b\u4f53\u52a0\u4ef7\u5982\u4f55\u5bf9\u4f01\u4e1a\u4ea7\u51fa\u6c34\u5e73\u7684\u51b2\u51fb\u4f5c\u51fa\u54cd\u5e94\u3002\u6211\u4eec\u91cf\u5316\u4e86\u8be5\u6a21\u578b\u5728\u4ece\u4f01\u4e1a\u5c42\u9762\u5230\u603b\u4f53\u5c42\u9762\u7684\u6cd5\u56fd\u884c\u653f\u4f01\u4e1a\u5c42\u9762\u6570\u636e\u4e2d\uff0c\u518d\u73b0\u6d4b\u5f97\u52a0\u4ef7\u5468\u671f\u7279\u5f81\u7684\u80fd\u529b\u3002\u6211\u4eec\u53d1\u73b0\uff1a\uff08i\uff09\u4f01\u4e1a\u5c42\u9762\u7684\u52a0\u4ef7\u968f\u5e02\u573a\u4efd\u989d\u4e0a\u5347\uff0c\u884c\u4e1a\u5c42\u9762\u7684\u52a0\u4ef7\u968f\u96c6\u4e2d\u5ea6\u4e0a\u5347\uff1b\uff08ii\uff09\u52a0\u4ef7\u4e0e\u884c\u4e1a\u4ea7\u51fa\u4e4b\u95f4\u7684\u5173\u7cfb\u56e0\u4f01\u4e1a\u89c4\u6a21\u800c\u5f02\u2014\u2014\u5bf9\u5c0f\u578b\u4f01\u4e1a\u4e3a\u8d1f\u76f8\u5173\uff0c\u5bf9\u5927\u578b\u4f01\u4e1a\u4e3a\u6b63\u76f8\u5173\uff1b\uff08iii\uff09\u884c\u4e1a\u5c42\u9762\u7684\u52a0\u4ef7\u4e0e\u884c\u4e1a\u4ea7\u51fa\u5448\u6b63\u5411\u53d8\u52a8\uff1b\uff08iv\uff09\u884c\u4e1a\u5c42\u9762\u7684\u52a0\u4ef7\u4e0e\u603b\u4f53\u4ea7\u51fa\u4e4b\u95f4\u6ca1\u6709\u7cfb\u7edf\u6027\u5173\u7cfb\u3002\u6211\u4eec\u7684\u6a21\u578b\u6709\u52a9\u4e8e\u89e3\u91ca\u8fd9\u4e9b\u770b\u4f3c\u77db\u76fe\u7684\u52a0\u4ef7\u5468\u671f\u6027\u7279\u5f81\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf027", "journal": "QJE", "title": "Who You Gonna Call? Gender Inequality in External Demands for Parental Involvement", "authors": ["Kristy Buzard", "Laura K Gee", "Olga Stoddard"], "author_details": [{"name": "Kristy Buzard", "affiliations": ["Syracuse University ,"]}, {"name": "Laura K Gee", "affiliations": ["Tufts University ,"]}, {"name": "Olga Stoddard", "affiliations": ["Brigham Young University ,"]}], "abstract": "ABSTRACT Gender imbalance in time spent on child-rearing causes gender inequalities in labor market outcomes, human capital accumulation, and economic mobility. We conduct a large-scale field experiment with a near universe of U.S. schools to investigate a potential source of inequality: external demands for parental involvement. Schools receive an email from a fictitious two-parent household and are asked to call one of the parents back. Mothers are 1.4 times more likely than fathers to be contacted. We decompose this inequality and demonstrate that the gender gap in external demands is associated with various measures of gender norms. We also show that signaling a father\u2019s availability substantially changes the gender pattern of callbacks. Our findings underscore a process through which agents outside the household contribute to within-household gender inequalities.", "date": "2025-06-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf027", "title_zh": "\u4f60\u8be5\u627e\u8c01\uff1f\u5bb6\u957f\u53c2\u4e0e\u5916\u90e8\u8981\u6c42\u4e2d\u7684\u6027\u522b\u4e0d\u5e73\u7b49", "abstract_zh": "\u6458\u8981 \u5bb6\u5ead\u80b2\u513f\u65f6\u95f4\u4e0a\u7684\u6027\u522b\u4e0d\u5e73\u8861\u5bfc\u81f4\u4e86\u52b3\u52a8\u529b\u5e02\u573a\u7ed3\u679c\u3001\u4eba\u529b\u8d44\u672c\u79ef\u7d2f\u4ee5\u53ca\u7ecf\u6d4e\u6d41\u52a8\u6027\u4e2d\u7684\u6027\u522b\u4e0d\u5e73\u7b49\u3002\u6211\u4eec\u5bf9\u7f8e\u56fd\u51e0\u4e4e\u6240\u6709\u5b66\u6821\u5f00\u5c55\u4e86\u4e00\u9879\u5927\u89c4\u6a21\u5b9e\u5730\u5b9e\u9a8c\uff0c\u4ee5\u63a2\u7a76\u4e0d\u5e73\u7b49\u7684\u4e00\u4e2a\u6f5c\u5728\u6765\u6e90\uff1a\u5916\u90e8\u5bf9\u5bb6\u957f\u53c2\u4e0e\u7684\u8981\u6c42\u3002\u5b66\u6821\u4f1a\u6536\u5230\u4e00\u5c01\u6765\u81ea\u865a\u6784\u7684\u53cc\u4eb2\u5bb6\u5ead\u7684\u7535\u5b50\u90ae\u4ef6\uff0c\u5e76\u88ab\u8981\u6c42\u81f4\u7535\u5176\u4e2d\u4e00\u4f4d\u5bb6\u957f\u3002\u6bcd\u4eb2\u88ab\u8054\u7cfb\u7684\u6982\u7387\u662f\u7236\u4eb2\u76841.4\u500d\u3002\u6211\u4eec\u5206\u89e3\u4e86\u8fd9\u79cd\u4e0d\u5e73\u7b49\uff0c\u5e76\u8bc1\u660e\u5916\u90e8\u8981\u6c42\u4e2d\u7684\u6027\u522b\u5dee\u8ddd\u4e0e\u5404\u79cd\u6027\u522b\u89c4\u8303\u6307\u6807\u76f8\u5173\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0c\u8868\u660e\u7236\u4eb2\u7684\u53ef\u53ca\u6027\u4f1a\u663e\u8457\u6539\u53d8\u56de\u8c03\u7684\u6027\u522b\u6a21\u5f0f\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u5f3a\u8c03\u4e86\u5bb6\u5ead\u5916\u90e8\u53c2\u4e0e\u8005\u5982\u4f55\u901a\u8fc7\u67d0\u79cd\u673a\u5236\u52a0\u5267\u5bb6\u5ead\u5185\u90e8\u7684\u6027\u522b\u4e0d\u5e73\u7b49\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf028", "journal": "QJE", "title": "Are Inflationary Shocks Regressive? A Feasible Set Approach", "authors": ["Felipe Del Canto", "John Grigsby", "Eric Qian", "Conor Walsh"], "author_details": [{"name": "Felipe Del Canto", "affiliations": ["Harvard University ,"]}, {"name": "John Grigsby", "affiliations": ["Princeton University and NBER ,"]}, {"name": "Eric Qian", "affiliations": ["Princeton University ,"]}, {"name": "Conor Walsh", "affiliations": ["Columbia University ,"]}], "abstract": "ABSTRACT We develop a framework to measure the welfare impact of macroeconomic shocks throughout the distribution. The first-order impact of a shock is summarized by the induced movements in agents\u2019 feasible sets: their budget constraint and borrowing constraints. We combine estimated impulse response functions with micro-data on household consumption bundles, asset holdings, and labor income for different U.S. households. We find that inflationary oil shocks are regressive, but monetary expansions are progressive, and there is substantial heterogeneity throughout the life cycle. In all cases, the dominant channel is the effect of the shock on the cost of accumulating assets, not movements in goods prices or labor income.", "date": "2025-06-09", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf028", "title_zh": "\u901a\u80c0\u51b2\u51fb\u662f\u5426\u5177\u6709\u518d\u5206\u914d\u6027\uff1f\u4e00\u79cd\u53ef\u884c\u96c6\u65b9\u6cd5", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6846\u67b6\uff0c\u7528\u4e8e\u8861\u91cf\u5b8f\u89c2\u7ecf\u6d4e\u51b2\u51fb\u5bf9\u4e0d\u540c\u7fa4\u4f53\u798f\u5229\u7684\u5f71\u54cd\u3002\u51b2\u51fb\u7684\u9996\u8981\u5f71\u54cd\u901a\u8fc7\u51b2\u51fb\u5f15\u53d1\u7684\u4e2a\u4f53\u53ef\u884c\u96c6\u53d8\u5316\u6765\u6982\u62ec\uff1a\u5373\u4ed6\u4eec\u7684\u9884\u7b97\u7ea6\u675f\u548c\u501f\u8d37\u7ea6\u675f\u7684\u53d8\u52a8\u3002\u6211\u4eec\u7ed3\u5408\u4e86\u4f30\u8ba1\u7684\u51b2\u51fb\u54cd\u5e94\u51fd\u6570\u4e0e\u7f8e\u56fd\u4e0d\u540c\u5bb6\u5ead\u7684\u6d88\u8d39\u7ec4\u5408\u3001\u8d44\u4ea7\u6301\u6709\u91cf\u548c\u52b3\u52a8\u6536\u5165\u7684\u5fae\u89c2\u6570\u636e\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u77f3\u6cb9\u901a\u80c0\u51b2\u51fb\u662f\u518d\u5206\u914d\u6027\u7684\uff0c\u800c\u8d27\u5e01\u6269\u5f20\u662f\u8fdb\u6b65\u6027\u7684\uff0c\u5e76\u4e14\u5728\u751f\u547d\u5468\u671f\u5185\u5b58\u5728\u663e\u8457\u5f02\u8d28\u6027\u3002\u5728\u6240\u6709\u60c5\u51b5\u4e0b\uff0c\u4e3b\u5bfc\u673a\u5236\u662f\u51b2\u51fb\u5bf9\u79ef\u7d2f\u8d44\u4ea7\u6210\u672c\u7684\u5f71\u54cd\uff0c\u800c\u975e\u5546\u54c1\u4ef7\u683c\u6216\u52b3\u52a8\u6536\u5165\u7684\u53d8\u5316\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf026", "journal": "QJE", "title": "Sexual Harassment in Public Spaces and Police Patrols: Experimental Evidence from Urban India", "authors": ["Sofia Amaral", "Girija Borker", "Nathan Fiala", "Anjani Kumar", "Nishith Prakash", "Maria Micaela Sviatschi"], "author_details": [{"name": "Sofia Amaral", "affiliations": ["South Asia Gender Innovation Lab, World Bank ,", "CESifo ,"]}, {"name": "Girija Borker", "affiliations": ["Development Impact, World Bank ,", "Institute of Labor Economics ,"]}, {"name": "Nathan Fiala", "affiliations": ["University of Connecticut ,"]}, {"name": "Anjani Kumar", "affiliations": ["Indian Police Service ,"]}, {"name": "Nishith Prakash", "affiliations": ["Northeastern University ,", "Bureau for Research and Economic Analysis of Development ,", "CESifo ,", "Institute of Labor Economics ,", "CReAM, Households in Conflict Network, and Global Labor Organization ,"]}, {"name": "Maria Micaela Sviatschi", "affiliations": ["Princeton University, National Bureau of Economic Research ,", "CESifo ,"]}], "abstract": "Abstract We conduct a randomized controlled trial to evaluate the effect of an innovative police patrol program on sexual harassment in public spaces in Hyderabad, India. In collaboration with the Hyderabad City Police, we randomize exposure to police patrols and the visibility of officers by deploying both uniformed and undercover officers across 350 hot spots. To assess the effect, we implement a novel, high-frequency observation exercise to measure sexual harassment at these hot spots, where enumerators recorded all observed instances of sexual harassment and women\u2019s responses in real time. We find that although police patrols had no effect on overall street harassment, uniformed police patrols reduced severe forms of harassment (forceful touching, intimidation) by 27% and reduced the likelihood of women leaving the hot spot due to sexual harassment. We uncovered the underlying mechanisms and found that both police visibility and officers\u2019 attitudes toward sexual harassment are key to understanding its incidence.", "date": "2025-05-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf026", "title_zh": "\u57ce\u5e02\u5370\u5ea6\u516c\u5171\u7a7a\u95f4\u4e2d\u7684\u6027\u9a9a\u6270\u4e0e\u8b66\u5bdf\u5de1\u903b\uff1a\u6765\u81ea\u6d77\u5f97\u62c9\u5df4\u7684\u5b9e\u9a8c\u8bc1\u636e", "abstract_zh": "\u6211\u4eec\u5f00\u5c55\u4e86\u4e00\u9879\u968f\u673a\u5bf9\u7167\u8bd5\u9a8c\uff0c\u4ee5\u8bc4\u4f30\u4e00\u9879\u521b\u65b0\u7684\u8b66\u5bdf\u5de1\u903b\u8ba1\u5212\u5bf9\u5370\u5ea6\u6d77\u5f97\u62c9\u5df4\u5e02\u516c\u5171\u7a7a\u95f4\u6027\u9a9a\u6270\u7684\u5f71\u54cd\u3002\u4e0e\u6d77\u5f97\u62c9\u5df4\u5e02\u8b66\u5bdf\u5c40\u5408\u4f5c\uff0c\u6211\u4eec\u968f\u673a\u5206\u914d\u8b66\u5bdf\u5de1\u903b\u66b4\u9732\u4ee5\u53ca\u8b66\u5bdf\u53ef\u89c1\u6027\uff0c\u901a\u8fc7\u90e8\u7f72\u5236\u670d\u8b66\u5bdf\u548c\u9690\u853d\u8b66\u5bdf\u8986\u76d6350\u4e2a\u70ed\u70b9\u533a\u57df\u3002\u4e3a\u4e86\u8bc4\u4f30\u5176\u6548\u679c\uff0c\u6211\u4eec\u5b9e\u65bd\u4e86\u4e00\u9879\u65b0\u9896\u7684\u9ad8\u9891\u89c2\u5bdf\u6d3b\u52a8\uff0c\u5b9e\u65f6\u8bb0\u5f55\u8fd9\u4e9b\u70ed\u70b9\u533a\u57df\u4e2d\u6240\u6709\u89c2\u5bdf\u5230\u7684\u6027\u9a9a\u6270\u4e8b\u4ef6\u4ee5\u53ca\u5973\u6027\u7684\u53cd\u5e94\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5c3d\u7ba1\u8b66\u5bdf\u5de1\u903b\u5bf9\u603b\u4f53\u8857\u5934\u6027\u9a9a\u6270\u6ca1\u6709\u5f71\u54cd\uff0c\u4f46\u5236\u670d\u8b66\u5bdf\u5de1\u903b\u5c06\u5f3a\u5236\u89e6\u6478\u548c\u6050\u5413\u7b49\u4e25\u91cd\u5f62\u5f0f\u7684\u6027\u9a9a\u6270\u51cf\u5c11\u4e8627%\uff0c\u5e76\u964d\u4f4e\u4e86\u5973\u6027\u56e0\u6027\u9a9a\u6270\u800c\u79bb\u5f00\u70ed\u70b9\u533a\u57df\u7684\u53ef\u80fd\u6027\u3002\u6211\u4eec\u63ed\u793a\u4e86\u5176\u80cc\u540e\u7684\u673a\u5236\uff0c\u53d1\u73b0\u8b66\u5bdf\u7684\u53ef\u89c1\u6027\u4ee5\u53ca\u8b66\u5bdf\u5bf9\u6027\u9a9a\u6270\u7684\u6001\u5ea6\u662f\u7406\u89e3\u5176\u53d1\u751f\u7684\u5173\u952e\u56e0\u7d20\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf025", "journal": "QJE", "title": "Manufacturing Revolutions: Industrial Policy and Industrialization in South Korea", "authors": ["Nathan Lane"], "author_details": [{"name": "Nathan Lane", "affiliations": ["University of Oxford, United Kingdom and CESifo ,"]}], "abstract": "Abstract I study the effect of industrial policies on industrial development by considering an important episode during the East Asian miracle: South Korea\u2019s heavy and chemical industry (HCI) drive, 1973\u20131979. Based on newly assembled data, I use the introduction and termination of industrial policies to study their effects during and after the intervention period. I reveal that HCI policies promoted the expansion and dynamic comparative advantage of directly targeted industries. Using variation in exposure to policies through the input-output network, I demonstrate that the policy indirectly benefited downstream users of targeted intermediates. The benefits of HCI persisted even after the policy ended, and some results took time to materialize. The findings suggest that the temporary drive shifted Korean manufacturing into more advanced markets and supported durable change. This study helps clarify the lessons drawn from the East Asian growth miracle.", "date": "2025-05-29", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf025", "title_zh": "\u5236\u9020\u4e1a\u9769\u547d\uff1a\u97e9\u56fd\u7684\u4ea7\u4e1a\u653f\u7b56\u4e0e\u5de5\u4e1a\u5316", "abstract_zh": "\u672c\u6587\u901a\u8fc7\u8003\u5bdf\u4e1c\u4e9a\u5947\u8ff9\u671f\u95f4\u7684\u4e00\u4e2a\u91cd\u8981\u4e8b\u4ef6\u2014\u20141973\u5e74\u81f31979\u5e74\u97e9\u56fd\u7684\u91cd\u5316\u5de5\u4e1a\uff08HCI\uff09\u53d1\u5c55\u653f\u7b56\uff0c\u7814\u7a76\u4ea7\u4e1a\u653f\u7b56\u5bf9\u5de5\u4e1a\u53d1\u5c55\u7684\u6548\u5e94\u3002\u57fa\u4e8e\u65b0\u6574\u7406\u7684\u6570\u636e\uff0c\u672c\u6587\u5229\u7528\u5de5\u4e1a\u653f\u7b56\u7684\u5f15\u5165\u548c\u7ec8\u6b62\u6765\u5206\u6790\u5176\u5728\u5e72\u9884\u671f\u95f4\u53ca\u5e72\u9884\u671f\u540e\u7684\u6548\u679c\u3002\u7814\u7a76\u53d1\u73b0\uff0cHCI\u653f\u7b56\u4fc3\u8fdb\u4e86\u76f4\u63a5\u76ee\u6807\u884c\u4e1a\u89c4\u6a21\u7684\u6269\u5f20\u548c\u52a8\u6001\u6bd4\u8f83\u4f18\u52bf\u7684\u5f62\u6210\u3002\u901a\u8fc7\u8f93\u5165-\u8f93\u51fa\u7f51\u7edc\u4e2d\u5bf9\u653f\u7b56\u66b4\u9732\u7a0b\u5ea6\u7684\u5dee\u5f02\uff0c\u672c\u6587\u8bc1\u660e\u4e86\u653f\u7b56\u5bf9\u76ee\u6807\u4e2d\u95f4\u4ea7\u54c1\u7684\u4e0b\u6e38\u4f7f\u7528\u8005\u4e5f\u4ea7\u751f\u4e86\u95f4\u63a5\u76ca\u5904\u3002HCI\u653f\u7b56\u7684\u76ca\u5904\u5728\u653f\u7b56\u7ec8\u6b62\u540e\u4f9d\u7136\u6301\u7eed\uff0c\u90e8\u5206\u6548\u679c\u9700\u8981\u65f6\u95f4\u624d\u80fd\u663e\u73b0\u3002\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u8fd9\u4e00\u77ed\u671f\u63a8\u52a8\u5c06\u97e9\u56fd\u5236\u9020\u4e1a\u5f15\u5bfc\u81f3\u66f4\u5148\u8fdb\u7684\u5e02\u573a\uff0c\u5e76\u652f\u6301\u4e86\u6301\u4e45\u6027\u7684\u53d8\u9769\u3002\u672c\u7814\u7a76\u6709\u52a9\u4e8e\u6f84\u6e05\u4ece\u4e1c\u4e9a\u589e\u957f\u5947\u8ff9\u4e2d\u5f97\u51fa\u7684\u7ecf\u9a8c\u6559\u8bad\u3002", "translation_source": "journal-qwen4b", "topics": ["\u7f51\u7edc"]}, {"doi": "10.1093/qje/qjaf021", "journal": "QJE", "title": "The Optimal Taxation of Couples", "authors": ["Mikhail Golosov", "Ilia Krasikov"], "author_details": [{"name": "Mikhail Golosov", "affiliations": ["University of Chicago ,"]}, {"name": "Ilia Krasikov", "affiliations": ["Arizona State University ,"]}], "abstract": "ABSTRACT We study optimal nonlinear taxation of single and married households. Taxes on couples depend on the earnings of both spouses and are an example of multidimensional tax schedules. We develop novel analytical techniques to study properties of such taxes. We show that the optimal marginal taxes for married individuals are generally lower than for single individuals because resource sharing in couples provides socially valuable redistribution. Under realistic assumptions, the optimal tax rates for married individuals increase with the correlation of spousal earnings, the marginal tax rates for one spouse increase (decrease) in the earnings of the other if both spouses have low (high) earnings, and the primary earner faces lower marginal taxes than the secondary earner.", "date": "2025-05-27", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf021", "title_zh": "\u592b\u59bb\u5bb6\u5ead\u7684\u6700\u4f18\u7a0e\u6536", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u5bf9\u5355\u8eab\u548c\u5df2\u5a5a\u5bb6\u5ead\u7684\u6700\u4f18\u975e\u7ebf\u6027\u7a0e\u6536\u3002\u5bf9\u592b\u59bb\u7684\u7a0e\u6536\u53d6\u51b3\u4e8e\u53cc\u65b9\u7684\u6536\u5165\uff0c\u662f\u591a\u7ef4\u7a0e\u6536\u4f53\u7cfb\u7684\u4e00\u4e2a\u4f8b\u5b50\u3002\u6211\u4eec\u53d1\u5c55\u4e86\u65b0\u7684\u5206\u6790\u6280\u672f\u6765\u7814\u7a76\u6b64\u7c7b\u7a0e\u6536\u7684\u6027\u8d28\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5728\u5927\u591a\u6570\u60c5\u51b5\u4e0b\uff0c\u5df2\u5a5a\u4e2a\u4f53\u7684\u6700\u4f18\u8fb9\u9645\u7a0e\u7387\u901a\u5e38\u4f4e\u4e8e\u5355\u8eab\u4e2a\u4f53\uff0c\u56e0\u4e3a\u592b\u59bb\u95f4\u7684\u8d44\u6e90\u5171\u4eab\u5177\u6709\u793e\u4f1a\u4ef7\u503c\u7684\u518d\u5206\u914d\u4f5c\u7528\u3002\u5728\u73b0\u5b9e\u5047\u8bbe\u4e0b\uff0c\u5df2\u5a5a\u4e2a\u4f53\u7684\u6700\u4f18\u7a0e\u7387\u968f\u914d\u5076\u6536\u5165\u76f8\u5173\u6027\u7684\u589e\u52a0\u800c\u4e0a\u5347\uff1b\u5f53\u53cc\u65b9\u6536\u5165\u8f83\u4f4e\u65f6\uff0c\u4e00\u65b9\u914d\u5076\u7684\u8fb9\u9645\u7a0e\u7387\u968f\u53e6\u4e00\u65b9\u6536\u5165\u7684\u589e\u52a0\u800c\u4e0a\u5347\uff1b\u5f53\u53cc\u65b9\u6536\u5165\u8f83\u9ad8\u65f6\uff0c\u4e00\u65b9\u914d\u5076\u7684\u8fb9\u9645\u7a0e\u7387\u968f\u53e6\u4e00\u65b9\u6536\u5165\u7684\u589e\u52a0\u800c\u4e0b\u964d\uff1b\u4e3b\u8981\u6536\u5165\u8005\u9762\u4e34\u7684\u8fb9\u9645\u7a0e\u7387\u4f4e\u4e8e\u6b21\u8981\u6536\u5165\u8005\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf024", "journal": "QJE", "title": "Collective Bargaining for Women: How Unions Can Create Female-Friendly Jobs", "authors": ["Viola Corradini", "Lorenzo Lagos", "Garima Sharma"], "author_details": [{"name": "Viola Corradini", "affiliations": ["Columbia University ,"]}, {"name": "Lorenzo Lagos", "affiliations": ["Brown University ,"]}, {"name": "Garima Sharma", "affiliations": ["Northwestern University ,"]}], "abstract": "ABSTRACT We study the role of unions in improving workplaces for women. Starting in 2015, Brazil\u2019s largest trade union federation made women central to its agenda. Using a difference-in-differences design that leverages variation in union affiliation to this federation, we find that \u201cbargaining for women\u201d increased female-friendly amenities in collective bargaining agreements and in practice. These changes led women to queue for jobs at treated establishments and separate from them less\u2014both revealed-preference measures of firm value. We find no evidence that gains came at the expense of wages, employment, or firm profits. Better amenities instead reduced turnover and absenteeism, suggesting greater worker satisfaction and effort. Larger improvements occurred where women initially composed a lower share of workers or union leaders. Our findings show that shifting union priorities toward women improved workplaces without meaningful trade-offs and benefited both workers and employers. They illustrate the potential for unions to improve workplace quality by focusing on the needs of less represented workers.", "date": "2025-05-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf024", "title_zh": "\u4e3a\u5973\u6027\u4e89\u53d6\u6743\u76ca\uff1a\u5de5\u4f1a\u5982\u4f55\u521b\u9020\u5973\u6027\u53cb\u597d\u578b\u5c97\u4f4d", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u7814\u7a76\u4e86\u5de5\u4f1a\u5728\u6539\u5584\u5973\u6027\u5de5\u4f5c\u73af\u5883\u4e2d\u7684\u4f5c\u7528\u3002\u81ea2015\u5e74\u8d77\uff0c\u5df4\u897f\u6700\u5927\u7684\u5de5\u4f1a\u8054\u5408\u4f1a\u5c06\u5973\u6027\u95ee\u9898\u7f6e\u4e8e\u5176\u8bae\u7a0b\u7684\u6838\u5fc3\u3002\u5229\u7528\u57fa\u4e8e\u5de5\u4f1a\u96b6\u5c5e\u5173\u7cfb\u53d8\u5316\u7684\u53cc\u91cd\u5dee\u5206\u8bbe\u8ba1\uff0c\u6211\u4eec\u53d1\u73b0\u201c\u4e3a\u5973\u6027\u8c08\u5224\u201d\u663e\u8457\u63d0\u5347\u4e86\u96c6\u4f53\u8c08\u5224\u534f\u8bae\u4e2d\u7684\u5973\u6027\u53cb\u597d\u578b\u8bbe\u65bd\uff0c\u5e76\u5728\u5b9e\u9645\u64cd\u4f5c\u4e2d\u4f53\u73b0\u51fa\u6765\u3002\u8fd9\u4e9b\u53d8\u5316\u5bfc\u81f4\u5973\u6027\u66f4\u613f\u610f\u6392\u961f\u7533\u8bf7\u5728\u5904\u7406\u5355\u4f4d\u7684\u804c\u4f4d\uff0c\u5e76\u51cf\u5c11\u79bb\u804c\u884c\u4e3a\u2014\u2014\u8fd9\u4e24\u9879\u90fd\u662f\u4f01\u4e1a\u4ef7\u503c\u7684\u76f4\u63a5\u53cd\u6620\u3002\u6211\u4eec\u672a\u53d1\u73b0\u8fd9\u4e9b\u6536\u76ca\u662f\u4ee5\u5de5\u8d44\u3001\u5c31\u4e1a\u6216\u4f01\u4e1a\u5229\u6da6\u7684\u635f\u5931\u4e3a\u4ee3\u4ef7\u7684\u3002\u66f4\u597d\u7684\u5de5\u4f5c\u6761\u4ef6\u964d\u4f4e\u4e86\u5458\u5de5\u6d41\u52a8\u7387\u548c\u7f3a\u52e4\u7387\uff0c\u8868\u660e\u5458\u5de5\u6ee1\u610f\u5ea6\u548c\u5de5\u4f5c\u6295\u5165\u6709\u6240\u63d0\u5347\u3002\u5728\u6700\u521d\u5973\u6027\u5458\u5de5\u6bd4\u4f8b\u8f83\u4f4e\u6216\u5de5\u4f1a\u9886\u5bfc\u4eba\u4e2d\u5973\u6027\u6bd4\u4f8b\u8f83\u4f4e\u7684\u5730\u533a\uff0c\u6539\u5584\u6548\u679c\u66f4\u4e3a\u663e\u8457\u3002\u6211\u4eec\u7684\u7814\u7a76\u7ed3\u679c\u8868\u660e\uff0c\u5c06\u5de5\u4f1a\u7684\u91cd\u70b9\u8f6c\u5411\u5973\u6027\uff0c\u80fd\u591f\u6539\u5584\u5de5\u4f5c\u73af\u5883\uff0c\u4e14\u4e0d\u4ea7\u751f\u91cd\u5927\u6743\u8861\uff0c\u65e2\u6709\u5229\u4e8e\u5458\u5de5\u4e5f\u5229\u4e8e\u4f01\u4e1a\u3002\u8fd9\u8bf4\u660e\u5de5\u4f1a\u53ef\u4ee5\u901a\u8fc7\u5173\u6ce8\u8f83\u5c11\u4ee3\u8868\u7fa4\u4f53\u7684\u9700\u6c42\uff0c\u6765\u63d0\u5347\u5de5\u4f5c\u573a\u6240\u7684\u8d28\u91cf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf023", "journal": "QJE", "title": "Lives Versus Livelihoods: The Impact of the Great Recession on Mortality and Welfare", "authors": ["Amy Finkelstein", "Matthew J Notowidigdo", "Frank Schilbach", "Jonathan Zhang"], "author_details": [{"name": "Amy Finkelstein", "affiliations": ["Massachusetts Institute of Technology and National Bureau of Economic Research ,"]}, {"name": "Matthew J Notowidigdo", "affiliations": ["University of Chicago and National Bureau of Economic Research ,"]}, {"name": "Frank Schilbach", "affiliations": ["Massachusetts Institute of Technology and National Bureau of Economic Research ,"]}, {"name": "Jonathan Zhang", "affiliations": ["Duke University and National Bureau of Economic Research ,"]}], "abstract": "ABSTRACT We leverage spatial variation in the severity of the Great Recession across the United States to examine its impact on mortality and explore the quantitative implications. We estimate that an increase in the unemployment rate of the magnitude of the Great Recession reduces the average annual age-adjusted mortality rate by 2.3%, with effects persisting for at least 10 years. Mortality reductions appear across causes of death and are concentrated in the half of the population with a high school degree or less. We estimate similar percentage reductions in mortality at all ages, with declines in elderly mortality thus responsible for about three-quarters of the total mortality reduction. Recession-induced mortality declines are driven primarily by external effects of reduced aggregate economic activity on mortality, and reduced air pollution appears to be a quantitatively important mechanism. Incorporating our estimates of procyclical mortality into a standard macroeconomic framework substantially reduces the welfare costs of recessions, particularly for people with less education, and at older ages.", "date": "2025-05-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf023", "title_zh": "\u751f\u547d\u8fd8\u662f\u751f\u8ba1\uff1a\u5927\u8870\u9000\u5bf9\u6b7b\u4ea1\u7387\u548c\u798f\u5229\u7684\u5f71\u54cd", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5229\u7528\u7f8e\u56fd\u5927\u8870\u9000\u4e25\u91cd\u7a0b\u5ea6\u5728\u7a7a\u95f4\u4e0a\u7684\u5dee\u5f02\uff0c\u7814\u7a76\u5176\u5bf9\u6b7b\u4ea1\u7387\u7684\u5f71\u54cd\uff0c\u5e76\u63a2\u8ba8\u5176\u5b9a\u91cf\u610f\u4e49\u3002\u6211\u4eec\u4f30\u8ba1\uff0c\u4e0e\u5927\u8870\u9000\u540c\u7b49\u7a0b\u5ea6\u7684\u5931\u4e1a\u7387\u4e0a\u5347\u4f1a\u4f7f\u5e73\u5747\u6bcf\u5e74\u7684\u5e74\u9f84\u8c03\u6574\u6b7b\u4ea1\u7387\u4e0b\u964d2.3%\uff0c\u8fd9\u4e00\u5f71\u54cd\u6301\u7eed\u81f3\u5c1110\u5e74\u3002\u6b7b\u4ea1\u7387\u7684\u4e0b\u964d\u51fa\u73b0\u5728\u5404\u7c7b\u6b7b\u4ea1\u539f\u56e0\u4e2d\uff0c\u5e76\u96c6\u4e2d\u5728\u9ad8\u4e2d\u5b66\u5386\u6216\u4ee5\u4e0b\u7684\u534a\u6570\u4eba\u53e3\u4e2d\u3002\u6211\u4eec\u4f30\u8ba1\u5728\u6240\u6709\u5e74\u9f84\u7fa4\u4f53\u4e2d\uff0c\u6b7b\u4ea1\u7387\u5747\u51fa\u73b0\u76f8\u4f3c\u6bd4\u4f8b\u7684\u4e0b\u964d\uff0c\u5176\u4e2d\u8001\u5e74\u4eba\u6b7b\u4ea1\u7387\u7684\u4e0b\u964d\u7ea6\u5360\u603b\u6b7b\u4ea1\u7387\u4e0b\u964d\u7684\u56db\u5206\u4e4b\u4e09\u3002\u7531\u6574\u4f53\u7ecf\u6d4e\u6d3b\u52a8\u51cf\u5c11\u5f15\u53d1\u7684\u6b7b\u4ea1\u7387\u4e0b\u964d\u4e3b\u8981\u6e90\u4e8e\u5916\u90e8\u6548\u5e94\uff0c\u800c\u7a7a\u6c14\u6c61\u67d3\u7684\u51cf\u5c11\u4f3c\u4e4e\u662f\u4e00\u4e2a\u5177\u6709\u91cd\u8981\u6570\u91cf\u610f\u4e49\u7684\u673a\u5236\u3002\u5c06\u6211\u4eec\u4f30\u8ba1\u7684\u5468\u671f\u6027\u6b7b\u4ea1\u7387\u7eb3\u5165\u6807\u51c6\u5b8f\u89c2\u7ecf\u6d4e\u6846\u67b6\u540e\uff0c\u663e\u8457\u964d\u4f4e\u4e86\u7ecf\u6d4e\u8870\u9000\u7684\u798f\u5229\u6210\u672c\uff0c\u5c24\u5176\u5bf9\u6559\u80b2\u6c34\u5e73\u8f83\u4f4e\u7684\u4eba\u7fa4\u4ee5\u53ca\u8001\u5e74\u4eba\u800c\u8a00\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf022", "journal": "QJE", "title": "Systemic Discrimination: Theory and Measurement", "authors": ["J Aislinn Bohren", "Peter Hull", "Alex Imas"], "author_details": [{"name": "J Aislinn Bohren", "affiliations": ["University of Pennslyvania ,"]}, {"name": "Peter Hull", "affiliations": ["Brown University ,"]}, {"name": "Alex Imas", "affiliations": ["University of Chicago ,"]}], "abstract": "Abstract Economists often measure discrimination as disparities arising from the direct effects of group identity. We develop new tools to model and measure systemic discrimination, capturing how discrimination in other decisions indirectly contributes to disparities. A novel experimental design, the iterated audit, identifies systemic discrimination. We illustrate these new tools in two field experiments. The first experiment shows how racial discrimination can accumulate across multiple rounds of hiring through the interaction of two forces: greater discrimination against inexperienced workers, which affects the opportunity to obtain experience, and high subsequent returns to experience. The second experiment shows how gender-based differences in the language of recommendation letters can translate into systemic gender discrimination in STEM hiring. We discuss how our findings qualify previous results on direct discrimination and how our tools can be used to target policy interventions.", "date": "2025-05-01", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf022", "title_zh": "\u7cfb\u7edf\u6027\u6b67\u89c6\uff1a\u7406\u8bba\u4e0e\u6d4b\u91cf", "abstract_zh": "\u7ecf\u6d4e\u5b66\u5bb6\u901a\u5e38\u5c06\u6b67\u89c6\u8861\u91cf\u4e3a\u7fa4\u4f53\u8eab\u4efd\u76f4\u63a5\u6548\u5e94\u5bfc\u81f4\u7684\u5dee\u5f02\u3002\u6211\u4eec\u5f00\u53d1\u4e86\u65b0\u7684\u5de5\u5177\u6765\u5efa\u6a21\u548c\u6d4b\u91cf\u7cfb\u7edf\u6027\u6b67\u89c6\uff0c\u6355\u6349\u5230\u5728\u5176\u4ed6\u51b3\u7b56\u4e2d\u51fa\u73b0\u7684\u6b67\u89c6\u5982\u4f55\u95f4\u63a5\u5bfc\u81f4\u4e0d\u5e73\u7b49\u3002\u4e00\u79cd\u65b0\u9896\u7684\u5b9e\u9a8c\u8bbe\u8ba1\u2014\u2014\u8fed\u4ee3\u5ba1\u8ba1\uff0c\u80fd\u591f\u8bc6\u522b\u7cfb\u7edf\u6027\u6b67\u89c6\u3002\u6211\u4eec\u901a\u8fc7\u4e24\u4e2a\u5b9e\u5730\u5b9e\u9a8c\u5c55\u793a\u4e86\u8fd9\u4e9b\u65b0\u5de5\u5177\u7684\u5e94\u7528\u3002\u7b2c\u4e00\u4e2a\u5b9e\u9a8c\u8868\u660e\uff0c\u79cd\u65cf\u6b67\u89c6\u53ef\u4ee5\u901a\u8fc7\u591a\u8f6e\u62db\u8058\u4e2d\u7684\u76f8\u4e92\u4f5c\u7528\u7d2f\u79ef\uff0c\u6d89\u53ca\u4e24\u4e2a\u56e0\u7d20\uff1a\u5bf9\u7f3a\u4e4f\u7ecf\u9a8c\u5de5\u4eba\u7684\u6b67\u89c6\u7a0b\u5ea6\u66f4\u9ad8\uff0c\u8fd9\u5f71\u54cd\u4e86\u83b7\u5f97\u7ecf\u9a8c\u7684\u673a\u4f1a\uff0c\u4ee5\u53ca\u7ecf\u9a8c\u540e\u7eed\u5e26\u6765\u7684\u9ad8\u56de\u62a5\u3002\u7b2c\u4e8c\u4e2a\u5b9e\u9a8c\u8868\u660e\uff0c\u6027\u522b\u5728\u63a8\u8350\u4fe1\u8bed\u8a00\u4e0a\u7684\u5dee\u5f02\u4f1a\u8f6c\u5316\u4e3aSTEM\u9886\u57df\u62db\u8058\u4e2d\u7684\u7cfb\u7edf\u6027\u6027\u522b\u6b67\u89c6\u3002\u6211\u4eec\u8ba8\u8bba\u4e86\u8fd9\u4e9b\u53d1\u73b0\u5982\u4f55\u4fee\u6b63\u4ee5\u5f80\u5173\u4e8e\u76f4\u63a5\u6b67\u89c6\u7684\u7814\u7a76\u7ed3\u679c\uff0c\u4ee5\u53ca\u6211\u4eec\u7684\u5de5\u5177\u5982\u4f55\u7528\u4e8e\u7cbe\u51c6\u8bbe\u8ba1\u653f\u7b56\u5e72\u9884\u63aa\u65bd\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf020", "journal": "QJE", "title": "Revealed Beliefs and the Marriage Market Return to Education", "authors": ["Alison Andrew", "Abi Adams"], "author_details": [{"name": "Alison Andrew", "affiliations": ["University of Oxford and Institute for Fiscal Studies ,"]}, {"name": "Abi Adams", "affiliations": ["University of Oxford and Institute for Fiscal Studies ,"]}], "abstract": "Abstract We develop a new methodology to estimate subjective beliefs from hypothetical-choice data. Our identification approach is based on the novel insight that by varying the amount of information on future realizations of stochastic variables, discrete-choice experiments can identify not only preferences but also subjective beliefs. We formally prove this result in a general setting and apply it to design a strategic survey instrument to measure Rajasthani parents\u2019 subjective beliefs over the joint distribution of girls\u2019 age of marriage, education, and marriage match quality. Our approach allows us to quantify the importance of perceived marriage market returns to education and youth, and perform various counterfactual simulation exercises. We find that eliminating the perceived marriage market return to education causes a 60% drop in the number of girls still in school at age 16, and almost none continue their education by age 18. Responses to our strategic survey instrument allow us accurately to predict realized schooling trajectories in follow-up data we collect from the same sample five years after our experimental data collection.", "date": "2025-04-15", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf020", "title_zh": "\u63ed\u793a\u7684\u4fe1\u5ff5\u4e0e\u5a5a\u59fb\u5e02\u573a\u4e2d\u6559\u80b2\u7684\u56de\u62a5", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u5f00\u53d1\u4e86\u4e00\u79cd\u4ece\u5047\u8bbe\u6027\u9009\u62e9\u6570\u636e\u4e2d\u4f30\u8ba1\u4e3b\u89c2\u4fe1\u5ff5\u7684\u65b0\u65b9\u6cd5\u3002\u6211\u4eec\u7684\u8bc6\u522b\u65b9\u6cd5\u57fa\u4e8e\u4e00\u4e2a\u65b0\u9896\u7684\u89c1\u89e3\uff1a\u901a\u8fc7\u6539\u53d8\u5bf9\u672a\u6765\u968f\u673a\u53d8\u91cf\u5b9e\u73b0\u503c\u7684\u4fe1\u606f\u91cf\uff0c\u79bb\u6563\u9009\u62e9\u5b9e\u9a8c\u4e0d\u4ec5\u80fd\u8bc6\u522b\u504f\u597d\uff0c\u8fd8\u80fd\u8bc6\u522b\u4e3b\u89c2\u4fe1\u5ff5\u3002\u6211\u4eec\u5728\u4e00\u822c\u60c5\u5883\u4e0b\u6b63\u5f0f\u8bc1\u660e\u4e86\u8fd9\u4e00\u7ed3\u679c\uff0c\u5e76\u5c06\u5176\u5e94\u7528\u4e8e\u8bbe\u8ba1\u4e00\u79cd\u6218\u7565\u6027\u7684\u8c03\u67e5\u5de5\u5177\uff0c\u4ee5\u6d4b\u91cf\u62c9\u8d3e\u65af\u5766\u90a6\u7236\u6bcd\u5bf9\u5973\u5b69\u7ed3\u5a5a\u5e74\u9f84\u3001\u6559\u80b2\u6c34\u5e73\u548c\u5a5a\u59fb\u5339\u914d\u8d28\u91cf\u8054\u5408\u5206\u5e03\u7684\u4e3b\u89c2\u4fe1\u5ff5\u3002\u6211\u4eec\u7684\u65b9\u6cd5\u4f7f\u5f97\u80fd\u591f\u91cf\u5316\u4eba\u4eec\u5bf9\u6559\u80b2\u548c\u5e74\u8f7b\u65f6\u671f\u5a5a\u59fb\u5e02\u573a\u56de\u62a5\u7684\u611f\u77e5\u91cd\u8981\u6027\uff0c\u5e76\u8fdb\u884c\u5404\u79cd\u53cd\u4e8b\u5b9e\u6a21\u62df\u5b9e\u9a8c\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u6d88\u9664\u5bf9\u6559\u80b2\u7684\u5a5a\u59fb\u5e02\u573a\u56de\u62a5\u4f1a\u5bfc\u81f416\u5c81\u65f6\u4ecd\u5728\u6821\u7684\u5973\u5b69\u6570\u91cf\u4e0b\u964d60%\uff0c\u51e0\u4e4e\u6ca1\u6709\u4efb\u4f55\u5973\u5b69\u572818\u5c81\u65f6\u7ee7\u7eed\u63a5\u53d7\u6559\u80b2\u3002\u5bf9\u6211\u4eec\u7684\u6218\u7565\u6027\u8c03\u67e5\u5de5\u5177\u7684\u56de\u5e94\u80fd\u591f\u51c6\u786e\u9884\u6d4b\u6211\u4eec\u4e94\u5e74\u540e\u4ece\u540c\u4e00\u6837\u672c\u4e2d\u6536\u96c6\u7684\u540e\u7eed\u6570\u636e\u4e2d\u7684\u5b9e\u9645\u5c31\u5b66\u8f68\u8ff9\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf019", "journal": "QJE", "title": "The Evolutionary Stability of Moral Foundations", "authors": ["Michelle Avataneo", "Thomas Norman", "Nicola Persico"], "author_details": [{"name": "Michelle Avataneo", "affiliations": ["Northwestern University ,"]}, {"name": "Thomas Norman", "affiliations": ["Magdalen College, Oxford ,"]}, {"name": "Nicola Persico", "affiliations": ["Northwestern University ,"]}], "abstract": "ABSTRACT Moral foundations theory is an influential empirical description of moral perception. According to this theory, individuals make moral judgments based on five distinct \u201cmoral foundations\u201d: care, fairness, loyalty, authority, and sanctity. We provide a theory that explores the claimed evolutionary basis for these moral foundations. The theory conceptualizes these five moral foundations as specific modifications of fitness payoffs in a 2 \u00d7 2 game. We find that the five foundations are distinguishable from each other and evolutionarily stable. However, they are not a minimal set: strict subsets of the foundations suffice to describe all preferences that are evolutionarily stable. Not all evolutionarily stable foundations deliver social fitness improvement over the Nash equilibrium in the fitness game: we characterize which do. Finally, we study moral overdrive, that is, the situation in which the moral component of preferences totally dominates fitness payoffs and drives decision making entirely. While every one of the five foundations is compatible with moral overdrive in at least one fitness game, there is no fitness game in which moral overdrive is compatible with social fitness improvement. These results are partially extended to n \u00d7 n games. We derive two testable implications from the theory and find empirical support for them.", "date": "2025-04-11", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf019", "title_zh": "\u9053\u5fb7\u57fa\u7840\u7684\u6f14\u5316\u7a33\u5b9a\u6027", "abstract_zh": "\u6458\u8981 \u9053\u5fb7\u57fa\u7840\u7406\u8bba\u662f\u5173\u4e8e\u9053\u5fb7\u611f\u77e5\u7684\u4e00\u79cd\u6709\u5f71\u54cd\u529b\u7684\u7ecf\u9a8c\u63cf\u8ff0\u3002\u6839\u636e\u8be5\u7406\u8bba\uff0c\u4e2a\u4f53\u57fa\u4e8e\u4e94\u4e2a\u4e0d\u540c\u7684\u201c\u9053\u5fb7\u57fa\u7840\u201d\u505a\u51fa\u9053\u5fb7\u5224\u65ad\uff1a\u5173\u6000\u3001\u516c\u5e73\u3001\u5fe0\u8bda\u3001\u6743\u5a01\u548c\u5723\u6d01\u3002\u672c\u6587\u63d0\u51fa\u4e00\u79cd\u7406\u8bba\uff0c\u63a2\u8ba8\u8fd9\u4e9b\u9053\u5fb7\u57fa\u7840\u6240\u58f0\u79f0\u7684\u6f14\u5316\u57fa\u7840\u3002\u8be5\u7406\u8bba\u5c06\u8fd9\u4e94\u4e2a\u9053\u5fb7\u57fa\u7840\u6982\u5ff5\u5316\u4e3a2\u00d72\u535a\u5f08\u4e2d\u9002\u5e94\u5ea6\u652f\u4ed8\u7684\u7279\u5b9a\u4fee\u6539\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u8fd9\u4e94\u4e2a\u57fa\u7840\u5f7c\u6b64\u53ef\u533a\u5206\uff0c\u5e76\u4e14\u5728\u6f14\u5316\u4e0a\u662f\u7a33\u5b9a\u7684\u3002\u7136\u800c\uff0c\u5b83\u4eec\u5e76\u975e\u6700\u5c0f\u96c6\u5408\uff1a\u57fa\u7840\u7684\u4e25\u683c\u5b50\u96c6\u8db3\u4ee5\u63cf\u8ff0\u6240\u6709\u6f14\u5316\u4e0a\u7a33\u5b9a\u7684\u504f\u597d\u3002\u5e76\u975e\u6240\u6709\u6f14\u5316\u4e0a\u7a33\u5b9a\u7684\u9053\u5fb7\u57fa\u7840\u90fd\u80fd\u5728\u9002\u5e94\u5ea6\u535a\u5f08\u4e2d\u5e26\u6765\u8d85\u8fc7\u7eb3\u4ec0\u5747\u8861\u7684\u793e\u4f1a\u9002\u5e94\u5ea6\u63d0\u5347\uff1a\u6211\u4eec\u6307\u51fa\u4e86\u54ea\u4e9b\u57fa\u7840\u786e\u5b9e\u5982\u6b64\u3002\u6700\u540e\uff0c\u6211\u4eec\u7814\u7a76\u4e86\u9053\u5fb7\u8fc7\u8f7d\u73b0\u8c61\uff0c\u5373\u9053\u5fb7\u504f\u597d\u5b8c\u5168\u4e3b\u5bfc\u9002\u5e94\u5ea6\u652f\u4ed8\u5e76\u4e3b\u5bfc\u51b3\u7b56\u7684\u60c5\u51b5\u3002\u5c3d\u7ba1\u6bcf\u4e2a\u57fa\u7840\u5728\u81f3\u5c11\u4e00\u4e2a\u9002\u5e94\u5ea6\u535a\u5f08\u4e2d\u4e0e\u9053\u5fb7\u8fc7\u8f7d\u517c\u5bb9\uff0c\u4f46\u4e0d\u5b58\u5728\u4e00\u4e2a\u9002\u5e94\u5ea6\u535a\u5f08\uff0c\u4f7f\u5f97\u9053\u5fb7\u8fc7\u8f7d\u4e0e\u793e\u4f1a\u9002\u5e94\u5ea6\u63d0\u5347\u540c\u65f6\u6210\u7acb\u3002\u8fd9\u4e9b\u7ed3\u679c\u90e8\u5206\u6269\u5c55\u5230\u4e86n\u00d7n\u535a\u5f08\u3002\u6211\u4eec\u4ece\u7406\u8bba\u4e2d\u63a8\u5bfc\u51fa\u4e24\u4e2a\u53ef\u68c0\u9a8c\u7684\u63a8\u8bba\uff0c\u5e76\u53d1\u73b0\u4e86\u5bf9\u8fd9\u4e9b\u63a8\u8bba\u7684\u5b9e\u8bc1\u652f\u6301\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf018", "journal": "QJE", "title": "Structural Estimation Under Misspecification: Theory and Implications for Practice", "authors": ["Isaiah Andrews", "Nano Barahona", "Matthew Gentzkow", "Ashesh Rambachan", "Jesse M Shapiro"], "author_details": [{"name": "Isaiah Andrews", "affiliations": ["Massachusetts Institute of Technology and National Bureau of Economic Research ,"]}, {"name": "Nano Barahona", "affiliations": ["University of California, Berkeley, and National Bureau of Economic Research ,"]}, {"name": "Matthew Gentzkow", "affiliations": ["Stanford University and National Bureau of Economic Research ,"]}, {"name": "Ashesh Rambachan", "affiliations": ["Massachusetts Institute of Technology ,"]}, {"name": "Jesse M Shapiro", "affiliations": ["Harvard University and National Bureau of Economic Research ,"]}], "abstract": "ABSTRACT A researcher can use a tightly parameterized structural model to obtain internally consistent estimates of a wide range of economically interesting targets. We ask how reliable these estimates are when the researcher\u2019s model may be misspecified. We focus on the case of multivariate, potentially nonlinear models where the causal variable of interest is endogenous. Reliable estimates require that the researcher\u2019s model is flexible enough to describe the effects of the endogenous variable approximately correctly. Reliable estimates do not require that the researcher has correctly specified the role of the exogenous controls in the model. However, if the role of the controls is misspecified, reliable estimates require a property we call strong exclusion. Strong exclusion depends on having sufficiently many instruments that are unrelated to the controls. We discuss how practitioners can achieve strong exclusion, and illustrate our findings with an application to a differentiated goods model of demand for beer.", "date": "2025-03-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf018", "title_zh": "\u53c2\u6570\u8bbe\u5b9a\u4e0d\u51c6\u786e\u60c5\u51b5\u4e0b\u7684\u7ed3\u6784\u4f30\u8ba1\uff1a\u7406\u8bba\u53ca\u5176\u5bf9\u5b9e\u8df5\u7684\u542f\u793a", "abstract_zh": "\u6458\u8981 \u7814\u7a76\u8005\u53ef\u4ee5\u4f7f\u7528\u9ad8\u5ea6\u53c2\u6570\u5316\u7684\u7ed3\u6784\u6a21\u578b\uff0c\u83b7\u5f97\u4e00\u7cfb\u5217\u5177\u6709\u7ecf\u6d4e\u610f\u4e49\u7684\u5185\u90e8\u4e00\u81f4\u4f30\u8ba1\u503c\u3002\u6211\u4eec\u63a2\u8ba8\u5f53\u7814\u7a76\u8005\u7684\u6a21\u578b\u53ef\u80fd\u5b58\u5728\u8bbe\u5b9a\u9519\u8bef\u65f6\uff0c\u8fd9\u4e9b\u4f30\u8ba1\u503c\u7684\u53ef\u9760\u6027\u5982\u4f55\u3002\u6211\u4eec\u91cd\u70b9\u5173\u6ce8\u591a\u53d8\u91cf\u3001\u53ef\u80fd\u975e\u7ebf\u6027\u7684\u6a21\u578b\uff0c\u5176\u4e2d\u611f\u5174\u8da3\u7684\u56e0\u679c\u53d8\u91cf\u662f\u5185\u751f\u7684\u3002\u8981\u83b7\u5f97\u53ef\u9760\u7684\u4f30\u8ba1\uff0c\u7814\u7a76\u8005\u7684\u6a21\u578b\u5fc5\u987b\u8db3\u591f\u7075\u6d3b\uff0c\u4ee5\u8fd1\u4f3c\u6b63\u786e\u5730\u63cf\u8ff0\u5185\u751f\u53d8\u91cf\u7684\u5f71\u54cd\u3002\u53ef\u9760\u7684\u4f30\u8ba1\u5e76\u4e0d\u8981\u6c42\u7814\u7a76\u8005\u6b63\u786e\u6307\u5b9a\u4e86\u5916\u751f\u63a7\u5236\u53d8\u91cf\u5728\u6a21\u578b\u4e2d\u7684\u4f5c\u7528\u3002\u7136\u800c\uff0c\u5982\u679c\u63a7\u5236\u53d8\u91cf\u7684\u4f5c\u7528\u88ab\u9519\u8bef\u8bbe\u5b9a\uff0c\u53ef\u9760\u7684\u4f30\u8ba1\u5219\u9700\u8981\u4e00\u4e2a\u6211\u4eec\u79f0\u4e4b\u4e3a\u201c\u5f3a\u6392\u9664\u201d\u7684\u6027\u8d28\u3002\u5f3a\u6392\u9664\u4f9d\u8d56\u4e8e\u62e5\u6709\u8db3\u591f\u591a\u4e0e\u63a7\u5236\u53d8\u91cf\u65e0\u5173\u7684\u5de5\u5177\u53d8\u91cf\u3002\u6211\u4eec\u8ba8\u8bba\u4e86\u5b9e\u8df5\u8005\u5982\u4f55\u5b9e\u73b0\u5f3a\u6392\u9664\uff0c\u5e76\u4ee5\u4e00\u4e2a\u5dee\u5f02\u5316\u5546\u54c1\u9700\u6c42\u6a21\u578b\uff08\u5564\u9152\u9700\u6c42\uff09\u7684\u5e94\u7528\u4e3a\u4f8b\u8bf4\u660e\u6211\u4eec\u7684\u53d1\u73b0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf017", "journal": "QJE", "title": "\u201cDescended from Immigrants and Revolutionists\u201d: How Family History Shapes Immigration Policy Making", "authors": ["James Feigenbaum", "Maxwell Palmer", "Benjamin Schneer"], "author_details": [{"name": "James Feigenbaum", "affiliations": ["Boston University and National Bureau of Economic Research ,"]}, {"name": "Maxwell Palmer", "affiliations": ["Boston University ,"]}, {"name": "Benjamin Schneer", "affiliations": ["Harvard Kennedy School ,"]}], "abstract": "Abstract Does family history matter for policy making in democracies? Linking members of Congress (MCs) to the census, we observe countries of birth for members, their parents, and their grandparents, allowing us to measure ancestry for the politicians in office when U.S. immigration policy changed dramatically, from closing the border in the 1920s to reshaping admittance criteria in the 1960s. We find that legislators descended from immigrant parents or grandparents support more permissive immigration legislation. They are also less likely to speak negatively about immigration in speeches before Congress. A regression discontinuity design analyzing close elections, which addresses district-level selection and holds district composition constant, confirms our results on roll call voting and speech. Efforts to account for selection into immigration\u2014such as comparing international immigrants to domestic migrants and exploiting variation in restrictive legislation targeting specific regions of origin\u2014further confirm the relationship between family immigration experience and more permissive stances on immigration policy. We then explore mechanisms, finding support for in-group identity in connecting family history with policy making. MCs name their children in ways that express immigrant identity, and immigrant-descended MCs discuss immigration using more personal frames, emphasizing family over economic considerations. Our findings illustrate the important role of personal background in legislative behavior in democratic societies, even on major and controversial topics like immigration, and suggest how experiences transmitted from previous generations can inform lawmakers\u2019 views.", "date": "2025-03-12", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf017", "title_zh": "\u201c\u6e90\u81ea\u79fb\u6c11\u4e0e\u9769\u547d\u8005\u540e\u4ee3\u201d\uff1a\u5bb6\u65cf\u5386\u53f2\u5982\u4f55\u5f71\u54cd\u79fb\u6c11\u653f\u7b56\u5236\u5b9a", "abstract_zh": "\u6458\u8981 \u5bb6\u65cf\u5386\u53f2\u662f\u5426\u4f1a\u5f71\u54cd\u6c11\u4e3b\u56fd\u5bb6\u7684\u653f\u7b56\u5236\u5b9a\uff1f\u6211\u4eec\u901a\u8fc7\u5c06\u56fd\u4f1a\u8bae\u5458\u4e0e\u4eba\u53e3\u666e\u67e5\u6570\u636e\u5173\u8054\uff0c\u89c2\u5bdf\u56fd\u4f1a\u8bae\u5458\u7684\u51fa\u751f\u56fd\u5bb6\u3001\u7236\u6bcd\u548c\u7956\u7236\u6bcd\u7684\u56fd\u7c4d\uff0c\u4ece\u800c\u6d4b\u91cf\u572820\u4e16\u7eaa20\u5e74\u4ee3\u8fb9\u5883\u5173\u95ed\u523060\u5e74\u4ee3\u79fb\u6c11\u6807\u51c6\u91cd\u5851\u671f\u95f4\uff0c\u6267\u653f\u8bae\u5458\u7684\u65cf\u88d4\u80cc\u666f\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u90a3\u4e9b\u7236\u6bcd\u6216\u7956\u7236\u6bcd\u4e3a\u79fb\u6c11\u7684\u8bae\u5458\u66f4\u652f\u6301\u5bbd\u677e\u7684\u79fb\u6c11\u7acb\u6cd5\uff0c\u4e14\u5728\u56fd\u4f1a\u6f14\u8bb2\u4e2d\u8f83\u5c11\u5bf9\u79fb\u6c11\u6301\u8d1f\u9762\u6001\u5ea6\u3002\u901a\u8fc7\u5206\u6790\u63a5\u8fd1\u80dc\u8d1f\u7684\u9009\u4e3e\uff0c\u91c7\u7528\u56de\u5f52\u65ad\u70b9\u8bbe\u8ba1\uff0c\u63a7\u5236\u4e86\u9009\u533a\u5c42\u9762\u7684\u9009\u6c11\u9009\u62e9\u95ee\u9898\uff0c\u5e76\u4fdd\u6301\u9009\u533a\u6784\u6210\u4e0d\u53d8\uff0c\u8bc1\u5b9e\u4e86\u8bae\u5458\u5728\u6295\u7968\u548c\u8a00\u8bba\u4e0a\u7684\u7ed3\u679c\u3002\u8bd5\u56fe\u8003\u8651\u79fb\u6c11\u9009\u62e9\u56e0\u7d20\u7684\u52aa\u529b\uff0c\u4f8b\u5982\u5c06\u56fd\u9645\u79fb\u6c11\u4e0e\u56fd\u5185\u79fb\u6c11\u8fdb\u884c\u6bd4\u8f83\uff0c\u6216\u5229\u7528\u9488\u5bf9\u7279\u5b9a\u539f\u7c4d\u5730\u533a\u79fb\u6c11\u7684\u4e25\u683c\u7acb\u6cd5\u5dee\u5f02\uff0c\u8fdb\u4e00\u6b65\u8bc1\u5b9e\u4e86\u5bb6\u65cf\u79fb\u6c11\u7ecf\u5386\u4e0e\u66f4\u5bbd\u5bb9\u79fb\u6c11\u7acb\u573a\u4e4b\u95f4\u7684\u5173\u7cfb\u3002\u6211\u4eec\u8fd8\u63a2\u8ba8\u4e86\u673a\u5236\uff0c\u53d1\u73b0\u5bb6\u65cf\u5386\u53f2\u4e0e\u653f\u7b56\u5236\u5b9a\u4e4b\u95f4\u7684\u8054\u7cfb\u53ef\u80fd\u6e90\u4e8e\u7fa4\u4f53\u8ba4\u540c\u3002\u8bae\u5458\u4eec\u5728\u4e3a\u5b50\u5973\u53d6\u540d\u65f6\u4f1a\u4f53\u73b0\u79fb\u6c11\u8eab\u4efd\uff0c\u800c\u79fb\u6c11\u540e\u4ee3\u8bae\u5458\u5728\u8ba8\u8bba\u79fb\u6c11\u95ee\u9898\u65f6\u66f4\u503e\u5411\u4e8e\u4f7f\u7528\u4e2a\u4eba\u5316\u6846\u67b6\uff0c\u5f3a\u8c03\u5bb6\u5ead\u800c\u975e\u7ecf\u6d4e\u56e0\u7d20\u3002\u672c\u7814\u7a76\u5c55\u793a\u4e86\u4e2a\u4eba\u80cc\u666f\u5728\u6c11\u4e3b\u793e\u4f1a\u7acb\u6cd5\u884c\u4e3a\u4e2d\u7684\u91cd\u8981\u4f5c\u7528\uff0c\u5373\u4f7f\u5728\u5982\u79fb\u6c11\u8fd9\u6837\u91cd\u5927\u4e14\u4e89\u8bae\u6027\u7684\u8bdd\u9898\u4e0a\uff0c\u4e5f\u8868\u660e\u524d\u51e0\u4ee3\u4eba\u7684\u7ecf\u5386\u53ef\u80fd\u5f71\u54cd\u7acb\u6cd5\u8005\u7684\u6001\u5ea6\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf016", "journal": "QJE", "title": "Voluntary Minimum Wages: The Local Labor Market Effects of National Retailer Policies", "authors": ["Ellora Derenoncourt", "David Weil"], "author_details": [{"name": "Ellora Derenoncourt", "affiliations": ["Princeton University ,"]}, {"name": "David Weil", "affiliations": ["Brandeis University ,"]}], "abstract": "ABSTRACT Low unionization rates, a falling real federal minimum wage, and outsourcing have hampered wage growth in the low-wage sector in the United States for several decades. In recent years (2014\u20132023), a number of large private retailers\u2014including some of the largest employers in the United States\u2014have opted to institute or raise company-wide, voluntary minimum wages (VMWs) for their employees. We use anonymized payroll data from a large credit bureau and a major payroll provider to study the effects of these national retailer policies on adopting employers\u2019 own wages and employment as well as their spillovers to other employers in shared local labor markets, variously defined. Using stacked event studies centered around multiple VMW events and a continuous treatment variable defined as the gap between local-area wages and the company minimum, we find that VMWs result in sizable wage increases and reductions in turnover at the companies that implement them. Turning to wages at other companies, we estimate small, often economically negligible, spillover effects across multiple measures of exposure to VMWs and numerous definitions of relevant competitors, including firms connected by worker flows. Together, the evidence points to little role for strategic interactions in the transmission of large retailers\u2019 wage policies to other firms. Voluntary minimum wage policies have affected over 3 million jobs at adopting employers, yet their impact on the broader labor market is limited.", "date": "2025-03-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf016", "title_zh": "\u81ea\u613f\u6700\u4f4e\u5de5\u8d44\uff1a\u5168\u56fd\u96f6\u552e\u5546\u653f\u7b56\u5bf9\u5f53\u5730\u52b3\u52a8\u529b\u5e02\u573a\u7684\u6548\u5e94", "abstract_zh": "\u6458\u8981 \u4f4e\u5de5\u4f1a\u5316\u7387\u3001\u5b9e\u9645\u8054\u90a6\u6700\u4f4e\u5de5\u8d44\u7684\u4e0b\u964d\u4ee5\u53ca\u5916\u5305\u884c\u4e3a\uff0c\u5df2\u4f7f\u7f8e\u56fd\u4f4e\u85aa\u90e8\u95e8\u7684\u5de5\u8d44\u589e\u957f\u5728\u6570\u5341\u5e74\u95f4\u53d7\u5230\u963b\u788d\u3002\u8fd1\u5e74\u6765\uff082014\u20132023\u5e74\uff09\uff0c\u4e00\u4e9b\u5927\u578b\u79c1\u8425\u96f6\u552e\u5546\u2014\u2014\u5305\u62ec\u7f8e\u56fd\u6700\u5927\u7684\u96c7\u4e3b\u4e4b\u4e00\u2014\u2014\u5df2\u9009\u62e9\u5b9e\u65bd\u6216\u63d0\u9ad8\u5176\u516c\u53f8\u8303\u56f4\u5185\u7684\u81ea\u613f\u6700\u4f4e\u5de5\u8d44\uff08VMW\uff09\u3002\u6211\u4eec\u5229\u7528\u4e00\u5bb6\u5927\u578b\u4fe1\u7528\u673a\u6784\u548c\u4e00\u5bb6\u4e3b\u8981\u85aa\u916c\u63d0\u4f9b\u5546\u7684\u533f\u540d\u85aa\u916c\u6570\u636e\uff0c\u7814\u7a76\u8fd9\u4e9b\u5168\u56fd\u6027\u96f6\u552e\u5546\u653f\u7b56\u5bf9\u5b9e\u65bd\u4f01\u4e1a\u81ea\u8eab\u5de5\u8d44\u548c\u5c31\u4e1a\uff0c\u4ee5\u53ca\u5728\u4e0d\u540c\u5b9a\u4e49\u4e0b\u7684\u5171\u4eab\u672c\u5730\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u5176\u4ed6\u4f01\u4e1a\u7684\u6ea2\u51fa\u6548\u5e94\u7684\u5f71\u54cd\u3002\u901a\u8fc7\u56f4\u7ed5\u591a\u4e2aVMW\u4e8b\u4ef6\u8fdb\u884c\u5806\u53e0\u4e8b\u4ef6\u7814\u7a76\uff0c\u5e76\u5b9a\u4e49\u4e00\u4e2a\u8fde\u7eed\u5904\u7406\u53d8\u91cf\u2014\u2014\u5373\u5f53\u5730\u5de5\u8d44\u4e0e\u516c\u53f8\u6700\u4f4e\u5de5\u8d44\u4e4b\u95f4\u7684\u5dee\u8ddd\u2014\u2014\u6211\u4eec\u53d1\u73b0\uff0cVMW\u5728\u5b9e\u65bd\u4f01\u4e1a\u4e2d\u5bfc\u81f4\u4e86\u663e\u8457\u7684\u5de5\u8d44\u4e0a\u6da8\u548c\u5458\u5de5\u6d41\u52a8\u7387\u4e0b\u964d\u3002\u5728\u5176\u4ed6\u4f01\u4e1a\u7684\u5de5\u8d44\u65b9\u9762\uff0c\u6211\u4eec\u4f30\u8ba1\u51fa\u5c0f\u5e45\u5ea6\u7684\u6ea2\u51fa\u6548\u5e94\uff0c\u8fd9\u4e9b\u6548\u5e94\u5728\u591a\u79cd\u66b4\u9732\u6307\u6807\u548c\u4f17\u591a\u76f8\u5173\u7ade\u4e89\u5bf9\u624b\u5b9a\u4e49\u4e0b\uff08\u5305\u62ec\u901a\u8fc7\u5458\u5de5\u6d41\u52a8\u8fde\u63a5\u7684\u516c\u53f8\uff09\u5747\u8868\u73b0\u5fae\u5f31\u3002\u603b\u4f53\u6765\u770b\uff0c\u8bc1\u636e\u8868\u660e\u5927\u578b\u96f6\u552e\u5546\u7684\u5de5\u8d44\u653f\u7b56\u5728\u5411\u5176\u4ed6\u4f01\u4e1a\u4f20\u5bfc\u8fc7\u7a0b\u4e2d\u51e0\u4e4e\u6ca1\u6709\u6218\u7565\u4e92\u52a8\u4f5c\u7528\u3002\u81ea\u613f\u6700\u4f4e\u5de5\u8d44\u653f\u7b56\u5df2\u5f71\u54cd\u8d85\u8fc7300\u4e07\u4e2a\u5c97\u4f4d\uff0c\u4f46\u5176\u5bf9\u66f4\u5e7f\u6cdb\u52b3\u52a8\u529b\u5e02\u573a\u7684\u51b2\u51fb\u6709\u9650\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf015", "journal": "QJE", "title": "Micro MPCs and Macro Counterfactuals: The Case of the 2008 Rebates", "authors": ["Jacob D Orchard", "Valerie A Ramey", "Johannes F Wieland"], "author_details": [{"name": "Jacob D Orchard", "affiliations": ["Board of Governors of the Federal Reserve System ,"]}, {"name": "Valerie A Ramey", "affiliations": ["Stanford University ,"]}, {"name": "Johannes F Wieland", "affiliations": ["University of California, San Diego and Federal Reserve Bank of San Francisco ,"]}], "abstract": "ABSTRACT We present evidence that the high estimated marginal propensities to consume (MPCs) from the leading household studies result in implausible macroeconomic counterfactuals. Using the 2008 tax rebate as a case study, we calibrate a standard macro model with the estimated micro MPCs to construct counterfactual macroeconomic consumption paths in the absence of a rebate. The counterfactual paths imply that consumption expenditures would have plummeted in spring and summer 2008 and mostly recovered in September 2008. We use narratives and forecasts to argue that these paths are implausible. We show that standard two-way fixed effect estimates of the micro MPCs are upward biased. When we correct for the biases, we estimate smaller micro MPCs using the CEX data than the previous literature. We show that realistic modifications of the model result in general equilibrium forces that dampen rather than amplify micro MPCs. The combination of smaller micro MPCs and dampening general equilibrium forces implies general equilibrium consumption multipliers that are below 0.2.", "date": "2025-02-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf015", "title_zh": "\u5fae\u89c2\u8fb9\u9645\u6d88\u8d39\u503e\u5411\u4e0e\u5b8f\u89c2\u53cd\u4e8b\u5b9e\uff1a2008\u5e74\u9000\u7a0e\u6848\u7684\u5206\u6790", "abstract_zh": "\u6458\u8981 \u6211\u4eec\u53d1\u73b0\uff0c\u4e3b\u6d41\u5bb6\u5ead\u7814\u7a76\u4e2d\u4f30\u8ba1\u7684\u9ad8\u8fb9\u9645\u6d88\u8d39\u503e\u5411\uff08MPC\uff09\u5bfc\u81f4\u4e86\u4e0d\u5408\u7406\u7684\u5b8f\u89c2\u7ecf\u6d4e\u53cd\u4e8b\u5b9e\u7ed3\u679c\u3002\u4ee52008\u5e74\u7a0e\u6536\u9000\u7a0e\u4e3a\u4f8b\uff0c\u6211\u4eec\u4f7f\u7528\u4e3b\u6d41\u5bb6\u5ead\u7814\u7a76\u4e2d\u4f30\u8ba1\u7684\u5fae\u89c2\u8fb9\u9645\u6d88\u8d39\u503e\u5411\u5bf9\u6807\u51c6\u5b8f\u89c2\u7ecf\u6d4e\u6a21\u578b\u8fdb\u884c\u6821\u51c6\uff0c\u6784\u5efa\u4e86\u5728\u6ca1\u6709\u9000\u7a0e\u60c5\u51b5\u4e0b\u6d88\u8d39\u8def\u5f84\u7684\u53cd\u4e8b\u5b9e\u60c5\u666f\u3002\u8be5\u53cd\u4e8b\u5b9e\u8def\u5f84\u8868\u660e\uff0c\u6d88\u8d39\u652f\u51fa\u57282008\u5e74\u6625\u5b63\u548c\u590f\u5b63\u4f1a\u6025\u5267\u4e0b\u964d\uff0c\u4e3b\u8981\u57282008\u5e749\u6708\u6062\u590d\u3002\u6211\u4eec\u901a\u8fc7\u53d9\u4e8b\u548c\u9884\u6d4b\u8bba\u8bc1\uff0c\u8ba4\u4e3a\u8fd9\u4e9b\u8def\u5f84\u662f\u4e0d\u5408\u7406\u7684\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u6807\u51c6\u7684\u53cc\u5411\u56fa\u5b9a\u6548\u5e94\u4f30\u8ba1\u65b9\u6cd5\u4f1a\u9ad8\u4f30\u5fae\u89c2\u8fb9\u9645\u6d88\u8d39\u503e\u5411\u3002\u5f53\u6211\u4eec\u5bf9\u504f\u5dee\u8fdb\u884c\u4fee\u6b63\u540e\uff0c\u4f7f\u7528CEX\u6570\u636e\u5f97\u5230\u7684\u5fae\u89c2\u8fb9\u9645\u6d88\u8d39\u503e\u5411\u4f4e\u4e8e\u4ee5\u5f80\u6587\u732e\u7684\u4f30\u8ba1\u503c\u3002\u6211\u4eec\u8fd8\u8868\u660e\uff0c\u5bf9\u6a21\u578b\u8fdb\u884c\u5408\u7406\u7684\u4fee\u6539\u540e\uff0c\u4e00\u822c\u5747\u8861\u529b\u91cf\u4f1a\u6291\u5236\u800c\u975e\u653e\u5927\u5fae\u89c2\u8fb9\u9645\u6d88\u8d39\u503e\u5411\u3002\u8f83\u5c0f\u7684\u5fae\u89c2\u8fb9\u9645\u6d88\u8d39\u503e\u5411\u4e0e\u6291\u5236\u6027\u7684\u4e00\u822c\u5747\u8861\u529b\u91cf\u76f8\u7ed3\u5408\uff0c\u610f\u5473\u7740\u4e00\u822c\u5747\u8861\u6d88\u8d39\u4e58\u6570\u4f4e\u4e8e0.2\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf012", "journal": "QJE", "title": "A Monetary-Fiscal Theory of Sudden Inflations", "authors": ["Marco Bassetto", "David S Miller"], "author_details": [{"name": "Marco Bassetto", "affiliations": ["Federal Reserve Bank of Minneapolis ,"]}, {"name": "David S Miller", "affiliations": ["Federal Reserve Board ,"]}], "abstract": "ABSTRACT This article posits an information channel as an explanation for sudden inflations. Households saving via nominal government bonds face a choice whether to acquire costly information about future government surpluses. They trade off the cost of acquiring information about the surpluses that back bond repayment against the benefit of a more informed saving decision. Through the information channel, small changes in the economic environment can trigger large responses in consumer behavior and prices. This setting explains why there can be long stretches of time during which government surpluses have large movements with little inflation response; then at some point, something snaps, and a sudden inflation takes off that is strongly responsive to incoming fiscal news.", "date": "2025-02-21", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf012", "title_zh": "\u8d27\u5e01-\u8d22\u653f\u7406\u8bba\u4e2d\u7684\u7a81\u7136\u901a\u8d27\u81a8\u80c0", "abstract_zh": "\u6458\u8981 \u672c\u6587\u63d0\u51fa\u4e00\u4e2a\u4fe1\u606f\u6e20\u9053\u6765\u89e3\u91ca\u7a81\u7136\u901a\u8d27\u81a8\u80c0\u7684\u73b0\u8c61\u3002\u5bb6\u5ead\u901a\u8fc7\u540d\u4e49\u653f\u5e9c\u503a\u5238\u8fdb\u884c\u50a8\u84c4\u65f6\uff0c\u9700\u8981\u51b3\u5b9a\u662f\u5426\u82b1\u8d39\u6210\u672c\u53bb\u83b7\u53d6\u672a\u6765\u653f\u5e9c\u76c8\u4f59\u7684\u4fe1\u606f\u3002\u4ed6\u4eec\u6743\u8861\u83b7\u53d6\u5173\u4e8e\u652f\u6491\u503a\u5238\u507f\u8fd8\u7684\u76c8\u4f59\u4fe1\u606f\u7684\u6210\u672c\uff0c\u4e0e\u505a\u51fa\u66f4\u660e\u667a\u50a8\u84c4\u51b3\u7b56\u6240\u5e26\u6765\u7684\u6536\u76ca\u3002\u901a\u8fc7\u8fd9\u4e00\u4fe1\u606f\u6e20\u9053\uff0c\u7ecf\u6d4e\u73af\u5883\u4e2d\u7684\u5fae\u5c0f\u53d8\u5316\u53ef\u80fd\u5f15\u53d1\u6d88\u8d39\u8005\u884c\u4e3a\u548c\u4ef7\u683c\u7684\u5267\u70c8\u53cd\u5e94\u3002\u8be5\u6a21\u578b\u89e3\u91ca\u4e86\u4e3a\u4f55\u5728\u653f\u5e9c\u76c8\u4f59\u5927\u5e45\u6ce2\u52a8\u7684\u65f6\u671f\uff0c\u901a\u80c0\u53cd\u5e94\u53ef\u80fd\u957f\u671f\u5904\u4e8e\u4f4e\u8ff7\u72b6\u6001\uff1b\u76f4\u5230\u67d0\u4e2a\u65f6\u523b\uff0c\u60c5\u51b5\u53d1\u751f\u8f6c\u6298\uff0c\u7a81\u7136\u51fa\u73b0\u5f3a\u70c8\u54cd\u5e94\u8d22\u653f\u4fe1\u606f\u7684\u901a\u8d27\u81a8\u80c0\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf014", "journal": "QJE", "title": "The Race Between Education, Technology, and the Minimum Wage", "authors": ["Jonathan Vogel"], "author_details": [{"name": "Jonathan Vogel", "affiliations": ["University of California , Los Angeles ,"]}], "abstract": "ABSTRACT What is the effect of the real minimum wage on wages and inequality? I develop a theory that nests the race between education and technology. The theory predicts that the effect of changes in minimum wages is initially small but grows over time. I present empirical evidence of these dynamic effects: the elasticity of real wages grows substantially over a three-year period. I show that minimum wages help rationalize a considerable decline in real wages of low-education workers in the 1980s and play a role in shaping the evolution of the U.S. college premium.", "date": "2025-02-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf014", "title_zh": "\u6559\u80b2\u3001\u6280\u672f\u4e0e\u6700\u4f4e\u5de5\u8d44\u4e4b\u95f4\u7684\u7ade\u4e89", "abstract_zh": "\u6458\u8981 \u5b9e\u9645\u6700\u4f4e\u5de5\u8d44\u5bf9\u5de5\u8d44\u548c\u4e0d\u5e73\u7b49\u6709\u4f55\u5f71\u54cd\uff1f\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u5305\u542b\u6559\u80b2\u4e0e\u6280\u672f\u4e4b\u95f4\u7ade\u4e89\u7684\u7406\u8bba\u3002\u8be5\u7406\u8bba\u9884\u6d4b\uff0c\u6700\u4f4e\u5de5\u8d44\u53d8\u5316\u7684\u6548\u5e94\u5728\u521d\u671f\u8f83\u5c0f\uff0c\u4f46\u968f\u7740\u65f6\u95f4\u63a8\u79fb\u9010\u6e10\u589e\u5f3a\u3002\u6211\u63d0\u4f9b\u4e86\u8fd9\u4e9b\u52a8\u6001\u6548\u5e94\u7684\u5b9e\u8bc1\u8bc1\u636e\uff1a\u5b9e\u9645\u5de5\u8d44\u7684\u5f39\u6027\u5728\u4e09\u5e74\u671f\u5185\u663e\u8457\u4e0a\u5347\u3002\u6211\u8868\u660e\uff0c\u6700\u4f4e\u5de5\u8d44\u6709\u52a9\u4e8e\u89e3\u91ca20\u4e16\u7eaa80\u5e74\u4ee3\u4f4e\u6559\u80b2\u6c34\u5e73\u5de5\u4eba\u5b9e\u9645\u5de5\u8d44\u7684\u5927\u5e45\u4e0b\u964d\uff0c\u5e76\u5728\u5851\u9020\u7f8e\u56fd\u5927\u5b66\u5b66\u5386\u6ea2\u4ef7\u7684\u6f14\u53d8\u8fc7\u7a0b\u4e2d\u53d1\u6325\u4e86\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf013", "journal": "QJE", "title": "What Works and for Whom? Effectiveness and Efficiency of School Capital Investments Across the U.S.", "authors": ["Barbara Biasi", "Julien Lafortune", "David Sch\u00f6nholzer"], "author_details": [{"name": "Barbara Biasi", "affiliations": ["Yale University School of Management ,"]}, {"name": "Julien Lafortune", "affiliations": ["Public Policy Institute of California ,"]}, {"name": "David Sch\u00f6nholzer", "affiliations": ["University of California, Santa Cruz ,"]}], "abstract": "ABSTRACT This article identifies which investments in school facilities help students and which are valued by homeowners. Using novel data on school district bonds, test scores, and house prices across 29 U.S. states and a research design based on narrowly decided elections with staggered timing, we find that increased capital spending in schools significantly improves test scores and is efficient on average. However, the effects vary widely depending on the type of project and the characteristics of the school district. Investments in essential infrastructure, such as HVAC systems or pollutant removal, yield notable improvements in student performance, while expenditures on athletic facilities show no measurable academic benefit. Socioeconomically disadvantaged districts gain disproportionately from capital investments, even after accounting for project type, yet these districts typically underinvest in such projects.", "date": "2025-02-18", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf013", "title_zh": "\u4ec0\u4e48\u6709\u6548\u4e14\u5bf9\u8c01\u6709\u6548\uff1f\u7f8e\u56fd\u5b66\u6821\u8d44\u672c\u6295\u8d44\u7684\u6548\u679c\u4e0e\u6548\u7387\u7814\u7a76", "abstract_zh": "\u6458\u8981 \u672c\u6587\u8bc6\u522b\u4e86\u54ea\u4e9b\u5b66\u6821\u8bbe\u65bd\u6295\u8d44\u6709\u52a9\u4e8e\u5b66\u751f\uff0c\u54ea\u4e9b\u88ab\u623f\u4e3b\u6240\u91cd\u89c6\u3002\u57fa\u4e8e\u5bf9\u7f8e\u56fd29\u4e2a\u5dde\u5b66\u6821\u503a\u5238\u3001\u5b66\u751f\u6210\u7ee9\u548c\u623f\u4ef7\u7684\u65b0\u578b\u6570\u636e\uff0c\u5e76\u91c7\u7528\u57fa\u4e8e narrowly decided elections\uff08 narrowly decided elections\uff09\u4e14\u5177\u6709\u9636\u68af\u5f0f\u65f6\u95f4\u5b89\u6392\u7684\u7814\u7a76\u8bbe\u8ba1\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u5b66\u6821\u8d44\u672c\u652f\u51fa\u7684\u589e\u52a0\u663e\u8457\u63d0\u5347\u4e86\u5b66\u751f\u6210\u7ee9\uff0c\u5e76\u5728\u5e73\u5747\u610f\u4e49\u4e0a\u662f\u9ad8\u6548\u7684\u3002\u7136\u800c\uff0c\u5176\u6548\u679c\u56e0\u9879\u76ee\u7c7b\u578b\u548c\u5b66\u533a\u7279\u5f81\u7684\u4e0d\u540c\u800c\u5dee\u5f02\u663e\u8457\u3002\u5bf9\u57fa\u672c\u57fa\u7840\u8bbe\u65bd\uff08\u5982\u4f9b\u6696\u3001\u901a\u98ce\u7cfb\u7edf\u6216\u6c61\u67d3\u7269\u53bb\u9664\uff09\u7684\u6295\u8d44\u663e\u8457\u63d0\u5347\u4e86\u5b66\u751f\u6210\u7ee9\uff0c\u800c\u5bf9\u4f53\u80b2\u8bbe\u65bd\u7684\u652f\u51fa\u5219\u672a\u663e\u793a\u51fa\u53ef\u6d4b\u91cf\u7684\u5b66\u672f\u6548\u76ca\u3002\u5728\u8003\u8651\u9879\u76ee\u7c7b\u578b\u540e\uff0c\u7ecf\u6d4e\u548c\u793e\u4f1a\u5730\u4f4d\u8f83\u5f31\u7684\u5b66\u533a\u4ece\u8d44\u672c\u6295\u8d44\u4e2d\u83b7\u5f97\u4e0d\u6210\u6bd4\u4f8b\u7684\u6536\u76ca\uff0c\u5c3d\u7ba1\u8fd9\u4e9b\u5b66\u533a\u901a\u5e38\u5728\u8fd9\u4e9b\u6295\u8d44\u4e0a\u6295\u5165\u4e0d\u8db3\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf011", "journal": "QJE", "title": "The Long-Run Effects of America\u2019s Largest Residential Racial Desegregation Program: Gautreaux", "authors": ["Eric Chyn", "Robert Collinson", "Danielle H Sandler"], "author_details": [{"name": "Eric Chyn", "affiliations": ["University of Texas-Austin and National Bureau of Economic Research ,"]}, {"name": "Robert Collinson", "affiliations": ["University of Notre Dame and National Bureau of Economic Research ,"]}, {"name": "Danielle H Sandler", "affiliations": ["U.S. Census Bureau ,"]}], "abstract": "ABSTRACT This article studies the effects of the largest residential racial desegregation initiative in U.S. history, the Gautreaux Assisted Housing Program. From the late 1970s to the 1990s, Gautreaux moved thousands of Black families into predominantly white neighborhoods to support racial and economic integration. We link historical program records to administrative data and use plausibly exogenous variation in neighborhood placements to study how desegregating moves affect children in the long run. Being placed in the predominantly white neighborhoods targeted by the program significantly increases children\u2019s future lifetime earnings and wealth. These moves also increase the likelihood of marriage and particularly raise the probability of being married to a white spouse. Moreover, placements through Gautreaux affect neighborhood choices in adulthood. Those placed in predominantly white neighborhoods during childhood live in more racially diverse areas with higher rates of upward mobility nearly 40 years later.", "date": "2025-02-13", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf011", "title_zh": "\u7f8e\u56fd\u6700\u5927\u4f4f\u5b85\u79cd\u65cf\u53bb\u9694\u79bb\u8ba1\u5212\u7684\u957f\u671f\u6548\u5e94\uff1a\u76d6\u7279\u96f7\u514b\u65af", "abstract_zh": "\u6458\u8981 \u672c\u6587\u7814\u7a76\u4e86\u7f8e\u56fd\u5386\u53f2\u4e0a\u6700\u5927\u7684\u4f4f\u5b85\u79cd\u65cf\u53bb\u9694\u79bb\u4e3e\u63aa\u2014\u2014\u76d6\u7279\u96f7\u514b\u65af\u8f85\u52a9\u4f4f\u623f\u8ba1\u5212\u7684\u6548\u5e94\u3002\u4ece20\u4e16\u7eaa70\u5e74\u4ee3\u672b\u523090\u5e74\u4ee3\uff0c\u76d6\u7279\u96f7\u514b\u65af\u5c06\u6570\u5343\u4e2a\u9ed1\u4eba\u5bb6\u5ead\u8fc1\u5165\u4ee5\u767d\u4eba\u4e3a\u4e3b\u7684\u793e\u533a\uff0c\u4ee5\u4fc3\u8fdb\u79cd\u65cf\u548c\u7ecf\u6d4e\u878d\u5408\u3002\u6211\u4eec\u901a\u8fc7\u5c06\u5386\u53f2\u9879\u76ee\u8bb0\u5f55\u4e0e\u884c\u653f\u6570\u636e\u76f8\u94fe\u63a5\uff0c\u5e76\u5229\u7528\u90bb\u91cc\u5b89\u7f6e\u7684\u5916\u751f\u53d8\u5316\uff0c\u7814\u7a76\u53bb\u9694\u79bb\u642c\u8fc1\u5bf9\u513f\u7ae5\u957f\u671f\u53d1\u5c55\u7684\u5f71\u54cd\u3002\u88ab\u5b89\u7f6e\u5230\u76ee\u6807\u4ee5\u767d\u4eba\u4e3a\u4e3b\u7684\u793e\u533a\u663e\u8457\u63d0\u9ad8\u4e86\u513f\u7ae5\u672a\u6765\u7684\u7ec8\u8eab\u6536\u5165\u548c\u8d22\u5bcc\u3002\u8fd9\u4e9b\u642c\u8fc1\u4e5f\u589e\u52a0\u4e86\u7ed3\u5a5a\u7684\u53ef\u80fd\u6027\uff0c\u5c24\u5176\u662f\u63d0\u9ad8\u4e86\u4e0e\u767d\u4eba\u914d\u5076\u7ed3\u5a5a\u7684\u6982\u7387\u3002\u6b64\u5916\uff0c\u7ae5\u5e74\u65f6\u671f\u901a\u8fc7\u76d6\u7279\u96f7\u514b\u65af\u8ba1\u5212\u88ab\u5b89\u7f6e\u5728\u4ee5\u767d\u4eba\u4e3a\u4e3b\u7684\u793e\u533a\u7684\u4e2a\u4f53\uff0c\u5728\u6210\u5e74\u540e\u66f4\u503e\u5411\u4e8e\u9009\u62e9\u79cd\u65cf\u66f4\u52a0\u591a\u5143\u7684\u793e\u533a\uff0c\u4e14\u8fd9\u4e9b\u793e\u533a\u7684\u5411\u4e0a\u6d41\u52a8\u7387\u4e5f\u663e\u8457\u66f4\u9ad8\uff0c\u8fd9\u4e00\u73b0\u8c61\u5728\u8fd140\u5e74\u540e\u4f9d\u7136\u5b58\u5728\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf009", "journal": "QJE", "title": "Can Pollution Markets Work in Developing Countries? Experimental Evidence from India", "authors": ["Michael Greenstone", "Rohini Pande", "Nicholas Ryan", "Anant Sudarshan"], "author_details": [{"name": "Michael Greenstone", "affiliations": ["University of Chicago ,"]}, {"name": "Rohini Pande", "affiliations": ["Yale University ,"]}, {"name": "Nicholas Ryan", "affiliations": ["Yale University ,"]}, {"name": "Anant Sudarshan", "affiliations": ["University of Warwick ,"]}], "abstract": "Abstract Market-based environmental regulations are seldom used in low-income countries, where pollution is highest but state capacity is often low. We collaborated with the Gujarat Pollution Control Board (GPCB) to design and experimentally evaluate the world\u2019s first particulate-matter emissions market, which covered industrial plants in a large Indian city. There are three main findings. First, the market functioned well. Treatment plants, randomly assigned to the emissions market, traded permits to become significant net sellers or buyers. After trading, treatment plants held enough permits to cover their emissions 99% of the time, compared with just 66% compliance with standards under the command-and-control status quo. Second, treatment plants reduced pollution emissions, relative to control plants, by 20%\u201330%. Third, the market reduced abatement costs by an estimated 11%, holding constant emissions. This cost-savings estimate is based on plant-specific marginal cost curves that we estimate from the universe of bids to buy and sell permits in the market. The combination of pollution reductions and low costs imply that the emissions market has mortality benefits that exceed its costs by at least 25 times.", "date": "2025-02-05", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf009", "title_zh": "\u53d1\u5c55\u4e2d\u56fd\u5bb6\u7684\u6c61\u67d3\u5e02\u573a\u80fd\u5426\u53d1\u6325\u4f5c\u7528\uff1f\u6765\u81ea\u5370\u5ea6\u7684\u5b9e\u9a8c\u8bc1\u636e", "abstract_zh": "\u62bd\u8c61\uff1a\u5728\u4f4e\u6536\u5165\u56fd\u5bb6\uff0c\u57fa\u4e8e\u5e02\u573a\u7684\u73af\u5883\u89c4\u5236\u5f88\u5c11\u88ab\u91c7\u7528\uff0c\u8fd9\u4e9b\u56fd\u5bb6\u6c61\u67d3\u6700\u4e25\u91cd\uff0c\u4f46\u653f\u5e9c\u80fd\u529b\u5f80\u5f80\u4e0d\u8db3\u3002\u6211\u4eec\u4e0e\u53e4\u5409\u62c9\u7279\u6c61\u67d3\u63a7\u5236\u59d4\u5458\u4f1a\uff08GPCB\uff09\u5408\u4f5c\uff0c\u8bbe\u8ba1\u5e76\u5b9e\u9a8c\u6027\u8bc4\u4f30\u4e86\u4e16\u754c\u4e0a\u9996\u4e2a\u9897\u7c92\u7269\u6392\u653e\u5e02\u573a\uff0c\u8be5\u5e02\u573a\u8986\u76d6\u4e86\u5370\u5ea6\u4e00\u5ea7\u5927\u57ce\u5e02\u4e2d\u7684\u5de5\u4e1a\u8bbe\u65bd\u3002\u7814\u7a76\u5f97\u51fa\u4e09\u4e2a\u4e3b\u8981\u53d1\u73b0\u3002\u9996\u5148\uff0c\u8be5\u5e02\u573a\u8fd0\u884c\u826f\u597d\u3002\u968f\u673a\u5206\u914d\u8fdb\u5165\u6392\u653e\u5e02\u573a\u7684\u5904\u7406\u5de5\u5382\u901a\u8fc7\u4ea4\u6613\u6392\u653e\u914d\u989d\uff0c\u6210\u4e3a\u663e\u8457\u7684\u51c0\u5356\u65b9\u6216\u51c0\u4e70\u65b9\u3002\u4ea4\u6613\u540e\uff0c\u5904\u7406\u5de5\u5382\u6301\u6709\u8db3\u591f\u914d\u989d\u4ee5\u8986\u76d6\u5176\u6392\u653e\u91cf\u768499%\u65f6\u95f4\uff0c\u800c\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u5728\u4f20\u7edf\u7684\u547d\u4ee4\u4e0e\u63a7\u5236\u5236\u5ea6\u4e0b\uff0c\u4ec566%\u7684\u5de5\u5382\u80fd\u591f\u7b26\u5408\u6392\u653e\u6807\u51c6\u3002\u5176\u6b21\uff0c\u4e0e\u5bf9\u7167\u5de5\u5382\u76f8\u6bd4\uff0c\u5904\u7406\u5de5\u5382\u7684\u6c61\u67d3\u6392\u653e\u91cf\u51cf\u5c11\u4e8620%\u81f330%\u3002\u7b2c\u4e09\uff0c\u8be5\u5e02\u573a\u5728\u4fdd\u6301\u6392\u653e\u91cf\u4e0d\u53d8\u7684\u524d\u63d0\u4e0b\uff0c\u5c06\u51cf\u6392\u6210\u672c\u964d\u4f4e\u4e86\u7ea611%\uff0c\u8fd9\u4e00\u6210\u672c\u8282\u7ea6\u4f30\u8ba1\u57fa\u4e8e\u6211\u4eec\u4ece\u5e02\u573a\u4e2d\u4e70\u5356\u914d\u989d\u7684\u5168\u90e8\u6295\u6807\u6570\u636e\u4e2d\u4f30\u8ba1\u51fa\u7684\u5404\u5de5\u5382\u8fb9\u9645\u6210\u672c\u66f2\u7ebf\u3002\u6c61\u67d3\u51cf\u6392\u4e0e\u4f4e\u6210\u672c\u7684\u7ed3\u5408\u8868\u660e\uff0c\u8be5\u6392\u653e\u5e02\u573a\u5e26\u6765\u7684\u6548\u76ca\u81f3\u5c11\u662f\u5176\u6210\u672c\u768425\u500d\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjae044", "journal": "QJE", "title": "Generative AI at Work", "authors": ["Erik Brynjolfsson", "Danielle Li", "Lindsey Raymond"], "author_details": [{"name": "Erik Brynjolfsson", "affiliations": ["Stanford University and National Bureau of Economic Research ,"]}, {"name": "Danielle Li", "affiliations": ["Massachusetts Institute of Technology and National Bureau of Economic Research ,"]}, {"name": "Lindsey Raymond", "affiliations": ["Massachusetts Institute of Technology ,"]}], "abstract": "Abstract We study the staggered introduction of a generative AI\u2013based conversational assistant using data from 5,172 customer-support agents. Access to AI assistance increases worker productivity, as measured by issues resolved per hour, by 15% on average, with substantial heterogeneity across workers. The effects vary significantly across different agents. Less experienced and lower-skilled workers improve both the speed and quality of their output, while the most experienced and highest-skilled workers see small gains in speed and small declines in quality. We also find evidence that AI assistance facilitates worker learning and improves English fluency, particularly among international agents. While AI systems improve with more training data, we find that the gains from AI adoption are largest for moderately rare problems, where human agents have less baseline experience but the system still has adequate training data. Finally, we provide evidence that AI assistance improves the experience of work along several dimensions: customers are more polite and less likely to ask to speak to a manager.", "date": "2025-02-04", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjae044", "title_zh": "\u751f\u6210\u5f0f\u4eba\u5de5\u667a\u80fd\u5728\u5de5\u4f5c\u4e2d\u7684\u5e94\u7528", "abstract_zh": "\u6211\u4eec\u5229\u7528\u6765\u81ea5172\u540d\u5ba2\u670d\u4ee3\u7406\u4eba\u5458\u7684\u6570\u636e\uff0c\u7814\u7a76\u4e86\u57fa\u4e8e\u751f\u6210\u5f0f\u4eba\u5de5\u667a\u80fd\u7684\u5bf9\u8bdd\u52a9\u624b\u5206\u9636\u6bb5\u5f15\u5165\u7684\u5f71\u54cd\u3002\u83b7\u5f97AI\u8f85\u52a9\u540e\uff0c\u5458\u5de5\u7684\u751f\u4ea7\u7387\u2014\u2014\u4ee5\u6bcf\u5c0f\u65f6\u89e3\u51b3\u7684\u95ee\u9898\u6570\u91cf\u8861\u91cf\u2014\u2014\u5e73\u5747\u63d0\u9ad8\u4e8615%\uff0c\u4e14\u5728\u4e0d\u540c\u5458\u5de5\u4e4b\u95f4\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002\u4e0d\u540c\u4ee3\u7406\u4eba\u5458\u7684\u53cd\u5e94\u5dee\u5f02\u663e\u8457\uff1a\u7ecf\u9a8c\u8f83\u5c11\u548c\u6280\u80fd\u8f83\u4f4e\u7684\u5458\u5de5\u5728\u8f93\u51fa\u901f\u5ea6\u548c\u8d28\u91cf\u4e0a\u5747\u6709\u63d0\u5347\uff0c\u800c\u6700\u8d44\u6df1\u548c\u6280\u80fd\u6700\u9ad8\u7684\u5458\u5de5\u5219\u4ec5\u5728\u901f\u5ea6\u4e0a\u7565\u6709\u6539\u5584\uff0c\u8d28\u91cf\u53cd\u800c\u7565\u6709\u4e0b\u964d\u3002\u6211\u4eec\u8fd8\u53d1\u73b0\uff0cAI\u8f85\u52a9\u6709\u52a9\u4e8e\u5458\u5de5\u5b66\u4e60\uff0c\u5e76\u63d0\u5347\u5176\u82f1\u8bed\u6d41\u5229\u5ea6\uff0c\u5c24\u5176\u5bf9\u56fd\u9645\u80cc\u666f\u7684\u4ee3\u7406\u4eba\u5458\u6548\u679c\u660e\u663e\u3002\u5c3d\u7ba1AI\u7cfb\u7edf\u968f\u7740\u8bad\u7ec3\u6570\u636e\u7684\u589e\u52a0\u800c\u4e0d\u65ad\u6539\u8fdb\uff0c\u4f46AI\u91c7\u7528\u5e26\u6765\u7684\u6536\u76ca\u5728\u76f8\u5bf9\u7f55\u89c1\u7684\u95ee\u9898\u4e0a\u6700\u4e3a\u663e\u8457\uff0c\u8fd9\u4e9b\u95ee\u9898\u5bf9\u4eba\u7c7b\u4ee3\u7406\u800c\u8a00\u7f3a\u4e4f\u57fa\u7840\u7ecf\u9a8c\uff0c\u4f46\u7cfb\u7edf\u4ecd\u5177\u5907\u8db3\u591f\u7684\u8bad\u7ec3\u6570\u636e\u3002\u6700\u540e\uff0c\u6211\u4eec\u53d1\u73b0AI\u8f85\u52a9\u5728\u591a\u4e2a\u65b9\u9762\u6539\u5584\u4e86\u5de5\u4f5c\u4f53\u9a8c\uff1a\u5ba2\u6237\u66f4\u52a0\u793c\u8c8c\uff0c\u4e14\u66f4\u5c11\u8981\u6c42\u4e0e\u7ecf\u7406\u901a\u8bdd\u3002", "translation_source": "journal-qwen4b", "topics": ["AI"]}, {"doi": "10.1093/qje/qjaf010", "journal": "QJE", "title": "Race to the Bottom: Competition and Quality in Science", "authors": ["Ryan Hill", "Carolyn Stein"], "author_details": [{"name": "Ryan Hill", "affiliations": ["Northwestern University ,"]}, {"name": "Carolyn Stein", "affiliations": ["University of California, Berkeley ,"]}], "abstract": "Abstract This article investigates how competition to publish first and thereby establish priority affects the quality of scientific research. We begin by developing a model where scientists decide whether and how long to work on a given project. When deciding how long they should let their projects mature, scientists trade off the marginal benefit of higher-quality research against the marginal risk of being preempted. Projects with the highest scientific potential are the most competitive because they induce the most entry. Therefore, the model predicts these projects are also the most rushed and lowest quality. We test the predictions of this model in the field of structural biology using data from the Protein Data Bank (PDB), a repository for structures of large macromolecules. An important feature of the PDB is that it assigns objective measures of scientific quality to each structure. As suggested by the model, we find that structures with higher ex ante potential generate more competition, are completed faster, and are lower quality. Consistent with the model, and with a causal interpretation of our empirical results, these relationships are mitigated when we focus on structures deposited by scientists who\u2014by nature of their employment position\u2014are less focused on publication and priority. We estimate that the costs associated with improving these low-quality structures are between $1.5 and $8.8 billion since the PDB\u2019s founding in 1971.", "date": "2025-02-03", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf010", "title_zh": "\u9010\u5e95\u7ade\u4e89\uff1a\u53d1\u8868\u4f18\u5148\u6743\u7ade\u4e89\u5bf9\u79d1\u5b66\u7814\u7a76\u8d28\u91cf\u7684\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e86\u4e3a\u4e89\u53d6\u7387\u5148\u53d1\u8868\u5e76\u786e\u7acb\u4f18\u5148\u6743\u800c\u4ea7\u751f\u7684\u7ade\u4e89\u5982\u4f55\u5f71\u54cd\u79d1\u5b66\u7814\u7a76\u7684\u8d28\u91cf\u3002\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6a21\u578b\uff0c\u5176\u4e2d\u79d1\u5b66\u5bb6\u51b3\u5b9a\u662f\u5426\u4ee5\u53ca\u5728\u591a\u957f\u65f6\u95f4\u5185\u6295\u5165\u67d0\u4e2a\u9879\u76ee\u3002\u5728\u51b3\u5b9a\u9879\u76ee\u6301\u7eed\u65f6\u95f4\u65f6\uff0c\u79d1\u5b66\u5bb6\u6743\u8861\u9ad8\u8d28\u91cf\u7814\u7a76\u7684\u8fb9\u9645\u6536\u76ca\u4e0e\u88ab\u62a2\u5148\u7684\u8fb9\u9645\u98ce\u9669\u3002\u79d1\u5b66\u6f5c\u529b\u6700\u9ad8\u7684\u9879\u76ee\u6700\u5177\u7ade\u4e89\u6027\uff0c\u56e0\u4e3a\u5b83\u4eec\u4f1a\u5f15\u53d1\u66f4\u591a\u8fdb\u5165\u8005\u3002\u56e0\u6b64\uff0c\u8be5\u6a21\u578b\u9884\u6d4b\u8fd9\u4e9b\u9879\u76ee\u4e5f\u6700\u4e3a\u4ed3\u4fc3\u4e14\u8d28\u91cf\u6700\u4f4e\u3002\u6211\u4eec\u5229\u7528\u86cb\u767d\u8d28\u6570\u636e\u94f6\u884c\uff08PDB\uff09\u7684\u6570\u636e\uff0c\u5bf9\u7ed3\u6784\u751f\u7269\u5b66\u9886\u57df\u8fdb\u884c\u4e86\u5b9e\u8bc1\u68c0\u9a8c\uff0cPDB\u662f\u4e00\u4e2a\u5b58\u50a8\u5927\u5206\u5b50\u7ed3\u6784\u7684\u6570\u636e\u5e93\uff0c\u5176\u5bf9\u6bcf\u4e2a\u7ed3\u6784\u90fd\u63d0\u4f9b\u4e86\u5ba2\u89c2\u7684\u8d28\u91cf\u8861\u91cf\u6807\u51c6\u3002\u6b63\u5982\u6a21\u578b\u6240\u9884\u6d4b\uff0c\u79d1\u5b66\u6f5c\u529b\u66f4\u9ad8\u7684\u9879\u76ee\u5f15\u53d1\u66f4\u591a\u7ade\u4e89\uff0c\u5b8c\u6210\u65f6\u95f4\u66f4\u77ed\uff0c\u8d28\u91cf\u4e5f\u66f4\u4f4e\u3002\u4e0e\u6a21\u578b\u9884\u6d4b\u4e00\u81f4\uff0c\u4e14\u5728\u5bf9\u5b9e\u8bc1\u7ed3\u679c\u8fdb\u884c\u56e0\u679c\u89e3\u91ca\u65f6\uff0c\u5f53\u6211\u4eec\u5173\u6ce8\u90a3\u4e9b\u56e0\u804c\u4f4d\u6027\u8d28\u800c\u8f83\u5c11\u5173\u6ce8\u53d1\u8868\u548c\u4f18\u5148\u6743\u7684\u79d1\u5b66\u5bb6\u6240\u63d0\u4ea4\u7684\u7ed3\u6784\u65f6\uff0c\u8fd9\u4e9b\u5173\u7cfb\u5f97\u5230\u4e86\u7f13\u89e3\u3002\u6211\u4eec\u4f30\u8ba1\uff0c\u81ea1971\u5e74PDB\u6210\u7acb\u4ee5\u6765\uff0c\u63d0\u5347\u8fd9\u4e9b\u4f4e\u8d28\u91cf\u7ed3\u6784\u6240\u9700\u7684\u6210\u672c\u572815\u4ebf\u7f8e\u5143\u81f388\u4ebf\u7f8e\u5143\u4e4b\u95f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf008", "journal": "QJE", "title": "Wage Hysteresis and Entitlement Effects: The Persistent Impacts of a Temporary Overtime Policy", "authors": ["Simon Quach"], "author_details": [{"name": "Simon Quach", "affiliations": ["University of Southern California ,"]}], "abstract": "Abstract This article studies the unexpected retraction of a U.S. federal policy in 2016 that would have more than doubled the \u201covertime exemption threshold\u201d from $455 to $913 per week and thereby grant overtime protection to an additional 20% of salaried workers. Although the policy was blocked by a federal court injunction a week before it was supposed to take effect, I show that it nevertheless had a persistent positive impact on workers\u2019 earnings. Leveraging a bunching design with administrative payroll data from ADP, I find that employers raised workers\u2019 salaries to the $913 threshold even after the policy was repealed. Over the next 18 months, difference-in-difference estimates reveal that employers did not slow the wage growth of workers affected by the policy relative to those already earning above $913 per week, nor did they hire new employees at a lower pay rate. Real wages remained persistently elevated relative to what they would have been absent the policy and separation rates decreased among workers bunched at the $913 threshold. Comparing highly exposed firms to unaffected firms, I find an increase in employers\u2019 wage bills but no change in aggregate employment. Taken together, the results indicate that temporary policies impacting wage levels can have permanent effects on the labor market. Survey responses collected by the Department of Labor suggest that morale concerns play a key role in driving the wage hysteresis.", "date": "2025-01-31", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf008", "title_zh": "\u5de5\u8d44\u6ede\u540e\u6548\u5e94\u4e0e\u6743\u76ca\u5f71\u54cd\uff1a\u4e34\u65f6\u52a0\u73ed\u653f\u7b56\u7684\u6301\u4e45\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u7814\u7a76\u4e862016\u5e74\u4e00\u9879\u7f8e\u56fd\u8054\u90a6\u653f\u7b56\u610f\u5916\u64a4\u56de\u7684\u4e8b\u4ef6\uff0c\u8be5\u653f\u7b56\u672c\u5e94\u5c06\u6bcf\u5468\u201c\u52a0\u73ed\u8d39\u8c41\u514d\u95e8\u69db\u201d\u4ece455\u7f8e\u5143\u63d0\u9ad8\u5230913\u7f8e\u5143\uff0c\u4ece\u800c\u4e3a\u989d\u591620%\u7684\u975e\u8ba1\u4ef6\u5de5\u8d44\u5458\u5de5\u63d0\u4f9b\u52a0\u73ed\u4fdd\u62a4\u3002\u5c3d\u7ba1\u8be5\u653f\u7b56\u5728\u539f\u5b9a\u751f\u6548\u524d\u4e00\u5468\u88ab\u8054\u90a6\u6cd5\u9662 injunction \u963b\u6b62\uff0c\u4f46\u672c\u6587\u53d1\u73b0\u5176\u4ecd\u5bf9\u5458\u5de5\u6536\u5165\u4ea7\u751f\u4e86\u6301\u4e45\u7684\u79ef\u6781\u5f71\u54cd\u3002\u5229\u7528ADP\u7684\u884c\u653f\u85aa\u916c\u6570\u636e\uff0c\u7ed3\u5408\u201c\u96c6\u4e2d\u6548\u5e94\u201d\u8bbe\u8ba1\uff0c\u7814\u7a76\u53d1\u73b0\u5373\u4f7f\u653f\u7b56\u88ab\u5e9f\u9664\uff0c\u96c7\u4e3b\u4ecd\u5c06\u5458\u5de5\u85aa\u8d44\u63d0\u5347\u81f3913\u7f8e\u5143\u95e8\u69db\u3002\u5728\u63a5\u4e0b\u6765\u768418\u4e2a\u6708\u5185\uff0c\u5dee\u5206\u5dee\u5206\u4f30\u8ba1\u8868\u660e\uff0c\u4e0e\u5df2\u8d85\u8fc7913\u7f8e\u5143/\u5468\u6536\u5165\u7684\u5458\u5de5\u76f8\u6bd4\uff0c\u53d7\u653f\u7b56\u5f71\u54cd\u7684\u5458\u5de5\u5de5\u8d44\u589e\u957f\u5e76\u672a\u653e\u7f13\uff0c\u4e14\u96c7\u4e3b\u5e76\u672a\u4ee5\u8f83\u4f4e\u85aa\u916c\u62db\u8058\u65b0\u5458\u5de5\u3002\u5b9e\u9645\u5de5\u8d44\u6301\u7eed\u9ad8\u4e8e\u653f\u7b56\u672a\u5b9e\u65bd\u65f6\u7684\u6c34\u5e73\uff0c\u540c\u65f6\u5728\u8fbe\u5230913\u7f8e\u5143\u95e8\u69db\u7684\u5458\u5de5\u4e2d\uff0c\u79bb\u804c\u7387\u4e5f\u6709\u6240\u4e0b\u964d\u3002\u5c06\u9ad8\u5ea6\u53d7\u5f71\u54cd\u7684\u516c\u53f8\u4e0e\u672a\u53d7\u5f71\u54cd\u7684\u516c\u53f8\u8fdb\u884c\u6bd4\u8f83\uff0c\u53d1\u73b0\u96c7\u4e3b\u7684\u5de5\u8d44\u652f\u51fa\u589e\u52a0\uff0c\u4f46\u603b\u4f53\u5c31\u4e1a\u4eba\u6570\u672a\u53d1\u751f\u53d8\u5316\u3002\u7efc\u5408\u6765\u770b\uff0c\u8fd9\u4e9b\u7ed3\u679c\u8868\u660e\uff0c\u5373\u4f7f\u77ed\u6682\u5f71\u54cd\u5de5\u8d44\u6c34\u5e73\u7684\u653f\u7b56\u4e5f\u53ef\u80fd\u5728\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u4ea7\u751f\u6301\u4e45\u6548\u5e94\u3002\u52b3\u5de5\u90e8\u6536\u96c6\u7684\u8c03\u67e5\u6570\u636e\u663e\u793a\uff0c\u5458\u5de5\u58eb\u6c14\u62c5\u5fe7\u5728\u9a71\u52a8\u5de5\u8d44\u6ede\u540e\u6548\u5e94\u4e2d\u8d77\u5230\u4e86\u5173\u952e\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf004", "journal": "QJE", "title": "Officer-Involved: The Media Language of Police Killings", "authors": ["Jonathan Moreno-Medina\u00ae", "Aur\u00e9lie Ouss\u00ae", "Patrick Bayer\u00ae", "Bocar A Ba\u00ae"], "author_details": [{"name": "Jonathan Moreno-Medina\u00ae", "affiliations": ["University of Texas, San Antonio ,"]}, {"name": "Aur\u00e9lie Ouss\u00ae", "affiliations": ["University of Pennsylvania and National Bureau of Economic Research ,"]}, {"name": "Patrick Bayer\u00ae", "affiliations": ["Duke University and National Bureau of Economic Research ,"]}, {"name": "Bocar A Ba\u00ae", "affiliations": ["Duke University and National Bureau of Economic Research ,"]}], "abstract": "Abstract This article examines language patterns in U.S. television news coverage of police killings. First, we document that the media use syntactic structures\u2014such as passive voice, nominalizations, and intransitive verbs\u2014that obscure responsibility more often in cases of police killings than in cases of civilian killings. Through an online experiment, we demonstrate the significance of these syntactic differences, revealing that participants are less likely to hold police officers morally responsible and demand penalties when exposed to obfuscatory language, particularly in cases involving unarmed victims. Further analysis of news data shows greater use of obfuscatory language when the victims are unarmed or video footage is available\u2014situations in which obfuscation may have the greatest impact. Exploring the causes of this differential obfuscation, we do not find evidence that it is driven by either demand-side factors or supply-side factors associated with TV station ownership and political leaning. Instead, our results suggest that narratives crafted by police departments are more likely drivers of media obfuscation. This article highlights how syntactic choices and their semantic consequences in media shape perceptions, extending beyond coverage volume and bias.", "date": "2025-01-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf004", "title_zh": "\u6d89\u8b66\u4e8b\u4ef6\uff1a\u8b66\u5bdf\u67aa\u6740\u4e8b\u4ef6\u7684\u5a92\u4f53\u62a5\u9053\u8bed\u8a00", "abstract_zh": "\u672c\u6587\u8003\u5bdf\u4e86\u7f8e\u56fd\u7535\u89c6\u65b0\u95fb\u5bf9\u8b66\u5bdf\u67aa\u6740\u4e8b\u4ef6\u7684\u8bed\u8a00\u6a21\u5f0f\u3002\u9996\u5148\uff0c\u6211\u4eec\u53d1\u73b0\u5a92\u4f53\u62a5\u9053\u5728\u8b66\u5bdf\u67aa\u6740\u4e8b\u4ef6\u4e2d\u6bd4\u5e73\u6c11\u6b7b\u4ea1\u4e8b\u4ef6\u66f4\u9891\u7e41\u5730\u4f7f\u7528\u906e\u853d\u8d23\u4efb\u7684\u53e5\u6cd5\u7ed3\u6784\uff0c\u4f8b\u5982\u88ab\u52a8\u8bed\u6001\u3001\u540d\u8bcd\u5316\u548c\u4e0d\u53ca\u7269\u52a8\u8bcd\u3002\u901a\u8fc7\u5728\u7ebf\u5b9e\u9a8c\uff0c\u6211\u4eec\u8bc1\u660e\u4e86\u8fd9\u4e9b\u53e5\u6cd5\u5dee\u5f02\u7684\u91cd\u8981\u6027\uff0c\u7ed3\u679c\u663e\u793a\uff0c\u5f53\u53c2\u4e0e\u8005\u63a5\u89e6\u5230\u906e\u853d\u6027\u8bed\u8a00\u65f6\uff0c\u4ed6\u4eec\u66f4\u5c11\u5c06\u8b66\u5bdf\u89c6\u4e3a\u9053\u5fb7\u4e0a\u8d1f\u6709\u8d23\u4efb\uff0c\u5e76\u4e14\u5bf9\u8b66\u5bdf\u7684\u60e9\u7f5a\u8981\u6c42\u4e5f\u66f4\u5c11\uff0c\u5c24\u5176\u662f\u5728\u6d89\u53ca\u65e0\u6b66\u88c5\u53d7\u5bb3\u8005\u7684\u60c5\u51b5\u4e0b\u3002\u8fdb\u4e00\u6b65\u5bf9\u65b0\u95fb\u6570\u636e\u7684\u5206\u6790\u8868\u660e\uff0c\u5f53\u53d7\u5bb3\u8005\u65e0\u6b66\u88c5\u6216\u6709\u89c6\u9891\u8d44\u6599\u65f6\uff0c\u906e\u853d\u6027\u8bed\u8a00\u7684\u4f7f\u7528\u66f4\u4e3a\u9891\u7e41\u2014\u2014\u8fd9\u4e9b\u60c5\u5883\u4e2d\u906e\u853d\u53ef\u80fd\u4ea7\u751f\u6700\u5927\u5f71\u54cd\u3002\u6211\u4eec\u63a2\u8ba8\u4e86\u8fd9\u79cd\u5dee\u5f02\u906e\u853d\u7684\u6210\u56e0\uff0c\u53d1\u73b0\u5176\u5e76\u975e\u7531\u89c2\u4f17\u9700\u6c42\u56e0\u7d20\u6216\u7535\u89c6\u53f0\u6240\u6709\u6743\u53ca\u653f\u6cbb\u503e\u5411\u7b49\u4f9b\u7ed9\u4fa7\u56e0\u7d20\u9a71\u52a8\u3002\u76f8\u53cd\uff0c\u6211\u4eec\u7684\u7ed3\u679c\u8868\u660e\uff0c\u8b66\u5bdf\u90e8\u95e8\u5236\u5b9a\u7684\u53d9\u4e8b\u66f4\u53ef\u80fd\u662f\u5a92\u4f53\u906e\u853d\u884c\u4e3a\u7684\u9a71\u52a8\u56e0\u7d20\u3002\u672c\u6587\u63ed\u793a\u4e86\u5a92\u4f53\u5728\u8bed\u8a00\u9009\u62e9\u53ca\u5176\u8bed\u4e49\u540e\u679c\u65b9\u9762\u5982\u4f55\u5f71\u54cd\u516c\u4f17\u8ba4\u77e5\uff0c\u8fd9\u8d85\u8d8a\u4e86\u62a5\u9053\u6570\u91cf\u548c\u504f\u89c1\u7684\u8303\u7574\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf006", "journal": "QJE", "title": "The Impact of Being Denied a Wanted Abortion on Women and Their Children", "authors": ["Juliana Londo\u00f1o-V\u00e9lez", "Estefan\u00eda Saravia"], "author_details": [{"name": "Juliana Londo\u00f1o-V\u00e9lez", "affiliations": ["University of California, Los Angeles and National Bureau of Economic Research ,"]}, {"name": "Estefan\u00eda Saravia", "affiliations": ["University of California, Los Angeles ,"]}], "abstract": "Abstract This article examines the impact of denying a wanted abortion on women and children in Colombia using high-quality administrative microdata and credibly exogenous variation in abortion access. Women can seek legal abortions through a tutela, with cases randomly assigned to judges. Female judges are 20 percentage points (32%) less likely to deny abortion cases than are male judges, and we use the judge\u2019s sex as an instrument for abortion denial. Denial of a wanted abortion has both immediate and lasting effects. It increases a woman\u2019s risk of death by 2.5 percentage points within nine months, mainly due to unsafe abortion procedures, and raises the likelihood of carrying the pregnancy to term by 31 percentage points. Tracking outcomes up to 15 years later, we find that women denied an abortion experience more health issues, lower educational attainment, reduced labor force participation, and higher rates of single motherhood, poverty, and reliance on government assistance. Existing children, born before their mother sought an abortion, are less likely to attend school and are more likely to work.", "date": "2025-01-24", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf006", "title_zh": "\u88ab\u62d2\u7edd\u83b7\u5f97\u60f3\u8981\u7684\u5815\u80ce\u5bf9\u5973\u6027\u53ca\u5176\u5b50\u5973\u7684\u5f71\u54cd", "abstract_zh": "\u672c\u6587\u5229\u7528\u9ad8\u8d28\u91cf\u7684\u884c\u653f\u5fae\u89c2\u6570\u636e\u548c\u5815\u80ce\u53ef\u53ca\u6027\u4e2d\u53ef\u4fe1\u7684\u5916\u751f\u53d8\u5f02\uff0c\u8003\u5bdf\u5728\u54e5\u4f26\u6bd4\u4e9a\u62d2\u7edd\u8fdb\u884c\u60f3\u8981\u7684\u5815\u80ce\u5bf9\u5973\u6027\u548c\u513f\u7ae5\u7684\u5f71\u54cd\u3002\u5973\u6027\u53ef\u4ee5\u901a\u8fc7\" tutela\" \u9014\u5f84\u5bfb\u6c42\u5408\u6cd5\u5815\u80ce\uff0c\u6848\u4ef6\u4f1a\u88ab\u968f\u673a\u5206\u914d\u7ed9\u6cd5\u5b98\u3002\u5973\u6027\u6cd5\u5b98\u6bd4\u7537\u6027\u6cd5\u5b98\u5c1120\u4e2a\u767e\u5206\u70b9\uff0832%\uff09\u5730\u62d2\u7edd\u5815\u80ce\u7533\u8bf7\uff0c\u6211\u4eec\u4ee5\u6cd5\u5b98\u6027\u522b\u4f5c\u4e3a\u5815\u80ce\u88ab\u62d2\u7edd\u7684\u5de5\u5177\u53d8\u91cf\u3002\u62d2\u7edd\u60f3\u8981\u7684\u5815\u80ce\u65e2\u6709\u5373\u65f6\u5f71\u54cd\uff0c\u4e5f\u6709\u957f\u671f\u540e\u679c\u3002\u5b83\u4f7f\u5973\u6027\u5728\u4e5d\u4e2a\u6708\u5185\u6b7b\u4ea1\u98ce\u9669\u589e\u52a02.5\u4e2a\u767e\u5206\u70b9\uff0c\u4e3b\u8981\u7531\u4e8e\u975e\u6cd5\u5815\u80ce\u64cd\u4f5c\uff0c\u540c\u65f6\u4f7f\u5973\u6027\u7ee7\u7eed\u598a\u5a20\u7684\u53ef\u80fd\u6027\u63d0\u9ad831\u4e2a\u767e\u5206\u70b9\u3002\u8ffd\u8e2a\u81f315\u5e74\u540e\uff0c\u88ab\u62d2\u7edd\u5815\u80ce\u7684\u5973\u6027\u9762\u4e34\u66f4\u591a\u5065\u5eb7\u95ee\u9898\u3001\u8f83\u4f4e\u7684\u6559\u80b2\u6c34\u5e73\u3001\u8f83\u5c11\u7684\u52b3\u52a8\u529b\u53c2\u4e0e\uff0c\u4ee5\u53ca\u66f4\u9ad8\u7684\u5355\u4eb2\u6bcd\u4eb2\u3001\u8d2b\u56f0\u548c\u4f9d\u8d56\u653f\u5e9c\u63f4\u52a9\u7684\u6982\u7387\u3002\u5728\u6bcd\u4eb2\u6b64\u524d\u5df2\u751f\u80b2\u7684\u5b50\u5973\u65b9\u9762\uff0c\u8fd9\u4e9b\u5b69\u5b50\u4e0a\u5b66\u7684\u53ef\u80fd\u6027\u66f4\u4f4e\uff0c\u66f4\u53ef\u80fd\u4ece\u4e8b\u5de5\u4f5c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.1093/qje/qjaf005", "journal": "QJE", "title": "\u201cSomething Works\u201d in U.S. Jails: Misconduct and Recidivism Effects of the IGNITE Program", "authors": ["Marcella Alsan", "Arkey Barnett", "Peter Hull", "Crystal S Yang"], "abstract": "Abstract A long-standing and influential view in U.S. correctional policy is that \u201cnothing works\u201d when it comes to rehabilitating incarcerated individuals. We revisit this hypothesis by studying an innovative law-enforcement-led program launched in the county jail of Flint, MI: Inmate Growth Naturally and Intentionally through Education (IGNITE). We develop an instrumental variables approach to estimate the effects of IGNITE exposure, leveraging quasi-random court delays that cause individuals to spend more time in jail before and after the program\u2019s launch. Holding time in jail fixed, we find that one additional month of IGNITE exposure reduces weekly misconduct in jail by 25% and three-month recidivism by 24%, with the recidivism effects growing over time. Surveys of staff and community members, along with administrative test-score records and within-jail text messages, suggest that cultural change and improved literacy and numeracy scores are contributing mechanisms.", "date": "2025-01-20", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.1093/qje/qjaf005", "topics": ["\u5176\u4ed6"], "title_zh": "\u7f8e\u56fd\u76d1\u72f1\u4e2d\u7684\u2018\u67d0\u79cd\u65b9\u6cd5\u6709\u6548\u2019\uff1aIGNITE\u9879\u76ee\u7684\u884c\u4e3a\u4e0d\u5f53\u4e0e\u518d\u72af\u5f71\u54cd", "abstract_zh": "\u6458\u8981 \u957f\u671f\u4ee5\u6765\uff0c\u7f8e\u56fd\u77eb\u6b63\u653f\u7b56\u4e2d\u5b58\u5728\u4e00\u79cd\u4e3b\u6d41\u89c2\u70b9\uff0c\u5373\u201c\u5bf9\u5728\u62bc\u4eba\u5458\u7684\u6539\u9020\u6ca1\u6709\u4efb\u4f55\u6709\u6548\u65b9\u6cd5\u201d\u3002\u6211\u4eec\u901a\u8fc7\u7814\u7a76\u5bc6\u6b47\u6839\u5dde\u5f17\u6797\u7279\u53bf\u76d1\u72f1\u4e2d\u4e00\u9879\u7531\u6267\u6cd5\u90e8\u95e8\u4e3b\u5bfc\u7684\u521b\u65b0\u9879\u76ee\u2014\u2014\u901a\u8fc7\u6559\u80b2\u5b9e\u73b0\u56da\u72af\u81ea\u7136\u4e14\u6709\u610f\u8bc6\u7684\u6210\u957f\uff08IGNITE\uff09\u2014\u2014\u91cd\u65b0\u5ba1\u89c6\u8fd9\u4e00\u5047\u8bbe\u3002\u6211\u4eec\u91c7\u7528\u5de5\u5177\u53d8\u91cf\u6cd5\u6765\u4f30\u8ba1IGNITE\u9879\u76ee\u66b4\u9732\u7684\u5f71\u54cd\uff0c\u5229\u7528\u6cd5\u9662\u5ef6\u8fdf\u8fd9\u4e00\u51c6\u968f\u673a\u4e8b\u4ef6\uff0c\u8be5\u4e8b\u4ef6\u5bfc\u81f4\u4e2a\u4f53\u5728\u9879\u76ee\u542f\u52a8\u524d\u548c\u542f\u52a8\u540e\u5728\u76d1\u72f1\u4e2d\u505c\u7559\u65f6\u95f4\u5ef6\u957f\u3002\u5728\u56fa\u5b9a\u670d\u5211\u65f6\u95f4\u7684\u524d\u63d0\u4e0b\uff0c\u6211\u4eec\u53d1\u73b0\uff0c\u6bcf\u591a\u4e00\u4e2a\u6708\u7684IGNITE\u9879\u76ee\u53c2\u4e0e\uff0c\u53ef\u4f7f\u76d1\u72f1\u5185\u7684\u6bcf\u5468\u4e0d\u5f53\u884c\u4e3a\u51cf\u5c1125%\uff0c\u4e09\u5e74\u5185\u518d\u72af\u7387\u4e0b\u964d24%\uff0c\u4e14\u518d\u72af\u6548\u5e94\u968f\u65f6\u95f4\u63a8\u79fb\u800c\u589e\u5f3a\u3002\u5de5\u4f5c\u4eba\u5458\u548c\u793e\u533a\u6210\u5458\u7684\u8c03\u67e5\uff0c\u4ee5\u53ca\u884c\u653f\u6d4b\u8bd5\u6210\u7ee9\u8bb0\u5f55\u548c\u72f1\u5185\u77ed\u4fe1\u6570\u636e\u8868\u660e\uff0c\u6587\u5316\u8f6c\u53d8\u3001\u8bc6\u5b57\u548c\u7b97\u672f\u80fd\u529b\u63d0\u5347\u53ef\u80fd\u662f\u5176\u53d1\u6325\u4f5c\u7528\u7684\u673a\u5236\u3002", "translation_source": "journal-qwen4b"}, {"doi": "10.3982/ecta18492", "journal": "ECTA", "title": "Fiduciary Duty and the Market for Financial Advice", "authors": ["Vivek Bhattacharya", "Gast\u00f3n Illanes", "Manisha Padi"], "author_details": [{"name": "Vivek Bhattacharya", "affiliations": ["Department of Economics, Northwestern University", "National Bureau of Economic Research"]}, {"name": "Gast\u00f3n Illanes", "affiliations": ["Department of Economics, Northwestern University", "National Bureau of Economic Research"]}, {"name": "Manisha Padi", "affiliations": ["Berkeley School of Law, University of California"]}], "abstract": "Fiduciary duty aims to solve principal\u2010agent problems, and the United States is in the middle of a protracted debate surrounding the merits of extending it to all financial advisers. Leveraging a transaction\u2010level data set of deferred annuities and state\u2010level variation in common law fiduciary duty, we find that it raises risk\u2010adjusted returns by 25 bp and leads to a 16% decline in the entry of affected firms. Through the lens of a model of entry and advice provision, we show that this effect can be due to both an increase in fixed costs and an increase in the cost of providing low\u2010quality advice. We show how to disentangle these channels and find that both are empirically relevant. Counterfactual simulations show that further increases in the stringency of fiduciary duty monotonically improve advice quality.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta18492", "title_zh": "\u4fe1\u6258\u4e49\u52a1\u4e0e\u91d1\u878d\u54a8\u8be2\u670d\u52a1\u5e02\u573a", "abstract_zh": "\u4fe1\u6258\u4e49\u52a1\u65e8\u5728\u89e3\u51b3\u59d4\u6258\u4ee3\u7406\u95ee\u9898\uff0c\u7f8e\u56fd\u76ee\u524d\u6b63\u5c31\u662f\u5426\u5c06\u8fd9\u4e00\u4e49\u52a1\u6269\u5c55\u81f3\u6240\u6709\u91d1\u878d\u987e\u95ee\u5c55\u5f00\u957f\u671f\u8fa9\u8bba\u3002\u57fa\u4e8e\u4e00\u9879\u6db5\u76d6\u5ef6\u671f\u5e74\u91d1\u4ea4\u6613\u5c42\u9762\u7684\u6570\u636e\u96c6\uff0c\u4ee5\u53ca\u5404\u5dde\u666e\u901a\u6cd5\u4fe1\u6258\u4e49\u52a1\u7684\u5dee\u5f02\uff0c\u6211\u4eec\u53d1\u73b0\u8be5\u4e49\u52a1\u63d0\u9ad8\u4e86\u98ce\u9669\u8c03\u6574\u540e\u7684\u6536\u76ca25\u4e2a\u57fa\u70b9\uff0c\u5e76\u5bfc\u81f4\u53d7\u5f71\u54cd\u4f01\u4e1a\u7684\u8fdb\u5165\u91cf\u4e0b\u964d16%\u3002\u901a\u8fc7\u4e00\u4e2a\u5173\u4e8e\u4f01\u4e1a\u8fdb\u5165\u548c\u54a8\u8be2\u670d\u52a1\u63d0\u4f9b\u7684\u6a21\u578b\uff0c\u6211\u4eec\u8868\u660e\u8fd9\u79cd\u6548\u5e94\u53ef\u80fd\u6e90\u4e8e\u56fa\u5b9a\u6210\u672c\u4e0a\u5347\u4ee5\u53ca\u63d0\u4f9b\u4f4e\u8d28\u91cf\u5efa\u8bae\u7684\u6210\u672c\u4e0a\u5347\u3002\u6211\u4eec\u5c55\u793a\u4e86\u5982\u4f55\u5206\u79bb\u8fd9\u4e9b\u6e20\u9053\uff0c\u5e76\u53d1\u73b0\u4e24\u8005\u5728\u7ecf\u9a8c\u4e0a\u5747\u5177\u6709\u76f8\u5173\u6027\u3002\u53cd\u4e8b\u5b9e\u6a21\u62df\u8868\u660e\uff0c\u8fdb\u4e00\u6b65\u63d0\u9ad8\u4fe1\u6258\u4e49\u52a1\u7684\u4e25\u683c\u6027\u5c06\u5355\u8c03\u63d0\u5347\u54a8\u8be2\u670d\u52a1\u7684\u8d28\u91cf\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta17051", "journal": "ECTA", "title": "Persuasion Meets Delegation", "authors": ["Anton Kolotilin", "Andriy Zapechelnyuk"], "author_details": [{"name": "Anton Kolotilin", "affiliations": ["School of Economics, UNSW Business School"]}, {"name": "Andriy Zapechelnyuk", "affiliations": ["School of Economics, University of Edinburgh"]}], "abstract": "A principal can restrict an agent's information (the persuasion problem) or discretion (the delegation problem). We study these two problems under standard single\u2010crossing assumptions on the agent's marginal utility. We show that these problems are equivalent on the set of monotone stochastic mechanisms, implying, in particular, the equivalence of deterministic delegation and monotone partitional persuasion. We also show that the monotonicity restriction is superfluous for linear persuasion and linear delegation, implying their equivalence on the set of all stochastic mechanisms. Finally, using tools from the persuasion literature, we characterize optimal delegation mechanisms, thereby generalizing and extending existing results in the delegation literature.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta17051", "title_zh": "\u8bf4\u670d\u4e0e\u59d4\u6258\u7684\u7ed3\u5408", "abstract_zh": "\u4ee3\u7406\u4eba\u53ef\u4ee5\u88ab\u9650\u5236\u5176\u4fe1\u606f\uff08\u8bf4\u670d\u95ee\u9898\uff09\u6216\u81ea\u4e3b\u6743\uff08\u59d4\u6258\u95ee\u9898\uff09\u3002\u6211\u4eec\u5728\u4ee3\u7406\u4eba\u8fb9\u9645\u6548\u7528\u6ee1\u8db3\u6807\u51c6\u5355\u4ea4\u53c9\u5047\u8bbe\u7684\u6761\u4ef6\u4e0b\u7814\u7a76\u8fd9\u4e24\u4e2a\u95ee\u9898\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5728\u5355\u8c03\u968f\u673a\u673a\u5236\u96c6\u5408\u4e0a\uff0c\u8fd9\u4e24\u4e2a\u95ee\u9898\u7b49\u4ef7\uff0c\u7279\u522b\u5730\uff0c\u786e\u5b9a\u6027\u59d4\u6258\u4e0e\u5355\u8c03\u5206\u6bb5\u8bf4\u670d\u662f\u7b49\u4ef7\u7684\u3002\u6211\u4eec\u8fd8\u8bc1\u660e\uff0c\u5bf9\u4e8e\u7ebf\u6027\u8bf4\u670d\u548c\u7ebf\u6027\u59d4\u6258\uff0c\u5355\u8c03\u6027\u9650\u5236\u662f\u591a\u4f59\u7684\uff0c\u610f\u5473\u7740\u5b83\u4eec\u5728\u6240\u6709\u968f\u673a\u673a\u5236\u96c6\u5408\u4e0a\u662f\u7b49\u4ef7\u7684\u3002\u6700\u540e\uff0c\u5229\u7528\u8bf4\u670d\u9886\u57df\u7684\u5de5\u5177\uff0c\u6211\u4eec\u523b\u753b\u4e86\u6700\u4f18\u59d4\u6258\u673a\u5236\uff0c\u4ece\u800c\u6269\u5c55\u5e76\u6df1\u5316\u4e86\u73b0\u6709\u59d4\u6258\u9886\u57df\u7684\u7814\u7a76\u6210\u679c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta21343", "journal": "ECTA", "title": "Auctioning Control and Cash\u2010Flow Rights Separately", "authors": ["Tingjun Liu", "Dan Bernhardt"], "author_details": [{"name": "Tingjun Liu", "affiliations": ["Faculty of Business and Economics, University of Hong Kong"]}, {"name": "Dan Bernhardt", "affiliations": ["Department of Economics, University of Illinois", "Department of Economics, University of Warwick"]}], "abstract": "We consider a classical auction setting in which an asset/project is sold to buyers who privately receive signals about expected payoffs, and payoffs are more sensitive to a bidder's signal if he runs the project than if another bidder does. We show that a seller can increase revenues by sometimes allocating cash\u2010flow rights and control to different bidders, for example, with the highest bidder receiving cash flows and the second\u2010highest receiving control. Separation reduces a bidder's information rent, which depends on the importance of his private information for the value of his awarded cash flows. As project payoffs are most sensitive to a bidder's information if he controls the project, allocating cash flow to another bidder lowers bidders' informational advantage. As a result, when signals are close, the seller can increase revenues by splitting rights between the top two bidders.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21343", "title_zh": "\u5206\u522b\u62cd\u5356\u63a7\u5236\u6743\u548c\u73b0\u91d1\u6d41\u6743\u5229", "abstract_zh": "\u6211\u4eec\u8003\u8651\u4e00\u4e2a\u7ecf\u5178\u62cd\u5356\u73af\u5883\uff0c\u5176\u4e2d\u4e00\u9879\u8d44\u4ea7\u6216\u9879\u76ee\u88ab\u51fa\u552e\u7ed9\u4e70\u5bb6\uff0c\u4e70\u5bb6\u4f1a\u79c1\u4e0b\u83b7\u5f97\u5173\u4e8e\u9884\u671f\u6536\u76ca\u7684\u4fe1\u53f7\uff0c\u4e14\u5982\u679c\u67d0\u4e70\u5bb6\u8fd0\u8425\u9879\u76ee\uff0c\u5176\u6536\u76ca\u5bf9\u4e70\u5bb6\u4fe1\u53f7\u7684\u654f\u611f\u5ea6\u4f1a\u9ad8\u4e8e\u7531\u5176\u4ed6\u4e70\u5bb6\u8fd0\u8425\u65f6\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u5356\u5bb6\u53ef\u4ee5\u901a\u8fc7\u5728\u67d0\u4e9b\u60c5\u51b5\u4e0b\u5c06\u73b0\u91d1\u6d41\u6743\u5229\u548c\u63a7\u5236\u6743\u5206\u914d\u7ed9\u4e0d\u540c\u7684\u4e70\u5bb6\u6765\u63d0\u9ad8\u6536\u5165\uff0c\u4f8b\u5982\uff0c\u6700\u9ad8\u51fa\u4ef7\u8005\u83b7\u5f97\u73b0\u91d1\u6d41\uff0c\u7b2c\u4e8c\u9ad8\u51fa\u4ef7\u8005\u83b7\u5f97\u63a7\u5236\u6743\u3002\u6743\u5229\u5206\u79bb\u51cf\u5c11\u4e86\u4e70\u5bb6\u7684\u4fe1\u606f\u79df\u91d1\uff0c\u800c\u4fe1\u606f\u79df\u91d1\u53d6\u51b3\u4e8e\u5176\u79c1\u4eba\u4fe1\u606f\u5bf9\u6240\u83b7\u5f97\u73b0\u91d1\u6d41\u4ef7\u503c\u7684\u91cd\u8981\u6027\u3002\u7531\u4e8e\u9879\u76ee\u6536\u76ca\u5728\u4e70\u5bb6\u62e5\u6709\u63a7\u5236\u6743\u65f6\u5bf9\u4e70\u5bb6\u4fe1\u606f\u6700\u4e3a\u654f\u611f\uff0c\u5c06\u73b0\u91d1\u6d41\u5206\u914d\u7ed9\u5176\u4ed6\u4e70\u5bb6\u4f1a\u524a\u5f31\u4e70\u5bb6\u7684\u4fe1\u606f\u4f18\u52bf\u3002\u56e0\u6b64\uff0c\u5f53\u4fe1\u53f7\u63a5\u8fd1\u65f6\uff0c\u5356\u5bb6\u53ef\u4ee5\u901a\u8fc7\u5728\u524d\u4e24\u540d\u4e70\u5bb6\u4e4b\u95f4\u5206\u5272\u6743\u5229\u6765\u63d0\u9ad8\u6536\u5165\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta18063", "journal": "ECTA", "title": "Private Information and Price Regulation in the US Credit Card Market", "authors": ["Scott T. Nelson"], "author_details": [{"name": "Scott T. Nelson", "affiliations": ["Booth School of Business, University of Chicago"]}], "abstract": "The 2009 CARD Act limited credit card lenders' ability to raise borrowers' interest rates on the basis of new information. Pricing became less responsive to public and private signals of borrowers' risk and demand characteristics, and price dispersion fell by one\u2010third. I estimate the efficiency and distributional effects of this shift toward more pooled pricing. Prices fell for high\u2010risk and price\u2010inelastic consumers, but prices rose elsewhere in the market and newly exceeded willingness to pay for over 30% of the safest subprime borrowers. On net, average traded prices fell and consumer surplus rose at all credit scores. Higher consumer surplus was partly driven by a fall in lender profits, and partly by the Act's insurance value to borrowers who could retain favorable pricing after adverse changes to their default risk. The relatively high level of pre\u2010CARD\u2010Act markups was crucial for realizing these surplus gains.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta18063", "title_zh": "\u79c1\u4eba\u4fe1\u606f\u4e0e\u7f8e\u56fd\u4fe1\u7528\u5361\u5e02\u573a\u7684\u4ef7\u683c\u76d1\u7ba1", "abstract_zh": "2009\u5e74\u7684\u300a\u4fe1\u7528\u5361\u6cd5\u300b\uff08CARD Act\uff09\u9650\u5236\u4e86\u4fe1\u7528\u5361\u8d37\u6b3e\u673a\u6784\u6839\u636e\u501f\u6b3e\u4eba\u65b0\u4fe1\u606f\u63d0\u9ad8\u5176\u5229\u7387\u7684\u80fd\u529b\u3002\u4ef7\u683c\u5bf9\u501f\u6b3e\u4eba\u98ce\u9669\u548c\u9700\u6c42\u7279\u5f81\u7684\u516c\u5171\u53ca\u79c1\u4eba\u4fe1\u53f7\u7684\u54cd\u5e94\u6027\u964d\u4f4e\uff0c\u4ef7\u683c\u5dee\u5f02\u4e0b\u964d\u4e86\u4e09\u5206\u4e4b\u4e00\u3002\u6211\u4f30\u8ba1\u4e86\u8fd9\u4e00\u5411\u66f4\u96c6\u4e2d\u5b9a\u4ef7\u8f6c\u53d8\u7684\u6548\u7387\u548c\u5206\u914d\u6548\u5e94\u3002\u5bf9\u4e8e\u9ad8\u98ce\u9669\u548c\u4ef7\u683c\u5f39\u6027\u8f83\u4f4e\u7684\u6d88\u8d39\u8005\uff0c\u4ef7\u683c\u4e0b\u964d\uff1b\u4f46\u5728\u5e02\u573a\u5176\u4ed6\u90e8\u5206\uff0c\u4ef7\u683c\u4e0a\u5347\uff0c\u4e14\u5bf9\u8d85\u8fc730%\u6700\u5b89\u5168\u7684\u6b21\u7ea7\u501f\u6b3e\u4eba\u800c\u8a00\uff0c\u4ef7\u683c\u5df2\u8d85\u8fc7\u5176\u613f\u610f\u652f\u4ed8\u7684\u6c34\u5e73\u3002\u603b\u4f53\u800c\u8a00\uff0c\u5e73\u5747\u4ea4\u6613\u4ef7\u683c\u4e0b\u964d\uff0c\u6240\u6709\u4fe1\u7528\u8bc4\u5206\u7b49\u7ea7\u4e0b\u7684\u6d88\u8d39\u8005\u5269\u4f59\u4e0a\u5347\u3002\u6d88\u8d39\u8005\u5269\u4f59\u7684\u589e\u52a0\u90e8\u5206\u6e90\u4e8e\u8d37\u6b3e\u673a\u6784\u5229\u6da6\u7684\u4e0b\u964d\uff0c\u90e8\u5206\u6e90\u4e8e\u8be5\u6cd5\u6848\u4e3a\u501f\u6b3e\u4eba\u63d0\u4f9b\u4e86\u4fdd\u9669\u4ef7\u503c\u2014\u2014\u5373\u5728\u8fdd\u7ea6\u98ce\u9669\u6076\u5316\u65f6\u4ecd\u80fd\u4fdd\u7559\u6709\u5229\u5b9a\u4ef7\u3002\u5728\u5b9e\u73b0\u8fd9\u4e9b\u5269\u4f59\u6536\u76ca\u65b9\u9762\uff0c\u4e8b\u524d\u300a\u4fe1\u7528\u5361\u6cd5\u300b\u65f6\u671f\u7684\u9ad8\u5229\u6da6\u7387\u8d77\u5230\u4e86\u5173\u952e\u4f5c\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22144", "journal": "ECTA", "title": "A Quest for Knowledge", "authors": ["Christoph Carnehl", "Johannes Schneider"], "author_details": [{"name": "Christoph Carnehl", "affiliations": ["Dept. of Economics & IGIER, Bocconi University"]}, {"name": "Johannes Schneider", "affiliations": ["Department of Economics, Universidad Carlos III de Madrid"]}], "abstract": "Is more novel research always desirable? We develop a model in which knowledge shapes society's policies and guides the search for discoveries. Researchers select a question and how intensely to study it. The novelty of a question determines both the value and difficulty of discovering its answer. We show that the benefits of discoveries are nonmonotone in novelty. Knowledge expands endogenously step\u2010by\u2010step over time. Through a dynamic externality, moonshots\u2014research on questions more novel than what is myopically optimal\u2014can improve the evolution of knowledge. Moonshots induce research cycles in which subsequent researchers connect the moonshot to previous knowledge.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22144", "title_zh": "\u77e5\u8bc6\u63a2\u7d22\u4e4b\u65c5", "abstract_zh": "\u66f4\u591a\u7684\u65b0\u9896\u7814\u7a76\u603b\u662f\u66f4\u6709\u4ef7\u503c\u5417\uff1f\u6211\u4eec\u6784\u5efa\u4e86\u4e00\u4e2a\u6a21\u578b\uff0c\u5176\u4e2d\u77e5\u8bc6\u5851\u9020\u4e86\u793e\u4f1a\u653f\u7b56\u5e76\u6307\u5bfc\u53d1\u73b0\u7684\u641c\u7d22\u8fc7\u7a0b\u3002\u7814\u7a76\u4eba\u5458\u9009\u62e9\u4e00\u4e2a\u7814\u7a76\u95ee\u9898\u4ee5\u53ca\u7814\u7a76\u7684\u5f3a\u5ea6\u3002\u95ee\u9898\u7684\u65b0\u9896\u6027\u51b3\u5b9a\u4e86\u53d1\u73b0\u5176\u7b54\u6848\u7684\u4ef7\u503c\u548c\u96be\u5ea6\u3002\u6211\u4eec\u8bc1\u660e\uff0c\u53d1\u73b0\u7684\u6536\u76ca\u4e0e\u65b0\u9896\u6027\u4e4b\u95f4\u662f\u975e\u5355\u8c03\u5173\u7cfb\u3002\u77e5\u8bc6\u968f\u7740\u65f6\u95f4\u9010\u6b65\u5185\u751f\u6269\u5c55\u3002\u901a\u8fc7\u52a8\u6001\u5916\u90e8\u6027\uff0c\u90a3\u4e9b\u6bd4\u77ed\u671f\u6700\u4f18\u66f4\u65b0\u9896\u7684\u7814\u7a76\uff08\u5373\u201c\u6708\u7403\u7ea7\u201d\u7814\u7a76\uff09\u80fd\u591f\u4fc3\u8fdb\u77e5\u8bc6\u6f14\u8fdb\u3002\u6708\u7403\u7ea7\u7814\u7a76\u5f15\u53d1\u7814\u7a76\u5468\u671f\uff0c\u5728\u8fd9\u4e9b\u5468\u671f\u4e2d\uff0c\u540e\u7eed\u7814\u7a76\u4eba\u5458\u5c06\u6708\u7403\u7ea7\u7814\u7a76\u4e0e\u5148\u524d\u77e5\u8bc6\u8054\u7cfb\u8d77\u6765\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta20203", "journal": "ECTA", "title": "Choices and Outcomes in Assignment Mechanisms: The Allocation of Deceased Donor Kidneys", "authors": ["Nikhil Agarwal", "Charles Hodgson", "Paulo Somaini"], "author_details": [{"name": "Nikhil Agarwal", "affiliations": ["Department of Economics, MIT", "NBER"]}, {"name": "Charles Hodgson", "affiliations": ["Department of Economics, Yale University", "NBER"]}, {"name": "Paulo Somaini", "affiliations": ["Graduate School of Business, Stanford University", "NBER"]}], "abstract": "While the mechanism design paradigm emphasizes notions of efficiency based on agent preferences, policymakers often focus on alternative objectives. School districts emphasize educational achievement, and transplantation communities focus on patient survival. It is unclear whether choice\u2010based mechanisms perform well when assessed based on these outcomes. This paper evaluates the assignment mechanism for allocating deceased donor kidneys on the basis of patient life\u2010years from transplantation (LYFT). We examine the role of choice in increasing LYFT and compare realized assignments to benchmarks that remove choice. Our model combines choices and outcomes in order to study how selection affects LYFT. We show how to identify and estimate the model using instruments derived from the mechanism. The estimates suggest that the design in use selects patients with better post\u2010transplant survival prospects and matches them well, resulting in an average LYFT of 9.29, which is 1.75 years more than a random assignment. However, the maximum aggregate LYFT is 14.08. Realizing the majority of the gains requires transplanting relatively healthy patients, who would have longer life expectancies even without a transplant. Therefore, a policymaker faces a dilemma between transplanting patients who are sicker and those for whom life will be extended the longest.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta20203", "title_zh": "\u5728\u5206\u914d\u673a\u5236\u4e2d\u7684\u9009\u62e9\u4e0e\u7ed3\u679c\uff1a\u6b7b\u4f9b\u4f53\u80be\u810f\u7684\u5206\u914d", "abstract_zh": "\u867d\u7136\u673a\u5236\u8bbe\u8ba1\u8303\u5f0f\u5f3a\u8c03\u57fa\u4e8e\u4ee3\u7406\u4eba\u504f\u597d\u7684\u6548\u7387\u6982\u5ff5\uff0c\u4f46\u653f\u7b56\u5236\u5b9a\u8005\u5f80\u5f80\u5173\u6ce8\u5176\u4ed6\u76ee\u6807\u3002\u5b66\u533a\u91cd\u89c6\u6559\u80b2\u6210\u679c\uff0c\u79fb\u690d\u793e\u533a\u5219\u5173\u6ce8\u60a3\u8005\u751f\u5b58\u7387\u3002\u76ee\u524d\u5c1a\u4e0d\u6e05\u695a\u57fa\u4e8e\u9009\u62e9\u7684\u673a\u5236\u5728\u4ee5\u8fd9\u4e9b\u7ed3\u679c\u4e3a\u8bc4\u4f30\u6807\u51c6\u65f6\u8868\u73b0\u5982\u4f55\u3002\u672c\u6587\u57fa\u4e8e\u79fb\u690d\u60a3\u8005\u63a5\u53d7\u79fb\u690d\u540e\u7684\u751f\u547d\u5e74\u6570\uff08LYFT\uff09\u6765\u8bc4\u4f30\u6b7b\u4f9b\u4f53\u80be\u810f\u5206\u914d\u673a\u5236\u7684\u8868\u73b0\u3002\u6211\u4eec\u8003\u5bdf\u4e86\u9009\u62e9\u5728\u63d0\u5347LYFT\u4e2d\u7684\u4f5c\u7528\uff0c\u5e76\u5c06\u5b9e\u9645\u5206\u914d\u7ed3\u679c\u4e0e\u79fb\u9664\u9009\u62e9\u7684\u57fa\u51c6\u8fdb\u884c\u6bd4\u8f83\u3002\u672c\u6a21\u578b\u7ed3\u5408\u4e86\u9009\u62e9\u4e0e\u7ed3\u679c\uff0c\u4ee5\u7814\u7a76\u9009\u62e9\u5982\u4f55\u5f71\u54cdLYFT\u3002\u6211\u4eec\u901a\u8fc7\u4ece\u673a\u5236\u4e2d\u5bfc\u51fa\u7684\u5de5\u5177\u53d8\u91cf\u6765\u8bc6\u522b\u5e76\u4f30\u8ba1\u8be5\u6a21\u578b\u3002\u4f30\u8ba1\u7ed3\u679c\u8868\u660e\uff0c\u5f53\u524d\u8bbe\u8ba1\u503e\u5411\u4e8e\u9009\u62e9\u672f\u540e\u751f\u5b58\u524d\u666f\u66f4\u597d\u7684\u60a3\u8005\uff0c\u5e76\u8fdb\u884c\u826f\u597d\u5339\u914d\uff0c\u4ece\u800c\u5b9e\u73b0\u5e73\u5747LYFT\u4e3a9.29\u5e74\uff0c\u6bd4\u968f\u673a\u5206\u914d\u9ad8\u51fa1.75\u5e74\u3002\u7136\u800c\uff0c\u6700\u5927\u7fa4\u4f53LYFT\u4e3a14.08\u5e74\u3002\u8981\u5b9e\u73b0\u5927\u90e8\u5206\u6536\u76ca\uff0c\u5fc5\u987b\u79fb\u690d\u76f8\u5bf9\u5065\u5eb7\u7684\u60a3\u8005\uff0c\u8fd9\u4e9b\u60a3\u8005\u5373\u4f7f\u6ca1\u6709\u79fb\u690d\uff0c\u5176\u9884\u671f\u5bff\u547d\u4e5f\u66f4\u957f\u3002\u56e0\u6b64\uff0c\u653f\u7b56\u5236\u5b9a\u8005\u9762\u4e34\u4e00\u4e2a\u4e24\u96be\u9009\u62e9\uff1a\u662f\u79fb\u690d\u75c5\u60c5\u8f83\u91cd\u7684\u60a3\u8005\uff0c\u8fd8\u662f\u4f18\u5148\u79fb\u690d\u90a3\u4e9b\u79fb\u690d\u540e\u751f\u547d\u5f97\u4ee5\u663e\u8457\u5ef6\u957f\u7684\u60a3\u8005\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta18385", "journal": "ECTA", "title": "Transparency and Percent Plans", "authors": ["Adam Kapor"], "author_details": [{"name": "Adam Kapor", "affiliations": ["Department of Economics and School of Public and International Affairs, Princeton University"]}], "abstract": "Transparency versus opacity is an important dimension of college admission policy. Colleges may gain useful information from a holistic review of applicants' materials, but in doing so may contribute to uncertainty that discourages potential applicants with poor information. This paper investigates the impacts of admissions transparency in the context of Texas' Top Ten Percent Plan, using survey and administrative data from Texas and a model of college applications, admissions, enrollment, grades, and persistence. I estimate that two thirds of the plan's 9.1 point impact on top\u2010decile students' probability of attending a flagship university was due to information rather than mechanical effects. Students induced to enroll are more likely to come from low\u2010income high schools, and academically outperform the students that they displace. These effects would be larger if complemented by financial\u2010aid information, and are driven by transparency, not misalignment between the rules used for automatic and discretionary admissions.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta18385", "title_zh": "\u900f\u660e\u5ea6\u4e0e\u767e\u5206\u6bd4\u8ba1\u5212", "abstract_zh": "\u900f\u660e\u5ea6\u4e0e\u4e0d\u900f\u660e\u6027\u662f\u5927\u5b66\u62db\u751f\u653f\u7b56\u4e2d\u7684\u4e00\u4e2a\u91cd\u8981\u7ef4\u5ea6\u3002\u5927\u5b66\u53ef\u80fd\u4ece\u5bf9\u7533\u8bf7\u6750\u6599\u7684\u5168\u9762\u5ba1\u67e5\u4e2d\u83b7\u5f97\u6709\u7528\u4fe1\u606f\uff0c\u4f46\u8fd9\u6837\u505a\u53ef\u80fd\u4f1a\u5e26\u6765\u4e0d\u786e\u5b9a\u6027\uff0c\u4ece\u800c\u6291\u5236\u4fe1\u606f\u4e0d\u8db3\u7684\u6f5c\u5728\u7533\u8bf7\u8005\u3002\u672c\u6587\u5728\u5fb7\u514b\u8428\u65af\u5dde\u7684\u524d\u5341\u767e\u5206\u6bd4\u8ba1\u5212\u80cc\u666f\u4e0b\uff0c\u7814\u7a76\u4e86\u62db\u751f\u900f\u660e\u5ea6\u7684\u5f71\u54cd\uff0c\u4f7f\u7528\u4e86\u5fb7\u514b\u8428\u65af\u5dde\u7684\u8c03\u67e5\u548c\u884c\u653f\u6570\u636e\uff0c\u5e76\u7ed3\u5408\u4e00\u4e2a\u5305\u542b\u5927\u5b66\u7533\u8bf7\u3001\u5f55\u53d6\u3001\u5165\u5b66\u3001\u6210\u7ee9\u548c\u6301\u7eed\u7387\u7684\u62db\u751f\u6a21\u578b\u3002\u6211\u4f30\u8ba1\uff0c\u8be5\u8ba1\u5212\u5bf9\u524d\u5341\u767e\u5206\u6bd4\u5b66\u751f\u8fdb\u5165\u65d7\u8230\u5927\u5b66\u6982\u7387\u76849.1\u5206\u5f71\u54cd\u4e2d\uff0c\u6709\u4e09\u5206\u4e4b\u4e8c\u5f52\u56e0\u4e8e\u4fe1\u606f\u56e0\u7d20\u800c\u975e\u673a\u68b0\u6027\u6548\u5e94\u3002\u88ab\u8bf1\u5bfc\u5165\u5b66\u7684\u5b66\u751f\u66f4\u591a\u6765\u81ea\u4f4e\u6536\u5165\u9ad8\u4e2d\uff0c\u4e14\u5728\u5b66\u672f\u8868\u73b0\u4e0a\u4f18\u4e8e\u88ab\u5176\u66ff\u4ee3\u7684\u5b66\u751f\u3002\u5982\u679c\u8865\u5145\u8d22\u52a1\u63f4\u52a9\u4fe1\u606f\uff0c\u8fd9\u4e9b\u6548\u5e94\u5c06\u66f4\u5927\uff0c\u4e14\u4e3b\u8981\u7531\u900f\u660e\u5ea6\u9a71\u52a8\uff0c\u800c\u975e\u81ea\u52a8\u5f55\u53d6\u4e0e\u81ea\u4e3b\u9009\u62e9\u65f6\u70b9\u5f55\u53d6\u89c4\u5219\u4e4b\u95f4\u7684\u4e0d\u4e00\u81f4\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta19106", "journal": "ECTA", "title": "Who Benefits From Surge Pricing?", "authors": ["Juan Camilo Castillo"], "author_details": [{"name": "Juan Camilo Castillo", "affiliations": ["Economics Department, University of Pennsylvania"]}], "abstract": "New technologies have recently led to a boom in real\u2010time pricing. I study the most salient example, surge pricing in ride hailing. Using data from Uber, I develop an empirical model of spatial equilibrium to measure the welfare effects of surge pricing. The model is composed of demand, supply, and a matching technology. It allows for temporal and spatial heterogeneity as well as randomness in supply and demand. I find that, relative to a uniform pricing counterfactual in which Uber sets the overall price level, surge pricing increases total welfare by 2.15% of gross revenue. Welfare effects differ substantially across sides of the market: rider surplus increases by 3.57% of gross revenue, whereas driver surplus and the platform's current profits decrease by 0.98% and 0.50% of gross revenue, respectively. Riders at all income levels benefit. Among drivers, those who work long hours are hurt the most, especially women.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta19106", "title_zh": "\u4ef7\u683c surge \u673a\u5236\u7684\u53d7\u76ca\u8005\u662f\u8c01\uff1f", "abstract_zh": "\u65b0\u6280\u672f\u8fd1\u5e74\u6765\u5f15\u53d1\u4e86\u5b9e\u65f6\u5b9a\u4ef7\u7684\u70ed\u6f6e\u3002\u672c\u6587\u7814\u7a76\u6700\u5177\u4ee3\u8868\u6027\u7684\u6848\u4f8b\u2014\u2014\u7f51\u7ea6\u8f66\u4e2d\u7684\u4ef7\u683c surge \u673a\u5236\u3002\u5229\u7528 Uber \u7684\u6570\u636e\uff0c\u6211\u6784\u5efa\u4e86\u4e00\u4e2a\u7a7a\u95f4\u5747\u8861\u7684\u5b9e\u8bc1\u6a21\u578b\uff0c\u4ee5\u8861\u91cf\u4ef7\u683c surge \u673a\u5236\u7684\u798f\u5229\u6548\u5e94\u3002\u8be5\u6a21\u578b\u5305\u542b\u9700\u6c42\u3001\u4f9b\u7ed9\u4ee5\u53ca\u5339\u914d\u6280\u672f\uff0c\u80fd\u591f\u5904\u7406\u65f6\u95f4\u4e0e\u7a7a\u95f4\u4e0a\u7684\u5f02\u8d28\u6027\uff0c\u4ee5\u53ca\u9700\u6c42\u548c\u4f9b\u7ed9\u4e2d\u7684\u968f\u673a\u6027\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u4e0e Uber \u7edf\u4e00\u8bbe\u5b9a\u6574\u4f53\u4ef7\u683c\u6c34\u5e73\u7684\u57fa\u51c6\u60c5\u666f\u76f8\u6bd4\uff0c\u4ef7\u683c surge \u673a\u5236\u4f7f\u603b\u798f\u5229\u63d0\u9ad8\u4e86\u603b\u6536\u5165\u7684 2.15%\u3002\u4e0d\u540c\u5e02\u573a\u53c2\u4e0e\u65b9\u7684\u798f\u5229\u6548\u5e94\u5dee\u5f02\u663e\u8457\uff1a\u4e58\u5ba2\u5269\u4f59\u589e\u52a0\u4e86\u603b\u6536\u5165\u7684 3.57%\uff0c\u800c\u53f8\u673a\u5269\u4f59\u548c\u5e73\u53f0\u5f53\u524d\u5229\u6da6\u5206\u522b\u4e0b\u964d\u4e86\u603b\u6536\u5165\u7684 0.98% \u548c 0.50%\u3002\u6240\u6709\u6536\u5165\u6c34\u5e73\u7684\u4e58\u5ba2\u5747\u53d7\u76ca\u3002\u5728\u53f8\u673a\u7fa4\u4f53\u4e2d\uff0c\u5de5\u4f5c\u65f6\u95f4\u8f83\u957f\u7684\u53f8\u673a\u53d7\u5230\u6700\u5927\u4f24\u5bb3\uff0c\u5c24\u5176\u662f\u5973\u6027\u53f8\u673a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta21466", "journal": "ECTA", "title": "Minimum Wages, Efficiency, and Welfare", "authors": ["David Berger", "Kyle Herkenhoff", "Simon Mongey"], "author_details": [{"name": "David Berger", "affiliations": ["Economics Department, Duke University"]}, {"name": "Kyle Herkenhoff", "affiliations": ["Department of Economics, University of Minnesota"]}, {"name": "Simon Mongey", "affiliations": ["Research Division, Federal Reserve Bank of Minneapolis"]}], "abstract": "Many argue that minimum wages can prevent efficiency losses from monopsony power. We assess this argument in a general equilibrium model of oligopsonistic labor markets with heterogeneous workers and firms. We decompose welfare gains into an efficiency component that captures reductions in monopsony power and a redistributive component that captures the way minimum wages shift resources across people. The minimum wage that maximizes the efficiency component of welfare lies below $8.00 and yields gains worth less than 0.2% of lifetime consumption. When we add back in Utilitarian redistributive motives, the optimal minimum wage is $11 and redistribution accounts for 102.5% of the resulting welfare gains, implying offsetting efficiency losses of \u22122.5%. The reason a minimum wage struggles to deliver efficiency gains is that with realistic firm productivity dispersion, a minimum wage that eliminates monopsony power at one firm causes severe rationing at another. These results hold under an EITC and progressive labor income taxes calibrated to the U.S. economy.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21466", "title_zh": "\u6700\u4f4e\u5de5\u8d44\u3001\u6548\u7387\u4e0e\u798f\u5229", "abstract_zh": "\u8bb8\u591a\u4eba\u8ba4\u4e3a\u6700\u4f4e\u5de5\u8d44\u53ef\u4ee5\u9632\u6b62\u5784\u65ad\u8d2d\u4e70\u529b\u5bfc\u81f4\u7684\u6548\u7387\u635f\u5931\u3002\u6211\u4eec\u5728\u4e00\u4e2a\u5305\u542b\u5f02\u8d28\u6027\u5de5\u4eba\u548c\u4f01\u4e1a\u7684\u5be1\u5934\u4e70\u65b9\u52b3\u52a8\u529b\u5e02\u573a\u7684\u4e00\u822c\u5747\u8861\u6a21\u578b\u4e2d\u8bc4\u4f30\u4e86\u8fd9\u4e00\u89c2\u70b9\u3002\u6211\u4eec\u5c06\u798f\u5229\u589e\u76ca\u5206\u89e3\u4e3a\u4e00\u4e2a\u53cd\u6620\u5784\u65ad\u8d2d\u4e70\u529b\u51cf\u5c11\u7684\u6548\u7387\u90e8\u5206\uff0c\u4ee5\u53ca\u4e00\u4e2a\u53cd\u6620\u6700\u4f4e\u5de5\u8d44\u5982\u4f55\u5728\u4e0d\u540c\u4eba\u7fa4\u4e4b\u95f4\u91cd\u65b0\u914d\u7f6e\u8d44\u6e90\u7684\u518d\u5206\u914d\u90e8\u5206\u3002\u4f7f\u6548\u7387\u90e8\u5206\u798f\u5229\u6700\u5927\u5316\u7684\u76ee\u6807\u6700\u4f4e\u5de5\u8d44\u4f4e\u4e8e8.00\u7f8e\u5143\uff0c\u5176\u5e26\u6765\u7684\u6536\u76ca\u4e0d\u8db3\u7ec8\u8eab\u6d88\u8d39\u76840.2%\u3002\u5f53\u6211\u4eec\u52a0\u5165\u529f\u5229\u4e3b\u4e49\u7684\u518d\u5206\u914d\u52a8\u673a\u540e\uff0c\u6700\u4f18\u6700\u4f4e\u5de5\u8d44\u4e3a11\u7f8e\u5143\uff0c\u518d\u5206\u914d\u90e8\u5206\u5360\u603b\u798f\u5229\u589e\u76ca\u7684102.5%\uff0c\u610f\u5473\u7740\u6548\u7387\u635f\u5931\u4e3a-2.5%\u3002\u6700\u4f4e\u5de5\u8d44\u96be\u4ee5\u5b9e\u73b0\u6548\u7387\u63d0\u5347\u7684\u539f\u56e0\u5728\u4e8e\uff0c\u5728\u73b0\u5b9e\u7684\u516c\u53f8\u751f\u4ea7\u7387\u5206\u6563\u60c5\u51b5\u4e0b\uff0c\u4e00\u4e2a\u4f01\u4e1a\u6d88\u9664\u5784\u65ad\u8d2d\u4e70\u529b\u4f1a\u5bfc\u81f4\u53e6\u4e00\u5bb6\u4f01\u4e1a\u51fa\u73b0\u4e25\u91cd\u7684\u8d44\u6e90\u914d\u7ed9\u95ee\u9898\u3002\u8fd9\u4e9b\u7ed3\u679c\u5728\u57fa\u4e8e\u7f8e\u56fd\u7ecf\u6d4e\u6821\u51c6\u7684EITC\uff08\u513f\u7ae5\u7a0e\u6536\u62b5\u514d\uff09\u548c\u7d2f\u8fdb\u52b3\u52a8\u6536\u5165\u7a0e\u6761\u4ef6\u4e0b\u4f9d\u7136\u6210\u7acb\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta21567", "journal": "ECTA", "title": "Bayesian Impact Evaluation With Informative Priors: An Application to a Colombian Management and Export Improvement Program", "authors": ["Leonardo Iacovone", "David McKenzie", "Rachael Meager"], "author_details": [{"name": "Leonardo Iacovone", "affiliations": ["The World Bank"]}, {"name": "David McKenzie", "affiliations": ["Development Research Group, The World Bank"]}, {"name": "Rachael Meager", "affiliations": ["Department of Economics, University of New South Wales"]}], "abstract": "Policymakers often test expensive new programs on relatively small samples. Formally incorporating informative Bayesian priors into impact evaluation offers the promise to learn more from these experiments. We evaluate a Colombian program for 200 firms which aimed to increase exporting. Priors were elicited from academics, policymakers, and firms. Contrary to these priors, frequentist estimation cannot reject null effects in 2019, and finds some negative impacts in 2020. For binary outcomes like whether firms export, frequentist estimates are relatively precise, and Bayesian posterior intervals update to overlap almost completely with standard confidence intervals. For outcomes like increasing export variety, where the priors align with the data, the value of these priors is seen in posterior intervals that are considerably narrower than the confidence intervals. Finally, for noisy outcomes like export value, posterior intervals show almost no updating from priors, highlighting how uninformative the data are about such outcomes. Future policy experiments could use these posteriors as priors in a Bayesian or empirical Bayesian analysis.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta21567", "title_zh": "\u5177\u6709\u4fe1\u606f\u5148\u9a8c\u7684\u8d1d\u53f6\u65af\u5f71\u54cd\u8bc4\u4f30\uff1a\u4e00\u9879\u54e5\u4f26\u6bd4\u4e9a\u7ba1\u7406\u4e0e\u51fa\u53e3\u6539\u5584\u8ba1\u5212\u7684\u5e94\u7528", "abstract_zh": "\u653f\u7b56\u5236\u5b9a\u8005\u901a\u5e38\u5728\u76f8\u5bf9\u8f83\u5c0f\u7684\u6837\u672c\u4e0a\u6d4b\u8bd5\u6602\u8d35\u7684\u65b0\u9879\u76ee\u3002\u6b63\u5f0f\u5730\u5c06\u4fe1\u606f\u4e30\u5bcc\u7684\u8d1d\u53f6\u65af\u5148\u9a8c\u7eb3\u5165\u5f71\u54cd\u8bc4\u4f30\uff0c\u6709\u671b\u4ece\u8fd9\u4e9b\u5b9e\u9a8c\u4e2d\u83b7\u5f97\u66f4\u591a\u4fe1\u606f\u3002\u6211\u4eec\u8bc4\u4f30\u4e86\u54e5\u4f26\u6bd4\u4e9a\u4e00\u9879\u9488\u5bf9200\u5bb6\u4f01\u4e1a\u7684\u8ba1\u5212\uff0c\u65e8\u5728\u63d0\u9ad8\u51fa\u53e3\u6d3b\u52a8\u3002\u5148\u9a8c\u5206\u5e03\u7531\u5b66\u8005\u3001\u653f\u7b56\u5236\u5b9a\u8005\u548c\u4f01\u4e1a\u81ea\u8eab\u83b7\u53d6\u3002\u4e0e\u8fd9\u4e9b\u5148\u9a8c\u5206\u5e03\u76f8\u53cd\uff0c\u57fa\u4e8e\u9891\u7387\u5b66\u7684\u4f30\u8ba1\u57282019\u5e74\u65e0\u6cd5\u62d2\u7edd\u96f6\u6548\u5e94\uff0c\u57282020\u5e74\u53d1\u73b0\u4e86\u4e00\u4e9b\u8d1f\u9762\u5f71\u54cd\u3002\u5bf9\u4e8e\u4e8c\u5143\u7ed3\u679c\uff08\u5982\u4f01\u4e1a\u662f\u5426\u51fa\u53e3\uff09\uff0c\u9891\u7387\u5b66\u4f30\u8ba1\u76f8\u5bf9\u7cbe\u786e\uff0c\u8d1d\u53f6\u65af\u540e\u9a8c\u533a\u95f4\u51e0\u4e4e\u5b8c\u5168\u4e0e\u6807\u51c6\u7f6e\u4fe1\u533a\u95f4\u91cd\u53e0\u3002\u5bf9\u4e8e\u4e0e\u5148\u9a8c\u5206\u5e03\u4e00\u81f4\u7684\u7ed3\u679c\uff08\u5982\u51fa\u53e3\u54c1\u79cd\u7684\u589e\u52a0\uff09\uff0c\u5148\u9a8c\u4fe1\u606f\u7684\u4ef7\u503c\u4f53\u73b0\u5728\u540e\u9a8c\u533a\u95f4\u7684\u5bbd\u5ea6\u660e\u663e\u5c0f\u4e8e\u7f6e\u4fe1\u533a\u95f4\u3002\u800c\u5bf9\u4e8e\u566a\u58f0\u8f83\u5927\u7684\u7ed3\u679c\uff08\u5982\u51fa\u53e3\u91d1\u989d\uff09\uff0c\u540e\u9a8c\u533a\u95f4\u51e0\u4e4e\u672a\u4ece\u5148\u9a8c\u4e2d\u66f4\u65b0\uff0c\u51f8\u663e\u4e86\u6570\u636e\u5bf9\u8fd9\u7c7b\u7ed3\u679c\u7684\u65e0\u4fe1\u606f\u6027\u3002\u672a\u6765\u653f\u7b56\u5b9e\u9a8c\u53ef\u4ee5\u5c06\u8fd9\u4e9b\u540e\u9a8c\u4f5c\u4e3a\u8d1d\u53f6\u65af\u6216\u7ecf\u9a8c\u8d1d\u53f6\u65af\u5206\u6790\u4e2d\u7684\u5148\u9a8c\u4f7f\u7528\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta19699", "journal": "ECTA", "title": "Rural Pensions, Labor Reallocation, and Aggregate Income: An Empirical and Quantitative Analysis of China", "authors": ["Qingen Gai", "Naijia Guo", "Bingjing Li", "Qinghua Shi", "Xiaodong Zhu"], "author_details": [{"name": "Qingen Gai", "affiliations": ["Antai College of Economics and Management, Shanghai Jiao Tong University"]}, {"name": "Naijia Guo", "affiliations": ["Faculty of Business and Economics, University of Hong Kong"]}, {"name": "Bingjing Li", "affiliations": ["Faculty of Business and Economics, University of Hong Kong"]}, {"name": "Qinghua Shi", "affiliations": ["Antai College of Economics and Management, Shanghai Jiao Tong University"]}, {"name": "Xiaodong Zhu", "affiliations": ["Faculty of Business and Economics, University of Hong Kong"]}], "abstract": "We exploit the implementation of a rural pension policy in China to estimate the average rural\u2010to\u2010urban migration cost for workers affected by the policy and the average underlying sectoral productivity difference. Our estimates, based on a large panel data set, reveal significant migration costs and substantial sectoral productivity differences, with sorting playing a minor role in accounting for sectoral labor income gaps. We construct and structurally estimate a general equilibrium household model with endogenous labor supply and migration. The results of this model align with the reduced\u2010form findings and illustrate how the rural pension policy influences migration, GDP, and welfare through improving within\u2010household labor allocation. Counterfactual analyses based on the model show that the positive effects of the policy remain even if migration costs were significantly lower, and that scaling up the rural pension policy would lead to even larger improvements in labor allocation, GDP, and welfare.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta19699", "title_zh": "\u519c\u6751\u517b\u8001\u91d1\u3001\u52b3\u52a8\u529b\u518d\u914d\u7f6e\u4e0e\u603b\u6536\u5165\uff1a\u5bf9\u4e2d\u56fd\u7684\u4e00\u9879\u5b9e\u8bc1\u4e0e\u5b9a\u91cf\u5206\u6790", "abstract_zh": "\u6211\u4eec\u5229\u7528\u4e2d\u56fd\u519c\u6751\u517b\u8001\u91d1\u653f\u7b56\u7684\u5b9e\u65bd\uff0c\u6765\u4f30\u8ba1\u53d7\u8be5\u653f\u7b56\u5f71\u54cd\u7684\u5de5\u4eba\u8fc1\u5f80\u57ce\u5e02\u7684\u5e73\u5747\u6210\u672c\u4ee5\u53ca\u57fa\u7840\u4ea7\u4e1a\u95f4\u7684\u751f\u4ea7\u7387\u5dee\u5f02\u3002\u57fa\u4e8e\u5927\u89c4\u6a21\u9762\u677f\u6570\u636e\uff0c\u6211\u4eec\u7684\u4f30\u8ba1\u7ed3\u679c\u663e\u793a\u5b58\u5728\u663e\u8457\u7684\u8fc1\u79fb\u6210\u672c\u548c\u8f83\u5927\u7684\u4ea7\u4e1a\u95f4\u751f\u4ea7\u7387\u5dee\u5f02\uff0c\u800c\u52b3\u52a8\u529b\u7684\u91cd\u65b0\u914d\u7f6e\u5728\u89e3\u91ca\u4ea7\u4e1a\u95f4\u6536\u5165\u5dee\u8ddd\u65b9\u9762\u4f5c\u7528\u8f83\u5c0f\u3002\u6211\u4eec\u6784\u5efa\u5e76\u7ed3\u6784\u5316\u4f30\u8ba1\u4e86\u4e00\u4e2a\u5305\u542b\u5185\u751f\u52b3\u52a8\u4f9b\u7ed9\u548c\u8fc1\u79fb\u7684\u4e00\u822c\u5747\u8861\u5bb6\u5ead\u6a21\u578b\u3002\u8be5\u6a21\u578b\u7684\u7ed3\u679c\u4e0e\u7b80\u5316\u5f62\u5f0f\u7684\u53d1\u73b0\u4e00\u81f4\uff0c\u8bf4\u660e\u519c\u6751\u517b\u8001\u91d1\u653f\u7b56\u901a\u8fc7\u6539\u5584\u5bb6\u5ead\u5185\u90e8\u7684\u52b3\u52a8\u5206\u914d\uff0c\u5f71\u54cd\u4e86\u8fc1\u79fb\u3001GDP\u548c\u798f\u5229\u3002\u57fa\u4e8e\u8be5\u6a21\u578b\u7684\u53cd\u4e8b\u5b9e\u5206\u6790\u8868\u660e\uff0c\u5373\u4f7f\u8fc1\u79fb\u6210\u672c\u663e\u8457\u964d\u4f4e\uff0c\u653f\u7b56\u7684\u79ef\u6781\u6548\u5e94\u4f9d\u7136\u5b58\u5728\uff0c\u4e14\u6269\u5927\u519c\u6751\u517b\u8001\u91d1\u653f\u7b56\u7684\u89c4\u6a21\u5c06\u5e26\u6765\u66f4\u663e\u8457\u7684\u52b3\u52a8\u5206\u914d\u3001GDP\u548c\u798f\u5229\u6539\u5584\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22260", "journal": "ECTA", "title": "Structural Estimation of Higher Order Risk Preferences", "authors": ["Morten I. Lau", "Hong Il Yoo"], "author_details": [{"name": "Morten I. Lau", "affiliations": ["Department of Economics, Copenhagen Business School", "Department of Economics, Durham University"]}, {"name": "Hong Il Yoo", "affiliations": ["Loughborough Business School, Loughborough University"]}], "abstract": "Structural measures of higher order risk attitudes have well\u2010developed foundations in Expected Utility Theory (EUT), but little is known about their empirical magnitudes. We introduce a novel experimental design and a companion econometric model that allows us to structurally estimate indices of risk aversion, prudence, and temperance under EUT without imposing restrictions on their interdependence. We find that indices of absolute risk aversion, prudence, and temperance exhibit distinct patterns of variation over income, and that predicted risk premia under EUT and Rank\u2010Dependent Utility Theory gradually converge as the order of risk increases. These findings are obscured by regular parametric utility functions, which inherently bias results toward prudence and temperance when subjects are risk averse. The results remain robust in subsamples of moderate size, which suggests that our approach can be adopted in broader studies that link higher order risk attitudes to other domains of latent individual preferences and economic behavior.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22260", "title_zh": "\u9ad8\u9636\u98ce\u9669\u504f\u597d\u7684\u7ed3\u6784\u4f30\u8ba1", "abstract_zh": "\u5728\u671f\u671b\u6548\u7528\u7406\u8bba\uff08EUT\uff09\u4e2d\uff0c\u9ad8\u9636\u98ce\u9669\u6001\u5ea6\u7684\u7ed3\u6784\u5ea6\u91cf\u5df2\u6709\u6210\u719f\u57fa\u7840\uff0c\u4f46\u5176\u5b9e\u9645\u6570\u503c\u4ecd\u77e5\u4e4b\u751a\u5c11\u3002\u6211\u4eec\u5f15\u5165\u4e86\u4e00\u79cd\u65b0\u9896\u7684\u5b9e\u9a8c\u8bbe\u8ba1\u548c\u914d\u5957\u7684\u8ba1\u91cf\u7ecf\u6d4e\u6a21\u578b\uff0c\u80fd\u591f\u5728\u4e0d\u65bd\u52a0\u5176\u76f8\u4e92\u4f9d\u8d56\u6027\u9650\u5236\u7684\u60c5\u51b5\u4e0b\uff0c\u5bf9EUT\u6846\u67b6\u4e0b\u7684\u98ce\u9669\u538c\u6076\u3001\u8c28\u614e\u6027\u548c\u514b\u5236\u6027\u6307\u6570\u8fdb\u884c\u7ed3\u6784\u4f30\u8ba1\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u7edd\u5bf9\u98ce\u9669\u538c\u6076\u3001\u8c28\u614e\u6027\u548c\u514b\u5236\u6027\u6307\u6570\u5728\u6536\u5165\u53d8\u5316\u4e2d\u8868\u73b0\u51fa\u4e0d\u540c\u7684\u53d8\u5316\u6a21\u5f0f\uff0c\u4e14\u5f53\u98ce\u9669\u9636\u6570\u589e\u52a0\u65f6\uff0cEUT\u4e0e\u57fa\u4e8e\u6392\u540d\u7684\u4f9d\u8d56\u6548\u7528\u7406\u8bba\u9884\u6d4b\u7684\u98ce\u9669\u6ea2\u4ef7\u9010\u6e10\u8d8b\u540c\u3002\u8fd9\u4e9b\u53d1\u73b0\u88ab\u5e38\u89c4\u53c2\u6570\u5316\u6548\u7528\u51fd\u6570\u6240\u63a9\u76d6\uff0c\u540e\u8005\u5728\u4e2a\u4f53\u98ce\u9669\u538c\u6076\u7684\u60c5\u51b5\u4e0b\u4f1a\u7cfb\u7edf\u6027\u5730\u504f\u5411\u4e8e\u8c28\u614e\u6027\u548c\u514b\u5236\u6027\u3002\u7ed3\u679c\u5728\u4e2d\u7b49\u89c4\u6a21\u7684\u5b50\u6837\u672c\u4e2d\u4f9d\u7136\u7a33\u5065\uff0c\u8fd9\u8868\u660e\u6211\u4eec\u7684\u65b9\u6cd5\u53ef\u88ab\u5e94\u7528\u4e8e\u66f4\u5e7f\u6cdb\u7684\u5b9e\u8bc1\u7814\u7a76\uff0c\u4ee5\u5c06\u9ad8\u9636\u98ce\u9669\u6001\u5ea6\u4e0e\u5176\u4ed6\u6f5c\u5728\u4e2a\u4f53\u504f\u597d\u548c\u7ecf\u6d4e\u884c\u4e3a\u9886\u57df\u8054\u7cfb\u8d77\u6765\u3002", "translation_source": "journal-qwen4b", "topics": ["\u8d44\u4ea7\u5b9a\u4ef7"]}, {"doi": "10.3982/ecta19153", "journal": "ECTA", "title": "Gaussian Transforms Modeling and the Estimation of Distributional Regression Functions", "authors": ["Richard H. Spady", "Sami Stouli"], "author_details": [{"name": "Richard H. Spady", "affiliations": ["Department of Economics, Johns Hopkins University", "Nuffield College, University of Oxford"]}, {"name": "Sami Stouli", "affiliations": ["School of Economics, University of Bristol", "Department of Economics, University of Melbourne"]}], "abstract": "We propose flexible Gaussian representations for conditional cumulative distribution functions and give a concave likelihood criterion for their estimation. Optimal representations satisfy the monotonicity property of conditional cumulative distribution functions, including in finite samples and under general misspecification. We use these representations to provide a unified framework for the flexible maximum likelihood estimation of conditional density, cumulative distribution, and quantile functions at parametric rate. Our formulation yields substantial simplifications and finite sample improvements over related methods. An empirical application to the gender wage gap in the United States illustrates our framework.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta19153", "title_zh": "\u9ad8\u65af\u53d8\u6362\u5efa\u6a21\u4e0e\u5206\u5e03\u56de\u5f52\u51fd\u6570\u7684\u4f30\u8ba1", "abstract_zh": "\u6211\u4eec\u4e3a\u6761\u4ef6\u7d2f\u79ef\u5206\u5e03\u51fd\u6570\u63d0\u51fa\u4e86\u7075\u6d3b\u7684\u9ad8\u65af\u8868\u793a\uff0c\u5e76\u4e3a\u5176\u4f30\u8ba1\u63d0\u4f9b\u4e86\u51f9\u6027\u4f3c\u7136\u51c6\u5219\u3002\u6700\u4f18\u8868\u793a\u6ee1\u8db3\u6761\u4ef6\u7d2f\u79ef\u5206\u5e03\u51fd\u6570\u7684\u5355\u8c03\u6027\u6027\u8d28\uff0c\u5305\u62ec\u5728\u6709\u9650\u6837\u672c\u60c5\u51b5\u4e0b\u4ee5\u53ca\u5728\u4e00\u822c\u6a21\u578b\u8bbe\u5b9a\u9519\u8bef\u4e0b\u7684\u60c5\u51b5\u3002\u6211\u4eec\u5229\u7528\u8fd9\u4e9b\u8868\u793a\uff0c\u4e3a\u6761\u4ef6\u5bc6\u5ea6\u3001\u7d2f\u79ef\u5206\u5e03\u548c\u5206\u4f4d\u6570\u51fd\u6570\u7684\u7075\u6d3b\u6700\u5927\u4f3c\u7136\u4f30\u8ba1\u63d0\u4f9b\u4e86\u4e00\u4e2a\u7edf\u4e00\u6846\u67b6\uff0c\u4e14\u5728\u53c2\u6570\u901f\u7387\u4e0b\u5b9e\u73b0\u4e86\u663e\u8457\u7b80\u5316\u548c\u6709\u9650\u6837\u672c\u6027\u80fd\u63d0\u5347\u3002\u8be5\u6846\u67b6\u5728\u7f8e\u56fd\u6027\u522b\u5de5\u8d44\u5dee\u8ddd\u7684\u5b9e\u8bc1\u5e94\u7528\u4e2d\u5f97\u5230\u4e86\u5c55\u793a\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22072", "journal": "ECTA", "title": "Competitive Capture of Public Opinion", "authors": ["Ricardo Alonso", "Gerard Padr\u00f3 i Miquel"], "author_details": [{"name": "Ricardo Alonso", "affiliations": ["Department of Management, London School of Economics"]}, {"name": "Gerard Padr\u00f3 i Miquel", "affiliations": ["Departments of Economics and Political Science, Yale University"]}], "abstract": "Two opposed interested parties (IPs) compete to influence citizens with heterogeneous priors which receive news items produced by a variety of sources. The IPs fight to capture the coverage conveyed in these items. We characterize the equilibrium level of capture of item as well as the equilibrium level of information transmission. Capture increases the prevalence of the ex ante most informative messages and can explain the empirical distribution of slant at the news\u2010item level. Opposite capturing efforts do not cancel each other and instead undermine social learning as rational citizens discount informative messages. Citizen skepticism makes efforts to capture the news strategic substitutes. Because of strategic substitution, competition for influence is compatible with horizontal differentiation between successful media. In equilibrium, rational citizens choose to consume messages from aligned sources despite knowledge of the bias in a manner consistent with recent empirical evidence.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22072", "title_zh": "\u516c\u5171\u610f\u89c1\u7684\u4e89\u593a", "abstract_zh": "\u4e24\u4e2a\u5bf9\u7acb\u7684\u5229\u76ca\u65b9\uff08IPs\uff09\u4e89\u593a\u5f71\u54cd\u5177\u6709\u5f02\u8d28\u6027\u5148\u9a8c\u4fe1\u5ff5\u7684\u516c\u6c11\uff0c\u8fd9\u4e9b\u516c\u6c11\u63a5\u6536\u6765\u81ea\u591a\u79cd\u6765\u6e90\u7684\u65b0\u95fb\u5185\u5bb9\u3002\u5229\u76ca\u65b9\u4eec\u52aa\u529b\u4e89\u593a\u8fd9\u4e9b\u65b0\u95fb\u5185\u5bb9\u6240\u4f20\u8fbe\u7684\u8986\u76d6\u8303\u56f4\u3002\u6211\u4eec\u523b\u753b\u4e86\u65b0\u95fb\u5185\u5bb9\u88ab\u4e89\u593a\u7684\u5747\u8861\u6c34\u5e73\u4ee5\u53ca\u4fe1\u606f\u4f20\u9012\u7684\u5747\u8861\u6c34\u5e73\u3002\u4e89\u593a\u884c\u4e3a\u4f1a\u589e\u52a0\u4e8b\u524d\u6700\u5177\u4fe1\u606f\u91cf\u7684\u65b0\u95fb\u5185\u5bb9\u7684\u4f20\u64ad\uff0c\u53ef\u4ee5\u89e3\u91ca\u65b0\u95fb\u5185\u5bb9\u5728\u65b0\u95fb\u9879\u76ee\u5c42\u9762\u7684\u504f\u89c1\u5206\u5e03\u3002\u76f8\u53cd\u7684\u4e89\u593a\u884c\u4e3a\u4e0d\u4f1a\u76f8\u4e92\u62b5\u6d88\uff0c\u53cd\u800c\u4f1a\u524a\u5f31\u793e\u4f1a\u5b66\u4e60\uff0c\u56e0\u4e3a\u7406\u6027\u516c\u6c11\u4f1a\u964d\u4f4e\u5bf9\u4fe1\u606f\u6027\u5185\u5bb9\u7684\u91cd\u89c6\u3002\u516c\u6c11\u7684\u6000\u7591\u6001\u5ea6\u4f7f\u5f97\u4e89\u593a\u65b0\u95fb\u5185\u5bb9\u7684\u884c\u4e3a\u6210\u4e3a\u6218\u7565\u66ff\u4ee3\u5173\u7cfb\u3002\u7531\u4e8e\u8fd9\u79cd\u6218\u7565\u66ff\u4ee3\uff0c\u5bf9\u5f71\u54cd\u529b\u7684\u7ade\u4e89\u4e0e\u6210\u529f\u5a92\u4f53\u4e4b\u95f4\u7684\u6c34\u5e73\u5dee\u5f02\u5316\u662f\u76f8\u5bb9\u7684\u3002\u5728\u5747\u8861\u72b6\u6001\u4e0b\uff0c\u7406\u6027\u516c\u6c11\u5373\u4f7f\u77e5\u9053\u65b0\u95fb\u5185\u5bb9\u7684\u504f\u89c1\uff0c\u4e5f\u4f1a\u9009\u62e9\u6d88\u8d39\u6765\u81ea\u4e00\u81f4\u6765\u6e90\u7684\u4fe1\u606f\uff0c\u8fd9\u4e00\u884c\u4e3a\u4e0e\u8fd1\u671f\u7684\u5b9e\u8bc1\u8bc1\u636e\u76f8\u7b26\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta20496", "journal": "ECTA", "title": "Estimating Candidate Valence", "authors": ["Kei Kawai", "Takeaki Sunada"], "author_details": [{"name": "Kei Kawai", "affiliations": ["Department of Economics, U.C. Berkeley and University of Tokyo"]}, {"name": "Takeaki Sunada", "affiliations": ["Simon Business School, University of Rochester"]}], "abstract": "We estimate valence measures of candidates running in U.S. House elections from data on vote shares. Our identification and estimation strategy builds on ideas developed for estimating production functions, allowing us to control for possible endogeneity of campaign spending and sample selection of candidates due to endogenous entry. We find that incumbents have substantially higher valence measures than challengers running against them, resulting in about 3.5 percentage\u2010point differences in the vote share, on average. Eliminating differences in the valence of challengers and incumbents results in an increase in the winning probability of a challenger from 6.5% to 12.1%. Our measure of candidate valence can be used to study various substantive questions of political economy. We illustrate its usefulness by studying the source of incumbency advantage in U.S. House elections.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta20496", "title_zh": "\u4f30\u8ba1\u5019\u9009\u4eba\u4ef7\u503c\u5ea6", "abstract_zh": "\u6211\u4eec\u57fa\u4e8e\u9009\u7968\u4efd\u989d\u6570\u636e\uff0c\u4f30\u8ba1\u4e86\u7f8e\u56fd\u4f17\u8bae\u9662\u9009\u4e3e\u4e2d\u5019\u9009\u4eba\u7684\u4ef7\u503c\u5ea6\u6307\u6807\u3002\u6211\u4eec\u7684\u8bc6\u522b\u4e0e\u4f30\u8ba1\u7b56\u7565\u501f\u9274\u4e86\u751f\u4ea7\u51fd\u6570\u4f30\u8ba1\u4e2d\u7684\u65b9\u6cd5\uff0c\u80fd\u591f\u63a7\u5236\u7ade\u9009\u652f\u51fa\u7684\u5185\u751f\u6027\u4ee5\u53ca\u7531\u4e8e\u5185\u751f\u8fdb\u5165\u5bfc\u81f4\u7684\u5019\u9009\u4eba\u6837\u672c\u9009\u62e9\u504f\u5dee\u3002\u6211\u4eec\u53d1\u73b0\uff0c\u73b0\u4efb\u8bae\u5458\u7684\u4ef7\u503c\u5ea6\u663e\u8457\u9ad8\u4e8e\u4e0e\u5176\u7ade\u4e89\u7684\u6311\u6218\u8005\uff0c\u5e73\u5747\u9009\u7968\u4efd\u989d\u4e0a\u5b58\u5728\u7ea63.5\u4e2a\u767e\u5206\u70b9\u7684\u5dee\u8ddd\u3002\u6d88\u9664\u73b0\u4efb\u8bae\u5458\u4e0e\u6311\u6218\u8005\u4e4b\u95f4\u4ef7\u503c\u5ea6\u5dee\u5f02\u540e\uff0c\u6311\u6218\u8005\u83b7\u80dc\u7684\u6982\u7387\u4ece6.5%\u4e0a\u5347\u81f312.1%\u3002\u8be5\u5019\u9009\u4eba\u7684\u4ef7\u503c\u5ea6\u6307\u6807\u53ef\u7528\u4e8e\u7814\u7a76\u653f\u6cbb\u7ecf\u6d4e\u5b66\u4e2d\u7684\u5404\u79cd\u5b9e\u8d28\u6027\u95ee\u9898\u3002\u6211\u4eec\u901a\u8fc7\u5206\u6790\u7f8e\u56fd\u4f17\u8bae\u9662\u9009\u4e3e\u4e2d\u4efb\u671f\u4f18\u52bf\u7684\u6765\u6e90\uff0c\u5c55\u793a\u4e86\u5176\u5e94\u7528\u4ef7\u503c\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}, {"doi": "10.3982/ecta22139", "journal": "ECTA", "title": "Dynamic Concern for Misspecification", "authors": ["Giacomo Lanzani"], "author_details": [{"name": "Giacomo Lanzani", "affiliations": ["Department of Economics, UC Berkeley"]}], "abstract": "I consider an agent who posits a set of probabilistic models for the payoff\u2010relevant outcomes. The agent has a prior over this set but fears the actual model is omitted and hedges against this possibility. The concern for misspecification is endogenous: If a model explains the previous observations well, the concern attenuates. I show that different static preferences under uncertainty (subjective expected utility, maxmin, robust control) arise in the long run, depending on how quickly the agent becomes unsatisfied with unexplained evidence. The misspecification concern's endogeneity naturally induces behavior cycles, and I characterize the limit action frequency. I apply the model to monetary policy cycles and choices in the face of complex tax schedules.", "date": "2025", "date_kind": "\u5728\u7ebf\u53d1\u8868", "first_seen": "2026-09-26T10:39:40+00:00", "url": "https://doi.org/10.3982/ecta22139", "title_zh": "\u5bf9\u6a21\u578b\u9057\u6f0f\u7684\u52a8\u6001\u5173\u6ce8", "abstract_zh": "\u6211\u7814\u7a76\u4e86\u4e00\u4f4d\u4e3b\u4f53\u5bf9\u6536\u76ca\u76f8\u5173\u7ed3\u679c\u63d0\u51fa\u4e00\u7ec4\u6982\u7387\u6a21\u578b\u7684\u60c5\u51b5\u3002\u8be5\u4e3b\u4f53\u5bf9\u8fd9\u4e00\u6a21\u578b\u96c6\u5408\u6301\u6709\u5148\u9a8c\u4fe1\u5ff5\uff0c\u4f46\u62c5\u5fc3\u5b9e\u9645\u6a21\u578b\u88ab\u9057\u6f0f\uff0c\u5e76\u4e3a\u6b64\u8fdb\u884c\u5bf9\u51b2\u3002\u5bf9\u6a21\u578b\u9057\u6f0f\u7684\u62c5\u5fe7\u662f\u5185\u751f\u7684\uff1a\u5982\u679c\u4e00\u4e2a\u6a21\u578b\u80fd\u5f88\u597d\u5730\u89e3\u91ca\u4ee5\u5f80\u7684\u89c2\u6d4b\u7ed3\u679c\uff0c\u8fd9\u79cd\u62c5\u5fe7\u5c31\u4f1a\u51cf\u5f31\u3002\u6211\u8bc1\u660e\uff0c\u5728\u957f\u671f\u4e2d\uff0c\u6839\u636e\u4e3b\u4f53\u5bf9\u672a\u89e3\u91ca\u8bc1\u636e\u7684\u4e0d\u6ee1\u7a0b\u5ea6\u53d8\u5316\u901f\u5ea6\uff0c\u4e0d\u540c\u7684\u9759\u6001\u4e0d\u786e\u5b9a\u6027\u504f\u597d\uff08\u4e3b\u89c2\u671f\u671b\u6548\u7528\u3001maxmin\u3001\u9c81\u68d2\u63a7\u5236\uff09\u4f1a\u663e\u73b0\u51fa\u6765\u3002\u5bf9\u6a21\u578b\u9057\u6f0f\u7684\u62c5\u5fe7\u7684\u5185\u751f\u6027\u81ea\u7136\u5bfc\u81f4\u884c\u4e3a\u5468\u671f\uff0c\u6211\u523b\u753b\u4e86\u6781\u9650\u884c\u52a8\u9891\u7387\u3002\u6211\u5c06\u8be5\u6a21\u578b\u5e94\u7528\u4e8e\u8d27\u5e01\u653f\u7b56\u5468\u671f\u4ee5\u53ca\u9762\u5bf9\u590d\u6742\u7a0e\u5236\u65f6\u7684\u51b3\u7b56\u95ee\u9898\u3002", "translation_source": "journal-qwen4b", "topics": ["\u5176\u4ed6"]}], "briefs": [{"date": "2026-10-09", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "preferences": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "\u7f51\u7edc", "\u5e02\u573a\u53cd\u9988", "AI", "\u6781\u7aef\u98ce\u9669", "\u5e76\u8d2d", "\u8d44\u672c\u6d41\u52a8"], "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.1287/mnsc.2024.06516", "summary_zh": "\u672c\u6587\u63d0\u51fa\u4e00\u79cd\u57fa\u4e8e\u516c\u53f8\u7f51\u7ad9\u6587\u672c\u7684\u8868\u793a\u5b66\u4e60\u65b9\u6cd5\uff0c\u901a\u8fc7\u6784\u5efa\u4f01\u4e1a\u5d4c\u5165\u7a7a\u95f4\uff0c\u8bc6\u522b\u516c\u5171\u548c\u79c1\u8425\u4f01\u4e1a\u7684\u7ade\u4e89\u7f51\u7edc\uff08WTNIC\uff09\u3002\u8be5\u65b9\u6cd5\u5229\u7528\u884c\u4e1a\u7279\u5b9a\u4fe1\u606f\uff0c\u5c06\u4f01\u4e1a\u7f6e\u4e8e\u7edf\u4e00\u7a7a\u95f4\uff0c\u5f62\u6210\u53ef\u5206\u6790\u7684\u7ade\u4e89\u7f51\u7edc\uff0c\u5e76\u5728\u591a\u4e2a\u771f\u5b9e\u6570\u636e\u96c6\u4e0a\u8868\u73b0\u7a33\u5065\uff0c\u751a\u81f3\u4f18\u4e8e\u4f9d\u8d56\u4eba\u5de5\u6570\u636e\u7684\u4f20\u7edf\u65b9\u6cd5\u3002\u6848\u4f8b\u7814\u7a76\u663e\u793a\uff0c\u4e2d\u56fd\u4f01\u4e1a\u7684\u7ade\u4e89\u5bf9\u76ee\u6807\u516c\u53f8\u53ca\u5176\u540c\u884c\u4ea7\u751f\u5f71\u54cd\uff0c\u51f8\u663e\u4e86\u7edf\u4e00\u5efa\u6a21\u516c\u5171\u4e0e\u79c1\u8425\u4f01\u4e1a\u7684\u91cd\u8981\u6027\u3002", "summary_en": "This paper proposes a representation learning method using company website text to identify competitor networks among public and private firms. By embedding firms in a shared space based on industry-specific content, it constructs a peer competitor network (WTNIC) that enables scalable analysis of competition. The method performs robustly and outperforms prior curated-data approaches, even with noisy web content. A case study shows how competition from China affects a focal firm and its peers, highlighting the importance of including both public and private firms in the same space.", "reason_zh": "\u8be5\u7814\u7a76\u5177\u6709\u5730\u7f18\u653f\u6cbb\uff08\u4e2d\u56fd\u7ade\u4e89\uff09\u3001\u7f51\u7edc\u7ed3\u6784\u3001\u6587\u672c\u5206\u6790\u548c\u5e02\u573a\u53cd\u9988\u7684\u73b0\u5b9e\u610f\u4e49\uff0c\u4e3a\u673a\u6784\u6295\u8d44\u8005\u8bc4\u4f30\u884c\u4e1a\u7ade\u4e89\u683c\u5c40\u4e0e\u6781\u7aef\u98ce\u9669\u63d0\u4f9b\u4e86\u57fa\u4e8e\u771f\u5b9e\u6570\u636e\u7684\u52a8\u6001\u89c6\u89d2\uff0c\u5c24\u5176\u9002\u7528\u4e8e\u5e76\u8d2d\u4e0e\u8d44\u672c\u6d41\u52a8\u4e2d\u7684\u7ade\u4e89\u76d1\u6d4b\u3002", "reason_en": "The study offers geopolitical relevance (e.g., China's competitive impact), network structure, text analysis, and market feedback, providing institutional investors with a dynamic, data-driven view of competitive landscapes and extreme risks, especially relevant for M&A and capital flow monitoring."}, {"doi": "10.1111/jofi.70084", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u91d1\u878d\u516c\u53f8\u53d1\u884c\u7684\u503a\u5238\u6bd4\u5de5\u4e1a\u516c\u53f8\u540c\u8bc4\u7ea7\u548c\u671f\u9650\u7684\u503a\u5238\u5177\u6709\u66f4\u9ad8\u7684\u4fe1\u7528\u5229\u5dee\uff0c\u5373\u2018\u91d1\u878d\u6ea2\u4ef7\u2019\uff0c\u5e73\u5747\u4e3a43\u4e2a\u57fa\u70b9\uff0c\u4e14\u5728\u4f4e\u8bc4\u7ea7\u3001\u91d1\u878d\u5371\u673a\u548c\u9ad8\u503a\u5238\u7cfb\u7edf\u6027\u98ce\u9669\u65f6\u663e\u8457\u4e0a\u5347\u3002\u6587\u7ae0\u6784\u5efa\u6a21\u578b\u6307\u51fa\uff0c\u94f6\u884c\u6301\u6709\u975e\u91d1\u878d\u503a\u52a1\u7684\u591a\u6837\u5316\u7ec4\u5408\uff0c\u5bfc\u81f4\u5176\u503a\u52a1\u627f\u62c5\u66f4\u591a\u7cfb\u7edf\u6027\u98ce\u9669\u3002", "summary_en": "We find that bonds issued by financial firms have higher spreads than those by industrial firms with identical ratings and maturities\u2014known as the financial premium. Over 1987\u20132002, the average premium is 43 basis points, increasing with lower ratings, financial crises, and higher bond beta. A model shows that banks' diversified holdings of nonfinancial debt lead to higher systematic risk in bank debt.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u91d1\u878d\u503a\u52a1\u7684\u7cfb\u7edf\u6027\u98ce\u9669\u6ea2\u4ef7\uff0c\u5bf9\u673a\u6784\u6295\u8d44\u8005\u7684\u98ce\u9669\u5b9a\u4ef7\u3001\u8d44\u672c\u914d\u7f6e\u53ca\u5730\u7f18\u653f\u6cbb\u6216\u5e02\u573a\u52a8\u8361\u4e0b\u7684\u8d44\u4ea7\u5b9a\u4ef7\u5177\u6709\u91cd\u8981\u53c2\u8003\u4ef7\u503c\u3002", "reason_en": "The paper reveals a systematic risk premium in financial firm debt, offering key insights for institutional investors in risk assessment, capital allocation, and asset pricing under geopolitical or market stress."}, {"doi": "10.1111/jofi.70083", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0cESG\u6295\u8d44\u7684\u8fd1\u671f\u6536\u76ca\u4e3b\u8981\u7531\u8d44\u91d1\u6d41\u5165\u5f15\u53d1\u7684\u4ef7\u683c\u51b2\u51fb\u9a71\u52a8\u3002\u6bcf\u6d41\u51651\u7f8e\u5143\u81f3\u4ee3\u8868\u6027ESG\u57fa\u91d1\uff0cESG\u80a1\u7968\u5e02\u503c\u589e\u52a00.8\u7f8e\u5143\uff0c\u5e74\u5316\u6d41\u5165\u9a71\u52a8\u6536\u76ca\u4e3a1.9%\u3002\u82e5\u65e0\u8d44\u91d1\u6d41\u5165\uff0cESG\u8d44\u4ea7\u57282012\u20132023\u5e74\u4e0d\u4f1a\u8dd1\u8d62\u5e02\u573a\uff0c\u51f8\u663e\u673a\u6784\u6295\u8d44\u8005\u884c\u4e3a\u4e0e\u8d44\u672c\u6d41\u52a8\u5bf9ESG\u56de\u62a5\u7684\u6838\u5fc3\u4f5c\u7528\u3002", "summary_en": "The recent ESG returns are primarily driven by price impacts from flows into ESG portfolios. Each $1 flowing into a representative ESG portfolio increases ESG stock market value by $0.8, yielding an annual flow-driven return of 1.9%. Without flows, ESG stocks would not have outperformed from 2012 to 2023, highlighting the central role of institutional flows and capital movements in ESG returns.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u8d44\u672c\u6d41\u52a8\u4e0e\u673a\u6784\u6295\u8d44\u8005\u884c\u4e3a\u5bf9ESG\u8d44\u4ea7\u5b9a\u4ef7\u7684\u76f4\u63a5\u5f71\u54cd\uff0c\u5bf9\u7406\u89e3\u5e02\u573a\u53cd\u9988\u3001\u6781\u7aef\u98ce\u9669\u53ca\u5e76\u8d2d\u4e2dESG\u56e0\u7d20\u7684\u5b9a\u4ef7\u903b\u8f91\u5177\u6709\u73b0\u5b9e\u610f\u4e49\uff0c\u5c24\u5176\u5728\u5730\u7f18\u653f\u6cbb\u4e0e\u7eff\u8272\u91d1\u878d\u653f\u7b56\u4ea4\u7ec7\u7684\u80cc\u666f\u4e0b\u3002", "reason_en": "The paper reveals how capital flows and institutional behavior directly influence ESG asset pricing, offering insights into market feedback, extreme risks, and ESG valuation in mergers and acquisitions, especially amid geopolitical and green finance policy shifts."}, {"doi": "10.1111/jofi.70085", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u7f8e\u56fd\u56fd\u503a\u7684\u4fbf\u5229\u6536\u76ca\u5728\u56fd\u503a\u56de\u62a5\u4e0e\u80a1\u5e02\u534f\u65b9\u5dee\u8f83\u9ad8\u65f6\u504f\u4f4e\uff0c\u8868\u660e\u5176\u5177\u6709\u5bf9\u51b2\u5c5e\u6027\u3002\u5206\u89e3\u663e\u793a\uff0c\u80a1\u7968\u56de\u62a5\u4e0e\u4fbf\u5229\u6536\u76ca\u4e4b\u95f4\u7684\u534f\u65b9\u5dee\u662f\u5173\u952e\u9a71\u52a8\u56e0\u7d20\uff0c\u51f8\u663e\u56fd\u503a\u5728\u7ecf\u6d4e\u4e0b\u884c\u6216\u5e02\u573a\u6ce2\u52a8\u4e2d\u7684\u5bf9\u51b2\u4f5c\u7528\u3002", "summary_en": "The convenience yield of U.S. Treasuries is low when Treasury returns are highly correlated with stock market returns, consistent with a hedging perspective. The covariance between stock returns and the convenience yield itself is a key driver, highlighting Treasuries' role as a hedge during adverse shocks.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u56fd\u503a\u5728\u6781\u7aef\u98ce\u9669\u548c\u5e02\u573a\u6ce2\u52a8\u4e2d\u7684\u5bf9\u51b2\u529f\u80fd\uff0c\u6709\u52a9\u4e8e\u7406\u89e3\u5730\u7f18\u653f\u6cbb\u51b2\u51fb\u4e0b\u7684\u8d44\u4ea7\u5b9a\u4ef7\u3001\u673a\u6784\u6295\u8d44\u8005\u907f\u9669\u884c\u4e3a\u53ca\u5e02\u573a\u53cd\u9988\u673a\u5236\u3002", "reason_en": "The paper sheds light on Treasuries' hedging role during extreme risks and market volatility, providing insights into asset pricing, institutional investor behavior, and market feedback under geopolitical or macroeconomic stress."}, {"doi": "10.1111/jofi.70090", "summary_zh": "\u4f01\u4e1a\u5e76\u8d2d\u524d\u589e\u52a0\u5bf9\u76ee\u6807\u76f8\u5173\u6148\u5584\u673a\u6784\u7684\u6350\u8d60\uff0c\u5c06\u8d44\u91d1\u4ece\u975e\u5e76\u8d2d\u9886\u57df\u8f6c\u5411\u76ee\u6807\u5173\u8054\u65b9\u7684\u6148\u5584\u3001\u5458\u5de5\u793e\u533a\u548c\u76d1\u7ba1\u533a\u57df\uff0c\u4ee5\u589e\u5f3a\u5229\u76ca\u76f8\u5173\u8005\u8ba4\u540c\uff0c\u4e0e\u5e76\u8d2d\u6ea2\u4ef7\u4e0b\u964d\u548c\u6574\u5408\u6210\u672c\u964d\u4f4e\u76f8\u5173\u3002\u5b9a\u5411\u6148\u5584\u6709\u52a9\u4e8e\u6539\u5584\u5e76\u8d2d\u7ee9\u6548\uff0c\u4f53\u73b0\u4f01\u4e1a\u901a\u8fc7\u516c\u76ca\u7ba1\u7406\u5229\u76ca\u76f8\u5173\u8005\u5173\u7cfb\u7684\u7b56\u7565\u6027\u884c\u4e3a\u3002", "summary_en": "Firms increase donations to target-related charities before M&A to strengthen stakeholder alignment, linked with lower merger premiums and reduced integration costs. Funds are reallocated from non-takeover areas to insider-affiliated charities, employee communities, and regulated counties. Targeted philanthropy is associated with better deal performance through enhanced stakeholder engagement.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u516c\u76ca\u5728\u5e76\u8d2d\u51b3\u7b56\u4e2d\u7684\u6218\u7565\u4f5c\u7528\uff0c\u5c24\u5176\u5728\u5730\u7f18\u653f\u6cbb\u590d\u6742\u3001\u5e02\u573a\u53cd\u9988\u654f\u611f\u7684\u80cc\u666f\u4e0b\uff0c\u4f01\u4e1a\u901a\u8fc7\u5b9a\u5411\u6148\u5584\u7ba1\u7406\u5458\u5de5\u3001\u76d1\u7ba1\u53ca\u673a\u6784\u6295\u8d44\u8005\u5173\u7cfb\uff0c\u6709\u52a9\u4e8e\u8bc6\u522b\u6f5c\u5728\u534f\u540c\u4e0e\u6781\u7aef\u98ce\u9669\uff0c\u63d0\u5347\u8d44\u672c\u6d41\u52a8\u4e0e\u5e76\u8d2d\u51b3\u7b56\u7684\u900f\u660e\u5ea6\u3002", "reason_en": "The study shows how targeted philanthropy strategically manages stakeholder relations during M&A, especially in geographically and politically complex environments. It helps institutional investors assess risk, market feedback, and integration outcomes, offering insight into capital flows and extreme risk in cross-border deals."}]}, {"date": "2026-10-07", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "preferences": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "\u7f51\u7edc", "\u5e02\u573a\u53cd\u9988", "AI", "\u6781\u7aef\u98ce\u9669", "\u5e76\u8d2d", "\u8d44\u672c\u6d41\u52a8"], "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.3386/w35838", "summary_zh": "\u8be5\u7814\u7a76\u53d1\u73b0\uff0c\u8d1f\u9762\u65b0\u95fb\u7684\u6301\u7eed\u6027\u5728\u4e0d\u540c\u7ecf\u6d4e\u4e3b\u9898\u4e2d\u5b58\u5728\u663e\u8457\u5dee\u5f02\uff0c\u5c24\u5176\u5728\u5b89\u5168\u3001\u4f01\u4e1a\u6218\u7565\u3001\u5065\u5eb7\u548c\u623f\u5730\u4ea7\u7b49\u9886\u57df\u8868\u73b0\u7a81\u51fa\u3002\u5373\u4f7f\u4fe1\u606f\u9891\u7e41\u5230\u8fbe\uff0c\u8d1f\u9762\u60c5\u7eea\u4ecd\u80fd\u957f\u671f\u5f71\u54cd\u5e02\u573a\u9884\u671f\u548c\u8d44\u4ea7\u4ef7\u683c\uff0c\u8868\u660e\u5b8f\u89c2\u60c5\u7eea\u6307\u6570\u63a9\u76d6\u4e86\u4e3b\u9898\u5c42\u9762\u7684\u53d9\u4e8b\u4e0d\u5bf9\u79f0\u6027\u3002", "summary_en": "This paper shows that negative news persists more than positive news across economic topics, with the largest asymmetry in security, human rights, firms and corporate strategy, health, public safety, and real estate. The persistence of negative sentiment is especially strong in data-rich topics, indicating that frequent information arrival does not necessarily lead to narrative reversion.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u8d1f\u9762\u65b0\u95fb\u5728\u5b89\u5168\u3001\u5065\u5eb7\u3001\u91d1\u878d\u7a33\u5b9a\u7b49\u5173\u952e\u9886\u57df\u7684\u957f\u671f\u5f71\u54cd\uff0c\u5bf9\u7406\u89e3\u5730\u7f18\u653f\u6cbb\u51b2\u7a81\u3001\u6781\u7aef\u98ce\u9669\u4e8b\u4ef6\u4e0b\u7684\u5e02\u573a\u60c5\u7eea\u4f20\u5bfc\u548c\u8d44\u4ea7\u5b9a\u4ef7\u5177\u6709\u91cd\u8981\u4ef7\u503c\uff0c\u5c24\u5176\u5bf9\u673a\u6784\u6295\u8d44\u8005\u548c\u6587\u672c\u5206\u6790\u4e2d\u7684\u98ce\u9669\u9884\u8b66\u6709\u6307\u5bfc\u610f\u4e49\u3002", "reason_en": "The study reveals persistent negative narratives in critical domains such as security and health, offering insights into market sentiment dynamics during geopolitical shocks and extreme risks, with implications for asset pricing and risk assessment by institutional investors and text-based analysis."}, {"doi": "10.3386/w35857", "summary_zh": "\u65b0\u673a\u5668\u8bbe\u5907\u5bf9\u9ad8\u6280\u80fd\u52b3\u52a8\u529b\u7684\u9700\u6c42\u4e3b\u8981\u901a\u8fc7\u5916\u90e8\u4f9b\u5e94\u5546\u4f20\u5bfc\uff0c\u63d0\u5347\u603b\u9700\u6c4245%\uff0c\u662f\u5185\u90e8\u62db\u8058\u7684\u4e09\u500d\uff0c\u5c24\u5176\u5728\u5c0f\u578b\u4f01\u4e1a\u548c\u6295\u8d44\u96c6\u4e2d\u5ea6\u9ad8\u7684\u884c\u4e1a\u66f4\u663e\u8457\uff0c\u53cd\u6620\u51fa\u4f01\u4e1a\u96c7\u4f63\u9ad8\u6280\u80fd\u5de5\u4eba\u5b58\u5728\u9ad8\u56fa\u5b9a\u6210\u672c\u3002", "summary_en": "New machinery increases demand for high-STEM workers primarily through external suppliers, raising total demand by 45%\u2014three times more than in-house hiring, especially for smaller firms and lumpy investments, consistent with high fixed costs of in-house hiring.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u6280\u672f\u6295\u8d44\u901a\u8fc7\u4f9b\u5e94\u94fe\u4f20\u5bfc\u5bf9\u52b3\u52a8\u529b\u5e02\u573a\u7684\u5f71\u54cd\uff0c\u6709\u52a9\u4e8e\u7406\u89e3\u5e76\u8d2d\u3001\u8d44\u672c\u6d41\u52a8\u4e0e\u6781\u7aef\u98ce\u9669\u4e0b\u7684\u6280\u80fd\u7ed3\u6784\u53d8\u5316\uff0c\u5bf9\u673a\u6784\u6295\u8d44\u8005\u8bc4\u4f30\u6280\u672f\u9a71\u52a8\u578b\u4f01\u4e1a\u7684\u8d44\u4ea7\u5b9a\u4ef7\u5177\u6709\u73b0\u5b9e\u610f\u4e49\u3002", "reason_en": "The findings reveal how machinery investment reshapes labor demand via supply chains, offering insights into skill-based wage premiums and capital-labor complementarity under market feedback, relevant to mergers, capital flows, and extreme risk in tech-driven firms."}, {"doi": "10.3386/w35870", "summary_zh": "\u7814\u7a76\u63d0\u51fa\uff0c\u793e\u4ea4\u5a92\u4f53\u5e73\u53f0\u53ef\u901a\u8fc7\u63d0\u4f9b\u2018\u5b89\u5168\u5c42\u7ea7\u2019\u4fdd\u7559\u7f51\u7edc\u8bbf\u95ee\u6743\u9650\u5e76\u9650\u5236\u7b97\u6cd5\u63a8\u8350\u7b49\u9ad8\u98ce\u9669\u5185\u5bb9\uff0c\u63d0\u5347\u9752\u5c11\u5e74\u798f\u7949\uff0c\u964d\u4f4e\u5bf9\u540c\u4f34\u538b\u529b\u7684\u4f9d\u8d56\uff0c\u5c24\u5176\u5728\u4e2d\u7b49\u76d1\u7ba1\u5904\u7f5a\u4e0b\u6548\u679c\u663e\u8457\u3002", "summary_en": "A policy design enabling platforms to offer a safe tier with restricted features (e.g., algorithmic feeds) while preserving network access improves teen welfare and reduces reliance on peer dynamics, especially under moderate regulatory penalties.", "reason_zh": "\u8be5\u7814\u7a76\u5bf9\u5730\u7f18\u653f\u6cbb\u4e0b\u6570\u5b57\u5e73\u53f0\u76d1\u7ba1\u3001\u8d44\u4ea7\u5b9a\u4ef7\u4e2d\u9752\u5c11\u5e74\u7f51\u7edc\u884c\u4e3a\u98ce\u9669\u3001\u673a\u6784\u6295\u8d44\u8005\u8bc4\u4f30\u5e73\u53f0\u6781\u7aef\u98ce\u9669\u4e0e\u8d44\u672c\u6d41\u52a8\u5177\u6709\u76f4\u63a5\u53c2\u8003\u4ef7\u503c\uff0c\u5c24\u5176\u5728\u5e76\u8d2d\u4e0e\u5e02\u573a\u53cd\u9988\u573a\u666f\u4e2d\u63d0\u4f9b\u53ef\u64cd\u4f5c\u7684\u6cbb\u7406\u8def\u5f84\u3002", "reason_en": "This paper offers actionable insights for institutional investors assessing digital platform risks, extreme risks, and capital flows in the context of social media regulation, with direct relevance to market feedback, network dynamics, and merger decisions under evolving geopolitical and policy environments."}, {"doi": "10.3386/w35860", "summary_zh": "\u79c1\u4eba\u80a1\u6743\u57fa\u91d1\u7ba1\u7406\u8005\u5728\u6295\u8d44\u65e9\u671f\u901a\u8fc7\u6587\u672c\u8ba8\u8bba\u4f20\u9012\u4f01\u4e1a\u8d28\u91cf\u4fe1\u606f\uff0c\u65e9\u671f\u6587\u672c\u62ab\u9732\u66f4\u6709\u6548\uff0c\u878d\u8d44\u4e8b\u4ef6\u540e\u4f30\u503c\u62ab\u9732\u91cd\u8981\u6027\u4e0a\u5347\uff1b\u4fe1\u606f\u5f3a\u5ea6\u53d7\u5185\u5bb9\u4e0e\u8bed\u6c14\u5f71\u54cd\uff0c\u6587\u672c\u8ba8\u8bba\u53ef\u80fd\u53cd\u6620\u4e00\u822c\u5408\u4f19\u4eba\u8d28\u91cf\u3002", "summary_en": "Private equity fund managers convey firm quality through textual discussions early on, with textual disclosures more informative initially and interim valuations gaining importance after financing events; signal strength depends on content and tone, suggesting textual discussions reflect general partner quality.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u975e\u8d22\u52a1\u6587\u672c\u62ab\u9732\u5728\u4fe1\u606f\u4e0d\u5bf9\u79f0\u5e02\u573a\u4e2d\u7684\u4fe1\u53f7\u4f5c\u7528\uff0c\u5bf9\u7406\u89e3\u673a\u6784\u6295\u8d44\u8005\u51b3\u7b56\u3001\u5e76\u8d2d\u8bc4\u4f30\u4e0e\u6781\u7aef\u98ce\u9669\u8bc6\u522b\u5177\u6709\u73b0\u5b9e\u610f\u4e49\u3002", "reason_en": "The study reveals the signaling role of narrative disclosures in information asymmetry markets, offering insights into institutional investor decisions, M&A evaluations, and extreme risk identification."}, {"doi": "10.3386/w35769", "summary_zh": "\u5730\u7406\u6269\u5f20\u6210\u672c\u9ad8\u6602\uff0c\u5bfc\u81f4\u5b9a\u4ef7\u52a3\u52bf\u548c\u8d54\u4ed8\u7387\u4e0a\u5347\uff0c\u5176\u7a33\u5b9a\u6027\u4e3b\u8981\u6e90\u4e8e\u89c4\u6a21\u6548\u5e94\u800c\u975e\u5730\u7406\u591a\u6837\u6027\u3002\u98ce\u9669\u5206\u6563\u5b58\u5728\u8fb9\u754c\uff0c\u7ea690%\u7684\u635f\u5931\u6ce2\u52a8\u7531\u5e02\u573a\u5171\u6027\u51b3\u5b9a\u3002", "summary_en": "Geographic expansion incurs high costs, including higher claims and lower per-dollar coverage; stability stems from scale, not diversification. Risk pooling is bounded, with about 90% of loss volatility shared across markets.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u673a\u6784\u6295\u8d44\u8005\u8de8\u533a\u57df\u6269\u5f20\u7684\u5185\u5728\u6210\u672c\u4e0e\u7a33\u5b9a\u6027\u6765\u6e90\uff0c\u5bf9\u7406\u89e3\u5730\u7f18\u653f\u6cbb\u4e0b\u8d44\u672c\u6d41\u52a8\u3001\u5e02\u573a\u53cd\u9988\u4e0e\u6781\u7aef\u98ce\u9669\u5177\u6709\u73b0\u5b9e\u610f\u4e49\u3002", "reason_en": "The study reveals the cost structure and stability origins of institutional investors' geographic expansion, offering insights into capital flows, market feedback, and extreme risks under geopolitical dynamics."}]}, {"date": "2026-10-06", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "preferences": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "\u7f51\u7edc", "\u5e02\u573a\u53cd\u9988", "AI", "\u6781\u7aef\u98ce\u9669", "\u5e76\u8d2d", "\u8d44\u672c\u6d41\u52a8"], "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.3386/w35862", "summary_zh": "\u672c\u6587\u63ed\u793a\u5730\u7f18\u653f\u6cbb\u7ade\u4e89\u5982\u4f55\u901a\u8fc7\u5efa\u7acb\u65e2\u5f97\u5229\u76ca\u673a\u5236\uff0c\u4f7f\u4e3b\u8981\u5f3a\u56fd\u907f\u514d\u538b\u5236\u65b0\u5174\u56fd\u5bb6\uff0c\u4ece\u800c\u95f4\u63a5\u4fdd\u62a4\u5176\u53d1\u5c55\u3002\u7f8e\u56fd\u9769\u547d\u3001\u4e2d\u56fd\u6838\u5d1b\u8d77\u53ca\u7f8e\u82cf\u897f\u5fb7\u6838\u535a\u5f08\u6848\u4f8b\u8868\u660e\uff0c\u73b0\u6709\u5f3a\u56fd\u95f4\u7684\u5bf9\u6297\u53ef\u80fd\u5f62\u6210\u2018\u5730\u7f18\u653f\u6cbb\u9677\u9631\u2019\uff0c\u7a33\u5b9a\u6743\u529b\u7ed3\u6784\uff0c\u5c24\u5176\u5bf9\u65b0\u5174\u56fd\u5bb6\u7684\u751f\u5b58\u4e0e\u6210\u957f\u5177\u6709\u6218\u7565\u610f\u4e49\u3002", "summary_en": "This paper reveals how rivalry among established powers creates strategic incentives to avoid suppressing rising states, indirectly protecting their development. Cases such as the American Revolution, China\u2019s nuclear emergence, and U.S.\u2013Soviet bargaining over West German nuclear capabilities demonstrate that established rivalries may form a 'geopolitical trap' that stabilizes the power structure, especially for vulnerable rising states.", "reason_zh": "\u8be5\u7814\u7a76\u5bf9\u5730\u7f18\u653f\u6cbb\u4e2d\u65b0\u5174\u56fd\u5bb6\u7684\u751f\u5b58\u673a\u5236\u63d0\u4f9b\u53cd\u76f4\u89c9\u4f46\u6709\u529b\u7684\u89e3\u91ca\uff0c\u6709\u52a9\u4e8e\u7406\u89e3\u6781\u7aef\u98ce\u9669\u4e0b\u7684\u6743\u529b\u52a8\u6001\uff0c\u5bf9\u673a\u6784\u6295\u8d44\u8005\u8bc4\u4f30\u5730\u7f18\u98ce\u9669\u3001\u4f01\u4e1a\u5e76\u8d2d\u51b3\u7b56\u53ca\u8d44\u672c\u6d41\u52a8\u5177\u6709\u73b0\u5b9e\u53c2\u8003\u4ef7\u503c\u3002", "reason_en": "The paper offers a counterintuitive yet robust explanation of how rising powers survive in competitive environments, providing critical insight into geopolitical risk, strategic stability, and implications for institutional investors, mergers and acquisitions, and capital flows."}, {"doi": "10.3386/w35840", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u80a1\u7968\u77ed\u671f\u56de\u62a5\u7684\u53cd\u8f6c\u4e3b\u8981\u7531\u975e\u7cfb\u7edf\u6027\u98ce\u9669\u7684\u4e0d\u5bf9\u79f0\u53cd\u8f6c\u9a71\u52a8\uff0c\u8d1f\u5411\u51b2\u51fb\u7684\u53cd\u8f6c\u901f\u5ea6\u663e\u8457\u6162\u4e8e\u6b63\u5411\u51b2\u51fb\uff0c\u8be5\u73b0\u8c61\u63ed\u793a\u4e86\u8d44\u4ea7\u5b9a\u4ef7\u4e2d\u7684\u975e\u5bf9\u79f0\u673a\u5236\uff0c\u6709\u52a9\u4e8e\u7406\u89e3\u5e02\u573a\u5f02\u5e38\u4e0e\u6781\u7aef\u98ce\u9669\u7684\u5f62\u6210\u3002", "summary_en": "The study finds that short-term return reversal is primarily driven by asymmetric idiosyncratic reversal, where negative shocks reverse more slowly than positive ones, revealing a key asymmetric mechanism in asset pricing.", "reason_zh": "\u8be5\u53d1\u73b0\u5bf9\u7406\u89e3\u5e02\u573a\u6781\u7aef\u98ce\u9669\u548c\u77ed\u671f\u4ef7\u683c\u6ce2\u52a8\u5177\u6709\u76f4\u63a5\u610f\u4e49\uff0c\u5c24\u5176\u5bf9\u673a\u6784\u6295\u8d44\u8005\u548c\u6587\u672c\u5206\u6790\u4e2d\u8bc6\u522b\u5f02\u5e38\u4fe1\u53f7\u3001\u8bc4\u4f30\u5e02\u573a\u53cd\u9988\u81f3\u5173\u91cd\u8981\u3002", "reason_en": "This insight is crucial for understanding short-term market volatility and extreme risks, offering practical value for institutional investors and market participants analyzing network dynamics and asset pricing anomalies."}, {"doi": "10.3386/w35865", "summary_zh": "\u4eba\u5de5\u667a\u80fd\u9a71\u52a8\u6570\u636e\u4e2d\u5fc3\u548c\u8ba1\u7b97\u8bbe\u5907\u5927\u89c4\u6a21\u6269\u5f20\uff0c1GW AI\u56ed\u533a\u6210\u672c\u7ea6410\u4ebf\u7f8e\u5143\uff0c\u7f8e\u56fd2032\u5e74188GW\u5efa\u8bbe\u8ba1\u5212\u9700\u6295\u8d44\u8fd19\u4e07\u4ebf\u7f8e\u5143\uff0c\u5e74\u5747\u5360GDP\u76843.2%\u3002\u878d\u8d44\u8f6c\u5411\u79df\u8d41\u3001\u5408\u8d44\u3001\u9879\u76ee\u503a\u52a1\u7b49\u7ed3\u6784\uff0c\u867d\u6269\u5927\u8d44\u91d1\u6765\u6e90\uff0c\u4f46\u52a0\u5267\u8d44\u4ea7\u6760\u6746\uff0c\u66b4\u9732\u6280\u672f\u8fc7\u65f6\u3001\u6267\u884c\u5ef6\u8fdf\u548c\u6b8b\u503c\u4e0d\u786e\u5b9a\u7b49\u98ce\u9669\u3002", "summary_en": "AI drives massive expansion in data centers and computing infrastructure. A 1 GW AI campus costs ~$41 billion; a 188 GW U.S. buildout by 2032 requires ~$9 trillion, representing 3.2% of GDP annually. Financing shifts to leases, joint ventures, and project debt, expanding capacity but increasing leverage and exposing risks like technological obsolescence and execution delays.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793aAI\u57fa\u7840\u8bbe\u65bd\u6295\u8d44\u7684\u89c4\u6a21\u4e0e\u98ce\u9669\u7ed3\u6784\uff0c\u5bf9\u7406\u89e3\u5730\u7f18\u653f\u6cbb\u4e0b\u7684\u8d44\u672c\u6d41\u52a8\u3001\u7f51\u7edc\u6269\u5f20\u3001\u6781\u7aef\u98ce\u9669\u53ca\u5e76\u8d2d\u51b3\u7b56\u5177\u6709\u73b0\u5b9e\u610f\u4e49\uff0c\u5c24\u5176\u6d89\u53ca\u673a\u6784\u6295\u8d44\u8005\u3001\u5e02\u573a\u53cd\u9988\u548cAI\u9a71\u52a8\u7684\u8d44\u672c\u914d\u7f6e\u3002", "reason_en": "The paper provides critical insights into AI-driven capital deployment, infrastructure scaling, and risk exposure, relevant to geopolitical dynamics, capital flows, network growth, and extreme risks in tech-driven markets, especially for institutional investors and market feedback mechanisms."}, {"doi": "10.3386/w35839", "summary_zh": "\u8bba\u6587\u5c06\u5927\u578b\u8bed\u8a00\u6a21\u578b\u7c7b\u6bd4\u4e3a\u6295\u7968\u673a\u5236\uff0c\u6307\u51fa\u5176\u63a8\u8350\u53ef\u80fd\u4ea7\u751fCondorcet\u5faa\u73af\uff0c\u5bfc\u81f4\u4e0d\u4e00\u81f4\u7684\u5efa\u8bae\uff0c\u5b58\u5728\u88ab\u5957\u5229\u5229\u7528\u7684\u98ce\u9669\u3002\u7814\u7a76\u57fa\u4e8eChatGPT-4o\u53d1\u73b0S&P 100\u516c\u53f8\u6295\u8d44\u9009\u62e9\u4e2d\u5b58\u5728\u5927\u91cf\u5faa\u73af\uff0c\u4e14\u4e8b\u540e\u4fee\u6b63\u4e0d\u53ef\u884c\uff0c\u6e29\u5ea6\u53c2\u6570\u5f71\u54cd\u6295\u7968\u7ed3\u679c\u7684\u5206\u5e03\u3002", "summary_en": "Large language models function as voting rules where input texts represent elections and outputs reflect vote shares. They can generate Condorcet cycles, resulting in intransitive recommendations and potential money-pump exploitation, with temperature altering the distribution of output probabilities.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86LLM\u5728\u91d1\u878d\u51b3\u7b56\u4e2d\u53ef\u80fd\u5f15\u53d1\u7684\u7cfb\u7edf\u6027\u4e0d\u4e00\u81f4\u4e0e\u6781\u7aef\u98ce\u9669\uff0c\u5bf9\u7406\u89e3AI\u5728\u8d44\u4ea7\u5b9a\u4ef7\u3001\u5e02\u573a\u53cd\u9988\u548c\u5e76\u8d2d\u4e2d\u7684\u884c\u4e3a\u5177\u6709\u73b0\u5b9e\u610f\u4e49\uff0c\u5951\u5408\u7528\u6237\u5bf9AI\u3001\u6781\u7aef\u98ce\u9669\u548c\u8d44\u672c\u6d41\u52a8\u7684\u5173\u6ce8\u3002", "reason_en": "The paper reveals systemic inconsistencies and extreme risk in LLM-driven financial recommendations, offering insights into AI behavior in asset pricing, market feedback, and M&A decisions, directly relevant to institutional investors and network dynamics."}, {"doi": "10.3386/w35859", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u81ea2023\u5e74\u8d77AI\u5199\u4f5c\u5728\u535a\u58eb\u8bba\u6587\u4e2d\u8fc5\u901f\u589e\u957f\uff0c\u5c24\u5176\u5728\u975e\u82f1\u8bed\u56fd\u5bb6\u548c\u4f4e\u6392\u540d\u9662\u6821\u4e2d\u66f4\u666e\u904d\u3002\u4f7f\u7528AI\u5199\u4f5c\u7684\u535a\u58eb\u751f\u66f4\u53ef\u80fd\u8fdb\u5165\u4ea7\u4e1a\u6216\u975e\u7ec8\u8eab\u5236\u5b66\u672f\u5c97\u4f4d\uff0c\u800c\u975e\u7814\u7a76\u578b\u5c97\u4f4d\uff0c\u8868\u660eAI\u53ef\u80fd\u524a\u5f31\u79d1\u5b66\u8bad\u7ec3\u4e2d\u5173\u952e\u80fd\u529b\u7684\u5f62\u6210\u3002", "summary_en": "AI-generated writing in PhD dissertations rises rapidly, especially among non-English-speaking students and lower-ranked programs. Students using AI are less likely to enter academic research and more likely to enter industry or non-tenure-track roles, suggesting AI may undermine key aspects of scientific expertise development.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793aAI\u5bf9\u79d1\u5b66\u4eba\u624d\u80fd\u529b\u57f9\u517b\u7684\u6f5c\u5728\u51b2\u51fb\uff0c\u5bf9\u7406\u89e3\u5730\u7f18\u653f\u6cbb\u4e0b\u4eba\u624d\u6d41\u52a8\u3001\u673a\u6784\u6295\u8d44\u8005\u5bf9\u79d1\u7814\u4eba\u624d\u7684\u957f\u671f\u8bc4\u4f30\u3001\u4ee5\u53ca\u5e02\u573a\u5bf9\u6781\u7aef\u98ce\u9669\u548c\u5e76\u8d2d\u4e2d\u4eba\u529b\u8d44\u672c\u7684\u4f9d\u8d56\u5177\u6709\u73b0\u5b9e\u610f\u4e49\u3002", "reason_en": "This paper highlights AI's potential to disrupt core scientific expertise development, offering insights into capital flows, institutional investor strategies, and market responses to extreme risks and M&A driven by human capital dynamics."}]}, {"date": "2026-10-05", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "preferences": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "\u7f51\u7edc", "\u5e02\u573a\u53cd\u9988", "AI", "\u6781\u7aef\u98ce\u9669", "\u5e76\u8d2d", "\u8d44\u672c\u6d41\u52a8"], "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.1287/mnsc.2025.02137", "summary_zh": "\u672c\u6587\u7814\u7a76\u4e86\u4f9b\u5e94\u94fe\u4e2d\u5e93\u5b58\u7ba1\u7406\u6743\u7684\u5206\u914d\u95ee\u9898\uff0c\u6bd4\u8f83\u4e86\u5ba2\u6237\u7ba1\u7406\u5e93\u5b58\uff08CMI\uff09\u548c\u4f9b\u5e94\u5546\u7ba1\u7406\u5e93\u5b58\uff08SMI\uff09\u7684\u6548\u7387\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5f53\u5ba2\u6237\u9762\u4e34\u66f4\u9ad8\u7684\u7f3a\u8d27\u60e9\u7f5a\u4e14\u5176\u5206\u9500\u7f51\u7edc\u7ed3\u6784\u4e0d\u5bf9\u79f0\uff08\u5982\u9700\u6c42\u96c6\u4e2d\u4e8e\u5c11\u6570\u4ed3\u5e93\u6216\u8865\u8d27\u5468\u671f\u5dee\u5f02\u5927\uff09\u65f6\uff0cCMI\u66f4\u4f18\uff1b\u53cd\u4e4b\uff0cSMI\u66f4\u5408\u9002\u3002\u7814\u7a76\u8fd8\u8868\u660e\uff0c\u5c3d\u7ba1\u4e24\u8005\u5747\u65e0\u6cd5\u8fbe\u5230\u5b8c\u5168\u96c6\u4e2d\u7ba1\u7406\u7684\u6700\u4f18\u6c34\u5e73\uff0c\u4f46\u4e0e\u4e4b\u76f8\u6bd4\u7684\u6548\u7387\u635f\u5931\u8f83\u5c0f\u3002\u6570\u503c\u6a21\u62df\u663e\u793a\uff0c\u51b3\u7b56\u6743\u8f6c\u79fb\u914d\u5408\u5408\u7406\u7684\u5e93\u5b58\u6210\u672c\u5206\u62c5\u662f\u63d0\u5347\u7ee9\u6548\u7684\u5173\u952e\u3002", "summary_en": "This paper investigates the optimal governance of inventory control in supply chains, comparing Customer-Managed Inventory (CMI) and Supplier-Managed Inventory (SMI). It finds that CMI is preferable when the customer faces higher shortage penalties and operates in an asymmetric distribution network (e.g., demand concentrated in a subset of warehouses or with large lead time variation). Conversely, SMI is favored under opposite conditions. The study shows that while neither achieves first-best efficiency, the performance gap relative to full centralization is typically small. Numerical studies reveal that decision-right transfer, supported by appropriate cost-sharing, drives most performance gains.", "reason_zh": "\u8be5\u7814\u7a76\u5bf9\u7406\u89e3\u590d\u6742\u7f51\u7edc\u4e0b\u7684\u4f9b\u5e94\u94fe\u97e7\u6027\u5177\u6709\u76f4\u63a5\u4ef7\u503c\uff0c\u5c24\u5176\u5728\u5730\u7f18\u653f\u6cbb\u98ce\u9669\u52a0\u5267\u3001\u9700\u6c42\u5206\u5e03\u4e0d\u5747\u7684\u80cc\u666f\u4e0b\uff0c\u51b3\u7b56\u6743\u5206\u914d\u5f71\u54cd\u4f9b\u5e94\u94fe\u54cd\u5e94\u80fd\u529b\u4e0e\u6297\u98ce\u9669\u6c34\u5e73\uff0c\u9002\u7528\u4e8e\u673a\u6784\u6295\u8d44\u8005\u8bc4\u4f30\u4f9b\u5e94\u94fe\u98ce\u9669\u53ca\u5e76\u8d2d\u4e2d\u7684\u63a7\u5236\u6743\u7ed3\u6784\u8bbe\u8ba1\u3002", "reason_en": "This paper is relevant to geopolitical risk, supply chain resilience, and institutional investor assessments of risk exposure in fragmented networks. The findings inform decisions on control structure in mergers and acquisitions and help institutions evaluate supply chain robustness under extreme disruptions and asymmetric demand conditions."}, {"doi": "10.3386/w35774", "summary_zh": "\u672c\u6587\u5229\u7528\u5965\u5730\u5229\u548c\u5fb7\u56fd\u7684\u884c\u653f\u6570\u636e\uff0c\u7814\u7a76\u56fd\u9645\u79fb\u6c11\u7684\u5de5\u8d44\u56de\u62a5\u3002\u4ece\u5965\u5730\u5229\u8fc1\u79fb\u5230\u5fb7\u56fd\u7684\u79fb\u6c11\u65e5\u85aa\u5e73\u5747\u63d0\u534713%\uff0c\u5fb7\u56fd\u5230\u5965\u5730\u5229\u5219\u63d0\u53474%\u3002\u6536\u76ca\u968f\u8fd4\u56de\u65f6\u95f4\u9012\u51cf\uff0c\u7559\u5728\u76ee\u7684\u5730\u8005\u6700\u9ad8\uff0c\u77ed\u671f\u8fd4\u56de\u8005\u8f83\u4f4e\u3002\u901a\u8fc7\u73b0\u6709\u8de8\u5883\u5de5\u4f5c\u7f51\u7edc\u8fc1\u79fb\u8005\u6536\u76ca\u66f4\u9ad8\uff0c\u663e\u793a\u793e\u4f1a\u7f51\u7edc\u5bf9\u8fc1\u79fb\u7ed3\u679c\u6709\u663e\u8457\u5f71\u54cd\u3002", "summary_en": "Using linked administrative data from Austria and Germany, migrants from Austria to Germany see an average 13% wage increase, while those from Germany to Austria gain about 4%. Returns decline with return timing, being largest for those who stay, smaller for those returning after 1\u20134 years, and zero or negative for those returning within a year. Migrants via established cross-border work networks achieve higher gains, indicating significant network effects.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u52b3\u52a8\u529b\u8fc1\u79fb\u4e0e\u5730\u7f18\u7ecf\u6d4e\u7ed3\u6784\u7684\u5173\u8054\uff0c\u5bf9\u7406\u89e3\u8d44\u672c\u6d41\u52a8\u3001\u5e02\u573a\u53cd\u9988\u548c\u7f51\u7edc\u6548\u5e94\u5728\u8de8\u56fd\u4eba\u624d\u914d\u7f6e\u4e2d\u7684\u4f5c\u7528\u5177\u6709\u73b0\u5b9e\u610f\u4e49\uff0c\u5c24\u5176\u5bf9\u673a\u6784\u6295\u8d44\u8005\u548c\u5e76\u8d2d\u51b3\u7b56\u4e2d\u7684\u4eba\u5458\u6d41\u52a8\u8bc4\u4f30\u63d0\u4f9b\u5b9e\u8bc1\u652f\u6301\u3002", "reason_en": "This study reveals the link between labor migration and regional economic structures, offering practical insights into capital flows, market feedback, and network effects in cross-border talent allocation, particularly relevant for institutional investors and merger decisions involving workforce mobility."}, {"doi": "10.1287/mnsc.2023.00580", "summary_zh": "\u672c\u6587\u53d1\u73b0\uff0c\u5a92\u4f53\u5bf9\u8d1f\u9762\u65b0\u95fb\u7684\u62a5\u9053\u663e\u8457\u9884\u6d4b\u4f01\u4e1a\u540e\u7eed\u57fa\u672c\u9762\u6076\u5316\uff0c\u5305\u62ec\u66f4\u4f4e\u76c8\u5229\u3001\u66f4\u9ad8\u7834\u4ea7\u53ca\u5206\u7ea2\u524a\u51cf\u6982\u7387\u3002\u5a92\u4f53\u5e38\u4f20\u9012\u8d1f\u9762\u60c5\u7eea\uff0c\u6295\u8d44\u8005\u5173\u6ce8\u5ea6\u968f\u4e4b\u4e0a\u5347\uff0c\u8868\u660e\u5a92\u4f53\u5b58\u5728\u8d1f\u9762\u503e\u659c\u4ee5\u5438\u5f15\u8bfb\u8005\u3002\u8d1f\u9762\u4fe1\u606f\u5728\u4ef7\u683c\u53d1\u73b0\u521d\u671f\u88ab\u6291\u5236\uff0c\u6295\u8d44\u8005\u53cd\u5e94\u8fdf\u7f13\uff0c\u5bfc\u81f4\u8d1f\u9762\u4fe1\u53f7\u9010\u6b65\u878d\u5165\u4ef7\u683c\u5e76\u5f62\u6210\u53ef\u9884\u6d4b\u56de\u62a5\u3002", "summary_en": "We find that media coverage of negative news strongly predicts lower subsequent firm fundamentals, including reduced earnings and higher probabilities of bankruptcy, dividend cuts, and delistings. Media articles often convey negative sentiment, and investor attention increases around publication, indicating media bias toward negative events to drive readership. The negative signal is initially suppressed in price discovery, and investors respond slowly, leading to gradual incorporation into prices and return predictability.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u5a92\u4f53\u53d9\u4e8b\u5982\u4f55\u7cfb\u7edf\u6027\u626d\u66f2\u5e02\u573a\u9884\u671f\uff0c\u5bf9\u7406\u89e3\u5730\u7f18\u653f\u6cbb\u5f15\u53d1\u7684\u5e02\u573a\u6ce2\u52a8\u3001\u6781\u7aef\u98ce\u9669\u4e8b\u4ef6\u53ca\u673a\u6784\u6295\u8d44\u8005\u7684\u8d44\u4ea7\u5b9a\u4ef7\u51b3\u7b56\u5177\u6709\u91cd\u8981\u53c2\u8003\u4ef7\u503c\u3002", "reason_en": "This paper reveals how media narratives systematically distort market expectations, offering critical insights into market reactions to geopolitical shocks, extreme risks, and institutional investors' asset pricing decisions."}, {"doi": "10.1093/restud/rdag106", "summary_zh": "\u672c\u6587\u63a2\u8ba8\u4e86\u5168\u7403\u77f3\u6cb9\u9700\u6c42\u8d8b\u96f6\u60c5\u666f\u4e0b\u4f9b\u7ed9\u7684\u53ef\u80fd\u53cd\u5e94\u3002\u5c3d\u7ba1\u5b58\u5728\u2018\u7eff\u8272\u6096\u8bba\u2019\uff08\u52a0\u901f\u5f00\u91c7\uff09\u7684\u62c5\u5fe7\uff0c\u4f46\u56e0\u5f00\u91c7\u9700\u957f\u671f\u8d44\u672c\u6295\u5165\uff0c\u751f\u4ea7\u8005\u66f4\u53ef\u80fd\u51cf\u5c11\u6295\u8d44\uff0c\u4ece\u800c\u964d\u4f4e\u5f00\u91c7\u91cf\u3002\u53ea\u6709\u5728\u6295\u8d44\u5468\u671f\u77ed\u4e14\u751f\u4ea7\u8005\u5b9e\u9645\u8d34\u73b0\u7387\u4f4e\u4e8e4%\u65f6\uff0c\u7eff\u8272\u6096\u8bba\u624d\u53ef\u80fd\u663e\u8457\u589e\u52a0\u603b\u5f00\u91c7\u91cf\u3002", "summary_en": "The paper examines how global oil supply might respond to anticipated demand decline driven by clean energy or climate policies. Despite the 'green paradox' (accelerated extraction), durable capital investments suggest producers may reduce investment and extraction. The green paradox only substantially increases cumulative extraction if investment horizons are short and producers\u2019 real discount rates are below 4%.", "reason_zh": "\u8be5\u7814\u7a76\u5bf9\u5730\u7f18\u653f\u6cbb\u3001\u6781\u7aef\u98ce\u9669\u548c\u8d44\u672c\u6d41\u52a8\u5177\u6709\u91cd\u8981\u53c2\u8003\u4ef7\u503c\uff0c\u63ed\u793a\u4e86\u6c14\u5019\u653f\u7b56\u4e0b\u80fd\u6e90\u7ed3\u6784\u8f6c\u578b\u4e2d\u7684\u5e02\u573a\u53cd\u9988\u4e0e\u4f9b\u7ed9\u97e7\u6027\uff0c\u6709\u52a9\u4e8e\u673a\u6784\u6295\u8d44\u8005\u8bc4\u4f30\u8d44\u4ea7\u5b9a\u4ef7\u4e0e\u5e76\u8d2d\u98ce\u9669\u3002", "reason_en": "Relevant to geopolitical shifts, extreme risks, and capital flows, the study reveals market feedback and supply resilience under energy transition, aiding institutional investors in asset pricing and M&A risk assessment."}, {"doi": "10.1111/jofi.70081", "summary_zh": "\u672c\u6587\u53d1\u73b0\uff0c\u5728\u7834\u4ea7\u6848\u4ef6\u4e2d\uff0c\u590d\u6742\u5f53\u4e8b\u4eba\u4f1a\u2018\u9009\u62e9\u6cd5\u5b98\u2019\uff0c\u503e\u5411\u4e8e\u9009\u62e9\u5bf9\u672a\u62c5\u4fdd\u5bf9\u51b2\u57fa\u91d1\u503a\u6743\u4eba\u548c\u80a1\u6743\u6301\u6709\u4eba\u66f4\u53cb\u597d\u7684\u6cd5\u5b98\uff0c\u8fd9\u4e9b\u6cd5\u5b98\u8fc7\u53bb\u8f6c\u5316\u7387\u8f83\u4f4e\u3001\u672a\u62c5\u4fdd\u56de\u6536\u7387\u8f83\u9ad8\u3002\u6cd5\u5f8b\u987e\u95ee\u7ecf\u9a8c\u4e5f\u5f71\u54cd\u6cd5\u5b98\u5206\u914d\u3002\u7814\u7a76\u63d0\u51fa\u65b9\u6cd5\u8861\u91cf\u6b64\u7c7b\u7cfb\u7edf\u6027\u504f\u89c1\uff0c\u5e76\u5f3a\u8c03\u6cd5\u5b98\u8bbe\u8ba1\u4e2d\u9700\u4f7f\u7528\u63a7\u5236\u53d8\u91cf\u548c\u6709\u754c\u5de5\u5177\u53d8\u91cf\u3002", "summary_en": "The paper finds that sophisticated parties 'judge-shop', preferring judges with lower conversion rates and higher unsecured recovery rates for unsecured hedge fund creditors and equity holders. Experienced legal counsel also influences judge assignment. A method is developed to measure the resulting systematic bias, emphasizing the need for controls and bounded instrumental variable specifications in judge/examiner designs.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u53f8\u6cd5\u7cfb\u7edf\u4e2d\u7684\u7cfb\u7edf\u6027\u504f\u6027\uff0c\u6709\u52a9\u4e8e\u7406\u89e3\u673a\u6784\u6295\u8d44\u8005\u5728\u5e76\u8d2d\u4e0e\u8d44\u4ea7\u5b9a\u4ef7\u4e2d\u7684\u98ce\u9669\u66b4\u9732\uff0c\u4ee5\u53ca\u5e02\u573a\u53cd\u9988\u4e0e\u6587\u672c\u5206\u6790\u4e2d\u4fe1\u606f\u4e0d\u5bf9\u79f0\u7684\u52a8\u6001\u3002\u5bf9\u7f51\u7edc\u7ed3\u6784\u4e0e\u6781\u7aef\u98ce\u9669\u7684\u8bc4\u4f30\u5177\u6709\u76f4\u63a5\u53c2\u8003\u4ef7\u503c\u3002", "reason_en": "This study reveals systematic bias in judicial assignment, providing insights into institutional investors' risk exposure in mergers and asset pricing, and the dynamics of information asymmetry in market feedback and text analysis. It is directly relevant to network structures and extreme risk assessment."}]}, {"date": "2026-10-04", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "preferences": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "\u7f51\u7edc", "\u5e02\u573a\u53cd\u9988", "AI", "\u6781\u7aef\u98ce\u9669", "\u5e76\u8d2d", "\u8d44\u672c\u6d41\u52a8"], "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.3386/w35812", "summary_zh": "\u8be5\u7814\u7a76\u901a\u8fc7\u6784\u5efa\u822a\u8fd0\u8fd0\u8f93\u7684\u6392\u961f\u7f51\u7edc\u6a21\u578b\uff0c\u5206\u6790\u4e86\u8fd0\u8f93\u74f6\u9888\u5bf9\u4ef7\u683c\u548c\u56fd\u9645\u8d38\u6613\u7684\u5f71\u54cd\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u5728\u5168\u7403\u4f9b\u5e94\u94fe\u91cd\u5927\u4e2d\u65ad\u671f\u95f4\uff0c\u6e2f\u53e3\u74f6\u9888\u5bfc\u81f4\u5546\u54c1\u4ef7\u683c\u4e0a\u6da8\u548c\u77ed\u7f3a\uff0c\u4f46\u5546\u54c1\u4f9b\u5e94\u51cf\u5c11\u4e5f\u6291\u5236\u4e86\u4ef7\u683c\u4e0a\u6da8\uff1b\u800c\u57282000\u5e74\u4ee3\u7684\u5927\u5b97\u5546\u54c1\u5468\u671f\u4e2d\uff0c\u822a\u8fd0\u80fd\u529b\u4e0d\u8db3\u662f\u4ef7\u683c\u4e0a\u6da8\u7684\u4e3b\u8981\u539f\u56e0\u3002\u7814\u7a76\u4e3a\u7406\u89e3\u8fd0\u8f93\u7cfb\u7edf\u5728\u5730\u7f18\u653f\u6cbb\u51b2\u51fb\u548c\u7ecf\u6d4e\u5468\u671f\u4e2d\u7684\u4f5c\u7528\u63d0\u4f9b\u4e86\u91cf\u5316\u6846\u67b6\u3002", "summary_en": "This paper develops a tractable model of the transportation sector to study its impact on prices and international trade. It finds that port bottlenecks raised commodity prices and caused shortages during the Great Supply Chain Disruption, but a contraction in supply dampened these effects. In contrast, insufficient shipping capacity was a key driver of price increases during the 2000s Commodity Supercycle.", "reason_zh": "\u8be5\u7814\u7a76\u76f4\u63a5\u5173\u8054\u5730\u7f18\u653f\u6cbb\u98ce\u9669\uff08\u5982\u4f9b\u5e94\u94fe\u4e2d\u65ad\uff09\u4e0e\u5b8f\u89c2\u7ecf\u6d4e\u53d8\u91cf\uff08\u4ef7\u683c\u3001\u8d38\u6613\uff09\uff0c\u5e76\u63d0\u4f9b\u53ef\u8ba1\u7b97\u7684\u8fd0\u8f93\u74f6\u9888\u6307\u6807\uff0c\u5bf9\u7406\u89e3\u6781\u7aef\u98ce\u9669\u4e0b\u7684\u8d44\u672c\u6d41\u52a8\u548c\u4f9b\u5e94\u94fe\u97e7\u6027\u5177\u6709\u91cd\u8981\u73b0\u5b9e\u610f\u4e49\u3002", "reason_en": "This paper directly links geopolitical risks (e.g., supply chain disruptions) to macroeconomic outcomes (prices, trade) and provides a computable measure of transportation bottlenecks, offering critical insights into extreme risk and capital flow dynamics in supply chains."}, {"doi": "10.1017/s0022109026103172", "summary_zh": "\u8be5\u7814\u7a76\u901a\u8fc7\u6295\u8d44\u8005\u6d41\u91cf\u7684\u8de8\u6837\u672c\u76f8\u5173\u6027\u8861\u91cf\u57fa\u91d1\u6d41\u91cf\u591a\u6837\u5316\uff0c\u53d1\u73b0\u66f4\u9ad8\u591a\u6837\u5316\u4e0e\u672a\u6765\u6d41\u91cf\u6ce2\u52a8\u964d\u4f4e\u3001\u6d41\u51fa\u89c4\u6a21\u51cf\u5c0f\u53ca\u73b0\u91d1\u6301\u6709\u51cf\u5c11\u76f8\u5173\u3002\u610f\u5916\u4f4e\u76f8\u5173\u6027\u4e0e\u6d41\u51fa\u540e\u57fa\u91d1\u8868\u73b0\u63d0\u5347\u76f8\u5173\uff0c\u7f13\u89e3\u4e86\u5bf9\u73b0\u6709\u80a1\u4e1c\u7684\u5916\u90e8\u6027\uff0c\u540c\u65f6\u964d\u4f4e\u6d41\u52a8\u6027\u5dee\u57fa\u91d1\u5bf9\u7b56\u7565\u6027\u4e92\u8865\u6027\u7684\u654f\u611f\u6027\u3002", "summary_en": "This study measures flow diversification in mutual funds via cross-sectional correlation of daily flows across investor clienteles. Greater diversification is associated with lower future flow volatility, smaller subsequent outflows, and lower cash holdings. Unexpectedly low flow correlation is linked to higher post-outflow fund returns, mitigating outflow-induced externalities and reducing flow-performance sensitivity in illiquid funds.", "reason_zh": "\u5bf9\u673a\u6784\u6295\u8d44\u8005\u884c\u4e3a\u3001\u5e02\u573a\u53cd\u9988\u673a\u5236\u53ca\u6781\u7aef\u98ce\u9669\u4e0b\u8d44\u4ea7\u5b9a\u4ef7\u5177\u6709\u91cd\u8981\u53c2\u8003\u4ef7\u503c\uff0c\u5c24\u5176\u5728\u5e76\u8d2d\u3001\u8d44\u672c\u6d41\u52a8\u548c\u7f51\u7edc\u7ed3\u6784\u5206\u6790\u4e2d\u63d0\u4f9b\u5b9e\u8bc1\u4f9d\u636e\u3002", "reason_en": "Provides actionable insights into institutional investor behavior, market feedback dynamics, and asset pricing under extreme conditions, particularly relevant to mergers and acquisitions, capital flows, and networked investor structures."}, {"doi": "10.1093/rfs/hhag075", "summary_zh": "\u8be5\u7814\u7a76\u63a2\u8ba8\u4e86\u4f01\u4e1a\u8d22\u52a1\u7ea6\u675f\u5982\u4f55\u5f71\u54cd\u5176\u5728\u6700\u4f4e\u5de5\u8d44\u653f\u7b56\u4e0b\u7684\u96c7\u4f63\u51b3\u7b56\u3002\u7ed3\u679c\u8868\u660e\uff0c\u8d22\u52a1\u53d7\u9650\u4f01\u4e1a\u663e\u8457\u51cf\u5c11\u96c7\u4f63\uff0c\u800c\u65e0\u7ea6\u675f\u4f01\u4e1a\u5219\u5728\u52b3\u52a8\u529b\u4f9b\u5e94\u589e\u52a0\u3001\u79bb\u804c\u7387\u8f83\u9ad8\u7684\u5730\u533a\u6269\u5927\u96c7\u4f63\u3002\u8d22\u52a1\u7ea6\u675f\u662f\u52b3\u52a8\u653f\u7b56\u5f71\u54cd\u5c31\u4e1a\u7684\u6838\u5fc3\u4e2d\u4ecb\u673a\u5236\u3002", "summary_en": "This study examines how corporate financial constraints shape firms' employment responses to minimum wage policies. Results show that financially constrained firms significantly reduce employment, while unconstrained firms expand in areas with higher worker turnover and greater minimum-wage labor supply. Financial constraints act as a key mediating mechanism in labor policy effects.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u8d22\u52a1\u7ea6\u675f\u5728\u52b3\u52a8\u653f\u7b56\u4f20\u5bfc\u4e2d\u7684\u6838\u5fc3\u4f5c\u7528\uff0c\u5bf9\u7406\u89e3\u5730\u7f18\u653f\u6cbb\u4e0b\u8d44\u672c\u6d41\u52a8\u4e0e\u52b3\u52a8\u529b\u5e02\u573a\u52a8\u6001\u3001\u673a\u6784\u6295\u8d44\u8005\u5bf9\u8d22\u52a1\u98ce\u9669\u7684\u8bc4\u4f30\u3001\u4ee5\u53ca\u6781\u7aef\u98ce\u9669\u60c5\u5883\u4e0b\u7684\u4f01\u4e1a\u96c7\u4f63\u7b56\u7565\u5177\u6709\u73b0\u5b9e\u610f\u4e49\u3002", "reason_en": "The study reveals financial constraints as a central mechanism in labor policy transmission, offering relevance to capital flows, institutional investor risk assessment, market feedback, and extreme risk scenarios in networked and text-driven financial environments."}, {"doi": "10.1017/s0022109026103159", "summary_zh": "\u79c1\u52df\u80a1\u6743\u6536\u8d2d\u540e\uff0c\u7f8e\u56fd\u5316\u77f3\u71c3\u6599\u7535\u5382\u78b3\u6392\u653e\u5e73\u5747\u4e0b\u964d4.2%\uff0c\u4e3b\u8981\u6e90\u4e8e\u751f\u4ea7\u6548\u7387\u63d0\u5347\uff1b\u652f\u6301ESG\u7684\u79c1\u52df\u80a1\u6743\u9879\u76ee\u6392\u653e\u5f3a\u5ea6\u4e0b\u964d\u66f4\u663e\u8457\uff0c\u4f53\u73b0\u73af\u5883\u6539\u5584\u7684\u589e\u5f3a\u3002", "summary_en": "Private equity buyouts are associated with a 4.2% average reduction in CO2 emissions from U.S. fossil fuel power plants, primarily due to fuel-saving efficiency improvements. Emission intensities decline more significantly with pro-ESG private equity, indicating stronger environmental performance gains.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u8d44\u672c\u7ed3\u6784\u4e0e\u73af\u5883\u7ee9\u6548\u7684\u5173\u8054\uff0c\u5bf9\u7406\u89e3\u8d44\u4ea7\u5b9a\u4ef7\u3001ESG\u6295\u8d44\u56de\u62a5\u53ca\u6781\u7aef\u73af\u5883\u98ce\u9669\u3001\u7f51\u7edc\u578b\u80fd\u6e90\u4f01\u4e1a\u6cbb\u7406\u5177\u6709\u73b0\u5b9e\u610f\u4e49\uff0c\u5c24\u5176\u5bf9\u673a\u6784\u6295\u8d44\u8005\u548c\u5e76\u8d2d\u51b3\u7b56\u4e2d\u7684\u73af\u5883\u8003\u91cf\u91cd\u8981\u3002", "reason_en": "This study reveals a link between capital structure and environmental performance, directly relevant to green asset pricing, ESG investment returns, extreme environmental risk, and networked energy firm governance, especially for institutional investors and M&A decisions involving environmental factors."}, {"doi": "10.1287/mnsc.2024.07272", "summary_zh": "\u7814\u7a76\u5229\u7528\u673a\u5668\u5b66\u4e60\u65b9\u6cd5\u91cf\u5316\u4f01\u4e1a\u62db\u8058\u4fe1\u606f\u4e2d\u7684\u6838\u5fc3\u6587\u5316\u4ef7\u503c\u89c2\uff0c\u53d1\u73b0\u6587\u5316\u4fe1\u606f\u6709\u52a9\u4e8e\u5438\u5f15\u6c42\u804c\u8005\u3001\u63d0\u5347\u62db\u8058\u6d41\u5165\uff0c\u5c24\u5176\u5728\u6c42\u804c\u8005\u91cd\u89c6\u6587\u5316\u4e14\u4fe1\u606f\u83b7\u53d6\u53d7\u9650\u65f6\u6548\u679c\u66f4\u663e\u8457\uff0c\u5e76\u63d0\u9ad8\u9762\u8bd5\u8f6cOffer\u7387\u548cOffer\u63a5\u53d7\u7387\u3002", "summary_en": "We use machine learning to measure five core values in job postings and find that culture information helps attract job seekers, increases worker inflows, and improves offer acceptance rates, especially when job seekers value culture and face information frictions.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u4f01\u4e1a\u6587\u5316\u5728\u52b3\u52a8\u529b\u5e02\u573a\u4e2d\u7684\u4fe1\u53f7\u4f5c\u7528\uff0c\u5bf9\u673a\u6784\u6295\u8d44\u8005\u8bc4\u4f30\u4f01\u4e1a\u6587\u5316\u6cbb\u7406\u3001\u5458\u5de5\u7a33\u5b9a\u6027\u53ca\u6781\u7aef\u98ce\u9669\u5177\u6709\u53c2\u8003\u610f\u4e49\uff0c\u5c24\u5176\u5728\u5e76\u8d2d\u3001\u8d44\u672c\u6d41\u52a8\u4e0e\u5e02\u573a\u53cd\u9988\u4e2d\u4f53\u73b0\u6587\u5316\u5339\u914d\u7684\u91cd\u8981\u6027\u3002", "reason_en": "The study reveals the signaling role of corporate culture in labor markets, offering insights for institutional investors assessing cultural governance, employee retention, and extreme risks, particularly in mergers, capital flows, and market feedback mechanisms."}]}, {"date": "2026-10-03", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "preferences": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "\u7f51\u7edc", "\u5e02\u573a\u53cd\u9988", "AI", "\u6781\u7aef\u98ce\u9669", "\u5e76\u8d2d", "\u8d44\u672c\u6d41\u52a8"], "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.1111/jofi.70093", "summary_zh": "\u5728\u5171\u548c\u515a\u4e3b\u5bfc\u7684\u5dde\uff0c\u673a\u6784\u6295\u8d44\u8005\u5bf9\u73af\u5883\u548c\u793e\u4f1a\u8bae\u9898\u7684\u80a1\u4e1c\u63d0\u6848\u652f\u6301\u7387\u8f83\u4f4e\uff0c\u4e14\u8fd9\u4e00\u8d8b\u52bf\u8fd1\u5e74\u6765\u52a0\u5267\uff0c\u5c24\u5176\u5728\u83b7\u5f97\u5dde\u7ea7\u8865\u8d34\u548c\u7a0e\u6536\u4f18\u60e0\u7684\u516c\u53f8\u4e2d\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u6295\u8d44\u8005\u66f4\u6ce8\u91cd\u6700\u5927\u5316\u80a1\u4e1c\u4ef7\u503c\uff0c\u653f\u6cbb\u529b\u91cf\u53ef\u901a\u8fc7\u6539\u53d8\u80a1\u4e1c\u63d0\u6848\u7684\u4ef7\u503c\u542b\u4e49\u5f71\u54cd\u6295\u8d44\u8005\u51b3\u7b56\u3002", "summary_en": "Institutional investors are less likely to support shareholder proposals on environmental and social issues for firms headquartered in Republican-led states. The decline in support has become more pronounced in recent years, especially among firms receiving state-level subsidies and tax breaks. Findings indicate that institutional investors prioritize maximizing shareholder value, and politicians can influence investor votes by altering the value implications of shareholder proposals.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u5730\u7f18\u653f\u6cbb\u4e0e\u673a\u6784\u6295\u8d44\u8005\u884c\u4e3a\u4e4b\u95f4\u7684\u76f4\u63a5\u5173\u8054\uff0c\u5bf9\u7406\u89e3\u653f\u6cbb\u73af\u5883\u5982\u4f55\u5f71\u54cd\u8d44\u672c\u6d41\u52a8\u3001\u4f01\u4e1a\u6cbb\u7406\u53ca\u6781\u7aef\u98ce\u9669\u5177\u6709\u73b0\u5b9e\u610f\u4e49\uff0c\u5c24\u5176\u76f8\u5173\u4e8e\u5730\u7f18\u653f\u6cbb\u3001\u673a\u6784\u6295\u8d44\u8005\u548c\u5e02\u573a\u53cd\u9988\u7b49\u5173\u952e\u8bae\u9898\u3002", "reason_en": "The study reveals a direct link between geopolitical dynamics and institutional investor behavior, offering insights into how political environments influence capital flows, corporate governance, and extreme risk\u2014highly relevant to geopolitics, institutional investing, market feedback, and AI-driven decision-making in complex networks."}, {"doi": "10.3386/w35789", "summary_zh": "\u901a\u8fc7\u5bf9\u516c\u5171\u5b66\u6821\u6559\u6750\u548c\u513f\u7ae5\u6587\u5b66\u4e2d\u60c5\u611f\u5185\u5bb9\u7684\u673a\u5668\u5b66\u4e60\u5206\u6790\uff0c\u53d1\u73b0\u6587\u672c\u63cf\u8ff0\u4e86\u5e7f\u6cdb\u7684\u60c5\u611f\uff0c\u4f46\u56fe\u50cf\u51e0\u4e4e\u53ea\u5c55\u793a\u5feb\u4e50\u548c\u5e73\u9759\uff0c\u6587\u672c\u4e0e\u56fe\u50cf\u4e4b\u95f4\u60c5\u611f\u4e25\u91cd\u4e0d\u5339\u914d\u3002\u8fd9\u79cd\u73b0\u8c61\u5728\u65f6\u95f4\u3001\u60c5\u5883\u548c\u7fa4\u4f53\u4e2d\u6301\u7eed\u5b58\u5728\uff0c\u53ef\u80fd\u6e90\u4e8e\u5e02\u573a\u5bf9\u2018\u79ef\u6781\u2019\u5c01\u9762\u56fe\u50cf\u7684\u504f\u597d\uff0c\u5bfc\u81f4\u513f\u7ae5\u63a5\u89e6\u7684\u60c5\u611f\u8303\u56f4\u88ab\u5e02\u573a\u529b\u91cf\u538b\u7f29\u3002", "summary_en": "Using machine learning and generative AI, we analyze emotional content in public-school textbooks and children's literature. A stark mismatch emerges: text exposes children to a broad emotional range, but images overwhelmingly depict happiness and calm, regardless of emotions described in text. This pattern persists across time, contexts, and identities. Market forces may endogenously shape content to favor positive imagery, narrowing children's emotional exposure.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u5e02\u573a\u673a\u5236\u5982\u4f55\u901a\u8fc7\u5c01\u9762\u56fe\u50cf\u504f\u597d\u5851\u9020\u513f\u7ae5\u60c5\u611f\u8ba4\u77e5\uff0c\u5bf9\u7406\u89e3\u7f51\u7edc\u5185\u5bb9\u4f20\u64ad\u3001\u8d44\u4ea7\u5b9a\u4ef7\u4e2d\u60c5\u7eea\u53cd\u9988\u53ca\u673a\u6784\u6295\u8d44\u8005\u5bf9\u6559\u80b2\u7c7b\u8d44\u4ea7\u7684\u8bc4\u4f30\u5177\u6709\u73b0\u5b9e\u610f\u4e49\uff0c\u5c24\u5176\u5728\u6587\u672c\u5206\u6790\u4e0e\u6781\u7aef\u98ce\u9669\u8bc6\u522b\u4e2d\u63d0\u4f9b\u6d1e\u89c1\u3002", "reason_en": "This study reveals how market forces shape emotional representation in children's media, offering insights into market feedback, sentiment propagation in networks, and asset pricing driven by emotional content\u2014particularly relevant to institutional investors, AI-generated content, and extreme risk assessment in financial and social systems."}, {"doi": "10.3386/w35766", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u957f\u671f\u5229\u7387\u5bf9\u77ed\u671f\u5229\u7387\u7684\u654f\u611f\u6027\u4e3b\u8981\u7531\u5e02\u573a\u53c2\u4e0e\u8005\u5bf9\u672a\u6765\u5229\u7387\u7684\u9884\u671f\u9a71\u52a8\uff0c\u800c\u975e\u98ce\u9669\u6ea2\u4ef7\u3002\u4e0d\u540c\u671f\u9650\u5229\u7387\u9884\u671f\u4e4b\u95f4\u5b58\u5728\u7cfb\u7edf\u6027\u5dee\u5f02\uff0c\u53cd\u6620\u51fa\u4e3b\u89c2\u9884\u671f\u7684\u7ed3\u6784\u6027\u4e0d\u4e00\u81f4\uff0c\u53ef\u80fd\u6e90\u4e8e\u5e02\u573a\u53c2\u4e0e\u8005\u5bf9\u4e0d\u540c\u671f\u9650\u548c\u9884\u6d4b\u671f\u9650\u7684\u9884\u671f\u4e0d\u4e00\u81f4\u3002", "summary_en": "We find that the sensitivity of long-term yields to short-term interest rates is primarily driven by movements in expectations, not risk premia. Systematic wedges exist between long-term and short-maturity yield expectations, indicating structural inconsistencies in subjective expectations across maturities and horizons.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u9884\u671f\u4e0e\u98ce\u9669\u6ea2\u4ef7\u7684\u5206\u79bb\u673a\u5236\uff0c\u6709\u52a9\u4e8e\u7406\u89e3\u5e02\u573a\u53c2\u4e0e\u8005\u5728\u5229\u7387\u671f\u9650\u7ed3\u6784\u4e2d\u7684\u884c\u4e3a\u903b\u8f91\uff0c\u5bf9\u8d44\u4ea7\u5b9a\u4ef7\u3001\u5e02\u573a\u53cd\u9988\u548c\u6781\u7aef\u98ce\u9669\u8bc6\u522b\u5177\u6709\u76f4\u63a5\u610f\u4e49\uff0c\u5c24\u5176\u5bf9\u673a\u6784\u6295\u8d44\u8005\u548c\u6587\u672c\u5206\u6790\u4e2d\u7684\u9884\u671f\u5efa\u6a21\u6709\u53c2\u8003\u4ef7\u503c\u3002", "reason_en": "The paper reveals a clear separation between expectations and risk premia, offering insights into market participants' behavior in term structure pricing. It is relevant to asset pricing, market feedback, and extreme risk identification, particularly for institutional investors and expectation modeling in text analysis and network dynamics."}, {"doi": "10.1093/rfs/hhag082", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u4f01\u4e1a\u503a\u5238\u4e58\u6570\u6548\u5e94\u5728\u5ffd\u7565\u66ff\u4ee3\u6027\u5dee\u5f02\u65f6\u88ab\u4e25\u91cd\u4f4e\u4f30\uff0c\u5b89\u5168\u7ea7\u522b\u548c\u671f\u9650\u8d8a\u957f\u7684\u503a\u5238\uff0c\u5176\u4e58\u6570\u6548\u5e94\u8d8a\u5927\u3002\u7279\u522b\u662f\u9ad8\u6536\u76ca\u503a\u5238\u548c\u5177\u6709\u66f4\u9ad8\u5957\u5229\u98ce\u9669\u7684\u503a\u5238\uff0c\u4e58\u6570\u663e\u8457\u589e\u5f3a\uff0c\u8868\u660e\u66ff\u4ee3\u6027\u7ed3\u6784\u5bf9\u4ef7\u683c\u4f20\u5bfc\u81f3\u5173\u91cd\u8981\u3002", "summary_en": "The study finds that ignoring heterogeneous substitutability leads to a severe underestimation of multipliers. Security-level multipliers are small, while portfolio multipliers are larger and increase with aggregation level, especially for high-yield, long-maturity, and high-arbitrage-risk bonds.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u503a\u5238\u5e02\u573a\u66ff\u4ee3\u6027\u7ed3\u6784\u5bf9\u4ef7\u683c\u4f20\u5bfc\u7684\u6df1\u5c42\u5f71\u54cd\uff0c\u5bf9\u7406\u89e3\u8d44\u4ea7\u5b9a\u4ef7\u3001\u5e02\u573a\u8054\u52a8\u6027\u53ca\u6781\u7aef\u98ce\u9669\u4f20\u64ad\u5177\u6709\u76f4\u63a5\u610f\u4e49\uff0c\u5c24\u5176\u9002\u7528\u4e8e\u673a\u6784\u6295\u8d44\u8005\u548c\u5e76\u8d2d\u51b3\u7b56\u4e2d\u7684\u98ce\u9669\u8bc4\u4f30\u3002", "reason_en": "The paper reveals how heterogeneous substitutability affects price transmission in bond markets, offering insights relevant to asset pricing, market interconnectivity, and extreme risk propagation, especially for institutional investors and M&A risk assessment."}, {"doi": "10.1287/mnsc.2024.04540", "summary_zh": "\u63d0\u51fa\u4e86\u4e00\u79cd\u540d\u4e3a\u2018\u987a\u5e8f\u641c\u7d22\u53d8\u538b\u5668\u2019\uff08SST\uff09\u7684\u6df1\u5ea6\u7ed3\u6784\u8ba1\u91cf\u6a21\u578b\uff0c\u878d\u5408\u6df1\u5ea6\u5b66\u4e60\u4e0e\u6d88\u8d39\u8005\u987a\u5e8f\u641c\u7d22\u7406\u8bba\uff0c\u663e\u5f0f\u5efa\u6a21\u52a8\u6001\u641c\u7d22\u884c\u4e3a\u3002\u6a21\u578b\u5728\u9884\u6d4b\u641c\u7d22\u4e0e\u8d2d\u4e70\u884c\u4e3a\u4e0a\u4f18\u4e8e\u73b0\u6709\u65b9\u6cd5\uff0c\u5e76\u80fd\u6709\u6548\u4f18\u5316\u4ea7\u54c1\u63a8\u8350\u4e0e\u65b0\u5546\u54c1\u63a8\u5e7f\u7b56\u7565\uff0c\u63d0\u5347\u7528\u6237\u4f53\u9a8c\u548c\u6536\u5165\u3002", "summary_en": "We propose the Sequential Search Transformer (SST), a deep structural econometric model integrating deep learning and sequential search theory. SST explicitly models consumer decision-making and outperforms existing models in predicting search and purchase behavior, enabling effective optimization of product recommendations and new product promotion strategies.", "reason_zh": "\u8be5\u7814\u7a76\u5bf9\u7406\u89e3\u6d88\u8d39\u8005\u5728\u7f51\u7edc\u5e73\u53f0\u4e2d\u7684\u52a8\u6001\u51b3\u7b56\u3001\u4e2a\u6027\u5316\u63a8\u8350\u673a\u5236\u53ca\u5e02\u573a\u53cd\u9988\u5177\u6709\u91cd\u8981\u4ef7\u503c\uff0c\u5c24\u5176\u5bf9\u673a\u6784\u6295\u8d44\u8005\u8bc4\u4f30\u5e73\u53f0\u7b56\u7565\u3001AI\u9a71\u52a8\u7684\u8d44\u4ea7\u5b9a\u4ef7\u4e0e\u6781\u7aef\u98ce\u9669\u8bc6\u522b\u3001\u5e76\u8d2d\u4e2d\u7684\u7528\u6237\u884c\u4e3a\u9884\u6d4b\u5177\u6709\u73b0\u5b9e\u610f\u4e49\u3002", "reason_en": "This work provides critical insights into consumer decision dynamics on digital platforms, with direct relevance to institutional investors' strategy evaluation, AI-based asset pricing, extreme risk detection, and user behavior forecasting in mergers and acquisitions."}]}, {"date": "2026-10-02", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "preferences": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "\u7f51\u7edc", "\u5e02\u573a\u53cd\u9988", "AI", "\u6781\u7aef\u98ce\u9669", "\u5e76\u8d2d", "\u8d44\u672c\u6d41\u52a8"], "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.1287/mnsc.2024.08553", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u62e5\u6709\u4e3b\u52a8\u6240\u6709\u6743\uff08\u5982\u5bf9\u51b2\u57fa\u91d1\u548c\u79c1\u52df\u80a1\u6743\uff09\u7684\u516c\u53f8\uff0c\u5176\u5458\u5de5\u5728\u76f8\u540c\u5c97\u4f4d\u4e0a\u7684\u85aa\u916c\u6bd4\u5176\u4ed6\u516c\u53f8\u4f4e2%\u81f34%\uff0c\u5c24\u5176\u662f\u5728\u5e38\u89c4\u6027\u3001\u53ef\u91cf\u5316\u4ea7\u51fa\u548c\u77e5\u8bc6\u5bc6\u96c6\u5ea6\u8f83\u4f4e\u7684\u5c97\u4f4d\u4e0a\u3002\u8fd9\u79cd\u5dee\u5f02\u53cd\u6620\u4e86\u4e3b\u52a8\u6240\u6709\u8005\u901a\u8fc7\u52a0\u5f3a\u7ba1\u7406\u76d1\u7763\u66ff\u4ee3\u85aa\u916c\u6fc0\u52b1\uff0c\u7279\u522b\u662f\u5728\u53ef\u6d4b\u91cf\u548c\u5e38\u89c4\u5de5\u4f5c\u7684\u573a\u666f\u4e2d\u3002", "summary_en": "Firms with active ownership (e.g., hedge funds and private equity) pay 2%\u20134% less for comparable work than other firms, especially in routine, quantifiable, and less knowledge-intensive jobs. This suggests active owners substitute compensation-based incentives with managerial oversight, particularly in measurable and routine settings.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u673a\u6784\u6295\u8d44\u8005\u901a\u8fc7\u6240\u6709\u6743\u7ed3\u6784\u5f71\u54cd\u5458\u5de5\u85aa\u916c\uff0c\u5bf9\u7406\u89e3\u8d44\u672c\u6d41\u52a8\u3001\u5e02\u573a\u53cd\u9988\u53ca\u5458\u5de5\u6fc0\u52b1\u673a\u5236\u5177\u6709\u73b0\u5b9e\u610f\u4e49\uff0c\u5c24\u5176\u5728\u5e76\u8d2d\u3001\u6587\u672c\u5206\u6790\u4e0e\u7f51\u7edc\u4e2d\u53ef\u8bc6\u522b\u4e3b\u52a8\u6240\u6709\u6743\u7684\u4fe1\u53f7\u3002", "reason_en": "The study reveals how institutional ownership shapes employee compensation, offering insights into capital flows, market feedback, and incentive design\u2014particularly relevant to mergers, network analysis, and AI-driven detection of active ownership signals."}, {"doi": "10.1111/jofi.70091", "summary_zh": "\u6b27\u6d32\u591a\u56fd\u4fe1\u7528\u6ce8\u518c\u6570\u636e\u663e\u793a\uff0c\u8de8\u56fd\u94f6\u884c\u76d1\u7ba1\u5728\u91d1\u878d\u538b\u529b\u56fd\u5bb6\u63d0\u5347\u4fe1\u8d37\u4f9b\u7ed9\uff0c\u51cf\u5c11\u5bf9\u9ad8\u98ce\u9669\uff08\u50f5\u5c38\uff09\u4f01\u4e1a\u7684\u8d37\u6b3e\uff0c\u6e90\u4e8e\u56fd\u5bb6\u76d1\u7ba1\u80fd\u529b\u5f31\u3001\u6fc0\u52b1\u5dee\u5f02\u548c\u7834\u4ea7\u6cd5\u4e0d\u5065\u5168\u3002", "summary_en": "Supranational banking supervision increases credit supply in financially stressed countries while reducing lending to the riskiest (zombie) firms, driven by weaker national institutions and lower supervisory abilities.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u8de8\u56fd\u76d1\u7ba1\u5982\u4f55\u5f71\u54cd\u8d44\u672c\u6d41\u52a8\u4e0e\u98ce\u9669\u5206\u914d\uff0c\u5bf9\u7406\u89e3\u5730\u7f18\u653f\u6cbb\u80cc\u666f\u4e0b\u91d1\u878d\u4f53\u7cfb\u6574\u5408\u53ca\u6781\u7aef\u98ce\u9669\u4e0b\u7684\u4fe1\u8d37\u53ef\u5f97\u6027\u5177\u6709\u73b0\u5b9e\u610f\u4e49\u3002", "reason_en": "The study reveals how supranational supervision affects capital flows and risk allocation under geopolitical and economic stress, offering insights into financial stability and extreme risk management in interconnected markets."}, {"doi": "10.1093/rfs/hhag088", "summary_zh": "\u957f\u671f\u501f\u6b3e\u867d\u53ef\u7f13\u89e3\u518d\u6295\u8d44\u98ce\u9669\uff0c\u4f46\u4f1a\u653e\u5927\u4f30\u503c\u6ce2\u52a8\uff0c\u4e0e\u6c47\u7387\u53d8\u52a8\u4ea7\u751f\u4ea4\u4e92\u6548\u5e94\uff0c\u5f62\u6210\u53cc\u91cd\u5f71\u54cd\u3002\u57fa\u91d1\u6295\u8d44\u8005\u4e4b\u95f4\u7684\u6218\u7565\u4e92\u8865\u6027\u5728\u5e02\u573a\u538b\u529b\u4e0b\u4f1a\u52a0\u5267\u6ce2\u52a8\uff0c\u51f8\u663e\u957f\u671f\u501f\u6b3e\u7684\u590d\u6742\u6027\u3002", "summary_en": "Long-term borrowing mitigates rollover risk but amplifies valuation changes that interact with currency movements, revealing a double-edged nature. Strategic complementarities among mutual fund investors exacerbate market stress dynamics.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u671f\u9650\u98ce\u9669\u4e0e\u6c47\u7387\u98ce\u9669\u7684\u4ea4\u4e92\u673a\u5236\uff0c\u5bf9\u7406\u89e3\u65b0\u5174\u5e02\u573a\u503a\u5238\u5e02\u573a\u6ce2\u52a8\u53ca\u6781\u7aef\u98ce\u9669\u4e0b\u7684\u8d44\u672c\u6d41\u52a8\u5177\u6709\u91cd\u8981\u53c2\u8003\u4ef7\u503c\uff0c\u5951\u5408\u2018\u8d44\u4ea7\u5b9a\u4ef7\u2019\u3001\u2018\u6781\u7aef\u98ce\u9669\u2019\u548c\u2018\u5e02\u573a\u53cd\u9988\u2019\u4e3b\u9898\u3002", "reason_en": "The paper reveals the interaction between duration and exchange rate risks in asset pricing, offering critical insights into volatility and systemic stress in emerging market bond flows and portfolio dynamics, relevant to asset pricing, market feedback, and extreme risk."}, {"doi": "10.3386/w35829", "summary_zh": "\u6a21\u578b\u663e\u793a\uff0c\u5728\u8fdb\u53e3\u5546\u6570\u91cf\u5c11\u3001\u5e02\u573a\u529b\u91cf\u5f3a\u7684\u80cc\u666f\u4e0b\uff0c\u6700\u4f18\u5173\u7a0e\u4e3a\u8d1f\u503c\uff0c\u4e14\u968f\u56fd\u5bb6\u89c4\u6a21\u6269\u5927\u800c\u4e0b\u964d\u3002\u8fd9\u8868\u660e\u8d38\u6613\u653f\u7b56\u53ef\u80fd\u5e76\u975e\u65e8\u5728\u4fdd\u62a4\u56fd\u5185\u4ea7\u4e1a\uff0c\u800c\u662f\u52a0\u5267\u4e86\u8d44\u6e90\u914d\u7f6e\u626d\u66f2\u3002", "summary_en": "The optimal tariff is negative and decreases with country size, indicating that trade policies may exacerbate distortions rather than correct them, especially when importers are few and have high market power.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u5e02\u573a\u7ed3\u6784\u4e0e\u6700\u4f18\u5173\u7a0e\u7684\u53cd\u76f4\u89c9\u5173\u7cfb\uff0c\u5bf9\u5730\u7f18\u653f\u6cbb\u4e2d\u7684\u8d38\u6613\u653f\u7b56\u5236\u5b9a\u3001\u8d44\u672c\u6d41\u52a8\u53ca\u5e02\u573a\u53cd\u9988\u673a\u5236\u5177\u6709\u91cd\u8981\u53c2\u8003\u4ef7\u503c\u3002", "reason_en": "This paper reveals a counterintuitive relationship between market structure and optimal tariffs, offering valuable insights into trade policy design in geopolitical contexts, capital flows, and market feedback mechanisms."}, {"doi": "10.1111/jofi.70092", "summary_zh": "\u5f53\u6d88\u8d39\u52a8\u6001\u5728\u4e0d\u540c\u9636\u6bb5\u53d1\u751f\u8f6c\u53d8\u65f6\uff0c\u503a\u5238\u4e0e\u80a1\u7968\u7684\u76f8\u5173\u6027\u51fa\u73b0\u6b63\u8d1f\u8f6c\u6362\uff0c\u8fd9\u4e00\u73b0\u8c61\u57281990\u5e74\u4ee3\u672b\u671f\u53d1\u751f\uff0c\u4ece\u771f\u5b9e\u6d88\u8d39\u52a8\u6001\u89d2\u5ea6\u89e3\u91ca\u4e86\u8d44\u4ea7\u4ef7\u683c\u7684\u76f8\u5173\u6027\u53d8\u5316\u3002", "summary_en": "A shift in consumption dynamics causes a sign change in bond-stock correlation, explaining the observed negative correlation in the late 1990s from a real consumption perspective.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u5730\u7f18\u653f\u6cbb\u6ce2\u52a8\u3001\u5e02\u573a\u53cd\u9988\u4e0e\u6781\u7aef\u98ce\u9669\u4e0b\u7684\u8d44\u4ea7\u5b9a\u4ef7\u673a\u5236\uff0c\u5bf9\u7406\u89e3\u8d44\u672c\u6d41\u52a8\u3001\u5e76\u8d2d\u51b3\u7b56\u53ca\u7f51\u7edc\u7ed3\u6784\u4e2d\u7684\u98ce\u9669\u4f20\u5bfc\u5177\u6709\u73b0\u5b9e\u610f\u4e49\u3002", "reason_en": "The findings offer insights into asset pricing under macroeconomic shifts, relevant to market feedback, capital flows, extreme risks, and network dynamics in financial systems."}]}, {"date": "2026-10-01", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "preferences": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "\u7f51\u7edc", "\u5e02\u573a\u53cd\u9988", "AI", "\u6781\u7aef\u98ce\u9669", "\u5e76\u8d2d", "\u8d44\u672c\u6d41\u52a8"], "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.3386/w35796", "summary_zh": "\u8be5\u7814\u7a76\u57fa\u4e8eCPS\u5fae\u89c2\u6570\u636e\uff0c\u9996\u6b21\u8bc4\u4f30\u4e86\u4eba\u5de5\u667a\u80fd\u5bf92026\u5e74\u65b0\u6bd5\u4e1a\u5927\u5b66\u751f\u5c31\u4e1a\u7684\u5f71\u54cd\u3002\u7ed3\u679c\u663e\u793a\uff0c2026\u5e74\u590f\u5b63\u5931\u4e1a\u7387\u672a\u663e\u8457\u4e0a\u5347\uff0c\u4e0e\u5f80\u5e74\u53ca\u66f4\u5e74\u957f\u7fa4\u4f53\u76f8\u6bd4\u65e0\u660e\u663e\u5dee\u5f02\u3002\u7eb3\u5165\u2018\u60f3\u8981\u5de5\u4f5c\u4f46\u672a\u5c31\u4e1a\u2019\u7fa4\u4f53\u540e\uff0c\u5931\u4e1a\u7387\u7565\u6709\u4e0a\u5347\uff0c\u4f46\u672a\u57282026\u5e74\u51fa\u73b0\u663e\u8457\u589e\u52a0\u3002\u7814\u7a76\u53d1\u73b0\u8fdc\u7a0b\u5de5\u4f5c\u53ef\u90e8\u5206\u7f13\u89e3AI\u5bf9\u5c31\u4e1a\u7684\u6f5c\u5728\u5f71\u54cd\uff0c\u4f46\u672a\u53d1\u73b0AI\u66b4\u9732\u4e0e\u5931\u4e1a\u7387\u4e4b\u95f4\u663e\u8457\u5173\u8054\u3002", "summary_en": "This study uses CPS microdata to assess AI's early impact on recent college graduates' employment in 2026. Results show no significant spike in unemployment during summer 2026 compared to prior years or older cohorts. Including 'wanting a job' individuals slightly raises the unemployment rate, but no significant increase is found in 2026. A positive association is observed between remote work availability and employment stability, suggesting remote work may mitigate AI-related employment effects.", "reason_zh": "\u8be5\u7814\u7a76\u4e3a\u7406\u89e3AI\u5bf9\u65b0\u5174\u52b3\u52a8\u529b\u7fa4\u4f53\u7684\u5c31\u4e1a\u5f71\u54cd\u63d0\u4f9b\u4e86\u5b9e\u8bc1\u4f9d\u636e\uff0c\u5bf9\u8d44\u4ea7\u5b9a\u4ef7\u4e2d\u6280\u672f\u98ce\u9669\u7684\u8bc4\u4f30\u3001\u673a\u6784\u6295\u8d44\u8005\u5728\u5e76\u8d2d\u4e0e\u8d44\u672c\u6d41\u52a8\u4e2d\u7684\u51b3\u7b56\u5177\u6709\u76f4\u63a5\u53c2\u8003\u4ef7\u503c\uff0c\u540c\u65f6\u63ed\u793a\u4e86\u7f51\u7edc\u7ed3\u6784\u4e0e\u5e02\u573a\u53cd\u9988\u5728AI\u51b2\u51fb\u4e0b\u7684\u52a8\u6001\u54cd\u5e94\u673a\u5236\u3002", "reason_en": "The study offers empirical insight into AI's impact on young workers, relevant to asset pricing, institutional investor strategies in mergers and capital flows, and the dynamics of market feedback in AI-driven labor market disruptions."}, {"doi": "10.3386/w35828", "summary_zh": "\u8be5\u7814\u7a76\u63a2\u8ba8\u4e86\u53cc\u7528\u9014AI\u670d\u52a1\u4e2d\u63d0\u4f9b\u5546\u7684\u8d23\u4efb\u5206\u914d\u95ee\u9898\u3002\u9002\u5ea6\u8d23\u4efb\u53ef\u63d0\u5347\u798f\u5229\uff0c\u4f46\u8fc7\u9ad8\u8d23\u4efb\u4f1a\u524a\u5f31\u9632\u5fa1\u5e76\u589e\u52a0\u653b\u51fb\u8005\u5229\u6da6\u3002\u5728\u5145\u5206\u7ade\u4e89\u4e0b\uff0c\u6700\u4f18\u8d23\u4efb\u4e0b\u964d\uff0c\u4e14\u5f53\u751f\u4ea7\u6027\u7528\u9014\u53d7\u4fdd\u62a4\u65f6\uff0c\u666e\u904d\u9632\u5fa1\u53ef\u4f7f\u8d23\u4efb\u673a\u5236\u5197\u4f59\u3002\u5784\u65ad\u4e0b\u8d23\u4efb\u5b58\u5728\u9608\u503c\uff0c\u800c\u9ad8\u7528\u6237\u6570\u91cf\u4e0b\u96f6\u8d23\u4efb\u53ef\u80fd\u6700\u4f18\u3002\u7814\u7a76\u4e3a\u7f51\u7edc\u5b89\u5168\u653f\u7b56\u548cAI\u6cbb\u7406\u63d0\u4f9b\u4e86\u7406\u8bba\u652f\u6301\u3002", "summary_en": "This paper examines liability for AI providers whose services enable both cyberattacks and defenses. Moderate liability improves welfare by balancing defensive incentives and productive exclusion. In competitive markets, optimal liability decreases, and universal guarding becomes socially optimal when productive uses are protected. Under monopoly, liability has a threshold; with many productive users, zero liability may be optimal. The study provides theoretical insights for AI liability and cybersecurity policy.", "reason_zh": "\u8be5\u7814\u7a76\u76f4\u63a5\u5173\u8054\u5730\u7f18\u653f\u6cbb\u4e2d\u7684\u7f51\u7edc\u5b89\u5168\u535a\u5f08\u3001\u6781\u7aef\u98ce\u9669\u4e0e\u8d44\u672c\u6d41\u52a8\uff0c\u5e2e\u52a9\u673a\u6784\u6295\u8d44\u8005\u8bc6\u522bAI\u76f8\u5173\u8d44\u4ea7\u7684\u7cfb\u7edf\u6027\u98ce\u9669\uff0c\u5bf9\u7406\u89e3\u7f51\u7edc\u5bf9\u6297\u3001\u5e02\u573a\u53cd\u9988\u548c\u5e76\u8d2d\u4e2d\u7684\u6280\u672f\u6743\u529b\u7ed3\u6784\u5177\u6709\u91cd\u8981\u53c2\u8003\u4ef7\u503c\u3002", "reason_en": "The study directly addresses dual-use AI in geopolitical and security contexts, enabling institutional investors to assess systemic risks in AI-related assets. It informs understanding of network dynamics, market feedback, and technology-driven risks in mergers and acquisitions."}, {"doi": "10.1093/restud/rdag099", "summary_zh": "\u5b9e\u9a8c\u663e\u793a\uff0c\u96c6\u4f53\u9000\u51fa\uff08\u5982\u96c6\u4f53\u7981\u7528TikTok\uff09\u5f15\u53d1\u7684\u66ff\u4ee3\u6548\u5e94\u663e\u8457\u5f3a\u4e8e\u4e2a\u4f53\u9000\u51fa\uff0c\u8868\u660e\u4e2a\u4f53\u66ff\u4ee3\u884c\u4e3a\u65e0\u6cd5\u51c6\u786e\u53cd\u6620\u7f51\u7edc\u5546\u54c1\u5e02\u573a\u7684\u8fb9\u754c\u3002\u5185\u5bb9\u4f9b\u7ed9\u53d8\u5316\u4e0e\u793e\u4f1a\u534f\u8c03\u5728\u5176\u4e2d\u8d77\u5173\u952e\u4f5c\u7528\uff0c\u5e02\u573a\u5b9a\u4e49\u9700\u57fa\u4e8e\u96c6\u4f53\u884c\u4e3a\u3002\u8be5\u53d1\u73b0\u5bf9\u7406\u89e3\u5e73\u53f0\u7ecf\u6d4e\u3001\u5730\u7f18\u653f\u6cbb\u4e2d\u7684\u8d44\u672c\u6d41\u52a8\u4e0e\u7f51\u7edc\u63a7\u5236\u5177\u6709\u73b0\u5b9e\u610f\u4e49\u3002", "summary_en": "The experiment shows collective deactivation (e.g., a TikTok ban) induces significantly stronger substitution to alternatives than individual deactivation, indicating individual-level substitution estimates are unreliable for market definition. Content shifts and social coordination drive market dynamics, highlighting the need for collective behavior in defining network markets.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u7f51\u7edc\u5546\u54c1\u5e02\u573a\u5b9a\u4e49\u7684\u96c6\u4f53\u6027\u7279\u5f81\uff0c\u5bf9\u673a\u6784\u6295\u8d44\u8005\u8bc4\u4f30\u6570\u5b57\u8d44\u4ea7\u4f30\u503c\u3001\u7406\u89e3\u5e73\u53f0\u95f4\u8d44\u672c\u6d41\u52a8\u4e0e\u5730\u7f18\u653f\u6cbb\u535a\u5f08\u5177\u6709\u76f4\u63a5\u4ef7\u503c\uff0c\u5c24\u5176\u5728\u5e76\u8d2d\u4e0e\u6781\u7aef\u98ce\u9669\u60c5\u5883\u4e0b\u6709\u52a9\u4e8e\u8bc6\u522b\u771f\u5b9e\u5e02\u573a\u8fb9\u754c\u3002", "reason_en": "The study reveals the collective nature of market definition in network goods, providing actionable insights for institutional investors in digital asset valuation, capital flows, and geopolitical platform competition\u2014especially under merger scenarios and extreme risk conditions."}, {"doi": "10.1111/jofi.70073", "summary_zh": "\u4f01\u4e1a\u4e3b\u52a8\u9009\u62e9\u62ab\u9732\u65f6\u95f4\u5bfc\u81f4\u80a1\u7968\u56de\u62a5\u7684\u6761\u4ef6\u98ce\u9669\u6ea2\u4ef7\u5347\u9ad8\uff0c\u5e76\u5448\u73b0\u8d1f\u6f02\u79fb\u540e\u6b63\u8df3\u53d8\u7684\u6a21\u5f0f\u3002\u62ab\u9732\u524d\u03b2\u503c\u4e0a\u5347\u901f\u5ea6\u8d85\u8fc7\u98ce\u9669\u6ea2\u4ef7\uff0c\u4f7fCAPM\u7684\u03b1\u503c\u8f6c\u8d1f\uff0c\u8868\u660e\u516c\u544a\u65f6\u95f4\u5177\u6709\u5e02\u573a\u4fe1\u53f7\u4f5c\u7528\u3002", "summary_en": "Discretionary announcement timing increases conditional risk premia and produces negative drifts followed by positive jumps in stock returns. Betas rise faster than risk premia before disclosures, leading to negative CAPM alphas, indicating announcement timing serves as a market signal.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u4fe1\u606f\u62ab\u9732\u65f6\u673a\u5bf9\u4f01\u4e1a\u4ef7\u503c\u4e0e\u5e02\u573a\u53cd\u5e94\u7684\u5f71\u54cd\uff0c\u5bf9\u8d44\u4ea7\u5b9a\u4ef7\u3001\u673a\u6784\u6295\u8d44\u8005\u51b3\u7b56\u3001\u5e02\u573a\u53cd\u9988\u53ca\u6781\u7aef\u98ce\u9669\u8bc6\u522b\u5177\u6709\u73b0\u5b9e\u610f\u4e49\uff0c\u5c24\u5176\u5728\u5e76\u8d2d\u3001\u8d44\u672c\u6d41\u52a8\u548c\u7f51\u7edc\u4fe1\u606f\u4f20\u64ad\u4e2d\u5177\u6709\u5e94\u7528\u4ef7\u503c\u3002", "reason_en": "The study reveals how announcement timing influences asset pricing and market reactions, offering practical insights for institutional investors, capital flows, market feedback, and extreme risk identification, especially in mergers, network dynamics, and text-based analysis."}, {"doi": "10.1287/mnsc.2025.01449", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u4e2d\u56fd\u4f20\u7edf\u6587\u5316\u4e2d\u7684\u6570\u5b57\u8ff7\u4fe1\uff08\u59828\u4e3a\u5409\u7965\u30014\u4e3a\u4e0d\u7965\uff09\u663e\u8457\u5f71\u54cd\u80a1\u7968\u3001\u503a\u5238\u3001\u5916\u6c47\u548c\u5546\u54c1\u671f\u8d27\u5e02\u573a\u7684\u4ef7\u683c\u884c\u4e3a\u3002\u8be5\u73b0\u8c61\u666e\u904d\u5b58\u5728\u4e8e\u5e02\u573a\u4e2d\uff0c\u7531\u7cbe\u660e\u6295\u8d44\u8005\u5c06\u5176\u4f5c\u4e3a\u4e0d\u786e\u5b9a\u6027\u951a\u70b9\u53ca\u666e\u901a\u6295\u8d44\u8005\u7684\u8fc7\u5ea6\u4e50\u89c2\u9a71\u52a8\uff0c\u5728\u7531\u666e\u901a\u6295\u8d44\u8005\u4e3b\u5bfc\u7684\u5e02\u573a\u4e2d\u8868\u73b0\u4e3a\u8d44\u4ea7\u9ad8\u4f30\u3002", "summary_en": "The study finds that numerological superstitions in Chinese culture\u2014such as the digit 8 being lucky and 4 unlucky\u2014significantly affect asset prices across stock, bond, FX, and commodity futures markets. This effect is driven by sophisticated investors using superstition as an anchor to manage ambiguity and by unsophisticated investors' overoptimism, leading to overpricing in markets dominated by the latter.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u6587\u5316\u56e0\u7d20\u5bf9\u91d1\u878d\u5e02\u573a\u5b9a\u4ef7\u7684\u975e\u7406\u6027\u5f71\u54cd\uff0c\u6709\u52a9\u4e8e\u7406\u89e3\u5e02\u573a\u60c5\u7eea\u3001\u6781\u7aef\u98ce\u9669\u53ca\u6295\u8d44\u8005\u884c\u4e3a\u5dee\u5f02\uff0c\u5bf9\u673a\u6784\u6295\u8d44\u8005\u5728\u4e9a\u6d32\u5e02\u573a\u4e2d\u7684\u51b3\u7b56\u4e0e\u98ce\u9669\u63a7\u5236\u5177\u6709\u73b0\u5b9e\u610f\u4e49\u3002", "reason_en": "This paper reveals how cultural superstitions influence financial markets, providing insight into irrational pricing, market sentiment, and investor behavior differences, highly relevant for institutional investors managing risk and making decisions in Asian markets."}]}, {"date": "2026-09-30", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "preferences": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "\u7f51\u7edc", "\u5e02\u573a\u53cd\u9988", "AI", "\u6781\u7aef\u98ce\u9669", "\u5e76\u8d2d", "\u8d44\u672c\u6d41\u52a8"], "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.3386/w35802", "summary_zh": "\u672c\u6587\u901a\u8fc7\u5206\u6790\u610f\u5927\u5229\u2018\u5357\u90e8\u53d1\u5c55\u57fa\u91d1\u2019\u548c\u7f8e\u56fd\u2018\u963f\u6ce2\u7f57\u767b\u6708\u8ba1\u5212\u2019\u4e24\u4e2a\u5386\u53f2\u6848\u4f8b\uff0c\u63d0\u51fa\u2018\u4ea7\u4e1a\u653f\u7b56\u613f\u666f\u2019\u6982\u5ff5\uff0c\u6307\u51fa\u4ea7\u4e1a\u653f\u7b56\u6e90\u4e8e\u653f\u6cbb\u9886\u5bfc\u8005\u7684\u957f\u671f\u6218\u7565\u76ee\u6807\u800c\u975e\u7ecf\u6d4e\u8bca\u65ad\u3002\u7814\u7a76\u53d1\u73b0\uff0c\u613f\u666f\u8bbe\u5b9a\u7684\u6846\u67b6\u51b3\u5b9a\u4e86\u653f\u7b56\u6210\u8d25\u7684\u8bc4\u5224\u6807\u51c6\uff0c\u5305\u62ec\u5931\u8d25\u5b9a\u4e49\u4e0e\u65f6\u95f4\u671f\u9650\u3002\u6708\u7403\u8ba1\u5212\u56e0\u76ee\u6807\u660e\u786e\u800c\u6210\u529f\uff0c\u5357\u90e8\u57fa\u91d1\u56e0\u76ee\u6807\u5f00\u653e\u4e14\u6301\u7eed\u5931\u8d25\u800c\u6700\u7ec8\u5931\u6548\u3002", "summary_en": "This paper analyzes two historical cases\u2014the Cassa per il Mezzogiorno in Italy and Kennedy's Moonshot in the U.S.\u2014to introduce the concept of 'industrial policy vision,' showing that industrial policies arise from political projects rather than economic diagnoses. The study finds that the vision sets the framework for evaluating policy success, including definitions of failure and time limits. The Moonshot succeeded due to a bounded vision, while the Cassa failed due to an open-ended vision that accumulated setbacks.", "reason_zh": "\u8be5\u7814\u7a76\u5bf9\u7406\u89e3\u5730\u7f18\u653f\u6cbb\u80cc\u666f\u4e0b\u7684\u79d1\u6280\u7ade\u4e89\u3001\u673a\u6784\u6295\u8d44\u8005\u7684\u6218\u7565\u5e03\u5c40\u53ca\u653f\u7b56\u53ef\u6301\u7eed\u6027\u5177\u6709\u91cd\u8981\u4ef7\u503c\uff0c\u63ed\u793a\u4e86\u4ea7\u4e1a\u653f\u7b56\u80cc\u540e\u7684\u6df1\u5c42\u653f\u6cbb\u903b\u8f91\uff0c\u6709\u52a9\u4e8e\u8bc4\u4f30\u5f53\u524d\u5168\u7403\u5e02\u573a\u4e2d\u7684\u6781\u7aef\u98ce\u9669\u4e0e\u8d44\u672c\u6d41\u52a8\u8d8b\u52bf\u3002", "reason_en": "This paper is relevant to geopolitics, institutional investment, and market dynamics, revealing the political foundations of industrial policy and offering insights into strategic capital flows, extreme risks, and policy endurance in global tech competition."}, {"doi": "10.3386/w35810", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u7ae5\u5e74\u90bb\u5c45\u7684\u804c\u4e1a\u4f1a\u663e\u8457\u5f71\u54cd\u4e2a\u4f5330\u5e74\u540e\u7684\u804c\u4e1a\u9009\u62e9\uff0c\u4e0e\u90bb\u5c45\u804c\u4e1a\u76f8\u5173\u7684\u66b4\u9732\u7a0b\u5ea6\u8d8a\u9ad8\uff0c\u804c\u4e1a\u9009\u62e9\u6982\u7387\u63d0\u5347\u7ea610%\u3002\u9ad8\u6536\u5165\u6216\u9ad8\u5b66\u5386\u90bb\u5c45\u7684\u5f71\u54cd\u529b\u66f4\u6301\u4e45\uff0c\u5e26\u6765\u663e\u8457\u7684\u6536\u5165\u548c\u6559\u80b2\u63d0\u5347\u3002\u8fd9\u8868\u660e\u90bb\u91cc\u7f51\u7edc\u5728\u4ee3\u9645\u7ecf\u6d4e\u6d41\u52a8\u4e2d\u626e\u6f14\u5173\u952e\u89d2\u8272\u3002", "summary_en": "The study finds that childhood neighbors significantly influence occupational choices decades later, increasing the probability of working in the same occupation by about 10%. Exposure to high-income or highly educated neighbors leads to lasting economic gains in income and education, suggesting that neighborhood networks play a key role in intergenerational mobility.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u793e\u4f1a\u7f51\u7edc\u5bf9\u4e2a\u4f53\u804c\u4e1a\u4e0e\u6536\u5165\u7684\u957f\u671f\u5f71\u54cd\uff0c\u5bf9\u7406\u89e3\u5e02\u573a\u4e2d\u7684\u7f51\u7edc\u6548\u5e94\u3001\u8d44\u672c\u6d41\u52a8\u4e0e\u6781\u7aef\u98ce\u9669\u4f20\u64ad\u5177\u6709\u73b0\u5b9e\u610f\u4e49\uff0c\u5c24\u5176\u5728\u5e76\u8d2d\u51b3\u7b56\u3001\u673a\u6784\u6295\u8d44\u8005\u884c\u4e3a\u548c\u6587\u672c\u5206\u6790\u4e2d\u53cd\u6620\u793e\u4f1a\u7ed3\u6784\u7684\u9690\u6027\u529b\u91cf\u3002", "reason_en": "This research reveals how social networks shape long-term occupational and income outcomes, offering relevance to network effects, capital flows, and extreme risk propagation in markets, particularly in merger decisions, institutional investor behavior, and text-based social structure analysis."}, {"doi": "10.3386/w35808", "summary_zh": "\u5229\u7528\u536b\u661f\u6570\u636e\u6784\u5efa\u4e86\u7f8e\u56fd\u8fdb\u53e3\u822a\u7ebf\u7684\u5bb9\u91cf\u6307\u6807\uff0c\u53d1\u73b0\u822a\u8fd0\u4e2d\u65ad\u5728\u5b9e\u9645\u53d1\u751f\u524d\u6570\u6708\u5373\u5df2\u5bfc\u81f4\u8fd0\u529b\u635f\u5931\uff0c2021\u5e74\u897f\u6d77\u5cb8\u5371\u673a\u548c2023-2024\u5e74\u7ea2\u6d77\u88ad\u51fb\u5206\u522b\u9020\u62100.69%\u548c0.35%\u7684\u4ea7\u51fa\u635f\u5931\u3002\u6d77\u519b\u62a4\u822a\u5e26\u67650.04%-0.08%\u6536\u76ca\uff0c\u8d22\u653f\u6210\u672c\u4e3a0.02%\u3002\u5173\u7a0e\u53ef\u7f13\u89e3\u62e5\u5835\uff0c\u90e8\u5206\u62b5\u6d88\u4f20\u7edf\u798f\u5229\u635f\u5931\u3002", "summary_en": "Using satellite data, the paper constructs route-level capacity measures and finds disruptions cause pre-visibility utilization losses. The 2021 West Coast crisis and 2023\u20132024 Red Sea attacks led to 0.69% and 0.35% output losses respectively. Naval protection yields 0.04\u20130.08% benefits at a 0.02% fiscal cost. Tariffs reduce congestion and partially offset conventional welfare costs.", "reason_zh": "\u7814\u7a76\u63ed\u793a\u5730\u7f18\u653f\u6cbb\u51b2\u7a81\u5bf9\u4f9b\u5e94\u94fe\u548c\u5e02\u573a\u53cd\u9988\u7684\u76f4\u63a5\u5f71\u54cd\uff0c\u6709\u52a9\u4e8e\u673a\u6784\u6295\u8d44\u8005\u8bc4\u4f30\u6781\u7aef\u98ce\u9669\u4e0b\u7684\u8d44\u672c\u6d41\u52a8\u4e0e\u8d44\u4ea7\u5b9a\u4ef7\uff0c\u4e3a\u5e76\u8d2d\u4e0e\u7f51\u7edc\u7ed3\u6784\u7a33\u5b9a\u6027\u63d0\u4f9b\u51b3\u7b56\u4f9d\u636e\u3002", "reason_en": "The study reveals direct impacts of geopolitical conflicts on supply chains and market feedback, aiding institutional investors in assessing capital flows and asset pricing under extreme risks, with implications for mergers, network resilience, and market responses."}, {"doi": "10.3386/w35819", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0cLRP\u6295\u4fdd\u884c\u4e3a\u4e0e\u671f\u6743\u5230\u671f\u65e5\u9ad8\u5ea6\u5173\u8054\uff0c\u4f46\u5b9e\u9645\u6536\u76ca\u6709\u9650\uff0c\u4e14\u5728\u4f4e\u6ce2\u52a8\u73af\u5883\u4e0b\u96c6\u4e2d\uff0c\u7ec4\u5408\u7b56\u7565\u53cd\u800c\u52a0\u5267\u4e0b\u884c\u98ce\u9669\u3002\u8fd9\u8868\u660e\u65f6\u95f4\u805a\u96c6\u53ef\u80fd\u6e90\u4e8e\u5e38\u89c4\u5957\u671f\u4fdd\u503c\uff0c\u800c\u975e\u7ecf\u6d4e\u610f\u4e49\u4e0a\u7684\u8865\u8d34\u5957\u5229\uff0c\u5bf9\u516c\u5171\u8865\u8d34\u653f\u7b56\u6548\u7387\u63d0\u51fa\u8d28\u7591\u3002", "summary_en": "The paper finds that LRP endorsement clusters around option expiration dates, but realized gains are small and concentrated in low-volatility environments. Combined strategies worsen downside outcomes, suggesting observed timing reflects routine hedging, not meaningful subsidy capture.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u5730\u7f18\u653f\u6cbb\u4e0e\u8d44\u672c\u6d41\u52a8\u4e2d\u653f\u7b56\u8865\u8d34\u7684\u6f5c\u5728\u98ce\u9669\uff0c\u4e0e\u673a\u6784\u6295\u8d44\u8005\u5bf9\u8d44\u4ea7\u5b9a\u4ef7\u3001\u5e02\u573a\u53cd\u9988\u548c\u6781\u7aef\u98ce\u9669\u7684\u5173\u5207\u5bc6\u5207\u76f8\u5173\uff0c\u4e3a\u8bc4\u4f30\u653f\u7b56\u652f\u6301\u8ba1\u5212\u7684\u7ecf\u6d4e\u5408\u7406\u6027\u63d0\u4f9b\u5b9e\u8bc1\u4f9d\u636e\u3002", "reason_en": "This study reveals risks in policy subsidies relevant to institutional investors' concerns about asset pricing, market feedback, and extreme risks, providing empirical evidence on the economic rationale of government support programs."}, {"doi": "10.3386/w35830", "summary_zh": "\u6587\u7ae0\u6307\u51fa\uff0c\u5e94\u5bf9\u6c14\u5019\u53d8\u5316\u5e94\u91c7\u7528\u9700\u6c42\u4fa7\u4e0e\u4f9b\u7ed9\u4fa7\u76f8\u7ed3\u5408\u7684\u653f\u7b56\u7ec4\u5408\uff0c\u800c\u975e\u5355\u4e00\u8def\u5f84\u3002\u9700\u6c42\u4fa7\u78b3\u5b9a\u4ef7\u53ef\u51cf\u5c11\u6392\u653e\u4f46\u53ef\u80fd\u5f15\u53d1\u5916\u6ea2\uff1b\u4f9b\u7ed9\u4fa7\u78b3\u63d0\u53d6\u5b9a\u4ef7\u53ef\u62b5\u6d88\u8fd9\u4e00\u6548\u5e94\u3002\u73b0\u5b9e\u4e2d\u4f9b\u7ed9\u4fa7\u653f\u7b56\u591a\u4e3a\u9650\u5236\u6027\u63aa\u65bd\uff0c\u6548\u7387\u4f4e\u4e0b\u3002\u5efa\u8bae\u52a0\u5f3a\u6e05\u6d01\u80fd\u6e90\u57fa\u7840\u8bbe\u65bd\u89c4\u5212\u4e0e\u7814\u53d1\u652f\u6301\uff0c\u4ee5\u63d0\u5347\u51cf\u6392\u6548\u679c\uff0c\u5e76\u5173\u6ce8\u5176\u5168\u7403\u5206\u914d\u5f71\u54cd\u3002", "summary_en": "The paper advocates a combined policy approach integrating demand-side carbon pricing and supply-side extraction pricing to address emission leakage. While practical supply-side policies are often restrictive and inefficient, reforms to transmission planning and clean energy R&D are essential for effective global emissions reduction and equitable outcomes.", "reason_zh": "\u8be5\u7814\u7a76\u5bf9\u5730\u7f18\u653f\u6cbb\u4e2d\u7684\u80fd\u6e90\u4f9d\u8d56\u3001\u8d44\u4ea7\u5b9a\u4ef7\u4e2d\u7684\u6c14\u5019\u98ce\u9669\u53ca\u673a\u6784\u6295\u8d44\u8005\u7684\u7eff\u8272\u6295\u8d44\u51b3\u7b56\u5177\u6709\u91cd\u8981\u53c2\u8003\u4ef7\u503c\uff0c\u5c24\u5176\u5728\u8bc4\u4f30\u5e76\u8d2d\u3001\u8d44\u672c\u6d41\u52a8\u4e0e\u6781\u7aef\u98ce\u9669\u65f6\u63d0\u4f9b\u653f\u7b56\u7ed3\u6784\u5206\u6790\u6846\u67b6\u3002", "reason_en": "This work is relevant to geopolitical energy dependencies, asset pricing under climate risk, and institutional investors' green investment decisions, particularly in assessing merger activity, capital flows, and extreme risks through structural policy analysis."}]}, {"date": "2026-09-29", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "preferences": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "\u7f51\u7edc", "\u5e02\u573a\u53cd\u9988", "AI", "\u6781\u7aef\u98ce\u9669", "\u5e76\u8d2d", "\u8d44\u672c\u6d41\u52a8"], "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.3386/w35793", "summary_zh": "\u8be5\u7814\u7a76\u57fa\u4e8e\u5b9e\u65f6\u91d1\u878d\u5e02\u573a\u6570\u636e\uff0c\u91cf\u5316\u4e86\u4eba\u5de5\u667a\u80fd\u5bf9\u8f6f\u4ef6\u5de5\u7a0b\u751f\u4ea7\u529b\u53ca\u5b8f\u89c2\u7ecf\u6d4e\u7684\u5f71\u54cd\u30022022\u5e7411\u6708\u81f32025\u5e7412\u6708\uff0cAI\u4f7f\u8f6f\u4ef6\u5de5\u7a0b\u751f\u4ea7\u529b\u63d0\u5347\u76f8\u5f53\u4e8e\u6c38\u4e45\u602732.6%\u7684\u589e\u957f\uff0c\u5e26\u52a8GDP\u589e\u957f3.6%\uff08\u8003\u8651\u7814\u53d1\u6548\u7387\u63d0\u5347\u65f6\u8fbe6.5%\uff09\u3002\u81f32026\u5e74\u4e2d\u671f\uff0c\u968f\u7740\u7f16\u7801\u4ee3\u7406\u6280\u672f\u5feb\u901f\u53d1\u5c55\uff0c\u8be5\u5f71\u54cd\u5df2\u8d85\u8fc72025\u5e74\u6c34\u5e73\u3002", "summary_en": "This paper uses real-time financial market data to quantify AI's impact on software engineering productivity and macroeconomic outcomes. From November 2022 to December 2025, AI increased software engineering productivity by an equivalent of a permanent 32.6% gain, translating to 3.6% GDP growth (6.5% with R&D productivity gains). By mid-2026, with rapid advances in coding agents, the impact has more than doubled.", "reason_zh": "\u7814\u7a76\u63ed\u793a\u4e86AI\u5bf9\u8f6f\u4ef6\u5de5\u7a0b\u4e0eGDP\u7684\u76f4\u63a5\u4f5c\u7528\uff0c\u5bf9\u7406\u89e3\u6280\u672f\u9a71\u52a8\u4e0b\u7684\u8d44\u4ea7\u5b9a\u4ef7\u3001\u8d44\u672c\u6d41\u52a8\u53ca\u673a\u6784\u6295\u8d44\u8005\u51b3\u7b56\u5177\u6709\u91cd\u8981\u53c2\u8003\u4ef7\u503c\uff0c\u5c24\u5176\u5728\u5730\u7f18\u653f\u6cbb\u4e0e\u7f51\u7edc\u6280\u672f\u7ade\u4e89\u80cc\u666f\u4e0b\u3002", "reason_en": "The paper reveals AI's direct impact on software productivity and GDP, offering actionable insights for asset pricing, capital allocation, and institutional investor decisions amid technological disruption and network competition."}, {"doi": "10.3386/w35806", "summary_zh": "\u8bba\u6587\u6307\u51fa\u6df1\u5ea6\u5b66\u4e60\u672c\u8d28\u4e0a\u5c5e\u4e8e\u6295\u5f71\u6cd5\u8303\u7574\uff0c\u800c\u975e\u7ecf\u6d4e\u6a21\u578b\u6c42\u89e3\u7684\u65b0\u8303\u5f0f\uff0c\u5f3a\u8c03\u5e94\u6839\u636e\u6a21\u578b\u7ef4\u5ea6\u9009\u62e9\u5408\u9002\u8fd1\u4f3c\u65b9\u6cd5\u3002\u4f4e\u7ef4\u4e0b\u4f20\u7edf\u65b9\u6cd5\u66f4\u51c6\u786e\u9ad8\u6548\uff0c\u9ad8\u7ef4\u4e0b\u5408\u7406\u51fd\u6570\u7a7a\u95f4\u53ef\u907f\u514d\u7ef4\u5ea6\u707e\u96be\u3002", "summary_en": "The paper argues that deep learning is fundamentally a projection method, not a new paradigm in economic modeling, and advocates selecting appropriate approximation methods based on model dimensionality. Traditional methods outperform neural networks in low dimensions, while suitable function spaces mitigate the curse of dimensionality in high dimensions.", "reason_zh": "\u8be5\u7814\u7a76\u4e3a\u673a\u6784\u6295\u8d44\u8005\u548c\u653f\u7b56\u5236\u5b9a\u8005\u63d0\u4f9b\u4e86\u6e05\u6670\u7684\u6a21\u578b\u9009\u62e9\u4f9d\u636e\uff0c\u6709\u52a9\u4e8e\u5728AI\u4e0e\u4f20\u7edf\u65b9\u6cd5\u878d\u5408\u4e2d\u8bc4\u4f30\u6781\u7aef\u98ce\u9669\u4e0e\u8d44\u672c\u6d41\u52a8\u7684\u5efa\u6a21\u7a33\u5065\u6027\uff0c\u5c24\u5176\u5728\u5e76\u8d2d\u4e0e\u5e02\u573a\u53cd\u9988\u573a\u666f\u4e2d\u5177\u6709\u5b9e\u7528\u4ef7\u503c\u3002", "reason_en": "Offers a clear model selection framework for institutional investors and policymakers, aiding robustness assessment in AI-integrated modeling under extreme risks and capital flows, particularly relevant in mergers, market feedback, and network dynamics."}, {"doi": "10.3386/w35807", "summary_zh": "\u7814\u7a76\u63ed\u793a\u7f51\u7edc\u5747\u8861\u6548\u5e94\u5bfc\u81f4\u65f6\u95f4\u56fa\u5b9a\u6548\u5e94\u65e0\u6cd5\u63a7\u5236\u7f51\u7edc\u68af\u5ea6\uff0c\u4f7f\u6807\u51c6\u9762\u677f\u6a21\u578b\u4ea7\u751f\u8bc6\u522b\u504f\u5dee\uff0c\u8be5\u504f\u5dee\u5728U.S.\u751f\u4ea7\u7f51\u7edc\u4e2d\u53ef\u80fd\u8d85\u8fc7130%\uff0c\u5e76\u63d0\u51fa\u53ef\u89c2\u5bdf\u4e0e\u9690\u85cf\u7f51\u7edc\u7684\u8bca\u65ad\u4e0e\u4fee\u6b63\u65b9\u6cd5\u3002", "summary_en": "The paper reveals that network equilibrium gradients escape control by time fixed effects, causing significant identification bias in standard panel models, with distortions exceeding 130% in the U.S. production network, and proposes diagnostics and remedies for network leakage.", "reason_zh": "\u5bf9\u7406\u89e3\u5730\u7f18\u653f\u6cbb\u4e0b\u7684\u7cfb\u7edf\u6027\u98ce\u9669\u3001\u8d44\u4ea7\u5b9a\u4ef7\u4e2d\u7684\u7f51\u7edc\u4f20\u5bfc\u3001\u673a\u6784\u6295\u8d44\u8005\u51b3\u7b56\u53ca\u5e02\u573a\u53cd\u9988\u673a\u5236\u5177\u6709\u91cd\u8981\u73b0\u5b9e\u610f\u4e49\uff0c\u5c24\u5176\u5728\u5e76\u8d2d\u4e0e\u8d44\u672c\u6d41\u52a8\u4e2d\u907f\u514d\u8bef\u5224\u76f4\u63a5\u6548\u5e94\u81f3\u5173\u91cd\u8981\u3002", "reason_en": "Critical for understanding systemic risk in geoeconomic networks, asset pricing, institutional investor decisions, and market feedback, especially in mergers and capital flows where misattributing network leakage undermines policy and investment judgment."}, {"doi": "10.3386/w35782", "summary_zh": "\u63d0\u51fa\u4e00\u4e2a\u5f00\u6e90\u5de5\u4f5c\u6d41\uff0c\u4f7f\u5927\u8bed\u8a00\u6a21\u578b\uff08LLM\uff09\u80fd\u591f\u590d\u73b0\u3001\u6539\u8fdb\u548c\u6269\u5c55\u5df2\u53d1\u8868\u7684\u7ecf\u6d4e\u5b66\u7814\u7a76\u3002\u57284452\u4e2a\u590d\u5236\u5305\u4e2d\uff0c\u53d1\u73b03460\u7bc7\u5b58\u5728\u8ba1\u7b97\u504f\u5dee\uff0c496\u7bc7\u8ba1\u7b97\u6548\u7387\u63d0\u5347\u8d8510\u500d\uff0c923\u7bc7\u751f\u6210\u4e86\u539f\u7814\u7a76\u672a\u5305\u542b\u4f46\u7b26\u5408\u76ee\u6807\u7684\u5408\u7406\u5ef6\u4f38\u3002", "summary_en": "An open-source workflow enables LLMs to reproduce, improve, and extend published economics research. Across 4,452 replication packages, it identifies discrepancies in 3,460 articles, improves computation time by more than 10x in 496 cases, and generates novel extensions in 923 cases.", "reason_zh": "\u8be5\u7814\u7a76\u6709\u52a9\u4e8e\u673a\u6784\u6295\u8d44\u8005\u8bc6\u522b\u7814\u7a76\u4e2d\u7684\u8ba1\u7b97\u8bef\u5dee\u4e0e\u6f5c\u5728\u504f\u8bef\uff0c\u63d0\u5347\u5bf9\u8d44\u4ea7\u5b9a\u4ef7\u4e0e\u5e76\u8d2d\u51b3\u7b56\u7684\u53ef\u9760\u6027\u5224\u65ad\uff0c\u5bf9\u7f51\u7edc\u7ed3\u6784\u5206\u6790\u548c\u5e02\u573a\u53cd\u9988\u673a\u5236\u5177\u6709\u53c2\u8003\u610f\u4e49\u3002", "reason_en": "The study helps institutional investors detect computational errors and biases in research, enhancing reliability in asset pricing and M&A decisions, with relevance to network analysis and market feedback mechanisms."}, {"doi": "10.3386/w35809", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u81ea1950\u5e74\u4ee5\u6765\u5168\u7403\u751f\u80b2\u7387\u6301\u7eed\u4e0b\u964d\uff0c\u5c24\u5176\u5728\u4f4e\u6536\u5165\u548c\u6559\u80b2\u6c34\u5e73\u8f83\u4f4e\u7fa4\u4f53\u4e2d\uff0c\u8fd9\u4e00\u8d8b\u52bf\u7531\u2018\u73b0\u4ee3\u6027\u2019\u9a71\u52a8\u2014\u2014\u517b\u80b2\u7b2c\u4e09\u4e2a\u5b69\u5b50\u6210\u672c\u4e0a\u5347\uff0c\u65e0\u5b69\u53d8\u5f97\u5ec9\u4ef7\u3002\u5f53\u524d\u8d8b\u52bf\u7531219\u4e2a\u56fd\u5bb6\u7279\u5b9a\u56e0\u7d20\u63a8\u52a8\uff0c\u65e0\u4e00\u8d8b\u7f13\uff0c\u4e14\u65e0\u5df2\u77e5\u673a\u5236\u53ef\u89e3\u91ca\u3002\u8fd9\u5c06\u5bfc\u81f4\u4eba\u53e3\u7ed3\u6784\u6076\u5316\u548c\u957f\u671f\u7ecf\u6d4e\u589e\u957f\u653e\u7f13\u3002", "summary_en": "The study finds global fertility has declined below replacement levels, especially among low-income and less-educated populations, driven by 'modernity'\u2014increased cost of third children and affordability of childlessness. This trend, driven by 219 country-specific factors with no sign of leveling off, will lead to demographic deterioration and prolonged economic slowdown.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u4eba\u53e3\u7ed3\u6784\u53d8\u5316\u5bf9\u5730\u7f18\u653f\u6cbb\u683c\u5c40\u3001\u8d44\u4ea7\u5b9a\u4ef7\u4e0e\u8d44\u672c\u6d41\u52a8\u7684\u6df1\u8fdc\u5f71\u54cd\uff0c\u5c24\u5176\u5728\u6781\u7aef\u98ce\u9669\u548c\u957f\u671f\u5e02\u573a\u53cd\u9988\u4e2d\u5177\u6709\u5173\u952e\u610f\u4e49\uff0c\u5bf9\u673a\u6784\u6295\u8d44\u8005\u548c\u5e76\u8d2d\u51b3\u7b56\u63d0\u4f9b\u524d\u77bb\u6027\u89c6\u89d2\u3002", "reason_en": "It reveals how demographic shifts driven by modernity impact geopolitical dynamics, asset pricing, and capital flows, offering critical foresight for institutional investors and M&A decisions under extreme risk scenarios."}]}, {"date": "2026-09-28", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "preferences": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "\u7f51\u7edc", "\u5e02\u573a\u53cd\u9988", "AI", "\u6781\u7aef\u98ce\u9669", "\u5e76\u8d2d", "\u8d44\u672c\u6d41\u52a8"], "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.3386/w35787", "summary_zh": "\u672c\u6587\u63d0\u51fa\u4e00\u79cd\u57fa\u4e8e\u5e02\u573a\u7ed3\u6784\u5916\u751f\u53d8\u5316\u7684\u7b80\u5316\u65b9\u6cd5\uff0c\u7528\u4e8e\u4f30\u8ba1\u5e76\u8d2d\u5bf9\u4ef7\u683c\u7684\u5f71\u54cd\uff0c\u4ee5JetBlue\u4e0eSpirit\u7684\u5408\u5e76\u4e3a\u4f8b\uff0c\u53d1\u73b0\u8be5\u5408\u5e76\u6bcf\u5e74\u5c06\u9020\u621026\u4ebf\u7f8e\u5143\u7684\u635f\u5931\uff0c\u65b9\u6cd5\u900f\u660e\u4e14\u5047\u8bbe\u8f83\u5c11\uff0c\u4e3a\u673a\u6784\u6295\u8d44\u8005\u548c\u5e02\u573a\u53cd\u9988\u63d0\u4f9b\u4e86\u53ef\u64cd\u4f5c\u7684\u5206\u6790\u5de5\u5177\u3002", "summary_en": "This paper proposes a simpler, more transparent method using quasi-exogenous variation in market structure to estimate merger impacts, applying it to the JetBlue\u2013Spirit merger and finding it would cause $2.6 billion in annual harm, offering a less assumption-heavy alternative to structural models.", "reason_zh": "\u8be5\u7814\u7a76\u901a\u8fc7\u771f\u5b9e\u5e02\u573a\u4e8b\u4ef6\u8bc6\u522b\u5e76\u8d2d\u5f71\u54cd\uff0c\u5bf9\u8d44\u4ea7\u5b9a\u4ef7\u3001\u5e76\u8d2d\u51b3\u7b56\u548c\u6781\u7aef\u98ce\u9669\u8bc4\u4f30\u5177\u6709\u76f4\u63a5\u4ef7\u503c\uff0c\u5c24\u5176\u6709\u52a9\u4e8e\u673a\u6784\u6295\u8d44\u8005\u8bc4\u4f30\u8d44\u672c\u6d41\u52a8\u4e0e\u5e02\u573a\u53cd\u9988\u4e2d\u7684\u7ed3\u6784\u6027\u53d8\u5316\u3002", "reason_en": "The study provides a direct method for assessing merger impacts in differentiated markets, with relevance to asset pricing, merger decisions, and extreme risk evaluation, particularly for institutional investors analyzing capital flows and market feedback."}, {"doi": "10.1093/restud/rdag105", "summary_zh": "\u672c\u6587\u6784\u5efa\u4e86\u878d\u5408\u673a\u5668\u5b66\u4e60\u4e0e\u52a8\u6001\u4f18\u5316\u7684\u6846\u67b6\uff0c\u89e3\u51b3\u5305\u542b\u6301\u4e45\u79c1\u4eba\u4fe1\u606f\u7684\u52a8\u6001\u6fc0\u52b1\u95ee\u9898\uff0c\u901a\u8fc7\u9ad8\u7ef4\u975e\u7ebf\u6027\u51fd\u6570\u8fd1\u4f3c\u5b9e\u73b0\u6570\u503c\u6c42\u89e3\uff0c\u63ed\u793a\u4e86\u8fc7\u5ea6\u62a5\u544a\u5982\u4f55\u6539\u53d8\u957f\u671f\u5408\u540c\u7ed3\u6784\u5e76\u5e73\u6ed1\u6548\u7528\u3002", "summary_en": "We present a scalable framework combining machine learning and dynamic optimization to solve dynamic adverse selection models with persistent private information, revealing how overreporting alters long-run contract structures and smooths utility over time.", "reason_zh": "\u8be5\u7814\u7a76\u5bf9\u7406\u89e3\u4fe1\u606f\u4e0d\u5bf9\u79f0\u4e0b\u7684\u6fc0\u52b1\u8bbe\u8ba1\u3001\u8d44\u4ea7\u5b9a\u4ef7\u4e0e\u5e02\u573a\u53cd\u9988\u673a\u5236\u5177\u6709\u91cd\u8981\u4ef7\u503c\uff0c\u5c24\u5176\u5728\u6587\u672c\u5206\u6790\u3001\u7f51\u7edc\u7ed3\u6784\u4e0e\u6781\u7aef\u98ce\u9669\u60c5\u5883\u4e2d\u63d0\u4f9b\u53ef\u64cd\u4f5c\u7684\u5efa\u6a21\u5de5\u5177\uff0c\u5951\u5408\u673a\u6784\u6295\u8d44\u8005\u4e0e\u5e76\u8d2d\u51b3\u7b56\u4e2d\u7684\u52a8\u6001\u98ce\u9669\u8bc4\u4f30\u9700\u6c42\u3002", "reason_en": "The framework offers actionable modeling for information asymmetry in dynamic settings, relevant to asset pricing, market feedback, network behavior, and extreme risk assessment in investment and merger decisions driven by AI and data."}, {"doi": "10.1287/mnsc.2024.06050", "summary_zh": "\u8de8\u793e\u533a\u793e\u4f1a\u7f51\u7edc\u663e\u8457\u63d0\u5347\u5f31\u52bf\u5730\u533a\u5728\u7ebf\u8d37\u6b3e\u4f9b\u9700\uff0c\u4e14\u4e0d\u589e\u52a0\u8fdd\u7ea6\u7387\uff0c\u901a\u8fc7\u4f20\u9012\u7a00\u7f3a\u4fe1\u606f\u548c\u63d0\u5347\u5bf9\u66ff\u4ee3\u501f\u8d37\u5e73\u53f0\u7684\u8ba4\u77e5\uff0c\u7f13\u89e3\u4e86\u533a\u57df\u95f4\u4fe1\u606f\u4e0d\u5bf9\u79f0\u3002", "summary_en": "Intercommunity social networks increase loan demand and supply in disadvantaged areas without raising delinquency, by transmitting hard-to-obtain information and raising awareness of alternative lending platforms.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u793e\u4f1a\u7f51\u7edc\u5982\u4f55\u901a\u8fc7\u4fe1\u606f\u4f20\u5bfc\u6539\u5584\u8fb9\u7f18\u793e\u533a\u7684\u91d1\u878d\u53ef\u53ca\u6027\uff0c\u5bf9\u7406\u89e3\u8d44\u672c\u6d41\u52a8\u3001\u5e02\u573a\u53cd\u9988\u4e0e\u7f51\u7edc\u7ed3\u6784\u5728\u8d44\u4ea7\u5b9a\u4ef7\u4e2d\u7684\u4f5c\u7528\u5177\u6709\u73b0\u5b9e\u610f\u4e49\uff0c\u5c24\u5176\u5bf9\u673a\u6784\u6295\u8d44\u8005\u548c\u6587\u672c\u5206\u6790\u4e2d\u7684\u7f51\u7edc\u6548\u5e94\u5efa\u6a21\u6709\u53c2\u8003\u4ef7\u503c\u3002", "reason_en": "The study demonstrates how social networks mitigate information asymmetry in underserved regions, offering insights into capital flows, market feedback, and network effects in asset pricing\u2014highly relevant to institutional investors, network analysis, and risk assessment in mergers and extreme risk events."}, {"doi": "10.3386/w35760", "summary_zh": "\u901a\u8fc7\u5206\u6790\u4f01\u4e1a\u62ab\u9732\u8bed\u8a00\uff0c\u53d1\u73b0\u5458\u5de5\u798f\u7949\u5bfc\u5411\u5f3a\u7684\u4f01\u4e1a\u5438\u5f15\u5458\u5de5\u540e\uff0c\u5176\u75c5\u5047\u7387\u4e0a\u5347\uff0c\u4f46\u5c31\u533b\u884c\u4e3a\u4e0d\u53d8\uff0c\u8868\u660e\u884c\u4e3a\u6539\u53d8\u800c\u975e\u5065\u5eb7\u6076\u5316\uff0c\u63ed\u793a\u4e86\u6587\u672c\u8bed\u8a00\u5bf9\u5458\u5de5\u884c\u4e3a\u7684\u6df1\u5c42\u5f71\u54cd\u3002", "summary_en": "Workers moving to firms with higher well-being salience show increased sickness absence without changes in healthcare use, suggesting behavioral shifts rather than health deterioration.", "reason_zh": "\u8be5\u7814\u7a76\u5c06\u6587\u672c\u5206\u6790\u4e0e\u5458\u5de5\u5065\u5eb7\u884c\u4e3a\u5173\u8054\uff0c\u4e3a\u673a\u6784\u6295\u8d44\u8005\u3001\u5e76\u8d2d\u51b3\u7b56\u548c\u6781\u7aef\u98ce\u9669\u8bc4\u4f30\u63d0\u4f9b\u4e86\u57fa\u4e8e\u8bed\u8a00\u7684\u53ef\u64cd\u4f5c\u6d1e\u5bdf\uff0c\u5c24\u5176\u5728\u5730\u7f18\u653f\u6cbb\u52a8\u8361\u6216\u8d44\u672c\u6d41\u52a8\u80cc\u666f\u4e0b\uff0c\u53cd\u6620\u4f01\u4e1a\u6cbb\u7406\u4e0e\u5458\u5de5\u7a33\u5b9a\u6027\u3002", "reason_en": "The study links language in corporate disclosures to worker behavior, offering actionable insights for institutional investors, M&A decisions, and extreme risk assessment, especially in contexts of geopolitical shifts and capital mobility."}, {"doi": "10.3386/w35762", "summary_zh": "\u5c3d\u7ba1\u79d1\u6280\u5de8\u5934\u9891\u7e41\u6536\u8d2d\u521d\u521b\u4f01\u4e1a\uff0c\u521b\u65b0\u5728\u6536\u8d2d\u524d\u53ca\u540e\u7eed\u4ecd\u6301\u7eed\u4e0a\u5347\uff0c\u7559\u4efb\u5458\u5de5\u4e13\u5229\u4ea7\u51fa\u663e\u8457\u589e\u52a0\uff0c\u8868\u660e\u6536\u8d2d\u4e0e\u521b\u65b0\u6b63\u5411\u5173\u8054\uff0c\u5c24\u5176\u5728\u6280\u672f\u5e03\u5c40\u91cd\u53e0\u9886\u57df\u66f4\u660e\u663e\uff0c\u5bf9\u5e76\u8d2d\u51b3\u7b56\u3001\u8d44\u4ea7\u5b9a\u4ef7\u4e0e\u7f51\u7edc\u7ed3\u6784\u6f14\u5316\u5177\u6709\u53c2\u8003\u4ef7\u503c\u3002", "summary_en": "Acquisitions by tech giants are associated with sustained innovation growth, and retained inventors produce more patents, indicating a positive link between acquisitions and innovation\u2014particularly in technology areas with existing acquirer presence.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u5e76\u8d2d\u4e0e\u521b\u65b0\u4e4b\u95f4\u7684\u52a8\u6001\u5173\u7cfb\uff0c\u5bf9\u7406\u89e3\u5730\u7f18\u653f\u6cbb\u4e0b\u6280\u672f\u7ade\u4e89\u3001\u673a\u6784\u6295\u8d44\u8005\u884c\u4e3a\u3001\u5e02\u573a\u53cd\u9988\u673a\u5236\u53ca\u6781\u7aef\u98ce\u9669\u4e0b\u7684\u8d44\u672c\u6d41\u52a8\u5177\u6709\u73b0\u5b9e\u610f\u4e49\u3002", "reason_en": "Provides insight into how digital acquisitions shape innovation in competitive tech ecosystems, relevant to market feedback, AI-driven network dynamics, capital flows, and extreme risk in M&A and asset pricing."}]}, {"date": "2026-09-27", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.3386/w35785", "summary_zh": "\u672c\u6587\u7814\u7a76\u4e86\u4e2d\u7f8e\u8d38\u6613\u6218\u5bf9\u5168\u7403\u8d38\u6613\u6a21\u5f0f\u7684\u91cd\u5851\uff0c\u53d1\u73b0\u4e2d\u56fd\u51fa\u53e3\u6b63\u4ece\u7f8e\u56fd\u5e02\u573a\u8f6c\u5411\u7b2c\u4e09\u56fd\u3002\u4f5c\u8005\u63d0\u51fa\u4e00\u79cd\u7406\u8bba\u6846\u67b6\uff0c\u5c06\u56fd\u5bb6\u66b4\u9732\u5206\u4e3a\u51fa\u53e3\u7ade\u4e89\u3001\u8fdb\u53e3\u7ade\u4e89\u3001\u6d88\u8d39\u8005\u6536\u76ca\u548c\u6765\u6e90\u6536\u76ca\u56db\u7c7b\uff0c\u5e76\u6784\u5efa\u4e86\u8003\u8651\u4ea7\u54c1\u51b2\u51fb\u3001\u5e02\u573a\u6e17\u900f\u4e0e\u66ff\u4ee3\u5f39\u6027\u7684\u6307\u6570\uff0c\u514b\u670d\u4e86\u4f20\u7edf\u8d38\u6613\u7bee\u5b50\u76f8\u4f3c\u6027\u5ea6\u91cf\u7684\u5bf9\u79f0\u6027\u4e0e\u4fe1\u606f\u7f3a\u5931\u95ee\u9898\u3002", "summary_en": "This paper studies how the U.S.-China trade war has reshaped global trade patterns, creating significant spillovers to third countries. It introduces a theoretical taxonomy separating four exposure channels\u2014export competition, import competition, consumer gains, and sourcing gains\u2014and constructs indices that account for product-specific shocks, market penetration, and substitution elasticities, overcoming limitations of conventional trade-basket similarity measures.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u5730\u7f18\u653f\u6cbb\u51b2\u7a81\u4e0b\u5168\u7403\u4f9b\u5e94\u94fe\u7684\u975e\u5bf9\u79f0\u91cd\u6784\uff0c\u4e3a\u7406\u89e3\u8d38\u6613\u6218\u5bf9\u7b2c\u4e09\u56fd\u7684\u7ed3\u6784\u6027\u5f71\u54cd\u63d0\u4f9b\u7cbe\u51c6\u5de5\u5177\uff0c\u5bf9\u673a\u6784\u6295\u8d44\u8005\u548c\u4f9b\u5e94\u94fe\u51b3\u7b56\u5177\u6709\u91cd\u8981\u53c2\u8003\u4ef7\u503c\u3002", "reason_en": "The study reveals asymmetric reconfiguration of global supply chains under geopolitical tensions, offering precise tools to assess cross-country exposure, making it highly relevant to institutional investors and supply chain strategists."}, {"doi": "10.1093/rfs/hhag084", "summary_zh": "\u672c\u6587\u63d0\u51fa\u4e00\u79cd\u901a\u7528\u975e\u7ebf\u6027\u534f\u65b9\u5dee\u6536\u7f29\u65b9\u6cd5\uff08UPSA\uff09\uff0c\u901a\u8fc7\u91cd\u65b0\u52a0\u6743\u4e3b\u6210\u5206\u4f18\u5316\u6295\u8d44\u7ec4\u5408\u9884\u671f\u51fa\u6837\u672c\u8868\u73b0\uff0c\u663e\u8457\u4f18\u4e8e\u73b0\u6709\u6536\u7f29\u65b9\u6cd5\u3002\u5728\u5927\u91cf\u5f02\u5e38\u56e0\u5b50\u7684\u5b9e\u8bc1\u4e2d\u8868\u73b0\u7a33\u5065\uff0c\u4e3a\u8d44\u4ea7\u5b9a\u4ef7\u548c\u6295\u8d44\u7ec4\u5408\u6784\u5efa\u63d0\u4f9b\u9ad8\u6548\u5b9e\u7528\u5de5\u5177\u3002", "summary_en": "The paper introduces a universal portfolio shrinkage method (UPSA) that reweights principal components to optimize out-of-sample portfolio performance, outperforming existing shrinkage methods in empirical applications using large cross-sections of anomaly factors.", "reason_zh": "\u8be5\u65b9\u6cd5\u5728\u8d44\u4ea7\u5b9a\u4ef7\u548c\u6295\u8d44\u7ec4\u5408\u7ba1\u7406\u4e2d\u5177\u6709\u5b9e\u7528\u4ef7\u503c\uff0c\u6709\u6548\u63d0\u5347\u6a21\u578b\u6cdb\u5316\u80fd\u529b\uff0c\u5bf9\u673a\u6784\u6295\u8d44\u8005\u4f18\u5316\u98ce\u9669\u8c03\u6574\u6536\u76ca\u5177\u6709\u91cd\u8981\u610f\u4e49\u3002", "reason_en": "This method enhances out-of-sample performance and generalization in portfolio construction, offering institutional investors a practical tool for improving risk-adjusted returns."}, {"doi": "10.1287/mnsc.2025.02458", "summary_zh": "\u672c\u6587\u901a\u8fc7\u5927\u89c4\u6a21\u5b9e\u5730\u5b9e\u9a8c\u9a8c\u8bc1\u751f\u6210\u5f0f\u641c\u7d22\u663e\u8457\u63d0\u5347\u6d88\u8d39\u8005\u8d2d\u4e70\u7387\uff0c\u4fc3\u8fdb\u66f4\u6709\u6548\u548c\u591a\u6837\u5316\u7684\u5173\u952e\u8bcd\u67e5\u8be2\uff0c\u51cf\u5c11\u6d4f\u89c8\u70b9\u51fb\uff0c\u5c06\u6ce8\u610f\u529b\u805a\u7126\u4e8e\u76f8\u5173\u54c1\u7c7b\uff0c\u63ed\u793aAI\u751f\u6210\u5185\u5bb9\u5982\u4f55\u5e2e\u52a9\u7528\u6237\u8868\u8fbe\u9700\u6c42\u5e76\u5f15\u5bfc\u51b3\u7b56\u3002", "summary_en": "A large-scale field experiment shows generative search significantly increases consumer purchases, enhances keyword query effectiveness and diversity, reduces exploratory browsing, and focuses attention on relevant categories, revealing how AI-generated responses help users express needs and guide decisions.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u751f\u6210\u5f0fAI\u5728\u641c\u7d22\u884c\u4e3a\u4e2d\u7684\u5b9e\u9645\u5f71\u54cd\uff0c\u6709\u52a9\u4e8e\u7406\u89e3\u5e73\u53f0\u7528\u6237\u51b3\u7b56\u8def\u5f84\uff0c\u5bf9\u8bc4\u4f30\u6570\u5b57\u5e73\u53f0\u4fe1\u606f\u83b7\u53d6\u6548\u7387\u5177\u6709\u53c2\u8003\u4ef7\u503c\u3002", "reason_en": "The findings offer insight into how generative AI influences user search behavior, providing relevance for evaluating information efficiency in digital platforms."}, {"doi": "10.3386/w35767", "summary_zh": "\u672c\u6587\u63ed\u793a\u4e2d\u56fd\u5bf9\u65b0\u5174\u7ecf\u6d4e\u4f53\u7684\u975e\u8fdd\u7ea6\u4f46\u6613\u88ab\u8981\u6c42\u7eed\u8d37\u8d37\u6b3e\u5f62\u6210\u2018\u9690\u6027\u98ce\u9669\u2019\uff0c\u901a\u8fc7\u66b4\u9732\u5e02\u573a\u503a\u52a1\u4e8e\u7a00\u91ca\u98ce\u9669\uff0c\u7ea6\u675f\u501f\u6b3e\u56fd\u5728\u56fd\u9645\u5e02\u573a\u7684\u501f\u8d37\u884c\u4e3a\uff0c\u4ea7\u751f\u2018\u7eaa\u5f8b\u6548\u5e94\u2019\u3002\u6a21\u578b\u663e\u793a\uff0c\u6b64\u7c7b\u8d37\u6b3e\u4fc3\u4f7f\u503a\u52a1\u53bb\u6760\u6746\uff0c\u6539\u53d8\u5168\u7403\u4e3b\u6743\u503a\u52a1\u7ed3\u6784\uff0c\u5177\u6709\u5730\u7f18\u653f\u6cbb\u4e0e\u91d1\u878d\u7a33\u5b9a\u610f\u4e49\u3002", "summary_en": "This paper shows that China's non-defaultable, rollover-prone loans create implicit risk, exposing market debt to dilution and disciplining borrowing in emerging markets. The model demonstrates that such loans lead to deleveraging, reshaping global sovereign debt dynamics under shifting geopolitical alignments.", "reason_zh": "\u8be5\u7814\u7a76\u6709\u52a9\u4e8e\u673a\u6784\u6295\u8d44\u8005\u7406\u89e3\u4e3b\u6743\u503a\u52a1\u5728\u5730\u7f18\u653f\u6cbb\u53d8\u5316\u4e0b\u7684\u8106\u5f31\u6027\uff0c\u4e3a\u8bc4\u4f30\u4e2d\u56fd\u8d37\u6b3e\u7ed3\u6784\u5bf9\u5168\u7403\u503a\u52a1\u4f53\u7cfb\u7684\u6f5c\u5728\u5f71\u54cd\u63d0\u4f9b\u5173\u952e\u6d1e\u89c1\u3002", "reason_en": "The findings help institutional investors assess how China's lending structure affects sovereign debt vulnerability under geopolitical shifts, offering key insights into global debt dynamics."}, {"doi": "10.3386/w35775", "summary_zh": "\u672c\u6587\u53d1\u73b0\uff0c2017\u5e74\u7a0e\u6cd5\u4e2d\u5bf9\u5229\u606f\u62b5\u6263\u7684\u9650\u5236\u663e\u8457\u6291\u5236\u4e86\u4f01\u4e1a\u521b\u65b0\uff0c\u5c24\u5176\u5f71\u54cd\u4f9d\u8d56\u957f\u671f\u503a\u52a1\u878d\u8d44\u7684\u2018\u63a0\u593a\u6027\u4e13\u5229\u2019\u3002\u7814\u7a76\u901a\u8fc7\u591a\u89d2\u5ea6\u8bc6\u522b\u7b56\u7565\u8bc1\u5b9e\uff0c\u8be5\u653f\u7b56\u524a\u5f31\u4e86\u4f01\u4e1a\u901a\u8fc7\u503a\u52a1\u878d\u8d44\u652f\u6301\u521b\u65b0\u7684\u80fd\u529b\uff0c\u63ed\u793a\u4e86\u7a0e\u6536\u653f\u7b56\u4e0e\u4f01\u4e1a\u6280\u672f\u521b\u65b0\u4e4b\u95f4\u7684\u65b0\u4f20\u5bfc\u8def\u5f84\u3002", "summary_en": "The paper finds that interest deductibility limitations under the 2017 TCJA significantly reduce corporate innovation, especially in exploitative patents supported by long-term debt, revealing a novel channel linking taxation to innovation via the debt tax shield.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86\u7a0e\u6536\u653f\u7b56\u5982\u4f55\u901a\u8fc7\u503a\u52a1\u7a0e\u76fe\u5f71\u54cd\u4f01\u4e1a\u521b\u65b0\uff0c\u5bf9\u7406\u89e3\u653f\u7b56\u5bf9\u8d44\u672c\u7ed3\u6784\u548c\u6280\u672f\u521b\u65b0\u7684\u95f4\u63a5\u5f71\u54cd\u5177\u6709\u91cd\u8981\u4ef7\u503c\uff0c\u5c24\u5176\u5bf9\u673a\u6784\u6295\u8d44\u8005\u8bc4\u4f30\u653f\u7b56\u5bf9\u8d44\u4ea7\u5b9a\u4ef7\u548c\u516c\u53f8\u7ee9\u6548\u7684\u5f71\u54cd\u5177\u6709\u53c2\u8003\u610f\u4e49\u3002", "reason_en": "This paper reveals how tax policy affects corporate innovation through the debt tax shield, offering insights into policy-induced changes in capital structure and firm-level performance\u2014highly relevant for institutional investors evaluating policy impacts on asset valuation and innovation outcomes."}]}, {"date": "2026-09-26", "kind": "QWEN DAILY BRIEF", "model": "journal-qwen4b", "title_zh": "\u4eca\u65e5\u7814\u7a76\u7cbe\u9009", "title_en": "Today's research reading list", "note_zh": "\u603b\u7ed3\u4e0e\u63a8\u8350\u7406\u7531\u4ec5\u4f9d\u636e\u516c\u5f00\u5143\u6570\u636e\uff0c\u4e0d\u4ee3\u8868\u5bf9\u5168\u6587\u8d28\u91cf\u7684\u8bc4\u5ba1\u3002", "note_en": "Summaries and subjective reading reasons are based on metadata, not full-text review.", "picks": [{"doi": "10.1287/mnsc.2025.03155", "summary_zh": "\u672c\u6587\u63d0\u51fa\u4e00\u79cd\u57fa\u4e8e\u7ebf\u6027\u89c4\u5212\u7684\u7cbe\u786e\u6c42\u89e3\u65b9\u6cd5\uff0c\u7528\u4e8e\u4f18\u5316\u590d\u6742\u4f9b\u5e94\u94fe\u7f51\u7edc\u4e2d\u7684\u5b89\u5168\u5e93\u5b58\u914d\u7f6e\u3002\u65b9\u6cd5\u5728\u8282\u70b9\u6570n\u4e0a\u5177\u6709\u591a\u9879\u5f0f\u590d\u6742\u5ea6\uff0c\u5bf9\u6700\u5927\u8865\u8d27\u65f6\u95f4M\u7684\u4f4d\u5927\u5c0f\u4e3a\u4f2a\u591a\u9879\u5f0f\uff0c\u4e14\u5728\u56fa\u5b9aM\u4e0b\u968f\u6811\u5bbd\uff08treewidth\uff09\u5448\u6307\u6570\u589e\u957f\uff0c\u800c\u6811\u5bbd\u53ef\u80fd\u8fdc\u5c0f\u4e8en\u3002\u76f8\u6bd4\u73b0\u6709\u65b9\u6cd5\u5728n\u4e0a\u5448\u6307\u6570\u589e\u957f\u7684\u590d\u6742\u5ea6\uff0c\u8be5\u65b9\u6cd5\u5728\u7ed3\u6784\u590d\u6742\u6027\u4e0a\u66f4\u9ad8\u6548\u3002\u7814\u7a76\u901a\u8fc7\u7406\u8bba\u8bc1\u660e\u548c\u5b9e\u8bc1\u9a8c\u8bc1\uff0c\u4e3a\u5b89\u5168\u5e93\u5b58\u4f18\u5316\u63d0\u4f9b\u4e86\u65b0\u7684\u7406\u8bba\u57fa\u7840\u548c\u5b9e\u7528\u5de5\u5177\u3002", "summary_en": "This paper proposes an LP-based exact method for safety stock optimization in complex supply chain networks. The algorithm scales polynomially in network size n and pseudo-polynomially in the bit size of maximum replenishment time M, and (for fixed M) exponentially in treewidth, which can be much smaller than n. This contrasts with existing methods that scale exponentially in n. The method provides new theoretical foundations and practical tools, validated by real-world benchmarks.", "reason_zh": "\u9002\u5408\u5173\u6ce8\u4f9b\u5e94\u94fe\u7f51\u7edc\u4e0e\u5e93\u5b58\u914d\u7f6e\u7684\u8bfb\u8005\u3002\u53ef\u91cd\u70b9\u8003\u5bdf\u6811\u5bbd\u5982\u4f55\u51b3\u5b9a\u6c42\u89e3\u96be\u5ea6\uff0c\u4ee5\u53ca\u7ebf\u6027\u89c4\u5212\u677e\u5f1b\u5728\u771f\u5b9e\u7f51\u7edc\u4e0a\u7684\u6548\u679c\u3002", "reason_en": "Relevant to supply-chain networks and inventory allocation. Examine how treewidth governs computational difficulty and how LP relaxations perform on real networks."}, {"doi": "10.1093/rfs/hhag080", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u4e3b\u52a8\u578b\u548c\u6307\u6570\u578b\u57fa\u91d1\u7684\u6d41\u52a8\u5747\u663e\u8457\u53d7\u8868\u73b0\u5f71\u54cd\uff0c\u5c24\u5176ETF\u8868\u73b0\u51fa\u6700\u5f3a\u7684\u654f\u611f\u6027\uff0c\u4e14\u8fd9\u79cd\u73b0\u8c61\u65e0\u6cd5\u7531\u57fa\u51c6\u8bbe\u8ba1\u6216\u4ea4\u6613\u673a\u5236\u89e3\u91ca\u3002\u673a\u6784\u6295\u8d44\u8005\u7684\u7fa4\u4f53\u884c\u4e3a\u548c\u6295\u8d44\u7ba1\u7406\u5916\u5305\u52a0\u5267\u4e86\u8fd9\u79cd\u8868\u73b0\u654f\u611f\u6027\u3002", "summary_en": "The study finds strong performance sensitivity in mutual funds and ETFs, especially in ETFs, which cannot be explained by benchmark design or trading mechanisms. Institutional herding and portfolio management outsourcing amplify this sensitivity.", "reason_zh": "\u8be5\u7814\u7a76\u63ed\u793a\u4e86ETF\u5e02\u573a\u4e2d\u7531\u673a\u6784\u884c\u4e3a\u9a71\u52a8\u7684\u6d41\u52a8\u654f\u611f\u6027\uff0c\u53cd\u6620\u4e86\u5e02\u573a\u5fae\u89c2\u7ed3\u6784\u4e2d\u7684\u7cfb\u7edf\u6027\u73b0\u8c61\u3002", "reason_en": "The paper reveals performance-sensitive flows in ETFs driven by institutional behavior, reflecting systematic dynamics in market microstructure."}, {"doi": "10.1287/mnsc.2024.07615", "summary_zh": "\u5229\u7528H-1B\u7b7e\u8bc1\u62bd\u7b7e\u6570\u636e\u53d1\u73b0\uff0c\u83b7\u5f97\u66f4\u591a\u7b7e\u8bc1\u7684\u5bf9\u51b2\u57fa\u91d1\u5728alpha\u3001\u590f\u666e\u6bd4\u7387\u548c\u4fe1\u606f\u6bd4\u7387\u4e0a\u8868\u73b0\u66f4\u4f18\uff0c\u8fd9\u4e00\u4f18\u52bf\u5f52\u56e0\u4e8e\u9ad8\u5b66\u5386\u3001\u9ad8\u6280\u80fd\u7684\u79fb\u6c11\u5458\u5de5\uff0c\u5c24\u5176\u6765\u81ea\u957f\u671f\u7b49\u5f85\u6c38\u4e45\u5c45\u7559\u56fd\u5bb6\u7684\u79fb\u6c11\u8d21\u732e\u663e\u8457\uff0c\u8868\u660e\u79fb\u6c11\u52b3\u52a8\u529b\u5bf9\u57fa\u91d1\u7ee9\u6548\u5177\u6709\u79ef\u6781\u5f71\u54cd\u3002", "summary_en": "Using H-1B visa lottery data, funds securing more visas show higher alpha, Sharpe ratio, and information ratio, attributed to skilled, highly educated immigrant workers, especially those from countries with long residency wait times.", "reason_zh": "\u7814\u7a76\u901a\u8fc7\u5b9e\u8bc1\u63ed\u793a\u4e86\u79fb\u6c11\u52b3\u52a8\u529b\u5bf9\u91d1\u878d\u7ee9\u6548\u7684\u79ef\u6781\u5f71\u54cd\uff0c\u53cd\u6620\u4e86\u52b3\u52a8\u529b\u5e02\u573a\u6469\u64e6\u4e0b\u4eba\u624d\u4ef7\u503c\u7684\u4f53\u73b0\uff0c\u4f46\u672a\u5efa\u7acb\u56e0\u679c\u5173\u7cfb\u3002", "reason_en": "The study provides empirical evidence of skilled immigrants' positive impact on fund performance under labor market frictions, without establishing causality."}, {"doi": "10.3386/w35781", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u91d1\u878d\u98ce\u9669\u6ea2\u4ef7\u4e0a\u5347\u4f1a\u524a\u5f31\u4f01\u4e1a\u5bf9\u51b2\u51fb\u7684\u4fdd\u9669\u80fd\u529b\uff0c\u5bfc\u81f4\u4f4e\u85aa\u5458\u5de5\u5728\u7ecf\u6d4e\u4e0b\u884c\u65f6\u6536\u5165\u98ce\u9669\u4e0a\u5347\uff0c\u5c24\u5176\u5728\u63a5\u8fd1\u79bb\u804c\u8fb9\u7f18\u7684\u7fa4\u4f53\u4e2d\u66f4\u4e3a\u660e\u663e\uff0c\u6a21\u578b\u89e3\u91ca\u4e86\u52b3\u52a8\u6536\u5165\u98ce\u9669\u7684\u65f6\u5e8f\u4e0e\u6a2a\u622a\u9762\u7279\u5f81\uff0c\u5e76\u8868\u660e\u5b58\u5728\u663e\u8457\u7684\u798f\u5229\u635f\u5931\u3001\u8f83\u9ad8\u7684\u79c1\u4eba\u8d34\u73b0\u7387\u53ca\u5bf9\u5468\u671f\u6027\u8f6c\u79fb\u652f\u4ed8\u7684\u6f5c\u5728\u6536\u76ca\u3002", "summary_en": "The paper finds that rising financial risk premia weaken firm insurance against idiosyncratic shocks, increasing labor income risk\u2014especially for lower-paid workers near the separation margin\u2014and implies substantial welfare costs, high private discount rates, and large gains from recession-contingent transfers.", "reason_zh": "\u8be5\u7814\u7a76\u57fa\u4e8e\u52a8\u6001\u641c\u5bfb\u6a21\u578b\uff0c\u63ed\u793a\u4e86\u91d1\u878d\u6761\u4ef6\u5982\u4f55\u901a\u8fc7\u4f01\u4e1a\u4fdd\u9669\u673a\u5236\u5f71\u54cd\u52b3\u52a8\u6536\u5165\u98ce\u9669\uff0c\u89e3\u91ca\u4e86\u6536\u5165\u98ce\u9669\u7684\u591a\u7ef4\u7279\u5f81\uff0c\u5177\u6709\u7406\u8bba\u548c\u653f\u7b56\u53c2\u8003\u4ef7\u503c\u3002", "reason_en": "The paper uses a dynamic search model to show how financial conditions affect firm insurance and labor income risk, explaining key time-series and cross-sectional features of earnings risk with implications for welfare and human capital valuation."}, {"doi": "10.1287/mnsc.2024.07171", "summary_zh": "\u7814\u7a76\u53d1\u73b0\uff0c\u6b27\u76df\u78b3\u8fb9\u5883\u8c03\u8282\u673a\u5236\uff08CBAM\uff09\u8986\u76d6\u4ea7\u54c1\u5bf9\u975e\u6b27\u76df\u4f9b\u5e94\u94fe\u7684\u6b27\u76df\u4e70\u5bb6\u4ea7\u751f\u663e\u8457\u8d1f\u5411\u5e02\u573a\u53cd\u5e94\uff0c\u8868\u660e\u5e02\u573a\u9884\u671f\u78b3\u5173\u7a0e\u5c06\u589e\u52a0\u8fdb\u53e3\u6210\u672c\uff0c\u5bf9\u6b27\u76df\u4f01\u4e1a\u8d22\u52a1\u8868\u73b0\u6784\u6210\u538b\u529b\u3002", "summary_en": "EU purchasers of CBAM-covered products experience significantly lower returns than non-European producers, especially with non-EU supply chains, indicating that equity markets expect cross-border carbon pricing to increase import costs for EU firms.", "reason_zh": "\u8be5\u7814\u7a76\u901a\u8fc7\u80a1\u7968\u4ef7\u683c\u53cd\u5e94\u63ed\u793a\u4e86\u78b3\u5173\u7a0e\u5bf9\u5e02\u573a\u9884\u671f\u7684\u5f71\u54cd\uff0c\u4e3a\u7406\u89e3\u8d38\u6613\u653f\u7b56\u4e0e\u4f01\u4e1a\u8d22\u52a1\u8868\u73b0\u4e4b\u95f4\u7684\u5173\u7cfb\u63d0\u4f9b\u4e86\u5b9e\u8bc1\u652f\u6301\u3002", "reason_en": "The study reveals market expectations of increased import costs due to carbon border taxes, providing empirical insight into the relationship between trade policy and firm financial performance."}], "quality_note": "Drafted and source-checked by the same local Qwen model; not independently reviewed."}], "topics": ["\u5730\u7f18\u653f\u6cbb", "\u8d44\u4ea7\u5b9a\u4ef7", "\u673a\u6784\u6295\u8d44\u8005", "\u6587\u672c\u5206\u6790", "\u7f51\u7edc", "\u5e02\u573a\u53cd\u9988", "AI", "\u6781\u7aef\u98ce\u9669", "\u5e76\u8d2d", "\u8d44\u672c\u6d41\u52a8", "\u5176\u4ed6"]};
